	[153] = {
		id = 153,
		skillName_vn = 'Bão lửa',
		skillName_en = 'Firestorm',
		skillName_th = 'พายุไฟ',
		skillName_in = 'Badai Api',
		skillName_ph = 'Bagyong Apoy',
		skillName_ma = 'Badai Api',
		skillName = 'Firestorm',
		describe_vn = 'Rồng phun lửa siêu cấp Y nhảy lên không trung, sau đó bay nhanh phóng ra bão lửa tấn công các đơn vị hàng dọc của đối phương, gây ra #C0x3D8A99#290% Sát Thương Phép Thuật #C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, thêm 2 lớp [Bỏng] kéo dài 2 lượt cho một hàng kẻ thù; và thêm 15% [Dễ bị tổn thương hệ lửa] 2 lượt cho các đơn vị đang bị Bỏng (Dễ bị tổn thương hệ lửa: hiệu ứng tiêu cực, nhận sát thương từ kỹ năng hệ lửa và sát thương Bỏng tăng lên)',
		describe_en = 'Super-level Y Fire-breathing Dragon leaps into the air, then quickly flies forward to unleash a firestorm attack on the enemy\'s vertical units, dealing #C0x3D8A99#290% Magic Damage #C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# Magic Damage #C0x5B545B#, applying 2 layers of [Burn] lasting 2 turns to one row of enemies; and adding 15% [Fire Vulnerability] for 2 turns to units that are Burned (Fire Vulnerability: negative effect, increases damage taken from fire attribute skills and Burn damage).',
		describe_th = 'มังกรพ่นไฟระดับซูเปอร์ Y กระโดดขึ้นสู่ท้องฟ้า จากนั้นบินเร็วปล่อยพายุไฟโจมตีหน่วยในแถวแนวตั้งของศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#290% #C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# เพิ่มเติม พร้อมเพิ่ม [ไฟไหม้] 2 ชั้น เป็นเวลานาน 2 เทิร์น ให้กับหนึ่งแถวของศัตรู และเพิ่ม [ช่องโหว่ไฟ] 15% เป็นเวลา 2 เทิร์น ให้กับหน่วยที่ถูกไฟไหม้ (ช่องโหว่ไฟ: ผลลบที่ทำให้ได้รับความเสียหายจากสกิลธาตุไฟและความเสียหายจากไฟไหม้เพิ่มขึ้น)',
		describe_in = 'Naga penyembur api tingkat super Y melompat ke udara, kemudian terbang cepat melepaskan badai api menyerang unit baris vertikal musuh, menyebabkan #C0x3D8A99#290% Damage Sihir #C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# Damage Sihir #C0x5B545B#, menambah 2 lapis [Terbakar] yang bertahan 2 giliran pada satu baris musuh; dan menambah 15% [Kerentanan Api] selama 2 giliran untuk unit yang sedang Terbakar (Kerentanan Api: efek negatif, menerima lebih banyak damage dari skill atribut api dan damage terbakar meningkat).',
		describe_ph = 'Ang super-level Y na dragon na naghihip ng apoy ay tumalon sa hangin, pagkatapos ay mabilis na lumilipad upang maglabas ng bagyong apoy na umaatake sa mga yunit sa patayong linya ng kalaban, nagdudulot ng #C0x3D8A99#290% Magic Damage #C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# Magic Damage #C0x5B545B#, nagdaragdag ng 2 layer ng [Sunog] na tumatagal ng 2 turn para sa isang linya ng kalaban; at nagdaragdag ng 15% [Fire Vulnerability] sa loob ng 2 turn sa mga yunit na nasusunog (Fire Vulnerability: negatibong epekto, tumatanggap ng mas maraming damage mula sa mga skill na may fire attribute at nadaragdagan ang damage ng Sunog).',
		describe_ma = 'Naga menyembur api tahap super Y melompat ke udara, kemudian terbang laju melepaskan ribut api menyerang unit lajur menegak musuh, menyebabkan #C0x3D8A99#290% Kerosakan Sihir #C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# Kerosakan Sihir #C0x5B545B#, menambah 2 lapisan [Terbakar] yang berlanjutan 2 pusingan kepada satu baris musuh; dan menambah 15% [Kelemahan Api] selama 2 pusingan kepada unit yang sedang Terbakar (Kelemahan Api: kesan negatif, menerima kerosakan daripada kemahiran elemen api dan kerosakan Terbakar meningkat).',
		describe = 'Super-level Y Fire-breathing Dragon leaps into the air, then quickly flies forward to unleash a firestorm attack on the enemy\'s vertical units, dealing #C0x3D8A99#290% Magic Damage #C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# Magic Damage #C0x5B545B#, applying 2 layers of [Burn] lasting 2 turns to one row of enemies; and adding 15% [Fire Vulnerability] for 2 turns to units that are Burned (Fire Vulnerability: negative effect, increases damage taken from fire attribute skills and Burn damage).',
		simDesc_vn = 'Siêu Phun Lửa Rồng Y nhảy lên không trung, sau đó bay nhanh và phóng ra bão lửa tấn công các đơn vị hàng dọc của đối phương, đốt cháy mục tiêu và thêm hiệu ứng dễ bị tổn thương với lửa cho mục tiêu bị cháy.',
		simDesc_en = 'Dragon\'s Super Flame Spray Y leaps into the air, then swiftly flies forward, unleashing a fiery storm to attack enemy\'s vertical units, burning targets and applying a vulnerability effect with fire to the burned targets.',
		simDesc_th = 'สเปรย์เปลวไฟมังกรขั้นสุดยอด Y กระโดดขึ้นสู่อากาศ จากนั้นบินไปอย่างรวดเร็วและปล่อยพายุไฟโจมตีหน่วยของศัตรูในแนวตั้ง เผาผลาญเป้าหมายและเพิ่มผลกระทบทำให้เป้าหมายที่ถูกเผาง่ายต่อการถูกโจมตีด้วยไฟ',
		simDesc_in = 'Semprotan Api Super Naga Y meloncat ke udara, kemudian terbang cepat dan melepaskan badai api untuk menyerang unit lawan secara vertikal, membakar target dan menambahkan efek kerentanan dengan api pada target yang terbakar.',
		simDesc_ph = 'Ang Super Flame Spray Dragon Y ay tumalon pataas sa himpapawid, pagkatapos ay mabilis na lumipad at nagpalabas ng apoy na bagyo upang atakihin ang mga vertical units ng kalaban, sinusunog ang mga target at nagdaragdag ng epekto ng pagiging bulnerable dahil sa apoy sa mga nasunog na target.',
		simDesc_ma = 'Semburan Api Hebat Naga Y melompat ke udara, kemudian terbang laju dan melepaskan ribut api untuk menyerang unit berturutan musuh, membakar sasaran dan menambah kesan kerentanan dengan api pada sasaran yang terbakar.',
		simDesc = 'Dragon\'s Super Flame Spray Y leaps into the air, then swiftly flies forward, unleashing a fiery storm to attack enemy\'s vertical units, burning targets and applying a vulnerability effect with fire to the burned targets.',
		starEffect = __data_t__starEffect[153],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Kỹ năng tuyệt chiêu có thể trực tiếp thêm tối đa 3 lớp hiệu ứng thiêu đốt lên mục tiêu, và thêm 30% hiệu ứng dễ bị tổn thương với lửa lên các mục tiêu bị thiêu đốt.',
		starEffectDesc = 'Additional effect: The ultimate skill can directly add up to 3 layers of burn effect on the target, and add 30% vulnerability effect with fire to targets that are burning.',
		starEffectDesc_en = 'Additional effect: The ultimate skill can directly add up to 3 layers of burn effect on the target, and add 30% vulnerability effect with fire to targets that are burning.',
		starEffectDesc_th = 'ผลเสริม: ทักษะสุดยอดสามารถเพิ่มชั้นของเอฟเฟกต์เผาไหม้ได้สูงสุด 3 ชั้นโดยตรงบนเป้าหมาย และเพิ่มเอฟเฟกต์ความเปราะบาง 30% กับไฟให้กับเป้าหมายที่กำลังถูกไฟเผาไหม้',
		starEffectDesc_in = 'Efek tambahan: Skill pamungkas dapat langsung menambahkan hingga 3 lapisan efek terbakar pada target, dan menambahkan 30% efek kerentanan dengan api pada target yang terbakar.',
		starEffectDesc_ph = 'Karagdagang epekto: Ang ultimate na kakayahan ay maaaring direktang magdagdag ng hanggang 3 na patong ng epekto ng pagsunog sa target, at magdagdag ng 30% na epekto ng pagiging mahina sa apoy sa mga target na nasusunog.',
		starEffectDesc_ma = 'Kesan tambahan: Kemahiran ulti boleh terus menambah sehingga 3 lapisan kesan terbakar pada sasaran, dan menambah 30% kesan kerentanan dengan api ke sasaran yang terbakar.',
