	[212] = {
		id = 212,
		skillName_vn = 'Va chạm',
		skillName_en = 'Collision',
		skillName_th = 'การชนกัน',
		skillName_in = 'Tabrakan',
		skillName_ph = 'Banggaan',
		skillName_ma = 'Perlanggaran',
		skillName = 'Collision',
		describe_vn = 'Rùa nước sử dụng sức mạnh của dòng nước đâm đầu vào mục tiêu đơn lẻ của kẻ thù, gây #C0x3D8A99#130% Công Phép #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, và thêm một lá chắn cho bản thân, có thể hấp thụ sát thương bằng 200% phòng pháp của bản thân, kéo dài 2 lượt',
		describe_en = 'The Water Turtle uses the power of the water stream to charge at a single enemy target, dealing #C0x3D8A99#130% Magical Power #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, and grants a shield to itself that can absorb damage equal to 200% of its own magic defense, lasting 2 turns.',
		describe_th = 'เต่าน้ำใช้พลังของกระแสน้ำพุ่งชนเป้าหมายศัตรูเดี่ยวสร้างความเสียหายทางเวท #C0x3D8A99#130% พลังเวท #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายเวท #C0x5B545B# และเพิ่มโล่ป้องกันให้ตัวเอง สามารถดูดซับความเสียหายได้เท่ากับ 200% ของการป้องกันเวทของตัวเอง เป็นเวลานาน 2 เทิร์น',
		describe_in = 'Kura air menggunakan kekuatan aliran air untuk menerjang satu target musuh, menyebabkan #C0x3D8A99#130% Kekuatan Magis #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, dan menambahkan perisai untuk dirinya sendiri yang dapat menyerap kerusakan sebesar 200% pertahanan sihirnya sendiri, bertahan selama 2 giliran.',
		describe_ph = 'Ginagamit ng Water Turtle ang lakas ng agos ng tubig upang tumackle sa isang solong target ng kalaban, na nagdudulot ng #C0x3D8A99#130% Magical Power #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, at nagbibigay ng isang kalasag para sa sarili na maaaring sumipsip ng pinsala na katumbas ng 200% ng sariling magic defense, tumatagal ng 2 turn.',
		describe_ma = 'Turtle Air menggunakan kekuatan aliran air untuk menyerang sasaran musuh tunggal, menyebabkan #C0x3D8A99#130% Kuasa Magik #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, dan menambah satu perisai untuk dirinya sendiri yang boleh menyerap kerosakan sebanyak 200% pertahanan magiknya sendiri, bertahan selama 2 pusingan.',
		describe = 'The Water Turtle uses the power of the water stream to charge at a single enemy target, dealing #C0x3D8A99#130% Magical Power #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, and grants a shield to itself that can absorb damage equal to 200% of its own magic defense, lasting 2 turns.',
		simDesc_vn = 'Nhím Nước sử dụng sức mạnh dòng nước đâm đầu vào mục tiêu đơn lẻ của đối phương.',
		simDesc_en = 'The Water Hedgehog uses the power of water to charge headfirst into a single enemy target.',
		simDesc_th = 'เม่นน้ำใช้พลังแห่งสายน้ำพุ่งเข้าชนเป้าหมายเดี่ยวของฝ่ายตรงข้าม',
		simDesc_in = 'Landak Air menggunakan kekuatan air untuk menubruk satu target musuh secara langsung.',
		simDesc_ph = 'Gumagamit ang Water Hedgehog ng kapangyarihan ng tubig para sumugod sa iisang target ng kalaban.',
		simDesc_ma = 'Landak Air menggunakan kekuatan air untuk menyerang sasaran tunggal musuh secara terus-menerus.',
		simDesc = 'The Water Hedgehog uses the power of water to charge headfirst into a single enemy target.',
		zawakeEffect = __data_t__zawakeEffect[212],
		-- {79002}
		zawakeEffectDesc = 'The Turtle uses the power of water currents to ram into a single enemy target, dealing #C0x3D8A99#130% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, and adds a shield to the front row of its own side, which can absorb damage equal to 200% of its own Magic Defense, lasting 2 turns',
		zawakeEffectDesc_en = 'The Turtle uses the power of water currents to ram into a single enemy target, dealing #C0x3D8A99#130% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, and adds a shield to the front row of its own side, which can absorb damage equal to 200% of its own Magic Defense, lasting 2 turns',
		zawakeEffectDesc_th = 'เต่าตัวน้อยใช้พลังคลื่นน้ำพุ่งชนเป้าหมายศัตรูเดี่ยว ก่อให้เกิด #C0x3D8A99#130% พลังโจมตีเวท#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายเวทเวท #C0x5B545B# และเพิ่มโล่ปกป้องให้กับแถวหน้าของฝ่ายตนเอง สามารถดูดซับความเสียหายได้เท่ากับ 200% พลังเวทป้องกันของตนเอง อยู่ได้ 2 เทิร์น',
		zawakeEffectDesc_in = 'Kura kecil memanfaatkan kekuatan arus air untuk menyeruduk satu target musuh, memberikan #C0x3D8A99#130% Serangan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, dan menambahkan perisai untuk barisan depan dari pihak sendiri, dapat menyerap kerusakan sebesar 200% Pertahanan Sihirnya sendiri, bertahan selama 2 giliran',
		zawakeEffectDesc_ph = 'Ang pagong ay gumagamit ng lakas ng agos ng tubig upang hampasin ang isang target na kalaban, na nagdudulot ng #C0x3D8A99#130% Pag-atake ng Mahika#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Pinsala ng Mahika #C0x5B545B#, at nagbibigay ng isang kalasag sa unahang hanay ng kanilang panig, na maaaring sumipsip ng pinsala na katumbas ng 200% ng sariling Depensa ng Mahika, tumatagal ng 2 mga turn',
		zawakeEffectDesc_ma = 'Tukik memanfaatkan kekuatan arus air untuk melanggar satu sasaran musuh, memberi #C0x3D8A99#130% Serangan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, dan menambahkan perisai untuk barisan hadapan pihak sendiri, dapat menyerap kerosakan sebanyak 200% Pertahanan Sihirnya sendiri, bertahan selama 2 pusingan',
		zawakeEffectDesc_vn = 'Rùa Con tận dụng sức mạnh dòng nước dùng đầu húc vào mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#130% Phép Công#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, và thêm lá chắn cho hàng trước của phe mình, có thể hấp thụ sát thương bằng 200% Phép Phòng của bản thân, kéo dài 2 lượt',
