	[243] = {
		id = 243,
		skillName_vn = 'Pháo đại bác tên lửa nước',
		skillName_en = 'Water rocket cannon',
		skillName_th = 'ปืนใหญ่จรวดน้ำ',
		skillName_in = 'Meriam roket air',
		skillName_ph = 'Kanyon ng rocket na tubig',
		skillName_ma = 'Meriam roket air',
		skillName = 'Water rocket cannon',
		describe_vn = 'Super Blastoise phun mạnh vòi rồng nước tấn công các mục tiêu ở hàng đầu của địch, gây #C0x3D8A99#250% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, loại bỏ 2 hiệu ứng buff trên mỗi mục tiêu và thêm khiên cho tất cả đồng minh có thể hấp thụ 240% khả năng phòng thủ phép thuật của chính họ. Giá trị lá chắn của anh hùng hàng đầu tăng 50%, kéo dài trong 2 hiệp.',
		describe_en = 'Super Blastoise sprays a powerful water vortex to attack front-line enemy targets, dealing #C0x3D8A99#250% Magic Damage#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# Magic Damage #C0x5B545B#, removing 2 buff effects from each target and adding a shield to all allies that can absorb 240% of their own magic defense. The front-line hero\'s shield value increases by 50%, lasting for 2 turns.',
		describe_th = 'ซูเปอร์บลาสโทไอซ์พ่นน้ำวนแรงๆโจมตีกลุ่มเป้าหมายแนวหน้า ศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#250%#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# ลบ 2 ผลบัฟจากแต่ละเป้าหมาย และเพิ่มโล่ป้องกันให้กับพันธมิตรรอบตัว สามารถดูดซับพลังป้องกันเวทมนตร์ของตนเอง 240% ค่าความแข็งแกร่งของโล่ฮีโร่แถวหน้าเพิ่มขึ้น 50% และอยู่ได้นาน 2 เทิร์น',
		describe_in = 'Super Blastoise menyemburkan pusaran air kuat yang menyerang target barisan depan musuh, memberikan #C0x3D8A99#250% Damage Sihir#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# Damage Sihir #C0x5B545B#, menghilangkan 2 efek buff dari setiap target dan menambahkan pelindung untuk semua sekutu yang dapat menyerap 240% kemampuan pertahanan sihir mereka sendiri. Nilai pelindung pahlawan barisan depan meningkat 50%, berlangsung selama 2 giliran.',
		describe_ph = 'Super Blastoise ay nagsuspray ng malakas na tubig na paikot upang atakihin ang mga target sa front line ng kalaban, na nagdudulot ng #C0x3D8A99#250% Magic Damage#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# Magic Damage #C0x5B545B#, nag-aalis ng 2 buff effects sa bawat target at nagdaragdag ng shield sa lahat ng kakampi na makakabawas ng 240% ng kanilang sariling magic defense. Ang shield value ng front-line hero ay tumataas ng 50%, tumatagal ng 2 turn.',
		describe_ma = 'Super Blastoise menyembur pusaran air kuat menyerang sasaran barisan hadapan musuh, menyebabkan #C0x3D8A99#250% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# Kerosakan Sihir #C0x5B545B#, membuang 2 kesan buff pada setiap sasaran dan menambah perisai kepada semua sekutu yang dapat menyerap 240% keupayaan pertahanan sihir mereka sendiri. Nilai perisai wira barisan hadapan meningkat 50%, bertahan selama 2 pusingan.',
		describe = 'Super Blastoise sprays a powerful water vortex to attack front-line enemy targets, dealing #C0x3D8A99#250% Magic Damage#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# Magic Damage #C0x5B545B#, removing 2 buff effects from each target and adding a shield to all allies that can absorb 240% of their own magic defense. The front-line hero\'s shield value increases by 50%, lasting for 2 turns.',
		simDesc_vn = 'Super Blastoise phun mạnh những khẩu pháo nước tấn công các mục tiêu ở hàng đầu của kẻ địch, phân tán hiệu ứng buff của từng mục tiêu và tạo thêm lá chắn cho tất cả đồng minh.',
		simDesc_en = 'Super Blastoise fiercely sprays powerful water cannons to attack targets in the enemy\'s front line, dispersing each target\'s buff effects and creating shields for all allies.',
		simDesc_th = 'ซูเปอร์บลาสโทไอส์ยิงปืนฉีดน้ำพลังสูงโจมตีเป้าหมายในแถวหน้าของศัตรู ทำให้สลายเอฟเฟกต์บัฟของแต่ละเป้าหมายและสร้างโล่ป้องกันให้กับพันธมิตรทั้งหมด',
		simDesc_in = 'Super Blastoise menyemprotkan meriam air yang kuat untuk menyerang target di barisan depan musuh, menyebarkan efek buff tiap target dan membuat perisai untuk semua sekutu.',
		simDesc_ph = 'Ang Super Blastoise ay malakas na nagbubuga ng mga kanyon ng tubig upang atakihin ang mga target sa harapang linya ng kalaban, pinaghihiwalay ang mga effect ng buff ng bawat target at lumikha ng mga kalasag para sa lahat ng kasamahan.',
		simDesc_ma = 'Super Blastoise menyembur meriam air yang kuat untuk menyerang sasaran di barisan hadapan musuh, menyebarkan kesan buff setiap sasaran dan menghasilkan perisai bagi semua sekutu.',
		simDesc = 'Super Blastoise fiercely sprays powerful water cannons to attack targets in the enemy\'s front line, dispersing each target\'s buff effects and creating shields for all allies.',
		starEffect = __data_t__starEffect[243],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Trong thời gian lá chắn tồn tại, tăng cho mục tiêu 10% kháng bạo kích và kháng tất sát, hiệu ứng tăng gấp đôi cho tướng hệ Thủy.',
		starEffectDesc = 'Additional effect: While the shield lasts, increases the target\'s Crit Resistance and Fatal Resistance by 10%, effect doubles for Water element heroes.',
		starEffectDesc_en = 'Additional effect: While the shield lasts, increases the target\'s Crit Resistance and Fatal Resistance by 10%, effect doubles for Water element heroes.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ในระยะเวลาที่โล่ยังอยู่ จะเพิ่มการต้านทานคริติคอลและการต้านทานคริติคอลขั้นรุนแรงของเป้าหมายขึ้น 10% ผลจะเพิ่มเป็นสองเท่าสำหรับฮีโร่ธาตุน้ำ',
		starEffectDesc_in = 'Efek tambahan: Selama perisai bertahan, tingkatkan Resistensi Kritis dan Resistensi Fatal target sebesar 10%, efeknya menjadi dua kali lipat untuk pahlawan elemen Air.',
		starEffectDesc_ph = 'Karagdagang epekto: Habang umiiral ang panangga, tataasan ang Crit Resistance at Fatal Resistance ng target ng 10%, doble ang epekto para sa mga bayani ng Water element.',
		starEffectDesc_ma = 'Kesan tambahan: Semasa perisai wujud, tingkatkan tentangan Kritikal dan tentangan Fatal sasaran sebanyak 10%, kesan berganda untuk wira elemen Air.',
		upLvDesc = 'Fixed damage +136',
