		skillName_ph = 'Magulong Bato ng Kidlat',
		skillName_ma = 'Batu Guruh Kacau',
		skillName = 'Chaotic Thunderstone',
		describe_vn = 'Pikachu giải phóng dòng điện liên tục đá vào mục tiêu hàng đối phương, gây ra #C0x3D8A99#230% Phép Công#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Phép Thuật#C0x5B545B#, và có 50% xác suất [tê liệt] (tê liệt: hiệu ứng kiểm soát, không thể sử dụng tuyệt chiêu) mục tiêu 2 lượt, lần đầu tiên giải phóng chắc chắn [tê liệt] mục tiêu',
		describe_en = 'Pikachu continuously releases a stream of electricity, striking the enemy\'s frontline, dealing #C0x3D8A99#230% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage#C0x5B545B#, and has a 50% chance to [paralyze] (paralyze: control effect, unable to use ultimate skills) the target for 2 turns. The first release guarantees [paralyze] the target.',
		describe_th = 'พิคาชูปล่อยกระแสไฟฟ้าต่อเนื่องโจมตีเป้าหมายแถวหน้าของฝ่ายตรงข้าม สร้างความเสียหายเวท #C0x3D8A99#230% พลังโจมตีเวท#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายเวท#C0x5B545B# และมีโอกาส 50% ที่จะ [เป็นอัมพาต] (เป็นอัมพาต: เอฟเฟกต์ควบคุม, ไม่สามารถใช้ท่าไม้ตายได้) เป้าหมาย 2 เทิร์น ครั้งแรกที่ปล่อยจะทำให้เป้าหมาย [เป็นอัมพาต] แน่นอน',
		describe_in = 'Pikachu melepaskan aliran listrik secara terus-menerus yang menghantam barisan depan musuh, menyebabkan #C0x3D8A99#230% Serangan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Sihir#C0x5B545B#, dan memiliki peluang 50% untuk [melumpuhkan] (melumpuhkan: efek kontrol, tidak bisa menggunakan jurus pamungkas) target selama 2 giliran. Pelepasan pertama pasti akan [melumpuhkan] target.',
		describe_ph = 'Patuloy na nagpapalabas si Pikachu ng kuryente na tumatama sa harapang hanay ng kalaban, nagdudulot ng #C0x3D8A99#230% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage#C0x5B545B#, at may 50% na tsansa na [paralyze] (paralyze: control effect, hindi makagamit ng ultimate skill) ang target ng 2 turn. Sa unang pagpapalabas, siguradong mapaparalyze ang target.',
		describe_ma = 'Pikachu melepaskan arus elektrik berterusan yang menyerang barisan hadapan musuh, menyebabkan #C0x3D8A99#230% Serangan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Sihir#C0x5B545B#, dan mempunyai peluang 50% untuk [lumpuhkan] (lumpuhkan: kesan kawalan, tidak boleh menggunakan serangan utama) sasaran selama 2 pusingan. Pelepasan pertama pasti akan [lumpuhkan] sasaran.',
		describe = 'Pikachu continuously releases a stream of electricity, striking the enemy\'s frontline, dealing #C0x3D8A99#230% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage#C0x5B545B#, and has a 50% chance to [paralyze] (paralyze: control effect, unable to use ultimate skills) the target for 2 turns. The first release guarantees [paralyze] the target.',
		simDesc_vn = 'Pikachu phát ra dòng điện liên tiếp đá vào mục tiêu hàng dọc của đối phương, có khả năng làm cho chúng tê liệt, lần sử dụng đầu tiên chắc chắn sẽ tê liệt.',
		simDesc_en = 'Pikachu unleashes a continuous stream of electricity, striking the opponent\'s vertical line of targets, with a chance to paralyze them. The first use is guaranteed to cause paralysis.',
		simDesc_th = 'ปิกาจูปล่อยกระแสไฟฟ้าต่อเนื่องโจมตีกลุ่มเป้าหมายในแนวตั้งของศัตรู มีโอกาสทำให้พวกมันเป็นอัมพาต และการใช้ครั้งแรกจะทำให้อัมพาตอย่างแน่นอน',
		simDesc_in = 'Pikachu mengeluarkan aliran listrik beruntun yang memukul target vertikal musuh, dengan kemungkinan melumpuhkan mereka. Penggunaan pertama dijamin akan melumpuhkan.',
		simDesc_ph = 'Si Pikachu ay nagbubuga ng tuloy-tuloy na kuryente, tumatama sa patayong hanay ng mga target ng kalaban, na may kakayahang paralizin sila. Ang unang paggamit ay garantisadong magpapalumpo.',
		simDesc_ma = 'Pikachu melepaskan aliran elektrik berterusan yang memukul sasaran dalam barisan menegak musuh, dengan kebarangkalian untuk melumpuhkan mereka. Penggunaan pertama pasti akan menyebabkan lumpuh.',
		simDesc = 'Pikachu unleashes a continuous stream of electricity, striking the opponent\'s vertical line of targets, with a chance to paralyze them. The first use is guaranteed to cause paralysis.',
		starEffect = __data_t__starEffect[913],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Đối với mục tiêu đã bị tê liệt, có 30% xác suất tạo ra quá tải, làm cho kẻ địch bị <Choáng> trong 1 lượt (Choáng: hiệu ứng kiểm soát, không thể hành động).',
		starEffectDesc = 'Additional Effect: For targets that are paralyzed, there is a 30% chance to cause overload, making the enemy <Stun> for 1 turn (Stun: control effect, unable to act).',
		starEffectDesc_en = 'Additional Effect: For targets that are paralyzed, there is a 30% chance to cause overload, making the enemy <Stun> for 1 turn (Stun: control effect, unable to act).',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: สำหรับเป้าหมายที่ถูกเป็นอัมพาต มีโอกาส 30% ที่จะสร้างโอเวอร์โหลด ทำให้ศัตรู <มึนงง> เป็นเวลา 1 เทิร์น (มึนงง: เอฟเฟกต์ควบคุม ไม่สามารถกระทำได้)',
		starEffectDesc_in = 'Efek Tambahan: Untuk target yang terkena kelumpuhan, ada peluang 30% untuk menyebabkan overload, membuat musuh <Pingsan> selama 1 giliran (Pingsan: efek kontrol, tidak bisa bertindak).',
		starEffectDesc_ph = 'Karagdagang Epekto: Para sa mga target na na-paralyze, may 30% na tsansa na magdulot ng overload, na ginagawang <Stun> ang kalaban sa loob ng 1 turn (Stun: kontrol na epekto, hindi makakilos).',
		starEffectDesc_ma = 'Kesan Tambahan: Untuk sasaran yang lumpuh, terdapat kebarangkalian 30% untuk menyebabkan beban lebih, membuat musuh <Kejutan> selama 1 giliran (Kejutan: kesan kawalan, tidak dapat bertindak).',
