	[946] = {
		id = 946,
		skillName_vn = 'Người khổng lồ điện',
		skillName_en = 'Electric giant',
		skillName_th = 'ยักษ์ไฟฟ้า',
		skillName_in = 'Raksasa listrik',
		skillName_ph = 'Elektrik na higante',
		skillName_ma = 'Gergasi elektrik',
		skillName = 'Electric giant',
		describe_vn = '#L10# Tích điện thành ánh sáng: #L0# Mỗi khi có một đơn vị trên sân phát ra kỹ năng hệ sét hoặc bị tê liệt, bản thân nhận được một lớp [tích điện] (tích điện: hiệu ứng đặc biệt, mỗi lớp tích điện tăng 5% sát thương kỹ năng hệ sét, giới hạn 10 lớp, khi đạt 10 lớp sẽ ngay lập tức giải tán một hiệu ứng kiểm soát của bản thân)\n#F20# \n#F40##L10# Tự tu dưỡng của diễn viên: #L0# Trước tiên bị đánh trong 3 phút, khi nhận sát thương chí mạng sẽ bùng nổ sức mạnh thật sự, giải tán toàn bộ kiểm soát của bản thân mà không tiêu hao để phát động tuyệt chiêu Zai Peli Ao, sau đó ngã xuống với kỹ năng diễn xuất vô cùng tinh tế, mỗi lớp tích điện tích lũy sẽ làm tăng sát thương đó vĩnh viễn #C0x5c9970#$(2+skillLevel*0.04-0.04)$%#C0x5B545B#',
		describe_en = '#L10# Charge into light: #L0# Whenever a unit on the field uses an electric skill or is paralyzed, you gain one layer of [Charge] (Charge: special effect, each layer increases electric skill damage by 5%, up to 10 layers. When reaching 10 layers, immediately dispel one control effect on yourself) \n#F20# \n#F40##L10# Actor\'s self-cultivation: #L0# Stunned first for 3 minutes, when receiving critical damage, truly unleash power, dispel all control effects on yourself without consuming mana to activate the Zai Peli Ao ultimate skill, then fall with extremely exquisite acting skills. Each accumulated layer of Charge permanently increases that damage by #C0x5c9970#$(2+skillLevel*0.04-0.04)$%#C0x5B545B#',
		describe_th = '#L10# สะสมพลังเป็นแสง: #L0# ทุกครั้งที่มีหน่วยบนสนามใช้ทักษะสายฟ้าหรือถูกช็อก, คุณจะได้รับชั้นของ [ชาร์จ] (ชาร์จ: เอฟเฟกต์พิเศษ, แต่ละชั้นเพิ่มความเสียหายจากทักษะสายฟ้า 5%, สูงสุด 10 ชั้น เมื่อถึง 10 ชั้นจะคลายเอฟเฟกต์ควบคุมบนตัวเองทันที) \n#F20# \n#F40##L10# การฝึกฝนตัวเองของนักแสดง: #L0# ถูกโจมตีเป็นเวลา 3 นาที, เมื่อได้รับความเสียหายวิกฤติ จะระเบิดพลังที่แท้จริง คลายทุกเอฟเฟกต์ควบคุมตัวเองโดยไม่เสียพลังเพื่อเปิดใช้งานท่าไม้ตาย Zai Peli Ao จากนั้นล้มลงด้วยทักษะการแสดงที่ยอดเยี่ยม แต่ละชั้นของชาร์จจะเพิ่มความเสียหายนั้นถาวร #C0x5c9970#$(2+skillLevel*0.04-0.04)$%#C0x5B545B#',
		describe_in = '#L10# Mengisi daya menjadi cahaya: #L0# Setiap kali ada unit di medan yang mengeluarkan skill petir atau terkena kelumpuhan, Anda menerima satu lapisan [Charge] (Charge: efek khusus, setiap lapisan meningkatkan damage skill petir sebesar 5%, maksimal 10 lapisan. Saat mencapai 10 lapisan langsung menghilangkan satu efek kontrol pada diri sendiri) \n#F20# \n#F40##L10# Pelatihan diri aktor: #L0# Pertama-tama terkena serangan selama 3 menit, ketika menerima serangan kritis akan meledakkan kekuatan sesungguhnya, menghilangkan semua kontrol pada diri sendiri tanpa menghabiskan energi untuk mengaktifkan ultimate skill Zai Peli Ao, kemudian jatuh dengan akting yang sangat halus. Setiap lapisan charge yang terkumpul akan meningkatkan damage tersebut secara permanen #C0x5c9970#$(2+skillLevel*0.04-0.04)$%#C0x5B545B#',
		describe_ph = '#L10# Mag-charge sa liwanag: #L0# Sa tuwing may yunit sa larangan na gumagamit ng ilang electric skill o na-paralyze, makakakuha ka ng isang layer ng [Charge] (Charge: espesyal na epekto, bawat layer ay nagdaragdag ng 5% electric skill damage, hanggang 10 layer. Kapag umabot sa 10 layers, agad na matatanggal ang isang control effect sa sarili) \n#F20# \n#F40##L10# Pagpapalakas ng sarili ng aktor: #L0# Pinipinsala muna ng 3 minuto, kapag nakatanggap ng critical damage ay magpapalabas ng tunay na lakas, tatanggalin ang lahat ng control effects sa sarili nang hindi kumokonsumo para paganahin ang Zai Peli Ao ultimate skill, at pagkatapos ay lalaglag gamit ang napaka-sining na acting skill. Bawat naipong layer ng charge ay permanenteng nagpapataas ng damage na iyon ng #C0x5c9970#$(2+skillLevel*0.04-0.04)$%#C0x5B545B#',
		describe_ma = '#L10# Mengecas menjadi cahaya: #L0# Setiap kali satu unit di medan menggunakan kemahiran petir atau lumpuh, anda menerima satu lapisan [Cas] (Cas: kesan khas, setiap lapisan menambah 5% kerosakan kemahiran petir, maksimum 10 lapisan. Apabila mencapai 10 lapisan, segera membuang satu kesan kawalan pada diri sendiri) \n#F20# \n#F40##L10# Latihan diri pelakon: #L0# Dikedari serangan selama 3 minit, apabila menerima kerosakan kritikal, melepaskan kekuatan sebenar, menghilangkan semua kawalan pada diri sendiri tanpa menggunakan tenaga untuk mengaktifkan kemahiran utama Zai Peli Ao, kemudian jatuh dengan kemahiran lakonan yang sangat halus. Setiap lapisan cas terkumpul akan meningkatkan kerosakan itu secara kekal #C0x5c9970#$(2+skillLevel*0.04-0.04)$%#C0x5B545B#',
		describe = '#L10# Charge into light: #L0# Whenever a unit on the field uses an electric skill or is paralyzed, you gain one layer of [Charge] (Charge: special effect, each layer increases electric skill damage by 5%, up to 10 layers. When reaching 10 layers, immediately dispel one control effect on yourself) \n#F20# \n#F40##L10# Actor\'s self-cultivation: #L0# Stunned first for 3 minutes, when receiving critical damage, truly unleash power, dispel all control effects on yourself without consuming mana to activate the Zai Peli Ao ultimate skill, then fall with extremely exquisite acting skills. Each accumulated layer of Charge permanently increases that damage by #C0x5c9970#$(2+skillLevel*0.04-0.04)$%#C0x5B545B#',
