		id = 1123,
		skillName_vn = 'Mưa kim châm độc',
		skillName_en = 'Poisoned acupuncture rain',
		skillName_th = 'ฝนเข็มพิษ',
		skillName_in = 'Hujan jarum beracun',
		skillName_ph = 'Lason na ulan ng karayom',
		skillName_ma = 'Hujan jarum beracun',
		skillName = 'Poisoned acupuncture rain',
		describe_vn = 'Nidoqueen dựng gai độc trên lưng, quét đuôi bắn ra hai hàng kim độc tấn công toàn bộ mục tiêu địch, gây #C0xE69900#120% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, và có 70% xác suất khiến chúng [Trúng độc] trong 3 lượt (Trúng độc: hiệu ứng tiêu cực, mục tiêu mất #C0xE69900#10% Công Vật Lý#C0x5B545B# sát thương thực mỗi lượt, tối đa cộng dồn 5 tầng)',
		describe_en = 'Nidoqueen raises poisonous spines on its back and sweeps its tail, shooting out two rows of toxic needles that attack all enemy targets, dealing #C0xE69900#120% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, with a 70% chance to poison them for 3 turns (Poisoned: a negative effect causing the target to lose #C0xE69900#10% Physical Attack#C0x5B545B# true damage each turn, stacking up to 5 layers).',
		describe_th = 'นิโดควีนชูหนามพิษที่หลังแล้วกวาดหางยิงเข็มพิษสองแถวโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหาย #C0xE69900#120% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# และมีโอกาส 70% ที่จะทำให้พวกมัน [ถูกพิษ] เป็นเวลา 3 เทิร์น (ถูกพิษ: เอฟเฟกต์ลบ ทำให้เป้าหมายสูญเสีย #C0xE69900#10% พลังโจมตีทางกายภาพ#C0x5B545B# ความเสียหายจริงในแต่ละเทิร์น สะสมได้สูงสุด 5 ชั้น)',
		describe_in = 'Nidoqueen menegakkan duri beracun di punggungnya dan menyapu ekornya, menembakkan dua baris jarum beracun yang menyerang semua target musuh, menyebabkan #C0xE69900#120% Serangan Fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, serta memiliki peluang 70% untuk membuat mereka [Teracuni] selama 3 giliran (Teracuni: efek negatif yang menyebabkan target kehilangan #C0xE69900#10% Serangan Fisik#C0x5B545B# kerusakan nyata setiap giliran, dapat ditumpuk hingga 5 lapis)',
		describe_ph = 'Itinaas ni Nidoqueen ang mga nakakalasong tinik sa likod nito at hinatak ang buntot nito, nagpapaputok ng dalawang hanay ng mga nakalalasong karayom na umaatake sa lahat ng mga kaaway, na nagdudulot ng #C0xE69900#120% pisikal na atake#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# pisikal na pinsala#C0x5B545B#, at may 70% tsansa na ma-[Poison] ang mga ito sa loob ng 3 turn (Poisoned: negatibong epektong nagdudulot sa target na mawalan ng #C0xE69900#10% pisikal na atake#C0x5B545B# tunay na pinsala bawat turn, hanggang 5 layers ang pwedeng mag-stack).',
		describe_ma = 'Nidoqueen mengangkat duri beracun di belakangnya dan mengibas ekornya, menembakkan dua baris jarum beracun yang menyerang semua sasaran musuh, menyebabkan #C0xE69900#120% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, dan mempunyai 70% peluang untuk menyebabkan mereka [Teracuni] selama 3 pusingan (Teracuni: kesan negatif yang menyebabkan sasaran kehilangan #C0xE69900#10% Serangan Fizikal#C0x5B545B# kerosakan sebenar setiap pusingan, boleh bertindan sehingga 5 lapisan)',
		describe = 'Nidoqueen raises poisonous spines on its back and sweeps its tail, shooting out two rows of toxic needles that attack all enemy targets, dealing #C0xE69900#120% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, with a 70% chance to poison them for 3 turns (Poisoned: a negative effect causing the target to lose #C0xE69900#10% Physical Attack#C0x5B545B# true damage each turn, stacking up to 5 layers).',
		simDesc_vn = 'Nidoqueen dựng gai độc trên lưng, quét đuôi ra hai hàng gai độc tấn công toàn bộ mục tiêu đối phương, có khả năng làm cho mục tiêu trúng độc, nếu không trúng độc thì sẽ giảm phòng thủ vật lý của mục tiêu.',
		simDesc_en = 'Nidoqueen raises poisonous spikes on its back and sweeps its tail, launching two rows of toxic spikes to attack all opposing targets. It has a chance to poison the targets; if it fails to poison, it will reduce their physical defense.',
		simDesc_th = 'นิโดควีนตั้งหนามพิษบนหลังและกวัดแกว่งหางออกไปเป็นสองแถวของหนามพิษโจมตีเป้าหมายฝ่ายตรงข้ามทั้งหมด มีโอกาสทำให้เป้าหมายถูกพิษ ถ้าไม่ถูกพิษจะลดการป้องกันทางกายภาพของเป้าหมายแทน',
		simDesc_in = 'Nidoqueen mengangkat duri beracun di punggungnya dan mengayunkan ekornya dengan dua baris duri beracun untuk menyerang semua target lawan. Memiliki peluang untuk membuat target keracunan; jika gagal, akan mengurangi pertahanan fisik target.',
		simDesc_ph = 'Itinaas ni Nidoqueen ang mga nakalalasong tinik sa kanyang likod at inayos ang buntot sa dalawang hilera ng mga nakalalasong tinik upang atakihin ang lahat ng kalabang target. May kakayahan itong magdulot ng pagkalason sa target; kung hindi magtagumpay sa pagkalason, babawasan nito ang pisikal na depensa ng target.',
		simDesc_ma = 'Nidoqueen menaikkan duri berbisa di belakangnya dan menghayunkan ekornya dengan dua baris duri berbisa untuk menyerang semua sasaran musuh. Ia berpeluang menyebabkan sasaran terkena racun; jika gagal, ia akan mengurangkan pertahanan fizikal sasaran.',
		simDesc = 'Nidoqueen raises poisonous spikes on its back and sweeps its tail, launching two rows of toxic spikes to attack all opposing targets. It has a chance to poison the targets; if it fails to poison, it will reduce their physical defense.',
		starEffect = __data_t__starEffect[1123],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Nếu mục tiêu chưa bị nhiễm độc, giảm 30% phòng thủ vật lý của mục tiêu trong 2 lượt.',
		starEffectDesc = 'Additional effect: If the target is not poisoned, reduce the target\'s physical defense by 30% for 2 turns.',
		starEffectDesc_en = 'Additional effect: If the target is not poisoned, reduce the target\'s physical defense by 30% for 2 turns.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: หากเป้าหมายยังไม่ถูกพิษ ให้ลดการป้องกันทางกายภาพของเป้าหมายลง 30% เป็นเวลา 2 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Jika target belum terkena racun, kurangi pertahanan fisik target sebesar 30% selama 2 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Kung ang target ay hindi pa nalalason, bawasan ang pisikal na depensa ng target ng 30% sa loob ng 2 na turno.',
