	[1133] = {
		id = 1133,
		skillName_vn = 'Mưa kim châm độc',
		skillName_en = 'Poisoned acupuncture rain',
		skillName_th = 'ฝนเข็มพิษ',
		skillName_in = 'Hujan jarum beracun',
		skillName_ph = 'Apat na ulan ng karayom na lason',
		skillName_ma = 'Hujan jarum beracun',
		skillName = 'Poisoned acupuncture rain',
		describe_vn = 'Nidoking dựng gai độc trên lưng nhảy lên không trung, sau đó bắn ra mưa kim độc tấn công toàn bộ mục tiêu địch, gây #C0xE69900#130% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, và có 70% xác suất khiến chúng [Trúng độc] trong 3 lượt (Trúng độc: hiệu ứng tiêu cực, mục tiêu mất #C0xE69900#10% Công Vật Lý#C0x5B545B# sát thương thực mỗi lượt, tối đa cộng dồn 5 tầng)',
		describe_en = 'Nidoking raises the poisonous spines on its back and leaps into the air, then shoots a rain of venomous needles to attack all enemy targets, dealing #C0xE69900#130% Physical Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, with a 70% chance to inflict [Poisoned] for 3 turns (Poisoned: a negative effect causing the target to lose #C0xE69900#10% Physical Attack#C0x5B545B# true damage each turn, stacking up to 5 layers).',
		describe_th = 'นิโดคิงชูหนามพิษบนหลังแล้วกระโดดขึ้นกลางอากาศ จากนั้นยิงฝนเข็มพิษโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหาย #C0xE69900#130% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# และมีโอกาส 70% ที่จะทำให้พวกมัน [ถูกพิษ] เป็นเวลา 3 เทิร์น ([ถูกพิษ]: เอฟเฟกต์ติดลบ ทำให้เป้าหมายสูญเสีย #C0xE69900#10% พลังโจมตีทางกายภาพ#C0x5B545B# ความเสียหายจริงในแต่ละเทิร์น สะสมได้สูงสุด 5 ชั้น)',
		describe_in = 'Nidoking menegakkan duri beracun di punggungnya dan melompat ke udara, kemudian menembakkan hujan jarum beracun yang menyerang semua target musuh, memberi damage #C0xE69900#130% Serangan Fisik#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, dengan peluang 70% untuk membuat mereka [Teracun] selama 3 giliran ([Teracun]: efek negatif yang menyebabkan target kehilangan #C0xE69900#10% Serangan Fisik#C0x5B545B# kerusakan nyata setiap giliran, menumpuk hingga maksimal 5 lapis).',
		describe_ph = 'Tinaas ng Nidoking ang mga lason na tinik sa likod nito at tumalon sa hangin, tapos nagpapaputok ng ulan ng lasong karayom na umaatake sa lahat ng kalaban, na nagdudulot ng #C0xE69900#130% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, at may 70% na tsansa na ma-[Poisoned] sila sa loob ng 3 turn (Poisoned: negatibong epekto na nagdudulot sa target ng pagkawala ng #C0xE69900#10% Pisikal na Atake#C0x5B545B# tunay na pinsala bawat turn, na maaaring magkayon hanggang 5 layer).',
		describe_ma = 'Nidoking mengangkat duri beracun di belakangnya dan melompat ke udara, kemudian menembak hujan jarum beracun untuk menyerang semua sasaran musuh, menyebabkan #C0xE69900#130% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, dan mempunyai peluang 70% menyebabkan mereka [Terkena Racun] selama 3 pusingan ([Terkena Racun]: kesan negatif yang menyebabkan sasaran kehilangan #C0xE69900#10% Serangan Fizikal#C0x5B545B# kerosakan sebenar setiap pusingan, bertindih sehingga maksimum 5 lapisan).',
		describe = 'Nidoking raises the poisonous spines on its back and leaps into the air, then shoots a rain of venomous needles to attack all enemy targets, dealing #C0xE69900#130% Physical Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, with a 70% chance to inflict [Poisoned] for 3 turns (Poisoned: a negative effect causing the target to lose #C0xE69900#10% Physical Attack#C0x5B545B# true damage each turn, stacking up to 5 layers).',
		simDesc_vn = 'Nido dựng gai độc trên lưng, nhảy lên không trung rồi phóng ra mưa gai độc tấn công toàn bộ mục tiêu đối phương, có khả năng làm cho mục tiêu trúng độc hoặc giảm phòng thủ vật lý.',
		simDesc_en = 'Nido raises poisonous spikes on its back, leaps into the air, and unleashes a rain of poisonous spikes attacking all enemy targets, with a chance to poison or lower their physical defense.',
		simDesc_th = 'นิโด้ตั้งหนามพิษบนหลัง กระโดดขึ้นกลางอากาศแล้วปล่อยฝนหนามพิษโจมตีเป้าหมายศัตรูทั้งหมด มีโอกาสทำให้เป้าหมายติดพิษหรือเพิ่มการลดการป้องกันทางกายภาพ',
		simDesc_in = 'Nido menancapkan duri beracun di punggungnya, melompat ke udara lalu melepaskan hujan duri beracun yang menyerang semua target musuh, dengan kemungkinan membuat target teracuni atau mengurangi pertahanan fisiknya.',
		simDesc_ph = 'Itinataas ni Nido ang mga nakakalason na tinik sa likod niya, tumatalon sa hangin at nagpapalabas ng ulan ng mga tinik na nakakalason na sumusugod sa lahat ng mga target na kalaban, na may kakayahang mapasapit ang target sa lason o mapababa ang kanilang pisikal na depensa.',
		simDesc_ma = 'Nido menaikkan duri beracun di belakangnya, melompat ke udara kemudian melepaskan hujan duri beracun yang menyerang semua sasaran musuh, dengan keupayaan meracun sasaran atau mengurangkan pertahanan fizikal mereka.',
		simDesc = 'Nido raises poisonous spikes on its back, leaps into the air, and unleashes a rain of poisonous spikes attacking all enemy targets, with a chance to poison or lower their physical defense.',
