	[1313] = {
		id = 1313,
		skillName_vn = 'À! Sao băng',
		skillName_en = 'Ah! Comet',
		skillName_th = 'อา! ดาวหาง',
		skillName_in = 'Ah! Komet',
		skillName_ph = 'Ah! Kometa',
		skillName_ma = 'Ah! Komet',
		skillName = 'Ah! Comet',
		describe_vn = 'Cleffa triệu hồi các bạn nhỏ cùng nhau ngắm sao băng và tấn công toàn bộ mục tiêu kẻ địch, gây ra #C0x3D8A99#120% Công Phép thuật#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, có 30% xác suất khiến mục tiêu [mê hoặc] trong 1 lượt (mê hoặc: hiệu ứng kiểm soát, mục tiêu có 50% xác suất không thể hành động, nếu tấn công thì sát thương gây ra giảm một nửa).',
		describe_en = 'Cleffa summons its little friends to watch shooting stars together and attack all enemy targets, dealing #C0x3D8A99#120% Magic Power#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 30% chance to cause the [charm] effect on targets for 1 turn (charm: a control effect where the target has a 50% chance to be unable to act and deals half damage if attacking).',
		describe_th = 'Cleffa เรียกเพื่อนตัวน้อยมาชมดาวตกด้วยกันและโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหาย #C0x3D8A99#120% พลังเวทย์#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# ความเสียหายเวทย์มนตร์ #C0x5B545B# โดยมีโอกาส 30% ที่จะทำให้เป้าหมาย [สาปเสน่ห์] เป็นเวลา 1 เทิร์น (สาปเสน่ห์: เอฟเฟกต์ควบคุม ทำให้เป้าหมายมีโอกาส 50% ที่จะไม่สามารถทำอะไรได้ และถ้าโจมตีจะสร้างความเสียหายเพียงครึ่งหนึ่ง).',
		describe_in = 'Cleffa memanggil teman-teman kecilnya untuk menonton meteor bersama dan menyerang semua target musuh, menyebabkan #C0x3D8A99#120% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, dengan peluang 30% untuk membuat target [terpesona] selama 1 giliran (terpesona: efek kontrol, target memiliki peluang 50% untuk tidak dapat bertindak, dan jika menyerang, kerusakan yang dihasilkan berkurang setengah).',
		describe_ph = 'Tinatawagan ni Cleffa ang kanyang maliliit na kaibigan upang sabay-sabay na magmasid ng falling stars at umatake sa lahat ng kaaway, na nagdudulot ng #C0x3D8A99#120% Magic Power#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Magic Damage #C0x5B545B#, na may 30% na tsansa na magdulot ng [charm] sa target sa loob ng 1 turn (charm: isang control effect kung saan may 50% na pagkakataon na hindi makakilos ang target, at kung umatake ay kalahati ang damage na idudulot).',
		describe_ma = 'Cleffa memanggil rakan-rakan kecilnya untuk bersama-sama memerhati bintang jatuh dan menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#120% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, dengan kebarangkalian 30% untuk menyebabkan sasaran [terpesona] selama 1 giliran (terpesona: kesan kawalan, sasaran mempunyai 50% kebarangkalian untuk tidak dapat bertindak, dan jika menyerang, kerosakan yang disebabkan berkurang separuh).',
		describe = 'Cleffa summons its little friends to watch shooting stars together and attack all enemy targets, dealing #C0x3D8A99#120% Magic Power#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 30% chance to cause the [charm] effect on targets for 1 turn (charm: a control effect where the target has a 50% chance to be unable to act and deals half damage if attacking).',
		simDesc_vn = 'Pichu triệu hồi các bạn cùng nhau truy đuổi sao băng tấn công toàn bộ mục tiêu của đối phương, có khả năng làm mục tiêu mê hoặc.',
		simDesc_en = 'Pichu summons friends to chase the shooting star, attacking all enemy targets with a chance to infatuate them.',
		simDesc_th = 'พิคชูเรียกเพื่อนๆ มาร่วมไล่ตามดาวตก โจมตีเป้าหมายฝ่ายตรงข้ามทั้งหมด พร้อมโอกาสทำให้เป้าหมายตกหลุมรัก',
