	[1616] = {
		id = 1616,
		skillName_vn = 'Chất độc xúc tác',
		skillName_en = 'Catalyst Poison',
		skillName_th = 'พิษตัวกระตุ้น',
		skillName_in = 'Racun Katalis',
		skillName_ph = 'Lason na Pampagana',
		skillName_ma = 'Racun Katalis',
		skillName = 'Catalyst Poison',
		describe_vn = 'Khiến các anh hùng phe ta khi sử dụng kỹ năng nhỏ tấn công mục tiêu có #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# xác suất kèm theo 1 tầng hiệu ứng trúng độc, kéo dài 3 lượt (trúng độc: hiệu ứng tiêu cực, mục tiêu mất sát thương thực bằng 40% Công Vật Lý của Zubat mỗi lượt, tối đa cộng dồn 5 tầng)\nCác anh hùng hệ độc có xác suất kích hoạt hiệu ứng này tăng thêm 50%',
		describe_en = 'When our heroes use a skill to lightly attack a target, there is a #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# chance to apply one stack of poison effect, lasting 3 turns (poison: a negative effect causing the target to lose true damage equal to 40% of Zubat\'s Physical Attack each turn, stacking up to 5 times).\n Heroes of the poison element have a 50% increased chance to trigger this effect.',
		describe_th = 'เมื่อฮีโร่ฝ่ายเราส่งทักษะโจมตีเป้าหมายแบบเล็กน้อย จะมีโอกาส #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# ที่จะติดเอฟเฟกต์พิษ 1 ชั้น นาน 3 เทิร์น (พิษ: เอฟเฟกต์ลบ เป้าหมายจะเสียดาเมจจริงเท่ากับ 40% ของพลังโจมตีทางกายภาพของ Zubat ในแต่ละเทิร์น สะสมได้สูงสุด 5 ชั้น)\n ฮีโร่ธาตุพิษจะมีโอกาสเพิ่มขึ้นอีก 50% ในการเปิดใช้งานเอฟเฟกต์นี้',
		describe_in = 'Ketika pahlawan kami menggunakan skill untuk menyerang target dengan serangan kecil, ada peluang #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# untuk mendapatkan 1 tumpukan efek racun, berlangsung selama 3 giliran (racun: efek negatif, target kehilangan damage sebenarnya sebesar 40% dari Serangan Fisik Zubat setiap giliran, bertumpuk hingga maksimal 5 tumpukan)\n Pahlawan elemen racun memiliki peluang meningkat 50% untuk mengaktifkan efek ini.',
		describe_ph = 'Kapag ginamit ng aming mga bayani ang isang kasanayan upang bahagyang atakihin ang target, may #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# na pagkakataon na makadagdag ng isang patong ng poison effect na tumatagal ng 3 turns (poison: isang negatibong epekto kung saan ang target ay nawawala ng totoong pinsala na katumbas ng 40% ng Physical Attack ni Zubat kada turn, maaari itong mag-stack ng hanggang 5 patong).\n Ang mga bayani ng poison element ay may dagdag na 50% na pagkakataon na mapagana ang epektong ito.',
		describe_ma = 'Apabila wira kami menggunakan kemahiran untuk menyerang sasaran dengan serangan kecil, terdapat kebarangkalian #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# untuk menerima satu lapisan kesan racun, bertahan selama 3 pusingan (racun: kesan negatif, sasaran kehilangan kerosakan sebenar sebanyak 40% Serangan Fizikal Zubat setiap pusingan, bertindih maksimum 5 lapisan)\n Wira elemen racun mempunyai kebarangkalian tambahan 50% untuk mengaktifkan kesan ini.',
		describe = 'When our heroes use a skill to lightly attack a target, there is a #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# chance to apply one stack of poison effect, lasting 3 turns (poison: a negative effect causing the target to lose true damage equal to 40% of Zubat\'s Physical Attack each turn, stacking up to 5 times).\n Heroes of the poison element have a 50% increased chance to trigger this effect.',
		starEffect = __data_t__starEffect[1616],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sau mỗi lần tấn công không phải kỹ năng tuyệt chiêu, sẽ sao chép hiệu ứng nhiễm độc từ mục tiêu bị tấn công sang một mục tiêu ngẫu nhiên bên địch (ưu tiên chọn đơn vị chưa bị nhiễm độc).',
		starEffectDesc = 'Additional Effect: After each attack that is not a special skill, the poison effect from the attacked target will be copied to a random enemy target (prioritizing units not yet poisoned).',
		starEffectDesc_en = 'Additional Effect: After each attack that is not a special skill, the poison effect from the attacked target will be copied to a random enemy target (prioritizing units not yet poisoned).',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: หลังการโจมตีแต่ละครั้งที่ไม่ใช่สกิลพิเศษ จะคัดลอกเอฟเฟกต์พิษจากเป้าหมายที่ถูกโจมตีไปยังเป้าหมายศัตรูแบบสุ่ม (ให้ความสำคัญกับหน่วยที่ยังไม่ถูกพิษ)',
		starEffectDesc_in = 'Efek Tambahan: Setelah setiap serangan yang bukan skill spesial, efek racun dari target yang diserang akan disalin ke target musuh acak (memprioritaskan unit yang belum terkena racun).',
		starEffectDesc_ph = 'Karagdagang Epekto: Pagkatapos ng bawat atake na hindi isang espesyal na kasanayan, ang epekto ng lason mula sa tinarget na inatake ay kokopyahin sa isang random na kalaban na target (binibigyang prayoridad ang mga yunit na hindi pa nalalason).',
		starEffectDesc_ma = 'Kesan Tambahan: Selepas setiap serangan yang bukan kemahiran istimewa, kesan racun daripada sasaran yang diserang akan disalin ke sasaran musuh secara rawak (utamakan unit yang belum terkena racun).',
		zawakeEffect = __data_t__zawakeEffect[1616],
		-- {79004}
		zawakeEffectDesc = 'Make our hero, when attacking with a minor skill, have a #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# chance to apply 1 layer of poison effect lasting 3 turns (poison: negative effect, target loses 40% of the actual physical attack of ultrasonic Bat each turn, stacking up to 5 layers)\nHeroes with poison attribute have their chance to trigger this effect increased by 100%',
		zawakeEffectDesc_en = 'Make our hero, when attacking with a minor skill, have a #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# chance to apply 1 layer of poison effect lasting 3 turns (poison: negative effect, target loses 40% of the actual physical attack of ultrasonic Bat each turn, stacking up to 5 layers)\nHeroes with poison attribute have their chance to trigger this effect increased by 100%',
		zawakeEffectDesc_th = 'ทำให้อัศวินฝ่ายเราตอนโจมตีด้วยสกิลเล็กมีโอกาส #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# แนบเอฟเฟกต์พิษ 1 ชั้นนาน 3 เทิร์น (พิษ: เอฟเฟกต์ลบ, เป้าหมายเสียพลังโจมตีจริงทางกายภาพของค้างคาวอัลตราโซนิค 40% ต่อเทิร์น สะสมได้สูงสุด 5 ชั้น)\nฮีโร่ธาตุพิษมีโอกาสเปิดใช้งานเอฟเฟกต์นี้เพิ่มขึ้น 100%',
		zawakeEffectDesc_in = 'Buat pahlawan kita saat menyerang dengan skill kecil memiliki peluang #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# untuk menimbulkan 1 lapisan efek racun yang berlangsung selama 3 giliran (racun: efek negatif, target kehilangan 40% serangan fisik nyata dari Kelelawar Ultrasonik setiap giliran, bertumpuk hingga 5 lapisan)\nPahlawan dengan atribut racun memiliki peluang aktivasi efek ini meningkat 100%',
		zawakeEffectDesc_ph = 'Gawing may #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# na chance ang aming bayani kapag umatake gamit ang maliit na skill na may 1 layer na poison effect na tumatagal ng 3 turns (poison: negatibong epekto, nawawala sa target ang 40% ng aktwal na physical attack mula sa Ultrasonic Bat kada turn, maximum na 5 layers ng stack)\nAng mga bayani na may poison attribute ay may 100% dagdag na chance na mag-trigger ng effect na ito',
		zawakeEffectDesc_ma = 'Jadikan wira kami apabila menyerang dengan kemahiran kecil mempunyai peluang #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# untuk mengenakan 1 lapisan kesan racun yang bertahan selama 3 pusingan (racun: kesan negatif, sasaran kehilangan 40% serangan fizikal sebenar Kelelawar Ultrasonik setiap pusingan, bertindih sehingga 5 lapisan)\nWira dengan elemen racun mempunyai peluang mengaktifkan kesan ini meningkat 100%',
		zawakeEffectDesc_vn = 'Làm cho anh hùng phe mình khi tấn công bằng kỹ năng nhỏ có #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# xác suất kèm theo 1 tầng hiệu ứng trúng độc, kéo dài 3 lượt (trúng độc: hiệu ứng tiêu cực, mục tiêu mất 40% vật công thực của Dơi siêu âm mỗi lượt, tối đa cộng dồn 5 tầng)\nAnh hùng hệ độc có xác suất kích hoạt hiệu ứng này tăng thêm 100%',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Poison heroes have 50% increased chance to trigger this effect\n#F20# \n#F40##C0x5c9970#→ Poison heroes have 100% increased chance to trigger this effect',
		zawakeSimpleDesc_en = 'Poison heroes have 50% increased chance to trigger this effect\n#F20# \n#F40##C0x5c9970#→ Poison heroes have 100% increased chance to trigger this effect',
		zawakeSimpleDesc_th = 'โอกาสเกิดผลนี้ของฮีโร่ธาตุพิษเพิ่มขึ้น 50%\n#F20# \n#F40##C0x5c9970#→ โอกาสเกิดผลนี้ของฮีโร่ธาตุพิษเพิ่มขึ้น 100%',
		zawakeSimpleDesc_in = 'Pahlawan elemen racun memiliki 50% peluang lebih tinggi untuk memicu efek ini\n#F20# \n#F40##C0x5c9970#→ Pahlawan elemen racun memiliki 100% peluang lebih tinggi untuk memicu efek ini',
		zawakeSimpleDesc_ph = 'Mas mataas ng 50% ang chance ng mga Poison-type na bayani na i-activate ang effect na ito\n#F20# \n#F40##C0x5c9970#→ Mas mataas ng 100% ang chance ng mga Poison-type na bayani na i-activate ang effect na ito',
		zawakeSimpleDesc_ma = 'Peluang untuk mengaktifkan kesan ini meningkat 50% bagi wira elemen racun\n#F20# \n#F40##C0x5c9970#→ Peluang untuk mengaktifkan kesan ini meningkat 100% bagi wira elemen racun',
