	[1623] = {
		id = 1623,
		skillName_vn = 'Đạn độc tập trung',
		skillName_en = 'Concentrated poison bullet',
		skillName_th = 'กระสุนพิษเข้มข้น',
		skillName_in = 'Peluru racun terkonsentrasi',
		skillName_ph = 'Nakatuon na lasong bala',
		skillName_ma = 'Peluru racun tertumpu',
		skillName = 'Concentrated poison bullet',
		describe_vn = 'Golbat mở miệng lớn nhất có thể và hít vào điên cuồng, sau đó phun ra một quả cầu chứa độc tố vào đám đông, quả cầu phát nổ và phân tách thành nhiều quả cầu nhỏ hơn rồi tiếp tục phát nổ, gây Sát Thương Vật Lý #C0xE69900#210% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Sát Thương Vật Lý#C0x5B545B# lên mục tiêu chính và kẻ địch trong phạm vi hình chữ thập, thêm 2 tầng [trúng độc] lên mục tiêu hình chữ thập, kéo dài 3 lượt (trúng độc: hiệu ứng tiêu cực, mục tiêu mất sát thương thực bằng 40% Công Vật Lý của Golbat mỗi lượt, tối đa cộng dồn 5 tầng)',
		describe_en = 'Golbat opens its mouth as wide as possible and inhales frantically, then spits out a toxic orb into the crowd. The orb explodes and splits into smaller orbs, which continue to explode, dealing Physical Damage #C0xE69900#210% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Physical Damage#C0x5B545B# to the main target and enemies within a cross-shaped area, applying 2 stacks of [Poisoned] to targets in the cross area lasting 3 turns (Poisoned: negative effect, target loses true damage equal to 40% of Golbat\'s Physical Attack each turn, up to 5 stacks).',
		describe_th = 'โกแบ็ตเปิดปากกว้างที่สุดเท่าที่จะทำได้และสูดลมหายใจอย่างบ้าคลั่ง จากนั้นพ่นลูกบอลพิษเข้าไปยังฝูงชน ลูกบอลระเบิดและแยกออกเป็นลูกบอลเล็ก ๆ ที่ระเบิดต่อเนื่อง ก่อให้เกิดความเสียหายทางกายภาพ #C0xE69900#210% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# แก่เป้าหมายหลักและศัตรูในพื้นที่รูปกากบาท พร้อมเพิ่มสถานะ [ถูกพิษ] 2 ชั้นกับเป้าหมายในพื้นที่กากบาทเป็นเวลา 3 รอบ (ถูกพิษ: ผลลบ, เป้าหมายเสียค่าความเสียหายจริงเท่ากับ 40% ของพลังโจมตีทางกายภาพของโกแบ็ตในแต่ละรอบ สะสมสูงสุด 5 ชั้น)',
		describe_in = 'Golbat membuka mulut selebar mungkin dan menghirup dengan gila, kemudian menyemburkan bola beracun ke kerumunan. Bola itu meledak dan terpecah menjadi bola-bola kecil yang terus meledak, menyebabkan Kerusakan Fisik #C0xE69900#210% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerusakan Fisik#C0x5B545B# pada target utama dan musuh dalam jangkauan berbentuk silang, menambahkan 2 tumpukan [Terkontaminasi] pada target area silang selama 3 giliran (Terkontaminasi: efek negatif, target kehilangan damage nyata sebesar 40% Serangan Fisik Golbat setiap giliran, maksimum 5 tumpukan).',
		describe_ph = 'Bukas ni Golbat ang pinakamalapad niyang bibig at huminga nang buong lakas, pagkatapos ay sumabog ng isang bola ng lason papunta sa karamihan. Ang bola ay sumabog at nahati sa mas maliliit na bola na patuloy na sumabog, nagdudulot ng Pisikal na Pinsala #C0xE69900#210% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Pisikal na Pinsala#C0x5B545B# sa pangunahing target at kalaban sa loob ng isang cross-shaped na lugar, nagdadagdag ng 2 stack ng [Naipisyuhan] sa mga target sa cross area na tumatagal ng 3 turn (Naipisyuhan: negatibong epekto, nawawalan ng tunay na pinsala ang target na katumbas ng 40% ng Pisikal na Atake ni Golbat bawat turn, hanggang sa maximum na 5 stack).',
		describe_ma = 'Golbat membuka mulut selebar mungkin dan menghirup dengan ganas, kemudian memuntahkan bola toksik ke dalam kerumunan. Bola itu meletup dan berpecah menjadi bola-bola kecil yang terus meletup, menyebabkan Kerosakan Fizikal #C0xE69900#210% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerosakan Fizikal#C0x5B545B# ke sasaran utama dan musuh dalam kawasan berbentuk silang, menambah 2 lapisan [Beracun] ke sasaran dalam kawasan silang selama 3 pusingan (Beracun: kesan negatif, sasaran kehilangan kerosakan sebenar sebanyak 40% daripada Serangan Fizikal Golbat setiap pusingan, maksimum 5 lapisan).',
		describe = 'Golbat opens its mouth as wide as possible and inhales frantically, then spits out a toxic orb into the crowd. The orb explodes and splits into smaller orbs, which continue to explode, dealing Physical Damage #C0xE69900#210% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Physical Damage#C0x5B545B# to the main target and enemies within a cross-shaped area, applying 2 stacks of [Poisoned] to targets in the cross area lasting 3 turns (Poisoned: negative effect, target loses true damage equal to 40% of Golbat\'s Physical Attack each turn, up to 5 stacks).',
		simDesc_vn = 'Golbat há miệng thật to hít vào, sau đó phun ra một quả cầu chứa đầy độc tố vào đám đông, quả cầu nổ tung và phân tách thành nhiều quả cầu nhỏ hơn, tiếp tục nổ, gây sát thương cho mục tiêu hình chữ thập và thêm trạng thái trúng độc.',
		simDesc_en = 'Golbat opens its mouth wide to inhale, then spits out a toxin-filled orb into the crowd. The orb explodes and splits into multiple smaller orbs that continue to burst, dealing damage to cross-shaped targets and inflicting poison status.',
		simDesc_th = 'โกลแบทอ้าปากกว้างเพื่อสูดลมเข้า จากนั้นพ่นลูกบอลที่เต็มไปด้วยพิษใส่ฝูงชน ลูกบอลระเบิดแล้วแตกออกเป็นลูกบอลเล็กๆ หลายลูกที่ระเบิดต่อเนื่อง ทำความเสียหายกับเป้าหมายรูปกากบาทและเพิ่มสถานะติดพิษ',
		simDesc_in = 'Golbat membuka mulutnya lebar-lebar untuk menarik napas, kemudian menyemburkan bola beracun ke kerumunan. Bola itu meledak dan terpecah menjadi beberapa bola kecil yang terus meledak, memberikan kerusakan pada target berbentuk silang dan menimbulkan status racun.',
		simDesc_ph = 'Binuksan ni Golbat nang malaki ang bibig para makahinga, tapos nilalabas ang isang bola na puno ng lason papunta sa karamihan. Pumutok ang bola at nahati-hati sa maraming maliliit na bola na patuloy na sumabog, nagdudulot ng pinsala sa mga target na hugis krus at nagdudulot ng status ng pagkakalason.',
		simDesc_ma = 'Golbat membuka mulutnya luas untuk menyedut, kemudian meludah keluar bola yang penuh dengan toksin ke arah orang ramai. Bola itu meletup dan terbahagi kepada beberapa bola lebih kecil yang terus meletup, menyebabkan kerosakan kepada sasaran berbentuk salib dan menambah status terkena racun.',
		simDesc = 'Golbat opens its mouth wide to inhale, then spits out a toxin-filled orb into the crowd. The orb explodes and splits into multiple smaller orbs that continue to burst, dealing damage to cross-shaped targets and inflicting poison status.',
		starEffect = __data_t__starEffect[1623],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi tấn công mục tiêu đã bị nhiễm độc, thời gian hiệu lực của tất cả các hiệu ứng nhiễm độc trên mục tiêu sẽ được kéo dài thêm 1 lượt.',
		starEffectDesc = 'Additional effect: When attacking a poisoned target, the duration of all poison effects on the target will be extended by 1 turn.',
		starEffectDesc_en = 'Additional effect: When attacking a poisoned target, the duration of all poison effects on the target will be extended by 1 turn.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อโจมตีเป้าหมายที่ถูกพิษ ระยะเวลาของเอฟเฟกต์พิษทั้งหมดบนเป้าหมายจะถูกขยายออกไปอีก 1 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Saat menyerang target yang teracuni, durasi semua efek racun pada target akan diperpanjang 1 giliran.',
