	[1626] = {
		id = 1626,
		skillName_vn = 'Chất độc xúc tác',
		skillName_en = 'Catalytic poison',
		skillName_th = 'พิษเร่งปฏิกิริยา',
		skillName_in = 'Racun katalitik',
		skillName_ph = 'Pamatay na pampagana',
		skillName_ma = 'Racun pemangkin',
		skillName = 'Catalytic poison',
		describe_vn = 'Khi tướng phe ta tấn công mục tiêu bằng kỹ năng nhỏ, có #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# xác suất gây hiệu ứng [Trúng độc] 1 tầng, kéo dài 3 lượt (Trúng độc: Hiệu ứng tiêu cực, mục tiêu mất sát thương thực bằng 40% Công Vật Lý của Dazui Bat trước mỗi lượt, tối đa cộng dồn 5 tầng)\nTướng hệ Độc có xác suất kích hoạt hiệu ứng này tăng thêm 50%',
		describe_en = 'When our faction\'s hero attacks a target with a minor skill, there is a #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# chance to inflict the [Poisoned] effect for 1 stack, lasting 3 turns (Poisoned: A debuff causing the target to lose true damage equal to 40% of Dazui Bat\'s Physical Attack at the start of each turn, stacking up to 5 times).\n Heroes aligned with Poison have a 50% increased chance to trigger this effect.',
		describe_th = 'เมื่อจอมพลฝ่ายเราทำการโจมตีเป้าหมายด้วยทักษะเล็ก จะมีโอกาส #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# ที่จะทำให้เกิดเอฟเฟกต์ [ถูกพิษ] 1 ชั้น เป็นระยะเวลา 3 เทิร์น (ถูกพิษ: ผลกระทบเชิงลบ ทำให้เป้าหมายสูญเสียดาเมจจริงเท่ากับ 40% ของพลังโจมตีทางกายภาพของ Dazui Bat ก่อนเริ่มเทิร์นแต่ละรอบ สะสมได้สูงสุด 5 ชั้น) \n ฮีโร่สายพิษมีโอกาสเพิ่มขึ้น 50% ในการกระตุ้นเอฟเฟกต์นี้',
		describe_in = 'Saat pahlawan pihak kita menyerang target dengan skill kecil, terdapat #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# peluang untuk menyebabkan efek [Terkontaminasi Racun] 1 tumpukan, berlangsung selama 3 giliran (Terkontaminasi Racun: Efek negatif yang membuat target kehilangan damage asli sebesar 40% Serangan Fisik Dazui Bat sebelum setiap giliran, maksimal bertumpuk hingga 5 tumpukan) \n Pahlawan dengan elemen Racun memiliki peluang 50% lebih tinggi untuk mengaktifkan efek ini.',
		describe_ph = 'Kapag ang bayani ng ating panig ay umatake sa target gamit ang maliit na kasanayan, may #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# posibilidad na magdulot ng epekto na [Na-pekto ng Lason] 1 patong, tumatagal ng 3 turn (Na-pekto ng Lason: Isang negatibong epekto kung saan nawawala ang tunay na pinsala ng target ng katumbas ng 40% ng Pisikal na Atake ni Dazui Bat bago mag-umpisa ang bawat turn, hanggang 5 patong ang maaaring ipon) \n Ang mga bayani na may elementong Lason ay may 50% dagdag na posibilidad na ma-trigger ang epekto na ito.',
		describe_ma = 'Apabila wira pihak kita menyerang sasaran menggunakan kemahiran kecil, terdapat #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# peluang untuk menyebabkan kesan [Tercemar Racun] 1 lapisan, berpanjangan selama 3 pusingan (Tercemar Racun: Kesan negatif yang membuat sasaran kehilangan kerosakan sebenar sebanyak 40% Serangan Fizikal Dazui Bat sebelum setiap pusingan, boleh bertindih sehingga 5 lapisan) \n Wira bertemakan Racun mempunyai peluang bertambah 50% untuk mengaktifkan kesan ini.',
		describe = 'When our faction\'s hero attacks a target with a minor skill, there is a #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# chance to inflict the [Poisoned] effect for 1 stack, lasting 3 turns (Poisoned: A debuff causing the target to lose true damage equal to 40% of Dazui Bat\'s Physical Attack at the start of each turn, stacking up to 5 times).\n Heroes aligned with Poison have a 50% increased chance to trigger this effect.',
		starEffect = __data_t__starEffect[1626],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sau mỗi lần tấn công không phải kỹ năng tuyệt chiêu, sẽ sao chép hiệu ứng nhiễm độc từ mục tiêu bị tấn công sang một mục tiêu ngẫu nhiên bên địch (ưu tiên chọn đơn vị chưa bị nhiễm độc).',
		starEffectDesc = 'Additional effect: After each attack that is not an ultimate skill, the poison effect from the attacked target will be copied to a random enemy target (prioritizing units not yet poisoned).',
		starEffectDesc_en = 'Additional effect: After each attack that is not an ultimate skill, the poison effect from the attacked target will be copied to a random enemy target (prioritizing units not yet poisoned).',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: หลังจากการโจมตีแต่ละครั้งที่ไม่ใช่สกิลอัลติเมท จะคัดลอกเอฟเฟกต์พิษจากเป้าหมายที่ถูกโจมตีไปยังเป้าหมายศัตรูแบบสุ่ม (ให้เลือกหน่วยที่ยังไม่ถูกพิษก่อน)',
		starEffectDesc_in = 'Efek tambahan: Setelah setiap serangan yang bukan skill ultimat, akan menyalin efek racun dari target yang diserang ke target musuh acak (memprioritaskan unit yang belum teracuni).',
		starEffectDesc_ph = 'Karagdagang epekto: Pagkatapos ng bawat pag-atake na hindi ultimate skill, kokopyahin ang poison effect mula sa tinarget na kalaban papunta sa isang random na target na kalaban (binibigyang prayoridad ang mga yunit na hindi pa nalalason).',
		starEffectDesc_ma = 'Kesan tambahan: Selepas setiap serangan yang bukan kemahiran utama, akan menyalin kesan racun dari sasaran yang diserang ke sasaran musuh rawak (mengutamakan unit yang belum terkena racun).',
		zawakeEffect = __data_t__zawakeEffect[1626],
		-- {79004}
		zawakeEffectDesc = 'When our faction heroes use minor skills to attack targets, there is a #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# chance to apply 1 layer of Poison effect, lasting 3 turns (Poison: a negative effect causing the target to lose True Damage equal to 40% of the Bat Demon\'s Physical Attack each turn, stacking up to 5 layers)\nThe activation chance of this effect for Poison-type heroes is increased by 100%',
		zawakeEffectDesc_en = 'When our faction heroes use minor skills to attack targets, there is a #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# chance to apply 1 layer of Poison effect, lasting 3 turns (Poison: a negative effect causing the target to lose True Damage equal to 40% of the Bat Demon\'s Physical Attack each turn, stacking up to 5 layers)\nThe activation chance of this effect for Poison-type heroes is increased by 100%',
		zawakeEffectDesc_th = 'เมื่อฮีโร่ฝ่ายเราส่งใช้สกิลเล็กโจมตีเป้าหมาย มีโอกาส #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# ที่จะติดเอฟเฟกต์พิษ 1 ชั้น เป็นเวลา 3 เทิร์น (พิษ: เอฟเฟกต์ลบ ทำให้เป้าหมายเสียดาเมจจริงเท่ากับ 40% ของพลังโจมตีทางกายภาพของค้างคาวปีศาจในแต่ละเทิร์น ติดสะสมได้สูงสุด 5 ชั้น)\nโอกาสยิ่งเปิดใช้งานเอฟเฟกต์นี้ของฮีโร่สายพิษเพิ่มขึ้นอีก 100%',
		zawakeEffectDesc_in = 'Ketika pahlawan pihak kita menggunakan keterampilan kecil untuk menyerang target, ada #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# peluang untuk menambahkan 1 lapisan efek Racun, berlangsung selama 3 giliran (Racun: efek negatif, target kehilangan Damage Sebenarnya sebesar 40% dari Serangan Fisik Bat Demon setiap giliran, bisa menumpuk hingga 5 lapisan)\nPeluang untuk mengaktifkan efek ini bagi pahlawan tipe Racun meningkat sebanyak 100%',
		zawakeEffectDesc_ph = 'Kapag ginamit ng ating mga bayani ang maliit na kasanayan upang atakihin ang target, may #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# pagkakataon na magdagdag ng 1 layer ng Poison effect, tumatagal ng 3 turn (Poison: negatibong epekto na nagdudulot sa target na mawalan ng totoong pinsala na katumbas ng 40% ng Physical Attack ng Bat Demon bawat turn, maaaring maka-stack hanggang 5 layers)\nTumaas ng 100% ang pagkakataon ng mga Poison-type na bayani na ma-activate ang epekto na ito',
		zawakeEffectDesc_ma = 'Apabila wira pihak kita menggunakan kemahiran kecil untuk menyerang sasaran, terdapat #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# peluang disertakan 1 lapisan kesan Racun, berlangsung selama 3 pusingan (Racun: kesan negatif, sasaran kehilangan kerosakan sebenar sebanyak 40% Serangan Fizikal Iblis Kelawar setiap pusingan, maksimum bertindih sehingga 5 lapisan)\nPeluang untuk mengaktifkan kesan ini bagi wira jenis Racun meningkat sebanyak 100%',
		zawakeEffectDesc_vn = 'Khi các anh hùng phe ta sử dụng kỹ năng nhỏ tấn công mục tiêu, có #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# xác suất kèm theo 1 tầng hiệu ứng Độc, kéo dài 3 lượt (Độc: hiệu ứng tiêu cực, mục tiêu mất sát thương thực bằng 40% Công Vật Lý của Dơi Quỷ mỗi lượt, tối đa cộng dồn 5 tầng)\nXác suất kích hoạt hiệu ứng này của anh hùng hệ Độc tăng thêm 100%',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Poison-element heroes have 50% increased chance to trigger this effect\n#F20# \n#F40##C0x5c9970#→ Poison-element heroes have 100% increased chance to trigger this effect',
		zawakeSimpleDesc_en = 'Poison-element heroes have 50% increased chance to trigger this effect\n#F20# \n#F40##C0x5c9970#→ Poison-element heroes have 100% increased chance to trigger this effect',
		zawakeSimpleDesc_th = 'ฮีโร่ธาตุพิษมีโอกาสเปิดใช้งานเอฟเฟกต์นี้เพิ่มขึ้น 50%\n#F20# \n#F40##C0x5c9970#→ ฮีโร่ธาตุพิษมีโอกาสเปิดใช้งานเอฟเฟกต์นี้เพิ่มขึ้น 100%',
		zawakeSimpleDesc_in = 'Pahlawan elemen racun memiliki peluang 50% lebih tinggi untuk memicu efek ini\n#F20# \n#F40##C0x5c9970#→ Pahlawan elemen racun memiliki peluang 100% lebih tinggi untuk memicu efek ini',
