	[1636] = {
		id = 1636,
		skillName_vn = 'Diêm vương dễ thương',
		skillName_en = 'Cute Lord of the Underworld',
		skillName_th = 'เจ้าแห่งยมทูตน่ารัก',
		skillName_in = 'Penguasa Neraka yang Imut',
		skillName_ph = 'Cute na Hari ng Kamatayan',
		skillName_ma = 'Tuan Neraka yang Comel',
		skillName = 'Cute Lord of the Underworld',
		describe_vn = 'Khi tướng phe ta tấn công mục tiêu bằng kỹ năng nhỏ, có #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# xác suất gây hiệu ứng [Trúng độc] 1 tầng, kéo dài 3 lượt (Trúng độc: Hiệu ứng tiêu cực, mục tiêu mất sát thương thực bằng 40% Công Vật Lý của Kagura trước mỗi lượt, tối đa cộng dồn 5 tầng)\nTướng hệ Độc có xác suất kích hoạt hiệu ứng này tăng thêm 50%',
		describe_en = 'When our faction\'s hero attacks a target with a minor skill, there is a #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# chance to inflict a [Poison Hit] stack, lasting 3 turns. (Poison Hit: A negative effect causing the target to lose true damage equal to 40% of Kagura\'s Physical Attack before each turn, stacking up to 5 layers.) \n Heroes with the Poison affinity have a 50% increased chance to trigger this effect.',
		describe_th = 'เมื่อจอมพลฝ่ายของเราทำการโจมตีเป้าหมายด้วยสกิลเล็ก จะมีโอกาส #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# ในการทำให้เกิดเอฟเฟกต์ [ติดพิษ] 1 ชั้น เป็นเวลานาน 3 เทิร์น (ติดพิษ: ผลลบ เป้าหมายจะเสียความเสียหายจริง เท่ากับ 40% ของพลังโจมตีทางกายภาพของคากุระ ก่อนแต่ละเทิร์น สะสมได้สูงสุด 5 ชั้น) \n จอมพลระบบพิษจะมีโอกาสเพิ่มขึ้น 50% ในการเปิดใช้เอฟเฟกต์นี้',
		describe_in = 'Ketika pahlawan dari pihak kita menyerang target dengan keterampilan kecil, ada peluang #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# untuk menyebabkan efek [Terkena Racun] 1 tumpukan, berlangsung selama 3 giliran. (Terkena Racun: efek negatif, target kehilangan damage nyata sebesar 40% dari Serangan Fisik Kagura sebelum setiap giliran, maksimal bertumpuk hingga 5 tumpukan) \n Pahlawan dengan afinitas Racun memiliki peluang kena efek ini bertambah 50%.',
		describe_ph = 'Kapag ang bayani ng aming panig ay umatake sa target gamit ang maliit na kasanayan, may #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# pagkakataon na magdulot ng epekto ng [Na-poison] na 1 stack, tumatagal ng 3 turn. (Na-poison: Isang negatibong epekto, nawawala ang tunay na pinsala ng target ng katumbas ng 40% ng Pisikal na Atake ni Kagura bago ang bawat turn, hanggang 5 stack na puwedeng mag-ipon) \n Ang mga bayani na may Poison system ay may dagdag na 50% na posibilidad na ma-activate ang epektong ito.',
		describe_ma = 'Apabila wira dari pihak kita menyerang sasaran menggunakan kemahiran kecil, terdapat peluang sebanyak #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# untuk menyebabkan kesan [Terkena Racun] 1 lapisan, bertahan selama 3 pusingan. (Terkena Racun: kesan negatif, sasaran kehilangan kerosakan sebenar sebanyak 40% Serangan Fizikal Kagura sebelum setiap pusingan, maksimum terkumpul 5 lapisan) \n Wira sistem Racun mempunyai peluang 50% lebih tinggi untuk mengaktifkan kesan ini.',
		describe = 'When our faction\'s hero attacks a target with a minor skill, there is a #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# chance to inflict a [Poison Hit] stack, lasting 3 turns. (Poison Hit: A negative effect causing the target to lose true damage equal to 40% of Kagura\'s Physical Attack before each turn, stacking up to 5 layers.) \n Heroes with the Poison affinity have a 50% increased chance to trigger this effect.',
		starEffect = __data_t__starEffect[1636],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sau mỗi lần tấn công không phải kỹ năng tuyệt chiêu, sẽ sao chép hiệu ứng nhiễm độc từ mục tiêu bị tấn công sang một mục tiêu ngẫu nhiên bên địch (ưu tiên chọn đơn vị chưa bị nhiễm độc).',
		starEffectDesc = 'Additional effect: After each normal attack (excluding special skill), it will copy the poison effect from the attacked target to a random enemy target (prioritizing units not yet poisoned).',
		starEffectDesc_en = 'Additional effect: After each normal attack (excluding special skill), it will copy the poison effect from the attacked target to a random enemy target (prioritizing units not yet poisoned).',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: หลังจากการโจมตีแต่ละครั้งที่ไม่ใช่ทักษะพิเศษ จะคัดลอกผลพิษจากเป้าหมายที่ถูกโจมตีไปยังเป้าหมายฝ่ายตรงข้ามแบบสุ่ม (ให้ความสำคัญกับหน่วยที่ยังไม่ถูกพิษก่อน).',
		starEffectDesc_in = 'Efek tambahan: Setelah setiap serangan biasa (bukan skill spesial), akan menyalin efek racun dari target yang diserang ke target musuh acak (memprioritaskan unit yang belum teracuni).',
		starEffectDesc_ph = 'Karagdagang epekto: Pagkatapos ng bawat normal na pag-atake (hindi kabilang ang espesyal na kasanayan), kokopyahin nito ang epekto ng lason mula sa inatakeng target papunta sa isang random na kalaban (binibigyang prayoridad ang yunit na hindi pa nalalason).',
		starEffectDesc_ma = 'Kesan tambahan: Selepas setiap serangan biasa (bukan kemahiran istimewa), ia akan menyalin kesan racun daripada sasaran yang diserang ke sasaran musuh rawak (mengutamakan unit yang belum dijangkiti racun).',
		zawakeEffect = __data_t__zawakeEffect[1636],
		-- {79004}
		zawakeEffectDesc = 'When our heroes use minor skills to attack targets, there is a #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# chance to apply 1 layer of Poison effect lasting 3 turns (Poison: negative effect, target loses true damage equal to 40% of Kagura\'s Physical Attack each turn, stacking up to 5 layers)\nThe activation chance of this effect is increased by 100% for Poison-type heroes',
		zawakeEffectDesc_en = 'When our heroes use minor skills to attack targets, there is a #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# chance to apply 1 layer of Poison effect lasting 3 turns (Poison: negative effect, target loses true damage equal to 40% of Kagura\'s Physical Attack each turn, stacking up to 5 layers)\nThe activation chance of this effect is increased by 100% for Poison-type heroes',
		zawakeEffectDesc_th = 'เมื่อฮีโร่ฝ่ายเราใช้สกิลเล็กโจมตีเป้าหมาย มีโอกาส #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# ที่จะทำให้เกิดชั้นผลลัพธ์พิษ 1 ชั้น มีผลต่อเนื่อง 3 เทิร์น (พิษ: ผลเสีย, เป้าหมายสูญเสียความเสียหายจริงเท่ากับ 40% ของพลังโจมตีทางกายภาพของ Kagura ในแต่ละเทิร์น สูงสุดสะสมได้ 5 ชั้น)\nโอกาสในการเปิดใช้งานเอฟเฟกต์นี้ของฮีโร่ระบบพิษเพิ่มขึ้น 100%',
		zawakeEffectDesc_in = 'Saat pahlawan kita menggunakan skill kecil untuk menyerang target, ada #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# peluang untuk menambahkan 1 lapis efek Racun selama 3 giliran (Racun: efek negatif, target kehilangan kerusakan nyata sebesar 40% Serangan Fisik Kagura setiap giliran, maksimal bertumpuk hingga 5 lapis)\nPeluang aktivasi efek ini dari pahlawan tipe Racun meningkat 100%',
		zawakeEffectDesc_ph = 'Kapag ang aming mga bayani ay gumagamit ng maliit na kasanayan upang atakihin ang target, may #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# pagkakataon na may 1 layer ng Epekto ng Poison na tatagal ng 3 turn (Poison: negatibong epekto, ang target ay nawawalan ng totoong pinsala na katumbas ng 40% ng Physical Attack ni Kagura bawat turn, max na maaaring ma-stack ay 5 layers)\nAng chance ng pag-activate ng effect na ito para sa mga poison-type na bayani ay nadagdagan ng 100%',
		zawakeEffectDesc_ma = 'Apabila wira kami menggunakan kemahiran kecil untuk menyerang sasaran, terdapat peluang #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# untuk menambah 1 lapisan kesan Racun selama 3 pusingan (Racun: kesan negatif, sasaran kehilangan kerosakan sebenar sebanyak 40% Serangan Fizikal Kagura setiap pusingan, maksimum terkumpul 5 lapisan)\nPeluang pengaktifan kesan ini oleh wira jenis Racun meningkat sebanyak 100%',
		zawakeEffectDesc_vn = 'Khi các anh hùng phe ta sử dụng kỹ năng nhỏ tấn công mục tiêu, có #C0x5c9970#$(25+skillLevel*0.25-0.25)$%#C0x5B545B# xác suất kèm theo 1 tầng hiệu ứng Độc, kéo dài 3 lượt (Độc: hiệu ứng tiêu cực, mục tiêu mất sát thương thực bằng 40% Công Vật Lý của Kagura mỗi lượt, tối đa cộng dồn 5 tầng)\nXác suất kích hoạt hiệu ứng này của anh hùng hệ Độc tăng thêm 100%',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Poison-element heroes have 50% increased chance to trigger this effect\n#F20# \n#F40##C0x5c9970#→ Poison-element heroes have 100% increased chance to trigger this effect',
		zawakeSimpleDesc_en = 'Poison-element heroes have 50% increased chance to trigger this effect\n#F20# \n#F40##C0x5c9970#→ Poison-element heroes have 100% increased chance to trigger this effect',
		zawakeSimpleDesc_th = 'ฮีโร่ธาตุพิษมีโอกาสเปิดใช้งานเอฟเฟกต์นี้เพิ่มขึ้น 50%\n#F20# \n#F40##C0x5c9970#→ ฮีโร่ธาตุพิษมีโอกาสเปิดใช้งานเอฟเฟกต์นี้เพิ่มขึ้น 100%',
		zawakeSimpleDesc_in = 'Pahlawan elemen racun memiliki peluang 50% lebih tinggi untuk memicu efek ini\n#F20# \n#F40##C0x5c9970#→ Pahlawan elemen racun memiliki peluang 100% lebih tinggi untuk memicu efek ini',
		zawakeSimpleDesc_ph = 'Mas mataas ng 50% ang tsansa ng mga bayani ng elementong lason na i-activate ang effect na ito\n#F20# \n#F40##C0x5c9970#→ Mas mataas ng 100% ang tsansa ng mga bayani ng elementong lason na i-activate ang effect na ito',
		zawakeSimpleDesc_ma = 'Wira elemen racun mempunyai 50% peluang tambahan untuk mengaktifkan kesan ini\n#F20# \n#F40##C0x5c9970#→ Wira elemen racun mempunyai 100% peluang tambahan untuk mengaktifkan kesan ini',
		zawakeSimpleDesc_vn = 'Xác suất kích hoạt hiệu ứng này của anh hùng hệ độc tăng thêm 50%\n#F20# \n#F40##C0x5c9970#→ Xác suất kích hoạt hiệu ứng này của anh hùng hệ độc tăng thêm 100%',
