	[1913] = {
		id = 1913,
		skillName_vn = 'Răng độc hút máu',
		skillName_en = 'Vampire fangs',
		skillName_th = 'เขี้ยวดูดเลือด',
		skillName_in = 'Taring vampir',
		skillName_ph = 'Pangil na sumisipsip ng dugo',
		skillName_ma = 'Taring pontianak',
		skillName = 'Vampire fangs',
		describe_vn = 'Quả cầu lông kích hoạt chức năng radar của mắt kép, chính xác tìm ra vị trí kẻ địch, tham lam và điên cuồng hút máu mục tiêu đơn lẻ của kẻ địch, gây ra #C0xE69900#430% Công Vật Lý#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, sát thương lần này kèm theo 30% hút máu, và vĩnh viễn cướp 8% Công Vật Lý và Công Phép của mục tiêu (mỗi lần cướp không vượt quá 40% thuộc tính của bản thân, tối đa cộng dồn 3 tầng)',
		describe_en = 'The shuttlecock activates the dual-eye radar function, accurately locating enemy positions, greedily and frantically draining the blood of a single enemy target, dealing #C0xE69900#430% Physical Attack#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Physical Damage#C0x5B545B#. This damage comes with 30% lifesteal and permanently steals 8% Physical Attack and Magic Power from the target (each steal cannot exceed 40% of the user\'s own attributes, stacking up to 3 layers).',
		describe_th = 'ลูกขนไก่เปิดใช้งานฟังก์ชันเรดาร์ตาของตาคู่ ค้นหาตำแหน่งศัตรูได้อย่างแม่นยำ ดูดเลือดเป้าหมายศัตรูเดี่ยวอย่างโลภและคลั่งไคล้ สร้างความเสียหายทางกายภาพ #C0xE69900#430%#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ความเสียหายครั้งนี้มาพร้อมกับการดูดเลือด 30% และขโมยพลังโจมตีทางกายภาพและเวทมนตร์จากเป้าหมายถาวร 8% (การขโมยแต่ละครั้งไม่เกิน 40% ของค่าคุณสมบัติของตัวเอง สะสมได้สูงสุด 3 ชั้น)',
		describe_in = 'Shuttlecock mengaktifkan fungsi radar mata ganda, dengan tepat menemukan posisi musuh, rakus dan gila menghisap darah satu target musuh, menyebabkan #C0xE69900#430% Serangan Fisik#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Damage Fisik#C0x5B545B#. Damage ini disertai dengan 30% lifesteal, dan secara permanen mencuri 8% Serangan Fisik dan Kekuatan Sihir dari target (setiap pencurian tidak melebihi 40% atribut milik sendiri, dapat terakumulasi hingga 3 lapis).',
		describe_ph = 'Ang bola ng shuttlecock ay nag-activate ng dual-eye radar function, eksaktong hinahanap ang posisyon ng kalaban, sakim at baliw na sumisipsip ng dugo mula sa isang pangunahing target ng kalaban, nagdudulot ng #C0xE69900#430% Physical Attack#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Physical Damage#C0x5B545B#. Kasama sa damage na ito ang 30% lifesteal, at permanenteng nananakaw ng 8% Physical Attack at Magic Power mula sa target (ang bawat pagnanakaw ay hindi lalagpas sa 40% ng sariling attributes, hanggang tatlong stack ang pwedeng maipon).',
		describe_ma = 'Buluh takraw mengaktifkan fungsi radar mata berganda, tepat mengesan kedudukan musuh, tamak dan gilakan penyedutan darah dari satu sasaran musuh, menyebabkan #C0xE69900#430% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Kerosakan kali ini disertakan dengan 30% penyedutan darah, dan secara kekal mencuri 8% Serangan Fizikal dan Kuasa Sihir dari sasaran (setiap pencurian tidak melebihi 40% atribut diri sendiri, maksimum terkumpul 3 lapisan).',
		describe = 'The shuttlecock activates the dual-eye radar function, accurately locating enemy positions, greedily and frantically draining the blood of a single enemy target, dealing #C0xE69900#430% Physical Attack#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Physical Damage#C0x5B545B#. This damage comes with 30% lifesteal and permanently steals 8% Physical Attack and Magic Power from the target (each steal cannot exceed 40% of the user\'s own attributes, stacking up to 3 layers).',
		simDesc_vn = 'Mao Cầu kích hoạt chức năng radar của mắt kép, chính xác tìm vị trí của đối phương, tham lam và điên cuồng hút máu từ mục tiêu đơn lẻ của đối phương, sát thương kèm theo hiệu ứng hút máu và đánh cắp chỉ số tấn công của mục tiêu.',
		simDesc_en = 'Mao activates the dual-eye radar function, precisely locating the opponent, greedily and frantically draining blood from a single target, dealing damage accompanied by a lifesteal effect and stealing the target\'s attack stats.',
		simDesc_th = 'เการุเปิดใช้งานฟังก์ชันเรดาร์ของดวงตาคู่ ค้นหาตำแหน่งของศัตรูอย่างแม่นยำ ดูดเลือดจากเป้าหมายเดียวอย่างโลภและบ้าคลั่ง สร้างความเสียหายพร้อมกับเอฟเฟกต์ดูดเลือดและขโมยค่าสถานะการโจมตีของเป้าหมาย',
		simDesc_in = 'Mao mengaktifkan fungsi radar mata ganda, secara tepat menemukan posisi lawan, dengan serakah dan gila menghisap darah dari satu target lawan, memberikan kerusakan disertai efek penghisapan darah dan mencuri statistik serangan target.',
		simDesc_ph = 'Ina-activate ni Mao ang dual-eye radar function, tumpak na hinahanap ang posisyon ng kalaban, sakim at baliw na sumisipsip ng dugo mula sa isang layuning kalaban, na may kasamang pinsalang may lifesteal effect at pagnanakaw ng attack stats ng target.',
		simDesc_ma = 'Mao mengaktifkan fungsi radar mata berkembar, tepat mengesan lokasi musuh, tamak dan ghairah menyedut darah dari sasaran tunggal musuh, memberikan kerosakan berserta kesan sedutan darah dan mencuri statistik serangan sasaran.',
		simDesc = 'Mao activates the dual-eye radar function, precisely locating the opponent, greedily and frantically draining blood from a single target, dealing damage accompanied by a lifesteal effect and stealing the target\'s attack stats.',
		starEffect = __data_t__starEffect[1913],
