	[1923] = {
		id = 1923,
		skillName_vn = 'Vũ điệu bướm chết người',
		skillName_en = 'Deadly butterfly dance',
		skillName_th = 'เต้นรำผีเสื้ออันตราย',
		skillName_in = 'Tarian kupu-kupu mematikan',
		skillName_ph = 'Nakakahalay na sayaw ng paru-paro',
		skillName_ma = 'Tarian rama-rama maut',
		skillName = 'Deadly butterfly dance',
		describe_vn = 'Bướm đêm Moru sử dụng điệu nhảy rực rỡ để mê hoặc kẻ địch, sau đó bất ngờ cắn và hút máu mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#440% Công Phép#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, sát thương lần này kèm theo 30% hút máu, và vĩnh viễn cướp 8% Công Vật Lý và Công Phép của mục tiêu (mỗi lần cướp không vượt quá 40% thuộc tính của bản thân, tối đa cộng dồn 3 tầng)',
		describe_en = 'Moru the Moth uses a dazzling dance to charm enemies, then suddenly bites and drains the blood of a single enemy target, dealing #C0x3D8A99#440% Magic Power#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Magic Damage #C0x5B545B#. This damage includes 30% lifesteal and permanently steals 8% Physical Attack and Magic Power from the target (each steal cannot exceed 40% of Moru\'s own stats, stacking up to 3 times).',
		describe_th = 'มนุษย์ผีเสื้อ Moru ใช้การเต้นรำที่สวยงามเพื่อสะกดจิตศัตรู จากนั้นจู่โจมด้วยการกัดและดูดเลือดเป้าหมายเดี่ยวของศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#440%#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# พร้อมกับดูดเลือด 30% และขโมยพลังโจมตีทางกายภาพและเวทมนตร์ของเป้าหมายถาวร 8% (การขโมยแต่ละครั้งไม่เกิน 40% ของค่าสถานะของ Moru เอง สะสมได้สูงสุด 3 ชั้น)',
		describe_in = 'Ngengat Malam Moru menggunakan tarian yang gemilang untuk mempesona musuh, lalu tiba-tiba menggigit dan mengisap darah dari satu target musuh, menyebabkan #C0x3D8A99#440% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Kerusakan ini disertai dengan 30% pencurian darah, dan secara permanen mencuri 8% Serangan Fisik dan Kekuatan Sihir dari target (setiap pencurian tidak melebihi 40% atribut Moru sendiri, dapat menumpuk hingga 3 tingkat).',
		describe_ph = 'Gumagambala ng Paruparo na Moru ang isang makulay na sayaw upang hipnotisin ang kalaban, pagkatapos ay biglang kagatin at sipsipin ang dugo ng isang kalaban, nagdudulot ng #C0x3D8A99#440% Lakas ng Mahika#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Pinsalang Mahika #C0x5B545B#. Kasama sa pinsalang ito ang 30% lifesteal, at permanenteng ninanakaw ang 8% Pisikal na Atake at Lakas ng Mahika ng target (bawat pagnanakaw ay hindi lalampas sa 40% ng sariling katangian ni Moru, na maaaring maipon hanggang 3 beses).',
		describe_ma = 'Kupu-kupu malam Moru menggunakan tarian yang memukau untuk memikat musuh, kemudian tiba-tiba menggigit dan menghisap darah satu sasaran musuh, menyebabkan #C0x3D8A99#440% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Kerosakan ini disertai dengan 30% hisap darah, dan secara kekal mencuri 8% Serangan Fizikal dan Kuasa Sihir daripada sasaran (setiap pencurian tidak melebihi 40% atribut Moru sendiri, boleh bertimbun sehingga 3 peringkat).',
		describe = 'Moru the Moth uses a dazzling dance to charm enemies, then suddenly bites and drains the blood of a single enemy target, dealing #C0x3D8A99#440% Magic Power#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Magic Damage #C0x5B545B#. This damage includes 30% lifesteal and permanently steals 8% Physical Attack and Magic Power from the target (each steal cannot exceed 40% of Moru\'s own stats, stacking up to 3 times).',
		simDesc_vn = 'Mothim dùng điệu nhảy rực rỡ để làm cho đối phương mê hoặc, sau đó bất ngờ cắn và hút máu từ mục tiêu đơn lẻ của đối phương, sát thương kèm theo hiệu ứng hút máu và đánh cắp chỉ số tấn công của mục tiêu.',
		simDesc_en = 'Mothim uses a dazzling dance to mesmerize the opponent, then suddenly bites and drains blood from a single target, dealing damage with a lifesteal effect and stealing the target\'s attack stat.',
		simDesc_th = 'Mothim ใช้การเต้นรำที่สดใสเพื่อสะกดจิตคู่ต่อสู้ จากนั้นจู่โจมด้วยการขบกัดและดูดเลือดจากเป้าหมายเดียว สร้างความเสียหายพร้อมกับเอฟเฟกต์ดูดเลือดและขโมยค่าสถานะพลังโจมตีของเป้าหมาย',
		simDesc_in = 'Mothim menggunakan tarian yang memukau untuk mempesona lawan, kemudian tiba-tiba menggigit dan mengisap darah dari satu target lawan, memberikan kerusakan dengan efek pengisapan darah dan mencuri status serangan target.',
		simDesc_ph = 'Gumagamit si Mothim ng kahanga-hangang sayaw upang maakit ang kalaban, pagkatapos ay biglang kumagat at sumipsip ng dugo mula sa isang target ng kalaban, na nagdudulot ng pinsala kasama ang epekto ng pag-sipsip ng buhay at pagnanakaw ng attack stat ng target.',
		simDesc_ma = 'Mothim menggunakan tarian yang memukau untuk mempesonakan musuh, kemudian secara tiba-tiba menggigit dan menghisap darah dari satu sasaran musuh, memberikan kerosakan dengan kesan hisap nyawa dan mencuri statistik serangan sasaran.',
		simDesc = 'Mothim uses a dazzling dance to mesmerize the opponent, then suddenly bites and drains blood from a single target, dealing damage with a lifesteal effect and stealing the target\'s attack stat.',
		starEffect = __data_t__starEffect[1923],
