		skillName_in = 'Kekuatan spiritual',
		skillName_ph = 'Lakas ng espiritu',
		skillName_ma = 'Kekuatan rohani',
		skillName = 'Spiritual power',
		describe_vn = 'Vịt Koduck bất ngờ sử dụng năng lực tâm linh, gây ra #C0x3D8A99#100% Công Phép#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# lên mục tiêu đơn lẻ của kẻ địch, khi chưa đầy nộ khí, tăng 200 nộ khí cho bản thân; khi đầy nộ khí, sẽ chuyển 200 nộ khí cho một đồng đội ngẫu nhiên',
		describe_en = 'Koduck suddenly uses spiritual power, causing #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Magic Damage#C0x5B545B# to a single enemy target. If anger is below full, increases own anger by 200; if anger is full, transfers 200 anger to a random ally.',
		describe_th = 'Koduck ใช้พลังจิตกะทันหัน สร้างความเสียหาย #C0x3D8A99#100% พลังเวท#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# ต่อเป้าหมายศัตรูหนึ่งตัว เมื่อพลังโกรธยังไม่เต็ม เพิ่มพลังโกรธของตัวเอง 200 หากพลังโกรธเต็ม จะโอนพลังโกรธ 200 ไปยังเพื่อนร่วมทีมแบบสุ่ม',
		describe_in = 'Koduck tiba-tiba menggunakan kekuatan spiritual, menyebabkan #C0x3D8A99#100% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B# pada satu target musuh tunggal. Jika amarah belum penuh, menambah 200 amarah pada diri sendiri; jika amarah penuh, akan mengalihkan 200 amarah ke sekutu acak.',
		describe_ph = 'Biglang ginamit ni Koduck ang kanyang espiritwal na kakayahan, na nagdudulot ng #C0x3D8A99#100% Kapangyarihan ng Mahika#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Pinsala mula sa Mahika #C0x5B545B# sa isang kalabang target. Kapag hindi pa puno ang galit, nadaragdagan ng 200 ang kanyang sariling galit; kapag puno na ang galit, ililipat niya ang 200 galit sa isang random na kakampi.',
		describe_ma = 'Koduck tiba-tiba menggunakan kuasa spiritual, menyebabkan #C0x3D8A99#100% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Kecederaan Sihir #C0x5B545B# ke satu sasaran musuh tunggal. Apabila belum mencapai kemarahan penuh, menambah 200 kemarahan kepada diri sendiri; apabila kemarahan penuh, akan memindahkan 200 kemarahan kepada rakan sepasukan secara rawak.',
		describe = 'Koduck suddenly uses spiritual power, causing #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Magic Damage#C0x5B545B# to a single enemy target. If anger is below full, increases own anger by 200; if anger is full, transfers 200 anger to a random ally.',
		zawakeEffect = __data_t__zawakeEffect[2212],
		-- {79002}
		zawakeEffectDesc = 'Psyduck uses psychic power in a strange way, dealing magic damage #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54# magic damage#C0x5B545B# to a single enemy target, when rage is not full, increases own rage by 300; when full rage, transfers 200 rage to a random ally unit.',
		zawakeEffectDesc_en = 'Psyduck uses psychic power in a strange way, dealing magic damage #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54# magic damage#C0x5B545B# to a single enemy target, when rage is not full, increases own rage by 300; when full rage, transfers 200 rage to a random ally unit.',
		zawakeEffectDesc_th = 'Psyduck ใช้พลังจิตในวิธีแปลก ๆ ก่อความเสียหายเวทย์ #C0x3D8A99#100% พลังเวท#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54# ความเสียหายเวทย์#C0x5B545B# ไปยังเป้าหมายศัตรูเดี่ยว เมื่อยังไม่เต็มความโกรธ เพิ่มความโกรธของตัวเอง 300 เมื่อเต็มความโกรธ จะส่งต่อความโกรธ 200 ให้กับหน่วยพันธมิตรแบบสุ่ม',
		zawakeEffectDesc_in = 'Psyduck menggunakan kekuatan psikis dengan cara aneh, memberikan damage magic #C0x3D8A99#100% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54# damage magic#C0x5B545B# ke target musuh tunggal, saat belum penuh amarah, meningkatkan amarah sendiri sebesar 300; saat amarah penuh, akan mentransfer 200 amarah ke satu unit sekutu secara acak',
		zawakeEffectDesc_ph = 'Gumagamit si Psyduck ng kakaibang kakayahang pang-isip, na nagdudulot ng magic damage #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54# magic damage#C0x5B545B# sa isang kalaban na target, kapag hindi pa puno ang galit, nadaragdagan ang sariling galit ng 300; kapag puno na ang galit, maglilipat ng 200 galit sa isang random na kaalyado',
		zawakeEffectDesc_ma = 'Psyduck menggunakan kuasa psikik dengan cara yang aneh, menyebabkan kerosakan magik #C0x3D8A99#100% Kuasa Magik#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54# kerosakan magik#C0x5B545B# kepada sasaran musuh tunggal, apabila marah belum penuh, meningkatkan marah sendiri sebanyak 300; apabila marah penuh, akan memindahkan 200 marah kepada satu unit sekutu secara rawak',
		zawakeEffectDesc_vn = 'Psyduck sử dụng năng lực tâm linh một cách kỳ lạ, gây sát thương phép #C0x3D8A99#100% Công Phép#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54# sát thương phép#C0x5B545B# lên mục tiêu đơn lẻ của kẻ địch, khi chưa đầy nộ, tăng 300 nộ khí của bản thân; khi đầy nộ, sẽ truyền 200 nộ khí cho một đơn vị phe ta ngẫu nhiên',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'When Rage is not full, gain 200 Rage\n#F20# \n#F40##C0x5c9970#→ When Rage is not full, gain 300 Rage  ',
		zawakeSimpleDesc_en = 'When Rage is not full, gain 200 Rage\n#F20# \n#F40##C0x5c9970#→ When Rage is not full, gain 300 Rage  ',
		zawakeSimpleDesc_th = 'เมื่อเกจโกรธยังไม่เต็ม ฟื้นฟูเกจโกรธ 200 แต้ม\n#F20# \n#F40##C0x5c9970#→ เมื่อเกจโกรธยังไม่เต็ม ฟื้นฟูเกจโกรธ 300 แต้ม',
		zawakeSimpleDesc_in = 'Saat Rage belum penuh, pulihkan 200 Rage\n#F20# \n#F40##C0x5c9970#→ Saat Rage belum penuh, pulihkan 300 Rage  ',
		zawakeSimpleDesc_ph = 'Kapag hindi pa puno ang Rage, makakakuha ng 200 Rage\n#F20# \n#F40##C0x5c9970#→ Kapag hindi pa puno ang Rage, makakakuha ng 300 Rage  ',
		zawakeSimpleDesc_ma = 'Apabila kemarahan belum penuh, pulihkan 200 mata kemarahan\n#F20# \n#F40##C0x5c9970#→ Apabila kemarahan belum penuh, pulihkan 300 mata kemarahan  ',
		zawakeSimpleDesc_vn = 'Khi chưa đầy nộ khí, tăng 200 nộ khí cho bản thân\n#F20# \n#F40##C0x5c9970#→ Khi chưa đầy nộ khí, tăng 300 nộ khí cho bản thân',
