	[2213] = {
		id = 2213,
		skillName_vn = 'Nổ',
		skillName_en = 'Explosion',
		skillName_th = 'ระเบิด',
		skillName_in = 'Ledakan',
		skillName_ph = 'Sumabog',
		skillName_ma = 'Letupan',
		skillName = 'Explosion',
		describe_vn = 'Cơn đau đầu của Psyduck trở nên dữ dội, phát ra sóng nổ gây sát thương phép #C0x3D8A99#160% Công Phép#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54# sát thương phép#C0x5B545B# lên mục tiêu hàng trước của kẻ địch. Nếu đang trong trạng thái đau đầu, sát thương kỹ năng tăng 100%, sau khi sử dụng sẽ quên kỹ năng tuyệt chiêu trong 5 lượt.',
		describe_en = 'Psyduck\'s headache intensifies, unleashing an explosive wave that deals magic damage of #C0x3D8A99#160% Magic Power#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54# magic damage#C0x5B545B# to the enemy\'s front row targets. If already in a headache state, skill damage increases by 100%, but after use, the ultimate skill will be forgotten for 5 turns.',
		describe_th = 'อาการปวดหัวของ Psyduck ทวีความรุนแรง ส่งคลื่นระเบิดที่สร้างความเสียหายเวทมนตร์ #C0x3D8A99#160% พลังเวทมนตร์#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# ไปยังเป้าหมายแถวหน้าของศัตรู หากอยู่ในสถานะปวดหัว ความเสียหายของสกิลจะเพิ่มขึ้น 100% หลังจากใช้จะลืมสกิลอัลติเมทเป็นเวลา 5 เทิร์น',
		describe_in = 'Sakit kepala Psyduck menjadi parah, memancarkan gelombang ledakan yang menyebabkan kerusakan sihir sebesar #C0x3D8A99#160% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54# kerusakan sihir#C0x5B545B# ke target barisan depan musuh. Jika dalam keadaan sakit kepala, kerusakan skill meningkat 100%, setelah digunakan akan melupakan skill ultimate selama 5 giliran.',
		describe_ph = 'Ang pananakit ng ulo ni Psyduck ay tumindi, naglalabas ng sumabog na alon na nagdudulot ng magic damage na #C0x3D8A99#160% Magic Power#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54# magic damage#C0x5B545B# sa mga target sa unang hanay ng kaaway. Kung nasa estado ng pananakit ng ulo, tataas ng 100% ang damage ng skill, pagkatapos gamitin ay makakalimutan ang ultimate skill sa loob ng 5 rounds.',
		describe_ma = 'Sakit kepala Psyduck menjadi kuat, mengeluarkan gelombang letupan yang memberi kerosakan sihir #C0x3D8A99#160% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54# kerosakan sihir#C0x5B545B# kepada sasaran barisan depan musuh. Jika sedang dalam keadaan sakit kepala, kerosakan skill meningkat 100%, selepas digunakan akan lupa kemahiran ultimate selama 5 giliran.',
		describe = 'Psyduck\'s headache intensifies, unleashing an explosive wave that deals magic damage of #C0x3D8A99#160% Magic Power#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54# magic damage#C0x5B545B# to the enemy\'s front row targets. If already in a headache state, skill damage increases by 100%, but after use, the ultimate skill will be forgotten for 5 turns.',
		simDesc_vn = 'Ducky không biết gì cả, không liên quan đến Ducky!',
		simDesc_en = 'Ducky knows nothing, has nothing to do with Ducky!',
		simDesc_th = 'ดัคกี้ไม่รู้เรื่องอะไรทั้งนั้น ไม่เกี่ยวกับดัคกี้!',
		simDesc_in = 'Ducky tidak tahu apa-apa, tidak ada hubungannya dengan Ducky!',
		simDesc_ph = 'Hindi alam ni Ducky ang anumang bagay, walang kinalaman kay Ducky!',
		simDesc_ma = 'Ducky tidak tahu apa-apa, tiada kaitan dengan Ducky!',
		simDesc = 'Ducky knows nothing, has nothing to do with Ducky!',
		starEffect = __data_t__starEffect[2213],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Kỹ năng tuyệt chiêu trong trạng thái đau đầu sẽ có thêm 30% xác suất hóa đá.',
		starEffectDesc = 'Additional effect: Special move skills in a dizzy state will have a 30% increased chance to petrify.',
		starEffectDesc_en = 'Additional effect: Special move skills in a dizzy state will have a 30% increased chance to petrify.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: ทักษะท่าไม้ตายในสภาวะเวียนหัวจะมีโอกาส 30% ที่จะกลายเป็นหิน',
		starEffectDesc_in = 'Efek tambahan: Keterampilan jurus khusus dalam keadaan pusing akan memiliki peluang 30% lebih besar untuk membatu.',
		starEffectDesc_ph = 'Karagdagang epekto: Ang mga espesyal na kasanayan sa estado ng pagkahilo ay magkakaroon ng 30% na tsansa na ma-petrify.',
		starEffectDesc_ma = 'Kesan tambahan: Kemahiran gerakan khas dalam keadaan pening akan mempunyai peluang 30% untuk menjadi batu.',
		zawakeEffect = __data_t__zawakeEffect[2213],
		-- {79003}
		zawakeEffectDesc = 'Psyduck suffers severe headache, emitting explosive waves that cause #C0x3D8A99#170% Magical Power#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54# magical damage#C0x5B545B# to the front row enemy targets, if in headache state, ultimate skill damage increases by 100%, after use will forget the ultimate skill for 5 turns',
		zawakeEffectDesc_en = 'Psyduck suffers severe headache, emitting explosive waves that cause #C0x3D8A99#170% Magical Power#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54# magical damage#C0x5B545B# to the front row enemy targets, if in headache state, ultimate skill damage increases by 100%, after use will forget the ultimate skill for 5 turns',
		zawakeEffectDesc_th = 'Psyduck ปวดหัวรุนแรง ปล่อยคลื่นระเบิดที่ก่อให้เกิด #C0x3D8A99#170% พลังเวทย์#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54# ความเสียหายเวทย์#C0x5B545B# ต่อเป้าหมายแถวหน้าของศัตรู ถ้าอยู่ในสถานะปวดหัว ความเสียหายสกิลอัลติเมทจะเพิ่มขึ้น 100% หลังใช้จะลืมสกิลอัลติเมทเป็นเวลา 5 เทิร์น',
		zawakeEffectDesc_in = 'Psyduck mengalami sakit kepala hebat, memancarkan gelombang ledakan yang menyebabkan #C0x3D8A99#170% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54# kerusakan sihir#C0x5B545B# pada target barisan depan musuh, jika dalam kondisi sakit kepala, kerusakan skill ultimate meningkat 100%, setelah digunakan akan melupakan skill ultimate selama 5 giliran',
