	[2313] = {
		id = 2313,
		skillName_vn = 'Gây náo loạn',
		skillName_en = 'Cause chaos',
		skillName_th = 'ก่อความวุ่นวาย',
		skillName_in = 'Menimbulkan kekacauan',
		skillName_ph = 'Magdulot ng kaguluhan',
		skillName_ma = 'Menyebabkan kekacauan',
		skillName = 'Cause chaos',
		describe_vn = 'Khỉ quái cầm dây leo đu qua lại, vào trạng thái [Cuồng nộ] trong 3 lượt (Cuồng nộ: hiệu ứng tăng cường, tăng 40% tỷ lệ chí mạng và 20% tốc độ), thực hiện đòn đánh liên tục điên cuồng vào mục tiêu đơn lẻ của đối phương, gây ra #C0xE69900#460% Công Vật Lý#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, sau sát thương này sẽ ngẫu nhiên thực hiện đòn đánh thường không phân biệt địch ta (duy trì đến khi trạng thái cuồng nộ kết thúc)',
		describe_en = 'The mischievous monkey swings back and forth on the vines, entering [Fury] state for 3 turns (Fury: buff effect, increases critical rate by 40% and speed by 20%), performing a frenzied continuous attack on a single enemy target, dealing #C0xE69900#460% Physical Attack#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Physical Damage#C0x5B545B#. After this damage, it will randomly perform normal attacks regardless of friend or foe (maintains until Fury state ends).',
		describe_th = 'ลิงซนปีนเถาวัลย์โยกไปมา เข้าสู่สถานะ [คลั่ง] เป็นเวลา 3 เทิร์น (คลั่ง: เอฟเฟกต์เสริม เพิ่มอัตราคริติคอล 40% และความเร็ว 20%) ดำเนินการโจมตีต่อเนื่องแบบคลั่งไคล้ไปยังเป้าหมายฝ่ายตรงข้ามเดี่ยว สร้างความเสียหาย #C0xE69900#460% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# หลังจากความเสียหายนี้ จะโจมตีปกติโดยสุ่มโดยไม่แยกแยะฝ่ายศัตรูหรือมิตร (ดำเนินต่อเนื่องจนกว่าสถานะคลั่งจะสิ้นสุด)',
		describe_in = 'Monyet usil melompat-lompat menggunakan sulur, memasuki keadaan [Amarah] selama 3 giliran (Amarah: efek buff, meningkatkan tingkat kritis sebesar 40% dan kecepatan sebesar 20%), melakukan serangan beruntun secara gila-gilaan ke target tunggal lawan, memberikan #C0xE69900#460% Serangan Fisik#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Setelah kerusakan ini, secara acak melakukan serangan biasa tanpa membedakan teman atau musuh (berlanjut hingga keadaan Amarah berakhir).',
		describe_ph = 'Ang pilyong unggoy ay umaalog sa baging, pumapasok sa estado ng [Galit] sa loob ng 3 na turn (Galit: efekto ng pagpapalakas, tumataas ang crit rate ng 40% at bilis ng 20%), nagsasagawa ng walang humpay at mabagsik na atake sa isang kalabang target, nagdudulot ng #C0xE69900#460% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Pagkatapos ng pinsalang ito, kusang magsasagawa ng pangkaraniwang atake nang hindi pinipili kung kaibigan o kalaban (patuloy hanggang matapos ang estado ng galit).',
		describe_ma = 'Monyet nakal memanjat dan mengayun di tali sulur, memasuki keadaan [Kemarahan] selama 3 pusingan (Kemarahan: efek peningkatan, meningkatkan kadar kritikal sebanyak 40% dan kelajuan sebanyak 20%), melakukan serangan bertubi-tubi secara gila-gila ke sasaran tunggal musuh, memberikan #C0xE69900#460% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Selepas kerosakan ini, secara rawak akan melakukan serangan biasa tanpa mengira kawan atau lawan (berterusan sehingga keadaan kemarahan berakhir).',
		describe = 'The mischievous monkey swings back and forth on the vines, entering [Fury] state for 3 turns (Fury: buff effect, increases critical rate by 40% and speed by 20%), performing a frenzied continuous attack on a single enemy target, dealing #C0xE69900#460% Physical Attack#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Physical Damage#C0x5B545B#. After this damage, it will randomly perform normal attacks regardless of friend or foe (maintains until Fury state ends).',
		simDesc_vn = 'Primeape cầm lấy dây leo lắc lư, vào trạng thái điên cuồng, tấn công mục tiêu đơn lẻ của đối phương bằng những cú đánh liên tiếp điên cuồng, sau khi sát thương này, sẽ ngẫu nhiên tấn công cả đồng minh và kẻ thù.',
		simDesc_en = 'Primeape grabs the vine and swings wildly, entering a frenzied state, attacking a single enemy target with a series of furious strikes. After this damage, it will randomly attack both allies and foes.',
		simDesc_th = 'ไพรม์เอปจับเถาไม้และแกว่งอย่างรุนแรงเข้าสู่สถานะคลุ้มคลั่ง โจมตีเป้าหมายศัตรูเดี่ยวด้วยการโจมตีต่อเนื่องบ้าคลั่ง หลังจากสร้างความเสียหายนี้ จะโจมตีแบบสุ่มทั้งพันธมิตรและศัตรู',
