		id = 2616,
		skillName_vn = 'Tâm linh mạnh mẽ',
		skillName_en = 'Strong spirituality',
		skillName_th = 'จิตวิญญาณที่แข็งแกร่ง',
		skillName_in = 'Spiritualitas yang kuat',
		skillName_ph = 'Malakas na espiritwalidad',
		skillName_ma = 'Semangat rohani yang kuat',
		skillName = 'Strong spirituality',
		describe_vn = 'Tăng tỷ lệ khống chế của bản thân lên #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKhi máu bản thân lần đầu tiên giảm dưới 30%, sử dụng năng lực tâm linh còn lại để truyền cho 2 mục tiêu ngẫu nhiên phe mình trong 2 lượt, khiến họ có 40% xác suất [Hóa đá] mục tiêu trong 1 lượt khi tấn công',
		describe_en = 'Increase own control rate by #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nWhen own HP first drops below 30%, use remaining spiritual power to transfer to 2 random allies for 2 turns, giving them a 40% chance to [Petrify] targets for 1 turn when attacking',
		describe_th = 'เพิ่มอัตราการควบคุมของตนเองขึ้น #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nเมื่อพลังชีวิตของตนลดลงต่ำกว่า 30% เป็นครั้งแรก ใช้พลังจิตที่เหลือส่งต่อให้กับเพื่อนร่วมทีม 2 คนแบบสุ่มใน 2 เทิร์น ทำให้พวกเขามีโอกาส 40% ในการ [กลายเป็นหิน] เป้าหมายเป็นเวลา 1 เทิร์นเมื่อโจมตี',
		describe_in = 'Meningkatkan tingkat kontrol diri sendiri sebesar #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nSaat HP sendiri pertama kali turun di bawah 30%, gunakan sisa kekuatan spiritual untuk diteruskan kepada 2 anggota tim secara acak selama 2 giliran, memberikan mereka kesempatan 40% untuk [Membatu] target selama 1 giliran saat menyerang',
		describe_ph = 'Taasan ang sariling control rate ng #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKapag ang HP ng sarili ay unang bumaba sa ilalim ng 30%, gamitin ang natitirang spiritual power para ipadala sa 2 random na kaalyado sa loob ng 2 turn, na nagbibigay sa kanila ng 40% na tsansa na [Maging Batong] ang target sa loob ng 1 turn kapag umaatake',
		describe_ma = 'Tingkatkan kadar kawalan diri sebanyak #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nApabila HP sendiri pertama kali jatuh di bawah 30%, gunakan kuasa rohani yang tinggal untuk disalurkan kepada 2 sasaran rawak dari pihak sendiri selama 2 pusingan, memberikan mereka peluang 40% untuk [Membatu] sasaran selama 1 pusingan ketika menyerang',
		describe = 'Increase own control rate by #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nWhen own HP first drops below 30%, use remaining spiritual power to transfer to 2 random allies for 2 turns, giving them a 40% chance to [Petrify] targets for 1 turn when attacking',
		starEffect = __data_t__starEffect[2616],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Nếu tỷ lệ máu chưa bao giờ thấp hơn 30%, tốc độ của bản thân sẽ tăng 20% (không thể bị giải trừ).',
		starEffectDesc = 'Additional effect: If the HP rate has never dropped below 30%, own speed will increase by 20% (cannot be dispelled).',
		starEffectDesc_en = 'Additional effect: If the HP rate has never dropped below 30%, own speed will increase by 20% (cannot be dispelled).',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: หากอัตราพลังชีวิตไม่เคยต่ำกว่า 30% ความเร็วของตนเองจะเพิ่มขึ้น 20% (ไม่สามารถถูกลบได้)',
		starEffectDesc_in = 'Efek tambahan: Jika tingkat HP belum pernah turun di bawah 30%, kecepatan sendiri akan meningkat 20% (tidak dapat dibatalkan).',
		starEffectDesc_ph = 'Karagdagang epekto: Kung ang HP rate ay hindi kailanman bumaba sa ilalim ng 30%, ang bilis ng sarili ay tataas ng 20% (hindi maaaring alisin).',
		starEffectDesc_ma = 'Kesan tambahan: Jika kadar HP tidak pernah kurang dari 30%, kelajuan diri akan meningkat sebanyak 20% (tidak boleh dibatalkan).',
		zawakeEffect = __data_t__zawakeEffect[2616],
		-- {79004}
		zawakeEffectDesc = 'Increase own control rate #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nWhen own HP first falls below 30%, use remaining energy to transfer to two random teammates for 2 turns, making them have a 40% chance to <Petrify> the target for 1 turn when attacking, superpower heroes receiving energy have a 60% chance to <Petrify> the target for 1 turn when attacking',
		zawakeEffectDesc_en = 'Increase own control rate #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nWhen own HP first falls below 30%, use remaining energy to transfer to two random teammates for 2 turns, making them have a 40% chance to <Petrify> the target for 1 turn when attacking, superpower heroes receiving energy have a 60% chance to <Petrify> the target for 1 turn when attacking',
		zawakeEffectDesc_th = 'เพิ่มอัตราการควบคุมของตนเอง #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nเมื่อ HP ของตนเองลดลงต่ำกว่า 30% เป็นครั้งแรก ใช้พลังงานที่เหลือถ่ายโอนให้กับเป้าหมายสุ่ม 2 คนในฝ่ายเดียวกันเป็นเวลา 2 เทิร์น ทำให้พวกเขามีโอกาส 40% ในการ <เป็นหิน> เป้าหมายเป็นเวลา 1 เทิร์นเมื่อทำการโจมตี ฮีโร่ระบบพลังพิเศษที่ได้รับพลังงานจะมีโอกาส 60% ในการ <เป็นหิน> เป้าหมายเป็นเวลา 1 เทิร์นเมื่อโจมตี',
		zawakeEffectDesc_in = 'Tingkatkan tingkat kontrol diri sendiri #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKetika HP sendiri pertama kali di bawah 30%, gunakan energi yang tersisa untuk mentransfer ke dua target acak tim sendiri selama 2 giliran, membuat mereka memiliki peluang 40% untuk <Membatu> target selama 1 giliran saat menyerang, pahlawan sistem super kekuatan yang menerima energi akan memiliki peluang 60% untuk <Membatu> target selama 1 giliran saat menyerang',
		zawakeEffectDesc_ph = 'Tumaas ang sariling rate ng kontrol #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKapag ang sariling HP ay unang bumaba sa ibaba ng 30%, gamitin ang natitirang enerhiya upang ilipat sa dalawang random na kaalyado mula sa sariling pangkat sa loob ng 2 turn, nagbibigay sa kanila ng 40% na tsansa na <Mag-petrify> ng target sa loob ng 1 turn kapag umaatake, ang mga bayani ng super power system na tumatanggap ng enerhiya ay may 60% na tsansa na <Mag-petrify> ng target sa loob ng 1 turn kapag umaatake',
		zawakeEffectDesc_ma = 'Tingkatkan kadar kawalan diri sendiri #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nApabila HP sendiri pertama kali di bawah 30%, gunakan tenaga yang ada untuk dipindahkan kepada dua sasaran rawak dalam pasukan sendiri selama 2 pusingan, menyebabkan mereka mempunyai peluang 40% untuk <Mengekalkan> sasaran selama 1 pusingan apabila menyerang, wira sistem kuasa luar biasa yang menerima tenaga akan mempunyai peluang 60% untuk <Mengekalkan> sasaran selama 1 pusingan apabila menyerang',
		zawakeEffectDesc_vn = 'Tăng tỷ lệ kiểm soát của bản thân #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKhi HP của bản thân lần đầu tiên dưới 30%, sử dụng năng lượng còn lại để truyền cho hai mục tiêu ngẫu nhiên phe mình trong 2 lượt, khiến họ khi tấn công có 40% xác suất <Hóa đá> mục tiêu trong 1 lượt, anh hùng hệ siêu năng khi nhận được năng lượng sẽ có 60% xác suất <Hóa đá> mục tiêu trong 1 lượt khi tấn công',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Psychic-type heroes, upon receiving Mind Power, have a 60% chance to <Petrify> the target for 1 turn when attacking',
		zawakeSimpleDesc_en = '#C0x5c9970#Psychic-type heroes, upon receiving Mind Power, have a 60% chance to <Petrify> the target for 1 turn when attacking',
		zawakeSimpleDesc_th = '#C0x5c9970#ฮีโร่สายพลังจิตเมื่อได้รับพลังจิต จะมีโอกาส 60% ทำให้เป้าหมาย <กลายเป็นหิน> เป็นเวลา 1 เทิร์นเมื่อโจมตี',
		zawakeSimpleDesc_in = '#C0x5c9970#Hero tipe Psikis saat menerima energi spiritual memiliki peluang 60% untuk <Mempetrifikasi> target selama 1 giliran saat menyerang',
