		skillName_en = 'Strong spirituality',
		skillName_th = 'จิตวิญญาณที่แข็งแกร่ง',
		skillName_in = 'Spiritualitas yang kuat',
		skillName_ph = 'Malakas na espiritu',
		skillName_ma = 'Semangat rohani yang kuat',
		skillName = 'Strong spirituality',
		describe_vn = 'Tăng tỷ lệ khống chế của bản thân lên #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKhi máu bản thân lần đầu tiên giảm dưới 30%, sử dụng năng lực tâm linh còn lại để truyền cho 2 mục tiêu ngẫu nhiên phe mình trong 2 lượt, khiến họ có 40% xác suất [Hóa đá] mục tiêu trong 1 lượt khi tấn công',
		describe_en = 'Increases self control effect rate by #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nWhen own HP first drops below 30%, consumes remaining spiritual power to transfer to 2 random allied targets for 2 turns, giving them a 40% chance to [Petrify] the target for 1 turn upon attack.',
		describe_th = 'เพิ่มอัตราการควบคุมของตนเองขึ้น #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nเมื่อพลังชีวิตของตัวเองลดลงต่ำกว่า 30% เป็นครั้งแรก จะใช้พลังจิตที่เหลือส่งต่อไปยังเป้าหมายฝ่ายเดียวกันแบบสุ่ม 2 ตัวเป็นเวลา 2 เทิร์น ทำให้พวกเขามีโอกาส 40% ที่จะ [กลายเป็นหิน] เป้าหมายเป็นเวลา 1 เทิร์นเมื่อโจมตี',
		describe_in = 'Meningkatkan tingkat kontrol diri sendiri sebanyak #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKetika HP sendiri pertama kali turun di bawah 30%, menggunakan kekuatan spiritual yang tersisa untuk diteruskan ke 2 target sekutu acak selama 2 giliran, memberikan mereka peluang 40% untuk [Membatu] target selama 1 giliran saat menyerang.',
		describe_ph = 'Tinutulungan ang sariling control rate ng #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKapag ang sariling HP ay bumaba ng una sa ilalim ng 30%, ginagawang enerhiya ng espiritu ang natitira upang ipasa sa 2 random na alyadong target sa loob ng 2 turns, na nagbibigay sa kanila ng 40% tsansa na [Maging Bato] ang target sa loob ng 1 turn kapag umaatake.',
		describe_ma = 'Meningkatkan kadar kawalan diri sendiri sebanyak #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nApabila HP sendiri jatuh di bawah 30% buat kali pertama, menggunakan kuasa rohani yang tinggal untuk disalurkan kepada 2 sasaran sekutu rawak selama 2 pusingan, memberikan mereka 40% peluang untuk [Membatu] sasaran selama 1 pusingan semasa menyerang.',
		describe = 'Increases self control effect rate by #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nWhen own HP first drops below 30%, consumes remaining spiritual power to transfer to 2 random allied targets for 2 turns, giving them a 40% chance to [Petrify] the target for 1 turn upon attack.',
		starEffect = __data_t__starEffect[2626],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Nếu tỷ lệ máu chưa bao giờ thấp hơn 30%, tốc độ của bản thân sẽ tăng 20% (không thể bị giải trừ).',
		starEffectDesc = 'Additional effect: If the HP ratio has never dropped below 30%, own speed increases by 20% (cannot be dispelled).',
		starEffectDesc_en = 'Additional effect: If the HP ratio has never dropped below 30%, own speed increases by 20% (cannot be dispelled).',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: หากอัตราส่วน HP ไม่เคยต่ำกว่า 30% ความเร็วของตัวเองจะเพิ่มขึ้น 20% (ไม่สามารถถูกลบได้)',
		starEffectDesc_in = 'Efek tambahan: Jika rasio HP tidak pernah turun di bawah 30%, kecepatan sendiri meningkat 20% (tidak dapat dihapus).',
		starEffectDesc_ph = 'Karagdagang epekto: Kung ang ratio ng HP ay hindi kailanman bumaba sa ilalim ng 30%, ang sariling bilis ay tataas ng 20% (hindi matatanggal).',
		starEffectDesc_ma = 'Kesan tambahan: Jika nisbah HP tidak pernah jatuh di bawah 30%, kelajuan sendiri meningkat 20% (tidak boleh dibuang).',
		zawakeEffect = __data_t__zawakeEffect[2626],
		-- {79004}
		zawakeEffectDesc = 'Increase own control rate #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKWhen own HP first falls below 30%, use remaining energy to transfer to two random allies for 2 turns, causing them to have a 40% chance to <Petrify> the target for 1 turn when attacking, superpower heroes receiving energy have a 60% chance to <Petrify> the target for 1 turn when attacking',
		zawakeEffectDesc_en = 'Increase own control rate #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKWhen own HP first falls below 30%, use remaining energy to transfer to two random allies for 2 turns, causing them to have a 40% chance to <Petrify> the target for 1 turn when attacking, superpower heroes receiving energy have a 60% chance to <Petrify> the target for 1 turn when attacking',
		zawakeEffectDesc_th = 'เพิ่มอัตราการควบคุมตนเอง #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKเมื่อ HP ของตนเองเป็นครั้งแรกต่ำกว่า 30% ใช้พลังงานที่เหลือเพื่อถ่ายโอนไปยังสองเป้าหมายสุ่มฝ่ายเดียวกันเป็นเวลา 2 เทิร์น ทำให้พวกเขามีโอกาส 40% ที่จะ <กลายเป็นหิน> เป้าหมายเป็นเวลา 1 เทิร์นเมื่อโจมตี ฮีโร่ระบบพลังเหนือมนุษย์เมื่อได้รับพลังงานจะมีโอกาส 60% ที่จะ <กลายเป็นหิน> เป้าหมายเป็นเวลา 1 เทิร์นเมื่อโจมตี',
		zawakeEffectDesc_in = 'Tingkatkan tingkat kendali diri sendiri #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKKetika HP sendiri pertama kali di bawah 30%, gunakan energi yang tersisa untuk mentransfer ke dua target acak dari pihak sendiri selama 2 giliran, membuat mereka memiliki peluang 40% untuk <Membatu> target selama 1 giliran saat menyerang, pahlawan superpower yang menerima energi memiliki peluang 60% untuk <Membatu> target selama 1 giliran saat menyerang',
		zawakeEffectDesc_ph = 'Tumaas ang sariling rate ng kontrol #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKPagsapit ng unang pagkakataon na ang sariling HP ay bumaba sa ilalim ng 30%, gamitin ang natitirang enerhiya upang ilipat sa dalawang random na kaalyado sa sariling panig sa loob ng 2 turn, na nagdudulot sa kanila ng 40% na tsansa na <Petrolyahin> ang target sa loob ng 1 turn kapag umaatake, ang mga superpower na bayani na tumatanggap ng enerhiya ay may 60% na tsansa na <Petrolyahin> ang target sa loob ng 1 turn kapag umaatake',
		zawakeEffectDesc_ma = 'Tingkatkan kadar kawalan diri sendiri #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKApa bila HP diri sendiri pertama kali di bawah 30%, gunakan tenaga baki untuk dipindahkan kepada dua sasaran rawak pihak sendiri dalam 2 giliran, menyebabkan mereka mempunyai 40% peluang untuk <Membatu> sasaran selama 1 giliran semasa menyerang, wira superpower yang menerima tenaga akan mempunyai 60% peluang untuk <Membatu> sasaran selama 1 giliran semasa menyerang',
		zawakeEffectDesc_vn = 'Tăng tỷ lệ kiểm soát của bản thân #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#;\nKhi HP của bản thân lần đầu tiên dưới 30%, sử dụng năng lượng còn lại để truyền cho hai mục tiêu ngẫu nhiên phe mình trong 2 lượt, khiến họ khi tấn công có 40% xác suất <Hóa đá> mục tiêu trong 1 lượt, anh hùng hệ siêu năng khi nhận được năng lượng sẽ có 60% xác suất <Hóa đá> mục tiêu trong 1 lượt khi tấn công',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Psychic-type heroes, when receiving Mind Energy, have a 60% chance to <Petrify> the target for 1 turn when attacking',
		zawakeSimpleDesc_en = '#C0x5c9970#Psychic-type heroes, when receiving Mind Energy, have a 60% chance to <Petrify> the target for 1 turn when attacking',
		zawakeSimpleDesc_th = '#C0x5c9970#ฮีโร่สายพลังจิต เมื่อได้รับพลังจิต จะมีโอกาส 60% ที่จะ <กลายเป็นหิน> เป้าหมาย 1 เทิร์นเมื่อโจมตี',
		zawakeSimpleDesc_in = '#C0x5c9970#Hero tipe Psikis, saat menerima Energi Pikiran, memiliki peluang 60% untuk <Mem petrifikasi> target selama 1 giliran saat menyerang',
		zawakeSimpleDesc_ph = '#C0x5c9970#Kapag ang Psychic-type hero ay nakatanggap ng Mind Energy, may 60% tsansa na ma-<Petrify> ang kalaban sa loob ng 1 turn kapag umatake',
