		zawakeEffect = __data_t__zawakeEffect[2733],
		-- {79003}
		zawakeEffectDesc = 'Ken spins a circle and punches a death tornado to attack an enemy target, dealing #C0xE69900#800% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#Physical Damage#C0x5B545B#, then abandons all his defensive abilities (double defense, resistance, crime prevention, damage reduction), lasting for 1 turn.',
		zawakeEffectDesc_en = 'Ken spins a circle and punches a death tornado to attack an enemy target, dealing #C0xE69900#800% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#Physical Damage#C0x5B545B#, then abandons all his defensive abilities (double defense, resistance, crime prevention, damage reduction), lasting for 1 turn.',
