	[3343] = {
		id = 3343,
		skillName_vn = 'Thần Uy - Bão Sét',
		skillName_en = 'Divine Power - Thunderstorm',
		skillName_th = 'อำนาจเทพ - พายุฟ้า',
		skillName_in = 'Kekuatan Ilahi - Badai Petir',
		skillName_ph = 'Banal na Lakas - Bagyong Kidlat',
		skillName_ma = 'Kuasa Ilahi - Ribut Petir',
		skillName = 'Divine Power - Thunderstorm',
		describe_vn = 'Thần Uy - Kakashi sử dụng nhẫn pháp ẩn mình vào mây sét, gây ra bão sét tấn công mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#780% Phép Công#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, sau đó kích hoạt bão sét kéo dài 1 lượt, trong thời gian này mỗi khi kết thúc lượt của cả địch và ta sẽ tạo ra một tia sét tấn công mục tiêu đơn lẻ ngẫu nhiên của kẻ địch, khi lượt của anh hùng hệ điện phe ta kết thúc sẽ tạo thêm một tia sét',
		describe_en = 'Divine Might - Kakashi uses a ninja technique to hide within the lightning clouds, unleashing a lightning storm that targets a single enemy, dealing #C0x3D8A99#780% Magic Attack#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Magic Damage#C0x5B545B#. Afterwards, a lightning storm lasts for 1 turn; during this time, at the end of both enemy and ally turns, a lightning strike will randomly hit a single enemy target. At the end of our electric-attribute hero\'s turn, an additional lightning strike is triggered.',
		describe_th = 'พลังเทพ - คาคาชิใช้วิชานินจาที่ซ่อนตัวในก้อนเมฆสายฟ้า สร้างพายุสายฟ้าโจมตีเป้าหมายศัตรูเดี่ยว ทำความเสียหาย #C0x3D8A99#780% พลังโจมตีเวท#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# จากนั้นจะเปิดพายุสายฟ้าต่อเนื่องเป็นเวลา 1 เทิร์น ในช่วงนี้เมื่อสิ้นสุดเทิร์นของทั้งฝ่ายศัตรูและฝ่ายเรา จะมีสายฟ้าฟาดโจมตีเป้าหมายศัตรูเดี่ยวแบบสุ่ม และเมื่อสิ้นสุดเทิร์นของฮีโร่ธาตุไฟฟ้าฝ่ายเรา จะมีสายฟ้าฟาดเพิ่มขึ้นอีกหนึ่งเส้น',
		describe_in = 'Kekuatan Dewa - Kakashi menggunakan teknik ninja untuk bersembunyi di awan petir, menyebabkan badai petir yang menyerang satu target musuh, memberikan #C0x3D8A99#780% Serangan Sihir#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Kerusakan Sihir#C0x5B545B#. Kemudian mengaktifkan badai petir selama 1 giliran, selama waktu ini, setiap akhir giliran musuh dan kita akan menghasilkan satu petir yang menyerang satu target musuh secara acak. Saat giliran pahlawan elemen listrik kita berakhir, akan menghasilkan satu petir tambahan.',
		describe_ph = 'Divine Might - Ginamit ni Kakashi ang isang ninjutsu upang magtago sa ulap ng kidlat, nagdulot ng bagyong kidlat na umatake sa isang random na kalaban, na nagdudulot ng #C0x3D8A99#780% Magic Attack#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Magic Damage#C0x5B545B#. Pagkatapos, nag-activate ng bagyong kidlat na tatagal ng 1 turn; sa panahon nito, pagkatapos ng bawat turn ng kaaway at ng ating koponan, isang kidlat ang tutugon at tatamaan ang isang random na kalaban. Kapag natapos ang turn ng electrical-element hero natin, isang karagdagang kidlat ang lilitaw.',
		describe_ma = 'Kekuatan Dewa - Kakashi menggunakan teknik ninja untuk bersembunyi dalam awan petir, menyebabkan ribut petir yang menyerang satu sasaran musuh, memberikan #C0x3D8A99#780% Serangan Sihir#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Kerosakan Sihir#C0x5B545B#. Kemudian mengaktifkan ribut petir selama 1 pusingan, dalam tempoh ini, setiap kali tamat giliran musuh dan kita, akan menghasilkan satu petir yang menyerang satu sasaran musuh secara rawak. Apabila giliran wira elemen elektrik pihak kita tamat, satu petir tambahan akan dihasilkan.',
		describe = 'Divine Might - Kakashi uses a ninja technique to hide within the lightning clouds, unleashing a lightning storm that targets a single enemy, dealing #C0x3D8A99#780% Magic Attack#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Magic Damage#C0x5B545B#. Afterwards, a lightning storm lasts for 1 turn; during this time, at the end of both enemy and ally turns, a lightning strike will randomly hit a single enemy target. At the end of our electric-attribute hero\'s turn, an additional lightning strike is triggered.',
		simDesc_vn = 'Kamui Kakashi ẩn mình trong mây sấm sét, gây ra bão sấm tấn công mục tiêu đơn lẻ của đối phương, sau đó liên tục gây ra bão sấm tấn công ngẫu nhiên vào các mục tiêu đơn lẻ của đối phương.',
		simDesc_en = 'Kamui Kakashi hides within thunderclouds, unleashing a thunderstorm to strike a single enemy target, then continuously summoning thunderstorms to randomly attack individual enemy targets.',
		simDesc_th = 'คามุอิ คาคาชิ ซ่อนตัวอยู่ในเมฆฝนฟ้าคะนอง สร้างพายุฟ้าผ่าทำร้ายศัตรูเป้าหมายเดียว จากนั้นจึงสร้างพายุฟ้าผ่าโจมตีเป้าหมายศัตรูเดี่ยวแบบสุ่มอย่างต่อเนื่อง',
		simDesc_in = 'Kamui Kakashi bersembunyi dalam awan petir, menyebabkan badai petir menyerang satu target musuh, kemudian terus-menerus menyebabkan badai petir menyerang secara acak ke target musuh tunggal.',
		simDesc_ph = 'Nagtatago si Kamui Kakashi sa mga ulap ng kidlat, nagdudulot ng bagyong kidlat para atakihin ang iisang target na kalaban, pagkatapos ay patuloy na nagdudulot ng mga bagyong kidlat para random na atakihin ang mga iisang target na kalaban.',
		simDesc_ma = 'Kamui Kakashi bersembunyi dalam awan ribut petir, menyebabkan ribut petir menyerang sasaran musuh tunggal, kemudian berterusan menyebabkan ribut petir menyerang sasaran musuh tunggal secara rawak.',
		simDesc = 'Kamui Kakashi hides within thunderclouds, unleashing a thunderstorm to strike a single enemy target, then continuously summoning thunderstorms to randomly attack individual enemy targets.',
		starEffect = __data_t__starEffect[3343],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Trong thời gian bão tố, sát thương từ sấm sét và xác suất kích hoạt <Siêu dẫn> sẽ tăng thêm 20%.',
		starEffectDesc = 'Enhance Effect: During storms, damage from lightning and the activation chance of <Superconduct> will increase by 20%.',
		starEffectDesc_en = 'Enhance Effect: During storms, damage from lightning and the activation chance of <Superconduct> will increase by 20%.',
		starEffectDesc_th = 'เสริมเอฟเฟกต์: ในช่วงพายุ ความเสียหายจากฟ้าผ่าและโอกาสในการเปิดใช้งาน <ซูเปอร์คอนดักต์> จะเพิ่มขึ้น 20%',
		starEffectDesc_in = 'Meningkatkan efek: Selama badai, kerusakan dari petir dan peluang aktivasi <Superkonduktor> akan meningkat sebesar 20%.',
