	[3352] = {
		id = 3352,
		skillName_vn = 'Thần Uy - Dẫn Sét',
		skillName_en = 'Divine Power - Lightning Conductor',
		skillName_th = 'อำนาจเทพ - นำสายฟ้า',
		skillName_in = 'Banal na Lakas - Tagapag-ugnay ng Kidlat',
		skillName_ph = 'Banal na Lakas - Tagapag-ugnay ng Kidlat',
		skillName_ma = 'Kuasa Ilahi - Pengarah Petir',
		skillName = 'Divine Power - Lightning Conductor',
		describe_vn = 'Thần Uy - Kakashi ném phi tiêu sấm sét tấn công mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#300% Phép Công#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, đồng thời đánh dấu mục tiêu có công kích cao nhất của kẻ địch trong 2 lượt, mỗi lần sấm sét kích hoạt sẽ có thêm một tia sét đánh vào mục tiêu bị đánh dấu',
		describe_en = 'Divine Might - Kakashi throws a lightning shuriken to attack a single enemy target, dealing #C0x3D8A99#300% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Magic Damage#C0x5B545B#. At the same time, it marks the enemy\'s highest attack target for 2 turns. Each time lightning activates, an additional lightning strike hits the marked target.',
		describe_th = 'พลังเทพ - คาคาชิ โยนชูริเคนสายฟ้าโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#300% พลังโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# พร้อมทั้งทำเครื่องหมายเป้าหมายที่มีการโจมตีสูงสุดของศัตรูเป็นเวลา 2 เทิร์น ทุกครั้งที่สายฟ้าทำงาน จะมีสายฟ้าโจมตีเป้าหมายที่ถูกทำเครื่องหมายเพิ่มเติม',
		describe_in = 'Kekuatan Dewa - Kakashi melempar shuriken petir untuk menyerang satu target musuh, memberikan #C0x3D8A99#300% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerusakan Sihir#C0x5B545B#. Pada saat yang sama, menandai target dengan serangan tertinggi musuh selama 2 giliran. Setiap kali petir aktif, akan ada satu sambaran petir tambahan yang menyerang target yang ditandai.',
		describe_ph = 'Divine Might - Si Kakashi ay nagtatapon ng kidlat na shuriken upang atakihin ang isang solong target na kaaway, na nagdudulot ng #C0x3D8A99#300% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Magic Damage#C0x5B545B#. Kasabay nito, minamarkahan ang pinaka-matinding target ng kaaway sa loob ng 2 na turno. Sa bawat pag-activate ng kidlat, isang dagdag na kidlat ang tumatama sa minarkahang target.',
		describe_ma = 'Kekuatan Ilahi - Kakashi melempar shuriken kilat untuk menyerang satu sasaran musuh, memberikan #C0x3D8A99#300% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerosakan Sihir#C0x5B545B#. Pada masa yang sama, menandakan sasaran serangan tertinggi musuh selama 2 pusingan. Setiap kali kilat diaktifkan, satu kilat tambahan akan menyerang sasaran yang ditandakan.',
		describe = 'Divine Might - Kakashi throws a lightning shuriken to attack a single enemy target, dealing #C0x3D8A99#300% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Magic Damage#C0x5B545B#. At the same time, it marks the enemy\'s highest attack target for 2 turns. Each time lightning activates, an additional lightning strike hits the marked target.',
		zawakeEffect = __data_t__zawakeEffect[3352],
		-- {79002}
		zawakeEffectDesc = 'Kamui Kakashi throws thunder shurikens to attack a single enemy target, dealing #C0x3D8A99#300% Magical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, and marks the enemy target with the highest attack for 3 turns, each time thunder activates it will add an extra lightning strike to the marked target',
		zawakeEffectDesc_en = 'Kamui Kakashi throws thunder shurikens to attack a single enemy target, dealing #C0x3D8A99#300% Magical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, and marks the enemy target with the highest attack for 3 turns, each time thunder activates it will add an extra lightning strike to the marked target',
		zawakeEffectDesc_th = 'คามุย คาคาชิ โยนดาวกระจายสายฟ้าโจมตีเป้าหมายศัตรูเดี่ยว สร้าง #C0x3D8A99#300% พลังโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# และทำเครื่องหมายเป้าหมายศัตรูที่มีพลังโจมตีสูงสุดเป็นเวลา 3 เทิร์น ทุกครั้งที่สายฟ้าทำงานจะมีสายฟ้าเพิ่มโจมตีเป้าหมายที่ถูกทำเครื่องหมาย',
		zawakeEffectDesc_in = 'Kamui Kakashi melempar shuriken petir untuk menyerang satu target musuh, memberikan #C0x3D8A99#300% Serangan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Magic #C0x5B545B#, dan menandai target musuh dengan serangan tertinggi selama 3 giliran, setiap kali petir aktif akan menambahkan satu serangan petir ke target yang ditandai',
		zawakeEffectDesc_ph = 'Pinaputok ni Kamui Kakashi ang kidlat na shuriken gamit ang thunder upang atakihin ang isang target na kalaban, nagdudulot ng #C0x3D8A99#300% Magical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, at minamarkahan ang kalabang may pinakamalakas na atake sa loob ng 3 turn, sa bawat pag-activate ng kidlat, may dagdag na kidlat na tumatama sa minarkahang target',
		zawakeEffectDesc_ma = 'Kamui Kakashi melempar shuriken petir untuk menyerang satu sasaran musuh, memberikan #C0x3D8A99#300% Serangan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Magik #C0x5B545B#, dan menandakan sasaran musuh dengan serangan tertinggi selama 3 pusingan, setiap kali petir diaktifkan akan menambah satu serangan petir ke sasaran yang ditandakan',
		zawakeEffectDesc_vn = 'Kamui Kakashi phóng phi tiêu sấm sét tấn công mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#300% Phép Công#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, và đánh dấu mục tiêu có công kích cao nhất của kẻ địch trong 3 lượt, mỗi lần sấm sét kích hoạt sẽ có thêm một tia sét đánh vào mục tiêu được đánh dấu',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Mark the enemy unit with the highest ATK for 2 turns\n#F20#\n#F40##C0x5c9970#→Mark the enemy unit with the highest ATK for 3 turns#C0x5B545B#',
		zawakeSimpleDesc_en = 'Mark the enemy unit with the highest ATK for 2 turns\n#F20#\n#F40##C0x5c9970#→Mark the enemy unit with the highest ATK for 3 turns#C0x5B545B#',
		zawakeSimpleDesc_th = 'ทำเครื่องหมายศัตรูที่มีพลังโจมตีสูงสุด เป็นเวลา 2 เทิร์น\n#F20#\n#F40##C0x5c9970#→ทำเครื่องหมายศัตรูที่มีพลังโจมตีสูงสุด เป็นเวลา 3 เทิร์น#C0x5B545B#',
		zawakeSimpleDesc_in = 'Tandai unit musuh dengan ATK tertinggi selama 2 giliran\n#F20#\n#F40##C0x5c9970#→Tandai unit musuh dengan ATK tertinggi selama 3 giliran#C0x5B545B#',
		zawakeSimpleDesc_ph = 'Markahan ang kalabang unit na may pinakamataas na ATK sa loob ng 2 turn\n#F20#\n#F40##C0x5c9970#→Markahan ang kalabang unit na may pinakamataas na ATK sa loob ng 3 turn#C0x5B545B#',
		zawakeSimpleDesc_ma = 'Tandakan unit musuh yang mempunyai Serangan tertinggi selama 2 pusingan\n#F20#\n#F40##C0x5c9970#→Tandakan unit musuh yang mempunyai Serangan tertinggi selama 3 pusingan#C0x5B545B#',
		zawakeSimpleDesc_vn = 'Đánh dấu đơn vị địch có công kích cao nhất trong 2 lượt\n#F20#\n#F40##C0x5c9970#→Đánh dấu đơn vị địch có công kích cao nhất trong 3 lượt#C0x5B545B#',
