	[3353] = {
		id = 3353,
		skillName_vn = 'Thần Uy - Bão Sét',
		skillName_en = 'Divine Power - Thunderstorm',
		skillName_th = 'อำนาจเทพ - พายุฟ้า',
		skillName_in = 'Banal na Lakas - Bagyong Kidlat',
		skillName_ph = 'Banal na Lakas - Bagyong Kidlat',
		skillName_ma = 'Kuasa Ilahi - Ribut Petir',
		skillName = 'Divine Power - Thunderstorm',
		describe_vn = 'Thần Uy - Kakashi sử dụng nhẫn pháp ẩn mình vào mây sét, gây ra bão sét tấn công mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#780% Phép Công#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, sau đó kích hoạt bão sét kéo dài 1 lượt, trong thời gian này mỗi khi kết thúc lượt của cả địch và ta sẽ tạo ra một tia sét tấn công mục tiêu đơn lẻ ngẫu nhiên của kẻ địch, khi lượt của anh hùng hệ điện phe ta kết thúc sẽ tạo thêm một tia sét',
		describe_en = 'Divine Might - Kakashi uses the ninja art to conceal himself within the thundercloud, unleashing a lightning storm that attacks a single enemy target, dealing #C0x3D8A99#780% Magic Attack#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Magic Damage#C0x5B545B#. Then activates a lightning storm lasting 1 turn, during which at the end of both enemy and ally turns, a lightning bolt is generated to strike a random single enemy target. When an allied electric-type hero\'s turn ends, an additional lightning bolt is created.',
		describe_th = 'เทพอำนาจ - คาคาชิใช้วิชานินจาซ่อนตัวในเมฆสายฟ้า ปล่อยพายุฟ้าผ่าที่โจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0x3D8A99#780% พลังเวท#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#ความเสียหายเวท#C0x5B545B# จากนั้นเปิดใช้งานพายุฟ้าผ่าที่มีระยะเวลานาน 1 เทิร์น ระหว่างนี้เมื่อจบเทิร์นของทั้งศัตรูและเรา จะเกิดฟ้าผ่าหนึ่งเส้นโจมตีเป้าหมายศัตรูเดี่ยวแบบสุ่ม และเมื่อจบเทิร์นของฮีโร่สายสายฟ้าของฝ่ายเรา จะสร้างฟ้าผ่าเพิ่มขึ้นอีกหนึ่งเส้น',
		describe_in = 'Kekuatan Dewa - Kakashi menggunakan jurus ninja menyembunyikan diri di awan petir, menyebabkan badai petir yang menyerang satu target musuh, memberikan #C0x3D8A99#780% Serangan Sihir#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Kerusakan Sihir#C0x5B545B#. Kemudian mengaktifkan badai petir yang berlangsung selama 1 giliran, selama waktu ini setiap kali giliran musuh dan giliran kita berakhir akan muncul sebuah petir yang menyerang satu target musuh secara acak. Saat giliran hero tipe listrik rekan kita berakhir, akan muncul petir tambahan.',
		describe_ph = 'Divine Might - Ginagamit ni Kakashi ang ninja art para magtago sa ulap ng kidlat, nagdudulot ng kidlat na bagyong umaatake sa isang target na kalaban, nagdudulot ng #C0x3D8A99#780% Magic Attack#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Magic Damage#C0x5B545B#. Pagkatapos ay pinapagana ang kidlat na bagyong tumatagal ng 1 turn, kung saan sa pagtatapos ng parehong kalaban at sariling turn ay lumalabas ang isang kidlat na tumatama sa isang random na target na kalaban. Kapag natapos ang turn ng kaalyadong electric-type hero ay lumalabas pang isang kidlat.',
		describe_ma = 'Kuasa Ilahi - Kakashi menggunakan ilmu ninja untuk bersembunyi dalam awan kilat, menyebabkan ribut petir yang menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#780% Serangan Sihir#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Kerosakan Sihir#C0x5B545B#. Kemudian mengaktifkan ribut petir yang berlangsung selama 1 pusingan, dalam tempoh ini setiap kali pengakhiran giliran musuh dan kita akan menghasilkan satu kilat yang menyerang satu sasaran musuh secara rawak. Apabila giliran wira jenis elektrik sekutu kita berakhir akan menghasilkan satu kilat tambahan.',
		describe = 'Divine Might - Kakashi uses the ninja art to conceal himself within the thundercloud, unleashing a lightning storm that attacks a single enemy target, dealing #C0x3D8A99#780% Magic Attack#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Magic Damage#C0x5B545B#. Then activates a lightning storm lasting 1 turn, during which at the end of both enemy and ally turns, a lightning bolt is generated to strike a random single enemy target. When an allied electric-type hero\'s turn ends, an additional lightning bolt is created.',
		simDesc_vn = 'Kamui Kakashi ẩn mình trong mây sấm sét, gây ra bão sấm tấn công mục tiêu đơn lẻ của đối phương, sau đó liên tục gây ra bão sấm tấn công ngẫu nhiên vào các mục tiêu đơn lẻ của đối phương.',
		simDesc_en = 'Kamui Kakashi hides within thunderclouds, unleashing a thunderstorm to strike a single enemy target, then continuously summons random thunderstorms to attack various single enemy targets.',
		simDesc_th = 'คามุย คาคาชิ ซ่อนตัวอยู่ในเมฆสายฟ้า ปล่อยพายุฟ้าร้องโจมตีเป้าหมายศัตรูเดี่ยว จากนั้นก็ปล่อยพายุฟ้าร้องโจมตีเป้าหมายศัตรูเดี่ยวแบบสุ่มอย่างต่อเนื่อง',
		simDesc_in = 'Kamui Kakashi bersembunyi dalam awan petir, menyebabkan badai petir menyerang satu target musuh, kemudian terus-menerus menghasilkan badai petir yang menyerang secara acak ke beberapa target musuh tunggal.',
		simDesc_ph = 'Nagtatago si Kamui Kakashi sa mga ulap ng kidlat, nagdudulot ng bagyong kulog upang atakihin ang isang layuning kalaban, at pagkatapos ay patuloy na nagdudulot ng mga bagyong kulog na random na sumasalakay sa iba\'t ibang magkakahiwalay na layunin ng kalaban.',
		simDesc_ma = 'Kamui Kakashi bersembunyi di dalam awan petir, menyebabkan ribut petir menyerang satu sasaran musuh, kemudian terus-menerus menyebabkan ribut petir menyerang secara rawak ke sasaran individu musuh.',
		simDesc = 'Kamui Kakashi hides within thunderclouds, unleashing a thunderstorm to strike a single enemy target, then continuously summons random thunderstorms to attack various single enemy targets.',
		starEffect = __data_t__starEffect[3353],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Trong thời gian bão tố, sát thương từ sấm sét và xác suất kích hoạt <Siêu dẫn> sẽ tăng thêm 20%.',
		starEffectDesc = 'Enhance effect: During storms, damage from lightning and the activation probability of <Superconduct> will increase by 20%.',
		starEffectDesc_en = 'Enhance effect: During storms, damage from lightning and the activation probability of <Superconduct> will increase by 20%.',
