	[3356] = {
		id = 3356,
		skillName_vn = 'Thần Uy - Thiên Lôi',
		skillName_en = 'Divine Power - Heavenly Thunder',
		skillName_th = 'อำนาจเทพ - ฟ้าร้อง',
		skillName_in = 'Banal na Lakas - Kalangitang Kidlat',
		skillName_ph = 'Banal na Lakas - Kalangitang Kidlat',
		skillName_ma = 'Kuasa Ilahi - Guntur Langit',
		skillName = 'Divine Power - Heavenly Thunder',
		describe_vn = 'Thần Uy - Thiên Lôi: Mỗi khi kết thúc đại lượt sẽ gây sát thương nguyên tố điện bằng 100% Phép Công của bản thân lên mục tiêu đơn lẻ ngẫu nhiên của kẻ địch, mỗi tia sét tấn công có #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# xác suất cơ bản khiến mục tiêu nhận một tầng [Siêu Dẫn]\n#F10#\n#F40##L10#[Siêu Dẫn]:#L0# Có thể chồng tối đa 5 tầng, mỗi tầng Siêu Dẫn tăng 5% sát thương hệ điện và 20% tỷ lệ truyền dẫn, khi mục tiêu Siêu Dẫn nhận sát thương từ sấm sét, tất cả mục tiêu Siêu Dẫn sẽ nhận sát thương nguyên tố điện tương ứng với tỷ lệ truyền dẫn',
		describe_en = 'Divine Might - Heavenly Thunder: At the end of each major turn, deals Electric elemental damage equal to 100% of own Magic Attack to a random single enemy target. Each lightning strike has a base chance of #(20+skillLevel*0.2-0.2)%# to apply one stack of [Superconduction]\n#F10#\n#F40##L10#[Superconduction]:#L0# Can stack up to 5 layers. Each layer of Superconduction increases Electric damage by 5% and conduction rate by 20%. When a Superconduction target takes thunder damage, all Superconduction targets receive Electric elemental damage according to the conduction rate.',
		describe_th = '[พลังเทพ · สายฟ้าสวรรค์]: เมื่อจบรอบใหญ่แต่ละครั้ง จะโจมตีศัตรูแบบสุ่ม 1 ตัวด้วยความเสียหายธาตุสายฟ้า เท่ากับ 100% ของพลังโจมตีเวทของตนเอง โดยแต่ละสายฟ้ามีโอกาสพื้นฐาน #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ที่จะทำให้เป้าหมายได้รับ 1 ชั้นของ [โอเวอร์โหลด] #F10##F40# [โอเวอร์โหลด]: ซ้อนทับได้สูงสุด 5 ชั้น แต่ละชั้นจะเพิ่มความรุนแรงของความเสียหายธาตุสายฟ้า 5% และเพิ่มอัตราการส่งผ่าน 20% เมื่อเป้าหมายที่มีโอเวอร์โหลดได้รับความเสียหายจากสายฟ้า เป้าหมายอื่นที่มีโอเวอร์โหลดทั้งหมดจะได้รับความเสียหายธาตุสายฟ้าตามอัตราการส่งผ่านที่สอดคล้องกัน',
		describe_in = 'Kekuatan Dewa - Petir Surgawi: Setiap akhir giliran utama, memberikan damage elemen Listrik sebesar 100% dari Serangan Sihir diri sendiri ke satu target musuh acak. Setiap serangan petir memiliki peluang dasar #(20+levelSkill*0.2-0.2)% untuk memberikan satu tumpukan [Superkonduksi]\n#F10#\n#F40##L10#[Superkonduksi]:#L0# Dapat menumpuk hingga 5 lapis, setiap lapisan Superkonduksi meningkatkan 5% damage elemen Listrik dan 20% tingkat konduksi. Saat target Superkonduksi menerima damage petir, semua target dengan Superkonduksi akan menerima damage elemen Listrik sesuai dengan tingkat konduksi tersebut.',
		describe_ph = 'Divine Might - Langit na Kulog: Sa pagtatapos ng bawat pangunahing turn, nagdudulot ng Elemental na elektrikal na pinsala na katumbas ng 100% ng sariling Magic Attack sa isang random na nag-iisang target na kalaban. Ang bawat kidlat na tinatamaan ay may base chance na #(20+skillLevel*0.2-0.2)% na maglagay ng isang stack ng [Superconduction]\n#F10#\n#F40##L10#[Superconduction]:#L0# Maaaring mag-stack ng hanggang 5 layers, bawat layer ng Superconduction ay nagpapataas ng 5% na elektrikal na pinsala at 20% conduction rate. Kapag ang target na may Superconduction ay tumanggap ng pinsala mula sa kidlat, lahat ng may Superconduction na target ay tatanggap ng Elemental na elektrikal na pinsala ayon sa conduction rate.',
		describe_ma = 'Kuasa Tuhan - Petir Syurga: Setiap kali berakhir giliran besar, akan menyebabkan kerosakan elemen Elektrik sebanyak 100% Serangan Sihir diri sendiri kepada sasaran musuh tunggal secara rawak. Setiap serangan kilat mempunyai peluang asas #(20+peringkatKemahiran*0.2-0.2)% untuk memberikan satu lapisan [Superkonduksi]\n#F10#\n#F40##L10#[Superkonduksi]:#L0# Boleh bertindih sehingga 5 lapisan, setiap lapisan Superkonduksi meningkatkan 5% kerosakan elemen Elektrik dan 20% kadar penghantaran. Apabila sasaran Superkonduksi menerima kerosakan daripada kilat, semua sasaran Superkonduksi akan menerima kerosakan elemen Elektrik mengikut kadar penghantaran tersebut.',
		describe = 'Divine Might - Heavenly Thunder: At the end of each major turn, deals Electric elemental damage equal to 100% of own Magic Attack to a random single enemy target. Each lightning strike has a base chance of #(20+skillLevel*0.2-0.2)%# to apply one stack of [Superconduction]\n#F10#\n#F40##L10#[Superconduction]:#L0# Can stack up to 5 layers. Each layer of Superconduction increases Electric damage by 5% and conduction rate by 20%. When a Superconduction target takes thunder damage, all Superconduction targets receive Electric elemental damage according to the conduction rate.',
		starEffect = __data_t__starEffect[3356],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Sát thương từ <Sấm sét> sẽ thêm 15% sát thương điện tử dựa trên máu đã mất của mục tiêu (không vượt quá 300% sức tấn Công Phép thuật của Thần Uy-Kakashi).',
		starEffectDesc = 'Enhance Effect: Damage from <Lightning> will add 15% electric damage based on the target\'s lost HP (not exceeding 300% of Kakashi God Power\'s Magic Attack).',
		starEffectDesc_en = 'Enhance Effect: Damage from <Lightning> will add 15% electric damage based on the target\'s lost HP (not exceeding 300% of Kakashi God Power\'s Magic Attack).',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: ความเสียหายจาก <ฟ้าผ่า> จะเพิ่มความเสียหายไฟฟ้า 15% ตามพลังชีวิตที่สูญเสียของเป้าหมาย (ไม่เกิน 300% ของพลังโจมตีเวทย์ของเทพคาคาชิ).',
		starEffectDesc_in = 'Perkuat Efek: Kerusakan dari <Petir> akan menambahkan 15% kerusakan listrik berdasarkan HP yang hilang dari target (tidak melebihi 300% Serangan Magis Dewa Kakashi).',
		starEffectDesc_ph = 'Palakasin ang Epekto: Ang pinsala mula sa <Kidlat> ay magdadagdag ng 15% na elektrikal na pinsala base sa nawalang HP ng target (hindi hihigit sa 300% ng Magic Attack ng Diyos na Kakashi).',
		starEffectDesc_ma = 'Tingkatkan Kesan: Kerosakan daripada <Petir> akan menambah 15% kerosakan elektrik berdasarkan HP yang hilang oleh sasaran (tidak melebihi 300% Serangan Magik Kuasa Dewa Kakashi).',
		zawakeEffect = __data_t__zawakeEffect[3356],
		-- {79004}
		zawakeEffectDesc = 'Thunder God: At the end of each major turn, deals electric elemental damage equal to 100% of own Magic Power to a random single enemy target. Each Thunder God attack has a #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# base chance to apply one stack of <Superconduct>, and a 10% chance to also apply <Paralysis> to the target\n#F10#\n#F40##L10#<Superconduct>: #L0#Can stack up to five times, each stack increases electric damage received by 5% and transmission rate by 20%. When a Superconduct target takes Thunder God damage, all Superconduct targets receive electric elemental damage corresponding to the transmission rate.',
		zawakeEffectDesc_en = 'Thunder God: At the end of each major turn, deals electric elemental damage equal to 100% of own Magic Power to a random single enemy target. Each Thunder God attack has a #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# base chance to apply one stack of <Superconduct>, and a 10% chance to also apply <Paralysis> to the target\n#F10#\n#F40##L10#<Superconduct>: #L0#Can stack up to five times, each stack increases electric damage received by 5% and transmission rate by 20%. When a Superconduct target takes Thunder God damage, all Superconduct targets receive electric elemental damage corresponding to the transmission rate.',
		zawakeEffectDesc_th = 'เทียนลุ่ย: ทุกครั้งเมื่อสิ้นสุดรอบใหญ่ สร้างความเสียหายธาตุไฟฟ้าเท่ากับ 100% ของพลังเวทย์ของตัวเองแก่เป้าหมายเดี่ยวสุ่มของฝ่ายตรงข้าม การโจมตีแต่ละครั้งของเทียนลุ่ยมาพร้อมกับโอกาสพื้นฐาน #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ในการทำให้เป้าหมายได้รับหนึ่งชั้นของ <ซูเปอร์คอนดักต์> และมีโอกาส 10% ที่จะทำให้เกิด <อัมพาต> บนเป้าหมาย\n#F10#\n#F40##L10#<ซูเปอร์คอนดักต์>: #L0#สามารถซ้อนกันได้สูงสุดห้าชั้น แต่ละชั้นจะเพิ่มความเสียหายไฟฟ้าที่รับเข้ามา 5% และอัตราการแพร่กระจาย 20% เมื่อเป้าหมายซูเปอร์คอนดักต์ได้รับความเสียหายจากเทียนลุ่ย เป้าหมายซูเปอร์คอนดักต์ทั้งหมดจะได้รับความเสียหายธาตุไฟฟ้าตามอัตราการแพร่กระจาย',
		zawakeEffectDesc_in = 'Thiên Lôi: Setiap kali menyelesaikan giliran besar, memberikan kerusakan elemen listrik sebesar 100% dari Kekuatan Sihir sendiri pada satu target tunggal acak dari lawan. Setiap serangan Thiên Lôi memiliki #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# peluang dasar untuk memberikan satu tumpukan <Superkonduktor>, dan ada peluang 10% tambahan untuk memberikan <Kelumpuhan> pada target\n#F10#\n#F40##L10#<Superkonduktor>: #L0#Dapat ditumpuk hingga lima kali, setiap tumpukan meningkatkan 5% kerusakan listrik yang diterima dan 20% tingkat transmisi. Ketika target Superkonduktor menerima kerusakan Thiên Lôi, semua target Superkonduktor akan menerima kerusakan elemen listrik sesuai dengan tingkat transmisi',
		zawakeEffectDesc_ph = 'Thiên Lôi: Sa tuwing natatapos ang pangunahing turn, nagdudulot ng electric elemental damage na katumbas ng 100% ng sariling Magic Power sa isang random na enemy single target. Ang bawat atake ng Thiên Lôi ay may #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# base chance na magbigay ng isang stack ng <Superconduct>, at may 10% chance pa na makapagbigay ng <Paralysis> sa target\n#F10#\n#F40##L10#<Superconduct>: #L0#Maaaring mag-stack ng hanggang limang beses, bawat stack ay nagdaragdag ng 5% electric damage na natatanggap at 20% transmission rate. Kapag ang Superconduct target ay tumanggap ng Thiên Lôi damage, lahat ng Superconduct targets ay tutanggap ng electric elemental damage ayon sa transmission rate.',
		zawakeEffectDesc_ma = 'Thiên Lôi: Setiap kali mengakhiri giliran besar, menyebabkan kerosakan elemen elektrik sebanyak 100% Kuasa Sihir diri sendiri ke satu sasaran tunggal rawak musuh. Setiap serangan Thiên Lôi mempunyai #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# kebarangkalian asas untuk menyebabkan satu lapisan <Superkonduktor>, dan ada 10% kebarangkalian tambahan untuk menyebabkan <Kelumpuhan> kepada sasaran\n#F10#\n#F40##L10#<Superkonduktor>: #L0#Boleh bertindih sehingga lima lapisan, setiap lapisan Superkonduktor meningkatkan 5% kerosakan elektrik diterima dan 20% kadar penghantaran. Apabila sasaran Superkonduktor menerima kerosakan Thiên Lôi, semua sasaran Superkonduktor akan menerima kerosakan elemen elektrik yang bersamaan dengan kadar penghantaran',
		zawakeEffectDesc_vn = 'Thiên Lôi: Mỗi khi kết thúc lượt lớn, gây sát thương nguyên tố điện bằng 100% Công Phép bản thân lên một mục tiêu đơn ngẫu nhiên của đối phương, mỗi lần Thiên Lôi tấn công có #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# xác suất cơ bản khiến mục tiêu nhận một tầng <Siêu dẫn>, và có 10% xác suất thêm <Tê liệt> cho mục tiêu\n#F10#\n#F40##L10#<Siêu dẫn>: #L0#Có thể chồng tối đa năm tầng, mỗi tầng Siêu dẫn tăng 5% sát thương điện nhận vào và 20% tỷ lệ dẫn truyền, khi mục tiêu Siêu dẫn nhận sát thương Thiên Lôi, tất cả mục tiêu Siêu dẫn sẽ nhận sát thương nguyên tố điện tương ứng với tỷ lệ dẫn truyền',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#When attacking with lightning, 10% base chance to paralyze target for 1 turn#C0x5B545B#',
		zawakeSimpleDesc_en = '#C0x5c9970#When attacking with lightning, 10% base chance to paralyze target for 1 turn#C0x5B545B#',
		zawakeSimpleDesc_th = '#C0x5c9970#เมื่อโจมตีด้วยสายฟ้า มีโอกาสพื้นฐาน 10% ทำให้เป้าหมายเป็นอัมพาต 1 เทิร์น#C0x5B545B#',
		zawakeSimpleDesc_in = '#C0x5c9970#Saat menyerang dengan petir, memiliki 10% peluang dasar untuk melumpuhkan target selama 1 giliran#C0x5B545B#',
		zawakeSimpleDesc_ph = '#C0x5c9970#Kapag umatake gamit ang kidlat, may 10% base chance na ma-paralyze ang target sa loob ng 1 turn#C0x5B545B#',
		zawakeSimpleDesc_ma = '#C0x5c9970#Apabila menyerang dengan petir, ada 10% peluang asas untuk melumpuhkan sasaran selama 1 pusingan#C0x5B545B#',
		zawakeSimpleDesc_vn = '#C0x5c9970#Khi tấn công bằng sấm sét, có 10% xác suất cơ bản làm tê liệt mục tiêu trong 1 lượt#C0x5B545B#',
		iconRes = 'battle/skill_icon/skill_3356.png',
