	[3822] = {
		id = 3822,
		skillName_vn = 'Côn băng',
		skillName_en = 'Condensed ice',
		skillName_th = 'น้ำแข็งอัด',
		skillName_in = 'Es padat',
		skillName_ph = 'Pinatamis na yelo',
		skillName_ma = 'Ais pekat',
		skillName = 'Condensed ice',
		describe_vn = 'Shellder bắn ra nhiều mảnh băng tấn công mục tiêu đơn phía địch, gây ra #C0xE69900#160% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ Sát Thương Vật Lý#C0x5B545B#, giả vờ tấn công mục tiêu hàng trước nhưng thực tế đặt bẫy băng 3 lượt cho mục tiêu hàng sau (Bẫy băng: Trước khi hành động, mục tiêu mất sát thương thực bằng 60% phòng thủ vật lý của Shellder, sau khi hành động giảm 30% phòng thủ vật lý trong 1 lượt và có 20% xác suất bị [Đóng băng] trong 1 lượt)',
		describe_en = 'Shellder shoots multiple ice shards to attack a single enemy target, dealing #C0xE69900#160% Physical Attack#C0x5B545B# + $(skillLevel*4*48)$ Physical Damage#C0x5B545B#. It feigns an attack on the front row target but actually sets an ice trap on the back row target for 3 turns (Ice Trap: Before acting, the target takes real damage equal to 60% of Shellder\'s physical defense; after acting, the target\'s physical defense is reduced by 30% for 1 turn and has a 20% chance to be [Frozen] for 1 turn).',
		describe_th = 'เชลเดอร์ยิงเศษน้ำแข็งหลายชิ้นโจมตียูนิตศัตรูเดี่ยว สร้างความเสียหาย #C0xE69900#160% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*48)$ ความเสียหายทางกายภาพ#C0x5B545B# จำลองโจมตีเป้าหมายแถวหน้าแต่จริงๆ แล้ววางกับดักน้ำแข็งไว้ที่เป้าหมายแถวหลังเป็นเวลา 3 เทิร์น (กับดักน้ำแข็ง: ก่อนการกระทำ เป้าหมายจะได้รับความเสียหายจริงเท่ากับ 60% ของพลังป้องกันทางกายภาพของเชลเดอร์ หลังการกระทำลดพลังป้องกันทางกายภาพของเป้าหมายลง 30% เป็นเวลา 1 เทิร์น และมีโอกาส 20% ที่จะถูก [แช่แข็ง] เป็นเวลา 1 เทิร์น)',
		describe_in = 'Shellder menembakkan beberapa potongan es untuk menyerang satu target musuh, memberikan #C0xE69900#160% Serangan Fisik#C0x5B545B# + $(skillLevel*4*48)$ Kerusakan Fisik#C0x5B545B#. Ia berpura-pura menyerang target baris depan tetapi sebenarnya memasang jebakan es selama 3 giliran untuk target baris belakang (Jebakan Es: Sebelum bertindak, target menerima kerusakan nyata sebesar 60% pertahanan fisik Shellder; setelah bertindak, pertahanan fisik target berkurang 30% selama 1 giliran dan ada peluang 20% untuk terkena [Membeku] selama 1 giliran).',
		describe_ph = 'Ang Shellder ay nagpapaputok ng maraming piraso ng yelo upang atakihin ang isang target na kaaway, na nagdudulot ng #C0xE69900#160% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*48)$ Pisikal na Pinsala#C0x5B545B#. Nagpapanggap itong umatake sa target sa harapang hanay ngunit sa totoo ay naglalagay ng bitag ng yelo sa target sa likurang hanay sa loob ng 3 turn (Bitag ng Yelo: Bago kumilos, ang target ay makakatanggap ng totoong pinsala na katumbas ng 60% ng pisikal na depensa ni Shellder; pagkatapos kumilos, nababawasan ng 30% ang pisikal na depensa ng target sa loob ng 1 turn at may 20% pagkakataon na maging [Nafreeze] sa loob ng 1 turn).',
		describe_ma = 'Shellder melepaskan serpihan ais untuk menyerang satu sasaran musuh, memberikan #C0xE69900#160% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*48)$ Kerosakan Fizikal#C0x5B545B#. Ia berpura-pura menyerang sasaran barisan hadapan tetapi sebenarnya meletakkan perangkap ais selama 3 pusingan ke sasaran barisan belakang (Perangkap Ais: Sebelum bertindak, sasaran menerima kerosakan sebenar bersamaan 60% pertahanan fizikal Shellder; selepas bertindak, pertahanan fizikal sasaran berkurang 30% selama 1 pusingan dan ada 20% peluang untuk menjadi [Beku] selama 1 pusingan).',
		describe = 'Shellder shoots multiple ice shards to attack a single enemy target, dealing #C0xE69900#160% Physical Attack#C0x5B545B# + $(skillLevel*4*48)$ Physical Damage#C0x5B545B#. It feigns an attack on the front row target but actually sets an ice trap on the back row target for 3 turns (Ice Trap: Before acting, the target takes real damage equal to 60% of Shellder\'s physical defense; after acting, the target\'s physical defense is reduced by 30% for 1 turn and has a 20% chance to be [Frozen] for 1 turn).',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
