	[3823] = {
		id = 3823,
		skillName_vn = 'Va chạm nước băng',
		skillName_en = 'Ice water collision',
		skillName_th = 'การชนของน้ำแข็ง',
		skillName_in = 'Tabrakan air es',
		skillName_ph = 'Banggaan ng yelong tubig',
		skillName_ma = 'Perlanggaran air ais',
		skillName = 'Ice water collision',
		describe_vn = 'Shellder nhảy lên từ nước, lăn và va chạm vào toàn bộ mục tiêu phía địch, gây ra #C0xE69900#160% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ Sát Thương Vật Lý#C0x5B545B#, có 80% xác suất khiến mục tiêu hàng sau rơi vào bẫy băng trong 2 lượt, nếu đã ở trong bẫy băng thì có 100% xác suất [Đóng băng] mục tiêu trong 2 lượt, đồng thời tăng 100% phòng thủ vật lý trong 1 lượt, sau đó rút vào vỏ tạo thành lá chắn bảo vệ cho đến lượt tiếp theo của bản thân (Lá chắn có tổng máu bằng 3000% phòng thủ vật lý ban đầu của Shellder, khi máu lá chắn bằng 0 thì không thể rút vào vỏ)',
		describe_en = 'Shellder jumps out of the water, rolls, and collides with all enemy targets, dealing #C0xE69900#160% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ Physical Damage#C0x5B545B#. There is an 80% chance to trap rear row targets in an ice trap for 2 turns. If the target is already trapped, there is a 100% chance to [Freeze] the target for 2 turns, simultaneously increasing physical defense by 100% for 1 turn, then Shellder retreats into its shell to form a shield until its next turn (Shield HP equals 3000% of Shellder\'s base physical defense; when shield HP reaches 0, it can no longer retreat into the shell).',
		describe_th = 'Shellder กระโดดขึ้นมาจากน้ำ หมุนกลิ้งและชนเป้าหมายฝ่ายศัตรูทั้งหมด ก่อให้เกิด #C0xE69900#160% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*36)$ ความเสียหายทางกายภาพ#C0x5B545B#. มีโอกาส 80% ที่จะทำให้เป้าหมายแถวหลังติดกับดักน้ำแข็งเป็นเวลา 2 เทิร์น หากเป้าหมายติดกับดักน้ำแข็งอยู่แล้ว มีโอกาส 100% ที่จะ [แช่แข็ง] เป้าหมายเป็นเวลา 2 เทิร์น พร้อมทั้งเพิ่มเกราะกายภาพ 100% เป็นเวลา 1 เทิร์น จากนั้น Shellder จะถอยเข้ากระดองเพื่อสร้างโล่คุ้มกันจนถึงเทิร์นถัดไปของตนเอง (โล่มีพลังชีวิตเท่ากับ 3000% ของเกราะกายภาพเริ่มต้นของ Shellder เมื่อพลังชีวิตโล่เหลือ 0 จะไม่สามารถถอยเข้ากระดองได้)',
		describe_in = 'Shellder melompat dari air, berguling, dan menabrak semua target musuh, menyebabkan #C0xE69900#160% Serangan Fisik#C0x5B545B# + $(skillLevel*4*36)$ Kerusakan Fisik#C0x5B545B#. Ada peluang 80% untuk menjebak target barisan belakang dalam perangkap es selama 2 giliran. Jika target sudah dalam perangkap es, ada peluang 100% untuk [Membekukan] target selama 2 giliran, sekaligus meningkatkan pertahanan fisik sebesar 100% selama 1 giliran, kemudian Shellder mundur ke cangkangnya membentuk perisai pelindung hingga giliran berikutnya (Perisai memiliki HP total sebesar 3000% pertahanan fisik awal Shellder; saat HP perisai 0, tidak bisa mundur ke cangkang).',
		describe_ph = 'Tumalon si Shellder mula sa tubig, rinaroll at bumangga sa lahat ng kalaban, na nagdudulot ng #C0xE69900#160% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ Physical Damage#C0x5B545B#. May 80% na tsansa na mahuli sa ice trap ang mga target sa likurang hanay sa loob ng 2 turn. Kung ang target ay nasa ice trap na, may 100% tsansa na [Mag-freeze] ng target sa loob ng 2 turn, sabay tumaas ng 100% ang physical defense sa loob ng 1 turn, pagkatapos ay umatras si Shellder papasok sa kanyang shell upang bumuo ng shield hanggang sa susunod niyang turn (Ang shield ay may total HP na katumbas ng 3000% ng base physical defense ni Shellder; kapag ang shield HP ay 0, hindi na siya makakapasok sa shell).',
		describe_ma = 'Shellder melompat keluar dari air, berguling dan bertembung dengan semua sasaran musuh, menyebabkan #C0xE69900#160% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*36)$ Kerosakan Fizikal#C0x5B545B#. Terdapat peluang 80% untuk menyebabkan sasaran barisan belakang terperangkap dalam perangkap ais selama 2 pusingan. Jika sasaran sudah berada dalam perangkap ais, terdapat peluang 100% untuk [Membekukan] sasaran selama 2 pusingan, serta meningkatkan pertahanan fizikal sebanyak 100% selama 1 pusingan, kemudian Shellder berundur ke dalam cangkerangnya membentuk perisai perlindungan sehingga giliran berikutnya (Perisai mempunyai jumlah darah sebanyak 3000% pertahanan fizikal asal Shellder; apabila darah perisai mencecah 0, tidak dapat berundur ke dalam cangkerang).',
		describe = 'Shellder jumps out of the water, rolls, and collides with all enemy targets, dealing #C0xE69900#160% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ Physical Damage#C0x5B545B#. There is an 80% chance to trap rear row targets in an ice trap for 2 turns. If the target is already trapped, there is a 100% chance to [Freeze] the target for 2 turns, simultaneously increasing physical defense by 100% for 1 turn, then Shellder retreats into its shell to form a shield until its next turn (Shield HP equals 3000% of Shellder\'s base physical defense; when shield HP reaches 0, it can no longer retreat into the shell).',
		simDesc_vn = 'Cloyster nhảy lên từ mặt nước, lăn vào toàn bộ mục tiêu của đối phương, có khả năng làm mục tiêu rơi vào bẫy băng, sau đó thu mình vào vỏ để tự bảo vệ.',
		simDesc_en = 'Cloyster leaps out of the water, rolling over all enemy targets, with the ability to trap them in ice, then withdraws into its shell to protect itself.',
		simDesc_th = 'Cloyster กระโดดขึ้นจากน้ำ กลิ้งใส่เป้าหมายทั้งหมดของศัตรู มีความสามารถทำให้เป้าหมายติดกับดักน้ำแข็ง จากนั้นหดตัวกลับเข้าหุ้มเปลือกเพื่อป้องกันตัวเอง',
		simDesc_in = 'Cloyster meloncat keluar dari air, menggulung ke seluruh target musuh, dengan kemampuan menjebak target dalam es, lalu menarik diri ke dalam cangkangnya untuk melindungi diri.',
		simDesc_ph = 'Tumalon si Cloyster mula sa tubig, umikot sa lahat ng mga kalabang target, may kakayahang i-trap ang mga ito sa yelo, pagkatapos ay umatras sa kanyang balat upang iprotekta ang sarili.',
		simDesc_ma = 'Cloyster melompat keluar dari air, menggulung ke semua sasaran musuh, dengan keupayaan untuk menjebak sasaran dalam ais, kemudian menarik diri ke dalam cengkerangnya untuk melindungi diri.',
		simDesc = 'Cloyster leaps out of the water, rolling over all enemy targets, with the ability to trap them in ice, then withdraws into its shell to protect itself.',
		starEffect = __data_t__starEffect[3823],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Trong thời gian thu mình, tăng 20% hiệu ứng giảm sát thương.',
		starEffectDesc = 'Additional effect: During the shrinking period, increase damage reduction effect by 20%.',
		starEffectDesc_en = 'Additional effect: During the shrinking period, increase damage reduction effect by 20%.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: ในช่วงเวลาหดตัว เพิ่มผลการลดความเสียหายขึ้น 20%',
		starEffectDesc_in = 'Efek tambahan: Selama periode mengecil, tingkatkan efek pengurangan kerusakan sebesar 20%.',
		starEffectDesc_ph = 'Karagdagang epekto: Sa panahon ng pagliit, dagdagan ang 20% epekto ng pagbabawas ng pinsala.',
		starEffectDesc_ma = 'Kesan tambahan: Semasa tempoh mengecil, tingkatkan kesan pengurangan kerosakan sebanyak 20%.',
