	[3911] = {
		id = 3911,
		skillName_vn = 'Tấn công bóng ma',
		skillName_en = 'Phantom attack',
		skillName_th = 'การโจมตีภูตผี',
		skillName_in = 'Serangan hantu',
		skillName_ph = 'Labanan ng multo',
		skillName_ma = 'Serangan hantu',
		skillName = 'Phantom attack',
		describe_vn = 'Gastly hóa thân thành hồn ma tấn công mục tiêu đơn phía địch, gây ra #C0x3D8A99#80% Công Phép thuật#C0x5B545B#+$(skillLevel*4*24)$ Sát Thương Phép Thuật#C0x5B545B#, có 30% xác suất khiến mục tiêu rơi vào trạng thái [Sợ hãi]',
		describe_en = 'Gastly transforms into a ghost to attack a single enemy target, dealing 80% Magic Power + $(skillLevel*4*24)$ Magic Damage, with a 30% chance to inflict [Fear] status.',
		describe_th = 'Gastly แปลงร่างเป็นผีโจมตีศัตรูเป้าหมายเดี่ยว สร้างความเสียหายเวท 80% + $(skillLevel*4*24)$ พร้อมโอกาส 30% ที่จะทำให้เป้าหมายติดสถานะ [กลัว]',
		describe_in = 'Gastly berubah menjadi hantu menyerang satu target musuh, memberikan 80% Kekuatan Sihir + $(skillLevel*4*24)$ Kerusakan Sihir, dengan peluang 30% menyebabkan target mengalami status [Takut].',
		describe_ph = 'Si Gastly ay nagiging espiritu para atakihin ang isang kalaban, nagdudulot ng 80% Magic Power + $(skillLevel*4*24)$ Magic Damage, may 30% tsansa na gawin ang target na magkaroon ng estado na [Takot].',
		describe_ma = 'Gastly bertukar menjadi hantu menyerang sasaran musuh tunggal, memberikan 80% Kuasa Sihir + $(skillLevel*4*24)$ Kerosakan Sihir, dengan peluang 30% menyebabkan sasaran terkena status [Takut].',
		describe = 'Gastly transforms into a ghost to attack a single enemy target, dealing 80% Magic Power + $(skillLevel*4*24)$ Magic Damage, with a 30% chance to inflict [Fear] status.',
		simDesc_vn = 'Gastly biến thành hồn ma tấn công mục tiêu đơn lẻ của đối phương.',
		simDesc_en = 'Gastly transforms into a ghost to attack a single enemy target.',
		simDesc_th = 'แกสท์ลี่แปลงร่างเป็นผีเพื่อโจมตีเป้าหมายเดียวของศัตรู',
		simDesc_in = 'Gastly berubah menjadi hantu untuk menyerang satu target musuh.',
		simDesc_ph = 'Nagbabago si Gastly sa isang multo upang atakihin ang isang target na kalaban.',
		simDesc_ma = 'Gastly berubah menjadi hantu untuk menyerang satu sasaran musuh.',
		simDesc = 'Gastly transforms into a ghost to attack a single enemy target.',
		zawakeEffect = __data_t__zawakeEffect[3911],
		-- {79001}
		zawakeEffectDesc = 'Gastly transforms into a ghost and attacks a single enemy target, dealing #C0x3D8A99#80% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 40% chance to cause the target to fall into <Fear>',
		zawakeEffectDesc_en = 'Gastly transforms into a ghost and attacks a single enemy target, dealing #C0x3D8A99#80% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 40% chance to cause the target to fall into <Fear>',
		zawakeEffectDesc_th = 'Gastly แปลงร่างเป็นผีและโจมตีเป้าหมายศัตรูเดี่ยว ก่อให้เกิดความเสียหายทางเวทมนตร์ #C0x3D8A99#80% พลังเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# พร้อมโอกาส 40% ที่จะทำให้เป้าหมายติดสถานะ <กลัว>',
