	[3942] = {
		id = 3942,
		skillName_vn = 'Tia bóng tối',
		skillName_en = 'Shadow Ray',
		skillName_th = 'ลำแสงเงามืด',
		skillName_in = 'Sinar Bayangan',
		skillName_ph = 'Sinag ng Anino',
		skillName_ma = 'Sinar Bayangan',
		skillName = 'Shadow Ray',
		describe_vn = 'Super Gengar phóng một tia bóng vào một mục tiêu kẻ thù, gây ra #C0x3D8A99#160% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#sát thương ma thuật#C0x5B545B#. Nếu giá trị máu vượt quá 50%, có 100% khả năng khiến mục tiêu rơi vào trạng thái [Sợ hãi] trong 2 lượt; nếu giá trị sức khỏe của bản thân nhỏ hơn 50%, một lượng giá trị sức khỏe nhất định sẽ được hấp thụ từ mục tiêu (lượng hấp thụ: 30% Sát Thương Phép Thuật của Super Gengar, sát thương là sát thương thực sự) và có 40% xác suất khiến mục tiêu sợ hãi, lượng máu hút sẽ tăng gấp đôi khi tấn công mục tiêu sợ hãi.',
		describe_en = 'Super Gengar shoots a shadow beam at an enemy target, dealing #C0x3D8A99#160% Magic Damage#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# magic damage #C0x5B545B#. If the target\'s HP is above 50%, there is a 100% chance to cause the target to enter the [Fear] state for 2 turns; if Super Gengar\'s own HP is below 50%, a certain amount of HP will be absorbed from the target (absorption amount: 30% of Super Gengar\'s Magic Damage, damage is true damage) and there is a 40% chance to cause the target to be feared. The amount of HP drained doubles when attacking a feared target.',
		describe_th = 'ซูเปอร์เก็งก้าส่งลำแสงเงาไปยังศัตรูเป้าหมาย สร้าง #C0x3D8A99#160% พลังเวท#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# ดาเมจเวท #C0x5B545B# หากค่า HP ของเป้าหมายสูงกว่า 50% จะมีโอกาส 100% ที่จะทำให้เป้าหมายตกอยู่ในสถานะ [หวาดกลัว] เป็นเวลา 2 เทิร์น; หากค่า HP ของซูเปอร์เก็งก้าต่ำกว่า 50% จะดูดเลือดจากเป้าหมายจำนวนหนึ่ง (ปริมาณดูดเลือด: 30% ของพลังเวทของซูเปอร์เก็งก้า ความเสียหายเป็นความเสียหายจริง) และมีโอกาส 40% ที่จะทำให้เป้าหมายหวาดกลัว จำนวนเลือดที่ดูดจะเพิ่มเป็นสองเท่าเมื่อโจมตีเป้าหมายที่หวาดกลัว',
		describe_in = 'Super Gengar menembakkan sinar bayangan ke musuh target, menyebabkan #C0x3D8A99#160% Damage Sihir#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# damage sihir #C0x5B545B#. Jika nilai HP target lebih dari 50%, ada kemungkinan 100% untuk membuat target masuk ke status [Takut] selama 2 giliran; jika nilai HP Super Gengar sendiri kurang dari 50%, sejumlah HP tertentu akan diserap dari target (jumlah yang diserap: 30% Damage Sihir Super Gengar, damage ini adalah damage nyata) dan ada peluang 40% untuk membuat target takut. Jumlah HP yang diserap akan berlipat ganda saat menyerang target yang takut.',
		describe_ph = 'Ang Super Gengar ay nagpapalabas ng isang sinag ng anino sa isang kalaban na target, nagdudulot ng #C0x3D8A99#160% Magic Damage#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# magic damage #C0x5B545B#. Kung ang halaga ng HP ng target ay higit sa 50%, may 100% na pagkakataon na mapapasailalim ang target sa estado ng [Takot] sa loob ng 2 turn; kung ang HP ng Super Gengar ay mas mababa sa 50%, isang tiyak na halaga ng HP ang masisipsip mula sa target (halaga ng pagsipsip: 30% ng Magic Damage ng Super Gengar, ang damage ay tunay na damage) at may 40% na pagkakataon na matakot ang target. Ang halaga ng HP na nasisipsip ay dodoble kapag inaatake ang takot na target.',
		describe_ma = 'Super Gengar menembak sinar bayangan ke sasaran musuh, menyebabkan #C0x3D8A99#160% Kerosakan Magik#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# kerosakan magik #C0x5B545B#. Jika nilai HP sasaran melebihi 50%, terdapat peluang 100% untuk menyebabkan sasaran memasuki keadaan [Takut] selama 2 giliran; jika nilai HP Super Gengar sendiri kurang daripada 50%, sejumlah HP tertentu akan diserap daripada sasaran (jumlah yang diserap: 30% Kerosakan Magik Super Gengar, kerosakan adalah kerosakan sebenar) dan terdapat peluang 40% untuk menyebabkan sasaran takut. Jumlah HP yang diserap akan berganda apabila menyerang sasaran yang takut.',
		describe = 'Super Gengar shoots a shadow beam at an enemy target, dealing #C0x3D8A99#160% Magic Damage#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# magic damage #C0x5B545B#. If the target\'s HP is above 50%, there is a 100% chance to cause the target to enter the [Fear] state for 2 turns; if Super Gengar\'s own HP is below 50%, a certain amount of HP will be absorbed from the target (absorption amount: 30% of Super Gengar\'s Magic Damage, damage is true damage) and there is a 40% chance to cause the target to be feared. The amount of HP drained doubles when attacking a feared target.',
		simDesc_vn = 'Super Gengar bắn một tia bóng vào một mục tiêu kẻ thù.',
		simDesc_en = 'Super Gengar shoots a shadow beam at an enemy target.',
		simDesc_th = 'ซูเปอร์เก็งการ์ยิงลำแสงเงาใส่เป้าหมายศัตรู',
		simDesc_in = 'Super Gengar menembakkan sinar bayangan ke target musuh.',
		simDesc_ph = 'Super Gengar ay nagpapaputok ng shadow beam sa isang kalaban.',
		simDesc_ma = 'Super Gengar melepaskan pancaran bayang ke sasaran musuh.',
		simDesc = 'Super Gengar shoots a shadow beam at an enemy target.',
		zawakeEffect = __data_t__zawakeEffect[3942],
		-- {79002}
		zawakeEffectDesc = 'Mega Gengar fires a dark beam at a single enemy target, dealing #C0x3D8A99#160% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ magic damage#C0xF13B54#; if own HP exceeds 50%, there is a 100% chance to cause the target to enter <Fear> state for 2 turns; if own HP is below 50%, it will drain a certain amount of HP from the target (drain amount: Mega Gengar\'s 50% Magic Power, this damage is true damage), when attacking a feared target, the HP drain will double',
		zawakeEffectDesc_en = 'Mega Gengar fires a dark beam at a single enemy target, dealing #C0x3D8A99#160% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ magic damage#C0xF13B54#; if own HP exceeds 50%, there is a 100% chance to cause the target to enter <Fear> state for 2 turns; if own HP is below 50%, it will drain a certain amount of HP from the target (drain amount: Mega Gengar\'s 50% Magic Power, this damage is true damage), when attacking a feared target, the HP drain will double',
		zawakeEffectDesc_th = 'Mega Gengar ยิงลำแสงแห่งความมืดไปยังเป้าหมายศัตรูเดี่ยวก่อให้เกิดความเสียหายเวท #C0x3D8A99#160% พลังเวท#C0x5B545B#+$(skillLevel*4*48)$ ความเสียหายเวท#C0xF13B54#; หากพลังชีวิตของตัวเองเกิน 50% มีโอกาส 100% ที่จะทำให้เป้าหมายตกอยู่ในสถานะ <กลัว> เป็นเวลา 2 เทิร์น; หากพลังชีวิตของตัวเองต่ำกว่า 50% จะดูดพลังชีวิตจากเป้าหมาย (ปริมาณที่ดูด: 50% พลังเวทของ Mega Gengar ความเสียหายนี้เป็นความเสียจริง) เมื่อโจมตีเป้าหมายที่ตกอยู่ในสถานะกลัว การดูดพลังชีวิตจะเพิ่มเป็นสองเท่า',
		zawakeEffectDesc_in = 'Mega Gengar menembakkan sinar gelap ke satu target musuh, menyebabkan #C0x3D8A99#160% Kekuatan Magis#C0x5B545B#+$(skillLevel*4*48)$ kerusakan magis#C0xF13B54#; jika HP sendiri melebihi 50%, ada 100% kemungkinan membuat target masuk ke <Takut> selama 2 giliran; jika HP sendiri kurang dari 50%, akan menyedot sejumlah HP dari target (jumlah yang disedot: 50% Kekuatan Magis Mega Gengar, kerusakan ini adalah kerusakan nyata), saat menyerang target yang takut, jumlah penyedotan HP akan menjadi dua kali lipat',
		zawakeEffectDesc_ph = 'Mega Gengar ay nagpapaputok ng isang sinag ng kadiliman sa isang solong target na kalaban, nagdudulot ng #C0x3D8A99#160% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ magic damage#C0xF13B54#; kung ang sariling HP ay higit sa 50%, may 100% tsansa na magdulot sa target na mapasailalim sa <Takot> na estado sa loob ng 2 round; kung ang sariling HP ay nasa ilalim ng 50%, huhugutin nito ang isang tiyak na halaga ng HP mula sa target (halaga ng paghugot: 50% Magic Power ni Mega Gengar, ang damage na ito ay totoong damage), kapag inaatake ang takot na target, ang pag-ubos ng HP ay magiging doble',
		zawakeEffectDesc_ma = 'Mega Gengar menembak sinar gelap ke satu sasaran musuh, menyebabkan #C0x3D8A99#160% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$ kerosakan sihir#C0xF13B54#; jika HP sendiri melebihi 50%, terdapat peluang 100% untuk menyebabkan sasaran berada dalam keadaan <Takut> selama 2 giliran; jika HP sendiri kurang daripada 50%, akan menyedut sejumlah HP dari sasaran (jumlah sedutan: 50% Kuasa Sihir Mega Gengar, kerosakan ini adalah kerosakan sebenar), ketika menyerang sasaran yang takut, jumlah sedutan HP akan berganda',
		zawakeEffectDesc_vn = 'Mega Gengar bắn một tia bóng tối vào mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#160% Công Phép#C0x5B545B#+$(skillLevel*4*48)$ sát thương phép#C0xF13B54#; nếu máu của bản thân vượt quá 50%, có 100% xác suất khiến mục tiêu rơi vào trạng thái <Sợ hãi> trong 2 lượt; nếu máu của bản thân dưới 50%, sẽ hút một lượng máu nhất định từ mục tiêu (lượng hút: Mega Gengar 50% Công Phép, sát thương này là sát thương thực), khi tấn công mục tiêu bị sợ hãi, lượng hút máu sẽ tăng gấp đôi',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Lifesteal amount increased to 50% of Magic ATK',
		zawakeSimpleDesc_en = '#C0x5c9970#Lifesteal amount increased to 50% of Magic ATK',
		zawakeSimpleDesc_th = '#C0x5c9970#ดูดเลือดเพิ่มขึ้นเป็น 50% ของพลังเวท',
		zawakeSimpleDesc_in = '#C0x5c9970#Lifesteal meningkat hingga 50% dari Magic ATK',
