	[3962] = {
		id = 3962,
		skillName_vn = 'Cầu ma',
		skillName_en = 'Demon Bridge',
		skillName_th = 'สะพานปีศาจ',
		skillName_in = 'Jembatan Iblis',
		skillName_ph = 'Tulay ng Demonyo',
		skillName_ma = 'Jambatan Syaitan',
		skillName = 'Demon Bridge',
		describe_vn = 'Siêu Gengar vung kính viễn vọng tung quả cầu ma tấn công mục tiêu đơn địch, gây ra #C0x3D8A99#160% Công Phép#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, nếu máu bản thân vượt quá 50%, có 100% xác suất khiến mục tiêu rơi vào trạng thái [Sợ hãi] trong 2 lượt; nếu máu bản thân dưới 50%, sẽ hút một lượng máu nhất định từ mục tiêu (lượng hút: Siêu Gengar 30% Công Phép, sát thương này là sát thương thực), và có 40% xác suất khiến mục tiêu sợ hãi, khi tấn công mục tiêu bị sợ hãi lượng hút máu sẽ tăng gấp đôi',
		describe_en = 'Super Gengar swings the telescope to launch a ghostly orb attacking a single enemy target, dealing #C0x3D8A99#160% Magic Power#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#. If its own HP is above 50%, there is a 100% chance to cause the target to enter the [Fear] state for 2 turns; if its own HP is below 50%, it will drain a certain amount of HP from the target (drain amount: Super Gengar\'s 30% Magic Power, this damage is true damage), and there is a 40% chance to make the target fearful. When attacking a fearful target, the HP drain amount is doubled.',
		describe_th = 'ซูเปอร์เก็งการ์แกว่งกล้องโทรทรรศน์ปล่อยวงบอลผีโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#160%#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# หาก HP ของตัวเองสูงกว่า 50% มีโอกาส 100% ที่จะทำให้เป้าหมายติดสถานะ [กลัว] เป็นเวลา 2 เทิร์น หาก HP ของตัวเองต่ำกว่า 50% จะดูดเลือดจากเป้าหมายจำนวนหนึ่ง (ปริมาณดูด: ซูเปอร์เก็งการ์ 30% พลังเวทมนตร์ ความเสียหายนี้ถือเป็นความเสียหายจริง) และมีโอกาส 40% ที่จะทำให้เป้าหมายกลัว เมื่อโจมตีเป้าหมายที่กลัว ปริมาณเลือดที่ดูดจะเพิ่มเป็นสองเท่า',
		describe_in = 'Super Gengar mengayunkan teleskop dan meluncurkan bola hantu yang menyerang satu musuh, menyebabkan #C0x3D8A99#160% Kekuatan Sihir#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Jika HP sendiri lebih dari 50%, ada peluang 100% untuk menyebabkan target mengalami status [Takut] selama 2 giliran; jika HP sendiri kurang dari 50%, akan menyerap sejumlah HP dari target (jumlah serapan: Super Gengar 30% Kekuatan Sihir, kerusakan ini adalah kerusakan nyata), dan ada peluang 40% untuk membuat target takut. Saat menyerang target yang takut, jumlah serapan HP akan meningkat dua kali lipat.',
		describe_ph = 'Siuper Gengar ayawing ang teleskopyo at bumato ng isang bola ng multo na umaatake sa isang target na kalaban, nagdudulot ng #C0x3D8A99#160% Magic Power#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#. Kung ang sariling HP ay higit sa 50%, may 100% tsansang magdulot sa target na mapabilang sa estado ng [Takot] sa loob ng 2 turn; kung ang sariling HP ay mababa sa 50%, hahawa ito ng tiyak na dami ng HP mula sa target (damang hinahawa: Siuper Gengar 30% Magic Power, ang pinsalang ito ay tunay na pinsala), at may 40% tsansa na magdulot sa target na matakot. Kapag inaatake ang takot na target, ang dami ng hihinang HP ay dodoblehin.',
		describe_ma = 'Super Gengar mengayunkan teleskop dan melancarkan bola hantu yang menyerang satu musuh sasaran, menyebabkan #C0x3D8A99#160% Kuasa Sihir#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Jika HP sendiri melebihi 50%, terdapat peluang 100% untuk menyebabkan sasaran mengalami keadaan [Takut] selama 2 pusingan; jika HP sendiri di bawah 50%, ia akan menyedut sejumlah darah tertentu dari sasaran (jumlah sedutan: Super Gengar 30% Kuasa Sihir, kerosakan ini adalah kerosakan sebenar), dan terdapat peluang 40% untuk menyebabkan sasaran takut. Apabila menyerang sasaran yang takut, jumlah sedutan darah akan meningkat dua kali ganda.',
		describe = 'Super Gengar swings the telescope to launch a ghostly orb attacking a single enemy target, dealing #C0x3D8A99#160% Magic Power#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#. If its own HP is above 50%, there is a 100% chance to cause the target to enter the [Fear] state for 2 turns; if its own HP is below 50%, it will drain a certain amount of HP from the target (drain amount: Super Gengar\'s 30% Magic Power, this damage is true damage), and there is a 40% chance to make the target fearful. When attacking a fearful target, the HP drain amount is doubled.',
		zawakeEffect = __data_t__zawakeEffect[3962],
		-- {79002}
		zawakeEffectDesc = 'Mega Gengar fires a single dark beam at a single enemy target, dealing #C0x3D8A99#160% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ magic damage#C0xF13B54#; if its own HP exceeds 50%, there is a 100% chance to cause the target to enter the <Fear> state for 2 turns; if its own HP is below 50%, it will drain a certain amount of HP from the target (drain amount: Mega Gengar 50% Magic Power, this damage is true damage), when attacking a feared target, the drained HP will be doubled',
		zawakeEffectDesc_en = 'Mega Gengar fires a single dark beam at a single enemy target, dealing #C0x3D8A99#160% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ magic damage#C0xF13B54#; if its own HP exceeds 50%, there is a 100% chance to cause the target to enter the <Fear> state for 2 turns; if its own HP is below 50%, it will drain a certain amount of HP from the target (drain amount: Mega Gengar 50% Magic Power, this damage is true damage), when attacking a feared target, the drained HP will be doubled',
		zawakeEffectDesc_th = 'Mega Gengar ยิงลำแสงความมืดหนึ่งครั้งไปยังเป้าหมายเดียวของศัตรู สร้าง #C0x3D8A99#160% พลังเวท#C0x5B545B#+$(skillLevel*4*48)$ ความเสียหายเวท#C0xF13B54#; หากพลังชีวิตเกิน 50% จะมีโอกาส 100% ที่ทำให้เป้าหมายเข้าสู่สถานะ <กลัว> เป็นเวลา 2 เทิร์น; หากพลังชีวิตต่ำกว่า 50% จะดูดพลังชีวิตบางส่วนจากเป้าหมาย (ปริมาณการดูด: Mega Gengar 50% พลังเวท, ความเสียหายนี้เป็นความเสียหายจริง), เมื่อโจมตีเป้าหมายที่อยู่ในสถานะกลัว, การดูดพลังชีวิตจะเพิ่มเป็นสองเท่า',
		zawakeEffectDesc_in = 'Mega Gengar menembakkan satu sinar gelap ke satu target musuh tunggal, menyebabkan #C0x3D8A99#160% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*48)$ kerusakan sihir#C0xF13B54#; jika HP sendiri melebihi 50%, ada 100% kemungkinan membuat target masuk ke kondisi <Takut> selama 2 giliran; jika HP sendiri di bawah 50%, akan menyerap sejumlah HP tertentu dari target (jumlah serapan: Mega Gengar 50% Kekuatan Sihir, kerusakan ini adalah kerusakan nyata), saat menyerang target yang takut, jumlah HP yang diserap akan meningkat dua kali lipat',
		zawakeEffectDesc_ph = 'Mega Gengar ay nagpapaputok ng isang sinag ng kadiliman sa isang nag-iisang target na kalaban, nagdudulot ng #C0x3D8A99#160% Lakas ng Mahika#C0x5B545B#+$(skillLevel*4*48)$ pinsalang mahika#C0xF13B54#; kung ang sarili nitong HP ay higit sa 50%, may 100% tsansa na mapapasok ang target sa estado ng <Takot> sa loob ng 2 turn; kung ang sarili nitong HP ay mababa sa 50%, huhugot ito ng tiyak na dami ng HP mula sa target (halaga ng paghugot: Mega Gengar 50% Lakas ng Mahika, ang pinsalang ito ay totoong pinsala), kapag inaatake ang target na natatakot, ang dami ng nahugot na HP ay dodoblehin',
		zawakeEffectDesc_ma = 'Mega Gengar melepaskan satu pancaran gelap ke satu sasaran musuh tunggal, menyebabkan #C0x3D8A99#160% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$ kerosakan sihir#C0xF13B54#; jika HP sendiri melebihi 50%, terdapat 100% kemungkinan menyebabkan sasaran memasuki keadaan <Takut> selama 2 giliran; jika HP sendiri di bawah 50%, ia akan menyerap sejumlah HP tertentu daripada sasaran (jumlah serapan: Mega Gengar 50% Kuasa Sihir, kerosakan ini adalah kerosakan sebenar), apabila menyerang sasaran yang takut, jumlah HP yang diserap akan berganda',
		zawakeEffectDesc_vn = 'Mega Gengar bắn một tia bóng tối vào mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#160% Công Phép#C0x5B545B#+$(skillLevel*4*48)$ sát thương phép#C0xF13B54#; nếu máu của bản thân vượt quá 50%, có 100% xác suất khiến mục tiêu rơi vào trạng thái <Sợ hãi> trong 2 lượt; nếu máu của bản thân dưới 50%, sẽ hút một lượng máu nhất định từ mục tiêu (lượng hút: Mega Gengar 50% Công Phép, sát thương này là sát thương thực), khi tấn công mục tiêu bị sợ hãi, lượng hút máu sẽ tăng gấp đôi',
