	[4013] = {
		id = 4013,
		skillName_vn = 'Đánh chí mạng đá',
		skillName_en = 'Critical hit stone',
		skillName_th = 'หินโจมตีวิกฤต',
		skillName_in = 'Batu serangan kritis',
		skillName_ph = 'Bato ng kritikal na tama',
		skillName_ma = 'Batu serangan kritikal',
		skillName = 'Critical hit stone',
		describe_vn = 'Đại Nham Xà lắc mình gây chấn động mạnh lên không khí và mặt đất, gây sát thương #C0xE69900#160% Công Vật Lý#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B# lên toàn bộ mục tiêu kẻ địch, nếu tốc độ bản thân và mục tiêu càng chênh lệch, sát thương lần này càng cao, tối đa không vượt quá 30%',
		describe_en = 'The Great Lava Serpent shakes its body, causing a powerful shockwave through the air and ground, dealing #C0xE69900#160% Physical Attack#C0x5B545B# + $(skillLevel*4*30)$ #C0xF13B54# Physical Damage#C0x5B545B# to all enemy targets. The greater the speed difference between the user and the targets, the higher the damage dealt, capped at a maximum of 30%.',
		describe_th = 'งูไฟยักษ์สั่นตัวก่อให้เกิดคลื่นกระแทกอย่างรุนแรงในอากาศและพื้นดิน สร้างความเสียหาย #C0xE69900#160% การโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*30)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# แก่เป้าหมายศัตรูทั้งหมด ยิ่งความแตกต่างของความเร็วระหว่างตัวเองกับเป้าหมายมากเท่าไร ความเสียหายยิ่งสูงขึ้นสูงสุดไม่เกิน 30%',
		describe_in = 'Ular Lava Besar menggoyangkan tubuhnya, menimbulkan gelombang kejut kuat di udara dan tanah, memberikan kerusakan #C0xE69900#160% Serangan Fisik#C0x5B545B# + $(skillLevel*4*30)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B# kepada semua musuh. Semakin besar perbedaan kecepatan antara pengguna dan target, semakin besar kerusakan yang diberikan, maksimal hingga 30%.',
		describe_ph = 'Ang Dakilang Lava Ahas ay yumugyog, nagdudulot ng malakas na shockwave sa hangin at lupa, na nagdudulot ng #C0xE69900#160% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*30)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B# sa lahat ng mga kalabang target. Kapag mas malaki ang pagkakaiba sa bilis ng sarili at target, mas mataas ang pinsalang matatamo, na may maximum na 30% lamang.',
		describe_ma = 'Ular Lava Besar menggoyangkan badannya, menghasilkan gelombang kejutan yang kuat di udara dan tanah, menyebabkan kerosakan #C0xE69900#160% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*30)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B# kepada semua musuh. Semakin besar perbezaan kelajuan antara diri sendiri dan sasaran, semakin tinggi kerosakan kali ini, maksimum tidak melebihi 30%.',
		describe = 'The Great Lava Serpent shakes its body, causing a powerful shockwave through the air and ground, dealing #C0xE69900#160% Physical Attack#C0x5B545B# + $(skillLevel*4*30)$ #C0xF13B54# Physical Damage#C0x5B545B# to all enemy targets. The greater the speed difference between the user and the targets, the higher the damage dealt, capped at a maximum of 30%.',
		simDesc_vn = 'Onix lắc lư cơ thể tạo ra chấn động mạnh vào mặt đất, gây sát thương cho toàn bộ mục tiêu của đối phương, nếu tốc độ của bản thân chênh lệch lớn hơn tốc độ của mục tiêu thì sát thương sẽ cao hơn.',
		simDesc_en = 'Onix sways its body to create a strong shockwave on the ground, dealing damage to all enemy targets. If its speed significantly exceeds that of the target, the damage dealt will be higher.',
		simDesc_th = 'ออนไิกซ์แกว่งตัวสร้างแรงสั่นสะเทือนรุนแรงลงบนพื้น ทำความเสียหายแก่ศัตรูทุกตัว หากความเร็วของออนไิกซ์เร็วกว่าศัตรูอย่างมาก ความเสียหายจะเพิ่มขึ้น',
		simDesc_in = 'Onix mengayunkan tubuhnya menciptakan gelombang kejut kuat ke tanah, memberikan kerusakan kepada semua target musuh. Jika kecepatan Onix jauh lebih tinggi dari target, maka kerusakan yang diberikan akan lebih besar.',
		simDesc_ph = 'Inililiksi ni Onix ang katawan nito upang makabuo ng malakas na pagyanig sa lupa, na nagbibigay ng pinsala sa lahat ng kalaban. Kung ang bilis nito ay mas mataas nang malaki kaysa sa target, mas mataas ang magiging pinsala.',
		simDesc_ma = 'Onix menghayunkan badannya menghasilkan kejutan kuat ke tanah, menyebabkan kerosakan kepada semua sasaran musuh. Jika kelajuan Onix jauh lebih tinggi daripada sasaran, kerosakan akan menjadi lebih tinggi.',
		simDesc = 'Onix sways its body to create a strong shockwave on the ground, dealing damage to all enemy targets. If its speed significantly exceeds that of the target, the damage dealt will be higher.',
		starEffect = __data_t__starEffect[4013],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Có 60% xác suất di chuyển một anh hùng ngẫu nhiên ở hàng sau của kẻ địch đến vị trí hàng trước trống.',
		starEffectDesc = 'Additional effect: 60% chance to move a random hero in the enemy\'s back row to an empty front row position.',
		starEffectDesc_en = 'Additional effect: 60% chance to move a random hero in the enemy\'s back row to an empty front row position.',
		starEffectDesc_th = 'ผลเสริม: มีโอกาส 60% ที่จะย้ายฮีโร่สุ่มในแถวหลังของศัตรูไปยังตำแหน่งแถวหน้าที่ว่าง.',
		starEffectDesc_in = 'Efek tambahan: 60% peluang untuk memindahkan pahlawan acak di barisan belakang musuh ke posisi barisan depan yang kosong.',
		starEffectDesc_ph = 'Karagdagang epekto: 60% na tsansa na ilipat ang isang random na bayani sa likurang hanay ng kalaban sa bakanteng posisyon sa harap na hanay.',
		starEffectDesc_ma = 'Kesan tambahan: 60% peluang memindahkan wira rawak di barisan belakang musuh ke posisi barisan hadapan yang kosong.',
		zawakeEffect = __data_t__zawakeEffect[4013],
		-- {79003}
		zawakeEffectDesc = 'The Great Lava Snake sways its body causing strong vibrations in the air and ground, dealing #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54#physical#C0x5B545B# damage to all enemy targets. The greater the speed difference between the user and the target, the higher the damage dealt, not exceeding 40%.',
		zawakeEffectDesc_en = 'The Great Lava Snake sways its body causing strong vibrations in the air and ground, dealing #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54#physical#C0x5B545B# damage to all enemy targets. The greater the speed difference between the user and the target, the higher the damage dealt, not exceeding 40%.',
		zawakeEffectDesc_th = 'งูไฟใหญ่แกว่งตัวสร้างแรงสั่นสะเทือนรุนแรงในอากาศและพื้นดิน ทำให้เกิดความเสียหาย #C0xE69900#160% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*30)$ ด้าน #C0xF13B54#กายภาพ#C0x5B545B# ต่อเป้าหมายศัตรูทั้งหมด ยิ่งความเร็วผู้ใช้และเป้าหมายแตกต่างกันมากเท่าไหร่ ความเสียหายที่เกิดขึ้นก็ยิ่งเพิ่มสูงขึ้น ไม่เกิน 40%',
		zawakeEffectDesc_in = 'Ular Lava Besar mengayunkan tubuhnya menyebabkan getaran hebat di udara dan tanah, memberikan #C0xE69900#160% Serangan Fisik#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54#fisik#C0x5B545B# kerusakan ke semua target musuh. Semakin besar perbedaan kecepatan antara pengguna dan target, semakin tinggi kerusakan yang dihasilkan, maksimum tidak melebihi 40%.',
		zawakeEffectDesc_ph = 'Ang Dakilang Lava Ahas ay umiindak ng katawan na nagdudulot ng malakas na panginginig sa hangin at lupa, na nagdudulot ng #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54#pisikal#C0x5B545B# na pinsala sa lahat ng mga kaaway na target. Kapag mas malaki ang pagkakaiba sa bilis ng gumagamit at ng target, mas mataas ang pinsalang naidudulot, hindi lalampas sa 40%.',
		zawakeEffectDesc_ma = 'Ular Lava Besar menggoyangkan badannya menyebabkan getaran kuat di udara dan tanah, memberikan #C0xE69900#160% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54#fizikal#C0x5B545B# kerosakan kepada semua sasaran musuh. Semakin besar beza kelajuan antara pengguna dan sasaran, semakin tinggi kerosakan yang diberikan, maksimum tidak melebihi 40%.',
		zawakeEffectDesc_vn = 'Đại Nham Xà lắc lư cơ thể gây rung động mạnh cho không khí và mặt đất, gây sát thương #C0xE69900#160% Công Vật Lý#C0x5B545B#+$(skillLevel*4*30)$ sát thương #C0xF13B54#vật lý#C0x5B545B# cho toàn bộ mục tiêu địch, nếu tốc độ bản thân và mục tiêu chênh lệch càng lớn, sát thương gây ra càng cao, tối đa không vượt quá 40%',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'The greater the speed difference between self and target, the higher the damage, up to a max of 30%\n#F20# \n#F40##C0x5c9970#→The greater the speed difference between self and target, the higher the damage, up to a max of 40%',
		zawakeSimpleDesc_en = 'The greater the speed difference between self and target, the higher the damage, up to a max of 30%\n#F20# \n#F40##C0x5c9970#→The greater the speed difference between self and target, the higher the damage, up to a max of 40%',
		zawakeSimpleDesc_th = 'ยิ่งความเร็วระหว่างตัวเองกับเป้าหมายแตกต่างกันมากเท่าไหร่ ความเสียหายยิ่งสูงขึ้น สูงสุดไม่เกิน 30%\n#F20# \n#F40##C0x5c9970#→ยิ่งความเร็วแตกต่างกันมาก ความเสียหายยิ่งสูงขึ้น สูงสุดไม่เกิน 40%',
		zawakeSimpleDesc_in = 'Semakin besar perbedaan kecepatan antara diri sendiri dan target, semakin besar damage, hingga maksimum 30%\n#F20# \n#F40##C0x5c9970#→Semakin besar perbedaan kecepatan, semakin besar damage, hingga maksimum 40%',
		zawakeSimpleDesc_ph = 'Kapag mas malaki ang agwat ng bilis ng sarili at ng target, mas malaki ang damage, maximum 30%\n#F20# \n#F40##C0x5c9970#→Kapag mas malaki ang agwat ng bilis, mas malaki ang damage, maximum 40%',
		zawakeSimpleDesc_ma = 'Semakin besar perbezaan kelajuan antara diri dan sasaran, semakin tinggi kerosakan, maksimum 30%\n#F20# \n#F40##C0x5c9970#→Semakin besar perbezaan kelajuan, semakin tinggi kerosakan, maksimum 40%',
		zawakeSimpleDesc_vn = 'Nếu tốc độ của bản thân và mục tiêu càng chênh lệch, sát thương gây ra càng cao, tối đa không vượt quá 30%\n#F20# \n#F40##C0x5c9970#→Nếu tốc độ của bản thân và mục tiêu càng chênh lệch, sát thương gây ra càng cao, tối đa không vượt quá 40%',
