		skillName_th = 'เสืออ้วนอวดตัว',
		skillName_in = 'Harimau Gemuk Pamer Tubuh',
		skillName_ph = 'Matabang Tigre na Nagmamalaki',
		skillName_ma = 'Harimau Gemuk Memperlihatkan Tubuh',
		skillName = 'Fat Tiger Showing Off',
		describe_vn = 'Zombie hổ béo đi về phía giữa kẻ thù. Sau đó, cơ thể mập mạp của nó rơi xuống và gây ra một trận động đất tấn công tất cả các mục tiêu của kẻ thù, gây ra #C0xE69900#170% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#. Sự chênh lệch giữa tốc độ của bản thân và mục tiêu càng lớn thì sát thương do sát thương này gây ra càng cao, tối đa là 30%.',
		describe_en = 'The fat zombie tiger moves towards the center of the enemies. Then, its plump body falls down, causing an earthquake that attacks all enemy targets, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Physical Damage#C0x5B545B#. The greater the speed difference between yourself and the target, the higher the damage dealt by this attack, up to a maximum of 30%.',
		describe_th = 'ซอมบี้เสืออ้วนเดินไปทางกลางของศัตรู จากนั้นร่างอ้วนของมันจะตกลงมาและก่อให้เกิดแผ่นดินไหวโจมตีเป้าหมายศัตรูทั้งหมด สร้าง #C0xE69900#170% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ความแตกต่างระหว่างความเร็วของตัวเองกับเป้าหมายยิ่งมาก ความเสียหายจากการโจมตีนี้ก็จะยิ่งสูงขึ้น สูงสุด 30%.',
		describe_in = 'Zombie harimau gemuk bergerak menuju tengah musuh. Kemudian, tubuhnya yang gemuk jatuh dan menyebabkan gempa yang menyerang semua target musuh, memberikan #C0xE69900#170% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Semakin besar perbedaan kecepatan antara diri sendiri dan target, semakin besar kerusakan yang dihasilkan oleh serangan ini, maksimal 30%.',
		describe_ph = 'Ang matabang zombie tiger ay lumalapit sa gitna ng mga kalaban. Pagkatapos, ang kanyang matabang katawan ay babagsak at magdudulot ng lindol na umatake sa lahat ng mga target ng kalaban, na nagdudulot ng #C0xE69900#170% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Mas malaki ang diperensya ng bilis mo at ng target, mas mataas ang pinsalang idudulot ng pag-atakeng ito, hanggang sa maximum na 30%.',
		describe_ma = 'Zombie harimau gemuk bergerak ke tengah musuh. Kemudian, badan gemuknya jatuh dan menyebabkan gempa yang menyerang semua sasaran musuh, menyebabkan #C0xE69900#170% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Perbezaan kelajuan antara diri sendiri dan sasaran semakin besar, kerosakan yang disebabkan oleh serangan ini semakin tinggi, maksimum 30%.',
		describe = 'The fat zombie tiger moves towards the center of the enemies. Then, its plump body falls down, causing an earthquake that attacks all enemy targets, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Physical Damage#C0x5B545B#. The greater the speed difference between yourself and the target, the higher the damage dealt by this attack, up to a maximum of 30%.',
		simDesc_vn = 'Zombie hổ béo đi về phía giữa kẻ thù. Sau đó, cơ thể mập mạp của nó rơi xuống và gây ra một trận động đất tấn công tất cả các mục tiêu của kẻ thù. Sự khác biệt giữa tốc độ của nó và mục tiêu càng lớn thì sát thương sẽ càng cao.',
		simDesc_en = 'The fat zombie tiger moves toward the center of the enemy. Then, its plump body falls down, causing an earthquake that attacks all enemy targets. The greater the speed difference between it and the target, the higher the damage.',
		simDesc_th = 'เสือซอมบี้ตัวอ้วนเคลื่อนที่ไปยังตรงกลางศัตรู จากนั้นร่างที่อ้วนท้วนของมันก็ตกลงมา ทำให้เกิดแผ่นดินไหวโจมตีเป้าหมายศัตรูทั้งหมด ยิ่งความแตกต่างของความเร็วระหว่างมันกับเป้าหมายมากเท่าไร ความเสียหายก็จะยิ่งสูงขึ้นเท่านั้น',
		simDesc_in = 'Zombie harimau gemuk bergerak ke tengah musuh. Kemudian, tubuhnya yang gemuk jatuh dan menyebabkan gempa yang menyerang semua target musuh. Semakin besar perbedaan kecepatan antara dia dan target, semakin tinggi kerusakannya.',
		simDesc_ph = 'Ang matabang zombie tigre ay lumalapit sa gitna ng kaaway. Pagkatapos, bumabagsak ang kanyang malapad na katawan at nagdudulot ng lindol na umatake sa lahat ng mga target ng kaaway. Mas malaki ang diperensya ng bilis niya at ng target, mas mataas ang damage.',
		simDesc_ma = 'Harimau zombi gemuk bergerak ke tengah musuh. Kemudian, tubuhnya yang montel jatuh dan menyebabkan gempa yang menyerang semua sasaran musuh. Semakin besar perbezaan kelajuan antara ia dan sasaran, semakin tinggi kerosakan yang dialami.',
		simDesc = 'The fat zombie tiger moves toward the center of the enemy. Then, its plump body falls down, causing an earthquake that attacks all enemy targets. The greater the speed difference between it and the target, the higher the damage.',
		starEffect = __data_t__starEffect[4023],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Có 60% xác suất di chuyển một anh hùng ngẫu nhiên ở hàng sau của kẻ địch đến vị trí hàng trước trống.',
		starEffectDesc = 'Additional effect: Has a 60% chance to move a random hero in the enemy\'s back row to an empty front row position.',
		starEffectDesc_en = 'Additional effect: Has a 60% chance to move a random hero in the enemy\'s back row to an empty front row position.',
		starEffectDesc_th = 'ผลเสริม: มีโอกาส 60% ที่จะย้ายฮีโร่แบบสุ่มในแถวหลังของศัตรูไปยังตำแหน่งแถวหน้าที่ว่างอยู่',
		starEffectDesc_in = 'Efek tambahan: Memiliki peluang 60% untuk memindahkan pahlawan acak di barisan belakang musuh ke posisi barisan depan yang kosong.',
		starEffectDesc_ph = 'Karagdagang epekto: May 60% na pagkakataon na ilipat ang isang random na bayani sa likurang hanay ng kalaban sa bakanteng posisyon sa harapang hanay.',
		starEffectDesc_ma = 'Kesan tambahan: Mempunyai peluang 60% untuk menggerakkan wira rawak di barisan belakang musuh ke posisi barisan depan yang kosong.',
		zawakeEffect = __data_t__zawakeEffect[4023],
		-- {79003}
		zawakeEffectDesc = 'The fat zombie tiger moves to the center of the enemy, then its plump body falls down causing an earthquake attacking all enemy targets, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*30)$ of #C0xF13B54#Physical Damage#C0x5B545B#. The greater the difference between the user\'s and the target\'s speed, the higher the damage caused by this attack, up to a maximum of 40%.',
		zawakeEffectDesc_en = 'The fat zombie tiger moves to the center of the enemy, then its plump body falls down causing an earthquake attacking all enemy targets, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*30)$ of #C0xF13B54#Physical Damage#C0x5B545B#. The greater the difference between the user\'s and the target\'s speed, the higher the damage caused by this attack, up to a maximum of 40%.',
		zawakeEffectDesc_th = 'ซอมบี้เสืออ้วนเดินไปยังจุดกึ่งกลางของศัตรู จากนั้นร่างกายอ้วนท้วนล้มลงและก่อให้เกิดแผ่นดินไหวโจมตีศัตรูทุกตัว ก่อให้เกิด #C0xE69900#170% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*30)$ ของ #C0xF13B54#พลังโจมตีทางกายภาพ#C0x5B545B#. ความแตกต่างของความเร็วระหว่างตัวละครและเป้าหมายยิ่งมาก ก็จะทำให้ความเสียหายจากพลังโจมตีนี้ยิ่งสูงขึ้น สูงสุดไม่เกิน 40%.',
		zawakeEffectDesc_in = 'Zombie harimau gemuk bergerak ke tengah musuh, lalu tubuh gemuknya jatuh dan menyebabkan gempa menyerang semua target musuh, memberikan #C0xE69900#170% Damage Fisik#C0x5B545B#+$(skillLevel*4*30)$ dari #C0xF13B54#Damage Fisik#C0x5B545B#. Perbedaan kecepatan antara pengguna dan target semakin besar maka kerusakan yang ditimbulkan oleh serangan ini semakin tinggi, hingga maksimum 40%.',
		zawakeEffectDesc_ph = 'Ang matabang zombie tiger ay lumalapit sa gitna ng mga kaaway, pagkatapos ang masangsang na katawan nito ay bumagsak at nagdudulot ng lindol na umatake sa lahat ng mga target ng kaaway, na nagdudulot ng #C0xE69900#170% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*30)$ ng #C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Ang mas malaking pagkakaiba sa bilis ng gumagamit at ng target, mas mataas ang pinsalang dulot ng atakeng ito, hanggang sa maximum na 40%.',
		zawakeEffectDesc_ma = 'Zombi harimau gemuk bergerak ke tengah musuh, kemudian badan gemuknya jatuh dan menyebabkan gempa menyerang semua sasaran musuh, memberikan #C0xE69900#170% Kecederaan Fizikal#C0x5B545B#+$(skillLevel*4*30)$ daripada #C0xF13B54#Kecederaan Fizikal#C0x5B545B#. Perbezaan antara kelajuan pengguna dan sasaran semakin besar, maka kerosakan yang disebabkan oleh serangan ini semakin tinggi, sehingga maksimum 40%.',
		zawakeEffectDesc_vn = 'Zombie hổ béo đi đến giữa kẻ địch, sau đó thân hình mập mạp ngã xuống và gây ra một trận động đất tấn công tất cả các mục tiêu của kẻ địch, gây ra #C0xE69900#170% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*30)$ thuộc #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#. Sự chênh lệch giữa tốc độ của bản thân và mục tiêu càng lớn thì sát thương do sát thương này gây ra càng cao, lên tới không quá 40%.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'The greater the speed difference between self and target, the more damage dealt, up to a maximum of 30%\n#F20# \n#F40##C0x5c9970#→The greater the speed difference between self and target, the more damage dealt, up to a maximum of 40%',
		zawakeSimpleDesc_en = 'The greater the speed difference between self and target, the more damage dealt, up to a maximum of 30%\n#F20# \n#F40##C0x5c9970#→The greater the speed difference between self and target, the more damage dealt, up to a maximum of 40%',
		zawakeSimpleDesc_th = 'ยิ่งความเร็วระหว่างตัวเองกับเป้าหมายแตกต่างกันมากเท่าไหร่ ความเสียหายยิ่งสูงขึ้น สูงสุดไม่เกิน 30%\n#F20# \n#F40##C0x5c9970#→ยิ่งความเร็วแตกต่างกันมาก ความเสียหายยิ่งสูงขึ้น สูงสุดไม่เกิน 40%',
		zawakeSimpleDesc_in = 'Semakin besar perbedaan kecepatan antara diri sendiri dan target, semakin besar kerusakan, maksimal 30%\n#F20# \n#F40##C0x5c9970#→Semakin besar perbedaan kecepatan, semakin besar kerusakan, maksimal 40%',
		zawakeSimpleDesc_ph = 'Kapag mas malaki ang agwat ng bilis ng sarili at ng target, mas mataas ang damage, hanggang 30%\n#F20# \n#F40##C0x5c9970#→Kapag mas malaki ang agwat ng bilis, mas mataas ang damage, hanggang 40%',
		zawakeSimpleDesc_ma = 'Semakin besar perbezaan kelajuan antara diri dan sasaran, semakin tinggi kerosakan, maksimum 30%\n#F20# \n#F40##C0x5c9970#→Semakin besar perbezaan kelajuan, semakin tinggi kerosakan, maksimum 40%',
		zawakeSimpleDesc_vn = 'Nếu tốc độ của bản thân và mục tiêu càng chênh lệch, sát thương gây ra càng cao, tối đa không vượt quá 30%\n#F20# \n#F40##C0x5c9970#→Nếu tốc độ của bản thân và mục tiêu càng chênh lệch, sát thương gây ra càng cao, tối đa không vượt quá 40%',
