	[4523] = {
		id = 4523,
		skillName_vn = 'Đánh gậy lung tung',
		skillName_en = 'Hit the stick randomly',
		skillName_th = 'ตีไม้แบบสุ่ม',
		skillName_in = 'Memukul tongkat secara acak',
		skillName_ph = 'Palo ng baston nang walang patumangga',
		skillName_ma = 'Pukul kayu secara rawak',
		skillName = 'Hit the stick randomly',
		describe_vn = 'Galagala ném một đống xương đập vào mục tiêu đơn lẻ của kẻ địch, sau đó dùng gậy xương đánh điên cuồng, gây #C0xE69900#400% Công Vật Lý#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, và có 40% [choáng] mục tiêu trong 1 lượt (choáng: hiệu ứng kiểm soát, không thể hành động), nếu không làm choáng thành công, xác suất choáng của kỹ năng tối thượng lần sau sẽ tăng gấp đôi',
		describe_en = 'Galagala throws a pile of bones at a single enemy target, then wildly attacks with a bone club, dealing #C0xE69900#400% Physical Attack#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Physical Damage#C0x5B545B#, and has a 40% chance to [stun] the target for 1 turn (stun: a control effect that prevents action). If the stun fails, the ultimate skill\'s stun chance will double next time.',
		describe_th = 'Galagala ขว้างกองกระดูกใส่เป้าหมายศัตรูหนึ่งตัว จากนั้นโจมตีคลั่งด้วยกระบองกระดูก ทำให้เกิด #C0xE69900#400% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# และมีโอกาส 40% ที่จะ [มึนงง] เป้าหมายเป็นเวลา 1 เทิร์น (มึนงง: เอฟเฟกต์ควบคุม ทำให้ไม่สามารถทำการใดๆ ได้) หากไม่สามารถทำให้มึนงงได้ โอกาสมึนงงของสกิลอัลติเมทครั้งถัดไปจะเพิ่มขึ้นเป็นสองเท่า',
		describe_in = 'Galagala melempar tumpukan tulang ke satu target musuh, kemudian menyerang dengan tongkat tulang secara brutal, memberikan #C0xE69900#400% Serangan Fisik#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, dan memiliki 40% [stun] target selama 1 giliran (stun: efek kontrol yang mencegah aksi). Jika gagal membuat stun, peluang stun skill ultimate berikutnya akan menjadi dua kali lipat.',
		describe_ph = 'Si Galagala ay naghagis ng tambak ng mga buto sa isang solong target na kaaway, pagkatapos ay mananakit nang walang humpay gamit ang butong pamalo, na nagdudulot ng #C0xE69900#400% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, at may 40% na [stun] sa target sa loob ng 1 turn (stun: isang kontrol na epekto na pumipigil sa aksyon). Kung hindi magtagumpay ang stun, ang posibilidad ng stun ng ultimate skill sa susunod ay dodoble.',
		describe_ma = 'Galagala melempar sebongkah tulang ke sasaran musuh tunggal, kemudian menyerang dengan kayu tulang secara ganas, menyebabkan #C0xE69900#400% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, dan mempunyai 40% peluang untuk [pingsan] sasaran selama 1 pusingan (pingsan: kesan kawalan yang menghalang tindakan). Jika tidak berjaya memingsankan, peluang pingsan skil utama akan meningkat dua kali ganda pada kali berikutnya.',
		describe = 'Galagala throws a pile of bones at a single enemy target, then wildly attacks with a bone club, dealing #C0xE69900#400% Physical Attack#C0x5B545B#+$(skillLevel*4*50)$ #C0xF13B54# Physical Damage#C0x5B545B#, and has a 40% chance to [stun] the target for 1 turn (stun: a control effect that prevents action). If the stun fails, the ultimate skill\'s stun chance will double next time.',
		simDesc_vn = 'Marowak ném một đống xương vào mục tiêu đơn lẻ của đối phương, sau đó dùng gậy xương tấn công điên cuồng, có khả năng làm choáng mục tiêu.',
		simDesc_en = 'Marowak throws a pile of bones at a single enemy target, then frantically attacks with its bone club, with a chance to stun the target.',
		simDesc_th = 'มารอแวกขว้างกองกระดูกไปยังเป้าหมายเดี่ยวของฝ่ายตรงข้าม จากนั้นโจมตีอย่างบ้าคลั่งด้วยไม้ก้างกระดูก มีโอกาสทำให้เป้าหมายติดสถานะมึนงง',
		simDesc_in = 'Marowak melempar tumpukan tulang ke satu target musuh, lalu menyerang dengan tongkat tulangnya secara gila-gilaan, dengan kemungkinan membuat target terpukul.',
		simDesc_ph = 'Si Marowak ayaw ang isang bungkos ng mga buto sa iisang target na kalaban, pagkatapos ay galit na umatake gamit ang kanyang butong pamalo, may tsansang makapag-stun sa target.',
		simDesc_ma = 'Marowak melemparkan sebongkah tulang ke sasaran musuh tunggal, kemudian menyerang dengan tongkat tulangnya secara ganas, berkemungkinan menyebabkan sasaran terhenti.',
