	[5013] = {
		id = 5013,
		skillName_vn = 'Ánh sáng quả trứng',
		skillName_en = 'Egg light',
		skillName_th = 'แสงของไข่',
		skillName_in = 'Cahaya telur',
		skillName_ph = 'Liwanag ng itlog',
		skillName_ma = 'Cahaya telur',
		skillName = 'Egg light',
		describe_vn = 'Tiểu Phúc Đản nâng quả trứng, phát ra ánh sáng chói lóa, hồi máu cho toàn bộ phe địch và phe ta bằng 50% giới hạn sinh mệnh của Tiểu Phúc Đản+$(skillLevel*4*60)$, hiệu quả hồi máu của anh hùng phe địch giảm một nửa, và sau khi hồi máu bị cảm hóa bởi trái tim của Tiểu Phúc Đản, giảm 30% hiệu quả hồi máu trong 2 lượt',
		describe_en = 'Little Phuc Dan raises an egg that emits a dazzling light, healing all allies and enemies for 50% of Little Phuc Dan\'s maximum health plus $(skillLevel*4*60)$. The healing effectiveness for enemy heroes is halved, and after healing, they are charmed by Little Phuc Dan\'s heart, reducing healing effectiveness by 30% for 2 turns.',
		describe_th = 'เล็กฟุกด่านยกไข่ที่ปล่อยแสงเจิดจ้า ฟื้นฟูสุขภาพให้ฝ่ายศัตรูและฝ่ายเราเป็นจำนวน 50% ของพลังชีวิตสูงสุดของเล็กฟุกด่านบวก $(skillLevel*4*60)$ ผลการฟื้นฟูของฮีโร่ฝ่ายศัตรูลดลงครึ่งหนึ่ง และหลังจากฟื้นฟูจะถูกเสน่ห์จากหัวใจของเล็กฟุกด่าน ลดผลการฟื้นฟูลง 30% เป็นเวลา 2 เทิร์น',
		describe_in = 'Little Phuc Dan mengangkat telur yang memancarkan cahaya terang, menyembuhkan semua pihak musuh dan teman sebesar 50% dari batas nyawa Little Phuc Dan ditambah $(skillLevel*4*60)$. Efektivitas penyembuhan pahlawan musuh berkurang setengah, dan setelah penyembuhan terpesona oleh hati Little Phuc Dan, mengurangi efektivitas penyembuhan sebesar 30% selama 2 giliran.',
		describe_ph = 'Itinataas ni Little Phuc Dan ang isang itlog na naglalabas ng matingkad na liwanag, nagpapagaling sa lahat ng kaalyado at kaaway ng 50% ng maximum na buhay ni Little Phuc Dan plus $(skillLevel*4*60)$. Ang bisa ng paggaling sa mga kalaban na bayani ay nabawasan ng kalahati, at pagkatapos ng paggaling, sila ay naakit ng puso ni Little Phuc Dan, na nagpapababa ng bisa ng paggaling ng 30% sa loob ng 2 turn.',
		describe_ma = 'Little Phuc Dan mengangkat sebiji telur yang memancarkan cahaya terang, memulihkan kesihatan seluruh pihak musuh dan pihak kita sebanyak 50% had nyawa Little Phuc Dan + $(skillLevel*4*60)$. Keberkesanan pemulihan untuk wira musuh berkurang separuh, dan selepas pemulihan, mereka terpesona oleh hati Little Phuc Dan, mengurangkan keberkesanan pemulihan sebanyak 30% selama 2 pusingan.',
		describe = 'Little Phuc Dan raises an egg that emits a dazzling light, healing all allies and enemies for 50% of Little Phuc Dan\'s maximum health plus $(skillLevel*4*60)$. The healing effectiveness for enemy heroes is halved, and after healing, they are charmed by Little Phuc Dan\'s heart, reducing healing effectiveness by 30% for 2 turns.',
		simDesc_vn = 'Chansey nâng quả trứng lên, phát ra ánh sáng chói lóa, hồi phục sinh lực cho toàn bộ cả hai bên, hiệu ứng hồi phục của các anh hùng đối phương giảm một nửa.',
		simDesc_en = 'Chansey raises the egg, emitting a dazzling light that restores HP to all on both sides. The healing effects for enemy heroes are halved.',
		simDesc_th = 'แชนซีย์ยกไข่ขึ้นแล้วปล่อยแสงสว่างเจิดจ้า รักษาค่าพลังชีวิตให้กับทุกคนทั้งสองฝ่าย ผลการฟื้นฟูของฮีโร่ฝ่ายตรงข้ามจะลดลงครึ่งหนึ่ง',
		simDesc_in = 'Chansey mengangkat telur, memancarkan cahaya terang yang menyembuhkan seluruh nyawa di kedua sisi. Efek penyembuhan pada pahlawan musuh berkurang setengahnya.',
		simDesc_ph = 'Itinaas ni Chansey ang itlog, naglalabas ng nakakasilaw na liwanag, nagpapagaling sa lahat sa magkabilang panig. Ang epekto ng pagpapagaling ng mga kalabang bayani ay nababawasan ng kalahati.',
		simDesc_ma = 'Chansey mengangkat telur, memancarkan cahaya terang yang memulihkan nyawa kepada semua di kedua pihak. Kesan penyembuhan untuk wira musuh berkurang separuh.',
		simDesc = 'Chansey raises the egg, emitting a dazzling light that restores HP to all on both sides. The healing effects for enemy heroes are halved.',
		starEffect = __data_t__starEffect[5013],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Giải tán tất cả hiệu ứng tiêu cực và kiểm soát trên mục tiêu có tỷ lệ máu thấp nhất; nhận cảm hóa từ trái tim nhỏ bé, giảm 20% sức tấn công của tất cả kẻ địch trong 2 lượt.',
		starEffectDesc = 'Additional effect: Dispel all negative effects and control on the target with the lowest HP; receive #mã màu#Little Heart#F x# #L x# sensitization, reducing all enemies\' attack power by 20% for 2 turns.',
		starEffectDesc_en = 'Additional effect: Dispel all negative effects and control on the target with the lowest HP; receive #mã màu#Little Heart#F x# #L x# sensitization, reducing all enemies\' attack power by 20% for 2 turns.',
		starEffectDesc_th = 'เอฟเฟกเพิ่มเติม: ขจัดเอฟเฟกต์เชิงลบและควบคุมทั้งหมดบนเป้าหมายที่มี HP ต่ำที่สุด; รับ #mã màu#ใจเล็กน้อย#F x# #L x# ทำให้ศัตรูทั้งหมดโจมตีลดลง 20% เป็นเวลา 2 ตา',
		starEffectDesc_in = 'Efek tambahan: Menghilangkan semua efek negatif dan kontrol pada target dengan HP terendah; menerima #mã màu#Hati Kecil#F x# #L x# yang membuat semua musuh berkurang serangannya sebesar 20% selama 2 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Alisin ang lahat ng negatibong epekto at kontrol sa target na may pinakamababang HP; tumanggap ng #mã màu#Munting Puso#F x# #L x# na nagpapababa ng 20% na atake ng lahat ng kalaban sa loob ng 2 turn.',
		starEffectDesc_ma = 'Kesan tambahan: Nyahaktifkan semua kesan negatif dan kawalan pada sasaran dengan HP terendah; menerima #mã màu#Hati Kecil#F x# #L x# yang mengurangkan serangan semua musuh sebanyak 20% selama 2 giliran.',
		upLvDesc = 'Healing amount +240',
