	[5016] = {
		id = 5016,
		skillName_vn = 'Đẻ trứng',
		skillName_en = 'Lay eggs',
		skillName_th = 'ออกไข่',
		skillName_in = 'Bertelur',
		skillName_ph = 'Magsalita itlog',
		skillName_ma = 'Bertelur',
		skillName = 'Lay eggs',
		describe_vn = 'Vào cuối mỗi vòng lớn, nếu bản thân không bị khống chế, sẽ ấp một quả trứng cho đồng đội có tỷ lệ sinh mệnh thấp nhất ăn (có thể hồi phục sinh mệnh bằng 50+skillLevel*0.4-0.4% giới hạn sinh mệnh từ trứng nhỏ), nếu hồi phục vượt mức, 20% lượng vượt mức sẽ vĩnh viễn chuyển hóa thành giới hạn sinh mệnh (tối đa 3 tầng)',
		describe_en = 'At the end of each major round, if you are not controlled, you will hatch an egg for the teammate with the lowest health to consume (restoring health by 50 + skillLevel * 0.4 - 0.4%, limited by small egg health cap). If the recovery exceeds the maximum, 20% of the excess amount will permanently convert into a health limit (up to 3 layers).',
		describe_th = 'เมื่อจบรอบใหญ่แต่ละรอบ หากตัวเองไม่ถูกควบคุม จะฟักไข่ให้เพื่อนร่วมทีมที่มีพลังชีวิตต่ำที่สุดกิน (ฟื้นฟูพลังชีวิต 50 + skillLevel * 0.4 - 0.4% จำกัดพลังชีวิตจากไข่ขนาดเล็ก) หากฟื้นฟูเกินขีดจำกัด 20% ของส่วนเกินจะถูกแปลงเป็นขีดจำกัดพลังชีวิตถาวร (สูงสุด 3 ชั้น)',
		describe_in = 'Di akhir setiap putaran besar, jika diri sendiri tidak dalam keadaan terkendali, akan menetaskan telur untuk dimakan oleh rekan tim dengan persentase kesehatan terendah (dapat memulihkan kesehatan sebesar 50 + skillLevel * 0.4 - 0.4%, dibatasi oleh batas kesehatan dari telur kecil). Jika pemulihan melebihi batas, 20% dari kelebihan tersebut akan secara permanen diubah menjadi batas kesehatan (maksimal 3 lapisan).',
		describe_ph = 'Sa pagtatapos ng bawat malaking round, kung hindi nakokontrol ang sarili, magbubukas ng itlog para makain ng kakampi na may pinakamababang porsyento ng buhay (maaaring bumalik ang buhay ng 50 + skillLevel * 0.4 - 0.4%, limitado ng health cap mula sa maliit na itlog). Kung lumabis ang paggaling, 20% ng sobrang halaga ay permanenteng magiging dagdag sa life limit (hanggang 3 layers).',
		describe_ma = 'Pada akhir setiap pusingan besar, jika diri sendiri tidak dikawal, akan menetas telur untuk dimakan oleh rakan sepasukan yang mempunyai nisbah kesihatan terendah (boleh memulihkan kesihatan sebanyak 50 + tahapKemahiran * 0.4 - 0.4%, dengan had kesihatan dari telur kecil). Jika pemulihan melebihi had, 20% daripada lebihan tersebut akan kekal bertukar menjadi had kesihatan (maksimum 3 lapisan).',
		describe = 'At the end of each major round, if you are not controlled, you will hatch an egg for the teammate with the lowest health to consume (restoring health by 50 + skillLevel * 0.4 - 0.4%, limited by small egg health cap). If the recovery exceeds the maximum, 20% of the excess amount will permanently convert into a health limit (up to 3 layers).',
		starEffect = __data_t__starEffect[5016],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Trái tim chữa lành: Cuối mỗi lượt, giải tán một hiệu ứng kiểm soát hoặc tiêu cực ngẫu nhiên trên một đồng minh.',
		starEffectDesc = 'Additional Effect: Healing Heart: At the end of each turn, dispels a random control or negative effect on an ally.',
		starEffectDesc_en = 'Additional Effect: Healing Heart: At the end of each turn, dispels a random control or negative effect on an ally.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: หัวใจแห่งการรักษา: สิ้นสุดแต่ละรอบ จะล้างสถานะควบคุมหรือลบแบบสุ่มออกจากพันธมิตรหนึ่งคน',
		starEffectDesc_in = 'Efek Tambahan: Hati Penyembuh: Di akhir setiap giliran, menghilangkan efek kontrol atau negatif secara acak pada satu sekutu.',
		starEffectDesc_ph = 'Karagdagang Epekto: Pusong Pagpapagaling: Sa katapusan ng bawat turno, nilalabas ang isang random na kontrol o negatibong epekto sa isang kakampi.',
		starEffectDesc_ma = 'Kesan Tambahan: Hati Penyembuh: Pada akhir setiap pusingan, membuang kesan kawalan atau negatif rawak pada satu sekutu.',
