	[5033] = {
		id = 5033,
		skillName_vn = 'Thiên thần bảo vệ',
		skillName_en = 'Guardian angel',
		skillName_th = 'เทวดาองค์รักษ์',
		skillName_in = 'Malaikat pelindung',
		skillName_ph = 'Tagapagbantay na anghel',
		skillName_ma = 'Malaikat pelindung',
		skillName = 'Guardian angel',
		describe_vn = 'Illya biến thành thiên thần. Cô là một người chữa lành nhân từ và cứu tất cả. Cô ấy chữa lành vết thương cho cả kẻ thù và bạn bè bằng 50% máu tối đa của Illya + #C0x5c9970#$(skillLevel*4*75)$%#C0x5B545B#. Hiệu quả hồi máu của tướng địch bị giảm một nửa. Sau khi điều trị, cô bị ảnh hưởng bởi tình yêu của Illya và khả năng hồi phục giảm 30% trong 2 đợt.',
		describe_en = 'Illya transforms into an angel. She is a kind healer who saves everyone. She heals wounds for both enemies and allies by 50% of Illya\'s maximum HP + #C0x5c9970#$(skillLevel*4*75)$%#C0x5B545B#. The healing effect on enemy heroes is halved. After healing, she is affected by Illya\'s love, reducing her healing ability by 30% for 2 turns.',
		describe_th = 'อิลลิญ่า กลายเป็นเทพธิดา เธอเป็นผู้รักษาที่ใจดีและช่วยชีวิตทุกคน เธอรักษาบาดแผลของทั้งศัตรูและเพื่อนร่วมทีมโดยใช้พลังชีวิตสูงสุดของอิลลิญ่า 50% + #C0x5c9970#$(skillLevel*4*75)$%#C0x5B545B# ผลการฟื้นฟูเลือดของฮีโร่ฝ่ายตรงข้ามถูกลดลงครึ่งหนึ่ง หลังจากรักษาแล้ว เธอได้รับผลกระทบจากความรักของอิลลิญ่า และความสามารถในการฟื้นฟูลดลง 30% เป็นเวลา 2 เทิร์น',
		describe_in = 'Illya berubah menjadi malaikat. Dia adalah penyembuh yang baik hati dan menyelamatkan semua orang. Dia menyembuhkan luka baik musuh maupun teman dengan menggunakan 50% dari darah maksimum Illya + #C0x5c9970#$(skillLevel*4*75)$%#C0x5B545B#. Efek penyembuhan pada pahlawan musuh berkurang setengahnya. Setelah penyembuhan, dia terpengaruh oleh cinta Illya dan kemampuan penyembuhannya berkurang 30% selama 2 giliran.',
		describe_ph = 'Nagiging anghel si Illya. Siya ay isang mabait na manggagamot na nagliligtas sa lahat. Pinagagaling niya ang mga sugat ng kalaban at kaalyado gamit ang 50% ng pinakamataas na HP ni Illya + #C0x5c9970#$(skillLevel*4*75)$%#C0x5B545B#. Ang bisa ng pagpapagaling sa mga kalabang bayani ay nababawasan ng kalahati. Pagkatapos magpagaling, naapektuhan siya ng pagmamahal ni Illya at bumaba ang kanyang kakayahan sa pagpapagaling ng 30% sa loob ng 2 turn.',
		describe_ma = 'Illya berubah menjadi malaikat. Dia seorang penyembuh yang baik hati dan menyelamatkan semua orang. Dia menyembuhkan luka untuk musuh dan rakan dengan 50% darah maksima Illya + #C0x5c9970#$(skillLevel*4*75)$%#C0x5B545B#. Kesan penyembuhan ke atas wira musuh dikurangkan separuh. Selepas merawat, dia terkesan oleh cinta Illya dan keupayaan penyembuhannya berkurang sebanyak 30% selama 2 pusingan.',
		describe = 'Illya transforms into an angel. She is a kind healer who saves everyone. She heals wounds for both enemies and allies by 50% of Illya\'s maximum HP + #C0x5c9970#$(skillLevel*4*75)$%#C0x5B545B#. The healing effect on enemy heroes is halved. After healing, she is affected by Illya\'s love, reducing her healing ability by 30% for 2 turns.',
		simDesc_vn = 'Illya biến thành thiên thần. Cô ấy là một người chữa lành nhân từ, người cứu tất cả mọi người. Cô ấy chữa lành mọi vết thương cho cả kẻ thù và chính chúng ta. Hiệu quả hồi máu của tướng địch bị giảm đi một nửa.',
		simDesc_en = 'Illya transforms into an angel. She is a kind healer who saves everyone. She heals all wounds for both enemies and ourselves. The healing effect on enemy generals is reduced by half.',
		simDesc_th = 'อิลเลียกลายเป็นเทพธิดา เธอเป็นผู้รักษาที่ใจดีที่ช่วยเหลือทุกคน เธอรักษาบาดแผลทั้งหมดทั้งของศัตรูและพวกเรา ผลการฟื้นฟูเลือดของหัวหน้าศัตรูลดลงครึ่งหนึ่ง',
		simDesc_in = 'Illya berubah menjadi malaikat. Dia adalah penyembuh yang baik hati yang menyelamatkan semua orang. Dia menyembuhkan semua luka untuk musuh maupun kita sendiri. Efek penyembuhan pada jenderal musuh berkurang setengahnya.',
		simDesc_ph = 'Nagiging anghel si Illya. Siya ay isang mabait na tagapagpagaling na inililigtas ang lahat. Ginagamot niya ang lahat ng sugat para sa mga kaaway at pati na rin sa atin. Ang epekto ng pagpapagaling sa mga kalaban na heneral ay nababawasan ng kalahati.',
		simDesc_ma = 'Illya berubah menjadi malaikat. Dia adalah penyembuh yang penyayang yang menyelamatkan semua orang. Dia menyembuhkan semua luka untuk musuh dan juga kita. Kesan pemulihan kesihatan terhadap jeneral musuh dikurangkan separuh.',
		simDesc = 'Illya transforms into an angel. She is a kind healer who saves everyone. She heals all wounds for both enemies and ourselves. The healing effect on enemy generals is reduced by half.',
		starEffect = __data_t__starEffect[5033],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng thêm: Đồng thời giải trừ toàn bộ hiệu ứng bất lợi và khống chế trên mục tiêu có tỷ lệ máu thấp nhất; Cảm hóa bởi tình yêu của Illya, giảm 20% Công Vật Lý và Công Phép trong 2 lượt.',
		starEffectDesc = 'Additional effect: Simultaneously dispel all negative effects and control on the target with the lowest HP; Enchanted by Illya\'s love, reduce Physical Attack and Magic Attack by 20% for 2 turns.',
		starEffectDesc_en = 'Additional effect: Simultaneously dispel all negative effects and control on the target with the lowest HP; Enchanted by Illya\'s love, reduce Physical Attack and Magic Attack by 20% for 2 turns.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: ลบสถานะลบและสถานะควบคุมทั้งหมดบนเป้าหมายที่มี HP ต่ำที่สุดพร้อมกัน; หลงใหลในความรักของ Illya ลด พลังโจมตีทางกายภาพ และ พลังเวทมนตร์ ลง 20% เป็นเวลา 2 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Secara bersamaan menghilangkan semua efek negatif dan kontrol pada target dengan HP terendah; Terpesona oleh cinta Illya, mengurangi Serangan Fisik dan Serangan Sulap sebesar 20% selama 2 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Sabay na inaalis ang lahat ng negatibong epekto at kontrol sa target na may pinakamababang HP; Nahulog sa pag-ibig ni Illya, binabawasan ang Physical Attack at Magic Attack ng 20% sa loob ng 2 turn.',
		starEffectDesc_ma = 'Kesan tambahan: Serentak membuang semua kesan negatif dan kawalan pada sasaran dengan HP terendah; Tersihir oleh cinta Illya, mengurangkan Serangan Fizikal dan Serangan Sihir sebanyak 20% selama 2 giliran.',
		upLvDesc = 'Recovery amount +300',
