	[5036] = {
		id = 5036,
		skillName_vn = 'Bảo vệ ma thuật',
		skillName_en = 'Protect magic',
		skillName_th = 'ปกป้องเวทมนตร์',
		skillName_in = 'Lindungi sihir',
		skillName_ph = 'Protektahan ang mahika',
		skillName_ma = 'Lindungi sihir',
		skillName = 'Protect magic',
		describe_vn = 'Vào cuối mỗi vòng lớn, nếu bạn không bị kiểm soát, hãy sử dụng phép thuật để bảo vệ đơn vị đồng đội có tỷ lệ máu thấp nhất (có thể khôi phục mạng sống từ Illya#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B# giới hạn mạng). Nếu xử lý tràn, 20% lượng tràn sẽ được chuyển đổi vĩnh viễn thành giới hạn tuổi thọ (tối đa 3 cấp độ)',
		describe_en = 'At the end of each major round, if you are not controlled, use magic to protect the allied unit with the lowest health percentage (can restore life from Illya by $(50+skillLevel*0.4-0.4)$% of the health limit). If overflow occurs, 20% of the overflow amount will be permanently converted into lifespan limit (up to 3 levels).',
		describe_th = 'ในตอนท้ายของแต่ละรอบใหญ่ หากคุณไม่ถูกควบคุม ให้ใช้เวทมนตร์ปกป้องหน่วยพันธมิตรที่มีเปอร์เซ็นต์พลังชีวิตต่ำที่สุด (สามารถฟื้นฟูชีวิตจาก Illya ได้ $(50+skillLevel*0.4-0.4)$% ของขีดจำกัดพลังชีวิต) หากเกิดการล้น 20% ของปริมาณล้นจะถูกแปลงถาวรเป็นขีดจำกัดอายุขัย (สูงสุด 3 ระดับ)',
		describe_in = 'Di akhir setiap putaran besar, jika kamu tidak terkendali, gunakan sihir untuk melindungi unit sekutu dengan persentase kesehatan terendah (dapat memulihkan kehidupan dari Illya sebesar $(50+skillLevel*0.4-0.4)$% dari batas kesehatan). Jika terjadi overflow, 20% dari jumlah overflow akan diubah secara permanen menjadi batas umur (maksimal 3 tingkat).',
		describe_ph = 'Sa pagtatapos ng bawat malaking round, kung hindi ka kontrolado, gumamit ng mahika upang protektahan ang kaalyadong yunit na may pinakamababang porsyento ng buhay (maaaring mabawi ang buhay mula kay Illya ng $(50+skillLevel*0.4-0.4)$% ng limitasyon ng buhay). Kung magkaroon ng overflow, 20% ng dami ng overflow ay permanenteng ikokonvert bilang limitasyon ng habang-buhay (hanggang 3 antas).',
		describe_ma = 'Pada akhir setiap pusingan besar, jika anda tidak dikawal, gunakan sihir untuk melindungi unit sekutu dengan peratusan kesihatan terendah (boleh memulihkan nyawa dari Illya sebanyak $(50+skillLevel*0.4-0.4)$% had kesihatan). Jika berlaku lebihan, 20% daripada jumlah lebihan akan ditukarkan secara kekal menjadi had jangka hayat (maksimum 3 tahap).',
		describe = 'At the end of each major round, if you are not controlled, use magic to protect the allied unit with the lowest health percentage (can restore life from Illya by $(50+skillLevel*0.4-0.4)$% of the health limit). If overflow occurs, 20% of the overflow amount will be permanently converted into lifespan limit (up to 3 levels).',
		starEffect = __data_t__starEffect[5036],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Trái tim chữa lành: Cuối mỗi lượt, giải tán một hiệu ứng kiểm soát hoặc tiêu cực ngẫu nhiên trên một đồng minh.',
		starEffectDesc = 'Additional effect: Healing Heart: At the end of each turn, dispel a random control or negative effect on an ally.',
		starEffectDesc_en = 'Additional effect: Healing Heart: At the end of each turn, dispel a random control or negative effect on an ally.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: หัวใจแห่งการรักษา: เมื่อสิ้นสุดแต่ละเทิร์น, ขจัดเอฟเฟกต์ควบคุมหรือเอฟเฟกต์ลบแบบสุ่มบนพันธมิตรหนึ่งคน',
		starEffectDesc_in = 'Efek tambahan: Hati Penyembuh: Di akhir setiap giliran, hilangkan efek kontrol atau negatif secara acak pada sekutu.',
		starEffectDesc_ph = 'Karagdagang epekto: Pusong Panlunas: Sa pagtatapos ng bawat turn, alisin ang isang random na epekto ng kontrol o negatibo sa isang alyado.',
		starEffectDesc_ma = 'Kesan tambahan: Hati Penyembuh: Pada akhir setiap giliran, hapuskan kesan kawalan atau negatif secara rawak pada sekutu.',
		iconRes = 'battle/skill_icon/skill_5036.png',
