	[5742] = {
		id = 5742,
		skillName_vn = 'Linh hồn - Táng tống',
		skillName_en = 'Soul - Send off',
		skillName_th = 'วิญญาณ - ส่งไป',
		skillName_in = 'Jiwa - Mengantarkan',
		skillName_ph = 'Kaluluwa - Pagpapadala',
		skillName_ma = 'Jiwa - Menghantar',
		skillName = 'Soul - Send off',
		describe_vn = 'Blood Slayer Akame bộc phát tốc độ cực cao, bạt đao trảm kích địch quân xếp sau HP thấp nhất mục tiêu, tạo thành #C0xE69900#350% Vật công #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, cho mục tiêu tăng thêm vĩnh cửu [ Cướp giết ] Tiêu ký ( Cướp giết: Hiệu quả đặc biệt, Blood Slayer Akame công kích cướp giết tiêu ký mục tiêu tổn thương tăng lên 30%, cái khác kiếm hệ tăng lên 15%; Tự thân công kích cướp giết mục tiêu lúc nếu như HP xuống tới 10% Trở xuống, thì sẽ ngoài định mức tạo thành một lần tương đương trước mắt HP chân thực tổn thương ( Không cao hơn tự thân 300% Vật công ), mỗi lần lặp lại tăng thêm nên tiêu ký sẽ làm nên máu hạn đề cao 5%)',
		describe_en = 'Blood Slayer Akame unleashes an extremely high speed, slashing through the enemy unit positioned behind with the lowest HP, dealing #C0xE69900#350% Physical Attack #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage #C0x5B545B#. This causes the target to gain an eternal [Murder Mark] (Murder Mark: Special effect, Blood Slayer Akame\'s attacks on targets with the Murder Mark deal 30% increased damage, while other sword-type attacks deal 15% increased damage; If Blood Slayer Akame attacks a target with the Murder Mark when their HP drops to 10% or below, it deals an extra damage equivalent to the target\'s current true HP (not exceeding 300% of Akame\'s Physical Attack). Each repeated hit increases the Murder Mark blood limit by 5%).',
		describe_th = 'Blood Slayer Akame ปลดปล่อยความเร็วสูงสุด ฟันศัตรูที่อยู่ด้านหลังที่มีพลังชีวิตต่ำที่สุด สร้างความเสียหายทางกายภาพ #C0xE69900#350% #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# #C0x5B545B# และทำให้เป้าหมายได้รับ [เครื่องหมายฆ่า] ตลอดกาล (เครื่องหมายฆ่า: เอฟเฟกต์พิเศษ การโจมตีของ Blood Slayer Akame ใส่เป้าหมายที่มีเครื่องหมายฆ่า จะเพิ่มความเสียหายขึ้น 30% การโจมตีประเภทดาบอื่น ๆ เพิ่มขึ้น 15%; หาก HP ของเป้าหมายที่มีเครื่องหมายฆ่า ลดลงเหลือ 10% หรือต่ำกว่า การโจมตีจะสร้างความเสียหายจริงเท่ากับ HP ปัจจุบันของเป้าหมาย (ไม่เกิน 300% ของพลังโจมตีทางกายภาพของตัวเอง) ทุกครั้งที่ทำซ้ำ เครื่องหมายฆ่าจะเพิ่มขีดจำกัดเลือดขึ้น 5%)',
		describe_in = 'Blood Slayer Akame melepaskan kecepatan sangat tinggi, menyerang musuh di belakang dengan HP terendah, menghasilkan #C0xE69900#350% Serangan Fisik #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#, membuat target mendapatkan [Tanda Pembunuhan] abadi (Tanda Pembunuhan: Efek khusus, serangan Blood Slayer Akame pada target dengan tanda ini meningkat 30%, serangan pedang lainnya meningkat 15%; jika Blood Slayer Akame menyerang target dengan tanda ini saat HP mereka turun ke 10% atau lebih rendah, serangan tersebut memberikan kerusakan tambahan setara dengan HP asli target saat ini (tidak lebih dari 300% Serangan Fisik Akame), setiap pengulangan meningkatkan batas darah tanda pembunuhan sebesar 5%).',
		describe_ph = 'Blood Slayer Akame ay nagpapalabas ng napakataas na bilis, pumuputol sa kaaway sa likod na may pinakamababang HP, nagdudulot ng #C0xE69900#350% Physical Attack #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage #C0x5B545B#, nagbibigay sa target ng walang hanggang [Murder Mark] (Murder Mark: Espesyal na epekto, ang mga atake ni Blood Slayer Akame sa target na may Murder Mark ay tumataas ng 30% ang pinsala, ang mga ibang sword-type na atake ay tumataas ng 15%; kapag inatake ni Blood Slayer Akame ang target na may Murder Mark na may HP na bumaba sa 10% o mas mababa, nagdudulot ito ng dagdag na pinsala na katumbas ng kasalukuyang totoong HP ng target (hindi lalampas sa 300% ng Physical Attack ni Akame). Sa bawat pag-uulit, tumataas ng 5% ang blood limit ng Murder Mark.)',
		describe_ma = 'Blood Slayer Akame melepaskan kelajuan sangat tinggi, membelah musuh yang berada di belakang dengan HP terendah, menghasilkan #C0xE69900#350% Serangan Fizikal #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, menyebabkan sasaran mendapat tanda [Pembunuhan] kekal (Tanda Pembunuhan: Kesan khas, serangan Blood Slayer Akame pada sasaran bertanda ini meningkat 30%, serangan pedang lain meningkat 15%; jika Blood Slayer Akame menyerang sasaran bertanda ini apabila HP mereka turun ke 10% atau ke bawah, ia memberikan kerosakan tambahan bersamaan HP sebenar sasaran pada masa itu (tidak melebihi 300% Serangan Fizikalnya sendiri). Setiap kali diulang, had darah tanda Pembunuhan meningkat sebanyak 5%).',
		describe = 'Blood Slayer Akame unleashes an extremely high speed, slashing through the enemy unit positioned behind with the lowest HP, dealing #C0xE69900#350% Physical Attack #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage #C0x5B545B#. This causes the target to gain an eternal [Murder Mark] (Murder Mark: Special effect, Blood Slayer Akame\'s attacks on targets with the Murder Mark deal 30% increased damage, while other sword-type attacks deal 15% increased damage; If Blood Slayer Akame attacks a target with the Murder Mark when their HP drops to 10% or below, it deals an extra damage equivalent to the target\'s current true HP (not exceeding 300% of Akame\'s Physical Attack). Each repeated hit increases the Murder Mark blood limit by 5%).',
		simDesc_vn = 'Zhan·Red Eyes phát nổ với tốc độ cực cao, rút ​​kiếm và tấn công mục tiêu địch có ít máu nhất ở hàng sau.',
		simDesc_en = 'Zhan·Red Eyes explodes at extreme speed, draws his sword, and attacks the enemy target with the lowest health in the back row.',
		simDesc_th = 'จั้น·เรดอายส์ ระเบิดด้วยความเร็วสูงสุด ดึงดาบออกมาและโจมตีเป้าหมายศัตรูที่มีพลังชีวิตต่ำที่สุดในแถวหลัง',
		simDesc_in = 'Zhan·Red Eyes meledak dengan kecepatan sangat tinggi, menghunus pedang dan menyerang target musuh dengan darah paling sedikit di barisan belakang.',
		simDesc_ph = 'Si Zhan·Red Eyes ay bumuga sa sobrang bilis, hilahin ang kanyang espada at atakehin ang kalaban na may pinakamababang HP sa likurang linya.',
		simDesc_ma = 'Zhan·Red Eyes meletup dengan kelajuan tinggi, menghunus pedang dan menyerang sasaran musuh yang mempunyai darah paling rendah di barisan belakang.',
		simDesc = 'Zhan·Red Eyes explodes at extreme speed, draws his sword, and attacks the enemy target with the lowest health in the back row.',
		zawakeEffect = __data_t__zawakeEffect[5742],
		-- {79002}
		zawakeEffectDesc = 'Zhan-Red Eye explodes with extremely high speed, draws the sword and attacks the enemy target with the lowest health in the back row, causing #C0xE69900#150% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, permanently adding <Predation> to the target. Mark (Plunder: special effect, damage of Zhan-Red Eye\'s attacks on targets marked by Plunder increases by 30% and other sword types increase by 15%; when attacking Plunder targets, if their HP falls below 10%, it deals additional true damage equal to their current HP (not exceeding 300% of its own Physical Damage). Each time the mark is added consecutively, the HP limit increases by 10%)',
		zawakeEffectDesc_en = 'Zhan-Red Eye explodes with extremely high speed, draws the sword and attacks the enemy target with the lowest health in the back row, causing #C0xE69900#150% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, permanently adding <Predation> to the target. Mark (Plunder: special effect, damage of Zhan-Red Eye\'s attacks on targets marked by Plunder increases by 30% and other sword types increase by 15%; when attacking Plunder targets, if their HP falls below 10%, it deals additional true damage equal to their current HP (not exceeding 300% of its own Physical Damage). Each time the mark is added consecutively, the HP limit increases by 10%)',
		zawakeEffectDesc_th = 'Zhan-Red Eye ระเบิดด้วยความเร็วสูงสุด วาดดาบและโจมตีเป้าหมายศัตรูที่มีเลือดต่ำที่สุดในแถวหลัง สร้างความเสียหายทางกายภาพ #C0xE69900#150%#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# เพิ่ม <Predation> ถาวรให้กับเป้าหมาย เครื่องหมาย (Plunder: เอฟเฟกต์พิเศษ ความเสียหายจากการโจมตีของ Zhan-Red Eye ต่อเป้าหมายที่ติดเครื่องหมาย Plunder เพิ่มขึ้น 30% และของดาบชนิดอื่นเพิ่มขึ้น 15%; เมื่อโจมตีเป้าหมาย Plunder หาก HP ของเป้าหมายน้อยกว่า 10% จะทำความเสียหายจริงเพิ่มเติมเท่ากับ HP ปัจจุบันของมัน (ไม่เกิน 300% ของความเสียหายทางกายภาพของตัวเอง) แต่ละครั้งที่เพิ่มเครื่องหมายต่อเนื่อง ขีดจำกัด HP จะเพิ่มขึ้น 10%)',
		zawakeEffectDesc_in = 'Zhan-Red Eye meledak dengan kecepatan sangat tinggi, menghunus pedang dan menyerang target musuh dengan darah terendah di barisan belakang, menyebabkan #C0xE69900#150% Damage Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Damage Fisik#C0x5B545B#, menambahkan <Predation> secara permanen ke target. Tanda (Plunder: efek khusus, damage serangan Zhan-Red Eye pada target yang ditandai Plunder meningkat 30% dan jenis pedang lain meningkat 15%; saat menyerang target Plunder, jika HP-nya turun di bawah 10%, akan memberikan damage nyata tambahan sebesar HP saat ini (tidak melebihi 300% Damage Fisiknya sendiri). Setiap kali tanda ditambahkan berturut-turut, batas HP bertambah 10%)',
		zawakeEffectDesc_ph = 'Zhan-Red Eye sumabog nang napakataas na bilis, hinawak ang espada at inatake ang kaaway na target na may pinakamababang HP sa likurang hanay, nagdudulot ng #C0xE69900#150% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, permanenteng nagdaragdag ng <Predation> sa target. Marka (Plunder: espesyal na epekto, ang pinsala ng mga atake ni Zhan-Red Eye sa mga target na may markang Plunder ay tumataas ng 30% at iba pang klase ng espada ay tumataas ng 15%; kapag inaatake ang target ng Plunder, kung bumaba ang HP nito sa ilalim ng 10%, magdudulot ito ng karagdagang tunay na pinsala na katumbas ng kasalukuyang HP nito (hindi lalampas sa 300% ng sariling Physical Damage nito). Sa bawat paulit-ulit na pagdagdag ng marka, tumataas ang limit ng HP ng 10%)',
		zawakeEffectDesc_ma = 'Zhan-Red Eye meletup dengan kelajuan sangat tinggi, menghunus pedang dan menyerang sasaran musuh dengan darah terendah di barisan belakang, menyebabkan #C0xE69900#150% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, menambah <Predation> secara kekal ke sasaran. Tanda (Plunder: kesan khas, kerosakan serangan Zhan-Red Eye pada sasaran yang ditandakan Plunder meningkat 30% dan jenis pedang lain meningkat 15%; apabila menyerang sasaran Plunder, jika HPnya turun di bawah 10%, ia akan memberikan kerosakan sebenar tambahan sama dengan HP semasa (tidak melebihi 300% Kerosakan Fizikalnya sendiri). Setiap kali tanda ditambah berturut-turut, had HP meningkat sebanyak 10%)',
		zawakeEffectDesc_vn = 'Zhan-Red Eye bùng nổ với tốc độ cực cao, rút ​​kiếm và tấn công mục tiêu địch có máu thấp nhất ở hàng sau, gây #C0xE69900#150% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, thêm <Predation> vĩnh viễn vào mục tiêu. Dấu ấn (Plunder: hiệu ứng đặc biệt, sát thương của đòn tấn công của Zhan-Red Eye lên mục tiêu được đánh dấu bởi Plunder tăng 30% và của các loại kiếm khác tăng 15%; khi tấn công mục tiêu Plunder, nếu HP của nó giảm xuống dưới 10%, nó sẽ gây thêm sát thương thực bằng HP hiện tại của nó (không vượt quá 300% đòn Sát Thương Vật Lý của chính nó). Mỗi lần dấu ấn được thêm vào liên tục, giới hạn HP sẽ tăng thêm 10%)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Each time this mark is added, increase max HP by 5%\n#F20# \n#F40##C0x5c9970#→Each time this mark is added, increase max HP by 10%#C0x5B545B#  ',
		zawakeSimpleDesc_en = 'Each time this mark is added, increase max HP by 5%\n#F20# \n#F40##C0x5c9970#→Each time this mark is added, increase max HP by 10%#C0x5B545B#  ',
		zawakeSimpleDesc_th = 'ทุกครั้งที่เพิ่มเครื่องหมายนี้ จะเพิ่มพลังชีวิตสูงสุด 5%\n#F20# \n#F40##C0x5c9970#→ทุกครั้งที่เพิ่มเครื่องหมายนี้ จะเพิ่มพลังชีวิตสูงสุด 10%#C0x5B545B#',
		zawakeSimpleDesc_in = 'Setiap kali tanda ini ditambahkan, tingkatkan HP maksimal sebesar 5%\n#F20# \n#F40##C0x5c9970#→Setiap kali tanda ini ditambahkan, tingkatkan HP maksimal sebesar 10%#C0x5B545B#  ',
