	[5746] = {
		id = 5746,
		skillName_vn = 'Sát Thần Ý Chí',
		skillName_en = 'Will of the Death God',
		skillName_th = 'เจตจำนงค์แห่งเทพมรณะ',
		skillName_in = 'Niat Dewa Kematian',
		skillName_ph = 'Kalooban ng Diyos ng Kamatayan',
		skillName_ma = 'Keazaman Dewa Kematian',
		skillName = 'Will of the Death God',
		describe_vn = 'Blood Slayer Akame sát ý bừng bừng phấn chấn, đại sát tứ phương, phe mình kiếm hệ hoặc Hắc Ám Hệ anh hùng tại đánh giết mục tiêu sau tự thân nhưng lập tức tái phát động một lần công kích;\n Đối HP thấp hơn 35% Mục tiêu ngoài định mức tạo thành #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# Tổn thương',
		describe_en = 'Blood Slayer Akame is fiercely ambitious and excited, ruthlessly slaying in all directions. Our side\'s Sword or Dark heroes attack targets after themselves but immediately reactivate to strike once more; \n Against targets with HP lower than 35%, dealing $(40+skillLevel*0.4-0.4)% damage beyond the limit.',
		describe_th = '[อาคาเมะ · สังหาร] ปลดปล่อยเจตนาสังหาร กวาดล้างศัตรูทุกสารทิศ เมื่อตัวละครฝ่ายเราที่เป็นสายดาบหรือสายความมืดสังหารศัตรูได้ จะสามารถโจมตีอีกครั้งได้ทันที;  สร้างความเสียหายเพิ่มเติมแก่เป้าหมายที่มีพลังชีวิตต่ำกว่า 35% อีก #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B#',
		describe_in = 'Blood Slayer Akame dengan semangat membara, membantai ke segala arah. Pihak kita yang menggunakan Sword atau Pahlawan Sistem Gelap menyerang target setelah dirinya sendiri dan langsung mengaktifkan serangan ulang; \n Melawan target dengan HP di bawah 35%, menghasilkan kerusakan $(40+skillLevel*0.4-0.4)% di luar batas normal.',
		describe_ph = 'Blood Slayer Akame ay puno ng labis na determinasyon at kasiglahan, malupit na sumasakop sa lahat ng panig. Ang ating panig na may Sword System o Dark System na mga bayani ay umatake sa mga target pagkatapos ng sarili nila at agad na muling nag-reactivate ng isang atake; \n Laban sa mga target na may HP na mas mababa sa 35%, nagdudulot ng $(40+skillLevel*0.4-0.4)% pinsala lampas sa normal na hangganan.',
		describe_ma = 'Blood Slayer Akame penuh semangat dan bersemangat, membunuh di semua arah. Pihak kita dengan pahlawan Sistem Pedang atau Kegelapan menyerang sasaran selepas dirinya sendiri dan serta-merta mengaktifkan serangan sekali lagi; \n Terhadap sasaran dengan HP kurang daripada 35%, menyebabkan kerosakan sebanyak $(40+skillLevel*0.4-0.4)% melebihi had.',
		describe = 'Blood Slayer Akame is fiercely ambitious and excited, ruthlessly slaying in all directions. Our side\'s Sword or Dark heroes attack targets after themselves but immediately reactivate to strike once more; \n Against targets with HP lower than 35%, dealing $(40+skillLevel*0.4-0.4)% damage beyond the limit.',
		starEffect = __data_t__starEffect[5746],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi tấn công mà không tiêu diệt mục tiêu, có xác suất gây <choáng> mục tiêu trong 1 lượt; xác suất choáng cao hơn khi tỷ lệ máu còn lại của mục tiêu cao, tối đa 30%.',
		starEffectDesc = 'Additional effect: When attacking without killing the target, there is a chance to <stun> the target for 1 turn; the stun chance is higher when the target\'s remaining HP is higher, up to 30%.',
		starEffectDesc_en = 'Additional effect: When attacking without killing the target, there is a chance to <stun> the target for 1 turn; the stun chance is higher when the target\'s remaining HP is higher, up to 30%.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อโจมตีโดยไม่ฆ่าเป้าหมาย มีโอกาสที่จะทำให้เป้าหมาย <มึนงง> เป็นเวลา 1 เทิร์น; โอกาสมึนงงจะสูงขึ้นเมื่อเปอร์เซ็นต์พลังชีวิตที่เหลือของเป้าหมายสูงขึ้น สูงสุด 30%',
		starEffectDesc_in = 'Efek tambahan: Ketika menyerang tanpa membunuh target, ada kemungkinan untuk <membuat pusing> target selama 1 giliran; peluang pusing lebih tinggi ketika persentase HP target yang tersisa tinggi, maksimal 30%.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag umatake nang hindi pinapatay ang target, may tsansang mag-<stun> ng target nang 1 turn; mas mataas ang tsansa ng stun kapag mataas ang natitirang HP ng target, hanggang 30%.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila menyerang tanpa mematikan sasaran, terdapat kemungkinan untuk <membuat sasaran terhuyung> selama 1 pusingan; kebarangkalian terhuyung lebih tinggi apabila peratusan HP sasaran yang tinggal tinggi, maksimum 30%.',
		zawakeEffect = __data_t__zawakeEffect[5746],
		-- {79004, 1}
		zawakeEffectDesc = 'Additional effect: when the user attacks but does not kill the target, there is a chance to <Stun> the target for 1 turn, the stun probability increases as the target\'s remaining HP rate increases, up to 60%',
		zawakeEffectDesc_en = 'Additional effect: when the user attacks but does not kill the target, there is a chance to <Stun> the target for 1 turn, the stun probability increases as the target\'s remaining HP rate increases, up to 60%',
		zawakeEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อผู้ใช้โจมตีแต่ไม่สามารถฆ่าเป้าหมายได้ มีโอกาส <มึนงง> เป้าหมายเป็นเวลา 1 เทิร์น อัตราการมึนงงจะสูงขึ้นตามอัตราพลังชีวิตที่เหลือของเป้าหมาย สูงสุด 60%',
		zawakeEffectDesc_in = 'Efek tambahan: ketika pengguna menyerang tetapi tidak membunuh target, ada kemungkinan <Pingsan> target selama 1 giliran, kemungkinan pingsan meningkat seiring dengan persentase HP target yang tersisa, maksimal 60%',
		zawakeEffectDesc_ph = 'Karagdagang epekto: kapag ang gumagamit ay umatake ngunit hindi napatay ang target, may tsansang <Stun> ang target sa loob ng 1 turn, tumataas ang tsansa ng stun habang mas mataas ang natitirang HP ng target, hanggang 60%',
		zawakeEffectDesc_ma = 'Kesan tambahan: apabila pengguna menyerang tetapi tidak membunuh sasaran, terdapat kemungkinan untuk <Kebingungan> sasaran selama 1 giliran, kebarangkalian kebingungan meningkat mengikut peratusan darah sasaran yang tinggal, maksimum 60%',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: khi bản thân tấn công không giết chết mục tiêu có khả năng <Choáng> mục tiêu trong 1 lượt, tỷ lệ choáng càng cao khi tỷ lệ máu còn lại của mục tiêu càng cao, tối đa 60%',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'When attacking without killing the target, has a chance to <stun> the target for 1 turn, the stun rate increases as the target\'s remaining HP rate increases, up to 30%\n#F20# \n#F40##C0x5c9970#→When attacking without killing the target, has a chance to <stun> the target for 1 turn, the stun rate increases as the target\'s remaining HP rate increases, up to 60%#C0x5B545B#  ',
		zawakeSimpleDesc_en = 'When attacking without killing the target, has a chance to <stun> the target for 1 turn, the stun rate increases as the target\'s remaining HP rate increases, up to 30%\n#F20# \n#F40##C0x5c9970#→When attacking without killing the target, has a chance to <stun> the target for 1 turn, the stun rate increases as the target\'s remaining HP rate increases, up to 60%#C0x5B545B#  ',
		zawakeSimpleDesc_th = 'เมื่อโจมตีแต่ไม่ฆ่าเป้าหมาย มีโอกาสทำให้เป้าหมาย <มึนงง> เป็นเวลา 1 เทิร์น อัตราการมึนงงจะเพิ่มขึ้นตามเปอร์เซ็นต์พลังชีวิตที่เหลือของเป้าหมาย สูงสุด 30%\n#F20# \n#F40##C0x5c9970#→เมื่อโจมตีแต่ไม่ฆ่าเป้าหมาย มีโอกาสทำให้เป้าหมาย <มึนงง> เป็นเวลา 1 เทิร์น อัตราการมึนงงจะเพิ่มขึ้นตามเปอร์เซ็นต์พลังชีวิตที่เหลือของเป้าหมาย สูงสุด 60%#C0x5B545B#',
		zawakeSimpleDesc_in = 'Saat menyerang tanpa membunuh target, ada kemungkinan untuk <stun> target selama 1 giliran, peluang stun meningkat saat persentase HP target semakin tinggi, maksimal 30%\n#F20# \n#F40##C0x5c9970#→Saat menyerang tanpa membunuh target, ada kemungkinan untuk <stun> target selama 1 giliran, peluang stun meningkat saat persentase HP target semakin tinggi, maksimal 60%#C0x5B545B#  ',
		zawakeSimpleDesc_ph = 'Kapag umaatake nang hindi pinapatay ang target, may tsansa na <stun> ang target sa loob ng 1 turn, tumataas ang tsansa ng stun habang mas mataas ang natitirang HP ng target, hanggang sa 30%\n#F20# \n#F40##C0x5c9970#→Kapag umaatake nang hindi pinapatay ang target, may tsansa na <stun> ang target sa loob ng 1 turn, tumataas ang tsansa ng stun habang mas mataas ang natitirang HP ng target, hanggang sa 60%#C0x5B545B#  ',
		zawakeSimpleDesc_ma = 'Apabila menyerang tanpa membunuh sasaran, ada peluang untuk <stun> sasaran selama 1 giliran, peluang stun meningkat apabila peratusan HP sasaran semakin tinggi, maksimum 30%\n#F20# \n#F40##C0x5c9970#→Apabila menyerang tanpa membunuh sasaran, ada peluang untuk <stun> sasaran selama 1 giliran, peluang stun meningkat apabila peratusan HP sasaran semakin tinggi, maksimum 60%#C0x5B545B#  ',
		zawakeSimpleDesc_vn = 'Khi tấn công không tiêu diệt mục tiêu, có xác suất <choáng> mục tiêu trong 1 lượt, tỷ lệ choáng càng cao khi tỷ lệ máu còn lại của mục tiêu càng cao, tối đa 30%\n#F20# \n#F40##C0x5c9970#→Khi tấn công không tiêu diệt mục tiêu, có xác suất <choáng> mục tiêu trong 1 lượt, tỷ lệ choáng càng cao khi tỷ lệ máu còn lại của mục tiêu càng cao, tối đa 60%#C0x5B545B#',
