	[5752] = {
		id = 5752,
		skillName_vn = 'Linh hồn - Tống táng',
		skillName_en = 'Soul - Funeral',
		skillName_th = 'วิญญาณ - งานศพ',
		skillName_in = 'Jiwa - Pemakaman',
		skillName_ph = 'Kaluluwa - Libing',
		skillName_ma = 'Jiwa - Pengebumian',
		skillName = 'Soul - Funeral',
		describe_vn = 'Blood Slayer Akame bộc phát tốc độ cực cao, bạt đao trảm kích địch quân xếp sau HP thấp nhất mục tiêu, gây #C0xE69900#350% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, thêm [Predation] vĩnh viễn vào mục tiêu. Dấu ấn (Plunder: hiệu ứng đặc biệt, sát thương của đòn tấn công của Blood Slayer Akame lên mục tiêu được đánh dấu bởi Plunder tăng 30% và của các loại kiếm khác tăng 15%; khi tấn công mục tiêu Plunder, nếu HP của nó giảm xuống dưới 10%, nó sẽ gây thêm sát thương thực bằng HP hiện tại của nó (không vượt quá 300% đòn Sát Thương Vật Lý của chính nó). Mỗi lần dấu ấn được thêm vào liên tục, giới hạn HP sẽ tăng thêm 5%)',
		describe_en = 'Blood Slayer Akame bursts out with extreme speed, slicing through the lowest HP target in the enemy ranks with a sword strike, dealing #C0xE69900#350% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, and permanently adds [Predation] to the target. Mark (Plunder: special effect where Blood Slayer Akame’s attack damage on a marked target increases by 30% and other swords\' damage increases by 15%; when attacking a Plunder-marked target, if its HP drops below 10%, it takes additional true damage equal to its current HP (not exceeding 300% of its own Physical Damage). Each consecutive application of the mark increases the HP limit by 5%).',
		describe_th = 'Blood Slayer Akame ปะทุด้วยความเร็วสูงสุด ตัดศัตรูที่มี HP ต่ำที่สุดในแถวหลังด้วยดาบ สร้างความเสียหายทางกายภาพ #C0xE69900#350%#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# พร้อมเพิ่ม [Predation] ให้เป้าหมายอย่างถาวร เครื่องหมาย (Plunder: ผลพิเศษที่ความเสียหายโจมตีของ Blood Slayer Akame กับเป้าหมายที่ติดเครื่องหมายเพิ่มขึ้น 30% และความเสียหายจากดาบอื่น ๆ เพิ่มขึ้น 15%; เมื่อโจมตีเป้าหมายที่มี Plunder ถ้า HP ของมันลดลงต่ำกว่า 10% จะสร้างความเสียหายจริงเพิ่มเติมตาม HP ปัจจุบันของมัน (ไม่เกิน 300% ของความเสียหายทางกายภาพของตัวเอง) แต่ละครั้งที่เพิ่มเครื่องหมายต่อเนื่องจะเพิ่มขีดจำกัด HP ขึ้นอีก 5%)',
		describe_in = 'Blood Slayer Akame meledak dengan kecepatan sangat tinggi, membelah musuh dengan HP terendah yang berada di barisan belakang dengan serangan pedang, memberikan #C0xE69900#350% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, serta secara permanen menambahkan [Predation] ke target. Tanda (Plunder: efek khusus dimana kerusakan serangan Blood Slayer Akame pada target yang diberi tanda meningkat 30% dan kerusakan dari pedang lain meningkat 15%; saat menyerang target yang bertanda Plunder, jika HP-nya turun di bawah 10%, akan memberikan damage nyata tambahan berdasarkan HP saat ini (tidak melebihi 300% Kerusakan Fisiknya sendiri). Setiap penambahan tanda berturut-turut akan meningkatkan batas HP sebesar 5%)',
		describe_ph = 'Blood Slayer Akame ay mabilis na sumabog, pinuputol ang kaaway na may pinakamababang HP sa likod gamit ang espada, na nagdudulot ng #C0xE69900#350% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#, at permanenteng naglalagay ng [Predation] sa target. Marka (Plunder: espesyal na epekto kung saan tumataas ng 30% ang pinsala ng mga atake ni Blood Slayer Akame sa isang naka-marka na target at 15% ang pinsala ng ibang mga espada; kapag inaatake ang target na may Plunder, kung ang HP nito ay bababa sa ilalim ng 10%, magdudulot ito ng dagdag na totoong pinsala batay sa kasalukuyang HP nito (hindi lalampas sa 300% ng sariling Pisikal na Pinsala). Sa bawat tuloy-tuloy na paglalagay ng marka, tumataas ang limit ng HP ng 5%)',
		describe_ma = 'Blood Slayer Akame meletus dengan kelajuan yang sangat tinggi, membelah musuh berHP terendah di belakang dengan serangan pedang, memberikan #C0xE69900#350% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, serta menambah [Predation] secara kekal kepada sasaran. Tanda (Plunder: kesan khas dimana kerosakan serangan Blood Slayer Akame ke sasaran bertanda meningkat 30% dan kerosakan dari pedang lain meningkat 15%; apabila menyerang sasaran bertanda Plunder, jika HPnya turun di bawah 10%, ia akan memberikan kerosakan nyata tambahan berdasarkan HP semasa (tidak melebihi 300% Kerosakan Fizikalnya sendiri). Setiap penambahan tanda berturut-turut meningkatkan had HP sebanyak 5%)',
		describe = 'Blood Slayer Akame bursts out with extreme speed, slicing through the lowest HP target in the enemy ranks with a sword strike, dealing #C0xE69900#350% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, and permanently adds [Predation] to the target. Mark (Plunder: special effect where Blood Slayer Akame’s attack damage on a marked target increases by 30% and other swords\' damage increases by 15%; when attacking a Plunder-marked target, if its HP drops below 10%, it takes additional true damage equal to its current HP (not exceeding 300% of its own Physical Damage). Each consecutive application of the mark increases the HP limit by 5%).',
		simDesc_vn = 'Zhan·Red Eyes phát nổ với tốc độ cực cao, rút ​​kiếm và tấn công mục tiêu địch có ít máu nhất ở hàng sau.',
		simDesc_en = 'Zhan·Red Eyes explodes at an extremely high speed, draws his sword, and attacks the enemy with the lowest health in the back row.',
		simDesc_th = 'จ้าน·เรดอายส์ระเบิดด้วยความเร็วสูงสุด ดึงดาบออกมาและโจมตีศัตรูที่มีเลือดน้อยที่สุดในแถวหลัง',
		simDesc_in = 'Zhan·Red Eyes meledak dengan kecepatan sangat tinggi, menghunus pedang dan menyerang musuh dengan HP terendah di barisan belakang.',
		simDesc_ph = 'Zhan·Red Eyes ay sumabog nang napakataas ang bilis, hinila ang kanyang espada at inatake ang kalabang may pinaka-mababang HP sa likurang hanay.',
		simDesc_ma = 'Zhan·Red Eyes meletup dengan kelajuan yang sangat tinggi, menghunus pedang dan menyerang musuh yang mempunyai darah paling rendah di barisan belakang.',
		simDesc = 'Zhan·Red Eyes explodes at an extremely high speed, draws his sword, and attacks the enemy with the lowest health in the back row.',
		zawakeEffect = __data_t__zawakeEffect[5752],
		-- {79002}
		zawakeEffectDesc = 'Zhan-Red Eye explodes with extreme speed, draws the sword and attacks the enemy target with the lowest health in the back row, causing #C0xE69900#150% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, adding <Predation> permanently to the target. Mark (Plunder: special effect, Zhan-Red Eye\'s attack damage on targets marked by Plunder increases by 30% and other swords increase by 15%; when attacking Plunder targets, if their HP falls below 10%, it deals additional true damage equal to their current HP (not exceeding 300% of its own Physical Damage). Each time the mark is added continuously, the HP limit increases by 10%)',
		zawakeEffectDesc_en = 'Zhan-Red Eye explodes with extreme speed, draws the sword and attacks the enemy target with the lowest health in the back row, causing #C0xE69900#150% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, adding <Predation> permanently to the target. Mark (Plunder: special effect, Zhan-Red Eye\'s attack damage on targets marked by Plunder increases by 30% and other swords increase by 15%; when attacking Plunder targets, if their HP falls below 10%, it deals additional true damage equal to their current HP (not exceeding 300% of its own Physical Damage). Each time the mark is added continuously, the HP limit increases by 10%)',
		zawakeEffectDesc_th = 'Zhan-Red Eye ระเบิดด้วยความเร็วสูงสุด ดึงดาบและโจมตีเป้าหมายศัตรูที่มีพลังชีวิตต่ำที่สุดในแถวหลัง ทำให้เกิด #C0xE69900#150% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# เพิ่ม <Predation> ให้กับเป้าหมายอย่างถาวร เครื่องหมาย (Plunder: เอฟเฟกต์พิเศษ ความเสียหายจากการโจมตีของ Zhan-Red Eye กับเป้าหมายที่มีมาร์ค Plunder เพิ่มขึ้น 30% และของดาบอื่น ๆ เพิ่มขึ้น 15%; เมื่อตีเป้าหมาย Plunder หาก HP ของเป้าหมายต่ำกว่า 10% จะสร้างความเสียหายจริงเพิ่มเติมตาม HP ปัจจุบันของเป้าหมาย (ไม่เกิน 300% ของความเสียหายทางกายภาพของตัวเอง) ทุกครั้งที่เพิ่มเครื่องหมายอย่างต่อเนื่อง ขีดจำกัด HP จะเพิ่มขึ้น 10%)',
		zawakeEffectDesc_in = 'Zhan-Red Eye meledak dengan kecepatan sangat tinggi, menghunus pedang dan menyerang target musuh dengan HP terendah di barisan belakang, menyebabkan #C0xE69900#150% Damage Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Damage Fisik#C0x5B545B#, menambahkan <Predation> secara permanen ke target. Tanda (Plunder: efek khusus, damage serangan Zhan-Red Eye pada target yang ditandai Plunder meningkat 30% dan pedang lain meningkat 15%; saat menyerang target Plunder, jika HP target turun di bawah 10%, ia memberikan damage nyata tambahan berdasarkan HP saat ini (tidak melebihi 300% dari Damage Fisik miliknya sendiri). Setiap kali tanda ditambahkan secara berturut-turut, batas HP meningkat 10%)',
		zawakeEffectDesc_ph = 'Zhan-Red Eye ay sumabog nang mataas na bilis, hinugot ang espada at inatake ang pinakamababang HP na kaaway sa likurang hanay, nagpapagastos ng #C0xE69900#150% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#, idinadagdag ang <Predation> nang permanente sa target. Marka (Plunder: espesyal na epekto, ang pinsala ng atake ni Zhan-Red Eye sa mga target na may markang Plunder ay tumataas ng 30% at ng ibang mga espada ay tumataas ng 15%; kapag inaatake ang mga target na Plunder, kung ang HP nito ay bumagsak sa ilalim ng 10%, magbibigay ito ng karagdagang totoong pinsala na katumbas ng kasalukuyang HP nito (hindi lalampas sa 300% ng sariling Pisikal na Pinsala nito). Sa bawat beses na ang marka ay naidagdag nang sunud-sunod, tumataas ang limitasyon ng HP ng 10%)',
		zawakeEffectDesc_ma = 'Zhan-Red Eye meletup dengan kelajuan tinggi, menghunus pedang dan menyerang sasaran musuh yang mempunyai darah paling rendah di barisan belakang, menyebabkan #C0xE69900#150% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, menambah <Predation> secara kekal kepada sasaran. Tanda (Plunder: kesan istimewa, kerosakan serangan Zhan-Red Eye ke atas sasaran yang ditandakan oleh Plunder meningkat sebanyak 30% dan pedang lain meningkat sebanyak 15%; semasa menyerang sasaran Plunder, jika HP sasaran jatuh di bawah 10%, ia memberikan kerosakan sebenar tambahan mengikut HP semasa (tidak melebihi 300% Kerosakan Fizikalnya sendiri). Setiap kali tanda ditambah secara berterusan, had HP akan meningkat sebanyak 10%)',
		zawakeEffectDesc_vn = 'Zhan-Red Eye bùng nổ với tốc độ cực cao, rút ​​kiếm và tấn công mục tiêu địch có máu thấp nhất ở hàng sau, gây #C0xE69900#150% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, thêm <Predation> vĩnh viễn vào mục tiêu. Dấu ấn (Plunder: hiệu ứng đặc biệt, sát thương của đòn tấn công của Zhan-Red Eye lên mục tiêu được đánh dấu bởi Plunder tăng 30% và của các loại kiếm khác tăng 15%; khi tấn công mục tiêu Plunder, nếu HP của nó giảm xuống dưới 10%, nó sẽ gây thêm sát thương thực bằng HP hiện tại của nó (không vượt quá 300% đòn Sát Thương Vật Lý của chính nó). Mỗi lần dấu ấn được thêm vào liên tục, giới hạn HP sẽ tăng thêm 10%)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Each time this mark is added, increase max HP by 5%\n#F20# \n#F40##C0x5c9970#→Each time this mark is added, increase max HP by 10%#C0x5B545B#  ',
		zawakeSimpleDesc_en = 'Each time this mark is added, increase max HP by 5%\n#F20# \n#F40##C0x5c9970#→Each time this mark is added, increase max HP by 10%#C0x5B545B#  ',
		zawakeSimpleDesc_th = 'ทุกครั้งที่เพิ่มเครื่องหมายนี้ จะเพิ่มพลังชีวิตสูงสุด 5%\n#F20# \n#F40##C0x5c9970#→ทุกครั้งที่เพิ่มเครื่องหมายนี้ จะเพิ่มพลังชีวิตสูงสุด 10%#C0x5B545B#',
		zawakeSimpleDesc_in = 'Setiap kali tanda ini ditambahkan, tingkatkan HP maksimal sebesar 5%\n#F20# \n#F40##C0x5c9970#→Setiap kali tanda ini ditambahkan, tingkatkan HP maksimal sebesar 10%#C0x5B545B#  ',
