		skillName_in = 'Jiwa - Murasame',
		skillName_ph = 'Kaluluwa - Murasame',
		skillName_ma = 'Jiwa - Murasame',
		skillName = 'Soul - Murasame',
		describe_vn = 'Blood Slayer Akame sử dụng Murasame và thực hiện Blade Waltz, tấn công mục tiêu của kẻ địch có HP thấp nhất ở hàng sau, gây #C0xE69900#800% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*90)$ F13B54#Sát Thương Vật Lý#C0x5B545B#, hấp thụ 30% đòn Sát Thương Vật Lý của mục tiêu trong 3 vòng. Nếu mục tiêu không bị giết bởi đòn tấn công này, nó sẽ vào [tàng hình] trong 1 lượt (hiệu ứng đặc biệt, không thể chọn và giảm 20% sát thương khu vực nhận được)',
		describe_en = 'Blood Slayer Akame wields Murasame and performs Blade Waltz, attacking the enemy with the lowest HP in the back row, dealing 800% Physical Damage + $(skillLevel*4*90)$ Physical Damage, absorbing 30% of the target\'s Physical Damage for 3 turns. If the target is not killed by this attack, it enters [stealth] for 1 turn (special effect, cannot be targeted and receives 20% less area damage).',
		describe_th = 'Blood Slayer Akame ใช้ Murasame และทำการโจมตี Blade Waltz โจมตีศัตรูที่มี HP ต่ำที่สุดในแถวหลัง ทำดาเมจ ฟิสิคอล 800% + $(skillLevel*4*90)$ ดาเมจฟิสิคอล ดูดซับดาเมจฟิสิคอลของเป้าหมาย 30% เป็นเวลา 3 เทิร์น หากเป้าหมายไม่ถูกฆ่าด้วยการโจมตีนี้ จะเข้าสู่สถานะ [ล่องหน] เป็นเวลา 1 เทิร์น (เอฟเฟกต์พิเศษ ไม่สามารถเลือกเป้าหมายได้และรับดาเมจพื้นที่ลดลง 20%)',
		describe_in = 'Blood Slayer Akame menggunakan Murasame dan melaksanakan Blade Waltz, menyerang musuh dengan HP terendah di barisan belakang, memberikan 800% Kerusakan Fisik + $(skillLevel*4*90)$ Kerusakan Fisik, menyerap 30% dari Kerusakan Fisik target selama 3 giliran. Jika target tidak terbunuh oleh serangan ini, ia memasuki [modes stealth] selama 1 giliran (efek khusus, tidak dapat dipilih dan menerima 20% lebih sedikit kerusakan area).',
		describe_ph = 'Blood Slayer Akame ay gumagamit ng Murasame at nagsasagawa ng Blade Waltz, ina-atake ang kalabang may pinakamababang HP sa likod na hanay, na nagdudulot ng 800% Physical Damage + $(skillLevel*4*90)$ Physical Damage, sumisipsip ng 30% ng Physical Damage ng target sa loob ng 3 turn. Kung ang target ay hindi mapapatay ng atakeng ito, papasok ito sa [stealth] sa loob ng 1 turn (espesyal na epekto, hindi maaaring pagpilian at nakakabawas ng 20% ng natanggap na area damage).',
		describe_ma = 'Blood Slayer Akame menggunakan Murasame dan melakukan Blade Waltz, menyerang musuh dengan HP terendah di barisan belakang, memberikan 800% Daya Hancur Fizikal + $(skillLevel*4*90)$ Daya Hancur Fizikal, menyerap 30% kerosakan Fizikal daripada sasaran selama 3 giliran. Jika sasaran tidak dibunuh oleh serangan ini, ia akan memasuki [penyamaran] selama 1 giliran (kesan khas, tidak boleh dipilih dan menerima 20% kurang kerosakan kawasan).',
		describe = 'Blood Slayer Akame wields Murasame and performs Blade Waltz, attacking the enemy with the lowest HP in the back row, dealing 800% Physical Damage + $(skillLevel*4*90)$ Physical Damage, absorbing 30% of the target\'s Physical Damage for 3 turns. If the target is not killed by this attack, it enters [stealth] for 1 turn (special effect, cannot be targeted and receives 20% less area damage).',
		simDesc_vn = 'Zhan Chitong sử dụng Murasame thực hiện Blade Waltz, tấn công mục tiêu có lượng máu thấp nhất ở hàng sau của kẻ địch và hấp thụ đòn tấn công vật lý của nó.',
		simDesc_en = 'Zhan Chitong uses Murasame to perform Blade Waltz, attacking the enemy with the lowest health in the back row and absorbing its physical attack.',
		simDesc_th = 'จ้าน ชี่ทง ใช้มูราซาเมะในการร่ายบเลดวอลต์ซ่า โจมตีกับศัตรูที่มีพลังชีวิตต่ำที่สุดในแถวหลัง และดูดซับการโจมตีทางกายภาพของมัน',
		simDesc_in = 'Zhan Chitong menggunakan Murasame untuk melakukan Blade Waltz, menyerang musuh dengan darah terendah di barisan belakang dan menyerap serangan fisiknya.',
		simDesc_ph = 'Gumagamit si Zhan Chitong ng Murasame upang isagawa ang Blade Waltz, inaatake ang kalaban na may pinakamababang HP sa likurang hanay at sinisipsip ang pisikal nitong atake.',
		simDesc_ma = 'Zhan Chitong menggunakan Murasame untuk melakukan Blade Waltz, menyerang musuh yang mempunyai darah paling rendah di barisan belakang dan menyerap serangan fizikalnya.',
		simDesc = 'Zhan Chitong uses Murasame to perform Blade Waltz, attacking the enemy with the lowest health in the back row and absorbing its physical attack.',
		starEffect = __data_t__starEffect[5753],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Nếu kỹ năng chí mạng không tiêu diệt mục tiêu, có thể hành động thêm một lần nữa và trả lại 40% năng lượng đã tiêu tốn.',
		starEffectDesc = 'Additional effect: If the critical skill does not defeat the target, you can act one more time and recover 40% of the energy spent.',
		starEffectDesc_en = 'Additional effect: If the critical skill does not defeat the target, you can act one more time and recover 40% of the energy spent.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: หากทักษะคริติคอลไม่สามารถกำจัดเป้าหมายได้ คุณสามารถทำการโจมตีอีกครั้งและคืนพลังงานที่ใช้ไป 40%',
		starEffectDesc_in = 'Efek tambahan: Jika keterampilan kritis tidak mengalahkan target, Anda dapat bertindak satu kali lagi dan mengembalikan 40% energi yang telah digunakan.',
		starEffectDesc_ph = 'Karagdagang epekto: Kung hindi mapatay ng critical skill ang target, maaaring kumilos ng isa pang beses at maibalik ang 40% ng nagastos na enerhiya.',
		starEffectDesc_ma = 'Kesan tambahan: Jika kemahiran kritikal tidak memusnahkan sasaran, anda boleh bertindak sekali lagi dan mengembalikan 40% tenaga yang telah digunakan.',
		zawakeEffect = __data_t__zawakeEffect[5753],
		-- {79003}
		zawakeEffectDesc = 'Zhan-Akatomi uses Murasame to perform Blade Waltz, attacking the target with the lowest HP in the back row, dealing #C0xE69900#450% Physical Damage#C0x5B545B#+$(skillLevel*4*75)$\'s #C0x F13B54#Physical Damage#C0x5B545B#, absorbing 30% of the target\'s Physical Damage for 3 turns. If the target is not killed by this attack, it will enter <invisible> for 1 turn (special effect, cannot be targeted and reduces 60% AoE damage received).',
		zawakeEffectDesc_en = 'Zhan-Akatomi uses Murasame to perform Blade Waltz, attacking the target with the lowest HP in the back row, dealing #C0xE69900#450% Physical Damage#C0x5B545B#+$(skillLevel*4*75)$\'s #C0x F13B54#Physical Damage#C0x5B545B#, absorbing 30% of the target\'s Physical Damage for 3 turns. If the target is not killed by this attack, it will enter <invisible> for 1 turn (special effect, cannot be targeted and reduces 60% AoE damage received).',
		zawakeEffectDesc_th = 'Zhan-Akatomi ใช้ Murasame ทำการ Blade Waltz โจมตีเป้าหมายที่มี HP ต่ำที่สุดในแถวหลัง สร้าง #C0xE69900#450% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*75)$\'s #C0x F13B54#ความเสียหายทางกายภาพ#C0x5B545B# ดูดซับความเสียหายทางกายภาพของเป้าหมาย 30% เป็นเวลา 3 เทิร์น หากเป้าหมายไม่ตายในโจมตีนี้ จะเข้าสู่ <ล่องหน> เป็นเวลา 1 เทิร์น (ผลพิเศษ ไม่สามารถถูกเลือกและลดความเสียหาย AoE ที่ได้รับลง 60%)',
		zawakeEffectDesc_in = 'Zhan-Akatomi menggunakan Murasame untuk melakukan Blade Waltz, menyerang target dengan HP terendah di barisan belakang, memberikan #C0xE69900#450% Damage Fisik#C0x5B545B#+$(skillLevel*4*75)$\'s #C0x F13B54#Damage Fisik#C0x5B545B#, menyerap 30% damage fisik target selama 3 giliran. Jika target tidak mati akibat serangan ini, target akan memasuki <tidak terlihat> selama 1 giliran (efek khusus, tidak dapat dipilih dan mengurangi 60% damage AoE yang diterima).',
		zawakeEffectDesc_ph = 'Gamitin ni Zhan-Akatomi ang Murasame para isagawa ang Blade Waltz, umatake sa target na may pinakamababang HP sa likurang linya, na nagdudulot ng #C0xE69900#450% Physical Damage#C0x5B545B#+$(skillLevel*4*75)$\'s #C0x F13B54#Physical Damage#C0x5B545B#, sumisipsip ng 30% ng Physical Damage ng target sa loob ng 3 turns. Kung hindi mapapatay ng atake na ito ang target, papasok ito sa <invisible> sa loob ng 1 turn (espesyal na epekto, hindi maaaring piliin at pinabababa ang 60% AoE damage na natatanggap).',
		zawakeEffectDesc_ma = 'Zhan-Akatomi menggunakan Murasame untuk melaksanakan Blade Waltz, menyerang sasaran dengan HP terendah di barisan belakang, menyebabkan #C0xE69900#450% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*75)$\'s #C0x F13B54#Kerosakan Fizikal#C0x5B545B#, menyerap 30% kerosakan fizikal sasaran selama 3 pusingan. Jika sasaran tidak mati akibat serangan ini, ia akan memasuki <tidak kelihatan> selama 1 pusingan (kesan khas, tidak boleh dipilih dan mengurangkan 60% kerosakan AoE diterima).',
		zawakeEffectDesc_vn = 'Zhan-Akatomi sử dụng Murasame thực hiện Blade Waltz, tấn công mục tiêu có HP thấp nhất ở hàng sau, gây #C0xE69900#450% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*75)$\'s #C0x F13B54#Sát Thương Vật Lý#C0x5B545B#, hấp thụ 30% sát thương của mục tiêu Sát Thương Vật Lý trong 3 hiệp. Nếu mục tiêu không bị giết bởi đòn tấn công này, nó sẽ vào <tàng hình> trong 1 lượt (hiệu ứng đặc biệt, không thể chọn và giảm 60% sát thương diện rộng nhận được)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Reduce AoE damage received by 20%\n#F20# \n#F40##C0x5c9970#→Reduce AoE damage received by 60%#C0x5B545B#',
