	[5756] = {
		id = 5756,
		skillName_vn = 'Sát Thần Ý Chí',
		skillName_en = 'Will of the Death God',
		skillName_th = 'เจตจำนงแห่งเทพเจ้าแห่งความตาย',
		skillName_in = 'Niat Dewa Kematian',
		skillName_ph = 'Kalooban ng Diyos ng Kamatayan',
		skillName_ma = 'Tekad Dewa Kematian',
		skillName = 'Will of the Death God',
		describe_vn = 'Blood Slayer Akame tràn đầy sát ý, giết chóc mọi phương hướng. Sau khi tiêu diệt mục tiêu, thanh kiếm hoặc anh hùng bóng tối của bạn có thể ngay lập tức tung ra một đòn tấn công khác;\nGây thêm #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# sát thương cho mục tiêu có máu thấp hơn 35%.',
		describe_en = 'Blood Slayer Akame is filled with murderous intent, slaying in all directions. After defeating a target, your sword or dark hero can immediately unleash another attack; \n Deals an additional #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# damage to targets with less than 35% HP.',
		describe_th = 'เลือดนักฆ่าอาคาเมะเต็มไปด้วยความมุ่งมั่นที่จะสังหาร คร่าชีวิตทุกทิศทาง หลังจากกำจัดเป้าหมาย ดาบหรือฮีโร่แห่งความมืดของคุณสามารถโจมตีอีกครั้งได้ทันที; \n สร้างความเสียหายเพิ่มเติม #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# กับเป้าหมายที่มีพลังชีวิตต่ำกว่า 35%.',
		describe_in = 'Blood Slayer Akame dipenuhi dengan niat membunuh, membunuh ke segala arah. Setelah mengalahkan target, pedang atau pahlawan kegelapan Anda dapat segera melancarkan serangan lain; \n Memberikan tambahan #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# kerusakan kepada target dengan HP di bawah 35%.',
		describe_ph = 'Si Blood Slayer Akame ay puno ng matinding layuning pumatay, pumapatay sa lahat ng direksyon. Pagkatapos matanggal ang target, ang iyong espada o madilim na bayani ay maaaring agad na maglunsad ng isa pang pag-atake; \n Nagdadagdag ng #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# pinsala sa target na may mas mababang 35% na HP.',
		describe_ma = 'Blood Slayer Akame dipenuhi dengan niat untuk membunuh, membunuh ke semua arah. Selepas mengalahkan sasaran, pedang atau wira gelap anda boleh segera melancarkan serangan lain; \n Menyebabkan tambahan #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# kerosakan untuk sasaran yang mempunyai kurang daripada 35% HP.',
		describe = 'Blood Slayer Akame is filled with murderous intent, slaying in all directions. After defeating a target, your sword or dark hero can immediately unleash another attack; \n Deals an additional #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# damage to targets with less than 35% HP.',
		starEffect = __data_t__starEffect[5756],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi tấn công mà không tiêu diệt mục tiêu, có xác suất gây <choáng> mục tiêu trong 1 lượt; xác suất choáng cao hơn khi tỷ lệ máu còn lại của mục tiêu cao, tối đa 30%.',
		starEffectDesc = 'Additional effect: When attacking without killing the target, there is a chance to cause <stun> the target for 1 turn; the stun chance is higher when the target\'s remaining HP is higher, up to 30%.',
		starEffectDesc_en = 'Additional effect: When attacking without killing the target, there is a chance to cause <stun> the target for 1 turn; the stun chance is higher when the target\'s remaining HP is higher, up to 30%.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อโจมตีโดยไม่ฆ่าศัตรู มีโอกาสทำให้ <มึนงง> ศัตรูเป็นเวลา 1 เทิร์น; โอกาสมึนงงจะสูงขึ้นเมื่อเปอร์เซ็นต์พลังชีวิตที่เหลือของศัตรูสูงขึ้น สูงสุด 30%',
		starEffectDesc_in = 'Efek tambahan: Saat menyerang tanpa membunuh target, ada kemungkinan menyebabkan <stun> target selama 1 giliran; kemungkinan stun lebih tinggi saat persentase HP target yang tersisa lebih tinggi, maksimal 30%.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag umatake ngunit hindi napatay ang target, may posibilidad na magdulot ng <stun> sa target ng 1 turn; mas mataas ang posibilidad ng stun kapag mataas ang natitirang HP ng target, hanggang 30%.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila menyerang tanpa membunuh sasaran, terdapat kemungkinan untuk menyebabkan <stun> sasaran selama 1 giliran; kemungkinan stun lebih tinggi apabila peratusan kesihatan sasaran yang tinggal lebih tinggi, sehingga maksima 30%.',
		zawakeEffect = __data_t__zawakeEffect[5756],
		-- {79004, 1}
		zawakeEffectDesc = 'Additional effect: when attacking without killing the target, there is a chance to <Stun> the target for 1 turn, the stun chance increases the higher the target\'s remaining HP rate is, up to 60%',
		zawakeEffectDesc_en = 'Additional effect: when attacking without killing the target, there is a chance to <Stun> the target for 1 turn, the stun chance increases the higher the target\'s remaining HP rate is, up to 60%',
		zawakeEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อโจมตีโดยไม่ฆ่าเป้าหมาย มีโอกาส <มึนงง> เป้าหมายเป็นเวลา 1 เทิร์น อัตราการมึนงงจะสูงขึ้นเมื่ออัตราพลังชีวิตที่เหลือของเป้าหมายสูงขึ้น สูงสุด 60%',
		zawakeEffectDesc_in = 'Efek tambahan: saat menyerang tanpa membunuh target, ada kemungkinan untuk <Pingsan> target selama 1 giliran, peluang pingsan meningkat semakin tinggi persentase HP yang tersisa dari target, maksimal 60%',
