	[6033] = {
		id = 6033,
		skillName_vn = 'Ma Long liệt hỏa bào',
		skillName_en = 'Ma Long fiery blast',
		skillName_th = 'ม้าหลงระเบิดไฟ',
		skillName_in = 'Ma Long ledakan api',
		skillName_ph = 'Ma Long na naglalagablab na pagsabog',
		skillName_ma = 'Letupan api Ma Long',
		skillName = 'Ma Long fiery blast',
		describe_vn = 'Lina-Inverse tập trung toàn bộ năng lượng trong cơ thể, giải phóng rồng lửa ma thuật tấn công mục tiêu hàng dọc địch, gây #C0x3D8A99#350% Phép Công #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, duy nhất một lần kết toán mục tiêu trên thân tất cả thiêu đốt tổn thương ( Kết toán tổn thương tối cao không thể vượt qua tự thân Phép Công 1000%), như chưa đánh giết mục tiêu thì cho tăng thêm [ Thiêu đốt ] 2 Hiệp',
		describe_en = 'Lina-Inverse concentrates all the energy in her body, unleashing a magical fire dragon to attack vertical enemy targets, dealing #C0x3D8A99#350% Magic Attack #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Magic Damage #C0x5B545B#. This effect triggers only once per target on the entire body, burning the damaged enemies (The maximum burn damage cannot exceed 1000% of her own Magic Attack). If the target is not killed, it will add [Burn] for 2 more turns.',
		describe_th = 'ลิน่า-อินเวิร์ส รวมพลังทั้งหมดในร่างกาย ปล่อยมังกรเพลิงเวทมนตร์โจมตีศัตรูในแนวตั้ง ทำให้เกิดความเสียหาย #C0x3D8A99#350% พลังเวท #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# ประสิทธิภาพนี้จะเกิดขึ้นเพียงครั้งเดียวต่อเป้าหมายทั่วทั้งร่าง ก่อให้เกิดการเผาไหม้ศัตรูที่ได้รับความเสียหาย (ความเสียหายการเผาไหม้สูงสุดไม่เกิน 1000% ของพลังเวทตัวเอง) หากเป้าหมายไม่ตาย จะเพิ่มสถานะ [เผาไหม้] อีก 2 รอบ',
		describe_in = 'Lina-Inverse mengumpulkan seluruh energi dalam tubuhnya, melepaskan naga api sihir yang menyerang target musuh secara vertikal, memberikan #C0x3D8A99#350% Serangan Sihir #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Efek ini hanya terjadi satu kali untuk setiap target di seluruh tubuh, membakar musuh yang terluka (Kerusakan bakar maksimum tidak boleh melebihi 1000% Serangan Sihirnya sendiri). Jika target tidak mati, akan menambahkan [Terbakar] selama 2 giliran lagi.',
		describe_ph = 'Si Lina-Inverse ay kinokonsentra ang lahat ng enerhiya sa kanyang katawan, nagpapalaya ng isang mahiwagang apoy na dragon upang atakehin ang mga patayong target na kalaban, nagdudulot ng #C0x3D8A99#350% Magic Attack #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Magic Damage #C0x5B545B#. Ang epekto na ito ay nagaganap lamang isang beses sa bawat target sa buong katawan, nasusunog ang mga naapektuhang kalaban (Ang pinakamataas na nasusunog na pinsala ay hindi maaaring lumampas sa 1000% ng sariling Magic Attack). Kung hindi mapatay ang target, magdadagdag ito ng [Burn] sa loob ng 2 turn pa.',
		describe_ma = 'Lina-Inverse menumpukan semua tenaga dalam badannya, melepaskan naga api sihir yang menyerang sasaran musuh secara menegak, memberikan #C0x3D8A99#350% Serangan Sihir #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Kesan ini hanya berlaku sekali kepada setiap sasaran di seluruh badan, membakar musuh yang terjejas (Kerosakan terbakar maksimum tidak boleh melebihi 1000% Serangan Sihir dirinya sendiri). Jika sasaran tidak mati, ia akan menambah [Terbakar] selama 2 pusingan lagi.',
		describe = 'Lina-Inverse concentrates all the energy in her body, unleashing a magical fire dragon to attack vertical enemy targets, dealing #C0x3D8A99#350% Magic Attack #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Magic Damage #C0x5B545B#. This effect triggers only once per target on the entire body, burning the damaged enemies (The maximum burn damage cannot exceed 1000% of her own Magic Attack). If the target is not killed, it will add [Burn] for 2 more turns.',
		simDesc_vn = 'Lina Inverse tập trung toàn bộ sức mạnh bên trong, phóng ra "Hỏa Long Gầm Thét" tấn công mục tiêu hàng ngang của đối phương, gây nổ trạng thái cháy trên mục tiêu và thêm một lớp cháy.',
		simDesc_en = 'Lina Inverse focuses all her inner power, unleashing the "Blazing Dragon Roar" to attack a horizontal line of enemies, causing an explosion of burning status on targets and adding an additional burn layer.',
		simDesc_th = 'ลินา อินเวิร์สรวมพลังทั้งหมดในตัว ปล่อย "คำรามมังกรเพลิง" โจมตีเป้าหมายในแนวนอนของศัตรู ทำให้เกิดระเบิดสถานะไฟลุกบนเป้าหมายและเพิ่มชั้นไฟไหม้อีกชั้นหนึ่ง',
		simDesc_in = 'Lina Inverse memfokuskan seluruh kekuatan batinnya, meluncurkan "Raungan Naga Api" untuk menyerang baris horizontal musuh, menyebabkan ledakan efek terbakar pada target dan menambahkan lapisan terbakar tambahan.',
		simDesc_ph = 'Pinagtutuunan ni Lina Inverse ang lahat ng kanyang panloob na lakas, inilalabas ang "Naglalagablab na Dragon Roar" para atakihin ang pahalang na hanay ng mga kalaban, nagdudulot ng pagsabog ng sunog na estado sa mga target at nagdadagdag ng isang dagdag na patong ng apoy.',
		simDesc_ma = 'Lina Inverse menumpukan semua kekuatan dalaman, melepaskan "Raungan Naga Api" menyerang barisan mendatar musuh, menyebabkan letupan status terbakar pada sasaran dan menambah satu lapisan terbakar lagi.',
		simDesc = 'Lina Inverse focuses all her inner power, unleashing the "Blazing Dragon Roar" to attack a horizontal line of enemies, causing an explosion of burning status on targets and adding an additional burn layer.',
		starEffect = __data_t__starEffect[6033],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Tăng 20% giới hạn sát thương cháy, nếu không tiêu diệt mục tiêu sẽ thêm 1 lớp cháy.',
		starEffectDesc = 'Additional effect: Increases burn damage limit by 20%. If the target is not defeated, add 1 stack of burn.',
		starEffectDesc_en = 'Additional effect: Increases burn damage limit by 20%. If the target is not defeated, add 1 stack of burn.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เพิ่มขีดจำกัดความเสียหายจากการเผาไหม้ขึ้น 20% หากไม่สามารถกำจัดเป้าหมายได้ จะเพิ่มสถานะเผาไหม้อีก 1 ชั้น',
		starEffectDesc_in = 'Efek tambahan: Meningkatkan batas kerusakan terbakar sebesar 20%. Jika target tidak dikalahkan, tambahkan 1 tumpukan terbakar.',
		starEffectDesc_ph = 'Karagdagang epekto: Pinapataas ang limitasyon ng nasusunog na pinsala ng 20%. Kung hindi mapapatay ang target, magdadagdag ng 1 layer ng pagsunog.',
		starEffectDesc_ma = 'Kesan tambahan: Meningkatkan had kerosakan terbakar sebanyak 20%. Jika sasaran tidak dikalahkan, tambah 1 lapisan terbakar.',
		zawakeEffect = __data_t__zawakeEffect[6033],
		-- {79003, 1}
		zawakeEffectDesc = 'Additional effect: Increase fire damage limit by 20%, if the target is not killed then add 1 burn stack, and recalculate fire damage on the target at a rate of 20%',
		zawakeEffectDesc_en = 'Additional effect: Increase fire damage limit by 20%, if the target is not killed then add 1 burn stack, and recalculate fire damage on the target at a rate of 20%',
		zawakeEffectDesc_th = 'ผลเสริม: เพิ่มขีดจำกัดความเสียหายจากไฟ 20% ถ้าไม่ฆ่าเป้าหมายให้เพิ่มชั้นไฟไหม้ 1 ชั้น และคำนวณความเสียหายจากไฟบนเป้าหมายใหม่ที่อัตรา 20%',
		zawakeEffectDesc_in = 'Efek tambahan: Tingkatkan batas kerusakan api sebesar 20%, jika target tidak mati maka tambahkan 1 tumpukan terbakar, dan hitung ulang kerusakan api pada target dengan rasio 20%',
		zawakeEffectDesc_ph = 'Karagdagang epekto: Dagdagan ng 20% ang limitasyon ng nasusunog na pinsala, kung hindi napatay ang target magdagdag ng 1 burn stack, at muling kalkulahin ang nasusunog na pinsala sa target sa rate na 20%',
		zawakeEffectDesc_ma = 'Kesan tambahan: Tambah had kerosakan api sebanyak 20%, jika sasaran tidak mati tambah 1 lapisan terbakar, dan kira semula kerosakan api pada sasaran pada kadar 20%',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: Tăng 20% giới hạn sát thương cháy, nếu không giết mục tiêu thì thêm 1 lớp cháy, và tính lại sát thương cháy trên mục tiêu với tỷ lệ 20%',
		zawakeSimpleType = 1,
