	[6333] = {
		id = 6333,
		skillName_vn = 'Nhảy nước rồng',
		skillName_en = 'Dragon Water Jump',
		skillName_th = 'กระโดดน้ำมังกร',
		skillName_in = 'Lompat Air Naga',
		skillName_ph = 'Dragon Water Jump',
		skillName_ma = 'Lompat Air Naga',
		skillName = 'Dragon Water Jump',
		describe_vn = 'Bạo Lệ Long nhảy lên không trung rồi phun pháo nước tấn công mục tiêu hàng ngang của kẻ địch, gây #C0xE69900#300% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, xóa bỏ toàn bộ hiệu ứng tăng cường của mục tiêu, tăng 80% sát thương chí mạng cho lần tấn công này, nếu kích hoạt chí mạng, sau khi tấn công bản thân có khả năng rơi vào trạng thái hỗn loạn 1-2 lượt (tỷ lệ hỗn loạn càng cao khi tỷ lệ chí mạng hiện tại của bản thân càng cao và số lần sử dụng kỹ năng tuyệt chiêu càng nhiều); nếu không kích hoạt chí mạng, sát thương chí mạng của kỹ năng tuyệt chiêu lần sau sẽ tăng gấp đôi',
		describe_en = 'Violent Dragon leaps into the air and sprays water cannons to attack a horizontal line of enemies, dealing #C0xE69900#300% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#. It removes all buffs from the targets, increases critical damage by 80% for this attack. If a critical hit is triggered, the user may enter a chaotic state for 1-2 turns (the chance of chaos increases with the user\'s current critical rate and the number of times the ultimate skill has been used). If no critical hit occurs, the critical damage of the next ultimate skill will be doubled.',
		describe_th = 'มังกรป่าเถื่อนกระโดดขึ้นกลางอากาศแล้วพ่นน้ำโจมตีเป้าหมายในแนวราบของศัตรู ทำความเสียหาย #C0xE69900#300% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ลบสถานะเพิ่มพลังทั้งหมดของเป้าหมาย เพิ่มความเสียหายคริติคอล 80% สำหรับการโจมตีครั้งนี้ หากเกิดคริติคอล ผู้ใช้อาจเข้าสู่สถานะสับสนเป็นเวลา 1-2 เทิร์น (โอกาสสับสนจะสูงขึ้นตามอัตราคริติคอลปัจจุบันของผู้ใช้และจำนวนครั้งที่ใช้สกิลสุดยอด) หากไม่เกิดคริติคอล ความเสียหายคริติคอลของสกิลสุดยอดครั้งถัดไปจะเพิ่มเป็นสองเท่า',
		describe_in = 'Naga Kekerasan melompat ke udara lalu menyemburkan meriam air menyerang baris horizontal musuh, memberikan #C0xE69900#300% Serangan Fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#. Menghapus semua efek peningkatan dari target, meningkatkan 80% kerusakan kritis untuk serangan ini. Jika mengenai kritis, setelah menyerang, pengguna berpeluang memasuki keadaan kacau selama 1-2 giliran (peluang kacau meningkat seiring tingginya tingkat kritis pengguna dan frekuensi penggunaan skill ultim). Jika tidak mengenai kritis, kerusakan kritis skill ultim berikutnya akan berlipat ganda.',
		describe_ph = 'Ang Bayaning Dragon ay tumalon sa hangin at sumabog ng tubig upang atakihin ang pahalang na hanay ng mga kalaban, na nagdudulot ng #C0xE69900#300% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Tinatanggal ang lahat ng mga buff ng target, pinapataas ang kritikal na pinsala ng 80% para sa atake na ito. Kung ma-activate ang kritikal, maaaring mapunta ang sarili sa kalagayan ng kaguluhan ng 1-2 na turn (tumataas ang posibilidad ng kaguluhan habang tumataas ang kasalukuyang kritikal na rate ng sarili at dami ng paggamit ng ultimate skill); kung hindi ma-activate ang kritikal, ang kritikal na pinsala ng susunod na ultimate skill ay magiging doble.',
		describe_ma = 'Naga Keras melonjak ke udara kemudian menyemburkan meriam air menyerang barisan mendatar musuh, menyebabkan #C0xE69900#300% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Memadamkan semua kesan peningkatan daripada sasaran, meningkatkan 80% kerosakan kritikal untuk serangan ini, jika mengaktifkan kritikal, selepas serangan pengguna berkemungkinan mengalami keadaan keliru selama 1-2 pusingan (kadar keliru bertambah apabila kadar kritikal semasa pengguna semakin tinggi dan bilangan kali menggunakan kemahiran utama semakin banyak); jika tidak mengaktifkan kritikal, kerosakan kritikal kemahiran utama seterusnya akan meningkat dua kali ganda.',
		describe = 'Violent Dragon leaps into the air and sprays water cannons to attack a horizontal line of enemies, dealing #C0xE69900#300% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#. It removes all buffs from the targets, increases critical damage by 80% for this attack. If a critical hit is triggered, the user may enter a chaotic state for 1-2 turns (the chance of chaos increases with the user\'s current critical rate and the number of times the ultimate skill has been used). If no critical hit occurs, the critical damage of the next ultimate skill will be doubled.',
		simDesc_vn = 'Gyarados nhảy lên không trung rồi phun ra nước tấn công mục tiêu hàng ngang của đối phương, tăng mạnh sát thương chí mạng, giải tán hiệu ứng buff của mục tiêu, có khả năng gây hỗn loạn cho bản thân sau khi tấn công.',
		simDesc_en = 'Gyarados leaps into the air and sprays water to attack the enemy\'s entire horizontal row, greatly increasing critical damage, dispelling the target\'s buff effects, and has a chance to cause confusion to itself after the attack.',
		simDesc_th = 'กิยาราดอสกระโดดขึ้นกลางอากาศแล้วพ่นน้ำโจมตีเป้าหมายแถวแนวนอนของฝ่ายตรงข้าม เพิ่มความเสียหายคริติคอลอย่างมาก ล้างเอฟเฟกต์บัฟของเป้าหมาย และมีโอกาสทำให้ตัวเองสับสนหลังการโจมตี',
		simDesc_in = 'Gyarados melompat ke udara lalu menyemprotkan air untuk menyerang baris horizontal musuh, meningkatkan kerusakan kritis secara signifikan, menghilangkan efek buff target, dan memiliki kemungkinan menyebabkan kebingungan pada dirinya sendiri setelah menyerang.',
		simDesc_ph = 'Tumatalon ang Gyarados sa hangin at bumubuga ng tubig upang atakihin ang pahalang na hilera ng kalaban, malaki ang pagtaas ng critical damage, tinatanggal ang mga buff effect ng target, at may posibilidad na malito ang sarili pagkatapos ng pag-atake.',
		simDesc_ma = 'Gyarados melompat ke udara lalu memancut air untuk menyerang barisan mendatar musuh, meningkatkan kerosakan kritikal dengan ketara, menghapuskan kesan buff sasaran, dan berkemungkinan menyebabkan kekeliruan pada dirinya sendiri selepas menyerang.',
		simDesc = 'Gyarados leaps into the air and sprays water to attack the enemy\'s entire horizontal row, greatly increasing critical damage, dispelling the target\'s buff effects, and has a chance to cause confusion to itself after the attack.',
