	[6413] = {
		id = 6413,
		skillName_vn = 'Thủy triều u minh',
		skillName_en = 'Tide of the Underworld',
		skillName_th = 'กระแสน้ำแห่งยมโลก',
		skillName_in = 'Pasang Dunia Bawah',
		skillName_ph = 'Dagat ng Imbakan ng Kadiliman',
		skillName_ma = 'Arus Dunia Bawah',
		skillName = 'Tide of the Underworld',
		describe_vn = 'Rem kích hoạt Thủy Triều U Minh bao phủ toàn trường, tấn công toàn bộ mục tiêu kẻ địch gây #C0x3D8A99#200% Công Phép thuật#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, chuyển đổi 80% lượng [Ngưng Thủy] thành lá chắn nước bảo vệ bản thân, và có 70% khả năng đẩy mục tiêu chính ra khỏi chiến trường, anh hùng bị đẩy ra sẽ quay lại chiến trường sau khi kết thúc vòng lớn tiếp theo',
		describe_en = 'Rem activates the Tidal Abyss covering the entire battlefield, attacking all enemy targets and dealing #C0x3D8A99#200% Magic Power#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Magic Damage#C0x5B545B#. Converts 80% of [Water Suspension] into a water shield protecting herself, and has a 70% chance to push the main target out of the battlefield. Pushed heroes will return after the next major round ends.',
		describe_th = 'Rem เปิดใช้งานคลื่นน้ำลึกครอบคลุมทั้งสนามรบ โจมตีศัตรูทั้งหมดและสร้างความเสียหายเวทมนตร์ #C0x3D8A99#200% พลังเวทมนตร์#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# แปลง 80% ของ [การแข็งตัวของน้ำ] เป็นโล่ป้องกันน้ำปกป้องตัวเอง และมีโอกาส 70% ที่จะผลักเป้าหมายหลักออกจากสนามรบ ฮีโร่ที่ถูกผลักออกจะกลับเข้าสู่สนามรบหลังจากรอบหลักถัดไปสิ้นสุดลง',
		describe_in = 'Rem mengaktifkan Pasang Abyss menutupi seluruh medan pertempuran, menyerang semua target musuh dan memberikan #C0x3D8A99#200% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Kerusakan Sihir#C0x5B545B#. Mengubah 80% dari [Penangguhan Air] menjadi perisai air yang melindungi dirinya, dan memiliki peluang 70% untuk mendorong target utama keluar dari medan pertempuran. Pahlawan yang terdorong akan kembali setelah ronde besar berikutnya berakhir.',
		describe_ph = 'Ina-activate ni Rem ang Tidal Abyss na sumasakop sa buong larangan ng laban, inaatake ang lahat ng kalaban at nagdudulot ng #C0x3D8A99#200% Magic Power#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Magic Damage#C0x5B545B#. Kinokonvert ang 80% ng [Water Suspension] bilang water shield na nagpoprotekta sa sarili, at may 70% tsansang itulak ang pangunahing target palabas ng larangan. Ang mga naitulak na bayani ay babalik matapos ang susunod na malaking round matapos matapos.',
		describe_ma = 'Rem mengaktifkan Pasang Abyss yang meliputi seluruh medan perang, menyerang semua sasaran musuh dan memberikan #C0x3D8A99#200% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Kerosakan Sihir#C0x5B545B#. Menukar 80% dari [Penggantungan Air] menjadi perisai air yang melindungi dirinya sendiri, dan mempunyai peluang 70% untuk menolak sasaran utama keluar dari medan perang. Wira yang didorong akan kembali selepas pusingan besar seterusnya selesai.',
		describe = 'Rem activates the Tidal Abyss covering the entire battlefield, attacking all enemy targets and dealing #C0x3D8A99#200% Magic Power#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Magic Damage#C0x5B545B#. Converts 80% of [Water Suspension] into a water shield protecting herself, and has a 70% chance to push the main target out of the battlefield. Pushed heroes will return after the next major round ends.',
		simDesc_vn = 'Rem phát động lũ lụt tấn công toàn bộ mục tiêu của đối phương, nhận được một lá chắn và có khả năng đẩy mục tiêu chính ra khỏi chiến trường.',
		simDesc_en = 'Rem launches a flood attack on all enemy targets, gaining a shield and having the ability to push the main target out of the battlefield.',
		simDesc_th = 'เรมปล่อยน้ำท่วมโจมตีเป้าหมายของศัตรูทั้งหมด พร้อมได้รับโล่และสามารถดันเป้าหมายหลักให้ออกจากสนามรบได้',
		simDesc_in = 'Rem melancarkan serangan banjir ke seluruh target musuh, mendapatkan perisai dan memiliki kemampuan untuk mendorong target utama keluar dari medan perang.',
		simDesc_ph = 'Inilunsad ni Rem ang pagbaha na atake sa lahat ng mga target ng kalaban, nakakakuha ng isang kalasag at may kakayahang itulak ang pangunahing target palabas ng larangan ng digmaan.',
		simDesc_ma = 'Rem melancarkan serangan banjir ke semua sasaran musuh, mendapatkan perisai dan mempunyai keupayaan untuk menolak sasaran utama keluar dari medan perang.',
		simDesc = 'Rem launches a flood attack on all enemy targets, gaining a shield and having the ability to push the main target out of the battlefield.',
		starEffect = __data_t__starEffect[6413],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Thêm một lớp nước cho anh hùng đồng minh ở hàng sau có máu thấp nhất và giải trừ một hiệu ứng tiêu cực ngẫu nhiên trên bản thân và đồng minh đó.',
		starEffectDesc = 'Additional effect: Adds a layer of water to the ally hero in the back row with the lowest HP and removes a random negative effect from both themselves and that ally.',
		starEffectDesc_en = 'Additional effect: Adds a layer of water to the ally hero in the back row with the lowest HP and removes a random negative effect from both themselves and that ally.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เพิ่มชั้นน้ำให้กับฮีโร่ฝ่ายเดียวกันในแถวหลังที่มีพลังชีวิตต่ำที่สุด และลบเอฟเฟกต์ลบแบบสุ่มบนตัวเองและฮีโร่นั้น',
		starEffectDesc_in = 'Efek tambahan: Menambahkan lapisan air pada pahlawan sekutu di baris belakang dengan HP terendah dan menghilangkan efek negatif acak pada diri sendiri dan pahlawan tersebut.',
		starEffectDesc_ph = 'Karagdagang epekto: Nagdaragdag ng isang water layer sa alyadong bayani sa likurang hanay na may pinakamababang HP at nag-aalis ng isang random na negatibong epekto sa sarili at sa alyang iyon.',
		starEffectDesc_ma = 'Kesan tambahan: Menambah lapisan air kepada wira sekutu di barisan belakang dengan HP terendah dan menghilangkan kesan negatif rawak pada diri sendiri dan wira tersebut.',
		zawakeEffect = __data_t__zawakeEffect[6413],
		-- {79003}
		zawakeEffectDesc = 'Rem activates the underworld tide covering the entire field, attacking all enemy targets dealing 200% Magic Damage +$(skillLevel*4*75)$ magic damage, converting 80% of <water suspension> into a water shield protecting himself, and has an 80% chance to push the main target out of the battlefield. The pushed hero will return to the battlefield at the end of the next major turn.',
		zawakeEffectDesc_en = 'Rem activates the underworld tide covering the entire field, attacking all enemy targets dealing 200% Magic Damage +$(skillLevel*4*75)$ magic damage, converting 80% of <water suspension> into a water shield protecting himself, and has an 80% chance to push the main target out of the battlefield. The pushed hero will return to the battlefield at the end of the next major turn.',
		zawakeEffectDesc_th = 'Rem เปิดใช้งานน้ำขึ้นน้ำลงในยมโลกคลุมทั้งสนาม โจมตีเป้าหมายศัตรูทั้งหมดสร้างความเสียหายเวท 200% +$(skillLevel*4*75)$ และแปลง 80% ของ <น้ำแข็ง> เป็นโล่น้ำปกป้องตัวเอง รวมถึงมีโอกาส 80% ที่จะผลักเป้าหมายหลักให้ออกจากสนามรบ ฮีโร่ที่ถูกผลักจะกลับเข้าสนามรบในตอนท้ายของเทิร์นใหญ่ถัดไป',
		zawakeEffectDesc_in = 'Rem mengaktifkan pasang surut dunia bawah yang menutupi seluruh lapangan, menyerang semua target musuh menyebabkan 200% Damage Magic +$(skillLevel*4*75)$ damage magic, mengubah 80% dari <penangguhan air> menjadi perisai air yang melindungi diri sendiri, dan memiliki peluang 80% untuk mendorong target utama keluar dari medan perang, pahlawan yang terdorong akan kembali ke medan perang di akhir giliran besar berikutnya.',
		zawakeEffectDesc_ph = 'Pinapagana ni Rem ang underworld tide na bumabalot sa buong field, umaatake sa lahat ng kalabang target na nagdudulot ng 200% Magic Damage +$(skillLevel*4*75)$ magic damage, kinokonvert ang 80% ng <water suspension> bilang water shield na nagpoprotekta sa sarili, at may 80% chance na itulak ang pangunahing target palabas ng battlefield, ang itinulak na bayani ay babalik sa battlefield sa katapusan ng susunod na malaking turn.',
		zawakeEffectDesc_ma = 'Rem mengaktifkan pasang surut alam bawah tanah yang meliputi seluruh medan, menyerang semua sasaran musuh menyebabkan 200% Kerosakan Sihir +$(skillLevel*4*75)$ kerosakan sihir, menukar 80% daripada <penangguhan air> menjadi perisai air yang melindungi diri sendiri, dan mempunyai peluang 80% untuk menolak sasaran utama keluar daripada medan perang, wira yang ditolak akan kembali ke medan perang pada akhir giliran utama seterusnya.',
		zawakeEffectDesc_vn = 'Rem kích hoạt thủy triều âm phủ bao phủ toàn trường, tấn công toàn bộ mục tiêu đối phương gây 200% Công Phép +$(skillLevel*4*75)$ sát thương phép, chuyển hóa 80% lượng <ngưng nước> thành khiên nước bảo vệ bản thân, và có 80% xác suất đẩy mục tiêu chính ra khỏi chiến trường, anh hùng bị đẩy sẽ trở lại chiến trường vào cuối lượt lớn tiếp theo',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'And has 70% chance to push the main target out of the battlefield\n#F20# \n#F40##C0x5c9970#→And has 80% chance to push the main target out of the battlefield',
		zawakeSimpleDesc_en = 'And has 70% chance to push the main target out of the battlefield\n#F20# \n#F40##C0x5c9970#→And has 80% chance to push the main target out of the battlefield',
		zawakeSimpleDesc_th = 'และมีโอกาส 70% ที่จะผลักเป้าหมายหลักออกจากสนามรบ\n#F20# \n#F40##C0x5c9970#→และมีโอกาส 80% ที่จะผลักเป้าหมายหลักออกจากสนามรบ',
		zawakeSimpleDesc_in = 'Dan memiliki 70% peluang untuk mendorong target utama keluar dari medan perang\n#F20# \n#F40##C0x5c9970#→Dan memiliki 80% peluang untuk mendorong target utama keluar dari medan perang',
		zawakeSimpleDesc_ph = 'At may 70% tsansa na itulak ang pangunahing target palabas ng battlefield\n#F20# \n#F40##C0x5c9970#→At may 80% tsansa na itulak ang pangunahing target palabas ng battlefield',
		zawakeSimpleDesc_ma = 'Dan mempunyai 70% peluang untuk menolak sasaran utama keluar dari medan perang\n#F20# \n#F40##C0x5c9970#→Dan mempunyai 80% peluang untuk menolak sasaran utama keluar dari medan perang',
		zawakeSimpleDesc_vn = 'Và có 70% xác suất đẩy mục tiêu chính ra khỏi chiến trường\n#F20# \n#F40##C0x5c9970#→Và có 80% xác suất đẩy mục tiêu chính ra khỏi chiến trường',
