	[6416] = {
		id = 6416,
		skillName_vn = 'Di sản của quỷ tộc',
		skillName_en = 'Legacy of the Demon Tribe',
		skillName_th = 'มรดกของเผ่าปีศาจ',
		skillName_in = 'Warisan Suku Iblis',
		skillName_ph = 'Pamana ng Tribo ng Demonyo',
		skillName_ma = 'Warisan Puak Syaitan',
		skillName = 'Legacy of the Demon Tribe',
		describe_vn = 'Lượng máu mất mỗi lượt sẽ được lưu trữ dưới trạng thái [Ngưng Thủy], khi hành động vào lượt tiếp theo sẽ hồi phục #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# máu từ [Ngưng Thủy].\nRem dịu dàng khi tấn công có 50% khả năng không làm đối phương sinh ra nộ khí',
		describe_en = 'The amount of HP lost each turn will be stored under the [Frozen Water] state; when acting in the next turn, it will recover #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# HP from [Frozen Water]. \n Rem gently has a 50% chance to prevent the opponent from generating anger when attacking.',
		describe_th = 'ปริมาณเลือดที่สูญเสียในแต่ละเทิร์นจะถูกจัดเก็บภายใต้สถานะ [น้ำแข็ง] เมื่อทำการกระทำในเทิร์นถัดไปจะฟื้นฟู #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ของเลือดจาก [น้ำแข็ง]. \n Rem อย่างอ่อนโยนมีโอกาส 50% ที่จะไม่ทำให้ฝ่ายตรงข้ามเกิดความโกรธเมื่อโจมตี',
		describe_in = 'Jumlah darah yang hilang setiap giliran akan disimpan dalam status [Bekukan Air], saat bertindak pada giliran berikutnya akan memulihkan #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# darah dari [Bekukan Air]. \n Rem dengan lembut memiliki peluang 50% untuk mencegah lawan menghasilkan kemarahan saat menyerang.',
		describe_ph = 'Ang dami ng health na nawawala sa bawat turn ay matatagpuan sa estado ng [Frozen Water], kapag kumilos sa susunod na turn, magbabalik ito ng #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# health mula sa [Frozen Water]. \n Ang maamo ni Rem ay may 50% pagkakataon na hindi magpahintulot sa kalaban na magkaroon ng galit kapag umaatake.',
		describe_ma = 'Jumlah darah yang hilang setiap pusingan akan disimpan dalam keadaan [Air Beku], apabila bertindak pada pusingan seterusnya akan memulihkan #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# darah dari [Air Beku]. \n Rem dengan lembut memiliki kemungkinan 50% untuk menghalang lawan daripada menghasilkan amarah semasa menyerang.',
		describe = 'The amount of HP lost each turn will be stored under the [Frozen Water] state; when acting in the next turn, it will recover #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# HP from [Frozen Water]. \n Rem gently has a 50% chance to prevent the opponent from generating anger when attacking.',
		starEffect = __data_t__starEffect[6416],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi hiệu ứng <ngưng nước> kích hoạt, giải trừ một hiệu ứng kiểm soát hoặc tiêu cực ngẫu nhiên trên bản thân.',
		starEffectDesc = 'Additional effect: When the <ngưng nước> effect activates, it removes a random control or negative effect on yourself.',
		starEffectDesc_en = 'Additional effect: When the <ngưng nước> effect activates, it removes a random control or negative effect on yourself.',
