	[7013] = {
		id = 7013,
		skillName_vn = 'Cánh tự do',
		skillName_en = 'Freedom wings',
		skillName_th = 'ปีกแห่งเสรีภาพ',
		skillName_in = 'Sayap kebebasan',
		skillName_ph = 'Mga pakpak ng kalayaan',
		skillName_ma = 'Sayap kebebasan',
		skillName = 'Freedom wings',
		describe_vn = 'Levi dưới sự hỗ trợ của thiết bị cơ khí lập thể thực hiện điệu Waltz tử thần, gây #C0xE69900#720% Công Vật Lý#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# lên mục tiêu đơn của kẻ địch, đồng thời thêm hiệu ứng [Rách] trong 5 lượt (Rách: hiệu ứng tiêu cực, mục tiêu bị cấm hồi máu và khi tấn công sẽ chịu sát thương thực bằng 60% Công Vật Lý của Levi, tối đa cộng dồn 3 lần)',
		describe_en = 'Levi, supported by the three-dimensional mechanical device, performs the deadly Waltz, dealing #C0xE69900#720% Physical Attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B# to a single enemy target, and simultaneously applies the [Rend] effect for 5 turns (Rend: a debuff that forbids healing and causes the target to take true damage equal to 60% of Levi\'s Physical Attack when attacking, stacking up to 3 times).',
		describe_th = 'เลวี่ ภายใต้การสนับสนุนของอุปกรณ์กลไกสามมิติ ทำท่า Waltz แห่งความตาย สร้าง #C0xE69900#720% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# แก่เป้าหมายศัตรูเดียว พร้อมทั้งเพิ่มเอฟเฟกต์ [ฉีก] เป็นเวลา 5 เทิร์น (ฉีก: เอฟเฟกต์ลบ ซ่อนห้ามฟื้นฟู และเมื่อโจมตีจะได้รับความเสียหายจริงเท่ากับ 60% ของพลังโจมตีทางกายภาพของเลวี่ สะสมได้สูงสุด 3 ครั้ง)',
		describe_in = 'Levi, didukung oleh perangkat mekanis tiga dimensi, melakukan Tari Waltz maut, memberikan #C0xE69900#720% Serangan Fisik#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B# pada satu musuh, sekaligus menambahkan efek [Robek] selama 5 giliran (Robek: efek negatif, target dilarang sembuh dan saat menyerang akan menerima damage nyata sebesar 60% Serangan Fisik Levi, dapat menumpuk hingga 3 kali).',
		describe_ph = 'Si Levi, sa tulong ng mekanikal na three-dimensional na kagamitan, ay nagsasagawa ng nakamamatay na Waltz, na nagdudulot ng #C0xE69900#720% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B# sa isang kalaban, kasabay nitong inilalapat ang epekto na [Rips] sa loob ng 5 mga turn (Rips: isang negatibong epekto, ang target ay ipinagbabawal ang pagpapagaling at kapag umaatake ay tatanggap ng tunay na pinsala na katumbas ng 60% ng Pisikal na Atake ni Levi, maaaring magkarga hanggang 3 beses).',
		describe_ma = 'Levi, dengan sokongan peranti mekanikal tiga dimensi, melaksanakan Tari Waltz maut, memberikan #C0xE69900#720% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B# ke satu sasaran musuh, serta menambah kesan [Robek] selama 5 giliran (Robek: kesan negatif, sasaran dilarang pulih dan apabila menyerang akan menerima kerosakan sebenar bersamaan 60% Serangan Fizikal Levi, boleh bertimbun sehingga 3 kali).',
		describe = 'Levi, supported by the three-dimensional mechanical device, performs the deadly Waltz, dealing #C0xE69900#720% Physical Attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B# to a single enemy target, and simultaneously applies the [Rend] effect for 5 turns (Rend: a debuff that forbids healing and causes the target to take true damage equal to 60% of Levi\'s Physical Attack when attacking, stacking up to 3 times).',
		simDesc_vn = 'Kowal dưới sự hỗ trợ của thiết bị cơ giới, thực hiện "Vũ Điệu Tử Vong", gây sát thương cho mục tiêu đơn lẻ của đối phương và thêm hiệu ứng xé toạc.',
		simDesc_en = 'Kowal, with the support of mechanical equipment, performs the "Dance of Death," dealing damage to a single enemy target and applying a tear effect.',
		simDesc_th = 'โควาล ภายใต้การสนับสนุนของอุปกรณ์กลไก ดำเนินการ "ท่าเต้นแห่งความตาย" สร้างความเสียหายให้กับเป้าหมายเดี่ยวของศัตรูและเพิ่มเอฟเฟกต์ฉีกขาด',
		simDesc_in = 'Kowal, dengan dukungan peralatan mekanis, melakukan "Tarian Kematian", memberikan kerusakan pada satu target musuh dan menambahkan efek robek.',
		simDesc_ph = 'Si Kowal, sa tulong ng makinaryang kagamitan, ay nagsasagawa ng "Sayaw ng Kamatayan," na nagdudulot ng pinsala sa isang kalaban at naglalagay ng epekto ng punit.',
		simDesc_ma = 'Kowal, dengan sokongan peralatan mekanikal, melaksanakan "Tarian Kematian", memberikan kerosakan kepada satu sasaran musuh dan menambah efek koyak.',
		simDesc = 'Kowal, with the support of mechanical equipment, performs the "Dance of Death," dealing damage to a single enemy target and applying a tear effect.',
		starEffect = __data_t__starEffect[7013],
