		skillName_ph = 'Pindutin tulad ng Bundok Tai',
		skillName_ma = 'Tekan seperti Gunung Tai',
		skillName = 'Press down like Mount Tai',
		describe_vn = 'Snorlax nhỏ dùng cơ thể đè lên mục tiêu đơn lẻ của kẻ địch, gây #C0xE69900#150% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, dạ dày mạnh mẽ tiêu hóa hai hiệu ứng tiêu cực ngẫu nhiên của bản thân, mỗi lần tiêu hóa một hiệu ứng tiêu cực hồi phục 5% máu tối đa của bản thân',
		describe_en = 'Small Snorlax uses its body to press down on a single enemy target, dealing #C0xE69900#150% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Its strong stomach digests two random negative effects on itself; each digested negative effect restores 5% of its maximum HP.',
		describe_th = 'สเนอร์แล็กซ์ตัวเล็กใช้ร่างกายกดลงบนเป้าหมายศัตรูเดี่ยว สร้าง #C0xE69900#150% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# กระเพาะที่แข็งแกร่งจะย่อยเอฟเฟกต์ลบ 2 อย่างแบบสุ่มของตนเอง โดยแต่ละครั้งที่ย่อยเอฟเฟกต์ลบจะฟื้นฟูเลือดสูงสุดของตัวเอง 5%',
		describe_in = 'Snorlax kecil menggunakan tubuhnya untuk menekan satu target musuh, memberikan #C0xE69900#150% Serangan Fisik#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Perut yang kuat mencerna dua efek negatif acak pada dirinya sendiri, setiap efek negatif yang dicerna memulihkan 5% HP maksimal dirinya.',
		describe_ph = 'Ang maliit na Snorlax ay ginagamit ang katawan para pindutin ang isang kalabang target, nagdudulot ng #C0xE69900#150% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Pinsalang Pisikal#C0x5B545B#. Ang malakas na tiyan ay nilulunok ang dalawang random na negatibong epekto sa sarili, bawat nalunok na negatibong epekto ay nagpapagaling ng 5% ng sarili nitong maximum na HP.',
		describe_ma = 'Snorlax kecil menggunakan badannya untuk menekan satu sasaran musuh, memberikan #C0xE69900#150% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Perut yang kuat mencerna dua kesan negatif rawak pada dirinya sendiri, setiap kali mencerna satu kesan negatif memulihkan 5% HP maksimum dirinya.',
		describe = 'Small Snorlax uses its body to press down on a single enemy target, dealing #C0xE69900#150% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Its strong stomach digests two random negative effects on itself; each digested negative effect restores 5% of its maximum HP.',
		zawakeEffect = __data_t__zawakeEffect[7112],
		-- {79002}
		zawakeEffectDesc = 'The small Snorlax uses its body to press on a single enemy target, dealing #C0xE69900#150% Physical Attack #C0x5B545B#+$(skillLevel*4*36)$ Physical Damage #C0xF13B54# #C0x5B545B#. Its strong stomach digests two random negative effects and one control effect on itself, each time digesting a negative or control effect restores 5% of its maximum HP.',
		zawakeEffectDesc_en = 'The small Snorlax uses its body to press on a single enemy target, dealing #C0xE69900#150% Physical Attack #C0x5B545B#+$(skillLevel*4*36)$ Physical Damage #C0xF13B54# #C0x5B545B#. Its strong stomach digests two random negative effects and one control effect on itself, each time digesting a negative or control effect restores 5% of its maximum HP.',
		zawakeEffectDesc_th = 'สโนร์แล็กซ์ตัวเล็กใช้ร่างกายกดเป้าหมายศัตรูเดี่ยว ทำ #C0xE69900#150% พลังโจมตีทางกายภาพ #C0x5B545B#+$(skillLevel*4*36)$ ความเสียหายกายภาพ #C0xF13B54# #C0x5B545B#. กระเพาะแข็งแรงย่อยผลกระทบลบสองอย่างแบบสุ่มและเอฟเฟกต์ควบคุมหนึ่งอย่างของตัวเอง แต่ละครั้งที่ย่อยผลกระทบลบหรือควบคุม จะฟื้นฟูพลังชีวิตสูงสุดของตัวเอง 5%.',
		zawakeEffectDesc_in = 'Snorlax kecil menggunakan tubuhnya untuk menekan satu target musuh, menyebabkan #C0xE69900#150% Serangan Fisik #C0x5B545B#+$(skillLevel*4*36)$ Kerusakan Fisik #C0xF13B54# #C0x5B545B#. Perut yang kuat mencerna dua efek negatif acak dan satu efek kontrol pada dirinya sendiri, setiap kali mencerna efek negatif atau kontrol akan memulihkan 5% dari HP maksimalnya.',
		zawakeEffectDesc_ph = 'Ang maliit na Snorlax ay ginagamit ang katawan niya para idiin ang isang target na kalaban, nagdudulot ng #C0xE69900#150% Pisikal na Atake #C0x5B545B#+$(skillLevel*4*36)$ Pisikal na Pinsala #C0xF13B54# #C0x5B545B#. Ang matibay niyang tiyan ay nagtutunaw ng dalawang random na negatibong epekto at isang control effect ng sarili, bawat pagkakataong matunaw ang negatibo o control effect ay nagpapagaling ng 5% ng kanyang maximum na HP.',
		zawakeEffectDesc_ma = 'Snorlax kecil menggunakan badannya untuk menekan satu sasaran musuh, menyebabkan #C0xE69900#150% Serangan Fizikal #C0x5B545B#+$(skillLevel*4*36)$ Kerosakan Fizikal #C0xF13B54# #C0x5B545B#. Perut yang kuat mencerna dua kesan negatif rawak dan satu kesan kawalan pada dirinya sendiri, setiap kali mencerna kesan negatif atau kawalan akan memulihkan 5% daripada HP maksumnya.',
		zawakeEffectDesc_vn = 'Snorlax nhỏ dùng thân mình đè lên mục tiêu đơn lẻ của kẻ địch, gây ra #C0xE69900#150% Công Vật Lý #C0x5B545B#+$(skillLevel*4*36)$ Sát Thương Vật Lý #C0xF13B54# #C0x5B545B#, dạ dày mạnh mẽ tiêu hóa hai hiệu ứng tiêu cực ngẫu nhiên và một hiệu ứng kiểm soát của bản thân, mỗi lần tiêu hóa một hiệu ứng tiêu cực hoặc kiểm soát hồi phục 5% lượng máu tối đa của bản thân',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Strong stomach removes 2 random negative effects on self, each removal restores 5% of self max HP\n#F20# \n#F40##C0x5c9970#→Strong stomach removes 2 random negative effects and 1 control effect on self, each removal restores 5% of self max HP',
		zawakeSimpleDesc_en = 'Strong stomach removes 2 random negative effects on self, each removal restores 5% of self max HP\n#F20# \n#F40##C0x5c9970#→Strong stomach removes 2 random negative effects and 1 control effect on self, each removal restores 5% of self max HP',
		zawakeSimpleDesc_th = 'กระเพาะแข็งแรงลบเอฟเฟกต์ลบแบบสุ่ม 2 อันจากตัวเอง ทุกครั้งที่ลบฟื้นฟู 5% ของ HP สูงสุดของตัวเอง\n#F20# \n#F40##C0x5c9970#→กระเพาะแข็งแรงลบเอฟเฟกต์ลบแบบสุ่ม 2 อันและ 1 เอฟเฟกต์ควบคุมจากตัวเอง ทุกครั้งที่ลบฟื้นฟู 5% ของ HP สูงสุดของตัวเอง',
		zawakeSimpleDesc_in = 'Perut kuat menghapus 2 efek negatif acak dari diri sendiri, setiap penghapusan memulihkan 5% HP maksimum diri\n#F20# \n#F40##C0x5c9970#→Perut kuat menghapus 2 efek negatif acak dan 1 efek kontrol dari diri sendiri, setiap penghapusan memulihkan 5% HP maksimum diri',
		zawakeSimpleDesc_ph = 'Malakas ang tiyan na nag-aalis ng 2 random na negatibong epekto sa sarili, bawat tanggal ay nagpapagaling ng 5% ng maximum HP\n#F20# \n#F40##C0x5c9970#→Malakas ang tiyan na nag-aalis ng 2 random na negatibong epekto at 1 control effect sa sarili, bawat tanggal ay nagpapagaling ng 5% ng maximum HP',
		zawakeSimpleDesc_ma = 'Perut kuat menghapus 2 kesan negatif rawak pada diri, setiap penghapusan memulihkan 5% HP maksimum\n#F20# \n#F40##C0x5c9970#→Perut kuat menghapus 2 kesan negatif rawak dan 1 kesan kawalan pada diri, setiap penghapusan memulihkan 5% HP maksimum',
		zawakeSimpleDesc_vn = 'Dạ dày mạnh mẽ loại bỏ 2 hiệu ứng tiêu cực ngẫu nhiên trên bản thân, mỗi lần loại bỏ hồi phục 5% máu tối đa của bản thân\n#F20# \n#F40##C0x5c9970#→Dạ dày mạnh mẽ loại bỏ 2 hiệu ứng tiêu cực ngẫu nhiên và 1 hiệu ứng khống chế trên bản thân, mỗi lần loại bỏ hồi phục 5% máu tối đa của bản thân',
