	[7113] = {
		id = 7113,
		skillName_vn = 'Ngáy như sấm',
		skillName_en = 'Snoring like thunder',
		skillName_th = 'กรนเหมือนฟ้าร้อง',
		skillName_in = 'Berdengung seperti guntur',
		skillName_ph = 'Nangangat ng parang kulog',
		skillName_ma = 'Bersin seperti guruh',
		skillName = 'Snoring like thunder',
		describe_vn = 'Snorlax nhỏ ăn trái cây rồi ngủ, phát ra tiếng ngáy lớn tấn công toàn bộ mục tiêu kẻ địch, gây #C0xE69900#180% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, và có 15% xác suất làm choáng mỗi kẻ địch 1 lượt, số lượng càng ít xác suất làm choáng càng cao. Sau khi kết thúc kỹ năng đặc biệt, bản thân vào trạng thái [tự ngủ] 1 lượt',
		describe_en = 'Small Snorlax eats fruit and then sleeps, emitting a loud snore that attacks all enemy targets, dealing #C0xE69900#180% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#, with a 15% chance to stun each enemy for 1 turn. The fewer the enemies, the higher the stun chance. After the special skill ends, Snorlax enters a [self-sleep] state for 1 turn.',
		describe_th = 'Snorlax ตัวเล็กกินผลไม้แล้วนอนหลับ พร้อมส่งเสียงกรนดังโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหาย #C0xE69900#180% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# และมีโอกาส 15% ที่จะทำให้ศัตรูทุกตัวติดสตันเป็นเวลา 1 เทิร์น ยิ่งจำนวนศัตรูน้อย โอกาสติดสตันจะยิ่งสูงขึ้น หลังจากสิ้นสุดทักษะพิเศษ Snorlax จะเข้าสู่สถานะ [หลับเอง] เป็นเวลา 1 เทิร์น',
		describe_in = 'Snorlax kecil makan buah lalu tidur, mengeluarkan dengkuran keras yang menyerang semua target musuh, menyebabkan #C0xE69900#180% Serangan Fisik#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, dengan peluang 15% untuk membuat setiap musuh stun selama 1 giliran. Semakin sedikit jumlah musuh, semakin tinggi peluang stun. Setelah skill spesial selesai, dirinya memasuki status [tidur sendiri] selama 1 giliran.',
		describe_ph = 'Munting Snorlax kumakain ng prutas at natutulog, naglalabas ng malakas na hilik na umaatake sa lahat ng kaaway, nagdudulot ng #C0xE69900#180% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#, at may 15% tsansa na ma-stun ang bawat kaaway ng 1 turn. Kapag mas kakaunti ang mga kaaway, mas mataas ang tsansa ng stun. Pagkatapos ng special skill, papasok siya sa estado ng [self-sleep] ng 1 turn.',
		describe_ma = 'Snorlax kecil makan buah kemudian tidur, mengeluarkan dengkuran kuat yang menyerang semua sasaran musuh, menyebabkan #C0xE69900#180% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, dengan 15% peluang untuk menyebabkan setiap musuh kelumpuhan selama 1 pusingan. Semakin kurang musuh, semakin tinggi peluang kelumpuhan. Selepas kemahiran khas tamat, Snorlax memasuki keadaan [tidur sendiri] selama 1 pusingan.',
		describe = 'Small Snorlax eats fruit and then sleeps, emitting a loud snore that attacks all enemy targets, dealing #C0xE69900#180% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#, with a 15% chance to stun each enemy for 1 turn. The fewer the enemies, the higher the stun chance. After the special skill ends, Snorlax enters a [self-sleep] state for 1 turn.',
		simDesc_vn = 'Snorlax ăn hết trái cây rồi ngủ, phát ra tiếng ngáy lớn tấn công toàn bộ mục tiêu của đối phương, có khả năng làm choáng mục tiêu, tỷ lệ làm choáng càng cao khi số lượng mục tiêu càng ít, sau khi kết thúc tuyệt chiêu, bản thân sẽ rơi vào trạng thái [Ngủ Tự Động].',
		simDesc_en = 'Snorlax eats all the fruit and then sleeps, emitting a loud snore that attacks all enemy targets. It has the ability to stun targets, with a higher stun rate when there are fewer targets. After finishing the ultimate move, it will enter the <Automatic Sleep> state.',
		simDesc_th = 'Snorlax กินผลไม้ทั้งหมดแล้วนอนหลับ พร้อมส่งเสียงกรนดังโจมตีเป้าหมายฝ่ายตรงข้ามทั้งหมด มีโอกาสทำให้เป้าหมายมึนงง อัตราการมึนงงจะสูงขึ้นเมื่อจำนวนเป้าหมายน้อยลง หลังจากจบท่าไม้ตาย จะเข้าสู่สถานะ [นอนหลับอัตโนมัติ].',
		simDesc_in = 'Snorlax memakan semua buah kemudian tidur, mengeluarkan dengkuran keras yang menyerang semua target musuh. Memiliki kemampuan untuk membuat target terpukau, dengan tingkat terpukau yang lebih tinggi saat jumlah target lebih sedikit. Setelah menyelesaikan jurus pamungkas, Snorlax akan memasuki keadaan <Tidur Otomatis>.',
		simDesc_ph = 'Kinain ni Snorlax ang lahat ng prutas tapos natulog, naglabas ng malakas na hilik na umatake sa lahat ng kalabang target. May kakayahang pahupain ang target, mas mataas ang tsansa ng pahupa kapag mas kakaunti ang mga target. Pagkatapos matapos ang ultimate, papasok ito sa estado ng <Awtomatikong Tulog>.',
		simDesc_ma = 'Snorlax makan semua buah kemudian tidur, mengeluarkan dengupan kuat yang menyerang semua sasaran musuh. Mempunyai kemampuan untuk membuat sasaran terkejut, dengan kadar kejutan yang lebih tinggi apabila jumlah sasaran lebih sedikit. Selepas melengkapkan serangan hebat, ia akan memasuki keadaan <Tidur Automatik>.',
		simDesc = 'Snorlax eats all the fruit and then sleeps, emitting a loud snore that attacks all enemy targets. It has the ability to stun targets, with a higher stun rate when there are fewer targets. After finishing the ultimate move, it will enter the [Automatic Sleep] state.',
		starEffect = __data_t__starEffect[7113],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Bản thân sẽ nhận 20% dễ bị tổn thương trong 1 lượt, đồng thời tăng 10% giới hạn máu tối đa và 10% hiệu ứng phản đòn trong 2 lượt.',
		starEffectDesc = 'Additional Effect: The user will receive 20% increased vulnerability for 1 turn, while also increasing the maximum HP limit by 10% and counterattack effect by 10% for 2 turns.',
		starEffectDesc_en = 'Additional Effect: The user will receive 20% increased vulnerability for 1 turn, while also increasing the maximum HP limit by 10% and counterattack effect by 10% for 2 turns.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ผู้ใช้จะได้รับความเปราะบางเพิ่มขึ้น 20% เป็นเวลา 1 เทิร์น และเพิ่มขีดจำกัดพลังชีวิตสูงสุด 10% และเอฟเฟกต์การตอบโต้ 10% เป็นเวลา 2 เทิร์น',
		starEffectDesc_in = 'Efek Tambahan: Pengguna akan menerima 20% kerentanan selama 1 giliran, sekaligus meningkatkan batas maksimum HP sebesar 10% dan efek serangan balik sebesar 10% selama 2 giliran.',
		starEffectDesc_ph = 'Karagdagang Epekto: Tatanggapin ng gumagamit ang 20% na mas madaling masaktan sa loob ng 1 turn, kasabay ng pagtaas ng 10% ng maximum HP limit at 10% na epekto ng counterattack sa loob ng 2 turn.',
		starEffectDesc_ma = 'Kesan Tambahan: Pengguna akan menerima 20% kerentanan selama 1 giliran, sambil meningkatkan had maksima HP sebanyak 10% dan kesan serangan balas sebanyak 10% selama 2 giliran.',
		zawakeEffect = __data_t__zawakeEffect[7113],
		-- {79003}
		zawakeEffectDesc = 'Little Snorlax eats fruit then sleeps, emits a loud snore attacking all enemy targets, dealing #C0xE69900#180% Physical Attack #C0x5B545B#+$(skillLevel*4*36)$ Physical Damage #C0xF13B54# #C0x5B545B#, and has a 20% chance to stun each enemy for 1 turn, fewer enemies means higher stun chance. After the ultimate ends, the user enters <self sleep> state for 1 turn',
		zawakeEffectDesc_en = 'Little Snorlax eats fruit then sleeps, emits a loud snore attacking all enemy targets, dealing #C0xE69900#180% Physical Attack #C0x5B545B#+$(skillLevel*4*36)$ Physical Damage #C0xF13B54# #C0x5B545B#, and has a 20% chance to stun each enemy for 1 turn, fewer enemies means higher stun chance. After the ultimate ends, the user enters <self sleep> state for 1 turn',
		zawakeEffectDesc_th = 'สโนร์แล็กซ์ตัวเล็กกินผลไม้แล้วนอนหลับ ส่งเสียงกรนดังโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายทางกายภาพ #C0xE69900#180% #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# #C0x5B545B# และมีโอกาส 20% ที่จะทำให้ศัตรูแต่ละตัวติดสตั๊น 1 เทิร์น ยิ่งศัตรูน้อยโอกาสติดสตั๊นจะยิ่งสูง หลังจากจบท่าไม้ตาย ตัวละครจะเข้าสู่สถานะ <tự ngủ> 1 เทิร์น',
		zawakeEffectDesc_in = 'Snorlax kecil makan buah lalu tidur, mengeluarkan dengkuran keras menyerang semua target musuh, memberikan #C0xE69900#180% Serangan Fisik #C0x5B545B#+$(skillLevel*4*36)$ Kerusakan Fisik #C0xF13B54# #C0x5B545B#, dan memiliki peluang 20% untuk membuat setiap musuh stun selama 1 giliran, jumlah musuh yang lebih sedikit meningkatkan peluang stun. Setelah skill ulti berakhir, pengguna memasuki status <tự ngủ> selama 1 giliran',
		zawakeEffectDesc_ph = 'Munting Snorlax kumakain ng prutas tapos matutulog, nagpapalabas ng malakas na hilik na umaatake sa lahat ng kalabang target, nagdudulot ng #C0xE69900#180% Physical Attack #C0x5B545B#+$(skillLevel*4*36)$ Physical Damage #C0xF13B54# #C0x5B545B#, at may 20% tsansa na ma-stun bawat kalaban ng 1 turn, mas kakaunti ang kalaban mas mataas ang tsansa ng stun. Pagkatapos ng ultimate, ang sarili ay papasok sa estado na <tự ngủ> ng 1 turn',
		zawakeEffectDesc_ma = 'Snorlax kecil makan buah kemudian tidur, mengeluarkan dengkuran kuat menyerang semua sasaran musuh, menyebabkan #C0xE69900#180% Serangan Fizikal #C0x5B545B#+$(skillLevel*4*36)$ Kerosakan Fizikal #C0xF13B54# #C0x5B545B#, dan mempunyai 20% peluang untuk membuat setiap musuh terkena stun selama 1 pusingan, semakin sedikit jumlah musuh semakin tinggi peluang stun. Selepas tamat serangan hebat, pengguna memasuki keadaan <tự ngủ> selama 1 pusingan',
		zawakeEffectDesc_vn = 'Snorlax nhỏ ăn trái cây xong ngủ, phát ra tiếng ngáy lớn tấn công toàn bộ mục tiêu kẻ địch, gây ra #C0xE69900#180% Công Vật Lý #C0x5B545B#+$(skillLevel*4*36)$ Sát Thương Vật Lý #C0xF13B54# #C0x5B545B#, và có 20% xác suất làm choáng mỗi kẻ địch 1 lượt, số lượng càng ít xác suất làm choáng càng cao. Sau khi kết thúc tuyệt chiêu, bản thân vào trạng thái <tự ngủ> 1 lượt',
