	[7123] = {
		id = 7123,
		skillName_vn = 'Chém hủy diệt',
		skillName_en = 'Destructive Slash',
		skillName_th = 'ฟันทำลายล้าง',
		skillName_in = 'Serangan Mematikan',
		skillName_ph = 'Mapaminsalang Hiwalay',
		skillName_ma = 'Belantan Pemusnah',
		skillName = 'Destructive Slash',
		describe_vn = 'Nier mở toàn bộ hỏa lực, thực hiện cú chém phá hủy tối thượng tấn công toàn bộ mục tiêu kẻ địch, gây #C0xE69900#250% Công Vật Lý#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, và có 15% xác suất làm choáng mỗi kẻ địch 1 lượt, số lượng càng ít xác suất làm choáng càng cao. Sau khi kết thúc kỹ năng đặc biệt, bản thân vào trạng thái [nghỉ ngơi] 1 lượt',
		describe_en = 'Nier unleashes full firepower, performing the ultimate destructive slash to attack all enemy targets, dealing #C0xE69900#250% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#, with a 15% chance to stun each enemy for 1 turn. The fewer the enemies, the higher the stun chance. After the special skill ends, Nier enters a [rest] state for 1 turn.',
		describe_th = 'เนียร์ปลดปล่อยพลังทั้งหมด ทำการฟันทำลายขั้นสุดยอดโจมตีเป้าหมายศัตรูทั้งหมด สร้าง #C0xE69900#250% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# โดยมีโอกาส 15% ที่จะทำให้ศัตรูแต่ละตัวติดสถานะมึนงงเป็นเวลา 1 เทิร์น จำนวนศัตรูน้อย โอกาสมึนงงยิ่งสูง หลังการใช้สกิลพิเศษ ตัวละครจะเข้าสู่สถานะ [พักผ่อน] เป็นเวลา 1 เทิร์น',
		describe_in = 'Nier mengerahkan semua kekuatan api, melakukan tebasan destruktif tertinggi untuk menyerang semua target musuh, memberikan #C0xE69900#250% Serangan Fisik#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, dengan peluang 15% untuk membuat setiap musuh ter-stun selama 1 giliran. Semakin sedikit musuh, semakin tinggi peluang stun. Setelah skill khusus selesai, Nier memasuki keadaan [istirahat] selama 1 giliran.',
		describe_ph = 'Ibinubuga ni Nier ang lahat ng apoy, isinasagawa ang pinakamataas na pambagsak na hiwa upang atakihin ang lahat ng kalaban, nagdudulot ng #C0xE69900#250% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#, at may 15% tsansa na ma-stun ang bawat kalaban ng 1 turn. Kapag mas kaunti ang kalaban, mas mataas ang tsansa ng stun. Pagkatapos matapos ang espesyal na kakayahan, papasok si Nier sa estado ng [pahinga] ng 1 turn.',
		describe_ma = 'Nier melancarkan keseluruhan kuasa tembakan, melaksanakan tebasan pemusnah utama menyerang semua sasaran musuh, menyebabkan #C0xE69900#250% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Keradangan Fizikal#C0x5B545B#, dan mempunyai peluang 15% untuk membuat setiap musuh terkena keadaan terkejut selama 1 pusingan. Jumlah musuh semakin sedikit, peluang terkejut semakin tinggi. Selepas kemahiran khas tamat, dirinya akan memasuki keadaan [berehat] selama 1 pusingan.',
		describe = 'Nier unleashes full firepower, performing the ultimate destructive slash to attack all enemy targets, dealing #C0xE69900#250% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#, with a 15% chance to stun each enemy for 1 turn. The fewer the enemies, the higher the stun chance. After the special skill ends, Nier enters a [rest] state for 1 turn.',
		simDesc_vn = 'Neil phóng sức mạnh tối đa, thực hiện "Đòn Chém Phá Hủy Tối Thượng" tấn công toàn bộ mục tiêu của đối phương gây sát thương lớn, có khả năng làm choáng mục tiêu, tỷ lệ làm choáng càng cao khi số lượng mục tiêu càng ít, sau khi kết thúc tuyệt chiêu, bản thân sẽ rơi vào trạng thái [Ngủ Tự Động].',
		simDesc_en = 'Neil unleashes his maximum power, executing the "Ultimate Destruction Slash" to strike all enemy targets dealing massive damage with a chance to stun. The stun chance increases the fewer the targets hit. After finishing the ultimate move, he enters an <Auto Sleep> state.',
		simDesc_th = 'นีลปลดปล่อยพลังสูงสุด ใช้ "ท่า斬ทำลายล้างสูงสุด" โจมตีศัตรูทั้งหมดก่อให้เกิดความเสียหายรุนแรง มีโอกาสทำให้เป้าหมายมึนงง โอกาสมึนงงจะสูงขึ้นเมื่อจำนวนเป้าหมายน้อยลง หลังจากทำท่ายอดเยี่ยมเสร็จ จะเข้าสู่สถานะ [หลับอัตโนมัติ]',
		simDesc_in = 'Neil melepaskan kekuatan maksimalnya, melaksanakan "Serangan Tebasan Penghancur Ultimate" yang menyerang semua target musuh dengan memberikan kerusakan besar, memiliki kemungkinan untuk membuat target terkena stun, peluang stun akan semakin tinggi jika jumlah target lebih sedikit, setelah menyelesaikan jurus, dirinya akan memasuki keadaan <Tidur Otomatis>.',
		simDesc_ph = 'Pinakawalan ni Neil ang kanyang pinakamalakas na lakas, isinasagawa ang "Ultimate Destruction Slash" na umatake sa lahat ng kalabang target na nagdudulot ng malaking pinsala, may kakayahang maka-stun ng target. Tumataas ang tsansa ng stun kapag mas kaunti ang mga target. Pagkatapos matapos ang ultimate move, siya ay mapapasok sa estado ng <Auto Sleep>.',
		simDesc_ma = 'Neil melancarkan kuasa maksima, melaksanakan "Serangan Tebasan Pemusnah Ultimate" yang menyerang semua sasaran musuh menyebabkan kerosakan besar, berkemungkinan untuk membuat sasaran terkena stun, kadar stun meningkat apabila jumlah sasaran berkurangan, selepas tamat serangan istimewa, dia akan memasuki keadaan <Tidur Automatik>.',
		simDesc = 'Neil unleashes his maximum power, executing the "Ultimate Destruction Slash" to strike all enemy targets dealing massive damage with a chance to stun. The stun chance increases the fewer the targets hit. After finishing the ultimate move, he enters an [Auto Sleep] state.',
		starEffect = __data_t__starEffect[7123],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Bản thân sẽ nhận 20% dễ bị tổn thương trong 1 lượt, đồng thời tăng 10% giới hạn máu tối đa và 10% hiệu ứng phản đòn trong 2 lượt.',
		starEffectDesc = 'Additional effect: The user will receive 20% increased vulnerability for 1 turn, while also increasing max HP limit by 10% and counterattack effect by 10% for 2 turns.',
		starEffectDesc_en = 'Additional effect: The user will receive 20% increased vulnerability for 1 turn, while also increasing max HP limit by 10% and counterattack effect by 10% for 2 turns.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ตัวละครจะได้รับช่องโหว่เพิ่มขึ้น 20% เป็นเวลา 1 เทิร์น พร้อมเพิ่มขีดจำกัด HP สูงสุด 10% และเอฟเฟกต์ตอบโต้ 10% เป็นเวลา 2 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Pengguna akan menerima kerentanan 20% selama 1 giliran, sekaligus meningkatkan batas HP maksimal sebesar 10% dan efek serangan balik sebesar 10% selama 2 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Tatanggap ang sarili ng 20% na pagiging madaling masaktan sa loob ng 1 turn, kasabay ng pagtaas ng 10% ng maximum na limitasyon ng HP at 10% na epekto ng counterattack sa loob ng 2 turns.',
		starEffectDesc_ma = 'Kesan tambahan: Diri sendiri akan menerima 20% kerentanan selama 1 giliran, sambil meningkatkan had maksimum HP sebanyak 10% dan kesan serangan balas sebanyak 10% selama 2 giliran.',
		zawakeEffect = __data_t__zawakeEffect[7123],
