	[7212] = {
		id = 7212,
		skillName_vn = 'Trận tên khắc ấn',
		skillName_en = 'Seal Engraving Battle',
		skillName_th = 'สงครามสลักตราประทับ',
		skillName_in = 'Pertarungan Ukiran Segel',
		skillName_ph = 'Laban ng Gawa ng Selyo',
		skillName_ma = 'Pertempuran Ukiran Cap',
		skillName = 'Seal Engraving Battle',
		describe_vn = 'Rin Tosaka thi triển một viên ngọc, triệu hồi một dãy mũi tên khắc tấn công mục tiêu địch theo hàng, gây #C0x3D8A99#150% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# sát thương phép #C0x5B545B#, 40% cơ hội [đóng băng] mục tiêu trong 2 lượt (đóng băng: hiệu ứng điều khiển, không thể di chuyển, sẽ được nâng lên sau khi nhận được mạng sống tích lũy vượt quá 30% mục tiêu)',
		describe_en = 'Rin Tosaka casts a gem, summoning a row of engraved arrows that attack enemy targets in a line, dealing 150% Magic Damage + $(skillLevel*4*48)$ magic damage, with a 40% chance to [freeze] the target for 2 turns (freeze: control effect, unable to move, will be enhanced after receiving accumulated healing exceeding 30% of the target).',
		describe_th = 'Rin Tosaka ปล่อยอัญมณี เรียกลูกศรที่สลักลงไปโจมตีเป้าหมายศัตรูเป็นแถวยาว สร้างความเสียหายเวทมนตร์ 150% + $(skillLevel*4*48)$ ความเสียหายเวทมนตร์ มีโอกาส 40% ที่จะ [แช่แข็ง] เป้าหมายเป็นเวลา 2 เทิร์น (แช่แข็ง: เอฟเฟกต์ควบคุม ไม่สามารถเคลื่อนที่ได้ จะถูกเพิ่มพลังหลังจากได้รับการฟื้นฟูชีวิตสะสมเกินกว่า 30% ของเป้าหมาย)',
		describe_in = 'Rin Tosaka mengeluarkan permata, memanggil deretan panah berukir yang menyerang target musuh secara baris, memberikan 150% Kerusakan Sihir + $(skillLevel*4*48)$ kerusakan sihir, dengan peluang 40% untuk [membekukan] target selama 2 giliran (membekukan: efek kontrol, tidak bisa bergerak, akan meningkat setelah menerima penyembuhan kumulatif melebihi 30% target).',
		describe_ph = 'Si Rin Tosaka ay naglabas ng isang hiyas, nagtawag ng isang hanay ng mga inukit na palaso na umaatake sa mga kalaban nang sunud-sunod, nagdudulot ng 150% Magic Damage + $(skillLevel*4*48)$ magic damage, may 40% na tsansa na [i-freeze] ang target sa loob ng 2 na turn (freeze: effect ng kontrol, hindi makagalaw, lalakas ito kapag nakatanggap ng cumulative healing na mahigit sa 30% ng target).',
		describe_ma = 'Rin Tosaka melontarkan permata, memanggil barisan anak panah yang diukir menyerang sasaran musuh secara baris, memberikan 150% Kerosakan Sihir + $(skillLevel*4*48)$ kerosakan sihir, dengan peluang 40% untuk [membekukan] sasaran selama 2 pusingan (membekukan: kesan kawalan, tidak dapat bergerak, akan dipertingkat selepas menerima pemulihan terkumpul melebihi 30% sasaran).',
		describe = 'Rin Tosaka casts a gem, summoning a row of engraved arrows that attack enemy targets in a line, dealing 150% Magic Damage + $(skillLevel*4*48)$ magic damage, with a 40% chance to [freeze] the target for 2 turns (freeze: control effect, unable to move, will be enhanced after receiving accumulated healing exceeding 30% of the target).',
		simDesc_vn = 'Rin Tosaka thi triển một câu thần chú bằng đá quý, triệu hồi một loạt mũi tên được khắc để tấn công mục tiêu của kẻ thù theo hàng.',
		simDesc_en = 'Rin Tosaka casts a gemstone spell, summoning a series of engraved arrows to attack the enemy\'s target in a row.',
		simDesc_th = 'Rin Tosaka ร่ายเวทอัญมณี เรียกธนูที่สลักขึ้นมาเพื่อโจมตีเป้าหมายของศัตรูเป็นแถว',
		simDesc_in = 'Rin Tosaka mengucapkan mantra batu permata, memanggil serangkaian panah yang terukir untuk menyerang target musuh secara berderet.',
		simDesc_ph = 'Si Rin Tosaka ay nagbitiw ng isang gemstone na pangkulam, na nagmumungkahi ng serye ng mga may ukit na pana upang atakihin ang target ng kalaban nang sunud-sunod.',
		simDesc_ma = 'Rin Tosaka melafazkan mantera batu permata, memanggil satu siri anak panah yang diukir untuk menyerang sasaran musuh secara berbaris.',
		simDesc = 'Rin Tosaka casts a gemstone spell, summoning a series of engraved arrows to attack the enemy\'s target in a row.',
		zawakeEffect = __data_t__zawakeEffect[7212],
		-- {79002}
		zawakeEffectDesc = 'Rin Tosaka casts a spell, summoning a series of engraved arrows to attack enemy targets in a row, dealing #C0x3D8A99#150% Spell Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Spell Damage#C0x5B545B#, 50% chance to <Freeze> targets for 2 turns (Freeze: control effect, unable to move, released after receiving more than 30% of target\'s HP), first time releases 100% freeze on units behind in enemy row',
		zawakeEffectDesc_en = 'Rin Tosaka casts a spell, summoning a series of engraved arrows to attack enemy targets in a row, dealing #C0x3D8A99#150% Spell Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Spell Damage#C0x5B545B#, 50% chance to <Freeze> targets for 2 turns (Freeze: control effect, unable to move, released after receiving more than 30% of target\'s HP), first time releases 100% freeze on units behind in enemy row',
		zawakeEffectDesc_th = 'Rin Tosaka ปล่อยคาถา, เรียกธนูกลุ่มหนึ่งที่สลักไว้โจมตีเป้าหมายศัตรูเป็นแถว, ทำ #C0x3D8A99#150% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B#, โอกาส 50% <แช่แข็ง> เป้าหมายเป็นเวลา 2 เทิร์น (แช่แข็ง: เอฟเฟกต์ควบคุม, ไม่สามารถเคลื่อนที่ได้, ปล่อยเมื่อรับความเสียหายเกิน 30% ของพลังชีวิตเป้าหมาย), ครั้งแรกปล่อยแช่แข็ง 100% กับยูนิตแถวหลังในแถวศัตรู',
		zawakeEffectDesc_in = 'Rin Tosaka mengeluarkan mantra, memanggil serangkaian panah berukir untuk menyerang target musuh dalam barisan, menyebabkan #C0x3D8A99#150% Damage Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Damage Sihir#C0x5B545B#, peluang 50% <Bekukan> target selama 2 giliran (Bekukan: efek kontrol, tidak dapat bergerak, dilepaskan setelah menerima lebih dari 30% HP target), pertama kali melepaskan pembekuan 100% pada unit di belakang dalam barisan musuh',
		zawakeEffectDesc_ph = 'Si Rin Tosaka ay nagpalabas ng isang sumpa, nag-summon ng serye ng mga inukit na mga palaso upang atakihin ang mga kalaban sa isang hilera, nagdudulot ng #C0x3D8A99#150% Spell Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Spell Damage#C0x5B545B#, 50% pagkakataon upang <Freeze> ang mga target sa loob ng 2 turn (Freeze: epekto ng control, hindi makagalaw, maaalis kapag nakatanggap ng higit sa 30% ng HP ng target), unang beses na nagpapalaya ng 100% freeze sa mga unit na nasa likod sa hilera ng kalaban',
		zawakeEffectDesc_ma = 'Rin Tosaka meletakkan sihir, memanggil satu siri anak panah berukir untuk menyerang sasaran musuh dalam barisan, menyebabkan #C0x3D8A99#150% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Kerosakan Sihir#C0x5B545B#, 50% peluang untuk <Bekukan> sasaran selama 2 pusingan (Bekukan: kesan kawalan, tidak boleh bergerak, dilepaskan selepas menerima lebih dari 30% HP sasaran), kali pertama melepaskan pembekuan 100% ke unit di belakang dalam barisan musuh',
		zawakeEffectDesc_vn = 'Rin Tosaka thi triển bùa chú, triệu hồi một loạt mũi tên khắc tấn công mục tiêu địch theo hàng, gây #C0x3D8A99#150% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B5 4#Spell Damage#C0x5B545B#, 50% cơ hội <Đóng băng> mục tiêu trong 2 lượt (Đóng băng: hiệu ứng khống chế, không thể di chuyển, giải phóng sau khi nhận hơn 30% sinh lực của mục tiêu), lần đầu tiên giải phóng 100% đóng băng các đơn vị hàng sau trong hàng địch',
