	[7413] = {
		id = 7413,
		skillName_vn = 'Trừng phạt thánh thiện',
		skillName_en = 'Holy punishment',
		skillName_th = 'การลงโทษศักดิ์สิทธิ์',
		skillName_in = 'Hukuman suci',
		skillName_ph = 'Banal na parusa',
		skillName_ma = 'Hukuman suci',
		skillName = 'Holy punishment',
		describe_vn = 'Ikki triệu hồi một con phượng hoàng lửa tấn công tất cả mục tiêu của kẻ địch, gây ra #C0x3D8A99#230% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# sát thương phép#C0x5B545B# cho tất cả kẻ thù. Thêm [Đốt] trong 3 hiệp (Đốt: hiệu ứng tiêu cực, mục tiêu sẽ gây ra #C0x3D8A99#40% Sát Thương Phép Thuật #C0x5B545B# sát thương phép cộng thêm trước mỗi hiệp, có thể cộng dồn tối đa 5 lớp); tăng 15% tỷ lệ trúng đòn chí mạng của tất cả đồng minh, kéo dài trong 2 hiệp và tăng gấp đôi số lượng nhân vật lửa.',
		describe_en = 'Ikki summons a fire phoenix to attack all enemy targets, dealing #C0x3D8A99#230% Magic Damage#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54# magic damage#C0x5B545B# to all enemies. Applies [Burn] for 3 turns (Burn: a negative effect, the target takes #C0x3D8A99#40% additional Magic Damage#C0x5B545B# before each turn, stacking up to 5 layers); increases all allies\' critical hit rate by 15% for 2 turns and doubles the number of fire characters.',
		describe_th = 'อิกกินำมังกรไฟฟีนิกซ์โจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวทมนตร์ #C0x3D8A99#230%#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# แก่ศัตรูทั้งหมด เพิ่ม [เผาไหม้] เป็นเวลา 3 เทิร์น (เผาไหม้: เอฟเฟกต์ลบ เป้าหมายจะได้รับความเสียหายเวทมนตร์เพิ่มขึ้น #C0x3D8A99#40%#C0x5B545B# ก่อนแต่ละเทิร์น ทับซ้อนได้สูงสุด 5 ชั้น); เพิ่มอัตราตีคริติคอลของพันธมิตรทั้งหมด 15% เป็นเวลา 2 เทิร์น และเพิ่มจำนวนตัวละครธาตุไฟเป็นสองเท่า',
		describe_in = 'Ikki memanggil burung phoenix api untuk menyerang semua target musuh, memberikan #C0x3D8A99#230% Kerusakan Magic#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54# kerusakan magic#C0x5B545B# kepada semua musuh. Menambahkan [Terbakar] selama 3 giliran (Terbakar: efek negatif, target akan menerima #C0x3D8A99#40% Kerusakan Magic tambahan#C0x5B545B# sebelum setiap giliran, dapat bertumpuk hingga 5 lapis); meningkatkan peluang serangan kritis semua sekutu sebesar 15% selama 2 giliran dan menggandakan jumlah karakter api.',
		describe_ph = 'Ikki ay nagpapatawag ng isang apoy na phoenix upang atakihin ang lahat ng kalabang target, nagdudulot ng #C0x3D8A99#230% Magic Damage#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54# magic damage#C0x5B545B# sa lahat ng kalaban. Naglalagay ng [Burn] sa loob ng 3 rounds (Burn: isang negatibong epekto, ang target ay tatanggap ng karagdagang #C0x3D8A99#40% Magic Damage#C0x5B545B# bago ang bawat round, maaaring mag-stack hanggang 5 layers); pinapataas ang critical hit rate ng lahat ng kaalyado ng 15% sa loob ng 2 rounds at pinadodoble ang bilang ng mga fire characters.',
		describe_ma = 'Ikki memanggil burung phoenix api untuk menyerang semua sasaran musuh, memberikan #C0x3D8A99#230% Kerosakan Sihir#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54# kerosakan sihir#C0x5B545B# kepada semua musuh. Menambah [Terbakar] selama 3 pusingan (Terbakar: kesan negatif, sasaran akan menerima #C0x3D8A99#40% Kerosakan Sihir tambahan#C0x5B545B# sebelum setiap pusingan, boleh bertindih sehingga 5 lapisan); meningkatkan kadar serangan kritikal semua sekutu sebanyak 15% selama 2 pusingan dan menggandakan bilangan watak api.',
		describe = 'Ikki summons a fire phoenix to attack all enemy targets, dealing #C0x3D8A99#230% Magic Damage#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54# magic damage#C0x5B545B# to all enemies. Applies [Burn] for 3 turns (Burn: a negative effect, the target takes #C0x3D8A99#40% additional Magic Damage#C0x5B545B# before each turn, stacking up to 5 layers); increases all allies\' critical hit rate by 15% for 2 turns and doubles the number of fire characters.',
		simDesc_vn = 'Ikki triệu hồi phượng hoàng lửa tấn công mọi mục tiêu của kẻ địch, tăng tỉ lệ chí mạng cho toàn bộ đồng minh.',
		simDesc_en = 'Ikki summons a fiery phoenix to attack all enemy targets, increasing the critical hit rate for all allies.',
		simDesc_th = 'อิกกิเรียกฟีนิกซ์ไฟโจมตีทุกเป้าหมายของศัตรู พร้อมเพิ่มอัตราคริติคอลให้กับพันธมิตรทั้งหมด',
		simDesc_in = 'Ikki memanggil phoenix api untuk menyerang semua target musuh, meningkatkan tingkat critical hit untuk semua sekutu.',
		simDesc_ph = 'Si Ikki ay nag-summon ng apoy na phoenix upang atakihin ang lahat ng target ng kaaway, pinapataas ang critical hit rate para sa lahat ng mga kapanalig.',
		simDesc_ma = 'Ikki memanggil phoenix api untuk menyerang semua sasaran musuh, meningkatkan kadar serangan kritikal untuk semua sekutu.',
		simDesc = 'Ikki summons a fiery phoenix to attack all enemy targets, increasing the critical hit rate for all allies.',
		starEffect = __data_t__starEffect[7413],
