	[7514] = {
		id = 7514,
		skillName_vn = 'Đòn đánh của rồng giận dữ',
		skillName_en = 'Strike of the furious dragon',
		skillName_th = 'การโจมตีของมังกรที่โกรธเกรี้ยว',
		skillName_in = 'Serangan naga yang marah',
		skillName_ph = 'Pag-atake ng galit na dragon',
		skillName_ma = 'Serangan naga yang marah',
		skillName = 'Strike of the furious dragon',
		describe_vn = 'Quái Long di chuyển nhanh, mang theo sấm sét, tung đòn Rồng Nộ vào mục tiêu đơn lẻ của địch, gây ra #C0xE69900#520% vật công#C0x5B545B#+$(skillLevel*4*75)$ Sát Thương Vật Lý#C0xF13B54#, đòn tấn công này bỏ qua 20% phòng thủ vật lý của mục tiêu, và mỗi hiệu ứng tiêu cực hoặc khống chế trên mục tiêu sẽ tăng 15% tỷ lệ bạo kích của Quái Long đối với mục tiêu đó',
		describe_en = 'The Thunder Dragon moves swiftly, bringing thunder and lightning, unleashing the Furious Dragon Strike on a single enemy target, dealing #C0xE69900#520% Physical Attack#C0x5B545B# + $(skillLevel*4*75)$ Physical Damage#C0xF13B54#. This attack bypasses 20% of the target\'s physical defense, and each negative effect or control effect on the target increases the Thunder Dragon\'s critical hit rate against that target by 15%.',
		describe_th = 'มังกรสายฟ้าเคลื่อนที่อย่างรวดเร็ว นำพาเสียงฟ้าร้องและสายฟ้า ปล่อยท่าร่างมังกรแห่งความโกรธใส่เป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0xE69900#520% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*75)$ ความเสียหายทางกายภาพ#C0xF13B54# การโจมตีนี้สามารถละเลยการป้องกันกายภาพของเป้าหมายได้ 20% และผลกระทบลบหรือสถานะควบคุมแต่ละอย่างบนเป้าหมายจะเพิ่มอัตราคริติคอลของมังกรสายฟ้าเพิ่มขึ้น 15% ต่อเป้าหมายนั้น',
		describe_in = 'Naga Petir bergerak cepat, membawa gemuruh dan kilat, melancarkan Serangan Naga Amarah ke satu target musuh, menyebabkan #C0xE69900#520% Serangan Fisik#C0x5B545B# + $(skillLevel*4*75)$ Kerusakan Fisik#C0xF13B54#. Serangan ini mengabaikan 20% pertahanan fisik target, dan setiap efek negatif atau kontrol pada target akan meningkatkan tingkat kritis Naga Petir terhadap target tersebut sebesar 15%.',
		describe_ph = 'Ang Makulog na Dragon ay mabilis na kumikilos, dala ang kulog at kidlat, naglunsad ng Furious Dragon Strike laban sa isang solong target ng kaaway, na nagdudulot ng #C0xE69900#520% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*75)$ Pisikal na Pinsala#C0xF13B54#. Ang atakeng ito ay nilalampasan ang 20% ng pisikal na depensa ng target, at bawat negatibong epekto o kontrol sa target ay nagpapataas ng kritikal na tsansa ng Makulog na Dragon laban sa target ng 15%.',
		describe_ma = 'Naga Guntur bergerak pantas, membawa petir dan guruh, melancarkan Serangan Naga Marah ke sasaran tunggal musuh, menyebabkan #C0xE69900#520% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*75)$ Kerosakan Fizikal#C0xF13B54#. Serangan ini mengabaikan 20% pertahanan fizikal sasaran, dan setiap kesan negatif atau kawalan ke atas sasaran akan meningkatkan kadar kritikal Naga Guntur terhadap sasaran tersebut sebanyak 15%.',
		describe = 'The Thunder Dragon moves swiftly, bringing thunder and lightning, unleashing the Furious Dragon Strike on a single enemy target, dealing #C0xE69900#520% Physical Attack#C0x5B545B# + $(skillLevel*4*75)$ Physical Damage#C0xF13B54#. This attack bypasses 20% of the target\'s physical defense, and each negative effect or control effect on the target increases the Thunder Dragon\'s critical hit rate against that target by 15%.',
		simDesc_vn = 'Dragonite di chuyển nhanh chóng, mang theo sấm sét, tấn công mạnh vào mục tiêu đơn lẻ của đối phương, tỷ lệ chí mạng tăng theo số lượng hiệu ứng tiêu cực của mục tiêu.',
		simDesc_en = 'Dragonite moves swiftly, carrying thunder and lightning, delivering a powerful attack on a single enemy target, with a critical hit rate that increases based on the number of negative effects on the target.',
		simDesc_th = 'Dragonite เคลื่อนที่อย่างรวดเร็ว พร้อมกับสายฟ้าโจมตีเป้าหมายเดียวของศัตรูด้วยพลัง ทำให้โอกาสคริติคอลเพิ่มขึ้นตามจำนวนเอฟเฟกต์ลบที่เป้าหมายได้รับ',
		simDesc_in = 'Dragonite bergerak cepat, membawa petir, menyerang dengan kuat pada satu sasaran musuh, dengan peluang kritis yang meningkat berdasarkan jumlah efek negatif pada target.',
