	[7534] = {
		id = 7534,
		skillName_vn = 'Đòn đánh của rồng giận dữ',
		skillName_en = 'Strike of the Furious Dragon',
		skillName_th = 'การโจมตีของมังกรโกรธเกรี้ยว',
		skillName_in = 'Serangan Naga yang Marah',
		skillName_ph = 'Atake ng Galit na Dragon',
		skillName_ma = 'Serangan Naga Marah',
		skillName = 'Strike of the Furious Dragon',
		describe_vn = 'Quái Long di chuyển nhanh, mang theo sấm sét, tung đòn Rồng Nộ vào mục tiêu đơn lẻ của địch, gây ra #C0xE69900#520% vật công#C0x5B545B#+$(skillLevel*4*75)$ Sát Thương Vật Lý#C0xF13B54#, đòn tấn công này bỏ qua 20% phòng thủ vật lý của mục tiêu, và mỗi hiệu ứng tiêu cực hoặc khống chế trên mục tiêu sẽ tăng 15% tỷ lệ bạo kích của Quái Long đối với mục tiêu đó',
		describe_en = 'The Thunder Dragon moves swiftly, carrying thunder and lightning, unleashing the Furious Dragon strike on a single enemy target, dealing #C0xE69900#520% Physical Attack#C0x5B545B# + $(skillLevel*4*75)$ Physical Damage#C0xF13B54#. This attack ignores 20% of the target\'s physical defense, and each negative effect or control effect on the target increases the Thunder Dragon\'s critical hit rate against that target by 15%.',
		describe_th = 'มังกรสายฟ้าเคลื่อนที่รวดเร็ว นำพาสายฟ้าแลบ ปล่อยท่าพลังมังกรโกรธจัดใส่เป้าหมายศัตรูเดี่ยว สร้างความเสียหายทางกายภาพ #C0xE69900#520%#C0x5B545B# + $(skillLevel*4*75)$#C0xF13B54# การโจมตีนี้ละเลยการป้องกันกายภาพของเป้าหมาย 20% และเอฟเฟกต์ลบหรือสถานะควบคุมบนเป้าหมายแต่ละอย่างจะเพิ่มโอกาสคริติคอลของมังกรสายฟ้าต่อเป้าหมายนั้น 15%',
		describe_in = 'Naga Petir bergerak cepat, membawa petir dan guntur, melancarkan serangan Naga Marah pada target musuh tunggal, memberikan #C0xE69900#520% Serangan Fisik#C0x5B545B# + $(skillLevel*4*75)$ Kerusakan Fisik#C0xF13B54#. Serangan ini mengabaikan 20% pertahanan fisik target, dan setiap efek negatif atau kontrol pada target meningkatkan peluang kritis Naga Petir terhadap target tersebut sebesar 15%.',
		describe_ph = 'Ang Bunsong Dragon ay mabilis kumilos, may dalang kidlat, nagpapalabas ng Galit na Dragon na atake sa isang target na kalaban, nagdudulot ng #C0xE69900#520% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*75)$ Pisikal na Pinsala#C0xF13B54#. Ang atakeng ito ay nilalampasan ang 20% ng pisikal na depensa ng target, at bawat negatibong epekto o kontrol sa target ay nagtataas ng 15% ng tsansa ng kritikal ng Bunsong Dragon laban sa target na iyon.',
		describe_ma = 'Naga Guruh bergerak pantas, membawa petir dan guntur, melancarkan serangan Naga Marah ke sasaran musuh tunggal, memberi #C0xE69900#520% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*75)$ Kerosakan Fizikal#C0xF13B54#. Serangan ini mengabaikan 20% pertahanan fizikal sasaran, dan setiap kesan negatif atau kawalan ke atas sasaran meningkatkan kadar kritikal Naga Guruh terhadap sasaran itu sebanyak 15%.',
		describe = 'The Thunder Dragon moves swiftly, carrying thunder and lightning, unleashing the Furious Dragon strike on a single enemy target, dealing #C0xE69900#520% Physical Attack#C0x5B545B# + $(skillLevel*4*75)$ Physical Damage#C0xF13B54#. This attack ignores 20% of the target\'s physical defense, and each negative effect or control effect on the target increases the Thunder Dragon\'s critical hit rate against that target by 15%.',
		simDesc_vn = 'Dragonite di chuyển nhanh chóng, mang theo sấm sét, tấn công mạnh vào mục tiêu đơn lẻ của đối phương, tỷ lệ chí mạng tăng theo số lượng hiệu ứng tiêu cực của mục tiêu.',
		simDesc_en = 'Dragonite moves swiftly, bringing thunder and lightning, delivering a powerful strike to a single enemy target. Critical hit rate increases based on the number of negative effects on the target.',
		simDesc_th = 'Dragonite เคลื่อนที่อย่างรวดเร็ว พร้อมสายฟ้าและฟ้าร้อง โจมตีเป้าหมายเดี่ยวของฝ่ายตรงข้ามอย่างรุนแรง อัตราคริติคอลเพิ่มขึ้นตามจำนวนผลลบที่เป้าหมายได้รับ',
		simDesc_in = 'Dragonite bergerak cepat, membawa petir, menyerang kuat pada satu target musuh. Tingkat serangan kritis meningkat berdasarkan jumlah efek negatif pada target.',
		simDesc_ph = 'Mabilis na gumagalaw ang Dragonite, dala ang kidlat, malakas na umaatake sa isang kalabang target. Tumataas ang tsansang gumawa ng critical hit batay sa dami ng negatibong epekto sa target.',
		simDesc_ma = 'Dragonite bergerak pantas, membawa petir, menyerang kuat pada satu sasaran musuh. Kadar serangan kritikal meningkat mengikut jumlah kesan negatif pada sasaran.',
		simDesc = 'Dragonite moves swiftly, bringing thunder and lightning, delivering a powerful strike to a single enemy target. Critical hit rate increases based on the number of negative effects on the target.',
		starEffect = __data_t__starEffect[7534],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Trước khi gây sát thương, có 60% xác suất thêm 20% dễ bị tổn thương, cháy, và tê liệt cho mục tiêu trong 1 lượt.',
		starEffectDesc = 'Additional effect: Before dealing damage, there is a 60% chance to add 20% increased vulnerability, burn, and paralysis to the target for 1 turn.',
		starEffectDesc_en = 'Additional effect: Before dealing damage, there is a 60% chance to add 20% increased vulnerability, burn, and paralysis to the target for 1 turn.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ก่อนที่จะสร้างความเสียหาย มีโอกาส 60% ที่จะเพิ่มความเปราะบาง 20%, การถูกไฟลวก และการถูกชะงักงันแก่เป้าหมายเป็นเวลา 1 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Sebelum memberikan kerusakan, ada 60% kemungkinan menambahkan 20% kerentanan, terbakar, dan lumpuh pada target selama 1 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Bago magdulot ng pinsala, may 60% na tsansa na magdagdag ng 20% na pagkahina, pagkasunog, at paralisis sa target sa loob ng 1 turn.',
		starEffectDesc_ma = 'Kesan tambahan: Sebelum menyebabkan kerosakan, terdapat 60% kemungkinan untuk menambah 20% kerentanan, kebakaran, dan lumpuh pada sasaran selama 1 pusingan.',
		zawakeEffect = __data_t__zawakeEffect[7534],
		-- {79003}
		zawakeEffectDesc = 'The Fierce Dragon moves swiftly, carrying thunder, attacking a single enemy target with a furious strike, dealing #C0xE69900#520% physical attack #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#physical #C0x5B545B# damage. This attack ignores 50% of the target\'s physical defense. This special skill temporarily increases critical strike by 30% and for each negative effect or control effect on the target, the Fierce Dragon increases critical strike rate by 15% against that target.',
		zawakeEffectDesc_en = 'The Fierce Dragon moves swiftly, carrying thunder, attacking a single enemy target with a furious strike, dealing #C0xE69900#520% physical attack #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#physical #C0x5B545B# damage. This attack ignores 50% of the target\'s physical defense. This special skill temporarily increases critical strike by 30% and for each negative effect or control effect on the target, the Fierce Dragon increases critical strike rate by 15% against that target.',
		zawakeEffectDesc_th = 'มังกรดุร้ายเคลื่อนที่อย่างรวดเร็ว พร้อมกับสายฟ้า ตีเป้าหมายศัตรูเดี่ยวด้วยการโจมตีที่ดุเดือด สร้างความเสียหาย #C0xE69900#520% พลังโจมตีทางกายภาพ #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#ความเสียหายทางกายภาพ #C0x5B545B# การโจมตีครั้งนี้ข้ามการป้องกันทางกายภาพของเป้าหมาย 50% ทักษะพิเศษนี้เพิ่มคริติคอลชั่วคราว 30% และสำหรับทุกเอฟเฟกต์ลบหรือเอฟเฟกต์ควบคุมบนเป้าหมาย มังกรดุร้ายเพิ่มอัตราคริติคอลอีก 15% ต่อเป้าหมายนั้น',
		zawakeEffectDesc_in = 'Naga Garang bergerak cepat, membawa petir, menyerang satu target musuh dengan serangan marah, menghasilkan #C0xE69900#520% serangan fisik #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#kerusakan fisik #C0x5B545B#. Serangan ini mengabaikan 50% pertahanan fisik target. Skill khusus ini sementara meningkatkan kritikal sebesar 30% dan untuk setiap efek negatif atau kontrol tambahan pada target, Naga Garang meningkatkan tingkat kritikal sebesar 15% terhadap target tersebut.',
		zawakeEffectDesc_ph = 'Ang Mabagsik na Dragon ay mabilis na kumikilos, may kasamang kidlat, umaatake sa isang kalabang target nang isa-isa gamit ang galit na pagtama, nagdudulot ng #C0xE69900#520% pisikal na atake #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#pisikal na pinsala #C0x5B545B#. Ang atakeng ito ay nilalampasan ang 50% pisikal na depensa ng target. Ang espesyal na kasanayang ito ay pansamantalang nagpapataas ng kritikal ng 30% at sa bawat negatibong epekto o kontrol na idinadagdag sa target, pinapataas ng Mabagsik na Dragon ang porsyento ng kritikal ng 15% laban sa target na iyon.',
		zawakeEffectDesc_ma = 'Naga Garang bergerak pantas, membawa petir, menyerang satu sasaran musuh dengan serangan yang marah, memberikan #C0xE69900#520% serangan fizikal #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#kerosakan fizikal #C0x5B545B#. Serangan ini mengabaikan 50% pertahanan fizikal sasaran. Kemahiran khas ini sementara meningkatkan kritikal sebanyak 30% dan untuk setiap kesan negatif atau kawalan tambahan pada sasaran, Naga Garang meningkatkan kadar kritikal sebanyak 15% terhadap sasaran tersebut.',
		zawakeEffectDesc_vn = 'Quái Long di chuyển nhanh, mang theo sấm sét, tấn công mục tiêu đơn lẻ của địch với cú đánh giận dữ, gây #C0xE69900#520% vật công #C0x5B545B#+$(skillLevel*4*75)$ sát thương #C0xF13B54#vật lý #C0x5B545B#, lần tấn công này bỏ qua 50% phòng thủ vật lý của mục tiêu, kỹ năng đặc biệt này tạm thời tăng 30% bạo kích và mỗi hiệu ứng tiêu cực hoặc kiểm soát thêm trên mục tiêu, Quái Long tăng 15% tỷ lệ bạo kích đối với mục tiêu đó',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'This attack ignores 20% of the target\'s physical resistance#F20# #F40##C0x5c9970#→This attack ignores 50% of the target\'s physical resistance, and critical skill damage temporarily increases by 30%',
		zawakeSimpleDesc_en = 'This attack ignores 20% of the target\'s physical resistance#F20# #F40##C0x5c9970#→This attack ignores 50% of the target\'s physical resistance, and critical skill damage temporarily increases by 30%',
		zawakeSimpleDesc_th = 'การโจมตีนี้ไม่สนพลังป้องกันกายภาพของเป้าหมาย 20%#F20# #F40##C0x5c9970#→การโจมตีนี้ไม่สนพลังป้องกันกายภาพของเป้าหมาย 50% และเพิ่มคริติคอลของสกิลนี้ชั่วคราว 30%',
		zawakeSimpleDesc_in = 'Serangan ini mengabaikan 20% resistensi fisik target#F20# #F40##C0x5c9970#→Serangan ini mengabaikan 50% resistensi fisik target, dan damage kritis skill sementara meningkat 30%',
		zawakeSimpleDesc_ph = 'Ang atakeng ito ay binabalewala ang 20% physical resistance ng target#F20# #F40##C0x5c9970#→Ang atakeng ito ay binabalewala ang 50% physical resistance ng target, pansamantalang tataas ng 30% ang skill critical',
		zawakeSimpleDesc_ma = 'Serangan ini mengabaikan 20% rintangan fizikal sasaran#F20# #F40##C0x5c9970#→Serangan ini mengabaikan 50% rintangan fizikal sasaran, dan serangan kritikal kemahiran sementara meningkat 30%',
		zawakeSimpleDesc_vn = 'Lần tấn công này bỏ qua 20% kháng vật lý của mục tiêu#F20# #F40##C0x5c9970#→Lần tấn công này bỏ qua 50% kháng vật lý của mục tiêu, kỹ năng chí mạng tạm thời tăng 30%',
