	[7613] = {
		id = 7613,
		skillName_vn = 'EX-Sao Băng Xung Kích',
		skillName_en = 'EX-Meteor Rush',
		skillName_th = 'EX-ฝ่าเมทิโอ',
		skillName_in = 'EX-Badai Meteor',
		skillName_ph = 'EX-Meteor Rush',
		skillName_ma = 'EX-Serbuan Meteor',
		skillName = 'EX-Meteor Rush',
		describe_vn = 'Shining Starlight-Asuna giải phóng sức mạnh của các vị thần và sử dụng Kỹ thuật kiếm siêu thần EX-Star Impact để tấn công một mục tiêu kẻ thù, gây ra #C0x3D8A99#680% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$ của #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, cho phép bản thân nhận được một tấm chắn chớp nhoáng trong 2 lượt (có thể hấp thụ 30% sát thương do chiêu thức đặc biệt này gây ra). Trong thời gian lá chắn chớp nhoáng, khả năng chống chịu các tác động tiêu cực của bản thân tăng thêm 60%. Khi tấm chắn ánh sáng bị vỡ sẽ gây sát thương bằng máu của tấm chắn ánh sáng cho mục tiêu (sát thương này có thể gây ra đòn chí mạng)',
		describe_en = 'Shining Starlight-Asuna unleashes the power of the gods and uses the EX Divine Sword Technique Star Impact to attack an enemy target, dealing 680% Magic Damage plus $(skillLevel*4*90)$ Magic Damage. She gains a Flash Shield for 2 turns (absorbs 30% of the damage dealt by this special skill). While the Flash Shield is active, her resistance to negative effects increases by 60%. When the Flash Shield breaks, it deals damage equal to the shield\'s HP to the target (this damage can critically hit).',
		describe_th = 'Shining Starlight-Asuna ปลดปล่อยพลังของเหล่าทวยเทพและใช้เทคนิคดาบเทพ EX-Star Impact โจมตีเป้าหมายศัตรู สร้างความเสียหายเวทมนตร์ 680% บวก $(skillLevel*4*90)$ ความเสียหายเวทมนตร์ รับโล่แสงวาบเป็นเวลา 2 เทิร์น (สามารถดูดซับความเสียหาย 30% จากสกิลพิเศษนี้) ในขณะที่มีโล่วาบ ป้องกันผลกระทบลบเพิ่มขึ้น 60% เมื่อโล่วิบวับแตก จะสร้างความเสียหายเท่ากับพลังชีวิตของโล่ให้กับเป้าหมาย (ความเสียหายนี้สามารถทำคริติคอลได้)',
		describe_in = 'Shining Starlight-Asuna melepaskan kekuatan para dewa dan menggunakan Teknik Pedang Ilahi EX-Star Impact untuk menyerang target musuh, memberikan 680% Kerusakan Sihir ditambah $(skillLevel*4*90)$ Kerusakan Sihir. Dia mendapat Perisai Kilat selama 2 giliran (menyerap 30% kerusakan yang disebabkan oleh skill khusus ini). Saat Perisai Kilat aktif, ketahanannya terhadap efek negatif meningkat sebesar 60%. Saat Perisai Kilat pecah, itu akan memberikan damage sama dengan HP perisai ke target (damage ini dapat mengenai serangan kritis).',
		describe_ph = 'Pinakikinang na Starlight-Asuna ipinakakawala ang kapangyarihan ng mga diyos at ginamit ang EX-Diyos na Teknik ng Espada Star Impact upang atakihin ang isang kaaway na target, na nagdudulot ng 680% Magic Damage kasama ang $(skillLevel*4*90)$ Magic Damage. Nakakakuha siya ng Flash Shield sa loob ng 2 rounds (nakakabawas ng 30% ng damage mula sa espesyal na skill na ito). Habang buhay ang Flash Shield, tumataas ang kanyang resistensya sa mga negatibong epekto ng 60%. Kapag nasira ang Flash Shield, ito ay nagdudulot ng damage na katumbas ng HP ng shield sa target (ang damage na ito ay maaaring magdulot ng critical hit).',
		describe_ma = 'Shining Starlight-Asuna melepaskan kuasa para dewa dan menggunakan Teknik Pedang Ilahi EX-Star Impact untuk menyerang sasaran musuh, menyebabkan 680% Kerosakan Sihir ditambah $(skillLevel*4*90)$ Kerosakan Sihir. Dia memperoleh Perisai Sekilas selama 2 pusingan (boleh menyerap 30% kerosakan daripada serangan khas ini). Semasa Perisai Sekilas aktif, ketahanannya terhadap kesan negatif meningkat sebanyak 60%. Apabila perisai pecah, ia akan menyebabkan kerosakan bersamaan dengan HP perisai kepada sasaran (kerosakan ini boleh menyebabkan serangan kritikal).',
		describe = 'Shining Starlight-Asuna unleashes the power of the gods and uses the EX Divine Sword Technique Star Impact to attack an enemy target, dealing 680% Magic Damage plus $(skillLevel*4*90)$ Magic Damage. She gains a Flash Shield for 2 turns (absorbs 30% of the damage dealt by this special skill). While the Flash Shield is active, her resistance to negative effects increases by 60%. When the Flash Shield breaks, it deals damage equal to the shield\'s HP to the target (this damage can critically hit).',
		simDesc_vn = 'Ánh sao tỏa sáng: Asuna giải phóng sức mạnh của các vị thần và sử dụng Kỹ thuật siêu thần kiếm EX: Star Impact để tấn công một mục tiêu kẻ thù và nhận cho mình một lá chắn chớp nhoáng.',
		simDesc_en = 'Shining Star: Asuna unleashes the power of the gods and uses the Super Divine Sword Technique EX: Star Impact to attack an enemy target and gains a flashing shield.',
		simDesc_th = 'ดาวประกาย: อาสึนะปลดปล่อยพลังของเทพเจ้าและใช้เทคนิคดาบเทพ EX: Star Impact เพื่อโจมตีเป้าหมายศัตรูและได้รับโล่แสงวาบวาบ',
		simDesc_in = 'Bintang Bercahaya: Asuna melepaskan kekuatan para dewa dan menggunakan Teknik Pedang Super Dewa EX: Star Impact untuk menyerang target musuh serta mendapatkan perisai yang berkilau.',
		simDesc_ph = 'Nagniningning na Bituin: Pinalalaya ni Asuna ang kapangyarihan ng mga diyos at ginagamit ang Super Divine Sword Technique EX: Star Impact upang atakihin ang isang target na kalaban at nakakakuha ng kumikislap na kalasag.',
		simDesc_ma = 'Bintang Bersinar: Asuna melepaskan kekuatan para dewa dan menggunakan Teknik Pedang Super Dewa EX: Star Impact untuk menyerang sasaran musuh serta memperoleh perisai yang berkilat.',
		simDesc = 'Shining Star: Asuna unleashes the power of the gods and uses the Super Divine Sword Technique EX: Star Impact to attack an enemy target and gains a flashing shield.',
		starEffect = __data_t__starEffect[7613],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Đòn tấn công này kích hoạt thêm Sức mạnh Sáng thế: Thêm một lượng Lá chắn Ánh sáng tương đương cho hai đồng đội hệ Ma Thần ngẫu nhiên (không gây sát thương khi phá khiên), và ngay lập tức khiến tất cả đồng đội hệ Ma Thần của phe ta tấn công thêm một lần vào đối phương (nếu đầy nộ có thể dùng kỹ năng tất sát).',
		starEffectDesc = 'Additional Effect: This attack activates the Power of Genesis: Adds an equivalent amount of Light Shield to two random Demon-type allies (does not deal damage when shield is broken), and immediately causes all Demon-type allies on our side to attack the enemy once more (if fully charged, they can use the lethal skill).',
		starEffectDesc_en = 'Additional Effect: This attack activates the Power of Genesis: Adds an equivalent amount of Light Shield to two random Demon-type allies (does not deal damage when shield is broken), and immediately causes all Demon-type allies on our side to attack the enemy once more (if fully charged, they can use the lethal skill).',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: การโจมตีนี้จะเปิดใช้งานพลังแห่งการถือกำเนิด: เพิ่มเกราะแสงเทียบเท่าสำหรับเพื่อนร่วมทีมสายปีศาจ 2 คนแบบสุ่ม (ไม่สร้างความเสียหายเมื่อเกราะแตก) และทำให้เพื่อนร่วมทีมสายปีศาจทั้งหมดฝ่ายเราตีศัตรูอีกครั้งทันที (ถ้าเกจเต็มสามารถใช้สกิลพิฆาตได้)',
		starEffectDesc_in = 'Efek Tambahan: Serangan ini mengaktifkan Kekuatan Penciptaan: Menambahkan sejumlah Perisai Cahaya yang setara ke dua rekan satu tim bertipe Iblis secara acak (tidak menyebabkan kerusakan saat perisai pecah), dan segera membuat semua rekan bertipe Iblis di pihak kita menyerang musuh satu kali lagi (jika penuh emosi bisa menggunakan keterampilan pembunuh).',
		starEffectDesc_ph = 'Karagdagang Epekto: Ang pag-atakeng ito ay nag-aaktibo ng Lakas ng Paglikha: Nagdadagdag ng katumbas na Halaga ng Liwanag na Kalasag sa dalawang random na Demon-type na kakampi (hindi nakakasakit kapag naputol ang kalasag), at agad na pinapaatake ng lahat ng Demon-type na kakampi sa aming panig ang kalaban ng isang ulit pa (kung puno ang galit ay maaaring gamitin ang nakamamatay na kasanayan).',
		starEffectDesc_ma = 'Kesan Tambahan: Serangan ini mengaktifkan Kuasa Penciptaan: Menambah jumlah Perisai Cahaya yang setara kepada dua rakan sepasukan jenis Iblis secara rawak (tidak menyebabkan kerosakan apabila perisai pecah), dan serta merta menyebabkan semua rakan jenis Iblis dalam pihak kita menyerang musuh sekali lagi (jika penuh kemarahan boleh menggunakan kemahiran mematikan).',
		zawakeEffect = __data_t__zawakeEffect[7613],
		-- {79003}
		zawakeEffectDesc = 'Shining Starlight-Asuna unleashes the power of the gods and uses the EX-Star Impact super divine sword technique to attack an enemy target, dealing #C0x3D8A99#680% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magical Damage#C0x5B545B#. Additionally, it increases the critical hit rate and critical damage of this attack by 20% and 40%, respectively, and creates a flash shield for 2 turns (which can absorb 50% of the damage from this special attack). While using the flash shield, it increases negative effect resistance by 60% and control immunity rate by 40%. When the light shield breaks, it deals damage equal to the shield\'s HP to the target (this damage can cause a critical hit).',
		zawakeEffectDesc_en = 'Shining Starlight-Asuna unleashes the power of the gods and uses the EX-Star Impact super divine sword technique to attack an enemy target, dealing #C0x3D8A99#680% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magical Damage#C0x5B545B#. Additionally, it increases the critical hit rate and critical damage of this attack by 20% and 40%, respectively, and creates a flash shield for 2 turns (which can absorb 50% of the damage from this special attack). While using the flash shield, it increases negative effect resistance by 60% and control immunity rate by 40%. When the light shield breaks, it deals damage equal to the shield\'s HP to the target (this damage can cause a critical hit).',
		zawakeEffectDesc_th = 'Shining Starlight-Asuna ปลดปล่อยพลังของเทพเจ้าและใช้เทคนิคดาบเทพ EX-Star Impact โจมตีเป้าหมายศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#680%#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# นอกจากนี้ ยังเพิ่มอัตราคริติคอลและความเสียหายคริติคอลของการโจมตีนี้อีก 20% และ 40% ตามลำดับ พร้อมสร้างโล่แสงวาบเป็นเวลา 2 เทิร์น (สามารถดูดซับความเสียหาย 50% จากการโจมตีพิเศษนี้) ขณะใช้โล่แสงวาบ จะเพิ่มอัตราต้านทานผลกระทบเชิงลบ 60% และอัตราป้องกันการควบคุม 40% เมื่อโล่แสงถูกทำลาย จะสร้างความเสียหายจากพลังชีวิตของโล่แสงให้กับเป้าหมาย (ความเสียหายนี้อาจเป็นคริติคอล)',
		zawakeEffectDesc_in = 'Shining Starlight-Asuna melepaskan kekuatan para dewa dan menggunakan Teknik Pedang Super Ilahi EX-Star Impact untuk menyerang satu target musuh, menyebabkan #C0x3D8A99#680% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Kerusakan Magis#C0x5B545B#. Selain itu, teknik ini meningkatkan peluang serangan kritis dan kerusakan kritis dari serangan ini masing-masing sebesar 20% dan 40%, serta menciptakan sebuah perisai kilat selama 2 giliran (yang dapat menyerap 50% kerusakan dari serangan khusus ini). Saat menggunakan perisai kilat, tingkat resistensi efek negatif meningkat 60% dan tingkat kebal kontrol meningkat 40%. Ketika perisai cahaya hancur, akan menyebabkan kerusakan sebanyak HP perisai ke target (kerusakan ini bisa menjadi serangan kritis).',
		zawakeEffectDesc_ph = 'Shining Starlight-Asuna ay nagpapalaya ng kapangyarihan ng mga diyos at ginagamit ang Super Divine Sword Technique na EX-Star Impact para atakihin ang isang target na kalaban, nagdudulot ng #C0x3D8A99#680% Panlaban sa Magic#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Panlaban sa Magic#C0x5B545B#. Bukod dito, pinapataas nito ang kritikal na posibilidad at kritikal na pinsala ng pag-atake na ito ng 20% at 40%, at lumilikha ng isang flash shield sa loob ng 2 turns (na maaaring sumipsip ng 50% ng pinsala mula sa espesyal na pag-atakeng ito). Habang ginagamit ang flash shield, pinapataas nito ang resistensya laban sa negatibong epekto ng 60% at ang imun sa kontrol ng 40%. Kapag nasira ang light shield, nagdudulot ito ng pinsala na katumbas ng HP ng light shield sa target (ang pinsalang ito ay maaaring maging kritikal).',
		zawakeEffectDesc_ma = 'Shining Starlight-Asuna melepaskan kuasa para dewa dan menggunakan Teknik Pedang Super Ilahi EX-Star Impact untuk menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#680% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Kerosakan Magik#C0x5B545B#. Selain itu, ia meningkatkan kadar serangan kritikal dan kerosakan kritikal bagi serangan ini sebanyak 20% dan 40%, serta mencipta perisai kilat selama 2 pusingan (yang dapat menyerap 50% kerosakan daripada serangan khas ini). Semasa menggunakan perisai kilat, ia meningkatkan kadar ketahanan terhadap kesan negatif sebanyak 60% dan kadar imun kawalan sebanyak 40%. Apabila perisai cahaya hancur, ia menyebabkan kerosakan bersamaan dengan darah perisai cahaya kepada sasaran (kerosakan ini boleh menyebabkan serangan kritikal).',
		zawakeEffectDesc_vn = 'Shining Starlight-Asuna giải phóng sức mạnh của các vị thần và sử dụng Kỹ thuật kiếm siêu thần EX-Star Impact để tấn công một mục tiêu kẻ thù, gây ra #C0x3D8A99#680% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, uh Ngoài ra, nó còn tăng tỷ lệ trúng đòn chí mạng và sát thương chí mạng của đòn tấn công này lên thêm 20% và 40%, đồng thời tạo cho mình một lá chắn chớp nhoáng trong 2 lượt (có thể hấp thụ 50% sát thương của đòn tấn công đặc biệt này). Trong khi sử dụng khiên chắn flash, nó tăng tỷ lệ kháng hiệu ứng tiêu cực lên 60% và tỷ lệ miễn nhiễm kiểm soát lên 40%. Khi tấm chắn ánh sáng bị vỡ sẽ gây sát thương bằng máu của tấm chắn ánh sáng cho mục tiêu (sát thương này có thể gây ra một đòn chí mạng).',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Additionally, the critical rate and critical damage of this attack increase by 20% and 40% respectively; flash shield’s damage absorption coefficient increases by 20% and self-control immunity rate increases by 40% during the light shield duration.',
		zawakeSimpleDesc_en = '#C0x5c9970#Additionally, the critical rate and critical damage of this attack increase by 20% and 40% respectively; flash shield’s damage absorption coefficient increases by 20% and self-control immunity rate increases by 40% during the light shield duration.',
		zawakeSimpleDesc_th = '#C0x5c9970#นอกจากนี้ อัตราคริติคอลและความเสียหายคริติคอลของการโจมตีนี้เพิ่มขึ้น 20% และ 40% ตามลำดับ; ค่าการดูดซับความเสียหายของโล่แฟลชเพิ่มขึ้น 20% และอัตราการต้านทานควบคุมตัวเองเพิ่มขึ้น 40% ขณะโล่แสงทำงาน',
		zawakeSimpleDesc_in = '#C0x5c9970#Selain itu, peluang kritis dan damage kritis dari serangan ini meningkat masing-masing 20% dan 40%; koefisien penyerapan damage dari perisai flash meningkat 20% dan tingkat kekebalan terhadap kontrol diri meningkat 40% selama durasi perisai cahaya.',
		zawakeSimpleDesc_ph = '#C0x5c9970#Bukod pa rito, ang crit rate at crit damage ng atakeng ito ay tumataas ng 20% at 40%; ang absorption rate ng flash shield ay tumataas ng 20% at self-control immunity rate ay tumataas ng 40% habang aktibo ang light shield.',
		zawakeSimpleDesc_ma = '#C0x5c9970#Selain itu, kadar kritikal dan kerosakan kritikal serangan ini masing-masing meningkat sebanyak 20% dan 40%; pekali penyerapan kerosakan perisai cahaya meningkat 20% dan kadar imuniti kawalan diri meningkat 40% semasa tempoh perisai cahaya.',
		zawakeSimpleDesc_vn = '#C0x5c9970#Ngoài ra, tỷ lệ chí mạng và sát thương chí mạng của đòn tấn công này tăng lần lượt là 20% và 40%; hệ số hấp thụ sát thương của lá chắn flash tăng 20% ​​và tỷ lệ miễn nhiễm tự kiểm soát tăng 40% trong thời gian lá chắn ánh sáng.',
		upLvDesc = 'Fixed damage +360',
		upLvDesc_en = 'Fixed damage +360',
		upLvDesc_th = 'ความเสียหายคงที่ +360',
		upLvDesc_in = 'Kerusakan tetap +360',
