	[7616] = {
		id = 7616,
		skillName_vn = 'EX-Ánh Sáng Lấp Lánh',
		skillName_en = 'EX-Sparkling Light',
		skillName_th = 'EX-แสงระยิบระยับ',
		skillName_in = 'EX-Cahaya Berkilau',
		skillName_ph = 'EX-Kumikinang na Liwanag',
		skillName_ma = 'EX-Cahaya Berkilau',
		skillName = 'EX-Sparkling Light',
		describe_vn = 'Asuna có được quyền năng của Thần Sáng tạo với trang bị GM Shining Starlight: Shining Starlight. Sát thương của Asuna lên các mục tiêu chậm hơn mình tăng thêm #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#\nTrong 5 hiệp đầu tiên của trận chiến, trước khi bắt đầu mỗi hiệp lớn, khi Shining Star Asuna ở lệnh hành động đầu tiên của chúng ta, sau tất cả các hành động của chúng ta anh hùng, bản thân Shining Star Asuna có thể nhận thêm một vòng mới\nSức mạnh sáng tạo: Tất cả đồng đội quỷ thân thiện đều tăng 30% và bỏ qua phòng thủ kép',
		describe_en = 'Asuna gains the power of the God of Creation with the GM Shining Starlight equipment: Shining Starlight. Asuna\'s damage to targets slower than herself increases by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#\nDuring the first 5 rounds of the battle, before the start of each major round, when Shining Star Asuna is our first action in order, after all of our heroes\' actions, Shining Star Asuna can gain an additional turn\nCreative Power: All friendly demon allies increase their attack by 30% and ignore double defense.',
		describe_th = 'อาสึนะได้รับพลังแห่งเทพเจ้าการสร้างสรรค์พร้อมอุปกรณ์ GM Shining Starlight: Shining Starlight ความเสียหายของอาสึนะต่อเป้าหมายที่ช้ากว่าเธอเพิ่มขึ้น #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#\nใน 5 รอบแรกของการต่อสู้ ก่อนเริ่มแต่ละรอบใหญ่ เมื่อ Shining Star Asuna เป็นลำดับการกระทำแรกของเรา หลังจากการกระทำทั้งหมดของฮีโร่ของเรา Shining Star Asuna จะได้รับเทิร์นเพิ่มเติม\nพลังแห่งการสร้างสรรค์: เพื่อนปีศาจทั้งหมดเพิ่มพลังโจมตี 30% และละเลยการป้องกันคู่',
		describe_in = 'Asuna memperoleh kekuatan Dewa Pencipta dengan peralatan GM Shining Starlight: Shining Starlight. Kerusakan Asuna pada target yang lebih lambat darinya bertambah sebesar #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#\nDalam 5 giliran pertama pertempuran, sebelum memulai setiap giliran besar, saat Shining Star Asuna menjadi aksi pertama kita dalam urutan, setelah semua aksi pahlawan kita, Shining Star Asuna dapat memperoleh giliran tambahan\nKekuatan Kreatif: Semua sekutu iblis yang bersahabat meningkat 30% dan mengabaikan pertahanan ganda',
		describe_ph = 'Nakamit ni Asuna ang kapangyarihan ng Diyos ng Paglikha gamit ang GM Shining Starlight na kagamitan: Shining Starlight. Ang pinsala ni Asuna sa mga target na mas mabagal sa kanya ay tumataas ng #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#\nSa unang 5 rounds ng laban, bago magsimula ang bawat malaking round, kapag si Shining Star Asuna ang unang galaw natin sa order, pagkatapos ng lahat ng aksyon ng mga bayani natin, maaaring makakuha si Shining Star Asuna ng karagdagang turn\nKapangyarihan ng Paglikha: Lahat ng kaibigang demon na kasamahan ay tumataas ng 30% at nilalampasan ang dobleng depensa',
		describe_ma = 'Asuna memperoleh kuasa Dewa Cipta dengan peralatan GM Shining Starlight: Shining Starlight. Kerosakan Asuna kepada sasaran yang lebih lambat daripadanya meningkat sebanyak #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#\nDalam 5 pusingan pertama pertempuran, sebelum memulakan setiap pusingan besar, apabila Shining Star Asuna menjadi tindakan pertama kita dalam urutan, selepas semua tindakan wira kita, Shining Star Asuna boleh mendapat pusingan tambahan\nKuasa Ciptaan: Semua rakan syaitan mesra meningkat 30% dan mengabaikan pertahanan berganda',
		describe = 'Asuna gains the power of the God of Creation with the GM Shining Starlight equipment: Shining Starlight. Asuna\'s damage to targets slower than herself increases by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#\nDuring the first 5 rounds of the battle, before the start of each major round, when Shining Star Asuna is our first action in order, after all of our heroes\' actions, Shining Star Asuna can gain an additional turn\nCreative Power: All friendly demon allies increase their attack by 30% and ignore double defense.',
		starEffect = __data_t__starEffect[7616],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng thêm: Tấn công mục tiêu chậm hơn bản thân sẽ bỏ qua 30% kháng phép và 20% giảm sát thương của mục tiêu.',
		starEffectDesc = 'Additional effect: Attack targets slower than yourself will ignore 30% magic resistance and 20% damage reduction of the target.',
		starEffectDesc_en = 'Additional effect: Attack targets slower than yourself will ignore 30% magic resistance and 20% damage reduction of the target.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: โจมตีเป้าหมายที่ช้ากว่าตัวเองจะข้ามการต้านทานเวทมนตร์ 30% และการลดความเสียหายของเป้าหมาย 20%',
		starEffectDesc_in = 'Efek tambahan: Serang target yang lebih lambat dari diri sendiri akan mengabaikan 30% resistensi sihir dan pengurangan kerusakan 20% dari target.',
		starEffectDesc_ph = 'Karagdagang epekto: Ang pag-atake sa mga target na mas mabagal kaysa sa iyong sarili ay babalewalain ang 30% magic resistance at 20% bawas sa pinsala ng target.',
		starEffectDesc_ma = 'Kesan tambahan: Serang sasaran yang lebih lambat daripada diri sendiri akan mengabaikan 30% ketahanan sihir dan pengurangan kerosakan 20% daripada sasaran.',
		zawakeEffect = __data_t__zawakeEffect[7616],
		-- {79004}
		zawakeEffectDesc = 'Asuna receives the power of the God of Creation with the GM Shining Starlight equipment: Shining Starlight The damage Asuna deals to targets slower than her is increased by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nDuring the first 5 rounds of the battle, after all our heroes have acted, Shining Star Asuna herself may have an additional turn;\nDemon Leader: All friendly demon allies gain 30% and ignore double defense; after acting, she invites another random demon ally to attack with a normal strike.',
		zawakeEffectDesc_en = 'Asuna receives the power of the God of Creation with the GM Shining Starlight equipment: Shining Starlight The damage Asuna deals to targets slower than her is increased by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nDuring the first 5 rounds of the battle, after all our heroes have acted, Shining Star Asuna herself may have an additional turn;\nDemon Leader: All friendly demon allies gain 30% and ignore double defense; after acting, she invites another random demon ally to attack with a normal strike.',
		zawakeEffectDesc_th = 'อาสึนะได้รับพลังของเทพแห่งการสร้างสรรค์พร้อมอุปกรณ์ GM Shining Starlight: Shining Starlight ความเสียหายที่อาสึนะทำกับเป้าหมายที่ช้ากว่าเธอจะเพิ่มขึ้น#C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nใน 5 รอบแรกของการต่อสู้ หลังจากฮีโร่ทั้งหมดของเราทำการกระทำแล้ว อาสึนะ Shining Star สามารถมีเทิร์นเพิ่มอีกหนึ่งเทิร์น;\nหัวหน้าปีศาจ: เพื่อนปีศาจทั้งหมดจะได้รับการเพิ่มขึ้น 30% และละเลยการป้องกันสองชั้น; หลังจากกระทำ เธอจะเชิญเพื่อนปีศาจอีกคนแบบสุ่มให้โจมตีด้วยการโจมตีปกติ.',
		zawakeEffectDesc_in = 'Asuna menerima kekuatan Dewa Pencipta dengan peralatan GM Shining Starlight: Shining Starlight Damage yang Asuna berikan kepada target yang lebih lambat darinya meningkat sebesar #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nDalam 5 putaran pertama pertempuran, setelah semua pahlawan kita bertindak, Shining Star Asuna sendiri dapat memiliki giliran tambahan;\nPemimpin Iblis: Semua sekutu iblis yang ramah mendapatkan peningkatan 30% dan mengabaikan pertahanan ganda; setelah bertindak, dia mengundang sekutu iblis acak lain untuk menyerang dengan serangan normal.',
		zawakeEffectDesc_ph = 'Nakukuha ni Asuna ang kapangyarihan ng Diyos ng Paglikha gamit ang kagamitan ng GM Shining Starlight: Shining Starlight Tumataas ang damage ni Asuna sa mga target na mas mabagal sa kanya ng #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nSa unang 5 rounds ng laban, matapos kumilos ang lahat ng mga bayani natin, si Shining Star Asuna mismo ay maaaring magkaroon ng dagdag na turn;\nDemon Leader: Lahat ng mga kaibigang demon ay tumatanggap ng 30% dagdag at nilalampasan ang double defense; pagkatapos kumilos, iniimbitahan niya ang isa pang random na kaibigan na demon na umatake gamit ang normal na atake.',
		zawakeEffectDesc_ma = 'Asuna menerima kuasa Tuhan Pencipta dengan peralatan GM Shining Starlight: Shining Starlight Kerosakan yang Asuna berikan kepada sasaran yang lebih perlahan daripadanya meningkat sebanyak #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nDalam 5 pusingan pertama pertempuran, selepas semua wira kita bertindak, Shining Star Asuna sendiri boleh mendapat giliran tambahan;\nKetua Syaitan: Semua sekutu syaitan yang mesra mendapat peningkatan 30% dan mengabaikan pertahanan berganda; selepas bertindak, dia menjemput sekutu syaitan rawak lain untuk menyerang dengan serangan biasa.',
		zawakeEffectDesc_vn = 'Asuna nhận được quyền năng của Thần Sáng tạo với trang bị GM Shining Starlight: Shining Starlight Sát thương của Asuna lên các mục tiêu chậm hơn cô được tăng lên#C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nTrong 5 vòng đầu tiên của trận chiến, sau khi tất cả các anh hùng của chúng ta đã hành động, Bản thân Shining Star Asuna có thể có thêm một lượt mới;\nQuỷ dữ Thủ lĩnh: Tất cả đồng đội quỷ thân thiện đều tăng 30% và bỏ qua phòng thủ kép; sau khi hành động, cô ấy mời một đồng đội quỷ ngẫu nhiên khác tấn công bằng đòn đánh thường.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'During the first 5 turns of battle, before the start of each major turn, if Shining Star Asuna is the first to act on our side, after all our heroes have completed their actions, Shining Star Asuna can gain an additional turn\n#F20#\n#F40##C0x5c9970#→During the first 5 turns of battle, after all our heroes have acted, Shining Star Asuna can gain an additional turn; Demonlord Leader Enhanced: After acting, she will invite a random Demonlord teammate to attack with a normal hit.',
		zawakeSimpleDesc_en = 'During the first 5 turns of battle, before the start of each major turn, if Shining Star Asuna is the first to act on our side, after all our heroes have completed their actions, Shining Star Asuna can gain an additional turn\n#F20#\n#F40##C0x5c9970#→During the first 5 turns of battle, after all our heroes have acted, Shining Star Asuna can gain an additional turn; Demonlord Leader Enhanced: After acting, she will invite a random Demonlord teammate to attack with a normal hit.',
		zawakeSimpleDesc_th = 'ใน 5 เทิร์นแรกของการต่อสู้ ก่อนเริ่มแต่ละรอบใหญ่ หาก Shining Star Asuna เป็นคนแรกที่ออกคำสั่งฝั่งเรา หลังจากที่ฮีโร่ของเราทั้งหมดดำเนินการเสร็จสิ้น Shining Star Asuna จะสามารถได้รับเทิร์นเพิ่มเติมอีกครั้ง\n#F20#\n#F40##C0x5c9970#→ใน 5 เทิร์นแรกของการต่อสู้ หลังจากที่ฮีโร่ของเราทั้งหมดดำเนินการเสร็จสิ้น Shining Star Asuna จะสามารถได้รับเทิร์นเพิ่มเติมอีกครั้ง; เสริมพลังหัวหน้าปีศาจ: หลังจากเคลื่อนไหว เธอจะเชิญเพื่อนร่วมทีมปีศาจแบบสุ่มมาโจมตีด้วยการโจมตีปกติ',
		zawakeSimpleDesc_in = 'Selama 5 giliran pertama pertempuran, sebelum awal setiap giliran besar, jika Shining Star Asuna adalah yang pertama bertindak di pihak kita, setelah semua pahlawan kita menyelesaikan aksi mereka, Shining Star Asuna bisa mendapatkan giliran tambahan\n#F20#\n#F40##C0x5c9970#→Selama 5 giliran pertama pertempuran, setelah semua pahlawan kita bertindak, Shining Star Asuna bisa mendapatkan giliran tambahan; Peningkatan Pemimpin Demonlord: Setelah bertindak, dia akan mengundang satu rekan Demonlord secara acak untuk menyerang dengan serangan biasa.',
		zawakeSimpleDesc_ph = 'Sa loob ng unang 5 turn ng laban, bago magsimula ang bawat major round, kung si Shining Star Asuna ang unang kikilos sa panig natin, pagkatapos makumpleto ng lahat ng kakampi ang kanilang kilos, maaaring makakuha si Shining Star Asuna ng isa pang turn\n#F20#\n#F40##C0x5c9970#→Sa loob ng unang 5 turn ng laban, pagkatapos makumpleto ng lahat ng kakampi ang kilos nila, maaaring makakuha si Shining Star Asuna ng isa pang turn; Pinalakas ang Lider ng Demonlord: Pagkatapos kumilos, iimbitahan niya ang isang random na kakamping Demonlord na umatake gamit ang normal na atake.',
		zawakeSimpleDesc_ma = 'Dalam 5 pusingan pertama pertempuran, sebelum permulaan setiap pusingan utama, jika Shining Star Asuna adalah yang pertama bertindak di pihak kita, selepas semua wira kita selesai bertindak, Shining Star Asuna boleh menerima satu pusingan tambahan\n#F20#\n#F40##C0x5c9970#→Dalam 5 pusingan pertama pertempuran, selepas semua wira kita bertindak, Shining Star Asuna boleh menerima satu pusingan tambahan; Peningkatan Ketua Demonlord: Selepas bertindak, dia akan menjemput satu rakan sepasukan Demonlord secara rawak untuk menyerang dengan serangan biasa.',
		zawakeSimpleDesc_vn = 'Trong 5 hiệp đầu tiên của trận chiến, trước khi bắt đầu mỗi hiệp lớn, khi Shining Star Asuna ở lệnh hành động đầu tiên của chúng ta, sau khi tất cả các hành động của các anh hùng của chúng ta đã hoàn thành, bản thân Shining Star Asuna có thể nhận thêm một lượt mới\n#F20#\n#F40##C 0x5c9970# → Trong 5 hiệp đầu tiên của trận chiến, sau khi tất cả các anh hùng của chúng ta đã hành động, bản thân Shining Star Asuna có thể nhận thêm một lượt mới; Cường hóa thủ lĩnh Quỷ Thần: Sau khi hành động, cô ấy sẽ mời một đồng đội Quỷ Thần ngẫu nhiên khác tấn công bằng đòn đánh thường.',
