	[7622] = {
		id = 7622,
		skillName_vn = 'EX-Vụn Sao Tung Bay',
		skillName_en = 'EX-Shattered Star Fragments',
		skillName_th = 'EX-เศษดาวที่แตกสลาย',
		skillName_in = 'EX-Pecahan Bintang Hancur',
		skillName_ph = 'EX-Nabasag na Bituin na Pira-piraso',
		skillName_ma = 'EX-Kepingan Bintang Hancur',
		skillName = 'EX-Shattered Star Fragments',
		describe_vn = 'Shining Starlight-Asuna sử dụng Kỹ thuật siêu thần kiếm EX-Stardust Splash để tấn công mục tiêu của kẻ địch theo hàng, gây ra #C0x3D8A99#220% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Sát thương phép #C0x5B545B#, hấp thụ 200 điểm tức giận từ cột mục tiêu và đánh cắp 10% sát thương của kẻ địch tốc độ trong 3 vòng; có 50% khả năng [làm choáng] mục tiêu trong 1 lượt (choáng: hiệu ứng khống chế, không thể di chuyển). Nếu mục tiêu nhanh hơn chính nó sẽ bị choáng 1 lượt.',
		describe_en = 'Shining Starlight-Asuna uses the Super Divine Sword Technique EX-Stardust Splash to attack enemies in a row, dealing 220% Magic Damage plus $(skillLevel*4*24)$ Magic Damage, absorbing 200 anger points from the target\'s column and stealing 10% of the enemy\'s speed damage for 3 turns; has a 50% chance to [stun] the target for 1 turn (stun: control effect, unable to move). If the target is faster than itself, it will be stunned for 1 turn.',
		describe_th = 'Shining Starlight-Asuna ใช้เทคนิคดาบเทพสุดยอด EX-Stardust Splash โจมตีเป้าหมายของศัตรูเป็นแถว ก่อให้เกิดความเสียหายเวทมนตร์ 220% บวก $(skillLevel*4*24)$ ความเสียหายเวทมนตร์ ดูดซับความโกรธ 200 จุดจากแถวเป้าหมาย และขโมย 10% ความเสียหายความเร็วของศัตรูเป็นเวลา 3 รอบ มีโอกาส 50% ที่จะ [ทำให้งง] เป้าหมายเป็นเวลา 1 รอบ (งง: เอฟเฟกต์ควบคุม ไม่สามารถเคลื่อนที่ได้) หากเป้าหมายเร็วกว่า จะถูกงงเป็นเวลา 1 รอบ',
		describe_in = 'Shining Starlight-Asuna menggunakan Teknik Pedang Ilahi Super EX-Stardust Splash untuk menyerang target musuh secara baris, menyebabkan 220% Kerusakan Sihir ditambah $(skillLevel*4*24)$ Kerusakan Sihir, menyerap 200 poin amarah dari kolom target dan mencuri 10% kerusakan kecepatan musuh selama 3 giliran; memiliki peluang 50% untuk [membuat bingung] target selama 1 giliran (bingung: efek kontrol, tidak bisa bergerak). Jika target lebih cepat dari dirinya sendiri, akan dibuat bingung selama 1 giliran.',
		describe_ph = 'Ginagamit ni Shining Starlight-Asuna ang Super Divine Sword Technique EX-Stardust Splash upang atakihin ang mga target ng kalaban sa isang hanay, na nagdudulot ng 220% Magic Damage dagdag pa ang $(skillLevel*4*24)$ Magic Damage, sumisipsip ng 200 na puntos ng galit mula sa column ng target at nagnanakaw ng 10% ng bilis na pinsala ng kalaban sa loob ng 3 round; may 50% na tsansa na [mastun] ang target sa loob ng 1 round (stun: kontrol na epekto, hindi makagalaw). Kung ang target ay mas mabilis kaysa sa sarili nito, ito ay mastun ng 1 round.',
		describe_ma = 'Shining Starlight-Asuna menggunakan Teknik Pedang Ilahi Super EX-Stardust Splash untuk menyerang sasaran musuh mengikut barisan, menyebabkan 220% Kerosakan Sihir ditambah $(skillLevel*4*24)$ Kerosakan Sihir, menyerap 200 mata kemarahan dari lajur sasaran dan mencuri 10% kerosakan kelajuan musuh selama 3 pusingan; mempunyai 50% kemungkinan untuk [membuat bingung] sasaran selama 1 pusingan (bingung: kesan kawalan, tidak dapat bergerak). Jika sasaran lebih pantas daripada dirinya sendiri, akan bingung selama 1 pusingan.',
		describe = 'Shining Starlight-Asuna uses the Super Divine Sword Technique EX-Stardust Splash to attack enemies in a row, dealing 220% Magic Damage plus $(skillLevel*4*24)$ Magic Damage, absorbing 200 anger points from the target\'s column and stealing 10% of the enemy\'s speed damage for 3 turns; has a 50% chance to [stun] the target for 1 turn (stun: control effect, unable to move). If the target is faster than itself, it will be stunned for 1 turn.',
		zawakeEffect = __data_t__zawakeEffect[7622],
		-- {79002}
		zawakeEffectDesc = 'Shining Starlight-Asuna uses a super punch to strike enemy targets consecutively, dealing #C0xF13B54# magic damage #C0x3D8A99#160% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0x5B545B#, absorbing 200 anger points and 20% of the target\'s Magic Damage for 2 rounds and stealing 10% of the enemy\'s speed, lasting for 3 turns; has a 50% chance to <stun> the target for 1 turn (stun: control effect, unable to move). If the target is faster than itself, it will be stunned for 1 turn.',
		zawakeEffectDesc_en = 'Shining Starlight-Asuna uses a super punch to strike enemy targets consecutively, dealing #C0xF13B54# magic damage #C0x3D8A99#160% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0x5B545B#, absorbing 200 anger points and 20% of the target\'s Magic Damage for 2 rounds and stealing 10% of the enemy\'s speed, lasting for 3 turns; has a 50% chance to <stun> the target for 1 turn (stun: control effect, unable to move). If the target is faster than itself, it will be stunned for 1 turn.',
		zawakeEffectDesc_th = 'Shining Starlight-Asuna ใช้หมัดพิเศษโจมตีเป้าหมายของศัตรูอย่างต่อเนื่อง สร้างความเสียหายเวทมนตร์ #C0xF13B54# #C0x3D8A99#160% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$#C0x5B545B# ดูดซับความโกรธ 200 คะแนนและ 20% ความเสียหายเวทมนตร์ของเป้าหมายเป็นเวลา 2 รอบ และขโมยความเร็ว 10% ของศัตรู เป็นระยะเวลา 3 เทิร์น; มีโอกาส 50% ที่จะ <ทำให้มึนงง> เป้าหมายเป็นเวลา 1 เทิร์น (มึนงง: ผลควบคุม, ไม่สามารถเคลื่อนที่ได้) ถ้าเป้าหมายเร็วกว่า จะถูกมึนงง 1 เทิร์น',
		zawakeEffectDesc_in = 'Shining Starlight-Asuna menggunakan pukulan super untuk menyerang target musuh secara beruntun, memberikan #C0xF13B54# kerusakan sihir #C0x3D8A99#160% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0x5B545B#, menyerap 200 poin kemarahan dan 20% Kerusakan Sihir dari target selama 2 giliran dan mencuri 10% kecepatan musuh, berlangsung selama 3 putaran; memiliki 50% peluang untuk <membuat stun> target selama 1 giliran (stun: efek kontrol, tidak bisa bergerak). Jika target lebih cepat dari dirinya sendiri akan terkena stun selama 1 giliran.',
		zawakeEffectDesc_ph = 'Shining Starlight-Asuna ay gumagamit ng super na suntok upang sunud-sunod na atakihin ang mga target ng kaaway, nagdudulot ng #C0xF13B54# magic damage #C0x3D8A99#160% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0x5B545B#, sumisipsip ng 200 na puntos ng galit at 20% ng Magic Damage ng target sa loob ng 2 mga round at nananakaw ng 10% ng bilis ng kalaban, tumatagal ng 3 mga turn; may 50% tsansa na <ma-stun> ang target sa loob ng 1 turn (stun: control effect, hindi makagalaw). Kung mas mabilis ang target kaysa sa sarili nito, ito ay ma-stun ng 1 turn.',
		zawakeEffectDesc_ma = 'Shining Starlight-Asuna menggunakan pukulan super untuk menyerang sasaran musuh secara berturutan, memberikan #C0xF13B54# kerosakan sihir #C0x3D8A99#160% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0x5B545B#, menyerap 200 mata kemarahan dan 20% Kerosakan Sihir sasaran selama 2 pusingan dan mencuri 10% kelajuan musuh, berlangsung selama 3 pusingan; mempunyai 50% peluang untuk <menghentak> sasaran selama 1 pusingan (hentak: kesan kawalan, tidak boleh bergerak). Sekiranya sasaran lebih pantas daripada dirinya, ia akan dihentak selama 1 pusingan.',
		zawakeEffectDesc_vn = 'Shining Starlight-Asuna dùng siêu cú đấm tấn công liên tiếp các mục tiêu của kẻ địch, gây #C0xF13B54# sát thương phép #C0x3D8A99#160% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0x 5B545B#, hấp thụ 200 điểm tức giận và 20% Sát Thương Phép Thuật của mục tiêu trong 2 hiệp và đánh cắp 10% tốc độ của kẻ địch, kéo dài trong 3 lượt; có 50% khả năng <làm choáng> mục tiêu trong 1 lượt (choáng: hiệu ứng khống chế, không thể di chuyển). Nếu mục tiêu nhanh hơn chính nó sẽ bị choáng 1 lượt.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Absorb 200 rage points from the target row\n#F20# \n#F40##C0x5c9970#→Absorb 200 rage points from the target and 20% Magic Attack for 2 turns',
		zawakeSimpleDesc_en = 'Absorb 200 rage points from the target row\n#F20# \n#F40##C0x5c9970#→Absorb 200 rage points from the target and 20% Magic Attack for 2 turns',
		zawakeSimpleDesc_th = 'ดูดซับ 200 แต้มโกรธจากแถวเป้าหมาย\n#F20# \n#F40##C0x5c9970#→ดูดซับ 200 แต้มโกรธจากเป้าหมายและ 20% พลังเวทโจมตี เป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Menyerap 200 poin rage dari baris target\n#F20# \n#F40##C0x5c9970#→Menyerap 200 poin rage dari target dan 20% Serangan Sihir selama 2 giliran',
		zawakeSimpleDesc_ph = 'Sumipsip ng 200 rage points mula sa row ng target\n#F20# \n#F40##C0x5c9970#→Sumipsip ng 200 rage points mula sa target at 20% Magic Attack sa loob ng 2 turn',
		zawakeSimpleDesc_ma = 'Serap 200 mata kemarahan dari barisan sasaran\n#F20# \n#F40##C0x5c9970#→Serap 200 mata kemarahan dari sasaran dan 20% Serangan Sihir selama 2 pusingan',
		zawakeSimpleDesc_vn = 'Hấp thụ 200 điểm thịnh nộ từ hàng mục tiêu\n#F20# \n#F40##C0x5c9970#→Hút 200 điểm thịnh nộ từ mục tiêu và 20% sức tấn Công Phép thuật trong 2 lượt',
		upLvDesc = 'Fixed damage +96',
