	[7623] = {
		id = 7623,
		skillName_vn = 'EX-Sao Xung Kích',
		skillName_en = 'EX-Assault Star',
		skillName_th = 'EX-ดาวจู่โจม',
		skillName_in = 'EX-Bintang Serangan',
		skillName_ph = 'EX-Assault Star',
		skillName_ma = 'EX-Bintang Serangan',
		skillName = 'EX-Assault Star',
		describe_vn = 'Shining Starlight-Asuna giải phóng sức mạnh của các vị thần và sử dụng Kỹ thuật kiếm siêu thần EX-Star Impact để tấn công một mục tiêu kẻ thù, gây ra #C0x3D8A99#680% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$ của #C0xF13B54# phép thuật. Sát thương phép #C0x5B545B#, cho phép bản thân nhận được một tấm chắn chớp nhoáng trong 2 lượt (có thể hấp thụ 30% sát thương do chiêu thức đặc biệt này gây ra). Trong thời gian lá chắn chớp nhoáng, khả năng chống chịu các tác động tiêu cực của bản thân tăng thêm 60%. Khi tấm chắn ánh sáng bị vỡ sẽ gây sát thương bằng máu của tấm chắn ánh sáng cho mục tiêu (sát thương này có thể gây ra đòn chí mạng)',
		describe_en = 'Shining Starlight-Asuna unleashes the power of the gods and uses the EX-Star Impact divine sword technique to attack an enemy target, dealing #C0x3D8A99#680% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$ of #C0xF13B54# magic damage. The magic damage #C0x5B545B# grants a brief shield for 2 turns (can absorb 30% of the damage caused by this special skill). While the shining shield is active, the user\'s resistance to negative effects is increased by 60%. When the shining shield breaks, it deals damage equal to the shield\'s HP to the target (this damage can cause a critical hit).',
		describe_th = 'Shining Starlight-Asuna ปลดปล่อยพลังของเทพเจ้าและใช้เทคนิคดาบ EX-Star Impact เพื่อโจมตีเป้าหมายศัตรูที่หนึ่ง สร้างความเสียหายเวท #C0x3D8A99#680%#C0x5B545B#+$(skillLevel*4*90)$ ของเวทมนตร์ #C0xF13B54# ความเสียหายเวท #C0x5B545B# มอบโล่ชั่วคราวเป็นเวลา 2 เทิร์น (สามารถดูดซับความเสียหาย 30% ที่เกิดจากทักษะพิเศษนี้) ขณะที่โล่ชั้นนำนี้ยังอยู่ ความทนทานต่อผลกระทบด้านลบของตัวเองจะเพิ่มขึ้น 60% เมื่อโล่แสงถูกทำลาย จะสร้างความเสียหายเท่ากับพลังชีวิตของโล่ให้กับเป้าหมาย (ความเสียหายนั้นสามารถสร้างคริติคอลได้)',
		describe_in = 'Shining Starlight-Asuna melepaskan kekuatan para dewa dan menggunakan Teknik Pedang Ilahi EX-Star Impact untuk menyerang satu target musuh, memberikan #C0x3D8A99#680% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*90)$ dari #C0xF13B54# kerusakan sihir. Kerusakan sihir #C0x5B545B# memberikan perisai kilat selama 2 giliran (dapat menyerap 30% kerusakan yang disebabkan oleh kemampuan khusus ini). Selama perisai kilat aktif, ketahanan terhadap efek negatif meningkat sebesar 60%. Ketika perisai cahaya hancur, akan memberikan kerusakan berdasarkan HP perisai kepada target (kerusakan ini dapat menghasilkan serangan kritis).',
		describe_ph = 'Shining Starlight-Asuna ay nagpapalaya ng kapangyarihan ng mga diyos at gumagamit ng EX-Star Impact na teknik sa divine sword upang atakihin ang isang target na kaaway, nagdudulot ng #C0x3D8A99#680% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$ mula sa #C0xF13B54# magic damage. Ang magic damage #C0x5B545B# ay nagbibigay ng isang pansamantalang shield sa loob ng 2 turn (kayang sumipsip ng 30% ng damage na dulot ng espesyal na skill na ito). Habang aktibo ang shining shield, tumataas ng 60% ang resistensya sa negative effects ng sarili. Kapag nasira ang shining shield, magdudulot ito ng damage na katumbas ng HP ng shield sa target (ang damage na ito ay maaaring magdulot ng critical hit).',
		describe_ma = 'Shining Starlight-Asuna membebaskan kuasa para dewa dan menggunakan Teknik Pedang Ilahi EX-Star Impact untuk menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#680% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*90)$ dari #C0xF13B54# kerosakan sihir. Kerosakan sihir #C0x5B545B# membenarkan diri menerima perisai kilat selama 2 giliran (boleh menyerap 30% kerosakan disebabkan oleh kemahiran khas ini). Semasa perisai kilat aktif, ketahanan terhadap kesan negatif meningkat sebanyak 60%. Apabila perisai cahaya pecah, ia menyebabkan kerosakan berdasarkan nyawa perisai kepada sasaran (kerosakan ini boleh menyebabkan serangan kritikal).',
		describe = 'Shining Starlight-Asuna unleashes the power of the gods and uses the EX-Star Impact divine sword technique to attack an enemy target, dealing #C0x3D8A99#680% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$ of #C0xF13B54# magic damage. The magic damage #C0x5B545B# grants a brief shield for 2 turns (can absorb 30% of the damage caused by this special skill). While the shining shield is active, the user\'s resistance to negative effects is increased by 60%. When the shining shield breaks, it deals damage equal to the shield\'s HP to the target (this damage can cause a critical hit).',
		simDesc_vn = 'Ánh sao tỏa sáng: Asuna giải phóng sức mạnh của các vị thần và sử dụng Kỹ thuật siêu thần kiếm EX: Star Impact để tấn công một mục tiêu kẻ thù và nhận cho mình một lá chắn chớp nhoáng.',
		simDesc_en = 'Shining Star: Asuna unleashes the power of the gods and uses the Super Divine Sword Technique EX: Star Impact to attack an enemy target and gains a flashing shield.',
		simDesc_th = 'ดาวส่องสว่าง: อาสึนะปลดปล่อยพลังของเทพเจ้าและใช้เทคนิคดาบเทพ EX: Star Impact โจมตีเป้าหมายศัตรูและได้รับโล่ที่สว่างวาบ',
		simDesc_in = 'Bintang Bersinar: Asuna melepaskan kekuatan para dewa dan menggunakan Teknik Pedang Super Dewa EX: Star Impact untuk menyerang target musuh dan mendapatkan perisai berkilauan.',
		simDesc_ph = 'Nagniningning na Bituin: Pinakawalan ni Asuna ang kapangyarihan ng mga diyos at ginamit ang Super Divine Sword Technique EX: Star Impact upang atakihin ang isang kaaway na target at nakakakuha ng isang kumikislap na shield.',
		simDesc_ma = 'Bintang Bersinar: Asuna melepaskan kuasa para dewa dan menggunakan Teknik Pedang Super Dewa EX: Star Impact untuk menyerang sasaran musuh dan memperoleh perisai yang berkelip-kelip.',
		simDesc = 'Shining Star: Asuna unleashes the power of the gods and uses the Super Divine Sword Technique EX: Star Impact to attack an enemy target and gains a flashing shield.',
		starEffect = __data_t__starEffect[7623],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Đòn tấn công này kích hoạt thêm Sức mạnh Sáng thế: Thêm một lượng Lá chắn Ánh sáng tương đương cho hai đồng đội hệ Ma Thần ngẫu nhiên (không gây sát thương khi phá khiên), và ngay lập tức khiến tất cả đồng đội hệ Ma Thần của phe ta tấn công thêm một lần vào đối phương (nếu đầy nộ có thể dùng kỹ năng tất sát).',
		starEffectDesc = 'Additional Effect: This attack triggers the Power of Genesis: Adds an equivalent amount of Light Shield to two random Demon-type allies (does not deal damage when breaking the shield), and immediately causes all Demon-type allies on our team to attack the enemy one more time (if full rage, can use the fatal skill).',
		starEffectDesc_en = 'Additional Effect: This attack triggers the Power of Genesis: Adds an equivalent amount of Light Shield to two random Demon-type allies (does not deal damage when breaking the shield), and immediately causes all Demon-type allies on our team to attack the enemy one more time (if full rage, can use the fatal skill).',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: การโจมตีนี้เปิดใช้งานพลังแห่งกำเนิด: เพิ่มเกราะแสงในปริมาณเท่ากันให้กับเพื่อนร่วมทีมสายปีศาจสองคนแบบสุ่ม (ไม่สร้างความเสียหายเมื่อทำลายเกราะ) และทันทีทำให้เพื่อนร่วมทีมสายปีศาจทุกคนของฝ่ายเราช่วยโจมตีศัตรูอีกครั้งหนึ่ง (ถ้าพลังโกรธเต็ม สามารถใช้ทักษะสังหารได้)',
		starEffectDesc_in = 'Efek Tambahan: Serangan ini mengaktifkan Kekuatan Penciptaan: Menambahkan jumlah Perisai Cahaya yang setara ke dua rekan tim tipe Iblis secara acak (tidak menyebabkan kerusakan saat memecahkan perisai), dan segera membuat semua rekan tim tipe Iblis di pihak kita menyerang musuh satu kali lagi (jika penuh kemarahan bisa menggunakan skill pembunuh).',
		starEffectDesc_ph = 'Karagdagang Epekto: Pinapagana nito ang Kapangyarihan ng Genesis: Nagdaragdag ng katumbas na halaga ng Liwanag na Kalasag sa dalawang random na kasama sa koponang Demon-type (hindi nakakasakit kapag winasak ang kalasag), at agad na pinapagawa ang lahat ng Demon-type na kasama sa aming koponan na umatake ng isang beses pa sa kalaban (kung puno na ang galit ay maaaring gamitin ang fatal na kakayahan).',
		starEffectDesc_ma = 'Kesan Tambahan: Serangan ini mengaktifkan Kuasa Genesis: Menambah jumlah Perisai Cahaya yang setara kepada dua rakan sepasukan jenis Iblis secara rawak (tidak menyebabkan kerosakan apabila perisai dipecahkan), dan serta-merta menyebabkan semua rakan sepasukan jenis Iblis pihak kita menyerang musuh sekali lagi (jika penuh kemarahan boleh menggunakan kemahiran pembunuh).',
		zawakeEffect = __data_t__zawakeEffect[7623],
		-- {79003}
		zawakeEffectDesc = 'Shining Starlight-Asuna unleashes the power of the gods and uses the EX-Star Impact super divine sword technique to attack an enemy target, dealing #C0x3D8A99#680% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Magical Damage#C0x5B545B#. Additionally, it increases the critical hit rate and critical damage of this attack by 20% and 40%, respectively, while creating a flashing shield for 2 turns (can absorb 50% of the damage from this special attack). While using the flashing shield, it increases negative effect resistance by 60% and control immunity rate by 40%. When the light shield breaks, it deals damage equal to the shield\'s health to the target (this damage can cause a critical hit).',
		zawakeEffectDesc_en = 'Shining Starlight-Asuna unleashes the power of the gods and uses the EX-Star Impact super divine sword technique to attack an enemy target, dealing #C0x3D8A99#680% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Magical Damage#C0x5B545B#. Additionally, it increases the critical hit rate and critical damage of this attack by 20% and 40%, respectively, while creating a flashing shield for 2 turns (can absorb 50% of the damage from this special attack). While using the flashing shield, it increases negative effect resistance by 60% and control immunity rate by 40%. When the light shield breaks, it deals damage equal to the shield\'s health to the target (this damage can cause a critical hit).',
		zawakeEffectDesc_th = 'Shining Starlight-Asuna ปลดปล่อยพลังของเทพเจ้าและใช้เทคนิคดาบเทพ EX-Star Impact โจมตีเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#680%#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# นอกจากนี้ ยังเพิ่มอัตราการตีคริติคอลและความเสียหายคริติคอลของการโจมตีนี้ขึ้นอีก 20% และ 40% ตามลำดับ พร้อมทั้งสร้างโล่แฟลชให้กับตัวเองเป็นเวลา 2 รอบ (สามารถดูดซับความเสียหาย 50% จากการโจมตีพิเศษนี้) ขณะที่ใช้โล่แฟลช จะเพิ่มอัตราต้านทานสถานะลบขึ้น 60% และอัตราป้องกันการควบคุม 40% เมื่อโล่แสงถูกทำลาย จะสร้างความเสียหายเท่ากับพลังชีวิตของโล่นั้นสู่เป้าหมาย (ความเสียหายนี้อาจเกิดการตีคริติคอลได้)',
		zawakeEffectDesc_in = 'Shining Starlight-Asuna melepaskan kekuatan para dewa dan menggunakan Teknik Pedang Super Ilahi EX-Star Impact untuk menyerang satu target musuh, memberikan #C0x3D8A99#680% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Kerusakan Magis#C0x5B545B#. Selain itu, meningkatkan tingkat kritis dan kerusakan kritis serangan ini hingga 20% dan 40%, sambil menciptakan perisai kilatan selama 2 giliran (dapat menyerap 50% kerusakan dari serangan khusus ini). Saat menggunakan perisai kilatan, meningkatkan resistensi efek negatif sebesar 60% dan tingkat kebal kontrol sebesar 40%. Ketika perisai cahaya hancur, memberikan kerusakan berdasarkan darah perisai cahaya ke target (kerusakan ini dapat menyebabkan serangan kritis).',
		zawakeEffectDesc_ph = 'Shining Starlight-Asuna ay nagpalaya ng kapangyarihan ng mga diyos at ginamit ang super divine sword technique na EX-Star Impact upang atakihin ang isang kaaway na target, nagdudulot ng #C0x3D8A99#680% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Magical Damage#C0x5B545B#. Bukod dito, pinapataas nito ang critical hit rate at critical damage ng pag-atakeng ito ng 20% at 40%, kasabay ng paglikha ng flashing shield sa loob ng 2 turn (maaaring sumipsip ng 50% ng pinsala mula sa espesyal na atake na ito). Habang gumagamit ng flashing shield, pinapataas nito ang resistance sa negative effects ng 60% at ang control immunity rate ng 40%. Kapag nabasag ang light shield, nagdudulot ito ng pinsala base sa health ng shield sa target (ang pinsalang ito ay maaaring magdulot ng critical hit).',
		zawakeEffectDesc_ma = 'Shining Starlight-Asuna melepaskan kekuatan para dewa dan menggunakan Teknik Pedang Super Ilahi EX-Star Impact untuk menyerang satu sasaran musuh, memberikan #C0x3D8A99#680% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Kerosakan Magik#C0x5B545B#. Selain itu, ia meningkatkan kadar serangan kritikal dan kerosakan kritikal serangan ini sebanyak 20% dan 40%, serta mewujudkan perisai kilatan selama 2 pusingan (boleh menyerap 50% kerosakan dari serangan khas ini). Semasa menggunakan perisai kilatan, ia meningkatkan rintangan kesan negatif sebanyak 60% dan kadar kebal kawalan sebanyak 40%. Apabila perisai cahaya pecah, ia memberikan kerosakan bersamaan dengan darah perisai cahaya kepada sasaran (kerosakan ini boleh menyebabkan serangan kritikal).',
		zawakeEffectDesc_vn = 'Shining Starlight-Asuna giải phóng sức mạnh của các vị thần và sử dụng Kỹ thuật kiếm siêu thần EX-Star Impact để tấn công một mục tiêu kẻ thù, gây ra #C0x3D8A99#680% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, uh Ngoài ra, nó còn tăng tỷ lệ trúng đòn chí mạng và sát thương chí mạng của đòn tấn công này lên thêm 20% và 40%, đồng thời tạo cho mình một lá chắn chớp nhoáng trong 2 lượt (có thể hấp thụ 50% sát thương của đòn tấn công đặc biệt này). Trong khi sử dụng khiên chắn flash, nó tăng tỷ lệ kháng hiệu ứng tiêu cực lên 60% và tỷ lệ miễn nhiễm kiểm soát lên 40%. Khi tấm chắn ánh sáng bị vỡ sẽ gây sát thương bằng máu của tấm chắn ánh sáng cho mục tiêu (sát thương này có thể gây ra một đòn chí mạng).',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Additionally, this attack\'s critical rate and critical damage are increased by 20% and 40% respectively; the damage absorption coefficient of the flash shield increases by 20%, and self-control immunity rate increases by 40% during the light shield duration.',
		zawakeSimpleDesc_en = '#C0x5c9970#Additionally, this attack\'s critical rate and critical damage are increased by 20% and 40% respectively; the damage absorption coefficient of the flash shield increases by 20%, and self-control immunity rate increases by 40% during the light shield duration.',
		zawakeSimpleDesc_th = '#C0x5c9970#นอกจากนี้ อัตราคริติคอลและความเสียหายคริติคอลของการโจมตีนี้เพิ่มขึ้น 20% และ 40% ตามลำดับ; ค่าการดูดซับความเสียหายของโล่แฟลชเพิ่มขึ้น 20% และอัตราการต้านทานควบคุมตัวเองเพิ่มขึ้น 40% ขณะโล่แสงทำงาน',
		zawakeSimpleDesc_in = '#C0x5c9970#Selain itu, peluang kritis dan damage kritis dari serangan ini meningkat masing-masing 20% dan 40%; koefisien penyerapan damage dari perisai flash meningkat 20% dan tingkat kekebalan terhadap kontrol diri meningkat 40% selama durasi perisai cahaya.',
		zawakeSimpleDesc_ph = '#C0x5c9970#Bukod pa rito, ang crit rate at crit damage ng atakeng ito ay tumataas ng 20% at 40%; ang absorption rate ng flash shield ay tumataas ng 20% at self-control immunity rate ay tumataas ng 40% habang aktibo ang light shield.',
		zawakeSimpleDesc_ma = '#C0x5c9970#Selain itu, kadar kritikal dan kerosakan kritikal serangan ini masing-masing meningkat sebanyak 20% dan 40%; pekali penyerapan kerosakan perisai kilat meningkat 20% dan kadar imuniti kawalan kendiri meningkat 40% semasa tempoh perisai cahaya.',
		zawakeSimpleDesc_vn = '#C0x5c9970#Ngoài ra, tỷ lệ chí mạng và sát thương chí mạng của đòn tấn công này tăng lần lượt là 20% và 40%; hệ số hấp thụ sát thương của lá chắn flash tăng 20% ​​và tỷ lệ miễn nhiễm tự kiểm soát tăng 40% trong thời gian lá chắn ánh sáng.',
		upLvDesc = 'Fixed damage +360',
		upLvDesc_en = 'Fixed damage +360',
