	[7626] = {
		id = 7626,
		skillName_vn = 'EX-Ánh Sáng Lấp Lánh',
		skillName_en = 'EX-Shining Light',
		skillName_th = 'EX-แสงสว่างระยิบระยับ',
		skillName_in = 'EX-Cahaya Berkilauan',
		skillName_ph = 'EX-Kumikinang na Liwanag',
		skillName_ma = 'EX-Cahaya Berkilau',
		skillName = 'EX-Shining Light',
		describe_vn = 'Asuna có được quyền năng của Thần Sáng tạo với trang bị GM Shining Starlight: Shining Starlight. Sát thương của Asuna lên các mục tiêu chậm hơn mình tăng thêm #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B #\nTrong 5 hiệp đầu tiên của trận chiến, trước khi bắt đầu mỗi hiệp lớn, khi Shining Star Asuna ở lệnh hành động đầu tiên của chúng ta, sau tất cả các hành động của chúng ta anh hùng, bản thân Shining Star Asuna có thể nhận thêm một vòng mới\nSức mạnh sáng tạo: Tất cả đồng đội quỷ thân thiện đều tăng 30% và bỏ qua phòng thủ kép',
		describe_en = 'Asuna possesses the power of the God of Creation equipped with the GM Shining Starlight: Shining Starlight. Asuna\'s damage to targets slower than herself increases by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B #\n During the first 5 rounds of the battle, before the start of each major round, when Shining Star Asuna is our first act in the order, after all our heroes have acted, Shining Star Asuna can gain an additional turn \n Creative Power: All friendly demon allies increase their stats by 30% and ignore dual defense.',
		describe_th = 'อาสึนะได้รับพลังของพระเจ้าผู้สร้าง พร้อมอุปกรณ์ GM Shining Starlight: Shining Starlight. ความเสียหายของอาสึนะต่อตัวละครที่ช้ากว่าเธอเพิ่มขึ้น #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B #\n ใน 5 รอบแรกของการต่อสู้ ก่อนเริ่มแต่ละรอบใหญ่ เมื่อ Shining Star Asuna เป็นฝ่ายทำการโจมตีเป็นคนแรกในทีม หลังจากฮีโร่ของเราทุกคนทำการแล้ว Shining Star Asuna จะได้รับเทิร์นเพิ่ม \n พลังสร้างสรรค์: เพื่อนร่วมทีมปีศาจทั้งหมดเพิ่มพลังขึ้น 30% และละเลยการป้องกันสองชั้น',
		describe_in = 'Asuna memiliki kekuatan Dewa Pencipta dengan perlengkapan GM Shining Starlight: Shining Starlight. Damage Asuna terhadap target yang lebih lambat darinya meningkat sebesar #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B #\n Dalam 5 ronde pertama pertarungan, sebelum memulai setiap ronde besar, ketika Shining Star Asuna menjadi aksi pertama kita, setelah semua aksi pahlawan kita selesai, Shining Star Asuna dapat memperoleh giliran tambahan \n Kekuatan Kreatif: Semua sekutu iblis yang bersahabat mendapatkan peningkatan 30% dan mengabaikan pertahanan ganda.',
		describe_ph = 'Nakuha ni Asuna ang kapangyarihan ng Diyos ng Paglikha gamit ang kagamitan ng GM Shining Starlight: Shining Starlight. Nadadagdagan ang pinsala ni Asuna sa mga target na mas mabagal sa kanya ng #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B #\n Sa unang 5 rounds ng laban, bago magsimula ang bawat malaking round, kapag si Shining Star Asuna ay ang unang kumilos natin, pagkatapos ng lahat ng mga aksyon ng ating mga bayani, makakakuha si Shining Star Asuna ng karagdagang turn \n Kapangyarihan ng Paglikha: Lahat ng kaibigang demonyo ay tumataas ng 30% at nilalampasan ang doble depensa.',
		describe_ma = 'Asuna memiliki kuasa Dewa Pencipta dengan peralatan GM Shining Starlight: Shining Starlight. Kerosakan Asuna ke sasaran yang lebih lambat daripadanya bertambah sebanyak #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B #\n Dalam 5 pusingan pertama pertempuran, sebelum memulakan setiap pusingan besar, apabila Shining Star Asuna menjadi tindakan pertama kita, selepas semua tindakan wira kita, Shining Star Asuna boleh mendapat satu pusingan tambahan \n Kuasa Kreatif: Semua rakan seteru iblis meningkat 30% dan mengabaikan pertahanan berganda.',
		describe = 'Asuna possesses the power of the God of Creation equipped with the GM Shining Starlight: Shining Starlight. Asuna\'s damage to targets slower than herself increases by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B #\n During the first 5 rounds of the battle, before the start of each major round, when Shining Star Asuna is our first act in the order, after all our heroes have acted, Shining Star Asuna can gain an additional turn \n Creative Power: All friendly demon allies increase their stats by 30% and ignore dual defense.',
		starEffect = __data_t__starEffect[7626],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng thêm: Tấn công mục tiêu chậm hơn bản thân sẽ bỏ qua 30% kháng phép và 20% giảm sát thương của mục tiêu.',
		starEffectDesc = 'Additional Effect: Attacking a target slower than yourself will ignore 30% of the target\'s magic resistance and 20% of the target\'s damage reduction.',
		starEffectDesc_en = 'Additional Effect: Attacking a target slower than yourself will ignore 30% of the target\'s magic resistance and 20% of the target\'s damage reduction.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: การโจมตีเป้าหมายที่ช้ากว่าตัวเองจะละเลยการต้านทานเวทมนตร์ของเป้าหมาย 30% และการลดความเสียหายของเป้าหมาย 20%',
		starEffectDesc_in = 'Efek Tambahan: Menyerang target yang lebih lambat dari diri sendiri akan mengabaikan 30% resistensi sihir target dan 20% pengurangan damage target.',
		starEffectDesc_ph = 'Karagdagang Epekto: Ang pag-atake sa target na mas mabagal kaysa sa sarili ay magpapawalang-bisa ng 30% ng magic resistance at 20% ng damage reduction ng target.',
		starEffectDesc_ma = 'Kesan Tambahan: Menyerang sasaran yang lebih perlahan daripada diri sendiri akan mengabaikan 30% rintangan sihir sasaran dan 20% pengurangan kerosakan sasaran.',
		zawakeEffect = __data_t__zawakeEffect[7626],
		-- {79004}
		zawakeEffectDesc = 'Asuna receives the power of the God of Creation with the GM Shining Starlight equipment: Shining Starlight The damage of Asuna to slower targets is increased by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nIn the first 5 rounds of the battle, after all our heroes have acted, Shining Star Asuna herself can have an additional turn;\nDemon Leader: All friendly demon teammates increase by 30% and ignore double defense; after acting, she invites another random demon teammate to attack with a normal strike.',
		zawakeEffectDesc_en = 'Asuna receives the power of the God of Creation with the GM Shining Starlight equipment: Shining Starlight The damage of Asuna to slower targets is increased by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nIn the first 5 rounds of the battle, after all our heroes have acted, Shining Star Asuna herself can have an additional turn;\nDemon Leader: All friendly demon teammates increase by 30% and ignore double defense; after acting, she invites another random demon teammate to attack with a normal strike.',
		zawakeEffectDesc_th = 'อาสึนะได้รับพลังของพระเจ้าผู้สร้างด้วยอุปกรณ์ GM Shining Starlight: Shining Starlight ความเสียหายของอาสึนะต่อเป้าหมายที่ช้ากว่านั้นเพิ่มขึ้น #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nใน 5 รอบแรกของการต่อสู้ หลังจากฮีโร่ทั้งหมดของเราได้ลงมือแล้ว อาสึนะดวงดาวเจิดจ้าสามารถมีเทิร์นเพิ่มเติมหนึ่งเทิร์น;\nผู้นำปีศาจ: เพื่อนร่วมทีมปีศาจทั้งหมดเพิ่มขึ้น 30% และละเลยการป้องกันสองชั้น; หลังจากลงมือแล้ว เธอให้เพื่อนร่วมทีมปีศาจคนอื่นที่สุ่มมาโจมตีด้วยการโจมตีปกติ',
		zawakeEffectDesc_in = 'Asuna menerima kekuatan Dewa Pencipta dengan perlengkapan GM Shining Starlight: Shining Starlight Damage Asuna terhadap target yang lebih lambat meningkat sebesar #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nDalam 5 putaran pertama pertempuran, setelah semua pahlawan kita bertindak, Shining Star Asuna sendiri dapat memiliki giliran tambahan;\nPemimpin Iblis: Semua rekan setim iblis yang bersahabat meningkat 30% dan mengabaikan pertahanan ganda; setelah bertindak, dia mengundang rekan setim iblis lain secara acak untuk menyerang dengan serangan normal.',
		zawakeEffectDesc_ph = 'Nakakatanggap si Asuna ng kapangyarihan ng Diyos ng Paglikha gamit ang GM Shining Starlight na kagamitan: Shining Starlight Tinutukoy na pinsala ni Asuna sa mga target na mas mabagal sa kaniya ay tumaas ng #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nSa unang 5 rounds ng laban, pagkatapos kumilos ang lahat ng aming mga bayani, si Shining Star Asuna mismo ay maaaring magkaroon ng karagdagang turn;\nPinuno ng Demonyo: Lahat ng kaibigang demonyong kasama ay tumataas ng 30% at nilalampasan ang dobleng depensa; pagkatapos kumilos, siya ay mag-anyaya ng isa pang random na kaibigang demonyo upang umatake gamit ang normal na suntok.',
		zawakeEffectDesc_ma = 'Asuna menerima kuasa Tuhan Pencipta dengan peralatan GM Shining Starlight: Shining Starlight Kerosakan Asuna kepada sasaran yang lebih perlahan meningkat sebanyak #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nDalam 5 pusingan pertama pertempuran, selepas semua wira kami bertindak, Shining Star Asuna sendiri boleh mendapat giliran tambahan;\nKetua Syaitan: Semua rakan sepasukan syaitan mesra meningkat sebanyak 30% dan mengabaikan pertahanan berganda; selepas bertindak, dia menjemput rakan sepasukan syaitan lain secara rawak untuk menyerang dengan serangan biasa.',
		zawakeEffectDesc_vn = 'Asuna nhận được quyền năng của Thần Sáng tạo với trang bị GM Shining Starlight: Shining Starlight Sát thương của Asuna lên các mục tiêu chậm hơn cô được tăng lên#C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ;\nTrong 5 vòng đầu tiên của trận chiến, sau khi tất cả các anh hùng của chúng ta đã hành động, Bản thân Shining Star Asuna có thể có thêm một lượt mới;\nQuỷ dữ Thủ lĩnh: Tất cả đồng đội quỷ thân thiện đều tăng 30% và bỏ qua phòng thủ kép; sau khi hành động, cô ấy mời một đồng đội quỷ ngẫu nhiên khác tấn công bằng đòn đánh thường.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'During the first 5 turns of battle, before the start of each major round, if Shining Star Asuna is the first to act on our side, after all our heroes have completed their actions, Shining Star Asuna can gain an additional turn\n#F20#\n#F40##C0x5c9970#→During the first 5 turns of battle, after all our heroes have acted, Shining Star Asuna can gain an additional turn; Demonlord Leader Enhanced: After acting, she will invite a random Demonlord teammate to attack with a normal hit.',
		zawakeSimpleDesc_en = 'During the first 5 turns of battle, before the start of each major round, if Shining Star Asuna is the first to act on our side, after all our heroes have completed their actions, Shining Star Asuna can gain an additional turn\n#F20#\n#F40##C0x5c9970#→During the first 5 turns of battle, after all our heroes have acted, Shining Star Asuna can gain an additional turn; Demonlord Leader Enhanced: After acting, she will invite a random Demonlord teammate to attack with a normal hit.',
		zawakeSimpleDesc_th = 'ใน 5 เทิร์นแรกของการต่อสู้ ก่อนเริ่มแต่ละรอบใหญ่ หาก Shining Star Asuna เป็นคนแรกที่ออกคำสั่งฝั่งเรา หลังจากที่ฮีโร่ของเราทั้งหมดดำเนินการเสร็จสิ้น Shining Star Asuna จะสามารถได้รับเทิร์นเพิ่มเติมอีกครั้ง\n#F20#\n#F40##C0x5c9970#→ใน 5 เทิร์นแรกของการต่อสู้ หลังจากที่ฮีโร่ของเราทั้งหมดดำเนินการเสร็จสิ้น Shining Star Asuna จะสามารถได้รับเทิร์นเพิ่มเติมอีกครั้ง; เสริมพลังหัวหน้าปีศาจ: หลังจากเคลื่อนไหว เธอจะเชิญเพื่อนร่วมทีมปีศาจแบบสุ่มมาโจมตีด้วยการโจมตีปกติ',
		zawakeSimpleDesc_in = 'Selama 5 giliran pertama pertempuran, sebelum awal setiap giliran besar, jika Shining Star Asuna adalah yang pertama bertindak di pihak kita, setelah semua pahlawan kita menyelesaikan aksinya, Shining Star Asuna bisa mendapatkan giliran tambahan\n#F20#\n#F40##C0x5c9970#→Selama 5 giliran pertama pertempuran, setelah semua pahlawan kita bertindak, Shining Star Asuna bisa mendapatkan giliran tambahan; Peningkatan Pemimpin Demonlord: Setelah bertindak, dia akan mengundang satu rekan Demonlord secara acak untuk menyerang dengan serangan biasa.',
		zawakeSimpleDesc_ph = 'Sa loob ng unang 5 turn ng laban, bago magsimula ang bawat major round, kung si Shining Star Asuna ang unang kikilos sa panig natin, pagkatapos makumpleto ng lahat ng kakampi ang kanilang aksyon, maaaring makakuha si Shining Star Asuna ng isa pang turn\n#F20#\n#F40##C0x5c9970#→Sa loob ng unang 5 turn ng laban, pagkatapos makumpleto ng lahat ng kakampi ang aksyon nila, maaaring makakuha si Shining Star Asuna ng isa pang turn; Pinalakas ang Lider ng Demonlord: Pagkatapos kumilos, iimbitahan niya ang isang random na kakamping Demonlord na umatake gamit ang normal na atake.',
		zawakeSimpleDesc_ma = 'Dalam 5 pusingan pertama pertempuran, sebelum permulaan setiap pusingan besar, jika Shining Star Asuna adalah yang pertama bertindak di pihak kita, selepas semua wira kita selesai bertindak, Shining Star Asuna boleh menerima satu pusingan tambahan\n#F20#\n#F40##C0x5c9970#→Dalam 5 pusingan pertama pertempuran, selepas semua wira kita bertindak, Shining Star Asuna boleh menerima satu pusingan tambahan; Peningkatan Ketua Demonlord: Selepas bertindak, dia akan menjemput satu rakan Demonlord secara rawak untuk menyerang dengan serangan biasa.',
		zawakeSimpleDesc_vn = 'Trong 5 hiệp đầu tiên của trận chiến, trước khi bắt đầu mỗi hiệp lớn, khi Shining Star Asuna ở lệnh hành động đầu tiên của chúng ta, sau khi tất cả các hành động của các anh hùng của chúng ta đã hoàn thành, bản thân Shining Star Asuna có thể nhận thêm một lượt mới\n#F20#\n#F40##C 0x5c9970# → Trong 5 hiệp đầu tiên của trận chiến, sau khi tất cả các anh hùng của chúng ta đã hành động, bản thân Shining Star Asuna có thể nhận thêm một lượt mới; Cường hóa thủ lĩnh Quỷ Thần: Sau khi hành động, cô ấy sẽ mời một đồng đội Quỷ Thần ngẫu nhiên khác tấn công bằng đòn đánh thường.',
