	[7712] = {
		id = 7712,
		skillName_vn = 'Đội hình mũi tên bí mật',
		skillName_en = 'Secret Arrow Team',
		skillName_th = 'ทีมธนูลับ',
		skillName_in = 'Tim Panah Rahasia',
		skillName_ph = 'Sikretong Arrow Team',
		skillName_ma = 'Pasukan Anak Panah Rahsia',
		skillName = 'Secret Arrow Team',
		describe_vn = 'Madoka tập hợp khả năng điều khiển từ xa của mình để triệu tập đội hình các mũi tên bí ẩn bắn phá mục tiêu ở hàng đầu của kẻ thù, gây ra #C0x3D8A99#160% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#sát thương ma thuật#C0x5B545B#, sao chép hiệu ứng buff ngẫu nhiên từ mục tiêu và chuyển hiệu ứng tiêu cực hoặc hiệu ứng kiểm soát ngẫu nhiên của riêng cô ấy tới mục tiêu, kéo dài 2 lượt.',
		describe_en = 'Madoka gathers her remote control abilities to summon a formation of mysterious arrows that bombard the front-line enemy targets, dealing #C0x3D8A99#160% Magical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# magic damage#C0x5B545B#, copies a random buff effect from the target and transfers her own random negative or control effect to the target, lasting 2 turns.',
		describe_th = 'มาดอกะรวบรวมความสามารถควบคุมระยะไกลของเธอเพื่อเรียกทีมลูกศรลึกลับยิงโจมตีเป้าหมายแนวหน้าในศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#160%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# คัดลอกเอฟเฟกต์บัฟแบบสุ่มจากเป้าหมายและส่งต่อเอฟเฟกต์เชิงลบหรือเอฟเฟกต์ควบคุมแบบสุ่มของเธอเองไปยังเป้าหมาย เป็นเวลา 2 ตา',
		describe_in = 'Madoka mengumpulkan kemampuan kendali jaraknya untuk memanggil formasi panah misterius yang membombardir target barisan depan musuh, memberikan #C0x3D8A99#160% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# kerusakan sihir#C0x5B545B#, menyalin efek buff acak dari target dan mentransfer efek negatif atau efek kontrol acak miliknya sendiri ke target, berlangsung selama 2 giliran.',
		describe_ph = 'Pinagsama ni Madoka ang kanyang kakayahang kontrol mula sa malayo upang tawagin ang pormasyong mga misteryosong mga palaso na sumusugod sa mga target sa unahang hanay ng kalaban, na nagdudulot ng #C0x3D8A99#160% Stock Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# nakasihang epekto ng mahika#C0x5B545B#, kinokopya ang random na buff effect mula sa target at inililipat ang kanyang sariling random na negatibo o control effect sa target, tumatagal ng 2 turnos.',
		describe_ma = 'Madoka mengumpulkan kebolehan kawalan jauh miliknya untuk memanggil formasi anak panah misteri yang membedil sasaran barisan hadapan musuh, menyebabkan #C0x3D8A99#160% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# kerosakan sihir#C0x5B545B#, menyalin kesan buff rawak dari sasaran dan memindahkan kesan negatif atau kesan kawalan rawak daripadanya sendiri kepada sasaran, berlangsung selama 2 pusingan.',
		describe = 'Madoka gathers her remote control abilities to summon a formation of mysterious arrows that bombard the front-line enemy targets, dealing #C0x3D8A99#160% Magical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# magic damage#C0x5B545B#, copies a random buff effect from the target and transfers her own random negative or control effect to the target, lasting 2 turns.',
		simDesc_vn = 'Madoka tập hợp khả năng điều khiển từ xa của mình để triệu tập đội hình các mũi tên bí ẩn nhằm bắn phá các mục tiêu ở hàng đầu của kẻ thù.',
		simDesc_en = 'Madoka gathers her remote control abilities to summon a formation of mysterious arrows to bombard the enemy\'s frontline targets.',
		simDesc_th = 'มาดอกะรวบรวมความสามารถควบคุมระยะไกลของเธอเพื่อนำกองทัพลูกธนูลึกลับมาปะทะเป้าหมายแนวหน้าแห่งศัตรู',
		simDesc_in = 'Madoka mengumpulkan kemampuan kendali jarak jauhnya untuk memanggil formasi panah misterius guna menyerang target di garis depan musuh.',
		simDesc_ph = 'Pinagsama ni Madoka ang kanyang kakayahan sa remote control upang tawagin ang porma ng mga misteryosong palaso para bombahin ang mga target sa unahang linya ng kaaway.',
		simDesc_ma = 'Madoka mengumpulkan kebolehan kawalan jauh beliau untuk memanggil barisan anak panah misteri bagi membedil sasaran di barisan hadapan musuh.',
		simDesc = 'Madoka gathers her remote control abilities to summon a formation of mysterious arrows to bombard the enemy\'s frontline targets.',
		zawakeEffect = __data_t__zawakeEffect[7712],
		-- {79002}
		zawakeEffectDesc = 'Madoka gathers her remote control abilities to summon a formation of mysterious arrows assaulting the frontline of enemies, dealing #C0x3D8A99#160% Magical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#magic damage#C0x5B545B#, copying a random buff effect from the target and transferring her own random negative or control effect to the target, lasting 3 turns.',
		zawakeEffectDesc_en = 'Madoka gathers her remote control abilities to summon a formation of mysterious arrows assaulting the frontline of enemies, dealing #C0x3D8A99#160% Magical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#magic damage#C0x5B545B#, copying a random buff effect from the target and transferring her own random negative or control effect to the target, lasting 3 turns.',
		zawakeEffectDesc_th = 'มาดกะรวมพลังควบคุมระยะไกลของเธอเพื่อเรียกกองทัพลูกศรลึกลับโจมตีแถวหน้าของศัตรู สร้าง #C0x3D8A99#160% พลังโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# เลียนแบบเอฟเฟกต์บัฟสุ่มจากเป้าหมายและส่งต่อเอฟเฟกต์ลบหรือเอฟเฟกต์ควบคุมสุ่มของเธอไปยังเป้าหมาย เป็นเวลา 3 เทิร์น',
		zawakeEffectDesc_in = 'Madoka mengumpulkan kemampuan kendali jarak jauhnya untuk memanggil formasi panah misterius yang menyerang barisan depan musuh, menyebabkan #C0x3D8A99#160% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#kerusakan sihir#C0x5B545B#, menyalin efek buff acak dari target dan memindahkan efek negatif atau efek kontrol acak miliknya sendiri ke target, berlangsung selama 3 giliran.',
		zawakeEffectDesc_ph = 'Pinagsama ni Madoka ang kanyang kakayahan sa remote control para tawagin ang hanay ng mga misteryosong palaso na sumasalakay sa unahang linya ng mga kalaban, na nagdudulot ng #C0x3D8A99#160% Pang-magic na Pinsala#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#pinsala mula sa magic#C0x5B545B#, kinokopya ang random buff effect mula sa target at inilipat ang kanyang sariling random na negatibo o control effect sa target, tumatagal ng 3 turn.',
		zawakeEffectDesc_ma = 'Madoka mengumpulkan kebolehan kawalan jauh untuk memanggil formasi anak panah misteri yang menyerang barisan hadapan musuh, menyebabkan #C0x3D8A99#160% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#kerosakan magik#C0x5B545B#, menyalin kesan buff rawak dari sasaran dan memindahkan kesan negatif atau kesan kawalan rawak miliknya ke sasaran, berlangsung selama 3 pusingan.',
		zawakeEffectDesc_vn = 'Madoka tập hợp khả năng điều khiển từ xa của mình để triệu tập đội hình các mũi tên bí ẩn bắn phá mục tiêu ở hàng đầu của kẻ thù, gây ra #C0x3D8A99#160% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#sát thương ma thuật#C0x5B545B#, sao chép hiệu ứng buff ngẫu nhiên từ mục tiêu và chuyển hiệu ứng tiêu cực hoặc hiệu ứng kiểm soát ngẫu nhiên của riêng cô ấy tới mục tiêu, kéo dài 3 hiệp.',
