	[7713] = {
		id = 7713,
		skillName_vn = 'Nguyên lý của vòng tròn',
		skillName_en = 'Principle of the circle',
		skillName_th = 'หลักการของวงกลม',
		skillName_in = 'Prinsip lingkaran',
		skillName_ph = 'Prinsip ng bilog',
		skillName_ma = 'Prinsip bulatan',
		skillName = 'Principle of the circle',
		describe_vn = 'Madoka biến thành một vị thần, kích hoạt nguyên lý vòng tròn và mở ra một giấc mơ có thật và ảo tưởng. Sau đó giấc mơ tan vỡ, tấn công toàn bộ kẻ địch, gây ra #C0x3D8A99#300% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Sát thương phép#C0x5B545B#, khiến mục tiêu có 70% xác suất tiến vào [Ảo ảnh] trong 2 hiệp (Ảo ảnh: hiệu ứng đặc biệt, mục tiêu rơi vào trạng thái im lặng, bối rối, một trong bốn tác dụng ngẫu nhiên là giảm 20% khả năng tấn công kép và giảm 30% khả năng phòng thủ kép)',
		describe_en = 'Madoka transforms into a deity, activates the principle of the circle, and opens a dream that is both real and illusory. Then the dream shatters, attacking all enemies, dealing #C0x3D8A99#300% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#magic damage#C0x5B545B#, causing a 70% chance to enter [Illusion] for 2 turns (Illusion: special effect, target falls into silence, confusion, and one of four random effects: 20% decrease in double attack rate and 30% decrease in double defense rate).',
		describe_th = 'มาดอกะเปลี่ยนร่างเป็นพระเจ้า เปิดใช้หลักการวงกลม และเปิดฝันที่เป็นจริงและภาพลวง หลังจากนั้นความฝันแตกสลาย โจมตีศัตรูทั้งหมด สร้างความเสียหายเวทมนตร์ #C0x3D8A99#300%#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# ทำให้เป้าหมายมีโอกาส 70% ที่จะเข้าสู่ [ภาพลวง] เป็นเวลา 2 ตา (ภาพลวง: เอฟเฟกต์พิเศษ เป้าหมายถูกทำให้เงียบ สับสน และหนึ่งในสี่ผลสุ่ม ลดอัตราการโจมตีคู่ 20% และลดอัตราการป้องกันคู่ 30%).',
		describe_in = 'Madoka berubah menjadi dewa, mengaktifkan prinsip lingkaran, dan membuka mimpi yang nyata dan ilusif. Kemudian mimpi itu pecah, menyerang semua musuh, menyebabkan #C0x3D8A99#300% Damage Magis#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#damage sihir#C0x5B545B#, membuat target memiliki peluang 70% untuk masuk ke [Ilusi] selama 2 giliran (Ilusi: efek khusus, target mengalami diam, bingung, dan salah satu dari empat efek acak yaitu pengurangan 20% peluang serangan ganda dan pengurangan 30% peluang pertahanan ganda).',
		describe_ph = 'Nagiging isang diyos si Madoka, pinapagana ang prinsipyo ng bilog at binubuksan ang isang panaginip na totoo at ilusyon. Pagkatapos ay nabasag ang panaginip, inaatake ang lahat ng kalaban, nagdudulot ng #C0x3D8A99#300% Pinsalang Mahika#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#pinsalang mahika#C0x5B545B#, na may 70% tsansa ang target na pumasok sa [Ilusyon] sa loob ng 2 turn (Ilusyon: espesyal na epekto, ang target ay napapatahimik, nalilito, at isa sa apat na random na epekto ay pagbaba ng 20% sa tsansa ng doble at pagbaba ng 30% sa tsansa ng dobleng depensa).',
		describe_ma = 'Madoka berubah menjadi dewa, mengaktifkan prinsip bulatan dan membuka mimpi yang nyata dan ilusi. Kemudian mimpi itu pecah, menyerang semua musuh, menyebabkan #C0x3D8A99#300% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#kerosakan sihir#C0x5B545B#, menyebabkan sasaran mempunyai peluang 70% untuk memasuki [Ilusi] selama 2 pusingan (Ilusi: kesan khas, sasaran menjadi bisu, keliru, dan salah satu daripada empat kesan rawak iaitu mengurangkan 20% kebarangkalian serangan berganda dan mengurangkan 30% kebarangkalian pertahanan berganda).',
		describe = 'Madoka transforms into a deity, activates the principle of the circle, and opens a dream that is both real and illusory. Then the dream shatters, attacking all enemies, dealing #C0x3D8A99#300% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#magic damage#C0x5B545B#, causing a 70% chance to enter [Illusion] for 2 turns (Illusion: special effect, target falls into silence, confusion, and one of four random effects: 20% decrease in double attack rate and 30% decrease in double defense rate).',
		simDesc_vn = 'Madoka biến thành một vị thần và kích hoạt nguyên lý vòng tròn để tạo ra một giấc mơ chân thực như ảo ảnh. Sau đó giấc mơ tan vỡ và tấn công tất cả kẻ thù, có khả năng khiến mục tiêu rơi vào ảo ảnh.',
		simDesc_en = 'Madoka transforms into a deity and activates the principle of the circle to create a dream as real as an illusion. Then the dream shatters and attacks all enemies, with the ability to cause targets to fall into an illusion.',
		simDesc_th = 'มาดอกะเปลี่ยนร่างเป็นเทพเจ้าและเปิดใช้หลักการของวงกลมเพื่อสร้างความฝันที่เหมือนจริงเสมือนภาพลวงตา จากนั้นความฝันแตกสลายและโจมตีศัตรูทั้งหมด มีพลังทำให้เป้าหมายตกอยู่ในภาพลวงตา',
		simDesc_in = 'Madoka berubah menjadi dewa dan mengaktifkan prinsip lingkaran untuk menciptakan mimpi yang nyata seperti ilusi. Kemudian mimpi itu pecah dan menyerang semua musuh, dengan kemampuan membuat target jatuh ke dalam ilusi.',
		simDesc_ph = 'Nag-transform si Madoka bilang isang diyos at pina-activate ang prinsipyo ng bilog para lumikha ng isang panaginip na kasing-totoo ng ilusyon. Pagkatapos, ang panaginip ay nabasag at inatake ang lahat ng mga kalaban, may kakayahang magdulot ng ilusyon sa mga target.',
		simDesc_ma = 'Madoka berubah menjadi dewa dan mengaktifkan prinsip bulatan untuk mencipta mimpi yang nyata seperti ilusi. Kemudian mimpi itu pecah dan menyerang semua musuh, dengan keupayaan menyebabkan sasaran jatuh ke dalam ilusi.',
		simDesc = 'Madoka transforms into a deity and activates the principle of the circle to create a dream as real as an illusion. Then the dream shatters and attacks all enemies, with the ability to cause targets to fall into an illusion.',
		starEffect = __data_t__starEffect[7713],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Mục tiêu trong ảo cảnh có 20% cơ hội rơi vào Song Trùng Ảo Cảnh (chịu thêm một loại hiệu ứng ảo cảnh ngẫu nhiên khác) sau khi hành động.',
		starEffectDesc = 'Additional effect: Targets in the illusion have a 20% chance to fall into Twin Illusion (suffering an additional random illusion effect) after acting.',
		starEffectDesc_en = 'Additional effect: Targets in the illusion have a 20% chance to fall into Twin Illusion (suffering an additional random illusion effect) after acting.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เป้าหมายในภาพลวงตามีโอกาส 20% ที่จะตกอยู่ในสภาพภาพลวงตาคู่ (ได้รับเอฟเฟกต์ภาพลวงตาสุ่มประเภทอื่นเพิ่มเติม) หลังจากการกระทำ',
		starEffectDesc_in = 'Efek tambahan: Target dalam ilusi memiliki peluang 20% untuk terkena Ilusi Kembar (mengalami efek ilusi acak tambahan) setelah bertindak.',
		starEffectDesc_ph = 'Karagdagang epekto: Ang mga target sa ilusyon ay may 20% na pagkakataon na mapasok sa Twin Illusion (nakararanas ng karagdagang random na epekto ng ilusyon) pagkatapos kumilos.',
		starEffectDesc_ma = 'Kesan tambahan: Sasaran dalam ilusi mempunyai peluang 20% untuk jatuh ke dalam Ilusi Berganda (menanggung kesan ilusi rawak tambahan) selepas bertindak.',
		zawakeEffect = __data_t__zawakeEffect[7713],
