	[7833] = {
		id = 7833,
		skillName_vn = 'Ân huệ của thiên nhiên',
		skillName_en = 'The grace of nature',
		skillName_th = 'พระคุณของธรรมชาติ',
		skillName_in = 'Anugerah alam',
		skillName_ph = 'Biyaya ng kalikasan',
		skillName_ma = 'Rahmat alam',
		skillName = 'The grace of nature',
		describe_vn = 'Đại Trúc Quỳ giải phóng sức mạnh tự nhiên, làm cho cây cỏ khô héo hồi sinh tự nhiên, hồi máu cho toàn bộ mục tiêu đồng minh #C0x3D8A99#200% Phép Công#C0x5B545B#+$(skillLevel*4*60)$ máu, lượng hồi máu dư thừa sẽ chuyển thành lá chắn tương đương (lá chắn kéo dài 2 lượt)',
		describe_en = 'Great Bamboo Flower unleashes natural power, causing withered plants to naturally revive, healing all allied targets for #C0x3D8A99#200% Magic Attack#C0x5B545B#+$(skillLevel*4*60)$ HP. Excess healing is converted into a shield of equivalent value (shield lasts 2 turns).',
		describe_th = 'ดอกไผ่ยักษ์ปลดปล่อยพลังธรรมชาติ ทำให้ต้นไม้แห้งแล้งฟื้นคืนชีพตามธรรมชาติ รักษาพลังชีวิตให้เป้าหมายพันธมิตรทั้งหมด #C0x3D8A99#200% พลังเวท#C0x5B545B#+$(skillLevel*4*60)$ พลังชีวิต การรักษาที่เกินจะถูกแปลงเป็นโล่ที่มีค่าเท่ากัน (โล่มีระยะเวลา 2 เทิร์น)',
		describe_in = 'Bunga Bambu Besar melepaskan kekuatan alami, membuat tanaman kering hidup kembali secara alami, menyembuhkan seluruh target sekutu sebesar #C0x3D8A99#200% Serangan Sihir#C0x5B545B#+$(skillLevel*4*60)$ HP, kelebihan penyembuhan akan diubah menjadi perisai yang setara (perisai bertahan selama 2 giliran).',
		describe_ph = 'Ang Dakilang Bulaklak ng Kawayan ay nagpapalabas ng likas na kapangyarihan, nagpapabuhay muli ng mga tuyong halaman nang natural, nagpapagaling sa lahat ng mga kaalyadong target ng #C0x3D8A99#200% Magic Attack#C0x5B545B#+$(skillLevel*4*60)$ HP. Ang sobrang paggaling ay gagawing pantakip na katumbas ng halaga (matatagal ang pantakip ng 2 turn).',
		describe_ma = 'Bunga Buluh Besar melepaskan kuasa semula jadi, menyebabkan tumbuhan kering kembali pulih secara semula jadi, memulihkan kesihatan semua sasaran sekutu sebanyak #C0x3D8A99#200% Serangan Sihir#C0x5B545B#+$(skillLevel*4*60)$ HP. Lebihan pemulihan akan ditukarkan menjadi perisai yang setara (perisai bertahan selama 2 pusingan).',
		describe = 'Great Bamboo Flower unleashes natural power, causing withered plants to naturally revive, healing all allied targets for #C0x3D8A99#200% Magic Attack#C0x5B545B#+$(skillLevel*4*60)$ HP. Excess healing is converted into a shield of equivalent value (shield lasts 2 turns).',
		simDesc_vn = 'Gloom giải phóng sức mạnh tự nhiên, làm hồi sinh cây cỏ héo tàn, hồi phục sinh lực cho toàn bộ đồng minh, phần hồi phục dư thừa sẽ chuyển thành lá chắn.',
		simDesc_en = 'Gloom releases natural power, reviving withered plants and restoring vitality to all allies. Any excess healing is converted into a shield.',
		simDesc_th = 'Gloom ปลดปล่อยพลังธรรมชาติ ชุบชีวิตพืชที่เหี่ยวเฉา ฟื้นฟูพลังชีวิตให้กับพันธมิตรทั้งหมด ส่วนพลังฟื้นฟูส่วนเกินจะกลายเป็นโล่ป้องกัน',
		simDesc_in = 'Gloom melepaskan kekuatan alam, menghidupkan kembali tanaman layu, memulihkan kekuatan seluruh sekutu. Sisa pemulihan akan diubah menjadi perisai.',
		simDesc_ph = 'Ang Gloom ay nagpapalabas ng likas na kapangyarihan, muling life-in ang mga nalalanta na halaman, at nagpapagaling ng lakas ng lahat ng kakampi. Ang sobrang paggaling ay nagiging panangga.',
		simDesc_ma = 'Gloom melepaskan kuasa semula jadi, menghidupkan tumbuhan yang layu, memulihkan tenaga seluruh sekutu. Sebarang pemulihan berlebihan akan ditukar menjadi perisai.',
		simDesc = 'Gloom releases natural power, reviving withered plants and restoring vitality to all allies. Any excess healing is converted into a shield.',
