	[7933] = {
		id = 7933,
		skillName_vn = 'Pháo plasma ba nòng',
		skillName_en = 'Triple-barrel plasma cannon',
		skillName_th = 'ปืนพลาสม่าสามลำกล้อง',
		skillName_in = 'Meriam plasma tiga laras',
		skillName_ph = 'Tatlong-baril na plasma cannon',
		skillName_ma = 'Meriam plasma tiga laras',
		skillName = 'Triple-barrel plasma cannon',
		describe_vn = 'Zombie mặc đồ đen lấy ra một khẩu pháo plasma ba ống và phun ra sức mạnh núi lửa theo mọi hướng để tấn công các mục tiêu ở hàng đầu của kẻ thù, gây ra #C0x3D8A99#240% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54#sát thương ma thuật#C0x5B545B#. Do cảm xúc không ổn định nên thiệt hại cuối cùng có thể không thay đổi, có thể tăng gấp đôi hoặc có thể giảm đi một nửa.',
		describe_en = 'The zombie dressed in black takes out a triple-barreled plasma cannon and unleashes volcanic power in all directions to attack the front-row enemies, dealing #C0x3D8A99#240% Magical Damage#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54#magic damage#C0x5B545B#. Due to unstable emotions, the final damage may vary, potentially doubling or halving.',
		describe_th = 'ซอมบี้ที่สวมชุดดำหยิบปืนพลาสม่าสามลำกล้องออกมาและพ่นพลังภูเขาไฟในทุกทิศทางเพื่อโจมตีเป้าหมายแถวหน้า ทำให้เกิด #C0x3D8A99#ความเสียหายเวทมนตร์ 240%#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B#. เนื่องจากอารมณ์ไม่มั่นคง ความเสียหายสุดท้ายอาจไม่แน่นอน อาจเพิ่มขึ้นเป็นสองเท่าหรืออาจลดลงเหลือครึ่งหนึ่ง',
		describe_in = 'Zombie berpakaian hitam mengeluarkan senapan plasma tiga laras dan menyemburkan kekuatan gunung berapi ke segala arah untuk menyerang target barisan depan musuh, memberikan #C0x3D8A99#240% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54#kerusakan magis#C0x5B545B#. Karena emosi tidak stabil, kerusakan akhir mungkin tidak konstan, bisa menjadi dua kali lipat atau berkurang setengahnya.',
		describe_ph = 'Ang zombie na nakasuot ng itim na damit ay kumuha ng tatlong-baril na plasma cannon at pinakawalan ang kapangyarihan ng bulkan sa lahat ng direksyon para atakihin ang mga layunin sa unahang hanay ng kalaban, nagdudulot ng #C0x3D8A99#240% Magical Damage#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54#magic damage#C0x5B545B#. Dahil sa hindi matatag na emosyon, ang panghuling pinsala ay maaaring magbago, maaaring dumoble o maging kalahati.',
		describe_ma = 'Zombie yang memakai pakaian hitam mengeluarkan meriam plasma tiga laras dan menyemburkan kuasa gunung berapi ke semua arah untuk menyerang sasaran barisan hadapan musuh, menyebabkan #C0x3D8A99#240% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54#kerosakan sihir#C0x5B545B#. Disebabkan emosi tidak stabil, kerosakan akhir mungkin tidak tetap, boleh menjadi dua kali ganda atau berkurang separuh.',
		describe = 'The zombie dressed in black takes out a triple-barreled plasma cannon and unleashes volcanic power in all directions to attack the front-row enemies, dealing #C0x3D8A99#240% Magical Damage#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54#magic damage#C0x5B545B#. Due to unstable emotions, the final damage may vary, potentially doubling or halving.',
		simDesc_vn = 'Những thây ma mặc đồ đen lấy ra ba khẩu pháo plasma và phun ra sức mạnh như núi lửa theo mọi hướng để tấn công các mục tiêu ở hàng đầu của kẻ thù. Thiệt hại cuối cùng có thể không thay đổi, có thể tăng gấp đôi hoặc giảm một nửa.',
		simDesc_en = 'The zombies dressed in black pulled out three plasma cannons and unleashed power like a volcano in all directions to attack the enemy\'s frontline targets. The final damage may remain unchanged, double, or be halved.',
		simDesc_th = 'ซอมบี้สวมชุดสีดำดึงปืนพลาสม่าสามกระบอกออกมาและปล่อยพลังเหมือนภูเขาไฟในทุกทิศทางเพื่อโจมตีเป้าหมายแถวหน้าของศัตรู ความเสียหายสุดท้ายอาจไม่เปลี่ยนแปลง เพิ่มขึ้นเป็นสองเท่าหรือลดลงครึ่งหนึ่ง',
		simDesc_in = 'Zombie yang mengenakan pakaian hitam mengeluarkan tiga meriam plasma dan melepaskan kekuatan seperti gunung berapi ke segala arah untuk menyerang target garis depan musuh. Kerusakan akhir dapat tetap sama, meningkat dua kali lipat, atau berkurang setengahnya.',
		simDesc_ph = 'Ang mga zombie na nakasuot ng itim na damit ay kumuha ng tatlong plasma cannons at pinakawalan ang kapangyarihan tulad ng isang bulkan sa lahat ng direksyon upang atakihin ang mga target sa unahang linya ng kaaway. Ang huling pinsala ay maaaring manatiling hindi nagbabago, dumoble, o mabawasan ng kalahati.',
		simDesc_ma = 'Zombi berpakaian hitam mengeluarkan tiga meriam plasma dan melepaskan kuasa seperti gunung berapi ke semua arah untuk menyerang sasaran barisan hadapan musuh. Kerosakan akhir mungkin tidak berubah, meningkat dua kali ganda, atau berkurang separuh.',
		simDesc = 'The zombies dressed in black pulled out three plasma cannons and unleashed power like a volcano in all directions to attack the enemy\'s frontline targets. The final damage may remain unchanged, double, or be halved.',
