		skillName_in = 'Meriam air',
		skillName_ph = 'Kanyon ng tubig',
		skillName_ma = 'Meriam air',
		skillName = 'Water cannon',
		describe_vn = 'Cá sấu xanh phun ra pháo nước xoáy mạnh mẽ tấn công hàng mục tiêu của kẻ địch, gây ra #C0xE69900#260% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, nếu mục tiêu có hiệu ứng giảm tốc độ, sát thương lần này tăng thêm 30%',
		describe_en = 'The green crocodile spits out a powerful swirling water cannon to attack the enemy\'s target row, dealing #C0xE69900#260% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. If the target has a slow effect, this damage increases by an additional 30%.',
		describe_th = 'จระเข้สีเขียวพ่นปืนฉีดน้ำวนแรงโจมตีแถวเป้าหมายของศัตรู สร้างความเสียหาย #C0xE69900#260% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายกายภาพ#C0x5B545B# หากเป้าหมายมีสถานะชะลอ ความเสียหายนี้จะเพิ่มขึ้นอีก 30%.',
		describe_in = 'Buaya hijau menyemburkan meriam air berputar yang kuat untuk menyerang bar target musuh, menyebabkan #C0xE69900#260% Serangan Fisik#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Jika target memiliki efek pelambatan, kerusakan ini meningkat 30% tambahan.',
		describe_ph = 'Ang berdinamikong buwaya ay nagsisiboy ng malakas na paikot na tubig na kanyon na umaatake sa hilera ng mga target ng kaaway, na nagdudulot ng #C0xE69900#260% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Kung ang target ay may epekto ng pagbagal, ang pinsalang ito ay tataas pa ng 30%.',
		describe_ma = 'Buaya hijau menyemburkan meriam air berpusar yang kuat untuk menyerang bar sasaran musuh, menyebabkan #C0xE69900#260% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Jika sasaran mempunyai kesan perlahan, kerosakan kali ini meningkat sebanyak 30%.',
		describe = 'The green crocodile spits out a powerful swirling water cannon to attack the enemy\'s target row, dealing #C0xE69900#260% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. If the target has a slow effect, this damage increases by an additional 30%.',
		simDesc_vn = 'Croconaw phun ra nước xoáy mạnh mẽ tấn công mục tiêu hàng ngang của đối phương, nếu mục tiêu bị giảm tốc độ, sát thương lần này sẽ được tăng cường.',
		simDesc_en = 'Croconaw sprays a powerful whirlpool of water to attack a horizontal row of enemy targets. If the targets are slowed, this attack\'s damage will be enhanced.',
		simDesc_th = 'โกรโครนอว์พ่นน้ำวนแรงเพื่อโจมตีเป้าหมายในแนวนอนของศัตรู หากเป้าหมายถูกชะลอความเร็ว ความเสียหายในการโจมตีครั้งนี้จะเพิ่มขึ้น',
		simDesc_in = 'Croconaw menyemburkan pusaran air yang kuat untuk menyerang baris horizontal target musuh. Jika target melambat, serangan ini akan mendapatkan peningkatan damage.',
		simDesc_ph = 'Croconaw ay nagsa-spray ng malakas na whirlpool ng tubig upang atakihin ang pahalang na hanay ng mga kalaban. Kung mabagal ang mga target, tataas ang pinsala ng pag-atake na ito.',
		simDesc_ma = 'Croconaw menyemburkan pusaran air yang kuat untuk menyerang barisan mendatar sasaran musuh. Jika sasaran dilambatkan, kerosakan serangan ini akan dipertingkatkan.',
		simDesc = 'Croconaw sprays a powerful whirlpool of water to attack a horizontal row of enemy targets. If the targets are slowed, this attack\'s damage will be enhanced.',
		starEffect = __data_t__starEffect[8023],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi tấn công mục tiêu bị giảm tốc, thêm 15% sát thương từ nguyên tố nước vào sát thương lần này.',
		starEffectDesc = 'Additional effect: When attacking a slowed target, add 15% water elemental damage to this hit.',
		starEffectDesc_en = 'Additional effect: When attacking a slowed target, add 15% water elemental damage to this hit.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อโจมตีเป้าหมายที่ถูกชะลอความเร็ว ให้เพิ่มความเสียหายธาตุน้ำ 15% ในการโจมตีครั้งนี้',
		starEffectDesc_in = 'Efek tambahan: Saat menyerang target yang diperlambat, tambahkan 15% kerusakan elemen air pada serangan ini.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag inaatake ang target na bumagal, magdagdag ng 15% na elemental na pinsala ng tubig sa pag-atakeng ito.',
		starEffectDesc_ma = 'Kesan tambahan: Semasa menyerang sasaran yang dilambatkan, tambah 15% kerosakan elemen air pada serangan ini.',
		zawakeEffect = __data_t__zawakeEffect[8023],
		-- {79003}
		zawakeEffectDesc = 'Lam Ngạc sprays strong swirling water to attack the enemy\'s row target, causing #C0xE69900#280% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. If the target has a slow effect, this damage increases by 30%',
		zawakeEffectDesc_en = 'Lam Ngạc sprays strong swirling water to attack the enemy\'s row target, causing #C0xE69900#280% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. If the target has a slow effect, this damage increases by 30%',
		zawakeEffectDesc_th = 'ลัม งักส์ พ่นน้ำวนแรงโจมตีเป้าหมายแถวฝ่ายตรงข้าม สร้างความเสียหาย #C0xE69900#280% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# หากเป้าหมายมีผลช้าลง ความเสียหายครั้งนี้จะเพิ่มขึ้น 30%',
		zawakeEffectDesc_in = 'Lam Ngạc menyemprotkan air berputar kencang untuk menyerang target baris musuh, menyebabkan #C0xE69900#280% Serangan Fisik#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, jika target memiliki efek perlambatan, kerusakan ini meningkat 30%',
		zawakeEffectDesc_ph = 'Si Lam Ngạc ay nagbubuga ng malakas na paikot-ikot na tubig upang atakihin ang target sa hanay ng kalaban, nagdudulot ng #C0xE69900#280% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Kung ang target ay may epekto ng pagbagal, tumataas ng 30% ang pinsalang ito',
		zawakeEffectDesc_ma = 'Lam Ngạc menyembur air pusaran kuat menyerang sasaran baris musuh, menyebabkan #C0xE69900#280% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Jika sasaran mempunyai kesan perlahan, kerosakan ini meningkat 30%',
		zawakeEffectDesc_vn = 'Lam Ngạc phun nước xoáy mạnh tấn công mục tiêu hàng của đối phương, gây ra #C0xE69900#280% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, nếu mục tiêu có hiệu ứng giảm tốc độ, sát thương lần này tăng 30%',
