	[8033] = {
		id = 8033,
		skillName_vn = 'Tấn công xoáy cuồng nộ',
		skillName_en = 'Frenzied Spiral Attack',
		skillName_th = 'การโจมตีหมุนวนคลั่ง',
		skillName_in = 'Serangan Spiral Amukan',
		skillName_ph = 'Galit na Paikot na Atake',
		skillName_ma = 'Serangan Pusingan Marah',
		skillName = 'Frenzied Spiral Attack',
		describe_vn = 'Cá sấu lớn kích hoạt sức mạnh hoang dã, ném hàng mục tiêu của kẻ địch lên không trung và phun pháo nước đại bác, nhốt chúng trong xoáy nước dữ dội và cắn chí mạng, gây ra #C0xE69900#280% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, nếu mục tiêu có hiệu ứng giảm tốc độ, sát thương lần này tăng thêm 30%',
		describe_en = 'The giant crocodile activates its wild power, throws multiple enemy targets into the air, and sprays a water cannon blast, trapping them in a fierce whirlpool before delivering a critical bite, dealing #C0xE69900#280% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. If the target is affected by a slowing effect, this damage increases by an additional 30%.',
		describe_th = 'จระเข้ยักษ์เปิดใช้งานพลังป่าเถื่อน ขว้างเป้าหมายศัตรูหลายตัวขึ้นสู่อากาศและพ่นปืนฉีดน้ำ จับพวกมันไว้ในกระแสน้ำวนรุนแรงก่อนจะกัดโจมตีอย่างรุนแรง สร้างความเสียหาย #C0xE69900#280% ความโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# หากเป้าหมายมีสถานะลดความเร็วจารทำนี้จะเพิ่มขึ้นอีก 30%',
		describe_in = 'Buaya besar mengaktifkan kekuatan liar, melempar beberapa target musuh ke udara dan menyemburkan meriam air, menahan mereka dalam pusaran air ganas sebelum menggigit dengan kritis, menyebabkan #C0xE69900#280% Serangan Fisik#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Jika target memiliki efek perlambatan, kerusakan ini meningkat 30% lebih lanjut.',
		describe_ph = 'Ang malaking buwaya ay nag-activate ng kanyang wild power, itinatapon ang maraming target ng kalaban sa hangin at nagpapalabas ng water cannon blast, nakakulong sila sa mabangis na whirlpool bago kumagat ng malakas, nagdudulot ng #C0xE69900#280% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Kung ang target ay may slow effect, tataas pa ang damage na ito ng 30%.',
		describe_ma = 'Buaya besar mengaktifkan kuasa liar, melempar beberapa sasaran musuh ke udara dan menyembur meriam air, memerangkap mereka dalam pusaran air ganas sebelum menggigit dengan kritikal, menyebabkan #C0xE69900#280% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Jika sasaran mempunyai kesan perlambatan, kerosakan ini meningkat sebanyak 30% lagi.',
		describe = 'The giant crocodile activates its wild power, throws multiple enemy targets into the air, and sprays a water cannon blast, trapping them in a fierce whirlpool before delivering a critical bite, dealing #C0xE69900#280% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. If the target is affected by a slowing effect, this damage increases by an additional 30%.',
		simDesc_vn = 'Feraligatr phát động sức mạnh, ném mục tiêu hàng ngang lên không trung và phun ra nước, giữ mục tiêu trong cơn lũ dữ và cắn một cú chí mạng, nếu mục tiêu bị giảm tốc độ, sát thương lần này sẽ được tăng cường.',
		simDesc_en = 'Feraligatr unleashes its power, tossing the horizontal row of targets into the air and spraying water, holding the targets in a raging flood and striking a critical bite. If the targets are slowed, this damage will be increased.',
		simDesc_th = 'Feraligatr ปล่อยพลังโจมตี ขว้างเป้าหมายในแนวนอนขึ้นกลางอากาศพร้อมพ่นน้ำ ถือเป้าหมายไว้ในน้ำท่วมทะลักและกัดอย่างรุนแรง หากเป้าหมายถูกทำให้ช้าลง ความเสียหายครั้งนี้จะเพิ่มขึ้น',
		simDesc_in = 'Feraligatr mengerahkan kekuatannya, melempar target dalam baris horizontal ke udara dan menyemburkan air, menahan target dalam banjir dahsyat dan menggigit dengan serangan kritis. Jika target melambat, kerusakan ini akan ditingkatkan.',
		simDesc_ph = 'Inilalabas ni Feraligatr ang kanyang lakas, itinapon ang mga target sa pahalang na linya sa hangin at bumubuga ng tubig, hinahawakan ang mga target sa isang mabangis na baha at kumagat ng malakas. Kung mabagal ang target, tataas ang pinsalang ito.',
		simDesc_ma = 'Feraligatr mengerahkan kekuatannya, melempar sasaran baris mendatar ke udara dan menyembur air, menahan sasaran dalam banjir yang ganas serta menggigit dengan serangan kritikal. Jika sasaran dilambatkan, kerosakan ini akan meningkat.',
		simDesc = 'Feraligatr unleashes its power, tossing the horizontal row of targets into the air and spraying water, holding the targets in a raging flood and striking a critical bite. If the targets are slowed, this damage will be increased.',
		starEffect = __data_t__starEffect[8033],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi tấn công mục tiêu bị giảm tốc, thêm 15% sát thương từ nguyên tố nước vào sát thương lần này.',
		starEffectDesc = 'Additional effect: When attacking a slowed target, add 15% water elemental damage to this hit.',
		starEffectDesc_en = 'Additional effect: When attacking a slowed target, add 15% water elemental damage to this hit.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อโจมตีเป้าหมายที่ถูกชะลอความเร็ว ให้เพิ่มความเสียหายธาตุน้ำ 15% ในการโจมตีครั้งนี้',
		starEffectDesc_in = 'Efek tambahan: Saat menyerang target yang diperlambat, tambahkan 15% kerusakan elemen air pada serangan ini.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag inaatake ang target na bumagal, magdagdag ng 15% na elemental na pinsala ng tubig sa pag-atakeng ito.',
		starEffectDesc_ma = 'Kesan tambahan: Semasa menyerang sasaran yang dilambatkan, tambah 15% kerosakan elemen air pada serangan ini.',
		zawakeEffect = __data_t__zawakeEffect[8033],
		-- {79003}
		zawakeEffectDesc = 'Feraligatr activates its primal power, hurling the enemy\'s horizontal targets into the air and blasting water cannons, trapping them in a fierce whirlpool to bite to death, dealing #C0xE69900#300% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#, if the target has a slow effect, this damage increases by 30%',
		zawakeEffectDesc_en = 'Feraligatr activates its primal power, hurling the enemy\'s horizontal targets into the air and blasting water cannons, trapping them in a fierce whirlpool to bite to death, dealing #C0xE69900#300% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#, if the target has a slow effect, this damage increases by 30%',
		zawakeEffectDesc_th = 'Feraligatr เปิดใช้งานพลังดุร้าย ขว้างเป้าหมายแถวนอนของฝ่ายตรงข้ามขึ้นกลางอากาศและพ่นปืนฉีดน้ำ กักขังพวกมันในน้ำวนรุนแรงเพื่อกัดตาย สร้าง #C0xE69900#300% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# หากเป้าหมายมีสถานะลดความเร็ว ความเสียหายครั้งนี้จะเพิ่มขึ้น 30%',
		zawakeEffectDesc_in = 'Feraligatr mengaktifkan kekuatan liar, melemparkan target horizontal musuh ke udara dan menyemburkan meriam air, menjebak mereka dalam pusaran air yang ganas untuk menggigit hingga mati, memberikan #C0xE69900#300% Serangan Fisik#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, jika target memiliki efek pelambatan, damage ini meningkat 30%',
		zawakeEffectDesc_ph = 'Pinapagana ni Feraligatr ang taglay na ligaw na lakas, hinahagis ang mga pahalang na target ng kalaban sa himpapawid at nagbubuga ng water cannon, nakakulong sila sa malupit na whirlpool para kagatin hanggang mamatay, nagdudulot ng #C0xE69900#300% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#, kung ang target ay may slow effect, tumataas ng 30% ang damage na ito',
		zawakeEffectDesc_ma = 'Feraligatr mengaktifkan kekuatan liar, melempar sasaran barisan mendatar musuh ke udara dan menyembur meriam air, memerangkap mereka dalam pusaran air ganas untuk menggigit hingga mati, menyebabkan #C0xE69900#300% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, jika sasaran mempunyai kesan perlahan, kerosakan ini meningkat 30%',
		zawakeEffectDesc_vn = 'Feraligatr kích hoạt sức mạnh hoang dã, ném mục tiêu hàng ngang của đối phương lên không trung và phun pháo nước, nhốt chúng trong xoáy nước dữ dội để cắn chết, gây #C0xE69900#300% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, nếu mục tiêu có hiệu ứng giảm tốc độ, sát thương lần này tăng 30%',
		zawakeSimpleType = 2,
