	[8616] = {
		id = 8616,
		skillName_vn = 'Phúc lành',
		skillName_en = 'Blessing',
		skillName_th = 'พร',
		skillName_in = 'Berkah',
		skillName_ph = 'Basbas',
		skillName_ma = 'Berkat',
		skillName = 'Blessing',
		describe_vn = 'Kỹ năng hào quang: Trước mỗi lần hành động của đơn vị phe ta, có #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# xác suất nhận [Phước lành] trong 1 lượt (kéo dài đến khi kết thúc vòng lớn hiện tại), đối với đồng đội có [May mắn], hiệu quả của [Phước lành] sẽ được nhân đôi\n#F20# \n#F40#[Phước lành]: Hiệu ứng tăng cường, tăng Công Phép và phòng phép của mục tiêu (mức tăng là 10% thuộc tính tương ứng của Togepi, nhân đôi là 20%)',
		describe_en = 'Aura Skill: Before each action of our faction\'s unit, there is a #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# chance to receive [Blessing] for 1 turn (lasting until the end of the current major round). For teammates with [Luck], the effect of [Blessing] will be doubled. #F20#[Blessing]: A buff effect that increases the target\'s Magic Attack and Magic Defense (the increase is 10% of Togepi\'s corresponding attribute, doubled to 20%)',
		describe_th = 'สกิลออร่า: ก่อนที่หน่วยฝ่ายเราจะทำการกระทำแต่ละครั้ง จะมีโอกาส #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# ในการได้รับ [พร] เป็นเวลา 1 เทิร์น (ต่อเนื่องจนกว่าจะสิ้นสุดรอบหลักปัจจุบัน) สำหรับเพื่อนร่วมทีมที่มี [โชค] เอ็ฟเฟ็กต์ของ [พร] จะถูกคูณเป็นสองเท่า #F20#[พร]: เอฟเฟกต์บัฟ เพิ่มพลังเวทและค่าป้องกันเวทของเป้าหมาย (เพิ่มขึ้น 10% ของค่าสถานะที่เกี่ยวข้องของ Togepi, คูณเป็น 20%)',
		describe_in = 'Skill Aura: Sebelum setiap aksi unit dari pihak kita, ada peluang #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# untuk menerima [Berkah] selama 1 giliran (bertahan hingga akhir putaran utama saat ini). Untuk rekan satu tim yang memiliki [Keberuntungan], efek [Berkah] akan diperbesar dua kali lipat. #F20#[Berkah]: Efek peningkatan yang meningkatkan Serangan Sihir dan Pertahanan Sihir target (peningkatan sebesar 10% atribut terkait milik Togepi, dua kali lipat menjadi 20%)',
		describe_ph = 'Aura Skill: Bago ang bawat aksyon ng unit sa ating panig, may #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# tsansa na makatanggap ng [Pagpapala] sa loob ng 1 turn (tumataas hanggang matapos ang kasalukuyang malaking round). Para sa mga kaalyadong may [Swerte], ang epekto ng [Pagpapala] ay dodoblehin. #F20#[Pagpapala]: Isang enhancement effect na nagbibigay ng pagtaas sa Magic Attack at Magic Defense ng target (ang pagtaas ay 10% ng kaugnay na attribute ni Togepi, na dodoblehin sa 20%)',
		describe_ma = 'Kemahiran Aura: Sebelum setiap tindakan unit pihak kita, terdapat peluang #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# untuk menerima [Berkat] selama 1 pusingan (berlaku sehingga tamat pusingan besar semasa). Bagi rakan sepasukan yang mempunyai [Nasib], kesan [Berkat] akan digandakan. #F20#[Berkat]: Kesan peningkatan yang meningkatkan Serangan Sihir dan Pertahanan Sihir sasaran (kenaikan ialah 10% atribut berkaitan Togepi, digandakan menjadi 20%)',
		describe = 'Aura Skill: Before each action of our faction\'s unit, there is a #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# chance to receive [Blessing] for 1 turn (lasting until the end of the current major round). For teammates with [Luck], the effect of [Blessing] will be doubled. #F20#[Blessing]: A buff effect that increases the target\'s Magic Attack and Magic Defense (the increase is 10% of Togepi\'s corresponding attribute, doubled to 20%)',
		starEffect = __data_t__starEffect[8616],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Khi <phúc lành> kết thúc, hồi phục 30% sức tấn Công Phép thuật cho đơn vị có máu thấp nhất trong đội.',
		starEffectDesc = 'Enhance effect: When <blessing> ends, restore 30% of Magic Attack to the unit with the lowest HP in the team.',
		starEffectDesc_en = 'Enhance effect: When <blessing> ends, restore 30% of Magic Attack to the unit with the lowest HP in the team.',
		starEffectDesc_th = 'เสริมประสิทธิภาพ: เมื่อ <phúc lành> สิ้นสุด ฟื้นฟูพลังโจมตีเวท 30% ให้กับหน่วยที่มี HP ต่ำที่สุดในทีม',
		starEffectDesc_in = 'Tingkatkan efek: Ketika <berkah> berakhir, pulihkan 30% Serangan Sihir untuk unit dengan HP terendah dalam tim.',
		starEffectDesc_ph = 'Palakasin ang epekto: Kapag natapos ang <blessing>, ibalik ang 30% ng Magic Attack sa yunit na may pinakamababang HP sa koponan.',
		starEffectDesc_ma = 'Tingkatkan kesan: Apabila <berkat> berakhir, pulihkan 30% Serangan Sihir untuk unit dengan HP terendah dalam pasukan.',
		zawakeEffect = __data_t__zawakeEffect[8616],
		-- {79004, 1}
		zawakeEffectDesc = 'Enhance effect: When <blessing> ends, restore 30% Magic Power of Togepi to the ally with the lowest HP on your side, each time restoring blessing increases recovery rate for the target by 5% for 2 turns, up to 6 stacks',
		zawakeEffectDesc_en = 'Enhance effect: When <blessing> ends, restore 30% Magic Power of Togepi to the ally with the lowest HP on your side, each time restoring blessing increases recovery rate for the target by 5% for 2 turns, up to 6 stacks',
		zawakeEffectDesc_th = 'เพิ่มประสิทธิภาพ: เมื่อ <phước lành> สิ้นสุด ฟื้นฟูพลังเวทย์ของ Togepi 30% ให้กับหน่วยที่มี HP ต่ำที่สุดในฝ่ายเดียวกัน ทุกครั้งที่ฟื้นฟูพรสิทธิ์จะเพิ่มอัตราการฟื้นฟูให้เป้าหมาย 5% เป็นเวลา 2 เทิร์น สะสมได้สูงสุด 6 ครั้ง',
		zawakeEffectDesc_in = 'Tingkatkan efek: Ketika <phước lành> berakhir, pulihkan 30% Kekuatan Sihir Togepi untuk unit dengan HP terendah di pihakmu, setiap kali pemulihan berkat meningkatkan tingkat pemulihan untuk target sebesar 5% selama 2 giliran, maksimum dapat bertumpuk 6 kali',
		zawakeEffectDesc_ph = 'Palakasin ang epekto: Kapag natapos ang <phước lành>, ibalik ang 30% Magic Power ng Togepi sa yunit na may pinakamababang HP sa iyong panig, bawat pag-restore ng blessing ay magdadagdag ng 5% recovery rate para sa target sa loob ng 2 turn, maximum na maaaring ma-stack ng 6 beses',
		zawakeEffectDesc_ma = 'Perkuat kesan: Apabila <phước lành> berakhir, pulihkan 30% Kuasa Sihir Togepi kepada unit dengan HP terendah dalam pihak anda, setiap kali pemulihan berkat akan meningkatkan kadar pemulihan untuk sasaran sebanyak 5% selama 2 giliran, sehingga maksimum terkumpul 6 kali',
		zawakeEffectDesc_vn = 'Tăng cường hiệu ứng: Khi <phước lành> kết thúc, hồi phục 30% Công Phép của Togepi cho đơn vị có HP thấp nhất của phe mình, mỗi lần hồi phục phước lành sẽ tăng 5% tỷ lệ nhận hồi phục cho mục tiêu trong 2 lượt, tối đa cộng dồn 6 lần',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Each time healed by Blessing increases the target’s healing received rate by 5% for 2 turns, stacks up to 6 times',
		zawakeSimpleDesc_en = '#C0x5c9970#Each time healed by Blessing increases the target’s healing received rate by 5% for 2 turns, stacks up to 6 times',
		zawakeSimpleDesc_th = '#C0x5c9970#ทุกครั้งที่ฟื้นฟูด้วยพร จะเพิ่มอัตราการฟื้นฟูของเป้าหมาย 5% เป็นเวลา 2 เทิร์น สะสมได้สูงสุด 6 ครั้ง',
		zawakeSimpleDesc_in = '#C0x5c9970#Setiap kali dipulihkan oleh Berkat, meningkatkan rasio pemulihan yang diterima oleh target sebesar 5% selama 2 giliran, maksimum 6 tumpukan',
		zawakeSimpleDesc_ph = '#C0x5c9970#Tuwing gumagaling gamit ang Basbas, nadaragdagan ang rate ng recovery ng target ng 5% sa loob ng 2 turn, hanggang 6 na ulit',
		zawakeSimpleDesc_ma = '#C0x5c9970#Setiap kali disembuhkan oleh Berkat, kadar pemulihan sasaran meningkat 5% selama 2 giliran, maksimum sehingga 6 kali',
		zawakeSimpleDesc_vn = '#C0x5c9970#Mỗi lần hồi phục bằng phước lành sẽ tăng 5% tỷ lệ nhận hồi phục cho mục tiêu trong 2 lượt, tối đa cộng dồn 6 lần',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
