	[8623] = {
		id = 8623,
		skillName_vn = 'Vui đùa',
		skillName_en = 'Playful',
		skillName_th = 'ขี้เล่น',
		skillName_in = 'Bermain-main',
		skillName_ph = 'Mapaglaro',
		skillName_ma = 'Bermain-main',
		skillName = 'Playful',
		describe_vn = 'Togetic chơi đùa và tấn công toàn bộ mục tiêu kẻ địch, gây ra #C0x3D8A99#130% Công Phép#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, mang [May mắn] đến cho 2 đồng đội ngẫu nhiên trong 2 lượt, đối với đồng đội đã nhận [Phước lành], hiệu quả của [May mắn] sẽ được nhân đôi\n#F20# \n#F40#[May mắn]: Hiệu ứng tăng cường, tăng 20% (nhân đôi là 40%) kháng hiệu ứng xấu, khi bị tấn công có 30% (nhân đôi là 60%) xác suất tiêu hao [May mắn] để giảm 50% sát thương lần này',
		describe_en = 'Togetic plays and attacks all enemy targets, dealing #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, bringing [Luck] to 2 random allies for 2 turns. For allies who already have [Blessing], the effect of [Luck] will be doubled\n#F20# \n#F40#[Luck]: A buff effect that increases resistance to negative effects by 20% (doubled to 40%) and when attacked, has a 30% chance (doubled to 60%) to consume [Luck] to reduce damage by 50% this time.',
		describe_th = 'Togetic เล่นและโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหาย #C0x3D8A99#130% พลังเวท#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายเวท #C0x5B545B# นำ [โชคดี] มาสู่เพื่อนร่วมทีมแบบสุ่ม 2 คน เป็นเวลา 2 เทิร์น สำหรับเพื่อนร่วมทีมที่ได้รับ [พร] แล้ว, ผลของ [โชคดี] จะถูกเพิ่มเป็นสองเท่า\n#F20# \n#F40#[โชคดี]: เอฟเฟกต์บัฟ เพิ่มการต้านทานผลกระทบเชิงลบ 20% (เพิ่มเป็นสองเท่าเป็น 40%) และเมื่อถูกโจมตีมีโอกาส 30% (เพิ่มเป็นสองเท่าเป็น 60%) ที่จะใช้ [โชคดี] เพื่อลดความเสียหายลง 50% ในครั้งนี้',
		describe_in = 'Togetic bermain dan menyerang semua musuh, menyebabkan #C0x3D8A99#130% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, membawa [Keberuntungan] kepada 2 rekan secara acak selama 2 giliran. Untuk rekan yang sudah menerima [Berkah], efek dari [Keberuntungan] akan digandakan\n#F20# \n#F40#[Keberuntungan]: Efek peningkatan yang meningkatkan resistensi terhadap efek negatif sebesar 20% (digandakan menjadi 40%) dan saat diserang, memiliki 30% (digandakan menjadi 60%) peluang untuk menghabiskan [Keberuntungan] guna mengurangi kerusakan sebesar 50% kali ini.',
		describe_ph = 'Togetic ay naglalaro at umaatake sa lahat ng kalaban, nagdudulot ng #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sakit ng Magic #C0x5B545B#, nagdadala ng [Swerte] sa 2 random na kasamahan sa loob ng 2 turn. Para sa mga kasamahan na may [Bendisyon], ang epekto ng [Swerte] ay dodoblehe\n#F20# \n#F40#[Swerte]: Isang buff effect na nagpapataas ng resistensya laban sa mga negatibong epekto ng 20% (dodoblehe sa 40%) at kapag inaatake, may 30% (dodoblehe sa 60%) tsansa na magamit ang [Swerte] para mabawasan ang damage ng 50% sa pagkakataong ito.',
		describe_ma = 'Togetic bermain dan menyerang semua musuh, menyebabkan #C0x3D8A99#130% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, membawa [Nasib Baik] kepada 2 rakan secara rawak selama 2 pusingan. Bagi rakan yang telah menerima [Berkat], kesan [Nasib Baik] akan digandakan\n#F20# \n#F40#[Nasib Baik]: Kesan peningkatan yang meningkatkan ketahanan terhadap kesan negatif sebanyak 20% (digandakan menjadi 40%) dan apabila diserang, mempunyai 30% (digandakan menjadi 60%) peluang untuk menggunakan [Nasib Baik] untuk mengurangkan kerosakan sebanyak 50% kali ini.',
		describe = 'Togetic plays and attacks all enemy targets, dealing #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, bringing [Luck] to 2 random allies for 2 turns. For allies who already have [Blessing], the effect of [Luck] will be doubled\n#F20# \n#F40#[Luck]: A buff effect that increases resistance to negative effects by 20% (doubled to 40%) and when attacked, has a 30% chance (doubled to 60%) to consume [Luck] to reduce damage by 50% this time.',
		simDesc_vn = 'Togetic vui đùa với đối thủ và tấn công toàn bộ mục tiêu của đối phương, mang lại [May Mắn] cho hai đồng đội ngẫu nhiên.',
		simDesc_en = 'Togetic plays with the opponent and attacks all enemy targets, granting <Luck> to two random teammates.',
		simDesc_th = 'โทเกติกเล่นกับฝ่ายตรงข้ามและโจมตีเป้าหมายของศัตรูทั้งหมด มอบ [โชค] ให้กับเพื่อนร่วมทีมสองคนแบบสุ่ม',
		simDesc_in = 'Togetic bermain dengan lawan dan menyerang semua target musuh, memberikan <Keberuntungan> kepada dua rekan tim secara acak.',
		simDesc_ph = 'Nakikipaglaro si Togetic sa kalaban at ina-atake ang lahat ng mga target ng kalaban, nagbibigay ng <Swerte> sa dalawang random na kakampi.',
