		zawakeEffect = __data_t__zawakeEffect[8623],
		-- {79003}
		zawakeEffectDesc = 'Togetic plays and attacks all enemy targets, dealing #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, granting <luck> to two random allies for 3 turns, for allies receiving <blessing>, the <luck> effect is doubled#F20# #F40#<luck>: a buff effect, increases target\'s resistance to negative effects by 20% (doubled to 40%), when attacked has a 30% chance (doubled to 60%) to consume <luck> to block 50% damage this time',
		zawakeEffectDesc_en = 'Togetic plays and attacks all enemy targets, dealing #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, granting <luck> to two random allies for 3 turns, for allies receiving <blessing>, the <luck> effect is doubled#F20# #F40#<luck>: a buff effect, increases target\'s resistance to negative effects by 20% (doubled to 40%), when attacked has a 30% chance (doubled to 60%) to consume <luck> to block 50% damage this time',
		zawakeEffectDesc_th = 'โตกิทิคเล่นและโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวทมนตร์ #C0x3D8A99#130% พลังเวทมนตร์#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# มอบ <โชค> ให้กับพันธมิตรสุ่ม 2 คน เป็นเวลา 3 เทิร์น สำหรับพันธมิตรที่ได้รับ <พร> ผลของ <โชค> จะถูกเพิ่มเป็นสองเท่า #F20# #F40#<โชค>: เอฟเฟกต์เสริม เพิ่มความต้านทานต่อสถานะลบของเป้าหมาย 20% (เพิ่มเป็น 40%) เมื่อถูกโจมตีมีโอกาส 30% (เพิ่มเป็น 60%) ที่จะใช้ <โชค> เพื่อบล็อกความเสียหาย 50% ครั้งนี้',
		zawakeEffectDesc_in = 'Togetic bermain dan menyerang semua target musuh, memberikan #C0x3D8A99#130% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, memberikan <keberuntungan> kepada dua sekutu acak selama 3 giliran, untuk sekutu yang menerima <berkah>, efek <keberuntungan> digandakan #F20# #F40#<keberuntungan>: efek peningkatan, meningkatkan ketahanan target terhadap efek negatif sebesar 20% (digandakan menjadi 40%), saat diserang memiliki peluang 30% (digandakan menjadi 60%) untuk menghabiskan <keberuntungan> guna memblokir 50% kerusakan kali ini',
		zawakeEffectDesc_ph = 'Togetic ay naglalaro at umaatake sa lahat ng kalabang target, nagdudulot ng #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, nagbibigay ng <swerte> sa dalawang random na kakampi sa loob ng 3 turn, para sa kakampi na tumanggap ng <bendisyon>, ang epekto ng <swerte> ay nadodoble#F20# #F40#<swerte>: isang buff effect, nagdaragdag ng 20% resistensya sa negatibong epekto sa target (nadodoble sa 40%), kapag inaatake ay may 30% (nadodoble sa 60%) na tsansa na maubos ang <swerte> para harangin ang 50% ng damage sa pagkakataong ito',
		zawakeEffectDesc_ma = 'Togetic bermain dan menyerang semua sasaran musuh, memberikan #C0x3D8A99#130% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, memberi <nasib baik> kepada dua rakan sepasukan rawak selama 3 giliran, untuk rakan sepasukan yang menerima <berkat>, kesan <nasib baik> akan digandakan #F20# #F40#<nasib baik>: kesan peningkatan, meningkatkan ketahanan sasaran terhadap kesan negatif sebanyak 20% (digandakan menjadi 40%), apabila diserang mempunyai 30% peluang (digandakan menjadi 60%) untuk menggunakan <nasib baik> bagi menghalang 50% kerosakan kali ini',
		zawakeEffectDesc_vn = 'Togetic chơi đùa và tấn công toàn bộ mục tiêu của đối phương, gây #C0x3D8A99#130% Công Phép#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, mang <may mắn> cho hai đồng đội ngẫu nhiên trong 3 lượt, đối với đồng đội nhận <phước lành>, hiệu ứng <may mắn> sẽ được nhân đôi#F20# #F40#<may mắn>: hiệu ứng tăng cường, tăng 20% (nhân đôi là 40%) kháng tiêu cực cho mục tiêu, khi bị tấn công có 30% (nhân đôi là 60%) xác suất tiêu hao <may mắn> để chặn 50% sát thương lần này',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Grant <Luck> to 2 random allies for 2 turns\n#F20# \n#F40##C0x5c9970#→Grant <Luck> to 2 random allies for 3 turns',
