	[8626] = {
		id = 8626,
		skillName_vn = 'Phúc lành',
		skillName_en = 'Blessing',
		skillName_th = 'พร',
		skillName_in = 'Berkah',
		skillName_ph = 'Basbas',
		skillName_ma = 'Berkat',
		skillName = 'Blessing',
		describe_vn = 'Kỹ năng hào quang: Trước mỗi lần hành động của đơn vị phe ta, có #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# xác suất nhận [Phước lành] trong 1 lượt (kéo dài đến khi kết thúc vòng lớn hiện tại), đối với đồng đội có [May mắn], hiệu quả của [Phước lành] sẽ được nhân đôi\n#F20# \n#F40#[Phước lành]: Hiệu ứng tăng cường, tăng Công Phép và phòng phép của mục tiêu (mức tăng là 10% thuộc tính tương ứng của Togetic, nhân đôi là 20%)',
		describe_en = 'Aura Skill: Before each action of our faction\'s unit, there is a #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# chance to receive [Blessing] for 1 turn (lasting until the end of the current major round). For allies with [Luck], the effect of [Blessing] is doubled \n#F20# \n#F40#[Blessing]: A buff effect that increases Magic Attack and Magic Defense of the target (the increase is 10% of Togetic\'s corresponding attribute, doubled to 20%).',
		describe_th = 'สกิลออร่า: ก่อนที่หน่วยฝ่ายเราจะทำการกระทำแต่ละครั้ง มีโอกาส #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# ในการได้รับ [พร] เป็นเวลา 1 เทิร์น (ต่อเนื่องจนจบรอบใหญ่ในปัจจุบัน) สำหรับพันธมิตรที่มี [โชค] ผลของ [พร] จะถูกเพิ่มเป็นสองเท่า \n#F20# \n#F40#[พร]: เอฟเฟกต์บัฟที่เพิ่มพลังเวทและพลังป้องกันเวทของเป้าหมาย (การเพิ่มขึ้นคือ 10% ของค่าสถานะที่เกี่ยวข้องของ Togetic เพิ่มขึ้นเป็นสองเท่าเป็น 20%)',
		describe_in = 'Skill Aura: Sebelum setiap kali unit pihak kita bertindak, ada #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# peluang untuk menerima [Berkat] selama 1 giliran (bertahan sampai akhir ronde besar saat ini). Untuk rekan tim yang memiliki [Keberuntungan], efek [Berkat] akan digandakan \n#F20# \n#F40#[Berkat]: Efek peningkatan yang meningkatkan Serangan Magis dan Pertahanan Magis target (peningkatan adalah 10% atribut terkait Togetic, digandakan menjadi 20%).',
		describe_ph = 'Aura Skill: Bago bawat aksyon ng unit ng ating panig, mayroong #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# tsansang makatanggap ng [Pagpalang] sa loob ng 1 turn (tumagal hanggang sa matapos ang kasalukuyang malaking round). Para sa mga kakampi na may [Swerte], ang bisa ng [Pagpalang] ay dodoblehin \n#F20# \n#F40#[Pagpalang]: Isang buff effect na nagpapataas ng Magic Attack at Magic Defense ng target (ang pagtaas ay 10% ng kaugnay na attribute ng Togetic, dodoblehin hanggang 20%).',
		describe_ma = 'Kemahiran Aura: Sebelum setiap tindakan unit pihak kita, terdapat #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# peluang untuk menerima [Berkat] selama 1 giliran (berlanjutan sehingga tamat pusingan utama semasa). Bagi rakan sepasukan yang mempunyai [Nasib], keberkesanan [Berkat] akan digandakan \n#F20# \n#F40#[Berkat]: Kesan pengukuhan yang meningkatkan Serangan Sihir dan Pertahanan Sihir sasaran (peningkatan adalah 10% atribut yang berkaitan Togetic, digandakan menjadi 20%).',
		describe = 'Aura Skill: Before each action of our faction\'s unit, there is a #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# chance to receive [Blessing] for 1 turn (lasting until the end of the current major round). For allies with [Luck], the effect of [Blessing] is doubled \n#F20# \n#F40#[Blessing]: A buff effect that increases Magic Attack and Magic Defense of the target (the increase is 10% of Togetic\'s corresponding attribute, doubled to 20%).',
		starEffect = __data_t__starEffect[8626],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Khi <phúc lành> kết thúc, hồi phục 30% sức tấn Công Phép thuật cho đơn vị có máu thấp nhất trong đội (tương tự như trên).',
		starEffectDesc = 'Enhance effects: When <blessing> ends, restore 30% Magic Attack health to the unit with the lowest HP in the team (same as above).',
		starEffectDesc_en = 'Enhance effects: When <blessing> ends, restore 30% Magic Attack health to the unit with the lowest HP in the team (same as above).',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: เมื่อ <phúc lành> สิ้นสุดลง ฟื้นฟูพลังโจมตีเวทมนตร์ 30% ให้กับหน่วยที่มีพลังชีวิตต่ำสุดในทีม (เหมือนข้างต้น)',
		starEffectDesc_in = 'Perkuat efek: Saat <phúc lành> berakhir, pulihkan 30% Kekuatan Serangan Sihir untuk unit dengan HP terendah di tim (sama seperti di atas).',
		starEffectDesc_ph = 'Palakasin ang epekto: Kapag natapos ang <phúc lành>, ibalik ang 30% Magic Attack health sa yunit na may pinakamababang HP sa koponan (katulad ng nasa itaas).',
		starEffectDesc_ma = 'Perkuat kesan: Apabila <phúc lành> berakhir, pulihkan 30% Serangan Sihir kepada unit yang mempunyai HP terendah dalam pasukan (sama seperti di atas).',
		zawakeEffect = __data_t__zawakeEffect[8626],
		-- {79004, 1}
		zawakeEffectDesc = 'Enhance effect: When <blessing> ends, restore 30% Magic Power of Togepi to the ally with the lowest HP, each blessing recovery increases the healing rate for the target by 5% for 2 turns, stacking up to 6 times',
		zawakeEffectDesc_en = 'Enhance effect: When <blessing> ends, restore 30% Magic Power of Togepi to the ally with the lowest HP, each blessing recovery increases the healing rate for the target by 5% for 2 turns, stacking up to 6 times',
		zawakeEffectDesc_th = 'เพิ่มประสิทธิภาพ: เมื่อ <phước lành> สิ้นสุด ฟื้นฟูพลังเวทย์ 30% ของ Togepi ให้หน่วยที่มี HP ต่ำที่สุดของฝ่ายเรา ทุกครั้งที่ฟื้นฟู phước lành จะเพิ่มอัตราการฟื้นฟูให้กับเป้าหมาย 5% เป็นเวลา 2 เทิร์น สูงสุดสะสมได้ 6 ครั้ง',
		zawakeEffectDesc_in = 'Tingkatkan efek: Ketika <phước lành> berakhir, pulihkan 30% Kekuatan Sihir Togepi kepada unit dengan HP terendah dari pihak kita, setiap pemulihan phước lành akan meningkatkan tingkat pemulihan untuk target sebesar 5% selama 2 giliran, maksimal menumpuk 6 kali',
		zawakeEffectDesc_ph = 'Palakasin ang epekto: Kapag natapos ang <phước lành>, ibalik ang 30% Magic Power ni Togepi sa yunit na may pinakamababang HP sa sariling pangkat, bawat pagpapagaling ng phước lành ay nagdaragdag ng 5% na tsansa ng paggaling para sa target sa loob ng 2 turn, hanggang 6 na beses na pwedeng maipon',
		zawakeEffectDesc_ma = 'Tingkatkan kesan: Apabila <phước lành> berakhir, pulihkan 30% Kuasa Sihir Togepi kepada unit dengan HP terendah dalam pihak kita, setiap pemulihan phước lành akan meningkatkan kadar pemulihan untuk sasaran sebanyak 5% selama 2 giliran, maksimum bertindih 6 kali',
		zawakeEffectDesc_vn = 'Tăng cường hiệu ứng: Khi <phước lành> kết thúc, hồi phục 30% Công Phép của Togepi cho đơn vị có HP thấp nhất của phe mình, mỗi lần hồi phục phước lành sẽ tăng 5% tỷ lệ nhận hồi phục cho mục tiêu trong 2 lượt, tối đa cộng dồn 6 lần',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Each time healed by blessing increases the healing received rate of the target by 5% for 2 turns, up to 6 stacks',
		zawakeSimpleDesc_en = '#C0x5c9970#Each time healed by blessing increases the healing received rate of the target by 5% for 2 turns, up to 6 stacks',
		zawakeSimpleDesc_th = '#C0x5c9970#ทุกครั้งที่ฟื้นฟูด้วยพร จะเพิ่มอัตราการฟื้นฟูของเป้าหมาย 5% เป็นเวลา 2 เทิร์น สะสมได้สูงสุด 6 ครั้ง',
		zawakeSimpleDesc_in = '#C0x5c9970#Setiap kali dipulihkan oleh Berkat, meningkatkan rasio pemulihan yang diterima oleh target sebesar 5% selama 2 giliran, maksimal 6 tumpukan',
		zawakeSimpleDesc_ph = '#C0x5c9970#Tuwing gumagaling gamit ang Basbas, nadaragdagan ang rate ng recovery ng target ng 5% sa loob ng 2 turn, hanggang 6 na ulit',
		zawakeSimpleDesc_ma = '#C0x5c9970#Setiap kali dipulihkan dengan Berkat, kadar penerimaan pemulihan sasaran meningkat 5% selama 2 giliran, maksimum 6 kali',
		zawakeSimpleDesc_vn = '#C0x5c9970#Mỗi lần hồi phục bằng phước lành sẽ tăng 5% tỷ lệ nhận hồi phục cho mục tiêu trong 2 lượt, tối đa cộng dồn 6 lần',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
