	[8813] = {
		id = 8813,
		skillName_vn = 'Tĩnh điện bông gòn',
		skillName_en = 'Cotton static electricity',
		skillName_th = 'ไฟฟ้าสถิตใยฝ้าย',
		skillName_in = 'Listrik statis kapas',
		skillName_ph = 'Kuryenteng estatik na bulak',
		skillName_ma = 'Elektrik statik kapas',
		skillName = 'Cotton static electricity',
		describe_vn = 'Mareep dùng lông mềm mại giải phóng dòng điện tấn công mục tiêu hàng dọc địch, gây #C0x3D8A99#200% Phép Công#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, có 40% xác suất thêm [Cảm Điện] cho mục tiêu trong 2 lượt; đồng thời hồi phục 100 nộ khí cho đồng đội, anh hùng hệ Lôi hồi phục thêm 100 nộ khí',
		describe_en = 'Mareep uses its soft wool to release electric currents, attacking enemy targets in a vertical line, dealing #C0x3D8A99#200% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 40% chance to apply [Electrified] to the target for 2 turns; meanwhile, it restores 100 energy to allies, and Thunder-type heroes recover an additional 100 energy.',
		describe_th = 'มารีปใช้ขนที่นุ่มนวลปล่อยกระแสไฟฟ้าโจมตีเป้าหมายในแนวดิ่งของศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#200% พลังโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# มีโอกาส 40% ที่จะเพิ่มสถานะ [ช็อตไฟฟ้า] ให้เป้าหมายเป็นเวลา 2 เทิร์น; พร้อมกันนั้น ฟื้นฟูพลังงาน 100 ให้กับทีม และฮีโร่ธาตุสายสายฟ้าจะได้รับพลังงานเพิ่มอีก 100',
		describe_in = 'Mareep menggunakan wol lembutnya untuk melepaskan arus listrik menyerang target musuh secara vertikal, memberikan #C0x3D8A99#200% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Damage Magis #C0x5B545B#, dengan 40% peluang memberikan [Kejutan Listrik] pada target selama 2 giliran; sekaligus memulihkan 100 energi untuk tim, pahlawan tipe Petir memulihkan energi tambahan 100.',
		describe_ph = 'Gumagamit si Mareep ng malambot na balahibo para magpalabas ng kuryente na umaatake sa mga kalaban sa patayong linya, nagdudulot ng #C0x3D8A99#200% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, may 40% tsansa na maglagay ng [Electrified] sa target sa loob ng 2 turn; kasabay nito, nagpapagaling ng 100 enerhiya sa mga kaalyado, at ang mga Thunder-type heroes ay nakakabawi ng dagdag na 100 enerhiya.',
		describe_ma = 'Mareep menggunakan bulu lembutnya untuk melepaskan arus elektrik menyerang musuh dalam barisan menegak, memberikan #C0x3D8A99#200% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, dengan 40% peluang untuk memberikan [Kejutan Elektrik] kepada sasaran selama 2 giliran; pada masa yang sama memulihkan 100 tenaga untuk rakan sepasukan, wira jenis Kilat memulihkan 100 tenaga tambahan.',
		describe = 'Mareep uses its soft wool to release electric currents, attacking enemy targets in a vertical line, dealing #C0x3D8A99#200% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 40% chance to apply [Electrified] to the target for 2 turns; meanwhile, it restores 100 energy to allies, and Thunder-type heroes recover an additional 100 energy.',
		simDesc_vn = 'Mareep dùng lông mềm mại phát ra điện tấn công mục tiêu hàng ngang của đối phương, có khả năng gây hiệu ứng cảm điện cho mục tiêu và hồi phục năng lượng cho đồng đội.',
		simDesc_en = 'Mareep uses its soft wool to generate electricity and attack the enemy\'s horizontal target line, with the ability to inflict an electric shock effect on the target and restore energy for allies.',
		simDesc_th = 'มารีปใช้ขนที่นุ่มนวลของมันสร้างไฟฟ้าโจมตีเป้าหมายแนวนอนของศัตรู โดยมีความสามารถทำให้เกิดผลช็อตไฟฟ้ากับเป้าหมายและฟื้นฟูพลังงานให้กับพันธมิตร',
		simDesc_in = 'Mareep menggunakan bulu lembutnya untuk menghasilkan listrik menyerang baris target horizontal musuh, dengan kemampuan menyebabkan efek kejutan listrik pada target dan memulihkan energi untuk rekan satu tim.',
		simDesc_ph = 'Gumagamit ang Mareep ng malambot nitong balahibo upang maglabas ng kuryente at atakihin ang pahalang na linya ng target ng kalaban, may kakayahang magdulot ng epekto ng electric shock sa target at magpagaling ng enerhiya para sa mga kakampi.',
		simDesc_ma = 'Mareep menggunakan bulu lembutnya untuk menghasilkan elektrik menyerang barisan sasaran mendatar musuh, dengan keupayaan menyebabkan kesan kejutan elektrik pada sasaran dan memulihkan tenaga untuk rakan sepasukan.',
		simDesc = 'Mareep uses its soft wool to generate electricity and attack the enemy\'s horizontal target line, with the ability to inflict an electric shock effect on the target and restore energy for allies.',
		starEffect = __data_t__starEffect[8813],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Có 60% xác suất thêm <cảm điện> cho mục tiêu trong 2 lượt; và hồi phục 150 điểm năng lượng cho đồng đội, các anh hùng hệ sấm sét hồi phục thêm 150 điểm năng lượng.',
		starEffectDesc = 'Enhance effect: 60% chance to add <cảm điện> to the target for 2 turns; and restore 150 energy points to teammates, thunder heroes restore an additional 150 energy points.',
		starEffectDesc_en = 'Enhance effect: 60% chance to add <cảm điện> to the target for 2 turns; and restore 150 energy points to teammates, thunder heroes restore an additional 150 energy points.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: มีโอกาส 60% ที่จะเพิ่ม <cảm điện> ให้เป้าหมายเป็นเวลา 2 รอบ; และฟื้นฟูพลังงาน 150 แต้มให้กับเพื่อนร่วมทีม, ฮีโร่ระบบสายฟ้าฟื้นฟูพลังงานเพิ่ม 150 แต้ม',
		starEffectDesc_in = 'Tingkatkan efek: 60% kesempatan menambahkan <cảm điện> ke target selama 2 giliran; dan memulihkan 150 poin energi untuk rekan tim, pahlawan sistem petir memulihkan tambahan 150 poin energi.',
		starEffectDesc_ph = 'Palakasin ang epekto: 60% tsansa na magdagdag ng <cảm điện> sa target sa loob ng 2 turn; at magpagaling ng 150 puntos ng enerhiya para sa mga kakampi, ang mga bayani ng sistemang kidlat ay nakakabawi ng karagdagang 150 puntos ng enerhiya.',
		starEffectDesc_ma = 'Meningkatkan kesan: 60% peluang untuk menambah <cảm điện> kepada sasaran selama 2 pusingan; dan memulihkan 150 mata tenaga kepada rakan sepasukan, wira sistem kilat memulihkan tambahan 150 mata tenaga.',
		zawakeEffect = __data_t__zawakeEffect[8813],
		-- {79003}
		zawakeEffectDesc = 'Mareep uses soft wool to release electric currents attacking the enemy\'s horizontal targets, causing #C0x3D8A99#200% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ magic damage#C0xF13B54#,#C0x5B545B# with a 100% chance to add <Electric Shock> to the target for 2 turns; and restores 100 rage to allies, lightning heroes restore an additional 100 rage points',
