	[8826] = {
		id = 8826,
		skillName_vn = 'Kích thích năng lượng điện',
		skillName_en = 'Electric energy stimulation',
		skillName_th = 'การกระตุ้นพลังงานไฟฟ้า',
		skillName_in = 'Stimulasi energi listrik',
		skillName_ph = 'Pagsigla ng enerhiya ng kuryente',
		skillName_ma = 'Rangsangan tenaga elektrik',
		skillName = 'Electric energy stimulation',
		describe_vn = 'Mỗi lượt ngẫu nhiên thêm [Cảm điện] cho một kẻ địch (Cảm điện: hiệu ứng đặc biệt);\nKỹ năng hào quang: Khi anh hùng [Cảm điện] tấn công anh hùng phe ta, anh hùng phe ta và Cừu lông mềm hồi phục thêm #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B# nộ khí',
		describe_en = 'Each turn, randomly add [Electrified] to one enemy (Electrified: special effect);\nAura skill: When an [Electrified] enemy hero attacks our hero, our hero and Soft Wool Sheep recover #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B# rage.',
		describe_th = 'ทุกตา สุ่มเพิ่ม [ช็อตไฟฟ้า] ให้กับศัตรูหนึ่งตัว (ช็อตไฟฟ้า: เอฟเฟกต์พิเศษ);\nทักษะออร่า: เมื่อฮีโร่ฝ่ายศัตรูที่ติดสถานะ [ช็อตไฟฟ้า] โจมตีฮีโร่ฝ่ายเรา ฮีโร่ฝ่ายเราและแกะขนฟูจะฟื้นฟูพลังแค้นเพิ่มอีก #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B#',
		describe_in = 'Setiap giliran, secara acak tambahkan [Tersengat Listrik] ke satu musuh (Tersengat Listrik: efek khusus);\nKemampuan aura: Ketika pahlawan musuh yang [Tersengat Listrik] menyerang pahlawan kita, pahlawan kita dan Domba Berbulu Lembut memulihkan #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B# amarah.',
		describe_ph = 'Bawat turn, random na magdagdag ng [Electrified] sa isang kalaban (Electrified: espesyal na epekto);\nAura skill: Kapag ang [Electrified] na kaaway na hero ay umatake sa aming hero, ang aming hero at ang Soft Wool Sheep ay nakakabawi ng #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B# na galit.',
		describe_ma = 'Setiap pusingan, secara rawak tambah [Kejutan Elektrik] kepada seorang musuh (Kejutan Elektrik: kesan khas);\nKemahiran aura: Apabila wira musuh yang [Kejutan Elektrik] menyerang wira kami, wira kami dan Kambing Bulu Lembut memulihkan #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B# kemarahan.',
		describe = 'Each turn, randomly add [Electrified] to one enemy (Electrified: special effect);\nAura skill: When an [Electrified] enemy hero attacks our hero, our hero and Soft Wool Sheep recover #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B# rage.',
		starEffect = __data_t__starEffect[8826],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Khi các anh hùng <cảm điện> tấn công mục tiêu hệ sấm sét, hồi phục năng lượng tăng lên $(60 + skillLevel * 0.1 - 0.1)$ điểm.',
		starEffectDesc = 'Enhance effect: When heroes <cảm điện> attack thunder-type targets, energy recovery increases by $(60 + skillLevel * 0.1 - 0.1)$ points.',
		starEffectDesc_en = 'Enhance effect: When heroes <cảm điện> attack thunder-type targets, energy recovery increases by $(60 + skillLevel * 0.1 - 0.1)$ points.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: เมื่อฮีโร่ <cảm điện> โจมตีเป้าหมายประเภทสายฟ้า การฟื้นฟูพลังงานจะเพิ่มขึ้น $(60 + skillLevel * 0.1 - 0.1)$ คะแนน',
		starEffectDesc_in = 'Meningkatkan efek: Ketika para pahlawan <cảm điện> menyerang target tipe petir, pemulihan energi meningkat sebesar $(60 + skillLevel * 0.1 - 0.1)$ poin.',
		starEffectDesc_ph = 'Pahusayin ang epekto: Kapag ang mga bayani <cảm điện> ay umatake sa mga target na uri ng kidlat, tumataas ang pag-recover ng enerhiya ng $(60 + skillLevel * 0.1 - 0.1)$ puntos.',
		starEffectDesc_ma = 'Tingkatkan kesan: Apabila wira <cảm điện> menyerang sasaran jenis petir, pemulihan tenaga meningkat sebanyak $(60 + skillLevel * 0.1 - 0.1)$ mata.',
		zawakeEffect = __data_t__zawakeEffect[8826],
		-- {79004}
		zawakeEffectDesc = 'Each turn randomly adds <Cảm điện> to one enemy (Cảm điện: special effect), 50% chance to add <Cảm điện> to another enemy; Aura skill: When a <Cảm điện> hero attacks our hero, our hero and Dê Dê Dê recover #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B# rage points',
		zawakeEffectDesc_en = 'Each turn randomly adds <Cảm điện> to one enemy (Cảm điện: special effect), 50% chance to add <Cảm điện> to another enemy; Aura skill: When a <Cảm điện> hero attacks our hero, our hero and Dê Dê Dê recover #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B# rage points',
		zawakeEffectDesc_th = 'ทุกเทิร์นสุ่มเพิ่ม <Cảm điện> ให้ศัตรูหนึ่งตัว (Cảm điện: เอฟเฟกต์พิเศษ), มีโอกาส 50% ที่จะเพิ่ม <Cảm điện> ให้ศัตรูอีกตัว; ทักษะออร่า: เมื่อตัวละคร <Cảm điện> โจมตีตัวละครฝ่ายเรา ตัวละครฝ่ายเราและ Dê Dê Dê ฟื้นฟูพลังแค้น #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B#',
		zawakeEffectDesc_in = 'Setiap giliran secara acak menambahkan <Cảm điện> ke satu musuh (Cảm điện: efek khusus), 50% peluang untuk menambahkan <Cảm điện> ke musuh lain; Skill aura: Ketika pahlawan <Cảm điện> menyerang pahlawan kita, pahlawan kita dan Dê Dê Dê memulihkan #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B# poin kemarahan',
		zawakeEffectDesc_ph = 'Bawat turn ay random na magdaragdag ng <Cảm điện> sa isang kalaban (Cảm điện: espesyal na epekto), 50% tsansa na magdagdag ng <Cảm điện> sa isa pang kalaban; Kasanayang aura: Kapag ang bayani na <Cảm điện> ay umatake sa ating bayani, ang ating bayani at Dê Dê Dê ay magre-recover ng #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B# puntos ng galit',
		zawakeEffectDesc_ma = 'Setiap giliran secara rawak menambah <Cảm điện> kepada satu musuh (Cảm điện: kesan khas), 50% peluang untuk menambah <Cảm điện> kepada musuh lain; Kemahiran aura: Apabila wira <Cảm điện> menyerang wira pihak kita, wira pihak kita dan Dê Dê Dê pulih #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B# mata kemarahan',
		zawakeEffectDesc_vn = 'Mỗi lượt ngẫu nhiên thêm <Cảm điện> cho một kẻ địch (Cảm điện: hiệu ứng đặc biệt), có 50% cơ hội thêm <Cảm điện> cho một kẻ địch khác;Kỹ năng hào quang: Khi anh hùng <Cảm điện> tấn công anh hùng phe ta, anh hùng phe ta và Dê Dê Dê hồi phục thêm #C0x5c9970#$(40+skillLevel*0.1-0.1)$#C0x5B545B# điểm nộ khí',
		zawakeSimpleType = 1,
