		skillName_ph = 'Hangin na malakas na parang kulog',
		skillName_ma = 'Angin kuat seperti guruh',
		skillName = 'Wind strong as thunder',
		describe_vn = 'Killua hóa thân thành sấm sét, tấn công mục tiêu hàng dọc địch với tốc độ chớp nhoáng, gây #C0x3D8A99#340% Phép Công#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, 40% xác suất thêm [Cảm điện] cho mục tiêu trong 2 lượt; đồng thời hồi phục 100 nộ khí cho đồng đội, anh hùng hệ Lôi hồi phục thêm 100 nộ khí',
		describe_en = 'Killua transforms into lightning, attacking enemies in a vertical line with lightning-fast speed, dealing #C0x3D8A99#340% Magic Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Magic Damage#C0x5B545B#, 40% chance to inflict [Electrocution] on the target for 2 turns; simultaneously restores 100 energy to allies, and Thunder-type heroes recover an additional 100 energy.',
		describe_th = 'คิลัวเปลี่ยนร่างเป็นสายฟ้าโจมตีเป้าหมายเป็นแนวดิ่งด้วยความเร็วแสง ฟาดฟันสร้างความเสียหายเวทย์ #C0x3D8A99#340% พลังเวทย์#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#ความเสียหายเวทย์#C0x5B545B# มีโอกาส 40% ที่จะทำให้เป้าหมายติดสถานะ [ช็อตไฟฟ้า] เป็นเวลา 2 เทิร์น พร้อมฟื้นฟูพลังงาน 100 หน่วยให้กับเพื่อนร่วมทีม และฮีโร่สายสายฟ้าจะได้รับพลังงานเพิ่มอีก 100 หน่วย',
		describe_in = 'Killua bertransformasi menjadi kilat, menyerang target dalam satu garis vertikal dengan kecepatan kilat, memberikan #C0x3D8A99#340% Serangan Sihir#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Kerusakan Sihir#C0x5B545B#, peluang 40% menambahkan efek [Kejutan Listrik] pada target selama 2 giliran; sekaligus memulihkan 100 energi untuk rekan satu tim, pahlawan tipe Petir memulihkan 100 energi tambahan.',
		describe_ph = 'Nagtransform si Killua bilang kidlat, umaatake ng mga target sa isang patayong linya ng kislap-agad na bilis, na nagdudulot ng #C0x3D8A99#340% Magic Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Magic Damage#C0x5B545B#, 40% na tsansa na maglagay ng [Electrocution] sa target sa loob ng 2 turn; kasabay nito, nagrerestore ng 100 energy sa mga kakampi, at mga Thunder-type heroes ay nakakaramdam ng dagdag na 100 energy.',
		describe_ma = 'Killua berubah menjadi kilat, menyerang sasaran dalam garisan menegak dengan kelajuan kilat, menyebabkan #C0x3D8A99#340% Serangan Sihir#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Kerosakan Sihir#C0x5B545B#, 40% kemungkinan menambah [Kejutan Elektrik] ke sasaran selama 2 giliran; pada masa yang sama memulihkan 100 tenaga untuk rakan sepasukan, wira jenis Kilat memulihkan tambahan 100 tenaga.',
		describe = 'Killua transforms into lightning, attacking enemies in a vertical line with lightning-fast speed, dealing #C0x3D8A99#340% Magic Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Magic Damage#C0x5B545B#, 40% chance to inflict [Electrocution] on the target for 2 turns; simultaneously restores 100 energy to allies, and Thunder-type heroes recover an additional 100 energy.',
		simDesc_vn = 'Killua hóa thân thành sấm sét, tấn công mục tiêu hàng ngang của đối phương với tốc độ chớp nhoáng, có khả năng gây hiệu ứng cảm điện cho mục tiêu và hồi phục năng lượng cho đồng đội.',
		simDesc_en = 'Killua transforms into lightning, attacking the enemy\'s horizontal targets at lightning speed, capable of inflicting electric shock effects on targets and restoring energy for teammates.',
		simDesc_th = 'Killua แปลงร่างเป็นสายฟ้า โจมตีเป้าหมายในแนวขวางของฝ่ายตรงข้ามด้วยความเร็ววาบฟ้า มีความสามารถทำให้เป้าหมายเกิดผลกระทบจากไฟฟ้าและฟื้นฟูพลังงานให้เพื่อนร่วมทีม',
		simDesc_in = 'Killua berubah menjadi petir, menyerang target horizontal musuh dengan kecepatan kilat, mampu memberikan efek kejutan listrik pada target dan memulihkan energi untuk rekan tim.',
		simDesc_ph = 'Nagbabago si Killua bilang kidlat, umatake sa horizontal na mga target ng kalaban nang napakabilis, may kakayahang magdulot ng electric shock effect sa mga target at mag-recover ng enerhiya para sa mga kakampi.',
		simDesc_ma = 'Killua berubah menjadi kilat, menyerang sasaran barisan mendatar musuh dengan kelajuan pantas, mampu memberikan kesan kejutan elektrik kepada sasaran dan memulihkan tenaga untuk rakan sepasukan.',
		simDesc = 'Killua transforms into lightning, attacking the enemy\'s horizontal targets at lightning speed, capable of inflicting electric shock effects on targets and restoring energy for teammates.',
		starEffect = __data_t__starEffect[8833],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Có 60% xác suất thêm <cảm điện> cho mục tiêu trong 2 lượt; và hồi phục 150 điểm năng lượng cho đồng đội, các anh hùng hệ sấm sét hồi phục thêm 150 điểm năng lượng.',
		starEffectDesc = 'Enhance effect: 60% chance to add <cảm điện> to the target for 2 turns; and restore 150 energy points to teammates, thunder-type heroes restore an additional 150 energy points.',
		starEffectDesc_en = 'Enhance effect: 60% chance to add <cảm điện> to the target for 2 turns; and restore 150 energy points to teammates, thunder-type heroes restore an additional 150 energy points.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: มีโอกาส 60% ที่จะใส่สถานะ [ช็อต] ให้กับเป้าหมายเป็นเวลา 2 เทิร์น และฟื้นฟูโทสะ 150 หน่วยให้เพื่อนร่วมทีม ฮีโร่สายสายฟ้าจะฟื้นฟูโทสะเพิ่มเติมอีก 150 หน่วย',
		starEffectDesc_in = 'Tingkatkan efek: Peluang 60% untuk menambahkan <cảm điện> pada target selama 2 giliran; dan mengembalikan 150 poin energi untuk rekan satu tim, pahlawan tipe petir mengembalikan tambahan 150 poin energi.',
		starEffectDesc_ph = 'Palakasin ang epekto: 60% tsansa na magdagdag ng <cảm điện> sa target sa loob ng 2 rounds; at magpagaling ng 150 puntos ng enerhiya sa mga kasama, ang mga bayani ng kidlat ay magpapagaling pa ng karagdagang 150 puntos ng enerhiya.',
		starEffectDesc_ma = 'Tingkatkan kesan: Peluang 60% menambah <cảm điện> pada sasaran selama 2 giliran; dan memulihkan 150 mata tenaga kepada ahli pasukan, wira petir memulihkan tambahan 150 mata tenaga.',
		zawakeEffect = __data_t__zawakeEffect[8833],
		-- {79003}
		zawakeEffectDesc = 'Killua transforms into lightning, with lightning-fast speed attacking a horizontal line of enemy targets, dealing #C0x3D8A99#340% Magical Attack#C0x5B545B#+$(skillLevel*4*75)$ Magical Damage#C0x5B545B#, 100% chance to apply <Electrocution> to targets for 2 turns; and restores 100 rage to teammates, Thunder element heroes restore an additional 100 rage points',
		zawakeEffectDesc_en = 'Killua transforms into lightning, with lightning-fast speed attacking a horizontal line of enemy targets, dealing #C0x3D8A99#340% Magical Attack#C0x5B545B#+$(skillLevel*4*75)$ Magical Damage#C0x5B545B#, 100% chance to apply <Electrocution> to targets for 2 turns; and restores 100 rage to teammates, Thunder element heroes restore an additional 100 rage points',
		zawakeEffectDesc_th = 'คิลลัวเปลี่ยนร่างเป็นสายฟ้า กับความเร็วว่องไวราวกับฟ้าผ่า โจมตีเป้าหมายแนวนอนของศัตรู ทำให้เกิด #C0x3D8A99#340% พลังโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*75)$ ความเสียหายเวทมนตร์#C0x5B545B# โอกาส 100% เพิ่ม <Cảm điện> ให้เป้าหมาย 2 เทิร์น; และฟื้นฟู 100 โกรธให้กับเพื่อนร่วมทีม ฮีโร่ธาตุสายฟ้าฟื้นฟูเพิ่มอีก 100 โกรธ',
		zawakeEffectDesc_in = 'Killua berubah menjadi petir, dengan kecepatan secepat kilat menyerang baris horizontal target musuh, menghasilkan #C0x3D8A99#340% Serangan Magical#C0x5B545B#+$(skillLevel*4*75)$ Kerusakan Magical#C0x5B545B#, kesempatan 100% menambahkan <Cảm điện> pada target selama 2 giliran; dan memulihkan 100 kemarahan untuk rekan tim, pahlawan elemen petir memulihkan tambahan 100 poin kemarahan',
		zawakeEffectDesc_ph = 'Nagiging kidlat si Killua, gamit ang bilis ng kidlat, umaatake sa pahalang na hanay ng mga target ng kalaban, nagdudulot ng #C0x3D8A99#340% Magical Attack#C0x5B545B#+$(skillLevel*4*75)$ Magical Damage#C0x5B545B#, 100% tsansa na magdagdag ng <Cảm điện> sa mga target sa loob ng 2 turn; at nagpapagaling ng 100 ng galit para sa mga kasama sa koponan, ang mga bayani ng elementong kidlat ay nagpapagaling pa ng 100 puntos ng galit',
