		skillName = 'Electric dragon roars',
		describe_vn = 'Siêu Điện Long tụ hội một con rồng điện vàng, tấn công mục tiêu hàng dọc của kẻ địch, gây #C0x3D8A99#220% Phép Công#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, thêm [Cảm Điện] cho mục tiêu trong 2 lượt; đồng thời hồi phục 150 nộ khí cho đồng đội, anh hùng hệ Lôi hồi phục thêm 150 điểm nộ khí',
		describe_en = 'Super Electric Dragon gathers a golden electric dragon, attacking the enemy\'s vertical targets, dealing #C0x3D8A99#220% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, inflicting [Electrify] on the target for 2 turns; simultaneously restoring 150 energy to allies, and lightning-type heroes restore an additional 150 energy.',
		describe_th = 'ซูเปอร์มังกรไฟฟ้ารวมตัวมังกรไฟฟ้าสีทอง โจมตีเป้าหมายในแนวตั้งของศัตรู สร้างความเสียหาย #C0x3D8A99#220% พลังเวท#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# เพิ่ม [Cảm Điện] ให้เป้าหมายเป็นเวลา 2 เทิร์น; พร้อมกันนี้ฟื้นฟูพลังงาน 150 หน่วยให้กับเพื่อนร่วมทีม และฮีโร่ระบบสายฟ้าฟื้นฟูพลังงานเพิ่มอีก 150 หน่วย',
		describe_in = 'Naga Listrik Super mengumpulkan seekor naga listrik emas, menyerang target vertikal musuh, memberikan #C0x3D8A99#220% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Damage Sihir #C0x5B545B#, menambahkan [Electrify] pada target selama 2 giliran; sekaligus memulihkan 150 energi untuk sekutu, dan pahlawan tipe petir memulihkan tambahan 150 energi.',
		describe_ph = 'Nagtipon ang Super Electric Dragon ng isang gintong electric dragon, inaatake ang mga patayong target ng kalaban, nagdudulot ng #C0x3D8A99#220% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, nagdaragdag ng [Electrify] sa target sa loob ng 2 turn; kasabay nito ay nagpapagaling ng 150 energy para sa mga kakampi, at ang mga bayani na may kuryenteng tipo ay nakakabawi ng dagdag na 150 energy.',
		describe_ma = 'Naga Elektrik Super mengumpulkan seekor naga elektrik emas, menyerang sasaran menegak musuh, menyebabkan #C0x3D8A99#220% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, menambah [Electrify] pada sasaran selama 2 giliran; pada masa yang sama memulihkan 150 tenaga untuk rakan sepasukan, wira jenis Kilat memulihkan tambahan 150 tenaga.',
		describe = 'Super Electric Dragon gathers a golden electric dragon, attacking the enemy\'s vertical targets, dealing #C0x3D8A99#220% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, inflicting [Electrify] on the target for 2 turns; simultaneously restoring 150 energy to allies, and lightning-type heroes restore an additional 150 energy.',
		simDesc_vn = 'Super Electrode triệu hồi một con rồng điện vàng, tấn công mục tiêu hàng ngang của đối phương, gây sát thương phép thuật, thêm hiệu ứng [Cảm Điện] cho mục tiêu và hồi phục năng lượng cho đồng đội.',
		simDesc_en = 'Super Electrode summons a golden electric dragon, attacks a horizontal row of enemy targets, deals magic damage, applies the <Electrified> effect to targets, and restores energy for allies.',
		simDesc_th = 'ซูเปอร์อิเล็กโทรดเรียกมังกรไฟฟ้าสีทอง โจมตีเป้าหมายแบบแถวแนวนอนของศัตรู สร้างความเสียหายเวทย์ เพิ่มสถานะ [ถูกช็อตไฟฟ้า] ให้เป้าหมาย และฟื้นฟูพลังงานให้กับทีม',
		simDesc_in = 'Super Electrode memanggil naga listrik emas, menyerang baris horizontal musuh, memberikan damage sihir, menambahkan efek <Kejutan Listrik> pada target, dan memulihkan energi untuk sekutu.',
		simDesc_ph = 'Ang Super Electrode ay nagpapatawag ng gintong electric dragon, umaatake sa pahalang na hanay ng mga kalaban, nagdudulot ng magic na pinsala, naglalagay ng epekto na <Electrified> sa mga target, at nagpapagaling ng enerhiya para sa mga kaalyado.',
		simDesc_ma = 'Super Electrode memanggil seekor naga elektrik emas, menyerang barisan mendatar musuh, memberikan kerosakan magik, menambah kesan <Kejutan Elektrik> pada sasaran dan memulihkan tenaga untuk rakan sepasukan.',
		simDesc = 'Super Electrode summons a golden electric dragon, attacks a horizontal row of enemy targets, deals magic damage, applies the [Electrified] effect to targets, and restores energy for allies.',
		starEffect = __data_t__starEffect[8843],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Tăng 20% sát thương kỹ năng chí mạng cho toàn bộ đồng minh trong lượt tiếp theo, các anh hùng hệ sấm sét tăng thêm 10%.',
		starEffectDesc = 'Additional effect: Increases critical skill damage by 20% for all allies in the next turn, heroes of the Lightning system gain an extra 10%.',
		starEffectDesc_en = 'Additional effect: Increases critical skill damage by 20% for all allies in the next turn, heroes of the Lightning system gain an extra 10%.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เพิ่มความเสียหายสกิลคริติคอล 20% สำหรับพันธมิตรทั้งหมดในรอบถัดไป ฮีโร่ระบบสายฟ้าได้รับเพิ่มอีก 10%',
		starEffectDesc_in = 'Efek tambahan: Meningkatkan kerusakan keterampilan kritis sebesar 20% untuk semua sekutu di giliran berikutnya, pahlawan sistem Petir mendapatkan tambahan 10%.',
		starEffectDesc_ph = 'Karagdagang epekto: Nagpapataas ng 20% kritikal na pinsala ng kasanayan para sa lahat ng mga kakampi sa susunod na turno, ang mga bayani ng Lightning system ay nakakakuha ng dagdag na 10%.',
		starEffectDesc_ma = 'Kesan tambahan: Meningkatkan kerosakan kemahiran kritikal sebanyak 20% untuk semua sekutu pada giliran seterusnya, wira sistem Petir memperoleh tambahan 10%.',
