		skillName_th = 'กระตุ้นพลังงานไฟฟ้า',
		skillName_in = 'Merangsang energi listrik',
		skillName_ph = 'Paganangkin ng enerhiyang elektriko',
		skillName_ma = 'Merangsang tenaga elektrik',
		skillName = 'Stimulate electric energy',
		describe_vn = 'Mỗi lượt ngẫu nhiên thêm [Cảm Điện] cho một kẻ địch (Cảm Điện: hiệu ứng đặc biệt); khi Siêu Điện Long có mặt, anh hùng bị [Cảm Điện] tấn công mục tiêu hệ Lôi của phe ta, nộ khí hồi phục thêm tăng lên #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# điểm nộ khí',
		describe_en = 'Each turn, randomly add [Electro Shock] to an enemy (Electro Shock: special effect); when Super Electro Dragon is present, heroes affected by [Electro Shock] attack our Lightning-type targets, and the rage recovery increases by #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# rage points.',
		describe_th = 'ในแต่ละรอบ เพิ่ม [ไฟฟ้าช็อต] ให้กับศัตรูแบบสุ่ม (ไฟฟ้าช็อต: เอฟเฟกต์พิเศษ); เมื่อมังกรไฟฟ้าซูเปอร์ปรากฏ ฮีโร่ที่ได้รับผล [ไฟฟ้าช็อต] จะโจมตีเป้าหมายสายฟ้าของฝ่ายเรา และการฟื้นฟูพลังแค้นเพิ่มขึ้น #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# แต้มพลังแค้น',
		describe_in = 'Setiap giliran, secara acak tambahkan [Kejutan Listrik] pada satu musuh (Kejutan Listrik: efek khusus); saat Naga Super Listrik hadir, pahlawan yang terkena [Kejutan Listrik] menyerang target tipe Listrik dari pihak kita, dan pemulihan kemarahan meningkat sebesar #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# poin kemarahan.',
		describe_ph = 'Bawat turno, random na magdagdag ng [Electro Shock] sa isang kalaban (Electro Shock: espesyal na epekto); kapag nandiyan ang Super Electro Dragon, ang bayani na may [Electro Shock] ay umatake sa aming Lightning-type na target, at tumataas ang pagbawi ng galit ng #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# na puntos ng galit.',
		describe_ma = 'Setiap giliran, secara rawak tambah [Kejutan Elektrik] kepada satu musuh (Kejutan Elektrik: kesan istimewa); apabila Naga Super Elektrik hadir, wira yang terkena [Kejutan Elektrik] menyerang sasaran jenis Petir pihak kita, dan pemulihan amarah meningkat sebanyak #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# mata amarah.',
		describe = 'Each turn, randomly add [Electro Shock] to an enemy (Electro Shock: special effect); when Super Electro Dragon is present, heroes affected by [Electro Shock] attack our Lightning-type targets, and the rage recovery increases by #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# rage points.',
		starEffect = __data_t__starEffect[8846],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi Siêu Điện Long có mặt, các anh hùng của chúng ta gây thêm 60% Sát Thương Phép Thuật cho các mục tiêu đang <cảm điện>.',
		starEffectDesc = 'Additional effect: When Super Electric Dragon is present, our heroes deal an extra 60% Magic Damage to targets that are <electrified>.',
		starEffectDesc_en = 'Additional effect: When Super Electric Dragon is present, our heroes deal an extra 60% Magic Damage to targets that are <electrified>.',
		starEffectDesc_th = 'ผลเสริม: เมื่อมังกรไฟฟ้าซูเปอร์ปรากฏ ตัวละครของเราจะสร้างความเสียหายเวทย์เพิ่มเติม 60% แก่เป้าหมายที่อยู่ในสถานะ <ถูกช็อตไฟฟ้า>.',
		starEffectDesc_in = 'Efek tambahan: Ketika Naga Listrik Super hadir, pahlawan kita memberikan 60% Kerusakan Sihir tambahan kepada target yang sedang <teraliri listrik>.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag naroroon ang Super Elektrik na Dragon, ang aming mga bayani ay nagdudulot ng dagdag na 60% Magic Damage sa mga target na <electrified>.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila Naga Elektrik Super hadir, wira kita memberikan tambahan 60% Kerosakan Sihir kepada sasaran yang sedang <terkena elektrik>.',
		zawakeEffect = __data_t__zawakeEffect[8846],
		-- {79004}
		zawakeEffectDesc = 'Each turn randomly adds <Electric Shock> to one enemy (Electric Shock: special effect), with a 30% chance to add <Electric Shock> to another random enemy; When Super Electric Dragon is present, when the hero <Electric Shock> attacks a lightning-aligned enemy target, restore #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# energy points.',
		zawakeEffectDesc_en = 'Each turn randomly adds <Electric Shock> to one enemy (Electric Shock: special effect), with a 30% chance to add <Electric Shock> to another random enemy; When Super Electric Dragon is present, when the hero <Electric Shock> attacks a lightning-aligned enemy target, restore #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# energy points.',
		zawakeEffectDesc_th = 'ในแต่ละเทิร์นสุ่มเพิ่ม <Cảm điện> ให้ศัตรูหนึ่งตัว (Cảm điện: ผลพิเศษ) มีโอกาส 30% ที่จะเพิ่ม <Cảm điện> ให้ศัตรูสุ่มอีกตัวหนึ่ง; เมื่อมี Siêu Điện Long อยู่ เมื่อฮีโร่ <Cảm điện> โจมตีเป้าหมายฝ่ายสายฟ้า จะฟื้นฟูพลังน้อยเพิ่ม #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# แต้มพลังน้อย',
		zawakeEffectDesc_in = 'Setiap giliran secara acak menambahkan <Cảm điện> ke satu musuh (Cảm điện: efek khusus), dengan peluang 30% untuk menambahkan <Cảm điện> ke musuh acak lainnya; Ketika Super Electric Dragon hadir, saat pahlawan <Cảm điện> menyerang target musuh dengan elemen petir, pulihkan #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# energi.',
		zawakeEffectDesc_ph = 'Bawat turn ay random na nagdadagdag ng <Cảm điện> sa isang kalaban (Cảm điện: espesyal na epekto), may 30% na tsansa na magdagdag din ng <Cảm điện> sa isa pang random na kalaban; Kapag nandiyan si Super Electric Dragon, kapag ang bayani na <Cảm điện> ay umatake sa kalaban na may kuryenteng elemento, magregenerate ng #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# energy points.',
		zawakeEffectDesc_ma = 'Setiap pusingan secara rawak menambah <Cảm điện> kepada satu musuh (Cảm điện: kesan khas), dengan peluang 30% untuk menambah <Cảm điện> kepada satu musuh rawak lain; Apabila Super Electric Dragon hadir, apabila wira <Cảm điện> menyerang sasaran musuh elemen petir, pulihkan #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# tenaga.',
		zawakeEffectDesc_vn = 'Mỗi lượt ngẫu nhiên thêm <Cảm điện> cho một kẻ địch (Cảm điện: hiệu ứng đặc biệt), có thêm 30% cơ hội thêm <Cảm điện> cho một kẻ địch ngẫu nhiên khác;Khi Siêu Điện Long có mặt, khi anh hùng <Cảm điện> tấn công mục tiêu hệ sét phe ta, hồi phục nộ khí thêm #C0x5c9970#$(60+skillLevel*0.1-0.1)$#C0x5B545B# điểm nộ khí',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#has an additional 30% chance to inflict <Shock> on a random enemy#C0x5B545B#',
		zawakeSimpleDesc_en = '#C0x5c9970#has an additional 30% chance to inflict <Shock> on a random enemy#C0x5B545B#',
		zawakeSimpleDesc_th = '#C0x5c9970#มีโอกาสเพิ่มเติม 30% ที่จะติด <ช็อก> ให้ศัตรูแบบสุ่ม#C0x5B545B#',
		zawakeSimpleDesc_in = '#C0x5c9970#memiliki peluang tambahan 30% untuk memberikan <Setrum> ke musuh secara acak#C0x5B545B#',
		zawakeSimpleDesc_ph = '#C0x5c9970#may karagdagang 30% tsansa na maglagay ng <Kuryente> sa isang random na kalaban#C0x5B545B#',
		zawakeSimpleDesc_ma = '#C0x5c9970#mempunyai peluang tambahan 30% untuk mengenakan <Renjatan> kepada musuh rawak#C0x5B545B#',
