	[9713] = {
		id = 9713,
		skillName_vn = 'Phá hủy oán linh',
		skillName_en = 'Destroy vengeful spirit',
		skillName_th = 'ทำลายวิญญาณแค้น',
		skillName_in = 'Hancurkan roh dendam',
		skillName_ph = 'Wasakin ang mapanirang espiritu',
		skillName_ma = 'Musnahkan roh dendam',
		skillName = 'Destroy vengeful spirit',
		describe_vn = 'Mộng Yêu trút toàn bộ oán niệm lên toàn bộ mục tiêu kẻ địch, gây #C0x3D8A99#120% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đồng thời phát ra sáu câu chú, chú ngẫu nhiên đánh trúng đơn vị phe ta hoặc kẻ địch; khi đánh trúng đơn vị phe ta, khiến đơn vị đó [hạnh phúc] tăng 30% công đôi trong 2 lượt; khi đánh trúng đơn vị kẻ địch, có 100% xác suất khiến mục tiêu [ảo giác] trong 1 lượt.\n[ảo giác]: Hiệu ứng khống chế, khiến mục tiêu không thể hành động, bị tấn công chủ động sẽ giải trừ, sau khi giải trừ trong 1 lượt tiếp theo công đôi giảm 40% và tốc độ hồi nộ khí giảm 50%',
		describe_en = 'Dream Love unleashes all resentments on all enemy targets, dealing #C0x3D8A99#120% Magical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, and simultaneously casts six spells that randomly hit ally or enemy units; when hitting an ally unit, it grants [happiness] increasing double attack by 30% for 2 turns; when hitting an enemy unit, there is a 100% chance to cause the target [illusion] for 1 turn.\n[illusion]: A control effect that prevents the target from acting, broken by active attacks; after breaking, the target’s double attack is reduced by 40% and rage recovery speed is reduced by 50% for the next turn.',
		describe_th = 'มงต์เยาว์ ปลดปล่อยความโกรธแค้นทั้งหมดไปยังเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวทมนตร์ #C0x3D8A99#120% พลังโจมตีเวทมนตร์ #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# และพร้อมกันนั้นร่ายคาถาหกประโยค สุ่มโจมตีเป้าหมายฝ่ายเรา หรือฝ่ายศัตรู; เมื่อโจมตีเป้าหมายฝ่ายเรา จะทำให้เป้าหมายนั้น [ความสุข] เพิ่มการโจมตีคู่ 30% เป็นเวลา 2 เทิร์น; เมื่อโจมตีเป้าหมายฝ่ายศัตรู มีโอกาส 100% ที่จะทำให้เป้าหมาย [ภาพลวงตา] เป็นเวลา 1 เทิร์น.\n[ภาพลวงตา]: เอฟเฟกต์ควบคุม ทำให้เป้าหมายไม่สามารถกระทำการได้ หากถูกโจมตีแบบแอกทีฟจะถูกยกเลิก หลังจากถูกยกเลิกในเทิร์นถัดไป การโจมตีคู่ลดลง 40% และการฟื้นฟูพลังแค้นลดลง 50%',
		describe_in = 'Mộng Yêu meluapkan seluruh dendam pada semua target musuh, memberikan #C0x3D8A99#120% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, sekaligus mengeluarkan enam mantra yang secara acak mengenai unit sekutu atau musuh; saat mengenai unit sekutu, memberikan [kebahagiaan] meningkatkan serangan ganda sebesar 30% selama 2 giliran; saat mengenai unit musuh, memiliki peluang 100% untuk menyebabkan target [ilusi] selama 1 giliran.\n[ilusi]: Efek kontrol yang membuat target tidak bisa bertindak, terhapus jika diserang aktif; setelah terhapus, pada giliran berikutnya serangan ganda berkurang 40% dan kecepatan pemulihan kemarahan berkurang 50%.',
		describe_ph = 'Pinapanghimasok ng Mộng Yêu ang lahat ng sama ng loob sa lahat ng mga layuning kalaban, nagdudulot ng #C0x3D8A99#120% Magical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Pinsalang Pang-magic #C0x5B545B#, kasabay ng pagpapalabas ng anim na spells na random na tumatama sa mga kaalyado o kalabang yunit; kapag tumama sa kaalyadong yunit, nagbibigay ito ng [kaligayahan] na nagpapataas ng double attack ng 30% sa loob ng 2 turn; kapag tumama naman sa kalabang yunit, may 100% tsansa nitong magdulot ng [ilusyón] sa target sa loob ng 1 turn.\n[ilusyón]: Isang control effect na pumipigil sa target na kumilos, nadudurog kung aktibong inaatake; pagkatapos madurog, sa susunod na turn bumababa ang double attack ng 40% at ang bilis ng pagkabawi ng galit ng 50%.',
		describe_ma = 'Mộng Yêu meluahkan segala dendam ke atas semua sasaran musuh, menyebabkan #C0x3D8A99#120% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, dan serentak mengeluarkan enam mantra yang secara rawak terkena unit sekutu atau musuh; apabila terkena unit sekutu, memberikan [kebahagiaan] meningkatkan serangan berganda sebanyak 30% selama 2 pusingan; apabila terkena unit musuh, mempunyai peluang 100% menyebabkan sasaran [ilusi] selama 1 pusingan.\n[ilusi]: Kesan kawalan yang menyebabkan sasaran tidak dapat bertindak, dibatalkan apabila diserang aktif; selepas dibatalkan pada pusingan berikutnya serangan berganda berkurang 40% dan kelajuan pemulihan kemarahan berkurang 50%.',
		describe = 'Dream Love unleashes all resentments on all enemy targets, dealing #C0x3D8A99#120% Magical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, and simultaneously casts six spells that randomly hit ally or enemy units; when hitting an ally unit, it grants [happiness] increasing double attack by 30% for 2 turns; when hitting an enemy unit, there is a 100% chance to cause the target [illusion] for 1 turn.\n[illusion]: A control effect that prevents the target from acting, broken by active attacks; after breaking, the target’s double attack is reduced by 40% and rage recovery speed is reduced by 50% for the next turn.',
		simDesc_vn = 'Misdreavus tấn công toàn bộ mục tiêu của đối phương, gây sát thương phép và phát ra sáu câu chú.',
		simDesc_en = 'Misdreavus attacks all opposing targets, dealing magic damage and casting six spells.',
		simDesc_th = 'มิสเดรฟัสโจมตีเป้าหมายฝ่ายตรงข้ามทั้งหมด สร้างความเสียหายเวทย์มนตร์และร่ายคาถาหกบท',
		simDesc_in = 'Misdreavus menyerang semua target lawan, memberikan kerusakan sihir dan mengeluarkan enam mantra.',
		simDesc_ph = 'Inaatake ni Misdreavus ang lahat ng kalabang target, nagdudulot ng magic damage at nagpapalabas ng anim na spells.',
		simDesc_ma = 'Misdreavus menyerang semua sasaran lawan, menyebabkan kerosakan sihir dan melancarkan enam jampi.',
		simDesc = 'Misdreavus attacks all opposing targets, dealing magic damage and casting six spells.',
		starEffect = __data_t__starEffect[9713],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Trong kỹ năng chí mạng, có thể hồi phục hoặc giảm năng lượng: đồng minh tăng 50 điểm năng lượng; đồng minh giảm 50 điểm năng lượng.',
		starEffectDesc = 'Additional effect: In critical skills, energy can be restored or reduced: ally gains 50 energy points; ally loses 50 energy points.',
		starEffectDesc_en = 'Additional effect: In critical skills, energy can be restored or reduced: ally gains 50 energy points; ally loses 50 energy points.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ในทักษะคริติคอล สามารถฟื้นฟูหรือ ลดพลังงาน: พันธมิตรได้รับพลังงานเพิ่ม 50 คะแนน; พันธมิตรเสียพลังงาน 50 คะแนน',
		starEffectDesc_in = 'Efek tambahan: Dalam skill kritis, dapat memulihkan atau mengurangi energi: sekutu mendapat tambahan 50 poin energi; sekutu kehilangan 50 poin energi.',
		starEffectDesc_ph = 'Karagdagang epekto: Sa kritikal na kasanayan, maaaring maibalik o mabawasan ang enerhiya: kaalyado tumataas ng 50 puntos na enerhiya; kaalyado nababawasan ng 50 puntos na enerhiya.',
		starEffectDesc_ma = 'Kesan tambahan: Dalam kemahiran kritikal, tenaga boleh dipulihkan atau dikurangkan: sekutu mendapat 50 mata tenaga; sekutu kehilangan 50 mata tenaga.',
