	[9716] = {
		id = 9716,
		skillName_vn = 'Nổi lên',
		skillName_en = 'Rise up',
		skillName_th = 'ลุกขึ้น',
		skillName_in = 'Bangkit',
		skillName_ph = 'Tumindig',
		skillName_ma = 'Bangkit',
		skillName = 'Rise up',
		describe_vn = 'Sau khi nhận kỹ năng chủ động, có #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# xác suất vào trạng thái [ẩn thân] trong 1 lượt [mỗi 3 lượt lớn chỉ kích hoạt 1 lần]; trước khi bắt đầu mỗi lượt lớn, bắn một câu chú vào một đơn vị ngẫu nhiên phe ta và một đơn vị ngẫu nhiên kẻ địch; khi đánh trúng đơn vị phe ta, khiến đơn vị đó [hạnh phúc] tăng 30% công đôi trong 2 lượt; khi đánh trúng đơn vị kẻ địch, có 50% xác suất khiến mục tiêu [ảo giác] trong 1 lượt',
		describe_en = 'After acquiring the active skill, there is a #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# chance to enter the [stealth] state for 1 turn [activates only once every 3 major turns]; before the start of each major turn, cast a spell on one random ally unit and one random enemy unit; when hitting an ally unit, causes that unit to be [happy] with double attack increased by 30% for 2 turns; when hitting an enemy unit, there is a 50% chance to cause the target to be [hallucinated] for 1 turn.',
		describe_th = 'หลังจากได้รับสกิลแอคทีฟ จะมีโอกาส #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# ในการเข้าสู่สถานะ [ซ่อนตัว] เป็นเวลา 1 เทิร์น [เปิดใช้งานครั้งเดียวทุก 3 เทิร์นใหญ่]; ก่อนเริ่มแต่ละเทิร์นใหญ่ จะยิงคำสาปใส่หน่วยพันธมิตรสุ่มหนึ่งหน่วยและหน่วยศัตรูสุ่มหนึ่งหน่วย; เมื่อโจมตีโดนหน่วยพันธมิตร จะทำให้หน่วยนั้น [มีความสุข] เพิ่มพลังโจมตีสองเท่า 30% เป็นเวลา 2 เทิร์น; เมื่อโจมตีโดนหน่วยศัตรู มีโอกาส 50% ที่จะทำให้เป้าหมาย [ประสาทหลอน] เป็นเวลา 1 เทิร์น',
		describe_in = 'Setelah menerima skill aktif, memiliki peluang #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# untuk memasuki status [siluman] selama 1 giliran [hanya aktif sekali setiap 3 giliran besar]; sebelum memulai setiap giliran besar, menembakkan mantra ke satu unit sekutu acak dan satu unit musuh acak; saat menyerang unit sekutu, membuat unit tersebut [bahagia] dengan peningkatan serangan ganda 30% selama 2 giliran; saat menyerang unit musuh, ada peluang 50% membuat target [halusinasi] selama 1 giliran.',
		describe_ph = 'Pagkatapos makuha ang aktibong kasanayan, may #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# pagkakataon na pumasok sa estado ng [pagkukunwari] sa loob ng 1 turn [isang beses lang na na-activate bawat 3 malalaking turn]; bago magsimula ang bawat malaking turn, magpapaputok ng isang spell sa isang random na kaalyadong yunit at isang random na kaaway na yunit; kapag tumama sa kaalyadong yunit, ginagawa nitong [masaya] ang yunit na iyon na may 30% dagdag sa dobleng atake sa loob ng 2 turn; kapag tumama sa kaaway na yunit, may 50% na tsansa na gawing [halusinasyon] ang target sa loob ng 1 turn.',
		describe_ma = 'Selepas memperoleh kemahiran aktif, terdapat #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# peluang untuk memasuki keadaan [sembunyi] selama 1 pusingan [hanya aktif sekali setiap 3 pusingan besar]; sebelum permulaan setiap pusingan besar, menembak satu mantra pada satu unit sekutu rawak dan satu unit musuh rawak; apabila menyerang unit sekutu, menyebabkan unit itu [gembira] dengan peningkatan serangan berganda sebanyak 30% selama 2 pusingan; apabila menyerang unit musuh, terdapat 50% peluang menyebabkan sasaran [halusinasi] selama 1 pusingan.',
		describe = 'After acquiring the active skill, there is a #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# chance to enter the [stealth] state for 1 turn [activates only once every 3 major turns]; before the start of each major turn, cast a spell on one random ally unit and one random enemy unit; when hitting an ally unit, causes that unit to be [happy] with double attack increased by 30% for 2 turns; when hitting an enemy unit, there is a 50% chance to cause the target to be [hallucinated] for 1 turn.',
