	[9723] = {
		id = 9723,
		skillName_vn = 'Thành phố khi ăn',
		skillName_en = 'City when eating',
		skillName_th = 'เมืองเวลาอาหาร',
		skillName_in = 'Kota saat makan',
		skillName_ph = 'Lungsod kapag kumakain',
		skillName_ma = 'Bandar ketika makan',
		skillName = 'City when eating',
		describe_vn = 'Tokisaki Kurumi phát huy tối đa hỏa lực của mình và kích hoạt kết giới Thành phố ăn thời gian để hút tất cả mục tiêu của kẻ địch vào kết giới. Cuộc tấn công gây ra #C0x3D8A99#220% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#sát thương ma thuật#C0x5B545B#. Sáu mục tiêu sẽ bị ảnh hưởng bởi rào chắn. Khi một đơn vị đồng minh bị ảnh hưởng, đòn tấn công kép của nó sẽ tăng 30% trong 2 lượt. Khi một đơn vị địch bị ảnh hưởng, có 100% khả năng khiến nó [ảo giác] trong 1 lượt.',
		describe_en = 'Tokisaki Kurumi unleashes her full firepower and activates the Time-Eating City barrier to pull all enemy targets into the barrier. The attack deals #C0x3D8A99#220% Magical Damage#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# magic damage#C0x5B545B#. Six targets will be affected by shields. When an allied unit is affected, its double attack increases by 30% for 2 turns. When an enemy unit is affected, there is a 100% chance to cause it to be [illusion] for 1 turn.',
		describe_th = 'โทคิซากิ คุรุมิ ใช้พลังไฟอย่างเต็มที่และเปิดใช้งานเกราะเมืองกินเวลาเพื่อดึงเป้าหมายศัตรูทั้งหมดเข้าสู่เกราะ การโจมตีทำให้เกิด #C0x3D8A99#220% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B#. เป้าหมายหกตัวจะได้รับผลกระทบจากโล่ เมื่อหน่วยพันธมิตรได้รับผลกระทบ การโจมตีคู่ของมันจะเพิ่มขึ้น 30% เป็นเวลา 2 เทิร์น เมื่อหน่วยศัตรูได้รับผลกระทบ มีโอกาส 100% ที่จะทำให้มัน [ภาพลวงตา] เป็นเวลา 1 เทิร์น',
		describe_in = 'Tokisaki Kurumi mengeluarkan kekuatan penuh dan mengaktifkan penghalang Kota Pemakan Waktu untuk menarik semua target musuh ke dalam penghalang. Serangan ini menyebabkan #C0x3D8A99#220% Kerusakan Magical#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#kerusakan sihir#C0x5B545B#. Enam target akan terpengaruh oleh perisai. Ketika unit sekutu terpengaruh, serangan ganda unit tersebut meningkat 30% selama 2 giliran. Ketika unit musuh terpengaruh, ada 100% kemungkinan membuatnya [ilusi] selama 1 giliran.',
		describe_ph = 'Si Tokisaki Kurumi ayusin ang kanyang buong apoy at pina-activate ang Time-Eating City barrier para hilahin lahat ng target na kalaban papasok sa barrier. Ang atake ay nagdudulot ng #C0x3D8A99#220% Magical Damage#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# magic damage#C0x5B545B#. Anim na target ang maaapektuhan ng shield. Kapag naapektuhan ang isang alyadong yunit, tataas ang kanyang double attack ng 30% sa loob ng 2 turn. Kapag naapektuhan naman ang isang kalabang yunit, may 100% tsansa itong ma-[illusion] sa loob ng 1 turn.',
		describe_ma = 'Tokisaki Kurumi menggerakkan sepenuhnya daya tembaknya dan mengaktifkan penghalang Kota Pemakan Masa untuk menarik semua sasaran musuh ke dalam penghalang tersebut. Serangan ini menyebabkan #C0x3D8A99#220% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#kerosakan sihir#C0x5B545B#. Enam sasaran akan terjejas oleh perisai. Apabila unit sekutu terjejas, serangannya berganda meningkat sebanyak 30% selama 2 pusingan. Apabila unit musuh terjejas, terdapat kemungkinan 100% untuk menjadikannya [ilusi] selama 1 pusingan.',
		describe = 'Tokisaki Kurumi unleashes her full firepower and activates the Time-Eating City barrier to pull all enemy targets into the barrier. The attack deals #C0x3D8A99#220% Magical Damage#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# magic damage#C0x5B545B#. Six targets will be affected by shields. When an allied unit is affected, its double attack increases by 30% for 2 turns. When an enemy unit is affected, there is a 100% chance to cause it to be [illusion] for 1 turn.',
		simDesc_vn = 'Tokisaki Kurumi phát huy tối đa hỏa lực của mình và kích hoạt kết giới Thành phố Nhật thực Thời gian để hút tất cả mục tiêu của kẻ địch vào kết giới.',
		simDesc_en = 'Tokisaki Kurumi unleashes her maximum firepower and activates the Eclipse City barrier, a time-based seal that pulls all enemy targets into the barrier.',
		simDesc_th = 'โทคิซากิ คุรุมิ ระเบิดความรุนแรงสูงสุดของเธอและเปิดใช้เกราะเมืองสุริยุปราคา ดักจับเป้าหมายศัตรูทั้งหมดเข้าสู่เกราะนี้โดยใช้เวลาจับเวลา',
		simDesc_in = 'Tokisaki Kurumi mengerahkan kekuatan tembak maksimum dan mengaktifkan penghalang Kota Gerhana, sebuah waktu untuk menyedot semua target musuh ke dalam penghalang tersebut.',
		simDesc_ph = 'Pinakakawala ni Tokisaki Kurumi ang kanyang pinakamataas na apoy at pinapagana ang Eclipse City barrier, isang oras na humihila sa lahat ng mga target ng kaaway papasok sa barrier.',
		simDesc_ma = 'Tokisaki Kurumi menggerakkan daya tembak maksimum dan mengaktifkan perisai Kota Gerhana, menggunakan masa untuk menarik semua sasaran musuh ke dalam perisai tersebut.',
		simDesc = 'Tokisaki Kurumi unleashes her maximum firepower and activates the Eclipse City barrier, a time-based seal that pulls all enemy targets into the barrier.',
		starEffect = __data_t__starEffect[9723],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng thêm: Kết giới trong kỹ năng tất sát kèm theo hiệu quả hồi nộ hoặc giảm nộ: Đơn vị đồng minh tăng 50 điểm nộ; đơn vị địch giảm 50 điểm nộ.',
		starEffectDesc = 'Additional effect: Barrier in the all-kill skill accompanied by rage recovery or rage reduction effect: Allied units gain 50 rage points; enemy units lose 50 rage points.',
		starEffectDesc_en = 'Additional effect: Barrier in the all-kill skill accompanied by rage recovery or rage reduction effect: Allied units gain 50 rage points; enemy units lose 50 rage points.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เกราะในทักษะสังหารทั้งหมดพร้อมกับผลการฟื้นฟูความโกรธหรือการลดความโกรธ: หน่วยพันธมิตรได้รับพลังความโกรธเพิ่ม 50 คะแนน; หน่วยศัตรูลดพลังความโกรธ 50 คะแนน',
		starEffectDesc_in = 'Efek tambahan: Perisai dalam keterampilan pembunuhan total disertai efek pemulihan kemarahan atau pengurangan kemarahan: Unit sekutu mendapat tambahan 50 poin kemarahan; unit musuh kehilangan 50 poin kemarahan.',
		starEffectDesc_ph = 'Karagdagang epekto: Hadlang sa kasanayan na lahat patayin kasama ang epekto ng pag-recover ng galit o pagbawas ng galit: Ang mga kasamang yunit ay tumatanggap ng 50 puntos ng galit; ang mga yunit ng kalaban ay nababawasan ng 50 puntos ng galit.',
		starEffectDesc_ma = 'Kesan tambahan: Perisai dalam kemahiran bunuh semua disertakan kesan pemulihan marah atau pengurangan marah: Unit sekutu mendapat 50 mata marah tambahan; unit musuh berkurang 50 mata marah.',
