	[9731] = {
		id = 9731,
		skillName_vn = 'Nhiễu loạn thời gian',
		skillName_en = 'Time distortion',
		skillName_th = 'ความยุ่งเหยิงของเวลา',
		skillName_in = 'Distorsi waktu',
		skillName_ph = 'Pagkagulo ng oras',
		skillName_ma = 'Pengeseran masa',
		skillName = 'Time distortion',
		describe_vn = 'Angel of Time kích hoạt Keke Emperor để tấn công một mục tiêu kẻ thù, gây ra #C0x3D8A99#160% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, Angel of Time nắm bắt sức mạnh của bản thân trong tương lai, tăng thuộc tính sáu chiều của anh ta lên 10% (tối đa 2 cấp), kéo dài trong hai vòng. Sau hai vòng, giá trị tương ứng sẽ giảm đi (có thể xóa đi)',
		describe_en = 'Angel of Time activates Keke Emperor to attack a single enemy target, dealing #C0x3D8A99#160% Magic Damage#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Magic Damage#C0x5B545B#. Angel of Time harnesses his future power, increasing his six attributes by 10% (up to 2 stacks) for two turns. After two turns, the corresponding values will decrease (can be removed).',
		describe_th = 'Angel of Time เปิดใช้ Keke Emperor เพื่อโจมตีเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#160% #C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B#. Angel of Time ใช้พลังแห่งอนาคต เพิ่มค่าหกมิติของเขาขึ้น 10% (สูงสุด 2 ชั้น) เป็นเวลาสองรอบ หลังจากสองรอบ ค่าที่สอดคล้องกันจะลดลง (สามารถลบได้)',
		describe_in = 'Angel of Time mengaktifkan Keke Emperor untuk menyerang satu target musuh, memberikan #C0x3D8A99#160% Kerusakan Sihir#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerusakan Sihir#C0x5B545B#. Angel of Time menguasai kekuatan dari masa depannya, meningkatkan enam atributnya sebesar 10% (maksimal 2 level) selama dua giliran. Setelah dua giliran, nilai yang sesuai akan berkurang (bisa dihapus).',
		describe_ph = 'Angel of Time ay nag-activate ng Keke Emperor para atakehin ang isang kaaway na target, na nagdudulot ng #C0x3D8A99#160% Magic Damage#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Magic Damage#C0x5B545B#. Sinusunggaban ni Angel of Time ang lakas ng kanyang hinaharap, pinapataas ang kanyang anim na katangian ng 10% (hanggang 2 antas) sa loob ng dalawang ikot. Pagkatapos ng dalawang ikot, ang kaukulang halaga ay bababa (maaaring matanggal).',
		describe_ma = 'Angel of Time mengaktifkan Keke Emperor untuk menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#160% Kerosakan Sihir#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerosakan Sihir#C0x5B545B#. Angel of Time menguasai kekuatan masa depannya, meningkatkan enam atributnya sebanyak 10% (maksimum 2 peringkat) selama dua pusingan. Selepas dua pusingan, nilai yang bersesuaian akan berkurang (boleh dipadam).',
		describe = 'Angel of Time activates Keke Emperor to attack a single enemy target, dealing #C0x3D8A99#160% Magic Damage#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Magic Damage#C0x5B545B#. Angel of Time harnesses his future power, increasing his six attributes by 10% (up to 2 stacks) for two turns. After two turns, the corresponding values will decrease (can be removed).',
		zawakeEffect = __data_t__zawakeEffect[9731],
		-- {79001}
		zawakeEffectDesc = 'Angel of Time activates Keke Emperor to attack an enemy target, dealing #C0x3D8A99#160% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#Magical Damage#C0x5B545B#. Angel of Time harnesses his future power, increasing his six attributes by 15% (max 2 stacks) for two rounds. After two rounds, the corresponding value decreases (can be removed).',
		zawakeEffectDesc_en = 'Angel of Time activates Keke Emperor to attack an enemy target, dealing #C0x3D8A99#160% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#Magical Damage#C0x5B545B#. Angel of Time harnesses his future power, increasing his six attributes by 15% (max 2 stacks) for two rounds. After two rounds, the corresponding value decreases (can be removed).',
		zawakeEffectDesc_th = 'Angel of Time เปิดใช้งาน Keke Emperor เพื่อโจมตียูนิตศัตรูหนึ่งตัว ก่อให้เกิด #C0x3D8A99#160% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#ความเสียหายเวทมนตร์#C0x5B545B#. Angel of Time ใช้พลังในอนาคตของเขา เพิ่มคุณสมบัติทั้งหกด้านขึ้น 15% (สูงสุด 2 ชั้น) เป็นเวลาสองรอบ หลังจากสองรอบ ค่าที่เกี่ยวข้องจะลดลง (สามารถลบได้)',
		zawakeEffectDesc_in = 'Angel of Time mengaktifkan Keke Emperor untuk menyerang satu target musuh, memberikan #C0x3D8A99#160% Damage Magis#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#Damage Magis#C0x5B545B#. Angel of Time memanfaatkan kekuatan masa depannya, meningkatkan enam atributnya sebesar 15% (maks 2 tumpukan) selama dua giliran. Setelah dua giliran, nilai yang bersangkutan akan berkurang (dapat dihapus).',
		zawakeEffectDesc_ph = 'Angel of Time activates Keke Emperor to attack one enemy target, dealing #C0x3D8A99#160% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#Magical Damage#C0x5B545B#. Angel of Time harnesses his future power, increasing his six attributes by 15% (max 2 stacks) for two rounds. After two rounds, the corresponding value decreases (can be removed).',
		zawakeEffectDesc_ma = 'Angel of Time mengaktifkan Keke Emperor untuk menyerang satu sasaran musuh, memberikan #C0x3D8A99#160% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#Kerosakan Magik#C0x5B545B#. Angel of Time menggunakan kuasa masa depannya, meningkatkan enam atributnya sebanyak 15% (maksimum 2 tingkat) selama dua pusingan. Selepas dua pusingan, nilai berkenaan akan berkurang (boleh dipadamkan).',
		zawakeEffectDesc_vn = 'Angel of Time kích hoạt Keke Emperor để tấn công một mục tiêu kẻ thù, gây ra #C0x3D8A99#160% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#Sát Thương Phép Thuật#C0x5B545B#, Angel of Time nắm bắt sức mạnh của bản thân trong tương lai, tăng thuộc tính sáu chiều của anh ta lên 15% (tối đa 2 cấp), kéo dài trong hai vòng. Sau hai vòng, giá trị tương ứng sẽ giảm đi (có thể xóa đi)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increase your six-dimensional attributes by 10% (up to 2 levels)\n#F20#\n#F40##C0x5c9970# → Increase your six-dimensional attributes by 15% (up to 2 levels)',
		zawakeSimpleDesc_en = 'Increase your six-dimensional attributes by 10% (up to 2 levels)\n#F20#\n#F40##C0x5c9970# → Increase your six-dimensional attributes by 15% (up to 2 levels)',
		zawakeSimpleDesc_th = 'เพิ่มคุณสมบัติทั้งหกของคุณขึ้น 10% (สูงสุด 2 ระดับ)\n#F20#\n#F40##C0x5c9970# → เพิ่มคุณสมบัติทั้งหกของคุณขึ้น 15% (สูงสุด 2 ระดับ)',
		zawakeSimpleDesc_in = 'Meningkatkan atribut enam dimensi kamu sebesar 10% (maksimal 2 level)\n#F20#\n#F40##C0x5c9970# → Meningkatkan atribut enam dimensi kamu sebesar 15% (maksimal 2 level)',
		zawakeSimpleDesc_ph = 'Dagdagan ng 10% ang iyong anim na katangiang pang-base (maximum 2 level)\n#F20#\n#F40##C0x5c9970# → Dagdagan ng 15% ang iyong anim na katangiang pang-base (maximum 2 level)',
		zawakeSimpleDesc_ma = 'Meningkatkan atribut enam dimensi anda sebanyak 10% (maksimum 2 tahap)\n#F20#\n#F40##C0x5c9970# → Meningkatkan atribut enam dimensi anda sebanyak 15% (maksimum 2 tahap)',
		zawakeSimpleDesc_vn = 'Tăng thuộc tính sáu chiều của bạn thêm 10% (tối đa 2 cấp)\n#F20#\n#F40##C0x5c9970# → Tăng thuộc tính sáu chiều của bạn thêm 15% (tối đa 2 cấp)',
