	[9733] = {
		id = 9733,
		skillName_vn = 'Thời gian nở rộ',
		skillName_en = 'Blooming time',
		skillName_th = 'เวลาบาน',
		skillName_in = 'Waktu Mekar',
		skillName_ph = 'Panahon ng Pamumulaklak',
		skillName_ma = 'Masa Mekar',
		skillName = 'Blooming time',
		describe_vn = 'Thiên thần của thời gian du hành trên dòng sông thời gian dài. Người xưa đã không còn nhưng thảm thực vật vẫn còn đó. Nó lãng phí thời gian để khắc các vòng tăng trưởng lên tất cả mục tiêu của kẻ thù, gây ra #C0x3D8A99#240% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# sẽ khiến tất cả anh hùng trên sân rơi vào [Thời Gian Hỗn Loạn] 2 lớn vòng\n#F10#\n#F40##L10# Thời Gian Hỗn Loạn: #L0# Tốc độ của tất cả kẻ địch giảm 10~30%, hiệu ứng buff giảm 1 hiệp, hiệu ứng tiêu cực tăng 1 hiệp, tốc độ của tất cả đồng minh tăng 20%, hiệu ứng tăng thêm 1 hiệp và hiệu ứng tiêu cực giảm 1 hiệp. Trong khoảng thời gian này, khi ba tướng địch đầu tiên đầy giận dữ lần đầu tiên, cơn giận của họ sẽ quay trở lại trạng thái của hiệp cuối cùng khi họ chưa hết giận dữ.',
		describe_en = 'The angel of time travels along the long river of time. The ancients are gone, but the vegetation remains. It wastes no time carving growth rings onto all enemy targets, causing #C0x3D8A99#240% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Magic Damage #C0x5B545B# that will put all heroes on the field into [Temporal Chaos] for 2 major rounds\n#F10#\n#F40##L10# Temporal Chaos: #L0# Reduces all enemies\' speed by 10~30%, decreases buff effects by 1 turn, increases debuff effects by 1 turn, increases all allies\' speed by 20%, increases buff effects by 1 turn, and decreases debuff effects by 1 turn. During this time, when the first three enemy heroes reach full rage for the first time, their rage will revert to the state of the last turn when they were not fully enraged.',
		describe_th = 'ทูตสวรรค์แห่งกาลเวลาเดินทางไปตามแม่น้ำแห่งกาลเวลาที่ยาวนาน ผู้โบราณได้จากไปแล้วแต่พืชพันธุ์ยังคงอยู่ เขาเสียเวลาในการแกะสลักวงปีเติบโตลงบนเป้าหมายศัตรูทั้งหมด ทำให้เกิด #C0x3D8A99#ความเสียหายเวทมนตร์ 240%#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#ความเสียหายเวทมนตร์ #C0x5B545B# ซึ่งจะทำให้ฮีโร่ทั้งหมดในสนามตกอยู่ใน [ความสับสนของเวลา] เป็นเวลา 2 รอบใหญ่\n#F10#\n#F40##L10# ความสับสนของเวลา: #L0# ลดความเร็วของศัตรูทั้งหมด 10~30%, ลดผลบัพ 1 เทิร์น, เพิ่มผลดีบัฟ 1 เทิร์น, เพิ่มความเร็วของพันธมิตรทั้งหมด 20%, เพิ่มผลบัพ 1 เทิร์น และลดผลดีบัฟ 1 เทิร์น ในช่วงเวลานี้ เมื่อฮีโร่ศัตรูสามคนแรกเต็มความโกรธเป็นครั้งแรก ความโกรธของพวกเขาจะกลับสู่สถานะของเทิร์นสุดท้ายเมื่อพวกเขายังไม่เต็มความโกรธ',
		describe_in = 'Malaikat waktu melakukan perjalanan di sepanjang sungai waktu yang panjang. Orang-orang zaman dulu telah tiada, tapi vegetasi masih ada. Dia tidak membuang waktu untuk mengukir cincin pertumbuhan pada semua target musuh, menyebabkan #C0x3D8A99#240% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B# yang akan membuat semua pahlawan di medan bertarung jatuh ke dalam [Kekacauan Waktu] selama 2 putaran besar\n#F10#\n#F40##L10# Kekacauan Waktu: #L0# Mengurangi kecepatan semua musuh sebesar 10~30%, mengurangi efek buff selama 1 giliran, menambah efek debuff selama 1 giliran, meningkatkan kecepatan semua sekutu sebesar 20%, menambah efek buff selama 1 giliran, dan mengurangi efek debuff selama 1 giliran. Selama waktu ini, ketika tiga pahlawan musuh pertama mencapai kemarahan penuh untuk pertama kalinya, kemarahan mereka akan kembali ke kondisi giliran terakhir saat mereka belum penuh kemarahan.',
		describe_ph = 'Anghel ng oras ay naglalakbay sa mahaba at malawak na ilog ng panahon. Ang mga sinaunang tao ay wala na ngunit nananatili ang mga halaman. Hindi sinasayang ang oras sa pag-ukit ng mga singsing ng paglago sa lahat ng mga target na kalaban, na nagdudulot ng #C0x3D8A99#240% Damage ng Mahika#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Damage ng Mahika #C0x5B545B# na magpapasailalim sa lahat ng mga bayani sa larangan sa [Temporal na Kaguluhan] sa loob ng 2 matitinding rounds\n#F10#\n#F40##L10# Temporal na Kaguluhan: #L0# Binabawasan ang bilis ng lahat ng kalaban ng 10~30%, binabawasan ang buff effect ng 1 round, pinapataas ang debuff effect ng 1 round, pinapataas ang bilis ng lahat ng kakampi ng 20%, pinapataas ang buff effect ng 1 round, at binabawasan ang debuff effect ng 1 round. Sa panahong ito, kapag ang unang tatlong kalaban bayani ay unang nag-full rage, ang kanilang galit ay babalik sa estado ng huling round bago pa sila ma-full rage.',
		describe_ma = 'Malaikat masa mengembara di sepanjang sungai masa yang panjang. Orang dahulu telah tiada tetapi tumbuhan masih ada. Dia tidak membuang masa untuk mengukir cincin pertumbuhan pada semua sasaran musuh, menyebabkan #C0x3D8A99#240% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B# yang akan menyebabkan semua wira di medan jatuh ke dalam [Kekacauan Masa] selama 2 pusingan utama\n#F10#\n#F40##L10# Kekacauan Masa: #L0# Mengurangkan kelajuan semua musuh sebanyak 10~30%, mengurangkan kesan buff selama 1 pusingan, menambah kesan debuff selama 1 pusingan, meningkatkan kelajuan semua sekutu sebanyak 20%, menambah kesan buff selama 1 pusingan, dan mengurangkan kesan debuff selama 1 pusingan. Dalam tempoh ini, apabila tiga wira musuh pertama mencapai kemarahan penuh untuk pertama kali, kemarahan mereka akan kembali kepada keadaan pada pusingan terakhir ketika mereka belum penuh kemarahan.',
		describe = 'The angel of time travels along the long river of time. The ancients are gone, but the vegetation remains. It wastes no time carving growth rings onto all enemy targets, causing #C0x3D8A99#240% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Magic Damage #C0x5B545B# that will put all heroes on the field into [Temporal Chaos] for 2 major rounds\n#F10#\n#F40##L10# Temporal Chaos: #L0# Reduces all enemies\' speed by 10~30%, decreases buff effects by 1 turn, increases debuff effects by 1 turn, increases all allies\' speed by 20%, increases buff effects by 1 turn, and decreases debuff effects by 1 turn. During this time, when the first three enemy heroes reach full rage for the first time, their rage will revert to the state of the last turn when they were not fully enraged.',
		simDesc_vn = 'Thiên thần Thời gian du hành trong khu rừng thời gian. Quá khứ đã qua đi nhưng cỏ cây vẫn còn tồn tại. Nó xoay chuyển thời gian để khắc các vòng tròn hàng năm lên tất cả các mục tiêu của kẻ thù và lôi kéo tất cả các anh hùng trên chiến trường vào sự hỗn loạn của thời gian. Tốc độ của tất cả kẻ thù bị giảm, hiệu ứng tăng được giảm và hiệu ứng tiêu cực tăng lên. Tất cả kẻ thù đều đảo ngược, cơn giận của kẻ thù được đưa trở lại trạng thái chưa hết giận dữ.',
		simDesc_en = 'The Time Angel travels through the forest of time. The past has passed, but the grass and trees still remain. It manipulates time to engrave annual circles upon all enemy targets and drags all heroes on the battlefield into the chaos of time. The speed of all enemies is reduced, buff effects are diminished, and debuff effects are increased. All enemies are reversed, and their anger is reset to an unspent state.',
		simDesc_th = 'เทพแห่งกาลเวลากำลังเดินทางผ่านป่ากาลเวลา อดีตได้ผ่านไปแล้ว แต่ต้นไม้และหญ้ายังคงอยู่ มันบิดเบือนเวลาเพื่อสลักวงกลมประจำปีลงบนเป้าหมายศัตรูทั้งหมดและดึงเหล่าฮีโร่ทั้งหมดบนสนามรบเข้าสู่ความวุ่นวายของเวลา ความเร็วของศัตรูทั้งหมดถูกลดลง ผลบัพฟ์ถูกลดทอน และผลดิเบฟฟ์ถูกเพิ่มขึ้น ศัตรูทุกตัวถูกย้อนกลับและความโกรธของศัตรูก็ถูกรีเซ็ตกลับสู่สถานะที่ยังไม่ได้ปลดปล่อยความโกรธ',
		simDesc_in = 'Malaikat Waktu melakukan perjalanan melalui hutan waktu. Masa lalu telah berlalu, tetapi rumput dan pepohonan tetap ada. Dia memanipulasi waktu untuk mengukir lingkaran tahunan pada semua target musuh dan menarik semua pahlawan di medan perang ke dalam kekacauan waktu. Kecepatan semua musuh dikurangi, efek buff berkurang, dan efek debuff meningkat. Semua musuh dibalik, dan amarah musuh dikembalikan ke keadaan belum marah.',
		simDesc_ph = 'Anghel ng Panahon ay naglalakbay sa kagubatan ng panahon. Ang nakaraan ay lumipas na ngunit ang mga damo at puno ay nananatili. Pinipihit niya ang oras upang ukitin ang mga taunang bilog sa lahat ng mga target na kalaban at hihilahin ang lahat ng mga bayani sa larangan ng digmaan sa kaguluhan ng panahon. Nababawasan ang bilis ng lahat ng kalaban, nababawasan ang mga epekto ng buff at nadaragdagan ang mga negatibong epekto. Lahat ng kalaban ay nirereverse, at ang galit ng kalaban ay ibinabalik sa estado ng hindi pa naibubuhos.',
		simDesc_ma = 'Malaikat Masa melakukan perjalanan dalam hutan masa. Masa lalu telah berlalu, tetapi rumput dan pokok masih kekal. Ia mengawal masa untuk mengukir bulatan tahunan ke atas semua sasaran musuh dan menarik semua wira di medan perang ke dalam kekacauan masa. Kelajuan semua musuh dikurangkan, kesan buff berkurang dan kesan debuff meningkat. Semua musuh diterbalikkan, kemarahan musuh dikembalikan ke keadaan belum meletus.',
		simDesc = 'The Time Angel travels through the forest of time. The past has passed, but the grass and trees still remain. It manipulates time to engrave annual circles upon all enemy targets and drags all heroes on the battlefield into the chaos of time. The speed of all enemies is reduced, buff effects are diminished, and debuff effects are increased. All enemies are reversed, and their anger is reset to an unspent state.',
		starEffect = __data_t__starEffect[9733],
		-- {11}
		starEffectDesc_vn = '<Thời Gian Loạn Lưu>  thời gian duy trì tăng lên 3 lượt lớn, Nộ Khí Hồi Tố tác dụng lên toàn bộ địch phương; khiến tất cả mục tiêu trên sân địch đã từng bị thêm  <Bom Thời Gian>  một lần nữa nhận thêm một quả  <Bom Thời Gian> , nếu không có địch phương nào từng bị thêm thì thêm một quả  <Bom Thời Gian> .',
		starEffectDesc = '[กระแสเวลาปั่นป่วน] ระยะเวลาต่อเนื่องเพิ่มเป็น 3 รอบใหญ่ ผลย้อนโทสะขยายผลครอบคลุมศัตรูทุกตัวในสนาม; ศัตรูทุกตัวที่เคยได้รับ [ระเบิดกาลเวลา] จะถูกเพิ่ม [ระเบิดกาลเวลา] อีกครั้ง หากไม่มีศัตรูใดเคยได้รับมาก่อน จะสุ่มเพิ่ม [ระเบิดกาลเวลา] 1 ลูก',
		starEffectDesc_en = '<#F 9733#><Chaos Time> duration increased to 3 large turns, Rage Counter effects apply to all enemies; causes all enemy targets on the field that have previously received <#F 9733#><Time Bomb> to receive an additional <#F 9733#><Time Bomb> once again. If no enemy has ever been added, then add one <#F 9733#><Time Bomb>.',
		starEffectDesc_th = '[กระแสเวลาปั่นป่วน] มีระยะเวลานานขึ้นเป็น 3 รอบใหญ่ เอฟเฟกต์ย้อนความโกรธจะมีผลต่อศัตรูทุกคนในสนาม ศัตรูทั้งหมดที่เคยถูกติดตั้ง [ระเบิดเวลา] จะได้รับ [ระเบิดเวลา] เพิ่มอีก 1 ลูก หากไม่มีใครเคยถูกติดตั้งมาก่อน จะสุ่มติดตั้ง [ระเบิดเวลา] จำนวน 1 ลูก',
		starEffectDesc_in = '<#F 9733#><Waktu Kekacauan> durasi ditingkatkan menjadi 3 giliran besar, Efek Balik Amarah diterapkan pada semua musuh; membuat semua target di medan musuh yang pernah menerima <#F 9733#><Bom Waktu> menerima tambahan <#F 9733#><Bom Waktu> sekali lagi. Jika tidak ada musuh yang pernah menerima, maka tambahkan satu <#F 9733#><Bom Waktu>.',
		starEffectDesc_ph = '<#F 9733#><Oras ng Kaguluhan> tumagal nang 3 malalaking turn, Ang Epekto ng Galit na Bumalik ay nakaaplay sa lahat ng kalaban; pinipilit ang lahat ng target sa larangan ng kalaban na dati nang pinaglagyan ng <#F 9733#><Bomba ng Oras> na makatanggap muli ng isa pang <#F 9733#><Bomba ng Oras>. Kung walang kalabang dati nang pinaglagyan, maglagay ng isang <#F 9733#><Bomba ng Oras>.',
		starEffectDesc_ma = '<#F 9733#><Masa Kacau> tempoh dinaikkan kepada 3 giliran besar, Kesan Balik Marah dikenakan ke atas semua musuh; menyebabkan semua sasaran di medan musuh yang pernah menerima <#F 9733#><Bom Masa> menerima tambahan <#F 9733#><Bom Masa> sekali lagi. Jika tiada musuh pernah menerima, tambah satu <#F 9733#><Bom Masa>.',
		zawakeEffect = __data_t__zawakeEffect[9733],
		-- {79003}
		zawakeEffectDesc = 'The angel of time travels through the time forest. The ancients are gone, but the vegetation remains. He spends time carving growth rings on all enemy targets, causing #C0x3D8A99#240% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$’s #C0xF13B54# Magical Damage #C0x5B545B# will pull all heroes on the field into <Time Turbulence> for 2 big rounds\n#F10#\n#F40##L10# Time Chaos: #L0# Enemy overall speed reduced by 10~30%, buff durations reduced by 1 turn, debuff durations increased by 1 turn, own team\'s overall speed increased by 20%, buff durations increased by 1 turn, debuff durations reduced by 1 turn. Before the first time three enemy heroes are fully enraged, their rage will return in the last round when they are no longer enraged. Meanwhile, the types of friendly darkness and superheroes with the lowest HP will also receive the <Future Prediction> effect of the Time Angel once, and the cooldown of minor skills will be shortened by 1 turn.',
		zawakeEffectDesc_en = 'The angel of time travels through the time forest. The ancients are gone, but the vegetation remains. He spends time carving growth rings on all enemy targets, causing #C0x3D8A99#240% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$’s #C0xF13B54# Magical Damage #C0x5B545B# will pull all heroes on the field into <Time Turbulence> for 2 big rounds\n#F10#\n#F40##L10# Time Chaos: #L0# Enemy overall speed reduced by 10~30%, buff durations reduced by 1 turn, debuff durations increased by 1 turn, own team\'s overall speed increased by 20%, buff durations increased by 1 turn, debuff durations reduced by 1 turn. Before the first time three enemy heroes are fully enraged, their rage will return in the last round when they are no longer enraged. Meanwhile, the types of friendly darkness and superheroes with the lowest HP will also receive the <Future Prediction> effect of the Time Angel once, and the cooldown of minor skills will be shortened by 1 turn.',
		zawakeEffectDesc_th = 'เทวทูตแห่งกาลเวลาการเดินทางผ่านป่ากาลเวลา ชาวโบราณได้จากไปแล้วแต่พืชพันธุ์ยังคงอยู่ เขาใช้เวลาแกะวงแหวนการเจริญเติบโตบนเป้าหมายศัตรูทั้งหมด ก่อให้เกิด #C0x3D8A99#240% ความเสียหายเวทย์มนตร์#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# ความเสียหายเวทย์มนตร์ #C0x5B545B# จะดึงฮีโร่ทั้งหมดในสนามเข้าสู่ <Time Turbulence> เป็นเวลา 2 รอบหลัก\n#F10#\n#F40##L10# ความวุ่นวายของกาลเวลา: #L0# ความเร็วโดยรวมของศัตรูลดลง 10~30%, ระยะเวลาบัฟลดลง 1 เทิร์น, ระยะเวลาการติดสถานะลดลง 1 เทิร์น, ความเร็วโดยรวมของทีมเพิ่มขึ้น 20%, ระยะเวลาบัฟเพิ่มขึ้น 1 เทิร์น และระยะเวลาการติดสถานะลดลง 1 เทิร์น ก่อนที่ฮีโร่ศัตรู 3 ตัวแรกจะเต็มความโกรธ ความโกรธของพวกเขาจะกลับมาในรอบสุดท้ายเมื่อพวกเขาไม่โกรธอีกต่อไป ในขณะเดียวกัน ประเภทของความมืดและซูเปอร์ฮีโร่ฝ่ายเดียวกันที่มีพลังชีวิตต่ำที่สุดจะได้รับผล <การทำนายอนาคต> ของเทวทูตกาลเวลา 1 ครั้ง และคูลดาวน์ของทักษะรองจะถูกย่นระยะเวลา 1 เทิร์น',
		zawakeEffectDesc_in = 'Malaikat waktu melakukan perjalanan melintasi hutan waktu. Orang-orang kuno sudah tiada tetapi vegetasi tetap ada. Dia menghabiskan waktu mengukir cincin pertumbuhan pada semua target musuh, menyebabkan #C0x3D8A99#240% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*60)$’s #C0xF13B54# Kerusakan Sihir #C0x5B545B# akan menarik semua pahlawan di medan ke dalam <Time Turbulence> selama 2 ronde besar\n#F10#\n#F40##L10# Kekacauan Waktu: #L0# Kecepatan keseluruhan musuh berkurang 10~30%, durasi buff berkurang 1 giliran, durasi debuff bertambah 1 giliran, kecepatan keseluruhan tim sendiri meningkat 20%, durasi buff bertambah 1 giliran, dan durasi debuff berkurang 1 giliran. Sebelum tiga pahlawan musuh pertama kali penuh amarah, amarah mereka akan kembali pada ronde terakhir saat mereka tidak lagi marah, sementara jenis kegelapan dan pahlawan super teman dengan HP terendah juga akan menerima efek <Future Prediction> dari Malaikat Waktu satu kali, dan cooldown skill kecil akan dipersingkat 1 giliran.',
		zawakeEffectDesc_ph = 'Anghel ng oras ay naglalakbay sa kagubatan ng oras. Wala na ang mga sinaunang tao ngunit nananatili pa rin ang mga halaman. Ginugugol niya ang oras sa pag-ukit ng mga growth ring sa lahat ng mga target ng kalaban, na nagdudulot ng #C0x3D8A99#240% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$’s #C0xF13B54# Magical Damage #C0x5B545B# na huhila sa lahat ng mga bayani sa larangan papasok sa <Time Turbulence> sa loob ng 2 malalaking round\n#F10#\n#F40##L10# Kaguluhan ng Oras: #L0# Binabawasan ng 10~30% ang kabuuang bilis ng kalaban, nababawasan ng 1 turn ang tagal ng buffs, nadadagdagan ng 1 turn ang epekto ng debuffs, tumataas ng 20% ang kabuuang bilis ng sarili nitong grupo, tumataas ng 1 turn ang tagal ng buffs, at nababawasan ng 1 turn ang epekto ng debuffs. Bago ang unang pagkakataon na may tatlong kalabang bayani na puno ng galit, babalik ang kanilang galit sa huling round kapag wala na silang galit, kasabay nito, ang mga uri ng friendly darkness at superhero na may pinakamababang HP ay makakatanggap din ng epekto ng <Future Prediction> mula sa Anghel ng Oras isang beses, kasabay nito ay mapapaikli ng 1 turn ang cooldown ng mga maliliit na kakayahan.',
		zawakeEffectDesc_ma = 'Malaikat masa melakukan perjalanan melalui hutan masa. Orang zaman dahulu sudah tiada tetapi vegetasi masih ada. Dia meluangkan masa mengukir cincin pertumbuhan pada semua sasaran musuh, menyebabkan #C0x3D8A99#240% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*60)$’s #C0xF13B54# Kerosakan Sihir #C0x5B545B# akan menarik semua wira di medan ke dalam <Time Turbulence> selama 2 pusingan besar\n#F10#\n#F40##L10# Huru-hara Masa: #L0# Kelajuan keseluruhan musuh dikurangkan 10~30%, tempoh buff dikurangkan 1 giliran, tempoh debuff meningkat 1 giliran, kelajuan keseluruhan pasukan sendiri meningkat 20%, tempoh buff meningkat 1 giliran, dan tempoh debuff dikurangkan 1 giliran. Sebelum tiga wira musuh pertama kali penuh marah, kemarahan mereka akan kembali pada pusingan terakhir apabila mereka tidak lagi marah, manakala jenis kegelapan dan wira adiwira mesra dengan HP terendah juga akan menerima kesan <Future Prediction> daripada Malaikat Masa sekali, dan cooldown kemahiran kecil akan dipendekkan 1 giliran.',
		zawakeEffectDesc_vn = 'Thiên thần của thời gian du hành xuyên qua khu rừng thời gian. Người xưa đã không còn nhưng thảm thực vật vẫn còn đó. Anh ta dành thời gian khắc các vòng tăng trưởng lên tất cả mục tiêu của kẻ thù, gây ra #C0x3D8A99#240% Sát Thương Phép Thuật#C0x5B545B#+$(skillLev el*4*60)$’s #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# sẽ kéo tất cả anh hùng trên sân vào <Time Turbulence> trong 2 lớn round\n#F10#\n#F40##L10# Hỗn loạn thời gian: #L0# Tốc độ tổng thể của kẻ địch giảm 10~30%, hiệu ứng buff giảm 1 lượt, hiệu ứng tiêu cực tăng 1 lượt, tốc độ chung của nhóm mình tăng 20%, hiệu ứng buff tăng 1 lượt và hiệu ứng tiêu cực giảm 1 lượt, trước giai đoạn Khi ba tướng địch đầy giận dữ lần đầu tiên, sự tức giận của họ sẽ quay trở lại vòng cuối cùng khi họ không còn giận dữ, đồng thời các loại bóng tối và siêu nhân thân thiện có tỷ lệ máu thấp nhất cũng sẽ nhận được hiệu ứng <Dự đoán tương lai> của Thiên thần thời gian một lần, đồng thời thời gian hồi chiêu của các kỹ năng nhỏ sẽ được rút ngắn 1 hiệp.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Friendly Grass-type, Super-type, or the Dialga unit with the lowest HP will also receive the <Future Sight> effect from the Time Angel once, and the cooldown of their minor skill will be reduced by 1 turn.',
		zawakeSimpleDesc_en = 'Friendly Grass-type, Super-type, or the Dialga unit with the lowest HP will also receive the <Future Sight> effect from the Time Angel once, and the cooldown of their minor skill will be reduced by 1 turn.',
		zawakeSimpleDesc_th = 'ยูนิตสายพืช มิตรภาพ, สายซูเปอร์ หรือ Dialga ที่มี HP ต่ำที่สุด จะได้รับผล <ญาณอนาคต> ของเทพแห่งเวลา 1 ครั้ง และคูลดาวน์ของสกิลย่อยจะลดลง 1 เทิร์น',
		zawakeSimpleDesc_in = 'Tipe Rumput yang bersahabat, tipe Super, atau Dialga dengan HP terendah juga akan menerima efek <Penglihatan Masa Depan> dari Malaikat Waktu satu kali, dan cooldown skill kecilnya akan dikurangi 1 giliran',
		zawakeSimpleDesc_ph = 'Friendly Grass-type, Super-type, o si Dialga na may pinakamababang HP ay makakatanggap din ng <Paglilinaw sa Hinaharap> mula kay Anghel ng Panahon isang beses, at mababawasan ang cooldown ng maliit na skill nila ng 1 turn',
		zawakeSimpleDesc_ma = 'Unit jenis Rumput, jenis Super, atau Dialga yang mempunyai HP paling rendah juga akan menerima kesan <Ramalan Masa Depan> dari Malaikat Masa sekali, dan masa kitar semula kemahiran kecilnya akan dikurangkan 1 pusingan',
		zawakeSimpleDesc_vn = 'Loại cỏ thân thiện, loại siêu hoặc Dialga có tỷ lệ máu thấp nhất cũng sẽ nhận được hiệu ứng <Dự đoán tương lai> của Thiên thần thời gian một lần và thời gian hồi chiêu của kỹ năng nhỏ sẽ được rút ngắn 1 lượt.',
		upLvDesc = 'Fixed damage +240',
