	[9736] = {
		id = 9736,
		skillName_vn = 'Sự kiểm soát thời gian',
		skillName_en = 'Time control',
		skillName_th = 'การควบคุมเวลา',
		skillName_in = 'Kontrol waktu',
		skillName_ph = 'Kontrol ng oras',
		skillName_ma = 'Kawalan masa',
		skillName = 'Time control',
		describe_vn = 'Dấu thời gian: #L0# nhập và thêm [Dấu thời gian] cho chính bạn và người bạn có đòn tấn công cao nhất. Khi thêm vào, mạng sống và cơn giận hiện tại của mục tiêu sẽ được ghi lại. Khi nhận sát thương chí mạng, [Dấu ấn thời gian] sẽ bị tiêu hao để kích hoạt [Thu hồi thời gian và không gian]. Miễn nhiễm với sát thương này, sinh lực và tức giận sẽ được truy về giá trị đã ghi (không bị ảnh hưởng bởi việc điều trị). Hiệu ứng và tốc độ hồi phục tức giận sẽ không làm cho tức giận thấp hơn giá trị hiện tại), xóa bỏ mọi hiệu ứng khống chế và tiêu cực, đồng thời tăng #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#giảm sát thương cuối cùng trong 2 lượt. \n#F10#\n#F40##L10#Dự đoán tương lai: #L0#Hãy nhận biết trước những mối nguy hiểm trong tương lai và tránh hoàn toàn sát thương kỹ năng (hiệu ứng được đánh cách nhau 5 lần)\n#F10#\n#F40##L10#Biến động thời gian: #L0#Mỗi khi thiên thần thời gian hành động hoặc hiệu ứng hồi tưởng được kích hoạt, [biến động thời gian] sẽ được tạo ra, khiến nhóm thân thiện Giảm thời gian hồi chiêu của kỹ năng anh hùng ngẫu nhiên thêm 1 lượt và kéo dài thời gian hồi chiêu của các kỹ năng anh hùng ngẫu nhiên của kẻ thù thêm 1 lượt, đồng thời tăng thời gian phát nổ của tất cả [Bom hẹn giờ] trên sân của kẻ thù thêm 1 lượt\n#F10#\n#F40##L10#Purification of Time: #L0#Khi tất cả đồng minh nhận 3 hiệu ứng tiêu cực, ngay lập tức loại bỏ 2 hiệu ứng tiêu cực trong trại của bạn.',
		describe_en = 'Timestamp: #L0# enter and add [Timestamp] for yourself and the friend with the highest attack. When added, the target\'s current health and rage are recorded. Upon receiving a critical hit, the [Timestamp] will be consumed to activate [Time and Space Rewind]. Immune to this damage, health and rage will revert to the recorded value (not affected by healing). Rage effects and recovery speed will not reduce rage below the current value), remove all control and negative effects, and increase #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# final damage reduction for 2 turns. \n#F10#\n#F40##L10#Future Prediction: #L0#Be aware of future dangers and completely avoid skill damage (effect can occur 5 times) \n#F10#\n#F40##L10#Time Fluctuation: #L0#Each time the time angel acts or the recall effect is triggered, [time fluctuation] is created, causing the friendly team to reduce the cooldown of random hero skills by 1 turn and extending the cooldown of random enemy hero skills by 1 turn, while also increasing the detonation time of all [Timed Bombs] on the enemy field by 1 turn \n#F10#\n#F40##L10#Purification of Time: #L0#When all allies receive 3 negative effects, instantly remove 2 negative effects in your camp.',
		describe_th = 'เครื่องหมายเวลา: #L0# เข้าสู่และเพิ่ม [เครื่องหมายเวลา] ให้กับตัวคุณเองและเพื่อนที่มีพลังโจมตีสูงที่สุด เมื่อติดตั้ง เครื่องหมายเวลาจะบันทึกค่าพลังชีวิตและความโกรธปัจจุบันของเป้าหมาย เมื่อได้รับความเสียหายคริติคอล [เครื่องหมายเวลา] จะถูกใช้เพื่อเปิดใช้งาน [ย้อนกลับเวลาและอวกาศ] ป้องกันความเสียหายนี้ พลังชีวิตและความโกรธจะถูกย้อนกลับสู่ค่าที่บันทึกไว้ (ไม่ถูกกระทบโดยการฟื้นฟู) เอฟเฟกต์และความเร็วการฟื้นฟูความโกรธจะไม่ทำให้ความโกรธลดต่ำกว่าค่าปัจจุบัน), ลบสถานะควบคุมและลบล้างทั้งหมด และเพิ่ม #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# การลดความเสียหายขั้นสุดท้ายเป็นเวลา 2 เทิร์น \n#F10#\n#F40##L10#การทำนายอนาคต: #L0#รู้ล่วงหน้าถึงอันตรายในอนาคตและหลีกเลี่ยงความเสียหายจากสกิลทั้งหมด (เอฟเฟกต์ถูกนับ 5 ครั้ง) \n#F10#\n#F40##L10#ความผันผวนของเวลา: #L0#ทุกครั้งที่ทูตแห่งเวลาออกคำสั่งหรือเอฟเฟกต์การย้อนความทรงจำถูกเปิดใช้ [ความผันผวนของเวลา] จะถูกสร้างขึ้น ทำให้ทีมฝ่ายเดียวกันลดเวลาคูลดาวน์สกิลฮีโร่แบบสุ่ม 1 เทิร์น และเพิ่มเวลาคูลดาวน์สกิลฮีโร่แบบสุ่มของศัตรูอีก 1 เทิร์น พร้อมทั้งเพิ่มเวลาระเบิดของ [ระเบิดตั้งเวลา] ทั้งหมดที่อยู่บนสนามของศัตรูเพิ่ม 1 เทิร์น \n#F10#\n#F40##L10#การชำระล้างแห่งเวลา: #L0#เมื่อผู้พันธมิตรถูกติดสถานะลบ 3 สถานะ จะลบ 2 สถานะลบในค่ายของคุณทันที',
		describe_in = 'Cap waktu: #L0# masukkan dan tambahkan [Cap waktu] untuk diri Anda dan teman dengan serangan tertinggi. Saat ditambahkan, kesehatan dan kemarahan target saat ini akan direkam. Saat menerima serangan kritis, [Cap waktu] akan digunakan untuk mengaktifkan [Pengembalian waktu dan ruang]. Kebal terhadap kerusakan ini, kesehatan dan kemarahan akan kembali ke nilai yang tercatat (tidak terpengaruh oleh penyembuhan). Efek dan kecepatan pemulihan kemarahan tidak akan membuat kemarahan turun di bawah nilai saat ini), menghapus semua efek kontrol dan negatif, sekaligus meningkatkan #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# pengurangan kerusakan akhir selama 2 giliran. \n#F10#\n#F40##L10#Prediksi masa depan: #L0#Kenali bahaya di masa depan dan hindari seluruh kerusakan skill (efek dapat terjadi 5 kali) \n#F10#\n#F40##L10#Fluktuasi waktu: #L0#Setiap kali malaikat waktu bertindak atau efek ingatan diaktifkan, [fluktuasi waktu] dibuat menyebabkan tim sendiri mengurangi cooldown skill pahlawan acak sebanyak 1 giliran dan memperpanjang cooldown skill pahlawan musuh acak sebanyak 1 giliran, sekaligus menambah waktu ledakan semua [Bom pengatur waktu] di medan musuh sebanyak 1 giliran \n#F10#\n#F40##L10#Pemurnian waktu: #L0#Ketika semua sekutu menerima 3 efek negatif, segera hilangkan 2 efek negatif di kamp Anda.',
		describe_ph = 'Timestamp: #L0# ipasok at idagdag ang [Timestamp] para sa iyong sarili at sa kaibigan na may pinakamataas na atake. Kapag idinagdag, ang kasalukuyang buhay at galit ng target ay mare-record. Kapag nakatanggap ng critical damage, ang [Timestamp] ay gagamitin para i-activate ang [Time and Space Rewind]. Immune sa damage na ito, babalik ang buhay at galit sa narecord na halaga (hindi naaapektuhan ng healing). Ang mga epekto at bilis ng pag-recover ng galit ay hindi magpapababa ng galit sa ilalim ng kasalukuyang halaga), aalisin lahat ng control at negatibong epekto, at magdaragdag ng #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# pagbawas sa huling damage sa loob ng 2 turns. \n#F10#\n#F40##L10#Pagtataya ng Kinabukasan: #L0#Alamin ang mga panganib sa hinaharap at iwasang labis ang skill damage (ang epekto ay maaaring mangyari ng 5 ulit) \n#F10#\n#F40##L10#Pag-alog ng Oras: #L0#Sa tuwing kikilos ang time angel o ma-activate ang recall effect, ang [time fluctuation] ay malilikha na nagpapabawas ng cooldown ng random hero skills ng friendly team ng 1 turn at nagpapahaba ng cooldown ng random enemy hero skills ng 1 turn, kasabay ng pagpapahaba ng detonation time ng lahat ng [Timed Bomb] sa enemy field ng 1 turn \n#F10#\n#F40##L10#Purification of Time: #L0#Kapag ang lahat ng mga kakampi ay nakatanggap ng 3 negatibong epekto, agad na aalisin ang 2 negatibong epekto sa iyong kampo.',
		describe_ma = 'Penanda Masa: #L0# masukkan dan tambah [Penanda Masa] untuk diri anda dan rakan dengan serangan tertinggi. Apabila ditambah, kesihatan dan kemarahan semasa sasaran akan direkodkan. Apabila menerima serangan kritikal, [Penanda Masa] akan digunakan untuk mengaktifkan [Pengunduran Masa dan Ruang]. Kebal daripada kerosakan ini, kesihatan dan kemarahan akan kembali ke nilai yang direkodkan (tidak terkesan oleh rawatan). Kesan dan kelajuan pemulihan kemarahan tidak akan menjadikan kemarahan kurang daripada nilai semasa), membuang semua kesan kawalan dan negatif, serta meningkatkan #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# pengurangan kerosakan akhir selama 2 giliran. \n#F10#\n#F40##L10#Ramalan Masa Depan: #L0#Sedar akan bahaya di masa depan dan mengelak sepenuhnya kerosakan kemahiran (kesan boleh berlaku sebanyak 5 kali) \n#F10#\n#F40##L10#Fluktuasi Masa: #L0#Setiap kali malaikat masa bertindak atau kesan ingatan diaktifkan, [fluktuasi masa] dicipta yang menyebabkan pasukan mesra mengurangkan masa tindak balas kemahiran wira secara rawak sebanyak 1 giliran dan melanjutkan masa tindak balas kemahiran wira musuh secara rawak sebanyak 1 giliran, serta meningkatkan masa letupan semua [Bom Pemasa] di medan musuh sebanyak 1 giliran \n#F10#\n#F40##L10#Penyucian Masa: #L0#Apabila semua sekutu menerima 3 kesan negatif, segera buang 2 kesan negatif di kem anda.',
		describe = 'Timestamp: #L0# enter and add [Timestamp] for yourself and the friend with the highest attack. When added, the target\'s current health and rage are recorded. Upon receiving a critical hit, the [Timestamp] will be consumed to activate [Time and Space Rewind]. Immune to this damage, health and rage will revert to the recorded value (not affected by healing). Rage effects and recovery speed will not reduce rage below the current value), remove all control and negative effects, and increase #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# final damage reduction for 2 turns. \n#F10#\n#F40##L10#Future Prediction: #L0#Be aware of future dangers and completely avoid skill damage (effect can occur 5 times) \n#F10#\n#F40##L10#Time Fluctuation: #L0#Each time the time angel acts or the recall effect is triggered, [time fluctuation] is created, causing the friendly team to reduce the cooldown of random hero skills by 1 turn and extending the cooldown of random enemy hero skills by 1 turn, while also increasing the detonation time of all [Timed Bombs] on the enemy field by 1 turn \n#F10#\n#F40##L10#Purification of Time: #L0#When all allies receive 3 negative effects, instantly remove 2 negative effects in your camp.',
		starEffect = __data_t__starEffect[9736],
		-- {8}
		starEffectDesc_vn = 'Cứ sau mỗi 1 lượt lớn, lại thêm  <Dấu Ấn Thời Gian> vào một đồng minh ngẫu nhiên (Dấu Ấn Thời Gian chỉ có hiệu lực một lần trên mỗi mục tiêu).',
		starEffectDesc = 'After each major turn, add <Time Mark> to a random ally (Time Mark only takes effect once per target).',
		starEffectDesc_en = 'After each major turn, add <Time Mark> to a random ally (Time Mark only takes effect once per target).',
		starEffectDesc_th = 'หลังจากแต่ละรอบใหญ่ ให้เพิ่ม <ตราประทับเวลา> ให้กับพันธมิตรสุ่มหนึ่งคน (<ตราประทับเวลา> จะมีผลเพียงครั้งเดียวต่อเป้าหมายแต่ละตัว)',
		starEffectDesc_in = 'Setelah setiap giliran besar, tambahkan <Cap Waktu> ke sekutu acak (Cap Waktu hanya berlaku sekali per target).',
		starEffectDesc_ph = 'Pagkatapos ng bawat malaking turn, magdagdag ng <Tatak ng Panahon> sa isang random na kakampi (Ang Tatak ng Panahon ay epektibo lamang isang beses kada target).',
		starEffectDesc_ma = 'Selepas setiap pusingan besar, tambah <Cap Masa> kepada sekutu rawak (Cap Masa hanya berkuat kuasa sekali bagi setiap sasaran).',
		zawakeEffect = __data_t__zawakeEffect[9736],
		-- {79004}
		zawakeEffectDesc = 'Timestamp: #L0# apply and add <Timestamp> to yourself and the teammate with the highest attack (further reduces final damage by 15% for darkness and superpower). When added, the target\'s current health and rage are recorded. Upon critical damage received, <Timestamp> triggers <Time and Space Recall>, granting immunity to that damage while restoring health and rage. Revert to the recorded value (unaffected by healing effects and rage recovery speed, and does not lower rage below the current value), removes all control and negative effects, and increases final damage reduction #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# for 2 turns. \n#F10#\n#F40##L10#Future Prediction: #L0#Be aware of impending dangers and completely avoid skill damage (effect can trigger 4 times) \n#F10#\n#F40##L10#Time Fluctuation: #L0#Each time the Time Angel acts or the recall effect triggers, <Time Fluctuation> is created, causing the friendly team to reduce one random hero skill cooldown by 1 turn and enemy random hero skills cooldown increased by 1 turn, while increasing the detonation time of all <Timed Bombs> on the enemy field by 1 turn \n#F10#\n#F40##L10#Purification of Time: #L0#When all allies receive 3 negative effects, immediately remove 2 negative effects in your camp.',
		zawakeEffectDesc_en = 'Timestamp: #L0# apply and add <Timestamp> to yourself and the teammate with the highest attack (further reduces final damage by 15% for darkness and superpower). When added, the target\'s current health and rage are recorded. Upon critical damage received, <Timestamp> triggers <Time and Space Recall>, granting immunity to that damage while restoring health and rage. Revert to the recorded value (unaffected by healing effects and rage recovery speed, and does not lower rage below the current value), removes all control and negative effects, and increases final damage reduction #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# for 2 turns. \n#F10#\n#F40##L10#Future Prediction: #L0#Be aware of impending dangers and completely avoid skill damage (effect can trigger 4 times) \n#F10#\n#F40##L10#Time Fluctuation: #L0#Each time the Time Angel acts or the recall effect triggers, <Time Fluctuation> is created, causing the friendly team to reduce one random hero skill cooldown by 1 turn and enemy random hero skills cooldown increased by 1 turn, while increasing the detonation time of all <Timed Bombs> on the enemy field by 1 turn \n#F10#\n#F40##L10#Purification of Time: #L0#When all allies receive 3 negative effects, immediately remove 2 negative effects in your camp.',
		zawakeEffectDesc_th = 'เครื่องหมายเวลา: #L0# ใช้และเพิ่ม <เครื่องหมายเวลา> ให้กับตัวเองและเพื่อนร่วมทีมที่มีพลังโจมตีสูงสุด (ลดความเสียหายสุดท้ายจากความมืดและพลังพิเศษเพิ่มอีก 15%) เมื่อนำไปใช้ จะบันทึกพลังชีวิตและความโกรธปัจจุบันของเป้าหมาย เมื่อได้รับความเสียหายคริติคอล <เครื่องหมายเวลา> จะถูกใช้เพื่อเปิดใช้งาน <การรำลึกเวลาและอวกาศ> และความต้านทานต่อความเสียหายนี้จะฟื้นฟูพลังชีวิตและความโกรธ กลับสู่ค่าที่บันทึกไว้ (ไม่ถูกผลกระทบจากการฟื้นฟูเลือดและความเร็วการฟื้นฟูความโกรธ และจะไม่ทำให้ความโกรธต่ำกว่าค่าปัจจุบัน) ลบเอฟเฟกต์ควบคุมและลบล้างทั้งหมดและเพิ่มการลดความเสียหายสุดท้าย #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# เป็นเวลา 2 รอบ \n#F10#\n#F40##L10#การทำนายอนาคต: #L0#รับรู้ก่อนอันตรายในอนาคตและหลีกเลี่ยงความเสียหายสกิลทั้งหมด (เอฟเฟกต์ใช้ได้ 4 ครั้ง) \n#F10#\n#F40##L10#ความแปรปรวนของเวลา: #L0#ทุกครั้งที่นางฟ้าแห่งเวลาเคลื่อนไหวหรือเอฟเฟกต์การรำลึกถูกเปิดใช้งาน จะสร้าง <ความแปรปรวนของเวลา> ทำให้ทีมฝ่ายดีลดระยะเวลาในการรอใช้สกิลฮีโร่แบบสุ่มลง 1 เทิร์น และเพิ่มระยะเวลาการรอใช้สกิลฮีโร่ของศัตรูแบบสุ่มขึ้น 1 เทิร์น พร้อมทั้งเพิ่มเวลาจุดระเบิดของ <ระเบิดจับเวลา> ทุกลูกในสนามศัตรูขึ้น 1 เทิร์น \n#F10#\n#F40##L10#การชำระล้างแห่งเวลา: #L0#เมื่อพันธมิตรทั้งหมดได้รับ 3 เอฟเฟกต์ลบ จะลบเอฟเฟกต์ลบ 2 อย่างทันทีในค่ายของคุณ',
		zawakeEffectDesc_in = 'Cap waktu: #L0# terapkan dan tambahkan <Cap waktu> pada diri sendiri dan rekan dengan serangan tertinggi (mengurangi 15% kerusakan akhir tambahan untuk kegelapan dan kekuatan super). Saat diterapkan, kesehatan dan kemarahan target saat ini akan dicatat. Saat menerima kerusakan kritis, <Cap waktu> digunakan untuk mengaktifkan <Kenangan waktu dan ruang>, dan kekebalan terhadap kerusakan ini akan memulihkan kesehatan dan kemarahan. Kembali ke nilai yang dicatat (tidak terpengaruh oleh efek penyembuhan dan kecepatan pemulihan kemarahan, dan tidak akan menurunkan kemarahan di bawah nilai saat ini), menghapus semua efek kontrol dan negatif, serta meningkatkan pengurangan kerusakan akhir #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# selama 2 giliran. \n#F10#\n#F40##L10#Prediksi Masa Depan: #L0#Kenali bahaya yang akan datang dan hindari sepenuhnya kerusakan keterampilan (efek dapat dipicu 4 kali) \n#F10#\n#F40##L10#Fluktuasi Waktu: #L0#Setiap kali Malaikat Waktu bertindak atau efek kenangan diaktifkan, <Fluktuasi Waktu> tercipta, menyebabkan tim ramah mengurangi cooldown skill pahlawan secara acak sebanyak 1 giliran dan memperpanjang cooldown skill pahlawan musuh secara acak sebanyak 1 giliran, sekaligus memperpanjang waktu ledakan semua <Bom Hitung Mundur> di medan musuh sebanyak 1 giliran \n#F10#\n#F40##L10#Pemurnian Waktu: #L0#Ketika semua sekutu menerima 3 efek negatif, segera hapus 2 efek negatif di kamp Anda.',
		zawakeEffectDesc_ph = 'Timestamp: #L0# ilapat at idagdag ang <Timestamp> sa sarili mo at sa ka-teammate na may pinakamataas na atake (karagdagang bawas ng 15% sa panghuling pinsala para sa dilim at superpower). Kapag nadagdag, ang kasalukuyang buhay at galit ng target ay itatala. Kapag nakatanggap ng critical damage, ginagamit ang <Timestamp> upang i-activate ang <Paggunita sa Oras at Espasyo>, na nagbibigay ng immunity sa pinsalang iyon habang pinapagana ang pag-restore ng buhay at galit. Bumalik sa naitalang halaga (hindi naapektuhan ng healing effect at speed ng rage recovery, at hindi bababa sa kasalukuyang galit), tinatanggal lahat ng kontrol at negatibong epekto, at pinapataas ang final damage reduction #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# ng 2 turn. \n#F10#\n#F40##L10#Predict the Future: #L0#Maging alerto sa mga paparating na panganib at ganap na iwasan ang skill damage (pwede mag-effect nang 4 na beses) \n#F10#\n#F40##L10#Time Fluctuation: #L0#Sa tuwing gagalaw ang Time Angel o mag-aactivate ang recall effect, nagkakaroon ng <Time Fluctuation> na nagpapabawas ng cooldown ng random friendly hero skill ng 1 turn at nagpapahaba ng cooldown ng random enemy hero skill ng 1 turn, pati na rin pinahahaba ang timer ng lahat ng <Timed Bomb> sa field ng kalaban ng 1 turn \n#F10#\n#F40##L10#Purification of Time: #L0#Kapag ang lahat ng allies ay nakatanggap ng 3 negative effects, agad na aalisin ang 2 negative effects sa iyong kampo.',
		zawakeEffectDesc_ma = 'Cap masa: #L0# gunakan dan tambah <Cap masa> kepada diri sendiri dan rakan yang mempunyai serangan tertinggi (mengurangkan kerosakan akhir sebanyak 15% untuk kegelapan dan kuasa super). Apabila digunakan, nyawa dan kemarahan sasaran semasa akan direkodkan. Apabila menerima kerosakan kritikal, <Cap masa> digunakan untuk mengaktifkan <Imbasan masa dan ruang>, dan kebal terhadap kerosakan ini akan memulihkan nyawa dan kemarahan. Kembali ke nilai yang direkodkan (tidak terjejas oleh kesan penyembuhan dan kelajuan pemulihan kemarahan, dan tidak akan menurunkan kemarahan di bawah nilai semasa), membuang semua kesan kawalan dan negatif, serta meningkatkan pengurangan kerosakan akhir #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# selama 2 giliran. \n#F10#\n#F40##L10#Ramalan Masa Depan: #L0#Kenali bahaya akan datang dan elak sepenuhnya kerosakan kemahiran (kesan boleh dicetuskan 4 kali) \n#F10#\n#F40##L10#Fluktuasi Masa: #L0#Setiap kali Malaikat Masa bertindak atau kesan imbasan diaktifkan, <Fluktuasi Masa> dicipta, menyebabkan kumpulan mesra mengurangkan cooldown kemahiran wira secara rawak sebanyak 1 giliran dan menambah cooldown kemahiran wira musuh secara rawak sebanyak 1 giliran, sekaligus menambah masa letupan semua <Bom Dering> di medan musuh sebanyak 1 giliran \n#F10#\n#F40##L10#Penjernihan Masa: #L0#Apabila semua sekutu menerima 3 kesan negatif, segera hapus 2 kesan negatif dalam kem anda.',
		zawakeEffectDesc_vn = 'Dấu thời gian: #L0# nhập và thêm <Dấu thời gian> cho bản thân và người bạn có đòn tấn công cao nhất (giảm thêm 15% sát thương cuối cùng cho bóng tối và siêu năng lực). Khi được thêm vào, mạng sống và cơn giận hiện tại của mục tiêu sẽ được ghi lại. Khi nhận sát thương chí mạng, <Dấu thời gian> được sử dụng để kích hoạt <Hồi tưởng thời gian và không gian>, và khả năng miễn nhiễm với sát thương này sẽ tăng sinh lực và sự tức giận. Quay trở lại giá trị đã ghi (không bị ảnh hưởng bởi hiệu ứng hồi máu và tốc độ hồi phục cơn thịnh nộ, đồng thời sẽ không khiến cơn thịnh nộ thấp hơn giá trị hiện tại), xóa bỏ mọi hiệu ứng khống chế và tiêu cực, đồng thời tăng mức giảm sát thương cuối cùng #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# thêm 2 lượt. \n#F10#\n#F40##L10#Dự đoán tương lai: #L0#Hãy nhận biết trước những mối nguy hiểm trong tương lai và tránh hoàn toàn sát thương kỹ năng (hiệu ứng được đánh cách nhau 4 lần)\n#F10#\n#F40##L10#Biến động thời gian: #L0#Mỗi khi Thiên thần thời gian hành động hoặc hiệu ứng hồi tưởng được kích hoạt, <Biến động thời gian> sẽ được tạo ra, khiến nhóm thân thiện Giảm thời gian hồi chiêu của kỹ năng anh hùng ngẫu nhiên thêm 1 lượt và kéo dài thời gian hồi chiêu của các kỹ năng anh hùng ngẫu nhiên của kẻ thù thêm 1 lượt, đồng thời tăng thời gian phát nổ của tất cả <Bom hẹn giờ> trên sân của kẻ thù thêm 1 lượt\n#F10#\n#F40##L10#Purification of Time: #L0#Khi tất cả đồng minh nhận 3 hiệu ứng tiêu cực, ngay lập tức loại bỏ 2 hiệu ứng tiêu cực trong trại của bạn.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Future Sight effect hits 5 times per activation\n#F20#\n#F40##C0x5c9970#→Future Sight effect hits 4 times',
		zawakeSimpleDesc_en = 'Future Sight effect hits 5 times per activation\n#F20#\n#F40##C0x5c9970#→Future Sight effect hits 4 times',
		zawakeSimpleDesc_th = 'เอฟเฟกต์ญาณอนาคตจะโจมตี 5 ครั้งต่อการใช้\n#F20#\n#F40##C0x5c9970#→เอฟเฟกต์ญาณอนาคตจะโจมตี 4 ครั้ง',
		zawakeSimpleDesc_in = 'Efek Pandangan Masa Depan menyerang 5 kali per aktivasi\n#F20#\n#F40##C0x5c9970#→Efek Pandangan Masa Depan menyerang 4 kali',
		zawakeSimpleDesc_ph = 'Ang epekto ng Paglilinaw sa Hinaharap ay tumatama ng 5 beses kada paggamit\n#F20#\n#F40##C0x5c9970#→Ang epekto ng Paglilinaw sa Hinaharap ay tumatama ng 4 na beses',
		zawakeSimpleDesc_ma = 'Kesan Ramalan Masa Depan menyerang 5 kali setiap kali digunakan\n#F20#\n#F40##C0x5c9970#→Kesan Ramalan Masa Depan menyerang 4 kali',
		zawakeSimpleDesc_vn = 'Hiệu ứng dự đoán tương lai được đánh 5 lần một lần\n#F20#\n#F40##C0x5c9970#→Hiệu ứng dự đoán tương lai được đánh 4 lần\n Dấu ấn thời gian tăng khả năng giảm sát thương cuối cùng của loại cỏ, siêu loại và Dialga thêm 15%',
		iconRes = 'battle/skill_icon/skill_9726.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
