		skillProcess = {97361, 97362}
	},
	[9741] = {
		id = 9741,
		skillName_vn = 'Nhiễu loạn của thời gian',
		skillName_en = 'Disturbance of time',
		skillName_th = 'ความปั่นป่วนของเวลา',
		skillName_in = 'Gangguan waktu',
		skillName_ph = 'Pagkagulo ng oras',
		skillName_ma = 'Gangguan masa',
		skillName = 'Disturbance of time',
		describe_vn = 'Angel of Time kích hoạt Keke Emperor để tấn công một mục tiêu kẻ thù, gây ra #C0x3D8A99#160% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#Sát Thương Phép Thuật#C0x5B545B#, Angel of Time nắm bắt sức mạnh của bản thân trong tương lai, tăng thuộc tính sáu chiều của anh ta lên 10% (tối đa 2 cấp), kéo dài trong hai vòng. Sau hai vòng, giá trị tương ứng sẽ giảm đi (có thể xóa đi)',
		describe_en = 'Angel of Time activates Keke Emperor to attack an enemy target, dealing #C0x3D8A99#160% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage#C0x5B545B#. Angel of Time harnesses his future power, increasing all six attributes by 10% (up to 2 stacks) for two turns. After two turns, the corresponding values will decrease (and can be removed).',
		describe_th = 'Angel of Time เปิดใช้งาน Keke Emperor เพื่อโจมตีเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#160%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B#. Angel of Time ควบคุมพลังแห่งอนาคตของเขา เพิ่มคุณสมบัติหกด้านขึ้น 10% (สูงสุด 2 ชั้น) เป็นเวลาสองรอบ หลังจากสองรอบ ค่าที่เกี่ยวข้องจะลดลง (และสามารถลบได้).',
		describe_in = 'Angel of Time mengaktifkan Keke Emperor untuk menyerang satu target musuh, menyebabkan #C0x3D8A99#160% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerusakan Sihir#C0x5B545B#. Angel of Time memanfaatkan kekuatannya di masa depan, meningkatkan enam atributnya sebesar 10% (maksimal 2 tingkat), bertahan selama dua giliran. Setelah dua giliran, nilai yang sesuai akan berkurang (dan dapat dihapus).',
		describe_ph = 'Angel of Time ayusin ang Keke Emperor para umatake ng isang kalabang target, na nagdudulot ng #C0x3D8A99#160% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage#C0x5B545B#. Angel of Time ay ginagamit ang kanyang kapangyarihan mula sa hinaharap, pinapataas ang anim na katangian niya ng 10% (maximum ng 2 levels) sa loob ng dalawang turn. Pagkatapos ng dalawang turn, ang kaukulang halaga ay bababa (at maaaring tanggalin).',
		describe_ma = 'Angel of Time mengaktifkan Keke Emperor untuk menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#160% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerosakan Sihir#C0x5B545B#. Angel of Time menguasai kekuatannya dari masa depan, meningkatkan enam atributnya sebanyak 10% (maksimum 2 tahap), bertahan selama dua pusingan. Selepas dua pusingan, nilai yang berkaitan akan berkurang (dan boleh dialih keluar).',
		describe = 'Angel of Time activates Keke Emperor to attack an enemy target, dealing #C0x3D8A99#160% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage#C0x5B545B#. Angel of Time harnesses his future power, increasing all six attributes by 10% (up to 2 stacks) for two turns. After two turns, the corresponding values will decrease (and can be removed).',
		zawakeEffect = __data_t__zawakeEffect[9741],
		-- {79001}
		zawakeEffectDesc = 'Angel of Time activates Keke Emperor to attack one enemy target, dealing #C0x3D8A99#160% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#Magic Damage#C0x5B545B#. Angel of Time harnesses his future power, increasing his six attributes by 15% (max 2 stacks), lasting for two turns. After two turns, the corresponding values will decrease (can be removed).',
		zawakeEffectDesc_en = 'Angel of Time activates Keke Emperor to attack one enemy target, dealing #C0x3D8A99#160% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#Magic Damage#C0x5B545B#. Angel of Time harnesses his future power, increasing his six attributes by 15% (max 2 stacks), lasting for two turns. After two turns, the corresponding values will decrease (can be removed).',
		zawakeEffectDesc_th = 'Angel of Time เปิดใช้งาน Keke Emperor เพื่อโจมตีเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหายเวท #C0x3D8A99#160%#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#ความเสียหายเวท#C0x5B545B# Angel of Time ควบคุมพลังแห่งอนาคตของเขา เพิ่มคุณสมบัติทั้งหกทิศทางของเขาขึ้น 15% (สูงสุด 2 ชั้น) เป็นเวลา 2 เทิร์น หลังจาก 2 เทิร์น ค่าที่สอดคล้องกันจะลดลง (สามารถลบได้)',
		zawakeEffectDesc_in = 'Angel of Time mengaktifkan Keke Emperor untuk menyerang satu target musuh, memberikan #C0x3D8A99#160% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#Kerusakan Sihir#C0x5B545B#. Angel of Time memanfaatkan kekuatannya dari masa depan, meningkatkan enam atributnya sebesar 15% (maksimum 2 tumpukan), berlangsung selama dua giliran. Setelah dua giliran, nilai yang sesuai akan berkurang (dapat dihapus).',
		zawakeEffectDesc_ph = 'Angel of Time ay nagpapatakbo ng Keke Emperor upang atakihin ang isang target na kaaway, nagdudulot ng #C0x3D8A99#160% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#Magic Damage#C0x5B545B#. Angel of Time kinukuha ang kapangyarihan ng kanyang hinaharap, pinapataas ang kanyang anim na katangian ng 15% (maximum 2 na stack), tumatagal ng dalawang turn. Pagkatapos ng dalawang turn, ang kaukulang halaga ay bababa (maaaring alisin).',
		zawakeEffectDesc_ma = 'Angel of Time mengaktifkan Keke Emperor untuk menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#160% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#Kerosakan Sihir#C0x5B545B#. Angel of Time menguasai kuasa masa depannya, meningkatkan enam atributnya sebanyak 15% (maksimum 2 peringkat), berlangsung selama dua pusingan. Selepas dua pusingan, nilai berkaitan akan berkurang (boleh dipadam).',
		zawakeEffectDesc_vn = 'Angel of Time kích hoạt Keke Emperor để tấn công một mục tiêu kẻ thù, gây ra #C0x3D8A99#160% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF1 3B54#Sát Thương Phép Thuật#C0x5B545B#, Angel of Time nắm bắt sức mạnh của bản thân trong tương lai, tăng thuộc tính sáu chiều của anh ta lên 15% (tối đa 2 cấp), kéo dài trong hai vòng. Sau hai vòng, giá trị tương ứng sẽ giảm đi (có thể xóa đi)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Time Mark increases final damage reduction of Grass-type, Super-type, and Dialga by 15%',
		zawakeSimpleDesc_en = 'Time Mark increases final damage reduction of Grass-type, Super-type, and Dialga by 15%',
		zawakeSimpleDesc_th = 'เครื่องหมายเวลาเพิ่มอัตราลดดาเมจสุดท้ายของสายพืช สายซูเปอร์ และ Dialga ขึ้น 15%',
		zawakeSimpleDesc_in = 'Tanda Waktu meningkatkan pengurangan damage akhir untuk tipe Rumput, tipe Super, dan Dialga sebesar 15%',
		zawakeSimpleDesc_ph = 'Pinapataas ng Marka ng Oras ang kakayahang bawasan ang huling pinsala ng Grass-type, Super-type, at Dialga ng 15%',
		zawakeSimpleDesc_ma = 'Tanda Masa meningkatkan kadar pengurangan kerosakan akhir bagi jenis Rumput, jenis Super dan Dialga sebanyak 15%',
