	[9742] = {
		id = 9742,
		skillName_vn = 'Sự tàn lụi của thời gian',
		skillName_en = 'The decline of time',
		skillName_th = 'การเสื่อมสลายของเวลา',
		skillName_in = 'Kemunduran waktu',
		skillName_ph = 'Ang pagbagsak ng oras',
		skillName_ma = 'Kejatuhan masa',
		skillName = 'The decline of time',
		describe_vn = 'Angel of Time phóng thích Tử thần và Suy tàn để tấn công mục tiêu ở hàng đầu của kẻ địch, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$#C0xF1 3B54#Spell Damage#C0x5B545B#, đồng thời thêm một [Bom hẹn giờ] có thể xếp chồng\n#F10#\n#F40##L10#Time Bom: #L0#Hiệu ứng đặc biệt, 90% xác suất mục tiêu [Bom hẹn giờ] Giam cầm] trong 1 lượt (hiệu ứng khống chế, không thể di chuyển), đợi mục tiêu phát nổ sau 3 lượt (nổ ngay sau khi chết và tạo thêm [biến động thời gian]), khiến Thiên thần Thời gian #C0xE69900#300% Tấn Công Phép thuật# C0x5B545B# sát thương (20% sát thương văng lên các mục tiêu xung quanh) và phân hạch thành hai [Bom hẹn giờ] được gắn ngẫu nhiên vào những kẻ thù khác. Nó có thể phân hạch tới 2 lần. Sau mỗi lần phân hạch, sát thương vụ nổ và xác suất bị giam giữ giảm 20%.',
		describe_en = 'Angel of Time releases Death and Decay to attack the front row enemies, causing #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Spell Damage#C0x5B545B#. At the same time, it adds a [Time Bomb] that can stack \n#F10#\n#F40##L10#Time Bomb: #L0#Special effect, 90% chance for the target to be [Time Bomb Captive] for 1 turn (control effect, unable to move), waiting for the target to explode after 3 turns (explodes immediately after death and creates [time disturbance]), causing the Angel of Time to deal #C0xE69900#300% Magic Attack#C0x5B545B# damage (20% splash damage to nearby targets) and split into two [Time Bombs] randomly attached to other enemies. It can split up to 2 times. After each split, explosion damage and chance of captivity are reduced by 20%.',
		describe_th = 'นางฟ้าแห่งกาลเวลา ปล่อยปล่อยความตายและการเสื่อมสลายโจมตีเป้าหมายแถวหน้าในฝั่งศัตรู ทำให้เกิด #C0x3D8A99#180% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# พร้อมกันนี้เพิ่ม [ระเบิดจับเวลา] ที่สามารถซ้อนกันได้ \n#F10#\n#F40##L10#ระเบิดจับเวลา: #L0#เอฟเฟคพิเศษ โอกาส 90% ที่เป้าหมายจะถูก [ระเบิดจับเวลากักขัง] เป็นเวลา 1 เทิร์น (สถานะควบคุม ไม่สามารถเคลื่อนที่) รอให้เป้าหมายระเบิดหลัง 3 เทิร์น (ระเบิดทันทีหลังตายและสร้าง [ความปั่นป่วนแห่งกาลเวลา]) ทำให้เทพแห่งกาลเวลา สร้างความเสียหาย #C0xE69900#300% การโจมตีเวทมนตร์#C0x5B545B# (ความเสียหายรอบด้าน 20% แพร่กระจายไปยังเป้าหมายใกล้เคียง) และแยกเป็น [ระเบิดจับเวลา] สองลูกที่แนบแบบสุ่มกับศัตรูคนอื่น สามารถแยกได้สูงสุด 2 ครั้ง หลังแต่ละครั้ง ความเสียหายจากการระเบิดและโอกาสที่ถูกกักขังลดลง 20%.',
		describe_in = 'Angel of Time melepaskan Death dan Decay untuk menyerang target di barisan depan musuh, menyebabkan #C0x3D8A99#180% Damage Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Damage Sihir#C0x5B545B#. Pada saat yang sama menambahkan [Bom Waktu] yang dapat ditumpuk \n#F10#\n#F40##L10#Bom Waktu: #L0#Efek khusus, 90% kemungkinan target terkena [Bom Waktu Tahanan] selama 1 giliran (efek kontrol, tidak bisa bergerak), menunggu target meledak setelah 3 giliran (meledak segera setelah mati dan menciptakan [gangguan waktu]), menyebabkan Angel of Time memberikan #C0xE69900#300% Serangan Sihir#C0x5B545B# kerusakan (20% damage menyebar ke target sekitar) dan bercabang menjadi dua [Bom Waktu] yang terpasang secara acak ke musuh lain. Ini dapat bercabang hingga 2 kali. Setelah setiap bercabang, damage ledakan dan kemungkinan ditahan berkurang 20%.',
		describe_ph = 'Angel of Time ay naglalabas ng Death at Decay upang atakehin ang mga target sa unahang hanay ng kalaban, nagdudulot ng #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Spell Damage#C0x5B545B#. Kasabay nito, nagdadagdag ito ng [Time Bomb] na maaaring mag-stack \n#F10#\n#F40##L10#Time Bomb: #L0#Espesyal na epekto, 90% tsansa ng target na mapailalim sa [Time Bomb Captive] sa loob ng 1 turn (control effect, hindi makagalaw), maghihintay na sumabog ang target pagkatapos ng 3 turns (sasabog agad pagkatapos mamatay at lilikha ng [time disturbance]), na nagdudulot sa Angel of Time ng #C0xE69900#300% Magic Attack#C0x5B545B# na pinsala (20% splash damage sa mga nakapaligid na target) at naghahati sa dalawang [Time Bomb] na nakakabit nang random sa ibang mga kaaway. Maaari itong mahati hanggang dalawang beses. Pagkatapos ng bawat paghahati, nababawasan ang pinsala ng pagsabog at tsansa ng pagkakulong ng 20%.',
		describe_ma = 'Malaikat Masa melepaskan Kematian dan Kemerosotan untuk menyerang sasaran barisan hadapan musuh, menyebabkan #C0x3D8A99#180% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerosakan Sihir#C0x5B545B#. Pada masa yang sama menambah [Bom Masa] yang boleh bertindih \n#F10#\n#F40##L10#Bom Masa: #L0#Kesan khas, 90% kebarangkalian sasaran [Bom Masa Kurungan] selama 1 giliran (kesan kawalan, tidak boleh bergerak), menunggu sasaran meletup selepas 3 giliran (meletup serta-merta selepas mati dan mewujudkan [gangguan masa]), menyebabkan Malaikat Masa memberikan #C0xE69900#300% Serangan Sihir#C0x5B545B# kerosakan (20% kerosakan semburan ke sasaran sekitar) dan membelah kepada dua [Bom Masa] yang dipasang secara rawak ke musuh lain. Ia boleh membelah sehingga 2 kali. Selepas setiap pembelahan, kerosakan letupan dan kebarangkalian kurungan berkurang 20%.',
		describe = 'Angel of Time releases Death and Decay to attack the front row enemies, causing #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Spell Damage#C0x5B545B#. At the same time, it adds a [Time Bomb] that can stack \n#F10#\n#F40##L10#Time Bomb: #L0#Special effect, 90% chance for the target to be [Time Bomb Captive] for 1 turn (control effect, unable to move), waiting for the target to explode after 3 turns (explodes immediately after death and creates [time disturbance]), causing the Angel of Time to deal #C0xE69900#300% Magic Attack#C0x5B545B# damage (20% splash damage to nearby targets) and split into two [Time Bombs] randomly attached to other enemies. It can split up to 2 times. After each split, explosion damage and chance of captivity are reduced by 20%.',
		zawakeEffect = __data_t__zawakeEffect[9742],
		-- {79002}
		zawakeEffectDesc = 'Angel of Time releases Death and Decay to attack the front row targets of the enemy, dealing #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54 #Spell Damage#C0x5B545B#, at the same time adding a <Timer Bomb>\n#F10#\n#F40##L10#Time that can stack Bombs: #L0#Special effect, 90% chance to <Time Distortion> the target once Combined (control effect, unable to act), waiting for the target to explode after 3 turns (explodes immediately after death and creates additional <Time Distortion>), 30% chance to detonate <Timer Bomb> immediately, dealing Angel of Time damage #C0xE69900#3 00% Magic Damage #C0x5B545B# (20% splash damage to surrounding targets) and splitting into two <Timer Bomb>s attached to other random enemies, splitting up to 2 times, after each split, explosion damage and entangle chance reduce by 20%',
		zawakeEffectDesc_en = 'Angel of Time releases Death and Decay to attack the front row targets of the enemy, dealing #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54 #Spell Damage#C0x5B545B#, at the same time adding a <Timer Bomb>\n#F10#\n#F40##L10#Time that can stack Bombs: #L0#Special effect, 90% chance to <Time Distortion> the target once Combined (control effect, unable to act), waiting for the target to explode after 3 turns (explodes immediately after death and creates additional <Time Distortion>), 30% chance to detonate <Timer Bomb> immediately, dealing Angel of Time damage #C0xE69900#3 00% Magic Damage #C0x5B545B# (20% splash damage to surrounding targets) and splitting into two <Timer Bomb>s attached to other random enemies, splitting up to 2 times, after each split, explosion damage and entangle chance reduce by 20%',
		zawakeEffectDesc_th = 'เทพแห่งกาลเวลา ปล่อยความตายและการเสื่อมสภาพเพื่อโจมตีเป้าหมายแถวหน้าของศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54 #ความเสียหายจากเวท#C0x5B545B# พร้อมกันนั้น เพิ่ม <ระเบิดจับเวลา>\n#F10#\n#F40##L10#เวลา ที่สามารถเรียงซ้อนระเบิดได้: #L0#เอฟเฟกต์พิเศษ โอกาส 90% เรียกใช้ <การบิดเบือนเวลา> เป้าหมาย 1 ครั้ง รวม (เอฟเฟกต์ควบคุม ไม่สามารถกระทำได้) รอให้เป้าหมายระเบิดหลัง 3 เทิร์น (ระเบิดทันทีหลังตายและสร้าง <การบิดเบือนเวลา> เพิ่มเติม) โอกาส 30% ระเบิด <ระเบิดจับเวลา> ทันที สร้างความเสียหายเทพแห่งกาลเวลา #C0xE69900#3 00% ความเสียหายเวท#C0x5B545B# (ความเสียหายกระจาย 20% ไปยังเป้าหมายรอบๆ) และแบ่งตัวเป็นสอง <ระเบิดจับเวลา> ติดกับศัตรูสุ่มอื่น แบ่งได้สูงสุด 2 ครั้ง หลังจากแต่ละครั้งที่แบ่ง ความเสียหายจากการระเบิดและโอกาสพันธนาการลดลง 20%',
		zawakeEffectDesc_in = 'Malaikat Waktu melepaskan Kematian dan Kerusakan untuk menyerang target barisan depan musuh, menyebabkan #C0x3D8A99#180% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54 #Kerusakan Sihir#C0x5B545B#, sekaligus menambahkan <Bom Waktu>\n#F10#\n#F40##L10#Waktu yang dapat menumpuk Bom: #L0#Efek khusus, peluang 90% untuk <Distorsi Waktu> target 1 kali Gabungan (efek kontrol, tidak bisa bertindak), menunggu target meledak setelah 3 giliran (meledak segera setelah mati dan membuat <Distorsi Waktu> tambahan), peluang 30% untuk meledakkan <Bom Waktu> segera, menyebabkan kerusakan Malaikat Waktu #C0xE69900#3 00% Kerusakan Sihir #C0x5B545B# (20% kerusakan semburan ke target di sekitar) dan membelah menjadi dua <Bom Waktu> yang terpasang pada musuh acak lain, membelah maksimal 2 kali, setelah setiap pembelahan, kerusakan ledakan dan peluang ikatan berkurang 20%',
		zawakeEffectDesc_ph = 'Angel of Time ay nagpapalaya ng Kamatayan at Pagkasira upang atakihin ang mga target sa harap na hanay ng kaaway, na nagdudulot ng #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54 #Spell Damage#C0x5B545B#, kasabay ang pagdaragdag ng isang <Timer Bomb>\n#F10#\n#F40##L10#Oras na maaaring makamasa ang Bom: #L0#Espesyal na epekto, 90% tsansa na <Pagbaluktot ng Oras> ang target isang beses Pinagsama (efekto ng kontrol, hindi makakilos), naghihintay na sumabog ang target matapos ang 3 turn (sumabog agad sa pagkamatay at lumilikha ng karagdagang <Pagbaluktot ng Oras>), 30% tsansa na agad na sumabog ang <Timer Bomb>, na nagdudulot ng pinsalang Angel of Time #C0xE69900#3 00% Magic Damage #C0x5B545B# (20% nakakalat na pinsala sa mga kalapit na target) at naghahati sa dalawang <Timer Bomb> na nakakabit sa ibang random na kaaway, naghahati hanggang 2 beses, pagkatapos ng bawat paghahati, bumababa ng 20% ang pinsala ng pagsabog at tsansa ng pagkakapit',
		zawakeEffectDesc_ma = 'Malaikat Masa melepaskan Kematian dan Kemerosotan untuk menyerang sasaran barisan hadapan musuh, menyebabkan #C0x3D8A99#180% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54 #Kerosakan Sihir#C0x5B545B#, sekaligus menambah <Bom Pemasa>\n#F10#\n#F40##L10#Masa yang boleh bertindih Bom: #L0#Kesan khas, 90% kebarangkalian <Penyimpangan Masa> sasaran 1 kali Digabungkan (kesan kawalan, tidak boleh bertindak), menunggu sasaran meletup selepas 3 pusingan (meletup terus selepas mati dan menghasilkan <Penyimpangan Masa> tambahan), 30% kebarangkalian meletupkan <Bom Pemasa> dengan segera, menyebabkan kerosakan Malaikat Masa #C0xE69900#3 00% Kerosakan Sihir #C0x5B545B# (20% kerosakan percikan kepada sasaran sekeliling) dan berbahagi kepada dua <Bom Pemasa> yang dilekatkan pada musuh rawak lain, berbahagi sehingga 2 kali, selepas setiap pembahagian, kerosakan letupan dan kebarangkalian terperangkap berkurang 20%',
		zawakeEffectDesc_vn = 'Angel of Time phóng thích Tử thần và Suy tàn để tấn công mục tiêu ở hàng đầu của kẻ địch, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54 #Spell Damage#C0x5B545B#, đồng thời thêm một <Bom hẹn giờ>\n#F10#\n#F40##L10#Time có thể xếp chồng Bom: #L0#Hiệu ứng đặc biệt, 90% xác suất <Biến động thời gian> mục tiêu 1 lần Kết hợp (hiệu ứng khống chế, không thể hành động), đợi mục tiêu phát nổ sau 3 lượt (nổ ngay sau khi chết và tạo thêm <Biến động thời gian>), 30% xác suất kích nổ <Bom hẹn giờ> ngay lập tức, gây sát thương Thiên thần thời gian #C0xE69900#3 00% Sát Thương Phép Thuật #C0x5B545B# (20% sát thương lan cho các mục tiêu xung quanh) và phân hạch thành hai <Bom hẹn giờ> gắn vào kẻ thù ngẫu nhiên khác, phân hạch tối đa 2 lần, sau mỗi lần phân hạch, sát thương nổ và xác suất vướng víu giảm 20%',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Increase your six-dimensional attributes by 10% (up to 2 levels)\n#F20#\n#F40##C0x5c9970# → Increase your six-dimensional attributes by 15% (up to 2 levels)',
		zawakeSimpleDesc_en = 'Increase your six-dimensional attributes by 10% (up to 2 levels)\n#F20#\n#F40##C0x5c9970# → Increase your six-dimensional attributes by 15% (up to 2 levels)',
		zawakeSimpleDesc_th = 'เพิ่มคุณสมบัติทั้งหกของคุณขึ้น 10% (สูงสุด 2 ระดับ)\n#F20#\n#F40##C0x5c9970# → เพิ่มคุณสมบัติทั้งหกของคุณขึ้น 15% (สูงสุด 2 ระดับ)',
		zawakeSimpleDesc_in = 'Meningkatkan atribut enam dimensi kamu sebesar 10% (maksimal 2 level)\n#F20#\n#F40##C0x5c9970# → Meningkatkan atribut enam dimensi kamu sebesar 15% (maksimal 2 level)',
		zawakeSimpleDesc_ph = 'Dagdagan ng 10% ang iyong anim na katangiang pang-base (maximum 2 level)\n#F20#\n#F40##C0x5c9970# → Dagdagan ng 15% ang iyong anim na katangiang pang-base (maximum 2 level)',
		zawakeSimpleDesc_ma = 'Meningkatkan atribut enam dimensi anda sebanyak 10% (maksimum 2 tahap)\n#F20#\n#F40##C0x5c9970# → Meningkatkan atribut enam dimensi anda sebanyak 15% (maksimum 2 tahap)',
		zawakeSimpleDesc_vn = '30% khả năng kích nổ <Bom hẹn giờ> ngay lập tức',
		upLvDesc = 'Fixed damage +192',
