	[9743] = {
		id = 9743,
		skillName_vn = 'Thời gian bung nở',
		skillName_en = 'Blooming time',
		skillName_th = 'เวลาบาน',
		skillName_in = 'Waktu Mekar',
		skillName_ph = 'Oras ng Pamumulaklak',
		skillName_ma = 'Masa Mekar',
		skillName = 'Blooming time',
		describe_vn = 'Thiên thần của thời gian du hành trên dòng sông thời gian dài. Người xưa đã không còn nhưng thảm thực vật vẫn còn đó. Nó lãng phí thời gian để khắc các vòng tăng trưởng lên tất cả mục tiêu của kẻ thù, gây ra #C0x3D8A99#240% Sát Thương Phép Thuật#C0x5B545B #+$(skillLevel*4*60)$’s #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# sẽ khiến tất cả anh hùng trên sân rơi vào [Time Turbulence] 2 lớn vòng\n#F10#\n#F40##L10# Thời gian hỗn loạn: #L0# Tốc độ của tất cả kẻ địch giảm 10~30%, hiệu ứng buff giảm 1 hiệp, hiệu ứng tiêu cực tăng 1 hiệp, tốc độ của tất cả đồng minh tăng 20%, hiệu ứng tăng thêm 1 hiệp và hiệu ứng tiêu cực giảm 1 hiệp. Trong khoảng thời gian này, khi ba tướng địch đầu tiên đầy giận dữ lần đầu tiên, cơn giận của họ sẽ quay trở lại trạng thái của hiệp cuối cùng khi họ chưa hết giận dữ.',
		describe_en = 'The angel of time travels along the long river of time. The ancients are gone, but the vegetation remains. It wastes time engraving growth rings on all enemy targets, causing #C0x3D8A99#240% Magical Damage#C0x5B545B# + $(skillLevel*4*60)$’s #C0xF13B54# Magical Damage#C0x5B545B#. This will cause all heroes on the field to fall into [Time Turbulence] with 2 large rings \n#F10#\n#F40##L10#. Time Turbulence: #L0# The speed of all enemies is reduced by 10~30%, buff effects are shortened by 1 turn, debuff effects are extended by 1 turn, the speed of all allies is increased by 20%, buff effects are extended by 1 turn, and debuff effects are shortened by 1 turn. During this period, when the first three enemy heroes reach full rage for the first time, their rage will return to the state of the last turn when they were not yet enraged.',
		describe_th = 'เทพแห่งกาลเวลาผ่านการเดินทางในแม่น้ำแห่งกาลเวลาที่ยาวนาน ชาวโบราณได้จากไปแล้วแต่พืชพันธุ์ยังคงอยู่ มันใช้เวลาแกะสลักวงแหวนการเจริญเติบโตลงบนเป้าหมายศัตรูทั้งหมด ก่อให้เกิด #C0x3D8A99#240% ความเสียหายเวทมนตร์#C0x5B545B# + $(skillLevel*4*60)$’s #C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# สิ่งนี้จะทำให้ฮีโร่ทุกตัวบนสนามตกอยู่ใน [Time Turbulence] พร้อม 2 วงแหวนใหญ่ \n#F10#\n#F40##L10# เวลาวุ่นวาย: #L0# ความเร็วของศัตรูทั้งหมดลดลง 10~30% ผลบัฟลดลง 1 เทิร์น ผลดีบัฟเพิ่มขึ้น 1 เทิร์น ความเร็วของพันธมิตรทั้งหมดเพิ่มขึ้น 20% ผลบัฟเพิ่มขึ้น 1 เทิร์น และผลดีบัฟลดลง 1 เทิร์น ในช่วงเวลานี้ เมื่อฮีโร่ศัตรูสามคนแรกถึงความโกรธเต็มครั้งแรก ความโกรธของพวกเขาจะกลับสู่สถานะของเทิร์นก่อนหน้าที่พวกเขายังไม่โกรธ',
		describe_in = 'Malaikat waktu melakukan perjalanan di sepanjang sungai waktu yang panjang. Orang-orang zaman dahulu telah tiada, tetapi vegetasinya masih ada. Ia membuang waktu mengukir cincin pertumbuhan pada semua target musuh, menyebabkan #C0x3D8A99#240% Kerusakan Sihir#C0x5B545B# + $(skillLevel*4*60)$’s #C0xF13B54# Kerusakan Sihir#C0x5B545B#. Ini akan membuat semua pahlawan di lapangan jatuh ke dalam [Time Turbulence] dengan 2 cincin besar \n#F10#\n#F40##L10#. Waktu Kacau: #L0# Kecepatan semua musuh berkurang 10~30%, efek buff berkurang 1 giliran, efek debuff bertambah 1 giliran, kecepatan semua sekutu meningkat 20%, efek buff bertambah 1 giliran, dan efek debuff berkurang 1 giliran. Dalam periode ini, ketika tiga pahlawan musuh pertama mencapai kemarahan penuh untuk pertama kalinya, kemarahan mereka akan kembali ke keadaan giliran terakhir saat mereka belum marah.',
		describe_ph = 'Anghel ng panahon ay naglalakbay sa mahabaang ilog ng panahon. Ang mga sinauna ay wala na, ngunit ang mga halaman ay nananatili. Sinasayang nito ang panahon sa pag-ukit ng mga singsing ng paglago sa lahat ng mga target na kalaban, na nagdudulot ng #C0x3D8A99#240% Pinsalang Mahika#C0x5B545B# + $(skillLevel*4*60)$’s #C0xF13B54# Pinsalang Mahika#C0x5B545B#. Magdudulot ito ng lahat ng bayani sa larangan na malagay sa [Time Turbulence] na may 2 malaking singsing \n#F10#\n#F40##L10#. Time Turbulence: #L0# Ang bilis ng lahat ng kalaban ay bumababa ng 10~30%, ang epekto ng buff ay nababawasan ng 1 na turn, ang epekto ng debuff ay nadadagdagan ng 1 na turn, ang bilis ng lahat ng mga kakampi ay tumataas ng 20%, ang epekto ng buff ay nadadagdagan ng 1 na turn, at ang epekto ng debuff ay nababawasan ng 1 na turn. Sa panahong ito, kapag ang unang tatlong bayani ng kalaban ay umabot sa ganap na galit sa kanilang unang pagkakataon, babalik ang kanilang galit sa estado ng nakaraang turn kung kailan hindi pa sila galit.',
		describe_ma = 'Malaikat masa melakukan perjalanan di sepanjang sungai masa yang panjang. Orang dahulu telah tiada, tetapi tumbuhan masih ada. Ia membazir masa untuk mengukir cincin pertumbuhan pada semua sasaran musuh, menyebabkan #C0x3D8A99#240% Kerosakan Sihir#C0x5B545B# + $(skillLevel*4*60)$’s #C0xF13B54# Kerosakan Sihir#C0x5B545B#. Ini akan menyebabkan semua wira di medan jatuh ke dalam [Time Turbulence] dengan 2 cincin besar \n#F10#\n#F40##L10#. Kekacauan Masa: #L0# Kelajuan semua musuh dikurangkan 10~30%, efek buff dikurangkan 1 pusingan, efek debuff ditambah 1 pusingan, kelajuan semua sekutu ditingkatkan 20%, efek buff ditambah 1 pusingan, dan efek debuff dikurangkan 1 pusingan. Dalam tempoh ini, apabila tiga wira musuh pertama mencapai kemarahan penuh buat kali pertama, kemarahan mereka akan kembali ke keadaan pusingan terakhir ketika mereka belum marah.',
		describe = 'The angel of time travels along the long river of time. The ancients are gone, but the vegetation remains. It wastes time engraving growth rings on all enemy targets, causing #C0x3D8A99#240% Magical Damage#C0x5B545B# + $(skillLevel*4*60)$’s #C0xF13B54# Magical Damage#C0x5B545B#. This will cause all heroes on the field to fall into [Time Turbulence] with 2 large rings \n#F10#\n#F40##L10#. Time Turbulence: #L0# The speed of all enemies is reduced by 10~30%, buff effects are shortened by 1 turn, debuff effects are extended by 1 turn, the speed of all allies is increased by 20%, buff effects are extended by 1 turn, and debuff effects are shortened by 1 turn. During this period, when the first three enemy heroes reach full rage for the first time, their rage will return to the state of the last turn when they were not yet enraged.',
		simDesc_vn = 'Thiên thần Thời gian du hành trong khu rừng thời gian. Quá khứ đã qua đi nhưng cỏ cây vẫn còn tồn tại. Nó xoay chuyển thời gian để khắc các vòng tròn hàng năm lên tất cả các mục tiêu của kẻ thù và lôi kéo tất cả các anh hùng trên chiến trường vào sự hỗn loạn của thời gian. Tốc độ của tất cả kẻ thù bị giảm, hiệu ứng tăng được giảm và hiệu ứng tiêu cực tăng lên. Tất cả kẻ thù đều đảo ngược, cơn giận của kẻ thù được đưa trở lại trạng thái chưa hết giận dữ.',
		simDesc_en = 'The Time Angel travels through the time forest. The past has passed, but the grass and trees still remain. It manipulates time to engrave annual circles on all enemy targets and drags all heroes on the battlefield into the chaos of time. The speed of all enemies is reduced, positive effects are diminished, and negative effects are increased. All enemies are reversed, and their wrath is restored to an unending fury state.',
		simDesc_th = 'เทวดาแห่งกาลเวลากำลังเดินทางผ่านป่ากาลเวลา อดีตได้ผ่านไปแล้วแต่ต้นไม้และหญ้ายังคงอยู่ มันหมุนเวลากลเพื่อสลักวงกลมประจำปีลงบนเป้าหมายศัตรูทั้งหมดและดึงเหล่าวีรบุรุษทุกคนบนสนามรบเข้าสู่ความอลหม่านแห่งเวลา ความเร็วของศัตรูทั้งหมดถูกลดลง ผลบวกลดลงและผลลบเพิ่มขึ้น ศัตรูทั้งหมดถูกกลับด้านและความโกรธของศัตรูกลับคืนสู่สถานะไม่สิ้นสุด',
		simDesc_in = 'Malaikat Waktu melakukan perjalanan dalam hutan waktu. Masa lalu telah berlalu, tetapi rumput dan pepohonan masih ada. Ia memutar waktu untuk mengukir lingkaran tahunan pada semua target musuh dan menyeret semua pahlawan di medan perang ke dalam kekacauan waktu. Kecepatan semua musuh berkurang, efek positif berkurang, dan efek negatif meningkat. Semua musuh dibalikkan, amarah mereka dikembalikan ke keadaan kemarahan yang belum mereda.',
		simDesc_ph = 'Anghel ng Panahon ay naglalakbay sa gubat ng panahon. Lumipas na ang nakaraan ngunit nananatili pa rin ang mga damo at puno. Iniikot nito ang panahon upang ukitin ang mga taunang bilog sa lahat ng mga target ng kaaway at hinihila lahat ng mga bayani sa battlefield sa kaguluhan ng panahon. Ang bilis ng lahat ng kaaway ay nababawasan, ang mga positibong epekto ay nababawasan at ang mga negatibong epekto ay nadaragdagan. Lahat ng mga kaaway ay binaligtad, at ang kanilang galit ay ibinabalik sa estado ng walang katapusang poot.',
		simDesc_ma = 'Malaikat Masa mengembara dalam hutan masa. Masa lalu telah berlalu tetapi rumput dan pokok masih wujud. Ia menggerakkan masa untuk mengukir bulatan tahunan pada semua sasaran musuh dan menarik semua wira di medan perang ke dalam kekacauan masa. Kelajuan semua musuh berkurang, kesan positif dikurangkan dan kesan negatif ditingkatkan. Semua musuh diterbalikkan, kemarahan mereka dikembalikan ke keadaan kemarahan yang belum reda.',
		simDesc = 'The Time Angel travels through the time forest. The past has passed, but the grass and trees still remain. It manipulates time to engrave annual circles on all enemy targets and drags all heroes on the battlefield into the chaos of time. The speed of all enemies is reduced, positive effects are diminished, and negative effects are increased. All enemies are reversed, and their wrath is restored to an unending fury state.',
		starEffect = __data_t__starEffect[9743],
		-- {11}
		starEffectDesc_vn = 'Thời gian hiệu lực của  <Thời Gian Loạn Lưu>  tăng lên 3 lượt lớn, hồi nộ tác dụng lên toàn bộ địch phương; khiến tất cả mục tiêu địch trên sân từng bị gắn  <Bom Thời Gian>  nhận thêm một  <Bom Thời Gian> , nếu không có địch nào từng bị gắn thì thêm một  <Bom Thời Gian> .',
		starEffectDesc = '[กระแสเวลาปั่นป่วน] ระยะเวลาต่อเนื่องเพิ่มเป็น 3 รอบใหญ่ ผลย้อนโทสะขยายผลครอบคลุมศัตรูทุกตัวในสนาม; ศัตรูทุกตัวที่เคยได้รับ [ระเบิดกาลเวลา] จะถูกเพิ่ม [ระเบิดกาลเวลา] อีกครั้ง หากไม่มีศัตรูใดเคยได้รับมาก่อน จะสุ่มเพิ่ม [ระเบิดกาลเวลา] 1 ลูก',
		starEffectDesc_en = 'The duration of <Thời Gian Loạn Lưu> is increased to 3 large turns. The rage effect applies to all enemies; all enemy targets on the field that were previously marked with <Bom Thời Gian> receive an additional <Bom Thời Gian>. If no enemy was previously marked, add one <Bom Thời Gian>.',
		starEffectDesc_th = '[กระแสเวลาปั่นป่วน] มีระยะเวลานานขึ้นเป็น 3 รอบใหญ่ เอฟเฟกต์ย้อนความโกรธจะมีผลต่อศัตรูทุกคนในสนาม ศัตรูทั้งหมดที่เคยถูกติดตั้ง [ระเบิดเวลา] จะได้รับ [ระเบิดเวลา] เพิ่มอีก 1 ลูก หากไม่มีใครเคยถูกติดตั้งมาก่อน จะสุ่มติดตั้ง [ระเบิดเวลา] จำนวน 1 ลูก',
		starEffectDesc_in = 'Durasi <Thời Gian Loạn Lưu> meningkat menjadi 3 giliran besar. Efek kemarahan berlaku pada seluruh musuh; semua target musuh di lapangan yang sebelumnya diberi tanda <Bom Thời Gian> akan menerima tambahan <Bom Thời Gian>. Jika tidak ada musuh yang pernah diberi tanda, tambahkan satu <Bom Thời Gian>.',
		starEffectDesc_ph = 'Ang tagal ng bisa ng <Thời Gian Loạn Lưu> ay tumaas sa 3 malaking turno, ang epekto ng galit ay para sa lahat ng kalaban; ang lahat ng kalabang target sa larangan na dati nang may marka ng <Bom Thời Gian> ay tatanggap ng karagdagang <Bom Thời Gian>. Kung walang kalabang may marka dati, magdagdag ng isang <Bom Thời Gian>.',
		starEffectDesc_ma = 'Tempoh sah <Thời Gian Loạn Lưu> meningkat kepada 3 pusingan besar, kesan amarah memberi impak kepada semua musuh; semua sasaran musuh di medan yang pernah ditandakan dengan <Bom Thời Gian> akan menerima tambahan satu <Bom Thời Gian>. Jika tiada musuh yang pernah ditandakan, tambahkan satu <Bom Thời Gian>.',
		zawakeEffect = __data_t__zawakeEffect[9743],
		-- {79003}
		zawakeEffectDesc = 'The angel of time travels through the time forest. The ancients are gone but the vegetation remains. He spends time carving the growth rings on all enemy targets, dealing #C0x3D8A99#240% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$’s #C0xF13B54# Magic Damage #C0x5B545B# and pulling all heroes on the field into <Time Turbulence> for 2 major rounds\n#F10#\n#F40##L10# Time Chaos: #L0# Overall enemy speed reduced by 10~30%, buff effects decreased by 1 turn, debuff effects increased by 1 turn, own team speed increased by 20%, buff effects increased by 1 turn and debuff effects decreased by 1 turn, before the first time three enemy heroes are full of rage, their anger will return in the last round when they are no longer angry, meanwhile the friendly shadows and superhumans with the lowest health will also receive the <Future Prediction> effect of the angel of time once, and the cooldown of minor skills will be shortened by 1 turn.',
		zawakeEffectDesc_en = 'The angel of time travels through the time forest. The ancients are gone but the vegetation remains. He spends time carving the growth rings on all enemy targets, dealing #C0x3D8A99#240% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$’s #C0xF13B54# Magic Damage #C0x5B545B# and pulling all heroes on the field into <Time Turbulence> for 2 major rounds\n#F10#\n#F40##L10# Time Chaos: #L0# Overall enemy speed reduced by 10~30%, buff effects decreased by 1 turn, debuff effects increased by 1 turn, own team speed increased by 20%, buff effects increased by 1 turn and debuff effects decreased by 1 turn, before the first time three enemy heroes are full of rage, their anger will return in the last round when they are no longer angry, meanwhile the friendly shadows and superhumans with the lowest health will also receive the <Future Prediction> effect of the angel of time once, and the cooldown of minor skills will be shortened by 1 turn.',
		zawakeEffectDesc_th = 'เทพแห่งกาลเวลาท่องผ่านป่ากาลเวลา ชาวโบราณได้หายไปแล้ว แต่พืชพรรณยังคงอยู่ เขาใช้เวลาสลักวงแหวนการเจริญเติบโตบนเป้าหมายศัตรูทั้งหมด ก่อให้เกิด #C0x3D8A99#240% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*60)$’s #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# และดึงฮีโร่ทั้งหมดในสนามเข้าสู่ <Time Turbulence> เป็นเวลา 2 รอบใหญ่\n#F10#\n#F40##L10# ความสับสนแห่งกาลเวลา: #L0# ความเร็วโดยรวมของศัตรูลดลง 10~30%, ผลดีลดลง 1 เทิร์น, ผลเสียเพิ่มขึ้น 1 เทิร์น, ความเร็วกลุ่มของเราสูงขึ้น 20%, ผลดีเพิ่มขึ้น 1 เทิร์น และ ผลเสียลดลง 1 เทิร์น ก่อนที่ 3 ฮีโร่ศัตรูจะมีความโกรธเต็มครั้งแรก ความโกรธของพวกเขาจะกลับมาในรอบสุดท้ายเมื่อพวกเขาไม่โกรธอีกต่อไป ในขณะเดียวกันเงาและซูเปอร์ฮีโร่ที่เป็นมิตรที่มีเลือดต่ำที่สุดจะได้รับเอฟเฟกต์ <การทำนายอนาคต> ของเทพแห่งกาลเวลา 1 ครั้ง และเวลาคูลดาวน์ของทักษะเล็กจะถูกลดลง 1 เทิร์น',
		zawakeEffectDesc_in = 'Malaikat waktu melakukan perjalanan melalui hutan waktu. Orang-orang kuno telah tiada tetapi vegetasi tetap ada. Dia menghabiskan waktu mengukir cincin pertumbuhan pada semua target musuh, menyebabkan #C0x3D8A99#240% Damage Magis#C0x5B545B#+$(skillLevel*4*60)$’s #C0xF13B54# Damage Magis #C0x5B545B# dan menarik semua pahlawan di lapangan ke dalam <Time Turbulence> selama 2 putaran utama \n#F10#\n#F40##L10# Kekacauan Waktu: #L0# Kecepatan keseluruhan musuh berkurang 10~30%, efek buff berkurang 1 giliran, efek debuff bertambah 1 giliran, kecepatan tim sendiri bertambah 20%, efek buff bertambah 1 giliran dan efek debuff berkurang 1 giliran, sebelum tiga pahlawan musuh pertama kali penuh amarah, kemarahan mereka akan kembali pada putaran terakhir ketika mereka tidak lagi marah, sementara bayangan dan superman yang bersahabat dengan darah terendah juga akan menerima efek <Prediksi Masa Depan> dari malaikat waktu sekali, dan cooldown skill kecil akan dipersingkat 1 giliran.',
		zawakeEffectDesc_ph = 'Anghel ng panahon ay naglalakbay sa gubat ng panahon. Wala na ang mga sinaunang tao ngunit nananatili pa rin ang halaman. Ginugol niya ang oras sa pag-ukit ng mga singsing ng paglago sa lahat ng layunin ng kalaban, na nagdudulot ng #C0x3D8A99#240% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$’s #C0xF13B54# Magic Damage #C0x5B545B# at hinihimok ang lahat ng mga bayani sa larangan sa <Time Turbulence> para sa 2 pangunahing round\n#F10#\n#F40##L10# Kaguluhan sa Panahon: #L0# Ang kabuuang bilis ng kaaway ay nabawasan ng 10~30%, nabawasan ng 1 turn ang mga epekto ng buff, nadagdagan ng 1 turn ang mga epekto ng debuff, tumaas ng 20% ang bilis ng sariling grupo, nadagdagan ng 1 turn ang mga epekto ng buff at nabawasan ng 1 turn ang mga epekto ng debuff, bago ang unang pagkakataon na tatlong bayani ng kalaban ay puno ng galit, babalik ang kanilang galit sa huling round kapag hindi na sila galit, samantala ang mga kaibigang anino at superhuman na may pinakamababang buhay ay makakatanggap din ng epekto ng <Future Prediction> ng anghel ng panahon isang beses, at ang cooldown ng mga maliit na kakayahan ay mapapaikli ng 1 turn.',
		zawakeEffectDesc_ma = 'Malaikat masa mengembara melalui hutan masa. Orang dahulu sudah tiada tetapi tumbuh-tumbuhan masih ada. Dia meluangkan masa mengukir gelang pertumbuhan pada semua sasaran musuh, menyebabkan #C0x3D8A99#240% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*60)$’s #C0xF13B54# Kerosakan Magik #C0x5B545B# dan menarik semua wira di medan ke dalam <Time Turbulence> selama 2 pusingan besar \n#F10#\n#F40##L10# Kekacauan Masa: #L0# Kelajuan keseluruhan musuh berkurang 10~30%, kesan buff berkurang 1 pusingan, kesan debuff bertambah 1 pusingan, kelajuan kumpulan sendiri bertambah 20%, kesan buff bertambah 1 pusingan dan kesan debuff berkurang 1 pusingan, sebelum tiga wira musuh penuh marah buat kali pertama, kemarahan mereka akan kembali pada pusingan terakhir apabila mereka tidak lagi marah, sementara bayangan dan manusia super mesra dengan darah terendah juga akan menerima kesan <Ramalan Masa Depan> malaikat masa sekali, dan masa cooldown kemahiran kecil akan dipendekkan 1 pusingan.',
		zawakeEffectDesc_vn = 'Thiên thần của thời gian du hành xuyên qua khu rừng thời gian. Người xưa đã không còn nhưng thảm thực vật vẫn còn đó. Anh ta dành thời gian khắc các vòng tăng trưởng lên tất cả mục tiêu của kẻ thù, gây ra #C0x3D8A99#240% Sát Thương Phép Thuật#C0x5B545B#+$(skillLev el*4*60)$’s #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# sẽ kéo tất cả anh hùng trên sân vào <Time Turbulence> trong 2 lớn round\n#F10#\n#F40##L10# Hỗn loạn thời gian: #L0# Tốc độ tổng thể của kẻ địch giảm 10~30%, hiệu ứng buff giảm 1 lượt, hiệu ứng tiêu cực tăng 1 lượt, tốc độ chung của nhóm mình tăng 20%, hiệu ứng buff tăng 1 lượt và hiệu ứng tiêu cực giảm 1 lượt, trước giai đoạn Khi ba tướng địch đầy giận dữ lần đầu tiên, sự tức giận của họ sẽ quay trở lại vòng cuối cùng khi họ không còn giận dữ, đồng thời các loại bóng tối và siêu nhân thân thiện có tỷ lệ máu thấp nhất cũng sẽ nhận được hiệu ứng <Dự đoán tương lai> của Thiên thần thời gian một lần, đồng thời thời gian hồi chiêu của các kỹ năng nhỏ sẽ được rút ngắn 1 hiệp.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '30% chance to instantly detonate <Time Bomb>',
		zawakeSimpleDesc_en = '30% chance to instantly detonate <Time Bomb>',
		zawakeSimpleDesc_th = 'มีโอกาส 30% ที่จะจุดระเบิด <ระเบิดเวลา> ทันที',
		zawakeSimpleDesc_in = '30% peluang untuk langsung meledakkan <Bom Waktu>',
		zawakeSimpleDesc_ph = '30% tsansa na agad sumabog ang <Oras na Bomba>',
		zawakeSimpleDesc_ma = '30% peluang untuk meletupkan <Bom Masa> serta-merta',
		zawakeSimpleDesc_vn = 'Loại cỏ thân thiện, loại siêu hoặc Dialga có tỷ lệ máu thấp nhất cũng sẽ nhận được hiệu ứng <Dự đoán tương lai> của Thiên thần thời gian một lần và thời gian hồi chiêu của kỹ năng nhỏ sẽ được rút ngắn 1 lượt.',
