	[9746] = {
		id = 9746,
		skillName_vn = 'Kiểm soát thời gian',
		skillName_en = 'Time Control',
		skillName_th = 'ควบคุมเวลา',
		skillName_in = 'Kontrol Waktu',
		skillName_ph = 'Kontrol ng Oras',
		skillName_ma = 'Kawalan Masa',
		skillName = 'Time Control',
		describe_vn = 'Dấu thời gian: #L0# nhập và thêm [Dấu thời gian] cho chính bạn và người bạn có đòn tấn công cao nhất. Khi thêm vào, mạng sống và cơn giận hiện tại của mục tiêu sẽ được ghi lại. Khi nhận sát thương chí mạng, [Dấu ấn thời gian] sẽ bị tiêu hao để kích hoạt [Thu hồi thời gian và không gian]. Miễn nhiễm với sát thương này, sinh lực và tức giận sẽ được truy về giá trị đã ghi (không bị ảnh hưởng bởi việc điều trị). Hiệu ứng và tốc độ hồi phục tức giận sẽ không làm cho tức giận thấp hơn giá trị hiện tại), xóa bỏ mọi hiệu ứng khống chế và tiêu cực, đồng thời tăng #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#giảm sát thương cuối cùng trong 2 lượt. \n#F10#\n#F40##L10#Dự đoán tương lai: #L0#Hãy nhận biết trước những mối nguy hiểm trong tương lai và tránh hoàn toàn sát thương kỹ năng (hiệu ứng được đánh cách nhau 5 lần)\n#F10#\n#F40##L10#Biến động thời gian: #L0#Mỗi khi thiên thần thời gian hành động hoặc hiệu ứng hồi tưởng được kích hoạt, [biến động thời gian] sẽ được tạo ra, khiến nhóm thân thiện Giảm thời gian hồi chiêu của kỹ năng anh hùng ngẫu nhiên thêm 1 lượt và kéo dài thời gian hồi chiêu của các kỹ năng anh hùng ngẫu nhiên của kẻ thù thêm 1 lượt, đồng thời tăng thời gian phát nổ của tất cả [Bom hẹn giờ] trên sân của kẻ thù thêm 1 lượt\n#F10#\n#F40##L10#Purification of Time: #L0#Khi tất cả đồng minh nhận 3 hiệu ứng tiêu cực, ngay lập tức loại bỏ 2 hiệu ứng tiêu cực trong trại của bạn.',
		describe_en = 'Timestamp: #L0# input and add [Timestamp] for yourself and your highest attack friend. When added, the target\'s current HP and rage will be recorded. When receiving a critical hit, [Timestamp] will be consumed to activate [Time and Space Rewind]. Immune to this damage, HP and rage will revert to the recorded value (not affected by healing). Effects and rage recovery speed will not reduce rage below the current value), removing all crowd control and negative effects, and increasing #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# final damage reduction for 2 turns. \n#F10#\n#F40##L10#Future Prediction: #L0#Recognize future dangers in advance and completely avoid skill damage (effect stacks 5 times) \n#F10#\n#F40##L10#Time Fluctuation: #L0#Each time the time angel acts or a recall effect triggers, [time fluctuation] is created, causing the friendly group to reduce a random hero skill cooldown by 1 turn and extending a random enemy hero skill cooldown by 1 turn, also increasing explosion time of all [Timed Bombs] on the enemy field by 1 turn \n#F10#\n#F40##L10#Purification of Time: #L0#When all allies receive 3 negative effects, immediately remove 2 negative effects within your camp.',
		describe_th = 'เครื่องหมายเวลาช่วง: #L0# ป้อนและเพิ่ม [เครื่องหมายเวลาช่วง] ให้กับตัวคุณและเพื่อนที่มีพลังโจมตีสูงที่สุด เมื่อเพิ่มแล้ว จะบันทึกพลังชีวิตปัจจุบันและความโกรธของเป้าหมาย เมื่อได้รับความเสียหายคริใหม่ [เครื่องหมายเวลาช่วง] จะถูกใช้เพื่อเปิดใช้งาน [ย้อนเวลาพื้นที่และเวลา] ป้องกันความเสียหายนี้ พลังชีวิตและความโกรธจะกลับสู่ค่าที่บันทึกไว้ (ไม่ได้รับผลกระทบจากการรักษา) ผลกระทบและความเร็วในการฟื้นฟูความโกรธจะไม่ลดความโกรธต่ำกว่าค่าปัจจุบัน), ล้างสถานะควบคุมฝูงชนและสถานะลบทั้งหมด และเพิ่ม #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# ลดความเสียหายสุดท้ายเป็นเวลา 2 เทิร์น \n#F10#\n#F40##L10#การทำนายอนาคต: #L0# ระบุอันตรายล่วงหน้าและหลีกเลี่ยงความเสียหายจากทักษะอย่างสมบูรณ์ (ผลซ้อนกัน 5 ครั้ง) \n#F10#\n#F40##L10#ความผันผวนของเวลา: #L0#ทุกครั้งที่ทูตแห่งเวลาเคลื่อนไหวหรือมีการเปิดใช้งานผลย้อนกลับ จะสร้าง [ความผันผวนของเวลา] ทำให้กลุ่มมิตรลดคูลดาวน์สกิลฮีโร่แบบสุ่มลง 1 เทิร์น และเพิ่มคูลดาวน์สกิลฮีโร่ของศัตรูแบบสุ่มขึ้น 1 เทิร์น พร้อมทั้งเพิ่มเวลาระเบิดของ [ระเบิดจับเวลา] ทั้งหมดบนสนามศัตรูอีก 1 เทิร์น \n#F10#\n#F40##L10#การชำระล้างแห่งเวลา: #L0#เมื่อพันธมิตรทุกคนได้รับสถานะลบ 3 อย่าง จะลบสถานะลบ 2 อย่างในค่ายของคุณทันที',
		describe_in = 'Cap Tanggal: #L0# masukkan dan tambahkan [Cap Tanggal] untuk diri Anda dan teman dengan serangan tertinggi. Saat ditambahkan, HP dan kemarahan target saat ini akan dicatat. Saat menerima serangan kritis, [Cap Tanggal] akan terpakai untuk mengaktifkan [Pemulihan Waktu dan Ruang]. Kebal terhadap kerusakan ini, HP dan kemarahan akan kembali ke nilai yang dicatat (tidak terpengaruh oleh penyembuhan). Efek dan kecepatan pemulihan kemarahan tidak akan menurunkan kemarahan di bawah nilai saat ini), menghapus semua efek kontrol massa dan negatif, serta meningkatkan #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# pengurangan kerusakan akhir selama 2 giliran. \n#F10#\n#F40##L10#Prediksi Masa Depan: #L0#Kenali bahaya di masa depan terlebih dahulu dan hindari sepenuhnya kerusakan skill (efek dapat menumpuk hingga 5 kali) \n#F10#\n#F40##L10#Fluktuasi Waktu: #L0#Setiap kali malaikat waktu bertindak atau efek ingatan diaktifkan, [fluktuasi waktu] akan tercipta, menyebabkan kelompok ramah mengurangi cooldown skill pahlawan acak sebesar 1 giliran dan memperpanjang cooldown skill pahlawan musuh acak sebesar 1 giliran, sekaligus menambah waktu ledakan semua [Bom Waktu] di medan musuh sebesar 1 giliran \n#F10#\n#F40##L10#Pemurnian Waktu: #L0#Ketika semua sekutu menerima 3 efek negatif, segera hapus 2 efek negatif dalam kamp Anda.',
		describe_ph = 'Timestamp: #L0# ipasok at idagdag ang [Timestamp] para sa iyong sarili at sa kaibigan mo na may pinakamataas na atake. Kapag naidagdag, itatala ang kasalukuyang HP at galit ng target. Kapag tumanggap ng kritikal na pinsala, gagamitin ang [Timestamp] para i-activate ang [Pagbawi ng Oras at Espasyo]. Hindi maaapektuhan ng pinsala na ito, babalik ang HP at galit sa naitalang halaga (hindi naaapektuhan ng pagpapagaling). Ang mga epekto at bilis ng paggaling ng galit ay hindi bababa sa kasalukuyang halaga), aalisin ang lahat ng control at negatibong epekto, at magdaragdag ng #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# bawas ng huling pinsala sa loob ng 2 turn. \n#F10#\n#F40##L10#Hula ng Hinaharap: #L0#Alamin nang maaga ang mga panganib sa hinaharap at ganap na iwasan ang pinsala mula sa skill (mga epekto ay maaaring mag-stack ng 5 beses) \n#F10#\n#F40##L10#Pag-alon ng Oras: #L0#Tuwing gagawa ng aksyon ang anghel ng oras o ma-activate ang recall effect, lilikhain ang [pag-alon ng oras], kung saan magpapababa ng random cooldown ng hero skill ng kaalyado ng 1 turn at magpapahaba ng random cooldown ng hero skill ng kalaban ng 1 turn, pati na rin magpapahaba ng explosion time ng lahat ng [Timed Bombs] sa field ng kalaban ng 1 turn \n#F10#\n#F40##L10#Paglilinis ng Oras: #L0#Kapag ang lahat ng kakampi ay nakatanggap ng 3 negatibong epekto, agad na tatanggalin ang 2 negatibong epekto sa iyong kampo.',
		describe_ma = 'Penanda Masa: #L0# masukkan dan tambahkan [Penanda Masa] untuk diri anda dan rakan dengan serangan tertinggi. Apabila ditambah, nyawa dan kemarahan sasaran semasa akan direkodkan. Apabila menerima serangan kritikal, [Penanda Masa] akan digunakan untuk mengaktifkan [Imbasan Masa dan Ruang]. Kebal terhadap kerosakan ini, nyawa dan kemarahan akan kembali ke nilai yang direkod (tidak terjejas oleh rawatan). Kesan dan kelajuan pemulihan kemarahan tidak akan menurunkan kemarahan di bawah nilai semasa), membuang semua kesan kawalan kumpulan dan negatif, serta meningkatkan #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# pengurangan kerosakan akhir selama 2 pusingan. \n#F10#\n#F40##L10#Ramalan Masa Depan: #L0#Kenal pasti bahaya masa depan terlebih dahulu dan elakkan sepenuhnya kerosakan kemahiran (kesan boleh bertindih sehingga 5 kali) \n#F10#\n#F40##L10#Gelembung Masa: #L0#Setiap kali malaikat masa bertindak atau kesan ingatan diaktifkan, [gelembung masa] akan terhasil, menyebabkan kumpulan mesra mengurangkan masa sejuk kemahiran wira secara rawak sebanyak 1 pusingan dan memanjangkan masa sejuk kemahiran wira musuh secara rawak sebanyak 1 pusingan, serta menambah masa letupan semua [Bom Waktu] di medan musuh sebanyak 1 pusingan \n#F10#\n#F40##L10#Penulenan Masa: #L0#Apabila semua sekutu menerima 3 kesan negatif, segera buang 2 kesan negatif dari kem anda.',
		describe = 'Timestamp: #L0# input and add [Timestamp] for yourself and your highest attack friend. When added, the target\'s current HP and rage will be recorded. When receiving a critical hit, [Timestamp] will be consumed to activate [Time and Space Rewind]. Immune to this damage, HP and rage will revert to the recorded value (not affected by healing). Effects and rage recovery speed will not reduce rage below the current value), removing all crowd control and negative effects, and increasing #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# final damage reduction for 2 turns. \n#F10#\n#F40##L10#Future Prediction: #L0#Recognize future dangers in advance and completely avoid skill damage (effect stacks 5 times) \n#F10#\n#F40##L10#Time Fluctuation: #L0#Each time the time angel acts or a recall effect triggers, [time fluctuation] is created, causing the friendly group to reduce a random hero skill cooldown by 1 turn and extending a random enemy hero skill cooldown by 1 turn, also increasing explosion time of all [Timed Bombs] on the enemy field by 1 turn \n#F10#\n#F40##L10#Purification of Time: #L0#When all allies receive 3 negative effects, immediately remove 2 negative effects within your camp.',
		starEffect = __data_t__starEffect[9746],
		-- {8}
		starEffectDesc_vn = 'Cứ mỗi 1 hiệp lớn, lại thêm  <Dấu Ấn Thời Gian>  cho một đồng minh ngẫu nhiên (Dấu Ấn Thời Gian chỉ có hiệu lực một lần trên mỗi mục tiêu).',
		starEffectDesc = 'Every major round, add <Time Seal> to a random ally (Time Seal only takes effect once per target).',
		starEffectDesc_en = 'Every major round, add <Time Seal> to a random ally (Time Seal only takes effect once per target).',
		starEffectDesc_th = 'ในแต่ละรอบใหญ่ ให้เพิ่ม <Time Seal> ให้กับพันธมิตรแบบสุ่ม (Time Seal มีผลเพียงหนึ่งครั้งต่อตัวเป้าหมายแต่ละตัว)',
		starEffectDesc_in = 'Setiap ronde besar, tambahkan <Time Seal> pada sekutu acak (Time Seal hanya berlaku sekali untuk setiap target).',
		starEffectDesc_ph = 'Sa bawat malaking round, maglagay ng <Time Seal> sa isang random na kakampi (Ang Time Seal ay may bisa lamang isang beses kada target).',
		starEffectDesc_ma = 'Setiap pusingan besar, tambahkan <Time Seal> pada sekutu rawak (Time Seal hanya berkuat kuasa sekali pada setiap sasaran).',
		zawakeEffect = __data_t__zawakeEffect[9746],
		-- {79004}
		zawakeEffectDesc = '#L0# Timestamp: Enter and add <Timestamp> to yourself and the ally with the highest attack (further reduce final damage by 15% for darkness and superpower). When added, the target\'s current health and rage are recorded. Upon receiving critical damage, <Timestamp> triggers <Time and Space Recall>, granting immunity to this damage while restoring health and rage. Revert to the recorded values (unaffected by healing effects and rage recovery speed, and will not lower rage below current value), remove all control and negative effects, and increase final damage reduction #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# for 2 more turns. \n#F10#\n#F40##L10#Future Prediction: #L0# Anticipate future dangers and completely avoid skill damage (effect triggers every 4 times) \n#F10#\n#F40##L10#Time Distortion: #L0# Each time the Time Angel acts or recall effect activates, <Time Distortion> is created, reducing cooldown of a random friendly heroic skill by 1 turn and increasing cooldown of a random enemy heroic skill by 1 turn, while also extending detonation time of all <Timed Bombs> on enemy field by 1 turn \n#F10#\n#F40##L10#Purification of Time: #L0# When all allies receive 3 negative effects, immediately remove 2 negative effects from your camp.',
		zawakeEffectDesc_en = '#L0# Timestamp: Enter and add <Timestamp> to yourself and the ally with the highest attack (further reduce final damage by 15% for darkness and superpower). When added, the target\'s current health and rage are recorded. Upon receiving critical damage, <Timestamp> triggers <Time and Space Recall>, granting immunity to this damage while restoring health and rage. Revert to the recorded values (unaffected by healing effects and rage recovery speed, and will not lower rage below current value), remove all control and negative effects, and increase final damage reduction #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# for 2 more turns. \n#F10#\n#F40##L10#Future Prediction: #L0# Anticipate future dangers and completely avoid skill damage (effect triggers every 4 times) \n#F10#\n#F40##L10#Time Distortion: #L0# Each time the Time Angel acts or recall effect activates, <Time Distortion> is created, reducing cooldown of a random friendly heroic skill by 1 turn and increasing cooldown of a random enemy heroic skill by 1 turn, while also extending detonation time of all <Timed Bombs> on enemy field by 1 turn \n#F10#\n#F40##L10#Purification of Time: #L0# When all allies receive 3 negative effects, immediately remove 2 negative effects from your camp.',
		zawakeEffectDesc_th = '#L0# สัญญาณเวลาชั่วคราว: ป้อนและเพิ่ม <สัญญาณเวลาชั่วคราว> ให้ตัวเองและเพื่อนที่มีการโจมตีสูงสุด (ลดความเสียหายขั้นสุดท้ายเพิ่มเติม 15% สำหรับความมืดและพลังพิเศษ) เมื่อติดตั้ง เป้าหมายจะถูกบันทึกสุขภาพปัจจุบันและความโกรธ เมื่อตกเป็นเป้าหมายของความเสียหายคริติคอล <สัญญาณเวลาชั่วคราว> จะใช้งาน <การระลึกเวลาและอวกาศ> และความต้านทานต่อความเสียหายนี้จะฟื้นฟูพลังชีวิตและความโกรธ กลับสู่ค่าที่บันทึกไว้ (ไม่ถูกผลกระทบจากเอฟเฟกต์ฟื้นฟูและความเร็วฟื้นฟูความโกรธ และจะไม่ทำให้ความโกรธลดลงต่ำกว่าค่าปัจจุบัน) ลบเอฟเฟกต์ควบคุมและลบลบทั้งหมด และเพิ่มการลดความเสียหายขั้นสุดท้าย #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# เพิ่มอีก 2 เทิร์น \n#F10#\n#F40##L10#การทำนายอนาคต: #L0# รับรู้ล่วงหน้าถึงอันตรายในอนาคตและหลีกเลี่ยงความเสียหายสกิลทั้งหมด (เอฟเฟกต์ถูกกระตุ้นทุก 4 ครั้ง) \n#F10#\n#F40##L10#ความผิดปกติของเวลา: #L0# ทุกครั้งที่ทูตแห่งเวลาเคลื่อนไหวหรือเอฟเฟกต์การระลึกถูกกระตุ้น จะสร้าง <ความผิดปกติของเวลา> ที่ลดคูลดาวน์สกิลวีรบุรุษสุ่มของฝ่ายเพื่อน 1 เทิร์น และเพิ่มคูลดาวน์สกิลวีรบุรุษสุ่มของศัตรู 1 เทิร์น พร้อมเพิ่มเวลาระเบิดของ <ระเบิดตั้งเวลาทุกลูก> ในสนามศัตรูอีก 1 เทิร์น \n#F10#\n#F40##L10#การชำระเวลาของกาลเวลา: #L0# เมื่อพันธมิตรทั้งหมดได้รับเอฟเฟกต์ลบ 3 ครั้ง ให้ลบ 2 เอฟเฟกต์ลบในค่ายของคุณทันที',
		zawakeEffectDesc_in = '#L0# Tanda Waktu: Masuk dan tambahkan <Tanda Waktu> pada diri sendiri dan teman dengan serangan tertinggi (mengurangi 15% lagi kerusakan akhir untuk kegelapan dan kekuatan super). Saat ditambahkan, nyawa dan kemarahan target saat ini akan dicatat. Saat menerima kerusakan kritis, <Tanda Waktu> mengaktifkan <Kenangan Waktu dan Ruang>, dan kekebalan terhadap kerusakan ini akan memulihkan kesehatan dan kemarahan. Kembali ke nilai yang tercatat (tidak terpengaruh oleh efek penyembuhan dan kecepatan pemulihan kemarahan, dan tidak akan menurunkan kemarahan di bawah nilai saat ini), menghapus semua efek kontrol dan efek negatif, serta meningkatkan pengurangan kerusakan akhir #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# selama 2 giliran lagi. \n#F10#\n#F40##L10#Prediksi Masa Depan: #L0# Sadari bahaya di masa depan dan hindari sepenuhnya kerusakan skill (efek dipicu setiap 4 kali) \n#F10#\n#F40##L10#Distorsi Waktu: #L0# Setiap kali Malaikat Waktu bertindak atau efek kenangan diaktifkan, <Distorsi Waktu> dibuat, mengurangi cooldown skill hero acak teman 1 giliran dan memperpanjang cooldown skill hero acak musuh 1 giliran, sekaligus memperpanjang waktu ledakan semua <Bom Waktu> di medan musuh 1 giliran \n#F10#\n#F40##L10#Pemurnian Waktu: #L0# Ketika semua sekutu menerima 3 efek negatif, segera hilangkan 2 efek negatif di kamp Anda.',
		zawakeEffectDesc_ph = '#L0# Tanda ng Panahon: Pumasok at magdagdag ng <Tanda ng Panahon> sa sarili at sa kaibigang may pinakamataas na atake (dagdagan ng bawas na 15% ang huling pinsala para sa kadiliman at superpower). Kapag idinagdag, ang kasalukuyang buhay at galit ng target ay maitatala. Kapag tumanggap ng kritikal na pinsala, ang <Tanda ng Panahon> ang nagpapatakbo ng <Paggunita ng Panahon at Espasyo>, at ang immunity sa pinsalang ito ay magpapagaling ng buhay at galit. Bumalik sa naitalang halaga (hindi naaapektuhan ng epekto ng paggaling at bilis ng pag-recover ng galit, at hindi bababa sa galit sa kasalukuyang halaga), alisin ang lahat ng control at negatibong epekto, at dagdagan ang bawas na huling pinsala #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# ng 2 turn pa. \n#F10#\n#F40##L10#Pagtataya ng Hinaharap: #L0# Alamin nang maaga ang mga panganib sa hinaharap at iwasan nang lubusan ang pinsala mula sa skill (epekto ay nai-activate kada 4 na beses) \n#F10#\n#F40##L10#Pagbaluktot ng Panahon: #L0# Tuwing kumikilos ang Time Angel o nag-aactivate ang recall effect, nalilikha ang <Pagbaluktot ng Panahon>, nagpapabawas ng cooldown ng random na bayani na skill ng kakampi ng 1 turn at nagpapahaba ng cooldown ng random na enemy na skill ng bayani ng 1 turn, kasabay ng pagpapahaba ng oras ng pagsabog ng lahat ng <Timed Bomb> sa field ng kalaban ng 1 turn \n#F10#\n#F40##L10#Paglilinis ng Panahon: #L0# Kapag ang lahat ng mga kakampi ay nakatanggap ng 3 negatibong epekto, agad tanggalin ang 2 negatibong epekto mula sa inyong kampo.',
		zawakeEffectDesc_ma = '#L0# Tanda Masa: Masuk dan tambah <Tanda Masa> pada diri sendiri dan rakan dengan serangan tertinggi (mengurangkan 15% lagi kerosakan akhir untuk kegelapan dan kuasa super). Apabila ditambah, nyawa dan kemarahan sasaran semasa akan direkod. Apabila menerima kerosakan kritikal, <Tanda Masa> mengaktifkan <Ingatan Masa dan Ruang>, dan imun terhadap kerosakan ini akan memulihkan kesihatan dan kemarahan. Kembali kepada nilai yang direkod (tidak terjejas oleh kesan penyembuhan dan kelajuan pemulihan kemarahan, dan tidak akan menurunkan kemarahan di bawah nilai semasa), hapus semua kesan kawalan dan negatif, serta tingkatkan pengurangan kerosakan akhir #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# selama 2 pusingan lagi. \n#F10#\n#F40##L10#Ramalan Masa Depan: #L0# Sangka bahaya yang akan datang dan elak sepenuhnya kerosakan kemahiran (kesan dicetus setiap 4 kali) \n#F10#\n#F40##L10#Distorsi Masa: #L0# Setiap kali Malaikat Masa bertindak atau kesan ingatan diaktifkan, <Distorsi Masa> dicipta, mengurangkan masa sejuk kemahiran kepahlawanan rawak rakan sebanyak 1 pusingan dan menambah masa sejuk kemahiran kepahlawanan rawak musuh sebanyak 1 pusingan, serta memanjangkan masa letupan semua <Bom Masa> di medan musuh sebanyak 1 pusingan \n#F10#\n#F40##L10#Penulenan Masa: #L0# Bila semua sekutu menerima 3 kesan negatif, segera alihkan 2 kesan negatif di kem anda.',
		zawakeEffectDesc_vn = 'Dấu thời gian: #L0# nhập và thêm <Dấu thời gian> cho bản thân và người bạn có đòn tấn công cao nhất (giảm thêm 15% sát thương cuối cùng cho bóng tối và siêu năng lực). Khi được thêm vào, mạng sống và cơn giận hiện tại của mục tiêu sẽ được ghi lại. Khi nhận sát thương chí mạng, <Dấu thời gian> được sử dụng để kích hoạt <Hồi tưởng thời gian và không gian>, và khả năng miễn nhiễm với sát thương này sẽ tăng sinh lực và sự tức giận. Quay trở lại giá trị đã ghi (không bị ảnh hưởng bởi hiệu ứng hồi máu và tốc độ hồi phục cơn thịnh nộ, đồng thời sẽ không khiến cơn thịnh nộ thấp hơn giá trị hiện tại), xóa bỏ mọi hiệu ứng khống chế và tiêu cực, đồng thời tăng mức giảm sát thương cuối cùng #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# thêm 2 lượt. \n#F10#\n#F40##L10#Dự đoán tương lai: #L0#Hãy nhận biết trước những mối nguy hiểm trong tương lai và tránh hoàn toàn sát thương kỹ năng (hiệu ứng được đánh cách nhau 4 lần)\n#F10#\n#F40##L10#Biến động thời gian: #L0#Mỗi khi Thiên thần thời gian hành động hoặc hiệu ứng hồi tưởng được kích hoạt, <Biến động thời gian> sẽ được tạo ra, khiến nhóm thân thiện Giảm thời gian hồi chiêu của kỹ năng anh hùng ngẫu nhiên thêm 1 lượt và kéo dài thời gian hồi chiêu của các kỹ năng anh hùng ngẫu nhiên của kẻ thù thêm 1 lượt, đồng thời tăng thời gian phát nổ của tất cả <Bom hẹn giờ> trên sân của kẻ thù thêm 1 lượt\n#F10#\n#F40##L10#Purification of Time: #L0#Khi tất cả đồng minh nhận 3 hiệu ứng tiêu cực, ngay lập tức loại bỏ 2 hiệu ứng tiêu cực trong trại của bạn.',
		zawakeSimpleType = 1,
