	[10313] = {
		id = 10313,
		skillName_vn = 'Tia sáng sắc bén',
		skillName_en = 'Sharp Light',
		skillName_th = 'แสงที่คมชัด',
		skillName_in = 'Cahaya Tajam',
		skillName_ph = 'Matingning ng Liwanag',
		skillName_ma = 'Cahaya Tajam',
		skillName = 'Sharp Light',
		describe_vn = 'Bọ cạp lao về phía mục tiêu từ trên không, dùng răng ba thuộc tính để cắn và tấn công, gây #C0xE69900#220% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ của #C0xF1 lên mục tiêu chính 3B54#Sát Thương Vật Lý#C0x5B545B# và áp dụng hiệu ứng [Tê liệt] trong 3 lượt và bắn thêm hai mục tiêu ngẫu nhiên để gây 100% sát thương và áp dụng một trong các hiệu ứng [Đóng băng] hoặc [Đốt cháy] cho mỗi đơn vị trong 3 lượt\n#F20# \n#F40#[Tê liệt]: Hiệu ứng khống chế, không thể sử dụng chiêu thức đặc biệt\n[Đóng băng]: Hiệu ứng khống chế, không thể di chuyển, sẽ được giải phóng sau khi nhận sát thương vượt quá 15% giới hạn máu của mục tiêu\n[Burning]: Hiệu ứng tiêu cực, mục tiêu sẽ nhận 150% phòng thủ vật lý của Bọ cạp sát thương thực sự trước mỗi hành động',
		describe_en = 'The scorpion lunges at the target from the air, using its triple-attribute fangs to bite and attack, dealing #C0xE69900#220% Physical Damage#C0x5B545B# + $(skillLevel*4*48)$ of #C0xF1# to the main target 3B54#Physical Damage#C0x5B545B# and applying the [Paralysis] effect for 3 turns. It also shoots two additional random targets, dealing 100% damage and applying one of the effects [Freeze] or [Burn] to each unit for 3 turns. \n#F20# \n#F40#[Paralysis]: A control effect that disables the use of special skills. \n[Freeze]: A control effect that prevents movement and is released when the target takes damage exceeding 15% of their max HP. \n[Burning]: A debuff that causes the target to take true damage equal to 150% of the Scorpion\'s physical defense before each action.',
		describe_th = 'แมงป่องพุ่งเข้าสู่เป้าหมายจากบนอากาศ ใช้ฟันสามคุณสมบัติของมันกัดและโจมตี สร้าง #C0xE69900#220% ความเสียหายทางกายภาพ#C0x5B545B# + $(skillLevel*4*48)$ ของ #C0xF1# ให้กับเป้าหมายหลัก 3B54#ความเสียหายทางกายภาพ#C0x5B545B# และติดสถานะ [ตะคริว] เป็นเวลา 3 รอบ และยิงเป้าหมายสุ่มอีกสองตัวเพื่อสร้างความเสียหาย 100% และติดสถานะ [แช่แข็ง] หรือ [ไฟลุกไหม้] หนึ่งในสองสถานะต่อยูนิตแต่ละตัวเป็นเวลา 3 รอบ \n#F20# \n#F40#[ตะคริว]: สถานะควบคุม ห้ามใช้สกิลพิเศษ \n[แช่แข็ง]: สถานะควบคุม ห้ามเคลื่อนที่ และจะถูกปลดปล่อยเมื่อได้รับความเสียหายเกิน 15% ของพลังชีวิตสูงสุด \n[ไฟไหม้]: สถานะลบ ยูนิตจะได้รับความเสียหายจริงเท่ากับ 150% ของพลังป้องกันทางกายภาพของแมงป่องก่อนแต่ละครั้งที่ทำการเคลื่อนไหว',
		describe_in = 'Kalajengking meluncur ke target dari udara, menggunakan taring dengan tiga atribut untuk menggigit dan menyerang, menyebabkan #C0xE69900#220% Kerusakan Fisik#C0x5B545B# + $(skillLevel*4*48)$ dari #C0xF1# pada target utama 3B54#Kerusakan Fisik#C0x5B545B# dan menerapkan efek [Paralisis] selama 3 giliran serta menembak dua target acak tambahan untuk menyebabkan 100% kerusakan dan menerapkan salah satu efek [Bekukan] atau [Terbakar] pada setiap unit selama 3 giliran \n#F20# \n#F40#[Paralisis]: Efek kontrol yang mencegah penggunaan keterampilan khusus \n[Bekukan]: Efek kontrol yang mencegah pergerakan dan akan hilang setelah menerima kerusakan melebihi 15% dari batas HP target \n[Terbakar]: Efek negatif yang menyebabkan target menerima damage nyata sebesar 150% dari pertahanan fisik Kalajengking sebelum setiap aksi',
		describe_ph = 'Ang gagamba ng alimango ay sumugod sa target mula sa himpapawid, gamit ang tatlong katangian ng mga pangil nito upang kumagat at umatake, na nagdudulot ng #C0xE69900#220% Pisikal na Pinsala#C0x5B545B# + $(skillLevel*4*48)$ ng #C0xF1# sa pangunahing target 3B54#Pisikal na Pinsala#C0x5B545B# at naglalapat ng epekto [Paralisis] sa loob ng 3 na turn, at nagpapaputok sa dalawang random na target para magdulot ng 100% pinsala at magtalaga ng isa sa mga epekto [Freeze] o [Burn] sa bawat yunit sa loob ng 3 na turn \n#F20# \n#F40#[Paralisis]: Isang kontrol na epekto na pumipigil sa paggamit ng espesyal na kasanayan \n[Freeze]: Isang kontrol na epekto na pumipigil sa paggalaw at mawawala kapag nakatanggap ng pinsalang lampas sa 15% ng maximum na HP ng target \n[Burning]: Isang negatibong epekto na nagpapadala sa target ng totoong pinsala na katumbas ng 150% ng pisikal na depensa ng Gagamba ng Alimango bago ang bawat kilos',
		describe_ma = 'Kalajengking meluru ke arah sasaran dari udara, menggunakan taring tiga atribut untuk menggigit dan menyerang, menyebabkan #C0xE69900#220% Kerosakan Fizikal#C0x5B545B# + $(skillLevel*4*48)$ daripada #C0xF1# kepada sasaran utama 3B54#Kerosakan Fizikal#C0x5B545B# dan mengenakan kesan [Paralisis] selama 3 giliran serta menembak dua sasaran rawak tambahan untuk menyebabkan 100% kerosakan dan mengenakan salah satu kesan [Bekukan] atau [Terbakar] kepada setiap unit selama 3 giliran \n#F20# \n#F40#[Paralisis]: Kesan kawalan yang menghalang penggunaan kemahiran khas \n[Bekukan]: Kesan kawalan yang menghalang pergerakan dan akan dilepaskan selepas menerima kerosakan melebihi 15% had HP sasaran \n[Terbakar]: Kesan negatif yang menyebabkan sasaran menerima kerosakan benar sebanyak 150% pertahanan fizikal Kalajengking sebelum setiap tindakan',
		describe = 'The scorpion lunges at the target from the air, using its triple-attribute fangs to bite and attack, dealing #C0xE69900#220% Physical Damage#C0x5B545B# + $(skillLevel*4*48)$ of #C0xF1# to the main target 3B54#Physical Damage#C0x5B545B# and applying the [Paralysis] effect for 3 turns. It also shoots two additional random targets, dealing 100% damage and applying one of the effects [Freeze] or [Burn] to each unit for 3 turns. \n#F20# \n#F40#[Paralysis]: A control effect that disables the use of special skills. \n[Freeze]: A control effect that prevents movement and is released when the target takes damage exceeding 15% of their max HP. \n[Burning]: A debuff that causes the target to take true damage equal to 150% of the Scorpion\'s physical defense before each action.',
		simDesc_vn = 'Scizor lao từ trên không xuống tấn công mục tiêu bằng hàm răng có ba thuộc tính, gây hiệu ứng tê liệt, bỏng, đóng băng.',
		simDesc_en = 'Scizor swoops down from the sky to attack the target with its jaws possessing three attributes, causing paralysis, burn, and freeze effects.',
		simDesc_th = 'สไซเซอร์พุ่งลงมาจากท้องฟ้าโจมตียังเป้าหมายด้วยขากรรไกรที่มีคุณสมบัติสามประการ ทำให้เกิดผลกระทบชาระบบ การเผาไหม้ และการแช่แข็ง',
		simDesc_in = 'Scizor meluncur dari udara untuk menyerang target dengan rahangnya yang memiliki tiga atribut, menyebabkan efek paralisis, terbakar, dan beku.',
		simDesc_ph = 'Si Scizor ay bumagsak mula sa himpapawid para atakihin ang target gamit ang mga panga nito na may tatlong katangian, nagdudulot ng paralysis, paso, at nagyeyelong epekto.',
		simDesc_ma = 'Scizor meluncur dari udara menyerang sasaran dengan rahangnya yang mempunyai tiga atribut, menyebabkan kesan lumpuh, terbakar, dan beku.',
		simDesc = 'Scizor swoops down from the sky to attack the target with its jaws possessing three attributes, causing paralysis, burn, and freeze effects.',
		starEffect = __data_t__starEffect[10313],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: 60% xác suất <Mù> mục tiêu chưa bị tấn công bởi chiêu thức đặc biệt trong 1 lượt và áp dụng <Độc bọ cạp> trong 3 lượt\n#F20#\n#F40#<Mù>: Hiệu ứng tiêu cực, giảm tỷ lệ trúng đòn 40%',
		starEffectDesc = 'Enhance effect: 60% chance <Blind> target not yet attacked by a special skill within 1 turn and apply <Scorpion Poison> for 3 turns\n#F20#\n#F40#<Blind>: Negative effect, reduces hit rate by 40%',
		starEffectDesc_en = 'Enhance effect: 60% chance <Blind> target not yet attacked by a special skill within 1 turn and apply <Scorpion Poison> for 3 turns\n#F20#\n#F40#<Blind>: Negative effect, reduces hit rate by 40%',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: โอกาส 60% ที่จะทำให้ <มืดบอด> เป้าหมายที่ยังไม่ได้ถูกโจมตีด้วยสกิลพิเศษใน 1 ตา และใช้ <พิษแมงป่อง> เป็นเวลา 3 ตา\n#F20#\n#F40#<มืดบอด>: ผลลบ ลดอัตราการถูกโจมตี 40%',
		starEffectDesc_in = 'Tingkatkan efek: 60% peluang <Buta> target yang belum diserang oleh skill khusus dalam 1 giliran dan terapkan <Racun Kalajengking> selama 3 giliran\n#F20#\n#F40#<Buta>: Efek negatif, mengurangi peluang terkena serangan sebesar 40%',
