	[10323] = {
		id = 10323,
		skillName_vn = 'Trận Thập Sát Hung Minh',
		skillName_en = 'Battle of the Ten Fierce Allies',
		skillName_th = 'การต่อสู้ของพันธมิตรสิบผู้ดุร้าย',
		skillName_in = 'Pertempuran Sepuluh Sekutu Galak',
		skillName_ph = 'Labanan ng Sampung Mabagsik na Alyado',
		skillName_ma = 'Pertempuran Sepuluh Sekutu Galak',
		skillName = 'Battle of the Ten Fierce Allies',
		describe_vn = 'Amakusa Shirou Tokisada lao về phía mục tiêu từ trên không, giải phóng vòng tròn ma thuật của Thập Sát trận đáng ngại và gây ra #C0xE69900#430% Vật công#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# và áp dụng hiệu ứng [Tê liệt] trong 3 lượt, đồng thời bắn thêm hai mục tiêu ngẫu nhiên để gây 100% sát thương và áp dụng một trong các hiệu ứng [Đóng băng] hoặc [Đốt] cho mỗi đơn vị trong 3 lượt\n#F20# \n#F40#[Tê liệt]: Hiệu ứng khống chế, không thể sử dụng chiêu thức đặc biệt\n[Đóng băng]: Hiệu ứng khống chế, không thể để di chuyển, sẽ được giải phóng sau khi nhận sát thương vượt quá 15% giới hạn máu của mục tiêu\n[Đốt]: Hiệu ứng tiêu cực, mục tiêu sẽ nhận 150% sát thương thực tế phòng thủ vật lý của Amakusa Shirou Tokisada trước mỗi hành động',
		describe_en = 'Amakusa Shirou Tokisada charges at the target from the air, unleashing the formidable Decimation Magic Circle and dealing #C0xE69900#430% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B# and applying the [Paralysis] effect for 3 turns. He simultaneously shoots two random targets to deal 100% damage and applies either the [Freeze] or [Burn] effect to each unit for 3 turns. \n#F20# \n#F40#[Paralysis]: A control effect that disables the use of special skills. \n[Freeze]: A control effect that prevents movement and is released after taking damage exceeding 15% of the target\'s max HP. \n[Burn]: A negative effect causing the target to receive 150% of Amakusa Shirou Tokisada\'s true physical defense damage before each action.',
		describe_th = 'อมาคุสะ ชิโร่ โทคิซาดะ พุ่งเข้าหาศัตรูจากอากาศ ปลดปล่อยวงเวทย์ร้ายกาจของสิบสามสนามและสร้างความเสียหาย #C0xE69900#430% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# และทำให้เกิดสถานะ [ชาระงับ] เป็นเวลา 3 เทิร์น พร้อมยิงสองเป้าหมายสุ่มเพื่อสร้างความเสียหาย 100% และทำให้เกิดหนึ่งในสถานะ [แช่แข็ง] หรือ [ไฟลุก] กับแต่ละหน่วยเป็นเวลา 3 เทิร์น \n#F20# \n#F40#[ชาระงับ]: สถานะควบคุม ไม่สามารถใช้สกิลพิเศษได้ \n[แช่แข็ง]: สถานะควบคุม ไม่สามารถเคลื่อนที่ได้ จะถูกปลดปล่อยหลังจากได้รับความเสียหายเกินกว่า 15% ของพลังชีวิตสูงสุด \n[ไฟลุก]: สถานะลบ ศัตรูจะได้รับความเสียหายจริงจากพลังป้องกันกายภาพของอมาคุสะ ชิโร่ โทคิซาดะ 150% ก่อนแต่ละการกระทำ',
		describe_in = 'Amakusa Shirou Tokisada meluncur ke target dari udara, melepaskan Lingkaran Sihir Kuburan Belas yang menakutkan dan menyebabkan #C0xE69900#430% Serangan Fisik#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B# serta menerapkan efek [Kelumpuhan] selama 3 giliran. Bersamaan itu, menyerang dua target acak untuk menyebabkan 100% kerusakan dan menerapkan salah satu efek [Bekukan] atau [Terbakar] kepada setiap unit selama 3 giliran. \n#F20# \n#F40#[Kelumpuhan]: Efek kontrol, tidak dapat menggunakan skill khusus \n[Bekukan]: Efek kontrol, tidak dapat bergerak, akan hilang setelah menerima kerusakan melebihi 15% batas HP target \n[Terbakar]: Efek negatif, target akan menerima 150% dari kerusakan pertahanan fisik sejati Amakusa Shirou Tokisada sebelum setiap tindakan',
		describe_ph = 'Ang Amakusa Shirou Tokisada ay bumabagsak patungo sa target mula sa hangin, nagpapalabas ng nakakakilabot na Magic Circle ng Sampung Kamatayan at nagdudulot ng #C0xE69900#430% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B# at nagpapataw ng epekto ng [Paralisa] sa loob ng 3 mga turno. Kasabay nito, tumatarget ng dalawang random na kalaban upang magdulot ng 100% pinsala at nagpapataw ng isa sa mga epekto na [Yelo] o [Sunog] sa bawat yunit sa loob ng 3 mga turno. \n#F20# \n#F40#[Paralisa]: Isang kontrol na epekto na pumipigil sa paggamit ng espesyal na kakayahan. \n[Yelo]: Isang kontrol na epekto na pumipigil sa paggalaw, mawawala lamang kapag nakatanggap ng pinsalang higit sa 15% ng pinakamataas na HP ng target. \n[Sunog]: Isang negatibong epekto kung saan ang target ay tumatanggap ng 150% ng totoong pisikal na pinsala mula sa depensa ni Amakusa Shirou Tokisada bago bawat aksyon.',
		describe_ma = 'Amakusa Shirou Tokisada meluru ke arah sasaran dari udara, melepaskan bulatan sihir bangkai Thập Sát yang menggerunkan dan menyebabkan #C0xE69900#430% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B# serta mengenakan kesan [Lumpuh] selama 3 pusingan. Pada masa yang sama, menembak dua sasaran rawak untuk menyebabkan 100% kerosakan dan memberi salah satu kesan [Beku] atau [Terbakar] kepada setiap unit selama 3 pusingan. \n#F20# \n#F40#[Lumpuh]: Kesan kawalan, tidak boleh menggunakan kemahiran khas \n[Beku]: Kesan kawalan, tidak boleh bergerak, akan dilepaskan selepas menerima kerosakan melebihi 15% had darah sasaran \n[Terbakar]: Kesan negatif, sasaran akan menerima 150% kesan kerosakan sebenar pertahanan fizikal Amakusa Shirou Tokisada sebelum setiap tindakan',
		describe = 'Amakusa Shirou Tokisada charges at the target from the air, unleashing the formidable Decimation Magic Circle and dealing #C0xE69900#430% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B# and applying the [Paralysis] effect for 3 turns. He simultaneously shoots two random targets to deal 100% damage and applies either the [Freeze] or [Burn] effect to each unit for 3 turns. \n#F20# \n#F40#[Paralysis]: A control effect that disables the use of special skills. \n[Freeze]: A control effect that prevents movement and is released after taking damage exceeding 15% of the target\'s max HP. \n[Burn]: A negative effect causing the target to receive 150% of Amakusa Shirou Tokisada\'s true physical defense damage before each action.',
		simDesc_vn = 'Amakusa Hiro Tokisada lao về phía mục tiêu từ trên không và giải phóng vòng tròn ma thuật của Thập Sát trận đáng ngại, gây ra ba hiệu ứng: tê liệt, thiêu đốt và đóng băng.',
		simDesc_en = 'Amakusa Hiro Tokisada lunged at the target from above and unleashed the formidable Ten Satsu magic circle, causing three effects: paralysis, burning, and freezing.',
		simDesc_th = 'อามาคุสะ ฮิโระ โทคิซาดะ พุ่งเข้าหาศัตรูจากด้านบนและปลดปล่อยวงเวทมนตร์อันน่ากลัวของเท็นซัตสึ สร้างผลกระทบสามอย่าง: ทำให้เป็นอัมพาต, เผาไหม้ และแช่แข็ง',
		simDesc_in = 'Amakusa Hiro Tokisada meluncur ke arah target dari atas dan melepaskan lingkaran sihir Ten Satsu yang menakutkan, menyebabkan tiga efek: kelumpuhan, pembakaran, dan pembekuan.',
		simDesc_ph = 'Si Amakusa Hiro Tokisada ayun sa target mula sa itaas at inilabas ang nakakatakot na magic circle ng Ten Satsu, na nagdudulot ng tatlong epekto: paralisis, pagkasunog, at pagyeyelo.',
		simDesc_ma = 'Amakusa Hiro Tokisada meluru ke sasaran dari atas dan melepaskan bulatan sihir Ten Satsu yang menggerunkan, menyebabkan tiga kesan: lumpuh, terbakar, dan pembekuan.',
