	[10822] = {
		id = 10822,
		skillName_vn = 'Quét ngang nghìn quân',
		skillName_en = 'Sweep across thousands of troops',
		skillName_th = 'กวาดล้างกองทัพนับพัน',
		skillName_in = 'Sapu ribuan pasukan',
		skillName_ph = 'Hugas sa libong hukbo',
		skillName_ma = 'Pusaran ribuan tentera',
		skillName = 'Sweep across thousands of troops',
		describe_vn = 'Marja tích lực thực hiện chiêu quét ngang tấn công mục tiêu hàng trước của kẻ địch, gây ra #C0xE69900#90% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Sát Thương Vật Lý#C0xF13B54#, đồng thời vĩnh viễn cướp 8% Công Vật Lý của hai mục tiêu ngẫu nhiên ở hàng trước và thêm vào bản thân (thuộc tính cướp được có thể cộng dồn, không thể xóa bỏ)',
		describe_en = 'Marja charges up and executes a sweeping attack on the enemy\'s front row targets, dealing #C0xE69900#90% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0xF13B54#, while permanently stealing 8% Physical Attack from two random targets in the front row and adding it to herself (the stolen attribute can stack and cannot be removed).',
		describe_th = 'มาร์จาทำการชาร์จพลังและโจมตีสไลด์ไปยังเป้าหมายแถวหน้าของศัตรู สร้างความเสียหาย #C0xE69900#90% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0xF13B54# พร้อมทั้งขโมยพลังโจมตีทางกายภาพ 8% จากเป้าหมายสองตัวแบบสุ่มในแถวหน้าอย่างถาวรและเพิ่มลงในตัวเอง (คุณสมบัติที่ถูกขโมยสามารถทับซ้อนได้และไม่สามารถลบออกได้).',
		describe_in = 'Marja mengumpulkan tenaga dan melakukan serangan sapuan pada target di barisan depan musuh, memberikan #C0xE69900#90% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerusakan Fisik#C0xF13B54#, sekaligus secara permanen mencuri 8% Serangan Fisik dari dua target acak di barisan depan dan menambahkannya ke dirinya sendiri (atribut yang dicuri bisa bertumpuk dan tidak bisa dihapus).',
		describe_ph = 'Nag-ipon si Marja ng lakas at nagsagawa ng paikot na atake sa mga target sa harapang hanay ng kalaban, na nagdudulot ng #C0xE69900#90% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0xF13B54#, kasabay ng permanenteng pagnanakaw ng 8% Physical Attack mula sa dalawang random na target sa harapang hanay at idinadagdag ito sa kanyang sarili (ang ninakaw na attribute ay maaaring mag-stack at hindi maaaring alisin).',
		describe_ma = 'Marja mengumpul tenaga dan melaksanakan serangan sapuan ke sasaran barisan hadapan musuh, menyebabkan #C0xE69900#90% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerosakan Fizikal#C0xF13B54#, serta kekal mencuri 8% Serangan Fizikal dari dua sasaran rawak di barisan hadapan dan menambahkannya pada dirinya sendiri (ciri yang dicuri boleh bertindih dan tidak boleh dipadam).',
		describe = 'Marja charges up and executes a sweeping attack on the enemy\'s front row targets, dealing #C0xE69900#90% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0xF13B54#, while permanently stealing 8% Physical Attack from two random targets in the front row and adding it to herself (the stolen attribute can stack and cannot be removed).',
		simDesc_vn = 'Maja tích tụ sức mạnh và thực hiện "Quét Sạch" tấn công mục tiêu hàng đầu của đối phương.',
		simDesc_en = 'Maja gathers strength and performs "Clean Sweep" to attack the enemy\'s top target.',
		simDesc_th = 'มาญ่าสะสมพลังและใช้ท่า "กวาดล้าง" โจมตีเป้าหมายอันดับหนึ่งของศัตรู',
		simDesc_in = 'Maja mengumpulkan kekuatan dan melakukan "Bersih Total" untuk menyerang target utama musuh.',
		simDesc_ph = 'Nag-ipon si Maja ng lakas at nagsagawa ng "Malinis na Paglipat" upang atakihin ang nangungunang target ng kalaban.',
		simDesc_ma = 'Maja mengumpul tenaga dan melakukan "Sapuan Bersih" untuk menyerang sasaran utama musuh.',
		simDesc = 'Maja gathers strength and performs "Clean Sweep" to attack the enemy\'s top target.',
		zawakeEffect = __data_t__zawakeEffect[10822],
		-- {79002}
		zawakeEffectDesc = 'Magar charges to perform a horizontal sweep attack on the front row enemies, dealing 90% Physical Damage +$(skillLevel*4*48)$ Physical Attack, permanently stealing 8% Physical Attack and 16% Physical Defense of two random front row targets and adding them to himself (can be stacked, cannot be dispelled)',
		zawakeEffectDesc_en = 'Magar charges to perform a horizontal sweep attack on the front row enemies, dealing 90% Physical Damage +$(skillLevel*4*48)$ Physical Attack, permanently stealing 8% Physical Attack and 16% Physical Defense of two random front row targets and adding them to himself (can be stacked, cannot be dispelled)',
		zawakeEffectDesc_th = 'มะการ์พุ่งตัวเพื่อโจมตีแบบกวาดแนวนอนใส่ศัตรูในแถวหน้า สร้างความเสียหายทางกายภาพ 90% +$(skillLevel*4*48)$ การโจมตีทางกายภาพ ขโมยค่าการโจมตีทางกายภาพ 8% และการป้องกันทางกายภาพ 16% ของเป้าหมายแถวหน้าสองตัวแบบสุ่มอย่างถาวรและเพิ่มให้ตัวเอง (สามารถสะสมได้ ไม่สามารถลบล้างได้)',
		zawakeEffectDesc_in = 'Magar melakukan serangan sapuan horizontal pada musuh barisan depan, memberikan 90% Kerusakan Fisik +$(skillLevel*4*48)$ Serangan Fisik, secara permanen mencuri 8% Serangan Fisik dan 16% Pertahanan Fisik dari dua target acak di barisan depan dan menambahkannya ke dirinya sendiri (dapat ditumpuk, tidak dapat dihapus)',
		zawakeEffectDesc_ph = 'Magar ay nagsasagawa ng pabilog na atake laban sa mga kalaban sa unahang hanay, nagdudulot ng 90% Pisikal na Pinsala +$(skillLevel*4*48)$ Pisikal na Atake, permanenteng nagnanakaw ng 8% Pisikal na Atake at 16% Pisikal na Depensa mula sa dalawang random na target sa unahang hanay at dinadagdag ito sa kanyang sarili (maaring maipon, hindi maaaring alisin)',
		zawakeEffectDesc_ma = 'Magar melaksanakan serangan sapuan mendatar ke musuh barisan hadapan, menyebabkan 90% Kerosakan Fizikal +$(skillLevel*4*48)$ Serangan Fizikal, secara kekal mencuri 8% Serangan Fizikal dan 16% Pertahanan Fizikal daripada dua sasaran rawak barisan hadapan dan menambahkannya kepada dirinya sendiri (boleh bertindih, tidak boleh dihapuskan)',
		zawakeEffectDesc_vn = 'Magar tích lực thực hiện tấn công quét ngang kẻ địch hàng trước, gây Sát Thương Vật Lý 90% Công Vật Lý +$(skillLevel*4*48)$, vĩnh viễn cướp 8% Công Vật Lý và 16% phòng vật lý của hai mục tiêu ngẫu nhiên hàng trước thêm vào bản thân (có thể cộng dồn, không thể xua tan)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Permanently steal 8% Physical ATK from two random front-row targets and add to self\n#F20# \n#F40##C0x5c9970#→Permanently steal 8% Physical ATK and 16% Physical DEF from two random front-row targets and add to self',
		zawakeSimpleDesc_en = 'Permanently steal 8% Physical ATK from two random front-row targets and add to self\n#F20# \n#F40##C0x5c9970#→Permanently steal 8% Physical ATK and 16% Physical DEF from two random front-row targets and add to self',
		zawakeSimpleDesc_th = 'ขโมยพลังโจมตีกายภาพ 8% อย่างถาวรจากศัตรูแถวหน้าแบบสุ่ม 2 ตัวและเพิ่มให้ตัวเอง\n#F20# \n#F40##C0x5c9970#→ขโมยพลังโจมตีกายภาพ 8% และพลังป้องกันกายภาพ 16% อย่างถาวรจากศัตรูแถวหน้าแบบสุ่ม 2 ตัวและเพิ่มให้ตัวเอง',
		zawakeSimpleDesc_in = 'Mencuri 8% ATK Fisik secara permanen dari dua target acak di baris depan dan menambahkannya ke diri sendiri\n#F20# \n#F40##C0x5c9970#→Mencuri 8% ATK Fisik dan 16% DEF Fisik secara permanen dari dua target acak di baris depan dan menambahkannya ke diri sendiri',
		zawakeSimpleDesc_ph = 'Permanently nakawin ang 8% Physical ATK mula sa dalawang random na kalaban sa front row at idagdag sa sarili\n#F20# \n#F40##C0x5c9970#→Permanently nakawin ang 8% Physical ATK at 16% Physical DEF mula sa dalawang random na kalaban sa front row at idagdag sa sarili',
