		skillName_ph = 'Kaya huli',
		skillName_ma = 'Jadi tangkap',
		skillName = 'So capture',
		describe_vn = 'Hắc Lujia triệu hồi Hắc Lujia tấn công toàn bộ mục tiêu kẻ địch, gây #C0x3D8A99#130% Phép Công#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, cướp 20% phòng thủ kép của toàn bộ mục tiêu kẻ địch, chia đều tổng lượng phòng thủ kép cướp được theo tỷ lệ 1:2 để tăng công kép cho toàn bộ phe ta, kéo dài 2 lượt; tăng 20% tỷ lệ hút máu cho anh hùng hệ bóng tối phe ta, kéo dài 2 lượt',
		describe_en = 'Black Lujia summons Black Lujia to attack all enemy targets, dealing #C0x3D8A99#130% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, stealing 20% double defense from all enemy targets, distributing the total stolen double defense in a 1:2 ratio to increase double attack for all allies, lasting 2 turns; increases 20% lifesteal rate for our dark heroes, lasting 2 turns.',
		describe_th = 'แบล็กลูเจีย เรียกแบล็กลูเจียโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหาย #C0x3D8A99#130% พลังเวท#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายเวท #C0x5B545B# ขโมยมง 20% เกราะคู่ของเป้าหมายศัตรูทั้งหมด แบ่งเกราะคู่ที่ขโมยได้เป็นอัตราส่วน 1:2 เพื่อเพิ่มพลังโจมตีคู่ให้กับพันธมิตรทั้งหมด เป็นเวลา 2 เทิร์น; เพิ่มอัตราดูดเลือด 20% ให้กับฮีโร่ระบบความมืดในฝ่ายเรา เป็นเวลา 2 เทิร์น',
		describe_in = 'Black Lujia memanggil Black Lujia untuk menyerang semua target musuh, memberikan #C0x3D8A99#130% Serangan Magic#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Magic #C0x5B545B#, mencuri 20% pertahanan ganda dari semua target musuh, membagi total pertahanan ganda yang dicuri dengan rasio 1:2 untuk meningkatkan serangan ganda seluruh sekutu, berlangsung selama 2 giliran; meningkatkan 20% tingkat pencurian darah untuk pahlawan kegelapan kita, berlangsung selama 2 giliran.',
		describe_ph = 'Black Lujia ay nagmumula Black Lujia upang atakihin ang lahat ng kaaway, nagdudulot ng #C0x3D8A99#130% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, nagnanakaw ng 20% dobleng depensa mula sa lahat ng kaaway, hinahati ang kabuuang ninakaw na dobleng depensa sa ratio na 1:2 upang mapataas ang dobleng atake para sa lahat ng kasamahan, tumatagal ng 2 liko; nagpapataas ng 20% lifesteal rate para sa aming mga dark heroes, tumatagal ng 2 liko.',
		describe_ma = 'Black Lujia memanggil Black Lujia untuk menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#130% Serangan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, mencuri 20% pertahanan berganda dari semua sasaran musuh, membahagikan jumlah pertahanan berganda yang dicuri mengikut nisbah 1:2 untuk meningkatkan serangan berganda kepada semua sekutu, berlangsung selama 2 giliran; meningkatkan 20% kadar serapan darah untuk wira sistem gelap kami, berlangsung selama 2 giliran.',
		describe = 'Black Lujia summons Black Lujia to attack all enemy targets, dealing #C0x3D8A99#130% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, stealing 20% double defense from all enemy targets, distributing the total stolen double defense in a 1:2 ratio to increase double attack for all allies, lasting 2 turns; increases 20% lifesteal rate for our dark heroes, lasting 2 turns.',
		simDesc_vn = 'Houndoom triệu hồi bầy Houndoom tấn công toàn bộ mục tiêu của đối phương, đánh cắp phòng thủ của mục tiêu và tăng tỷ lệ hút máu cho các anh hùng thuộc hệ Bóng Tối của mình.',
		simDesc_en = 'Houndoom summons a pack of Houndooms to attack all enemy targets, stealing their defense and increasing lifesteal rate for heroes of its Dark faction.',
		simDesc_th = 'ฮาวนด์ดุม เรียกฝูงฮาวนด์ดุมโจมตีเป้าหมายฝ่ายตรงข้ามทั้งหมด ขโมยการป้องกันของเป้าหมาย และเพิ่มอัตราการดูดเลือดให้กับฮีโร่ในฝ่ายเงาของมัน',
		simDesc_in = 'Houndoom memanggil kawanan Houndoom untuk menyerang semua target musuh, mencuri pertahanan target, dan meningkatkan tingkat lifesteal untuk pahlawan dari faksi Gelapnya.',
		simDesc_ph = 'Ang Houndoom ay sumasagupa ng isang kawan ng mga Houndoom upang atakihin ang lahat ng kalaban, ninanakaw ang depensa ng mga target, at pinapataas ang lifesteal rate para sa mga bayani ng Kanyang Dark faction.',
		simDesc_ma = 'Houndoom memanggil sekumpulan Houndoom untuk menyerang semua sasaran musuh, mencuri pertahanan sasaran dan meningkatkan kadar sedutan darah untuk wira-wira dalam kumpulan Gelapnya.',
		simDesc = 'Houndoom summons a pack of Houndooms to attack all enemy targets, stealing their defense and increasing lifesteal rate for heroes of its Dark faction.',
		starEffect = __data_t__starEffect[11723],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Tăng cường khả năng cướp 30% phòng thủ đôi của kẻ thù ở hàng trước.',
		starEffectDesc = 'Additional effect: Increases the ability to steal 30% of the front row enemy\'s double defense.',
		starEffectDesc_en = 'Additional effect: Increases the ability to steal 30% of the front row enemy\'s double defense.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เพิ่มความสามารถในการขโมย 30% ของการป้องกันคู่ของศัตรูแถวหน้า',
		starEffectDesc_in = 'Efek tambahan: Meningkatkan kemampuan mencuri 30% pertahanan ganda musuh di barisan depan.',
