	[11733] = {
		id = 11733,
		skillName_vn = 'Hỏa Sát Hắc Long Ba',
		skillName_en = 'Fire Death Black Dragon Eight',
		skillName_th = 'ไฟตายมังกรดำแปด',
		skillName_in = 'Naga Hitam Kematian Api Delapan',
		skillName_ph = 'Apat na Itim na Dragon ng Apoy Mamatay',
		skillName_ma = 'Naga Hitam Kematian Api Lapan',
		skillName = 'Fire Death Black Dragon Eight',
		describe_vn = 'Bóng Bay tấn công từ địa ngục tối tăm, triệu hồi làn sóng rồng đen sát lửa tấn công tất cả mục tiêu địch, gây #C0x3D8A99#280% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, đồng thời đánh cắp 20% phòng thủ kép của tất cả mục tiêu địch. Theo Tổng số phòng thủ kép bị đánh cắp được chia đều cho phần thưởng tấn công kép của tất cả đồng minh theo tỷ lệ 1:2, kéo dài trong 2 hiệp; tăng tỷ lệ hút máu của các anh hùng chiến đấu của bản thân thêm 30%, kéo dài trong 2 hiệp, cho phép tất cả đồng minh nhận được [Sức mạnh của Mặt trời] trong 2 hiệp (hiệu ứng đặc biệt, thay thế sức mạnh của ngọn lửa tà ác, tăng sát thương cộng thêm thêm 30%, mất 10% sinh lực hiện tại trước mỗi hiệp, tăng vĩnh viễn sát thương cộng thêm thêm 24%)',
		describe_en = 'Shadow Balloon attacks from the dark abyss, summoning a wave of black flame dragons to strike all enemy targets, dealing #C0x3D8A99#280% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B#, while stealing 20% dual defense from all enemy targets. The total stolen dual defense is evenly distributed as dual attack rewards among all allies at a ratio of 1:2, lasting 2 turns; increases lifesteal rate of own combat heroes by 30%, lasting 2 turns; allows all allies to gain [Power of the Sun] for 2 turns (special effect, replaces the power of evil flame, increases additional damage by 30%, loses 10% current HP before each turn, permanently increases additional damage by 24%).',
		describe_th = 'ลูกโป่งเงาโจมตีจากนรกมืด ดึงดูดคลื่นมังกรไฟดำโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายทางกายภาพ #C0x3D8A99#280% +$(skillLevel*4*90)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# พร้อมกับขโมยการป้องกันคู่ 20% จากเป้าหมายศัตรูทั้งหมด รวมการป้องกันคู่ที่ถูกขโมยและแจกจ่ายเป็นรางวัลการโจมตีคู่ให้กับพันธมิตรทั้งหมดในอัตรา 1:2 เป็นเวลา 2 เทิร์น; เพิ่มอัตราการดูดเลือดของฮีโร่ต่อสู้ของตัวเอง 30% โดยมีผล 2 เทิร์น; ให้พันธมิตรทั้งหมดได้รับ [พลังแห่งดวงอาทิตย์] เป็นเวลา 2 เทิร์น (เอฟเฟกต์พิเศษ แทนที่พลังแห่งไฟชั่วร้าย เพิ่มความเสียหายพิเศษ 30%, สูญเสียครึ่งชีพปัจจุบัน 10% ก่อนแต่ละเทิร์น, เพิ่มความเสียหายพิเศษถาวร 24%)',
		describe_in = 'Balon Bayangan menyerang dari neraka gelap, memanggil gelombang naga api hitam yang menyerang semua target musuh, memberikan #C0x3D8A99#280% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, sekaligus mencuri 20% pertahanan ganda dari semua target musuh. Total pertahanan ganda yang dicuri dibagikan merata sebagai hadiah serangan ganda kepada semua sekutu dengan rasio 1:2, berlangsung selama 2 giliran; meningkatkan tingkat pencurian darah pahlawan tempur sendiri sebesar 30%, berlangsung selama 2 giliran; memungkinkan semua sekutu menerima [Kekuatan Matahari] selama 2 giliran (efek khusus, menggantikan kekuatan api jahat, meningkatkan kerusakan tambahan sebesar 30%, kehilangan 10% HP saat ini sebelum setiap giliran, menambah kerusakan tambahan permanen sebesar 24%).',
		describe_ph = 'Ang Balon ng Anino ay umatake mula sa madilim na impiyerno, tumatawag ng alon ng itim na apoy na dragons upang atakihin ang lahat ng kalaban, nagdudulot ng #C0x3D8A99#280% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#, kasabay ng pagnanakaw ng 20% doble depensa mula sa lahat ng kalabang target. Ang kabuuang na-nakaw na doble depensa ay pantay na ipinamahagi bilang gantimpala ng doble atake sa lahat ng kakampi sa ratio ng 1:2, tumatagal ng 2 turn; pinapataas ang lifesteal rate ng sariling mga bayani sa laban ng 30%, tumatagal ng 2 turn; pinapayagan ang lahat ng kakampi na makatanggap ng [Lakas ng Araw] sa loob ng 2 turn (espesyal na epekto, pumapalit sa kapangyarihan ng masamang apoy, tumataas ang karagdagang pinsala ng 30%, nawawala ang 10% ng kasalukuyang HP bago ang bawat termino, pati na rin permanenteng tumataas ang karagdagang pinsala ng 24%).',
		describe_ma = 'Belon Bayangan menyerang dari neraka gelap, memanggil gelombang naga api hitam yang menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#280% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, serta mencuri 20% pertahanan berganda dari semua sasaran musuh. Jumlah pertahanan berganda yang dicuri dibahagikan sama rata sebagai ganjaran serangan berganda kepada semua sekutu dengan nisbah 1:2, berlangsung selama 2 pusingan; meningkatkan kadar sedutan darah wira pertempuran sendiri sebanyak 30%, berlangsung selama 2 pusingan; membolehkan semua sekutu menerima [Kuasa Matahari] selama 2 pusingan (kesan khas, menggantikan kuasa api jahat, meningkatkan kerosakan tambahan sebanyak 30%, hilang 10% HP semasa sebelum setiap pusingan, meningkatkan kerosakan tambahan secara kekal sebanyak 24%).',
		describe = 'Shadow Balloon attacks from the dark abyss, summoning a wave of black flame dragons to strike all enemy targets, dealing #C0x3D8A99#280% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B#, while stealing 20% dual defense from all enemy targets. The total stolen dual defense is evenly distributed as dual attack rewards among all allies at a ratio of 1:2, lasting 2 turns; increases lifesteal rate of own combat heroes by 30%, lasting 2 turns; allows all allies to gain [Power of the Sun] for 2 turns (special effect, replaces the power of evil flame, increases additional damage by 30%, loses 10% current HP before each turn, permanently increases additional damage by 24%).',
		simDesc_vn = 'Fei Ying tấn công từ địa ngục bóng tối, triệu tập một làn sóng rồng đen diệt lửa để tấn công tất cả các mục tiêu của kẻ thù, đánh cắp khả năng phòng thủ kép của tất cả các mục tiêu của kẻ thù và phân phối nó cho toàn bộ nhóm của mình.',
		simDesc_en = 'Fei Ying attacks from the dark hell, summoning a wave of fire-extinguishing black dragons to strike all enemy targets, stealing the dual defense abilities of all enemy targets and distributing them to the entire team.',
		simDesc_th = 'เฟย หยิง โจมตีจากนรกมืด เรียกคลื่นมังกรดำดับไฟเพื่อโจมตีเป้าหมายศัตรูทั้งหมด ขโมยความสามารถป้องกันคู่ของเป้าหมายศัตรูทั้งหมดและแจกจ่ายให้กับทีมทั้งหมดของเขา',
		simDesc_in = 'Fei Ying menyerang dari neraka gelap, memanggil gelombang naga hitam pemadam api untuk menyerang semua target musuh, mencuri kemampuan pertahanan ganda dari semua target musuh dan mendistribusikannya ke seluruh timnya.',
		simDesc_ph = 'Si Fei Ying ay pumapasok mula sa madilim na impiyerno, tinatawag ang alon ng mga itim na dragon na pumapatay ng apoy upang atakihin ang lahat ng mga kalaban na target, ninanakaw ang kakayahan ng dobleng depensa ng lahat ng mga kalaban na target at ipinapamahagi ito sa buong koponan niya.',
		simDesc_ma = 'Fei Ying menyerang dari neraka gelap, memanggil gelombang naga hitam memadamkan api untuk menyerang semua sasaran musuh, mencuri kemampuan pertahanan berganda semua sasaran musuh dan mengedarkannya kepada seluruh pasukannya.',
		simDesc = 'Fei Ying attacks from the dark hell, summoning a wave of fire-extinguishing black dragons to strike all enemy targets, stealing the dual defense abilities of all enemy targets and distributing them to the entire team.',
