	[11736] = {
		id = 11736,
		skillName_vn = 'Luyện Ngục Tà Vương',
		skillName_en = 'Training Devil King',
		skillName_th = 'ฝึกฝนกษัตริย์ปีศาจ',
		skillName_in = 'Latihan Raja Setan',
		skillName_ph = 'Pagsasanay sa Hari ng Demonyo',
		skillName_ma = 'Latihan Raja Syaitan',
		skillName = 'Training Devil King',
		describe_vn = 'Trong trận chiến, trước khi bắt đầu mỗi hiệp lớn, tổng đòn Sát Thương Vật Lý từ Feiying #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# sẽ tăng lên trong 1 hiệp (không thể xua tan) và sẽ được phân bổ đều cho từng mục tiêu của bạn và số lượng sẽ bằng với thời gian chết. Kích hoạt hiệu ứng này một lần từ bên ngoài\n#F10#\n#F40##L10#Power of Evil Flame: #L0# Mất 6% sinh lực hiện tại trước mỗi vòng, tăng vĩnh viễn sát thương cộng thêm thêm 12% (tối đa 8 lớp). Khi chết, trả lại gấp 4 lần số mạng mà tất cả đồng minh đã mất do sức mạnh của ngọn lửa tà ác và sức mạnh của mặt trời rực rỡ và chia đều cho bạn bè.',
		describe_en = 'In battle, before the start of each major round, the total Physical Damage from Feiying #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# will increase within one round (cannot be dispelled) and will be evenly distributed among your targets, with the amount equal to downtime. Activate this effect once externally \n#F10#\n#F40##L10#Power of Evil Flame: #L0# Lose 6% of current HP each round, permanently increases additional damage by 12% (up to 8 stacks). Upon death, return 4 times the number of lives all allies lost due to the power of the evil flame and the power of the radiant sun, distributed evenly to your friends.',
		describe_th = 'ในศึกก่อนเริ่มแต่ละรอบใหญ่ ความเสียหายทางกายภาพรวมจาก Feiying #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# จะเพิ่มขึ้นในหนึ่งรอบ (ไม่สามารถลบได้) และจะแบ่งเท่าๆ กันไปยังเป้าหมายของคุณ โดยจำนวนจะเท่ากับเวลาที่หยุดพัก เปิดใช้งานเอฟเฟกต์นี้ครั้งเดียวจากภายนอก \n#F10#\n#F40##L10#พลังของเปลวไฟชั่วร้าย: #L0# สูญเสีย 6% ของพลังชีวิตปัจจุบันในแต่ละรอบ เพิ่มความเสียหายเพิ่มเติมถาวร 12% (สูงสุด 8 ชั้น) เมื่อเสียชีวิต จะคืนค่าชีวิตให้เพื่อน ๆ เท่ากับ 4 เท่าของจำนวนชีวิตที่เพื่อนร่วมทีมทั้งหมดสูญเสียจากพลังของเปลวไฟชั่วร้ายและพลังของดวงอาทิตย์เจิดจ้า',
		describe_in = 'Dalam pertempuran, sebelum dimulainya setiap ronde besar, total Kerusakan Fisik dari Feiying #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# akan meningkat dalam satu ronde (tidak dapat dihapus) dan akan dibagikan merata ke setiap target Anda dengan jumlah yang sama dengan waktu mati. Aktifkan efek ini sekali dari luar \n#F10#\n#F40##L10#Kekuatan Api Jahat: #L0# Kehilangan 6% HP saat ini setiap ronde, secara permanen meningkatkan tambahan kerusakan sebesar 12% (maksimal 8 lapis). Saat mati, kembalikan 4 kali lipat jumlah nyawa yang hilang oleh semua sekutu akibat kekuatan api jahat dan kekuatan matahari yang bersinar, dibagi rata kepada teman-teman Anda.',
		describe_ph = 'Sa labanan, bago magsimula ang bawat malaking yugto, ang kabuuang Pisikal na Pinsala mula kay Feiying #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# ay tataas sa loob ng isang yugto (hindi maaaring mawala) at ipamamahagi nang pantay-pantay sa bawat target mo, na may dami katumbas ng downtime. Isa lang beses ma-activate ang epekto mula sa labas \n#F10#\n#F40##L10#Kapangyarihan ng Masamang Apoy: #L0# Mawawala ang 6% ng kasalukuyang HP bago ang bawat round, permanenteng pinapataas ang dagdag na pinsala ng 12% (hanggang 8 na stack). Sa pagkamatay, ibalik nang apat na beses ang bilang ng buhay na nawala ng lahat ng kakampi dahil sa kapangyarihan ng masamang apoy at kapangyarihan ng nagniningning na araw at pantay-pantay na ipamamahagi sa mga kaibigan mo.',
		describe_ma = 'Dalam pertempuran, sebelum permulaan setiap pusingan besar, jumlah Kerosakan Fizikal daripada Feiying #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# akan meningkat dalam satu pusingan (tidak boleh dibersihkan) dan akan diagihkan secara rata kepada setiap sasaran anda dengan jumlah yang sama dengan masa mati. Aktifkan kesan ini sekali dari luar \n#F10#\n#F40##L10#Kuasa Api Jahat: #L0# Hilang 6% HP semasa setiap pusingan, kekal meningkatkan kerosakan tambahan sebanyak 12% (maksimum 8 lapisan). Apabila mati, kembalikan 4 kali ganda jumlah nyawa yang telah hilang oleh semua sekutu akibat kuasa api jahat dan kuasa matahari yang bersinar, diagihkan secara rata kepada rakan-rakan anda.',
		describe = 'In battle, before the start of each major round, the total Physical Damage from Feiying #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# will increase within one round (cannot be dispelled) and will be evenly distributed among your targets, with the amount equal to downtime. Activate this effect once externally \n#F10#\n#F40##L10#Power of Evil Flame: #L0# Lose 6% of current HP each round, permanently increases additional damage by 12% (up to 8 stacks). Upon death, return 4 times the number of lives all allies lost due to the power of the evil flame and the power of the radiant sun, distributed evenly to your friends.',
		starEffect = __data_t__starEffect[11736],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng thêm: Kỹ năng hào quang: Tăng 8% hút máu cho các tướng hệ Đấu Sĩ và hệ Lửa phe ta, tăng gấp đôi khi tỷ lệ máu dưới 30%.',
		starEffectDesc = 'Additional effect: Aura skill: Increases lifesteal by 8% for our Fighter and Fire-aligned heroes, doubled when health is below 30%.',
		starEffectDesc_en = 'Additional effect: Aura skill: Increases lifesteal by 8% for our Fighter and Fire-aligned heroes, doubled when health is below 30%.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ทักษะออร่า: เพิ่มการดูดเลือด 8% สำหรับฮีโร่ระบบนักสู้และระบบไฟฝ่ายเรา เพิ่มเป็นสองเท่าเมื่อพลังชีวิตต่ำกว่า 30%',
		starEffectDesc_in = 'Efek tambahan: Skill aura: Meningkatkan lifesteal sebesar 8% untuk pahlawan sistem Fighter dan Fire di pihak kita, berlipat ganda saat HP di bawah 30%.',
		starEffectDesc_ph = 'Karagdagang epekto: Kakayahang aura: Nagdaragdag ng 8% lifesteal para sa aming mga bayani na nasa sistem ng Fighter at Fire, doble kapag ang HP ay mababa sa 30%.',
		starEffectDesc_ma = 'Kesan tambahan: Kemahiran aura: Meningkatkan penghisapan darah sebanyak 8% untuk wira sistem Fighter dan Fire di pihak kita, berganda apabila HP di bawah 30%.',
		zawakeEffect = __data_t__zawakeEffect[11736],
		-- {79004}
		zawakeEffectDesc = 'In battle, before the start of each main round, the total special attack from Super Black Luga #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# will be increased once per match (cannot be dispelled) and will be evenly distributed among your targets. This effect will trigger once more after death. Distribute 100% of your double attacks to remaining allies in 2 rounds\n#F10#\n#F40##L10#Power of Evil Flame: #L0# Lose 6% current HP before each round, permanently increase bonus damage by 12% (max 8 levels). Upon death, return 4 times the lost lives of all allies due to the power of the evil flame and the power of the blazing sun and evenly share among allies.',
		zawakeEffectDesc_en = 'In battle, before the start of each main round, the total special attack from Super Black Luga #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# will be increased once per match (cannot be dispelled) and will be evenly distributed among your targets. This effect will trigger once more after death. Distribute 100% of your double attacks to remaining allies in 2 rounds\n#F10#\n#F40##L10#Power of Evil Flame: #L0# Lose 6% current HP before each round, permanently increase bonus damage by 12% (max 8 levels). Upon death, return 4 times the lost lives of all allies due to the power of the evil flame and the power of the blazing sun and evenly share among allies.',
		zawakeEffectDesc_th = 'ในการต่อสู้ ก่อนเริ่มรอบหลักแต่ละรอบ ค่าโจมตีพิเศษทั้งหมดจาก Super Black Luga #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# จะเพิ่มขึ้นในหนึ่งแมตช์ (ไม่สามารถลบออกได้) และจะแบ่งเท่าๆ กันให้กับเป้าหมายของคุณ เอฟเฟกต์นี้จะถูกเปิดใช้งานอีกครั้งหลังจากตาย แจกจ่ายการโจมตีคู่ 100% ของคุณให้กับพันธมิตรที่เหลือใน 2 รอบ\n#F10#\n#F40##L10#พลังแห่งเปลวไฟชั่วร้าย: #L0# สูญเสียพลังชีวิตปัจจุบัน 6% ก่อนแต่ละรอบ เพิ่มโบนัสความเสียหายถาวร 12% (สูงสุด 8 ระดับ) เมื่อเสียชีวิต คืนค่าชีวิตที่สูญเสียของพันธมิตรทั้งหมดเป็น 4 เท่าโดยพลังแห่งเปลวไฟชั่วร้ายและพลังของดวงอาทิตย์ที่ร้อนแรง และแบ่งเท่าๆ กันให้กับพันธมิตร',
		zawakeEffectDesc_in = 'Dalam pertarungan, sebelum memulai setiap babak utama, total serangan khusus dari Super Black Luga #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# akan ditingkatkan sekali per pertandingan (tidak bisa dihapus) dan akan dibagikan merata kepada target Anda. Efek ini akan aktif sekali lagi setelah mati. Distribusikan 100% serangan ganda Anda ke sekutu yang tersisa dalam 2 putaran\n#F10#\n#F40##L10#Kekuatan Api Jahat: #L0# Kehilangan 6% HP saat ini sebelum setiap putaran, secara permanen meningkatkan bonus kerusakan sebesar 12% (maks 8 level). Saat mati, kembalikan 4 kali nyawa yang hilang dari semua sekutu karena kekuatan api jahat dan kekuatan matahari yang menyala dan bagikan secara merata kepada sekutu.',
		zawakeEffectDesc_ph = 'Sa laban, bago magsimula ang bawat pangunahing round, ang kabuuang special attack mula sa Super Black Luga #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# ay tataas sa isang laban (hindi maaaring alisin) at pantay na ipapamahagi sa bawat target mo. Magti-trigger muli ang effect na ito pagkatapos mamatay. Ibahagi ang 100% ng iyong double attacks sa natitirang mga kakampi sa loob ng 2 rounds\n#F10#\n#F40##L10#Power of Evil Flame: #L0# Mawalan ng 6% current HP bago ang bawat round, permanenteng nadadagdagan ng 12% ang bonus damage (max 8 levels). Pag namatay, ibalik ang 4 na beses na nawalang buhay ng lahat ng kakampi dahil sa kapangyarihan ng masamang apoy at kapangyarihan ng naglalagablab na araw at pantay-pantay na ipamahagi sa mga kakampi.',
		zawakeEffectDesc_ma = 'Dalam pertempuran, sebelum memulakan setiap pusingan utama, jumlah serangan khas dari Super Black Luga #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# akan ditingkatkan sekali setiap perlawanan (tidak boleh dibuang) dan akan diagihkan secara sama rata kepada sasaran anda. Kesan ini akan diaktifkan sekali lagi selepas mati. Edarkan 100% serangan berganda anda kepada sekutu yang tinggal dalam 2 pusingan\n#F10#\n#F40##L10#Kuasa Api Jahat: #L0# Kehilangan 6% HP semasa sebelum setiap pusingan, meningkatkan kerosakan bonus secara kekal sebanyak 12% (maksimum 8 tahap). Sewaktu mati, pulangkan 4 kali kehilangan nyawa semua sekutu disebabkan oleh kuasa api jahat dan kuasa matahari menyala dan edarkan secara sama rata kepada sekutu.',
		zawakeEffectDesc_vn = 'Trong trận chiến, trước khi bắt đầu mỗi vòng chính, tổng các đòn tấn công đặc biệt từ Super Black Luga #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# sẽ được tăng lên trong 1 hiệp (không thể xua tan) và sẽ được phân bổ đều cho từng mục tiêu của bạn. Hiệu ứng này sẽ được kích hoạt thêm một lần nữa sau khi chết. Trải 100% đòn tấn công kép của bản thân cho các đồng minh còn lại trong 2 hiệp\n#F10#\n#F40##L10#Power of Evil Flame: #L0# Mất 6% sinh lực hiện tại trước mỗi hiệp, tăng vĩnh viễn sát thương cộng thêm thêm 12% (tối đa 8 cấp). Khi chết, trả lại gấp 4 lần số mạng bị mất của tất cả đồng minh do sức mạnh của ngọn lửa tà ác và sức mạnh của mặt trời rực rỡ và chia đều cho các đồng minh.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Upon death, additionally triggers this effect and evenly distributes 100% of own double ATK to remaining teammates, lasts for 2 turns',
		zawakeSimpleDesc_en = 'Upon death, additionally triggers this effect and evenly distributes 100% of own double ATK to remaining teammates, lasts for 2 turns',
		zawakeSimpleDesc_th = 'เมื่อเสียชีวิต จะกระตุ้นเอฟเฟกต์นี้อีกครั้ง และแบ่ง 100% พลังโจมตีคู่ของตัวเองให้กับเพื่อนร่วมทีมที่เหลือ เป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Saat mati, memicu efek ini sekali lagi dan membagikan 100% ATK ganda milik sendiri ke rekan tim yang tersisa, berlangsung 2 giliran',
		zawakeSimpleDesc_ph = 'Kapag namatay, awtomatikong pinapagana ulit ang epektong ito at ibinabahagi ang 100% ng sariling double ATK sa mga natitirang kakampi, tumatagal ng 2 turn',
		zawakeSimpleDesc_ma = 'Apabila mati, aktifkan semula kesan ini dan agihkan 100% serangan berganda kepada rakan sepasukan yang tinggal, selama 2 pusingan',
		zawakeSimpleDesc_vn = 'Khi chết, kích hoạt thêm một lần hiệu ứng này và chia đều 100% công đôi của bản thân cho đồng đội còn lại, kéo dài 2 lượt',
		upLvDesc = 'Increase skill effect level +1',
		upLvDesc_en = 'Increase skill effect level +1',
		upLvDesc_th = 'เพิ่มระดับเอฟเฟกต์สกิล +1',
		upLvDesc_in = 'Tingkatkan efek keterampilan +1',
		upLvDesc_ph = 'Dagdagan ang antas ng epekto ng kasanayan +1',
		upLvDesc_ma = 'Tingkatkan kesan kemahiran +1',
		upLvDesc_vn = 'Cấp hiệu ứng kỹ năng +1',
