	[12213] = {
		id = 12213,
		skillName_vn = 'Phán quyết bão tố',
		skillName_en = 'Storm Verdict',
		skillName_th = 'คำตัดสินพายุ',
		skillName_in = 'Putusan Badai',
		skillName_ph = 'Hatol ng Bagyong',
		skillName_ma = 'Keputusan Ribut',
		skillName = 'Storm Verdict',
		describe_vn = 'Thunder God Zombie giải phóng sức mạnh của sấm sét và bay lên không trung, triệu hồi Storm Judgement tấn công mục tiêu ở hàng đầu của kẻ địch, gây #C0x3D8A99#200% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*42)$\'s #C0xF13B54# sát thương phép #C0x5B545B#, 40% khả năng [làm tê liệt] kẻ địch trong 2 lượt. Nếu mục tiêu ở trạng thái tê liệt, mục tiêu sẽ bị [choáng] trong 2 lượt.',
		describe_en = 'Thunder God Zombie unleashes the power of thunder and flies into the air, summoning Storm Judgement to attack the enemy\'s frontline target, dealing 200% Magic Damage + $(skillLevel*4*42)$ Magic Damage, with a 40% chance to [paralyze] the enemy for 2 turns. If the target is already paralyzed, it will be [stunned] for 2 turns.',
		describe_th = 'ซอมบี้เทพสายฟ้าปลดปล่อยพลังแห่งสายฟ้าและบินขึ้นบนฟ้า เรียก Storm Judgement โจมตีเป้าหมายแถวหน้าของศัตรู สร้างความเสียหายเวทมนตร์ 200% + $(skillLevel*4*42)$ พร้อมโอกาส 40% ที่จะ [ทำให้เป็นอัมพาต] ศัตรูเป็นเวลา 2 เทิร์น หากเป้าหมายอยู่ในสถานะอัมพาต จะถูก [ทำให้มึนงง] เป็นเวลา 2 เทิร์น',
		describe_in = 'Thunder God Zombie melepaskan kekuatan petir dan terbang ke udara, memanggil Storm Judgement untuk menyerang target barisan depan musuh, memberikan 200% Kerusakan Sihir + $(skillLevel*4*42)$ Kerusakan Sihir, dengan peluang 40% untuk [melumpuhkan] musuh selama 2 giliran. Jika target dalam keadaan lumpuh, target akan [terpukul] selama 2 giliran.',
		describe_ph = 'Thunder God Zombie ay nagpapalabas ng kapangyarihan ng kidlat at lumilipad sa himpapawid, tumatawag ng Storm Judgement upang atakihin ang target sa unahang hanay ng kalaban, nagdudulot ng 200% Magic Damage + $(skillLevel*4*42)$ Magic Damage, may 40% na tsansa na [paralyze] ang kalaban sa loob ng 2 turno. Kung ang target ay nasa paralyzed na estado, ang target ay magiging [stunned] sa loob ng 2 turno.',
		describe_ma = 'Thunder God Zombie melepaskan kuasa guruh dan terbang ke udara, memanggil Storm Judgement untuk menyerang sasaran barisan hadapan musuh, menyebabkan 200% Kecederaan Sihir + $(skillLevel*4*42)$ Kecederaan Sihir, dengan peluang 40% untuk [melumpuhkan] musuh selama 2 pusingan. Jika sasaran dalam keadaan lumpuh, sasaran akan [terkejut] selama 2 pusingan.',
		describe = 'Thunder God Zombie unleashes the power of thunder and flies into the air, summoning Storm Judgement to attack the enemy\'s frontline target, dealing 200% Magic Damage + $(skillLevel*4*42)$ Magic Damage, with a 40% chance to [paralyze] the enemy for 2 turns. If the target is already paralyzed, it will be [stunned] for 2 turns.',
		simDesc_vn = 'Thunder God Zombie giải phóng sức mạnh của sấm sét và bay lên không trung, triệu hồi Storm Judgement để tấn công mục tiêu ở hàng đầu của kẻ địch. Nó có khả năng làm tê liệt mục tiêu. Nếu mục tiêu ở trạng thái tê liệt sẽ bị choáng.',
		simDesc_en = 'Thunder God Zombie unleashes the power of thunder and flies into the sky, summoning Storm Judgement to attack the front-line enemy targets. It has the ability to paralyze targets. If the target is paralyzed, they will be stunned.',
		simDesc_th = 'Thunder God Zombie ปลดปล่อยพลังฟ้าร้องและบินขึ้นสู่ท้องฟ้า เรียก Storm Judgement มาตีเป้าหมายแถวหน้าในฝ่ายศัตรู มันมีความสามารถในการทำให้เป้าหมายเป็นอัมพาต หากเป้าหมายอยู่ในสถานะอัมพาตจะถูกมึนงง',
		simDesc_in = 'Thunder God Zombie mengeluarkan kekuatan petir dan terbang ke udara, memanggil Storm Judgement untuk menyerang target di barisan depan musuh. Ia memiliki kemampuan untuk melumpuhkan target. Jika target lumpuh, mereka akan terkena efek pingsan.',
		simDesc_ph = 'Pinakakawala ng Thunder God Zombie ang kapangyarihan ng kidlat at lumilipad sa himpapawid, tinatawag ang Storm Judgement upang atakihin ang mga layunin sa unang hanay ng kaaway. May kakayahan itong paralizin ang layunin. Kapag ang layunin ay na-paralyze, ito ay mae-stun.',
		simDesc_ma = 'Thunder God Zombie melepaskan kekuatan petir dan terbang ke udara, memanggil Storm Judgement untuk menyerang sasaran di barisan hadapan musuh. Ia mempunyai keupayaan untuk melumpuhkan sasaran. Jika sasaran dilumpuhkan, mereka akan terkena stun.',
		simDesc = 'Thunder God Zombie unleashes the power of thunder and flies into the sky, summoning Storm Judgement to attack the front-line enemy targets. It has the ability to paralyze targets. If the target is paralyzed, they will be stunned.',
		starEffect = __data_t__starEffect[12213],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu quả: Khi Thần Sấm Zombie tấn công mục tiêu bị <Điện giật>, tăng thêm 30% tỷ lệ <Tê liệt>, đồng thời <Tê liệt> ngẫu nhiên một mục tiêu <Điện giật> của địch trong 1 hiệp.',
		starEffectDesc = 'Enhance Effectiveness: When Zombie Thunder attacks a target affected by <#Electric Shock#>, increase the chance of <#Paralysis#> by 30%, and randomly <#Paralyze#> one <#Electric Shocked#> enemy target for 1 turn.',
		starEffectDesc_en = 'Enhance Effectiveness: When Zombie Thunder attacks a target affected by <#Electric Shock#>, increase the chance of <#Paralysis#> by 30%, and randomly <#Paralyze#> one <#Electric Shocked#> enemy target for 1 turn.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อซอมบี้เทพสายฟ้าโจมตีเป้าหมายที่อยู่ในสถานะ [ช็อต] จะเพิ่มโอกาส [อัมพาต] ขึ้นอีก 30% และทำให้ศัตรูแบบสุ่มที่อยู่ในสถานะ [ช็อต] 1 ตัวติด [อัมพาต] เป็นเวลา 1 เทิร์น',
		starEffectDesc_in = 'Tingkatkan Efektivitas: Saat Zombie Petir menyerang target yang terkena <#Kejutan Listrik#>, tingkatkan peluang <#Kelumpuhan#> sebesar 30%, sekaligus secara acak <#Melumpuhkan#> satu target musuh yang <#Kejutan Listrik#> selama 1 giliran.',
		starEffectDesc_ph = 'Pahusayin ang Bisa: Kapag inatake ng Zombie Thunder ang target na may <#Electrocuted#>, dagdagan ang 30% na tsansa ng <#Paralisis#>, at random na <#Paralyze#> ang isang target na may <#Electrocuted#> ng kalaban sa loob ng 1 turn.',
		starEffectDesc_ma = 'Tingkatkan Keberkesanan: Apabila Zombie Guruh menyerang sasaran yang mengalami <#Kejutan Elektrik#>, tambah 30% peluang <#Lumpuh#>, dan secara rawak <#Melumpuhkan#> satu sasaran musuh yang <#Kejutan Elektrik#> selama 1 pusingan.',
		zawakeEffect = __data_t__zawakeEffect[12213],
		-- {79003}
		zawakeEffectDesc = 'Thunder God Zombie unleashes the power of thunder and flies into the air, summoning Storm Judgement to attack the front row enemy target, dealing #C0x3D8A99#200% Magic Damage#C0x5B545B#+$(skillLevel*4*42)$# #C0xF13B54#Sell Damage#C0x5B545B#, 40% chance to <paralyze> the enemy for 2 turns. If the target is paralyzed, it will be <stunned> for 2 rounds. Attacking a target that is electrocuted will restore 30% of your Magic Attack cooldown.',
		zawakeEffectDesc_en = 'Thunder God Zombie unleashes the power of thunder and flies into the air, summoning Storm Judgement to attack the front row enemy target, dealing #C0x3D8A99#200% Magic Damage#C0x5B545B#+$(skillLevel*4*42)$# #C0xF13B54#Sell Damage#C0x5B545B#, 40% chance to <paralyze> the enemy for 2 turns. If the target is paralyzed, it will be <stunned> for 2 rounds. Attacking a target that is electrocuted will restore 30% of your Magic Attack cooldown.',
		zawakeEffectDesc_th = 'Thunder God Zombie ปลดปล่อยพลังแห่งสายฟ้าและบินขึ้นสู่ท้องฟ้า เรียก Storm Judgement โจมตีเป้าหมายแถวหน้าในศัตรู สร้าง #C0x3D8A99#200% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*42)$# #C0xF13B54#Sell Damage#C0x5B545B# มีโอกาส 40% ที่จะ <ทำให้เป็นอัมพาต> ศัตรูเป็นเวลา 2 เทิร์น หากเป้าหมายอยู่ในสถานะเป็นอัมพาต เป้าหมายจะถูก <มึนงง> เป็นเวลา 2 รอบ การโจมตีเป้าหมายที่ถูกไฟฟ้าช็อตจะฟื้นฟูเวลาเวลาคูลดาวน์โจมตีเวทมนตร์ของคุณ 30%',
		zawakeEffectDesc_in = 'Thunder God Zombie melepaskan kekuatan petir dan terbang ke udara, memanggil Storm Judgement untuk menyerang target barisan depan musuh, memberikan #C0x3D8A99#200% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*42)$# #C0xF13B54#Sell Damage#C0x5B545B#, 40% kemungkinan untuk <melumpuhkan> musuh selama 2 giliran. Jika target dalam keadaan lumpuh, target akan <terpana> selama 2 giliran. Menyerang target yang tersengat listrik akan mengembalikan 30% waktu cooldown Serangan Sihirmu.',
		zawakeEffectDesc_ph = 'Thunder God Zombie ay nagpapalaya ng kapangyarihan ng kidlat at lumilipad sa himpapawid, nanawagan ng Storm Judgement upang atakihin ang target sa harapang hanay ng kalaban, na nagdudulot ng #C0x3D8A99#200% Magic Damage#C0x5B545B#+$(skillLevel*4*42)$# #C0xF13B54#Sell Damage#C0x5B545B#, 40% na tsansa na <paralyze> ang kalaban sa loob ng 2 na turn. Kung ang target ay nasa paralyzed na estado, ang target ay magiging <stunned> sa loob ng 2 na rounds. Ang pag-atake sa target na electrocuted ay magpapabawi ng 30% ng iyong Magic Attack cooldown.',
		zawakeEffectDesc_ma = 'Thunder God Zombie membebaskan kuasa kilat dan terbang ke udara, memanggil Storm Judgement untuk menyerang sasaran barisan hadapan musuh, memberikan #C0x3D8A99#200% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*42)$# #C0xF13B54#Sell Damage#C0x5B545B#, 40% peluang untuk <melumpuhkan> musuh selama 2 giliran. Jika sasaran berada dalam keadaan lumpuh, sasaran akan <terpana> selama 2 pusingan. Menyerang sasaran yang eletrik akan memulihkan 30% masa masa serangan sihir anda.',
		zawakeEffectDesc_vn = 'Thunder God Zombie giải phóng sức mạnh của sấm sét và bay lên không trung, triệu hồi Storm Judgement tấn công mục tiêu ở hàng đầu của kẻ địch, gây ra #C0x3D8A99#200% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*42)$# C0xF13B54#Sell Damage#C0x5B545B#, 40% khả năng <làm tê liệt> kẻ địch trong 2 rẽ. Nếu mục tiêu ở trạng thái tê liệt, mục tiêu sẽ bị <choáng> trong 2 lượt. Tấn công mục tiêu bị điện giật sẽ phục hồi 30% thời gian tấn Công Phép thuật của bạn.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Attacking an Electroshocked target heals self by 30% of own Magic ATK',
