	[12313] = {
		id = 12313,
		skillName_vn = 'Xung kích lưỡi liềm',
		skillName_en = 'Crescent Charge',
		skillName_th = 'พุ่งชนเคียวขนาดครึ่งวงเดือน',
		skillName_in = 'Serangan Sabit Bulan Sabit',
		skillName_ph = 'Crescent Blade Assault',
		skillName_ma = 'Serangan Sabit Bulan Sabit',
		skillName = 'Crescent Charge',
		describe_vn = 'Kurosaki Ichigo sử dụng sức mạnh tử thần, hợp nhất sức mạnh tử thần với bản thân, chém ra kiếm khí vô biên tấn công mục tiêu hàng dọc phía địch, gây ra #C0xE69900#370% Công Vật Lý#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, mất 15% máu hiện tại của bản thân, nhận được [Bất Khuất] trong 2 lượt (Bất Khuất: hiệu ứng đặc biệt, tỷ lệ máu càng thấp sát thương càng cao, khi tỷ lệ máu dưới 30% đạt tối đa 100% tăng sát thương); kèm theo hiệu ứng [Đốt Cháy] trong 2 lượt (hiệu ứng tiêu cực, mục tiêu nhận sát thương bằng 12% máu đã mất của Kurosaki Ichigo trước khi hành động)',
		describe_en = 'Kurosaki Ichigo uses the power of the Shinigami, merging the Shinigami\'s power with himself, slicing out infinite sword energy to attack a vertical line of enemy targets, dealing #C0xE69900#370% Physical Attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B#, losing 15% of his current HP, gaining [Unyielding] for 2 turns (Unyielding: special effect, the lower the HP percentage, the higher the damage; when HP is below 30%, damage increase caps at 100%); along with the [Burn] effect for 2 turns (debuff, the target takes damage equal to 12% of the HP Kurosaki Ichigo has lost before acting).',
		describe_th = 'คุโรซากิ อิจิโกะ ใช้พลังของเทพมรณะ ผสานพลังเทพมรณะกับตัวเอง ฟันด้วยพลังดาบไร้ขอบเขตโจมตีเป้าหมายในแนวตั้งของศัตรู สร้างความเสียหาย #C0xE69900#370% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# สูญเสียพลังชีวิตปัจจุบัน 15% ได้รับ [ไม่ยอมแพ้] เป็นเวลา 2 ตา (ไม่ยอมแพ้: เอฟเฟ็กต์พิเศษ ยิ่งพลังชีวิตต่ำ ยิ่งทำดาเมจสูง เมื่อพลังชีวิตต่ำกว่า 30% จะเพิ่มดาเมจสูงสุด 100%) พร้อมด้วยเอฟเฟ็กต์ [ไฟลุกไหม้] 2 ตา (เอฟเฟ็กต์ลบ เป้าหมายได้รับความเสียหายเท่ากับ 12% ของพลังชีวิตที่คุโรซากิ อิจิโกะ สูญเสียก่อนทำการโจมตี)',
		describe_in = 'Kurosaki Ichigo menggunakan kekuatan Shinigami, menggabungkan kekuatan Shinigami dengan dirinya sendiri, mengayunkan energi pedang tanpa batas untuk menyerang barisan vertikal musuh, memberikan #C0xE69900#370% Serangan Fisik#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, mengorbankan 15% HP saat ini, mendapatkan [Pantang Menyerah] selama 2 giliran (Pantang Menyerah: efek khusus, semakin rendah persentase HP, semakin tinggi kerusakan; saat HP di bawah 30%, peningkatan kerusakan maksimal 100%); disertai dengan efek [Terbakar] selama 2 giliran (efek negatif, target menerima kerusakan sebesar 12% dari HP yang hilang Kurosaki Ichigo sebelum bertindak).',
		describe_ph = 'Gumagamit si Kurosaki Ichigo ng kapangyarihan ng Shinigami, pinagsasama ang kapangyarihan ng Shinigami sa kanyang sarili, at pinutol gamit ang walang hanggang enerhiya ng espada upang atakihin ang mga target sa patindihang hanay ng kalaban, na nagdudulot ng #C0xE69900#370% Physical Attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B#, nawawalan ng 15% ng kanyang kasalukuyang HP, nakakakuha ng [Hindi Susuko] sa loob ng 2 turn (Hindi Susuko: espesyal na epekto, kapag mas mababa ang porsyento ng HP, mas mataas ang damage; kapag ang HP ay nasa ilalim ng 30%, umaabot sa maximum na 100% na pagtaas ng damage); kasabay ng epekto ng [Nasusunog] sa loob ng 2 turn (negatibong epekto, tumatanggap ang target ng damage na katumbas ng 12% ng HP na nawala kay Kurosaki Ichigo bago kumilos).',
		describe_ma = 'Kurosaki Ichigo menggunakan kuasa Shinigami, menggabungkan kuasa Shinigami dengan dirinya sendiri, menebas dengan tenaga pedang tanpa batas untuk menyerang sasaran dalam barisan menegak musuh, memberikan #C0xE69900#370% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, kehilangan 15% daripada HP semasa, memperoleh [Tidak Menyerah] selama 2 pusingan (Tidak Menyerah: kesan khas, semakin rendah peratusan HP, semakin tinggi kerosakan; apabila HP di bawah 30%, peningkatan kerosakan mencapai maksimum 100%); disertakan dengan kesan [Terbakar] selama 2 pusingan (kesan negatif, sasaran menerima kerosakan bersamaan 12% daripada HP yang hilang oleh Kurosaki Ichigo sebelum bertindak).',
		describe = 'Kurosaki Ichigo uses the power of the Shinigami, merging the Shinigami\'s power with himself, slicing out infinite sword energy to attack a vertical line of enemy targets, dealing #C0xE69900#370% Physical Attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B#, losing 15% of his current HP, gaining [Unyielding] for 2 turns (Unyielding: special effect, the lower the HP percentage, the higher the damage; when HP is below 30%, damage increase caps at 100%); along with the [Burn] effect for 2 turns (debuff, the target takes damage equal to 12% of the HP Kurosaki Ichigo has lost before acting).',
		simDesc_vn = 'Ichigo Kurosaki sử dụng sức mạnh của thần chết, hòa quyện sức mạnh cái chết với bản thân, chém ra kiếm khí vô biên tấn công mục tiêu hàng ngang của đối phương, mất một phần máu, nhận được hiệu ứng bất khuất và gây hiệu ứng cháy cho mục tiêu.',
		simDesc_en = 'Ichigo Kurosaki uses the power of the death god, merging the power of death with himself, slashing out infinite sword energy to attack the opponent\'s horizontal targets, losing some health, gaining the undying effect, and applying a burn effect to the targets.',
		simDesc_th = 'อิจิโกะ คุโรซากิ ใช้พลังของเทพเจ้าแห่งความตาย ผสานพลังแห่งความตายเข้ากับตัวเอง ฟันด้วยดาบไร้ขอบเขตโจมตีเป้าหมายแนวนอนของศัตรู สูญเสียเลือดบางส่วน ได้รับเอฟเฟกต์ไม่ยอมแพ้และสร้างเอฟเฟกต์ไฟไหม้กับเป้าหมาย',
		simDesc_in = 'Ichigo Kurosaki menggunakan kekuatan dewa kematian, menggabungkan kekuatan kematian dengan dirinya sendiri, mengayunkan energi pedang tak terbatas untuk menyerang target horizontal musuh, kehilangan sebagian kesehatan, mendapatkan efek ketangguhan, dan memberikan efek terbakar pada target.',
		simDesc_ph = 'Gumagamit si Ichigo Kurosaki ng kapangyarihan ng diyos ng kamatayan, pinag-iisa ang kapangyarihan ng kamatayan sa kanyang sarili, nagsasagawa ng walang hangganang enerhiya ng espada upang atakehin ang mga pahalang na target ng kalaban, nawawala ang bahagi ng buhay, nakakakuha ng epekto ng katatagan at nagdudulot ng sunog sa mga target.',
		simDesc_ma = 'Ichigo Kurosaki menggunakan kuasa dewa kematian, menggabungkan kuasa kematian dengan dirinya, menghayunkan tenaga pedang tanpa batas untuk menyerang sasaran mendatar musuh, kehilangan sebahagian kesihatan, menerima kesan tidak menyerah dan menyebabkan kesan terbakar pada sasaran.',
		simDesc = 'Ichigo Kurosaki uses the power of the death god, merging the power of death with himself, slashing out infinite sword energy to attack the opponent\'s horizontal targets, losing some health, gaining the undying effect, and applying a burn effect to the targets.',
		starEffect = __data_t__starEffect[12313],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Hiệu ứng bất khuất được tăng cường: càng ít máu, sát thương tăng cao hơn; khi tỷ lệ máu nhỏ hơn hoặc bằng 40%, đạt tối đa 120% tăng cường, kéo dài 2 lượt.',
		starEffectDesc = 'Enhance effect: The indomitable effect is enhanced: the less health, the higher the damage; when the health rate is less than or equal to 40%, it reaches a maximum of 120% enhancement, lasting 2 turns.',
		starEffectDesc_en = 'Enhance effect: The indomitable effect is enhanced: the less health, the higher the damage; when the health rate is less than or equal to 40%, it reaches a maximum of 120% enhancement, lasting 2 turns.',
		starEffectDesc_th = 'เพิ่มประสิทธิผล: เอฟเฟกต์ไม่ยอมแพ้ได้รับการเสริม: ยิ่งเลือดน้อย ความเสียหายยิ่งสูงขึ้น; เมื่ออัตราเลือดน้อยกว่าหรือเท่ากับ 40% จะเพิ่มสูงสุดถึง 120% คงอยู่ 2 เทิร์น',
		starEffectDesc_in = 'Tingkatkan efek: Efek tak terkalahkan ditingkatkan: semakin sedikit darah, semakin besar kerusakan; ketika persentase darah kurang dari atau sama dengan 40%, mencapai maksimal peningkatan 120%, berlangsung selama 2 giliran.',
		starEffectDesc_ph = 'Pahusayin ang epekto: Ang epekto ng matatag ay pinalakas: mas kaunti ang buhay, mas mataas ang pinsala; kapag ang porsyento ng buhay ay mas mababa o katumbas ng 40%, umaabot sa pinakamataas na 120% na pagpapahusay, tumatagal ng 2 na turno.',
		starEffectDesc_ma = 'Tingkatkan kesan: Kesan tidak menyerah dipertingkatkan: semakin sedikit darah, semakin tinggi kerosakan; apabila kadar darah kurang daripada atau sama dengan 40%, mencapai peningkatan maksimum 120%, berlangsung selama 2 pusingan.',
		zawakeEffect = __data_t__zawakeEffect[12313],
		-- {79003}
		zawakeEffectDesc = 'Kurosaki Ichigo uses the power of the Death God, merging the power of the reaper with himself, slashing out an infinite sword energy to attack a vertical line of enemy targets, causing #C0xE69900#370% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ Physical Damage#C0x5B545B#, losing 15% of his current health, gaining <Unyielding> for 2 turns (Unyielding: special effect, the lower the health percentage, the higher the damage; when health is below 30%, damage increase reaches a maximum of 100%); accompanied by the effect <Burn> for 2 turns (negative effect, before acting the target takes damage equal to 18% of Kurosaki Ichigo\'s lost health).',
		zawakeEffectDesc_en = 'Kurosaki Ichigo uses the power of the Death God, merging the power of the reaper with himself, slashing out an infinite sword energy to attack a vertical line of enemy targets, causing #C0xE69900#370% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ Physical Damage#C0x5B545B#, losing 15% of his current health, gaining <Unyielding> for 2 turns (Unyielding: special effect, the lower the health percentage, the higher the damage; when health is below 30%, damage increase reaches a maximum of 100%); accompanied by the effect <Burn> for 2 turns (negative effect, before acting the target takes damage equal to 18% of Kurosaki Ichigo\'s lost health).',
		zawakeEffectDesc_th = 'Kurosaki Ichigo ใช้พลังของเทพเจ้าแห่งความตาย รวมพลังแห่งยมทูตเข้ากับตัวเอง ฟันพลังดาบไร้ขอบเขตโจมตีเป้าหมายแนวตั้งของฝ่ายตรงข้าม สร้าง #C0xE69900#370% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ ความเสียหายทางกายภาพ#C0x5B545B# เสียเลือดตัวเอง 15% ของเลือดปัจจุบัน ได้รับสถานะ <ไม่ยอมแพ้> เป็นเวลา 2 เทิร์น (ไม่ยอมแพ้: ผลพิเศษ ยิ่งเลือดต่ำ ยิ่งเพิ่มดาเมจมากขึ้น เมื่อเลือดต่ำกว่า 30% จะเพิ่มดาเมจสูงสุด 100%); พร้อมกับผล <การเผาไหม้> เป็นเวลา 2 เทิร์น (ผลเสีย เป้าหมายจะได้รับความเสียหายเท่ากับ 18% ของเลือดที่ Kurosaki Ichigo สูญเสียก่อนการกระทำ)',
		zawakeEffectDesc_in = 'Kurosaki Ichigo menggunakan kekuatan Dewa Kematian, menggabungkan kekuatan reaper dengan dirinya sendiri, mengayunkan energi pedang tanpa batas untuk menyerang target berbaris vertikal musuh, menyebabkan #C0xE69900#370% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ Kerusakan Fisik#C0x5B545B#, kehilangan 15% dari darah saat ini, mendapatkan <Tidak Terkalahkan> selama 2 giliran (Tidak Terkalahkan: efek khusus, semakin rendah persentase darah, semakin tinggi kerusakannya; saat darah di bawah 30%, peningkatan kerusakan mencapai 100% maksimum); disertai efek <Terbakar> selama 2 giliran (efek negatif, sebelum bertindak target menerima kerusakan sebesar 18% dari darah yang hilang Kurosaki Ichigo).',
		zawakeEffectDesc_ph = 'Gumagamit si Kurosaki Ichigo ng kapangyarihan ng Diyos ng Kamatayan, pinagsasama ang kapangyarihan ng reaper sa kanyang sarili, sumasagwak ng walang-hanggang enerhiya ng espada upang atakihin ang patayong hanay ng mga kalaban, na nagdudulot ng #C0xE69900#370% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*48)$ Pisikal na Pinsala#C0x5B545B#, nawawala ang 15% ng kasalukuyang buhay niya, nakakakuha ng <Hindi Matitinag> sa loob ng 2 turn (Hindi Matitinag: espesyal na epekto, mas mababa ang porsyento ng buhay, mas mataas ang pinsala; kapag buhay ay bumaba sa ilalim ng 30%, umaabot ang pagtaas ng pinsala sa 100% maximum); kasabay ang epekto ng <Pagkasunog> sa loob ng 2 turn (negatibong epekto, bago kumilos ay nakakakuha ang target ng pinsala na katumbas ng 18% ng nawalang buhay ni Kurosaki Ichigo).',
		zawakeEffectDesc_ma = 'Kurosaki Ichigo menggunakan kekuatan Tuhan Kematian, menggabungkan kekuatan pembawa maut dengan dirinya, menebas tenaga pedang tanpa batas untuk menyerang barisan menegak sasaran musuh, menyebabkan #C0xE69900#370% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ Kerosakan Fizikal#C0x5B545B#, kehilangan 15% darah semasa, mendapat <Tidak Gentar> selama 2 pusingan (Tidak Gentar: efek khas, semakin rendah peratusan darah, semakin tinggi kerosakan; apabila darah di bawah 30%, peningkatan kerosakan maksimum 100%); disertai efek <Terbakar> selama 2 pusingan (efek negatif, sebelum bertindak sasaran menerima kerosakan sebanyak 18% daripada darah yang hilang Kurosaki Ichigo).',
		zawakeEffectDesc_vn = 'Kurosaki Ichigo sử dụng sức mạnh của Thần Chết, hợp nhất sức mạnh tử thần với bản thân, chém ra vô biên kiếm khí tấn công mục tiêu hàng dọc của đối phương, gây ra #C0xE69900#370% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ Sát Thương Vật Lý#C0x5B545B#, mất 15% máu hiện tại của bản thân, nhận được <Bất Khuất> trong 2 lượt (Bất Khuất: hiệu ứng đặc biệt, tỷ lệ máu càng thấp sát thương càng cao, khi tỷ lệ máu dưới 30% đạt tối đa 100% tăng sát thương); kèm theo hiệu ứng <Thiêu Đốt> trong 2 lượt (hiệu ứng tiêu cực, trước khi hành động mục tiêu nhận sát thương bằng 18% máu đã mất của Kurosaki Ichigo).',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '<Fire Burn> (Negative effect, before acting, target takes damage equal to 12% of Kurosaki Ichigo’s missing HP)#F20# #F40##C0x5c9970#→<Fire Burn> (Before acting, target takes damage equal to 18% of Kurosaki Ichigo’s missing HP)  ',
		zawakeSimpleDesc_en = '<Fire Burn> (Negative effect, before acting, target takes damage equal to 12% of Kurosaki Ichigo’s missing HP)#F20# #F40##C0x5c9970#→<Fire Burn> (Before acting, target takes damage equal to 18% of Kurosaki Ichigo’s missing HP)  ',
		zawakeSimpleDesc_th = '<ไฟเผา> (ดีบัฟ, ก่อนเทิร์นของเป้าหมาย จะได้รับความเสียหายเท่ากับ 12% HP ที่หายไปของ Kurosaki Ichigo)#F20# #F40##C0x5c9970#→<ไฟเผา> (ก่อนเทิร์นของเป้าหมาย จะได้รับความเสียหายเท่ากับ 18% HP ที่หายไปของ Kurosaki Ichigo)  ',
		zawakeSimpleDesc_in = '<Bakar Api> (Efek negatif, sebelum bertindak target menerima damage sebesar 12% dari HP yang hilang milik Kurosaki Ichigo)#F20# #F40##C0x5c9970#→<Bakar Api> (Sebelum bertindak target menerima damage sebesar 18% dari HP yang hilang milik Kurosaki Ichigo)  ',
		zawakeSimpleDesc_ph = '<Sunog> (Debuff, bago kumilos, makakatanggap ang target ng damage katumbas ng 12% ng nawalang HP ni Kurosaki Ichigo)#F20# #F40##C0x5c9970#→<Sunog> (Bago kumilos, makakatanggap ang target ng damage katumbas ng 18% ng nawalang HP ni Kurosaki Ichigo)  ',
		zawakeSimpleDesc_ma = '<Bakar Api> (Kesan negatif, sebelum bertindak sasaran menerima kerosakan sama dengan 12% HP yang hilang milik Kurosaki Ichigo)#F20# #F40##C0x5c9970#→<Bakar Api> (Sebelum bertindak sasaran menerima kerosakan sama dengan 18% HP yang hilang milik Kurosaki Ichigo)  ',
		zawakeSimpleDesc_vn = '<Hỏa thiêu> (Hiệu ứng tiêu cực, trước khi hành động mục tiêu nhận sát thương bằng 12% máu đã mất của Kurosaki Ichigo)#F20# #F40##C0x5c9970#→<Hỏa thiêu> (Trước khi hành động mục tiêu nhận sát thương bằng 18% máu đã mất của Kurosaki Ichigo)',
