	[12413] = {
		id = 12413,
		skillName_vn = 'Bản giao hưởng mộng mơ',
		skillName_en = 'Dream Symphony',
		skillName_th = 'ซิมโฟนีแห่งความฝัน',
		skillName_in = 'Simfoni Mimpi',
		skillName_ph = 'Symphony ng Pangarap',
		skillName_ma = 'Simfoni Mimpi',
		skillName = 'Dream Symphony',
		describe_vn = 'Hatsune Miku thực hiện động tác mộng mơ, triệu hồi các nốt nhạc trên bầu trời tấn công tất cả mục tiêu địch, gây ra #C0x3D8A99#240% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4* 90)$ #C0xF13B54# Sát thương phép #C0x5B545B#, giảm giá trị thịnh nộ của nó đi 200 điểm và giảm 30% sát thương chí mạng trong 3 xoay chuyển, đồng thời xua tan mọi ảnh hưởng tiêu cực của ba quân thiện.',
		describe_en = 'Hatsune Miku performs a dreamy move, summoning musical notes in the sky to attack all enemy targets, dealing #C0x3D8A99#240% Magic Damage#C0x5B545B#+$(skillLevel*4* 90)$ #C0xF13B54# magic damage #C0x5B545B#, reducing their rage by 200 points and decreasing critical damage by 30% for 3 turns, while dispelling all negative effects from allies.',
		describe_th = 'ฮัตสึเนะ มิคุ ทำการเคลื่อนไหวในฝัน เรียกโน้ตเพลงบนท้องฟ้าโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวทมนตร์ #C0x3D8A99#240%#C0x5B545B#+$(skillLevel*4* 90)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# ลดค่าความโกรธลง 200 คะแนน และลดความเสียหายคริติคอล 30% เป็นเวลา 3 เทิร์น พร้อมทั้งขจัดผลกระทบเชิงลบทั้งหมดของพันธมิตร',
		describe_in = 'Hatsune Miku melakukan gerakan yang penuh mimpi, memanggil not musik di langit untuk menyerang semua target musuh, menyebabkan #C0x3D8A99#240% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4* 90)$ #C0xF13B54# kerusakan sihir #C0x5B545B#, mengurangi kemarahan musuh sebesar 200 poin dan mengurangi kerusakan kritis sebesar 30% selama 3 giliran, sekaligus menghilangkan semua efek negatif dari sekutu.',
		describe_ph = 'Gumagawa si Hatsune Miku ng panaginip na galaw, nagtatanghal ng mga nota ng musika sa langit upang atakihin ang lahat ng mga target ng kalaban, na nagdudulot ng #C0x3D8A99#240% Magic Damage#C0x5B545B#+$(skillLevel*4* 90)$ #C0xF13B54# magic damage #C0x5B545B#, nagpapababa ng kanilang galit ng 200 puntos at nagpapababa ng critical damage ng 30% sa loob ng 3 turn, kasabay ng pag-aalis ng lahat ng negatibong epekto mula sa mga kakampi.',
		describe_ma = 'Hatsune Miku melakukan gerakan impian, memanggil nota muzik di langit untuk menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#240% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4* 90)$ #C0xF13B54# kerosakan sihir #C0x5B545B#, mengurangkan nilai kemarahan musuh sebanyak 200 mata dan mengurangkan kerosakan kritikal sebanyak 30% selama 3 pusingan, serta menyingkirkan semua kesan negatif daripada barisan sekutu.',
		describe = 'Hatsune Miku performs a dreamy move, summoning musical notes in the sky to attack all enemy targets, dealing #C0x3D8A99#240% Magic Damage#C0x5B545B#+$(skillLevel*4* 90)$ #C0xF13B54# magic damage #C0x5B545B#, reducing their rage by 200 points and decreasing critical damage by 30% for 3 turns, while dispelling all negative effects from allies.',
		simDesc_vn = 'Hatsune Miku thực hiện một động tác mộng mơ, triệu hồi các nốt nhạc từ trên trời để tấn công các mục tiêu ở hàng sau của kẻ địch, làm giảm cơn giận và sát thương chí mạng của chúng, đồng thời xóa bỏ hầu hết các bùa lợi thân thiện.',
		simDesc_en = 'Hatsune Miku performs a dreamy move, summoning musical notes from the sky to attack enemies in the back row, reducing their rage and critical damage, while also clearing most friendly buffs.',
		simDesc_th = 'ฮัตสึเนะ มิกุ ทำท่าทางเหมือนฝัน ตะโกนโน้ตเพลงจากท้องฟ้าโจมตีเป้าหมายที่แถวหลังของศัตรู ลดความโกรธและความเสียหายคริติคอลของพวกมัน พร้อมทั้งลบโบนัสที่เป็นมิตรส่วนใหญ่',
		simDesc_in = 'Hatsune Miku melakukan gerakan seperti mimpi, memanggil nada musik dari langit untuk menyerang target di barisan belakang musuh, mengurangi kemarahan dan kerusakan kritis mereka, serta menghapus sebagian besar buff ramah.',
		simDesc_ph = 'Gumagawa si Hatsune Miku ng isang mala-panaginip na galaw, tinatawag ang mga nota ng musika mula sa langit upang atakihin ang mga target sa likurang linya ng kalaban, nagpapababa sa kanilang galit at kritikal na pinsala, habang tinatanggal rin ang karamihan sa mga friendly buffs.',
		simDesc_ma = 'Hatsune Miku melakukan satu gerakan seperti mimpi, memanggil nota muzik dari langit untuk menyerang sasaran di barisan belakang musuh, mengurangkan kemarahan dan kerosakan kritikal mereka, serta menghapus kebanyakan buff mesra.',
		simDesc = 'Hatsune Miku performs a dreamy move, summoning musical notes from the sky to attack enemies in the back row, reducing their rage and critical damage, while also clearing most friendly buffs.',
		starEffect = __data_t__starEffect[12413],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng thêm: Giảm thêm 20% sát thương chí mạng của mục tiêu, đồng thời giải một hiệu ứng khống chế ngẫu nhiên trên một mục tiêu đồng minh.',
		starEffectDesc = 'Additional effect: Reduces the target\'s critical damage by 20%, while simultaneously removing a random crowd control effect from an allied target.',
		starEffectDesc_en = 'Additional effect: Reduces the target\'s critical damage by 20%, while simultaneously removing a random crowd control effect from an allied target.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ลดความเสียหายคริติคอลของเป้าหมายลงอีก 20% และในขณะเดียวกันก็ลบสถานะควบคุมฝูงชนแบบสุ่มออกจากเป้ื่อนที่พันธมิตรหนึ่งตัว',
		starEffectDesc_in = 'Efek tambahan: Mengurangi kerusakan kritis target sebesar 20%, sekaligus menghapus efek crowd control acak pada satu target sekutu.',
		starEffectDesc_ph = 'Karagdagang epekto: Binabawasan ang kritikal na pinsala ng target ng 20%, kasabay ng pag-alis ng isang random na crowd control effect sa isang kaalyadong target.',
		starEffectDesc_ma = 'Kesan tambahan: Mengurangkan kerosakan kritikal sasaran sebanyak 20%, serentak membuang kesan kawalan orang ramai rawak pada satu sasaran sekutu.',
		zawakeEffect = __data_t__zawakeEffect[12413],
		-- {79003}
		zawakeEffectDesc = 'Hatsune Miku performs a dreamy move, summoning musical notes from the sky to attack the back row of enemies, dealing #C0x3D8A99#240% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Spell Damage#C0x5B545B#, reducing their rage by 200 points and decreasing critical damage by 30% for 3 turns. At the same time, it dispels all negative effects from three allied units and increases all allies\' control immunity rate and negative effect resistance by 5% for 1 turn.',
		zawakeEffectDesc_en = 'Hatsune Miku performs a dreamy move, summoning musical notes from the sky to attack the back row of enemies, dealing #C0x3D8A99#240% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Spell Damage#C0x5B545B#, reducing their rage by 200 points and decreasing critical damage by 30% for 3 turns. At the same time, it dispels all negative effects from three allied units and increases all allies\' control immunity rate and negative effect resistance by 5% for 1 turn.',
		zawakeEffectDesc_th = 'Hatsune Miku ทำท่าทางฝัน ๆ เรียกโน้ตเพลงจากท้องฟ้ามาโจมตีเป้าหมายแถวหลังของศัตรู สร้าง #C0x3D8A99#240% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# ลดค่าความโกรธของเป้าหมายลง 200 คะแนน และลดความเสียหายคริติคอลลง 30% เป็นเวลา 3 ตา พร้อมกันนั้น จะขจัดผลลบทั้งหมดของหน่วยพันธมิตร 3 หน่วย และเพิ่มอัตราป้องกันสถานะควบคุมและอัตราต้านผลลบของพันธมิตรทั้งหมด 5% เป็นเวลา 1 ตา',
		zawakeEffectDesc_in = 'Hatsune Miku melakukan gerakan yang seperti mimpi, memanggil nada musik dari langit untuk menyerang target di barisan belakang musuh, memberikan #C0x3D8A99#240% Damage Sihir#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Damage Sihir#C0x5B545B#, mengurangi nilai amarahnya sebesar 200 poin dan mengurangi damage kritikal sebesar 30% selama 3 giliran. Pada saat yang sama, ia menghilangkan semua efek negatif dari tiga unit sekutu, serta meningkatkan tingkat kebal terhadap kontrol dan resistensi efek negatif semua sekutu sebesar 5% selama 1 giliran.',
		zawakeEffectDesc_ph = 'Gumagawa si Hatsune Miku ng isang panaginip na galaw, nananawagan ng mga nota ng musika mula sa langit upang umatake sa likurang hanay ng mga kaaway, na nagdudulot ng #C0x3D8A99#240% Spell Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Spell Damage#C0x5B545B#, binabawasan ang kanyang galit ng 200 puntos at binabawasan ang kritikal na pinsala ng 30% sa loob ng 3 pang-ikot. Kasabay nito, nililinis nito ang lahat ng negatibong epekto ng tatlong yunit ng kaalyado, at pinapataas ang rate ng hindi mapigilang kontrol at paglaban sa negatibong epekto ng lahat ng kaalyado ng 5% sa loob ng 1 pang-ikot.',
		zawakeEffectDesc_ma = 'Hatsune Miku melakukan gerakan seperti mimpi, memanggil nota muzik dari langit untuk menyerang sasaran di barisan belakang musuh, menghasilkan #C0x3D8A99#240% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Kerosakan Sihir#C0x5B545B#, mengurangkan nilai kemarahan sebanyak 200 mata dan mengurangkan kerosakan kritikal sebanyak 30% selama 3 pusingan. Pada masa yang sama, ia menghapuskan semua kesan negatif daripada tiga unit sekutu dan meningkatkan kadar imun kawalan dan rintangan kesan negatif semua sekutu sebanyak 5% selama 1 pusingan.',
		zawakeEffectDesc_vn = 'Hatsune Miku thực hiện một động tác mộng mơ, triệu hồi các nốt nhạc từ trên trời tấn công mục tiêu ở hàng sau của kẻ địch, gây ra #C0x3D8A99#240% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$#C0xF13 B54#Spell Damage#C0x5B545B#, giảm giá trị tức giận của nó đi 200 điểm và giảm 30% sát thương chí mạng trong một thời gian. 3 lượt. Đồng thời, nó xua tan mọi tác động tiêu cực của ba đơn vị đồng minh, đồng thời tăng tỷ lệ không bị kiểm soát và tỷ lệ kháng hiệu ứng tiêu cực của tất cả đồng minh thêm 5% trong 1 lượt.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#and increase all allies\' control immunity rate and debuff resistance rate by 5% for 1 turn',
		zawakeSimpleDesc_en = '#C0x5c9970#and increase all allies\' control immunity rate and debuff resistance rate by 5% for 1 turn',
		zawakeSimpleDesc_th = '#C0x5c9970#และเพิ่มอัตราต้านควบคุมและต้านดีบัฟของพันธมิตรทั้งหมด 5% เป็นเวลา 1 เทิร์น',
		zawakeSimpleDesc_in = '#C0x5c9970#dan meningkatkan tingkat kekebalan kontrol serta resistensi efek negatif semua sekutu sebesar 5% selama 1 giliran',
		zawakeSimpleDesc_ph = '#C0x5c9970#at dagdagan ang control immunity at debuff resistance ng lahat ng kakampi ng 5% sa loob ng 1 turn',
		zawakeSimpleDesc_ma = '#C0x5c9970#dan meningkatkan kadar kebal kawalan dan rintangan debuff semua sekutu sebanyak 5% selama 1 pusingan',
		zawakeSimpleDesc_vn = '#C0x5c9970# và tăng tỷ lệ miễn nhiễm khống chế cũng như tỷ lệ kháng hiệu ứng tiêu cực của tất cả đồng minh thêm 5% trong 1 hiệp.',
