		skillName = 'Idol singer',
		describe_vn = 'Kỹ năng hào quang: #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# Tốc độ cùng #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# Kháng bạo, siêu hệ anh hùng thu hoạch được gấp đôi tăng thêm;\n Tự thân miễn dịch tuyệt đại bộ phận thiêu đốt',
		describe_en = 'Aura Skill: #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# Speed and #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# Critical Resistance, harvest doubled for super heroes;\n Immunity to most burning by itself',
		describe_th = 'ทักษะออร่า: #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# ความเร็วและ #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# การต้านทานคริติคอล, รวบรวมซูเปอร์ฮีโร่เพิ่มเป็นสองเท่า;\n ภูมิคุ้มกันต่อการถูกเผาส่วนใหญ่ด้วยตนเอง',
		describe_in = 'Skill Aura: #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# Kecepatan dan #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# Ketahanan Kritikal, panen pahlawan super bertambah dua kali lipat;\n Kebal terhadap sebagian besar efek terbakar dengan sendirinya',
		describe_ph = 'Kasanayan sa Aura: #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# Bilis at #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# Kritikal Resistensya, dobleng ani para sa mga superhero;\n Kusang nagtatanggol laban sa karamihan ng pagkasunog',
		describe_ma = 'Kemahiran Aura: #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# Kelajuan dan #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# Ketahanan Kritikal, pahlawan super memperolehi hasil berganda;\n Kebal terhadap kebakaran sebahagian besar secara sendiri',
		describe = 'Aura Skill: #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# Speed and #C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# Critical Resistance, harvest doubled for super heroes;\n Immunity to most burning by itself',
		starEffect = __data_t__starEffect[12416],
