	[12516] = {
		id = 12516,
		skillName_vn = 'Núi sập đất nứt',
		skillName_en = 'Mountain collapse, earth cracks',
		skillName_th = 'ภูเขาถล่ม ดินแตกร้าว',
		skillName_in = 'Gunung runtuh, tanah retak',
		skillName_ph = 'Bumagsak ang bundok, nabiyak ang lupa',
		skillName_ma = 'Gunung runtuh, tanah retak',
		skillName = 'Mountain collapse, earth cracks',
		describe_vn = 'Máu của bản thân càng thấp, sát thương của bản thân càng cao, tối đa có thể tăng#C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; khi nhận sát thương chí mạng, sẽ giữ lại một chút máu để sống sót trong 1 lượt, toàn trận chỉ kích hoạt 1 lần',
		describe_en = 'The lower your own HP, the higher your damage, increasing up to #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; when receiving a critical hit, you will retain a small amount of HP to survive for 1 turn, this effect can only activate once per battle.',
		describe_th = 'เลือดของตัวเองยิ่งต่ำ ความเสียหายของตัวเองก็จะยิ่งสูง เพิ่มขึ้นสูงสุด #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; เมื่อได้รับความเสียหายแบบคริติคอล จะเหลือเลือดเพียงเล็กน้อยเพื่อรอดชีวิตใน 1 ตา ผลนี้จะเกิดขึ้นได้เพียง 1 ครั้งต่อการต่อสู้หนึ่งครั้ง',
		describe_in = 'Semakin rendah HP sendiri, semakin tinggi damage yang diberikan, maksimal dapat meningkat sebesar #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; saat menerima serangan kritis, akan mempertahankan sedikit HP untuk bertahan hidup selama 1 giliran, efek ini hanya dapat aktif 1 kali per pertandingan.',
		describe_ph = 'Kapag mas mababa ang sariling HP, mas mataas ang damage na dulot, maaaring tumaas hanggang #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; kapag tumanggap ng critical damage, mananatili ang kaunting HP para mabuhay sa loob ng 1 turn, isang beses lamang ito maa-activate sa buong laban.',
		describe_ma = 'Semakin rendah darah sendiri, semakin tinggi serangan yang diberikan, boleh meningkat sehingga #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; apabila menerima kerosakan kritikal, akan menyimpan sedikit darah untuk hidup selama 1 pusingan, hanya boleh diaktifkan sekali bagi setiap perlawanan.',
		describe = 'The lower your own HP, the higher your damage, increasing up to #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; when receiving a critical hit, you will retain a small amount of HP to survive for 1 turn, this effect can only activate once per battle.',
		starEffect = __data_t__starEffect[12516],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi hiệu ứng miễn tử kết thúc, hồi phục 20% máu của bản thân.',
		starEffectDesc = 'Additional effect: When the immortality effect ends, recover 20% of your own HP.',
		starEffectDesc_en = 'Additional effect: When the immortality effect ends, recover 20% of your own HP.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อเอฟเฟกต์อมตะสิ้นสุดลง ฟื้นฟูพลังชีวิตของตนเอง 20%.',
		starEffectDesc_in = 'Efek tambahan: Saat efek keabadian berakhir, pulihkan 20% HP sendiri.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag natapos ang epekto ng imortalidad, bumawi ng 20% ng sariling HP.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila kesan kebal berakhir, pulihkan 20% darah sendiri.',
		zawakeEffect = __data_t__zawakeEffect[12516],
		-- {79004}
		zawakeEffectDesc = 'The lower #ma mau# of yourself, the higher your damage, up to a maximum increase of $(30+skillLevel*0.3-0.3)$%; when receiving critical damage, there is a 20% chance to <taunt> all enemies for 1 turn and retain a little #ma mau# to survive for 1 turn, can only be activated once per battle',
		zawakeEffectDesc_en = 'The lower #ma mau# of yourself, the higher your damage, up to a maximum increase of $(30+skillLevel*0.3-0.3)$%; when receiving critical damage, there is a 20% chance to <taunt> all enemies for 1 turn and retain a little #ma mau# to survive for 1 turn, can only be activated once per battle',
		zawakeEffectDesc_th = 'เมื่อ #ma mau# ของตัวเองต่ำลง ความเสียหายของตัวเองจะสูงขึ้น สูงสุดสามารถเพิ่มได้ $(30+skillLevel*0.3-0.3)$%; เมื่อได้รับความเสียหายวิกฤติ มีโอกาส 20% ที่จะ <ท้าทาย> ศัตรูทั้งหมดเป็นเวลา 1 เทิร์น และเก็บรักษา #ma mau# เล็กน้อยเพื่ออยู่รอดเป็นเวลา 1 เทิร์น เปิดใช้งานได้เพียงครั้งเดียวในหนึ่งแมตช์',
		zawakeEffectDesc_in = 'Semakin rendah #ma mau# diri sendiri, semakin tinggi kerusakan yang diberikan, maksimal dapat meningkat sebesar $(30+skillLevel*0.3-0.3)$%; saat menerima kerusakan kritis, ada peluang 20% untuk <menantang> semua musuh selama 1 giliran dan mempertahankan sedikit #ma mau# untuk bertahan selama 1 giliran, hanya bisa diaktifkan sekali per pertandingan',
		zawakeEffectDesc_ph = 'Kapag mas mababa ang #ma mau# mo, mas mataas ang iyong pinsala, hanggang sa maximum na pagtaas na $(30+skillLevel*0.3-0.3)$%; kapag tumanggap ng critical na pinsala, may 20% na pagkakataon na <magtalaga ng panunuya> sa lahat ng kalaban sa loob ng 1 turn at mapanatili ang kaunting #ma mau# para makaligtas sa 1 turn, maaari lamang ma-activate ng isang beses bawat laban',
		zawakeEffectDesc_ma = 'Semakin rendah #ma mau# diri sendiri, semakin tinggi kerosakan yang diberikan, maksimum boleh meningkat sebanyak $(30+skillLevel*0.3-0.3)$%; apabila menerima kerosakan kritikal, terdapat peluang 20% untuk <menghasut> semua musuh selama 1 giliran dan mengekalkan sedikit #ma mau# untuk terus hidup selama 1 giliran, hanya boleh diaktifkan sekali setiap perlawanan',
		zawakeEffectDesc_vn = 'Máu của bản thân càng thấp, sát thương của bản thân càng cao, tối đa có thể tăng $(30+skillLevel*0.3-0.3)$%; khi nhận sát thương chí mạng, có 20% cơ hội <khiêu khích> toàn bộ kẻ địch trong 1 lượt và giữ lại một chút máu để sống sót trong 1 lượt, chỉ có thể kích hoạt 1 lần trong toàn trận',
		zawakeSimpleType = 1,
