	[12526] = {
		id = 12526,
		skillName_vn = 'Núi sập đất nứt',
		skillName_en = 'Mountain collapse, ground cracks',
		skillName_th = 'ภูเขาถล่ม ดินแตกร้าว',
		skillName_in = 'Gunung runtuh, tanah retak',
		skillName_ph = 'Bumagsak ang bundok, nabiyak ang lupa',
		skillName_ma = 'Gunung runtuh, tanah retak',
		skillName = 'Mountain collapse, ground cracks',
		describe_vn = 'Máu của bản thân càng thấp, sát thương của bản thân càng cao, tối đa có thể tăng#C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; khi nhận sát thương chí mạng, sẽ giữ lại một chút máu để sống sót trong 1 lượt, toàn trận chỉ kích hoạt 1 lần',
		describe_en = 'The lower your HP, the higher your damage, increasing up to #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; when receiving a critical hit, you will retain a small amount of HP to survive for 1 turn, this effect can only trigger once per battle.',
		describe_th = 'ยิ่งเลือดของคุณต่ำ ความเสียหายของคุณจะยิ่งสูงขึ้น เพิ่มสูงสุด #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; เมื่อได้รับความเสียหายคริติคอล จะคงเลือดไว้เล็กน้อยเพื่อให้มีชีวิตรอดใน 1 เทิร์น เอฟเฟกต์นี้จะทำงานได้เพียงครั้งเดียวต่อการต่อสู้',
		describe_in = 'Semakin rendah darahmu, semakin tinggi kerusakan yang kamu berikan, maksimal meningkat sebesar #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; saat menerima serangan kritis, kamu akan mempertahankan sedikit darah agar bertahan hidup selama 1 giliran, efek ini hanya dapat aktif sekali per pertarungan.',
		describe_ph = 'Kapag mas mababa ang iyong HP, mas mataas ang iyong damage, pwedeng tumaas hanggang #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; kapag tumanggap ng critical damage, mananatili kang may kaunting HP para mabuhay ng 1 turn, at maa-activate lang ito ng isang beses sa buong laban.',
		describe_ma = 'Semakin rendah darah anda, semakin tinggi kerosakan anda, maksimum boleh meningkat sebanyak #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; apabila menerima serangan kritikal, anda akan mengekalkan sedikit darah untuk terus hidup selama 1 pusingan, kesan ini hanya boleh diaktifkan sekali setiap perlawanan.',
		describe = 'The lower your HP, the higher your damage, increasing up to #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; when receiving a critical hit, you will retain a small amount of HP to survive for 1 turn, this effect can only trigger once per battle.',
		starEffect = __data_t__starEffect[12526],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi hiệu ứng miễn tử kết thúc, hồi phục 20% máu của bản thân.',
		starEffectDesc = 'Additional Effect: When the immortal effect ends, recover 20% of your own HP.',
		starEffectDesc_en = 'Additional Effect: When the immortal effect ends, recover 20% of your own HP.',
		starEffectDesc_th = 'ผลเพิ่มเติม: เมื่อเอฟเฟกต์อมตะสิ้นสุดลง ฟื้นฟูพลังชีวิตของตัวเอง 20%',
		starEffectDesc_in = 'Efek Tambahan: Saat efek abadi berakhir, pulihkan 20% HP sendiri.',
		starEffectDesc_ph = 'Karagdagang Epekto: Kapag natapos ang epekto ng imortalidad, gumaling ng 20% ng sarili mong HP.',
		starEffectDesc_ma = 'Kesan Tambahan: Apabila kesan kebal tamat, pulihkan 20% HP diri sendiri.',
		zawakeEffect = __data_t__zawakeEffect[12526],
		-- {79004}
		zawakeEffectDesc = 'The lower #ma mau# oneself has, the higher #ma mau# damage dealt is, up to a maximum increase of $(30+skillLevel*0.3-0.3)$%; when receiving a critical hit, there is a 20% chance to <taunt> all enemies for 1 turn and keep a small amount of #ma mau# to survive for 1 turn, can only be activated once per match',
		zawakeEffectDesc_en = 'The lower #ma mau# oneself has, the higher #ma mau# damage dealt is, up to a maximum increase of $(30+skillLevel*0.3-0.3)$%; when receiving a critical hit, there is a 20% chance to <taunt> all enemies for 1 turn and keep a small amount of #ma mau# to survive for 1 turn, can only be activated once per match',
		zawakeEffectDesc_th = 'ยิ่ง #ma mau# ของตัวเองต่ำเท่าไหร่ ความเสียหายที่ตัวเองทำก็จะสูงขึ้น สูงสุดสามารถเพิ่มได้ $(30+skillLevel*0.3-0.3)$%; เมื่อได้รับความเสียหายคริติคอล มีโอกาส 20% ที่จะ <เย้ยหยัน> ศัตรูทั้งหมดเป็นเวลา 1 เทิร์น และรักษา #ma mau# เล็กน้อยไว้เพื่อมีชีวิตอยู่ 1 เทิร์น เปิดใช้งานได้เพียงครั้งเดียวต่อแมทช์',
		zawakeEffectDesc_in = 'Semakin rendah #ma mau# diri sendiri, semakin tinggi kerusakan yang diberikan, maksimal dapat meningkat $(30+skillLevel*0.3-0.3)$%; saat menerima serangan kritis, ada peluang 20% untuk <mengolok-olok> semua musuh selama 1 giliran dan menyimpan sedikit #ma mau# untuk bertahan hidup selama 1 giliran, hanya bisa aktif sekali dalam satu pertandingan',
		zawakeEffectDesc_ph = 'Kapag mas mababa ang #ma mau# ng sarili, mas mataas ang damage na naidudulot, maximum maaring tumaas ng $(30+skillLevel*0.3-0.3)$%; kapag tumanggap ng critical damage, may 20% chance na <mang-akit> ng lahat ng kalaban sa loob ng 1 turn at panatilihin ang maliit na #ma mau# para mabuhay sa loob ng 1 turn, maaaring mag-activate ng 1 beses lang sa buong laban',
		zawakeEffectDesc_ma = 'Semakin rendah #ma mau# diri sendiri, semakin tinggi kerosakan yang diberikan, maksimum boleh meningkat $(30+skillLevel*0.3-0.3)$%; apabila menerima serangan kritikal, terdapat peluang 20% untuk <mencabar> semua musuh selama 1 giliran dan mengekalkan sedikit #ma mau# untuk terus hidup selama 1 giliran, hanya boleh diaktifkan sekali dalam satu perlawanan',
		zawakeEffectDesc_vn = 'Máu của bản thân càng thấp, sát thương của bản thân càng cao, tối đa có thể tăng $(30+skillLevel*0.3-0.3)$%; khi nhận sát thương chí mạng, có 20% cơ hội <khiêu khích> toàn bộ kẻ địch trong 1 lượt và giữ lại một chút máu để sống sót trong 1 lượt, chỉ có thể kích hoạt 1 lần trong toàn trận',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#When receiving fatal damage, has a 20% chance to <Taunt> all enemies for 1 turn  ',
		zawakeSimpleDesc_en = '#C0x5c9970#When receiving fatal damage, has a 20% chance to <Taunt> all enemies for 1 turn  ',
		zawakeSimpleDesc_th = '#C0x5c9970#เมื่อได้รับความเสียหายที่อาจถึงตาย มีโอกาส 20% เพื่อ <ยั่วยุ> ศัตรูทั้งหมด 1 เทิร์น',
		zawakeSimpleDesc_in = '#C0x5c9970#Saat menerima damage fatal, memiliki 20% peluang untuk <Menantang> semua musuh selama 1 giliran  ',
		zawakeSimpleDesc_ph = '#C0x5c9970#Kapag tumanggap ng nakamamatay na pinsala, may 20% tsansa na mag-<Taunt> sa lahat ng kalaban sa loob ng 1 turn  ',
		zawakeSimpleDesc_ma = '#C0x5c9970#Apabila menerima kerosakan maut, mempunyai 20% peluang untuk <Provokasi> semua musuh selama 1 pusingan  ',
		zawakeSimpleDesc_vn = '#C0x5c9970#Khi nhận sát thương chí tử, có 20% xác suất <Khiêu khích> toàn bộ kẻ địch trong 1 lượt',
