	[12612] = {
		id = 12612,
		skillName_vn = 'Bão táp dữ dội',
		skillName_en = 'Severe storm',
		skillName_th = 'พายุรุนแรง',
		skillName_in = 'Badai hebat',
		skillName_ph = 'Matinding bagyo',
		skillName_ma = 'Ribut hebat',
		skillName = 'Severe storm',
		describe_vn = 'Lugia nhảy lên không trung và vỗ cánh tạo ra những cơn gió dữ dội tấn công mục tiêu địch, gây ra #C0x3D8A99#170% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, phục hồi 10% máu của bản thân, hấp thụ hiệu ứng tiêu cực ngẫu nhiên từ tướng đồng minh (có tỷ lệ máu ưu tiên thấp nhất) và chuyển đổi nó thành 15% máu của chính mình.',
		describe_en = 'Lugia leaps into the air and flaps its wings, creating fierce winds that attack enemy targets, dealing #C0x3D8A99#170% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Magic Damage#C0x5B545B#. It also restores 10% of its own HP, absorbs a random negative effect from an allied hero (prioritizing the one with the lowest HP), and converts it into 15% of its own HP.',
		describe_th = 'ลูเกียพุ่งขึ้นสู่อากาศและโบกปีกสร้างลมกระโชกแรงโจมตีเป้าหมายศัตรู ทำให้เกิด #C0x3D8A99#170% พลังเวทโจมตี#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#พลังเวทโจมตี#C0x5B545B# ฟื้นฟูพลังชีวิตของตนเอง 10% ดูดซับสถานะลบสุ่มจากฮีโร่พันธมิตร (ให้ความสำคัญกับผู้ที่มีพลังชีวิตต่ำที่สุด) และเปลี่ยนเป็นพลังชีวิตของตนเอง 15%.',
		describe_in = 'Lugia melompat ke udara dan mengibaskan sayapnya menciptakan angin kencang yang menyerang musuh, menyebabkan #C0x3D8A99#170% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Kerusakan Sihir#C0x5B545B#. Memulihkan 10% HP sendiri, menyerap efek negatif acak dari pahlawan sekutu (memprioritaskan yang memiliki HP terendah) dan mengubahnya menjadi 15% HP miliknya sendiri.',
		describe_ph = 'Tumalon si Lugia sa himpapawid at pinakawalan ang mga pakpak nito upang lumikha ng malalakas na hangin na umaatake sa mga kalabang target, nagdudulot ng #C0x3D8A99#170% Pinsalang Mahika#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Pinsalang Mahika#C0x5B545B#. Nagpapagaling ng 10% ng sariling HP, sumisipsip ng isang random na negatibong epekto mula sa isang alyadong bayani (pinaprioridad ang may pinakamababang HP) at ini-convert ito sa 15% ng sariling HP.',
		describe_ma = 'Lugia melompat ke udara dan mengibas sayapnya mencipta angin kencang yang menyerang sasaran musuh, menyebabkan #C0x3D8A99#170% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Kerosakan Sihir#C0x5B545B#. Memulihkan 10% darahnya sendiri, menyerap kesan negatif rawak daripada wira sekutu (mengutamakan yang mempunyai darah paling rendah) dan menukarnya menjadi 15% darahnya sendiri.',
		describe = 'Lugia leaps into the air and flaps its wings, creating fierce winds that attack enemy targets, dealing #C0x3D8A99#170% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Magic Damage#C0x5B545B#. It also restores 10% of its own HP, absorbs a random negative effect from an allied hero (prioritizing the one with the lowest HP), and converts it into 15% of its own HP.',
		zawakeEffect = __data_t__zawakeEffect[12612],
		-- {79002}
		zawakeEffectDesc = 'Lugia leaps into the air and flaps its wings, creating a violent storm that attacks enemy targets, dealing #C0x3D8A99#170% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Magical Damage#C0x5B545B#, restoring 10% of its own health, absorbing three random negative effects from allied heroes (with the lowest priority health rate) and converting them into 25% of its own health.',
		zawakeEffectDesc_en = 'Lugia leaps into the air and flaps its wings, creating a violent storm that attacks enemy targets, dealing #C0x3D8A99#170% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Magical Damage#C0x5B545B#, restoring 10% of its own health, absorbing three random negative effects from allied heroes (with the lowest priority health rate) and converting them into 25% of its own health.',
		zawakeEffectDesc_th = 'ลูเกีย กระโดดขึ้นกลางอากาศและโบกปีก สร้างพายุรุนแรงโจมตีเป้าหมายศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#170%#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# ฟื้นฟูพลังชีวิตตนเอง 10% ดูดซับสถานะลบสุ่มสามอย่างจากฝ่ายพันธมิตร (ซึ่งมีพลังชีวิตน้อยที่สุดเป็นลำดับความสำคัญ) แล้วเปลี่ยนเป็นพลังชีวิตตนเอง 25%',
		zawakeEffectDesc_in = 'Lugia melompat ke udara dan mengepakkan sayapnya, menciptakan badai dahsyat yang menyerang target musuh, menyebabkan #C0x3D8A99#170% Damage Magical#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Damage Magical#C0x5B545B#, memulihkan 10% darahnya sendiri, menyerap tiga efek negatif acak dari pahlawan sekutu (dengan prioritas darah terendah) dan mengubahnya menjadi 25% darahnya sendiri.',
		zawakeEffectDesc_ph = 'Tumalon si Lugia sa himpapawid at pinalipad ang mga pakpak nito, lumilikha ng malakas na bagyo na umatake sa mga kalaban, nagdudulot ng #C0x3D8A99#170% Pinsalang Magical#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Pinsalang Magical#C0x5B545B#, nagpapagaling ng 10% ng sariling buhay, sumisipsip ng tatlong random na negatibong epekto mula sa mga kakampi (na may pinakamababang prioridad sa buhay) at ginagawang 25% ng sariling buhay nito.',
		zawakeEffectDesc_ma = 'Lugia melompat ke udara dan mengepakkan sayapnya, menghasilkan ribut kuat yang menyerang sasaran musuh, menyebabkan #C0x3D8A99#170% Kerosakan Ajaib#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Kerosakan Ajaib#C0x5B545B#, memulihkan 10% darahnya sendiri, menyerap tiga kesan negatif rawak dari wira sekutu (dengan keutamaan darah terendah) dan menukarnya menjadi 25% darahnya sendiri.',
		zawakeEffectDesc_vn = 'Lugia nhảy lên không trung và vỗ cánh tạo ra một cơn bão dữ dội tấn công mục tiêu địch, gây ra #C0x3D8A99#170% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, phục hồi 10% máu của bản thân, hấp thụ ba hiệu ứng tiêu cực ngẫu nhiên từ các tướng đồng minh (có tỷ lệ máu ưu tiên thấp nhất) và chuyển đổi chúng thành 25% máu của chính mình.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Absorb one random negative effect from an allied hero (lowest HP ratio prioritized) and convert it into 15% of your own HP\n#F20# \n#F40##C0x5c9970#→Absorb three random negative effects from an allied hero (lowest HP ratio prioritized) and convert it into 25% of your own HP',
		zawakeSimpleDesc_en = 'Absorb one random negative effect from an allied hero (lowest HP ratio prioritized) and convert it into 15% of your own HP\n#F20# \n#F40##C0x5c9970#→Absorb three random negative effects from an allied hero (lowest HP ratio prioritized) and convert it into 25% of your own HP',
		zawakeSimpleDesc_th = 'ดูดซับ 1 ดีบัฟแบบสุ่มจากฮีโร่ฝ่ายเรา (เลือกผู้มี % HP ต่ำที่สุด) และแปลงเป็น 15% HP ของตัวเอง\n#F20# \n#F40##C0x5c9970#→ดูดซับ 3 ดีบัฟแบบสุ่มจากฮีโร่ฝ่ายเรา (เลือกผู้มี % HP ต่ำที่สุด) และแปลงเป็น 25% HP ของตัวเอง',
		zawakeSimpleDesc_in = 'Menyerap satu efek negatif acak dari hero sekutu (prioritas rasio HP terendah) dan mengubahnya menjadi 15% HP milik sendiri\n#F20# \n#F40##C0x5c9970#→Menyerap tiga efek negatif acak dari hero sekutu (prioritas rasio HP terendah) dan mengubahnya menjadi 25% HP milik sendiri',
		zawakeSimpleDesc_ph = 'Sumisipsip ng isang random na debuff mula sa kakamping hero (inuuna ang may pinakamababang HP ratio) at ginagawang 15% HP para sa sarili\n#F20# \n#F40##C0x5c9970#→Sumisipsip ng tatlong random na debuff mula sa kakamping hero (inuuna ang may pinakamababang HP ratio) at ginagawang 25% HP para sa sarili',
		zawakeSimpleDesc_ma = 'Serap satu kesan negatif rawak dari hero sekutu (keutamaan nisbah HP terendah) dan tukarkannya kepada 15% HP sendiri\n#F20# \n#F40##C0x5c9970#→Serap tiga kesan negatif rawak dari hero sekutu (keutamaan nisbah HP terendah) dan tukarkannya kepada 25% HP sendiri',
		zawakeSimpleDesc_vn = 'Hấp thụ một hiệu ứng tiêu cực ngẫu nhiên từ anh hùng đồng minh (tỷ lệ máu ưu tiên thấp nhất) và chuyển đổi nó thành 15% máu của chính bạn\n#F20# \n#F40##C0x5c9970#→Hấp thụ ba hiệu ứng tiêu cực ngẫu nhiên từ anh hùng đồng minh (tỷ lệ máu ưu tiên thấp nhất) và chuyển đổi nó thành 25% máu của chính bạn.',
