	[12613] = {
		id = 12613,
		skillName_vn = 'Bão lốc xoáy',
		skillName_en = 'Typhoon',
		skillName_th = 'ไต้ฝุ่น',
		skillName_in = 'Topan',
		skillName_ph = 'Bagyo',
		skillName_ma = 'Taufan',
		skillName = 'Typhoon',
		describe_vn = 'Lugia có mối liên hệ chân thành với đại dương và lặn sâu xuống đáy đại dương. Khi anh ta nhảy lên, một cơn bão xoáy ập đến, gây ra #C0x3D8A99#300% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$ tới ba mục tiêu kẻ thù ngẫu nhiên. F13B54#Sát thương phép#C0x5B545B#. Đối với mỗi kẻ địch bị mất một kẻ địch, sát thương chí mạng sẽ tăng thêm 30%. Đồng thời, nó sẽ bổ sung khả năng bảo vệ gió cho tất cả các anh hùng, tăng 10% tốc độ và 15% né tránh trong 2 hiệp, đồng thời tăng khả năng giảm sát thương chí mạng của bản thân thêm 25% trong 2 hiệp.',
		describe_en = 'Lugia has a sincere connection with the ocean and dives deep into the seabed. When it leaps up, a cyclone storm erupts, causing #C0x3D8A99#300% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$ to three random enemy targets. F13B54#Magic Damage#C0x5B545B#. For each enemy defeated, critical damage increases by 30%. At the same time, it grants wind protection to all heroes, increasing speed by 10% and evasion by 15% for 2 turns, while also increasing its own critical damage reduction by 25% for 2 turns.',
		describe_th = 'ลูเกียมีความสัมพันธ์อย่างจริงใจกับมหาสมุทรและดำน้ำลึกลงไปใต้ทะเล เมื่อมันกระโดดขึ้น พายุไซโคลนจะพัดเข้ามา สร้างความเสียหายเวทมนตร์ #C0x3D8A99#300%#+$(skillLevel*4*60)$ แก่ศัตรูสุ่มสามเป้าหมาย F13B54#ความเสียหายเวทมนตร์#C0x5B545B# สำหรับศัตรูแต่ละตัวที่ถูกทำลาย ความเสียหายคริติคอลจะเพิ่มขึ้นอีก 30% พร้อมกันนั้นยังมอบการปกป้องลมให้ฮีโร่ทั้งหมด เพิ่มความเร็ว 10% และการหลบหลีก 15% เป็นเวลา 2 เทิร์น พร้อมทั้งเพิ่มการลดความเสียหายคริติคอลของตัวเองอีก 25% เป็นเวลา 2 เทิร์น',
		describe_in = 'Lugia memiliki hubungan yang tulus dengan lautan dan menyelam jauh ke dasar laut. Ketika ia melompat, sebuah badai siklon muncul, menyebabkan #C0x3D8A99#300% Damage Magic#C0x5B545B#+$(skillLevel*4*60)$ kepada tiga target musuh acak. F13B54#Damage Magic#C0x5B545B#. Untuk setiap musuh yang kalah, damage kritis meningkat sebesar 30%. Pada saat yang sama, ia memberikan perlindungan angin kepada semua pahlawan, meningkatkan kecepatan sebesar 10% dan penghindaran sebesar 15% selama 2 giliran, sekaligus meningkatkan pengurangan damage kritisnya sendiri sebesar 25% selama 2 giliran.',
		describe_ph = 'May matapat na koneksyon si Lugia sa dagat at sumisisid nang malalim sa ilalim ng dagat. Kapag siya ay tumalon, isang bagyong siklon ang dumating, nagdudulot ng #C0x3D8A99#300% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$ sa tatlong random na kaaway. F13B54#Magic Damage#C0x5B545B#. Para sa bawat kalabang natalo, tumataas ang critical damage ng 30%. Kasabay nito, nagbibigay ito ng proteksyon sa hangin sa lahat ng mga bayani, tumataas ang bilis ng 10% at pag-iwas ng 15% sa loob ng 2 rounds, habang pinapataas din ang sariling critical damage reduction ng 25% sa loob ng 2 rounds.',
		describe_ma = 'Lugia mempunyai hubungan yang tulus dengan lautan dan menyelam ke dasar laut. Apabila ia melompat, ribut taufan akan melanda, menyebabkan #C0x3D8A99#300% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*60)$ kepada tiga sasaran musuh secara rawak. F13B54#Kerosakan Magik#C0x5B545B#. Bagi setiap musuh yang kalah, kerosakan kritikal akan meningkat sebanyak 30%. Pada masa yang sama, ia memberikan perlindungan angin kepada semua wira, meningkatkan kelajuan sebanyak 10% dan kelicikan sebanyak 15% selama 2 pusingan, serta meningkatkan pengurangan kerosakan kritikal dirinya sendiri sebanyak 25% selama 2 pusingan.',
		describe = 'Lugia has a sincere connection with the ocean and dives deep into the seabed. When it leaps up, a cyclone storm erupts, causing #C0x3D8A99#300% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$ to three random enemy targets. F13B54#Magic Damage#C0x5B545B#. For each enemy defeated, critical damage increases by 30%. At the same time, it grants wind protection to all heroes, increasing speed by 10% and evasion by 15% for 2 turns, while also increasing its own critical damage reduction by 25% for 2 turns.',
		simDesc_vn = 'Lugia có mối liên hệ chân thành với đại dương. Anh lặn xuống vực sâu của biển. Khi anh ta nhảy lên, một cơn bão xoáy tràn vào tấn công ba mục tiêu kẻ thù ngẫu nhiên và thêm [Người bảo vệ gió] cho tất cả các anh hùng của anh ta.',
		simDesc_en = 'Lugia has a sincere connection with the ocean. He dives into the deep sea abyss. When he leaps up, a whirlwind storm rushes in to attack three random enemy targets and adds <Wind Guardian> to all his heroes.',
		simDesc_th = 'ลูเกียมีความสัมพันธ์ที่จริงใจกับมหาสมุทร เขาดำน้ำลงสู่หุบเหวลึกของทะเล เมื่อเขากระโดดขึ้น พายุหมุนจะพุ่งเข้าทำลายเป้าหมายศัตรูสามตัวแบบสุ่มและเพิ่ม [ผู้พิทักษ์ลม] ให้กับฮีโร่ทั้งหมดของเขา',
		simDesc_in = 'Lugia memiliki hubungan yang tulus dengan lautan. Dia menyelam ke jurang dalam laut. Ketika dia melompat, badai pusaran menyerbu menyerang tiga target musuh secara acak dan menambahkan <Penjaga Angin> ke semua pahlawannya.',
		simDesc_ph = 'May tunay na ugnayan si Lugia sa karagatan. Siya ay sumisid sa kailaliman ng dagat. Kapag siya ay tumalon, isang unos na umiikot ang dumadagsa upang atakihin ang tatlong random na target na kalaban at magdagdag ng <Tagapangalaga ng Hangin> sa lahat ng kanyang mga bayani.',
		simDesc_ma = 'Lugia mempunyai hubungan ikhlas dengan lautan. Dia menyelam ke dalam jurang laut yang dalam. Apabila dia melompat, ribut pusaran menyerbu menyerang tiga sasaran musuh secara rawak dan menambah <Penjaga Angin> kepada semua wira-wiranya.',
		simDesc = 'Lugia has a sincere connection with the ocean. He dives into the deep sea abyss. When he leaps up, a whirlwind storm rushes in to attack three random enemy targets and adds [Wind Guardian] to all his heroes.',
		starEffect = __data_t__starEffect[12613],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu quả: Tăng cường hiệu ứng của  <Phong Chi Thủ Hộ> : Tăng 20% tốc độ và 25% né tránh; bản thân cũng có thể kích hoạt né tránh khi chia sẻ sát thương.',
		starEffectDesc = 'Enhance Effect: Enhance the effect of <Phong Chi Thủ Hộ>: Increase speed by 20% and evasion by 25%; also allows self to activate evasion when sharing damage.',
		starEffectDesc_en = 'Enhance Effect: Enhance the effect of <Phong Chi Thủ Hộ>: Increase speed by 20% and evasion by 25%; also allows self to activate evasion when sharing damage.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: เพิ่มผลของ <Phong Chi Thủ Hộ>: เพิ่มความเร็ว 20% และการหลบหลีก 25%; ตัวเองยังสามารถเปิดใช้งานการหลบหลีกเมื่อแบ่งปันความเสียหายได้',
		starEffectDesc_in = 'Tingkatkan Efek: Tingkatkan efek <Phong Chi Thủ Hộ>: Tambah kecepatan 20% dan evasi 25%; diri sendiri juga dapat mengaktifkan evasi saat berbagi kerusakan.',
		starEffectDesc_ph = 'Palakasin ang epekto: Palakasin ang epekto ng <Phong Chi Thủ Hộ>: Dagdagan ang bilis ng 20% at iwas ng 25%; maaari ring mag-activate ng iwas kapag nagbabahagi ng pinsala.',
		starEffectDesc_ma = 'Tingkatkan Kesan: Tingkatkan kesan <Phong Chi Thủ Hộ>: Tambah kelajuan 20% dan elakan 25%; diri sendiri juga boleh mengaktifkan elakan ketika berkongsi kerosakan.',
		zawakeEffect = __data_t__zawakeEffect[12613],
		-- {79003}
		zawakeEffectDesc = 'Lugia has a sincere connection with the ocean and dives into the deep sea abyss. When he leaps up, a whirlpool storm strikes, causing #C0x3D8A99#300% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$ of #C0xF13B54#magical damage#C0x5B for three random enemy targets. Each time an enemy is lost, the damage of this critical strike increases by 30%. At the same time, all heroes in the team are protected by the wind, increasing speed by 10% and evasion by 15% for 3 turns (the effect on flying heroes increases by 35%), and increasing critical damage reduction by 25% for 2 turns; meanwhile, the <self-healing> revive effect is extended by 1 turn.',
		zawakeEffectDesc_en = 'Lugia has a sincere connection with the ocean and dives into the deep sea abyss. When he leaps up, a whirlpool storm strikes, causing #C0x3D8A99#300% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$ of #C0xF13B54#magical damage#C0x5B for three random enemy targets. Each time an enemy is lost, the damage of this critical strike increases by 30%. At the same time, all heroes in the team are protected by the wind, increasing speed by 10% and evasion by 15% for 3 turns (the effect on flying heroes increases by 35%), and increasing critical damage reduction by 25% for 2 turns; meanwhile, the <self-healing> revive effect is extended by 1 turn.',
		zawakeEffectDesc_th = 'ลูเกียมีความสัมพันธ์ที่แท้จริงกับมหาสมุทรและดำน้ำลงสู่เบื้องลึกของทะเล เมื่อลูกกระโดดขึ้น พายุหมุนจะเกิดขึ้น ทำให้เกิด #C0x3D8A99#300% ความเสียหายเวทย์มนตร์#C0x5B545B#+$(skillLevel*4*60)$ ของ #C0xF13B54#ความเสียหายเวทย์มนตร์#C0x5B แก่ศัตรูสุ่มสามเป้าหมาย ทุกครั้งที่ศัตรูหนึ่งตัวถูกทำลาย ความเสียหายของการโจมตีคริติคอลนี้จะเพิ่มขึ้น 30% ในขณะเดียวกัน ฮีโร่ทุกคนในทีมจะได้รับการปกป้องด้วยลม เพิ่มความเร็ว 10% และหลบหลีก 15% เป็นเวลา 3 เทิร์น (ผลต่อฮีโร่ที่บินได้จะเพิ่มขึ้น 35%) และเพิ่มการลดความเสียหายคริติคอลอีก 25% เป็นเวลา 2 เทิร์น; พร้อมกันนั้น เอฟเฟกต์ <การฟื้นฟูตัวเอง> ที่ช่วยไม่ตายจะขยายเวลาออกไปอีก 1 เทิร์น',
		zawakeEffectDesc_in = 'Lugia memiliki hubungan yang tulus dengan lautan dan menyelam ke kedalaman laut. Saat dia melompat, badai pusaran air muncul, menyebabkan #C0x3D8A99#300% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*60)$ dari #C0xF13B54#kerusakan magis#C0x5B pada tiga target musuh acak. Setiap kali musuh hilang, kerusakan serangan kritis ini meningkat sebesar 30%. Pada saat yang sama, semua pahlawan dalam tim terlindungi oleh angin, meningkatkan kecepatan sebesar 10% dan menghindar sebesar 15% selama 3 giliran (efek pada pahlawan terbang meningkat sebesar 35%), dan meningkatkan pengurangan kerusakan kritis sebesar 25% selama 2 giliran; sekaligus, efek kebangkitan <pemulihan diri> diperpanjang selama 1 giliran.',
		zawakeEffectDesc_ph = 'Ang Lugia ay may taimtim na koneksyon sa karagatan at lumalangoy sa kailaliman ng dagat. Kapag siya ay tumalon, isang bagyong paikot ang dumating, na nagdudulot ng #C0x3D8A99#300% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$ mula sa #C0xF13B54#magical damage#C0x5B sa tatlong random na target na kalaban. Sa bawat pagkawala ng kalaban, tumataas ng 30% ang pinsala ng critical strike na ito. Kasabay nito, lahat ng mga bayani sa koponan ay pinoprotektahan ng hangin, na nagpapataas ng bilis ng 10% at pag-iwas ng 15% sa loob ng 3 turn (ang epekto sa mga bayaning lumilipad ay tumataas ng 35%), at nagpapataas ng critical damage reduction ng 25% sa loob ng 2 turn; sabay nito, ang ‘<self-healing>’ revive effect ay pinahaba pa ng 1 turn.',
		zawakeEffectDesc_ma = 'Lugia mempunyai hubungan yang ikhlas dengan lautan dan menyelam ke dasar laut yang dalam. Apabila dia melompat, ribut pusaran air berlaku, menyebabkan #C0x3D8A99#300% Kerosakan Ajaib#C0x5B545B#+$(skillLevel*4*60)$ daripada #C0xF13B54#kerosakan ajaib#C0x5B kepada tiga sasaran musuh rawak. Setiap kali musuh hilang, kerosakan serangan kritikal ini bertambah sebanyak 30%. Pada masa yang sama, semua wira dalam pasukan dilindungi oleh angin, meningkatkan kelajuan sebanyak 10% dan elakkan sebanyak 15% selama 3 giliran (kesan ke atas wira terbang meningkat sebanyak 35%), serta meningkatkan pengurangan kerosakan kritikal sebanyak 25% selama 2 giliran; serentak itu, kesan kebangkitan <pemulihan diri> dilanjutkan selama 1 giliran.',
		zawakeEffectDesc_vn = 'Lugia có mối liên hệ chân thành với đại dương và lặn xuống vực sâu của biển. Khi anh ta nhảy lên, một cơn bão xoáy ập đến, gây ra #C0x3D8A99#300% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$ thuộc #C0xF13B54#sát thương phép#C0x5B cho ba mục tiêu kẻ thù ngẫu nhiên. 545B#, mỗi khi kẻ địch mất kẻ địch, sát thương của đòn chí mạng này sẽ tăng thêm 30%. Đồng thời, tất cả các anh hùng trong đội sẽ được bảo vệ bằng gió, giúp tăng 10% tốc độ và 15% né tránh trong 3 hiệp (hiệu ứng lên tướng bay sẽ tăng 35%), và tăng khả năng giảm sát thương chí mạng thêm 25% trong 2 hiệp; đồng thời, hiệu ứng không chết của <tự phục hồi> sẽ được kéo dài thêm 1 lượt.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Guardian of the Wind increases Speed by 10% and Evasion by 15% for 3 turns (effect increases to 35% on flying heroes); also extends <Self-Recovery>\'s undying effect by 1 turn.',
		zawakeSimpleDesc_en = 'Guardian of the Wind increases Speed by 10% and Evasion by 15% for 3 turns (effect increases to 35% on flying heroes); also extends <Self-Recovery>\'s undying effect by 1 turn.',
		zawakeSimpleDesc_th = 'ผู้พิทักษ์สายลมเพิ่มความเร็วขึ้น 10% และหลบหลีกขึ้น 15% เป็นเวลา 3 เทิร์น (ฮีโร่บินได้รับโบนัสเพิ่มเป็น 35%); และขยายเอฟเฟกต์อมตะของ <ฟื้นตัวเอง> อีก 1 เทิร์น',
		zawakeSimpleDesc_in = 'Penjaga Angin meningkatkan kecepatan sebesar 10% dan penghindaran sebesar 15% selama 3 giliran (efek meningkat menjadi 35% untuk hero terbang); juga memperpanjang efek tidak mati dari <Pemulihan Diri> selama 1 giliran',
		zawakeSimpleDesc_ph = 'Pinoprotektahan ng Tagapangalaga ng Hangin ang sarili sa pamamagitan ng pagtaas ng Bilis ng 10% at Evasion ng 15% sa loob ng 3 turn (tumataas sa 35% para sa mga lumilipad na bayani); pinapahaba rin ang hindi-namamamatay na epekto ng <Paghilom sa Sarili> ng 1 turn',
		zawakeSimpleDesc_ma = 'Penjaga Angin meningkatkan Kelajuan sebanyak 10% dan Elak sebanyak 15% selama 3 pusingan (kesan meningkat kepada 35% untuk hero terbang); turut memanjangkan kesan tidak mati dari <Pemulihan Diri> selama 1 pusingan',
		zawakeSimpleDesc_vn = 'Guardian of the Wind tăng tốc độ lên 10% và né tránh lên 15% trong 3 lượt (hiệu ứng lên tướng bay tăng 35%); nó cũng kéo dài hiệu ứng không chết của <Tự phục hồi> thêm 1 lượt.',
		upLvDesc = 'Fixed damage +240',
		upLvDesc_en = 'Fixed damage +240',
