	[12616] = {
		id = 12616,
		skillName_vn = 'Self-Regeneration',
		skillName_en = 'Self-Regeneration',
		skillName_th = 'การฟื้นฟูตนเอง',
		skillName_in = 'Regenerasi Diri',
		skillName_ph = 'Sariling Pagpapanumbalik',
		skillName_ma = 'Pemulihan Diri',
		skillName = 'Self-Regeneration',
		describe_vn = 'Nó giữ lại một giọt máu và miễn nhiễm sát thương chí mạng trong 1 lượt. Nó ngay lập tức khôi phục sức khỏe #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (bị ảnh hưởng bởi hiệu quả điều trị) và #C0x5c997 trước vòng hành động tiếp theo. 0#$(600+skillLevel*2-2)$#C0x5B545B# điểm thịnh nộ;\nKhi anh hùng có tỷ lệ máu thấp nhất đang bảo vệ phe mình trong trận chiến bị tấn công bởi các kỹ năng chủ động của kẻ địch, Lugia sẽ chia sẻ 50% sát thương (sát thương chung được sửa đổi theo thuộc tính phòng thủ của Lugia)',
		describe_en = 'It retains a drop of blood and is immune to critical damage for 1 turn. It immediately restores #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (affected by healing effects) health and gains #C0x5c997 0#$(600+skillLevel*2-2)$#C0x5B545B# fury points before the next action round. \n When the hero with the lowest health protecting their side in battle is attacked by enemy active skills, Lugia will share 50% of the damage (damage shared is adjusted according to Lugia\'s defense attribute).',
		describe_th = 'มันเก็บเลือดไว้หนึ่งหยดและได้รับการป้องกันความเสียหายคริติคอลใน 1 เทิร์น มันฟื้นฟูสุขภาพทันที #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (ได้รับผลจากประสิทธิภาพการรักษา) และรับ #C0x5c997 0#$(600+skillLevel*2-2)$#C0x5B545B# คะแนนโกรธก่อนรอบการกระทำถัดไป \n เมื่อฮีโร่ที่มีอัตราสุขภาพต่ำที่สุดที่ปกป้องฝ่ายของตนถูกโจมตีด้วยสกิลแอคทีฟของศัตรู Lugia จะแบ่งปันความเสียหาย 50% (ความเสียหายที่แบ่งปันถูกปรับตามค่าการป้องกันของ Lugia).',
		describe_in = 'Ia menyimpan setetes darah dan kebal terhadap kerusakan kritis selama 1 giliran. Ia segera memulihkan kesehatan sebanyak #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (dipengaruhi oleh efek penyembuhan) dan mendapatkan #C0x5c997 0#$(600+skillLevel*2-2)$#C0x5B545B# poin amarah sebelum giliran aksi berikutnya. \n Ketika pahlawan dengan persentase darah terendah yang melindungi timnya diserang oleh skill aktif musuh, Lugia akan membagi 50% kerusakan (kerusakan yang dibagi disesuaikan berdasarkan atribut pertahanan Lugia).',
		describe_ph = 'Nagtatabi ito ng isang patak ng dugo at immune sa critical damage sa loob ng 1 turn. Agad nitong nire-recover ang kalusugan ng #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (apektado ng healing effect) at nakakakuha ng #C0x5c997 0#$(600+skillLevel*2-2)$#C0x5B545B# na puntos ng poot bago ang susunod na round ng aksyon. \n Kapag ang bayani na may pinakamababang health percentage na nagpoprotekta sa kanyang panig ay inaatake ng mga active skills ng kalaban, si Lugia ay maghahati ng 50% ng damage (ang nasabing damage ay ina-adjust base sa defense attribute ni Lugia).',
		describe_ma = 'Ia mengekalkan setitis darah dan kebal kepada kerosakan kritikal selama 1 pusingan. Ia segera memulihkan kesihatan sebanyak #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (dipengaruhi oleh kesan penyembuhan) dan mendapat #C0x5c997 0#$(600+skillLevel*2-2)$#C0x5B545B# mata kemarahan sebelum pusingan tindakan seterusnya. \n Apabila wira dengan peratus darah terendah yang melindungi pihaknya diserang oleh kemahiran aktif musuh, Lugia akan berkongsi 50% kerosakan (kerosakan dikongsi dilaras mengikut atribut pertahanan Lugia).',
		describe = 'It retains a drop of blood and is immune to critical damage for 1 turn. It immediately restores #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (affected by healing effects) health and gains #C0x5c997 0#$(600+skillLevel*2-2)$#C0x5B545B# fury points before the next action round. \n When the hero with the lowest health protecting their side in battle is attacked by enemy active skills, Lugia will share 50% of the damage (damage shared is adjusted according to Lugia\'s defense attribute).',
		starEffect = __data_t__starEffect[12616],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Mỗi lần bị tấn công bởi kỹ năng chủ động, tăng 3% khả năng giảm sát thương (không thể giải trừ), tối đa có thể tăng lên 30%.',
		starEffectDesc = 'Additional Effect: Each time attacked by an active skill, increases damage reduction chance by 3% (cannot be dispelled), up to a maximum of 30%.',
		starEffectDesc_en = 'Additional Effect: Each time attacked by an active skill, increases damage reduction chance by 3% (cannot be dispelled), up to a maximum of 30%.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: ทุกครั้งที่ถูกโจมตีโดยสกิลแอคทีฟ จะเพิ่มโอกาสลดความเสียหายขึ้น 3% (ไม่สามารถลบได้) สูงสุดเพิ่มได้ถึง 30%',
		starEffectDesc_in = 'Efek Tambahan: Setiap kali diserang oleh skill aktif, meningkatkan kemungkinan pengurangan kerusakan sebesar 3% (tidak dapat dihapus), maksimum dapat meningkat hingga 30%.',
		starEffectDesc_ph = 'Karagdagang Epekto: Sa bawat pag-atake gamit ang aktibong kasanayan, tumataas ng 3% ang tsansa ng pagbawas ng pinsala (hindi maaalis), hanggang sa maximum na 30%.',
		starEffectDesc_ma = 'Kesan Tambahan: Setiap kali diserang oleh kemahiran aktif, meningkatkan kemungkinan pengurangan kerosakan sebanyak 3% (tidak boleh dibuang), maksimum boleh meningkat sehingga 30%.',
		zawakeEffect = __data_t__zawakeEffect[12616],
		-- {79004}
		zawakeEffectDesc = 'It retains a drop of blood and is immune to critical damage for 1 turn. It will immediately restore #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# health (affected by healing effects) and #C0x5c9970#$(600+skillLevel*2-2)$#C0x5B545B# before the next action round, causes anger and increases its own evasion by 50% for 1 turn, while removing all self-control abilities; The hero with the lowest health ratio protecting their side in battle will share 50% damage when attacked by enemies\' active skills (damage is generally modified according to Lugia\'s defense attribute).',
		zawakeEffectDesc_en = 'It retains a drop of blood and is immune to critical damage for 1 turn. It will immediately restore #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# health (affected by healing effects) and #C0x5c9970#$(600+skillLevel*2-2)$#C0x5B545B# before the next action round, causes anger and increases its own evasion by 50% for 1 turn, while removing all self-control abilities; The hero with the lowest health ratio protecting their side in battle will share 50% damage when attacked by enemies\' active skills (damage is generally modified according to Lugia\'s defense attribute).',
		zawakeEffectDesc_th = 'มันเก็บเลือดไว้หยดหนึ่งและไม่รับความเสียหายคริติคอลใน 1 เทิร์น มันจะฟื้นฟูสุขภาพทันที #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (ได้รับผลจากเอฟเฟกต์การรักษา) และ #C0x5c9970#$(600+skillLevel*2-2)$#C0x5B545B# ก่อนรอบการกระทำถัดไป ทำให้เกิดความโกรธและเพิ่มการหลบหลีกของตัวเอง 50% เป็นเวลา 1 เทิร์น พร้อมทั้งลบความสามารถควบคุมตนเองทั้งหมด; ฮีโร่ที่มีอัตราสุขภาพต่ำที่สุดที่ปกป้องฝ่ายของตนในสนามรบบางจะแบ่งปันความเสียหาย 50% เมื่อถูกโจมตีโดยสกิลใช้งานของศัตรู (ความเสียหายโดยรวมถูกปรับตามค่าป้องกันของลูเกีย).',
		zawakeEffectDesc_in = 'Ia mempertahankan setetes darah dan kebal terhadap kerusakan kritis selama 1 giliran. Ia akan segera memulihkan #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# kesehatan (dipengaruhi oleh efek penyembuhan) dan #C0x5c9970#$(600+skillLevel*2-2)$#C0x5B545B# sebelum giliran aksi berikutnya, menyebabkan amarah dan meningkatkan penghindaran dirinya sendiri sebesar 50% selama 1 giliran, sekaligus menghapus semua kemampuan pengendalian diri; Pahlawan dengan rasio darah terendah yang melindungi pihaknya dalam pertempuran akan berbagi 50% kerusakan saat diserang oleh skill aktif musuh (kerusakan umum dimodifikasi menurut atribut pertahanan Lugia).',
		zawakeEffectDesc_ph = 'Nananatili ito ng isang patak ng dugo at immune sa critical damage sa loob ng 1 turn. Agad nitong ibabalik ang #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# na kalusugan (naipapailalim sa epekto ng pagpapagaling) at #C0x5c9970#$(600+skillLevel*2-2)$#C0x5B545B# bago ang susunod na round ng aksyon, nagdudulot ng galit at pinapataas ang sariling evasion ng 50% sa loob ng 1 turn, habang tinatanggal ang lahat ng kakayahang kontrolin ang sarili; Ang bayani na may pinakamababang health ratio na nagpoprotekta sa kanilang panig sa laban ay maghahati ng 50% damage kapag inatake ng mga aktibong skill ng kalaban (ang pinsalang pangkalahatan ay inaayos base sa defense attribute ni Lugia).',
		zawakeEffectDesc_ma = 'Ia mengekalkan setitis darah dan kebal terhadap kerosakan kritikal selama 1 pusingan. Ia akan segera memulihkan #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# kesihatan (dipengaruhi oleh kesan penyembuhan) dan #C0x5c9970#$(600+skillLevel*2-2)$#C0x5B545B# sebelum pusingan tindakan seterusnya, menyebabkan amarah dan meningkatkan keupayaan mengelak diri sendiri sebanyak 50% selama 1 pusingan, serta menghapus semua kebolehan kawalan kendiri; Wira dengan nisbah darah paling rendah yang melindungi pihaknya dalam pertempuran akan berkongsi 50% kerosakan apabila diserang oleh kemahiran aktif musuh (kerosakan umum diubah suai mengikut atribut pertahanan Lugia).',
		zawakeEffectDesc_vn = 'Nó giữ lại một giọt máu và miễn nhiễm sát thương chí mạng trong 1 lượt. Nó sẽ ngay lập tức khôi phục sức khỏe #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# sức khỏe (bị ảnh hưởng bởi hiệu ứng điều trị) và #C0x5c9970#$(600+skil) trước vòng hành động tiếp theo. lLevel*2-2)$#C0x5B545B# gây tức giận và tăng 50% khả năng né tránh của bản thân trong 1 lượt, đồng thời xóa bỏ mọi khả năng tự kiểm soát;\nAnh hùng có tỷ lệ máu thấp nhất bảo vệ phe mình trong trận chiến sẽ chia sẻ 50% sát thương khi bị tấn công bởi các kỹ năng chủ động của kẻ địch (sát thương chung được sửa đổi theo thuộc tính phòng thủ của Lugia)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#When the undying effect ends, increase Dodge by 50% for self for 1 turn, and remove all control statuses from self  ',
		zawakeSimpleDesc_en = '#C0x5c9970#When the undying effect ends, increase Dodge by 50% for self for 1 turn, and remove all control statuses from self  ',
		zawakeSimpleDesc_th = '#C0x5c9970#เมื่อเอฟเฟกต์อมตะสิ้นสุด เพิ่มอัตราหลบหลีก 50% ให้ตัวเอง 1 เทิร์น พร้อมลบสถานะควบคุมทั้งหมดของตัวเอง',
		zawakeSimpleDesc_in = '#C0x5c9970#Saat efek tidak mati berakhir, meningkatkan Evasion sebesar 50% untuk diri sendiri selama 1 giliran, dan menghapus semua status kontrol dari diri sendiri  ',
		zawakeSimpleDesc_ph = '#C0x5c9970#Kapag natapos ang epekto ng pagiging imortal, dagdagan ng 50% Evasion para sa sarili sa loob ng 1 turn, at alisin lahat ng crowd control sa sarili  ',
		zawakeSimpleDesc_ma = '#C0x5c9970#Apabila kesan tidak mati tamat, tingkatkan 50% Evasion kepada diri sendiri selama 1 pusingan, serta buang semua status kawalan dari diri sendiri  ',
		zawakeSimpleDesc_vn = '#C0x5c9970#Khi hiệu quả bất tử kết thúc, tăng 50% né tránh cho bản thân trong 1 lượt, đồng thời xóa bỏ toàn bộ trạng thái khống chế của bản thân',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
