	[12711] = {
		id = 12711,
		skillName_vn = 'Thần Điểu Mãnh Kích',
		skillName_en = 'Divine Bird Fierce Strike',
		skillName_th = 'เทพนกจู่โจมดุร้าย',
		skillName_in = 'Serangan Hebat Burung Ilahi',
		skillName_ph = 'Diyos na Ibon Matinding Suntok',
		skillName_ma = 'Serangan Hebat Burung Ilahi',
		skillName = 'Divine Bird Fierce Strike',
		describe_vn = 'Phượng Vương nhanh chóng bao vây kẻ địch và phát động đòn tấn công ác liệt, tấn công một mục tiêu địch, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24) $\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, thêm một lớp [Holy Fire Burning] cho mục tiêu trong 2 lượt (Holy Fire Burning: hiệu ứng âm, mục tiêu thua 40% sát thương thực sự của đòn Sát Thương Vật Lý của Phượng Hoàng Vương trước mỗi hiệp)',
		describe_en = 'Phoenix King quickly surrounds the enemy and launches a fierce attack, targeting one enemy to deal #C0xE69900#100% Physical Damage#C0x5B545B# + $(skillLevel*4*24) \'s #C0xF13B54# Physical Damage #C0x5B545B#, adding a layer of [Holy Fire Burning] on the target for 2 turns (Holy Fire Burning: a sound effect, the target loses 40% of the true damage from the Phoenix King\'s Physical Damage attacks before each round).',
		describe_th = 'ฟีนิกซ์คิงล้อมศัตรูอย่างรวดเร็วและโจมตีอย่างดุเดือด โจมตีเป้าหมายศัตรูหนึ่งตัว สร้าง #C0xE69900#100% ความเสียหายทางกายภาพ#C0x5B545B# + $(skillLevel*4*24) \'s #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# เพิ่มชั้น [Holy Fire Burning] ให้เป้าหมายเป็นเวลา 2 เทิร์น (Holy Fire Burning: เอฟเฟกต์เสียง เป้าหมายเสีย 40% ของความเสียหายจริงจากการโจมตีทางกายภาพของฟีนิกซ์คิงก่อนแต่ละเทิร์น)',
		describe_in = 'Raja Phoenix dengan cepat mengepung musuh dan melancarkan serangan hebat, menyerang satu target musuh, menyebabkan #C0xE69900#100% Kerusakan Fisik#C0x5B545B# + $(skillLevel*4*24) \'s #C0xF13B54# Kerusakan Fisik #C0x5B545B#, menambahkan satu lapisan [Holy Fire Burning] pada target selama 2 giliran (Holy Fire Burning: efek suara, target kehilangan 40% dari kerusakan sejati dari serangan Kerusakan Fisik Raja Phoenix sebelum setiap giliran).',
		describe_ph = 'Agad na pinapalibutan ng Phoenix King ang kaaway at inilulunsad ang isang malupit na atake, tumatarget sa isang kalaban, na nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B# + $(skillLevel*4*24) \'s #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, nagdadagdag ng isang layer ng [Holy Fire Burning] sa target sa loob ng 2 turn (Holy Fire Burning: isang sound effect, nawawala ang target ng 40% ng tunay na pinsala mula sa mga Pisikal na Atake ng Phoenix King bago ang bawat round).',
		describe_ma = 'Raja Phoenix dengan pantas mengepung musuh dan melancarkan serangan ganas, menyerang satu sasaran musuh, menyebabkan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B# + $(skillLevel*4*24) \'s #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, menambah satu lapisan [Holy Fire Burning] pada sasaran selama 2 pusingan (Holy Fire Burning: kesan bunyi, sasaran kehilangan 40% daripada kerosakan sebenar daripada serangan Kerosakan Fizikal Raja Phoenix sebelum setiap pusingan).',
		describe = 'Phoenix King quickly surrounds the enemy and launches a fierce attack, targeting one enemy to deal #C0xE69900#100% Physical Damage#C0x5B545B# + $(skillLevel*4*24) \'s #C0xF13B54# Physical Damage #C0x5B545B#, adding a layer of [Holy Fire Burning] on the target for 2 turns (Holy Fire Burning: a sound effect, the target loses 40% of the true damage from the Phoenix King\'s Physical Damage attacks before each round).',
		simDesc_vn = 'Phượng Vương nhanh chóng bao vây kẻ địch và tung ra đòn tấn công bạo lực đúng lúc, tấn công vào một mục tiêu duy nhất của kẻ địch.',
		simDesc_en = 'The Phoenix King quickly surrounds the enemy and launches a violent attack at the right moment, striking a single enemy target.',
		simDesc_th = 'จ้าวฟีนิกซ์ล้อมรอบศัตรูอย่างรวดเร็วและโจมตีอย่างรุนแรงในเวลาที่เหมาะสม โจมตีเป้าหมายศัตรูเพียงหนึ่งเดียว',
		simDesc_in = 'Raja Phoenix dengan cepat mengepung musuh dan melancarkan serangan ganas pada waktu yang tepat, menyerang satu target musuh.',
		simDesc_ph = 'Mabilis na pumapalibot ang Phoenix King sa kalaban at nagpapalabas ng marahas na pag-atake sa tamang sandali, tumatarget sa isang kalabang nilalayon.',
		simDesc_ma = 'Raja Phoenix dengan pantas mengepung musuh dan melancarkan serangan ganas pada masa yang tepat, menyerang satu sasaran musuh sahaja.',
		simDesc = 'The Phoenix King quickly surrounds the enemy and launches a violent attack at the right moment, striking a single enemy target.',
		zawakeEffect = __data_t__zawakeEffect[12711],
		-- {79001}
		zawakeEffectDesc = 'The Phoenix quickly surrounds the enemy and launches a fierce attack, striking a single enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B# +$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#, adding one layer of <Holy Fire Burn> to the target for 2 turns (Holy Fire Burn: sound effect, the target suffers 40% of the true damage of the Phoenix King\'s Physical Damage before each round) and adding one layer of <Holy Fire Burn> to random other units for 2 rounds (Holy Fire Burn: negative effect, the target loses 40% of the standard damage of the Phoenix King\'s Physical Damage before each round)',
		zawakeEffectDesc_en = 'The Phoenix quickly surrounds the enemy and launches a fierce attack, striking a single enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B# +$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#, adding one layer of <Holy Fire Burn> to the target for 2 turns (Holy Fire Burn: sound effect, the target suffers 40% of the true damage of the Phoenix King\'s Physical Damage before each round) and adding one layer of <Holy Fire Burn> to random other units for 2 rounds (Holy Fire Burn: negative effect, the target loses 40% of the standard damage of the Phoenix King\'s Physical Damage before each round)',
		zawakeEffectDesc_th = 'นกฟีนิกซ์ล้อมศัตรูอย่างรวดเร็วและโจมตีอย่างโหดเหี้ยม โจมตีเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหายทางกายภาพ #C0xE69900#100%#C0x5B545B# +$(skillLevel*4*24)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มชั้น <Holy Fire Burn> ให้เป้าหมายเป็นเวลา 2 เทิร์น (Holy Fire Burn: เอฟเฟกต์เสียง เป้าหมายได้รับความเสียหายจริง 40% จากความเสียหายทางกายภาพของราชานกฟีนิกซ์ก่อนแต่ละรอบ) และเพิ่มชั้น <Thánh Hỏa Đốt> ให้กับหน่วยสุ่มอื่นๆ เป็นเวลา 2 เทิร์น (Thánh Hỏa Đốt: เอฟเฟกต์ลบ เป้าหมายสูญเสียความเสียหายปกติ 40% จากความเสียหายทางกายภาพของราชานกฟีนิกซ์ก่อนแต่ละรอบ)',
		zawakeEffectDesc_in = 'Burung Phoenix dengan cepat mengepung musuh dan melakukan serangan ganas, menyerang satu target musuh, menyebabkan #C0xE69900#100% Kerusakan Fisik#C0x5B545B# +$(skillLevel*4*24)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, menambahkan satu lapis <Holy Fire Burn> pada target selama 2 giliran (Holy Fire Burn: efek suara, target menerima 40% dari kerusakan asli dari Kerusakan Fisik Raja Phoenix sebelum setiap giliran) dan menambahkan satu lapis <Thánh Hỏa Đốt> ke unit acak lainnya selama 2 giliran (Thánh Hỏa Đốt: efek negatif, target kehilangan 40% dari kerusakan standar Kerusakan Fisik Raja Phoenix sebelum setiap giliran)',
		zawakeEffectDesc_ph = 'Mabilis na pinapalibutan ng Phoenix ang kalaban at nagsasagawa ng malupit na pag-atake, tumatama sa isang target na kalaban, nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B# +$(skillLevel*4*24)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#, nagdadagdag ng isang layer ng <Holy Fire Burn> sa target sa loob ng 2 turn (Holy Fire Burn: epekto ng tunog, ang target ay tumatanggap ng 40% ng totoong pinsala ng Pisikal na Pinsala ng Phoenix King bago ang bawat round) at nagdadagdag ng isang layer ng <Thánh Hỏa Đốt> sa mga random na yunit sa loob ng 2 turn (Thánh Hỏa Đốt: negatibong epekto, ang target ay nawawala ng 40% ng karaniwang pinsala ng Pisikal na Pinsala ng Phoenix King bago ang bawat round)',
		zawakeEffectDesc_ma = 'Phoenix dengan cepat mengepung musuh dan melakukan serangan ganas, menyerang satu sasaran musuh, menyebabkan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B# +$(skillLevel*4*24)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, menambah satu lapisan <Holy Fire Burn> pada sasaran selama 2 pusingan (Holy Fire Burn: kesan bunyi, sasaran menerima 40% daripada kerosakan sebenar Kerosakan Fizikal Raja Phoenix sebelum setiap pusingan) dan menambah satu lapisan <Thánh Hỏa Đốt> kepada unit rawak lain selama 2 pusingan (Thánh Hỏa Đốt: kesan negatif, sasaran kehilangan 40% daripada kerosakan standard Kerosakan Fizikal Raja Phoenix sebelum setiap pusingan)',
		zawakeEffectDesc_vn = 'Phượng Hoàng nhanh chóng bao vây kẻ địch và thực hiện đòn tấn công ác liệt, tấn công một mục tiêu địch, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B #, thêm một lớp <Holy Fire Burn> cho mục tiêu trong 2 lượt (Holy Fire Burn: hiệu ứng âm, mục tiêu thua 40% sát thương thực sự của đòn Sát Thương Vật Lý của Phượng Hoàng Vương trước mỗi hiệp) và thêm một lớp <Thánh Hỏa Đốt> cho các đơn vị ngẫu nhiên khác trong 2 hiệp (Thiêu Hỏa Hỏa: hiệu ứng tiêu cực, mục tiêu mất 40% sát thương chuẩn của đòn Sát Thương Vật Lý của Phượng Hoàng Vương trước mỗi hiệp)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Add one layer of <Holy Fire Burning> to other random units for 2 turns (Holy Fire Burning: negative effect, target loses 40% of Phoenix King\'s true physical damage before each round)  ',
		zawakeSimpleDesc_en = '#C0x5c9970#Add one layer of <Holy Fire Burning> to other random units for 2 turns (Holy Fire Burning: negative effect, target loses 40% of Phoenix King\'s true physical damage before each round)  ',
		zawakeSimpleDesc_th = '#C0x5c9970#เพิ่ม 1 ชั้น <เพลิงศักดิ์สิทธิ์แผดเผา> ให้กับหน่วยสุ่มอื่นเป็นเวลา 2 เทิร์น (เพลิงศักดิ์สิทธิ์แผดเผา: ดีบัฟ, เป้าหมายจะเสีย HP เท่ากับ 40% ความเสียหายกายภาพจริงของราชาฟีนิกซ์ก่อนแต่ละรอบ)  ',
		zawakeSimpleDesc_in = '#C0x5c9970#Tambahkan satu lapisan <Api Suci Membakar> ke unit acak lainnya selama 2 giliran (Api Suci Membakar: efek negatif, target kehilangan 40% dari damage fisik murni Raja Phoenix sebelum setiap ronde)  ',
		zawakeSimpleDesc_ph = '#C0x5c9970#Magdagdag ng isang layer ng <Banal na Apoy na Nasusunog> sa ibang random na unit sa loob ng 2 turn (Banal na Apoy na Nasusunog: debuff, target ay nawawalan ng 40% ng tunay na pisikal na pinsala mula sa Phoenix King bago ang bawat round)  ',
		zawakeSimpleDesc_ma = '#C0x5c9970#Tambah satu lapisan <Api Suci Membakar> kepada unit rawak lain selama 2 pusingan (Api Suci Membakar: kesan negatif, sasaran kehilangan 40% kerosakan fizikal sebenar Raja Phoenix sebelum setiap pusingan)  ',
