	[12713] = {
		id = 12713,
		skillName_vn = 'Phoenix Soaring in the Sky',
		skillName_en = 'Phoenix Soaring in the Sky',
		skillName_th = 'ฟีนิกซ์ทะยานสู่ท้องฟ้า',
		skillName_in = 'Phoenix Terbang Tinggi di Langit',
		skillName_ph = 'Phoenix Lumilipad sa Kalangitan',
		skillName_ma = 'Phoenix Terbang Tinggi di Langit',
		skillName = 'Phoenix Soaring in the Sky',
		describe_vn = 'Phượng Vương bay lên trên bầu trời, từ miệng phóng ra những tia sáng nóng như ánh nắng, tấn công mọi mục tiêu của kẻ địch, gây #C0xE69900#180% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*60)$ thuộc #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, thêm vào tất cả mục tiêu kẻ địch Một lớp [Holy Fire Burning] cho 2 vòng; ban cho đồng đội không phải mình (ưu tiên ở hàng đầu) [Chúc phúc] (Chúc phúc: hiệu ứng đặc biệt. Sau khi chết, nó sẽ biến thành trứng phượng. Trứng phượng sẽ vỡ sau khi bị tấn công 6 lần. Nếu không bị vỡ, nó sẽ hồi sinh sau vòng tiếp theo. Sau khi hồi sinh, 50% lượng máu và 30% cơn thịnh nộ sẽ được giữ lại.) [Chúc phúc cho chim] chỉ có thể được kích hoạt một lần trong trận đấu. toàn bộ lĩnh vực.',
		describe_en = 'The Phoenix King soars into the sky, emitting rays of heat like sunlight from its mouth, attacking all enemy targets, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$ of #C0xF13B54#Physical Damage#C0x5B545B#, adding a layer of [Holy Fire Burning] to all enemy targets for 2 rounds; grants allies except itself (prioritizing the front row) [Blessing] (Blessing: special effect. Upon death, it transforms into a phoenix egg. The egg will break after being attacked 6 times. If not broken, it will revive after the next round. Upon revival, 50% HP and 30% fury are retained.) [Blessing of the Bird] can only be activated once per match. Whole field effect.',
		describe_th = 'ราชานกฟีนิกซ์บินขึ้นสู่ท้องฟ้า ปล่อยแสงความร้อนราวกับแสงแดดจากปาก โจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายทางกายภาพ #C0xE69900#180%#C0x5B545B#+$(skillLevel*4*60)$ ของ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มสถานะ [Holy Fire Burning] ให้ศัตรูทุกตัวเป็นเวลา 2 รอบ; มอบ [Blessing] ให้กับพันธมิตรที่ไม่ใช่ตัวเอง (เน้นแถวหน้า) (Blessing: เอฟเฟ็กต์พิเศษ เมื่อตาย จะกลายเป็นไข่นกฟีนิกซ์ ไข่นี้จะแตกหลังโดนโจมตี 6 ครั้ง หากไม่แตก จะฟื้นคืนชีพหลังจบรอบถัดไป หลังฟื้นคืนชีพ จะรักษาพลังชีวิตไว้ 50% และความโกรธ 30%) [Blessing of the Bird] สามารถเปิดใช้งานได้เพียงครั้งเดียวในแต่ละแมตช์ ส่งผลทั่วแผนที่',
		describe_in = 'Raja Phoenix terbang ke langit, memancarkan sinar panas seperti sinar matahari dari mulutnya, menyerang semua target musuh, memberikan #C0xE69900#180% Damage Fisik#C0x5B545B#+$(skillLevel*4*60)$ dari #C0xF13B54#Damage Fisik#C0x5B545B#, menambahkan lapisan [Holy Fire Burning] ke semua target musuh selama 2 giliran; memberikan [Blessing] kepada sekutu selain dirinya sendiri (prioritas barisan depan) (Blessing: efek khusus. Setelah mati, akan berubah menjadi telur phoenix. Telur akan pecah setelah diserang 6 kali. Jika tidak pecah, akan bangkit kembali setelah giliran berikutnya. Setelah bangkit kembali, mempertahankan 50% HP dan 30% kemarahan.) [Blessing of the Bird] hanya dapat diaktifkan sekali per pertandingan. Efek seluruh medan.',
		describe_ph = 'Ang Hari ng Phoenix ay lumilipad pataas sa kalangitan, nagpapalabas ng mga sinag ng init na parang sikat ng araw mula sa bibig, umaatake sa lahat ng mga target ng kalaban, nagdudulot ng #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$ ng #C0xF13B54#Physical Damage#C0x5B545B#, nagdadagdag ng isang layer ng [Holy Fire Burning] sa lahat ng mga target ng kalaban para sa 2 round; nagbibigay sa mga kaalyado maliban sa sarili (pinaprioritize ang front row) ng [Blessing] (Blessing: espesyal na epekto. Pagkatapos mamatay, magiging isang phoenix egg. Ang itlog ay mababasag pagkatapos tamaan ng 6 na beses. Kung hindi mababasag, magbabangon ito pagkatapos ng susunod na round. Pagkabangon, 50% HP at 30% galit ang mananatili.) [Blessing of the Bird] ay maaaring magamit lamang isang beses sa buong laban. Apektado ang buong field.',
		describe_ma = 'Raja Phoenix terbang ke langit, memancarkan sinar panas seperti sinaran matahari dari mulutnya, menyerang semua sasaran musuh, memberikan #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*60)$ daripada #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, menambah lapisan [Holy Fire Burning] kepada semua sasaran musuh selama 2 pusingan; memberikan [Blessing] kepada rakan sepasukan selain dirinya (utamakan barisan hadapan) (Blessing: kesan istimewa. Selepas mati, ia akan berubah menjadi telur phoenix. Telur akan pecah selepas diserang 6 kali. Jika tidak pecah, ia akan hidup semula selepas pusingan seterusnya. Selepas hidup semula, 50% HP dan 30% kemarahan akan dikekalkan.) [Blessing of the Bird] hanya boleh diaktifkan sekali dalam perlawanan. Keseluruhan medan berkesan.',
		describe = 'The Phoenix King soars into the sky, emitting rays of heat like sunlight from its mouth, attacking all enemy targets, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$ of #C0xF13B54#Physical Damage#C0x5B545B#, adding a layer of [Holy Fire Burning] to all enemy targets for 2 rounds; grants allies except itself (prioritizing the front row) [Blessing] (Blessing: special effect. Upon death, it transforms into a phoenix egg. The egg will break after being attacked 6 times. If not broken, it will revive after the next round. Upon revival, 50% HP and 30% fury are retained.) [Blessing of the Bird] can only be activated once per match. Whole field effect.',
		simDesc_vn = 'Phượng Hoàng bay lượn trên trời, phun ra những tia sáng nóng bỏng như ánh mặt trời từ miệng, tấn công toàn bộ mục tiêu kẻ thù, và thêm một lớp lửa thánh, ban cho một đồng đội khác ngoài bản thân hiệu ứng phước lành của thần điểu.',
		simDesc_en = 'The Phoenix soars in the sky, unleashing scorching rays like sunlight from its mouth, attacking all enemy targets, and adding a layer of holy flames, granting another ally besides itself the blessing effect of the divine bird.',
		simDesc_th = 'นกฟีนิกซ์บินวนในท้องฟ้า พ่นแสงเปลวไฟร้อนแรงเหมือนแสงอาทิตย์จากปาก โจมตีเป้าหมายศัตรูทั้งหมด และเพิ่มชั้นไฟศักดิ์สิทธิ์ มอบผลแห่งพรจากนกศักดิ์สิทธิ์ให้กับพันธมิตรอีกคนหนึ่งนอกจากตัวมันเอง',
		simDesc_in = 'Phoenix terbang melayang di langit, memuntahkan sinar panas seperti sinar matahari dari mulutnya, menyerang semua target musuh, dan menambahkan lapisan api suci, memberikan efek berkat dari burung ilahi kepada satu rekan selain dirinya sendiri.',
		simDesc_ph = 'Ang Phoenix ay lumilipad sa himpapawid, nagpapalabas ng mainit na mga sinag tulad ng sikat ng araw mula sa bibig, inaatake ang lahat ng mga kaaway, at nagdadagdag ng isang patong ng banal na apoy, na nagbibigay ng pagpapala mula sa banal na ibon sa isa pang kasamahan bukod sa sarili nito.',
		simDesc_ma = 'Phoenix terbang melayang di langit, memancarkan sinaran panas seperti cahaya matahari dari mulutnya, menyerang semua sasaran musuh, dan menambah lapisan api suci, memberi rakan satu lagi selain dirinya sendiri kesan berkat burung suci.',
		simDesc = 'The Phoenix soars in the sky, unleashing scorching rays like sunlight from its mouth, attacking all enemy targets, and adding a layer of holy flames, granting another ally besides itself the blessing effect of the divine bird.',
		starEffect = __data_t__starEffect[12713],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Mục tiêu được hồi sinh bởi <Phúc lành của thần điểu> sẽ giữ nguyên toàn bộ máu và toàn bộ năng lượng.',
		starEffectDesc = 'Enhance effect: The target resurrected by <Blessing of the Divine Bird> will retain full health and full energy.',
		starEffectDesc_en = 'Enhance effect: The target resurrected by <Blessing of the Divine Bird> will retain full health and full energy.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: เป้าหมายที่ถูกชุบชีวิตโดย <พรของนกเทพ> จะรักษาเลือดและพลังงานเต็มจำนวนไว้',
		starEffectDesc_in = 'Tingkatkan efek: Target yang dihidupkan kembali oleh <Berkah Burung Ilahi> akan mempertahankan seluruh darah dan energi penuh.',
		starEffectDesc_ph = 'Palakasin ang epekto: Ang target na binuhay muli ng <Basbas ng Makalangit na Ibon> ay mananatili ang buong buhay at buong enerhiya.',
		starEffectDesc_ma = 'Tambah kesan: Sasaran yang dihidupkan semula oleh <Berkat Burung Ilahi> akan mengekalkan kesihatan dan tenaga sepenuhnya.',
		zawakeEffect = __data_t__zawakeEffect[12713],
		-- {79003}
		zawakeEffectDesc = 'The Phoenix King soars into the sky, releasing beams of heat like sunlight from its mouth, attacking all enemy targets, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#Physical Damage#C0x5B545B#, applying a layer of <Holy Fire Burn> to all enemy targets for 2 turns; grants it to one ally excluding yourself. (Top priority) <Bird Welfare> (Special effect, upon death transforms into a phoenix egg. The phoenix egg is destroyed after 6 attacks. If not destroyed, it will revive next round. Upon revival, 50% health and 30% rage are retained) <Bird Blessing> After Phoenix King revives, 2 random heroes from the team and up to 2 allies on the field will be revived; and <Holy Fire Barrier> will be applied to all friendly fire heroes for 2 turns.',
		zawakeEffectDesc_en = 'The Phoenix King soars into the sky, releasing beams of heat like sunlight from its mouth, attacking all enemy targets, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#Physical Damage#C0x5B545B#, applying a layer of <Holy Fire Burn> to all enemy targets for 2 turns; grants it to one ally excluding yourself. (Top priority) <Bird Welfare> (Special effect, upon death transforms into a phoenix egg. The phoenix egg is destroyed after 6 attacks. If not destroyed, it will revive next round. Upon revival, 50% health and 30% rage are retained) <Bird Blessing> After Phoenix King revives, 2 random heroes from the team and up to 2 allies on the field will be revived; and <Holy Fire Barrier> will be applied to all friendly fire heroes for 2 turns.',
		zawakeEffectDesc_th = 'ราชาฟีนิกส์บินขึ้นไปในท้องฟ้า ปล่อยลำแสงร้อนเหมือนแสงแดดจากปาก โจมตีเป้าหมายศัตรูทั้งหมด ก่อให้เกิด #C0xE69900#180% ความเสียหายกายภาพ#C0x5B545B#+$(ระดับทักษะ*4*60)$#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# เพิ่มชั้นของ <เปลวไฟศักดิ์สิทธิ์เผา> ให้กับเป้าหมายศัตรูทั้งหมดเป็นเวลา 2 เทิร์น; มอบให้แก่หนึ่งพันธมิตรยกเว้นตัวคุณเอง (ลำดับความสำคัญสูงสุด) <สวัสดิการนก> (เอฟเฟกต์พิเศษ หลังตายจะกลายเป็นไข่ฟีนิกส์ ไข่ฟีนิกส์จะถูกทำลายหลังถูกโจมตี 6 ครั้ง หากไม่ถูกทำลาย จะฟื้นคืนชีพในรอบถัดไป หลังฟื้นคืน 50% ของพลังชีวิตและ 30% ของความโกรธจะถูกเก็บไว้) <พรนก> หลังจากราชาฟีนิกส์ฟื้นคืน จะฟื้น 2 ฮีโร่สุ่มจากทีมและสูงสุด 2 พันธมิตรบนสนาม และ <โล่ไฟศักดิ์สิทธิ์> จะถูกเพิ่มให้กับฮีโร่ไฟฝ่ายเราทุกคนเป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Raja Phoenix terbang ke langit, mengeluarkan sinar panas seperti sinar matahari dari mulutnya, menyerang semua target musuh, memberikan #C0xE69900#180% Kerusakan Fisik#C0x5B545B#+$(level skill*4*60)$#C0xF13B54#Kerusakan Fisik#C0x5B545B#, menambahkan lapisan <Pembakaran Api Suci> pada semua target musuh selama 2 giliran; memberikannya kepada satu rekan kecuali diri Anda sendiri. (Prioritas utama) <Kesejahteraan Burung> (Efek khusus, setelah mati berubah menjadi telur phoenix. Telur phoenix hancur setelah diserang 6 kali. Jika tidak hancur, akan bangkit pada giliran berikutnya. Setelah bangkit, 50% HP dan 30% amarah dipertahankan) <Berkah Burung> Setelah Raja Phoenix bangkit, 2 pahlawan acak dari tim dan maksimal 2 rekan akan dibangkitkan di seluruh arena; dan <Penghalang Api Suci> akan diterapkan pada semua pahlawan api ramah selama 2 giliran.',
		zawakeEffectDesc_ph = 'Ang Hari ng Phoenix ay lumilipad pataas sa langit, nagpapalabas ng mga sinag ng init na parang sikat ng araw mula sa bibig, inaatake ang lahat ng mga kalaban, nagdudulot ng #C0xE69900#180% Physical Damage#C0x5B545B#+$(antas ng kasanayan*4*60)$#C0xF13B54#Physical Damage#C0x5B545B#, nagdadagdag ng isang layer ng <Holy Fire Burn> sa lahat ng mga kalaban sa loob ng 2 turn; ibinibigay ito sa isang kakampi maliban sa iyong sarili. (Pangunahing prayoridad) <Bird Welfare> (Espesyal na epekto, pagkatapos mamatay ay nagiging isang phoenix egg. Ang phoenix egg ay mawawasak pagkatapos tamaan ng 6 na beses. Kung hindi ito nasira, babangon ito sa susunod na round. Pagkatapos bumangon, 50% ng health at 30% ng galit ay mananatili) <Bird Blessing> Pagkatapos bumangon ng Phoenix King, 2 random na bayani mula sa koponan at hanggang 2 kakampi ang mabubuhay muli sa buong larangan; at ang <Holy Fire Barrier> ay idaragdag sa lahat ng mga kaibigang fire heroes sa loob ng 2 turn.',
		zawakeEffectDesc_ma = 'Raja Phoenix terbang ke langit, melepaskan pancaran panas seperti sinar matahari dari mulutnya, menyerang semua sasaran musuh, menyebabkan #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#+$(tahap kemahiran*4*60)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B#, menambahkan lapisan <Pembakaran Api Suci> pada semua sasaran musuh selama 2 giliran; memberikannya kepada seorang rakan kecuali diri anda sendiri. (Keutamaan tertinggi) <Kebajikan Burung> (Kesan khas, selepas mati akan berubah menjadi telur phoenix. Telur phoenix akan musnah selepas diserang 6 kali. Jika tidak dimusnahkan, ia akan bangkit pada pusingan berikutnya. Selepas kebangkitan, 50% darah dan 30% kemarahan akan dikekalkan) <Berkat Burung> Selepas Raja Phoenix bangkit, 2 wira rawak dari pasukan dan maksimum 2 rakan akan dihidupkan semula di seluruh medan; dan <Halangan Api Suci> akan ditambahkan pada semua wira api mesra selama 2 giliran.',
		zawakeEffectDesc_vn = 'Phượng Hoàng Vương bay lên trên bầu trời, từ miệng phóng ra những tia sáng nóng như ánh nắng, tấn công tất cả mục tiêu địch, gây #C0xE69900#180% Sát Thương Vật Lý#C0x5B545B#+$(cấp kỹ năng*4*60)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, thêm một lớp <Thánh Hỏa Đốt> cho tất cả mục tiêu địch trong 2 lượt; ban nó cho một đồng đội ngoại trừ chính bạn. (Ưu tiên hàng đầu) <Phúc lợi chim> (Hiệu ứng đặc biệt, sau khi chết sẽ biến thành trứng phượng. Trứng phượng sẽ bị phá hủy sau khi bị tấn công 6 lần. Nếu không bị tiêu diệt, nó sẽ hồi sinh sau vòng tiếp theo. Sau khi hồi sinh, 50% lượng máu và 30% tức giận sẽ được giữ lại) <Phước chim> Sau khi bản thân Phượng hoàng vương hồi sinh sẽ được thêm vào 2 ngẫu nhiên anh hùng của nhóm và tối đa 2 đồng đội sẽ được hồi sinh trên toàn sân; và <Holy Fire Barrier> sẽ được thêm vào tất cả các anh hùng lửa thân thiện trong 2 lượt.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '<Blessing for Birds> can only be triggered once on the field\n#F20# \n#F40##C0x5c9970#→<Blessing for Birds> After Phoenix King is resurrected, it will be applied to 2 random allies on the same side, and up to 2 teammates across the field will be revived; <Holy Fire Barrier> will also be granted to all friendly Fire heroes for 2 turns  ',
		zawakeSimpleDesc_en = '<Blessing for Birds> can only be triggered once on the field\n#F20# \n#F40##C0x5c9970#→<Blessing for Birds> After Phoenix King is resurrected, it will be applied to 2 random allies on the same side, and up to 2 teammates across the field will be revived; <Holy Fire Barrier> will also be granted to all friendly Fire heroes for 2 turns  ',
		zawakeSimpleDesc_th = '<พรแห่งนก> สามารถเปิดใช้งานได้เพียงครั้งเดียวในสนาม\n#F20# \n#F40##C0x5c9970#→<พรแห่งนก> หลังจากราชาฟีนิกซ์ฟื้นคืนชีพ จะถูกเพิ่มให้กับ 2 พันธมิตรสุ่มด้านเดียวกัน และสูงสุด 2 เพื่อนร่วมทีมในสนามจะฟื้นคืนชีพ; และจะมอบ <โล่เพลิงศักดิ์สิทธิ์> ให้กับฮีโร่ธาตุไฟฝ่ายเดียวกันทุกคนเป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = '<Berkat untuk Burung> hanya dapat diaktifkan satu kali di medan perang\n#F20# \n#F40##C0x5c9970#→<Berkat untuk Burung> Setelah Raja Phoenix dibangkitkan, efek ini akan diberikan ke 2 sekutu acak di sisi yang sama, dan maksimal 2 anggota tim di seluruh medan akan dibangkitkan; dan <Perisai Api Suci> akan ditambahkan selama 2 giliran ke semua hero elemen Api yang ramah  ',
		zawakeSimpleDesc_ph = '<Blessing para sa mga Ibon> ay maaari lamang i-activate isang beses sa field\n#F20# \n#F40##C0x5c9970#→<Blessing para sa mga Ibon> Matapos ma-revive si Phoenix King, ito ay mailalapat sa 2 random na kakampi sa parehong panig at hanggang 2 kakampi sa kabuuang field ay mare-revive; at <Banal na Apoy na Kalasag> ay idaragdag sa lahat ng Fire heroes ng kakampi sa loob ng 2 turn  ',
		zawakeSimpleDesc_ma = '<Berkat untuk Burung> hanya boleh diaktifkan sekali di atas medan',
		zawakeSimpleDesc_vn = '<Phúc lành cho chim> chỉ có thể được kích hoạt một lần trên sân\n#F20# \n#F40##C0x5c9970#→<Phúc lành cho chim> Sau khi bản thân Phượng hoàng vua được hồi sinh, nó sẽ được thêm vào 2 anh hùng ngẫu nhiên của một bên và tối đa 2 đồng đội sẽ được hồi sinh trên toàn sân; và <Holy Fire Barrier> sẽ được thêm vào trong 2 lượt cho tất cả các anh hùng lửa thân thiện.',
		upLvDesc = 'Fixed damage +240',
		upLvDesc_en = 'Fixed damage +240',
		upLvDesc_th = 'ดาเมจคงที่ +240',
		upLvDesc_in = 'Kerusakan tetap +240',
