	[12716] = {
		id = 12716,
		skillName_vn = 'Ho-Oh Nirvana',
		skillName_en = 'Ho-Oh Nirvana',
		skillName_th = 'โฮ-โอห์ เนอร์วานา',
		skillName_in = 'Ho-Oh Nirvana',
		skillName_ph = 'Ho-Oh Nirvana',
		skillName_ma = 'Ho-Oh Nirvana',
		skillName = 'Ho-Oh Nirvana',
		describe_vn = 'Sau khi chết, Niết-bàn sẽ tái sinh một lần. Sau khi hồi sinh, nó sẽ thừa hưởng lượng máu #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B#, trở lại trạng thái thịnh nộ tối đa, thêm một lớp [Thánh lửa đốt] cho tất cả mục tiêu của kẻ địch trong hai lượt và tăng vĩnh viễn 20% khả năng giảm sát thương chí mạng của bản thân và 2 lượt [Rào chắn lửa thánh]',
		describe_en = 'After death, Nirvana will be reincarnated once. Upon resurrection, it will inherit #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# health, return to maximum rage state, add a [Holy Burning Flame] layer to all enemy targets for two turns, and permanently increase its own critical damage reduction by 20% as well as gain [Holy Fire Barrier] for 2 turns.',
		describe_th = 'หลังจากตาย นิรันดร์จะเกิดใหม่อีกครั้งหนึ่ง เมื่อลืมตาขึ้นอีกครั้ง มันจะได้รับชีวิต #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# กลับสู่สถานะความโกรธสูงสุด เพิ่มชั้น [เปลวไฟศักดิ์สิทธิ์ลุกไหม้] ให้กับเป้าหมายศัตรูทั้งหมดเป็นเวลา 2 เทิร์น และเพิ่มความสามารถลดความเสียหายคริติคอลของตนเองถาวรอีก 20% พร้อมได้ [กำแพงไฟศักดิ์สิทธิ์] เป็นเวลา 2 เทิร์น',
		describe_in = 'Setelah mati, Nirwana akan bereinkarnasi sekali. Setelah bangkit, ia akan mewarisi #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# darah, kembali ke keadaan kemarahan maksimal, menambahkan satu lapisan [Api Suci Membakar] untuk semua target musuh selama dua giliran, dan meningkatkan pengurangan kerusakan kritisnya sendiri secara permanen sebesar 20% serta mendapatkan [Perisai Api Suci] selama 2 giliran.',
		describe_ph = 'Pagkatapos mamatay, muling isisilang ang Nirvana isang beses. Pagkabuhay muli, mamanahin nito ang #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# na buhay, babalik sa pinakamataas na estado ng galit, maglalagay ng isang layer ng [Banal na Apoy na Sumusunog] sa lahat ng target ng kalaban sa loob ng dalawang turn, at permanenteng tataasan ang sariling kakayahan sa pagbawas ng kritikal na pinsala ng 20% pati na rin magkakaroon ng [Banal na Araw na Pader] sa loob ng 2 turn.',
		describe_ma = 'Selepas mati, Nirvana akan dilahirkan semula sekali. Selepas kebangkitan, ia akan mewarisi #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# kesihatan, kembali ke keadaan kemarahan maksimum, menambah lapisan [Api Pembakaran Suci] untuk semua sasaran musuh selama dua pusingan, dan meningkatkan pengurangan kerosakan kritikal dirinya sebanyak 20% secara kekal serta memperoleh [Perisai Api Suci] selama 2 pusingan.',
		describe = 'After death, Nirvana will be reincarnated once. Upon resurrection, it will inherit #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# health, return to maximum rage state, add a [Holy Burning Flame] layer to all enemy targets for two turns, and permanently increase its own critical damage reduction by 20% as well as gain [Holy Fire Barrier] for 2 turns.',
		starEffect = __data_t__starEffect[12716],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi hiệu ứng Thánh Hỏa kích hoạt, sẽ hồi phục lại lượng máu tương ứng cho bản thân.',
		starEffectDesc = 'Additional effect: When the Sacred Flame effect activates, it will restore a corresponding amount of health to the user.',
		starEffectDesc_en = 'Additional effect: When the Sacred Flame effect activates, it will restore a corresponding amount of health to the user.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อเอฟเฟกต์เพลิงศักดิ์สิทธิ์ถูกเปิดใช้ จะฟื้นฟูพลังชีวิตที่สอดคล้องกลับให้กับตัวละครเอง',
		starEffectDesc_in = 'Efek tambahan: Saat efek Api Suci diaktifkan, akan mengembalikan sejumlah kesehatan yang sesuai kepada diri sendiri.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag na-activate ang epekto ng Banal na Apoy, magbabalik ito ng kaukulang dami ng buhay sa sarili.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila kesan Api Suci diaktifkan, ia akan memulihkan jumlah kesihatan yang sepadan kepada diri sendiri.',
		zawakeEffect = __data_t__zawakeEffect[12716],
		-- {79004, 1}
		zawakeEffectDesc = 'Additional effect: When #L1# Holy Flame Burn activates, it restores an equivalent amount of health to oneself, the additional effect of <#L1# Holy Flame Burn> increases: Holy Flame Burn comes with an 8% dual attack reduction on the target (maximum 3 stacks).',
		zawakeEffectDesc_en = 'Additional effect: When #L1# Holy Flame Burn activates, it restores an equivalent amount of health to oneself, the additional effect of <#L1# Holy Flame Burn> increases: Holy Flame Burn comes with an 8% dual attack reduction on the target (maximum 3 stacks).',
		zawakeEffectDesc_th = 'ผลเสริม: เมื่อ #L1# เปลวไฟศักดิ์สิทธิ์ลุกไหม้ทำงาน จะฟื้นฟูเลือดที่เท่ากันให้กับตนเอง ผลเสริมของ <#L1# เปลวไฟศักดิ์สิทธิ์ลุกไหม้> เพิ่มขึ้น: เปลวไฟศักดิ์สิทธิ์ลุกไหม้มาพร้อมกับการลดการโจมตีคู่ของเป้าหมาย 8% (สะสมได้สูงสุด 3 ชั้น).',
		zawakeEffectDesc_in = 'Efek tambahan: Ketika #L1# Pembakaran Api Suci aktif, akan memulihkan jumlah HP yang setara untuk diri sendiri, efek tambahan dari <#L1# Pembakaran Api Suci> meningkat: Pembakaran Api Suci disertai dengan pengurangan serangan ganda target sebesar 8% (maksimal 3 lapis tumpukan).',
		zawakeEffectDesc_ph = 'Karagdagang epekto: Kapag na-activate ang #L1# Holy Flame Burn, magre-restore ng katumbas na HP para sa sarili, tumataas ang karagdagang epekto ng <#L1# Holy Flame Burn>: Holy Flame Burn ay may kasamang pagbaba ng 8% dual attack ng target (maximum na 3 stack).',
		zawakeEffectDesc_ma = 'Kesan tambahan: Apabila #L1# Pembakaran Api Suci diaktifkan, akan memulihkan jumlah darah yang sama untuk diri sendiri, kesan tambahan <#L1# Pembakaran Api Suci> meningkat: Pembakaran Api Suci disertai pengurangan serangan berganda sasaran sebanyak 8% (maksimum 3 lapisan timbunan).',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: Khi Lửa thánh thiêu đốt kích hoạt, sẽ hồi phục lượng máu tương đương cho bản thân, hiệu ứng bổ sung của <Lửa thánh thiêu đốt> tăng: Lửa thánh thiêu đốt kèm theo giảm 8% công đôi của mục tiêu (tối đa cộng dồn 3 lớp)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#<Holy Fire Burning> additional effect: It now reduces the target\'s dual ATK by 8% (can stack up to 3 layers)',
		zawakeSimpleDesc_en = '#C0x5c9970#<Holy Fire Burning> additional effect: It now reduces the target\'s dual ATK by 8% (can stack up to 3 layers)',
		zawakeSimpleDesc_th = '#C0x5c9970#<เพลิงศักดิ์สิทธิ์แผดเผา> เพิ่มเอฟเฟกต์: ลดพลังโจมตีคู่ของเป้าหมาย 8% (สะสมได้สูงสุด 3 ชั้น)',
		zawakeSimpleDesc_in = '#C0x5c9970#<Api Suci Membakar> mendapat efek tambahan: Mengurangi 8% serangan ganda target (maks 3 lapis)',
		zawakeSimpleDesc_ph = '#C0x5c9970#<Banal na Apoy na Nasusunog> karagdagang epekto: Binabawasan ng 8% ang dobleng lakas ng target (hanggang 3 ulit na pagsasama)',
		zawakeSimpleDesc_ma = '#C0x5c9970#<Api Suci Membakar> kesan tambahan: Kurangkan 8% serangan berganda sasaran (maksimum 3 lapisan)',
		zawakeSimpleDesc_vn = '#C0x5c9970#<Thánh hỏa thiêu đốt> tăng thêm hiệu quả: Thánh hỏa thiêu đốt kèm theo giảm 8% công đôi của mục tiêu (tối đa cộng dồn 3 lớp)',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
