	[12911] = {
		id = 12911,
		skillName_vn = 'Độc tố',
		skillName_en = 'Poison',
		skillName_th = 'พิษ',
		skillName_in = 'Racun',
		skillName_ph = 'Lason',
		skillName_ma = 'Racun',
		skillName = 'Poison',
		describe_vn = 'Mộc Thủ Cung phun cành cây tấn công mục tiêu có lượng máu thấp nhất ở hàng sau của địch, gây ra#C0x3D8A99#80% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ sát thương#C0xF13B54#pháp thuật#C0x5B545B#, sau khi tấn công tăng 20% sát thương chí mạng cho bản thân, kéo dài 2 lượt',
		describe_en = 'The Wooden Hand Bow shoots a branch to attack the enemy with the lowest health in the back row, dealing 80% Magic Attack + $(skillLevel*4*24)$ magic damage. After the attack, it increases its own critical damage by 20% for 2 turns.',
		describe_th = 'ธนูมือไม้ยิงกิ่งไม้โจมตีเป้าหมายที่มีเลือดต่ำที่สุดในแถวหลังของศัตรู สร้างความเสียหายเวท 80% + $(skillLevel*4*24)$ หลังโจมตีเพิ่มความเสียCrit 20% เป็นเวลา 2 เทิร์น',
		describe_in = 'Busur Tangan Kayu menembakkan ranting untuk menyerang target dengan darah terendah di barisan belakang musuh, memberikan 80% Serangan Sihir + $(skillLevel*4*24)$ kerusakan sihir. Setelah menyerang, meningkatkan kerusakan kritis diri sebesar 20% selama 2 giliran.',
		describe_ph = 'Angkla ng Kahoy na Pana ay bumabara ng sanga para atakihin ang layuning may pinakamababang HP sa likurang hanay ng kalaban, na nagdudulot ng 80% Magic Attack + $(skillLevel*4*24)$ na magic damage. Pagkatapos ng atake, tumataas ng 20% ang sariling critical damage sa loob ng 2 turno.',
