		describe_ph = 'Inaatake ni Shifengyuan Yoruichi ang kalaban na may pinakababang HP sa likurang hanay, na nagdudulot ng #C0x3D8A99#560% Magical Damage#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# Magical Damage#C0x5B545B#, kasabay ng pagnakaw ng 20% ng attack at magic speed ng target, tumatagal ng 3 turn.',
		describe_ma = 'Shifengyuan Yoruichi menyerang sasaran musuh dengan HP terendah di barisan belakang, menyebabkan #C0x3D8A99#560% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# Kerosakan Magik#C0x5B545B#, sambil mencuri 20% serangan dan kelajuan magik sasaran, bertahan selama 3 pusingan.',
		describe = 'Shifengyuan Yoruichi attacks the enemy target with the lowest HP in the back row, dealing #C0x3D8A99#560% Magical Damage#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# Magical Damage#C0x5B545B#, while stealing 20% of the target\'s attack power and magic speed, lasting for 3 turns.',
		simDesc_vn = 'Shifengyuan Yoichi tấn công liên tiếp vào mục tiêu của kẻ địch và đánh cắp đòn tấn công phép thuật và tốc độ của mục tiêu.',
		simDesc_en = 'Shifengyuan Yoichi continuously attacks the enemy\'s target, stealing their magical attack and speed.',
		simDesc_th = 'ชิเฟิงหยวน โยอิจิ โจมตีเป้าหมายของศัตรูอย่างต่อเนื่องและขโมยพลังโจมตีเวทมนตร์และความเร็วของเป้าหมาย',
		simDesc_in = 'Shifengyuan Yoichi menyerang sasaran musuh secara berturut-turut dan mencuri serangan sihir serta kecepatan target.',
		simDesc_ph = 'Patuloy na ina-atake ni Shifengyuan Yoichi ang target ng kalaban at ninanakaw ang kanilang magic attack at bilis.',
		simDesc_ma = 'Shifengyuan Yoichi menyerang sasaran musuh secara berterusan dan mencuri serangan sihir serta kelajuan sasaran.',
		simDesc = 'Shifengyuan Yoichi continuously attacks the enemy\'s target, stealing their magical attack and speed.',
		starEffect = __data_t__starEffect[12933],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Cướp lấy sức tấn Công Phép thuật và tốc độ tăng thêm 5%, kỹ năng chí mạng trong trạng thái lén lút sẽ có thêm 25% hiệu ứng hút máu.',
		starEffectDesc = 'Enhance effects: Steal Magic Attack power and speed increased by 5%, critical skills in stealth state gain an additional 25% lifesteal effect.',
		starEffectDesc_en = 'Enhance effects: Steal Magic Attack power and speed increased by 5%, critical skills in stealth state gain an additional 25% lifesteal effect.',
