	[12936] = {
		id = 12936,
		skillName_vn = 'Nữ Miêu Bóng Đêm',
		skillName_en = 'Night Shadow Cat',
		skillName_th = 'แมวดำเงากลางคืน',
		skillName_in = 'Kucing Bayangan Malam',
		skillName_ph = 'Pusang Anino ng Gabi',
		skillName_ma = 'Kucing Bayang Malam',
		skillName = 'Night Shadow Cat',
		describe_vn = 'Là sát thủ hàng đầu, khi máu bản thân dưới #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B#, bản thân vào trạng thái ẩn thân trong 2 lượt (trong trạng thái ẩn thân không thể bị chọn, nhưng sẽ bị ảnh hưởng bởi sát thương diện rộng, sau khi kích hoạt sẽ hồi chiêu trong 3 lượt)',
		describe_en = 'As a top assassin, when your HP drops below #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B#, you enter a stealth state for 2 turns (while in stealth, you cannot be targeted, but you are still affected by area damage; after activation, the skill cooldown lasts for 3 turns).',
		describe_th = 'ในฐานะนักฆ่าชั้นนำ เมื่อเลือดของคุณต่ำกว่า #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# คุณจะเข้าสู่สถานะล่องหนเป็นเวลา 2 เทิร์น (ในสถานะล่องหนจะไม่สามารถถูกเลือกได้ แต่จะได้รับผลกระทบจากความเสียหายพื้นที่ หลังจากเปิดใช้งานจะมีเวลาคูลดาวน์ 3 เทิร์น)',
		describe_in = 'Sebagai pembunuh terbaik, ketika darah Anda di bawah #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B#, Anda masuk ke dalam keadaan tersembunyi selama 2 giliran (dalam keadaan tersembunyi tidak dapat dipilih, tetapi masih terpengaruh oleh kerusakan area; setelah aktivasi, cooldown berlangsung selama 3 giliran).',
		describe_ph = 'Bilang nangungunang mamamatay, kapag ang iyong HP ay bumaba sa ilalim ng #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B#, papasok ka sa stealth mode sa loob ng 2 turn (habang nasa stealth ay hindi ka maaaring mapili, ngunit maaapektuhan pa rin ng area damage; pagkatapos ma-activate, magkakaroon ng cooldown ng 3 turn).',
		describe_ma = 'Sebagai pembunuh utama, apabila darah anda berada di bawah #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B#, anda akan memasuki keadaan sembunyi selama 2 pusingan (dalam keadaan sembunyi tidak boleh dipilih, tetapi masih terkesan dengan kerosakan kawasan; selepas pengaktifan, tempoh penyejukan berlanjutan selama 3 pusingan).',
		describe = 'As a top assassin, when your HP drops below #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B#, you enter a stealth state for 2 turns (while in stealth, you cannot be targeted, but you are still affected by area damage; after activation, the skill cooldown lasts for 3 turns).',
		starEffect = __data_t__starEffect[12936],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Trong trạng thái lén lút, sát thương chí mạng tăng 25%, lần đầu tiên ở trạng thái lén lút sẽ nhận được một dấu hiệu lạnh lùng.',
		starEffectDesc = 'Enhance Effects: In stealth mode, critical damage increases by 25%. The first time in stealth mode, a cool sign will be received.',
		starEffectDesc_en = 'Enhance Effects: In stealth mode, critical damage increases by 25%. The first time in stealth mode, a cool sign will be received.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: ในสถานะลอบเร้น ความเสียหายคริติคอลเพิ่มขึ้น 25% ครั้งแรกในสถานะลอบเร้นจะได้รับสัญลักษณ์เย็นชา',
		starEffectDesc_in = 'Tingkatkan Efek: Dalam keadaan sembunyi, kerusakan kritis meningkat 25%. Pertama kali dalam keadaan sembunyi akan menerima tanda keren.',
		starEffectDesc_ph = 'Pahusayin ang mga Epekto: Sa estado ng stealth, tumataas ang kritikal na pinsala ng 25%. Sa unang pagkakataon sa estado ng stealth, makakatanggap ng isang malamig na tanda.',
		starEffectDesc_ma = 'Tingkatkan Kesan: Dalam keadaan sembunyi, kerosakan kritikal meningkat 25%. Kali pertama dalam keadaan sembunyi akan menerima tanda sejuk.',
		zawakeEffect = __data_t__zawakeEffect[12936],
		-- {79004}
		zawakeEffectDesc = 'When own health is lower than #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B#, enter <Stealth> state for 2 turns (Stealth: In stealth state cannot be targeted, will be affected by area damage, activates after 3 turns cooldown); when kill a target, gain <Cold>.',
		zawakeEffectDesc_en = 'When own health is lower than #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B#, enter <Stealth> state for 2 turns (Stealth: In stealth state cannot be targeted, will be affected by area damage, activates after 3 turns cooldown); when kill a target, gain <Cold>.',
		zawakeEffectDesc_th = 'เมื่อเลือดของตนเองต่ำกว่า #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B#, เข้าสู่สถานะ <ซ่อนตัว> 2 เทิร์น (ซ่อนตัว: ในสถานะซ่อนตัวจะไม่สามารถถูกเลือกเป้าหมาย, จะได้รับผลกระทบจากความเสียหายพื้นที่, เปิดใช้งานหลังคูลดาวน์ 3 เทิร์น); เมื่อฆ่าศัตรูได้รับ <ความเย็นชา>.',
		zawakeEffectDesc_in = 'Ketika darah sendiri kurang dari #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B#, memasuki status <Menyembunyi> selama 2 giliran (Menyembunyi: Dalam status menyembunyi tidak dapat dipilih, akan terpengaruh oleh damage area, aktif setelah cooldown 3 giliran); saat membunuh target, mendapatkan <Dingin>.',
		zawakeEffectDesc_ph = 'Kapag ang sariling HP ay mababa sa #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B#, pumapasok sa estado ng <Tago> ng 2 na turno (Tago: Sa estado ng tago ay hindi maaaring mapili, maaapektuhan ng area damage, aktibo pagkatapos ng 3 turn cooldown); kapag napatay ang target, nakakakuha ng <Malamig>.',
		zawakeEffectDesc_ma = 'Apabila darah sendiri kurang daripada #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B#, memasuki keadaan <Menyembunyi> selama 2 pusingan (Menyembunyi: Dalam keadaan menyembunyi tidak boleh dipilih, akan terjejas oleh kerosakan kawasan, aktif selepas cooldown 3 pusingan); apabila membunuh sasaran, memperoleh <Sejuk>.',
		zawakeEffectDesc_vn = 'Khi máu bản thân thấp hơn#C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B#, bản thân vào trạng thái <Ẩn nấp> 2 lượt (Ẩn nấp: Trong trạng thái ẩn nấp không thể bị chọn, sẽ bị ảnh hưởng bởi sát thương phạm vi, kích hoạt sau khi hồi chiêu 3 lượt); khi tiêu diệt mục tiêu, bản thân nhận <Lạnh lùng>',
		zawakeSimpleType = 1,
