	[13033] = {
		id = 13033,
		skillName_vn = 'EX Sóng Lửa Quyền',
		skillName_en = 'EX Fire Wave Fist',
		skillName_th = 'EX หมัดคลื่นไฟ',
		skillName_in = 'EX Tinju Gelombang Api',
		skillName_ph = 'EX Fire Wave Fist',
		skillName_ma = 'EX Penumbuk Gelombang Api',
		skillName = 'EX Fire Wave Fist',
		describe_vn = 'Akuma khơi dậy tinh thần chiến đấu và ra đòn nhanh chóng, phóng EX Searing Wave Fist lên không trung triệu hồi ngọn lửa tấn công một mục tiêu địch, gây #C0xE69900#640% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, hấp thụ đòn Sát Thương Vật Lý và phòng thủ vật lý của mục tiêu (tùy theo theo tỷ lệ 25% Sát Thương Vật Lý và 30% phòng thủ vật lý), kéo dài trong 2 hiệp; với 15% sát thương chí mạng và thêm 60% sát thương chí mạng khi tấn công mục tiêu đang cháy.',
		describe_en = 'Akuma ignites his fighting spirit and strikes swiftly, unleashing the EX Searing Wave Fist into the air to summon flames that attack an enemy target, dealing #C0xE69900#640% Physical Damage#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#. It absorbs the target\'s Physical Damage and physical defense (at a rate of 25% Physical Damage and 30% physical defense), lasting for 2 turns; with a 15% critical damage chance and an additional 60% critical damage when attacking burning targets.',
		describe_th = 'อาคุมะปลุกวิญญาณนักสู้และโจมตีอย่างรวดเร็ว ปล่อย EX Searing Wave Fist ขึ้นสู่ท้องฟ้า เรียกเปลวไฟโจมตีเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#640%#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ดูดซับความเสียหายทางกายภาพและการป้องกันทางกายภาพของเป้าหมาย (ตามอัตรา 25% ของความเสียหายทางกายภาพและ 30% ของการป้องกันทางกายภาพ) นาน 2 เทิร์น; โอกาสคริติคอล 15% และเพิ่มความเสียหายคริติคอลอีก 60% เมื่อโจมตีเป้าหมายที่กำลังติดไฟ',
		describe_in = 'Akuma membangkitkan semangat bertarungnya dan melancarkan serangan cepat, melepaskan EX Searing Wave Fist ke udara untuk memanggil api yang menyerang target musuh, memberikan #C0xE69900#640% Kerusakan Fisik#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#. Menyerap kerusakan fisik dan pertahanan fisik target (sesuai rasio 25% kerusakan fisik dan 30% pertahanan fisik), berlangsung selama 2 giliran; dengan 15% kerusakan kritis dan tambahan 60% kerusakan kritis saat menyerang target yang terbakar.',
		describe_ph = 'Pinukaw ni Akuma ang espiritu sa pakig-away ug dali nga milihok, gipagawas ang EX Searing Wave Fist sa kahanginan aron mohimo og kalayo nga mipaningkamot sa usa ka kaaway nga target, nagdala og #C0xE69900#640% Physical Damage#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#. Gikuha niini ang Physical Damage ug pisikal nga depensa sa target (sumala sa 25% Physical Damage ug 30% pisikal nga depensa), nga magdugay sulod sa 2 ka rounds; adunay 15% kritikal nga kadaut ug dugang 60% kritikal nga kadaut kung atakon ang target nga nagsunog.',
		describe_ma = 'Akuma membangkitkan semangat berperang dan menyerang dengan cepat, melancarkan EX Searing Wave Fist ke udara untuk memanggil api yang menyerang sasaran musuh, memberikan #C0xE69900#640% Kerosakan Fizikal#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Menyedut kerosakan fizikal dan pertahanan fizikal sasaran (mengikut kadar 25% kerosakan fizikal dan 30% pertahanan fizikal), berlangsung selama 2 pusingan; dengan 15% kerosakan kritikal dan tambahan 60% kerosakan kritikal apabila menyerang sasaran yang terbakar.',
		describe = 'Akuma ignites his fighting spirit and strikes swiftly, unleashing the EX Searing Wave Fist into the air to summon flames that attack an enemy target, dealing #C0xE69900#640% Physical Damage#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#. It absorbs the target\'s Physical Damage and physical defense (at a rate of 25% Physical Damage and 30% physical defense), lasting for 2 turns; with a 15% critical damage chance and an additional 60% critical damage when attacking burning targets.',
		simDesc_vn = 'Akuma khơi dậy tinh thần chiến đấu và ra đòn nhanh chóng, phóng ra EX Searing Wave Fist trong không trung triệu hồi ngọn lửa tấn công một mục tiêu kẻ địch, hấp thụ đòn tấn công vật lý và phòng thủ vật lý của mục tiêu. Khi tấn công mục tiêu đang cháy, anh ta sẽ tăng thêm sát thương chí mạng và sát thương chí mạng của chính mình.',
		simDesc_en = 'Akuma awakens his fighting spirit and strikes swiftly, unleashing the EX Searing Wave Fist midair to summon flames that attack a single enemy target, absorbing the target\'s physical attacks and defenses. When attacking a burning target, he increases his critical damage and critical hit rate.',
		simDesc_th = 'อาคุมะปลุกจิตวิญญาณนักสู้และโจมตีอย่างรวดเร็ว ปล่อย EX Searing Wave Fist ในอากาศเพื่อเรียกเปลวไฟโจมตีกลุ่มศัตรูเป้าหมายหนึ่ง ดูดซับการโจมตีทางกายภาพและการป้องกันของเป้าหมาย เมื่อโจมตีเป้าหมายที่กำลังลุกไหม้ เขาจะเพิ่มความเสียหายคริติคอลและอัตราคริติคอลของตนเอง',
		simDesc_in = 'Akuma membangkitkan semangat bertarungnya dan menyerang dengan cepat, melepaskan EX Searing Wave Fist di udara yang memanggil api untuk menyerang satu target musuh, menyerap serangan fisik dan pertahanan fisik target. Saat menyerang target yang terbakar, ia meningkatkan kerusakan kritis dan tingkat serangan kritisnya sendiri.',
		simDesc_ph = 'Binubuo ni Akuma ang kanyang diwa ng pakikipaglaban at mabilis na umatake, nagpapalabas ng EX Searing Wave Fist sa himpapawid na nagpapatawag ng apoy upang atakihin ang isang target na kalaban, sumisipsip ng pisikal na pag-atake at pisikal na depensa ng target. Kapag umatake sa naglalagablab na target, pinapataas niya ang kanyang kritikal na pinsala at rate ng kritikal na tama.',
		simDesc_ma = 'Akuma membangkitkan semangat bertarung dan menyerang dengan pantas, melepaskan EX Searing Wave Fist di udara yang memanggil api menyerang satu sasaran musuh, menyerap serangan fizikal dan pertahanan fizikal sasaran. Ketika menyerang sasaran yang terbakar, dia meningkatkan kerosakan kritikal dan kadar serangan kritikalnya sendiri.',
		simDesc = 'Akuma awakens his fighting spirit and strikes swiftly, unleashing the EX Searing Wave Fist midair to summon flames that attack a single enemy target, absorbing the target\'s physical attacks and defenses. When attacking a burning target, he increases his critical damage and critical hit rate.',
		starEffect = __data_t__starEffect[13033],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Gây thêm 30% sát thương chí mạng, khi tấn công mục tiêu đang bị cháy sẽ có thêm 80% sát thương chí mạng.',
		starEffectDesc = 'Enhance effect: Deals 30% more critical damage; when attacking targets that are burning, deals an additional 80% critical damage.',
		starEffectDesc_en = 'Enhance effect: Deals 30% more critical damage; when attacking targets that are burning, deals an additional 80% critical damage.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: สร้างความเสียหายคริติคอลเพิ่มขึ้น 30% เมื่อโจมตีเป้าหมายที่กำลังถูกเผาไหม้ จะได้รับความเสียหายคริติคอลเพิ่มขึ้นอีก 80%',
		starEffectDesc_in = 'Tingkatkan efek: Memberikan 30% kerusakan kritis tambahan, saat menyerang target yang terbakar akan memberikan 80% kerusakan kritis tambahan.',
		starEffectDesc_ph = 'Palakasin ang epekto: Nagdudulot ng 30% dagdag sa kritikal na pinsala; kapag inaatake ang target na nasusunog, nagdudulot ng karagdagang 80% kritikal na pinsala.',
		starEffectDesc_ma = 'Perkuat kesan: Menyebabkan 30% kerosakan kritikal tambahan, apabila menyerang sasaran yang sedang terbakar akan menerima 80% kerosakan kritikal tambahan.',
		zawakeEffect = __data_t__zawakeEffect[13033],
		-- {79003}
		zawakeEffectDesc = 'Akuma ignites fighting spirit and attacks swiftly, launching EX Searing Wave Fist in mid-air to summon flames attacking an enemy target, dealing #C0xE69900#640% Physical Damage#C0x5B545B#+$(skillLevel*4*75)$#C0xF 13B54#Physical Damage#C0x5B545B#, absorbing the target\'s Physical Damage and physical defense (according to 25% Physical Damage and 30% physical defense), lasting for 2 turns; with 15% critical damage, plus 30%% critical damage and 60% critical damage when attacking a burning target.',
		zawakeEffectDesc_en = 'Akuma ignites fighting spirit and attacks swiftly, launching EX Searing Wave Fist in mid-air to summon flames attacking an enemy target, dealing #C0xE69900#640% Physical Damage#C0x5B545B#+$(skillLevel*4*75)$#C0xF 13B54#Physical Damage#C0x5B545B#, absorbing the target\'s Physical Damage and physical defense (according to 25% Physical Damage and 30% physical defense), lasting for 2 turns; with 15% critical damage, plus 30%% critical damage and 60% critical damage when attacking a burning target.',
		zawakeEffectDesc_th = 'Akuma ปลุกจิตวิญญาณการต่อสู้และโจมตีอย่างรวดเร็ว ยิง EX Searing Wave Fist ในอากาศเพื่อเรียกเปลวไฟโจมตีเป้าหมายศัตรู สร้างความเสียหาย #C0xE69900#640% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*75)$#C0xF 13B54#ความเสียหายทางกายภาพ#C0x5B545B# ดูดซับความเสียหายทางกายภาพและการป้องกันทางกายภาพของเป้าหมาย (ขึ้นอยู่กับ 25% ความเสียหายทางกายภาพและ 30% การป้องกันทางกายภาพ) ต่อเนื่องเป็นเวลา 2 เทิร์น; พร้อมด้วยความเสียหายคริติคอล 15% เพิ่มเติม 30%% ความเสียหายคริติคอล และ 60% ความเสียหายคริติคอลเมื่อโจมตีเป้าหมายที่กำลังถูกไฟเผา',
		zawakeEffectDesc_in = 'Akuma membangkitkan semangat berjuang dan menyerang dengan cepat, meluncurkan EX Searing Wave Fist di udara untuk memanggil api yang menyerang satu target musuh, memberikan #C0xE69900#640% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*75)$#C0xF 13B54#Kerusakan Fisik#C0x5B545B#, menyerap Kerusakan Fisik dan pertahanan fisik target (sesuai dengan 25% Kerusakan Fisik dan 30% pertahanan fisik), berlangsung selama 2 giliran; dengan 15% kerusakan kritis, ditambah 30%% kerusakan kritis dan 60% kerusakan kritis saat menyerang target yang terbakar.',
		zawakeEffectDesc_ph = 'Ginising ni Akuma ang espiritu ng pakikipaglaban at mabilis na umaatake, nagpapalabas ng EX Searing Wave Fist sa hangin na nagtatawag ng apoy para atakihin ang isang kalaban, na nagdudulot ng #C0xE69900#640% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*75)$#C0xF 13B54#Pisikal na Pinsala#C0x5B545B#, sumisipsip ng Pisikal na Pinsala at pisikal na depensa ng target (ayon sa 25% Pisikal na Pinsala at 30% pisikal na depensa), tumatagal ng 2 turn; may 15% kritikal na pinsala, dagdag pa ang 30%% kritikal na pinsala at 60% kritikal na pinsala kapag inaatake ang nasusunog na target.',
		zawakeEffectDesc_ma = 'Akuma membangkitkan semangat berjuang dan menyerang dengan pantas, melancarkan EX Searing Wave Fist di udara untuk memanggil api yang menyerang satu sasaran musuh, memberikan #C0xE69900#640% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*75)$#C0xF 13B54#Kerosakan Fizikal#C0x5B545B#, menyerap Kerosakan Fizikal dan pertahanan fizikal sasaran (menurut 25% Kerosakan Fizikal dan 30% pertahanan fizikal), berlangsung selama 2 pusingan; dengan 15% kerosakan kritikal, ditambah 30%% kerosakan kritikal dan 60% kerosakan kritikal apabila menyerang sasaran yang terbakar.',
		zawakeEffectDesc_vn = 'Akuma khơi dậy tinh thần chiến đấu và tấn công nhanh chóng, phóng EX Searing Wave Fist trong không trung triệu hồi ngọn lửa tấn công một mục tiêu địch, gây #C0xE69900#640% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*75)$#C0xF 13B54#Sát Thương Vật Lý#C0x5B545B#, hấp thụ đòn Sát Thương Vật Lý và phòng thủ vật lý của mục tiêu (tùy theo theo tỷ lệ 25% Sát Thương Vật Lý và 30% phòng thủ vật lý), kéo dài trong 2 hiệp; với 15% sát thương chí mạng, cộng thêm 30%% sát thương chí mạng và 60% sát thương chí mạng khi tấn công mục tiêu bị đốt cháy.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'When attacking a burning target, add 60% Critical DMG#F20# #F40##C0x5c9970#→When attacking a burning target, add 30% Crit Rate and 60% Critical DMG  ',
		zawakeSimpleDesc_en = 'When attacking a burning target, add 60% Critical DMG#F20# #F40##C0x5c9970#→When attacking a burning target, add 30% Crit Rate and 60% Critical DMG  ',
		zawakeSimpleDesc_th = 'เมื่อโจมตีเป้าหมายที่ติดไฟ เพิ่ม 60% ดาเมจคริติคอล#F20# #F40##C0x5c9970#→เมื่อโจมตีเป้าหมายที่ติดไฟ เพิ่มคริติคอล 30% และดาเมจคริติคอล 60%',
		zawakeSimpleDesc_in = 'Saat menyerang target yang terbakar, tambahkan 60% Critical DMG#F20# #F40##C0x5c9970#→Saat menyerang target yang terbakar, tambahkan 30% Crit Rate dan 60% Critical DMG  ',
		zawakeSimpleDesc_ph = 'Kapag umatake sa target na nasusunog, dagdag 60% Critical DMG#F20# #F40##C0x5c9970#→Kapag umatake sa target na nasusunog, dagdag 30% Crit Rate at 60% Critical DMG  ',
		zawakeSimpleDesc_ma = 'Apabila menyerang sasaran yang terbakar, tambah 60% Kerosakan Kritikal#F20# #F40##C0x5c9970#→Apabila menyerang sasaran yang terbakar, tambah 30% Kritikal dan 60% Kerosakan Kritikal  ',
		zawakeSimpleDesc_vn = 'Khi tấn công mục tiêu bị đốt cháy, thêm 60% sát thương chí mạng#F20# #F40##C0x5c9970#→Khi tấn công mục tiêu bị đốt cháy, thêm 30% chí mạng và 60% sát thương chí mạng',
