	[13143] = {
		id = 13143,
		skillName_vn = 'Bão bùn',
		skillName_en = 'Rainstorm',
		skillName_th = 'พายุฝน',
		skillName_in = 'Badai hujan',
		skillName_ph = 'Bagyo ng ulan',
		skillName_ma = 'Ribut hujan',
		skillName = 'Rainstorm',
		describe_vn = 'Siêu quái vật đầm lầy vung cây búa khổng lồ của mình để khuấy động một cơn bão bùn tấn công tất cả các mục tiêu của kẻ thù, gây #C0xE69900#200% Sát Thương Vật Lý #C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, đồng thời thêm [Mud Bomb] lên tất cả mục tiêu trong 2 lượt ( Mud Bomb: Hiệu ứng tiêu cực, khi được gắn vào sẽ giảm sát thương tốc độ của mục tiêu tăng 15%. Sau khi trúng đòn một lần, quả bom sẽ phát nổ và gây #C0xE69900#100% Sát Thương Vật Lý cho mục tiêu.',
		describe_en = 'The swamp super monster swings its giant hammer to stir up a mud storm, attacking all enemy targets, dealing #C0xE69900#200% Physical Damage #C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# Physical Damage #C0x5B545B#, and simultaneously applies [Mud Bomb] to all targets for 2 turns (Mud Bomb: A debuff that reduces the target\'s damage and speed by 15%. After being hit once, the bomb explodes and deals #C0xE69900#100% Physical Damage to the target.)',
		describe_th = 'ปีศาจบึงยักษ์แกว่งค้อนใหญ่ของมันเพื่อก่อพายุโคลนโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายทางกายภาพ #C0xE69900#200% #C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# และพร้อมกันนั้นยังเพิ่ม [Mud Bomb] ให้กับเป้าหมายทั้งหมดเป็นเวลา 2 เทิร์น (Mud Bomb: ผลเสียลดความเสียหายและความเร็วของเป้าหมายลง 15% เมื่อถูกโจมตีครั้งหนึ่ง จะระเบิดและสร้างความเสียหายทางกายภาพ #C0xE69900#100% แก่เป้าหมาย)',
		describe_in = 'Monster rawa super mengayunkan palu raksasanya untuk mengguncang badai lumpur, menyerang semua target musuh, memberikan #C0xE69900#200% Kerusakan Fisik #C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#, sekaligus menambahkan [Mud Bomb] ke semua target selama 2 giliran (Mud Bomb: Efek negatif yang mengurangi kerusakan dan kecepatan target sebesar 15%. Setelah terkena serangan sekali, bom akan meledak dan memberikan #C0xE69900#100% Kerusakan Fisik pada target.)',
		describe_ph = 'Ang super halimaw sa latian ay hinahampas ang kanyang malaking martilyo upang pukawin ang isang bagyong putik na umaatake sa lahat ng kaaway, na nagdudulot ng #C0xE69900#200% Pisikal na Danyos #C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# Pisikal na Danyos #C0x5B545B#, kasabay ng paglalagay ng [Mud Bomb] sa lahat ng target sa loob ng 2 turno (Mud Bomb: Isang negatibong epekto na nagpapababa sa danyos at bilis ng target ng 15%. Kapag tinamaan nang isang beses, sumabog ang bomba at nagdudulot ng #C0xE69900#100% Pisikal na Danyos sa target.)',
		describe_ma = 'Raksasa rawa mega menghayunkan tukul gergasi untuk mengacaukan ribut lumpur menyerang semua sasaran musuh, menyebabkan #C0xE69900#200% Kerosakan Fizikal #C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, serta menambah [Mud Bomb] ke semua sasaran selama 2 pusingan (Mud Bomb: Kesan negatif yang mengurangkan kerosakan dan kelajuan sasaran sebanyak 15%. Setelah terkena satu serangan, bom akan meletup dan menyebabkan #C0xE69900#100% Kerosakan Fizikal ke sasaran.)',
		describe = 'The swamp super monster swings its giant hammer to stir up a mud storm, attacking all enemy targets, dealing #C0xE69900#200% Physical Damage #C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# Physical Damage #C0x5B545B#, and simultaneously applies [Mud Bomb] to all targets for 2 turns (Mud Bomb: A debuff that reduces the target\'s damage and speed by 15%. After being hit once, the bomb explodes and deals #C0xE69900#100% Physical Damage to the target.)',
		simDesc_vn = 'Swampert triệu hồi một làn sóng bùn để tấn công một mục tiêu địch, thêm hiệu ứng bom bùn vào mục tiêu.',
		simDesc_en = 'Swampert summons a wave of mud to attack an enemy target, adding a mud bomb effect to the target.',
		simDesc_th = 'Swampert เรียกคลื่นโคลนโจมตีเป้าหมายศัตรู พร้อมเพิ่มเอฟเฟกต์ระเบิดโคลนให้กับเป้าหมาย',
		simDesc_in = 'Swampert memanggil gelombang lumpur untuk menyerang target musuh, menambahkan efek bom lumpur ke target.',
