	[13146] = {
		id = 13146,
		skillName_vn = 'Dòng chảy đục',
		skillName_en = 'Murky Stream',
		skillName_th = 'ลำธารขุ่น',
		skillName_in = 'Aliran Keruh',
		skillName_ph = 'Maulap na Agos',
		skillName_ma = 'Aliran Keruh',
		skillName = 'Murky Stream',
		describe_vn = 'Trong trận chiến: Cải thiện #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# tỷ lệ chống tội phạm của chính mình; HP của bản thân đạt 75%/50%/25 lần đầu tiên. % bên dưới lần lượt xua tan 1/2/3 hiệu ứng tiêu cực của bản thân và tăng khả năng giảm sát thương của bản thân thêm 40% (không thể xua tan), kéo dài trong 1 hiệp; khi bản thân bị tổn thương bởi các kỹ năng không quan trọng, mạng sống của người bị thiệt hại sẽ được phục hồi tương ứng với lượng máu đã mất của bản thân.',
		describe_en = 'In battle: Increase your own crime resistance by #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#; when your HP reaches 75%/50%/25 for the first time, dispel 1/2/3 negative effects from yourself respectively and increase your damage reduction by 40% (cannot be dispelled), lasting for 1 turn; when you are damaged by non-critical skills, you will recover health equal to your own lost HP.',
		describe_th = 'ในระหว่างการต่อสู้: เพิ่มอัตราต้านอาชญากรรมของตัวเอง #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#; เมื่อ HP ของตัวเองลดลงถึง 75%/50%/25% เป็นครั้งแรก จะขจัดสถานะลบ 1/2/3 อย่างตามลำดับ และเพิ่มความสามารถลดความเสียหายของตัวเองอีก 40% (ไม่สามารถขจัดได้) เป็นระยะเวลา 1 เทิร์น; เมื่อได้รับความเสียหายจากสกิลที่ไม่สำคัญ ชีวิตของผู้ที่ได้รับความเสียหายจะฟื้นฟูเท่ากับพลังชีวิตที่สูญเสียไปของตัวเอง',
		describe_in = 'Dalam pertarungan: Tingkatkan resistensi kejahatan diri sendiri sebesar #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#; saat HP diri mencapai 75%/50%/25% untuk pertama kalinya, hilangkan 1/2/3 efek negatif dari diri sendiri secara berturut-turut dan tingkatkan kemampuan pengurangan kerusakan diri sendiri sebesar 40% (tidak dapat dihilangkan), berlangsung selama 1 giliran; saat diri sendiri terluka oleh skill non-kritis, nyawa yang hilang akan dipulihkan sesuai dengan jumlah HP yang hilang sendiri.',
		describe_ph = 'Sa laban: Pinahusay ang sariling rate ng resistance sa krimen ng #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#; kapag ang HP ng sarili ay umabot ng 75%/50%/25% sa unang pagkakataon, puwersahang alisin ang 1/2/3 na negatibong epekto mula sa sarili ayon sa pagkakasunod at dagdagan ang kakayahang bawasan ang pinsala ng sarili ng 40% (hindi mabubura), tumagal ng 1 turn; kapag nasaktan ng mga hindi kritikal na kasanayan, ang buhay ng nasugatang tao ay babalik na katumbas ng nawalang HP ng sarili.',
		describe_ma = 'Dalam pertarungan: Tingkatkan kadar ketahanan jenayah diri sendiri sebanyak #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#; apabila HP diri mencapai 75%/50%/25% buat kali pertama, hilangkan 1/2/3 kesan negatif daripada diri sendiri secara berperingkat dan tingkatkan keupayaan pengurangan kerosakan diri sendiri sebanyak 40% (tidak boleh dihilangkan), bertahan selama 1 giliran; apabila diri sendiri mengalami kecederaan daripada kemahiran yang tidak penting, nyawa yang hilang akan dipulihkan mengikut jumlah darah yang hilang sendiri.',
		describe = 'In battle: Increase your own crime resistance by #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#; when your HP reaches 75%/50%/25 for the first time, dispel 1/2/3 negative effects from yourself respectively and increase your damage reduction by 40% (cannot be dispelled), lasting for 1 turn; when you are damaged by non-critical skills, you will recover health equal to your own lost HP.',
		starEffect = __data_t__starEffect[13146],
		-- {8}
		starEffectDesc_vn = 'Hiệu quả bổ sung: Khi lượng máu của bản thân lần lượt giảm xuống dưới 75%, 50% và 25%, sẽ nhận thêm 30% khả năng kháng bạo kích (hiệu ứng không thể bị xóa, có thể cộng dồn), kéo dài trong 2 lượt.',
		starEffectDesc = 'Additional effect: When your HP gradually drops below 75%, 50%, and 25%, you gain an extra 30% critical resistance (#effect cannot be removed, stackable#), lasting for 2 turns.',
