	[13943] = {
		id = 13943,
		skillName_vn = 'Thiên Luân Thập Tự Kiếm',
		skillName_en = 'Heavenly Wheel Cross Sword',
		skillName_th = 'ดาบแห่งวงล้อสวรรค์กากบาท',
		skillName_in = 'Pedang Salib Roda Surgawi',
		skillName_ph = 'Langit na Roda na Krus na Espada',
		skillName_ma = 'Pedang Salib Roda Syurga',
		skillName = 'Heavenly Wheel Cross Sword',
		describe_vn = 'Erza di chuyển với tốc độ cao và sử dụng Thiên Luân Thập Tự Kiếm để đánh lén mục tiêu của kẻ địch với đòn tấn công cao nhất. Có 70% khả năng khiến mục tiêu [Bối rối] trong 1 lượt và gây ra #C0xE69900#530% Sát Thương Vật Lý #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#. Nếu nhầm lẫn thành công, nó sẽ không thể nhận được hiệu ứng buff trong 3 lượt.',
		describe_en = 'Erza moves at high speed and uses Heavenly Wheel Cross Sword to ambush the enemy\'s target with the highest attack. There is a 70% chance to cause the target to be [Confused] for 1 turn and deal #C0xE69900#530% Physical Damage #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#. If confused successfully, the target will not be able to receive buff effects for 3 turns.',
		describe_th = 'เอิร์ซ่าเคลื่อนที่ด้วยความเร็วสูงและใช้ดาบครอสวีลเทพเพื่อโจมตีเป้าหมายของศัตรูด้วยการโจมตีสูงสุด มีโอกาส 70% ที่จะทำให้เป้าหมาย [สับสน] เป็นเวลา 1 เทิร์น และสร้างความเสียหายทางกายภาพ #C0xE69900#530% #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# หากสับสนสำเร็จ จะไม่สามารถรับเอฟเฟกต์บัฟได้นาน 3 เทิร์น',
		describe_in = 'Erza bergerak dengan kecepatan tinggi dan menggunakan Pedang Salib Roda Surgawi untuk menyerang secara diam-diam target musuh dengan serangan tertinggi. Ada kemungkinan 70% menyebabkan target menjadi [Bingung] selama 1 giliran dan memberikan #C0xE69900#530% Kerusakan Fisik #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#. Jika berhasil membuat bingung, target tidak dapat menerima efek buff selama 3 giliran.',
		describe_ph = 'Si Erza ay mabilis kumilos at gumagamit ng Heavenly Wheel Cross Sword upang lihim na atakihin ang pinakamataas na target ng kalaban. May 70% na tsansa na magdulot sa target ng [Nalilito] sa loob ng 1 turn at magdulot ng #C0xE69900#530% Physical Damage #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#. Kapag nalito ang target, hindi ito makakatanggap ng buff effects sa loob ng 3 turn.',
		describe_ma = 'Erza bergerak dengan kelajuan tinggi dan menggunakan Pedang Salib Roda Syurga untuk menyerang secara mengejut sasaran musuh dengan serangan tertinggi. Terdapat 70% kemungkinan menyebabkan sasaran menjadi [Keliru] selama 1 pusingan dan menyebabkan #C0xE69900#530% Kerosakan Fizikal #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Jika keliru berjaya, sasaran tidak dapat menerima efek buff selama 3 pusingan.',
		describe = 'Erza moves at high speed and uses Heavenly Wheel Cross Sword to ambush the enemy\'s target with the highest attack. There is a 70% chance to cause the target to be [Confused] for 1 turn and deal #C0xE69900#530% Physical Damage #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#. If confused successfully, the target will not be able to receive buff effects for 3 turns.',
		simDesc_vn = 'Erza di chuyển với tốc độ cao và sử dụng Thiên Luân Thập Tự Kiếm để đánh lén mục tiêu của kẻ địch với đòn tấn công cao nhất. Có khả năng gây nhầm lẫn cho mục tiêu. Nếu trúng sẽ không thể nhận được hiệu ứng buff.',
		simDesc_en = 'Erza moves at high speed and uses the Heavenly Wheel Cross Sword to stealthily strike enemy targets with maximum attack power. It has the potential to confuse the target. If it hits, the target cannot receive buff effects.',
		simDesc_th = 'เออร์ซ่าเคลื่อนที่ด้วยความเร็วสูงและใช้ดาบกางเขนล้อสวรรค์โจมตีศัตรูอย่างลับๆ ด้วยพลังโจมตีสูงสุด มีโอกาสทำให้เป้าหมายสับสน หากโดนจะไม่สามารถรับบัฟได้',
		simDesc_in = 'Erza bergerak dengan kecepatan tinggi dan menggunakan Pedang Salib Roda Surgawi untuk menyerang target musuh secara diam-diam dengan serangan tertinggi. Memiliki kemungkinan membingungkan target. Jika mengenai, target tidak dapat menerima efek buff.',
		simDesc_ph = 'Si Erza ayaw kumilos nang mabilis at gumamit ng Heavenly Wheel Cross Sword upang lihim na atakihin ang target ng kalaban gamit ang pinakamataas na lakas ng atake. May kakayahang lituhin ang target. Kapag tumama, hindi makakatanggap ng buff effect ang target.',
		simDesc_ma = 'Erza bergerak dengan kelajuan tinggi dan menggunakan Pedang Salib Roda Syurga untuk menyerang secara senyap sasaran musuh dengan serangan tertinggi. Mempunyai kemampuan untuk mengelirukan sasaran. Jika terkena, sasaran tidak dapat menerima kesan buff.',
		simDesc = 'Erza moves at high speed and uses the Heavenly Wheel Cross Sword to stealthily strike enemy targets with maximum attack power. It has the potential to confuse the target. If it hits, the target cannot receive buff effects.',
		starEffect = __data_t__starEffect[13943],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Tỷ lệ gây rối tăng thêm 15%, sau khi sử dụng kỹ năng chí mạng sẽ gây thêm 30% sát thương thật cho tất cả các mục tiêu trên sân đang bị kiểm soát.',
		starEffectDesc = 'Additional Effect: #mã màu# The chance to cause disruption increases by 15%. After using a critical skill, deals an additional 30% true damage to all controlled targets on the field. #F x# #L x#',
		starEffectDesc_en = 'Additional Effect: #mã màu# The chance to cause disruption increases by 15%. After using a critical skill, deals an additional 30% true damage to all controlled targets on the field. #F x# #L x#',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เพิ่มโอกาสสร้างสถานะ [สับสน] ขึ้นอีก 15% และหลังใช้ท่าไม้ตาย จะสร้างความเสียหายจริงเพิ่มเติม 30% ของความเสียหายจากครั้งนี้แก่เป้าหมายทั้งหมดในสนามที่มีสถานะควบคุม',
		starEffectDesc_in = 'Additional Effect: #mã màu# Peluang mengganggu meningkat sebesar 15%. Setelah menggunakan skill kritis, memberikan tambahan 30% kerusakan nyata kepada semua target yang dikendalikan di medan pertempuran. #F x# #L x#',
		starEffectDesc_ph = 'Additional Effect: #mã màu# Tumataas ng 15% ang tsansa ng pagkagulo. Pagkatapos gamitin ang critical skill, magdudulot ng karagdagang 30% totoong pinsala sa lahat ng mga kontroladong target sa larangan. #F x# #L x#',
		starEffectDesc_ma = 'Additional Effect: #mã màu# Kadar gangguan meningkat sebanyak 15%. Selepas menggunakan kemahiran kritikal, memberi tambahan 30% kerosakan sebenar kepada semua sasaran yang dikawal di medan. #F x# #L x#',
		zawakeEffect = __data_t__zawakeEffect[13943],
