	[13963] = {
		id = 13963,
		skillName_vn = 'Bà phù thủy bên này bờ',
		skillName_en = 'The witch on this shore',
		skillName_th = 'แม่มดที่ฝั่งนี้',
		skillName_in = 'Penyihir di tepi ini',
		skillName_ph = 'Ang bruha sa baybay na ito',
		skillName_ma = 'Ahli sihir di tepi ini',
		skillName = 'The witch on this shore',
		describe_vn = 'Ngọn lửa của quỷ giải phóng năng lượng ma quỷ, biến thành phù thủy và rơi về phía mục tiêu ở hàng sau của kẻ địch, gây ra #C0x3D8A99#350% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, mục tiêu sẽ không thể nhận được hiệu ứng buff trong 2 hiệp và sẽ có một 40% khả năng [Bùa mê] mục tiêu ở hàng sau trong 1 lượt, và sau đó một mục tiêu địch ngẫu nhiên bị [Bùa mê] ngoại trừ mục tiêu chính sẽ ngay lập tức tấn công một lần',
		describe_en = 'The devil\'s flame unleashes demonic energy, transforming into a witch and descending upon the enemy\'s backline target, dealing #C0x3D8A99#350% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magic Damage#C0x5B545B#. The target cannot receive buff effects for 2 turns and has a 40% chance to be [Charmed] for 1 turn. Then, a random enemy (excluding the main target) will be [Charmed] and immediately perform one attack.',
		describe_th = 'เปลวไฟปีศาจปลดปล่อยพลังปีศาจ แปลงร่างเป็นแม่มดและพุ่งตรงไปยังเป้าหมายที่แถวหลังของศัตรู ทำความเสียหายเวทย์ #C0x3D8A99#350%#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# ความเสียหายเวทย์#C0x5B545B# เป้าหมายจะไม่สามารถรับบัฟได้เป็นเวลา 2 เทิร์น และมีโอกาส 40% ที่จะถูก [เสน่ห์] ใน 1 เทิร์น จากนั้นศัตรูแบบสุ่มหนึ่งตัว (ยกเว้นเป้าหมายหลัก) จะถูก [เสน่ห์] และโจมตีทันทีหนึ่งครั้ง',
		describe_in = 'Api iblis melepaskan energi iblis, berubah menjadi penyihir dan jatuh ke target di barisan belakang musuh, menyebabkan #C0x3D8A99#350% Damage Sihir#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Damage Sihir#C0x5B545B#. Target tidak dapat menerima efek buff selama 2 giliran dan memiliki peluang 40% untuk [Terpesona] selama 1 giliran. Kemudian, satu musuh acak (kecuali target utama) akan [Terpesona] dan langsung menyerang sekali.',
		describe_ph = 'Ang apoy ng demonyo ay nagpapalaya ng enerhiyang demonyo, nagiging isang mangkukulam at bumabagsak sa target sa likurang hanay ng kalaban, nagdudulot ng #C0x3D8A99#350% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magic Damage#C0x5B545B#. Ang target ay hindi makakatanggap ng anumang buff effect sa loob ng 2 na turn at may 40% na tsansa na maging [Charmed] sa loob ng 1 turn. Pagkatapos, isang random na kalaban (maliban sa pangunahing target) ay magiging [Charmed] at agad na gagawa ng isang pag-atake.',
		describe_ma = 'Api syaitan melepaskan tenaga syaitan, berubah menjadi ahli sihir dan jatuh ke sasaran di barisan belakang musuh, menyebabkan #C0x3D8A99#350% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Kerosakan Sihir#C0x5B545B#. Sasaran tidak dapat menerima kesan buff selama 2 giliran dan mempunyai peluang 40% untuk [Terpesona] selama 1 giliran. Kemudian, satu musuh rawak (kecuali sasaran utama) akan [Terpesona] dan menyerang sekali dengan segera.',
		describe = 'The devil\'s flame unleashes demonic energy, transforming into a witch and descending upon the enemy\'s backline target, dealing #C0x3D8A99#350% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magic Damage#C0x5B545B#. The target cannot receive buff effects for 2 turns and has a 40% chance to be [Charmed] for 1 turn. Then, a random enemy (excluding the main target) will be [Charmed] and immediately perform one attack.',
		simDesc_vn = 'Ngọn lửa quỷ giải phóng năng lượng ma quỷ, biến thành phù thủy và rơi về phía mục tiêu ở hàng sau của kẻ địch, khiến mục tiêu không nhận được buff và có cơ hội mê hoặc mục tiêu.',
		simDesc_en = 'The demon flame unleashes demonic energy, transforming into a witch and falling onto the enemy\'s backline, preventing the target from receiving buffs and having a chance to charm them.',
		simDesc_th = 'เปลวไฟปีศาจปลดปล่อยพลังงานปีศาจ กลายร่างเป็นแม่มดและตกลงไปยังแถวหลังของศัตรู ทำให้เป้าหมายไม่ได้รับบัฟและมีโอกาสหลอกล่อเป้าหมายได้',
		simDesc_in = 'Api iblis melepaskan energi setan, berubah menjadi penyihir dan jatuh ke barisan belakang musuh, membuat target tidak menerima buff dan memiliki peluang untuk memikat target.',
		simDesc_ph = 'Ang apoy ng demonyo ay naglalabas ng demonic energy, nagiging isang bruha at bumabagsak sa likurang hanay ng kalaban, na nagpapahinto sa target na makatanggap ng buff at may pagkakataong mahikayat ang target.',
		simDesc_ma = 'Api syaitan melepaskan tenaga syaitan, berubah menjadi ahli sihir dan jatuh ke arah barisan belakang musuh, menyebabkan sasaran tidak menerima buff dan berpeluang untuk memikat sasaran.',
		simDesc = 'The demon flame unleashes demonic energy, transforming into a witch and falling onto the enemy\'s backline, preventing the target from receiving buffs and having a chance to charm them.',
		starEffect = __data_t__starEffect[13963],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu quả: Các hành động tấn công bổ sung do kỹ năng tất sát gây ra cho kẻ địch sẽ không khiến chúng nhận thêm nộ khí, sau khi thi triển tất sát, tất cả mục tiêu bị mê hoặc sẽ tự nguyện hiến 5% máu tối đa của bản thân cho Ngọn Lửa Ác Ma (tối đa không vượt quá 300% Công Phép của Ngọn Lửa Ác Ma).',
		starEffectDesc = 'Enhance Effectiveness: Additional attack actions caused by the execution skill on enemies will not increase their rage. After executing the skill, all charmed targets will voluntarily sacrifice 5% of their maximum health to the Demon Flame (not exceeding 300% of the Demon Flame\'s Magic Power).',
		starEffectDesc_en = 'Enhance Effectiveness: Additional attack actions caused by the execution skill on enemies will not increase their rage. After executing the skill, all charmed targets will voluntarily sacrifice 5% of their maximum health to the Demon Flame (not exceeding 300% of the Demon Flame\'s Magic Power).',
		starEffectDesc_th = 'เสริมประสิทธิภาพ: การโจมตีเสริมที่เกิดจากทักษะสังหารใส่ศัตรูจะไม่เพิ่มความโกรธของพวกมัน หลังจากใช้ทักษะสังหาร เป้าหมายที่ถูกล่อลวงทั้งหมดจะสละเลือดสูงสุด 5% ของตนเองให้กับเปลวเพลิงปีศาจ (ไม่เกิน 300% ของพลังเวทย์ของเปลวเพลิงปีศาจ)',
		starEffectDesc_in = 'Tingkatkan Efektivitas: Tindakan serangan tambahan yang disebabkan oleh keterampilan pembunuhan pada musuh tidak akan menambah kemarahan mereka. Setelah menggunakan keterampilan pembunuhan, semua target yang terpesona akan secara sukarela memberikan 5% dari darah maksimum mereka kepada Api Setan (maksimal tidak melebihi 300% Kekuatan Sihir Api Setan).',
		starEffectDesc_ph = 'Pahusayin ang Bisa: Ang mga dagdag na aksyon sa pag-atake na dulot ng kasanayan sa pagpatay sa mga kalaban ay hindi magpapataas ng kanilang galit. Pagkatapos gamitin ang kasanayan sa pagpatay, lahat ng mga target na naakit ay kusang-loob na magsasakripisyo ng 5% ng kanilang pinakamataas na kalusugan para sa Demon Flame (hindi lalampas sa 300% ng Magic Power ng Demon Flame).',
		starEffectDesc_ma = 'Tingkatkan Keberkesanan: Tindakan serangan tambahan yang disebabkan oleh kemahiran pembunuhan ke atas musuh tidak akan menambahkan kemarahan mereka. Selepas menggunakan kemahiran pembunuhan, semua sasaran yang terpesona akan secara sukarela menyumbangkan 5% darah maksimum mereka kepada Api Syaitan (tidak melebihi 300% Kuasa Sihir Api Syaitan).',
