	[13966] = {
		id = 13966,
		skillName_vn = 'Tâm hồn giao động',
		skillName_en = 'A trembling soul',
		skillName_th = 'จิตวิญญาณที่สั่นสะท้าน',
		skillName_in = 'Jiwa yang berguncang',
		skillName_ph = 'Nanginginig na kaluluwa',
		skillName_ma = 'Jiwa yang bergelora',
		skillName = 'A trembling soul',
		describe_vn = 'Trước khi bắt đầu mỗi vòng lớn, có #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# xác suất [ Quyến rũ] một mục tiêu kẻ thù ngẫu nhiên trong 1 vòng và 50% xác suất [ Quyến rũ] một mục tiêu bổ sung, đối với mỗi mục tiêu của riêng bạn. Đối với các anh hùng bóng tối, xác suất quyến rũ của các kỹ năng thụ động ở vòng đầu tiên tăng thêm 10% (khi chiến đấu với Madoka, chỉ thuộc tính thứ hai của Madoka sẽ được thay thế bằng thuộc tính bóng tối trong trận chiến này, và cả Ngọn lửa quỷ và Madoka đều nhận được 20% sát thương bổ sung); mục tiêu dưới [Bùa chú] sẽ tăng 15% sát thương khi tấn công các đơn vị đồng minh của nó.',
		describe_en = 'Before each major round begins, there is a #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# chance to [Charm] a random enemy target for 1 round and a 50% chance to [Charm] an additional target for each of your own targets. For Dark heroes, the charm chance of passive skills in the first round increases by 10% (when battling Madoka, only Madoka\'s second attribute will be replaced with the dark attribute in this battle, and both Demon Flame and Madoka receive 20% additional damage); targets under [Curse] will deal 15% increased damage when attacking their allied units.',
		describe_th = 'ก่อนเริ่มรอบใหญ่แต่ละรอบ จะมีโอกาส #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# ในการ [เสน่ห์] เป้าหมายศัตรูแบบสุ่มเป็นเวลา 1 รอบ และมีโอกาส 50% ในการ [เสน่ห์] เป้าหมายเพิ่มเติมสำหรับแต่ละเป้าหมายของคุณ สำหรับฮีโร่แห่งความมืด โอกาส [เสน่ห์] ของสกิลติดตัวในรอบแรกจะเพิ่มขึ้น 10% (เมื่อสู้กับมาดока จะมีการแทนที่คุณสมบัติที่สองของมาดокаด้วยคุณสมบัติแห่งความมืดในการต่อสู้ครั้งนี้ และทั้งเปลวเพลิงปีศาจและมาดโอก็จะได้รับความเสียหายเพิ่มขึ้น 20%); เป้าหมายที่อยู่ภายใต้ [คำสาป] จะเพิ่มความเสียหาย 15% เมื่อโจมตีหน่วยพันธมิตรของพวกมัน',
		describe_in = 'Sebelum memulai setiap putaran besar, ada peluang #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# untuk [Mempesona] target musuh acak selama 1 putaran dan peluang 50% untuk [Mempesona] target tambahan untuk setiap target milikmu. Untuk pahlawan kegelapan, peluang pesona dari skill pasif pada putaran pertama meningkat 10% (ketika bertarung melawan Madoka, hanya atribut kedua Madoka yang akan digantikan dengan atribut gelap dalam pertempuran ini, dan baik Demon Flame maupun Madoka menerima tambahan 20% kerusakan); target yang berada di bawah [Kutukan] akan meningkatkan 15% kerusakan saat menyerang unit sekutunya.',
		describe_ph = 'Bago magsimula ang bawat malaking round, mayroong #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# na pagkakataon na [Charm] ang isang random na kalaban na target sa loob ng 1 round at 50% chance na [Charm] ang karagdagang target para sa bawat sarili mong target. Para sa mga Dark heroes, tumaas ng 10% ang charm chance ng mga passive skills sa unang round (kapag nakikipaglaban kay Madoka, ang pangalawang attribute lang ni Madoka ang papalitan ng dark attribute sa laban na ito, at parehong nakakatanggap ng 20% karagdagang damage ang Demon Flame at Madoka); ang mga target sa ilalim ng [Curse] ay tataas ng 15% ang damage kapag inaatake ang kanilang mga kaalyadong yunit.',
		describe_ma = 'Sebelum setiap pusingan besar bermula, terdapat peluang #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# untuk [Memikat] sasaran musuh secara rawak selama 1 pusingan dan peluang 50% untuk [Memikat] sasaran tambahan bagi setiap sasaran milik anda. Bagi wira gelap, peluang memikat kemahiran pasif pada pusingan pertama meningkat sebanyak 10% (apabila bertarung dengan Madoka, hanya sifat kedua Madoka akan digantikan dengan sifat gelap dalam pertempuran ini, dan kedua-dua Demon Flame dan Madoka menerima 20% kerosakan tambahan); sasaran yang di bawah [Sumpahan] akan meningkatkan kerosakan sebanyak 15% apabila menyerang unit sekutunya.',
		describe = 'Before each major round begins, there is a #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# chance to [Charm] a random enemy target for 1 round and a 50% chance to [Charm] an additional target for each of your own targets. For Dark heroes, the charm chance of passive skills in the first round increases by 10% (when battling Madoka, only Madoka\'s second attribute will be replaced with the dark attribute in this battle, and both Demon Flame and Madoka receive 20% additional damage); targets under [Curse] will deal 15% increased damage when attacking their allied units.',
		starEffect = __data_t__starEffect[13966],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi Ngọn Lửa Quỷ chịu một đòn tấn công chí mạng từ kỹ năng chủ động của địch, một mục tiêu địch đang bị <Mê Hoặc> (ngoại trừ kẻ tấn công) sẽ thay mặt gánh chịu đòn tấn công này (chỉ kích hoạt một lần duy nhất, tính lũy kế toàn trận).',
		starEffectDesc = 'Additional effect: When the Devil Flame takes a critical hit from an enemy\'s active skill, an enemy target under <Charm> (except the attacker) will take the hit instead (activates only once, accumulates throughout the battle).',
		starEffectDesc_en = 'Additional effect: When the Devil Flame takes a critical hit from an enemy\'s active skill, an enemy target under <Charm> (except the attacker) will take the hit instead (activates only once, accumulates throughout the battle).',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อเปลวไฟปีศาจได้รับการโจมตีคริติคอลจากสกิลแอคทีฟของศัตรู เป้าหมายศัตรูที่อยู่ในสถานะ <มึนเมา> (ยกเว้นผู้โจมตี) จะรับการโจมตีแทน (เปิดใช้งานได้เพียงครั้งเดียวสะสมตลอดการต่อสู้)',
		starEffectDesc_in = 'Efek tambahan: Ketika Api Iblis menerima serangan kritis dari skill aktif musuh, satu target musuh yang sedang <Terpesona> (kecuali penyerang) akan menerima serangan tersebut sebagai gantinya (hanya aktif sekali, terakumulasi selama pertandingan).',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag ang Devil Flame ay tumanggap ng critical hit mula sa active skill ng kalaban, isang kalaban na target na nasa ilalim ng <Charm> (maliban ang attacker) ay tatanggap ng atake na ito bilang kapalit (isang beses lang ito ma-a-activate, naiipon sa buong laban).',
		starEffectDesc_ma = 'Kesan tambahan: Apabila Api Syaitan menerima serangan kritikal daripada kemahiran aktif musuh, satu sasaran musuh yang berada di bawah <Terpesona> (kecuali penyerang) akan menerima serangan tersebut sebagai ganti (aktif hanya sekali, terkumpul sepanjang perlawanan).',
		zawakeSimpleDesc = 'When a charmed hero attacks Gardevoir, damage is reduced by 20%  ',
		zawakeSimpleDesc_en = 'When a charmed hero attacks Gardevoir, damage is reduced by 20%  ',
		zawakeSimpleDesc_th = 'เมื่อฮีโร่ที่ถูกทำให้หลงใหลโจมตี Gardevoir ความเสียหายจะลดลง 20%',
		zawakeSimpleDesc_in = 'Saat hero yang terpesona menyerang Gardevoir, damage akan berkurang 20%  ',
		zawakeSimpleDesc_ph = 'Kapag ang hero na nahumaling ay umatake kay Gardevoir, bawas ang damage ng 20%  ',
		zawakeSimpleDesc_ma = 'Apabila hero yang dipikat menyerang Gardevoir, kerosakan akan dikurangkan sebanyak 20%  ',
		zawakeSimpleDesc_vn = 'Anh hùng bị mê hoặc tấn công Gardevoir, sát thương sẽ giảm 20%',
