	[13972] = {
		id = 13972,
		skillName_vn = 'Cơn lốc u ám',
		skillName_en = 'Dark Tornado',
		skillName_th = 'พายุหมุนมืดมน',
		skillName_in = 'Badai Gelap',
		skillName_ph = 'Madilim na Bagyong Ikot',
		skillName_ma = 'Tornedo Gelap',
		skillName = 'Dark Tornado',
		describe_vn = 'Ngọn lửa của con quỷ cầm lưỡi hái tử thần và tấn công các mục tiêu hàng của kẻ thù, gây ra #C0x3D8A99#220% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$#C0xF13 B54#Sát Thương Phép Thuật#C0x5B545B#, tăng vĩnh viễn xác suất [Bùa chú] lên 5% và thêm [Yêu thích] vào mục tiêu trong 2 lượt (mục tiêu giảm 20% khả năng miễn nhiễm khống chế và giảm 30% khả năng phòng thủ kép khi bị anh hùng bóng tối tấn công)',
		describe_en = 'The demon\'s flame wields the grim reaper\'s scythe and attacks enemy row targets, dealing #C0x3D8A99#220% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Magic Damage#C0x5B545B#. Permanently increases the chance of [Charm] by 5% and inflicts [Favor] on targets for 2 turns (targets suffer 20% reduced control immunity and 30% reduced dual defense when attacked by the dark hero).',
		describe_th = 'เปลวไฟปีศาจถือเคียวยมฑูตและโจมตีเป้าหมายในแถวของศัตรู ทำให้เกิดความเสียหายเวทย์มนตร์ #C0x3D8A99#220%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายเวทย์มนตร์#C0x5B545B#. เพิ่มโอกาส [เสน่ห์] ขึ้นถาวร 5% และเพิ่มสถานะ [ถูกใจ] ให้เป้าหมายเป็นเวลา 2 ตา (เป้าหมายได้รับการลดภูมิต้านทานการควบคุม 20% และลดการป้องกันคู่ 30% เมื่อถูกฮีโร่แห่งความมืดโจมตี)',
		describe_in = 'Api iblis memegang sabit kematian dan menyerang target barisan musuh, memberikan #C0x3D8A99#220% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerusakan Sihir#C0x5B545B#. Meningkatkan peluang [Mantra] secara permanen sebesar 5% dan menambahkan [Favorit] pada target selama 2 giliran (target mengalami pengurangan 20% kekebalan kontrol dan pengurangan 30% pertahanan ganda saat diserang oleh pahlawan kegelapan).',
		describe_ph = 'Ang apoy ng demonyo ay humahawak ng ari-arian ng kamatayan at umaatake sa mga target na nasa hanay ng kalaban, na nagdudulot ng #C0x3D8A99#220% Magical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Magical Damage#C0x5B545B#. Permanenteng pinapataas ang tsansa ng [Charm] ng 5% at idinadagdag ang [Favor] sa target sa loob ng 2 turn (ang target ay bumababa ang 20% resistensya laban sa control at bumaba ang 30% sa double defense kapag inatake ng madilim na bayani).',
		describe_ma = 'Api iblis memegang sabit maut dan menyerang sasaran baris musuh, menyebabkan #C0x3D8A99#220% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerosakan Sihir#C0x5B545B#. Meningkatkan secara kekal peluang [Mantera] sebanyak 5% dan menambah [Kegemaran] pada sasaran selama 2 pusingan (sasaran mengalami pengurangan 20% imun kawalan dan pengurangan 30% ketahanan berganda apabila diserang oleh wira gelap).',
		describe = 'The demon\'s flame wields the grim reaper\'s scythe and attacks enemy row targets, dealing #C0x3D8A99#220% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Magic Damage#C0x5B545B#. Permanently increases the chance of [Charm] by 5% and inflicts [Favor] on targets for 2 turns (targets suffer 20% reduced control immunity and 30% reduced dual defense when attacked by the dark hero).',
		zawakeSimpleDesc = 'Permanently increases charm chance by 6%',
