	[13973] = {
		id = 13973,
		skillName_vn = 'Bà phù thủy của bờ bên này',
		skillName_en = 'The witch of this shore',
		skillName_th = 'แม่มดของฝั่งนี้',
		skillName_in = 'Penyihir di pantai ini',
		skillName_ph = 'Ang bruha sa baybayin na ito',
		skillName_ma = 'Penyihir di tepi pantai ini',
		skillName = 'The witch of this shore',
		describe_vn = 'Ngọn lửa của quỷ giải phóng năng lượng ma quỷ, biến thành phù thủy và rơi về phía mục tiêu ở hàng sau của kẻ địch, gây ra #C0x3D8A99#350% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$#C0xF13 B54#Spell Damage#C0x5B545B#, mục tiêu sẽ không thể nhận được hiệu ứng buff trong 2 hiệp và sẽ có một 40% khả năng [Bùa mê] mục tiêu ở hàng sau trong 1 lượt, và sau đó một mục tiêu địch ngẫu nhiên bị [Bùa mê] ngoại trừ mục tiêu chính sẽ ngay lập tức tấn công một lần',
		describe_en = 'The demon\'s flame releases demonic energy, transforming into a witch and descending upon the backline enemy target, dealing #C0x3D8A99#350% Magic Damage#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Spell Damage#C0x5B545B#. The target will be unable to receive buff effects for 2 turns and there is a 40% chance to [Charm] a backline target for 1 turn. Then, a random enemy target except the main one who was charmed will immediately perform one attack.',
		describe_th = 'ไฟของปีศาจปลดปล่อยพลังงานปีศาจ เปลี่ยนรูปเป็นแม่มดและตกลงสู่เป้าหมายที่แถวหลังของศัตรู สร้างความเสียหายเวท #C0x3D8A99#350%#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#ความเสียหายเวท#C0x5B545B# เป้าหมายจะไม่สามารถรับบัฟได้เป็นเวลา 2 ตา และมีโอกาส 40% ที่จะ [เสน่หา] เป้าหมายแถวหลังเป็นเวลา 1 ตา จากนั้นเป้าหมายศัตรูสุ่มหนึ่งที่ไม่ใช่เป้าหมายหลักที่ติด [เสน่หา] จะโจมตีทันที 1 ครั้ง',
		describe_in = 'Api iblis melepaskan energi iblis, berubah menjadi penyihir dan jatuh ke target di barisan belakang musuh, menyebabkan #C0x3D8A99#350% Damage Sihir#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Damage Sihir#C0x5B545B#. Target tidak akan menerima efek buff selama 2 giliran dan ada peluang 40% untuk [Pesona] target di barisan belakang selama 1 giliran, kemudian satu target musuh acak selain target utama yang terkena [Pesona] akan langsung menyerang sekali.',
		describe_ph = 'Ang apoy ng demonyo ay nagpapalaya ng demonyong enerhiya, nagiging isang mangkukulam at bumabagsak sa target sa hulihan ng mga kaaway, na nagdudulot ng #C0x3D8A99#350% Spell Damage#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Spell Damage#C0x5B545B#. Ang target ay hindi makakatanggap ng mga buff effect sa loob ng 2 na turn at may 40% na pagkakataon na [Pagkakabighani] ang target sa hulihan sa loob ng 1 turn, at pagkatapos ay isang random na kalaban maliban sa pangunahing target na na-[Pagkakabighani] ay agad na gagawa ng isang pag-atake.',
		describe_ma = 'Api syaitan melepaskan tenaga syaitan, berubah menjadi ahli sihir dan jatuh ke sasaran di barisan belakang musuh, menyebabkan #C0x3D8A99#350% Kerosakan Sihir#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Kerosakan Sihir#C0x5B545B#. Sasaran tidak dapat menerima kesan buff selama 2 pusingan dan terdapat peluang 40% untuk [Mantra] sasaran di barisan belakang selama 1 pusingan, kemudian satu sasaran musuh rawak kecuali sasaran utama yang terkena [Mantra] akan melakukan serangan segera sekali.',
		describe = 'The demon\'s flame releases demonic energy, transforming into a witch and descending upon the backline enemy target, dealing #C0x3D8A99#350% Magic Damage#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Spell Damage#C0x5B545B#. The target will be unable to receive buff effects for 2 turns and there is a 40% chance to [Charm] a backline target for 1 turn. Then, a random enemy target except the main one who was charmed will immediately perform one attack.',
		simDesc_vn = 'Ngọn lửa quỷ giải phóng năng lượng ma quỷ, biến thành phù thủy và rơi về phía mục tiêu ở hàng sau của kẻ địch, khiến mục tiêu không nhận được buff và có cơ hội mê hoặc mục tiêu.',
		simDesc_en = 'The demon flame releases demonic energy, transforming into a witch and falling towards the enemy\'s backline, preventing the target from receiving buffs and having a chance to charm the target.',
		simDesc_th = 'เปลวไฟปีศาจปล่อยพลังปีศาจ แปลงร่างเป็นแม่มดและตกลงไปยังแถวหลังของศัตรู ทำให้เป้าหมายไม่ได้รับบัฟและมีโอกาสสะกดจิตเป้าหมาย',
		simDesc_in = 'Api iblis melepaskan energi iblis, berubah menjadi penyihir dan jatuh ke arah barisan belakang musuh, mencegah target menerima buff dan memiliki peluang untuk memesona target.',
		simDesc_ph = 'Ang apoy ng demonyo ay naglalabas ng enerhiyang demonyo, nagiging isang bruha at bumabagsak patungo sa likurang hanay ng kalaban, na nagpipigil sa target na makatanggap ng buff at may pagkakataong mabighani ang target.',
		simDesc_ma = 'Api syaitan melepaskan tenaga syaitan, bertukar menjadi ahli sihir dan jatuh ke arah barisan belakang musuh, menyebabkan sasaran tidak menerima buff dan berpeluang mempesona sasaran.',
		simDesc = 'The demon flame releases demonic energy, transforming into a witch and falling towards the enemy\'s backline, preventing the target from receiving buffs and having a chance to charm the target.',
		starEffect = __data_t__starEffect[13973],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu quả: Các đòn tấn công phụ từ kỹ năng tất sát lên kẻ địch sẽ không khiến chúng nhận thêm nộ khí, sau khi thi triển kỹ năng tất sát, tất cả mục tiêu bị mê hoặc sẽ tự nguyện hiến 5% máu tối đa của bản thân cho Ngọn Lửa Quỷ Dữ (tối đa không vượt quá 300% Công Phép của Ngọn Lửa Quỷ Dữ).',
		starEffectDesc = 'Increase Effectiveness: Secondary attacks from the finishing skill on enemies will not cause them to gain additional Rage. After activating the finishing skill, all charmed targets will willingly sacrifice 5% of their maximum HP to the Demon Flame (up to a maximum of 300% of the Demon Flame\'s Magic Power).',
		starEffectDesc_en = 'Increase Effectiveness: Secondary attacks from the finishing skill on enemies will not cause them to gain additional Rage. After activating the finishing skill, all charmed targets will willingly sacrifice 5% of their maximum HP to the Demon Flame (up to a maximum of 300% of the Demon Flame\'s Magic Power).',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: การโจมตีรองจากสกิลฆ่าหมดจะไม่ทำให้ศัตรูได้รับพลังความโกรธเพิ่ม หลังจากใช้สกิลฆ่าหมด ทุกเป้าหมายที่ถูกหลงใหลจะยินดีสละเลือดสูงสุด 5% ของตนให้กับเปลวไฟปีศาจ (สูงสุดไม่เกิน 300% ของพลังเวทย์ของเปลวไฟปีศาจ)',
		starEffectDesc_in = 'Tingkatkan Efektivitas: Serangan tambahan dari keterampilan penyelesaian pada musuh tidak akan membuat mereka mendapatkan Kemarahan tambahan. Setelah menggunakan keterampilan penyelesaian, semua target yang terpesona akan rela menyerahkan 5% HP maksimum mereka untuk Api Iblis (maksimal tidak melebihi 300% dari Kekuatan Sihir Api Iblis).',
		starEffectDesc_ph = 'Palakasin ang Bisa: Ang mga pangalawang pag-atake mula sa finishing skill laban sa mga kaaway ay hindi magpaparami ng kanilang Galit. Pagkatapos gamitin ang finishing skill, lahat ng mga target na nabighani ay kusang magbibigay ng 5% ng kanilang maximum na HP sa Demon Flame (hanggang sa maksimum na 300% ng Magic Power ng Demon Flame).',
		starEffectDesc_ma = 'Tingkatkan Keberkesanan: Serangan tambahan dari kemahiran pembunuhan ke atas musuh tidak akan menyebabkan mereka mendapat kemarahan tambahan. Selepas menggunakan kemahiran pembunuhan, semua sasaran yang terpesona akan rela menyerahkan 5% kesihatan maksimum mereka kepada Api Syaitan (maksimum tidak melebihi 300% Kuasa Sihir Api Syaitan).',
		zawakeSimpleDesc = 'Charm chance increases to 40%',
		zawakeSimpleDesc_en = 'Charm chance increases to 40%',
