	[13976] = {
		id = 13976,
		skillName_vn = 'Tâm hồn giao động',
		skillName_en = 'A trembling soul',
		skillName_th = 'จิตวิญญาณที่สั่นสะท้าน',
		skillName_in = 'Jiwa yang berguncang',
		skillName_ph = 'Nanginginig na kaluluwa',
		skillName_ma = 'Jiwa yang bergelora',
		skillName = 'A trembling soul',
		describe_vn = 'Trước khi bắt đầu mỗi vòng lớn, có #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# xác suất [ Quyến rũ] một mục tiêu kẻ thù ngẫu nhiên trong 1 vòng và 50% xác suất [ Quyến rũ] một mục tiêu bổ sung, đối với mỗi mục tiêu của riêng bạn. Đối với các anh hùng bóng tối, xác suất quyến rũ của các kỹ năng thụ động ở vòng đầu tiên tăng thêm 10% (khi chiến đấu với Madoka, chỉ thuộc tính thứ hai của Madoka sẽ được thay thế bằng thuộc tính bóng tối trong trận chiến này, và cả Ngọn lửa quỷ và Madoka đều nhận được 20% sát thương bổ sung); mục tiêu dưới [Bùa chú] sẽ tăng 15% sát thương khi tấn công các đơn vị đồng minh của nó.',
		describe_en = 'Before each major round starts, there is a #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# chance to [Charm] a random enemy target for 1 round and a 50% chance to [Charm] an additional target for each of your own targets. For dark heroes, the charm chance from passive skills increases by 10% in the first round (when fighting Madoka, only Madoka\'s second attribute will be replaced with the dark attribute in this battle, and both Demon Flame and Madoka receive 20% extra damage); targets under [Enchantment] take 15% increased damage when attacking their allied units.',
		describe_th = 'ก่อนเริ่มรอบใหญ่แต่ละรอบ จะมีโอกาส #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# ในการ [สะกดจิต] เป้าหมายศัตรูสุ่มเป็นเวลา 1 รอบ และมีโอกาส 50% ในการ [สะกดจิต] เป้าหมายเสริมสำหรับเป้าหมายของคุณแต่ละตัว สำหรับฮีโร่แห่งความมืด อัตราการสะกดจิตจากสกิลติดตัวจะเพิ่มขึ้น 10% ในรอบแรก (เมื่อสู้กับมาดอกะ คุณสมบัติที่สองของมาดอกะจะถูกแทนที่ด้วยคุณสมบัติความมืดในรอบนี้ และทั้งเปลวไฟปีศาจและมาดอกะจะได้รับความเสียหายเพิ่มขึ้น 20%); เป้าหมายที่ถูก [มนต์สะกด] จะได้รับความเสียหายเพิ่มขึ้น 15% เมื่อโจมตีหน่วยพันธมิตรของพวกมัน',
		describe_in = 'Sebelum memulai setiap ronde besar, ada peluang sebesar #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# untuk [Menyihir] satu target musuh acak selama 1 ronde dan peluang 50% untuk [Menyihir] target tambahan untuk setiap target milikmu. Untuk pahlawan kegelapan, peluang menyihir dari skill pasif meningkat 10% pada ronde pertama (ketika bertarung melawan Madoka, hanya atribut kedua Madoka yang akan diganti dengan atribut kegelapan dalam pertarungan ini, dan baik Demon Flame maupun Madoka mendapatkan tambahan 20% damage); target yang berada di bawah [Mantra] menerima 15% damage tambahan saat menyerang unit sekutu mereka.',
		describe_ph = 'Bago magsimula ang bawat malaking round, may #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# na tsansa na [Makitidwain] ang isang random na target ng kaaway sa loob ng 1 round at 50% tsansa na [Makitidwain] ang isang karagdagang target para sa bawat isa mong target. Para sa mga madilim na bayani, ang tsansa ng makitidwain mula sa passive na mga kasanayan ay tumataas ng 10% sa unang round (kapag nakikipaglaban kay Madoka, ang pangalawang attribute lamang ni Madoka ang papalitan ng dark attribute sa laban na ito, at pareho ang Demon Flame at Madoka ay tumatanggap ng 20% dagdag na pinsala); ang mga target na nasa ilalim ng [Enchantment] ay tumatanggap ng 15% dagdag pinsala kapag umaatake sa kanilang mga kaalyadong yunit.',
		describe_ma = 'Sebelum memulakan setiap pusingan besar, terdapat peluang #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# untuk [Memikat] satu sasaran musuh rawak selama 1 pusingan dan peluang 50% untuk [Memikat] sasaran tambahan bagi setiap sasaran milik anda. Bagi wira kegelapan, peluang memikat dari kemahiran pasif meningkat 10% pada pusingan pertama (apabila bertarung dengan Madoka, hanya atribut kedua Madoka akan digantikan dengan atribut kegelapan dalam pertempuran ini, dan kedua-dua Demon Flame dan Madoka menerima tambahan 20% kerosakan); sasaran yang berada di bawah [Sihir] menerima 15% peningkatan kerosakan apabila menyerang unit sekutu mereka.',
		describe = 'Before each major round starts, there is a #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# chance to [Charm] a random enemy target for 1 round and a 50% chance to [Charm] an additional target for each of your own targets. For dark heroes, the charm chance from passive skills increases by 10% in the first round (when fighting Madoka, only Madoka\'s second attribute will be replaced with the dark attribute in this battle, and both Demon Flame and Madoka receive 20% extra damage); targets under [Enchantment] take 15% increased damage when attacking their allied units.',
		starEffect = __data_t__starEffect[13976],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi Ngọn lửa Ác ma chịu một đòn tấn công chí mạng từ kỹ năng chủ động của kẻ địch, một mục tiêu địch bị <Mê hoặc> (ngoại trừ kẻ tấn công) sẽ thay mặt chịu đòn tấn công này (chỉ có thể kích hoạt một lần, tính lũy kế toàn trận).',
		starEffectDesc = 'Additional effect: When the Demon Flame suffers a critical hit from an enemy\'s active skill, an enemy target affected by <Charmed> (except the attacker) will take the hit instead (can only trigger once, accumulates throughout the battle).',
		starEffectDesc_en = 'Additional effect: When the Demon Flame suffers a critical hit from an enemy\'s active skill, an enemy target affected by <Charmed> (except the attacker) will take the hit instead (can only trigger once, accumulates throughout the battle).',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อเปลวเพลิงปีศาจได้รับการโจมตีคริติคอลจากสกิลแอคทีฟของศัตรู เป้าหมายศัตรูที่ถูก <มาหลงใหล> (ยกเว้นผู้โจมตี) จะได้รับการโจมตีแทน (สามารถเปิดใช้งานได้เพียงครั้งเดียว สะสมตลอดทั้งเกม)',
		starEffectDesc_in = 'Efek tambahan: Ketika Api Iblis menerima serangan kritis dari keterampilan aktif musuh, satu target musuh yang terkena <Terkesima> (kecuali penyerang) akan menanggung serangan tersebut (hanya dapat aktif sekali, terakumulasi selama pertandingan).',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag ang Demon Flame ay tumanggap ng critical hit mula sa active skill ng kalaban, isang kalabang target na may <Napahanga> (maliban sa attacker) ang tatanggap sa atake (maaari lamang ma-activate nang isang beses, nag-aaccumulate sa buong laban).',
		starEffectDesc_ma = 'Kesan tambahan: Apabila Api Syaitan menerima serangan kritikal daripada kemahiran aktif musuh, satu sasaran musuh yang <Terpesona> (kecuali penyerang) akan menerima serangan tersebut bagi pihaknya (hanya boleh diaktifkan sekali, terkumpul sepanjang perlawanan).',
