		skillName_ph = 'Tusok ng bakal',
		skillName_ma = 'Tusuk dengan besi',
		skillName = 'Stab with iron',
		describe_vn = 'Kodora dùng đầu cứng như thép tấn công hàng ngang của kẻ địch, gây ra #C0xE69900#250% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ Sát Thương Vật Lý#C0xF13B54#C0x5B545B#, tăng 80% phòng thủ vật lý của bản thân, kéo dài 2 lượt, thêm khiên thép cho toàn đội (giá trị khiên dựa trên 350% phòng thủ vật lý của Maple), kéo dài 2 lượt',
		describe_en = 'Kodora uses a steel-hard head to attack the enemy\'s horizontal line, dealing #C0xE69900#250% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ Physical Damage#C0xF13B54#C0x5B545B#. Increases own physical defense by 80% for 2 turns and grants a steel shield to the entire team (shield value based on 350% of Maple\'s physical defense), lasting 2 turns.',
		describe_th = 'โคโดระใช้หัวแข็งเหมือนเหล็กโจมตีแถวแนวนอนของศัตรู สร้างความเสียหาย #C0xE69900#250% การโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ ความเสียหายทางกายภาพ#C0xF13B54#C0x5B545B# เพิ่มการป้องกันทางกายภาพของตนเองขึ้น 80% เป็นเวลา 2 รอบ และมอบโล่เหล็กให้กับทีมทั้งหมด (ค่าของโล่ขึ้นอยู่กับการป้องกันทางกายภาพ 350% ของเมเปิ้ล) เป็นเวลา 2 รอบ',
		describe_in = 'Kodora menggunakan kepala yang sekeras baja untuk menyerang baris horizontal musuh, memberikan #C0xE69900#250% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ Kerusakan Fisik#C0xF13B54#C0x5B545B#. Meningkatkan pertahanan fisik sendiri sebesar 80% selama 2 giliran, dan menambahkan perisai baja untuk seluruh tim (nilai perisai berdasarkan 350% pertahanan fisik Maple), bertahan selama 2 giliran.',
		describe_ph = 'Ginagamit ni Kodora ang matigas na ulo na parang bakal upang atakihin ang pahalang na linya ng kalaban, na nagdudulot ng #C0xE69900#250% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*48)$ Pisikal na Pinsala#C0xF13B54#C0x5B545B#. Pinapataas ang sariling pisikal na depensa ng 80% sa loob ng 2 turno, at nagdaragdag ng steel shield para sa buong koponan (ang halaga ng shield ay base sa 350% pisikal na depensa ni Maple), tumatagal ng 2 turno.',
		describe_ma = 'Kodora menggunakan kepala keras seperti besi untuk menyerang barisan mendatar musuh, menyebabkan #C0xE69900#250% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ Kecederaan Fizikal#C0xF13B54#C0x5B545B#. Meningkatkan pertahanan fizikal sendiri sebanyak 80% selama 2 pusingan, serta menambah perisai besi untuk seluruh pasukan (nilai perisai berdasarkan 350% pertahanan fizikal Maple), bertahan selama 2 pusingan.',
		describe = 'Kodora uses a steel-hard head to attack the enemy\'s horizontal line, dealing #C0xE69900#250% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ Physical Damage#C0xF13B54#C0x5B545B#. Increases own physical defense by 80% for 2 turns and grants a steel shield to the entire team (shield value based on 350% of Maple\'s physical defense), lasting 2 turns.',
		simDesc_vn = 'Kodora dùng đầu cứng như thép va chạm vào mục tiêu hàng ngang của đối phương, tăng cường phòng thủ vật lý của bản thân và thêm lá chắn thép cho toàn bộ đồng minh.',
		simDesc_en = 'Kodora uses a steel-hard head to smash into the enemy\'s horizontal target, enhancing their own physical defense and adding a steel shield to all allies.',
		simDesc_th = 'โคโดระใช้หัวแข็งเหมือนเหล็กพุ่งชนเป้าหมายแนวนอนของศัตรู เพิ่มการป้องกันทางกายภาพของตัวเองและมอบโล่เหล็กให้กับพันธมิตรทั้งหมด',
		simDesc_in = 'Kodora menggunakan kepala keras seperti baja untuk menghantam target horizontal musuh, memperkuat pertahanan fisiknya sendiri dan menambahkan perisai baja untuk semua sekutu.',
		simDesc_ph = 'Ginagamit ni Kodora ang matigas na ulo na tila bakal para tumama sa pahalang na target ng kalaban, pinapalakas ang kanyang pisikal na depensa at nagpapalagay ng bakal na kalasag para sa lahat ng mga kakampi.',
		simDesc_ma = 'Kodora menggunakan kepala yang keras seperti besi untuk melanggar sasaran mendatar musuh, meningkatkan pertahanan fizikal dirinya dan menambah perisai besi untuk semua sekutu.',
		simDesc = 'Kodora uses a steel-hard head to smash into the enemy\'s horizontal target, enhancing their own physical defense and adding a steel shield to all allies.',
		starEffect = __data_t__starEffect[15023],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Khiên thép được nâng cấp thành khiên với 400% phòng thủ vật lý của Meipulu.',
		starEffectDesc = 'Enhance effect: Steel shield upgraded to a shield with 400% physical defense of Meipulu.',
		starEffectDesc_en = 'Enhance effect: Steel shield upgraded to a shield with 400% physical defense of Meipulu.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: โล่เหล็กได้รับการอัพเกรดเป็นโล่ที่มีการป้องกันกายภาพ 400% ของ Meipulu',
		starEffectDesc_in = 'Tingkatkan efek: Perisai baja ditingkatkan menjadi perisai dengan pertahanan fisik 400% dari Meipulu.',
