	[15046] = {
		id = 15046,
		skillName_vn = 'Giáp sắt',
		skillName_en = 'Iron Armor',
		skillName_th = 'ชุดเกราะเหล็ก',
		skillName_in = 'Baju Besi',
		skillName_ph = 'Bakal na Bakal',
		skillName_ma = 'Perisai Besi',
		skillName = 'Iron Armor',
		describe_vn = 'Trước khi bắt đầu mỗi vòng đấu lớn, hãy thêm [Khiên thép] cho chính bạn và anh hùng của bạn có lượng HP thấp nhất; Super Boss Cordora sẽ không bị ảnh hưởng bởi sát thương tràn khi Khiên Thép và Khiên Thép phá vỡ lá chắn. Hiệu ứng này có thể được kích hoạt ba lần (tích lũy cho toàn bộ trò chơi)\n#F10# \n#F40#[Steel Shield]: Lượng khiên là Super Boss Cordora#C0x5c9970#$(150+skillLevel*1-1)$%#C0x5B545B# phòng thủ vật lý. Khi được thêm vào các anh hùng cơ khí, nó sẽ tự động được nâng cấp lên [Khiên thép]',
		describe_en = 'Before starting each major round, add [Steel Shield] to yourself and your hero with the lowest HP; Super Boss Cordora will not be affected by spill damage when Steel Shield and Steel Shield break the shield. This effect can be triggered three times (accumulative for the entire game). \n#F10# \n#F40#[Steel Shield]: Shield amount is Super Boss Cordora#C0x5c9970#$(150+skillLevel*1-1)$%#C0x5B545B# physical defense. When applied to mechanical heroes, it automatically upgrades to [Steel Shield].',
		describe_th = 'ก่อนเริ่มแต่ละรอบใหญ่ ให้เพิ่ม [โล่เหล็ก] ให้กับตัวคุณเองและฮีโร่ที่มี HP ต่ำที่สุดของคุณ; ซูเปอร์บอสคอร์โดราจะไม่ถูกผลกระทบจากความเสียหายล้นเมื่อ โล่เหล็ก และ โล่เหล็ก ทำลายโล่เอฟเฟกต์นี้สามารถเปิดใช้งานได้สามครั้ง (สะสมตลอดเกมทั้งหมด) \n#F10# \n#F40#[โล่เหล็ก]: ปริมาณโล่คือซูเปอร์บอสคอร์โดรา#C0x5c9970#$(150+skillLevel*1-1)$%#C0x5B545B# เกราะกายภาพ เมื่อใช้กับฮีโร่เครื่องจักร จะอัปเกรดอัตโนมัติเป็น [โล่เหล็ก]',
		describe_in = 'Sebelum memulai setiap babak besar, tambahkan [Perisai Baja] kepada diri Anda dan pahlawan Anda yang memiliki HP terendah; Super Boss Cordora tidak akan terpengaruh oleh kerusakan limpahan saat Perisai Baja dan Perisai Baja memecahkan perisai. Efek ini dapat diaktifkan tiga kali (terakumulasi untuk seluruh permainan). \n#F10# \n#F40#[Perisai Baja]: Jumlah perisai adalah Super Boss Cordora#C0x5c9970#$(150+skillLevel*1-1)$%#C0x5B545B# pertahanan fisik. Ketika diterapkan pada pahlawan mekanis, secara otomatis akan ditingkatkan menjadi [Perisai Baja].',
		describe_ph = 'Bago simulan ang bawat malaking round, magdagdag ng [Steel Shield] para sa iyong sarili at ang iyong hero na may pinakamababang HP; hindi maaapektuhan si Super Boss Cordora ng spill damage kapag ang Steel Shield ay nasira. Maaaring ma-trigger ang effect na ito ng tatlong beses (naipon para sa buong laro). \n#F10# \n#F40#[Steel Shield]: Ang dami ng shield ay Super Boss Cordora#C0x5c9970#$(150+skillLevel*1-1)$%#C0x5B545B# physical defense. Kapag inilapat sa mga mechanical hero, awtomatikong mag-a-upgrade ito sa [Steel Shield].',
		describe_ma = 'Sebelum memulakan setiap pusingan besar, tambah [Perisai Keluli] kepada diri anda dan wira anda yang memiliki HP terendah; Super Bos Cordora tidak akan terjejas oleh kerosakan limpahan apabila Perisai Keluli dan Perisai Keluli memecahkan perisai. Kesan ini boleh diaktifkan tiga kali (berkumulasi untuk seluruh permainan). \n#F10# \n#F40#[Perisai Keluli]: Jumlah perisai adalah Super Bos Cordora#C0x5c9970#$(150+skillLevel*1-1)$%#C0x5B545B# pertahanan fizikal. Apabila digunakan pada wira mekanikal, ia akan dinaik taraf secara automatik menjadi [Perisai Keluli].',
		describe = 'Before starting each major round, add [Steel Shield] to yourself and your hero with the lowest HP; Super Boss Cordora will not be affected by spill damage when Steel Shield and Steel Shield break the shield. This effect can be triggered three times (accumulative for the entire game). \n#F10# \n#F40#[Steel Shield]: Shield amount is Super Boss Cordora#C0x5c9970#$(150+skillLevel*1-1)$%#C0x5B545B# physical defense. When applied to mechanical heroes, it automatically upgrades to [Steel Shield].',
		starEffect = __data_t__starEffect[15046],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Trong lượt đầu tiên, thêm 2 lượt <Khiên thép> cho toàn bộ đồng minh.',
		starEffectDesc = 'Additional effect: In the first turn, add 2 <Steel Shields> to all allies.',
		starEffectDesc_en = 'Additional effect: In the first turn, add 2 <Steel Shields> to all allies.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ในรอบแรก เพิ่ม <โล่เหล็ก> 2 อันให้กับพันธมิตรทั้งหมด',
		starEffectDesc_in = 'Efek tambahan: Pada giliran pertama, tambahkan 2 <Perisai Baja> untuk semua sekutu.',
		starEffectDesc_ph = 'Karagdagang epekto: Sa unang turn, magdagdag ng 2 <Bakus na Kalasag> para sa lahat ng mga kakampi.',
