	[17712] = {
		id = 17712,
		skillName_vn = 'Rung rinh',
		skillName_en = 'Ripple',
		skillName_th = 'ริปเปิล',
		skillName_in = 'Gelisah',
		skillName_ph = 'Riknik',
		skillName_ma = 'Gelisah',
		skillName = 'Ripple',
		describe_vn = 'Cá Xấu Xí cắn dây thừng đung đưa và dùng cơ thể đánh vào mục tiêu đơn phía địch, gây #C0x3D8A99#150% Phép Công#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đồng thời khiến một mục tiêu ngẫu nhiên ở hàng sau phía địch rơi vào trạng thái [Mê Hoặc] trong 1 lượt (Mê Hoặc: hiệu ứng khống chế, mục tiêu có 50% khả năng không thể hành động, nếu tấn công thì sát thương gây ra lần này giảm một nửa)',
		describe_en = 'The Ugly Crocodile bites the swinging rope and uses its body to strike a single target on the enemy\'s front row, dealing #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, and simultaneously causing a random target in the enemy\'s back row to fall into [Confusion] for 1 turn (Confusion: a control effect, the target has a 50% chance to be unable to act, and if it attacks, the damage dealt is halved).',
		describe_th = 'จระเข้ขี้เหร่กัดเชือกที่แกว่งไปมาและใช้ร่างกายโจมตีเป้าหมายเดี่ยวแถวหน้า ฝ่ายตรงข้าม สร้างความเสียหาย #C0x3D8A99#150% พลังเวท#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# พร้อมกันนี้ ทำให้เป้าหมายสุ่มหนึ่งตัวในแถวหลังฝ่ายตรงข้าม ตกอยู่ในสถานะ [เมาหลง] เป็นเวลา 1 เทิร์น (เมาหลง: เอฟเฟกต์ควบคุม เป้าหมายมีโอกาส 50% ที่จะไม่สามารถทำอะไรกระทำได้ หากโจมตี ความเสียหายที่เกิดขึ้นจะลดลงครึ่งหนึ่ง)',
		describe_in = 'Buaya Jelek menggigit tali yang berayun dan menggunakan tubuhnya untuk menyerang satu target di barisan depan musuh, memberikan #C0x3D8A99#150% Serangan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, sekaligus membuat target acak di barisan belakang musuh masuk ke dalam keadaan [Kebingungan] selama 1 giliran (Kebingungan: efek kontrol, target memiliki peluang 50% untuk tidak bisa bertindak, jika menyerang maka kerusakan yang dihasilkan kali ini berkurang setengahnya).',
		describe_ph = 'Ang Pangit na Buwaya ay kumagat sa pumupukaw na lubid at ginamit ang katawan para tamaan ang isang target sa harapang hanay ng kalaban, na nagdudulot ng #C0x3D8A99#150% Lakas ng Mahika#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Pinsalang Mahika #C0x5B545B#, kasabay nito ay nagdudulot sa isang random na target sa likurang hanay ng kalaban na mapasailalim sa estado ng [Pagkalito] sa loob ng 1 turno (Pagkalito: isang control effect, may 50% tsansa ang target na hindi makakilos, at kung umatake ay kalahati lamang ng pinsalang dulot ang matatanggap).',
		describe_ma = 'Buaya Hodoh menggigit tali yang berayun dan menggunakan badannya untuk menyerang satu sasaran di barisan depan musuh, menyebabkan #C0x3D8A99#150% Serangan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, dan pada masa yang sama menyebabkan satu sasaran rawak di barisan belakang musuh jatuh ke dalam keadaan [Keliru] selama 1 pusingan (Keliru: kesan kawalan, sasaran mempunyai peluang 50% untuk tidak dapat bertindak, jika menyerang maka kerosakan yang dihasilkan kali ini dikurangkan separuh).',
		describe = 'The Ugly Crocodile bites the swinging rope and uses its body to strike a single target on the enemy\'s front row, dealing #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, and simultaneously causing a random target in the enemy\'s back row to fall into [Confusion] for 1 turn (Confusion: a control effect, the target has a 50% chance to be unable to act, and if it attacks, the damage dealt is halved).',
