	[17713] = {
		id = 17713,
		skillName_vn = 'Sóng biển',
		skillName_en = 'Sea wave',
		skillName_th = 'คลื่นทะเล',
		skillName_in = 'Gelombang laut',
		skillName_ph = 'Alon ng dagat',
		skillName_ma = 'Ombak laut',
		skillName = 'Sea wave',
		describe_vn = 'Cá Xấu Xí tạo ra một cơn sóng biển tấn công toàn bộ mục tiêu phía địch, gây #C0x3D8A99#150% Phép Công#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đồng thời dựa vào trạng thái tiêu cực của bản thân để hồi máu cho toàn bộ đồng đội (lượng hồi máu cơ bản là 400% Phép Phòng, mỗi tầng tiêu cực của bản thân tăng 50% Phép Phòng lượng hồi máu, tối đa 800%), giảm 20% tỷ lệ chí mạng của toàn bộ mục tiêu phía địch trong 1 lượt, sau đó xóa bỏ toàn bộ trạng thái tiêu cực của bản thân',
		describe_en = 'Ugly Crocodile creates a tidal wave attacking all enemy targets, dealing #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#. At the same time, based on its own negative status, it heals all allies (base heal is 400% Magic Defense, each stack of negative status on itself increases healing by 50% Magic Defense, up to 800%), reduces all enemy targets\' critical rate by 20% for 1 turn, then removes all negative statuses from itself.',
		describe_th = 'จระเข้ขี้เหร่สร้างคลื่นทะเลโจมตีเป้าหมายฝ่ายตรงข้ามทั้งหมด สร้างความเสียหายเวทมนตร์ #C0x3D8A99#150% พลังโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# พร้อมกับฟื้นฟูสุขภาพให้กับทีมทั้งหมดโดยอิงจากสถานะลบของตัวเอง (การฟื้นฟูขั้นพื้นฐานคือ 400% การป้องกันเวทมนตร์ ของแต่ละชั้นสถานะลบเพิ่มการฟื้นฟูขึ้น 50% การป้องกันเวทมนตร์ สูงสุด 800%) ลดอัตราคริติคอลของเป้าหมายฝ่ายตรงข้ามทั้งหมดลง 20% เป็นเวลา 1 เทิร์น จากนั้นลบสถานะลบทั้งหมดของตัวเอง',
		describe_in = 'Bangkai Buaya menciptakan gelombang laut yang menyerang semua target musuh, memberikan #C0x3D8A99#150% Serangan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Bersamaan dengan itu, berdasarkan status negatif dirinya sendiri, menyembuhkan seluruh tim (penyembuhan dasar adalah 400% Pertahanan Sihir, setiap level status negatif dirinya meningkatkan penyembuhan sebesar 50% Pertahanan Sihir, maksimal 800%), mengurangi tingkat kritikal semua target musuh sebesar 20% selama 1 giliran, kemudian menghapus semua status negatif pada dirinya sendiri.',
		describe_ph = 'Nilalang Buwaya ay bumubuo ng isang alon ng dagat na umaatake sa lahat ng kalaban, nagdudulot ng #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#. Kasabay nito, base sa sariling negatibong estado, nagpapagaling sa buong kasamahan (ang base na paggaling ay 400% Magic Defense, bawat antas ng negatibong estado ng sarili ay nagpapataas ng paggaling ng 50% Magic Defense, hanggang 800%), binabawasan ang critical rate ng lahat ng kalaban ng 20% sa loob ng 1 turn, pagkatapos ay tinatanggal ang lahat ng negatibong estado ng sarili.',
		describe_ma = 'Buaya Hodoh mencipta gelombang laut yang menyerang semua sasaran musuh, memberikan #C0x3D8A99#150% Serangan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Pada masa yang sama, berdasarkan keadaan negatif dirinya sendiri untuk memulihkan kesihatan seluruh rakan sepasukan (pemerolehan asas adalah 400% Pertahanan Sihir, setiap lapisan keadaan negatif pada dirinya sendiri menambah pemulihan sebanyak 50% Pertahanan Sihir, maksimum 800%), mengurangkan kadar kritikal semua sasaran musuh sebanyak 20% selama 1 giliran, selepas itu menghapuskan semua keadaan negatif dirinya sendiri.',
		describe = 'Ugly Crocodile creates a tidal wave attacking all enemy targets, dealing #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#. At the same time, based on its own negative status, it heals all allies (base heal is 400% Magic Defense, each stack of negative status on itself increases healing by 50% Magic Defense, up to 800%), reduces all enemy targets\' critical rate by 20% for 1 turn, then removes all negative statuses from itself.',
		simDesc_vn = 'Xấu Xí Ngư tạo ra một cơn sóng lớn tấn công tất cả mục tiêu của đối phương và hồi phục cho toàn bộ đồng minh.',
		simDesc_en = 'Ugly Fish creates a huge wave to attack all enemy targets and heals all allies.',
		simDesc_th = 'ปลาน่าเกลียดสร้างคลื่นขนาดใหญ่โจมตีเป้าหมายของศัตรูทั้งหมดและฟื้นฟูเพื่อนร่วมทีมทั้งหมด',
		simDesc_in = 'Ikan Jelek menciptakan gelombang besar untuk menyerang semua target musuh dan menyembuhkan semua sekutu.',
		simDesc_ph = 'Ang Pangit na Isda ay lumilikha ng malaking alon upang atakihin ang lahat ng mga target ng kalaban at nagpapagaling sa lahat ng mga kasamahan.',
		simDesc_ma = 'Ikan Hodoh menghasilkan gelombang besar untuk menyerang semua sasaran musuh dan menyembuhkan semua sekutu.',
		simDesc = 'Ugly Fish creates a huge wave to attack all enemy targets and heals all allies.',
