	[17716] = {
		id = 17716,
		skillName_vn = 'Vảy thần kỳ',
		skillName_en = 'Magical scales',
		skillName_th = 'เกล็ดมหัศจรรย์',
		skillName_in = 'Sisik ajaib',
		skillName_ph = 'Mahiwagang kaliskis',
		skillName_ma = 'Sisikan ajaib',
		skillName = 'Magical scales',
		describe_vn = 'Sau khi đồng đội kết thúc hành động, nếu trên người họ có trạng thái tiêu cực, sẽ chuyển ngẫu nhiên một trạng thái tiêu cực sang bản thân, đồng thời cung cấp cho bản thân một lá chắn (dựa trên #C0x5c9970#$(100+1*skillLevel-1)$%#C0x5B545B# Phép Phòng cơ bản) trong 1 lượt, giá trị lá chắn có thể cộng dồn tối đa bốn lần',
		describe_en = 'After teammates finish their actions, if they have a negative status, one random negative status will be transferred to themselves, and at the same time, they grant themselves a shield (based on #C0x5c9970#$(100+1*skillLevel-1)$%#C0x5B545B# Basic Magic Defense) for 1 turn. The shield value can stack up to four times.',
		describe_th = 'หลังจากเพื่อนร่วมทีมทำการกระทำเสร็จสิ้น หากพวกเขามีสถานะลบ จะทำการย้ายสถานะลบหนึ่งสถานะแบบสุ่มไปยังตัวเอง และในขณะเดียวกันจะมอบโล่ (อ้างอิงจาก #C0x5c9970#$(100+1*skillLevel-1)$%#C0x5B545B# พลังป้องกันเวทพื้นฐาน) เป็นเวลา 1 เทิร์น ค่าของโล่สามารถสะสมได้สูงสุดสี่ครั้ง',
		describe_in = 'Setelah rekan setim menyelesaikan aksi mereka, jika mereka memiliki status negatif, satu status negatif secara acak akan dipindahkan ke diri sendiri, dan pada saat yang sama, memberikan diri sendiri sebuah perisai (berdasarkan #C0x5c9970#$(100+1*skillLevel-1)$%#C0x5B545B# Pertahanan Sihir Dasar) selama 1 giliran. Nilai perisai dapat bertumpuk hingga maksimal empat kali.',
		describe_ph = 'Pagkatapos matapos ang aksyon ng mga kakampi, kung may negatibong estado sila, isang random na negatibong estado ang ililipat sa sarili, at sabay na bibigyan ang sarili ng isang shield (batay sa #C0x5c9970#$(100+1*skillLevel-1)$%#C0x5B545B# Basic Magic Defense) sa loob ng 1 turn. Ang halaga ng shield ay maaaring mag-stack nang hanggang apat na beses.',
		describe_ma = 'Selepas rakan sepasukan menamatkan tindakan mereka, jika mereka mempunyai status negatif, satu status negatif rawak akan dipindahkan kepada diri sendiri, dan pada masa yang sama, memberi diri sendiri perisai (berdasarkan #C0x5c9970#$(100+1*skillLevel-1)$%#C0x5B545B# Pertahanan Sihir Asas) selama 1 giliran. Nilai perisai boleh bertumpuk sehingga maksimum empat kali.',
		describe = 'After teammates finish their actions, if they have a negative status, one random negative status will be transferred to themselves, and at the same time, they grant themselves a shield (based on #C0x5c9970#$(100+1*skillLevel-1)$%#C0x5B545B# Basic Magic Defense) for 1 turn. The shield value can stack up to four times.',
		starEffect = __data_t__starEffect[17716],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi bị tấn công bởi kỹ năng chủ động, có 60% xác suất khiến kẻ tấn công rơi vào trạng thái <Mê hoặc> trong 1 lượt.',
		starEffectDesc = 'Additional effect: When attacked by an active skill, there is a 60% chance to cause the attacker to fall into the <Charm> state for 1 turn.',
		starEffectDesc_en = 'Additional effect: When attacked by an active skill, there is a 60% chance to cause the attacker to fall into the <Charm> state for 1 turn.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อถูกโจมตีด้วยสกิลแอคทีฟ มีโอกาส 60% ที่จะทำให้ผู้โจมตีเข้าสู่สถานะ <หลงใหล> เป็นเวลา 1 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Saat diserang oleh skill aktif, ada peluang 60% untuk membuat penyerang masuk ke status <Terpesona> selama 1 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag inatake ng isang active skill, may 60% na tsansa na mapalagay ang umaatake sa estado ng <Engganyo> sa loob ng 1 turn.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila diserang oleh kemahiran aktif, terdapat 60% kemungkinan menyebabkan penyerang jatuh ke dalam keadaan <Terpesona> selama 1 pusingan.',
