	[18013] = {
		id = 18013,
		skillName_vn = 'Đột kích bóng oán',
		skillName_en = 'Ghost Strike',
		skillName_th = 'จู่โจมผี',
		skillName_in = 'Serangan Hantu',
		skillName_ph = 'Ghost Strike',
		skillName_ma = 'Serangan Hantu',
		skillName = 'Ghost Strike',
		describe_vn = 'Búp bê Oán Ảnh lặn vào không gian bóng tối, sau đó triệu hồi nhiều bóng ma tấn công mục tiêu đơn lẻ ở bất kỳ vị trí nào của kẻ địch, gây #C0xE69900#440% Công Vật Lý#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, nếu mục tiêu đang chịu ảnh hưởng của [Oán Niệm], kéo dài thời gian hiệu lực lên 5 lượt và khiến [Oán Niệm] trên mục tiêu không thể bị xóa',
		describe_en = 'The Vengeful Doll dives into the darkness, then summons multiple ghosts to attack a single target at any enemy position, dealing #C0xE69900#440% Physical Attack#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage#C0x5B545B#. If the target is affected by [Grudge], the duration is extended to 5 turns and the [Grudge] on the target cannot be removed.',
		describe_th = 'ตุ๊กตาผีดิสแผลงดำน้ำเข้าสู่ความมืด จากนั้นเรียกผีหลายตัวโจมตีเป้าหมายเดี่ยวในตำแหน่งใดก็ได้ของศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#440%#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# หากเป้าหมายได้รับผลกระทบจาก [Grudge] จะยืดเวลาการใช้งานเป็น 5 เทิร์น และ [Grudge] บนเป้าหมายจะไม่สามารถถูกลบได้',
		describe_in = 'Boneka Dendam menyelam ke dalam kegelapan, kemudian memanggil banyak hantu untuk menyerang satu target di posisi musuh mana pun, memberikan #C0xE69900#440% Serangan Fisik#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Jika target sedang terkena efek [Dendam], durasi diperpanjang menjadi 5 giliran dan [Dendam] pada target tidak dapat dihapus.',
		describe_ph = 'Ang Manika ng Poot ay lumulubog sa madilim na kalawakan, pagkatapos ay nag-aanyaya ng maraming mga multo upang umatake sa isang target sa anumang posisyon ng kalaban, na nagdudulot ng #C0xE69900#440% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Kung ang target ay naapektuhan ng [Poot], pinalalawig ang tagal nito ng 5 na turn at ang [Poot] sa target ay hindi maaaring tanggalin.',
		describe_ma = 'Doll Dendam menyelam ke dalam kegelapan, kemudian memanggil beberapa hantu untuk menyerang satu sasaran di mana-mana posisi musuh, menyebabkan #C0xE69900#440% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Jika sasaran sedang menerima kesan [Dendam], tempoh kesan dilanjutkan kepada 5 pusingan dan [Dendam] pada sasaran tidak boleh dipadamkan.',
		describe = 'The Vengeful Doll dives into the darkness, then summons multiple ghosts to attack a single target at any enemy position, dealing #C0xE69900#440% Physical Attack#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage#C0x5B545B#. If the target is affected by [Grudge], the duration is extended to 5 turns and the [Grudge] on the target cannot be removed.',
		simDesc_vn = 'Oán Ảnh Búp Bê lặn vào không gian bóng tối, sau đó triệu hồi nhiều bóng ma tấn công mục tiêu đơn lẻ ở vị trí bất kỳ của đối phương.',
		simDesc_en = 'The Vengeful Doll dives into the shadow realm, then summons multiple phantoms to attack a single target at any position of the enemy.',
		simDesc_th = 'ตุ๊กตาแค้นดำดิ่งเข้าสู่มิติแห่งเงามืด จากนั้นเรียกผีเสื้อหลายตนโจมตีเป้าหมายเดียวในตำแหน่งใดก็ได้ของศัตรู',
		simDesc_in = 'Boneka Pendendam menyelam ke dalam ruang bayangan, kemudian memanggil banyak hantu untuk menyerang satu target di posisi mana pun dari musuh.',
		simDesc_ph = 'Angkinang na Manika ay lumulubog sa kalawakan ng kadiliman, pagkatapos ay nagtatawag ng maraming multo upang atakihin ang isang layunin sa anumang posisyon ng kalaban.',
		simDesc_ma = 'Patung Dendam menyelam ke dalam ruang kegelapan, kemudian memanggil banyak hantu untuk menyerang satu sasaran di mana-mana kedudukan musuh.',
		simDesc = 'The Vengeful Doll dives into the shadow realm, then summons multiple phantoms to attack a single target at any position of the enemy.',
		starEffect = __data_t__starEffect[18013],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi tấn công mục tiêu bị ảnh hưởng bởi <Oán niệm>, có thể hồi phục 30% máu đã mất.',
		starEffectDesc = 'Additional effect: When attacking a target affected by <Oán niệm>, can recover 30% of lost HP.',
		starEffectDesc_en = 'Additional effect: When attacking a target affected by <Oán niệm>, can recover 30% of lost HP.',
		starEffectDesc_th = 'ผลเพิ่มเติม: เมื่อโจมตีเป้าหมายที่ได้รับผลกระทบจาก <Oán niệm> สามารถฟื้นฟู HP ที่หายไปได้ 30%.',
		starEffectDesc_in = 'Efek tambahan: Saat menyerang target yang terkena <Oán niệm>, dapat memulihkan 30% HP yang hilang.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag umaatake sa target na apektado ng <Oán niệm>, maaaring makabawi ng 30% ng nawalang HP.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila menyerang sasaran yang terjejas oleh <Oán niệm>, boleh memulihkan 30% daripada HP yang hilang.',
		zawakeEffect = __data_t__zawakeEffect[18013],
		-- {79003}
		zawakeEffectDesc = 'A doll of resentment dives into the dark space, then summons many phantoms to attack a single target at any position of the enemy, dealing #C0xE69900#440% Physical Attack#C0x5B545B#+$(skillLevel*4*60)$ Physical Damage#C0x5B545B#. If the target is affected by <resentment>, extend its duration by 5 turns and make <resentment> on the target cannot be dispelled; and this skill\'s critical damage is increased by 50%.',
		zawakeEffectDesc_en = 'A doll of resentment dives into the dark space, then summons many phantoms to attack a single target at any position of the enemy, dealing #C0xE69900#440% Physical Attack#C0x5B545B#+$(skillLevel*4*60)$ Physical Damage#C0x5B545B#. If the target is affected by <resentment>, extend its duration by 5 turns and make <resentment> on the target cannot be dispelled; and this skill\'s critical damage is increased by 50%.',
		zawakeEffectDesc_th = 'ตุ๊กตาความแค้นดิ่งเข้าสู่พื้นที่มืด จากนั้นเรียกผีหลายตนโจมตีเป้าหมายเดี่ยวในตำแหน่งใดก็ได้ของศัตรู สร้างความเสียหาย #C0xE69900#440% การโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*60)$ ความเสียหายทางกายภาพ#C0x5B545B# หากเป้าหมายติดสถานะ <ความแค้น> จะเพิ่มระยะเวลาของมันเป็น 5 เทิร์น และทำให้ <ความแค้น> บนเป้าหมายไม่สามารถถูกล้างได้; และความเสียหายคริติคอลของสกิลนี้เพิ่มขึ้น 50%',
		zawakeEffectDesc_in = 'Boneka dendam menyelam ke dalam ruang gelap, kemudian memanggil banyak hantu untuk menyerang satu target pada posisi mana pun dari musuh, memberikan #C0xE69900#440% Serangan Fisik#C0x5B545B#+$(skillLevel*4*60)$ Kerusakan Fisik#C0x5B545B#. Jika target sedang dipengaruhi oleh <dendam>, perpanjang durasinya menjadi 5 giliran, dan buat <dendam> pada target tidak bisa dihilangkan; serta kerusakan kritis dari skill ini meningkat 50%.',
		zawakeEffectDesc_ph = 'Isang manika ng poot ang lumusong sa madilim na espasyo, pagkatapos ay nagmumula ng maraming multo upang atakihin ang isang target sa anumang posisyon ng kaaway, na nagdudulot ng #C0xE69900#440% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*60)$ Pisikal na Pinsala#C0x5B545B#. Kung ang target ay apektado ng <poot>, pinapalawig ang tagal nito ng 5 na turn, at ginagawa ang <poot> sa target na hindi maaaring matanggal; at ang kritikal na pinsala ng kasanayang ito ay tumaas ng 50%.',
		zawakeEffectDesc_ma = 'Patung dendam menyelam ke ruang gelap, kemudian memanggil banyak hantu untuk menyerang satu sasaran di mana-mana posisi musuh, menyebabkan #C0xE69900#440% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*60)$ Kerosakan Fizikal#C0x5B545B#. Jika sasaran sedang menerima kesan <dendam>, lanjutkan tempoh kesan tersebut selama 5 pusingan, dan menjadikan <dendam> pada sasaran tidak boleh dihapus; serta kerosakan kritikal kemahiran ini meningkat 50%.',
		zawakeEffectDesc_vn = 'Búp bê oán ảnh lặn vào không gian bóng tối, sau đó triệu hồi nhiều bóng ma tấn công mục tiêu đơn lẻ ở bất kỳ vị trí nào của kẻ địch, gây ra #C0xE69900#440% Công Vật Lý#C0x5B545B#+$(skillLevel*4*60)$ Sát Thương Vật Lý#C0x5B545B#, nếu mục tiêu đang chịu ảnh hưởng của <oán niệm>, kéo dài thời gian của nó lên 5 lượt, và làm cho <oán niệm> trên người mục tiêu không thể bị xua tan; và sát thương kỹ năng chí mạng lần này tăng 50%',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Critical skill damage of this attack is increased by 50%',
		zawakeSimpleDesc_en = '#C0x5c9970#Critical skill damage of this attack is increased by 50%',
		zawakeSimpleDesc_th = '#C0x5c9970#ความเสียหายคริติคอลของสกิลนี้เพิ่มขึ้น 50%',
