	[18026] = {
		id = 18026,
		skillName_vn = 'Thân xác bị nguyền rủa',
		skillName_en = 'The body is cursed',
		skillName_th = 'ร่างกายถูกสาปแช่ง',
		skillName_in = 'Tubuh dikutuk',
		skillName_ph = 'Ang katawan ay pinatibayan ng sumpa',
		skillName_ma = 'Badan itu dikutuk',
		skillName = 'The body is cursed',
		describe_vn = 'Mỗi lần tấn công giảm 1 điểm nộ khí của mục tiêu;\nKhi bị kẻ địch tấn công, có #C0x5c9970#$(15+skillLevel*0.15-0.15)$%#C0x5B545B# xác suất áp đặt [Oán Niệm] lên kẻ tấn công trong 2 lượt (Oán Niệm: hiệu ứng kiểm soát, phong ấn chiêu thức cuối cùng mà mục tiêu sử dụng trước khi bị áp đặt Oán Niệm)',
		describe_en = 'Each attack reduces the target\'s anger by 1 point;\nWhen attacked by an enemy, there is a #C0x5c9970#$(15+skillLevel*0.15-0.15)$%#C0x5B545B# chance to apply [Grudge] on the attacker for 2 turns (Grudge: a control effect that seals the target\'s ultimate skill used before the Grudge is applied).',
		describe_th = 'ทุกครั้งที่โจมตีจะลดพลังโกรธของเป้าหมายลง 1 แต้ม;\nเมื่อถูกศัตรูโจมตี มีโอกาส #C0x5c9970#$(15+skillLevel*0.15-0.15)$%#C0x5B545B# ที่จะติดสถานะ [ความแค้น] กับผู้โจมตีเป็นเวลา 2 เทิร์น (ความแค้น: ผลกระทบควบคุมที่ปิดผนึกสกิลสุดท้ายที่เป้าหมายใช้ก่อนถูกติดสถานะ ความแค้น)',
		describe_in = 'Setiap kali menyerang mengurangi 1 poin kemarahan target;\nKetika diserang musuh, ada peluang #C0x5c9970#$(15+skillLevel*0.15-0.15)$%#C0x5B545B# untuk menerapkan [Dendam] pada penyerang selama 2 giliran (Dendam: efek kontrol yang mengunci skill pamungkas yang digunakan target sebelum terkena Dendam).',
		describe_ph = 'Bawat pag-atake ay nagbabawas ng 1 punto ng galit ng target;\nKapag inatake ng kalaban, may #C0x5c9970#$(15+skillLevel*0.15-0.15)$%#C0x5B545B# tsansa na maipataw ang [Pananabik] sa attacker sa loob ng 2 turn (Pananabik: isang control effect na pumipigil sa huling skill na ginamit ng target bago maipataw ang Pananabik).',
		describe_ma = 'Setiap kali menyerang mengurangkan 1 mata kemarahan sasaran;\nApabila diserang oleh musuh, terdapat peluang #C0x5c9970#$(15+skillLevel*0.15-0.15)$%#C0x5B545B# untuk mengenakan [Dendam] ke atas penyerang selama 2 pusingan (Dendam: kesan kawalan yang menyekat kemahiran terakhir yang digunakan oleh sasaran sebelum dikenakan Dendam).',
		describe = 'Each attack reduces the target\'s anger by 1 point;\nWhen attacked by an enemy, there is a #C0x5c9970#$(15+skillLevel*0.15-0.15)$%#C0x5B545B# chance to apply [Grudge] on the attacker for 2 turns (Grudge: a control effect that seals the target\'s ultimate skill used before the Grudge is applied).',
