	[18111] = {
		id = 18111,
		skillName_vn = 'Đe dọa',
		skillName_en = 'Threaten',
		skillName_th = 'ข่มขู่',
		skillName_in = 'Mengancam',
		skillName_ph = 'Banta',
		skillName_ma = 'Mengancam',
		skillName = 'Threaten',
		describe_vn = 'Linh Hồn Tuần Đêm dần biến mất, đột ngột xuất hiện sau lưng kẻ địch để hù dọa mục tiêu đơn lẻ của kẻ địch, gây #C0xE69900#80% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, và có 30% xác suất hút mục tiêu vào [Hố Đen] trong 1 lượt (Hố Đen: hiệu ứng kiểm soát, không thể hành động, không thể bị chọn và bị tấn công)',
		describe_en = 'The Night Patrol Spirit gradually disappears, suddenly appearing behind the enemy to scare a single enemy target, dealing #C0xE69900#80% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, and has a 30% chance to pull the target into the [Black Hole] for 1 turn (Black Hole: control effect, cannot act, cannot be targeted or attacked).',
		describe_th = 'วิญญาณตรวจตรายามค่ำคืนค่อยๆ หายไป ปรากฏตัวอย่างกะทันหันหลังศัตรูเพื่อข่มขวัญเป้าหมายศัตรูเพียงหนึ่งราย สร้าง #C0xE69900#80% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# และมีโอกาส 30% ที่จะดึงเป้าหมายเข้าสู่ [หลุมดำ] เป็นเวลา 1 เทิร์น (หลุมดำ: ผลควบคุม ไม่สามารถกระทำการได้ ไม่สามารถถูกเลือกหรือตีได้)',
		describe_in = 'Roh Penjaga Malam perlahan menghilang, tiba-tiba muncul di belakang musuh untuk menakuti satu target musuh, memberikan #C0xE69900#80% Serangan Fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, dan memiliki peluang 30% untuk menarik target ke dalam [Lubang Hitam] selama 1 giliran (Lubang Hitam: efek kontrol, tidak bisa bertindak, tidak bisa dipilih atau diserang).',
		describe_ph = 'Dahan ng Gabi na Kaluluwa unti-unting nawawala, biglang lilitaw sa likod ng kalaban upang takutin ang isang target ng kalaban, nagdudulot ng #C0xE69900#80% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, at may 30% tsansa na hilahin ang target sa [Itim na Butas] sa loob ng 1 turn (Itim na Butas: epektong kontrol, hindi makakilos, hindi maaaring piliin o atakihin).',
		describe_ma = 'Jiwa Rondaan Malam perlahan hilang, tiba-tiba muncul di belakang musuh untuk menakutkan satu sasaran musuh, menyebabkan #C0xE69900#80% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, dan mempunyai 30% peluang untuk menarik sasaran ke dalam [Lubang Hitam] selama 1 giliran (Lubang Hitam: kesan kawalan, tidak boleh bertindak, tidak boleh dipilih atau diserang).',
		describe = 'The Night Patrol Spirit gradually disappears, suddenly appearing behind the enemy to scare a single enemy target, dealing #C0xE69900#80% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, and has a 30% chance to pull the target into the [Black Hole] for 1 turn (Black Hole: control effect, cannot act, cannot be targeted or attacked).',
		simDesc_vn = 'Đêm Tuần Tra Linh biến mất, sau đó xuất hiện sau lưng kẻ thù, làm choáng mục tiêu đơn lẻ của đối phương.',
		simDesc_en = 'The Spirit Patrol Night disappears, then appears behind the enemy, stunning a single target.',
		simDesc_th = 'ดึกคืนลาดตระเวนจิตวิญญาณหายตัวไป จากนั้นปรากฏตัวอยู่ข้างหลังศัตรู ทำให้เป้าหมายเดียวของฝ่ายตรงข้ามมึนงง',
		simDesc_in = 'Malam Patroli Roh menghilang, kemudian muncul di belakang musuh, membuat satu target lawan terkejut.',
		simDesc_ph = 'Ang Spirit Patrol Night ay nawawala, pagkatapos ay lumilitaw sa likod ng kaaway, na nagpapakumbaba sa isang target ng kalaban.',
		simDesc_ma = 'Malam Rondaan Roh hilang, kemudian muncul di belakang musuh, mengejutkan satu sasaran musuh.',
		simDesc = 'The Spirit Patrol Night disappears, then appears behind the enemy, stunning a single target.',
		zawakeEffect = __data_t__zawakeEffect[18111],
		-- {79001}
		zawakeEffectDesc = 'The night patrol gradually disappears, suddenly appearing behind the enemy to scare a single target of the opponent, causing #C0xE69900#80% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ Physical Damage#C0xF13B54# and has a 40% chance to pull into <Black Hole> for 1 turn (Black Hole: control effect, cannot act, cannot be targeted or attacked).',
		zawakeEffectDesc_en = 'The night patrol gradually disappears, suddenly appearing behind the enemy to scare a single target of the opponent, causing #C0xE69900#80% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ Physical Damage#C0xF13B54# and has a 40% chance to pull into <Black Hole> for 1 turn (Black Hole: control effect, cannot act, cannot be targeted or attacked).',
		zawakeEffectDesc_th = 'การลาดตระเวนกลางคืนค่อยๆ หายไป ปรากฏขึ้นอย่างกะทันหันหลังศัตรูเพื่อข่มขู่เป้าหมายเดี่ยวของฝ่ายตรงข้าม ทำให้เกิด #C0xE69900#80% การโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ ความเสียหายทางกายภาพ#C0xF13B54# และมีโอกาส 40% ที่จะดึงเข้า <รูดำ> เป็นเวลา 1 เทิร์น (รูดำ: เอฟเฟกต์ควบคุม, ไม่สามารถกระทำได้, ไม่สามารถถูกเลือกและโจมตี).',
		zawakeEffectDesc_in = 'Patroli malam perlahan menghilang, tiba-tiba muncul di belakang musuh untuk menakuti satu target lawan, menyebabkan #C0xE69900#80% Serangan Fisik#C0x5B545B#+$(skillLevel*4*24)$ Kerusakan Fisik#C0xF13B54# dan memiliki peluang 40% untuk ditarik ke <Lubang Hitam> selama 1 giliran (Lubang Hitam: efek kontrol, tidak bisa bertindak, tidak bisa dipilih dan diserang).',
		zawakeEffectDesc_ph = 'Dahan ng gabi ay unti-unting nawawala, biglang lumilitaw sa likod ng kalaban upang takutin ang nag-iisang target ng kalaban, nagdudulot ng #C0xE69900#80% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*24)$ Pisikal na Pinsala#C0xF13B54# at may 40% tsansa na hilahin sa <Itim na Butas> sa loob ng 1 turn (Itim na Butas: kontrol na epekto, hindi makakilos, hindi maaaring piliin at atakihin).',
		zawakeEffectDesc_ma = 'Patroli malam secara beransur-ansur hilang, tiba-tiba muncul di belakang musuh untuk menakutkan sasaran tunggal pihak lawan, menyebabkan #C0xE69900#80% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ Kerosakan Fizikal#C0xF13B54# dan mempunyai peluang 40% untuk disedut ke dalam <Lubang Hitam> selama 1 pusingan (Lubang Hitam: kesan kawalan, tidak boleh bertindak, tidak boleh dipilih dan diserang).',
		zawakeEffectDesc_vn = 'Linh tuần đêm dần biến mất, đột ngột xuất hiện sau lưng kẻ địch để hù dọa mục tiêu đơn lẻ của đối phương, gây #C0xE69900#80% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ Sát Thương Vật Lý#C0xF13B54# và có 40% cơ hội hút vào <Hố Đen> trong 1 lượt (Hố Đen: hiệu ứng kiểm soát, không thể hành động, không thể bị chọn và bị tấn công)',
