		skillName_in = 'Serangan Jiwa',
		skillName_ph = 'Soul Attack',
		skillName_ma = 'Serangan Jiwa',
		skillName = 'Soul Attack',
		describe_vn = 'Linh Hồn Tuần Đêm dang rộng hai tay lắc lư, xuyên qua mục tiêu đơn lẻ của kẻ địch, gây #C0xE69900#140% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, và thêm hiệu ứng [Thông Cảm] lên mục tiêu trong 2 lượt (Thông Cảm: hiệu ứng tiêu cực, khi Linh Hồn Tuần Đêm chịu sát thương, mục tiêu bị đánh dấu Thông Cảm cũng chịu sát thương tương đương)',
		describe_en = 'Night Soul spreads its arms and sways, passing through a single enemy target, dealing #C0xE69900#140% Physical Attack#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, and applying the [Empathy] effect on the target for 2 turns (Empathy: a debuff effect, when Night Soul takes damage, the target marked with Empathy also takes the equivalent damage).',
		describe_th = 'วิญญาณแห่งรัตติกาลกางแขนและแกว่งไปมา หลบทะลุเป้าหมายศัตรูเดียว สร้างความเสียหาย #C0xE69900#140% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# และเพิ่มเอฟเฟกต์ [ความเห็นอกเห็นใจ] ให้กับเป้าหมายเป็นเวลา 2 เทิร์น (ความเห็นอกเห็นใจ: เอฟเฟกต์สถานะติดลบ เมื่อวิญญาณแห่งรัตติกาลได้รับความเสียหาย เป้าหมายที่ติดสถานะความเห็นอกเห็นใจก็จะได้รับความเสียหายเท่ากัน)',
		describe_in = 'Jiwa Malam membuka kedua tangan dan bergoyang, menembus satu target musuh, memberikan #C0xE69900#140% Serangan Fisik#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, dan menambahkan efek [Empati] pada target selama 2 giliran (Empati: efek negatif, ketika Jiwa Malam menerima kerusakan, target yang diberi tanda Empati juga menerima kerusakan yang sama).',
		describe_ph = 'Binhi ng Gabi ay dumadapa na nakabuka ang mga braso at umiindak, tumatagos sa isang kalabang target, nagdudulot ng #C0xE69900#140% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, at naglalagay ng epekto ng [Empatiya] sa target sa loob ng 2 turn (Empatiya: isang negatibong epektong, kapag ang Binhi ng Gabi ay tumanggap ng pinsala, ang target na may marka ng Empatiya ay tumatanggap din ng katumbas na pinsala).',
		describe_ma = 'Jiwa Malam menghulurkan kedua tangan dan bergoyang, menembusi satu sasaran musuh, memberikan #C0xE69900#140% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, dan menambah kesan [Empati] pada sasaran selama 2 giliran (Empati: kesan negatif, apabila Jiwa Malam menerima kerosakan, sasaran yang ditanda Empati juga menerima kerosakan yang sama).',
		describe = 'Night Soul spreads its arms and sways, passing through a single enemy target, dealing #C0xE69900#140% Physical Attack#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, and applying the [Empathy] effect on the target for 2 turns (Empathy: a debuff effect, when Night Soul takes damage, the target marked with Empathy also takes the equivalent damage).',
		simDesc_vn = 'Đêm Tuần Tra Linh dang rộng hai tay, lắc lư tay qua lại, xuyên qua mục tiêu đơn lẻ của đối phương.',
		simDesc_en = 'The Spirit Patrol Night stretches out both arms, swinging them back and forth, passing through a single enemy target.',
		simDesc_th = 'คืนลาดตระเวนวิญญาณยืดแขนทั้งสองข้าง โยกไปมา ผ่านเป้าหมายเดี่ยวของศัตรู',
		simDesc_in = 'Malam Patroli Roh membentangkan kedua tangan, mengayunkannya ke depan dan belakang, menembus target tunggal musuh.',
		simDesc_ph = 'Ang Gabi ng Spirit Patrol ay iniunat ang dalawang kamay, hinahampas-hampas pasulong at pabalik, dumadaan sa isang target ng kalaban.',
		simDesc_ma = 'Malam Rondaan Roh menghulurkan kedua tangan, mengayun tangan ke kiri dan kanan, menembusi satu sasaran musuh.',
		simDesc = 'The Spirit Patrol Night stretches out both arms, swinging them back and forth, passing through a single enemy target.',
		zawakeEffect = __data_t__zawakeEffect[18112],
		-- {79002}
		zawakeEffectDesc = 'The Night Spirit swings its arms wide, swaying through a single enemy target, causing #C0xE69900#140% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ Physical Damage#C0xF13B54# and applying the <Empathy> effect to the target for 3 turns (Empathy: a negative effect, when the Night Spirit is damaged, the target marked with Empathy also takes equivalent damage)',
		zawakeEffectDesc_en = 'The Night Spirit swings its arms wide, swaying through a single enemy target, causing #C0xE69900#140% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ Physical Damage#C0xF13B54# and applying the <Empathy> effect to the target for 3 turns (Empathy: a negative effect, when the Night Spirit is damaged, the target marked with Empathy also takes equivalent damage)',
		zawakeEffectDesc_th = 'จิตวิญญาณแห่งรัตติกาลแกว่งแขนกว้าง โคลงเคลงผ่านเป้าหมายฝ่ายตรงข้ามเพียงตัวเดียว สร้าง #C0xE69900#140% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ ความเสียหายทางกายภาพ#C0xF13B54# และเพิ่มเอฟเฟกต์ <ความเข้าใจ> ให้กับเป้าหมายเป็นเวลา 3 เทิร์น (ความเข้าใจ: เอฟเฟกต์ลบ เมื่อจิตวิญญาณแห่งรัตติกาลได้รับความเสียหาย เป้าหมายที่ถูกทำเครื่องหมายด้วยความเข้าใจก็จะได้รับความเสียหายในปริมาณเท่ากัน)',
		zawakeEffectDesc_in = 'Roh Malam mengayunkan kedua tangannya lebar-lebar, bergoyang melewati satu target musuh, menyebabkan #C0xE69900#140% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ Kerusakan Fisik#C0xF13B54# dan menambahkan efek <Empati> pada target selama 3 giliran (Empati: efek negatif, ketika Roh Malam terluka, target yang ditandai Empati juga akan menerima kerusakan yang setara)',
		zawakeEffectDesc_ph = 'Ang espiritu ng gabi ay malawak na hinahawakan ang mga braso, umiindak sa isang kalabang target, nagdudulot ng #C0xE69900#140% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*48)$ Pisikal na Damage#C0xF13B54# at naglalagay ng epekto ng <Empatiya> sa target sa loob ng 3 na turn (Empatiya: negatibong epekto, kapag nasaktan ang espiritu ng gabi, ang target na may tanda ng Empatiya ay tatanggap din ng katumbas na pinsala)',
		zawakeEffectDesc_ma = 'Roh Malam mengayunkan kedua tangannya luas, bergoyang melewati satu sasaran musuh, menyebabkan #C0xE69900#140% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ Kerosakan Fizikal#C0xF13B54# dan menambah kesan <Empati> kepada sasaran selama 3 giliran (Empati: kesan negatif, apabila Roh Malam cedera, sasaran yang ditandakan Empati juga akan menerima kerosakan yang setara)',
		zawakeEffectDesc_vn = 'Linh tuần đêm dang rộng hai tay lắc lư, xuyên qua mục tiêu đơn lẻ của đối phương, gây #C0xE69900#140% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ Sát Thương Vật Lý#C0xF13B54# và thêm hiệu ứng <Thông Cảm> cho mục tiêu trong 3 lượt (Thông Cảm: hiệu ứng tiêu cực, khi Linh tuần đêm bị tổn thương, mục tiêu bị đánh dấu Thông Cảm cũng sẽ chịu tổn thương tương đương)',
