	[18413] = {
		id = 18413,
		skillName_vn = 'Trăng lưỡi liềm đường tối',
		skillName_en = 'Crescent Moon in the Dark Path',
		skillName_th = 'พระจันทร์เสี้ยวในทางมืด',
		skillName_in = 'Bulan Sabit di Jalan Gelap',
		skillName_ph = 'Buwan Crescent sa Madilim na Daan',
		skillName_ma = 'Bulan Sabit di Jalan Gelap',
		skillName = 'Crescent Moon in the Dark Path',
		describe_vn = 'Sesshomaru dùng lực nhảy lên không trung, rút kiếm chém ra một lỗ đen tấn công mục tiêu của kẻ địch, gây #C0xE69900#330% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, gây thêm 40% sát thương cho mục tiêu dưới tác dụng của kỹ năng [Thảm họa] và thêm [Dấu ấn nguyền rủa] trong 3 hiệp (Dấu ấn nguyền rủa: hiệu ứng tiêu cực, 15% lượng máu đã mất của mục tiêu sẽ bị khấu trừ trước mỗi hiệp. Sát thương này là sát thương thực sự và sát thương lên BOSS sao chép được tính theo lượng máu mất của chính nó)',
		describe_en = 'Sesshomaru leaps into the air using force, draws his sword and slashes to create a black hole that attacks the enemy\'s target, dealing #C0xE69900#330% Physical Damage#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#. Additionally, it deals 40% more damage to targets affected by the [Disaster] skill and applies [Cursed Mark] for 3 rounds (Cursed Mark: a negative effect that deducts 15% of the target\'s lost health at the start of each round. This damage is true damage, and damage to clone BOSSES is calculated based on their own lost health).',
		describe_th = 'เซสโชมารุใช้พลังกระโดดขึ้นสู่ท้องฟ้า ดึงดาบฟันเป็นรูดำโจมตีเป้าหมายของศัตรู สร้าง #C0xE69900#330% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# นอกจากนี้ ยังสร้างความเสียหายเพิ่ม 40% ต่อเป้าหมายที่อยู่ภายใต้อิทธิพลของสกิล [หายนะ] และเพิ่ม [ตราคำสาป] เป็นเวลา 3 เทิร์น (ตราคำสาป: ผลกระทบทางลบ หักเลือดของเป้าหมาย 15% ของเลือดที่เสียไปก่อนแต่ละเทิร์น ความเสียหายนี้เป็นความเสียจริง และความเสียหายต่อบอสโคลนนั้นคำนวณตามเลือดที่เสียของมันเอง)',
		describe_in = 'Sesshomaru menggunakan kekuatan untuk melompat ke udara, menghunus pedang dan mengayunkan membentuk lubang hitam yang menyerang target musuh, memberikan #C0xE69900#330% Damage Fisik#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Damage Fisik#C0x5B545B#. Memberikan tambahan 40% damage pada target yang berada di bawah efek skill [Bencana] dan menambahkan [Tanda Kutukan] selama 3 giliran (Tanda Kutukan: efek negatif yang mengurangi 15% dari darah yang hilang target sebelum setiap giliran. Damage ini adalah damage nyata dan damage pada BOSSKlon dihitung berdasarkan darah yang hilang miliknya sendiri).',
		describe_ph = 'Gumamit si Sesshomaru ng lakas upang tumalon sa himpapawid, hinugot ang espada at pumutok ng isang itim na butas na sumasalakay sa target ng kalaban, na nagdudulot ng #C0xE69900#330% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Nagdudulot din ng dagdag na 40% pinsala sa mga target na nasa ilalim ng epekto ng kasanayang [Sakuna] at naglalagay ng [Tatak ng Sumpa] sa loob ng 3 turn (Tatak ng Sumpa: negatibong epekto, 15% ng nawawalang buhay ng target ay ibabawas bago ang bawat turn. Ang pinsalang ito ay tunay na pinsala at ang pinsala sa clone na BOSS ay kinakalkula batay sa pagkawala ng buhay nito).',
		describe_ma = 'Sesshomaru menggunakan tenaga untuk melompat ke udara, menghunus pedang dan melibas mencipta lubang hitam yang menyerang sasaran musuh, menyebabkan #C0xE69900#330% Damage Fizikal#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Damage Fizikal#C0x5B545B#. Menyebabkan tambahan 40% kerosakan kepada sasaran yang berada di bawah kesan kemahiran [Bencana] dan menambah [Tanda Terkutuk] selama 3 pusingan (Tanda Terkutuk: kesan negatif, 15% daripada jumlah darah yang hilang sasaran akan ditolak sebelum setiap pusingan. Kerosakan ini adalah kerosakan sebenar dan kerosakan kepada BOSSKlon dikira berdasarkan jumlah darah yang hilang dirinya sendiri).',
		describe = 'Sesshomaru leaps into the air using force, draws his sword and slashes to create a black hole that attacks the enemy\'s target, dealing #C0xE69900#330% Physical Damage#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#. Additionally, it deals 40% more damage to targets affected by the [Disaster] skill and applies [Cursed Mark] for 3 rounds (Cursed Mark: a negative effect that deducts 15% of the target\'s lost health at the start of each round. This damage is true damage, and damage to clone BOSSES is calculated based on their own lost health).',
		simDesc_vn = 'Sesshomaru dùng lực nhảy lên không trung, rút ​​kiếm và chém ra một lỗ đen tấn công các mục tiêu kẻ địch trong hàng, gây thêm một lượng sát thương cho mục tiêu kèm hiệu ứng thảm họa và thêm dấu nguyền.',
		simDesc_en = 'Sesshomaru leaps into the air, draws his sword, and slashes a black hole that attacks enemy targets in a row, dealing additional damage to them along with a disaster effect and adding a curse mark.',
		simDesc_th = 'เซสโชมารุใช้พลังกระโดดขึ้นสู่อากาศ ดึงดาบออกและฟันสร้างรูดำโจมตีเป้าหมายศัตรูในแถว สร้างความเสียหายเพิ่มเติมให้กับเป้าหมายพร้อมกับเอฟเฟกต์ภัยพิบัติและเพิ่มเครื่องหมายคำสาป',
		simDesc_in = 'Sesshomaru melompat ke udara, menghunus pedangnya, dan mengayunkan lubang hitam yang menyerang target musuh dalam satu baris, memberikan kerusakan tambahan kepada target beserta efek bencana dan menambahkan tanda kutukan.',
		simDesc_ph = 'Tumalon si Sesshomaru sa hangin, hila ang kanyang espada, at hiwain ang isang itim na butas na umaatake sa mga kalabang target sa isang hanay, na nagdudulot ng karagdagang pinsala sa mga target kasabay ng isang epekto ng sakuna at pagdagdag ng marka ng sumpa.',
		simDesc_ma = 'Sesshomaru melompat ke udara, menghunus pedangnya dan menghayunkan lubang hitam yang menyerang sasaran musuh dalam barisan, memberikan kerosakan tambahan kepada sasaran bersama kesan bencana dan menambah tanda sumpahan.',
		simDesc = 'Sesshomaru leaps into the air, draws his sword, and slashes a black hole that attacks enemy targets in a row, dealing additional damage to them along with a disaster effect and adding a curse mark.',
		starEffect = __data_t__starEffect[18413],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sát thương từ dấu ấn nguyền rủa sẽ tăng 20% cho mỗi lần kích hoạt tiếp theo.',
		starEffectDesc = 'Additional Effect: Damage from the cursed mark increases by 20% with each subsequent activation.',
