	[18416] = {
		id = 18416,
		skillName_vn = 'Tuyệt thế đại yêu',
		skillName_en = 'Ultimate Great Demon',
		skillName_th = 'ปีศาจยิ่งใหญ่ที่สุด',
		skillName_in = 'Iblis Hebat Terunggul',
		skillName_ph = 'Pinakamalakas na Dakilang Demonyo',
		skillName_ma = 'Iblis Hebat Terunggul',
		skillName = 'Ultimate Great Demon',
		describe_vn = 'Khi Sesshomaru bị tấn công, một đơn vị ngẫu nhiên tấn công Sesshomaru và kẻ địch sẽ bị chiếm hữu bởi [Thảm họa]; khi Sesshomaru tấn công, một đơn vị ngẫu nhiên bị Sesshomaru tấn công và kẻ địch cũng sẽ bị [Thảm họa] chiếm hữu; trong khi [Thảm họa] kéo dài, mỗi lần Trước khi bắt đầu kết hợp, giới hạn sinh mệnh trên giảm đi #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# và khả năng phòng thủ kép giảm đi #C0x5c9970#$(5 +skillLevel*0.1-0.1)$%#C0x5B545B#, giảm đòn tấn công kép #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, lần tiếp theo bạn bị đánh, sát thương sẽ tăng lên #C0x5c9970#$(80+skillLevel*0.2-0.2)$%#C0x5B545B#) Một điều xui xẻo ngẫu nhiên sẽ ảnh hưởng đến bạn. [Thảm họa] không thể được chồng lên. Khi Sesshomaru hiện diện, hiệu ứng [Thảm họa] luôn tồn tại.',
		describe_en = 'When Sesshomaru is attacked, a random unit attacks Sesshomaru and the enemy will be possessed by [Disaster]; when Sesshomaru attacks, a random unit is attacked by Sesshomaru and the enemy will also be possessed by [Disaster]. While [Disaster] lasts, before each combination starts, the maximum health limit decreases by #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B#, dual defense decreases by #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, dual attack decreases by #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#. The next time you are hit, damage will increase by #C0x5c9970#$(80+skillLevel*0.2-0.2)$%#C0x5B545B#. A random misfortune will affect you. [Disaster] cannot be stacked. When Sesshomaru is present, the [Disaster] effect always exists.',
		describe_th = 'เมื่อเซสโชมารุถูกโจมตี หน่วยสุ่มหนึ่งจะโจมตีเซสโชมารุ และศัตรูจะถูกครอบงำด้วย [ภัยพิบัติ]; เมื่อเซสโชมารุโจมตี หน่วยสุ่มหนึ่งจะถูกเซสโชมารุโจมตี และศัตรูจะถูกครอบงำด้วย [ภัยพิบัติ] ด้วย ในขณะที่ [ภัยพิบัติ] ดำเนินอยู่ ก่อนเริ่มผสมแต่ละครั้ง ขีดจำกัดพลังชีวิตสูงสุดจะลดลง #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# ความสามารถป้องกันคู่ลดลง #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B# การโจมตีคู่ลดลง #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B# ครั้งถัดไปที่คุณถูกตี ความเสียหายจะเพิ่มขึ้น #C0x5c9970#$(80+skillLevel*0.2-0.2)$%#C0x5B545B# โชคร้ายสุ่มจะส่งผลกระทบต่อคุณ [ภัยพิบัติ] ไม่สามารถซ้อนทับได้ เมื่อเซสโชมารุปรากฏ เอฟเฟกต์ [ภัยพิบัติ] จะคงอยู่เสมอ',
		describe_in = 'Ketika Sesshomaru diserang, sebuah unit acak menyerang Sesshomaru dan musuh akan dikuasai oleh [Bencana]; ketika Sesshomaru menyerang, sebuah unit acak diserang oleh Sesshomaru dan musuh juga akan dikuasai oleh [Bencana]. Selama [Bencana] berlangsung, sebelum setiap penggabungan dimulai, batas maksimum hidup berkurang sebesar #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B#, pertahanan ganda berkurang sebesar #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, serangan ganda berkurang sebesar #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#. Kali berikutnya Anda terkena serangan, kerusakan akan meningkat sebesar #C0x5c9970#$(80+skillLevel*0.2-0.2)$%#C0x5B545B#. Suatu kemalangan acak akan memengaruhi Anda. [Bencana] tidak dapat ditumpuk. Ketika Sesshomaru hadir, efek [Bencana] selalu ada.',
		describe_ph = 'Kapag inaatake si Sesshomaru, isang random na unit ang umaatake kay Sesshomaru at ang kalaban ay mapapasailalim sa [Sakuna]; kapag si Sesshomaru ang umatake, isang random na unit ang inaatake ni Sesshomaru at ang kalaban ay din din ay mapapasailalim sa [Sakuna]. Habang tumatagal ang [Sakuna], bago magsimula ang bawat kombinasyon, bumababa ang maximum na limitasyon ng buhay ng #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B#, bumababa ang kakayahan sa dobleng depensa ng #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, bumababa ang dobleng atake ng #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#. Sa susunod na masaktan ka, tataas ang damage ng #C0x5c9970#$(80+skillLevel*0.2-0.2)$%#C0x5B545B#. Isang random na kasawian ang tatama sa iyo. Ang [Sakuna] ay hindi maaaring ipagpatuloy. Kapag naroroon si Sesshomaru, ang epekto ng [Sakuna] ay palaging umiiral.',
		describe_ma = 'Apabila Sesshomaru diserang, satu unit rawak menyerang Sesshomaru dan musuh akan dikuasai oleh [Bencana]; apabila Sesshomaru menyerang, satu unit rawak diserang oleh Sesshomaru dan musuh juga akan dikuasai oleh [Bencana]. Semasa [Bencana] berlangsung, sebelum setiap gabungan bermula, had nyawa maksimum berkurang sebanyak #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B#, keupayaan pertahanan berganda berkurang sebanyak #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, serangan berganda berkurang sebanyak #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#. Kali seterusnya anda diserang, kerosakan akan meningkat sebanyak #C0x5c9970#$(80+skillLevel*0.2-0.2)$%#C0x5B545B#. Satu kemalangan rawak akan memberi kesan kepada anda. [Bencana] tidak boleh bertindih. Apabila Sesshomaru hadir, kesan [Bencana] sentiasa wujud.',
		describe = 'When Sesshomaru is attacked, a random unit attacks Sesshomaru and the enemy will be possessed by [Disaster]; when Sesshomaru attacks, a random unit is attacked by Sesshomaru and the enemy will also be possessed by [Disaster]. While [Disaster] lasts, before each combination starts, the maximum health limit decreases by #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B#, dual defense decreases by #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, dual attack decreases by #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#. The next time you are hit, damage will increase by #C0x5c9970#$(80+skillLevel*0.2-0.2)$%#C0x5B545B#. A random misfortune will affect you. [Disaster] cannot be stacked. When Sesshomaru is present, the [Disaster] effect always exists.',
		starEffect = __data_t__starEffect[18416],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Khi Sesshomaru bị tấn công, đơn vị tấn công Sesshomaru sẽ liên tục bị  <Tai Ương>  nhập hai lần, mỗi lần nhập sẽ kèm theo ngẫu nhiên một đơn vị khác; Khi Sesshomaru tấn công, đơn vị bị Sesshomaru tấn công cũng sẽ liên tục bị  <Tai Ương>  nhập hai lần, mỗi lần nhập sẽ kèm theo ngẫu nhiên một đơn vị khác.',
		starEffectDesc = 'Enhance Effect: When Sesshomaru is attacked, the attacking unit on Sesshomaru will be afflicted by <Calamity> twice, each time accompanied randomly by another unit; When Sesshomaru attacks, the unit attacked by Sesshomaru will also be afflicted by <Calamity> twice, each time accompanied randomly by another unit.',
		starEffectDesc_en = 'Enhance Effect: When Sesshomaru is attacked, the attacking unit on Sesshomaru will be afflicted by <Calamity> twice, each time accompanied randomly by another unit; When Sesshomaru attacks, the unit attacked by Sesshomaru will also be afflicted by <Calamity> twice, each time accompanied randomly by another unit.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อเซสโชมารูถูกโจมตี ศัตรูที่โจมตีเขาจะได้รับ [คำสาปหายนะ] ติดต่อกัน 2 ครั้ง และแต่ละครั้งจะสุ่มส่งต่อคำสาปไปยังยูนิตอื่นอีก 1 ตัว; เมื่อเซสโชมารูโจมตี เป้าหมายที่ถูกโจมตีก็จะได้รับ [คำสาปหายนะ] ติดต่อกัน 2 ครั้ง และแต่ละครั้งจะสุ่มส่งต่อคำสาปไปยังยูนิตอื่นอีก 1 ตัวเช่นกัน',
		starEffectDesc_in = 'Tingkatkan efek: Ketika Sesshomaru diserang, unit yang menyerang Sesshomaru akan terus terkena <Tai Ương> dua kali, setiap kali dengan secara acak disertai unit lain; Ketika Sesshomaru menyerang, unit yang diserang oleh Sesshomaru juga akan terus terkena <Tai Ương> dua kali, setiap kali dengan secara acak disertai unit lain.',
		starEffectDesc_ph = 'Palakasin ang epekto: Kapag inatake si Sesshomaru, ang yunit na umatake kay Sesshomaru ay patuloy na mabibiktima ng <Tai Ương> nang dalawang beses, bawat pagsalakay ay may kasamang random na ibang yunit; Kapag umatake si Sesshomaru, ang yunit na inatake ni Sesshomaru ay patuloy ding mabibiktima ng <Tai Ương> nang dalawang beses, bawat pagsalakay ay may kasamang random na ibang yunit.',
		starEffectDesc_ma = 'Perkuat kesan: Apabila Sesshomaru diserang, unit yang menyerang Sesshomaru akan terus mengalami <Tai Ương> sebanyak dua kali, setiap kali disertai secara rawak dengan unit lain; Apabila Sesshomaru menyerang, unit yang diserang oleh Sesshomaru juga akan terus mengalami <Tai Ương> sebanyak dua kali, setiap kali disertai secara rawak dengan unit lain.',
