	[18513] = {
		id = 18513,
		skillName_vn = 'Tia sáng đông lạnh',
		skillName_en = 'Frozen Ray',
		skillName_th = 'ลำแสงเยือกแข็ง',
		skillName_in = 'Sinar Beku',
		skillName_ph = 'Frozen Ray',
		skillName_ma = 'Sinar Beku',
		skillName = 'Frozen Ray',
		describe_vn = 'Tuyết Đồng Tử phát ra tia sáng đóng băng tấn công mục tiêu hàng ngang của địch, gây ra 490% thuộc tính (Công Phép, Công Vật Lý, phòng pháp, phòng vật lý ngẫu nhiên một loại)+$(skillLevel*4*24)$ sát thương#C0xF13B54#pháp thuật#C0x5B545B#, và thêm cho bản thân một lá chắn băng có thể hấp thụ 180% thuộc tính (dựa trên loại hệ số sát thương ngẫu nhiên lần này chọn loại ngược lại, tức là Công Phép tương ứng với phòng vật lý) trong 2 lượt.',
		describe_en = 'Snow Doll emits a freezing beam that attacks a horizontal line of enemies, dealing 490% of a randomly chosen attribute (Magic Attack, Physical Attack, Magic Defense, or Physical Defense) + $(skillLevel*4*24)$ damage. It also grants itself an ice shield that can absorb 180% of the attribute (based on the opposite attribute type selected this time, meaning Magic Attack corresponds to Physical Defense) for 2 turns.',
		describe_th = 'ตุ๊กตาหิมะปล่อยลำแสงเยือกแข็งโจมตีเป้าหมายในแนวขวางของศัตรู สร้างความเสียหาย 490% ของคุณสมบัติที่เลือกแบบสุ่ม (พลังเวท เวทมนตร์ พลังป้องกันเวท พลังป้องกันกายภาพ) + $(skillLevel*4*24)$ และยังเพิ่มโล่เย็นที่สามารถดูดซับความเสียหาย 180% ของคุณสมบัติ (โดยใช้ประเภทคุณสมบัติตรงกันข้ามที่เลือกในครั้งนี้ เช่น พลังเวทตรงกับพลังป้องกันกายภาพ) เป็นเวลา 2 เทิร์น',
		describe_in = 'Boneka Salju memancarkan sinar beku yang menyerang bar horizontal musuh, memberikan 490% dari atribut acak (Serangan Magic, Serangan Fisik, Pertahanan Magic, atau Pertahanan Fisik) + $(skillLevel*4*24)$ kerusakan. Juga memberikan perisai es yang dapat menyerap 180% atribut (berdasarkan jenis atribut kebalikan yang dipilih kali ini, misalnya Serangan Magic berbanding Pertahanan Fisik) selama 2 giliran.',
		describe_ph = 'Nagpapalabas ang Snow Doll ng isang nagyeyelong sinag na sumasalakay sa hanay na pahalang ng mga kalaban, na nagdudulot ng 490% ng isang random na katangian (Magic Attack, Physical Attack, Magic Defense, o Physical Defense) + $(skillLevel*4*24)$ na pinsala. Nagbibigay din ito ng ice shield sa sarili na kayang sumipsip ng 180% ng katangian (batay sa kabaligtarang uri ng katangiang napili ngayong beses, ibig sabihin Magic Attack ay tumutugma sa Physical Defense) sa loob ng 2 turno.',
		describe_ma = 'Boneka Salji mengeluarkan pancaran beku yang menyerang baris mendatar musuh, menyebabkan 490% sifat (Serangan Sihir, Serangan Fizikal, Pertahanan Sihir, atau Pertahanan Fizikal yang dipilih secara rawak) + $(skillLevel*4*24)$ kerosakan. Juga menambah perisai ais yang boleh menyerap 180% sifat (berdasarkan jenis sifat bertentangan yang dipilih kali ini, iaitu Serangan Sihir sepadan dengan Pertahanan Fizikal) selama 2 pusingan.',
		describe = 'Snow Doll emits a freezing beam that attacks a horizontal line of enemies, dealing 490% of a randomly chosen attribute (Magic Attack, Physical Attack, Magic Defense, or Physical Defense) + $(skillLevel*4*24)$ damage. It also grants itself an ice shield that can absorb 180% of the attribute (based on the opposite attribute type selected this time, meaning Magic Attack corresponds to Physical Defense) for 2 turns.',
		simDesc_vn = 'Tuyết Đồng Tử phóng ra chùm ánh sáng đóng băng tấn công mục tiêu hàng ngang của đối phương và thêm một lá chắn cho bản thân.',
		simDesc_en = 'Tuyet Dong Tu releases a beam of freezing light that attacks a horizontal line of enemy targets and adds a shield to himself.',
		simDesc_th = 'ทุยเย็ต ตง ตู่ ปล่อยลำแสงเย็นจัดโจมตีเป้าหมายในแนวนอนของศัตรูและเพิ่มโล่ให้ตัวเอง',
		simDesc_in = 'Tuyet Dong Tu melepaskan pancaran cahaya beku yang menyerang deretan target horizontal musuh dan menambahkan perisai untuk dirinya sendiri.',
		simDesc_ph = 'Pinakakawalan ni Tuyet Dong Tu ang isang sinag ng nagyeyelong liwanag na umaatake sa pahalang na mga target ng kalaban at nagdaragdag ng isang kalasag para sa kanyang sarili.',
		simDesc_ma = 'Tuyet Dong Tu melepaskan pancaran cahaya beku yang menyerang baris mendatar sasaran musuh dan menambah perisai untuk dirinya sendiri.',
		simDesc = 'Tuyet Dong Tu releases a beam of freezing light that attacks a horizontal line of enemy targets and adds a shield to himself.',
		starEffect = __data_t__starEffect[18513],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Hệ số khiên tăng lên 220%.',
		starEffectDesc = 'Enhanced effect: Shield coefficient increased to 220%.',
