	[18522] = {
		id = 18522,
		skillName_vn = 'Gió đông lạnh',
		skillName_en = 'Cold east wind',
		skillName_th = 'ลมหนาวจากทิศตะวันออก',
		skillName_in = 'Angin timur dingin',
		skillName_ph = 'Malamig na hangin mula sa silangan',
		skillName_ma = 'Angin timur sejuk',
		skillName = 'Cold east wind',
		describe_vn = 'Băng Quỷ Hộ thổi khí lạnh đóng băng về phía mục tiêu đơn phía địch, gây #C0x3D8A99#150% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đồng thời thêm cho bản thân một lá chắn băng có thể hấp thụ 250% phòng ngự (loại phòng ngự cao hơn trong hai loại) trong 2 lượt',
		describe_en = 'Ice Demon Guard blows a freezing chill toward a single enemy target, dealing #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, and simultaneously grants a frost shield to yourself that absorbs 250% defense (the higher defense type of the two) for 2 turns.',
		describe_th = 'ปีศาจน้ำแข็งส่งลมเย็นจัดไปยังเป้าหมายศัตรูเดี่ยว ทำให้เกิดความเสียหายเวท #C0x3D8A99#150% พลังเวท#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวท #C0x5B545B# พร้อมกับเพิ่มโล่เย็นแข็งให้ตัวเองซึ่งสามารถดูดซับการป้องกัน 250% (ประเภทการป้องกันที่สูงกว่าทั้งสองประเภท) เป็นเวลา 2 เทิร์น',
		describe_in = 'Penjaga Iblis Es meniup udara dingin yang membekukan ke arah satu target musuh, menyebabkan #C0x3D8A99#150% Serangan Magical#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Magis #C0x5B545B#, sekaligus menambahkan perisai es pada diri sendiri yang dapat menyerap 250% pertahanan (jenis pertahanan yang lebih tinggi dari kedua jenis) selama 2 giliran.',
		describe_ph = 'Ang Nagbabantay ng Demon ng Yelo ay humihip ng malamig na hangin na nagpapalamig sa isang target na kalaban, nagdudulot ng #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sakit na Magic #C0x5B545B#, kasabay ng pagdagdag sa sarili ng isang yelo na kalasag na maaaring sumipsip ng 250% depensa (ang mas mataas na uri ng depensa sa dalawa) sa loob ng 2 na turn.',
		describe_ma = 'Penjaga Iblis Ais meniup udara sejuk yang membekukan ke arah satu sasaran musuh, menyebabkan #C0x3D8A99#150% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, sekaligus menambah perisai ais kepada diri sendiri yang boleh menyerap 250% pertahanan (jenis pertahanan yang lebih tinggi dari kedua-dua jenis) selama 2 pusingan.',
		describe = 'Ice Demon Guard blows a freezing chill toward a single enemy target, dealing #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, and simultaneously grants a frost shield to yourself that absorbs 250% defense (the higher defense type of the two) for 2 turns.',
		simDesc_vn = 'Băng Quỷ Hộ thổi hơi lạnh đóng băng về phía mục tiêu đơn lẻ của đối phương.',
		simDesc_en = 'The Demon Ice Guard breathes icy cold air to freeze a single enemy target.',
		simDesc_th = 'นักบอดีน้ำแข็งปีศาจพ่นลมหายใจเย็นจัดไปยังเป้าหมายเดียวนั่นคือศัตรู',
		simDesc_in = 'Penjaga Es Iblis menghembuskan udara dingin membekukan ke arah satu target musuh.',
		simDesc_ph = 'Ang Bandila ng Demonyong Yelo ay humihip ng malamig na hangin upang i-freeze ang isang kalabang target.',
		simDesc_ma = 'Penjaga Ais Syaitan menghembuskan udara sejuk membekukan ke arah satu sasaran musuh.',
		simDesc = 'The Demon Ice Guard breathes icy cold air to freeze a single enemy target.',
		zawakeEffect = __data_t__zawakeEffect[18522],
		-- {79002}
		zawakeEffectDesc = 'The Ice Demon Guard blows freezing cold air to freeze a single enemy target, dealing #C0x3D8A99#150% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, and grants self an ice shield that can absorb 250% defense (the higher of the two defense types) for 3 turns',
