	[18523] = {
		id = 18523,
		skillName_vn = 'Đâm băng',
		skillName_en = 'Stab ice',
		skillName_th = 'แทงน้ำแข็ง',
		skillName_in = 'Tusuk es',
		skillName_ph = 'Saksak ng yelo',
		skillName_ma = 'Tikus ais',
		skillName = 'Stab ice',
		describe_vn = 'Băng Quỷ Hộ ngưng tụ băng và dùng cơ thể cứng như thép đập vào hàng mục tiêu phía địch, gây 500% thuộc tính (Phép Công, vật công, Phép Phòng, vật phòng ngẫu nhiên một loại) +$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đồng thời thêm cho bản thân một lá chắn băng có thể hấp thụ 180% thuộc tính (dựa trên loại hệ số sát thương ngẫu nhiên lần này chọn loại ngược lại, tức Phép Công tương ứng với vật phòng) trong 2 lượt',
		describe_en = 'Ice Demon Guard condenses ice and uses a body as hard as steel to slam into rows of enemy targets, dealing 500% attribute damage (randomly one of Magic Attack, Physical Attack, Magic Defense, Physical Defense) + $(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, and simultaneously grants itself an ice shield that can absorb 180% attribute damage (based on the opposite attribute of the randomly chosen damage type, e.g. Magic Attack corresponds to Physical Defense) for 2 turns.',
		describe_th = 'บังภูติน้ำแข็งรวมตัวน้ำแข็งและใช้ร่างกายที่แข็งเหมือนเหล็กทุบใส่แถวเป้าหมายฝ่ายศัตรู สร้างความเสียหาย 500% ตามคุณสมบัติ (สุ่มหนึ่งอย่างระหว่าง พลังเวท การโจมตีทางกายภาพ การป้องกันเวท การป้องกันทางกายภาพ) + $(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# พร้อมทั้งเพิ่มโล่น้ำแข็งให้ตัวเองที่สามารถดูดซับความเสียหายได้ 180% ตามคุณสมบัติ (โดยใช้ค่าความเสียหายชนิดตรงข้ามที่สุ่มได้ เช่น พลังเวท จะสอดคล้องกับการป้องกันทางกายภาพ) เป็นเวลา 2 เทิร์น',
		describe_in = 'Penjaga Iblis Es mengkondensasi es dan menggunakan tubuh yang sekeras baja untuk menghantam barisan target musuh, menyebabkan kerusakan atribut sebesar 500% (acak salah satu dari Serangan Sihir, Serangan Fisik, Pertahanan Sihir, Pertahanan Fisik) + $(skillLevel*4*24)$ #C0xF13B54# Kerusakan Magis #C0x5B545B#, sekaligus menambahkan perisai es pada dirinya sendiri yang dapat menyerap 180% kerusakan atribut (berdasarkan jenis atribut berlawanan yang dipilih secara acak kali ini, misalnya Serangan Sihir berpasangan dengan Pertahanan Fisik) selama 2 giliran.',
		describe_ph = 'Anghel ng Yelo ay nagsisiksik ng yelo at ginagamit ang katawan na matigas tulad ng bakal upang hampasin ang hanay ng mga target na kaaway, nagdudulot ng 500% na katangiang pinsala (pumili ng isa nang random mula sa Magic Attack, Physical Attack, Magic Defense, Physical Defense) + $(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, kasabay nito ay nagbibigay sa sarili ng isang yelong kalasag na kayang sumipsip ng 180% na katangiang pinsala (batay sa kabaligtarang uri ng rating ng pinsalang napili sa pagkakataong ito, halimbawa Magic Attack ay tumutugma sa Physical Defense) sa loob ng 2 turn.',
		describe_ma = 'Pengawal Iblis Ais memampatkan ais dan menggunakan badan yang keras seperti besi untuk memukul barisan sasaran musuh, menyebabkan 500% kerosakan atribut (rawak salah satu dari Serangan Sihir, Serangan Fizikal, Pertahanan Sihir, Pertahanan Fizikal) + $(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, dan pada masa yang sama menambahkan perisai ais pada dirinya yang boleh menyerap 180% kerosakan atribut (berdasarkan jenis atribut lawan yang dipilih secara rawak kali ini, contohnya Serangan Sihir bersesuaian dengan Pertahanan Fizikal) selama 2 pusingan.',
		describe = 'Ice Demon Guard condenses ice and uses a body as hard as steel to slam into rows of enemy targets, dealing 500% attribute damage (randomly one of Magic Attack, Physical Attack, Magic Defense, Physical Defense) + $(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, and simultaneously grants itself an ice shield that can absorb 180% attribute damage (based on the opposite attribute of the randomly chosen damage type, e.g. Magic Attack corresponds to Physical Defense) for 2 turns.',
		simDesc_vn = 'Băng Quỷ Hộ tạo ra khối băng và dùng cơ thể cứng như thép đập vào mục tiêu hàng ngang của đối phương, đồng thời thêm một lá chắn cho bản thân.',
		simDesc_en = 'The Ice Demon Guard creates a block of ice and uses a steel-hard body to strike the opponent\'s horizontal target, while simultaneously adding a shield to itself.',
		simDesc_th = 'ผู้พิทักษ์ปีศาจน้ำแข็งสร้างบล็อกน้ำแข็งและใช้ร่างกายแข็งเหมือนเหล็กกระแทกเป้าหมายในแนวนอนของศัตรู พร้อมทั้งเพิ่มโล่ให้ตัวเองด้วย',
		simDesc_in = 'Penjaga Iblis Es menciptakan blok es dan menggunakan tubuh yang keras seperti baja untuk memukul target horizontal musuh, sekaligus menambahkan perisai untuk dirinya sendiri.',
		simDesc_ph = 'Ang Ice Demon Guard ay lumilikha ng bloke ng yelo at ginagamit ang katawan na matigas na parang bakal upang hampasin ang pahalang na target ng kalaban, sabay na nagdaragdag ng kalasag para sa sarili.',
		simDesc_ma = 'Penjaga Syaitan Ais menghasilkan ketulan ais dan menggunakan badan yang keras seperti besi untuk memukul sasaran mendatar musuh, sambil menambah perisai untuk dirinya sendiri.',
		simDesc = 'The Ice Demon Guard creates a block of ice and uses a steel-hard body to strike the opponent\'s horizontal target, while simultaneously adding a shield to itself.',
		starEffect = __data_t__starEffect[18523],
