	[18532] = {
		id = 18532,
		skillName_vn = 'Tai họa không đơn lẻ',
		skillName_en = 'Disaster is not isolated',
		skillName_th = 'ภัยพิบัติไม่ใช่เหตุการณ์เดี่ยว',
		skillName_in = 'Bencana bukanlah kejadian tunggal',
		skillName_ph = 'Ang sakuna ay hindi nag-iisa',
		skillName_ma = 'Bencana bukanlah peristiwa tunggal',
		skillName = 'Disaster is not isolated',
		describe_vn = 'Tuyết Yêu Nữ dùng thân ảnh ma quái tấn công mục tiêu đơn phía địch, gây #C0x3D8A99#150% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, nếu mục tiêu có hiệu ứng tiêu cực hoặc bị khống chế, có 100% xác suất đóng băng mục tiêu trong 1 lượt (đóng băng: không thể hành động, khi mục tiêu bị đóng băng mất hơn 10% sinh mệnh sẽ giải trừ)',
		describe_en = 'Snow Enchantress uses a ghostly form to attack a single enemy target, dealing 150% Magic Attack + $(skillLevel*4*24)$ Magic Damage. If the target has a negative effect or is controlled, there is a 100% chance to freeze the target for 1 turn (frozen: cannot act, and the freeze is removed if the target loses more than 10% HP).',
		describe_th = 'หญิงสาวหิมะใช้ร่างผีสิงโจมตีเป้าหมายฝ่ายศัตรูเดียว ทำให้เสียหายเวท 150% + $(skillLevel*4*24)$ ความเสียหายเวท หากเป้าหมายมีสถานะลบหรือถูกควบคุม มีโอกาส 100% ที่จะทำให้เป้าหมายแข็งท้านเป็นเวลา 1 เทิร์น (แข็งท้าน: ไม่สามารถทำการใดๆ ได้ และสถานะแข็งท้านจะถูกลบหากเป้าหมายเสียชีวิตมากกว่า 10% ของพลังชีวิต)',
		describe_in = 'Putri Salju menggunakan bentuk gaib untuk menyerang satu target musuh, memberikan 150% Serangan Sihir + $(skillLevel*4*24)$ Kerusakan Sihir. Jika target memiliki efek negatif atau sedang terkendali, ada peluang 100% untuk membekukan target selama 1 giliran (beku: tidak bisa bertindak, dan efek beku akan hilang jika target kehilangan lebih dari 10% HP).',
		describe_ph = 'Gumagamit ang Snow Enchantress ng isang mahiwagang anyo upang atakihin ang isang target na kaaway, na nagdudulot ng 150% Magic Attack + $(skillLevel*4*24)$ Magic Damage. Kung ang target ay may negatibong epekto o kontrolado, may 100% tsansa na mapagyelo ang target ng 1 turn (frozen: hindi makakakilos, at nawawala ang effect kung ang target ay mawalan ng higit sa 10% HP).',
		describe_ma = 'Puteri Salji menggunakan bentuk ghaib untuk menyerang satu sasaran musuh, memberikan 150% Serangan Sihir + $(skillLevel*4*24)$ Kerosakan Sihir. Jika sasaran mempunyai kesan negatif atau dikawal, terdapat peluang 100% untuk membekukan sasaran selama 1 giliran (beku: tidak boleh bertindak, dan beku akan dibuang jika sasaran kehilangan lebih daripada 10% HP).',
		describe = 'Snow Enchantress uses a ghostly form to attack a single enemy target, dealing 150% Magic Attack + $(skillLevel*4*24)$ Magic Damage. If the target has a negative effect or is controlled, there is a 100% chance to freeze the target for 1 turn (frozen: cannot act, and the freeze is removed if the target loses more than 10% HP).',
		simDesc_vn = 'Tuyết Yêu Nữ tấn công mục tiêu đơn lẻ của đối phương bằng hình dáng quái dị.',
		simDesc_en = 'The Snow Demoness attacks a single enemy target with a grotesque form.',
		simDesc_th = 'หญิงปีศาจหิมะโจมตีเป้าหมายคู่ต่อสู้ทีละหนึ่งด้วยรูปร่างประหลาด',
		simDesc_in = 'Gadis Salju Seram menyerang satu sasaran musuh dengan bentuk yang aneh.',
		simDesc_ph = 'Ang Snow Demoness ay umatake sa isang katunggaling target gamit ang kakaibang anyo.',
		simDesc_ma = 'Perempuan Salji Seram menyerang satu sasaran musuh dengan bentuk aneh.',
		simDesc = 'The Snow Demoness attacks a single enemy target with a grotesque form.',
		zawakeEffect = __data_t__zawakeEffect[18532],
		-- {79002}
		zawakeEffectDesc = 'The Snow Demoness uses a ghostly shadow to attack a single enemy target, dealing #C0x3D8A99#150% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. If the target has a negative effect or control effect, there is a 100% chance to freeze the target for 1 turn (freeze: unable to act, if the target loses more than 20% HP during freeze, the freeze is removed)',
		zawakeEffectDesc_en = 'The Snow Demoness uses a ghostly shadow to attack a single enemy target, dealing #C0x3D8A99#150% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. If the target has a negative effect or control effect, there is a 100% chance to freeze the target for 1 turn (freeze: unable to act, if the target loses more than 20% HP during freeze, the freeze is removed)',
		zawakeEffectDesc_th = 'นางปีศาจหิมะใช้เงาผีโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายเวทย์มนตร์ #C0x3D8A99#150% พลังเวทย์มนตร์#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทย์มนตร์ #C0x5B545B# หากเป้าหมายมีสถานะลบหรือถูกควบคุม มีโอกาส 100% ที่จะทำให้เป้าหมายถูกแช่แข็ง 1 เทิร์น (แช่แข็ง: ไม่สามารถกระทำการใดๆ ได้ หากเป้าหมายเสียชีวิตเกิน 20% ในขณะที่แช่แข็ง จะถูกยกเลิก)',
		zawakeEffectDesc_in = 'Wanita Setan Salju menggunakan bayangan hantu untuk menyerang satu target musuh, memberikan #C0x3D8A99#150% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Jika target memiliki efek negatif atau kontrol, ada peluang 100% untuk membekukan target selama 1 giliran (membekukan: tidak dapat bertindak, jika target kehilangan lebih dari 20% HP selama pembekuan, pembekuan akan dihapus)',
		zawakeEffectDesc_ph = 'Ang Snow Demoness ay gumagamit ng daga-dagat ng multo para atakihin ang isang target na kalaban, na nagdudulot ng #C0x3D8A99#150% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. Kung ang target ay may negatibong epekto o kontrol, may 100% tsansa na i-freeze ang target ng 1 turn (freeze: hindi makakilos, kapag ang target ay nawalan ng higit sa 20% HP habang naka-freeze ay aalisin ang freeze)',
		zawakeEffectDesc_ma = 'Wanita Iblis Salji menggunakan bayangan hantu untuk menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#150% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Jika sasaran mempunyai kesan negatif atau kawalan, ada peluang 100% untuk membekukan sasaran selama 1 pusingan (membekukan: tidak dapat bertindak, jika sasaran kehilangan lebih daripada 20% HP semasa pembekuan, pembekuan akan dibuang)',
		zawakeEffectDesc_vn = 'Tuyết Yêu Nữ dùng bóng dáng ma quái tấn công mục tiêu đơn địch, gây #C0x3D8A99#150% Công Phép#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, nếu mục tiêu có hiệu ứng tiêu cực hoặc kiểm soát, thì có 100% xác suất đóng băng mục tiêu 1 lượt (đóng băng: không thể hành động, khi mục tiêu mất hơn 20% sinh mệnh trong thời gian đóng băng thì giải trừ)',
