	[18533] = {
		id = 18533,
		skillName_vn = 'Đá băng bão tố',
		skillName_en = 'Storm Ice',
		skillName_th = 'น้ำแข็งพายุ',
		skillName_in = 'Es Badai',
		skillName_ph = 'Yelong Bagyo',
		skillName_ma = 'Ais Ribut',
		skillName = 'Storm Ice',
		describe_vn = 'Tuyết Yêu Nữ triệu hồi băng vụn đầy trời cuốn theo gió mạnh tấn công toàn bộ mục tiêu phía địch, gây #C0x3D8A99#130% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đối với mục tiêu có tốc độ thấp hơn bản thân có 80% xác suất đóng băng trong 1 lượt (đóng băng: hiệu ứng khống chế, không thể hành động, khi nhận sát thương vượt quá 10% sinh mệnh của mục tiêu sẽ giải trừ), sau khi sử dụng bản thân sẽ ẩn thân trong 1 lượt (ẩn thân: hiệu ứng đặc biệt, mục tiêu không thể bị chọn, có thể bị ảnh hưởng bởi tấn công phạm vi)',
		describe_en = 'Snow Enchantress summons a flurry of ice shards swept by strong winds to attack all enemy targets, dealing #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. Targets with lower speed than herself have an 80% chance to be frozen for 1 turn (frozen: a control effect that prevents actions; the effect is removed if the target takes damage exceeding 10% of its HP). After use, she will become hidden for 1 turn (hidden: a special effect where the target cannot be selected but can still be affected by area attacks).',
		describe_th = 'หญิงแม่มดหิมะเรียกเกล็ดน้ำแข็งเต็มฟ้าพัดโดยลมแรงโจมตีเป้าหมายฝ่ายศัตรูทั้งหมด สร้างความเสียหายเวทมนตร์ #C0x3D8A99#130% พลังเวท#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# กับเป้าหมายที่มีความเร็วต่ำกว่าเธอมีโอกาส 80% ที่จะถูกแช่แข็งเป็นเวลา 1 เทิร์น (แช่แข็ง: สถานะควบคุม ไม่สามารถกระทำการใดๆ ได้ สถานะจะถูกยกเลิกเมื่อได้รับความเสียหายเกิน 10% ของพลังชีวิต) หลังใช้สกิล จะซ่อนตัวเป็นเวลา 1 เทิร์น (ซ่อนตัว: สถานะพิเศษ เป้าหมายไม่สามารถถูกเลือก แต่ยังถูกโจมตีในพื้นที่ได้)',
		describe_in = 'Penyihir Salju memanggil serpihan es yang berterbangan tertiup angin kencang untuk menyerang semua target musuh, memberikan #C0x3D8A99#130% Tenaga Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Target yang memiliki kecepatan lebih rendah darinya memiliki peluang 80% untuk membeku selama 1 giliran (membeku: efek kontrol, tidak bisa bertindak, efek ini akan hilang jika target menerima kerusakan lebih dari 10% HP). Setelah digunakan, dia akan menyembunyikan diri selama 1 giliran (menyembunyikan diri: efek khusus, target tidak dapat dipilih, tetapi masih bisa terkena serangan area).',
		describe_ph = 'Ang Babaeng Mangkukulong-niyebe ay nagmumungkahi ng mga pagyeyel ng yelo na hinahawi ng malakas na hangin upang atakihin ang lahat ng mga target na nasa pakanan, nagdudulot ng #C0x3D8A99#130% Kapangyarihan ng Salamangka#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Pinsalang Salamangka #C0x5B545B#. Ang mga target na mas mababa ang bilis kaysa sa kanya ay may 80% tsansa na mapagal sa loob ng 1 turno (pagyeyel: epektong kontrol na pumipigil sa pagkilos; mawawala kapag nakatanggap ng pinsalang higit sa 10% ng HP ng target). Pagkatapos gamitin, siya ay magiging tago sa loob ng 1 turno (tago: espesyal na epekto kung saan ang target ay hindi pwedeng piliin ngunit maaari pa ring maapektuhan ng mga pag-atake sa lugar).',
		describe_ma = 'Perempuan Salji memanggil serpihan ais yang diterbangkan angin kencang untuk menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#130% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Sasaran dengan kelajuan lebih rendah daripadanya mempunyai 80% peluang untuk dibekukan selama 1 pusingan (beku: kesan kawalan, tidak dapat bertindak, kesan akan hilang jika sasaran menerima kerosakan melebihi 10% HP). Selepas digunakan, dia akan menyembunyikan diri selama 1 pusingan (menyembunyikan diri: kesan khas, sasaran tidak boleh dipilih tetapi masih boleh terjejas oleh serangan kawasan).',
		describe = 'Snow Enchantress summons a flurry of ice shards swept by strong winds to attack all enemy targets, dealing #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. Targets with lower speed than herself have an 80% chance to be frozen for 1 turn (frozen: a control effect that prevents actions; the effect is removed if the target takes damage exceeding 10% of its HP). After use, she will become hidden for 1 turn (hidden: a special effect where the target cannot be selected but can still be affected by area attacks).',
		simDesc_vn = 'Tuyết Yêu Nữ triệu hồi bão tuyết cuốn theo gió mạnh tấn công tất cả mục tiêu của đối phương, có khả năng làm đông mục tiêu có tốc độ thấp hơn bản thân, và sau khi sử dụng sẽ trở nên vô hình.',
		simDesc_en = 'The Snow Sorceress summons a blizzard accompanied by strong winds to attack all enemy targets, capable of freezing targets slower than herself, and becomes invisible after use.',
		simDesc_th = 'แม่มดหิมะเรียกพายุหิมะพัดแรงโจมตีเป้าหมายศัตรูทั้งหมด สามารถทำให้เป้าหมายที่เคลื่อนที่ช้ากว่าตัวเองถูกแช่แข็ง และจะกลายเป็นล่องหนหลังใช้สกิล',
		simDesc_in = 'Penyihir Salju memanggil badai salju yang disertai angin kencang untuk menyerang semua target musuh, mampu membekukan target yang lebih lambat darinya, dan menjadi tidak terlihat setelah digunakan.',
		simDesc_ph = 'Ang Snow Sorceress ay tumatawag ng bagyong niyebe na may malalakas na hangin upang atakihin ang lahat ng mga kalaban, kayang i-freeze ang mga target na mas mabagal sa kanya, at nagiging invisible pagkatapos gamitin.',
		simDesc_ma = 'Ahli Sihir Salji memanggil ribut salji disertai angin kencang untuk menyerang semua sasaran musuh, berupaya membekukan sasaran yang lebih perlahan daripadanya, dan menjadi tidak kelihatan selepas digunakan.',
		simDesc = 'The Snow Sorceress summons a blizzard accompanied by strong winds to attack all enemy targets, capable of freezing targets slower than herself, and becomes invisible after use.',
		starEffect = __data_t__starEffect[18533],
		-- {11}
		starEffectDesc_vn = 'Cơ sở: Có 20% xác suất đóng băng, xác suất đóng băng đối với mục tiêu có tốc độ thấp hơn sẽ tăng lên 100%.',
		starEffectDesc = 'Base: 20% chance to freeze, chance to freeze against targets with lower speed increases to 100%.',
		starEffectDesc_en = 'Base: 20% chance to freeze, chance to freeze against targets with lower speed increases to 100%.',
		starEffectDesc_th = 'ฐาน: มีโอกาสเยือกแข็ง 20%, โอกาสเยือกแข็งกับเป้าหมายที่มีความเร็วต่ำกว่าจะเพิ่มขึ้นเป็น 100%',
		starEffectDesc_in = 'Dasar: 20% kemungkinan membekukan, kemungkinan membekukan terhadap target dengan kecepatan lebih rendah meningkat menjadi 100%.',
		starEffectDesc_ph = 'Base: 20% na tsansa na mag-freeze, ang tsansa na mag-freeze laban sa target na may mas mababang bilis ay tumataas sa 100%.',
		starEffectDesc_ma = 'Asas: 20% peluang untuk membekukan, peluang membekukan terhadap sasaran dengan kelajuan lebih rendah meningkat kepada 100%.',
		zawakeEffect = __data_t__zawakeEffect[18533],
		-- {79003}
		zawakeEffectDesc = 'Snow Enchantress summons ice shards swirling in the sky driven by strong wind to attack all enemy targets, dealing #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. Against targets with lower speed than herself, there is an 80% chance to freeze for 1 turn (freeze: control effect, cannot act, when receiving accumulated damage exceeding 20% of the target\'s HP then removed). After use, she will hide for 2 turns (hide: special effect, the target cannot be selected, but can be affected by area attacks).',
		zawakeEffectDesc_en = 'Snow Enchantress summons ice shards swirling in the sky driven by strong wind to attack all enemy targets, dealing #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. Against targets with lower speed than herself, there is an 80% chance to freeze for 1 turn (freeze: control effect, cannot act, when receiving accumulated damage exceeding 20% of the target\'s HP then removed). After use, she will hide for 2 turns (hide: special effect, the target cannot be selected, but can be affected by area attacks).',
		zawakeEffectDesc_th = 'สาวเสน่ห์น้ำแข็ง (#ma mau#) เรียกเศษน้ำแข็งเต็มท้องฟ้าพัดด้วยลมแรงโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวทย์ #C0x3D8A99#130% พลังเวทย์#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทย์ #C0x5B545B# ต่อเป้าหมายที่มีความเร็วต่ำกว่าเธอ มีโอกาส 80% ที่จะถูกแช่แข็งเป็นเวลา 1 เทิร์น (แช่แข็ง: เอฟเฟกต์ควบคุม, ไม่สามารถกระทำได้, เมื่อได้รับความเสียหายสะสมเกิน 20% ของพลังชีวิตเป้าหมายจะถูกปลดออก) หลังใช้จะซ่อนตัว 2 เทิร์น (ซ่อนตัว: เอฟเฟกต์พิเศษ, เป้าหมายไม่สามารถถูกเลือก, แต่ยังได้รับผลกระทบจากการโจมตีพื้นที่)',
		zawakeEffectDesc_in = 'Gadis Salju Memanggil serpihan es berterbangan di langit yang dibawa angin kencang menyerang semua musuh, memberikan #C0x3D8A99#130% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Sulap #C0x5B545B#. Terhadap target dengan kecepatan lebih rendah darinya, ada peluang 80% untuk membekukan selama 1 giliran (membekukan: efek kontrol, tidak bisa bertindak, saat menerima akumulasi kerusakan melebihi 20% HP target efek ini dicabut). Setelah digunakan, dia akan bersembunyi selama 2 giliran (bersembunyi: efek khusus, target tidak dapat dipilih, namun dapat terpengaruh oleh serangan area).',
		zawakeEffectDesc_ph = 'Ang Snow Enchantress ay tumatawag ng mga pira-pirasong yelo na umiikot sa langit na hinihimok ng malakas na hangin upang atakihin ang lahat ng mga kaaway, na nagdudulot ng #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. Sa mga target na may mas mababang bilis kaysa sa kanya, may 80% tsansa na ma-freeze ng 1 round (freeze: control effect, hindi makakilos, kapag ang naipong pinsala ay lumampas sa 20% ng HP ng target ay mawawala ito). Pagkatapos gamitin ay magtatago siya ng 2 rounds (tago: special effect, ang target ay hindi pwedeng mapili, pero maaaring maapektuhan ng area attacks).',
		zawakeEffectDesc_ma = '#ma mau# Salji Penggoda memanggil serpihan ais berterbangan di angkasa yang dibawa angin kencang menyerang semua sasaran musuh, memberikan #C0x3D8A99#130% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Terhadap sasaran yang mempunyai kelajuan lebih rendah daripadanya, terdapat 80% kebarangkalian akan dibekukan selama 1 giliran (dibekukan: kesan kawalan, tidak boleh bertindak, apabila menerima kerosakan terkumpul melebihi 20% nyawa sasaran kesan ini akan dibuang). Selepas digunakan, dia akan bersembunyi selama 2 giliran (bersembunyi: kesan khas, sasaran tidak boleh dipilih, tetapi boleh terjejas oleh serangan kawasan).',
		zawakeEffectDesc_vn = 'Tuyết Yêu Nữ triệu hồi băng vụn đầy trời cuốn theo gió mạnh tấn công toàn bộ mục tiêu địch, gây #C0x3D8A99#130% Công Phép#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đối với mục tiêu có tốc độ thấp hơn bản thân có 80% xác suất đóng băng 1 lượt (đóng băng: hiệu ứng kiểm soát, không thể hành động, khi nhận sát thương tích lũy vượt quá 20% sinh mệnh của mục tiêu thì giải trừ), sau khi sử dụng bản thân sẽ ẩn thân 2 lượt (ẩn thân: hiệu ứng đặc biệt, mục tiêu không thể bị chọn, có thể bị ảnh hưởng bởi tấn công phạm vi)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '<Frozen> (Frozen: Cannot act, removed if target loses more than 20% HP while frozen)  ',
		zawakeSimpleDesc_en = '<Frozen> (Frozen: Cannot act, removed if target loses more than 20% HP while frozen)  ',
		zawakeSimpleDesc_th = '<แช่แข็ง> (แช่แข็ง: ไม่สามารถกระทำการได้ ยกเลิกเมื่อเป้าหมายเสีย HP เกิน 20% ระหว่างติดแช่แข็ง)',
		zawakeSimpleDesc_in = '<Beku> (Beku: Tidak bisa bergerak, efek hilang jika target kehilangan lebih dari 20% HP saat beku)  ',
		zawakeSimpleDesc_ph = '<Nagyelo> (Nagyelo: Hindi makakakilos, matatanggal kapag nabawasan ng higit 20% HP habang nagyeyelo)  ',
		zawakeSimpleDesc_ma = '<Beku> (Beku: Tidak boleh bertindak, akan hilang jika sasaran kehilangan lebih 20% HP ketika beku)  ',
