		skillName_ph = 'Umuusbong bola',
		skillName_ma = 'Bola bergolek',
		skillName = 'Rolling ball',
		describe_vn = 'Hải Cẩu Cầu hóa thân thành quả cầu băng lăn tấn công mục tiêu đơn phía địch, gây #C0x3D8A99#340% Phép Công#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, lần tiếp theo khi bị tấn công, gây sát thương phản đòn bằng 10% sinh mệnh đã mất của bản thân lên toàn bộ mục tiêu phía địch (sát thương này là sát thương thực)',
		describe_en = 'Seal Ball transforms into an ice rolling sphere to attack a single enemy target, dealing #C0x3D8A99#340% Magic Attack#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Magic Damage #C0x5B545B#. The next time it is attacked, it counterattacks, dealing true damage equal to 10% of its lost HP to all enemy targets.',
		describe_th = 'แมวน้ำบอลแปลงร่างเป็นลูกบอลน้ำแข็งกลิ้งโจมตีเป้าหมายฝ่ายศัตรูเดียว สร้างความเสียหาย #C0x3D8A99#340% พลังเวท#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# ครั้งถัดไปเมื่อถูกโจมตี จะสะท้อนความเสียหายเป็นจำนวน 10% ของพลังชีวิตที่สูญเสียไปให้แก่เป้าหมายฝ่ายศัตรูทั้งหมด (ความเสียหายนี้เป็นความเสียหายจริง)',
		describe_in = 'Seal Ball berubah menjadi bola es yang menggulung menyerang satu target musuh, memberikan #C0x3D8A99#340% Serangan Sihir#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Pada serangan berikutnya saat diserang, memberikan serangan balasan berupa 10% dari HP yang hilang kepada seluruh target musuh (kerusakan ini adalah kerusakan nyata).',
		describe_ph = 'Ang Seal Ball ay nagiging isang rolling ice sphere na umaatake sa isang target na kalaban, nagdudulot ng #C0x3D8A99#340% Magic Attack#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Magic Damage #C0x5B545B#. Sa susunod na tama kapag inatake, nagbibigay ito ng counter damage na katumbas ng 10% ng nawalang HP nito sa lahat ng kalabang target (ang damage na ito ay tunay na damage).',
		describe_ma = 'Seal Ball berubah menjadi bola ais yang bergolek menyerang satu sasaran musuh, memberikan #C0x3D8A99#340% Serangan Magik#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerosakan Magik #C0x5B545B#. Pada kali serangan seterusnya apabila diserang, memberikan serangan balas sebanyak 10% daripada nyawa yang hilang ke semua sasaran musuh (kerosakan ini adalah kerosakan sebenar).',
		describe = 'Seal Ball transforms into an ice rolling sphere to attack a single enemy target, dealing #C0x3D8A99#340% Magic Attack#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Magic Damage #C0x5B545B#. The next time it is attacked, it counterattacks, dealing true damage equal to 10% of its lost HP to all enemy targets.',
		simDesc_vn = 'Hải Bảo Cầu hóa thân thành quả cầu băng lăn lộn tấn công mục tiêu đơn lẻ của đối phương, khi bị tấn công lần tiếp theo, sẽ gây thêm sát thương phản đòn cho tất cả mục tiêu của đối phương dựa trên lượng máu đã mất.',
		simDesc_en = 'The Sea Treasure Orb transforms into an ice sphere that rolls and attacks a single enemy target. When attacked next time, it deals additional counter damage to all enemy targets based on the lost health.',
		simDesc_th = 'ไอเท็มทรัพย์สมบัติทางทะเลแปรสภาพเป็นลูกน้ำแข็งกลิ้งโจมตีเป้าหมายศัตรูเดียว เมื่อถูกรุกล้ำในครั้งถัดไป จะสร้างความเสียหายตอบโต้เพิ่มเติมแก่เป้าหมายศัตรูทั้งหมดตามปริมาณเลือดที่เสียไป',
		simDesc_in = 'Harta Laut berubah menjadi bola es yang berguling menyerang satu target musuh. Saat diserang berikutnya, akan memberikan kerusakan balasan tambahan kepada semua target musuh berdasarkan jumlah darah yang hilang.',
		simDesc_ph = 'Ang Sea Treasure Orb ay nagiging isang ice sphere na gumugulong at umaatake sa isang kalaban. Kapag itinarget sa susunod, magdudulot ito ng karagdagang counter na pinsala sa lahat ng kalaban base sa nawalang HP.',
		simDesc_ma = 'Harta Karun Laut berubah menjadi bola ais yang bergolek menyerang sasaran musuh tunggal. Apabila diserang kali berikutnya, ia akan memberikan kerosakan balas tambahan kepada semua sasaran musuh berdasarkan jumlah darah yang hilang.',
		simDesc = 'The Sea Treasure Orb transforms into an ice sphere that rolls and attacks a single enemy target. When attacked next time, it deals additional counter damage to all enemy targets based on the lost health.',
		starEffect = __data_t__starEffect[18613],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: <Khiêu khích> kẻ địch tấn công nhân vật có chỉ số tấn công cao nhất trong 1 lượt (Khiêu khích: hiệu ứng kiểm soát, buộc mục tiêu chọn mình làm mục tiêu tấn công).',
		starEffectDesc = 'Additional effect: <Taunt> forces enemies to attack the character with the highest attack stat for 1 turn (Taunt: a control effect that forces the target to choose the user as the attack target).',
		starEffectDesc_en = 'Additional effect: <Taunt> forces enemies to attack the character with the highest attack stat for 1 turn (Taunt: a control effect that forces the target to choose the user as the attack target).',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: <เย้ยหยัน> บังคับให้ศัตรูโจมตีตัวละครที่มีค่าสถานะโจมตีสูงสุดใน 1 เทิร์น (เย้ยหยัน: เอฟเฟกต์ควบคุมที่บังคับให้เป้าหมายเลือกผู้ใช้เป็นเป้าหมายโจมตี).',
		starEffectDesc_in = 'Efek tambahan: <Memancing> memaksa musuh menyerang karakter dengan statistik serangan tertinggi selama 1 giliran (Memancing: efek kontrol yang memaksa target untuk memilih pengguna sebagai target serangan).',
		starEffectDesc_ph = 'Karagdagang epekto: <Lukso> pinipilit ang mga kalaban na atakihin ang karakter na may pinakamataas na attack stat sa loob ng 1 turn (Lukso: isang control effect na pinipilit ang target na piliin ang user bilang target ng pag-atake).',
		starEffectDesc_ma = 'Kesan tambahan: <Mengejek> memaksa musuh menyerang watak yang mempunyai statistik serangan tertinggi selama 1 pusingan (Mengejek: kesan kawalan yang memaksa sasaran memilih pengguna sebagai sasaran serangan).',
		zawakeEffect = __data_t__zawakeEffect[18613],
		-- {79003}
		zawakeEffectDesc = 'Seal transforms into a rolling ice ball to attack a single enemy target, dealing 340% Magic Power + (skillLevel * 4 * 60) magic damage. The next time being attacked, it deals additional counterattack damage equal to 20% of its lost HP to all enemies (this damage is true damage).',
		zawakeEffectDesc_en = 'Seal transforms into a rolling ice ball to attack a single enemy target, dealing 340% Magic Power + (skillLevel * 4 * 60) magic damage. The next time being attacked, it deals additional counterattack damage equal to 20% of its lost HP to all enemies (this damage is true damage).',
		zawakeEffectDesc_th = 'แมวน้ำแปลงร่างเป็นลูกบอลน้ำแข็งกลิ้งโจมตีเป้าหมายเดี่ยวของฝ่ายตรงข้าม สร้างความเสียหายเวทมนตร์ 340% พลังเวท + (levelสกิล * 4 * 60) ครั้งต่อไปเมื่อถูกโจมตี สร้างความเสียหายตอบโต้เพิ่มขึ้นเท่ากับ 20% ของพลังชีวิตที่สูญเสียไปแก่ศัตรูทั้งหมด (ความเสียหายนี้เป็นความเสียหายจริง)',
		zawakeEffectDesc_in = 'Anjing laut berubah menjadi bola es bergulir menyerang satu target musuh, menyebabkan 340% Kekuatan Sihir + (levelKeahlian * 4 * 60) kerusakan sihir, pada serangan berikutnya saat diserang, menyebabkan tambahan kerusakan serangan balik sebesar 20% dari HP yang hilang ke semua musuh (kerusakan ini adalah kerusakan murni).',
		zawakeEffectDesc_ph = 'Ang seal ay nagiging isang gumugulong na bola ng yelo upang atakihin ang isang solong target ng kalaban, nagdudulot ng 340% Magic Power + (skillLevel * 4 * 60) na pinsalang mahika, sa susunod na pagkakataon kapag inatake, nagdudulot ng karagdagang counterattack damage na katumbas ng 20% ng nawalang HP sa lahat ng mga kalaban (ang pinsalang ito ay tunay na pinsala).',
		zawakeEffectDesc_ma = 'Anjing laut berubah menjadi bola ais bergolek menyerang sasaran musuh tunggal, menyebabkan 340% Kuasa Sihir + (tahapKemahiran * 4 * 60) kerosakan sihir, serangan seterusnya apabila diserang, memberikan kerosakan balas sebanyak 20% daripada darah yang hilang kepada semua musuh (kerosakan ini adalah kerosakan sebenar).',
		zawakeEffectDesc_vn = 'Hải cẩu hóa thân thành quả cầu băng lăn tấn công mục tiêu đơn lẻ của đối phương, gây 340% Công Phép + (skillLevel * 4 * 60) sát thương phép, lần tiếp theo khi bị tấn công, gây thêm sát thương phản đòn bằng 20% máu đã mất của bản thân lên toàn bộ kẻ địch (sát thương này là sát thương thực)',
