	[18633] = {
		id = 18633,
		skillName_vn = 'Gai Băng Nộ',
		skillName_en = 'Wrath Ice Girl',
		skillName_th = 'สาวน้ำแข็งแห่งความโกรธ',
		skillName_in = 'Gadis Es Amarah',
		skillName_ph = 'Galit na Babaeng Yelo',
		skillName_ma = 'Gadis Ais Amarah',
		skillName = 'Wrath Ice Girl',
		describe_vn = 'Diya Sea Lion gầm lên và triệu hồi các gai băng tấn công một mục tiêu kẻ địch, gây ra #C0x3D8A99#360% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#sát thương phép#C0x5B545B#. Lần tiếp theo bị tấn công, nó sẽ cộng thêm 10% lượng HP đã mất của chính mình dưới dạng sát thương hồi phục cho tất cả kẻ thù (sát thương này là sát thương thực sự)',
		describe_en = 'Diya Sea Lion roars and summons ice spikes to attack a single enemy target, dealing #C0x3D8A99#360% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B#. On the next attack received, it will add 10% of its lost HP as true damage healing to all enemies.',
		describe_th = 'สิงโตทะเลไดย่า เข้ามะล่อและเรียกหนามน้ำแข็งโจมตีเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#360%#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# ครั้งถัดไปที่ถูกโจมตี มันจะเพิ่ม 10% ของพลังชีวิตที่สูญเสียในรูปแบบความเสียหายที่ฟื้นฟูไปยังศัตรูทั้งหมด (ความเสียหายนี้เป็นความเสียหายจริง)',
		describe_in = 'Singanya Diya Sea Lion mengaum dan memanggil duri es untuk menyerang satu target musuh, memberikan #C0x3D8A99#360% Damage Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# damage sihir#C0x5B545B#. Serangan berikutnya yang diterima, akan menambahkan 10% dari HP yang hilang sebagai damage penyembuhan ke semua musuh (damage ini adalah damage nyata).',
		describe_ph = 'Ang Diyan Sea Lion ay umuungol at naglalabas ng mga tinik ng yelo upang atakihin ang isang target na kaaway, na nagdudulot ng #C0x3D8A99#360% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B#. Sa susunod na pagtanggap ng atake, magdadagdag ito ng 10% ng nawalang HP bilang true damage healing sa lahat ng mga kaaway.',
		describe_ma = 'Singa Laut Diya mengaum dan memanggil duri ais untuk menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#360% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# kerosakan sihir#C0x5B545B#. Serangan seterusnya yang diterima akan menambah 10% dari HP yang hilang sebagai kerosakan penyembuhan kepada semua musuh (kerosakan ini adalah kerosakan sebenar).',
		describe = 'Diya Sea Lion roars and summons ice spikes to attack a single enemy target, dealing #C0x3D8A99#360% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B#. On the next attack received, it will add 10% of its lost HP as true damage healing to all enemies.',
		simDesc_vn = 'Sư tử biển của Hoàng đế: Sư tử biển của Hoàng đế gầm lên, sau đó triệu hồi những gai băng để tấn công một mục tiêu kẻ thù. Lần tiếp theo bị tấn công, nó sẽ cộng thêm một phần HP đã mất của mình dưới dạng sát thương phản hồi lên tất cả kẻ thù.',
		simDesc_en = 'Emperor\'s Sea Lion: The Emperor\'s Sea Lion roars, then summons ice spikes to attack a target enemy. The next time it is attacked, it deals damage back to all enemies equal to a portion of its lost HP.',
		simDesc_th = 'สิงโตทะเลจักรพรรดิ: สิงโตทะเลจักรพรรดิคำราม แล้วเรียกยอดแหลมเย็นจัดโจมตีเป้าหมายศัตรู ครั้งถัดไปที่ถูกโจมตี มันจะสะท้อนความเสียหายกลับไปยังศัตรูทั้งหมดเท่ากับบางส่วนของพลังชีวิตที่สูญเสียไป',
		simDesc_in = 'Singa Laut Kaisar: Singa Laut Kaisar mengaum, lalu memanggil duri es untuk menyerang musuh target. Berikutnya saat diserang, ia akan memberikan damage pantulan ke semua musuh sebesar sebagian dari HP yang hilang.',
		simDesc_ph = 'Leon ng Dagat ng Emperador: Umuungal ang Leon ng Dagat ng Emperador, pagkatapos ay nagmumungkahi ng mga tinik ng yelo para atakihin ang isang target na kaaway. Sa susunod na atakihin, magbabalik ito ng pinsala sa lahat ng kaaway na katumbas ng bahagi ng nawalang HP nito.',
		simDesc_ma = 'Singa Laut Maharaja: Singa Laut Maharaja mengaum, kemudian memanggil duri ais untuk menyerang satu musuh sasaran. Serangan seterusnya terhadapnya akan memberikan kerosakan pemantulan kepada semua musuh bersamaan dengan sebahagian HP yang hilang.',
		simDesc = 'Emperor\'s Sea Lion: The Emperor\'s Sea Lion roars, then summons ice spikes to attack a target enemy. The next time it is attacked, it deals damage back to all enemies equal to a portion of its lost HP.',
		starEffect = __data_t__starEffect[18633],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: <Khiêu khích> kẻ địch tấn công nhân vật có chỉ số tấn công cao nhất trong 1 lượt (Khiêu khích: hiệu ứng kiểm soát, buộc mục tiêu chọn mình làm mục tiêu tấn công).',
		starEffectDesc = 'Additional effect: <Taunt> enemies attack the character with the highest attack stat for 1 turn (Taunt: a control effect that forces the target to choose the taunting character as the attack target).',
		starEffectDesc_en = 'Additional effect: <Taunt> enemies attack the character with the highest attack stat for 1 turn (Taunt: a control effect that forces the target to choose the taunting character as the attack target).',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: <ท้าทาย> ศัตรูโจมตีตัวละครที่มีค่าสถานะการโจมตีสูงที่สุดเป็นเวลา 1 เทิร์น (ท้าทาย: เอฟเฟกต์ควบคุม บังคับเป้าหมายให้เลือกตัวท้าทายเป็นเป้าหมายโจมตี)',
		starEffectDesc_in = 'Efek tambahan: <Menantang> musuh menyerang karakter dengan statistik serangan tertinggi selama 1 giliran (Menantang: efek kontrol yang memaksa target memilih karakter penantang sebagai target serangan).',
		starEffectDesc_ph = 'Karagdagang epekto: <Pang-aakit> inaatake ng mga kaaway ang karakter na may pinakamataas na estadistika ng pag-atake sa loob ng 1 na turn (Pang-aakit: isang kontrol na epekto na pinipilit ang target na piliin ang nag-aakit na karakter bilang target ng pag-atake).',
		starEffectDesc_ma = 'Kesan tambahan: <Menantang> musuh menyerang watak dengan statistik serangan tertinggi selama 1 giliran (Menantang: kesan kawalan yang memaksa sasaran memilih watak menantang sebagai sasaran serangan).',
		zawakeEffect = __data_t__zawakeEffect[18633],
		-- {79003}
		zawakeEffectDesc = 'Diya Sea Lion roars and summons ice spikes to attack a single enemy target, dealing #C0xF13B54# magic damage #C0x3D8A99#360% Magic Damage #C0x5B545B#+$(skillLevel*4*60)$ #C0x5B545B#. The next time it is attacked, it will add 20% of its lost HP as true damage healing to all enemies.',
		zawakeEffectDesc_en = 'Diya Sea Lion roars and summons ice spikes to attack a single enemy target, dealing #C0xF13B54# magic damage #C0x3D8A99#360% Magic Damage #C0x5B545B#+$(skillLevel*4*60)$ #C0x5B545B#. The next time it is attacked, it will add 20% of its lost HP as true damage healing to all enemies.',
		zawakeEffectDesc_th = 'Diya Sea Lion คำรามและเรียกหนามน้ำแข็งโจมตีเป้าหมายศัตรูหนึ่งตัว สร้าง #C0xF13B54# ความเสียหายเวท #C0x3D8A99#360% ความเสียหายเวท #C0x5B545B#+$(skillLevel*4*60)$ #C0x5B545B#. ครั้งถัดไปที่ถูกโจมตี มันจะเพิ่ม 20% ของพลังชีวิตที่เสียไปในรูปแบบความเสียหายจริงแก่ศัตรูทั้งหมด',
		zawakeEffectDesc_in = 'Diya Sea Lion mengaum dan memanggil duri es untuk menyerang satu musuh, memberikan #C0xF13B54# kerusakan sihir #C0x3D8A99#360% Kerusakan Sihir #C0x5B545B#+$(skillLevel*4*60)$ #C0x5B545B#. Pada serangan berikutnya yang diterimanya, ia akan menambahkan 20% dari HP yang hilang sebagai jumlah penyembuhan kerusakan nyata pada semua musuh.',
		zawakeEffectDesc_ph = 'Diya Sea Lion umuungal at nagpapatawag ng mga tinik ng yelo upang atakihin ang isang target na kaaway, na nagdudulot ng #C0xF13B54# magic damage #C0x3D8A99#360% Magic Damage #C0x5B545B#+$(skillLevel*4*60)$ #C0x5B545B#. Sa susunod na beses na ito ay tatamaan, magdadagdag ito ng 20% ng nawalang HP bilang totoong pinsalang pagpapagaling sa lahat ng mga kalaban.',
		zawakeEffectDesc_ma = 'Diya Sea Lion mengaum dan memanggil duri ais untuk menyerang satu sasaran musuh, menyebabkan #C0xF13B54# kerosakan sihir #C0x3D8A99#360% Kerosakan Sihir #C0x5B545B#+$(skillLevel*4*60)$ #C0x5B545B#. Kali seterusnya diserang, ia akan menambah 20% jumlah HP yang hilang sebagai kerosakan penyembuhan sebenar kepada semua musuh.',
		zawakeEffectDesc_vn = 'Diya Sea Lion gầm lên và triệu hồi các gai băng tấn công một mục tiêu địch, gây #C0xF13B54# sát thương phép #C0x3D8A99#360% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$#C0x5B545B#. Lần tiếp theo bị tấn công, nó sẽ cộng thêm 20% lượng HP đã mất của mình dưới dạng sát thương hồi phục cho tất cả kẻ thù (sát thương này là sát thương thực sự)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Deals counter damage equal to 20% of self lost HP to all enemies',
		zawakeSimpleDesc_en = 'Deals counter damage equal to 20% of self lost HP to all enemies',
		zawakeSimpleDesc_th = 'สร้างความเสียหายตอบโต้เท่ากับ 20% ของ HP ที่สูญเสียให้กับศัตรูทั้งหมด',
		zawakeSimpleDesc_in = 'Memberikan damage balik sebesar 20% dari HP yang hilang ke semua musuh',
		zawakeSimpleDesc_ph = 'Nagdudulot ng counter damage na katumbas ng 20% ng nawalang HP sa lahat ng kalaban',
