		skillName_vn = 'Siêu Năng Tiêu Diệt Tinh Tiễn',
		skillName_en = 'Super Energy Eliminate Missile',
		skillName_th = 'ซูเปอร์พลังทำลายจรวด',
		skillName_in = 'Super Energi Menghancurkan Rudal',
		skillName_ph = 'Super Enerhiya Pumatay Missiles',
		skillName_ma = 'Kuasa Super Memusnahkan Peluru',
		skillName = 'Super Energy Eliminate Missile',
		describe_vn = 'Icarus nhanh chóng bay lên trời và phóng những mũi tên hủy diệt siêu sao tấn công mục tiêu ở hàng đầu của kẻ địch, gây #C0xE69900#320% Sát Thương Vật Lý #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, thêm một lớp [Tear] và ngay lập tức gây ra sát thương [Tear] trên mục tiêu.',
		describe_en = 'Icarus swiftly flies into the sky and shoots devastating superstar arrows targeting the enemy\'s front line, dealing #C0xE69900#320% Physical Damage #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Physical Damage #C0x5B545B#, adds a [Tear] layer and immediately inflicts [Tear] damage on the target.',
		describe_th = 'ไอคารัสบินขึ้นสู่ท้องฟ้าอย่างรวดเร็วและยิงลูกธนูทำลายล้างสุดยอดไปยังเป้าหมายแถวหน้าของศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#320% #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B#, เพิ่มชั้น [Tear] และทันทีที่ก่อให้เกิดความเสียหาย [Tear] บนเป้าหมาย',
		describe_in = 'Icarus dengan cepat terbang ke langit dan menembakkan panah superstar penghancur yang menyerang target di barisan depan musuh, menyebabkan #C0xE69900#320% Kerusakan Fisik #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#, menambahkan lapisan [Tear] dan segera menyebabkan kerusakan [Tear] pada target.',
		describe_ph = 'Mabilis na lumipad si Icarus papunta sa langit at nagpalipad ng mga mapanirang superstar na palaso na tumatarget sa unahang hanay ng kaaway, nagdudulot ng #C0xE69900#320% Pisikal na Pinsala #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, nagdadagdag ng isang layer na [Tear] at agad na nagdudulot ng [Tear] na pinsala sa target.',
		describe_ma = 'Icarus dengan pantas terbang ke langit dan melepaskan anak panah superstar pemusnah yang menyerang sasaran di barisan depan musuh, menyebabkan #C0xE69900#320% Kerosakan Fizikal #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, menambah lapisan [Tear] dan segera menyebabkan kerosakan [Tear] pada sasaran.',
		describe = 'Icarus swiftly flies into the sky and shoots devastating superstar arrows targeting the enemy\'s front line, dealing #C0xE69900#320% Physical Damage #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Physical Damage #C0x5B545B#, adds a [Tear] layer and immediately inflicts [Tear] damage on the target.',
		simDesc_vn = 'Icarus nhanh chóng bay lên trời và phóng những mũi tên hủy diệt siêu sao tấn công các mục tiêu ở hàng đầu của kẻ địch, tạo thêm một lớp nước mắt và ngay lập tức gây ra sát thương nước mắt lên mục tiêu.',
		simDesc_en = 'Icarus swiftly soared into the sky, unleashing devastating superstar arrows that struck the enemy\'s frontline targets, creating an additional layer of tears and instantly dealing tear damage to the targets.',
		simDesc_th = 'อิคารัสบินขึ้นฟ้าอย่างรวดเร็วและยิงลูกศรทำลายล้างสุดยอดโจมตีเป้าหมายแถวหน้าของศัตรู สร้างชั้นน้ำตาเพิ่มขึ้นและก่อให้เกิดความเสียหายน้ำตาต่อเป้าหมายทันที',
		simDesc_in = 'Icarus dengan cepat terbang ke langit dan melepaskan panah bintang super penghancur yang menyerang target di barisan depan musuh, menciptakan lapisan air mata tambahan dan langsung memberikan kerusakan air mata pada target.',
		simDesc_ph = 'Mabilis na lumipad si Icarus sa kalangitan at nagpalipad ng mga nakapinsalang superstar na palaso na tumama sa mga target sa unahang linya ng kaaway, lumikha ng isang karagdagang layer ng luha at agad na nagdulot ng pinsala mula sa luha sa mga target.',
		simDesc_ma = 'Icarus dengan pantas terbang ke langit dan melepaskan anak panah superstar pemusnah yang menyerang sasaran di barisan hadapan musuh, mencipta lapisan air mata tambahan dan serta-merta menyebabkan kerosakan air mata pada sasaran.',
		simDesc = 'Icarus swiftly soared into the sky, unleashing devastating superstar arrows that struck the enemy\'s frontline targets, creating an additional layer of tears and instantly dealing tear damage to the targets.',
		starEffect = __data_t__starEffect[18933],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: 50% sát thương từ <Xé rách> sẽ được chuyển đổi thành điểm sinh lực của bản thân.',
		starEffectDesc = 'Additional Effect: 50% of damage from <Rip> will be converted into own HP.',
		starEffectDesc_en = 'Additional Effect: 50% of damage from <Rip> will be converted into own HP.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: 50% ของความเสียหายจาก [ฉีกเนื้อ] จะถูกเปลี่ยนเป็นพลังชีวิตของตนเอง',
		starEffectDesc_in = 'Efek Tambahan: 50% kerusakan dari <Xé rách> akan diubah menjadi poin HP sendiri.',
		starEffectDesc_ph = 'Karagdagang Epekto: 50% ng pinsala mula sa <Xé rách> ay iko-convert bilang sariling HP.',
		starEffectDesc_ma = 'Kesan Tambahan: 50% kerosakan dari <Xé rách> akan ditukar menjadi mata HP sendiri.',
