	[18936] = {
		id = 18936,
		skillName_vn = 'Nữ hoàng bầu trời',
		skillName_en = 'Queen of the Sky',
		skillName_th = 'ราชินีแห่งท้องฟ้า',
		skillName_in = 'Ratu Langit',
		skillName_ph = 'Reyna ng Kalangitan',
		skillName_ma = 'Ratu Langit',
		skillName = 'Queen of the Sky',
		describe_vn = 'Có một lớp hiệu ứng [Tear] được đính kèm khi tấn công (Xé: hiệu ứng tiêu cực, mục tiêu bị cấm hồi máu và sẽ nhận sát thương thực sự từ Icarus#C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# Sát Thương Vật Lý khi tấn công, kéo dài 2 hiệp và có thể cộng dồn tối đa 3 lần)',
		describe_en = 'There is a [Tear] effect layer attached when attacking (Tear: a negative effect, the target is forbidden from healing and will receive true damage from Icarus equal to $(30+skillLevel*0.2-0.2)$% Physical Damage when attacking, lasting 2 turns and can stack up to 3 times)',
		describe_th = 'มีชั้นเอฟเฟ็กต์ [Tear] แนบเมื่อโจมตี (ฉีก: เอฟเฟ็กต์เชิงลบ เป้าหมายถูกห้ามฟื้นฟูพลังชีวิตและจะได้รับความเสียหายจริงจาก Icarus เท่ากับ $(30+skillLevel*0.2-0.2)$% ของความเสียหายกายภาพเมื่อโจมตี มีผลนาน 2 เทิร์น และสะสมได้สูงสุด 3 ครั้ง)',
		describe_in = 'Ada lapisan efek [Tear] yang melekat saat menyerang (Sobek: efek negatif, target dilarang sembuh dan akan menerima damage nyata dari Icarus sebesar $(30+skillLevel*0.2-0.2)$% Damage Fisik saat menyerang, berlangsung selama 2 giliran dan bisa menumpuk hingga 3 kali)',
		describe_ph = 'Mayroong [Tear] effect layer na naka-attach kapag umaatake (Tear: negatibong epekto, ang target ay ipinagbabawal na gumaling at tatanggap ng totoong pinsala mula sa Icarus na katumbas ng $(30+skillLevel*0.2-0.2)$% Physical Damage kapag umaatake, tumatagal ng 2 turns at maaaring maipon hanggang 3 beses)',
		describe_ma = 'Terdapat lapisan kesan [Tear] yang disertakan ketika menyerang (Robek: kesan negatif, sasaran dilarang untuk sembuh dan akan menerima kerosakan sebenar dari Icarus sebanyak $(30+skillLevel*0.2-0.2)$% Kerosakan Fizikal semasa menyerang, berlangsung selama 2 pusingan dan boleh bertindih sehingga 3 kali)',
		describe = 'There is a [Tear] effect layer attached when attacking (Tear: a negative effect, the target is forbidden from healing and will receive true damage from Icarus equal to $(30+skillLevel*0.2-0.2)$% Physical Damage when attacking, lasting 2 turns and can stack up to 3 times)',
		starEffect = __data_t__starEffect[18936],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung:  <Xé rách> Khi mục tiêu bị tiêu diệt, hồi cho Icarus 15% lượng máu tối đa.',
		starEffectDesc = 'Additional effect: <Tear> When the target is defeated, restores 15% of Icarus\'s max HP.',
		starEffectDesc_en = 'Additional effect: <Tear> When the target is defeated, restores 15% of Icarus\'s max HP.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: <ฉีกขาด> เมื่อเป้าหมายถูกกำจัด ฟื้นฟู HP สูงสุดของ Icarus 15%',
		starEffectDesc_in = 'Efek tambahan: <Robek> Ketika target dikalahkan, pulihkan 15% dari HP maksimum Icarus.',
		starEffectDesc_ph = 'Karagdagang epekto: <Hibla> Kapag natalo ang target, magpagaling ng 15% ng maximum HP ni Icarus.',
		starEffectDesc_ma = 'Kesan tambahan: <Robek> Apabila sasaran dikalahkan, pulihkan 15% daripada HP maksimum Icarus.',
		zawakeEffect = __data_t__zawakeEffect[18936],
		-- {79004}
		zawakeEffectDesc = 'When attacking, applies a layer of <torn> effect (torn: negative effect, target is forbidden from healing, and when attacked will receive true damage equal to #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# of the dragonling\'s Physical Attack, lasts 3 turns, can stack up to 3 layers)',
		zawakeEffectDesc_en = 'When attacking, applies a layer of <torn> effect (torn: negative effect, target is forbidden from healing, and when attacked will receive true damage equal to #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# of the dragonling\'s Physical Attack, lasts 3 turns, can stack up to 3 layers)',
		zawakeEffectDesc_th = 'เมื่อโจมตี จะเพิ่มชั้นของเอฟเฟกต์ <ฉีกขาด> (ฉีกขาด: เอฟเฟกต์ลบ เป้าหมายถูกห้ามฟื้นฟู และเมื่อถูกโจมตีจะได้รับความเสียหายจริงเท่ากับ #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# พลังโจมตีทางกายภาพของลูกมังกร นาน 3 เทิร์น สามารถสะสมได้สูงสุด 3 ชั้น)',
		zawakeEffectDesc_in = 'Saat menyerang, menerapkan satu lapis efek <robek> (robek: efek negatif, target dilarang melakukan penyembuhan, dan ketika diserang akan menerima damage nyata sebesar #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# dari Serangan Fisik naga muda, bertahan selama 3 giliran, dapat menumpuk hingga 3 lapis)',
		zawakeEffectDesc_ph = 'Kapag umaatake, naglalagay ng isang layer ng epekto ng <punit> (punit: negatibong epekto, ipinagbabawal ang pagpapagaling sa target, at kapag inaatake ay tatanggap ng tunay na pinsala na katumbas ng #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# ng Pisikal na Atake ng dragonling, tumatagal ng 3 round, pwedeng magkapatong hanggang 3 layer)',
		zawakeEffectDesc_ma = 'Semasa menyerang, kenakan satu lapisan kesan <robek> (robek: kesan negatif, sasaran dilarang pulih, dan apabila diserang akan menerima kerosakan sebenar sebanyak #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# Serangan Fizikal anak naga, berpanjangan selama 3 pusingan, boleh bertumpuk sehingga 3 lapisan)',
		zawakeEffectDesc_vn = 'Khi tấn công kèm theo một lớp hiệu ứng <xé rách> (xé rách: hiệu ứng tiêu cực, mục tiêu bị cấm hồi máu, và khi tấn công sẽ nhận sát thương thực bằng #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# Công Vật Lý của rồng con, kéo dài 3 lượt, tối đa có thể chồng 3 lớp)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '<Rend> lasts for 3 turns',
		zawakeSimpleDesc_en = '<Rend> lasts for 3 turns',
		zawakeSimpleDesc_th = '<ฉีกขาด> คงอยู่เป็นเวลา 3 เทิร์น',
		zawakeSimpleDesc_in = '<Terkoyak> berlangsung selama 3 giliran',
		zawakeSimpleDesc_ph = '<Punit> tumatagal ng 3 turn',
		zawakeSimpleDesc_ma = '<Terkoyak> bertahan selama 3 pusingan',
		zawakeSimpleDesc_vn = '<Xé Rách> kéo dài trong 3 lượt',
		iconRes = 'battle/skill_icon/skill_18936.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {189361}
	},
	[19011] = {
		id = 19011,
		skillName_vn = 'Va chạm',
		skillName_en = 'Collision',
		skillName_th = 'การชนกัน',
		skillName_in = 'Tabrakan',
		skillName_ph = 'Banggaan',
		skillName_ma = 'Perlanggaran',
		skillName = 'Collision',
		describe_vn = 'Quả tạ sắt tấn công mục tiêu đơn địch với khí thế kinh ngạc, gây #C0xE69900#80% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, giảm thời gian hồi chiêu kỹ năng nhỏ đi 1 lượt',
		describe_en = 'The iron weight attacks a single enemy with astonishing momentum, dealing #C0xE69900#80% Physical Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, and reduces the cooldown of minor skills by 1 turn.',
		describe_th = 'ลูกตุ้มน้ำหนักเหล็กโจมตีศัตรูเป้าหมายเดี่ยวด้วยพลังที่น่าทึ่ง สร้างความเสียหาย #C0xE69900#80% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# และลดเวลาคูลดาวน์สกิลเล็กลง 1 เทิร์น',
		describe_in = 'Beban besi menyerang satu musuh dengan semangat mengagumkan, memberikan #C0xE69900#80% Serangan Fisik#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, mengurangi waktu cooldown skill kecil sebanyak 1 giliran.',
		describe_ph = 'Ang bumbong bakal na bakal ay umatake sa isang kalabang target na may kamangha-manghang lakas, nagdudulot ng #C0xE69900#80% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, binabawasan ang cooldown ng maliit na kasanayan ng 1 turn.',
		describe_ma = 'Tali besi menyerang satu sasaran musuh dengan semangat yang mengagumkan, menyebabkan #C0xE69900#80% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, mengurangkan masa rehat kemahiran kecil sebanyak 1 pusingan.',
		describe = 'The iron weight attacks a single enemy with astonishing momentum, dealing #C0xE69900#80% Physical Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, and reduces the cooldown of minor skills by 1 turn.',
		simDesc_vn = 'Tạ Nhân lao về phía mục tiêu đơn lẻ của đối phương với sức mạnh đáng kinh ngạc để tấn công.',
		simDesc_en = 'Ta Nhan lunged toward the enemy\'s single target with incredible power to attack.',
		simDesc_th = 'ตะ เหนิน โจมตีเป้าหมายเดียวของศัตรูด้วยพลังที่เหลือเชื่อ',
		simDesc_in = 'Ta Nhan melaju ke target tunggal musuh dengan kekuatan luar biasa untuk menyerang.',
		simDesc_ph = 'Si Ta Nhan ay lumipad patungo sa nag-iisang target ng kalaban na may kahanga-hangang lakas upang umatake.',
		simDesc_ma = 'Ta Nhan menyerbu ke arah sasaran tunggal musuh dengan kekuatan yang luar biasa untuk menyerang.',
		simDesc = 'Ta Nhan lunged toward the enemy\'s single target with incredible power to attack.',
