	[19113] = {
		id = 19113,
		skillName_vn = 'Đấm Bắc Đẩu trăm nhát',
		skillName_en = 'Hundred Strikes of the Northern Dipper',
		skillName_th = 'หมัดร้อยนัดแห่งกลุ่มดาวเหนือนางฟ้า',
		skillName_in = 'Seratus Pukulan Utara Dipper',
		skillName_ph = 'Siyam na Suntok ng Hilagang Dipper',
		skillName_ma = 'Seratus Pukulan Dipper Utara',
		skillName = 'Hundred Strikes of the Northern Dipper',
		describe_vn = 'Kenshiro dốc toàn lực thi triển Bắc Đẩu Bách Liệt Quyền tấn công toàn bộ mục tiêu địch, gây ra #C0xE69900#220% Công Vật Lý#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, và có 40% xác suất khiến chúng [Choáng] 1 lượt (Choáng: hiệu ứng khống chế, không thể hành động)',
		describe_en = 'Kenshiro unleashes the full power of the Big Dipper Hundred Crack Fist, attacking all enemy targets, dealing #C0xE69900#220% Physical Attack#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#, and has a 40% chance to cause [Stun] for 1 turn (Stun: control effect, unable to act).',
		describe_th = 'เคนชิโระ ใช้พลังทั้งหมดในการปล่อยท่าต่อยร้อยรอยร้าวจักรราศีเหนือโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายทางกายภาพ #C0xE69900#220% พลังโจมตี#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# และมีโอกาส 40% ที่จะทำให้เป้าหมาย [มึนงง] เป็นเวลา 1 เทิร์น (มึนงง: สถานะควบคุม ไม่สามารถทำอะไรได้)',
		describe_in = 'Kenshiro mengerahkan seluruh tenaga untuk melancarkan Tinju Seratus Retakan Utara Dipper yang menyerang semua target musuh, menyebabkan #C0xE69900#220% Serangan Fisik#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, dan memiliki peluang 40% untuk membuat mereka [Pingsan] selama 1 giliran (Pingsan: efek kontrol, tidak dapat bertindak).',
		describe_ph = 'Buong lakas na inilabas ni Kenshiro ang Big Dipper Hundred Crack Fist na umatake sa lahat ng kaaway, nagdudulot ng #C0xE69900#220% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#, at may 40% na tsansa na magdulot ng [Stun] sa loob ng 1 turn (Stun: control effect, hindi makakilos).',
		describe_ma = 'Kenshiro menggunakan segala tenaga untuk melancarkan Tinju Seratus Retakan Bintang Utara menyerang semua sasaran musuh, memberikan #C0xE69900#220% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, dan mempunyai 40% peluang untuk menyebabkan mereka [Pengsan] selama 1 pusingan (Pengsan: kesan kawalan, tidak dapat bertindak).',
		describe = 'Kenshiro unleashes the full power of the Big Dipper Hundred Crack Fist, attacking all enemy targets, dealing #C0xE69900#220% Physical Attack#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#, and has a 40% chance to cause [Stun] for 1 turn (Stun: control effect, unable to act).',
		simDesc_vn = 'Kiện Tử phát huy toàn bộ sức mạnh thi triển "Bắc Đẩu Bách Liệt Quyền" tấn công tất cả mục tiêu của đối phương.',
		simDesc_en = 'The Fighter unleashes full power to perform the "Northern Dipper Hundred Fury Fists", attacking all enemy targets.',
		simDesc_th = 'นักสู้ปลดปล่อยพลังเต็มที่เพื่อใช้ "หมัดร้อยลูกจักรราศีเหนือ" โจมตีเป้าหมายฝ่ายตรงข้ามทั้งหมด',
		simDesc_in = 'Petarung mengerahkan kekuatan penuh untuk melancarkan "Tinju Seribu Serangan Utara", menyerang semua target musuh.',
		simDesc_ph = 'Ipinapangalakal ng Mandirigma ang buong lakas upang ipatupad ang "Hilaga na Dipper na Daang Daan na Kamao", inaatake ang lahat ng kalaban.',
		simDesc_ma = 'Pejuang mengerahkan sepenuh tenaga untuk melaksanakan "Tinju Seratus Serangan Bintang Utara", menyerang semua sasaran musuh.',
		simDesc = 'The Fighter unleashes full power to perform the "Northern Dipper Hundred Fury Fists", attacking all enemy targets.',
		starEffect = __data_t__starEffect[19113],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Đối với những kẻ thù không bị choáng, khi tấn công Kenjiro, sẽ không gây được Sát Thương Phép Thuật, kéo dài 1 lượt.',
		starEffectDesc = 'Additional Effect: For enemies who are not stunned, when attacking Kenjiro, Magical Damage will not be inflicted, lasting 1 turn.',
		starEffectDesc_en = 'Additional Effect: For enemies who are not stunned, when attacking Kenjiro, Magical Damage will not be inflicted, lasting 1 turn.',
		starEffectDesc_th = 'ผลเพิ่มเติม: สำหรับศัตรูที่ไม่ได้ถูกทำให้มึน เมื่อโจมตี Kenjiro จะไม่สร้างความเสียหายเวทมนตร์ โดยมีระยะเวลา 1 รอบ',
		starEffectDesc_in = 'Efek Tambahan: Untuk musuh yang tidak terkena stun, ketika menyerang Kenjiro, tidak akan memberikan Damage Magis, berlangsung selama 1 giliran.',
		starEffectDesc_ph = 'Karagdagang Epekto: Para sa mga kalaban na hindi na-stun, kapag inatake si Kenjiro, hindi magkakaroon ng Magical Damage, tumatagal ng 1 turn.',
		starEffectDesc_ma = 'Kesan Tambahan: Bagi musuh yang tidak terkena stun, apabila menyerang Kenjiro, tidak akan menyebabkan Kerosakan Sihir, berlangsung selama 1 pusingan.',
		zawakeEffect = __data_t__zawakeEffect[19113],
		-- {79003}
		zawakeEffectDesc = 'Kenjiro dốc toàn lực thi triển Bắc Đẩu Bách Liệt Quyền tấn công toàn bộ mục tiêu địch, gây #C0xE69900#220% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Physical Damage#C0x5B545B#, và có 40% xác suất khiến chúng <choáng> 1 lượt (choáng: hiệu ứng kiểm soát, không thể hành động), khi tử trận xác suất choáng vĩnh viễn tăng 10%',
		zawakeEffectDesc_en = 'Kenjiro dốc toàn lực thi triển Bắc Đẩu Bách Liệt Quyền tấn công toàn bộ mục tiêu địch, gây #C0xE69900#220% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Physical Damage#C0x5B545B#, và có 40% xác suất khiến chúng <choáng> 1 lượt (choáng: hiệu ứng kiểm soát, không thể hành động), khi tử trận xác suất choáng vĩnh viễn tăng 10%',
		zawakeEffectDesc_th = 'Kenjiro ใช้กำลังทั้งหมดออกหมัดแสนร้ายกาจโจมตีศัตรูทั้งหมดก่อให้เกิด #C0xE69900#220% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# และมีโอกาส 40% ทำให้พวกมัน <choáng> 1 เทิร์น (choáng: เอฟเฟกต์ควบคุม, ไม่สามารถทำอะไรได้) เมื่อถูกฆ่า โอกาส choáng ถาวรจะเพิ่มขึ้น 10%',
		zawakeEffectDesc_in = 'Kenjiro mengerahkan seluruh tenaga melancarkan Pukulan Seribu Belati Utara yang menyerang semua target musuh, menyebabkan #C0xE69900#220% Serangan Fisik#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, dan ada peluang 40% untuk membuat mereka <choáng> 1 giliran (choáng: efek kendali, tidak bisa bertindak), ketika mati peluang choáng permanen meningkat 10%',
		zawakeEffectDesc_ph = 'Kenjiro inilalabas ang buong lakas sa Seribu Palakol ng Hilagang Bituin na umaatake sa lahat ng mga kalaban, nagdudulot ng #C0xE69900#220% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, at may 40% tsansang mapang-<choáng> sila ng 1 turn (choáng: kontrol na epekto, hindi makakilos), kapag namatay tumataas ng 10% ang permanenteng tsansa ng choáng',
		zawakeEffectDesc_ma = 'Kenjiro mengerahkan seluruh tenaga melaksanakan Pukulan Seribu Belati Utara menyerang semua sasaran musuh, menyebabkan #C0xE69900#220% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, dan mempunyai peluang 40% untuk menyebabkan mereka <choáng> 1 giliran (choáng: kesan kawalan, tidak boleh bertindak), apabila terbunuh peluang choáng kekal meningkat 10%',
		zawakeEffectDesc_vn = 'Kenjiro dốc toàn lực thi triển Bắc Đẩu Bách Liệt Quyền tấn công toàn bộ mục tiêu địch, gây #C0xE69900#220% Công Vật Lý#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, và có 40% xác suất khiến chúng <choáng> 1 lượt (choáng: hiệu ứng kiểm soát, không thể hành động), khi tử trận xác suất choáng vĩnh viễn tăng 10%',
