	[19213] = {
		id = 19213,
		skillName_vn = 'Đất đai bị đóng băng',
		skillName_en = 'Frozen land',
		skillName_th = 'ที่ดินแช่แข็ง',
		skillName_in = 'Tanah beku',
		skillName_ph = 'Yabang lupa',
		skillName_ma = 'Tanah beku',
		skillName = 'Frozen land',
		describe_vn = 'Regice xoay tròn trên không, khi đáp xuống đóng băng mặt đất, gây ra #C0x3D8A99#130% Công Phép#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# lên toàn bộ mục tiêu địch, sau đó tự đóng băng vào [Hạt Băng] (Hạt Băng: hiệu ứng đặc biệt, không thể hành động, miễn nhiễm sát thương, Hạt Băng sẽ vỡ sau khi chịu 2 lần tấn công, nếu không bị phá vỡ, hiệu ứng Hạt Băng sẽ được giải trừ trước khi bắt đầu lượt thứ hai sau kỹ năng tất sát này)',
		describe_en = 'Regice spins in the air, freezes the ground upon landing, dealing #C0x3D8A99#130% Magic Power#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B# to all enemy targets, then freezes itself into [Ice Orb] (Ice Orb: special effect, unable to take actions, immune to damage, the Ice Orb will shatter after taking 2 attacks; if not broken, the Ice Orb effect will be removed before the start of the second turn after this lethal skill).',
		describe_th = 'Regice หมุนตัวในอากาศ เมื่อลงพื้นจะทำให้พื้นแข็งตัวเป็นน้ำแข็ง สร้างความเสียหายเวทมนตร์ #C0x3D8A99#130% พลังเวท#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# แก่เป้าหมายศัตรูทั้งหมด จากนั้นจะแข็งตัวกลายเป็น [เมล็ดน้ำแข็ง] (เมล็ดน้ำแข็ง: เอฟเฟกต์พิเศษ ไม่สามารถกระทำการใด ๆ และป้องกันความเสียหาย เมล็ดน้ำแข็งจะแตกหลังจากโดนโจมตี 2 ครั้ง หากไม่โดนทำลาย เอฟเฟกต์เมล็ดน้ำแข็งจะถูกยกเลิกก่อนเริ่มเทิร์นที่สองหลังใช้สกิลสังหารนี้)',
		describe_in = 'Regice berputar di udara, membekukan tanah saat mendarat, menyebabkan #C0x3D8A99#130% Kekuatan Sihir#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B# ke semua target musuh, kemudian membekukan dirinya menjadi [Butir Es] (Butir Es: efek khusus, tidak bisa bertindak, kebal terhadap kerusakan, Butir Es akan pecah setelah menerima 2 serangan, jika tidak pecah, efek Butir Es akan dihapus sebelum mulai giliran kedua setelah skill pamungkas ini).',
		describe_ph = 'Umiikot si Regice sa hangin, nagyeyelo ng lupa pagdating sa lupa, nagdudulot ng #C0x3D8A99#130% Lakas ng Mahika#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Pinsalang Mahika #C0x5B545B# sa lahat ng mga kaaway na target, pagkatapos ay nagyeyelo ang sarili sa [Butil ng Yelo] (Butil ng Yelo: espesyal na epekto, hindi makakilos, immune sa pinsala, ang Butil ng Yelo ay mababasag pagkatapos makatanggap ng 2 atake; kung hindi nabasag, ang epekto ng Butil ng Yelo ay aalisin bago magsimula ang ikalawang turno pagkatapos ng skill na ito).',
		describe_ma = 'Regice berpusing di udara, membekukan tanah ketika mendarat, menyebabkan #C0x3D8A99#130% Kuasa Sihir#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B# kepada semua musuh sasaran, kemudian membekukan dirinya menjadi [Butiran Ais] (Butiran Ais: kesan khas, tidak dapat bertindak, kebal terhadap kerosakan, Butiran Ais akan pecah selepas menerima 2 serangan, jika tidak pecah, kesan Butiran Ais akan dibuang sebelum permulaan giliran kedua selepas kemahiran pembunuhan ini).',
		describe = 'Regice spins in the air, freezes the ground upon landing, dealing #C0x3D8A99#130% Magic Power#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B# to all enemy targets, then freezes itself into [Ice Orb] (Ice Orb: special effect, unable to take actions, immune to damage, the Ice Orb will shatter after taking 2 attacks; if not broken, the Ice Orb effect will be removed before the start of the second turn after this lethal skill).',
		simDesc_vn = 'Regiace xoay tròn trên không, khi tiếp đất sẽ đóng băng mặt đất, tấn công tất cả mục tiêu của đối phương và tự đưa mình vào trạng thái băng hạt.',
		simDesc_en = 'Regiace spins in the air, freezing the ground upon landing, attacking all enemy targets and putting itself into Ice Particle state.',
		simDesc_th = 'Regiace หมุนกลางอากาศ เมื่อลงจอดจะทำให้พื้นกลายเป็นน้ำแข็ง โจมตีเป้าหมายของศัตรูทั้งหมด และเข้าสู่สถานะอนุภาคน้ำแข็ง',
		simDesc_in = 'Regiace berputar di udara, saat mendarat akan membekukan tanah, menyerang semua target musuh dan memasuki keadaan partikel es.',
		simDesc_ph = 'Umiikot si Regiace sa hangin, kapag bumagsak ay magyeyelo sa lupa, iaaatake ang lahat ng kalaban at ilalagay ang sarili sa Ice Particle na estado.',
		simDesc_ma = 'Regiace berpusing di udara, ketika mendarat akan membekukan tanah, menyerang semua sasaran musuh dan memasuki keadaan zarah ais.',
		simDesc = 'Regiace spins in the air, freezing the ground upon landing, attacking all enemy targets and putting itself into Ice Particle state.',
		starEffect = __data_t__starEffect[19213],
		-- {11}
		starEffectDesc_vn = '<Hạt băng>: Có thể chịu 3 lần tấn công, nếu không bị phá vỡ, sẽ hồi phục 500% phòng thủ phép thuật của Regice thành điểm sinh lực.',
		starEffectDesc = '<Ice Seed>: Can withstand 3 attacks. If not broken, it will restore 500% of Regice\'s magic defense as health points.',
		starEffectDesc_en = '<Ice Seed>: Can withstand 3 attacks. If not broken, it will restore 500% of Regice\'s magic defense as health points.',
		starEffectDesc_th = '<เมล็ดน้ำแข็ง>: สามารถทนทานการโจมตีได้ 3 ครั้ง หากไม่ถูกทำลาย จะฟื้นฟูพลังป้องกันเวทมนตร์ของ Regice 500% เป็นคะแนนพลังชีวิต',
		starEffectDesc_in = '<Biji Es>: Dapat menahan 3 serangan, jika tidak hancur, akan mengembalikan 500% pertahanan sihir Regice menjadi poin kesehatan.',
		starEffectDesc_ph = '<Butil ng Yelo>: Kayang tumagal ng 3 pag-atake, kung hindi mabasag, magpapagaling ng 500% ng magic defense ni Regice bilang health points.',
		starEffectDesc_ma = '<Benih Ais>: Boleh tahan 3 serangan, jika tidak hancur, akan memulihkan 500% pertahanan sihir Regice menjadi mata kesihatan.',
