	[19216] = {
		id = 19216,
		skillName_vn = 'Thân xác đông lạnh',
		skillName_en = 'Frozen body',
		skillName_th = 'ร่างกายแช่แข็ง',
		skillName_in = 'Tubuh beku',
		skillName_ph = 'Naghimo ng katawan',
		skillName_ma = 'Badan beku',
		skillName = 'Frozen body',
		describe_vn = 'Kỹ năng hào quang: Mỗi khi kết thúc một vòng lớn, hồi phục lượng máu bằng 100% phòng thủ phép của Regice cho đồng minh hệ Băng;\nKhi bị kỹ năng khống chế, hồi phục lượng máu bằng #C0x5c9970#$(100+skillLevel*1-1)$%#C0x5B545B# phòng thủ phép (khi bị đóng băng, lượng hồi phục tăng 50%)',
		describe_en = 'Aura Skill: At the end of each major round, restore HP equal to 100% of Regice\'s Magic Defense to Ice attribute allies; \n When affected by a control skill, restore HP equal to #(100+skillLevel*1-1)%# of Magic Defense (when frozen, healing amount increases by 50%).',
		describe_th = 'ทักษะออร่า: เมื่อสิ้นสุดรอบใหญ่แต่ละครั้ง ฟื้นฟูพลังชีวิตเท่ากับ 100% ของการป้องกันเวทมนตร์ของ Regice ให้กับพันธมิตรธาตุน้ำแข็ง; \n เมื่อถูกทักษะควบคุม ฟื้นฟูพลังชีวิตเท่ากับ #(100+skillLevel*1-1)%# ของการป้องกันเวทมนตร์ (เมื่อถูกแช่แข็ง ปริมาณการฟื้นฟูเพิ่มขึ้น 50%)',
		describe_in = 'Skill Aura: Setiap kali ronde besar selesai, pulihkan HP sebesar 100% pertahanan sihir Regice untuk sekutu atribut Es; \n Saat terkena skill kontrol, pulihkan HP sebesar #(100+skillLevel*1-1)%# pertahanan sihir (saat membeku, jumlah pemulihan meningkat 50%).',
		describe_ph = 'Aura Skill: Sa bawat pagtatapos ng isang malaking round, magbigay ng HP na katumbas ng 100% ng Magic Defense ni Regice para sa Ice attribute na mga kakampi; \n Kapag naapektuhan ng control skill, magbigay ng HP na katumbas ng #(100+skillLevel*1-1)%# ng Magic Defense (kapag nagyelo, tumataas ng 50% ang halaga ng pagpapagaling).',
		describe_ma = 'Kemahiran Aura: Setiap kali tamat satu pusingan besar, pulihkan HP sebanyak 100% pertahanan sihir Regice untuk sekutu elemen Ais; \n Apabila terjejas oleh kemahiran kawalan, pulihkan HP sebanyak #(100+skillLevel*1-1)%# pertahanan sihir (apabila dibekukan, jumlah pemulihan meningkat sebanyak 50%).',
		describe = 'Aura Skill: At the end of each major round, restore HP equal to 100% of Regice\'s Magic Defense to Ice attribute allies; \n When affected by a control skill, restore HP equal to #(100+skillLevel*1-1)%# of Magic Defense (when frozen, healing amount increases by 50%).',
		starEffect = __data_t__starEffect[19216],
		-- {8}
		starEffectDesc_vn = 'Khi nhận sát thương chí mạng: Ngay lập tức vào trạng thái <Hạt băng> (chỉ kích hoạt một lần).',
		starEffectDesc = 'Upon receiving critical damage: Immediately enter the <Ice Shard> state (activates only once).',
		starEffectDesc_en = 'Upon receiving critical damage: Immediately enter the <Ice Shard> state (activates only once).',
		starEffectDesc_th = 'เมื่อได้รับความเสียหายคริติคอล: เข้าโหมด <Hạt băng> ทันที (เปิดใช้งานได้ครั้งเดียวเท่านั้น)',
		starEffectDesc_in = 'Saat menerima damage kritis: Segera masuk ke keadaan <Hạt băng> (hanya aktif sekali).',
		starEffectDesc_ph = 'Kapag tumanggap ng kritikal na pinsala: Agarang pumasok sa estado ng <Hạt băng> (activate lamang nang isang beses).',
		starEffectDesc_ma = 'Apabila menerima kerosakan kritikal: Terus memasuki keadaan <Hạt băng> (hanya aktif sekali).',
		zawakeEffect = __data_t__zawakeEffect[19216],
		-- {79004}
		zawakeEffectDesc = 'Aura skill: Each time a major round ends, restore health equal to 120% of Regice\'s magic defense to Ice allies; when controlled by crowd control skills, restore health to self equal to #C0x5c9970#$(100+skillLevel*1-1)$%#C0x5B545B# magic defense (when frozen, healing amount increases by 100%)',
		zawakeEffectDesc_en = 'Aura skill: Each time a major round ends, restore health equal to 120% of Regice\'s magic defense to Ice allies; when controlled by crowd control skills, restore health to self equal to #C0x5c9970#$(100+skillLevel*1-1)$%#C0x5B545B# magic defense (when frozen, healing amount increases by 100%)',
