	[19413] = {
		id = 19413,
		skillName_vn = 'Mũi tên thần thánh',
		skillName_en = 'Divine Arrow',
		skillName_th = 'ลูกศรศักดิ์สิทธิ์',
		skillName_in = 'Anak Panah Ilahi',
		skillName_ph = 'Banal na Palaso',
		skillName_ma = 'Anak Panah Ilahi',
		skillName = 'Divine Arrow',
		describe_vn = 'Thiên thú lao lên trời và bắn những mũi tên thiên đường bắn phá mục tiêu ở hàng đầu của kẻ địch, gây ra #C0x3D8A99#300% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# sát thương phép#C0x5B545B# và giảm 30% Sát Thương Phép Thuật của kẻ địch ở hàng sau trong 3 lượt\n#F20# \n#F40# Nếu Angelmon thân thiện hiện diện và chiêu thức đặc biệt của nó không bị hạn chế, chiêu thức đặc biệt hiện tại sẽ được thay thế bằng [#L10#Kỹ năng tấn công kết hợp#L0#]\n#F20# \n#F40##L10#Kỹ năng kết hợp: #L0# Tấn công tất cả mục tiêu trong phạm vi của kẻ địch, gây sát thương bằng 480% tổng Sát Thương Phép Thuật của cả hai bên. Tất cả tác dụng của các chiêu thức đặc biệt của cả hai bên sẽ được thêm vào tất cả các mục tiêu của kẻ thù và mọi cơn thịnh nộ của cả hai bên sẽ bị tiêu hao. Hệ số sát thương của kỹ năng kết hợp là 80% tổng cộng của cả hai bên, hiệu ứng hút máu của phe mình và hiệu ứng phản sát thương của mục tiêu sẽ không được kích hoạt. Có thời gian hồi chiêu là 5 hiệp.',
		describe_en = 'The celestial beast soars into the sky and fires heavenly arrows to bombard the front row targets of the enemy, dealing #C0x3D8A99#300% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# magic damage#C0x5B545B# and reduces the Magical Damage of the enemies in the back row by 30% for 3 rounds \n#F20# \n#F40# If a friendly Angelmon is present and its special skill is not restricted, the current special skill will be replaced by [#L10#Combined Attack Skill#L0#] \n#F20# \n#F40##L10#Combined Skill: #L0# Attacks all targets within the enemy’s range, dealing damage equal to 480% of the total Magical Damage of both sides. All effects of the special skills from both sides are applied to all enemy targets and all fury from both sides is consumed. The damage coefficient of the combined skill is 80% of the total from both sides. Life-steal effects of the user\'s side and damage reflection effects of the targets will not be triggered. Cooldown time is 5 turns.',
		describe_th = 'สัตว์สวรรค์พุ่งขึ้นฟ้าและยิงลูกธนูแห่งสวรรค์โจมตีเป้าหมายแถวหน้าของศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#300%#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# และลดความเสียหายเวทมนตร์ของศัตรูแถวหลังลง 30% เป็นเวลา 3 รอบ \n#F20# \n#F40# หากมี Angelmon ที่เป็นมิตรอยู่และสกิลพิเศษของมันไม่ได้ถูกจำกัด สกิลพิเศษปัจจุบันจะถูกแทนที่ด้วย [#L10#สกิลโจมตีร่วม#L0#] \n#F20# \n#F40##L10#สกิลร่วม: #L0# โจมตีทุกเป้าหมายในระยะของศัตรู สร้างความเสียหายเท่ากับ 480% ของความเสียหายเวทมนตร์รวมของทั้งสองฝ่าย ผลของสกิลพิเศษจากทั้งสองฝ่ายจะถูกเพิ่มไปยังเป้าหมายของศัตรูทั้งหมดและความโกรธทั้งหมดของทั้งสองฝ่ายจะถูกใช้ไป อัตราความเสียหายของสกิลร่วมคือ 80% ของค่ารวมของทั้งสองฝ่าย ผลดูดพลังชีวิตของฝ่ายเราและผลสะท้อนความเสียหายของเป้าหมายจะไม่ทำงาน มีเวลาคูลดาวน์ 5 เทิร์น',
		describe_in = 'Makhluk surgawi melesat ke langit dan menembakkan panah surgawi untuk menghancurkan target di barisan depan musuh, menyebabkan #C0x3D8A99#300% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# kerusakan sihir#C0x5B545B# dan mengurangi 30% Kerusakan Magis musuh di barisan belakang selama 3 giliran \n#F20# \n#F40# Jika Angelmon yang bersahabat hadir dan skill spesialnya tidak dibatasi, skill spesial saat ini akan digantikan oleh [#L10#Skill Serangan Gabungan#L0#] \n#F20# \n#F40##L10#Skill Gabungan: #L0# Menyerang semua target dalam jangkauan musuh, menyebabkan kerusakan sebesar 480% dari total Kerusakan Magis kedua pihak. Semua efek dari skill spesial kedua pihak akan diterapkan ke semua target musuh dan semua kemarahan kedua pihak akan habis. Koefisien kerusakan skill gabungan adalah 80% dari total kedua pihak. Efek penghisapan darah dari pihak sendiri dan efek refleksi kerusakan dari target tidak akan aktif. Waktu cooldown adalah 5 giliran.',
		describe_ph = 'Anghel na hayop ay lumilipad pataas sa langit at nagpapaputok ng mga langit na palaso upang wasakin ang mga target sa unahang hanay ng kalaban, na nagdudulot ng #C0x3D8A99#300% Damage na Magical#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# magic damage#C0x5B545B# at nagpapababa ng 30% Magical Damage ng mga kalaban sa likurang hanay sa loob ng 3 rounds \n#F20# \n#F40# Kung may presensiya ang friendly na Angelmon at ang kanyang espesyal na kakayahan ay hindi limitado, ang kasalukuyang espesyal na kakayahan ay papalitan ng [#L10#Pinagsamang Skill sa Atake#L0#] \n#F20# \n#F40##L10#Pinagsamang Skill: #L0# Tinatamaan ang lahat ng target sa loob ng saklaw ng kalaban, na nagdudulot ng pinsala na katumbas ng 480% ng kabuuang Magical Damage ng dalawang panig. Ang lahat ng epekto ng espesyal na mga kakayahan ng dalawang panig ay iaaplay sa lahat ng mga target ng kalaban at ang lahat ng galit mula sa dalawang panig ay gagamitin. Ang damage coefficient ng pinagsamang skill ay 80% ng kabuuan ng dalawang panig. Ang life-steal effect ng sariling panig at ang damage reflection effect ng mga target ay hindi mai-activate. Ang cooldown time ay 5 turn.',
		describe_ma = 'Binatang syurga meluncur ke langit dan menembak anak panah syurga untuk membom sasaran di barisan depan musuh, menyebabkan #C0x3D8A99#300% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# kerosakan sihir#C0x5B545B# dan mengurangkan 30% Kerosakan Sihir musuh di barisan belakang selama 3 pusingan \n#F20# \n#F40# Jika Angelmon mesra hadir dan kemahiran istimewanya tidak terhad, kemahiran istimewa semasa akan digantikan dengan [#L10#Kemahiran Serangan Gabungan#L0#] \n#F20# \n#F40##L10#Kemahiran Gabungan: #L0# Menyerang semua sasaran dalam julat musuh, menyebabkan kerosakan sebanyak 480% Jumlah Kerosakan Sihir kedua-dua pihak. Semua kesan kemahiran istimewa kedua-dua pihak akan ditambah kepada semua sasaran musuh dan semua kemarahan kedua-dua pihak akan habis. Pekali kerosakan kemahiran gabungan adalah 80% jumlah kedua-dua pihak. Kesan hisap darah dari pihak sendiri dan kesan pantulan kerosakan dari sasaran tidak akan diaktifkan. Masa kembali semula adalah 5 pusingan.',
		describe = 'The celestial beast soars into the sky and fires heavenly arrows to bombard the front row targets of the enemy, dealing #C0x3D8A99#300% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# magic damage#C0x5B545B# and reduces the Magical Damage of the enemies in the back row by 30% for 3 rounds \n#F20# \n#F40# If a friendly Angelmon is present and its special skill is not restricted, the current special skill will be replaced by [#L10#Combined Attack Skill#L0#] \n#F20# \n#F40##L10#Combined Skill: #L0# Attacks all targets within the enemy’s range, dealing damage equal to 480% of the total Magical Damage of both sides. All effects of the special skills from both sides are applied to all enemy targets and all fury from both sides is consumed. The damage coefficient of the combined skill is 80% of the total from both sides. Life-steal effects of the user\'s side and damage reflection effects of the targets will not be triggered. Cooldown time is 5 turns.',
		simDesc_vn = 'Thiên Thú lao lên trời và bắn những mũi tên thiên đường để bắn phá các mục tiêu ở hàng trước của kẻ thù và làm giảm một lượng đòn tấn công phép thuật của hàng sau của kẻ thù.',
		simDesc_en = 'The Celestial Beast soars into the sky, shooting heavenly arrows to strike enemy frontline targets and reducing the magical attack power of the enemies in the backline.',
		simDesc_th = 'เทพสัตว์บินขึ้นสู่ท้องฟ้า ยิงธนูสวรรค์เพื่อโจมตีเป้าหมายแถวหน้าของศัตรูและลดพลังโจมตีเวทมนตร์ของแถวหลังศัตรู',
		simDesc_in = 'Makhluk Surgawi melesat ke langit dan menembakkan panah surgawi untuk menghancurkan target di barisan depan musuh serta mengurangi serangan sihir barisan belakang musuh.',
		simDesc_ph = 'Ang Langit na Hayop ay lumilipad sa langit at nagpapaputok ng mga langit na mga pana upang sirain ang mga target sa harapang hanay ng kaaway at nagpapababa ng kapangyarihan ng mahika ng mga likurang hanay ng kaaway.',
		simDesc_ma = 'Binatang Syurga meluncur ke angkasa dan melepaskan anak panah syurga untuk menyerang sasaran di barisan hadapan musuh serta mengurangkan serangan sihir barisan belakang musuh.',
		simDesc = 'The Celestial Beast soars into the sky, shooting heavenly arrows to strike enemy frontline targets and reducing the magical attack power of the enemies in the backline.',
		starEffect = __data_t__starEffect[19413],
