	[19414] = {
		id = 19414,
		skillName_vn = 'Thần Thánh Hợp Kích',
		skillName_en = 'Divine Combo',
		skillName_th = 'ผสมผสานเทพ',
		skillName_in = 'Serangan Gabungan Ilahi',
		skillName_ph = 'Banal na Pagsasanib',
		skillName_ma = 'Serangan Gabungan Ilahi',
		skillName = 'Divine Combo',
		describe_vn = 'Thiên thú và Angelmon giao nhau, Âm và Dương hình thành sự thống nhất và hòa hợp vĩnh cửu, phun ra một quả cầu ánh sáng thần thánh tối cao xuyên qua sóng và tấn công mục tiêu trong phạm vi chéo của kẻ thù, gây ra Celestial Beast và Angelmon #C0x3D8A99#4 80% Sát Thương Phép Thuật #C0x5B545B# #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đồng thời cộng thêm tất cả các hiệu ứng của Những chiêu thức đặc biệt của Celestialmon và Angelmon tới tất cả mục tiêu của kẻ thù.',
		describe_en = 'Celestial Beast and Angelmon intersect, Yin and Yang form eternal unity and harmony, unleashing a supreme divine light orb that pierces through waves and attacks targets within the enemy\'s diagonal range, dealing Celestial Beast and Angelmon\'s 80% Magic Damage, while also applying all special skill effects of Celestialmon and Angelmon to all enemy targets.',
		describe_th = 'สัตว์สวรรค์และแองเจลมอนมาบรรจบกัน หยินและหยางสร้างความเป็นหนึ่งเดียวและความสมดุลนิรันดร์ ปล่อยลูกแก้วแสงศักดิ์สิทธิ์สูงสุดทะลุผ่านคลื่นและโจมตีเป้าหมายในระยะทแยงของศัตรู ทำความเสียหายเวทมนตร์ 80% ของสัตว์สวรรค์และแองเจลมอน พร้อมทั้งเพิ่มผลพิเศษของทักษะเฉพาะของเซเลสเชียลมอนและแองเจลมอนไปยังเป้าหมายศัตรูทั้งหมด',
		describe_in = 'Celestial Beast dan Angelmon bersilangan, Yin dan Yang membentuk kesatuan dan harmoni abadi, melontarkan bola cahaya ilahi tertinggi yang menembus gelombang dan menyerang target dalam jangkauan diagonal musuh, mengakibatkan 80% Kerusakan Sihir dari Celestial Beast dan Angelmon, sekaligus menambahkan semua efek keterampilan khusus Celestialmon dan Angelmon ke semua target musuh.',
		describe_ph = 'Nagtagpo ang Celestial Beast at Angelmon, nabuo ang walang hanggang pagkakaisa at pagkakabagay ng Yin at Yang, bumuga ng isang pinakamataas na banal na bola ng liwanag na tumatagos sa mga alon at umaatake sa mga target sa diagonal na saklaw ng kaaway, nagdudulot ng 80% Magic Damage ng Celestial Beast at Angelmon, kasabay ng pagdadagdag ng lahat ng espesyal na epekto ng mga espesyal na kakayahan ng Celestialmon at Angelmon sa lahat ng mga target ng kaaway.',
		describe_ma = 'Celestial Beast dan Angelmon bertemu, Yin dan Yang membentuk kesatuan dan keharmonian abadi, memancarkan bola cahaya ilahi tertinggi yang menembusi gelombang dan menyerang sasaran dalam julat pepenjuru musuh, menyebabkan 80% Kerosakan Sihir Celestial Beast dan Angelmon, sambil menambahkan semua kesan khas daripada kemahiran Celestialmon dan Angelmon kepada semua sasaran musuh.',
		describe = 'Celestial Beast and Angelmon intersect, Yin and Yang form eternal unity and harmony, unleashing a supreme divine light orb that pierces through waves and attacks targets within the enemy\'s diagonal range, dealing Celestial Beast and Angelmon\'s 80% Magic Damage, while also applying all special skill effects of Celestialmon and Angelmon to all enemy targets.',
		zawakeEffectDesc = 'The celestial beast and Angelmon intersect, Yin and Yang form eternal unity and harmony, spewing a supreme divine light orb that pierces through waves and attacks targets within the enemy\'s cross range, causing Celestial Beast and Angelmon #C0x3D8A99#4 80% Magical Damage #C0x5B545B# #C0xF13B54# Magical Damage #C0x5B545B#, while additionally applying all effects of the special skills of Celestialmon and Angelmon to all enemy targets.',
		zawakeEffectDesc_en = 'The celestial beast and Angelmon intersect, Yin and Yang form eternal unity and harmony, spewing a supreme divine light orb that pierces through waves and attacks targets within the enemy\'s cross range, causing Celestial Beast and Angelmon #C0x3D8A99#4 80% Magical Damage #C0x5B545B# #C0xF13B54# Magical Damage #C0x5B545B#, while additionally applying all effects of the special skills of Celestialmon and Angelmon to all enemy targets.',
		zawakeEffectDesc_th = 'สัตว์สวรรค์และแองเจลมอนตัดกัน หยินและหยางสร้างความสามัคคีและความกลมเกลียวชั่วนิรันดร์ พ่นลูกกลมแสงศักดิ์สิทธิ์สูงสุดที่ทะลุผ่านคลื่นและโจมตีเป้าหมายในช่วงตัดของศัตรู ทำให้สัตว์สวรรค์และแองเจลมอน #C0x3D8A99#4 80% ความเสียหายเวทมนตร์ #C0x5B545B# #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# พร้อมกับเพิ่มผลของท่าไม้ตายพิเศษทั้งหมดของเซเลสเชียลมอนและแองเจลมอนไปยังเป้าหมายศัตรูทั้งหมด',
		zawakeEffectDesc_in = 'Binatang surgawi dan Angelmon bertemu, Yin dan Yang membentuk kesatuan dan keharmonisan abadi, memuntahkan sebuah bola cahaya ilahi tertinggi yang menembus gelombang dan menyerang target dalam jangkauan silang musuh, menyebabkan Binatang Surgawi dan Angelmon #C0x3D8A99#4 80% Kerusakan Magis #C0x5B545B# #C0xF13B54# Kerusakan Magis #C0x5B545B#, sekaligus menambahkan semua efek dari teknik khusus Celestialmon dan Angelmon ke semua target musuh.',
		zawakeEffectDesc_ph = 'Ang celestial beast at Angelmon ay nagtatagpo, Yin at Yang ay bumubuo ng walang hanggang pagkakaisa at pagkakaisa, nagbubuga ng isang mataas na banal na ilaw na bola na tumatagos sa mga alon at sumasalakay sa mga target sa loob ng krus na saklaw ng kaaway, nagdudulot ng Celestial Beast at Angelmon #C0x3D8A99#4 80% Magical Damage #C0x5B545B# #C0xF13B54# Magical Damage #C0x5B545B#, habang karagdagang inilalapat ang lahat ng mga epekto ng mga espesyal na kasanayan ng Celestialmon at Angelmon sa lahat ng mga target ng kaaway.',
		zawakeEffectDesc_ma = 'Binatang syurgawi dan Angelmon bertemu, Yin dan Yang membentuk kesatuan dan keharmonian abadi, memancarkan bola cahaya ilahi tertinggi yang menembusi gelombang dan menyerang sasaran dalam julat silang musuh, menyebabkan Binatang Syurgawi dan Angelmon #C0x3D8A99#4 80% Kerosakan Sihir #C0x5B545B# #C0xF13B54# Kerosakan Sihir #C0x5B545B#, serentak menambah semua kesan kemahiran khas Celestialmon dan Angelmon ke semua sasaran musuh.',
		zawakeEffectDesc_vn = 'Thiên thú và Angelmon giao nhau, Âm và Dương hình thành sự thống nhất và hòa hợp vĩnh cửu, phun ra một quả cầu ánh sáng thần thánh tối cao xuyên qua sóng và tấn công mục tiêu trong phạm vi chéo của kẻ thù, gây ra Celestial Beast và Angelmon #C0x3D8A99#4 80% Sát Thương Phép Thuật #C0x5B545B# #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đồng thời cộng thêm tất cả các hiệu ứng của Những chiêu thức đặc biệt của Celestialmon và Angelmon tới tất cả mục tiêu của kẻ thù.',
