	[19416] = {
		id = 19416,
		skillName_vn = 'Thiên thần hộ mệnh',
		skillName_en = 'Guardian angel',
		skillName_th = 'นางฟ้าผู้พิทักษ์',
		skillName_in = 'Malaikat pelindung',
		skillName_ph = 'Tagapagbantay na anghel',
		skillName_ma = 'Malaikat pelindung',
		skillName = 'Guardian angel',
		describe_vn = 'Vào trạng thái [Thánh Quang-Âm] trong 2 hiệp\n#F20# \n#F40##L10#Thánh Quang-Âm: #L0# Mức tăng ban đầu của #C0x5c9970#$(35+skillLevel*0.2-0.2)$%#C0x5B545B# tỷ lệ né tránh. Mỗi lần né thành công sẽ bị mất 10% tỷ lệ né tránh (tối đa 30%). Sau khi trạng thái Âm Quang Thánh kết thúc, tỷ lệ né tránh sẽ tăng vĩnh viễn thêm 10%.',
		describe_en = 'Enter the [Holy Light-Darkness] state for 2 turns. #Holy Light-Darkness: Initial increase of #C0x5c9970#$(35+skillLevel*0.2-0.2)$%#C0x5B545B# dodge rate. Each successful dodge reduces dodge rate by 10% (up to 30%). After the Holy Light-Darkness state ends, dodge rate permanently increases by 10%.',
		describe_th = 'เข้าสู่สถานะ [แสงศักดิ์สิทธิ์-ความมืด] เป็นเวลา 2 เทิร์น #แสงศักดิ์สิทธิ์-ความมืด: เพิ่มอัตราหลีกเลี่ยงเริ่มต้น #C0x5c9970#$(35+skillLevel*0.2-0.2)$%#C0x5B545B# ทุกครั้งที่หลีกเลี่ยงสำเร็จ จะสูญเสียอัตราหลีกเลี่ยง 10% (สูงสุด 30%) หลังจากสถานะแสง-ความมืดสิ้นสุดลง อัตราหลีกเลี่ยงจะเพิ่มขึ้นถาวรอีก 10%',
		describe_in = 'Masuk ke status [Cahaya Suci-Kegelapan] selama 2 giliran. #Cahaya Suci-Kegelapan: Peningkatan awal tingkat dodge sebesar #C0x5c9970#$(35+skillLevel*0.2-0.2)$%#C0x5B545B#. Setiap kali dodge berhasil, tingkat dodge berkurang 10% (maksimum 30%). Setelah status Cahaya Suci-Kegelapan berakhir, tingkat dodge akan meningkat permanen sebesar 10%.',
		describe_ph = 'Pumasok sa estado ng [Banal na Liwanag-Dilim] sa loob ng 2 turn. #Banal na Liwanag-Dilim: Unang pagtaas ng dodge rate ng #C0x5c9970#$(35+skillLevel*0.2-0.2)$%#C0x5B545B#. Sa bawat matagumpay na dodge, mababawasan ang dodge rate ng 10% (hanggang sa maximum na 30%). Pagkatapos ng estado ng Banal na Liwanag-Dilim, permanenteng tataas ang dodge rate ng 10%.',
		describe_ma = 'Masuk ke keadaan [Cahaya Suci-Kegelapan] selama 2 giliran. #Cahaya Suci-Kegelapan: Peningkatan awal kadar elak sebanyak #C0x5c9970#$(35+skillLevel*0.2-0.2)$%#C0x5B545B#. Setiap kali elak berjaya, kadar elak berkurang 10% (maksimum 30%). Selepas keadaan Cahaya Suci-Kegelapan berakhir, kadar elak akan meningkat kekal sebanyak 10%.',
		describe = 'Enter the [Holy Light-Darkness] state for 2 turns. #Holy Light-Darkness: Initial increase of #C0x5c9970#$(35+skillLevel*0.2-0.2)$%#C0x5B545B# dodge rate. Each successful dodge reduces dodge rate by 10% (up to 30%). After the Holy Light-Darkness state ends, dodge rate permanently increases by 10%.',
		starEffect = __data_t__starEffect[19416],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi không né tránh thành công, giảm 10% sát thương của kẻ tấn công trong 3 lượt (có thể tích lũy tối đa 2 lớp).',
		starEffectDesc = 'Additional Effect: When failing to dodge successfully, reduce the attacker\'s damage by 10% for 3 turns (can stack up to 2 layers).',
		starEffectDesc_en = 'Additional Effect: When failing to dodge successfully, reduce the attacker\'s damage by 10% for 3 turns (can stack up to 2 layers).',
