	[19513] = {
		id = 19513,
		skillName_vn = 'Thiên Phạt Thần Thánh',
		skillName_en = 'Divine Punishment',
		skillName_th = 'บทลงโทษศักดิ์สิทธิ์',
		skillName_in = 'Hukuman Ilahi',
		skillName_ph = 'Banal na Parusa',
		skillName_ma = 'Hukuman Ilahi',
		skillName = 'Divine Punishment',
		describe_vn = 'Angelmon bay thẳng lên trời, phóng ra ánh sáng chói lóa tấn công mục tiêu ở hàng sau của kẻ địch, gây ra #C0x3D8A99#300% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Sát Thương Phép Thuật#C0x5B545B# và giảm 45% khả năng phòng thủ ma thuật ở hàng trước của kẻ địch trong 3 lượt\n#F20# \n#F40#Nếu Thiên thú thân thiện hiện diện và chiêu thức đặc biệt của nó không bị hạn chế, chiêu thức đặc biệt hiện tại sẽ được thay thế bằng [#L10#Kỹ năng tấn công kết hợp#L0#]\n#F20# \n#F40##L10#Kỹ năng tấn công kết hợp: #L0# Tấn công tất cả mục tiêu của kẻ địch, gây sát thương bằng 480% tổng Sát Thương Phép Thuật của cả hai bên. Nó cũng bổ sung tất cả tác dụng của các chiêu thức đặc biệt của cả hai bên vào đòn tấn công tổng hợp vào tất cả các mục tiêu của kẻ thù, đồng thời tiêu diệt toàn bộ sự tức giận của cả hai bên trong đòn tấn công tổng hợp. Hệ số sát thương của kỹ năng tấn công tổng hợp là 80% tổng lực của cả hai bên trong đòn tấn công tổng hợp, không phát huy tác dụng hút máu của bên mình và tác dụng phản sát thương của mục tiêu. Nó có thời gian hồi chiêu là 5 vòng.',
		describe_en = 'Angelmon flies straight into the sky, releasing dazzling light to attack the enemy\'s back row, dealing #C0x3D8A99#300% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Magical Damage#C0x5B545B# and reducing magical defense by 45% of the enemy\'s front row for 3 turns.\n#F20# \n#F40#If a friendly celestial beast is present and its special skill is not restricted, the current special skill will be replaced by [#L10#Combined Attack Skill#L0#].\n#F20# \n#F40##L10#Combined Attack Skill: #L0# Attacks all enemy targets, dealing damage equal to 480% of the total Magical Damage of both sides. It also incorporates all effects of the special skills of both sides into the combined attack on all enemy targets, while consuming all anger of both sides during the combined attack. The damage coefficient of the combined attack skill is 80% of the total power of both sides during the combined attack, without triggering the life steal effect of the user or the damage reflection of the target. The cooldown time is 5 turns.',
		describe_th = 'Angelmon บินขึ้นตรงไปบนท้องฟ้า ปล่อยแสงสว่างจ้าโจมตีเป้าหมายแถวหลังของศัตรู สร้าง #C0x3D8A99#300% พลังโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# พลังโจมตีเวทมนตร์#C0x5B545B# และลดการป้องกันเวทมนตร์ของศัตรูแถวหน้า 45% เป็นเวลา 3 เทิร์น.\n#F20# \n#F40#หากสัตว์เทพพันธมิตรมีอยู่และสกิลพิเศษของมันไม่ได้รับการจำกัด สกิลพิเศษปัจจุบันจะถูกแทนที่ด้วย [#L10#สกิลโจมตีรวม#L0#].\n#F20# \n#F40##L10#สกิลโจมตีรวม: #L0#โจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเท่ากับ 480% ของพลังโจมตีเวทมนตร์รวมของทั้งสองฝ่าย รวมทั้งเพิ่มผลของสกิลพิเศษของทั้งสองฝ่ายเข้ากับการโจมตีรวมทุกเป้าหมายศัตรู พร้อมใช้ความโกรธทั้งหมดของทั้งสองฝ่ายในระหว่างการโจมตีรวม ค่าสัมประสิทธิ์ความเสียหายของสกิลโจมตีรวมคือ 80% ของพลังทั้งหมดของทั้งสองฝ่ายในระหว่างการโจมตีรวม ไม่เปิดใช้งานผลดูดเลือดของฝ่ายตนและผลสะท้อนความเสียหายของเป้าหมาย มีเวลาคูลดาวน์ 5 เทิร์น.',
		describe_in = 'Angelmon terbang langsung ke langit, melepaskan cahaya menyilaukan untuk menyerang target di barisan belakang musuh, memberikan #C0x3D8A99#300% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Kerusakan Sihir#C0x5B545B# dan mengurangi 45% pertahanan sihir musuh di barisan depan selama 3 giliran.\n#F20# \n#F40#Jika makhluk surgawi ramah hadir dan skill spesialnya tidak dibatasi, skill spesial saat ini akan digantikan dengan [#L10#Skill Serangan Gabungan#L0#].\n#F20# \n#F40##L10#Skill Serangan Gabungan: #L0# Menyerang semua target musuh, memberikan kerusakan sebesar 480% dari total Kerusakan Sihir kedua belah pihak. Skill ini juga menggabungkan semua efek skill spesial kedua belah pihak ke dalam serangan gabungan ke semua target musuh, sekaligus menghabiskan semua kemarahan kedua belah pihak dalam serangan gabungan tersebut. Koefisien kerusakan skill serangan gabungan adalah 80% dari total kekuatan kedua belah pihak selama serangan gabungan, tanpa mengaktifkan efek serap darah dari pihak sendiri maupun efek pantulan kerusakan dari target. Waktu cooldownnya adalah 5 giliran.',
		describe_ph = 'Angelmon ay lumilipad diretso sa langit, nagpapalabas ng matinding liwanag na umaatake sa mga target sa likurang hanay ng kalaban, nagdudulot ng #C0x3D8A99#300% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Magical Damage#C0x5B545B# at nagpapababa ng 45% na magical defense ng mga kalaban sa unahan na hanay sa loob ng 3 turn.\n#F20# \n#F40#Kung may presensiya ang isang friendly celestial beast at ang espesyal nitong skill ay hindi limitado, ang kasalukuyang espesyal na skill ay papalitan ng [#L10#Combined Attack Skill#L0#].\n#F20# \n#F40##L10#Combined Attack Skill: #L0# Umaatake sa lahat ng target ng kalaban, nagdudulot ng damage na katumbas ng 480% ng kabuuang Magical Damage ng dalawang panig. Ino-incorporate din nito ang lahat ng epekto ng espesyal na mga skill ng dalawang panig sa pinagsanib na pag-atake sa lahat ng target ng kaaway, at sinusunog ang lahat ng galit ng parehong panig sa pinagsanib na pag-atake. Ang damage coefficient ng combined attack skill ay 80% ng kabuuang lakas ng dalawang panig sa pinagsanib na pag-atake, hindi pinapagana ang life steal effect ng sariling panig at damage reflection ng target. May cooldown time na 5 turn.',
		describe_ma = 'Angelmon terbang terus ke langit, melepaskan cahaya yang menyilaukan untuk menyerang sasaran di barisan belakang musuh, menyebabkan #C0x3D8A99#300% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Kerosakan Sihir#C0x5B545B# dan mengurangkan pertahanan sihir musuh di barisan depan sebanyak 45% selama 3 pusingan.\n#F20# \n#F40#Jika haiwan syurgawi mesra hadir dan kemahiran istimewa mereka tidak dihadkan, kemahiran istimewa semasa akan digantikan dengan [#L10#Kemahiran Serangan Gabungan#L0#].\n#F20# \n#F40##L10#Kemahiran Serangan Gabungan: #L0# Menyerang semua sasaran musuh, menyebabkan kerosakan sebanyak 480% daripada Jumlah Kerosakan Sihir kedua-dua pihak. Ia juga menambah semua kesan kemahiran istimewa kedua-dua pihak ke dalam serangan gabungan ke semua sasaran musuh, dan menghabiskan semua kemarahan kedua-dua pihak dalam serangan gabungan tersebut. Koefisien kerosakan kemahiran serangan gabungan ialah 80% daripada jumlah kekuatan kedua-dua pihak dalam serangan gabungan tersebut, tanpa mengaktifkan kesan serapan darah pihak sendiri atau kesan pantulan kerosakan sasaran. Masa masa sejuk adalah 5 pusingan.',
		describe = 'Angelmon flies straight into the sky, releasing dazzling light to attack the enemy\'s back row, dealing #C0x3D8A99#300% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Magical Damage#C0x5B545B# and reducing magical defense by 45% of the enemy\'s front row for 3 turns.\n#F20# \n#F40#If a friendly celestial beast is present and its special skill is not restricted, the current special skill will be replaced by [#L10#Combined Attack Skill#L0#].\n#F20# \n#F40##L10#Combined Attack Skill: #L0# Attacks all enemy targets, dealing damage equal to 480% of the total Magical Damage of both sides. It also incorporates all effects of the special skills of both sides into the combined attack on all enemy targets, while consuming all anger of both sides during the combined attack. The damage coefficient of the combined attack skill is 80% of the total power of both sides during the combined attack, without triggering the life steal effect of the user or the damage reflection of the target. The cooldown time is 5 turns.',
		simDesc_vn = 'Angel Beast bay lên trời, phóng ra ánh sáng chói lóa để tấn công các mục tiêu ở hàng sau của kẻ thù và làm giảm khả năng phòng thủ phép thuật ở hàng đầu của kẻ thù đi một lượng nhất định.',
		simDesc_en = 'Angel Beast soars into the sky, unleashing a dazzling light to attack the targets in the enemy\'s back row and reduces the magical defense of the enemy\'s front row by a certain amount.',
		simDesc_th = 'แองเจิลบีสต์บินขึ้นสู่ท้องฟ้า ปล่อยแสงสว่างจ้าโจมตียังเป้าหมายในแถวหลังของศัตรู และลดความสามารถในการป้องกันเวทมนตร์ของแถวหน้าศัตรูลงในระดับหนึ่ง',
		simDesc_in = 'Angel Beast terbang ke langit, memancarkan cahaya yang menyilaukan untuk menyerang target di barisan belakang musuh dan mengurangi pertahanan sihir di barisan depan musuh dalam jumlah tertentu.',
		simDesc_ph = 'Ang Angel Beast ay lumilipad sa langit, nagpapalabas ng maliwanag na liwanag upang atakihin ang mga target sa likurang hanay ng kaaway at binabawasan ang mahikal na depensa ng panig na harapan ng kaaway ng isang tiyak na halaga.',
		simDesc_ma = 'Angel Beast terbang ke langit, memancarkan cahaya yang terang untuk menyerang sasaran di barisan belakang musuh dan mengurangkan pertahanan sihir di barisan hadapan musuh dalam jumlah tertentu.',
		simDesc = 'Angel Beast soars into the sky, unleashing a dazzling light to attack the targets in the enemy\'s back row and reduces the magical defense of the enemy\'s front row by a certain amount.',
		starEffect = __data_t__starEffect[19513],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng thêm: Nếu kỹ năng tất sát tiêu diệt mục tiêu, sẽ vào trạng thái <Quang Ẩn - Dương> trong 2 hiệp.',
		starEffectDesc = 'เอฟเฟกต์เพิ่มเติม: หากท่าไม้ตายสังหารเป้าหมายได้ จะเข้าสู่สถานะ [แสงเร้น · หยาง] เป็นเวลา 2 เทิร์น',
		starEffectDesc_en = 'Additional effect: If the skill finishes off the target, enter the <Quang Ẩn - Dương> state for 2 turns.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: หากท่าไม้ตายสามารถสังหารเป้าหมายได้ จะเข้าสู่สถานะ [แสงซ่อน · หยาง] เป็นเวลา 2 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Jika keterampilan membunuh sasaran, akan memasuki status <Quang Ẩn - Dương> selama 2 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Kung ang kasanayan ay pumatay ng target, papasok sa estado ng <Quang Ẩn - Dương> sa loob ng 2 turn.',
		starEffectDesc_ma = 'Kesan tambahan: Jika kemahiran membunuh sasaran, akan memasuki keadaan <Quang Ẩn - Dương> selama 2 pusingan.',
		zawakeEffect = __data_t__zawakeEffect[19513],
		-- {79003}
		zawakeEffectDesc = 'Angelmon flies into the sky, emitting dazzling light to attack an enemy target, causing #C0x3D8A99#550% Magic Damage#C0x5B545B#+$(skillLevel*4 *75)$\'s #C0xF13B54# Magic Damage #C0x5B545B#, reducing enemy front row\'s magic defense by 45% for 3 turns and removing negative slow effects on all allies\n#F20# \n#F40#If a friendly celestial beast is present and its special skill is not restricted, the current special skill will be replaced with <#L10#Combined Attack Skill#L0#>\n#F20# \n#F40##L10#Combined Attack Skill: #L0#Attacks a ranged enemy target, dealing damage equal to 360% of the total magic attack of both sides. It will add all effects of the corresponding special skills from both sides to the enemy target and eliminate all rage from both sides. The damage coefficient of the combined attack skill is 80% of the total from both sides and will not trigger lifesteal effects from either side nor the target\'s damage reflection effects. The cooldown is 5 turns.',
		zawakeEffectDesc_en = 'Angelmon flies into the sky, emitting dazzling light to attack an enemy target, causing #C0x3D8A99#550% Magic Damage#C0x5B545B#+$(skillLevel*4 *75)$\'s #C0xF13B54# Magic Damage #C0x5B545B#, reducing enemy front row\'s magic defense by 45% for 3 turns and removing negative slow effects on all allies\n#F20# \n#F40#If a friendly celestial beast is present and its special skill is not restricted, the current special skill will be replaced with <#L10#Combined Attack Skill#L0#>\n#F20# \n#F40##L10#Combined Attack Skill: #L0#Attacks a ranged enemy target, dealing damage equal to 360% of the total magic attack of both sides. It will add all effects of the corresponding special skills from both sides to the enemy target and eliminate all rage from both sides. The damage coefficient of the combined attack skill is 80% of the total from both sides and will not trigger lifesteal effects from either side nor the target\'s damage reflection effects. The cooldown is 5 turns.',
		zawakeEffectDesc_th = 'Angelmon บินขึ้นสู่ท้องฟ้า ปล่อยแสงสว่างเจิดจ้าโจมตีเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#550%#C0x5B545B#+$(skillLevel*4 *75)$’s #C0xF13B54#ความเสียหายเวทมนตร์ #C0x5B545B# ลดการป้องกันเวทมนตร์ของแถวหน้าศัตรูลง 45% เป็นเวลา 3 เทิร์น และลบทุกสถานะชะลอตัวเชิงลบของพันธมิตรทั้งหมด\n#F20# \n#F40#ถ้าสัตว์ฟ้าประเภทมิตรอยู่ในสนามและทักษะพิเศษของมันไม่ถูกจำกัด ทักษะพิเศษปัจจุบันจะถูกแทนที่ด้วย <#L10#ทักษะโจมตีผสม#L0#>\n#F20# \n#F40##L10#ทักษะโจมตีผสม: #L0#โจมตีเป้าหมายระยะไกลของศัตรู สร้างความเสียหายเท่ากับ 360% ของพลังเวทโจมตีรวมของทั้งสองฝ่าย จะเพิ่มผลของทักษะพิเศษของทั้งสองฝ่ายไปยังเป้าหมายศัตรูและกำจัดความโกรธทั้งหมดของทั้งสองฝ่าย ค่าสัดส่วนความเสียหายของทักษะโจมตีผสมคือ 80% ของรวมทั้งสองฝ่าย และจะไม่เปิดใช้งานผลดูดเลือดของฝ่ายใดฝ่ายหนึ่งและผลสะท้อนความเสียหายของเป้าหมาย มีคูลดาวน์ 5 เทิร์น',
		zawakeEffectDesc_in = 'Angelmon terbang ke langit, memancarkan cahaya yang menyilaukan menyerang satu target musuh, menyebabkan #C0x3D8A99#550% Kerusakan Magis#C0x5B545B#+$(skillLevel*4 *75)$’s #C0xF13B54# Kerusakan Magis #C0x5B545B#, mengurangi pertahanan sihir baris depan musuh sebesar 45% selama 3 giliran dan menghapus efek lambat negatif pada semua sekutu\n#F20# \n#F40#Jika makhluk surgawi ramah hadir dan skill khususnya tidak dibatasi, skill khusus saat ini akan digantikan dengan <#L10#Skill Serangan Gabungan#L0#>\n#F20# \n#F40##L10#Skill Serangan Gabungan: #L0#Menyerang target musuh jarak jauh, memberikan kerusakan sebesar 360% dari total serangan magis kedua belah pihak. Ini akan menambahkan semua efek dari skill khusus yang sesuai dari kedua belah pihak ke target musuh dan menghilangkan semua kemarahan dari kedua belah pihak. Koefisien kerusakan skill serangan gabungan adalah 80% dari total kedua belah pihak dan tidak akan memicu efek penyedotan darah dari salah satu pihak dan efek pantulan kerusakan dari target. Cooldown adalah 5 giliran.',
		zawakeEffectDesc_ph = 'Lumilipad ang Angelmon papuntang himpapawid, nagpapalabas ng maningning na liwanag upang atakihin ang isang target na kalaban, nagdudulot ng #C0x3D8A99#550% Pinsalang Mahika#C0x5B545B#+$(skillLevel*4 *75)$’s #C0xF13B54# Pinsalang Mahika #C0x5B545B#, nagpapababa ng magic defense ng unang hanay ng kalaban ng 45% sa loob ng 3 turn at inaalis ang negatibong slow effect sa lahat ng kaalyado\n#F20# \n#F40#Kung may kaibigang celestial beast na naroroon at ang espesyal na kasanayan nito ay hindi nakapigil, ang kasalukuyang espesyal na kasanayan ay papalitan ng <#L10#Pinagsamang Kasanayan sa Atake#L0#>\n#F20# \n#F40##L10#Pinagsamang Kasanayan sa Atake: #L0#Umaatake sa isang ranged na target ng kalaban, nagdudulot ng pinsala na katumbas ng 360% ng kabuuang magic attack ng dalawang panig. Dadagdag nito ang lahat ng epekto ng kaukulang espesyal na kasanayan mula sa dalawang panig sa target ng kalaban at aalisin ang lahat ng galit mula sa dalawang panig. Ang damage coefficient ng pinagsamang kasanayan sa atake ay 80% ng kabuuan ng dalawang panig at hindi i-trigger ang lifesteal effect ng alinmang panig o ang damage reflection effect ng target. May cooldown na 5 turn.',
		zawakeEffectDesc_ma = 'Angelmon terbang ke langit, memancarkan cahaya terang untuk menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#550% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4 *75)$’s #C0xF13B54# Kerosakan Sihir #C0x5B545B#, mengurangkan ketahanan sihir barisan depan musuh sebanyak 45% selama 3 pusingan dan menghapuskan kesan perlahan negatif pada semua sekutu\n#F20# \n#F40#Jika makhluk langit yang mesra hadir dan kemahiran istimewanya tidak dihadkan, kemahiran istimewa semasa akan digantikan dengan <#L10#Kemahiran Serangan Gabungan#L0#>\n#F20# \n#F40##L10#Kemahiran Serangan Gabungan: #L0#Menyerang sasaran musuh jarak jauh, menyebabkan kerosakan bersamaan 360% jumlah serangan sihir kedua-dua pihak. Ia akan menambah semua kesan kemahiran istimewa yang bersesuaian dari kedua-dua pihak ke sasaran musuh dan menghapuskan semua kemarahan kedua-dua pihak. Pekali kerosakan kemahiran serangan gabungan adalah 80% jumlah kedua-dua pihak dan tidak akan mencetuskan kesan sedutan darah dari mana-mana pihak mahupun kesan pantulan kerosakan sasaran. Masa sejuk adalah 5 pusingan.',
		zawakeEffectDesc_vn = 'Angelmon bay lên trời, phóng ra ánh sáng chói lóa tấn công một mục tiêu địch, gây ra #C0x3D8A99#550% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4 *75)$’s #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, giảm 45% khả năng phòng thủ phép thuật ở hàng trước của kẻ địch trong 3 lượt và loại bỏ hiệu ứng làm chậm tiêu cực trên tất cả đồng minh\n#F20# \n#F40#Nếu Thiên thú thân thiện hiện diện và chiêu thức đặc biệt của nó không bị hạn chế, chiêu thức đặc biệt hiện tại sẽ được thay thế bằng <#L10#Kỹ năng tấn công kết hợp#L0#>\n#F20# \n#F40##L10#Kỹ năng tấn công kết hợp: #L0# Tấn công mục tiêu tầm xa của kẻ địch, gây sát thương bằng 360% tổng đòn tấn công ma thuật của cả hai bên. Nó sẽ thêm tất cả tác dụng của các chiêu thức đặc biệt tương ứng của cả hai bên vào mục tiêu của kẻ thù và tiêu diệt mọi sự tức giận của cả hai bên. Hệ số sát thương của kỹ năng tấn công tổng hợp là 80% tổng cộng của cả hai bên và sẽ không kích hoạt tác dụng hút máu của một bên và tác dụng phản sát thương của mục tiêu. Nó có thời gian hồi chiêu là 5 vòng.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Removes all speed reduction effects from all allies',
		zawakeSimpleDesc_en = '#C0x5c9970#Removes all speed reduction effects from all allies',
		zawakeSimpleDesc_th = '#C0x5c9970#ลบเอฟเฟกต์ลดความเร็วทั้งหมดออกจากพันธมิตรทั้งหมด',
		zawakeSimpleDesc_in = '#C0x5c9970#Menghapus semua efek pengurangan kecepatan dari seluruh sekutu',
		zawakeSimpleDesc_ph = '#C0x5c9970#Inaalis ang lahat ng efekto ng pagbaba ng bilis sa lahat ng kakampi',
		zawakeSimpleDesc_ma = '#C0x5c9970#Buang semua kesan pengurangan kelajuan dari semua sekutu',
		zawakeSimpleDesc_vn = '#C0x5c9970#Xóa bỏ tất cả hiệu ứng giảm tốc độ cho toàn bộ đồng minh',
