	[19514] = {
		id = 19514,
		skillName_vn = 'Thần Thánh Hợp Kích',
		skillName_en = 'Divine Combo',
		skillName_th = 'คอมโบศักดิ์สิทธิ์',
		skillName_in = 'Kombinasi Ilahi',
		skillName_ph = 'Banal na Kombinasyon',
		skillName_ma = 'Gabungan Ilahi',
		skillName = 'Divine Combo',
		describe_vn = 'Thiên thú và Thiên thần giao nhau, Âm và Dương hình thành sự thống nhất và hòa hợp vĩnh cửu, bùng nổ với quả cầu ánh sáng thần thánh tối cao xuyên qua sóng nước và tấn công tất cả mục tiêu của kẻ thù, khiến Thiên thú và Thiên thần #C0x3D8A99#48 0% tấn Công Phép thuật #C0x5B545B# và #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đồng thời thêm tất cả các hiệu ứng của Thiên thú và Thiên thần. Các chiêu thức đặc biệt tương ứng của Angelmon tới tất cả các mục tiêu của kẻ thù.',
		describe_en = 'Heavenly Beast and Angel intersect, Yin and Yang form eternal unity and harmony, exploding with the supreme divine light orb that pierces through waves and strikes all enemy targets, causing Heavenly Beast and Angel to deal 48 0% Magical Attack and Magical Damage, while adding all effects of Heavenly Beast and Angel. Corresponding special skills of Angelmon hit all enemy targets.',
		describe_th = 'สัตว์สวรรค์และเทพเจ้าเดินทางมาบรรจบกัน ยันและหยางก่อตัวเป็นความสามัคคีและความกลมกลืนที่ยั่งยืน ระเบิดด้วยลูกแก้วแสงศักดิ์สิทธิ์สูงสุดที่ทะลุน้ำและโจมตีเป้าหมายศัตรูทั้งหมด ทำให้สัตว์สวรรค์และเทพเจ้าส่งผลต่อการโจมตีเวทมนตร์ 48 0% และความเสียหายเวทมนตร์ พร้อมทั้งเพิ่มเอฟเฟกต์ทั้งหมดของสัตว์สวรรค์และเทพเจ้า ทักษะพิเศษที่สอดคล้องของ Angelmon โจมตีเป้าหมายศัตรูทั้งหมด',
		describe_in = 'Makhluk Langit dan Malaikat bertemu, Yin dan Yang membentuk kesatuan dan harmoni abadi, meledak dengan bola cahaya ilahi tertinggi yang menembus gelombang air dan menyerang semua target musuh, menyebabkan Makhluk Langit dan Malaikat memberikan Serangan Sihir 48 0% dan Kerusakan Sihir, sekaligus menambahkan semua efek Makhluk Langit dan Malaikat. Kemampuan khusus Angelmon yang sesuai menyerang semua target musuh.',
		describe_ph = 'Nagtagpo ang Heavenly Beast at Angel, bumuo ang Yin at Yang ng walang hanggang pagkakaisa at pagkakabagay, sumabog gamit ang pinakamataas na makalangit na bola ng liwanag na tumatagos sa alon ng tubig at sumasalakay sa lahat ng kaaway, na nagdudulot ng 48 0% Magical Attack at Magical Damage mula sa Heavenly Beast at Angel, kasabay ng pagdaragdag ng lahat ng epektong dala ng Heavenly Beast at Angel. Ang mga kaugnay na espesyal na kakayahan ni Angelmon ay tumatama sa lahat ng kaaway.',
		describe_ma = 'Binatang Syurga dan Malaikat bertemu, Yin dan Yang membentuk kesatuan dan keharmonian abadi, meletup dengan bola cahaya ilahi tertinggi yang menembusi ombak dan menyerang semua sasaran musuh, menyebabkan Binatang Syurga dan Malaikat memberikan Serangan Sihir 48 0% dan Kerosakan Sihir, serta menambah semua kesan Binatang Syurga dan Malaikat. Kemahiran khas Angelmon yang sewajarnya menyerang semua sasaran musuh.',
		describe = 'Heavenly Beast and Angel intersect, Yin and Yang form eternal unity and harmony, exploding with the supreme divine light orb that pierces through waves and strikes all enemy targets, causing Heavenly Beast and Angel to deal 48 0% Magical Attack and Magical Damage, while adding all effects of Heavenly Beast and Angel. Corresponding special skills of Angelmon hit all enemy targets.',
		zawakeEffectDesc = 'Celestial beast and Angelmon intersect, Yin and Yang create eternal unity and harmony, spewing a supreme holy light sphere through water waves and attacking the enemy\'s piercing range target, causing Celestial beast and Angelmon #C0x3D8A99#3 60% Magic Damage #C0x5B545B# #C0xF13B54# Magic Damage #C0x5B545B#, while adding all special skill effects corresponding to Celestialmon and Angelmon to all enemy targets.',
		zawakeEffectDesc_en = 'Celestial beast and Angelmon intersect, Yin and Yang create eternal unity and harmony, spewing a supreme holy light sphere through water waves and attacking the enemy\'s piercing range target, causing Celestial beast and Angelmon #C0x3D8A99#3 60% Magic Damage #C0x5B545B# #C0xF13B54# Magic Damage #C0x5B545B#, while adding all special skill effects corresponding to Celestialmon and Angelmon to all enemy targets.',
		zawakeEffectDesc_th = 'สัตว์สวรรค์และ Angelmon พบกัน, หยินและหยางสร้างความเป็นเอกภาพและความกลมกลืนชั่วนิรันดร์, พ่นลูกแก้วแสงศักดิ์สิทธิ์สูงสุดผ่านคลื่นน้ำและโจมตีเป้าหมายที่ทะลุทะลวงของศัตรู, ทำให้สัตว์สวรรค์และ Angelmon #C0x3D8A99#3 60% พิษเวทย์มนตร์ #C0x5B545B# #C0xF13B54# พิษเวทย์มนตร์ #C0x5B545B#, พร้อมทั้งเพิ่มผลของทักษะพิเศษที่สอดคล้องกับ Celestialmon และ Angelmon ให้กับเป้าหมายศัตรูทั้งหมด',
		zawakeEffectDesc_in = 'Makhluk surgawi dan Angelmon bertemu, Yin dan Yang menciptakan kesatuan dan harmoni abadi, mengeluarkan bola cahaya suci tertinggi melalui ombak air dan menyerang target jangkauan tembus musuh, menyebabkan Makhluk surgawi dan Angelmon #C0x3D8A99#3 60% Damage Sihir #C0x5B545B# #C0xF13B54# Damage Sihir #C0x5B545B#, sekaligus menambahkan semua efek skill khusus yang sesuai dari Celestialmon dan Angelmon ke semua target musuh.',
		zawakeEffectDesc_ph = 'Nagkita ang Celestial beast at Angelmon, nilikha ng Yin at Yang ang pangmatagalang pagkakaisa at pagkakabagay, nagpapalabas ng pinakamataas na banal na bolang liwanag sa pamamagitan ng mga alon ng tubig at sumusugod sa target ng pumapasok na saklaw ng kalaban, na nagdudulot sa Celestial beast at Angelmon #C0x3D8A99#3 60% Magic Damage #C0x5B545B# #C0xF13B54# Magic Damage #C0x5B545B#, kasabay ng pagdaragdag ng lahat ng espesyal na epekto ng mga kakayahan na kaugnay ng Celestialmon at Angelmon sa lahat ng mga target ng kalaban.',
		zawakeEffectDesc_ma = 'Binatang langit dan Angelmon bertemu, Yin dan Yang mencipta perpaduan dan keharmonian abadi, memancarkan sfera cahaya suci tertinggi melalui ombak air dan menyerang sasaran jangkauan tembus musuh, menyebabkan Binatang langit dan Angelmon #C0x3D8A99#3 60% Kerosakan Sihir #C0x5B545B# #C0xF13B54# Kerosakan Sihir #C0x5B545B#, dan pada masa yang sama menambah semua kesan kemahiran khas yang sepadan daripada Celestialmon dan Angelmon ke semua sasaran musuh.',
		zawakeEffectDesc_vn = 'Thiên thú và Angelmon giao nhau, Âm và Dương tạo thành sự thống nhất và hòa hợp vĩnh cửu, phun ra một quả cầu ánh sáng thần thánh tối cao xuyên qua sóng nước và tấn công mục tiêu xuyên tầm của kẻ thù, khiến Thiên thú và Angelmon #C0x3D8A99#3 60% Sát Thương Phép Thuật #C0x5B545B# #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đồng thời thêm tất cả các hiệu ứng của Các chiêu thức đặc biệt tương ứng của Celestialmon và Angelmon tới tất cả các mục tiêu của kẻ thù.',
