	[19612] = {
		id = 19612,
		skillName_vn = 'Cột sáng nước thần',
		skillName_en = 'Spirit Water Column',
		skillName_th = 'เสาน้ำวิญญาณ',
		skillName_in = 'Kolom Air Roh',
		skillName_ph = 'Haligi ng Tubig na Espiritu',
		skillName_ma = 'Tiang Air Roh',
		skillName = 'Spirit Water Column',
		describe_vn = 'Aqua vẫy cây trượng thần thánh của mình và triệu hồi một chùm ánh sáng nước thần thánh, đối địch phương ngẫu nhiên 3 Cái mục tiêu tạo thành #C0x3D8A99#160% Phép Công #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, cũng vì tự thân cùng phe bạn công kích tối cao anh hùng chế tạo một vòng dòng nước vờn quanh, dòng nước sẽ triệt tiêu 25% Cuối cùng tổn thương, tiếp tục 2 Hiệp, dòng nước kết thúc sau lập tức khôi phục 20% Sinh mệnh hạn mức cao nhất lượng máu',
		describe_en = 'Aqua waves her holy staff and summons a cluster of sacred water light, attacking 3 random enemy targets, dealing #C0x3D8A99#160% Magic Power #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#. Additionally, she and her allies launch a supreme attack by creating a ring of swirling water around them, which negates 25% of the enemy\'s final damage for 2 turns. After the effect ends, the water ring immediately restores 20% of the maximum HP.',
		describe_th = 'อาคัว โบกไม้เท้าวิเศษของเธอและเรียกแสงน้ำศักดิ์สิทธิ์จำนวนหนึ่งโจมตีศัตรูแบบสุ่ม 3 เป้าหมาย สร้างความเสียหาย #C0x3D8A99#160% พลังเวท #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวท #C0x5B545B# นอกจากนี้ เธอและพวกพ้องใช้การโจมตีขั้นสูงสุดด้วยการสร้างวงน้ำวนรอบตัว ซึ่งจะต้านทานความเสียหายขั้นสุดท้ายของศัตรูได้ 25% เป็นเวลา 2 เทิร์น เมื่อวงน้ำสิ้นสุดจะฟื้นฟู HP สูงสุด 20% ทันที',
		describe_in = 'Aqua melambaikan tongkat suci miliknya dan memanggil kumpulan cahaya air suci, menyerang 3 target musuh acak dengan efek #C0x3D8A99#160% Kekuatan Sihir #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Selain itu, dia dan sekutunya melancarkan serangan tertinggi dengan menciptakan lingkaran air yang berputar di sekitar mereka, yang menetralkan 25% kerusakan akhir musuh selama 2 giliran. Setelah efek berakhir, lingkaran air tersebut langsung memulihkan 20% dari HP maksimum.',
		describe_ph = 'Aqua ayaw ang kanyang banal na tungkod at nagpalabas ng isang kumpol ng sagradong ilaw ng tubig, lumalaban sa 3 random na target na kalaban, na nagdudulot ng #C0x3D8A99#160% Lakas ng Magic #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pinsalang Magic #C0x5B545B#. Bukod dito, siya at ang kanyang mga kasamahan ay nagsagawa ng pinakamataas na atake sa pamamagitan ng paglikha ng isang singsing ng umiikot na tubig sa paligid nila, na naglalabas ng 25% ng huling pinsala ng kalaban sa loob ng 2 turn. Pagkatapos ng epekto, ang singsing ng tubig ay agad na magpapagaling ng 20% ng pinakamataas na HP.',
		describe_ma = 'Aqua melambaikan tongkat suci miliknya dan memanggil sekumpulan cahaya air suci, menyerang 3 sasaran musuh secara rawak, menghasilkan #C0x3D8A99#160% Kuasa Sihir #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Selain itu, dia dan sekutunya melancarkan serangan tertinggi dengan mencipta cincin air yang berputar di sekeliling, yang akan meneutralkan 25% Kerosakan Akhir musuh selama 2 pusingan. Setelah kesan berakhir, cincin air itu segera memulihkan 20% dari HP maksima.',
		describe = 'Aqua waves her holy staff and summons a cluster of sacred water light, attacking 3 random enemy targets, dealing #C0x3D8A99#160% Magic Power #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#. Additionally, she and her allies launch a supreme attack by creating a ring of swirling water around them, which negates 25% of the enemy\'s final damage for 2 turns. After the effect ends, the water ring immediately restores 20% of the maximum HP.',
		zawakeEffect = __data_t__zawakeEffect[19612],
		-- {79002}
		zawakeEffectDesc = 'Aqua shoots a water beam, dealing Magical Damage #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# to a single enemy target. Deals damage #C0x5B545B# and creates a water circle around it. The water helps absorb 25% of the final damage, lasting for 2 turns. Within the surrounding water, after each action, it can recover 20% of its maximum health.',
		zawakeEffectDesc_en = 'Aqua shoots a water beam, dealing Magical Damage #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# to a single enemy target. Deals damage #C0x5B545B# and creates a water circle around it. The water helps absorb 25% of the final damage, lasting for 2 turns. Within the surrounding water, after each action, it can recover 20% of its maximum health.',
		zawakeEffectDesc_th = 'Aqua ยิงลำแสงน้ำ สร้างความเสียหายเวทมนตร์ #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ไปยังเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหาย #C0x5B545B# และสร้างวงน้ำล้อมรอบ มวลน้ำจะช่วยดูดซับความเสียหายสุดท้าย 25% เป็นเวลา 2 เทิร์น ในบริเวณน้ำล้อมรอบ หลังจากแต่ละการกระทำ สามารถฟื้นฟูพลังชีวิตสูงสุด 20% ให้กับตัวเองได้',
		zawakeEffectDesc_in = 'Aqua menembakkan sinar air, memberikan Damage Ajaib #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ke satu target musuh. Memberikan damage #C0x5B545B# dan menciptakan lingkaran air di sekelilingnya. Air tersebut membantu menyerap 25% damage akhir, bertahan selama 2 giliran. Di dalam air tersebut, setelah setiap aksi, dapat memulihkan 20% dari total HP maksimal dirinya.',
		zawakeEffectDesc_ph = 'Aqua ay nagpapalabas ng sinag ng tubig, nagdudulot ng Magical Damage #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# sa isang target na kalaban. Nagdudulot ng pinsala #C0x5B545B# at lumilikha ng isang bilog ng tubig sa paligid nito. Tinutulungan ng tubig na sumipsip ng 25% ng huling pinsala, tumatagal ng 2 turn. Sa tubig na nakapalibot, pagkatapos ng bawat aksyon, maaari nitong maibalik ang 20% ng pinakamataas na HP para sa sarili.',
		zawakeEffectDesc_ma = 'Aqua menembakkan pancaran air, menyebabkan Kerosakan Ajaib #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ke satu sasaran musuh. Menyebabkan kerosakan #C0x5B545B# dan mencipta bulatan air di sekelilingnya. Air itu membantu menyerap 25% kerosakan terakhir, bertahan selama 2 pusingan. Dalam air sekeliling, selepas setiap tindakan, ia boleh memulihkan 20% daripada jumlah darah maksima untuk dirinya sendiri.',
		zawakeEffectDesc_vn = 'Aqua phóng một tia nước, gây ra Sát Thương Phép Thuật #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# lên một mục tiêu kẻ thù. Gây sát thương #C0x5B545B# và tạo một vòng tròn nước xung quanh nó. Nước sẽ giúp bù lại 25% sát thương cuối cùng, kéo dài trong 2 hiệp. Trong vùng nước bao quanh, sau mỗi hành động, nó có thể phục hồi 20% lượng máu tối đa cho bản thân.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Right after the water stream ends, restores 20% of max HP to self\n#F20# \n#F40##C0x5c9970#→While the water is flowing, after each action, restores 20% of max HP to self  ',
		zawakeSimpleDesc_en = 'Right after the water stream ends, restores 20% of max HP to self\n#F20# \n#F40##C0x5c9970#→While the water is flowing, after each action, restores 20% of max HP to self  ',
		zawakeSimpleDesc_th = 'ทันทีที่สายน้ำจบ ฟื้นฟู 20% HP สูงสุดให้ตัวเอง\n#F20# \n#F40##C0x5c9970#→ขณะสายน้ำกำลังไหล หลังจากทุกการกระทำ ฟื้นฟู 20% HP สูงสุดให้ตัวเอง',
		zawakeSimpleDesc_in = 'Segera setelah aliran air berakhir, memulihkan 20% HP maksimum untuk diri sendiri\n#F20# \n#F40##C0x5c9970#→Selama aliran air aktif, setelah setiap aksi, memulihkan 20% HP maksimum untuk diri sendiri  ',
		zawakeSimpleDesc_ph = 'Pagkatapos ng daloy ng tubig, agad na maghihilom ng 20% ng max HP sa sarili\n#F20# \n#F40##C0x5c9970#→Habang dumadaloy ang tubig, bawat aksyon ay maghihilom ng 20% max HP sa sarili  ',
		zawakeSimpleDesc_ma = 'Sebaik sahaja aliran air berakhir, pulihkan 20% HP maksimum kepada diri sendiri\n#F20# \n#F40##C0x5c9970#→Semasa air mengalir, selepas setiap tindakan, pulihkan 20% HP maksimum kepada diri sendiri  ',
		zawakeSimpleDesc_vn = 'Ngay sau khi dòng nước kết thúc, lượng máu 20% giới hạn sinh mệnh trên sẽ được phục hồi cho bản thân\n#F20# \n#F40##C0x5c9970#→ Trong khi dòng nước chảy, sau mỗi hành động của bản thân, lượng máu 20% sinh mệnh giới hạn trên sẽ được phục hồi cho chính mình.',
		upLvDesc = 'Fixed damage +192',
