	[19613] = {
		id = 19613,
		skillName_vn = 'Cơn thịnh nộ của biển cả',
		skillName_en = 'The Fury of the Sea',
		skillName_th = 'ความโกรธแค้นของท้องทะเล',
		skillName_in = 'Amarah Lautan',
		skillName_ph = 'Galit ng Dagat',
		skillName_ma = 'Kemarahan Lautan',
		skillName = 'The Fury of the Sea',
		describe_vn = 'Aqua giải phóng thần lực của mình để triệu hồi một làn sóng cuồng nộ khổng lồ. Làn sóng cuồng nộ sẽ nảy lên 6 lần giữa các mục tiêu đơn lẻ của kẻ địch. Lần nảy đầu tiên sẽ gây ra #C0x3D8A99#450% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# (Hai lần phóng liên tiếp có các mục tiêu khác nhau. Sẽ không có lần phóng khi chỉ có một mục tiêu trên sân. Sát thương sẽ giảm 30% cho mỗi lần phóng trong một lần phóng đặc biệt di chuyển). Mỗi lần phóng làm giảm tốc độ của nó đi 10% và khả năng dễ bị dính nước đi 8% (có thể chồng tối đa 5 lớp), kéo dài trong 2 vòng.',
		describe_en = 'Aqua unleashes her divine power to summon a giant wave of rage. The wave of rage bounces 6 times among single enemy targets. The first bounce deals #C0x3D8A99#450% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Magic Damage #C0x5B545B# (Two consecutive launches must hit different targets. There will be no launch if there is only one target on the field. Damage decreases by 30% for each bounce in a special moving launch). Each bounce reduces the target\'s speed by 10% and increases their vulnerability to water by 8% (can stack up to 5 layers), lasting 2 rounds.',
		describe_th = 'อควาใช้พลังเทพของเธอเพื่อเรียกคลื่นแห่งความโกรธขนาดใหญ่ คลื่นแห่งความโกรธจะดีดกลับ 6 ครั้งระหว่างเป้าหมายศัตรูเดี่ยว ครั้งดีดกลับแรกจะก่อให้เกิด #C0x3D8A99#450% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# (สองครั้งที่ยิงต่อเนื่องต้องมีเป้าหมายแตกต่างกัน จะไม่มีการยิงหากมีเป้าหมายเพียงหนึ่งในสนาม ความเสียหายจะลดลง 30% สำหรับแต่ละครั้งยิงในครั้งยิงพิเศษที่เคลื่อนที่) แต่ละครั้งยิงจะลดความเร็วของเป้าหมายลง 10% และเพิ่มความไวต่อการถูกโจมตีด้วยน้ำ 8% (สามารถซ้อนได้สูงสุด 5 ชั้น) เป็นเวลา 2 รอบ',
		describe_in = 'Aqua melepaskan kekuatan ilahinya untuk memanggil gelombang amarah raksasa. Gelombang amarah ini akan memantul sebanyak 6 kali di antara target musuh tunggal. Pantulan pertama akan menyebabkan #C0x3D8A99#450% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B# (Dua peluncuran berturut-turut harus mengenai target yang berbeda. Tidak akan ada peluncuran jika hanya ada satu target di medan. Kerusakan berkurang 30% untuk setiap pantulan dalam peluncuran khusus yang bergerak). Setiap pantulan mengurangi kecepatan target sebesar 10% dan meningkatkan kerentanannya terhadap air sebesar 8% (dapat bertumpuk hingga 5 lapisan), berlangsung selama 2 giliran.',
		describe_ph = 'Pinakawalan ni Aqua ang kanyang banal na kapangyarihan upang tawagin ang isang dambuhalang alon ng poot. Ang alon ng poot ay tatama ng 6 na beses sa mga magkakahiwalay na target ng kalaban. Ang unang talbog ay magdudulot ng #C0x3D8A99#450% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Magic Damage #C0x5B545B# (Ang dalawang magkasunod na atake ay dapat tumama sa magkaibang target. Walang atake kung iisa lang ang target sa larangan. Babawasan ng 30% ang pinsala sa bawat talbog sa isang espesyal na gumagalaw na atake). Bawat talbog ay babawasan ang bilis ng target ng 10% at tataas ang kanilang pagiging bulnerable sa tubig ng 8% (pwedeng mag-stack hanggang 5 layers), tumatagal ng 2 rounds.',
		describe_ma = 'Aqua membebaskan kuasa ketuhannya untuk memanggil gelombang kemarahan gergasi. Gelombang kemarahan akan memantul 6 kali di antara sasaran musuh tunggal. Pantulan pertama akan menyebabkan #C0x3D8A99#450% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B# (Dua pelancaran berturut-turut mesti mengenai sasaran berbeza. Tiada pelancaran akan berlaku jika hanya ada satu sasaran di medan. Kerosakan berkurang 30% bagi setiap pantulan dalam pelancaran bergerak khas). Setiap pantulan mengurangkan kelajuan sasaran sebanyak 10% dan meningkatkan kerentanan mereka terhadap air sebanyak 8% (boleh bertindih sehingga 5 lapisan), berlangsung selama 2 pusingan.',
		describe = 'Aqua unleashes her divine power to summon a giant wave of rage. The wave of rage bounces 6 times among single enemy targets. The first bounce deals #C0x3D8A99#450% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Magic Damage #C0x5B545B# (Two consecutive launches must hit different targets. There will be no launch if there is only one target on the field. Damage decreases by 30% for each bounce in a special moving launch). Each bounce reduces the target\'s speed by 10% and increases their vulnerability to water by 8% (can stack up to 5 layers), lasting 2 rounds.',
		simDesc_vn = 'Aqua triệu hồi một làn sóng cuồng nộ khổng lồ. Làn sóng cuồng nộ sẽ nảy lên giữa các mục tiêu đơn lẻ của kẻ thù và mỗi lần nảy sẽ làm giảm tốc độ của nó.',
		simDesc_en = 'Aqua summons a colossal wave of fury. The furious wave rebounds among the enemy\'s single targets, and each rebound reduces their speed.',
		simDesc_th = 'อาควาเรียกคลื่นแห่งความโกรธอันยิ่งใหญ่ คลื่นโกรธนั้นจะเด้งกระทบเป้าหมายเดี่ยวของศัตรู และทุกครั้งที่เด้งจะทำให้ความเร็วของเป้าหมายนั้นลดลง',
		simDesc_in = 'Aqua memanggil gelombang kemarahan yang besar. Gelombang kemarahan tersebut akan memantul di antara target tunggal musuh, dan setiap pantulan akan mengurangi kecepatan mereka.',
		simDesc_ph = 'Si Aqua ay nagpapatawag ng isang malaking alon ng poot. Ang alon ng poot ay tumatama sa mga iisang target ng kalaban at bawat tumama ay magpapababa ng kanilang bilis.',
		simDesc_ma = 'Aqua memanggil gelombang kemarahan yang besar. Gelombang kemarahan itu akan memantul di antara sasaran tunggal musuh dan setiap pantulan akan mengurangkan kelajuan mereka.',
		simDesc = 'Aqua summons a colossal wave of fury. The furious wave rebounds among the enemy\'s single targets, and each rebound reduces their speed.',
		starEffect = __data_t__starEffect[19613],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng phụ: Các đơn vị bị nảy trúng sẽ ngẫu nhiên bị giải trừ 1 đến 2 hiệu ứng có lợi, mục tiêu bị nảy trúng giảm 20% sát thương cộng thêm (không cộng dồn), kéo dài 2 lượt.',
		starEffectDesc = 'Side Effect: Units hit by the bounce will randomly have 1 to 2 beneficial effects removed. Targets hit by the bounce have their bonus damage reduced by 20% (non-stacking) for 2 turns.',
		starEffectDesc_en = 'Side Effect: Units hit by the bounce will randomly have 1 to 2 beneficial effects removed. Targets hit by the bounce have their bonus damage reduced by 20% (non-stacking) for 2 turns.',
		starEffectDesc_th = 'ผลข้างเคียง: หน่วยที่ถูกดีดโดนจะถูกลบเอฟเฟกต์บวก 1 ถึง 2 อย่างแบบสุ่ม เป้าหมายที่ถูกดีดโดนจะได้รับความเสียหายโบนัสลดลง 20% (ไม่สะสม) เป็นเวลา 2 เทิร์น',
		starEffectDesc_in = 'Efek Samping: Unit yang terkena pantulan akan secara acak kehilangan 1 sampai 2 efek menguntungkan. Target yang terkena pantulan akan mengurangi damage tambahan sebesar 20% (tidak dapat menumpuk) selama 2 giliran.',
		starEffectDesc_ph = 'Side Effect: Ang mga yunit na tinamaan ng bounce ay random na matatanggalan ng 1 hanggang 2 benepisyo. Ang target na tinamaan ng bounce ay mababawasan ng 20% ang bonus damage (hindi nag-iipon), tumatagal ng 2 turn.',
		starEffectDesc_ma = 'Kesan Sampingan: Unit yang terkena pantulan akan secara rawak kehilangan 1 hingga 2 kesan positif. Sasaran yang terkena pantulan akan mengurangkan kerosakan tambahan sebanyak 20% (tidak bertindan), selama 2 pusingan.',
		zawakeEffect = __data_t__zawakeEffect[19613],
		-- {79003, 1}
		zawakeEffectDesc = 'Additional effect: The unit being pushed will randomly have 1 to 2 buff effects dispelled, and the pushed target will have 20% reduced bonus damage and 20% critical rate (cannot stack) for 2 turns; and random control effects from allies\' formation will be removed.',
		zawakeEffectDesc_en = 'Additional effect: The unit being pushed will randomly have 1 to 2 buff effects dispelled, and the pushed target will have 20% reduced bonus damage and 20% critical rate (cannot stack) for 2 turns; and random control effects from allies\' formation will be removed.',
		zawakeEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: หน่วยที่ถูกผลักจะถูกลบเอฟเฟกต์บัฟ 1 ถึง 2 อย่างแบบสุ่ม และเป้าหมายที่ถูกผลักจะถูกลดความเสียหายโบนัส 20% และอัตราคริติคอล 20% (ไม่สามารถทับซ้อนได้) เป็นเวลา 2 เทิร์น; และเอฟเฟกต์ควบคุมแบบสุ่มจากทีมเพื่อนร่วมทีมจะถูกลบออก',
		zawakeEffectDesc_in = 'Efek tambahan: Unit yang terdorong akan secara acak kehilangan 1 hingga 2 efek buff, dan target yang terdorong akan mengalami pengurangan 20% damage tambahan dan 20% rate critical (tidak dapat ditumpuk) selama 2 giliran; serta efek kontrol acak dari formasi teman satu tim akan dihapus.',
		zawakeEffectDesc_ph = 'Karagdagang epekto: Ang yunit na itinutulak ay random na matatanggalan ng 1 hanggang 2 buff effects, at ang target na itinutulak ay mababawasan ng 20% karagdagang pinsala at 20% crit rate (hindi pwedeng mag-stack) sa loob ng 2 turn; at mawala ang random control effects mula sa ka-team na porma.',
		zawakeEffectDesc_ma = 'Kesan tambahan: Unit yang didorong akan terkena pembatalan secara rawak 1 hingga 2 kesan buff, dan sasaran yang didorong akan mengalami pengurangan 20% kerosakan tambahan dan 20% kadar kritikal (tidak boleh bertindan), berlangsung selama 2 giliran; serta kesan kawalan rawak dari barisan rakan sepasukan akan dihapuskan.',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: Đơn vị bị đẩy ra sẽ bị xua tan ngẫu nhiên bởi 1 đến 2 hiệu ứng buff, và mục tiêu bị đẩy ra sẽ bị giảm 20% sát thương cộng thêm và 20% tỷ lệ chí mạng (không thể cộng dồn), kéo dài trong 2 hiệp; và hiệu ứng khống chế ngẫu nhiên từ đội hình đồng đội sẽ bị loại bỏ.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Target pushed back will have -20% additional damage taken (non-stackable), lasts 2 turns\n#F20# \n#F40##C0x5c9970#→Target pushed back will have -20% additional damage taken and -20% crit hit rate (non-stackable), lasts 2 turns; also removes 1 random control effect from allied formation  ',
		zawakeSimpleDesc_en = 'Target pushed back will have -20% additional damage taken (non-stackable), lasts 2 turns\n#F20# \n#F40##C0x5c9970#→Target pushed back will have -20% additional damage taken and -20% crit hit rate (non-stackable), lasts 2 turns; also removes 1 random control effect from allied formation  ',
		zawakeSimpleDesc_th = 'เป้าหมายที่ถูกผลักจะได้รับความเสียหายเพิ่มเติมน้อยลง 20% (ไม่สามารถซ้อน), คงอยู่ 2 เทิร์น\n#F20# \n#F40##C0x5c9970#→เป้าหมายที่ถูกผลักจะได้รับความเสียหายเพิ่มเติมน้อยลง 20% และโอกาสคริติคอลลดลง 20% (ไม่สามารถซ้อน), คงอยู่ 2 เทิร์น; และลบ 1 เอฟเฟกต์ควบคุมแบบสุ่มจากทีม  ',
		zawakeSimpleDesc_in = 'Target yang terdorong akan mengurangi 20% kerusakan tambahan (tidak bisa ditumpuk), berlangsung selama 2 giliran\n#F20# \n#F40##C0x5c9970#→Target yang terdorong akan mengurangi 20% kerusakan tambahan dan 20% peluang crit (tidak bisa ditumpuk), berlangsung selama 2 giliran; dan menghapus 1 efek kontrol secara acak dari tim  ',
		zawakeSimpleDesc_ph = 'Ang target na naitulak ay babawasan ng 20% sa karagdagang damage (hindi pwedeng i-stack), tumatagal ng 2 turn\n#F20# \n#F40##C0x5c9970#→Ang target na naitulak ay babawasan ng 20% sa karagdagang damage at 20% crit hit rate (hindi pwedeng i-stack), tumatagal ng 2 turn; at mag-aalis ng 1 random control effect mula sa kakampi  ',
		zawakeSimpleDesc_ma = 'Sasaran yang ditolak akan mengurangkan 20% kerosakan tambahan (tidak boleh ditindih), bertahan selama 2 pusingan\n#F20# \n#F40##C0x5c9970#→Sasaran yang ditolak akan mengurangkan 20% kerosakan tambahan dan 20% kadar serangan kritikal (tidak boleh ditindih), bertahan selama 2 pusingan; dan membuang 1 kesan kawalan rawak dari pasukan  ',
		zawakeSimpleDesc_vn = 'Mục tiêu bị đẩy ra sẽ giảm 20% sát thương cộng thêm (không thể thay thế), tồn tại trong 2 lượt\n#F20# \n#F40##C0x5c9970#→Mục tiêu bị đẩy ra sẽ giảm 20% sát thương cộng thêm và 20% tỷ lệ trúng đích chí mạng (không thể chồng lên nhau), kéo dài trong 2 lượt; và loại bỏ 1 hiệu ứng khống chế ngẫu nhiên khỏi đội hình đồng minh',
