	[19616] = {
		id = 19616,
		skillName_vn = 'Thần Biển Che Chở',
		skillName_en = 'God of the Sea\'s Protection',
		skillName_th = 'เทพเจ้าทะเลคุ้มครอง',
		skillName_in = 'Dewa Laut yang Melindungi',
		skillName_ph = 'Diyos ng Proteksyon ng Dagat',
		skillName_ma = 'Dewa Laut yang Melindungi',
		skillName = 'God of the Sea\'s Protection',
		describe_vn = 'Trong trận chiến, tăng khả năng kháng đòn chí mạng của #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# của chính mình; tăng khả năng miễn nhiễm #C0x5c9970#$(10+skillLevel*0.08-0.08)$%#C0x5B545B# của một người. Xác suất khống chế (hiệu ứng đặc biệt, không thể xua tan), các đơn vị xung quanh bạn sẽ nhận được một nửa tiền thưởng; trước mỗi hiệp đấu lớn, hãy loại bỏ 2 hiệu ứng tiêu cực ngẫu nhiên và 2 hiệu ứng khống chế trong trại của bạn. Trước mỗi lần tự hành động, hãy loại bỏ 2 hiệu ứng khống chế ngẫu nhiên và 2 hiệu ứng tiêu cực trong trại của bạn. Khi kỹ năng bị động được loại bỏ thành công, bạn có thể khôi phục HP của chính mình bằng 250% phần thưởng phòng thủ phép thuật.',
		describe_en = 'In battle, increase your own critical hit resistance by #(60+skillLevel*0.2-0.2)%#. Increase the immunity rate of one ally by #(10+skillLevel*0.08-0.08)%#. The probability of control effects (special effect, cannot be dispelled) causes units nearby you to receive half the bonus. Before each major round, remove 2 random negative effects and 2 control effects in your camp. Before each autonomous action, remove 2 random control effects and 2 negative effects in your camp. When a passive skill is successfully removed, you can restore your HP by 250% of your magical defense reward.',
		describe_th = 'ระหว่างการต่อสู้ เพิ่มค่าต้านคริติคอลของตนเอง #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# และเพิ่มโอกาสต้านทานการควบคุมทั้งหมด #C0x5c9970#$(10+skillLevel*0.08-0.08)$%#C0x5B545B# (เอฟเฟกต์พิเศษ ไม่สามารถถูกลบได้) ยูนิตรอบข้างจะได้รับโบนัสครึ่งหนึ่งของค่านี้; ก่อนเริ่มแต่ละรอบใหญ่ จะลบดีบัฟแบบสุ่ม 2 ชนิดและเอฟเฟกต์ควบคุม 2 ชนิดจากฝ่ายเราแบบสุ่ม; ก่อนตนเองจะลงมือในแต่ละครั้ง จะลบดีบัฟและเอฟเฟกต์ควบคุมแบบสุ่มฝ่ายเราอย่างละ 2 ชนิด หากการลบของสกิลติดตัวสำเร็จ จะฟื้นฟูพลังชีวิตเท่ากับ 250% ของค่าพลังป้องกันเวทของตน',
		describe_in = 'Dalam pertarungan, tingkatkan ketahanan terhadap serangan kritikal diri sendiri sebesar #(60+skillLevel*0.2-0.2)%#. Tingkatkan tingkat imunisasi satu unit sebesar #(10+skillLevel*0.08-0.08)%#. Probabilitas kontrol (efek khusus, tidak bisa dihilangkan) membuat unit di sekitar Anda menerima setengah bonus. Sebelum setiap ronde besar, hapus 2 efek negatif acak dan 2 efek kontrol di perkemahan Anda. Sebelum setiap aksi otomatis, hapus 2 efek kontrol acak dan 2 efek negatif di perkemahan Anda. Saat skill pasif berhasil dihapus, Anda dapat memulihkan HP sendiri sebesar 250% dari hadiah pertahanan sihir.',
		describe_ph = 'Sa laban, dagdagan ang sariling tsansa ng pagtitiis sa critical hit ng #(60+skillLevel*0.2-0.2)%#. Dagdagan ang resistensya ng isa pang yunit ng #(10+skillLevel*0.08-0.08)%#. Ang pagkakataon ng control (espesyal na epekto, hindi maaalis) ay nagbibigay sa mga yunit sa iyong paligid ng kalahating bonus. Bago ang bawat malaking round, alisin ang 2 random na negatibong epekto at 2 control effects sa iyong kampo. Bago ang bawat automated na galaw, alisin ang 2 random na control effects at 2 negatibong epekto sa iyong kampo. Kapag matagumpay na naalis ang passive skill, maaari mong ibalik ang iyong HP ng 250% ng magic defense bonus.',
		describe_ma = 'Dalam pertempuran, tingkatkan keupayaan ketahanan serangan kritikal diri sendiri sebanyak #(60+skillLevel*0.2-0.2)%#. Tingkatkan imuniti satu unit sebanyak #(10+skillLevel*0.08-0.08)%#. Kebarangkalian kawalan (kesan khas, tidak boleh dibuang) menyebabkan unit di sekitar anda menerima separuh ganjaran. Sebelum setiap pusingan besar, alihkan 2 kesan negatif rawak dan 2 kesan kawalan dalam kem anda. Sebelum setiap tindakan automatik, alihkan 2 kesan kawalan rawak dan 2 kesan negatif dalam kem anda. Apabila kemahiran pasif berjaya dialihkan, anda boleh memulihkan HP sendiri sebanyak 250% ganjaran pertahanan sihir.',
		describe = 'In battle, increase your own critical hit resistance by #(60+skillLevel*0.2-0.2)%#. Increase the immunity rate of one ally by #(10+skillLevel*0.08-0.08)%#. The probability of control effects (special effect, cannot be dispelled) causes units nearby you to receive half the bonus. Before each major round, remove 2 random negative effects and 2 control effects in your camp. Before each autonomous action, remove 2 random control effects and 2 negative effects in your camp. When a passive skill is successfully removed, you can restore your HP by 250% of your magical defense reward.',
		starEffect = __data_t__starEffect[19616],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi bản thân có mặt trên sân, giảm 15% tốc độ và 15% tỷ lệ chí mạng của anh hùng có tỷ lệ chí mạng cao nhất của kẻ địch (không thể bị giải trừ).',
		starEffectDesc = 'Additional effect: When on the field, reduce the speed by 15% and the critical rate by 15% of the enemy\'s hero with the highest critical rate (cannot be removed).',
		starEffectDesc_en = 'Additional effect: When on the field, reduce the speed by 15% and the critical rate by 15% of the enemy\'s hero with the highest critical rate (cannot be removed).',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่ออยู่ในสนาม ลดความเร็วลง 15% และอัตราคริติคอลลง 15% ของฮีโร่ศัตรูที่มีอัตราคริติคอลสูงสุด (ไม่สามารถลบออกได้)',
		starEffectDesc_in = 'Efek tambahan: Saat berada di lapangan, kurangi kecepatan sebesar 15% dan rasio kritis sebesar 15% dari pahlawan musuh dengan rasio kritis tertinggi (tidak bisa dihilangkan).',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag nasa laban, bawasan ng 15% ang bilis at 15% ang kritikal na porsyento ng kaaway na may pinakamataas na kritikal na bayani (hindi matatanggal).',
		starEffectDesc_ma = 'Kesan tambahan: Apabila berada di medan, kurangkan kelajuan sebanyak 15% dan kadar kritikal sebanyak 15% wira musuh yang mempunyai kadar kritikal tertinggi (tidak boleh dibuang).',
		zawakeEffect = __data_t__zawakeEffect[19616],
		-- {79004}
		zawakeEffectDesc = 'In battle, increase your own critical hit resistance by #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#; increase yourself by #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# immunity to full Control Probability control (special effect, cannot be dispelled), surrounding units will receive half the bonus; before each major round, remove 2 random negative effects and 2 control effects in your camp, before each action, remove 2 random control effects and 2 negative effects in your camp, when the passive skill is successfully removed, you can recover your HP by 250% of the magic defense bonus.',
		zawakeEffectDesc_en = 'In battle, increase your own critical hit resistance by #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#; increase yourself by #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# immunity to full Control Probability control (special effect, cannot be dispelled), surrounding units will receive half the bonus; before each major round, remove 2 random negative effects and 2 control effects in your camp, before each action, remove 2 random control effects and 2 negative effects in your camp, when the passive skill is successfully removed, you can recover your HP by 250% of the magic defense bonus.',
		zawakeEffectDesc_th = 'ในระหว่างการต่อสู้ เพิ่มความสามารถในการต้านทานการโจมตีวิกฤตของ #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# ของตนเอง; เพิ่มความต้านทานของตนเองโดย #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# ต่อการป้องกันการควบคุมโอกาสทั้งหมด (เอฟเฟกต์พิเศษ ไม่สามารถขจัดได้) หน่วยรอบๆ คุณจะได้รับโบนัสครึ่งหนึ่ง; ก่อนแต่ละรอบใหญ่ ให้ลบ 2 เอฟเฟกต์ลบแบบสุ่มและ 2 เอฟเฟกต์ควบคุมในค่ายของคุณ ก่อนแต่ละการกระทำ ให้ลบ 2 เอฟเฟกต์ควบคุมแบบสุ่มและ 2 เอฟเฟกต์ลบในค่ายของคุณ เมื่อสกิลซ่อนถูกลบสำเร็จ คุณสามารถฟื้นฟู HP ของคุณโดยใช้ 250% ของโบนัสป้องกันเวทย์มนตร์',
		zawakeEffectDesc_in = 'Dalam pertarungan, tingkatkan ketahanan terhadap pukulan kritis sebanyak #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# dari diri sendiri; tingkatkan kekebalan diri sebesar #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# terhadap Kontrol Probabilitas penuh (efek khusus, tidak dapat dihilangkan), unit di sekitar Anda akan menerima setengah bonus; sebelum setiap ronde besar, hapus 2 efek negatif acak dan 2 efek kontrol di kamp Anda, sebelum setiap tindakan, hapus 2 efek kontrol acak dan 2 efek negatif di kamp Anda, ketika skill pasif berhasil dihilangkan, Anda dapat memulihkan HP sebesar 250% dari bonus pertahanan sihir.',
		zawakeEffectDesc_ph = 'Sa laban, pataasin ang sariling resistensya sa critical hit ng #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#; pataasin ang sariling #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# immunity sa buong Control Probability (special effect, hindi maalis), ang mga yunit sa paligid mo ay makakatanggap ng kalahati ng bonus; bago ang bawat malaking round, alisin ang 2 random negative effects at 2 control effects sa iyong camp, bago ang bawat aksyon, alisin ang 2 random control effects at 2 negative effects sa iyong camp, kapag matagumpay na natanggal ang passive skill, maaari mong i-recover ang iyong HP ng 250% ng magic defense bonus.',
		zawakeEffectDesc_ma = 'Dalam pertempuran, tingkatkan ketahanan serangan kritikal anda sebanyak #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#; tingkatkan imuniti diri sebanyak #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# kepada Kawalan Kebarangkalian penuh (kesan khas, tidak boleh dibuang), unit sekitar anda akan menerima separuh bonus; sebelum setiap pusingan besar, keluarkan 2 kesan negatif rawak dan 2 kesan kawalan dalam kem anda, sebelum setiap tindakan, keluarkan 2 kesan kawalan rawak dan 2 kesan negatif dalam kem anda, apabila kemahiran pasif berjaya dibuang, anda boleh memulihkan HP anda sebanyak 250% daripada bonus pertahanan sihir.',
		zawakeEffectDesc_vn = 'Trong trận chiến, tăng khả năng kháng đòn chí mạng của #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# của chính mình; tăng bản thân #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# miễn nhiễm toàn quyền Kiểm soát Xác suất kiểm soát (hiệu ứng đặc biệt, không thể xua tan), các đơn vị xung quanh bạn sẽ nhận được một nửa tiền thưởng; trước mỗi vòng lớn, loại bỏ 2 hiệu ứng tiêu cực ngẫu nhiên và 2 hiệu ứng khống chế trong trại của chính bạn, trước mỗi hành động, loại bỏ 2 hiệu ứng kiểm soát ngẫu nhiên và 2 hiệu ứng tiêu cực trong trại của chính bạn, khi kỹ năng bị động được loại bỏ thành công, bạn có thể phục hồi HP của mình bằng 250% phần thưởng phòng thủ phép thuật.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increases immunity to full control effects by 20%~30% (special effect, cannot be dispelled), and nearby units receive half of the bonus.',
		zawakeSimpleDesc_en = 'Increases immunity to full control effects by 20%~30% (special effect, cannot be dispelled), and nearby units receive half of the bonus.',
		zawakeSimpleDesc_th = 'เพิ่มความสามารถในการต้านทานการควบคุมทั้งหมดขึ้น 20%~30% (เอฟเฟกต์พิเศษ ไม่สามารถลบได้) และยูนิตที่อยู่ใกล้จะได้รับโบนัสครึ่งหนึ่ง',
		zawakeSimpleDesc_in = 'Meningkatkan kekebalan terhadap efek kontrol penuh sebesar 20%~30% (efek khusus, tidak bisa dihapus), dan unit di sekitarmu akan menerima setengah dari bonus tersebut.',
		zawakeSimpleDesc_ph = 'Pinapataas ang immunity laban sa kabuuang kontrol ng 20%~30% (espesyal na epekto, hindi matatanggal), at ang mga kalapit na yunit ay makakatanggap ng kalahati ng bonus.',
		zawakeSimpleDesc_ma = 'Meningkatkan kebal terhadap kawalan sepenuhnya sebanyak 20%~30% (kesan khas, tidak boleh dihapuskan) dan unit di sekeliling anda akan menerima separuh daripada bonus tersebut.',
		zawakeSimpleDesc_vn = 'Tăng khả năng miễn nhiễm với toàn quyền kiểm soát lên 20%~30% (hiệu ứng đặc biệt, không thể xóa bỏ) và các đơn vị xung quanh bạn sẽ nhận được một nửa tiền thưởng.',
		iconRes = 'battle/skill_icon/skill_19616.png',
