	[19621] = {
		id = 19621,
		skillName_vn = 'Sóng nước',
		skillName_en = 'Water waves',
		skillName_th = 'คลื่นน้ำ',
		skillName_in = 'Gelombang air',
		skillName_ph = 'Alon ng tubig',
		skillName_ma = 'Ombak air',
		skillName = 'Water waves',
		describe_vn = '#C0xC0C0C0#我是英雄#C0x5B545B#\n#F20#\n#F40#Gây ra #C0x3D8A99#120% Sát Thương Phép Thuật vào một mục tiêu kẻ thù#C0x5B545B#+$(skillLevel*4*24)$#C 0xF13B54#Spell Sát thương#C0x5B545B#, tăng 15% tỷ lệ chống tội phạm và 20% tỷ lệ kháng cự của bản thân trong 2 lượt\n#F20#\n#F40#Xóa hai hiệu ứng tiêu cực và khống chế ngẫu nhiên của một tướng đồng minh (loại bỏ tổng cộng hai hiệu ứng, ưu tiên cho mục tiêu bị kiểm soát)',
		describe_en = '#C0xC0C0C0#I am a hero#C0x5B545B#\n#F20#\n#F40#Deals #C0x3D8A99#120% Magic Damage to a single enemy target#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Spell Damage#C0x5B545B#, increases own Crime Resistance by 15% and Resistance Rate by 20% for 2 rounds \n#F20#\n#F40#Removes two negative effects and random control effects from one allied hero (removes a total of two effects, prioritizing controlled targets)',
		describe_th = '#C0xC0C0C0#ฉันคือฮีโร่#C0x5B545B#\n#F20#\n#F40#สร้างความเสียหายเวทมนตร์ #C0x3D8A99#120% ไปยังเป้าหมายศัตรูหนึ่งตัว#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# เพิ่มอัตราต้านอาชญากรรมของตัวเอง 15% และอัตราต้านทาน 20% เป็นเวลา 2 รอบ \n#F20#\n#F40#ลบเอฟเฟกต์ลบและการควบคุมแบบสุ่ม 2 อย่างจากฮีโร่พันธมิตร 1 ตัว (ลบทั้งหมด 2 เอฟเฟกต์ โดยให้ความสำคัญกับเป้าหมายที่ถูกควบคุม)',
		describe_in = '#C0xC0C0C0#Aku adalah pahlawan#C0x5B545B#\n#F20#\n#F40#Memberikan #C0x3D8A99#120% Kerusakan Sihir kepada satu target musuh#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerusakan Sihir#C0x5B545B#, meningkatkan tingkat Resistensi Kriminal sebesar 15% dan tingkat Resistansi sebesar 20% pada diri sendiri selama 2 giliran \n#F20#\n#F40#Menghapus dua efek negatif dan efek kontrol acak dari satu pahlawan sekutu (menghapus total dua efek, memprioritaskan target yang sedang dikendalikan)',
		describe_ph = '#C0xC0C0C0#Ako ay isang bayani#C0x5B545B#\n#F20#\n#F40#Nagdadala ng #C0x3D8A99#120% Magic Damage sa isang kalabang target#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Spell Damage#C0x5B545B#, pinapataas ang sariling Crime Resistance ng 15% at Resistance Rate ng 20% sa loob ng 2 rounds \n#F20#\n#F40#Nagtatanggal ng dalawang negatibong epekto at random control mula sa isang kaalyadong bayani (tinatanggal ang kabuuang dalawang epekto, inuuna ang mga target na kontrolado)',
		describe_ma = '#C0xC0C0C0#Saya adalah wira#C0x5B545B#\n#F20#\n#F40#Menyebabkan #C0x3D8A99#120% Kerosakan Sihir kepada satu sasaran musuh#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerosakan Sihir#C0x5B545B#, meningkatkan kadar Ketahanan Jenayah diri sendiri sebanyak 15% dan kadar Tahanan sebanyak 20% selama 2 pusingan \n#F20#\n#F40#Menghapus dua kesan negatif dan kawalan rawak daripada seorang wira sekutu (menghapuskan sejumlah dua kesan, mengutamakan sasaran yang sedang dikawal)',
		describe = '#C0xC0C0C0#I am a hero#C0x5B545B#\n#F20#\n#F40#Deals #C0x3D8A99#120% Magic Damage to a single enemy target#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Spell Damage#C0x5B545B#, increases own Crime Resistance by 15% and Resistance Rate by 20% for 2 rounds \n#F20#\n#F40#Removes two negative effects and random control effects from one allied hero (removes a total of two effects, prioritizing controlled targets)',
		simDesc_vn = '#C0xC0C0C0# Overlord of the Original Sea#C0x5B545B##F20##F40#Gây sát thương phép cho một kẻ địch, tăng tỷ lệ chống tội phạm và tỷ lệ kháng cự của bản thân trong 2 lượt#F20##F40#Xóa hai hiệu ứng tiêu cực và kiểm soát ngẫu nhiên của một anh hùng đồng minh',
		simDesc_en = '#C0xC0C0C0# Overlord of the Original Sea #C0x5B545B##F20##F40# Deals magic damage to an enemy, increases own crime resistance rate and resistance chance for 2 turns #F20##F40# Removes two negative effects and random control effects from an allied hero',
		simDesc_th = '#C0xC0C0C0# เจ้าแห่งทะเลดั้งเดิม #C0x5B545B##F20##F40# สร้างความเสียหายเวทมนตร์ต่อศัตรูหนึ่งตัว เพิ่มอัตราการต่อต้านอาชญากรรมและอัตราการต้านทานของตนเองเป็นเวลา 2 เทิร์น #F20##F40# ล้างสถานะลบสองอย่างและการควบคุมแบบสุ่มจากฮีโร่ฝ่ายเดียวกัน',
		simDesc_in = '#C0xC0C0C0# Penguasa Laut Asli #C0x5B545B##F20##F40# Memberikan damage sihir kepada satu musuh, meningkatkan tingkat perlawanan terhadap kejahatan dan tingkat ketahanan diri selama 2 giliran #F20##F40# Menghapus dua efek negatif dan kontrol acak dari pahlawan sekutu',
		simDesc_ph = '#C0xC0C0C0# Overlord ng Orihinal na Dagat #C0x5B545B##F20##F40# Nagdudulot ng magic damage sa isang kaaway, pinapataas ang sariling crime resistance rate at resistance chance sa loob ng 2 turn #F20##F40# Tinatanggal ang dalawang negatibong epekto at random control mula sa isang allied hero',
		simDesc_ma = '#C0xC0C0C0# Penguasa Laut Asal #C0x5B545B##F20##F40# Menyebabkan kerosakan sihir pada satu musuh, meningkatkan kadar ketahanan jenayah dan kadar ketahanan sendiri selama 2 giliran #F20##F40# Menghapus dua kesan negatif dan kawalan rawak daripada wira sekutu',
		simDesc = '#C0xC0C0C0# Overlord of the Original Sea #C0x5B545B##F20##F40# Deals magic damage to an enemy, increases own crime resistance rate and resistance chance for 2 turns #F20##F40# Removes two negative effects and random control effects from an allied hero',
		upLvDesc = 'Fixed damage +96',
