	[19622] = {
		id = 19622,
		skillName_vn = 'Xâm chiếm',
		skillName_en = 'Invasion',
		skillName_th = 'การรุกราน',
		skillName_in = 'Invasi',
		skillName_ph = 'Pagsalakay',
		skillName_ma = 'Penaklukan',
		skillName = 'Invasion',
		describe_vn = '#C0xC0C0C0#Nơi trú ẩn của biển, rộng ngàn dặm#C0x5B545B#\n#F20#\n#F40#Gây ra #C0x3D8A99#180% phép thuật tấn công vào danh sách mục tiêu#C0 x5B545B#+$(skillLevel*4*48)$’s #C0xF13B54# Spell sát thương#C0x5B545B# tạo ra Nước bao quanh, nước có thể bù đắp 30% sát thương cuối cùng, tồn tại trong 2 hiệp. Trong vòng tròn nước, mỗi khi hành động, bạn sẽ ngay lập tức phục hồi 15% giới hạn máu của mình.\n#F20#\n#F40# Và thêm [Transfer Purification] cho đồng đội của bạn có đòn tấn công cao nhất. Các hiệu ứng bất thường mà đồng đội phải chịu sẽ được chuyển sang Kyogre ban đầu, kéo dài trong 1 hiệp\n#F20#\n#F40#Khi [Mưa Mưa] được kích hoạt, hai hiệu ứng trên sẽ +1 cho hiệp.',
		describe_en = 'Sanctuary of the sea, spanning a thousand miles. Deals 180% magic damage to the target list. +$(skillLevel*4*48)$’s Spell damage generates surrounding Water, which can absorb 30% of the final damage and lasts for 2 turns. Within the water circle, each action instantly restores 15% of your max HP. And grants [Transfer Purification] to your ally with the highest attack. Any abnormal effects on that ally will be transferred to the original Kyogre, lasting for 1 turn. When [Rain Rain] is activated, the above two effects gain +1 turn.',
		describe_th = 'ที่หลบภัยของทะเล กว้างไกลถึงพันไมล์ ก่อให้เกิดความเสียหายเวทมนตร์ 180% ต่อรายชื่อเป้าหมาย +$(skillLevel*4*48)$ พลังโจมตีเวทมนตร์ สร้างน้ำล้อมรอบ น้ำสามารถชดเชยความเสียหายสุดท้ายได้ 30% และคงอยู่ 2 เทิร์น ในวงน้ำ ทุกครั้งที่กระทำการ คุณจะฟื้นฟูพลังชีวิตสูงสุด 15% ทันที และเพิ่ม [Transfer Purification] ให้กับเพื่อนร่วมทีมที่มีพลังโจมตีสูงที่สุด ผลกระทบผิดปกติที่เพื่อนร่วมทีมได้รับ จะถูกย้ายไปยัง Kyogre ดั้งเดิม คงอยู่ 1 เทิร์น เมื่อ [Rain Rain] ถูกเปิดใช้งาน เอฟเฟกต์ทั้งสองข้างต้นจะเพิ่มอีก 1 เทิร์น',
		describe_in = 'Sarang laut yang luas hingga ribuan mil. Menimbulkan 180% serangan sihir pada daftar target. +$(skillLevel*4*48)$ kerusakan mantra menghasilkan air di sekeliling, air dapat menutupi 30% dari kerusakan akhir dan bertahan selama 2 giliran. Dalam lingkaran air, setiap kali bertindak, kamu langsung memulihkan 15% batas HP-mu. Dan memberikan [Transfer Purification] kepada rekan tim dengan serangan tertinggi. Efek abnormal yang dialami oleh rekan tim akan dialihkan ke Kyogre asli, bertahan selama 1 giliran. Ketika [Rain Rain] diaktifkan, dua efek di atas bertambah +1 giliran.',
		describe_ph = 'Kanlungan ng dagat, sumasaklaw ng libong milya. Nagdudulot ng 180% magic damage sa listahan ng mga target. +$(skillLevel*4*48)$ Spell damage ang lumilikha ng tubig sa paligid, ang tubig ay maaaring tumakip ng 30% ng huling pinsala at tumatagal ng 2 turn. Sa loob ng bilog ng tubig, sa bawat pagkilos, agad mong naibabalik ang 15% ng iyong maximum HP. At nagdaragdag ng [Transfer Purification] para sa kasama mo na may pinakamataas na atake. Ang mga abnormal effects na nararanasan ng kasama ay maililipat kay orihinal na Kyogre, tumatagal ng 1 turn. Kapag na-activate ang [Rain Rain], ang dalawang epekto sa itaas ay +1 turn.',
		describe_ma = 'Tempat perlindungan laut, meluas hingga ribuan batu. Menyebabkan 180% serangan sihir ke senarai sasaran. +$(skillLevel*4*48)$ kerosakan Sihir menghasilkan air di sekeliling, air boleh menampung 30% kerosakan akhir dan bertahan selama 2 pusingan. Dalam bulatan air, setiap kali bertindak, kamu segera memulihkan 15% had HP kamu. Dan menambah [Transfer Purification] kepada rakan sepasukan yang mempunyai serangan tertinggi. Kesan tidak normal yang dialami rakan sepasukan akan dipindahkan kepada Kyogre asal, bertahan selama 1 pusingan. Apabila [Rain Rain] diaktifkan, dua kesan di atas bertambah +1 pusingan.',
		describe = 'Sanctuary of the sea, spanning a thousand miles. Deals 180% magic damage to the target list. +$(skillLevel*4*48)$’s Spell damage generates surrounding Water, which can absorb 30% of the final damage and lasts for 2 turns. Within the water circle, each action instantly restores 15% of your max HP. And grants [Transfer Purification] to your ally with the highest attack. Any abnormal effects on that ally will be transferred to the original Kyogre, lasting for 1 turn. When [Rain Rain] is activated, the above two effects gain +1 turn.',
		simDesc_vn = '#C0xC0C0C0# Nơi trú ẩn của biển, rộng hàng ngàn dặm #C0x5B545B##F20##F40#Gây sát thương phép lên danh sách mục tiêu, tạo vòng tròn nước xung quanh bản thân và một anh hùng nước ngẫu nhiên của nhóm, kéo dài 2 hiệp. Trong thời gian chảy nước, nó ngay lập tức phục hồi máu của chính mình sau mỗi hành động #F20##F40#Thêm [Transfer Purification] cho đồng đội có đòn tấn công cao nhất, kéo dài trong 1 hiệp#F20##F40#Khi [Mưa Mưa] được kích hoạt, hai hiệu ứng trên sẽ là +1 cho hiệp.',
		simDesc_en = '#C0xC0C0C0# Sanctuary of the Sea, spanning thousands of miles #C0x5B545B##F20##F40#Deals magical damage to a list of targets, creating a circle of water around yourself and a random water hero in the team, lasting 2 turns. During the flowing water, it instantly restores its own HP after each action #F20##F40#Adds <Transfer Purification> to the teammate with the highest attack, lasting 1 turn#F20##F40#When <Rain Rain> is activated, the two above effects are extended by +1 turn.',
		simDesc_th = '#C0xC0C0C0# ที่หลบภัยของทะเล กว้างนับพันไมล์ #C0x5B545B##F20##F40#ก่อให้เกิดความเสียหายเวทมนตร์กับรายชื่อเป้าหมาย สร้างวงกลมน้ำรอบตัวเองและฮีโร่น้ำแบบสุ่มหนึ่งคนในกลุ่ม เป็นเวลานาน 2 เทิร์น ขณะน้ำไหลจะฟื้นฟูเลือดตัวเองทันทีหลังจากแต่ละการกระทำ #F20##F40#เพิ่ม [Transfer Purification] ให้กับเพื่อนร่วมทีมที่มีการโจมตีสูงสุด เป็นเวลา 1 เทิร์น#F20##F40#เมื่อ [Rain Rain] ถูกเปิดใช้ เอฟเฟกต์ทั้งสองด้านบนจะเพิ่มขึ้น 1 เทิร์น',
		simDesc_in = '#C0xC0C0C0# Tempat Perlindungan Laut, membentang ribuan mil #C0x5B545B##F20##F40#Memberikan kerusakan sihir ke daftar target, menciptakan lingkaran air di sekitar diri sendiri dan satu pahlawan air acak dari tim, berlangsung selama 2 giliran. Selama aliran air, segera memulihkan HP sendiri setelah setiap aksi #F20##F40#Menambahkan <Transfer Purification> ke rekan setim dengan serangan tertinggi, berlangsung 1 giliran#F20##F40#Ketika <Rain Rain> diaktifkan, dua efek di atas bertambah +1 giliran.',
		simDesc_ph = '#C0xC0C0C0# Tahanan ng Dagat, sumasaklaw ng libu-libong milya #C0x5B545B##F20##F40#Nagdudulot ng magic damage sa listahan ng mga target, lumilikha ng bilog ng tubig sa paligid ng sarili at isang random na water hero sa grupo, tumatagal ng 2 turns. Sa panahon ng pagdaloy ng tubig, agad nitong nire-recover ang sarili nitong HP pagkatapos ng bawat aksyon #F20##F40#Nagdadagdag ng <Transfer Purification> sa kakampi na may pinakamataas na atake, tumatagal ng 1 turn#F20##F40#Kapag na-activate ang <Rain Rain>, ang dalawang epekto sa itaas ay tataas ng +1 turn.',
		simDesc_ma = '#C0xC0C0C0# Tempat Perlindungan Laut, meliputi ribuan batu #C0x5B545B##F20##F40#Menggunakan kerosakan sihir pada senarai sasaran, mencipta bulatan air di sekitar diri sendiri dan seorang wira air rawak dari pasukan, berlangsung selama 2 giliran. Semasa air mengalir, ia serta-merta memulihkan HP sendiri selepas setiap tindakan #F20##F40#Menambah <Transfer Purification> kepada rakan sepasukan dengan serangan tertinggi, berlangsung 1 giliran#F20##F40#Apabila <Rain Rain> diaktifkan, dua kesan di atas bertambah +1 giliran.',
		simDesc = '#C0xC0C0C0# Sanctuary of the Sea, spanning thousands of miles #C0x5B545B##F20##F40#Deals magical damage to a list of targets, creating a circle of water around yourself and a random water hero in the team, lasting 2 turns. During the flowing water, it instantly restores its own HP after each action #F20##F40#Adds [Transfer Purification] to the teammate with the highest attack, lasting 1 turn#F20##F40#When [Rain Rain] is activated, the two above effects are extended by +1 turn.',
