	[19628] = {
		id = 19628,
		skillName_vn = 'Đỉnh cao sắc bén',
		skillName_en = 'Sharp peak',
		skillName_th = 'ยอดแหลม',
		skillName_in = 'Puncak tajam',
		skillName_ph = 'Matinding Talim',
		skillName_ma = 'Puncak runcing',
		skillName = 'Sharp peak',
		describe_vn = 'Gabite dùng răng cứng cắn mục tiêu đơn lẻ của kẻ địch, gây ra #C0xE69900#80% vật công#C0x5B545B#+$(skillLevel*4*24)$ Sát Thương Vật Lý#C0xF13B54#, tăng 15% tốc độ của bản thân trong 2 lượt',
		describe_en = 'Gabite bites a single enemy target with its hard teeth, dealing #C0xE69900#80% physical attack#C0x5B545B# + $(skillLevel*4*24)$ physical damage#C0xF13B54#, and increases its own speed by 15% for 2 turns.',
		describe_th = 'กาบาอิทใช้ฟันแข็งกัดเป้าหมายศัตรูเดี่ยว สร้างความเสียหายทางกายภาพ #C0xE69900#80%#C0x5B545B# + $(skillLevel*4*24)$ และเพิ่มความเร็วตัวเอง 15% เป็นเวลา 2 เทิร์น',
		describe_in = 'Gabite menggunakan gigi keras untuk menggigit satu target musuh, memberikan #C0xE69900#80% serangan fisik#C0x5B545B# + $(skillLevel*4*24)$ kerusakan fisik#C0xF13B54#, serta meningkatkan kecepatan dirinya sebesar 15% selama 2 giliran.',
		describe_ph = 'Gumamit si Gabite ng matitigas na ngipin upang kagatin ang isang kalaban na target, na nagdudulot ng #C0xE69900#80% pisikal na atake#C0x5B545B# + $(skillLevel*4*24)$ Pisikal na pinsala#C0xF13B54#, at nagpapataas ng 15% bilis ng sarili sa loob ng 2 paligid.',
		describe_ma = 'Gabite menggunakan gigi keras untuk menggigit sasaran musuh tunggal, menyebabkan #C0xE69900#80% serangan fizikal#C0x5B545B# + $(skillLevel*4*24)$ Kerosakan Fizikal#C0xF13B54#, dan meningkatkan kelajuan sendiri sebanyak 15% selama 2 pusingan.',
		describe = 'Gabite bites a single enemy target with its hard teeth, dealing #C0xE69900#80% physical attack#C0x5B545B# + $(skillLevel*4*24)$ physical damage#C0xF13B54#, and increases its own speed by 15% for 2 turns.',
		simDesc_vn = 'Rồng Cứng dùng những chiếc răng cứng để cắn vào mục tiêu đơn lẻ của đối phương.',
