	[19631] = {
		id = 19631,
		skillName_vn = 'Sóng nước',
		skillName_en = 'Water waves',
		skillName_th = 'คลื่นน้ำ',
		skillName_in = 'Gelombang air',
		skillName_ph = 'Mga alon ng tubig',
		skillName_ma = 'Gelombang air',
		skillName = 'Water waves',
		describe_vn = '#C0xC0C0C0#我是英雄#C0x5B545B#\n#F20#\n#F40#Gây ra #C0x3D8A99#120% Sát Thương Phép Thuật vào một mục tiêu kẻ thù#C0x5B545B#+$(skillLevel*4*24)$#C 0xF13B54#Spell Sát thương#C0x5B545B#, tăng 15% tỷ lệ chống tội phạm và 20% tỷ lệ kháng cự của bản thân trong 2 lượt\n#F20#\n#F40#Xóa hai hiệu ứng tiêu cực và khống chế ngẫu nhiên của một tướng đồng minh (loại bỏ tổng cộng hai hiệu ứng, ưu tiên cho mục tiêu bị kiểm soát)',
		describe_en = '#C0xC0C0C0#I am a hero#C0x5B545B#\n#F20#\n#F40#Deals #C0x3D8A99#120% Magic Damage to a single enemy target#C0x5B545B#+$(skillLevel*4*24)$#C 0xF13B54#Spell Damage#C0x5B545B#, increases own 15% Crime Resistance rate and 20% Resistance rate for 2 rounds\n#F20#\n#F40#Removes two random negative and control effects from an allied hero (removes a total of two effects, prioritizing controlled targets)',
		describe_th = '#C0xC0C0C0#ฉันคือฮีโร่#C0x5B545B#\n#F20#\n#F40#สร้างความเสียหายเวทมนตร์ #C0x3D8A99#120% ไปยังเป้าหมายศัตรูหนึ่งตัว#C0x5B545B#+$(skillLevel*4*24)$#C 0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B#, เพิ่มอัตราต้านอาชญากรรมของตนเอง 15% และอัตราต้านทาน 20% เป็นเวลา 2 รอบ\n#F20#\n#F40#ลบสถานะลบและควบคุมสองอย่างแบบสุ่มจากฮีโร่พันธมิตรหนึ่งตัว (ลบสถานะทั้งหมดสองอย่าง โดยให้ความสำคัญกับเป้าหมายที่ถูกควบคุม)',
		describe_in = '#C0xC0C0C0#Aku adalah pahlawan#C0x5B545B#\n#F20#\n#F40#Memberikan #C0x3D8A99#120% Kerusakan Sihir ke satu target musuh#C0x5B545B#+$(skillLevel*4*24)$#C 0xF13B54#Kerusakan Sihir#C0x5B545B#, meningkatkan tingkat Ketahanan Kejahatan sendiri sebesar 15% dan tingkat Perlindungan sebesar 20% selama 2 giliran\n#F20#\n#F40#Menghapus dua efek negatif dan kontrol secara acak dari satu pahlawan sekutu (menghapus total dua efek, memprioritaskan target yang dalam kondisi kontrol)',
		describe_ph = '#C0xC0C0C0#Ako ay bayani#C0x5B545B#\n#F20#\n#F40#Nagdudulot ng #C0x3D8A99#120% Magic Damage sa isang kalabang target#C0x5B545B#+$(skillLevel*4*24)$#C 0xF13B54#Spell Damage#C0x5B545B#, pinapataas ang 15% na rate ng Crime Resistance at 20% na rate ng Resistance sa sarili sa loob ng 2 rounds \n#F20#\n#F40#Inaalis ang dalawang random na negatibong epekto at kontrol mula sa isang alyadong bayani (alinman ang dalawang epekto, prayoridad ang mga target na kontrolado)',
		describe_ma = '#C0xC0C0C0#Saya adalah wira#C0x5B545B#\n#F20#\n#F40#Menyebabkan #C0x3D8A99#120% Kerosakan Sihir pada satu sasaran musuh#C0x5B545B#+$(skillLevel*4*24)$#C 0xF13B54#Kerosakan Sihir#C0x5B545B#, meningkatkan kadar Ketahanan Jenayah diri sendiri sebanyak 15% dan kadar Ketahanan sebanyak 20% selama 2 pusingan\n#F20#\n#F40#Menghapus dua kesan negatif dan kawalan secara rawak daripada satu wira sekutu (menghapus jumlah dua kesan, memberi keutamaan kepada sasaran yang dikawal)',
		describe = '#C0xC0C0C0#I am a hero#C0x5B545B#\n#F20#\n#F40#Deals #C0x3D8A99#120% Magic Damage to a single enemy target#C0x5B545B#+$(skillLevel*4*24)$#C 0xF13B54#Spell Damage#C0x5B545B#, increases own 15% Crime Resistance rate and 20% Resistance rate for 2 rounds\n#F20#\n#F40#Removes two random negative and control effects from an allied hero (removes a total of two effects, prioritizing controlled targets)',
		simDesc_vn = '#C0xC0C0C0# Overlord of the Original Sea#C0x5B545B##F20##F40#Gây sát thương phép cho một kẻ địch, tăng tỷ lệ chống tội phạm và tỷ lệ kháng cự của bản thân trong 2 lượt#F20##F40#Xóa hai hiệu ứng tiêu cực và kiểm soát ngẫu nhiên của một anh hùng đồng minh',
		simDesc_en = '#C0xC0C0C0# Overlord of the Original Sea #C0x5B545B##F20##F40# Deals magic damage to an enemy, increases crime resistance and self resistance rate for 2 turns #F20##F40# Removes two negative effects and random control effects from an allied hero',
		simDesc_th = '#C0xC0C0C0# ผู้ปกครองแห่งทะเลดั้งเดิม #C0x5B545B##F20##F40# สร้างความเสียหายเวทมนตร์กับศัตรูหนึ่งตัว เพิ่มอัตราต้านอาชญากรรมและอัตราการต้านทานของตัวเองเป็นเวลา 2 เทิร์น #F20##F40# ลบสถานะลบสองอย่างและการควบคุมแบบสุ่มของฮีโร่พันธมิตรหนึ่งตัว',
		simDesc_in = '#C0xC0C0C0# Penguasa Laut Asli #C0x5B545B##F20##F40# Memberikan kerusakan sihir pada satu musuh, meningkatkan tingkat resistensi terhadap kejahatan dan resistensi diri selama 2 giliran #F20##F40# Menghapus dua efek negatif dan kontrol acak dari satu pahlawan sekutu',
		simDesc_ph = '#C0xC0C0C0# Overlord ng Original Sea #C0x5B545B##F20##F40# Nagdudulot ng magic damage sa isang kalaban, nagpapataas ng crime resistance at self resistance rate ng 2 turn #F20##F40# Nag-aalis ng dalawang negative effects at random control mula sa isang allied hero',
		simDesc_ma = '#C0xC0C0C0# Penguasa Laut Asal #C0x5B545B##F20##F40# Menyebabkan kerosakan sihir kepada musuh, meningkatkan kadar ketahanan jenayah dan ketahanan diri selama 2 pusingan #F20##F40# Menghapus dua kesan negatif dan kawalan rawak daripada wira sekutu',
		simDesc = '#C0xC0C0C0# Overlord of the Original Sea #C0x5B545B##F20##F40# Deals magic damage to an enemy, increases crime resistance and self resistance rate for 2 turns #F20##F40# Removes two negative effects and random control effects from an allied hero',
		upLvDesc = 'Fixed damage +96',
		upLvDesc_en = 'Fixed damage +96',
		upLvDesc_th = 'ความเสียหายคงที่ +96',
		upLvDesc_in = 'Kerusakan tetap +96',
