	[19632] = {
		id = 19632,
		skillName_vn = 'Xâm chiếm',
		skillName_en = 'Invade',
		skillName_th = 'รุกราน',
		skillName_in = 'Menyerbu',
		skillName_ph = 'Sumalakay',
		skillName_ma = 'Menyerang',
		skillName = 'Invade',
		describe_vn = '#C0xC0C0C0#Nơi trú ẩn của biển, rộng ngàn dặm#C0x5B545B#\n#F20#\n#F40#Gây ra #C0x3D8A99#180% phép thuật tấn công vào danh sách mục tiêu#C0 x5B545B#+$(skillLevel*4*48)$’s #C0xF13B54# Spell sát thương#C0x5B545B# tạo ra Nước bao quanh, nước có thể bù đắp 30% sát thương cuối cùng, tồn tại trong 2 hiệp. Trong vòng tròn nước, mỗi khi hành động, bạn sẽ ngay lập tức phục hồi 15% giới hạn máu của mình.\n#F20#\n#F40# Và thêm [Transfer Purification] cho đồng đội của bạn có đòn tấn công cao nhất. Các hiệu ứng bất thường mà đồng đội phải chịu sẽ được chuyển sang Kyogre ban đầu, kéo dài trong 1 hiệp\n#F20#\n#F40#Khi [Mưa Mưa] được kích hoạt, hai hiệu ứng trên sẽ +1 cho hiệp.',
		describe_en = 'Sanctuary of the sea, vast for a thousand miles. Deals 180% magic damage to a list of targets +$(skillLevel*4*48)$’s spell damage. Creates surrounding Water that can absorb 30% of the final damage, lasting 2 turns. Within the water circle, each time you act, immediately restore 15% of your maximum HP. And adds [Transfer Purification] to your ally with the highest attack. Abnormal effects the ally suffers will transfer to the original Kyogre, lasting for 1 turn. When [Rain Rain] is activated, the above two effects increase by 1 turn.',
		describe_th = 'ที่พักของทะเล กว้างไกลนับพันไมล์ สร้างความเสียหายเวทมนตร์ 180% ไปยังรายชื่อเป้าหมาย +$(skillLevel*4*48)$’s ความเสียหายเวทมนตร์ สร้างน้ำล้อมรอบ น้ำสามารถดูดซับความเสียหายสุดท้าย 30% ใช้งานได้ 2 เทิร์น ภายในวงน้ำ ทุกครั้งที่คุณทำการกระทำ จะฟื้นฟู HP สูงสุดของคุณทันที 15% และเพิ่ม [Transfer Purification] ให้กับพันธมิตรที่มีพลังโจมตีสูงสุด ผลเสียที่พันธมิตรได้รับจะถูกส่งต่อไปยัง Kyogre ต้นฉบับ ใช้งานได้ 1 เทิร์น เมื่อ [Rain Rain] ถูกใช้งาน เอฟเฟกต์ทั้งสองข้างต้นจะเพิ่มขึ้นอีก 1 เทิร์น',
		describe_in = 'Perlindungan laut, luasnya ribuan mil. Menyebabkan 180% serangan sihir ke daftar target +$(skillLevel*4*48)$’s damage sihir. Membuat Air di sekeliling yang dapat menutupi 30% kerusakan akhir, bertahan selama 2 giliran. Dalam lingkaran air, setiap kali bertindak, langsung pulihkan 15% batas maksimal HP kamu. Dan menambahkan [Transfer Purification] kepada rekan dengan serangan tertinggi. Efek abnormal yang dialami rekan dipindahkan ke Kyogre asli, bertahan selama 1 giliran. Saat [Rain Rain] diaktifkan, kedua efek di atas bertambah 1 giliran.',
		describe_ph = 'Kanlungan ng dagat, malawak ng isang libong milya. Nagdudulot ng 180% na magic na pinsala sa mga listahan ng target +$(skillLevel*4*48)$’s magic na pinsala. Lumilikha ng Tubig sa paligid, ang tubig ay maaaring sumipsip ng 30% ng huling pinsala, tumatagal ng 2 rounds. Sa loob ng bilog ng tubig, sa bawat aksyon mo, agad na ibabalik ang 15% ng maximum HP mo. At nagdaragdag ng [Transfer Purification] sa kakampi mo na may pinakamataas na atake. Ang mga abnormal na epektong nararanasan ng kakampi ay ililipat sa orihinal na Kyogre, tumatagal ng 1 round. Kapag na-activate ang [Rain Rain], ang dalawang epektong ito ay madadagdagan ng 1 round.',
		describe_ma = 'Tempat perlindungan laut, luas hingga ribuan batu. Menyebabkan 180% serangan sihir ke senarai sasaran +$(skillLevel*4*48)$’s kerosakan sihir. Mewujudkan Air sekeliling yang boleh menyerap 30% kerosakan akhir, bertahan selama 2 giliran. Dalam bulatan air, setiap kali bertindak, pulihkan 15% had maksimum HP anda dengan serta-merta. Dan menambah [Transfer Purification] untuk rakan sepasukan dengan serangan tertinggi. Kesan abnormal yang rakan alami akan dipindahkan kepada Kyogre asal, bertahan selama 1 giliran. Apabila [Rain Rain] diaktifkan, dua kesan di atas akan bertambah 1 giliran.',
		describe = 'Sanctuary of the sea, vast for a thousand miles. Deals 180% magic damage to a list of targets +$(skillLevel*4*48)$’s spell damage. Creates surrounding Water that can absorb 30% of the final damage, lasting 2 turns. Within the water circle, each time you act, immediately restore 15% of your maximum HP. And adds [Transfer Purification] to your ally with the highest attack. Abnormal effects the ally suffers will transfer to the original Kyogre, lasting for 1 turn. When [Rain Rain] is activated, the above two effects increase by 1 turn.',
		simDesc_vn = '#C0xC0C0C0# Nơi trú ẩn của biển, rộng hàng ngàn dặm #C0x5B545B##F20##F40#Gây sát thương phép lên danh sách mục tiêu, tạo vòng tròn nước xung quanh bản thân và một anh hùng nước ngẫu nhiên của nhóm, kéo dài 2 hiệp. Trong thời gian chảy nước, nó ngay lập tức phục hồi máu của chính mình sau mỗi hành động #F20##F40#Thêm [Transfer Purification] cho đồng đội có đòn tấn công cao nhất, kéo dài trong 1 hiệp#F20##F40#Khi [Mưa Mưa] được kích hoạt, hai hiệu ứng trên sẽ là +1 cho hiệp.',
		simDesc_en = 'Shelter of the sea, spanning thousands of miles. Deals magic damage to a list of targets, creating a circle of water around yourself and a random water hero in the team, lasting 2 turns. While the water flows, it instantly restores its own health after each action. Adds <Transfer Purification> to the teammate with the highest attack, lasting 1 turn. When <Rain Rain> is activated, the above two effects gain +1 turn.',
		simDesc_th = 'ที่หลบภัยของทะเล กว้างหลายพันไมล์ สร้างความเสียหายเวทแก่รายชื่อเป้าหมาย สร้างวงน้ำรอบตัวเองและฮีโร่น้ำสุ่มหนึ่งตัวในทีม เป็นเวลา 2 เทิร์น ในช่วงที่น้ำไหล จะฟื้นฟูพลังชีวิตของตัวเองทันทีหลังจากแต่ละการกระทำ เพิ่ม [Transfer Purification] ให้กับเพื่อนร่วมทีมที่มีการโจมตีสูงสุด เป็นเวลา 1 เทิร์น เมื่อ [Rain Rain] ถูกเปิดใช้ เอฟเฟกต์ทั้งสองข้างต้นจะเพิ่มอีก 1 เทิร์น',
		simDesc_in = 'Sarang perlindungan laut, membentang ribuan mil. Memberikan kerusakan sihir pada daftar target, menciptakan lingkaran air di sekitar diri sendiri dan seorang pahlawan air acak dalam tim, berlangsung selama 2 giliran. Selama air mengalir, segera memulihkan kesehatan sendiri setelah setiap aksi. Menambahkan <Transfer Purification> kepada rekan tim dengan serangan tertinggi, berlangsung selama 1 giliran. Ketika <Rain Rain> aktif, dua efek di atas bertambah +1 giliran.',
		simDesc_ph = 'Kanlungan ng dagat, umaabot ng libu-libong milya. Nagdudulot ng magic damage sa listahan ng mga target, lumilikha ng bilog ng tubig sa paligid ng sarili at isang random na water hero sa grupo, tumatagal ng 2 turn. Habang umaagos ang tubig, agad nitong nire-recover ang sariling HP pagkatapos ng bawat aksyon. Nagdaragdag ng <Transfer Purification> sa ka-team na may pinakamataas na attack, tumatagal ng 1 turn. Kapag na-activate ang <Rain Rain>, ang dalawang epekto sa itaas ay nadaragdagan ng +1 turn.',
		simDesc_ma = 'Tempat perlindungan laut, merangkumi ribuan batu. Memberi kerosakan magik kepada senarai sasaran, mewujudkan bulatan air di sekitar diri sendiri dan seorang wira air rawak dalam kumpulan, berlangsung selama 2 giliran. Semasa air mengalir, ia segera memulihkan kesihatan sendiri selepas setiap tindakan. Menambah <Transfer Purification> kepada rakan sepasukan yang mempunyai serangan tertinggi, berlangsung selama 1 giliran. Apabila <Rain Rain> diaktifkan, kedua-dua kesan di atas mendapat tambahan +1 giliran.',
		simDesc = 'Shelter of the sea, spanning thousands of miles. Deals magic damage to a list of targets, creating a circle of water around yourself and a random water hero in the team, lasting 2 turns. While the water flows, it instantly restores its own health after each action. Adds [Transfer Purification] to the teammate with the highest attack, lasting 1 turn. When [Rain Rain] is activated, the above two effects gain +1 turn.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
		upLvDesc_in = 'Kerusakan tetap +192',
		upLvDesc_ph = 'Fixed damage +192',
