		skillName_th = 'ล็อกหิน',
		skillName_in = 'Kunci Batu',
		skillName_ph = 'Rock Lock',
		skillName_ma = 'Kunci Batu',
		skillName = 'Rock Lock',
		describe_vn = 'Groudon đập đất, sau đó dựng đá tấn công một mục tiêu, gây ra #C0xE69900#160% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$#C0xF 13B54#Sát Thương Vật Lý#C0x5B545B#, đòn tấn công này đi kèm với hiệu ứng xuyên thủng vết nứt mặt đất (thêm 40% sát thương cuối cùng của kỹ năng này gây ra cho kẻ địch mục tiêu đằng sau nó); nó tăng khả năng giảm sát thương của bản thân thêm 20%, kéo dài trong 2 lượt. \nThêm 50% độ mù cho đơn vị tấn công chính nó bằng kỹ năng kích hoạt tiếp theo, kéo dài trong 1 hiệp.',
		describe_en = 'Groudon slams the ground, then raises rocks to attack a target, dealing #C0xE69900#160% Physical Damage#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#. This attack comes with an effect that pierces cracks in the ground (adds 40% of the final damage of this skill to enemies behind the primary target); it increases self damage reduction by 20% for 2 turns. \n Adds 50% blindness to the attacking unit itself with the next activated skill, lasting 1 round.',
		describe_th = 'กรูดอนทุบพื้น จากนั้นยกหินขึ้นโจมตีเป้าหมาย ทำดาเมจ #C0xE69900#160% ความเสียหายทางกายภาพ#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# การโจมตีนี้มาพร้อมกับเอฟเฟกต์เจาะแตกแยกของพื้นดิน (เพิ่มความเสียหายสุดท้ายของสกิลนี้อีก 40% ให้กับศัตรูที่อยู่ด้านหลังเป้าหมาย); เพิ่มความสามารถลดความเสียหายของตนเองขึ้น 20% เป็นเวลา 2 เทิร์น \n เพิ่มตาบอด 50% แก่ยูนิตที่โจมตีตัวเองด้วยสกิลครั้งถัดไป เป็นเวลาหนึ่งรอบ',
		describe_in = 'Groudon menghantam tanah, kemudian mengangkat batu untuk menyerang target, memberikan #C0xE69900#160% Damage Fisik#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Damage Fisik#C0x5B545B#. Serangan ini disertai dengan efek menembus retakan tanah (menambahkan 40% damage akhir skill ini yang diberikan kepada musuh di belakang target utama); meningkatkan kemampuan pengurangan damage diri sendiri sebesar 20% selama 2 giliran. \n Menambahkan 50% kebutaan pada unit penyerang itu sendiri dengan skill aktif berikutnya, bertahan selama 1 giliran.',
		describe_ph = 'Binubugbog ni Groudon ang lupa, pagkatapos ay itinutayo ang bato upang atakihin ang isang target, nagdudulot ng #C0xE69900#160% Pisikal na Pinsala#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Kasama sa pag-atakeng ito ang epekto ng paglusob sa mga bitak ng lupa (nagdaragdag ng 40% ng panghuling pinsala ng kasanayan na ito sa mga kaaway sa likod ng pangunahing target); pinapataas nito ang sariling kakayahan sa pagbabawas ng pinsala ng 20%, tumatagal ng 2 na turn. \n Nagdaragdag ng 50% pagkabulag sa nag-aatake na yunit gamit ang susunod na aktibong kasanayan, tumatagal ng 1 round.',
		describe_ma = 'Groudon memukul tanah, kemudian mengangkat batu untuk menyerang sasaran, memberikan #C0xE69900#160% Kerosakan Fizikal#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Serangan ini disertai dengan efek menembusi retakan tanah (menambah 40% kerosakan akhir kemahiran ini yang diberikan kepada musuh di belakang sasaran utama); meningkatkan kemampuan pengurangan kerosakan diri sendiri sebanyak 20% selama 2 pusingan. \n Menambah 50% kebutaan kepada unit menyerang itu sendiri dengan kemahiran aktif seterusnya, bertahan selama 1 pusingan.',
		describe = 'Groudon slams the ground, then raises rocks to attack a target, dealing #C0xE69900#160% Physical Damage#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#. This attack comes with an effect that pierces cracks in the ground (adds 40% of the final damage of this skill to enemies behind the primary target); it increases self damage reduction by 20% for 2 turns. \n Adds 50% blindness to the attacking unit itself with the next activated skill, lasting 1 round.',
		simDesc_vn = 'Cố La Đô đập xuống mặt đất, sau đó nâng cao đá tấn công mục tiêu hàng dọc.',
		simDesc_en = 'Kola slammed the ground, then raised the stone to attack the vertical target line.',
		simDesc_th = 'โคลา กระแทกลงที่พื้น จากนั้นยกหินขึ้นโจมตีเป้าหมายในแนวตั้ง',
		simDesc_in = 'Kola memukul tanah, kemudian mengangkat batu untuk menyerang target vertikal.',
		simDesc_ph = 'Binangga ni Kola ang lupa, saka itinaas ang bato para atakihin ang patayong target.',
		simDesc_ma = 'Kola memukul tanah, kemudian mengangkat batu untuk menyerang sasaran menegak.',
		simDesc = 'Kola slammed the ground, then raised the stone to attack the vertical target line.',
		zawakeEffect = __data_t__zawakeEffect[19712],
		-- {79002}
		zawakeEffectDesc = 'Groudon slams the ground, then rises up to strike a single target with a rock, dealing #C0xE69900#160% Physical Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#. This attack includes the effect Pierce Earth Thunder (dealing an additional 40% of the final damage of this skill to the target behind); increases self damage reduction by 30% for 3 turns. Adds 50% blindness to the unit attacking self with the next active skill, lasting 1 turn.',
		zawakeEffectDesc_en = 'Groudon slams the ground, then rises up to strike a single target with a rock, dealing #C0xE69900#160% Physical Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#. This attack includes the effect Pierce Earth Thunder (dealing an additional 40% of the final damage of this skill to the target behind); increases self damage reduction by 30% for 3 turns. Adds 50% blindness to the unit attacking self with the next active skill, lasting 1 turn.',
		zawakeEffectDesc_th = 'กรูดอนตบพื้น จากนั้นพุ่งขึ้นเพื่อโจมตีเป้าหมายเดี่ยวด้วยหิน ทำให้เกิด #C0xE69900#160% การโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# การโจมตีนี้มาพร้อมกับผลเจาะทะลุสายฟ้าผ่า (ก่อให้เกิดความเสียหายเพิ่มเติม 40% ของความเสียหายสุดท้ายของทักษะนี้กับเป้าหมายด้านหลัง); เพิ่มการลดความเสียหายตนเอง 30% เป็นเวลา 3 เทิร์น เพิ่มความพร่ามัว 50% ให้แก่หน่วยที่โจมตีตนเองด้วยทักษะใช้งานถัดไป เป็นเวลา 1 เทิร์น',
		zawakeEffectDesc_in = 'Groudon memukul tanah, kemudian muncul untuk menyerang satu target dengan batu, memberikan #C0xE69900#160% Serangan Fisik#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#. Serangan ini disertai efek Menembus Petir Bumi (memberikan tambahan 40% kerusakan akhir dari skill ini ke target di belakang); meningkatkan pengurangan kerusakan diri sendiri sebesar 30% selama 3 giliran. Menambahkan 50% kebutaan pada unit yang menyerang diri sendiri dengan skill aktif berikutnya, berlangsung selama 1 giliran.',
		zawakeEffectDesc_ph = 'Pinapalo ni Groudon ang lupa, pagkatapos ay itinaas ang bato para atakihin ang isang target na nag-iisa, nagdudulot ng #C0xE69900#160% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Ang atakeng ito ay may kasamang epekto ng Pagbutas ng Lupa at Kidlat (nagbibigay ng karagdagang 40% ng panghuling pinsala ng kasanayang ito sa target sa likod); nagpapataas ng 30% pagbawas ng pinsala sa sarili, tumatagal ng 3 turn. Nagdaragdag ng 50% pagkabulag sa yunit na umatake sa sarili gamit ang susunod na aktibong kasanayan, tumatagal ng 1 turn.',
		zawakeEffectDesc_ma = 'Groudon menampar tanah, kemudian muncul untuk menyerang satu sasaran dengan batu, memberikan #C0xE69900#160% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Keragaman Fizikal#C0x5B545B#. Serangan ini disertai dengan kesan Menembusi Renjatan Bumi (menyebabkan tambahan 40% kerosakan akhir kemahiran ini kepada sasaran di belakang); meningkatkan pengurangan kerosakan diri sendiri sebanyak 30% selama 3 giliran. Menambah 50% kebutaan kepada unit yang menyerang diri sendiri dengan kemahiran aktif seterusnya, berlangsung selama 1 giliran.',
		zawakeEffectDesc_vn = 'Groudon vỗ mặt đất, sau đó làm trồi lên đá tấn công một mục tiêu đơn lẻ, gây #C0xE69900#160% Công Vật Lý#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, đòn tấn công này kèm theo hiệu ứng Xuyên Thấu Địa Liệt (gây thêm 40% sát thương cuối cùng của kỹ năng này lên mục tiêu phía sau); tăng 30% giảm sát thương cho bản thân, kéo dài 3 hiệp\nThêm 50% mù lòa cho đơn vị tấn công bản thân bằng kỹ năng chủ động tiếp theo, kéo dài 1 hiệp',
		zawakeSimpleType = 2,
