	[19713] = {
		id = 19713,
		skillName_vn = 'Kiếm vực thẳm',
		skillName_en = 'Abyssal Sword',
		skillName_th = 'ดาบลึกลงไปในหุบเหว',
		skillName_in = 'Pedang Jurang',
		skillName_ph = 'Tabak ng Kailaliman',
		skillName_ma = 'Pedang Gaung',
		skillName = 'Abyssal Sword',
		describe_vn = 'Groudon thức dậy sau giấc ngủ, rồi điều khiển những tảng đá trên núi đâm vào một mục tiêu địch, gây ra #C0xE69900#660% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, đòn tấn công này có tác dụng lan rộng vết nứt mặt đất (gây thêm 35% sát thương cuối cùng) sát thương của kỹ năng này lên các mục tiêu xung quanh); kích hoạt [Sức mạnh nguyên thủy] trong 2 hiệp (Sức mạnh nguyên thủy: hiệu ứng đặc biệt, ngay lập tức tăng khả năng giảm sát thương của bản thân lên 30% và giữ lại vĩnh viễn một nửa hiệu ứng sau vòng cuối cùng) và kích hoạt 1 [Hiệu ứng động đất] ngay sau chiêu thức đặc biệt.',
		describe_en = 'Groudon awakens from sleep, then controls the boulders on the mountain to strike an enemy target, dealing #C0xE69900#660% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B#. This attack causes cracks to spread across the ground (dealing an additional 35% final damage) to surrounding targets; activates [Primal Power] for 2 turns (Primal Power: special effect, instantly increases own damage reduction by 30% and permanently retains half of the effect after the last turn) and triggers 1 [Earthquake Effect] immediately after the special move.',
		describe_th = 'กรูดอนตื่นขึ้นหลังจากหลับ จากนั้นควบคุมหินก้อนใหญ่บนภูเขาให้พุ่งชนเป้าหมายศัตรู ทำให้เกิด #C0xE69900#660% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# การโจมตีนี้จะทำให้รอยแตกแผ่ขยายบนพื้น (สร้างความเสียหายขั้นสุดท้ายเพิ่มอีก 35%) กับเป้าหมายรอบข้าง; เปิดใช้ [พลังดั้งเดิม] เป็นเวลา 2 เทิร์น ([พลังดั้งเดิม]: เอฟเฟกต์พิเศษ เพิ่มการลดความเสียหายให้ตนเองทันที 30% และเก็บครึ่งหนึ่งของเอฟเฟกต์ไว้ถาวรหลังจากเทิร์นสุดท้าย) และเรียกใช้ 1 [เอฟเฟกต์แผ่นดินไหว] ทันทีหลังจากสกิลพิเศษ',
		describe_in = 'Groudon terbangun dari tidur, lalu mengendalikan batu-batu di gunung untuk menyerang satu target musuh, memberikan #C0xE69900#660% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#. Serangan ini menyebabkan retakan menyebar di tanah (menimbulkan tambahan 35% kerusakan akhir) ke target di sekitar; mengaktifkan [Kekuatan Purba] selama 2 giliran ([Kekuatan Purba]: efek khusus, langsung meningkatkan kemampuan pengurangan kerusakan sendiri sebesar 30% dan menyimpan setengah efek secara permanen setelah giliran terakhir) dan mengaktifkan 1 [Efek Gempa] segera setelah serangan khusus.',
		describe_ph = 'Groudon ay nagising mula sa pagkakatulog, pagkatapos pinakokontrol ang mga bato sa bundok para tumama sa isang target na kaaway, na nagdudulot ng #C0xE69900#660% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Ang atake na ito ay nagpapalaganap ng mga bitak sa lupa (nagdudulot ng dagdag na 35% panghuling pinsala) sa mga kalapit na target; nag-a-activate ng [Pangunahing Lakas] sa loob ng 2 na turno ([Pangunahing Lakas]: espesyal na epekto, agad na nagpapataas ng sariling pagbawas ng pinsala ng 30% at permanenteang pinananatili ang kalahati ng epekto pagkatapos ng huling turno) at nagpapagana ng 1 [Epekto ng Lindol] agad pagkatapos ng espesyal na galaw.',
		describe_ma = 'Groudon bangun daripada tidur, kemudian mengawal batu-batu di gunung untuk menikam sasaran musuh, menyebabkan #C0xE69900#660% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Serangan ini menyebabkan retakan meluas di tanah (menyebabkan tambahan 35% kerosakan akhir) kepada sasaran di sekeliling; mengaktifkan [Kekuatan Asal] selama 2 pusingan ([Kekuatan Asal]: kesan khas, segera meningkatkan kemampuan pengurangan kerosakan diri sendiri sebanyak 30% dan mengekalkan separuh kesan itu secara kekal selepas pusingan terakhir) dan mengaktifkan 1 [Kesan Gempa Bumi] serta-merta selepas serangan istimewa.',
		describe = 'Groudon awakens from sleep, then controls the boulders on the mountain to strike an enemy target, dealing #C0xE69900#660% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B#. This attack causes cracks to spread across the ground (dealing an additional 35% final damage) to surrounding targets; activates [Primal Power] for 2 turns (Primal Power: special effect, instantly increases own damage reduction by 30% and permanently retains half of the effect after the last turn) and triggers 1 [Earthquake Effect] immediately after the special move.',
		simDesc_vn = 'Cố La Đô từ giấc ngủ tỉnh dậy, sau đó điều khiển đá núi đâm vào mục tiêu đơn lẻ của kẻ thù; lần tấn công này kèm theo hiệu ứng nứt đất và kích hoạt hiệu ứng sức mạnh nguyên thủy.',
		simDesc_en = 'Kola woke up from sleep, then controlled a boulder to strike a single enemy target; this attack came with an earth-cracking effect and triggered the primal power effect.',
		simDesc_th = 'โคลา ตื่นขึ้นจากการหลับ จากนั้นควบคุมก้อนหินพุ่งชนเป้าหมายศัตรูเพียงหนึ่งเดียว การโจมตีครั้งนี้มาพร้อมกับเอฟเฟกต์แผ่นดินแตกร้าวและเปิดใช้งานเอฟเฟกต์พลังดั้งเดิม',
		simDesc_in = 'Kola terbangun dari tidur, lalu mengendalikan batu besar untuk menusuk satu target musuh; serangan ini disertai efek retakan tanah dan mengaktifkan efek kekuatan primal.',
		simDesc_ph = 'Nagising si Kola mula sa pagtulog, pagkatapos ay ginamit ang isang bato upang tumama sa isang kalabang target; ang pag-atakeng ito ay may kasamang epekto ng pagbasag ng lupa at nag-activate ng epekto ng primal na kapangyarihan.',
		simDesc_ma = 'Kola terjaga dari tidur, kemudian mengawal batu besar untuk menyerang sasaran musuh tunggal; serangan ini disertai dengan kesan retakan bumi dan mengaktifkan kesan kuasa primal.',
		simDesc = 'Kola woke up from sleep, then controlled a boulder to strike a single enemy target; this attack came with an earth-cracking effect and triggered the primal power effect.',
		starEffect = __data_t__starEffect[19713],
		-- {11}
		starEffectDesc_vn = '<Sức mạnh Nguyên thủy> hiệu quả tăng cường: Khi kích hoạt, tăng khả năng giảm sát thương của bản thân lên 40%; gây thêm sát thương chuẩn bằng 50% lượng máu đã mất của bản thân lên mục tiêu (mục tiêu chịu sát thương lan cũng sẽ chịu thêm sát thương theo tỷ lệ lan).',
		starEffectDesc = '<Primeval Power> Enhancement Effect: When activated, increases self damage reduction by 40%; deals additional true damage equal to 50% of own lost HP to the target (targets affected by damage spread will also take additional damage proportionally).',
		starEffectDesc_en = '<Primeval Power> Enhancement Effect: When activated, increases self damage reduction by 40%; deals additional true damage equal to 50% of own lost HP to the target (targets affected by damage spread will also take additional damage proportionally).',
		starEffectDesc_th = '<พลังโบราณ> ผลเสริม: เมื่อเปิดใช้งาน จะเพิ่มความสามารถในการลดความเสียหายของตนเองขึ้น 40%; สร้างความเสียหายจริงเพิ่มเติมเท่ากับ 50% ของพลังชีวิตที่สูญเสียไปของตนเองให้กับเป้าหมาย (เป้าหมายที่ได้รับความเสียหายแบบกระจายจะได้รับความเสียหายเพิ่มขึ้นตามสัดส่วนการกระจาย).',
		starEffectDesc_in = '<Kekuatan Purba> Efek Peningkatan: Saat diaktifkan, meningkatkan pengurangan damage diri sendiri sebesar 40%; memberikan damage murni tambahan sebesar 50% dari HP yang hilang pada target (target yang terkena damage menyebar juga akan menerima damage tambahan sesuai dengan rasio penyebaran).',
		starEffectDesc_ph = '<Lakas ng Sinaunang Panahon> Epekto ng Pagpapalakas: Kapag na-activate, tumataas ang sariling kakayahan na bawasan ang damage ng 40%; nagdudulot ng karagdagang totoong damage na katumbas ng 50% ng nawalang HP ng sarili sa target (ang mga target na tinamaan ng damage spread ay tatanggap din ng karagdagang damage ayon sa proporsyon ng spread).',
		starEffectDesc_ma = '<Kuasa Primitif> Kesan Peningkatan: Apabila diaktifkan, meningkatkan kemampuan pengurangan kerosakan diri sendiri sebanyak 40%; memberikan kerosakan sebenar tambahan bersamaan dengan 50% jumlah darah yang hilang kepada sasaran (sasaran yang menerima kerosakan berjangkit juga akan menerima kerosakan tambahan mengikut nisbah jangkitannya).',
		zawakeEffect = __data_t__zawakeEffect[19713],
		-- {79003}
		zawakeEffectDesc = 'Groudon awakens from a deep sleep, then controls mountain rocks to pierce a single enemy target, dealing #C0xE69900#660% Physical Attack#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B#. This attack is accompanied by an expanding earth paralysis effect (deals an additional 35% of the final damage of this skill to nearby targets); activates <Primal Power> for 3 turns (Primal Power: a special effect that immediately increases self damage reduction by 30%, after the duration ends permanently retains half of the effect), and immediately performs <Earthquake Effect> once after using the fatal skill; earthquake damage includes 20% true damage based on the HP lost by self.',
		zawakeEffectDesc_en = 'Groudon awakens from a deep sleep, then controls mountain rocks to pierce a single enemy target, dealing #C0xE69900#660% Physical Attack#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B#. This attack is accompanied by an expanding earth paralysis effect (deals an additional 35% of the final damage of this skill to nearby targets); activates <Primal Power> for 3 turns (Primal Power: a special effect that immediately increases self damage reduction by 30%, after the duration ends permanently retains half of the effect), and immediately performs <Earthquake Effect> once after using the fatal skill; earthquake damage includes 20% true damage based on the HP lost by self.',
		zawakeEffectDesc_th = 'กลองดอนตื่นจากการนอนหลับลึก จากนั้นควบคุมหินภูเขาแทงใส่เป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0xE69900#660% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# การโจมตีนี้มาพร้อมกับเอฟเฟกต์แผ่ขยายทำให้ติดพิษแผ่นดิน (สร้างความเสียหายเพิ่ม 35% ของความเสียหายสุดท้ายของสกิลนี้แก่เป้าหมายใกล้เคียง); เปิดใช้งาน <พลังดั้งเดิม> เป็นเวลา 3 เทิร์น (พลังดั้งเดิม: เอฟเฟกต์พิเศษ เพิ่มความต้านทานความเสียหายให้ตัวเองทันที 30% เมื่อสิ้นสุดระยะเวลาจะคงผลครึ่งหนึ่งไว้ถาวร), และใช้ <เอฟเฟกต์แผ่นดินไหว> ครั้งหนึ่งทันทีหลังใช้สกิลสังหาร; ความเสียหายแผ่นดินไหวครอบคลุมความเสียหายจริง 20% โดยขึ้นอยู่กับ HP ที่เสียไปของตัวเอง',
		zawakeEffectDesc_in = 'Groudon bangun dari tidur nyenyak, kemudian mengendalikan batu gunung untuk menusuk satu target musuh, memberikan #C0xE69900#660% Serangan Fisik#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#. Serangan ini disertai efek perluasan kelumpuhan tanah (memberikan tambahan 35% damage akhir skill ini ke target di sekitar); mengaktifkan <Kekuatan Primal> selama 3 giliran (Kekuatan Primal: efek khusus, langsung meningkatkan pengurangan damage diri sendiri sebesar 30%, setelah durasi berakhir mempertahankan setengah efek secara permanen), dan segera melakukan <Efek Gempa Bumi> satu kali setelah menggunakan skill kematian; kerusakan gempa bumi termasuk 20% true damage berdasarkan HP yang hilang dari diri sendiri.',
		zawakeEffectDesc_ph = 'Groudon ayusin mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mula mulamula demanda #C0xE69900#660% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Ang pag-atakeng ito ay may kasamang epektong pagpapalawak ng pagkahilo sa lupa (nagdagdag ng 35% ng huling pinsala ng kasanayan sa mga kalapit na target); pinapagana ang <Primal na Lakas> sa loob ng 3 turn (Primal na Lakas: espesyal na epektong agad na nagpapataas ng 30% pagbabawas ng pinsala para sa sarili, pagkatapos ng tagal ay permanenteng pinanatili ang kalahati ng epekto), at agad na nagsasagawa ng isang <Epekto ng Lindol> pagkatapos gamitin ang skill na fatal; ang pinsalang dulot ng lindol ay may kasamang 20% tunay na pinsala batay sa HP na nawala sa sarili.',
		zawakeEffectDesc_ma = 'Groudon bangun dari tidur nyenyak, kemudian mengawal batu gunung untuk menikam satu sasaran musuh, menyebabkan #C0xE69900#660% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Serangan ini disertai kesan meluas lumpuh tanah (menyebabkan tambahan 35% kerosakan akhir kemahiran ini ke sasaran di sekeliling); mengaktifkan <Kuasa Asal> selama 3 pusingan (Kuasa Asal: kesan khas, segera meningkatkan pengurangan kerosakan diri sendiri sebanyak 30%, selepas tamat tempoh mengekalkan separuh kesan secara kekal), dan segera melaksanakan <Kesan Gempa Bumi> sekali selepas menggunakan kemahiran maut; kerosakan gempa bumi termasuk 20% kerosakan sebenar berdasarkan HP yang hilang oleh diri sendiri.',
		zawakeEffectDesc_vn = 'Groudon thức tỉnh từ giấc ngủ sâu, sau đó điều khiển đá núi đâm vào mục tiêu đơn lẻ của địch, gây #C0xE69900#660% Công Vật Lý#C0x5B545B# + $(skillLevel*4*90)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, đòn tấn công này kèm theo hiệu ứng lan rộng địa liệt (gây thêm 35% sát thương cuối cùng của kỹ năng này lên các mục tiêu xung quanh); kích hoạt  <Sức Mạnh Nguyên Thủy> trong 3 lượt (Sức Mạnh Nguyên Thủy: hiệu ứng đặc biệt, lập tức tăng 30% giảm sát thương cho bản thân, sau khi kết thúc lượt duy trì sẽ giữ vĩnh viễn một nửa hiệu quả), ngay lập tức thi triển 1 lần  <Hiệu ứng Động Đất> sau khi dùng kỹ năng tất sát; sát thương động đất kèm theo 20% sát thương chuẩn dựa trên lượng máu đã mất của bản thân.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#The activation duration of <Primal Power> is extended to 3 rounds; the earthquake damage in the special move of <Primal Power> comes with true damage equal to 20% of the user\'s lost HP.',
		zawakeSimpleDesc_en = '#C0x5c9970#The activation duration of <Primal Power> is extended to 3 rounds; the earthquake damage in the special move of <Primal Power> comes with true damage equal to 20% of the user\'s lost HP.',
		zawakeSimpleDesc_th = '#C0x5c9970#ระยะเวลาการเปิดใช้งาน <พลังดึกดำบรรพ์> เพิ่มเป็น 3 รอบ; ความเสียหายจากแผ่นดินไหวของท่าไม้ตายจะมาพร้อมกับความเสียหายจริงเท่ากับ 20% ของ HP ที่สูญเสียไปของตัวเอง',
		zawakeSimpleDesc_in = '#C0x5c9970#Durasi aktivasi <Kekuatan Primal> diperpanjang menjadi 3 ronde; kerusakan gempa dari jurus spesial <Kekuatan Primal> disertai true damage sebesar 20% dari HP yang hilang milik pengguna.',
		zawakeSimpleDesc_ph = '#C0x5c9970#Ang tagal ng <Primal Power> ay pinahaba sa 3 rounds; ang damage ng lindol sa special skill ay may dagdag na true damage na katumbas ng 20% ng sariling nawawalang HP',
		zawakeSimpleDesc_ma = '#C0x5c9970#Tempoh pengaktifan <Kuasa Primal> dilanjutkan kepada 3 pusingan; kerosakan gempa dari kemahiran khas <Kuasa Primal> akan disertakan dengan kerosakan sebenar bersamaan 20% daripada HP yang hilang milik sendiri',
		zawakeSimpleDesc_vn = '#C0x5c9970# Thời gian kích hoạt <Sức mạnh nguyên thủy> được tăng lên 3 vòng; sát thương do động đất trong chiêu thức đặc biệt của <Sức mạnh nguyên thủy> đi kèm với sát thương thực sự bằng 20% ​​lượng HP đã mất của chính một người.',
		upLvDesc = 'Fixed damage +360',
