	[19716] = {
		id = 19716,
		skillName_vn = 'Ancient Bloodline',
		skillName_en = 'Ancient Bloodline',
		skillName_th = 'สายเลือดโบราณ',
		skillName_in = 'Garis Keturunan Kuno',
		skillName_ph = 'Sinaunang Linya ng Dugo',
		skillName_ma = 'Garis Darah Purba',
		skillName = 'Ancient Bloodline',
		describe_vn = 'Trước mỗi vòng đấu chính, Groudon điều khiển trái đất để kích hoạt [Hiệu ứng động đất]: ban đầu khiến Groudon #C0xE69900##C0x5c9970#$(12+skillLevel*0.12-0.12)$%#C0x5B545B# Sát Thương Vật Lý lên tất cả mục tiêu của kẻ thù. Sát thương thực sự của #C0x5B545B#; sau mỗi lần phát hành [Hiệu ứng động đất], hệ số sát thương do động đất tăng vĩnh viễn #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# và hệ số tối đa có thể tăng lên 150%',
		describe_en = 'Before each main round, Groudon controls the earth to trigger [Earthquake Effect]: initially causing Groudon to deal $(12+skillLevel*0.12-0.12)$% Physical Damage to all enemy targets. True damage of #; after each release of [Earthquake Effect], the earthquake damage multiplier permanently increases by $(10+skillLevel*0.1-0.1)$%, with a maximum increase of up to 150%.',
		describe_th = 'ก่อนแต่ละรอบหลัก Groudon ควบคุมพื้นดินเพื่อเปิดใช้งาน [เอฟเฟกต์แผ่นดินไหว]: เริ่มต้นทำให้ Groudon สร้างความเสียหายทางกายภาพ $(12+skillLevel*0.12-0.12)$% ไปยังเป้าหมายศัตรูทั้งหมด ความเสียหายจริงของ #; หลังจากแต่ละครั้งที่เปิดใช้งาน [เอฟเฟกต์แผ่นดินไหว] ค่าสัมประสิทธิ์ความเสียหายจากแผ่นดินไหวจะเพิ่มขึ้นถาวร $(10+skillLevel*0.1-0.1)$% โดยมีค่าสูงสุดที่เพิ่มได้ถึง 150%.',
		describe_in = 'Sebelum setiap ronde utama, Groudon mengendalikan bumi untuk mengaktifkan [Efek Gempa]: awalnya menyebabkan Groudon memberikan $(12+skillLevel*0.12-0.12)$% Kerusakan Fisik ke semua target musuh. Kerusakan sebenarnya #; setelah setiap penggunaan [Efek Gempa], faktor kerusakan gempa meningkat secara permanen sebesar $(10+skillLevel*0.1-0.1)$% dengan peningkatan maksimum hingga 150%.',
		describe_ph = 'Bago ang bawat pangunahing round, kinokontrol ni Groudon ang lupa upang i-activate ang [Earthquake Effect]: sa simula ay nagdudulot si Groudon ng $(12+skillLevel*0.12-0.12)$% Physical Damage sa lahat ng kalabang target. Tunay na pinsala ng #; pagkatapos ng bawat pag-activate ng [Earthquake Effect], permanenteng tumataas ang earthquake damage multiplier ng $(10+skillLevel*0.1-0.1)$% at maaari itong tumaas hanggang sa maximum na 150%.',
		describe_ma = 'Sebelum setiap pusingan utama, Groudon mengawal bumi untuk mengaktifkan [Kesan Gempa Bumi]: pada mulanya menyebabkan Groudon memberikan $(12+skillLevel*0.12-0.12)$% Kerosakan Fizikal kepada semua sasaran musuh. Kerosakan sebenar #; selepas setiap pengeluaran [Kesan Gempa Bumi], faktor kerosakan gempa bumi meningkat secara kekal sebanyak $(10+skillLevel*0.1-0.1)$% dan faktor maksimum boleh meningkat sehingga 150%.',
		describe = 'Before each main round, Groudon controls the earth to trigger [Earthquake Effect]: initially causing Groudon to deal $(12+skillLevel*0.12-0.12)$% Physical Damage to all enemy targets. True damage of #; after each release of [Earthquake Effect], the earthquake damage multiplier permanently increases by $(10+skillLevel*0.1-0.1)$%, with a maximum increase of up to 150%.',
		starEffect = __data_t__starEffect[19716],
		-- {8}
		starEffectDesc_vn = 'Tăng sát thương Địa Chấn: Sát thương chuẩn ban đầu gây ra cho toàn bộ mục tiêu địch tăng lên thành $(18+skillLevel*0.18-0.18)$% Vật công của Groudon, Địa Chấn kèm hiệu ứng mù: Ban đầu giảm 20% tỷ lệ chính xác của toàn bộ địch, mỗi lần tung Địa Chấn, hệ số mù của hai đơn vị địch ngẫu nhiên giảm 5%, giảm tối đa đến 10%.',
		starEffectDesc = 'Increase Seismic Damage: Initial base damage dealt to all enemy targets increases to $(18+skillLevel*0.18-0.18)$% of Groudon\'s Physical Attack. Seismic comes with a blind effect: Initially reduces all enemies\' accuracy by 20%. Each time Seismic is cast, the blind coefficient of two random enemy units decreases by 5%, up to a maximum reduction of 10%.',
		starEffectDesc_en = 'Increase Seismic Damage: Initial base damage dealt to all enemy targets increases to $(18+skillLevel*0.18-0.18)$% of Groudon\'s Physical Attack. Seismic comes with a blind effect: Initially reduces all enemies\' accuracy by 20%. Each time Seismic is cast, the blind coefficient of two random enemy units decreases by 5%, up to a maximum reduction of 10%.',
		starEffectDesc_th = 'เพิ่มความเสียหายแผ่นดินไหว: ความเสียหายพื้นฐานเริ่มต้นที่เกิดขึ้นกับเป้าหมายศัตรูทั้งหมดเพิ่มขึ้นเป็น $(18+skillLevel*0.18-0.18)$% ของพลังโจมตีทางกายภาพของ Groudon, แผ่นดินไหวมาพร้อมกับเอฟเฟกต์ตาบอด: ลดความแม่นยำของศัตรูทั้งหมดลง 20% ตั้งแต่ต้น, ทุกครั้งที่ใช้แผ่นดินไหว ค่าสัมประสิทธิ์การตาบอดของศัตรูสุ่ม 2 หน่วยจะลดลง 5% สูงสุดลดได้ถึง 10%',
		starEffectDesc_in = 'Tingkatkan Damage Gempa: Damage dasar awal yang diberikan ke semua target musuh meningkat menjadi $(18+skillLevel*0.18-0.18)$% dari Serangan Fisik Groudon. Gempa disertai efek buta: Awalnya mengurangi akurasi semua musuh sebesar 20%, setiap kali menggunakan Gempa, koefisien buta dari dua unit musuh acak berkurang 5%, berkurang maksimal hingga 10%.',
		starEffectDesc_ph = 'Taasan ang Seismic Damage: Ang base damage na ibinibigay sa lahat ng kalaban ay tumataas sa $(18+skillLevel*0.18-0.18)$% ng Physical Attack ni Groudon. Ang Seismic ay may kasamang blind effect: Simula pa lang ay nagpapababa ng 20% sa accuracy ng lahat ng kalaban, sa bawat paggamit ng Seismic, ang blind coefficient ng dalawang random na kalaban ay bumababa ng 5%, hanggang sa maximum na 10%.',
		starEffectDesc_ma = 'Tingkatkan Damage Gempa: Damage asas awal yang diberikan kepada semua sasaran musuh meningkat kepada $(18+skillLevel*0.18-0.18)$% Serangan Fizikal Groudon. Gempa disertakan dengan kesan buta: Pada mulanya mengurangkan ketepatan semua musuh sebanyak 20%, setiap kali menggunakan Gempa, pekali buta bagi dua unit musuh secara rawak berkurang 5%, berkurang maksimum sehingga 10%.',
		zawakeEffect = __data_t__zawakeEffect[19716],
		-- {79004, 1}
		zawakeEffectDesc = 'Increase Earthquake damage: Initial true damage dealt to all enemy targets increases to $(18+skillLevel*0.18-0.18)$% of Groudon\'s Physical Attack, Earthquake includes blind effect: Reduces the initial accuracy rate of all enemies by 20%, each time Earthquake is cast, the blind coefficient of two random enemy units decreases by 5%, up to a maximum reduction of 10%; Blinded units suffer an additional 10% accuracy reduction before attacking Groudon, targets are guaranteed to be blinded when first attacked by an active skill.',
		zawakeEffectDesc_en = 'Increase Earthquake damage: Initial true damage dealt to all enemy targets increases to $(18+skillLevel*0.18-0.18)$% of Groudon\'s Physical Attack, Earthquake includes blind effect: Reduces the initial accuracy rate of all enemies by 20%, each time Earthquake is cast, the blind coefficient of two random enemy units decreases by 5%, up to a maximum reduction of 10%; Blinded units suffer an additional 10% accuracy reduction before attacking Groudon, targets are guaranteed to be blinded when first attacked by an active skill.',
		zawakeEffectDesc_th = 'เพิ่มความเสียหาย แผ่นดินไหว: ความเสียหายมาตรฐานเริ่มต้นที่สร้างขึ้นกับศัตรูทั้งหมดเพิ่มขึ้นเป็น $(18+skillLevel*0.18-0.18)$% ของพลังโจมตีร่างกายของ Groudon, แผ่นดินไหวมาพร้อมกับเอฟเฟกต์ตาบอด: ลดอัตราความแม่นยำเริ่มต้นของศัตรูทั้งหมดลง 20%, ทุกครั้งที่ใช้แผ่นดินไหว ค่าสถานะตาบอดของศัตรูสองหน่วยที่สุ่มจะลดลง 5%, สูงสุดลดได้ 10%; หน่วยที่ถูกตาบอดจะถูกลดอัตราความแม่นยำอีก 10% ก่อนโจมตี Groudon, เป้าหมายแน่นอนว่าจะถูกตาบอดเมื่อถูกโจมตีครั้งแรกด้วยสกิลแอคทีฟ',
		zawakeEffectDesc_in = 'Tingkatkan kerusakan Gempa Bumi: Kerusakan dasar awal yang diberikan ke semua target musuh meningkat menjadi $(18+skillLevel*0.18-0.18)$% dari Serangan Fisik Groudon, Gempa Bumi disertai efek buta: Mengurangi tingkat akurasi awal semua musuh sebesar 20%, setiap kali menggunakan Gempa Bumi, koefisien buta dari dua unit musuh secara acak berkurang 5%, pengurangan maksimal hingga 10%; Unit yang terkena buta mendapatkan pengurangan akurasi tambahan sebesar 10% sebelum menyerang Groudon, target dijamin terkena buta saat pertama kali diserang oleh skill aktif.',
		zawakeEffectDesc_ph = 'Taasan ang pinsalang Dulot ng Lindol: Ang unang base na pinsalang dulot sa lahat ng kalabang target ay tataas sa $(18+skillLevel*0.18-0.18)$% ng Physical Attack ni Groudon, ang Lindol ay may kasamang blind effect: Binabawasan ang unang accuracy rate ng lahat ng kalaban ng 20%, sa bawat pag-cast ng Lindol, bumababa ang blind coefficient ng dalawang random na yunit ng kaaway ng 5%, hanggang sa maximum na 10% ang pagbawas; Ang mga yunit na may bulag ay nababawasan pa ng 10% ng accuracy bago umatake kay Groudon, siguradong mabubulag ang target kapag unang tinamaan ng aktibong skill.',
		zawakeEffectDesc_ma = 'Tingkatkan kerosakan Gempa Bumi: Kerosakan asas awal yang diberikan ke semua sasaran musuh meningkat kepada $(18+skillLevel*0.18-0.18)$% Serangan Fizikal Groudon, Gempa Bumi disertakan kesan buta: Mengurangkan kadar ketepatan awal semua musuh sebanyak 20%, setiap kali menggunakan Gempa Bumi, pekali buta dua unit musuh secara rawak berkurangan 5%, pengurangan maksimum sehingga 10%; Unit yang buta dikurangkan ketepatan tambahan sebanyak 10% sebelum menyerang Groudon, sasaran pasti akan buta apabila kali pertama diserang oleh kemahiran aktif.',
		zawakeEffectDesc_vn = 'Tăng sát thương Địa Chấn: Sát thương chuẩn ban đầu gây lên toàn bộ mục tiêu địch tăng lên thành $(18+skillLevel*0.18-0.18)$% Vật Công của Groudon, Địa Chấn kèm hiệu ứng mù: Giảm 20% tỉ lệ chính xác ban đầu của toàn bộ địch, mỗi lần tung Địa Chấn, hệ số mù của hai đơn vị địch ngẫu nhiên giảm 5%, giảm tối đa đến 10%; Đơn vị bị mù bị giảm thêm 10% tỉ lệ chính xác trước khi tấn công Groudon, mục tiêu chắc chắn bị mù khi bản thân lần đầu bị tấn công bởi kỹ năng chủ động.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Units afflicted with blindness will have 10% lower hit rate before attacking Groudon. Targets will be blinded when hit by active skills for the first time.',
		zawakeSimpleDesc_en = '#C0x5c9970#Units afflicted with blindness will have 10% lower hit rate before attacking Groudon. Targets will be blinded when hit by active skills for the first time.',
		zawakeSimpleDesc_th = '#C0x5c9970#หน่วยที่ตาบอดจะลดอัตราการโจมตีแม่นลง 10% ก่อนโจมตี Groudon โดยเป้าหมายจะติดสถานะตาบอดเมื่อถูกสกิลแอคทีฟโจมตีครั้งแรก',
		zawakeSimpleDesc_in = '#C0x5c9970#Unit yang terkena buta akan menurunkan akurasi sebesar 10% sebelum menyerang Groudon. Target akan menjadi buta saat terkena skill aktif untuk pertama kalinya.',
		zawakeSimpleDesc_ph = '#C0x5c9970#Ang mga unit na nabulag ay bababa ng 10% ang hit rate bago umatake kay Groudon. Ang target ay mabubulag kapag unang tinamaan ng isang active skill.',
		zawakeSimpleDesc_ma = '#C0x5c9970#Unit yang buta akan mengurangkan kadar serangan terkena sebanyak 10% sebelum menyerang Groudon. Sasaran akan menjadi buta apabila terkena kemahiran aktif buat pertama kali.',
		zawakeSimpleDesc_vn = '#C0x5c9970#Đơn vị bị mù sẽ giảm tỷ lệ trúng đòn thêm 10% trước khi tấn công Groudon. Mục tiêu sẽ bị mù khi bị tấn công bởi các kỹ năng chủ động lần đầu tiên.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {197161}
	},
	[19717] = {
		id = 19717,
