	[19721] = {
		id = 19721,
		skillName_vn = 'Đòn đánh đuôi sắt',
		skillName_en = 'Iron tail strike',
		skillName_th = 'โจมตีหางเหล็ก',
		skillName_in = 'Serangan ekor besi',
		skillName_ph = 'Iron tail strike',
		skillName_ma = 'Serangan ekor besi',
		skillName = 'Iron tail strike',
		describe_vn = 'Primal Groudon đánh và tát một mục tiêu địch bằng cái đuôi sắt chứa đầy magma của nó, gây ra #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel* 4*24)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, giúp kéo dài thời gian hồi chiêu của các kỹ năng nhỏ của mục tiêu trong hai lượt và tăng khả năng phòng thủ gấp đôi của bản thân lên thêm 300% trong 2 lượt\n#F20# \n#F40#Sau khi Molten Core được kích hoạt, sát thương và hiệu ứng sẽ ảnh hưởng đến tướng ở hàng sau của mục tiêu (thêm 80% sát thương cuối cùng của kỹ năng này sẽ gây ra cho mục tiêu phía sau mục tiêu chính)',
		describe_en = 'Primal Groudon strikes and slaps a single enemy with its magma-filled iron tail, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel* 4*24)$ #C0xF13B54# Physical Damage #C0x5B545B#, extends the cooldown of the target\'s minor skills by two turns, and increases its own double defense by an additional 300% for 2 turns\n#F20# \n#F40# After Molten Core is activated, damage and effects will also affect the rear-row enemy (an additional 80% of the skill\'s final damage will be dealt to the enemy behind the main target).',
		describe_th = 'Primal Groudon โจมตีและตบเป้าหมายศัตรูหนึ่งตัวด้วยหางเหล็กที่เต็มไปด้วยแมกมา สร้าง #C0xE69900#100% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel* 4*24)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B#, ช่วยยืดเวลาคูลดาวน์ของสกิลย่อยของเป้าหมายเป็นสองเท่าเป็นเวลา 2 เทิร์น และเพิ่มการป้องกันสองเท่าของตนเองขึ้นอีก 300% เป็นเวลา 2 เทิร์น\n#F20# \n#F40# หลังจากเปิดใช้งาน Molten Core ความเสียหายและผลจะส่งผลต่อศัตรูในแถวหลังของเป้าหมาย (เพิ่มความเสียหายสุดท้ายของสกิลนี้ 80% ไปยังเป้าหมายหลังเป้าหมายหลัก).',
		describe_in = 'Primal Groudon menyerang dan menampar satu target musuh dengan ekor besi yang penuh magma, memberikan #C0xE69900#100% Kerusakan Fisik#C0x5B545B#+$(skillLevel* 4*24)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#, memperpanjang waktu cooldown skill minor target selama dua giliran, dan meningkatkan pertahanan ganda dirinya sendiri sebesar 300% selama 2 giliran\n#F20# \n#F40# Setelah Molten Core diaktifkan, kerusakan dan efek juga akan memengaruhi unit di barisan belakang target (tambahan 80% dari kerusakan akhir skill ini akan diberikan ke target di belakang target utama).',
		describe_ph = 'Pinapalagan ni Primal Groudon ang isang target na kalaban gamit ang bakal nitong buntot na puno ng magma, na nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B#+$(skillLevel* 4*24)$ #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, tumutulong na pahabain ang cooldown ng maliliit na kasanayan ng target sa loob ng dalawang turno at pinapataas ang dobleng depensa ng sarili nito ng dagdag na 300% sa loob ng 2 turno \n#F20# \n#F40# Pagkatapos ma-activate ang Molten Core, ang pinsala at epekto ay apektado rin ang mga bayani sa likurang linya ng target (dagdag na 80% ng huling pinsala ng kasanayang ito ang gagawin sa target sa likod ng pangunahing target).',
		describe_ma = 'Primal Groudon menyerang dan menampar satu sasaran musuh dengan ekor besi yang penuh magma, memberikan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B#+$(skillLevel* 4*24)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, memanjangkan tempoh penyejukan kemahiran kecil sasaran selama dua pusingan dan meningkatkan pertahanan berganda dirinya sendiri sebanyak 300% selama 2 pusingan\n#F20# \n#F40# Selepas Molten Core diaktifkan, kerosakan dan kesan juga akan menjejaskan musuh di barisan belakang sasaran (tambahan 80% kerosakan akhir kemahiran ini akan diberikan kepada sasaran di belakang sasaran utama).',
		describe = 'Primal Groudon strikes and slaps a single enemy with its magma-filled iron tail, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel* 4*24)$ #C0xF13B54# Physical Damage #C0x5B545B#, extends the cooldown of the target\'s minor skills by two turns, and increases its own double defense by an additional 300% for 2 turns\n#F20# \n#F40# After Molten Core is activated, damage and effects will also affect the rear-row enemy (an additional 80% of the skill\'s final damage will be dealt to the enemy behind the main target).',
		zawakeSimpleDesc = 'Bonus effect: Increases own Physical Damage by 10%, lasts 2 turns  ',
		zawakeSimpleDesc_en = 'Bonus effect: Increases own Physical Damage by 10%, lasts 2 turns  ',
		zawakeSimpleDesc_th = 'เอฟเฟกต์เสริม: เพิ่มพลังโจมตีกายภาพของตัวเอง 10% เป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Efek tambahan: Meningkatkan Serangan Fisik diri sendiri sebesar 10%, berlangsung selama 2 giliran  ',
		zawakeSimpleDesc_ph = 'Karagdagang epekto: Dagdagan ng 10% ang Physical Attack ng sarili, tumatagal ng 2 turn  ',
