	[19722] = {
		id = 19722,
		skillName_vn = 'Phong Ấn Đại Địa',
		skillName_en = 'Great Land Seal',
		skillName_th = 'ผนึกแผ่นดินใหญ่',
		skillName_in = 'Segel Tanah Agung',
		skillName_ph = 'Dakilang Tatak ng Lupa',
		skillName_ma = 'Meterai Tanah Besar',
		skillName = 'Great Land Seal',
		describe_vn = 'Groudon ban đầu đập vào bề mặt magma, gây ra #C0xE69900#180% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ của #C0xF13B54#Sát Thương Vật Lý#C0x5 B545B#, đòn tấn công này có hiệu ứng xuyên thủng mặt đất (gây thêm 40% sát thương cuối cùng của kỹ năng này cho mục tiêu phía sau), tăng khả năng giảm sát thương của bản thân giảm 30%, kéo dài 2 đợt; và thêm thổ ấn cho kẻ địch trong 2 hiệp\n#F20# \n#F40##L10#Earth Seal: #L0#Đòn tấn công kép giảm 20%; kẻ thù bị phong ấn không thể nhìn rõ Groudon ban đầu và sẽ có 50% khả năng mất tích khi tấn công Groudon. Nếu không sử dụng kỹ năng phụ nào trong thời gian bị đánh dấu, chúng sẽ bị choáng một hiệp khi kết thúc đánh dấu\n#F20# \n#F40#Sau khi Molten Core được kích hoạt, sát thương xuyên thấu bằng 100% sát thương của kỹ năng này và một phong ấn đất được thêm vào cột mục tiêu trong 2 lượt.',
		describe_en = 'Groudon initially strikes the magma surface, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ of #C0xF13B54#Physical Damage#C0x5B545B#. This attack pierces the ground (dealing an additional 40% of the final skill damage to targets behind), increases self damage reduction by 30% for 2 turns; and adds Earth Seal to enemies for 2 turns: Earth Seal: Dual attacks deal 20% less damage; sealed enemies cannot clearly see Groudon initially and have a 50% chance to miss attacks on Groudon. If they do not use any secondary skills while marked, they will be stunned for 1 turn at the end of the mark. After Molten Core is activated, piercing damage is 100% of this skill\'s damage and an Earth Seal is added to the target column for 2 turns.',
		describe_th = 'กรูดอนเริ่มต้นโดยการทุบพื้นผิวแมกมา สร้างความเสียหายทางกายภาพ #C0xE69900#180%#C0x5B545B#+$(skillLevel*4*24)$ ของ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# การโจมตีนี้มีผลเจาะทะลุพื้นดิน (สร้างความเสียหายเพิ่ม 40% ของความเสียหายสุดท้ายของสกิลนี้กับเป้าหมายด้านหลัง) เพิ่มความสามารถลดความเสียหายของตัวเอง 30% เป็นเวลา 2 เทิร์น และเพิ่มตราดินให้ศัตรูเป็นเวลา 2 เทิร์น Earth Seal: การโจมตีคู่ลดความเสียหายลง 20%; ศัตรูที่ถูกตราจะไม่สามารถเห็นกรูดอนได้ชัดเจนในช่วงเริ่มต้นและมีโอกาส 50% ที่จะพลาดการโจมตีกรูดอน หากไม่ใช้สกิลเสริมใดๆ ในระหว่างที่ถูกทำเครื่องหมาย พวกเขาจะถูกสตัน 1 เทิร์นเมื่อสิ้นสุดการทำเครื่องหมาย หลังจากเปิดใช้งาน Molten Core ความเสียหายเจาะทะลุจะเป็น 100% ของความเสียหายสกิลนี้ และเพิ่มตราดินในคอลัมน์เป้าหมายเป็นเวลา 2 เทิร์น',
		describe_in = 'Groudon awalnya menghantam permukaan magma, menyebabkan #C0xE69900#180% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*24)$ dari #C0xF13B54#Kerusakan Fisik#C0x5B545B#. Serangan ini memiliki efek menembus tanah (menimbulkan tambahan 40% kerusakan akhir dari skill ini kepada target di belakang), meningkatkan pengurangan kerusakan diri sebesar 30% selama 2 giliran; dan menambahkan segel bumi pada musuh selama 2 giliran: Segel Bumi: Serangan ganda mengurangi kerusakan sebesar 20%; musuh yang tersegel tidak bisa melihat Groudon awal dengan jelas dan memiliki peluang 50% untuk gagal menyerang Groudon. Jika tidak menggunakan skill pendukung selama ditandai, mereka akan terkena stun selama 1 giliran setelah tanda berakhir. Setelah Molten Core diaktifkan, kerusakan tembus adalah 100% dari kerusakan skill ini dan segel bumi ditambahkan ke kolom target selama 2 giliran.',
		describe_ph = 'Unang tinamaan ni Groudon ang ibabaw ng magma, na nagdudulot ng #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ ng #C0xF13B54#Physical Damage#C0x5B545B#. Ang atake na ito ay may epekto na tumagos sa lupa (nagbibigay ng dagdag na 40% ng huling damage ng skill na ito sa mga target sa likod), nagpapataas ng sariling damage reduction ng 30% sa loob ng 2 turn; at nagdadagdag ng Earth Seal sa mga kalaban sa loob ng 2 turn: Earth Seal: Ang dobleng atake ay bumababa ng 20% sa damage; ang mga kalabang may seal ay hindi malinaw na nakikita si Groudon sa simula at may 50% pagkakataon na hindi tumama kay Groudon kapag umaatake. Kung hindi gagamit ng anumang sekundaryang skill habang naka-markahan, ma-stun sila sa loob ng 1 turn pagkatapos matapos ang markahan. Pagkatapos ma-activate ang Molten Core, ang piercing damage ay 100% ng damage ng skill na ito at nagdadagdag ng Earth Seal sa column ng target sa loob ng 2 turn.',
		describe_ma = 'Groudon pada mulanya memukul permukaan magma, menyebabkan #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ daripada #C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Serangan ini mempunyai kesan menembusi tanah (menyebabkan tambahan 40% kerosakan akhir kemahiran ini kepada sasaran di belakang), meningkatkan keupayaan pengurangan kerosakan diri sebanyak 30% selama 2 pusingan; dan menambah Segel Bumi pada musuh selama 2 pusingan: Segel Bumi: Serangan berganda mengurangkan 20% kerosakan; musuh yang tersegel tidak dapat melihat Groudon dengan jelas pada mulanya dan mempunyai 50% peluang untuk gagal menyerang Groudon. Jika tidak menggunakan kemahiran sampingan semasa ditanda, mereka akan terkena kejutan selama 1 pusingan apabila tanda tamat. Selepas Molten Core diaktifkan, kerosakan menembusi adalah 100% daripada kerosakan kemahiran ini dan satu segel bumi ditambah pada lajur sasaran selama 2 pusingan.',
		describe = 'Groudon initially strikes the magma surface, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ of #C0xF13B54#Physical Damage#C0x5B545B#. This attack pierces the ground (dealing an additional 40% of the final skill damage to targets behind), increases self damage reduction by 30% for 2 turns; and adds Earth Seal to enemies for 2 turns: Earth Seal: Dual attacks deal 20% less damage; sealed enemies cannot clearly see Groudon initially and have a 50% chance to miss attacks on Groudon. If they do not use any secondary skills while marked, they will be stunned for 1 turn at the end of the mark. After Molten Core is activated, piercing damage is 100% of this skill\'s damage and an Earth Seal is added to the target column for 2 turns.',
		simDesc_vn = 'Cố La Đô đập xuống mặt đất, sau đó nâng cao đá tấn công mục tiêu hàng dọc.',
		simDesc_en = 'Kola slammed the ground, then raised a rock to attack the vertical line of targets.',
		simDesc_th = 'โกลา ทำการทุบลงกับพื้น จากนั้นยกหินขึ้นโจมตีเป้าหมายแนวตั้ง',
		simDesc_in = 'Kola menghantam tanah, kemudian mengangkat batu untuk menyerang target secara vertikal.',
		simDesc_ph = 'Pinukpok ni Kola ang lupa sa lupa, pagkatapos ay itinaas ang bato para atakihin ang mga target sa pahabang linya.',
		simDesc_ma = 'Kola memukul tanah, kemudian mengangkat batu untuk menyerang sasaran secara menegak.',
		simDesc = 'Kola slammed the ground, then raised a rock to attack the vertical line of targets.',
		zawakeSimpleDesc = 'Improved effect: Damage reduction increased to 30% and lasts 3 turns',
