	[19723] = {
		id = 19723,
		skillName_vn = 'Kiếm vực thẳm',
		skillName_en = 'Abyssal Sword',
		skillName_th = 'ดาบแห่งเหวลึก',
		skillName_in = 'Pedang Jurang',
		skillName_ph = 'Palaso ng Kakwaban',
		skillName_ma = 'Pedang Jurang',
		skillName = 'Abyssal Sword',
		describe_vn = 'Primal Groudon thức tỉnh từ bề mặt magma, sau đó triệu hồi magma để gây #C0xE69900#700% Sát Thương Vật Lý lên một mục tiêu kẻ thù#C0x5B545B#+$(skillLevel*4*90)$#C0xF1 3B54#Sát Thương Vật Lý#C0x5B545B#, đòn tấn công này có hiệu ứng lan rộng vết nứt mặt đất (gây thêm 50% trận chung kết sát thương của kỹ năng này lên các mục tiêu xung quanh), và ngay lập tức được tung ra một lần #L10#Ending Land#L0#\n#F20# \n#F40# và chuyển sang trạng thái dung nham trong 2 lượt #L10#: #L0# Ngay lập tức tăng khả năng giảm sát thương của bản thân thêm 60% và vĩnh viễn giữ lại một nửa hiệu ứng sau lượt cuối cùng; khi nhận được kỹ năng hoạt động, sẽ thêm 2 lượt hiệu ứng đốt dung nham cho kẻ tấn công\n#F20# \n#F40#Sau khi Kích hoạt Lõi nóng chảy, #L10#Trạng thái dung nham #L0# có thể được kích hoạt bằng đòn tấn công kỹ năng chủ động #L10#Ending Land#L0# và trạng thái dung nham sẽ giữ lại tất cả hiệu ứng sau khi kết thúc vòng.',
		describe_en = 'Primal Groudon awakens from the magma surface, then summons magma to deal #C0xE69900#700% Physical Damage to a single enemy target#C0x5B545B#+$(skillLevel*4*90)$#C0xF1 3B54#Physical Damage#C0x5B545B#. This attack has a spreading ground crack effect (dealing an additional 50% final damage of this skill to surrounding targets), and immediately unleashes once #L10#Ending Land#L0#\n#F20# \n#F40# and enters magma state for 2 turns #L10#: #L0# Instantly increases self damage reduction by 60% and permanently retains half of the effect after the last turn; when receiving an active skill, adds 2 turns of magma burn effect to the attacker\n#F20# \n#F40#After activating the Melting Core, #L10#Magma State #L0# can be triggered by actively using the skill #L10#Ending Land#L0# and the magma state will retain all effects after the round ends.',
		describe_th = 'Primal Groudon ตื่นขึ้นจากผิวแมกมา จากนั้นเรียกแมกมาเพื่อสร้าง #C0xE69900#700% ความเสียหายทางกายภาพ ไปยังเป้าศัตรูหนึ่งตัว#C0x5B545B#+$(skillLevel*4*90)$#C0xF1 3B54#ความเสียหายทางกายภาพ#C0x5B545B# การโจมตีนี้มีผลแตกแยกพื้นดิน (สร้างความเสียหายเพิ่มเติม 50% ของความเสียหายสุดท้ายของสกิลนี้กับเป้าหมายรอบข้าง) และปล่อยออกมา 1 ครั้งทันที #L10#Ending Land#L0#\n#F20# \n#F40# จากนั้นเข้าสู่สถานะแมกมาเป็นเวลา 2 ตา #L10#: #L0# เพิ่มการลดความเสียหายของตัวเองทันที 60% และรักษาผลครึ่งหนึ่งอย่างถาวรหลังจากเทิร์นสุดท้าย; เมื่อได้รับสกิลคุณสมบัติจะเพิ่มเอฟเฟกต์ไฟแมกมาเผาไหม้อีก 2 ตาให้กับผู้โจมตี\n#F20# \n#F40#หลังจากเปิดใช้งานเมลติ้งคอร์ #L10#สถานะแมกมา #L0# สามารถเปิดใช้งานได้โดยการโจมตีด้วยสกิลหลัก #L10#Ending Land#L0# และสถานะแมกมาจะรักษาผลทั้งหมดหลังจบรอบ',
		describe_in = 'Primal Groudon terbangun dari permukaan magma, kemudian memanggil magma untuk memberikan #C0xE69900#700% Damage Fisik pada satu target musuh#C0x5B545B#+$(skillLevel*4*90)$#C0xF1 3B54#Damage Fisik#C0x5B545B#. Serangan ini memiliki efek retakan tanah yang menyebar (memberikan tambahan 50% damage final dari skill ini ke target di sekitar), dan langsung diluncurkan sekali #L10#Ending Land#L0#\n#F20# \n#F40# kemudian berubah menjadi status magma selama 2 giliran #L10#: #L0# Segera meningkatkan pengurangan damage diri sendiri sebesar 60% dan secara permanen mempertahankan setengah efek setelah giliran terakhir; saat menerima skill aktif, akan menambah efek terbakar magma selama 2 giliran pada penyerang\n#F20# \n#F40#Setelah mengaktifkan Melting Core, #L10#Status Magma #L0# dapat diaktifkan dengan serangan skill aktif #L10#Ending Land#L0# dan status magma akan mempertahankan semua efek setelah ronde berakhir.',
		describe_ph = 'Nagising si Primal Groudon mula sa ibabaw ng magma, pagkatapos ay tumawag ng magma upang magdulot ng #C0xE69900#700% Physical Damage sa isang target na kaaway#C0x5B545B#+$(skillLevel*4*90)$#C0xF1 3B54#Physical Damage#C0x5B545B#. Ang atakeng ito ay may epekto ng pagkalat ng bitak sa lupa (nagdudulot ng karagdagang 50% huling pinsala ng kakayahang ito sa mga kalapit na target), at agad na inilalabas ng isang beses ang #L10#Ending Land#L0#\n#F20# \n#F40# at papasok sa magma state nang 2 turn #L10#: #L0# Agad na pinapataas ang sariling kakayahan sa pagbawas ng pinsala ng 60% at permanenteng pinananatili ang kalahati ng epekto pagkatapos ng huling turn; kapag tumanggap ng isang aktibong kakayahan, magdadagdag ng 2 turn ng magma burn effect sa attacker\n#F20# \n#F40#Pagkatapos i-activate ang Melting Core, #L10#Magma State #L0# ay maaaring ma-trigger sa pamamagitan ng pag-atake gamit ang aktibong skill na #L10#Ending Land#L0# at ang magma state ay mananatili sa lahat ng epekto pagkatapos ng round.',
		describe_ma = 'Primal Groudon terjaga dari permukaan magma, kemudian memanggil magma untuk memberikan #C0xE69900#700% Kerosakan Fizikal pada satu sasaran musuh#C0x5B545B#+$(skillLevel*4*90)$#C0xF1 3B54#Kerosakan Fizikal#C0x5B545B#. Serangan ini mempunyai kesan rekahan tanah yang meluas (memberi tambahan 50% kerosakan akhir daripada kemahiran ini ke sasaran sekitar), dan serta-merta dilancarkan sekali #L10#Ending Land#L0#\n#F20# \n#F40# serta beralih ke keadaan magma selama 2 pusingan #L10#: #L0# Meningkatkan pengurangan kerosakan diri sendiri sebanyak 60% serta-merta dan kekal mengekalkan separuh kesan selepas pusingan terakhir; apabila menerima kemahiran aktif, akan menambah 2 pusingan kesan terbakar magma pada penyerang\n#F20# \n#F40#Selepas mengaktifkan Inti Cair, #L10#Keadaan Magma #L0# boleh diaktifkan dengan serangan kemahiran aktif #L10#Ending Land#L0# dan keadaan magma akan mengekalkan semua kesan selepas pusingan berakhir.',
		describe = 'Primal Groudon awakens from the magma surface, then summons magma to deal #C0xE69900#700% Physical Damage to a single enemy target#C0x5B545B#+$(skillLevel*4*90)$#C0xF1 3B54#Physical Damage#C0x5B545B#. This attack has a spreading ground crack effect (dealing an additional 50% final damage of this skill to surrounding targets), and immediately unleashes once #L10#Ending Land#L0#\n#F20# \n#F40# and enters magma state for 2 turns #L10#: #L0# Instantly increases self damage reduction by 60% and permanently retains half of the effect after the last turn; when receiving an active skill, adds 2 turns of magma burn effect to the attacker\n#F20# \n#F40#After activating the Melting Core, #L10#Magma State #L0# can be triggered by actively using the skill #L10#Ending Land#L0# and the magma state will retain all effects after the round ends.',
		simDesc_vn = 'Groudon ban đầu thức tỉnh từ bề mặt magma, sau đó triệu hồi magma để gây sát thương vật lý cho một mục tiêu kẻ thù. Cuộc tấn công này đi kèm với hiệu ứng của Vùng đất kết thúc. Sau khi Lõi nóng chảy được kích hoạt, trạng thái dung nham có thể được kích hoạt bằng các đòn tấn công kỹ năng chủ động và trạng thái dung nham sẽ giữ lại mọi hiệu ứng sau khi kết thúc vòng đấu.',
		simDesc_en = 'Groudon initially awakens from the magma surface, then summons magma to deal physical damage to an enemy target. This attack comes with the effect of the End Land Zone. After the Molten Core is activated, the molten state can be triggered by active skill attacks, and the molten state retains all effects after the round ends.',
		simDesc_th = 'กรูดอนตื่นจากพื้นผิวแมกมา จากนั้นเรียกแมกมาเพื่อสร้างความเสียหายทางกายภาพให้กับเป้าหมายศัตรู การโจมตีนี้มาพร้อมกับเอฟเฟกต์ของโซนดินแดนสิ้นสุด เมื่อแกนนำละลายถูกเปิดใช้งาน สถานะลาวาสามารถถูกกระตุ้นโดยการโจมตีทักษะเชิงรุก และสถานะลาวาจะคงผลทั้งหมดไว้หลังจากรอบสิ้นสุด',
		simDesc_in = 'Groudon awalnya bangkit dari permukaan magma, kemudian memanggil magma untuk memberikan kerusakan fisik pada target musuh. Serangan ini disertai dengan efek Zona Akhir Tanah. Setelah Inti Cair diaktifkan, status lelehan dapat diaktifkan oleh serangan keterampilan aktif, dan status lelehan akan mempertahankan semua efek setelah ronde berakhir.',
		simDesc_ph = 'Ang Groudon ay unang nagising mula sa ibabaw ng magma, pagkatapos ay tumatawag ng magma upang magdulot ng pisikal na pinsala sa isang target na kalaban. Ang pag-atakeng ito ay may kasamang epekto ng End Land Zone. Pagkatapos ma-activate ang Molten Core, maaaring ma-trigger ang molten state sa pamamagitan ng mga aktibong skill na atake at mapananatili ang lahat ng epekto ng molten state pagkatapos matapos ang round.',
		simDesc_ma = 'Groudon pada mulanya bangun dari permukaan magma, kemudian memanggil magma untuk menyebabkan kerosakan fizikal pada sasaran musuh. Serangan ini disertai dengan kesan Zon Tanah Tamat. Selepas Teras Cair diaktifkan, keadaan cairan boleh diaktifkan melalui serangan kemahiran aktif dan keadaan cairan akan mengekalkan semua kesan selepas pusingan berakhir.',
		simDesc = 'Groudon initially awakens from the magma surface, then summons magma to deal physical damage to an enemy target. This attack comes with the effect of the End Land Zone. After the Molten Core is activated, the molten state can be triggered by active skill attacks, and the molten state retains all effects after the round ends.',
		starEffect = __data_t__starEffect[19723],
		-- {11}
		starEffectDesc_vn = 'Gây sát thương chuẩn bằng 20% lượng máu đã mất của bản thân lên mục tiêu trong phạm vi, đồng thời kích nổ toàn bộ hiệu ứng thiêu đốt của địch; sau khi Khởi động Dung Nham Tâm, sát thương kích nổ thiêu đốt tăng 20%.',
		starEffectDesc = 'Deals true damage equal to 20% of the user\'s lost HP to targets within range, while detonating all burn effects on enemies; after activating Molten Core, burn detonation damage increases by 20%.',
		starEffectDesc_en = 'Deals true damage equal to 20% of the user\'s lost HP to targets within range, while detonating all burn effects on enemies; after activating Molten Core, burn detonation damage increases by 20%.',
		starEffectDesc_th = 'สร้างความเสียหายจริงเท่ากับ 20% ของพลังชีวิตที่สูญเสียไปของตนเองแก่เป้าหมายในระยะ และจุดระเบิดสถานะเผาไหม้ทั้งหมดของศัตรู; หลังจากเริ่มต้นแก่นลาวา ความเสียหายจากการจุดระเบิดเผาไหม้จะเพิ่มขึ้น 20%',
		starEffectDesc_in = 'Memberikan damage murni sebesar 20% dari HP yang hilang pada diri sendiri kepada target di dalam jangkauan, sekaligus meledakkan semua efek terbakar pada musuh; setelah Mengaktifkan Inti Cair, damage ledakan terbakar meningkat sebesar 20%.',
		starEffectDesc_ph = 'Nagdudulot ng tunay na pinsala na katumbas ng 20% ng nawalang HP ng sarili sa mga target sa saklaw, kasabay ng pagsabog ng lahat ng mga epekto ng pagkasunog sa mga kalaban; pagkatapos i-activate ang Molten Core, tumataas ng 20% ang pinsalang dulot ng pagsabog ng pagkasunog.',
		starEffectDesc_ma = 'Menyebabkan kerosakan sejati sama dengan 20% daripada kehilangan HP diri kepada sasaran dalam jarak, serta meletupkan semua kesan terbakar musuh; selepas Mengaktifkan Teras Lava, kerosakan letupan terbakar meningkat sebanyak 20%.',
		zawakeSimpleDesc = '<Primal Power> Improved effect: Upon activation, increases own damage reduction by 60% and earthquake damage in the ultimate skill includes true damage equal to 50% of own lost HP.  ',
		zawakeSimpleDesc_en = '<Primal Power> Improved effect: Upon activation, increases own damage reduction by 60% and earthquake damage in the ultimate skill includes true damage equal to 50% of own lost HP.  ',
		zawakeSimpleDesc_th = '<พลังดึกดำบรรพ์> เอฟเฟกต์ที่ปรับปรุง: เมื่อเปิดใช้งาน ลดความเสียหายเพิ่มขึ้น 60% และความเสียหายจากแผ่นดินไหวในท่าไม้ตายจะกลายเป็นความเสียหายจริง 50% ของ HP ที่สูญเสีย',
		zawakeSimpleDesc_in = '<Kekuatan Purba> Efek peningkatan: Saat diaktifkan, meningkatkan pengurangan damage sebesar 60% dan damage gempa pada skill ultimate menyertakan damage asli sebesar 50% dari HP yang hilang  ',
		zawakeSimpleDesc_ph = '<Primal Power> Pinahusay na epekto: Kapag na-activate, dagdag 60% damage reduction at ang earthquake damage ng ultimate ay may kasamang tunay na pinsala na katumbas ng 50% ng sariling nawawalang HP  ',
		zawakeSimpleDesc_ma = '<Kekuatan Purba> Kesan ditambah baik: Apabila diaktifkan, meningkatkan pengurangan kerosakan sebanyak 60% dan kerosakan gempa dalam skill ultimate akan termasuk kerosakan sebenar sebanyak 50% daripada HP yang hilang  ',
		zawakeSimpleDesc_vn = '<Sức mạnh nguyên thủy> Cải thiện hiệu ứng: Khi được kích hoạt, khả năng giảm sát thương của bản thân tăng lên 60% và sát thương động đất trong chiêu thức đặc biệt đi kèm với sát thương thực sự là 50% lượng HP đã mất của bản thân.',
		upLvDesc = 'Fixed damage +360',
		upLvDesc_en = 'Fixed damage +360',
