	[19726] = {
		id = 19726,
		skillName_vn = 'Vùng đất tận cùng',
		skillName_en = 'The Land of the End',
		skillName_th = 'ดินแดนแห่งจุดสิ้นสุด',
		skillName_in = 'Tanah Akhir',
		skillName_ph = 'Ang Lupain ng Wakas',
		skillName_ma = 'Tanah Kesudahan',
		skillName = 'The Land of the End',
		describe_vn = '#L10#Ending Land: #L0# Làm xáo trộn sức mạnh chấm dứt dưới lòng đất, gây #C0xE69900##C0x5c9970#$(20+skillL cho tất cả kẻ địch trước mỗi vòng evel*0.2-0.2)$%#C0x5B545B#Sát Thương Vật Lý#C0x5B545B# sát thương chuẩn; và thêm đốt dung nham trong 2 lượt (đốt dung nham: hiệu ứng tiêu cực, mục tiêu sẽ Mất 40% sát thương thực tế của đòn Sát Thương Vật Lý ban đầu của Groudon trước vòng đấu (không thể chồng lên); mỗi lần giải phóng động đất: hệ số sát thương do động đất tăng 15%, lên tới 150% và hệ số sát thương đốt dung nham tăng 10%, lên tới 100%; và đi kèm với hiệu ứng chói mắt: ban đầu giảm 20% tỷ lệ trúng đòn của tất cả kẻ thù, sau mỗi trận động đất được giải phóng, hệ số làm mù của hai đơn vị kẻ địch ngẫu nhiên giảm 5%, lên tới 10%\n#F20# \n#F40##L10#Lava Armor: #L0# Sau khi quay trở lại ban đầu, cơ thể được bao phủ bởi dung nham: miễn nhiễm với các điều khiển dịch chuyển như bị thổi bay và cuốn trôi. phòng thủ thêm 500% và giảm 100% trong mỗi hiệp lớn xuống tối thiểu 200%, đồng thời tăng mức giảm sát thương cuối cùng lên 20% khi đối mặt với các đòn tấn công bằng kỹ năng chủ động kiềm chế phi thuộc tính\n#F20# \n#F40##L10# Molten Core: #L0# Sát thương gây ra bởi Land of End và Molten Armor sẽ được Molten Core hấp thụ và lưu trữ. Khi Groudon ban đầu nhận sát thương chí mạng, 1 HP sẽ được giữ lại và #L10#lõi nóng chảy#L0# sẽ được kích hoạt. Khi bị thương, năng lượng tích trữ trong #L10#lõi nóng chảy#L0# sẽ bị tiêu hao trước tiên. Lượng năng lượng không thể phục hồi và bạn sẽ không bị sát thương quá mức khi cạn kiệt. Bạn cũng có thể nhận được lượng máu và sự tức giận tương tự bằng cách tiêu thụ năng lượng. #L10#lõi nóng chảy#L0#Lượng hấp thụ sát thương tối đa không vượt quá 2 lần lượng máu tối đa của Groudon ban đầu. Khi trạng thái lõi nóng chảy được kích hoạt, nó sẽ thêm #L10#phong ấn đất#L0# cho tất cả kẻ thù trong 2 lượt.',
		describe_en = 'Lỗi: Unexpected character encountered while parsing value: {. Path \'en\', line 2, position 9.',
		describe_th = 'Lỗi: Unexpected character encountered while parsing value: {. Path \'en\', line 2, position 9.',
		describe_in = 'Lỗi: Unexpected character encountered while parsing value: {. Path \'en\', line 2, position 9.',
		describe_ph = 'Lỗi: Unexpected character encountered while parsing value: {. Path \'en\', line 2, position 9.',
		describe_ma = 'Lỗi: Unexpected character encountered while parsing value: {. Path \'en\', line 2, position 9.',
		describe = 'Lỗi: Unexpected character encountered while parsing value: {. Path \'en\', line 2, position 9.',
		starEffect = __data_t__starEffect[19726],
		-- {8}
		starEffectDesc_vn = 'Khi Lõi Dung Nham khởi động, tự thêm trạng thái Dung Nham trong 2 lượt và vĩnh viễn 30% kháng bạo kích, đồng thời miễn nhiễm hiệu ứng giảm giới hạn máu, và sát thương của Vùng Đất Chết và Áo Giáp Dung Nham tăng thêm 30%.',
		starEffectDesc = 'When the #Lava Core# activates, it automatically adds the #Lava# status for 2 turns and permanently grants 30% critical resistance, while also being immune to HP limit reduction effects. Additionally, the damage from #Dead Land# and #Lava Armor# increases by 30%.',
		starEffectDesc_en = 'When the #Lava Core# activates, it automatically adds the #Lava# status for 2 turns and permanently grants 30% critical resistance, while also being immune to HP limit reduction effects. Additionally, the damage from #Dead Land# and #Lava Armor# increases by 30%.',
		starEffectDesc_th = 'เมื่อ #Lõi Dung Nham# ทำงาน จะเพิ่มสถานะ #Dung Nham# อัตโนมัติเป็นเวลา 2 เทิร์น และมีความต้านทานคริติคอล 30% ตลอดไป พร้อมทั้งป้องกันผลกระทบลดขีดจำกัดพลังชีวิต และความเสียหายจาก #Vùng Đất Chết# กับ #Áo Giáp Dung Nham# เพิ่มขึ้น 30%',
		starEffectDesc_in = 'Saat #Inti Lava# aktif, secara otomatis menambahkan status #Lava# selama 2 giliran dan permanen memberikan 30% resistensi kritikal, sekaligus kebal terhadap efek pengurangan batas HP. Selain itu, kerusakan dari #Dead Land# dan #Lava Armor# meningkat sebesar 30%.',
		starEffectDesc_ph = 'Kapag ang #Lava Core# ay nag-activate, awtomatikong idinadagdag ang estado ng #Lava# sa loob ng 2 turns at permanente nang nagbibigay ng 30% kritikal na resistensya, kasabay ng pagiging immune sa epekto ng pagbabawas ng limitasyon ng HP. Bukod pa rito, tumataas ng 30% ang pinsala mula sa #Dead Land# at #Lava Armor#.',
		starEffectDesc_ma = 'Apabila #Teras Lava# diaktifkan, ia secara automatik menambah status #Lava# selama 2 pusingan dan secara kekal memberikan ketahanan kritikal sebanyak 30%, serta kebal terhadap kesan pengurangan had HP. Selain itu, kerosakan daripada #Dead Land# dan #Lava Armor# meningkat sebanyak 30%.',
		zawakeSimpleDesc = 'Bonus effect: Before a blinded unit attacks Groudon, their hit rate is further reduced by 10%. Targets will be blinded when hit by an active skill for the first time.  ',
		zawakeSimpleDesc_en = 'Bonus effect: Before a blinded unit attacks Groudon, their hit rate is further reduced by 10%. Targets will be blinded when hit by an active skill for the first time.  ',
		zawakeSimpleDesc_th = 'เอฟเฟกต์เสริม: ก่อนที่หน่วยที่ตาบอดจะโจมตี Groudon อัตราโดนโจมตีจะลดลงอีก 10% เป้าหมายจะตาบอดเมื่อถูกโจมตีด้วยสกิลแอคทีฟครั้งแรก',
		zawakeSimpleDesc_in = 'Efek tambahan: Sebelum unit yang buta menyerang Groudon, akurasi serangannya berkurang 10% lagi. Target akan menjadi buta saat pertama kali terkena skill aktif  ',
		zawakeSimpleDesc_ph = 'Karagdagang epekto: Bago umatake si Groudon ang isang bulag na yunit, bababa pa ng 10% ang kanilang hit rate. Ang target ay mabubulag kapag unang tinamaan ng isang active skill  ',
		zawakeSimpleDesc_ma = 'Kesan tambahan: Sebelum unit yang buta menyerang Groudon, kadar kena serang dikurangkan sebanyak 10% lagi. Sasaran akan menjadi buta apabila terkena skill aktif buat kali pertama  ',
		zawakeSimpleDesc_vn = 'Hiệu ứng bổ sung: Trước khi đơn vị bị mù tấn công Groudon, tỷ lệ trúng đòn sẽ giảm thêm 10%. Mục tiêu sẽ bị mù khi bị tấn công bởi một kỹ năng chủ động lần đầu tiên.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
