	[19732] = {
		id = 19732,
		skillName_vn = 'Đại Địa Phong Ấn',
		skillName_en = 'Great Earth Seal',
		skillName_th = 'ตราพิฆาตแผ่นดินใหญ่',
		skillName_in = 'Segel Bumi Besar',
		skillName_ph = 'Dakilang Selyo ng Lupa',
		skillName_ma = 'Meterai Bumi Agung',
		skillName = 'Great Earth Seal',
		describe_vn = '#C0xC0C0C0# Dung nham này cháy bỏng đối với tôi! #C0x5B545B#\n#F10#\n#F40#Gula ban đầu phun một quả bom siêu hạt nhân về phía trước, gây ra #C0xE69900#180% đòn Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4 *24)$ của #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#. Đòn tấn công này đi kèm với hiệu ứng xuyên qua vết nứt trên mặt đất (thêm 40% sát thương cuối cùng của kỹ năng này gây ra cho mục tiêu đằng sau nó), tăng khả năng giảm sát thương của bản thân thêm 30%. Tiếp tục trong 2 vòng; và thêm Thổ ấn vào kẻ địch trong 2 lượt\n#F20#\n#F40##L10#Earth Seal: #L0# Đòn tấn công kép giảm 20%; kẻ thù bị phong ấn không thể nhìn rõ Groudon ban đầu và có 50% cơ hội hạ cánh khi tấn công Groudon. Nếu bạn chưa sử dụng bất kỳ kỹ năng phụ nào khi bị đánh dấu, bạn sẽ bị choáng một hiệp khi kết thúc đánh dấu\n#F20#\n#F40#Sau khi Molten Core được kích hoạt, sát thương xuyên thấu sẽ bằng 100% sát thương của kỹ năng này và một phong ấn đất sẽ được thêm vào cột mục tiêu trong 2 lượt.',
		describe_en = 'This molten lava burns fiercely within me! Initially, Gula launches a super nuclear bomb forward, dealing 180% Physical Damage plus $(skillLevel*4 *24)$ of Physical Damage. This attack comes with a special effect that pierces through cracks in the ground (adding 40% of the final damage from this skill to targets behind), and increases self damage reduction by 30% for 2 turns; additionally, it adds the Earth Seal to enemies for 2 turns. Earth Seal: Dual attacks deal 20% less damage; sealed enemies cannot clearly see the original Groudon and have a 50% chance to miss when attacking Groudon. If you haven\'t used any secondary skills when marked, you will be stunned for one turn when the mark ends. After Molten Core is activated, piercing damage will equal 100% of this skill\'s damage, and an Earth Seal will be applied to the target\'s column for 2 turns.',
		describe_th = 'ลาวานี้ลุกโชนร้อนแรงในตัวฉัน! กูลาเริ่มต้นด้วยการปล่อยระเบิดนิวเคลียร์ซูเปอร์ขนาดใหญ่ไปข้างหน้า สร้างความเสียหายกายภาพ 180% บวก $(skillLevel*4 *24)$ ของความเสียหายกายภาพ การโจมตีนี้มาพร้อมกับเอฟเฟกต์เจาะผ่านรอยแตกบนพื้น (เพิ่มความเสียหาย 40% ของความเสียหายสุดท้ายของสกิลนี้ต่อตัวเป้าหมายที่อยู่ด้านหลัง) และเพิ่มความสามารถลดความเสียหายให้ตัวเองขึ้นอีก 30% เป็นเวลา 2 เทิร์น; และเพิ่มตราดินให้ศัตรูเป็นเวลา 2 เทิร์น ตราย์ดิน: การโจมตีแบบคู่ลดความเสียหายลง 20%; ศัตรูที่ถูกตรานั้นมองไม่เห็นกรูดอนดั้งเดิมอย่างชัดเจน และมีโอกาส 50% ที่จะโจมตีกรูดอนไม่โดน หากคุณยังไม่ใช้ทักษะรองใดๆ ขณะที่ถูกตีตรา คุณจะถูกสะดุดเป็นเวลา 1 เทิร์นเมื่อจบการตีตรา หลังจากเปิดใช้งาน Molten Core ความเสียหายแบบเจาะทะลุจะเท่ากับ 100% ของความเสียหายจากสกิลนี้ และจะมีการเพิ่มตราดินในคอลัมน์เป้าหมายเป็นเวลา 2 เทิร์น',
		describe_in = 'Lava ini membara dalam diriku! Awalnya, Gula meluncurkan bom nuklir super ke depan, menyebabkan 180% Kerusakan Fisik ditambah $(skillLevel*4 *24)$ Kerusakan Fisik. Serangan ini disertai dengan efek menembus retakan di tanah (menambahkan 40% kerusakan akhir dari skill ini ke target di belakangnya), meningkatkan kemampuan pengurangan kerusakan diri sendiri sebesar 30% selama 2 giliran; dan menambahkan Segel Bumi ke musuh selama 2 giliran. Segel Bumi: Serangan ganda mengurangi kerusakan sebesar 20%; musuh yang tersegel tidak dapat melihat Groudon asli dengan jelas dan memiliki peluang 50% untuk gagal menyerang Groudon. Jika kamu belum menggunakan skill tambahan apapun saat diberi tanda, kamu akan terkena stun selama satu giliran saat tanda itu berakhir. Setelah Molten Core diaktifkan, kerusakan tembus akan menjadi 100% dari kerusakan skill ini dan segel bumi akan diterapkan pada kolom target selama 2 giliran.',
		describe_ph = 'Ang apoy na ito ay sumisiklab sa akin! Sa simula, si Gula ay naglunsad ng isang super nuclear bomb pasulong, na nagdudulot ng 180% Pisikal na Pinsala plus $(skillLevel*4 *24)$ Pisikal na Pinsala. Ang atakeng ito ay may kasamang epekto na tumatagos sa mga bitak sa lupa (nagdagdag ng 40% ng huling pinsala ng kasanayang ito sa mga target sa likod nito), at nagpapataas ng kakayahang bawasan ang sarili ng pinsala ng 30% sa loob ng 2 rounds; at nagdaragdag ng Earth Seal sa mga kalaban sa loob ng 2 rounds. Earth Seal: Ang dobleng atake ay bumababa ng 20% ang pinsala; ang mga kalaban na napektohan ng seal ay hindi malinaw na nakikita ang orihinal na Groudon at may 50% tsansa na palampasin kapag inaatake ang Groudon. Kung hindi ka pa nakagamit ng anumang karagdagang kasanayan habang minarkahan, matutulala ka sa isang round kapag natapos ang marka. Pagkatapos ma-activate ang Molten Core, ang tumatagos na pinsala ay magiging 100% ng pinsala ng kasanayang ito at isang Earth Seal ang idadagdag sa target na kolum sa loob ng 2 rounds.',
		describe_ma = 'Lava ini membara dalam diri saya! Pada mulanya, Gula melancarkan bom nuklear super ke hadapan, menyebabkan 180% Kerosakan Fizikal ditambah $(skillLevel*4 *24)$ Kerosakan Fizikal. Serangan ini disertai dengan kesan menembusi rekahan di tanah (menambah 40% kerosakan akhir daripada kemahiran ini kepada sasaran di belakangnya), meningkatkan keupayaan pengurangan kerosakan diri sendiri sebanyak 30% selama 2 pusingan; dan menambah Cap Bumi kepada musuh selama 2 pusingan. Cap Bumi: Serangan berganda mengurangkan kerosakan sebanyak 20%; musuh yang dicap tidak dapat melihat Groudon asal dengan jelas dan mempunyai 50% peluang untuk gagal menyerang Groudon. Jika anda belum menggunakan mana-mana kemahiran tambahan semasa ditandakan, anda akan terkena pening satu pusingan apabila tanda tamat. Selepas Molten Core diaktifkan, kerosakan tembus akan menjadi 100% kerosakan kemahiran ini dan cap bumi akan dikenakan pada lajur sasaran selama 2 pusingan.',
		describe = 'This molten lava burns fiercely within me! Initially, Gula launches a super nuclear bomb forward, dealing 180% Physical Damage plus $(skillLevel*4 *24)$ of Physical Damage. This attack comes with a special effect that pierces through cracks in the ground (adding 40% of the final damage from this skill to targets behind), and increases self damage reduction by 30% for 2 turns; additionally, it adds the Earth Seal to enemies for 2 turns. Earth Seal: Dual attacks deal 20% less damage; sealed enemies cannot clearly see the original Groudon and have a 50% chance to miss when attacking Groudon. If you haven\'t used any secondary skills when marked, you will be stunned for one turn when the mark ends. After Molten Core is activated, piercing damage will equal 100% of this skill\'s damage, and an Earth Seal will be applied to the target\'s column for 2 turns.',
		simDesc_vn = 'Cố La Đô đập xuống mặt đất, sau đó nâng cao đá tấn công mục tiêu hàng dọc.',
		simDesc_en = 'Co La Do slammed down to the ground, then raised the stone to attack the vertical row target.',
		simDesc_th = 'โค่ ลา โด้ กระแทกลงพื้น จากนั้นยกก้อนหินขึ้นโจมตีเป้าหมายแนวตั้ง',
		simDesc_in = 'Co La Do menghantam ke tanah, lalu mengangkat batu untuk menyerang target baris vertikal.',
		simDesc_ph = 'Pinukpok ni Co La Do ang lupa sa lupa, pagkatapos ay itinaas ang bato para atakihin ang target na hanay-pahalang.',
		simDesc_ma = 'Co La Do menghentak ke tanah, kemudian mengangkat batu untuk menyerang sasaran barisan menegak.',
		simDesc = 'Co La Do slammed down to the ground, then raised the stone to attack the vertical row target.',
