	[19736] = {
		id = 19736,
		skillName_vn = 'Vùng đất tận cùng',
		skillName_en = 'The Land of the End',
		skillName_th = 'ดินแดนแห่งจุดสิ้นสุด',
		skillName_in = 'Tanah Akhir',
		skillName_ph = 'Ang Lupain ng Wakas',
		skillName_ma = 'Tanah Kesudahan',
		skillName = 'The Land of the End',
		describe_vn = '#C0xC0C0C0# Nơi tôi ở là trái đất. #C0x5B545B#\n#F10#\n#F40##L10#Land of Ending: #L0# Làm xáo trộn sức mạnh tận thế dưới lòng đất, gây ra #C0xE69900##C0x5c997 cho toàn bộ kẻ địch trước mỗi hiệp đấu. 0#$(20+cấp kỹ năng*0,2-0,2)$%#C0x5B545B#Sát Thương Vật Lý#C0x5B545B# sát thương thực sự; và thêm dung nham đốt trong 2 lượt (đốt dung nham: hiệu ứng tiêu cực, nhắm mục tiêu mỗi Tổn thất 40% đòn Sát Thương Vật Lý của Groudon ban đầu (sát thương thực) trước vòng đấu, không thể chồng lên); mỗi lần giải phóng động đất: hệ số sát thương do động đất tăng 15%, tối đa 150%, hệ số sát thương đốt dung nham tăng 10%, tối đa 100%; và đi kèm với Hiệu ứng làm chói mắt: Ban đầu giảm 20% tỷ lệ trúng đích của tất cả kẻ thù. Sau mỗi trận động đất được giải phóng, hệ số làm mù của hai đơn vị kẻ địch ngẫu nhiên giảm 5%, tối đa 10%\n#F20#\n#F40##L10#Áo giáp dung nham: #L0#Sau khi trở về ban đầu Cơ thể được bao phủ bởi dung nham: miễn nhiễm với đóng băng; miễn nhiễm với các điều khiển dịch chuyển như bị thổi bay và cuốn trôi. Kẻ địch tấn công Groudon sẽ nhận 80% đòn Sát Thương Vật Lý của nó dưới dạng sát thương thuộc tính lửa; áo giáp dung nham tăng khả năng phòng thủ gấp đôi ban đầu lên 500% và giảm 100% trong mỗi hiệp. Thấp tới 200% và mức giảm sát thương cuối cùng tăng thêm 20% khi đối mặt với các đòn tấn công kỹ năng chủ động kiềm chế phi thuộc tính\n#F20#\n#F40##L10# Molten Core: #L0# Thiệt hại do Land of the End và Lava Armor gây ra sẽ được hấp thụ bởi Molten Core Storage. Khi Groudon ban đầu nhận sát thương chí mạng, anh ta giữ lại 1 điểm máu và kích hoạt #L10#lõi nóng chảy#L0#. Khi bị thương, năng lượng tích trữ trong #L10#lõi nóng chảy#L0# sẽ bị tiêu hao trước tiên. Năng lượng không thể phục hồi và sẽ không bị tổn hại quá mức khi cạn kiệt. Nó sẽ được tiêu thụ. Năng lượng cũng có thể được phục hồi sau lượng máu mất tương tự. #L10#lõi nóng chảy#L0#Sát thương hấp thụ tối đa không vượt quá 2 lần lượng máu tối đa của Groudon ban đầu. Khi trạng thái lõi nóng chảy được kích hoạt, nó sẽ thêm #L10#phong ấn đất#L0# cho tất cả kẻ thù trong 2 lượt.',
		describe_en = '#C0xC0C0C0# My home is Earth. #C0x5B545B#\n#F10#\n#F40##L10#Land of Ending: #L0#Disturbs apocalypse power underground, causing #C0xE69900##C0x5c997 to all enemies before each round. 0#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#Physical Damage#C0x5B545B# true damage; and adds burning magma for 2 turns (burning magma: negative effect, targets each time causing 40% of original Groudon’s Physical Damage (true damage) before the round, cannot stack); each time an earthquake is released: earthquake damage coefficient increases by 15%, max 150%, magma burn damage coefficient increases by 10%, max 100%; and accompanied by Blind effect: Initially reduces hit rate of all enemies by 20%. After each earthquake released, the blindness coefficient of two random enemy units reduces by 5%, max 10%. \n#F20#\n#F40##L10#Lava Armor: #L0#After reverting, the Body is covered with magma: immune to freezing; immune to displacement controls like being blown away and swept away. Enemies attacking Groudon will receive 80% of its Physical Damage as fire attribute damage; lava armor doubles original defense to 500% and reduces 100% each round, down to 200% minimum; and final damage reduction increases by 20% when facing active skill restraint non-elemental attacks. \n#F20#\n#F40##L10#Molten Core: #L0#Damage caused by Land of the End and Lava Armor will be absorbed by Molten Core Storage. When original Groudon receives critical damage, he retains 1 HP and activates #L10#molten core#L0#. When injured, energy stored in the #L10#molten core#L0# is consumed first. Energy cannot be recovered and will not be over-depleted when exhausted. It will be consumed. Energy can be restored after HP loss similarly. #L10#molten core#L0#Maximum damage absorption does not exceed 2 times the original Groudon’s max HP. When molten core state is activated, it adds #L10#Earth Seal#L0# to all enemies for 2 turns.',
		describe_th = '#C0xC0C0C0# ที่ที่ฉันอยู่คือโลก #C0x5B545B#\n#F10#\n#F40##L10#ดินแดนแห่งจุดจบ: #L0#ก่อความปั่นป่วนพลังวันสิ้นโลกใต้พื้นดิน สร้าง #C0xE69900##C0x5c997 แก่ศัตรูทั้งหมดก่อนทุกช่วงรอบ 0#$(20+ระดับสกิล*0.2-0.2)$%#C0x5B545B#ความเสียหายทางกายภาพ#C0x5B545B# ความเสียหายจริง; และเพิ่มการติดไฟลาวานาน 2 ตา (ติดไฟลาวา: ผลลบ, เป้าหมายจะเสีย 40% ของความเสียหายทางกายภาพดั้งเดิมของ Groudon (ความเสียหายจริง) ก่อนรอบ ไม่สามารถทับซ้อนได้); ทุกครั้งที่เกิดแผ่นดินไหว: ค่าสัมประสิทธิ์ความเสียหายแผ่นดินไหวเพิ่มขึ้น 15%, สูงสุด 150%, ค่าสัมประสิทธิ์ความเสียหายจากการติดไฟลาวาเพิ่มขึ้น 10%, สูงสุด 100%; พร้อมกับเอฟเฟกต์ตาพร่ามัว: ในตอนแรกลดอัตราการโดนโจมตีของศัตรูทั้งหมด 20% หลังจากแผ่นดินไหวแต่ละครั้ง จะลดค่าการทำให้ตาบอดของศัตรูสองหน่วยแบบสุ่ม 5%, สูงสุด 10% \n#F20#\n#F40##L10#ชุดเกราะลาวา: #L0#หลังจากกลับสู่สภาพเดิม ร่างกายถูกปกคลุมด้วยลาวา: ป้องกันการถูกแช่แข็ง; ป้องกันการถูกควบคุมการเคลื่อนที่ เช่น การถูกพัดหรือถูกพัดพา ศัตรูที่โจมตี Groudon จะได้รับความเสียหายทางไฟ 80% ของความเสียหายทางกายภาพของเขา; ชุดเกราะลาวาเพิ่มการป้องกันเป็นสองเท่าจากเดิมเป็น 500% และลดทีละ 100% ทุกรอบ ต่ำสุดถึง 200% และเพิ่มการลดความเสียหายสุดท้าย 20% เมื่อเผชิญกับการโจมตีทักษะที่จำกัดแบบไม่มีธาตุ \n#F20#\n#F40##L10#แก่นกลางหลอมเหลว: #L0#ความเสียหายจาก Land of the End และ Lava Armor จะถูกดูดซับโดยที่เก็บพลังงานแก่นกลางหลอมเหลว เมื่อ Groudon ดั้งเดิมได้รับความเสียหายคริติคอล เขาจะเหลือ HP 1 และเปิดใช้งาน #L10#แก่นกลางหลอมเหลว#L0# เมื่อบาดเจ็บ พลังงานที่เก็บใน #L10#แก่นกลางหลอมเหลว#L0# จะถูกใช้ก่อน พลังงานไม่สามารถฟื้นฟูได้และจะไม่ถูกทำลายเกินไปเมื่อตกต่ำ จะถูกใช้ไป พลังงานยังสามารถฟื้นฟูได้หลังจากการสูญเสีย HP ในลักษณะเดียวกัน #L10#แก่นกลางหลอมเหลว#L0# การดูดซับความเสียหายสูงสุดไม่เกินสองเท่าของ HP สูงสุดของ Groudon ดั้งเดิม เมื่อสถานะแก่นกลางหลอมเหลวเปิดใช้งาน จะเพิ่ม #L10#ผนึกดิน#L0# แก่ศัตรูทั้งหมดเป็นเวลา 2 ตา',
		describe_in = '#C0xC0C0C0# Tempat saya adalah bumi. #C0x5B545B#\n#F10#\n#F40##L10#Land of Ending: #L0# Mengacaukan kekuatan kiamat di bawah tanah, menyebabkan #C0xE69900##C0x5c997 ke semua musuh sebelum setiap giliran. 0#$(20+level skill*0.2-0.2)$%#C0x5B545B#Kerusakan Fisik#C0x5B545B# kerusakan sebenarnya; dan menambahkan terbakar lava selama 2 giliran (terbakar lava: efek negatif, sasaran setiap kali mengalami 40% dari Physical Damage asli Groudon (kerusakan nyata) sebelum giliran, tidak dapat ditumpuk); setiap kali gempa dilepaskan: koefisien kerusakan gempa meningkat 15%, maksimal 150%, koefisien kerusakan terbakar lava meningkat 10%, maksimal 100%; dan disertai efek Buta: Awalnya mengurangi peluang mengenai semua musuh sebesar 20%. Setelah setiap gempa dilepaskan, koefisien kebutaan dari dua unit musuh acak berkurang 5%, maksimal 10%. \n#F20#\n#F40##L10#Baju Zirah Lava: #L0#Setelah kembali ke kondisi awal Tubuh tertutup lava: kebal terhadap pembekuan; kebal terhadap kontrol perpindahan seperti tersapu dan terbang. Musuh yang menyerang Groudon akan menerima 80% dari Physical Damage-nya sebagai kerusakan atribut api; baju zirah lava meningkatkan pertahanan dua kali lipat dari awal menjadi 500% dan berkurang 100% setiap giliran, hingga minimum 200% dan pengurangan kerusakan akhir meningkat 20% saat menghadapi serangan skill aktif non-elemen. \n#F20#\n#F40##L10#Inti Cair: #L0#Kerusakan yang disebabkan oleh Land of the End dan Lava Armor akan diserap oleh Penyimpanan Inti Cair. Ketika Groudon asli menerima kerusakan kritis, dia mempertahankan 1 HP dan mengaktifkan #L10#inti cair#L0#. Ketika terluka, energi yang tersimpan dalam #L10#inti cair#L0# akan digunakan terlebih dahulu. Energi tidak dapat dipulihkan dan tidak akan terbuang berlebihan ketika habis. Energi akan dikonsumsi. Energi juga dapat dipulihkan setelah kehilangan HP serupa. #L10#inti cair#L0#Penyerapan kerusakan maksimum tidak melebihi 2 kali HP maksimum Groudon asli. Saat status inti cair diaktifkan, ini akan menambahkan #L10#penyegelan tanah#L0# ke semua musuh selama 2 giliran.',
		describe_ph = '#C0xC0C0C0# Ang aking tirahan ay ang mundo. #C0x5B545B#\n#F10#\n#F40##L10#Land of Ending: #L0# Naguugnay ng kapangyarihan ng katapusan sa ilalim ng lupa, nagdudulot ng #C0xE69900##C0x5c997 sa lahat ng kalaban bago bawat round. 0#$(20+antas ng kasanayan*0.2-0.2)$%#C0x5B545B#Pisikal na Pinsala#C0x5B545B# tunay na pinsala; at nagdaragdag ng nasusunog na lava sa loob ng 2 turns (nasusunog na lava: negatibong epekto, target bawat pagkakataon na mawawalan ng 40% ng orihinal na Pisikal na Pinsala ni Groudon (tunay na pinsala) bago ang round, hindi pwedeng ma-stack); bawat paglabas ng lindol: tumataas ang damage coefficient ng lindol ng 15%, max 150%, damage coefficient ng nasusunog na lava tumataas ng 10%, max 100%; at kalakip ang epekto ng Pagkabulag: Una nitong binabawasan ang hit rate ng lahat ng kalaban ng 20%. Pagkatapos ng bawat lindol, ang coefficient ng pagkabulag ng dalawang random na kalaban ay bumaba ng 5%, max 10%. \n#F20#\n#F40##L10#Baluti ng Lava: #L0# Pagkatapos bumalik sa orihinal na anyo, ang katawan ay nababalutan ng lava: immune sa freezing; immune sa displacement controls gaya ng itinataboy o dinadala. Ang mga kalabang umatake kay Groudon ay makatatanggap ng 80% ng Pisikal na Pinsala nito bilang damage na may apoy; pinapataas ng baluti ng lava ang depensa ng dalawang beses ng orihinal hanggang 500% at nababawasan ng 100% bawat round, hanggang sa 200% minimum at nadadagdagan ang huling pagbawas ng pinsala ng 20% kapag hinaharap ang mga aktibong skill na attack na walang elemento. \n#F20#\n#F40##L10#Molten Core: #L0# Ang pinsala na dulot ng Land of the End at Lava Armor ay maaabsorb ng imbakan ng Molten Core. Kapag ang orihinal na Groudon ay nakatanggap ng kritikal na pinsala, siya ay pinananatili sa 1 HP at nag-activate ng #L10#molten core#L0#. Kapag nasugatan, ang enerhiya na nakaimbak sa #L10#molten core#L0# ay unang gagamitin. Ang enerhiya ay hindi mababawi at hindi mawawala nang sobra kapag nauubos. Magagamit ito. Ang enerhiya ay maaari ring maibalik pagkatapos ng katulad na pagkawala ng HP. #L10#molten core#L0# Ang maximum na absorption ng pinsala ay hindi hihigit sa 2 beses ng maximum HP ng orihinal na Groudon. Kapag na-activate ang estado ng molten core, ito ay magdadagdag ng #L10#earth seal#L0# sa lahat ng kalaban sa loob ng 2 turns.',
		describe_ma = '#C0xC0C0C0# Tempat saya adalah bumi. #C0x5B545B#\n#F10#\n#F40##L10#Land of Ending: #L0# Mengacaukan kuasa kiamat di bawah tanah, menyebabkan #C0xE69900##C0x5c997 kepada semua musuh sebelum setiap pusingan. 0#$(20+peringkat kemahiran*0.2-0.2)$%#C0x5B545B#Kerosakan Fizikal#C0x5B545B# kerosakan sebenar; dan menambahkan lava terbakar selama 2 pusingan (lava terbakar: kesan negatif, sasaran setiap kali mengalami 40% daripada Kerosakan Fizikal Groudon asal (kerosakan sebenar) sebelum pusingan, tidak boleh bertindih); setiap kali gempa bumi dilepaskan: pekali kerosakan gempa bumi meningkat 15%, maksimum 150%, pekali kerosakan lava terbakar meningkat 10%, maksimum 100%; dan diiringi dengan kesan Buta: Pada mulanya mengurangkan kadar mengenai semua musuh sebanyak 20%. Selepas setiap gempa bumi dilepaskan, pekali buta dua unit musuh rawak berkurang 5%, maksimum 10%. \n#F20#\n#F40##L10#Zirah Lava: #L0#Selepas kembali kepada asal Badan dilitupi lava: kebal daripada pembekuan; kebal terhadap kawalan pergerakan seperti terhempas dan dibawa arus. Musuh yang menyerang Groudon akan menerima 80% daripada Kerosakan Fizikalnya sebagai kerosakan atribut api; zirah lava menggandakan ketahanan asal kepada 500% dan mengurangkan 100% setiap pusingan, sehingga minimum 200% dan pengurangan kerosakan akhir meningkat 20% apabila berhadapan dengan serangan kemahiran aktif tanpa elemen. \n#F20#\n#F40##L10#Teras Peleburan: #L0#Kerosakan yang disebabkan oleh Land of the End dan Zirrah Lava akan diserap oleh Penyimpanan Teras Peleburan. Apabila Groudon asal menerima kerosakan kritikal, dia mengekalkan 1 HP dan mengaktifkan #L10#teras peleburan#L0#. Ketika cedera, tenaga yang disimpan dalam #L10#teras peleburan#L0# akan digunakan terlebih dahulu. Tenaga tidak boleh dipulihkan dan tidak akan habis terlampau apabila kehabisan. Ia akan digunakan. Tenaga juga boleh dipulihkan selepas kehilangan HP yang serupa. #L10#teras peleburan#L0#Penyerapan kerosakan maksimum tidak melebihi 2 kali HP maksimum Groudon asal. Apabila keadaan teras peleburan diaktifkan, ia akan menambah #L10#meterai tanah#L0# kepada semua musuh selama 2 pusingan.',
		describe = '#C0xC0C0C0# My home is Earth. #C0x5B545B#\n#F10#\n#F40##L10#Land of Ending: #L0#Disturbs apocalypse power underground, causing #C0xE69900##C0x5c997 to all enemies before each round. 0#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#Physical Damage#C0x5B545B# true damage; and adds burning magma for 2 turns (burning magma: negative effect, targets each time causing 40% of original Groudon’s Physical Damage (true damage) before the round, cannot stack); each time an earthquake is released: earthquake damage coefficient increases by 15%, max 150%, magma burn damage coefficient increases by 10%, max 100%; and accompanied by Blind effect: Initially reduces hit rate of all enemies by 20%. After each earthquake released, the blindness coefficient of two random enemy units reduces by 5%, max 10%. \n#F20#\n#F40##L10#Lava Armor: #L0#After reverting, the Body is covered with magma: immune to freezing; immune to displacement controls like being blown away and swept away. Enemies attacking Groudon will receive 80% of its Physical Damage as fire attribute damage; lava armor doubles original defense to 500% and reduces 100% each round, down to 200% minimum; and final damage reduction increases by 20% when facing active skill restraint non-elemental attacks. \n#F20#\n#F40##L10#Molten Core: #L0#Damage caused by Land of the End and Lava Armor will be absorbed by Molten Core Storage. When original Groudon receives critical damage, he retains 1 HP and activates #L10#molten core#L0#. When injured, energy stored in the #L10#molten core#L0# is consumed first. Energy cannot be recovered and will not be over-depleted when exhausted. It will be consumed. Energy can be restored after HP loss similarly. #L10#molten core#L0#Maximum damage absorption does not exceed 2 times the original Groudon’s max HP. When molten core state is activated, it adds #L10#Earth Seal#L0# to all enemies for 2 turns.',
		starEffect = __data_t__starEffect[19736],
		-- {8}
		starEffectDesc_vn = 'Khi kích hoạt Lõi Dung Nham, bản thân nhận hiệu ứng Dung Nham trong 2 lượt và vĩnh viễn tăng 30% kháng bạo, đồng thời miễn nhiễm hiệu ứng giảm giới hạn máu, và sát thương của Vùng Đất Chết Chóc và Áo Giáp Dung Nham tăng thêm 30%.',
		starEffectDesc = 'When #F1#Activating the Magma Core#L1#, you receive the Magma effect for 2 turns and permanently increase critical resistance by 30%. At the same time, you become immune to HP limit reduction effects, and the damage of #F2#Deadly Land#L2# and #F3#Magma Armor#L3# increases by 30%.',
		starEffectDesc_en = 'When #F1#Activating the Magma Core#L1#, you receive the Magma effect for 2 turns and permanently increase critical resistance by 30%. At the same time, you become immune to HP limit reduction effects, and the damage of #F2#Deadly Land#L2# and #F3#Magma Armor#L3# increases by 30%.',
		starEffectDesc_th = 'เมื่อ #F1#เปิดใช้งานแก่นแมกม่า#L1# จะได้รับเอฟเฟกต์แมกม่า 2 เทิร์น และเพิ่มความต้านทานคริติคอลขึ้น 30% ตลอดกาล พร้อมกับได้รับภูมิคุ้มกันต่อเอฟเฟกต์ลดขีดจำกัดพลังชีวิต และความเสียหายของ #F2#ดินแดนอันตราย#L2# และ #F3#ชุดเกราะแมกม่า#L3# เพิ่มขึ้นอีก 30%',
		starEffectDesc_in = 'Saat #F1#Mengaktifkan Inti Lava#L1#, kamu menerima efek Lava selama 2 giliran dan secara permanen meningkatkan ketahanan kritis sebesar 30%. Selain itu kebal terhadap efek pengurangan batas HP, dan kerusakan dari #F2#Tanah Maut#L2# serta #F3#Zirah Lava#L3# meningkat sebesar 30%.',
		starEffectDesc_ph = 'Kapag #F1#Inilunsad ang Lava Core#L1#, makakatanggap ka ng Lava effect sa loob ng 2 turn at permanente na tumataas ang 30% na resistensya sa kritikal. Kasabay nito, immune ka sa epekto ng pagbawas ng limitasyon ng HP, at tumataas ng 30% ang damage ng #F2#Deadly Land#L2# at #F3#Magma Armor#L3#.',
		starEffectDesc_ma = 'Apabila #F1#Mengaktifkan Teras Lava#L1#, akan menerima kesan Lava selama 2 pusingan dan kekal meningkatkan rintangan kritikal sebanyak 30%. Serentak akan kebal terhadap kesan pengurangan had HP, dan kerosakan daripada #F2#Tanah Maut#L2# serta #F3#Zirah Lava#L3# meningkat sebanyak 30%.',
		zawakeSimpleDesc = 'Bonus effect: Before a blinded unit attacks Groudon, their hit rate is further reduced by 10%. Targets will be blinded when hit by an active skill for the first time.  ',
		zawakeSimpleDesc_en = 'Bonus effect: Before a blinded unit attacks Groudon, their hit rate is further reduced by 10%. Targets will be blinded when hit by an active skill for the first time.  ',
		zawakeSimpleDesc_th = 'เอฟเฟกต์เสริม: ก่อนที่หน่วยที่ตาบอดจะโจมตี Groudon อัตราโดนโจมตีจะลดลงอีก 10% เป้าหมายจะตาบอดเมื่อถูกโจมตีด้วยสกิลแอคทีฟครั้งแรก',
		zawakeSimpleDesc_in = 'Efek tambahan: Sebelum unit yang buta menyerang Groudon, akurasi serangannya berkurang 10% lagi. Target akan menjadi buta saat pertama kali terkena skill aktif  ',
