	[19812] = {
		id = 19812,
		skillName_vn = 'Lốc xoáy',
		skillName_en = 'Tornado',
		skillName_th = 'พายุทอร์นาโด',
		skillName_in = 'Tornado',
		skillName_ph = 'Ipo-ipo',
		skillName_ma = 'Tornado',
		skillName = 'Tornado',
		describe_vn = 'Rayquaza bay lượn và triệu hồi một cơn lốc xoáy để tấn công một mục tiêu của kẻ thù, gây ra #C0xE69900#80% đòn Sát Thương Vật Lý#C0x5B545B#+#C0x3D8A99#80% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$ của #C0xF13B54# Sát Thương Phép Thuật. #C0x5B545B#, thổi mục tiêu lên trời 1 lượt (Thổi bay: hiệu ứng khống chế, không thể xua tan, không thể tấn công hoặc bị trúng đòn trong thời gian). Khi mục tiêu rơi trở lại mặt đất, có 70% khả năng bị đánh bất tỉnh và rơi vào trạng thái [choáng] 1 lượt (choáng: hiệu ứng khống chế, không thể hành động). Càng có nhiều mục tiêu xung quanh thì khả năng bị choáng càng cao, có thể tăng lên 100%.',
		describe_en = 'Rayquaza soars and summons a whirlwind to attack an enemy target, dealing #C0xE69900#80% Physical Damage#C0x5B545B# + #C0x3D8A99#80% Magical Damage#C0x5B545B# + $(skillLevel*4*48)$ of #C0xF13B54# Magical Damage. #C0x5B545B# It lifts the target into the air for 1 turn (Knock-up: crowd control effect, cannot be dispelled, cannot attack or be hit during this time). When the target falls back to the ground, there is a 70% chance to be stunned and enter the [stun] state for 1 turn (Stun: crowd control effect, unable to act). The more targets around, the higher the chance to be stunned, potentially up to 100%.',
		describe_th = 'เรย์เควซ่าบินวนและเรียกพายุหมุนโจมตีเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#80%#C0x5B545B# + #C0x3D8A99#80% ความเสียหายทางเวทมนตร์#C0x5B545B# + $(skillLevel*4*48)$ ของความเสียหายทางเวทมนตร์ #C0xF13B54#. #C0x5B545B# ทำให้เป้าหมายถูกพัดขึ้นฟ้าเป็นเวลา 1 เทิร์น (พัดขึ้น: เอฟเฟกต์ควบคุมฝูงชน ไม่สามารถลบออก ไม่สามารถโจมตีหรือถูกโจมตีได้ในช่วงเวลานี้) เมื่อเป้าหมายตกสู่พื้น จะมีโอกาส 70% ที่จะถูกสะดุดและเข้าสู่สถานะ [มึนงง] เป็นเวลา 1 เทิร์น (มึนงง: เอฟเฟกต์ควบคุมฝูงชน ไม่สามารถกระทำการใดๆ) ยิ่งมีเป้าหมายรอบข้างมาก โอกาสถูกสะดุดยิ่งสูง อาจเพิ่มขึ้นถึง 100%',
		describe_in = 'Rayquaza terbang dan memanggil pusaran angin untuk menyerang target musuh, memberikan #C0xE69900#80% Kerusakan Fisik#C0x5B545B# + #C0x3D8A99#80% Kerusakan Magis#C0x5B545B# + $(skillLevel*4*48)$ dari #C0xF13B54# Kerusakan Magis. #C0x5B545B# Meniup target ke udara selama 1 giliran (Terbang Terpental: efek kontrol kerumunan, tidak dapat dibersihkan, tidak dapat menyerang atau terkena serangan selama waktu ini). Saat target jatuh kembali ke tanah, ada 70% kemungkinan tertidur dan masuk ke status [pingsan] selama 1 giliran (pingsan: efek kontrol kerumunan, tidak dapat bertindak). Semakin banyak target di sekitar, semakin tinggi kemungkinan tertidur, bisa meningkat hingga 100%.',
		describe_ph = 'Lumilipad si Rayquaza at nagpapatawag ng isang whirlwind upang atakihin ang isang kalabang target, nagdudulot ng #C0xE69900#80% Physical Damage#C0x5B545B# + #C0x3D8A99#80% Magical Damage#C0x5B545B# + $(skillLevel*4*48)$ ng #C0xF13B54# Magical Damage. #C0x5B545B# Itinutulak ang target pataas sa himpapawid ng 1 turn (Knock-up: crowd control effect, hindi maaaring alisin, hindi maaaring umatake o tamaan habang oras na ito). Kapag bumagsak ang target pabalik sa lupa, may 70% na tsansa na ma-stun at mapasailalim sa estado ng [stun] ng 1 turn (Stun: crowd control effect, hindi makakilos). Kapag mas marami ang mga target sa paligid, mas mataas ang tsansa na ma-stun, maaaring umabot hanggang 100%.',
		describe_ma = 'Rayquaza terbang dan memanggil pusaran angin untuk menyerang sasaran musuh, menyebabkan #C0xE69900#80% Kerosakan Fizikal#C0x5B545B# + #C0x3D8A99#80% Kerosakan Magikal#C0x5B545B# + $(skillLevel*4*48)$ daripada #C0xF13B54# Kerosakan Magikal. #C0x5B545B# Ia meniup sasaran ke udara selama 1 pusingan (Teriup: kesan kawalan, tidak boleh dibuang, tidak boleh menyerang atau terkena serangan dalam masa ini). Apabila sasaran jatuh kembali ke tanah, terdapat 70% kemungkinan untuk pengsan dan memasuki keadaan [pengsan] selama 1 pusingan (pengsan: kesan kawalan, tidak dapat bertindak). Semakin ramai sasaran di sekeliling, semakin tinggi peluang untuk pengsan, boleh meningkat sehingga 100%.',
		describe = 'Rayquaza soars and summons a whirlwind to attack an enemy target, dealing #C0xE69900#80% Physical Damage#C0x5B545B# + #C0x3D8A99#80% Magical Damage#C0x5B545B# + $(skillLevel*4*48)$ of #C0xF13B54# Magical Damage. #C0x5B545B# It lifts the target into the air for 1 turn (Knock-up: crowd control effect, cannot be dispelled, cannot attack or be hit during this time). When the target falls back to the ground, there is a 70% chance to be stunned and enter the [stun] state for 1 turn (Stun: crowd control effect, unable to act). The more targets around, the higher the chance to be stunned, potentially up to 100%.',
		zawakeEffect = __data_t__zawakeEffect[19812],
		-- {79002}
		zawakeEffectDesc = 'Rayquaza soars and summons a whirlwind to attack an enemy target, dealing #C0xE69900#80% Physical Damage#C0x5B545B#+#C0x3D8A99#80% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Magic Damage#C0x5B545B#, blowing the target into the air for 1 turn (Knock-up: control effect, cannot be dispelled, cannot attack or be attacked during this time). When the target falls back to the ground, it will receive 10% increased damage to the target and surrounding units, lasting 2 turns, and has a 70% chance to be stunned and enter the <stun> state for 1 turn (Stun: control effect, cannot act). The more targets around, the higher the chance to be stunned, up to 100%.',
		zawakeEffectDesc_en = 'Rayquaza soars and summons a whirlwind to attack an enemy target, dealing #C0xE69900#80% Physical Damage#C0x5B545B#+#C0x3D8A99#80% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Magic Damage#C0x5B545B#, blowing the target into the air for 1 turn (Knock-up: control effect, cannot be dispelled, cannot attack or be attacked during this time). When the target falls back to the ground, it will receive 10% increased damage to the target and surrounding units, lasting 2 turns, and has a 70% chance to be stunned and enter the <stun> state for 1 turn (Stun: control effect, cannot act). The more targets around, the higher the chance to be stunned, up to 100%.',
		zawakeEffectDesc_th = 'Rayquaza โบยบินและเรียกพายุหมุนโจมตีเป้าหมายศัตรู ทำความเสียหาย #C0xE69900#80% ความเสียหายทางกายภาพ#C0x5B545B#+#C0x3D8A99#80% พลังโจมตีเวทย์#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#ความเสียหายเวทย์#C0x5B545B#, พัดเป้าหมายลอยขึ้นฟ้าเป็นเวลา 1 เทิร์น (พัดลอย: ผลควบคุม ไม่สามารถลบสถานะนี้ได้, ไม่สามารถโจมตีหรือตอบโต้ได้ในระหว่างนี้) เมื่อเป้าหมายตกกลับสู่พื้น จะได้รับความเสียหายเพิ่มขึ้น 10% ทั้งเป้าหมายและหน่วยรอบข้าง คงอยู่ 2 เทิร์น และมีโอกาส 70% ที่จะถูกทำให้มึนงงและเข้าสู่สถานะ <ง่วงงุน> เป็นเวลา 1 เทิร์น (มึนงง: ผลควบคุม ไม่สามารถกระทำการใดๆ) ยิ่งมีเป้าหมายรอบๆ มาก โอกาสถูกมึนงงก็ยิ่งสูงขึ้น สูงสุดถึง 100%.',
		zawakeEffectDesc_in = 'Rayquaza terbang dan memanggil pusaran angin untuk menyerang target musuh, memberikan #C0xE69900#80% Kerusakan Fisik#C0x5B545B#+#C0x3D8A99#80% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Kerusakan Sihir#C0x5B545B#, meniup target ke udara selama 1 giliran (Terpental: efek kontrol, tidak dapat dihapus, tidak dapat menyerang atau diserang selama waktu ini). Ketika target jatuh kembali ke tanah akan menerima 10% peningkatan kerusakan pada target dan unit di sekitarnya, bertahan selama 2 giliran dan memiliki 70% peluang untuk terkena efek pingsan dan masuk ke status <pingsan> selama 1 giliran (Pingsan: efek kontrol, tidak dapat bertindak). Semakin banyak target di sekitar, semakin tinggi peluang terkena pingsan, hingga 100%.',
		zawakeEffectDesc_ph = 'Si Rayquaza ay lumilipad at nagtatawag ng unos upang atakihin ang isang kaaway na target, nagdudulot ng #C0xE69900#80% Pinsala sa Pisikal#C0x5B545B#+#C0x3D8A99#80% Magic na Atake#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Pinsalang Magic#C0x5B545B#, na itinutulak ang target sa himpapawid sa loob ng 1 turn (Itinutulak: epektong kontrol, hindi maaaring tanggalin, hindi maaaring umatake o sugurin habang ito ay nakakabit). Kapag nahulog ang target pabalik sa lupa ay magkakaroon ng 10% dagdag na pinsala sa target at mga nakakapaligid na yunit, tumatagal ng 2 turn at may 70% chance na ma-stun at mapasok sa estado ng <stun> sa loob ng 1 turn (Stun: epektong kontrol, hindi makakakilos). Kapag marami ang mga target sa paligid, tumataas ang chance ng stun hanggang umabot ng 100%.',
		zawakeEffectDesc_ma = 'Rayquaza terbang tinggi dan memanggil pusaran angin untuk menyerang sasaran musuh, menyebabkan #C0xE69900#80% Kerosakan Fizikal#C0x5B545B#+#C0x3D8A99#80% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Kerosakan Magik#C0x5B545B#, meniup sasaran ke udara selama 1 pusingan (Terbang: kesan kawalan, tidak boleh dialih keluar, tidak boleh menyerang atau diserang sepanjang masa ini). Apabila sasaran jatuh kembali ke tanah, akan menerima tambahan 10% kerosakan kepada sasaran dan unit di sekeliling, bertahan selama 2 pusingan dan mempunyai peluang 70% untuk dipukul pengsan dan memasuki keadaan <pengsan> selama 1 pusingan (Pengsan: kesan kawalan, tak boleh bertindak). Semakin banyak sasaran di sekeliling, semakin tinggi peluang untuk pengsan, sehingga 100%.',
		zawakeEffectDesc_vn = 'Rayquaza bay lượn và triệu hồi một cơn lốc xoáy để tấn công một mục tiêu kẻ địch, gây ra #C0xE69900#80% Sát Thương Vật Lý#C0x5B545B#+#C0x3D8A99#80% tấn Công Phép thuật#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, Thổi bay mục tiêu lên trời trong 1 lượt (Thổi bay: hiệu ứng khống chế, không thể xua tan, không thể tấn công hoặc bị đánh trong thời gian này). Khi mục tiêu rơi trở lại mặt đất sẽ dễ bị 10% sát thương lên mục tiêu và các đơn vị xung quanh, tồn tại 2 lượt và có 70% khả năng bị đánh bất tỉnh và rơi vào trạng thái <choáng> 1 lượt (choáng: hiệu ứng khống chế, không thể hành động). Càng có nhiều mục tiêu xung quanh thì khả năng bị choáng càng cao, lên tới 100%.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#<Knock-Up> When the target lands, the target and nearby units take 10% more damage, lasts 2 turns  ',
		zawakeSimpleDesc_en = '#C0x5c9970#<Knock-Up> When the target lands, the target and nearby units take 10% more damage, lasts 2 turns  ',
		zawakeSimpleDesc_th = '#C0x5c9970#<ลอยขึ้น> เมื่อเป้าหมายตกลงพื้น เป้าหมายและหน่วยโดยรอบจะรับความเสียหายเพิ่มขึ้น 10% เป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = '#C0x5c9970#<Terlontar> Saat target jatuh ke tanah, target dan unit di sekitarnya menerima 10% lebih banyak damage selama 2 giliran  ',
		zawakeSimpleDesc_ph = '#C0x5c9970#<Tinatangay> Kapag bumagsak sa lupa ang target, siya at ang mga kalapit na yunit ay tatanggap ng 10% dagdag pinsala sa loob ng 2 turn  ',
		zawakeSimpleDesc_ma = '#C0x5c9970#<Tersingkir> Apabila sasaran jatuh ke tanah, sasaran dan unit berdekatan menerima 10% lebih banyak kerosakan selama 2 pusingan  ',
		zawakeSimpleDesc_vn = '#C0x5c9970#<Thổi Bay> Khi mục tiêu rơi xuống đất, mục tiêu và các đơn vị xung quanh mục tiêu dễ bị tổn thương thêm 10%, kéo dài 2 lượt',
