	[19813] = {
		id = 19813,
		skillName_vn = 'Điểm nhấn rồng',
		skillName_en = 'Dragon highlight',
		skillName_th = 'ไฮไลต์มังกร',
		skillName_in = 'Sorotan naga',
		skillName_ph = 'Dragon highlight',
		skillName_ma = 'Sorotan naga',
		skillName = 'Dragon highlight',
		describe_vn = 'Rayquaza bay lên mây, đưa mục tiêu của kẻ địch lên trời rồi giải phóng sức mạnh của bầu trời, gây ra #C0xE69900#180% đòn Sát Thương Vật Lý#C0x5B545B#+#C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$ (skillLevel*4*80)$\'s #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, Rayquaza làm trung gian tinh thần chiến đấu của mục tiêu, khiến mục tiêu [Seal Rage] trong 1 hiệp (Seal Rage: hiệu ứng tiêu cực, không thể xua tan và không thể phục hồi Rage trong thời gian này)',
		describe_en = 'Rayquaza soars into the clouds, lifting the enemy target into the sky and unleashing the power of the heavens, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+#C0x3D8A99#180% Magic Damage#C0x5B545B#+$ (skillLevel*4*80)$\'s #C0xF13B54# Magic Damage #C0x5B545B#. Rayquaza acts as the combat spirit intermediary of the target, causing the target to [Seal Rage] for 1 turn (Seal Rage: a negative effect that prevents clearing and recovering Rage during this time).',
		describe_th = 'เรย์เควซาบินขึ้นสู่เมฆ ยกเป้าหมายศัตรูขึ้นไปบนท้องฟ้าแล้วปลดปล่อยพลังแห่งฟ้า สร้างความเสียหายทางกายภาพ #C0xE69900#180%#C0x5B545B#+#C0x3D8A99#180% ความเสียหายเวทมนตร์#C0x5B545B#+$ (skillLevel*4*80)$\'s #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B#. เรย์เควซาทำหน้าที่เป็นสื่อกลางจิตวิญญาณการต่อสู้ของเป้าหมาย ทำให้เป้าหมาย [Seal Rage] เป็นเวลา 1 เทิร์น (Seal Rage: ผลลบ ไม่สามารถล้างหรือฟื้นฟู Rage ในช่วงเวลานี้)',
		describe_in = 'Rayquaza terbang ke awan, mengangkat target musuh ke langit kemudian melepaskan kekuatan langit, menyebabkan #C0xE69900#180% Damage Fisik#C0x5B545B#+#C0x3D8A99#180% Damage Sihir#C0x5B545B#+$ (skillLevel*4*80)$\'s #C0xF13B54# Damage Sihir #C0x5B545B#. Rayquaza menjadi perantara jiwa pertarungan target, membuat target [Seal Rage] selama 1 giliran (Seal Rage: efek negatif, tidak bisa dihapus dan tidak bisa memulihkan Rage selama waktu ini).',
		describe_ph = 'Ang Rayquaza ay lumilipad sa mga ulap, iniaangat ang target ng kaaway sa langit at nagpapakawala ng kapangyarihan ng kalangitan, nagdudulot ng #C0xE69900#180% Pisikal na Pinsala#C0x5B545B#+#C0x3D8A99#180% Mahiwagang Pinsala#C0x5B545B#+$ (skillLevel*4*80)$\'s #C0xF13B54# Mahiwagang Pinsala #C0x5B545B#. Ginagampanan ng Rayquaza bilang tagapamagitan ng espiritu ng labanan ng target, na nagdudulot sa target na [Seal Rage] sa loob ng 1 turn (Seal Rage: negatibong epekto, hindi maaaring alisin o mabawi ang Rage sa panahong ito).',
		describe_ma = 'Rayquaza terbang ke awan, membawa sasaran musuh ke langit dan melepaskan kuasa langit, menyebabkan #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#+#C0x3D8A99#180% Kerosakan Sihir#C0x5B545B#+$ (skillLevel*4*80)$\'s #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Rayquaza menjadi perantara roh pertarungan sasaran, menyebabkan sasaran [Seal Rage] selama 1 pusingan (Seal Rage: kesan negatif, tidak boleh dibersihkan dan tidak boleh memulihkan Rage dalam tempoh ini).',
		describe = 'Rayquaza soars into the clouds, lifting the enemy target into the sky and unleashing the power of the heavens, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+#C0x3D8A99#180% Magic Damage#C0x5B545B#+$ (skillLevel*4*80)$\'s #C0xF13B54# Magic Damage #C0x5B545B#. Rayquaza acts as the combat spirit intermediary of the target, causing the target to [Seal Rage] for 1 turn (Seal Rage: a negative effect that prevents clearing and recovering Rage during this time).',
		simDesc_vn = 'Liệt Không Tọa bay lên cao, đưa mục tiêu hàng dọc của kẻ thù lên không trung, sau đó phóng ra sức mạnh liệt không, khiến tức giận của mục tiêu bị khóa lại.',
		simDesc_en = 'Liệt Không Tọa rises high, lifting the enemy\'s vertical targets into the air, then unleashes the power of Liệt Không, locking the targets\' anger.',
		simDesc_th = 'Liệt Không Tọa บินขึ้นสูง ยกเป้าหมายในแนวดิ่งของศัตรูขึ้นกลางอากาศ จากนั้นปล่อยพลังของ Liệt Không ทำให้ความโกรธของเป้าหมายถูกล็อคไว้',
		simDesc_in = 'Liệt Không Tọa terbang tinggi, mengangkat target vertikal musuh ke udara, kemudian melepaskan kekuatan Liệt Không, mengunci kemarahan target.',
		simDesc_ph = 'Si Liệt Không Tọa ay tumataas nang mataas, dinadala ang mga patayong target ng kaaway sa himpapawid, pagkatapos ay inilalabas ang kapangyarihan ng Liệt Không, na nakakandado sa galit ng mga target.',
		simDesc_ma = 'Liệt Không Tọa terbang tinggi, mengangkat sasaran menegak musuh ke udara, kemudian melepaskan kuasa Liệt Không, mengunci kemarahan sasaran.',
		simDesc = 'Liệt Không Tọa rises high, lifting the enemy\'s vertical targets into the air, then unleashes the power of Liệt Không, locking the targets\' anger.',
		starEffect = __data_t__starEffect[19813],
		-- {11}
		starEffectDesc_vn = 'Thêm vào mục tiêu sát thương thực tế bằng tổng Sát Thương Vật Lý và phép thuật của bản thân là 30% (sát thương này có thể chí mạng và không bị ảnh hưởng bởi miễn dịch sát thương phép hoặc vật lý).',
		starEffectDesc = 'Add to the actual damage target by 30% of the sum of your own Physical and Magical Damage (this damage can critical hit and is not affected by magic or physical damage immunity).',
		starEffectDesc_en = 'Add to the actual damage target by 30% of the sum of your own Physical and Magical Damage (this damage can critical hit and is not affected by magic or physical damage immunity).',
		starEffectDesc_th = 'เพิ่มไปยังเป้าหมายที่ได้รับความเสียหายจริงโดย 30% ของผลรวมความเสียหายทางกายภาพและเวทมนตร์ของตัวเอง (ความเสียหายนี้สามารถคริติคอลและไม่ถูกผลกระทบจากการป้องกันความเสียหายเวทหรือกายภาพ).',
		starEffectDesc_in = 'Tambahkan ke target kerusakan nyata sebesar 30% dari total Kerusakan Fisik dan Magis Anda sendiri (kerusakan ini dapat terkena kritikal dan tidak terpengaruh oleh imun terhadap kerusakan magis atau fisik).',
		starEffectDesc_ph = 'Magdagdag sa aktwal na target ng pinsala ng 30% ng kabuuang Pisikal at Mahiwagang Pinsala ng sarili mo (ang pinsalang ito ay maaaring maging kritikal at hindi naapektuhan ng immune sa mahiwaga o pisikal na pinsala).',
		starEffectDesc_ma = 'Tambah kepada sasaran kerosakan sebenar sebanyak 30% daripada jumlah Kerosakan Fizikal dan Magikal anda sendiri (kerosakan ini boleh mendapat serangan kritikal dan tidak terjejas oleh imuniti kerosakan magikal atau fizikal).',
		zawakeEffect = __data_t__zawakeEffect[19813],
		-- {79003, 1}
		zawakeEffectDesc = 'Add real damage equal to 50% of own total attack power to the target (#this damage# can crit and ignore Magic Immunity and Physical Immunity); and this ultimate skill attack comes with 30% life steal',
		zawakeEffectDesc_en = 'Add real damage equal to 50% of own total attack power to the target (#this damage# can crit and ignore Magic Immunity and Physical Immunity); and this ultimate skill attack comes with 30% life steal',
		zawakeEffectDesc_th = 'เพิ่มความเสียหายจริงเท่ากับ 50% ของพลังโจมตีรวมของตนเองให้กับเป้าหมาย (#ความเสียหายนี้# สามารถคริติคอลและละเลยภูมิคุ้มกันเวทมนตร์และภูมิคุ้มกันทางกายภาพ); และสกิลอัลติเมทครั้งนี้มาพร้อมกับการดูดชีวิต 30%',
		zawakeEffectDesc_in = 'Tambahkan kerusakan nyata sebesar 50% dari total kekuatan serangan sendiri ke target (#kerusakan ini# dapat kritis dan mengabaikan Imunitas Magic dan Imunitas Fisik); dan keterampilan ultimate kali ini disertai dengan 30% lifesteal',
		zawakeEffectDesc_ph = 'Magdagdag ng totoong pinsala na katumbas ng 50% ng kabuuang lakas ng sariling atake sa target (#ang pinsalang ito# ay maaaring maging kritikal at madaig ang Magic Immunity at Physical Immunity); at ang ultimate skill na ito ay may kasamang 30% life steal',
		zawakeEffectDesc_ma = 'Tambah kerosakan sebenar sebanyak 50% daripada jumlah kuasa serangan sendiri kepada sasaran (#kerosakan ini# boleh kritikal dan mengabaikan Imuniti Sihir dan Imuniti Fizikal); dan kemahiran ulti kali ini disertai dengan 30% pengisapan darah',
		zawakeEffectDesc_vn = 'Thêm sát thương thực tế bằng 50% tổng công đôi của bản thân cho mục tiêu (sát thương này có thể bạo kích và bỏ qua miễn dịch Công Phép và miễn dịch Công Vật Lý); và kỹ năng tuyệt chiêu lần này kèm theo 30% hút máu',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#11-star effect: Deals additional true damage equal to 50% of total Double Attack to the target (this damage can crit and ignores Magic/Physical immunity); this ultimate includes 15% lifesteal',
		zawakeSimpleDesc_en = '#C0x5c9970#11-star effect: Deals additional true damage equal to 50% of total Double Attack to the target (this damage can crit and ignores Magic/Physical immunity); this ultimate includes 15% lifesteal',
		zawakeSimpleDesc_th = '#C0x5c9970#เอฟเฟกต์ 11 ดาว: สร้างความเสียหายจริงเพิ่มอีก 50% ของพลังโจมตีสองครั้งทั้งหมด (ความเสียหายนี้สามารถคริติคอลและละเว้นการต้านเวท/กายภาพ); สกิลไม้ตายนี้ฟื้นฟู HP 15%',
		zawakeSimpleDesc_in = '#C0x5c9970#Efek bintang 11: Menyebabkan damage asli tambahan sebesar 50% dari total Serangan Ganda (dapat critical dan mengabaikan imun sihir/fisik); skill ultimate ini memberikan lifesteal sebesar 15%',
		zawakeSimpleDesc_ph = '#C0x5c9970#11-Star Effect: Gumagawa ng karagdagang tunay na pinsala na katumbas ng 50% ng kabuuang Double Attack (puwedeng mag-critical at hindi pinipigilan ng immunity sa Magic o Physical); Ang ultimate skill ay may kasamang 15% lifesteal',
		zawakeSimpleDesc_ma = '#C0x5c9970#Kesan 11 bintang: Memberikan kerosakan sebenar tambahan sebanyak 50% daripada jumlah Serangan Berganda kepada sasaran (boleh critical dan abaikan imuniti Magic/Fizikal); skill ultimate ini mempunyai kesan mencuri nyawa 15%',
		zawakeSimpleDesc_vn = '#C0x5c9970#Hiệu quả 11 sao: Gây thêm sát thương thực bằng 50% tổng công kép bản thân lên mục tiêu (sát thương này có thể bạo kích và bỏ qua miễn dịch Công Phép và miễn dịch Công Vật Lý); Kỹ năng tuyệt chiêu lần này kèm theo hiệu ứng hút máu 15%',
