		skillName_ma = 'Sinar Pemusnah',
		skillName = 'Destructive Beam',
		describe_vn = 'Super Rayquaza phát ra ánh sáng cực mạnh vào một mục tiêu kẻ thù, gây ra #C0xE69900#50% Sát Thương Vật Lý#C0x5B545B#+#C0x3D8A99#50% tấn Công Phép thuật#C0x5B54 5B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, tăng đòn tấn công kép của bản thân thêm thêm 40% và tốc độ 20%, kéo dài 2 hiệp',
		describe_en = 'Super Rayquaza emits a powerful light towards an enemy target, dealing #C0xE69900#50% Physical Damage#C0x5B545B#+#C0x3D8A99#50% Magical Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magical Damage#C0x5B545B#. Increases own double attack by 40% and speed by 20% for 2 turns.',
		describe_th = 'ซูเปอร์เรย์ควาซ่าส่งแสงที่รุนแรงอย่างมากไปยังเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#50%#C0x5B545B#+#C0x3D8A99#50% การโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# เพิ่มการโจมตีคู่ของตนเองขึ้นอีก 40% และความเร็ว 20% เป็นเวลา 2 เทิร์น',
		describe_in = 'Super Rayquaza memancarkan cahaya yang sangat kuat ke target musuh, menyebabkan #C0xE69900#50% Kerusakan Fisik#C0x5B545B#+#C0x3D8A99#50% Serangan Magis#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerusakan Magis#C0x5B545B#, meningkatkan serangan ganda sendiri sebesar 40% dan kecepatan sebesar 20%, berlangsung selama 2 giliran.',
		describe_ph = 'Ang Super Rayquaza ay naglalabas ng malakas na liwanag sa isang kaaway na target, na nagdudulot ng #C0xE69900#50% Pisikal na Pinsala#C0x5B545B#+#C0x3D8A99#50% Panggamagic na Atake#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Pinsalang Panggamagic#C0x5B545B#, nagpapataas ng sariling dobleng atake ng 40% at bilis ng 20% sa loob ng 2 turn.',
		describe_ma = 'Super Rayquaza memancarkan cahaya yang sangat terang ke sasaran musuh, menyebabkan #C0xE69900#50% Kerosakan Fizikal#C0x5B545B#+#C0x3D8A99#50% Serangan Magik#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerosakan Magik#C0x5B545B#, meningkatkan serangan berganda diri sendiri sebanyak 40% dan kelajuan sebanyak 20%, berlangsung selama 2 pusingan.',
		describe = 'Super Rayquaza emits a powerful light towards an enemy target, dealing #C0xE69900#50% Physical Damage#C0x5B545B#+#C0x3D8A99#50% Magical Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magical Damage#C0x5B545B#. Increases own double attack by 40% and speed by 20% for 2 turns.',
		zawakeEffect = __data_t__zawakeEffect[19821],
		-- {79001}
		zawakeEffectDesc = '#C0xC0C0C0# Enter my territory and accept my punishment order #C0x5B545B# \n#F10# \n#F40#Super Rayquaza emits extremely strong light onto an enemy target, causing #C0xE69900#50% Physical Damage#C0x5B545B#+#C0x3D8A99#50% Magical Attack#C0x5B545B#+$(skillLevel*4*24)$\'s #C0xF13B54#spell Damage#C0x5B545B# increasing a person\'s double attack by 40% and speed by 20% for 2 turns; additionally increases own critical damage by 10% and critical damage by 15%, lasting 2 turns and can stack up to 2 layers',
		zawakeEffectDesc_en = '#C0xC0C0C0# Enter my territory and accept my punishment order #C0x5B545B# \n#F10# \n#F40#Super Rayquaza emits extremely strong light onto an enemy target, causing #C0xE69900#50% Physical Damage#C0x5B545B#+#C0x3D8A99#50% Magical Attack#C0x5B545B#+$(skillLevel*4*24)$\'s #C0xF13B54#spell Damage#C0x5B545B# increasing a person\'s double attack by 40% and speed by 20% for 2 turns; additionally increases own critical damage by 10% and critical damage by 15%, lasting 2 turns and can stack up to 2 layers',
		zawakeEffectDesc_th = '#C0xC0C0C0# เข้าสู่ดินแดนของฉันและยอมรับคำสั่งลงโทษของฉัน #C0x5B545B# \n#F10# \n#F40#Super Rayquaza ปล่อยแสงสว่างรุนแรงมากไปยังเป้าหมายศัตรู ก่อให้เกิด #C0xE69900#50% ความเสียหายทางกายภาพ#C0x5B545B#+#C0x3D8A99#50% การโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$\'s #C0xF13B54#ความเสียหายเวทย์#C0x5B545B# เพิ่มการโจมตีคู่ของบุคคลหนึ่งขึ้น 40% และความเร็วขึ้น 20% เป็นเวลา 2 เทิร์น; นอกจากนี้ยังเพิ่มความเสียหายคริติคอลของตัวเอง 10% และความเสียหายคริติคอล 15% มีผล 2 เทิร์นและสะสมได้สูงสุด 2 ชั้น',
		zawakeEffectDesc_in = '#C0xC0C0C0# Masuki wilayah saya dan terima perintah hukuman saya #C0x5B545B# \n#F10# \n#F40#Super Rayquaza memancarkan cahaya sangat kuat ke target musuh, menyebabkan #C0xE69900#50% Kerusakan Fisik#C0x5B545B#+#C0x3D8A99#50% serangan sihir#C0x5B545B#+$(skillLevel*4*24)$\'s #C0xF13B54#kerusakan sihir#C0x5B545B# meningkatkan serangan ganda seseorang sebesar 40% dan kecepatan sebesar 20% selama 2 giliran; selain itu juga meningkatkan 10% kerusakan kritikal sendiri dan 15% kerusakan kritikal, bertahan selama 2 giliran dan dapat bertumpuk hingga 2 lapis',
		zawakeEffectDesc_ph = '#C0xC0C0C0# Pumasok sa teritoryo ko at tanggapin ang aking utos ng parusa #C0x5B545B# \n#F10# \n#F40#Super Rayquaza ay naglabas ng napakalakas na liwanag sa isang kalabang target, nagdudulot ng #C0xE69900#50% Pisikal na Pinsala#C0x5B545B#+#C0x3D8A99#50% atakeng pang-magic#C0x5B545B#+$(skillLevel*4*24)$\'s #C0xF13B54#spell Damage#C0x5B545B# nagpapataas ng dobleng pag-atake ng isang tao ng 40% at bilis ng 20% sa loob ng 2 turn; bukod pa rito, pinapataas ang sariling kritikal na pinsala ng 10% at kritikal na pinsala ng 15%, tumatagal ng 2 turn at maaaring mag-stack hanggang 2 layer',
		zawakeEffectDesc_ma = '#C0xC0C0C0# Masuk ke wilayah saya dan terima perintah hukuman saya #C0x5B545B# \n#F10# \n#F40#Super Rayquaza memancarkan cahaya yang sangat kuat ke sasaran musuh, menyebabkan #C0xE69900#50% Kerosakan Fizikal#C0x5B545B#+#C0x3D8A99#50% serangan sihir#C0x5B545B#+$(skillLevel*4*24)$\'s #C0xF13B54#kerosakan sihir#C0x5B545B# meningkatkan serangan berganda seseorang sebanyak 40% dan kelajuan sebanyak 20% selama 2 pusingan; selain itu juga meningkatkan 10% kerosakan kritikal sendiri dan 15% kerosakan kritikal, bertahan selama 2 pusingan dan boleh bertindih sehingga 2 lapisan',
		zawakeEffectDesc_vn = '#C0xC0C0C0# Bước vào lãnh thổ của tôi và chấp nhận lệnh trừng phạt của tôi #C0x5B545B# \n#F10# \n#F40#Super Rayquaza phát ra ánh sáng cực mạnh vào một mục tiêu kẻ thù, gây ra #C0xE69900#50% Sát Thương Vật Lý#C0x5B545B#+#C0x3D8A99#50% phép thuật attack#C0x5B545B#+$(skillLe vel*4*24)$\'s #C0xF13B54#spel Damage#C0x5B545B# tăng đòn tấn công kép của một người thêm 40% và tốc độ thêm 20%, kéo dài trong 2 lượt; ngoài ra còn tăng 10% sát thương chí mạng của bản thân và 15% sát thương chí mạng, tồn tại trong 2 lượt và có thể cộng dồn tối đa 2 lớp',
		zawakeSimpleType = 1,
