	[19822] = {
		id = 19822,
		skillName_vn = 'Lốc xoáy',
		skillName_en = 'Tornado',
		skillName_th = 'ทอร์นาโด',
		skillName_in = 'Topan',
		skillName_ph = 'Lindol',
		skillName_ma = 'Taufan',
		skillName = 'Tornado',
		describe_vn = 'Super Rayquaza bay lượn và triệu hồi một cơn lốc xoáy để tấn công một mục tiêu kẻ thù, gây ra #C0xE69900#90% Sát Thương Vật Lý#C0x5B545B#+#C0x3D8A99#90% tấn Công Phép thuật#C0x5B545B#+$(skillLeve l*4*48)$\'s #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, cái này đòn tấn công có hiệu ứng lan tỏa như bão (thêm 50% sát thương cuối cùng của kỹ năng này gây ra cho các mục tiêu xung quanh), và mục tiêu sẽ bị thổi bay lên trời trong 1 lượt\n#F10# \n#F40#[#L10#BLOWFLY#L0#]: Hiệu ứng khống chế, không thể xua tan, không thể tấn công hoặc nhận đòn trong thời gian đó. Khi mục tiêu rơi trở lại mặt đất, có 70% khả năng bị đánh bất tỉnh và rơi vào trạng thái [choáng] 1 lượt (choáng: hiệu ứng khống chế, không thể hành động), càng có nhiều mục tiêu xung quanh thì khả năng bị choáng càng cao, lên tới 100% \n#F20# \n#F40#[#L10#Bay lên mây#L0#] Kỹ năng nhỏ đầu tiên sau [#L10#Bay lên mây#L0#] có thể nhận được [Khiên Gió]\n#F10# \n#F40#[#L10#Wind Shield#L0#] trong 2 lượt: không thể chồng lên nhau và có thể hấp thụ 100% lượng lá chắn từ tổng các đòn tấn công kép của Super Rayquaza. Sau khi tấm chắn gió bị vỡ sẽ gây sát thương tương đương với lượng khiên cho kẻ tấn công.',
		describe_en = 'Super Rayquaza soars and summons a whirlwind to attack an enemy target, dealing #C0xE69900#90% Physical Damage#C0x5B545B#+#C0x3D8A99#90% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Magic Damage #C0x5B545B#. This attack has a spreading effect like a storm (adding 50% of the final damage of this skill to surrounding targets), and the target will be blown into the air for 1 turn \n#F10# \n#F40#[#L10#BLOWFLY#L0#]: Control effect, cannot be removed, target can\'t attack or be attacked during this time. When the target falls back to the ground, there is a 70% chance to be stunned and enter [stun] status for 1 turn (stun: control effect, unable to act). The more targets nearby, the higher the chance to be stunned, up to 100% \n#F20# \n#F40#[#L10#Fly Up to the Clouds#L0#]. The first minor skill after [#L10#Fly Up to the Clouds#L0#] can gain [Wind Shield]\n#F10# \n#F40#[#L10#Wind Shield#L0#] for 2 turns: cannot stack and can absorb 100% of the shield from the combined double attacks of Super Rayquaza. When the wind shield breaks, it deals damage equal to the shield amount to the attacker.',
		describe_th = 'Super Rayquaza โผบินและเรียกลมพายุเพื่อตีเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#90%#C0x5B545B#+#C0x3D8A99#90% พลังโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# การโจมตีนี้มีเอฟเฟ็กต์กระจายเหมือนพายุ (เพิ่มความเสียหาย 50% ของความเสียหายสุดท้ายของสกิลนี้ไปยังเป้าหมายรอบๆ) และเป้าหมายจะถูกพัดขึ้นฟ้าเป็นเวลา 1 เทิร์น \n#F10# \n#F40#[#L10#BLOWFLY#L0#]: เอฟเฟกต์ควบคุม ไม่สามารถคลายได้ เป้าหมายไม่สามารถโจมตีหรือรับการโจมตีในช่วงเวลานี้ เมื่อเป้าหมายตกลงสู่พื้น มีโอกาส 70% ที่จะสตั๊นและเข้าสู่สถานะ [ตะลึง] 1 เทิร์น (ตะลึง: เอฟเฟกต์ควบคุม ไม่สามารถกระทำได้) ยิ่งมีเป้าหมายรอบๆ มาก โอกาสตะลึงจะยิ่งสูงขึ้นถึง 100% \n#F20# \n#F40#[#L10#บินขึ้นสู่เมฆ#L0#] สกิลเล็กแรกหลัง [#L10#บินขึ้นสู่เมฆ#L0#] จะได้รับ [โล่ลม]\n#F10# \n#F40#[#L10#โล่ลม#L0#] เป็นเวลา 2 เทิร์น: ไม่สามารถซ้อนทับกันและสามารถดูดซับ 100% ของจำนวนโล่จากการโจมตีคู่ของ Super Rayquaza เมื่อโล่ลมแตกจะสร้างความเสียหายเท่ากับจำนวนโล่แก่ศัตรูที่โจมตี',
		describe_in = 'Super Rayquaza terbang dan memanggil pusaran angin untuk menyerang target musuh, memberikan #C0xE69900#90% Kerusakan Fisik#C0x5B545B#+#C0x3D8A99#90% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Serangan ini memiliki efek menyebar seperti badai (menambahkan 50% dari total kerusakan akhir skill ini ke target di sekitarnya), dan target akan tertiup ke udara selama 1 giliran \n#F10# \n#F40#[#L10#BLOWFLY#L0#]: Efek kontrol, tidak bisa dibatalkan, target tidak bisa menyerang atau menerima serangan selama waktu tersebut. Ketika target jatuh kembali ke tanah, ada kemungkinan 70% untuk pingsan dan memasuki status [tertegun] selama 1 giliran (tertegun: efek kontrol, tidak bisa bertindak), semakin banyak target di sekitar, semakin tinggi kemungkinan tertegun, hingga 100% \n#F20# \n#F40#[#L10#Terbang ke Awan#L0#]. Skill kecil pertama setelah [#L10#Terbang ke Awan#L0#] dapat memperoleh [Perisai Angin]\n#F10# \n#F40#[#L10#Perisai Angin#L0#] selama 2 giliran: tidak dapat ditumpuk dan dapat menyerap 100% dari jumlah perisai dari serangan ganda Super Rayquaza. Setelah perisai angin pecah, akan memberikan kerusakan sebesar jumlah perisai kepada penyerang.',
		describe_ph = 'Ang Super Rayquaza ay lumilipad at tumatawag ng isang buhawi upang atakihin ang isang kalaban na target, na nagdudulot ng #C0xE69900#90% Physical Damage#C0x5B545B#+#C0x3D8A99#90% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Magic Damage #C0x5B545B#. Ang pag-atakeng ito ay may epekto ng pagkalat tulad ng bagyo (nagdadagdag ng 50% ng pangwakas na pinsala ng skill na ito sa mga nakapaligid na target), at ang target ay hahangin pataas sa himpapawid ng 1 turn \n#F10# \n#F40#[#L10#BLOWFLY#L0#]: Kontrol na epekto, hindi mapapawi, ang target ay hindi maaaring umatake o makatanggap ng atake sa panahong ito. Kapag bumagsak ang target pabalik sa lupa, may 70% posibilidad na ma-stun at mapasailalim sa [stun] status sa loob ng 1 turn (stun: kontrol na epekto, hindi makakilos), mas maraming target sa paligid ay mas mataas ang tsansa ng stun, hanggang 100% \n#F20# \n#F40#[#L10#Lumipad Papunta sa Ulap#L0#]. Ang unang maliit na skill pagkatapos ng [#L10#Lumipad Papunta sa Ulap#L0#] ay maaaring makakuha ng [Wind Shield]\n#F10# \n#F40#[#L10#Wind Shield#L0#] sa loob ng 2 turn: hindi maaaring pagsamahin at maaaring sumipsip ng 100% ng shield mula sa pinagsamang double attacks ng Super Rayquaza. Kapag nabasag ang shield ng hangin, ito ay magdudulot ng pinsalang katumbas ng halaga ng shield sa attacker.',
		describe_ma = 'Super Rayquaza terbang dan memanggil pusaran angin untuk menyerang sasaran musuh, menyebabkan #C0xE69900#90% Kerosakan Fizikal#C0x5B545B#+#C0x3D8A99#90% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Serangan ini mempunyai kesan menular seperti ribut (menambah 50% daripada jumlah kerosakan akhir kemahiran ini kepada sasaran di sekeliling), dan sasaran akan diterbangkan ke udara selama 1 giliran \n#F10# \n#F40#[#L10#BLOWFLY#L0#]: Kesan kawalan, tidak boleh dibersihkan, sasaran tidak boleh menyerang atau menerima serangan sepanjang tempoh itu. Apabila sasaran jatuh kembali ke tanah, terdapat kebarangkalian 70% untuk terhantuk dan memasuki keadaan [pengsan] selama 1 giliran (pengsan: kesan kawalan, tidak boleh bertindak), semakin banyak sasaran di sekitar, semakin tinggi kebarangkalian pengsan, sehingga 100% \n#F20# \n#F40#[#L10#Terbang ke Awan#L0#]. Kemahiran kecil pertama selepas [#L10#Terbang ke Awan#L0#] boleh menerima [Perisai Angin]\n#F10# \n#F40#[#L10#Perisai Angin#L0#] selama 2 giliran: tidak boleh bertindih dan boleh menyerap 100% jumlah perisai dari serangan berganda Super Rayquaza. Apabila perisai angin pecah, ia akan menyebabkan kerosakan sama dengan jumlah perisai kepada penyerang.',
		describe = 'Super Rayquaza soars and summons a whirlwind to attack an enemy target, dealing #C0xE69900#90% Physical Damage#C0x5B545B#+#C0x3D8A99#90% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Magic Damage #C0x5B545B#. This attack has a spreading effect like a storm (adding 50% of the final damage of this skill to surrounding targets), and the target will be blown into the air for 1 turn \n#F10# \n#F40#[#L10#BLOWFLY#L0#]: Control effect, cannot be removed, target can\'t attack or be attacked during this time. When the target falls back to the ground, there is a 70% chance to be stunned and enter [stun] status for 1 turn (stun: control effect, unable to act). The more targets nearby, the higher the chance to be stunned, up to 100% \n#F20# \n#F40#[#L10#Fly Up to the Clouds#L0#]. The first minor skill after [#L10#Fly Up to the Clouds#L0#] can gain [Wind Shield]\n#F10# \n#F40#[#L10#Wind Shield#L0#] for 2 turns: cannot stack and can absorb 100% of the shield from the combined double attacks of Super Rayquaza. When the wind shield breaks, it deals damage equal to the shield amount to the attacker.',
		zawakeEffect = __data_t__zawakeEffect[19822],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#I will ride the wind#C0x5B545B# \n#F10# \n#F40#Super Rayquaza soars and summons a whirlwind to attack an enemy target, dealing #C0xE69900#90% Physical Damage#C0x5B545B#+#C0x3D8A99#90% magical attack#C0x5B545B#+$(sk illLevel*4*48)$\'s #C0xF13B54#spell damage#C0x5B545B#, this attack has a tornado-like area effect (dealing an additional 50% of the final skill damage to surrounding targets) and will blow the target into the air for 1 turn \n#F10# \n#F40#<#L10#BLOWFLY#L0#>: Control effect, cannot be removed, cannot attack or be hit during this time, the target has a 70% chance to be knocked out and fall into <Stun> for 1 turn when landing (Stun: Control effect, cannot act), the more targets around, the higher the chance of stun, up to 100%. Upon landing, it causes 50% real damage of Super Rayquaza\'s dual attack to the target and applies 20% vulnerability effect (damage and vulnerability effects of surrounding units are halved) \n#F20# \n#F40# The first minor skill after <#L10#Cloud Dive#L0#> can gain <Wind Shield> \n#F10# \n#F40#<#L10#Wind Shield#L0#> lasts 2 rounds: can stack 1 layer, can absorb 180% shield amount from Super Rayquaza\'s dual attack total damage. After the wind shield breaks, it deals damage equal to the shield amount to the attacker. When equipped with <Wind Shield>, it splits into two small tornadoes by releasing a minor skill, randomly attacks enemies, and deals 50% real damage of its dual strike.',
		zawakeEffectDesc_en = '#C0xC0C0C0#I will ride the wind#C0x5B545B# \n#F10# \n#F40#Super Rayquaza soars and summons a whirlwind to attack an enemy target, dealing #C0xE69900#90% Physical Damage#C0x5B545B#+#C0x3D8A99#90% magical attack#C0x5B545B#+$(sk illLevel*4*48)$\'s #C0xF13B54#spell damage#C0x5B545B#, this attack has a tornado-like area effect (dealing an additional 50% of the final skill damage to surrounding targets) and will blow the target into the air for 1 turn \n#F10# \n#F40#<#L10#BLOWFLY#L0#>: Control effect, cannot be removed, cannot attack or be hit during this time, the target has a 70% chance to be knocked out and fall into <Stun> for 1 turn when landing (Stun: Control effect, cannot act), the more targets around, the higher the chance of stun, up to 100%. Upon landing, it causes 50% real damage of Super Rayquaza\'s dual attack to the target and applies 20% vulnerability effect (damage and vulnerability effects of surrounding units are halved) \n#F20# \n#F40# The first minor skill after <#L10#Cloud Dive#L0#> can gain <Wind Shield> \n#F10# \n#F40#<#L10#Wind Shield#L0#> lasts 2 rounds: can stack 1 layer, can absorb 180% shield amount from Super Rayquaza\'s dual attack total damage. After the wind shield breaks, it deals damage equal to the shield amount to the attacker. When equipped with <Wind Shield>, it splits into two small tornadoes by releasing a minor skill, randomly attacks enemies, and deals 50% real damage of its dual strike.',
		zawakeEffectDesc_th = '#C0xC0C0C0#ฉันจะขึ้นขี่ลม#C0x5B545B# \n#F10# \n#F40#ซูเปอร์เรย์ควาชาบินโฉบและเรียกพายุหมุนเพื่อโจมตีเป้าหมายศัตรู ทำให้เกิด #C0xE69900#ความเสียหายทางกายภาพ 90%#C0x5B545B#+#C0x3D8A99#ความเสียหายเวทมนตร์ 90%#C0x5B545B#+$(sk illLevel*4*48)$\'s #C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# การโจมตีนี้มีผลแบบพายุหมุนที่กระจายออก (สร้างความเสียหายเพิ่มอีก 50% จากความเสียหายสุดท้ายของทักษะนี้ต่อเป้าหมายรอบข้าง) และจะพุ่งเป้าหมายขึ้นสู่ท้องฟ้าใน 1 เทิร์น \n#F10# \n#F40#<#L10#BLOWFLY#L0#>: ผลการควบคุม ไม่สามารถลบได้ ไม่สามารถโจมตีหรือติดคริติคอลระหว่างนี้ได้ เป้าหมายมีโอกาส 70% ที่จะถูกทำให้อ่อนแรงและตกลงใน <มึนงง> เป็นเวลา 1 เทิร์นเมื่อกลับถึงพื้น (มึนงง: ผลการควบคุม ไม่สามารถกระทำการได้) ยิ่งมีเป้าหมายรอบๆ มากเท่าไหร่ โอกาสถูกมึนงงก็จะยิ่งสูงขึ้น สูงสุด 100% หลังลงสู่พื้น จะสร้างความเสียหายจริง 50% ของการโจมตีคู่ของซูเปอร์เรย์ควาชาแก่เป้าหมายและมีผลเปราะบาง 20% (ความเสียหายและผลเปราะบางของหน่วยรอบข้างถูกลดลงครึ่งหนึ่ง) \n#F20# \n#F40# สกิลย่อยแรกหลังจาก <#L10#บินเข้าสู่เมฆ#L0#> สามารถได้รับ <โล่ลม> \n#F10# \n#F40#<#L10#โล่ลม#L0#> 2 รอบ: สามารถซ้อนทับได้ 1 ชั้น สามารถดูดซับเกราะ 180% จากความเสียหายรวมของการโจมตีคู่ของซูเปอร์เรย์ควาชา หลังจากโล่ลมแตก จะสร้างความเสียหายเท่ากับจำนวนเกราะแก่ผู้โจมตี เมื่อมี <โล่ลม> ติดตั้ง จะสลายตัวเป็นพายุกันลมเล็กสองลูกด้วยการปล่อยสกิลย่อย โจมตีศัตรูแบบสุ่มและสร้างความเสียหายจริง 50% ของการโจมตีคู่ของมันเอง',
		zawakeEffectDesc_in = '#C0xC0C0C0#Aku akan menunggang angin#C0x5B545B# \n#F10# \n#F40#Super Rayquaza terbang dan memanggil pusaran angin untuk menyerang target musuh, menghasilkan #C0xE69900#90% Damage Fisik#C0x5B545B#+#C0x3D8A99#90% serangan sihir#C0x5B545B#+$(sk illLevel*4*48)$\'s #C0xF13B54#damage mantra#C0x5B545B#, serangan ini memiliki efek area seperti tornado (memberikan tambahan 50% damage akhir skill ini ke target di sekitarnya) dan akan meniup target ke udara selama 1 giliran \n#F10# \n#F40#<#L10#BLOWFLY#L0#>: Efek kontrol, tidak dapat dibatalkan, tidak dapat menyerang atau terkena serangan selama waktu ini, target memiliki peluang 70% untuk pingsan dan jatuh ke dalam <Pingsan> selama 1 giliran saat mendarat (Pingsan: Efek kontrol, tidak dapat bertindak), semakin banyak target di sekitar, semakin tinggi peluang pingsan, hingga maksimum 100%. Setelah mendarat, memberikan 50% damage nyata dari serangan ganda Super Rayquaza ke target dan 20% efek kerentanan (damage dan efek kerentanan dari unit di sekitar dikurangi setengah) \n#F20# \n#F40# Skill kecil pertama setelah <#L10#Terbang ke Awan#L0#> dapat memperoleh <Perisai Angin> \n#F10# \n#F40#<#L10#Perisai Angin#L0#> bertahan 2 giliran: dapat menumpuk 1 lapis, dapat menyerap 180% jumlah perisai dari total damage serangan ganda Super Rayquaza. Setelah perisai angin pecah akan memberikan damage setara dengan jumlah perisai ke penyerang. Saat dilengkapi <Perisai Angin>, ia akan membelah menjadi dua pusaran kecil dengan melepaskan skill kecil, menyerang musuh secara acak dan memberikan 50% damage nyata dari serangan gandanya sendiri.',
		zawakeEffectDesc_ph = '#C0xC0C0C0#Ako ay sasakay sa hangin#C0x5B545B# \n#F10# \n#F40#Sumusulong si Super Rayquaza at nagtataboy ng isang whirlwind upang atakihin ang isang kalabang target, nagdudulot ng #C0xE69900#90% Pisikal na Pinsala#C0x5B545B#+#C0x3D8A99#90% na magical attack#C0x5B545B#+$(sk illLevel*4*48)$\'s #C0xF13B54#spell na pinsala#C0x5B545B#, ang pag-atakeng ito ay may epektong parang bagyong umaabot sa paligid (nagdudulot ng dagdag na 50% sa huling pinsala ng kasanayan na ito sa mga kalapit na target) at tututok ang target pataas sa himpapawid sa loob ng 1 turno \n#F10# \n#F40#<#L10#BLOWFLY#L0#>: Epekto ng kontrol, hindi maaaring alisin, hindi makakasalakay o matamaan habang nasa epektong ito, may 70% tsansa ang target na ma-knockout at mapunta sa <Stun> ng 1 turno pagkaraan bumaba sa lupa (Stun: Epekto ng kontrol, hindi makakilos), mas maraming target ang nakapaligid, mas mataas ang posibilidad na ma-stun, hanggang sa 100%. Pagkatapos bumaba sa lupa, nagdudulot ito ng 50% totoong pinsala mula sa dual attack ni Super Rayquaza sa target at may 20% effect na pagiging marupok (pinsala at effect na pagiging marupok sa mga kalapit na yunit ay nababawasan ng kalahati) \n#F20# \n#F40# Ang unang maliit na kakayahan pagkatapos ng <#L10#Paglipad sa Ulap#L0#> ay maaaring makamit ang <Wind Shield> \n#F10# \n#F40#<#L10#Wind Shield#L0#> tumatagal ng 2 turno: maaaring mag-stack ng 1 layer, maaaring sumipsip ng 180% shield mula sa kabuuang dual attack damage ni Super Rayquaza. Pagkatapos mabasag ang shield ng hangin, magdudulot ito ng pinsala katumbas ng halaga ng shield sa umaatake. Kapag may <Wind Shield>, ito ay hinahati sa dalawang maliit na whirlwind sa pamamagitan ng pagpapakawala ng isang maliit na kakayahan, random na inaatake ang mga kalaban at nagdudulot ng 50% totoong pinsala ng sariling dual strike.',
		zawakeEffectDesc_ma = '#C0xC0C0C0#Aku akan menunggang angin#C0x5B545B# \n#F10# \n#F40#Super Rayquaza terbang dan memanggil pusaran angin untuk menyerang sasaran musuh, menyebabkan #C0xE69900#90% Kerosakan Fizikal#C0x5B545B#+#C0x3D8A99#90% serangan sihir#C0x5B545B#+$(sk illLevel*4*48)$\'s #C0xF13B54#kerosakan sihir#C0x5B545B#, serangan ini mempunyai kesan kawasan seperti taufan (menyebabkan tambahan 50% kerosakan akhir kemahiran ini ke sasaran sekeliling) dan akan meniup sasaran ke udara selama 1 pusingan \n#F10# \n#F40#<#L10#BLOWFLY#L0#>: Kesan kawalan, tidak boleh dibuang, tidak boleh menyerang atau terkena serangan dalam tempoh ini, sasaran mempunyai 70% peluang untuk pengsan dan jatuh ke dalam <Pengsan> selama 1 pusingan apabila mendarat (Pengsan: Kesan kawalan, tidak boleh bertindak), semakin banyak sasaran di sekeliling, semakin tinggi kebarangkalian pengsan, sehingga maksimum 100%. Selepas mendarat, ia menyebabkan 50% kerosakan sebenar dari serangan berganda Super Rayquaza ke sasaran dan 20% kesan kerentanan (kerosakan dan kesan kerentanan unit di sekitar dikurangkan separuh) \n#F20# \n#F40# Kemahiran kecil pertama selepas <#L10#Terbang ke Awan#L0#> boleh mendapat <Perisai Angin> \n#F10# \n#F40#<#L10#Perisai Angin#L0#> selama 2 pusingan: boleh bertindih 1 lapisan, boleh menyerap 180% jumlah perisai dari jumlah kerosakan serangan berganda Super Rayquaza. Selepas perisai angin pecah, ia akan menyebabkan kerosakan yang setara dengan jumlah perisai kepada penyerang. Apabila dipasang <Perisai Angin>, ia akan membahagikan menjadi dua pusaran kecil dengan melepaskan kemahiran kecil, menyerang musuh secara rawak dan menyebabkan 50% kerosakan sebenar dari serangan bergandanya sendiri.',
		zawakeEffectDesc_vn = '#C0xC0C0C0#Tôi sẽ cưỡi trên gió#C0x5B545B# \n#F10# \n#F40#Super Rayquaza bay lượn và triệu hồi một cơn lốc xoáy để tấn công một mục tiêu kẻ địch, gây ra #C0xE69900#90% Sát Thương Vật Lý#C0x5B545B#+#C0x3D8A99#90% phép thuật attack#C0x5B545B#+$(sk illLevel*4*48)$\'s #C0xF13B54#spell sát thương#C0x5B545B#, đòn tấn công này có hiệu ứng lan rộng như bão (gây thêm 50% sát thương cuối cùng của kỹ năng này lên các mục tiêu xung quanh) và sẽ thổi mục tiêu lên trời trong 1 hiệp \n#F10# \n#F40#<#L10#BLOWFLY#L0#>: Hiệu ứng khống chế, không thể giải trừ, không thể tấn công hoặc bị trúng đòn trong thời gian, mục tiêu có 70% khả năng bị đánh bất tỉnh và rơi vào <Choáng> 1 lượt khi rơi trở lại mặt đất (Choáng: Hiệu ứng khống chế, không thể hành động), càng có nhiều mục tiêu xung quanh thì xác suất bị choáng càng cao, có thể tăng lên tới 100%. Sau khi hạ cánh, nó sẽ gây ra 50% sát thương thực sự của đòn tấn công kép Super Rayquaza cho mục tiêu và 20% hiệu ứng dễ bị tổn thương (sát thương và hiệu ứng dễ bị tổn thương của các đơn vị xung quanh giảm một nửa) \n#F20# \n#F40# Kỹ năng nhỏ đầu tiên sau <#L10#Bay vào mây#L0#> có thể nhận được <Wind Shield> \n#F10# \n#F40#<#L10#Wind Shield#L0#> 2 vòng: có thể chồng thêm 1 lớp, có thể hấp thụ 180% lượng khiên từ tổng đòn tấn công kép của Super Rayquaza. Sau khi tấm chắn gió bị vỡ sẽ gây sát thương tương đương với lượng khiên cho kẻ tấn công. Khi được trang bị <Khiên gió>, nó sẽ tách thành hai cơn lốc nhỏ bằng cách giải phóng một kỹ năng nhỏ, tấn công kẻ thù ngẫu nhiên và gây ra 50% sát thương thực sự của đòn đánh kép của chính nó.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Wind Shield amount increases by 50%, can stack once more; while under <Wind Shield>, casting a basic skill summons two mini tornadoes to randomly hit enemies, dealing true damage equal to 50% of Double Attack; <Knock-Up> When the target lands, deals true damage equal to 50% of Double Attack to target and nearby enemies, with 20% Vulnerable effect (damage and effect halved for nearby enemies)  ',
		zawakeSimpleDesc_en = '#C0x5c9970#Wind Shield amount increases by 50%, can stack once more; while under <Wind Shield>, casting a basic skill summons two mini tornadoes to randomly hit enemies, dealing true damage equal to 50% of Double Attack; <Knock-Up> When the target lands, deals true damage equal to 50% of Double Attack to target and nearby enemies, with 20% Vulnerable effect (damage and effect halved for nearby enemies)  ',
		zawakeSimpleDesc_th = '#C0x5c9970#โล่ลมเพิ่มขึ้น 50% และสะสมได้เพิ่ม 1 ชั้น; ขณะมี <โล่ลม> การใช้สกิลพื้นฐานจะปล่อยพายุเล็ก 2 ลูกโจมตีศัตรูแบบสุ่ม สร้างความเสียหายจริง 50% จากการโจมตีสองครั้ง; <ลอยขึ้น> เมื่อเป้าหมายตกลงพื้น สร้างความเสียหายจริง 50% จากการโจมตีสองครั้งให้เป้าหมายและหน่วยใกล้เคียง พร้อมเอฟเฟกต์อ่อนแอลง 20% (ศัตรูรอบข้างจะรับผลเพียงครึ่งหนึ่ง)',
		zawakeSimpleDesc_in = '#C0x5c9970#Jumlah Perisai Angin meningkat 50% dan dapat ditumpuk satu kali lagi; saat memiliki <Perisai Angin>, menggunakan skill dasar akan memanggil 2 tornado kecil yang menyerang musuh acak, memberikan damage asli sebesar 50% dari Serangan Ganda; <Terlontar> saat target jatuh, memberikan damage asli 50% dari Serangan Ganda kepada target dan musuh sekitar, disertai efek Rentan 20% (efek dan damage terhadap musuh sekitar dikurangi setengah)  ',
		zawakeSimpleDesc_ph = '#C0x5c9970#Ang halaga ng Wind Shield ay tumataas ng 50% at puwedeng i-stack isang beses pa; habang may <Wind Shield>, ang paggamit ng basic skill ay lumilikha ng 2 mini tornado na random na umatake, gumagawa ng tunay na pinsala na katumbas ng 50% ng Double Attack; <Tinatangay> kapag bumagsak ang target, nagdudulot ng tunay na pinsala na katumbas ng 50% ng Double Attack sa target at mga kalapit na kaaway, na may 20% Vulnerable effect (kalahati ang pinsala at effect sa mga kaaway sa paligid)  ',
		zawakeSimpleDesc_ma = '#C0x5c9970#Jumlah Perisai Angin meningkat sebanyak 50%, boleh ditindan sekali lagi; semasa mempunyai <Perisai Angin>, menggunakan skill asas akan menjana 2 tornado kecil menyerang musuh rawak, menyebabkan kerosakan sebenar 50% Serangan Berganda; <Tersingkir> Apabila sasaran jatuh, menyebabkan kerosakan sebenar 50% Serangan Berganda ke atas sasaran dan musuh sekitarnya, dengan kesan Rentan 20% (kesan dan kerosakan kepada musuh sekeliling dikurangkan separuh)  ',
		zawakeSimpleDesc_vn = '#C0x5c9970#Lượng Khiên Gió tăng 50% có thể cộng dồn thêm một lần; Khi bản thân có <Khiên Gió>, sử dụng kỹ năng nhỏ sẽ tạo ra hai cơn lốc nhỏ tấn công kẻ địch ngẫu nhiên, gây sát thương thực bằng 50% công kép bản thân; <Thổi Bay> Khi mục tiêu rơi xuống đất, gây sát thương thực bằng 50% công kép bản thân lên mục tiêu và các đơn vị xung quanh mục tiêu, kèm theo hiệu ứng dễ bị tổn thương 20% (sát thương và hiệu ứng dễ bị tổn thương của các đơn vị xung quanh giảm một nửa)',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
