	[19823] = {
		id = 19823,
		skillName_vn = 'Điểm nhấn rồng',
		skillName_en = 'Dragon highlight',
		skillName_th = 'ไฮไลท์มังกร',
		skillName_in = 'Sorotan naga',
		skillName_ph = 'Dragon highlight',
		skillName_ma = 'Sorotan naga',
		skillName = 'Dragon highlight',
		describe_vn = '#L10#Đòn kết liễu: #L0#Super Rayquaza bay lên mây, đưa các mục tiêu dàn trận của kẻ địch lên trời rồi giải phóng sức mạnh của bầu trời, gây ra #C0xE69900#180% đòn Sát Thương Vật Lý#C0x5B545B#+#C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B54 5B#+$(skillLevel*4*80)$#C0xF13B54#spel Damage#C0x5B545B#, Rayquaza làm trung gian tinh thần chiến đấu của mục tiêu, khiến mục tiêu [Seal Rage] trong 1 hiệp (Seal Rage: hiệu ứng tiêu cực, không thể xua tan và Rage không thể phục hồi trong khoảng thời gian này)\n#F20# \n#F40##L10# Cú chạm cuối cùng: #L0# Super Rayquaza bay lên mây, đưa mục tiêu của kẻ địch lên trời rồi giải phóng sức mạnh của bầu trời, gây ra #C0xE69900#200% Sát Thương Vật Lý#C0x5B545B#+#C0x3D8A99#200% tấn công ma thuật#C0x5B5 45B#+$(skillLevel*4*80)$#C0xF13B54#spell sát thương#C0x5B545B# khiến mục tiêu [Seal Rage] trong 1 lượt, tiêu thụ toàn bộ [Rage] để tăng khả năng hút máu của bản thân thêm 20% và 30% sát thương chí mạng trong 2 lượt. Sau khi kích hoạt, nó sẽ giảm 20% khả năng phòng thủ kép trong 1 lượt.',
		describe_en = 'Finishing Strike: Super Rayquaza soars into the clouds, lifting enemy formation targets into the sky and unleashing the power of the heavens, dealing 180% Physical Damage + 180% Magic Damage + $(skillLevel*4*80)$ spell Damage. Rayquaza acts as a spiritual mediator for the target\'s combat, causing the target to [Seal Rage] for 1 turn (Seal Rage: a negative status effect that cannot be removed and Rage cannot recover during this time). \n Final Touch: Super Rayquaza flies into the clouds, lifting the enemy\'s target into the sky and releasing the power of the heavens, dealing 200% Physical Damage + 200% Magic Attack + $(skillLevel*4*80)$ spell damage, causing the target to [Seal Rage] for 1 turn, consuming all [Rage] to increase self life-steal by 20% and critical damage by 30% for 2 turns. After activation, it reduces dual defense by 20% for 1 turn.',
		describe_th = 'ท่าโจมตีขั้นสุดท้าย: Super Rayquaza บินขึ้นสู่เมฆ นำเป้าหมายแนวศัตรูขึ้นสู่ท้องฟ้าแล้วปลดปล่อยพลังแห่งท้องฟ้า สร้างความเสียหายทางกายภาพ 180% + ความเสียหายเวทย์ 180% + $(skillLevel*4*80)$ ความเสียหายเวทย์ Rayquaza ทำหน้าที่เป็นสื่อกลางจิตใจในศึกของเป้าหมาย ทำให้เป้าหมาย [Seal Rage] เป็นเวลา 1 เทิร์น (Seal Rage: สถานะลบ ไม่สามารถลบได้ และ Rage ไม่ฟื้นฟูในช่วงเวลานี้) \n สัมผัสสุดท้าย: Super Rayquaza บินขึ้นสู่เมฆ นำเป้าหมายของศัตรูขึ้นสู่ฟ้าแล้วปลดปล่อยพลังแห่งท้องฟ้า สร้างความเสียหายทางกายภาพ 200% + ความเสียหายเวทย์ 200% + $(skillLevel*4*80)$ ความเสียหายเวทย์ ทำให้เป้าหมาย [Seal Rage] เป็นเวลา 1 เทิร์น ใช้ Rage ทั้งหมดเพื่อเพิ่มการดูดเลือดตัวเอง 20% และความเสียหายคริติคอล 30% เป็นเวลา 2 เทิร์น หลังจากเปิดใช้งาน จะลดการป้องกันคู่ลง 20% เป็นเวลา 1 เทิร์น',
		describe_in = 'Serangan Penuntasan: Super Rayquaza terbang ke awan, mengangkat target formasi musuh ke langit lalu melepaskan kekuatan langit, menyebabkan 180% Kerusakan Fisik + 180% Kerusakan Sihir + $(skillLevel*4*80)$ Kerusakan mantra. Rayquaza bertindak sebagai perantara spiritual dalam pertempuran target, menyebabkan target [Seal Rage] selama 1 giliran (Seal Rage: efek negatif, tidak dapat disapu bersih dan Rage tidak bisa pulih selama waktu ini). \n Sentuhan Terakhir: Super Rayquaza terbang ke awan, mengangkat target musuh ke langit lalu melepaskan kekuatan langit, menyebabkan 200% Kerusakan Fisik + 200% Serangan sihir + $(skillLevel*4*80)$ kerusakan mantra, menyebabkan target [Seal Rage] selama 1 giliran, menghabiskan semua [Rage] untuk meningkatkan kemampuan pencurian darah diri sendiri sebesar 20% dan 30% kerusakan kritikal selama 2 giliran. Setelah aktif, mengurangi pertahanan ganda sebesar 20% selama 1 giliran.',
		describe_ph = 'Finishing Blow: Super Rayquaza lumilipad sa ulap, iniaangat ang mga target ng pormasyon ng kalaban sa himpapawid at pinapalabas ang kapangyarihan ng langit, na nagdudulot ng 180% Pisikal na Pinsala + 180% Mahiwagang Pinsala + $(skillLevel*4*80)$ spell Damage. Ginagawa ni Rayquaza ang espirituwal na tagapamagitan ng laban ng target, na nagdudulot ng [Seal Rage] sa target sa loob ng 1 turn (Seal Rage: negatibong epekto, hindi maaaring alisin at hindi nakakabawi ang Rage sa panahong ito). \n Huling Haplos: Super Rayquaza lumilipad sa ulap, iniaangat ang target ng kalaban sa himpapawid at pinapalabas ang kapangyarihan ng langit, na nagdudulot ng 200% Pisikal na Pinsala + 200% Mahiwagang Atake + $(skillLevel*4*80)$ spell damage, na nagdudulot ng [Seal Rage] sa target sa loob ng 1 turn, kinokonsumo ang lahat ng [Rage] para tumaas ang sarili nitong life-steal ng 20% at 30% kritikal na pinsala sa loob ng 2 turn. Pagkatapos ma-activate, babawasan nito ang doble na depensa ng target ng 20% sa loob ng 1 turn.',
		describe_ma = 'Serangan Penamat: Super Rayquaza terbang ke awan, mengangkat sasaran barisan musuh ke udara kemudian melepaskan kuasa langit, menyebabkan 180% Kerosakan Fizikal + 180% Kerosakan Sihir + $(skillLevel*4*80)$ Kerosakan Sihir. Rayquaza berfungsi sebagai perantara semangat pertempuran sasaran, menyebabkan sasaran [Seal Rage] selama 1 pusingan (Seal Rage: kesan negatif, tidak boleh disingkirkan dan Rage tidak boleh pulih dalam tempoh ini). \n Sentuhan Terakhir: Super Rayquaza terbang ke awan, mengangkat sasaran musuh ke udara kemudian melepaskan kuasa langit, menyebabkan 200% Kerosakan Fizikal + 200% Serangan Sihir + $(skillLevel*4*80)$ kerosakan sihir, menyebabkan sasaran [Seal Rage] selama 1 pusingan, menggunakan semua [Rage] untuk meningkatkan kemampuan sedutan darah sendiri sebanyak 20% dan 30% kerosakan kritikal selama 2 pusingan. Selepas diaktifkan, ia akan mengurangkan pertahanan berganda sebanyak 20% selama 1 pusingan.',
		describe = 'Finishing Strike: Super Rayquaza soars into the clouds, lifting enemy formation targets into the sky and unleashing the power of the heavens, dealing 180% Physical Damage + 180% Magic Damage + $(skillLevel*4*80)$ spell Damage. Rayquaza acts as a spiritual mediator for the target\'s combat, causing the target to [Seal Rage] for 1 turn (Seal Rage: a negative status effect that cannot be removed and Rage cannot recover during this time). \n Final Touch: Super Rayquaza flies into the clouds, lifting the enemy\'s target into the sky and releasing the power of the heavens, dealing 200% Physical Damage + 200% Magic Attack + $(skillLevel*4*80)$ spell damage, causing the target to [Seal Rage] for 1 turn, consuming all [Rage] to increase self life-steal by 20% and critical damage by 30% for 2 turns. After activation, it reduces dual defense by 20% for 1 turn.',
		simDesc_vn = 'Đòn kết liễu: Super Rayquaza bay lên mây, đưa mục tiêu của kẻ địch lên trời, sau đó giải phóng sức mạnh của bầu trời để phong ấn cơn giận của mục tiêu; Đòn kết liễu cuối cùng: Sát thương chí mạng và tốc độ hút máu của sát thương này được tăng lên',
		simDesc_en = 'Finishing Move: Super Rayquaza soars into the clouds, lifting the enemy\'s target into the sky, then unleashes the power of the heavens to seal the target\'s fury; Final Finishing Move: Critical damage and lifesteal speed of this damage are increased.',
		simDesc_th = 'ท่าไม้ตาย: ซูเปอร์เรย์ควาซ่าบินขึ้นสู่เมฆ นำเป้าหมายของศัตรูขึ้นไปบนท้องฟ้า จากนั้นปลดปล่อยพลังแห่งสรวงสวรรค์เพื่อสาปโกรธของเป้าหมาย; ท่าไม้ตายขั้นสุดท้าย: ความเสียหายคริติคอลและความเร็วในการดูดเลือดจากความเสียหายนี้เพิ่มขึ้น',
		simDesc_in = 'Serangan Penyelesaian: Super Rayquaza terbang ke awan, mengangkat target musuh ke langit, kemudian melepaskan kekuatan langit untuk menyegel amarah target; Serangan Penyelesaian Terakhir: Kerusakan kritis dan kecepatan menyedot darah dari serangan ini meningkat.',
		simDesc_ph = 'Pangwakas na Atake: Ang Super Rayquaza ay lumilipad pataas sa mga ulap, itinaas ang target ng kalaban sa langit, pagkatapos ay pinapalabas ang kapangyarihan ng langit upang selyuhan ang galit ng target; Pangwakas na Huling Atake: Tumataas ang kritikal na pinsala at bilis ng pagdudugtong ng buhay mula sa atakeng ito.',
		simDesc_ma = 'Serangan Penamat: Super Rayquaza terbang ke awan, membawa sasaran musuh ke langit, kemudian melepaskan kekuatan langit untuk mengikat kemarahan sasaran; Serangan Penamat Terakhir: Kerosakan kritikal dan kelajuan menyedut darah daripada serangan ini meningkat.',
		simDesc = 'Finishing Move: Super Rayquaza soars into the clouds, lifting the enemy\'s target into the sky, then unleashes the power of the heavens to seal the target\'s fury; Final Finishing Move: Critical damage and lifesteal speed of this damage are increased.',
		starEffect = __data_t__starEffect[19823],
		-- {11}
		starEffectDesc_vn = 'Gây thêm sát thương chuẩn tương đương 50% tổng Công Vật Lý và Công Phép của bản thân lên mục tiêu (sát thương này có thể chí mạng và bỏ qua miễn nhiễm Công Vật Lý và miễn nhiễm phép).\n#F20# \n#F40##L10#Tuyệt kỹ Họa Long Điểm Tinh: #L0#Gây thêm sát thương chuẩn lên mục tiêu, tăng lên 100% tổng Công Vật Lý và Công Phép của bản thân (sát thương này có thể chí mạng và bỏ qua miễn nhiễm Công Vật Lý và miễn nhiễm phép).',
		starEffectDesc = 'Deals additional true damage equal to 50% of your total Physical Attack and Magic Attack to the target (this damage can critical hit and ignores Physical Resistance and Magic Resistance).\n#F20# \n#F40##L10#Dragon Mark Technique: #L0#Deals additional true damage to the target, increased to 100% of your total Physical Attack and Magic Attack (this damage can critical hit and ignores Physical Resistance and Magic Resistance).',
		starEffectDesc_en = 'Deals additional true damage equal to 50% of your total Physical Attack and Magic Attack to the target (this damage can critical hit and ignores Physical Resistance and Magic Resistance).\n#F20# \n#F40##L10#Dragon Mark Technique: #L0#Deals additional true damage to the target, increased to 100% of your total Physical Attack and Magic Attack (this damage can critical hit and ignores Physical Resistance and Magic Resistance).',
		starEffectDesc_th = 'ก่อความเสียหายจริงเพิ่มเติมเท่ากับ 50% ของพลังโจมตีทางกายภาพและพลังโจมตีเวททั้งหมดของตัวเองใส่เป้าหมาย (ความเสียหายนี้สามารถคริติคอลและละเว้นการต้านทานกายภาพและการต้านทานเวท).\n#F20# \n#F40##L10#เคล็ดวิชาหยกมังกร: #L0#ก่อความเสียหายจริงเพิ่มเติมใส่เป้าหมาย เพิ่มขึ้นเป็น 100% ของพลังโจมตีทางกายภาพและพลังโจมตีเวททั้งหมดของตัวเอง (ความเสียหายนี้สามารถคริติคอลและละเว้นการต้านทานกายภาพและการต้านทานเวท).',
		starEffectDesc_in = 'Memberikan tambahan damage murni sebesar 50% dari total Serangan Fisik dan Serangan Sihir milik sendiri ke target (damage ini dapat mengenai critical dan mengabaikan imun Serangan Fisik serta imun sihir).\n#F20# \n#F40##L10#Teknik Titik Naga: #L0#Memberikan tambahan damage murni ke target, meningkat menjadi 100% dari total Serangan Fisik dan Serangan Sihir milik sendiri (damage ini dapat mengenai critical dan mengabaikan imun Serangan Fisik serta imun sihir).',
		starEffectDesc_ph = 'Nagdudulot ng karagdagang tunay na pinsala nang katumbas ng 50% ng kabuuang Pisikal at Pangkamangha-manghang Atake ng sarili sa target (ang pinsalang ito ay maaaring maging kritikal at nilalampasan ang immunidad sa Pisikal at pangkampo).\n#F20# \n#F40##L10#Teknik ng Dragon Mark: #L0#Nagdudulot ng karagdagang tunay na pinsala sa target, tumataas sa 100% ng kabuuang Pisikal at Pangkamangha-manghang Atake ng sarili (ang pinsalang ito ay maaaring maging kritikal at nilalampasan ang immunidad sa Pisikal at pangkampo).',
		starEffectDesc_ma = 'Menyebabkan kerosakan sebenar tambahan bersamaan 50% jumlah Serangan Fizikal dan Serangan Sihir diri sendiri ke sasaran (kerosakan ini boleh kritikal dan mengabaikan imun Serangan Fizikal serta imun Sihir).\n#F20# \n#F40##L10#Teknik Titik Naga: #L0#Menyebabkan kerosakan sebenar tambahan ke sasaran, meningkat kepada 100% jumlah Serangan Fizikal dan Serangan Sihir diri sendiri (kerosakan ini boleh kritikal dan mengabaikan imun Serangan Fizikal serta imun Sihir).',
		zawakeEffect = __data_t__zawakeEffect[19823],
		-- {79003, 1}
		zawakeEffectDesc = '#L10#Finishing move: #L0# also absorbs 30% of the target\'s critical hits and 20% of dual attacks for 2 turns. When dodged, it immediately restores 4 anger points; it will deal an additional 40% of its total dual attacks to the target as true damage (this damage can be critical, ignores shields, and cannot be resisted by Magic Damage and Physical Damage) \n#F20# \n#F40##L10# Final finishing move: #L0# cannot receive counter damage. The third final finishing move comes with 10% continuous damage spread (damage spread does not exceed 200% of its total dual attacks); at the same time, it absorbs 30% of the target\'s critical hits and 20% of dual attacks. When dodged, <Flying to the clouds> immediately restores 4 anger points for itself; it will also deal 80% true damage of its total dual attacks twice to the target and the second time is halved (this damage can be critical, ignores shields, and bypasses immunity to Magic Damage and Physical Damage).',
		zawakeEffectDesc_en = '#L10#Finishing move: #L0# also absorbs 30% of the target\'s critical hits and 20% of dual attacks for 2 turns. When dodged, it immediately restores 4 anger points; it will deal an additional 40% of its total dual attacks to the target as true damage (this damage can be critical, ignores shields, and cannot be resisted by Magic Damage and Physical Damage) \n#F20# \n#F40##L10# Final finishing move: #L0# cannot receive counter damage. The third final finishing move comes with 10% continuous damage spread (damage spread does not exceed 200% of its total dual attacks); at the same time, it absorbs 30% of the target\'s critical hits and 20% of dual attacks. When dodged, <Flying to the clouds> immediately restores 4 anger points for itself; it will also deal 80% true damage of its total dual attacks twice to the target and the second time is halved (this damage can be critical, ignores shields, and bypasses immunity to Magic Damage and Physical Damage).',
		zawakeEffectDesc_th = '#L10#ท่าปิดฉาก: #L0# ยังดูดซับ 30% ของการโจมตีวิกฤติของเป้าหมายและ 20% ของการโจมตีคู่เป็นเวลา 2 เทิร์น เมื่อหลบหลีกจะฟื้นฟูความโกรธ 4 แต้มทันที; จะก่อให้เกิดความเสียหายเพิ่มเติม 40% ของการโจมตีคู่ทั้งหมดของตนเองแก่เป้าหมายในรูปแบบความเสียหายจริง (ความเสียหายนี้สามารถเป็นการโจมตีวิกฤติ, ข้ามโล่และไม่อาจถูกป้องกันด้วยความเสียหายเวทย์และความเสียหายกายภาพ) \n#F20# \n#F40##L10# ท่าปิดฉากสุดท้าย: #L0# ไม่สามารถได้รับความเสียหายตอบโต้ ท่าปิดฉากสุดท้ายครั้งที่สามมาพร้อมกับความเสียหายแพร่กระจายต่อเนื่อง 10% (ความเสียหายแพร่กระจายไม่เกิน 200% ของการโจมตีคู่ทั้งหมดของตนเอง); พร้อมกันนั้นดูดซับ 30% ของการโจมตีวิกฤติของเป้าหมายและ 20% ของการโจมตีคู่ เมื่อถูกหลบหลีก, <บินสู่เมฆ> จะฟื้นฟูความโกรธ 4 แต้มให้ตัวเองทันที; จะก่อให้เกิดความเสียหายจริง 80% ของการโจมตีคู่ทั้งหมดของตนเอง 2 ครั้งแก่เป้าหมายและครั้งที่สองจะลดลงครึ่งหนึ่ง (ความเสียหายนี้สามารถเป็นการโจมตีวิกฤติ, ข้ามโล่และข้ามภูมิคุ้มกันความเสียหายเวทย์และความเสียหายกายภาพ).',
		zawakeEffectDesc_in = '#L10#Gerakan penuntasan: #L0# juga menyerap 30% serangan kritis target dan 20% serangan ganda selama 2 giliran. Saat menghindar, segera memulihkan 4 poin kemarahan; akan memberikan tambahan 40% dari total serangan gandanya kepada target sebagai kerusakan sebenarnya (kerusakan ini bisa kritis, mengabaikan perisai, dan tidak dapat diabaikan oleh Kerusakan Sihir dan Kerusakan Fisik) \n#F20# \n#F40##L10# Gerakan penuntasan akhir: #L0# tidak dapat menerima kerusakan balasan. Kali ketiga gerakan penuntasan akhir membawa 10% kerusakan berantai (kerusakan menyebar tidak melebihi 200% dari total serangan gandanya); bersamaan itu menyerap 30% serangan kritis target dan 20% serangan ganda. Saat menghindar, <Terbang ke awan> segera memulihkan 4 poin kemarahan untuk dirinya sendiri; juga akan menyebabkan 80% kerusakan nyata dari total serangan gandanya dalam 2 kali berturut-turut ke target dan kali kedua berkurang separuh (kerusakan ini bisa kritis, mengabaikan perisai, dan mengabaikan kekebalan terhadap Kerusakan Sihir dan Kerusakan Fisik).',
		zawakeEffectDesc_ph = '#L10#Pangwakas na atake: #L0# ay humihigop din ng 30% ng kritikal na dagok ng target at 20% ng dobleng atake sa loob ng 2 na turn. Kapag naiiwasan, agad nitong pinapanumbalik ang 4 puntos ng galit; magdudulot ito ng karagdagang 40% ng kabuuang dobleng atake nito sa target bilang tunay na pinsala (ang pinsalang ito ay maaaring kritikal, nilalampasan ang mga panangga, at hindi maaaring iwasan ng mga Pinsalang Magic at Pisikal) \n#F20# \n#F40##L10# Pangwakas na huling atake: #L0# ay hindi maaaring tumanggap ng baliktarang pinsala. Ang pangatlong pangwakas na atake ay may kasamang 10% tuloy-tuloy na pagkalat ng pinsala (ang pagkalat ng pinsala ay hindi lalampas sa 200% ng kabuuang dobleng atake nito); kasabay nito ay humihigop ng 30% ng kritikal na dagok ng target at 20% ng dobleng atake. Kapag naiiwasan, <Lumilipad sa mga ulap> ay agad na pinapanumbalik ang 4 na puntos ng galit para sa sarili; magdudulot din ito ng 80% tunay na pinsala ng kabuuang dobleng atake nito ng dalawang beses sa target at ang pangalawang beses ay kalahati ang pinsala (ang pinsalang ito ay maaaring kritikal, nilalampasan ang mga panangga, at nilalampasan ang immunidad sa mga Pinsalang Magic at Pisikal).',
		zawakeEffectDesc_ma = '#L10#Serangan penamat: #L0# juga menyerap 30% serangan kritikal sasaran dan 20% serangan berganda selama 2 pusingan. Apabila mengelak, ia segera memulihkan 4 mata kemarahan; ia akan menyebabkan tambahan 40% jumlah serangan bergandanya ke sasaran sebagai kerosakan benar (kerosakan ini boleh menjadi kritikal, mengabaikan perisai, dan tidak boleh dilawan oleh Kerosakan Ajaib dan Kerosakan Fizikal) \n#F20# \n#F40##L10# Serangan penamat terakhir: #L0# tidak boleh menerima kerosakan balas. Serangan penamat terakhir kali ketiga datang dengan 10% kerosakan berantai (kerosakan berantai tidak melebihi 200% jumlah serangan berganda sendiri); pada masa yang sama menyerap 30% serangan kritikal sasaran dan 20% serangan berganda. Apabila mengelak, <Terbang ke awan> akan segera memulihkan 4 mata kemarahan untuk dirinya sendiri; ia juga akan menyebabkan 80% kerosakan benar daripada jumlah serangan bergandanya dalam 2 kali berturut-turut ke sasaran dan kali kedua dikurangkan separuh (kerosakan ini boleh menjadi kritikal, mengabaikan perisai dan mengabaikan imuniti terhadap Kerosakan Ajaib dan Kerosakan Fizikal).',
		zawakeEffectDesc_vn = '#L10#Đòn kết liễu: #L0# cũng hấp thụ 30% đòn chí mạng của mục tiêu và 20% đòn tấn công kép trong 2 hiệp. Khi né tránh sẽ lập tức khôi phục 4 điểm tức giận; nó sẽ gây thêm 40% tổng số đòn tấn công kép của chính nó lên mục tiêu dưới dạng sát thương chuẩn (sát thương này có thể là đòn chí mạng, bỏ qua lá chắn và không có khả năng miễn nhiễm với các Sát Thương Phép Thuật và Sát Thương Vật Lý) \n#F20# \n#F40##L10# Đòn kết liễu cuối cùng: #L0# không thể nhận sát thương phản hồi. Lần kết liễu cuối cùng thứ ba đi kèm với 10% sát thương lan liên tiếp (sát thương lan không vượt quá 200% tổng số đòn tấn công kép của chính mình); đồng thời hấp thụ 30% đòn chí mạng của mục tiêu và 20% đòn tấn công kép. Khi bị né tránh, <Bay lên mây> sẽ lập tức khôi phục 4 điểm tức giận cho chính nó; nó cũng sẽ gây ra 80% sát thương thực sự của tổng đòn tấn công kép của chính nó trong 2 lần liên tiếp lên mục tiêu và lần thứ hai sẽ giảm đi một nửa (sát thương này có thể là đòn chí mạng, bỏ qua lá chắn và bỏ qua khả năng miễn nhiễm với các Sát Thương Phép Thuật và Sát Thương Vật Lý).',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Finishing moves steal 30% Crit Damage and 20% Double Attack from the target for 2 rounds. If dodged, user regains 4 Rage. Finishing moves: immune to counterattacks. The third final strike includes 10% splash damage (up to 200% of total Double Attack); post-ultimate true damage bypasses shields, and ultimate true damage can be triggered again (at half value) at 11 stars',
		zawakeSimpleDesc_en = '#C0x5c9970#Finishing moves steal 30% Crit Damage and 20% Double Attack from the target for 2 rounds. If dodged, user regains 4 Rage. Finishing moves: immune to counterattacks. The third final strike includes 10% splash damage (up to 200% of total Double Attack); post-ultimate true damage bypasses shields, and ultimate true damage can be triggered again (at half value) at 11 stars',
		zawakeSimpleDesc_th = '#C0x5c9970#การโจมตีปิดฉากจะขโมย 30% ความเสียหายคริติคอล และ 20% โจมตีสองครั้งจากเป้าหมายใน 2 เทิร์น หากหลบได้จะฟื้น 4 ความโกรธ โจมตีปิดฉากจะไม่โดนโต้กลับ การโจมตีปิดฉากรอบที่ 3 จะมีดาเมจกระจาย 10% (ไม่เกิน 200% โจมตีสองครั้งทั้งหมดของตัวเอง); ความเสียหายจริงหลังสกิลไม้ตายจะละเว้นโล่ และสามารถกระตุ้นได้อีกครั้ง (ดาเมจลดครึ่งหนึ่ง)',
		zawakeSimpleDesc_in = '#C0x5c9970#Serangan penyelesaian mencuri 30% Crit Damage dan 20% Serangan Ganda dari target selama 2 giliran. Jika menghindar, memulihkan 4 Rage. Serangan penyelesaian: tidak menerima serangan balik. Serangan penyelesaian ketiga memberikan 10% damage sebar (maks 200% Serangan Ganda total); damage asli setelah ultimate mengabaikan perisai, dan dapat diaktifkan ulang dengan damage setengah (bintang 11)',
		zawakeSimpleDesc_ph = '#C0x5c9970#Ang finishing move ay magnanakaw ng 30% Crit Damage at 20% Double Attack ng target sa loob ng 2 round. Kapag naiwasan, makakakuha ng 4 Rage. Ang finishing move ay immune sa counter. Sa ikatlong finishing move, may 10% AoE damage (max 200% ng total Double Attack); Ang tunay na pinsala pagkatapos ng ultimate ay binabalewala ang shield, at maaaring maulit muli sa kalahating lakas (11-star)',
		zawakeSimpleDesc_ma = '#C0x5c9970#Serangan penamat akan mencuri 30% Kerosakan Kritikal dan 20% Serangan Berganda daripada sasaran selama 2 pusingan. Jika dielak, memulihkan 4 Kemarahan. Serangan penamat: kebal kepada serangan balas. Serangan penamat ketiga memberikan 10% kerosakan percikan (maksimum 200% daripada jumlah Serangan Berganda); kerosakan sebenar selepas skill ultimate akan mengabaikan perisai dan boleh dicetuskan semula (dengan separuh kerosakan) pada tahap 11 bintang',
		zawakeSimpleDesc_vn = '#C0x5c9970# Đòn kết liễu và đòn kết liễu làm trung gian cho trái tim đấu tranh của mục tiêu và hấp thụ 30% sát thương chí mạng và 20% đòn tấn công kép của mục tiêu trong 2 hiệp. Đòn kết liễu hoặc đòn kết thúc tự phục hồi 4 điểm tức giận khi né đòn kết liễu hoặc đòn kết liễu; đòn kết liễu: sẽ không nhận sát thương phản hồi. Lần kết liễu cuối cùng thứ ba đi kèm với 10% sát thương lan hàng (sát thương lan không vượt quá 200% tổng số đòn tấn công kép của chính mình); sát thương thực sự gây ra sau chiêu thức đặc biệt sẽ bỏ qua lá chắn và sát thương thực sự kèm theo khi sử dụng chiêu cuối có thể được kích hoạt một lần nữa và sát thương giảm một nửa (11 sao)',
		upLvDesc = 'Fixed damage +320',
		upLvDesc_en = 'Fixed damage +320',
		upLvDesc_th = 'ความเสียหายคงที่ +320',
		upLvDesc_in = 'Kerusakan tetap +320',
		upLvDesc_ph = 'Tiyak na pinsala +320',
		upLvDesc_ma = 'Kerosakan tetap +320',
		upLvDesc_vn = 'Sát thương cố định +320',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
