		skillName = 'Red Dragon\'s Wrath',
		describe_vn = 'Super Rayquaza phóng Hơi thở rồng trời đỏ thẫm vào một mục tiêu kẻ địch, gây ra #C0xE69900#50% Sát Thương Vật Lý#C0x5B545B#+#C0x3D8A99#50% tấn Công Phép thuật#C0x5B54 5B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, tăng gấp đôi của bản thân tấn công 40% và tốc độ 20%, kéo dài 2 hiệp',
		describe_en = 'Super Rayquaza unleashes a deep red Dragon Breath onto an enemy target, dealing #C0xE69900#50% Physical Damage#C0x5B545B#+#C0x3D8A99#50% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magic Damage#C0x5B545B#, doubling own Attack by 40% and Speed by 20%, lasting 2 turns.',
		describe_th = 'ซูเปอร์เรย์ควาซาปล่อยลมหายใจมังกรสีแดงเข้มใส่เป้าหมายศัตรู สร้างความเสียหาย #C0xE69900#50% ความเสียหายกายภาพ#C0x5B545B#+#C0x3D8A99#50% การโจมตีเวท#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายเวท#C0x5B545B# เพิ่มพลังโจมตีตัวเอง 40% และความเร็ว 20% เป็นเวลา 2 เทิร์น',
		describe_in = 'Super Rayquaza melepaskan Nafas Naga merah tua pada satu target musuh, menyebabkan #C0xE69900#50% Damage Fisik#C0x5B545B#+#C0x3D8A99#50% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Damage Sihir#C0x5B545B#, meningkatkan Serangan sendiri sebesar 40% dan Kecepatan sebesar 20%, berlangsung selama 2 giliran.',
		describe_ph = 'Super Rayquaza ay nagpapalabas ng malalim na pulang Dragon Breath sa isang kaaway na target, na nagdudulot ng #C0xE69900#50% Physical Damage#C0x5B545B#+#C0x3D8A99#50% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magic Damage#C0x5B545B#, pinapatdoble ang sariling Attack ng 40% at Speed ng 20%, tumatagal ng 2 turn.',
		describe_ma = 'Super Rayquaza melepaskan Nafas Naga merah gelap ke sasaran musuh, menyebabkan #C0xE69900#50% Kerosakan Fizikal#C0x5B545B#+#C0x3D8A99#50% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerosakan Sihir#C0x5B545B#, meningkatkan Serangan sendiri sebanyak 40% dan Kelajuan sebanyak 20%, bertahan selama 2 pusingan.',
		describe = 'Super Rayquaza unleashes a deep red Dragon Breath onto an enemy target, dealing #C0xE69900#50% Physical Damage#C0x5B545B#+#C0x3D8A99#50% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magic Damage#C0x5B545B#, doubling own Attack by 40% and Speed by 20%, lasting 2 turns.',
		zawakeEffect = __data_t__zawakeEffect[19841],
		-- {79001}
		zawakeEffectDesc = 'Super Rayquaza unleashes #C0xE69900#50% Physical Damage#C0x5B545B#+#C0x3D8A99#50% Magic Attack#C0x5B545B#+$(skillLevel* 4*24)$ of #C0xF13B54# Magic Damage#C0x5B545B# breath of deep red dragon breath onto a single enemy target, increasing the dual attack of one person by 40% and attack speed by 20% for 2 turns; also increases own critical damage by 10% and critical damage by 15%, lasting 2 turns and can stack up to 2 layers.',
		zawakeEffectDesc_en = 'Super Rayquaza unleashes #C0xE69900#50% Physical Damage#C0x5B545B#+#C0x3D8A99#50% Magic Attack#C0x5B545B#+$(skillLevel* 4*24)$ of #C0xF13B54# Magic Damage#C0x5B545B# breath of deep red dragon breath onto a single enemy target, increasing the dual attack of one person by 40% and attack speed by 20% for 2 turns; also increases own critical damage by 10% and critical damage by 15%, lasting 2 turns and can stack up to 2 layers.',
		zawakeEffectDesc_th = 'Super Rayquaza ปล่อย #C0xE69900#50% ความเสียหายทางกายภาพ#C0x5B545B#+#C0x3D8A99#50% การโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel* 4*24)$ ของ #C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# ด้วยลมหายใจมังกรสีแดงเข้มใส่เป้าหมายศัตรูหนึ่งตัว เพิ่มการโจมตีคู่ของผู้เล่นหนึ่งคนขึ้น 40% และความเร็วโจมตีขึ้น 20% เป็นเวลา 2 เทิร์น นอกจากนี้ยังเพิ่มความเสียหายคริติคอลของตนเอง 10% และความเสียหายคริติคอล 15% อยู่เป็นเวลา 2 เทิร์นและสามารถซ้อนกันได้สูงสุด 2 ชั้น',
		zawakeEffectDesc_in = 'Super Rayquaza melepaskan #C0xE69900#50% Kerusakan Fisik#C0x5B545B#+#C0x3D8A99#50% Serangan Sulap#C0x5B545B#+$(skillLevel* 4*24)$ dari #C0xF13B54# Kerusakan Sulap#C0x5B545B# napas naga merah tua ke satu target musuh, meningkatkan serangan ganda satu orang sebesar 40% dan kecepatan serangan sebesar 20% selama 2 giliran; juga meningkatkan kerusakan kritis sendiri sebesar 10% dan kerusakan kritis sebesar 15%, bertahan selama 2 giliran dan dapat bertumpuk hingga 2 lapisan.',
		zawakeEffectDesc_ph = 'Super Rayquaza ay nagpapalabas ng #C0xE69900#50% Pisikal na Pinsala#C0x5B545B#+#C0x3D8A99#50% Magic na Atake#C0x5B545B#+$(skillLevel* 4*24)$ ng #C0xF13B54# Magic na Pinsala#C0x5B545B# ng malalim na pulang dragon breath sa isang target na kalaban, nagpapataas ng doble na pag-atake ng isang tao ng 40% at bilis ng pag-atake ng 20% sa loob ng 2 mga turn; dagdag pa, pinapataas ang sariling critical damage ng 10% at critical damage ng 15%, tumatagal ng 2 mga turn at maaaring mag-stack hanggang 2 layer.',
		zawakeEffectDesc_ma = 'Super Rayquaza mengeluarkan #C0xE69900#50% Kerosakan Fizikal#C0x5B545B#+#C0x3D8A99#50% Serangan Sihir#C0x5B545B#+$(skillLevel* 4*24)$ daripada #C0xF13B54# Kerosakan Sihir#C0x5B545B# nafas naga merah tua ke satu sasaran musuh, meningkatkan serangan berganda seorang individu sebanyak 40% dan kelajuan serangan sebanyak 20% selama 2 giliran; juga meningkatkan kerosakan kritikal sendiri sebanyak 10% dan kerosakan kritikal sebanyak 15%, kekal selama 2 giliran dan boleh bertindih sehingga 2 lapisan.',
		zawakeEffectDesc_vn = 'Super Rayquaza phóng Hơi thở rồng đỏ thẫm vào một mục tiêu kẻ thù, gây ra #C0xE69900#50% Sát Thương Vật Lý#C0x5B545B#+#C0x3D8A99#50% tấn Công Phép thuật#C0x5B545B#+$(skillLevel* 4*24)$ của #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, tăng lên đòn tấn công kép của một người tăng 40% và tốc độ tăng 20%, kéo dài trong 2 hiệp; ngoài ra còn tăng 10% sát thương chí mạng của bản thân và 15% sát thương chí mạng, tồn tại trong 2 lượt và có thể xếp chồng lên nhau thành 2 lớp.',
