	[19843] = {
		id = 19843,
		skillName_vn = 'Điểm nhấn rồng',
		skillName_en = 'Dragon highlight',
		skillName_th = 'ไฮไลต์มังกร',
		skillName_in = 'Sorotan naga',
		skillName_ph = 'Dragon highlight',
		skillName_ma = 'Sorotan naga',
		skillName = 'Dragon highlight',
		describe_vn = '#L10#Đòn kết liễu: #L0#Super Rayquaza bay lên mây, đưa các mục tiêu dàn trận của kẻ địch lên trời rồi giải phóng sức mạnh của bầu trời, gây ra #C0xE69900#180% đòn Sát Thương Vật Lý#C0x5B545B#+#C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B54 5B#+$(skillLevel*4*80)$#C0xF13B54#spel Damage#C0x5B545B#, Rayquaza làm trung gian tinh thần chiến đấu của mục tiêu, khiến mục tiêu [Seal Rage] trong 1 hiệp (Seal Rage: hiệu ứng tiêu cực, không thể xua tan và Rage không thể phục hồi trong khoảng thời gian này)\n#F20# \n#F40##L10# Cú chạm cuối cùng: #L0# Super Rayquaza bay lên mây, đưa mục tiêu của kẻ địch lên trời rồi giải phóng sức mạnh của bầu trời, gây ra #C0xE69900#200% Sát Thương Vật Lý#C0x5B545B#+#C0x3D8A99#200% tấn công ma thuật#C0x5B5 45B#+$(skillLevel*4*80)$#C0xF13B54#spell sát thương#C0x5B545B# khiến mục tiêu [Seal Rage] trong 1 lượt, tiêu thụ toàn bộ [Rage] để tăng khả năng hút máu của bản thân thêm 20% và 30% sát thương chí mạng trong 2 lượt. Sau khi kích hoạt, nó sẽ giảm 20% khả năng phòng thủ kép trong 1 lượt.',
		describe_en = 'Finish Move: Super Rayquaza soars into the clouds, lifting the enemy\'s formation targets into the sky and unleashing the power of the heavens, dealing 180% Physical Damage + 180% Magic Damage + $(skillLevel*4*80)$ spell Damage. Rayquaza acts as a conduit for the target\'s fighting spirit, causing the target to [Seal Rage] for 1 turn (Seal Rage: a negative effect that cannot be dispelled and Rage cannot be recovered during this time). \n // Final Touch: Super Rayquaza soars into the clouds, lifting the enemy\'s target into the sky and unleashing the power of the heavens, dealing 200% Physical Damage + 200% Magic Attack + $(skillLevel*4*80)$ spell damage, causing the target to [Seal Rage] for 1 turn, consuming all [Rage] to increase self lifesteal by 20% and critical damage by 30% for 2 turns. After activation, it reduces the target\'s dual defense by 20% for 1 turn.',
		describe_th = 'ท่าตัดสิน: Super Rayquaza บินขึ้นสู่ท้องฟ้า นำเป้าหมายในแนวของศัตรูขึ้นสู่ฟ้าแล้วปลดปล่อยพลังแห่งท้องฟ้า สร้างความเสียหายทางกายภาพ 180% + ความเสียหายเวทมนตร์ 180% + $(skillLevel*4*80)$ ความเสียหายเวทมนตร์ Rayquaza ทำหน้าที่เป็นสื่อกลางจิตวิญญาณการต่อสู้ของเป้าหมาย ทำให้เป้าหมายติดสถานะ [Seal Rage] เป็นเวลา 1 เทิร์น (Seal Rage: ภาวะติดลบ ไม่สามารถกำจัดสถานะและไม่สามารถฟื้นฟูโกรธได้ในช่วงเวลานี้) \n // สัมผัสสุดท้าย: Super Rayquaza บินขึ้นสู่เมฆ นำเป้าหมายของศัตรูขึ้นฟ้าแล้วปลดปล่อยพลังแห่งท้องฟ้า สร้างความเสียหายทางกายภาพ 200% + การโจมตีเวทมนตร์ 200% + $(skillLevel*4*80)$ ความเสียหายเวทมนตร์ ทำให้เป้าหมายติดสถานะ [Seal Rage] เป็นเวลา 1 เทิร์น ใช้โกรธทั้งหมดเพื่อเพิ่มการดูดเลือดของตนเอง 20% และพลังโจมตีคริติคอล 30% เป็นเวลา 2 เทิร์น หลังเปิดใช้จะลดการป้องกันคู่ของเป้าหมาย 20% เป็นเวลา 1 เทิร์น',
		describe_in = 'Serangan Penyelesaian: Super Rayquaza terbang ke awan, mengangkat target barisan musuh ke langit lalu melepaskan kekuatan langit, memberikan 180% Kerusakan Fisik + 180% Kerusakan Sihir + $(skillLevel*4*80)$ kerusakan sihir. Rayquaza menjadi perantara semangat bertarung target, membuat target terkena efek [Seal Rage] selama 1 giliran (Seal Rage: efek negatif, tidak dapat dihapus dan Rage tidak bisa pulih selama periode ini). \n // Sentuhan Terakhir: Super Rayquaza terbang ke awan, mengangkat target musuh ke langit lalu melepaskan kekuatan langit, memberikan 200% Kerusakan Fisik + 200% Serangan Sihir + $(skillLevel*4*80)$ kerusakan sihir, menyebabkan target terkena [Seal Rage] selama 1 giliran, menghabiskan semua [Rage] untuk meningkatkan penyedotan darah diri sendiri sebanyak 20% dan kerusakan kritis sebesar 30% selama 2 giliran. Setelah aktif, akan mengurangi pertahanan ganda target sebesar 20% selama 1 giliran.',
		describe_ph = 'Pangwakas na Atake: Lumilipad ang Super Rayquaza sa ulap, iniaangat ang mga target na pahalang ng kalaban sa langit at pinakakawalan ang kapangyarihan ng langit, na nagdudulot ng 180% Pisikal na Pinsala + 180% Mahiwagang Pinsala + $(skillLevel*4*80)$ pinsalang mahiwaga. Ginagamit ni Rayquaza ang espiritu ng pakikipaglaban ng target, kaya ang target ay nagkakaroon ng [Seal Rage] sa loob ng 1 turno (Seal Rage: negatibong epekto, hindi maaaring alisin at hindi makakabawi ng Rage sa panahong ito). \n // Huling Dampot: Lumilipad ang Super Rayquaza sa ulap, iniaangat ang target ng kalaban sa langit at pinakakawalan ang kapangyarihan ng langit, na nagdudulot ng 200% Pisikal na Pinsala + 200% Mahiwagang Atake + $(skillLevel*4*80)$ pinsalang mahiwaga, pinapailalim ang target sa [Seal Rage] sa loob ng 1 turno, ginagamit ang lahat ng [Rage] upang dagdagan ang sariling lifesteal ng 20% at critical damage ng 30% sa loob ng 2 turno. Pagkatapos ma-activate, babawasan nito ang dobleng depensa ng target ng 20% sa loob ng 1 turno.',
		describe_ma = 'Serangan Penamat: Super Rayquaza terbang ke awan, mengangkat sasaran barisan musuh ke langit kemudian melepaskan kuasa langit, menyebabkan 180% Kerosakan Fizikal + 180% Kerosakan Sihir + $(skillLevel*4*80)$ kerosakan sihir. Rayquaza bertindak sebagai perantara semangat bertempur sasaran, menyebabkan sasaran [Seal Rage] selama 1 giliran (Seal Rage: kesan negatif yang tidak boleh dihilangkan dan Rage tidak boleh pulih dalam tempoh ini). \n // Sentuhan Terakhir: Super Rayquaza terbang ke awan, mengangkat sasaran musuh ke langit dan melepaskan kuasa langit, menyebabkan 200% Kerosakan Fizikal + 200% Serangan Sihir + $(skillLevel*4*80)$ kerosakan sihir, menyebabkan sasaran [Seal Rage] selama 1 giliran, menggunakan semua [Rage] untuk meningkatkan penyerapan darah sendiri sebanyak 20% dan kerosakan kritikal sebanyak 30% selama 2 giliran. Selepas diaktifkan, ia akan mengurangkan pertahanan dwi sasaran sebanyak 20% selama 1 giliran.',
		describe = 'Finish Move: Super Rayquaza soars into the clouds, lifting the enemy\'s formation targets into the sky and unleashing the power of the heavens, dealing 180% Physical Damage + 180% Magic Damage + $(skillLevel*4*80)$ spell Damage. Rayquaza acts as a conduit for the target\'s fighting spirit, causing the target to [Seal Rage] for 1 turn (Seal Rage: a negative effect that cannot be dispelled and Rage cannot be recovered during this time). \n // Final Touch: Super Rayquaza soars into the clouds, lifting the enemy\'s target into the sky and unleashing the power of the heavens, dealing 200% Physical Damage + 200% Magic Attack + $(skillLevel*4*80)$ spell damage, causing the target to [Seal Rage] for 1 turn, consuming all [Rage] to increase self lifesteal by 20% and critical damage by 30% for 2 turns. After activation, it reduces the target\'s dual defense by 20% for 1 turn.',
		simDesc_vn = 'Đòn kết liễu: Super Rayquaza bay lên mây, đưa mục tiêu của kẻ địch lên trời, sau đó giải phóng sức mạnh của bầu trời để phong ấn cơn giận của mục tiêu; Đòn kết liễu cuối cùng: Sát thương chí mạng và tốc độ hút máu của sát thương này được tăng lên',
		simDesc_en = 'Finishing move: Super Rayquaza flies into the clouds, lifting the enemy\'s target into the sky, then unleashes the power of the heavens to seal the target\'s fury; Ultimate finishing move: Critical damage and life steal speed of this damage are increased',
		simDesc_th = 'ท่าฟันธง: Super Rayquaza บินขึ้นสู่เมฆ นำเป้าหมายของศัตรูขึ้นฟ้า จากนั้นปลดปล่อยพลังแห่งท้องฟ้าเพื่อผนึกความโกรธของเป้าหมาย; ท่าสุดท้าย: ความเสียหายคริติคอลและความเร็วในการดูดเลือดจากความเสียหายนี้จะเพิ่มขึ้น',
		simDesc_in = 'Serangan penyelesaian: Super Rayquaza terbang ke awan, mengangkat target musuh ke langit, lalu melepaskan kekuatan langit untuk menyegel amarah target; Serangan penyelesaian terakhir: Kerusakan kritis dan kecepatan pencurian darah dari kerusakan ini meningkat',
		simDesc_ph = 'Panghuling suntok: Lumilipad ang Super Rayquaza sa mga ulap, iniaangat ang target ng kalaban sa kalangitan, pagkatapos ay pinakakawalan ang kapangyarihan ng langit upang selyuhan ang galit ng target; Panghuling panghuli na suntok: Tumaas ang kritikal na pinsala at bilis ng life steal ng pinsalang ito',
		simDesc_ma = 'Serangan penyudah: Super Rayquaza terbang ke awan, mengangkat sasaran musuh ke langit, kemudian melepaskan kuasa langit untuk menyegel kemarahan sasaran; Serangan penyudah terakhir: Kerosakan kritikal dan kelajuan sedutan darah daripada kerosakan ini meningkat',
		simDesc = 'Finishing move: Super Rayquaza flies into the clouds, lifting the enemy\'s target into the sky, then unleashes the power of the heavens to seal the target\'s fury; Ultimate finishing move: Critical damage and life steal speed of this damage are increased',
		starEffect = __data_t__starEffect[19843],
		-- {11}
		starEffectDesc_vn = 'Gây thêm sát thương chuẩn tương đương 50% tổng Công Vật Lý và Công Phép của bản thân lên mục tiêu (sát thương này có thể chí mạng và bỏ qua miễn nhiễm Công Vật Lý và miễn nhiễm Công Phép).\n#F20#\n#F40##L10#Tuyệt kỹ Họa Long Điểm Tinh: #L0#Tăng sát thương chuẩn gây thêm lên mục tiêu thành 100% tổng Công Vật Lý và Công Phép của bản thân (sát thương này có thể chí mạng và bỏ qua miễn nhiễm Công Vật Lý và miễn nhiễm Công Phép).',
		starEffectDesc = 'Deal additional true damage equal to 50% of own total Physical Attack and Magic Attack to the target (this damage can critically strike and ignores Physical Resistance and Magic Resistance).\n#F20#\n#F40##L10#Hoa Long Dian Tinh Skill: #L0#Increase additional true damage dealt to the target to 100% of own total Physical Attack and Magic Attack (this damage can critically strike and and ignores Physical Resistance and Magic Resistance).',
		starEffectDesc_en = 'Deal additional true damage equal to 50% of own total Physical Attack and Magic Attack to the target (this damage can critically strike and ignores Physical Resistance and Magic Resistance).\n#F20#\n#F40##L10#Hoa Long Dian Tinh Skill: #L0#Increase additional true damage dealt to the target to 100% of own total Physical Attack and Magic Attack (this damage can critically strike and and ignores Physical Resistance and Magic Resistance).',
		starEffectDesc_th = 'Deal additional true damage equal to 50% of own total Physical Attack and Magic Attack to the target (this damage can critically strike and ignores Physical Resistance and Magic Resistance).\n#F20#\n#F40##L10#Hoa Long Dian Tinh Skill: #L0#Increase additional true damage dealt to the target to 100% of own total Physical Attack and Magic Attack (this damage can critically strike and and ignores Physical Resistance and Magic Resistance).',
		starEffectDesc_in = 'Deal additional true damage equal to 50% of own total Physical Attack and Magic Attack to the target (this damage can critically strike and ignores Physical Resistance and Magic Resistance).\n#F20#\n#F40##L10#Hoa Long Dian Tinh Skill: #L0#Increase additional true damage dealt to the target to 100% of own total Physical Attack and Magic Attack (this damage can critically strike and and ignores Physical Resistance and Magic Resistance).',
		starEffectDesc_ph = 'Deal additional true damage equal to 50% of own total Physical Attack and Magic Attack to the target (this damage can critically strike and ignores Physical Resistance and Magic Resistance).\n#F20#\n#F40##L10#Hoa Long Dian Tinh Skill: #L0#Increase additional true damage dealt to the target to 100% of own total Physical Attack and Magic Attack (this damage can critically strike and and ignores Physical Resistance and Magic Resistance).',
		starEffectDesc_ma = 'Deal additional true damage equal to 50% of own total Physical Attack and Magic Attack to the target (this damage can critically strike and ignores Physical Resistance and Magic Resistance).\n#F20#\n#F40##L10#Hoa Long Dian Tinh Skill: #L0#Increase additional true damage dealt to the target to 100% of own total Physical Attack and Magic Attack (this damage can critically strike and and ignores Physical Resistance and Magic Resistance).',
		zawakeEffect = __data_t__zawakeEffect[19843],
		-- {79003, 1}
		zawakeEffectDesc = '#L10#Finishing move: #L0# also absorbs 30% of the target\'s critical hits and 20% of dual attacks for 2 turns. When dodged, it immediately restores 4 anger points; it will deal an additional 40% of its total dual attacks to the target as true damage (this damage can be critical, ignores shields, and cannot be resisted by Magic Damage and Physical Damage) \n#F20# \n#F40##L10# Final finishing move: #L0# cannot receive counter damage. The third final finishing move comes with 10% continuous damage spread (damage spread does not exceed 200% of its total dual attacks); at the same time, it absorbs 30% of the target\'s critical hits and 20% of dual attacks. When dodged, <Flying to the clouds> immediately restores 4 anger points for itself; it will also deal 80% true damage of its total dual attacks twice to the target and the second time is halved (this damage can be critical, ignores shields, and bypasses immunity to Magic Damage and Physical Damage).',
		zawakeEffectDesc_en = '#L10#Finishing move: #L0# also absorbs 30% of the target\'s critical hits and 20% of dual attacks for 2 turns. When dodged, it immediately restores 4 anger points; it will deal an additional 40% of its total dual attacks to the target as true damage (this damage can be critical, ignores shields, and cannot be resisted by Magic Damage and Physical Damage) \n#F20# \n#F40##L10# Final finishing move: #L0# cannot receive counter damage. The third final finishing move comes with 10% continuous damage spread (damage spread does not exceed 200% of its total dual attacks); at the same time, it absorbs 30% of the target\'s critical hits and 20% of dual attacks. When dodged, <Flying to the clouds> immediately restores 4 anger points for itself; it will also deal 80% true damage of its total dual attacks twice to the target and the second time is halved (this damage can be critical, ignores shields, and bypasses immunity to Magic Damage and Physical Damage).',
		zawakeEffectDesc_th = '#L10#ท่าปิดฉาก: #L0# ยังดูดซับ 30% ของการโจมตีวิกฤติของเป้าหมายและ 20% ของการโจมตีคู่เป็นเวลา 2 เทิร์น เมื่อหลบหลีกจะฟื้นฟูความโกรธ 4 แต้มทันที; จะก่อให้เกิดความเสียหายเพิ่มเติม 40% ของการโจมตีคู่ทั้งหมดของตนเองแก่เป้าหมายในรูปแบบความเสียหายจริง (ความเสียหายนี้สามารถเป็นการโจมตีวิกฤติ, ข้ามโล่และไม่อาจถูกป้องกันด้วยความเสียหายเวทย์และความเสียหายกายภาพ) \n#F20# \n#F40##L10# ท่าปิดฉากสุดท้าย: #L0# ไม่สามารถได้รับความเสียหายตอบโต้ ท่าปิดฉากสุดท้ายครั้งที่สามมาพร้อมกับความเสียหายแพร่กระจายต่อเนื่อง 10% (ความเสียหายแพร่กระจายไม่เกิน 200% ของการโจมตีคู่ทั้งหมดของตนเอง); พร้อมกันนั้นดูดซับ 30% ของการโจมตีวิกฤติของเป้าหมายและ 20% ของการโจมตีคู่ เมื่อถูกหลบหลีก, <บินสู่เมฆ> จะฟื้นฟูความโกรธ 4 แต้มให้ตัวเองทันที; จะก่อให้เกิดความเสียหายจริง 80% ของการโจมตีคู่ทั้งหมดของตนเอง 2 ครั้งแก่เป้าหมายและครั้งที่สองจะลดลงครึ่งหนึ่ง (ความเสียหายนี้สามารถเป็นการโจมตีวิกฤติ, ข้ามโล่และข้ามภูมิคุ้มกันความเสียหายเวทย์และความเสียหายกายภาพ).',
		zawakeEffectDesc_in = '#L10#Gerakan penuntasan: #L0# juga menyerap 30% serangan kritis target dan 20% serangan ganda selama 2 giliran. Saat menghindar, segera memulihkan 4 poin kemarahan; akan memberikan tambahan 40% dari total serangan gandanya kepada target sebagai kerusakan sebenarnya (kerusakan ini bisa kritis, mengabaikan perisai, dan tidak dapat diabaikan oleh Kerusakan Sihir dan Kerusakan Fisik) \n#F20# \n#F40##L10# Gerakan penuntasan akhir: #L0# tidak dapat menerima kerusakan balasan. Kali ketiga gerakan penuntasan akhir membawa 10% kerusakan berantai (kerusakan menyebar tidak melebihi 200% dari total serangan gandanya); bersamaan itu menyerap 30% serangan kritis target dan 20% serangan ganda. Saat menghindar, <Terbang ke awan> segera memulihkan 4 poin kemarahan untuk dirinya sendiri; juga akan menyebabkan 80% kerusakan nyata dari total serangan gandanya dalam 2 kali berturut-turut ke target dan kali kedua berkurang separuh (kerusakan ini bisa kritis, mengabaikan perisai, dan mengabaikan kekebalan terhadap Kerusakan Sihir dan Kerusakan Fisik).',
		zawakeEffectDesc_ph = '#L10#Pangwakas na atake: #L0# ay humihigop din ng 30% ng kritikal na dagok ng target at 20% ng dobleng atake sa loob ng 2 na turn. Kapag naiiwasan, agad nitong pinapanumbalik ang 4 puntos ng galit; magdudulot ito ng karagdagang 40% ng kabuuang dobleng atake nito sa target bilang tunay na pinsala (ang pinsalang ito ay maaaring kritikal, nilalampasan ang mga panangga, at hindi maaaring iwasan ng mga Pinsalang Magic at Pisikal) \n#F20# \n#F40##L10# Pangwakas na huling atake: #L0# ay hindi maaaring tumanggap ng baliktarang pinsala. Ang pangatlong pangwakas na atake ay may kasamang 10% tuloy-tuloy na pagkalat ng pinsala (ang pagkalat ng pinsala ay hindi lalampas sa 200% ng kabuuang dobleng atake nito); kasabay nito ay humihigop ng 30% ng kritikal na dagok ng target at 20% ng dobleng atake. Kapag naiiwasan, <Lumilipad sa mga ulap> ay agad na pinapanumbalik ang 4 na puntos ng galit para sa sarili; magdudulot din ito ng 80% tunay na pinsala ng kabuuang dobleng atake nito ng dalawang beses sa target at ang pangalawang beses ay kalahati ang pinsala (ang pinsalang ito ay maaaring kritikal, nilalampasan ang mga panangga, at nilalampasan ang immunidad sa mga Pinsalang Magic at Pisikal).',
		zawakeEffectDesc_ma = '#L10#Serangan penamat: #L0# juga menyerap 30% serangan kritikal sasaran dan 20% serangan berganda selama 2 pusingan. Apabila mengelak, ia segera memulihkan 4 mata kemarahan; ia akan menyebabkan tambahan 40% jumlah serangan bergandanya ke sasaran sebagai kerosakan benar (kerosakan ini boleh menjadi kritikal, mengabaikan perisai, dan tidak boleh dilawan oleh Kerosakan Ajaib dan Kerosakan Fizikal) \n#F20# \n#F40##L10# Serangan penamat terakhir: #L0# tidak boleh menerima kerosakan balas. Serangan penamat terakhir kali ketiga datang dengan 10% kerosakan berantai (kerosakan berantai tidak melebihi 200% jumlah serangan berganda sendiri); pada masa yang sama menyerap 30% serangan kritikal sasaran dan 20% serangan berganda. Apabila mengelak, <Terbang ke awan> akan segera memulihkan 4 mata kemarahan untuk dirinya sendiri; ia juga akan menyebabkan 80% kerosakan benar daripada jumlah serangan bergandanya dalam 2 kali berturut-turut ke sasaran dan kali kedua dikurangkan separuh (kerosakan ini boleh menjadi kritikal, mengabaikan perisai dan mengabaikan imuniti terhadap Kerosakan Ajaib dan Kerosakan Fizikal).',
		zawakeEffectDesc_vn = '#L10#Đòn kết liễu: #L0# cũng hấp thụ 30% đòn chí mạng của mục tiêu và 20% đòn tấn công kép trong 2 hiệp. Khi né tránh sẽ lập tức khôi phục 4 điểm tức giận; nó sẽ gây thêm 40% tổng số đòn tấn công kép của chính nó lên mục tiêu dưới dạng sát thương chuẩn (sát thương này có thể là đòn chí mạng, bỏ qua lá chắn và không có khả năng miễn nhiễm với các Sát Thương Phép Thuật và Sát Thương Vật Lý) \n#F20# \n#F40##L10# Đòn kết liễu cuối cùng: #L0# không thể nhận sát thương phản hồi. Lần kết liễu cuối cùng thứ ba đi kèm với 10% sát thương lan liên tiếp (sát thương lan không vượt quá 200% tổng số đòn tấn công kép của chính mình); đồng thời hấp thụ 30% đòn chí mạng của mục tiêu và 20% đòn tấn công kép. Khi bị né tránh, <Bay lên mây> sẽ lập tức khôi phục 4 điểm tức giận cho chính nó; nó cũng sẽ gây ra 80% sát thương thực sự của tổng đòn tấn công kép của chính nó trong 2 lần liên tiếp lên mục tiêu và lần thứ hai sẽ giảm đi một nửa (sát thương này có thể là đòn chí mạng, bỏ qua lá chắn và bỏ qua khả năng miễn nhiễm với các Sát Thương Phép Thuật và Sát Thương Vật Lý).',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Finishing and intermediate strikes resonate with the target’s fighting spirit and absorb 30% of their critical damage and 20% of their double attack for 2 turns. When dodging a finishing move, restore 4 rage. Finishing move: immune to counterattack. The third final strike deals 10% splash damage (capped at 200% of total double attack); true damage from the ultimate skill ignores shields and can trigger again at half damage (11-star)',
		zawakeSimpleDesc_en = '#C0x5c9970#Finishing and intermediate strikes resonate with the target’s fighting spirit and absorb 30% of their critical damage and 20% of their double attack for 2 turns. When dodging a finishing move, restore 4 rage. Finishing move: immune to counterattack. The third final strike deals 10% splash damage (capped at 200% of total double attack); true damage from the ultimate skill ignores shields and can trigger again at half damage (11-star)',
		zawakeSimpleDesc_th = '#C0x5c9970#ท่าไม้ตายและการโจมตีต่อเนื่องจะดูดซับ 30% ความเสียหายคริติคอลและ 20% การโจมตีคู่ของเป้าหมายเป็นเวลา 2 เทิร์น หากหลบได้ จะฟื้นคืนค่าโทสะ 4 แต้ม ท่าไม้ตาย: ไม่ได้รับผลตอบโต้ การโจมตีครั้งสุดท้ายที่สามจะมีดาเมจระเบิด 10% (ไม่เกิน 200% ของการโจมตีคู่ทั้งหมด); ดาเมจจริงจากอัลติเมทจะทะลุโล่และสามารถเปิดใช้งานซ้ำได้อีกครั้งแต่ครึ่งหนึ่งของดาเมจ (11 ดาว)',
		zawakeSimpleDesc_in = '#C0x5c9970#Serangan penyelesai dan serangan pertengahan akan menembus semangat juang target dan menyerap 30% damage critical serta 20% serangan ganda target selama 2 giliran. Serangan penyelesai atau penutup akan memulihkan 4 poin amarah saat menghindari serangan. Serangan penyelesai: tidak menerima serangan balik. Serangan penyelesai ketiga memberikan 10% damage sebaran (maksimal 200% dari total serangan ganda); damage nyata setelah skill ultimate mengabaikan perisai, dan dapat diaktifkan lagi dengan separuh damage (11 bintang)',
		zawakeSimpleDesc_ph = '#C0x5c9970#Ang finishing at intermediate strike ay sumisipsip ng 30% critical damage at 20% double attack ng target sa loob ng 2 turn. Kapag naiwasan, nakakuha ng 4 Rage. Finishing move: hindi tatamaan ng counterattack. Sa ikatlong finishing move, may 10% splash damage (hindi lalampas sa 200% ng kabuuang Double Attack); Ang tunay na pinsala pagkatapos ng ultimate ay babale-walain ang shield, at puwedeng maulit muli ang epekto pero kalahati lang ang damage (11-star)',
		zawakeSimpleDesc_ma = '#C0x5c9970#Serangan penamat dan serangan pertengahan menyerap 30% kerosakan kritikal dan 20% serangan berganda sasaran selama 2 pusingan. Serangan penamat atau penghabisan akan memulihkan 4 mata kemarahan apabila mengelak. Serangan penamat: tidak menerima serangan balas. Serangan penamat ketiga menghasilkan 10% kerosakan percikan (maksimum 200% daripada jumlah serangan berganda); kerosakan sebenar selepas skill akhir mengabaikan perisai, dan boleh diaktifkan sekali lagi dengan separuh kerosakan (bintang 11)',
		zawakeSimpleDesc_vn = '#C0x5c9970# Đòn kết liễu và đòn kết liễu làm trung gian cho trái tim đấu tranh của mục tiêu và hấp thụ 30% sát thương chí mạng và 20% đòn tấn công kép của mục tiêu trong 2 hiệp. Đòn kết liễu hoặc đòn kết thúc tự phục hồi 4 điểm tức giận khi né đòn kết liễu hoặc đòn kết liễu; đòn kết liễu: sẽ không nhận sát thương phản hồi. Lần kết liễu cuối cùng thứ ba đi kèm với 10% sát thương lan hàng (sát thương lan không vượt quá 200% tổng số đòn tấn công kép của chính mình); sát thương thực sự gây ra sau chiêu thức đặc biệt sẽ bỏ qua lá chắn và sát thương thực sự kèm theo khi sử dụng chiêu cuối có thể được kích hoạt một lần nữa và sát thương giảm một nửa (11 sao)',
		upLvDesc = 'Fixed damage +320',
		upLvDesc_en = 'Fixed damage +320',
		upLvDesc_th = 'ความเสียหายคงที่ +320',
		upLvDesc_in = 'Kerusakan tetap +320',
		upLvDesc_ph = 'Fixed damage +320',
		upLvDesc_ma = 'Kerosakan tetap +320',
		upLvDesc_vn = 'Sát thương cố định +320',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
