	[19846] = {
		id = 19846,
		skillName_vn = 'Delta Airflow',
		skillName_en = 'Delta Airflow',
		skillName_th = 'เดลต้า แอร์โฟลว์',
		skillName_in = 'Delta Airflow',
		skillName_ph = 'Delta Airflow',
		skillName_ma = 'Delta Airflow',
		skillName = 'Delta Airflow',
		describe_vn = '#L10#Delta Airflow: #L0#Cải thiện tất cả thành viên trong nhóm#C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#Magic Attack và#C0x5c 9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#Sát Thương Vật Lý; tỷ lệ đánh chí mạng và tỷ lệ hút máu của bản thân tăng 10%, tỷ lệ đánh chí mạng của các đơn vị xung quanh tăng 5%\n#F20# \n#F40##L10#Tiêu diệt diện rộng: #L0# Mục tiêu bị Rayquaza tấn công chỉ có thể phòng thủ với 50% mức phòng thủ thấp hơn của chính nó (và đòn tấn công này bỏ qua khả năng miễn nhiễm sát thương phép)\n#F20# \n#F40##L10# Kích hoạt tức giận: #L0# Nhận 2 lớp [Rage] khi nhập cảnh, nhận 2 lớp [Rage] khi bạn chủ động tấn công, nhận 1 lớp [Rage] khi đồng đội của bạn tấn công bằng kỹ năng chủ động và nhận thêm một lớp [Rage] khi thực hiện đòn chí mạng, cho đến Sau khi đạt đến cấp độ 7 của [Rage], hãy xóa tất cả các hiệu ứng kiểm soát không thống trị của bản thân và ngay lập tức tung ra một chiêu thức đặc biệt [Cú chạm kết liễu], sau đó [Bay lên mây], xuất hiện trước lượt tự hành động tiếp theo và thêm [Khiên gió] trong 2 lượt (kích hoạt hai lần trên toàn sân)\n#F10# \n#F40#[#L10#bay lên mây#L0#] Tự mình lao lên mây (không thể bị sát thương bởi sát thương hoặc hiệu ứng kỹ năng)',
		describe_en = '#L10#Delta Airflow: #L0#Enhances all party members\' #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B# Magic Attack and #C0x599970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B# Physical Damage; own critical hit rate and lifesteal rate increase by 10%, critical hit rate of nearby units increases by 5%\n#F20# \n#F40##L10#Wide-area Annihilation: #L0# Targets attacked by Rayquaza can only defend at 50% of their reduced defense (this attack ignores magic damage immunity)\n#F20# \n#F40##L10#Rage Activation: #L0#Gain 2 layers of [Rage] upon entering, 2 layers when you actively attack, 1 layer when an ally attacks with an active skill, and 1 more layer when landing a critical hit. Upon reaching level 7 of [Rage], remove all your non-dominant control effects immediately and unleash a special move [Finishing Touch], then [Soar to the Clouds], appearing before the next auto turn and gaining [Wind Shield] for 2 turns (activates twice on the whole field)\n#F10# \n#F40#[#L10#Soar to the Clouds#L0#] Launch yourself into the clouds (immune to damage and skill effects)',
		describe_th = '#L10#กระแสลมเดลต้า: #L0#เพิ่มพลังเวทย์และความเสียหายกายภาพให้กับสมาชิกในกลุ่มทั้งหมดที่ #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#; อัตราคริติคอลและการดูดเลือดของตนเองเพิ่มขึ้น 10% อัตราคริติคอลของหน่วยรอบข้างเพิ่มขึ้น 5%\n#F20# \n#F40##L10#การทำลายล้างแบบกว้าง: #L0#เป้าหมายที่ถูก Rayquaza โจมตีสามารถป้องกันได้เพียง 50% ของการป้องกันที่ลดลง (และการโจมตีนี้จะละเลยความต้านทานเวทมนตร์)\n#F20# \n#F40##L10#การเปิดใช้งานความโกรธ: #L0#ได้รับ 2 เลเยอร์ของ [Rage] เมื่อเข้าสู่สนาม, 2 เลเยอร์เมื่อคุณโจมตีแบบแอ็คทีฟ, 1 เลเยอร์เมื่อเพื่อนร่วมทีมโจมตีด้วยสกิลแอ็คทีฟ และเพิ่มอีก 1 เลเยอร์เมื่อโจมตีคริติคอล เมื่อถึงระดับ 7 ของ [Rage] ให้ลบเอฟเฟกต์ควบคุมที่ไม่ครอบงำทั้งหมดของตนเองทันทีและปล่อยท่าไม้ตายพิเศษ [Finishing Touch] จากนั้น [Soar to the Clouds] ปรากฏตัวก่อนรอบการโจมตีอัตโนมัติถัดไป และได้รับ [Wind Shield] เป็นเวลา 2 รอบ (เปิดใช้งานสองครั้งทั่วสนาม)\n#F10# \n#F40#[#L10#บินขึ้นสู่เมฆ#L0#] พุ่งขึ้นสู่เมฆด้วยตัวเอง (ไม่ถูกทำร้ายจากความเสียหายหรือสกิล)',
		describe_in = '#L10#Aliran Delta: #L0#Meningkatkan semua anggota tim sebesar #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B# Serangan Sihir dan #C0x599970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B# Kerusakan Fisik; tingkat serangan kritis dan tingkat serapan darah sendiri meningkat 10%, tingkat serangan kritis unit sekitar meningkat 5%\n#F20# \n#F40##L10#Pemusnahan Area Luas: #L0#Sasaran yang diserang oleh Rayquaza hanya dapat bertahan dengan 50% pertahanan yang dikuranginya (serangan ini melewati imunitas kerusakan sihir)\n#F20# \n#F40##L10#Aktivasi Amarah: #L0#Dapatkan 2 lapis [Rage] saat masuk, 2 lapis saat kamu menyerang secara aktif, 1 lapis saat sekutu menyerang dengan skill aktif, dan 1 lapis lagi saat melakukan serangan kritis. Setelah mencapai level 7 [Rage], hapus semua efek kontrol non-domineering pada diri sendiri dan segera luncurkan gerakan khusus [Finishing Touch], kemudian [Soar to the Clouds], muncul sebelum giliran otomatis berikutnya dan mendapat [Wind Shield] selama 2 giliran (berlaku dua kali di seluruh medan)\n#F10# \n#F40#[#L10#terbang ke awan#L0#] Meluncur ke awan sendiri (tidak bisa terkena kerusakan atau efek skill)',
		describe_ph = '#L10#Delta Airflow: #L0#Pinapalakas ang lahat ng miyembro ng grupo ng #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B# Magic Attack at #C0x599970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B# Physical Damage; tumataas ng 10% ang sariling critical hit rate at lifesteal rate, tumataas ng 5% ang critical hit rate ng mga kalapit na yunit\n#F20# \n#F40##L10#Malawakang Pagwasak: #L0# Ang mga target na inatake ni Rayquaza ay makakapagtanggol lamang gamit ang 50% ng kanilang nabawasang depensa (at nilalampasan ng atakeng ito ang magic damage immunity)\n#F20# \n#F40##L10#Pag-activate ng Galit: #L0#Kumakuha ng 2 layer ng [Rage] kapag pumasok, 2 layer kapag ikaw ay aktibong umaatake, 1 layer kapag ang iyong kasama ay umaatake gamit ang active skill, at dagdag pa ng 1 layer kapag nakagawa ng critical hit. Kapag naabot ang level 7 ng [Rage], tanggalin ang lahat ng non-dominant control effects sa sarili kaagad at ilunsad ang espesyal na galaw [Finishing Touch], pagkatapos ay [Soar to the Clouds], lilitaw bago ang susunod na auto turn at magkakaroon ng [Wind Shield] sa loob ng 2 turn (nag-a-activate nang dalawang beses sa buong field)\n#F10# \n#F40#[#L10#soar to the clouds#L0#] Ipinapailan ang sarili sa ulap (hindi maaaring masaktan ng damage o skill effects)',
		describe_ma = '#L10#Aliran Delta: #L0#Meningkatkan semua ahli pasukan sebanyak #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B# Serangan Sihir dan #C0x599970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B# Kerosakan Fizikal; kadar serangan kritikal dan kadar sedutan darah diri sendiri meningkat 10%, kadar serangan kritikal unit sekeliling meningkat 5%\n#F20# \n#F40##L10#Pembunuhan Bersepadu: #L0#Sasaran yang diserang oleh Rayquaza hanya boleh bertahan pada 50% pertahanan yang dikurangkan (serangan ini mengabaikan imuniti kerosakan sihir)\n#F20# \n#F40##L10#Pengaktifan Kemarahan: #L0#Dapatkan 2 lapisan [Rage] semasa memasuki, 2 lapisan apabila anda menyerang secara aktif, 1 lapisan apabila rakan sepasukan menyerang dengan kemahiran aktif dan 1 lapisan lagi apabila melakukan serangan kritikal. Selepas mencapai tahap 7 [Rage], buang semua kesan kawalan bukan dominan pada diri sendiri serta-merta dan lepaskan serangan khas [Finishing Touch], kemudian [Soar to the Clouds], muncul sebelum giliran tindakan automatik seterusnya dan dapatkan [Wind Shield] selama 2 giliran (aktif dua kali di seluruh medan)\n#F10# \n#F40#[#L10#terbang ke awan#L0#] Meluncur ke awan sendiri (tidak boleh menerima kerosakan atau kesan kemahiran)',
		describe = '#L10#Delta Airflow: #L0#Enhances all party members\' #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B# Magic Attack and #C0x599970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B# Physical Damage; own critical hit rate and lifesteal rate increase by 10%, critical hit rate of nearby units increases by 5%\n#F20# \n#F40##L10#Wide-area Annihilation: #L0# Targets attacked by Rayquaza can only defend at 50% of their reduced defense (this attack ignores magic damage immunity)\n#F20# \n#F40##L10#Rage Activation: #L0#Gain 2 layers of [Rage] upon entering, 2 layers when you actively attack, 1 layer when an ally attacks with an active skill, and 1 more layer when landing a critical hit. Upon reaching level 7 of [Rage], remove all your non-dominant control effects immediately and unleash a special move [Finishing Touch], then [Soar to the Clouds], appearing before the next auto turn and gaining [Wind Shield] for 2 turns (activates twice on the whole field)\n#F10# \n#F40#[#L10#Soar to the Clouds#L0#] Launch yourself into the clouds (immune to damage and skill effects)',
		starEffect = __data_t__starEffect[19846],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng khi vào trận: Giảm 200 điểm năng lượng của toàn bộ kẻ địch trong lượt đầu tiên; khi tấn công, bỏ qua tất cả hiệu ứng buff của mục tiêu kẻ địch.',
		starEffectDesc = 'Effect upon entering battle: Reduce the energy of all enemies by 200 points in the first turn; when attacking, ignore all buff effects of the enemy target.',
		starEffectDesc_en = 'Effect upon entering battle: Reduce the energy of all enemies by 200 points in the first turn; when attacking, ignore all buff effects of the enemy target.',
		starEffectDesc_th = 'Effect upon entering battle: Reduce the energy of all enemies by 200 points in the first turn; when attacking, ignore all buff effects of the enemy target.',
		starEffectDesc_in = 'Effect upon entering battle: Reduce the energy of all enemies by 200 points in the first turn; when attacking, ignore all buff effects of the enemy target.',
		starEffectDesc_ph = 'Effect upon entering battle: Reduce the energy of all enemies by 200 points in the first turn; when attacking, ignore all buff effects of the enemy target.',
		starEffectDesc_ma = 'Effect upon entering battle: Reduce the energy of all enemies by 200 points in the first turn; when attacking, ignore all buff effects of the enemy target.',
		zawakeEffect = __data_t__zawakeEffect[19846],
		-- {79004}
		zawakeEffectDesc = '#L10#Delta Airflow: #L0#Increase all #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#Magic Damage and #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#Physical Damage; Increase your critical strike chance and life steal chance by 10%, increase the critical strike chance of nearby units by 5%, increase your demon hero\'s critical damage by 10% and ignore 20% dual defense of the target when dealing critical damage, increase your flying hero\'s speed by 10% and receive <Wind Shield> for 2 turns upon the first entry (Yveltal will receive <Wind Shield> when exiting the cocoon) \n#F20# \n#F40##L10#Wide Annihilation: #L0#Targets attacked by Rayquaza can only defend with 50% less of their own defense (and the attack ignores magic damage immunity) \n#F20# \n#F40##L10#Rage Activation: #L0#Gain 2 layers of <Rage> when entering and gain 2 layers of <Rage> when you actively attack (when there are 2 or more demon heroes on your side, you start with 3 layers of rage and the <Soar Skyward> count increases by +1) \n#F20# \n#F40#Your teammates gain 1 layer of <Rage> when attacking with active skills and can gain 1 more layer of <Rage> when landing critical hits. Each layer of rage provides 3% bonus damage and 2% critical damage. After reaching 7 layers of <Rage>, all non-dominant control effects are removed and the special annihilation skill <Ultimate Finishing Touch> is immediately unleashed, followed by <Soar Skyward> \n#F20# \n#F40#During <Soar into the Clouds>, allies can use normal attacks to cooperate in battle when actively attacking. Dragon/Fly heroes can trigger effects linked to normal attacks when they actively attack (activated up to 5 times each time they soar into the clouds to cooperate in battle). They will appear before the next action round and add <Wind Shield> for 2 rounds (activated twice on the whole field) \n#F10# \n#F40#<#L10#Soar Skyward#L0#> Charge up into the clouds yourself (cannot be damaged by damage or skill effects)',
		zawakeEffectDesc_en = '#L10#Delta Airflow: #L0#Increase all #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#Magic Damage and #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#Physical Damage; Increase your critical strike chance and life steal chance by 10%, increase the critical strike chance of nearby units by 5%, increase your demon hero\'s critical damage by 10% and ignore 20% dual defense of the target when dealing critical damage, increase your flying hero\'s speed by 10% and receive <Wind Shield> for 2 turns upon the first entry (Yveltal will receive <Wind Shield> when exiting the cocoon) \n#F20# \n#F40##L10#Wide Annihilation: #L0#Targets attacked by Rayquaza can only defend with 50% less of their own defense (and the attack ignores magic damage immunity) \n#F20# \n#F40##L10#Rage Activation: #L0#Gain 2 layers of <Rage> when entering and gain 2 layers of <Rage> when you actively attack (when there are 2 or more demon heroes on your side, you start with 3 layers of rage and the <Soar Skyward> count increases by +1) \n#F20# \n#F40#Your teammates gain 1 layer of <Rage> when attacking with active skills and can gain 1 more layer of <Rage> when landing critical hits. Each layer of rage provides 3% bonus damage and 2% critical damage. After reaching 7 layers of <Rage>, all non-dominant control effects are removed and the special annihilation skill <Ultimate Finishing Touch> is immediately unleashed, followed by <Soar Skyward> \n#F20# \n#F40#During <Soar into the Clouds>, allies can use normal attacks to cooperate in battle when actively attacking. Dragon/Fly heroes can trigger effects linked to normal attacks when they actively attack (activated up to 5 times each time they soar into the clouds to cooperate in battle). They will appear before the next action round and add <Wind Shield> for 2 rounds (activated twice on the whole field) \n#F10# \n#F40#<#L10#Soar Skyward#L0#> Charge up into the clouds yourself (cannot be damaged by damage or skill effects)',
		zawakeEffectDesc_th = '#L10#Delta Airflow: #L0#เพิ่มทั้งหมด #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#ความเสียหายเวทย์มนตร์ และ #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#ความเสียหายทางกายภาพ; เพิ่มโอกาสตีคริติคอลและโอกาสดูดเลือดของตัวเอง 10%, เพิ่มโอกาสตีคริติคอลของหน่วยรอบข้าง 5%, เพิ่มความเสียหายคริติคอลของฮีโร่ปีศาจของคุณ 10% และละเลยการป้องกันคู่ 20% ของเป้าหมายเมื่อสร้างความเสียหายคริติคอล, เพิ่มความเร็วของฮีโร่บินของคุณ 10% และได้รับ <โล่ลม> เป็นเวลา 2 เทิร์นเมื่อเข้าครั้งแรก (Yveltal จะได้รับ <โล่ลม> เมื่อออกจากดักแด้) \n#F20# \n#F40##L10#การทำลายล้างในวงกว้าง: #L0#เป้าหมายที่ถูก Rayquaza โจมตีสามารถป้องกันได้เพียง 50% ของเกราะตัวเองที่ลดลง (และการโจมตีจะเลี่ยงการต่อต้านความเสียหายเวทย์มนตร์) \n#F20# \n#F40##L10#การเปิดใช้งานความโกรธ: #L0#รับ 2 ชั้นของ <ความโกรธ> เมื่อเข้ามาและรับ 2 ชั้นของ <ความโกรธ> เมื่อคุณโจมตีโดยตรง (เมื่อมีฮีโร่ปีศาจ 2 ตัวขึ้นไปอยู่ข้างคุณ คุณจะได้รับ 3 ชั้นของความโกรธเมื่อเริ่มต้นและจำนวน <บินขึ้นสู่เมฆ> จะเพิ่ม +1) \n#F20# \n#F40#เพื่อนร่วมทีมของคุณจะได้รับ 1 ชั้นของ <ความโกรธ> เมื่อโจมตีด้วยสกิลโจมตีโดยตรงและสามารถได้รับเพิ่มอีก 1 ชั้นของ <ความโกรธ> เมื่อโจมตีคริติคอล แต่ละชั้นของความโกรธให้โบนัสความเสียหาย 3% และความเสียหายคริติคอล 2% หลังจากได้รับครบ 7 ชั้นของ <ความโกรธ> ผลควบคุมที่ไม่เด่นจะถูกลบและสกิลทำลายล้างพิเศษ <การโจมตีสุดท้ายขั้นสูง> จะถูกปลดปล่อยทันที ตามด้วย <บินขึ้นสู่เมฆ> \n#F20# \n#F40#ใน <บินเข้าสู่เมฆ> เพื่อนร่วมทีมสามารถใช้การโจมตีปกติเพื่อประสานงานในการต่อสู้เมื่อโจมตีโดยตรง ฮีโร่มังกร/บินสามารถเปิดใช้งานเอฟเฟกต์ที่เชื่อมโยงกับการโจมตีปกติเมื่อโจมตีโดยตรง (เปิดใช้งานได้สูงสุด 5 ครั้งต่อการบินขึ้นสู่เมฆเพื่อประสานงานในการต่อสู้) พวกมันจะปรากฏก่อนรอบการกระทำถัดไปและเพิ่ม <โล่ลม> เป็นเวลา 2 รอบ (เปิดใช้งาน 2 ครั้งทั่วสนาม) \n#F10# \n#F40#<#L10#บินขึ้นสู่เมฆ#L0#> บุกขึ้นสู่เมฆด้วยตัวเอง (ไม่สามารถถูกทำร้ายด้วยความเสียหายหรือเอฟเฟกต์ทักษะได้)',
		zawakeEffectDesc_in = '#L10#Delta Airflow: #L0#Meningkatkan semua #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#Kerusakan Magis dan #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#Kerusakan Fisik; Meningkatkan peluang serangan kritis dan peluang pencurian darah kamu sebesar 10%, meningkatkan peluang serangan kritis unit di sekitar sebesar 5%, meningkatkan kerusakan kritis pahlawan iblis kamu sebesar 10% dan mengabaikan 20% pertahanan ganda target saat memberikan kerusakan kritis, meningkatkan kecepatan pahlawan terbang kamu sebesar 10% dan mendapat <Perisai Angin> selama 2 giliran saat pertama kali masuk (Yveltal akan memperoleh <Perisai Angin> saat keluar dari kepompong) \n#F20# \n#F40##L10#Pembasmian Luas: #L0#Target yang diserang oleh Rayquaza hanya dapat bertahan dengan 50% pertahanan sendiri yang dikurangi (dan serangan melewati kemampuan kebal kerusakan magis) \n#F20# \n#F40##L10#Aktivasi Amarah: #L0#Mendapat 2 lapis <Amarah> saat masuk dan mendapatkan 2 lapis <Amarah> saat kamu menyerang aktif (ketika ada 2 atau lebih pahlawan iblis di pihakmu, kamu memulai dengan 3 lapis amarah dan jumlah <Terbang ke Awan> meningkat +1) \n#F20# \n#F40#Rekan timmu mendapatkan 1 lapis <Amarah> saat menyerang dengan keterampilan aktif dan mereka bisa mendapatkan 1 lapis <Amarah> tambahan saat menyerang kritis. Setiap lapis amarah memberikan 3% kerusakan tambahan dan 2% kerusakan kritis. Setelah mencapai 7 lapis <Amarah>, semua efek kontrol non-dominan akan dihapus dan keterampilan pembasmian khusus <Sentuhan Akhir Utama> akan segera dilepaskan, diikuti oleh <Terbang ke Awan> \n#F20# \n#F40#Dalam <Terbang ke Awan>, rekan tim dapat menggunakan serangan biasa untuk bekerjasama bertarung saat menyerang aktif. Pahlawan Naga/Terbang dapat mengaktifkan efek yang berhubungan dengan serangan biasa ketika mereka menyerang aktif (aktif hingga 5 kali setiap kali mereka terbang ke awan untuk bekerjasama bertarung). Mereka akan muncul sebelum putaran tindakan berikutnya dan menambahkan <Perisai Angin> selama 2 putaran (diaktifkan 2 kali di seluruh medan) \n#F10# \n#F40#<#L10#Terbang ke Awan#L0#> Meluncur sendiri ke awan (tidak bisa terkena kerusakan oleh damage atau efek skill)',
		zawakeEffectDesc_ph = '#L10#Delta Airflow: #L0#Tumaas ang lahat ng #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#Mahiwagang Pinsala at #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#Pisikal na Pinsala; Taasan ang iyong pagkakataon ng kritikal na tama at pagkakataon ng life steal ng 10%, pataasin ang pagkakataon ng kritikal na tama ng mga yunit sa paligid ng 5%, pataasin ang kritikal na pinsala ng iyong demonic hero ng 10% at balewalain ang 20% doble na depensa ng target kapag nagbibigay ng kritikal na pinsala, pataasin ang bilis ng iyong flying hero ng 10% at makatanggap ng <Wind Shield> sa loob ng 2 turn kapag unang pumasok (Makakakuha si Yveltal ng <Wind Shield> kapag lumabas mula sa silid-pugad) \n#F20# \n#F40##L10#Malawakang Pagwasak: #L0#Ang mga target na inatake ni Rayquaza ay maaari lamang magtanggol gamit ang 50% bawas ng kanilang sariling depensa (at ang pag-atake ay nilalampasan ang immunity sa magic damage) \n#F20# \n#F40##L10#Pag-activate ng Galit: #L0#Kumuha ng 2 layer ng <Galit> kapag pumasok at kumuha ng 2 layer ng <Galit> kapag aktibong umaatake ka (kapag may 2 o higit pang demonic heroes sa iyong panig, magkakaroon ka ng 3 layer ng galit sa simula at tataas ang bilang ng <Lumipad sa Ulap> ng +1) \n#F20# \n#F40#Nakakakuha ang iyong mga kakampi ng 1 layer ng <Galit> kapag umaatake gamit ang aktibong kasanayan at maaari silang makakuha ng dagdag na 1 layer ng <Galit> kapag tumatama ng kritikal na tama. Bawat layer ng galit ay nagbibigay ng 3% dagdag na pinsala at 2% kritikal na pinsala. Kapag naabot ang 7 layer ng <Galit>, lahat ng mga non-dominant control effect ay mawawala at ang espesyal na skill na pagwasak na <Ultimate Finishing Touch> ay agad na ilalabas, kasunod ang <Lumipad sa Ulap> \n#F20# \n#F40#Sa <Lumipad sa Ulap>, maaaring gumamit ang mga kakampi ng normal na atake upang makipagtulungan sa labanan kapag aktibong umaatake. Ang mga Dragon/Flying na bayani ay maaaring mag-activate ng mga epekto na kaugnay ng normal na atake kapag aktibong umaatake sila (na-activate hanggang 5 beses sa bawat pag-lumipad sa ulap para makipagtulungan sa labanan). Lalabas sila bago ang susunod na action round at magdadagdag ng <Wind Shield> sa loob ng 2 round (na-activate 2 beses sa buong field) \n#F10# \n#F40#<#L10#Lumipad sa Ulap#L0#> Sagad papunta sa ulap nang mag-isa (hindi maaaring mapinsala ng pinsala o efekto ng skill)',
		zawakeEffectDesc_ma = '#L10#Delta Airflow: #L0#Meningkatkan semua #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#Kerosakan Sihir dan #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#Kerosakan Fizikal; Meningkatkan peluang serangan kritikal dan peluang hisap darah anda sebanyak 10%, meningkatkan peluang serangan kritikal unit di sekitar sebanyak 5%, meningkatkan kerosakan kritikal wira iblis anda sebanyak 10% dan mengabaikan 20% pertahanan berganda sasaran apabila menyebabkan kerosakan kritikal, meningkatkan halaju wira terbang anda sebanyak 10% dan menerima <Perisai Angin> selama 2 giliran semasa kemasukan pertama (Yveltal akan menerima <Perisai Angin> apabila keluar dari kepompong) \n#F20# \n#F40##L10#Pemusnahan Luas: #L0#Sasaran yang diserang oleh Rayquaza hanya boleh bertahan dengan 50% pertahanan sendiri yang dikurangkan (dan serangan mengabaikan imuniti kerosakan sihir) \n#F20# \n#F40##L10#Aktifkan Kemarahan: #L0#Mendapat 2 lapisan <Kemarahan> apabila memasuki dan mendapat 2 lapisan <Kemarahan> apabila anda menyerang secara aktif (apabila terdapat 2 atau lebih wira iblis di pihak anda, anda akan mendapat 3 lapisan kemarahan ketika bermula dan bilangan <Terbang ke Awan> akan meningkat +1) \n#F20# \n#F40#Rakan sepasukan anda mendapat 1 lapisan <Kemarahan> apabila menyerang dengan kemahiran aktif dan mereka boleh mendapat 1 lapisan <Kemarahan> tambahan apabila menyerang kritikal. Setiap lapisan kemarahan memberikan 3% kerosakan tambahan dan 2% kerosakan kritikal. Selepas mencapai 7 lapisan <Kemarahan>, semua kesan kawalan yang tidak dominan akan dihapus dan kemahiran pemusnahan khas <Sentuhan Akhir Utama> akan dilepaskan dengan segera, diikuti oleh <Terbang ke Awan> \n#F20# \n#F40#Dalam <Terbang ke Awan>, rakan sepasukan boleh menggunakan serangan biasa untuk bekerjasama dalam pertarungan apabila menyerang secara aktif. Wira Naga/Terbang boleh mengaktifkan kesan yang berkaitan dengan serangan biasa apabila mereka menyerang secara aktif (diaktifkan sehingga 5 kali setiap kali mereka terbang ke awan untuk bekerjasama dalam pertarungan). Mereka akan muncul sebelum pusingan tindakan seterusnya dan menambah <Perisai Angin> selama 2 pusingan (diaktifkan 2 kali di seluruh padang) \n#F10# \n#F40#<#L10#Terbang ke Awan#L0#> Menyerbu ke awan sendiri (tidak boleh menerima kerosakan oleh kerosakan atau kesan kemahiran)',
		zawakeEffectDesc_vn = '#L10#Delta Airflow: #L0#Tăng tất cả #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B545B#Sát Thương Phép Thuật và #C0x5c9970#$(6+skillLevel*0.06-0.06)$%#C0x5B5 45B#Sát Thương Vật Lý; Tăng tỷ lệ đánh chí mạng và tỷ lệ hút máu của bản thân thêm 10%, tăng tỷ lệ đánh chí mạng của các đơn vị xung quanh thêm 5%, tăng 10% sát thương chí mạng cho tướng quỷ của chính bạn và bỏ qua phòng thủ kép 20% của mục tiêu khi gây sát thương chí mạng, tăng 10% tốc độ của anh hùng bay của chính bạn và nhận được <Khiên gió> trong 2 lượt khi bước vào lần đầu tiên (Yveltal sẽ nhận được <Khiên gió> khi thoát ra khỏi kén) \n#F20# \n#F40##L10#Tiêu diệt diện rộng: #L0# Mục tiêu bị Rayquaza tấn công chỉ có thể phòng thủ với 50% mức phòng thủ thấp hơn của chính nó (và đòn tấn công bỏ qua khả năng miễn nhiễm sát thương phép) \n#F20# \n#F40##L10# Kích hoạt cơn giận: #L0# Nhận 2 lớp <Cơn thịnh nộ> khi xâm nhập và nhận được 2 lớp <Cơn thịnh nộ> khi bạn chủ động tấn công (khi có 2 anh hùng thuộc loại quỷ trở lên về phía bạn, bạn sẽ có được 3 lớp thịnh nộ khi bắt đầu và số <Bay lên mây> sẽ tăng thêm +1) \n#F20# \n#F40# Đồng đội của bạn có được 1 lớp <Cơn thịnh nộ> khi tấn công bằng kỹ năng chủ động và họ có thể nhận thêm 1 lớp <Cơn thịnh nộ> khi tấn công chí mạng. Mỗi lớp giận dữ cung cấp 3% sát thương cộng thêm và 2% sát thương chí mạng. Sau khi đạt 7 lớp <Cơn thịnh nộ>, tất cả các hiệu ứng điều khiển không chiếm ưu thế sẽ bị xóa và kỹ năng tiêu diệt đặc biệt <Cú chạm kết thúc tối thượng> sẽ được giải phóng ngay lập tức, sau đó <Bay lên mây> \n#F20# \n#F40# Trong <Bay vào mây>, đồng đội có thể sử dụng đòn đánh thường để phối hợp chiến đấu khi chủ động tấn công. Tướng Rồng/Bay có thể kích hoạt các hiệu ứng gắn với đòn đánh thông thường khi họ chủ động tấn công (kích hoạt tối đa 5 lần mỗi lần họ bay lên mây để phối hợp chiến đấu). Chúng sẽ xuất hiện trước vòng hành động tiếp theo và thêm <Khiên gió> trong 2 vòng (được kích hoạt 2 lần trên toàn sân) \n#F10# \n#F40#<#L10#bay lên mây#L0#> Tự mình lao lên mây (không thể bị sát thương bởi sát thương hoặc hiệu ứng kỹ năng)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970# When there are 2 or more demon-type heroes on your side, you will gain 3 stacks of rage at the start and the number of <Soaring into the Clouds> will be increased by +1; while <Soaring into the Clouds>, allies can use basic attacks to assist when they actively attack. When dragon/flying heroes actively attack, they can trigger the effects of basic attacks (once per soaring). Cloud collaboration can be triggered up to 5 times); Increase Delta Airflow: Increase your demon heroes’ critical hit rate by 10% and ignore 20% of the target’s dual defense when dealing critical damage. Increase your flying heroes’ speed by 10% and gain <Wind Shield> for 2 turns when entering the arena for the first time (Yveltal will gain <Wind Shield> when emerging from the cocoon)',
		zawakeSimpleDesc_en = '#C0x5c9970# When there are 2 or more demon-type heroes on your side, you will gain 3 stacks of rage at the start and the number of <Soaring into the Clouds> will be increased by +1; while <Soaring into the Clouds>, allies can use basic attacks to assist when they actively attack. When dragon/flying heroes actively attack, they can trigger the effects of basic attacks (once per soaring). Cloud collaboration can be triggered up to 5 times); Increase Delta Airflow: Increase your demon heroes’ critical hit rate by 10% and ignore 20% of the target’s dual defense when dealing critical damage. Increase your flying heroes’ speed by 10% and gain <Wind Shield> for 2 turns when entering the arena for the first time (Yveltal will gain <Wind Shield> when emerging from the cocoon)',
		zawakeSimpleDesc_th = '#C0x5c9970# เมื่อมีฮีโร่สายปีศาจ 2 ตัวขึ้นไปอยู่ฝั่งคุณ คุณจะได้รับ 3 ชั้นความโกรธตั้งแต่เริ่มต้น และจำนวน <ลอยขึ้นฟ้า> จะเพิ่มขึ้น +1; ขณะอยู่ในสถานะ <ลอยขึ้นฟ้า> เพื่อนร่วมทีมสามารถใช้การโจมตีปกติเพื่อประสานในการโจมตีเมื่อพวกเขาโจมตีแบบแอคทีฟ เมื่อฮีโร่สายมังกร/บิน โจมตีแบบแอคทีฟ พวกเขาสามารถกระตุ้นเอฟเฟกต์ของการโจมตีปกติ (หนึ่งครั้งต่อการลอยขึ้นฟ้า) การประสานบนเมฆสามารถเปิดใช้งานได้สูงสุด 5 ครั้ง); เพิ่ม Delta Airflow: เพิ่มอัตราคริติคอลของฮีโร่ปีศาจของคุณ 10% และเจาะทะลุการป้องกันคู่ของเป้าหมาย 20% เมื่อโจมตีคริติคอล เพิ่มความเร็วของฮีโร่สายบินของคุณ 10% และได้รับ <โล่ลม> เป็นเวลา 2 เทิร์น เมื่อเข้าสู่สนามต่อสู้ครั้งแรก (Yveltal จะได้รับ <โล่ลม> เมื่อออกจากดักแด้)',
		zawakeSimpleDesc_in = '#C0x5c9970# Ketika ada 2 atau lebih hero tipe iblis di pihakmu, kamu akan mendapatkan 3 lapis kemarahan sejak awal dan jumlah <Melayang di Awan> akan bertambah +1; selama <Melayang di Awan>, rekan tim bisa menggunakan serangan dasar untuk ikut menyerang saat mereka menyerang secara aktif. Ketika hero naga/terbang menyerang secara aktif, mereka bisa memicu efek dari serangan dasar (sekali setiap kali melayang). Kolaborasi di awan dapat dipicu hingga 5 kali); Tingkatkan Delta Airflow: Meningkatkan 10% peluang kritikal hero iblismu dan mengabaikan 20% pertahanan ganda target saat memberikan damage kritikal. Meningkatkan kecepatan hero terbangmu sebesar 10% dan mendapatkan <Perisai Angin> selama 2 giliran saat pertama kali memasuki arena (Yveltal akan mendapatkan <Perisai Angin> saat keluar dari kepompong)',
		zawakeSimpleDesc_ph = '#C0x5c9970# Kapag may 2 o higit pang demon-type na bayani sa iyong panig, makakakuha ka ng 3 layers ng Galit sa simula at ang bilang ng <Paglipad sa Ulap> ay madaragdagan ng +1; habang nasa <Paglipad sa Ulap>, maaaring gumamit ng basic attack ang mga kakampi upang makipag-koordinasyon kapag sila ay umatake. Kapag ang dragon/flying na bayani ay umatake, maaari nilang i-activate ang epekto ng normal attacks (tuwing lilipad). Maaaring ma-trigger ang cloud collaboration hanggang 5 beses); Pahusayin ang Delta Airflow: Tumaas ang critical hit rate ng demon hero mo ng 10% at bale-wala ang 20% ng dual defense ng target kapag critical damage. Tumaas ang bilis ng flying hero mo ng 10% at makakatanggap ng <Wind Shield> sa loob ng 2 turns sa unang pagpasok sa arena (Makakakuha ng <Wind Shield> si Yveltal pagkatapos lumabas sa cocoon)',
		zawakeSimpleDesc_ma = '#C0x5c9970# Apabila terdapat 2 atau lebih hero jenis syaitan di pihak anda, anda akan mendapat 3 lapisan Kemarahan pada permulaan dan jumlah <Terbang di Awan> akan ditambah +1; semasa <Terbang di Awan>, rakan sepasukan boleh menggunakan serangan biasa untuk bekerjasama apabila mereka menyerang secara aktif. Apabila hero naga/terbang menyerang secara aktif, mereka boleh mencetuskan kesan daripada serangan biasa (setiap kali terbang). Kerjasama awan boleh dicetuskan sehingga 5 kali); Tingkatkan Delta Airflow: Meningkatkan kadar serangan kritikal hero syaitan anda sebanyak 10% dan mengabaikan 20% pertahanan berganda sasaran apabila memberikan serangan kritikal. Meningkatkan kelajuan hero terbang anda sebanyak 10% dan menerima <Perisai Angin> selama 2 pusingan apabila pertama kali memasuki arena (Yveltal akan menerima <Perisai Angin> selepas keluar dari kepompong)',
		zawakeSimpleDesc_vn = '#C0x5c9970# Khi có 2 anh hùng loại quỷ trở lên về phía bạn, bạn sẽ có được 3 lớp giận dữ ngay từ đầu và số <Bay lên mây> sẽ được cộng thêm +1; trong khi <Bay lên mây>, đồng đội có thể sử dụng đòn đánh thường để phối hợp khi họ chủ động tấn công. Khi anh hùng rồng/bay chủ động tấn công, họ có thể kích hoạt hiệu ứng của các đòn tấn công thông thường (mỗi lần bay lên mây). Kích hoạt cộng tác trên đám mây lên tới 5 lần); Tăng Delta Airflow: Tăng 10% đòn chí mạng của tướng quỷ của bạn và bỏ qua 20% phòng thủ kép của mục tiêu khi gây sát thương chí mạng. Tăng tốc độ của anh hùng bay của bạn thêm 10% và nhận được <Khiên gió> trong 2 hiệp khi vào đấu trường lần đầu tiên (Yveltar sẽ nhận được <Khiên gió> khi thoát ra khỏi kén)',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		passivePriority = 200,
		skillType = 2,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {198461, 198462, 198463, 198464, 198465, 198466, 198467}
