	[19911] = {
		id = 19911,
		skillName_vn = 'Sự xuất hiện của các vì sao',
		skillName_en = 'The appearance of the stars',
		skillName_th = 'การปรากฏตัวของดาว',
		skillName_in = 'Kemunculan bintang-bintang',
		skillName_ph = 'Ang paglitaw ng mga bituin',
		skillName_ma = 'Kemunculan bintang-bintang',
		skillName = 'The appearance of the stars',
		describe_vn = '#C0xC0C0C0#*Xingxing, vui lòng cho tôi biết~*#C0x5B545B#\n#F10# \n#F40#Jirachi triệu hồi một thiên thạch hạ cánh và tấn công một mục tiêu kẻ thù, gây ra #C0x3D8A99#100% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel* 4*24)$ trong #C0xF13B54# sát thương phép #C0x5B545B#, tăng tốc độ của bản thân thêm 15% trong 2 lượt và có 70% xác suất khiến một người bạn ngẫu nhiên nhận thêm [Wish Note]',
		describe_en = '#C0xC0C0C0#*Xingxing, please let me know~*#C0x5B545B#\n#F10# \n#F40#Jirachi summons a meteor to land and attack an enemy target, dealing #C0x3D8A99#100% Magic Damage#C0x5B545B#+$(skillLevel* 4*24)$ in #C0xF13B54# magic damage #C0x5B545B#, increases own speed by 15% for 2 turns, and has a 70% chance to grant a random ally an additional [Wish Note].',
		describe_th = '#C0xC0C0C0#*Xingxing กรุณาบอกฉันที~*#C0x5B545B#\n#F10# \n#F40# จิราชิเรียกอุกกาบาตลงมายิงใส่เป้าหมายศัตรู ทำให้เกิดความเสียหายเวทมนตร์ #C0x3D8A99#100%#C0x5B545B#+$(skillLevel* 4*24)$ ใน #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# เพิ่มความเร็วตัวเอง 15% เป็นเวลา 2 เทิร์น และมีโอกาส 70% ที่จะมอบ [Wish Note] เพิ่มเติมให้เพื่อนสุ่มหนึ่งคน',
		describe_in = '#C0xC0C0C0#*Xingxing, tolong beri tahu aku~*#C0x5B545B#\n#F10# \n#F40#Jirachi memanggil meteor yang mendarat dan menyerang target musuh, memberikan #C0x3D8A99#100% Damage Sihir#C0x5B545B#+$(skillLevel* 4*24)$ dalam #C0xF13B54# damage sihir #C0x5B545B#, meningkatkan kecepatan sendiri sebesar 15% selama 2 giliran dan memiliki peluang 70% untuk memberikan [Wish Note] tambahan kepada sekutu acak.',
		describe_ph = '#C0xC0C0C0#*Xingxing, pakisabi sa akin~*#C0x5B545B#\n#F10# \n#F40#Jirachi ay nagmumungkahi ng isang meteor na bumagsak at umatake sa isang kalaban na target, na nagdudulot ng #C0x3D8A99#100% Pinsalang Mahika#C0x5B545B#+$(skillLevel* 4*24)$ sa #C0xF13B54# pinsalang mahika #C0x5B545B#, nagpapataas ng sariling bilis ng 15% sa loob ng 2 turn at may 70% tsansa na bigyan ang isang random na kasamahan ng karagdagang [Wish Note].',
		describe_ma = '#C0xC0C0C0#*Xingxing, sila beritahu saya~*#C0x5B545B#\n#F10# \n#F40#Jirachi memanggil meteor yang mendarat dan menyerang sasaran musuh, menyebabkan #C0x3D8A99#100% Kerosakan Sihir#C0x5B545B#+$(skillLevel* 4*24)$ dalam #C0xF13B54# kerosakan sihir #C0x5B545B#, meningkatkan kelajuan diri sebanyak 15% selama 2 pusingan dan mempunyai peluang 70% untuk memberikan [Wish Note] tambahan kepada rakan rawak.',
		describe = '#C0xC0C0C0#*Xingxing, please let me know~*#C0x5B545B#\n#F10# \n#F40#Jirachi summons a meteor to land and attack an enemy target, dealing #C0x3D8A99#100% Magic Damage#C0x5B545B#+$(skillLevel* 4*24)$ in #C0xF13B54# magic damage #C0x5B545B#, increases own speed by 15% for 2 turns, and has a 70% chance to grant a random ally an additional [Wish Note].',
		upLvDesc = 'Fixed damage +96',
