	[19912] = {
		id = 19912,
		skillName_vn = 'Mắt chân thật',
		skillName_en = 'Real eyes',
		skillName_th = 'ดวงตาจริง',
		skillName_in = 'Mata nyata',
		skillName_ph = 'Tunay na mga mata',
		skillName_ma = 'Mata sebenar',
		skillName = 'Real eyes',
		describe_vn = '#C0xC0C0C0#*Điều ước đã thành hiện thực~*#C0x5B545B#\n#F10# \n#F40# Jirachi mở [Eye of Truth] trên bụng tồn tại trong 1 lượt và phát ra một tia tấn công một mục tiêu kẻ địch, gây #C0xF13B54# Sát Thương Phép Thuật #C0x3D8A99#180% phép thuật attack#C0x5B545B#+$(skillLevel*4*48)$#C0x5B545B#\n#F20# \n#F40##L10# Eye of Truth: #L0# Hiệu ứng đặc biệt, tỷ lệ kháng và khả năng kháng đòn chí mạng tăng 30%. Trong thời gian này, Jirachi có 77% cơ hội thực hiện điều ước sau bất kỳ hành động thân thiện nào.',
		describe_en = '*The wish has come true~* Jirachi opens [Eye of Truth] on its belly lasting for 1 turn and fires a beam attacking one enemy target, dealing 180% magic attack + $(skillLevel*4*48)$ magic damage. Eye of Truth: Special effect that increases resistance rate and critical block chance by 30%. During this time, Jirachi has a 77% chance to grant a wish after any friendly action.',
		describe_th = '*คำอธิษฐานเป็นจริงแล้ว~* Jirachi เปิด [Eye of Truth] ที่ท้อง ซึ่งคงอยู่ 1 เทิร์นและปล่อยลำแสงโจมตีศัตรูเป้าหมายหนึ่งตัว สร้างความเสียหายเวทย์ 180% + $(skillLevel*4*48)$ ความเสียหายเวทย์ Eye of Truth: เอฟเฟกต์พิเศษ เพิ่มโอกาสต่อต้านและโอกาสป้องกันคริติคอล 30% ในช่วงเวลานี้ Jirachi มีโอกาส 77% ในการทำให้คำอธิษฐานเป็นจริงหลังจากการกระทำที่เป็นมิตรใดๆ',
		describe_in = '*Keinginan telah menjadi kenyataan~* Jirachi membuka [Eye of Truth] di perutnya yang bertahan selama 1 giliran dan menembakkan sinar menyerang satu musuh, menghasilkan 180% serangan sihir + $(skillLevel*4*48)$ damage sihir. Eye of Truth: Efek khusus yang meningkatkan tingkat resistensi dan peluang menangkis serangan kritikal sebesar 30%. Selama waktu ini, Jirachi memiliki peluang 77% untuk mengabulkan keinginan setelah setiap aksi bersahabat.',
		describe_ph = '*Ang kahilingan ay natupad na~* Binuksan ni Jirachi ang [Eye of Truth] sa kanyang tiyan na tumatagal ng 1 turn at nagpalabas ng sinag na sumasalakay sa isang kalabang target, nagdudulot ng 180% magic attack + $(skillLevel*4*48)$ magic damage. Eye of Truth: Espesyal na epekto na nagpapataas ng resistance rate at critical block chance ng 30%. Sa panahong ito, may 77% na tsansa si Jirachi na matupad ang kahilingan pagkatapos ng anumang friendly action.',
		describe_ma = '*Permintaan telah menjadi kenyataan~* Jirachi membuka [Eye of Truth] di perutnya yang berlangsung selama 1 giliran dan melepaskan pancaran menyerang satu musuh, menyebabkan 180% serangan sihir + $(skillLevel*4*48)$ kerosakan sihir. Eye of Truth: Kesan istimewa yang meningkatkan kadar penentangan dan peluang menangkis serangan kritikal sebanyak 30%. Sepanjang masa ini, Jirachi mempunyai peluang 77% untuk merealisasikan permintaan selepas mana-mana tindakan mesra.',
		describe = '*The wish has come true~* Jirachi opens [Eye of Truth] on its belly lasting for 1 turn and fires a beam attacking one enemy target, dealing 180% magic attack + $(skillLevel*4*48)$ magic damage. Eye of Truth: Special effect that increases resistance rate and critical block chance by 30%. During this time, Jirachi has a 77% chance to grant a wish after any friendly action.',
		upLvDesc = 'Fixed damage +192',
