	[19913] = {
		id = 19913,
		skillName_vn = 'Nguyện ước diệt vong',
		skillName_en = 'Wish of Destruction',
		skillName_th = 'ความปรารถนาแห่งการทำลายล้าง',
		skillName_in = 'Doa Kehancuran',
		skillName_ph = 'Pagnanais ng Pagkawasak',
		skillName_ma = 'Hasrat Kemusnahan',
		skillName = 'Wish of Destruction',
		describe_vn = '#C0xC0C0C0#*Luôn có những nơi các ngôi sao không thể tỏa sáng...*#C0x5B545B#\n#F10# \n#F40#Jirachi cầu nguyện sức mạnh của Sao chổi Thiên niên kỷ, và ánh sáng của các ngôi sao tỏa ra từ Mắt Sự thật và tấn công tất cả mục tiêu của kẻ thù, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+ The #C0xF13B54# Sát Thương Phép Thuật $(skillLevel*4*60)$#C0x5B545B# loại bỏ mọi hiệu ứng buff của mục tiêu chính (1~3 mục tiêu khác)\n#F20# \n#F40##L10#Meteor Beam: #L0# Ở vòng tiếp theo, khi hiệu ứng ghi chú điều ước trên mỗi bên thân thiện kết thúc (bao gồm cả cái chết), tia sao băng sẽ phóng lên tất cả kẻ thù, khiến Jirachi #C0xE69900#50%~120% Sát Thương Vật Lý #C0x5B545B# sát thương\n#F20# \n#F40##L10#天恩: #L0# Lời cầu nguyện của Jirachi lần này có 35% xác suất kích hoạt Thiên An và giải phóng 3 ghi chú điều ước cùng một lúc.',
		describe_en = '*There are always places where stars cannot shine...* Jirachi prays for the power of the Millennium Comet, and the light of the stars radiates from the Eye of Truth, attacking all enemy targets, dealing 180% Magic Damage + The Magic Damage $(skillLevel*4*60)$ and removing all buff effects from the main target (1~3 additional targets). Meteor Beam: In the next round, when the wish note effect on each friendly side ends (including death), a comet beam will shoot at all enemies, causing Jirachi to deal 50%~120% Physical Damage. 天恩 (Heaven’s Grace): This time Jirachi\'s prayer has a 35% chance to activate Heaven’s Blessing and release 3 wish notes simultaneously.',
		describe_th = '*มีสถานที่เสมอที่ดาวไม่อาจส่องแสง...* จิราจิอธิษฐานขอพลังของดาวหางพันปี แสงดาวส่องออกจากดวงตาความจริงและโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวทมนตร์ 180% + ความเสียหายเวท $(skillLevel*4*60)$ และลบทุกบัฟของเป้าหมายหลัก (1~3 เป้าหมายเพิ่มเติม) Meteor Beam: ในรอบถัดไป เมื่อผลโน้ตอธิษฐานของฝ่ายที่เป็นมิตรถูกยุติ (รวมถึงการตาย) รังสีดาวหางจะยิงไปยังศัตรูทั้งหมด ทำให้จิราจิทำความเสียหายทางกายภาพ 50%~120% 天恩 : การอธิษฐานครั้งนี้ของจิราจิมีโอกาส 35% ที่จะเปิดใช้งานสวรรค์และปล่อยโน้ตอธิษฐาน 3 ชิ้นพร้อมกัน',
		describe_in = '*Selalu ada tempat di mana bintang tidak bisa bersinar...* Jirachi berdoa untuk kekuatan Komet Milenium, dan cahaya bintang memancar dari Mata Kebenaran menyerang semua target musuh, menyebabkan 180% Damage Sihir + Damage Sihir $(skillLevel*4*60)$ dan menghapus semua efek buff dari target utama (1~3 target tambahan). Meteor Beam: Pada giliran berikutnya, ketika efek catatan harapan di setiap sisi teman berakhir (termasuk kematian), sinar komet akan ditembakkan ke semua musuh, menyebabkan Jirachi memberikan Damage Fisik 50%~120%. 天恩: Doa Jirachi kali ini memiliki peluang 35% untuk mengaktifkan Berkah Surga dan melepaskan 3 catatan harapan sekaligus.',
		describe_ph = '*Laging may mga lugar kung saan hindi makapagliliwanag ang mga bituin...* Nananalangin si Jirachi para sa kapangyarihan ng Millennium Comet, at ang liwanag ng mga bituin mula sa Mata ng Katotohanan ay inaatake ang lahat ng kalaban, na nagdudulot ng 180% Magic Damage + Magic Damage na $(skillLevel*4*60)$ at tinatanggal ang lahat ng buff effect mula sa pangunahing target (1~3 karagdagang target). Meteor Beam: Sa susunod na round, kapag natapos ang wish note effect sa bawat kaalyadong panig (kasama ang kamatayan), ang sinag ng kometa ay ipapaputok sa lahat ng kalaban, na nagdudulot kay Jirachi ng 50%~120% Physical Damage. 天恩: Ang panalangin ni Jirachi sa pagkakataong ito ay may 35% na tsansa na ma-activate ang Heaven’s Blessing at mapalabas ang 3 wish notes nang sabay-sabay.',
		describe_ma = '*Sentiasa ada tempat di mana bintang tidak dapat bersinar...* Jirachi berdoa untuk kekuatan Komet Millennium, dan cahaya bintang memancar dari Mata Kebenaran menyerang semua sasaran musuh, menyebabkan 180% Kerosakan Sihir + Kerosakan Sihir $(skillLevel*4*60)$ dan menghapuskan semua kesan buff pada sasaran utama (1~3 sasaran tambahan). Meteor Beam: Pada pusingan berikutnya, apabila kesan nota harapan di setiap pihak rakan berakhir (termasuk kematian), sinar bintang jatuh akan ditembakkan ke semua musuh, menyebabkan Jirachi memberikan Kerosakan Fizikal 50%~120%. 天恩: Doa Jirachi kali ini mempunyai peluang 35% untuk mengaktifkan Rahmat Syurga dan melepaskan 3 nota harapan serentak.',
		describe = '*There are always places where stars cannot shine...* Jirachi prays for the power of the Millennium Comet, and the light of the stars radiates from the Eye of Truth, attacking all enemy targets, dealing 180% Magic Damage + The Magic Damage $(skillLevel*4*60)$ and removing all buff effects from the main target (1~3 additional targets). Meteor Beam: In the next round, when the wish note effect on each friendly side ends (including death), a comet beam will shoot at all enemies, causing Jirachi to deal 50%~120% Physical Damage. 天恩 (Heaven’s Grace): This time Jirachi\'s prayer has a 35% chance to activate Heaven’s Blessing and release 3 wish notes simultaneously.',
		simDesc_vn = 'Kira cầu nguyện sức mạnh của sao chổi nghìn năm, tấn công toàn bộ mục tiêu của đối phương, xóa bỏ hiệu ứng tăng cường của mục tiêu và khi hiệu ứng Nguyện Giấy trên tất cả đồng minh kết thúc trong lượt tiếp theo, sẽ phát ra Ánh Sáng Sao Băng lên toàn bộ đối phương.',
		simDesc_en = 'Kira prays for the power of the thousand-year comet, attacking all enemy targets, removing their buff effects, and when the Paper Wish effect on all allies ends in the next turn, it will emit a Meteor Light onto all enemies.',
		simDesc_th = 'คิระอธิษฐานขอพลังจากดาวหางพันปี โจมตีเป้าหมายฝ่ายตรงข้ามทั้งหมด ลบล้างเอฟเฟกต์เสริมของเป้าหมาย และเมื่อเอฟเฟกต์คำอธิษฐานกระดาษบนพันธมิตรทั้งหมดสิ้นสุดในเทิร์นถัดไป จะปล่อยแสงดาวตกไปยังฝ่ายตรงข้ามทั้งหมด',
		simDesc_in = 'Kira berdoa untuk kekuatan komet seribu tahun, menyerang semua target musuh, menghapus efek buff dari target, dan ketika efek Doa Kertas pada semua sekutu berakhir pada giliran berikutnya, akan memancarkan Cahaya Meteor ke seluruh musuh.',
		simDesc_ph = 'Nanalangin si Kira sa kapangyarihan ng libong taong kometa, inaatake ang lahat ng mga kalaban, tinatanggal ang mga epekto ng pagpapalakas ng mga target, at kapag natapos ang epekto ng Hiling na Papel sa lahat ng mga kakampi sa susunod na turn, magbubuga ito ng Liwanag ng Shooting Star sa lahat ng mga kalaban.',
		simDesc_ma = 'Kira berdoa kepada kekuatan komet seribu tahun, menyerang semua sasaran musuh, menghapus kesan peningkatan pada sasaran, dan apabila kesan Doa Kertas pada semua sekutu tamat pada giliran berikutnya, ia akan memancarkan Cahaya Bintang Jatuh ke semua musuh.',
		simDesc = 'Kira prays for the power of the thousand-year comet, attacking all enemy targets, removing their buff effects, and when the Paper Wish effect on all allies ends in the next turn, it will emit a Meteor Light onto all enemies.',
		starEffect = __data_t__starEffect[19913],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Mỗi tầng <Nguyện Sao> tăng 30% sát thương sao băng; nếu có ít nhất 2 tầng <Nguyện Sao>, sẽ giải trừ một hiệu ứng tiêu cực cho toàn bộ đồng đội; nếu có ít nhất 3 tầng <Nguyện Sao>, sẽ chắc chắn kích hoạt hiệu ứng Thiên Ân.',
		starEffectDesc = 'Additional effect: Each layer of <Nguyện Sao> increases meteor damage by 30%; if there are at least 2 layers of <Nguyện Sao>, one negative effect will be removed from all teammates; if there are at least 3 layers of <Nguyện Sao>, the Grace effect will be guaranteed to activate.',
		starEffectDesc_en = 'Additional effect: Each layer of <Nguyện Sao> increases meteor damage by 30%; if there are at least 2 layers of <Nguyện Sao>, one negative effect will be removed from all teammates; if there are at least 3 layers of <Nguyện Sao>, the Grace effect will be guaranteed to activate.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ทุกชั้นของ <Nguyện Sao> เพิ่มความเสียหายดาวตกขึ้น 30%; หากมีอย่างน้อย 2 ชั้นของ <Nguyện Sao> จะลบเอฟเฟกต์ลบหนึ่งอย่างของทุกสมาชิกในทีม; หากมีอย่างน้อย 3 ชั้นของ <Nguyện Sao> จะทำให้เอฟเฟกต์ความเมตตาเปิดใช้งานแน่นอน',
		starEffectDesc_in = 'Efek tambahan: Setiap lapisan <Nguyện Sao> meningkatkan kerusakan meteor sebesar 30%; jika ada setidaknya 2 lapisan <Nguyện Sao>, satu efek negatif akan dihapus dari semua rekan satu tim; jika ada setidaknya 3 lapisan <Nguyện Sao>, efek Rahmat akan dipastikan aktif.',
		starEffectDesc_ph = 'Karagdagang epekto: Bawat layer ng <Nguyện Sao> ay nagpapataas ng 30% na pinsala ng meteor; kung mayroong hindi bababa sa 2 layer ng <Nguyện Sao>, aalisin ang isang negatibong epekto para sa lahat ng kasamahan; kung mayroong hindi bababa sa 3 layer ng <Nguyện Sao>, tiyak na maa-activate ang epekto ng Biyaya.',
		starEffectDesc_ma = 'Kesan tambahan: Setiap lapisan <Nguyện Sao> meningkatkan kerosakan meteor sebanyak 30%; jika terdapat sekurang-kurangnya 2 lapisan <Nguyện Sao>, satu kesan negatif akan dihapuskan dari semua rakan sepasukan; jika terdapat sekurang-kurangnya 3 lapisan <Nguyện Sao>, kesan Rahmat pasti akan diaktifkan.',
		upLvDesc = 'Fixed damage +240',
