	[19921] = {
		id = 19921,
		skillName_vn = 'Sự xuất hiện của các vì sao',
		skillName_en = 'The appearance of the stars',
		skillName_th = 'การปรากฏตัวของดวงดาว',
		skillName_in = 'Kemunculan bintang-bintang',
		skillName_ph = 'Ang paglitaw ng mga bituin',
		skillName_ma = 'Kemunculan bintang-bintang',
		skillName = 'The appearance of the stars',
		describe_vn = '#C0xC0C0C0#*Xingxing, vui lòng cho tôi biết~*#C0x5B545B#\n#F10# \n#F40#Jirachi triệu hồi một thiên thạch hạ cánh và tấn công một mục tiêu kẻ thù, gây ra #C0x3D8A99#100% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel* 4*24)$ trong #C0xF13B54# sát thương phép #C0x5B545B#, tăng tốc độ của bản thân thêm 15% trong 2 lượt và có 70% xác suất khiến một người bạn ngẫu nhiên nhận thêm [Wish Note]',
		describe_en = '*Xingxing, please tell me~* \n Jirachi summons a meteor to land and attack an enemy target, dealing 100% Magical Damage + $(skillLevel* 4*24)$ in magical damage, increasing its own speed by 15% for 2 turns and has a 70% chance to grant a random ally an extra [Wish Note].',
		describe_th = '*Xingxing โปรดบอกฉันหน่อย~* \n จิราจิ์เรียกดาวตกลงมาโจมตีเป้าหมายศัตรู สร้างความเสียหายเวทมนตร์ 100% + $(skillLevel* 4*24)$ ในความเสียหายเวทมนตร์ เพิ่มความเร็วของตนเอง 15% เป็นเวลา 2 เทิร์น และมีโอกาส 70% ที่จะมอบ [Wish Note] เพิ่มเติมให้กับเพื่อนร่วมทีมแบบสุ่ม',
		describe_in = '*Xingxing, tolong beri tahu aku~* \n Jirachi memanggil meteor untuk mendarat dan menyerang target musuh, memberikan 100% Kerusakan Magis + $(skillLevel* 4*24)$ dalam kerusakan magis, meningkatkan kecepatannya sendiri sebesar 15% selama 2 giliran dan memiliki 70% peluang untuk memberikan [Wish Note] tambahan kepada sekutu acak.',
		describe_ph = '*Xingxing, pakiusap sabihin mo sa akin~* \n Jirachi ay tumatawag ng isang meteor na lumapag at umatake sa isang target na kalaban, nagdudulot ng 100% Magical Damage + $(skillLevel* 4*24)$ sa magical damage, pinapataas ang sariling bilis ng 15% sa loob ng 2 turno at may 70% tsansang magbigay ng dagdag na [Wish Note] sa isang random na kaalyado.',
		describe_ma = '*Xingxing, sila beritahu saya~* \n Jirachi memanggil meteor untuk mendarat dan menyerang sasaran musuh, menyebabkan 100% Kerosakan Magik + $(skillLevel* 4*24)$ dalam kerosakan magik, meningkatkan kelajuan diri sendiri sebanyak 15% selama 2 pusingan dan mempunyai 70% kebarangkalian untuk memberikan [Wish Note] tambahan kepada rakan secara rawak.',
		describe = '*Xingxing, please tell me~* \n Jirachi summons a meteor to land and attack an enemy target, dealing 100% Magical Damage + $(skillLevel* 4*24)$ in magical damage, increasing its own speed by 15% for 2 turns and has a 70% chance to grant a random ally an extra [Wish Note].',
		upLvDesc = 'Fixed damage +96',
		upLvDesc_en = 'Fixed damage +96',
		upLvDesc_th = 'ความเสียหายคงที่ +96',
		upLvDesc_in = 'Kerusakan tetap +96',
		upLvDesc_ph = 'Fixed damage +96',
