	[19923] = {
		id = 19923,
		skillName_vn = 'Nguyện ước diệt vong',
		skillName_en = 'Wish for ruin',
		skillName_th = 'คำอธิษฐานแห่งความพินาศ',
		skillName_in = 'Harapan kehancuran',
		skillName_ph = 'Pagnanais ng Kabaulakan',
		skillName_ma = 'Harapan kehancuran',
		skillName = 'Wish for ruin',
		describe_vn = '#C0xC0C0C0#*Luôn có những nơi các ngôi sao không thể tỏa sáng...*#C0x5B545B#\n#F10# \n#F40#Jirachi cầu nguyện sức mạnh của Sao chổi Thiên niên kỷ, và ánh sáng của các ngôi sao tỏa ra từ Mắt Sự thật và tấn công tất cả mục tiêu của kẻ thù, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+ The #C0xF13B54# Sát Thương Phép Thuật $(skillLevel*4*60)$#C0x5B545B# loại bỏ mọi hiệu ứng buff của mục tiêu chính (1~3 mục tiêu khác)\n#F20# \n#F40##L10#Meteor Beam: #L0# Ở vòng tiếp theo, khi hiệu ứng ghi chú điều ước trên mỗi bên thân thiện kết thúc (bao gồm cả cái chết), tia sao băng sẽ phóng lên tất cả kẻ thù, khiến Jirachi #C0xE69900#50%~120% Sát Thương Vật Lý #C0x5B545B# sát thương\n#F20# \n#F40##L10#天恩: #L0# Lời cầu nguyện của Jirachi lần này có 35% xác suất kích hoạt Thiên An và giải phóng 3 ghi chú điều ước cùng một lúc.',
		describe_en = '*There are always places where stars cannot shine...* Jirachi prays for the power of the Millennium Comet, and the light of the stars radiates from the Eye of Truth, attacking all enemy targets, dealing 180% Magic Damage + Magic Damage $(skillLevel*4*60)$ and dispelling all buffs from the main target (plus 1~3 other targets). Meteor Beam: In the next turn, when the wish note effect on each friendly side ends (including death), a meteor beam shoots at all enemies, causing Jirachi to deal 50%~120% Physical Damage. Tian En: This time, Jirachi\'s prayer has a 35% chance to trigger Tian An and release 3 wish notes simultaneously.',
		describe_th = '*มีสถานที่ที่ดาวไม่สามารถส่องแสงได้เสมอ...* จิราจิอธิษฐานขอพลังของดาวหางพันปี และแสงของดาวจากดวงตาแห่งความจริงโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวทมนตร์ 180% + ความเสียหายเวทมนตร์ $(skillLevel*4*60)$ และลบเอฟเฟกต์บัฟทั้งหมดของเป้าหมายหลัก (1~3 เป้าหมายอื่น) Meteor Beam: ในรอบถัดไป เมื่อเอฟเฟกต์โน้ตคำอธิษฐานที่ฝ่ายเพื่อนสิ้นสุดลง (รวมถึงการตาย) รังสีดาวตกจะพุ่งใส่ศัตรูทั้งหมด ทำให้จิราจิสร้างความเสียหายกายภาพ 50%~120% Tian En: การอธิษฐานครั้งนี้ของจิราจิมีโอกาส 35% ที่จะทริกเกอร์ Tian An และปล่อยโน้ตคำอธิษฐาน 3 ตัวพร้อมกัน',
		describe_in = '*Selalu ada tempat di mana bintang tidak bisa bersinar...* Jirachi berdoa untuk kekuatan Komet Milenium, dan cahaya bintang dari Mata Kebenaran menyerang semua target musuh, menyebabkan 180% Kerusakan Magis + Kerusakan Magis $(skillLevel*4*60)$ serta menghilangkan semua efek buff dari target utama (1~3 target lain). Meteor Beam: Pada giliran berikutnya, ketika efek catatan harapan pada masing-masing sisi rekan berakhir (termasuk kematian), sinar meteor akan ditembakkan ke semua musuh, menyebabkan Jirachi memberikan 50%~120% Kerusakan Fisik. Tian En: Doa Jirachi kali ini memiliki peluang 35% untuk memicu Tian An dan melepaskan 3 catatan harapan sekaligus.',
		describe_ph = '*Laging may mga lugar kung saan hindi kayang kumislap ang mga bituin...* Nagdarasal si Jirachi para sa kapangyarihan ng Millennium Comet, at ang liwanag ng mga bituin mula sa Mata ng Katotohanan ay sumasalakay sa lahat ng mga kalaban, nagdudulot ng 180% Magic Damage + Magic Damage $(skillLevel*4*60)$ at tinatanggal ang lahat ng buff sa pangunahing target (1~3 na iba pang target). Meteor Beam: Sa susunod na round, kapag natapos ang effect ng wish note sa bawat kaalyadong panig (kasama na ang pagkamatay), ang meteor beam ay tatamaan ang lahat ng kalaban, na nagdudulot kay Jirachi ng 50%~120% Physical Damage. Tian En: Sa pagkakataong ito, may 35% chance ang panalangin ni Jirachi na magtrigger ng Tian An at palayain ang 3 wish notes nang sabay-sabay.',
		describe_ma = '*Sentiasa ada tempat di mana bintang tidak dapat bersinar...* Jirachi berdoa untuk kuasa Komet Milenium, dan cahaya bintang dari Mata Kebenaran menyerang semua sasaran musuh, menyebabkan 180% Kerosakan Sihir + Kerosakan Sihir $(skillLevel*4*60)$ serta menghapus semua kesan buff dari sasaran utama (1~3 sasaran lain). Meteor Beam: Pada pusingan seterusnya, apabila kesan nota harapan pada setiap pihak rakan tamat (termasuk kematian), pancaran bintang jatuh akan melepaskan serangan ke semua musuh, menyebabkan Jirachi memberikan 50%~120% Kerosakan Fizikal. Tian En: Doa Jirachi kali ini mempunyai peluang 35% untuk mencetuskan Tian An dan melepaskan 3 nota harapan sekaligus.',
		describe = '*There are always places where stars cannot shine...* Jirachi prays for the power of the Millennium Comet, and the light of the stars radiates from the Eye of Truth, attacking all enemy targets, dealing 180% Magic Damage + Magic Damage $(skillLevel*4*60)$ and dispelling all buffs from the main target (plus 1~3 other targets). Meteor Beam: In the next turn, when the wish note effect on each friendly side ends (including death), a meteor beam shoots at all enemies, causing Jirachi to deal 50%~120% Physical Damage. Tian En: This time, Jirachi\'s prayer has a 35% chance to trigger Tian An and release 3 wish notes simultaneously.',
		simDesc_vn = 'Kira cầu nguyện sức mạnh của sao chổi nghìn năm, tấn công toàn bộ mục tiêu của đối phương, xóa bỏ hiệu ứng tăng cường của mục tiêu và khi hiệu ứng Nguyện Giấy trên tất cả đồng minh kết thúc trong lượt tiếp theo, sẽ phát ra Ánh Sáng Sao Băng lên toàn bộ đối phương.',
		simDesc_en = 'Kira prays for the power of the thousand-year comet, attacking all enemy targets, removing their buffs, and when the Paper Prayer effect on all allies ends in the next turn, it will unleash Meteor Light on all enemies.',
		simDesc_th = 'คิระอธิษฐานขอพลังของดาวตกพันปี โจมตีเป้าหมายฝ่ายตรงข้ามทั้งหมด ล้างเอฟเฟกต์เพิ่มพลังของเป้าหมาย และเมื่อเอฟเฟกต์คำอธิษฐานกระดาษบนพันธมิตรทั้งหมดสิ้นสุดในเทาถัดไป จะปล่อยแสงดาวตกไปยังฝ่ายตรงข้ามทั้งหมด',
		simDesc_in = 'Kira berdoa untuk kekuatan komet ribuan tahun, menyerang semua target musuh, menghapus efek peningkatan dari target, dan ketika efek Doa Kertas pada semua sekutu berakhir pada giliran berikutnya, akan mengeluarkan Cahaya Meteor ke semua musuh.',
		simDesc_ph = 'Si Kira ay nananalangin sa kapangyarihan ng libong taong kometa, umaatake sa lahat ng kalaban, tinatanggal ang mga epekto ng pagpapalakas sa mga target, at kapag natapos ang epekto ng Panalangin ng Papel sa lahat ng mga kakampi sa susunod na turno, magpapalabas ng Liwanag ng Meteor sa lahat ng kalaban.',
		simDesc_ma = 'Kira berdoa kepada kekuatan komet seribu tahun, menyerang semua sasaran musuh, menghapus kesan peningkatan sasaran, dan apabila kesan Doa Kertas pada semua sekutu berakhir pada giliran berikutnya, akan melepaskan Cahaya Meteor kepada semua musuh.',
		simDesc = 'Kira prays for the power of the thousand-year comet, attacking all enemy targets, removing their buffs, and when the Paper Prayer effect on all allies ends in the next turn, it will unleash Meteor Light on all enemies.',
		starEffect = __data_t__starEffect[19923],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Mỗi tầng <Nguyện Sao> tăng 30% sát thương sao băng; nếu có ít nhất 2 tầng <Nguyện Sao>, sẽ giải trừ một hiệu ứng tiêu cực cho toàn bộ đồng đội; nếu có ít nhất 3 tầng <Nguyện Sao>, sẽ chắc chắn kích hoạt hiệu ứng Thiên Ân.',
		starEffectDesc = 'Additional Effect: Each layer of <#Wishing Star#> increases shooting star damage by 30%; if there are at least 2 layers of <#Wishing Star#>, one negative effect will be removed for the entire team; if there are at least 3 layers of <#Wishing Star#>, the Blessing effect will be guaranteed to activate.',
		starEffectDesc_en = 'Additional Effect: Each layer of <#Wishing Star#> increases shooting star damage by 30%; if there are at least 2 layers of <#Wishing Star#>, one negative effect will be removed for the entire team; if there are at least 3 layers of <#Wishing Star#>, the Blessing effect will be guaranteed to activate.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: แต่ละชั้นของ <#Wishing Star#> เพิ่มความเสียหายดาวตก 30%; ถ้ามีชั้นของ <#Wishing Star#> อย่างน้อย 2 ชั้น จะลบเอฟเฟกต์ลบหนึ่งอย่างให้กับทีมทั้งหมด; ถ้ามีชั้นของ <#Wishing Star#> อย่างน้อย 3 ชั้น จะทำให้เอฟเฟกต์ Blessing แน่นอนที่จะถูกเปิดใช้งาน',
		starEffectDesc_in = 'Efek Tambahan: Setiap lapisan <#Wishing Star#> meningkatkan kerusakan bintang jatuh sebesar 30%; jika ada setidaknya 2 lapisan <#Wishing Star#>, satu efek negatif akan dihapus untuk seluruh tim; jika ada setidaknya 3 lapisan <#Wishing Star#>, efek Blessing pasti akan aktif.',
		starEffectDesc_ph = 'Karagdagang Epekto: Bawat antas ng <#Wishing Star#> ay nagpapataas ng 30% na pinsala ng shooting star; kung may hindi bababa sa 2 antas ng <#Wishing Star#>, aalisin ang isang negatibong epekto para sa buong koponan; kung may hindi bababa sa 3 antas ng <#Wishing Star#>, tiyak na mae-activate ang epekto ng Blessing.',
		starEffectDesc_ma = 'Kesan Tambahan: Setiap lapisan <#Wishing Star#> meningkatkan kerosakan bintang jatuh sebanyak 30%; jika terdapat sekurang-kurangnya 2 lapisan <#Wishing Star#>, satu kesan negatif akan dikeluarkan untuk semua pasukan; jika terdapat sekurang-kurangnya 3 lapisan <#Wishing Star#>, kesan Blessing pasti akan diaktifkan.',
		upLvDesc = 'Fixed damage +240',
