	[20113] = {
		id = 20113,
		skillName_vn = 'Tia sáng mặt trời',
		skillName_en = 'Sunlight',
		skillName_th = 'แสงแดด',
		skillName_in = 'Cahaya matahari',
		skillName_ph = 'Sikat ng araw',
		skillName_ma = 'Cahaya matahari',
		skillName = 'Sunlight',
		describe_vn = 'Rùa Cỏ hấp thụ ánh sáng mặt trời, phát ra chùm năng lượng từ cơ thể tấn công toàn bộ mục tiêu kẻ địch, gây ra #C0xE69900#110% Công Vật Lý#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, dây leo từ dưới đất mọc lên, có 30% xác suất khiến kẻ địch [trói buộc] trong 1 lượt (trói buộc: hiệu ứng kiểm soát, không thể hành động, có thể bị phá hủy bởi đốt cháy)',
		describe_en = 'The Grass Turtle absorbs sunlight and emits a beam of energy from its body to attack all enemy targets, dealing #C0xE69900#110% Physical Attack#C0x5B545B# + $(skillLevel*4*30)$ #C0xF13B54# Physical Damage#C0x5B545B#. Vines grow from the ground with a 30% chance to [bind] enemies for 1 turn (bind: a control effect, unable to act, can be broken by burn).',
		describe_th = 'เต่าหญ้า ดูดซับแสงอาทิตย์และปล่อยลำแสงพลังงานจากร่างกายโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายทางกายภาพ #C0xE69900#110%#C0x5B545B# + $(skillLevel*4*30)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เถาวัลย์ขึ้นมาจากพื้น มีโอกาส 30% ที่จะ[trói buộc] ศัตรูเป็นเวลา 1 เทิร์น (trói buộc: เอฟเฟกต์ควบคุม ไม่สามารถกระทำได้ สามารถถูกทำลายโดยการเผาไหม้)',
		describe_in = 'Kura Rumput menyerap sinar matahari dan memancarkan gelombang energi dari tubuhnya yang menyerang semua target musuh, menyebabkan #C0xE69900#110% Serangan Fisik#C0x5B545B# + $(skillLevel*4*30)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Sulur tumbuh dari tanah, dengan peluang 30% untuk [trói buộc] musuh selama 1 giliran (trói buộc: efek kontrol, tidak bisa bertindak, bisa dihancurkan oleh api).',
		describe_ph = 'Ang Grass Turtle ay sumisipsip ng sikat ng araw at naglalabas ng sinag ng enerhiya mula sa katawan upang atakihin ang lahat ng mga target na kaaway, na nagdudulot ng #C0xE69900#110% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*30)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Ang mga baging ay tumutubo mula sa lupa, may 30% na tsansa na [trói buộc] ang mga kalaban sa loob ng 1 turn (trói buộc: isang kontrol na epekto, hindi makakilos, maaaring masira ng pagsunog).',
		describe_ma = 'Kura Rumput menyerap cahaya matahari dan memancarkan pancaran tenaga dari badannya untuk menyerang semua sasaran musuh, menyebabkan #C0xE69900#110% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*30)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Pokok renek tumbuh dari tanah, mempunyai peluang 30% untuk [trói buộc] musuh selama 1 pusingan (trói buộc: efek kawalan, tidak dapat bertindak, boleh dihancurkan oleh kebakaran).',
		describe = 'The Grass Turtle absorbs sunlight and emits a beam of energy from its body to attack all enemy targets, dealing #C0xE69900#110% Physical Attack#C0x5B545B# + $(skillLevel*4*30)$ #C0xF13B54# Physical Damage#C0x5B545B#. Vines grow from the ground with a 30% chance to [bind] enemies for 1 turn (bind: a control effect, unable to act, can be broken by burn).',
		simDesc_vn = 'Cỏ Mầm Rùa hấp thụ ánh sáng mặt trời, phát ra chùm năng lượng tấn công toàn bộ mục tiêu của đối phương, có khả năng khiến mục tiêu không thể hành động.',
		simDesc_en = 'The Turtle Sprout Grass absorbs sunlight and emits an energy beam that attacks all enemy targets, with the ability to prevent them from taking any actions.',
		simDesc_th = 'หญ้าเต่าซึมซับแสงแดดและปล่อยลำแสงพลังงานโจมตีเป้าหมายฝ่ายตรงข้ามทั้งหมด มีความสามารถทำให้เป้าหมายไม่สามารถเคลื่อนไหวได้',
		simDesc_in = 'Rumput Tunas Kura-kura menyerap sinar matahari dan memancarkan sinar energi yang menyerang semua target lawan, dengan kemampuan membuat target tidak dapat bertindak.',
