	[20216] = {
		id = 20216,
		skillName_vn = 'Lửa thiêu đốt trái tim',
		skillName_en = 'The fire burns the heart',
		skillName_th = 'ไฟเผาทำลายหัวใจ',
		skillName_in = 'Api membakar hati',
		skillName_ph = 'Apoy na sinusunog ang puso',
		skillName_ma = 'Api membakar hati',
		skillName = 'The fire burns the heart',
		describe_vn = '#L10#Fire Burning Heart: #L0#Khi giá trị máu giảm xuống dưới 40%, có xác suất bằng tỷ lệ máu đã mất để kích hoạt tái sinh trong lửa, phục hồi 100% máu và vào trạng thái [Linh hồn đốt cháy],\nĐốt cháy linh hồn: hiệu ứng đặc biệt, tốc độ, tỷ lệ chí mạng và sát thương chí mạng tăng lên #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, sau đó đốt 20% máu tối đa của một người trước lượt của mỗi người\n#F20# \n#F40##L10# Đấm đấm theo cặp: #L0# Nếu tốc độ của bản thân cao hơn mục tiêu 25% khi tấn công, có xác suất 50% (100% ở trạng thái đốt cháy linh hồn) để kích hoạt Đấu kiếm theo cặp và mỗi đòn tấn công sẽ bổ sung thêm #C0x3D8A99# của cùng một kỹ năng thuộc loại tấn công đặc biệt #C0x5B545B#',
		describe_en = '#L10#Fire Burning Heart: #L0#When HP drops below 40%, there is a chance equal to the lost HP percentage to trigger resurrection in flames, restoring 100% HP and entering the [Burning Soul] state. \n Burning Soul: special effect, increases speed, critical rate, and critical damage by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, then burns 20% of a person\'s max HP before each turn. \n #F20# \n #F40# #L10#Paired Punch: #L0# If your speed is 25% higher than the target when attacking, there is a 50% chance (100% in Burning Soul state) to activate Paired Swordfighting, and each attack adds #C0x3D8A99# damage from the same special attack skill #C0x5B545B#.',
		describe_th = '#L10#หัวใจลุกไหม้: #L0#เมื่อค่าพลังชีวิตลดลงต่ำกว่า 40% มีโอกาสเท่ากับอัตราส่วนของพลังชีวิตที่เสียไปในการเปิดใช้งานการเกิดใหม่ในไฟ ฟื้นฟูพลังชีวิต 100% และเข้าสู่สถานะ [วิญญาณลุกไหม้] \n วิญญาณลุกไหม้: เอฟเฟกต์พิเศษ เพิ่มความเร็ว อัตราคริติคอล และความเสียหายคริติคอลขึ้น #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# จากนั้นเผาผลาญพลังชีวิตสูงสุดของเป้าหมาย 20% ก่อนเทิร์นของแต่ละคน \n #F20# \n #F40# #L10# หมัดคู่: #L0# ถ้าความเร็วของตัวเองสูงกว่าเป้าหมาย 25% เมื่อโจมตี มีโอกาส 50% (100% ในสถานะวิญญาณลุกไหม้) ที่จะเปิดใช้งานการดวลดาบคู่ และทุกการโจมตีจะเพิ่ม #C0x3D8A99# ของสกิลประเภทการโจมตีพิเศษเดียวกัน #C0x5B545B#',
		describe_in = '#L10#Fire Burning Heart: #L0#Ketika nilai HP turun di bawah 40%, ada peluang sesuai persentase HP yang hilang untuk mengaktifkan kebangkitan dalam api, memulihkan 100% HP dan memasuki status [Jiwa Membara]. \n Jiwa Membara: efek khusus, kecepatan, tingkat kritis, dan kerusakan kritis meningkat sebesar #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, kemudian membakar 20% HP maksimal satu orang sebelum giliran setiap orang. \n #F20# \n #F40# #L10#Pukulan Berpasangan: #L0# Jika kecepatan Anda 25% lebih tinggi dari target saat menyerang, ada peluang 50% (100% saat dalam status Jiwa Membara) untuk mengaktifkan Duel Pedang Berpasangan dan setiap serangan akan menambahkan #C0x3D8A99# dari keterampilan serangan spesial yang sama #C0x5B545B#.',
		describe_ph = '#L10#Fire Burning Heart: #L0#Kapag bumaba ang HP ng mas mababa sa 40%, may tsansa na katumbas ng nawalang porsyento ng HP upang i-activate ang muling pagsilang sa apoy, mapanumbalik ang 100% HP at mapasok ang estado ng [Burning Soul]. \n Burning Soul: espesyal na epektong nagpapataas ng bilis, critical rate, at critical damage ng #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, pagkatapos ay sinusunog ang 20% ng maximum HP ng isang tao bago ang bawat turn. \n #F20# \n #F40# #L10#Paired Punch: #L0# Kung ang bilis mo ay 25% mas mataas kaysa sa target kapag umaatake, may 50% na tsansa (100% sa estado ng Burning Soul) na i-activate ang Paired Swordfighting at bawat atake ay magdaragdag ng #C0x3D8A99# mula sa parehong espesyal na uri ng skill sa pag-atake #C0x5B545B#.',
		describe_ma = '#L10#Fire Burning Heart: #L0#Apabila nilai darah menurun di bawah 40%, terdapat peluang sama dengan peratusan darah yang hilang untuk mengaktifkan kebangkitan dalam api, memulihkan 100% darah dan memasuki keadaan [Jiwa Membara]. \n Jiwa Membara: kesan khas, meningkatkan kelajuan, kadar kritikal dan kerosakan kritikal sebanyak #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, kemudian membakar 20% darah maksimum seseorang sebelum giliran setiap orang. \n #F20# \n #F40# #L10#Pukulan Berpasangan: #L0# Jika kelajuan sendiri 25% lebih tinggi daripada sasaran semasa menyerang, ada peluang 50% (100% dalam keadaan Jiwa Membara) untuk mengaktifkan Duel Pedang Berpasangan dan setiap serangan akan menambah #C0x3D8A99# dari kemahiran khas jenis serangan yang sama #C0x5B545B#.',
		describe = '#L10#Fire Burning Heart: #L0#When HP drops below 40%, there is a chance equal to the lost HP percentage to trigger resurrection in flames, restoring 100% HP and entering the [Burning Soul] state. \n Burning Soul: special effect, increases speed, critical rate, and critical damage by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, then burns 20% of a person\'s max HP before each turn. \n #F20# \n #F40# #L10#Paired Punch: #L0# If your speed is 25% higher than the target when attacking, there is a 50% chance (100% in Burning Soul state) to activate Paired Swordfighting, and each attack adds #C0x3D8A99# damage from the same special attack skill #C0x5B545B#.',
		starEffect = __data_t__starEffect[20216],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Trong trạng thái <Nhiệt Hồn>, trước mỗi lượt của kẻ địch, hồi phục 40% máu đã mất.',
		starEffectDesc = 'Additional Effect: While in the <Fiery Spirit> state, restore 40% of lost HP before each enemy\'s turn.',
		starEffectDesc_en = 'Additional Effect: While in the <Fiery Spirit> state, restore 40% of lost HP before each enemy\'s turn.',
		starEffectDesc_th = 'ผลเสริม: ในสถานะ <วิญญาณร้อนแรง> ฟื้นฟูพลังชีวิตที่เสียไป 40% ก่อนเทิร์นของศัตรูแต่ละคน',
		starEffectDesc_in = 'Efek Tambahan: Dalam keadaan <Semangat Berapi>, pulihkan 40% HP yang hilang sebelum giliran musuh setiap kali.',
		starEffectDesc_ph = 'Karagdagang Epekto: Sa estado ng <Nagsisiglang Apoy>, ibalik ang 40% ng nawalang HP bago ang bawat turno ng kalaban.',
		starEffectDesc_ma = 'Kesan Tambahan: Dalam keadaan <Semangat Berapi>, pulihkan 40% HP yang hilang sebelum giliran musuh setiap kali.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 2,
		skillType2 = 3,
