	[20223] = {
		id = 20223,
		skillName_vn = 'Xung phong lửa chớp',
		skillName_en = 'Charge the lightning fire',
		skillName_th = 'บุกไฟฟ้าฟ้าผ่า',
		skillName_in = 'Maju api petir',
		skillName_ph = 'Sugod ang apoy ng kidlat',
		skillName_ma = 'Maju api kilat',
		skillName = 'Charge the lightning fire',
		describe_vn = 'Khỉ Lửa Mạnh nhảy lên tung cú đấm lửa vào mục tiêu đơn, gây #C0xE69900#530% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, mất 8% máu hiện tại của bản thân, thêm [Lửa Cháy] 1 lượt cho mục tiêu (Lửa Cháy: hiệu ứng tiêu cực, tăng 20% sát thương thuộc tính lửa, có thể xóa, không thể cộng dồn, sau lượt của mục tiêu sẽ phát nổ, gây sát thương bằng #C0xE69900#100% Công Vật Lý#C0x5B545B# của Khỉ Lửa Mạnh (có thể chí mạng), sau đó chuyển thành hiệu ứng đốt cháy trong 2 lượt, khi thêm Lửa Cháy lặp lại sẽ phát nổ ngay lập tức)',
		describe_en = 'Strong Fire Monkey jumps up and unleashes a fire punch on a single target, dealing #C0xE69900#530% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#, consuming 8% of its current HP, and applying [Burning Fire] on the target for 1 turn (Burning Fire: a debuff that increases fire attribute damage by 20%, can be removed, does not stack, explodes after the target\'s turn dealing damage equal to #C0xE69900#100% Physical Attack#C0x5B545B# of Strong Fire Monkey (can crit), then transforms into a burning effect for 2 turns. If Burning Fire is applied again, it explodes immediately).',
		describe_th = 'ลิงไฟแข็งกระโดดขึ้นและปล่อยหมัดไฟใส่เป้าหมายเดี่ยว สร้างความเสียหาย #C0xE69900#530% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ใช้เลือดตัวเอง 8% และติดสถานะ [ไฟลุกโชน] ให้กับเป้าหมาย 1 เทิร์น (ไฟลุกโชน: เอฟเฟกต์ลบ เพิ่มความเสียหายธาตุไฟ 20% สามารถลบได้ ไม่ซ้อนทับ หลังเทิร์นของเป้าหมายจะระเบิด สร้างความเสียหายเท่ากับ #C0xE69900#100% พลังโจมตีทางกายภาพ#C0x5B545B# ของลิงไฟแข็ง (มีโอกาสคริติคอล) จากนั้นเปลี่ยนเป็นสถานะไฟไหม้ 2 เทิร์น หากเพิ่มไฟลุกโชนซ้ำจะระเบิดทันที)',
		describe_in = 'Monyet Api Kuat melompat dan melancarkan pukulan api ke satu target, menyebabkan #C0xE69900#530% Serangan Fisik#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, mengorbankan 8% HP saat ini, dan menambahkan [Api Membara] 1 giliran untuk target (Api Membara: efek negatif yang meningkatkan 20% damage atribut api, bisa dihapus, tidak bisa ditumpuk, meledak setelah giliran target, menyebabkan damage sebesar #C0xE69900#100% Serangan Fisik#C0x5B545B# milik Monyet Api Kuat (bisa kritikal), kemudian berubah menjadi efek terbakar selama 2 giliran, jika Api Membara ditambahkan lagi akan meledak segera).',
		describe_ph = 'Malakas na Apoy na Unggoy ang tumatalon pataas at nagpapakawala ng suntok ng apoy sa isang target, na nagdudulot ng #C0xE69900#530% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, nawalan ng 8% ng kasalukuyang HP, nagdadagdag ng [Naglalagablab na Apoy] ng 1 turn sa target (Naglalagablab na Apoy: negatibong epekto na nagpapataas ng 20% pinsalang apoy, maaaring alisin, hindi pwedeng mag-stack, sasabog pagkatapos ng turn ng target na nagdudulot ng pinsala katumbas ng #C0xE69900#100% Pisikal na Atake#C0x5B545B# ng Malakas na Apoy na Unggoy (pwedeng kritikal), pagkatapos ay magbabago sa nasusunog na epekto sa loob ng 2 turn, kapag muling inapply ang Naglalagablab na Apoy ay sasabog agad).',
		describe_ma = 'Monyet Api Kuat melompat dan melancarkan pukulan api ke sasaran tunggal, menyebabkan #C0xE69900#530% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, kehilangan 8% darah semasa, menambah [Api Membara] selama 1 pusingan untuk sasaran (Api Membara: kesan negatif yang meningkatkan 20% kerosakan atribut api, boleh dipadamkan, tidak boleh bertindih, selepas giliran sasaran akan meletup, menyebabkan kerosakan sebanyak #C0xE69900#100% Serangan Fizikal#C0x5B545B# daripada Monyet Api Kuat (boleh kritikal), kemudian berubah menjadi kesan terbakar selama 2 pusingan, apabila Api Membara ditambah lagi akan meletup serta-merta).',
		describe = 'Strong Fire Monkey jumps up and unleashes a fire punch on a single target, dealing #C0xE69900#530% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#, consuming 8% of its current HP, and applying [Burning Fire] on the target for 1 turn (Burning Fire: a debuff that increases fire attribute damage by 20%, can be removed, does not stack, explodes after the target\'s turn dealing damage equal to #C0xE69900#100% Physical Attack#C0x5B545B# of Strong Fire Monkey (can crit), then transforms into a burning effect for 2 turns. If Burning Fire is applied again, it explodes immediately).',
		simDesc_vn = 'Mãnh Hỏa bao phủ toàn thân bằng ngọn lửa từ trên cao rơi xuống tấn công mục tiêu đơn lẻ của đối phương, mất một phần sinh lực của bản thân, gây hiệu ứng [Nóng Bỏng] cho mục tiêu.',
		simDesc_en = 'Flames engulf the entire body, raining down from above to attack a single enemy target, sacrificing some of the user\'s vitality and inflicting the <Burning> status effect on the target.',
		simDesc_th = 'เปลวไฟปกคลุมร่างกายทั้งหมดจากด้านบนตกลงโจมตีเป้าหมายเดียวของศัตรู สูญเสียพลังชีวิตบางส่วนของตนเอง และทำให้เป้าหมายได้รับสถานะ [ถูกเผาไหม้]',
		simDesc_in = 'Api menyelimuti seluruh tubuh, jatuh dari atas untuk menyerang satu target lawan, mengorbankan sebagian vitalitas sendiri dan memberikan efek <Terbakar> kepada target.',
		simDesc_ph = 'Apoy ay bumabalot sa buong katawan, bumabagsak mula sa itaas upang atakihin ang isang target ng kalaban, nawawala ang ilang lakas ng buhay ng sarili at nagdudulot ng epekto na <Nasusunog> sa target.',
		simDesc_ma = 'Api menyelubungi seluruh badan dari atas jatuh menyerang satu sasaran musuh, mengorbankan sebahagian tenaga hidup sendiri dan menyebabkan kesan <Terbakar> pada sasaran.',
		simDesc = 'Flames engulf the entire body, raining down from above to attack a single enemy target, sacrificing some of the user\'s vitality and inflicting the [Burning] status effect on the target.',
		starEffect = __data_t__starEffect[20223],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sau khi sử dụng kỹ năng đặc biệt, nếu lần đầu tiên nhận sát thương chí mạng, có 80% xác suất ngay lập tức vào trạng thái <Nhiệt Hồn>.',
		starEffectDesc = 'Additional effect: After using the special skill, if receiving critical damage for the first time, there is an 80% chance to immediately enter <Nhiệt Hồn> state.',
		starEffectDesc_en = 'Additional effect: After using the special skill, if receiving critical damage for the first time, there is an 80% chance to immediately enter <Nhiệt Hồn> state.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: หลังจากใช้ทักษะพิเศษ หากได้รับความเสียหายคริติคอลเป็นครั้งแรก จะมีโอกาส 80% ที่จะเข้าสู่สถานะ <Nhiệt Hồn> ทันที',
		starEffectDesc_in = 'Efek tambahan: Setelah menggunakan skill khusus, jika menerima kerusakan kritis untuk pertama kalinya, ada peluang 80% untuk langsung memasuki keadaan <Nhiệt Hồn>.',
