	[20236] = {
		id = 20236,
		skillName_vn = 'Kẻ sát thần',
		skillName_en = 'Killer God',
		skillName_th = 'เทพนักฆ่า',
		skillName_in = 'Dewa Pembunuh',
		skillName_ph = 'Murderer God',
		skillName_ma = 'Dewa Pembunuh',
		skillName = 'Killer God',
		describe_vn = '#L10#Fire Burning Heart: #L0#Khi giá trị máu giảm xuống dưới 40%, có xác suất bằng tỷ lệ máu đã mất để kích hoạt tái sinh trong lửa, phục hồi 100% máu và vào trạng thái [Linh hồn đốt cháy],\nĐốt cháy linh hồn: hiệu ứng đặc biệt, tốc độ, tỷ lệ chí mạng và sát thương chí mạng tăng lên #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, sau đó đốt 20% máu tối đa của một người trước lượt của mỗi người\n#F20# \n#F40##L10#God Eater: #L0# Nếu tốc độ của bản thân cao hơn mục tiêu 25% khi tấn công, có xác suất 50% (100% ở trạng thái đốt cháy linh hồn) kích hoạt God Eater. Mỗi đòn tấn công sẽ thêm một #C0x3D8A99#loại tấn công đặc biệt #C0x5B545B# của cùng một kỹ năng.',
		describe_en = '#L10#Fire Burning Heart: #L0#When health drops below 40%, there is a chance equal to the percentage of health lost to trigger regeneration in flames, restoring 100% health and entering the [Burning Soul] state, \nBurning Soul: special effect, speed, critical rate, and critical damage increase by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, then burn 20% of the maximum health of one person before each person\'s turn \n#F20# \n#F40##L10#God Eater: #L0#If your speed is 25% higher than the target when attacking, there is a 50% chance (100% chance when in Burning Soul state) to activate God Eater. Each attack adds one #C0x3D8A99#special attack type #C0x5B545B# of the same skill.',
		describe_th = '#L10#Fire Burning Heart: #L0#เมื่อค่าพลังชีวิตลดลงต่ำกว่า 40% จะมีโอกาสเท่ากับสัดส่วนของพลังชีวิตที่เสียไปในการเปิดใช้งานการฟื้นฟูในเปลวไฟ ฟื้นฟูพลังชีวิต 100% และเข้าสู่สถานะ [วิญญาณลุกไหม้], \nวิญญาณลุกไหม้: เอฟเฟกต์พิเศษ ความเร็ว อัตราคริติคอล และความเสียหายคริติคอลเพิ่มขึ้น #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# จากนั้นเผา 20% ของพลังชีวิตสูงสุดของหนึ่งคนก่อนรอบของทุกคน \n#F20# \n#F40##L10#God Eater: #L0#ถ้าความเร็วของตนเองมากกว่าศัตรู 25% เมื่อโจมตี จะมีโอกาส 50% (100% ในสถานะวิญญาณลุกไหม้) ในการเปิดใช้งาน God Eater การโจมตีแต่ละครั้งจะเพิ่ม #C0x3D8A99#ชนิดการโจมตีพิเศษ #C0x5B545B# ของทักษะเดียวกัน',
		describe_in = '#L10#Fire Burning Heart: #L0#Ketika nilai darah turun di bawah 40%, ada kemungkinan sesuai dengan persentase darah yang hilang untuk mengaktifkan regenerasi dalam api, memulihkan 100% darah dan memasuki keadaan [Burning Soul], \nBurning Soul: efek khusus, kecepatan, tingkat kritis, dan kerusakan kritis meningkat sebesar #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, kemudian membakar 20% darah maksimum satu orang sebelum giliran setiap orang \n#F20# \n#F40##L10#God Eater: #L0#Jika kecepatan sendiri 25% lebih tinggi dari target saat menyerang, ada kemungkinan 50% (100% saat dalam keadaan Burning Soul) untuk mengaktifkan God Eater. Setiap serangan akan menambahkan satu #C0x3D8A99#jenis serangan khusus #C0x5B545B# dari keterampilan yang sama.',
		describe_ph = '#L10#Fire Burning Heart: #L0#Kapag bumaba ang halaga ng buhay sa ibaba ng 40%, may pagkakataon na katumbas ng porsyento ng nawalang buhay upang ma-activate ang pag-regenerate sa apoy, nakakabawi ng 100% buhay at pumapasok sa estado ng [Burning Soul], \nBurning Soul: espesyal na epekto, bilis, critical rate, at critical damage ay tumataas ng #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, pagkatapos ay sinusunog ang 20% ng pinakamataas na buhay ng isang tao bago ang turn ng bawat tao \n#F20# \n#F40##L10#God Eater: #L0#Kung ang bilis mo ay 25% mas mataas kaysa sa target kapag umaatake, may 50% (100% sa Burning Soul state) chance na ma-activate ang God Eater. Bawat atake ay magdadagdag ng isang #C0x3D8A99#uri ng espesyal na pag-atake #C0x5B545B# ng parehong kasanayan.',
		describe_ma = '#L10#Fire Burning Heart: #L0#Apabila nilai darah turun di bawah 40%, terdapat kebarangkalian sama dengan peratusan darah yang hilang untuk mengaktifkan regenerasi dalam api, memulihkan 100% darah dan memasuki keadaan [Burning Soul], \nBurning Soul: kesan khas, kelajuan, kadar kritikal, dan kerosakan kritikal meningkat sebanyak #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, kemudian membakar 20% darah maksimum seseorang sebelum giliran setiap orang \n#F20# \n#F40##L10#God Eater: #L0#Jika kelajuan sendiri 25% lebih tinggi daripada sasaran ketika menyerang, terdapat kebarangkalian 50% (100% dalam keadaan Burning Soul) untuk mengaktifkan God Eater. Setiap serangan akan menambah satu #C0x3D8A99#jenis serangan khas #C0x5B545B# daripada kemahiran yang sama.',
		describe = '#L10#Fire Burning Heart: #L0#When health drops below 40%, there is a chance equal to the percentage of health lost to trigger regeneration in flames, restoring 100% health and entering the [Burning Soul] state, \nBurning Soul: special effect, speed, critical rate, and critical damage increase by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, then burn 20% of the maximum health of one person before each person\'s turn \n#F20# \n#F40##L10#God Eater: #L0#If your speed is 25% higher than the target when attacking, there is a 50% chance (100% chance when in Burning Soul state) to activate God Eater. Each attack adds one #C0x3D8A99#special attack type #C0x5B545B# of the same skill.',
		starEffect = __data_t__starEffect[20236],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Trong trạng thái <Nhiệt Hồn>, trước mỗi lượt của kẻ địch, hồi phục 40% máu đã mất.',
		starEffectDesc = 'Additional Effect: While in the <Fiery Spirit> state, restore 40% of lost HP before each enemy\'s turn.',
		starEffectDesc_en = 'Additional Effect: While in the <Fiery Spirit> state, restore 40% of lost HP before each enemy\'s turn.',
		starEffectDesc_th = 'ผลเสริม: ในสถานะ <วิญญาณร้อนแรง> ฟื้นฟูพลังชีวิตที่เสียไป 40% ก่อนเทิร์นของศัตรูแต่ละคน',
		starEffectDesc_in = 'Efek Tambahan: Dalam keadaan <Semangat Berapi>, pulihkan 40% HP yang hilang sebelum giliran musuh setiap kali.',
		starEffectDesc_ph = 'Karagdagang Epekto: Sa estado ng <Nagsisiglang Apoy>, ibalik ang 40% ng nawalang HP bago ang bawat turno ng kalaban.',
		starEffectDesc_ma = 'Kesan Tambahan: Dalam keadaan <Semangat Berapi>, pulihkan 40% HP yang hilang sebelum giliran musuh setiap kali.',
