	[20316] = {
		id = 20316,
		skillName_vn = 'Kiên nhẫn',
		skillName_en = 'Patience',
		skillName_th = 'ความอดทน',
		skillName_in = 'Kesabaran',
		skillName_ph = 'Pasensya',
		skillName_ma = 'Kesabaran',
		skillName = 'Patience',
		describe_vn = 'Khi vào trận chiến, vĩnh viễn tăng 30% kháng chí mạng cho bản thân, mỗi lần bị tấn công trước sẽ tăng #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Phép Phòng trong 1 lượt (không thể xóa, tối đa 4 tầng), khi tấn công sẽ tạm thời tăng Phép Công tương đương với lượng Phép Phòng tăng cường này',
		describe_en = 'Upon entering battle, permanently increase Critical Resistance by 30% for yourself. Each time you are attacked first, increase Magic Defense by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# for 1 turn (cannot be removed, up to 4 stacks). When attacking, temporarily increase Magic Attack by the amount of this enhanced Magic Defense.',
		describe_th = 'เมื่อเข้าสู่การต่อสู้ เพิ่มความต้านทานคริติคอลให้ตัวเองตลอดไป 30% ทุกครั้งที่ถูกโจมตีก่อน จะเพิ่มค่าป้องกันเวทมนตร์ #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# เป็นเวลา 1 เทิร์น (ไม่สามารถลบได้ สูงสุด 4 ชั้น) เมื่อโจมตี จะเพิ่มพลังโจมตีเวทมนตร์ชั่วคราวเท่ากับค่าป้องกันเวทมนตร์ที่เพิ่มขึ้นนี้',
		describe_in = 'Saat memasuki pertempuran, tingkatkan kekebalan kritis sebesar 30% secara permanen untuk diri sendiri. Setiap kali diserang terlebih dahulu, tingkatkan Pertahanan Sihir sebesar #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# selama 1 giliran (tidak dapat dihapus, maksimum 4 lapisan). Saat menyerang, tingkatkan Serangan Sihir sementara sesuai dengan peningkatan Pertahanan Sihir ini.',
		describe_ph = 'Kapag pumasok sa laban,永久 na madagdagan ng 30% ang Laban sa Kritikal para sa sarili. Sa bawat unang pag-atake sa iyo, tataas ang Magic Defense ng #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# sa loob ng 1 turn (hindi maaaring tanggalin, hanggang sa max na 4 na stack). Kapag umaatake, pansamantalang nadaragdagan ang Magic Attack na katumbas ng pagtaas ng Magic Defense na ito.',
		describe_ma = 'Apabila memasuki pertempuran, tingkatkan Ketahanan Kritikal sebanyak 30% secara kekal untuk diri sendiri. Setiap kali diserang terlebih dahulu, tingkatkan Pertahanan Sihir sebanyak #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# selama 1 pusingan (tidak boleh dipadam, maksimum 4 lapisan). Ketika menyerang, tingkatkan Serangan Sihir sementara mengikut jumlah Pertahanan Sihir yang diperkuat ini.',
		describe = 'Upon entering battle, permanently increase Critical Resistance by 30% for yourself. Each time you are attacked first, increase Magic Defense by #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# for 1 turn (cannot be removed, up to 4 stacks). When attacking, temporarily increase Magic Attack by the amount of this enhanced Magic Defense.',
		starEffect = __data_t__starEffect[20316],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi bị tấn công, nếu tổng số hiệu ứng tiêu cực và kiểm soát trên bản thân vượt quá 3, sẽ ngay lập tức giải trừ tất cả hiệu ứng kiểm soát và hồi phục 600 điểm năng lượng; hiệu ứng này có thời gian hồi chiêu 2 lượt.',
		starEffectDesc = 'Additional effect: When attacked, if the total number of negative effects and control effects on yourself exceeds 3, immediately dispel all control effects and recover 600 energy points; this effect has a cooldown of 2 turns.',
		starEffectDesc_en = 'Additional effect: When attacked, if the total number of negative effects and control effects on yourself exceeds 3, immediately dispel all control effects and recover 600 energy points; this effect has a cooldown of 2 turns.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อถูกโจมตี หากจำนวนรวมของเอฟเฟกต์ลบและเอฟเฟกต์ควบคุมบนตัวเองเกิน 3 จะทำการปลดปล่อยเอฟเฟกต์ควบคุมทั้งหมดทันทีและฟื้นฟูพลังงาน 600 คะแนน; เอฟเฟกต์นี้มีเวลาคูลดาวน์ 2 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Saat diserang, jika jumlah total efek negatif dan kontrol pada diri sendiri melebihi 3, segera hilangkan semua efek kontrol dan pulihkan 600 poin energi; efek ini memiliki cooldown selama 2 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag inatake, kung ang kabuuang bilang ng negatibong epekto at kontrol sa sarili ay lumagpas sa 3, agad na alisin lahat ng epekto ng kontrol at mag-recover ng 600 energy points; ang epekto na ito ay may cooldown na 2 na turn.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila diserang, jika jumlah kesan negatif dan kawalan ke atas diri sendiri melebihi 3, segera hilangkan semua kesan kawalan dan pulihkan 600 mata tenaga; kesan ini mempunyai masa pemulihan selama 2 pusingan.',
		zawakeEffect = __data_t__zawakeEffect[20316],
		-- {79004}
		zawakeEffectDesc = 'Enter the battle with a permanent 30% increase to your own critical resistance, each time attacked before increasing #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Magic Defense and 10% damage reduction for 1 turn (cannot be removed, up to 4 stacks), when attacking temporarily increase Magic Attack by the amount of the enhanced Magic Defense.',
		zawakeEffectDesc_en = 'Enter the battle with a permanent 30% increase to your own critical resistance, each time attacked before increasing #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Magic Defense and 10% damage reduction for 1 turn (cannot be removed, up to 4 stacks), when attacking temporarily increase Magic Attack by the amount of the enhanced Magic Defense.',
		zawakeEffectDesc_th = 'เข้าสู่การต่อสู้โดยเพิ่มความต้านทานคริติคอลของตนเองถาวร 30% ทุกครั้งที่ถูกโจมตีก่อนเพิ่ม #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# พลังเวทป้องกันและลดความเสียหาย 10% เป็นเวลา 1 เทิร์น (ไม่สามารถลบได้ สูงสุด 4 ชั้น) เมื่อโจมตีจะเพิ่มพลังเวทโจมตีชั่วคราวเท่ากับปริมาณพลังเวทป้องกันที่เพิ่มขึ้นนั้น',
		zawakeEffectDesc_in = 'Masuk ke pertempuran dengan peningkatan tahan kritis permanen 30% pada diri sendiri, setiap kali diserang sebelum menambahkan #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Pertahanan Magic dan pengurangan kerusakan 10% selama 1 giliran (tidak bisa dihapus, maksimum 4 lapis), saat menyerang secara sementara meningkatkan Serangan Magic sebesar jumlah Pertahanan Magic yang diperkuat itu.',
		zawakeEffectDesc_ph = 'Pumasok sa laban na may permanenteng 30% dagdag sa sariling kritikal na resistensya, sa bawat beses na tinatamaan bago dagdagan ang #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Magic Defense at 10% bawas sa pinsala sa loob ng 1 turn (hindi maaaring alisin, hanggang 4 na layers), kapag umaatake pansamantalang tumaas ang Magic Attack ng katumbas ng nadagdag na Magic Defense.',
		zawakeEffectDesc_ma = 'Masuk ke dalam pertempuran dengan peningkatan ketahanan kritikal kekal 30% pada diri sendiri, setiap kali diserang sebelum meningkatkan #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Pertahanan Ajaib dan pengurangan kerosakan sebanyak 10% selama 1 pusingan (tidak boleh dibuang, maksimum 4 lapisan), ketika menyerang secara sementara meningkatkan Serangan Ajaib mengikut jumlah Pertahanan Ajaib yang dipertingkatkan itu.',
		zawakeEffectDesc_vn = 'Vào trận chiến tăng vĩnh viễn 30% kháng chí mạng của bản thân, mỗi lần bị tấn công trước khi tăng #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Phép Phòng và 10% giảm sát thương trong 1 lượt (không thể xóa bỏ, tối đa 4 tầng), khi tấn công tạm thời tăng Phép Công bằng lượng Phép Phòng tăng cường đó',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#For each previous time attacked, gain 10% damage reduction for 1 turn',
		zawakeSimpleDesc_en = '#C0x5c9970#For each previous time attacked, gain 10% damage reduction for 1 turn',
		zawakeSimpleDesc_th = '#C0x5c9970#ทุกครั้งที่ถูกโจมตีก่อนหน้านี้ เพิ่มการลดความเสียหาย 10% เป็นเวลา 1 เทิร์น',
		zawakeSimpleDesc_in = '#C0x5c9970#Setiap kali diserang sebelumnya, meningkatkan pengurangan damage sebesar 10% selama 1 giliran',
		zawakeSimpleDesc_ph = '#C0x5c9970#Sa bawat pagkakataong inatake, dagdag 10% damage reduction sa loob ng 1 turn',
		zawakeSimpleDesc_ma = '#C0x5c9970#Setiap kali diserang sebelum ini, tingkatkan 10% pengurangan kerosakan selama 1 giliran',
		zawakeSimpleDesc_vn = '#C0x5c9970#Mỗi lần bị tấn công trước đó, tăng 10% giảm sát thương trong 1 lượt',
