	[20321] = {
		id = 20321,
		skillName_vn = 'Đạn pháo thanh lịch',
		skillName_en = 'Elegant shell',
		skillName_th = 'กระสุนปืนที่สง่างาม',
		skillName_in = 'Garis peluru yang elegan',
		skillName_ph = 'Magarang bala',
		skillName_ma = 'Butir peluru yang anggun',
		skillName = 'Elegant shell',
		describe_vn = 'Prinplup nhẹ nhàng nhảy lên, xoay 360 độ hoàn hảo trên không rồi dùng cơ thể va chạm vào mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#90% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, chuyển hóa vĩnh viễn 3% kháng chí mạng của bản thân thành 10% Phép Công (có thể cộng dồn, tối đa 5 tầng)',
		describe_en = 'Prinplup gently jumps up, performs a perfect 360-degree spin in the air, then collides with a single enemy target using its body, dealing #C0x3D8A99#90% Magic Attack #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. Permanently converts 3% of its own critical resistance into 10% Magic Attack (can stack up to 5 layers).',
		describe_th = 'Prinplup กระโดดขึ้นอย่างนุ่มนวล หมุนตัว 360 องศาอย่างสมบูรณ์แบบกลางอากาศ จากนั้นใช้ร่างกายชนเป้าหมายศัตรูเดี่ยว สร้าง #C0x3D8A99#90% พลังเวท #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวท #C0x5B545B# แปลง 3% ของการต้านทานคริติคอลของตัวเองเป็น 10% พลังเวทอย่างถาวร (ซ้อนกันได้สูงสุด 5 ชั้น)',
		describe_in = 'Prinplup melompat dengan lembut, melakukan putaran 360 derajat sempurna di udara, lalu menggunakan tubuhnya untuk menabrak target musuh tunggal, menyebabkan #C0x3D8A99#90% Serangan Sihir #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, mengubah secara permanen 3% ketahanan kritisnya menjadi 10% Serangan Sihir (dapat menumpuk hingga 5 lapis).',
		describe_ph = 'Maingat na lumukso si Prinplup, umiikot ng 360 degrees nang perpekto sa ere, pagkatapos ay ginagamit ang katawan para bumangga sa isang target ng kalaban, nagdudulot ng #C0x3D8A99#90% Magic Attack #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. Permanently kinokonvert ang 3% ng sariling critical resistance sa 10% Magic Attack (pwedeng mag-stack hanggang 5 layers).',
		describe_ma = 'Prinplup melompat dengan lembut, berpusing 360 darjah dengan sempurna di udara, kemudian menggunakan badan untuk bertembung dengan satu sasaran musuh, menyebabkan #C0x3D8A99#90% Serangan Sihir #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, menukar secara kekal 3% ketahanan kritikal sendiri menjadi 10% Serangan Sihir (boleh bertindih sehingga 5 lapisan).',
		describe = 'Prinplup gently jumps up, performs a perfect 360-degree spin in the air, then collides with a single enemy target using its body, dealing #C0x3D8A99#90% Magic Attack #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. Permanently converts 3% of its own critical resistance into 10% Magic Attack (can stack up to 5 layers).',
		simDesc_vn = 'Bo Hoàng Tử nhẹ nhàng nhảy lên, hoàn hảo xoay 360 độ trên không rồi dùng cơ thể va chạm vào mục tiêu đơn lẻ của đối phương.',
		simDesc_en = 'The Prince gently leaps up, flawlessly spinning 360 degrees in the air before colliding with a single enemy target using his body.',
		simDesc_th = 'เจ้าชายน้อยกระโดดขึ้นอย่างนุ่มนวล หมุนตัว 360 องศาอย่างสมบูรณ์แบบในอากาศ แล้วใช้ร่างกายชนเป้าหมายเดี่ยวของฝ่ายตรงข้าม',
		simDesc_in = 'Pangeran melompat dengan lembut, berputar 360 derajat di udara dengan sempurna kemudian menggunakan tubuhnya untuk menabrak satu target musuh.',
		simDesc_ph = 'Ang Prinsipe ay maingat na tumalon pataas, perpektong umiikot ng 360 degrees sa hangin bago gamitin ang kanyang katawan upang tumama sa isang target ng kalaban.',
		simDesc_ma = 'Putera berjongkok dengan lembut melompat, berputar 360 darjah dengan sempurna di udara sebelum menggunakan tubuhnya untuk melanggar satu sasaran lawan.',
		simDesc = 'The Prince gently leaps up, flawlessly spinning 360 degrees in the air before colliding with a single enemy target using his body.',
