	[20336] = {
		id = 20336,
		skillName_vn = 'Ngạ quỷ',
		skillName_en = 'Demon',
		skillName_th = 'ปีศาจ',
		skillName_in = 'Iblis',
		skillName_ph = 'Demonyo',
		skillName_ma = 'Iblis',
		skillName = 'Demon',
		describe_vn = 'Khi vào trận chiến, vĩnh viễn tăng 30% kháng chí mạng cho bản thân, mỗi lần bị tấn công trước sẽ tăng #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Phép Phòng trong 1 lượt (không thể xóa, tối đa 4 tầng), khi tấn công sẽ tạm thời tăng Phép Công tương đương với lượng Phép Phòng tăng cường này',
		describe_en = 'Upon entering battle, permanently increases critical resistance by 30% for yourself. Each time attacked first, increases #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Magic Defense for 1 turn (cannot be removed, up to 4 stacks). When attacking, temporarily increases Magic Attack equal to the enhanced Magic Defense amount.',
		describe_th = 'เมื่อเข้าสู่การต่อสู้ เพิ่มความต้านทานคริติคอลให้ตัวเองถาวร 30% ทุกครั้งที่ถูกโจมตีเป็นครั้งแรก จะเพิ่ม #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# พลังเวทย์ป้องกันเป็นเวลา 1 เทิร์น (ไม่สามารถลบได้ สูงสุด 4 ชั้น) เมื่อโจมตีจะเพิ่มพลังเวทย์โจมตีชั่วคราวเท่ากับปริมาณพลังเวทย์ป้องกันที่เพิ่มขึ้นนี้',
		describe_in = 'Saat memasuki pertempuran, secara permanen meningkatkan ketahanan kritis sebesar 30% untuk diri sendiri. Setiap kali diserang terlebih dahulu, meningkatkan #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Pertahanan Magic selama 1 giliran (tidak dapat dihapus, maksimal 4 tumpukan). Saat menyerang, sementara meningkatkan Serangan Magic setara dengan jumlah Pertahanan Magic yang ditingkatkan ini.',
		describe_ph = 'Kapag pumasok sa labanan, permanenteng tumataas ng 30% ang kritikal na resistensya para sa sarili. Sa bawat unang pag-atake sa iyo, tataas ang #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Mahika Depensa sa loob ng 1 turn (hindi maaaring alisin, hanggang 4 na stack). Kapag umaatake, pansamantalang tataas ang Mahika Atake na katumbas ng nadagdagang halaga ng Mahika Depensa.',
		describe_ma = 'Apabila memasuki pertempuran, secara kekal meningkatkan ketahanan kritikal sebanyak 30% untuk diri sendiri. Setiap kali diserang dahulu, meningkatkan #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Pertahanan Magik selama 1 pusingan (tidak boleh dipadam, maksimum 4 lapisan). Semasa menyerang, sementara meningkatkan Serangan Magik bersamaan dengan jumlah Pertahanan Magik yang dipertingkatkan ini.',
		describe = 'Upon entering battle, permanently increases critical resistance by 30% for yourself. Each time attacked first, increases #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Magic Defense for 1 turn (cannot be removed, up to 4 stacks). When attacking, temporarily increases Magic Attack equal to the enhanced Magic Defense amount.',
		starEffect = __data_t__starEffect[20336],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi bị tấn công, nếu tổng số hiệu ứng tiêu cực và kiểm soát trên bản thân vượt quá 3, sẽ ngay lập tức giải trừ tất cả hiệu ứng kiểm soát và hồi phục 600 điểm năng lượng; hiệu ứng này có thời gian hồi chiêu 2 lượt.',
		starEffectDesc = 'Additional effect: When attacked, if the total number of negative effects and controls on yourself exceeds 3, immediately dispel all control effects and recover 600 energy points; this effect has a cooldown of 2 turns.',
		starEffectDesc_en = 'Additional effect: When attacked, if the total number of negative effects and controls on yourself exceeds 3, immediately dispel all control effects and recover 600 energy points; this effect has a cooldown of 2 turns.',
		starEffectDesc_th = 'ผลเพิ่มเติม: เมื่อถูกโจมตี หากจำนวนผลลบและการควบคุมที่มีอยู่กับตนเองเกิน 3 จะทำการยกเลิกผลการควบคุมทั้งหมดทันทีและฟื้นฟูพลังงาน 600 คะแนน; ผลนี้มีเวลาคูลดาวน์ 2 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Saat diserang, jika jumlah total efek negatif dan kontrol pada diri sendiri melebihi 3, segera hapus semua efek kontrol dan pulihkan 600 poin energi; efek ini memiliki waktu cooldown 2 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag inaatake, kung ang kabuuang bilang ng negatibong epekto at kontrol sa sarili ay lumampas sa 3, agad na alisin ang lahat ng control effects at mabawi ang 600 puntos ng enerhiya; ang epekto na ito ay may cooldown na 2 turn.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila diserang, jika jumlah kesan negatif dan kawalan pada diri melebihi 3, akan segera membuang semua kesan kawalan dan memulihkan 600 mata tenaga; kesan ini mempunyai masa penyejukan 2 pusingan.',
		zawakeEffect = __data_t__zawakeEffect[20336],
		-- {79004}
		zawakeEffectDesc = 'Enter the battle to permanently increase your own critical resistance by 30%. Each time you are attacked, before increasing #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Magic Defense and 10% damage reduction for 1 turn (cannot be removed, max 4 stacks), when attacking temporarily increase Magic Attack equal to the enhanced Magic Defense.',
		zawakeEffectDesc_en = 'Enter the battle to permanently increase your own critical resistance by 30%. Each time you are attacked, before increasing #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Magic Defense and 10% damage reduction for 1 turn (cannot be removed, max 4 stacks), when attacking temporarily increase Magic Attack equal to the enhanced Magic Defense.',
		zawakeEffectDesc_th = 'เข้าสู่การต่อสู้เพื่อเพิ่มการต้านทานคริติคอลของตนเองอย่างถาวร 30% ทุกครั้งที่ถูกโจมตีก่อนที่จะเพิ่ม #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# พลังเวทป้องกันและลดความเสียหาย 10% ใน 1 เทิร์น (ไม่สามารถลบได้ สูงสุด 4 ชั้น) เมื่อโจมตีจะเพิ่มพลังเวทโจมตีชั่วคราวเท่ากับพลังเวทป้องกันที่เสริมขึ้นนั้น',
		zawakeEffectDesc_in = 'Masuk ke pertarungan untuk meningkatkan ketahanan kritis permanen sebesar 30% pada diri sendiri. Setiap kali diserang, sebelum meningkatkan #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Pertahanan Sihir dan mengurangi kerusakan sebesar 10% selama 1 giliran (tidak bisa dihapus, maksimal 4 tumpukan), saat menyerang meningkatkan Serangan Sihir sementara sebesar jumlah Pertahanan Sihir yang diperkuat tersebut.',
		zawakeEffectDesc_ph = 'Pumasok sa labanan upang permanenteng madagdagan ang sariling kritikal na resistensya ng 30%. Sa bawat beses na tinatamaan, bago tumaas ang #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Magic Defense at 10% pagbawas ng pinsala sa loob ng 1 turn (hindi maaaring tanggalin, maximum ng 4 na layer), kapag umaatake pansamantalang pinapataas ang Magic Attack ayon sa nadagdag na Magic Defense.',
		zawakeEffectDesc_ma = 'Masuk ke dalam pertempuran untuk meningkatkan ketahanan serangan kritikal diri sendiri sebanyak 30% secara kekal. Setiap kali diserang, sebelum meningkatkan #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Pertahanan Sihir dan mengurangkan kerosakan sebanyak 10% selama 1 giliran (tidak boleh dihapus, maksimum 4 lapisan), ketika menyerang sementara meningkatkan Serangan Sihir sama dengan jumlah Pertahanan Sihir yang dipertingkatkan itu.',
		zawakeEffectDesc_vn = 'Vào trận chiến tăng vĩnh viễn 30% kháng chí mạng của bản thân, mỗi lần bị tấn công trước khi tăng #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# Phép Phòng và 10% giảm sát thương trong 1 lượt (không thể xóa bỏ, tối đa 4 tầng), khi tấn công tạm thời tăng Phép Công bằng lượng Phép Phòng tăng cường đó',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#For each previous time attacked, gain 10% damage reduction for 1 turn',
		zawakeSimpleDesc_en = '#C0x5c9970#For each previous time attacked, gain 10% damage reduction for 1 turn',
		zawakeSimpleDesc_th = '#C0x5c9970#ทุกครั้งที่ถูกโจมตีก่อนหน้านี้ เพิ่มการลดความเสียหาย 10% เป็นเวลา 1 เทิร์น',
		zawakeSimpleDesc_in = '#C0x5c9970#Setiap kali diserang sebelumnya, meningkatkan pengurangan damage sebesar 10% selama 1 giliran',
		zawakeSimpleDesc_ph = '#C0x5c9970#Sa bawat pagkakataong inatake, dagdag 10% damage reduction sa loob ng 1 turn',
		zawakeSimpleDesc_ma = '#C0x5c9970#Setiap kali diserang sebelum ini, tingkatkan 10% pengurangan kerosakan selama 1 giliran',
		zawakeSimpleDesc_vn = '#C0x5c9970#Mỗi lần bị tấn công trước đó, tăng 10% giảm sát thương trong 1 lượt',
