	[22316] = {
		id = 22316,
		skillName_vn = 'Cơn thịnh nộ của rồng',
		skillName_en = 'The Rage of the Dragon',
		skillName_th = 'ความโกรธเกรี้ยวของมังกร',
		skillName_in = 'Amukan Naga',
		skillName_ph = 'Galit ng Dragon',
		skillName_ma = 'Kemarahan Naga',
		skillName = 'The Rage of the Dragon',
		describe_vn = 'Khi sinh mệnh của bản thân lần đầu tiên giảm xuống dưới #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, sẽ vào trạng thái [cuồng nộ] trong 3 lượt (cuồng nộ: hiệu ứng đặc biệt, tăng 35% Công Vật Lý, tốc độ, chí mạng của bản thân, đồng thời dễ bị tổn thương thêm 30%, mỗi lần tấn công sẽ kèm theo sát thương thực bằng 10% giới hạn sinh mệnh của bản thân, sát thương này có thể chí mạng)',
		describe_en = 'When your HP first drops below #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, enter [Rage] state for 3 turns (Rage: special effect that increases own Physical Attack, Speed, and Critical Rate by 35%, but also increases damage taken by 30%. Each attack deals additional true damage equal to 10% of own max HP, and this damage can crit).',
		describe_th = 'เมื่อพลังชีวิตของตนเองลดลงต่ำกว่า #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B# เป็นครั้งแรก จะเข้าสู่สถานะ [คลั่ง] เป็นเวลา 3 เทิร์น (คลั่ง: ผลพิเศษ เพิ่มพลังโจมตีทางกายภาพ ความเร็ว และคริติคอลของตนเอง 35% แต่จะได้รับความเสียหายเพิ่มขึ้น 30% ทุกการโจมตีจะมีความเสียหายจริงเพิ่มขึ้น 10% ของพลังชีวิตสูงสุดของตนเอง และความเสียหายนี้สามารถคริติคอลได้)',
		describe_in = 'Ketika HP sendiri pertama kali turun di bawah #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, masuk ke status [Amarah] selama 3 giliran (Amarah: efek khusus yang meningkatkan Serangan Fisik, Kecepatan, dan Critical rate sendiri sebesar 35%, tetapi juga meningkatkan kerusakan yang diterima sebesar 30%. Setiap serangan akan disertai dengan damage murni sebesar 10% dari batas HP sendiri, damage ini dapat menjadi kritikal).',
		describe_ph = 'Kapag unang bumaba ang iyong HP sa ilalim ng #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, papasok ka sa [Galit] na estado sa loob ng 3 turn (Galit: espesyal na epekto na nagpapataas ng 35% ng sariling Physical Attack, Bilis, at Critical rate, ngunit mas lalong tinatanggap ang 30% mas mataas na damage. Bawat atake ay may kasamang true damage na katumbas ng 10% ng sariling max HP, at maaaring makagawa ito ng critical damage).',
		describe_ma = 'Apabila nyawa sendiri pertama kali jatuh di bawah #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, akan memasuki keadaan [Amarah] selama 3 pusingan (Amarah: kesan khas yang meningkatkan Serangan Fizikal, Kelajuan, dan Kritikal sebanyak 35%, tetapi juga meningkatkan kerosakan yang diterima sebanyak 30%. Setiap serangan disertai dengan kerosakan sebenar sebanyak 10% daripada had nyawa sendiri, kerosakan ini boleh mendapat kritikal).',
		describe = 'When your HP first drops below #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, enter [Rage] state for 3 turns (Rage: special effect that increases own Physical Attack, Speed, and Critical Rate by 35%, but also increases damage taken by 30%. Each attack deals additional true damage equal to 10% of own max HP, and this damage can crit).',
		starEffect = __data_t__starEffect[22316],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi vào trạng thái cuồng bạo, sẽ giải trừ tất cả hiệu ứng tiêu cực và tăng 300 điểm năng lượng; trong thời gian này, miễn dịch với các hiệu ứng tiêu cực.',
		starEffectDesc = 'Additional effect: When entering the Berserk state, all negative effects will be removed and 300 energy points will be restored; during this time, immune to negative effects.',
		starEffectDesc_en = 'Additional effect: When entering the Berserk state, all negative effects will be removed and 300 energy points will be restored; during this time, immune to negative effects.',
		starEffectDesc_th = 'ผลเสริม: เมื่อเข้าสู่สถานะคลุ้มคลั่ง จะล้างผลกระทบเชิงลบทั้งหมดและเพิ่มพลังงาน 300 คะแนน; ในช่วงเวลานี้ ป้องกันผลกระทบเชิงลบ',
		starEffectDesc_in = 'Efek tambahan: Saat memasuki keadaan ganas, semua efek negatif akan dihapus dan menambah 300 poin energi; selama waktu ini, kebal terhadap efek negatif.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag pumasok sa kalagayan ng galit, aalisin ang lahat ng negatibong epekto at madaragdagan ng 300 puntos ng enerhiya; sa panahong ito, immune sa mga negatibong epekto.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila memasuki keadaan ganas, semua kesan negatif akan dibuang dan menambah 300 mata tenaga; dalam waktu ini, kebal terhadap kesan negatif.',
		zawakeEffect = __data_t__zawakeEffect[22316],
		-- {79004}
		zawakeEffectDesc = 'When your own HP first falls below #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, enter <Burst> state for 3 turns (Burst: special effect, increases own Physical Attack, Speed, and Critical Rate by 35%, each attack also deals true damage equal to 10% of own max HP, this damage can crit)',
		zawakeEffectDesc_en = 'When your own HP first falls below #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, enter <Burst> state for 3 turns (Burst: special effect, increases own Physical Attack, Speed, and Critical Rate by 35%, each attack also deals true damage equal to 10% of own max HP, this damage can crit)',
		zawakeEffectDesc_th = 'เมื่อพลังชีวิตของตัวเองครั้งแรกต่ำกว่า #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B# เข้าสู่สถานะ <ระเบิด> เป็นเวลา 3 เทิร์น (ระเบิด: ผลพิเศษ เพิ่มพลังโจมตีทางกายภาพ, ความเร็ว และคริติคอลของตัวเอง 35%, ทุกการโจมตีจะทำดาเมจจริงเท่ากับ 10% ของพลังชีวิตสูงสุดของตัวเอง ดาเมจนี้สามารถคริติคอลได้)',
		zawakeEffectDesc_in = 'Saat HP sendiri pertama kali turun di bawah #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, masuk ke kondisi <Ledakan> selama 3 giliran (Ledakan: efek khusus, meningkatkan Serangan Fisik, Kecepatan, dan Kritikal sendiri sebesar 35%, setiap serangan juga menghasilkan damage nyata sebesar 10% dari batas HP maksimal sendiri, damage ini dapat mengenai kritikal)',
		zawakeEffectDesc_ph = 'Kapag ang sariling HP ay unang bumaba ng mas mababa sa #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, papasok sa <Pagsabog> na estado sa loob ng 3 turn (Pagsabog: espesyal na epekto, tumaas ang sariling Physical Attack, Bilis, at Critical ng 35%, bawat pag-atake ay may kasamang tunay na pinsala na katumbas ng 10% ng sariling maximum HP, maaaring mag-crit ang pinsalang ito)',
		zawakeEffectDesc_ma = 'Apabila HP sendiri buat kali pertama jatuh di bawah #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, masuk ke keadaan <Ledakan> selama 3 giliran (Ledakan: kesan khas, meningkatkan Serangan Fizikal, Kelajuan dan Kritikal sendiri sebanyak 35%, setiap serangan juga memberikan kerosakan sebenar sebanyak 10% dari had HP maksima sendiri, kerosakan ini boleh mendapat kritikal)',
		zawakeEffectDesc_vn = 'Khi sinh mệnh của bản thân lần đầu tiên thấp hơn #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, vào trạng thái <bạo phát> trong 3 lượt (bạo phát: hiệu ứng đặc biệt, tăng 35% Công Vật Lý, tốc độ, chí mạng của bản thân, mỗi lần tấn công sẽ kèm theo sát thương thực bằng 10% giới hạn sinh mệnh của bản thân, sát thương này có thể chí mạng)',
