		skillName_ph = 'Ulap ng dragon',
		skillName_ma = 'Awan naga',
		skillName = 'Dragon cloud',
		describe_vn = 'Garchomp tập trung năng lượng vào đan điền rồi phun lên trời, thiên thạch rơi xuống tấn công mục tiêu hàng dọc của kẻ địch, gây #C0xE69900#250% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, gây thêm 30% sát thương cho mục tiêu hàng sau',
		describe_en = 'Garchomp concentrates energy into the dantian, then spits it into the sky, causing meteors to fall and attack the enemy\'s vertical target line, dealing #C0xE69900#250% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, and dealing an additional 30% damage to targets in the back row.',
		describe_th = 'Garchomp มุ่งพลังงานไปที่ตันเตียนแล้วพ่นขึ้นฟ้า ดาวตกจะตกลงมาโจมตีเป้าหมายในแนวตั้งของศัตรู ทำความเสียหาย #C0xE69900#250% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# และสร้างความเสียหายเพิ่มเติม 30% กับเป้าหมายแถวหลัง',
		describe_in = 'Garchomp memusatkan energi ke dantian kemudian meludah ke langit, meteorit jatuh menyerang baris target vertikal musuh, memberikan #C0xE69900#250% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, memberikan tambahan 30% kerusakan pada target barisan belakang.',
		describe_ph = 'Garchomp ayusin ang enerhiya sa dantian at bahing sa langit, nagbabagsak ang mga meteor na umatake sa patayong linya ng kalaban, nagdudulot ng #C0xE69900#250% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, dagdag pa 30% na pinsala sa mga target sa hulihang linya.',
		describe_ma = 'Garchomp menumpukan tenaga ke dantian kemudian menyembur ke langit, meteor jatuh menyerang sasaran barisan menegak musuh, menyebabkan #C0xE69900#250% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, dan menyebabkan tambahan 30% kerosakan kepada sasaran barisan belakang.',
		describe = 'Garchomp concentrates energy into the dantian, then spits it into the sky, causing meteors to fall and attack the enemy\'s vertical target line, dealing #C0xE69900#250% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, and dealing an additional 30% damage to targets in the back row.',
		simDesc_vn = 'Rồng Mũi Nhọn tập trung năng lượng từ đan điền phun lên trời, từ trên không rơi xuống thiên thạch tấn công mục tiêu hàng của đối phương, gây sát thương bổ sung cho các mục tiêu ở hàng sau.',
		simDesc_en = 'The Sharp-Nosed Dragon concentrates energy from the dantian and shoots it into the sky, causing meteorites to fall from above and attack the enemy\'s front row, dealing additional damage to targets in the back row.',
		simDesc_th = 'มังกรจมูกแหลมรวมพลังจากตันเตียนยิงขึ้นสู่ท้องฟ้า ทำให้ดาวตกจากบนฟ้าตกลงมาโจมตีแถวหน้าของศัตรู สร้างความเสียหายเพิ่มเติมแก่เป้าหมายในแถวหลัง',
		simDesc_in = 'Naga Bermulut Runcing mengumpulkan energi dari dantian dan menyemburkannya ke langit, menyebabkan meteorit jatuh dari atas menyerang barisan depan musuh, memberikan kerusakan tambahan pada target di barisan belakang.',
		simDesc_ph = 'Ang Matulis na Dragon ay nagtitipon ng enerhiya mula sa dantian at iniluluwal ito sa kalangitan, na nagdudulot ng mga meteoryo na bumabagsak mula sa itaas at umaatake sa harapang hanay ng kalaban, na nagdudulot ng karagdagang pinsala sa mga target sa likurang hanay.',
		simDesc_ma = 'Naga Hidung Tajam menumpukan tenaga dari dantian dan memancarkannya ke langit, menyebabkan meteor jatuh dari atas menyerang barisan hadapan musuh, memberikan kerosakan tambahan kepada sasaran di barisan belakang.',
		simDesc = 'The Sharp-Nosed Dragon concentrates energy from the dantian and shoots it into the sky, causing meteorites to fall from above and attack the enemy\'s front row, dealing additional damage to targets in the back row.',
		starEffect = __data_t__starEffect[22323],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Trong trạng thái cuồng bạo, tấn công sẽ gây sát thương cho toàn bộ mục tiêu, với tỷ lệ sát thương bắn ra là 50%.',
		starEffectDesc = 'Additional Effect: In Berserk state, attacks will deal damage to all targets, with a 50% damage output rate.',
		starEffectDesc_en = 'Additional Effect: In Berserk state, attacks will deal damage to all targets, with a 50% damage output rate.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ในสถานะบ้าคลั่ง การโจมตีจะสร้างความเสียหายแก่เป้าหมายทั้งหมด โดยมีอัตราความเสียหายที่ยิงออกมาเป็น 50%',
		starEffectDesc_in = 'Efek Tambahan: Dalam keadaan ganas, serangan akan memberikan kerusakan pada semua target, dengan tingkat kerusakan yang dikeluarkan sebesar 50%.',
		starEffectDesc_ph = 'Karagdagang Epekto: Sa estado ng pagkabaliw, ang mga atake ay magdudulot ng pinsala sa lahat ng mga target, na may 50% na porsyento ng pinsalang ibinibuga.',
		starEffectDesc_ma = 'Kesan Tambahan: Dalam keadaan ganas, serangan akan memberikan kerosakan kepada semua sasaran, dengan kadar kerosakan yang dikeluarkan sebanyak 50%.',
		zawakeEffect = __data_t__zawakeEffect[22323],
		-- {79003}
		zawakeEffectDesc = 'Garchomp focuses energy into the dantian then spits it into the sky, from which meteorites fall to attack the enemy\'s horizontal target, dealing #C0xE69900#260% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, dealing an additional 30% damage to the rear target',
		zawakeEffectDesc_en = 'Garchomp focuses energy into the dantian then spits it into the sky, from which meteorites fall to attack the enemy\'s horizontal target, dealing #C0xE69900#260% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, dealing an additional 30% damage to the rear target',
		zawakeEffectDesc_th = 'Garchomp รวมพลังเข้าไปในตัณเตียนแล้วพ่นขึ้นฟ้า จากนั้นดาวตกจะตกลงมาโจมตีเป้าหมายในแนวนอนของศัตรู ก่อให้เกิด #C0xE69900#260% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# และก่อความเสียหายเพิ่มเติม 30% ต่อเป้าหมายแถวหลัง',
		zawakeEffectDesc_in = 'Garchomp memusatkan energi ke dantian lalu menyemburkannya ke langit, dari situ meteor jatuh menyerang target horizontal musuh, memberikan #C0xE69900#260% Serangan Fisik#C0x5B545B# +$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, memberikan tambahan 30% kerusakan ke target barisan belakang',
		zawakeEffectDesc_ph = 'Garchomp ayusin ang enerhiya sa dantian saka suminga sa langit, mula doon bumagsak ang mga meteor na sumalakay sa pahalang na target ng kalaban, na nagdudulot ng #C0xE69900#260% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, na nagdudulot ng dagdag na 30% pinsala sa target sa likuran',
		zawakeEffectDesc_ma = 'Garchomp memfokuskan tenaga ke dantian lalu meludah ke langit, dari situ meteor jatuh menyerang sasaran mendatar musuh, menyebabkan #C0xE69900#260% Serangan Fizikal#C0x5B545B# +$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, menyebabkan tambahan 30% kerosakan kepada sasaran barisan belakang',
		zawakeEffectDesc_vn = 'Garchomp tập trung năng lượng vào đan điền rồi phun lên trời, từ trên trời rơi xuống thiên thạch tấn công mục tiêu hàng ngang của kẻ địch, gây #C0xE69900#260% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, gây thêm 30% sát thương cho mục tiêu hàng sau',
