	[22326] = {
		id = 22326,
		skillName_vn = 'Cơn thịnh nộ của rồng',
		skillName_en = 'The fury of the dragon',
		skillName_th = 'ความโกรธเกรี้ยวของมังกร',
		skillName_in = 'Amarah naga',
		skillName_ph = 'Galit ng dragon',
		skillName_ma = 'Kemarahan naga',
		skillName = 'The fury of the dragon',
		describe_vn = 'Khi sinh mệnh của bản thân lần đầu tiên giảm xuống dưới #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, sẽ vào trạng thái [cuồng nộ] trong 3 lượt (cuồng nộ: hiệu ứng đặc biệt, tăng 35% Công Vật Lý, tốc độ, chí mạng của bản thân, đồng thời dễ bị tổn thương thêm 30%, mỗi lần tấn công sẽ kèm theo sát thương thực bằng 10% giới hạn sinh mệnh của bản thân, sát thương này có thể chí mạng)',
		describe_en = 'When your life first drops below #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, you enter the [Rage] state for 3 turns (Rage: special effect that increases your Physical Attack, Speed, and Critical Rate by 35%, but also makes you 30% more vulnerable. Each attack inflicts additional true damage equal to 10% of your max HP, and this damage can critically hit).',
		describe_th = 'เมื่อพลังชีวิตของคุณลดลงต่ำกว่า #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B# เป็นครั้งแรก จะเข้าสู่สถานะ [คลั่งแค้น] นาน 3 เทิร์น (คลั่งแค้น: เอฟเฟกต์พิเศษ เพิ่มพลังโจมตีทางกายภาพ, ความเร็ว และอัตราคริติคอลของตัวเอง 35% แต่จะได้รับความเสียหายเพิ่มขึ้น 30% ทุกครั้งที่โจมตีจะเพิ่มความเสียหายจริงเท่ากับ 10% ของพลังชีวิตสูงสุด และความเสียหายนี้สามารถคริติคอลได้)',
		describe_in = 'Ketika nyawamu pertama kali turun di bawah #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, kamu akan masuk ke keadaan [Kemarahan] selama 3 giliran (Kemarahan: efek khusus yang meningkatkan Serangan Fisik, Kecepatan, dan Kritikal sebesar 35%, namun kamu juga menjadi 30% lebih rentan. Setiap serangan akan menghasilkan kerusakan nyata tambahan sebesar 10% dari batas maksimal nyawamu, dan kerusakan ini bisa menghasilkan kritikal).',
		describe_ph = 'Kapag ang buhay mo ay unang bumaba sa ilalim ng #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, papasok ka sa estado ng [Galit] sa loob ng 3 turn (Galit: espesyal na epekto na nagdaragdag ng iyong Physical Attack, Bilis, at Critical Rate ng 35%, ngunit nagiging 30% na mas mahina ka rin. Bawat atake ay may kasamang karagdagang true damage na katumbas ng 10% ng iyong maximum HP, at maaaring maging critical ang damage na ito).',
		describe_ma = 'Apabila nyawa anda pertama kali jatuh di bawah #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, anda akan memasuki keadaan [Kemarahan] selama 3 pusingan (Kemarahan: kesan istimewa yang meningkatkan Serangan Fizikal, Kelajuan, dan Kritikal anda sebanyak 35%, tetapi juga menjadikan anda 30% lebih mudah terdedah kepada kecederaan. Setiap serangan disertakan dengan kerosakan sebenar tambahan sebanyak 10% daripada had nyawa anda, dan kerosakan ini boleh menjadi kritikal).',
		describe = 'When your life first drops below #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, you enter the [Rage] state for 3 turns (Rage: special effect that increases your Physical Attack, Speed, and Critical Rate by 35%, but also makes you 30% more vulnerable. Each attack inflicts additional true damage equal to 10% of your max HP, and this damage can critically hit).',
		starEffect = __data_t__starEffect[22326],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi vào trạng thái cuồng bạo, sẽ giải trừ tất cả hiệu ứng tiêu cực và tăng 300 điểm năng lượng; trong thời gian này, miễn dịch với các hiệu ứng tiêu cực.',
		starEffectDesc = 'Additional effect: When entering the berserk state, all negative effects will be removed and 300 energy points will be increased; during this time, immune to all negative effects.',
		starEffectDesc_en = 'Additional effect: When entering the berserk state, all negative effects will be removed and 300 energy points will be increased; during this time, immune to all negative effects.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อเข้าสู่สถานะคลุ้มคลั่ง จะลบล้างสถานะลบทั้งหมดและเพิ่มพลังงาน 300 คะแนน; ในช่วงเวลานี้ ป้องกันสถานะลบทั้งหมด',
		starEffectDesc_in = 'Efek tambahan: Saat memasuki keadaan ganas, semua efek negatif akan dihapus dan energi akan bertambah 300 poin; selama waktu ini, kebal terhadap semua efek negatif.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag pumasok sa kalagayan ng galit, aalisin ang lahat ng negatibong epekto at madadagdag ang 300 puntos ng enerhiya; sa panahong ito, immune sa lahat ng negatibong epekto.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila memasuki keadaan ganas, semua kesan negatif akan dibuang dan tenaga akan meningkat sebanyak 300 mata; dalam tempoh ini, kebal kepada semua kesan negatif.',
		zawakeEffect = __data_t__zawakeEffect[22326],
		-- {79004}
		zawakeEffectDesc = 'When your own HP first falls below #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, enter <burst> state for 3 turns (burst: special effect, increases own Physical Attack, Speed, Critical by 35%, each attack deals additional true damage equal to 10% of own max HP, this damage can crit)',
		zawakeEffectDesc_en = 'When your own HP first falls below #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, enter <burst> state for 3 turns (burst: special effect, increases own Physical Attack, Speed, Critical by 35%, each attack deals additional true damage equal to 10% of own max HP, this damage can crit)',
		zawakeEffectDesc_th = 'เมื่อพลังชีวิตของตัวเองครั้งแรกต่ำกว่า #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B# เข้าในสถานะ <ระเบิด> เป็นเวลา 3 เทิร์น (ระเบิด: เอฟเฟกต์พิเศษ เพิ่มพลังโจมตีทางกายภาพ ความเร็ว และคริติคอลของตัวเอง 35% แต่ละครั้งที่โจมตีจะมีความเสียหายจริงเพิ่ม 10% ของพลังชีวิตสูงสุดตัวเอง ความเสียหายนี้สามารถคริติคอลได้)',
		zawakeEffectDesc_in = 'Saat HP sendiri pertama kali turun di bawah #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, masuk ke status <ledakan> selama 3 giliran (ledakan: efek khusus, meningkatkan Serangan Fisik, Kecepatan, dan Crit milik sendiri sebesar 35%, setiap serangan memberikan tambahan damage nyata sebesar 10% dari batas maksimal HP sendiri, damage ini dapat crit)',
		zawakeEffectDesc_ph = 'Kapag ang sariling HP ay unang bumaba sa ilalim ng #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, papasok sa <burst> na estado sa loob ng 3 turn (burst: espesyal na epekto, nagpapataas ng sariling Physical Attack, Speed, Critical ng 35%, bawat pag-atake ay may kasamang totoong damage na katumbas ng 10% ng maximum HP ng sarili, pwedeng mag-crit ang damage na ito)',
		zawakeEffectDesc_ma = 'Apabila HP sendiri pertama kali jatuh di bawah #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, masuk ke keadaan <letusan> selama 3 giliran (letusan: kesan khas, meningkatkan Serangan Fizikal, Kelajuan, Kritikal sebanyak 35%, setiap serangan disertai kerosakan sebenar sebanyak 10% had maks HP sendiri, kerosakan ini boleh kritikal)',
		zawakeEffectDesc_vn = 'Khi sinh mệnh của bản thân lần đầu tiên thấp hơn #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, vào trạng thái <bạo phát> trong 3 lượt (bạo phát: hiệu ứng đặc biệt, tăng 35% Công Vật Lý, tốc độ, chí mạng của bản thân, mỗi lần tấn công sẽ kèm theo sát thương thực bằng 10% giới hạn sinh mệnh của bản thân, sát thương này có thể chí mạng)',
