	[22336] = {
		id = 22336,
		skillName_vn = 'Cơn Thịnh Nộ Của Người Saiyan',
		skillName_en = 'The Fury Of The Saiyan',
		skillName_th = 'ความโกรธของไซยาน',
		skillName_in = 'Kemarahan Saiyan',
		skillName_ph = 'Galit ng Saiyan',
		skillName_ma = 'Kemarahan Saiyan',
		skillName = 'The Fury Of The Saiyan',
		describe_vn = 'Khi sinh mệnh của bản thân lần đầu tiên giảm xuống dưới #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, sẽ vào trạng thái [cuồng nộ] trong 3 lượt (cuồng nộ: hiệu ứng đặc biệt, tăng 35% Công Vật Lý, tốc độ, chí mạng của bản thân, đồng thời dễ bị tổn thương thêm 30%, mỗi lần tấn công sẽ kèm theo sát thương thực bằng 10% giới hạn sinh mệnh của bản thân, sát thương này có thể chí mạng)',
		describe_en = 'When your life first drops below #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, you enter the [Rage] state for 3 turns (Rage: a special effect that increases your Physical Attack, Speed, and Critical Rate by 35%, but also makes you 30% more vulnerable. Each attack deals additional true damage equal to 10% of your maximum life, this true damage can critically hit).',
		describe_th = 'เมื่อพลังชีวิตของคุณลดลงต่ำกว่า #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B# เป็นครั้งแรก จะเข้าสู่สถานะ [ความโกรธ] เป็นเวลา 3 เทิร์น (ความโกรธ: ผลพิเศษที่เพิ่มพลังโจมตีทางกายภาพ 35%, ความเร็ว, และอัตราคริติคอลของตัวเอง แต่ก็ทำให้ได้รับความเสียหายเพิ่มขึ้น 30% ทุกการโจมตีจะได้รับความเสียหายจริงเพิ่มเติมเท่ากับ 10% ของพลังชีวิตสูงสุดของตัวเอง ความเสียหายนี้สามารถคริติคอลได้)',
		describe_in = 'Saat nyawa Anda pertama kali turun di bawah #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, Anda akan memasuki status [Amarah] selama 3 giliran (Amarah: efek khusus yang meningkatkan Serangan Fisik, Kecepatan, dan Kritikal Anda sebesar 35%, namun membuat Anda 30% lebih rentan. Setiap serangan memberikan tambahan damage nyata sebesar 10% dari batas nyawa maksimal Anda, damage ini bisa mengenai kritikal).',
		describe_ph = 'Kapag ang iyong buhay ay unang bumaba sa ilalim ng #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, ikaw ay papasok sa estado ng [Galit] sa loob ng 3 na turn (Galit: isang espesyal na epekto na nagpapataas ng iyong Physical Attack, Bilis, at Critical Rate ng 35%, ngunit ginagawang 30% kang mas madaling masaktan. Bawat atake ay may kasamang karagdagang tunay na pinsala na katumbas ng 10% ng iyong maximum na buhay, at ang pinsalang ito ay maaaring maging kritikal).',
		describe_ma = 'Apabila nyawa anda mula-mula turun di bawah #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, anda akan memasuki keadaan [Kemarahan] selama 3 pusingan (Kemarahan: kesan khas yang meningkatkan Serangan Fizikal, Kelajuan, dan Kritikal anda sebanyak 35%, tetapi sekaligus menjadikan anda 30% lebih mudah menerima kerosakan. Setiap serangan turut memberikan kerosakan sebenar sebanyak 10% dari had nyawa maksimum anda, kerosakan ini boleh menjadi kritikal).',
		describe = 'When your life first drops below #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, you enter the [Rage] state for 3 turns (Rage: a special effect that increases your Physical Attack, Speed, and Critical Rate by 35%, but also makes you 30% more vulnerable. Each attack deals additional true damage equal to 10% of your maximum life, this true damage can critically hit).',
		starEffect = __data_t__starEffect[22336],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi vào trạng thái cuồng bạo, sẽ giải trừ tất cả hiệu ứng tiêu cực và tăng 300 điểm năng lượng; trong thời gian này, miễn dịch với các hiệu ứng tiêu cực.',
		starEffectDesc = 'Additional effect: When entering the berserk state, all negative effects are removed and 300 energy points are increased; during this time, immune to negative effects.',
		starEffectDesc_en = 'Additional effect: When entering the berserk state, all negative effects are removed and 300 energy points are increased; during this time, immune to negative effects.',
		starEffectDesc_th = 'ผลกระทบเพิ่มเติม: เมื่อเข้าสู่สถานะคลั่ง จะล้างเอฟเฟกต์ลบทั้งหมดและเพิ่มพลังงาน 300 คะแนน; ในช่วงเวลานี้ มีภูมิคุ้มกันต่อเอฟเฟกต์ลบ',
		starEffectDesc_in = 'Efek tambahan: Saat memasuki keadaan ganas, semua efek negatif dihapus dan energi bertambah 300 poin; selama waktu ini, kebal terhadap efek negatif.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag pumasok sa estado ng pagkabaliw, aalisin ang lahat ng negatibong epekto at tataas ang 300 puntos ng enerhiya; sa panahong ito, immune sa mga negatibong epekto.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila memasuki keadaan ganas, semua kesan negatif akan dibatalkan dan tenaga bertambah 300 mata; pada masa ini, kebal terhadap kesan negatif.',
		zawakeEffect = __data_t__zawakeEffect[22336],
		-- {79004}
		zawakeEffectDesc = 'When your own health first drops below #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, enter <berserk> state for 3 turns (berserk: special effect, increase own Physical Attack, Speed, and Critical Hit by 35%, each attack also deals true damage equal to 10% of own max health, this damage can critically hit)',
		zawakeEffectDesc_en = 'When your own health first drops below #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, enter <berserk> state for 3 turns (berserk: special effect, increase own Physical Attack, Speed, and Critical Hit by 35%, each attack also deals true damage equal to 10% of own max health, this damage can critically hit)',
		zawakeEffectDesc_th = 'เมื่อพลังชีวิตของตัวเองต่ำกว่า #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B# เป็นครั้งแรก เข้า <bạo phát> เป็นเวลา 3 เทิร์น (bạo phát: ผลพิเศษ เพิ่มพลังโจมตีทางกาย, ความเร็ว และคริติคอลของตัวเอง 35%, ทุกครั้งที่โจมตีจะเพิ่มความเสียหายจริงเท่ากับ 10% ของพลังชีวิตสูงสุดของตัวเอง ความเสียหายนี้สามารถคริติคอลได้)',
		zawakeEffectDesc_in = 'Saat nyawa sendiri pertama kali turun di bawah #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, masuk ke status <bạo phát> selama 3 giliran (bạo phát: efek khusus, meningkatkan 35% Serangan Fisik, kecepatan, dan critical hit milik sendiri, setiap serangan juga menghasilkan damage nyata sebesar 10% dari batas maksimal nyawa sendiri, damage ini bisa critical)',
		zawakeEffectDesc_ph = 'Kapag ang sariling buhay ay unang bumaba sa ibaba ng #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, pumapasok sa <bạo phát> na estado sa loob ng 3 turn (bạo phát: espesyal na epekto, tumataas ng 35% ang sariling Physical Attack, bilis, at critical hit, bawat atake ay may kasamang totoong damage na katumbas ng 10% ng sariling maximum na buhay, pwedeng mag-critical ang damage na ito)',
		zawakeEffectDesc_ma = 'Apabila nyawa sendiri pertama kali jatuh di bawah #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, masuk ke keadaan <bạo phát> selama 3 pusingan (bạo phát: kesan khas, meningkatkan 35% Serangan Fizikal, kelajuan, dan kritikal diri sendiri, setiap serangan turut menyebabkan kerosakan nyata bersamaan 10% had maksimum nyawa sendiri, kerosakan ini boleh kritikal)',
		zawakeEffectDesc_vn = 'Khi sinh mệnh của bản thân lần đầu tiên thấp hơn #C0x5c9970#$(35+skillLevel*0.15-0.15)$%#C0x5B545B#, vào trạng thái <bạo phát> trong 3 lượt (bạo phát: hiệu ứng đặc biệt, tăng 35% Công Vật Lý, tốc độ, chí mạng của bản thân, mỗi lần tấn công sẽ kèm theo sát thương thực bằng 10% giới hạn sinh mệnh của bản thân, sát thương này có thể chí mạng)',
		zawakeSimpleType = 1,
