	[22413] = {
		id = 22413,
		skillName_vn = 'Đạn chân khí',
		skillName_en = 'Compressed air bullet',
		skillName_th = 'กระสุนอัดลม',
		skillName_in = 'Peluru udara tekan',
		skillName_ph = 'Piniga ng hangin',
		skillName_ma = 'Peluru udara mampat',
		skillName = 'Compressed air bullet',
		describe_vn = 'Riolu chạy nhanh xoay quanh kẻ địch, sau đó nhảy lên và phát ra đạn khí chân thật vào mục tiêu đơn địch, gây Sát Thương Phép Thuật #C0x3D8A99#470% Công Phép#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Sát Thương Phép Thuật#C0x5B545B#; đòn tấn công này chắc chắn trúng; nếu mục tiêu còn sống, sức mạnh sóng dẫn còn lại trên kẻ địch sẽ gây thêm sát thương bằng 35% sát thương của kỹ năng tối thượng này trước khi mục tiêu có thể tấn công.',
		describe_en = 'Riolu runs quickly around the enemy, then leaps up and fires a projectile of true leg air at a single enemy target, dealing Magical Damage of #C0x3D8A99#470% Magic Power#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Magical Damage#C0x5B545B#; this attack is guaranteed to hit; if the target is still alive, the remaining power wave on the enemy will deal additional damage equal to 35% of the ultimate skill\'s damage before the target can attack.',
		describe_th = 'ริโอรุ วิ่งอย่างรวดเร็วรอบศัตรู จากนั้นกระโดดขึ้นและปล่อยกระสุนลมขาจริงไปยังเป้าหมายเดี่ยว ก่อให้เกิด ความเสียหายเวทย์มนตร์ #C0x3D8A99#470% พลังเวทย์#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# ความเสียหายเวทย์มนตร์#C0x5B545B#; การโจมตีนี้จะถูกต้องอย่างแน่นอน; หากเป้าหมายยังมีชีวิตอยู่ พลังคลื่นที่เหลือบนศัตรูจะสร้างความเสียหายเพิ่มเติมเท่ากับ 35% ของความเสียหายทักษะอัลติเมทนี้ก่อนที่เป้าหมายจะโจมตีได้',
		describe_in = 'Riolu berlari cepat mengelilingi musuh, kemudian melompat dan menembakkan peluru udara kaki asli ke target musuh tunggal, menyebabkan Damage Magic sebesar #C0x3D8A99#470% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Damage Magic#C0x5B545B#; serangan ini pasti mengenai; jika target masih hidup, gelombang kekuatan yang tersisa pada musuh akan menyebabkan damage tambahan sebesar 35% dari damage skill ultimate ini sebelum target dapat menyerang.',
		describe_ph = 'Mabilis na tumakbo si Riolu paikot sa kalaban, pagkatapos ay tumalon at nagpaputok ng totoong hangin na bala sa paa papunta sa isang kalaban, na nagdudulot ng Magical Damage na #C0x3D8A99#470% Magic Power#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Magical Damage#C0x5B545B#; tiyak na tumatama ang pag-atakeng ito; kung buhay pa ang target, ang natitirang kapangyarihan ng alon sa kalaban ay magdudulot ng karagdagang pinsala na katumbas ng 35% ng pinsala ng ultimate skill na ito bago makaatake ang target.',
		describe_ma = 'Riolu berlari pantas mengelilingi musuh, kemudian melompat dan melepaskan peluru angin kaki sebenar ke sasaran musuh tunggal, menyebabkan Kerosakan Ajaib #C0x3D8A99#470% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Kerosakan Ajaib#C0x5B545B#; serangan ini pasti tepat; jika sasaran masih hidup, gelombang kuasa yang tinggal pada musuh akan menyebabkan kerosakan tambahan sebanyak 35% daripada kerosakan kemahiran utama ini sebelum sasaran dapat menyerang.',
		describe = 'Riolu runs quickly around the enemy, then leaps up and fires a projectile of true leg air at a single enemy target, dealing Magical Damage of #C0x3D8A99#470% Magic Power#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Magical Damage#C0x5B545B#; this attack is guaranteed to hit; if the target is still alive, the remaining power wave on the enemy will deal additional damage equal to 35% of the ultimate skill\'s damage before the target can attack.',
		simDesc_vn = 'Lio Luu chạy quanh kẻ thù với tốc độ nhanh, sau đó nhảy lên phát ra Chân Khí Đạn vào mục tiêu đơn lẻ của đối phương. Đòn tấn công này sẽ trúng chắc chắn, nếu mục tiêu còn sống, dư lực từ Bước Sóng sẽ gây thêm sát thương trước khi bản thân hành động.',
		simDesc_en = 'Lio Luu swiftly runs around the enemy, then leaps up to unleash the Vitality Bullet on a single opponent. This attack is a guaranteed hit, and if the target survives, the residual force from Wave Step will deal additional damage before acting again.',
		simDesc_th = 'ลิโอ ลู่วิ่งอย่างรวดเร็วรอบศัตรู จากนั้นกระโดดขึ้นปล่อยลูกปืนชี่ไปยังเป้าหมายเดี่ยวของฝ่ายตรงข้าม การโจมตีนี้จะโดนอย่างแน่นอน หากเป้าหมายยังมีชีวิตอยู่ แรงตกค้างจากก้าวคลื่นจะก่อให้เกิดความเสียหายเพิ่มเติมก่อนที่จะเคลื่อนไหวอีกครั้ง',
		simDesc_in = 'Lio Luu berlari cepat mengelilingi musuh, lalu melompat untuk meluncurkan Peluru Vitalitas ke satu target lawan. Serangan ini pasti mengenai, dan jika target masih hidup, sisa tenaga dari Langkah Gelombang akan menyebabkan kerusakan tambahan sebelum bertindak lagi.',
		simDesc_ph = 'Si Lio Luu ay mabilis na tumakbo sa paligid ng kalaban, pagkatapos ay tumalon upang maglunsad ng Chân Khí Bullet sa isang target lamang ng kalaban. Ang atakeng ito ay tiyak na tatamaan, at kung buhay pa ang target, ang natitirang lakas mula sa Wave Step ay magdudulot ng karagdagang pinsala bago muli kumilos.',
		simDesc_ma = 'Lio Luu berlari laju mengelilingi musuh, kemudian melompat untuk melepaskan Peluru Chi ke sasaran tunggal musuh. Serangan ini pasti terkena, dan jika sasaran masih hidup, daya lebihan dari Langkah Gelombang akan menyebabkan kerosakan tambahan sebelum bertindak semula.',
		simDesc = 'Lio Luu swiftly runs around the enemy, then leaps up to unleash the Vitality Bullet on a single opponent. This attack is a guaranteed hit, and if the target survives, the residual force from Wave Step will deal additional damage before acting again.',
		starEffect = __data_t__starEffect[22413],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sát thương từ sức mạnh sóng dẫn sẽ tạo thêm 35% sát thương cho kỹ năng đặc biệt này.',
		starEffectDesc = 'Additional Effect: Damage from Wave Power creates 35% extra damage for this special skill. #F x# #L x#',
		starEffectDesc_en = 'Additional Effect: Damage from Wave Power creates 35% extra damage for this special skill. #F x# #L x#',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ความเสียหายจากพลังคลื่นจะสร้างความเสียหายเพิ่มขึ้น 35% สำหรับสกิลพิเศษนี้ #F x# #L x#',
		starEffectDesc_in = 'Efek Tambahan: Kerusakan dari kekuatan gelombang akan memberikan 35% kerusakan tambahan untuk keterampilan khusus ini. #F x# #L x#',
