	[22423] = {
		id = 22423,
		skillName_vn = 'Quay về trời',
		skillName_en = 'Return to the sky',
		skillName_th = 'กลับสู่ท้องฟ้า',
		skillName_in = 'Kembali ke langit',
		skillName_ph = 'Bumalik sa langit',
		skillName_ma = 'Kembali ke langit',
		skillName = 'Return to the sky',
		describe_vn = 'Hinata Hyuga nhảy lên, sau đó thực hiện Hồi Thiên, tấn công mục tiêu hàng trước của địch, gây Sát Thương Phép Thuật #C0x3D8A99#280% Công Phép#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# Sát Thương Phép Thuật#C0x5B545B#; đòn tấn công này chắc chắn trúng; nếu mục tiêu còn sống, sức mạnh Hồi Thiên còn lại trên kẻ địch sẽ gây thêm sát thương bằng 35% sát thương của kỹ năng tối thượng này trước khi mục tiêu có thể tấn công.',
		describe_en = 'Hinata Hyuga jumps up, then performs Heavenly Return, attacking the enemy\'s front row target, dealing Magical Damage #C0x3D8A99#280% Magic Power#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# Magical Damage#C0x5B545B#; this attack is guaranteed to hit; if the target survives, the remaining Heavenly Return power on the enemy will cause additional damage equal to 35% of this ultimate skill\'s damage before the target can attack.',
		describe_th = 'ฮินาตะ ฮิวงะ กระโดดขึ้น จากนั้นใช้ท่า \'หวนคืนสวรรค์\' โจมตีเป้าหมายแถวหน้าของศัตรู สร้างความเสียหายทางเวทมนตร์ #C0x3D8A99#280% พลังเวท#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# ความเสียหายทางเวท#C0x5B545B#; การโจมตีนี้จะโดนอย่างแน่นอน; หากเป้าหมายยังมีชีวิตอยู่ พลังหวนคืนสวรรค์ที่เหลือบนศัตรูจะสร้างความเสียหายเพิ่มเติมเป็น 35% ของความเสียหายสกิลอัลติเมทนี้ก่อนที่เป้าหมายจะได้โจมตี',
		describe_in = 'Hinata Hyuga melompat ke atas, kemudian melakukan Kembalinya Surga, menyerang target barisan depan musuh, memberikan Kerusakan Magical #C0x3D8A99#280% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# Kerusakan Magical#C0x5B545B#; serangan ini pasti mengenai; jika target masih hidup, kekuatan Kembalinya Surga yang tersisa pada musuh akan memberikan kerusakan tambahan sebesar 35% dari kerusakan skill ultimate ini sebelum target dapat menyerang.',
		describe_ph = 'Tumalon si Hinata Hyuga pataas, pagkatapos ay isinasagawa ang Huling Pagbabalik, inaatake ang pyramide ng mga kalaban sa harapan, na nagdudulot ng Pambihirang Pinsala #C0x3D8A99#280% Lakas ng Salamangka#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# Pambihirang Pinsala#C0x5B545B#; tiyak na tatama ang atakeng ito; kung buhay pa ang target, ang natitirang kapangyarihan ng Huling Pagbabalik sa kalaban ay magdudulot ng karagdagang pinsala na katumbas ng 35% ng pinsala ng pinakamatinding kasanayang ito bago pa makaatake ang target.',
		describe_ma = 'Hinata Hyuga melompat ke atas, kemudian melakukan Pulang Ke Syurga, menyerang sasaran barisan hadapan musuh, memberikan Kerosakan Magikal #C0x3D8A99#280% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# Kerosakan Magikal#C0x5B545B#; serangan ini pasti mengenai; jika sasaran masih hidup, kuasa Pulang Ke Syurga yang tinggal pada musuh akan menyebabkan kerosakan tambahan sebanyak 35% daripada kerosakan kemahiran ulti ini sebelum sasaran boleh menyerang.',
		describe = 'Hinata Hyuga jumps up, then performs Heavenly Return, attacking the enemy\'s front row target, dealing Magical Damage #C0x3D8A99#280% Magic Power#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# Magical Damage#C0x5B545B#; this attack is guaranteed to hit; if the target survives, the remaining Heavenly Return power on the enemy will cause additional damage equal to 35% of this ultimate skill\'s damage before the target can attack.',
		simDesc_vn = 'Nhật Hướng Hiina nhảy lên, ngay sau đó thực hiện Hồi Thiên, tấn công mục tiêu hàng trước của đối phương. Đòn tấn công này sẽ trúng chắc chắn, nếu mục tiêu còn sống, dư lực từ Hồi Thiên sẽ gây thêm sát thương trước khi bản thân hành động.',
		simDesc_en = 'Hiina Japan jumps up, then immediately performs Heavenly Return, attacking the opponent\'s front-line target. This attack will definitely hit, and if the target is still alive, the residual power from Heavenly Return will cause additional damage before Hiina acts again.',
		simDesc_th = 'ฮินะ ญี่ปุ่นกระโดดขึ้น แล้วทันทีทำการ ฮอยเทียน โจมตีเป้าหมายแถวหน้าของฝ่ายตรงข้าม การโจมตีนี้จะโดนอย่างแน่นอน หากเป้าหมายยังมีชีวิตอยู่ พลังตกค้างจาก ฮอยเทียน จะสร้างความเสียหายเพิ่มเติมก่อนที่ฮินะจะลงมืออีกครั้ง',
		simDesc_in = 'Hiina Jepang melompat, lalu segera melakukan Hồi Thiên, menyerang target barisan depan lawan. Serangan ini pasti akan mengenai, dan jika target masih hidup, sisa kekuatan dari Hồi Thiên akan menyebabkan kerusakan tambahan sebelum Hiina bertindak kembali.',
		simDesc_ph = 'Tumalon si Hiina Japan, pagkatapos ay agad na isinagawa ang Hồi Thiên, inaatake ang front-line na target ng kalaban. Ang pag-atakeng ito ay tiyak na tatama, at kung buhay pa ang target, ang natitirang puwersa mula sa Hồi Thiên ay magdudulot ng karagdagang pinsala bago muling kumilos si Hiina.',
		simDesc_ma = 'Hiina Jepun melompat, kemudian segera melakukan Hồi Thiên, menyerang sasaran barisan hadapan pihak lawan. Serangan ini pasti akan mengena, dan jika sasaran masih hidup, tenaga tambahan daripada Hồi Thiên akan menyebabkan kerosakan tambahan sebelum Hiina bertindak semula.',
		simDesc = 'Hiina Japan jumps up, then immediately performs Heavenly Return, attacking the opponent\'s front-line target. This attack will definitely hit, and if the target is still alive, the residual power from Heavenly Return will cause additional damage before Hiina acts again.',
		starEffect = __data_t__starEffect[22423],
