	[22433] = {
		id = 22433,
		skillName_vn = 'Ván lướt cực chất',
		skillName_en = 'Super cool round',
		skillName_th = 'รอบสุดเจ๋ง',
		skillName_in = 'Babak sangat keren',
		skillName_ph = 'Napakahusay na round',
		skillName_ma = 'Pusingan yang sangat hebat',
		skillName = 'Super cool round',
		describe_vn = 'Lucario biểu diễn kỹ năng ván trượt tấn công mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#480% Công Phép thuật#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đòn tấn công này chắc chắn trúng; nếu mục tiêu còn sống, sức mạnh sóng dẫn còn lại trên kẻ địch sẽ gây thêm sát thương bằng 35% sát thương của kỹ năng này trước khi mục tiêu có thể tấn công',
		describe_en = 'Lucario performs a skateboarding skill that attacks a single enemy target, dealing #C0x3D8A99#480% Magic Power#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Magic Damage #C0x5B545B#. This attack is guaranteed to hit; if the target survives, the remaining aura power on the enemy will deal additional damage equal to 35% of this skill\'s damage before the target can retaliate.',
		describe_th = 'ลูคาริโอแสดงทักษะการเล่นสเก็ตบอร์ดโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0x3D8A99#480% พลังเวทย์#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# ความเสียหายเวทย์มนตร์ #C0x5B545B# การโจมตีนี้จะต้องโดนอย่างแน่นอน; หากเป้าหมายยังมีชีวิตอยู่ พลังออร่าที่เหลือบนศัตรูจะสร้างความเสียหายเพิ่มเติมเท่ากับ 35% ของความเสียหายของสกิลนี้ก่อนที่เป้าหมายจะสามารถโจมตีกลับได้',
		describe_in = 'Lucario menampilkan skill skateboard yang menyerang satu musuh, menghasilkan #C0x3D8A99#480% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Damage Sihir #C0x5B545B#. Serangan ini pasti mengenai; jika target masih hidup, kekuatan aura yang tersisa pada musuh akan memberikan damage tambahan sebesar 35% dari damage skill ini sebelum target dapat menyerang balik.',
		describe_ph = 'Gumaganap si Lucario ng kasanayan sa skateboarding na umaatake sa isang kalaban, na nagdudulot ng #C0x3D8A99#480% Lakas ng Salamangka#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Pinsalang Salamangka #C0x5B545B#. Tiyak na tatama ang atakeng ito; kung ang target ay buhay pa, ang natitirang kapangyarihan ng aura sa kalaban ay magdudulot ng karagdagang pinsala na katumbas ng 35% ng pinsala ng kasanayang ito bago makapagpagtanggol ang target.',
		describe_ma = 'Lucario mempamerkan kemahiran meluncur papan yang menyerang satu sasaran musuh, memberikan #C0x3D8A99#480% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Serangan ini pasti tepat mengenai; jika sasaran masih hidup, kekuatan aura yang tinggal pada musuh akan menyebabkan kerosakan tambahan sebanyak 35% daripada kerosakan kemahiran ini sebelum sasaran dapat menyerang balik.',
		describe = 'Lucario performs a skateboarding skill that attacks a single enemy target, dealing #C0x3D8A99#480% Magic Power#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Magic Damage #C0x5B545B#. This attack is guaranteed to hit; if the target survives, the remaining aura power on the enemy will deal additional damage equal to 35% of this skill\'s damage before the target can retaliate.',
		simDesc_vn = 'Luka Liêu nhảy lên, ngay sau đó phát ra Chân Khí Đạn tấn công mục tiêu đơn lẻ của đối phương. Đòn tấn công này sẽ trúng chắc chắn, nếu mục tiêu còn sống, dư lực từ Bước Sóng sẽ gây thêm sát thương trước khi bản thân hành động.',
		simDesc_en = 'Luka Liêu jumps up, then immediately releases a Vital Energy Bullet targeting a single enemy. This attack is guaranteed to hit; if the target survives, the residual force from Wave Step will deal additional damage before Luka acts again.',
		simDesc_th = 'ลูคา เหลียว กระโดดขึ้น จากนั้นทันทีปล่อย กระสุนพลังชี่โจมตีเป้าหมายเดี่ยวของศัตรู การโจมตีนี้จะโดนแน่นอน หากเป้าหมายยังมีชีวิตอยู่ พลังตกค้างจากก้าวลูกคลื่นจะสร้างความเสียหายเพิ่มเติมก่อนที่ลูคาจะลงมืออีกครั้ง',
		simDesc_in = 'Luka Liêu melompat, kemudian segera melepaskan Peluru Energi Vital yang menyerang satu target musuh. Serangan ini pasti mengenai; jika target masih hidup, sisa kekuatan dari Langkah Gelombang akan menyebabkan kerusakan tambahan sebelum Luka bertindak lagi.',
		simDesc_ph = 'Tumalon si Luka Liêu, pagkatapos ay agad na nagpakawala ng Vital Energy Bullet upang atakihin ang isang tiyak na target ng kalaban. Ang atakeng ito ay tiyak na tatama; kung buhay pa ang target, ang natitirang lakas mula sa Wave Step ay magdudulot pa ng karagdagang pinsala bago muling kumilos si Luka.',
		simDesc_ma = 'Luka Liêu melompat, kemudian segera melepaskan Peluru Tenaga Vital yang menyerang satu sasaran musuh. Serangan ini pasti tepat; jika sasaran masih hidup, sisa tenaga dari Langkah Gelombang akan menyebabkan kerosakan tambahan sebelum Luka bertindak semula.',
		simDesc = 'Luka Liêu jumps up, then immediately releases a Vital Energy Bullet targeting a single enemy. This attack is guaranteed to hit; if the target survives, the residual force from Wave Step will deal additional damage before Luka acts again.',
		starEffect = __data_t__starEffect[22433],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sát thương từ sức mạnh sóng dẫn sẽ tạo thêm 35% sát thương cho kỹ năng đặc biệt này.',
