	[23023] = {
		id = 23023,
		skillName_vn = 'Sức mạnh băng glacier',
		skillName_en = 'Glacier ice power',
		skillName_th = 'พลังน้ำแข็งกลาเซียร์',
		skillName_in = 'Kekuatan es gletser',
		skillName_ph = 'Kapangyarihan ng yelong glacier',
		skillName_ma = 'Kekuatan ais glasier',
		skillName = 'Glacier ice power',
		describe_vn = 'Bão Tuyết Vương hấp thụ sức mạnh băng hà từ bên ngoài, sau đó biến xung quanh thành băng hà, tấn công toàn bộ mục tiêu kẻ địch, gây ra #C0xE69900#140% Công Vật Lý#C0x5B545B#+$(skillLevel*4*30)$ Sát Thương Vật Lý #C0xF13B54##C0x5B545B#, và có 12% xác suất [đóng băng] mục tiêu trong 1 lượt (đóng băng: hiệu ứng kiểm soát, không thể hành động, bị giải trừ khi nhận sát thương tích lũy vượt quá 25% máu của mục tiêu), đồng thời tăng 15% phòng thủ vật lý và phòng thủ pháp thuật của bản thân, kéo dài 2 lượt, mỗi kẻ địch bị đóng băng trên sân sẽ tăng thêm 3% hiệu quả tăng phòng thủ kép',
		describe_en = 'Blizzard King absorbs glacial power from outside, then transforms the surroundings into ice glaciers, attacking all enemy targets, dealing #C0xE69900#140% Physical Attack#C0x5B545B# + $(skillLevel*4*30)$ Physical Damage #C0xF13B54##C0x5B545B#. It also has a 12% chance to [freeze] targets for 1 turn (freeze: control effect, cannot act, dispelled if accumulated damage exceeds 25% of the target\'s health). At the same time, it increases the user\'s physical and magical defense by 15% for 2 turns. Each frozen enemy on the battlefield further increases the double defense boost effect by 3%.',
		describe_th = 'ราชาอากาศหิมะดูดซับพลังน้ำแข็งจากภายนอก จากนั้นเปลี่ยนรอบตัวเป็นธารน้ำแข็ง โจมตีเป้าหมายศัตรูทั้งหมด ทำให้เกิด #C0xE69900#140% การโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*30)$ ความเสียหายทางกายภาพ #C0xF13B54##C0x5B545B# มีโอกาส 12% ที่จะ [แช่แข็ง] เป้าหมายเป็นเวลา 1 รอบ (แช่แข็ง: เอฟเฟกต์ควบคุม ไม่สามารถกระทำการได้ ถูกลบออกเมื่อรับความเสียหายสะสมเกิน 25% ของพลังชีวิตของเป้าหมาย) พร้อมกันนี้เพิ่มการป้องกันกายภาพและเวทมนตร์ของตนเองขึ้น 15% เป็นเวลา 2 รอบ ศัตรูที่ถูกแช่แข็งแต่ละตัวบนสนามจะเพิ่มประสิทธิภาพการเพิ่มป้องกันสองเท่าอีก 3%',
		describe_in = 'Raja Badai Salju menyerap kekuatan glasial dari luar, kemudian mengubah sekeliling menjadi glasial es, menyerang semua target musuh, menyebabkan #C0xE69900#140% Serangan Fisik#C0x5B545B# + $(skillLevel*4*30)$ Kerusakan Fisik #C0xF13B54##C0x5B545B#. Memiliki peluang 12% untuk [membekukan] target selama 1 giliran (membekukan: efek kontrol, tidak dapat bertindak, hilang jika menerima akumulasi kerusakan melebihi 25% dari kesehatan target), sekaligus meningkatkan pertahanan fisik dan magis dirinya sebesar 15% selama 2 giliran. Setiap musuh yang dibekukan di medan pertempuran akan menambah efek peningkatan pertahanan ganda sebesar 3%.',
		describe_ph = 'Ang Hari ng Bagyong Niyebe ay sumisipsip ng lakas ng glacier mula sa labas, pagkatapos ay ginagawang glacier ang paligid, inaatake ang lahat ng kalabang target, nagdudulot ng #C0xE69900#140% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*30)$ Pisikal na Pinsala #C0xF13B54##C0x5B545B#. May 12% tsansa na [mag-freeze] ng target sa loob ng 1 turn (freeze: epektong kontrol, hindi makakilos, matatanggal kapag nakatanggap ng naipong pinsala na lumampas sa 25% ng buhay ng target), kasabay nito ay nagpapataas ng 15% pisikal at magic na depensa ng sarili sa loob ng 2 turn. Bawat yelong kalabang nasa battlefield ay dagdag pa ng 3% sa bisa ng double defense boost.',
		describe_ma = 'Raja Ribut Salji menyerap kuasa glasial dari luar, kemudian mengubah sekitar menjadi glasier ais, menyerang semua sasaran musuh, menyebabkan #C0xE69900#140% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*30)$ Kerosakan Fizikal #C0xF13B54##C0x5B545B#. Ia juga mempunyai peluang 12% untuk [membekukan] sasaran selama 1 pusingan (membekukan: kesan kawalan, tidak dapat bertindak, dibatalkan jika menerima kerosakan terkumpul melebihi 25% hayat sasaran), pada masa sama meningkatkan pertahanan fizikal dan pertahanan sihir sendiri sebanyak 15% selama 2 pusingan. Setiap musuh yang dibekukan di medan akan menambah keberkesanan peningkatan pertahanan berganda sebanyak 3%.',
		describe = 'Blizzard King absorbs glacial power from outside, then transforms the surroundings into ice glaciers, attacking all enemy targets, dealing #C0xE69900#140% Physical Attack#C0x5B545B# + $(skillLevel*4*30)$ Physical Damage #C0xF13B54##C0x5B545B#. It also has a 12% chance to [freeze] targets for 1 turn (freeze: control effect, cannot act, dispelled if accumulated damage exceeds 25% of the target\'s health). At the same time, it increases the user\'s physical and magical defense by 15% for 2 turns. Each frozen enemy on the battlefield further increases the double defense boost effect by 3%.',
		simDesc_vn = 'Bão Tuyết Vương hấp thụ sức mạnh từ băng giá bên ngoài, sau đó biến xung quanh thành băng giá, tấn công toàn bộ mục tiêu của đối phương, có khả năng làm đông băng mục tiêu và tăng cường phòng thủ vật lý và pháp lý của bản thân.',
		simDesc_en = 'Blizzard King absorbs power from the surrounding frost, then transforms the area into icy cold, attacking all enemy targets, with the ability to freeze enemies and enhance both physical and magical defense.',
		simDesc_th = 'ราชาน้ำแข็งดูดซับพลังจากความหนาวเย็นภายนอก จากนั้นเปลี่ยนรอบตัวให้กลายเป็นน้ำแข็งโจมตีเป้าหมายศัตรูทั้งหมด มีความสามารถในการแช่แข็งเป้าหมายและเพิ่มการป้องกันทางกายภาพและเวทมนตร์ของตนเอง',
		simDesc_in = 'Raja Badai Salju menyerap kekuatan dari hawa dingin di luar, kemudian mengubah sekitarnya menjadi es, menyerang semua target musuh, dengan kemampuan membekukan target dan memperkuat pertahanan fisik dan magis dirinya sendiri.',
		simDesc_ph = 'Ang Hari ng Blizzard ay sumisipsip ng kapangyarihan mula sa yelong hangin sa labas, pagkatapos ay ginagawang nagyeyelong paligid, inaatake ang lahat ng kalaban, may kakayahang mag-freeze ng mga target at palakasin ang sariling pisikal at mahiwagang depensa.',
		simDesc_ma = 'Raja Ribut Salji menyerap kuasa dari kesejukan di luar, kemudian mengubah sekeliling menjadi ais, menyerang semua sasaran musuh, dengan keupayaan untuk membekukan sasaran dan meningkatkan pertahanan fizikal dan sihir sendiri.',
		simDesc = 'Blizzard King absorbs power from the surrounding frost, then transforms the area into icy cold, attacking all enemy targets, with the ability to freeze enemies and enhance both physical and magical defense.',
		starEffect = __data_t__starEffect[23023],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Các đơn vị chưa bị đóng băng bởi kỹ năng đặc biệt sẽ giảm 10% tốc độ trong 1 lượt.',
		starEffectDesc = 'Additional effect: Units not frozen by special skills will have their speed reduced by 10% for 1 turn.',
		starEffectDesc_en = 'Additional effect: Units not frozen by special skills will have their speed reduced by 10% for 1 turn.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: หน่วยที่ไม่ได้ถูกแช่แข็งด้วยสกิลพิเศษจะลดความเร็วลง 10% เป็นเวลา 1 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Unit yang tidak dibekukan oleh skill khusus akan mengurangi kecepatan sebesar 10% selama 1 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Ang mga yunit na hindi nagyeyelo dahil sa espesyal na kasanayan ay babawasan ang bilis ng 10% sa loob ng 1 turn.',
		starEffectDesc_ma = 'Kesan tambahan: Unit yang tidak dibekukan oleh kemahiran khas akan mengurangkan kelajuan sebanyak 10% selama 1 pusingan.',
		zawakeEffect = __data_t__zawakeEffect[23023],
		-- {79003}
		zawakeEffectDesc = 'Blizzard King absorbs the glacier power from outside, then turns the surroundings into glaciers, attacking all enemy targets, dealing #C0xE69900#140% Physical Attack#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Physical Damage#C0x5B545B#, with a 20% chance to <freeze> the target for 1 turn (freeze: control effect, unable to act, removed after receiving accumulated damage exceeding 25% of the target\'s HP), and increases own physical defense and magic defense by 15%, lasting 2 turns, each frozen enemy on the field increases the double defense boost effect by 3%.',
		zawakeEffectDesc_en = 'Blizzard King absorbs the glacier power from outside, then turns the surroundings into glaciers, attacking all enemy targets, dealing #C0xE69900#140% Physical Attack#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Physical Damage#C0x5B545B#, with a 20% chance to <freeze> the target for 1 turn (freeze: control effect, unable to act, removed after receiving accumulated damage exceeding 25% of the target\'s HP), and increases own physical defense and magic defense by 15%, lasting 2 turns, each frozen enemy on the field increases the double defense boost effect by 3%.',
		zawakeEffectDesc_th = 'ราชันย์พายุหิมะดูดซับพลังน้ำแข็งจากภายนอก จากนั้นเปลี่ยนรอบตัวเป็นน้ำแข็งโบราณ โจมตีเป้าหมายศัตรูทั้งหมด สร้าง #C0xE69900#140% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# และมีโอกาส 20% ที่จะ <แช่แข็ง> เป้าหมายเป็นเวลา 1 เทิร์น (แช่แข็ง: เอฟเฟ็กต์ควบคุม ไม่สามารถกระทำได้ ถูกลบหลังจากรับความเสียหายสะสมเกิน 25% ของพลังชีวิตเป้าหมาย) และเพิ่มการป้องกันทางกายภาพและเวทมนตร์ของตัวเอง 15% เป็นเวลา 2 เทิร์น ทุกคนที่ถูกแช่แข็งบนสนามศัตรูจะเพิ่มผลบวกป้องกันเป็นสองเท่าขึ้นอีก 3%',
		zawakeEffectDesc_in = 'Raja Badai Salju menyerap kekuatan glasier dari luar, kemudian mengubah sekitar menjadi glasier, menyerang semua target musuh, memberikan #C0xE69900#140% Serangan Fisik#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, dengan peluang 20% untuk <membekukan> target selama 1 giliran (membekukan: efek kontrol, tidak bisa bertindak, dibatalkan setelah menerima akumulasi kerusakan melebihi 25% HP target), serta meningkatkan pertahanan fisik dan pertahanan sihir diri sendiri sebesar 15%, berlangsung 2 giliran, setiap musuh yang dibekukan di lapangan menambah efek peningkatan pertahanan ganda sebesar 3%',
		zawakeEffectDesc_ph = 'Absorbs ang kapangyarihan ng glacier mula sa labas, pagkatapos ay ginagawang glacier ang paligid, inaatake ang lahat ng kalabang target, nagdudulot ng #C0xE69900#140% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, at may 20% tsansa na <yelong> ang target sa loob ng 1 turno (yelo: epektong kontrol, hindi makakilos, aalisin pagkatapos makatanggap ng naipong pinsalang higit sa 25% ng buhay ng target), at pinapataas ng 15% ang sariling pisikal na depensa at mahiwagang depensa, tumatagal ng 2 turno, bawat kalabang frozen sa field ay nagdadagdag ng 3% ng dobleng epekto ng pagdagdag ng depensa',
		zawakeEffectDesc_ma = 'Raja Ribut Salji menyerap kekuatan glasier dari luar, kemudian menukar kawasan sekitar menjadi glasier, menyerang semua sasaran musuh, memberikan #C0xE69900#140% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, dengan peluang 20% untuk <membekukan> sasaran selama 1 giliran (membekukan: kesan kawalan, tidak boleh bertindak, dibuang selepas menerima kerosakan terkumpul melebihi 25% HP sasaran), dan meningkatkan pertahanan fizikal dan pertahanan sihir sendiri sebanyak 15%, berlangsung selama 2 giliran, setiap musuh yang dibekukan di medan menambah keberkesanan peningkatan pertahanan dua kali ganda sebanyak 3%',
		zawakeEffectDesc_vn = 'Bão Tuyết Vương hấp thụ sức mạnh băng hà từ bên ngoài, sau đó biến xung quanh thành băng hà, tấn công toàn bộ mục tiêu địch, gây #C0xE69900#140% Công Vật Lý#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, và có 20% xác suất <đóng băng> mục tiêu 1 lượt (đóng băng: hiệu ứng kiểm soát, không thể hành động, bị giải trừ sau khi nhận sát thương tích lũy vượt quá 25% sinh mệnh của mục tiêu), và tăng 15% phòng thủ vật lý và Phép Phòng của bản thân, kéo dài 2 lượt, mỗi người bị đóng băng trên sân địch tăng thêm 3% hiệu quả tăng phòng thủ đôi',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'And has a 12% chance to <Freeze> the target for 1 turn\n#F20# \n#F40##C0x5c9970#→And has a 20% chance to <Freeze> the target for 1 turn#C0x5B545B#',
		zawakeSimpleDesc_en = 'And has a 12% chance to <Freeze> the target for 1 turn\n#F20# \n#F40##C0x5c9970#→And has a 20% chance to <Freeze> the target for 1 turn#C0x5B545B#',
		zawakeSimpleDesc_th = 'มีโอกาส 12% ที่จะ<แช่แข็ง>เป้าหมายเป็นเวลา 1 เทิร์น\n#F20# \n#F40##C0x5c9970#→มีโอกาส 20% ที่จะ<แช่แข็ง>เป้าหมายเป็นเวลา 1 เทิร์น#C0x5B545B#',
		zawakeSimpleDesc_in = 'Dan memiliki 12% peluang untuk <Membekukan> target selama 1 giliran\n#F20# \n#F40##C0x5c9970#→Dan memiliki 20% peluang untuk <Membekukan> target selama 1 giliran#C0x5B545B#',
		zawakeSimpleDesc_ph = 'May 12% na tsansa na <ma-freeze> ang target ng 1 turn\n#F20# \n#F40##C0x5c9970#→May 20% na tsansa na <ma-freeze> ang target ng 1 turn#C0x5B545B#',
		zawakeSimpleDesc_ma = 'Dan mempunyai 12% kebarangkalian untuk <Membekukan> sasaran selama 1 pusingan\n#F20# \n#F40##C0x5c9970#→Dan mempunyai 20% kebarangkalian untuk <Membekukan> sasaran selama 1 pusingan#C0x5B545B#',
