	[23511] = {
		id = 23511,
		skillName_vn = 'Tàn ảnh cước',
		skillName_en = 'Footprint of ruin',
		skillName_th = 'รอยเท้าความพินาศ',
		skillName_in = 'Jejak kehancuran',
		skillName_ph = 'Bakás ng pagkawasak',
		skillName_ma = 'Jejak kemusnahan',
		skillName = 'Footprint of ruin',
		describe_vn = 'Rùa Sennin lao tới trước mục tiêu với tốc độ cao và tung cú đá sang một bên để tấn công một mục tiêu địch, gây #C0x3D8A99#160% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, tăng Sát Thương Vật Lý cộng thêm của bản thân thêm 15%, tồn tại trong 2 hiệp và có thể cộng dồn 2 lần',
		describe_en = 'The Sennin Turtle charges toward the target at high speed and delivers a side kick to attack an enemy target, dealing #C0x3D8A99#160% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#, increasing the user\'s additional Physical Damage by 15% for 2 turns, stacking up to 2 times.',
		describe_th = 'เต่าผู้ทรงภูมิปัญญาพุ่งไปยังเป้าหมายด้วยความเร็วสูงและเตะด้านข้างโจมตีเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ #C0x3D8A99#160%#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มความเสียหายทางกายภาพเสริมของตัวเองอีก 15% อยู่ได้นาน 2 เทิร์น และสามารถซ้อนทับได้ 2 ครั้ง',
		describe_in = 'Kura Sennin melesat ke depan target dengan kecepatan tinggi dan melepaskan tendangan ke samping untuk menyerang target musuh, memberikan #C0x3D8A99#160% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, meningkatkan Kerusakan Fisik tambahan sendiri sebesar 15%, bertahan selama 2 giliran dan dapat bertumpuk hingga 2 kali.',
		describe_ph = 'Ang Sennin na pagong ay mabilis na lumapit sa target at nagbigay ng sipa sa gilid upang atakihin ang kalabang target, nagdudulot ng #C0x3D8A99#160% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#, pinapataas ang karagdagang Pisikal na Pinsala ng sarili ng 15%, tumatagal ng 2 turn at maaaring mag-stack ng hanggang 2 beses.',
		describe_ma = 'Kura Sennin meluru ke hadapan sasaran dengan kelajuan tinggi dan menendang ke tepi untuk menyerang sasaran musuh, memberikan #C0x3D8A99#160% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, meningkatkan Kerosakan Fizikal tambahan diri sendiri sebanyak 15%, bertahan selama 2 pusingan dan boleh bertindih sehingga 2 kali.',
