	[23513] = {
		id = 23513,
		skillName_vn = 'Siêu Quy Phái Khí Công',
		skillName_en = 'Super Martial Qi Technique',
		skillName_th = 'วิชากระบวนท่าอากาศชั้นยอด',
		skillName_in = 'Teknik Qi Bela Diri Super',
		skillName_ph = 'Super Martial Qi Technique',
		skillName_ma = 'Teknik Qi Seni Bela Diri Super',
		skillName = 'Super Martial Qi Technique',
		describe_vn = 'Rùa Sennin chắp hai tay lại, ngưng tụ Khí trong lòng bàn tay và phóng ra khí công kiểu siêu rùa tấn công hàng kẻ địch, gây #C0x3D8A99#550% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, đồng thời thêm [Vết thương hắc ám tái sinh] tác dụng lên mục tiêu: khi kết thúc vòng đấu lớn, mục tiêu sẽ nhận sát thương thực tế bằng 30% tổng sát thương gánh chịu trong vòng đấu lớn (tối đa bằng 900% đòn Sát Thương Vật Lý của Kame Sennin); sau khi thực hiện chiêu thức đặc biệt, tất cả [Sát thương chí mạng] sẽ bị xóa khỏi chính nó.',
		describe_en = 'Sage Turtle clasps both hands together, condenses Qi in the palms, and releases a super turtle-style Qi attack on a line of enemies, dealing #C0x3D8A99#550% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Physical Damage#C0x5B545B#, while applying [Dark Rebirth Wound] on the target: at the end of the major round, the target will take true damage equal to 30% of the total damage suffered during the major round (up to 900% of Kame Sennin\'s Physical Damage); after executing the special move, all [Critical Damage] on itself will be removed.',
		describe_th = 'เต่าเซนชิน ประสานมือทั้งสองไว้ด้วยกัน รวมพลังชี่ในฝ่ามือ และปล่อยพลังชี่รูปแบบเต่ายอดเยี่ยมโจมตีเป็นแถวใส่ศัตรู ก่อให้เกิด #C0x3D8A99#550% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# พร้อมทั้งเพิ่ม [บาดแผลฟื้นฟูมืด] บนเป้าหมาย: เมื่อสิ้นสุดรอบใหญ่ เป้าหมายจะได้รับดาเมจจริงเท่ากับ 30% ของความเสียหายที่ได้รับในรอบใหญ่นั้น (สูงสุดเท่ากับ 900% ความเสียหายทางกายภาพของ Kame Sennin); หลังใช้ท่าไม้ตายพิเศษ ทุก [ความเสียหายคริติคอล] บนตัวเขาจะถูกลบออก',
		describe_in = 'Kura Sennin menyatukan kedua tangan, mengumpulkan Qi di telapak tangan dan meluncurkan serangan Qi gaya kura-kura super ke barisan musuh, menyebabkan #C0x3D8A99#550% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, sekaligus menambahkan [Luka Kegelapan Reinkarnasi] pada target: pada akhir putaran besar, target akan menerima kerusakan nyata sebesar 30% dari total kerusakan yang diderita selama putaran besar (maksimal sebesar 900% dari Kerusakan Fisik Kame Sennin); setelah melakukan serangan khusus, semua [Kerusakan Kritis] pada dirinya akan dihapus.',
		describe_ph = 'Sennin na Pagong ay magkakasamang ipitin ang mga kamay, nagtitipon ng Qi sa mga palad, at nagpapalabas ng super turtle-style Qi attack sa hanay ng mga kalaban, na nagdudulot ng #C0x3D8A99#550% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#, kasabay ng paglalagay ng [Madilim na Sugat na Muling Bumabuhay] sa target: sa pagtatapos ng malaking round, ang target ay tatanggap ng totoong pinsala na katumbas ng 30% ng kabuuang pinsalang tinanggap sa malaking round (hanggang sa 900% ng Pisikal na Pinsala ng Kame Sennin); pagkatapos gamitin ang espesyal na kasanayan, lahat ng [Critikal na Pinsala] sa sarili nito ay matatanggal.',
		describe_ma = 'Kura Sennin menyatukan kedua tangan, memampatkan Qi di tapak tangan dan melepaskan serangan Qi gaya kura-kura super ke barisan musuh, menyebabkan #C0x3D8A99#550% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, serta menambah [Kecederaan Kegelapan Kebangkitan Semula] ke sasaran: pada akhir pusingan besar, sasaran akan menerima kerosakan sebenar sebanyak 30% daripada jumlah kerosakan yang dialami dalam pusingan besar (maksimum sebanyak 900% Kerosakan Fizikal Kame Sennin); selepas melakukan serangan khas, semua [Kerosakan Kritikal] pada dirinya akan dihapuskan.',
		describe = 'Sage Turtle clasps both hands together, condenses Qi in the palms, and releases a super turtle-style Qi attack on a line of enemies, dealing #C0x3D8A99#550% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54#Physical Damage#C0x5B545B#, while applying [Dark Rebirth Wound] on the target: at the end of the major round, the target will take true damage equal to 30% of the total damage suffered during the major round (up to 900% of Kame Sennin\'s Physical Damage); after executing the special move, all [Critical Damage] on itself will be removed.',
		simDesc_vn = 'Người bất tử chắp hai tay lại, ngưng tụ khí trong lòng bàn tay và phóng ra khí công kiểu siêu rùa để tấn công hàng kẻ địch, thêm hiệu ứng [Sát thương bóng tối tái sinh] cho mục tiêu, để mục tiêu sẽ lại nhận một lượng sát thương thực sự nhất định vào cuối hiệp.',
		simDesc_en = 'The immortal clasped his hands together, condensing energy in his palms and releasing a super turtle-style qi blast to attack a row of enemies, adding the <Dark Rebirth Damage> effect to the targets, causing them to receive a certain amount of true damage at the end of the turn.',
		simDesc_th = 'ผู้เป็นอมตะประสานมือกันเข้าด้วยกัน รวมพลังชี่ในฝ่ามือและปล่อยชี่แบบเต่าซูเปอร์โจมตีแถวศัตรู พร้อมเพิ่มเอฟเฟกต์ [ความเสียหายแห่งการเกิดใหม่ในเงามืด] ให้กับเป้าหมาย เพื่อให้เป้าหมายได้รับความเสียหายจริงในจำนวนหนึ่งตอนจบเทิร์น',
		simDesc_in = 'Orang abadi menyatukan kedua tangannya, mengkondensasikan energi di telapak tangan dan melepaskan serangan qi gaya kura-kura super untuk menyerang barisan musuh, menambahkan efek <Kerusakan Kelahiran Kembali Kegelapan> pada target, agar target menerima sejumlah kerusakan nyata pada akhir giliran.',
		simDesc_ph = 'Pinagpisa ng walang kamatayang kamay, pinagtibay ang enerhiya sa kanyang mga palad at nagpakawala ng super turtle-style na qi para salakayin ang isang hanay ng mga kalaban, nagdagdag ng epekto na <Dark Rebirth Damage> sa mga target, upang makatanggap sila ng tiyak na dami ng tunay na pinsala sa katapusan ng turn.',
		simDesc_ma = 'Orang yang tiada mati menyatukan kedua tangan, menumpukan tenaga dalam tapak tangan dan melepaskan tenaga qi gaya kura-kura super untuk menyerang barisan musuh, menambah kesan <Kerosakan Kegelapan Kelahiran Semula> pada sasaran, supaya sasaran akan menerima sejumlah kerosakan nyata pada penghujung giliran.',
		simDesc = 'The immortal clasped his hands together, condensing energy in his palms and releasing a super turtle-style qi blast to attack a row of enemies, adding the [Dark Rebirth Damage] effect to the targets, causing them to receive a certain amount of true damage at the end of the turn.',
		starEffect = __data_t__starEffect[23513],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng thêm: Thiên Nhân Hợp Nhất: Võ đạo hóa cảnh, nắm giữ sức mạnh luân hồi, khi thi triển tất sát kỹ sẽ mở ra kết giới luân hồi, tạm dừng mọi hành động và hiệu ứng của cả địch và ta, hồi phục 30% lượng sinh mệnh dựa trên sát thương của tất sát kỹ lần này, đồng thời thêm 1 lần tấn công thường.',
		starEffectDesc = 'Additional Effect: Celestial Fusion: Martial Dao reaches a new realm, wielding the power of reincarnation. When executing a finishing skill, it triggers the reincarnation barrier, pausing all actions and effects of both enemies and allies, restores 30% HP based on the damage dealt by the finishing skill, and grants 1 extra normal attack.',
		starEffectDesc_en = 'Additional Effect: Celestial Fusion: Martial Dao reaches a new realm, wielding the power of reincarnation. When executing a finishing skill, it triggers the reincarnation barrier, pausing all actions and effects of both enemies and allies, restores 30% HP based on the damage dealt by the finishing skill, and grants 1 extra normal attack.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: การผสานสวรรค์: วิถีการต่อสู้ก้าวสู่ขั้นสูงสุด ถือครองพลังแห่งการเวียนว่ายตายเกิด เมื่อใช้ทักษะสุดท้ายจะเปิดเกราะกั้นแห่งการเวียนว่ายตายเกิด หยุดการกระทำและเอฟเฟกต์ทั้งหมดของฝ่ายศัตรูและเรา ฟื้นฟูพลังชีวิต 30% ตามความเสียหายของทักษะสุดท้ายครั้งนี้ และเพิ่มการโจมตีปกติอีก 1 ครั้ง',
		starEffectDesc_in = 'Efek Tambahan: Penyatuan Surgawi: Jalan bela diri mencapai tahap lanjutan, menguasai kekuatan reinkarnasi. Saat menggunakan skill penyelesaian, akan membuka perisai reinkarnasi, menghentikan semua aksi dan efek dari musuh dan kita, memulihkan 30% HP berdasarkan damage skill penyelesaian kali ini, dan menambah 1 serangan biasa.',
		starEffectDesc_ph = 'Karagdagang Epekto: Pagsasanib ng Langit at Tao: Ang landas ng pakikipaglaban ay umabot sa bagong antas, hawak ang kapangyarihan ng muling pagsilang. Kapag gumamit ng ganap na kasanayan, bubuksan nito ang hadlang ng muling pagsilang, pihitin ang lahat ng aksyon at epekto ng kalaban at atin, nagpapagaling ng 30% buhay base sa pinsalang dulot ng kasanayang iyon, at nagbibigay ng 1 dagdag na normal na pag-atake.',
		starEffectDesc_ma = 'Kesan Tambahan: Penyatuan Langit: Jalan seni mempertahankan diri mencapai tahap tinggi, menguasai kuasa kitaran semula jadi. Apabila melaksanakan kemahiran penamat, ia akan membuka penghalang kitaran semula jadi, menghentikan semua tindakan dan kesan musuh dan kita, memulihkan 30% hayat berdasarkan kerosakan kemahiran penamat kali ini, dan menambah 1 serangan biasa.',
		zawakeEffect = __data_t__zawakeEffect[23513],
		-- {79003}
		zawakeEffectDesc = 'Kame Sennin clasps both hands together, gathering Qi into the palms, then releases it in a super turtle-style energy attack on enemy ranks, dealing #C0xF13B54# Physical Damage #C0x5B545B Physical Damage 550% #C0x5B545B +$(skillLevel*4*60)$ #, while also applying the <Ultimate Damage Rebirth> effect to the target, so when the large round ends, the target hit will receive 50% of the total damage taken during the large round as true damage (maximum not exceeding 1200% of Kame Sennin\'s Physical Damage); after using this special skill, all <Vital Death> effects are removed from self and the final damage reduction is increased by 10% for one round.',
		zawakeEffectDesc_en = 'Kame Sennin clasps both hands together, gathering Qi into the palms, then releases it in a super turtle-style energy attack on enemy ranks, dealing #C0xF13B54# Physical Damage #C0x5B545B Physical Damage 550% #C0x5B545B +$(skillLevel*4*60)$ #, while also applying the <Ultimate Damage Rebirth> effect to the target, so when the large round ends, the target hit will receive 50% of the total damage taken during the large round as true damage (maximum not exceeding 1200% of Kame Sennin\'s Physical Damage); after using this special skill, all <Vital Death> effects are removed from self and the final damage reduction is increased by 10% for one round.',
		zawakeEffectDesc_th = 'คาเมะ เซ็นนิน ประสานมือทั้งสอง มือรวมพลังชี่เข้าหาฝ่ามือแล้วปล่อยพลังแบบเต่าซุปเปอร์โจมตีศัตรู ก่อให้เกิด #C0xF13B54# ความเสียหายกายภาพ #C0x5B545B ความเสียหายกายภาพ 550% #C0x5B545B +$(skillLevel*4*60)$ # พร้อมกับเพิ่มเอฟเฟกต์ <การฟื้นฟูความเสียหายขั้นสูง> ให้เป้าหมาย เมื่อตอนจบรอบใหญ่ เป้าหมายที่ถูกโจมตีจะได้รับความเสียหายจริงเท่ากับ 50% ของความเสียหายทั้งหมดที่ได้รับในรอบใหญ่นั้น (สูงสุดไม่เกิน 1200% ของความเสียหายกายภาพของคาเมะ เซ็นนิน); หลังใช้ท่าสกิลพิเศษนี้ เอฟเฟกต์ <Vital Death> ทั้งหมดจะถูกลบออกจากตนเองและการลดความเสียหายขั้นสุดท้ายจะเพิ่มขึ้นอีก 10% เป็นเวลา 1 เทิร์น',
		zawakeEffectDesc_in = 'Kame Sennin mengepal kedua tangan, mengumpulkan Qi ke telapak tangan lalu melepaskan serangan energi gaya kura-kura super ke barisan musuh, menyebabkan #C0xF13B54# Kerusakan Fisik #C0x5B545B Kerusakan Fisik 550% #C0x5B545B +$(skillLevel*4*60)$ #, sekaligus menambahkan efek <Reinkarnasi Kerusakan Ultimate> ke target, sehingga saat ronde besar berakhir, target yang terkena serangan akan menerima 50% dari total kerusakan yang diderita selama ronde besar sebagai kerusakan sejati (maksimal tidak melebihi 1200% dari Kerusakan Fisik Kame Sennin); setelah mengeluarkan jurus khusus ini, semua efek <Vital Death> akan dihapus dari diri sendiri dan pengurangan kerusakan akhir akan meningkat sebesar 10% selama 1 giliran.',
		zawakeEffectDesc_ph = 'Kame Sennin ayuin ang parehong mga kamay, kinokolekta ang Qi sa mga palad tapos nagpapalabas ng super turtle-style energy attack sa mga kalabang linya, nagdudulot ng #C0xF13B54# Physical Damage #C0x5B545B Physical Damage 550% #C0x5B545B +$(skillLevel*4*60)$ #, kasabay na inaaplay ang <Ultimate Damage Rebirth> effect sa target, kaya kapag natapos ang malaking round, ang target na tinamaan ay makakatanggap ng 50% ng kabuuang damage na natanggap sa round na iyon bilang true damage (hindi hihigit sa 1200% ng Physical Damage ni Kame Sennin); pagkatapos gumamit ng espesyal na skill na ito, lahat ng <Vital Death> ay matatanggal sa sarili at tataas pa ng 10% ang final damage reduction sa loob ng 1 turn.',
		zawakeEffectDesc_ma = 'Kame Sennin mengepal kedua tangan, mengumpul Qi ke tapak tangan lalu melepaskan serangan tenaga gaya kura-kura super ke barisan musuh, menyebabkan #C0xF13B54# Kerosakan Fizikal #C0x5B545B Kerosakan Fizikal 550% #C0x5B545B +$(skillLevel*4*60)$ #, serta menambah kesan <Reinkarnasi Kerosakan Utama> ke sasaran, jadi apabila pusingan besar berakhir, sasaran yang terkena akan menerima 50% daripada jumlah kerosakan yang ditanggung dalam pusingan besar sebagai kerosakan sebenar (maksimum tidak melebihi 1200% daripada Kerosakan Fizikal Kame Sennin); selepas menggunakan teknik khas ini, semua <Vital Death> akan dihapus dari diri sendiri dan pengurangan kerosakan akhir akan bertambah 10% selama 1 pusingan.',
		zawakeEffectDesc_vn = 'Kame Sennin chắp hai tay lại, gom Khí vào lòng bàn tay rồi phóng ra khí công kiểu siêu rùa tấn công hàng kẻ địch, gây #C0xF13B54# Sát Thương Vật Lý#C0x5B545B Sát Thương Vật Lý 550%#C0x5B545B#+$(skillLevel*4*60)$ #, đồng thời thêm hiệu ứng <Sát thương tối tái sinh> vào mục tiêu, để khi kết thúc vòng đấu lớn, mục tiêu bị trúng đòn sẽ lại nhận 50% tổng sát thương gánh chịu trong vòng đấu lớn là sát thương chuẩn (tối đa không quá 1200% đòn Sát Thương Vật Lý của Kame Sennin); sau khi tung ra chiêu thức đặc biệt, tất cả <Vital Death> sẽ bị xóa khỏi bản thân và mức giảm sát thương cuối cùng sẽ tăng thêm 10% trong 1 hiệp.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Take true damage equal to 30% of total damage taken this round (up to 900% of Kame Sennin\'s Physical Damage); after casting special skill, remove all <Vital Death> from yourself\n#F20# \n#F40##C0x5c9970#→Take 50% of total damage this round as true damage (up to 1200% of Kame Sennin\'s Physical Damage); after casting special skill, remove all <Blood Death> on yourself and increase final damage reduction by 10% for 1 round',
		zawakeSimpleDesc_en = 'Take true damage equal to 30% of total damage taken this round (up to 900% of Kame Sennin\'s Physical Damage); after casting special skill, remove all <Vital Death> from yourself\n#F20# \n#F40##C0x5c9970#→Take 50% of total damage this round as true damage (up to 1200% of Kame Sennin\'s Physical Damage); after casting special skill, remove all <Blood Death> on yourself and increase final damage reduction by 10% for 1 round',
		zawakeSimpleDesc_th = 'รับดาเมจจริงเท่ากับ 30% ของดาเมจทั้งหมดในรอบนี้ (สูงสุด 900% พลังโจมตีกายภาพของ Kame Sennin); หลังใช้สกิลพิเศษ ให้ลบ <Vital Death> ออกจากตัวเอง\n#F20# \n#F40##C0x5c9970#→รับดาเมจจริง 50% จากดาเมจที่ได้รับรอบนี้ (สูงสุด 1200% พลังโจมตีของ Kame Sennin); sau khi sử dụng kỹ năng đặc biệt, xóa toàn bộ <Chết máu> và tăng giảm sát thương cuối cùng thêm 10% trong 1 lượt',
		zawakeSimpleDesc_in = 'Menerima 30% dari total damage ronde ini sebagai True Damage (maks. 900% Serangan Fisik Kame Sennin); setelah menggunakan skill spesial, hilangkan semua <Kematian Vital> dari diri sendiri\n#F20# \n#F40##C0x5c9970#→Menerima 50% total damage sebagai True Damage (maks. 1200% Serangan Fisik Kame Sennin); setelah mengaktifkan skill spesial, hapus semua <Darah Mati> dan tingkatkan pengurangan damage akhir sebesar 10% selama 1 giliran',
		zawakeSimpleDesc_ph = 'Tumatanggap ng 30% ng total damage ngayong round bilang True Damage (max 900% Physical Damage ni Kame Sennin); pagkatapos gamitin ultimate, burahin lahat ng <Vital Death> sa sarili\n#F20# \n#F40##C0x5c9970#→Tumatanggap ng 50% ng total damage bilang True Damage (max 1200%), at pagkatapos ng ultimate, tanggalin lahat ng <Blood Death> at dagdagan ang final damage reduction ng 10% sa loob ng 1 turn',
		zawakeSimpleDesc_ma = 'Terima 30% daripada jumlah kerosakan pusingan ini sebagai Kerosakan Sebenar (maks 900% Serangan Fizikal Kame Sennin); selepas menggunakan skill khas, hapuskan semua <Kematian Vital> dan tingkatkan pengurangan kerosakan akhir sebanyak 10% selama 1 pusingan',
		zawakeSimpleDesc_vn = 'Chịu lại sát thương chuẩn bằng 30% tổng sát thương nhận được trong vòng này (tối đa 900% Sát Thương Vật Lý của Kame Sennin); sau khi thi triển chiêu thức đặc biệt, tất cả <Vital Death> trên người bạn sẽ bị tiêu diệt\n#F20# \n#F40##C0x5c9970#→ Chịu 50% tổng sát thương nhận được trong vòng này là sát thương thực sự (lên tới 1200% đòn Sát Thương Vật Lý của Kame Sennin); sau khi thực hiện chiêu thức đặc biệt, hãy xóa tất cả <Chết máu> trên bản thân và tăng mức giảm sát thương cuối cùng thêm 10% trong 1 hiệp',
		upLvDesc = 'Fixed damage +240',
