	[23516] = {
		id = 23516,
		skillName_vn = 'Thần Võ Thuật',
		skillName_en = 'Martial God',
		skillName_th = 'เทพศิลปะการต่อสู้',
		skillName_in = 'Dewa Bela Diri',
		skillName_ph = 'Diyos ng Martial Arts',
		skillName_ma = 'Dewa Seni Bela Diri',
		skillName = 'Martial God',
		describe_vn = 'Khả năng chịu sát thương bị trì hoãn: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# Bất kỳ sát thương nào mà Thần Võ Thuật nhận được sẽ chuyển thành dạng [Nỗi buồn máu]. [Nỗi buồn máu] sẽ tính 50% vào cuối vòng hiện tại và cuối vòng tiếp theo. Có [Nỗi buồn máu] giúp tăng sức Sát Thương Vật Lý của bản thân thêm 10%. \n Kame Sennin nhận được hiệu ứng [Hợp tác] (Hợp tác: Khi đồng đội sử dụng đòn đánh cơ bản, Kame Sennin cũng sử dụng đòn đánh cơ bản để tấn công cùng một mục tiêu). Anh hùng chiến đấu không phục hồi cơn giận của mục tiêu khi họ hợp tác/phản công.',
		describe_en = 'Damage resistance delayed: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# Any damage received by the Martial God will be converted into [Blood Sorrow]. [Blood Sorrow] counts for 50% at the end of the current round and the next round. Having [Blood Sorrow] increases own Physical Damage by 10%. \n Kame Sennin gains the effect [Cooperation] (Cooperation: When allies use a basic attack, Kame Sennin also performs a basic attack on the same target). Combat heroes do not restore the target\'s rage when they cooperate/counterattack.',
		describe_th = 'ความสามารถทนทานต่อความเสียหายถูกเลื่อน: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# ความเสียหายใดๆ ที่เทพเจ้าแห่งศิลปะการต่อสู้ได้รับ จะถูกเปลี่ยนเป็น [ความเศร้าของเลือด] [ความเศร้าของเลือด] จะนับ 50% ในตอนท้ายรอบปัจจุบันและรอบถัดไป การมี [ความเศร้าของเลือด] ช่วยเพิ่มพลังโจมตีทางกายภาพของตัวเองขึ้น 10% \n กาเมะเซ็นนินได้รับเอฟเฟกต์ [ความร่วมมือ] (ความร่วมมือ: เมื่อผู้ร่วมทีมใช้การโจมตีพื้นฐาน กาเมะเซ็นนินจะใช้การโจมตีพื้นฐานเดียวกันกับเป้าหมายเดียวกัน) ฮีโร่ในการต่อสู้จะไม่ฟื้นฟูความโกรธของเป้าหมายเมื่อพวกเขาร่วมมือ/ตอบโต้',
		describe_in = 'Penundaan kemampuan menahan kerusakan: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# Setiap kerusakan yang diterima oleh Dewa Seni Bela Diri akan diubah menjadi [Kesedihan Darah]. [Kesedihan Darah] dihitung 50% pada akhir putaran saat ini dan putaran berikutnya. Memiliki [Kesedihan Darah] meningkatkan Damage Fisik sendiri sebesar 10%. \n Kame Sennin mendapatkan efek [Kerjasama] (Kerjasama: Ketika rekan menggunakan serangan dasar, Kame Sennin juga melakukan serangan dasar pada target yang sama). Pahlawan bertarung tidak memulihkan amarah target saat mereka bekerja sama/bersilang serang.',
		describe_ph = 'Naantalang kakayahan sa pagtitiis ng pinsala: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# Anumang pinsalang matatanggap ng Martial God ay gagawing [Kalungkutan sa Dugo]. Ang [Kalungkutan sa Dugo] ay binibilang ng 50% sa katapusan ng kasalukuyang round at ng susunod na round. Ang pagkakaroon ng [Kalungkutan sa Dugo] ay nagpapataas ng sariling Pisikal na Pinsala ng 10%. \n Nakakatanggap si Kame Sennin ng epekto na [Kooperasyon] (Kooperasyon: Kapag ang mga kakampi ay gumamit ng basic attack, gagamit din si Kame Sennin ng basic attack laban sa parehong target). Ang mga bayani sa laban ay hindi nagbabalik ng galit ng target kapag sila ay nakikipag-kooperasyon/o nagbabalik ng atake.',
		describe_ma = 'Keupayaan menahan kerosakan ditangguhkan: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# Sebarang kerosakan yang diterima oleh Dewa Seni Perang akan ditukar menjadi [Duka Darah]. [Duka Darah] dikira 50% pada akhir pusingan semasa dan pusingan seterusnya. Mempunyai [Duka Darah] membantu meningkatkan Kerosakan Fizikal sendiri sebanyak 10%. \n Kame Sennin mendapat kesan [Kerjasama] (Kerjasama: Apabila sekutu menggunakan serangan asas, Kame Sennin juga menggunakan serangan asas untuk menyerang sasaran yang sama). Wira bertempur tidak memulihkan kemarahan sasaran apabila mereka bekerjasama/menentang serangan.',
		describe = 'Damage resistance delayed: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# Any damage received by the Martial God will be converted into [Blood Sorrow]. [Blood Sorrow] counts for 50% at the end of the current round and the next round. Having [Blood Sorrow] increases own Physical Damage by 10%. \n Kame Sennin gains the effect [Cooperation] (Cooperation: When allies use a basic attack, Kame Sennin also performs a basic attack on the same target). Combat heroes do not restore the target\'s rage when they cooperate/counterattack.',
		starEffect = __data_t__starEffect[23516],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng thêm: Tấn công kèm hiệu ứng  <Ám Kình>  1 hiệp (Ám Kình: Hiệu ứng bất lợi, không thể giải trừ, 10% dễ bị tổn thương và giảm 20% tốc độ hồi nộ, không cộng dồn)',
		starEffectDesc = 'เอฟเฟกต์เพิ่มเติม: การโจมตีจะมาพร้อมเอฟเฟกต์ [พลังมืดแฝง] เป็นเวลา 1 เทิร์น ([พลังมืดแฝง]: เอฟเฟกต์ลบ ไม่สามารถถูกลบได้ ทำให้เป้าหมายได้รับความเสียหายเพิ่มขึ้น 10% และลดความเร็วในการฟื้นฟูโกรธลง 20% ไม่สามารถซ้อนทับได้)',
		starEffectDesc_en = 'Additional effect: Attack with <#Ám Kình#> effect for 1 turn (Ám Kình: Disadvantageous effect, cannot be removed, 10% increased vulnerability and 20% reduced rage recovery speed, does not stack)',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: การโจมตีมีผล [พลังมืด] ติดตัวเป็นเวลา 1 เทิร์น (พลังมืด: ดีบัฟ ไม่สามารถลบได้ เพิ่มความเสียหายที่ได้รับ 10% และลดความเร็วในการฟื้นฟูโทสะลง 20%, ไม่สามารถซ้อนทับได้)',
		starEffectDesc_in = 'Efek tambahan: Serangan dengan efek <#Ám Kình#> selama 1 giliran (Ám Kình: Efek merugikan, tidak bisa dihapus, 10% lebih rentan dan mengurangi kecepatan pemulihan amarah sebesar 20%, tidak bisa bertumpuk)',
		starEffectDesc_ph = 'Karagdagang epekto: Atake na may epekto ng <#Ám Kình#> sa loob ng 1 turn (Ám Kình: Hindi kanais-nais na epekto, hindi maaaring alisin, 10% mas madaling madamage at bumababa ng 20% ang bilis ng paggaling ng galit, hindi nagtatambak)',
		starEffectDesc_ma = 'Kesan tambahan: Serangan dengan kesan <#Ám Kình#> selama 1 pusingan (Ám Kình: Kesan tidak menguntungkan, tidak boleh dibuang, 10% lebih mudah terdedah dan mengurangkan kelajuan pemulihan amarah sebanyak 20%, tidak berganda)',
		zawakeEffect = __data_t__zawakeEffect[23516],
		-- {79004}
		zawakeEffectDesc = 'Delayed damage: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# Any damage received by the Divine Martial Arts converts to <Blood Woe>. <Blood Woe> counts 1/3 of that damage at the end of the current turn and the next two turns. Having <Blood Woe> increases own Physical Damage by 10%. \n Kame Sennin gains the <Cooperation> effect (Cooperation: When teammates use basic attacks, Kame Sennin also uses basic attacks to attack the same target. The hero can also trigger cooperative battles by using small skills). The hero does not restore the target\'s rage when cooperating/counterattacking.',
		zawakeEffectDesc_en = 'Delayed damage: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# Any damage received by the Divine Martial Arts converts to <Blood Woe>. <Blood Woe> counts 1/3 of that damage at the end of the current turn and the next two turns. Having <Blood Woe> increases own Physical Damage by 10%. \n Kame Sennin gains the <Cooperation> effect (Cooperation: When teammates use basic attacks, Kame Sennin also uses basic attacks to attack the same target. The hero can also trigger cooperative battles by using small skills). The hero does not restore the target\'s rage when cooperating/counterattacking.',
		zawakeEffectDesc_th = 'รับความเสียหายช้า: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# ความเสียหายใด ๆ ที่ได้รับโดยเทพศิลปะการต่อสู้จะถูกแปลงเป็น <ความโศกเศร้าของเลือด> <ความโศกเศร้าของเลือด> จะคิดเป็น 1/3 ของจำนวนดังกล่าวในตอนท้ายของรอบปัจจุบันและสองรอบถัดไป การมี <ความโศกเศร้าของเลือด> ช่วยเพิ่มความเสียหายทางกายภาพของตัวเองอีก 10% \n คาเมะเซนนินได้รับเอฟเฟกต์ <ความร่วมมือ> (ความร่วมมือ: เมื่อเพื่อนร่วมทีมใช้การโจมตีพื้นฐาน คาเมะเซนนินก็ใช้การโจมตีพื้นฐานโจมตีเป้าหมายเดียวกัน นักรบฮีโร่ยังสามารถเปิดใช้งานการต่อสู้ร่วมโดยการใช้ทักษะเล็ก) นักรบฮีโร่จะไม่ฟื้นฟูความโกรธของเป้าหมายเมื่อร่วมมือ/สวนกลับ',
		zawakeEffectDesc_in = 'Cedera tertunda: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# Setiap kerusakan yang diterima oleh Seni Bela Diri Ilahi akan berubah menjadi <Kesedihan Darah>. <Kesedihan Darah> dihitung 1/3 dari jumlah itu pada akhir giliran saat ini dan dua giliran berikutnya. Memiliki <Kesedihan Darah> membantu meningkatkan Kerusakan Fisik diri sendiri sebesar 10%. \n Kame Sennin mendapatkan efek <Kerjasama> (Kerjasama: Saat rekan setim menggunakan serangan dasar, Kame Sennin juga menggunakan serangan dasar untuk menyerang target yang sama. Pahlawan juga dapat memicu pertempuran kerjasama dengan menggunakan keterampilan kecil). Pahlawan tidak memulihkan kemarahan target saat mereka bekerja sama/menyerang balik.',
		zawakeEffectDesc_ph = 'Naantalang pinsala: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# Anumang pinsalang matanggap ng Banal na Sining ng Pakikipaglaban ay nagiging <Dugong Paghapis>. Ang <Dugong Paghapis> ay binibilang ng 1/3 nito sa katapusan ng kasalukuyang turno at sa susunod na dalawang turno. Ang pagkaroon ng <Dugong Paghapis> ay nagpapataas ng sariling Pisikal na Pinsala ng 10%. \n Nakakatanggap si Kame Sennin ng epekto ng <Kooperasyon> (Kooperasyon: Kapag gumagamit ang mga kasama ng koponan ng mga pangkaraniwang atake, ginagamit din ni Kame Sennin ang mga pangkaraniwang atake upang atakihin ang parehong target. Maaari ring pasimulan ng bayani ang mga labang kooperatiba gamit ang mga maliliit na kasanayan). Hindi nagbabalik ng galit ang bayani ng target kapag sila ay nakikipagtulungan/nagtatanggol.',
		zawakeEffectDesc_ma = 'Cedera tertunda: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# Sebarang kerosakan yang diterima oleh Seni Bela Diri Ilahi akan bertukar menjadi <Duka Darah>. <Duka Darah> akan mengira 1/3 dari jumlah itu pada akhir pusingan semasa dan dua pusingan berikutnya. Mempunyai <Duka Darah> membantu meningkatkan Kerosakan Fizikal sendiri sebanyak 10%. \n Kame Sennin mendapat kesan <Kerjasama> (Kerjasama: Apabila rakan sepasukan menggunakan serangan asas, Kame Sennin juga menggunakan serangan asas untuk menyerang sasaran yang sama. Wira juga boleh mengaktifkan pertempuran kerjasama dengan menggunakan kemahiran kecil). Wira tidak memulihkan kemarahan sasaran apabila mereka bekerjasama/menyerang balas.',
		zawakeEffectDesc_vn = 'Chịu vết thương chậm: #C0x5c9970#$(40+skillLevel*0.2-0.2)$%#C0x5B545B# Bất kỳ sát thương nào mà Thần Võ Thuật nhận được sẽ chuyển thành dạng <Nỗi buồn máu>. <Nỗi buồn máu> sẽ tính 1/3 số đó vào cuối vòng hiện tại và cuối hai vòng tiếp theo. Có <Nỗi buồn máu> giúp tăng sức Sát Thương Vật Lý của bản thân thêm 10%. \n Kame Sennin nhận được hiệu ứng <Hợp tác> (Hợp tác: Khi đồng đội sử dụng các đòn tấn công cơ bản, Kame Sennin cũng sử dụng các đòn tấn công cơ bản để tấn công cùng một mục tiêu. Anh hùng chiến đấu cũng có thể kích hoạt các trận chiến hợp tác bằng cách sử dụng các kỹ năng nhỏ). Anh hùng chiến đấu không phục hồi cơn giận của mục tiêu khi họ hợp tác/phản công.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '<Blood Death> will deal 50% of its effect at the end of the current round and the next round in sequence\n(Cooperation: When an ally uses a basic attack, Kame Sennin also uses a basic attack to hit the same target)\n#F20# \n#F40##C0x5c9970#→<Blood Sorrow> 1/3 will be resolved at the end of the current round and the next two rounds.\n(Cooperation: When an ally uses a basic attack, Immortal Turtle also uses a basic attack on the same target. Battle heroes can also trigger cooperation attacks using minor skills)',
		zawakeSimpleDesc_en = '<Blood Death> will deal 50% of its effect at the end of the current round and the next round in sequence\n(Cooperation: When an ally uses a basic attack, Kame Sennin also uses a basic attack to hit the same target)\n#F20# \n#F40##C0x5c9970#→<Blood Sorrow> 1/3 will be resolved at the end of the current round and the next two rounds.\n(Cooperation: When an ally uses a basic attack, Immortal Turtle also uses a basic attack on the same target. Battle heroes can also trigger cooperation attacks using minor skills)',
		zawakeSimpleDesc_th = '<Blood Death> จะสร้างผล 50% ในตอนท้ายของรอบนี้และรอบถัดไปตามลำดับ\n(การร่วมมือ: เมื่อพันธมิตรใช้การโจมตีพื้นฐาน Kame Sennin จะโจมตีพื้นฐานเป้าหมายเดียวกัน)\n#F20# \n#F40##C0x5c9970#→<Blood Sorrow> 1/3 จะถูกใช้ในตอนท้ายของรอบนี้และอีกสองรอบถัดไป\n(การร่วมมือ: เมื่อพันธมิตรใช้การโจมตีพื้นฐาน เต่ายักษ์อมตะจะร่วมโจมตีเป้าหมายเดียวกัน ฮีโร่ต่อสู้สามารถร่วมโจมตีโดยใช้สกิลเล็ก)',
		zawakeSimpleDesc_in = '<Blood Death> akan memberikan 50% efek di akhir giliran saat ini dan giliran berikutnya secara berurutan\n(Kerja Sama: Saat rekan menggunakan serangan dasar, Kame Sennin juga akan menyerang target yang sama)\n#F20# \n#F40##C0x5c9970#→<Blood Sorrow> 1/3 akan dihitung di akhir giliran saat ini dan dua giliran berikutnya.\n(Kerja Sama: Saat rekan menggunakan serangan dasar, Kura-Kura Abadi juga akan menyerang target yang sama. Hero bertarung juga bisa memicu serangan kerja sama melalui skill kecil)',
		zawakeSimpleDesc_ph = '<Blood Death> ay magdudulot ng 50% epekto sa dulo ng kasalukuyang turn at sa susunod na turn\n(Kooperasyon: Kapag gumamit ng basic attack ang kakampi, si Kame Sennin ay sasabay sa pag-atake sa parehong target)\n#F20# \n#F40##C0x5c9970#→<Blood Sorrow> 1/3 ay maa-activate sa dulo ng turn na ito at dalawang susunod na turn\n(Kooperasyon: Kapag ang kakampi ay gumamit ng basic attack, si Immortal Turtle ay aatake rin sa parehong target. Ang mga hero sa labanan ay maaari ring mag-trigger ng kooperasyon gamit ang maliit na skill)',
		zawakeSimpleDesc_ma = '<Blood Death> akan mengira 50% kesan pada akhir pusingan semasa dan pusingan berikutnya secara berurutan\n(Kerjasama: Apabila sekutu menggunakan serangan asas, Kame Sennin juga menyerang sasaran yang sama)\n#F20# \n#F40##C0x5c9970#→<Blood Sorrow> 1/3 akan diaktifkan pada akhir pusingan semasa dan dua pusingan berikutnya.\n(Kerjasama: Apabila sekutu menggunakan serangan asas, Kura-kura Abadi juga akan menyerang sasaran yang sama. Hero pertempuran juga boleh mencetuskan kerjasama dengan menggunakan kemahiran kecil)',
		zawakeSimpleDesc_vn = '<Blood Death> sẽ tính 50% trong số đó vào cuối vòng hiện tại và cuối vòng tiếp theo theo trình tự\n (Hợp tác: Khi đồng đội sử dụng đòn đánh cơ bản, Kame Sennin cũng sử dụng đòn đánh cơ bản để tấn công cùng một mục tiêu)\n#F20# \n#F40##C0x5c9970#→<Blood Sorrow> 1/3 sẽ được giải quyết ở cuối vòng hiện tại và hai vòng tiếp theo.\n (Hợp tác: Khi nào đồng đội sử dụng các đòn tấn công cơ bản, Rùa Bất Tử cũng sẽ sử dụng các đòn tấn công cơ bản để tấn công cùng một mục tiêu. Các anh hùng chiến đấu cũng có thể kích hoạt các trận chiến hợp tác bằng cách sử dụng các kỹ năng nhỏ)',
		iconRes = 'battle/skill_icon/skill_23516.png',
		changeUnitTrigger = true,
		isCombat = true,
