	[23611] = {
		id = 23611,
		skillName_vn = 'Chém trên mặt nước',
		skillName_en = 'Slash on the water surface',
		skillName_th = 'ฟันบนผิวน้ำ',
		skillName_in = 'Tebas di permukaan air',
		skillName_ph = 'Gupit sa ibabaw ng tubig',
		skillName_ma = 'Tebas di permukaan air',
		skillName = 'Slash on the water surface',
		describe_vn = 'Bankai · Kenpachi rơi vào trạng thái cuồng bạo, vung đại đao tấn công mục tiêu đơn ở hàng sau địch (trong chế độ tự động sẽ chọn mục tiêu có thủ vật lý hàng sau thấp nhất), gây #C0x3D8A99#180% công vật lý#C0x5B545B#+$(skillLevel*4*24)$ sát thương vật lý#C0xF13B54# #C0x5B545B#, chuyển một hiệu ứng bất lợi ngẫu nhiên của bản thân sang mục tiêu và cướp một hiệu ứng có lợi ngẫu nhiên từ mục tiêu về cho bản thân',
		describe_en = 'Bankai · Kenpachi enters a berserk state, swings his giant blade to attack a single enemy in the back row (in auto battle, targets the back-row enemy with the lowest physical defense), dealing #C0x3D8A99#180% physical attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#physical damage#C0x5B545B#, transfers one random debuff from self to the target and steals one random buff from the target',
		describe_th = 'สลายขีดจำกัด · เคมปาจิเข้าสู่สภาวะคลุ้มคลั่ง ฟาดดาบยักษ์โจมตีศัตรูเดี่ยวในแถวหลัง (ในโหมดอัตโนมัติจะเลือกเป้าหมายแถวหลังที่มีพลังป้องกันกายภาพต่ำที่สุด) สร้างความเสียหายกายภาพ #C0x3D8A99#180% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ เป็น #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# จากนั้นสุ่มถ่ายโอนเอฟเฟกต์ลบ 1 อย่างของตนเองไปยังเป้าหมาย และขโมยเอฟเฟกต์บัฟแบบสุ่ม 1 อย่างจากเป้าหมายมาให้ตนเอง',
		describe_in = 'Bankai · Kenpachi memasuki mode mengamuk, mengayunkan pedang raksasa untuk menyerang satu target di baris belakang musuh (dalam mode otomatis akan memilih target dengan pertahanan fisik terendah di baris belakang), memberikan #C0x3D8A99#180% serangan fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#kerusakan fisik#C0x5B545B#, memindahkan satu debuff acak dari diri sendiri ke target dan mencuri satu buff acak dari target',
		describe_ph = 'Bankai · Pumasok si Kenpachi sa galit na estado, iwasiwas ang higanteng espada upang umatake sa isang kalaban sa likurang hanay (sa auto battle ay pipiliin ang kalaban sa likod na may pinakamababang physical defense), magdudulot ng #C0x3D8A99#180% physical attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#physical damage#C0x5B545B#, ililipat ang isang random na debuff mula sa sarili sa kalaban at kukuha ng isang random buff mula sa kalaban',
		describe_ma = 'Bankai · Kenpachi memasuki keadaan mengamuk, menghayun pedang gergasi untuk menyerang satu sasaran di barisan belakang musuh (dalam mod automatik akan memilih sasaran dengan pertahanan fizikal paling rendah di barisan belakang), memberikan #C0x3D8A99#180% serangan fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#kerosakan fizikal#C0x5B545B#, memindahkan satu debuff rawak dari diri sendiri ke sasaran dan mencuri satu buff rawak dari sasaran',
		describe = 'Bankai · Kenpachi enters a berserk state, swings his giant blade to attack a single enemy in the back row (in auto battle, targets the back-row enemy with the lowest physical defense), dealing #C0x3D8A99#180% physical attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#physical damage#C0x5B545B#, transfers one random debuff from self to the target and steals one random buff from the target',
		simDesc_vn = 'Bankai ẩn nấp trước kẻ địch, tấn công hàng sau của kẻ địch bằng đòn chém nước và chặt (chọn mục tiêu có khả năng phòng thủ hợp pháp thấp nhất ở hàng sau trong khi chiến đấu tự động), gây sát thương phép và chuyển hiệu ứng tiêu cực ngẫu nhiên của bản thân sang mục tiêu và chuyển hiệu ứng buff ngẫu nhiên của mục tiêu cho chính nó.',
		simDesc_en = 'Bankai hides from enemies, attacking the back row with water slash and chop (targets the enemy in the back row with the lowest valid defense while auto-fighting), dealing magic damage and randomly transferring its own negative effects to the target and randomly stealing the target\'s buffs for itself.',
		simDesc_th = 'Bankai ซ่อนตัวจากศัตรู โจมตีแถวหลังของศัตรูด้วยการฟันน้ำและฟัน (เลือกเป้าหมายที่มีการป้องกันถูกต้องต่ำที่สุดในแถวหลังขณะต่อสู้แบบอัตโนมัติ) ก่อให้เกิดความเสียหายเวทและสุ่มถ่ายโอนผลกระทบลบของตัวเองไปยังเป้าหมาย และสุ่มขโมยบัฟของเป้าหมายมาใช้กับตัวเอง',
		simDesc_in = 'Bankai bersembunyi dari musuh, menyerang barisan belakang musuh dengan serangan slash air dan chop (memilih target dengan pertahanan sah terendah di barisan belakang selama bertarung otomatis), memberikan damage sihir dan secara acak memindahkan efek negatif dirinya ke target serta memindahkan buff acak dari target ke dirinya sendiri.',
		simDesc_ph = 'Ang Bankai ay nagtatago mula sa mga kalaban, umatake sa likurang hanay ng kalaban gamit ang water slash at chop (pinipili ang target na may pinakamababang legal na depensa sa likurang hanay habang awtomatikong nakikipaglaban), nagdudulot ng magic damage at random na inilipat ang sariling negatibong epekto sa target at inilipat naman nang random ang buff ng target para sa sarili.',
		simDesc_ma = 'Bankai bersembunyi daripada musuh, menyerang barisan belakang musuh dengan serangan belahan air dan tebasan (memilih sasaran dengan pertahanan sah paling rendah di barisan belakang semasa bertarung automatik), menyebabkan kerosakan sihir dan secara rawak memindahkan kesan negatif dirinya ke sasaran serta memindahkan buff rawak sasaran kepada dirinya sendiri.',
		simDesc = 'Bankai hides from enemies, attacking the back row with water slash and chop (targets the enemy in the back row with the lowest valid defense while auto-fighting), dealing magic damage and randomly transferring its own negative effects to the target and randomly stealing the target\'s buffs for itself.',
		zawakeEffect = __data_t__zawakeEffect[23611],
		-- {79001}
		zawakeEffectDesc = 'Bankai · Kenpachi stealthily dashes in front of the enemy and performs a Water Surface Slash on a single back-row target (in auto battle, targets the back-row enemy with the lowest physical defense), dealing #C0x3D8A99#100% physical attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#physical damage#C0x5B545B#, transfers one random debuff from self to the target and steals one random buff from the target, and increases own physical attack by 30% for 2 turns',
		zawakeEffectDesc_en = 'Bankai · Kenpachi stealthily dashes in front of the enemy and performs a Water Surface Slash on a single back-row target (in auto battle, targets the back-row enemy with the lowest physical defense), dealing #C0x3D8A99#100% physical attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#physical damage#C0x5B545B#, transfers one random debuff from self to the target and steals one random buff from the target, and increases own physical attack by 30% for 2 turns',
		zawakeEffectDesc_th = 'Bankai·เค็นปาจิพุ่งตัวไปยังด้านหน้าของศัตรู โจมตีเป้าหมายเดี่ยวแถวหลังด้วยท่าฟันผิวน้ำ (ในโหมดอัตโนมัติจะเลือกเป้าหมายแถวหลังที่มีพลังป้องกันกายภาพต่ำที่สุด) สร้างความเสียหายทางกายภาพ #C0x3D8A99#100% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# โอนผลลบแบบสุ่ม 1 อย่างของตัวเองให้เป้าหมาย และขโมยผลดีแบบสุ่ม 1 อย่างจากเป้าหมายมาให้ตัวเอง พร้อมเพิ่มพลังโจมตีกายภาพ 30% ให้ตนเองเป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Bankai · Kenpachi menyelinap ke depan musuh dan menebas target tunggal di barisan belakang dengan serangan Tebasan Permukaan Air (dalam mode otomatis akan memilih target barisan belakang dengan pertahanan fisik terendah), memberikan #C0x3D8A99#100% serangan fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#kerusakan fisik#C0x5B545B#, memindahkan satu debuff acak dari dirinya ke target dan mencuri satu buff acak dari target, serta meningkatkan serangan fisik sendiri sebesar 30% selama 2 ronde',
		zawakeEffectDesc_ph = 'Bankai · Si Kenpachi ay biglang lumitaw sa harap ng kalaban at umatake sa isang target sa likurang hanay gamit ang Water Surface Slash (sa auto battle ay pipiliin ang target na may pinakamababang physical defense sa likod), nagdudulot ng #C0x3D8A99#100% physical attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#physical damage#C0x5B545B#, inililipat ang isang random na debuff mula sa sarili sa target at nagnanakaw ng isang random buff mula sa target, at pinapataas ang sariling physical attack ng 30% sa loob ng 2 turn',
		zawakeEffectDesc_ma = 'Bankai · Kenpachi menyelinap ke hadapan musuh dan menyerang satu sasaran barisan belakang dengan serangan Tebasan Permukaan Air (dalam mod automatik akan memilih sasaran dengan pertahanan fizikal paling rendah di barisan belakang), memberikan #C0x3D8A99#100% serangan fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#kerosakan fizikal#C0x5B545B#, memindahkan satu debuff rawak daripada diri sendiri ke sasaran dan mencuri satu buff rawak daripada sasaran, serta meningkatkan serangan fizikal sendiri sebanyak 30% selama 2 pusingan',
		zawakeEffectDesc_vn = 'Bankai · Kenpachi lướt ẩn đến trước mặt kẻ địch, tung chiêu chém Mặt Nước tấn công mục tiêu đơn hàng sau của địch (trong chế độ tự động sẽ chọn mục tiêu hàng sau có thủ vật lý thấp nhất), gây #C0x3D8A99#100% công vật lý#C0x5B545B#+$(skillLevel*4*24)$ sát thương vật lý#C0xF13B54##C0x5B545B#, chuyển một hiệu ứng bất lợi ngẫu nhiên từ bản thân sang mục tiêu và cướp một hiệu ứng có lợi ngẫu nhiên từ mục tiêu, đồng thời tăng 30% công vật lý bản thân, duy trì 2 lượt',
