	[23613] = {
		id = 23613,
		skillName_vn = 'Nhát chém xé rách không trung',
		skillName_en = 'A slash that tears through the air',
		skillName_th = 'ฟันที่ฉีกกลางอากาศ',
		skillName_in = 'Tebasan yang mengoyak udara',
		skillName_ph = 'Isang hiwa na pumuputol sa hangin',
		skillName_ma = 'Sepakan yang merobek udara',
		skillName = 'A slash that tears through the air',
		describe_vn = 'Bankai · Kenpachi kiếm khí tung hoành, xé rách không gian đưa mục tiêu đơn hàng sau của địch vào không gian dị giới và triệu hồi Vô Gián Luyện Ngục (trong chế độ tự động sẽ chọn mục tiêu hàng sau có thủ vật lý thấp nhất), gây #C0x3D8A99#750% công vật lý#C0x5B545B#+$(skillLevel*4*90)$ sát thương vật lý#C0xF13B54##C0x5B545B#, giải phóng hiệu ứng cường hóa không gian kéo dài 2 lượt: tăng 20% tỷ lệ bạo kích và 20% sát thương cộng thêm cho bản thân và đồng đội hàng sau. \n Nếu mục tiêu bị hạ gục, 35% sát thương dư từ tuyệt kỹ này sẽ được chuyển sang một mục tiêu ngẫu nhiên còn lại của địch (sát thương chuyển là sát thương chuẩn)',
		describe_en = 'Bankai · Kenpachi’s sword energy tears through space, dragging a single back-row enemy into another dimension and summoning the Infernal Prison (in auto battle, targets the back-row enemy with the lowest physical defense), dealing #C0x3D8A99#750% physical attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#physical damage#C0x5B545B#, and unleashes a Space Enhancement effect for 2 turns: increases Crit Rate and DMG Bonus by 20% for self and allies in the back row. \n If the target is killed, 35% of the overflow damage from this ultimate will be transferred to a random remaining enemy (transferred damage is true damage)',
		describe_th = 'สลายขีดจำกัด · เคมปาจิปลดปล่อยคลื่นดาบอันบ้าคลั่ง ฉีกเปิดมิติและดึงศัตรูแถวหลังแบบเดี่ยวเข้าสู่มิตินอกเวลา พร้อมอัญเชิญขุมนรกไร้จุดจบ (ในโหมดอัตโนมัติจะเลือกเป้าหมายแถวหลังที่มีพลังป้องกันกายภาพต่ำที่สุด) สร้างความเสียหายกายภาพ #C0x3D8A99#750% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*90)$ เป็น #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# และปล่อยเอฟเฟกต์เสริมพลังมิติ มีผล 2 เทิร์น: เพิ่มอัตราคริติคอลและโบนัสความเสียหายของตนเองและฮีโร่ฝ่ายเราในแถวหลัง 20%  หากสังหารเป้าหมายได้ จะโอนความเสียหายส่วนเกิน 35% ของท่าไม้ตายนี้ไปยังศัตรูที่เหลือแบบสุ่ม 1 ตัว (ความเสียหายที่โอนเป็นความเสียหายจริง)',
		describe_in = 'Bankai · Kenpachi melepaskan energi pedang yang menembus ruang, menyeret target tunggal di baris belakang musuh ke dimensi lain dan memanggil Neraka Tanpa Akhir (dalam mode otomatis akan memilih target baris belakang dengan pertahanan fisik terendah), memberikan #C0x3D8A99#750% serangan fisik#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#kerusakan fisik#C0x5B545B#, lalu mengaktifkan efek Penguatan Dimensi selama 2 ronde: meningkatkan 20% Crit Rate dan 20% Bonus Damage untuk diri sendiri dan rekan baris belakang. \n Jika target terbunuh, 35% dari kelebihan damage dari Ultimate ini akan ditransfer ke satu musuh acak yang tersisa (damage yang ditransfer adalah true damage)',
		describe_ph = 'Bankai · Si Kenpachi ay nagpalabas ng matinding enerhiya ng espada, pinunit ang espasyo at hinila ang isang kalaban sa likod patungo sa ibang dimensyon, kasabay ng pagsummon ng Walang-hanggang Impiyerno (sa auto battle ay pipiliin ang kalaban sa likod na may pinakamababang physical defense), nagdudulot ng #C0x3D8A99#750% physical attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#physical damage#C0x5B545B#, at naglalabas ng Space Enhancement effect sa loob ng 2 turn: pinapataas ng 20% ang Crit Rate at Damage Bonus ng sarili at mga kakamping nasa likod. \n Kapag napatay ang target, 35% ng labis na damage mula sa ultimate na ito ay ililipat sa isang random na natitirang kalaban (ang damage ay true damage)',
		describe_ma = 'Bankai · Kenpachi melepaskan tenaga pedang yang kuat, mengoyakkan ruang dan menarik satu sasaran barisan belakang musuh ke dimensi lain serta memanggil Neraka Tanpa Henti (dalam mod automatik akan memilih sasaran barisan belakang dengan pertahanan fizikal paling rendah), memberikan #C0x3D8A99#750% serangan fizikal#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#kerosakan fizikal#C0x5B545B#, dan mengaktifkan kesan Pengukuhan Dimensi selama 2 pusingan: meningkatkan 20% Kadar Kritikal dan Bonus Kerosakan kepada diri sendiri dan rakan sepasukan di barisan belakang. \n Jika sasaran dibunuh, 35% daripada lebihan kerosakan dari ultimate ini akan dipindahkan kepada satu musuh rawak yang tinggal (kerosakan dipindahkan ialah kerosakan sebenar)',
		describe = 'Bankai · Kenpachi’s sword energy tears through space, dragging a single back-row enemy into another dimension and summoning the Infernal Prison (in auto battle, targets the back-row enemy with the lowest physical defense), dealing #C0x3D8A99#750% physical attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#physical damage#C0x5B545B#, and unleashes a Space Enhancement effect for 2 turns: increases Crit Rate and DMG Bonus by 20% for self and allies in the back row. \n If the target is killed, 35% of the overflow damage from this ultimate will be transferred to a random remaining enemy (transferred damage is true damage)',
		simDesc_vn = 'Bankai xuất hiện từ mặt phẳng không gian, sau đó đưa mục tiêu duy nhất của kẻ địch ở hàng sau vào một không gian chiều khác, tấn công bằng cách chia tách không gian phụ (chọn mục tiêu có khả năng phòng thủ pháp lý thấp nhất ở hàng sau trong chiến đấu tự động), gây sát thương phép và giải phóng không gian để tăng cường hiệu ứng. Sau khi tiêu diệt mục tiêu, sát thương tràn của chiêu thức đặc biệt này sẽ được chuyển sang mục tiêu ngẫu nhiên còn lại của kẻ địch.',
		simDesc_en = 'Bankai appears from the spatial plane, then transports the enemy\'s sole rear-row target into another dimensional space, attacking by splitting a subspace (automatically selecting the rear-row target with the lowest magic defense). It deals magic damage and releases the space to enhance the effect. After defeating the target, the overflow damage from this special move is transferred to a random remaining enemy target.',
		simDesc_th = 'ปัลเกียปรากฏตัวจากมิติอวกาศ จากนั้นพาตัวเป้าหมายเดียวของศัตรูที่อยู่แถวหลังเข้าสู่มิติอื่น โจมตีโดยการแยกพื้นที่ย่อย (เลือกเป้าหมายแถวหลังที่มีการป้องกันเวทมนตร์ต่ำที่สุดในการต่อสู้แบบอัตโนมัติ) สร้างความเสียหายเวทมนตร์และปลดปล่อยพื้นที่เพื่อเพิ่มประสิทธิภาพ หลังจากกำจัดเป้าหมาย ความเสียหายล้นจากสกิลพิเศษนี้จะถูกโอนไปยังเป้าหมายศัตรูที่เหลือแบบสุ่ม',
		simDesc_in = 'Bankai muncul dari bidang ruang, lalu membawa target tunggal musuh di barisan belakang ke dimensi lain, menyerang dengan memisahkan ruang cabang (memilih target dengan pertahanan sihir terendah di barisan belakang secara otomatis), menyebabkan kerusakan sihir dan melepaskan ruang untuk meningkatkan efek. Setelah mengalahkan target, kerusakan limpahan dari serangan khusus ini akan dialihkan ke target musuh acak yang tersisa.',
		simDesc_ph = 'Lumilitaw si Bankai mula sa spatial plane, pagkatapos ay dinadala ang natatanging target ng kalaban sa likurang hanay sa ibang dimensyon, umatake sa pamamagitan ng paghahati ng subspace (awtomatikong pinipili ang target sa likurang hanay na may pinakamababang magic defense), nagdudulot ng magic damage at pinapalaya ang espasyo upang mapalakas ang epekto. Pagkatapos mapatay ang target, ang sobrang pinsala mula sa espesyal na atake na ito ay ililipat sa isang random na natitirang target ng kalaban.',
		simDesc_ma = 'Bankai muncul dari bidang ruang, kemudian membawa sasaran tunggal musuh di barisan belakang ke ruang dimensi lain, menyerang dengan memecahkan ruang sub (memilih sasaran dengan pertahanan sihir terendah di barisan belakang secara automatik), menyebabkan kerosakan sihir dan melepaskan ruang untuk meningkatkan kesan. Selepas menewaskan sasaran, kerosakan lebih daripada serangan istimewa ini akan dipindahkan ke sasaran musuh lain yang tinggal secara rawak.',
		simDesc = 'Bankai appears from the spatial plane, then transports the enemy\'s sole rear-row target into another dimensional space, attacking by splitting a subspace (automatically selecting the rear-row target with the lowest magic defense). It deals magic damage and releases the space to enhance the effect. After defeating the target, the overflow damage from this special move is transferred to a random remaining enemy target.',
		starEffect = __data_t__starEffect[23613],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Tăng thêm 80% hiệu quả cường hóa không gian cho bản thân, hệ số chuyển sát thương lan từ kỹ năng tất sát tăng lên 60%.',
		starEffectDesc = 'Additional effect: Increase the spatial enhancement effectiveness for oneself by 80%, the damage transfer coefficient from the deadly skill increases to 60%.',
		starEffectDesc_en = 'Additional effect: Increase the spatial enhancement effectiveness for oneself by 80%, the damage transfer coefficient from the deadly skill increases to 60%.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เพิ่มประสิทธิภาพการเสริมพลังพื้นที่ให้ตัวเองขึ้น 80% อัตราการส่งต่อความเสียหายจากทักษะฆ่าสังหารเพิ่มขึ้นเป็น 60%',
		starEffectDesc_in = 'Efek tambahan: Meningkatkan efektivitas penguatan ruang sebesar 80% untuk diri sendiri, koefisien transfer kerusakan dari keterampilan pembunuhan meningkat menjadi 60%.',
		starEffectDesc_ph = 'Karagdagang epekto: Dagdagan ang bisa ng pagpapalakas ng espasyo para sa sarili ng 80%, tumataas ang koepisyent ng paglilipat ng pinsala mula sa kasanayang nakamamatay ng hanggang 60%.',
		starEffectDesc_ma = 'Kesan tambahan: Meningkatkan keberkesanan pengukuhan ruang untuk diri sendiri sebanyak 80%, pekali pemindahan kerosakan dari kemahiran membunuh meningkat kepada 60%.',
		zawakeEffect = __data_t__zawakeEffect[23613],
		-- {79003}
		zawakeEffectDesc = 'Bankai · Kenpachi slashes through space, dragging a single back-row enemy into an alternate dimension and purifying 2 of their defensive buff effects, then summons the Infernal Prison (in auto battle, targets an unguarded special single target), dealing #C0x3D8A99#750% physical attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#physical damage#C0x5B545B#, unleashing a spatial enhancement effect for 2 turns: increases Crit Rate and DMG Bonus by 20% for self and allies in the back row \n If the target is killed, 35% of the overflow damage from this ultimate is transferred to a random remaining enemy (transferred damage is true damage)',
		zawakeEffectDesc_en = 'Bankai · Kenpachi slashes through space, dragging a single back-row enemy into an alternate dimension and purifying 2 of their defensive buff effects, then summons the Infernal Prison (in auto battle, targets an unguarded special single target), dealing #C0x3D8A99#750% physical attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#physical damage#C0x5B545B#, unleashing a spatial enhancement effect for 2 turns: increases Crit Rate and DMG Bonus by 20% for self and allies in the back row \n If the target is killed, 35% of the overflow damage from this ultimate is transferred to a random remaining enemy (transferred damage is true damage)',
		zawakeEffectDesc_th = 'Bankai·เค็นปาจิปล่อยพลังดาบทะลุมิติ ลากศัตรูเดี่ยวแถวหลังเข้าสู่มิติคู่ขนาน และชำระล้างบัฟป้องกัน 2 ประเภทของเป้าหมาย จากนั้นอัญเชิญนรกไร้สิ้นสุด (ในโหมดอัตโนมัติจะเลือกเป้าหมายพิเศษที่ไม่มีการป้องกัน) สร้างความเสียหายทางกายภาพ #C0x3D8A99#750% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ปล่อยเอฟเฟกต์เสริมพลังมิติ 2 เทิร์น: เพิ่มคริติคอลและโบนัสความเสียหาย 20% ให้ตัวเองและฮีโร่แถวหลัง \n หากเป้าหมายถูกสังหาร ความเสียหายล้น 35% จากท่าไม้ตายนี้จะถ่ายโอนไปยังศัตรูที่เหลือแบบสุ่ม 1 ตัว (เป็นความเสียหายจริง)',
		zawakeEffectDesc_in = 'Bankai · Kenpachi mengoyak ruang dengan tebasan pedangnya, menyeret satu musuh barisan belakang ke dimensi alternatif dan menghapus 2 efek buff pertahanan mereka, lalu memanggil Neraka Tanpa Akhir (dalam mode otomatis akan memilih target spesial tanpa pertahanan), memberikan #C0x3D8A99#750% serangan fisik#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#kerusakan fisik#C0x5B545B#, melepaskan efek peningkatan ruang selama 2 ronde: meningkatkan 20% Crit Rate dan Bonus Damage untuk diri sendiri dan rekan di barisan belakang \n Jika target terbunuh, 35% dari kelebihan damage ultimate ini akan dialihkan ke satu musuh acak yang tersisa (damage tersebut adalah true damage)',
		zawakeEffectDesc_ph = 'Bankai · Si Kenpachi ay humiwa sa espasyo gamit ang kanyang espada, hinila ang isang kalaban sa likod sa ibang dimensyon at nilinis ang 2 buff na may kaugnayan sa depensa ng target, kasabay na tumawag ng Walang-hanggang Impiyerno (sa auto battle pipiliin ang isang espesyal na target na walang depensa), nagdudulot ng #C0x3D8A99#750% physical attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#physical damage#C0x5B545B#, naglalabas ng space enhancement effect sa loob ng 2 turn: pinapataas ang Crit Rate at DMG Bonus ng sarili at kaalyado sa likod ng 20% \n Kapag napatay ang target, 35% ng overflow damage ng ultimate ay ililipat sa isang random na natitirang kalaban (ang damage ay true damage)',
		zawakeEffectDesc_ma = 'Bankai · Kenpachi mengoyakkan ruang dengan serangan pedang, menarik satu sasaran barisan belakang ke dimensi alternatif dan membersihkan 2 kesan buff pertahanan sasaran, kemudian memanggil Neraka Abadi (dalam mod automatik akan memilih sasaran khas yang tidak mempunyai pertahanan), memberikan #C0x3D8A99#750% serangan fizikal#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#kerosakan fizikal#C0x5B545B#, melepaskan kesan penambahbaikan ruang selama 2 pusingan: meningkatkan 20% Kadar Kritikal dan Bonus Kerosakan untuk diri dan rakan sepasukan di barisan belakang \n Jika sasaran dibunuh, 35% kerosakan berlebihan dari ultimate ini akan dipindahkan kepada satu musuh rawak yang tinggal (kerosakan ini adalah kerosakan sebenar)',
		zawakeEffectDesc_vn = 'Bankai · Kenpachi tung kiếm khí xuyên phá không gian, kéo mục tiêu đơn hàng sau của địch vào không gian dị giới và thanh tẩy 2 hiệu ứng tăng thủ của mục tiêu, đồng thời triệu hồi Vô Gián Luyện Ngục (trong chế độ tự động sẽ chọn mục tiêu đặc biệt không có phòng ngự), gây #C0x3D8A99#750% công vật lý#C0x5B545B#+$(skillLevel*4*90)$ sát thương vật lý#C0xF13B54##C0x5B545B#, giải phóng hiệu ứng tăng cường không gian kéo dài 2 lượt: tăng 20% tỷ lệ bạo kích và 20% sát thương cho bản thân và đồng minh hàng sau \n Nếu tiêu diệt mục tiêu, 35% sát thương dư của chiêu tất sát này sẽ chuyển sang một kẻ địch còn lại ngẫu nhiên (sát thương chuyển là sát thương chuẩn)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Purify 2 defense enhancement effects from the target\nExcess damage may be redirected to another enemy target, with an additional 15% damage transfer ratio',
		zawakeSimpleDesc_en = '#C0x5c9970#Purify 2 defense enhancement effects from the target\nExcess damage may be redirected to another enemy target, with an additional 15% damage transfer ratio',
		zawakeSimpleDesc_th = '#C0x5c9970#ล้างบัฟป้องกัน 2 อย่างจากเป้าหมาย\nดาเมจส่วนเกินสามารถส่งต่อไปยังเป้าหมายศัตรูอื่น อัตราส่งต่อดาเมจเพิ่มอีก 15%',
		zawakeSimpleDesc_in = '#C0x5c9970#Bersihkan 2 efek peningkatan pertahanan target\nDamage berlebih dapat diarahkan ke musuh lain, dengan tambahan rasio transfer damage 15%',
		zawakeSimpleDesc_ph = '#C0x5c9970#Tanggalin ang 2 buff ng pertahanan ng target\nAng labis na damage ay maaaring lumipat sa ibang kalaban, dagdag 15% transfer rate',
		zawakeSimpleDesc_ma = '#C0x5c9970#Bersihkan 2 kesan peningkatan pertahanan dari sasaran\nKerosakan berlebihan boleh disasarkan ke musuh lain, dengan kadar pemindahan tambahan sebanyak 15%',
		zawakeSimpleDesc_vn = '#C0x5c9970#Thanh tẩy 2 hiệu ứng tăng cường phòng thủ của mục tiêu\nSát thương dư thừa có thể nhắm vào mục tiêu kẻ địch khác, tỷ lệ chuyển sát thương của mục tiêu được chọn thêm là 15%',
		upLvDesc = 'Fixed damage +360',
