	[23616] = {
		id = 23616,
		skillName_vn = 'Space Concealment',
		skillName_en = 'Space Concealment',
		skillName_th = 'การซ่อนตัวในอวกาศ',
		skillName_in = 'Penyembunyian Ruang',
		skillName_ph = 'Pagkukunwaring Espasyo',
		skillName_ma = 'Penyembunyian Angkasa',
		skillName = 'Space Concealment',
		describe_vn = 'Kenpachi tinh thông kiếm kỹ không gian, lĩnh ngộ kỹ năng Ẩn Không: Khi chịu sát thương kỹ năng vượt quá 30% máu tối đa hoặc máu bản thân dưới 60%, sẽ bước vào trạng thái【Ẩn Không】: bản thân tiến vào không gian ẩn (trong không gian không thể nhận sát thương hoặc hiệu ứng kỹ năng), trước lượt hành động tiếp theo sẽ quay lại trận, xóa toàn bộ trạng thái bất lợi, hồi 1000 nộ và tăng 20% tỷ lệ bạo kích, miễn nhiễm hiệu ứng xấu 1 lượt (toàn trận chỉ kích hoạt 1 lần) \n Trước mỗi lần tấn công, hấp thụ một phần thủ vật lý của mục tiêu và vĩnh viễn chuyển hóa thành công vật lý của bản thân (tỷ lệ hấp thụ bằng #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# thủ vật lý của Vạn Giải · Kenpachi, lượng công vật lý chuyển hóa vĩnh viễn tối đa bằng 50% công vật lý của Bankai · Kenpachi)',
		describe_en = 'Kenpachi masters spatial swordsmanship and acquires Spatial Concealment: When receiving skill damage exceeding 30% of max HP or HP drops below 60%, enters 【Concealment】state: becomes hidden in a spatial dimension (cannot receive damage or skill effects), returns before next action to cleanse all debuffs, recover 1000 Rage, gain 20% Crit Rate, and gain 1-turn immunity to negative effects (can only trigger once per battle) \n Before each attack, absorbs a portion of the target\'s physical defense and permanently converts it into own physical attack (absorption rate is #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# of Bankai Kenpachi’s physical defense, with conversion capped at 50% of Bankai Kenpachi’s physical attack)',
		describe_th = 'เคนพาจิผู้เชี่ยวชาญวิชาดาบแห่งมิติ เชี่ยวชาญการซ่อนตัวในมิติ: เมื่อตนเองได้รับความเสียหายจากสกิลเกิน 30% ของพลังชีวิตสูงสุด หรือเมื่อพลังชีวิตลดลงต่ำกว่า 60% จะเข้าสู่สถานะ [ซ่อนตัว]: เข้าสู่มิติซ่อนตัว (ในมิตินี้จะไม่ได้รับความเสียหายหรือบัฟจากสกิลใด ๆ) ก่อนการลงมือในเทิร์นถัดไป จะกลับเข้าสู่สนาม ล้างสถานะผิดปกติทั้งหมด ฟื้นฟูโทสะ 1000 หน่วย เพิ่มอัตราคริติคอล 20% และได้รับภูมิคุ้มกันดีบัฟ 1 เทิร์น (สามารถเกิดได้ 1 ครั้งต่อการต่อสู้)  ทุกครั้งก่อนโจมตี จะดูดซับค่าพลังป้องกันกายภาพบางส่วนจากเป้าหมาย แล้วเปลี่ยนเป็นพลังโจมตีกายภาพถาวร (สัดส่วนที่ดูดซับคือ #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# ของพลังป้องกันกายภาพของ เคนพาจิ – ขั้นปลดปล่อย, โดยค่าพลังโจมตีที่แปลงได้สูงสุดไม่เกิน 50% ของพลังโจมตีกายภาพของตัวเอง)',
		describe_in = 'Kenpachi menguasai teknik pedang ruang dan menguasai Ketersembunyian Dimensi: Saat menerima damage skill melebihi 30% HP maksimal atau HP turun di bawah 60%, akan masuk ke status【Tersembunyi】: masuk ke dimensi tersembunyi (tidak bisa menerima damage atau efek skill), sebelum giliran berikutnya akan kembali ke medan tempur, menghapus semua efek negatif, memulihkan 1000 Rage, menambah 20% Crit Rate, dan kebal terhadap efek negatif selama 1 ronde (hanya dapat dipicu sekali per pertempuran) \n Sebelum setiap serangan, menyerap sebagian dari pertahanan fisik target dan secara permanen mengubahnya menjadi serangan fisik dirinya (rasio penyerapan sebesar #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# dari DEF fisik Bankai Kenpachi, jumlah maksimal konversi adalah 50% dari ATK fisik Bankai Kenpachi)',
		describe_ph = 'Kenpachi ay bihasa sa espada ng espasyo at nagkamit ng Spatial Concealment: Kapag nakatanggap ng skill damage na higit sa 30% ng max HP o bumaba sa ilalim ng 60% HP, papasok sa estado ng【Concealment】: papasok sa espasyong nakatago (hindi maaaring makatanggap ng damage o mga skill effect), babalik bago ang susunod na aksyon, aalisin ang lahat ng debuff, magre-recover ng 1000 Rage, tataas ang Crit Rate ng 20%, at magkakaroon ng 1 turn na immunity sa negative effects (maaaring ma-activate 1 beses sa buong laban) \n Bago ang bawat atake, sumisipsip ng porsyento ng physical defense ng kalaban at permanenteng kinokonvert sa sariling physical attack (rate ng pagsipsip ay #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# ng physical DEF ng Bankai Kenpachi, konversi maksimum ay 50% ng physical ATK ng Bankai Kenpachi)',
		describe_ma = 'Kenpachi menguasai teknik pedang ruang dan memiliki Kemahiran Sembunyi Dimensi: Apabila menerima kerosakan kemahiran melebihi 30% HP maksimum atau HP kurang daripada 60%, akan memasuki status【Tersembunyi】: masuk ke ruang tersembunyi (tidak dapat menerima kerosakan atau kesan kemahiran), sebelum giliran seterusnya akan kembali, menghapus semua kesan negatif, memulihkan 1000 Kemarahan, meningkatkan 20% Kadar Kritikal, dan imun terhadap kesan negatif selama 1 pusingan (boleh diaktifkan sekali sahaja dalam pertempuran) \n Sebelum setiap serangan, menyerap sebahagian DEF fizikal sasaran dan menukarnya secara kekal kepada ATK fizikal sendiri (kadar serapan ialah #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# DEF fizikal Bankai Kenpachi, had maksimum pertukaran ialah 50% daripada ATK fizikal Bankai Kenpachi)',
		describe = 'Kenpachi masters spatial swordsmanship and acquires Spatial Concealment: When receiving skill damage exceeding 30% of max HP or HP drops below 60%, enters 【Concealment】state: becomes hidden in a spatial dimension (cannot receive damage or skill effects), returns before next action to cleanse all debuffs, recover 1000 Rage, gain 20% Crit Rate, and gain 1-turn immunity to negative effects (can only trigger once per battle) \n Before each attack, absorbs a portion of the target\'s physical defense and permanently converts it into own physical attack (absorption rate is #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# of Bankai Kenpachi’s physical defense, with conversion capped at 50% of Bankai Kenpachi’s physical attack)',
		starEffect = __data_t__starEffect[23616],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Số lần <Ẩn Nấp> toàn trường tăng thêm 1; lần ẩn nấp thứ hai có thể kích hoạt khi máu bản thân dưới 30% và lần ẩn nấp này, sát thương từ đòn tấn công không thể bị né tránh.',
		starEffectDesc = 'เอฟเฟกต์เพิ่มเติม: เพิ่มจำนวนครั้งของสถานะ [ซ่อนตัว] ได้อีก 1 ครั้ง โดยการเข้าสู่ [ซ่อนตัว] ครั้งที่สองจะเกิดขึ้นเมื่อพลังชีวิตของตนเองต่ำกว่า 30% และการโจมตีในครั้งนั้นจะไม่สามารถหลบหลีกได้',
		starEffectDesc_en = 'Additional effect: The number of <Ẩn Nấp> on the field increases by 1; the second <Ẩn Nấp> can be activated when own HP is below 30%, and during this <Ẩn Nấp>, damage from attacks cannot be evaded.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เพิ่มจำนวนครั้งของสถานะ [ซ่อนตัว] ได้อีก 1 ครั้ง โดยการเข้าสู่ [ซ่อนตัว] ครั้งที่สองจะเกิดขึ้นเมื่อพลังชีวิตของตนเองต่ำกว่า 30% และการโจมตีในครั้งนั้นจะไม่สามารถหลบหลีกได้',
		starEffectDesc_in = 'Efek tambahan: Jumlah <Ẩn Nấp> di seluruh medan bertambah 1; <Ẩn Nấp> kedua dapat diaktifkan saat HP sendiri di bawah 30%, dan selama <Ẩn Nấp> ini, kerusakan dari serangan tidak dapat dihindari.',
		starEffectDesc_ph = 'Karagdagang epekto: Ang bilang ng <Ẩn Nấp> sa buong field ay nadagdagan ng 1; ang ikalawang <Ẩn Nấp> ay maaaring i-activate kapag ang sariling HP ay mababa sa 30%, at sa panahon ng <Ẩn Nấp> na ito, ang damage mula sa mga atake ay hindi maiiwasan.',
		starEffectDesc_ma = 'Kesan tambahan: Bilangan <Ẩn Nấp> di medan bertambah 1; kali kedua <Ẩn Nấp> boleh diaktifkan apabila nyawa sendiri di bawah 30%, dan semasa <Ẩn Nấp> ini, kerosakan daripada serangan tidak boleh dielak.',
		zawakeEffect = __data_t__zawakeEffect[23616],
		-- {79004, 1}
		zawakeEffectDesc = 'Additional effect: <Stealth> +1 for the entire game. The second <Stealth> can enter and hide a second time when own HP ratio is below 30%. Subsequent action turns after hiding twice are immune to negative effects and cannot avoid damage dealt, meanwhile it also comes with 10% life steal for 1 turn.',
		zawakeEffectDesc_en = 'Additional effect: <Stealth> +1 for the entire game. The second <Stealth> can enter and hide a second time when own HP ratio is below 30%. Subsequent action turns after hiding twice are immune to negative effects and cannot avoid damage dealt, meanwhile it also comes with 10% life steal for 1 turn.',
		zawakeEffectDesc_th = 'ผลกระทบเสริม: <ล่องหน> +1 ตลอดทั้งเกม <ล่องหน> ครั้งที่สองสามารถเข้าสู่สถานะและซ่อนตัวครั้งที่สองได้เมื่ออัตราส่วน HP ของตนเองต่ำกว่า 30% การกระทำในรอบถัดไปหลังจากซ่อนตัวสองครั้งจะได้รับการป้องกันจากผลลบและไม่สามารถหลีกเลี่ยงความเสียหายที่เกิดขึ้นได้ พร้อมกับมีการดูดเลือด 10% ใน 1 รอบ',
		zawakeEffectDesc_in = 'Efek tambahan: <Sembunyi> +1 untuk seluruh permainan. <Sembunyi> kedua dapat masuk dan bersembunyi untuk kedua kalinya ketika rasio HP sendiri kurang dari 30%. Giliran aksi berikutnya setelah bersembunyi dua kali akan kebal terhadap efek negatif dan tidak dapat menghindari kerusakan yang diterima, sekaligus disertai dengan pencurian nyawa 10% selama 1 giliran.',
		zawakeEffectDesc_ph = 'Karagdagang epekto: <Tago> +1 para sa buong laro. Ang pangalawang <Tago> ay maaaring pumasok at magtago ng pangalawang beses kapag ang sariling porsyento ng HP ay mas mababa sa 30%. Ang mga sumunod na turno pagkatapos magtago ng dalawang beses ay immune sa mga negatibong epekto at hindi maiiwasan ang pinsalang dulot, kasabay ng 10% life steal sa loob ng 1 turno.',
		zawakeEffectDesc_ma = 'Kesan tambahan: <Sembunyi> +1 untuk keseluruhan permainan. <Sembunyi> kedua boleh masuk dan menyembunyikan diri kali kedua apabila nisbah HP sendiri kurang daripada 30%. Giliran tindakan selepas bersembunyi dua kali akan kebal terhadap kesan negatif dan tidak dapat mengelak kerosakan yang dikenakan, sekaligus disertai dengan penyerapan darah sebanyak 10% selama 1 giliran.',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: <Tàng hình> +1 cho toàn bộ trò chơi. <Tàng hình> thứ hai có thể tiến vào và ẩn náu lần thứ hai khi tỷ lệ máu của bản thân thấp hơn 30%. Các hiệp hành động sau khi ẩn nấp hai lần sẽ miễn nhiễm với các tác động tiêu cực và không thể tránh khỏi sát thương gây ra, đồng thời nó còn đi kèm với việc hút máu 10% trong 1 hiệp.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#For two turns after hiding, you will be immune to negative effects and unavoidable damage, and gain 10% lifesteal for 1 turn.',
		zawakeSimpleDesc_en = '#C0x5c9970#For two turns after hiding, you will be immune to negative effects and unavoidable damage, and gain 10% lifesteal for 1 turn.',
		zawakeSimpleDesc_th = '#C0x5c9970#ใน 2 เทิร์นหลังจากหลบซ่อน จะไม่ติดผลสถานะลบและไม่สามารถหลบหลีกความเสียหาย พร้อมกับดูดเลือด 10% เป็นเวลา 1 เทิร์น',
		zawakeSimpleDesc_in = '#C0x5c9970#Selama dua giliran setelah bersembunyi, kamu akan kebal terhadap efek negatif dan tidak bisa menghindari damage, serta memperoleh lifesteal 10% selama 1 giliran.',
		zawakeSimpleDesc_ph = '#C0x5c9970#Sa loob ng dalawang turn pagkatapos magtago, immune ka sa negative effects at hindi maiiwasan ang damage, kasabay ng 10% lifesteal sa loob ng 1 turn.',
		zawakeSimpleDesc_ma = '#C0x5c9970#Selama dua pusingan selepas bersembunyi, anda akan kebal terhadap kesan negatif dan tidak boleh mengelak kerosakan, serta mendapat 10% serapan nyawa selama 1 pusingan.',
		zawakeSimpleDesc_vn = '#C0x5c9970# Trong hai lượt hành động sau khi ẩn nấp, bạn sẽ miễn nhiễm với các hiệu ứng tiêu cực và không thể né tránh sát thương gây ra, đồng thời sẽ kèm theo hút máu 10% trong 1 lượt.',
