	[23653] = {
		id = 23653,
		skillName_vn = 'Á Không Liệt Trảm',
		skillName_en = 'A No Slice Slash',
		skillName_th = 'อา ไม่ฟันหั่น',
		skillName_in = 'A Tidak Memotong Irisan',
		skillName_ph = 'A Walang Hiwa',
		skillName_ma = 'A Tiada Potongan Irisan',
		skillName = 'A No Slice Slash',
		describe_vn = 'Tấn công mục tiêu của kẻ thù với mức phòng thủ hợp pháp thấp nhất',
		describe_en = 'Attack the enemy\'s target with the lowest legal defense level',
		describe_th = 'โจมตีเป้าหมายของศัตรูที่มีระดับการป้องกันตามกฎหมายต่ำที่สุด',
		describe_in = 'Serang target musuh dengan tingkat pertahanan legal terendah',
		describe_ph = 'Atakihin ang target ng kalaban na may pinakamababang legal na depensa',
		describe_ma = 'Serang sasaran musuh dengan tahap pertahanan sah yang terendah',
		describe = 'Attack the enemy\'s target with the lowest legal defense level',
		simDesc_vn = 'Palkia xuất hiện từ mặt phẳng không gian, sau đó đưa mục tiêu duy nhất của kẻ địch ở hàng sau vào một không gian chiều khác, tấn công bằng cách chia tách không gian phụ (chọn mục tiêu có khả năng phòng thủ pháp lý thấp nhất ở hàng sau trong chiến đấu tự động), gây sát thương phép và giải phóng không gian để tăng cường hiệu ứng. Sau khi tiêu diệt mục tiêu, sát thương tràn của chiêu thức đặc biệt này sẽ được chuyển sang mục tiêu ngẫu nhiên còn lại của kẻ địch.',
		simDesc_en = 'Palkia appears from the spatial plane, then takes the enemy\'s only target in the back row into another dimensional space, attacking by splitting the auxiliary space (selecting the target with the lowest magical defense in the back row during auto-battle), dealing magic damage and releasing the space to enhance effects. After eliminating the target, the overflow damage from this special move will be transferred to a random remaining enemy target.',
		simDesc_th = 'ปาลเคียปรากฏจากมิติเวลา จากนั้นนำเป้าหมายเดียวของศัตรูที่อยู่แถวหลังเข้าสู่มิติอื่น โจมตีโดยการแยกพื้นที่ช่วย (เลือกเป้าหมายที่มีค่าป้องกันเวทมนตร์ต่ำที่สุดในแถวหลังในโหมดต่อสู้อัตโนมัติ) สร้างความเสียหายเวทมนตร์และปลดปล่อยพื้นที่เพื่อเพิ่มพลัง หลังจากกำจัดเป้าหมายแล้ว ความเสียหายส่วนเกินจากท่าพิเศษนี้จะถูกส่งต่อไปยังเป้าหมายศัตรูที่เหลือแบบสุ่ม',
		simDesc_in = 'Palkia muncul dari bidang ruang, kemudian membawa satu-satunya target musuh di barisan belakang ke dimensi lain, menyerang dengan memisahkan ruang tambahan (memilih target dengan pertahanan sihir terendah di barisan belakang dalam pertarungan otomatis), memberikan kerusakan sihir dan melepaskan ruang untuk meningkatkan efek. Setelah menghabisi target, kerusakan berlebih dari serangan khusus ini akan dialihkan ke target musuh acak yang tersisa.',
		simDesc_ph = 'Lumilit si Palkia mula sa espasyo, pagkatapos ay inilipat ang nag-iisang target ng kalaban sa likurang hanay sa ibang dimensyon, umatake sa pamamagitan ng paghahati ng karagdagang espasyo (pinipili ang target na may pinakamababang depensa sa salamangka sa likurang hanay sa awtomatikong laban), nagdudulot ng pinsala mula sa salamangka at pinapalaya ang espasyo upang mapalakas ang epekto. Pagkatapos mapanalunan ang target, ang sobrang pinsala mula sa espesyal na galaw na ito ay ililipat sa isang random na natitirang kalaban.',
		simDesc_ma = 'Palkia muncul dari ruang dimensi, kemudian membawa satu-satunya sasaran musuh di barisan belakang ke dimensi lain, menyerang dengan memisahkan ruang tambahan (memilih sasaran dengan pertahanan sihir terendah di barisan belakang dalam pertempuran automatik), memberikan kerosakan sihir dan membebaskan ruang untuk meningkatkan kesan. Setelah menghapus sasaran, kerosakan lebihan dari serangan khas ini akan dialihkan ke sasaran musuh rawak yang masih ada.',
		simDesc = 'Palkia appears from the spatial plane, then takes the enemy\'s only target in the back row into another dimensional space, attacking by splitting the auxiliary space (selecting the target with the lowest magical defense in the back row during auto-battle), dealing magic damage and releasing the space to enhance effects. After eliminating the target, the overflow damage from this special move will be transferred to a random remaining enemy target.',
		starEffect = __data_t__starEffect[23653],
		-- {11}
		starEffectDesc_vn = 'Sau khi thi triển tuyệt kỹ này, bản thân sẽ vào trạng thái ẩn thân và triệu hồi một ảo ảnh tại chỗ.',
		starEffectDesc = 'After performing this special move, the user will enter stealth mode and summon an illusion at the spot.',
		starEffectDesc_en = 'After performing this special move, the user will enter stealth mode and summon an illusion at the spot.',
		starEffectDesc_th = 'หลังจากใช้ท่าไม้ตายนี้ ตัวละครจะเข้าสู่สถานะล่องหนและเรียกภาพลวงตาขึ้นที่จุดนั้น',
		starEffectDesc_in = 'Setelah menggunakan teknik khusus ini, karakter akan memasuki mode menghilang dan memanggil ilusi di tempat tersebut.',
		starEffectDesc_ph = 'Pagkatapos gamitin ang natatanging galaw na ito, ang karakter ay mapapasok sa estado ng pagtatago at magtatawag ng ilusyon sa lugar.',
		starEffectDesc_ma = 'Selepas menggunakan teknik khas ini, watak akan memasuki mod tersembunyi dan memanggil ilusi di tempat itu.',
		zawakeEffect = __data_t__zawakeEffect[23653],
		-- {79003}
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Additional Effect: Purify 2 defense buffs from the target\nOverflow damage may target another enemy, with an added 15% damage transfer rate from the selected target.',
		zawakeSimpleDesc_en = 'Additional Effect: Purify 2 defense buffs from the target\nOverflow damage may target another enemy, with an added 15% damage transfer rate from the selected target.',
		zawakeSimpleDesc_th = 'เอฟเฟกต์เสริม: ล้างบัฟป้องกัน 2 รายการของเป้าหมาย\nความเสียหายส่วนเกินสามารถส่งต่อไปยังเป้าหมายศัตรูอื่น อัตราการส่งต่อความเสียหายของเป้าหมายเพิ่มขึ้นอีก 15%',
		zawakeSimpleDesc_in = 'Efek Tambahan: Membersihkan 2 buff pertahanan dari target\nDamage berlebih dapat mengenai target musuh lain, dengan tambahan rasio transfer damage 15%.',
		zawakeSimpleDesc_ph = 'Karagdagang Epekto: Linisin ang 2 buff ng depensa ng kalaban\nAng sobrang damage ay maaaring mapunta sa ibang kalaban, at tataas ang damage transfer rate ng target ng 15%.',
		zawakeSimpleDesc_ma = 'Kesan Tambahan: Menyucikan 2 peningkatan pertahanan daripada sasaran\nKerosakan berlebihan boleh menyasarkan musuh lain, dengan tambahan kadar pemindahan kerosakan sebanyak 15%.',
		zawakeSimpleDesc_vn = 'Hiệu ứng bổ sung: Thanh lọc mục tiêu bằng 2 bùa lợi phòng thủ\nSát thương tràn có thể nhắm thêm vào mục tiêu địch và tỷ lệ sát thương chuyển của mục tiêu được chọn bổ sung là 15%.',
		iconRes = 'battle/skill_icon/skill_23613.png',
