	[23656] = {
		id = 23656,
		skillName_vn = 'Space Concealment',
		skillName_en = 'Space Concealment',
		skillName_th = 'การซ่อนตัวในอวกาศ',
		skillName_in = 'Penyembunyian Ruang',
		skillName_ph = 'Pagkukunwarta ng Espasyo',
		skillName_ma = 'Penyembunyian Ruang',
		skillName = 'Space Concealment',
		describe_vn = 'ma',
		describe_en = 'demon',
		describe_th = 'เคนพาจิเชี่ยวชาญวิชาดาบแห่งมิติ ฝึกฝนการซ่อนตัวในมิติ: เมื่อตนเองได้รับความเสียหายจากสกิลเกิน 30% ของพลังชีวิตสูงสุด หรือพลังชีวิตลดลงต่ำกว่า 60% จะเข้าสู่สถานะ [ซ่อนตัว]: เข้าสู่มิติซ่อน (ในมิตินี้จะไม่ได้รับความเสียหายหรือผลจากสกิลใด ๆ) และก่อนจะลงมือในเทิร์นถัดไป จะกลับสู่สนาม ล้างสถานะผิดปกติทั้งหมด ฟื้นฟูโทสะ 1000 หน่วย เพิ่มอัตราคริติคอล 20% และได้รับภูมิคุ้มกันดีบัฟ 1 เทิร์น (สามารถเกิดได้เพียง 1 ครั้งต่อการต่อสู้)  ก่อนการโจมตีแต่ละครั้ง จะดูดซับพลังป้องกันกายภาพบางส่วนของเป้าหมายแล้วเปลี่ยนเป็นพลังโจมตีกายภาพถาวร (สัดส่วนการดูดซับคือ #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# ของพลังป้องกันกายภาพของ เคนพาจิ – ขั้นปลดปล่อย โดยพลังโจมตีที่แปลงได้ถาวรสูงสุดไม่เกิน 50% ของพลังโจมตีกายภาพของตัวเอง)',
		describe_in = 'iblis',
		describe_ph = 'demonyo',
		describe_ma = 'iblis',
		describe = 'demon',
		starEffect = __data_t__starEffect[23656],
		-- {8}
		starEffectDesc_vn = 'Khi vào trạng thái <Ẩn Nấp>, bản thân tạo ra một ảo ảnh tại chỗ (ảo ảnh kế thừa 100% thuộc tính của bản thân, ảo ảnh có thể sử dụng kỹ năng tấn công thường của bản thể nhưng không có hiệu ứng bổ sung, ảo ảnh tấn công thường một lần vào mục tiêu có phòng thủ phép thấp nhất của địch rồi biến mất).',
		starEffectDesc = 'When entering the <Ẩn Nấp> state, the user creates an illusion at the spot (the illusion inherits 100% of the user\'s attributes, the illusion can use the user\'s normal attack skills but without additional effects, the illusion performs one normal attack on the enemy target with the lowest magic defense and then disappears).',
		starEffectDesc_en = 'When entering the <Ẩn Nấp> state, the user creates an illusion at the spot (the illusion inherits 100% of the user\'s attributes, the illusion can use the user\'s normal attack skills but without additional effects, the illusion performs one normal attack on the enemy target with the lowest magic defense and then disappears).',
		starEffectDesc_th = 'เมื่อเข้าสู่สถานะ <Ẩn Nấp> ผู้เล่นจะสร้างภาพลวงตาที่ตำแหน่งเดิม (ภาพลวงตาสืบทอดคุณสมบัติ 100% จากผู้เล่น ภาพลวงตาสามารถใช้ทักษะโจมตีปกติของผู้เล่นได้แต่ไม่มีผลเสริม ภาพลวงตาจะโจมตีปกติเป้าหมายหนึ่งครั้งที่มีการป้องกันเวทมนตร์ต่ำที่สุดของศัตรู จากนั้นภาพลวงตาจะหายไป)',
		starEffectDesc_in = 'Saat masuk ke status <Ẩn Nấp>, pengguna menciptakan ilusi di tempat itu (ilusi mewarisi 100% atribut pengguna, ilusi dapat menggunakan skill serangan normal pengguna tetapi tanpa efek tambahan, ilusi menyerang normal sekali ke target musuh dengan pertahanan sihir terendah, lalu menghilang).',
		starEffectDesc_ph = 'Kapag pumapasok sa estado ng <Ẩn Nấp>, lumilikha ang sarili ng ilusyon sa lugar (ang ilusyon ay namamana ang 100% katangian ng sarili, maaaring gamitin ng ilusyon ang normal na kasanayan sa pag-atake ng orihinal pero walang karagdagang epekto, isang normal na atake lang ang gagawin ng ilusyon sa kalaban na may pinakamababang magic defense, pagkatapos ay nawawala ito).',
		starEffectDesc_ma = 'Apabila memasuki keadaan <Ẩn Nấp>, pengguna akan menghasilkan satu ilusi di tempat itu (ilusi mewarisi 100% atribut pengguna, ilusi boleh menggunakan kemahiran serangan biasa pengguna tetapi tanpa kesan tambahan, ilusi menyerang biasa sekali ke sasaran musuh yang mempunyai pertahanan sihir paling rendah, kemudian hilang).',
		zawakeEffect = __data_t__zawakeEffect[23656],
		-- {79004, 1}
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '\nEffect Upgrade: For two turns after hiding, you will be immune to negative effects and unavoidable damage, and gain 10% lifesteal for 1 turn.',
		zawakeSimpleDesc_en = '\nEffect Upgrade: For two turns after hiding, you will be immune to negative effects and unavoidable damage, and gain 10% lifesteal for 1 turn.',
		zawakeSimpleDesc_th = '\nปรับปรุงเอฟเฟกต์: ใน 2 เทิร์นหลังจากหลบซ่อน จะไม่ติดผลสถานะลบและไม่สามารถหลบหลีกความเสียหาย พร้อมกับดูดเลือด 10% เป็นเวลา 1 เทิร์น',
		zawakeSimpleDesc_in = '\nPeningkatan Efek: Selama dua giliran setelah bersembunyi, kamu akan kebal terhadap efek negatif dan tidak bisa menghindari damage, serta mendapatkan lifesteal 10% selama 1 giliran.',
		zawakeSimpleDesc_ph = '\nPinahusay na Epekto: Sa loob ng dalawang turn pagkatapos magtago, immune ka sa negative effects at hindi maiiwasan ang damage, at may 10% lifesteal sa loob ng 1 turn.',
		zawakeSimpleDesc_ma = '\nPenambahbaikan Kesan: Selama dua pusingan selepas bersembunyi, anda akan kebal terhadap kesan negatif dan tidak boleh mengelak kerosakan, serta memperoleh 10% serapan nyawa selama 1 pusingan.',
		zawakeSimpleDesc_vn = '\nCải thiện hiệu ứng: Trong hai lượt hành động sau khi ẩn nấp, bạn sẽ miễn nhiễm với các hiệu ứng tiêu cực và không thể né tránh sát thương gây ra, đồng thời sẽ nhận được 10% hút máu trong 1 lượt.',
		iconRes = 'battle/skill_icon/skill_23616.png',
