	[23663] = {
		id = 23663,
		skillName_vn = 'Á Không Liệt Trảm',
		skillName_en = 'A No Lie Slash',
		skillName_th = 'เอ โน ไม้ ขีด',
		skillName_in = 'A Tidak Ada Tebas',
		skillName_ph = 'A Walang Hiwa',
		skillName_ma = 'A Tiada Tebas',
		skillName = 'A No Lie Slash',
		describe_vn = 'Tấn công mục tiêu của kẻ thù với mức phòng thủ hợp pháp thấp nhất',
		describe_en = 'Attack the enemy\'s target with the lowest legitimate defense level',
		describe_th = 'โจมตีเป้าหมายของศัตรูที่มีระดับการป้องกันที่ถูกต้องตามกฎหมายต่ำที่สุด',
		describe_in = 'Serang target musuh dengan tingkat pertahanan sah terendah',
		describe_ph = 'Atakihin ang target ng kalaban na may pinakamababang lehitimong depensa',
		describe_ma = 'Serang sasaran musuh dengan tahap pertahanan yang sah terendah',
		describe = 'Attack the enemy\'s target with the lowest legitimate defense level',
		simDesc_vn = 'Palkia xuất hiện từ mặt phẳng không gian, sau đó đưa mục tiêu duy nhất của kẻ địch ở hàng sau vào một không gian chiều khác, tấn công bằng cách chia tách không gian phụ (chọn mục tiêu có khả năng phòng thủ pháp lý thấp nhất ở hàng sau trong chiến đấu tự động), gây sát thương phép và giải phóng không gian để tăng cường hiệu ứng. Sau khi tiêu diệt mục tiêu, sát thương tràn của chiêu thức đặc biệt này sẽ được chuyển sang mục tiêu ngẫu nhiên còn lại của kẻ địch.',
		simDesc_en = 'Palkia appears from a spatial plane, then sends the enemy\'s only target in the back row into another dimensional space, attacking by splitting a subspace (selecting the enemy with the lowest magical defense in the back row in auto battle), dealing magic damage and releasing space to enhance the effect. After defeating the target, the overflow damage of this special move is transferred to a random remaining enemy target.',
		simDesc_th = 'ปัลเกียปรากฏมาจากมิติอวกาศ จากนั้นส่งเป้าหมายเดียวของศัตรูในแถวหลังเข้าไปในอีกมิติหนึ่ง ทำการโจมตีโดยแยกมิติเสริม (เลือกเป้าหมายที่มีการป้องกันเวทมนตร์ต่ำที่สุดในแถวหลังในการต่อสู้อัตโนมัติ) สร้างความเสียหายประเภทเวทมนตร์และปลดปล่อยพื้นที่เพื่อเพิ่มผลพิเศษ หลังจากกำจัดเป้าหมาย ความเสียหายส่วนเกินของสกิลพิเศษนี้จะถูกส่งต่อไปยังเป้าหมายศัตรูที่เหลือแบบสุ่ม',
		simDesc_in = 'Palkia muncul dari bidang ruang, kemudian mengirim target musuh tunggal di barisan belakang ke dimensi lain, menyerang dengan memisahkan sub-ruang (memilih target dengan pertahanan sihir terendah di barisan belakang dalam pertarungan otomatis), memberikan kerusakan sihir dan melepaskan ruang untuk memperkuat efek. Setelah mengalahkan target, kerusakan berlebih dari kemampuan khusus ini akan dialihkan ke target musuh acak yang tersisa.',
		simDesc_ph = 'Lumilitaw si Palkia mula sa isang espasyo ng dimensyon, pagkatapos ay ipinapadala ang nag-iisang target ng kalaban sa likurang hanay sa ibang dimensyon, umaatake sa pamamagitan ng paghihiwa ng subspace (pinipili ang target na may pinakamababang depensa sa mahika sa likurang hanay sa awtomatikong laban), nagdudulot ng pinsala sa mahika at nagpapalaya ng espasyo upang palakasin ang epekto. Pagkatapos mapatay ang target, ang sobra-sobrang pinsala ng espesyal na atake na ito ay ililipat sa isang random na natitirang target ng kalaban.',
		simDesc_ma = 'Palkia muncul dari bidang ruang, kemudian menghantar sasaran musuh tunggal di barisan belakang ke ruang dimensi lain, menyerang dengan memisahkan sub-ruang (memilih sasaran dengan pertahanan magik terendah di barisan belakang dalam pertempuran automatik), menyebabkan kerosakan magik dan melepaskan ruang untuk menguatkan kesan. Selepas menewaskan sasaran, kerosakan berlebihan dari serangan khas ini akan dipindahkan ke sasaran musuh yang tinggal secara rawak.',
		simDesc = 'Palkia appears from a spatial plane, then sends the enemy\'s only target in the back row into another dimensional space, attacking by splitting a subspace (selecting the enemy with the lowest magical defense in the back row in auto battle), dealing magic damage and releasing space to enhance the effect. After defeating the target, the overflow damage of this special move is transferred to a random remaining enemy target.',
		starEffect = __data_t__starEffect[23663],
		-- {11}
		starEffectDesc_vn = 'Sau khi thi triển kỹ năng tất sát này, bản thân sẽ vào trạng thái ẩn thân và triệu hồi một ảo ảnh tại chỗ.',
		starEffectDesc = 'After casting this deadly skill, the user will enter stealth mode and summon an illusion at the spot.',
		starEffectDesc_en = 'After casting this deadly skill, the user will enter stealth mode and summon an illusion at the spot.',
		starEffectDesc_th = 'หลังใช้สกิลสังหารนี้ ผู้ใช้จะเข้าสู่สถานะล่องหนและเรียกภาพลวงตาที่ตำแหน่งนั้น',
		starEffectDesc_in = 'Setelah menggunakan skill pembunuhan ini, pengguna akan memasuki mode tersembunyi dan memanggil ilusi di lokasi tersebut.',
		starEffectDesc_ph = 'Matapos gamitin ang mapaminsalang kakayahang ito, ang gumagamit ay papasok sa stealth mode at magpapatawag ng ilusyon sa lugar.',
		starEffectDesc_ma = 'Selepas menggunakan kemahiran pembunuhan ini, pengguna akan memasuki mod sembunyi dan memanggil ilusi di lokasi tersebut.',
		zawakeEffect = __data_t__zawakeEffect[23663],
		-- {79003}
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Additional Effect: Purify 2 defensive buffs from the target\nOverflow damage may target another enemy, and the selected target\'s damage transfer rate is increased by 15%.',
		zawakeSimpleDesc_en = 'Additional Effect: Purify 2 defensive buffs from the target\nOverflow damage may target another enemy, and the selected target\'s damage transfer rate is increased by 15%.',
		zawakeSimpleDesc_th = 'เอฟเฟกต์เสริม: ล้างบัฟป้องกัน 2 อย่างของเป้าหมาย\nความเสียหายส่วนเกินสามารถส่งไปยังศัตรูอื่น และเพิ่มอัตราการส่งต่อความเสียหายของเป้าหมายที่เลือกอีก 15%',
		zawakeSimpleDesc_in = 'Efek Tambahan: Membersihkan 2 buff pertahanan dari target\nDamage berlebih dapat mengenai musuh lain, dan rasio transfer damage target yang dipilih bertambah 15%.',
		zawakeSimpleDesc_ph = 'Karagdagang Epekto: Linisin ang 2 buff sa depensa ng kalaban\nAng sobrang damage ay maaaring mapunta sa ibang target, at tataas ng 15% ang damage transfer rate ng target na napili.',
		zawakeSimpleDesc_ma = 'Kesan Tambahan: Membersihkan 2 buff pertahanan dari sasaran\nKerosakan berlebihan boleh disasarkan ke musuh lain, dan kadar pemindahan kerosakan sasaran yang dipilih bertambah sebanyak 15%.',
		zawakeSimpleDesc_vn = 'Hiệu ứng bổ sung: Thanh lọc mục tiêu bằng 2 bùa lợi phòng thủ\nSát thương tràn có thể nhắm thêm vào mục tiêu địch và tỷ lệ sát thương chuyển của mục tiêu được chọn bổ sung là 15%.',
		iconRes = 'battle/skill_icon/skill_23613.png',
