	},
	[23811] = {
		id = 23811,
		skillName_vn = 'Cú đánh ác độc',
		skillName_en = 'A vicious strike',
		skillName_th = 'การชกที่รุนแรง',
		skillName_in = 'Pukulan kejam',
		skillName_ph = 'Makasamang suntok',
		skillName_ma = 'Serangan kejam',
		skillName = 'A vicious strike',
		describe_vn = 'Albedo chém chiếc rìu khổng lồ của mình để tấn công một mục tiêu kẻ thù, gây ra #C0xE69900#160% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, giảm 15% giới hạn máu trên của mục tiêu (tối đa 30% giới hạn trên của Albedo) sức khỏe cơ bản được tạo ra cho BOSS sao chép), kéo dài trong 2 hiệp (không thể xua tan, sao chép hoặc chuyển giao)',
		describe_en = 'Albedo swings his giant axe to attack an enemy target, dealing #C0xE69900#160% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#, reducing the target\'s max HP by 15% (up to 30% of Albedo\'s max HP) based on the base health of the BOSS clone, lasting 2 rounds (cannot be dispelled, copied, or transferred).',
