	[23816] = {
		id = 23816,
		skillName_vn = 'Hình dạng thật của ác ma',
		skillName_en = 'The true form of the demon',
		skillName_th = 'รูปร่างที่แท้จริงของปีศาจ',
		skillName_in = 'Bentuk asli dari iblis',
		skillName_ph = 'Tunay na anyo ng demonyo',
		skillName_ma = 'Bentuk sebenar syaitan',
		skillName = 'The true form of the demon',
		describe_vn = '#L10#Hình dạng thật của quỷ: #L0#Khi vào trận, giảm sát thương bản thân, phòng thủ kép và giới hạn HP ban đầu#C0x5c9970#$(50+skillLevel*0.4-0.4)$ #C0x5B545B#, đồng thời giảm 50% tốc độ tấn công kép và hồi phục tức giận (không thể xua tan và bỏ qua) Vòng tự hành động thứ tư Trước khi bắt đầu, các thuộc tính quay trở lại bình thường, tăng 15% đòn Sát Thương Vật Lý của bản thân (không thể loại bỏ mức tăng vĩnh viễn), giải phóng trạng thái kiểm soát của bản thân (không thể giải phóng trạng thái kiểm soát chi phối), khôi phục hoàn toàn cơn tức giận của bản thân và miễn nhiễm với hiệu ứng giảm tức giận trong 1 hiệp, kích hoạt sự biến đổi của bản thân: khi xác định ngay rằng có một chỗ trống ở hàng sau của trại của mình, bản thân sẽ di chuyển đến vị trí đó;không bản thân nào miễn nhiễm với tác dụng giảm giới hạn trên của lượng máu.',
		describe_en = 'True form of the demon: Upon entering the battle, reduces own damage taken, double defense, and initial HP limit by $(50+skillLevel*0.4-0.4)$. Simultaneously reduces double attack speed by 50% and suppresses anger recovery (cannot be dispelled or bypassed). On the fourth action round, before starting, all attributes return to normal, increases own Physical Damage by 15% (permanent boost cannot be removed), releases control states on self (except domination control), fully restores own anger and is immune to anger reduction effects for one turn, activates self-transformation: if a free slot is detected in the rear row of own camp, moves to that position; no self is immune to the effect of reducing the upper limit of HP.',
		describe_th = 'รูปลักษณ์ที่แท้จริงของปีศาจ: เมื่อลงสนาม ลดความเสียหายตัวเอง, ป้องกันสองชั้น และขีดจำกัด HP เริ่มต้นลง $(50+skillLevel*0.4-0.4)$. พร้อมกันนี้ลดความเร็วโจมตีสองเท่า 50% และฟื้นฟูความโกรธ (ไม่สามารถลบหรือเลี่ยงได้) ในรอบการกระทำที่สี่ ก่อนเริ่ม คุณสมบัติทั้งหมดจะกลับสู่ปกติ เพิ่มพลังโจมตีทางกายภาพของตัวเอง 15% (เพิ่มถาวรไม่สามารถลบได้), ปลดปล่อยสถานะควบคุมตนเอง (ไม่รวมสถานะควบคุมแบบครอบงำ), ฟื้นฟูความโกรธเต็มที่และได้รับภูมิคุ้มกันต่อผลลดความโกรธเป็นเวลา 1 เทิร์น, เปิดใช้งานการแปลงร่าง: หากตรวจพบช่องว่างในแถวหลังของค่ายตัวเอง จะย้ายไปตำแหน่งนั้น; ไม่มีตัวใดได้รับภูมิคุ้มกันจากผลลดขีดจำกัดสูงสุดของเลือด',
		describe_in = 'Bentuk asli dari iblis: Saat memasuki pertarungan, mengurangi kerusakan yang diterima, pertahanan ganda, dan batas HP awal sebesar $(50+levelKeterampilan*0.4-0.4)$. Secara bersamaan mengurangi kecepatan serangan ganda sebesar 50% dan pemulihan kemarahan (tidak dapat dibersihkan atau diabaikan). Pada giliran aksi keempat, sebelum memulai, semua atribut kembali normal, meningkatkan 15% Damage Fisik sendiri (peningkatan permanen tidak dapat dihilangkan), melepaskan status kontrol diri (kecuali kontrol dominasi), memulihkan kemarahan secara penuh dan kebal terhadap efek pengurangan kemarahan selama 1 giliran, mengaktifkan transformasi diri: jika terdeteksi slot kosong di barisan belakang kamp sendiri, maka berpindah ke posisi tersebut; tidak ada diri yang kebal terhadap efek pengurangan batas maksimum HP.',
		describe_ph = 'Tunay na anyo ng demonyo: Kapag pumasok sa laban, binabawasan ang sariling pinsala, dobleng depensa, at paunang limitasyon ng HP ng $(50+antasNgKasanayan*0.4-0.4)$. Kasabay nito, binabawasan ang bilis ng doble na pag-atake ng 50% at pagpapagaling ng galit (hindi maaaring alisin o balewalain). Sa ika-apat na ikot ng aksyon, bago magsimula, bumabalik sa normal ang lahat ng katangian, pinapataas ang sariling Pisikal na Pinsala ng 15% (hindi maaaring tanggalin ang permanenteng pagtaas), pinalalaya ang mga kontrol na estado sa sarili (maliban sa dominasyong kontrol), ganap na pinapawi ang sariling galit at immune sa mga epekto ng pagbawas ng galit sa loob ng 1 turn, pina-aktibo ang sariling transformasyon: kapag natiyak na may bakanteng puwesto sa likurang hanay ng sariling kampo, lilipat sa posisyong iyon; walang sarili ang immune sa epekto ng pagbabawas ng itaas na limitasyon ng HP.',
		describe_ma = 'Bentuk sebenar iblis: Apabila memasuki pertempuran, mengurangkan kerosakan diri sendiri, pertahanan berganda dan had HP awal sebanyak $(50+peringkatKemahiran*0.4-0.4)$. Pada masa yang sama mengurangkan kelajuan serangan berganda sebanyak 50% dan pemulihan kemarahan (tidak boleh dibersihkan atau diabaikan). Pada pusingan tindakan keempat, sebelum memulakan, semua atribut kembali normal, meningkatkan 15% Kerosakan Fizikal sendiri (peningkatan kekal tidak boleh dibuang), melepaskan keadaan kawalan diri (kecuali kawalan dominasi), memulihkan kemarahan sepenuhnya dan kebal terhadap kesan pengurangan kemarahan selama 1 giliran, mengaktifkan perubahan diri: jika terdapat ruang kosong di barisan belakang kem kumpulan sendiri, diri akan bergerak ke posisi itu; tiada diri yang kebal terhadap kesan pengurangan had atas HP.',
		describe = 'True form of the demon: Upon entering the battle, reduces own damage taken, double defense, and initial HP limit by $(50+skillLevel*0.4-0.4)$. Simultaneously reduces double attack speed by 50% and suppresses anger recovery (cannot be dispelled or bypassed). On the fourth action round, before starting, all attributes return to normal, increases own Physical Damage by 15% (permanent boost cannot be removed), releases control states on self (except domination control), fully restores own anger and is immune to anger reduction effects for one turn, activates self-transformation: if a free slot is detected in the rear row of own camp, moves to that position; no self is immune to the effect of reducing the upper limit of HP.',
		starEffect = __data_t__starEffect[23816],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu quả: Tăng 30% Công Vật Lý cho bản thân trước khi bắt đầu hiệp tấn công thứ ba (tăng vĩnh viễn, không thể bị giải trừ) và vẫn giữ lại 20% giảm sát thương, phòng thủ kép, giới hạn máu ban đầu được tăng trong Chân Thân Ác Ma.Tăng giới hạn máu cho các Ma Thần Anh Hùng phe mình (từ 30% giới hạn máu cơ bản của Albedo).',
		starEffectDesc = 'Enhance Effectiveness: Increase own Physical Attack by 30% before starting the third attack round (permanent increase, cannot be removed) and still retain 20% damage reduction, double defense, initial HP limit increased in True Body Demon. Increase HP limit for allied Demon Heroes (from 30% of Albedo\'s base HP limit).',
		starEffectDesc_en = 'Enhance Effectiveness: Increase own Physical Attack by 30% before starting the third attack round (permanent increase, cannot be removed) and still retain 20% damage reduction, double defense, initial HP limit increased in True Body Demon. Increase HP limit for allied Demon Heroes (from 30% of Albedo\'s base HP limit).',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: เพิ่มพลังโจมตีทางกายภาพของตัวเองขึ้น 30% ก่อนเริ่มรอบโจมตีที่สาม (เพิ่มถาวร ไม่สามารถถูกลบได้) และยังคงรักษาการลดความเสียหาย 20%, ป้องกันสองชั้น, จำกัดพลังชีวิตเริ่มต้นเพิ่มขึ้นในร่างแท้ปีศาจ เพิ่มขีดจำกัดพลังชีวิตให้กับฮีโร่ปีศาจฝ่ายเดียวกัน (จาก 30% ของขีดจำกัดพลังชีวิตพื้นฐานของ Albedo)',
		starEffectDesc_in = 'Tingkatkan Efektivitas: Tingkatkan Serangan Fisik sendiri sebesar 30% sebelum memulai ronde serangan ketiga (peningkatan permanen, tidak bisa dihapus) dan tetap mempertahankan pengurangan kerusakan 20%, pertahanan ganda, batas HP awal yang ditingkatkan dalam Tubuh Asli Setan. Tingkatkan batas HP untuk Pahlawan Setan sekutu (dari 30% batas HP dasar Albedo).',
		starEffectDesc_ph = 'Pahusayin ang Bisa: Taasan ang sarili na 30% Pisikal na Atake bago simulan ang ikatlong round ng pag-atake (permanenteng pagtaas, hindi maaaring alisin) at panatilihin ang 20% pagbawas ng pinsala, doble depensa, initial HP limit na tumaas sa True Body Demon. Taasan ang HP limit para sa mga kaalyadong Demon Heroes (mula sa 30% ng base HP limit ni Albedo).',
		starEffectDesc_ma = 'Tingkatkan Keberkesanan: Tambah Serangan Fizikal diri sendiri sebanyak 30% sebelum memulakan pusingan serangan ketiga (peningkatan kekal, tidak boleh dipadamkan) dan masih mengekalkan pengurangan kerosakan 20%, pertahanan berganda, had HP awal yang ditingkatkan dalam Tubuh Asal Syaitan. Tingkatkan had HP untuk Wira Syaitan sekutu (dari 30% had HP asas Albedo).',
		zawakeEffect = __data_t__zawakeEffect[23816],
		-- {79004, 1}
		zawakeEffectDesc = 'Enhance effect: Before starting the third attack round, increase your Physical Damage by 30% (permanent increase cannot be removed) and the damage reduction is increased, double defense and the initial HP limit in the demon body will remain at 40%\nYou can act once when changing position\nIncrease the HP limit of your demon and superhero (from Albedo\'s basic 30% HP limit)',
		zawakeEffectDesc_en = 'Enhance effect: Before starting the third attack round, increase your Physical Damage by 30% (permanent increase cannot be removed) and the damage reduction is increased, double defense and the initial HP limit in the demon body will remain at 40%\nYou can act once when changing position\nIncrease the HP limit of your demon and superhero (from Albedo\'s basic 30% HP limit)',
		zawakeEffectDesc_th = 'เพิ่มเอฟเฟกต์: ก่อนเริ่มรอบโจมตีที่สาม ให้เพิ่มความเสียหายทางกายภาพของตนเอง 30% (เพิ่มถาวรไม่สามารถลบได้) และการลดความเสียหายเพิ่มขึ้น, ป้องกันสองเท่า และขีดจำกัด HP เริ่มต้นในร่างปีศาจจะยังคงอยู่ที่ 40%\nคุณสามารถทำการกระทำได้ครั้งหนึ่งเมื่อเปลี่ยนตำแหน่ง\nเพิ่มขีดจำกัด HP ของปีศาจและซูเปอร์ฮีโร่ของคุณ (จากขีดจำกัด HP พื้นฐาน 30% ของ Albedo)',
		zawakeEffectDesc_in = 'Tingkatkan efek: Sebelum memulai putaran serangan ketiga, tingkatkan 30% Serangan Fisik Anda (peningkatan permanen tidak dapat dihapus) dan peningkatan pengurangan kerusakan, pertahanan ganda dan batas HP awal dalam tubuh iblis akan tetap 40%\nAnda dapat bertindak sekali saat mengganti posisi\nTingkatkan batas HP iblis dan pahlawan super Anda sendiri (dari batas HP dasar 30% milik Albedo)',
		zawakeEffectDesc_ph = 'Pahusayin ang epekto: Bago simulan ang ikatlong pag-ikot ng atake, dagdagan ng 30% ang iyong Pisikal na Pinsala (hindi matatanggal ang permanenteng pagdagdag) at tumataas ang pagbawas ng pinsala, dobleng depensa at ang unang limitasyon ng HP sa katawan ng demonyo ay mananatili sa 40%\nMaaari kang kumilos nang isang beses kapag nagpalit ng posisyon\nDagdagan ang limitasyon ng HP ng iyong demonyo at superhero (mula sa pangunahing 30% na limitasyon ng HP ni Albedo)',
		zawakeEffectDesc_ma = 'Tingkatkan kesan: Sebelum memulakan pusingan serangan ketiga, tingkatkan 30% Serangan Fizikal anda (kenaikan kekal tidak boleh dialih keluar) dan tahap pengurangan kerosakan meningkat, pertahanan berganda dan had HP awal dalam tubuh syaitan akan kekal pada 40%\nAnda boleh bertindak sekali apabila menukar posisi\nTingkatkan had HP syaitan dan wira super anda sendiri (daripada had HP asas 30% Albedo)',
		zawakeEffectDesc_vn = 'Nâng cao hiệu ứng: Trước khi bắt đầu vòng tấn công thứ ba, hãy tăng 30% đòn Sát Thương Vật Lý của bản thân (mức tăng vĩnh viễn không thể bị loại bỏ) và mức giảm sát thương tăng lên, phòng thủ kép và giới hạn HP ban đầu trong cơ thể quỷ sẽ vẫn là 40%\nBạn có thể hành động một lần khi thay đổi vị trí\nTăng giới hạn HP của quỷ và siêu anh hùng của riêng bạn (từ giới hạn HP cơ bản 30% của Albedo)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Damage reduction increases, double defense and initial HP cap in Demon True Body remains at 20%\n#F20# \n#F40##C0x5c9970#→Damage reduction increases, double defense and initial HP cap in Demon True Body remains at 40%\nYou can act once when changing position.',
		zawakeSimpleDesc_en = 'Damage reduction increases, double defense and initial HP cap in Demon True Body remains at 20%\n#F20# \n#F40##C0x5c9970#→Damage reduction increases, double defense and initial HP cap in Demon True Body remains at 40%\nYou can act once when changing position.',
		zawakeSimpleDesc_th = 'เพิ่มอัตราลดความเสียหาย, พลังป้องกันสองเท่า และขีดจำกัด HP ดั้งเดิมในร่าง Demon True Body ยังคงอยู่ที่ 20%\n#F20# \n#F40##C0x5c9970#→เพิ่มอัตราลดความเสียหาย, พลังป้องกันสองเท่า และขีดจำกัด HP ดั้งเดิมในร่าง Demon True Body เป็น 40%\nสามารถเคลื่อนไหวหนึ่งครั้งเมื่อเปลี่ยนตำแหน่ง',
		zawakeSimpleDesc_in = 'Pengurangan damage meningkat, pertahanan ganda dan batas HP awal dalam Demon True Body tetap 20%\n#F20# \n#F40##C0x5c9970#→Pengurangan damage meningkat, pertahanan ganda dan batas HP awal dalam Demon True Body tetap 40%\nBisa bertindak sekali saat mengubah posisi.',
		zawakeSimpleDesc_ph = 'Tumaas ang damage reduction, double defense at base HP limit sa Demon True Body nananatili sa 20%\n#F20# \n#F40##C0x5c9970#→Tumaas ang damage reduction, double defense at base HP limit sa Demon True Body nananatili sa 40%\nMaaaring kumilos isang beses kapag nagpalit ng posisyon.',
		zawakeSimpleDesc_ma = 'Tahap pengurangan kerosakan meningkat, pertahanan berganda dan had HP awal dalam Demon True Body kekal pada 20%\n#F20# \n#F40##C0x5c9970#→Tahap pengurangan kerosakan meningkat, pertahanan berganda dan had HP awal dalam Demon True Body kekal pada 40%\nBoleh bergerak sekali semasa menukar posisi.',
		zawakeSimpleDesc_vn = 'Mức giảm sát thương tăng lên, phòng thủ gấp đôi và giới hạn HP ban đầu trong Demon True Body vẫn giữ nguyên 20%\n#F20# \n#F40##C0x5c9970#→Tăng khả năng giảm sát thương, phòng thủ gấp đôi và giới hạn HP ban đầu trong Demon True Body vẫn giữ lại 40%\nBạn có thể hành động một lần khi thay đổi vị trí.',
		iconRes = 'battle/skill_icon/skill_23816.png',
