	[23911] = {
		id = 23911,
		skillName_vn = 'Huyết Quỷ Thuật: Dải Lụa',
		skillName_en = 'Blood Demon Technique: Silk Ribbon',
		skillName_th = 'เทคนิคลมปีศาจเลือด: ริบบิ้นผ้าไหม',
		skillName_in = 'Teknik Iblis Darah: Pita Sutra',
		skillName_ph = 'Blood Demon Technique: Silk Ribbon',
		skillName_ma = 'Teknik Iblis Darah: Pita Sutera',
		skillName = 'Blood Demon Technique: Silk Ribbon',
		describe_vn = 'Công chúa sa ngã đập đất triệu hồi một cơn gió lạ tấn công một mục tiêu địch, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, tăng gấp đôi phòng thủ của cô ấy lên 50% trong 2 lượt và nhận được 1 điểm ma sau đòn tấn công.',
		describe_en = 'The fallen princess slams the ground, summoning a strange wind to attack an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Physical Damage#C0x5B545B#, doubling her defense by 50% for 2 turns and gaining 1 mana point after the attack.',
		describe_th = 'เจ้าหญิงผู้ล่มสลายตะปบพื้น ดึงลมประหลาดโจมตีเป้าหมายศัตรู สร้าง #C0xE69900#100% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มเกราะของเธอเป็นสองเท่าเป็น 50% เป็นเวลา 2 เทิร์น และได้รับ 1 พ้อยต์มานาหลังจากการโจมตี',
		describe_in = 'Putri yang jatuh menghantam tanah, memanggil angin aneh untuk menyerang target musuh, memberikan #C0xE69900#100% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerusakan Fisik#C0x5B545B#, menggandakan pertahanannya menjadi 50% selama 2 giliran dan mendapatkan 1 poin mana setelah serangan.',
		describe_ph = 'Ang bumagsak na prinsesa ay tumama sa lupa, naglunsad ng kakaibang hangin upang atakihin ang isang kalaban, nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Pisikal na Pinsala#C0x5B545B#, pinadodoble ang kanyang depensa sa 50% sa loob ng 2 turnos at nakakakuha ng 1 punto ng mana pagkatapos ng atake.',
		describe_ma = 'Puteri yang jatuh memukul tanah, memanggil angin aneh untuk menyerang sasaran musuh, memberikan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerosakan Fizikal#C0x5B545B#, menggandakan pertahanannya kepada 50% selama 2 giliran dan menerima 1 mata mana selepas serangan.',
		describe = 'The fallen princess slams the ground, summoning a strange wind to attack an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Physical Damage#C0x5B545B#, doubling her defense by 50% for 2 turns and gaining 1 mana point after the attack.',
		simDesc_vn = 'Công chúa sa ngã đập đất triệu hồi một cơn gió lạ tấn công một mục tiêu địch, gây sát thương vật lý, tăng khả năng giảm sát thương của bản thân và phục hồi bóng ma.',
		simDesc_en = 'The fallen princess strikes the ground, summoning a strange wind that attacks an enemy target, dealing physical damage, increasing her damage reduction, and restoring the phantom.',
		simDesc_th = 'เจ้าหญิงผู้พลัดตกกระทบพื้นแล้วเรียกลมประหลาดโจมตีเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ เพิ่มความสามารถลดความเสียหายของตนเอง และฟื้นฟูผีเสื้อ',
		simDesc_in = 'Putri yang jatuh menghantam tanah memanggil angin aneh yang menyerang target musuh, menyebabkan kerusakan fisik, meningkatkan kemampuan pengurangan kerusakan dirinya dan memulihkan bayangan.',
		simDesc_ph = 'Ang bumagsak na prinsesa ay binugbog ang lupa upang tawagin ang kakaibang hangin na umatake sa isang target na kaaway, nagdudulot ng pisikal na pinsala, nagpapataas ng kakayahan sa pagbawas ng pinsala sa sarili, at nagpapagaling ng multo.',
		simDesc_ma = 'Puteri yang jatuh memukul tanah dan memanggil angin aneh menyerang sasaran musuh, menyebabkan kerosakan fizikal, meningkatkan keupayaan penurunan kerosakan diri sendiri dan memulihkan bayangan.',
		simDesc = 'The fallen princess strikes the ground, summoning a strange wind that attacks an enemy target, dealing physical damage, increasing her damage reduction, and restoring the phantom.',
		zawakeEffect = __data_t__zawakeEffect[23911],
		-- {79001}
		zawakeEffectDesc = 'The fallen princess slams the ground to summon a strange wind that attacks an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Physical Damage#C0x5B545B#. It increases its own double defense by 50% for 2 turns and resistance rate by 15% for 2 turns. After attacking, it gains 1 mana point.',
		zawakeEffectDesc_en = 'The fallen princess slams the ground to summon a strange wind that attacks an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Physical Damage#C0x5B545B#. It increases its own double defense by 50% for 2 turns and resistance rate by 15% for 2 turns. After attacking, it gains 1 mana point.',
		zawakeEffectDesc_th = 'เจ้าหญิงผู้ตกต่ำกระแทกพื้นเพื่อเรียกลมประหลาดโจมตีเป้าหมายศัตรูหนึ่งตัว ทำ #C0xE69900#100% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# มันเพิ่มความสามารถการป้องกันสองเท่าของตนเองขึ้นอีก 50% เป็นเวลา 2 เทิร์น และอัตราต้านทานเพิ่มขึ้น 15% เป็นเวลา 2 เทิร์น หลังจากโจมตี มันได้รับ 1 คะแนนมานา',
		zawakeEffectDesc_in = 'Putri yang jatuh menghantam tanah untuk memanggil angin aneh yang menyerang satu target musuh, memberikan #C0xE69900#100% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerusakan Fisik#C0x5B545B#. Ini meningkatkan pertahanan gandanya sendiri sebesar 50% selama 2 giliran dan tingkat resistensi sebesar 15% selama 2 giliran. Setelah menyerang, ia mendapatkan 1 poin mana.',
		zawakeEffectDesc_ph = 'Ang bumagsak na prinsesa ay pinapalo ang lupa upang tawagin ang isang kakaibang hangin na umatake sa isang kaaway na target, nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Pinapataas nito ang sariling dobleng depensa ng 50% sa loob ng 2 turn at ang rate ng resistensya ng 15% sa loob ng 2 turn. Pagkatapos umatake, nakakakuha ito ng 1 mana point.',
		zawakeEffectDesc_ma = 'Puteri yang jatuh menghentak tanah untuk memanggil angin aneh menyerang satu sasaran musuh, menyebabkan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Ia meningkatkan pertahanan bergandanya sendiri sebanyak 50% selama 2 pusingan dan kadar rintangan sebanyak 15% selama 2 pusingan. Selepas menyerang, ia menerima 1 mata tenaga.',
		zawakeEffectDesc_vn = 'Công chúa sa ngã đập đất triệu hồi một cơn gió lạ tấn công một mục tiêu địch, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B#. Nó tăng khả năng phòng thủ gấp đôi của chính mình thêm 50% trong 2 lượt và tỷ lệ kháng cự thêm 15% trong 2 lượt. Sau khi tấn công, nó nhận được 1 điểm ma.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increase own double defense by 50% for 2 turns\n#F20# \n#F40##C0x5c9970#→Increase own double defense by 50% for 2 turns and resistance rate by 15% for 2 turns',
		zawakeSimpleDesc_en = 'Increase own double defense by 50% for 2 turns\n#F20# \n#F40##C0x5c9970#→Increase own double defense by 50% for 2 turns and resistance rate by 15% for 2 turns',
		zawakeSimpleDesc_th = 'เพิ่มพลังป้องกันสองเท่าของตัวเอง 50% ใน 2 เทิร์น\n#F20# \n#F40##C0x5c9970#→เพิ่มพลังป้องกันสองเท่าของตัวเอง 50% และอัตราต้านทาน 15% ใน 2 เทิร์น',
		zawakeSimpleDesc_in = 'Meningkatkan pertahanan ganda sendiri sebesar 50% selama 2 giliran\n#F20# \n#F40##C0x5c9970#→Meningkatkan pertahanan ganda sendiri sebesar 50% dan resistensi sebesar 15% selama 2 giliran',
		zawakeSimpleDesc_ph = 'Tumaas ng 50% ang double defense ng sarili sa loob ng 2 turn\n#F20# \n#F40##C0x5c9970#→Tumaas ng 50% ang double defense ng sarili sa loob ng 2 turn at 15% resistance sa loob ng 2 turn',
		zawakeSimpleDesc_ma = 'Tingkatkan pertahanan berganda sebanyak 50% selama 2 pusingan\n#F20# \n#F40##C0x5c9970#→Tingkatkan pertahanan berganda sebanyak 50% dan kadar ketahanan sebanyak 15% selama 2 pusingan',
		zawakeSimpleDesc_vn = 'Tăng 50% phòng thủ đôi của bản thân trong 2 lượt\n#F20# \n#F40##C0x5c9970#→ Tăng 50% phòng thủ đôi của bản thân trong 2 lượt và 15% tỷ lệ chống chịu trong 2 lượt',
		upLvDesc = 'Fixed damage +96',
		upLvDesc_en = 'Fixed damage +96',
		upLvDesc_th = 'ความเสียหายคงที่ +96',
