	[23912] = {
		id = 23912,
		skillName_vn = 'Huyết Quỷ Thuật: U Minh Hỏa',
		skillName_en = 'Blood Demon Technique: Netherworld Fire',
		skillName_th = 'เทคนิคปีศาจเลือด: ไฟยมทูต',
		skillName_in = 'Teknik Iblis Darah: Api Dunia Bawah',
		skillName_ph = 'Teknik Dugo ng Demonyo: Apoy ng Kabilang Mundo',
		skillName_ma = 'Teknik Iblis Darah: Api Alam Bawah',
		skillName = 'Blood Demon Technique: Netherworld Fire',
		describe_vn = 'Công chúa sa ngã biến thành ma và di chuyển đến một mục tiêu địch để đánh lén, gây #C0xE69900#170% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, tăng mức giảm sát thương cho cột của cô ấy thêm 15% trong 2 lượt và nhận được 2 điểm ma sau tấn công\n#F20# \n#F40#[#L10#Awakening Form#L0#], phạm vi tấn công thay đổi theo hàng và có thêm 80% xác suất [#L10#Ghost Fire#L0#] trong 2 lượt\n[#L10#Ghost Ghost Fire#L0#]: Hiệu ứng tiêu cực đặc biệt, chỉ có thể xua tan và không thể chồng lên. Trước khi mục tiêu di chuyển hoặc khi lửa ma bị xua tan, máu của mục tiêu sẽ bị giảm (12% giới hạn trên của lượng máu của nữ hoàng đã ngã xuống, sát thương là sát thương thực sự) và 120 điểm thịnh nộ.',
		describe_en = 'The fallen princess transforms into a demon and moves to a target enemy to ambush, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, increasing damage reduction of her column by 15% for 2 turns and gaining 2 demon points after attack\n#F20# \n#F40#[#L10#Awakening Form#L0#], attack range changes according to the row and gains an 80% chance of [#L10#Ghost Fire#L0#] for 2 turns\n[#L10#Ghost Ghost Fire#L0#]: A special negative effect, can only be dispelled and cannot be stacked. Before the target moves or when the ghost fire is dispelled, the target\'s HP will be reduced (12% of the fallen queen\'s max HP, damage is true damage) and 120 rage points.',
		describe_th = 'เจ้าหญิงผู้ล้มลงเปลี่ยนร่างเป็นปีศาจและเคลื่อนที่ไปยังเป้าหมายศัตรูเพื่อจู่โจมจากด้านหลัง ก่อให้เกิด #C0xE69900#170% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มการลดความเสียหายของแถวของเธอขึ้นอีก 15% เป็นเวลา 2 เทิร์น และได้รับ 2 แต้มปีศาจหลังการโจมตี\n#F20# \n#F40#[#L10#รูปแบบการตื่นรู้#L0#] ระยะโจมตีเปลี่ยนแปลงตามแถวและได้รับโอกาส 80% ในการใช้ [#L10#ไฟผี#L0#] เป็นเวลา 2 เทิร์น\n[#L10#ไฟผีวิญญาณ#L0#]: เอฟเฟกต์ลบพิเศษ มีเพียงการขจัดเท่านั้นที่สามารถลบได้ และไม่สามารถทับซ้อนได้ ก่อนที่เป้าหมายจะเคลื่อนที่หรือเมื่อไฟผีถูกขจัด HP ของเป้าหมายจะลดลง (12% ของ HP สูงสุดของราชินีผู้ล้มลง, ความเสียหายเป็นความเสียหายจริง) และได้รับ 120 แต้มความโกรธ',
		describe_in = 'Putri yang jatuh berubah menjadi setan dan bergerak ke target musuh untuk menyerang secara diam-diam, memberikan #C0xE69900#170% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, meningkatkan pengurangan kerusakan untuk kolomnya sebesar 15% selama 2 giliran dan mendapatkan 2 poin setan setelah serangan\n#F20# \n#F40#[#L10#Form Kebangkitan#L0#], jangkauan serangan berubah sesuai baris dan mendapatkan peluang 80% [#L10#Api Hantu#L0#] selama 2 giliran\n[#L10#Api Hantu#L0#]: Efek negatif khusus, hanya bisa dihapus dan tidak bisa ditumpuk. Sebelum target bergerak atau saat api hantu dihapus, HP target akan berkurang (12% dari batas atas HP ratu yang terjatuh, kerusakan adalah kerusakan nyata) dan 120 poin kemarahan.',
		describe_ph = 'Ang prinsesang bumagsak ay nagiging demonyo at lumilipat sa isang target na kalaban upang umatake nang palihim, nagdudulot ng #C0xE69900#170% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, nagpapataas ng pagbawas ng pinsala para sa kanyang hanay ng 15% sa loob ng 2 mga turn at nakakakuha ng 2 puntos ng demonyo pagkatapos ng atake\n#F20# \n#F40#[#L10#Awakening Form#L0#], nagbabago ang saklaw ng atake ayon sa hanay at may 80% na tsansa ng [#L10#Ghost Fire#L0#] sa loob ng 2 mga turn\n[#L10#Ghost Ghost Fire#L0#]: Isang espesyal na negatibong epekto, maaari lamang maalis at hindi maaaring pagsamahin. Bago kumilos ang target o kapag naialis ang apoy ng multo, ang HP ng target ay babawasan (12% ng maximum na HP ng bumagsak na reyna, ang pinsala ay totoong pinsala) at 120 puntos ng galit.',
		describe_ma = 'Puteri yang jatuh berubah menjadi iblis dan bergerak ke sasaran musuh untuk menyerang secara tiba-tiba, menyebabkan #C0xE69900#170% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, meningkatkan tahap pengurangan kerosakan untuk barisnya sebanyak 15% selama 2 pusingan dan menerima 2 mata iblis selepas serangan\n#F20# \n#F40#[#L10#Bentuk Kebangkitan#L0#], jarak serangan berubah mengikut baris dan mendapat peluang 80% [#L10#Api Hantu#L0#] selama 2 pusingan\n[#L10#Api Hantu Hantu#L0#]: Kesan negatif istimewa, hanya boleh dihapus dan tidak boleh bertindih. Sebelum sasaran bergerak atau apabila api hantu dihapus, nyawa sasaran akan berkurang (12% batas atas nyawa ratu yang jatuh, kerosakan adalah kerosakan sebenar) dan 120 mata kemarahan.',
		describe = 'The fallen princess transforms into a demon and moves to a target enemy to ambush, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, increasing damage reduction of her column by 15% for 2 turns and gaining 2 demon points after attack\n#F20# \n#F40#[#L10#Awakening Form#L0#], attack range changes according to the row and gains an 80% chance of [#L10#Ghost Fire#L0#] for 2 turns\n[#L10#Ghost Ghost Fire#L0#]: A special negative effect, can only be dispelled and cannot be stacked. Before the target moves or when the ghost fire is dispelled, the target\'s HP will be reduced (12% of the fallen queen\'s max HP, damage is true damage) and 120 rage points.',
		simDesc_vn = 'Công chúa sa ngã biến thành một bóng ma và di chuyển đến một mục tiêu kẻ thù để đánh lén, gây sát thương vật lý, tăng cơn thịnh nộ tối đa của mục tiêu và nhận điểm ma cho bản thân; ở dạng thức tỉnh, phạm vi tấn công thay đổi thành một hàng, có khả năng thêm lửa ma.',
		simDesc_en = 'The fallen princess transforms into a ghost and moves to a target enemy for a stealth attack, dealing physical damage, increasing the target\'s maximum rage, and gaining soul points for herself; in awakened form, the attack range changes to a line, with the ability to add ghostly fire.',
		simDesc_th = 'เจ้าหญิงผู้ล่มสลายเปลี่ยนร่างเป็นผีและเคลื่อนที่ไปยังศัตรูเป้าหมายเพื่อโจมตีลอบทำร้าย สร้างความเสียหายทางกายภาพ เพิ่มความโกรธสูงสุดของเป้าหมาย และได้รับคะแนนวิญญาณสำหรับตัวเอง ในรูปแบบตื่นรู้ ระยะโจมตีจะเปลี่ยนเป็นแถว มีความสามารถเพิ่มไฟผีได้',
		simDesc_in = 'Putri yang jatuh berubah menjadi hantu dan bergerak menuju musuh target untuk serangan diam-diam, memberikan kerusakan fisik, meningkatkan kemarahan maksimum target, dan mendapatkan poin jiwa untuk dirinya sendiri; dalam bentuk kebangkitan, jangkauan serangan berubah menjadi satu baris, dengan kemampuan menambah api hantu.',
		simDesc_ph = 'Ang bumagsak na prinsesa ay nagbabago sa isang multo at lumilipat sa isang target na kaaway para sa lihim na pag-atake, nagdudulot ng pisikal na pinsala, pinapataas ang pinakamataas na galit ng target, at nakakakuha ng puntos ng kaluluwa para sa kanyang sarili; sa ginising na anyo, ang saklaw ng pag-atake ay nagbabago sa isang linya, na may kakayahang magdagdag ng apoy ng multo.',
		simDesc_ma = 'Puteri yang jatuh berubah menjadi hantu dan bergerak ke sasaran musuh untuk serangan secara senyap, memberikan kerosakan fizikal, meningkatkan kemarahan maksimum sasaran, dan memperoleh mata roh untuk dirinya sendiri; dalam bentuk kebangkitan, julat serangan berubah menjadi satu baris, dengan keupayaan menambah api roh.',
		simDesc = 'The fallen princess transforms into a ghost and moves to a target enemy for a stealth attack, dealing physical damage, increasing the target\'s maximum rage, and gaining soul points for herself; in awakened form, the attack range changes to a line, with the ability to add ghostly fire.',
		zawakeEffect = __data_t__zawakeEffect[23912],
		-- {79002}
		zawakeEffectDesc = 'The fallen princess transforms into a demon and moves to an enemy target to ambush, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage#C0x5B545B#, increasing damage reduction for her column by 20% for 2 turns and gaining 2 demon points after attack\n#F20# \n#F40#<#L10#Awakening Form#L0#>, attack range changes by row and gains 80% chance of <#L10#Ghost Fire#L0#> for 2 turns and adds <#L10#Ghost Shield#L0> to your demon-type dark hero. #>\n<#L10#鬼火#L0#>: A special negative effect, can only be dispelled and cannot be stacked. Before the target moves or when ghost fire is dispelled, the target\'s HP is reduced (12% of the upper limit of the fallen queen\'s HP, damage is true damage) and 120 rage points.',
		zawakeEffectDesc_en = 'The fallen princess transforms into a demon and moves to an enemy target to ambush, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage#C0x5B545B#, increasing damage reduction for her column by 20% for 2 turns and gaining 2 demon points after attack\n#F20# \n#F40#<#L10#Awakening Form#L0#>, attack range changes by row and gains 80% chance of <#L10#Ghost Fire#L0#> for 2 turns and adds <#L10#Ghost Shield#L0> to your demon-type dark hero. #>\n<#L10#鬼火#L0#>: A special negative effect, can only be dispelled and cannot be stacked. Before the target moves or when ghost fire is dispelled, the target\'s HP is reduced (12% of the upper limit of the fallen queen\'s HP, damage is true damage) and 120 rage points.',
		zawakeEffectDesc_th = 'เจ้าหญิงผู้ล้มลงเปลี่ยนร่างเป็นปีศาจและเคลื่อนที่ไปยังเป้าหมายศัตรูเพื่อโจมตีแบบลอบทำร้าย สร้าง #C0xE69900#170% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ ของ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มความสามารถในการลดความเสียหายให้แก่คอลัมน์ของเธออีก 20% ใน 2 เทิร์น และได้รับ 2 แต้มปีศาจหลังโจมตี\n#F20# \n#F40#<#L10#Awakening Form#L0#> ระยะโจมตีเปลี่ยนแปลงตามแถวและมีโอกาส 80% ของ <#L10#Ghost Fire#L0#> ใน 2 เทิร์น และเพิ่ม <#L10#Ghost Shield#L0> ให้กับฮีโร่ปิศาจสายมืดของคุณ #>\n<#L10#鬼火#L0#>: ผลกระทบลบพิเศษ สามารถลบได้เท่านั้นและไม่สามารถซ้อนทับได้ ก่อนที่เป้าหมายจะเคลื่อนที่หรือเมื่อไฟผีถูกลบ เลือดของเป้าหมายจะถูกลดลง (12% ของขีดจำกัดสูงสุดของเลือดราชินีผู้ล้มลง ความเสียหายเป็นความเสียหายจริง) และเพิ่มความโกรธ 120 แต้ม',
		zawakeEffectDesc_in = 'Putri yang jatuh berubah menjadi iblis dan bergerak ke target musuh untuk menyerang secara diam-diam, memberikan #C0xE69900#170% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54# Kerusakan Fisik#C0x5B545B#, meningkatkan kemampuan pengurangan kerusakan untuk kolomnya sebesar 20% selama 2 giliran dan mendapatkan 2 poin iblis setelah menyerang\n#F20# \n#F40#<#L10#Awakening Form#L0#>, jangkauan serangan berubah mengikuti baris dan memiliki 80% peluang <#L10#Ghost Fire#L0#> selama 2 giliran dan menambahkan <#L10#Ghost Shield#L0> ke pahlawan gelap tipe iblis Anda. #>\n<#L10#鬼火#L0#>: Efek negatif khusus, hanya dapat dihilangkan dan tidak dapat ditumpuk. Sebelum target bergerak atau saat api hantu dihilangkan, HP target akan berkurang (12% dari batas atas HP ratu yang jatuh, kerusakan adalah kerusakan nyata) dan 120 poin amarah.',
		zawakeEffectDesc_ph = 'Ang prinsesang bumagsak ay nagiging demonyo at lumalapit sa kalabang target para sa isang palihim na pag-atake, nagdudulot ng #C0xE69900#170% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$ ng #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, nagpapataas ng kakayahan sa pagbawas ng pinsala para sa kanyang kolum ng 20% sa loob ng 2 mga turn at nakakakuha ng 2 puntos ng demonyo pagkatapos ng pag-atake\n#F20# \n#F40#<#L10#Awakening Form#L0#>, nagbabago ang saklaw ng pag-atake ayon sa hanay at may 80% tsansa ng <#L10#Ghost Fire#L0#> sa loob ng 2 mga turn at nagdadagdag ng <#L10#Ghost Shield#L0> sa iyong madilim na bayani na uri ng demonyo. #>\n<#L10#鬼火#L0#>: Isang espesyal na negatibong epekto, maaari lamang matanggal at hindi maaaring mag-stack. Bago gumalaw ang target o kapag nawala ang apoy ng multo, nababawasan ang HP ng target (12% ng pinakamataas na limitasyon ng HP ng bumagsak na reyna, ang pinsala ay totoong pinsala) at 120 puntos ng galit.',
		zawakeEffectDesc_ma = 'Puteri yang gugur berubah menjadi syaitan dan bergerak ke sasaran musuh untuk menyerang secara tiba-tiba, memberikan #C0xE69900#170% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ daripada #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, meningkatkan keupayaan pengurangan kerosakan untuk lajur beliau sebanyak 20% selama 2 pusingan dan mendapat 2 mata syaitan selepas serangan\n#F20# \n#F40#<#L10#Awakening Form#L0#>, jarak serangan berubah mengikut baris dan mempunyai 80% peluang <#L10#Ghost Fire#L0#> selama 2 pusingan serta menambah <#L10#Ghost Shield#L0> kepada wira gelap jenis syaitan anda. #>\n<#L10#鬼火#L0#>: Kesan negatif khas, hanya boleh dipadam dan tidak boleh bertindih. Sebelum sasaran bergerak atau apabila api hantu dipadamkan, darah sasaran akan berkurang (12% daripada had atas darah permaisuri yang gugur, kerosakan adalah kerosakan sebenar) dan 120 mata amarah.',
		zawakeEffectDesc_vn = 'Công chúa sa ngã biến thành ma và di chuyển đến một mục tiêu địch để đánh lén, gây #C0xE69900#170% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ của #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, tăng khả năng giảm sát thương cho cột của cô ấy thêm 20% trong 2 lượt và nhận được 2 điểm ma sau tấn công\n#F20# \n#F40#<#L10#Awakening Form#L0#>, phạm vi tấn công thay đổi theo hàng và có thêm 80% xác suất <#L10#Ghost Fire#L0#> trong 2 lượt và thêm <#L10#Ghost Shield#L0> cho anh hùng bóng tối loại ma của riêng bạn. #>\n<#L10#鬼火#L0#>: Hiệu ứng tiêu cực đặc biệt, chỉ có thể xua tan và không thể chồng chất. Trước khi mục tiêu di chuyển hoặc khi lửa ma bị xua tan, máu của mục tiêu sẽ bị giảm (12% giới hạn trên của lượng máu của nữ hoàng đã ngã xuống, sát thương là sát thương thực sự) và 120 điểm thịnh nộ.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increase your column’s damage reduction by 15% for 2 turns\n#F20# \n#F40##C0x5c9970#→Increase your column’s damage reduction by 20% for 2 turns\n<#L10#Awakening Form#L0#> Adds <#L10#Ghost Shield#L0#> to your Ghost and Dark heroes.',
		zawakeSimpleDesc_en = 'Increase your column’s damage reduction by 15% for 2 turns\n#F20# \n#F40##C0x5c9970#→Increase your column’s damage reduction by 20% for 2 turns\n<#L10#Awakening Form#L0#> Adds <#L10#Ghost Shield#L0#> to your Ghost and Dark heroes.',
		zawakeSimpleDesc_th = 'เพิ่มการลดความเสียหายให้กับแถวของคุณ 15% ใน 2 เทิร์น\n#F20# \n#F40##C0x5c9970#→เพิ่มการลดความเสียหายให้กับแถวของคุณ 20% ใน 2 เทิร์น\n<#L10#Awakening Form#L0#> เพิ่ม <#L10#Ghost Shield#L0#> ให้กับผีและฮีโร่ธาตุมืดของคุณ',
		zawakeSimpleDesc_in = 'Meningkatkan pengurangan damage untuk kolommu sebesar 15% selama 2 giliran\n#F20# \n#F40##C0x5c9970#→Meningkatkan pengurangan damage untuk kolommu sebesar 20% selama 2 giliran\n<#L10#Awakening Form#L0#> Menambahkan <#L10#Ghost Shield#L0#> ke Ghost dan hero Gelap milikmu.',
		zawakeSimpleDesc_ph = 'Tumaas ang damage reduction ng column mo ng 15% sa loob ng 2 turn\n#F20# \n#F40##C0x5c9970#→Tumaas ang damage reduction ng column mo ng 20% sa loob ng 2 turn\n<#L10#Awakening Form#L0#> Nagdadagdag ng <#L10#Ghost Shield#L0#> para sa mga Ghost at Dark heroes mo.',
		zawakeSimpleDesc_ma = 'Tingkatkan pengurangan kerosakan untuk lajur anda sebanyak 15% selama 2 pusingan\n#F20# \n#F40##C0x5c9970#→Tingkatkan pengurangan kerosakan untuk lajur anda sebanyak 20% selama 2 pusingan\n<#L10#Awakening Form#L0#> Menambah <#L10#Ghost Shield#L0#> kepada Hantu dan wira Elemen Gelap anda.',
		zawakeSimpleDesc_vn = 'Tăng mức giảm sát thương cho cột của bạn thêm 15% trong 2 lượt\n#F20# \n#F40##C0x5c9970#→Tăng mức giảm sát thương cho cột của bạn thêm 20% trong 2 lượt\n<#L10#Awakening Form#L0#> Thêm <#L10#Ghost Shield#L0#> cho bóng ma và anh hùng bóng tối của riêng bạn.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
