	[23913] = {
		id = 23913,
		skillName_vn = 'Huyết Quỷ Thuật: Bát Trọng Đới Trảm',
		skillName_en = 'Blood Demon Technique: Eightfold Belt Slash',
		skillName_th = 'เทคนิคลมปีศาจเลือด: ฟันสายรัดแปดชั้น',
		skillName_in = 'Teknik Iblis Darah: Tebasan Sabuk Delapan Lapisan',
		skillName_ph = 'Blood Demon Technique: Walong Ulap na Gupit',
		skillName_ma = 'Teknik Iblis Darah: Hirisan Tali Delapan Lapisan',
		skillName = 'Blood Demon Technique: Eightfold Belt Slash',
		describe_vn = 'Công chúa sa ngã thức dậy từ vực thẳm, sau đó triệu hồi lối vào thế giới đảo ngược, hút các đơn vị hàng đầu của kẻ địch vào đó, gây #C0xE69900#230% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, giảm cơn thịnh nộ của mục tiêu trúng đòn đi 250 điểm và nhận được 3 điểm ma sau khi tấn công\n#F20# \n#F40#Sau khi thực hiện chiêu thức đặc biệt, anh ta chuyển sang [#L10#Hình thức thức tỉnh#L0#] trong 2 hiệp. Giới hạn trên của lượng máu của chính anh ta (chỉ tăng giới hạn trên), tốc độ và tổng tỷ lệ kiểm soát được tăng thêm 50% (không thể phân tán, chuyển giao, sao chép), Chuyển sang chiêu thức đặc biệt mới (không yêu cầu cuồng nộ và không tiêu hao thịnh nộ khi giải phóng, hạ nhiệt trong 2 lượt sau khi giải phóng): Phạm vi thay đổi đối với tất cả kẻ thù và có thêm 75% xác suất thêm [#L10#鬼鬼火#L0#] của 4 anh hùng của kẻ địch có cơn thịnh nộ cao nhất trong 2 lượt.',
		describe_en = 'The fallen princess awakens from the abyss, then summons the entrance to the reversed world, pulling the enemy\'s top units inside, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, reducing the rage of hit targets by 250 points and gaining 3 mana points after attacking\n#F20# \n#F40#After performing the special skill, he switches to [#L10#Awakened Form#L0#] for 2 turns. His maximum health cap (only the cap increases), speed, and total control rate increase by 50% (cannot be dispersed, transferred, or copied). Switches to a new special skill (does not require rage and does not consume rage upon release, cooldown 2 turns after release): The range changes to all enemies and adds a 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy heroes with the highest rage for 2 turns.',
		describe_th = 'ดาคิหลุดสติคลั่ง ใช้ท่าไม้ตาย [ศิลปะเลือดปีศาจ · แปดชั้นดาบริบบิ้น] โจมตีศัตรูแถวหน้า พร้อมเรียกวิญญาณอสูรบุกรุกโลกมนุษย์ สร้างความเสียหายกายภาพ #C0xE69900#250% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# ลดโทสะของเป้าหมายลง 250 หน่วย และได้รับแต้ม [เงาอสูร] 3 แต้ม #F20# #F40# หลังใช้ท่าไม้ตายจะเข้าสู่ [ร่างตื่นรู้] เป็นเวลา 2 เทิร์น เพิ่มพลังชีวิตสูงสุด (เฉพาะส่วนที่เพิ่ม), ความเร็ว, และอัตราต้านสถานะควบคุมทั้งหมดขึ้น 50% (ไม่สามารถถูกลบ ย้าย หรือคัดลอกได้) พร้อมเปลี่ยนท่าไม้ตายใหม่ (ใช้โดยไม่ต้องใช้โทสะและไม่เสียโทสะ มีคูลดาวน์ 2 เทิร์น): เปลี่ยนเป็นโจมตีศัตรูทุกตัว และมีโอกาส 75% ที่จะทำให้ฮีโร่ศัตรูที่มีโทสะสูงสุด 4 ตัว ได้รับ [ไฟวิญญาณนรก] เป็นเวลา 2 เทิร์น',
		describe_in = 'Putri yang jatuh terbangun dari jurang, kemudian memanggil pintu masuk ke dunia terbalik, menarik unit teratas musuh ke dalamnya, memberikan #C0xE69900#230% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Kerusakan Fisik #C0x5B545B#, mengurangi kemarahan target yang terkena sebanyak 250 poin dan mendapatkan 3 poin mana setelah menyerang\n#F20# \n#F40#Setelah menggunakan skill khusus, dia beralih ke [#L10#Bentuk Terbangun#L0#] selama 2 giliran. Batas atas HP-nya (hanya batas atas yang meningkat), kecepatan, dan total persentase kontrol meningkat 50% (tidak dapat disebarkan, dialihkan, atau disalin). Beralih ke skill khusus baru (tidak memerlukan kemarahan dan tidak menghabiskan kemarahan saat digunakan, cooldown 2 giliran setelah digunakan): Jangkauannya berubah ke semua musuh dan menambahkan peluang 75% untuk menambahkan [#L10#鬼鬼火#L0#] pada 4 pahlawan musuh dengan kemarahan tertinggi selama 2 giliran.',
		describe_ph = 'Ang bumagsak na prinsesa ay nagising mula sa kailaliman, pagkatapos ay tinawag ang pasukan sa baligtad na mundo, hinihila ang mga nangungunang yunit ng kalaban doon, nagdudulot ng #C0xE69900#230% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, binabawasan ang galit ng mga target na tinamaan ng 250 puntos at nakakakuha ng 3 mana points pagkatapos umatake\n#F20# \n#F40#Pagkatapos isagawa ang espesyal na kakayahan, siya ay lumilipat sa [#L10#Na-gising na Any0#L0#] sa loob ng 2 turns. Ang itaas na hangganan ng kanyang HP (tanging ang limitasyon lang ang tataas), bilis, at kabuuang porsyento ng control ay tataas ng 50% (hindi maaaring ipamahagi, ilipat, o kopyahin). Lumilipat sa bagong espesyal na kakayahan (hindi nangangailangan ng galit at hindi kumokonsumo ng galit sa pagpapalabas, cooldown 2 turns pagkatapos ng pagpapalabas): Ang saklaw ay nagbabago sa lahat ng kalaban at may dagdag na 75% na tsansa na magdagdag ng [#L10#鬼鬼火#L0#] sa 4 na mga bayani ng kalaban na may pinakamataas na galit sa loob ng 2 turns.',
		describe_ma = 'Puteri yang jatuh terbangun dari jurang, kemudian memanggil pintu masuk ke dunia terbalik, menarik unit teratas musuh ke dalamnya, memberikan #C0xE69900#230% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, mengurangkan kemarahan sasaran yang terkena sebanyak 250 mata dan menerima 3 mata mana selepas menyerang\n#F20# \n#F40#Selepas melaksanakan kemahiran khas, dia bertukar kepada [#L10#Bentuk Kebangkitan#L0#] selama 2 pusingan. Had atas HPnya (hanya had atas bertambah), kelajuan dan kadar kawalan keseluruhan meningkat sebanyak 50% (tidak boleh dibahagikan, dipindahkan, atau disalin). Bertukar kepada kemahiran khas baru (tidak memerlukan kemarahan dan tidak menggunakan kemarahan apabila melepaskan, masa sejuk selama 2 pusingan selepas melepaskan): Julat bertukar kepada semua musuh dan menambah peluang 75% untuk menambah [#L10#鬼鬼火#L0#] ke 4 wira musuh yang mempunyai kemarahan tertinggi selama 2 pusingan.',
		describe = 'ดากิคลุ้มคลั่ง ปล่อยวิชาลับ "โลหิตอสูร · แปดคมสายสะบัด" โจมตีศัตรูแถวหน้า พร้อมอัญเชิญอสูรรุกโลกมนุษย์ สร้างความเสียหายกายภาพ #C0xE69900#250% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ เป็น #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# ลดพลังโกรธของเป้าหมายที่โดนลง 250 หน่วย และหลังโจมตีจะได้รับ 3 แต้มเงาอสูร \n#F20# \n#F40# หลังใช้ท่าไม้ตาย จะเข้าสู่สถานะ [#L10#ร่างตื่นรู้#L0#] เป็นเวลา 2 เทิร์น เพิ่มพลังชีวิตสูงสุด (เฉพาะส่วนที่เพิ่มจากฐาน), ความเร็ว, และอัตราต้านสถานะควบคุมทั้งหมดขึ้น 50% (ไม่สามารถถูกลบ ย้าย หรือคัดลอกได้) พร้อมเปลี่ยนท่าไม้ตายใหม่ (ไม่ต้องใช้โกรธและไม่สิ้นเปลืองโกรธ แต่มีคูลดาวน์ 2 เทิร์น): เป้าหมายกลายเป็นศัตรูทุกคน และมีโอกาส 75% ทำให้ศัตรูที่มีโกรธสูงสุด 4 ตัวได้รับ [#L10#เปลวไฟอสูรนรก#L0#] เป็นเวลา 2 เทิร์น',
		simDesc_vn = 'Nữ hoàng sa ngã tỉnh dậy từ vực thẳm, sau đó triệu hồi lối vào thế giới ngược để hút các đơn vị hàng đầu của kẻ địch vào đó, giảm giá trị tức giận của chúng và phục hồi bóng ma, chuyển sang dạng thức tỉnh, phạm vi tấn công trở thành toàn bộ cơ thể và có lửa ma.',
		simDesc_en = 'The fallen queen awakens from the abyss, then summons the entrance to the inverted world to吸引 the enemy\'s top units into it, reducing their anger value and restoring the phantom, shifting into an awakened form with an attack range encompassing the entire body and possessing spectral flames.',
		simDesc_th = 'ราชินีผู้ล่มสลายตื่นขึ้นจากหุบเหว จากนั้นเรียกประตูไปยังโลกกลับหัวเพื่อดูดหน่วยชั้นนำของศัตรูเข้าไป ลดค่าความโกรธของพวกเขาและฟื้นฟูปีศาจเงา เปลี่ยนเป็นรูปแบบการตื่นรู้ ช่วงการโจมตีกลายเป็นร่างกายทั้งหมดและมีไฟวิญญาณ',
		simDesc_in = 'Ratu yang jatuh bangun dari jurang, kemudian memanggil pintu masuk ke dunia terbalik untuk menarik unit-unit utama musuh ke dalamnya, mengurangi nilai kemarahan mereka dan memulihkan hantu, beralih ke bentuk kebangkitan, jangkauan serangan menjadi seluruh tubuh dan memiliki api gaib.',
		simDesc_ph = 'Nagising ang bumagsak na reyna mula sa kailaliman, pagkatapos ay tinawag ang pasukan sa mundo ng baliktad upang mahila ang mga nangungunang yunit ng kalaban doon, binabawasan ang halaga ng kanilang galit at binabawi ang phantom, lumilipat sa paggising na anyo, ang saklaw ng atake ay naging buong katawan at may apoy na espiritu.',
		simDesc_ma = 'Ratu yang jatuh bangun dari jurang, kemudian memanggil pintu masuk ke dunia terbalik untuk menarik unit utama musuh ke dalamnya, mengurangkan nilai kemarahan mereka dan memulihkan hantu, beralih ke bentuk kebangkitan, julat serangan menjadi seluruh badan dan memiliki api ghaib.',
		simDesc = 'The fallen queen awakens from the abyss, then summons the entrance to the inverted world to吸引 the enemy\'s top units into it, reducing their anger value and restoring the phantom, shifting into an awakened form with an attack range encompassing the entire body and possessing spectral flames.',
		starEffect = __data_t__starEffect[23913],
		-- {11}
		starEffectDesc_vn = 'Tuyệt kỹ của hình thái thức tỉnh đảo ngược toàn bộ thế giới trong 3 lượt: Giảm 15% tốc độ hồi nộ của toàn bộ địch; Tăng số lượt duy trì hình thái thức tỉnh thêm 1 và tăng hồi nộ khi tấn công trong hình thái thức tỉnh từ 0 lên 40%.',
		starEffectDesc = 'Ultimate technique of the awakening form reverses the entire world for 3 turns: Reduces all enemies\' rage recovery speed by 15%; Increases the duration of the awakening form by 1 turn and raises rage recovery on attack in the awakening form from 0 to 40%.',
		starEffectDesc_en = 'Ultimate technique of the awakening form reverses the entire world for 3 turns: Reduces all enemies\' rage recovery speed by 15%; Increases the duration of the awakening form by 1 turn and raises rage recovery on attack in the awakening form from 0 to 40%.',
		starEffectDesc_th = 'เทคนิคขั้นสูงของรูปแบบการตื่นรู้กลับโลกทั้งหมดใน 3 เทิร์น: ลดความเร็วการฟื้นฟูความโกรธของศัตรูทั้งหมดลง 15%; เพิ่มจำนวนเทิร์นของรูปแบบการตื่นรู้ขึ้นอีก 1 เทิร์น และเพิ่มการฟื้นฟูความโกรธเมื่อโจมตีในรูปแบบการตื่นรู้จาก 0 เป็น 40%',
		starEffectDesc_in = 'Teknik pamungkas dari bentuk kebangkitan yang membalikkan seluruh dunia selama 3 giliran: Mengurangi kecepatan pemulihan kemarahan semua musuh sebesar 15%; Menambah durasi bentuk kebangkitan sebanyak 1 giliran dan meningkatkan pemulihan kemarahan saat menyerang dalam bentuk kebangkitan dari 0 menjadi 40%.',
		starEffectDesc_ph = 'Kakaibang teknik ng anyo ng paggising na nagpapabaliktad ng buong mundo sa loob ng 3 turn: Binabawasan ang bilis ng pag-recover ng galit ng lahat ng kalaban ng 15%; Pinapataas ang bilang ng mga turn ng pananatili ng anyo ng paggising ng 1 at pinapataas ang pag-recover ng galit kapag umaatake sa anyo ng paggising mula 0 hanggang 40%.',
		starEffectDesc_ma = 'Teknik utama bentuk kebangkitan yang membalikkan seluruh dunia selama 3 giliran: Mengurangkan kelajuan pemulihan kemarahan semua musuh sebanyak 15%; Menambah tempoh bentuk kebangkitan sebanyak 1 giliran dan meningkatkan pemulihan kemarahan ketika menyerang dalam bentuk kebangkitan daripada 0 kepada 40%.',
		zawakeEffect = __data_t__zawakeEffect[23913],
		-- {79003, 1}
		zawakeEffectDesc = 'Special awakening technique that shakes the whole world in 3 rounds: reduces 15% anger recovery speed of all enemies and randomly swaps the front and back rows of enemies. It is limited to once per entire field; awakening duration is +1 and anger recovery on attack during awakening increases from 0 to 40%.',
		zawakeEffectDesc_en = 'Special awakening technique that shakes the whole world in 3 rounds: reduces 15% anger recovery speed of all enemies and randomly swaps the front and back rows of enemies. It is limited to once per entire field; awakening duration is +1 and anger recovery on attack during awakening increases from 0 to 40%.',
		zawakeEffectDesc_th = 'เทคนิคพิเศษของการปลุกพลังที่ทำให้ทั้งโลกสั่นสะเทือนใน 3 รอบ: ลดความเร็วการฟื้นฟูความโกรธของศัตรูทั้งหมดลง 15% และสลับตำแหน่งแถวหน้าและแถวหลังของศัตรูแบบสุ่ม จำกัดใช้ได้ครั้งเดียวตลอดสนาม; ระยะเวลาการปลุกพลังเพิ่มขึ้น +1 และการฟื้นฟูความโกรธเมื่อโจมตีในสถานะปลุกพลังเพิ่มจาก 0 เป็น 40%.',
		zawakeEffectDesc_in = 'Teknik khusus kebangkitan yang mengguncang seluruh dunia dalam 3 giliran: mengurangi kecepatan pemulihan kemarahan semua musuh sebesar 15% dan menukar secara acak posisi baris depan dan belakang musuh. Ini dibatasi sekali untuk seluruh medan; durasi kebangkitan +1 dan pemulihan kemarahan saat menyerang dalam keadaan kebangkitan meningkat dari 0 menjadi 40%.',
		zawakeEffectDesc_ph = 'Espesyal na teknik ng paggising na nagpapailog sa buong mundo sa 3 rounds: nagbabawas ng 15% sa bilis ng pagbawi ng galit ng lahat ng kaaway at random na pinapalitan ang pwesto ng mga nasa harap at likod na gwapo ng kaaway. Limitado ito nang isang beses sa buong field; ang tagal ng paggising ay +1 at ang pagbawi ng galit kapag umaatake sa paggising ay nadagdagan mula 0 hanggang 40%.',
		zawakeEffectDesc_ma = 'Teknik kebangkitan istimewa yang menggoncang seluruh dunia dalam 3 pusingan: mengurangkan 15% kelajuan pemulihan kemarahan semua musuh dan menukar secara rawak kedudukan barisan depan dan belakang musuh. Ia terhad kepada sekali sahaja untuk keseluruhan bidang; tempoh kebangkitan adalah +1 dan pemulihan kemarahan ketika menyerang semasa kebangkitan meningkat daripada 0 kepada 40%.',
		zawakeEffectDesc_vn = 'Tuyệt chiêu đặc biệt của dạng thức tỉnh khiến cả thế giới đảo lộn trong 3 hiệp: giảm 15% tốc độ hồi phục cơn giận của tất cả kẻ thù và hoán đổi ngẫu nhiên vị trí của hàng trước và hàng sau của kẻ thù. Nó được giới hạn một lần trong toàn bộ lĩnh vực; thời gian của dạng thức tỉnh là +1 và khả năng hồi phục cơn giận khi tấn công ở dạng thức tỉnh được tăng từ 0 lên 40%.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#World Reversal effect randomly swaps enemy front and back row positions once per game.',
		zawakeSimpleDesc_en = '#C0x5c9970#World Reversal effect randomly swaps enemy front and back row positions once per game.',
		zawakeSimpleDesc_th = '#C0x5c9970#เอฟเฟกต์พลิกโลกจะสลับตำแหน่งด้านหน้าและด้านหลังของศัตรูแบบสุ่มได้หนึ่งครั้งตลอดเกม',
		zawakeSimpleDesc_in = '#C0x5c9970#Efek Pembalikan Dunia secara acak menukar posisi depan dan belakang musuh satu kali per permainan.',
		zawakeSimpleDesc_ph = '#C0x5c9970#Ang epekto ng World Reversal ay random na nagpapalit ng posisyon ng front at back row ng kalaban isang beses sa buong laro.',
		zawakeSimpleDesc_ma = '#C0x5c9970#Kesan World Reversal secara rawak menukar posisi barisan hadapan dan belakang musuh sekali dalam satu permainan.',
		zawakeSimpleDesc_vn = '#C0x5c9970# Hiệu ứng đảo ngược thế giới đi kèm với việc hoán đổi ngẫu nhiên vị trí hàng trước và hàng sau của kẻ địch và được giới hạn một lần trong toàn bộ trò chơi.',
