	},
	[23921] = {
		id = 23921,
		skillName_vn = 'Huyết Quỷ Thuật: Trướng Đới',
		skillName_en = 'Blood Demon Technique: Veil of the Zone',
		skillName_th = 'เทคนิคปีศาจเลือด: ผ้าคลุมแห่งโซน',
		skillName_in = 'Teknik Iblis Darah: Selubung Zona',
		skillName_ph = 'Blood Demon Technique: Tabing ng Zone',
		skillName_ma = 'Teknik Iblis Darah: Selubung Zon',
		skillName = 'Blood Demon Technique: Veil of the Zone',
		describe_vn = 'Công chúa sa ngã đập đất triệu hồi một cơn gió lạ tấn công một mục tiêu địch, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, tăng gấp đôi phòng thủ của cô ấy lên 50% trong 2 lượt và nhận được 1 điểm ma sau đòn tấn công.',
		describe_en = 'The fallen princess slams the ground to summon a strange wind that attacks an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Physical Damage#C0x5B545B#, doubles her defense to 50% for 2 turns and gains 1 chakra point after the attack.',
		describe_th = 'เจ้าหญิงผู้ตกต่ำกระแทกพื้นเพื่อเรียกลมแปลกๆโจมตียุทธเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#100%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มการป้องกันของเธอเป็นสองเท่าเป็น 50% เป็นเวลา 2 เทิร์น และได้รับ 1 คะแนนมาคมหลังจากการโจมตี',
		describe_in = 'Putri yang jatuh menghantam tanah memanggil angin aneh yang menyerang satu target musuh, memberikan #C0xE69900#100% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerusakan Fisik#C0x5B545B#, menggandakan pertahanannya menjadi 50% selama 2 giliran dan mendapatkan 1 poin chakra setelah serangan.',
		describe_ph = 'Ang bumagsak na prinsesa ay tinapakan ang lupa upang tawagin ang isang kakaibang hangin na umatake sa isang kalaban na target, na nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Pisikal na Pinsala#C0x5B545B#, pinararami ang kanyang depensa ng dalawang beses hanggang 50% sa loob ng 2 turn at nakakakuha ng 1 chakra point pagkatapos ng atake.',
		describe_ma = 'Puteri yang jatuh menghentak tanah memanggil angin aneh yang menyerang satu sasaran musuh, memberikan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerosakan Fizikal#C0x5B545B#, menggandakan pertahanannya kepada 50% selama 2 pusingan dan menerima 1 mata chakra selepas serangan.',
		describe = 'The fallen princess slams the ground to summon a strange wind that attacks an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Physical Damage#C0x5B545B#, doubles her defense to 50% for 2 turns and gains 1 chakra point after the attack.',
		simDesc_vn = 'Công chúa sa ngã đập đất triệu hồi một cơn gió lạ tấn công một mục tiêu địch, gây sát thương vật lý, tăng khả năng giảm sát thương của bản thân và phục hồi bóng ma.',
		simDesc_en = 'The fallen princess slams the ground, summoning a strange wind to attack an enemy target, dealing physical damage, increasing her own damage reduction, and restoring her shadow.',
		simDesc_th = 'เจ้าหญิงผู้ล่วงลับทุบพื้นเรียกลมแปลกโจมตีเป้าหมายศัตรู ก่อให้เกิดความเสียหายทางกายภาพ เพิ่มความสามารถในการลดความเสียหายของตัวเอง และฟื้นฟูเงา',
		simDesc_in = 'Putri yang jatuh menghantam tanah memanggil angin aneh untuk menyerang target musuh, menyebabkan kerusakan fisik, meningkatkan kemampuan pengurangan kerusakan sendiri, dan memulihkan bayangan.',
		simDesc_ph = 'Ang bumagsak na prinsesa ay yumapak sa lupa at nagtawag ng kakaibang hangin upang atakihin ang isang kaaway na target, nagdudulot ng pisikal na pinsala, pinapataas ang kanyang kakayahan sa pagbawas ng pinsala, at nagpapagaling ng kanyang anino.',
		simDesc_ma = 'Puteri yang jatuh memukul tanah dan memanggil angin aneh untuk menyerang sasaran musuh, menyebabkan kerosakan fizikal, meningkatkan keupayaan pengurangan kerosakannya sendiri, dan memulihkan bayangannya.',
		simDesc = 'The fallen princess slams the ground, summoning a strange wind to attack an enemy target, dealing physical damage, increasing her own damage reduction, and restoring her shadow.',
		zawakeEffect = __data_t__zawakeEffect[23921],
		-- {79001}
		zawakeEffectDesc = 'The fallen princess slams the ground to summon a strange wind that attacks an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Physical Damage#C0x5B545B#. It increases its own double defense by 50% for 2 turns and resistance rate by 15% for 2 turns. After attacking, it gains 1 mana point.',
		zawakeEffectDesc_en = 'The fallen princess slams the ground to summon a strange wind that attacks an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Physical Damage#C0x5B545B#. It increases its own double defense by 50% for 2 turns and resistance rate by 15% for 2 turns. After attacking, it gains 1 mana point.',
		zawakeEffectDesc_th = 'เจ้าหญิงผู้ล่มสลายทุบพื้นเพื่อเรียกลมประหลาดโจมตีเป้าหมายศัตรูหนึ่งตัว สร้าง #C0xE69900#100% ความเสียหายกายภาพ#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B#. มันเพิ่มการป้องกันสองเท่าของตัวเองอีก 50% เป็นเวลา 2 เทิร์น และอัตราการต้านทานเพิ่มขึ้น 15% ใน 2 เทิร์น หลังจากโจมตี มันได้รับ 1 คะแนนมานา',
		zawakeEffectDesc_in = 'Putri yang jatuh menghantam tanah memanggil angin aneh yang menyerang satu target musuh, menyebabkan #C0xE69900#100% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerusakan Fisik#C0x5B545B#. Ini meningkatkan pertahanan ganda dirinya sendiri sebesar 50% selama 2 giliran dan tingkat resistensi sebesar 15% selama 2 giliran. Setelah menyerang, ia memperoleh 1 poin mana.',
		zawakeEffectDesc_ph = 'Ang bumagsak na prinsesa ay tumama sa lupa upang tawagin ang kakaibang hangin na umatake sa isang kaaway na target, nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Pinapataas nito ang sariling dobleng depensa ng 50% sa loob ng 2 turn at ang rate ng resistensya ng 15% sa loob ng 2 turn. Pagkatapos umatake, nakakakuha ito ng 1 punto ng mana.',
		zawakeEffectDesc_ma = 'Puteri yang jatuh memukul tanah untuk memanggil angin aneh yang menyerang satu sasaran musuh, menyebabkan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Ia meningkatkan pertahanannya sendiri dua kali ganda sebanyak 50% selama 2 pusingan dan kadar ketahanan sebanyak 15% selama 2 pusingan. Selepas menyerang, ia menerima 1 mata mana.',
		zawakeEffectDesc_vn = 'Công chúa sa ngã đập đất triệu hồi một cơn gió lạ tấn công một mục tiêu địch, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B#. Nó tăng khả năng phòng thủ gấp đôi của chính mình thêm 50% trong 2 lượt và tỷ lệ kháng cự thêm 15% trong 2 lượt. Sau khi tấn công, nó nhận được 1 điểm ma.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increase own double defense by 50% for 2 turns\n#F20# \n#F40##C0x5c9970#→ Increase own double defense by 50% for 2 turns and 15% resistance rate for 2 turns',
		zawakeSimpleDesc_en = 'Increase own double defense by 50% for 2 turns\n#F20# \n#F40##C0x5c9970#→ Increase own double defense by 50% for 2 turns and 15% resistance rate for 2 turns',
		zawakeSimpleDesc_th = 'เพิ่มพลังป้องกันคู่ของตัวเอง 50% เป็นเวลา 2 เทิร์น\n#F20# \n#F40##C0x5c9970#→ เพิ่มพลังป้องกันคู่ของตัวเอง 50% เป็นเวลา 2 เทิร์น และเพิ่มอัตราต้านทาน 15% เป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Meningkatkan pertahanan ganda sendiri sebesar 50% selama 2 giliran\n#F20# \n#F40##C0x5c9970#→ Meningkatkan pertahanan ganda sendiri sebesar 50% selama 2 giliran dan 15% resistensi selama 2 giliran',
		zawakeSimpleDesc_ph = 'Dagdagan ng 50% ang double defense ng sarili sa loob ng 2 turn\n#F20# \n#F40##C0x5c9970#→ Dagdagan ng 50% ang double defense ng sarili sa loob ng 2 turn at 15% resistance sa loob ng 2 turn',
		zawakeSimpleDesc_ma = 'Tingkatkan pertahanan berganda diri sebanyak 50% selama 2 pusingan\n#F20# \n#F40##C0x5c9970#→ Tingkatkan pertahanan berganda diri sebanyak 50% selama 2 pusingan dan kadar ketahanan sebanyak 15% selama 2 pusingan',
		zawakeSimpleDesc_vn = 'Tăng 50% phòng thủ đôi của bản thân trong 2 lượt\n#F20# \n#F40##C0x5c9970#→ Tăng 50% phòng thủ đôi của bản thân trong 2 lượt và 15% tỷ lệ chống chịu trong 2 lượt',
		upLvDesc = 'Fixed damage +96',
		upLvDesc_en = 'Fixed damage +96',
