	[23922] = {
		id = 23922,
		skillName_vn = 'Huyết Quỷ Thuật: U Minh Hỏa',
		skillName_en = 'Blood Demon Art: Nether Flame',
		skillName_th = 'ศิลปะปีศาจเลือด: เปลวไฟเนเทอร์',
		skillName_in = 'Seni Iblis Darah: Nyala Neraka',
		skillName_ph = 'Sining ng Demon ng Dugo: Apoy ng Impiyerno',
		skillName_ma = 'Seni Iblis Darah: Api Neraka',
		skillName = 'Blood Demon Art: Nether Flame',
		describe_vn = 'Công chúa sa ngã biến thành ma và di chuyển đến một mục tiêu địch để đánh lén, gây #C0xE69900#170% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, tăng mức giảm sát thương cho cột của cô ấy thêm 15% trong 2 lượt và nhận được 2 điểm ma sau tấn công\n#F20# \n#F40#[#L10#Awakening Form#L0#], phạm vi tấn công thay đổi theo hàng và có thêm 80% xác suất [#L10#Ghost Fire#L0#] trong 2 lượt\n[#L10#Ghost Ghost Fire#L0#]: Hiệu ứng tiêu cực đặc biệt, chỉ có thể xua tan và không thể chồng lên. Trước khi mục tiêu di chuyển hoặc khi lửa ma bị xua tan, máu của mục tiêu sẽ bị giảm (12% giới hạn trên của lượng máu của nữ hoàng đã ngã xuống, sát thương là sát thương thực sự) và 120 điểm thịnh nộ.',
		describe_en = 'The fallen princess transforms into a ghost and moves to an enemy target to strike stealthily, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, increasing her column\'s damage reduction by 15% for 2 turns and gaining 2 ghost points after the attack\n#F20# \n#F40#[#L10#Awakening Form#L0#], attack range changes by row and gains an 80% chance of [#L10#Ghost Fire#L0#] for 2 turns\n[#L10#Ghost Ghost Fire#L0#]: A special negative effect that can only be dispelled but not stacked. Before the target moves or when the ghost fire is dispelled, the target\'s HP is reduced (12% of the upper limit of the fallen queen\'s HP, damage is true damage) and 120 rage points are gained.',
		describe_th = 'เจ้าหญิงผู้ล้มลงกลายเป็นผีสิงและเคลื่อนที่ไปยังเป้าหมายศัตรูเพื่อจู่โจมอย่างลับๆ สร้างความเสียหายทางกายภาพ #C0xE69900#170%#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มการลดความเสียหายของคอลัมน์เธอขึ้นอีก 15% เป็นเวลา 2 เทิร์นและได้รับ 2 คะแนนผีหลังการโจมตี\n#F20# \n#F40#[#L10#Awakening Form#L0#] ขอบเขตการโจมตีเปลี่ยนแปลงตามแถวและได้รับโอกาส 80% ของ [#L10#Ghost Fire#L0#] เป็นเวลา 2 เทิร์น\n[#L10#Ghost Ghost Fire#L0#]: เอฟเฟกต์ลบพิเศษ ฉายาเพียงสามารถขจัดได้และไม่สามารถทับซ้อนได้ ก่อนที่เป้าหมายจะเคลื่อนที่หรือเมื่อเปลวไฟผีถูกขจัด HP ของเป้าหมายจะถูกลดลง (12% ของขีดจำกัดบนของ HP ของราชินีผู้ล้มลง ความเสียหายเป็นความเสียหายจริง) และได้รับ 120 แต้มความโกรธ',
		describe_in = 'Putri yang jatuh berubah menjadi hantu dan bergerak ke target musuh untuk menyerang diam-diam, memberikan #C0xE69900#170% Damage Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Damage Fisik#C0x5B545B#, meningkatkan pengurangan damage pada kolomnya sebesar 15% selama 2 giliran dan mendapatkan 2 poin hantu setelah serangan\n#F20# \n#F40#[#L10#Awakening Form#L0#], jangkauan serangan berubah sesuai baris dan mendapatkan peluang 80% [#L10#Ghost Fire#L0#] selama 2 giliran\n[#L10#Ghost Ghost Fire#L0#]: Efek negatif khusus, hanya dapat dihapus dan tidak dapat ditumpuk. Sebelum target bergerak atau ketika api hantu dihapus, HP target akan berkurang (12% dari batas atas HP ratu yang jatuh, damage adalah damage nyata) dan mendapatkan 120 poin kemarahan.',
		describe_ph = 'Ang prinsesang bumagsak ay nagiging multo at lumilipat sa isang kalabang target upang umatake nang palihim, na nagdudulot ng #C0xE69900#170% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, tumataas ang pagbawas ng pinsala sa kanyang kolum ng 15% sa loob ng 2 turn at nakakakuha ng 2 puntos ng multo pagkatapos ng pag-atake\n#F20# \n#F40#[#L10#Awakening Form#L0#], nagbabago ang saklaw ng pag-atake ayon sa hanay at may 80% tsansa ng [#L10#Ghost Fire#L0#] sa loob ng 2 turn\n[#L10#Ghost Ghost Fire#L0#]: Isang espesyal na negatibong epekto, maaari lamang itong mawala at hindi maaaring pagsamahin. Bago gumalaw ang target o kapag nawala ang apoy ng multo, mababawasan ang HP ng target (12% ng pinakamataas na limitasyon ng HP ng bumagsak na reyna, ang pinsala ay totoong pinsala) at makakakuha ng 120 puntos ng galit.',
		describe_ma = 'Puteri yang gugur berubah menjadi hantu dan bergerak ke sasaran musuh untuk menyerang secara senyap, memberikan #C0xE69900#170% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, meningkatkan tahap pengurangan kerosakan bagi lajur dia sebanyak 15% selama 2 giliran dan menerima 2 mata hantu selepas serangan\n#F20# \n#F40#[#L10#Awakening Form#L0#], julat serangan berubah mengikut baris dan mendapat 80% kemungkinan [#L10#Ghost Fire#L0#] selama 2 giliran\n[#L10#Ghost Ghost Fire#L0#]: Kesan negatif khas, hanya boleh dibuang dan tidak boleh bertindih. Sebelum sasaran bergerak atau apabila api hantu dibuang, darah sasaran akan dikurangkan (12% had atas darah ratu yang gugur, kerosakan adalah kerosakan sebenar) dan 120 mata kemarahan.',
		describe = 'The fallen princess transforms into a ghost and moves to an enemy target to strike stealthily, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, increasing her column\'s damage reduction by 15% for 2 turns and gaining 2 ghost points after the attack\n#F20# \n#F40#[#L10#Awakening Form#L0#], attack range changes by row and gains an 80% chance of [#L10#Ghost Fire#L0#] for 2 turns\n[#L10#Ghost Ghost Fire#L0#]: A special negative effect that can only be dispelled but not stacked. Before the target moves or when the ghost fire is dispelled, the target\'s HP is reduced (12% of the upper limit of the fallen queen\'s HP, damage is true damage) and 120 rage points are gained.',
		simDesc_vn = 'Công chúa sa ngã biến thành một bóng ma và di chuyển đến một mục tiêu kẻ thù để đánh lén, gây sát thương vật lý, tăng cơn thịnh nộ tối đa của mục tiêu và nhận điểm ma cho bản thân; ở dạng thức tỉnh, phạm vi tấn công thay đổi thành một hàng, có khả năng thêm lửa ma.',
		simDesc_en = 'The fallen princess transforms into a phantom and moves to an enemy target to launch a sneak attack, dealing physical damage, maxing out the target\'s rage, and gaining ghost points for herself; in awakened form, the attack range changes to a row with the ability to add ghost fire.',
		simDesc_th = 'เจ้าหญิงผู้ล่มสลายเปลี่ยนร่างเป็นเงาผีและเคลื่อนที่ไปยังเป้าหมายศัตรูเพื่อโจมตีแบบลอบโจมตี สร้างความเสียหายกายภาพ เพิ่มความโกรธสูงสุดของเป้าหมายและได้รับคะแนนผีสำหรับตัวเอง; ในสภาพตื่นรู้ ระยะโจมตีเปลี่ยนเป็นแนวแถว พร้อมความสามารถในการเพิ่มไฟผี',
		simDesc_in = 'Putri yang jatuh berubah menjadi hantu dan bergerak ke target musuh untuk melakukan serangan mendadak, memberikan kerusakan fisik, meningkatkan amarah maksimum target, dan mendapatkan poin hantu untuk dirinya sendiri; dalam bentuk terbangun, jangkauan serangan berubah menjadi satu baris dengan kemampuan menambahkan api hantu.',
		simDesc_ph = 'Ang bumagsak na prinsesa ay nagiging isang anino at lumilipat sa isang kaaway na target upang maglunsad ng palihim na pag-atake, na nagdudulot ng pisikal na pinsala, pinapataas ang pinakamataas na galit ng target, at nakakakuha ng ghost points para sa sarili; sa pinarousing na anyo, ang saklaw ng pag-atake ay nagbabago sa isang hanay na may kakayahang magdagdag ng apoy ng multo.',
		simDesc_ma = 'Puteri yang jatuh berubah menjadi hantu dan bergerak ke sasaran musuh untuk melancarkan serangan mengejutkan, memberikan kerosakan fizikal, meningkatkan kemarahan maksimum sasaran dan memperoleh mata hantu untuk dirinya sendiri; dalam bentuk bangun, julat serangan berubah menjadi satu baris dengan keupayaan menambah api hantu.',
		simDesc = 'The fallen princess transforms into a phantom and moves to an enemy target to launch a sneak attack, dealing physical damage, maxing out the target\'s rage, and gaining ghost points for herself; in awakened form, the attack range changes to a row with the ability to add ghost fire.',
		zawakeEffect = __data_t__zawakeEffect[23922],
		-- {79002}
		zawakeEffectDesc = 'The fallen princess transforms into a demon and moves to an enemy target to ambush, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage#C0x5B545B#, increasing her column\'s damage reduction by 20% for 2 turns and gaining 2 demon points after attacking\n#F20# \n#F40#<#L10#Awakening Form#L0#>, attack range changes by row and adds an 80% chance of <#L10#Ghost Fire#L0#> for 2 turns and adds <#L10#Ghost Shield#L0> to your demon-type dark hero. #>\n<#L10#鬼火#L0#>: Special negative effect, can only be dispelled and cannot stack. Before the target moves or when Ghost Fire is dispelled, the target’s HP is reduced (12% of the fallen queen\'s max HP, damage is true damage) and 120 rage points.',
		zawakeEffectDesc_en = 'The fallen princess transforms into a demon and moves to an enemy target to ambush, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage#C0x5B545B#, increasing her column\'s damage reduction by 20% for 2 turns and gaining 2 demon points after attacking\n#F20# \n#F40#<#L10#Awakening Form#L0#>, attack range changes by row and adds an 80% chance of <#L10#Ghost Fire#L0#> for 2 turns and adds <#L10#Ghost Shield#L0> to your demon-type dark hero. #>\n<#L10#鬼火#L0#>: Special negative effect, can only be dispelled and cannot stack. Before the target moves or when Ghost Fire is dispelled, the target’s HP is reduced (12% of the fallen queen\'s max HP, damage is true damage) and 120 rage points.',
		zawakeEffectDesc_th = 'เจ้าหญิงผู้ล้มลงแปลงร่างเป็นปีศาจและเคลื่อนที่ไปยังเป้าหมายศัตรูเพื่อโจมตีอย่างลอบเร้น ทำให้เกิด #C0xE69900#170% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ ของ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มความสามารถในการลดความเสียหายของแถวที่เธออยู่ขึ้นอีก 20% เป็นเวลา 2 รอบ และได้รับ 2 แต้มปีศาจหลังการโจมตี\n#F20# \n#F40#<#L10#รูปแบบการตื่นรู้#L0#>, ระยะโจมตีเปลี่ยนตามแถว และเพิ่มโอกาส 80% ของ <#L10#ไฟผี#L0#> เป็นเวลา 2 รอบ พร้อมทั้งเพิ่ม <#L10#โล่ผี#L0> ให้กับฮีโร่แห่งความมืดประเภทปีศาจของคุณ #>\n<#L10#鬼火#L0#>: เอฟเฟกต์ลบพิเศษ สามารถลบได้เท่านั้นและไม่สามารถซ้อนทับ ก่อนที่เป้าหมายจะเคลื่อนที่หรือเมื่อไฟผีถูกลบ ชีวิตของเป้าหมายจะลดลง (12% ของพลังชีวิตสูงสุดของราชินีผู้ล้มลง ความเสียหายเป็นความเสียหายจริง) และเพิ่มความโกรธ 120 คะแนน',
		zawakeEffectDesc_in = 'Putri yang jatuh berubah menjadi iblis dan bergerak ke target musuh untuk menyerang secara diam-diam, menyebabkan #C0xE69900#170% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54# Kerusakan Fisik#C0x5B545B#, meningkatkan pengurangan kerusakan pada kolomnya sebesar 20% selama 2 giliran dan memperoleh 2 poin iblis setelah menyerang\n#F20# \n#F40#<#L10#Bentuk Kebangkitan#L0#>, jangkauan serangan berubah menurut baris dan menambahkan peluang 80% <#L10#Api Hantu#L0#> selama 2 giliran serta menambahkan <#L10#Perisai Hantu#L0> kepada pahlawan gelap tipe iblis Anda. #>\n<#L10#鬼火#L0#>: Efek negatif khusus, hanya bisa dihapus dan tidak bisa ditumpuk. Sebelum target bergerak atau saat Api Hantu dihapus, HP target akan berkurang (12% batas atas HP ratu yang jatuh, kerusakan adalah kerusakan asli) dan 120 poin kemarahan.',
		zawakeEffectDesc_ph = 'Ang prinsesa na bumagsak ay nagiging demonyo at lumilipat sa isang kalabang target para maniktik, na nagdudulot ng #C0xE69900#170% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$ ng #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, pinalalaki ang kakayahan ng kanyang hanay na bawasan ang pinsala ng 20% sa loob ng 2 mga turn at nakakakuha ng 2 puntos ng demonyo pagkatapos umatake\n#F20# \n#F40#<#L10#Anyong Paggising#L0#>, nagbabago ang hanay ng atake ayon sa linya at may karagdagang 80% tsansa ng <#L10#Apoy ng Multo#L0#> sa loob ng 2 mga turn at nadaragdagan ang <#L10#Kalasag ng Multo#L0> sa iyong madilim na bayaning uri demonyo. #>\n<#L10#鬼火#L0#>: Espesyal na negatibong epekto, maaari lamang matanggal at hindi pwedeng mag-stack. Bago gumalaw ang target o kapag na-disperse ang Apoy ng Multo, nababawasan ang HP ng target (12% ng maximum HP ng bumagsak na reyna, ang pinsala ay totoong pinsala) at 120 puntos ng pagkagalit.',
		zawakeEffectDesc_ma = 'Puteri yang jatuh berubah menjadi hantu dan bergerak ke sasaran musuh untuk menyerang secara sembunyi-sembunyi, menyebabkan #C0xE69900#170% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ Kerosakan Fizikal#C0x5B545B# pada kolumnya, meningkatkan pengurangan kerosakan kolumnya sebanyak 20% selama 2 giliran dan menerima 2 mata hantu selepas menyerang\n#F20# \n#F40#<#L10#Bentuk Kebangkitan#L0#>, julat serangan berubah mengikut baris dan menambah 80% peluang <#L10#Api Hantu#L0#> selama 2 giliran serta menambah <#L10#Perisai Hantu#L0> kepada wira kegelapan jenis hantu anda. #>\n<#L10#鬼火#L0#>: Kesan negatif khas, hanya boleh dipadamkan dan tidak boleh bertindih. Sebelum sasaran bergerak atau apabila Api Hantu dipadamkan, HP sasaran akan berkurangan (12% had atas HP ratu yang jatuh, kerosakan adalah kerosakan sebenar) dan 120 mata kemarahan.',
		zawakeEffectDesc_vn = 'Công chúa sa ngã biến thành ma và di chuyển đến một mục tiêu địch để đánh lén, gây #C0xE69900#170% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ của #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, tăng khả năng giảm sát thương cho cột của cô ấy thêm 20% trong 2 lượt và nhận được 2 điểm ma sau tấn công\n#F20# \n#F40#<#L10#Awakening Form#L0#>, phạm vi tấn công thay đổi theo hàng và có thêm 80% xác suất <#L10#Ghost Fire#L0#> trong 2 lượt và thêm <#L10#Ghost Shield#L0> cho anh hùng bóng tối loại ma của riêng bạn. #>\n<#L10#鬼火#L0#>: Hiệu ứng tiêu cực đặc biệt, chỉ có thể xua tan và không thể chồng chất. Trước khi mục tiêu di chuyển hoặc khi lửa ma bị xua tan, máu của mục tiêu sẽ bị giảm (12% giới hạn trên của lượng máu của nữ hoàng đã ngã xuống, sát thương là sát thương thực sự) và 120 điểm thịnh nộ.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increase your column’s damage reduction by 15% for 2 turns\n#F20# \n#F40##C0x5c9970#→Increase your column’s damage reduction by 20% for 2 turns\n<#L10#Awakening Form#L0#> Adds <#L10#Ghost Shield#L0#> to your ghosts and dark heroes.',
		zawakeSimpleDesc_en = 'Increase your column’s damage reduction by 15% for 2 turns\n#F20# \n#F40##C0x5c9970#→Increase your column’s damage reduction by 20% for 2 turns\n<#L10#Awakening Form#L0#> Adds <#L10#Ghost Shield#L0#> to your ghosts and dark heroes.',
		zawakeSimpleDesc_th = 'เพิ่มการลดความเสียหายของแถวของคุณ 15% เป็นเวลา 2 เทิร์น\n#F20# \n#F40##C0x5c9970#→เพิ่มการลดความเสียหายของแถวของคุณ 20% เป็นเวลา 2 เทิร์น\n<#L10#Awakening Form#L0#> เพิ่ม <#L10#Ghost Shield#L0#> ให้กับผีและฮีโร่ธาตุมืดของคุณ',
		zawakeSimpleDesc_in = 'Meningkatkan pengurangan damage untuk kolommu sebesar 15% selama 2 giliran\n#F20# \n#F40##C0x5c9970#→Meningkatkan pengurangan damage untuk kolommu sebesar 20% selama 2 giliran\n<#L10#Awakening Form#L0#> Menambahkan <#L10#Ghost Shield#L0#> ke hantu dan hero gelap milikmu',
		zawakeSimpleDesc_ph = 'Dagdagan ng 15% ang damage reduction ng hanay mo sa loob ng 2 turn\n#F20# \n#F40##C0x5c9970#→Dagdagan ng 20% ang damage reduction ng hanay mo sa loob ng 2 turn\n<#L10#Awakening Form#L0#> Nagdadagdag ng <#L10#Ghost Shield#L0#> sa sarili mong mga espiritu at dark heroes',
		zawakeSimpleDesc_ma = 'Tingkatkan pengurangan kerosakan untuk lajur anda sebanyak 15% selama 2 pusingan\n#F20# \n#F40##C0x5c9970#→Tingkatkan pengurangan kerosakan untuk lajur anda sebanyak 20% selama 2 pusingan\n<#L10#Awakening Form#L0#> Menambah <#L10#Ghost Shield#L0#> kepada roh dan wira gelap anda',
		zawakeSimpleDesc_vn = 'Tăng mức giảm sát thương cho cột của bạn thêm 15% trong 2 lượt\n#F20# \n#F40##C0x5c9970#→Tăng mức giảm sát thương cho cột của bạn thêm 20% trong 2 lượt\n<#L10#Awakening Form#L0#> Thêm <#L10#Ghost Shield#L0#> cho bóng ma và anh hùng bóng tối của riêng bạn.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
		upLvDesc_in = 'Kerusakan tetap +192',
