	[23923] = {
		id = 23923,
		skillName_vn = 'Huyết Quỷ Thuật: Bát Trọng Đới Trảm',
		skillName_en = 'Blood Demon Technique: Eight Layers Severing Belt',
		skillName_th = 'เทคนิคปีศาจเลือด: สายรัดตัดแปดชั้น',
		skillName_in = 'Teknik Iblis Darah: Sabuk Pemotong Delapan Lapisan',
		skillName_ph = 'Blood Demon Technique: Búhang Walong Patong na Sintas',
		skillName_ma = 'Teknik Iblis Darah: Tali Pemotong Lapan Lapisan',
		skillName = 'Blood Demon Technique: Eight Layers Severing Belt',
		describe_vn = 'Công chúa sa ngã thức dậy từ vực thẳm, sau đó triệu hồi lối vào thế giới đảo ngược, hút các đơn vị hàng đầu của kẻ địch vào đó, gây #C0xE69900#230% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, giảm cơn thịnh nộ của mục tiêu trúng đòn đi 250 điểm và nhận được 3 điểm ma sau khi tấn công\n#F20# \n#F40#Sau khi thực hiện chiêu thức đặc biệt, anh ta chuyển sang [#L10#Hình thức thức tỉnh#L0#] trong 2 hiệp. Giới hạn trên của lượng máu của chính anh ta (chỉ tăng giới hạn trên), tốc độ và tổng tỷ lệ kiểm soát được tăng thêm 50% (không thể phân tán, chuyển giao, sao chép), Chuyển sang chiêu thức đặc biệt mới (không yêu cầu cuồng nộ và không tiêu hao thịnh nộ khi giải phóng, hạ nhiệt trong 2 lượt sau khi giải phóng): Phạm vi thay đổi đối với tất cả kẻ thù và có thêm 75% xác suất thêm [#L10#鬼鬼火#L0#] của 4 anh hùng của kẻ địch có cơn thịnh nộ cao nhất trong 2 lượt.',
		describe_en = 'The fallen princess awakens from the abyss, then summons the entrance to the reversed world, drawing top enemy units into it, dealing #C0xE69900#230% Physical Damage#C0x5B545B# + $(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, reducing the target\'s rage by 250 points on hit and gaining 3 mana points after attacking\n#F20# \n#F40# After performing the special move, he switches to [#L10#Awakening Form#L0#] for 2 turns. His maximum HP (only the cap increases), speed, and total control rate increase by 50% (cannot be dispersed, transferred, or copied). Switches to a new special skill (no rage required and does not consume rage upon activation, cooldown of 2 turns after use): The range changes to all enemies and gains an additional 75% chance to apply [#L10#Demonic Flame#L0#] to the 4 enemy heroes with the highest rage for 2 turns.',
		describe_th = 'เจ้าหญิงผู้ล่มสลือตื่นขึ้นจากเหวลึก จากนั้นก็เรียกทางเข้าสู่โลกย้อนกลับ ดึงหน่วยศัตรูชั้นนำเข้าไปในนั้น สร้าง #C0xE69900#230% ความเสียหายทางกายภาพ#C0x5B545B# + $(skillLevel*4*48)$\'s #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# ลดความโกรธของเป้าหมายลง 250 หน่วยเมื่อโจมตีและได้รับ 3 หน่วยมานาหลังโจมตี\n#F20# \n#F40# หลังจากใช้ท่าพิเศษ เขาจะเปลี่ยนเป็น [#L10#รูปลักษณ์การตื่นรู้#L0#] เป็นเวลา 2 เทิร์น ขีดจำกัดสูงสุดของค่า HP ของเขา (เพิ่มเฉพาะขีดจำกัดสูงสุด), ความเร็ว และอัตราการควบคุมโดยรวมเพิ่มขึ้น 50% (ไม่สามารถแจกจ่าย โอน หรือคัดลอก) เปลี่ยนไปใช้ท่าพิเศษใหม่ (ไม่ต้องใช้ความโกรธและไม่เสียความโกรธเมื่อปล่อย ใช้เวลาคูลดาวน์ 2 เทิร์นหลังปล่อย): ขอบเขตเปลี่ยนเป็นศัตรูทั้งหมด และมีโอกาสเพิ่มขึ้น 75% ที่จะเพิ่ม [#L10#ไฟผีปีศาจ#L0#] ให้กับ 4 ฮีโร่ฝ่ายศัตรูที่มีความโกรธสูงสุดเป็นเวลา 2 เทิร์น',
		describe_in = 'Putri yang jatuh bangun dari jurang, lalu memanggil pintu masuk ke dunia terbalik, menarik unit teratas musuh ke dalamnya, memberikan #C0xE69900#230% Damage Fisik#C0x5B545B# + $(skillLevel*4*48)$\'s #C0xF13B54# Damage Fisik #C0x5B545B#, mengurangi amarah target yang terkena sebanyak 250 poin dan mendapatkan 3 poin mana setelah menyerang\n#F20# \n#F40# Setelah melakukan teknik khusus, dia beralih ke [#L10#Bentuk Kebangkitan#L0#] selama 2 giliran. Batas atas HP-nya (hanya batas atas yang meningkat), kecepatan, dan total tingkat kontrol meningkat 50% (tidak bisa didispersi, dipindahkan, atau disalin), Beralih ke teknik khusus baru (tidak memerlukan amarah dan tidak menghabiskan amarah saat dilepaskan, cooldown selama 2 giliran setelah dilepaskan): Jangkauan berubah ke semua musuh dan memiliki tambahan peluang 75% untuk menambahkan [#L10#Api Iblis#L0#] pada 4 pahlawan musuh dengan amarah tertinggi selama 2 giliran.',
		describe_ph = 'Ang bumagsak na prinsesa ay nagmulat mula sa kailaliman, pagkatapos ay tinawag ang lagusan patungo sa baliktad na mundo, hinihila ang nangungunang yunit ng kaaway doon, nagdudulot ng #C0xE69900#230% Pisikal na Pinsala#C0x5B545B# + $(skillLevel*4*48)$\'s #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, nagbabawas ng galit ng target ng 250 puntos kapag tumama at nakakakuha ng 3 puntos ng mana pagkatapos umatake\n#F20# \n#F40# Pagkatapos gawin ang espesyal na kasanayan, siya ay lumilipat sa [#L10#Anyong Pagkamulat#L0#] sa loob ng 2 turn. Ang maximum na HP niya (tumaas lang ang limitasyon), bilis, at kabuuang rate ng kontrol ay tumataas ng 50% (hindi puwedeng i-dispersion, ilipat, o kopyahin), Lumilipat sa bagong espesyal na kasanayan (hindi nangangailangan ng galit at hindi kumukonsumo ng galit sa paggamit, cooldown ng 2 turn pagkatapos gamitin): Nagbabago ang saklaw sa lahat ng kaaway at may dagdag na 75% tsansa na magdagdag ng [#L10#Aning Demonyo#L0#] sa 4 na mga bayani ng kalaban na may pinakamataas na galit sa loob ng 2 turn.',
		describe_ma = 'Puteri yang jatuh bangun dari jurang, kemudian memanggil pintu masuk ke dunia terbalik, menarik unit teratas musuh ke dalamnya, menyebabkan #C0xE69900#230% Kerosakan Fizikal#C0x5B545B# + $(skillLevel*4*48)$\'s #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, mengurangkan kemarahan sasaran sebanyak 250 mata apabila terkena dan menerima 3 mata sihir selepas menyerang\n#F20# \n#F40# Selepas menggunakan gerakan khas, dia beralih kepada [#L10#Bentuk Kebangkitan#L0#] selama 2 pusingan. Had atas jumlah darahnya (hanya had atas yang meningkat), kelajuan dan kadar kawalan keseluruhan meningkat sebanyak 50% (tidak boleh diagihkan, dipindahkan atau disalin), Beralih kepada gerakan khas baru (tidak memerlukan kemarahan dan tidak menggunakan kemarahan ketika melepaskan, sejuk selama 2 pusingan selepas melepaskan): Julat berubah kepada semua musuh dan mempunyai peluang tambahan sebanyak 75% untuk menambah [#L10#Api Hantu#L0#] pada 4 wira musuh dengan kemarahan tertinggi selama 2 pusingan.',
		describe = 'The fallen princess awakens from the abyss, then summons the entrance to the reversed world, drawing top enemy units into it, dealing #C0xE69900#230% Physical Damage#C0x5B545B# + $(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, reducing the target\'s rage by 250 points on hit and gaining 3 mana points after attacking\n#F20# \n#F40# After performing the special move, he switches to [#L10#Awakening Form#L0#] for 2 turns. His maximum HP (only the cap increases), speed, and total control rate increase by 50% (cannot be dispersed, transferred, or copied). Switches to a new special skill (no rage required and does not consume rage upon activation, cooldown of 2 turns after use): The range changes to all enemies and gains an additional 75% chance to apply [#L10#Demonic Flame#L0#] to the 4 enemy heroes with the highest rage for 2 turns.',
		simDesc_vn = 'Nữ hoàng sa ngã tỉnh dậy từ vực thẳm, sau đó triệu hồi lối vào thế giới ngược để hút các đơn vị hàng đầu của kẻ địch vào đó, giảm giá trị tức giận của chúng và phục hồi bóng ma, chuyển sang dạng thức tỉnh, phạm vi tấn công trở thành toàn bộ cơ thể và có lửa ma.',
		simDesc_en = 'The fallen queen awakens from the abyss, then summons the entrance to the reverse world to absorb the enemy\'s top units, reducing their fury value and restoring the phantom. She shifts into an awakened form, with her attack range becoming her entire body, engulfed in demonic flames.',
		simDesc_th = 'ราชินีผู้ล่วงหลับฟื้นขึ้นจากห้วงลึก จากนั้นเรียกทางเข้าสู่โลกย้อนกลับเพื่อดูดซับหน่วยชั้นนำของศัตรู ลดค่าความโกรธของพวกเขาและฟื้นฟูปิศาจเงา เปลี่ยนรูปร่างเป็นการตื่นรู้ ช่วงการโจมตีครอบคลุมร่างกายทั้งหมดและมีไฟปีศาจ',
		simDesc_in = 'Ratu yang terjatuh terbangun dari jurang, lalu memanggil pintu masuk ke dunia terbalik untuk menyedot unit teratas musuh, mengurangi nilai amarah mereka dan mengembalikan bayangan hantu. Dia beralih ke bentuk terbangun, dengan jangkauan serangan menjadi seluruh tubuhnya dan memiliki api iblis.',
		simDesc_ph = 'Ang bumagsak na reina ay nagising mula sa kailaliman, pagkatapos ay tumawag ng pasukan sa mundo ng baligtad upang sumipsip ng mga nangungunang yunit ng kalaban, binabawasan ang kanilang halaga ng galit at pinapagaling ang anino. Nagbabago siya sa anyong nagigising, na ang saklaw ng pag-atake ay ang buong katawan at may apoy na demonyo.',
		simDesc_ma = 'Ratu yang jatuh bangkit dari gaung, kemudian memanggil pintu masuk ke dunia terbalik untuk menyedut unit teratas musuh, mengurangkan nilai kemarahan mereka dan memulihkan bayang hantu. Dia berubah ke bentuk terbangun, dengan julat serangan menjadi seluruh tubuh dan mempunyai api syaitan.',
		simDesc = 'The fallen queen awakens from the abyss, then summons the entrance to the reverse world to absorb the enemy\'s top units, reducing their fury value and restoring the phantom. She shifts into an awakened form, with her attack range becoming her entire body, engulfed in demonic flames.',
		starEffect = __data_t__starEffect[23923],
		-- {11}
		starEffectDesc_vn = 'Tuyệt kỹ dạng thức thức tỉnh đảo ngược toàn bộ thế giới trong 3 hiệp: Giảm 15% tốc độ hồi nộ của toàn bộ địch; Tăng số hiệp duy trì dạng thức thức tỉnh thêm 1 và tăng hồi nộ khi tấn công trong dạng thức thức tỉnh từ 0 lên 40%.',
		starEffectDesc = 'Ultimate Form Awakening technique that reverses the entire world in 3 rounds: Reduces all enemies\' rage recovery speed by 15%; Increases the number of rounds maintaining the awakening form by 1 and increases rage recovery when attacking in awakening form from 0 to 40%.',
		starEffectDesc_en = 'Ultimate Form Awakening technique that reverses the entire world in 3 rounds: Reduces all enemies\' rage recovery speed by 15%; Increases the number of rounds maintaining the awakening form by 1 and increases rage recovery when attacking in awakening form from 0 to 40%.',
		starEffectDesc_th = 'เทคนิคฟอร์มปลุกพลังขั้นสูงที่ย้อนกลับโลกทั้งใบใน 3 ตา: ลดความเร็วการฟื้นฟูความโกรธของศัตรูทั้งหมดลง 15%; เพิ่มจำนวนตาที่รักษาฟอร์มปลุกพลังเพิ่มขึ้น 1 และเพิ่มการฟื้นฟูความโกรธเมื่อโจมตีในฟอร์มปลุกพลังจาก 0 เป็น 40%.',
		starEffectDesc_in = 'Teknik Bentuk Terbangun Ultimate yang membalikkan seluruh dunia dalam 3 giliran: Mengurangi kecepatan pemulihan kemarahan semua musuh sebanyak 15%; Menambah jumlah giliran mempertahankan bentuk terbangun sebanyak 1 dan meningkatkan pemulihan kemarahan saat menyerang dalam bentuk terbangun dari 0 menjadi 40%.',
		starEffectDesc_ph = 'Ultimate Form Awakening technique na nagbabaliktad sa buong mundo sa loob ng 3 rounds: Binabawasan ang bilis ng pagbawi ng galit ng lahat ng kalaban ng 15%; Pinapataas ang bilang ng rounds ng pagpapanatili ng awakening form ng 1 at pinapataas ang pagbawi ng galit kapag umaatake sa awakening form mula 0 hanggang 40%.',
		starEffectDesc_ma = 'Teknik Bentuk Bangkit Ultimate yang membalikkan seluruh dunia dalam 3 pusingan: Mengurangkan kelajuan pemulihan kemarahan semua musuh sebanyak 15%; Meningkatkan bilangan pusingan mengekalkan bentuk bangkit sebanyak 1 dan meningkatkan pemulihan kemarahan apabila menyerang dalam bentuk bangkit dari 0 kepada 40%.',
		zawakeEffect = __data_t__zawakeEffect[23923],
		-- {79003, 1}
		zawakeEffectDesc = 'Special ultimate technique of awakening form that shakes the world for 3 turns: reduces 15% anger recovery speed of all enemies and randomly swaps the front and back rows of enemies. It is limited to once throughout the entire field; awakening form duration is +1 and anger recovery when attacking in awakening form is increased from 0 to 40%.',
		zawakeEffectDesc_en = 'Special ultimate technique of awakening form that shakes the world for 3 turns: reduces 15% anger recovery speed of all enemies and randomly swaps the front and back rows of enemies. It is limited to once throughout the entire field; awakening form duration is +1 and anger recovery when attacking in awakening form is increased from 0 to 40%.',
		zawakeEffectDesc_th = 'เทคนิคพิเศษของรูปแบบการตื่นรู้ที่ทำให้โลกสั่นสะเทือนเป็นเวลา 3 เทิร์น: ลดความเร็วในการฟื้นฟูความโกรธของศัตรูทั้งหมดลง 15% และสลับตำแหน่งแถวหน้าและแถวหลังของศัตรูแบบสุ่ม จำกัดใช้ได้ครั้งเดียวในสนามทั้งหมด; ระยะเวลารูปแบบการตื่นรู้เพิ่มขึ้น 1 และเพิ่มการฟื้นฟูความโกรธเมื่อโจมตีในรูปแบบการตื่นรู้จาก 0 เป็น 40%',
		zawakeEffectDesc_in = 'Teknik khusus dari bentuk kebangkitan yang mengguncang dunia selama 3 giliran: mengurangi kecepatan pemulihan kemarahan semua musuh sebesar 15% dan secara acak menukar posisi baris depan dan belakang musuh. Dibatasi hanya sekali di seluruh medan; durasi bentuk kebangkitan +1 dan pemulihan kemarahan saat menyerang dalam bentuk kebangkitan meningkat dari 0 menjadi 40%.',
		zawakeEffectDesc_ph = 'Espesyal na teknika ng paggising na nagpapalimot sa mundo sa loob ng 3 turn: binabawasan ng 15% ang bilis ng pag-recover ng galit ng lahat ng kalaban at random na pinapalitan ang posisyon ng harap at likod na hanay ng kalaban. Limitado ito sa isang beses sa buong larangan; ang tagal ng paggising ay +1 at ang pag-recover ng galit kapag umaatake sa paggising ay tumaas mula 0 hanggang 40%.',
		zawakeEffectDesc_ma = 'Teknik istimewa bentuk kebangkitan yang menggoncang dunia selama 3 pusingan: mengurangkan kelajuan pemulihan kemarahan semua musuh sebanyak 15% dan secara rawak menukar kedudukan barisan hadapan dan belakang musuh. Ia terhad kepada sekali sahaja di seluruh medan; tempoh bentuk kebangkitan +1 dan pemulihan kemarahan ketika menyerang dalam bentuk kebangkitan meningkat daripada 0 kepada 40%.',
		zawakeEffectDesc_vn = 'Tuyệt chiêu đặc biệt của dạng thức tỉnh khiến cả thế giới đảo lộn trong 3 hiệp: giảm 15% tốc độ hồi phục cơn giận của tất cả kẻ thù và hoán đổi ngẫu nhiên vị trí của hàng trước và hàng sau của kẻ thù. Nó được giới hạn một lần trong toàn bộ lĩnh vực; thời gian của dạng thức tỉnh là +1 và khả năng hồi phục cơn giận khi tấn công ở dạng thức tỉnh được tăng từ 0 lên 40%.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970# World Reversal effect randomly swaps the enemy\'s front and back row positions, limited to once per game.',
		zawakeSimpleDesc_en = '#C0x5c9970# World Reversal effect randomly swaps the enemy\'s front and back row positions, limited to once per game.',
		zawakeSimpleDesc_th = '#C0x5c9970# เอฟเฟกต์การกลับด้านโลกจะสลับตำแหน่งแนวหน้ากับแนวหลังของศัตรูแบบสุ่ม ใช้ได้หนึ่งครั้งต่อเกม',
		zawakeSimpleDesc_in = '#C0x5c9970# Efek Pembalikan Dunia secara acak menukar posisi depan dan belakang musuh, hanya berlaku satu kali dalam satu permainan',
		zawakeSimpleDesc_ph = '#C0x5c9970# Ang epekto ng World Reversal ay random na nagpapalit ng posisyon ng front at back row ng kalaban, isang beses lang sa buong laban',
		zawakeSimpleDesc_ma = '#C0x5c9970# Kesan World Reversal akan menukar posisi barisan hadapan dan belakang musuh secara rawak, terhad kepada sekali sahaja dalam permainan',
		zawakeSimpleDesc_vn = '#C0x5c9970# Hiệu ứng đảo ngược thế giới đi kèm với việc hoán đổi ngẫu nhiên vị trí hàng trước và hàng sau của kẻ địch và được giới hạn một lần trong toàn bộ trò chơi.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
