	[23931] = {
		id = 23931,
		skillName_vn = 'Huyết Quỷ Thuật: Trướng Đới',
		skillName_en = 'Blood Demon Technique: Crimson Realm',
		skillName_th = 'เทคนิคลมปีศาจเลือด: อาณาเขตสีแดงเข้ม',
		skillName_in = 'Teknik Setan Darah: Wilayah Merah',
		skillName_ph = 'Blood Demon Technique: Pulang Anyo',
		skillName_ma = 'Teknik Darah Syaitan: Kawasan Merah',
		skillName = 'Blood Demon Technique: Crimson Realm',
		describe_vn = 'Công chúa sa ngã đập đất triệu hồi một cơn gió lạ tấn công một mục tiêu địch, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, tăng gấp đôi phòng thủ của cô ấy lên 50% trong 2 lượt và nhận được 1 điểm ma sau đòn tấn công.',
		describe_en = 'The fallen princess slams the ground to summon a strange wind that attacks an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#. She doubles her defense to 50% for 2 turns and gains 1 mana point after the attack.',
		describe_th = 'เจ้าหญิงที่ตกต่ำกระทืบพื้นเพื่อตะโกนลมแปลกโจมตีเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#100%#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# เธอเพิ่มการป้องกันของเธอเป็นสองเท่าเป็น 50% เป็นเวลา 2 เทิร์นและได้รับ 1 แต้มมานาหลังการโจมตี',
		describe_in = 'Putri yang jatuh menghantam tanah dan memanggil angin aneh untuk menyerang target musuh, memberikan #C0xE69900#100% Kerusakan Fisik#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#. Dia menggandakan pertahanannya menjadi 50% selama 2 giliran dan mendapatkan 1 poin mana setelah serangan.',
		describe_ph = 'Ang bumagsak na prinsesa ay tinapakan ang lupa upang tawagin ang kakaibang hangin na umatake sa isang katunggaling target, nagdudulot ng #C0xE69900#100% Physical Damage#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#. Dobleng pinapataas ang kanyang depensa sa 50% sa loob ng 2 turn at nakakakuha ng 1 mana point pagkatapos ng atake.',
		describe_ma = 'Puteri yang jatuh menghentak tanah untuk memanggil angin aneh menyerang sasaran musuh, memberikan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Dia menggandakan pertahanannya kepada 50% selama 2 pusingan dan memperoleh 1 mata mana selepas serangan.',
		describe = 'The fallen princess slams the ground to summon a strange wind that attacks an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#. She doubles her defense to 50% for 2 turns and gains 1 mana point after the attack.',
		simDesc_vn = 'Công chúa sa ngã đập đất triệu hồi một cơn gió lạ tấn công một mục tiêu địch, gây sát thương vật lý, tăng khả năng giảm sát thương của bản thân và phục hồi bóng ma.',
		simDesc_en = 'The fallen princess slams the ground, summoning a strange wind to attack an enemy target, dealing physical damage, increasing her own damage reduction, and restoring her phantom.',
		simDesc_th = 'เจ้าหญิงผู้ตกต่ำทุบพื้นเพื่อเรียกลมประหลาดโจมตีเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ เพิ่มความสามารถในการลดความเสียหายของตัวเอง และฟื้นฟูเงาผีของเธอ',
		simDesc_in = 'Putri yang jatuh menghantam tanah, memanggil angin aneh untuk menyerang target musuh, memberikan kerusakan fisik, meningkatkan kemampuan pengurangan kerusakan dirinya sendiri, dan memulihkan hantu bayangannya.',
		simDesc_ph = 'Ang bumagsak na prinsesa ay tumama sa lupa, nagpaalab ng kakaibang hangin upang atakihin ang isang kalaban, nagdudulot ng pisikal na pinsala, nagpapataas ng kakayahan sa pagbabawas ng pinsala sa sarili, at nagpapagaling ng kanyang anino.',
		simDesc_ma = 'Puteri yang jatuh memukul tanah, memanggil angin pelik untuk menyerang sasaran musuh, memberikan kerosakan fizikal, meningkatkan keupayaan pengurangan kerosakan diri, dan memulihkan bayang hantu dirinya.',
		simDesc = 'The fallen princess slams the ground, summoning a strange wind to attack an enemy target, dealing physical damage, increasing her own damage reduction, and restoring her phantom.',
		zawakeEffect = __data_t__zawakeEffect[23931],
		-- {79001}
		zawakeEffectDesc = 'The fallen princess slams the ground to summon a strange wind to attack an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Physical Damage#C0x5B545B#. It increases its own defense doubled by an additional 50% for 2 turns and resistance rate by 15% for 2 turns. After attacking, it gains 1 mana point.',
		zawakeEffectDesc_en = 'The fallen princess slams the ground to summon a strange wind to attack an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Physical Damage#C0x5B545B#. It increases its own defense doubled by an additional 50% for 2 turns and resistance rate by 15% for 2 turns. After attacking, it gains 1 mana point.',
		zawakeEffectDesc_th = 'เจ้าหญิงที่ล้มลงทุบพื้นเพื่อเรียกลมประหลาดโจมตีเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#100%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B#. มันเพิ่มพลังป้องกันของตนเองเป็นสองเท่าบวกอีก 50% เป็นเวลา 2 เทิร์น และอัตราต้านทานเพิ่มขึ้น 15% เป็นเวลา 2 เทิร์น หลังโจมตี มันได้รับ 1 คะแนน #ma mau#.',
		zawakeEffectDesc_in = 'Putri yang jatuh menghantam tanah untuk memanggil angin aneh menyerang satu target musuh, menyebabkan #C0xE69900#100% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerusakan Fisik#C0x5B545B#. Ia meningkatkan pertahanannya sendiri dua kali lipat ditambah 50% selama 2 giliran dan tingkat resistensi sebesar 15% selama 2 giliran. Setelah menyerang, ia memperoleh 1 poin #ma mau#.',
		zawakeEffectDesc_ph = 'Ang bumagsak na prinsesa ay pinagsuntok ang lupa upang tumawag ng kakaibang hangin na umatake sa isang kalaban, na nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Pinapataas nito ang kanyang sariling depensa na doble pa ng 50% sa loob ng 2 turn at ang rate ng pagtutol ay nadadagdagan ng 15% sa loob ng 2 turn. Pagkatapos umatake, nakakakuha ito ng 1 #ma mau# na puntos.',
		zawakeEffectDesc_ma = 'Puteri yang jatuh menghentak tanah untuk memanggil angin aneh menyerang satu sasaran musuh, menyebabkan #C0xE69900#100% Kecederaan Fizikal#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kecederaan Fizikal#C0x5B545B#. Ia meningkatkan pertahanannya sendiri dua kali ganda ditambah 50% selama 2 pusingan dan kadar ketahanan sebanyak 15% selama 2 pusingan. Selepas menyerang, ia menerima 1 mata #ma mau#.',
		zawakeEffectDesc_vn = 'Công chúa sa ngã đập đất triệu hồi một cơn gió lạ tấn công một mục tiêu địch, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B#. Nó tăng khả năng phòng thủ gấp đôi của chính mình thêm 50% trong 2 lượt và tỷ lệ kháng cự thêm 15% trong 2 lượt. Sau khi tấn công, nó nhận được 1 điểm ma.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increase own double defense by 50% for 2 turns\n#F20# \n#F40##C0x5c9970#→ Increase own double defense by 50% for 2 turns and 15% resistance rate for 2 turns',
		zawakeSimpleDesc_en = 'Increase own double defense by 50% for 2 turns\n#F20# \n#F40##C0x5c9970#→ Increase own double defense by 50% for 2 turns and 15% resistance rate for 2 turns',
		zawakeSimpleDesc_th = 'เพิ่มพลังป้องกันคู่ของตัวเอง 50% เป็นเวลา 2 เทิร์น\n#F20# \n#F40##C0x5c9970#→ เพิ่มพลังป้องกันคู่ของตัวเอง 50% เป็นเวลา 2 เทิร์น และเพิ่มอัตราต้านทาน 15% เป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Meningkatkan pertahanan ganda sendiri sebesar 50% selama 2 giliran\n#F20# \n#F40##C0x5c9970#→ Meningkatkan pertahanan ganda sendiri sebesar 50% selama 2 giliran dan 15% resistensi selama 2 giliran',
		zawakeSimpleDesc_ph = 'Dagdagan ng 50% ang double defense ng sarili sa loob ng 2 turn\n#F20# \n#F40##C0x5c9970#→ Dagdagan ng 50% ang double defense ng sarili sa loob ng 2 turn at 15% resistance sa loob ng 2 turn',
		zawakeSimpleDesc_ma = 'Tingkatkan pertahanan berganda diri sebanyak 50% selama 2 pusingan\n#F20# \n#F40##C0x5c9970#→ Tingkatkan pertahanan berganda diri sebanyak 50% selama 2 pusingan dan kadar ketahanan sebanyak 15% selama 2 pusingan',
		zawakeSimpleDesc_vn = 'Tăng 50% phòng thủ đôi của bản thân trong 2 lượt\n#F20# \n#F40##C0x5c9970#→ Tăng 50% phòng thủ đôi của bản thân trong 2 lượt và 15% tỷ lệ chống chịu trong 2 lượt',
		upLvDesc = 'Fixed damage +96',
		upLvDesc_en = 'Fixed damage +96',
		upLvDesc_th = 'ความเสียหายคงที่ +96',
		upLvDesc_in = 'Kerusakan tetap +96',
		upLvDesc_ph = 'Fixed damage +96',
