	[23932] = {
		id = 23932,
		skillName_vn = 'Huyết Quỷ Thuật: U Minh Hỏa',
		skillName_en = 'Blood Demon Technique: Underworld Fire',
		skillName_th = 'วิชาอสูรเลือด: ไฟใต้นรก',
		skillName_in = 'Teknik Setan Darah: Api Dunia Bawah',
		skillName_ph = 'Teknik ng Dugo ng Demonyo: Apoy sa Ilalim ng Mundo',
		skillName_ma = 'Teknik Iblis Darah: Api Alam Bawah',
		skillName = 'Blood Demon Technique: Underworld Fire',
		describe_vn = 'Công chúa sa ngã biến thành ma và di chuyển đến một mục tiêu địch để đánh lén, gây #C0xE69900#170% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, tăng mức giảm sát thương cho cột của cô ấy thêm 15% trong 2 lượt và nhận được 2 điểm ma sau tấn công\n#F20# \n#F40#[#L10#Awakening Form#L0#], phạm vi tấn công thay đổi theo hàng và có thêm 80% xác suất [#L10#Ghost Fire#L0#] trong 2 lượt\n[#L10#Ghost Ghost Fire#L0#]: Hiệu ứng tiêu cực đặc biệt, chỉ có thể xua tan và không thể chồng lên. Trước khi mục tiêu di chuyển hoặc khi lửa ma bị xua tan, máu của mục tiêu sẽ bị giảm (12% giới hạn trên của lượng máu của nữ hoàng đã ngã xuống, sát thương là sát thương thực sự) và 120 điểm thịnh nộ.',
		describe_en = 'The fallen princess transforms into a demon and moves to an enemy target to stealthily strike, dealing #C0xE69900#170% Physical Damage#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, increases her column\'s damage reduction by 15% for 2 turns and gains 2 demon points after the attack \n#F20# \n#F40#[#L10#Awakening Form#L0#], attack range changes by row and gains an 80% chance of [#L10#Ghost Fire#L0#] for 2 turns \n[#L10#Ghost Ghost Fire#L0#]: a special negative effect that can only be dispelled and cannot be stacked. Before the target moves or when the ghost fire is dispelled, the target’s HP is reduced (12% of the fallen queen’s max HP, damage is true damage) and 120 rage points.',
		describe_th = 'เจ้าหญิงผู้พลัดตกกลายเป็นปีศาจและเคลื่อนที่ไปยังเป้าหมายศัตรูเพื่อโจมตีแบบลอบโจมตี สร้างความเสียหายทางกายภาพ #C0xE69900#170%#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มการลดความเสียหายของแถวที่เธออยู่ขึ้นอีก 15% เป็นเวลา 2 เทิร์น และได้รับ 2 แต้มปีศาจหลังโจมตี \n#F20# \n#F40#[#L10#ฟอร์มตื่นรู้#L0#] ระยะโจมตีเปลี่ยนไปตามแถว พร้อมมีโอกาส 80% ที่จะเกิด [#L10#ไฟผี#L0#] เป็นเวลา 2 เทิร์น \n[#L10#ไฟผีผี#L0#]: ผลลบพิเศษที่สามารถลบได้อย่างเดียวและไม่สามารถซ้อนทับ ก่อนที่เป้าหมายจะเคลื่อนที่หรือเมื่อไฟผีถูกลบ พลังชีวิตของเป้าหมายจะถูกลดลง (12% ของพลังชีวิตสูงสุดของราชินีผู้พลัดตก ความเสียหายเป็นความเสียหายแท้) พร้อมกับได้รับ 120 แต้มโกรธ',
		describe_in = 'Putri yang jatuh berubah menjadi setan dan bergerak ke target musuh untuk serangan diam-diam, memberikan #C0xE69900#170% Kerusakan Fisik#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, meningkatkan pengurangan kerusakan pada kolomnya sebesar 15% selama 2 giliran dan mendapatkan 2 poin setan setelah menyerang \n#F20# \n#F40#[#L10#Bentuk Kebangkitan#L0#], jangkauan serangan berubah berdasarkan baris dan mendapat 80% kemungkinan [#L10#Api Hantu#L0#] selama 2 giliran \n[#L10#Api Hantu Hantu#L0#]: efek negatif khusus yang hanya bisa dihapus dan tidak bisa bertumpuk. Sebelum target bergerak atau ketika api hantu dihapus, HP target akan berkurang (12% dari batas atas HP ratu yang jatuh, kerusakan adalah kerusakan nyata) dan mendapatkan 120 poin amarah.',
		describe_ph = 'Ang nabagsak na prinsesa ay nagiging demonyo at lumalapit sa kaaway upang umatake nang palihim, nagdudulot ng #C0xE69900#170% Pisikal na Pinsala#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, nagpapataas ng 15% pagbawas ng pinsala sa kanyang hanay sa loob ng 2 turn at nakakakuha ng 2 demonyong puntos pagkatapos ng pag-atake \n#F20# \n#F40#[#L10#Hugis ng Pagkamulat#L0#], nagbabago ang saklaw ng pag-atake ayon sa hanay at may 80% tsansa ng [#L10#Aking Apoy#L0#] sa loob ng 2 turn \n[#L10#Aking Apoy Aking Apoy#L0#]: isang espesyal na negatibong epekto na maaaring alisin lamang at hindi maaaring magkapatong. Bago kumilos ang target o kapag naalis ang apoy ng multo, mababawasan ang HP ng target (12% ng pinakamataas na HP ng mabagsak na reyna, ang pinsala ay totoong pinsala) at 120 puntos ng galit.',
		describe_ma = 'Puteri yang jatuh berubah menjadi syaitan dan bergerak ke sasaran musuh untuk menyerang secara senyap, menyebabkan #C0xE69900#170% Kerosakan Fizikal#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, meningkatkan tahap pengurangan kerosakan untuk barisnya sebanyak 15% selama 2 giliran dan menerima 2 mata syaitan selepas serangan \n#F20# \n#F40#[#L10#Bentuk Kebangkitan#L0#], julat serangan berubah mengikut baris dan mempunyai peluang 80% untuk [#L10#Api Hantu#L0#] selama 2 giliran \n[#L10#Api Hantu Hantu#L0#]: kesan negatif khas yang hanya boleh dipulihkan dan tidak boleh bertindih. Sebelum sasaran bergerak atau ketika api hantu dipulihkan, nyawa sasaran akan berkurang (12% daripada had atas nyawa ratu yang telah jatuh, kerosakan adalah kerosakan sebenar) dan menerima 120 mata kemarahan.',
		describe = 'The fallen princess transforms into a demon and moves to an enemy target to stealthily strike, dealing #C0xE69900#170% Physical Damage#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, increases her column\'s damage reduction by 15% for 2 turns and gains 2 demon points after the attack \n#F20# \n#F40#[#L10#Awakening Form#L0#], attack range changes by row and gains an 80% chance of [#L10#Ghost Fire#L0#] for 2 turns \n[#L10#Ghost Ghost Fire#L0#]: a special negative effect that can only be dispelled and cannot be stacked. Before the target moves or when the ghost fire is dispelled, the target’s HP is reduced (12% of the fallen queen’s max HP, damage is true damage) and 120 rage points.',
		simDesc_vn = 'Công chúa sa ngã biến thành một bóng ma và di chuyển đến một mục tiêu kẻ thù để đánh lén, gây sát thương vật lý, tăng cơn thịnh nộ tối đa của mục tiêu và nhận điểm ma cho bản thân; ở dạng thức tỉnh, phạm vi tấn công thay đổi thành một hàng, có khả năng thêm lửa ma.',
		simDesc_en = 'The fallen princess transforms into a ghost and moves toward an enemy target to perform a sneak attack, dealing physical damage, increasing the target\'s maximum rage, and gaining ghost points for herself; in awakened form, the attack range changes to a line and has the ability to add ghost fire.',
		simDesc_th = 'เจ้าหญิงผู้ล่มสลายแปลงร่างเป็นผีและเคลื่อนที่ไปยังเป้าหมายศัตรูเพื่อโจมตีแบบลอบทำร้าย สร้างความเสียหายทางกายภาพ เพิ่มความโกรธสูงสุดของเป้าหมายและรับแต้มผีสำหรับตัวเอง; ในรูปแบบตื่นรู้ ระยะโจมตีเปลี่ยนเป็นแนวแถว และมีความสามารถในการเพิ่มไฟผี',
		simDesc_in = 'Putri yang jatuh berubah menjadi hantu dan bergerak menuju target musuh untuk menyerang diam-diam, memberikan kerusakan fisik, meningkatkan kemarahan maksimum target, dan mendapatkan poin hantu untuk dirinya sendiri; dalam bentuk terbangun, jangkauan serangan berubah menjadi satu baris dan memiliki kemampuan untuk menambahkan api hantu.',
		simDesc_ph = 'Ang prinsesang bumagsak ay nagiging isang multo at lumalapit sa isang kalabang target upang magsagawa ng lihim na pag-atake, nagdudulot ng pisikal na pinsala, pinapataas ang maximum na galit ng target at nakakakuha ng puntos ng multo para sa kanyang sarili; sa gising na anyo, nagbabago ang saklaw ng atake sa isang linya at may kakayahang magdagdag ng apoy ng multo.',
		simDesc_ma = 'Puteri yang jatuh berubah menjadi hantu dan bergerak ke arah sasaran musuh untuk menyerang secara senyap, menyebabkan kerosakan fizikal, meningkatkan kemarahan maksimum sasaran dan memperoleh mata hantu untuk dirinya sendiri; dalam bentuk terjaga, julat serangan berubah menjadi satu baris dan berupaya menambah api hantu.',
		simDesc = 'The fallen princess transforms into a ghost and moves toward an enemy target to perform a sneak attack, dealing physical damage, increasing the target\'s maximum rage, and gaining ghost points for herself; in awakened form, the attack range changes to a line and has the ability to add ghost fire.',
		zawakeEffect = __data_t__zawakeEffect[23932],
		-- {79002}
		zawakeEffectDesc = 'The fallen princess transforms into a demon and moves to an enemy target to ambush, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage#C0x5B545B#, increases her column\'s damage reduction by 20% for 2 turns and gains 2 demon points after attacking\n#F20# \n#F40#<#L10#Awakening Form#L0#>, attack range changes by row and gains 80% chance of <#L10#Ghost Fire#L0#> for 2 turns and adds <#L10#Ghost Shield#L0> to your dark demon hero. #>\n<#L10#鬼火#L0#>: Special negative effect, can only be dispelled and cannot stack. Before the target moves or when ghost fire is dispelled, the target\'s HP is reduced (12% of the fallen queen\'s max HP, damage is true damage) and 120 rage points.',
		zawakeEffectDesc_en = 'The fallen princess transforms into a demon and moves to an enemy target to ambush, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage#C0x5B545B#, increases her column\'s damage reduction by 20% for 2 turns and gains 2 demon points after attacking\n#F20# \n#F40#<#L10#Awakening Form#L0#>, attack range changes by row and gains 80% chance of <#L10#Ghost Fire#L0#> for 2 turns and adds <#L10#Ghost Shield#L0> to your dark demon hero. #>\n<#L10#鬼火#L0#>: Special negative effect, can only be dispelled and cannot stack. Before the target moves or when ghost fire is dispelled, the target\'s HP is reduced (12% of the fallen queen\'s max HP, damage is true damage) and 120 rage points.',
		zawakeEffectDesc_th = 'เจ้าหญิงผู้ตกสู่มืดกลายเป็นปีศาจและเคลื่อนที่ไปยังเป้าหมายศัตรูเพื่อโจมตีแบบลอบทำร้าย สร้างความเสียหายทางกายภาพ #C0xE69900#170%#C0x5B545B#+$(skillLevel*4*48)$ ของ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มการลดความเสียหายของคอลัมน์ของเธอ 20% เป็นเวลา 2 เทิร์น และได้รับ 2 คะแนนปีศาจหลังจากโจมตี\n#F20# \n#F40#<#L10#รูปแบบดื่มด่ำ#L0#>, ระยะการโจมตีเปลี่ยนแปลงตามแถวและมีโอกาส 80% ของ <#L10#ไฟผี#L0#> เป็นเวลา 2 เทิร์น และเพิ่ม <#L10#โล่ผี#L0> ให้กับฮีโร่ปีศาจมืดของคุณ #>\n<#L10#鬼火#L0#>: ผลกระทบลบพิเศษ สามารถล้างได้เท่านั้นและไม่สามารถทับซ้อน ก่อนที่เป้าหมายจะเคลื่อนที่หรือเมื่อไฟผีถูกล้าง เลือดของเป้าหมายจะลดลง (12% ของค่าพลังชีวิตสูงสุดของราชินีที่ล้มลง ความเสียหายเป็นความเสียหายจริง) และได้รับ 120 คะแนนความโกรธ',
		zawakeEffectDesc_in = 'Putri yang jatuh berubah menjadi iblis dan bergerak ke target musuh untuk menyerang secara diam-diam, memberikan #C0xE69900#170% Damage Fisik#C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54# Damage Fisik#C0x5B545B#, meningkatkan kemampuan pengurangan damage kolomnya sebesar 20% selama 2 giliran dan mendapatkan 2 poin iblis setelah menyerang\n#F20# \n#F40#<#L10#Bentuk Kebangkitan#L0#>, jangkauan serangan berubah berdasarkan baris dan mendapatkan 80% peluang <#L10#Api Hantu#L0#> selama 2 giliran serta menambahkan <#L10#Perisai Hantu#L0> ke pahlawan iblis gelap milik Anda. #>\n<#L10#鬼火#L0#>: Efek negatif khusus, hanya dapat dihilangkan dan tidak dapat menumpuk. Sebelum target bergerak atau ketika api hantu dihilangkan, HP target berkurang (12% batas atas HP ratu yang jatuh, damage adalah damage nyata) dan 120 poin amarah.',
		zawakeEffectDesc_ph = 'Ang prinsesang bumagsak ay nagiging demonyo at lumilipat sa isang kalaban na target upang umatake nang palihim, nagdudulot ng #C0xE69900#170% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$ ng #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, pinapataas ang kakayahang magpababa ng pinsala ng kanyang kolum ng 20% sa loob ng 2 turn at nakakakuha ng 2 demon points pagkatapos umatake\n#F20# \n#F40#<#L10#Anyo ng Pagkagising#L0#>, nagbabago ang saklaw ng atake ayon sa hilera at nagkakaroon ng 80% tsansa ng <#L10#Ghost Fire#L0#> sa loob ng 2 turn at nagdadagdag ng <#L10#Ghost Shield#L0> sa iyong madilim na demonyong bayani. #>\n<#L10#鬼火#L0#>: Espesyal na negatibong epekto, maaari lamang ma-dispel at hindi maaaring magsabay. Bago gumalaw ang target o kapag na-dispel ang ghost fire, nababawasan ang HP ng target (12% ng pinakamataas na HP ng bumagsak na reyna, ang pinsala ay tunay na pinsala) at 120 puntos ng galit.',
		zawakeEffectDesc_ma = 'Puteri yang terjatuh berubah menjadi syaitan dan bergerak ke sasaran musuh untuk menyerang secara mengejut, memberikan #C0xE69900#170% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ daripada #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, meningkatkan kemampuan pengurangan kerosakan untuk kolumnya sebanyak 20% selama 2 giliran dan menerima 2 mata syaitan selepas menyerang\n#F20# \n#F40#<#L10#Bentuk Kebangkitan#L0#>, julat serangan berubah mengikut baris dan mempunyai 80% peluang <#L10#Api Hantu#L0#> selama 2 giliran dan menambah <#L10#Perisai Hantu#L0> ke wira syaitan gelap anda. #>\n<#L10#鬼火#L0#>: Kesan negatif khas, hanya boleh dibersihkan dan tidak boleh bertindih. Sebelum sasaran bergerak atau apabila api hantu dibersihkan, HP sasaran akan dikurangkan (12% had atas HP ratu yang terjatuh, kerosakan adalah kerosakan sebenar) dan 120 mata kemarahan.',
		zawakeEffectDesc_vn = 'Công chúa sa ngã biến thành ma và di chuyển đến một mục tiêu địch để đánh lén, gây #C0xE69900#170% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ của #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, tăng khả năng giảm sát thương cho cột của cô ấy thêm 20% trong 2 lượt và nhận được 2 điểm ma sau tấn công\n#F20# \n#F40#<#L10#Awakening Form#L0#>, phạm vi tấn công thay đổi theo hàng và có thêm 80% xác suất <#L10#Ghost Fire#L0#> trong 2 lượt và thêm <#L10#Ghost Shield#L0> cho anh hùng bóng tối loại ma của riêng bạn. #>\n<#L10#鬼火#L0#>: Hiệu ứng tiêu cực đặc biệt, chỉ có thể xua tan và không thể chồng chất. Trước khi mục tiêu di chuyển hoặc khi lửa ma bị xua tan, máu của mục tiêu sẽ bị giảm (12% giới hạn trên của lượng máu của nữ hoàng đã ngã xuống, sát thương là sát thương thực sự) và 120 điểm thịnh nộ.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increase your column’s damage reduction by 15% for 2 turns\n#F20# \n#F40##C0x5c9970#→Increase your column’s damage reduction by 20% for 2 turns\n<#L10#Awakening Form#L0#> Adds <#L10#Ghost Shield#L0#> to your ghosts and dark heroes.',
		zawakeSimpleDesc_en = 'Increase your column’s damage reduction by 15% for 2 turns\n#F20# \n#F40##C0x5c9970#→Increase your column’s damage reduction by 20% for 2 turns\n<#L10#Awakening Form#L0#> Adds <#L10#Ghost Shield#L0#> to your ghosts and dark heroes.',
		zawakeSimpleDesc_th = 'เพิ่มการลดความเสียหายของแถวของคุณ 15% เป็นเวลา 2 เทิร์น\n#F20# \n#F40##C0x5c9970#→เพิ่มการลดความเสียหายของแถวของคุณ 20% เป็นเวลา 2 เทิร์น\n<#L10#Awakening Form#L0#> เพิ่ม <#L10#Ghost Shield#L0#> ให้กับผีและฮีโร่ธาตุมืดของคุณ',
		zawakeSimpleDesc_in = 'Meningkatkan pengurangan damage untuk kolommu sebesar 15% selama 2 giliran\n#F20# \n#F40##C0x5c9970#→Meningkatkan pengurangan damage untuk kolommu sebesar 20% selama 2 giliran\n<#L10#Awakening Form#L0#> Menambahkan <#L10#Ghost Shield#L0#> ke hantu dan hero gelap milikmu',
		zawakeSimpleDesc_ph = 'Dagdagan ng 15% ang damage reduction ng hanay mo sa loob ng 2 turn\n#F20# \n#F40##C0x5c9970#→Dagdagan ng 20% ang damage reduction ng hanay mo sa loob ng 2 turn\n<#L10#Awakening Form#L0#> Nagdadagdag ng <#L10#Ghost Shield#L0#> sa sarili mong mga espiritu at dark heroes',
		zawakeSimpleDesc_ma = 'Tingkatkan pengurangan kerosakan untuk lajur anda sebanyak 15% selama 2 pusingan\n#F20# \n#F40##C0x5c9970#→Tingkatkan pengurangan kerosakan untuk lajur anda sebanyak 20% selama 2 pusingan\n<#L10#Awakening Form#L0#> Menambah <#L10#Ghost Shield#L0#> kepada roh dan wira gelap anda',
		zawakeSimpleDesc_vn = 'Tăng mức giảm sát thương cho cột của bạn thêm 15% trong 2 lượt\n#F20# \n#F40##C0x5c9970#→Tăng mức giảm sát thương cho cột của bạn thêm 20% trong 2 lượt\n<#L10#Awakening Form#L0#> Thêm <#L10#Ghost Shield#L0#> cho bóng ma và anh hùng bóng tối của riêng bạn.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
		upLvDesc_in = 'Kerusakan tetap +192',
