		targetTypeDesc_en = 'Single unit or enemy vertical row',
		targetTypeDesc_th = 'ยูนิตเดี่ยวหรือแถวตั้งของศัตรู',
		targetTypeDesc_in = 'Unit tunggal atau baris vertikal musuh',
		targetTypeDesc_ph = 'Isang yunit o patayong hanay ng kalaban',
		targetTypeDesc_ma = 'Unit tunggal atau barisan menegak musuh',
