	[23933] = {
		id = 23933,
		skillName_vn = 'Huyết Quỷ Thuật: Bát Trọng Đới Trảm',
		skillName_en = 'Blood Demon Technique: Eight-Layered Belt Slash',
		skillName_th = 'เทคนิครับปีศาจเลือด: ฟันสายรัดแปดชั้น',
		skillName_in = 'Teknik Setan Darah: Tebas Sabuk Delapan Lapisan',
		skillName_ph = 'Blood Demon Technique: Walong Patong na Sintas',
		skillName_ma = 'Teknik Syaitan Darah: Tebasan Tali Lapan Lapisan',
		skillName = 'Blood Demon Technique: Eight-Layered Belt Slash',
		describe_vn = 'Công chúa sa ngã thức dậy từ vực thẳm, sau đó triệu hồi lối vào thế giới đảo ngược, hút các đơn vị hàng đầu của kẻ địch vào đó, gây #C0xE69900#230% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, giảm cơn thịnh nộ của mục tiêu trúng đòn đi 250 điểm và nhận được 3 điểm ma sau khi tấn công\n#F20# \n#F40#Sau khi thực hiện chiêu thức đặc biệt, anh ta chuyển sang [#L10#Hình thức thức tỉnh#L0#] trong 2 hiệp. Giới hạn trên của lượng máu của chính anh ta (chỉ tăng giới hạn trên), tốc độ và tổng tỷ lệ kiểm soát được tăng thêm 50% (không thể phân tán, chuyển giao, sao chép), Chuyển sang chiêu thức đặc biệt mới (không yêu cầu cuồng nộ và không tiêu hao thịnh nộ khi giải phóng, hạ nhiệt trong 2 lượt sau khi giải phóng): Phạm vi thay đổi đối với tất cả kẻ thù và có thêm 75% xác suất thêm [#L10#鬼鬼火#L0#] của 4 anh hùng của kẻ địch có cơn thịnh nộ cao nhất trong 2 lượt.',
		describe_en = 'The fallen princess awakens from the abyss, then summons the entrance to the reversed world, drawing the enemy\'s top units in, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, reducing the target\'s rage by 250 points upon hit and gaining 3 mana points after attacking\n#F20# \n#F40# After performing the special skill, he shifts into [#L10#Awakened Form#L0#] for 2 turns. His maximum health cap (only increasing the cap), speed, and total control resistance are increased by 50% (cannot be dispersed, transferred, or copied). Switches to a new special skill (no rage required, no rage consumed on release, cooldown for 2 turns after release): The range changes to affect all enemies and has an additional 75% chance to inflict [#L10#鬼鬼火#L0#] on the 4 enemy heroes with the highest rage for 2 turns.',
		describe_th = 'เจ้าหญิงที่ล้มลงตื่นขึ้นมาจากเหวนรก จากนั้นเรียกทางเข้าโลกกลับด้าน ดึงยูนิตชั้นนำของศัตรูเข้ามา สร้าง #C0xE69900#230% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# ลดความโกรธของเป้าหมายลง 250 แต้มเมื่อโดนโจมตี และได้รับ 3 แต้มมานาหลังโจมตี\n#F20# \n#F40# หลังจากใช้ทักษะพิเศษ เขาจะเปลี่ยนเป็น [#L10#รูปลักษณ์ตื่นรู้#L0#] เป็นเวลา 2 เทิร์น ขีดจำกัดสูงสุดของพลังชีวิตของเขา (เพิ่มได้เฉพาะขีดจำกัดสูงสุด) ความเร็ว และอัตราการควบคุมโดยรวมเพิ่มขึ้น 50% (ไม่สามารถแจกจ่าย โอน หรือคัดลอกได้) เปลี่ยนไปใช้ทักษะพิเศษใหม่ (ไม่ต้องใช้ความโกรธ และไม่ใช้ความโกรธเมื่อปล่อย ท่าจะเย็นลงใน 2 เทิร์นหลังปล่อย): ขอบเขตเปลี่ยนเป็นโจมตีศัตรูทั้งหมดและมีโอกาสเพิ่ม 75% ในการติด [#L10#鬼鬼火#L0#] กับ 4 ฮีโร่ของศัตรูที่มีความโกรธสูงสุดใน 2 เทิร์น',
		describe_in = 'Putri yang jatuh bangun dari jurang, kemudian memanggil pintu masuk ke dunia terbalik, menarik unit utama musuh ke dalamnya, memberikan #C0xE69900#230% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Kerusakan Fisik #C0x5B545B#, mengurangi kemarahan target yang terkena serangan sebanyak 250 poin dan mendapatkan 3 poin mana setelah menyerang\n#F20# \n#F40# Setelah melakukan skill khusus, dia berubah menjadi [#L10#Bentuk Terbangun#L0#] selama 2 giliran. Batas atas HP-nya (hanya meningkatkan batas atas), kecepatan, dan total tingkat kontrolnya bertambah 50% (tidak bisa disebarkan, dipindahkan, atau disalin). Beralih ke skill khusus baru (tidak memerlukan kemarahan dan tidak mengonsumsi kemarahan saat digunakan, cooldown selama 2 giliran setelah penggunaan): Jangkauan berubah menjadi semua musuh dan memiliki peluang 75% untuk menambahkan [#L10#鬼鬼火#L0#] pada 4 pahlawan musuh dengan kemarahan tertinggi selama 2 giliran.',
		describe_ph = 'Ang bumagsak na prinsesa ay nagising mula sa kailaliman, pagkatapos ay tumawag ng pasukan sa mundo ng baligtad, hinila ang nangungunang mga yunit ng kaaway doon, nagdudulot ng #C0xE69900#230% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, binabawasan ang galit ng tinarget na tinamaan ng 250 puntos at nakakakuha ng 3 puntos ng mana pagkatapos umatake\n#F20# \n#F40# Pagkatapos gawin ang espesyal na kasanayan, siya ay nagbabago sa [#L10#Nabuhay na Anyong Gising#L0#] sa loob ng 2 turn. Ang itaas na hangganan ng kanyang HP (tanging pinapataas ang hangganan lamang), bilis, at kabuuang rate ng kontrol ay tumataas ng 50% (hindi maaaring ipamahagi, ilipat, o kopyahin). Lumilipat sa bagong espesyal na kasanayan (hindi kailangan ang galit at hindi gumagamit ng galit kapag niyayakap, cooldown sa loob ng 2 turn pagkatapos ng pagpalaya): Nagbabago ang saklaw upang maapektuhan lahat ng kalaban at may dagdag na 75% tsansang magdulot ng [#L10#鬼鬼火#L0#] sa 4 na pinakamataas ang galit na bayani ng kalaban nang 2 turn.',
		describe_ma = 'Puteri yang jatuh bangun dari jurang, kemudian memanggil pintu masuk ke dunia terbalik, menarik unit teratas musuh ke dalamnya, memberikan #C0xE69900#230% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, mengurangkan kemarahan sasaran yang terkena serangan sebanyak 250 mata dan menerima 3 mata mana selepas menyerang\n#F20# \n#F40# Selepas melakukan kemahiran khas, dia bertukar ke [#L10#Bentuk Kebangkitan#L0#] selama 2 pusingan. Had atas jumlah darahnya (hanya meningkatkan had atas), kelajuan, dan kadar kawalan keseluruhan meningkat sebanyak 50% (tidak boleh disebar, dipindahkan, atau disalin). Beralih ke kemahiran khas baru (tidak memerlukan kemarahan dan tidak menggunakan kemarahan semasa melepaskan, masa sejuk selama 2 pusingan selepas pelepasan): Julat berubah kepada semua musuh dan mempunyai peluang tambahan 75% untuk menambahkan [#L10#鬼鬼火#L0#] ke 4 wira musuh dengan kemarahan tertinggi selama 2 pusingan.',
		describe = 'The fallen princess awakens from the abyss, then summons the entrance to the reversed world, drawing the enemy\'s top units in, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, reducing the target\'s rage by 250 points upon hit and gaining 3 mana points after attacking\n#F20# \n#F40# After performing the special skill, he shifts into [#L10#Awakened Form#L0#] for 2 turns. His maximum health cap (only increasing the cap), speed, and total control resistance are increased by 50% (cannot be dispersed, transferred, or copied). Switches to a new special skill (no rage required, no rage consumed on release, cooldown for 2 turns after release): The range changes to affect all enemies and has an additional 75% chance to inflict [#L10#鬼鬼火#L0#] on the 4 enemy heroes with the highest rage for 2 turns.',
		simDesc_vn = 'Nữ hoàng sa ngã tỉnh dậy từ vực thẳm, sau đó triệu hồi lối vào thế giới ngược để hút các đơn vị hàng đầu của kẻ địch vào đó, giảm giá trị tức giận của chúng và phục hồi bóng ma, chuyển sang dạng thức tỉnh, phạm vi tấn công trở thành toàn bộ cơ thể và có lửa ma.',
		simDesc_en = 'The fallen queen awakens from the abyss, then summons the entrance to the reversed world to pull the enemy\'s top units inside, reducing their rage and restoring the phantom. She shifts into an awakened form, with her attack range becoming her entire body and wielding spectral flames.',
		simDesc_th = 'ราชินีผู้ตกตื่นขึ้นมาจากห้วงลึก จากนั้นเรียกทางเข้าของโลกผกผันเพื่อดึงหน่วยชั้นยอดของศัตรูเข้ามา ลดค่าความโกรธของพวกมันและฟื้นฟูเงา จากนั้นเปลี่ยนเป็นรูปแบบตื่นรู้ ระยะโจมตีครอบคลุมทั้งร่างกายและมีเพลิงวิญญาณ',
		simDesc_in = 'Ratu yang jatuh terbangun dari jurang, lalu memanggil pintu masuk dunia terbalik untuk menarik unit terbaik musuh ke dalamnya, mengurangi nilai kemarahan mereka dan memulihkan bayangan. Dia berubah ke bentuk terbangun, dengan jangkauan serangan menjadi seluruh tubuh dan diliputi api roh.',
		simDesc_ph = 'Nagising ang nagbagsak na reyna mula sa kailaliman, pagkatapos ay tumawag ng pasukan sa mundo ng balik upang hilahin ang nangungunang yunit ng kalaban dito, binabawasan ang kanilang galit at pinapagana muli ang anino. Lumilipat siya sa pormasyon ng paggising, na may saklaw ng pag-atake na buong katawan at may apoy na espiritu.',
		simDesc_ma = 'Ratu yang jatuh bangkit dari jurang, kemudian memanggil pintu masuk dunia terbalik untuk menarik unit utama musuh ke dalamnya, mengurangkan nilai kemarahan mereka dan memulihkan bayangan. Dia berubah ke bentuk kebangkitan, dengan julat serangan menjadi seluruh badan dan mempunyai api roh.',
		simDesc = 'The fallen queen awakens from the abyss, then summons the entrance to the reversed world to pull the enemy\'s top units inside, reducing their rage and restoring the phantom. She shifts into an awakened form, with her attack range becoming her entire body and wielding spectral flames.',
		starEffect = __data_t__starEffect[23933],
		-- {11}
		starEffectDesc_vn = 'Tuyệt kỹ thức tỉnh đảo ngược toàn bộ thế giới trong 3 hiệp: Giảm 15% tốc độ hồi nộ của toàn bộ địch; Tăng số hiệp duy trì trạng thái thức tỉnh thêm 1 và tăng hồi nộ khi tấn công trong trạng thái thức tỉnh từ 0 lên 40%.',
		starEffectDesc = 'Ultimate Awakening skill reverses the entire world for 3 turns: Reduces all enemies\' rage recovery speed by 15%; Increases the number of turns maintaining the awakening state by 1 and increases rage recovery when attacking in the awakening state from 0 to 40%.',
		starEffectDesc_en = 'Ultimate Awakening skill reverses the entire world for 3 turns: Reduces all enemies\' rage recovery speed by 15%; Increases the number of turns maintaining the awakening state by 1 and increases rage recovery when attacking in the awakening state from 0 to 40%.',
		starEffectDesc_th = 'ทักษะตื่นรู้ขั้นสูง พลิกผันทั้งโลกเป็นเวลา 3 เทิร์น: ลดความเร็วการฟื้นฟูความโกรธของศัตรูทั้งหมด 15%; เพิ่มจำนวนเทิร์นที่คงสถานะตื่นรู้เพิ่มขึ้น 1 และเพิ่มการฟื้นฟูความโกรธเมื่อโจมตีในสถานะตื่นรู้จาก 0 เป็น 40%.',
		starEffectDesc_in = 'Skill Kebangkitan Ultimate membalikkan seluruh dunia selama 3 giliran: Mengurangi kecepatan pemulihan kemarahan seluruh musuh sebesar 15%; Menambah jumlah giliran mempertahankan status kebangkitan sebanyak 1 dan meningkatkan pemulihan kemarahan saat menyerang dalam status kebangkitan dari 0 menjadi 40%.',
		starEffectDesc_ph = 'Ang Ultimate Awakening skill ay nagpapabaligtad sa buong mundo sa loob ng 3 turn: Binabawasan ng 15% ang bilis ng recovery ng galit ng lahat ng kalaban; Pinapataas ang bilang ng turn na nagpapatuloy ang estado ng paggising ng 1 at pinapataas ang recovery ng galit kapag umaatake sa estado ng paggising mula 0 hanggang 40%.',
		starEffectDesc_ma = 'Kemahiran Kebangkitan Mutlak membalikkan seluruh dunia selama 3 pusingan: Mengurangkan kelajuan pemulihan kemarahan semua musuh sebanyak 15%; Meningkatkan bilangan pusingan mengekalkan keadaan kebangkitan sebanyak 1 dan meningkatkan pemulihan kemarahan apabila menyerang dalam keadaan kebangkitan dari 0 kepada 40%.',
		zawakeEffect = __data_t__zawakeEffect[23933],
		-- {79003, 1}
		zawakeEffectDesc = 'Special move of the awakening form that shakes the world for 3 rounds: reduces all enemies\' anger recovery speed by 15% and randomly swaps the front and back rows of enemies. It is limited to once per entire battlefield; awakening form duration is +1 and anger recovery on attack in awakening form is increased from 0 to 40%.',
		zawakeEffectDesc_en = 'Special move of the awakening form that shakes the world for 3 rounds: reduces all enemies\' anger recovery speed by 15% and randomly swaps the front and back rows of enemies. It is limited to once per entire battlefield; awakening form duration is +1 and anger recovery on attack in awakening form is increased from 0 to 40%.',
		zawakeEffectDesc_th = 'ท่าไม้ตายพิเศษของรูปแบบตื่นรู้ที่ทำให้ทั้งโลกสั่นคลอนเป็นเวลา 3 รอบ: ลดความเร็วในการฟื้นฟูความโกรธของศัตรูทั้#F 15#L % และสลับตำแหน่งแถวหน้าและแถวหลังของศัตรูแบบสุ่ม จำกัดใช้ได้เพียงครั้งเดียวในสนามทั้งหมด; ระยะเวลาของรูปแบบตื่นรู้เพิ่มขึ้น +1 และความสามารถในการฟื้นฟูความโกรธเมื่อโจมตีในรูปแบบตื่นรู้เพิ่มขึ้นจาก 0 เป็น 40%.',
		zawakeEffectDesc_in = 'Serangan khusus bentuk kesadaran yang mengguncang dunia selama 3 giliran: mengurangi kecepatan pemulihan kemarahan semua musuh sebesar 15% dan menukar posisi baris depan dan belakang musuh secara acak. Ini dibatasi hanya sekali di seluruh medan; durasi bentuk kesadaran bertambah +1 dan pemulihan kemarahan saat menyerang dalam bentuk kesadaran meningkat dari 0 menjadi 40%.',
		zawakeEffectDesc_ph = 'Espesyal na galaw ng awakening form na gumagalaw sa buong mundo sa loob ng 3 round: bumababa ng 15% ang bilis ng paggaling ng galit ng lahat ng kalaban at paikot-ikot na pinapalitan ang mga posisyon ng front at back rows ng kalaban. Limitado lang ito ng isang beses sa buong larangan; ang tagal ng awakening form ay +1 at ang recovery ng galit kapag umaatake sa awakening form ay tumaas mula 0 hanggang 40%.',
		zawakeEffectDesc_ma = 'Serangan khas bentuk sedar yang menggoncang dunia selama 3 pusingan: mengurangkan kelajuan pemulihan kemarahan semua musuh sebanyak 15% dan menukar kedudukan barisan hadapan dan belakang musuh secara rawak. Ia terhad sekali sahaja sepanjang medan; tempoh bentuk sedar adalah +1 dan pemulihan kemarahan semasa menyerang dalam bentuk sedar meningkat daripada 0 kepada 40%.',
		zawakeEffectDesc_vn = 'Tuyệt chiêu đặc biệt của dạng thức tỉnh khiến cả thế giới đảo lộn trong 3 hiệp: giảm 15% tốc độ hồi phục cơn giận của tất cả kẻ thù và hoán đổi ngẫu nhiên vị trí của hàng trước và hàng sau của kẻ thù. Nó được giới hạn một lần trong toàn bộ lĩnh vực; thời gian của dạng thức tỉnh là +1 và khả năng hồi phục cơn giận khi tấn công ở dạng thức tỉnh được tăng từ 0 lên 40%.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970# World Reversal effect randomly swaps the enemy\'s front and back row positions, limited to once per game.',
		zawakeSimpleDesc_en = '#C0x5c9970# World Reversal effect randomly swaps the enemy\'s front and back row positions, limited to once per game.',
		zawakeSimpleDesc_th = '#C0x5c9970# เอฟเฟกต์การกลับด้านโลกจะสลับตำแหน่งแนวหน้ากับแนวหลังของศัตรูแบบสุ่ม ใช้ได้หนึ่งครั้งต่อเกม',
		zawakeSimpleDesc_in = '#C0x5c9970# Efek Pembalikan Dunia secara acak menukar posisi depan dan belakang musuh, hanya berlaku satu kali dalam satu permainan',
		zawakeSimpleDesc_ph = '#C0x5c9970# Ang epekto ng World Reversal ay random na nagpapalit ng posisyon ng front at back row ng kalaban, isang beses lang sa buong laban',
		zawakeSimpleDesc_ma = '#C0x5c9970# Kesan World Reversal akan menukar posisi barisan hadapan dan belakang musuh secara rawak, terhad kepada sekali sahaja dalam permainan',
		zawakeSimpleDesc_vn = '#C0x5c9970# Hiệu ứng đảo ngược thế giới đi kèm với việc hoán đổi ngẫu nhiên vị trí hàng trước và hàng sau của kẻ địch và được giới hạn một lần trong toàn bộ trò chơi.',
		upLvDesc = 'Fixed damage +192',
