	[24011] = {
		id = 24011,
		skillName_vn = 'Nguyệt Quán Phi Kích',
		skillName_en = 'Moon Pavilion Strike',
		skillName_th = 'หมู่ตึกพระจันทร์โจมตี',
		skillName_in = 'Serangan Paviliun Bulan',
		skillName_ph = 'Lusob ng Moon Pavilion',
		skillName_ma = 'Serangan Paviliun Bulan',
		skillName = 'Moon Pavilion Strike',
		describe_vn = 'Tsukino Usagi triệu hồi Moon Shadow tấn công một mục tiêu kẻ địch, gây ra #C0x3D8A99#150% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#,\nFull Moon Phase: Tăng khả năng giảm sát thương thêm 10% trong 2 lượt cho tướng thân thiện có HP thấp nhất.\nMới Giai đoạn mặt trăng: Hồi phục 10% HP từ Moon Hare cho anh hùng thân thiện có lượng HP thấp nhất.',
		describe_en = 'Tsukino Usagi summons Moon Shadow to attack an enemy target, dealing #C0x3D8A99#150% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magical Damage #C0x5B545B#. \nFull Moon Phase: Increases damage reduction by 10% for 2 turns for the friendly hero with the lowest HP. \nNew Moon Phase: Restores 10% HP from Moon Hare to the friendly hero with the lowest HP.',
		describe_th = 'ซึกิโนะ อูซางิ ใช้ท่า Moon Shadow โจมตีเป้าหมายศัตรู 1 ตัว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#150%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B#. \nFull Moon Phase: เพิ่มการลดความเสียหาย 10% เป็นเวลา 2 เทิร์นแก่ฮีโร่ฝ่ายเรา ที่มี HP ต่ำที่สุด \nNew Moon Phase: ฟื้นฟู HP 10% จาก Moon Hare แก่ฮีโร่ฝ่ายเราที่มี HP ต่ำที่สุด',
		describe_in = 'Tsukino Usagi memanggil Moon Shadow untuk menyerang satu target musuh, memberikan #C0x3D8A99#150% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerusakan Magis #C0x5B545B#. \nFase Bulan Purnama: Meningkatkan pengurangan kerusakan sebesar 10% selama 2 giliran untuk pahlawan ramah dengan HP terendah. \nFase Bulan Baru: Memulihkan 10% HP dari Moon Hare pada pahlawan ramah dengan HP terendah.',
		describe_ph = 'Pinapatawag ni Tsukino Usagi ang Moon Shadow upang atakihin ang isang kaaway, na nagdudulot ng #C0x3D8A99#150% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magical Damage #C0x5B545B#. \nFull Moon Phase: Nagdaragdag ng 10% na damage reduction sa loob ng 2 turn para sa kaibigan na bayani na may pinakamababang HP. \nNew Moon Phase: Nagpapagaling ng 10% HP mula sa Moon Hare sa kaibigan na bayani na may pinakamababang HP.',
		describe_ma = 'Tsukino Usagi memanggil Moon Shadow untuk menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#150% Kerosakan Ajaib#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerosakan Ajaib #C0x5B545B#. \nFasa Bulan Purnama: Meningkatkan pengurangan kerosakan sebanyak 10% selama 2 pusingan kepada wira mesra dengan HP terendah. \nFasa Bulan Baru: Memulihkan 10% HP dari Moon Hare kepada wira mesra dengan HP terendah.',
		describe = 'Tsukino Usagi summons Moon Shadow to attack an enemy target, dealing #C0x3D8A99#150% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magical Damage #C0x5B545B#. \nFull Moon Phase: Increases damage reduction by 10% for 2 turns for the friendly hero with the lowest HP. \nNew Moon Phase: Restores 10% HP from Moon Hare to the friendly hero with the lowest HP.',
		simDesc_vn = 'Tsukino Usagi triệu hồi Moon Shadow để tấn công một mục tiêu kẻ địch.',
		simDesc_en = 'Tsukino Usagi summons Moon Shadow to attack an enemy target.',
		simDesc_th = 'ซึกิโนะ อุซางิ เรียกมูนแชโดว์โจมตีเป้าหมายศัตรู',
		simDesc_in = 'Tsukino Usagi memanggil Moon Shadow untuk menyerang target musuh.',
		simDesc_ph = 'Si Tsukino Usagi ay nag-summon ng Moon Shadow para atakihin ang isang target na kalaban.',
		simDesc_ma = 'Tsukino Usagi memanggil Moon Shadow untuk menyerang sasaran musuh.',
		simDesc = 'Tsukino Usagi summons Moon Shadow to attack an enemy target.',
		zawakeEffect = __data_t__zawakeEffect[24011],
		-- {79001}
		zawakeEffectDesc = 'Tsukino Usagi summons Moon Shadow to attack a single enemy, dealing #C0x3D8A99#150% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54 #MagicDamage#C0x5B545B#. \nFull Moon Phase: Increases damage reduction by 15% for 2 turns to the friendly hero with the lowest HP. \nNew Moon Phase: Recovers 15% HP from Moon Hare for the friendly hero with the lowest HP.',
		zawakeEffectDesc_en = 'Tsukino Usagi summons Moon Shadow to attack a single enemy, dealing #C0x3D8A99#150% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54 #MagicDamage#C0x5B545B#. \nFull Moon Phase: Increases damage reduction by 15% for 2 turns to the friendly hero with the lowest HP. \nNew Moon Phase: Recovers 15% HP from Moon Hare for the friendly hero with the lowest HP.',
		zawakeEffectDesc_th = 'Tsukino Usagi เรียก Moon Shadow โจมตีเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหายเวท #C0x3D8A99#150%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54 #MagicDamage#C0x5B545B#. \nFull Moon Phase: เพิ่มการลดความเสียหายอีก 15% เป็นเวลา 2 เทิร์นให้กับฮีโร่ฝ่ายเดียวที่มีพีซีต่ำที่สุด \nNew Moon Phase: ฟื้นฟูพีซี 15% จาก Moon Hare ให้ฮีโร่ฝ่ายเดียวที่มีพีซีต่ำที่สุด',
		zawakeEffectDesc_in = 'Tsukino Usagi memanggil Moon Shadow untuk menyerang satu musuh, menyebabkan #C0x3D8A99#150% Damage Magic#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54 #MagicDamage#C0x5B545B#. \nFull Moon Phase: Meningkatkan pengurangan damage sebesar 15% selama 2 giliran untuk pahlawan teman dengan HP terendah. \nNew Moon Phase: Memulihkan 15% HP dari Moon Hare untuk pahlawan teman dengan HP terendah.',
		zawakeEffectDesc_ph = 'Tsukino Usagi summons Moon Shadow to attack one enemy target, dealing #C0x3D8A99#150% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54 #MagicDamage#C0x5B545B#. \nFull Moon Phase: Increases damage reduction by 15% for 2 turns to the friendly hero with the lowest HP. \nNew Moon Phase: Recovers 15% HP from Moon Hare for the friendly hero with the lowest HP.',
		zawakeEffectDesc_ma = 'Tsukino Usagi memanggil Moon Shadow untuk menyerang satu musuh, menyebabkan #C0x3D8A99#150% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54 #MagicDamage#C0x5B545B#. \nFull Moon Phase: Meningkatkan pengurangan kerosakan sebanyak 15% selama 2 pusingan untuk wira mesra dengan HP terendah. \nNew Moon Phase: Memulihkan 15% HP daripada Moon Hare untuk wira mesra dengan HP terendah.',
		zawakeEffectDesc_vn = 'Tsukino Usagi triệu hồi Moon Shadow tấn công một mục tiêu kẻ địch, gây ra #C0x3D8A99#150% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54 #MagicDamage#C0x5B545B#,\nFull Moon Phase: Tăng khả năng giảm sát thương thêm 15% trong 2 lượt cho tướng thân thiện có HP thấp nhất.\nMới Giai đoạn mặt trăng: Hồi phục 15% HP từ Moon Hare cho anh hùng thân thiện có lượng HP thấp nhất.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Full Moon Phase: Increases damage reduction by 10% for 2 turns for the friendly hero with the lowest HP ratio\nWaxing Moon Phase: Heals 10% HP from the Moon Hare for the friendly hero with the lowest HP ratio\n#F20# \n#F40##C0x5c9970#→Full Moon Phase: Increases damage reduction by 15% for 2 turns for the friendly hero with the lowest HP ratio\nNew Moon Phase: Restores 15% HP to the friendly hero with the lowest HP ratio based on the Moon Hare\'s HP',
		zawakeSimpleDesc_en = 'Full Moon Phase: Increases damage reduction by 10% for 2 turns for the friendly hero with the lowest HP ratio\nWaxing Moon Phase: Heals 10% HP from the Moon Hare for the friendly hero with the lowest HP ratio\n#F20# \n#F40##C0x5c9970#→Full Moon Phase: Increases damage reduction by 15% for 2 turns for the friendly hero with the lowest HP ratio\nNew Moon Phase: Restores 15% HP to the friendly hero with the lowest HP ratio based on the Moon Hare\'s HP',
		zawakeSimpleDesc_th = 'ช่วงพระจันทร์เต็มดวง: เพิ่มการลดความเสียหาย 10% เป็นเวลา 2 เทิร์นให้กับฮีโร่ฝ่ายเดียวกันที่มีเลือดต่ำที่สุด\nช่วงพระจันทร์ข้างขึ้น: ฟื้นฟู 10% HP จากกระต่ายจันทร์ให้ฮีโร่ฝ่ายเดียวกันที่มีเลือดต่ำที่สุด\n#F20# \n#F40##C0x5c9970#→ช่วงพระจันทร์เต็มดวง: เพิ่มการลดความเสียหาย 15% เป็นเวลา 2 เทิร์นให้กับฮีโร่ฝ่ายเดียวกันที่มีเลือดต่ำที่สุด\nช่วงพระจันทร์ใหม่: ฟื้นฟู HP 15% ให้ฮีโร่ฝ่ายเดียวกันที่มีเลือดต่ำที่สุดโดยอิงจาก HP ของกระต่ายจันทร์',
		zawakeSimpleDesc_in = 'Fase Bulan Purnama: Meningkatkan pengurangan damage sebesar 10% selama 2 giliran untuk hero teman dengan rasio HP terendah\nFase Bulan Sabit: Memulihkan 10% HP dari Kelinci Bulan untuk hero teman dengan rasio HP terendah\n#F20# \n#F40##C0x5c9970#→Fase Bulan Purnama: Meningkatkan pengurangan damage sebesar 15% selama 2 giliran untuk hero teman dengan rasio HP terendah\nFase Bulan Baru: Memulihkan 15% HP kepada hero teman dengan rasio HP terendah berdasarkan HP Kelinci Bulan',
		zawakeSimpleDesc_ph = 'Full Moon Phase: Dagdagan ng 10% damage reduction sa loob ng 2 turn para sa kakamping may pinakamababang HP ratio\nWaxing Moon Phase: Maghilom ng 10% HP mula sa Moon Hare para sa kakamping may pinakamababang HP ratio\n#F20# \n#F40##C0x5c9970#→Full Moon Phase: Dagdagan ng 15% damage reduction sa loob ng 2 turn para sa kakamping may pinakamababang HP ratio\nNew Moon Phase: Maghilom ng 15% HP batay sa HP ng Moon Hare para sa kakamping may pinakamababang HP ratio',
		zawakeSimpleDesc_ma = 'Fasa Bulan Purnama: Meningkatkan pengurangan kerosakan sebanyak 10% selama 2 giliran untuk hero sekutu dengan nisbah HP paling rendah\nFasa Bulan Sabit: Memulihkan 10% HP dari Arnab Bulan kepada hero sekutu dengan nisbah HP paling rendah\n#F20# \n#F40##C0x5c9970#→Fasa Bulan Purnama: Meningkatkan pengurangan kerosakan sebanyak 15% selama 2 giliran untuk hero sekutu dengan nisbah HP paling rendah\nFasa Bulan Baru: Memulihkan 15% HP kepada hero sekutu dengan nisbah HP paling rendah berdasarkan HP Arnab Bulan',
		zawakeSimpleDesc_vn = 'Giai đoạn Trăng tròn: Tăng 10% khả năng giảm sát thương trong 2 lượt cho anh hùng thân thiện có tỷ lệ máu thấp nhất\nGiai đoạn Trăng non: Hồi 10% máu từ Thỏ Mặt trăng cho anh hùng thân thiện có tỷ lệ máu thấp nhất\n#F20# \n#F40##C0x5c9970#→Giai đoạn Trăng tròn: Tăng 15% khả năng giảm sát thương trong 2 lượt cho anh hùng thân thiện có tỷ lệ máu thấp nhất\nGiai đoạn Trăng mới: Hồi máu 15% về lượng máu của người anh hùng thân thiện có tỷ lệ máu thấp nhất so với Moon Hare',
		upLvDesc = 'Fixed damage +96',
		upLvDesc_en = 'Fixed damage +96',
		upLvDesc_th = 'ความเสียหายคงที่ +96',
