	[24012] = {
		id = 24012,
		skillName_vn = 'Lễ rửa tội dưới ánh trăng',
		skillName_en = 'Baptism under the moonlight',
		skillName_th = 'พิธีล้างบาปใต้แสงจันทร์',
		skillName_in = 'Pembaptisan di bawah sinar bulan',
		skillName_ph = 'Binyag sa ilalim ng liwanag ng buwan',
		skillName_ma = 'Pembaptisan di bawah sinar bulan',
		skillName = 'Baptism under the moonlight',
		describe_vn = 'Tsukino Usagi sử dụng sức mạnh của ánh trăng để phát ra ánh sáng, chữa lành máu cho một mục tiêu thân thiện ở hàng trước #C0x3D8A99#250% Sát Thương Phép Thuật #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# và khiến mục tiêu rơi vào trạng thái [Sweet Dream]. Nếu nó thức dậy vào giai đoạn trăng non, nó sẽ khôi phục 400 điểm thịnh nộ cho mục tiêu. Nếu nó thức dậy vào thời điểm trăng tròn, nó sẽ được miễn nhiễm một lần.',
		describe_en = 'Tsukino Usagi uses the power of the moonlight to emit light, healing the blood of a friendly target in the front row. #C0x3D8A99#250% Magical Damage #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magical Damage #C0x5B545B# and causes the target to enter the [Sweet Dream] state. If they wake up during the new moon phase, they will restore 400 rage points. If they wake up at the full moon, they will become immune once.',
		describe_th = 'สึกิโนะ อุซางิ ใช้พลังของแสงจันทร์เพื่อส่องสว่าง รักษาเลือดของเป้าหมายฝ่ายเดียวในแถวหน้า #C0x3D8A99#250% ความเสียหายเวทย์มนตร์ #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวทย์มนตร์ #C0x5B545B# และทำให้เป้าหมายเข้าสู่สถานะ [Sweet Dream] หากเป้าหมายตื่นในช่วงข้างขึ้น จะฟื้นฟูพลังโกรธ 400 แต้ม หากตื่นในช่วงจันทร์เต็มดวง จะได้รับการป้องกันสถานะครั้งหนึ่ง',
		describe_in = 'Tsukino Usagi menggunakan kekuatan cahaya bulan untuk memancarkan cahaya, menyembuhkan darah target ramah di barisan depan. #C0x3D8A99#250% Kerusakan Sihir #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B# dan menyebabkan target memasuki status [Sweet Dream]. Jika terbangun pada fase bulan baru, akan memulihkan 400 poin kemarahan. Jika terbangun pada saat bulan purnama, akan mendapatkan kekebalan satu kali.',
		describe_ph = 'Gumagamit si Tsukino Usagi ng kapangyarihan ng liwanag ng buwan upang maglabas ng liwanag, nagpapagaling ng dugo sa isang kaibigang target sa harapang hanay. #C0x3D8A99#250% Magical Damage #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magical Damage #C0x5B545B# at nagdudulot sa target na mapunta sa estado ng [Sweet Dream]. Kung magigising siya sa yugto ng bagong buwan, mapapanumbalik nito ang 400 punto ng galit. Kung magigising siya sa panahon ng kabilugan ng buwan, magkakaroon siya ng isang pagkakataon ng immunity.',
		describe_ma = 'Tsukino Usagi menggunakan kuasa cahaya bulan untuk memancarkan cahaya, menyembuhkan darah sasaran mesra di barisan hadapan. #C0x3D8A99#250% Kerosakan Sihir #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B# dan menyebabkan sasaran memasuki keadaan [Sweet Dream]. Jika bangun semasa fasa bulan baru, ia akan memulihkan 400 mata kemarahan. Jika bangun pada waktu bulan purnama, ia akan mendapat imuniti sekali.',
		describe = 'Tsukino Usagi uses the power of the moonlight to emit light, healing the blood of a friendly target in the front row. #C0x3D8A99#250% Magical Damage #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magical Damage #C0x5B545B# and causes the target to enter the [Sweet Dream] state. If they wake up during the new moon phase, they will restore 400 rage points. If they wake up at the full moon, they will become immune once.',
		simDesc_vn = 'Tsukino Usagi sử dụng sức mạnh của ánh trăng để phát ra ánh sáng và chữa lành vết thương cho một mục tiêu thân thiện ở hàng ghế đầu.',
		simDesc_en = 'Tsukino Usagi uses the power of the moonlight to emit light and heal the wounds of a friendly target in the front row.',
		simDesc_th = 'ซึกิโนะ อูซางิ ใช้พลังแสงจันทร์เพื่อส่งแสงและรักษาบาดแผลให้กับเป้าหมายที่เป็นมิตรในแถวหน้า',
		simDesc_in = 'Tsukino Usagi menggunakan kekuatan sinar bulan untuk mengeluarkan cahaya dan menyembuhkan luka pada target ramah di barisan depan.',
		simDesc_ph = 'Gumagamit si Tsukino Usagi ng kapangyarihan ng sinag ng buwan upang magbuga ng liwanag at pagalingin ang mga sugat ng isang kaibigang target sa front row.',
		simDesc_ma = 'Tsukino Usagi menggunakan kekuatan sinar bulan untuk memancarkan cahaya dan menyembuhkan luka pada sasaran mesra di barisan hadapan.',
		simDesc = 'Tsukino Usagi uses the power of the moonlight to emit light and heal the wounds of a friendly target in the front row.',
		zawakeEffect = __data_t__zawakeEffect[24012],
		-- {79002}
		zawakeEffectDesc = 'Tsukino Usagi uses the power of the moonlight to emit light, healing blood for a friendly target in the front row #C0x3D8A99#250% Magic Damage #C0x5B545B#+$(skillLevel*4*48)$ and causing the target to enter <Sweet Dream> state. If it wakes up during the new moon phase, it restores 400 rage points to the target. If it wakes up during the full moon phase, it will be immune once.',
		zawakeEffectDesc_en = 'Tsukino Usagi uses the power of the moonlight to emit light, healing blood for a friendly target in the front row #C0x3D8A99#250% Magic Damage #C0x5B545B#+$(skillLevel*4*48)$ and causing the target to enter <Sweet Dream> state. If it wakes up during the new moon phase, it restores 400 rage points to the target. If it wakes up during the full moon phase, it will be immune once.',
		zawakeEffectDesc_th = 'Tsukino Usagi ใช้พลังของแสงจันทร์เพื่อปล่อยแสง รักษาเลือดให้เป้าหมายที่เป็นมิตรในแถวหน้า #C0x3D8A99#250% ความเสียหายเวทมนตร์ #C0x5B545B#+$(skillLevel*4*48)$ และทำให้เป้าหมายเข้าสู่สถานะ <Sweet Dream> หากมันตื่นขึ้นในช่วงจันทร์ใหม่ จะฟื้นฟู 400 คะแนนความโกรธให้กับเป้าหมาย หากมันตื่นขึ้นในช่วงจันทร์เต็มดวง จะได้รับการป้องกันการติดสถานะครั้งหนึ่ง',
		zawakeEffectDesc_in = 'Tsukino Usagi menggunakan kekuatan cahaya bulan untuk memancarkan cahaya, menyembuhkan darah untuk target ramah di baris depan #C0x3D8A99#250% Kerusakan Sihir #C0x5B545B#+$(skillLevel*4*48)$ dan menyebabkan target memasuki keadaan <Sweet Dream>. Jika terbangun saat fase bulan baru, akan memulihkan 400 poin kemarahan untuk target. Jika terbangun saat fase bulan purnama, akan kebal sekali.',
		zawakeEffectDesc_ph = 'Gumagamit si Tsukino Usagi ng kapangyarihan ng liwanag ng buwan para maglabas ng liwanag, nagpapagaling ng dugo sa isang kaibigang target sa harapang hanay #C0x3D8A99#250% Magic Damage #C0x5B545B#+$(skillLevel*4*48)$ at pinapasok ang target sa estado ng <Sweet Dream>. Kung magigising ito sa panahon ng new moon, magbabalik ito ng 400 puntos ng galit para sa target. Kung magigising ito sa panahon ng full moon, magiging immune ito isang beses.',
		zawakeEffectDesc_ma = 'Tsukino Usagi menggunakan kekuatan cahaya bulan untuk memancarkan cahaya, menyembuhkan darah untuk sasaran mesra di barisan hadapan #C0x3D8A99#250% Kerosakan Sihir #C0x5B545B#+$(skillLevel*4*48)$ dan menyebabkan sasaran memasuki keadaan <Sweet Dream>. Jika bangun semasa fasa bulan baru, ia akan memulihkan 400 mata kemarahan untuk sasaran. Jika bangun semasa fasa bulan penuh, ia akan kebal sekali.',
		zawakeEffectDesc_vn = 'Tsukino Usagi sử dụng sức mạnh của ánh trăng để phát ra ánh sáng, chữa lành máu cho một mục tiêu thân thiện ở hàng trước #C0x3D8A99#250% Sát Thương Phép Thuật #C0x5B545B#+$(skillLevel*4*48)$ và khiến mục tiêu rơi vào trạng thái <Sweet Dream>. Nếu nó thức dậy vào giai đoạn trăng non, nó sẽ khôi phục 400 điểm thịnh nộ cho mục tiêu. Nếu nó thức dậy vào thời điểm trăng tròn, nó sẽ được miễn nhiễm một lần.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Healing coefficient increased by 30%',
