	[24013] = {
		id = 24013,
		skillName_vn = 'Nguyệt Công Chúa Hoa Quang',
		skillName_en = 'Princess Nguyet Hoa Quang',
		skillName_th = 'เจ้าหญิงเหงว็ยท์ ฮวา กวาง',
		skillName_in = 'Putri Nguyet Hoa Quang',
		skillName_ph = 'Prinsesa Nguyet Hoa Quang',
		skillName_ma = 'Puteri Nguyet Hoa Quang',
		skillName = 'Princess Nguyet Hoa Quang',
		describe_vn = 'Tsukino Usagi bay xuống từ giữa mặt trăng, tỏa sáng rực rỡ ở bất cứ nơi nào anh ta đi qua, chữa lành máu cho mục tiêu thân thiện có tỷ lệ máu thấp nhất #C0x3D8A99#580% Tấn Công Phép thuật#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, và khiến mục tiêu đó rơi vào trạng thái [Giấc mơ ngọt ngào] và tiêu tan toàn bộ máu sau khi rời khỏi giấc mơ. Hiệu ứng tiêu cực và kiểm soát\n (Giấc mơ: hiệu ứng đặc biệt, không thể di chuyển, không thể xua tan. Trong thời gian này, sẽ nhận được một lá chắn đặc biệt bằng với lượng máu tối đa của mục tiêu và trạng thái giấc mơ ngọt ngào sẽ được giải phóng trước lượt tiếp theo của mục tiêu. Nếu lá chắn bị vỡ, giấc mơ ngọt ngào sẽ kết thúc sớm và kẻ địch tấn công mục tiêu trong [Giấc mơ] sẽ có 80% khả năng rơi vào [Ngủ] trong 1 hiệp)',
		describe_en = 'Tsukino Usagi descends from the middle of the moon, shining brilliantly wherever he goes, healing blood for the friendly target with the lowest health percentage by 580% Magic Attack + $(skillLevel*4*90)$ Magic Damage, and causing that target to enter the [Sweet Dream] state and lose all blood after leaving the dream. Negative effects and control o0oo (Dream: special effect, unable to move, cannot be dispelled. During this time, the target receives a special shield equal to their maximum health and the Sweet Dream state is released before the target’s next turn. If the shield breaks, Sweet Dream ends early and enemies attacking the target in [Dream] have an 80% chance to fall asleep for 1 turn.)',
		describe_th = 'สึคิโนะ อูซางิ บินลงมาจากกลางดวงจันทร์ เปล่งประกายเจิดจ้าที่ทุกที่ที่เขาผ่านไป รักษาค่าพลังชีวิตให้เป้าหมายฝ่ายดีที่มีเปอร์เซ็นต์พลังชีวิตต่ำที่สุด โดยมีพลังโจมตีเวทย์มนตร์ 580% + $(skillLevel*4*90)$ ความเสียหายเวทย์มนตร์ และทำให้เป้าหมายเข้าสู่สถานะ [Sweet Dream] และสูญเสียพลังชีวิตทั้งหมดหลังออกจากความฝัน ผลกระทบลบและควบคุม o0oo (ความฝัน: เอฟเฟกต์พิเศษ ไม่สามารถเคลื่อนที่และไม่สามารถขจัดออกได้ ในระหว่างนี้ จะได้รับโล่พิเศษเท่ากับพลังชีวิตสูงสุดของเป้าหมาย และสถานะ Sweet Dream จะถูกปลดปล่อยก่อนเทิร์นถัดไปของเป้าหมาย หากโล่แตก Sweet Dream จะสิ้นสุดก่อนเวลา และศัตรูที่โจมตีเป้าหมายใน [Dream] จะมีโอกาส 80% ที่จะหลับเป็นเวลา 1 เทิร์น)',
		describe_in = 'Tsukino Usagi turun dari tengah bulan, bersinar terang di mana pun dia pergi, menyembuhkan darah untuk target ramah dengan persentase darah terendah sebesar 580% Serangan Sihir + $(skillLevel*4*90)$ Kerusakan Sihir, dan menyebabkan target tersebut memasuki status [Sweet Dream] dan kehilangan semua darah setelah keluar dari mimpi. Efek negatif dan kontrol o0oo (Mimpi: efek khusus, tidak bisa bergerak, tidak bisa dihilangkan. Selama waktu ini, target menerima perisai khusus sebesar darah maksimal mereka dan status Sweet Dream akan dilepaskan sebelum giliran target berikutnya. Jika perisai pecah, Sweet Dream berakhir lebih awal dan musuh yang menyerang target dalam [Dream] memiliki peluang 80% tertidur selama 1 giliran.)',
		describe_ph = 'Si Tsukino Usagi ay bumaba mula sa gitna ng buwan, nagliliwanag nang maliwanag saan man siya magpunta, nagpapagaling ng dugo para sa kaibigang target na may pinakamababang porsyento ng buhay na 580% Magic Attack + $(skillLevel*4*90)$ Magic Damage, at pinapasok ang target sa estado ng [Sweet Dream] at nawawala ang lahat ng dugo pagkatapos umalis sa panaginip. Negatibong epekto at kontrol o0oo (Pangarap: espesyal na epekto, hindi makagalaw, hindi matanggal. Sa panahong ito, makakatanggap ang target ng espesyal na kalasag na katumbas ng pinakamataas na buhay nila at ang estado ng Sweet Dream ay mawawala bago ang susunod na turn ng target. Kung masira ang kalasag, magtatapos nang maaga ang Sweet Dream at ang kalaban na umatake sa target sa [Dream] ay may 80% tsansa na makatulog para sa 1 turn.)',
		describe_ma = 'Tsukino Usagi turun dari tengah bulan, bersinar terang di mana sahaja dia pergi, menyembuhkan darah untuk sasaran bersahabat dengan peratusan darah paling rendah sebanyak 580% Serangan Sihir + $(skillLevel*4*90)$ Kerosakan Sihir, dan menyebabkan sasaran itu memasuki keadaan [Sweet Dream] dan hilang semua darah selepas keluar dari mimpi. Kesan negatif dan kawalan o0oo (Mimpi: kesan khas, tidak boleh bergerak, tidak boleh dihapuskan. Sepanjang tempoh ini, sasaran menerima perisai khas bersamaan dengan darah maksimum mereka dan keadaan Sweet Dream akan dilepaskan sebelum giliran sasaran berikutnya. Jika perisai pecah, Sweet Dream berakhir awal dan musuh yang menyerang sasaran dalam [Dream] mempunyai peluang 80% untuk tertidur selama 1 giliran.)',
		describe = 'Tsukino Usagi descends from the middle of the moon, shining brilliantly wherever he goes, healing blood for the friendly target with the lowest health percentage by 580% Magic Attack + $(skillLevel*4*90)$ Magic Damage, and causing that target to enter the [Sweet Dream] state and lose all blood after leaving the dream. Negative effects and control o0oo (Dream: special effect, unable to move, cannot be dispelled. During this time, the target receives a special shield equal to their maximum health and the Sweet Dream state is released before the target’s next turn. If the shield breaks, Sweet Dream ends early and enemies attacking the target in [Dream] have an 80% chance to fall asleep for 1 turn.)',
		simDesc_vn = 'Tsukino Usagi bay xuống từ giữa mặt trăng, tỏa sáng rực rỡ ở bất cứ nơi nào anh ta đến, chữa lành vết thương cho một mục tiêu thân thiện và đưa người anh hùng thân thiện có phần trăm máu thấp nhất vào trạng thái mơ.',
		simDesc_en = 'Tsukino Usagi descends from the middle of the moon, shining brightly wherever he goes, healing wounds of a friendly target and putting the friendly hero with the lowest health percentage into a dream state.',
		simDesc_th = 'Tsukino Usagi ร่วงลงมาจากกลางดวงจันทร์ เปล่งประกายสว่างไสวทุกที่ที่เขาไป รักษาแผลให้กับเป้าหมายที่เป็นมิตรและทำให้ฮีโร่ที่เป็นมิตรที่มีเปอร์เซ็นต์เลือดต่ำที่สุดเข้าสู่สถานะฝัน.',
		simDesc_in = 'Tsukino Usagi turun dari tengah bulan, bersinar terang di mana pun dia pergi, menyembuhkan luka pada target yang bersahabat dan memasukkan pahlawan bersahabat dengan persentase darah terendah ke dalam keadaan mimpi.',
		simDesc_ph = 'Si Tsukino Usagi ay bumaba mula sa gitna ng buwan, nagniningning sa kahit saan siya pumunta, nagpapagaling ng sugat sa isang kaibigang target at inilalagay ang kaibigang bayani na may pinakamababang porsyento ng buhay sa estado ng panaginip.',
		simDesc_ma = 'Tsukino Usagi turun dari tengah bulan, bersinar terang di mana sahaja dia pergi, menyembuhkan luka pada sasaran yang mesra dan meletakkan wira mesra dengan peratusan darah terendah ke dalam keadaan mimpi.',
		simDesc = 'Tsukino Usagi descends from the middle of the moon, shining brightly wherever he goes, healing wounds of a friendly target and putting the friendly hero with the lowest health percentage into a dream state.',
		starEffect = __data_t__starEffect[24013],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Dưới ánh trăng Non, lượng hồi phục dư thừa sẽ được phân chia cho các đồng đội khác; dưới ánh trăng Tròn, trong 2 lượt sau kỹ năng đặc biệt sẽ chuyển thành ánh trăng Non.',
		starEffectDesc = 'Additional Effect: Under the New Moon, excess healing will be distributed to other teammates; under the Full Moon, for the next 2 turns, the special skill will transform into the New Moon.',
		starEffectDesc_en = 'Additional Effect: Under the New Moon, excess healing will be distributed to other teammates; under the Full Moon, for the next 2 turns, the special skill will transform into the New Moon.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: ใต้แสงจันทร์เสี้ยว การฟื้นฟูส่วนเกินจะถูกแจกจ่ายให้เพื่อนร่วมทีมคนอื่น ๆ; ใต้แสงจันทร์เต็มดวง ใน 2 เทิร์นถัดไป สกิลพิเศษจะเปลี่ยนเป็นแสงจันทร์เสี้ยว',
		starEffectDesc_in = 'Efek Tambahan: Di bawah Bulan Sabit, penyembuhan berlebih akan dibagikan ke anggota tim lain; di bawah Bulan Purnama, selama 2 giliran berikutnya, keterampilan khusus akan berubah menjadi Bulan Sabit.',
		starEffectDesc_ph = 'Karagdagang Epekto: Sa ilalim ng Buwan na Siklista, ang sobrang paggaling ay ipapamahagi sa iba pang mga kasamahan sa koponan; sa ilalim ng Buong Buwan, sa loob ng 2 turn, ang espesyal na kasanayan ay magbabago sa Buwan na Siklista.',
		starEffectDesc_ma = 'Kesan Tambahan: Di bawah Bulan Sabit, pemulihan lebihan akan diagihkan kepada rakan sepasukan lain; di bawah Bulan Purnama, untuk 2 giliran akan datang, kemahiran khas akan bertukar menjadi Bulan Sabit.',
		zawakeEffect = __data_t__zawakeEffect[24013],
		-- {79003}
		zawakeEffectDesc = 'Tsukino Usagi descends from the middle of the moon, shining brightly wherever he goes, healing the friendly target with the lowest health rate #C0x3D8A99#680% Magic Attack#C0x5B545B#+$(skillLevel*4*90)$, and causing that target to enter the <Sweet Dream> state and lose all health after leaving the dream. Negative effects and controls o0oo (Dream: special effect, cannot move, cannot dispel. During this time, a special shield equal to the target\'s maximum health is gained and the sweet dream state will be released before the target\'s next turn. If the shield breaks, the sweet dream ends early and enemies attacking the target in <Dream> have a 100% chance to fall asleep for 1 turn).',
		zawakeEffectDesc_en = 'Tsukino Usagi descends from the middle of the moon, shining brightly wherever he goes, healing the friendly target with the lowest health rate #C0x3D8A99#680% Magic Attack#C0x5B545B#+$(skillLevel*4*90)$, and causing that target to enter the <Sweet Dream> state and lose all health after leaving the dream. Negative effects and controls o0oo (Dream: special effect, cannot move, cannot dispel. During this time, a special shield equal to the target\'s maximum health is gained and the sweet dream state will be released before the target\'s next turn. If the shield breaks, the sweet dream ends early and enemies attacking the target in <Dream> have a 100% chance to fall asleep for 1 turn).',
		zawakeEffectDesc_th = 'สึกิโนะ อูซางิ บินลงจากกลางดวงจันทร์ เปล่งประกายสว่างไสวทุกที่ที่เขาไป รักษาผู้เข้าร่วมฝ่ายเดียวกันที่มีค่าน้ำเลือดต่ำที่สุด #C0x3D8A99#680% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*90)$ และทำให้เป้าหมายเข้าสู่สถานะ <Sweet Dream> และสูญเสียเลือดทั้งหมดหลังออกจากฝัน ผลกระทบลบและการควบคุม o0oo (ฝัน: เอฟเฟกต์พิเศษ ไม่สามารถเคลื่อนที่ ไม่สามารถล้างสถานะ ในช่วงเวลานี้จะได้รับโล่พิเศษเท่ากับค่าพลังชีวิตสูงสุดของเป้าหมาย และสถานะ Sweet Dream จะถูกปลดปล่อยก่อนรอบถัดไปของเป้าหมาย หากโล่ถูกทำลาย Sweet Dream จะสิ้นสุดก่อนเวลา และศัตรูที่โจมตีเป้าหมายใน <Dream> จะมีโอกาส 100% ที่จะหลับใน 1 เทิร์น)',
		zawakeEffectDesc_in = 'Tsukino Usagi turun dari tengah bulan, bersinar terang di mana pun dia pergi, menyembuhkan target ramah dengan persentase darah terendah #C0x3D8A99#680% Serangan Sihir#C0x5B545B#+$(skillLevel*4*90)$, dan menyebabkan target tersebut memasuki status <Sweet Dream> serta kehilangan seluruh darah setelah keluar dari mimpi. Efek negatif dan kontrol o0oo (Mimpi: efek khusus, tidak bisa bergerak, tidak bisa dihilangkan. Selama waktu ini, akan mendapatkan perisai khusus sebesar darah maksimal target dan status sweet dream akan dilepaskan sebelum giliran berikutnya target. Jika perisai rusak, sweet dream berakhir lebih cepat dan musuh yang menyerang target dalam <Dream> memiliki peluang 100% untuk tertidur selama 1 giliran).',
		zawakeEffectDesc_ph = 'Si Tsukino Usagi ay bumababa mula sa gitna ng buwan, kumikinang nang maliwanag kahit saan siya pumunta, nagpapagaling sa kaibigang target na may pinakamababang porsyento ng buhay #C0x3D8A99#680% Magic Attack#C0x5B545B#+$(skillLevel*4*90)$, at pinapasok ang target sa estado ng <Sweet Dream> at mawalan ng lahat ng buhay pagkatapos umalis sa panaginip. Negatibong epekto at kontrol o0oo (Panaginip: espesyal na epekto, hindi makagalaw, hindi maaaring alisin. Sa panahong ito, makakakuha ng espesyal na kalasag na kasing-halaga ng maximum na buhay ng target at ang estado ng sweet dream ay aalisin bago ang susunod na turno ng target. Kung masira ang kalasag, matatapos nang maaga ang sweet dream at ang mga kalaban na umatake sa target sa <Dream> ay may 100% na tsansa na matulog sa loob ng 1 turn).',
		zawakeEffectDesc_ma = 'Tsukino Usagi turun dari tengah bulan, bersinar terang di mana sahaja dia pergi, menyembuhkan sasaran mesra dengan peratus darah terendah #C0x3D8A99#680% Serangan Sihir#C0x5B545B#+$(skillLevel*4*90)$, dan menyebabkan sasaran itu memasuki status <Sweet Dream> serta kehilangan semua darah selepas meninggalkan mimpi. Kesan negatif dan kawalan o0oo (Mimpi: kesan istimewa, tidak boleh bergerak, tidak boleh dihilangkan. Sepanjang masa ini, akan mendapat perisai istimewa bersamaan dengan jumlah darah maksimum sasaran dan status sweet dream akan dilepaskan sebelum giliran seterusnya sasaran. Jika perisai pecah, sweet dream tamat lebih awal dan musuh menyerang sasaran dalam <Dream> mempunyai peluang 100% untuk tidur selama 1 giliran).',
		zawakeEffectDesc_vn = 'Tsukino Usagi bay xuống từ giữa mặt trăng, tỏa sáng rực rỡ ở bất cứ nơi nào anh ta đến, chữa lành máu cho mục tiêu thân thiện có tỷ lệ máu thấp nhất #C0x3D8A99#680% Tấn Công Phép thuật#C0x5B545B#+$(skillLevel*4*90)$, và khiến mục tiêu đó rơi vào trạng thái <Giấc mơ ngọt ngào> và tiêu tan toàn bộ máu sau khi rời khỏi giấc mơ. Hiệu ứng tiêu cực và kiểm soát\n (Giấc mơ: hiệu ứng đặc biệt, không thể di chuyển, không thể xua tan. Trong thời gian này, người ta sẽ nhận được một lá chắn đặc biệt bằng với lượng máu tối đa của mục tiêu và trạng thái giấc mơ ngọt ngào sẽ được giải phóng trước lượt tiếp theo của mục tiêu. Nếu lá chắn bị vỡ, giấc mơ ngọt ngào sẽ kết thúc sớm và kẻ địch tấn công mục tiêu trong <Giấc mơ> sẽ có 100% xác suất rơi vào <Ngủ> trong 1 hiệp)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Healing amount increased from 550% to 680%, and sleep chance increased to 100%',
		zawakeSimpleDesc_en = 'Healing amount increased from 550% to 680%, and sleep chance increased to 100%',
		zawakeSimpleDesc_th = 'ปริมาณการรักษาเพิ่มจาก 550% เป็น 680% และโอกาสหลับเพิ่มเป็น 100%',
		zawakeSimpleDesc_in = 'Jumlah penyembuhan meningkat dari 550% menjadi 680% dan peluang tidur meningkat menjadi 100%',
		zawakeSimpleDesc_ph = 'Ang healing ay tumaas mula 550% hanggang 680% at ang chance ng pagkatulog ay naging 100%',
