	[24016] = {
		id = 24016,
		skillName_vn = 'Thủy Thủ Mặt Trăng',
		skillName_en = 'Sailor Moon',
		skillName_th = 'เซเลอร์มูน',
		skillName_in = 'Sailor Moon',
		skillName_ph = 'Sailor Moon',
		skillName_ma = 'Sailor Moon',
		skillName = 'Sailor Moon',
		describe_vn = 'Một vòng duy nhất là giai đoạn trăng tròn, nâng cao bản thân #C0x5c9970#$(10+skillLevel*0.15-0.15)$%#C0x5B545B# phòng thủ kép (không thể xua tan);\nVòng đôi là giai đoạn trăng mới, Cải thiện bản thân #C0x5c9970#$(30+skillLevel*0.35-0.35)$%#C0x5B545B# tốc độ hồi phục (không thể xua tan);\nXóa bỏ hiệu ứng ngủ của chính mình ngay lập tức khi ngủ.',
		describe_en = 'A single circle is the full moon phase, enhancing yourself by #C0x5c9970#$(10+skillLevel*0.15-0.15)$%#C0x5B545B# double defense (cannot be dispelled);\nDouble circles are the new moon phase, improving yourself by #C0x5c9970#$(30+skillLevel*0.35-0.35)$%#C0x5B545B# recovery speed (cannot be dispelled);\nInstantly removes your own sleep effect upon falling asleep.',
		describe_th = 'วงเดี่ยวคือช่วงพระจันทร์เต็มดวง เสริมพลังตัวเอง #C0x5c9970#$(10+skillLevel*0.15-0.15)$%#C0x5B545B# ป้องกันคู่ (ไม่สามารถลบได้);\nวงคู่คือช่วงพระจันทร์ใหม่ ปรับปรุงตัวเอง #C0x5c9970#$(30+skillLevel*0.35-0.35)$%#C0x5B545B# ความเร็วการฟื้นฟู (ไม่สามารถลบได้);\nลบสถานะหลับของตัวเองทันทีเมื่อหลับ',
		describe_in = 'Satu lingkaran adalah fase bulan purnama, meningkatkan diri sendiri sebesar #C0x5c9970#$(10+skillLevel*0.15-0.15)$%#C0x5B545B# pertahanan ganda (tidak dapat dihapus);\nLingkaran ganda adalah fase bulan baru, memperbaiki diri sendiri sebesar #C0x5c9970#$(30+skillLevel*0.35-0.35)$%#C0x5B545B# kecepatan pemulihan (tidak dapat dihapus);\nSegera menghapus efek tidur diri sendiri saat tertidur.',
		describe_ph = 'Ang isang bilog lang ay ang full moon phase, nagpapalakas ng sarili ng #C0x5c9970#$(10+skillLevel*0.15-0.15)$%#C0x5B545B# doble na depensa (hindi maaaring tanggalin);\nAng dalawang bilog ay ang new moon phase, nagpapabuti ng sarili ng #C0x5c9970#$(30+skillLevel*0.35-0.35)$%#C0x5B545B# bilis ng paggaling (hindi maaaring tanggalin);\nAgad na tinatanggal ang sariling sleeping effect kapag natutulog.',
		describe_ma = 'Satu pusingan adalah fasa bulan purnama, meningkatkan diri sendiri sebanyak #C0x5c9970#$(10+skillLevel*0.15-0.15)$%#C0x5B545B# pertahanan berganda (tidak boleh dibuang);\nPusingan berganda adalah fasa bulan baru, memperbaiki diri sendiri sebanyak #C0x5c9970#$(30+skillLevel*0.35-0.35)$%#C0x5B545B# kelajuan pemulihan (tidak boleh dibuang);\nSerentak menghapus kesan tidur sendiri apabila tidur.',
		describe = 'A single circle is the full moon phase, enhancing yourself by #C0x5c9970#$(10+skillLevel*0.15-0.15)$%#C0x5B545B# double defense (cannot be dispelled);\nDouble circles are the new moon phase, improving yourself by #C0x5c9970#$(30+skillLevel*0.35-0.35)$%#C0x5B545B# recovery speed (cannot be dispelled);\nInstantly removes your own sleep effect upon falling asleep.',
		starEffect = __data_t__starEffect[24016],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng thêm: Kỹ năng hào quang: Khi bất kỳ mục tiêu nào trên sân bị hiệu ứng <Ngủ>, hồi máu cho đồng minh có tỷ lệ máu thấp nhất tương đương 10% máu của Thủy thủ Mặt Trăng.',
		starEffectDesc = 'Additional Effect: Aura Skill: When any target on the field is affected by <Sleep>, heal the ally with the lowest HP for an amount equal to 10% of Sailor Moon\'s HP.',
		starEffectDesc_en = 'Additional Effect: Aura Skill: When any target on the field is affected by <Sleep>, heal the ally with the lowest HP for an amount equal to 10% of Sailor Moon\'s HP.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ทักษะออร่า: เมื่อเป้าหมายใด ๆ บนสนามโดนผล <หลับ>, ฟื้นฟูพลังชีวิตให้กับพันธมิตรที่มีพลังชีวิตต่ำที่สุดโดยเท่ากับ 10% ของพลังชีวิตของเซเลอร์มูน',
		starEffectDesc_in = 'Efek tambahan: Skill Aura: Ketika target mana pun di medan terkena efek <Tidur>, sembuhkan sekutu dengan HP terendah sebesar 10% dari HP Sailor Moon.',
		starEffectDesc_ph = 'Karagdagang Epekto: Aura Skill: Kapag ang sinumang target sa larangan ay naapektuhan ng <Tulog>, pagalingin ang kasaping may pinakamababang HP ng katumbas na 10% ng HP ni Sailor Moon.',
		starEffectDesc_ma = 'Kesan tambahan: Kemahiran aura: Apabila mana-mana sasaran di medan terkena kesan <Tidur>, pulihkan rakan sepasukan yang mempunyai HP paling rendah dengan jumlah bersamaan 10% HP Sailor Moon.',
		zawakeEffect = __data_t__zawakeEffect[24016],
		-- {79004}
		zawakeEffectDesc = 'A single round is the full moon phase, improving oneself by #C0x5c9970#$(30+skillLevel*0.15-0.15)$%#C0x5B545B# dual defense (cannot be dispelled);\nA double round is the new moon phase, enhancing a person\'s #C0x5c9970#$(40+skillLevel*0.35-0.35)$%#C0x5B545B# recovery speed (cannot be dispelled);\nImmediately removes the sleep effect on oneself upon sleeping.',
		zawakeEffectDesc_en = 'A single round is the full moon phase, improving oneself by #C0x5c9970#$(30+skillLevel*0.15-0.15)$%#C0x5B545B# dual defense (cannot be dispelled);\nA double round is the new moon phase, enhancing a person\'s #C0x5c9970#$(40+skillLevel*0.35-0.35)$%#C0x5B545B# recovery speed (cannot be dispelled);\nImmediately removes the sleep effect on oneself upon sleeping.',
		zawakeEffectDesc_th = 'รอบเดี่ยวคือช่วงพระจันทร์เต็มดวง ปรับปรุงตนเอง #C0x5c9970#$(30+skillLevel*0.15-0.15)$%#C0x5B545B# การป้องกันสองเท่า (ไม่สามารถลบล้างได้);\nรอบคู่คือช่วงพระจันทร์ใหม่ เพิ่มพูนความสามารถของบุคคล #C0x5c9970#$(40+skillLevel*0.35-0.35)$%#C0x5B545B# ความเร็วการฟื้นฟู (ไม่สามารถลบล้างได้);\nลบเอฟเฟกต์การนอนหลับของตนเองทันทีเมื่อหลับ',
		zawakeEffectDesc_in = 'Satu putaran adalah fase bulan purnama, meningkatkan diri sendiri #C0x5c9970#$(30+skillLevel*0.15-0.15)$%#C0x5B545B# pertahanan ganda (tidak dapat dihapus);\nPutaran ganda adalah fase bulan baru, meningkatkan kemampuan seseorang #C0x5c9970#$(40+skillLevel*0.35-0.35)$%#C0x5B545B# kecepatan pemulihan (tidak dapat dihapus);\nSegera menghapus efek tidur pada diri sendiri saat tertidur.',
		zawakeEffectDesc_ph = 'Isang isang pag-ikot ay ang yugto ng buong buwan, pinapabuti ang sarili ng #C0x5c9970#$(30+skillLevel*0.15-0.15)$%#C0x5B545B# dobleng depensa (hindi maaaring alisin);\nAng dobleng pag-ikot ay ang yugto ng bagong buwan, pinapalakas ang kakayahan ng isang tao ng #C0x5c9970#$(40+skillLevel*0.35-0.35)$%#C0x5B545B# bilis ng paggaling (hindi maaaring alisin);\nAgad na tinatanggal ang epekto ng pagtulog sa sarili kapag natutulog.',
		zawakeEffectDesc_ma = 'Satu pusingan adalah fasa bulan penuh, meningkatkan diri sendiri #C0x5c9970#$(30+skillLevel*0.15-0.15)$%#C0x5B545B# pertahanan berganda (tidak boleh dibuang);\nPusingan berganda adalah fasa bulan baru, meningkatkan keupayaan seseorang #C0x5c9970#$(40+skillLevel*0.35-0.35)$%#C0x5B545B# kelajuan pemulihan (tidak boleh dibuang);\nSegera menghapuskan kesan tidur pada diri sendiri apabila tidur.',
		zawakeEffectDesc_vn = 'Một vòng duy nhất là giai đoạn trăng tròn, cải thiện bản thân #C0x5c9970#$(30+skillLevel*0.15-0.15)$%#C0x5B545B# phòng thủ kép (không thể xua tan);\nVòng đôi là giai đoạn trăng mới, Cải thiện khả năng của một người #C0x5c9970#$(40+skillLevel*0.35-0.35)$%#C0x5B545B# tốc độ hồi phục (không thể xua tan);\nXóa bỏ hiệu ứng ngủ của chính mình ngay lập tức khi ngủ.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Double defense from Full Moon Phase increased by an additional 20%, and healing speed from Waxing Moon Phase increased by 10%',
		zawakeSimpleDesc_en = 'Double defense from Full Moon Phase increased by an additional 20%, and healing speed from Waxing Moon Phase increased by 10%',
		zawakeSimpleDesc_th = 'การป้องกันคู่จากช่วงพระจันทร์เต็มดวงเพิ่มขึ้นอีก 20% และความเร็วฟื้นฟูจากช่วงพระจันทร์ข้างขึ้นเพิ่มขึ้นอีก 10%',
		zawakeSimpleDesc_in = 'Pertahanan ganda dari Fase Bulan Purnama meningkat sebesar 20% dan kecepatan pemulihan dari Fase Bulan Sabit meningkat sebesar 10%',
		zawakeSimpleDesc_ph = 'Nadagdagan ng 20% ang double defense ng Full Moon Phase at ng 10% ang healing speed ng Waxing Moon Phase',
		zawakeSimpleDesc_ma = 'Pertahanan berganda dari Fasa Bulan Purnama meningkat sebanyak 20% dan kadar penyembuhan dari Fasa Bulan Sabit meningkat sebanyak 10%',
		zawakeSimpleDesc_vn = 'Khả năng phòng thủ kép của giai đoạn trăng tròn được tăng thêm 20% và tốc độ hồi phục của giai đoạn trăng non được tăng thêm 10%.',
