	[24311] = {
		id = 24311,
		skillName_vn = 'Móng Vuốt Ma Ảnh',
		skillName_en = 'Phantom Claws',
		skillName_th = 'กระบองเงาผี',
		skillName_in = 'Cakar Hantu',
		skillName_ph = 'Mga Kuko ng Multo',
		skillName_ma = 'Cakar Hantu',
		skillName = 'Phantom Claws',
		describe_vn = 'Hoàng hậu Boya Hancock lóe lên trước một mục tiêu kẻ địch và tấn công bằng móng vuốt ma, gây ra #C0x3D8A99#100% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#sát thương ma thuật#C0x5B545B#, đồng thời đánh cắp 15% đòn tấn công kép và 15% tốc độ của nó, kéo dài 2 hiệp.',
		describe_en = 'Empress Boya Hancock flashes before an enemy target and attacks with demonic claws, dealing #C0x3D8A99#100% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# magic damage#C0x5B545B#, while stealing 15% of the target\'s double attack and 15% of its speed, lasting 2 turns.',
		describe_th = 'จักรพรรดินีโบยา แฮนค็อก ปรากฏตัวต่อหน้าศัตรูเป้าหมายและโจมตีด้วยกรงเล็บปีศาจ สร้างความเสียหายเวทมนตร์ #C0x3D8A99#100%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# พร้อมกับขโมยการโจมตีคู่ 15% และความเร็ว 15% ของเป้าหมาย เป็นระยะเวลา 2 เทิร์น',
		describe_in = 'Ratu Boya Hancock muncul di depan target musuh dan menyerang dengan cakar iblis, memberikan #C0x3D8A99#100% Damage Magis#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# damage magis#C0x5B545B#, sekaligus mencuri 15% serangan ganda dan 15% kecepatan target, berlangsung selama 2 giliran.',
		describe_ph = 'Ang Reyna Boya Hancock ay biglang sumulpot sa harap ng isang target na kalaban at umatake gamit ang demonyong mga kuko, na nagdudulot ng #C0x3D8A99#100% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# pinsalang pang-magic#C0x5B545B#, kasabay ng pagnanakaw ng 15% ng doble atake at 15% ng bilis nito, na tumatagal ng 2 na turn.',
		describe_ma = 'Permaisuri Boya Hancock muncul di hadapan sasaran musuh dan menyerang dengan kuku iblis, menyebabkan #C0x3D8A99#100% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# kerosakan sihir#C0x5B545B#, sambil mencuri 15% serangan berganda dan 15% kelajuan sasaran, berlangsung selama 2 pusingan.',
		describe = 'Empress Boya Hancock flashes before an enemy target and attacks with demonic claws, dealing #C0x3D8A99#100% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# magic damage#C0x5B545B#, while stealing 15% of the target\'s double attack and 15% of its speed, lasting 2 turns.',
		simDesc_vn = 'Hoàng hậu Boya Hancock phóng tới trước một mục tiêu kẻ thù, tấn công bằng móng vuốt ma để gây sát thương phép, đồng thời cướp gấp đôi đòn tấn công và tốc độ của kẻ thù.',
		simDesc_en = 'Empress Boya Hancock lunges at an enemy target, attacking with spectral claws to deal magic damage, while simultaneously stealing double the enemy\'s attack and speed.',
		simDesc_th = 'จักรพรรดินีโบยา ฮันค็อก พุ่งเข้าใส่เป้าหมายศัตรูด้วยกรงเล็บผีโจมตีเพื่อสร้างความเสียหายเวทมนตร์ พร้อมทั้งขโมยพลังโจมตีและความเร็วของศัตรูเป็นสองเท่าในทันที',
		simDesc_in = 'Ratu Boya Hancock melesat ke depan ke target musuh, menyerang dengan cakar gaib untuk memberikan kerusakan sihir, sekaligus mencuri dua kali lipat serangan dan kecepatan musuh.',
		simDesc_ph = 'Sumugod si Empress Boya Hancock sa isang kalaban, umatake gamit ang mga espirituwal na kuko upang makagawa ng magic damage, kasabay ng pagnanakaw ng doble ng atake at bilis ng kalaban.',
		simDesc_ma = 'Permaisuri Boya Hancock meluru ke hadapan sasaran musuh, menyerang dengan kuku hantu untuk memberikan kerosakan sihir, sambil mencuri dua kali ganda serangan dan kelajuan musuh.',
		simDesc = 'Empress Boya Hancock lunges at an enemy target, attacking with spectral claws to deal magic damage, while simultaneously stealing double the enemy\'s attack and speed.',
		zawakeEffect = __data_t__zawakeEffect[24311],
		-- {79001}
		zawakeEffectDesc = 'Empress Boya Hancock lunges at an enemy target and uses her demonic claw attack to deal #C0x3D8A99#100% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#magic damage#C0x5B545B#, while stealing 20% dual attack and 20% speed from it, lasting 2 turns.',
		zawakeEffectDesc_en = 'Empress Boya Hancock lunges at an enemy target and uses her demonic claw attack to deal #C0x3D8A99#100% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#magic damage#C0x5B545B#, while stealing 20% dual attack and 20% speed from it, lasting 2 turns.',
		zawakeEffectDesc_th = 'จักรพรรดินีโบยาแฮนค็อกพุ่งไปยังเป้าหมายศัตรูและใช้ท่าปล้นด้วยกรงเล็บอสูรของเธอเพื่อสร้าง #C0x3D8A99#100% พลังเวทโจมตี#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# พร้อมทั้งขโมยการโจมตีคู่ 20% และความเร็ว 20% จากมัน เป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Ratu Boya Hancock menyerang target musuh dan menggunakan serangan cakarnya yang terdakwa untuk memberikan #C0x3D8A99#100% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#kerusakan sihir#C0x5B545B#, sekaligus mencuri 20% serangan ganda dan 20% kecepatan dari target tersebut, berlangsung selama 2 giliran.',
		zawakeEffectDesc_ph = 'Si Empress Boya Hancock ay bumagsak sa isang kaaway na target at ginamit ang kanyang demonic claw attack upang magdulot ng #C0x3D8A99#100% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#magic damage#C0x5B545B#, sabay na pumupulot ng 20% dual attack at 20% speed mula dito, tumatagal ng 2 turn.',
		zawakeEffectDesc_ma = 'Permaisuri Boya Hancock menyerang sasaran musuh dan menggunakan serangan cakarnya yang berdendam untuk memberikan #C0x3D8A99#100% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#kerosakan sihir#C0x5B545B#, sambil mencuri 20% serangan berganda dan 20% kelajuan daripadanya, berlangsung selama 2 pusingan.',
		zawakeEffectDesc_vn = 'Hoàng hậu Boya Hancock lao tới trước một mục tiêu kẻ thù và sử dụng đòn tấn công bằng móng vuốt ma của mình để gây ra #C0x3D8A99#100% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#sát thương ma thuật#C0x5B545B#, đồng thời cướp 20% đòn tấn công kép và 20% tốc độ của nó, kéo dài 2 hiệp.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'And steal 15% double attack and 15% speed from the target#F20# #F40##C0x5c9970#→And steal 20% double attack and 20% speed from the target',
		zawakeSimpleDesc_en = 'And steal 15% double attack and 15% speed from the target#F20# #F40##C0x5c9970#→And steal 20% double attack and 20% speed from the target',
		zawakeSimpleDesc_th = 'ขโมยพลังโจมตีคู่ 15% และความเร็ว 15% จากเป้าหมาย#F20# #F40##C0x5c9970#→ขโมยพลังโจมตีคู่ 20% และความเร็ว 20% จากเป้าหมาย',
		zawakeSimpleDesc_in = 'Mencuri 15% serangan ganda dan 15% kecepatan target#F20# #F40##C0x5c9970#→Mencuri 20% serangan ganda dan 20% kecepatan target',
		zawakeSimpleDesc_ph = 'Magnanakaw ng 15% double attack at 15% bilis mula sa target#F20# #F40##C0x5c9970#→Magnanakaw ng 20% double attack at 20% bilis mula sa target',
		zawakeSimpleDesc_ma = 'Mencuri 15% serangan berganda dan 15% kelajuan daripada sasaran#F20# #F40##C0x5c9970#→Mencuri 20% serangan berganda dan 20% kelajuan daripada sasaran',
		zawakeSimpleDesc_vn = 'Và cướp 15% công kép và 15% tốc độ của mục tiêu#F20# #F40##C0x5c9970#→Và cướp 20% công kép và 20% tốc độ của mục tiêu',
