		skillName_in = 'Tidur berjalan',
		skillName_ph = 'Sleepwalking',
		skillName_ma = 'Berjalan semula jadi',
		skillName = 'Sleepwalking',
		describe_vn = 'Hoàng hậu Boya Hancock đã ký khế ước với Thần chết để triệu hồi bàn tay ma tấn công mục tiêu kẻ thù, gây ra #C0x3D8A99#170% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Sát thương phép #C0x5B545B#, nuốt 50% sát thương do kỹ năng này gây ra và chuyển thành máu của chính mình, đồng thời có hiệu ứng 80% khả năng khiến mục tiêu tiến vào [Hóa đá tâm linh] trong 1 hiệp (Hóa đá tâm linh: hiệu ứng khống chế, không thể hành động, sẽ thức tỉnh sau khi bị tấn công bởi 2 kỹ năng chủ động)',
		describe_en = 'Queen Boya Hancock has signed a contract with the Grim Reaper to summon the phantom hand to strike enemy targets, dealing #C0x3D8A99#170% Magic Damage#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# magic damage #C0x5B545B#, consuming 50% of the damage caused by this skill and converting it to her own health, while also having an 80% chance to cause the target to enter [Spiritual Petrification] for 1 turn (Spiritual Petrification: a control effect, cannot act, will awaken after being hit by 2 active skills).',
		describe_th = 'ราชินีบอยา ฮันค็อก ได้เซ็นสัญญากับยมทูตเพื่อเรียกมือผีมารุกรานเป้าหมายศัตรู ก่อให้เกิด #C0x3D8A99#170% ความเสียหายเวทย์มนตร์#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# ความเสียหายเวทย์มนตร์ #C0x5B545B# กลืนกิน 50% ของความเสียหายที่สกิลนี้ก่อให้เกิดและเปลี่ยนเป็นพลังชีวิตของตัวเอง พร้อมทั้งมีโอกาส 80% ทำให้เป้าหมายเข้าสู่สถานะ [กลายเป็นหินทางจิตวิญญาณ] เป็นเวลา 1 เทิร์น (กลายเป็นหินทางจิตวิญญาณ: เอฟเฟกต์ควบคุม ไม่สามารถกระทำการได้ จะฟื้นตัวหลังถูกโจมตีด้วยทักษะแอคทีฟ 2 ครั้ง)',
		describe_in = 'Ratu Boya Hancock telah menandatangani kontrak dengan Malaikat Maut untuk memanggil tangan hantu menyerang target musuh, menyebabkan #C0x3D8A99#170% Damage Magic#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# damage magic #C0x5B545B#, menelan 50% dari damage yang dihasilkan skill ini dan mengubahnya menjadi darahnya sendiri, sekaligus memiliki efek 80% peluang membuat target masuk ke [Petrifikasi Spiritual] selama 1 giliran (Petrifikasi Spiritual: efek kontrol, tidak bisa bergerak, akan sadar kembali setelah diserang oleh 2 skill aktif).',
		describe_ph = 'Nilag ng Reyna Boya Hancock ay pumirma ng kontrata sa Kamatayan upang tawagin ang espiritung kamay na umatake sa mga kalaban na target, nagdudulot ng #C0x3D8A99#170% Magic Damage#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# magic damage #C0x5B545B#, nilulunok ang 50% ng damage na dulot ng skill na ito at ginagawang sariling dugo, kasabay ng 80% tsansa na mapasok ang target sa [Spiritual Petrification] sa loob ng 1 turn (Spiritual Petrification: isang control effect, hindi makakagalaw, gigising kapag naatake ng 2 active skills).',
		describe_ma = 'Ratu Boya Hancock telah menandatangani perjanjian dengan Malaikat Maut untuk memanggil tangan hantu menyerang sasaran musuh, menyebabkan #C0x3D8A99#170% Kerosakan Sihir#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# kerosakan sihir #C0x5B545B#, menyerap 50% daripada kerosakan yang disebabkan oleh kemahiran ini dan mengubahnya menjadi darahnya sendiri, serta mempunyai kesan 80% peluang untuk menyebabkan sasaran masuk ke [Petrifikasi Spiritual] selama 1 giliran (Petrifikasi Spiritual: kesan kawalan, tidak dapat bertindak, akan sedar semula selepas diserang oleh 2 kemahiran aktif).',
		describe = 'Queen Boya Hancock has signed a contract with the Grim Reaper to summon the phantom hand to strike enemy targets, dealing #C0x3D8A99#170% Magic Damage#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# magic damage #C0x5B545B#, consuming 50% of the damage caused by this skill and converting it to her own health, while also having an 80% chance to cause the target to enter [Spiritual Petrification] for 1 turn (Spiritual Petrification: a control effect, cannot act, will awaken after being hit by 2 active skills).',
		simDesc_vn = 'Hoàng hậu Boya Hancock đã ký khế ước với Thần Chết để triệu hồi bàn tay ma quái tấn công mục tiêu kẻ thù, nuốt kỹ năng này để gây sát thương, hồi phục bản thân và có cơ hội đưa chúng vào giấc ngủ.',
		simDesc_en = 'Empress Boya Hancock has signed a contract with the Grim Reaper to summon the phantom hand to attack enemy targets, absorbing this skill to deal damage, heal herself, and has a chance to put them to sleep.',
		simDesc_th = 'จักรพรรดินีโบยา แฮนค็อก ได้ลงนามในสัญญากับยมทูตเพื่อเรียกมือปีศาจโจมตีเป้าหมายศัตรู ใช้ทักษะนี้เพื่อสร้างความเสียหาย ฟื้นฟูตัวเอง และมีโอกาสทำให้พวกเขาหลับใหล',
		simDesc_in = 'Ratu Boya Hancock telah menandatangani kontrak dengan Malaikat Maut untuk memanggil tangan hantu menyerang target musuh, menyerap keterampilan ini untuk memberikan kerusakan, menyembuhkan dirinya sendiri, dan memiliki kesempatan untuk membuat mereka tertidur.',
		simDesc_ph = 'Nilagdaang si Empress Boya Hancock ng kontrata sa Grim Reaper para tawagin ang mahiwagang kamay na umatake sa mga kalaban, sisipsipin ang kakayahang ito para makapagdulot ng pinsala, makapagpagaling ng sarili, at may pagkakataong makapagpatulog sa kanila.',
		simDesc_ma = 'Permaisuri Boya Hancock telah menandatangani kontrak dengan Malaikat Maut untuk memanggil tangan hantu menyerang sasaran musuh, menyerap kemahiran ini untuk menyebabkan kerosakan, memulihkan dirinya sendiri, dan berpeluang untuk memaklumkan mereka tidur.',
		simDesc = 'Empress Boya Hancock has signed a contract with the Grim Reaper to summon the phantom hand to attack enemy targets, absorbing this skill to deal damage, heal herself, and has a chance to put them to sleep.',
		zawakeEffect = __data_t__zawakeEffect[24312],
		-- {79002}
		zawakeEffectDesc = 'Empress Boya Hancock has signed a contract with the Grim Reaper to summon a demonic hand to attack enemy targets, causing #C0x3D8A99#170% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magical damage#C0x5B545B# , consuming 50% of the damage dealt by this skill and immediately converting it into its own health. The remaining 50% will convert into its own health before the next action round begins, with an 80% chance to inflict <Spiritual Petrification> on the target for 1 turn (Spiritual Petrification: a control effect, unable to act, will awaken after being attacked by 2 active skills).',
		zawakeEffectDesc_en = 'Empress Boya Hancock has signed a contract with the Grim Reaper to summon a demonic hand to attack enemy targets, causing #C0x3D8A99#170% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magical damage#C0x5B545B# , consuming 50% of the damage dealt by this skill and immediately converting it into its own health. The remaining 50% will convert into its own health before the next action round begins, with an 80% chance to inflict <Spiritual Petrification> on the target for 1 turn (Spiritual Petrification: a control effect, unable to act, will awaken after being attacked by 2 active skills).',
		zawakeEffectDesc_th = 'พระราชินีบอย่า ฮันค็อก ได้ลงนามในสัญญากับยมฑูตเพื่อเรียกมือปีศาจโจมตีเป้าหมายศัตรู สร้าง #C0x3D8A99#170% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# กลืนกิน 50% ของความเสียหายที่ทักษะนี้สร้างขึ้นและเปลี่ยนเป็นเลือดของตัวเองทันที ส่วนที่เหลือ 50% จะเปลี่ยนเป็นเลือดของตัวเองก่อนเริ่มรอบการกระทำถัดไปและมีโอกาส 80% ที่จะทำให้เป้าหมายตกอยู่ใน <Hóa đá tâm linh> เป็นเวลา 1 รอบ (Hóa đá tâm linh: เอฟเฟกต์ควบคุม ไม่สามารถกระทำการใดๆ ได้ จะตื่นขึ้นหลังจากถูกโจมตีด้วยทักษะใช้งาน 2 ครั้ง)',
		zawakeEffectDesc_in = 'Permaisuri Boya Hancock telah menandatangani kontrak dengan Malaikat Maut untuk memanggil tangan iblis menyerang target musuh, menyebabkan #C0x3D8A99#170% Damage Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# damage sihir#C0x5B545B# , menelan 50% dari damage yang diberikan oleh skill ini dan segera mengubahnya menjadi darahnya sendiri. Sisa 50% akan diubah menjadi darahnya sebelum putaran aksi berikutnya dimulai dan memiliki peluang 80% untuk membuat target jatuh ke dalam <Hóa đá tâm linh> selama 1 putaran (Hóa đá tâm linh: efek kontrol, tidak bisa bertindak, akan bangun setelah diserang oleh 2 skill aktif).',
		zawakeEffectDesc_ph = 'Nilagdaang Boya Hancock ay pumirma ng kontrata sa kamatayan upang tawagin ang demonic hand para atakihin ang mga kaaway, na nagdudulot ng #C0x3D8A99#170% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# nakakapinsalang magic#C0x5B545B# , nilamon ang 50% ng pinsalang dulot ng skill na ito at agad itong ginawang sariling dugo. Ang natitirang 50% ay gagawing dugo bago magsimula ang susunod na round ng aksyon at may 80% tsansa na mapasailalim ang target sa <Hóa đá tâm linh> ng 1 round (Hóa đá tâm linh: isang kontrol na effect, hindi makakilos, gagising kapag tinamaan ng 2 active skills).',
		zawakeEffectDesc_ma = 'Permaisuri Boya Hancock telah menandatangani kontrak dengan Malaikat Maut untuk memanggil tangan syaitan menyerang sasaran musuh, menyebabkan #C0x3D8A99#170% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# kerosakan sihir#C0x5B545B# , menelan 50% daripada kerosakan yang disebabkan oleh kemahiran ini dan segera menukarnya menjadi darahnya sendiri. Baki 50% akan ditukar menjadi darahnya sebelum pusingan tindakan seterusnya bermula dan mempunyai kebarangkalian 80% untuk menyebabkan sasaran jatuh ke dalam <Hóa đá tâm linh> selama 1 pusingan (Hóa đá tâm linh: kesan kawalan, tidak boleh bertindak, akan bangun selepas diserang oleh 2 kemahiran aktif).',
		zawakeEffectDesc_vn = 'Hoàng hậu Boya Hancock đã ký khế ước với Thần chết để triệu hồi bàn tay ma tấn công mục tiêu kẻ thù, gây ra #C0x3D8A99#170% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#sát thương ma thuật#C0x5B545B# , nuốt chửng 50% sát thương do kỹ năng này gây ra và ngay lập tức chuyển hóa thành máu của chính nó, phần còn lại 50% sẽ chuyển hóa thành máu của chính nó trước khi bắt đầu vòng hành động tiếp theo và có 80% khả năng khiến mục tiêu rơi vào <Hóa đá tâm linh> trong 1 vòng (Hóa đá tâm linh: hiệu ứng khống chế, không thể hành động, sẽ thức tỉnh sau khi bị tấn công bởi 2 kỹ năng chủ động)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Devour 50% of the remaining damage from this skill and convert it into own HP before the next action turn',
		zawakeSimpleDesc_en = '#C0x5c9970#Devour 50% of the remaining damage from this skill and convert it into own HP before the next action turn',
		zawakeSimpleDesc_th = '#C0x5c9970#กลืนกิน 50% ความเสียหายที่เหลือจากสกิลนี้และเปลี่ยนเป็นพลังชีวิตของตนก่อนรอบการกระทำถัดไป',
		zawakeSimpleDesc_in = '#C0x5c9970#Menelan 50% sisa damage dari skill ini dan mengubahnya menjadi HP sendiri sebelum giliran aksi berikutnya',
		zawakeSimpleDesc_ph = '#C0x5c9970#Lulunukin ang 50% ng natitirang damage mula sa kasanayang ito at gagawing sariling HP bago magsimula ang susunod na turn',
		zawakeSimpleDesc_ma = '#C0x5c9970#Telan 50% kerosakan yang tinggal dari kemahiran ini dan tukarkan kepada HP sendiri sebelum giliran tindakan seterusnya',
		zawakeSimpleDesc_vn = '#C0x5c9970#Nuốt chửng 50% sát thương còn lại của kỹ năng lần này sẽ chuyển hóa thành sinh lực của bản thân trước khi bắt đầu lượt hành động tiếp theo',
