	[24313] = {
		id = 24313,
		skillName_vn = 'Cơn ác mộng ập đến',
		skillName_en = 'The nightmare strikes',
		skillName_th = 'ฝันร้ายโจมตี',
		skillName_in = 'Mimpi buruk menyerang',
		skillName_ph = 'Umabot ang bangungot',
		skillName_ma = 'Mimpi ngeri menyerang',
		skillName = 'The nightmare strikes',
		describe_vn = 'Hoàng hậu Boya Hancock thức dậy từ màn đêm, nhấn chìm mọi thứ xung quanh vào cơn ác mộng, sau đó triệu hồi hàng ngàn bàn tay ma tấn công tất cả mục tiêu của kẻ thù, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, có 40% xác suất lọt vào [Cơn ác mộng hóa đá] trong 1 hiệp (Cơn ác mộng hóa đá: hiệu ứng khống chế, không thể di chuyển, không thể xua tan, sẽ thức tỉnh sau khi bị tấn công bởi 2 kỹ năng chủ động), kẻ địch sau khi Cơn ác mộng hóa đá thức dậy sẽ rơi vào trạng thái yếu trong 1 hiệp (giảm 20% phòng thủ kép và 20% tấn công kép)',
		describe_en = 'Empress Boya Hancock awakens from the night, plunging everything around into a nightmare, then summons thousands of ghostly hands to attack all enemy targets, dealing #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 40% chance to inflict [Petrifying Nightmare] for 1 turn (Petrifying Nightmare: a control effect, unable to move or dispel, will awaken after being hit by 2 active skills). Enemies who awaken from Petrifying Nightmare will enter a weakened state for 1 turn (reducing dual defense and dual attack by 20%).',
		describe_th = 'จักรพรรดินีโบยา Hancock ตื่นขึ้นจากความมืด มอบฝันร้ายให้ทุกสิ่งรอบข้าง จากนั้นเรียกมือผีหลายพันมือโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวทมนตร์ #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# พร้อมโอกาส 40% ที่จะติด [ฝันร้ายทำให้กลายเป็นหิน] เป็นเวลา 1 เทิร์น (ฝันร้ายทำให้กลายเป็นหิน: เอฟเฟกต์ควบคุม ไม่สามารถเคลื่อนที่หรือขจัดออก จะฟื้นคืนหลังถูกโจมตีด้วยสกิลใช้งาน 2 ครั้ง) ศัตรูที่ฟื้นคืนจากฝันร้ายจะตกอยู่ในสถานะอ่อนแอเป็นเวลา 1 เทิร์น (ลดการป้องกันคูณและการโจมตีคูณลง 20%)',
		describe_in = 'Ratu Boya Hancock bangkit dari kegelapan malam, menenggelamkan segala sesuatu di sekitarnya ke dalam mimpi buruk, kemudian memanggil ribuan tangan hantu untuk menyerang semua target musuh, menyebabkan #C0x3D8A99#180% Kerusakan Magic#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerusakan Magic #C0x5B545B#, dengan peluang 40% terkena [Mimpi Buruk Membatu] selama 1 giliran (Mimpi Buruk Membatu: efek kontrol, tidak bisa bergerak, tidak bisa hilang, akan sadar setelah terkena 2 skill aktif). Musuh yang sadar dari Mimpi Buruk Membatu akan mengalami kondisi lemah selama 1 giliran (mengurangi pertahanan ganda dan serangan ganda sebesar 20%).',
		describe_ph = 'Ang Reyna Boya Hancock ay nagising mula sa kadiliman, inilubog ang lahat sa paligid sa isang bangungot, pagkatapos ay tinawag ang libu-libong mga kamay ng multo upang atakihin ang lahat ng mga target ng kaaway, nagdudulot ng #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Magic Damage #C0x5B545B#, na may 40% na tsansa na mapasailalim sa [Petrifying Nightmare] sa loob ng 1 turn (Petrifying Nightmare: isang kontrol na epekto, hindi makagalaw, hindi maalis, gigising matapos tamaan ng 2 aktibong kasanayan). Ang mga kaaway na gigising mula sa Petrifying Nightmare ay magiging mahina sa loob ng 1 turn (binabawasan ang dobleng depensa at dobleng atake ng 20%).',
		describe_ma = 'Permaisuri Boya Hancock terjaga dari kegelapan malam, menenggelamkan segala-galanya di sekelilingnya ke dalam mimpi ngeri, kemudian memanggil ribuan tangan hantu untuk menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#180% Kerosakan Magic#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerosakan Magic #C0x5B545B#, dengan peluang 40% untuk terkena [Mimpi Ngeri Membatu] selama 1 pusingan (Mimpi Ngeri Membatu: kesan kawalan, tidak boleh bergerak, tidak boleh ditanggalkan, akan bangun selepas diserang oleh 2 kemahiran aktif). Musuh yang bangun dari Mimpi Ngeri Membatu akan berada dalam keadaan lemah selama 1 pusingan (mengurangkan pertahanan berganda dan serangan berganda sebanyak 20%).',
		describe = 'Empress Boya Hancock awakens from the night, plunging everything around into a nightmare, then summons thousands of ghostly hands to attack all enemy targets, dealing #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 40% chance to inflict [Petrifying Nightmare] for 1 turn (Petrifying Nightmare: a control effect, unable to move or dispel, will awaken after being hit by 2 active skills). Enemies who awaken from Petrifying Nightmare will enter a weakened state for 1 turn (reducing dual defense and dual attack by 20%).',
		simDesc_vn = 'Hoàng hậu Boya Hancock thức dậy từ màn đêm, nhấn chìm mọi thứ xung quanh vào cơn ác mộng, sau đó triệu hồi hàng nghìn bàn tay ma tấn công tất cả mục tiêu của kẻ thù, có khả năng khiến chúng rơi vào cơn ác mộng hóa đá. Sau khi cơn ác mộng hóa đá thức dậy, nó sẽ yếu đi.',
		simDesc_en = 'Empress Boya Hancock awakens from the darkness, drowning everything around into a nightmare, then summons thousands of ghostly hands to attack all enemy targets, with the ability to trap them in a petrifying nightmare. Once the petrifying nightmare fades, its power weakens.',
		simDesc_th = 'จักรพรรดินีโบยา ฮันค็อกตื่นขึ้นจากความมืด ดับทุกสิ่งรอบตัวให้กลายเป็นฝันร้าย จากนั้นเรียกมือผีนับพันโจมตียังเป้าหมายศัตรูทั้งหมด มีความสามารถทำให้พวกมันตกอยู่ในฝันร้ายหิน เมื่อฝันร้ายหินหมดความแรง พลังจะอ่อนลง',
		simDesc_in = 'Ratu Boya Hancock bangun dari kegelapan, menenggelamkan segala sesuatu di sekitarnya ke dalam mimpi buruk, lalu memanggil ribuan tangan hantu untuk menyerang semua target musuh, dengan kemampuan membuat mereka terjebak dalam mimpi buruk membatu. Setelah mimpi buruk membatu itu menghilang, kekuatannya melemah.',
		simDesc_ph = 'Nagising si Empress Boya Hancock mula sa dilim, nilubog ang lahat sa paligid sa isang bangungot, pagkatapos ay tinawag ang libu-libong mga espiritung kamay upang atakihin ang lahat ng mga target ng kaaway, na may kakayahang gawing isang bangungot ng pagkatigang. Kapag nawala na ang bangungot ng pagkatigang, humina ang lakas nito.',
		simDesc_ma = 'Permaisuri Boya Hancock bangun dari kegelapan, menenggelamkan segala-galanya di sekelilingnya ke dalam mimpi ngeri, kemudian memanggil ribuan tangan hantu untuk menyerang semua sasaran musuh, dengan kemampuan menyebabkan mereka terperangkap dalam mimpi ngeri batu. Setelah mimpi ngeri batu itu pudar, kuasanya akan berkurang.',
		simDesc = 'Empress Boya Hancock awakens from the darkness, drowning everything around into a nightmare, then summons thousands of ghostly hands to attack all enemy targets, with the ability to trap them in a petrifying nightmare. Once the petrifying nightmare fades, its power weakens.',
		starEffect = __data_t__starEffect[24313],
		-- {11}
		starEffectDesc_vn = 'Sau khi thi triển tất sát kỹ, toàn bộ cảnh sẽ chuyển hóa thành Mộng Cảnh Ác Mộng, kéo dài 1 hiệp; trong Mộng Cảnh Ác Mộng, Nữ Đế Boa Hancock sẽ đánh cắp khả năng giảm sát thương của phe địch (tổng cộng 60%, chia đều cho mỗi mục tiêu địch); trong Mộng Cảnh Ác Mộng, các tướng bị Ngủ hoặc Hóa Đá Ác Mộng sẽ không bị đánh thức khi bị tấn công.',
		starEffectDesc = 'After performing Total Kill Technique, the entire battlefield transforms into Nightmare Dreamscape, lasting for 1 round; in Nightmare Dreamscape, Empress Boa Hancock will steal the enemy\'s damage reduction ability (a total of 60%, divided evenly among each enemy target); in Nightmare Dreamscape, generals who are Asleep or Petrified by Nightmare will not be awakened upon being attacked.',
		starEffectDesc_en = 'After performing Total Kill Technique, the entire battlefield transforms into Nightmare Dreamscape, lasting for 1 round; in Nightmare Dreamscape, Empress Boa Hancock will steal the enemy\'s damage reduction ability (a total of 60%, divided evenly among each enemy target); in Nightmare Dreamscape, generals who are Asleep or Petrified by Nightmare will not be awakened upon being attacked.',
		starEffectDesc_th = 'หลังจากใช้เทคนิครวดฆ่าทั้งหมด สนามรบทั้งหมดจะเปลี่ยนเป็นฝันร้ายแห่งฝันประหลาด คงอยู่เป็นเวลา 1 เทิร์น; ในฝันร้ายแห่งฝันประหลาด จักรพรรดินีโบอาฮันค็อกจะขโมยความสามารถลดความเสียหายของฝ่ายศัตรู (รวมทั้งหมด 60% แบ่งเท่าๆ กันไปยังเป้าหมายศัตรูแต่ละตัว); ในฝันร้ายแห่งฝันประหลาด นายพลที่ถูกหลับหรือถูกกลายเป็นหินโดยฝันร้ายจะไม่ตื่นขึ้นเมื่อถูกโจมตี',
		starEffectDesc_in = 'Setelah menggunakan Teknik Pembunuhan Total, seluruh medan pertempuran berubah menjadi Mimpi Buruk Mimpi, berlangsung selama 1 giliran; dalam Mimpi Buruk Mimpi, Ratu Boa Hancock akan mencuri kemampuan pengurangan kerusakan musuh (total 60%, dibagi rata untuk setiap target musuh); dalam Mimpi Buruk Mimpi, jenderal yang tertidur atau membatu akibat Mimpi Buruk tidak akan terbangun saat diserang.',
		starEffectDesc_ph = 'Pagkatapos gamitin ang Total Kill Technique, ang buong larangan ay magbabago sa Nightmare Dreamscape, tatagal ng 1 round; sa Nightmare Dreamscape, iistolin ni Empress Boa Hancock ang kakayahan ng kalaban na magbawas ng pinsala (kabuuang 60%, pantay-pantay na hinati sa bawat kalabang target); sa Nightmare Dreamscape, ang mga heneral na Natutulog o Naging Bato dahil sa Bangungot ay hindi gigising kapag inatake.',
		starEffectDesc_ma = 'Selepas menggunakan Teknik Pembunuhan Total, seluruh arena akan berubah menjadi Mimpi Ngeri Mimpi, berlangsung selama 1 pusingan; dalam Mimpi Ngeri Mimpi, Maharani Boa Hancock akan mencuri keupayaan pengurangan kerosakan pihak musuh (jumlah keseluruhan 60%, dibahagikan sama rata kepada setiap sasaran musuh); dalam Mimpi Ngeri Mimpi, panglima yang tertidur atau telah menjadi batu akibat Mimpi Ngeri tidak akan terjaga apabila diserang.',
		zawakeEffect = __data_t__zawakeEffect[24313],
		-- {79003}
		zawakeEffectDesc = 'Empress Boya Hancock awakens from the night, plunging everything around into a nightmare, then summons thousands of ghost hands to attack all enemy targets, dealing #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54 #Spell Damage#C0x5B545B#, with a 50% chance to inflict <Petrifying Nightmare> for 1 turn (Petrifying Nightmare: control effect, unable to move, cannot be dispelled, will awaken after being attacked by 2 active skills). Enemies will fall into a weakened state for 2 turns after awakening from Petrifying Nightmare (reducing both defense and attack by 20%).',
		zawakeEffectDesc_en = 'Empress Boya Hancock awakens from the night, plunging everything around into a nightmare, then summons thousands of ghost hands to attack all enemy targets, dealing #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54 #Spell Damage#C0x5B545B#, with a 50% chance to inflict <Petrifying Nightmare> for 1 turn (Petrifying Nightmare: control effect, unable to move, cannot be dispelled, will awaken after being attacked by 2 active skills). Enemies will fall into a weakened state for 2 turns after awakening from Petrifying Nightmare (reducing both defense and attack by 20%).',
		zawakeEffectDesc_th = 'จักรพรรดินีโบยา ฮันค็อกตื่นขึ้นจากค่ำคืน ดับทุกสิ่งรอบตัวด้วยฝันร้าย จากนั้นเรียกมือผีเป็นพันมือโจมตีเป้าหมายศัตรูทั้งหมด สร้าง #C0x3D8A99#180% พลังเวทย์#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54 #ความเสียหายเวทมนตร์#C0x5B545B# มีโอกาส 50% ที่จะเข้าสู่ <ฝันร้ายกลายเป็นหิน> เป็นเวลา 1 เทิร์น (ฝันร้ายกลายเป็นหิน: สถานะควบคุม ไม่สามารถเคลื่อนที่ ไม่สามารถขจัด จะตื่นหลังถูกโจมตีโดยสกิลแอคทีฟ 2 ครั้ง) ศัตรูจะเข้าสู่สถานะอ่อนแอ 2 เทิร์น หลังตื่นจากฝันร้ายกลายเป็นหิน (ลดพลังป้องกันและพลังโจมตีคู่ลง 20%)',
		zawakeEffectDesc_in = 'Permaisuri Boya Hancock bangun dari kegelapan, menenggelamkan segala sesuatu di sekitarnya ke dalam mimpi buruk, lalu memanggil ribuan tangan hantu untuk menyerang semua target musuh, menyebabkan #C0x3D8A99#180% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54 #Damage Sihir#C0x5B545B#, dengan peluang 50% masuk ke dalam <Mimpi Buruk Endapan Batu> selama 1 giliran (Mimpi Buruk Endapan Batu: efek kontrol, tidak bisa bergerak, tidak bisa dihilangkan, akan terbangun setelah diserang oleh 2 skill aktif), musuh akan berada dalam kondisi lemah selama 2 giliran setelah terbangun dari Mimpi Buruk Endapan Batu (mengurangi 20% pertahanan ganda dan 20% serangan ganda).',
		zawakeEffectDesc_ph = 'Ginigang Boya Hancock ay magising mula sa gabi, lulubog ang lahat ng paligid sa isang bangungot, pagkatapos ay magpapatawag ng libu-libong kamay ng multo upang atakihin ang lahat ng target ng kalaban, na nagdudulot ng #C0x3D8A99#180% Spell Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54 #Spell Damage#C0x5B545B#, may 50% tsansang mapasailalim sa <Petrifying Nightmare> sa loob ng 1 turn (Petrifying Nightmare: control effect, hindi makakagalaw, hindi maaaring mapawi, gigising matapos atakihin ng 2 aktibong kasanayan), ang mga kalaban pagkatapos gumising mula sa Petrifying Nightmare ay mapapasailalim sa isang mahinaang estado sa loob ng 2 turn (bawas ng 20% dobleng depensa at 20% dobleng atake).',
		zawakeEffectDesc_ma = 'Permaisuri Boya Hancock bangun dari kegelapan malam, menenggelamkan segala sesuatu di sekeliling ke dalam mimpi ngeri, kemudian memanggil ribuan tangan hantu untuk menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#180% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54 #Kerosakan Sihir#C0x5B545B#, dengan 50% peluang untuk terkena <Mimpi Ngeri Bertukar Batu> selama 1 pusingan (Mimpi Ngeri Bertukar Batu: efek kawalan, tidak boleh bergerak, tidak boleh dibersihkan, akan bangun selepas diserang oleh 2 kemahiran aktif), musuh selepas bangun dari Mimpi Ngeri Bertukar Batu akan jatuh ke dalam keadaan lemah selama 2 pusingan (mengurangkan 20% pertahanan berganda dan 20% serangan berganda).',
		zawakeEffectDesc_vn = 'Hoàng hậu Boya Hancock thức dậy từ màn đêm, nhấn chìm mọi thứ xung quanh vào cơn ác mộng, sau đó triệu hồi hàng ngàn bàn tay ma tấn công tất cả mục tiêu của kẻ thù, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54 #Spell Damage#C0x5B545B#, có 50% xác suất lọt vào <Cơn ác mộng hóa đá> trong 1 hiệp (Cơn ác mộng hóa đá: hiệu ứng khống chế, không thể di chuyển, không thể xua tan, sẽ thức tỉnh sau khi bị tấn công bởi 2 kỹ năng chủ động), kẻ địch sau khi Cơn ác mộng hóa đá thức dậy sẽ rơi vào trạng thái yếu trong 2 lượt (giảm 20% phòng thủ kép và 20% tấn công kép)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Has a 40% chance to inflict <Petrifying Nightmare> for 1 round\nEnemies awakened from the Petrifying Nightmare will fall into a weakened state for 1 round\n#F20# \n#F40##C0x5c9970#→Has a 50% chance to inflict <Petrifying Nightmare> for 1 round\nEnemies awakened from the Petrifying Nightmare will fall into a weakened state for 2 rounds',
		zawakeSimpleDesc_en = 'Has a 40% chance to inflict <Petrifying Nightmare> for 1 round\nEnemies awakened from the Petrifying Nightmare will fall into a weakened state for 1 round\n#F20# \n#F40##C0x5c9970#→Has a 50% chance to inflict <Petrifying Nightmare> for 1 round\nEnemies awakened from the Petrifying Nightmare will fall into a weakened state for 2 rounds',
		zawakeSimpleDesc_th = 'มีโอกาส 40% ทำให้ศัตรูติดสถานะ <ฝันร้ายกลายเป็นหิน> 1 เทิร์น\nศัตรูที่ตื่นจากฝันร้ายกลายเป็นหินจะเข้าสู่สถานะอ่อนแอเป็นเวลา 1 เทิร์น\n#F20# \n#F40##C0x5c9970#→มีโอกาส 50% ทำให้ศัตรูติดสถานะ <ฝันร้ายกลายเป็นหิน> 1 เทิร์น\nศัตรูที่ตื่นจากฝันร้ายกลายเป็นหินจะเข้าสู่สถานะอ่อนแอเป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Memiliki 40% peluang menyebabkan <Mimpi Buruk Membatu> selama 1 ronde\nMusuh yang terbangun dari Mimpi Buruk Membatu akan mengalami status lemah selama 1 ronde\n#F20# \n#F40##C0x5c9970#→Memiliki 50% peluang menyebabkan <Mimpi Buruk Membatu> selama 1 ronde\nMusuh yang terbangun dari Mimpi Buruk Membatu akan mengalami status lemah selama 2 ronde',
		zawakeSimpleDesc_ph = 'May 40% chance na magdulot ng <Bato’t Bangungot> sa loob ng 1 turn\nKalaban na nagising mula sa Bato’t Bangungot ay babagsak sa kahinaan sa loob ng 1 turn\n#F20# \n#F40##C0x5c9970#→May 50% chance na magdulot ng <Bato’t Bangungot> sa loob ng 1 turn\nKalaban na nagising mula sa Bato’t Bangungot ay babagsak sa kahinaan sa loob ng 2 turn',
		zawakeSimpleDesc_ma = 'Mempunyai 40% peluang menyebabkan <Mimpi Ngeri Membatu> selama 1 pusingan\nMusuh yang sedar dari Mimpi Ngeri Membatu akan berada dalam keadaan lemah selama 1 pusingan\n#F20# \n#F40##C0x5c9970#→Mempunyai 50% peluang menyebabkan <Mimpi Ngeri Membatu> selama 1 pusingan\nMusuh yang sedar dari Mimpi Ngeri Membatu akan berada dalam keadaan lemah selama 2 pusingan',
		zawakeSimpleDesc_vn = 'Có 40% khả năng khiến nó rơi vào <Cơn ác mộng hóa đá> trong 1 hiệp\nKẻ địch sau khi thức tỉnh từ Ác mộng hóa đá sẽ rơi vào trạng thái suy yếu trong 1 hiệp\n#F20# \n#F40##C0x5c9970#→Có 50% xác suất khiến nó rơi vào <Cơn ác mộng hóa đá> trong 1 hiệp\nKẻ địch sau khi thức tỉnh từ Cơn ác mộng hóa đá sẽ rơi vào trạng thái suy yếu trong 2 vòng',
