	[24316] = {
		id = 24316,
		skillName_vn = 'Entering Dream',
		skillName_en = 'Entering Dream',
		skillName_th = 'เข้าสู่ความฝัน',
		skillName_in = 'Memasuki Mimpi',
		skillName_ph = 'Pumasok sa Panaginip',
		skillName_ma = 'Memasuki Mimpi',
		skillName = 'Entering Dream',
		describe_vn = 'Kỹ năng hào quang: Khi anh hùng bóng tối của bạn sử dụng các đòn tấn công cơ bản để tấn công mục tiêu, anh ta sẽ đánh cắp vĩnh viễn đòn tấn công kép cơ bản của mục tiêu #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (trở lại sau khi chết);\n Trước khi Hoàng hậu Boya Hancock hành động, có 50% xác suất một anh hùng ngẫu nhiên sẽ vào [Hóa đá tâm linh] trong 1 hiệp (không thể di chuyển, có thể bị xua tan và sẽ thức tỉnh sau khi nhận 2 đòn tấn công kỹ năng);\nHoàng hậu Boya Hancock tấn công một anh hùng đang ngủ hoặc trạng thái ác mộng hóa đá và sẽ không đánh thức anh ta.',
		describe_en = 'Aura Skill: When your Dark Hero uses basic attacks to hit a target, he will permanently steal the target\'s basic double attack at #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (restored after death);\n Before Queen Boya Hancock acts, there is a 50% chance that a random hero will enter [Spiritual Petrification] for 1 turn (unable to move, can be dispelled, and will awaken after receiving 2 skill attacks);\n Queen Boya Hancock attacks a hero who is sleeping or in nightmare petrification state and will not awaken him.',
		describe_th = 'ทักษะออร่า: เมื่อฮีโร่แห่งความมืดของคุณใช้การโจมตีพื้นฐานเพื่อโจมตีเป้าหมาย เขาจะขโมยท่าต่อยคู่พื้นฐานของเป้าหมายอย่างถาวรที่ #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (จะกลับมาเมื่อฟื้นหลังตาย);\n ก่อนที่ราชินีบอยา แฮนค็อกจะทำการกระทำ จะมีโอกาส 50% ที่ฮีโร่แบบสุ่มจะเข้าสู่ [สภาวะหินจิตวิญญาณ] เป็นเวลา 1 เทิร์น (ไม่สามารถเคลื่อนที่ได้ สามารถถูกลบสถานะ และจะฟื้นหลังรับการโจมตีทักษะ 2 ครั้ง);\n ราชินีบอยา แฮนค็อกจะโจมตีฮีโร่ที่กำลังหลับหรือติดสภาวะฝันร้ายหินและจะไม่ปลุกเขา',
		describe_in = 'Skill Aura: Ketika Pahlawan Kegelapan Anda menggunakan serangan dasar untuk menyerang target, dia akan mencuri secara permanen serangan ganda dasar target sebesar #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (kembali setelah mati);\n Sebelum Ratu Boya Hancock bertindak, ada kemungkinan 50% bahwa pahlawan acak akan memasuki [Petrifikasi Spiritual] selama 1 giliran (tidak dapat bergerak, dapat disingkirkan, dan akan terbangun setelah menerima 2 serangan keterampilan);\n Ratu Boya Hancock menyerang pahlawan yang sedang tidur atau dalam keadaan mimpi buruk petrifikasi dan tidak akan membangunkannya.',
		describe_ph = 'Aura Skill: Kapag ginamit ng iyong Dark Hero ang mga basic attacks upang atakihin ang target, permanente niyang mananakaw ang basic double attack ng target ng #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (ibabalik pagkatapos mamatay);\n Bago kumilos si Queen Boya Hancock, may 50% na tsansa na ang isang random na bayani ay papasok sa [Spiritual Petrification] sa loob ng 1 round (hindi makakagalaw, maaaring ma-dispel at magigising matapos makatanggap ng 2 skill attacks);\n Inaatake ni Queen Boya Hancock ang bayani na natutulog o nasa estado ng nightmare petrification at hindi niya siya gigisingin.',
		describe_ma = 'Kemahiran Aura: Apabila Wira Gelap anda menggunakan serangan asas untuk menyerang sasaran, dia akan mencuri secara kekal serangan berganda asas sasaran sebanyak #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (berbalik semula selepas mati);\n Sebelum Ratu Boya Hancock bertindak, terdapat 50% peluang wira rawak akan memasuki [Petrifikasi Roh] selama 1 giliran (tidak boleh bergerak, boleh disingkirkan dan akan tersedar selepas menerima 2 serangan kemahiran);\n Ratu Boya Hancock menyerang wira yang sedang tidur atau dalam keadaan mimpi ngeri petrifikasi dan tidak akan membangunkannya.',
		describe = 'Aura Skill: When your Dark Hero uses basic attacks to hit a target, he will permanently steal the target\'s basic double attack at #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (restored after death);\n Before Queen Boya Hancock acts, there is a 50% chance that a random hero will enter [Spiritual Petrification] for 1 turn (unable to move, can be dispelled, and will awaken after receiving 2 skill attacks);\n Queen Boya Hancock attacks a hero who is sleeping or in nightmare petrification state and will not awaken him.',
		starEffect = __data_t__starEffect[24316],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Nữ Đế Boa Hancock miễn nhiễm trạng thái ngủ và hóa đá ác mộng, khi tấn công tướng đang trong trạng thái ngủ hoặc hóa đá ác mộng, sẽ đánh cắp một hiệu ứng tăng cường của mục tiêu.',
		starEffectDesc = 'Additional Effect: Empress Boa Hancock is immune to sleep and petrification nightmare states. When attacking a general who is in a sleep or petrification nightmare state, she will steal one buff effect from the target.',
		starEffectDesc_en = 'Additional Effect: Empress Boa Hancock is immune to sleep and petrification nightmare states. When attacking a general who is in a sleep or petrification nightmare state, she will steal one buff effect from the target.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: จักรพรรดินีโบอา แฮนค็อก ป้องกันสถานะหลับและฝันร้ายกลายเป็นหิน เมื่อโจมตีแม่ทัพที่อยู่ในสถานะหลับหรือฝันร้ายกลายเป็นหิน จะขโมยเอฟเฟกต์เสริมหนึ่งอย่างจากเป้าหมาย',
		starEffectDesc_in = 'Efek Tambahan: Ratu Boa Hancock kebal terhadap status tidur dan mimpi buruk yang berubah menjadi batu. Saat menyerang jenderal yang sedang dalam status tidur atau mimpi buruk yang berubah menjadi batu, dia akan mencuri satu efek peningkatan dari target.',
		starEffectDesc_ph = 'Karagdagang Epekto: Si Empress Boa Hancock ay immune sa estado ng pagtulog at nightmare petrification. Kapag inaatake ang heneral na nasa estado ng pagtulog o nightmare petrification, magnanakaw siya ng isang buff effect mula sa target.',
		starEffectDesc_ma = 'Kesan Tambahan: Maharani Boa Hancock kebal terhadap keadaan tidur dan mimpi ngeri bertukar menjadi batu. Apabila menyerang jeneral yang berada dalam keadaan tidur atau mimpi ngeri bertukar menjadi batu, dia akan mencuri satu kesan peningkatan daripada sasaran.',
		zawakeEffect = __data_t__zawakeEffect[24316],
		-- {79004}
		zawakeEffectDesc = 'Aura Skill: When your evil/undead hero uses a normal attack or a minor skill to attack a target, it permanently steals the target\'s basic double attack #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (returns after death)\nActivated when there are 2 or more evil/undead heroes alive in the first round of the battle: immediately steal from 4 random enemy heroes who have 100 rage points and the total stolen rage is evenly distributed to adjacent demon/undead heroes.\nBefore Queen Boya Hancock acts, there is a 50% chance a random hero will enter <Spiritual Petrification> for 1 turn (cannot move, can be dispersed, and will be awakened after receiving 2 skill attack hits);\nQueen Boya Hancock will not awaken heroes when attacking sleeping nightmare or petrified statuses.',
		zawakeEffectDesc_en = 'Aura Skill: When your evil/undead hero uses a normal attack or a minor skill to attack a target, it permanently steals the target\'s basic double attack #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (returns after death)\nActivated when there are 2 or more evil/undead heroes alive in the first round of the battle: immediately steal from 4 random enemy heroes who have 100 rage points and the total stolen rage is evenly distributed to adjacent demon/undead heroes.\nBefore Queen Boya Hancock acts, there is a 50% chance a random hero will enter <Spiritual Petrification> for 1 turn (cannot move, can be dispersed, and will be awakened after receiving 2 skill attack hits);\nQueen Boya Hancock will not awaken heroes when attacking sleeping nightmare or petrified statuses.',
		zawakeEffectDesc_th = 'ทักษะออร่า: เมื่อฮีโร่ปีศาจ/ซากศพของคุณใช้การโจมตีปกติหรือสกิลเล็กโจมตีเป้าหมาย จะขโมยการโจมตีคู่พื้นฐานของเป้าหมายอย่างถาวร #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (กลับมาเมื่อฟื้นคืนชีพ)\nทำงานเมื่อมีฮีโร่ปีศาจ/ซากศพอย่างน้อย 2 ตัวอยู่รอดในรอบแรกของการต่อสู้: ขโมยจากศัตรู 4 ตัวแบบสุ่มที่มี 100 คะแนนความโกรธและแจกจ่ายความโกรธที่ขโมยได้อย่างเท่าเทียมให้ฮีโร่ปีศาจ/ซากศพที่อยู่ใกล้เคียง\nก่อนที่ราชินีโบยาแฮนค็อคจะลงมือ มีโอกาส 50% ที่ฮีโร่สุ่มจะเข้าสู่ <ขังหินทางจิตวิญญาณ> เป็นเวลา 1 เทิร์น (ไม่สามารถเคลื่อนที่ แยกออกได้ และจะตื่นขึ้นหลังรับการโจมตีสกิล 2 ครั้ง);\nราชินีโบยาแฮนค็อคจะไม่ปลุกฮีโร่เมื่อโจมตีสถานะฝันร้ายที่หลับหรือการขังหิน',
		zawakeEffectDesc_in = 'Keterampilan Aura: Ketika pahlawan jahat/mayat Anda menggunakan serangan normal atau skill kecil untuk menyerang target, ia akan secara permanen mencuri serangan ganda dasar target #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (kembali setelah mati)\nDiaktifkan ketika ada 2 atau lebih pahlawan jahat/mayat yang hidup pada ronde pertama pertarungan: segera mencuri dari 4 pahlawan musuh acak yang memiliki 100 poin kemarahan dan jumlah kemarahan yang dicuri secara total dibagikan rata kepada pahlawan setan/mayat di sekitar.\nSebelum Ratu Boya Hancock bertindak, ada kemungkinan 50% pahlawan acak masuk ke <Spiritual Petrification> selama 1 giliran (tidak dapat bergerak, dapat disebarkan, dan akan dibangunkan setelah menerima 2 serangan skill);\nRatu Boya Hancock tidak akan membangunkan pahlawan ketika menyerang status mimpi buruk yang tertidur atau mengalami pengerasan.',
		zawakeEffectDesc_ph = 'Kasanayan ng Aura: Kapag ang iyong masama/undead na bayani ay gumagamit ng normal na atake o maliit na kasanayan upang atakehin ang target, permanente nitong ninanakaw ang pangunahing dobleng atake ng target #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (babalik pagkatapos mamatay)\nNa-activate kapag may 2 o higit pang masama/undead na bayani buhay sa unang round ng labanan: agad na nagnanakaw mula sa 4 na random na kalaban na may 100 puntos na galit at ang kabuuang nagnakaw na galit ay pantay-pantay na ipinamamahagi sa mga karatig na demonyo/undead na bayani.\nBago kumilos si Reyna Boya Hancock, may 50% tsansa na ang isang random na bayani ay papasok sa <Spiritual Petrification> sa loob ng 1 round (hindi makagalaw, maaaring mabaliwas at magigising pagkatapos makatanggap ng 2 skill na atake);\nHindi gigisingin ni Reyna Boya Hancock ang bayani kapag inaatake ang nagpapahimbing na bangungot o na-petrify na estado.',
		zawakeEffectDesc_ma = 'Kemahiran Aura: Apabila wira jahat/mayat anda menggunakan serangan biasa atau kemahiran kecil untuk menyerang sasaran, ia akan mencuri secara kekal serangan berganda asas sasaran #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (kembali selepas mati)\nDiaktifkan apabila terdapat 2 atau lebih wira jahat/mayat yang hidup dalam pusingan pertama pertempuran: curi segera dari 4 wira musuh rawak yang mempunyai 100 mata kemarahan dan jumlah kiraan kemarahan yang dicuri diagihkan sama rata kepada wira iblis/mayat berdekatan.\nSebelum Ratu Boya Hancock bertindak, terdapat kebarangkalian 50% wira rawak akan memasuki <Spiritual Petrification> selama 1 giliran (tidak boleh bergerak, boleh dibubarkan dan akan dibangunkan selepas menerima 2 serangan kemahiran);\nRatu Boya Hancock tidak akan membangunkan wira apabila menyerang keadaan mimpi ngeri yang sedang tidur atau bertukar menjadi batu.',
		zawakeEffectDesc_vn = 'Kỹ năng hào quang: Khi tướng ác/xác sống của bạn sử dụng đòn tấn công bình thường hoặc kỹ năng nhỏ để tấn công mục tiêu, nó sẽ đánh cắp vĩnh viễn đòn tấn công kép cơ bản của mục tiêu #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (trở lại sau khi chết)\nĐược kích hoạt khi có 2 tướng ác/xác sống trở lên trong vòng đầu tiên của trận chiến: cướp ngay Kẻ địch có 4 tướng ngẫu nhiên nhắm mục tiêu có 100 điểm giận dữ và tổng số cơn giận bị đánh cắp được phân bổ đều cho các anh hùng ác quỷ/xác sống bên bạn\nTrước khi Hoàng hậu Boya Hancock hành động, có 50% xác suất một anh hùng ngẫu nhiên sẽ tiến vào <Hóa đá tâm linh> trong 1 hiệp (không thể di chuyển, có thể bị phân tán và sẽ được đánh thức sau khi nhận 2 đòn tấn công kỹ năng);\nNữ hoàng Boya Hancock sẽ không đánh thức anh hùng khi tấn công trạng thái ác mộng đang ngủ hoặc hóa đá.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Dark Aura evolves into Evil Aura: when your Demon/Undead heroes attack a target with normal attacks or minor skills, it will permanently steal the target’s basic double attacks\nTriggered when you have 2 or more Demon/Undead heroes on your side at the start of battle: 100 Fury will be instantly stolen from 4 random enemy targets, and the total Fury stolen will be evenly distributed among your own Demon/Undead heroes.',
		zawakeSimpleDesc_en = 'Dark Aura evolves into Evil Aura: when your Demon/Undead heroes attack a target with normal attacks or minor skills, it will permanently steal the target’s basic double attacks\nTriggered when you have 2 or more Demon/Undead heroes on your side at the start of battle: 100 Fury will be instantly stolen from 4 random enemy targets, and the total Fury stolen will be evenly distributed among your own Demon/Undead heroes.',
		zawakeSimpleDesc_th = 'ออร่าความมืดวิวัฒนาการเป็นออร่าปีศาจ: เมื่อฮีโร่ปีศาจ/อันเดดของคุณโจมตีเป้าหมายด้วยการโจมตีปกติหรือสกิลเล็ก จะขโมยการโจมตีคู่พื้นฐานของเป้าหมายอย่างถาวร\nทำงานเมื่อมีฮีโร่ปีศาจ/อันเดด 2 ตัวขึ้นไปอยู่ฝั่งคุณในรอบแรกของการต่อสู้: จะขโมยความโกรธ 100 แต้มจากศัตรูแบบสุ่ม 4 ตัว และแบ่งความโกรธที่ขโมยได้อย่างเท่าเทียมให้ฮีโร่ปีศาจ/อันเดดของคุณ',
		zawakeSimpleDesc_in = 'Aura Kegelapan berevolusi menjadi Aura Jahat: saat hero Iblis/Mayat Hidup kamu menyerang target dengan serangan biasa atau skill minor, mereka akan mencuri serangan ganda dasar target secara permanen\nAktif saat ada 2 atau lebih hero Iblis/Mayat Hidup di pihakmu di ronde pertama: 100 poin Amarah akan dicuri dari 4 musuh acak, lalu dibagikan merata ke semua hero Iblis/Mayat Hidup milikmu.',
		zawakeSimpleDesc_ph = 'Ang Dark Aura ay umuunlad bilang Evil Aura: kapag ang iyong mga Demon/Undead na bayani ay umatake gamit ang normal na atake o minor na kakayahan, permanenteng nananakaw ito ng basic double attack ng target\nNa-aactivate kapag may 2 o higit pang Demon/Undead heroes sa iyong panig sa unang round ng laban: Agad na nananakaw ng 100 Fury mula sa 4 random na kalaban at pantay-pantay itong ipapamahagi sa iyong Demon/Undead heroes.',
		zawakeSimpleDesc_ma = 'Aura Gelap berevolusi menjadi Aura Jahat: apabila hero Iblis/Zombi anda menyerang dengan serangan biasa atau kemahiran kecil, ia akan mencuri serangan berganda asas sasaran secara kekal\nDiaktifkan apabila anda mempunyai 2 atau lebih hero Iblis/Zombi di pihak anda pada pusingan pertama: 100 Kemarahan dicuri serta-merta daripada 4 sasaran musuh rawak dan jumlah Kemarahan yang dicuri akan dibahagikan sama rata kepada hero Iblis/Zombi anda.',
		zawakeSimpleDesc_vn = 'Quầng sáng bóng tối tiến hóa thành quầng sáng tà ác: khi anh hùng ác quỷ/xác sống của bạn tấn công mục tiêu bằng các đòn tấn công thông thường hoặc kỹ năng nhỏ, nó sẽ đánh cắp vĩnh viễn các đòn tấn công kép cơ bản của mục tiêu\nĐược kích hoạt khi có 2 anh hùng ác quỷ/xác sống trở lên ở bên bạn trong vòng đầu tiên của trận chiến: 100 điểm thịnh nộ ngay lập tức bị đánh cắp từ 4 mục tiêu kẻ thù ngẫu nhiên và tổng số cơn thịnh nộ bị đánh cắp sẽ được phân bổ đều cho các anh hùng xấu xa/xác sống của chính bạn.',
		changeUnitTrigger = true,
		isCombat = true,
