	[24321] = {
		id = 24321,
		skillName_vn = 'Ảo thuật',
		skillName_en = 'Magic',
		skillName_th = 'มายากล',
		skillName_in = 'Sulap',
		skillName_ph = 'Mahika',
		skillName_ma = 'Sihir',
		skillName = 'Magic',
		describe_vn = 'Darkrai sử dụng chiếc mũ ma thuật của mình và tạo ra một con búp bê gấu bom để tấn công một mục tiêu kẻ thù, gây ra #C0x3D8A99#100% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#sát thương ma thuật#C0x5B545B#, đồng thời đánh cắp 15% đòn tấn công kép và 15% tốc độ của nó, kéo dài 2 hiệp.',
		describe_en = 'Darkrai uses his magic hat to create a bomb bear doll to attack an enemy target, dealing #C0x3D8A99#100% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# magic damage#C0x5B545B#, while stealing 15% of its double attack and 15% of its speed, lasting 2 turns.',
		describe_th = 'Darkrai ใช้หมวกเวทมนตร์ของเขาสร้างตุ๊กตาหมีระเบิดเพื่อโจมตีเป้าหมายศัตรู ก่อให้เกิด #C0x3D8A99#100% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# พร้อมทั้งขโมยการโจมตีคู่ 15% และความเร็ว 15% จากเป้าหมาย นาน 2 เทิร์น',
		describe_in = 'Darkrai menggunakan topi sihirnya untuk menciptakan boneka beruang bom menyerang target musuh, memberikan #C0x3D8A99#100% Kerusakan Ajaib#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# kerusakan sihir#C0x5B545B#, sekaligus mencuri 15% serangan ganda dan 15% kecepatannya, bertahan selama 2 giliran.',
		describe_ph = 'Gumagamit si Darkrai ng kanyang magic hat upang lumikha ng bomb bear doll para atakihin ang isang kaaway na target, nagdudulot ng #C0x3D8A99#100% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# pinsalang magic#C0x5B545B#, kasabay ng pagnanakaw ng 15% ng double attack at 15% ng bilis nito, tumatagal ng 2 turn.',
		describe_ma = 'Darkrai menggunakan topi sihirnya untuk mencipta patung beruang bom menyerang sasaran musuh, menyebabkan #C0x3D8A99#100% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# kerosakan sihir#C0x5B545B#, sambil mencuri 15% serangan berganda dan 15% kelajuannya, berlangsung selama 2 pusingan.',
