	[24323] = {
		id = 24323,
		skillName_vn = 'Kẻ trộm giấc mơ, kẻ cắp trái tim',
		skillName_en = 'Dream Thief, Heart Stealer',
		skillName_th = 'โจรแห่งความฝัน ขโมยหัวใจ',
		skillName_in = 'Pencuri Mimpi, Pencuri Hati',
		skillName_ph = 'Magnanakaw ng Pangarap, Magnanakaw ng Puso',
		skillName_ma = 'Pencuri Mimpi, Pencuri Hati',
		skillName = 'Dream Thief, Heart Stealer',
		describe_vn = 'Darkrai lẻn vào không gian trong mơ, đánh cắp trái tim của kẻ địch và gây #C0xF13B54# sát thương phép#C0x của #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$ lên tất cả mục tiêu của kẻ địch. 5B545B#, có 40% khả năng khiến nó rơi vào [Ác mộng] trong 1 hiệp (Ác mộng: hiệu ứng khống chế, không thể di chuyển, không thể xua tan, sẽ thức tỉnh sau khi bị tấn công bởi 2 kỹ năng chủ động). Sau khi cơn ác mộng tỉnh dậy, địch sẽ rơi vào trạng thái suy yếu trong 1 hiệp (giảm 20% phòng thủ kép và 20% tấn công kép)',
		describe_en = 'Darkrai sneaks into the dream realm, steals the hearts of enemies, and deals #C0xF13B54# magic damage #C0x of #C0x3D8A99#180% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$ to all enemy targets. 5B545B#, with a 40% chance to inflict [Nightmare] for 1 turn (Nightmare: a control effect, unable to move or dispel, will awaken after being hit by 2 active skills). After awakening from the nightmare, the enemy enters a weakened state for 1 turn (reduces dual defense and dual attack by 20%).',
		describe_th = 'Darkrai แทรกซึมเข้าสู่โลกแห่งความฝัน ขโมยหัวใจของศัตรูและก่อให้เกิด #C0xF13B54# ความเสียหายเวทมนตร์ #C0x ของ #C0x3D8A99#180% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*60)$ กับเป้าหมายศัตรูทั้งหมด 5B545B# พร้อมโอกาส 40% ที่จะทำให้ติด [ฝันร้าย] เป็นเวลา 1 เทิร์น (ฝันร้าย: สถานะควบคุม ไม่สามารถเคลื่อนที่หรือขจัดได้ จะตื่นขึ้นหลังจากถูกโจมตีด้วยสกิลแอคทีฟ 2 ครั้ง) หลังจากตื่นจากฝันร้าย ศัตรูจะเข้าสู่สถานะอ่อนแอเป็นเวลา 1 เทิร์น (ลดการป้องกันคู่และการโจมตีคู่ลง 20%)',
		describe_in = 'Darkrai menyusup ke dunia mimpi, mencuri hati musuh, dan memberikan #C0xF13B54# kerusakan sihir #C0x sebesar #C0x3D8A99#180% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*60)$ ke semua target musuh. 5B545B#, dengan peluang 40% untuk menyebabkan [Mimpi Buruk] selama 1 giliran (Mimpi Buruk: efek kontrol, tidak bisa bergerak atau menghilangkan, akan bangun setelah terkena 2 skill aktif). Setelah bangun dari mimpi buruk, musuh akan dalam kondisi lemah selama 1 giliran (mengurangi pertahanan ganda dan serangan ganda sebesar 20%).',
		describe_ph = 'Darkrai ayaw sumilip sa loob ng panaginip, nanakaw ng puso ng kalaban at nagdudulot ng #C0xF13B54# pinsalang magic #C0x ng #C0x3D8A99#180% Pinsalang Magic#C0x5B545B#+$(skillLevel*4*60)$ sa lahat ng kalaban. 5B545B#, may 40% na tsansang maipataw ang [Bangungot] sa loob ng 1 turn (Bangungot: control effect, hindi makagalaw o matanggal, gigising kapag tinamaan ng 2 aktibong skill). Pagkatapos gumising mula sa bangungot, ang kalaban ay papasok sa isang mahina na estado sa loob ng 1 turn (bumababa ang dobleng depensa at dobleng atake ng 20%).',
		describe_ma = 'Darkrai menyelinap ke dalam ruang mimpi, mencuri hati musuh dan memberi #C0xF13B54# kerosakan sihir #C0x sebanyak #C0x3D8A99#180% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*60)$ kepada semua sasaran musuh. 5B545B#, dengan peluang 40% untuk menyebabkan [Mimpi Ngeri] selama 1 giliran (Mimpi Ngeri: kesan kawalan, tidak boleh bergerak atau membuang, akan terjaga selepas diserang oleh 2 kemahiran aktif). Selepas terjaga dari mimpi ngeri, musuh akan jatuh dalam keadaan lemah selama 1 giliran (mengurangkan pertahanan berganda dan serangan berganda sebanyak 20%).',
		describe = 'Darkrai sneaks into the dream realm, steals the hearts of enemies, and deals #C0xF13B54# magic damage #C0x of #C0x3D8A99#180% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$ to all enemy targets. 5B545B#, with a 40% chance to inflict [Nightmare] for 1 turn (Nightmare: a control effect, unable to move or dispel, will awaken after being hit by 2 active skills). After awakening from the nightmare, the enemy enters a weakened state for 1 turn (reduces dual defense and dual attack by 20%).',
		simDesc_vn = 'Darkrai thức dậy từ màn đêm, nhấn chìm mọi thứ xung quanh vào cơn ác mộng, sau đó triệu hồi hàng chục triệu bàn tay ma tấn công tất cả mục tiêu của kẻ thù, có khả năng khiến chúng rơi vào ác mộng. Những cơn ác mộng sẽ thức dậy và làm chúng yếu đi.',
		simDesc_en = 'Darkrai awakens from the darkness, plunging everything around into a nightmare, then summons tens of millions of ghostly hands to attack all enemy targets, with the power to trap them in nightmares. The nightmares will awaken and weaken them.',
		simDesc_th = 'ดาร์ครายตื่นขึ้นจากความมืด กลืนทุกสิ่งรอบตัวลงไปในฝันร้าย จากนั้นเรียกมือผีจำนวนหลายสิบล้านมือโจมตีเป้าหมายศัตรูทั้งหมด ซึ่งสามารถทำให้พวกเขาตกอยู่ในฝันร้าย ฝันร้ายเหล่านั้นจะตื่นขึ้นและทำให้พวกเขาอ่อนแอลง',
		simDesc_in = 'Darkrai terbangun dari kegelapan, menenggelamkan segala sesuatu di sekitarnya ke dalam mimpi buruk, kemudian memanggil puluhan juta tangan hantu untuk menyerang semua target musuh, dengan kemampuan membuat mereka jatuh ke dalam mimpi buruk. Mimpi buruk itu akan bangkit dan melemahkan mereka.',
		simDesc_ph = 'Nagising si Darkrai mula sa dilim, nalunod ang lahat sa paligid sa isang bangungot, pagkatapos ay tinawag ang sampu-sampung milyong mga kamay ng multo upang atakihin ang lahat ng mga target na kaaway, may kakayahang dalhin sila sa bangungot. Ang mga bangungot ay magigising at pahinain sila.',
		simDesc_ma = 'Darkrai bangkit dari kegelapan, menenggelamkan segala-galanya di sekeliling ke dalam mimpi ngeri, kemudian memanggil berpuluh juta tangan hantu untuk menyerang semua sasaran musuh, dengan kebolehan menyebabkan mereka terperangkap dalam mimpi ngeri. Mimpi ngeri itu akan bangkit dan melemahkan mereka.',
		simDesc = 'Darkrai awakens from the darkness, plunging everything around into a nightmare, then summons tens of millions of ghostly hands to attack all enemy targets, with the power to trap them in nightmares. The nightmares will awaken and weaken them.',
		starEffect = __data_t__starEffect[24323],
		-- {11}
		starEffectDesc_vn = 'Sau khi thi triển tuyệt kỹ, toàn bộ khung cảnh sẽ biến thành Mộng Cảnh Ác Mộng, kéo dài 1 hiệp; trong Mộng Cảnh Ác Mộng, Darkrai sẽ đánh cắp khả năng giảm sát thương của phe địch (tổng cộng 60%, chia đều cho mỗi mục tiêu địch); trong Mộng Cảnh Ác Mộng, các tướng bị trạng thái Ngủ hoặc Ác Mộng sẽ không bị đánh thức khi bị tấn công.',
		starEffectDesc = 'After unleashing the ultimate skill, the entire scene will transform into Nightmare Dreamscape, lasting for 1 turn; in the Nightmare Dreamscape, Darkrai will steal the damage reduction ability from enemy side (total 60%, evenly distributed among each enemy target); in the Nightmare Dreamscape, heroes affected by Sleep or Nightmare status will not be awakened when attacked.',
		starEffectDesc_en = 'After unleashing the ultimate skill, the entire scene will transform into Nightmare Dreamscape, lasting for 1 turn; in the Nightmare Dreamscape, Darkrai will steal the damage reduction ability from enemy side (total 60%, evenly distributed among each enemy target); in the Nightmare Dreamscape, heroes affected by Sleep or Nightmare status will not be awakened when attacked.',
		starEffectDesc_th = 'หลังจากใช้ท่าไม้ตาย ฉากทั้งหมดจะเปลี่ยนเป็นฝันร้ายฝันวิกลจริตเป็นเวลา 1 เทิร์น; ในฝันร้ายฝันวิกลจริต Darkrai จะขโมยความสามารถลดความเสียหายจากฝ่ายศัตรู (รวม 60% แบ่งเท่าๆ กันในแต่ละเป้าหมายศัตรู); ในฝันร้ายฝันวิกลจริต ฮีโร่ที่มีสถานะหลับหรือฝันร้ายจะไม่ถูกปลุกเมื่อถูกโจมตี',
		starEffectDesc_in = 'Setelah mengeluarkan skill pamungkas, seluruh pemandangan akan berubah menjadi Mimpi Mengerikan, berlangsung selama 1 giliran; dalam Mimpi Mengerikan, Darkrai akan mencuri kemampuan pengurangan kerusakan dari pihak musuh (total 60%, dibagi rata untuk setiap target musuh); dalam Mimpi Mengerikan, pahlawan yang terkena status Tidur atau Mimpi Buruk tidak akan terbangun saat diserang.',
		starEffectDesc_ph = 'Pagkatapos gamitin ang ultimate skill, ang buong eksena ay magbabago sa Nightmare Dreamscape, tatagal ng 1 turn; sa Nightmare Dreamscape, si Darkrai ay magnanakaw ng kakayahang magbawas ng pinsala mula sa kalabang panig (kabuuang 60%, pantay-pantay na hinahati sa bawat kalabang target); sa Nightmare Dreamscape, ang mga bayani na may Sleep o Nightmare status ay hindi magigising kapag inatake.',
		starEffectDesc_ma = 'Selepas menggunakan kemahiran utama, keseluruhan suasana akan berubah menjadi Mimpi Ngeri, berlangsung selama 1 pusingan; dalam Mimpi Ngeri, Darkrai akan mencuri keupayaan pengurangan kerosakan pihak musuh (jumlah keseluruhan 60%, dibahagikan sama rata untuk setiap sasaran musuh); dalam Mimpi Ngeri, wira yang berada dalam status Tidur atau Mimpi Ngeri tidak akan terjaga apabila diserang.',
		zawakeEffect = __data_t__zawakeEffect[24323],
		-- {79003}
		zawakeEffectDesc = 'Darkrai sneaks into the dream space, steals the hearts of enemies, and deals #C0xF13B54# magic damage #C0x of #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$ to all enemy targets. 5B545B#, with a 50% chance to put them into <Nightmare> for 1 turn (Nightmare: control effect, cannot move, cannot be dispelled, will be awakened after being hit by 2 active skills), enemies awakened from the nightmare will fall into a weak state for 2 turns (reducing 20% double defense and 20% double attack)',
		zawakeEffectDesc_en = 'Darkrai sneaks into the dream space, steals the hearts of enemies, and deals #C0xF13B54# magic damage #C0x of #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$ to all enemy targets. 5B545B#, with a 50% chance to put them into <Nightmare> for 1 turn (Nightmare: control effect, cannot move, cannot be dispelled, will be awakened after being hit by 2 active skills), enemies awakened from the nightmare will fall into a weak state for 2 turns (reducing 20% double defense and 20% double attack)',
		zawakeEffectDesc_th = 'Darkrai แอบเข้ามาในโลกแห่งความฝัน ขโมยหัวใจของศัตรูและสร้าง #C0xF13B54# พิษเวทมนตร์ #C0x ที่ #C0x3D8A99#180% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*60)$ ไปยังเป้าหมายศัตรูทั้งหมด 5B545B# โดยมีโอกาส 50% ที่จะทำให้พวกเขาเข้าสู่ <ฝันร้าย> เป็นเวลา 1 เทิร์น (ฝันร้าย: ผลควบคุม, ไม่สามารถเคลื่อนที่, ไม่สามารถลบได้, จะตื่นขึ้นหลังถูกโจมตีด้วยสกิลแอคทีฟ 2 ครั้ง) ศัตรูที่ตื่นจากฝันร้ายจะตกอยู่ในสถานะอ่อนแอเป็นเวลา 2 เทิร์น (ลดการป้องกันคู่ 20% และการโจมตีคู่ 20%)',
		zawakeEffectDesc_in = 'Darkrai menyelinap ke dalam ruang mimpi, mencuri hati musuh, dan memberikan #C0xF13B54# kerusakan sihir #C0x sebesar #C0x3D8A99#180% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*60)$ ke semua target musuh. 5B545B#, dengan peluang 50% untuk membuat mereka masuk ke dalam <Mimpi Buruk> selama 1 giliran (Mimpi Buruk: efek kontrol, tidak dapat bergerak, tidak dapat dihilangkan, akan terbangun setelah terkena 2 skill aktif), musuh yang terbangun dari mimpi buruk akan masuk ke status lemah selama 2 giliran (mengurangi 20% pertahanan ganda dan 20% serangan ganda)',
		zawakeEffectDesc_ph = 'Pumapasok si Darkrai sa panaginip na espasyo, nagnanakaw ng puso ng kalaban at nagdudulot ng #C0xF13B54# magic damage #C0x ng #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$ sa lahat ng kalabang target. 5B545B#, may 50% tsansang maglagay sa kanila sa <Nightmare> sa loob ng 1 turn (Nightmare: control effect, hindi makagalaw, hindi matanggal, gigisingin matapos ma-apektuhan ng 2 active skills), ang mga kalabang gigising mula sa nightmare ay mapupunta sa mahina na estado sa loob ng 2 turn (binabawasan ang 20% double defense at 20% double attack)',
		zawakeEffectDesc_ma = 'Darkrai menyelinap ke dalam ruang mimpi, mencuri hati musuh dan menyebabkan #C0xF13B54# kerosakan sihir #C0x sebanyak #C0x3D8A99#180% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*60)$ kepada semua sasaran musuh. 5B545B#, dengan kebarangkalian 50% untuk menyebabkan mereka jatuh ke dalam <Mimpi Ngeri> selama 1 pusingan (Mimpi Ngeri: kesan kawalan, tidak boleh bergerak, tidak boleh dihapus, akan terjaga selepas terkena 2 kemahiran aktif), musuh yang terjaga dari mimpi ngeri akan jatuh ke dalam keadaan lemah selama 2 pusingan (mengurangkan 20% pertahanan berganda dan 20% serangan berganda)',
		zawakeEffectDesc_vn = 'Darkrai lẻn vào không gian trong mơ, đánh cắp trái tim của kẻ địch và gây #C0xF13B54# sát thương phép#C0x của #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$ lên tất cả mục tiêu của kẻ địch. 5B545B#, có 50% xác suất khiến nó rơi vào <Cơn ác mộng> trong 1 hiệp (Ác mộng: hiệu ứng khống chế, không thể di chuyển, không thể xua tan, sẽ bị đánh thức sau khi bị tấn công bởi 2 kỹ năng chủ động), kẻ địch sau khi thức tỉnh từ cơn ác mộng sẽ rơi vào trạng thái yếu trong 2 hiệp (giảm 20% phòng thủ kép và 20% tấn công kép)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Has a 40% chance to put the target into a <Nightmare> state for 1 round\nEnemies who awaken from the Nightmare will fall into a weakened state for 1 round\n#F20# \n#F40##C0x5c9970#→Has a 50% chance to put the target into a <Nightmare> state for 1 round\nEnemies who awaken from the Nightmare will fall into a weakened state for 2 rounds',
		zawakeSimpleDesc_en = 'Has a 40% chance to put the target into a <Nightmare> state for 1 round\nEnemies who awaken from the Nightmare will fall into a weakened state for 1 round\n#F20# \n#F40##C0x5c9970#→Has a 50% chance to put the target into a <Nightmare> state for 1 round\nEnemies who awaken from the Nightmare will fall into a weakened state for 2 rounds',
		zawakeSimpleDesc_th = 'มีโอกาส 40% ทำให้เป้าหมายเข้าสู่สถานะ <ฝันร้าย> 1 เทิร์น\nศัตรูที่ตื่นจากฝันร้ายจะเข้าสู่สถานะอ่อนแอเป็นเวลา 1 เทิร์น\n#F20# \n#F40##C0x5c9970#→มีโอกาส 50% ทำให้เป้าหมายเข้าสู่สถานะ <ฝันร้าย> 1 เทิร์น\nศัตรูที่ตื่นจากฝันร้ายจะเข้าสู่สถานะอ่อนแอเป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Memiliki 40% peluang membuat target masuk ke dalam <Mimpi Buruk> selama 1 ronde\nMusuh yang terbangun dari Mimpi Buruk akan berada dalam keadaan lemah selama 1 ronde\n#F20# \n#F40##C0x5c9970#→Memiliki 50% peluang membuat target masuk ke dalam <Mimpi Buruk> selama 1 ronde\nMusuh yang terbangun dari Mimpi Buruk akan berada dalam keadaan lemah selama 2 ronde',
		zawakeSimpleDesc_ph = 'May 40% chance na ilagay ang target sa <Bangungot> sa loob ng 1 turn\nAng mga kalabang nagising mula sa Bangungot ay mahihina sa loob ng 1 turn\n#F20# \n#F40##C0x5c9970#→May 50% chance na ilagay ang target sa <Bangungot> sa loob ng 1 turn\nAng mga kalabang nagising mula sa Bangungot ay mahihina sa loob ng 2 turn',
		zawakeSimpleDesc_ma = 'Ada 40% peluang menyebabkan sasaran berada dalam keadaan <Mimpi Ngeri> selama 1 pusingan\nMusuh yang tersedar dari Mimpi Ngeri akan berada dalam keadaan lemah selama 1 pusingan\n#F20# \n#F40##C0x5c9970#→Ada 50% peluang menyebabkan sasaran berada dalam keadaan <Mimpi Ngeri> selama 1 pusingan\nMusuh yang tersedar dari Mimpi Ngeri akan berada dalam keadaan lemah selama 2 pusingan',
		zawakeSimpleDesc_vn = 'Có 40% xác suất khiến mục tiêu rơi vào trạng thái <Ác mộng> trong 1 lượt\nKẻ địch tỉnh dậy từ ác mộng sẽ rơi vào trạng thái suy yếu trong 1 lượt\n#F20# \n#F40##C0x5c9970#→Có 50% xác suất khiến mục tiêu rơi vào trạng thái <Ác mộng> trong 1 lượt\nKẻ địch tỉnh dậy từ ác mộng sẽ rơi vào trạng thái suy yếu trong 2 lượt',
