	[24326] = {
		id = 24326,
		skillName_vn = 'Entering Dream',
		skillName_en = 'Entering Dream',
		skillName_th = 'เข้าสู่ความฝัน',
		skillName_in = 'Memasuki Mimpi',
		skillName_ph = 'Pumapasok sa Panaginip',
		skillName_ma = 'Memasuki Mimpi',
		skillName = 'Entering Dream',
		describe_vn = 'Kỹ năng hào quang: Khi anh hùng bóng tối của bạn tấn công mục tiêu bằng đòn tấn công cơ bản, anh ta sẽ đánh cắp vĩnh viễn đòn tấn công kép cơ bản của mục tiêu #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (trở lại sau khi chết));\nTrước khi Darkrai hành động, có 50% khả năng một anh hùng ngẫu nhiên sẽ vào [Ngủ sâu] trong 1 hiệp (không thể di chuyển, có thể) bị xua tan và sẽ thức tỉnh sau khi nhận 2 đòn tấn công kỹ năng);\nDarkrai sẽ không đánh thức anh hùng khi họ tấn công trạng thái ngủ hoặc ác mộng.',
		describe_en = 'Aura Skill: When your dark hero attacks a target with a basic attack, he will permanently steal the target\'s dual basic attack #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (returns after death);\nBefore Darkrai acts, there is a 50% chance that a random hero will fall into [Deep Sleep] for 1 turn (unable to move, can be dispelled) and will awaken after receiving 2 skill attack hits);\nDarkrai will not awaken heroes when they attack the sleep or nightmare status.',
		describe_th = 'ทักษะออร่า: เมื่อฮีโร่แห่งความมืดของคุณโจมตีเป้าหมายด้วยการโจมตีพื้นฐาน เขาจะขโมยการโจมตีพื้นฐานคู่ของเป้าหมายอย่างถาวร #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (จะกลับคืนหลังตาย);\nก่อนที่ Darkrai จะทำการกระทำ จะมีโอกาส 50% ที่ฮีโร่สุ่มคนหนึ่งจะเข้าสู่ [หลับลึก] เป็นเวลา 1 เทิร์น (ไม่สามารถเคลื่อนที่ได้ สามารถถูกขจัดได้) และจะตื่นหลังจากได้รับการโจมตีสกิล 2 ครั้ง);\nDarkrai จะไม่ปลุกฮีโร่เมื่อพวกเขาโจมตีสถานะหลับหรือตื่นฝันร้าย',
		describe_in = 'Kemampuan Aura: Ketika pahlawan kegelapan Anda menyerang target dengan serangan dasar, dia akan mencuri selamanya serangan ganda dasar target #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (kembali setelah mati);\nSebelum Darkrai bertindak, ada peluang 50% pahlawan acak akan masuk [Tidur Dalam] selama 1 giliran (tidak bisa bergerak, bisa dihapus) dan akan bangun setelah menerima 2 serangan keterampilan);\nDarkrai tidak akan membangunkan pahlawan saat mereka menyerang status tidur atau mimpi buruk.',
		describe_ph = 'Kasanayan ng Aura: Kapag inatake ng iyong madilim na bayani ang isang target gamit ang pangunahing atake, permanente niyang ninanakaw ang dobleng pangunahing atake ng target #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (babalik pagkatapos mamatay);\nBago kumilos si Darkrai, may 50% tsansa na ang isang random na bayani ay pumasok sa [Malalim na Tulog] ng 1 turn (hindi makagalaw, maaaring ma-dispel) at gisingin matapos makatanggap ng 2 skill attack);\nHindi gigisingin ni Darkrai ang mga bayani kapag inaatake nila ang status na tulog o bangungot.',
		describe_ma = 'Kemahiran Aura: Apabila wira gelap anda menyerang sasaran dengan serangan asas, dia akan mencuri secara kekal serangan asas berganda sasaran #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (kembali selepas mati);\nSebelum Darkrai bertindak, terdapat peluang 50% seorang wira rawak akan masuk [Tidur Dalam] selama 1 pusingan (tidak boleh bergerak, boleh disingkirkan) dan akan sedar selepas menerima 2 serangan kemahiran);\nDarkrai tidak akan membangunkan wira apabila mereka menyerang status tidur atau mimpi ngeri.',
		describe = 'Aura Skill: When your dark hero attacks a target with a basic attack, he will permanently steal the target\'s dual basic attack #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (returns after death);\nBefore Darkrai acts, there is a 50% chance that a random hero will fall into [Deep Sleep] for 1 turn (unable to move, can be dispelled) and will awaken after receiving 2 skill attack hits);\nDarkrai will not awaken heroes when they attack the sleep or nightmare status.',
		starEffect = __data_t__starEffect[24326],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng thêm: Darkrai miễn nhiễm hiệu ứng Ngủ và Ác Mộng, khi tấn công tướng đang trong trạng thái Ngủ hoặc Ác Mộng, sẽ đánh cắp một hiệu ứng có lợi của mục tiêu.',
		starEffectDesc = 'Additional effect: Darkrai is immune to Sleep and Nightmare effects. When attacking a hero in Sleep or Nightmare state, it will steal one beneficial effect from the target.',
		starEffectDesc_en = 'Additional effect: Darkrai is immune to Sleep and Nightmare effects. When attacking a hero in Sleep or Nightmare state, it will steal one beneficial effect from the target.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: Darkrai ป้องกันผลกระทบจากการหลับและฝันร้าย เมื่อโจมตีฮีโร่ที่อยู่ในสถานะหลับหรือฝันร้าย จะขโมยเอฟเฟกต์ที่เป็นประโยชน์หนึ่งอย่างจากเป้าหมาย',
		starEffectDesc_in = 'Efek tambahan: Darkrai kebal terhadap efek Tidur dan Mimpi Buruk, saat menyerang hero yang sedang dalam keadaan Tidur atau Mimpi Buruk, akan mencuri satu efek menguntungkan dari target.',
		starEffectDesc_ph = 'Karagdagang epekto: Ang Darkrai ay immune sa epekto ng Tulog at Bangungot, kapag inatake ang bayani na nasa estado ng Tulog o Bangungot, ninanakaw nito ang isang kapaki-pakinabang na epekto mula sa target.',
		starEffectDesc_ma = 'Kesan tambahan: Darkrai kebal terhadap kesan Tidur dan Mimpi Buruk, apabila menyerang wira yang berada dalam keadaan Tidur atau Mimpi Buruk, ia akan mencuri satu kesan bermanfaat daripada sasaran.',
		zawakeEffect = __data_t__zawakeEffect[24326],
		-- {79004}
		zawakeEffectDesc = 'Aura skill: When your demon/undead hero uses normal attacks or minor skills to attack a target, he will permanently steal the target\'s basic double attack #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (returns after death)\nIn the first round of the battle, your own evil/spirit/dead heroes can steal 100 rage points from the target when using normal attacks or minor skills.\nBefore Darkrai acts, there is a 50% chance that a random hero will fall into <Deep Sleep> for 1 turn (cannot move, can be dispersed, and will wake up after receiving 2 skill attack hits);\nDarkrai will not awaken heroes when he attacks with sleep or nightmare status.',
		zawakeEffectDesc_en = 'Aura skill: When your demon/undead hero uses normal attacks or minor skills to attack a target, he will permanently steal the target\'s basic double attack #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (returns after death)\nIn the first round of the battle, your own evil/spirit/dead heroes can steal 100 rage points from the target when using normal attacks or minor skills.\nBefore Darkrai acts, there is a 50% chance that a random hero will fall into <Deep Sleep> for 1 turn (cannot move, can be dispersed, and will wake up after receiving 2 skill attack hits);\nDarkrai will not awaken heroes when he attacks with sleep or nightmare status.',
		zawakeEffectDesc_th = 'ทักษะออร่า: เมื่อฮีโร่ปีศาจ/ผีดิบของคุณใช้การโจมตีปกติหรือสกิลเล็กโจมตีเป้าหมาย เขาจะขโมยการโจมตีคู่พื้นฐานของเป้าหมายไปถาวร #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (กลับคืนหลังความตาย)\nในรอบแรกของการต่อสู้ ฮีโร่ปีศาจ/จิตวิญญาณ/ผู้ที่ตายของคุณสามารถขโมยพลังแค้น 100 คะแนนจากเป้าหมายเมื่อใช้การโจมตีปกติหรือสกิลเล็ก \nก่อนที่ Darkrai จะทำการกระทำ มีโอกาส 50% ที่ฮีโร่สุ่มคนหนึ่งจะตกอยู่ใน <หลับลึก> เป็นเวลา 1 เทิร์น (ไม่สามารถเคลื่อนที่ได้ อาจถูกแยก และจะตื่นหลังจากได้รับการโจมตีด้วยสกิล 2 ครั้ง);\nDarkrai จะไม่ปลุกฮีโร่เมื่อเขาโจมตีสถานะหลับหรือนิทราร้าย',
		zawakeEffectDesc_in = 'Skill aura: Ketika pahlawan iblis/undead Anda menggunakan serangan normal atau skill kecil untuk menyerang target, dia akan mencuri secara permanen serangan ganda dasar target #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (kembali setelah mati)\nPada putaran pertama pertarungan, pahlawan jahat/roh/mati anda sendiri dapat mencuri 100 poin kemarahan dari target saat menggunakan serangan normal atau skill kecil.\nSebelum Darkrai bertindak, ada kemungkinan 50% seorang pahlawan acak akan jatuh ke dalam <Tidur Dalam> selama 1 giliran (tidak bisa bergerak, dapat dibubarkan, dan akan bangun setelah menerima 2 serangan skill);\nDarkrai tidak akan membangunkan pahlawan saat ia menyerang status tidur atau mimpi buruk.',
		zawakeEffectDesc_ph = 'Kasanayan sa aura: Kapag ginamit ng iyong diyablo/undead na bayani ang mga normal na pag-atake o maliliit na kasanayan upang atakihin ang target, permanente niyang naisinang ang pangunahing dobleng pag-atake ng target #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (babalik pagkatapos mamatay)\nSa unang round ng laban, maaaring magnakaw ang iyong sariling masasamang/espiritwal/namatay na mga bayani ng 100 punto ng galit mula sa target kapag gumamit ng mga normal na pag-atake o maliliit na kasanayan.\nBago kumilos si Darkrai, may 50% tsansa na ang isang random na bayani ay mahuhulog sa <Deep Sleep> ng 1 turn (hindi makagalaw, maaaring matanggal, at magigising pagkatapos makatanggap ng 2 skill na atake);\nHindi gigisingin ni Darkrai ang mga bayani kapag inaatake niya ang status na tulog o bangungot.',
		zawakeEffectDesc_ma = 'Kemahiran aura: Apabila wira iblis/mayat hidup anda menggunakan serangan biasa atau kemahiran kecil untuk menyerang sasaran, dia akan mencuri serangan berganda asas sasaran secara kekal #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (kembali selepas mati)\nDalam pusingan pertama pertempuran, wira jahat/rohani/mati anda sendiri boleh mencuri 100 mata kemarahan daripada sasaran apabila menggunakan serangan biasa atau kemahiran kecil.\nSebelum Darkrai bertindak, terdapat peluang 50% seorang wira rawak akan jatuh ke <Tidur Mendalam> selama 1 pusingan (tidak boleh bergerak, boleh dibubarkan, dan akan bangun selepas menerima 2 serangan kemahiran);\nDarkrai tidak akan membangunkan wira apabila dia menyerang dengan status tidur atau mimpi ngeri.',
		zawakeEffectDesc_vn = 'Kỹ năng hào quang: Khi anh hùng ác quỷ/xác sống của bạn sử dụng các đòn tấn công thông thường hoặc kỹ năng nhỏ để tấn công mục tiêu, anh ta sẽ đánh cắp vĩnh viễn đòn tấn công kép cơ bản của mục tiêu #C0x5c9970#$(3+skillLevel*0,03-0,03)$%#C0x5B545B# (trở lại sau khi chết)\nTrong vòng đầu tiên của trận chiến, các anh hùng Tâm linh tà ác/đã chết của chính bạn có thể đánh cắp 100 điểm thịnh nộ từ mục tiêu khi sử dụng các đòn tấn công thông thường hoặc các kỹ năng nhỏ.\nTrước khi Darkrai hành động, có 50% khả năng một anh hùng ngẫu nhiên sẽ rơi vào <Ngủ sâu> trong 1 hiệp (không thể di chuyển, có thể bị phân tán và sẽ thức dậy sau khi nhận 2 đòn tấn công kỹ năng);\nDarkrai sẽ không đánh thức anh hùng khi anh ta tấn công trạng thái ngủ hoặc ác mộng.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Dark Aura evolves into Demonic Aura: When your Demon/Undead heroes use basic attacks or minor skills to attack targets, they can permanently steal the target’s basic double attack\nIn the first round of battle, your Demon/Undead heroes can steal 100 Rage points from targets when using basic attacks or minor skills to attack.',
		zawakeSimpleDesc_en = 'Dark Aura evolves into Demonic Aura: When your Demon/Undead heroes use basic attacks or minor skills to attack targets, they can permanently steal the target’s basic double attack\nIn the first round of battle, your Demon/Undead heroes can steal 100 Rage points from targets when using basic attacks or minor skills to attack.',
		zawakeSimpleDesc_th = 'ออร่ามืดวิวัฒนาการเป็นออร่าปีศาจ: เมื่อฮีโร่ปีศาจ/อันเดดของคุณใช้การโจมตีปกติหรือสกิลเล็กโจมตีศัตรู จะสามารถขโมยการโจมตีคู่พื้นฐานของเป้าหมายอย่างถาวรได้\nในรอบแรกของการต่อสู้ ฮีโร่ปีศาจ/อันเดดของคุณสามารถขโมยความโกรธ 100 แต้มจากเป้าหมายเมื่อใช้การโจมตีปกติหรือสกิลเล็ก',
		zawakeSimpleDesc_in = 'Aura Gelap berevolusi menjadi Aura Iblis: Saat hero Iblis/Mayat Hidup kamu menggunakan serangan biasa atau skill kecil untuk menyerang target, mereka dapat mencuri serangan ganda dasar target secara permanen\nPada ronde pertama pertempuran, hero Iblis/Mayat Hidup kamu dapat mencuri 100 poin Amarah dari target saat menggunakan serangan biasa atau skill kecil.',
		zawakeSimpleDesc_ph = 'Ang Dark Aura ay nag-evolve bilang Demonic Aura: Kapag ang iyong Demon/Undead na mga bayani ay gumagamit ng basic attack o minor skill upang umatake, maaari nilang permanenteng nakawin ang basic double attack ng kalaban\nSa unang round ng laban, maaaring magnakaw ng 100 Rage points mula sa target ang iyong mga Demon/Undead heroes gamit ang basic attack o minor skill.',
		zawakeSimpleDesc_ma = 'Aura Gelap berevolusi menjadi Aura Syaitan: Apabila hero Iblis/Zombi anda menggunakan serangan biasa atau kemahiran kecil untuk menyerang, mereka boleh mencuri serangan berganda asas sasaran secara kekal\nPada pusingan pertama pertempuran, hero Iblis/Zombi anda boleh mencuri 100 mata Kemarahan daripada sasaran semasa menyerang menggunakan serangan biasa atau kemahiran kecil.',
		zawakeSimpleDesc_vn = 'Hào quang đen tối tiến hóa thành hào quang ma quái: Khi anh hùng ác quỷ/xác sống của chính bạn sử dụng các đòn tấn công thông thường hoặc kỹ năng nhỏ để tấn công mục tiêu, bạn có thể đánh cắp vĩnh viễn đòn tấn công kép cơ bản của mục tiêu\nTrong vòng đầu tiên của trận chiến, anh hùng ác quỷ/xác sống của chính bạn có thể đánh cắp 100 điểm thịnh nộ từ mục tiêu khi bạn sử dụng các đòn tấn công thông thường hoặc kỹ năng nhỏ để tấn công.',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {243261, 243262}
	},
	[24411] = {
		id = 24411,
		skillName_vn = 'Đâm cỏ',
		skillName_en = 'Grass stabbing',
		skillName_th = 'แทงหญ้า',
		skillName_in = 'Tusuk rumput',
		skillName_ph = 'Tusok damo',
		skillName_ma = 'Tikam rumput',
		skillName = 'Grass stabbing',
		describe_vn = 'Xie Mi cuộn tròn cơ thể, dồn toàn lực lao vào mục tiêu đơn lẻ của kẻ địch để tấn công, gây #C0x3D8A99#100% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ sát thương#C0xF13B54# pháp thuật#C0x5B545B#, tăng 60% song phòng của bản thân, duy trì trong 2 lượt',
		describe_en = 'Xie Mi curls up his body and focuses all his strength to charge at a single enemy target, dealing 100% Magic Attack + $(skillLevel*4*24)$ magic damage, increases his dual defense by 60%, lasting for 2 turns.',
		describe_th = 'เซียหมี่กลมตัวและทุ่มพลังทั้งหมดเพื่อพุ่งโจมตียังเป้าหมายศัตรูเพียงหนึ่งเดียว สร้างความเสียหายเวทมนตร์ 100% + $(skillLevel*4*24)$ และเพิ่มการป้องกันคู่ของตนเองขึ้น 60% คงอยู่เป็นเวลา 2 เทิร์น',
		describe_in = 'Xie Mi menggulung tubuhnya dan mengerahkan seluruh kekuatan untuk menyerang satu target musuh, memberikan 100% Serangan Sihir + $(skillLevel*4*24)$ kerusakan sihir, meningkatkan pertahanan ganda sebesar 60%, bertahan selama 2 giliran.',
		describe_ph = 'Si Xie Mi ay yumuyuko sa kanyang katawan at inilalabas ang lahat ng lakas upang atakihin ang iisang target ng kaaway, na nagdudulot ng 100% Magic Attack + $(skillLevel*4*24)$ na magic damage, pinapataas ang kanyang double defense ng 60%, tumatagal ng 2 turns.',
		describe_ma = 'Xie Mi menggulung badannya dan menumpukan seluruh kekuatannya untuk menyerang sasaran musuh tunggal, memberikan 100% Serangan Sihir + $(skillLevel*4*24)$ kerosakan sihir, meningkatkan pertahanan berganda sebanyak 60%, bertahan selama 2 giliran.',
		describe = 'Xie Mi curls up his body and focuses all his strength to charge at a single enemy target, dealing 100% Magic Attack + $(skillLevel*4*24)$ magic damage, increases his dual defense by 60%, lasting for 2 turns.',
		simDesc_vn = 'Xie Mi cuộn mình lại, dồn toàn lực lao vào mục tiêu đơn lẻ của đối phương, gây sát thương ma pháp và tăng cường phòng thủ vật lý của bản thân.',
		simDesc_en = 'Xie Mi curls up, focusing all his strength on a single enemy target, dealing magic damage and boosting his own physical defense.',
		simDesc_th = 'เซียมิขดตัว มุ่งเน้นพลังทั้งหมดไปที่เป้าหมายเดี่ยวของศัตรู สร้างความเสียหายเวทมนตร์และเพิ่มการป้องกันทางกายภาพของตัวเอง',
		simDesc_in = 'Xie Mi menggulung tubuhnya, mengerahkan seluruh kekuatannya pada satu target musuh, memberikan kerusakan sihir dan meningkatkan pertahanan fisiknya sendiri.',
		simDesc_ph = 'Si Xie Mi ay nagkukumpol, inilalagay ang lahat ng lakas niya sa isang kalaban na target, nagdudulot ng magic damage at pinapalakas ang kanyang sariling physical defense.',
		simDesc_ma = 'Xie Mi menggulung badan, menumpukan semua kekuatannya pada sasaran tunggal musuh, menyebabkan kerosakan sihir dan meningkatkan pertahanan fizikalnya sendiri.',
		simDesc = 'Xie Mi curls up, focusing all his strength on a single enemy target, dealing magic damage and boosting his own physical defense.',
		zawakeEffect = __data_t__zawakeEffect[24411],
		-- {79001}
