	[24412] = {
		id = 24412,
		skillName_vn = 'Nguyện ước của thiên nhiên',
		skillName_en = 'Wish of nature',
		skillName_th = 'ความปรารถนาของธรรมชาติ',
		skillName_in = 'Harapan alam',
		skillName_ph = 'Hiling ng kalikasan',
		skillName_ma = 'Harapan alam',
		skillName = 'Wish of nature',
		describe_vn = 'Xie Mi sử dụng sức mạnh tự nhiên tấn công mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#180% Phép Công#C0x5B545B#+$(skillLevel*4*60)$ sát thương#C0xF13B54# pháp thuật#C0x5B545B#, xóa bỏ 2 hiệu ứng tiêu cực của mỗi anh hùng trong hàng của bản thân, và hồi phục máu cho họ (dựa trên 80% Phép Công của Xie Mi)',
		describe_en = 'Xie Mi uses natural power to attack a single enemy target, dealing 180% Magical Attack + $(skillLevel*4*60)$ magic damage, removes 2 negative effects from each hero in their own row, and heals them based on 80% of Xie Mi\'s Magical Attack.',
		describe_th = 'เสี่ยวมี่ใช้พลังธรรมชาติเพื่อโจมตีเป้าหมายเดี่ยวของศัตรู สร้างความเสียหายเวทมนตร์ 180% บวก $(skillLevel*4*60)$ และลบ 2 สถานะลบจากฮีโร่แต่ละตัวในแถวของตนเอง รวมถึงฟื้นฟูเลือดให้พวกเขาตาม 80% ของพลังโจมตีเวทมนตร์ของเสี่ยวมี่',
		describe_in = 'Xie Mi menggunakan kekuatan alam untuk menyerang satu target musuh, memberikan 180% Serangan Magis + $(skillLevel*4*60)$ kerusakan sihir, menghapus 2 efek negatif dari setiap pahlawan di barisnya sendiri, dan menyembuhkan mereka berdasarkan 80% Serangan Magis Xie Mi.',
		describe_ph = 'Gumagamit si Xie Mi ng likas na kapangyarihan upang atakihin ang isang kalabang target, na nagdudulot ng 180% Magical Attack + $(skillLevel*4*60)$ na pinsala sa mahika, tinatanggal ang 2 negatibong epekto mula sa bawat bayani sa kanilang sariling hanay, at nagpapagaling sa kanila base sa 80% ng Magical Attack ni Xie Mi.',
		describe_ma = 'Xie Mi menggunakan kuasa semula jadi untuk menyerang sasaran musuh tunggal, memberikan 180% Serangan Sihir + $(skillLevel*4*60)$ kerosakan sihir, menghapus 2 kesan negatif daripada setiap wira di barisnya sendiri, dan memulihkan kesihatan mereka berdasarkan 80% Serangan Sihir Xie Mi.',
		describe = 'Xie Mi uses natural power to attack a single enemy target, dealing 180% Magical Attack + $(skillLevel*4*60)$ magic damage, removes 2 negative effects from each hero in their own row, and heals them based on 80% of Xie Mi\'s Magical Attack.',
		simDesc_vn = 'Xie Mi sử dụng sức mạnh tự nhiên tấn công mục tiêu đơn lẻ của đối phương, gây sát thương ma pháp, giải tán các hiệu ứng tiêu cực ở hàng của mình và hồi phục sinh lực.',
		simDesc_en = 'Xie Mi uses natural power to attack a single enemy target, dealing magical damage, dispelling negative effects on their own row, and restoring health.',
		simDesc_th = 'เซียมี่ใช้พลังธรรมชาติเพื่อโจมตีเป้าหมายเดี่ยวของศัตรู สร้างความเสียหายเวทย์มนตร์ ลบล้างสถานะลบในแถวของตนเอง และฟื้นฟูพลังชีวิต',
		simDesc_in = 'Xie Mi menggunakan kekuatan alami untuk menyerang satu target musuh, memberikan kerusakan sihir, menghapus efek negatif di barisnya sendiri, dan memulihkan kesehatan.',
		simDesc_ph = 'Gumagamit si Xie Mi ng natural na kapangyarihan para atakehin ang isang kalaban, nagdudulot ng magic na pinsala, nag-aalis ng mga negatibong epekto sa sariling linya, at nagpapagaling ng buhay.',
		simDesc_ma = 'Xie Mi menggunakan kuasa semula jadi untuk menyerang sasaran tunggal musuh, memberikan kerosakan magik, membuang kesan negatif di barisan sendiri dan memulihkan kesihatan.',
		simDesc = 'Xie Mi uses natural power to attack a single enemy target, dealing magical damage, dispelling negative effects on their own row, and restoring health.',
		zawakeEffect = __data_t__zawakeEffect[24412],
		-- {79002}
		zawakeEffectDesc = 'Xie Mi uses natural power to attack a single enemy target, dealing #C0x3D8A99#180% Magic Power#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B#, removing 3 negative effects from each hero in his row and restoring health (based on 100% of Xie Mi\'s Magic Power)',
		zawakeEffectDesc_en = 'Xie Mi uses natural power to attack a single enemy target, dealing #C0x3D8A99#180% Magic Power#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B#, removing 3 negative effects from each hero in his row and restoring health (based on 100% of Xie Mi\'s Magic Power)',
		zawakeEffectDesc_th = 'เซียะ หมี่ ใช้พลังธรรมชาติเพื่อโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายเวท #C0x3D8A99#180% พลังเวท#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# ความเสียหายเวท#C0x5B545B# ลบ 3 ผลกระทบด้านลบจากฮีโร่แต่ละตัวในแถวของเขา และฟื้นฟูเลือด (อิงจาก 100% พลังเวทของเซียะ หมี่)',
		zawakeEffectDesc_in = 'Xie Mi menggunakan kekuatan alami untuk menyerang satu target musuh, memberikan #C0x3D8A99#180% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# kerusakan sihir#C0x5B545B#, menghapus 3 efek negatif dari setiap pahlawan di barisnya dan memulihkan darah (berdasarkan 100% Kekuatan Sihir Xie Mi)',
		zawakeEffectDesc_ph = 'Gumagamit si Xie Mi ng natural na lakas para atakihin ang isang target na kalaban, na nagdudulot ng #C0x3D8A99#180% Magic Power#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B#, nagtatanggal ng 3 negatibong epekto mula sa bawat bayani sa kanyang hanay at nagpapagaling ng health (batay sa 100% Magic Power ni Xie Mi)',
		zawakeEffectDesc_ma = 'Xie Mi menggunakan kekuatan semula jadi untuk menyerang sasaran musuh tunggal, memberikan #C0x3D8A99#180% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# kerosakan sihir#C0x5B545B#, menghapus 3 kesan negatif dari setiap wira di barisnya dan memulihkan kesihatan (berdasarkan 100% Kuasa Sihir Xie Mi)',
		zawakeEffectDesc_vn = 'Xie Mi sử dụng sức mạnh tự nhiên để tấn công mục tiêu đơn lẻ của kẻ địch, gây sát thương phép #C0x3D8A99#180% Công Phép#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# sát thương phép#C0x5B545B#, xóa 3 hiệu ứng tiêu cực cho mỗi anh hùng trong hàng của mình và hồi phục máu (dựa trên 100% Công Phép của Xie Mi)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Remove 2 debuffs from each ally in your row and heal them (based on 80% of Shaymin’s Magic Attack)→Remove 3 debuffs from each ally in your row and heal them (based on 100% of Shaymin’s Magic Attack)',
		zawakeSimpleDesc_en = 'Remove 2 debuffs from each ally in your row and heal them (based on 80% of Shaymin’s Magic Attack)→Remove 3 debuffs from each ally in your row and heal them (based on 100% of Shaymin’s Magic Attack)',
		zawakeSimpleDesc_th = 'ลบดีบัฟ 2 อย่างจากฮีโร่แต่ละตัวในแถวของคุณและฟื้นฟู HP ให้พวกเขา (อิงจาก 80% พลังเวทของ Shaymin)→ลบดีบัฟ 3 อย่างจากฮีโร่แต่ละตัวในแถวของคุณและฟื้นฟู HP ให้พวกเขา (อิงจาก 100% พลังเวทของ Shaymin)',
		zawakeSimpleDesc_in = 'Menghapus 2 efek negatif dari setiap hero di baris kamu dan memulihkan HP mereka (berdasarkan 80% Magic Attack dari Shaymin)→Menghapus 3 efek negatif dari setiap hero di baris kamu dan memulihkan HP mereka (berdasarkan 100% Magic Attack dari Shaymin)',
		zawakeSimpleDesc_ph = 'Tanggalin ang 2 debuffs mula sa bawat hero sa sariling hanay at i-heal sila (base sa 80% ng Magic Attack ni Shaymin)→Tanggalin ang 3 debuffs mula sa bawat hero sa sariling hanay at i-heal sila (base sa 100% ng Magic Attack ni Shaymin)',
		zawakeSimpleDesc_ma = 'Singkirkan 2 kesan negatif daripada setiap hero dalam barisan anda dan pulihkan HP mereka (berdasarkan 80% Serangan Magik Shaymin)→Singkirkan 3 kesan negatif daripada setiap hero dalam barisan anda dan pulihkan HP mereka (berdasarkan 100% Serangan Magik Shaymin)',
		zawakeSimpleDesc_vn = 'Xóa 2 hiệu ứng tiêu cực của mỗi anh hùng trong hàng của bản thân và hồi máu cho họ (dựa trên 80% Công Phép của Shaymin)→Xóa 3 hiệu ứng tiêu cực của mỗi anh hùng trong hàng của bản thân và hồi máu cho họ (dựa trên 100% Công Phép của Shaymin)',
