	[24413] = {
		id = 24413,
		skillName_vn = 'Điệu nhảy hương thơm',
		skillName_en = 'Fragrant Dance',
		skillName_th = 'การเต้นรำกลิ่นหอม',
		skillName_in = 'Tarian Harum',
		skillName_ph = 'Amoy na Sayaw',
		skillName_ma = 'Tarian Harum',
		skillName = 'Fragrant Dance',
		describe_vn = 'Xie Mi vui vẻ chơi đùa trên bãi cỏ, sau đó lao về phía một mục tiêu địch, gây ra #C0x3D8A99#500% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#sát thương ma thuật#C0x5B54 5B# và giải phóng [#L10#Chuỗi chữa lành#L0#] Hiệu ứng: Hồi máu cho đơn vị có phần trăm HP thấp nhất (hồi máu) số lượng bằng 300% Sát Thương Phép Thuật của Shemi). Chuỗi hồi máu sẽ đẩy ra tổng cộng 4 mục tiêu. Hiệu quả hồi máu sau mỗi lần phóng ra là 70% so với mục tiêu trước đó\n#F20# \n#F40#Động tác đặc biệt đầu tiên là thêm dấu [#L10#心之之心#L0#] vào hai đơn vị có lượng máu thấp nhất. Dấu hiệu [#L10#心之之心#L0#]: Khi nhận sát thương chí mạng, 50% lượng máu từ Sát Thương Phép Thuật của Shemi sẽ được giữ lại để tồn tại và nó có thể xua tan các hiệu ứng tiêu cực và khống chế. Dấu sẽ biến mất ngay lập tức sau khi được kích hoạt ([#L10# land form #L0#] chỉ có thể thêm một dấu vào toàn bộ trường)',
		describe_en = 'Xie Mi happily plays on the grass, then rushes toward an enemy target, dealing #C0x3D8A99#500% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# magical damage#C0x5B545B# and unleashing [#L10#Healing Chain#L0#] Effect: Heals the unit with the lowest HP percentage (healing amount equal to 300% of Shemi\'s Magical Damage). The healing chain will bounce up to 4 targets in total. Each subsequent heal is 70% as effective as the previous target \n#F20# \n#F40# The first special move additionally applies [#L10#Heart of Hearts#L0#] to the two units with the lowest health. The [#L10#Heart of Hearts#L0#] mark: Upon taking a critical hit, 50% of Shemi\'s Magical Damage is retained as HP to survive, and it can dispel negative effects and controls. The mark disappears immediately after activation ([#L10# land form #L0#] can only apply one mark on the entire field).',
		describe_th = 'เซี่ย มิ เล่นอย่างสนุกสนานบนสนามหญ้า จากนั้นพุ่งเข้าหาศัตรูเป้าหมาย สร้างความเสียหายเวทมนตร์ #C0x3D8A99#500%#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# และปลดปล่อย [#L10#โซ่รักษา#L0#] ผล: ฟื้นฟูหน่วยที่มีเปอร์เซ็นต์ HP ต่ำที่สุด (ปริมาณฟื้นฟูเท่ากับ 300% ของความเสียหายเวทมนตร์ของเซี่ยมิ) โซ่รักษานี้จะดีดกลับไปยังเป้าหมายสูงสุด 4 ตัว ผลการฟื้นฟูหลังจากแต่ละครั้งที่ส่งออกคือ 70% เทียบกับเป้าหมายก่อนหน้า \n#F20# \n#F40# การโจมตีพิเศษครั้งแรกจะเพิ่มเครื่องหมาย [#L10#หัวใจแห่งหัวใจ#L0#] ให้กับสองหน่วยที่มีเลือดต่ำที่สุด เครื่องหมาย [#L10#หัวใจแห่งหัวใจ#L0#]: เมื่อได้รับความเสียหายคริติคอล จะเก็บรักษา HP 50% ของความเสียหายเวทมนตร์ของเซี่ยมิไว้เพื่อเอาชีวิตรอด และสามารถขจัดสถานะลบและการควบคุม เครื่องหมายจะหายไปทันทีหลังจากถูกกระตุ้น ([#L10# land form #L0#] สามารถเพิ่มเครื่องหมายได้แค่หนึ่งครั้งในสนามทั้งหมด)',
		describe_in = 'Xie Mi dengan senang bermain di rumput, kemudian melompat menuju target musuh, menyebabkan #C0x3D8A99#500% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# kerusakan magis#C0x5B545B# dan melepaskan [#L10#Rantai Penyembuhan#L0#] Efek: Menyembuhkan unit dengan persentase HP terendah (jumlah penyembuhan sama dengan 300% Kerusakan Magis Shemi). Rantai penyembuhan akan memantul ke total 4 target. Efektivitas penyembuhan setiap kali terpancar adalah 70% dari target sebelumnya \n#F20# \n#F40# Gerakan khusus pertama menambahkan tanda [#L10#Hati dari Hati#L0#] pada dua unit dengan HP terendah. Tanda [#L10#Hati dari Hati#L0#]: Saat menerima serangan kritis, 50% dari Kerusakan Magis Shemi akan disimpan sebagai HP untuk bertahan hidup dan dapat menghilangkan efek negatif serta kontrol. Tanda akan hilang segera setelah diaktifkan ([#L10# land form #L0#] hanya dapat menambahkan satu tanda di seluruh medan).',
		describe_ph = 'Masayang naglalaro si Xie Mi sa damuhan, pagkatapos ay tumakbo patungo sa isang kaaway, nagdudulot ng #C0x3D8A99#500% Pinagaling na Pinsala ng Mahika#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# pinsala ng mahika#C0x5B545B# at nagpapakawala ng [#L10#Kadena ng Pagpapagaling#L0#] Epekto: Nagpapagaling sa yunit na may pinakamababang porsyento ng HP (ang dami ng pagpapagaling ay katumbas ng 300% ng Pinsalang Mahika ni Shemi). Ang pagpapagaling na kadena ay tatalbog sa kabuuang 4 na target. Ang bisa ng pagpapagaling pagkatapos ng bawat pagpapakalat ay 70% kumpara sa naunang target \n#F20# \n#F40# Ang unang espesyal na galaw ay nagdaragdag ng marka ng [#L10#Puso ng Puso#L0#] sa dalawang yunit na may pinakamababang HP. Ang marka ng [#L10#Puso ng Puso#L0#]: Kapag tumanggap ng kritikal na pinsala, 50% ng Pinsalang Mahika ni Shemi ay itatabi bilang HP upang mabuhay at maaari nitong tanggalin ang mga negatibong epekto at kontrol. Ang marka ay mawawala agad pagkatapos ma-activate ([#L10# land form #L0#] ay maaari lamang magdagdag ng isang marka sa buong larangan).',
		describe_ma = 'Xie Mi bermain dengan gembira di atas rumput, kemudian meluru ke arah sasaran musuh, menyebabkan #C0x3D8A99#500% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# kerosakan magik#C0x5B545B# dan melepaskan [#L10#Rantai Penyembuhan#L0#] Kesan: Menyembuhkan unit dengan peratusan HP terendah (jumlah penyembuhan bersamaan dengan 300% Kerosakan Magik Shemi). Rantai penyembuhan akan melantun ke jumlah 4 sasaran keseluruhan. Keberkesanan penyembuhan selepas setiap pancaran adalah 70% berbanding sasaran sebelumnya \n#F20# \n#F40# Gerakan khas pertama menambah tanda [#L10#Hati dari Hati#L0#] pada dua unit dengan darah terendah. Tanda [#L10#Hati dari Hati#L0#]: Apabila menerima kerosakan kritikal, 50% daripada Kerosakan Magik Shemi akan disimpan sebagai HP untuk bertahan dan ia boleh menangkis kesan negatif serta kawalan. Tanda itu akan hilang serta-merta selepas diaktifkan ([#L10# land form #L0#] hanya boleh menambah satu tanda di seluruh medan).',
		describe = 'Xie Mi happily plays on the grass, then rushes toward an enemy target, dealing #C0x3D8A99#500% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# magical damage#C0x5B545B# and unleashing [#L10#Healing Chain#L0#] Effect: Heals the unit with the lowest HP percentage (healing amount equal to 300% of Shemi\'s Magical Damage). The healing chain will bounce up to 4 targets in total. Each subsequent heal is 70% as effective as the previous target \n#F20# \n#F40# The first special move additionally applies [#L10#Heart of Hearts#L0#] to the two units with the lowest health. The [#L10#Heart of Hearts#L0#] mark: Upon taking a critical hit, 50% of Shemi\'s Magical Damage is retained as HP to survive, and it can dispel negative effects and controls. The mark disappears immediately after activation ([#L10# land form #L0#] can only apply one mark on the entire field).',
		simDesc_vn = 'Xie Mi vui vẻ chơi đùa trong bụi cỏ, sau đó lao vào mục tiêu đơn lẻ của đối phương gây sát thương ma pháp, và giải phóng hiệu ứng Chuỗi Chữa Lành: lần đầu tiên sử dụng chiêu thức đặc biệt sẽ thêm Dấu Ấn Lòng Biết Ơn cho các đơn vị đồng minh.',
		simDesc_en = 'Xie Mi happily plays in the grass, then charges at a single enemy target, dealing magical damage and triggering the Healing Chain effect: the first time a special skill is used, it adds the Mark of Gratitude to allied units.',
		simDesc_th = 'เซียมีเล่นอย่างมีความสุขในพุ่มหญ้า จากนั้นพุ่งเข้าโจมตีเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหายเวทมนตร์ และปลดปล่อยเอฟเฟกต์โซ่การรักษา: ครั้งแรกที่ใช้ทักษะพิเศษจะเพิ่มเครื่องหมายแห่งความกตัญญูให้กับมิตรสหายทั้งหมด',
		simDesc_in = 'Xie Mi dengan riang bermain di rumput, kemudian menyerang satu target musuh, memberikan kerusakan sihir, dan memicu efek Rantai Penyembuhan: penggunaan pertama kali dari skill khusus akan menambahkan Tanda Rasa Terima Kasih pada unit sekutu.',
		simDesc_ph = 'Si Xie Mi ay masayang naglalaro sa damuhan, pagkatapos ay tumatakbo sa isang solong target na kalaban, nagdudulot ng magic damage, at nagpapalabas ng Healing Chain effect: sa unang paggamit ng espesyal na kakayahan, magdadagdag ito ng Mark of Gratitude sa mga kaalyadong yunit.',
		simDesc_ma = 'Xie Mi dengan gembira bermain di rumput, kemudian menyerang satu sasaran musuh, menyebabkan kerosakan magik, dan melepaskan kesan Rantaian Penyembuhan: kali pertama menggunakan kemahiran istimewa akan menambah Tanda Kesyukuran pada unit sekutu.',
		simDesc = 'Xie Mi happily plays in the grass, then charges at a single enemy target, dealing magical damage and triggering the Healing Chain effect: the first time a special skill is used, it adds the Mark of Gratitude to allied units.',
		starEffect = __data_t__starEffect[24413],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Chuỗi Chữa Trị có lượng chữa trị ban đầu được nâng lên 400% sức mạnh pháp thuật; số lượng đơn vị bị ảnh hưởng bởi <#L10#Tâm của Lòng Biết Ơn#L0#> tăng thêm 1.',
		starEffectDesc = 'Additional Effect: The Healing Chain\'s initial healing amount is increased by 400% of magic power; the number of units affected by <#L10#Heart of Gratitude#L0#> is increased by 1.',
		starEffectDesc_en = 'Additional Effect: The Healing Chain\'s initial healing amount is increased by 400% of magic power; the number of units affected by <#L10#Heart of Gratitude#L0#> is increased by 1.',
		starEffectDesc_th = 'ผลเพิ่มเติม: โซ่การรักษามีปริมาณการรักษาเริ่มต้นเพิ่มขึ้น 400% ของพลังเวท; จำนวนหน่วยที่ได้รับผลกระทบจาก <#L10#ใจแห่งความกตัญญู#L0#> เพิ่มขึ้น 1 หน่วย',
		starEffectDesc_in = 'Efek Tambahan: Jumlah penyembuhan awal Rantai Penyembuhan ditingkatkan sebesar 400% dari kekuatan sihir; jumlah unit yang terpengaruh oleh <#L10#Hati Syukur#L0#> bertambah 1.',
		starEffectDesc_ph = 'Karagdagang Epekto: Ang paunang dami ng pagpapagaling ng Healing Chain ay pinalaki ng 400% ng magic power; ang bilang ng mga yunit na apektado ng <#L10#Puso ng Pasasalamat#L0#> ay nadagdagan ng 1.',
		starEffectDesc_ma = 'Kesan Tambahan: Jumlah penyembuhan awal Rantaian Penyembuhan ditingkatkan sebanyak 400% kuasa sihir; bilangan unit yang terjejas oleh <#L10#Hati Kesyukuran#L0#> bertambah 1.',
		zawakeEffect = __data_t__zawakeEffect[24413],
		-- {79003}
		zawakeEffectDesc = 'Xie Mi happily plays on the grass, then dashes toward an enemy target, dealing #C0x3D8A99#500% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#magic damage#C0x5B545B# and unleashing <#L10# Healing Chain #L0#> Effect: Heals the unit with the lowest HP (healing amount is a percentage) equal to 300% of Shemi\'s Magical Damage). The healing chain will bounce to a total of 4 targets. Healing effectiveness after each bounce is 70% compared to the previous target, and units in the <Healing Chain> will gain double defense increase of 120%, lasting 2 seconds #F20# Special first move adds the <#L10#心之之心#L0#> mark to the two units with the lowest HP. <#L10#心之之心#L0#> Mark: When receiving critical damage, the mark from Xie Mi will be retained. 50% HP of Magical Damage remains and removes negative and control effects. HP retained by Ninja, Wind, and Earth types is doubled. The mark disappears immediately after activation (<#L10#LAND FORM#L0#> can only add one mark to the entire field).',
		zawakeEffectDesc_en = 'Xie Mi happily plays on the grass, then dashes toward an enemy target, dealing #C0x3D8A99#500% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#magic damage#C0x5B545B# and unleashing <#L10# Healing Chain #L0#> Effect: Heals the unit with the lowest HP (healing amount is a percentage) equal to 300% of Shemi\'s Magical Damage). The healing chain will bounce to a total of 4 targets. Healing effectiveness after each bounce is 70% compared to the previous target, and units in the <Healing Chain> will gain double defense increase of 120%, lasting 2 seconds #F20# Special first move adds the <#L10#心之之心#L0#> mark to the two units with the lowest HP. <#L10#心之之心#L0#> Mark: When receiving critical damage, the mark from Xie Mi will be retained. 50% HP of Magical Damage remains and removes negative and control effects. HP retained by Ninja, Wind, and Earth types is doubled. The mark disappears immediately after activation (<#L10#LAND FORM#L0#> can only add one mark to the entire field).',
		zawakeEffectDesc_th = 'เซมีเล่นอย่างมีความสุขบนหญ้า จากนั้นพุ่งไปยังเป้าหมายศัตรู ก่อให้เกิด #C0x3D8A99#500% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# และปลดปล่อย <#L10# Healing Chain #L0#> ผลลัพธ์: ฟื้นฟูหน่วยที่มี HP ต่ำที่สุด (ปริมาณการฟื้นฟูเป็นเปอร์เซ็นต์) เท่ากับ 300% ของความเสียหายเวทมนตร์ของ Shemi) โซ่การฟื้นฟูจะเด้งไปยังเป้าหมายทั้งหมด 4 ตัว ประสิทธิภาพการฟื้นฟูหลังจากแต่ละครั้งลดลง 70% เมื่อเทียบกับเป้าหมายก่อนหน้า และหน่วยใน <โซ่การฟื้นฟู> จะได้รับการเพิ่มเกราะแบบทวีคูณ 120% เป็นเวลา 2 วินาที #F20# การเคลื่อนไหวพิเศษครั้งแรกจะเพิ่มเครื่องหมาย <#L10#心之之心#L0#> ให้กับสองหน่วยที่มี HP ต่ำที่สุด เครื่องหมาย <#L10#心之之心#L0#>: เมื่อได้รับความเสียหายวิกฤต เครื่องหมายจาก เซมี จะถูกเก็บไว้ HP 50% ของความเสียหายเวทมนตร์จะยังคงอยู่และลบล้างผลลบและควบคุม HP ที่หน่วยนินจา ลม และดินได้รับจะเพิ่มขึ้นเป็นสองเท่า เครื่องหมายจะหายไปทันทีหลังจากเปิดใช้งาน (<#L10#LAND FORM#L0#> สามารถเพิ่มเครื่องหมายได้เพียงหนึ่งเครื่องหมายในสนามทั้งหมด)',
		zawakeEffectDesc_in = 'Xie Mi dengan gembira bermain di atas rumput, lalu menerjang menuju target musuh, menyebabkan #C0x3D8A99#500% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#kerusakan magis#C0x5B545B# dan membebaskan <#L10# Healing Chain #L0#> Efek: Menyembuhkan unit dengan HP terendah (jumlah penyembuhan adalah persentase) sebesar 300% Kerusakan Magis Shemi). Rantai penyembuhan akan memantul ke total 4 target. Efektivitas penyembuhan setelah setiap pantulan adalah 70% dibandingkan target sebelumnya, dan unit dalam <Rantai Penyembuhan> akan mendapatkan peningkatan pertahanan ganda sebesar 120%, bertahan selama 2 detik #F20# Gerakan khusus pertama menambahkan tanda <#L10#心之之心#L0#> pada dua unit dengan HP terendah. Tanda <#L10#心之之心#L0#>: Saat menerima kerusakan kritis, tanda dari Xie Mi akan tetap ada. 50% HP dari Kerusakan Magis tetap ada dan menghilangkan efek negatif dan kontrol. HP yang dipertahankan oleh Ninja, Angin, dan Tanah menjadi dua kali lipat. Tanda akan hilang segera setelah diaktifkan (<#L10#LAND FORM#L0#> hanya dapat menambahkan satu tanda ke seluruh medan).',
		zawakeEffectDesc_ph = 'Masayang naglalaro si Xie Mi sa damuhan, pagkatapos ay nagtutungo sa isang kalaban, nagdudulot ng #C0x3D8A99#500% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#magical damage#C0x5B545B# at naglalabas ng <#L10# Healing Chain #L0#> Epekto: Nagpapagaling sa yunit na may pinakamababang HP (ang dami ng paggaling ay porsyento) ng 300% ng Magical Damage ni Shemi). Ang healing chain ay lalaktaw sa kabuuang 4 na target. Ang bisa ng paggaling pagkatapos ng bawat laktaw ay 70% kumpara sa naunang target, at ang mga yunit sa <Healing Chain> ay nakakakuha ng dobleng pagtaas ng depensa na 120%, tumatagal ng 2 segundo #F20# Ang unang espesyal na galaw ay nagdaragdag ng <#L10#心之之心#L0#> marka sa dalawang yunit na may pinakamababang HP. <#L10#心之之心#L0#> Marka: Kapag tumatanggap ng kritikal na pinsala, mananatili ang marka mula kay Xie Mi. 50% HP ng Magical Damage ay mananatili at tinatanggal ang mga negatibo at kontrol na epekto. Ang HP na nananatili sa Ninja, Wind, at Earth ay dumoble. Ang marka ay mawawala kaagad pagkatapos ma-activate (<#L10#LAND FORM#L0#> ay maaari lamang magdagdag ng isang marka sa buong larangan).',
		zawakeEffectDesc_ma = 'Xie Mi dengan gembira bermain di atas rumput, kemudian berlari ke arah sasaran musuh, menyebabkan #C0x3D8A99#500% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#kerosakan magik#C0x5B545B# dan membebaskan <#L10# Healing Chain #L0#> Kesan: Memulihkan unit dengan HP terendah (jumlah pemulihan adalah peratusan) sebanyak 300% Kerosakan Magik Shemi). Rantai pemulihan akan memantul kepada 4 sasaran jumlahnya. Keberkesanan pemulihan selepas setiap pantulan adalah 70% berbanding sasaran sebelumnya dan unit dalam <Rantai Penyembuhan> akan mendapat peningkatan pertahanan berganda sebanyak 120%, bertahan selama 2 saat #F20# Gerakan istimewa pertama menambah tanda <#L10#心之之心#L0#> pada dua unit dengan HP terendah. Tanda <#L10#心之之心#L0#>: Apabila menerima kerosakan kritikal, tanda dari Xie Mi akan kekal. 50% HP daripada Kerosakan Magik kekal dan menghilangkan kesan negatif dan kawalan. HP yang dikekalkan oleh Ninja, Angin, dan Tanah menjadi dua kali ganda. Tanda akan hilang dengan serta-merta selepas diaktifkan (<#L10#LAND FORM#L0#> hanya boleh menambah satu tanda ke seluruh medan).',
		zawakeEffectDesc_vn = 'Xie Mi vui vẻ chơi đùa trên bãi cỏ, sau đó lao về phía một mục tiêu địch, gây ra #C0x3D8A99#500% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#sát thương ma thuật#C0x5B545B# và giải phóng <#L10# Healing Chain #L0#> Hiệu ứng: Hồi máu cho đơn vị có HP thấp nhất (lượng hồi máu là phần trăm) 300% Sát Thương Phép Thuật của Shemi). Chuỗi hồi máu sẽ đẩy ra tổng cộng 4 mục tiêu. Hiệu quả hồi máu sau mỗi lần phóng ra là 70% so với mục tiêu trước đó và đơn vị trong <Chuỗi chữa bệnh> sẽ tăng khả năng phòng thủ kép lên 120%, tồn tại trong 2 hiệp\n#F20# \n#F40#Động tác đặc biệt đầu tiên là thêm dấu <#L10#心之之心#L0#> cho hai đơn vị có HP thấp nhất. <#L10#心之之心#L0#> dấu ấn: Khi nhận sát thương chí mạng, dấu ấn từ Xie Mi sẽ được giữ lại. 50% HP của Sát Thương Phép Thuật sẽ tồn tại và loại bỏ các hiệu ứng tiêu cực và khống chế. HP mà các loại Ninja, Gió và Đất giữ lại được tăng gấp đôi. Dấu sẽ biến mất ngay lập tức sau khi được kích hoạt (<#L10#LAND FORM#L0#> chỉ có thể thêm một dấu vào toàn bộ trường)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Increase double defense by an additional 120% for units in the healing chain for 2 turns; <Grateful Soul> Mark: When activated with Ninja, Wind, or Earth types, retained HP is doubled',
		zawakeSimpleDesc_en = 'Increase double defense by an additional 120% for units in the healing chain for 2 turns; <Grateful Soul> Mark: When activated with Ninja, Wind, or Earth types, retained HP is doubled',
		zawakeSimpleDesc_th = 'เพิ่มพลังป้องกันคู่ 120% ให้ยูนิตในสายการฟื้นฟูเป็นเวลา 2 เทิร์น; <จิตวิญญาณแห่งความกตัญญู>: เมื่อติดตั้งกับสาย นินจา, ลม, ดิน ปริมาณ HP ที่รักษาจะคูณสอง',
		zawakeSimpleDesc_in = 'Tambahan 120% pertahanan ganda untuk unit dalam rantai penyembuhan selama 2 ronde; Tanda <Jiwa Bersyukur>: Saat diaktifkan bersama tipe Ninja, Angin, atau Tanah, HP yang tersisa akan digandakan',
