	[24416] = {
		id = 24416,
		skillName_vn = 'Hạt giống bó hoa',
		skillName_en = 'Seed bouquet',
		skillName_th = 'ช่อเมล็ดพันธุ์',
		skillName_in = 'Buket biji',
		skillName_ph = 'Bukol ng buto',
		skillName_ma = 'Jambakan biji',
		skillName = 'Seed bouquet',
		describe_vn = 'Trong trận chiến, nhập [#L10#Land Form#L0#] cho vòng 1-3 và chuyển sang [#L10#Sky Form#L0#] cho vòng 4-6 (chu kỳ này)\n#F20# \n#F40#[#L10#Land Form#L0#] có thể tạo [#L10#Barrier#L0#] để chống lại 3 sát thương đường thẳng đầu tiên mà toàn đội nhận được trong vòng lớn (hàng trước) đơn vị chống lại #C0x5c9970#$(10+skillL evel*0.1-0.1)$%#C0x5B545B#, đơn vị phía sau chống lại #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#)\n#F20# \n#F40# Mỗi lần [#L10#LAND FORM#L0#] xuất hiện, đặt [#L10#bouquetseed#L0#] trước tất cả các trại của bạn trong 2 vòng lớn: ba đồng đội có HP thấp nhất có thể phục hồi một lượng HP nhất định (60% Sát Thương Phép Thuật của Shemi) trước khi hành động trong vòng\n#F20# \n#F40#[#L10#bouquetseed#L0#] biến mất, Xie Mi hồi phục 500 điểm thịnh nộ và có một Có 40% cơ hội trói tất cả tướng địch trong 1 lượt.',
		describe_en = 'In battle, enter [#L10#Land Form#L0#] for rounds 1-3 and switch to [#L10#Sky Form#L0#] for rounds 4-6 (this cycle) \n#F20# \n#F40# [#L10#Land Form#L0#] can create a [#L10#Barrier#L0#] to block the first 3 straight-line damages received by the entire team in a big round (front row): front unit resists #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#, rear unit resists #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#) \n#F20# \n#F40# Each time [#L10#LAND FORM#L0#] appears, place [#L10#bouquetseed#L0#] before all your camps for 2 big rounds: the three teammates with the lowest HP can recover a certain amount of HP (60% of Shemi\'s Magic Damage) before acting in the round \n#F20# \n#F40# [#L10#bouquetseed#L0#] disappears, Xie Mi recovers 500 rage points and has a 40% chance to bind all enemy generals for 1 turn.',
		describe_th = 'ในศึกต่อสู้ ให้เข้าสู่ [#L10#Land Form#L0#] สำหรับรอบที่ 1-3 และเปลี่ยนเป็น [#L10#Sky Form#L0#] สำหรับรอบที่ 4-6 (วงรอบนี้) \n#F20# \n#F40# [#L10#Land Form#L0#] สามารถสร้าง [#L10#Barrier#L0#] เพื่อป้องกันความเสียหายเส้นตรง 3 ครั้งแรกที่ทีมได้รับในรอบใหญ่ (แถวหน้า): หน่วยด้านหน้าป้องกัน #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# หน่วยด้านหลังป้องกัน #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#) \n#F20# \n#F40# ทุกครั้งที่ [#L10#LAND FORM#L0#] ปรากฏขึ้น วาง [#L10#bouquetseed#L0#] ไว้ด้านหน้าทุกแคมป์ของคุณเป็นเวลา 2 รอบใหญ่: เพื่อนร่วมทีม 3 คนที่มี HP ต่ำที่สุดสามารถฟื้นฟู HP ได้บางส่วน (60% ของความเสียหายเวทมนตร์ของ Shemi) ก่อนทำการในรอบ \n#F20# \n#F40# [#L10#bouquetseed#L0#] หายไป Xie Mi จะฟื้นฟูพลังโมโห 500 แต้มและมีโอกาส 40% ในการผูกพันทหารศัตรูทั้งหมดเป็นเวลา 1 เทิร์น',
		describe_in = 'Dalam pertempuran, masuk ke [#L10#Land Form#L0#] untuk putaran 1-3 dan pindah ke [#L10#Sky Form#L0#] untuk putaran 4-6 (siklus ini) \n#F20# \n#F40# [#L10#Land Form#L0#] dapat membuat [#L10#Barrier#L0#] untuk menahan 3 kerusakan garis lurus pertama yang diterima oleh seluruh tim dalam putaran besar (barisan depan): unit depan menahan #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#, unit belakang menahan #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#) \n#F20# \n#F40# Setiap kali [#L10#LAND FORM#L0#] muncul, tempatkan [#L10#bouquetseed#L0#] di depan semua kamp Anda selama 2 putaran besar: tiga rekan setim dengan HP terendah dapat memulihkan sejumlah HP tertentu (60% Kerusakan Sihir Shemi) sebelum bertindak dalam putaran \n#F20# \n#F40# [#L10#bouquetseed#L0#] hilang, Xie Mi memulihkan 500 poin amarah dan memiliki peluang 40% untuk mengikat semua jenderal musuh selama 1 giliran.',
		describe_ph = 'Sa panahon ng laban, pumasok sa [#L10#Land Form#L0#] para sa rounds 1-3 at lumipat sa [#L10#Sky Form#L0#] para sa rounds 4-6 (itong siklo) \n#F20# \n#F40# Ang [#L10#Land Form#L0#] ay maaaring lumikha ng [#L10#Barrier#L0#] upang harangin ang unang 3 direktang pinsalang natanggap ng buong koponan sa malaking round (front row): ang harapang yunit ay tumatagal ng #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#, ang likurang yunit ay tumatagal ng #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#) \n#F20# \n#F40# Sa bawat paglitaw ng [#L10#LAND FORM#L0#], ilagay ang [#L10#bouquetseed#L0#] sa harapan ng lahat ng iyong mga kampo para sa 2 malaking rounds: ang tatlong kasamahan na may pinakamababang HP ay maaaring magpagaling ng isang tiyak na halaga ng HP (60% ng Magic Damage ni Shemi) bago kumilos sa round \n#F20# \n#F40# Nawala ang [#L10#bouquetseed#L0#], bumalik ang 500 rage points kay Xie Mi at may 40% tsansa na itali ang lahat ng kalaban na heneral sa loob ng 1 turn.',
		describe_ma = 'Dalam pertempuran, masuki [#L10#Land Form#L0#] untuk pusingan 1-3 dan beralih ke [#L10#Sky Form#L0#] untuk pusingan 4-6 (kitaran ini) \n#F20# \n#F40# [#L10#Land Form#L0#] boleh mencipta [#L10#Barrier#L0#] untuk melawan 3 kerosakan garis lurus pertama yang diterima oleh seluruh pasukan dalam pusingan besar (barisan hadapan): unit hadapan melawan #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#, unit belakang melawan #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#) \n#F20# \n#F40# Setiap kali [#L10#LAND FORM#L0#] muncul, letakkan [#L10#bouquetseed#L0#] di hadapan semua kem anda selama 2 pusingan besar: tiga rakan sepasukan dengan HP terendah boleh memulihkan sejumlah HP tertentu (60% Kerosakan Sihir Shemi) sebelum bertindak dalam pusingan \n#F20# \n#F40# [#L10#bouquetseed#L0#] hilang, Xie Mi memulihkan 500 mata kemarahan dan mempunyai peluang 40% untuk mengikat semua jeneral musuh selama 1 pusingan.',
		describe = 'In battle, enter [#L10#Land Form#L0#] for rounds 1-3 and switch to [#L10#Sky Form#L0#] for rounds 4-6 (this cycle) \n#F20# \n#F40# [#L10#Land Form#L0#] can create a [#L10#Barrier#L0#] to block the first 3 straight-line damages received by the entire team in a big round (front row): front unit resists #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#, rear unit resists #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#) \n#F20# \n#F40# Each time [#L10#LAND FORM#L0#] appears, place [#L10#bouquetseed#L0#] before all your camps for 2 big rounds: the three teammates with the lowest HP can recover a certain amount of HP (60% of Shemi\'s Magic Damage) before acting in the round \n#F20# \n#F40# [#L10#bouquetseed#L0#] disappears, Xie Mi recovers 500 rage points and has a 40% chance to bind all enemy generals for 1 turn.',
		starEffect = __data_t__starEffect[24416],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Trong thời gian tồn tại của <Hạt Giống Hoa>, 12% sát thương mà Xemi nhận được sẽ được chuyển đổi thành chữa trị.',
		starEffectDesc = 'Additional effect: During the existence of <Hạt Giống Hoa>, 12% of the damage Xemi receives will be converted into healing.',
		starEffectDesc_en = 'Additional effect: During the existence of <Hạt Giống Hoa>, 12% of the damage Xemi receives will be converted into healing.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ในช่วงเวลาที่ <Hạt Giống Hoa> อยู่ จะมีการเปลี่ยน 12% ของความเสียหายที่ Xemi ได้รับ ให้กลายเป็นการฟื้นฟู',
