		skillName_ph = 'Dahon ng mahika',
		skillName_ma = 'Daun sihir',
		skillName = 'Magic leaf',
		describe_vn = 'Shaymin ném ra lá phép thuật, tấn công mục tiêu đơn phe địch gây #C0x3D8A99#100% Công Phép#C0x5B545B#+$(skillLevel*4*24)$ sát thương phép#C0xF13B54# và tăng 20% Công Phép của bản thân, kéo dài 2 lượt',
		describe_en = 'Shaymin throws a magic leaf, attacking a single enemy target, dealing #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ magic damage#C0xF13B54# and increasing own Magic Power by 20%, lasting 2 turns.',
		describe_th = 'Shaymin โยนใบเวทมนตร์โจมตีเป้าหมายฝ่ายตรงข้ามเดี่ยว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#100% พลังเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# และเพิ่มพลังเวทมนตร์ของตนเอง 20% เป็นเวลา 2 เทิร์น',
		describe_in = 'Shaymin melempar daun sihir, menyerang satu target musuh, memberikan #C0x3D8A99#100% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*24)$ kerusakan sihir#C0xF13B54# dan meningkatkan Kekuatan Sihir sendiri sebesar 20%, berlangsung selama 2 giliran.',
		describe_ph = 'Si Shaymin ay naghagis ng dahong mahiwaga, umatake sa isang target na kalaban, na nagdudulot ng #C0x3D8A99#100% Lakas ng Mahika#C0x5B545B#+$(skillLevel*4*24)$ pinsalang mahiwaga#C0xF13B54# at pinapataas ang sariling Lakas ng Mahika ng 20%, tumatagal ng 2 na turn.',
		describe_ma = 'Shaymin melemparkan daun sihir, menyerang satu sasaran musuh, memberikan #C0x3D8A99#100% Kuasa Magik#C0x5B545B#+$(skillLevel*4*24)$ kerosakan magik#C0xF13B54# dan meningkatkan Kuasa Magik sendiri sebanyak 20%, berlangsung selama 2 pusingan.',
		describe = 'Shaymin throws a magic leaf, attacking a single enemy target, dealing #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ magic damage#C0xF13B54# and increasing own Magic Power by 20%, lasting 2 turns.',
		simDesc_vn = 'Xie Mi ném ra lá có ma pháp, tấn công mục tiêu đơn lẻ của đối phương gây sát thương ma pháp, và tăng cường sức mạnh pháp thuật của bản thân.',
		simDesc_en = 'Xie Mi throws a magic card, attacking a single enemy target to deal magic damage and enhance his own magical power.',
		simDesc_th = 'เซี่ยหมี่โยนไพ่เวทมนตร์โจมตีเป้าหมายเดียวของฝ่ายตรงข้าม ทำดาเมจเวทมนตร์ และเพิ่มพลังเวทของตัวเอง',
		simDesc_in = 'Xie Mi melempar kartu sihir, menyerang satu target musuh yang menyebabkan kerusakan sihir, dan memperkuat kekuatan sihirnya sendiri.',
		simDesc_ph = 'Si Xie Mi ay nagtatapon ng magic card, umaatake sa isang layuning kalaban na nagdudulot ng magic damage, at pinapalakas ang kanyang sariling magical power.',
		simDesc_ma = 'Xie Mi melempar kad sihir, menyerang sasaran musuh tunggal yang memberikan kerosakan sihir, serta meningkatkan kekuatan sihir dirinya sendiri.',
		simDesc = 'Xie Mi throws a magic card, attacking a single enemy target to deal magic damage and enhance his own magical power.',
		zawakeEffect = __data_t__zawakeEffect[24421],
		-- {79001}
		zawakeEffectDesc = 'Shaymin throws magical leaves, attacking a single enemy target causing #C0x3D8A99#100% magical damage#C0x5B545B#+$(skillLevel*4*24)$ magical damage#C0xF13B54#, increases own double attack by 30% for 2 turns',
		zawakeEffectDesc_en = 'Shaymin throws magical leaves, attacking a single enemy target causing #C0x3D8A99#100% magical damage#C0x5B545B#+$(skillLevel*4*24)$ magical damage#C0xF13B54#, increases own double attack by 30% for 2 turns',
		zawakeEffectDesc_th = 'Shaymin ขว้างใบไม้เวทย์มนตร์ โจมตีเป้าหมายศัตรูเดี่ยว ทำ #C0x3D8A99#100% ความเสียหายเวทย์มนตร์#C0x5B545B#+$(skillLevel*4*24)$ ความเสียหายเวทย์มนตร์#C0xF13B54# เพิ่มพลังโจมตีคู่ของตัวเอง 30% เป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Shaymin melempar daun ajaib, menyerang satu target musuh menyebabkan #C0x3D8A99#100% damage magic#C0x5B545B#+$(skillLevel*4*24)$ damage magic#C0xF13B54#, meningkatkan serangan ganda sendiri sebesar 30% selama 2 giliran',
		zawakeEffectDesc_ph = 'Shaymin naghahagis ng mga mahiwagang dahon, umaatake sa isang target na kalaban na nagdudulot ng #C0x3D8A99#100% pinsalang mahika#C0x5B545B#+$(skillLevel*4*24)$ pinsalang mahika#C0xF13B54#, nagdaragdag ng 30% sa sariling dobleng atake sa loob ng 2 turn',
		zawakeEffectDesc_ma = 'Shaymin melempar daun ajaib, menyerang satu sasaran musuh menyebabkan #C0x3D8A99#100% kerosakan sihir#C0x5B545B#+$(skillLevel*4*24)$ kerosakan sihir#C0xF13B54#, meningkatkan serangan berganda sendiri sebanyak 30% selama 2 pusingan',
		zawakeEffectDesc_vn = 'Shaymin ném ra những chiếc lá ma thuật, tấn công mục tiêu đơn lẻ của kẻ địch gây #C0x3D8A99#100% sát thương phép#C0x5B545B#+$(skillLevel*4*24)$ sát thương phép#C0xF13B54#, tăng 30% công đôi của bản thân, kéo dài 2 lượt',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increase own Double Attack by 20% for 2 turns\n#F20# \n#F40##C0x5c9970#→Increase own Double Attack by 30% for 2 turns',
