	[24422] = {
		id = 24422,
		skillName_vn = 'Bão lá bay',
		skillName_en = 'The storm blows the leaves',
		skillName_th = 'พายุพัดใบไม้',
		skillName_in = 'Badai menerbangkan daun',
		skillName_ph = 'Ang bagyo ay nagpapalipad ng mga dahon',
		skillName_ma = 'Badai meniup daun',
		skillName = 'The storm blows the leaves',
		describe_vn = 'Shaymin tạo ra một cơn bão lá bay, tấn công mục tiêu đơn phe địch, gây #C0x3D8A99#180% Công Phép#C0x5B545B#+$(skillLevel*4*60)$ sát thương phép#C0xF13B54#, chuyển đổi 1 hiệu ứng tiêu cực ngẫu nhiên của mỗi anh hùng trong hàng của bản thân thành 1 hiệu ứng tăng cường ngẫu nhiên, đồng thời tăng 10% sát thương cộng thêm và 10% giảm sát thương, kéo dài 2 lượt',
		describe_en = 'Shaymin creates a swirling storm of leaves, attacking a single enemy target, dealing #C0x3D8A99#180% Magic Power#C0x5B545B#+$(skillLevel*4*60)$ magic damage#C0xF13B54#. It converts one random negative effect on each ally in its own row into a random buff, while increasing bonus damage by 10% and damage reduction by 10%, lasting 2 turns.',
		describe_th = 'เชย์มินสร้างพายุใบไม้โหมกระหน่ำโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายเวท #C0x3D8A99#180% พลังเวท#C0x5B545B#+$(skillLevel*4*60)$ หน่วยความเสียหายเวท#C0xF13B54# เปลี่ยนสถานะลบสุ่มหนึ่งสถานะของฮีโร่แต่ละตัวในแนวของตนเองเป็นสถานะบัฟสุ่ม พร้อมทั้งเพิ่มการโจมตีพิเศษ 10% และลดความเสียหาย 10% เป็นเวลา 2 เทิร์น',
		describe_in = 'Shaymin menciptakan badai daun yang menerbangkan, menyerang satu musuh tunggal, memberikan #C0x3D8A99#180% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*60)$ kerusakan sihir#C0xF13B54#. Mengubah satu efek negatif acak dari setiap pahlawan di barisan sendiri menjadi satu efek peningkatan acak, sekaligus meningkatkan 10% kerusakan tambahan dan 10% pengurangan kerusakan, bertahan selama 2 giliran.',
		describe_ph = 'Si Shaymin ay lumilikha ng bagyo ng mga dahon, umaatake sa isang target na kalaban, nagdudulot ng #C0x3D8A99#180% Lakas ng Magic#C0x5B545B#+$(skillLevel*4*60)$ pinsalang magic#C0xF13B54#. Pinapalitan ang isang random na negatibong epekto ng bawat bayani sa kanilang sariling hanay ng isang random na benepisyo, kasabay ng pagtaas ng 10% dagdag na pinsala at 10% bawas sa pinsala, tumatagal ng 2 turn.',
		describe_ma = 'Shaymin menghasilkan ribut daun yang berterbangan, menyerang satu sasaran musuh tunggal, menyebabkan #C0x3D8A99#180% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*60)$ kerosakan sihir#C0xF13B54#. Menukar satu kesan negatif rawak pada setiap wira dalam barisan sendiri kepada satu kesan pengukuhan rawak, serta meningkatkan 10% kerosakan tambahan dan 10% pengurangan kerosakan, berlangsung selama 2 pusingan.',
		describe = 'Shaymin creates a swirling storm of leaves, attacking a single enemy target, dealing #C0x3D8A99#180% Magic Power#C0x5B545B#+$(skillLevel*4*60)$ magic damage#C0xF13B54#. It converts one random negative effect on each ally in its own row into a random buff, while increasing bonus damage by 10% and damage reduction by 10%, lasting 2 turns.',
		simDesc_vn = 'Xie Mi thổi ra cơn bão lá bay, tấn công mục tiêu đơn lẻ của đối phương, gây sát thương ma pháp, biến mọi hiệu ứng tiêu cực của các anh hùng ở hàng của mình thành hiệu ứng cường hóa, và tăng cường sát thương và giảm sát thương.',
		simDesc_en = 'Xie Mi blows out a storm of flying leaves, attacking a single enemy target, dealing magic damage, transforming all negative effects on heroes in his row into buffs, and increasing damage dealt while reducing damage taken.',
		simDesc_th = 'เซี่ยวมี่พัดพายุกระดาษใบไม้ที่พัดพาโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายเวทมนตร์ เปลี่ยนผลกระทบเชิงลบทั้งหมดของฮีโร่ในแถวนั้นให้กลายเป็นผลบัพ และเพิ่มความเสียหายที่สร้างและลดความเสียหายที่ได้รับ',
		simDesc_in = 'Xie Mi meniup badai daun yang terbang, menyerang target musuh tunggal, memberikan kerusakan sihir, mengubah semua efek negatif pada pahlawan di barisnya menjadi buff, serta meningkatkan dan mengurangi kerusakan.',
		simDesc_ph = 'Hinihip ni Xie Mi ang bagyong lumilipad na dahon, inaatake ang isang target na kalaban, nagdudulot ng magic damage, binabago ang lahat ng negatibong epekto sa mga bayani sa kanyang hanay bilang mga buff, at pinapataas ang pinsala habang binabawasan ang natatanggap na pinsala.',
		simDesc_ma = 'Xie Mi meniup ribut daun yang terbang, menyerang sasaran musuh tunggal, menyebabkan kerosakan sihir, mengubah semua kesan negatif pada wira dalam barisnya menjadi kesan penguatan, serta meningkatkan dan mengurangkan kerosakan.',
		simDesc = 'Xie Mi blows out a storm of flying leaves, attacking a single enemy target, dealing magic damage, transforming all negative effects on heroes in his row into buffs, and increasing damage dealt while reducing damage taken.',
		zawakeEffect = __data_t__zawakeEffect[24422],
		-- {79002}
		zawakeEffectDesc = 'Shaymin blows up a storm of flying leaves, attacking a single enemy target, dealing #C0x3D8A99#180% magic damage#C0x5B545B#+$(skillLevel*4*60)$ magic damage#C0xF13B54#, randomly converting 1-2 negative effects of each hero in own row into random buff effects, and increasing additional damage by 15% and reducing damage taken by 15%, lasting 2 turns',
		zawakeEffectDesc_en = 'Shaymin blows up a storm of flying leaves, attacking a single enemy target, dealing #C0x3D8A99#180% magic damage#C0x5B545B#+$(skillLevel*4*60)$ magic damage#C0xF13B54#, randomly converting 1-2 negative effects of each hero in own row into random buff effects, and increasing additional damage by 15% and reducing damage taken by 15%, lasting 2 turns',
		zawakeEffectDesc_th = 'Shaymin เป่าให้เกิดพายุของใบไม้ที่ปลิวว่อน โจมตีเป้าหมายศัตรูเดี่ยว ทำ #C0x3D8A99#180% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*60)$ ความเสียหายเวทมนตร์#C0xF13B54#, แปลงเอฟเฟกต์ลบ 1-2 อันของฮีโร่แต่ละตัวในแถวตัวเองเป็นเอฟเฟกต์บัฟแบบสุ่ม และเพิ่มความเสียหายเพิ่มเติม 15% และลดความเสียหายที่ได้รับ 15% เป็นเวลา 2 รอบ',
		zawakeEffectDesc_in = 'Shaymin meniup badai daun terbang, menyerang 1 target musuh tunggal, memberikan #C0x3D8A99#180% kerusakan sihir#C0x5B545B#+$(skillLevel*4*60)$ kerusakan sihir#C0xF13B54#, secara acak mengubah 1-2 efek negatif dari setiap pahlawan di baris sendiri menjadi efek buff acak, serta meningkatkan tambahan 15% kerusakan dan mengurangi 15% kerusakan selama 2 giliran',
		zawakeEffectDesc_ph = 'Shaymin humampas ng isang bagyong mga lumilipad na dahon, umaatake sa isang solong target ng kaaway, na nagdudulot ng #C0x3D8A99#180% magic damage#C0x5B545B#+$(skillLevel*4*60)$ magic damage#C0xF13B54#, random na nagbabago ng 1-2 negatibong epekto ng bawat bayani sa sariling hanay sa random na buff effect, at nagdaragdag ng 15% dagdag na pinsala at 15% bawas na pinsala, tumatagal ng 2 na turn',
		zawakeEffectDesc_ma = 'Shaymin meniup ribut daun terbang, menyerang 1 sasaran musuh tunggal, menyebabkan #C0x3D8A99#180% kerosakan sihir#C0x5B545B#+$(skillLevel*4*60)$ kerosakan sihir#C0xF13B54#, menukar secara rawak 1-2 kesan negatif setiap wira dalam baris sendiri menjadi kesan peningkatan rawak, dan meningkat 15% kerosakan tambahan dan mengurangkan 15% kerosakan, selama 2 pusingan',
		zawakeEffectDesc_vn = 'Shaymin thổi lên một cơn bão lá bay, tấn công mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#180% sát thương phép#C0x5B545B#+$(skillLevel*4*60)$ sát thương phép#C0xF13B54#, chuyển đổi ngẫu nhiên 1-2 hiệu ứng tiêu cực của mỗi anh hùng trong hàng của bản thân thành hiệu ứng tăng cường ngẫu nhiên, và tăng 15% sát thương cộng thêm và 15% giảm sát thương, kéo dài 2 lượt',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Convert 1 random debuff of each ally in your row into a random buff, and increase extra damage by 10% while reducing damage taken by 10%\n#F20# \n#F40##C0x5c9970#→Convert 1–2 random debuffs of each ally in your row into random buffs, increase extra damage by 15% and reduce damage taken by 15%',
		zawakeSimpleDesc_en = 'Convert 1 random debuff of each ally in your row into a random buff, and increase extra damage by 10% while reducing damage taken by 10%\n#F20# \n#F40##C0x5c9970#→Convert 1–2 random debuffs of each ally in your row into random buffs, increase extra damage by 15% and reduce damage taken by 15%',
		zawakeSimpleDesc_th = 'เปลี่ยนดีบัฟแบบสุ่ม 1 อย่างของฮีโร่แต่ละคนในแถวของคุณเป็นบัฟแบบสุ่ม และเพิ่มดาเมจเพิ่มเติม 10% พร้อมลดความเสียหายที่ได้รับ 10%\n#F20# \n#F40##C0x5c9970#→เปลี่ยนดีบัฟแบบสุ่ม 1–2 อย่างของฮีโร่แต่ละคนในแถวของคุณเป็นบัฟแบบสุ่ม และเพิ่มดาเมจเพิ่มเติม 15% พร้อมลดความเสียหายที่ได้รับ 15%',
		zawakeSimpleDesc_in = 'Ubah 1 debuff acak dari setiap hero di baris kamu menjadi buff acak, meningkatkan damage tambahan 10% dan mengurangi damage yang diterima 10%\n#F20# \n#F40##C0x5c9970#→Ubah 1–2 debuff acak menjadi buff acak, tingkatkan damage tambahan 15% dan kurangi damage yang diterima 15%',
		zawakeSimpleDesc_ph = 'I-convert ang 1 random debuff ng bawat kakampi sa row bilang random buff, dagdag 10% extra damage at bawas 10% damage received\n#F20# \n#F40##C0x5c9970#→I-convert ang 1–2 random debuff bilang random buff, dagdag 15% extra damage at bawas 15% damage received',
		zawakeSimpleDesc_ma = 'Tukar 1 kesan negatif rawak setiap sekutu dalam barisan kepada kesan positif rawak, dan tingkatkan 10% serangan tambahan serta kurangkan 10% kerosakan diterima\n#F20# \n#F40##C0x5c9970#→Tukar 1–2 kesan negatif rawak kepada kesan positif rawak, tingkatkan 15% serangan tambahan dan kurangkan 15% kerosakan diterima',
		zawakeSimpleDesc_vn = 'Chuyển đổi 1 hiệu ứng tiêu cực ngẫu nhiên của mỗi anh hùng trong hàng của bản thân thành hiệu ứng tăng cường ngẫu nhiên, đồng thời tăng 10% sát thương cộng thêm và giảm 10% sát thương nhận vào\n#F20# \n#F40##C0x5c9970#→Chuyển đổi 1-2 hiệu ứng tiêu cực ngẫu nhiên của mỗi anh hùng trong hàng của bản thân thành hiệu ứng tăng cường ngẫu nhiên, đồng thời tăng 15% sát thương cộng thêm và giảm 15% sát thương nhận vào',
