	[24423] = {
		id = 24423,
		skillName_vn = 'Mưa hương thơm',
		skillName_en = 'Fragrant rain',
		skillName_th = 'ฝนหอม',
		skillName_in = 'Hujan harum',
		skillName_ph = 'Pabango ng ulan',
		skillName_ma = 'Hujan wangi',
		skillName = 'Fragrant rain',
		describe_vn = 'Xie Mi thả 2 con bướm, gây ra đòn tấn công ma thuật #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B cho một mục tiêu kẻ địch ngẫu nhiên. 54#Sát Thương Phép Thuật#C0x5B545B#. Sau các cuộc tấn công của loài bướm, nó sẽ quay trở lại trại của chính mình và phục hồi sức khỏe cho hai anh hùng có tỷ lệ máu thấp nhất (mỗi con bướm phục hồi 50% sát thương do nó gây ra)\n#F20# \n#F40#Động thái đặc biệt đầu tiên là thêm dấu [#L10#心之知#L0#] cho hai đơn vị có lượng máu thấp nhất. Dấu hiệu [#L10#心之心#L0#]: Khi nhận sát thương chí mạng, 50% lượng máu từ Sát Thương Phép Thuật của Semi sẽ được giữ lại để tồn tại và nó có thể xua tan các hiệu ứng tiêu cực và khống chế. Dấu sẽ biến mất ngay lập tức sau khi được kích hoạt ([#L10# Sky Form#L0#] chỉ có thể thêm một dấu vào toàn bộ trường)',
		describe_en = 'Xie Mi releases 2 butterflies, causing magic attacks dealing #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B to a random enemy target. 54#Magic Damage#C0x5B545B#. After the butterflies\' attacks, they return to their camp and heal the two heroes with the lowest HP (each butterfly restores 50% of the damage it dealt)\n#F20# \n#F40#The first special move adds the [#L10#Heart\'s Knowledge#L0#] mark to the two units with the lowest HP. The [#L10#Heart\'s Knowledge#L0#] mark: When taking critical damage, 50% of Semi\'s Magic Damage is retained to survive, and it can dispel negative effects and control effects. The mark disappears immediately after activation ([#L10# Sky Form#L0#] can only add one mark to the entire field).',
		describe_th = 'เซี่ยหมี่ปล่อยผีเสื้อจำนวน 2 ตัว สร้างการโจมตีเวทมนตร์ที่สร้างความเสียหาย #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B ไปยังศัตรูเป้าหมายแบบสุ่ม 1 ตัว 54#ความเสียหายเวทมนตร์#C0x5B545B# หลังจากการโจมตีของผีเสื้อ เหล่าผีเสื้อจะกลับมายังค่ายของตนและฟื้นฟูพลังชีวิตให้กับ 2 ฮีโร่ที่มีพลังชีวิตต่ำที่สุด (ผีเสื้อแต่ละตัวฟื้นฟู 50% ของความเสียหายที่มันสร้าง)\n#F20# \n#F40#ท่าพิเศษครั้งแรกจะเพิ่มเครื่องหมาย [#L10#หัวใจแห่งปัญญา#L0#] ให้กับ 2 ยูนิตที่มีพลังชีวิตต่ำที่สุด เครื่องหมาย [#L10#หัวใจแห่งปัญญา#L0#]: เมื่อได้รับความเสียหายคริติคอล จะเก็บรักษา 50% ของความเสียหายเวทมนตร์ของเซมี่ไว้เพื่อความอยู่รอด และจะสามารถขจัดสถานะผิดปกติและควบคุมได้ เครื่องหมายจะหายไปทันทีหลังจากถูกเปิดใช้งาน ([#L10# สกายฟอร์ม#L0#] สามารถเพิ่มเครื่องหมายได้เพียงหนึ่งครั้งในสนามทั้งหมด)',
		describe_in = 'Xie Mi melepaskan 2 kupu-kupu, menyebabkan serangan sihir dengan damage #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B ke satu musuh acak. 54#Kerusakan Sihir#C0x5B545B#. Setelah serangan kupu-kupu, mereka kembali ke markas dan menyembuhkan dua pahlawan dengan HP terendah (setiap kupu-kupu menyembuhkan 50% dari damage yang ditimbulkan)\n#F20# \n#F40#Gerakan khusus pertama menambahkan tanda [#L10#Pengetahuan Hati#L0#] kepada dua unit dengan HP terendah. Tanda [#L10#Pengetahuan Hati#L0#]: Saat menerima damage kritis, 50% dari Magic Damage Semi akan disimpan untuk bertahan hidup, dan dapat menghilangkan efek negatif dan kontrol. Tanda ini hilang segera setelah diaktifkan ([#L10# Bentuk Langit#L0#] hanya dapat menambahkan satu tanda di seluruh medan).',
		describe_ph = 'Inilabas ni Xie Mi ang 2 paru-paro, na nagdudulot ng magic attack na #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B sa isang random na kaaway na target. 54#Magic Damage#C0x5B545B#. Pagkatapos ng mga pag-atake ng mga paru-paro, babalik ito sa sariling kampo at magpapagaling sa dalawang bayani na may pinakamababang HP (ang bawat paru-paro ay nagpapagaling ng 50% ng damage na naidulot nito)\n#F20# \n#F40#Ang unang espesyal na galaw ay maglalagay ng markang [#L10#Kaalaman ng Puso#L0#] sa dalawang unit na may pinakamababang HP. Ang markang [#L10#Kaalaman ng Puso#L0#]: Kapag tumatanggap ng critical damage, 50% ng Magic Damage ni Semi ay mapapanatili upang mabuhay, at kaya nitong tanggalin ang mga negatibong epekto at kontrol. Ang marka ay agad na mawawala pagkatapos ma-activate ([#L10# Sky Form#L0#] ay maaaring magdagdag lamang ng isang marka sa buong field).',
		describe_ma = 'Xie Mi melepaskan 2 rama-rama, menyebabkan serangan sihir dengan #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B kepada satu sasaran musuh secara rawak. 54#Kerusakan Sihir#C0x5B545B#. Selepas serangan rama-rama, ia akan kembali ke kemnya dan memulihkan kesihatan kepada dua wira dengan jumlah darah terendah (setiap rama-rama memulihkan 50% kerosakan yang disebabkannya)\n#F20# \n#F40#Gerakan khas pertama adalah menambah tanda [#L10#Pengetahuan Hati#L0#] kepada dua unit dengan darah terendah. Tanda [#L10#Pengetahuan Hati#L0#]: Apabila menerima serangan kritikal, 50% daripada Kerusakan Sihir Semi akan disimpan untuk bertahan dan ia boleh menolak kesan negatif dan kawalan. Tanda akan hilang serta-merta selepas diaktifkan ([#L10# Bentuk Langit#L0#] hanya boleh menambah satu tanda ke seluruh medan).',
		describe = 'Xie Mi releases 2 butterflies, causing magic attacks dealing #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B to a random enemy target. 54#Magic Damage#C0x5B545B#. After the butterflies\' attacks, they return to their camp and heal the two heroes with the lowest HP (each butterfly restores 50% of the damage it dealt)\n#F20# \n#F40#The first special move adds the [#L10#Heart\'s Knowledge#L0#] mark to the two units with the lowest HP. The [#L10#Heart\'s Knowledge#L0#] mark: When taking critical damage, 50% of Semi\'s Magic Damage is retained to survive, and it can dispel negative effects and control effects. The mark disappears immediately after activation ([#L10# Sky Form#L0#] can only add one mark to the entire field).',
		simDesc_vn = 'Xie Mi phóng ra hai con bướm, mỗi con tấn công một mục tiêu ngẫu nhiên của đối phương gây sát thương ma pháp, hồi phục sinh lực cho hai anh hùng đồng minh, và thêm Dấu Ấn Lòng Biết Ơn cho từng đơn vị của mình.',
		simDesc_en = 'Xie Mi releases two butterflies, each attacking a random enemy target causing magic damage, healing two allied heroes, and adding a Mark of Gratitude to each of his units.',
		simDesc_th = 'เซีย หมี่ ปล่อยผีเสื้อสองตัว แต่ละตัวโจมตีเป้าหมายศัตรูแบบสุ่ม สร้างความเสียหายเวทมนตร์ รักษาพลังชีวิตให้กับฮีโร่พันธมิตรสองคน และเพิ่มเครื่องหมายแห่งความกตัญญูให้กับหน่วยของเขาทุกตัว',
		simDesc_in = 'Xie Mi melepaskan dua kupu-kupu, masing-masing menyerang target musuh secara acak yang menyebabkan kerusakan sihir, menyembuhkan dua pahlawan sekutu, dan menambahkan Tanda Terima Kasih pada tiap unitnya.',
		simDesc_ph = 'Pinapalabas ni Xie Mi ang dalawang paru-paro, bawat isa ay sumasalakay sa isang random na target ng kalaban na nagdudulot ng magic damage, nagpapagaling sa dalawang kaalyadong bayani, at nagdadagdag ng Mark of Gratitude sa bawat yunit niya.',
		simDesc_ma = 'Xie Mi melepaskan dua rama-rama, setiap satu menyerang sasaran musuh secara rawak yang menyebabkan kerosakan magik, memulihkan dua wira sekutu, dan menambah Tanda Kesyukuran pada setiap unitnya.',
		simDesc = 'Xie Mi releases two butterflies, each attacking a random enemy target causing magic damage, healing two allied heroes, and adding a Mark of Gratitude to each of his units.',
		starEffect = __data_t__starEffect[24423],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng thêm: Tuyệt kỹ có thể triệu hồi thêm một con bướm; Số lượng đơn vị bị ảnh hưởng bởi ấn ký  <#L10#Tri ân từ trái tim#L0#>  +1',
		starEffectDesc = 'Effect added: The skill can summon an additional butterfly; Number of units affected by the seal <#L10#Gratitude from the heart#L0#> +1',
		starEffectDesc_en = 'Effect added: The skill can summon an additional butterfly; Number of units affected by the seal <#L10#Gratitude from the heart#L0#> +1',
		starEffectDesc_th = 'เพิ่มเอฟเฟกต์: ทักษะสามารถเรียกผีเสื้อเพิ่มเติมได้หนึ่งตัว; จำนวนหน่วยที่ได้รับผลกระทบจากตราประทับ <#L10#ความกตัญญูจากใจ#L0#> +1',
		starEffectDesc_in = 'Efek ditambahkan: Teknik dapat memanggil kupu-kupu tambahan; Jumlah unit yang terpengaruh oleh segel <#L10#Rasa terima kasih dari hati#L0#> +1',
		starEffectDesc_ph = 'Nagdagdag ng epekto: Ang kakayahan ay maaaring magpalitaw ng karagdagang paru-paro; Bilang ng yunit na apektado ng tatak <#L10#Pasasalamat mula sa puso#L0#> +1',
		starEffectDesc_ma = 'Kesan ditambah: Teknik boleh memanggil seekor rama-rama tambahan; Bilangan unit yang terjejas oleh cap <#L10#Penghargaan dari hati#L0#> +1',
		zawakeEffect = __data_t__zawakeEffect[24423],
		-- {79003}
		zawakeEffectDesc = 'Xie Mi releases 2 butterflies, causing a magical attack #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B to a random enemy target. 54#Magic Damage#C0x5B545B#, after being attacked by the butterflies, they return to their camp and heal the two allies with the lowest health percentages on their side (each butterfly heals 80% of the damage it dealt)\n#F20# \n#F40#The first special move adds the mark <#L10#心之之心#L0#> to the two units with the lowest HP. <#L10#心之之心#L0#> mark: When receiving a critical hit, the mark from Xie Mi will be retained. 50% of the Magic Damage HP will persist and remove negative and control effects. The HP retained by Ninja, Wind, and Earth types is doubled. The mark disappears immediately after activation (<#L10# Sky Form#L0#> can only add one mark to the whole field)',
		zawakeEffectDesc_en = 'Xie Mi releases 2 butterflies, causing a magical attack #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B to a random enemy target. 54#Magic Damage#C0x5B545B#, after being attacked by the butterflies, they return to their camp and heal the two allies with the lowest health percentages on their side (each butterfly heals 80% of the damage it dealt)\n#F20# \n#F40#The first special move adds the mark <#L10#心之之心#L0#> to the two units with the lowest HP. <#L10#心之之心#L0#> mark: When receiving a critical hit, the mark from Xie Mi will be retained. 50% of the Magic Damage HP will persist and remove negative and control effects. The HP retained by Ninja, Wind, and Earth types is doubled. The mark disappears immediately after activation (<#L10# Sky Form#L0#> can only add one mark to the whole field)',
		zawakeEffectDesc_th = 'เซี่ยหมี่ปล่อยผีเสื้อ 2 ตัว ก่อให้เกิดการโจมตีเวทมนตร์ #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B ต่อเป้าหมายศัตรูแบบสุ่ม 54#ความเสียหายเวทมนตร์#C0x5B545B# หลังจากถูกผีเสื้อโจมตี พวกมันจะกลับค่ายของตนและฟื้นฟูพลังชีวิตให้กับผู้กล้า 2 คนที่มีเปอร์เซ็นต์พลังชีวิตต่ำที่สุดในฝั่งของตน (ผีเสื้อแต่ละตัวฟื้นฟู 80% ของความเสียหายที่มันก่อให้เกิด)\n#F20# \n#F40#ท่าไม้ตายพิเศษครั้งแรกจะเพิ่มเครื่องหมาย <#L10#心之之心#L0#> ให้กับ 2 หน่วยที่มี HP ต่ำที่สุด เครื่องหมาย <#L10#心之之心#L0#>: เมื่อได้รับการโจมตีคริติคอล เครื่องหมายจากเซี่ยหมี่จะยังคงอยู่ 50% ของ HP ความเสียหายเวทมนตร์จะคงอยู่และกำจัดสถานะลบและการควบคุม HP ที่ได้รับการคงไว้จากนินจา, ธาตุลม และ ธาตุดิน จะเพิ่มเป็นสองเท่า เครื่องหมายจะหายไปทันทีหลังใช้งาน (<#L10#รูปแบบสวรรค์#L0#> สามารถเพิ่มเครื่องหมายได้เพียงหนึ่งอันในสนามทั้งหมด)',
		zawakeEffectDesc_in = 'Xie Mi melepaskan 2 kupu-kupu, menyebabkan serangan magis #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B ke target musuh acak. 54#Kerusakan Sihir#C0x5B545B#, setelah diserang kupu-kupu, mereka kembali ke kamp mereka dan menyembuhkan dua pahlawan dengan persentase HP terendah di pihaknya (setiap kupu-kupu menyembuhkan 80% dari kerusakan yang ditimbulkannya)\n#F20# \n#F40#Gerakan khusus pertama menambahkan tanda <#L10#心之之心#L0#> pada dua unit dengan HP terendah. Tanda <#L10#心之之心#L0#>: Saat menerima serangan kritis, tanda dari Xie Mi akan tetap ada. 50% HP Kerusakan Sihir akan bertahan dan menghapus efek negatif dan kontrol. HP yang dipertahankan oleh tipe Ninja, Angin, dan Tanah dilipatgandakan. Tanda akan langsung hilang setelah diaktifkan (<#L10# Bentuk Langit#L0#> hanya bisa menambahkan satu tanda untuk seluruh medan)',
		zawakeEffectDesc_ph = 'Pinakawalan ni Xie Mi ang 2 paru-paro, nagdulot ng isang mahikang atake #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B sa isang random na kaaway na target. 54#Mahikang Pinsala#C0x5B545B#, pagkatapos tamaan ng paru-paro, babalik ito sa kampo nila at gagalingin ang dalawang bayani na may pinakamababang porsyento ng HP sa kanilang panig (bawat paru-paro ay nagpapagaling ng 80% ng pinsalang ipinataw nito)\n#F20# \n#F40#Ang unang espesyal na galaw ay nagdadagdag ng marka <#L10#心之之心#L0#> sa dalawang yunit na may pinakamababang HP. Marka <#L10#心之之心#L0#>: Kapag tumatanggap ng kritikal na pinsala, mananatili ang marka mula kay Xie Mi. 50% ng HP ng Mahikang Pinsala ay mananatili at aalisin ang negatibong mga epekto at kontrol. Ang HP na pinananatili ng mga Ninja, Hangin, at Lupa na uri ay duplipikado. Ang marka ay mawawala agad pagkatapos ma-activate (<#L10# Sky Form#L0#> ay maaaring magdagdag ng isang marka sa buong larangan)',
		zawakeEffectDesc_ma = 'Xie Mi melepaskan 2 rama-rama, menyebabkan serangan magik #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B kepada sasaran musuh secara rawak. 54#Kerosakan Ajaib#C0x5B545B#, selepas diserang rama-rama, mereka akan kembali ke kem mereka dan memulihkan dua wira yang mempunyai peratusan kesihatan terendah di pihak mereka (setiap rama-rama memulihkan 80% daripada kerosakan yang disebabkan)\n#F20# \n#F40#Gerakan khas pertama menambah tanda <#L10#心之之心#L0#> kepada dua unit dengan HP terendah. Tanda <#L10#心之之心#L0#>: Apabila menerima serangan kritikal, tanda daripada Xie Mi akan dikekalkan. 50% HP Kerosakan Ajaib akan kekal dan menghilangkan kesan negatif dan kawalan. HP yang dikekalkan oleh jenis Ninja, Angin, dan Tanah akan digandakan. Tanda akan hilang dengan serta-merta selepas diaktifkan (<#L10# Bentuk Langit#L0#> hanya boleh menambah satu tanda untuk seluruh medan)',
		zawakeEffectDesc_vn = 'Xie Mi thả 2 con bướm, gây ra đòn tấn công ma thuật #C0x3D8A99#330%#C0x5B545B#+$(skillLevel*4*45)$#C0xF13B cho một mục tiêu kẻ thù ngẫu nhiên. 54#Sát thương phép#C0x5B545B#, sau khi bị bướm tấn công, nó sẽ trở về trại của mình và phục hồi máu cho hai anh hùng có phần trăm máu thấp nhất của chính mình (mỗi con bướm phục hồi 80% sát thương do nó gây ra)\n#F20# \n#F40#Động thái đặc biệt đầu tiên là thêm dấu <#L10#心之之心#L0#> cho hai đơn vị có HP thấp nhất. <#L10#心之之心#L0#> dấu ấn: Khi nhận sát thương chí mạng, dấu ấn từ Xie Mi sẽ được giữ lại. 50% HP của Sát Thương Phép Thuật sẽ tồn tại và loại bỏ các hiệu ứng tiêu cực và khống chế. HP mà các loại Ninja, Gió và Đất giữ lại được tăng gấp đôi. Dấu sẽ biến mất ngay lập tức sau khi được kích hoạt (<#L10# Sky Form#L0#> chỉ có thể thêm một dấu vào toàn bộ trường)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Butterfly\'s healing ratio increases to 80% of damage dealt; <Grateful Soul> Mark: When activated with Ninja, Wind, or Earth type, retained HP is doubled',
		zawakeSimpleDesc_en = 'Butterfly\'s healing ratio increases to 80% of damage dealt; <Grateful Soul> Mark: When activated with Ninja, Wind, or Earth type, retained HP is doubled',
		zawakeSimpleDesc_th = 'อัตราการฮีลของผีเสื้อเพิ่มขึ้นเป็น 80% ของดาเมจที่สร้างได้; <จิตวิญญาณแห่งความกตัญญู>: เมื่อเปิดใช้กับสาย นินจา, ลม, หรือดิน ปริมาณ HP ที่คงไว้จะเพิ่มขึ้นเป็นสองเท่า',
		zawakeSimpleDesc_in = 'Rasio penyembuhan Butterfly naik menjadi 80% dari damage yang diberikan; <Jiwa Bersyukur>: Saat aktif dengan tipe Ninja, Angin, atau Tanah, HP yang tersisa akan digandakan',
		zawakeSimpleDesc_ph = 'Ang healing ng Butterfly ay nagiging 80% ng damage na naibigay; <Pasasalamat na Kaluluwa>: kapag kasama ang Ninja, Wind, o Earth-type, dodoble ang natirang HP',
		zawakeSimpleDesc_ma = 'Kadar pemulihan Butterfly meningkat kepada 80% daripada kerosakan yang diberi; <Jiwa Bersyukur>: Apabila diaktifkan dengan jenis Ninja, Angin, atau Tanah, HP yang tinggal akan digandakan',
		zawakeSimpleDesc_vn = 'Hệ số hồi máu của Bướm tăng lên 80% sát thương gây ra; Dấu ấn <Tâm Hồn Biết Ơn>: Khi kích hoạt với hệ Nhẫn, hệ Gió, hệ Đất, lượng máu giữ lại sẽ được nhân đôi',
		upLvDesc = 'Fixed damage +180',
