	[24426] = {
		id = 24426,
		skillName_vn = 'Hoa trên trời',
		skillName_en = 'Flowers in the sky',
		skillName_th = 'ดอกไม้บนท้องฟ้า',
		skillName_in = 'Bunga di langit',
		skillName_ph = 'Mga bulaklak sa langit',
		skillName_ma = 'Bunga di langit',
		skillName = 'Flowers in the sky',
		describe_vn = 'Nhập [#L10#Sky Form#L0#] cho các vòng 1-3 trong trận chiến và chuyển sang [#L10#Land Form#L0#] cho các vòng 4-6 (chu kỳ này)\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn của [#L10#Sky Form#L0#], hạ hai đơn vị ngẫu nhiên ở hàng trước của kẻ địch Hiệu ứng hồi máu của #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C 0x5B545B# và hiệu ứng hồi máu của #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# kéo dài trong một hiệp lớn\n#F20# \n#F40# Mỗi lần [#L10# Sky Form#L0#] xuất hiện, đặt [#L10#花花#L0#] trước toàn bộ trại của bạn trong 2 lượt lớn: bạn có thể phục hồi thêm 150 điểm nộ trước khi hành động và đồng đội của bạn thực hiện ba hành động đầu tiên sẽ tăng đòn tấn công kép của họ lên 12% (1 lượt) và 12% tỷ lệ trúng đòn chí mạng (1 lượt) trước khi hành động.\n#F20# \n#F40#[#L10#花花#L0#] biến mất hoặc khi [#L10#天花#L0#] thực hiện chiêu cuối đầu tiên, Sát Thương Phép Thuật và sát thương cộng thêm của Xie Mi sẽ tăng vĩnh viễn thêm 20% (không thể cộng dồn).',
		describe_en = 'Enter [#L10#Sky Form#L0#] for rounds 1-3 in the battle and switch to [#L10#Land Form#L0#] for rounds 4-6 (this cycle).\n#F20# \n#F40# At the start of each major round of [#L10#Sky Form#L0#], lower two random units in the front row of the enemy. Healing effect of #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# and the healing effect of #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# last for one major round.\n#F20# \n#F40# Each time [#L10#Sky Form#L0#] appears, place [#L10#花花#L0#] before your entire camp for 2 major rounds: you can recover an additional 150 rage points before acting, and your teammates performing the first three actions will have their dual attack increased by 12% (1 round) and critical hit rate increased by 12% (1 round) before acting.\n#F20# \n#F40# [#L10#花花#L0#] disappears or when [#L10#天花#L0#] performs the first ultimate skill, Xie Mi\'s Magic Damage and additional damage increase permanently by 20% (cannot stack).',
		describe_th = 'เข้าสู่ [#L10#รูปแบบท้องฟ้า#L0#] สำหรับรอบที่ 1-3 ในการต่อสู้และเปลี่ยนเป็น [#L10#รูปแบบพื้นดิน#L0#] สำหรับรอบที่ 4-6 (รอบนี้)\n#F20# \n#F40# เมื่อเริ่มแต่ละรอบใหญ่ของ [#L10#รูปแบบท้องฟ้า#L0#] ให้ลดหน่วยสุ่มสองหน่วยในแถวหน้าของศัตรู ผลการฟื้นฟูของ #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# และผลการฟื้นฟูของ #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# จะอยู่ได้นานหนึ่งรอบใหญ่\n#F20# \n#F40# ทุกครั้งที่ [#L10#รูปแบบท้องฟ้า#L0#] ปรากฏ ให้วาง [#L10#花花#L0#] ต่อหน้าค่ายของคุณทั้งหมดเป็นเวลา 2 รอบใหญ่: คุณสามารถฟื้นฟูพลังแค้นเพิ่มอีก 150 ก่อนที่จะเคลื่อนไหว และเพื่อนร่วมทีมที่ทำการเคลื่อนไหวสามครั้งแรกจะได้รับการเพิ่มการโจมตีคู่ 12% (1 รอบ) และอัตราการตีคริติคอล 12% (1 รอบ) ก่อนที่จะเคลื่อนไหว\n#F20# \n#F40# [#L10#花花#L0#] หายไปหรือเมื่อ [#L10#天花#L0#] ใช้สกิลอัลติเมตครั้งแรก ความเสียหายเวทมนตร์และความเสียหายเพิ่มเติมของเซี่ยมี่จะเพิ่มขึ้นถาวร 20% (ไม่สามารถซ้อนทับได้)',
		describe_in = 'Masuk ke [#L10#Sky Form#L0#] untuk putaran 1-3 dalam pertempuran dan beralih ke [#L10#Land Form#L0#] untuk putaran 4-6 (siklus ini).\n#F20# \n#F40# Saat memulai setiap putaran besar [#L10#Sky Form#L0#], turunkan dua unit acak pada baris depan musuh. Efek penyembuhan sebesar #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# dan efek penyembuhan sebesar #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# berlangsung selama satu putaran besar.\n#F20# \n#F40# Setiap kali [#L10#Sky Form#L0#] muncul, tempatkan [#L10#花花#L0#] di depan seluruh kamp Anda selama 2 putaran besar: Anda dapat memulihkan 150 poin kemarahan tambahan sebelum bertindak dan rekan tim yang melakukan tiga aksi pertama akan meningkatkan serangan ganda mereka sebesar 12% (1 putaran) dan tingkat serangan kritis sebesar 12% (1 putaran) sebelum bertindak.\n#F20# \n#F40# [#L10#花花#L0#] menghilang atau saat [#L10#天花#L0#] melakukan jurus pamungkas pertama, Damage Sihir dan damage tambahan Xie Mi akan meningkat secara permanen sebesar 20% (tidak dapat menumpuk).',
		describe_ph = 'Pasukin ang [#L10#Sky Form#L0#] para sa mga round 1-3 sa laban at lumipat sa [#L10#Land Form#L0#] para sa mga round 4-6 (itong siklo).\n#F20# \n#F40# Sa pagsisimula ng bawat malaking round ng [#L10#Sky Form#L0#], pababain ang dalawang random units sa unahang linya ng kalaban. Ang epekto ng paghilom ng #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# at epekto ng paghilom ng #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# ay tumatagal sa loob ng isang malaking round.\n#F20# \n#F40# Sa bawat paglitaw ng [#L10#Sky Form#L0#], ilagay ang [#L10#花花#L0#] sa unahan ng buong kampo mo sa loob ng 2 malaking round: makakapag-recover ka ng dagdag na 150 rage points bago kumilos at ang mga kakampi mo na gagawa ng unang tatlong aksyon ay tumaas ng 12% ang kanilang double attack (1 round) at 12% ang critical hit rate (1 round) bago kumilos.\n#F20# \n#F40# Mawawala ang [#L10#花花#L0#] o kapag ginamit ni [#L10#天花#L0#] ang unang ultimate skill, ang Magic Damage at dagdag na damage ni Xie Mi ay tataas ng permanente ng 20% (hindi maaaring mag-stack).',
		describe_ma = 'Masuk ke [#L10#Sky Form#L0#] untuk pusingan 1-3 dalam pertempuran dan beralih ke [#L10#Land Form#L0#] untuk pusingan 4-6 (kitaran ini).\n#F20# \n#F40# Pada permulaan setiap pusingan utama [#L10#Sky Form#L0#], turunkan dua unit rawak di barisan hadapan musuh. Kesan penyembuhan #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# dan kesan penyembuhan #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# berlangsung selama satu pusingan utama.\n#F20# \n#F40# Setiap kali [#L10#Sky Form#L0#] muncul, letakkan [#L10#花花#L0#] di hadapan seluruh kem anda selama 2 pusingan utama: anda boleh memulihkan tambahan 150 mata kemarahan sebelum bertindak dan rakan sepasukan yang melakukan tiga aksi pertama akan meningkatkan serangan berganda mereka sebanyak 12% (1 pusingan) dan kadar serangan kritikal sebanyak 12% (1 pusingan) sebelum bertindak.\n#F20# \n#F40# [#L10#花花#L0#] hilang atau apabila [#L10#天花#L0#] melakukan serangan utama pertama, Kerosakan Ajaib dan kerosakan tambahan Xie Mi akan meningkat kekal sebanyak 20% (tidak boleh bertindan).',
		describe = 'Enter [#L10#Sky Form#L0#] for rounds 1-3 in the battle and switch to [#L10#Land Form#L0#] for rounds 4-6 (this cycle).\n#F20# \n#F40# At the start of each major round of [#L10#Sky Form#L0#], lower two random units in the front row of the enemy. Healing effect of #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# and the healing effect of #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# last for one major round.\n#F20# \n#F40# Each time [#L10#Sky Form#L0#] appears, place [#L10#花花#L0#] before your entire camp for 2 major rounds: you can recover an additional 150 rage points before acting, and your teammates performing the first three actions will have their dual attack increased by 12% (1 round) and critical hit rate increased by 12% (1 round) before acting.\n#F20# \n#F40# [#L10#花花#L0#] disappears or when [#L10#天花#L0#] performs the first ultimate skill, Xie Mi\'s Magic Damage and additional damage increase permanently by 20% (cannot stack).',
		starEffect = __data_t__starEffect[24426],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Trong thời gian tồn tại của <Hoa Trên Trời>, bản thân nhận được 20% hồi phục tấn công (sát thương gây ra cho mục tiêu sẽ hồi phục một tỷ lệ máu cho bản thân).',
		starEffectDesc = 'Additional effect: During the duration of <Hoa Trên Trời>, the user gains 20% attack recovery (damage dealt to the target will heal a portion of HP for the user).',
		starEffectDesc_en = 'Additional effect: During the duration of <Hoa Trên Trời>, the user gains 20% attack recovery (damage dealt to the target will heal a portion of HP for the user).',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ในระหว่างที่ <Hoa Trên Trời> อยู่ จะได้รับการฟื้นฟูการโจมตี 20% (ความเสียหายที่ทำกับเป้าหมายจะฟื้นฟูพลังชีวิตบางส่วนให้กับตัวเอง)',
		starEffectDesc_in = 'Efek tambahan: Selama <Hoa Trên Trời> aktif, pengguna menerima pemulihan serangan sebesar 20% (kerusakan yang ditimbulkan pada target akan memulihkan sebagian HP untuk pengguna).',
		starEffectDesc_ph = 'Karagdagang epekto: Sa habang umiiral ang <Hoa Trên Trời>, ang sarili ay nakakakuha ng 20% na paggaling ng atake (ang pinsalang ginawa sa target ay gagaling ng isang bahagi ng HP para sa sarili).',
		starEffectDesc_ma = 'Kesan tambahan: Semasa <Hoa Trên Trời> berlangsung, pengguna mendapat pemulihan serangan sebanyak 20% (kerosakan yang diberikan kepada sasaran akan memulihkan sebahagian HP untuk pengguna).',
		zawakeEffect = __data_t__zawakeEffect[24426],
		-- {79004}
		zawakeEffectDesc = 'Enter <#L10#Sky Form#L0#> for rounds 1-3 in battle and switch to <#L10#Land Form#L0#> for rounds 4-6 (this cycle)\n#F20# \n#F40# At the start of each major round of <#L10#Sky Form#L0#>, lower two random front-row enemy units The healing effect of #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# and the healing effect of #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# last for one major round\n#F20# \n#F40# Each time <#L10#Sky Form#L0#> appears, place <#L10#花花#L0#> in front of your entire camp for 2 major rounds: you can recover an additional 150 rage points before acting, and all your teammates will have 12% double attack (1 round) and 12% critical hit rate (1 round) before acting. After acting, 60% of their double attack health will be recovered\n#F20# \n#F40# <#L10#花花#L0#> disappears or when <#L10#天花#L0#> performs the first ultimate skill, 20% Magic Damage and 20% additional damage from Xie Mi will increase permanently (cannot stack); upon entering battle, gain the effect of the mark <Grateful Heart> (activated once on the whole field)',
		zawakeEffectDesc_en = 'Enter <#L10#Sky Form#L0#> for rounds 1-3 in battle and switch to <#L10#Land Form#L0#> for rounds 4-6 (this cycle)\n#F20# \n#F40# At the start of each major round of <#L10#Sky Form#L0#>, lower two random front-row enemy units The healing effect of #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# and the healing effect of #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# last for one major round\n#F20# \n#F40# Each time <#L10#Sky Form#L0#> appears, place <#L10#花花#L0#> in front of your entire camp for 2 major rounds: you can recover an additional 150 rage points before acting, and all your teammates will have 12% double attack (1 round) and 12% critical hit rate (1 round) before acting. After acting, 60% of their double attack health will be recovered\n#F20# \n#F40# <#L10#花花#L0#> disappears or when <#L10#天花#L0#> performs the first ultimate skill, 20% Magic Damage and 20% additional damage from Xie Mi will increase permanently (cannot stack); upon entering battle, gain the effect of the mark <Grateful Heart> (activated once on the whole field)',
		zawakeEffectDesc_th = 'เข้าสู่ <#L10#รูปแบบท้องฟ้า#L0#> สำหรับรอบที่ 1-3 ในการต่อสู้ และเปลี่ยนเป็น <#L10#รูปแบบพื้นดิน#L0#> สำหรับรอบที่ 4-6 (รอบนี้)\n#F20# \n#F40# เมื่อเริ่มแต่ละรอบใหญ่ของ <#L10#รูปแบบท้องฟ้า#L0#> ลดหน่วยศัตรูแถวหน้าแบบสุ่ม 2 ตัว ผลการฟื้นฟูของ #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# และผลการฟื้นฟูของ #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# จะคงอยู่เป็นเวลาหนึ่งรอบใหญ่\n#F20# \n#F40# ทุกครั้งที่ <#L10#รูปแบบท้องฟ้า#L0#> ปรากฏ ให้วาง <#L10#花花#L0#> หน้าแคมป์ของคุณทั้งหมดเป็นเวลา 2 รอบใหญ่: คุณจะฟื้นฟูพลังโกรธเพิ่มอีก 150 ก่อนที่ทำการกระทำ และเพื่อนร่วมทีมทั้งหมดจะได้รับการโจมตีสองเท่า 12% (1 รอบ) และอัตราคริติคอล 12% (1 รอบ) ก่อนทำการกระทำ หลังจากทำการกระทำ สุขภาพของการโจมตีสองเท่าของพวกเขาจะถูกฟื้นฟู 60%\n#F20# \n#F40# <#L10#花花#L0#> หายไป หรือเมื่อ <#L10#天花#L0#> ใช้สกิลอัลติเมทครั้งแรก ความเสียหายเวทมนตร์ 20% และความเสียหายพิเศษ 20% ของเซียนหมี่จะเพิ่มขึ้นอย่างถาวร (ไม่สามารถซ้อนทับ); เมื่อเข้าสู่การต่อสู้จะได้รับผลของเครื่องหมาย <หัวใจแห่งความกตัญญู> (เปิดใช้งานหนึ่งครั้งทั่วทั้งสนาม)',
		zawakeEffectDesc_in = 'Masuk ke <#L10#Sky Form#L0#> untuk putaran 1-3 dalam pertempuran dan beralih ke <#L10#Land Form#L0#> untuk putaran 4-6 (siklus ini)\n#F20# \n#F40# Pada awal setiap putaran besar <#L10#Sky Form#L0#>, turunkan dua unit acak barisan depan musuh Efek penyembuhan dari #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# dan efek penyembuhan dari #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# bertahan selama satu putaran besar\n#F20# \n#F40# Setiap kali <#L10#Sky Form#L0#> muncul, tempatkan <#L10#花花#L0#> di depan seluruh kamp Anda selama 2 putaran besar: Anda bisa memulihkan tambahan 150 poin amarah sebelum bertindak, dan semua rekan tim Anda akan mendapat tambahan 12% serangan ganda (1 putaran) dan 12% peluang serangan kritis (1 putaran) sebelum bertindak. Setelah bertindak, 60% dari kesehatan serangan ganda mereka akan dipulihkan\n#F20# \n#F40# <#L10#花花#L0#> hilang atau ketika <#L10#天花#L0#> melakukan serangan ultimate pertama, 20% Kerusakan Magis dan 20% kerusakan tambahan dari Xie Mi akan meningkat secara permanen (tidak dapat ditumpuk); saat memasuki pertempuran akan mendapatkan efek tanda <Hati Bersyukur> (aktif satu kali di seluruh medan)',
		zawakeEffectDesc_ph = 'Pumasok sa <#L10#Sky Form#L0#> para sa mga rounds 1-3 sa laban at lumipat sa <#L10#Land Form#L0#> para sa rounds 4-6 (sa siklong ito)\n#F20# \n#F40# Sa simula ng bawat malaking round ng <#L10#Sky Form#L0#>, pababain ang dalawang random na yunit sa front row ng kalaban Ang healing effect ng #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# at healing effect ng #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# ay tumatagal ng isang malaking round\n#F20# \n#F40# Sa bawat paglitaw ng <#L10#Sky Form#L0#>, ilagay ang <#L10#花花#L0#> sa harap ng buong kampo mo sa loob ng 2 malaking rounds: maaari kang makabawi ng dagdag na 150 rage points bago kumilos, at lahat ng kakampi mo ay magkakaroon ng dagdag na 12% double attack (1 round) at 12% critical hit rate (1 round) bago kumilos. Pagkatapos kumilos, mababawi ang 60% ng double attack health nila\n#F20# \n#F40# Mawawala ang <#L10#花花#L0#> o kapag ginamit ni <#L10#天花#L0#> ang unang ultimate skill, 20% Magic Damage at 20% karagdagang pinsala mula kay Xie Mi ay tataas nang permanente (hindi pwedeng mag-stack); pagpasok sa laban ay makakatanggap ng epekto ng marka <Grateful Heart> (na-activate isang beses sa buong field)',
		zawakeEffectDesc_ma = 'Masuk ke <#L10#Sky Form#L0#> untuk pusingan 1-3 dalam pertempuran dan beralih ke <#L10#Land Form#L0#> untuk pusingan 4-6 (kitaran ini)\n#F20# \n#F40# Pada permulaan setiap pusingan besar <#L10#Sky Form#L0#>, turunkan dua unit depan musuh secara rawak Kesan penyembuhan #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# dan kesan penyembuhan #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# bertahan selama satu pusingan besar\n#F20# \n#F40# Setiap kali <#L10#Sky Form#L0#> muncul, letakkan <#L10#花花#L0#> di hadapan keseluruhan kem anda selama 2 pusingan besar: anda boleh memulihkan tambahan 150 mata amarah sebelum bertindak, dan semua rakan sepasukan anda akan mendapat tambahan 12% serangan berganda (1 pusingan) dan 12% kadar serangan kritikal (1 pusingan) sebelum bertindak. Selepas bertindak, 60% kesihatan serangan berganda mereka akan dipulihkan\n#F20# \n#F40# <#L10#花花#L0#> hilang atau apabila <#L10#天花#L0#> melakukan serangan utama pertama, 20% Kerosakan Sihir dan 20% kerosakan tambahan dari Xie Mi akan meningkat secara kekal (tidak boleh bertindih); apabila memasuki pertempuran akan menerima kesan tanda <Hati Bersyukur> (aktif sekali untuk seluruh medan)',
		zawakeEffectDesc_vn = 'Nhập <#L10#Sky Form#L0#> cho các vòng 1-3 trong trận chiến và chuyển sang <#L10#Land Form#L0#> cho các vòng 4-6 (chu kỳ này)\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn của <#L10#Sky Form#L0#>, hạ hai đơn vị ngẫu nhiên ở hàng trước của kẻ địch Hiệu ứng hồi máu của #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C 0x5B545B# và hiệu ứng hồi máu của #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# kéo dài trong một hiệp lớn\n#F20# \n#F40# Mỗi lần <#L10# Sky Form#L0#> xuất hiện, đặt <#L10#花花#L0#> trước toàn bộ trại của bạn trong 2 lượt lớn: bạn có thể phục hồi thêm 150 điểm giận dữ trước khi hành động và tất cả đồng đội của bạn sẽ có thêm 12% đòn tấn công kép (1 lượt) và 12% tỷ lệ trúng đòn chí mạng (1 lượt) trước khi hành động. Sau khi hành động, 60% máu tấn công kép của họ sẽ được phục hồi\n#F20# \n#F40#<#L10#花花#L0#> biến mất hoặc khi <#L10#天花#L0#> thực hiện chiêu cuối đầu tiên, 20% Sát Thương Phép Thuật và 20% sát thương cộng thêm của Xie Mi sẽ tăng vĩnh viễn (không thể chồng lên); khi vào trận sẽ nhận được hiệu ứng dấu ấn <Trái tim biết ơn> (kích hoạt một lần trên toàn sân)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Enhanced <Heavenly Flower> effect: Before each ally\'s turn, increase Double Attack by 12% (1 turn) and Crit Rate by 12% (1 turn); after the ally\'s action, heal HP equal to 60% of their Double Attack; Upon entering battle, gain <Grateful Soul> Mark (activates once per battle)',
		zawakeSimpleDesc_en = 'Enhanced <Heavenly Flower> effect: Before each ally\'s turn, increase Double Attack by 12% (1 turn) and Crit Rate by 12% (1 turn); after the ally\'s action, heal HP equal to 60% of their Double Attack; Upon entering battle, gain <Grateful Soul> Mark (activates once per battle)',
		zawakeSimpleDesc_th = 'เอฟเฟกต์ <ดอกไม้สวรรค์> ที่พัฒนาแล้ว: ก่อนถึงตาของพันธมิตรแต่ละคน เพิ่มพลังโจมตีคู่ 12% (1 เทิร์น) และคริติคอล 12% (1 เทิร์น); หลังจากการกระทำของพันธมิตร จะฟื้น HP เท่ากับ 60% พลังโจมตีคู่ของพวกเขา; เมื่อเริ่มต่อสู้ จะได้รับ <จิตวิญญาณแห่งความกตัญญู> (เปิดใช้ 1 ครั้ง)',
		zawakeSimpleDesc_in = 'Efek <Bunga Surga> yang ditingkatkan: Sebelum giliran sekutu, tingkatkan Serangan Ganda 12% (1 giliran) dan Crit Rate 12% (1 giliran); Setelah giliran sekutu, pulihkan HP sebesar 60% dari Serangan Ganda mereka; Saat memasuki pertempuran, diri sendiri memperoleh Tanda <Jiwa Bersyukur> (aktif 1 kali)',
		zawakeSimpleDesc_ph = 'Pinalakas na <Heaven Flower> effect: Bago ang bawat turn ng kakampi, dagdagan ng 12% Double Attack at 12% Crit Rate (1 turn); pagkatapos ng turn nila, mag-heal ng 60% ng kanilang Double Attack; Sa simula ng laban, nakukuha ang <Pasasalamat na Kaluluwa> (gamitin 1 beses lamang)',
		zawakeSimpleDesc_ma = 'Kesan <Bunga Langit> dipertingkatkan: Sebelum giliran setiap sekutu, tambah 12% Serangan Berganda dan 12% Kadar Kritikal (1 giliran); selepas tindakan sekutu, pulihkan HP bersamaan 60% Serangan Berganda mereka; Diri sendiri menerima <Jiwa Bersyukur> apabila memasuki medan pertempuran (aktif 1 kali)',
		zawakeSimpleDesc_vn = 'Hiệu quả <Hoa Trời> được tăng cường: Trước lượt hành động của tất cả đồng đội phe ta, tăng thêm 12% tấn công đôi (1 lượt) và 12% tỷ lệ chí mạng (1 lượt), sau lượt hành động của đồng đội, hồi máu bằng 60% tấn công đôi của họ; Khi vào trận, bản thân nhận hiệu quả Dấu ấn <Tâm Hồn Biết Ơn> (kích hoạt 1 lần toàn trận)',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {244261, 244262}
	},
	[24611] = {
		id = 24611,
		skillName_vn = 'Sao băng lửa',
		skillName_en = 'Fire Meteor',
		skillName_th = 'ดาวตกไฟ',
		skillName_in = 'Meteor Api',
		skillName_ph = 'Sunog na Meteor',
		skillName_ma = 'Meteor Api',
		skillName = 'Fire Meteor',
		describe_vn = '#C0xC0C0C0#V Kết nối tốt, đây là tia sáng của chiến thắng! V#C0x5B545B#\n#F10#\n#F40#Victini triệu hồi 3 thiên thạch rực lửa để tấn công một mục tiêu kẻ thù, mỗi thiên thạch gây ra #C0x3D8A99#60% Sát Thương Phép Thuật#C0x5B545B#+$( SkillLevel*4*24)$#C0xF13B54#sát thương phép#C0x5B545B#, cho mỗi mục tiêu bổ sung bị tấn công, Sát Thương Phép Thuật và tốc độ tăng 10% (có thể cộng dồn tối đa 3 lớp), kéo dài trong 2 hiệp.',
		describe_en = 'V Good connection, this is the light of victory! Victini summons 3 blazing meteors to attack a single enemy target, each meteor dealing 60% Magic Damage + $( SkillLevel*4*24)$ magic damage. For each additional target hit, Magic Damage and speed increase by 10% (stacks up to 3 times), lasting 2 turns.',
		describe_th = 'V การเชื่อมต่อดี นี่คือแสงแห่งชัยชนะ! Victini เรียกอุกกาบาตเปลวเพลิง 3 ลูกโจมตีเป้าหมายศัตรูหนึ่งตัว อุกกาบาตแต่ละลูกก่อให้เกิดความเสียหายเวทมนตร์ 60% + $( SkillLevel*4*24)$ ความเสียหายเวท สำหรับแต่ละเป้าหมายเพิ่มเติมที่ถูกโจมตี ความเสียหายเวทและความเร็วจะเพิ่มขึ้น 10% (สะสมได้สูงสุด 3 ครั้ง) นาน 2 เทิร์น',
		describe_in = 'V Koneksi bagus, ini adalah cahaya kemenangan! Victini memanggil 3 meteorit yang menyala untuk menyerang satu target musuh, setiap meteorit memberikan 60% Damage Magic + $( SkillLevel*4*24)$ damage magic. Untuk setiap target tambahan yang terkena serangan, Damage Magic dan kecepatan meningkat 10% (dapat bertumpuk hingga 3 kali), berlangsung selama 2 giliran.',
		describe_ph = 'V Magandang koneksyon, ito ang liwanag ng tagumpay! Victini ay nag-summon ng 3 naglalagablab na meteoro upang atakehin ang isang kaaway na target, bawat meteor ay nagdudulot ng 60% Magic Damage + $( SkillLevel*4*24)$ magic damage. Para sa bawat karagdagang target na tinamaan, Magic Damage at bilis ay tumataas ng 10% (maaaring mag-stack hanggang 3 beses), tumatagal ng 2 turns.',
		describe_ma = 'V Sambungan baik, ini adalah cahaya kemenangan! Victini memanggil 3 meteorit berapi untuk menyerang satu sasaran musuh, setiap meteorit menyebabkan 60% Kerosakan Sihir + $( SkillLevel*4*24)$ kerosakan sihir. Untuk setiap sasaran tambahan yang diserang, Kerosakan Sihir dan kelajuan meningkat 10% (boleh bertindih sehingga 3 kali), berlangsung selama 2 giliran.',
		describe = 'V Good connection, this is the light of victory! Victini summons 3 blazing meteors to attack a single enemy target, each meteor dealing 60% Magic Damage + $( SkillLevel*4*24)$ magic damage. For each additional target hit, Magic Damage and speed increase by 10% (stacks up to 3 times), lasting 2 turns.',
		zawakeEffect = __data_t__zawakeEffect[24611],
		-- {79001}
		zawakeEffectDesc = '#C0xC0C0C0#Good connection, this is the ray of victory! V#C0x5B545B#\n#F10#\n#F40#Victini summons 3 blazing meteors to attack one enemy target, each meteor dealing #C0x3D8A99#60% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$\'s #C0xF13B54# Magical Damage #C0x5B545B#, and simultaneously applies a burn effect to each target for 2 turns. For each additional target attacked, Magical Damage and speed increase by 10% (can stack up to 3 times), lasting for 2 turns.',
		zawakeEffectDesc_en = '#C0xC0C0C0#Good connection, this is the ray of victory! V#C0x5B545B#\n#F10#\n#F40#Victini summons 3 blazing meteors to attack one enemy target, each meteor dealing #C0x3D8A99#60% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$\'s #C0xF13B54# Magical Damage #C0x5B545B#, and simultaneously applies a burn effect to each target for 2 turns. For each additional target attacked, Magical Damage and speed increase by 10% (can stack up to 3 times), lasting for 2 turns.',
		zawakeEffectDesc_th = '#C0xC0C0C0#การเชื่อมต่อดี นี่คือแสงแห่งชัยชนะ! V#C0x5B545B#\n#F10#\n#F40#Victini เรียกดาวตกเปลวไฟ 3 ดวงโจมตีเป้าหมายศัตรูหนึ่งตัว ดาวตกแต่ละดวงสร้าง #C0x3D8A99#60% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$\'s #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# และในขณะเดียวกันก็เพิ่มผลเผาไหม้ให้กับเป้าหมายแต่ละตัวเป็นเวลา 2 เทิร์น สำหรับเป้าหมายเพิ่มเติมแต่ละตัวที่ถูกโจมตี ความเสียหายเวทมนตร์และความเร็วจะเพิ่มขึ้น 10% (ซ้อนทับได้สูงสุด 3 ชั้น) มีผลนาน 2 เทิร์น',
		zawakeEffectDesc_in = '#C0xC0C0C0#Koneksi baik, ini adalah sinar kemenangan! V#C0x5B545B#\n#F10#\n#F40#Victini memanggil 3 meteor yang membara untuk menyerang satu target musuh, setiap meteor memberikan #C0x3D8A99#60% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*24)$\'s #C0xF13B54# Kerusakan Magis #C0x5B545B#, dan sekaligus memberikan efek terbakar pada setiap target selama 2 giliran. Untuk setiap target tambahan yang diserang, Kerusakan Magis dan kecepatan meningkat 10% (bisa bertumpuk hingga 3 kali), berlaku selama 2 giliran.',
		zawakeEffectDesc_ph = '#C0xC0C0C0#Magandang koneksyon, ito ang sinag ng tagumpay! V#C0x5B545B#\n#F10#\n#F40#Victini ay nanawagan ng 3 naglalagablab na meteor upang atakihin ang isang kalaban na target, bawat meteor ay nagdudulot ng #C0x3D8A99#60% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$\'s #C0xF13B54# Magical Damage #C0x5B545B#, at kasabay nito ay naglalapat ng burn effect sa bawat target sa loob ng 2 turn. Para sa bawat karagdagang target na tinamaan, tumataas ang Magical Damage at bilis ng 10% (maaring mag-stack hanggang 3 layers), tumatagal ng 2 turn.',
		zawakeEffectDesc_ma = '#C0xC0C0C0#Sambungan baik, ini adalah cahaya kemenangan! V#C0x5B545B#\n#F10#\n#F40#Victini memanggil 3 meteor berapi untuk menyerang satu sasaran musuh, setiap meteor menyebabkan #C0x3D8A99#60% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*24)$\'s #C0xF13B54# Kerosakan Magik #C0x5B545B#, dan sekaligus menambah kesan terbakar pada setiap sasaran selama 2 pusingan. Untuk setiap sasaran tambahan yang diserang, Kerosakan Magik dan kelajuan meningkat 10% (boleh bertindih sehingga 3 lapisan), bertahan selama 2 pusingan.',
		zawakeEffectDesc_vn = '#C0xC0C0C0#V Kết nối tốt, đây là tia sáng của chiến thắng! V#C0x5B545B#\n#F10#\n#F40#Victini triệu hồi 3 thiên thạch rực lửa để tấn công một mục tiêu kẻ thù, mỗi thiên thạch gây ra #C0x3D8A99#60% Sát Thương Phép Thuật#C0x5B545B#+$(skillLev el*4*24)$\'s #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, và đồng thời thêm hiệu ứng đốt cháy lên mỗi mục tiêu trong 2 lượt. Với mỗi mục tiêu bổ sung bị tấn công, Sát Thương Phép Thuật và tốc độ tăng thêm 10% (có thể chồng lên 3 lớp), kéo dài trong 2 lượt.',
