	[24612] = {
		id = 24612,
		skillName_vn = 'Sức mạnh trao ban',
		skillName_en = 'Granted Power',
		skillName_th = 'พลังที่มอบให้',
		skillName_in = 'Kekuatan yang Diberikan',
		skillName_ph = 'Ipinagkaloob na Lakas',
		skillName_ma = 'Kuasa yang Diberikan',
		skillName = 'Granted Power',
		describe_vn = '#C0xC0C0C0#V Vâng! Có bạn rồi! V#C0x5B545B#\n#F10#\n#F40#Victini tấn công một mục tiêu ở hàng trước và hàng sau của kẻ địch, gây #C0x3D8A99#90% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel* 4*60)$ của #C0xF13B54# sát thương phép #C0x5B545B# và thêm [Fire Sun Dây] vào nó và gây [Đốt] trong 2 hiệp, và vào trạng thái [Hỏa Linh] cho đến hết vòng tiếp theo\n#F10#\n#F40 #[Yang Yangsuo]: Hiệu ứng khống chế chiếm ưu thế, [Hỏa Linh] sẽ được giải phóng sau khi trạng thái kết thúc hoặc bị gián đoạn\n#F10#\n#F40#[Hỏa Linh]: Trạng thái đặc biệt, không thể hành động, miễn nhiễm sát thương nhưng có thể được thêm vào hiệu ứng (sẽ bị gián đoạn khi bị điều khiển bởi không có khả năng hành động), Nó sẽ cấp 50% khả năng phòng thủ kép cho các đơn vị thân thiện ở hàng trước và 20% khả năng tấn công kép cho các đơn vị thân thiện ngẫu nhiên ở hàng sau (ưu tiên lửa và siêu anh hùng). Nó sẽ phục hồi 150 điểm thịnh nộ của chính mình khi nhận được một đòn tấn công tích cực; sau khi Flame Spirit kết thúc hoặc bị gián đoạn, nó sẽ tự thêm [Áo giáp lửa] vào bản thân trong 2 lượt.',
		describe_en = '#C0xC0C0C0#V Yes! Allies identified! V#C0x5B545B#\n#F10#\n#F40#Victini attacks a target in the front and back rows of the enemy, dealing #C0x3D8A99#90% Magic Damage#C0x5B545B#+$(skillLevel* 4*60)$ magic damage #C0x5B545B# and applies [Fire Sun Chain] inflicting [Burn] for 2 turns, and enters the [Flame Spirit] state until the next turn\n#F10#\n#F40 #[Yang Yangsuo]: Dominant control effect, [Flame Spirit] is released after the state ends or is interrupted\n#F10#\n#F40#[Flame Spirit]: Special state, cannot act, immune to damage but can receive effects (will be interrupted if controlled and unable to act). Grants 50% dual defense to friendly units in the front row and 20% dual attack to random friendly units in the back row (prioritizing fire and superheroes). Restores 150 Rage when receiving an active attack; after Flame Spirit ends or is interrupted, applies [Fire Armor] to self for 2 turns.',
		describe_th = '#C0xC0C0C0#V ใช่! มีเพื่อนร่วมทีมแล้ว! V#C0x5B545B#\n#F10#\n#F40#วิคทินี่โจมตีเป้าหมายในแถวหน้ากับแถวหลังของศัตรู สร้าง #C0x3D8A99#ความเสียหายเวทมนตร์ 90%#C0x5B545B#+$(skillLevel* 4*60)$ ความเสียหายเวทมนตร์ #C0x5B545B# และเพิ่ม [สายไฟแสงอาทิตย์] ทำให้เกิด [การเผาไหม้] เป็นเวลา 2 ตา พร้อมเข้าสู่สถานะ [จิตวิญญาณเพลิง] จนกว่าจะถึงตาถัดไป\n#F10#\n#F40 #[หยาง หยางซัว]: ผลการควบคุมหลัก, [จิตวิญญาณเพลิง] จะถูกปลดปล่อยเมื่อสถานะจบหรือถูกขัดขวาง\n#F10#\n#F40#[จิตวิญญาณเพลิง]: สถานะพิเศษ ไม่สามารถกระทำใดๆ ได้ ดื้อต่อความเสียหายแต่ยังได้รับเอฟเฟกต์ (จะถูกขัดขวางเมื่อถูกควบคุมและไม่สามารถกระทำ) มอบค่าป้องกันคู่ 50% ให้กับมิตรในแถวหน้า และเพิ่มค่าการโจมตีคู่ 20% ให้กับมิตรในแถวหลังแบบสุ่ม (เน้นไฟและฮีโร่) ฟื้นฟูความโกรธ 150 เมื่อได้รับการโจมตีเชิงบวก หลังจากจิตวิญญาณเพลิงสิ้นสุดหรือถูกขัดขวางจะเพิ่ม [เกราะไฟ] ให้กับตนเองเป็นเวลา 2 ตา',
		describe_in = '#C0xC0C0C0#V Ya! Ada teman! V#C0x5B545B#\n#F10#\n#F40#Victini menyerang target di baris depan dan belakang musuh, memberikan #C0x3D8A99#90% Damage Magic#C0x5B545B#+$(skillLevel* 4*60)$ damage magic #C0x5B545B# dan menambahkan [Rantai Matahari Api] yang menyebabkan [Terbakar] selama 2 giliran, dan memasuki status [Roh Api] sampai giliran berikutnya\n#F10#\n#F40 #[Yang Yangsuo]: Efek kontrol dominan, [Roh Api] akan dilepaskan setelah status berakhir atau terganggu\n#F10#\n#F40#[Roh Api]: Status khusus, tidak dapat bertindak, kebal terhadap damage tetapi masih dapat menerima efek (akan terganggu bila dikontrol dan tidak bisa bertindak). Memberikan 50% pertahanan ganda ke unit bersahabat di baris depan dan 20% serangan ganda ke unit bersahabat acak di baris belakang (prioritaskan api dan pahlawan). Memulihkan 150 Kemarahan saat menerima serangan aktif; setelah Roh Api berakhir atau terganggu, memberikan [Armor Api] pada diri sendiri selama 2 giliran.',
		describe_ph = '#C0xC0C0C0#V Oo! May kaibigan na! V#C0x5B545B#\n#F10#\n#F40#Umunlad si Victini sa isang target sa harap at likod na hilera ng kalaban, na nagdudulot ng #C0x3D8A99#90% Magic Damage#C0x5B545B#+$(skillLevel* 4*60)$ magic damage #C0x5B545B# at nagpapatong ng [Fire Sun Chain] na nagdudulot ng [Burn] sa loob ng 2 mga turn, at pumapasok sa estado ng [Flame Spirit] hanggang sa susunod na turn\n#F10#\n#F40 #[Yang Yangsuo]: Dominant control effect, ang [Flame Spirit] ay mapapalaya pagkatapos magtapos o maistorbo ang estado\n#F10#\n#F40#[Flame Spirit]: Espesyal na estado, hindi makakilos, immune sa damage ngunit maaari pa ring makatanggap ng mga epekto (maaaring maistorbo kapag kontrolado at hindi makakilos). Nagbibigay ng 50% dual defense sa mga kaalyadong yunit sa harap na hilera at 20% dual attack sa random na alyadong yunit sa likod na hilera (binibigyang prayoridad ang apoy at mga superhero). Nagpapagaling ng 150 Rage kapag tumatanggap ng aktibong atake; pagkatapos magtapos o maistorbo ang Flame Spirit, ilalagay ang [Fire Armor] sa sarili para sa 2 mga turn.',
		describe_ma = '#C0xC0C0C0#V Ya! Ada rakan! V#C0x5B545B#\n#F10#\n#F40#Victini menyerang sasaran di barisan depan dan belakang musuh, menyebabkan #C0x3D8A99#90% Kerosakan Sihir#C0x5B545B#+$(skillLevel* 4*60)$ kerosakan sihir #C0x5B545B# dan menambah [Rantai Matahari Api] yang menyebabkan [Terbakar] selama 2 pusingan, serta memasuki keadaan [Semangat Api] sehingga pusingan seterusnya\n#F10#\n#F40 #[Yang Yangsuo]: Kesan kawalan dominan, [Semangat Api] akan dilepaskan selepas keadaan berakhir atau terganggu\n#F10#\n#F40#[Semangat Api]: Keadaan khas, tidak boleh bertindak, kebal kepada kerosakan tetapi boleh menerima kesan (akan terganggu jika dikawal dan tidak boleh bertindak). Memberikan 50% pertahanan berganda kepada unit mesra di barisan depan dan 20% serangan berganda kepada unit mesra secara rawak di barisan belakang (utamakan api dan wira super). Memulihkan 150 Keberanian apabila menerima serangan aktif; selepas Semangat Api berakhir atau terganggu, menambah [Perisai Api] pada diri sendiri selama 2 pusingan.',
		describe = '#C0xC0C0C0#V Yes! Allies identified! V#C0x5B545B#\n#F10#\n#F40#Victini attacks a target in the front and back rows of the enemy, dealing #C0x3D8A99#90% Magic Damage#C0x5B545B#+$(skillLevel* 4*60)$ magic damage #C0x5B545B# and applies [Fire Sun Chain] inflicting [Burn] for 2 turns, and enters the [Flame Spirit] state until the next turn\n#F10#\n#F40 #[Yang Yangsuo]: Dominant control effect, [Flame Spirit] is released after the state ends or is interrupted\n#F10#\n#F40#[Flame Spirit]: Special state, cannot act, immune to damage but can receive effects (will be interrupted if controlled and unable to act). Grants 50% dual defense to friendly units in the front row and 20% dual attack to random friendly units in the back row (prioritizing fire and superheroes). Restores 150 Rage when receiving an active attack; after Flame Spirit ends or is interrupted, applies [Fire Armor] to self for 2 turns.',
		zawakeEffect = __data_t__zawakeEffect[24612],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#V Yes! There is a friend! V#C0x5B545B#\n#F10#\n#F40#Victini attacks one target in the front and back rows of the enemy, dealing #C0x3D8A99#90% Magic Damage#C0x5B545B#+$(skill lLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B# and adding <Yang Yang Quấn> to it and causing <Burn> for 2 rounds, and entering the <Flame Spirit> state until the end of the next round \n#F20# \n#F40#<Yang Yang Suo>: Dominant control effect, it will be released after the <Flame Spirit> state ends or is interrupted \n#F20# \n#F40#<Flame Spirit>: Special state, cannot move, immune to damage but can be added with effects (will be interrupted) when controlled by unable to move) and provides 50% of its own double defense to allied units in the front row and 20% of its double attack to random allied units in the back row (priority fire, super), receiving positive attacks will restore 150 anger points to itself. In the Flame Spirit state, receiving skill damage will increase its own speed by 10% (stackable up to 3 times), and add a burning effect to the attacker for 2 turns; after Flame Spirit ends or is interrupted, it will add <Fire Armor> to itself for 2 turns.',
		zawakeEffectDesc_en = '#C0xC0C0C0#V Yes! There is a friend! V#C0x5B545B#\n#F10#\n#F40#Victini attacks one target in the front and back rows of the enemy, dealing #C0x3D8A99#90% Magic Damage#C0x5B545B#+$(skill lLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B# and adding <Yang Yang Quấn> to it and causing <Burn> for 2 rounds, and entering the <Flame Spirit> state until the end of the next round \n#F20# \n#F40#<Yang Yang Suo>: Dominant control effect, it will be released after the <Flame Spirit> state ends or is interrupted \n#F20# \n#F40#<Flame Spirit>: Special state, cannot move, immune to damage but can be added with effects (will be interrupted) when controlled by unable to move) and provides 50% of its own double defense to allied units in the front row and 20% of its double attack to random allied units in the back row (priority fire, super), receiving positive attacks will restore 150 anger points to itself. In the Flame Spirit state, receiving skill damage will increase its own speed by 10% (stackable up to 3 times), and add a burning effect to the attacker for 2 turns; after Flame Spirit ends or is interrupted, it will add <Fire Armor> to itself for 2 turns.',
		zawakeEffectDesc_th = '#C0xC0C0C0#V ใช่! มีเพื่อนแล้ว! V#C0x5B545B#\n#F10#\n#F40#Victini โจมตีเป้าหมายหนึ่งตัวในแถวหน้าหลังของศัตรู สร้างความเสียหาย #C0x3D8A99#90% ความเสียหายเวทมนตร์#C0x5B545B#+$(skill lLevel*4*60)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# และเพิ่ม <Yang Yang Quấn> เข้าไปพร้อมกับทำให้เกิด <การเผาไหม้> เป็นเวลา 2 เทิร์น และเข้าสู่สถานะ <วิญญาณไฟ> จนกว่าจะสิ้นสุดเทิร์นถัดไป \n#F20# \n#F40#<Yang Yang Suo>: เอฟเฟกต์ควบคุมที่เด่นชัด จะปลดปล่อยหลังจากสถานะ <วิญญาณไฟ> สิ้นสุดหรือถูกขัดจังหวะ \n#F20# \n#F40#<วิญญาณไฟ>: สถานะพิเศษ ไม่สามารถเคลื่อนที่ได้ ป้องกันความเสียหายแต่สามารถถูกเพิ่มเอฟเฟกต์ (จะถูกขัดจังหวะ) เมื่อถูกควบคุมไม่ให้เคลื่อนที่ และมอบค่าป้องกันคู่ 50% ของตนเองให้กับพันธมิตรในแถวหน้า และมอบค่าการโจมตีคู่ 20% ให้กับพันธมิตรแบบสุ่มในแถวหลัง (เน้นไฟ, ซูเปอร์) การได้รับการโจมตีเชิงบวกจะฟื้นฟูความโกรธให้ตัวเอง 150 คะแนน ในสถานะวิญญาณไฟ การได้รับความเสียหายจากสกิลจะเพิ่มความเร็วตัวเอง 10% (สะสมได้ 3 ครั้ง) และเพิ่มเอฟเฟกต์เผาไหม้ให้กับผู้โจมตีเป็นเวลา 2 เทิร์น; หลังจากสถานะวิญญาณไฟสิ้นสุดหรือถูกขัดจังหวะ จะเพิ่ม <เกราะไฟ> ให้กับตัวเองเป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = '#C0xC0C0C0#V Ya! Ada teman! V#C0x5B545B#\n#F10#\n#F40#Victini menyerang satu target di baris depan dan belakang musuh, memberikan #C0x3D8A99#90% Kerusakan Sihir#C0x5B545B#+$(skill lLevel*4*60)$#C0xF13B54# kerusakan sihir#C0x5B545B# dan menambahkan <Yang Yang Quấn> ke dalamnya serta menyebabkan <Terbakar> selama 2 giliran, dan masuk ke status <Roh Api> hingga akhir giliran berikutnya \n#F20# \n#F40#<Yang Yang Suo>: Efek kontrol dominan, akan dilepaskan setelah status <Roh Api> berakhir atau terganggu \n#F20# \n#F40#<Roh Api>: Status khusus, tidak dapat bergerak, kebal terhadap kerusakan tetapi dapat ditambahkan efek (akan terganggu) saat dikontrol tidak bisa bergerak) dan memberikan 50% pertahanan ganda miliknya untuk unit sekutu di baris depan dan 20% serangan gandanya untuk unit sekutu acak di baris belakang (prioritas api, super), menerima serangan positif akan memulihkan 150 poin amarah untuk dirinya sendiri. Dalam status Roh Api, menerima kerusakan skill akan meningkatkan kecepatan dirinya sebesar 10% (dapat bertumpuk hingga 3 kali), sekaligus menambahkan efek terbakar pada penyerang selama 2 giliran; setelah Roh Api berakhir atau terganggu, itu akan menambahkan <Baju Zirah Api> pada dirinya sendiri selama 2 giliran.',
		zawakeEffectDesc_ph = '#C0xC0C0C0#V Oo! May kasama na! V#C0x5B545B#\n#F10#\n#F40#Inaatake ni Victini ang isang target sa harap at likurang hanay ng kaaway, nagdudulot ng #C0x3D8A99#90% Magic Damage#C0x5B545B#+$(skill lLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B# at idinadagdag ang <Yang Yang Quấn> dito at nagdudulot ng <Sunog> sa loob ng 2 turn, at pumapasok sa estado ng <Flame Spirit> hanggang matapos ang susunod na turn \n#F20# \n#F40#<Yang Yang Suo>: Dominant control effect, ilalabas ito pagkatapos matapos o ma-interrupt ang estado ng <Flame Spirit> \n#F20# \n#F40#<Flame Spirit>: Espesyal na estado, hindi makagalaw, immune sa pinsala ngunit maaaring madagdagan ng mga epekto (maaaaring ma-interrupt) kapag kinontrol na hindi makagalaw) at nagbibigay ng 50% ng sariling doble depensa sa mga kasangga sa harap na hanay at 20% ng doble opensiba nito sa mga kasangga sa likurang hanay nang random (prayoridad apoy, super), ang pagtanggap ng positibong opensiba ay magpapatunay ng 150 galit na puntos sa sarili. Sa estado ng Flame Spirit, ang pagtanggap ng skill damage ay magpapataas ng bilis ng sarili ng 10% (puwedeng ma-stacking ng 3 beses), habang nadaragdagan ang epekto ng sunog sa attacker sa loob ng 2 turn; pagkatapos matapos o ma-interrupt ang Flame Spirit, idadagdag nito ang <Fire Armor> sa sarili sa loob ng 2 turn.',
		zawakeEffectDesc_ma = '#C0xC0C0C0#V Ya! Ada kawan! V#C0x5B545B#\n#F10#\n#F40#Victini menyerang satu sasaran di barisan hadapan dan belakang musuh, menyebabkan #C0x3D8A99#90% Kerosakan Magik#C0x5B545B#+$(skill lLevel*4*60)$#C0xF13B54# kerosakan magik#C0x5B545B# dan menambahkan <Yang Yang Quấn> serta menyebabkan <Terbakar> selama 2 pusingan, dan memasuki keadaan <Roh Api> sehingga tamat pusingan berikutnya \n#F20# \n#F40#<Yang Yang Suo>: Kesan kawalan dominan, ia akan dilepaskan selepas keadaan <Roh Api> tamat atau terganggu \n#F20# \n#F40#<Roh Api>: Keadaan khas, tidak boleh bergerak, kebal terhadap kerosakan tetapi boleh ditambah kesan (akan terganggu) apabila dikawal tidak boleh bergerak) dan memberikan 50% pertahanan berganda dirinya kepada unit sekutu di barisan hadapan dan 20% serangan bergandanya kepada unit sekutu rawak di barisan belakang (keutamaan api, super), menerima serangan positif akan memulihkan 150 mata kemarahan untuk dirinya sendiri. Dalam keadaan Roh Api, menerima kerosakan kemahiran akan meningkatkan kelajuan dirinya sebanyak 10% (boleh bertindih sehingga 3 kali), serta menambah kesan terbakar kepada penyerang selama 2 pusingan; selepas Roh Api tamat atau terganggu, ia akan menambah <Baju Perisai Api> pada dirinya sendiri selama 2 pusingan.',
		zawakeEffectDesc_vn = '#C0xC0C0C0#V Vâng! Có bạn rồi! V#C0x5B545B#\n#F10#\n#F40#Victini tấn công một mục tiêu ở hàng trước và hàng sau của kẻ địch, gây #C0x3D8A99#90% Sát Thương Phép Thuật#C0x5B545B#+$(skill lLevel*4*60)$#C0xF13B54#sát thương phép#C0x5B545B# và thêm <Yang Yang Quấn> vào nó và gây <Đốt> trong 2 hiệp, và vào trạng thái <Hỏa Linh> cho đến hết hiệp tiếp theo \n#F20# \n#F40#<Yang Yang Suo>: Hiệu ứng khống chế chiếm ưu thế, nó sẽ được giải phóng sau khi trạng thái <Hỏa Linh> kết thúc hoặc bị gián đoạn \n#F20# \n#F40#<Hỏa Linh>: Trạng thái đặc biệt, không thể di chuyển, miễn nhiễm sát thương nhưng có thể được thêm vào hiệu ứng (sẽ bị gián đoạn) khi bị điều khiển bởi không thể di chuyển) và cung cấp 50% khả năng phòng thủ kép của chính mình cho các đơn vị đồng minh ở hàng trước và 20% đòn tấn công kép của nó cho các đơn vị đồng minh ngẫu nhiên ở hàng sau (ưu tiên lửa, siêu), nhận các đòn tấn công tích cực sẽ khôi phục 150 điểm tức giận cho chính nó. Ở trạng thái Hỏa Linh, nhận sát thương kỹ năng sẽ tăng 10% tốc độ của bản thân (có thể cộng dồn 3 lần), đồng thời thêm hiệu ứng đốt cháy cho kẻ tấn công trong 2 lượt; sau khi Flame Spirit kết thúc hoặc bị gián đoạn, nó sẽ tự thêm <Áo giáp lửa> vào bản thân trong 2 lượt.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'While in Spirit Flame state, taking skill damage increases your Speed by 10% (stackable up to 3 times), and inflicts Burn on the attacker for 2 turns.',
		zawakeSimpleDesc_en = 'While in Spirit Flame state, taking skill damage increases your Speed by 10% (stackable up to 3 times), and inflicts Burn on the attacker for 2 turns.',
		zawakeSimpleDesc_th = 'ในสถานะเปลวเพลิงวิญญาณ การโดนสกิลจะเพิ่มความเร็ว 10% (สะสมได้สูงสุด 3 ครั้ง) และเผาไหม้ผู้โจมตีกลับเป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Saat dalam mode Jiwa Api, menerima damage skill meningkatkan Kecepatan 10% (maksimal 3 kali) dan menyebabkan pembakar pada penyerang selama 2 giliran',
		zawakeSimpleDesc_ph = 'Habang nasa Flame Spirit mode, tuwing tatamaan ng skill, tataas ang Speed mo ng 10% (stack hanggang 3x) at masusunog ang kalaban ng 2 turn',
		zawakeSimpleDesc_ma = 'Dalam keadaan Roh Api, apabila menerima kerosakan kemahiran, Kelajuan meningkat 10% (boleh digandakan sehingga 3 kali), dan menyebabkan penyerang Terbakar selama 2 giliran',
		zawakeSimpleDesc_vn = 'Khi ở trạng thái Linh hồn ngọn lửa, nhận sát thương kỹ năng sẽ tăng tốc độ của bạn thêm 10% (có thể cộng dồn tối đa 3 lần) và gây hiệu ứng thiêu đốt cho kẻ tấn công trong 2 lượt.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 1,
		skillDamageType = 1,
		skillNatureType = 11,
		cdRound = 2,
		posChoose = 1,
		targetTypeDesc = 'Single targets at the front and back of the enemy',
		targetTypeDesc_vn = 'Mục tiêu đơn lẻ phía trước và phía sau của địch',
		targetTypeDesc_en = 'Single targets at the front and back of the enemy',
		targetTypeDesc_th = 'เป้าหมายเดี่ยวที่ด้านหน้าและด้านหลังของศัตรู',
		targetTypeDesc_in = 'Target tunggal di bagian depan dan belakang musuh',
		targetTypeDesc_ph = 'Isang target sa unahan at likuran ng kalaban',
		targetTypeDesc_ma = 'Sasaran tunggal di bahagian depan dan belakang musuh',
		damageFormula = 'self:specialDamage()*0.9+(self:flag(99) and skillLevel or skillLevel*4)*60',
		skillProcess = {246121, 246122, 246123, 246124, 246125, 246126, 246127},
		recoverMp1 = 480,
