	},
	[24613] = {
		id = 24613,
		skillName_vn = 'V Ngọn Lửa Nóng',
		skillName_en = 'Hot Flame',
		skillName_th = 'เปลวไฟร้อน',
		skillName_in = 'Api Panas',
		skillName_ph = 'Mainit na Apoy',
		skillName_ma = 'Api Panas',
		skillName = 'Hot Flame',
		describe_vn = '#C0xC0C0C0#V Chiến thắng! V#C0x5B545B#\n#F10#\n#F40#Victini tấn công tất cả mục tiêu địch, gây #C0x3D8A99#200% sát thương phép#C0x5B545B#+$(skillLevel *4*24)$\'s #C0xF13B54# sát thương phép #C0x5B545B#, đồng thời thêm 1 lớp đốt trong 2 hiệp (đốt cháy: hiệu ứng tiêu cực, mục tiêu mất 40% sát thương phép cộng thêm của Sát Thương Phép Thuật của Victini trước mỗi vòng) và trở thành một người bạn Thêm [Áo giáp lửa] cho tất cả các đơn vị ở bên trong 2 lượt\n#F10#\n#F40#[Áo giáp lửa]: Giới hạn sinh mệnh ban đầu tăng thêm 10% (gấp đôi đối với tướng lửa), 30% sát thương tấn công chủ động sẽ được phản ánh lên kẻ địch và 10% (gấp đôi đối với tướng lửa) sẽ được chuyển thành Phục hồi, vô hiệu khi tổng sát thương phản công vượt quá 25% giới hạn máu trên của Victini (giới hạn thất bại trên đối với các anh hùng hệ lửa tăng gấp đôi). Khi áo giáp lửa kết thúc hoặc hết hạn, anh hùng lửa sẽ hồi phục 20% lượng máu từ giới hạn máu trên của Victini và tăng 15% đòn chí mạng và sát thương chí mạng (1 hiệp)',
		describe_en = 'Victory! Victini attacks all enemy targets, dealing 200% magic damage +$(skillLevel *4*24)$\'s magic damage, and applies 1 layer of burn for 2 turns (Burn: a negative effect causing the target to lose 40% of Victini\'s additional magic damage before each round) and becomes an ally. Adds [Flame Armor] to all units inside for 2 rounds. [Flame Armor]: Increases maximum HP by 10% (doubled for fire heroes), reflects 30% of active attack damage back to enemies, and converts 10% (doubled for fire heroes) into healing. This is invalidated if total counterattack damage exceeds 25% of Victini\'s max HP (failure limit for fire heroes doubled). When Flame Armor ends or expires, fire heroes heal 20% of Victini\'s max HP and gain 15% critical hit rate and critical damage for 1 turn.',
		describe_th = 'ชัยชนะ! Victini โจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวทมนตร์ 200% +$(skillLevel *4*24)$ ความเสียหายเวทมนตร์ และเพิ่มสถานะเบิร์น 1 ชั้นเป็นเวลา 2 เทิร์น (เบิร์น: สถานะลบ เป้าหมายจะเสียความเสียหายเวทสะสม 40% ของ Victini ก่อนแต่ละรอบ) และกลายเป็นพันธมิตร เพิ่ม [ชุดเกราะเพลิง] ให้กับยูนิตทั้งหมดภายใน 2 รอบ [ชุดเกราะเพลิง]: เพิ่มพลังชีวิตสูงสุด 10% (เพิ่มเป็นสองเท่าสำหรับฮีโร่ธาตุไฟ), สะท้อนความเสียหายโจมตีแบบแอคทีฟ 30% กลับไปยังศัตรู และแปลง 10% (เพิ่มเป็นสองเท่าสำหรับฮีโร่ธาตุไฟ) เป็นการฟื้นฟู เมื่อความเสียหายสะท้อนรวมเกิน 25% ของพลังชีวิตสูงสุดของ Victini จะไม่สามารถใช้ได้ (ขีดจำกัดสำหรับฮีโร่ธาตุไฟเพิ่มเป็นสองเท่า) เมื่อตอนชุดเกราะเพลิงสิ้นสุดหรือหมดเวลา ฮีโร่ธาตุไฟจะฟื้นฟู 20% ของพลังชีวิตสูงสุดของ Victini และได้รับโบนัสอัตราคริติคอลและความเสียหายคริติคอล 15% เป็นเวลา 1 เทิร์น',
		describe_in = 'Kemenangan! Victini menyerang semua target musuh, memberikan 200% kerusakan sihir +$(skillLevel *4*24)$ kerusakan sihir, dan menambahkan 1 lapis terbakar selama 2 giliran (Terbakar: efek negatif, target kehilangan 40% tambahan kerusakan sihir dari Victini sebelum setiap giliran) serta menjadi rekan. Menambahkan [Baja Api] untuk semua unit di dalam selama 2 giliran. [Baja Api]: Meningkatkan batas HP awal sebesar 10% (ganda untuk pahlawan api), memantulkan 30% kerusakan serangan aktif ke musuh, dan mengubah 10% (ganda untuk pahlawan api) menjadi penyembuhan. Efek ini tidak berlaku jika total kerusakan pantulan melebihi 25% batas HP maksimal Victini (batas gagal untuk pahlawan api dua kali lipat). Ketika Baja Api berakhir atau habis, pahlawan api akan memulihkan 20% HP berdasarkan batas HP maksimal Victini dan mendapatkan peningkatan 15% kritikal dan kerusakan kritikal selama 1 giliran.',
		describe_ph = 'Tagumpay! Inaatake ni Victini ang lahat ng mga kalabang target, nagdudulot ng 200% magic damage +$(skillLevel *4*24)$ na magic damage, at nagdaragdag ng 1 layer ng burn sa loob ng 2 round (Burn: negatibong epekto, nawawala ang target ng 40% dagdag na magic damage ng Victini bago ang bawat round) at nagiging kaalyado. Nagdadagdag ng [Flaming Armor] sa lahat ng yunit sa loob ng 2 round. [Flaming Armor]: Pinapataas ang maksimum na HP ng 10% (doble para sa mga fire heroes), nirereflect ang 30% ng aktibong damage pabalik sa mga kalaban, at 10% (doble para sa mga fire heroes) ay nagiging recovery. Hindi epektibo kapag lumampas ang kabuuang reflected damage ng 25% ng max HP ni Victini (doble ang failure limit para sa mga fire heroes). Kapag natapos o nag-expire ang Flaming Armor, nagpapagaling ang fire heroes ng 20% ng max HP ni Victini at tumatanggap ng dagdag na 15% critical rate at critical damage sa loob ng 1 round.',
		describe_ma = 'Kemenangan! Victini menyerang semua sasaran musuh, menyebabkan 200% kerosakan magik +$(skillLevel *4*24)$ kerosakan magik dan menambah 1 lapisan terbakar selama 2 giliran (Terbakar: kesan negatif, sasaran kehilangan 40% kerosakan magik tambahan daripada Victini sebelum setiap pusingan) dan menjadi sekutu. Menambah [Zirah Api] kepada semua unit di dalamnya selama 2 pusingan. [Zirah Api]: Menambah had nyawa awal sebanyak 10% (berganda untuk wira api), memantulkan 30% kerosakan serangan aktif kepada musuh dan menukar 10% (berganda untuk wira api) menjadi Pemulihan. Tidak berkesan apabila jumlah kerosakan balas melebihi 25% had darah maksimum Victini (had kegagalan untuk wira api berganda). Apabila Zirah Api tamat atau luput, wira api akan memulihkan 20% daripada jumlah darah maksima Victini dan mendapat peningkatan 15% kadar kritikal dan kerosakan kritikal selama 1 pusingan.',
		describe = 'Victory! Victini attacks all enemy targets, dealing 200% magic damage +$(skillLevel *4*24)$\'s magic damage, and applies 1 layer of burn for 2 turns (Burn: a negative effect causing the target to lose 40% of Victini\'s additional magic damage before each round) and becomes an ally. Adds [Flame Armor] to all units inside for 2 rounds. [Flame Armor]: Increases maximum HP by 10% (doubled for fire heroes), reflects 30% of active attack damage back to enemies, and converts 10% (doubled for fire heroes) into healing. This is invalidated if total counterattack damage exceeds 25% of Victini\'s max HP (failure limit for fire heroes doubled). When Flame Armor ends or expires, fire heroes heal 20% of Victini\'s max HP and gain 15% critical hit rate and critical damage for 1 turn.',
		starEffect = __data_t__starEffect[24613],
		-- {11}
		starEffectDesc_vn = '<Xung Phong Chiến Thắng> ：Gây hiệu ứng Hỏa hệ dễ tổn thương và thiêu đốt nộ khí của một tướng địch có nộ khí cao nhất, ngay lập tức lệnh cho tất cả tướng Hỏa hệ phe ta tấn công mục tiêu một lần (nếu đầy nộ khí có thể sử dụng kỹ năng tất sát).',
		starEffectDesc = '<Charge Victory>: Inflicts Fire vulnerability effect and burns the Fury of the enemy general with the highest Fury. Immediately commands all allied Fire faction generals to attack the target once (if Fury is full, can use the finishing skill).',
		starEffectDesc_en = '<Charge Victory>: Inflicts Fire vulnerability effect and burns the Fury of the enemy general with the highest Fury. Immediately commands all allied Fire faction generals to attack the target once (if Fury is full, can use the finishing skill).',
		starEffectDesc_th = '<Xung Phong Chiến Thắng>: ทำให้เกิดเอฟเฟกต์ไวไฟและเผาโกรธของแม่ทัพฝ่ายศัตรูที่มีโกรธสูงสุด สั่งให้แม่ทัพฝ่ายไฟของเราโจมตีเป้าหมายหนึ่งครั้งทันที (ถ้ามีโกรธเต็มสามารถใช้สกิลสังหารได้)',
		starEffectDesc_in = '<Charge Victory>: Memberikan efek kerentanan Api dan membakar Kemarahan pada jenderal musuh dengan Kemarahan tertinggi, segera memerintahkan semua jenderal fraksi Api kita untuk menyerang target sekali (jika Kemarahan penuh dapat menggunakan skill pembunuhan).',
		starEffectDesc_ph = '<Charge Victory>: Nagdudulot ng epekto ng pagiging mahina sa Apoy at sinusunog ang Galit ng kalaban na heneral na may pinakamataas na Galit, agad iniutos sa lahat ng heneral ng Apoy ng ating panig na atakihin ang target nang isang beses (kung puno ang Galit, maaaring gamitin ang finishing skill).',
		starEffectDesc_ma = '<Charge Victory>: Menimbulkan kesan kerentanan Api dan membakar Kemarahan jeneral musuh yang mempunyai Kemarahan tertinggi, serta segera mengarahkan semua jeneral pihak Api kita menyerang sasaran sekali (jika Kemarahan penuh boleh menggunakan kemahiran pembunuhan).',
		zawakeEffect = __data_t__zawakeEffect[24613],
		-- {79003}
		zawakeEffectDesc = '#C0xC0C0C0#V Victory! V#C0x5B545B#\n#F10#\n#F40#Victini attacks all enemy targets, dealing #C0x3D8A99#200% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# magic damage #C0x5B545B#, and applies 1 burn stack for 2 turns (burn: negative effect, target loses 40% additional magical damage of Victini\'s Magical Damage before each round) and adds <Flame Armor> to all allied units for 2 turns \n#F20# \n#F40#<Flame Armor>: Initially increases maximum HP by 10% (doubles for fire heroes), 30% of active attack damage will be reflected to enemies, 10% (doubles for fire heroes) will be converted to healing and expires when total counter damage exceeds 25% of Victini\'s HP (fire hero fail limit doubles), when Flame Armor is destroyed or nullified, fire heroes will restore 20% of Victini\'s HP and gain 15% critical hit and critical damage (1 round). When the <Flame Armor> duo covered by fire heroes expires, it deals 40% magical damage of Victini to all enemy targets; <Victory> burns all buffs of the target.',
		zawakeEffectDesc_en = '#C0xC0C0C0#V Victory! V#C0x5B545B#\n#F10#\n#F40#Victini attacks all enemy targets, dealing #C0x3D8A99#200% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# magic damage #C0x5B545B#, and applies 1 burn stack for 2 turns (burn: negative effect, target loses 40% additional magical damage of Victini\'s Magical Damage before each round) and adds <Flame Armor> to all allied units for 2 turns \n#F20# \n#F40#<Flame Armor>: Initially increases maximum HP by 10% (doubles for fire heroes), 30% of active attack damage will be reflected to enemies, 10% (doubles for fire heroes) will be converted to healing and expires when total counter damage exceeds 25% of Victini\'s HP (fire hero fail limit doubles), when Flame Armor is destroyed or nullified, fire heroes will restore 20% of Victini\'s HP and gain 15% critical hit and critical damage (1 round). When the <Flame Armor> duo covered by fire heroes expires, it deals 40% magical damage of Victini to all enemy targets; <Victory> burns all buffs of the target.',
		zawakeEffectDesc_th = '#C0xC0C0C0#V ชัยชนะ! V#C0x5B545B#\n#F10#\n#F40#Victini โจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวทมนตร์ #C0x3D8A99#200%#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# พร้อมทั้งเพิ่มสถานะไฟลวก 1 ชั้นเป็นเวลา 2 เทิร์น (ไฟลวก: ผลเสีย เป้าหมายเสียความเสียหายเวทเพิ่มขึ้น 40% จากความเสียหายเวทของ Victini ก่อนแต่ละรอบ) และเพิ่ม <เกราะไฟ> ให้กับหน่วยพันธมิตรทั้งหมดเป็นเวลา 2 เทิร์น \n#F20# \n#F40#<เกราะไฟ>: เพิ่มพลังชีวิตสูงสุดเริ่มต้น 10% (เพิ่มเป็นสองเท่าสำหรับฮีโร่ธาตุไฟ), โจมตีเชิงรุก 30% จะสะท้อนกลับไปยังศัตรู, 10% (เพิ่มเป็นสองเท่าสำหรับฮีโร่ธาตุไฟ) จะถูกแปลงเป็นการฟื้นฟู และหมดอายุเมื่อความเสียหายสะท้อนรวมเกิน 25% ของพลังชีวิต Victini (ข้อจำกัดความล้มเหลวของฮีโร่ธาตุไฟเพิ่มเป็นสองเท่า), เมื่อเกราะไฟถูกทำลายหรือลบล้าง ฮีโร่ธาตุไฟจะฟื้นฟู HP ของ Victini 20% และเพิ่มความแรงวิธีวิจารณ์และความเสียหายวิธีวิจารณ์ 15% (1 เทิร์น) เมื่อคู่มือ <เกราะไฟ> ที่ฮีโร่ธาตุไฟปกคลุมหมดอายุ มันจะสร้างความเสียหายเวท 40% ของ Victini แก่ศัตรูทั้งหมด; <ชัยชนะ> จะเผาทำลายบัฟทั้งหมดของเป้าหมาย',
		zawakeEffectDesc_in = '#C0xC0C0C0#V Kemenangan! V#C0x5B545B#\n#F10#\n#F40#Victini menyerang semua target musuh, memberikan #C0x3D8A99#200% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# kerusakan magis #C0x5B545B#, sekaligus menambahkan 1 lapisan terbakar selama 2 giliran (terbakar: efek negatif, target kehilangan 40% tambahan kerusakan magis dari Kerusakan Magis Victini sebelum setiap giliran) dan menambahkan <Baju Zirah Api> ke semua unit sekutu selama 2 giliran \n#F20# \n#F40#<Baju Zirah Api>: Menambah maksimal HP awal sebesar 10% (dua kali lipat untuk pahlawan api), 30% kerusakan serangan aktif akan dipantulkan ke musuh, 10% (dua kali lipat untuk pahlawan api) akan diubah menjadi penyembuhan dan akan berakhir ketika total kerusakan pantulan melebihi 25% batas HP Victini (batas kegagalan pahlawan api meningkat dua kali lipat), saat baju zirah api hancur atau dinonaktifkan, pahlawan api akan memulihkan 20% HP Victini dan meningkatkan kritis dan kerusakan kritis sebesar 15% (1 giliran). Saat duo <Baju Zirah Api> yang ditutupi oleh pahlawan api berakhir, akan menyebabkan 40% kerusakan magis Victini ke semua target musuh; <Kemenangan> akan membakar semua buff dari target.',
		zawakeEffectDesc_ph = '#C0xC0C0C0#V Tagumpay! V#C0x5B545B#\n#F10#\n#F40#Atake ni Victini ang lahat ng kalabang target, na nagdudulot ng #C0x3D8A99#200% Damage na Mahiwaga#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# mahiwagang pinsala #C0x5B545B#, at naglalagay ng 1 burn stack sa loob ng 2 turns (burn: negatibong epekto, nawawala ng target ang 40% dagdag na mahiwagang pinsala mula sa Magical Damage ni Victini bago ang bawat round) at nagdadagdag ng <Baluti ng Apoy> sa lahat ng kakampi sa loob ng 2 turns \n#F20# \n#F40#<Baluti ng Apoy>: Pinapataas ang maximum HP ng simula ng 10% (doble para sa fire heroes), 30% ng aktibong pinsala sa atake ay maire-reflect sa mga kalaban, 10% (doble para sa fire heroes) ay magiging paggaling at mag-e-expire kapag lumampas ang total counter damage ng 25% ng HP ng Victini (doble ang faillimit ng fire hero), kapag nasira o nabu-buff ang Baluti ng Apoy, magre-recover ang fire hero ng 20% HP ni Victini at tataas ng 15% ang critical hit at critical damage (1 round). Kapag nag-expire ang <Baluti ng Apoy> na sakop ng fire hero, magdudulot ito ng 40% mahiwagang pinsala ni Victini sa lahat ng kalabang target; ang <Tagumpay> ay sisunugin ang lahat ng buffs ng target.',
		zawakeEffectDesc_ma = '#C0xC0C0C0#V Kemenangan! V#C0x5B545B#\n#F10#\n#F40#Victini menyerang semua sasaran musuh, memberikan #C0x3D8A99#200% Kerosakan Magikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# kerosakan magikal #C0x5B545B#, dan menambah 1 lapisan terbakar selama 2 pusingan (terbakar: kesan negatif, sasaran kehilangan 40% kerosakan magikal tambahan dari Kerosakan Magikal Victini sebelum setiap pusingan) dan menambah <Perisai Api> untuk semua unit sekutu selama 2 pusingan \n#F20# \n#F40#<Perisai Api>: Meningkatkan had nyawa maksimum awal sebanyak 10% (berganda untuk wira api), 30% daripada kerosakan serangan aktif akan dipantulkan kepada musuh, 10% (berganda untuk wira api) akan ditukar menjadi pemulihan dan akan tamat apabila jumlah kerosakan pantulan melebihi 25% had nyawa Victini (had kegagalan wira api berganda), apabila Perisai Api musnah atau dihapuskan, wira api akan memulihkan 20% HP Victini dan meningkatkan 15% kritikal dan kerosakan kritikal (1 pusingan). Apabila duo <Perisai Api> yang dilindungi oleh wira api tamat, ia akan memberikan 40% kerosakan magikal Victini kepada semua sasaran musuh; <Kemenangan> akan membakar semua buff sasaran.',
		zawakeEffectDesc_vn = '#C0xC0C0C0#V Chiến thắng! V#C0x5B545B#\n#F10#\n#F40#Victini tấn công tất cả mục tiêu địch, gây #C0x3D8A99#200% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# sát thương phép #C0x5B545B#, đồng thời thêm 1 lớp đốt trong 2 lượt (đốt: hiệu ứng tiêu cực, mục tiêu mất 40% sát thương phép bổ sung của Sát Thương Phép Thuật của Victini trước mỗi vòng) và thêm <Áo giáp lửa> cho tất cả các đơn vị đồng minh trong 2 lượt \n#F20# \n#F40#<Áo giáp lửa>: Giới hạn sinh mệnh ban đầu tăng thêm 10% (gấp đôi đối với tướng lửa), 30% sát thương tấn công chủ động sẽ được phản ánh lên kẻ địch, 10% (gấp đôi đối với tướng lửa) sẽ được chuyển thành hồi phục và sẽ hết hạn khi tổng sát thương phản đòn vượt quá 25% giới hạn máu của Victini (giới hạn thất bại của anh hùng lửa tăng gấp đôi), áo giáp lửa Khi bị phá hủy hoặc vô hiệu, anh hùng lửa sẽ phục hồi 20% HP của Victini và tăng 15% đòn chí mạng và sát thương chí mạng (1 hiệp). Khi bộ đôi <Áo giáp lửa> được anh hùng lửa che phủ hết hạn, nó sẽ gây 40% sát thương phép của Victini lên tất cả mục tiêu kẻ địch; <Chiến thắng> sẽ đốt cháy tất cả bùa lợi của mục tiêu.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '<Victorious Charge> burns all buffs on the target; in Ultimate Skill, when Fire Armor effect is nullified, deals Magic DMG equal to 40% of Victini’s Magic Attack to all enemy targets',
		zawakeSimpleDesc_en = '<Victorious Charge> burns all buffs on the target; in Ultimate Skill, when Fire Armor effect is nullified, deals Magic DMG equal to 40% of Victini’s Magic Attack to all enemy targets',
		zawakeSimpleDesc_th = '<พุ่งชนสู่ชัยชนะ> เผาไหม้บัฟทั้งหมดของเป้าหมาย; ในสกิลอัลติเมต หาก <เกราะไฟ> ถูกยกเลิก จะสร้างความเสียหายเวทเท่ากับ 40% ของพลังเวทของ Victini แก่ศัตรูทุกตัว',
		zawakeSimpleDesc_in = '<Serbu Kemenangan> membakar semua buff target; Dalam skill Ultimate, jika efek <Perisai Api> dinetralkan, berikan damage sihir setara 40% dari Magic Attack Victini ke semua musuh',
		zawakeSimpleDesc_ph = '<Panalo sa Paglusob> sinusunog ang lahat ng buff ng target; Sa Ultimate Skill, kung ma-disable ang <Fire Armor>, magdudulot ng 40% Magic Damage ni Victini sa lahat ng kalaban',
		zawakeSimpleDesc_ma = '<Serangan Menang> membakar semua buff sasaran; Dalam Kemahiran Ultimate, jika kesan <Perisai Api> dinyahaktifkan, berikan 40% kerosakan sihir berdasarkan Serangan Magik Victini kepada semua musuh',
		zawakeSimpleDesc_vn = '<Xung Phong Chiến Thắng> thiêu rụi toàn bộ hiệu ứng tăng cường của mục tiêu; Trong kỹ năng tuyệt chiêu, khi hiệu ứng <Giáp Lửa> của anh hùng hệ Lửa bị vô hiệu hóa, sẽ gây sát thương phép bằng 40% Công Phép của Victini lên toàn bộ mục tiêu phe địch',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 2,
		skillDamageType = 1,
		skillNatureType = 2,
		targetTypeDesc = 'All enemies',
		targetTypeDesc_vn = 'Toàn bộ địch',
		targetTypeDesc_en = 'All enemies',
		targetTypeDesc_th = 'ศัตรูทั้งหมด',
