	[24621] = {
		id = 24621,
		skillName_vn = 'Sao băng lửa',
		skillName_en = 'Fire Meteor',
		skillName_th = 'ดาวตกไฟ',
		skillName_in = 'Meteor Api',
		skillName_ph = 'Pulang Apoy',
		skillName_ma = 'Meteor Api',
		skillName = 'Fire Meteor',
		describe_vn = 'Victini triệu hồi 3 ngôi sao lửa tấn công mục tiêu đơn lẻ của kẻ địch, mỗi ngôi sao gây ra #C0x3D8A99#60% Công Phép#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, mỗi lần tấn công thêm một mục tiêu, Công Phép và tốc độ tăng 10% (tối đa cộng dồn 3 tầng), kéo dài 2 lượt.',
		describe_en = 'Victini summons 3 fire stars to attack a single enemy target. Each star deals #C0x3D8A99#60% Magic Power#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. Each additional target attacked increases Magic Power and Speed by 10% (stacking up to 3 times) for 2 turns.',
		describe_th = 'Victini เรียกดาวไฟ 3 ดวงโจมตีเป้าหมายศัตรูทีละเป้าหมาย ดาวแต่ละดวงสร้างความเสียหายเวทมนตร์ #C0x3D8A99#60% พลังเวทมนตร์#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# การโจมตีแต่ละครั้งต่อเป้าหมายเพิ่มเติมจะเพิ่มพลังเวทและความเร็ว 10% (สะสมได้สูงสุด 3 ชั้น) เป็นเวลา 2 รอบ',
		describe_in = 'Victini memanggil 3 bintang api untuk menyerang satu sasaran musuh. Setiap bintang memberikan #C0x3D8A99#60% Kekuatan Sihir#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Setiap serangan pada sasaran tambahan meningkatkan Kekuatan Sihir dan Kecepatan sebesar 10% (maksimal bertumpuk 3 kali) selama 2 giliran.',
		describe_ph = 'Victini ay nag-summon ng 3 apoy na bituin upang atakihin ang isang target na kalaban. Ang bawat bituin ay nagdudulot ng #C0x3D8A99#60% Lakas ng Magic#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Pinsalang Magic #C0x5B545B#. Sa bawat karagdagang target na inaatake, tumataas ang Lakas ng Magic at Bilis ng 10% (maximum na ma-stack ng 3 beses) sa loob ng 2 turn.',
		describe_ma = 'Victini memanggil 3 bintang api untuk menyerang satu sasaran musuh. Setiap bintang memberikan #C0x3D8A99#60% Kuasa Sihir#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Setiap serangan pada sasaran tambahan meningkatkan Kuasa Sihir dan Kelajuan sebanyak 10% (maksimum bertindih 3 kali) selama 2 pusingan.',
		describe = 'Victini summons 3 fire stars to attack a single enemy target. Each star deals #C0x3D8A99#60% Magic Power#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. Each additional target attacked increases Magic Power and Speed by 10% (stacking up to 3 times) for 2 turns.',
		zawakeEffect = __data_t__zawakeEffect[24621],
		-- {79001}
		zawakeEffectDesc = 'Victini summons 3 fire stars to attack a single enemy target, each star deals 60% Magic Power + $(skillLevel*4*24)$ magic damage, and applies a 2-turn burn effect to each target. Each time it attacks an additional target, Magic Power and speed increase by 10% (max 3 stacks), lasting 2 turns',
		zawakeEffectDesc_en = 'Victini summons 3 fire stars to attack a single enemy target, each star deals 60% Magic Power + $(skillLevel*4*24)$ magic damage, and applies a 2-turn burn effect to each target. Each time it attacks an additional target, Magic Power and speed increase by 10% (max 3 stacks), lasting 2 turns',
		zawakeEffectDesc_th = 'Victini เรียกดาวไฟ 3 ดวงโจมตีเป้าหมายศัตรูเดียว แต่ละดวงสร้างความเสียหายเวท 60% + $(skillLevel*4*24)$ และเพิ่มเอฟเฟกต์เผาไหม้ 2 เทิร์นให้แต่ละเป้าหมาย ทุกครั้งที่โจมตีเป้าหมายเพิ่มเติม พลังเวทและความเร็วเพิ่มขึ้น 10% (สะสมสูงสุด 3 ชั้น) คงอยู่ 2 เทิร์น',
		zawakeEffectDesc_in = 'Victini memanggil 3 bintang api untuk menyerang satu target musuh, setiap bintang memberikan 60% Kekuatan Sihir + $(skillLevel*4*24)$ kerusakan sihir, serta memberikan efek terbakar selama 2 giliran pada setiap target. Setiap kali menyerang target tambahan, Kekuatan Sihir dan kecepatan meningkat 10% (maksimal 3 tumpukan), bertahan selama 2 giliran',
		zawakeEffectDesc_ph = 'Victini ay nagpo-summon ng 3 star ng apoy para atakihin ang isang target na kaaway, bawat star ay nagbibigay ng 60% Magic Power + $(skillLevel*4*24)$ na magic damage, at nagdadagdag ng 2 turn burn effect sa bawat target. Sa bawat karagdagang target na ina-atake, tumaas ang Magic Power at bilis ng 10% (maximum ng 3 stacks), tumatagal ng 2 turn',
		zawakeEffectDesc_ma = 'Victini memanggil 3 bintang api untuk menyerang satu sasaran musuh, setiap bintang memberikan 60% Kuasa Sihir + $(skillLevel*4*24)$ kerosakan sihir, serta menambah kesan terbakar selama 2 pusingan untuk setiap sasaran. Setiap kali menyerang sasaran tambahan, Kuasa Sihir dan kelajuan meningkat 10% (maksimum 3 tumpukan), berlangsung selama 2 pusingan',
		zawakeEffectDesc_vn = 'Victini triệu hồi 3 ngôi sao lửa tấn công mục tiêu đơn lẻ của kẻ địch, mỗi ngôi sao gây 60% Công Phép + $(skillLevel*4*24)$ sát thương phép, đồng thời thêm hiệu ứng đốt cháy 2 lượt cho mỗi mục tiêu, mỗi khi tấn công thêm một mục tiêu, Công Phép và tốc độ tăng 10% (tối đa cộng dồn 3 tầng), kéo dài 2 lượt',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Attacks apply Burn effect for 2 turns.',
		zawakeSimpleDesc_en = 'Attacks apply Burn effect for 2 turns.',
		zawakeSimpleDesc_th = 'โจมตีพร้อมเอฟเฟกต์เผาไหม้เป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Serangan memberikan efek Terbakar selama 2 giliran.',
		zawakeSimpleDesc_ph = 'Ang mga atake ay magdudulot ng Burn effect sa loob ng 2 turn.',
		zawakeSimpleDesc_ma = 'Serangan memberikan kesan Terbakar selama 2 giliran.',
		zawakeSimpleDesc_vn = 'Tấn công với hiệu ứng thiêu đốt trong 2 lượt',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
