		skillName_ph = 'Kalasag - Puspos ng Apoy',
		skillName_ma = 'Pedang - Meteor Api',
		skillName = 'Sword - Fire Meteor',
		describe_vn = '#C0xC0C0C0#剑来~#C0x5B545B#\n#F10#\n#F40#Victini triệu hồi 3 thanh kiếm bay rực lửa để tấn công một mục tiêu kẻ thù, mỗi thanh gây ra #C0x3D8A99#60% Sát Thương Phép Thuật#C0x5B54 5B#+$(skillLevel*4*24)$#C0xF13B54#skill sát thương#C0x5B545B#, với mỗi mục tiêu bổ sung bị tấn công, Sát Thương Phép Thuật và tốc độ tăng thêm 10% (có thể cộng dồn tối đa 3 lớp), kéo dài trong 2 lượt.',
		describe_en = 'Victini summons 3 fiery flying swords to attack a single enemy target, each dealing 60% Magic Damage + $(skillLevel*4*24)$ skill damage. For each additional target attacked, Magic Damage and speed increase by 10% (stacking up to 3 times), lasting 2 turns.',
		describe_th = 'Victini เรียกดาบบินไฟ 3 เล่มโจมตีเป้าหมายศัตรูหนึ่งตัว แต่ละเล่มสร้างความเสียหายเวทมนตร์ 60% + $(skillLevel*4*24)$ ความเสียหายสกิล สำหรับเป้าหมายเพิ่มเติมแต่ละตัวที่ถูกโจมตี ความเสียหายเวทและความเร็วจะเพิ่มขึ้น 10% (สะสมได้สูงสุด 3 ชั้น) มีผลนาน 2 เทิร์น',
		describe_in = 'Victini memanggil 3 pedang terbang berapi untuk menyerang satu target musuh, setiap pedang memberikan 60% Kerusakan Sihir + $(skillLevel*4*24)$ kerusakan skill. Untuk setiap target tambahan yang diserang, Kerusakan Sihir dan kecepatan meningkat 10% (dapat bertumpuk hingga 3 lapis), bertahan selama 2 giliran.',
		describe_ph = 'Victini ay nagtatawag ng 3 nagliliyab na lumilipad na mga espada upang atakihin ang isang kaaway na target, bawat espada ay nagdudulot ng 60% Magic Damage + $(skillLevel*4*24)$ skill damage. Sa bawat karagdagang target na inaatake, ang Magic Damage at bilis ay tumataas ng 10% (pwedeng ma-stack hanggang 3 beses), tumatagal ng 2 turns.',
		describe_ma = 'Victini memanggil 3 pedang terbang berapi untuk menyerang satu sasaran musuh, setiap pedang memberikan 60% Kerosakan Sihir + $(skillLevel*4*24)$ kerosakan skil. Untuk setiap sasaran tambahan yang diserang, Kerosakan Sihir dan kelajuan meningkat 10% (boleh bertindan sehingga 3 lapisan), bertahan selama 2 pusingan.',
		describe = 'Victini summons 3 fiery flying swords to attack a single enemy target, each dealing 60% Magic Damage + $(skillLevel*4*24)$ skill damage. For each additional target attacked, Magic Damage and speed increase by 10% (stacking up to 3 times), lasting 2 turns.',
		zawakeEffect = __data_t__zawakeEffect[24631],
		-- {79001}
		zawakeEffectDesc = '#C0xC0C0C0#Jianlai~#C0x5B545B# \n#F10# \n#F40# Victini summons 3 blazing meteors to attack a single enemy target, each meteor dealing #C0x3D8A99#60% Magical Damage #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#spell damage#C0x5B545B#, and applying a burn effect on the target for 2 turns. For each additional target attacked, Magical Damage and speed increase by 10% (can stack up to 3 times), lasting 2 turns.',
		zawakeEffectDesc_en = '#C0xC0C0C0#Jianlai~#C0x5B545B# \n#F10# \n#F40# Victini summons 3 blazing meteors to attack a single enemy target, each meteor dealing #C0x3D8A99#60% Magical Damage #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#spell damage#C0x5B545B#, and applying a burn effect on the target for 2 turns. For each additional target attacked, Magical Damage and speed increase by 10% (can stack up to 3 times), lasting 2 turns.',
		zawakeEffectDesc_th = '#C0xC0C0C0#Jianlai~#C0x5B545B# \n#F10# \n#F40# วิคตินี่ เรียกดาวตกลุกโชน 3 ลูกโจมตีเป้าหมายศัตรูหนึ่งตัว แต่ละลูกทำ #C0x3D8A99#60% ความเสียหายเวทมนตร์ #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# พร้อมทั้งเพิ่มสถานะไฟเผาตัวเป้าหมายเป็นเวลา 2 รอบ สำหรับเป้าหมายเสริมแต่ละตัวที่โดนโจมตี ความเสียหายเวทมนตร์และความเร็วจะเพิ่มขึ้นอีก 10% (สะสมได้สูงสุด 3 ชั้น) เป็นเวลา 2 รอบ',
		zawakeEffectDesc_in = '#C0xC0C0C0#Jianlai~#C0x5B545B# \n#F10# \n#F40# Victini memanggil 3 meteorit menyala untuk menyerang satu target musuh, setiap meteorit memberikan #C0x3D8A99#60% Kerusakan Magis #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#kerusakan mantra#C0x5B545B#, sekaligus menambahkan efek terbakar pada setiap target selama 2 giliran. Untuk setiap target tambahan yang diserang, Kerusakan Magis dan kecepatan meningkat sebesar 10% (bisa bertumpuk hingga 3 lapis), berlangsung selama 2 giliran.',
		zawakeEffectDesc_ph = '#C0xC0C0C0#Jianlai~#C0x5B545B# \n#F10# \n#F40# Victini ay nag summon ng 3 nagliliyab na meteor para atakihin ang isang target na kalaban, bawat meteor ay nagdudulot ng #C0x3D8A99#60% Magical Damage #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#spell damage#C0x5B545B#, sabay naglalagay ng burn effect sa bawat target sa loob ng 2 turn. Sa bawat karagdagang target na naatake, ang Magical Damage at speed ay tumataas ng 10% (pwedeng mag stack hanggang 3 beses), tumatagal ng 2 turn.',
		zawakeEffectDesc_ma = '#C0xC0C0C0#Jianlai~#C0x5B545B# \n#F10# \n#F40# Victini memanggil 3 meteor berapi untuk menyerang satu sasaran musuh, setiap meteor menyebabkan #C0x3D8A99#60% Kerosakan Magik #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#kerosakan mantra#C0x5B545B#, serta menambah kesan terbakar pada setiap sasaran selama 2 pusingan. Untuk setiap sasaran tambahan yang diserang, Kerosakan Magik dan kelajuan meningkat sebanyak 10% (boleh bertingkat sehingga 3 lapisan), bertahan selama 2 pusingan.',
		zawakeEffectDesc_vn = '#C0xC0C0C0#Jianlai~#C0x5B545B# \n#F10# \n#F40# Victini triệu hồi 3 thiên thạch rực lửa để tấn công một mục tiêu kẻ địch, mỗi thiên thạch gây ra #C0x3D8A99#60% Sát Thương Phép Thuật #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Spell sát thương#C0x5B545B#, đồng thời thêm hiệu ứng đốt cháy lên mỗi mục tiêu trong 2 lượt. Với mỗi mục tiêu bổ sung bị tấn công, Sát Thương Phép Thuật và tốc độ tăng thêm 10% (có thể chồng lên 3 lớp), kéo dài trong 2 lượt.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Attacks apply Burn effect for 2 turns.',
		zawakeSimpleDesc_en = 'Attacks apply Burn effect for 2 turns.',
		zawakeSimpleDesc_th = 'โจมตีพร้อมเอฟเฟกต์เผาไหม้เป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Serangan memberikan efek Terbakar selama 2 giliran.',
