	[24632] = {
		id = 24632,
		skillName_vn = 'Kiếm - Ban Sức Mạnh',
		skillName_en = 'Sword - Power Band',
		skillName_th = 'ดาบ - สายพลัง',
		skillName_in = 'Pedang - Sabuk Kekuatan',
		skillName_ph = 'Sword - Power Band',
		skillName_ma = 'Pedang - Ikat Kuasa',
		skillName = 'Sword - Power Band',
		describe_vn = '#C0xC0C0C0#Ngày Thanh Kiếm Gãy Được Rèn Lại, Hiệp Sĩ Trở Về#C0x5B545B#\n#F10#\n#F40#Victini triệu hồi một thanh kiếm khổng lồ rực lửa tấn công một mục tiêu ở hàng trước và hàng sau của kẻ địch, gây ra #C0x3D8A99#90% Sát Thương Phép Thuật#C 0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# sát thương phép#C0x5B545B#, đồng thời thêm [Fire Sun Cord] vào đó và gây [Burn] trong 2 hiệp, đồng thời chuyển sang trạng thái [Fire Spirit] cho đến vòng tiếp theo. End\n#F10#\n#F40#[Yang Yangsuo]: Hiệu ứng kiểm soát chiếm ưu thế, [Fire Spirit] được giải phóng sau khi trạng thái kết thúc hoặc bị gián đoạn\n#F10#\n#F40#[Fire Spirit]: Trạng thái đặc biệt, không thể hành động, miễn nhiễm sát thương nhưng có thể được thêm vào, hiệu ứng (được điều khiển bởi không thể hành động) sẽ bị gián đoạn trong hệ thống) và 50% phòng thủ kép được trao cho đơn vị hàng đầu thân thiện, và 20% đòn tấn công kép được trao cho đơn vị ngẫu nhiên ở hàng sau đồng minh (ưu tiên lửa và siêu anh hùng). Khi nhận đòn tấn công chủ động, 150 điểm tức giận sẽ được phục hồi về chính nó; sau khi Flame Spirit kết thúc hoặc bị gián đoạn, nó sẽ tự thêm [Áo giáp lửa] vào bản thân trong 2 lượt.',
		describe_en = '#The Broken Sword Reforged Day, The Knight Returns#\n#F10#\n#F40#Victini summons a giant flaming sword to attack a target in the front and back rows of the enemy, dealing #C0x3D8A99#90% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# magic damage#C0x5B545B#, while adding [Fire Sun Cord] and inflicting [Burn] for 2 turns, also switching to [Fire Spirit] state until the next round. End\n#F10#\n#F40#[Yang Yangsuo]: Dominant control effect, [Fire Spirit] releases after state ends or is interrupted\n#F10#\n#F40#[Fire Spirit]: Special state, cannot act, immune to damage but can be added to, effect (controlled by inability to act) will be interrupted in the system) and grants 50% double defense to the front-line friendly unit, and 20% double attack to a random unit in the back row ally (priority to fire and super hero). When receiving an active attack, 150 rage points will be restored to itself; after Flame Spirit ends or is interrupted, it will add [Fire Armor] to itself for 2 turns.',
		describe_th = '#วันที่ดาบที่หักถูกตีใหม่ นักรบกลับมาแล้ว#\n#F10#\n#F40#Victini เรียกดาบเปลวเพลิงขนาดใหญ่โจมตีเป้าหมายในแถวหน้าและแถวหลังของศัตรู สร้าง #C0x3D8A99#ความเสียหายเวทมนตร์ 90%#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# พร้อมทั้งเพิ่ม [Fire Sun Cord] และก่อให้เกิด [Burn] เป็นเวลา 2 เทิร์น พร้อมเปลี่ยนสถานะเป็น [Fire Spirit] จนถึงรอบถัดไป End\n#F10#\n#F40#[Yang Yangsuo]: เอฟเฟกต์ควบคุมหลัก, [Fire Spirit] ปลดปล่อยหลังจากสถานะสิ้นสุดหรือถูกขัดขวาง\n#F10#\n#F40#[Fire Spirit]: สถานะพิเศษ ไม่สามารถทำการใดๆ ได้ ป้องกันความเสียหายแต่สามารถเพิ่มได้, เอฟเฟกต์ (ควบคุมโดยไม่สามารถกระทำ) จะถูกขัดจังหวะในระบบ) และมอบการป้องกันคู่ 50% ให้กับหน่วยแนวหน้าเพื่อน และมอบการโจมตีคู่ 20% ให้กับหน่วยสุ่มในแถวหลังฝ่ายเดียวกัน (ให้ความสำคัญกับไฟและซูเปอร์ฮีโร่) เมื่อถูกโจมตีแบบแอคทีฟ จะฟื้นฟูพลังแค้น 150 แต้มให้ตัวเอง; หลังจาก Flame Spirit สิ้นสุดหรือถูกขัดขวาง จะเพิ่ม [Fire Armor] ให้ตัวเองเป็นเวลา 2 เทิร์น',
		describe_in = '#Hari Pedang Pecah Ditempa Kembali, Ksatria Kembali#\n#F10#\n#F40#Victini memanggil pedang besar berapi-api untuk menyerang target di barisan depan dan belakang musuh, menyebabkan #C0x3D8A99#90% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# kerusakan sihir#C0x5B545B#, sambil menambahkan [Fire Sun Cord] dan memberikan [Burn] selama 2 giliran, serta beralih ke status [Fire Spirit] hingga giliran berikutnya. End\n#F10#\n#F40#[Yang Yangsuo]: Efek kontrol dominan, [Fire Spirit] dilepaskan setelah status berakhir atau terputus\n#F10#\n#F40#[Fire Spirit]: Status khusus, tidak dapat bertindak, kebal terhadap kerusakan tapi dapat ditambahkan, efek (dikendalikan oleh ketidakmampuan bertindak) akan terputus dalam sistem) dan memberikan pertahanan ganda 50% pada unit barisan depan teman, serta 20% serangan ganda pada unit acak di barisan belakang sekutu (prioritas pada api dan pahlawan super). Saat menerima serangan aktif, akan memulihkan 150 poin kemarahan pada dirinya sendiri; setelah Flame Spirit berakhir atau terputus, ia akan menambahkan [Fire Armor] pada dirinya sendiri selama 2 giliran.',
		describe_ph = '#Araw ng Muling Pagtatag ng Nabaling Espada, Bumulalik ang Kabalyero#\n#F10#\n#F40#Si Victini ay nagmumula ng isang dambuhalang naglalagablab na espada upang atakihin ang target sa unahan at likurang hanay ng kalaban, nagdudulot ng #C0x3D8A99#90% Malikhain na Panganib#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# pinsalang mahiwaga#C0x5B545B#, kasabay ng pagdagdag ng [Fire Sun Cord] at nagdudulot ng [Burn] sa loob ng 2 rounds, pati na rin paglilipat sa estado ng [Fire Spirit] hanggang sa susunod na round. End\n#F10#\n#F40#[Yang Yangsuo]: Pangunahing epekto ng kontrol, ang [Fire Spirit] ay napapalaya pagkatapos ng katapusan ng estado o kapag nailigaw\n#F10#\n#F40#[Fire Spirit]: Espesyal na estado, hindi makakilos, immune sa pinsala ngunit maaaring mapabilang, epekto (kontrolado ng kakulangan ng kakayahang kumilos) ay mapuputol sa sistema) at nagbibigay ng 50% dobleng depensa sa pinakaunahang kaalyadong yunit, at 20% dobleng atake sa isang random na yunit sa likurang hanay ng mga kaalyado (pinapahalagahan ang apoy at mga superhero). Kapag tumatanggap ng aktibong atake, 150 puntos ng galit ay ibabalik sa sarili; matapos ang pagtatapos o pag-interrupt ng Flame Spirit, idadagdag nito ang [Fire Armor] sa sarili sa loob ng 2 rounds.',
		describe_ma = '#Hari Pedang Patah Ditempa Semula, Kesatria Kembali#\n#F10#\n#F40#Victini memanggil pedang berapi gergasi untuk menyerang sasaran di barisan hadapan dan belakang musuh, menyebabkan #C0x3D8A99#90% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# kerosakan sihir#C0x5B545B#, sambil menambah [Fire Sun Cord] dan menyebabkan [Burn] selama 2 pusingan, dan beralih kepada keadaan [Fire Spirit] sehingga pusingan berikutnya. End\n#F10#\n#F40#[Yang Yangsuo]: Kesan kawalan dominan, [Fire Spirit] dibebaskan selepas keadaan berakhir atau diganggu\n#F10#\n#F40#[Fire Spirit]: Keadaan khas, tidak boleh bertindak, kebal kepada kerosakan tetapi boleh ditambah, kesan (dikawal oleh ketidakupayaan untuk bertindak) akan terganggu dalam sistem) dan memberikan 50% pertahanan berganda kepada unit barisan hadapan mesra, dan 20% serangan berganda kepada unit rawak di barisan belakang sekutu (keutamaan api dan wira super). Apabila menerima serangan aktif, 150 mata kemarahan akan dipulihkan kepada dirinya sendiri; selepas Flame Spirit berakhir atau terganggu, ia akan menambah [Fire Armor] pada diri sendiri selama 2 pusingan.',
		describe = '#The Broken Sword Reforged Day, The Knight Returns#\n#F10#\n#F40#Victini summons a giant flaming sword to attack a target in the front and back rows of the enemy, dealing #C0x3D8A99#90% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# magic damage#C0x5B545B#, while adding [Fire Sun Cord] and inflicting [Burn] for 2 turns, also switching to [Fire Spirit] state until the next round. End\n#F10#\n#F40#[Yang Yangsuo]: Dominant control effect, [Fire Spirit] releases after state ends or is interrupted\n#F10#\n#F40#[Fire Spirit]: Special state, cannot act, immune to damage but can be added to, effect (controlled by inability to act) will be interrupted in the system) and grants 50% double defense to the front-line friendly unit, and 20% double attack to a random unit in the back row ally (priority to fire and super hero). When receiving an active attack, 150 rage points will be restored to itself; after Flame Spirit ends or is interrupted, it will add [Fire Armor] to itself for 2 turns.',
		zawakeEffect = __data_t__zawakeEffect[24632],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#Day the broken sword was reforged, the knight returns#C0x5B545B# \n#F10# \n#F40# Victini attacks a target in the front and back rows of the enemy, dealing #C0x3D8A99#90% magic attack#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B#, simultaneously adding <Fire Sun Cord> to it and causing <Burning> for 2 turns, while switching to <Fire Spirit> state until the end of the next turn. \n#F20# \n#F40#<Yang Yang Suo>: Dominant control effect, it will be released after the <Fire Spirit> state ends or is interrupted \n#F20# \n#F40#<Fire Spirit>: Special state, cannot move, immune to damage but can be affected by effects (will be interrupted when controlled due to inability to move) and increases its own double defense ability by 50% for top allied units and 20% double attack to random allied units in the back row (prioritizing fire heroes, super), taking positive attacks restores 150 anger points for itself. While in Fire Spirit state, receiving skill damage increases own speed by 10% (can stack up to 3 times), and applies burning effect to attackers for 2 turns; after Flame Spirit ends or is interrupted, it will apply <Fire Armor> to itself for 2 turns.',
		zawakeEffectDesc_en = '#C0xC0C0C0#Day the broken sword was reforged, the knight returns#C0x5B545B# \n#F10# \n#F40# Victini attacks a target in the front and back rows of the enemy, dealing #C0x3D8A99#90% magic attack#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B#, simultaneously adding <Fire Sun Cord> to it and causing <Burning> for 2 turns, while switching to <Fire Spirit> state until the end of the next turn. \n#F20# \n#F40#<Yang Yang Suo>: Dominant control effect, it will be released after the <Fire Spirit> state ends or is interrupted \n#F20# \n#F40#<Fire Spirit>: Special state, cannot move, immune to damage but can be affected by effects (will be interrupted when controlled due to inability to move) and increases its own double defense ability by 50% for top allied units and 20% double attack to random allied units in the back row (prioritizing fire heroes, super), taking positive attacks restores 150 anger points for itself. While in Fire Spirit state, receiving skill damage increases own speed by 10% (can stack up to 3 times), and applies burning effect to attackers for 2 turns; after Flame Spirit ends or is interrupted, it will apply <Fire Armor> to itself for 2 turns.',
		zawakeEffectDesc_th = '#C0xC0C0C0#วันที่ดาบที่หักถูกหลอมใหม่ อัศวินกลับมา#C0x5B545B# \n#F10# \n#F40# Victini โจมตีเป้าหมายในแถวหน้าและแถวหลังของศัตรู สร้าง #C0x3D8A99#90% พลังโจมตีเวทย์มนตร์#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#ความเสียหายเวทย์มนตร์#C0x5B545B# พร้อมกันนั้นเพิ่ม <Fire Sun Cord> ให้กับมันและทำให้เกิด <Burning> เป็นเวลา 2 เทิร์น พร้อมเปลี่ยนเป็นสถานะ <Fire Spirit> จนกว่าจะสิ้นสุดเทิร์นถัดไป \n#F20# \n#F40#<Yang Yang Suo>: เอฟเฟกต์ควบคุมเด่นชัด จะถูกปลดปล่อยเมื่อสถานะ <Fire Spirit> สิ้นสุดหรือถูกขัดจังหวะ \n#F20# \n#F40#<Fire Spirit>: สถานะพิเศษ ไม่สามารถเคลื่อนที่ได้ ทนทานต่อความเสียหาย แต่สามารถถูกเพิ่มเอฟเฟกต์ (จะถูกขัดจังหวะเมื่อถูกควบคุมเนื่องจากไม่สามารถเคลื่อนที่ได้) และเพิ่มความสามารถป้องกันคู่ของตนเองขึ้น 50% สำหรับหน่วยพันธมิตรแถวหน้าและเพิ่มการโจมตีคู่ 20% ให้กับหน่วยพันธมิตรแบบสุ่มในแถวหลัง (ให้ความสำคัญกับฮีโร่ไฟระดับซูเปอร์) การได้รับการโจมตีเชิงบวกจะฟื้นฟูความโกรธ 150 จุดให้กับตัวเอง ในสถานะ Fire Spirit การได้รับความเสียหายจากทักษะจะเพิ่มความเร็วของตนเอง 10% (สะสมได้สูงสุด 3 ครั้ง) พร้อมเพิ่มเอฟเฟกต์การเผาไหม้ให้กับผู้โจมตีเป็นเวลา 2 เทิร์น; หลังจาก Fire Spirit สิ้นสุดหรือถูกขัดจังหวะ จะเพิ่ม <Fire Armor> ให้กับตัวเองเป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = '#C0xC0C0C0#Hari pedang patah ditempa ulang, ksatria kembali#C0x5B545B# \n#F10# \n#F40# Victini menyerang target di baris depan dan belakang musuh, menyebabkan #C0x3D8A99#90% serangan sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# damage sihir#C0x5B545B#, sekaligus menambahkan <Fire Sun Cord> padanya dan menyebabkan <Burning> selama 2 giliran, sambil beralih ke status <Fire Spirit> hingga akhir giliran berikutnya. \n#F20# \n#F40#<Yang Yang Suo>: Efek kontrol dominan, akan dilepaskan setelah status <Fire Spirit> berakhir atau terganggu \n#F20# \n#F40#<Fire Spirit>: Status khusus, tidak dapat bergerak, kebal terhadap kerusakan tetapi bisa terkena efek (akan terganggu saat dikendalikan karena tidak bisa bergerak) dan meningkatkan kemampuan pertahanan ganda dirinya sendiri sebesar 50% untuk unit sekutu baris depan dan 20% serangan ganda ke unit sekutu acak di baris belakang (memprioritaskan pahlawan api, super), menerima serangan positif akan memulihkan 150 poin amarah untuk dirinya sendiri. Dalam keadaan Fire Spirit, menerima damage skill akan meningkatkan kecepatan diri sebesar 10% (bisa bertumpuk hingga 3 kali), sekaligus menambahkan efek terbakar pada penyerang selama 2 giliran; setelah Fire Spirit berakhir atau terganggu, ia akan menambahkan <Fire Armor> pada dirinya sendiri selama 2 giliran.',
		zawakeEffectDesc_ph = '#C0xC0C0C0#Araw na muling pinanday ang nabasag na espada, bumalik ang kabalyero#C0x5B545B# \n#F10# \n#F40# Tutulain ni Victini ang target sa harap at likod na hanay ng kalaban, nagdudulot ng #C0x3D8A99#90% magic attack#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic na pinsala#C0x5B545B#, kasabay ng pagdaragdag ng <Fire Sun Cord> dito at nagiging sanhi ng <Burning> sa loob ng 2 turn, sabay lumilipat sa estado ng <Fire Spirit> hanggang matapos ang susunod na turn. \n#F20# \n#F40#<Yang Yang Suo>: Dominant control effect, mapapalaya ito pagkatapos matapos o maantala ang estado ng <Fire Spirit> \n#F20# \n#F40#<Fire Spirit>: Espesyal na estado, hindi makagalaw, immune sa pinsala ngunit maaaring madagdagan ng mga epekto (maaantala kung makokontrol dahil hindi makagalaw) at nagdaragdag ng 50% na dobleng depensa ng sarili para sa nangungunang kalapit na yunit ng kakampi at 20% dobleng atake sa random na kalapit na yunit sa likurang hanay (pinaprioritize ang apoy na bayani, super), ang pagtanggap ng positibong atake ay makabagong bumabalik ng 150 puntos ng galit para sa sarili. Sa estado ng Fire Spirit, ang pagtanggap ng skill damage ay nagpapataas ng 10% ng sariling bilis (pwedeng ma-stack ng hanggang 3 beses), kasabay ng pagdaragdag ng burning effect sa umaatake sa loob ng 2 turn; pagkaraan ng Fire Spirit o pagkaantala nito, awtomatikong idinadagdag ang <Fire Armor> sa sarili sa loob ng 2 turn.',
		zawakeEffectDesc_ma = '#C0xC0C0C0#Hari pedang patah ditempa semula, kesatria kembali#C0x5B545B# \n#F10# \n#F40# Victini menyerang sasaran di barisan depan dan belakang musuh, menyebabkan #C0x3D8A99#90% serangan sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# kerosakan sihir#C0x5B545B#, serentak menambah <Fire Sun Cord> kepadanya dan menyebabkan <Burning> selama 2 pusingan, sambil beralih ke status <Fire Spirit> sehingga tamat pusingan berikutnya. \n#F20# \n#F40#<Yang Yang Suo>: Kesan kawalan dominan, ia akan dilepaskan selepas status <Fire Spirit> tamat atau terganggu \n#F20# \n#F40#<Fire Spirit>: Status istimewa, tidak boleh bergerak, kebal kepada kerosakan tetapi boleh ditambah kesan (akan terganggu apabila dikawal kerana tidak boleh bergerak) dan meningkatkan keupayaan pertahanan berganda sendiri sebanyak 50% untuk unit sekutu barisan depan dan 20% serangan berganda kepada unit sekutu rawak di barisan belakang (mengutamakan wira api, super), menerima serangan positif akan memulihkan 150 mata kemarahan untuk dirinya sendiri. Dalam status Fire Spirit, menerima kerosakan kemahiran akan meningkatkan kelajuannya sendiri sebanyak 10% (boleh bertindih sehingga 3 kali), serentak menambah kesan terbakar kepada penyerang selama 2 pusingan; selepas Fire Spirit tamat atau terganggu, ia akan menambah <Fire Armor> kepada dirinya sendiri selama 2 pusingan.',
		zawakeEffectDesc_vn = '#C0xC0C0C0#Ngày đúc lại kiếm gãy, hiệp sĩ trở về#C0x5B545B# \n#F10# \n#F40# Victini tấn công một mục tiêu ở hàng trước và sau của kẻ địch, gây ra #C0x3D8A99#90% phép thuật attack#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#magic sát thương#C0x5B545B#, đồng thời thêm <Fire Sun Cord> vào nó và gây <Burning> trong 2 hiệp, đồng thời chuyển sang trạng thái <Fire Spirit> cho đến hết hiệp tiếp theo. \n#F20# \n#F40#<Yang Yang Suo>: Hiệu ứng điều khiển chiếm ưu thế, nó sẽ được giải phóng sau khi trạng thái <Hỏa Linh> kết thúc hoặc bị gián đoạn \n#F20# \n#F40#<Hỏa Linh>: Trạng thái đặc biệt, không thể di chuyển, miễn nhiễm sát thương nhưng có thể được thêm vào hiệu ứng (sẽ bị gián đoạn khi bị điều khiển do không thể di chuyển) và tăng 50% khả năng phòng thủ kép của chính nó cho các đơn vị hàng đầu đồng minh và 20% đòn tấn công kép của nó vào các đơn vị đồng minh ngẫu nhiên ở hàng sau (ưu tiên anh hùng lửa, siêu), nhận các đòn tấn công tích cực sẽ khôi phục 150 điểm giận dữ cho chính nó. Ở trạng thái Hỏa Linh, nhận sát thương kỹ năng sẽ tăng 10% tốc độ của bản thân (có thể cộng dồn 3 lần), đồng thời thêm hiệu ứng đốt cháy cho kẻ tấn công trong 2 lượt; sau khi Flame Spirit kết thúc hoặc bị gián đoạn, nó sẽ tự thêm <Áo giáp lửa> vào bản thân trong 2 lượt.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'While in Soul of Flame state, receiving skill damage increases your Speed by 10% (can stack up to 3 times) and inflicts Burn on the attacker for 2 turns.',
		zawakeSimpleDesc_en = 'While in Soul of Flame state, receiving skill damage increases your Speed by 10% (can stack up to 3 times) and inflicts Burn on the attacker for 2 turns.',
		zawakeSimpleDesc_th = 'ขณะอยู่ในสถานะวิญญาณแห่งเปลวเพลิง หากได้รับความเสียหายจากสกิลจะเพิ่มความเร็วของคุณ 10% (สะสมได้สูงสุด 3 ครั้ง) และทำให้ผู้โจมตีติดสถานะเผาไหม้เป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Saat dalam keadaan Jiwa Api, menerima damage skill akan meningkatkan Kecepatan sebesar 10% (dapat ditumpuk hingga 3 kali) dan memberikan efek Terbakar kepada penyerang selama 2 giliran.',
		zawakeSimpleDesc_ph = 'Kapag nasa Kaluluwa ng Apoy na estado, ang pagkatanggap ng skill damage ay magpapataas ng Speed mo ng 10% (puwedeng maipon hanggang 3 beses) at maglalagay ng Burn sa umaatake sa loob ng 2 turn.',
		zawakeSimpleDesc_ma = 'Semasa dalam status Roh Api, menerima kerosakan kemahiran akan meningkatkan Kelajuan anda sebanyak 10% (boleh ditindan sehingga 3 kali) dan menyebabkan penyerang terkena kesan Terbakar selama 2 giliran.',
		zawakeSimpleDesc_vn = 'Khi ở trạng thái Linh hồn ngọn lửa, nhận sát thương kỹ năng sẽ tăng tốc độ của bạn thêm 10% (có thể cộng dồn tối đa 3 lần) và gây hiệu ứng thiêu đốt cho kẻ tấn công trong 2 lượt.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 1,
		skillDamageType = 1,
		skillNatureType = 11,
		cdRound = 2,
		posChoose = 1,
		targetTypeDesc = 'Single targets at the front and back of the enemy',
		targetTypeDesc_vn = 'Mục tiêu đơn lẻ phía trước và phía sau của địch',
		targetTypeDesc_en = 'Single targets at the front and back of the enemy',
		targetTypeDesc_th = 'เป้าหมายเดี่ยวที่ด้านหน้าและด้านหลังของศัตรู',
		targetTypeDesc_in = 'Target tunggal di bagian depan dan belakang musuh',
		targetTypeDesc_ph = 'Isang target sa unahan at likuran ng kalaban',
		targetTypeDesc_ma = 'Sasaran tunggal di bahagian depan dan belakang musuh',
