	[24633] = {
		id = 24633,
		skillName_vn = 'Kiếm-V Nhiệt Diễm',
		skillName_en = 'Kiếm-V Nhiệt Diễm',
		skillName_th = 'Kiếm-V Nhiệt Diễm',
		skillName_in = 'Kiếm-V Nhiệt Diễm',
		skillName_ph = 'Kiếm-V Nhiệt Diễm',
		skillName_ma = 'Kiếm-V Nhiệt Diễm',
		skillName = 'Kiếm-V Nhiệt Diễm',
		describe_vn = '#C0xC0C0C0#Cắt đôi, Như Ý Thần Kiếm#C0x5B545B#\n#F10#\n#F40#Victini cầm thanh kiếm khổng lồ rực lửa nhắm vào tất cả kẻ thù, gây ra #C0x3D8A99#200% Sát Thương Phép Thuật#C0x5B5 45B#+$(skillLevel*4*24)$#C0xF13B54#spell sát thương#C0x5B545B#, và thêm 1 lớp đốt trong 2 lượt (đốt: hiệu ứng tiêu cực, mục tiêu mất 40% sức mạnh tấn Công Phép thuật của Victini trước mỗi Sát Thương Phép Thuật của vòng) và thêm [Áo giáp lửa] cho tất cả đơn vị đồng minh trong 2 lượt\n#F10#\n#F40#[Áo giáp lửa]: Giới hạn sinh mệnh ban đầu tăng 10% (gấp đôi theo loại lửa), 30% sát thương tấn công chủ động sẽ phản ánh vào kẻ thù, 10% (anh hùng loại lửa) (gấp đôi số lượng anh hùng) để hồi phục. Nó sẽ hết hạn khi tổng lượng sát thương phản công vượt quá 25% giới hạn máu trên của Victini (giới hạn trên của thất bại của tướng lửa tăng gấp đôi). Khi áo giáp lửa kết thúc hoặc hết hạn, anh hùng lửa sẽ hồi phục 20% máu từ giới hạn máu trên của Victini, đồng thời tăng 15% đòn chí mạng và sát thương chí mạng (1 hiệp).',
		describe_en = 'Slicing in two, the As-You-Wish Divine Sword. Victini wields a gigantic blazing sword targeting all enemies, inflicting 200% Magic Damage + $(skillLevel*4*24)$ spell damage, and applies a burn effect for 2 turns (burn: negative effect, the target loses 40% of Victini\'s Magical Attack power before each Magic Damage of the turn). Additionally, it grants [Flame Armor] to all allied units for 2 turns. [Flame Armor]: Initially increases max HP by 10% (doubled for fire types), reflects 30% of active attack damage to enemies, and heals 10% for fire-type heroes (doubled by the number of heroes). It expires when the total reflected damage exceeds 25% of Victini\'s max HP (the upper limit of defeat for fire generals is doubled). When Flame Armor ends or expires, fire heroes recover 20% HP based on Victini\'s max HP and gain 15% critical hit rate and critical damage for 1 round.',
		describe_th = 'ตัดครึ่ง ดาบอัศจรรย์ตามปรารถนา Victini ถือดาบยักษ์เปลวไฟที่ลุกโชติช่วงโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวท 200% + $(skillLevel*4*24)$ ความเสียหายเวท และเพิ่มสถานะไหม้เป็นเวลา 2 เทิร์น (ไหม้: ผลลบ ทำให้เป้าหมายสูญเสียพลังโจมตีเวทของ Victini 40% ก่อนทุกครั้งที่โจมตีเวทในรอบ) อีกทั้งยังมอบ [เกราะไฟ] ให้กับหน่วยพันธมิตรรอบตัวเป็นเวลา 2 เทิร์น [เกราะไฟ]: เพิ่มพลังชีวิตสูงสุดเริ่มต้น 10% (เพิ่มเป็นสองเท่าสำหรับประเภทไฟ) สะท้อนความเสียหายโจมตีที่ทำได้ 30% ไปยังศัตรู ฟื้นฟู 10% สำหรับฮีโร่ประเภทไฟ (คูณสองตามจำนวนฮีโร่) จะหมดอายุเมื่อตัวสะท้อนความเสียหายรวมเกิน 25% ของพลังชีวิตสูงสุดของ Victini (ขีดจำกัดการพ่ายแพ้ของผู้บัญชาการไฟเพิ่มเป็นสองเท่า) เมื่อเกราะไฟสิ้นสุดหรือหมดอายุ ฮีโร่ไฟจะฟื้นฟูพลังชีวิต 20% จากพลังชีวิตสูงสุดของ Victini และเพิ่มอัตราคริติคอลและความเสียหายคริติคอล 15% เป็นเวลา 1 เทิร์น',
		describe_in = 'Memotong dua, Pedang Dewa Sesuai Harapan. Victini memegang pedang raksasa berapi menyala yang menyerang semua musuh, menyebabkan 200% Kerusakan Sihir + $(skillLevel*4*24)$ kerusakan sihir, dan memberikan efek terbakar selama 2 giliran (terbakar: efek negatif, target kehilangan 40% kekuatan Serangan Sihir Victini sebelum setiap Kerusakan Sihir giliran tersebut). Selain itu, memberikan [Baju Besi Api] kepada semua unit sekutu selama 2 giliran. [Baju Besi Api]: Awalnya meningkatkan batas HP maksimum sebesar 10% (ganda untuk tipe api), memantulkan 30% kerusakan serangan aktif ke musuh, dan menyembuhkan 10% untuk pahlawan tipe api (ganda berdasarkan jumlah pahlawan). Efek ini berakhir saat total kerusakan pantulan melebihi 25% dari HP maksimum Victini (batas atas kekalahan jenderal api digandakan). Saat Baju Besi Api berakhir atau habis, pahlawan api akan pulih 20% HP berdasarkan HP maksimum Victini serta mendapatkan tambahan 15% tingkat kritis dan kerusakan kritis selama 1 giliran.',
		describe_ph = 'Hatingin ng dalawa, Ang Banal na Espada ng Nais. Hawak ni Victini ang napakalaking nag-aalab na espada na tumatarget sa lahat ng kalaban, nagdudulot ng 200% Magic Damage + $(skillLevel*4*24)$ na spell damage, at naglalapat ng burn effect sa loob ng 2 turn (burn: negatibong epekto, mawawala sa target ang 40% ng Magical Attack power ni Victini bago ang bawat Magic Damage ng turn). Dagdag pa rito, nagbibigay ito ng [Flame Armor] sa lahat ng kaalyadong yunit sa loob ng 2 turn. [Flame Armor]: Pinapataas ang maximum HP ng 10% (dumodoble sa mga fire type), nire-reflect ang 30% ng damage ng active attack sa mga kalaban, at nagpapagaling ng 10% para sa mga fire-type na bayani (dumodoble base sa dami ng mga bayani). Mawawala ang epekto kapag ang total na reflected damage ay lumagpas sa 25% ng max HP ni Victini (doble ang limitasyon ng pagkatalo para sa mga fire generals). Kapag nagtatapos ang Flame Armor, magpapagaling ang mga fire hero ng 20% HP base sa max HP ni Victini at tumatanggap ng dagdag na 15% critical hit rate at critical damage sa loob ng 1 round.',
		describe_ma = 'Membelah dua, Pedang Ilahi Sesuai Kehendak. Victini memegang pedang besar menyala membakar yang menyerang semua musuh, menyebabkan 200% Kerosakan Sihir + $(skillLevel*4*24)$ kerosakan mantra, dan menambah kesan terbakar selama 2 giliran (terbakar: kesan negatif, sasaran kehilangan 40% kekuatan Serangan Sihir Victini sebelum setiap Kerosakan Sihir giliran tersebut). Selain itu, ia memberikan [Zirah Api] kepada semua unit sekutu selama 2 giliran. [Zirah Api]: Meningkatkan had nyawa maksimum sebanyak 10% (berganda untuk jenis api), memantulkan 30% kerosakan serangan aktif kepada musuh, dan menyembuh 10% untuk wira jenis api (berganda mengikut bilangan wira). Ia akan tamat apabila jumlah kerosakan pantulan melebihi 25% had nyawa maksimum Victini (had atas kekalahan wira api digandakan). Apabila Zirah Api tamat atau habis tempohnya, wira api akan pulih 20% nyawa berdasarkan had nyawa maksimum Victini dan meningkatkan 15% kadar kritikal dan kerosakan kritikal selama 1 pusingan.',
		describe = 'Slicing in two, the As-You-Wish Divine Sword. Victini wields a gigantic blazing sword targeting all enemies, inflicting 200% Magic Damage + $(skillLevel*4*24)$ spell damage, and applies a burn effect for 2 turns (burn: negative effect, the target loses 40% of Victini\'s Magical Attack power before each Magic Damage of the turn). Additionally, it grants [Flame Armor] to all allied units for 2 turns. [Flame Armor]: Initially increases max HP by 10% (doubled for fire types), reflects 30% of active attack damage to enemies, and heals 10% for fire-type heroes (doubled by the number of heroes). It expires when the total reflected damage exceeds 25% of Victini\'s max HP (the upper limit of defeat for fire generals is doubled). When Flame Armor ends or expires, fire heroes recover 20% HP based on Victini\'s max HP and gain 15% critical hit rate and critical damage for 1 round.',
		simDesc_vn = 'Victini tấn công toàn bộ mục tiêu của đối phương, gây sát thương ma pháp và thêm hiệu ứng Thiêu Đốt, đồng thời thêm [Giáp Lửa] cho tất cả đơn vị đồng minh.',
		simDesc_en = 'Victini attacks all enemy targets, dealing magical damage and applying the Burn effect, while also granting <Fire Shield> to all allied units.',
		simDesc_th = 'Victini โจมตีเป้าหมายทั้งหมดของศัตรู ทำความเสียหายเวทมนตร์และเพิ่มเอฟเฟกต์เผาไหม้ พร้อมทั้งมอบ [เกราะไฟ] ให้กับหน่วยพันธมิตรทั้งหมด',
		simDesc_in = 'Victini menyerang semua target musuh, memberikan kerusakan magis dan efek Terbakar, serta menambahkan <Perisai Api> untuk semua unit sekutu.',
		simDesc_ph = 'Inaatake ni Victini ang lahat ng mga kalaban na target, nagdudulot ng magic na pinsala at naglalagay ng Burn effect, habang nagbibigay din ng <Fire Shield> sa lahat ng kaalyadong yunit.',
		simDesc_ma = 'Victini menyerang semua sasaran musuh, memberikan kerosakan magik dan kesan Terbakar, serta menambah <Perisai Api> untuk semua unit sekutu.',
		simDesc = 'Victini attacks all enemy targets, dealing magical damage and applying the Burn effect, while also granting [Fire Shield] to all allied units.',
		starEffect = __data_t__starEffect[24633],
		-- {11}
		starEffectDesc_vn = '<Cuộc Tấn Công Chiến Thắng>: Gây hiệu ứng dễ bị tổn thương bằng lửa 20% lên anh hùng kẻ địch có năng lượng cao nhất và thiêu đốt năng lượng của họ, ngay lập tức khiến tất cả anh hùng hệ lửa của mình tấn công mục tiêu một lần bổ sung (nếu đã đầy năng lượng, có thể sử dụng kỹ năng đặc biệt).',
		starEffectDesc = '<#F Cuộc Tấn Công Chiến Thắng#>: Inflicts 20% fire vulnerability on the enemy hero with the highest energy and burns their energy, instantly causing all of your fire heroes to attack the target one additional time (if energy is full, they can use their special skill).',
		starEffectDesc_en = '<#F Cuộc Tấn Công Chiến Thắng#>: Inflicts 20% fire vulnerability on the enemy hero with the highest energy and burns their energy, instantly causing all of your fire heroes to attack the target one additional time (if energy is full, they can use their special skill).',
		starEffectDesc_th = '<#F Cuộc Tấn Công Chiến Thắng#>: สร้างเอฟเฟกต์ติดไฟทำให้ได้รับความเสียหายเพิ่มขึ้น 20% แก่ฮีโร่ฝ่ายตรงข้ามที่มีพลังงานสูงสุดและเผาพลังงานของพวกเขา ทันทีทำให้ฮีโร่ระบบไฟของคุณทั้งหมดโจมตีเป้าหมายอีกหนึ่งครั้ง (ถ้าพลังงานเต็ม สามารถใช้สกิลพิเศษได้)',
		starEffectDesc_in = '<#F Cuộc Tấn Công Chiến Thắng#>: Memberikan efek kerentanan api 20% pada pahlawan musuh dengan energi tertinggi dan membakar energi mereka, segera menyebabkan semua pahlawan api Anda menyerang target satu kali tambahan (jika energi penuh, dapat menggunakan skill khusus).',
		starEffectDesc_ph = '<#F Cuộc Tấn Công Chiến Thắng#>: Nagdudulot ng 20% na pagiging bulnerable sa apoy sa kaaway na may pinakamataas na enerhiya at sinusunog ang kanilang enerhiya, agad na pinapaatake ang lahat ng iyong mga fire heroes sa target ng isang karagdagang beses (kung puno ang enerhiya, maaaring gamitin ang espesyal na kasanayan).',
		starEffectDesc_ma = '<#F Cuộc Tấn Công Chiến Thắng#>: Memberikan kesan mudah terkesan api sebanyak 20% kepada wira musuh dengan tenaga tertinggi dan membakar tenaganya, serta segera menyebabkan semua wira api anda menyerang sasaran sekali lagi (jika tenaga penuh, boleh menggunakan kemahiran khas).',
		zawakeEffect = __data_t__zawakeEffect[24633],
		-- {79003}
		zawakeEffectDesc = '#C0xC0C0C0#Half Cut, Ruyi Divine Sword#C0x5B545B# \n#F10# \n#F40# Victini attacks all enemy targets, dealing #C0x3D8A99#200% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B5 4#Spell Damage#C0x5B545B#, and applies 1 stack of burn for 2 turns (burn: a debuff causing the target to lose 40% of Victini\'s additional Magic Damage before each turn) and grants <Flame Armor> to all allied units for 2 turns \n#F20# \n#F40#<Flame Armor>: Initial health limit increased by 10% (doubled for fire heroes), 30% of active attack damage is reflected back to enemies, 10% (doubled for fire heroes) is converted to healing, and this effect ends when the total reflected damage exceeds 25% of Victini\'s max HP (the failure limit for fire heroes is doubled). When Flame Armor is destroyed or nullified, fire heroes heal 20% of Victini\'s HP and gain 15% critical damage and critical hit rate for 1 round. When the duo <Flame Armor> coverage by fire heroes expires, it deals 40% magic damage of Victini to all enemy targets; <Victory> burns all buffs on the target.',
		zawakeEffectDesc_en = '#C0xC0C0C0#Half Cut, Ruyi Divine Sword#C0x5B545B# \n#F10# \n#F40# Victini attacks all enemy targets, dealing #C0x3D8A99#200% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B5 4#Spell Damage#C0x5B545B#, and applies 1 stack of burn for 2 turns (burn: a debuff causing the target to lose 40% of Victini\'s additional Magic Damage before each turn) and grants <Flame Armor> to all allied units for 2 turns \n#F20# \n#F40#<Flame Armor>: Initial health limit increased by 10% (doubled for fire heroes), 30% of active attack damage is reflected back to enemies, 10% (doubled for fire heroes) is converted to healing, and this effect ends when the total reflected damage exceeds 25% of Victini\'s max HP (the failure limit for fire heroes is doubled). When Flame Armor is destroyed or nullified, fire heroes heal 20% of Victini\'s HP and gain 15% critical damage and critical hit rate for 1 round. When the duo <Flame Armor> coverage by fire heroes expires, it deals 40% magic damage of Victini to all enemy targets; <Victory> burns all buffs on the target.',
		zawakeEffectDesc_th = '#C0xC0C0C0#ตัดครึ่ง, ดาบเทพรูยี่#C0x5B545B# \n#F10# \n#F40# Victini โจมตีเป้าหมายศัตรูทั้งหมด สร้าง #C0x3D8A99#200% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B5 4#ความเสียหายเวทมนตร์#C0x5B545B# และเพิ่มสถานะเผาไหม้ 1 ชั้นเป็นเวลา 2 เทิร์น (เผาไหม้: ผลกระทบลบ ทำให้เป้าหมายสูญเสีย 40% ของความเสียหายเวทมนตร์เสริมจาก Victini ก่อนแต่ละรอบ) และเพิ่ม <เกราะไฟ> ให้กับหน่วยพันธมิตรทั้งหมดเป็นเวลา 2 เทิร์น \n#F20# \n#F40#<เกราะไฟ>: จำกัดพลังชีวิตเริ่มต้นเพิ่มขึ้น 10% (เพิ่มเป็นสองเท่าสำหรับฮีโร่ธาตุไฟ), 30% ของความเสียหายการโจมตีที่ใช้งานจะถูกสะท้อนกลับไปยังศัตรู, 10% (เพิ่มเป็นสองเท่าสำหรับฮีโร่ธาตุไฟ) จะถูกเปลี่ยนเป็นฟื้นฟู และเอฟเฟกต์นี้จะสิ้นสุดเมื่อความเสียที่สะท้อนทั้งหมดเกิน 25% ของพลังชีวิตสูงสุดของ Victini (ขีดจำกัดการล้มเหลวของฮีโร่ธาตุไฟเพิ่มเป็นสองเท่า) เมื่อเกราะไฟถูกทำลายหรือถูกยกเลิก ฮีโร่ธาตุไฟจะฟื้นฟู HP ของ Victini 20% และเพิ่มความเสียหายคริติคอลและอัตราคริติคอล 15% เป็นเวลา 1 เทิร์น เมื่อชุดคู่ <เกราะไฟ> ที่ฮีโร่ธาตุไฟคลุมหมดอายุ มันจะสร้างความเสียหายเวท 40% ของ Victini กับเป้าหมายศัตรูทั้งหมด; <ชัยชนะ> จะเผาทุกบัฟของเป้าหมาย',
		zawakeEffectDesc_in = '#C0xC0C0C0#Belah Dua, Pedang Dewa Ruyi#C0x5B545B# \n#F10# \n#F40# Victini menyerang semua target musuh, memberikan #C0x3D8A99#200% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B5 4#Kerusakan Sihir#C0x5B545B#, dan menambahkan 1 lapis terbakar selama 2 giliran (terbakar: efek negatif, target kehilangan 40% dari tambahan Kerusakan Sihir Victini sebelum setiap giliran) serta menambahkan <Baju Zirah Api> kepada semua unit sekutu selama 2 giliran \n#F20# \n#F40#<Baju Zirah Api>: Batas awal nyawa meningkat 10% (dobel untuk pahlawan api), 30% dari kerusakan serangan aktif akan dipantulkan ke musuh, 10% (dobel untuk pahlawan api) akan diubah menjadi penyembuhan dan akan berakhir saat total kerusakan pantulan melewati 25% batas darah Victini (batas kegagalan untuk pahlawan api dobel), Baju zirah api saat dihancurkan atau dinetralkan, pahlawan api menyembuhkan 20% HP Victini dan meningkatkan 15% kerusakan kritis serta peluang kritis (1 giliran). Saat duo <Baju Zirah Api> dilindungi oleh pahlawan api berakhir, ia akan memberikan 40% kerusakan sihir Victini ke semua target musuh; <Kemenangan> akan membakar semua buff pada target.',
		zawakeEffectDesc_ph = '#C0xC0C0C0#Hating Hati, Ruyi Divine Sword#C0x5B545B# \n#F10# \n#F40# Atinakag Victini ang lahat ng kalabang target, nagdudulot ng #C0x3D8A99#200% Magic na Pinsala#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B5 4#Spell na Pinsala#C0x5B545B#, at nagdadagdag ng 1 layer ng paso sa loob ng 2 turn (paso: negatibong epekto, nawawala ang target ng 40% ng karagdagang Magic Pinsala mula sa Spell Damage ni Victini bago ang bawat round) at nagdadagdag ng <Armour ng Apoy> sa lahat ng kaalyadong yunit sa loob ng 2 turn \n#F20# \n#F40#<Armour ng Apoy>: Initial na limitasyon ng buhay nadagdagan ng 10% (doble para sa mga fire na bayani), 30% ng aktibong damage attack ay mare-reflect sa mga kalaban, 10% (doble para sa mga fire bayani) ay magiging healing at matatapos ang effect kapag lumagpas ang total reflected damage ng 25% ng buhay ni Victini (doble din ang failure limit ng mga fire bayani), kapag nawasak o na-neutralize ang armour ng apoy, nagpapagaling ng 20% ng HP ni Victini ang mga fire bayani at tumataas ng 15% ang critical damage at crit rate (1 round). Kapag nag-expire ang duo na <Armour ng Apoy> na natakpan ng mga fire hero, nagdudulot ito ng 40% magic na pinsala ni Victini sa lahat ng kalabang target; ang <Victory> ay sinusunog ang lahat ng buff ng target.',
		zawakeEffectDesc_ma = '#C0xC0C0C0#Belah Dua, Pedang Dewa Ruyi#C0x5B545B# \n#F10# \n#F40# Victini menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#200% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B5 4#Kerosakan Sihir#C0x5B545B#, dan menambah 1 lapisan kebakaran selama 2 pusingan (kebakaran: kesan negatif, sasaran kehilangan 40% kerosakan sihir tambahan dari Kerosakan Sihir Victini sebelum setiap pusingan) serta menambah <Perisai Api> kepada semua unit sekutu selama 2 pusingan \n#F20# \n#F40#<Perisai Api>: Had nyawa awal meningkat 10% (berganda untuk wira api), 30% daripada kerosakan serangan aktif akan dipantulkan kepada musuh, 10% (berganda untuk wira api) akan ditukar menjadi pemulihan dan akan tamat apabila jumlah kerosakan pantulan melebihi 25% had darah Victini (had kegagalan untuk wira api berganda), perisai api apabila musnah atau tidak berkesan, wira api memulihkan 20% HP Victini dan meningkatkan 15% kerosakan kritikal dan kadar kritikal (1 pusingan). Apabila duo <Perisai Api> yang dilindungi oleh wira api tamat tempoh, ia akan menyebabkan 40% kerosakan sihir Victini kepada semua sasaran musuh; <Kemenangan> akan membakar semua buff pada sasaran.',
		zawakeEffectDesc_vn = '#C0xC0C0C0#Cắt đôi, Như Ý Thần Kiếm#C0x5B545B# \n#F10# \n#F40# Victini tấn công tất cả mục tiêu địch, gây ra #C0x3D8A99#200% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B5 4#Spell Sát thương#C0x5B545B#, và thêm 1 lớp đốt trong 2 lượt (đốt: hiệu ứng tiêu cực, mục tiêu mất 40% sát thương phép cộng thêm của Sát Thương Phép Thuật của Victini trước mỗi vòng) và thêm <Áo giáp lửa> cho tất cả đơn vị đồng minh trong 2 lượt \n#F20# \n#F40#<Áo giáp lửa>: Giới hạn sinh mệnh ban đầu tăng 10% (gấp đôi đối với tướng lửa), 30% sát thương tấn công chủ động sẽ là phản lại kẻ địch, 10% (gấp đôi đối với tướng lửa) sẽ chuyển thành hồi phục và sẽ hết hiệu lực khi tổng sát thương phản đòn vượt quá 25% giới hạn máu của Victini (giới hạn thất bại của tướng lửa tăng gấp đôi), áo giáp lửa Khi bị phá hủy hoặc vô hiệu, tướng lửa hồi phục 20% HP của Victini và tăng 15% sát thương chí mạng và sát thương chí mạng (1 hiệp). Khi bộ đôi <Áo giáp lửa> được anh hùng lửa che phủ hết hạn, nó sẽ gây 40% sát thương phép của Victini lên tất cả mục tiêu kẻ địch; <Chiến thắng> sẽ đốt cháy tất cả bùa lợi của mục tiêu.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '<Victory Charge> burns all buff effects from the target; In Ultimate Skill, when the <Flame Armor> effect of a Fire-type hero is nullified, deals Magic Damage equal to 40% of Victini\'s Magic ATK to all enemy targets.',
		zawakeSimpleDesc_en = '<Victory Charge> burns all buff effects from the target; In Ultimate Skill, when the <Flame Armor> effect of a Fire-type hero is nullified, deals Magic Damage equal to 40% of Victini\'s Magic ATK to all enemy targets.',
		zawakeSimpleDesc_th = '<พุ่งทะยานแห่งชัยชนะ> เผาผลาญเอฟเฟกต์เสริมทั้งหมดของเป้าหมาย; ในท่าไม้ตาย หากเอฟเฟกต์ <เกราะเพลิง> ของฮีโร่ธาตุไฟถูกลบ จะสร้างความเสียหายเวทเท่ากับ 40% ของพลังเวทของ Victini แก่ศัตรูทั้งหมด',
		zawakeSimpleDesc_in = '<Serangan Kemenangan> membakar semua efek buff target; Dalam Skill Ultimate, ketika efek <Armor Api> dari hero tipe Api dinetralkan, memberikan Damage Sihir sebesar 40% dari Magic ATK Victini ke semua musuh.',
		zawakeSimpleDesc_ph = '<Paglusob ng Tagumpay> ay susunugin ang lahat ng buff ng target; Sa Ultimate Skill, kapag ang <Flame Armor> ng Fire-type na bayani ay nawala, magdudulot ito ng 40% Magic ATK ni Victini bilang Magic Damage sa lahat ng kalaban.',
		zawakeSimpleDesc_ma = '<Serangan Kemenangan> membakar semua kesan buff dari sasaran; Dalam Kemahiran Utama, apabila kesan <Perisai Api> daripada hero elemen Api dineutralkan, akan menyebabkan Kerosakan Ajaib bersamaan 40% daripada Magic ATK Victini kepada semua musuh.',
		zawakeSimpleDesc_vn = '<Xung Phong Chiến Thắng> thiêu rụi toàn bộ hiệu ứng tăng cường của mục tiêu; Trong kỹ năng tuyệt chiêu, khi hiệu ứng <Giáp Lửa> của anh hùng hệ Lửa bị vô hiệu hóa, sẽ gây sát thương phép bằng 40% Công Phép của Victini lên toàn bộ mục tiêu phe địch',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 2,
		skillDamageType = 1,
