	[24712] = {
		id = 24712,
		skillName_vn = 'Siết chặt dây leo',
		skillName_en = 'Tighten the vine',
		skillName_th = 'รัดเถาให้แน่น',
		skillName_in = 'Kencangkan sulur',
		skillName_ph = 'Higpitan ang baging',
		skillName_ma = 'Ketatkan sulur',
		skillName = 'Tighten the vine',
		describe_vn = 'Tằng Tằng Xà dùng dây leo siết chặt mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#140% Phép Công#C0x5B545B#+$(skillLevel*4*48)$ Sát Thương Phép Thuật#C0xF13B54#,#C0x5B545B# hấp thụ một hiệu ứng tiêu cực ngẫu nhiên từ tối đa ba anh hùng đồng minh lên bản thân, nếu mục tiêu là anh hùng hệ gió, hồi phục lượng máu bằng 80% tổng phòng thủ kép của Tằng Tằng Xà',
		describe_en = 'Tang Tang Snake uses vines to tightly bind a single enemy target, dealing #C0x3D8A99#140% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ Magic Damage#C0xF13B54#,#C0x5B545B# absorbing a random negative effect from up to three allied heroes onto itself. If the target is a Wind-type hero, it restores HP equal to 80% of Tang Tang Snake\'s total dual defense.',
		describe_th = 'ตังตังสเนคใช้เถาวัลย์มัดเป้าหมายศัตรูเดี่ยวอย่างแน่นหนา สร้างความเสียหายเวท #C0x3D8A99#140%#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#, #C0x5B545B# ดูดซับเอฟเฟกต์ลบแบบสุ่มจากฮีโร่พันธมิตรร่วมสูงสุดสามคนมายังตัวเอง หากเป้าหมายเป็นฮีโร่สายลม จะฟื้นฟูพลังชีวิตเท่ากับ 80% ของการป้องกันคู่รวมของตังตังสเนค',
		describe_in = 'Tang Tang Snake menggunakan tali tanaman untuk mengikat target musuh tunggal dengan erat, menyebabkan #C0x3D8A99#140% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ Kerusakan Sihir#C0xF13B54#,#C0x5B545B# menyerap efek negatif acak dari hingga tiga pahlawan sekutu ke dirinya sendiri. Jika target adalah pahlawan tipe Angin, memulihkan HP sebesar 80% dari total pertahanan ganda Tang Tang Snake.',
		describe_ph = 'Ginagamit ng Tang Tang Snake ang mga baging upang higpit na higpitan ang isang target na kalaban, na nagdudulot ng #C0x3D8A99#140% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ Magic Damage#C0xF13B54#,#C0x5B545B# sumisipsip ng isang random na negatibong epekto mula sa hanggang tatlong kakampi na bayani sa sarili. Kung ang target ay isang bayani ng tipo ng Hangin, nagpapagaling ng HP na katumbas ng 80% ng kabuuang dobleng depensa ni Tang Tang Snake.',
		describe_ma = 'Tang Tang Snake menggunakan pokok anggur untuk mengikat sasaran musuh tunggal dengan ketat, menyebabkan #C0x3D8A99#140% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ Kerosakan Sihir#C0xF13B54#,#C0x5B545B# menyerap kesan negatif rawak daripada sehingga tiga wira sekutu ke atas dirinya sendiri. Jika sasaran adalah wira jenis Angin, memulihkan HP sebanyak 80% daripada jumlah pertahanan berganda Tang Tang Snake.',
		describe = 'Tang Tang Snake uses vines to tightly bind a single enemy target, dealing #C0x3D8A99#140% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ Magic Damage#C0xF13B54#,#C0x5B545B# absorbing a random negative effect from up to three allied heroes onto itself. If the target is a Wind-type hero, it restores HP equal to 80% of Tang Tang Snake\'s total dual defense.',
		simDesc_vn = 'Vine Snake dùng dây leo siết chặt mục tiêu đơn lẻ của đối phương.',
		simDesc_en = 'Vine Snake uses vines to strangle a single target of the opponent.',
		simDesc_th = 'งูเถาใช้เถาไม้รัดเป้าหมายเดี่ยวของฝ่ายตรงข้ามอย่างแน่นหนา',
		simDesc_in = 'Ular Ikat menggunakan sulur untuk mencekik satu target lawan.',
		simDesc_ph = 'Ginamit ng Vine Snake ang mga baging upang higpitan ang isang target ng kalaban.',
		simDesc_ma = 'Ular Rampi menggunakan pokok memanjat untuk mencekik satu sasaran lawan.',
		simDesc = 'Vine Snake uses vines to strangle a single target of the opponent.',
		zawakeEffect = __data_t__zawakeEffect[24712],
		-- {79002}
		zawakeEffectDesc = 'The snake vine uses climbing vines to constrict a single enemy target, dealing #C0x3D8A99#140% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, absorbing a random negative effect from up to five allied heroes for itself. If the target is a wind-element hero, it heals them for 80% of the snake vine\'s total double defense.',
		zawakeEffectDesc_en = 'The snake vine uses climbing vines to constrict a single enemy target, dealing #C0x3D8A99#140% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, absorbing a random negative effect from up to five allied heroes for itself. If the target is a wind-element hero, it heals them for 80% of the snake vine\'s total double defense.',
		zawakeEffectDesc_th = 'เถางูใช้เถาปีนป่ายรัดเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหาย #C0x3D8A99#140% พลังเวท#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# พร้อมดูดซับเอฟเฟกต์ลบแบบสุ่มจากฮีโร่พันธมิตรสูงสุดห้าตัวเข้าสู่ตัวเอง หากเป้าหมายเป็นฮีโร่ธาตุลม ฟื้นฟูเลือดให้พวกเขาเท่ากับ 80% ของพลังป้องกันคู่ทั้งหมดของเถางู',
		zawakeEffectDesc_in = 'Ular tanaman menggunakan sulur merambat untuk mencekik satu target musuh, memberikan #C0x3D8A99#140% Kekuatan Sulap#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Sulap #C0x5B545B#, menyerap efek negatif acak dari hingga lima pahlawan sekutu untuk dirinya sendiri. Jika target adalah pahlawan elemen angin, menyembuhkan mereka sebesar 80% dari total pertahanan ganda ular tanaman.',
		zawakeEffectDesc_ph = 'Ang ahas na baging ay gumagamit ng mga baging na umaakyat upang higpitan ang isang kalabang target, nagdudulot ng #C0x3D8A99#140% Lakas ng Mahika#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pinsala ng Mahika #C0x5B545B#, sumisipsip ng isang random na negatibong epekto mula sa hanggang limang kaalyadong bayani para sa sarili. Kung ang target ay isang bayani ng elemento ng hangin, nagpapagaling sa kanila ng 80% ng kabuuang dobleng depensa ng ahas na baging.',
		zawakeEffectDesc_ma = 'Ular pokok menggunakan sulur memanjat untuk mencekik satu sasaran musuh, menyebabkan #C0x3D8A99#140% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, menyerap satu efek negatif rawak dari maksimum lima wira sekutu untuk diri sendiri. Jika sasaran adalah wira unsur angin, memulihkan mereka dengan 80% jumlah pertahanan berganda ular pokok itu.',
		zawakeEffectDesc_vn = 'Rắn dây dùng dây leo siết chặt mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#140% Công Phép#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, hấp thụ một hiệu ứng tiêu cực ngẫu nhiên từ tối đa năm anh hùng đồng minh cho bản thân, nếu mục tiêu là anh hùng hệ gió, hồi phục cho họ lượng máu bằng 80% tổng phòng thủ kép của rắn dây',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Absorb 1 random negative effect from up to 3 allied heroes\n#F20# \n#F40##C0x5c9970#→Absorb 1 random negative effect from up to 5 allied heroes',
		zawakeSimpleDesc_en = 'Absorb 1 random negative effect from up to 3 allied heroes\n#F20# \n#F40##C0x5c9970#→Absorb 1 random negative effect from up to 5 allied heroes',
		zawakeSimpleDesc_th = 'ดูดซับผลลบแบบสุ่ม 1 อย่างจากฮีโร่พันธมิตรสูงสุด 3 คน\n#F20# \n#F40##C0x5c9970#→ดูดซับผลลบแบบสุ่ม 1 อย่างจากฮีโร่พันธมิตรสูงสุด 5 คน',
		zawakeSimpleDesc_in = 'Menyerap 1 efek negatif acak dari maksimal 3 hero sekutu\n#F20# \n#F40##C0x5c9970#→Menyerap 1 efek negatif acak dari maksimal 5 hero sekutu',
		zawakeSimpleDesc_ph = 'Sumisipsip ng 1 random na negatibong epekto mula sa hanggang 3 kakamping bayani\n#F20# \n#F40##C0x5c9970#→Sumisipsip ng 1 random na negatibong epekto mula sa hanggang 5 kakamping bayani',
		zawakeSimpleDesc_ma = 'Serap 1 kesan negatif rawak daripada maksimum 3 wira sekutu\n#F20# \n#F40##C0x5c9970#→Serap 1 kesan negatif rawak daripada maksimum 5 wira sekutu',
		zawakeSimpleDesc_vn = 'Hấp thụ 1 hiệu ứng tiêu cực ngẫu nhiên từ tối đa 3 anh hùng đồng minh\n#F20# \n#F40##C0x5c9970#→Hấp thụ 1 hiệu ứng tiêu cực ngẫu nhiên từ tối đa 5 anh hùng đồng minh',
