	[24713] = {
		id = 24713,
		skillName_vn = 'Điệu nhảy gai góc',
		skillName_en = 'Edgy dance',
		skillName_th = 'การเต้นที่มีความแหลมคม',
		skillName_in = 'Tarian yang tajam',
		skillName_ph = 'Makinang sayaw',
		skillName_ma = 'Tarian yang tajam',
		skillName = 'Edgy dance',
		describe_vn = 'Tằng Tằng Xà mượn sức mạnh tự nhiên, triệu hồi dây leo gai tấn công toàn bộ mục tiêu kẻ địch, gây ra #C0x3D8A99#140% Phép Công#C0x5B545B#+$(skillLevel*4*36)$ Sát Thương Phép Thuật#C0xF13B54#,#C0x5B545B# và gieo hạt giống dây leo dưới chân toàn bộ kẻ địch, sau lượt hành động của mục tiêu, dây leo sẽ mọc lên và [trói buộc] mục tiêu trong 1 lượt',
		describe_en = 'The Climbing Serpent borrows natural power, summoning thorny vines to attack all enemy targets, dealing #C0x3D8A99#140% Magic Attack#C0x5B545B# + $(skillLevel*4*36)$ Magic Damage#C0xF13B54#,#C0x5B545B# and planting vine seeds beneath all enemies. After the target\'s turn, the vines will grow and [bind] the target for 1 turn.',
		describe_th = 'งูปีนเขายืมพลังธรรมชาติ เรียกเถาวัลย์มีหนามโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหาย #C0x3D8A99#140% พลังเวท#C0x5B545B# + $(skillLevel*4*36)$ ความเสียหายเวทมนตร์#C0xF13B54#,#C0x5B545B# และหว่านเมล็ดเถาวัลย์ใต้เท้าศัตรูทั้งหมด หลังจากเทิร์นของเป้าหมาย เถาวัลย์จะเติบโตและ [ผูกมัด] เป้าหมายเป็นเวลา 1 เทิร์น',
		describe_in = 'Ular Merambat meminjam kekuatan alam, memanggil sulur berduri untuk menyerang semua target musuh, memberikan #C0x3D8A99#140% Serangan Magis#C0x5B545B# + $(skillLevel*4*36)$ Kerusakan Magis#C0xF13B54#,#C0x5B545B# dan menanam benih sulur di bawah semua musuh. Setelah giliran target, sulur akan tumbuh dan [mengikat] target selama 1 giliran.',
		describe_ph = 'Hiniram ng Climbing Serpent ang kapangyarihang likas, nagmumungkahi ng tinik na baging upang atakihin ang lahat ng kalabang target, nagdudulot ng #C0x3D8A99#140% Magic Attack#C0x5B545B# + $(skillLevel*4*36)$ Magic Damage#C0xF13B54#,#C0x5B545B# at nagtatanim ng binhi ng baging sa ilalim ng lahat ng kalaban. Pagkatapos ng turn ng target, lalago ang mga baging at [iipit] ang target sa loob ng 1 turn.',
		describe_ma = 'Ular Memanjat meminjam kekuatan semula jadi, memanggil sulur berduri menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#140% Serangan Magik#C0x5B545B# + $(skillLevel*4*36)$ Kerosakan Magik#C0xF13B54#,#C0x5B545B# dan menanam benih sulur di bawah semua musuh. Selepas giliran sasaran, sulur akan tumbuh dan [mengikat] sasaran selama 1 giliran.',
		describe = 'The Climbing Serpent borrows natural power, summoning thorny vines to attack all enemy targets, dealing #C0x3D8A99#140% Magic Attack#C0x5B545B# + $(skillLevel*4*36)$ Magic Damage#C0xF13B54#,#C0x5B545B# and planting vine seeds beneath all enemies. After the target\'s turn, the vines will grow and [bind] the target for 1 turn.',
		simDesc_vn = 'Vine Snake tận dụng sức mạnh tự nhiên, triệu hồi những dây leo gai nhọn múa may tấn công toàn bộ mục tiêu của đối phương và quấn chặt họ.',
		simDesc_en = 'Vine Snake harnesses natural power, summoning sharp thorny vines that dance and attack all enemy targets, tightly binding them.',
		simDesc_th = 'Vine Snake ใช้พลังธรรมชาติ เรียกเถาหนามแหลมที่ร่ายรำโจมตีเป้าหมายศัตรูทั้งหมดและพันรัดพวกมันแน่นหนา',
		simDesc_in = 'Vine Snake memanfaatkan kekuatan alam, memanggil sulur berduri tajam yang menari menyerang semua target musuh dan membelit mereka dengan erat.',
		simDesc_ph = 'Pinapakinabangan ng Vine Snake ang likas na lakas, nagtatawag ng matutulis na tinik na baging na sumasayaw upang atakihin ang lahat ng mga kalaban at mahigpit silang iyukot.',
		simDesc_ma = 'Vine Snake menggunakan kuasa semula jadi, memanggil sulur berduri yang tajam menari menyerang semua sasaran musuh dan melilit mereka dengan ketat.',
		simDesc = 'Vine Snake harnesses natural power, summoning sharp thorny vines that dance and attack all enemy targets, tightly binding them.',
		starEffect = __data_t__starEffect[24713],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi kỹ năng đặc biệt quấn lấy mục tiêu, sẽ hút 60% tổng phòng thủ của mục tiêu từ Vine Snake thành sát thương (sát thương này là sát thương thật).',
		starEffectDesc = 'Additional effect: When the special skill wraps around the target, it will absorb 60% of the target\'s total defense from Vine Snake as damage (this damage is true damage).',
		starEffectDesc_en = 'Additional effect: When the special skill wraps around the target, it will absorb 60% of the target\'s total defense from Vine Snake as damage (this damage is true damage).',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อทักษะพิเศษพันรอบเป้าหมาย จะดูด 60% ของการป้องกันทั้งหมดของเป้าหมายจาก Vine Snake เป็นความเสียหาย (ความเสียหายนี้เป็นความเสียหายจริง)',
		starEffectDesc_in = 'Efek tambahan: Ketika keterampilan khusus membelit target, akan menyerap 60% total pertahanan target dari Vine Snake sebagai kerusakan (kerusakan ini adalah kerusakan nyata).',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag ang espesyal na kasanayan ay yumukod sa target, ito ay huhugot ng 60% ng kabuuang depensa ng target mula sa Vine Snake bilang pinsala (ang pinsalang ito ay tunay na pinsala).',
		starEffectDesc_ma = 'Kesan tambahan: Apabila kemahiran khas melilit sasaran, ia akan menyerap 60% jumlah pertahanan sasaran daripada Vine Snake sebagai kerosakan (kerosakan ini adalah kerosakan sebenar).',
		zawakeEffect = __data_t__zawakeEffect[24713],
		-- {79003, 1}
		zawakeEffectDesc = 'Additional effect: When the critical skill tightly binds the target, it absorbs health from the target equal to 70% of the snake\'s dual defense (this damage is true damage). If the caster\'s health is full, the excess healing is transferred to the ally with the lowest health percentage.',
		zawakeEffectDesc_en = 'Additional effect: When the critical skill tightly binds the target, it absorbs health from the target equal to 70% of the snake\'s dual defense (this damage is true damage). If the caster\'s health is full, the excess healing is transferred to the ally with the lowest health percentage.',
		zawakeEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อสกิลวิกฤตพันเป้าหมายแน่น จะดูดเลือดจากเป้าหมายโดยเท่ากับ 70% ของการป้องกันคู่ของงู (ความเสียหายนี้เป็นความเสียหายจริง) หากตนเองมีเลือดเต็ม จะเปลี่ยนการฟื้นฟูส่วนเกินให้เป้าหมายพันธมิตรที่มีเปอร์เซ็นต์เลือดต่ำที่สุด',
		zawakeEffectDesc_in = 'Efek tambahan: Ketika keterampilan kritis mengikat target dengan erat, menyerap darah dari target sebesar 70% dari pertahanan ganda ular (kerusakan ini adalah kerusakan nyata). Jika darah pengguna sudah penuh, kelebihan penyembuhan dialihkan ke sekutu dengan persentase darah terendah.',
		zawakeEffectDesc_ph = 'Karagdagang epekto: Kapag mahigpit na nililimitahan ng kritikal na kakayahan ang target, sumisipsip ito ng buhay mula sa target na katumbas ng 70% ng doble\'ng depensa ng ahas (ang pinsalang ito ay totoong pinsala). Kung puno na ang sariling buhay, ang sobrang paggaling ay ililipat sa alyadong may pinakamababang porsyento ng buhay.',
		zawakeEffectDesc_ma = 'Kesan tambahan: Apabila kemahiran kritikal mengikat sasaran dengan kuat, ia menyerap darah dari sasaran sebanyak 70% pertahanan berganda ular (kerosakan ini adalah kerosakan sebenar). Jika kesihatan sendiri penuh, lebihan pemulihan dialihkan kepada sekutu yang mempunyai peratusan kesihatan terendah.',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: Khi kỹ năng chí mạng quấn chặt mục tiêu, hấp thụ lượng máu từ mục tiêu bằng 70% tổng phòng thủ kép của rắn dây (sát thương này là sát thương thực), nếu bản thân đã đầy máu, chuyển lượng hồi phục dư thừa cho mục tiêu đồng minh có tỷ lệ máu thấp nhất',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Lifesteal increased to 70%, if user is at full HP, excess healing will be transferred to the ally with the lowest HP',
		zawakeSimpleDesc_en = 'Lifesteal increased to 70%, if user is at full HP, excess healing will be transferred to the ally with the lowest HP',
		zawakeSimpleDesc_th = 'การดูดเลือดเพิ่มขึ้นเป็น 70% หากตัวละครมี HP เต็ม การฟื้นฟูส่วนเกินจะส่งต่อให้พันธมิตรที่มี HP ต่ำที่สุด',
		zawakeSimpleDesc_in = 'Hisap nyawa meningkat menjadi 70%, jika HP penuh, penyembuhan berlebih akan ditransfer ke sekutu dengan HP terendah',
		zawakeSimpleDesc_ph = 'Tumaas ang lifesteal sa 70%, kung puno ang HP, ang sobrang heal ay ibibigay sa kakampi na may pinakamababang HP',
		zawakeSimpleDesc_ma = 'Penyerapan nyawa meningkat kepada 70%, jika HP penuh, penyembuhan berlebihan akan dipindahkan kepada sekutu dengan HP paling rendah',
		zawakeSimpleDesc_vn = 'Hấp thụ sinh lực tăng lên 70%, nếu bản thân đã đầy máu, lượng hồi máu dư thừa sẽ chuyển cho mục tiêu đồng minh có máu thấp nhất',
		upLvDesc = 'Fixed damage +144',
