	[24721] = {
		id = 24721,
		skillName_vn = 'Lưỡi lá',
		skillName_en = 'Leaf Blade',
		skillName_th = 'ใบมีดใบไม้',
		skillName_in = 'Pisau Daun',
		skillName_ph = 'Dahon Talim',
		skillName_ma = 'Bilahan Daun',
		skillName = 'Leaf Blade',
		describe_vn = 'Thanh Xà dùng lá cây như kiếm để chém mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#100% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ Sát Thương Phép Thuật#C0xF13B54#,#C0x5B545B# với 20% xác suất khiến mục tiêu [trói buộc] trong 1 lượt (trói buộc: hiệu ứng kiểm soát, không thể hành động, có thể bị phá hủy bởi thiêu đốt)',
		describe_en = 'Thanh Xa uses a leaf as a sword to strike a single enemy target, dealing 100% Magic Attack + $(skillLevel*4*24)$ Magic Damage, with a 20% chance to [bind] the target for 1 turn (bind: a control effect that prevents actions and can be broken by burning).',
		describe_th = 'ธันห์ซาใช้ใบไม้เป็นดาบฟันเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหายเวท 100% + $(skillLevel*4*24)$ ความเสียหายเวท มาพร้อมโอกาส 20% ที่จะ [มัด] เป้าหมายเป็นเวลา 1 เทิร์น (มัด: เอฟเฟกต์ควบคุมทำให้ไม่สามารถเคลื่อนไหวได้ และสามารถถูกทำลายด้วยการเผาไหม้)',
		describe_in = 'Thanh Xa menggunakan daun sebagai pedang untuk memukul satu target musuh, memberikan 100% Serangan Sihir + $(skillLevel*4*24)$ Kerusakan Sihir, dengan peluang 20% untuk [mengikat] target selama 1 giliran (ikatan: efek kontrol yang mencegah aksi dan dapat dihancurkan oleh pembakaran).',
		describe_ph = 'Ginagamit ni Thanh Xa ang dahon bilang espada para hampasin ang isang target na kalaban, nagdudulot ng 100% Magic Attack + $(skillLevel*4*24)$ Magic Damage, may 20% na tsansa na [itali] ang target sa loob ng 1 turn (itali: control effect na pumipigil sa aksyon at maaaring mabali dahil sa pagsunog).',
		describe_ma = 'Thanh Xa menggunakan daun sebagai pedang untuk memukul satu sasaran musuh, memberikan 100% Serangan Sihir + $(skillLevel*4*24)$ Kerosakan Sihir, dengan peluang 20% untuk [ikatan] sasaran selama 1 pusingan (ikatan: kesan kawalan yang menghalang tindakan dan boleh dimusnahkan oleh pembakaran).',
		describe = 'Thanh Xa uses a leaf as a sword to strike a single enemy target, dealing 100% Magic Attack + $(skillLevel*4*24)$ Magic Damage, with a 20% chance to [bind] the target for 1 turn (bind: a control effect that prevents actions and can be broken by burning).',
		simDesc_vn = 'Thanh Đằng Xà điều khiển lá như một thanh kiếm, chém vào mục tiêu đơn lẻ của đối phương.',
		simDesc_en = 'The Silver Vine Serpent wields its leaves like a sword, slashing at a single enemy target.',
		simDesc_th = 'งูใบเงินใช้ใบไม้เหมือนดาบ ฟันใส่เป้าหมายเดี่ยวของศัตรู',
		simDesc_in = 'Ular Daun Perak mengendalikan daunnya seperti pedang, mengiris satu target musuh.',
		simDesc_ph = 'Kinokontrol ng Silver Vine Serpent ang mga dahon nito na parang espada, hinihiwa ang isang target na kalaban.',
		simDesc_ma = 'Ular Daun Perak mengawal daun-daunnya seperti pedang, memotong sasaran tunggal musuh.',
		simDesc = 'The Silver Vine Serpent wields its leaves like a sword, slashing at a single enemy target.',
		zawakeEffect = __data_t__zawakeEffect[24721],
		-- {79001}
		zawakeEffectDesc = 'Green snake controls leaves like a sword to slash a single enemy target, dealing #C0x3D8A99#100% Magical Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 40% chance to <bind> the target for 1 turn (bind: control effect, cannot act, can be broken by burn)',
		zawakeEffectDesc_en = 'Green snake controls leaves like a sword to slash a single enemy target, dealing #C0x3D8A99#100% Magical Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 40% chance to <bind> the target for 1 turn (bind: control effect, cannot act, can be broken by burn)',
		zawakeEffectDesc_th = 'งูเขียวควบคุมใบไม้เหมือนดาบเพื่อตัดศัตรูเป้าหมายเดี่ยว สร้าง #C0x3D8A99#100% พลังเวท#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวท #C0x5B545B# มีโอกาส 40% ที่จะ <พันธนาการ> เป้าหมายเป็นเวลา 1 เทิร์น (พันธนาการ: เอฟเฟกต์ควบคุม ไม่สามารถทำการกระทำได้ สามารถถูกทำลายด้วยการเผาไหม้)',
		zawakeEffectDesc_in = 'Ular hijau mengendalikan daun seperti pedang untuk memotong target musuh tunggal, memberikan #C0x3D8A99#100% Kekuatan Magis#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Magis #C0x5B545B#, dengan peluang 40% untuk <mengikat> target selama 1 giliran (mengikat: efek kontrol, tidak bisa bertindak, bisa dihancurkan oleh terbakar)',
		zawakeEffectDesc_ph = 'Ang berdenggang na ahas ay kumokontrol sa dahon tulad ng espada upang hiwain ang isang nag-iisang target ng kalaban, na nagdudulot ng #C0x3D8A99#100% Kapangyarihang Mahika#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Pinsalang Mahika #C0x5B545B#, may 40% tsansa na <itali> ang target sa loob ng 1 turn (itali: epekto ng kontrol, hindi makakilos, maaaring masira ng pagsunog)',
		zawakeEffectDesc_ma = 'Ular hijau mengawal daun seperti pedang untuk memotong sasaran musuh tunggal, memberikan #C0x3D8A99#100% Kuasa Magik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Magik #C0x5B545B#, dengan kebarangkalian 40% untuk <mengikat> sasaran selama 1 pusingan (mengikat: kesan kawalan, tidak boleh bertindak, boleh dimusnahkan oleh pembakaran)',
		zawakeEffectDesc_vn = 'Rắn dây xanh điều khiển lá như kiếm để cắt chém mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#100% Công Phép#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, có 40% xác suất khiến mục tiêu <quấn chặt> 1 lượt (quấn chặt: hiệu ứng kiểm soát, không thể hành động, có thể bị phá hủy bởi đốt cháy)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '20% chance to inflict <Bound> on the target for 1 turn\n#F20# \n#F40##C0x5c9970#→40% chance to inflict <Bound> on the target for 1 turn',
