	[24722] = {
		id = 24722,
		skillName_vn = 'Lời thề của cỏ',
		skillName_en = 'The Oath of Grass',
		skillName_th = 'คำสาบานของหญ้า',
		skillName_in = 'Sumpah Rumput',
		skillName_ph = 'Ang Panata ng Damo',
		skillName_ma = 'Sumpah Rumput',
		skillName = 'The Oath of Grass',
		describe_vn = 'Thanh Xà tập hợp lá cây thành quả cầu tấn công mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#150% Phép Công#C0x5B545B#+$(skillLevel*4*48)$ Sát Thương Phép Thuật#C0xF13B54#,#C0x5B545B# hấp thụ một hiệu ứng tiêu cực ngẫu nhiên từ tối đa ba anh hùng đồng minh lên bản thân, nếu mục tiêu là anh hùng hệ gió, hồi phục lượng máu bằng 80% tổng phòng thủ kép của Thanh Xà',
		describe_en = 'Thanh Xà gathers leaves into a sphere to attack a single enemy target, dealing #C0x3D8A99#150% Magic Attack#C0x5B545B# + $(skillLevel*4*48)$ Magic Damage#C0xF13B54#, #C0x5B545B# absorbing a random negative effect from up to three allied heroes onto itself. If the target is a Wind-type hero, it recovers health equal to 80% of Thanh Xà\'s total dual defense.',
		describe_th = 'ธันห์ซา รวบรวมใบไม้เป็นลูกบอลโจมตีเป้าหมายเดียวของศัตรู สร้างความเสียหายเวท #C0x3D8A99#150% พลังเวท#C0x5B545B# + $(skillLevel*4*48)$ ความเสียหายเวท#C0xF13B54#,#C0x5B545B# ดูดซับเอฟเฟกต์ลบแบบสุ่มจากฮีโร่พันธมิตรมากสุดสามคนมาไว้ที่ตัวเอง หากเป้าหมายเป็นฮีโร่สายลม ฟื้นฟูเลือดเป็น 80% ของค่าป้องกันคู่รวมของธันห์ซา',
		describe_in = 'Thanh Xà mengumpulkan daun menjadi bola untuk menyerang satu target musuh, memberikan #C0x3D8A99#150% Serangan Magis#C0x5B545B# + $(skillLevel*4*48)$ Damage Magis#C0xF13B54#, #C0x5B545B# menyerap efek negatif acak dari hingga tiga pahlawan sekutu ke dirinya sendiri. Jika target adalah pahlawan tipe Angin, memulihkan HP sebesar 80% dari total pertahanan ganda Thanh Xà.',
		describe_ph = 'Pinagsama ni Thanh Xà ang mga dahon upang bumuo ng isang bola na atake sa isang target na kalaban, na nagdudulot ng #C0x3D8A99#150% Magic Attack#C0x5B545B# + $(skillLevel*4*48)$ Magic Damage#C0xF13B54#, #C0x5B545B# sumisipsip ng isang random na negatibong epekto mula sa hanggang tatlong alyadong bayani sa sarili niya. Kung ang target ay isang Wind-type na bayani, nakakabawi ng HP na katumbas ng 80% ng kabuuang doble na depensa ni Thanh Xà.',
		describe_ma = 'Thanh Xà mengumpulkan daun menjadi bola untuk menyerang sasaran musuh tunggal, memberikan #C0x3D8A99#150% Serangan Sihir#C0x5B545B# + $(skillLevel*4*48)$ Kerosakan Sihir#C0xF13B54#, #C0x5B545B# menyerap satu kesan negatif rawak dari sehingga tiga wira sekutu ke atas dirinya sendiri. Jika sasaran adalah wira jenis Angin, memulihkan kesihatan sebanyak 80% daripada jumlah pertahanan berganda Thanh Xà.',
		describe = 'Thanh Xà gathers leaves into a sphere to attack a single enemy target, dealing #C0x3D8A99#150% Magic Attack#C0x5B545B# + $(skillLevel*4*48)$ Magic Damage#C0xF13B54#, #C0x5B545B# absorbing a random negative effect from up to three allied heroes onto itself. If the target is a Wind-type hero, it recovers health equal to 80% of Thanh Xà\'s total dual defense.',
		simDesc_vn = 'Thanh Đằng Xà tập hợp lá cỏ thành một quả cầu tấn công mục tiêu đơn lẻ của đối phương.',
		simDesc_en = 'Thanh Dang Snake gathers grass blades into a sphere to attack a single enemy target.',
		simDesc_th = 'งูทันดังรวบรวมใบหญ้าเป็นลูกบอลโจมตีเป้าหมายเดียวของศัตรู',
		simDesc_in = 'Ular Thanh Dang mengumpulkan daun rumput menjadi bola untuk menyerang satu target musuh.',
		simDesc_ph = 'Pinagsasama ng Ulang Thanh Dang ang mga dahon ng damo upang bumuo ng isang bola para atakihin ang isang kalaban.',
		simDesc_ma = 'Ular Thanh Dang mengumpulkan daun rumput menjadi bola untuk menyerang satu sasaran musuh.',
		simDesc = 'Thanh Dang Snake gathers grass blades into a sphere to attack a single enemy target.',
		zawakeEffect = __data_t__zawakeEffect[24722],
		-- {79002}
		zawakeEffectDesc = 'The green vine snake gathers grass leaves into a sphere to attack a single enemy target, dealing #C0x3D8A99#150% Magical Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, absorbing a random negative effect from up to five allied heroes for itself. If the target is a wind-type hero, it heals them for 80% of the green vine snake\'s total dual defense.',
		zawakeEffectDesc_en = 'The green vine snake gathers grass leaves into a sphere to attack a single enemy target, dealing #C0x3D8A99#150% Magical Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, absorbing a random negative effect from up to five allied heroes for itself. If the target is a wind-type hero, it heals them for 80% of the green vine snake\'s total dual defense.',
		zawakeEffectDesc_th = 'งูเถ้าสีเขียวรวบรวมใบหญ้าเป็นลูกบอลโจมตีเป้าหมายเดี่ยวของศัตรู ก่อให้เกิด #C0x3D8A99#150% พลังเวท#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวท#C0x5B545B# พร้อมดูดซับผลลบสุ่มจากฮีโร่พันธมิตรมากถึงห้าคนสำหรับตัวเอง หากเป้าหมายเป็นฮีโร่ประเภทลม จะฟื้นฟูพวกเขาด้วย 80% ของการป้องกันคู่รวมของงูเถ้าสีเขียว',
		zawakeEffectDesc_in = 'Ular sulur hijau mengumpulkan daun rumput menjadi bola untuk menyerang satu target musuh, memberikan #C0x3D8A99#150% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Magical #C0x5B545B#, menyerap efek negatif acak dari hingga lima pahlawan sekutu untuk dirinya sendiri. Jika target adalah pahlawan tipe angin, menyembuhkan mereka sebesar 80% dari total pertahanan ganda ular sulur hijau.',
		zawakeEffectDesc_ph = 'Ang berdahilig berdahilig na ahas ay nagtitipon ng mga dahon ng damo sa isang bola upang atakihin ang isang target na kalaban, na nagdudulot ng #C0x3D8A99#150% Kapangyarihang Mahika#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pinsalang Mahika #C0x5B545B#, sumisipsip ng isang random na negatibong epekto mula sa hanggang limang nakatagong kaalyado para sa sarili nito. Kung ang target ay isang bayani ng hangin, nagpapagaling ito sa kanila ng 80% ng kabuuang dobleng depensa ng berdeng ahas na may dahilig.',
		zawakeEffectDesc_ma = 'Ular pokok hijau mengumpulkan daun rumput menjadi bola untuk menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#150% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Magik #C0x5B545B#, menyerap satu kesan negatif rawak daripada sehingga lima wira sekutu untuk dirinya sendiri. Jika sasaran adalah wira jenis angin, memulihkan mereka sebanyak 80% dari jumlah pertahanan berganda ular pokok hijau.',
		zawakeEffectDesc_vn = 'Rắn dây xanh tập hợp lá cỏ thành quả cầu tấn công mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#150% Công Phép#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, hấp thụ một hiệu ứng tiêu cực ngẫu nhiên từ tối đa năm anh hùng đồng minh cho bản thân, nếu mục tiêu là anh hùng hệ gió, hồi phục cho họ lượng máu bằng 80% tổng phòng thủ kép của rắn dây xanh',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Absorb 1 random negative effect from up to 3 allied heroes\n#F20# \n#F40##C0x5c9970#→Absorb 1 random negative effect from up to 5 allied heroes',
		zawakeSimpleDesc_en = 'Absorb 1 random negative effect from up to 3 allied heroes\n#F20# \n#F40##C0x5c9970#→Absorb 1 random negative effect from up to 5 allied heroes',
		zawakeSimpleDesc_th = 'ดูดซับผลลบแบบสุ่ม 1 อย่างจากฮีโร่พันธมิตรสูงสุด 3 คน\n#F20# \n#F40##C0x5c9970#→ดูดซับผลลบแบบสุ่ม 1 อย่างจากฮีโร่พันธมิตรสูงสุด 5 คน',
		zawakeSimpleDesc_in = 'Menyerap 1 efek negatif acak dari maksimal 3 hero sekutu\n#F20# \n#F40##C0x5c9970#→Menyerap 1 efek negatif acak dari maksimal 5 hero sekutu',
		zawakeSimpleDesc_ph = 'Sumisipsip ng 1 random na negatibong epekto mula sa hanggang 3 kakamping bayani\n#F20# \n#F40##C0x5c9970#→Sumisipsip ng 1 random na negatibong epekto mula sa hanggang 5 kakamping bayani',
		zawakeSimpleDesc_ma = 'Serap 1 kesan negatif rawak daripada maksimum 3 wira sekutu\n#F20# \n#F40##C0x5c9970#→Serap 1 kesan negatif rawak daripada maksimum 5 wira sekutu',
		zawakeSimpleDesc_vn = 'Hấp thụ 1 hiệu ứng tiêu cực ngẫu nhiên từ tối đa 3 anh hùng đồng minh\n#F20# \n#F40##C0x5c9970#→Hấp thụ 1 hiệu ứng tiêu cực ngẫu nhiên từ tối đa 5 anh hùng đồng minh',
