	[24723] = {
		id = 24723,
		skillName_vn = 'Mưa hạt giống',
		skillName_en = 'Seed Rain',
		skillName_th = 'ฝนเมล็ดพันธุ์',
		skillName_in = 'Hujan Biji',
		skillName_ph = 'Ulan ng Binhi',
		skillName_ma = 'Hujan Benih',
		skillName = 'Seed Rain',
		describe_vn = 'Thanh Xà rải hạt giống từ trên cao, hạt giống rơi xuống đất sẽ mọc thành dây leo khổng lồ tấn công toàn bộ mục tiêu kẻ địch, gây ra #C0x3D8A99#150% Phép Công#C0x5B545B#+$(skillLevel*4*36)$ Sát Thương Phép Thuật#C0xF13B54#,#C0x5B545B# và gieo hạt giống dây leo dưới chân toàn bộ kẻ địch, sau lượt hành động của mục tiêu, dây leo sẽ mọc lên và [trói buộc] mục tiêu trong 1 lượt',
		describe_en = 'The White Snake scatters seeds from above; the seeds falling to the ground will grow into gigantic vines attacking all enemy targets, dealing #C0x3D8A99#150% Magical Attack#C0x5B545B# + $(skillLevel*4*36)$ Magic Damage#C0xF13B54#, #C0x5B545B# and planting vine seeds at the feet of all enemies. After the target\'s action turn, the vines will grow and [bind] the target for 1 turn.',
		describe_th = 'งูขาวกระจายเมล็ดพันธุ์จากด้านบน เมล็ดพันธุ์ที่ตกลงพื้นจะเติบโตเป็นเถาวัลย์ยักษ์โจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหาย #C0x3D8A99#150% พลังเวทย์โจมตี#C0x5B545B# + $(skillLevel*4*36)$ ความเสียหายเวทมนตร์#C0xF13B54#, #C0x5B545B# และหว่านเมล็ดพันธุ์เถาวัลย์ที่เท้าของศัตรูทั้งหมด หลังจากรอบการกระทำของเป้าหมาย เถาวัลย์จะงอกขึ้นและ [มัด] เป้าหมายเป็นเวลา 1 เทิร์น',
		describe_in = 'Ular Putih menyebarkan biji dari atas; biji yang jatuh ke tanah akan tumbuh menjadi sulur raksasa menyerang seluruh target musuh, memberikan #C0x3D8A99#150% Serangan Magis#C0x5B545B# + $(skillLevel*4*36)$ Kerusakan Sihir#C0xF13B54#, #C0x5B545B# dan menanam biji sulur di kaki seluruh musuh. Setelah giliran aksi target, sulur akan tumbuh dan [mengikat] target selama 1 giliran.',
		describe_ph = 'Pinapakalat ng Puting Ahas ang mga buto mula sa mataas; ang mga butong bumagsak sa lupa ay tutubo bilang malalaking baging na sumisira sa lahat ng target na kaaway, nagdudulot ng #C0x3D8A99#150% Magical Attack#C0x5B545B# + $(skillLevel*4*36)$ Magic Damage#C0xF13B54#, #C0x5B545B# at nagtatanim ng buto ng baging sa mga paa ng lahat ng kaaway. Pagkatapos ng turn ng aksyon ng target, tutubo ang mga baging at [bubuhol] sa target ng 1 turn.',
		describe_ma = 'Ular Putih menabur biji dari atas; biji yang jatuh ke tanah akan tumbuh menjadi pokok lumut gergasi menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#150% Serangan Magik#C0x5B545B# + $(skillLevel*4*36)$ Kerosakan Magik#C0xF13B54#, #C0x5B545B# serta menabur biji pokok lumut di kaki semua musuh. Selepas giliran tindakan sasaran, pokok lumut akan tumbuh dan [mengikat] sasaran selama 1 giliran.',
		describe = 'The White Snake scatters seeds from above; the seeds falling to the ground will grow into gigantic vines attacking all enemy targets, dealing #C0x3D8A99#150% Magical Attack#C0x5B545B# + $(skillLevel*4*36)$ Magic Damage#C0xF13B54#, #C0x5B545B# and planting vine seeds at the feet of all enemies. After the target\'s action turn, the vines will grow and [bind] the target for 1 turn.',
		simDesc_vn = 'Thanh Đằng Xà rải hạt giống từ độ cao, khi hạt giống rơi xuống sẽ phát triển thành dây leo khổng lồ tấn công toàn bộ mục tiêu của đối phương và quấn chặt họ.',
		simDesc_en = 'The Azure Vine scatters seeds from above; when the seeds fall, they grow into giant vines that attack all the enemy\'s targets and tightly bind them.',
		simDesc_th = 'เถาฟ้าโปรยเมล็ดจากที่สูง เมื่อเมล็ดตกลงจะเติบโตเป็นเถายักษ์โจมตีเป้าหมายทั้งหมดของฝ่ายตรงข้ามและพันรัดแน่นหนา',
		simDesc_in = 'Anggur Biru Menabur benih dari ketinggian; saat benih jatuh akan tumbuh menjadi sulur raksasa yang menyerang semua target musuh dan melilit erat mereka.',
		simDesc_ph = 'Ang Asul na Ubas ay nagbubunyi ng mga buto mula sa taas; kapag nahulog ang mga buto, lalaki ito bilang higanteng baging na umatake sa lahat ng kalaban at mahigpit na kinakaladkad sila.',
		simDesc_ma = 'Pucuk Biru menabur biji dari tempat tinggi; apabila biji jatuh, ia akan membesar menjadi pokok memanjat gergasi yang menyerang semua sasaran musuh dan melilit mereka dengan kemas.',
		simDesc = 'The Azure Vine scatters seeds from above; when the seeds fall, they grow into giant vines that attack all the enemy\'s targets and tightly bind them.',
		starEffect = __data_t__starEffect[24723],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi kỹ năng đặc biệt quấn lấy mục tiêu, sẽ hút 60% tổng phòng thủ của mục tiêu từ Green Vine Snake thành sát thương (sát thương này là sát thương thật).',
		starEffectDesc = 'Additional Effect: When the special skill wraps around the target, it absorbs 60% of the target\'s total defense from Green Vine Snake as damage (this damage is true damage).',
		starEffectDesc_en = 'Additional Effect: When the special skill wraps around the target, it absorbs 60% of the target\'s total defense from Green Vine Snake as damage (this damage is true damage).',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อทักษะพิเศษพันเป้าหมาย จะดูดซับเกราะรวม 60% ของเป้าหมายจาก Green Vine Snake เป็นความเสียหาย (ความเสียหายนี้เป็นความเสียหายจริง)',
		starEffectDesc_in = 'Efek Tambahan: Ketika skill khusus melilit target, akan menyerap 60% total pertahanan target dari Green Vine Snake sebagai damage (damage ini adalah damage nyata).',
		starEffectDesc_ph = 'Karagdagang Epekto: Kapag ang espesyal na kakayahan ay pumapalibot sa target, hihigupin nito ang 60% ng kabuuang depensa ng target mula sa Green Vine Snake bilang pinsala (ang pinsalang ito ay tunay na pinsala).',
		starEffectDesc_ma = 'Kesan Tambahan: Apabila kemahiran khas melilit sasaran, ia akan menyerap 60% jumlah pertahanan sasaran dari Green Vine Snake sebagai kerosakan (kerosakan ini adalah kerosakan sebenar).',
		zawakeEffect = __data_t__zawakeEffect[24723],
		-- {79003, 1}
		zawakeEffectDesc = 'Additional effect: When the critical skill wraps around the target, it absorbs the target\'s health by 70% of Thanh Đằng Xà\'s total defense (this damage is true damage), if the user is at full health, the excess healing is transferred to the ally target with the lowest health rate.',
		zawakeEffectDesc_en = 'Additional effect: When the critical skill wraps around the target, it absorbs the target\'s health by 70% of Thanh Đằng Xà\'s total defense (this damage is true damage), if the user is at full health, the excess healing is transferred to the ally target with the lowest health rate.',
		zawakeEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อทักษะวิกฤตพันเป้าหมาย จะดูดซับพลังชีวิตของเป้าหมายโดยเท่ากับ 70% ของพลังป้องกันรวมของ Thanh Đằng Xà (ความเสียหายนี้เป็นความเสียหายจริง), หากผู้ใช้มีพลังชีวิตเต็ม จะโอนการฟื้นฟูส่วนเกินให้กับเป้าหมายพันธมิตรรายที่มีอัตราพลังชีวิตต่ำที่สุด',
		zawakeEffectDesc_in = 'Efek tambahan: Ketika skill kritis membungkus target, menyerap nyawa target sebesar 70% dari total pertahanan Thanh Đằng Xà (kerusakan ini adalah kerusakan nyata), jika pengguna dalam keadaan penuh darah, maka kelebihan penyembuhan dialihkan ke target sekutu dengan persentase darah terendah.',
		zawakeEffectDesc_ph = 'Karagdagang epekto: Kapag ang kritikal na kasanayan ay bumalot sa target, sumisipsip ng buhay ng target gamit ang 70% ng kabuuang depensa ng Thanh Đằng Xà (ang pinsalang ito ay totoong pinsala), kung ang sarili ay nasa buong buhay, ang labis na pagpapagaling ay ililipat sa kaalyadong target na may pinakamababang porsyento ng buhay.',
		zawakeEffectDesc_ma = 'Kesan tambahan: Apabila kemahiran kritikal melilit sasaran, menyedut nyawa sasaran dengan 70% jumlah pertahanan Thanh Đằng Xà (kerosakan ini adalah kerosakan sebenar), jika pengguna berada pada kesihatan penuh, lebihan pemulihan akan dipindahkan kepada sasaran sekutu yang mempunyai nisbah kesihatan terendah.',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: Khi kỹ năng chí mạng quấn lấy mục tiêu, hút sinh lực của mục tiêu bằng 70% tổng phòng thủ của Thanh Đằng Xà (sát thương này là sát thương thực), nếu bản thân đã đầy máu, thì chuyển lượng hồi phục dư thừa cho mục tiêu đồng minh có tỷ lệ máu thấp nhất',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Lifesteal increased to 70%, if self is at full HP, excess healing will be transferred to the ally with the lowest HP',
		zawakeSimpleDesc_en = 'Lifesteal increased to 70%, if self is at full HP, excess healing will be transferred to the ally with the lowest HP',
		zawakeSimpleDesc_th = 'การดูดเลือดเพิ่มขึ้นเป็น 70% หากตัวละครมี HP เต็ม การฟื้นฟูส่วนเกินจะส่งต่อให้พันธมิตรที่มี HP ต่ำที่สุด',
		zawakeSimpleDesc_in = 'Hisap nyawa meningkat menjadi 70%, jika HP penuh, penyembuhan berlebih akan ditransfer ke sekutu dengan HP terendah',
		zawakeSimpleDesc_ph = 'Tumaas ang lifesteal sa 70%, kung puno ang HP, ang sobrang heal ay ibibigay sa kakampi na may pinakamababang HP',
		zawakeSimpleDesc_ma = 'Penyerapan nyawa meningkat kepada 70%, jika HP penuh, penyembuhan berlebihan akan dipindahkan kepada sekutu dengan HP paling rendah',
		zawakeSimpleDesc_vn = 'Hấp thụ sinh lực tăng lên 70%, nếu bản thân đã đầy máu, lượng hồi máu dư thừa sẽ chuyển cho mục tiêu đồng minh có máu thấp nhất',
		upLvDesc = 'Fixed damage +144',
		upLvDesc_en = 'Fixed damage +144',
