	[24726] = {
		id = 24726,
		skillName_vn = 'Hát ngược',
		skillName_en = 'Sing backwards',
		skillName_th = 'ร้องเพลงย้อนกลับ',
		skillName_in = 'Bernyanyi terbalik',
		skillName_ph = 'Kumanta nang pabaliktad',
		skillName_ma = 'Menyanyi terbalik',
		skillName = 'Sing backwards',
		describe_vn = 'Miễn nhiễm với hiệu ứng tăng cường không phải do bản thân thêm vào, nếu bản thân nhận hiệu ứng tiêu cực sẽ chuyển hóa thành hiệu ứng tăng cường ngẫu nhiên;\nKỹ năng hào quang: Tăng sát thương kỹ năng hệ gió của toàn bộ đồng minh #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#',
		describe_en = 'Immune to buff effects not applied by oneself; if receiving negative effects, they will be converted into random buff effects; \n Aura skill: Increases wind attribute skill damage of all allies by $(10+skillLevel*0.1-0.1)$%.',
		describe_th = 'ภูมิคุ้มกันต่อเอฟเฟกต์บัฟที่ไม่ได้มาจากตัวเอง หากได้รับเอฟเฟกต์ลบจะถูกเปลี่ยนเป็นเอฟเฟกต์บัฟแบบสุ่ม; \n ทักษะออร์ร่า: เพิ่มความเสียหายจากทักษะธาตุลมของพันธมิตรทั้งหมด $ (10+skillLevel*0.1-0.1) $%.',
		describe_in = 'Kebal terhadap efek buff yang tidak diberikan oleh diri sendiri; jika menerima efek negatif, akan diubah menjadi efek buff acak; \n Skill aura: Meningkatkan kerusakan skill elemen angin untuk semua sekutu sebesar $(10+skillLevel*0.1-0.1)$%.',
		describe_ph = 'Immun sa mga buff effect na hindi galing sa sarili; kung makatanggap ng negative effect, ito ay magbabago sa random buff effect; \n Aura skill: Pinapataas ang wind attribute skill damage ng lahat ng alyado ng $(10+skillLevel*0.1-0.1)$%.',
		describe_ma = 'Kebal terhadap kesan peningkatan yang bukan diberikan sendiri; jika menerima kesan negatif, ia akan bertukar menjadi kesan peningkatan secara rawak; \n Kemahiran aura: Meningkatkan kerosakan kemahiran unsur angin semua sekutu sebanyak $(10+skillLevel*0.1-0.1)$%.',
		describe = 'Immune to buff effects not applied by oneself; if receiving negative effects, they will be converted into random buff effects; \n Aura skill: Increases wind attribute skill damage of all allies by $(10+skillLevel*0.1-0.1)$%.',
		simDesc_vn = 'Tất cả các hiệu ứng tiêu cực được áp dụng lên bản thân sẽ chuyển hóa thành các hiệu ứng tích cực ngẫu nhiên; các hiệu ứng tích cực do đồng minh áp dụng cho bản thân sẽ không có hiệu lực. Khi có mặt, sức mạnh của kỹ năng hệ gió tăng 15%.',
		simDesc_en = 'All negative effects applied to yourself will be transformed into random positive effects; positive effects applied to yourself by allies will have no effect. When present, the power of wind attribute skills increases by 15%.',
		simDesc_th = 'ผลเสียทั้งหมดที่ถูกใช้กับตัวคุณจะถูกเปลี่ยนเป็นผลดีแบบสุ่ม; ผลดีที่ถูกใช้กับตัวคุณโดยพันธมิตรจะไม่มีผล เมื่ออยู่ในสนาม พลังของสกิลธาตุลมจะเพิ่มขึ้น 15%.',
		simDesc_in = 'Semua efek negatif yang diterapkan pada diri sendiri akan diubah menjadi efek positif acak; efek positif yang diterapkan oleh sekutu pada diri sendiri tidak akan berpengaruh. Ketika hadir, kekuatan skill elemen angin meningkat sebesar 15%.',
		simDesc_ph = 'Lahat ng negatibong epekto na ipinapataw sa sarili ay magiging random na positibong epekto; ang positibong epekto na ipinapataw sa sarili ng mga kakampi ay walang bisa. Kapag naroroon, tumataas ang lakas ng kakayahan ng hangin ng 15%.',
		simDesc_ma = 'Semua kesan negatif yang dikenakan ke atas diri sendiri akan diubah menjadi kesan positif secara rawak; kesan positif yang dikenakan oleh sekutu ke atas diri sendiri tidak akan berkesan. Apabila hadir, kekuatan kemahiran unsur angin meningkat sebanyak 15%.',
		simDesc = 'All negative effects applied to yourself will be transformed into random positive effects; positive effects applied to yourself by allies will have no effect. When present, the power of wind attribute skills increases by 15%.',
		starEffect = __data_t__starEffect[24726],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sau khi chết, sẽ sao chép tất cả các hiệu ứng tăng cường của bản thân cho toàn bộ đồng đội, kéo dài 2 lượt.',
		starEffectDesc = 'Additional effect: After death, copies all self-enhancement effects to all teammates, lasting 2 turns.',
		starEffectDesc_en = 'Additional effect: After death, copies all self-enhancement effects to all teammates, lasting 2 turns.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: หลังจากตาย จะคัดลอกเอฟเฟกต์เสริมพลังทั้งหมดของตนไปยังเพื่อนร่วมทีมทุกคน เป็นเวลา 2 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Setelah mati, menyalin semua efek peningkatan diri ke seluruh rekan tim, berlangsung selama 2 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Pagkatapos mamatay, kinokopya ang lahat ng mga epekto ng pagpapahusay sa sarili para sa lahat ng kakampi, tumatagal ng 2 na pag-ikot.',
		starEffectDesc_ma = 'Kesan tambahan: Selepas mati, akan menyalin semua kesan peningkatan diri kepada semua rakan sepasukan, berlangsung selama 2 pusingan.',
		zawakeEffect = __data_t__zawakeEffect[24726],
		-- {79004, 1}
		zawakeEffectDesc = 'Additional effect: Upon death, absorbs a random negative effect from all allies for oneself, and copies all beneficial effects of oneself to all allies, lasting 2 turns',
		zawakeEffectDesc_en = 'Additional effect: Upon death, absorbs a random negative effect from all allies for oneself, and copies all beneficial effects of oneself to all allies, lasting 2 turns',
		zawakeEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อเสียชีวิต ดูดซับผลกระทบเชิงลบแบบสุ่มจากเพื่อนร่วมทีมทั้งหมดสำหรับตัวเอง และคัดลอกผลกระทบที่เป็นประโยชน์ทั้งหมดของตัวเองไปยังเพื่อนร่วมทีมทั้งหมด เป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Efek tambahan: Setelah mati, menyerap efek negatif acak dari semua sekutu untuk diri sendiri, dan menyalin semua efek menguntungkan milik diri sendiri ke semua sekutu, berlangsung selama 2 giliran',
		zawakeEffectDesc_ph = 'Karagdagang epekto: Pagkatapos mamatay, sumisipsip ng isang random na negatibong epekto mula sa lahat ng kakampi para sa sarili, at kinokopya ang lahat ng kapaki-pakinabang na epekto ng sarili para sa lahat ng kakampi, tumatagal ng 2 na turn',
		zawakeEffectDesc_ma = 'Kesan tambahan: Selepas mati, menyerap kesan negatif rawak daripada semua sekutu untuk diri sendiri, dan menyalin semua kesan bermanfaat diri sendiri kepada semua sekutu, berlangsung selama 2 pusingan',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: Sau khi chết, hấp thụ một hiệu ứng tiêu cực ngẫu nhiên từ toàn bộ đồng minh cho bản thân, và sao chép tất cả các hiệu ứng có lợi của bản thân cho toàn bộ đồng minh, kéo dài 2 lượt',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#After death, absorb 1 random negative effect from all allies to self',
		zawakeSimpleDesc_en = '#C0x5c9970#After death, absorb 1 random negative effect from all allies to self',
		zawakeSimpleDesc_th = '#C0x5c9970#หลังจากตาย ดูดซับผลลบแบบสุ่ม 1 อย่างจากพันธมิตรทั้งหมดมายังตัวเอง',
		zawakeSimpleDesc_in = '#C0x5c9970#Setelah mati, menyerap 1 efek negatif acak dari semua sekutu ke diri sendiri',
		zawakeSimpleDesc_ph = '#C0x5c9970#Kapag namatay, sumisipsip ng 1 random na negatibong epekto mula sa lahat ng kakampi papunta sa sarili',
		zawakeSimpleDesc_ma = '#C0x5c9970#Selepas mati, serap 1 kesan negatif rawak daripada semua sekutu kepada diri sendiri',
		zawakeSimpleDesc_vn = '#C0x5c9970#Sau khi chết, hấp thụ 1 hiệu ứng tiêu cực ngẫu nhiên từ toàn bộ đồng minh về bản thân',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
