	[24733] = {
		id = 24733,
		skillName_vn = 'Ngục giam linh hồn cây',
		skillName_en = 'Soul Prison',
		skillName_th = 'คุกวิญญาณ',
		skillName_in = 'Penjara Jiwa',
		skillName_ph = 'Bilangguan ng Kaluluwa',
		skillName_ma = 'Penjara Jiwa',
		skillName = 'Soul Prison',
		describe_vn = 'Quân chủ xà điều khiển dây leo tạo thành nhà tù kiên cố, sau đó nhà tù phát nổ gây Sát Thương Phép Thuật#C0x3D8A99#160% Phép Công#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54##C0x5B545B# lên toàn bộ mục tiêu kẻ địch, đồng thời gieo hạt giống dây leo dưới chân toàn bộ kẻ địch, sau lượt hành động của mục tiêu, dây leo mọc lên và [quấn chặt] mục tiêu trong 1 lượt',
		describe_en = 'The Snake Lord controls vines to form a sturdy prison, then the prison explodes causing Magic Damage #C0x3D8A99# 160% Magic Attack #C0x5B545B# +$(skillLevel*4*36)$ #C0xF13B54##C0x5B545B# to all enemy targets, simultaneously planting vine seeds at the feet of all enemies. After the target\'s action turn, the vines grow and [bind] the target for 1 turn.',
		describe_th = 'ผู้นำงูควบคุมเถาวัลย์สร้างเป็นคุกที่แข็งแกร่ง จากนั้นคุกระเบิดทำให้เกิดความเสียหายเวทมนตร์ #C0x3D8A99# 160% พลังโจมตีเวทมนตร์ #C0x5B545B# +$(skillLevel*4*36)$ #C0xF13B54##C0x5B545B# แก่ศัตรูทั้งหมด พร้อมกันนั้นยังปลูกเมล็ดเถาวัลย์ที่เท้าของศัตรูทั้งหมด หลังจากรอบการกระทำของเป้าหมาย เถาวัลย์จะงอกขึ้นและ [พันธนาการ] เป้าหมายเป็นเวลา 1 เทิร์น',
		describe_in = 'Pemimpin Ular mengendalikan tanaman merambat untuk membentuk penjara yang kokoh, kemudian penjara tersebut meledak menyebabkan Kerusakan Sihir #C0x3D8A99# 160% Serangan Sihir #C0x5B545B# +$(skillLevel*4*36)$ #C0xF13B54##C0x5B545B# ke semua target musuh, sekaligus menanam benih tanaman merambat di kaki semua musuh. Setelah giliran aksi target, tanaman merambat tumbuh dan [melilit] target selama 1 giliran.',
		describe_ph = 'Kinokontrol ng Hari ng Ahas ang mga baging upang bumuo ng matibay na bilangguan, pagkatapos ay sumabog ang bilangguan na nagdudulot ng Pinsalang Magic #C0x3D8A99# 160% Magic Attack #C0x5B545B# +$(skillLevel*4*36)$ #C0xF13B54##C0x5B545B# sa lahat ng kalaban, kasabay nito ay nagtatanim ng buto ng baging sa mga paa ng lahat ng kalaban. Pagkatapos ng turn ng aksyon ng target, tumutubo ang mga baging at [nagmumkód] sa target sa loob ng 1 turn.',
		describe_ma = 'Pemimpin Ular mengawal tali-tali memanjat membentuk penjara kukuh, kemudian penjara itu meletup menyebabkan Kerosakan Sihir #C0x3D8A99# 160% Serangan Sihir #C0x5B545B# +$(skillLevel*4*36)$ #C0xF13B54##C0x5B545B# kepada semua sasaran musuh, serentak menabur benih tali-tali memanjat di kaki semua musuh. Selepas giliran tindakan sasaran, tali-tali memanjat tumbuh dan [membelit] sasaran selama 1 giliran.',
		describe = 'The Snake Lord controls vines to form a sturdy prison, then the prison explodes causing Magic Damage #C0x3D8A99# 160% Magic Attack #C0x5B545B# +$(skillLevel*4*36)$ #C0xF13B54##C0x5B545B# to all enemy targets, simultaneously planting vine seeds at the feet of all enemies. After the target\'s action turn, the vines grow and [bind] the target for 1 turn.',
		simDesc_vn = 'Quân Chủ Xà điều khiển dây leo tạo thành một nhà tù không thể phá vỡ, sau đó nhà tù sẽ phát nổ gây sát thương cho toàn bộ mục tiêu của đối phương, và sau khi mục tiêu hành động ở lượt tiếp theo sẽ bị quấn chặt.',
		simDesc_en = 'The Serpent Monarch controls vines to create an unbreakable prison, which then explodes to deal damage to all enemy targets, and after the targets act on their next turn, they will be tightly bound.',
		simDesc_th = 'จ้าวราชาอสรพิษควบคุมเถาวัลย์สร้างคุกที่ไม่อาจทำลายได้ จากนั้นคุกจะระเบิดทำความเสียหายกับศัตรูทั้งหมด และหลังจากเป้าหมายทำการในรอบถัดไปจะถูกมัดแน่นหนา',
		simDesc_in = 'Penguasa Ular mengendalikan sulur untuk membentuk penjara yang tak bisa dihancurkan, lalu penjara tersebut meledak dan memberikan kerusakan kepada semua target musuh, dan setelah target bertindak di giliran berikutnya, mereka akan terikat erat.',
		simDesc_ph = 'Kinokontrol ng Tagapangulo ng Ahas ang mga baging upang makabuo ng isang hindi mapipinsalang kulungan, na pagkatapos ay sasabog upang makapagdulot ng pinsala sa lahat ng kalaban, at pagkatapos kumilos ang mga target sa kanilang susunod na turn ay mahihigpit silang balutin.',
		simDesc_ma = 'Raja Ular mengawal tali pokok memanjat untuk membentuk penjara yang tidak dapat dipecahkan, kemudian penjara itu akan meletup menyebabkan kerosakan kepada semua sasaran musuh, dan selepas sasaran bertindak pada giliran seterusnya, mereka akan terikat rapat.',
		simDesc = 'The Serpent Monarch controls vines to create an unbreakable prison, which then explodes to deal damage to all enemy targets, and after the targets act on their next turn, they will be tightly bound.',
		starEffect = __data_t__starEffect[24733],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi kỹ năng đặc biệt quấn lấy mục tiêu, sẽ hút 60% tổng phòng thủ của mục tiêu từ Ruler Snake thành sát thương (sát thương này là sát thương thật).',
		starEffectDesc = 'Additional effect: When the special skill wraps around the target, it will absorb 60% of the target\'s total defense from Ruler Snake as damage (this damage is true damage).',
		starEffectDesc_en = 'Additional effect: When the special skill wraps around the target, it will absorb 60% of the target\'s total defense from Ruler Snake as damage (this damage is true damage).',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อทักษะพิเศษพันรอบเป้าหมาย จะดูดซับ 60% ของการป้องกันทั้งหมดของเป้าหมายจาก Ruler Snake เป็นความเสียหาย (ความเสียหายนั้นเป็นความเสียหายโดยตรง).',
		starEffectDesc_in = 'Efek tambahan: Saat skill khusus membungkus target, akan menyerap 60% total pertahanan target dari Ruler Snake sebagai damage (damage ini adalah true damage).',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag ang espesyal na kakayahan ay paikot na pumapalibot sa target, sumisipsip ito ng 60% ng kabuuang depensa ng target mula sa Ruler Snake bilang pinsala (ang pinsalang ito ay totoong pinsala).',
		starEffectDesc_ma = 'Kesan tambahan: Apabila kemahiran istimewa melilit sasaran, ia akan menyerap 60% jumlah pertahanan sasaran dari Ruler Snake sebagai kerosakan (kerosakan ini adalah kerosakan sebenar).',
		zawakeEffect = __data_t__zawakeEffect[24733],
		-- {79003, 1}
		zawakeEffectDesc = 'Additional effect: When a critical skill wraps around the target, it drains the target\'s health by 70% of the Snake Monarch\'s total defense (this damage is true damage), if the user is already at full health, excess healing is transferred to the ally with the lowest health percentage',
		zawakeEffectDesc_en = 'Additional effect: When a critical skill wraps around the target, it drains the target\'s health by 70% of the Snake Monarch\'s total defense (this damage is true damage), if the user is already at full health, excess healing is transferred to the ally with the lowest health percentage',
		zawakeEffectDesc_th = 'ผลเสริม: เมื่อทักษะคริติคอลพันเป้าหมาย จะดูดชีวิตของเป้าหมายโดยคิดเป็น 70% ของเกราะรวมของเจ้าผู้ครองงู (ความเสียหายนี้เป็นความเสียหายที่แท้จริง), หากตัวเองมีพลังชีวิตเต็ม จะเปลี่ยนการฟื้นฟูส่วนเกินไปยังพันธมิตรที่มีเปอร์เซ็นต์พลังชีวิตต่ำที่สุด',
		zawakeEffectDesc_in = 'Efek tambahan: Ketika keterampilan kritis membungkus target, menyedot kesehatan target sebesar 70% dari total pertahanan Raja Ular (kerusakan ini adalah kerusakan nyata), jika pengguna sudah penuh darah, maka kelebihan penyembuhan dialihkan ke sekutu dengan persentase darah terendah',
		zawakeEffectDesc_ph = 'Karagdagang epekto: Kapag ang critical skill ay pumapalibot sa target, sumisipsip ito ng buhay ng target gamit ang 70% ng kabuuang depensa ng Snake Monarch (ang pinsalang ito ay tunay na pinsala), kung ang sarili ay puno na sa buhay, ang sobrang paggaling ay ililipat sa kaalyadong may pinakamababang porsyento ng buhay',
		zawakeEffectDesc_ma = 'Kesan tambahan: Apabila kemahiran kritikal membelit sasaran, ia menyedut tenaga hidup sasaran sebanyak 70% daripada jumlah pertahanan Raja Ular (kerosakan ini adalah kerosakan sebenar), jika diri sudah penuh darah, maka ‘healing’ lebihan akan dipindahkan kepada sekutu yang mempunyai peratusan darah terendah',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: Khi kỹ năng chí mạng quấn lấy mục tiêu, hút sinh lực của mục tiêu bằng 70% tổng phòng thủ của Quân chủ xà (sát thương này là sát thương thực), nếu bản thân đã đầy máu, thì chuyển lượng hồi phục dư thừa cho mục tiêu đồng minh có tỷ lệ máu thấp nhất',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Lifesteal increases to 70%, if self is at full HP, the excess healing will be transferred to the ally with the lowest HP',
		zawakeSimpleDesc_en = 'Lifesteal increases to 70%, if self is at full HP, the excess healing will be transferred to the ally with the lowest HP',
		zawakeSimpleDesc_th = 'อัตราการดูดเลือดเพิ่มขึ้นเป็น 70% หาก HP เต็ม การฟื้นฟูส่วนเกินจะส่งต่อให้พันธมิตรที่มี HP ต่ำที่สุด',
		zawakeSimpleDesc_in = 'Lifesteal meningkat menjadi 70%, jika HP penuh, penyembuhan berlebih akan diberikan kepada sekutu dengan HP terendah',
		zawakeSimpleDesc_ph = 'Ang lifesteal ay tumataas sa 70%, kung puno ang HP, ang sobrang healing ay ililipat sa kakampi na may pinakamababang HP',
		zawakeSimpleDesc_ma = 'Penyerapan nyawa meningkat kepada 70%, jika HP penuh, penyembuhan berlebihan akan dipindahkan kepada sekutu dengan HP paling rendah',
		zawakeSimpleDesc_vn = 'Hấp thụ sinh lực tăng lên 70%, nếu bản thân đã đầy máu, lượng hồi máu dư thừa sẽ chuyển cho mục tiêu đồng minh có máu thấp nhất',
