	[24736] = {
		id = 24736,
		skillName_vn = 'Hát ngược',
		skillName_en = 'Sing backwards',
		skillName_th = 'ร้องเพลงย้อนกลับ',
		skillName_in = 'Bernyanyi mundur',
		skillName_ph = 'Kumanta nang pababalik',
		skillName_ma = 'Menyanyi secara terbalik',
		skillName = 'Sing backwards',
		describe_vn = 'Miễn nhiễm với hiệu ứng tăng cường không phải do bản thân thêm vào, nếu bản thân nhận hiệu ứng tiêu cực sẽ chuyển hóa thành hiệu ứng tăng cường ngẫu nhiên;\nKỹ năng hào quang: Tăng sát thương kỹ năng hệ gió của toàn bộ đồng minh #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#',
		describe_en = 'Immune to enhancement effects not applied by oneself; if oneself receives a negative effect, it will be converted into a random enhancement effect; \n Aura Skill: Increases wind attribute skill damage of all allies by #(10+skillLevel*0.1-0.1)%#.',
		describe_th = 'ภูมิคุ้มกันต่อเอฟเฟกต์เสริมที่ไม่ได้มาจากตัวเอง; หากตัวเองได้รับเอฟเฟกต์ลบ จะถูกเปลี่ยนเป็นเอฟเฟกต์เสริมแบบสุ่ม; \n ทักษะออร่า: เพิ่มความเสียหายทักษะธาตุลมของพันธมิตรทั้งหมด #(10+skillLevel*0.1-0.1)%#',
		describe_in = 'Kebal terhadap efek peningkatan yang tidak diberikan oleh diri sendiri; jika diri sendiri menerima efek negatif, akan diubah menjadi efek peningkatan acak; \n Skill Aura: Meningkatkan kerusakan skill elemen angin dari semua sekutu sebesar #(10+skillLevel*0.1-0.1)%#.',
		describe_ph = 'Immun sa mga enhancement effect na hindi galing sa sarili; kapag nakatanggap ng negative effect ang sarili, ito ay magbabago sa isang random enhancement effect; \n Aura Skill: Nagdaragdag ng wind element skill damage sa lahat ng kaalyado ng #(10+skillLevel*0.1-0.1)%#.',
		describe_ma = 'Kebal kepada kesan peningkatan yang bukan daripada diri sendiri; jika diri sendiri menerima kesan negatif, ia akan ditukar menjadi kesan peningkatan rawak; \n Kemahiran Aura: Meningkatkan kerosakan kemahiran unsur angin semua sekutu sebanyak #(10+skillLevel*0.1-0.1)%#.',
		describe = 'Immune to enhancement effects not applied by oneself; if oneself receives a negative effect, it will be converted into a random enhancement effect; \n Aura Skill: Increases wind attribute skill damage of all allies by #(10+skillLevel*0.1-0.1)%#.',
		simDesc_vn = 'Tất cả các hiệu ứng tiêu cực được áp dụng lên bản thân sẽ chuyển hóa thành các hiệu ứng tích cực ngẫu nhiên; các hiệu ứng tích cực do đồng minh áp dụng cho bản thân sẽ không có hiệu lực. Khi có mặt, sức mạnh của kỹ năng hệ gió tăng 15%.',
		simDesc_en = 'All negative effects applied to yourself will be converted into random positive effects; positive effects applied to yourself by allies will have no effect. While present, the power of wind-element skills increases by 15%.',
		simDesc_th = 'เอฟเฟกต์ลบทั้งหมดที่ถูกใช้กับตัวเองจะถูกเปลี่ยนเป็นเอฟเฟกต์บวกแบบสุ่ม; เอฟเฟกต์บวกที่พันธมิตรใช้กับตัวเองจะไม่มีผล เมื่ออยู่ในสถานะ พลังของสกิลธาตุลมจะเพิ่มขึ้น 15%',
		simDesc_in = 'Semua efek negatif yang diterapkan pada diri sendiri akan diubah menjadi efek positif acak; efek positif yang diterapkan oleh sekutu pada diri sendiri tidak akan berpengaruh. Saat hadir, kekuatan skill elemen angin meningkat 15%.',
		simDesc_ph = 'Ang lahat ng negative effects na inilapat sa sarili ay magiging random positive effects; ang mga positive effects na inilapat ng mga kaalyado sa sarili ay walang bisa. Kapag naroroon, tumataas ang lakas ng mga wind-element skills ng 15%.',
		simDesc_ma = 'Semua kesan negatif yang dikenakan ke diri sendiri akan bertukar menjadi kesan positif secara rawak; kesan positif yang dikenakan oleh sekutu kepada diri sendiri tidak akan berkesan. Semasa hadir, kekuatan kemahiran elemen angin meningkat 15%.',
		simDesc = 'All negative effects applied to yourself will be converted into random positive effects; positive effects applied to yourself by allies will have no effect. While present, the power of wind-element skills increases by 15%.',
		starEffect = __data_t__starEffect[24736],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sau khi chết, sẽ sao chép tất cả các hiệu ứng tăng cường của bản thân cho toàn bộ đồng đội, kéo dài 2 lượt.',
		starEffectDesc = 'Additional effect: After death, copies all self-enhancement effects to all teammates, lasting 2 turns.',
		starEffectDesc_en = 'Additional effect: After death, copies all self-enhancement effects to all teammates, lasting 2 turns.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: หลังจากตาย จะคัดลอกเอฟเฟกต์เสริมพลังทั้งหมดของตนไปยังเพื่อนร่วมทีมทุกคน เป็นเวลา 2 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Setelah mati, menyalin semua efek peningkatan diri ke seluruh rekan tim, berlangsung selama 2 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Pagkatapos mamatay, kinokopya ang lahat ng mga epekto ng pagpapahusay sa sarili para sa lahat ng kakampi, tumatagal ng 2 na pag-ikot.',
		starEffectDesc_ma = 'Kesan tambahan: Selepas mati, akan menyalin semua kesan peningkatan diri kepada semua rakan sepasukan, berlangsung selama 2 pusingan.',
		zawakeEffect = __data_t__zawakeEffect[24736],
		-- {79004, 1}
		zawakeEffectDesc = 'Additional effect: Upon death, absorbs a random negative effect from all allies for oneself, and copies all beneficial effects of oneself to all allies, lasting 2 turns',
