	[24823] = {
		id = 24823,
		skillName_vn = 'Chém xoáy lửa',
		skillName_en = 'Flaming Slash',
		skillName_th = 'ฟันเปลวไฟ',
		skillName_in = 'Iblis Tebas',
		skillName_ph = 'Punit na Apoy',
		skillName_ma = 'Sula Api',
		skillName = 'Flaming Slash',
		describe_vn = 'Heo chiên xoay lên không trung rồi đánh xuống mục tiêu, sử dụng sóng lửa dư âm tấn công mục tiêu hàng ngang của kẻ địch, gây Sát Thương Vật Lý#C0xE69900#260% vật công#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54##C0x5B545B#, nếu lần tấn công này phá vỡ lá chắn, sẽ gây thêm sát thương thực bằng 15% máu tối đa của Heo chiên lên kẻ địch',
		describe_en = 'The fried pig spins up into the air and then strikes down on the target, using the lingering flame wave to attack a horizontal line of enemies, dealing Physical Damage#C0xE69900#260% attack power#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54##C0x5B545B#. If this attack breaks the shield, it will deal additional true damage equal to 15% of the fried pig\'s maximum health to the enemy.',
		describe_th = 'หมูทอดหมุนขึ้นกลางอากาศแล้วโจมตีลงบนเป้าหมาย ใช้คลื่นไฟร่องรอยโจมตีศัตรูเป็นแนวนอน สร้างความเสียหายทางกายภาพ#C0xE69900#260% พลังโจมตี#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54##C0x5B545B# หากการโจมตีนี้ทำลายโล่ได้ จะสร้างความเสียหายแท้เพิ่มเติมเป็น 15% ของพลังชีวิตสูงสุดของหมูทอดต่อศัตรู',
		describe_in = 'Babi goreng berputar ke udara lalu menyerang ke bawah target, menggunakan gelombang api residual untuk menyerang baris horizontal musuh, memberikan Damage Fisik#C0xE69900#260% kekuatan serang#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54##C0x5B545B#. Jika serangan ini memecahkan perisai, akan memberikan damage nyata tambahan sebesar 15% dari total darah maksimum babi goreng ke musuh.',
		describe_ph = 'Ang pritong baboy ay umiikot pataas sa hangin at pagkatapos ay bumabagsak sa target, gumagamit ng residual na alon ng apoy para atakihin ang pahalang na hanay ng mga kaaway, na nagdudulot ng Pisikal na Pinsala#C0xE69900#260% lakas ng atake#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54##C0x5B545B#. Kung ang pag-atakeng ito ay makakabasag sa kalasag, magdudulot ito ng karagdagang tunay na pinsala na katumbas ng 15% ng pinakamataas na buhay ng pritong baboy sa kaaway.',
		describe_ma = 'Babi goreng berpusing ke udara kemudian menyerang sasaran ke bawah, menggunakan gelombang api tinggalan untuk menyerang barisan mendatar musuh, menyebabkan Kerosakan Fizikal#C0xE69900#260% kuasa serangan#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54##C0x5B545B#. Jika serangan ini memecahkan perisai, ia akan menyebabkan kerosakan nyata tambahan sebanyak 15% daripada jumlah kesihatan maksimum babi goreng ke musuh.',
		describe = 'The fried pig spins up into the air and then strikes down on the target, using the lingering flame wave to attack a horizontal line of enemies, dealing Physical Damage#C0xE69900#260% attack power#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54##C0x5B545B#. If this attack breaks the shield, it will deal additional true damage equal to 15% of the fried pig\'s maximum health to the enemy.',
		simDesc_vn = 'Chiên Chiên Trư xoay lên không trung rồi chém vào mục tiêu, sử dụng sóng lửa dư để tấn công các mục tiêu hàng của đối phương; nếu đòn tấn công này phá vỡ khiên, sẽ gây thêm một lượng sát thương thực cho kẻ thù.',
		simDesc_en = 'Chiên Chiên Trư spins into the air and slashes at the target, using residual flame waves to attack enemy\'s row targets; if this attack breaks the shield, it deals additional true damage to the enemy.',
		simDesc_th = 'เฉียน เฉียน จู หมุนขึ้นกลางอากาศแล้วฟันใส่เป้าหมาย โดยใช้คลื่นไฟที่เหลือโจมตีเป้าหมายในแถวของศัตรู; หากการโจมตีนี้ทำลายโล่ จะสร้างความเสียหายจริงเพิ่มเติมแก่ศัตรู',
		simDesc_in = 'Chiên Chiên Trư berputar ke udara lalu menyerang target, menggunakan gelombang api sisa untuk menyerang target bar musuh; jika serangan ini memecahkan perisai, akan memberikan kerusakan nyata tambahan kepada musuh.',
		simDesc_ph = 'Si Chiên Chiên Trư ay pumaling sa hangin at inaatake ang target gamit ang leftover flame waves para atakihin ang row ng kalaban; kung ang atakeng ito ay nakabasag ng kalasag, magbibigay ito ng karagdagang tunay na pinsala sa kalaban.',
		simDesc_ma = 'Chiên Chiên Trư berpusing ke udara kemudian menebas sasaran, menggunakan gelombang api baki untuk menyerang sasaran bar musuh; jika serangan ini memecahkan perisai, akan menyebabkan kerosakan sebenar tambahan kepada musuh.',
		simDesc = 'Chiên Chiên Trư spins into the air and slashes at the target, using residual flame waves to attack enemy\'s row targets; if this attack breaks the shield, it deals additional true damage to the enemy.',
		starEffect = __data_t__starEffect[24823],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Sau khi phá vỡ lá chắn, sát thương bổ sung sẽ tăng lên 30% máu tối đa của Fire King thành sát thương thật',
		starEffectDesc = 'Enhance effect: After breaking the shield, additional damage will increase by 30% of the Fire King\'s maximum HP as true damage',
		starEffectDesc_en = 'Enhance effect: After breaking the shield, additional damage will increase by 30% of the Fire King\'s maximum HP as true damage',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: หลังจากทำลายโล่ ความเสียหายเพิ่มเติมจะเพิ่มขึ้น 30% ของพลังชีวิตสูงสุดของ Fire King เป็นความเสียหายจริง',
		starEffectDesc_in = 'Tingkatkan efek: Setelah memecahkan perisai, kerusakan tambahan akan meningkat sebesar 30% dari HP maksimum Fire King sebagai kerusakan nyata',
		starEffectDesc_ph = 'Palakasin ang epekto: Pagkatapos mabasag ang kalasag, ang karagdagang pinsala ay tataas ng 30% ng maximum na HP ng Fire King bilang totoong pinsala',
		starEffectDesc_ma = 'Tingkatkan kesan: Selepas memecahkan perisai, kerosakan tambahan akan meningkat sebanyak 30% daripada HP maksima Fire King sebagai kerosakan sebenar',
		zawakeEffect = __data_t__zawakeEffect[24823],
		-- {79003, 1}
		zawakeEffectDesc = 'Enhancement Effect: After breaking the shield, additional damage increases to true damage equal to 45% of the Blaze King’s maximum HP.',
		zawakeEffectDesc_en = 'Enhancement Effect: After breaking the shield, additional damage increases to true damage equal to 45% of the Blaze King’s maximum HP.',
		zawakeEffectDesc_th = 'ผลการเสริมพลัง: หลังจากทำลายโล่ ความเสียหายเพิ่มเติมจะเปลี่ยนเป็นความเสียหายจริงเท่ากับ 45% ของพลังชีวิตสูงสุดของราชาเปลวไฟ',
		zawakeEffectDesc_in = 'Efek Peningkatan: Setelah menghancurkan perisai, kerusakan tambahan meningkat menjadi kerusakan nyata sebesar 45% dari HP maksimum Raja Api.',
		zawakeEffectDesc_ph = 'Epekto ng Pagpapalakas: Pagkatapos masira ang kalasag, tumataas ang karagdagang pinsala sa tunay na pinsala na katumbas ng 45% ng pinakamataas na HP ng Blaze King.',
		zawakeEffectDesc_ma = 'Kesan Peningkatan: Selepas memecahkan perisai, kerosakan tambahan meningkat menjadi kerosakan sebenar sebanyak 45% daripada HP maksimum Raja Api.',
