	[24932] = {
		id = 24932,
		skillName_vn = 'Kho báu của vua',
		skillName_en = 'The king\'s treasure',
		skillName_th = 'สมบัติของกษัตริย์',
		skillName_in = 'Harta Raja',
		skillName_ph = 'Kayamanan ng hari',
		skillName_ma = 'Harta Raja',
		skillName = 'The king\'s treasure',
		describe_vn = 'Gilgamesh giải phóng Kho báu của Nhà vua và tấn công hàng loạt mục tiêu của kẻ địch, gây ra #C0x3D8A99#190% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$ của #C0xF13B54# sát thương phép#C0x5B545B#, thêm 1 lớp [vết thương] cho mỗi mục tiêu trong 3 lượt và giảm 30% tỷ lệ chí mạng của mục tiêu đó trong 2 lượt #F10# #F40#[Vết thương]: Hiệu ứng tiêu cực, giảm khả năng hồi phục 20%, dễ bị tổn thương 5%, tăng sát thương chảy máu và rách da thêm 20%, có thể cộng dồn 3 lần',
		describe_en = 'Gilgamesh unleashes the King\'s Treasure and attacks multiple enemy targets, dealing #C0x3D8A99#190% Magical Damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# magic damage#C0x5B545B#, applying 1 layer of [Wound] to each target for 3 turns and reducing their critical hit rate by 30% for 2 turns. #F10# #F40#[Wound]: A negative effect that reduces healing by 20%, increases vulnerability by 5%, and increases bleed and flesh tear damage by 20%, stackable up to 3 times.',
		describe_th = 'กิลกาเมชปลดปล่อยสมบัติของราชาและโจมตีเป้าหมายศัตรูหลายตัว ทำให้เกิด #C0x3D8A99#190% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*48)$ ของ #C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# เพิ่ม 1 ชั้น [แผล] ให้แต่ละเป้าหมายเป็นเวลา 3 เทิร์น และลดอัตราคริติคอลของเป้าหมายลง 30% เป็นเวลา 2 เทิร์น #F10# #F40#[แผล]: ผลลบ ลดการฟื้นฟู 20%, เพิ่มความเปราะบาง 5%, เพิ่มความเสียหายจากเลือดออกและบาดแผลผิวหนังอีก 20%, ซ้อนทับได้สูงสุด 3 ครั้ง',
		describe_in = 'Gilgamesh membebaskan Harta Raja dan menyerang banyak target musuh, memberikan #C0x3D8A99#190% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54# kerusakan sihir#C0x5B545B#, menambahkan 1 lapisan [Luka] pada setiap target selama 3 giliran dan mengurangi tingkat kritikal target sebesar 30% selama 2 giliran. #F10# #F40#[Luka]: Efek negatif yang mengurangi penyembuhan sebesar 20%, meningkatkan kerentanan sebesar 5%, meningkatkan kerusakan pendarahan dan robek kulit sebesar 20%, dapat bertumpuk hingga 3 kali.',
		describe_ph = 'Pinakawalan ni Gilgamesh ang Kayamanan ng Hari kag atakehon ang madamo nga target sang kalaban, nagahatag #C0x3D8A99#190% nga Magic Damage#C0x5B545B#+$(skillLevel*4*48)$ sang #C0xF13B54# magic damage#C0x5B545B#, nagadugang 1 ka layer sang [Bakas sang Samad] sa kada target sa sulod sang 3 ka turno kag nagapakunhod sang 30% sang critical rate sang target sa sulod sang 2 ka turno. #F10# #F40#[Bakas sang Samad]: Negatibo nga epekto, nagapakunhod sang pag-ayo sang 20%, nagapataas sang kahuyang sang 5%, nagapataas sang dugo kag garas nga damage sang 20%, pwede mag-stack up to 3 ka beses.',
		describe_ma = 'Gilgamesh melepaskan Harta Raja dan menyerang pelbagai sasaran musuh, menyebabkan #C0x3D8A99#190% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*48)$ daripada #C0xF13B54# kerosakan magik#C0x5B545B#, menambah 1 lapisan [Luka] pada setiap sasaran selama 3 pusingan dan mengurangkan kadar kritikal sasaran sebanyak 30% selama 2 pusingan. #F10# #F40#[Luka]: Kesan negatif yang mengurangkan pemulihan sebanyak 20%, meningkatkan kerentanan sebanyak 5%, meningkatkan kerosakan pendarahan dan koyakan kulit sebanyak 20%, boleh bertindih sehingga 3 kali.',
		describe = 'Gilgamesh unleashes the King\'s Treasure and attacks multiple enemy targets, dealing #C0x3D8A99#190% Magical Damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# magic damage#C0x5B545B#, applying 1 layer of [Wound] to each target for 3 turns and reducing their critical hit rate by 30% for 2 turns. #F10# #F40#[Wound]: A negative effect that reduces healing by 20%, increases vulnerability by 5%, and increases bleed and flesh tear damage by 20%, stackable up to 3 times.',
		simDesc_vn = 'Gilgamesh giải phóng Kho báu của Nhà vua và tấn công hàng mục tiêu của kẻ thù.',
		simDesc_en = 'Gilgamesh unleashes the King\'s Treasure and attacks the enemy\'s targets.',
