	[24936] = {
		id = 24936,
		skillName_vn = 'Cơn thịnh nộ của Vua Anh Hùng',
		skillName_en = 'The Wrath of the Hero King',
		skillName_th = 'ความโกรธแค้นของพระราชาผู้กล้า',
		skillName_in = 'Kemarahan Raja Pahlawan',
		skillName_ph = 'Ang Galit ng Hari ng Bayani',
		skillName_ma = 'Kemarahan Raja Wira',
		skillName = 'The Wrath of the Hero King',
		describe_vn = '#L10#Wrath of the King of Heroes: #L0#Khi bị sát thương bởi đòn tấn công chủ động không có đòn chí mạng, anh ta sẽ ngay lập tức sử dụng đòn đánh thường để tấn công một đơn vị kẻ địch ngẫu nhiên #F10# #F40##L10#Bảo Khí: #L0# mang 1 [Bảo Khí] khi vào sân. Nếu bạn mất [Bảo Khí], bạn sẽ lấy lại một [Bảo Khí] sau 3 lượt #F10# #F40# [Bảo Khí]: Hiệu ứng đặc biệt, không thể bị xua tan, tối đa 1. Khi bạn bị tấn công chủ động, nếu thuộc tính kiềm chế không được kích hoạt, đòn tấn công này không thể là đòn chí mạng; sau khi bạn bị tấn công tích cực, một lớp [Vết thương] sẽ được thêm vào mục tiêu trong 3 lượt; bản thân Khi nhận sát thương tấn công chủ động chí mạng, hãy sử dụng [Bảo Khí] để vô hiệu hóa đòn tấn công và phục hồi lượng máu đã mất của một người #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#',
		describe_en = 'Wrath of the King of Heroes: When taking damage from an active attack that is not a critical hit, he will immediately use a normal attack to strike a random enemy unit.  Aura: Carries 1 [Aura] upon entering the battlefield. If you lose [Aura], you will recover one [Aura] after 3 turns.  [Aura]: A special effect that cannot be dispelled, max 1. When attacked actively, if the restraint attribute is not triggered, the attack cannot be a critical hit; after being attacked actively, a layer of [Wound] is added to the target for 3 turns; when receiving critical active attack damage, use [Aura] to nullify the attack and recover the lost HP by one ally. $(30+skillLevel*0.3-0.3)$%',
		describe_th = 'ความโกรธของราชาผู้กล้า: เมื่อได้รับความเสียหายจากการโจมตีที่ทำงานโดยตรงซึ่งไม่ใช่การโจมตีคริติคัล เขาจะใช้การโจมตีปกติทันทีเพื่อโจมตีศัตรูแบบสุ่ม  ออร่า: ถือ 1 [ออร่า] เมื่อเข้าสู่สนาม หากคุณสูญเสีย [ออร่า] คุณจะได้รับคืน 1 [ออร่า] หลังจาก 3 เทิร์น  [ออร่า]: ผลพิเศษที่ไม่สามารถลบออกได้ สูงสุด 1 เมื่อถูกโจมตีโดยตรง หากคุณสมบัติควบคุมไม่ได้ถูกเปิดใช้งาน การโจมตีนี้จะไม่ใช่คริติคัล หลังจากถูกโจมตีโดยตรง จะเพิ่ม [แผล] ให้เป้าหมายเป็นเวล 3 เทิร์น เมื่อรับความเสียหายจากการโจมตีที่เป็นคริติคัล ใช้ [ออร่า] เพื่อยกเลิกการโจมตีและฟื้นฟูพลังชีวิตที่สูญเสียของพันธมิตร  $(30+skillLevel*0.3-0.3)$%',
		describe_in = 'Amarah Raja Pahlawan: Saat menerima kerusakan dari serangan aktif yang bukan serangan kritis, ia akan segera menggunakan serangan biasa untuk menyerang satu unit musuh secara acak. Aura: Membawa 1 [Aura] saat memasuki arena. Jika Anda kehilangan [Aura], Anda akan mendapatkan kembali satu [Aura] setelah 3 giliran. [Aura]: Efek khusus yang tidak bisa dihilangkan, maksimal 1. Saat diserang secara aktif, jika atribut kendali tidak aktif, serangan ini tidak bisa menjadi serangan kritis; setelah diserang secara aktif, satu lapis [Luka] akan ditambahkan ke target selama 3 giliran; ketika menerima kerusakan serangan aktif kritis, gunakan [Aura] untuk membatalkan serangan dan memulihkan jumlah HP yang hilang untuk satu sekutu. $(30+skillLevel*0.3-0.3)$%',
		describe_ph = 'Galit ng Hari ng mga Bayani: Kapag tumatanggap ng pinsala mula sa aktibong pag-atake na hindi kritikal, agad siyang gagamit ng normal na atake upang umatake sa isang random na kalabang yunit. Aura: May dala ng 1 [Aura] sa pagpasok sa laban. Kung mawawala ang iyong [Aura], makakakuha ka ng isa pang [Aura] matapos ang 3 turn. [Aura]: Isang espesyal na epekto na hindi matanggal, hanggang sa 1 lamang. Kapag inaatake ng aktibo, kung ang attribute ng pagpigil ay hindi nag-trigger, hindi magiging kritikal ang pag-atakeng ito; pagkatapos ma-atake nang aktibo, isang layer ng [Sugat] ang idinadagdag sa target sa loob ng 3 turn; kapag tumatanggap ng kritikal na pinsala mula sa aktibong pag-atake, gamitin ang [Aura] upang pawalang bisa ang pag-atake at pagalingin ang nawalang HP ng isang kakampi. $(30+skillLevel*0.3-0.3)$%',
		describe_ma = 'Amarah Raja Wira: Apabila menerima kerosakan daripada serangan aktif yang bukan serangan kritikal, dia akan segera menggunakan serangan biasa untuk menyerang satu unit musuh secara rawak. Aura: Membawa 1 [Aura] ketika memasuki medan pertempuran. Jika anda kehilangan [Aura], anda akan mendapat kembali satu [Aura] selepas 3 pusingan. [Aura]: Kesan khas yang tidak boleh dibersihkan, maksimum 1. Apabila diserang secara aktif, jika atribut kawalan tidak diaktifkan, serangan ini tidak boleh menjadi serangan kritikal; selepas menerima serangan aktif, satu lapis [Luka] akan ditambah ke sasaran selama 3 pusingan; apabila menerima kerosakan akibat serangan aktif kritikal, gunakan [Aura] untuk menafikan serangan dan memulihkan jumlah HP yang hilang kepada seorang sekutu. $(30+skillLevel*0.3-0.3)$%',
		describe = 'Wrath of the King of Heroes: When taking damage from an active attack that is not a critical hit, he will immediately use a normal attack to strike a random enemy unit.  Aura: Carries 1 [Aura] upon entering the battlefield. If you lose [Aura], you will recover one [Aura] after 3 turns.  [Aura]: A special effect that cannot be dispelled, max 1. When attacked actively, if the restraint attribute is not triggered, the attack cannot be a critical hit; after being attacked actively, a layer of [Wound] is added to the target for 3 turns; when receiving critical active attack damage, use [Aura] to nullify the attack and recover the lost HP by one ally. $(30+skillLevel*0.3-0.3)$%',
		starEffect = __data_t__starEffect[24936],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu quả: Khi đồng đội phe ta chịu một đòn tấn công chủ động không chí mạng, Gilgamesh sẽ lập tức dùng tấn công thường lên một đơn vị địch ngẫu nhiên.',
		starEffectDesc = 'Enhance effectiveness: When an ally of our faction suffers a non-critical active attack, Gilgamesh will immediately perform a normal attack on a random enemy unit.',
		starEffectDesc_en = 'Enhance effectiveness: When an ally of our faction suffers a non-critical active attack, Gilgamesh will immediately perform a normal attack on a random enemy unit.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: เมื่อเพื่อนร่วมทีมฝ่ายเราถูกโจมตีแบบไม่คริติคอล Gilgamesh จะโจมตีปกติทันทีบนหน่วยศัตรูแบบสุ่ม',
		starEffectDesc_in = 'Tingkatkan efektivitas: Ketika rekan satu tim kita menerima serangan aktif yang tidak kritis, Gilgamesh akan langsung melakukan serangan biasa ke satu unit musuh secara acak.',
		starEffectDesc_ph = 'Pahusayin ang bisa: Kapag ang kasamahan sa aming panig ay tinamaan ng isang aktibong atake na hindi kritikal, agad gagamitin ni Gilgamesh ang karaniwang atake sa isang random na kalaban.',
		starEffectDesc_ma = 'Tingkatkan keberkesanan: Apabila rakan sepasukan kami menerima serangan aktif yang bukan kritikal, Gilgamesh akan segera melakukan serangan biasa ke satu unit musuh secara rawak.',
		zawakeEffect = __data_t__zawakeEffect[24936],
