	[25913] = {
		id = 25913,
		skillName_vn = 'Điện quang lửa đá',
		skillName_en = 'Electric spark fire stone',
		skillName_th = 'ไฟหินประกายไฟฟ้า',
		skillName_in = 'Batu api percikan listrik',
		skillName_ph = 'Kalahating electric spark na bato',
		skillName_ma = 'Batu api percikan elektrik',
		skillName = 'Electric spark fire stone',
		describe_vn = 'Viên đá tích tụ năng lượng trong miệng, hội tụ thành pháo điện từ hình trụ, bắn vào mục tiêu hàng ngang của đối phương, gây ra #C0xE69900#230% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, trong toàn trận mỗi lần nhận sát thương sẽ tăng 10% sát thương kỹ năng tối thượng, tối đa cộng dồn 5 lần, sau khi sử dụng kỹ năng tối thượng sẽ mất kiểm soát và chắc chắn tấn công đồng đội một lần ở lượt tiếp theo',
		describe_en = 'The stone accumulates energy in the mouth, converging into a cylindrical electromagnetic cannon, firing at the enemy\'s horizontal row of targets, causing #C0xE69900#230% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Each time damage is received during the entire battle, the ultimate skill damage increases by 10%, stacking up to 5 times. After using the ultimate skill, the user loses control and will definitely attack allies once on the next turn.',
		describe_th = 'หินสะสมพลังงานในปาก รวมตัวเป็นปืนไฟฟ้าทรงกระบอก ยิงไปยังแถวเป้าหมายแนวนอนของศัตรู สร้างความเสียหาย #C0xE69900#230% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ทั้งการต่อสู้ เมื่อได้รับความเสียหายแต่ละครั้ง จะเพิ่มความเสียหายสกิลอัลติเมทขึ้น 10% สะสมได้สูงสุด 5 ครั้ง หลังจากใช้สกิลอัลติเมท จะเสียการควบคุมและโจมตีเพื่อนร่วมทีมอย่างแน่นอนครั้งหนึ่งในรอบถัดไป',
		describe_in = 'Batu mengumpulkan energi di dalam mulut, berkonsentrasi menjadi meriam elektromagnetik berbentuk silinder, menembak ke barisan target musuh, menyebabkan #C0xE69900#230% Serangan Fisik#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Sepanjang pertandingan, setiap kali menerima kerusakan, meningkatkan kerusakan skill ultimate sebesar 10%, dapat ditumpuk hingga 5 kali. Setelah menggunakan skill ultimate, kehilangan kendali dan pasti menyerang rekan satu tim sekali pada giliran berikutnya.',
		describe_ph = 'Ang bato ay nag-iipon ng enerhiya sa bibig, nagtitipon bilang isang electromagnetic cannon na hugis silindro, pumaputok sa hanay ng mga target ng kalaban, nagdudulot ng #C0xE69900#230% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Sa buong laban, sa bawat pagtanggap ng damage, tumataas ng 10% ang ultimate skill damage, hanggang limang beses na pwedeng mag-stack. Pagkatapos gamitin ang ultimate skill, mawawala ang kontrol at tiyak na tatamaan ang kakampi ng isang beses sa susunod na turn.',
		describe_ma = 'Batu mengumpul tenaga di dalam mulut, berkumpul menjadi meriam elektromagnet silinder, menembak ke sasaran barisan mendatar musuh, menyebabkan #C0xE69900#230% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Sepanjang perlawanan, setiap kali menerima kerosakan, akan meningkatkan kerosakan kemahiran utama sebanyak 10%, bertumpuk sehingga 5 kali. Selepas menggunakan kemahiran utama, kehilangan kawalan dan pasti menyerang rakan sepasukan sekali pada pusingan seterusnya.',
		describe = 'The stone accumulates energy in the mouth, converging into a cylindrical electromagnetic cannon, firing at the enemy\'s horizontal row of targets, causing #C0xE69900#230% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Each time damage is received during the entire battle, the ultimate skill damage increases by 10%, stacking up to 5 times. After using the ultimate skill, the user loses control and will definitely attack allies once on the next turn.',
		simDesc_vn = 'Thạch Hoàn Tử tích lũy năng lượng trong miệng, tập hợp thành một khẩu pháo điện từ hình trụ, bắn vào các mục tiêu hàng của đối phương; mỗi lần nhận sát thương, sẽ tăng cường một lượng sát thương chí mạng, sau đó sẽ mất kiểm soát và chắc chắn tấn công đồng minh trong lượt tiếp theo.',
		simDesc_en = 'Thach Hoan Tu accumulates energy in his mouth, forming a cylindrical electromagnetic cannon that fires at rows of enemy targets; each time he takes damage, his critical damage increases, but then he loses control and will definitely attack allies on the next turn.',
		simDesc_th = 'ทัชฮวนตู้สะสมพลังงานในปาก สร้างปืนแม่เหล็กไฟฟ้าทรงกระบอก ยิงไปยังเป้าหมายเป็นแถวของศัตรู ทุกครั้งที่ได้รับความเสียหาย จะเพิ่มความเสียหายคริติคอล แต่หลังจากนั้นจะสูญเสียการควบคุมและจะโจมตีพันธมิตรในเทาถัดไปอย่างแน่นอน',
		simDesc_in = 'Thach Hoan Tu mengumpulkan energi di mulutnya, membentuk meriam elektromagnetik berbentuk silinder yang menembak ke barisan target musuh; setiap kali menerima kerusakan, akan meningkatkan kerusakan kritis, namun kemudian kehilangan kendali dan pasti akan menyerang sekutu pada giliran berikutnya.',
		simDesc_ph = 'Ang Thach Hoan Tu ay nag-iipon ng enerhiya sa kanyang bibig, bumubuo ng isang silindrikong electromagnetic na kanyon na pumaputok sa mga hanay ng mga target ng kalaban; de bawat tumanggap ng pinsala, tumataas ang dami ng kritikal na pinsala, ngunit mawawala siya sa kontrol at tiyak na aatake sa mga kaalyado sa susunod na turn.',
		simDesc_ma = 'Thach Hoan Tu mengumpul tenaga di dalam mulutnya, membentuk meriam elektromagnet berbentuk silinder yang menembak ke barisan sasaran musuh; setiap kali menerima kerosakan, akan meningkatkan jumlah kerosakan kritikal, kemudian hilang kawalan dan pasti menyerang sekutu pada giliran berikutnya.',
		simDesc = 'Thach Hoan Tu accumulates energy in his mouth, forming a cylindrical electromagnetic cannon that fires at rows of enemy targets; each time he takes damage, his critical damage increases, but then he loses control and will definitely attack allies on the next turn.',
		starEffect = __data_t__starEffect[25913],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Mỗi lần nhận sát thương, tăng 20% sát thương cho kỹ năng đặc biệt.',
		starEffectDesc = 'Enhance effect: Each time you take damage, increase special skill damage by 20%.',
		starEffectDesc_en = 'Enhance effect: Each time you take damage, increase special skill damage by 20%.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: ทุกครั้งที่ได้รับความเสียหาย เพิ่มความเสียหายของทักษะพิเศษขึ้น 20%',
