	[25933] = {
		id = 25933,
		skillName_vn = 'Cơn lốc xanh',
		skillName_en = 'The Blue Tornado',
		skillName_th = 'พายุหมุนสีฟ้า',
		skillName_in = 'Badai Biru',
		skillName_ph = 'Asul na Bagyong',
		skillName_ma = 'Taufan Biru',
		skillName = 'The Blue Tornado',
		describe_vn = 'Các Zombie Ninja Rùa phóng ra những cơn lốc màu xanh để bắn phá các mục tiêu của kẻ địch theo hàng, gây ra #C0xE69900#250% đòn Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, mỗi khi sát thương tích lũy mà bản thân nhận được tăng thêm 10%, sát thương cộng thêm của chiêu thức đặc biệt có thể là tích lũy tới 5 lần. Sau khi mất kiểm soát sau chiêu thức đặc biệt, anh ta sẽ tấn công đồng đội của mình một lần ở vòng tiếp theo.',
		describe_en = 'The Turtle Zombie Ninja unleashes blue whirlwinds to attack enemy targets in rows, causing #C0xE69900#250% Physical Damage#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#Physical Damage#C0x5B545B#. Each time accumulated damage taken increases by 10%, the additional damage of the special skill can stack up to 5 times. After losing control following the special skill, he will attack his own teammates once in the next round.',
		describe_th = 'ซูโนะบิซอมบี้เต่าปล่อยพายุหมุนสีน้ำเงินโจมตีเป้าหมายศัตรูเป็นแถว ทำความเสียหายทางกายภาพ #C0xE69900#250%#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ทุกครั้งที่ความเสียหายสะสมที่ได้รับเพิ่มขึ้น 10% ความเสียหายพิเศษของทักษะพิเศษจะสะสมได้สูงสุด 5 ครั้ง หลังจากเสียการควบคุมหลังใช้ทักษะพิเศษ เขาจะโจมตีเพื่อนร่วมทีมของตัวเองหนึ่งครั้งในรอบถัดไป',
		describe_in = 'Zombie Ninja Kura melepaskan pusaran angin berwarna biru untuk menyerang target musuh dalam barisan, menyebabkan #C0xE69900#250% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#. Setiap kali kerusakan yang terakumulasi bertambah 10%, tambahan kerusakan dari skill khusus dapat bertumpuk hingga 5 kali. Setelah kehilangan kontrol setelah menggunakan skill khusus, dia akan menyerang teman satu timnya sekali pada ronde berikutnya.',
		describe_ph = 'Ang Turtle Zombie Ninja ay nagpapalabas ng mga asul na whirlwinds upang atakihin ang mga target ng kalaban nang sunud-sunod, na nagdudulot ng #C0xE69900#250% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Sa tuwing ang naipong pinsala na natanggap ay tataas ng 10%, ang karagdagang pinsala ng espesyal na kakayahan ay maaaring mag-ipon hanggang 5 beses. Pagkatapos mawalan ng kontrol matapos ang espesyal na kakayahan, siya ay aatake sa kanyang sariling mga kakampi nang isang beses sa susunod na round.',
		describe_ma = 'Zombie Ninja Kura melepaskan pusaran angin berwarna biru untuk menyerang sasaran musuh secara barisan, menyebabkan #C0xE69900#250% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Setiap kali kerosakan terkumpul yang diterima bertambah 10%, kerosakan tambahan daripada kemahiran khas boleh terkumpul sehingga 5 kali. Selepas kehilangan kawalan selepas kemahiran khas, dia akan menyerang rakan sepasukannya sekali dalam pusingan seterusnya.',
		describe = 'The Turtle Zombie Ninja unleashes blue whirlwinds to attack enemy targets in rows, causing #C0xE69900#250% Physical Damage#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#Physical Damage#C0x5B545B#. Each time accumulated damage taken increases by 10%, the additional damage of the special skill can stack up to 5 times. After losing control following the special skill, he will attack his own teammates once in the next round.',
		simDesc_vn = 'Ninja Rùa Zombie phóng ra một cơn lốc màu xanh để bắn phá hàng loạt mục tiêu của kẻ thù. Mỗi khi sát thương tích lũy mà zombie Ninja Rùa nhận sẽ tăng thêm một lượng sát thương tiêu diệt nhất định, sau khi mất kiểm soát, nó sẽ tấn công đồng đội của mình một lần ở lượt tiếp theo.',
		simDesc_en = 'The Zombie Ninja Turtle unleashes a blue whirlwind to bombard multiple enemy targets. Each time the accumulated damage the Zombie Ninja Turtle receives increases, it gains a certain amount of additional killing damage. After losing control, it will attack its own team once in the next turn.',
		simDesc_th = 'นินจาเต่าซอมบี้ปล่อยพายุหมุนสีน้ำเงินเพื่อโจมตีเป้าหมายศัตรูหลายตัว ทุกครั้งที่ความเสียหายสะสมที่นินจาเต่าซอมบี้ได้รับเพิ่มขึ้น มันจะได้รับความเสียหายจากการฆ่าเพิ่มขึ้น หลังจากเสียการควบคุม มันจะโจมตีเพื่อนร่วมทีมของตัวเองหนึ่งครั้งในเทาต่อไป',
		simDesc_in = 'Zombie Ninja Turtle melepaskan pusaran biru untuk menyerang banyak target musuh sekaligus. Setiap kali akumulasi kerusakan yang diterima Zombie Ninja Turtle meningkat, ia mendapatkan tambahan kerusakan mematikan tertentu. Setelah kehilangan kendali, ia akan menyerang rekan timnya sekali pada giliran berikutnya.',
		simDesc_ph = 'Ang Zombie Ninja Turtle ay nagpapalabas ng asul na whirlwind upang atakihin ang maraming kaaway nang sabay-sabay. Sa tuwing tataas ang naipon na pinsalang natatanggap ng Zombie Ninja Turtle, nakakakuha ito ng dagdag na nakamamatay na pinsala. Pagkatapos mawalan ng kontrol, aatakihin nito ang sariling koponan ng isang beses sa susunod na turn.',
		simDesc_ma = 'Zombie Ninja Turtle melepaskan pusaran biru untuk menyerang pelbagai sasaran musuh. Setiap kali kerosakan terkumpul yang diterima oleh Zombie Ninja Turtle meningkat, ia mendapat sejumlah kerosakan mematikan tambahan. Setelah hilang kawalan, ia akan menyerang rakan pasukannya sekali pada giliran berikutnya.',
		simDesc = 'The Zombie Ninja Turtle unleashes a blue whirlwind to bombard multiple enemy targets. Each time the accumulated damage the Zombie Ninja Turtle receives increases, it gains a certain amount of additional killing damage. After losing control, it will attack its own team once in the next turn.',
		starEffect = __data_t__starEffect[25933],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Mỗi lần nhận sát thương, tăng 20% sát thương cho kỹ năng đặc biệt.',
		starEffectDesc = 'Enhance Effect: Each time you take damage, increase special skill damage by 20%.',
		starEffectDesc_en = 'Enhance Effect: Each time you take damage, increase special skill damage by 20%.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: ทุกครั้งที่ได้รับความเสียหาย เพิ่มความเสียหายทักษะพิเศษขึ้น 20%.',
		starEffectDesc_in = 'Perkuat Efek: Setiap kali menerima kerusakan, tingkatkan kerusakan keterampilan khusus sebesar 20%.',
		starEffectDesc_ph = 'Palakasin ang Epekto: Sa bawat pagkakataon na tumanggap ng pinsala, dagdagan ng 20% ang pinsala ng espesyal na kasanayan.',
		starEffectDesc_ma = 'Kukuhkan Kesan: Setiap kali menerima kerosakan, tingkatkan kerosakan kemahiran istimewa sebanyak 20%.',
		zawakeEffect = __data_t__zawakeEffect[25933],
		-- {79003}
		zawakeEffectDesc = 'The Ninja Turtles zombies unleash a blue tornado to bombard the enemy\'s row targets, causing #C0xE69900#260% Physical Damage #C0x5B545B#+$(skillLevel*4*36)$ of #C0xF13B54# Physical Damage #C0x5B545B#. Each time the accumulated damage that the Ninja Turtles receive increases by 10%, the special attack damage bonus can be stacked up to 5 times.',
		zawakeEffectDesc_en = 'The Ninja Turtles zombies unleash a blue tornado to bombard the enemy\'s row targets, causing #C0xE69900#260% Physical Damage #C0x5B545B#+$(skillLevel*4*36)$ of #C0xF13B54# Physical Damage #C0x5B545B#. Each time the accumulated damage that the Ninja Turtles receive increases by 10%, the special attack damage bonus can be stacked up to 5 times.',
		zawakeEffectDesc_th = 'ซอมบี้เต่านินจาปล่อยพายุทอร์นาโดสีน้ำเงินเพื่อโจมตีเป้าหมายในแถวของศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#260% #C0x5B545B#+$(skillLevel*4*36)$ ของ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B#. ทุกครั้งที่ความเสียหายสะสมที่เต่านินจาได้รับเพิ่มขึ้น 10% โบนัสความเสียหายโจมตีพิเศษสามารถสะสมได้สูงสุด 5 ครั้ง',
		zawakeEffectDesc_in = 'Zombie Ninja Turtles melepaskan tornado biru untuk membombardir target barisan musuh, menyebabkan #C0xE69900#260% Kerusakan Fisik #C0x5B545B#+$(skillLevel*4*36)$ dari #C0xF13B54# Kerusakan Fisik #C0x5B545B#. Setiap kali kerusakan terakumulasi yang diterima Ninja Turtles bertambah 10%, bonus kerusakan serangan khusus dapat ditumpuk hingga 5 kali.',
		zawakeEffectDesc_ph = 'Ang mga Zombie Ninja Turtles ay nagpapalabas ng asul na buhawi upang bombahin ang mga target sa hanay ng kalaban, na nagdudulot ng #C0xE69900#260% Pisikal na Pinsala #C0x5B545B#+$(skillLevel*4*36)$ ng #C0xF13B54# Pisikal na Pinsala #C0x5B545B#. Sa tuwing tataas ng 10% ang naipong pinsalang natatanggap ng Ninja Turtles, maaaring maipon ang espesyal na bonus sa pinsala ng atake hanggang sa 5 beses.',
		zawakeEffectDesc_ma = 'Zombi Ninja Turtles melepaskan taufan biru untuk menyerang sasaran barisan musuh, menyebabkan #C0xE69900#260% Kerosakan Fizikal #C0x5B545B#+$(skillLevel*4*36)$ daripada #C0xF13B54# Kerosakan Fizikal #C0x5B545B#. Setiap kali kerosakan terkumpul yang diterima Ninja Turtles meningkat sebanyak 10%, bonus kerosakan serangan khas boleh dikumpul sehingga 5 kali.',
		zawakeEffectDesc_vn = 'Các thây ma Ninja Rùa phóng ra một cơn lốc màu xanh để bắn phá các mục tiêu hàng của kẻ thù, gây ra #C0xE69900#260% đòn Sát Thương Vật Lý #C0x5B545B#+$(skillLevel*4*36)$ của #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#. Mỗi khi sát thương tích lũy mà Ninja Rùa nhận được tăng thêm 10%, phần thưởng sát thương tấn công đặc biệt có thể được tích lũy lên tới 5 lần.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Damage multiplier increases from 250% to 260%, and you will not lose control after a special move.  ',
		zawakeSimpleDesc_en = 'Damage multiplier increases from 250% to 260%, and you will not lose control after a special move.  ',
		zawakeSimpleDesc_th = 'ตัวคูณความเสียหายเพิ่มจาก 250% เป็น 260% และคุณจะไม่สูญเสียการควบคุมหลังจากใช้ท่าไม้ตาย',
		zawakeSimpleDesc_in = 'Pengganda damage meningkat dari 250% menjadi 260%, dan kamu tidak akan kehilangan kendali setelah menggunakan jurus spesial  ',
		zawakeSimpleDesc_ph = 'Tumaas ang damage multiplier mula 250% hanggang 260%, at hindi ka mawawalan ng kontrol pagkatapos ng special skill  ',
		zawakeSimpleDesc_ma = 'Pengganda kerosakan meningkat dari 250% ke 260%, dan anda tidak akan kehilangan kawalan selepas menggunakan kemahiran khas  ',
		zawakeSimpleDesc_vn = 'Hệ số sát thương tăng từ 250% lên 260% và bạn sẽ không bị mất kiểm soát sau một chiêu thức đặc biệt.',
