	[26833] = {
		id = 26833,
		skillName_vn = 'Chớp xoáy',
		skillName_en = 'Whirlwind',
		skillName_th = 'พายุหมุน',
		skillName_in = 'Angin Pusaran',
		skillName_ph = 'Ihip ng Ulan',
		skillName_ma = 'Angin Pusaran',
		skillName = 'Whirlwind',
		describe_vn = 'Zombie của Feimura vung kiếm tấn công mục tiêu ở hàng đầu của kẻ địch bằng một cơn lốc xoáy, gây #C0xE69900#230% Vật công #C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, 50% xác suất thêm hiệu ứng [ngộ độc] trong 2 hiệp (ngộ độc: hiệu ứng tiêu cực, the mục tiêu mất 20% sát thương thực sự của đòn Sát Thương Vật Lý của Feimun Zombie trước mỗi hiệp, có thể cộng dồn tối đa 5 lần). Đối với mỗi mục tiêu [Độc] bổ sung vào kẻ địch, sát thương do Feimun Zombie gây ra tăng thêm 10%.',
		describe_en = 'Feimura\'s Zombie swings its sword to attack the frontline enemies with a whirlwind, dealing #C0xE69900#230% Physical Attack #C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# Physical Damage #C0x5B545B#, with a 50% chance to inflict [Poison] for 2 turns (Poison: a negative effect causing the target to lose 20% of the actual Physical Damage from Feimura Zombie\'s Physical Damage attack before each turn, stacking up to 5 times). For each [Poisoned] target added to enemies, the damage dealt by Feimura Zombie increases by 10%.',
		describe_th = 'ซอมบี้ของเฟอิมูระ ฟาดดาบโจมตีเป้าหมายแถวหน้าโดยใช้พายุพัดกระหน่ำ สร้างความเสียหายทางกายภาพ #C0xE69900#230% #C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# โดยมีโอกาส 50% ทำให้เกิดสถานะ [พิษ] เป็นเวลา 2 เทิร์น (พิษ: สถานะลบที่ทำให้เป้าหมายสูญเสีย 20% ของความเสียหายทางกายภาพจริงจากการโจมตีของซอมบี้เฟอิมูระก่อนแต่ละเทิร์น และสามารถซ้อนทับกันได้สูงสุด 5 ครั้ง) สำหรับแต่ละเป้าหมายที่ได้รับ [พิษ] เพิ่มเติมบนศัตรู ความเสียหายที่ซอมบี้เฟอิมูระสร้างจะเพิ่มขึ้นอีก 10%',
		describe_in = 'Zombie Feimura mengayunkan pedangnya menyerang target barisan depan musuh dengan pusaran angin, memberikan #C0xE69900#230% Serangan Fisik #C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#, dengan peluang 50% menambahkan efek [Racun] selama 2 giliran (Racun: efek negatif yang menyebabkan target kehilangan 20% dari kerusakan fisik nyata dari serangan Kerusakan Fisik Zombie Feimura sebelum setiap giliran, dapat menumpuk hingga 5 kali). Untuk setiap target [Teracun] yang ditambahkan ke musuh, kerusakan yang diberikan oleh Zombie Feimura meningkat sebesar 10%.',
		describe_ph = 'Ang Zombie ni Feimura ay sumasagasa gamit ang espada upang atakihin ang mga target sa unahang linya ng kalaban gamit ang isang buhawi, na nagdudulot ng #C0xE69900#230% Physical Attack #C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# Physical Damage #C0x5B545B#, may 50% tsansa na makapaglagay ng efektong [Lason] sa loob ng 2 na turn (Lason: negatibong epekto kung saan ang target ay nawawalan ng 20% ng totoong pisikal na pinsala mula sa Physical Damage attack ng Feimura Zombie bago ang bawat turn, maaaring mag-stack hanggang 5 beses). Para sa bawat [Nilason] na target na nadagdag sa mga kalaban, tumataas ng 10% ang pinsalang dulot ng Feimura Zombie.',
		describe_ma = 'Zombie Feimura mengayunkan pedangnya menyerang sasaran barisan depan musuh dengan pusaran angin, menyebabkan #C0xE69900#230% Serangan Fizikal #C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, dengan peluang 50% untuk menambah kesan [Racun] selama 2 pusingan (Racun: kesan negatif yang menyebabkan sasaran kehilangan 20% daripada kerosakan fizikal sebenar daripada serangan Kerosakan Fizikal Zombie Feimura sebelum setiap pusingan, boleh bertindih sehingga 5 kali). Untuk setiap sasaran [Diracun] yang ditambah ke musuh, kerosakan yang disebabkan oleh Zombie Feimura meningkat sebanyak 10%.',
		describe = 'Feimura\'s Zombie swings its sword to attack the frontline enemies with a whirlwind, dealing #C0xE69900#230% Physical Attack #C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# Physical Damage #C0x5B545B#, with a 50% chance to inflict [Poison] for 2 turns (Poison: a negative effect causing the target to lose 20% of the actual Physical Damage from Feimura Zombie\'s Physical Damage attack before each turn, stacking up to 5 times). For each [Poisoned] target added to enemies, the damage dealt by Feimura Zombie increases by 10%.',
		simDesc_vn = 'Các thây ma Himura vung kiếm và chém ra những cơn lốc xoáy để tấn công các mục tiêu ở hàng đầu của kẻ thù, có khả năng bị nhiễm độc.',
		simDesc_en = 'The Himura zombies swing their swords and slash out whirlwinds to attack the enemy\'s front-line targets, with a chance to inflict poison.',
		simDesc_th = 'ซอมบี้ฮิมูระฟันดาบและฟันออกเป็นพายุหมุนเพื่อโจมตีเป้าหมายแนวหน้า ของศัตรู มีโอกาสติดพิษ',
		simDesc_in = 'Zombi Himura mengayunkan pedang mereka dan mengayunkan pusaran angin untuk menyerang target garis depan musuh, dengan kemungkinan terkena racun.',
		simDesc_ph = 'Ang mga Himura zombie ay umiikot ng kanilang mga espada at humahati ng mga bagyong paikot upang atakihin ang mga target sa unahang linya ng kaaway, may kakayahang magdulot ng lason.',
