		skillName_vn = 'Cấm chế luyện thành trận',
		skillName_en = 'Prohibited from refining into formation',
		skillName_th = 'ห้ามกลั่นแปรเป็นรูปแบบ',
		skillName_in = 'Dilarang menyempurnakan menjadi formasi',
		skillName_ph = 'Ipinagbabawal ang paghasa para maging pormasyon',
		skillName_ma = 'Dilarang memperhalusi menjadi formasi',
		skillName = 'Prohibited from refining into formation',
		describe_vn = 'Edward tích tụ sức mạnh chứa đựng khí đen tối, sử dụng trận luyện cấm kỵ, gây ra #C0xE69900#520% Công Vật Lý#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# cho mục tiêu đơn lẻ của kẻ địch, gây sát thương lan 20% cho các mục tiêu xung quanh, thêm [Mù] trong 1 lượt (Mù: hiệu ứng tiêu cực, giảm 65% tỷ lệ trúng đích của mục tiêu chính, các mục tiêu xung quanh giảm 35% tỷ lệ trúng đích)',
		describe_en = 'Edward accumulates power containing dark energy, using the forbidden training formation, dealing #C0xE69900#520% Physical Attack#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B# to a single enemy target, causing 20% splash damage to surrounding targets, adding [Blind] for 1 turn (Blind: negative effect, reducing the main target\'s hit rate by 65%, surrounding targets\' hit rate by 35%).',
		describe_th = 'เอ็ดเวิร์ดสะสมพลังที่มีพลังงานมืด ใช้การฝึกห้ามที่เป็นพิษ ทำให้เกิด #C0xE69900#520% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ต่อเป้าหมายศัตรูเดี่ยว สร้างความเสียหายกระจาย 20% ให้เป้าหมายรอบข้าง เพิ่ม [ตาบอด] เป็นเวลา 1 เทิร์น (ตาบอด: ผลลบ ลดอัตราช่องทางถูกตีของเป้าหมายหลักลง 65%, เป้าหมายรอบข้างลดลง 35%)',
		describe_in = 'Edward mengumpulkan kekuatan yang mengandung energi gelap, menggunakan formasi latihan terlarang, memberikan #C0xE69900#520% Serangan Fisik#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B# kepada satu target musuh, menyebabkan kerusakan tersebar 20% ke target sekitar, menambahkan [Buta] selama 1 giliran (Buta: efek negatif, mengurangi tingkat akurasi target utama sebesar 65%, target sekitar sebesar 35%).',
		describe_ph = 'Pinagsama ni Edward ang kapangyarihang naglalaman ng madilim na enerhiya, ginamit ang ipinagbabawal na pagsasanay na pormasyon, nagdudulot ng #C0xE69900#520% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B# sa isang kalaban, nagdudulot ng 20% na laganap na pinsala sa mga kalapit na target, nagdaragdag ng [Bulag] sa loob ng 1 turn (Bulag: negatibong epekto, nagpapababa ng 65% hit rate ng pangunahing target, 35% para sa mga kalapit na target).',
		describe_ma = 'Edward mengumpul kuasa yang mengandungi tenaga gelap, menggunakan formasi latihan terlarang, memberikan #C0xE69900#520% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B# kepada satu sasaran musuh, menyebabkan kerosakan limpahan 20% kepada sasaran sekitar, menambah [Butakan] selama 1 pusingan (Butakan: kesan negatif, mengurangkan kadar tepat sasaran sasaran utama sebanyak 65%, sasaran sekitar sebanyak 35%).',
		describe = 'Edward accumulates power containing dark energy, using the forbidden training formation, dealing #C0xE69900#520% Physical Attack#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B# to a single enemy target, causing 20% splash damage to surrounding targets, adding [Blind] for 1 turn (Blind: negative effect, reducing the main target\'s hit rate by 65%, surrounding targets\' hit rate by 35%).',
		simDesc_vn = 'Edward tích trữ sức mạnh đen tối, thi triển trận pháp cấm, gây sát thương lan ra cho các mục tiêu xung quanh và thêm hiệu ứng mù.',
		simDesc_en = 'Edward accumulates dark power, casting a forbidden formation that deals area damage to surrounding targets and adds a blindness effect.',
		simDesc_th = 'เอ็ดเวิร์ดสะสมพลังแห่งความมืด ใช้ผังเวทย์ต้องห้าม สร้างความเสียหายรอบเป้าหมายและเพิ่มสถานะตาบอด',
		simDesc_in = 'Edward mengumpulkan kekuatan gelap, menampilkan formasi terlarang yang menyebabkan kerusakan area pada target di sekitarnya dan menambahkan efek buta.',
		simDesc_ph = 'Si Edward ay nag-iipon ng madilim na kapangyarihan, nagsasagawa ng ipinagbabawal na pormasyon na nagdudulot ng area damage sa mga kalapit na target at nagdaragdag ng status na bulag.',
		simDesc_ma = 'Edward mengumpul kuasa gelap, melancarkan formasi larangan yang memberi kerosakan kawasan kepada sasaran sekitar serta menambah kesan buta.',
		simDesc = 'Edward accumulates dark power, casting a forbidden formation that deals area damage to surrounding targets and adds a blindness effect.',
		starEffect = __data_t__starEffect[27233],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Hiệu ứng mù làm giảm 85% tỷ lệ trúng đích của mục tiêu chính, và giảm 45% tỷ lệ trúng đích của các mục tiêu xung quanh.',
		starEffectDesc = 'Enhance Effect: Blind effect reduces the main target\'s hit rate by 85%, and reduces the surrounding targets\' hit rate by 45%.',
		starEffectDesc_en = 'Enhance Effect: Blind effect reduces the main target\'s hit rate by 85%, and reduces the surrounding targets\' hit rate by 45%.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: เอฟเฟกต์ตาบอดลดอัตราการโจมตีเป้าหมายหลักลง 85% และลดอัตราการโจมตีเป้าหมายรอบข้างลง 45%',
		starEffectDesc_in = 'Tingkatkan Efek: Efek buta mengurangi tingkat akurasi target utama sebesar 85%, dan mengurangi tingkat akurasi target di sekitar sebesar 45%.',
		starEffectDesc_ph = 'Palakasin ang Epekto: Ang bulag na epekto ay nagpapababa ng 85% sa hit rate ng pangunahing target, at nagpapababa ng 45% sa hit rate ng mga kalapit na target.',
		starEffectDesc_ma = 'Kukuhkan Kesan: Kesan kabur mengurangkan kadar tepat sasaran sasaran utama sebanyak 85%, dan mengurangkan kadar tepat sasaran sasaran di sekeliling sebanyak 45%.',
		zawakeEffect = __data_t__zawakeEffect[27233],
		-- {79003}
		zawakeEffectDesc = 'Edward accumulates power containing dark energy, using a forbidden training formation on a single enemy target, dealing #C0xE69900#520% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ Physical Damage#C0xF13B54#C0x5B545B#, spreading 20% damage to surrounding targets, adding blindness effect for 2 turns (blindness: a negative effect that reduces the main target\'s hit rate by 65% and surrounding targets\' hit rate by 35%)',
		zawakeEffectDesc_en = 'Edward accumulates power containing dark energy, using a forbidden training formation on a single enemy target, dealing #C0xE69900#520% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ Physical Damage#C0xF13B54#C0x5B545B#, spreading 20% damage to surrounding targets, adding blindness effect for 2 turns (blindness: a negative effect that reduces the main target\'s hit rate by 65% and surrounding targets\' hit rate by 35%)',
		zawakeEffectDesc_th = 'เอ็ดเวิร์ดสะสมพลังที่มีพลังงานมืด ใช้รูปแบบการฝึกห้ามสำหรับเป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0xE69900#520% การโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*75)$ ความเสียหายทางกายภาพ#C0xF13B54#C0x5B545B# และสร้างความเสียหายลาม 20% ให้เป้าหมายรอบข้าง เพิ่มผลมืด 2 เทิร์น (มืด: ผลลบ ลดความแม่นยำของเป้าหมายหลัก 65% และลดความแม่นยำของเป้าหมายรอบข้าง 35%)',
		zawakeEffectDesc_in = 'Edward mengumpulkan kekuatan yang mengandung energi gelap, menggunakan formasi latihan terlarang pada satu target musuh, menyebabkan #C0xE69900#520% Serangan Fisik#C0x5B545B#+$(skillLevel*4*75)$ Kerusakan Fisik#C0xF13B54#C0x5B545B#, menyebabkan kerusakan lanjutan 20% ke target di sekitar, menambahkan efek kabur selama 2 giliran (kabur: efek negatif, mengurangi akurasi target utama sebesar 65% dan target di sekitar sebesar 35%)',
		zawakeEffectDesc_ph = 'Nag-iipon si Edward ng lakas na naglalaman ng madilim na enerhiya, gamit ang ipinagbabawal na pagsasanay na pormasyon sa isang kalabang target, nagdudulot ng #C0xE69900#520% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*75)$ Pisikal na Pinsala#C0xF13B54#C0x5B545B#, nagdudulot ng 20% na laning pinsala sa mga nakapaligid na target, nagdaragdag ng bulag na epekto sa loob ng 2 turn (bulag: negatibong epekto, bawasan ang hit rate ng pangunahing target ng 65% at hit rate ng paligid ng target ng 35%)',
		zawakeEffectDesc_ma = 'Edward mengumpul kekuatan yang mengandungi tenaga gelap, menggunakan formasi latihan terlarang pada sasaran musuh tunggal, menyebabkan #C0xE69900#520% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*75)$ Kerosakan Fizikal#C0xF13B54#C0x5B545B#, menyebabkan kerosakan berjangkit 20% kepada sasaran sekitar, menambahkan efek kabur selama 2 pusingan (kabur: efek negatif, mengurangkan ketepatan sasaran utama sebanyak 65% dan sasaran sekitar sebanyak 35%)',
		zawakeEffectDesc_vn = 'Edward tích tụ sức mạnh chứa đựng khí tối, sử dụng trận luyện cấm kỵ đối với mục tiêu đơn lẻ của kẻ địch, gây ra #C0xE69900#520% Công Vật Lý#C0x5B545B#+$(skillLevel*4*75)$ Sát Thương Vật Lý#C0xF13B54#C0x5B545B#, gây sát thương lan 20% cho các mục tiêu xung quanh, thêm <mù> 2 lượt (mù: hiệu ứng tiêu cực, giảm 65% tỷ lệ trúng đích của mục tiêu chính, giảm 35% tỷ lệ trúng đích của mục tiêu xung quanh)',
		zawakeSimpleType = 2,
