	[28213] = {
		id = 28213,
		skillName_vn = 'Sóng ác',
		skillName_en = 'Evil wave',
		skillName_th = 'คลื่นชั่วร้าย',
		skillName_in = 'Gelombang jahat',
		skillName_ph = 'Masamang alon',
		skillName_ma = 'Gelombang jahat',
		skillName = 'Evil wave',
		describe_vn = 'Zoroa hóa thân thành bí ẩn đen tối và liên tục tấn công mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#460% Công Phép thuật#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, nếu mục tiêu chưa chết, sẽ hóa thân thành mục tiêu trong 1 lượt, trong thời gian hóa thân sẽ không trở thành mục tiêu tấn công của kẻ địch (trong thời gian hóa thân có thể bị mục tiêu hóa thân chọn), và được hưởng toàn bộ hiệu ứng tăng cường của kẻ địch',
		describe_en = 'Zoroa transforms into a dark mystery and continuously attacks a single enemy target, dealing #C0x3D8A99#460% Magic Power#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Magic Damage #C0x5B545B#. If the target is not killed, Zoroa will transform into the target for 1 turn. During the transformation, Zoroa cannot be targeted by enemy attacks (but can be targeted by the transformation target) and benefits from all of the enemy\'s buffs.',
		describe_th = 'โซโรอาแปลงร่างเป็นความลึกลับดำมืดและโจมตีเป้าหมายศัตรูทีละตัวอย่างต่อเนื่อง สร้างความเสียหายเวทมนตร์ #C0x3D8A99#460% พลังเวทมนตร์#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# หากเป้าหมายยังไม่ตาย โซโรอาจแปลงร่างเป็นเป้าหมายนั้นเป็นเวลา 1 เทิร์น ในช่วงที่แปลงร่างจะไม่ถูกศัตรูโจมตี (แต่สามารถถูกเป้าหมายที่แปลงร่างเลือกโจมตีได้) และได้รับผลบัฟทั้งหมดของศัตรู',
		describe_in = 'Zoroa berubah menjadi misteri gelap dan terus menyerang satu target musuh, memberikan #C0x3D8A99#460% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Damage Sihir #C0x5B545B#. Jika target belum mati, Zoroa akan berubah menjadi target tersebut selama 1 giliran. Selama transformasi, Zoroa tidak dapat menjadi target serangan musuh (tetapi dapat menjadi target oleh target transformasi) dan mendapatkan semua efek peningkatan dari musuh.',
		describe_ph = 'Nagbabago si Zoroa sa isang madilim na misteryo at tuloy-tuloy na inaatake ang iisang target na kalaban, na nagdudulot ng #C0x3D8A99#460% Lakas ng Magic#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Pinsala sa Magic #C0x5B545B#. Kung hindi pa namamatay ang target, magbabago si Zoroa sa target na iyon sa loob ng 1 turn. Sa panahon ng pagbabago, hindi matatarget ni kalaban ang pag-atake (ngunit maaaring maitarget ng target ng pagbabago), at tinatamasa ang lahat ng mga buff ng kalaban.',
		describe_ma = 'Zoroa berubah menjadi misteri gelap dan berterusan menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#460% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Jika sasaran belum mati, Zoroa akan berubah menjadi sasaran itu selama 1 pusingan. Semasa transformasi, Zoroa tidak boleh menjadi sasaran serangan musuh (tetapi boleh menjadi sasaran oleh sasaran transformasi) dan mendapat semua kesan peningkatan dari musuh.',
		describe = 'Zoroa transforms into a dark mystery and continuously attacks a single enemy target, dealing #C0x3D8A99#460% Magic Power#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Magic Damage #C0x5B545B#. If the target is not killed, Zoroa will transform into the target for 1 turn. During the transformation, Zoroa cannot be targeted by enemy attacks (but can be targeted by the transformation target) and benefits from all of the enemy\'s buffs.',
		simDesc_vn = 'Sora biến thành một bóng đen, liên tục tấn công mục tiêu đơn lẻ của kẻ thù. Nếu mục tiêu chưa chết, sẽ hóa thành mục tiêu đó.',
		simDesc_en = 'Sora transforms into a shadow, relentlessly attacking the enemy\'s single target. If the target is not defeated, Sora will transform into that target.',
		simDesc_th = 'โซระกลายเป็นเงามืด โจมตีเป้าหมายเดียวของศัตรูอย่างต่อเนื่อง หากเป้าหมายยังไม่ตาย โซระจะกลายเป็นเป้าหมายนั้น',
		simDesc_in = 'Sora berubah menjadi bayangan, terus menyerang satu target musuh. Jika target belum mati, Sora akan berubah menjadi target tersebut.',
		simDesc_ph = 'Si Sora ay naging isang anino, patuloy na inaatake ang isang target ng kaaway. Kung hindi pa patay ang target, si Sora ay magiging katulad ng target na iyon.',
		simDesc_ma = 'Sora berubah menjadi bayangan, menyerang sasaran tunggal musuh tanpa henti. Jika sasaran belum mati, Sora akan berubah menjadi sasaran tersebut.',
		simDesc = 'Sora transforms into a shadow, relentlessly attacking the enemy\'s single target. If the target is not defeated, Sora will transform into that target.',
		starEffect = __data_t__starEffect[28213],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sát thương mà bản thân nhận được từ mục tiêu bị ảo hóa trong kỹ năng đặc biệt sẽ được mục tiêu đó gánh chịu 20%.',
		starEffectDesc = 'Additional effect: 20% of the damage you receive from targets that are hallucinated in the special skill will be borne by those targets.',
		starEffectDesc_en = 'Additional effect: 20% of the damage you receive from targets that are hallucinated in the special skill will be borne by those targets.',
		starEffectDesc_th = 'ผลเสริม: ความเสียหายที่คุณได้รับจากเป้าหมายที่ถูกหลอกลวงในทักษะพิเศษ จะถูกเป้าหมายนั้นรับไว้ 20%',
		starEffectDesc_in = 'Efek tambahan: 20% dari kerusakan yang Anda terima dari target yang terhalusinasi dalam keterampilan khusus akan ditanggung oleh target tersebut.',
		starEffectDesc_ph = 'Karagdagang epekto: 20% ng pinsalang natatanggap mo mula sa mga target na nalilinlang sa espesyal na kakayahan ay dadalhin ng mga target na iyon.',
		starEffectDesc_ma = 'Kesan tambahan: 20% daripada kerosakan yang anda terima daripada sasaran yang halusinasi dalam kemahiran khas akan ditanggung oleh sasaran tersebut.',
		upLvDesc = 'Fixed damage +300',
		upLvDesc_en = 'Fixed damage +300',
