	[28216] = {
		id = 28216,
		skillName_vn = 'Ảo ảnh lừa dối',
		skillName_en = 'Illusion deceit',
		skillName_th = 'มายาหลอกลวง',
		skillName_in = 'Ilusi tipu daya',
		skillName_ph = 'Pagkukunwari ng ilusyon',
		skillName_ma = 'Ilusi penipuan',
		skillName = 'Illusion deceit',
		describe_vn = 'Trước khi bắt đầu lượt chiến đấu, hóa thân thành anh hùng có Công Phép cao nhất của kẻ địch, trong thời gian hóa thân sẽ không trở thành mục tiêu tấn công của kẻ địch (trong thời gian hóa thân có thể bị mục tiêu hóa thân chọn, khi hóa thân thành anh hùng có Công Phép cao hơn bản thân có 20% xác suất không kế thừa hiệu quả kỹ năng bị động của họ), và nhận được toàn bộ hiệu ứng tăng cường #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B# của kẻ địch, kéo dài 2 lượt',
		describe_en = 'Before starting the battle turn, transform into the enemy hero with the highest Magic Power. During the transformation, you cannot be targeted by enemy attacks (you can still be targeted by transformed heroes). When transforming into a hero with higher Magic Power than yourself, there is a 20% chance not to inherit their passive skill effects. Additionally, receive all buff effects from the enemy at #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B# strength, lasting 2 turns.',
		describe_th = 'ก่อนเริ่มรอบการต่อสู้ แปลงร่างเป็นฮีโร่ที่มีพลังเวทมนตร์สูงสุดของศัตรู ในระหว่างการแปลงร่างจะไม่ถูกโจมตีโดยศัตรู (แต่ยังสามารถถูกเป้าหมายโดยฮีโร่ที่แปลงร่างได้) เมื่อแปลงร่างเป็นฮีโร่ที่มีพลังเวทสูงกว่าตัวเอง มีโอกาส 20% ที่จะไม่สืบทอดผลทักษะพาสซีฟของพวกเขา และรับเอฟเฟกต์บัฟทั้งหมดจากศัตรูที่แรง #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B# เป็นเวลา 2 รอบ',
		describe_in = 'Sebelum memulai giliran pertempuran, bertransformasi menjadi pahlawan musuh dengan Kekuatan Magis tertinggi. Selama transformasi, tidak akan menjadi target serangan musuh (tetap bisa dipilih sebagai target oleh pahlawan yang bertransformasi). Saat bertransformasi menjadi pahlawan dengan Kekuatan Magis lebih tinggi dari diri sendiri, ada kemungkinan 20% untuk tidak mewarisi efek skill pasif mereka. Selain itu, menerima semua efek buff dari musuh dengan kekuatan #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B#, bertahan selama 2 giliran.',
		describe_ph = 'Bago magsimula ng turn ng laban, mag-transform bilang ang bayani ng kalaban na may pinakamataas na Magic Power. Sa panahon ng transformation, hindi magiging target ng mga kalaban (maaari pa ring mapili bilang target ng mga transformed heroes). Kapag nag-transform bilang bayani na may mas mataas na Magic Power kaysa sa sarili, may 20% chance na hindi mamanahin ang kanilang passive skill effects. At tatanggapin ang lahat ng buff effects ng kalaban sa lakas na #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B#, tumatagal ng 2 turns.',
		describe_ma = 'Sebelum memulakan pusingan pertempuran, bertukar menjadi wira dengan Kuasa Sihir tertinggi musuh. Semasa penukaran, tidak akan menjadi sasaran serangan musuh (tetapi masih boleh disasarkan oleh wira yang bertukar). Apabila bertukar menjadi wira dengan Kuasa Sihir lebih tinggi dari diri sendiri, terdapat peluang 20% untuk tidak mewarisi kesan kemahiran pasif mereka. Selain itu, terima semua kesan penambahbaikan dari musuh dengan kekuatan #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B#, bertahan selama 2 pusingan.',
		describe = 'Before starting the battle turn, transform into the enemy hero with the highest Magic Power. During the transformation, you cannot be targeted by enemy attacks (you can still be targeted by transformed heroes). When transforming into a hero with higher Magic Power than yourself, there is a 20% chance not to inherit their passive skill effects. Additionally, receive all buff effects from the enemy at #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B# strength, lasting 2 turns.',
		starEffect = __data_t__starEffect[28216],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sát thương nhận được từ mục tiêu bị ảo hóa trong kỹ năng thụ động sẽ giảm 20%.',
		starEffectDesc = 'Additional effect: Damage received from targets affected by the illusion in the passive skill is reduced by 20%.',
		starEffectDesc_en = 'Additional effect: Damage received from targets affected by the illusion in the passive skill is reduced by 20%.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: ความเสียหายที่ได้รับจากเป้าหมายที่ถูกลวงตาในสกิลพาสซีฟจะลดลง 20%',
		starEffectDesc_in = 'Efek tambahan: Damage yang diterima dari target yang terkena ilusi dalam skill pasif akan berkurang 20%.',
		starEffectDesc_ph = 'Karagdagang epekto: Ang pinsalang natatanggap mula sa mga target na naapektuhan ng ilusyon sa passive skill ay nababawasan ng 20%.',
		starEffectDesc_ma = 'Kesan tambahan: Kerosakan yang diterima daripada sasaran yang terpesona dalam kemahiran pasif akan dikurangkan sebanyak 20%.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
