	[28223] = {
		id = 28223,
		skillName_vn = 'Sóng ác',
		skillName_en = 'Evil wave',
		skillName_th = 'คลื่นร้าย',
		skillName_in = 'Gelombang jahat',
		skillName_ph = 'Masamang alon',
		skillName_ma = 'Gelombang jahat',
		skillName = 'Evil wave',
		describe_vn = 'Zoroark mượn sức mạnh ánh trăng, nhảy lên cao, tạo ra sóng năng lượng đỏ tấn công mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#470% Công Phép#C0x5B545B#+$(skillLevel*4*75)$ Sát Thương Phép Thuật#C0xF13B54#, nếu mục tiêu không chết, sẽ hóa thân thành mục tiêu trong 1 lượt, trong thời gian hóa thân sẽ không trở thành mục tiêu tấn công của kẻ địch (trong thời gian hóa thân có thể bị mục tiêu hóa thân chọn), và nhận được toàn bộ hiệu ứng tăng cường của kẻ địch',
		describe_en = 'Zoroark borrows the power of the moonlight, leaps high, generating a red energy wave to attack a single enemy target, dealing #C0x3D8A99#470% Magical Power#C0x5B545B# + $(skillLevel*4*75)$ Magical Damage#C0xF13B54#. If the target is not killed, Zoroark will transform into the target for 1 turn. During the transformation, Zoroark will not be targeted by enemy attacks (but can be targeted by the transformed target) and will receive all buff effects from the enemy.',
		describe_th = 'โซโรอาร์กยืมพลังแห่งแสงจันทร์ กระโดดสูง สร้างคลื่นพลังงานสีแดงโจมตีเป้าหมายศัตรูเดี่ยว ก่อให้เกิดความเสียหายเวทมนตร์ #C0x3D8A99#470% พลังเวท#C0x5B545B# + $(skillLevel*4*75)$ ความเสียหายเวทมนตร์#C0xF13B54# หากเป้าหมายไม่ตาย จะเปลี่ยนร่างเป็นเป้าหมายเป็นเวลา 1 เทิร์น ในระหว่างเปลี่ยนร่างจะไม่ถูกโจมตีโดยศัตรู (แต่สามารถถูกเป้าหมายที่แปลงร่างเลือกโจมตีได้) และจะได้รับผลบัฟทั้งหมดจากศัตรู',
		describe_in = 'Zoroark meminjam kekuatan sinar bulan, melompat tinggi, menciptakan gelombang energi merah untuk menyerang satu target musuh, menyebabkan #C0x3D8A99#470% Kekuatan Magis#C0x5B545B# + $(skillLevel*4*75)$ Kerusakan Magis#C0xF13B54#. Jika target tidak mati, akan berubah menjadi target selama 1 giliran. Selama transformasi, tidak akan menjadi sasaran serangan musuh (namun dapat menjadi sasaran oleh target yang berubah wujud) dan menerima semua efek peningkatan dari musuh.',
		describe_ph = 'Hinihiram ni Zoroark ang kapangyarihan ng liwanag ng buwan, tumatalon nang mataas, lumilikha ng pulang alon ng enerhiya upang atakihin ang isang solong target na kalaban, na nagdudulot ng #C0x3D8A99#470% Lakas ng Mahika#C0x5B545B# + $(skillLevel*4*75)$ Pinsala ng Mahika#C0xF13B54#. Kung hindi mamamatay ang target, magbabago siya sa target sa loob ng 1 turn. Sa panahon ng pagbabagong-anyo, hindi siya magiging layunin ng mga kalaban (ngunit maaaring maging layunin ng target na pinagbabagong-anyo) at tatanggap ng lahat ng mga epekto ng pampalakas mula sa kalaban.',
		describe_ma = 'Zoroark meminjam kekuatan sinar bulan, melompat tinggi, menghasilkan gelombang tenaga merah untuk menyerang sasaran musuh tunggal, menyebabkan #C0x3D8A99#470% Kuasa Sihir#C0x5B545B# + $(skillLevel*4*75)$ Kerosakan Sihir#C0xF13B54#. Jika sasaran tidak mati, dia akan berubah menjadi sasaran itu selama 1 giliran. Semasa penukaran, tidak akan menjadi sasaran serangan musuh (tetapi boleh menjadi sasaran oleh sasaran yang menjadi) dan menerima semua kesan peningkatan dari musuh.',
		describe = 'Zoroark borrows the power of the moonlight, leaps high, generating a red energy wave to attack a single enemy target, dealing #C0x3D8A99#470% Magical Power#C0x5B545B# + $(skillLevel*4*75)$ Magical Damage#C0xF13B54#. If the target is not killed, Zoroark will transform into the target for 1 turn. During the transformation, Zoroark will not be targeted by enemy attacks (but can be targeted by the transformed target) and will receive all buff effects from the enemy.',
		simDesc_vn = 'Zoroark tận dụng sức mạnh của ánh trăng, nhảy lên cao, gây ra sóng năng lượng đỏ vào mục tiêu đơn lẻ của kẻ thù. Nếu mục tiêu chưa chết, sẽ hóa thành mục tiêu đó.',
		simDesc_en = 'Zoroark harnesses the power of the moonlight, leaping high and unleashing a wave of red energy at a single enemy target. If the target is not defeated, Zoroark will transform into that target.',
		simDesc_th = 'โซโรอาร์คใช้พลังจากแสงจันทร์ กระโดดสูงและปล่อยคลื่นพลังงานสีแดงใส่เป้าหมายศัตรูหนึ่งตัว หากเป้าหมายยังไม่ตาย โซโรอาร์คจะกลายร่างเป็นเป้าหมายนั้น',
		simDesc_in = 'Zoroark memanfaatkan kekuatan cahaya bulan, melompat tinggi, dan melepaskan gelombang energi merah ke satu target musuh. Jika target belum mati, Zoroark akan berubah menjadi target tersebut.',
		simDesc_ph = 'Pinapakinabangan ni Zoroark ang kapangyarihan ng liwanag ng buwan, tumatalon nang mataas at nagpapalabas ng alon ng pulang enerhiya sa isang target na kaaway. Kung hindi pa patay ang target, magbabago si Zoroark sa hitong iyon.',
		simDesc_ma = 'Zoroark memanfaatkan kekuatan cahaya bulan, melompat tinggi dan menghasilkan gelombang tenaga merah ke satu sasaran musuh. Jika sasaran belum mati, Zoroark akan berubah menjadi sasaran tersebut.',
		simDesc = 'Zoroark harnesses the power of the moonlight, leaping high and unleashing a wave of red energy at a single enemy target. If the target is not defeated, Zoroark will transform into that target.',
		starEffect = __data_t__starEffect[28223],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sát thương mà bản thân nhận được từ mục tiêu bị ảo hóa trong kỹ năng đặc biệt sẽ được mục tiêu đó gánh chịu 20%.',
		starEffectDesc = 'Additional effect: Damage taken by yourself from a target that is hallucinated in a special skill will be absorbed 20% by that target.',
		starEffectDesc_en = 'Additional effect: Damage taken by yourself from a target that is hallucinated in a special skill will be absorbed 20% by that target.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: ความเสียหายที่ตัวคุณได้รับจากเป้าหมายที่ถูกทำให้หลอนในทักษะพิเศษ จะถูกเป้าหมายนั้นรับไว้ 20%',
		starEffectDesc_in = 'Efek tambahan: Kerusakan yang Anda terima dari target yang dihalusinasikan dalam keterampilan khusus akan ditanggung 20% oleh target tersebut.',
		starEffectDesc_ph = 'Karagdagang epekto: Ang pinsala na natatanggap mo mula sa isang target na nahalucinate sa espesyal na kasanayan ay sasagutin ng target na iyon ng 20%.',
		starEffectDesc_ma = 'Kesan tambahan: Kerosakan yang anda terima daripada sasaran yang dihalusinasi dalam kemahiran khas akan ditanggung 20% oleh sasaran tersebut.',
