	[28226] = {
		id = 28226,
		skillName_vn = 'Ảo ảnh lừa dối',
		skillName_en = 'Illusion deception',
		skillName_th = 'ภาพลวงตาหลอกลวง',
		skillName_in = 'Ilusi penipuan',
		skillName_ph = 'Pandaraya ng ilusyon',
		skillName_ma = 'Illusi penipuan',
		skillName = 'Illusion deception',
		describe_vn = 'Trước khi bắt đầu lượt chiến đấu, hóa thân thành anh hùng có Công Phép cao nhất của kẻ địch, trong thời gian hóa thân sẽ không trở thành mục tiêu tấn công của kẻ địch (trong thời gian hóa thân có thể bị mục tiêu hóa thân chọn, khi hóa thân thành anh hùng có Công Phép cao hơn bản thân có 20% xác suất không kế thừa hiệu quả kỹ năng bị động của họ), và nhận được toàn bộ hiệu ứng tăng cường #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B# của kẻ địch, kéo dài 2 lượt',
		describe_en = 'Before starting the battle turn, transform into the enemy hero with the highest Magic Attack. During the transformation, you cannot become a target of enemy attacks (during transformation, you can be targeted by the chosen transformation target. When transforming into a hero with higher Magic Attack than yourself, there is a 20% chance not to inherit their passive skill effects), and receive all buff effects of the enemy increased by #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B#, lasting 2 turns.',
		describe_th = 'ก่อนเริ่มรอบการต่อสู้ แปลงร่างเป็นฮีโร่ที่มีพลังเวทสูงสุดของศัตรู ในช่วงแปลงร่างจะไม่กลายเป็นเป้าหมายการโจมตีของศัตรู (ในช่วงแปลงร่างอาจถูกเลือกเป็นเป้าหมายโดยเป้าหมายแปลงร่างได้ เมื่อแปลงร่างเป็นฮีโร่ที่มีพลังเวทสูงกว่าตัวเอง มีโอกาส 20% ที่จะไม่สืบทอดผลของสกิลพาสซีฟของพวกเขา) และได้รับผลเพิ่มพลังทั้งหมดของศัตรูเพิ่มขึ้น #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B# นาน 2 รอบ',
		describe_in = 'Sebelum memulai giliran bertarung, berubah menjadi pahlawan musuh dengan Serangan Magic tertinggi. Selama transformasi, tidak akan menjadi target serangan musuh (selama transformasi dapat menjadi target yang dipilih transformasi. Saat berubah menjadi pahlawan dengan Serangan Magic lebih tinggi dari diri sendiri, ada peluang 20% untuk tidak mewarisi efek skill pasif mereka), dan menerima semua efek peningkatan dari musuh sebesar #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B#, berlangsung selama 2 giliran.',
		describe_ph = 'Bago simulan ang turn ng laban, mag-transform bilang bayani ng kalaban na may pinakamataas na Magic Attack. Sa panahon ng transformasyon, hindi ka magiging target ng mga kalabang atake (sa panahon ng transformasyon ay maaaring maging target ng napiling transformasyon. Kapag nag-transform bilang bayani na may mas mataas na Magic Attack kaysa sa sarili, may 20% na pagkakataon na hindi mamanahin ang kanilang passive skill effects), at tatanggapin ang lahat ng buff effects ng kalaban na pinalakas ng #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B#, na tatagal ng 2 turns.',
		describe_ma = 'Sebelum memulakan pusingan pertempuran, berubah menjadi wira musuh dengan Serangan Mistik tertinggi. Semasa berubah bentuk, tidak akan menjadi sasaran serangan musuh (semasa berubah bentuk boleh menjadi sasaran yang dipilih oleh transformasi, apabila berubah menjadi wira dengan Serangan Mistik yang lebih tinggi daripada diri, terdapat kebarangkalian 20% untuk tidak mewarisi kesan kemahiran pasif mereka), dan menerima semua kesan peningkatan dari musuh sebanyak #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B#, berlangsung selama 2 pusingan.',
		describe = 'Before starting the battle turn, transform into the enemy hero with the highest Magic Attack. During the transformation, you cannot become a target of enemy attacks (during transformation, you can be targeted by the chosen transformation target. When transforming into a hero with higher Magic Attack than yourself, there is a 20% chance not to inherit their passive skill effects), and receive all buff effects of the enemy increased by #C0x5c9970#$(70+skillLevel*0.3-0.3)$%#C0x5B545B#, lasting 2 turns.',
		starEffect = __data_t__starEffect[28226],
		-- {8}
