		skillName_in = 'Cahaya Ilusi',
		skillName_ph = 'Ilusyon ng Liwanag',
		skillName_ma = 'Cahaya Ilusi',
		skillName = 'Illusory Light',
		describe_vn = 'Goethe Bébé tức giận phát ra tia sáng ảo ảnh đen trắng tấn công mục tiêu đơn lẻ của kẻ địch, gây sát thương phép #C0x3D8A99#130% Công Phép#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# sát thương phép#C0x5B545B#, và thông qua dẫn truyền không gian, truyền thêm sát thương phép #C0x3D8A99#100% Công Phép#C0x5B545B# của anh hùng có Công Phép cao nhất bên ta cho mục tiêu đơn lẻ của kẻ địch',
		describe_en = 'Goethe Bébé angrily emits black and white illusion light to attack a single enemy target, dealing magical damage of #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# magical damage#C0x5B545B#, and through spatial conduction, additionally transmits magical damage equal to #C0x3D8A99#100% Magic Power#C0x5B545B# of the hero with the highest Magic Power on our side to a single enemy target.',
		describe_th = 'โกเธ่ เบเบ้ โกรธจัดปล่อยแสงลวงตาสีขาวดำโจมตีเป้าหมายศัตรูเดี่ยว ก่อให้เกิดความเสียหายเวท #C0x3D8A99#130% พลังเวท#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายเวท#C0x5B545B# และผ่านการส่งผ่านเชิงพื้นที่ ส่งต่อความเสียหายเวทเพิ่มเติม #C0x3D8A99#100% พลังเวท#C0x5B545B# ของฮีโร่ที่มีพลังเวทสูงสุดในฝั่งเราให้กับเป้าหมายศัตรูเดี่ยว',
		describe_in = 'Goethe Bébé marah mengeluarkan cahaya ilusi hitam putih untuk menyerang satu target musuh, memberikan kerusakan sihir sebesar #C0x3D8A99#130% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# kerusakan sihir#C0x5B545B#, dan melalui transmisi ruang, menyalurkan tambahan kerusakan sihir sebesar #C0x3D8A99#100% Kekuatan Sihir#C0x5B545B# dari pahlawan dengan Kekuatan Sihir tertinggi di pihak kita ke target musuh tunggal.',
		describe_ph = 'Nag-aalboroto si Goethe Bébé nagpapalabas ng itim-puting ilusyon ng liwanag upang atakihin ang isang kalabang target, na nagdudulot ng magic damage na #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# magic damage#C0x5B545B#, at sa pamamagitan ng transmisyon ng espasyo, nagdadala rin ng karagdagang magic damage na #C0x3D8A99#100% Magic Power#C0x5B545B# mula sa bayani na may pinakamataas na Magic Power sa aming panig sa isang kalabang target.',
		describe_ma = 'Goethe Bébé marah mengeluarkan cahaya ilusi hitam dan putih menyerang satu sasaran musuh, menyebabkan kerosakan magik #C0x3D8A99#130% Kuasa Magik#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# kerosakan magik#C0x5B545B#, dan melalui pemindahan ruang, menyalurkan tambahan kerosakan magik #C0x3D8A99#100% Kuasa Magik#C0x5B545B# wira dengan Kuasa Magik tertinggi di pihak kita kepada satu sasaran musuh.',
		describe = 'Goethe Bébé angrily emits black and white illusion light to attack a single enemy target, dealing magical damage of #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# magical damage#C0x5B545B#, and through spatial conduction, additionally transmits magical damage equal to #C0x3D8A99#100% Magic Power#C0x5B545B# of the hero with the highest Magic Power on our side to a single enemy target.',
		simDesc_vn = 'Gothita tức giận phát ra tia sáng ảo ảnh đen trắng tấn công mục tiêu đơn lẻ của kẻ thù, và thêm một lần truyền dẫn sát thương từ đơn vị tấn công cao nhất của đội mình.',
		simDesc_en = 'Gothita angrily emits black and white illusion rays that attack a single enemy target, and adds one damage transfer from the highest attacking unit in its team.',
		simDesc_th = 'โกธิตะปล่อยแสงลวงตาสีดำขาวอย่างโกรธเคืองโจมตีเป้าหมายศัตรูเดียว และเพิ่มการถ่ายโอนความเสียหายหนึ่งครั้งจากหน่วยที่โจมตีสูงที่สุดในทีมของมัน',
		simDesc_in = 'Gothita dengan marah memancarkan sinar ilusi hitam putih yang menyerang satu target musuh, dan menambahkan satu transmisi kerusakan dari unit dengan serangan tertinggi dalam timnya.',
		simDesc_ph = 'Galit na naglalabas si Gothita ng itim at puting sinag na ilusyon na umatake sa isang target na kaaway, at nagdadagdag ng isang beses na paglilipat ng pinsala mula sa pinakamataas na attacking unit ng kanyang koponan.',
		simDesc_ma = 'Gothita dengan marah memancarkan sinar ilusi hitam putih yang menyerang satu sasaran musuh, dan menambah satu penghantaran kerosakan dari unit serangan tertinggi dalam pasukannya.',
		simDesc = 'Gothita angrily emits black and white illusion rays that attack a single enemy target, and adds one damage transfer from the highest attacking unit in its team.',
		zawakeEffect = __data_t__zawakeEffect[28412],
		-- {79002}
		zawakeEffectDesc = 'Goethe\'s angry child emits black-and-white illusion light rays attacking a single enemy target, dealing #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ Magic Damage#C0xF13B54#C0x5B545B#, and through spatial conduction, transmits additional Magic Damage #C0x3D8A99#100% Magic Power#C0x5B545B# from the hero with the highest Magic Power on our side to this attacked target and another random enemy unit',
		zawakeEffectDesc_en = 'Goethe\'s angry child emits black-and-white illusion light rays attacking a single enemy target, dealing #C0x3D8A99#130% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ Magic Damage#C0xF13B54#C0x5B545B#, and through spatial conduction, transmits additional Magic Damage #C0x3D8A99#100% Magic Power#C0x5B545B# from the hero with the highest Magic Power on our side to this attacked target and another random enemy unit',
		zawakeEffectDesc_th = 'เด็ก Goethe ที่โกรธจัดปล่อยแสงลวงตาสีขาวดำโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0x3D8A99#130% พลังเวท#C0x5B545B#+$(skillLevel*4*48)$ ความเสียหายเวทเวท#C0xF13B54#C0x5B545B# และผ่านการนำพาพื้นที่ ส่งต่อความเสียหายเวท #C0x3D8A99#100% พลังเวท#C0x5B545B# จากฮีโร่ที่มีพลังเวทสูงสุดในฝั่งเราไปยังเป้าหมายที่ถูกโจมตีและอีกหนึ่งหน่วยศัตรูแบบสุ่ม',
		zawakeEffectDesc_in = 'Anak Goethe yang marah mengeluarkan sinar ilusi hitam putih menyerang satu target musuh, memberikan #C0x3D8A99#130% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*48)$ Kerusakan Sihir#C0xF13B54#C0x5B545B#, dan melalui konduksi ruang, mentransmisikan tambahan Kerusakan Sihir #C0x3D8A99#100% Kekuatan Sihir#C0x5B545B# dari pahlawan dengan Kekuatan Sihir tertinggi di pihak kita ke target yang diserang kali ini dan satu unit musuh acak lainnya',
		zawakeEffectDesc_ph = 'Ang batang Goethe na galit ay naglalabas ng itim-puting ilusyong liwanag na sumasalakay sa isang solong target na kalaban, nagdudulot ng #C0x3D8A99#130% Lakas ng Mahika#C0x5B545B#+$(skillLevel*4*48)$ Pinsalang Mahika#C0xF13B54#C0x5B545B#, at sa pamamagitan ng paghahatid sa espasyo, naglilipat ng karagdagang Pinsalang Mahika #C0x3D8A99#100% Lakas ng Mahika#C0x5B545B# mula sa bayani na may pinakamataas na Lakas ng Mahika sa aming panig sa target na inatake sa pagkakataong ito at isa pang random na yunit ng kalaban',
		zawakeEffectDesc_ma = 'Anak Goethe yang marah mengeluarkan sinar ilusi hitam putih menyerang satu sasaran musuh tunggal, menyebabkan #C0x3D8A99#130% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$ Kerosakan Sihir#C0xF13B54#C0x5B545B#, dan melalui penghantaran ruang, menyalurkan tambahan Kerosakan Sihir #C0x3D8A99#100% Kuasa Sihir#C0x5B545B# daripada wira dengan Kuasa Sihir tertinggi di pihak kita kepada sasaran yang diserang ini dan satu unit musuh rawak lain',
		zawakeEffectDesc_vn = 'Bé Goethe tức giận phát ra tia sáng ảo ảnh đen trắng tấn công mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#130% Công Phép#C0x5B545B#+$(skillLevel*4*48)$ Sát Thương Phép Thuật#C0xF13B54#C0x5B545B#, và thông qua truyền dẫn không gian, truyền thêm Sát Thương Phép Thuật #C0x3D8A99#100% Công Phép#C0x5B545B# của anh hùng có Công Phép cao nhất của phe ta cho mục tiêu tấn công lần này và một đơn vị kẻ địch ngẫu nhiên khác',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Deals additional damage to a single enemy target\n#F20# \n#F40##C0x5c9970#→Deals additional damage to the current target and a random enemy unit',
		zawakeSimpleDesc_en = 'Deals additional damage to a single enemy target\n#F20# \n#F40##C0x5c9970#→Deals additional damage to the current target and a random enemy unit',
		zawakeSimpleDesc_th = 'สร้างความเสียหายเพิ่มเติมแก่ศัตรูเป้าหมายเดี่ยว\n#F20# \n#F40##C0x5c9970#→สร้างความเสียหายเพิ่มเติมแก่เป้าหมายที่โจมตีและอีกหนึ่งศัตรูแบบสุ่ม',
		zawakeSimpleDesc_in = 'Memberikan damage tambahan ke satu target musuh tunggal\n#F20# \n#F40##C0x5c9970#→Memberikan damage tambahan ke target saat ini dan satu unit musuh acak',
		zawakeSimpleDesc_ph = 'Nagdadagdag ng damage sa isang kalabang target\n#F20# \n#F40##C0x5c9970#→Nagdadagdag ng damage sa kasalukuyang target at isang random na yunit ng kalaban',
		zawakeSimpleDesc_ma = 'Menyerang tambahan satu sasaran musuh tunggal\n#F20# \n#F40##C0x5c9970#→Menyerang tambahan sasaran semasa ini dan satu unit musuh rawak',
		zawakeSimpleDesc_vn = 'Truyền thêm cho một mục tiêu đơn lẻ của kẻ địch\n#F20# \n#F40##C0x5c9970#→Truyền thêm cho mục tiêu tấn công lần này và một đơn vị ngẫu nhiên khác của kẻ địch',
