	[28413] = {
		id = 28413,
		skillName_vn = 'Trường điện từ',
		skillName_en = 'Electromagnetic field',
		skillName_th = 'สนามแม่เหล็กไฟฟ้า',
		skillName_in = 'Medan elektromagnetik',
		skillName_ph = 'Elektromagnetik na patlang',
		skillName_ma = 'Medan elektromagnet',
		skillName = 'Electromagnetic field',
		describe_vn = 'Goethe Bébé bay lên cao, triệu hồi từ trường tinh thần xung quanh mục tiêu đơn lẻ của kẻ địch, sau đó phá vỡ bằng tia sáng, gây sát thương phép #C0x3D8A99#420% Công Phép#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# sát thương phép#C0x5B545B#, và khiến bản thân bước vào không gian dị độ, khiến anh hùng tấn công mình lần tiếp theo bước vào không gian xoắn, chỉ xuất hiện lại khi đến lượt hành động tiếp theo của mục tiêu',
		describe_en = 'Goethe Bébé ascends high, summoning a psychic magnetic field around a single enemy target, then breaking it with a beam of light, dealing magic damage of #C0x3D8A99#420% Magic Power#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# magic damage#C0x5B545B#, and causing himself to enter a warped space, making the next hero who attacks him enter a twisted space, only reappearing when the target\'s next action turn arrives.',
		describe_th = 'Goethe Bébé บินขึ้นสูง เรียกสนามแม่เหล็กจิตใจรอบเป้าหมายศัตรูเดี่ยว จากนั้นทำลายด้วยลำแสง สร้างความเสียหายเวทมนตร์ #C0x3D8A99#420% พลังเวท#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# ความเสียหายเวท#C0x5B545B# และทำให้ตัวเองเข้าสู่มิติผิดเพี้ยน ทำให้ฮีโร่คนต่อไปที่โจมตีเขาเข้าสู่มิติบิดเบี้ยว ซึ่งจะปรากฏขึ้นอีกครั้งเมื่อถึงตาทำการของเป้าหมายคนต่อไปเท่านั้น',
		describe_in = 'Goethe Bébé terbang tinggi, memanggil medan magnet psikis di sekitar target musuh tunggal, kemudian memecahkannya dengan sinar cahaya, menyebabkan kerusakan sihir sebesar #C0x3D8A99#420% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# kerusakan sihir#C0x5B545B#, dan membuat dirinya masuk ke ruang terdistorsi, membuat pahlawan berikutnya yang menyerangnya masuk ke ruang berpilin, hanya muncul kembali saat giliran aksi target berikutnya tiba.',
		describe_ph = 'Goethe Bébé lumilipad nang mataas, tinatawag ang psychic magnetic field sa paligid ng isang kalabang target, pagkatapos ay binabasag ito gamit ang sinag ng liwanag, nagdudulot ng magic damage na #C0x3D8A99#420% Magic Power#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# magic damage#C0x5B545B#, at nagpapasok sa kanyang sarili sa isang warped space, dahilan upang ang susunod na bayani na umatake sa kanya ay pumasok sa twisted space, at muling lilitaw lamang kapag dumating ang susunod na turno ng pagkilos ng target.',
		describe_ma = 'Goethe Bébé terbang tinggi, memanggil medan magnet psikik di sekitar sasaran musuh tunggal, kemudian memecahkannya dengan pancaran cahaya, menyebabkan kerosakan sihir sebanyak #C0x3D8A99#420% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# kerosakan sihir#C0x5B545B#, dan menyebabkan dirinya memasuki ruang berlekuk, menyebabkan wira yang menyerangnya seterusnya memasuki ruang berpilin, hanya muncul semula apabila giliran tindakan sasaran berikutnya tiba.',
		describe = 'Goethe Bébé ascends high, summoning a psychic magnetic field around a single enemy target, then breaking it with a beam of light, dealing magic damage of #C0x3D8A99#420% Magic Power#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# magic damage#C0x5B545B#, and causing himself to enter a warped space, making the next hero who attacks him enter a twisted space, only reappearing when the target\'s next action turn arrives.',
		simDesc_vn = 'Gothita bay lên cao, triệu hồi một trường năng lượng xung quanh mục tiêu đơn lẻ của kẻ thù, sau đó dùng tia sáng phá hủy, và tự mình vào không gian khác, khiến hero tấn công mình lần sau sẽ vào không gian méo, cho đến khi vòng hành động tiếp theo của mục tiêu đó.',
		simDesc_en = 'Gothita flies high, summons an energy field around a single enemy target, then uses a beam of light to destroy, and retreats into another dimension, causing any hero who attacks it next to be pulled into a warped space until that target\'s next action turn.',
		simDesc_th = 'ก็อตติต้าบินขึ้นสูง เรียกสนามพลังรอบเป้าหมายศัตรูเพียงหนึ่งตัว จากนั้นใช้แสงยิงทำลาย และหลบเข้าสู่อีกมิติเพื่อให้ฮีโร่ที่โจมตีตัวมันครั้งถัดไปตกอยู่ในมิติเว้าแหว่งจนกว่าจะถึงรอบการกระทำถัดไปของเป้าหมายคนนั้น',
		simDesc_in = 'Gothita terbang tinggi, memanggil medan energi di sekitar satu target musuh, kemudian menggunakan sinar cahaya untuk menghancurkan, dan masuk ke dimensi lain, membuat hero yang menyerangnya berikutnya masuk ke ruang terdistorsi sampai giliran aksi berikutnya dari target tersebut.',
		simDesc_ph = 'Lumilipad si Gothita nang mataas, nag-summon ng field ng enerhiya sa paligid ng isang kalabang target, pagkatapos ay gumagamit ng light beam para sirain ito, at pumasok sa ibang dimensyon, na nagiging sanhi na ang hero na susunod na tatakbo laban sa kanya ay papasok sa warped space hanggang sa susunod na action turn ng target na iyon.',
		simDesc_ma = 'Gothita terbang tinggi, memanggil medan tenaga di sekitar satu sasaran musuh, kemudian menggunakan pancaran cahaya untuk memusnahkan, dan memasuki dimensi lain, menyebabkan hero yang menyerangnya seterusnya akan memasuki ruang terapung sehingga giliran tindakan berikutnya sasaran itu.',
		simDesc = 'Gothita flies high, summons an energy field around a single enemy target, then uses a beam of light to destroy, and retreats into another dimension, causing any hero who attacks it next to be pulled into a warped space until that target\'s next action turn.',
