		skillName_ph = 'Illusion Beam',
		skillName_ma = 'Sinar Ilusi',
		skillName = 'Illusion Beam',
		describe_vn = 'Goethe Bébé nhỏ nhảy lên rồi phát ra tia sáng ảo ảnh màu hồng tấn công mục tiêu đơn lẻ của kẻ địch, gây sát thương phép #C0x3D8A99#140% Công Phép#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# sát thương phép#C0x5B545B#, và thông qua dẫn truyền không gian, truyền thêm sát thương phép #C0x3D8A99#100% Công Phép#C0x5B545B# của anh hùng có Công Phép cao nhất bên ta cho mục tiêu đơn lẻ của kẻ địch',
		describe_en = 'Goethe Baby jumps up and emits a pink illusion light to attack a single enemy target, dealing magical damage of #C0x3D8A99#140% Magic Power#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# magical damage#C0x5B545B#, and through spatial conduction, transfers additional magical damage of #C0x3D8A99#100% Magic Power#C0x5B545B# from the hero with the highest Magic Power on our side to a single enemy target.',
		describe_th = 'โคเธ่ เบบี้ กระโดดขึ้นและปล่อยแสงลวงตาสีชมพูโจมตีเป้าหมายศัตรูเดี่ยว ทำความเสียหายเวท #C0x3D8A99#140% พลังเวท#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายเวท#C0x5B545B# และผ่านการนำพาพื้นที่ ส่งต่อความเสียหายเวทเพิ่มเติม #C0x3D8A99#100% พลังเวท#C0x5B545B# จากฮีโร่ที่มีพลังเวทสูงสุดฝ่ายเราไปยังเป้าหมายศัตรูเดี่ยว',
		describe_in = 'Goethe Bayi melompat dan memancarkan cahaya ilusi merah muda untuk menyerang satu target musuh, menyebabkan kerusakan sihir sebesar #C0x3D8A99#140% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# kerusakan sihir#C0x5B545B#, dan melalui konduksi ruang, mentransfer kerusakan sihir tambahan sebesar #C0x3D8A99#100% Kekuatan Sihir#C0x5B545B# dari pahlawan dengan Kekuatan Sihir tertinggi di pihak kita ke satu target musuh.',
		describe_ph = 'Tumalon ang Goethe Baby at naglabas ng rosas na ilusyon na liwanag upang atakihin ang isang kalabang target, na nagdudulot ng mahikal na pinsala na #C0x3D8A99#140% Lakas ng Mahika#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# mahikal na pinsala#C0x5B545B#, at sa pamamagitan ng spatial conduction, nagpapasa ng karagdagang mahikal na pinsala na #C0x3D8A99#100% Lakas ng Mahika#C0x5B545B# mula sa bayaning may pinakamataas na Lakas ng Mahika sa atin papunta sa isang kalabang target.',
		describe_ma = 'Goethe Bayi melompat dan memancarkan cahaya ilusi warna merah jambu untuk menyerang satu sasaran musuh, menyebabkan kerosakan sihir sebanyak #C0x3D8A99#140% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# kerosakan sihir#C0x5B545B#, dan melalui penghantaran ruang, memindahkan kerosakan sihir tambahan sebanyak #C0x3D8A99#100% Kuasa Sihir#C0x5B545B# daripada wira dengan Kuasa Sihir tertinggi di pihak kita ke satu sasaran musuh.',
		describe = 'Goethe Baby jumps up and emits a pink illusion light to attack a single enemy target, dealing magical damage of #C0x3D8A99#140% Magic Power#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# magical damage#C0x5B545B#, and through spatial conduction, transfers additional magical damage of #C0x3D8A99#100% Magic Power#C0x5B545B# from the hero with the highest Magic Power on our side to a single enemy target.',
		simDesc_vn = 'Gothitelle nhảy lên rồi phóng ra tia sáng ảo ảnh màu hồng tấn công mục tiêu đơn lẻ của kẻ thù, và thêm một lần truyền dẫn sát thương từ đơn vị tấn công cao nhất của đội mình.',
		simDesc_en = 'Gothitelle jumps up and fires a pink illusion beam to attack a single enemy target, and also chains damage once more from the highest attacking unit on your team.',
		simDesc_th = 'กอธิเทลล์กระโดดขึ้นและปล่อยลำแสงลวงตาสีชมพูโจมตีเป้าหมายศัตรูเดี่ยว พร้อมกับส่งผ่านความเสียหายอีกครั้งจากหน่วยที่มีพลังโจมตีสูงสุดในทีมของคุณ',
		simDesc_in = 'Gothitelle melompat dan menembakkan sinar ilusi merah muda untuk menyerang target musuh tunggal, serta menyalurkan damage sekali lagi dari unit dengan serangan tertinggi di tim kamu.',
		simDesc_ph = 'Tumalon si Gothitelle at nagpapalabas ng pink na ilusyon na sinag upang atakihin ang isang kalabang target, at nagdadagdag ng isa pang transmisyon ng pinsala mula sa pinakamataas na atakeng yunit ng iyong koponan.',
		simDesc_ma = 'Gothitelle melompat dan melepaskan pancaran ilusi berwarna merah jambu untuk menyerang satu sasaran musuh, dan juga menyalurkan kerosakan sekali lagi dari unit dengan serangan tertinggi dalam pasukan anda.',
		simDesc = 'Gothitelle jumps up and fires a pink illusion beam to attack a single enemy target, and also chains damage once more from the highest attacking unit on your team.',
		zawakeEffect = __data_t__zawakeEffect[28422],
		-- {79002}
		zawakeEffectDesc = 'Goethe makes a small jump then fires a pink illusion light beam to attack a single enemy target, causing #C0x3D8A99#140% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magical Damage #C0x5B545B#, and through spatial conduction, additionally transmits #C0xF13B54# Magical Damage #C0x5B545B# with #C0x3D8A99#100% Magic Power#C0x5B545B# of the ally hero with the highest Magic Power to this attack target and another random enemy unit',
		zawakeEffectDesc_en = 'Goethe makes a small jump then fires a pink illusion light beam to attack a single enemy target, causing #C0x3D8A99#140% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magical Damage #C0x5B545B#, and through spatial conduction, additionally transmits #C0xF13B54# Magical Damage #C0x5B545B# with #C0x3D8A99#100% Magic Power#C0x5B545B# of the ally hero with the highest Magic Power to this attack target and another random enemy unit',
		zawakeEffectDesc_th = 'Goethe กระโดดเล็กน้อยแล้วยิงลำแสงภาพลวงตาสีชมพูโจมตีเป้าหมายศัตรูเดี่ยว ก่อให้เกิด #C0x3D8A99#140% พลังเวท#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# และผ่านการนำทางเชิงพื้นที่ ส่งต่อ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# พร้อมกับ #C0x3D8A99#100% พลังเวท#C0x5B545B# ของฮีโร่ฝ่ายเรา ที่มีพลังเวทสูงสุด ไปยังเป้าหมายการโจมตีนี้และหน่วยศัตรูสุ่มอีกตัวหนึ่ง',
		zawakeEffectDesc_in = 'Goethe melompat kecil lalu menembakkan sinar ilusi berwarna merah muda untuk menyerang satu target musuh, menyebabkan #C0x3D8A99#140% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Magis #C0x5B545B#, dan melalui penghantaran ruang, mengirimkan tambahan #C0xF13B54# Kerusakan Magis #C0x5B545B# dengan #C0x3D8A99#100% Kekuatan Sihir#C0x5B545B# dari pahlawan sekutu dengan Kekuatan Sihir tertinggi ke target serangan ini dan satu unit musuh acak lainnya',
		zawakeEffectDesc_ph = 'Si Goethe ay maliit na tumalon tapos nagpapaputok ng rosas na ilusyon na sinag ng ilaw para atakihin ang isang solong kalabang target, nagdudulot ng #C0x3D8A99#140% Kapangyarihan ng Mahika#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pinsalang Mahika #C0x5B545B#, at sa pamamagitan ng pagpapasa sa espasyo, nagpapadala ng dagdag na #C0xF13B54# Pinsalang Mahika #C0x5B545B# na may #C0x3D8A99#100% Kapangyarihan ng Mahika#C0x5B545B# mula sa kaalyadong bayani na may pinakamataas na Kapangyarihan ng Mahika sa atin sa target na ito at isang ibang random na kalabang yunit',
		zawakeEffectDesc_ma = 'Goethe melompat kecil kemudian menembak pancaran cahaya ilusi berwarna merah jambu untuk menyerang satu sasaran musuh tunggal, menyebabkan #C0x3D8A99#140% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Magikal #C0x5B545B#, dan melalui penghantaran ruang, menyalurkan tambahan #C0xF13B54# Kerosakan Magikal #C0x5B545B# dengan #C0x3D8A99#100% Kuasa Sihir#C0x5B545B# wira sekutu yang mempunyai Kuasa Sihir tertinggi kepada sasaran serangan ini dan satu unit musuh rawak lain',
		zawakeEffectDesc_vn = 'Goethe nhỏ nhảy lên rồi bắn ra tia sáng ảo ảnh màu hồng tấn công mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#140% Công Phép#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, và thông qua dẫn truyền không gian, truyền thêm #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# với #C0x3D8A99#100% Công Phép#C0x5B545B# của anh hùng có Công Phép cao nhất bên ta cho mục tiêu tấn công lần này và một đơn vị kẻ địch ngẫu nhiên khác',
		zawakeSimpleType = 2,
