	[28423] = {
		id = 28423,
		skillName_vn = 'Tấn công tinh thần',
		skillName_en = 'Mental attack',
		skillName_th = 'การโจมตีทางจิต',
		skillName_in = 'Serangan mental',
		skillName_ph = 'Mental na atake',
		skillName_ma = 'Serangan mental',
		skillName = 'Mental attack',
		describe_vn = 'Goethe Bébé nhỏ thiền định tích năng lượng, sau đó phát ra xung kích tinh thần vào mục tiêu đơn lẻ của kẻ địch, gây sát thương phép #C0x3D8A99#440% Công Phép#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# sát thương phép#C0x5B545B#, và khiến bản thân bước vào không gian dị độ, khiến anh hùng tấn công mình lần tiếp theo bước vào không gian xoắn, chỉ xuất hiện lại khi đến lượt hành động tiếp theo của mục tiêu',
		describe_en = 'Goethe Baby meditates to accumulate energy, then releases a spiritual shockwave targeting a single enemy, dealing magic damage of #C0x3D8A99#440% Magic Power#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# magic damage#C0x5B545B#. Meanwhile, he enters a dimensional space state, causing any hero who attacks him next to be trapped in a twisted space, only reappearing when the target\'s next action turn begins.',
		describe_th = 'โกเธ่เบบี้นั่งสมาธิเพื่อสะสมพลังงาน จากนั้นปล่อยคลื่นช็อกจิตใจโจมตีกับศัตรูหนึ่งเป้าหมาย สร้างความเสียหายเวท #C0x3D8A99#440% พลังเวท#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# ความเสียหายเวท#C0x5B545B# และทำให้ตัวเองเข้าสู่มิติที่ผิดปกติ ทำให้ฮีโร่ที่โจมตีเขาครั้งถัดไปติดอยู่ในมิติเวียนกลับ และจะกลับมาอีกครั้งเมื่อถึงตาของเป้าหมายในการลงมือทำครั้งต่อไป',
		describe_in = 'Goethe Bayi bermeditasi untuk mengumpulkan energi, kemudian mengeluarkan gelombang kejut spiritual yang menargetkan musuh tunggal, memberikan kerusakan sihir sebesar #C0x3D8A99#440% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# kerusakan sihir#C0x5B545B#, dan memasuki ruang dimensi yang aneh, menyebabkan pahlawan yang menyerangnya berikutnya terjebak dalam ruang berputar, hanya muncul kembali saat giliran bertindak berikutnya dari target.',
		describe_ph = 'Nagme-meditate si Goethe Baby para mag-ipon ng enerhiya, pagkatapos ay magpapalabas ng espirituwal na shockwave na tutok sa isang kalabang target lamang, na nagdudulot ng magic damage na #C0x3D8A99#440% Magic Power#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# magic damage#C0x5B545B#, at papasok siya sa isang dimensyong kakaiba, na nagpapalagay na anumang bayani na susunod na umatake sa kanya ay mapupunta sa isang paikot-ikot na dimensyon, na muling lilitaw lamang kapag nagsimula ang susunod na turn ng target.',
		describe_ma = 'Goethe Bayi bermeditasi untuk mengumpul tenaga, kemudian melepaskan kejutan rohani yang mensasarkan satu musuh, menyebabkan kerosakan ajaib #C0x3D8A99#440% Kuasa Ajaib#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# kerosakan ajaib#C0x5B545B#, dan memasuki ruang dimensi aneh, menyebabkan wira yang menyerang dirinya seterusnya memasuki ruang bersimpul, hanya muncul semula apabila giliran tindakan seterusnya sasaran tiba.',
		describe = 'Goethe Baby meditates to accumulate energy, then releases a spiritual shockwave targeting a single enemy, dealing magic damage of #C0x3D8A99#440% Magic Power#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# magic damage#C0x5B545B#. Meanwhile, he enters a dimensional space state, causing any hero who attacks him next to be trapped in a twisted space, only reappearing when the target\'s next action turn begins.',
		simDesc_vn = 'Gothitelle thiền để tích trữ năng lượng, sau đó phóng ra cú đấm tâm linh vào mục tiêu đơn lẻ của kẻ thù, và tự mình vào không gian khác, khiến hero tấn công mình lần sau sẽ vào không gian méo, cho đến khi vòng hành động tiếp theo của mục tiêu đó.',
		simDesc_en = 'Gothitelle meditates to accumulate energy, then unleashes a psychic punch on a single enemy target, and slips into another dimension herself, causing the hero\'s next attack on her to enter a twisted space until that target\'s next action turn.',
		simDesc_th = 'กอทิเทลล์นั่งสมาธิเพื่อสะสมพลังงาน จากนั้นปล่อยหมัดจิตวิญญาณใส่เป้าหมายศัตรูเพียงหนึ่งตัว และเข้าสู่อีกมิติหนึ่งเอง ทำให้ฮีโร่ที่โจมตีเธอในครั้งต่อไปจะถูกพาเข้าสู่มิติบิดเบี้ยวจนกว่าจะถึงเทิร์นดำเนินการครั้งต่อไปของเป้าหมายนั้น',
		simDesc_in = 'Gothitelle bermeditasi untuk mengumpulkan energi, kemudian melepaskan pukulan psikis ke satu target musuh, dan memasuki dimensi lain sendiri, menyebabkan serangan berikutnya dari pahlawan terhadapnya masuk ke ruang terdistorsi sampai giliran aksi berikutnya dari target tersebut.',
		simDesc_ph = 'Si Gothitelle ay nagme-meditate para mag-ipon ng enerhiya, pagkatapos ay nagpapalabas ng isang psychikong suntok sa iisang target ng kaaway, at lumilipat sa ibang dimensyon, kaya ang susunod na atake ng hero sa kanya ay mapupunta sa isang baluktot na espasyo hanggang sa susunod na yugto ng pagkilos ng target.',
		simDesc_ma = 'Gothitelle bermeditasi untuk mengumpul tenaga, kemudian melancarkan tumbukan psikis ke sasaran musuh tunggal, dan masuk ke dimensi lain sendiri, menyebabkan serangan hero seterusnya kepadanya masuk ke ruang yang memesong sehingga giliran tindakan seterusnya bagi sasaran tersebut.',
		simDesc = 'Gothitelle meditates to accumulate energy, then unleashes a psychic punch on a single enemy target, and slips into another dimension herself, causing the hero\'s next attack on her to enter a twisted space until that target\'s next action turn.',
