		skillName_ph = 'Pangarap',
		skillName_ma = 'Harapan',
		skillName = 'Wish',
		describe_vn = 'Zombie đèn ma thuật thực hiện một điều ước với chiếc đèn ma thuật và tấn công một mục tiêu kẻ thù, gây #C0x3D8A99#150% Phép Công #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, cũng thông qua thần đăng truyền, đem bên ta Phép Công tối cao anh hùng #C0x3D8A99#100% Phép Công #C0x5B545B# #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# Ngoài định mức truyền lại nhanh nhanh địch quân đơn thể mục tiêu',
		describe_en = 'The Magic Lamp Zombie makes a wish with the magic lamp and attacks an enemy target, dealing #C0x3D8A99#150% Arcane Attack #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#. Also, through the divine lamp transmission, it grants our side the supreme hero Arcane Attack #C0x3D8A99#100% Arcane Attack #C0x5B545B# #C0xF13B54# Magic Damage #C0x5B545B#. Beyond the set limit, it quickly transmits to single enemy units.',
		describe_th = 'ซอมบี้ตะเกียงวิเศษทำตามความปรารถนาด้วยตะเกียงวิเศษและโจมตีเป้าหมายศัตรู ก่อให้เกิด #C0x3D8A99#150% พลังโจมตีเวทย์ #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวทย์ #C0x5B545B# นอกจากนี้ ผ่านการส่งของตะเกียงศักดิ์สิทธิ์ มอบพลังโจมตีสูงสุดของฮีโร่ให้กับฝ่ายเรา #C0x3D8A99#100% พลังโจมตีเวทย์ #C0x5B545B# #C0xF13B54# ความเสียหายเวทย์ #C0x5B545B# นอกเหนือจากขีดจำกัดที่กำหนด จะส่งต่ออย่างรวดเร็วถึงเป้าหมายศัตรูเดี่ยว',
		describe_in = 'Zombie Lampu Ajaib membuat permintaan dengan lampu ajaib dan menyerang target musuh, memberikan #C0x3D8A99#150% Serangan Sihir #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Juga melalui transmisi lampu ilahi, memberikan kepada pihak kita Serangan Sihir tertinggi pahlawan #C0x3D8A99#100% Serangan Sihir #C0x5B545B# #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Di luar batas yang ditentukan, transmisi cepat ke target musuh tunggal.',
		describe_ph = 'Ang Magic Lamp Zombie ay gumagawa ng kahilingan gamit ang magic lamp at inaatake ang isang kaaway na target, na nagdudulot ng #C0x3D8A99#150% Arcane Attack #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#. Gayundin, sa pamamagitan ng pagpasa ng divine lamp, nagbibigay ito sa ating panig ng pinakamataas na Arcane Attack ng bayani #C0x3D8A99#100% Arcane Attack #C0x5B545B# #C0xF13B54# Magic Damage #C0x5B545B#. Higit sa itinakdang limitasyon, mabilis itong nagpapasa sa iisang target ng kaaway.',
		describe_ma = 'Zombie Lampu Ajaib melaksanakan satu permintaan dengan lampu ajaib dan menyerang sasaran musuh, menyebabkan #C0x3D8A99#150% Serangan Sihir #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Juga melalui penghantaran lampu ilahi, memberi pihak kita Serangan Sihir tertinggi wira #C0x3D8A99#100% Serangan Sihir #C0x5B545B# #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Melebihi had ditetapkan, penghantaran pantas kepada sasaran musuh tunggal.',
		describe = 'The Magic Lamp Zombie makes a wish with the magic lamp and attacks an enemy target, dealing #C0x3D8A99#150% Arcane Attack #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#. Also, through the divine lamp transmission, it grants our side the supreme hero Arcane Attack #C0x3D8A99#100% Arcane Attack #C0x5B545B# #C0xF13B54# Magic Damage #C0x5B545B#. Beyond the set limit, it quickly transmits to single enemy units.',
		simDesc_vn = 'Thây ma đèn thần thực hiện điều ước với cây đèn thần, tấn công một mục tiêu của kẻ thù và gây thêm sát thương cho đơn vị của chúng ta với đòn tấn công cao nhất.',
		simDesc_en = 'The Genie Zombie grants wishes with the magic lamp, attacking an enemy target and dealing additional damage to our unit with the highest attack power.',
		simDesc_th = 'ซอมบี้จินนี่ทำตามคำขอด้วยตะเกียงวิเศษ โจมตีเป้าหมายศัตรูและสร้างความเสียหายเพิ่มเติมให้กับหน่วยของเราที่มีพลังโจมตีสูงสุด',
		simDesc_in = 'Zombie Jin menggunakan lampu ajaib untuk mengabulkan permintaan, menyerang satu target musuh dan memberikan kerusakan tambahan pada unit kita dengan serangan tertinggi.',
		simDesc_ph = 'Ang Genie Zombie ay nagsasagawa ng kahilingan gamit ang magic lamp, sumasalakay sa isang target na kaaway at nagdudulot ng dagdag na pinsala sa aming yunit na may pinakamataas na atake.',
		simDesc_ma = 'Zombie Jin memenuhi permintaan dengan lampu ajaib, menyerang sasaran musuh dan memberikan kerosakan tambahan kepada unit kita dengan serangan tertinggi.',
		simDesc = 'The Genie Zombie grants wishes with the magic lamp, attacking an enemy target and dealing additional damage to our unit with the highest attack power.',
		zawakeEffect = __data_t__zawakeEffect[28432],
		-- {79002}
		zawakeEffectDesc = 'Magic lamp zombie makes a wish with the magic lamp and attacks an enemy target, dealing #C0xF13B54# Magical Damage #C0x3D8A99#150% of magical attack#C0x5B545B#+$(skillLevel*4*48)$#C0x5B545B# and through lamp transmission, the magical attack #C0x3D8A99# 100% #C0x5B545B# and #C0xF13B54# Magical Damage #C0x5B545B# of our hero with the highest Magical Damage will be additionally transferred to this attack\'s target and an additional random enemy unit.',
		zawakeEffectDesc_en = 'Magic lamp zombie makes a wish with the magic lamp and attacks an enemy target, dealing #C0xF13B54# Magical Damage #C0x3D8A99#150% of magical attack#C0x5B545B#+$(skillLevel*4*48)$#C0x5B545B# and through lamp transmission, the magical attack #C0x3D8A99# 100% #C0x5B545B# and #C0xF13B54# Magical Damage #C0x5B545B# of our hero with the highest Magical Damage will be additionally transferred to this attack\'s target and an additional random enemy unit.',
		zawakeEffectDesc_th = 'ซอมบี้ตะเกียงวิเศษทำความปรารถนาด้วยตะเกียงวิเศษและโจมตีเป้าหมายศัตรู ทำให้เกิด #C0xF13B54# ความเสียหายเวท #C0x3D8A99#150% ของการโจมตีเวท#C0x5B545B#+$(skillLevel*4*48)$#C0x5B545B# และผ่านการส่งตะเกียง, การโจมตีเวท #C0x3D8A99# 100% #C0x5B545B# และ #C0xF13B54# ความเสียหายเวท #C0x5B545B# ของฮีโร่ของเราที่มีความเสียหายเวทสูงสุดจะถูกส่งเพิ่มเติมไปยังเป้าหมายของการโจมตีนี้และหน่วยศัตรูสุ่มเพิ่มเติมหนึ่งหน่วย',
		zawakeEffectDesc_in = 'Zombie lampu ajaib membuat sebuah permintaan dengan lampu ajaib dan menyerang target musuh, memberikan #C0xF13B54# Kerusakan Magis #C0x3D8A99#150% dari serangan magis#C0x5B545B#+$(skillLevel*4*48)$#C0x5B545B# dan melalui transmisi lampu, serangan magis #C0x3D8A99# 100% #C0x5B545B# dan #C0xF13B54# Kerusakan Magis #C0x5B545B# dari pahlawan kita dengan Kerusakan Magis tertinggi akan ditransfer tambahan ke target serangan ini dan satu unit musuh acak tambahan',
		zawakeEffectDesc_ph = 'Ang zombie na lampara ng mahika ay gumagawa ng isang kahilingan gamit ang lampara ng mahika at umaatake sa isang target na kaaway, na nagdudulot ng #C0xF13B54# Magical Damage #C0x3D8A99#150% ng magical attack#C0x5B545B#+$(skillLevel*4*48)$#C0x5B545B# at sa pamamagitan ng pagpapadala ng lampara, ang magical attack #C0x3D8A99# 100% #C0x5B545B# at #C0xF13B54# Magical Damage #C0x5B545B# ng aming bayani na may pinakamataas na Magical Damage ay idadagdag na maipapasa sa target ng pag-atake na ito at isang karagdagang random na yunit ng kalaban',
		zawakeEffectDesc_ma = 'Zombi lampu ajaib membuat satu permintaan dengan lampu ajaib dan menyerang sasaran musuh, menyebabkan #C0xF13B54# Kerosakan Sihir #C0x3D8A99#150% serangan sihir#C0x5B545B#+$(skillLevel*4*48)$#C0x5B545B# dan melalui penghantaran lampu, serangan sihir #C0x3D8A99# 100% #C0x5B545B# dan #C0xF13B54# Kerosakan Sihir #C0x5B545B# wira kita dengan Kerosakan Sihir tertinggi akan dipindahkan tambahan kepada sasaran serangan ini dan satu unit musuh rawak tambahan',
		zawakeEffectDesc_vn = 'Zombie đèn ma thuật thực hiện một điều ước với chiếc đèn ma thuật và tấn công một mục tiêu kẻ thù, gây ra #C0xF13B54# Sát Thương Phép Thuật #C0x3D8A99#150% đòn tấn công ma thuật#C0x5B545B#+$(skillLevel*4*48)$#C0x5B545B# và thông qua việc truyền đèn ma thuật, đòn tấn công ma thuật #C0x3D8A99# 100% #C0x5B545B# và #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# của anh hùng của chúng ta với Sát Thương Phép Thuật cao nhất sẽ được truyền thêm đến mục tiêu của đòn tấn công này và một đơn vị kẻ thù ngẫu nhiên bổ sung.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Also spreads to one single enemy target\n#F20# \n#F40##C0x5c9970#→Also spreads to the current target and one random enemy unit',
