	[28433] = {
		id = 28433,
		skillName_vn = 'Ước nguyện ác ý',
		skillName_en = 'Malicious wish',
		skillName_th = 'คำอธิษฐานที่เป็นอันตราย',
		skillName_in = 'Harapan jahat',
		skillName_ph = 'Masamang kahilingan',
		skillName_ma = 'Hasrat jahat',
		skillName = 'Malicious wish',
		describe_vn = 'Zombie đèn thần đã tức giận. Anh ta thực hiện một điều ước độc ác với chiếc đèn ma thuật và tấn công một mục tiêu của kẻ thù, gây ra nó #C0x3D8A99#450% đòn tấn công ma thuật#C0x5B545B#+$(skillLevel*4*75) $ #C0xF13B54#Sát Thương Phép Thuật #C0x5B545B# và tự đưa mình vào không gian ngoài hành tinh, khiến anh hùng tự tấn công lần sau đi vào không gian bị xoắn và sẽ không xuất hiện trở lại cho đến khi có hành động mục tiêu tiếp theo xoay.',
		describe_en = 'The Genie Zombie has become enraged. He makes a wicked wish with the magical lamp and attacks an enemy target, dealing #C0x3D8A99#450% magical attack#C0x5B545B#+$(skillLevel*4*75) $ #C0xF13B54#Magical Damage#C0x5B545B#, and then banishes himself into an alien space, causing the hero\'s next self-attack to enter a twisted space and not reappear until the next target action spins.',
		describe_th = 'ซอมบี้จินนี่โคมไฟโกรธจัด เขาทำคำขอร้ายกาจกับโคมไฟวิเศษและโจมตีเป้าหมายศัตรู ทำความเสียหาย #C0x3D8A99#450% พลังโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*75) $ #C0xF13B54#ความเสียหายเวทย์มนตร์#C0x5B545B# จากนั้นเขาจะส่งตัวเองเข้าไปในอวกาศต่างดาว ทำให้การโจมตีตนเองครั้งต่อไปของฮีโร่เข้าสู่อวกาศบิดเบี้ยวและจะไม่ปรากฏตัวอีกจนกว่าจะมีการกระทำเป้าหมายถัดไปหมุน',
		describe_in = 'Zombie Jin Lampu Marah. Dia membuat permintaan jahat dengan lampu ajaib dan menyerang target musuh, memberikan #C0x3D8A99#450% serangan sihir#C0x5B545B#+$(skillLevel*4*75) $ #C0xF13B54#Kerusakan Sihir#C0x5B545B# dan mengirim dirinya ke ruang alien, menyebabkan serangan berikutnya dari pahlawan masuk ke ruang terpelintir dan tidak akan muncul kembali hingga ada aksi target berikutnya yang berputar.',
		describe_ph = 'Nagalit ang Genie Zombie. Ginawa niya ang isang masamang kahilingan gamit ang mahiwagang lampara at inatake ang isang target ng kaaway, na nagdulot ng #C0x3D8A99#450% na magical attack#C0x5B545B#+$(skillLevel*4*75) $ #C0xF13B54#Sakit na Mahika#C0x5B545B# at inilagay ang sarili sa isang dayuhang espasyo, na naging sanhi ng susunod na self-attack ng bayani na pumasok sa twisted space at hindi lalabas muli hanggang sa susunod na ikot ng target na aksyon.',
		describe_ma = 'Zombie Jin Lampu marah. Dia membuat satu hasrat jahat dengan lampu ajaib dan menyerang sasaran musuh, menyebabkan #C0x3D8A99#450% serangan magik#C0x5B545B#+$(skillLevel*4*75) $ #C0xF13B54#Kerosakan Magik#C0x5B545B# dan membawanya ke ruang angkasa asing, menyebabkan serangan seterusnya oleh wira ke atas dirinya sendiri memasuki ruang berpilin dan tidak akan muncul semula sehingga tindakan sasaran seterusnya berputar.',
		describe = 'The Genie Zombie has become enraged. He makes a wicked wish with the magical lamp and attacks an enemy target, dealing #C0x3D8A99#450% magical attack#C0x5B545B#+$(skillLevel*4*75) $ #C0xF13B54#Magical Damage#C0x5B545B#, and then banishes himself into an alien space, causing the hero\'s next self-attack to enter a twisted space and not reappear until the next target action spins.',
		simDesc_vn = 'Zombie đèn thần đã tức giận. Anh ta thực hiện một điều ước độc ác với cây đèn thần và tấn công một mục tiêu kẻ thù.',
		simDesc_en = 'The genie zombie has become furious. He makes a wicked wish with the magic lamp and attacks an enemy target.',
