		skillName_in = 'Cahaya Aneh',
		skillName_ph = 'Kakaibang Liwanag',
		skillName_ma = 'Cahaya Aneh',
		skillName = 'Strange Light',
		describe_vn = 'Nhẹ nhàng-Nữ bất ngờ xuất hiện phía sau mục tiêu đơn lẻ của kẻ địch, phát ra ánh sáng kỳ lạ từ tay, gây ra #C0x3D8A99#140% Phép Công#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, hút 5% sinh mệnh hiện tại của mục tiêu dựa trên giới hạn sinh mệnh của mục tiêu (không vượt quá 20% giới hạn sinh mệnh của bản thân)',
		describe_en = 'Gentle - The female ninja suddenly appears behind a single enemy target, emitting a strange light from her hand, dealing #C0x3D8A99#140% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magical Damage#C0x5B545B#, draining 5% of the target\'s current health based on the target\'s health limit (not exceeding 20% of the user\'s own health limit).',
		describe_th = 'นุ่มนวล - หญิงสาวปรากฏตัวอย่างกะทันหันข้างหลังเป้าหมายฝ่ายศัตรูเพียงหนึ่งราย ปล่อยแสงประหลาดจากมือ สร้างความเสียหายเวทมนตร์ #C0x3D8A99#140%#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# ดูดเลือด 5% ของพลังชีวิตปัจจุบันของเป้าหมายโดยอิงจากขีดจำกัดพลังชีวิตของเป้าหมาย (ไม่เกิน 20% ของขีดจำกัดพลังชีวิตของผู้ใช้).',
		describe_in = 'Lembut - Wanita tiba-tiba muncul di belakang satu sasaran musuh, memancarkan cahaya aneh dari tangannya, memberikan #C0x3D8A99#140% Serangan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, menyedot 5% kehidupan saat ini dari target berdasarkan batasan kesehatan target (tidak melebihi 20% dari batasan kesehatan pengguna).',
		describe_ph = 'Malamlamig - Biglang lumitaw ang babae sa likod ng isang target na kalaban, nagpapalabas ng kakaibang liwanag mula sa kanyang kamay, nagdudulot ng #C0x3D8A99#140% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Pinsalang Magic #C0x5B545B#, sumisipsip ng 5% ng kasalukuyang buhay ng target batay sa limitasyon ng buhay ng target (hindi lalampas sa 20% ng limitasyon ng sariling buhay ng gumagamit).',
		describe_ma = 'Lembut - Wanita tiba-tiba muncul di belakang satu sasaran musuh, memancarkan cahaya aneh dari tangannya, menyebabkan #C0x3D8A99#140% Serangan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, menyedut 5% nyawa semasa sasaran berdasarkan had nyawa sasaran (tidak melebihi 20% had nyawa pengguna).',
		describe = 'Gentle - The female ninja suddenly appears behind a single enemy target, emitting a strange light from her hand, dealing #C0x3D8A99#140% Magic Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magical Damage#C0x5B545B#, draining 5% of the target\'s current health based on the target\'s health limit (not exceeding 20% of the user\'s own health limit).',
		simDesc_vn = 'Light and Fluffy - Nữ xuất hiện sau lưng mục tiêu đơn lẻ của kẻ thù, tay phát ra ánh sáng kỳ lạ.',
		simDesc_en = 'Light and Fluffy - A female appears behind a single enemy target, her hand emitting a strange light.',
		simDesc_th = 'Light and Fluffy - หญิงสาวปรากฏตัวด้านหลังเป้าหมายศัตรูเพียงหนึ่งคน มือของเธอปล่อยแสงแปลกประหลาดออกมา',
		simDesc_in = 'Light and Fluffy - Seorang wanita muncul di belakang satu target musuh, tangannya memancarkan cahaya aneh.',
		simDesc_ph = 'Light and Fluffy - Isang babae ang lumilitaw sa likod ng isang target na kalaban, ang kanyang kamay ay naglalabas ng kakaibang ilaw.',
		simDesc_ma = 'Light and Fluffy - Seorang wanita muncul di belakang satu sasaran musuh, tangannya memancarkan cahaya pelik.',
		simDesc = 'Light and Fluffy - A female appears behind a single enemy target, her hand emitting a strange light.',
		zawakeEffect = __data_t__zawakeEffect[29212],
		-- {79002}
		zawakeEffectDesc = 'Gently - The female glides behind a single enemy target, emitting a strange light from her hands, dealing #C0x3D8A99#140% Magic Power #C0x5B545B#+$(skillLevel*4*36)$ Magic Damage #C0xF13B54# #C0x5B545B#, draining 10% of the target\'s current health (not exceeding 30% of own maximum health)',
		zawakeEffectDesc_en = 'Gently - The female glides behind a single enemy target, emitting a strange light from her hands, dealing #C0x3D8A99#140% Magic Power #C0x5B545B#+$(skillLevel*4*36)$ Magic Damage #C0xF13B54# #C0x5B545B#, draining 10% of the target\'s current health (not exceeding 30% of own maximum health)',
		zawakeEffectDesc_th = 'เบาๆ - ผู้หญิงลู่เข้าไปข้างหลังเป้าหมายศัตรูเดี่ยว ปล่อยแสงประหลาดจากมือ ก่อให้เกิด #C0x3D8A99#140% พลังเวท #C0x5B545B#+$(skillLevel*4*36)$ ความเสียหายเวทมนตร์ #C0xF13B54# #C0x5B545B#, ดูด 10% ชีวิตปัจจุบันของเป้าหมาย (ไม่เกิน 30% ของชีวิตสูงสุดของตนเอง)',
		zawakeEffectDesc_in = 'Lembut - Perempuan meluncur ke belakang target musuh tunggal, memancarkan cahaya aneh dari tangan, menyebabkan #C0x3D8A99#140% Kekuatan Sihir #C0x5B545B#+$(skillLevel*4*36)$ Kerusakan Sihir #C0xF13B54# #C0x5B545B#, menyedot 10% kesehatan target saat ini (tidak melebihi 30% kesehatan maksimum diri sendiri)',
		zawakeEffectDesc_ph = 'Malamlam - Babae ay dahan-dahang dumulas sa likod ng isang kalabang target, naglalabas ng kakaibang liwanag mula sa mga kamay, nagdudulot ng #C0x3D8A99#140% Lakas ng Mahika #C0x5B545B#+$(skillLevel*4*36)$ Pinsalang Mahika #C0xF13B54# #C0x5B545B#, sumisipsip ng 10% kasalukuyang buhay ng target (hindi lalampas sa 30% ng sariling pinakamataas na buhay)',
		zawakeEffectDesc_ma = 'Lembut - Wanita meluncur ke belakang sasaran musuh tunggal, memancarkan cahaya aneh dari tangan, menyebabkan #C0x3D8A99#140% Kuasa Sihir #C0x5B545B#+$(skillLevel*4*36)$ Kecederaan Sihir #C0xF13B54# #C0x5B545B#, menyedut 10% kesihatan semasa sasaran (tidak melebihi 30% kesihatan maksimum diri sendiri)',
		zawakeEffectDesc_vn = 'Nhẹ nhàng - Nữ lướt đến sau lưng mục tiêu đơn lẻ của kẻ địch, phát ra ánh sáng kỳ lạ từ tay, gây #C0x3D8A99#140% Phép Công #C0x5B545B#+$(skillLevel*4*36)$ Sát Thương Phép Thuật #C0xF13B54# #C0x5B545B#, hút 10% sinh mệnh hiện tại của mục tiêu (không vượt quá 30% sinh mệnh tối đa của bản thân)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Drains 5% of the target’s current HP based on Max HP (no more than 20% of own Max HP)\n#F20# \n#F40##C0x5c9970#→Drains 10% of the target’s current HP based on Max HP (up to 30% of own Max HP)',
		zawakeSimpleDesc_en = 'Drains 5% of the target’s current HP based on Max HP (no more than 20% of own Max HP)\n#F20# \n#F40##C0x5c9970#→Drains 10% of the target’s current HP based on Max HP (up to 30% of own Max HP)',
		zawakeSimpleDesc_th = 'ดูด 5% HP ปัจจุบันของเป้าหมายตาม HP สูงสุด (ไม่เกิน 20% ของ HP สูงสุดตัวเอง)\n#F20# \n#F40##C0x5c9970#→ดูด 10% HP (ไม่เกิน 30%)',
		zawakeSimpleDesc_in = 'Menyedot 5% HP target saat ini berdasarkan Max HP (maks. 20% Max HP sendiri)\n#F20# \n#F40##C0x5c9970#→Menyedot 10% (maks. 30%)',
		zawakeSimpleDesc_ph = 'Sumisipsip ng 5% ng kasalukuyang HP ng target base sa Max HP (hindi hơn 20%)\n#F20# \n#F40##C0x5c9970#→Sumisipsip ng 10% (tối đa 30%)',
		zawakeSimpleDesc_ma = 'Menyedut 5% HP semasa sasaran berdasarkan HP Maks (tidak lebih 20% HP sendiri)\n#F20# \n#F40##C0x5c9970#→10% (maks 30%)',
		zawakeSimpleDesc_vn = 'Hút 5% sinh mệnh hiện tại của mục tiêu dựa trên giới hạn sinh mệnh (không vượt quá 20% giới hạn sinh mệnh của bản thân)\n#F20# \n#F40##C0x5c9970#→Hút 10% sinh mệnh hiện tại của mục tiêu dựa trên giới hạn sinh mệnh (không vượt quá 30% giới hạn sinh mệnh của bản thân)',
