	[29913] = {
		id = 29913,
		skillName_vn = 'Hận thù tro tàn',
		skillName_en = 'Hatred ashes',
		skillName_th = 'ความเกลียดชังที่เป็นเถ้าถ่าน',
		skillName_in = 'Dendam menjadi abu',
		skillName_ph = 'Paghatol sa abo',
		skillName_ma = 'Benci menjadi abu',
		skillName = 'Hatred ashes',
		describe_vn = 'Linh Hồn Nến triệu hồi nhiều ngọn lửa ma quái xung quanh cơ thể, sau đó ném tất cả vào kẻ địch, gây ra #C0x3D8A99#220% Công Phép thuật#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# lên mục tiêu hàng ngang của kẻ địch, mục tiêu bị sát thương lần này sẽ không tạo ra nộ khí do bị thương, kèm theo [Ngọn Lửa Ma Quái] (Ngọn Lửa Ma Quái: Hiệu ứng tiêu cực, giảm ngay 150 điểm nộ khí, và giảm cùng lượng nộ khí trước hành động tiếp theo của mục tiêu)',
		describe_en = 'Candle Soul summons multiple ghostly flames around the body, then hurls them all at the enemy, causing #C0x3D8A99#220% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magical Damage #C0x5B545B# to enemies in a horizontal line. Targets damaged this time will not generate rage from injuries, accompanied by [Ghostly Flame] (Ghostly Flame: Negative effect, immediately reduces 150 rage points, and reduces the same amount of rage before the target\'s next action).',
		describe_th = 'วิญญาณเทียนเรียกเปลวไฟวิญญาณจำนวนมากรอบร่าง จากนั้นพุ่งทั้งหมดไปที่ศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#220% พลังเวทมนตร์#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# ต่อเป้าหมายในแถวแนวนอนของศัตรู เป้าหมายที่ได้รับความเสียหายในครั้งนี้จะไม่สร้างความโกรธจากการบาดเจ็บ พร้อมด้วย [เปลวไฟวิญญาณ] (เปลวไฟวิญญาณ: ผลเสีย ลดความโกรธทันที 150 แต้ม และลดความโกรธจำนวนเท่าเดิมก่อนการกระทำถัดไปของเป้าหมาย)',
		describe_in = 'Jiwa Lilin memanggil banyak api hantu di sekitar tubuh, lalu melemparkan semuanya ke musuh, menyebabkan #C0x3D8A99#220% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B# pada target barisan horizontal musuh. Target yang menerima kerusakan kali ini tidak akan menghasilkan kemarahan karena luka, disertai [Api Hantu] (Api Hantu: efek negatif, segera mengurangi 150 poin kemarahan, dan mengurangi kemarahan dalam jumlah yang sama sebelum tindakan berikutnya dari target).',
		describe_ph = 'Angkal ng Kandila ay nagpapatawag ng maraming espiritung apoy sa paligid ng katawan, pagkatapos ay ihahagis ang lahat sa kalaban, nagdudulot ng #C0x3D8A99#220% Kapangyarihang Mahika#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pinsalang Mahika #C0x5B545B# sa mga target sa pahalang na hanay ng kalaban. Ang mga target na nasaktan sa pagkakataong ito ay hindi gagawa ng galit mula sa pinsala, kasabay ng [Espiritung Apoy] (Espiritung Apoy: negatibong epekto, agad na nagpapababa ng 150 puntos ng galit, at nagpapababa ng parehong dami ng galit bago ang susunod na kilos ng target).',
		describe_ma = 'Jiwa Lilin mengeluarkan banyak api hantu di sekeliling badan, kemudian melemparkan semuanya ke musuh, menyebabkan #C0x3D8A99#220% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B# ke sasaran barisan mendatar musuh. Sasaran yang mengalami kerosakan kali ini tidak akan menghasilkan kemarahan akibat kecederaan, disertakan dengan [Api Hantu] (Api Hantu: kesan negatif, segera mengurangkan 150 mata kemarahan, dan mengurangkan jumlah kemarahan yang sama sebelum tindakan seterusnya sasaran).',
		describe = 'Candle Soul summons multiple ghostly flames around the body, then hurls them all at the enemy, causing #C0x3D8A99#220% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magical Damage #C0x5B545B# to enemies in a horizontal line. Targets damaged this time will not generate rage from injuries, accompanied by [Ghostly Flame] (Ghostly Flame: Negative effect, immediately reduces 150 rage points, and reduces the same amount of rage before the target\'s next action).',
		simDesc_vn = 'Candle Spirit triệu hồi rất nhiều ánh lửa ma quái xung quanh cơ thể, sau đó ném tất cả ánh lửa vào kẻ thù. Mục tiêu bị tấn công lần này sẽ không tạo ra năng lượng do bị thương, và kèm theo [Ánh lửa ma].',
		simDesc_en = 'The Candle Spirit summons numerous eerie flames around its body, then throws all the flames at the enemy. The attacked target will not generate energy due to injury, accompanied by <Ghostly Flames>.',
		simDesc_th = 'วิญญาณเทียนเรียกเปลวไฟลึกลับจำนวนมากรอบร่างกาย จากนั้นขว้างเปลวไฟทั้งหมดไปยังศัตรู เป้าหมายที่ถูกโจมตีจะไม่สร้างพลังงานเนื่องจากได้รับบาดเจ็บ พร้อมด้วย [เปลวไฟลึกลับ].',
		simDesc_in = 'Roh Lilin memanggil banyak api menyeramkan di sekeliling tubuhnya, kemudian melemparkan semua api tersebut ke musuh. Target yang diserang kali ini tidak akan menghasilkan energi karena terluka, disertai dengan <Api Hantu>.',
		simDesc_ph = 'Ang Espiritu ng Kandila ay nagtatipon ng maraming mahiwagang apoy sa paligid ng katawan, pagkatapos ay inihahagis ang lahat ng apoy sa kaaway. Ang target na inatake ay hindi gagawa ng enerhiya dahil sa sugat, kasabay ng <Mahiwagang Apoy>.',
		simDesc_ma = 'Roh Lilin memanggil banyak cahaya api aneh di sekitar tubuhnya, kemudian melemparkan semua cahaya api itu kepada musuh. Sasaran yang diserang kali ini tidak akan menghasilkan tenaga akibat kecederaan, disertai dengan <Cahaya Api Hantu>.',
		simDesc = 'The Candle Spirit summons numerous eerie flames around its body, then throws all the flames at the enemy. The attacked target will not generate energy due to injury, accompanied by [Ghostly Flames].',
		starEffect = __data_t__starEffect[29913],
		-- {11}
		starEffectDesc_vn = 'Khi sử dụng kỹ năng đặc biệt, nếu tấn công vào mục tiêu bị Quỷ Hỏa, tỷ lệ chí mạng tăng 20%.',
		starEffectDesc = 'When using a special skill, if attacking a target afflicted by Demon Fire, the critical hit rate increases by 20%.',
		starEffectDesc_en = 'When using a special skill, if attacking a target afflicted by Demon Fire, the critical hit rate increases by 20%.',
		starEffectDesc_th = 'เมื่อใช้ทักษะพิเศษ หากโจมตีเป้าหมายที่ถูกวิญญาณเพลิงปีศาจโจมตี อัตราคริติคอลจะเพิ่มขึ้น 20%',
		starEffectDesc_in = 'Saat menggunakan keterampilan khusus, jika menyerang target yang terkena Api Setan, tingkat serangan kritis meningkat sebesar 20%.',
		starEffectDesc_ph = 'Kapag gumagamit ng espesyal na kasanayan, kung umatake sa target na apektado ng Apoy ng Demonyo, tumataas ang porsyento ng critical hit ng 20%.',
		starEffectDesc_ma = 'Apabila menggunakan kemahiran istimewa, jika menyerang sasaran yang terkena Api Syaitan, kadar serangan kritikal meningkat sebanyak 20%.',
