	[29916] = {
		id = 29916,
		skillName_vn = 'Đâm tay',
		skillName_en = 'Stab hand',
		skillName_th = 'แทงมือ',
		skillName_in = 'Tusuk tangan',
		skillName_ph = 'Saksak kamay',
		skillName_ma = 'Tusuk tangan',
		skillName = 'Stab hand',
		describe_vn = 'Khi bản thân chết lần đầu, sẽ để lại một ngọn lửa ma quái tại chỗ, trước hành động tiếp theo sẽ hồi sinh dưới dạng linh hồn với #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# máu (trạng thái linh hồn không bị ảnh hưởng bởi Sát Thương Vật Lý), tồn tại cho đến khi kết thúc vòng lớn',
		describe_en = 'When the user dies for the first time, they will leave behind a ghostly flame at the spot. Before the next action, they will revive in spirit form with #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (the spirit state is not affected by Physical Damage), and will persist until the end of the major round.',
		describe_th = 'เมื่อผู้ใช้ตายครั้งแรก จะทิ้งเปลวไฟลึกลับไว้ที่จุดนั้น ก่อนการกระทำครั้งถัดไปจะเกิดการฟื้นคืนในรูปแบบวิญญาณโดยมี #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# พลังชีวิต (สถานะวิญญาณจะไม่ถูกผลกระทบจากความเสียหายทางกายภาพ) จะคงอยู่จนกว่าจะสิ้นสุดรอบใหญ่',
		describe_in = 'Ketika pengguna mati untuk pertama kalinya, akan meninggalkan api gaib di tempat tersebut. Sebelum tindakan berikutnya, akan bangkit kembali dalam bentuk roh dengan #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (keadaan roh tidak terpengaruh oleh Kerusakan Fisik), dan akan bertahan hingga akhir putaran besar.',
		describe_ph = 'Kapag unang namatay ang sarili, mag-iiwan ito ng isang mahiwagang apoy sa lugar, bago ang susunod na aksyon ay muling mabubuhay bilang espiritu na may #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (ang estado ng espiritu ay hindi naaapektuhan ng Physical Damage), at mananatili hanggang sa katapusan ng malaking round.',
		describe_ma = 'Apabila pengguna mati buat kali pertama, akan meninggalkan api ghaib di tempat tersebut. Sebelum tindakan seterusnya, akan bangkit semula dalam bentuk roh dengan #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (keadaan roh tidak terjejas oleh Kerosakan Fizikal), dan akan wujud sehingga tamat pusingan besar.',
		describe = 'When the user dies for the first time, they will leave behind a ghostly flame at the spot. Before the next action, they will revive in spirit form with #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (the spirit state is not affected by Physical Damage), and will persist until the end of the major round.',
		starEffect = __data_t__starEffect[29916],
		-- {8}
		starEffectDesc_vn = 'Khi hồi sinh ở trạng thái Oán Linh, tức thì đầy tức giận và tăng 30% phép công và 30% tỷ lệ chí mạng.',
		starEffectDesc = 'When resurrected in the Vengeful Spirit state, instantly fills with rage and increases magic attack by 30% and critical rate by 30%.',
		starEffectDesc_en = 'When resurrected in the Vengeful Spirit state, instantly fills with rage and increases magic attack by 30% and critical rate by 30%.',
		starEffectDesc_th = 'เมื่อฟื้นชีพในสถานะวิญญาณแค้น จะมีความโกรธจัดทันทีและเพิ่มพลังเวท 30% และอัตราคริติคอล 30%',
		starEffectDesc_in = 'Saat bangkit kembali dalam keadaan Roh Pendendam, langsung dipenuhi kemarahan dan meningkatkan kekuatan sihir sebesar 30% serta tingkat kritis sebesar 30%.',
