	[29923] = {
		id = 29923,
		skillName_vn = 'Tấn công bất ngờ',
		skillName_en = 'Surprise attack',
		skillName_th = 'โจมตีแบบกะทันหัน',
		skillName_in = 'Serangan mendadak',
		skillName_ph = 'Biglaang atake',
		skillName_ma = 'Serangan mengejutkan',
		skillName = 'Surprise attack',
		describe_vn = 'Linh Hồn Đèn Diệu triệu hồi ngọn lửa ma quái khổng lồ, sau đó ném vào mục tiêu hàng ngang của kẻ địch, gây ra #C0x3D8A99#230% Công Phép thuật#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, mục tiêu bị sát thương lần này sẽ không tạo ra nộ khí do bị thương, kèm theo [Ngọn Lửa Ma Quái] (Ngọn Lửa Ma Quái: Hiệu ứng tiêu cực, giảm ngay 150 điểm nộ khí, và giảm cùng lượng nộ khí trước hành động tiếp theo của mục tiêu)',
		describe_en = 'Soul Lantern summons a colossal demonic flame and hurls it at the enemy’s horizontal target line, dealing #C0x3D8A99#230% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#. Targets hit by this attack will not generate chakra from injury, and are affected by [Demonic Flame] (Demonic Flame: a debuff that instantly reduces 150 chakra points and further reduces the target\'s chakra by the same amount before their next action).',
		describe_th = 'วิญญาณโคมหวนเรียกเปลวไฟปีศาจขนาดยักษ์ จากนั้นขว้างไปยังเป้าหมายในแนวราบของศัตรู ทำให้เกิด #C0x3D8A99#230% พลังเวทมนตร์#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# เป้าหมายที่ได้รับความเสียหายครั้งนี้จะไม่สร้างโหมดชักช้าเนื่องจากบาดเจ็บ พร้อมด้วย [เปลวไฟปีศาจ] (เปลวไฟปีศาจ: เอฟเฟกต์ลดทอน ดร็อปโหมดชักช้า 150 หน่วยทันที และลดโหมดชักช้าด้วยจำนวนเท่ากันก่อนการกระทำถัดไปของเป้าหมาย)',
		describe_in = 'Roh Lentera memanggil api iblis raksasa, lalu melemparkannya ke barisan target horizontal musuh, menyebabkan #C0x3D8A99#230% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Target yang terkena serangan ini tidak akan menghasilkan chakra saat terluka, disertai [Api Iblis] (Api Iblis: efek negatif yang langsung mengurangi 150 poin chakra, dan mengurangi chakra sebanyak itu sebelum aksi berikutnya dari target).',
		describe_ph = 'Ang Kaluluwa ng Parola ay tumatawag ng dambuhalang demonyong apoy, at itinatapon ito sa pahalang na hanay ng mga target ng kalaban, na nagdudulot ng #C0x3D8A99#230% Kapangyarihan ng Mahika#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pinsalang Mahika #C0x5B545B#. Ang mga target na tamaan sa beses na ito ay hindi gagawa ng chakra mula sa pinsala, kalakip ang [Demonyong Apoy] (Demonyong Apoy: negatibong epekto, agad na nagbabawas ng 150 puntos ng chakra, at nagbabawas din ng parehong dami ng chakra bago ang susunod na aksyon ng target).',
		describe_ma = 'Jiwa Lampu memanggil api iblis gergasi, kemudian membalingkannya ke barisan sasaran musuh secara mendatar, menyebabkan #C0x3D8A99#230% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Sasaran yang terkena serangan ini tidak akan menghasilkan nadi jutsu akibat kecederaan, disertai [Api Iblis] (Api Iblis: kesan negatif yang mengurangkan segera 150 titik nadi jutsu, dan mengurangkan nadi jutsu dalam jumlah yang sama sebelum tindakan seterusnya sasaran).',
		describe = 'Soul Lantern summons a colossal demonic flame and hurls it at the enemy’s horizontal target line, dealing #C0x3D8A99#230% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#. Targets hit by this attack will not generate chakra from injury, and are affected by [Demonic Flame] (Demonic Flame: a debuff that instantly reduces 150 chakra points and further reduces the target\'s chakra by the same amount before their next action).',
		simDesc_vn = 'Lamp Ghost triệu hồi một quả cầu năng lượng ma quái khổng lồ, rồi ném vào mục tiêu theo hàng. Mục tiêu bị tấn công lần này sẽ không tạo ra năng lượng do bị thương, và kèm theo [Ánh lửa ma].',
		simDesc_en = 'Lamp Ghost summons a giant spectral energy orb and throws it in a row towards the target. The attacked target will not generate energy due to injury, accompanied by <Phantom Flame>.',
		simDesc_th = 'โคมไฟภูตเรียกบอลพลังงานวิญญาณขนาดมหึมา แล้วขว้างใส่เป้าหมายเรียงตามแถว เป้าหมายที่ถูกโจมตีครั้งนี้จะไม่สร้างพลังงานเนื่องจากบาดเจ็บ พร้อมกับ [เปลวไฟวิญญาณ].',
		simDesc_in = 'Lamp Ghost memanggil bola energi spektral raksasa, lalu melemparkannya secara berbaris ke target. Target yang diserang kali ini tidak akan menghasilkan energi akibat terluka, disertai dengan <Api Hantu>.',
		simDesc_ph = 'Inaanyayahan ng Lamp Ghost ang isang higanteng mahiwagang bola ng enerhiya at itinatapon ito nang sunod-sunod sa target. Ang target na inatake ay hindi makakalikha ng enerhiya dahil sa sugat, kasabay ng <Apoy ng Multo>.',
		simDesc_ma = 'Lamp Ghost memanggil bola tenaga ghaib gergasi dan melemparkannya selari ke sasaran. Sasaran yang diserang kali ini tidak akan menghasilkan tenaga kerana cedera, dan disertai dengan <Api Hantu>.',
		simDesc = 'Lamp Ghost summons a giant spectral energy orb and throws it in a row towards the target. The attacked target will not generate energy due to injury, accompanied by [Phantom Flame].',
		starEffect = __data_t__starEffect[29923],
		-- {11}
		starEffectDesc_vn = 'Khi sử dụng kỹ năng đặc biệt, nếu tấn công vào mục tiêu bị Quỷ Hỏa, tỷ lệ chí mạng tăng 20%.',
		starEffectDesc = 'When using a special skill, if attacking a target affected by #mã màu#Demon Flame#L x#, critical hit rate increases by 20%.',
		starEffectDesc_en = 'When using a special skill, if attacking a target affected by #mã màu#Demon Flame#L x#, critical hit rate increases by 20%.',
		starEffectDesc_th = 'เมื่อใช้ทักษะพิเศษ หากโจมตีเป้าหมายที่ถูก #mã màu#เปลวไฟปีศาจ#L x# โอกาสวิกฤตเพิ่มขึ้น 20%',
		starEffectDesc_in = 'Saat menggunakan skill khusus, jika menyerang target yang terkena #mã màu#Api Setan#L x#, peluang kritikal meningkat 20%.',
		starEffectDesc_ph = 'Kapag gumagamit ng espesyal na kakayahan, kung umatake sa target na apektado ng #mã màu#Apoy ng Demonyo#L x#, tumaas ang porsyento ng kritikal ng 20%.',
		starEffectDesc_ma = 'Apabila menggunakan kemahiran khas, jika menyerang sasaran yang terjejas oleh #mã màu#Api Syaitan#L x#, kadar kritikal meningkat 20%.',
