	[29933] = {
		id = 29933,
		skillName_vn = 'Trận Pháp Hỏa Linh',
		skillName_en = 'Battle of Fire Spirit',
		skillName_th = 'ศึกจิตวิญญาณเพลิง',
		skillName_in = 'Pertempuran Roh Api',
		skillName_ph = 'Laban ng Espiritu ng Apoy',
		skillName_ma = 'Pertempuran Roh Api',
		skillName = 'Battle of Fire Spirit',
		describe_vn = 'Linh hồn lửa đèn lồng pha lê lóe lên trước hàng mục tiêu của kẻ thù, sau đó triệu tập một đội hình tinh linh lửa không gian khổng lồ xung quanh nó, sau đó nhảy lên không trung và bất ngờ lao tới trước mặt kẻ thù, gây ra Sát Thương Phép Thuật #C0x3D8A99#240% vào hàng mục tiêu của kẻ thù#C0x5B545B#+$(skillL evel*4*48)$\'s #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, mục tiêu của sát thương này sẽ không tức giận do bị thương và sẽ kèm theo [Will-o\'-the-wisp] (Will-o\'-the-wisp: hiệu ứng tiêu cực, giảm ngay 150 điểm tức giận và giảm lượng tức giận của mục tiêu tương đương trước khi thực hiện hành động tiếp theo)',
		describe_en = 'The crystal lantern fire spirit flashes before the enemy\'s target line, then summons a massive spatial fire elemental formation around it, before leaping into the air and suddenly dashing in front of the enemy, dealing #C0x3D8A99#240% Magical Damage #C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Magical Damage #C0x5B545B# to the enemy\'s target line. Targets hit by this damage will not become enraged and will be afflicted with [Will-o\'-the-wisp] (Will-o\'-the-wisp: a negative effect that instantly reduces anger by 150 points and decreases the target\'s anger accumulation by the same amount before their next action).',
		describe_th = 'วิญญาณไฟโคมคริสตัลวาบขึ้นต่อหน้ากองเป้าหมายของศัตรู จากนั้นเรียกกองกำลังธาตุไฟมิติเชิงพื้นที่ขนาดใหญ่รอบตัว ก่อนจะกระโดดขึ้นฟ้าแล้วพุ่งเข้าหาด้านหน้าศัตรูอย่างกะทันหัน ก่อให้เกิด #C0x3D8A99#ความเสียหายเวทมนตร์ 240% #C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# ต่อกองเป้าหมายของศัตรู เป้าหมายที่ได้รับความเสียหายนี้จะไม่โกรธและจะติด [Will-o\'-the-wisp] (Will-o\'-the-wisp: สถานะลบ ลดความโกรธทันที 150 แต้มและลดการสะสมความโกรธของเป้าหมายในจำนวนเท่ากันก่อนการกระทำถัดไป)',
		describe_in = 'Roh api lentera kristal menyala di depan barisan target musuh, kemudian memanggil formasi elemen api ruang yang sangat besar di sekitarnya, lalu melompat ke udara dan tiba-tiba menerjang di depan musuh, menyebabkan #C0x3D8A99#240% Kerusakan Sihir #C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Kerusakan Sihir #C0x5B545B# pada barisan target musuh. Target yang terkena kerusakan ini tidak akan menjadi marah dan akan terkena efek [Will-o\'-the-wisp] (Will-o\'-the-wisp: efek negatif yang langsung mengurangi kemarahan sebesar 150 poin dan mengurangi akumulasi kemarahan target dengan jumlah yang sama sebelum tindakan berikutnya).',
		describe_ph = 'Nagliyab ang espiritu ng kristal na parol ng apoy sa harap ng hanay ng mga target ng kalaban, pagkatapos ay tinawag ang isang malaking porma ng espasyong apoy na elemental sa paligid nito, saka tumalon sa hangin at biglang bumilis sa harap ng kalaban, na nagdudulot ng #C0x3D8A99#240% Magical Damage #C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Magical Damage #C0x5B545B# sa hanay ng mga target ng kalaban. Ang mga target na tinamaan ng pinsalang ito ay hindi magagalit at sasalamin ng [Will-o\'-the-wisp] (Will-o\'-the-wisp: negatibong epekto na agad nagpapababa ng galit ng 150 puntos at nagpapabawas ng pag-imbak ng galit ng target ng katulad na halaga bago ang susunod na aksyon).',
		describe_ma = 'Roh api pelita kristal menyala di hadapan barisan sasaran musuh, kemudian memanggil formasi elemen api ruang yang besar di sekelilingnya, lalu melompat ke udara dan tiba-tiba meluru ke hadapan musuh, menyebabkan #C0x3D8A99#240% Kerosakan Sihir #C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Kerosakan Sihir #C0x5B545B# ke barisan sasaran musuh. Sasaran yang terjejas oleh kerosakan ini tidak akan menjadi marah dan akan disertakan dengan [Will-o\'-the-wisp] (Will-o\'-the-wisp: kesan negatif yang segera mengurangkan kemarahan sebanyak 150 mata dan mengurangkan penambahan kemarahan sasaran sebanyak jumlah yang sama sebelum tindakan seterusnya).',
		describe = 'The crystal lantern fire spirit flashes before the enemy\'s target line, then summons a massive spatial fire elemental formation around it, before leaping into the air and suddenly dashing in front of the enemy, dealing #C0x3D8A99#240% Magical Damage #C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Magical Damage #C0x5B545B# to the enemy\'s target line. Targets hit by this damage will not become enraged and will be afflicted with [Will-o\'-the-wisp] (Will-o\'-the-wisp: a negative effect that instantly reduces anger by 150 points and decreases the target\'s anger accumulation by the same amount before their next action).',
		simDesc_vn = 'Hỏa linh đèn lồng pha lê lóe lên trước mục tiêu dàn trận của kẻ thù, sau đó triệu tập một trận hỏa linh không gian khổng lồ xung quanh nó, sau đó lao lên không trung và bất ngờ lao tới trước mặt kẻ thù. Mục tiêu lần này sẽ không tức giận vì vết thương và sẽ kèm theo [will-o\'-the-wisp]',
		simDesc_en = 'The crystal lantern spirit flared up before the enemy\'s formation target, then summoned a massive spatial fire spirit around it, before rushing into the air and suddenly dashing in front of the enemy. This time, the target will not get angry because of the wound and will be accompanied by <will-o\'-the-wisp>.',
		simDesc_th = 'วิญญาณโคมไฟคริสตัลเรืองแสงขึ้นต่อหน้าจุดมุ่งหมายในสมรภูมิของศัตรู จากนั้นเรียกวิญญาณไฟอวกาศขนาดมหึมารอบตัว ก่อนพุ่งขึ้นสู่อากาศแล้วพุ่งตรงไปข้างหน้าศัตรู เป้าหมายในครั้งนี้จะไม่โกรธเพราะบาดแผล และจะมาพร้อมกับ [will-o\'-the-wisp].',
		simDesc_in = 'Roh lentera kristal menyala di depan target formasi musuh, lalu memanggil roh api besar ruang di sekitarnya, kemudian melesat ke udara dan tiba-tiba menyerang tepat di depan musuh. Kali ini target tidak akan marah karena luka dan akan disertai dengan <will-o\'-the-wisp>.',
		simDesc_ph = 'Ang espiritu ng kristal na parol ay kumislap sa harap ng target ng pormasyon ng kaaway, pagkatapos ay tinawag ang isang napakalaking espasyo ng apoy na espiritu sa paligid nito, saka sumulpot sa himpapawid at biglaang sumugod sa harap ng kaaway. Sa pagkakataong ito, ang target ay hindi magagalit dahil sa sugat at sasamahan ng <will-o\'-the-wisp>.',
		simDesc_ma = 'Roh tanglung kristal menyala di hadapan sasaran formasi musuh, kemudian memanggil roh api ruang yang besar mengelilinginya, sebelum meluru ke udara dan secara tiba-tiba menyerang di hadapan musuh. Sasaran kali ini tidak akan marah kerana luka dan akan disertai dengan <will-o\'-the-wisp>.',
		simDesc = 'The crystal lantern spirit flared up before the enemy\'s formation target, then summoned a massive spatial fire spirit around it, before rushing into the air and suddenly dashing in front of the enemy. This time, the target will not get angry because of the wound and will be accompanied by [will-o\'-the-wisp].',
		starEffect = __data_t__starEffect[29933],
		-- {11}
		starEffectDesc_vn = 'Khi sử dụng kỹ năng đặc biệt, nếu tấn công vào mục tiêu bị Quỷ Hỏa, tỷ lệ chí mạng tăng 20%.',
		starEffectDesc = 'When using a special skill, if attacking a target affected by Demon Fire, the critical hit rate increases by 20%.',
		starEffectDesc_en = 'When using a special skill, if attacking a target affected by Demon Fire, the critical hit rate increases by 20%.',
		starEffectDesc_th = 'เมื่อใช้ทักษะพิเศษ หากโจมตีเป้าหมายที่ถูกไฟปีศาจ โอกาสคริติคอลจะเพิ่มขึ้น 20%',
		starEffectDesc_in = 'Saat menggunakan skill khusus, jika menyerang target yang terkena Api Iblis, peluang serangan kritis meningkat 20%.',
		starEffectDesc_ph = 'Kapag gumagamit ng espesyal na kasanayan, kung umatake sa target na apektado ng Demon Fire, tataas ang kritikal na tsansa ng 20%.',
