	[29936] = {
		id = 29936,
		skillName_vn = 'Đâm tay',
		skillName_en = 'Stab finger',
		skillName_th = 'แทงนิ้ว',
		skillName_in = 'Tusuk jari',
		skillName_ph = 'Tusok daliri',
		skillName_ma = 'Tusuk jari',
		skillName = 'Stab finger',
		describe_vn = 'Khi bản thân chết lần đầu, sẽ để lại một ngọn lửa ma quái tại chỗ, trước hành động tiếp theo sẽ hồi sinh dưới dạng linh hồn với #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# máu (trạng thái linh hồn không bị ảnh hưởng bởi Sát Thương Vật Lý), tồn tại cho đến khi kết thúc vòng lớn',
		describe_en = 'When you die for the first time, you will leave behind an eerie flame at the spot. Before the next action, you will be revived in spirit form with #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (spirit form is not affected by Physical Damage), lasting until the end of the major round.',
		describe_th = 'เมื่อคุณตายครั้งแรก จะทิ้งเปลวไฟลึกลับไว้ ณ จุดนั้น ก่อนการกระทำถัดไปจะฟื้นคืนชีพในรูปแบบจิตวิญญาณโดยมี #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# พลังชีวิต (สถานะจิตวิญญาณไม่ถูกผลกระทบจากความเสียหายทางกายภาพ) คงอยู่จนกว่าจะสิ้นสุดรอบใหญ่',
		describe_in = 'Ketika kamu mati untuk pertama kalinya, akan meninggalkan api mistis di tempat tersebut. Sebelum tindakan berikutnya, kamu akan bangkit kembali dalam bentuk roh dengan #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (bentuk roh tidak terpengaruh oleh Kerusakan Fisik), bertahan hingga akhir ronde besar.',
		describe_ph = 'Kapag namatay ka sa unang pagkakataon, mag-iiwan ka ng isang mahiwagang apoy sa lugar. Bago ang susunod na kilos, magbabalik-buhay ka bilang espiritu na may #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (ang kalagayan ng espiritu ay hindi naaapektuhan ng Pisikal na Pinsala), magtatagal hanggang matapos ang malaking round.',
		describe_ma = 'Apabila anda mati buat kali pertama, akan meninggalkan api ghaib di tempat itu. Sebelum tindakan seterusnya, anda akan dihidupkan semula dalam bentuk roh dengan #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# darah (keadaan roh tidak terjejas oleh Kerosakan Fizikal), kekal sehingga tamat pusingan besar.',
		describe = 'When you die for the first time, you will leave behind an eerie flame at the spot. Before the next action, you will be revived in spirit form with #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (spirit form is not affected by Physical Damage), lasting until the end of the major round.',
		starEffect = __data_t__starEffect[29936],
		-- {8}
		starEffectDesc_vn = 'Khi hồi sinh ở trạng thái Oán Linh, tức thì đầy tức giận và tăng 30% phép công và 30% tỷ lệ chí mạng (không thể bị giải trừ).',
		starEffectDesc = 'When resurrected in the Vengeful Spirit state, instantly fill with rage and increase magic attack by 30% and critical rate by 30% (cannot be dispelled).',
		starEffectDesc_en = 'When resurrected in the Vengeful Spirit state, instantly fill with rage and increase magic attack by 30% and critical rate by 30% (cannot be dispelled).',
		starEffectDesc_th = 'เมื่อฟื้นคืนชีพในสถานะวิญญาณแค้น จะเต็มไปด้วยความโกรธทันทีและเพิ่มพลังเวทมนตร์ 30% และอัตราคริติคอล 30% (ไม่สามารถถูกลบล้างได้)',
		starEffectDesc_in = 'Saat bangkit kembali dalam keadaan Roh Pendendam, langsung penuh kemarahan dan meningkatkan serangan sihir sebesar 30% serta tingkat kritis sebesar 30% (tidak dapat dihapus).',
		starEffectDesc_ph = 'Kapag nabuhay muli sa estado ng Mga Galit na Espiritu, agarang mapuno ng galit at tumaas ng 30% ang magic attack at 30% ang critical rate (hindi maaaring maalis).',
		starEffectDesc_ma = 'Apabila bangkit semula dalam keadaan Roh Pendendam, segera dipenuhi dengan kemarahan dan meningkatkan serangan sihir sebanyak 30% serta kadar kritikal sebanyak 30% (tidak boleh dibersihkan).',
