	[30023] = {
		id = 30023,
		skillName_vn = 'Đâm súng thần',
		skillName_en = 'Divine Gunshot',
		skillName_th = 'ยิงปืนเทพ',
		skillName_in = 'Tembakan Ilahi',
		skillName_ph = 'Bakas ng Diyos',
		skillName_ma = 'Tembakan Ilahi',
		skillName = 'Divine Gunshot',
		describe_vn = 'Rồng Răng Rìu tích tụ sức mạnh rồi bay về phía mục tiêu đơn lẻ của kẻ địch, phát ra sóng xung kích để tấn công, gây ra #C0xE69900#470% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, giảm vĩnh viễn 10% phòng thủ vật lý của mục tiêu, nếu tiêu diệt mục tiêu, sẽ tăng vĩnh viễn 20% Công Vật Lý của bản thân (tối đa 4 lần, không thể xóa bỏ)',
		describe_en = 'Dragon Axe Fang gathers power and flies towards a single enemy target, emitting shockwaves to attack, dealing #C0xE69900#470% Physical Attack#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, permanently reducing the target\'s physical defense by 10%. If the target is defeated, permanently increase own Physical Attack by 20% (up to 4 times, cannot be removed).',
		describe_th = 'กรงเล็บขวานมังกรสะสมพลังแล้วพุ่งไปยังเป้าหมายศัตรูเพียงหนึ่งเดียว ปล่อยคลื่นกระแทกโจมตี, สร้างความเสียหายทางกายภาพ #C0xE69900#470%#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ลดการป้องกันทางกายภาพของเป้าหมายถาวร 10% หากฆ่าเป้าหมายได้ จะเพิ่มพลังโจมตีทางกายภาพของตนเองถาวร 20% (สูงสุด 4 ครั้ง, ไม่สามารถลบได้)',
		describe_in = 'Taring Kapak Naga mengumpulkan kekuatan lalu terbang menuju satu target musuh, mengeluarkan gelombang kejut untuk menyerang, memberikan #C0xE69900#470% Serangan Fisik#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, secara permanen mengurangi pertahanan fisik target sebesar 10%. Jika target dikalahkan, meningkatkan Serangan Fisik sendiri secara permanen sebesar 20% (maksimal 4 kali, tidak bisa dihapus).',
		describe_ph = 'Ang Tang ng Tabak ng Dragon ay nag-iipon ng lakas at lumilipad patungo sa isang nag-iisang target ng kaaway, nagbubuga ng mga shockwave upang umatake, nagdudulot ng #C0xE69900#470% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, permanenteng nagpapababa ng pisikal na depensa ng target ng 10%. Kapag napatay ang target, permanenteng tumataas ang sariling Pisikal na Atake ng 20% (hanggang 4 na beses, hindi maaaring tanggalin).',
		describe_ma = 'Taring Kapak Naga mengumpul kekuatan kemudian terbang ke arah sasaran musuh tunggal, memancarkan gelombang kejutan untuk menyerang, menyebabkan #C0xE69900#470% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Kecederaan Fizikal#C0x5B545B#, mengurangkan pertahanan fizikal sasaran secara kekal sebanyak 10%. Jika menyahaktifkan sasaran, akan meningkatkan Serangan Fizikal sendiri secara kekal sebanyak 20% (maksimum 4 kali, tidak dapat dipadamkan).',
		describe = 'Dragon Axe Fang gathers power and flies towards a single enemy target, emitting shockwaves to attack, dealing #C0xE69900#470% Physical Attack#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, permanently reducing the target\'s physical defense by 10%. If the target is defeated, permanently increase own Physical Attack by 20% (up to 4 times, cannot be removed).',
		simDesc_vn = 'Axew tích trữ sức mạnh, bay về phía mục tiêu đơn lẻ của kẻ thù, phát ra sóng xung kích tấn công, giảm vĩnh viễn phòng thủ vật lý của mục tiêu. Nếu tiêu diệt mục tiêu, sẽ tăng vĩnh viễn tấn công vật lý của bản thân.',
		simDesc_en = 'Axew gathers strength and flies towards a single enemy target, emitting a shockwave attack that permanently reduces the target\'s physical defense. If the target is defeated, Axew permanently increases its own physical attack.',
		simDesc_th = 'Axew สะสมพลัง บินไปยังเป้าหมายศัตรูเดี่ยว ปล่อยคลื่นช็อกเวฟโจมตี ลดการป้องกันทางกายภาพของเป้าหมายอย่างถาวร หากกำจัดเป้าหมายได้ จะเพิ่มพลังโจมตีทางกายภาพของตัวเองอย่างถาวร',
		simDesc_in = 'Axew mengumpulkan kekuatan dan terbang menuju satu target musuh, mengeluarkan serangan gelombang kejut yang mengurangi pertahanan fisik target secara permanen. Jika target dikalahkan, Axew akan meningkatkan serangan fisiknya secara permanen.',
		simDesc_ph = 'Nangangarap ng lakas si Axew at lumilipad papunta sa isang kalabang target, naglalabas ng shockwave attack na permanenteng nagpapababa sa pisikal na depensa ng target. Kung matatalo ang target, permanenteng tataas ang pisikal na atake ni Axew.',
		simDesc_ma = 'Axew mengumpul tenaga dan terbang ke arah sasaran musuh tunggal, mengeluarkan serangan gelombang kejut yang mengurangkan pertahanan fizikal sasaran secara kekal. Jika sasaran dikalahkan, Axew akan meningkatkan serangan fizikalnya secara kekal.',
		simDesc = 'Axew gathers strength and flies towards a single enemy target, emitting a shockwave attack that permanently reduces the target\'s physical defense. If the target is defeated, Axew permanently increases its own physical attack.',
		starEffect = __data_t__starEffect[30023],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Nếu tiêu diệt mục tiêu, thì vĩnh viễn tăng 40% vật công (giới hạn 4 tầng, không thể bị giải trừ) và lần đầu tiên kích hoạt kỹ năng đặc biệt sẽ tăng 40% xác suất tấn công tiếp theo.',
		starEffectDesc = 'Enhance Effect: If the target is eliminated, permanently increase physical attack by 40% (limit 4 stacks, cannot be dispelled) and the first time the special skill is activated, increase the next attack probability by 40%.',
		starEffectDesc_en = 'Enhance Effect: If the target is eliminated, permanently increase physical attack by 40% (limit 4 stacks, cannot be dispelled) and the first time the special skill is activated, increase the next attack probability by 40%.',
		starEffectDesc_th = 'เพิ่มพลังเอฟเฟกต์: หากกำจัดเป้าหมายได้ จะเพิ่มพลังโจมตีทางกายภาพถาวร 40% (จำกัด 4 ชั้น, ไม่สามารถถูกลบออกได้) และครั้งแรกที่เปิดใช้งานสกิลพิเศษ จะเพิ่มโอกาสโจมตีครั้งถัดไป 40%.',
		starEffectDesc_in = 'Perkuat Efek: Jika target berhasil dikalahkan, secara permanen tingkatkan serangan fisik sebesar 40% (batas 4 tumpukan, tidak bisa dihapus) dan saat pertama kali mengaktifkan skill khusus, tingkatkan peluang serangan berikutnya sebesar 40%.',
		starEffectDesc_ph = 'Palakasin ang Epekto: Kung matalo ang target, permanenteng tataasan ng 40% ang pisikal na atake (limitadong 4 na patong, hindi matatanggal) at sa unang activation ng espesyal na kakayahan ay tataasan ng 40% ang tsansa ng susunod na atake.',
		starEffectDesc_ma = 'Tingkatkan Kesan: Jika sasaran berjaya dibunuh, akan meningkatkan serangan fizikal kekal sebanyak 40% (had 4 lapisan, tidak boleh dibersihkan) dan kali pertama mengaktifkan kemahiran istimewa akan meningkatkan kebarangkalian serangan berikutnya sebanyak 40%.',
		zawakeEffect = __data_t__zawakeEffect[30023],
