	[30033] = {
		id = 30033,
		skillName_vn = 'Kẻ tiêu diệt tông đồ',
		skillName_en = 'The apostle exterminator',
		skillName_th = 'ฆ่าล้างตระกูลอัครสาวก',
		skillName_in = 'Pemusnah rasul',
		skillName_ph = 'Tagapagwasak ng mga apostol',
		skillName_ma = 'Pembasmi rasul',
		skillName = 'The apostle exterminator',
		describe_vn = 'Ayanami Rei ném cây thương thần Longinus, điên cuồng tấn công mục tiêu đơn phía địch, gây #C0xE69900#580% Công Vật Lý#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, vĩnh viễn giảm 10% phòng thủ vật lý của mục tiêu, nếu tiêu diệt mục tiêu, sẽ vĩnh viễn tăng 20% Công Vật Lý của bản thân (tối đa 4 tầng, không thể xóa bỏ)',
		describe_en = 'Ayanami Rei throws the divine spear Longinus, frantically attacking a single enemy target, dealing #C0xE69900#580% Physical Attack#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#, permanently reducing the target\'s physical defense by 10%. If the target is defeated, permanently increases own Physical Attack by 20% (up to 4 stacks, cannot be removed).',
		describe_th = 'อายานามิ เรย์ ขว้างหอกศักดิ์สิทธิ์ลองกินัส โจมตีเป้าหมายเดี่ยวอย่างบ้าคลั่ง สร้างความเสียหาย #C0xE69900#580% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ลดการป้องกันทางกายภาพของเป้าหมายถาวร 10% หากสังหารเป้าหมายได้ จะเพิ่มพลังโจมตีทางกายภาพของตนเองถาวร 20% (สูงสุด 4 ชั้น, ไม่สามารถลบได้)',
		describe_in = 'Ayanami Rei melempar tombak ilahi Longinus, menyerang gila-gilaan ke satu target musuh, memberikan #C0xE69900#580% Serangan Fisik#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, secara permanen mengurangi pertahanan fisik target sebesar 10%. Jika target dikalahkan, secara permanen meningkatkan Serangan Fisik sendiri sebesar 20% (maksimal 4 tumpukan, tidak dapat dihapus).',
		describe_ph = 'Ibinato ni Ayanami Rei ang banal na sibat na Longinus, nagwawala sa pag-atake sa isang kalaban lamang, nagdudulot ng #C0xE69900#580% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#, binabawasan nang permanente ang pisikal na depensa ng target ng 10%. Kung mapapatay ang target, permanente nitong pinapataas ang sariling Pisikal na Atake ng 20% (hanggang sa 4 na patong, hindi maaaring alisin).',
		describe_ma = 'Ayanami Rei melempar tombak suci Longinus, menyerang sasaran musuh tunggal dengan ganas, menyebabkan #C0xE69900#580% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Kecederaan Fizikal#C0x5B545B#, secara kekal mengurangkan pertahanan fizikal sasaran sebanyak 10%. Jika sasaran dibunuh, akan meningkatkan Serangan Fizikal sendiri secara kekal sebanyak 20% (maksimum 4 lapisan, tidak boleh dipadamkan).',
		describe = 'Ayanami Rei throws the divine spear Longinus, frantically attacking a single enemy target, dealing #C0xE69900#580% Physical Attack#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#, permanently reducing the target\'s physical defense by 10%. If the target is defeated, permanently increases own Physical Attack by 20% (up to 4 stacks, cannot be removed).',
		simDesc_vn = 'Rei Ayanami ném giáo Longinus tấn công mục tiêu đơn lẻ của kẻ thù, gây sát thương mạnh mẽ, giảm vĩnh viễn phòng thủ vật lý của mục tiêu. Nếu tiêu diệt mục tiêu, sẽ tăng vĩnh viễn tấn công vật lý của bản thân.',
		simDesc_en = 'Rei Ayanami throws the Longinus spear to attack a single enemy target, dealing powerful damage and permanently reducing the target\'s physical defense. If the target is defeated, Rei permanently increases her physical attack.',
		simDesc_th = 'เรย์ อายานามิ ขว้างหอกลองกินัสโจมตีเป้าหมายเดี่ยวของศัตรู สร้างความเสียหายรุนแรงและลดพลังป้องกันทางกายภาพของเป้าหมายอย่างถาวร หากกำจัดเป้าหมายได้ จะเพิ่มพลังโจมตีทางกายภาพของตัวเองอย่างถาวร',
		simDesc_in = 'Rei Ayanami melempar tombak Longinus untuk menyerang satu target musuh, memberikan kerusakan besar dan mengurangi pertahanan fisik target secara permanen. Jika target dikalahkan, akan meningkatkan serangan fisik Rei secara permanen.',
		simDesc_ph = 'Inihahatid ni Rei Ayanami ang Longinus na sibat upang atakihin ang isang kalabang target, na nagdudulot ng malakas na pinsala at permanenteng nagpapababa sa pisikal na depensa ng target. Kung mapapatay ang target, permanenteng tataas ang pisikal na atake ni Rei.',
		simDesc_ma = 'Rei Ayanami melempar tombak Longinus untuk menyerang satu sasaran musuh, memberikan kerosakan hebat dan mengurangkan pertahanan fizikal sasaran secara kekal. Jika sasaran dikalahkan, ia akan meningkatkan serangan fizikalnya secara kekal.',
		simDesc = 'Rei Ayanami throws the Longinus spear to attack a single enemy target, dealing powerful damage and permanently reducing the target\'s physical defense. If the target is defeated, Rei permanently increases her physical attack.',
		starEffect = __data_t__starEffect[30033],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Nếu tiêu diệt mục tiêu, thì vĩnh viễn tăng 40% vật công (giới hạn 4 tầng, không thể bị giải trừ) và lần đầu tiên kích hoạt kỹ năng đặc biệt sẽ tăng 40% xác suất tấn công tiếp theo.',
		starEffectDesc = 'Enhance Effect: If the target is defeated, permanently increase physical attack by 40% (max 4 stacks, cannot be removed) and the first time the special skill is activated, increase the next attack chance by 40%.',
		starEffectDesc_en = 'Enhance Effect: If the target is defeated, permanently increase physical attack by 40% (max 4 stacks, cannot be removed) and the first time the special skill is activated, increase the next attack chance by 40%.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: หากฆ่าเป้าหมายได้ จะเพิ่มพลังโจมตีทางกายภาพถาวร 40% (จำกัดสูงสุด 4 ชั้น ไม่สามารถลบได้) และครั้งแรกที่เปิดใช้งานสกิลพิเศษ จะเพิ่มโอกาสโจมตีถัดไป 40%.',
		starEffectDesc_in = 'Tingkatkan efek: Jika target dikalahkan, secara permanen tingkatkan serangan fisik sebesar 40% (batas 4 tumpuk, tidak bisa dihapus) dan pertama kali mengaktifkan skill khusus akan meningkatkan peluang serangan berikutnya sebesar 40%.',
		starEffectDesc_ph = 'Pahusayin ang epekto: Kung mapatay ang target, permanenteng tataasan ang pisikal na atake ng 40% (limit 4 na patong, hindi matatanggal) at sa unang pag-activate ng espesyal na kasanayan, tataasan ang tsansa ng susunod na atake ng 40%.',
		starEffectDesc_ma = 'Kukuhkan kesan: Jika menewaskan sasaran, tingkatkan serangan fizikal sebanyak 40% secara kekal (had 4 lapisan, tidak boleh dibuang) dan kali pertama mengaktifkan kemahiran khas akan meningkatkan peluang serangan seterusnya sebanyak 40%.',
		zawakeEffect = __data_t__zawakeEffect[30033],
