	[30036] = {
		id = 30036,
		skillName_vn = 'Hắt hơi bông tuyết',
		skillName_en = 'Snowflake sneeze',
		skillName_th = 'จามเกล็ดหิมะ',
		skillName_in = 'Bersin kepingan salju',
		skillName_ph = 'Bahing ng snowflake',
		skillName_ma = 'Selsema keping salji',
		skillName = 'Snowflake sneeze',
		describe_vn = 'Sau khi tấn công có #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# xác suất thực hiện lại cùng một đòn tấn công (đòn tấn công thêm không hồi nộ khí); khi liên tục tấn công cùng một mục tiêu, sát thương sẽ tăng dần 20%, tối đa 100% (nếu đổi mục tiêu giữa chừng sẽ tính lại từ đầu)',
		describe_en = 'After attacking, there is a #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# chance to perform the same attack again (additional attack does not restore rage); when continuously attacking the same target, damage gradually increases by 20%, up to a maximum of 100% (changing targets midway resets the count).',
		describe_th = 'หลังจากโจมตี มีโอกาส #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# ที่จะโจมตีเดิมอีกครั้ง (การโจมตีเพิ่มเติมจะไม่ฟื้นฟูพลังแค้น); เมื่อโจมตีเป้าหมายเดิมติดต่อกัน ความเสียหายจะเพิ่มขึ้นทีละ 20% สูงสุดไม่เกิน 100% (หากเปลี่ยนเป้าหมายกลางคันจะเริ่มนับใหม่)',
		describe_in = 'Setelah menyerang, ada peluang #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# untuk melakukan serangan yang sama lagi (serangan tambahan tidak mengembalikan kemarahan); ketika terus menyerang target yang sama, kerusakan akan bertambah 20%, hingga maksimal 100% (jika mengganti target di tengah, hitungan akan direset).',
		describe_ph = 'Pagkatapos umatake, may #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# na tsansa na ulitin ang parehong atake (ang karagdagang atake ay hindi nagbabalik ng galit); kapag tuloy-tuloy na umatake sa parehong target, ang pinsala ay tataas ng 20% kada sunod, hanggang sa maximum na 100% (kung lilipat ng target sa gitna, mababalik muli ang bilang).',
		describe_ma = 'Selepas menyerang, terdapat peluang #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# untuk melakukan serangan yang sama sekali lagi (serangan tambahan tidak memulihkan kemarahan); apabila menyerang sasaran yang sama secara berterusan, kerosakan akan meningkat secara berperingkat sebanyak 20%, sehingga maksimum 100% (jika menukar sasaran di tengah jalan, kiraan akan dimulakan semula).',
		describe = 'After attacking, there is a #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# chance to perform the same attack again (additional attack does not restore rage); when continuously attacking the same target, damage gradually increases by 20%, up to a maximum of 100% (changing targets midway resets the count).',
		starEffect = __data_t__starEffect[30036],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Tăng 10% xác suất tấn công tiếp theo.',
		starEffectDesc = 'Enhance effect: Increase the probability of the next attack by 10%.',
