	[30123] = {
		id = 30123,
		skillName_vn = 'Ngôi sao lạnh',
		skillName_en = 'Cold Star',
		skillName_th = 'ดาวหนาว',
		skillName_in = 'Bintang Dingin',
		skillName_ph = 'Malamig na Bituin',
		skillName_ma = 'Bintang Sejuk',
		skillName = 'Cold Star',
		describe_vn = 'Gấu Đồng Nguyên phun ra gió băng giá biến sân đấu xung quanh thành băng tuyết, đập mạnh xuống đất tạo ra hàng cột băng, nhấc khối băng lớn nhất ném vào mục tiêu hàng ngang địch, gây #C0xE69900#280% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, nếu tốc độ nhanh hơn mục tiêu, khi tấn công sẽ tăng thêm 30% chí mạng cho bản thân',
		describe_en = 'The Bronze Plains Bear exhales icy wind, turning the battlefield into ice and snow, slamming the ground to create rows of ice pillars, then lifts the largest ice block and throws it in a horizontal line at enemy targets, dealing #C0xE69900#280% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. If the bear\'s speed is higher than the target\'s, its attacks will gain an additional 30% critical hit chance.',
		describe_th = 'หมีบรอนซ์เพลนพ่นลมเย็นจนเปลี่ยนสนามรบรอบตัวเป็นน้ำแข็งและหิมะ ตบพื้นแรงๆ สร้างเสาหินน้ำแข็งหลายเสาแล้วยกก้อนน้ำแข็งใหญ่ที่สุดขว้างใส่เป้าหมายแนวตั้ง ทำดาเมจ #C0xE69900#280% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# หากความเร็วของหมีสูงกว่าเป้าหมาย การโจมตีจะได้รับโอกาสคริติคอลเพิ่มขึ้น 30%',
		describe_in = 'Beruang Bronze Plains menghembuskan angin beku yang mengubah arena pertempuran menjadi es dan salju, memukul tanah dengan keras menciptakan barisan tiang es, mengangkat bongkahan es terbesar lalu melemparkannya ke target musuh secara horizontal, memberikan #C0xE69900#280% Serangan Fisik#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Jika kecepatannya lebih tinggi dari target, serangan akan mendapat tambahan 30% peluang kritis.',
		describe_ph = 'Ang Bronze Plains Bear ay bumubuga ng nagyeyelong hangin na nagbabago sa paligsahan sa paligid upang maging yelo at niyebe, malakas na pinapabagsak ang lupa para lumikha ng hanay ng mga haligi ng yelo, binubuhat ang pinakamalaking bloke ng yelo at itinatapon ito sa mga pahalang na target ng kaaway, na nagdudulot ng #C0xE69900#280% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Kung mas mabilis ang bilis kaysa sa target, tataas ang 30% na kritikal na strike chance sa kanyang mga pag-atake.',
		describe_ma = 'Beruang Bronze Plains menghembuskan angin sejuk yang mengubah medan pertempuran menjadi ais dan salji, mengetuk tanah dengan kuat menghasilkan barisan tiang ais, mengangkat bongkah ais terbesar kemudian melemparkannya ke sasaran musuh secara mendatar, menyebabkan #C0xE69900#280% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Jika kelajuannya lebih tinggi daripada sasaran, serangan akan mendapat tambahan 30% kritikal untuk dirinya sendiri.',
		describe = 'The Bronze Plains Bear exhales icy wind, turning the battlefield into ice and snow, slamming the ground to create rows of ice pillars, then lifts the largest ice block and throws it in a horizontal line at enemy targets, dealing #C0xE69900#280% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. If the bear\'s speed is higher than the target\'s, its attacks will gain an additional 30% critical hit chance.',
		simDesc_vn = 'Gấu bắc cực phun ra gió băng, biến xung quanh thành một vùng băng giá, mạnh mẽ đập xuống đất tạo thành một hàng cột băng, nâng lên miếng băng lớn nhất ném vào mục tiêu theo hàng, nếu tốc độ nhanh hơn mục tiêu, sẽ tăng thêm tỷ lệ chí mạng khi tấn công.',
		simDesc_en = 'The polar bear releases a blast of icy wind, turning the surroundings into a frozen zone. It forcefully strikes the ground, creating a row of ice pillars, then raises the largest ice block and hurls it at the target in succession. If its speed is higher than the target\'s, it increases the critical hit rate when attacking.',
		simDesc_th = 'หมีขั้วโลกพ่นลมเย็นจัด ทำให้พื้นที่รอบตัวกลายเป็นเขตน้ำแข็ง จากนั้นกระแทกพื้นอย่างแรงสร้างเสาแห่งน้ำแข็งเป็นแถวยกก้อนน้ำแข็งใหญ่ที่สุดขึ้นแล้วขว้างใส่เป้าหมายเป็นแถว ถ้าความเร็วเร็วกว่าศัตรู จะเพิ่มอัตราการตีคริติคอลในการโจมตี',
		simDesc_in = 'Beruang kutub menghembuskan angin es, mengubah sekitarnya menjadi daerah beku. Ia kuat memukul tanah membentuk deretan pilar es, lalu mengangkat balok es terbesar dan melemparkannya ke sasaran secara berurutan. Jika kecepatannya lebih tinggi dari target, tingkat serangan kritis akan meningkat saat menyerang.',
		simDesc_ph = 'Ang polar bear ay umubug ng malamig na hangin ng yelo, ginagawang yelo ang paligid. Malakas nitong pinapalo ang lupa na gumagawa ng hanay ng mga haligi ng yelo, itinaas ang pinakamalaking yelo at pinapalahok ito sa target sunud-sunod. Kung mas mabilis ang bilis kaysa sa target, tataas ang kritikal na tsansa sa pag-atake.',
		simDesc_ma = 'Beruang kutub menghembuskan angin ais, mengubah sekeliling menjadi kawasan beku. Ia memukul tanah dengan kuat membentuk barisan tiang ais, kemudian mengangkat ketulan ais terbesar dan melemparkannya ke sasaran secara berbaris. Jika kelajuannya lebih pantas daripada sasaran, ia akan meningkatkan kadar serangan kritikal semasa menyerang.',
		simDesc = 'The polar bear releases a blast of icy wind, turning the surroundings into a frozen zone. It forcefully strikes the ground, creating a row of ice pillars, then raises the largest ice block and hurls it at the target in succession. If its speed is higher than the target\'s, it increases the critical hit rate when attacking.',
		starEffect = __data_t__starEffect[30123],
		-- {11}
		starEffectDesc_vn = 'Đối với mục tiêu có tốc độ chậm hơn, tăng 30% sát thương chí mạng.',
		starEffectDesc = 'For targets with slower speed, increase critical damage by 30%.',
		starEffectDesc_en = 'For targets with slower speed, increase critical damage by 30%.',
		starEffectDesc_th = 'สำหรับเป้าหมายที่มีความเร็วช้ากว่า เพิ่มความเสียหายคริติคอลขึ้น 30%',
		starEffectDesc_in = 'Untuk target dengan kecepatan lebih lambat, tingkatkan kerusakan kritis sebesar 30%.',
		starEffectDesc_ph = 'Para sa mga target na mabagal ang bilis, dagdagan ang kritikal na pinsala ng 30%.',
		starEffectDesc_ma = 'Untuk sasaran dengan kelajuan yang lebih perlahan, tingkatkan kerosakan kritikal sebanyak 30%.',
		zawakeEffect = __data_t__zawakeEffect[30123],
		-- {79003}
		zawakeEffectDesc = 'Tundra Bear breathes icy wind transforming the surrounding area into ice and snow, slamming down to create rows of ice pillars, lifting the largest ice block and throwing it at a horizontal row of enemy targets, causing #C0xE69900#280% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#, if faster than the target, increases critical rate by 50% when attacking',
		zawakeEffectDesc_en = 'Tundra Bear breathes icy wind transforming the surrounding area into ice and snow, slamming down to create rows of ice pillars, lifting the largest ice block and throwing it at a horizontal row of enemy targets, causing #C0xE69900#280% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#, if faster than the target, increases critical rate by 50% when attacking',
		zawakeEffectDesc_th = 'หมีทุนดร้าพ่นลมเย็นแช่แข็งเปลี่ยนพื้นที่รอบ ๆ เป็นน้ำแข็งและหิมะ ตีลงพื้นอย่างแรงสร้างเสา น้ำแข็งเป็นแถว ยกแท่งน้ำแข็งที่ใหญ่ที่สุดขว้างใส่แถวแนวนอนของศัตรู ทำให้เกิด #C0xE69900#280% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# หากเร็วกว่าเป้าหมาย จะเพิ่มอัตราคริติคอลอีก 50% เมื่อโจมตี',
		zawakeEffectDesc_in = 'Beruang Tundra menghembuskan angin es yang mengubah area sekitar menjadi salju dan es, menghantam tanah dengan keras menciptakan barisan tiang es, mengangkat balok es terbesar dan melemparkannya ke barisan horizontal target musuh, menyebabkan #C0xE69900#280% Serangan Fisik#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, jika lebih cepat dari target, meningkatkan kritikal sebesar 50% saat menyerang',
		zawakeEffectDesc_ph = 'Ang Tundra Bear ay humihinga ng nagyeyelong hangin na nagpapabago sa paligid na lugar sa yelo at niyebe, malakas na tinatama ang lupa upang lumikha ng mga hanay ng mga haligi ng yelo, iniangat ang pinakamalaking bloke ng yelo at inihahagis ito sa pahalang na hanay ng mga target na kalaban, nagdudulot ng #C0xE69900#280% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#, kung mas mabilis kaysa sa target, tumataas ng 50% ang critical rate kapag umaatake',
		zawakeEffectDesc_ma = 'Beruang Tundra menghembuskan angin ais yang mengubah kawasan sekeliling menjadi ais dan salji, menghentam tanah dengan kuat menghasilkan barisan tiang ais, mengangkat bongkah ais terbesar dan melemparkannya ke barisan mendatar sasaran musuh, menyebabkan #C0xE69900#280% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, jika lebih pantas daripada sasaran, meningkatkan kadar kritikal sebanyak 50% semasa menyerang',
		zawakeEffectDesc_vn = 'Gấu Tundra phun ra gió băng làm biến đổi khu vực xung quanh thành băng tuyết, đập mạnh xuống đất tạo ra hàng cột băng, nhấc khối băng lớn nhất ném vào mục tiêu hàng ngang của kẻ địch, gây #C0xE69900#280% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, nếu tốc độ nhanh hơn mục tiêu, sẽ tăng thêm 50% chí mạng khi tấn công',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'If faster than the target, gain an additional 30% Critical Rate when attacking#F20# #F40##C0x5c9970#→If faster than the target, gain an additional 50% Critical Rate when attacking#C0x5B545B#  ',
		zawakeSimpleDesc_en = 'If faster than the target, gain an additional 30% Critical Rate when attacking#F20# #F40##C0x5c9970#→If faster than the target, gain an additional 50% Critical Rate when attacking#C0x5B545B#  ',
		zawakeSimpleDesc_th = 'หากเร็วกว่าศัตรู จะเพิ่มอัตราคริติคอลของตัวเองอีก 30% เมื่อโจมตี#F20# #F40##C0x5c9970#→หากเร็วกว่าศัตรู จะเพิ่มอัตราคริติคอลของตัวเองอีก 50% เมื่อโจมตี#C0x5B545B#',
		zawakeSimpleDesc_in = 'Jika lebih cepat dari target, saat menyerang akan menambah 30% Crit Rate#F20# #F40##C0x5c9970#→Jika lebih cepat dari target, saat menyerang akan menambah 50% Crit Rate#C0x5B545B#  ',
		zawakeSimpleDesc_ph = 'Kung mas mabilis kaysa target, tataas ng 30% Crit Rate sa pag-atake#F20# #F40##C0x5c9970#→Kung mas mabilis kaysa target, tataas ng 50% Crit Rate sa pag-atake#C0x5B545B#  ',
		zawakeSimpleDesc_ma = 'Jika lebih laju dari sasaran, tambahkan 30% kadar Kritikal semasa menyerang#F20# #F40##C0x5c9970#→Jika lebih laju dari sasaran, tambahkan 50% kadar Kritikal semasa menyerang#C0x5B545B#  ',
		zawakeSimpleDesc_vn = 'Nếu tốc độ nhanh hơn mục tiêu, khi tấn công sẽ tăng thêm 30% chí mạng của bản thân#F20# #F40##C0x5c9970#→Nếu tốc độ nhanh hơn mục tiêu, khi tấn công sẽ tăng thêm 50% chí mạng của bản thân#C0x5B545B#',
