	[30216] = {
		id = 30216,
		skillName_vn = 'Kẻ Thống Trị Vong Linh',
		skillName_en = 'The Ghost Overlord',
		skillName_th = 'ผู้ปกครองผีดิบ',
		skillName_in = 'Penguasa Roh Gentayangan',
		skillName_ph = 'Ang Tagapamahala ng mga Multo',
		skillName_ma = 'Penguasa Roh Hantu',
		skillName = 'The Ghost Overlord',
		describe_vn = 'Tăng Phép Phòng trong 2 lượt trước chiến đấu #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B#(không thể bị xóa);\nSau khi bị tấn công, phản xạ một hiệu ứng tiêu cực ngẫu nhiên của bản thân lên kẻ tấn công, và có #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# xác suất khiến kẻ đó [Đóng băng] 1 lượt (Đóng băng: hiệu ứng kiểm soát, không thể hành động, bị giải trừ sau khi nhận sát thương tích lũy vượt quá 30% sinh mệnh của mục tiêu)',
		describe_en = 'Increases Magic Defense for 2 turns before battle by #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (cannot be removed); \n After being attacked, reflects a random negative effect on yourself back to the attacker, and has a #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# chance to cause the attacker to be [Frozen] for 1 turn (Frozen: a control effect, unable to act, removed after receiving accumulated damage exceeding 30% of the target\'s health).',
		describe_th = 'เพิ่มการป้องกันเวทมนตร์เป็นเวลา 2 เทิร์นก่อนเริ่มการต่อสู้ #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (ไม่สามารถลบได้); \n หลังจากถูกโจมตี จะสะท้อนผลลบสุ่มที่มีต่อตัวเองไปยังผู้โจมตี และมีโอกาส #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# ที่จะทำให้ผู้โจมตีถูก [แช่แข็ง] เป็นเวลา 1 เทิร์น (แช่แข็ง: เอฟเฟกต์ควบคุม ไม่สามารถกระทำใดๆ ได้ และจะถูกลบเมื่อได้รับความเสียหายรวมเกิน 30% ของพลังชีวิตเป้าหมาย)',
		describe_in = 'Meningkatkan Pertahanan Sihir selama 2 giliran sebelum bertarung #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (tidak dapat dihapus); \n Setelah diserang, memantulkan efek negatif acak dari diri sendiri ke penyerang, dan memiliki #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# peluang untuk menyebabkan penyerang [Membeku] selama 1 giliran (Membeku: efek kontrol, tidak bisa bertindak, dihapus setelah menerima kerusakan kumulatif melebihi 30% dari kesehatan target)',
		describe_ph = 'Pinapataas ang Magic Defense sa loob ng 2 turn bago ang laban #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (hindi matatanggal); \n Pagkatapos tamaan, nire-reflect ang isang random na negatibong epekto mula sa sarili pabalik sa umaatake, at may #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# tsansa na mapagyelo ([Frozen]) ang umaatake ng 1 turn (Frozen: control effect, hindi pwedeng kumilos, matatanggal kapag tumanggap ng damage na lampas sa 30% ng HP ng target)',
		describe_ma = 'Meningkatkan Pertahanan Sihir selama 2 pusingan sebelum bertarung #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (tidak boleh dipadamkan); \n Selepas diserang, memantulkan satu kesan negatif rawak daripada diri sendiri kepada penyerang, dan mempunyai peluang #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# untuk menyebabkan penyerang [Membeku] selama 1 pusingan (Membeku: kesan kawalan, tidak boleh bertindak, dibuang selepas menerima kerosakan terkumpul melebihi 30% daripada nyawa sasaran)',
		describe = 'Increases Magic Defense for 2 turns before battle by #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (cannot be removed); \n After being attacked, reflects a random negative effect on yourself back to the attacker, and has a #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# chance to cause the attacker to be [Frozen] for 1 turn (Frozen: a control effect, unable to act, removed after receiving accumulated damage exceeding 30% of the target\'s health).',
		starEffect = __data_t__starEffect[30216],
