	[30223] = {
		id = 30223,
		skillName_vn = 'Ma trận băng khóa lục giác',
		skillName_en = 'Hexagonal lock matrix',
		skillName_th = 'เมทริกซ์ล็อคหกเหลี่ยม',
		skillName_in = 'Matriks kunci heksagonal',
		skillName_ph = 'Hexagonal lock matrix',
		skillName_ma = 'Matriks kunci heksagonal',
		skillName = 'Hexagonal lock matrix',
		describe_vn = 'Những bông tuyết hình học khúc xạ ánh sáng lạnh qua lại và cuối cùng phản xạ tập thể tới tất cả mục tiêu của kẻ thù, gây ra #C0x3D8A99#120% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#sát thương ma thuật#C0x5B545B#, với 30% xác suất [đóng băng] mục tiêu trong 2 lượt và tăng khả năng phòng thủ ma thuật của bản thân lên thêm Giảm 120% và 15% sát thương phép trong 2 lượt.',
		describe_en = 'Geometric snowflakes refract cold light back and forth and finally collectively reflect towards all enemy targets, causing #C0x3D8A99#120% Magical Damage#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54#magic damage#C0x5B545B#, with a 30% chance to [freeze] the target for 2 turns and increasing own magical defense by reducing magical damage taken by 120% and 15% for 2 turns.',
		describe_th = 'เกล็ดหิมะเรขาคณิตที่หักเหแสงเย็นไปมาและสุดท้ายสะท้อนรวมกันไปยังเป้าหมายศัตรูทั้งหมด สร้าง #C0x3D8A99#120% ความเสียหายเวทมนตร์#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# มีโอกาส 30% ที่จะ [แช่แข็ง] เป้าหมายเป็นเวลา 2 เทิร์น และเพิ่มความสามารถป้องกันเวทมนตร์ของตัวเองโดยลดความเสียหายเวทมนตร์ที่ได้รับลง 120% และ 15% เป็นเวลา 2 เทิร์น',
		describe_in = 'Butiran salju geometris membiaskan cahaya dingin bolak-balik dan akhirnya memantulkan secara kolektif ke semua target musuh, menyebabkan #C0x3D8A99#120% Kerusakan Magis#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54#kerusakan magis#C0x5B545B#, dengan peluang 30% untuk [membekukan] target selama 2 giliran dan meningkatkan pertahanan magis diri dengan mengurangi kerusakan magis sebesar 120% dan 15% selama 2 giliran.',
		describe_ph = 'Ang mga geometric na snowflake ay nagrereflect ng malamig na ilaw pabalik-balik at sa huli ay sama-samang bumabalik sa lahat ng mga target na kalaban, nagdudulot ng #C0x3D8A99#120% Magical Damage#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54#magical damage#C0x5B545B#, na may 30% na tsansa na [mag-freeze] ng target sa loob ng 2 turns at pinapataas ang sariling magical defense sa pamamagitan ng pagbawas ng magical damage ng 120% at 15% sa loob ng 2 turns.',
		describe_ma = 'Bunga salji geometri membias cahaya sejuk ke sana ke mari dan akhirnya memantul secara kolektif ke semua sasaran musuh, menyebabkan #C0x3D8A99#120% Kerosakan Magik#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54#kerosakan magik#C0x5B545B#, dengan peluang 30% untuk [membekukan] sasaran selama 2 pusingan dan meningkatkan pertahanan magik diri dengan mengurangkan kerosakan magik sebanyak 120% dan 15% selama 2 pusingan.',
		describe = 'Geometric snowflakes refract cold light back and forth and finally collectively reflect towards all enemy targets, causing #C0x3D8A99#120% Magical Damage#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54#magic damage#C0x5B545B#, with a 30% chance to [freeze] the target for 2 turns and increasing own magical defense by reducing magical damage taken by 120% and 15% for 2 turns.',
		simDesc_vn = 'Cryogonal triệu hồi trận pháp băng sáu cánh để tấn công toàn bộ mục tiêu của đối phương, có cơ hội đóng băng mục tiêu, đồng thời tăng phòng thủ phép thuật và giảm sát thương phép nhận vào cho bản thân.',
		simDesc_en = 'Cryogonal summons a six-winged ice formation to attack all enemy targets, with a chance to freeze them, while simultaneously increasing its magic defense and reducing magic damage received.',
		simDesc_th = 'Cryogonal เรียกใช้การจัดการน้ำแข็งหกปีกเพื่อโจมตีเป้าหมายทั้งหมดของศัตรู มีโอกาสทำให้เป้าหมายแข็งตัว พร้อมกับเพิ่มการป้องกันเวทมนตร์และลดความเสียหายเวทมนตร์ที่ได้รับสำหรับตัวเอง',
		simDesc_in = 'Cryogonal memanggil formasi es bersayap enam untuk menyerang semua target musuh, dengan peluang membekukan target, sekaligus meningkatkan pertahanan sihir dan mengurangi kerusakan sihir yang diterima untuk dirinya sendiri.',
		simDesc_ph = 'Inilulunsad ni Cryogonal ang anim na pakpak na yelong pormasyon upang atakihin ang lahat ng mga target ng kalaban, na may pagkakataong mapapaso ang mga target, kasabay ng pagtaas ng depensa sa mahika at pagbabawas ng tanging pinsalang mahika na natatanggap para sa sarili.',
		simDesc_ma = 'Cryogonal memanggil formasi ais enam sayap untuk menyerang semua sasaran musuh, dengan peluang membekukan sasaran, sekaligus meningkatkan pertahanan sihir dan mengurangkan kerosakan sihir yang diterima untuk dirinya sendiri.',
		simDesc = 'Cryogonal summons a six-winged ice formation to attack all enemy targets, with a chance to freeze them, while simultaneously increasing its magic defense and reducing magic damage received.',
		starEffect = __data_t__starEffect[30223],
