	[30226] = {
		id = 30226,
		skillName_vn = 'Frost Seal',
		skillName_en = 'Frost Seal',
		skillName_th = 'ตราประทับแห่งน้ำแข็ง',
		skillName_in = 'Segel Beku',
		skillName_ph = 'Selyo ng Yelo',
		skillName_ma = 'Meterai Sejuk',
		skillName = 'Frost Seal',
		describe_vn = 'Tăng Phép Phòng trong 2 lượt trước chiến đấu #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B#（không thể bị xóa）；\nSau khi bị tấn công, phản xạ một hiệu ứng tiêu cực ngẫu nhiên của bản thân lên kẻ tấn công, và có #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# xác suất khiến kẻ đó [Đóng băng] 1 lượt (Đóng băng: hiệu ứng kiểm soát, không thể hành động, bị giải trừ sau khi nhận sát thương tích lũy vượt quá 30% sinh mệnh của mục tiêu)',
		describe_en = 'Increase Magic Defense for 2 turns before battle by #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (cannot be removed); after being attacked, reflect a random negative effect from yourself onto the attacker, and has a #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# chance to cause the attacker to be [Frozen] for 1 turn (Frozen: control effect, cannot act, removed after receiving cumulative damage exceeding 30% of the target\'s HP).',
		describe_th = 'เพิ่มค่าป้องกันเวทใน 2 เทิร์นก่อนการต่อสู้ #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (ไม่สามารถลบออกได้); หลังถูกโจมตี สะท้อนผลลบสุ่มจากตัวเองไปยังผู้โจมตี และมีโอกาส #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# ทำให้ผู้โจมตีถูก [แช่แข็ง] เป็นเวลา 1 เทิร์น (แช่แข็ง: ผลควบคุม ไม่สามารถกระทำได้ จะถูกปลดหลังรับความเสียหายสะสมเกิน 30% ของพลังชีวิตเป้าหมาย)',
		describe_in = 'Tingkatkan Pertahanan Magic selama 2 giliran sebelum bertarung sebesar #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (tidak dapat dihapus); setelah diserang, memantulkan efek negatif acak dari diri sendiri ke penyerang, dan memiliki peluang #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# untuk membuat penyerang [Membeku] selama 1 giliran (Membeku: efek kontrol, tidak bisa bertindak, dihapus setelah menerima kerusakan kumulatif melebihi 30% dari HP target).',
