	[31512] = {
		id = 31512,
		skillName_vn = 'Xung phong lửa chớp',
		skillName_en = 'Charge the lightning fire',
		skillName_th = 'บุกไฟฟ้าฟ้าผ่า',
		skillName_in = 'Maju api petir',
		skillName_ph = 'Sugod ang apoy ng kidlat',
		skillName_ma = 'Maju api kilat',
		skillName = 'Charge the lightning fire',
		describe_vn = 'Sâu cháy bùng lên ngọn lửa, cuộn mình lại và lao vào mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#150% Công Phép#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, thêm [Áo lông mặt trời] cho mục tiêu hàng trước của phe mình có giới hạn sinh mệnh cao nhất trong 3 lượt (Áo lông mặt trời: hiệu ứng tăng cường, khi bị tấn công sẽ gây sát thương thuộc tính lửa bằng 120% Công Phép của Bướm lửa lên kẻ tấn công, khi có Áo lông mặt trời sẽ giải trừ hiệu ứng trói buộc trên mục tiêu)',
		describe_en = 'The blazing larva ignites a fire, curls up, and charges at a single enemy target, dealing #C0x3D8A99#150% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, then grants [Sun Feather Cloak] to the front-row ally with the highest max HP for 3 turns (Sun Feather Cloak: a buff effect that reflects fire attribute damage equal to 120% of the Magic Power of the Fire Butterfly back to the attacker when attacked, and removes binding effects from the target while active).',
		describe_th = 'ตัวหนอนไฟลุกโชนลุกขึ้นเป็นเปลวไฟ ม้วนตัวและพุ่งเข้าหาศัตรูเป้าหมายเดียว ก่อให้เกิด #C0x3D8A99#150% พลังเวท#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# จากนั้นมอบ [เสื้อขนนกดวงอาทิตย์] ให้กับพันธมิตรแถวหน้าที่มีพลังชีวิตสูงสุด 3 เทิร์น (เสื้อขนนกดวงอาทิตย์: เอฟเฟกต์เสริม ที่เมื่อถูกโจมตีจะสะท้อนความเสียหายธาตุไฟเป็นจำนวน 120% ของพลังเวทของผีเสื้อไฟไปยังผู้โจมตี และขณะมีเอฟเฟกต์นี้จะปลดปล่อยการผูกมัดจากเป้าหมาย)',
		describe_in = 'Larva yang membara menyalakan api, menggulung tubuhnya, dan menyerang satu target musuh, menyebabkan #C0x3D8A99#150% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, kemudian memberikan [Jubah Bulu Matahari] kepada anggota barisan depan sekutu dengan HP maksimum tertinggi selama 3 giliran (Jubah Bulu Matahari: efek peningkatan yang saat diserang akan memantulkan kerusakan atribut api sebesar 120% Kekuatan Sihir dari Kupu-kupu Api ke penyerang, dan saat memiliki Jubah Bulu Matahari akan menghapus efek ikatan pada target).',
		describe_ph = 'Ang apoy na uod ay sumisiklab, nagluluko at sumasalang sa isang solong target ng kaaway, na nagdudulot ng #C0x3D8A99#150% Kapangyarihan ng Mahika#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Pinsalang Mahika #C0x5B545B#, pagkatapos ay nagbibigay ng [Balabal ng mga Balahibong Araw] sa pakatiringan sa unahang hilera na may pinakamataas na max HP sa loob ng 3 mga turn (Balabal ng mga Balahibong Araw: effect ng buff, kapag inatake, magbibigay ng apoy na pinsala na katumbas ng 120% Kapangyarihan ng Mahika ng Fire Butterfly pabalik sa umaatake, at habang may Balabal ng mga Balahibong Araw ay aalisin ang binding effects sa target).',
		describe_ma = 'Larva yang membakar menyala dengan api, menggulung dan menyerang sasaran tunggal musuh, menyebabkan #C0x3D8A99#150% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, kemudian memberikan [Jubah Bulu Matahari] kepada sekutu barisan hadapan dengan HP maksimum tertinggi selama 3 giliran (Jubah Bulu Matahari: kesan peningkatan yang apabila diserang akan memantulkan kerosakan elemen api sebanyak 120% Kuasa Sihir Kupu-kupu Api kepada penyerang, dan apabila mempunyai Jubah Bulu Matahari akan membuang kesan ikatan pada sasaran).',
		describe = 'The blazing larva ignites a fire, curls up, and charges at a single enemy target, dealing #C0x3D8A99#150% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, then grants [Sun Feather Cloak] to the front-row ally with the highest max HP for 3 turns (Sun Feather Cloak: a buff effect that reflects fire attribute damage equal to 120% of the Magic Power of the Fire Butterfly back to the attacker when attacked, and removes binding effects from the target while active).',
		zawakeEffect = __data_t__zawakeEffect[31512],
		-- {79002}
		zawakeEffectDesc = 'The Flame Rages, igniting the fire on the body, curling up and charging at a single enemy target, dealing #C0x3D8A99#150% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, adding <Sun Feather Cloak> to the front-row enemy with the highest health limit on our side for 3 turns, with a 50% chance to add the Sun Feather Cloak to another front-row enemy with the highest health limit for 3 turns. (Sun Feather Cloak: enhancement effect, when attacked will deal fire attribute damage equal to 120% of the Magic Power of Fire Butterfly to the attacker, and when having the Sun Feather Cloak it will remove binding effects on the target)',
		zawakeEffectDesc_en = 'The Flame Rages, igniting the fire on the body, curling up and charging at a single enemy target, dealing #C0x3D8A99#150% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, adding <Sun Feather Cloak> to the front-row enemy with the highest health limit on our side for 3 turns, with a 50% chance to add the Sun Feather Cloak to another front-row enemy with the highest health limit for 3 turns. (Sun Feather Cloak: enhancement effect, when attacked will deal fire attribute damage equal to 120% of the Magic Power of Fire Butterfly to the attacker, and when having the Sun Feather Cloak it will remove binding effects on the target)',
		zawakeEffectDesc_th = 'เปลวไฟลุกโชน จุดไฟลุกบนร่างกาย ม้วนตัวพุ่งเข้าหาศัตรูเป้าหมายเดียว ก่อให้เกิด #C0x3D8A99#150% พลังเวทย์#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทย์ #C0x5B545B# เพิ่ม <เสื้อขนนกตะวัน> ให้เป้าหมายแถวหน้าที่มีพลังชีวิตจำกัดสูงสุดในฝั่งเราเป็นเวลา 3 เทิร์น มีโอกาส 50% ที่จะเพิ่มเสื้อขนนกตะวันให้เป้าหมายแถวหน้าอื่นที่มีพลังชีวิตจำกัดสูงสุดใน 3 เทิร์น (เสื้อขนนกตะวัน: ผลบวก เมื่อถูกโจมตีจะสร้างความเสียหายธาตุไฟเท่ากับ 120% ของพลังเวทย์ของผีเสื้อไฟแก่ผู้โจมตี และเมื่อมีเสื้อขนนกตะวันจะกำจัดสถานะผูกมัดออกจากเป้าหมาย)',
		zawakeEffectDesc_in = 'Api Menyala, membakar nyala api pada tubuh, meringkuk dan menerjang ke satu target musuh, menyebabkan #C0x3D8A99#150% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, menambahkan <Jubah Bulu Matahari> pada target baris depan dengan batas kesehatan tertinggi di pihak kita selama 3 giliran, dengan kemungkinan 50% menambahkan Jubah Bulu Matahari pada target baris depan lain yang memiliki batas kesehatan tertinggi selama 3 giliran. (Jubah Bulu Matahari: efek peningkatan, saat diserang akan memberikan kerusakan atribut api sebesar 120% Kekuatan Sihir dari Kupu-kupu Api kepada penyerang, saat memiliki Jubah Bulu Matahari akan menghilangkan efek ikatan pada target)',
		zawakeEffectDesc_ph = 'Nag-aalab na Apoy, nagpapaliyab ng apoy sa katawan, yumuko at sumugod sa isang target na kalaban, nagdudulot ng #C0x3D8A99#150% Kapangyarihang Pangkaka#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Panlaban na Pinsala #C0x5B545B#, nagdaragdag ng <Baluti ng Balahibong Araw> sa panandang nasa unahang hanay na may pinakamataas na limitasyon ng buhay sa ating panig sa loob ng 3 turn, may 50% tsansa na magdagdag ng Baluti ng Balahibong Araw sa isa pang panandang nasa unahang hanay na may pinakamataas na limitasyon ng buhay sa loob ng 3 turn. (Baluti ng Balahibong Araw: epekto ng pagpapalakas, kapag inatake ay magdudulot ng apoy na pinsala na katumbas ng 120% ng Kapangyarihang Pangkaka ng Apoy na Paruparo sa umaatake, kapag may Baluti ng Balahibong Araw ay aalisin ang epekto ng pagkakadena sa target)',
		zawakeEffectDesc_ma = 'Api Membara, membakar api pada tubuh, meringkuk dan meluru ke sasaran musuh tunggal, menyebabkan #C0x3D8A99#150% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, menambah <Jubah Bulu Matahari> kepada sasaran barisan hadapan dengan had nyawa tertinggi pihak kita selama 3 pusingan, dengan 50% peluang untuk menambah Jubah Bulu Matahari kepada sasaran barisan hadapan lain yang mempunyai had nyawa tertinggi selama 3 pusingan. (Jubah Bulu Matahari: kesan peningkatan, apabila diserang akan menyebabkan kerosakan atribut api sebanyak 120% Kuasa Sihir Rama Api kepada penyerang, apabila mempunyai Jubah Bulu Matahari akan menghapuskan kesan ikatan pada sasaran)',
		zawakeEffectDesc_vn = 'Trùng Cháy bùng cháy ngọn lửa trên cơ thể, cuộn tròn thân mình lao vào mục tiêu đơn của kẻ địch, gây #C0x3D8A99#150% Công Phép#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, thêm <Áo Lông Mặt Trời> cho mục tiêu hàng trước có giới hạn sinh mệnh cao nhất của phe ta trong 3 lượt, có 50% xác suất thêm Áo Lông Mặt Trời cho mục tiêu hàng trước khác có giới hạn sinh mệnh cao nhất trong 3 lượt (Áo Lông Mặt Trời: hiệu ứng tăng cường, khi bị tấn công sẽ gây sát thương thuộc tính lửa bằng 120% Công Phép của Bướm Lửa lên kẻ tấn công, khi có Áo Lông Mặt Trời sẽ giải trừ hiệu ứng trói buộc trên mục tiêu)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#50% chance to grant Sun Feather Cloak to the front-row ally with the highest HP limit for 3 turns',
		zawakeSimpleDesc_en = '#C0x5c9970#50% chance to grant Sun Feather Cloak to the front-row ally with the highest HP limit for 3 turns',
		zawakeSimpleDesc_th = '#C0x5c9970#มีโอกาส 50% มอบ “เสื้อคลุมขนนกแห่งดวงอาทิตย์” ให้เป้าหมายแถวหน้าที่มีพลังชีวิตสูงสุด เป็นเวลา 3 เทิร์น',
		zawakeSimpleDesc_in = '#C0x5c9970#Peluang 50% untuk memberikan Jubah Bulu Matahari kepada sekutu baris depan dengan batas HP tertinggi selama 3 giliran',
		zawakeSimpleDesc_ph = '#C0x5c9970#May 50% tsansa na magbigay ng Balabal ng Araw sa kakampi sa front row na may pinakamataas na limit ng HP sa loob ng 3 turn',
		zawakeSimpleDesc_ma = '#C0x5c9970#Peluang 50% untuk memberi Jubah Bulu Matahari kepada sekutu barisan hadapan dengan had HP tertinggi selama 3 giliran',
