	[31513] = {
		id = 31513,
		skillName_vn = 'Cộng hưởng côn trùng',
		skillName_en = 'Insect Resonance',
		skillName_th = 'เรโซแนนซ์แมลง',
		skillName_in = 'Resonansi Serangga',
		skillName_ph = 'Insektong Pagsabog',
		skillName_ma = 'Resonans Serangga',
		skillName = 'Insect Resonance',
		describe_vn = 'Sâu cháy hít một hơi sâu, sau đó phun ra ngọn lửa rực cháy thiêu đốt mục tiêu hàng sau của kẻ địch, gây ra #C0x3D8A99#240% Công Phép#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, thêm 20% dễ tổn thương cho mục tiêu chính trong 1 lượt, tăng 20% xác suất mời chiến, có thể mời chiến tối đa 3 mục tiêu được đồng minh chọn tấn công',
		describe_en = 'The Flame Moth takes a deep breath, then exhales blazing flames that scorch the enemy\'s backline targets, dealing #C0x3D8A99#240% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, adds 20% vulnerability to the main target for 1 turn, increases taunt chance by 20%, can taunt up to 3 targets selected by allies to attack.',
		describe_th = 'ผีเสื้อไฟสูดลมหายใจลึก แล้วพ่นเปลวเพลิงร้อนแรงเผาผลาญเป้าหมายแถวหลังของศัตรู สร้าง #C0x3D8A99#240% พลังเวท#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# เพิ่ม 20% ความเปราะบางให้กับเป้าหมายหลักเป็นเวลา 1 เทิร์น เพิ่มโอกาสล่อลวง 20% สามารถล่อลวงได้สูงสุด 3 เป้าหมายที่พันธมิตรเลือกโจมตี',
		describe_in = 'Ngengat Api menghirup napas dalam, lalu menghembuskan api membara yang membakar target belakang musuh, menyebabkan #C0x3D8A99#240% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Magis #C0x5B545B#, menambahkan 20% kerentanan pada target utama selama 1 giliran, meningkatkan peluang memancing serangan sebesar 20%, dapat memancing serangan hingga maksimal 3 target yang dipilih sekutu untuk diserang.',
		describe_ph = 'Huminga ng malalim ang Nasusunog na Uod ng Apoy, pagkatapos ay sumabog ng naglalagablab na apoy na sinusunog ang mga target sa likod ng kaaway, na nagdudulot ng #C0x3D8A99#240% Lakas ng Mahika#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Pinsalang Mahika #C0x5B545B#, nagdaragdag ng 20% kahinaan sa pangunahing target sa loob ng 1 turn, nagpapataas ng 20% tsansa ng pang-akit, maaaring mag-akit ng hanggang 3 target na pinili ng kaalyado upang atakihin.',
		describe_ma = 'Ngengat Api menarik nafas dalam-dalam, kemudian menghembuskan api yang membakar sasaran barisan belakang musuh, menyebabkan #C0x3D8A99#240% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, menambah 20% kerentanan pada sasaran utama selama 1 giliran, meningkatkan 20% peluang \'taunt\', boleh memancing serangan sehingga 3 sasaran yang dipilih oleh sekutu untuk diserang.',
		describe = 'The Flame Moth takes a deep breath, then exhales blazing flames that scorch the enemy\'s backline targets, dealing #C0x3D8A99#240% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, adds 20% vulnerability to the main target for 1 turn, increases taunt chance by 20%, can taunt up to 3 targets selected by allies to attack.',
		simDesc_vn = 'Lửa thiêu đốt hít một hơi, sau đó phun ra ngọn lửa dữ dội thiêu đốt mục tiêu ở hàng sau của kẻ thù, gây thêm hiệu ứng dễ bị tổn thương cho mục tiêu chính, tăng tỷ lệ mời chiến.',
		simDesc_en = 'The burning flame inhales deeply, then unleashes a fierce blaze that scorches the enemies in the back row, inflicting a vulnerability debuff on the main target and increasing the chance to provoke.',
		simDesc_th = 'เปลวไฟลุกโชนสูดลมหายใจเข้าเต็มปอดก่อนจะพ่นเปลวไฟแรงกล้าที่เผาทำลายเป้าหมายในแถวหลังของศัตรู พร้อมสร้างสถานะเปราะบางแก่เป้าหมายหลักและเพิ่มโอกาสในการล่อศัตรูให้มายังตัวเอง',
		simDesc_in = 'Api yang membara menghirup nafas dalam, kemudian menghembuskan api hebat yang membakar target di barisan belakang musuh, memberikan efek kerentanan pada target utama, serta meningkatkan peluang untuk memancing pertarungan.',
		simDesc_ph = 'Humihinga ang naglalagablab na apoy, pagkatapos ay sumabog ng matinding apoy na sinusunog ang mga target sa likurang hanay ng kalaban, nagkakaroon ng karagdagang epekto ng kahinaan sa pangunahing target, at tumataas ang tsansa ng paghamon sa laban.',
		simDesc_ma = 'Api yang membara menyedut udara, kemudian melontarkan api yang dahsyat membakar sasaran barisan belakang musuh, memberikan efek kerentanan kepada sasaran utama, serta meningkatkan kadar cabaran.',
		simDesc = 'The burning flame inhales deeply, then unleashes a fierce blaze that scorches the enemies in the back row, inflicting a vulnerability debuff on the main target and increasing the chance to provoke.',
		starEffect = __data_t__starEffect[31513],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Gây hiệu ứng 15% dễ bị tổn thương bởi kiếm lên mục tiêu trong 2 lượt.',
		starEffectDesc = 'Additional effect: Inflict 15% increased vulnerability to sword attacks on the target for 2 turns.',
		starEffectDesc_en = 'Additional effect: Inflict 15% increased vulnerability to sword attacks on the target for 2 turns.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ทำให้เป้าหมายได้รับความเสียหายจากดาบเพิ่มขึ้น 15% เป็นเวลา 2 ตา',
		starEffectDesc_in = 'Efek tambahan: Menyebabkan target 15% lebih rentan terhadap serangan pedang selama 2 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Nagdudulot ng 15% na mas mataas na pagka-marupok sa espada sa target sa loob ng 2 na turn.',
		starEffectDesc_ma = 'Kesan tambahan: Menyebabkan sasaran 15% lebih mudah terdedah kepada serangan pedang selama 2 giliran.',
		zawakeEffect = __data_t__zawakeEffect[31513],
		-- {79003}
		zawakeEffectDesc = 'Trùng Cháy takes a deep breath, then exhales a blazing flame that burns the enemy\'s back-row targets, dealing #C0x3D8A99#240% Spell Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, applying 20% increased vulnerability to the main target for 1 turn, increasing the chance to provoke by 20%, can provoke up to 4 allied targets to attack the chosen target',
		zawakeEffectDesc_en = 'Trùng Cháy takes a deep breath, then exhales a blazing flame that burns the enemy\'s back-row targets, dealing #C0x3D8A99#240% Spell Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, applying 20% increased vulnerability to the main target for 1 turn, increasing the chance to provoke by 20%, can provoke up to 4 allied targets to attack the chosen target',
		zawakeEffectDesc_th = 'Trùng Cháy สูดลมหายใจลึกๆ จากนั้นพ่นเปลวไฟลุกโชนเผาผลาญเป้าหมายแถวหลังของศัตรู สร้าง #C0x3D8A99#240% พลังเวทย์#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทย์มนตร์ #C0x5B545B# เพิ่มความเปราะบาง 20% แก่เป้าหมายหลักเป็นเวลา 1 เทิร์น เพิ่มโอกาสล่อศัตรู 20% สามารถล่อศัตรูสูงสุด 4 เป้าหมายฝ่ายเราให้โจมตีเป้าหมายที่เลือก',
		zawakeEffectDesc_in = 'Trùng Cháy menarik napas dalam-dalam, lalu menghembuskan api menyala yang membakar target barisan belakang musuh, memberikan #C0x3D8A99#240% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, menambah 20% kerentanan pada target utama selama 1 giliran, meningkatkan peluang mengajak bertarung sebesar 20%, dapat mengajak bertarung maksimal 4 target dari pihak kita menyerang target yang dipilih',
		zawakeEffectDesc_ph = 'Huminga nang malalim si Trùng Cháy, pagkatapos ay bumuga ng naglalagablab na apoy na sinusunog ang mga target sa likod na hanay ng kalaban, nagdudulot ng #C0x3D8A99#240% Spell Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, dagdagan ang 20% kahinaan sa pangunahing target sa loob ng 1 turn, dagdagan ang 20% tsansa na mag-provoke, maaaring mag-provoke ng hanggang 4 na target mula sa ating panig upang atakihin ang napiling target',
		zawakeEffectDesc_ma = 'Trùng Cháy menarik nafas dalam-dalam, kemudian menghembuskan api membara yang membakar sasaran barisan belakang musuh, menyebabkan #C0x3D8A99#240% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, menambah 20% kerentanan pada sasaran utama selama 1 pusingan, meningkatkan 20% peluang menggoda, boleh menggoda maksimum 4 sasaran pihak kita menyerang sasaran yang dipilih',
		zawakeEffectDesc_vn = 'Trùng Cháy hít một hơi sâu, sau đó phun ra ngọn lửa rực cháy thiêu đốt mục tiêu hàng sau của kẻ địch, gây #C0x3D8A99#240% Công Phép#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, thêm 20% dễ tổn thương lên mục tiêu chính trong 1 lượt, tăng 20% xác suất mời chiến, có thể mời chiến tối đa 4 mục tiêu phe ta tấn công mục tiêu đã chọn',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Can invite up to 3 allies to attack#F20# #F40##C0x5c9970#→Can invite up to 4 allies to attack',
		zawakeSimpleDesc_en = 'Can invite up to 3 allies to attack#F20# #F40##C0x5c9970#→Can invite up to 4 allies to attack',
		zawakeSimpleDesc_th = 'สามารถเชิญพันธมิตรได้สูงสุด 3 คนให้โจมตี#F20# #F40##C0x5c9970#→สามารถเชิญพันธมิตรได้สูงสุด 4 คนให้โจมตี',
		zawakeSimpleDesc_in = 'Dapat mengundang hingga 3 sekutu untuk menyerang#F20# #F40##C0x5c9970#→Dapat mengundang hingga 4 sekutu untuk menyerang',
		zawakeSimpleDesc_ph = 'Maaaring mag-imbita ng hanggang 3 kakampi na umatake#F20# #F40##C0x5c9970#→Maaaring mag-imbita ng hanggang 4 kakampi na umatake',
		zawakeSimpleDesc_ma = 'Boleh menjemput maksimum 3 sekutu untuk menyerang#F20# #F40##C0x5c9970#→Boleh menjemput maksimum 4 sekutu untuk menyerang',
		zawakeSimpleDesc_vn = 'Có thể mời tối đa 3 đồng minh tấn công#F20# #F40##C0x5c9970#→Có thể mời tối đa 4 đồng minh tấn công',
