	[31516] = {
		id = 31516,
		skillName_vn = 'Lửa tím',
		skillName_en = 'Purple flame',
		skillName_th = 'เปลวไฟสีม่วง',
		skillName_in = 'Api ungu',
		skillName_ph = 'Lila na apoy',
		skillName_ma = 'Api ungu',
		skillName = 'Purple flame',
		describe_vn = 'Khi tấn công [Mời chiến] ngẫu nhiên 1 đồng minh (Mời chiến: Đồng minh được mời chiến sẽ sử dụng đòn đánh thường để tấn công cùng mục tiêu kẻ địch), mỗi đồng minh có #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# xác suất được mời chiến, tỷ lệ càng thấp của mục tiêu bị tấn công thì xác suất càng cao, tối đa có thể tăng lên 40%, nếu là anh hùng hệ kiếm thì xác suất tăng thêm 40%;\nBản thân vĩnh viễn sở hữu [Áo lông mặt trời] (không thể xóa bỏ)',
		describe_en = 'When attacking, [Challenge] randomly invites an ally (Challenge: The invited ally will use normal attacks to attack the same enemy target). Each ally has a #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# chance to be invited. The lower the attacked target’s rate, the higher the chance, up to a maximum increase of 40%. If the ally is a sword-type hero, the chance increases by an additional 40%; \n Permanently own [Sun Feather Cloak] (cannot be removed).',
		describe_th = 'เมื่อโจมตี [ท้าแข่ง] จะสุ่มเชิญพันธมิตร 1 คน (ท้าแข่ง: พันธมิตรที่ถูกเชิญจะใช้การโจมตีปกติเพื่อโจมตีเป้าหมายศัตรูเดียวกัน) แต่ละพันธมิตรมี #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# โอกาสถูกเชิญ ยิ่งอัตราของเป้าหมายถูกโจมตียิ่งต่ำ โอกาสจะยิ่งสูงขึ้น สูงสุดเพิ่มได้ถึง 40% หากเป็นฮีโร่สายดาบ โอกาสจะเพิ่มขึ้นอีก 40%; \n ครอบครองถาวร [เสื้อขนนกแห่งดวงอาทิตย์] (ไม่สามารถลบได้)',
		describe_in = 'Saat menyerang, [Tantang] secara acak mengundang 1 sekutu (Tantang: Sekutu yang diundang akan menggunakan serangan biasa untuk menyerang target musuh yang sama). Setiap sekutu memiliki peluang #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# untuk diundang, semakin rendah tingkat target yang diserang, semakin tinggi peluangnya, maksimum dapat meningkat hingga 40%. Jika pahlawan tipe pedang, peluang bertambah 40%; \n Memiliki secara permanen [Jubah Bulu Matahari] (tidak dapat dihapus).',
		describe_ph = 'Kapag umaatake, [Hamunin] ay random na pipili ng isang alyado (Hamunin: Ang inimbitahang alyado ay gagamit ng normal na atake upang atakihin ang kaparehong kaaway). Bawat alyado ay may #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# na tsansa na maimbitahan. Kapag mas mababa ang rate ng target na inaatake, mas mataas ang tsansa, hanggang maximum na 40% ang pwedeng tumaas. Kung bayani ay nasa klase ng espada, tataas pa ng 40% ang tsansa; \n Palaging may [Kulot ng Araw] (hindi pwedeng tanggalin).',
		describe_ma = 'Semasa menyerang, [Cabaran] akan secara rawak menjemput 1 sekutu (Cabaran: Sekutu yang dijemput akan menggunakan serangan biasa untuk menyerang sasaran musuh yang sama). Setiap sekutu mempunyai peluang #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# untuk dijemput, semakin rendah kadar sasaran yang diserang, semakin tinggi peluang, maksimum boleh meningkat sehingga 40%. Jika wira jenis pedang, peluang meningkat sebanyak 40%; \n Memiliki secara kekal [Jubah Bulu Matahari] (tidak boleh dipadam).',
		describe = 'When attacking, [Challenge] randomly invites an ally (Challenge: The invited ally will use normal attacks to attack the same enemy target). Each ally has a #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# chance to be invited. The lower the attacked target’s rate, the higher the chance, up to a maximum increase of 40%. If the ally is a sword-type hero, the chance increases by an additional 40%; \n Permanently own [Sun Feather Cloak] (cannot be removed).',
		starEffect = __data_t__starEffect[31516],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi đồng minh bị mời chiến đấu tấn công, sát thương tăng 15%.',
		starEffectDesc = 'Additional Effect: When allies are invited to fight and attack, damage increases by 15%.',
		starEffectDesc_en = 'Additional Effect: When allies are invited to fight and attack, damage increases by 15%.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อพันธมิตรถูกเชิญให้ต่อสู้และโจมตี ความเสียหายจะเพิ่มขึ้น 15%',
		starEffectDesc_in = 'Efek tambahan: Ketika sekutu diundang untuk bertarung dan menyerang, kerusakan meningkat sebesar 15%.',
		starEffectDesc_ph = 'Karagdagang Epekto: Kapag inimbitahan ang mga kakampi na makipaglaban at umatake, tumataas ng 15% ang pinsala.',
		starEffectDesc_ma = 'Kesan Tambahan: Apabila sekutu dijemput untuk bertarung dan menyerang, kerosakan meningkat sebanyak 15%.',
		zawakeEffect = __data_t__zawakeEffect[31516],
		-- {79004}
		zawakeEffectDesc = 'When attacking <Invite to Battle> a random teammate (Invite to Battle: the invited teammate will use normal attacks to attack the same enemy target), each teammate has #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# chance to be invited to battle, the chance increases as the target\'s HP ratio decreases, up to a maximum of 40%. If the hero is a swordsman type, the chance increases by an additional 40%;\nPermanently possesses <Sun Feather Cloak> (cannot be removed)',
		zawakeEffectDesc_en = 'When attacking <Invite to Battle> a random teammate (Invite to Battle: the invited teammate will use normal attacks to attack the same enemy target), each teammate has #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# chance to be invited to battle, the chance increases as the target\'s HP ratio decreases, up to a maximum of 40%. If the hero is a swordsman type, the chance increases by an additional 40%;\nPermanently possesses <Sun Feather Cloak> (cannot be removed)',
		zawakeEffectDesc_th = 'เมื่อโจมตี <เชิญรบ> สมาชิกในทีมแบบสุ่ม 1 คน (เชิญรบ: สมาชิกทีมที่ถูกเชิญจะใช้งานโจมตีปกติเพื่อโจมตีเป้าหมายศัตรูเดียวกัน) แต่ละสมาชิกมีโอกาส #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# ที่จะถูกเชิญรบ โอกาสจะเพิ่มขึ้นเมื่ออัตราพลังชีวิตของเป้าหมายต่ำลง โดยสูงสุดเพิ่มขึ้นถึง 40% หากเป็นฮีโร่สายดาบ โอกาสจะเพิ่มขึ้นอีก 40%;\nเป็นเจ้าของ <เสื้อขนนกพระอาทิตย์> ถาวร (ไม่สามารถลบได้)',
		zawakeEffectDesc_in = 'Saat menyerang <Undang Bertempur> satu anggota tim secara acak (Undang Bertempur: anggota tim yang diundang akan menggunakan serangan biasa untuk menyerang target musuh yang sama), setiap anggota tim memiliki #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# peluang untuk diundang bertempur, peluang meningkat saat rasio HP target rendah, maksimal hingga 40%. Jika pahlawan adalah tipe pedang, peluang meningkat tambahan 40%;\nSelamanya memiliki <Jubah Bulu Matahari> (tidak dapat dihapus)',
		zawakeEffectDesc_ph = 'Kapag umaatake ng <Imbitahan sa Laban> ng isang random na kasamahan (Imbitahan sa Laban: ang inimbitahang kasamahan ay gagamit ng karaniwang atake upang atakehin ang parehong kalaban), bawat kasamahan ay may #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# tsansa na imbitahan sa laban, tumataas ang tsansa kapag mababa ang HP ratio ng target, hanggang maximum na 40%. Kung ang bayani ay swordsman type, tataas pa ng 40% ang tsansa;\nPalaging nagmamay-ari ng <Sun Feather Cloak> (hindi maaaring alisin)',
		zawakeEffectDesc_ma = 'Semasa menyerang <Jemput Berperang> seorang rakan sepasukan secara rawak (Jemput Berperang: rakan sepasukan yang dijemput akan menggunakan serangan biasa untuk menyerang sasaran musuh yang sama), setiap rakan sepasukan mempunyai #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# peluang dijemput berperang, peluang meningkat apabila nisbah nyawa sasaran rendah, maksimum meningkat kepada 40%. Jika wira adalah jenis pedang, peluang bertambah 40% lagi;\nSentiasa memiliki <Jubah Bulu Matahari> (tidak boleh dibuang)',
		zawakeEffectDesc_vn = 'Khi tấn công <Mời Chiến> ngẫu nhiên 1 đồng đội (Mời Chiến: đồng đội được mời chiến sẽ sử dụng đòn đánh thường tấn công cùng mục tiêu kẻ địch), mỗi đồng đội có #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# xác suất được mời chiến, tỷ lệ xác suất tăng cao khi tỷ lệ sinh mệnh của mục tiêu thấp, tối đa có thể tăng lên 40%, nếu là anh hùng hệ kiếm thì xác suất tăng thêm 40%;\nBản thân vĩnh viễn sở hữu <Áo Lông Mặt Trời> (không thể xóa bỏ)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Attack invitation chance increased by 10%',
		zawakeSimpleDesc_en = 'Attack invitation chance increased by 10%',
		zawakeSimpleDesc_th = 'โอกาสเชิญโจมตีเพิ่มขึ้น 10%',
