	[31522] = {
		id = 31522,
		skillName_vn = 'Ngọn lửa bay',
		skillName_en = 'Flying flame',
		skillName_th = 'เปลวไฟบิน',
		skillName_in = 'Api terbang',
		skillName_ph = 'Lumilipad na apoy',
		skillName_ma = 'Api terbang',
		skillName = 'Flying flame',
		describe_vn = 'Shana sử dụng năng lượng kiếm lửa đỏ bằng thanh kiếm của mình, tấn công một mục tiêu địch như ngọn lửa bay, gây #C0xF13B54#Sát Thương Phép Thuật của #C0x3D8A99#220% tấn Công Phép thuật#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, thêm [Quần áo lông mặt trời] vào mục tiêu thân thiện có giới hạn máu cao nhất ở hàng trước trong 3 lượt (Quần Áo Lông Mặt Trời: buff hiệu ứng, gây sát thương thuộc tính lửa 120% Sát Thương Phép Thuật của Shana cho kẻ tấn công khi bị tấn công. Có Quần Áo Lông Mặt Trời sẽ loại bỏ hiệu ứng vướng víu lên mục tiêu)',
		describe_en = 'Shana uses red flame sword energy with her sword, attacking an enemy target like a flying flame, dealing #C0xF13B54#Magic Damage of #C0x3D8A99#220% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, adding [Sun Feather Garment] to the friendly target with the highest HP in the front row for 3 turns (Sun Feather Garment: buffs effects, deals fire attribute damage equal to 120% of Shana\'s Magic Damage to attackers when attacked. Having Sun Feather Garment removes bind effects on the target).',
		describe_th = 'ชานะใช้พลังดาบเพลิงสีแดงด้วยดาบของเธอ โจมตีเป้าหมายศัตรูเหมือนเปลวไฟที่บิน ส่งผล #C0xF13B54#ความเสียหายเวทมนตร์ของ #C0x3D8A99#220% การโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# เพิ่ม [ชุดขนนกแห่งดวงอาทิตย์] ให้กับเป้าหมายฝ่ายเดียวที่มีพลังชีวิตสูงสุดในแถวหน้าตลอด 3 เทิร์น (ชุดขนนกแห่งดวงอาทิตย์: เสริมบัฟผล ส่งผลความเสียหายธาตุไฟ 120% ของความเสียหายเวทมนตร์ของชานะให้กับผู้โจมตีเมื่อถูกโจมตี มีชุดขนนกแห่งดวงอาทิตย์จะลบผลผูกมัดออกจากเป้าหมาย)',
		describe_in = 'Shana menggunakan energi pedang api merah dengan pedangnya, menyerang target musuh seperti api yang terbang, memberikan #C0xF13B54#Kerusakan Sihir sebesar #C0x3D8A99#220% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, menambahkan [Pakaian Bulu Matahari] pada target teman dengan HP tertinggi di barisan depan selama 3 giliran (Pakaian Bulu Matahari: memberikan buff efek, memberikan kerusakan atribut api sebesar 120% Kerusakan Sihir Shana kepada penyerang saat diserang. Pakaian Bulu Matahari akan menghilangkan efek tersangkut pada target).',
		describe_ph = 'Ginagamit ni Shana ang enerhiya ng pulang apoy sa kanyang espada, inaatake ang isang kaaway na target na parang lumilipad na apoy, na nagdudulot ng #C0xF13B54#Magic Damage ng #C0x3D8A99#220% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, nagdadagdag ng [Sun Feather Garment] sa kaibigang target na may pinakamataas na HP sa front row sa loob ng 3 turn (Sun Feather Garment: nagbabuff ng effect, nagbibigay ng sunog na damage na katumbas ng 120% Magic Damage ni Shana sa umaatake kapag inaatake. Ang pagkakaroon ng Sun Feather Garment ay aalisin ang bind effect sa target).',
		describe_ma = 'Shana menggunakan tenaga pedang api merah dengan pedangnya, menyerang sasaran musuh seperti api yang terbang, memberi #C0xF13B54#Kerosakan Sihir sebanyak #C0x3D8A99#220% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, menambah [Pakaian Bulu Matahari] kepada sasaran rakan yang mempunyai HP tertinggi di barisan hadapan selama 3 pusingan (Pakaian Bulu Matahari: memberikan buff kesan, memberikan kerosakan atribut api sebanyak 120% Kerosakan Sihir Shana kepada penyerang apabila diserang. Mempunyai Pakaian Bulu Matahari akan menghilangkan kesan terikat pada sasaran).',
		describe = 'Shana uses red flame sword energy with her sword, attacking an enemy target like a flying flame, dealing #C0xF13B54#Magic Damage of #C0x3D8A99#220% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, adding [Sun Feather Garment] to the friendly target with the highest HP in the front row for 3 turns (Sun Feather Garment: buffs effects, deals fire attribute damage equal to 120% of Shana\'s Magic Damage to attackers when attacked. Having Sun Feather Garment removes bind effects on the target).',
		simDesc_vn = 'Shana sử dụng năng lượng kiếm lửa đỏ bằng thanh kiếm của mình, tấn công một mục tiêu kẻ thù như ngọn lửa bay.',
		simDesc_en = 'Shana uses the red flame energy with her sword, attacking an enemy target like a flying flame.',
		simDesc_th = 'ชานะใช้พลังไฟสีแดงด้วยดาบของเธอ โจมตีเป้าหมายศัตรูเหมือนไฟที่ลุกโชนบินไป',
		simDesc_in = 'Shana menggunakan energi api merah dengan pedangnya, menyerang target musuh seperti api yang terbang.',
		simDesc_ph = 'Ginagamit ni Shana ang pulang enerhiya ng apoy gamit ang kanyang espada, umatake sa isang kaaway na parang lumilipad na apoy.',
		simDesc_ma = 'Shana menggunakan tenaga api merah dengan pedangnya, menyerang sasaran musuh seperti api yang terbang.',
		simDesc = 'Shana uses the red flame energy with her sword, attacking an enemy target like a flying flame.',
		zawakeEffect = __data_t__zawakeEffect[31522],
		-- {79002}
		zawakeEffectDesc = 'Shana uses the red fire sword energy with her sword, attacking an enemy target like flying flames, causing #C0x3D8A99#220% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magical Damage#C0x5B545B#, on the friendly front line. The target with the highest HP limit in the row is granted <Sun Fur Clothes> for 3 turns, and there is a 50% chance to add Sun Fur Clothes to the remaining target in the front row with the highest HP limit for 3 turns (Sun Fur Clothes: buff effect, when attacked will deal fire damage equal to 120% of Shana\'s Magical Damage back to the attacker. Having Sun Fur Clothes will remove the entangle effect from the target)',
		zawakeEffectDesc_en = 'Shana uses the red fire sword energy with her sword, attacking an enemy target like flying flames, causing #C0x3D8A99#220% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magical Damage#C0x5B545B#, on the friendly front line. The target with the highest HP limit in the row is granted <Sun Fur Clothes> for 3 turns, and there is a 50% chance to add Sun Fur Clothes to the remaining target in the front row with the highest HP limit for 3 turns (Sun Fur Clothes: buff effect, when attacked will deal fire damage equal to 120% of Shana\'s Magical Damage back to the attacker. Having Sun Fur Clothes will remove the entangle effect from the target)',
		zawakeEffectDesc_th = 'ชานะใช้พลังดาบไฟสีแดงด้วยดาบของเธอ โจมตีเป้าหมายศัตรูเหมือนไฟที่บิน, สร้างความเสียหายเวทมนตร์ #C0x3D8A99#220%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# ให้กับแนวหน้าเพื่อน เลือกเป้าหมายที่มีพลังชีวิตสูงสุดในแถวเพื่อรับ <ผ้าขนสัตว์ดวงอาทิตย์> เป็นเวลา 3 เทิร์น และมีโอกาส 50% ที่จะเพิ่มผ้าขนสัตว์ดวงอาทิตย์ให้กับเป้าหมายที่เหลือในแถวหน้า ซึ่งมีพลังชีวิตสูงสุดเป็นเวลา 3 เทิร์น (ผ้าขนสัตว์ดวงอาทิตย์: เอฟเฟกต์บัฟ เมื่อถูกโจมตีจะสร้างความเสียหายไฟเท่ากับ 120% ของความเสียหายเวทของชานะกลับทายาทที่โจมตี การมีผ้าขนสัตว์ดวงอาทิตย์จะช่วยลบเอฟเฟกต์พันธนาการออกจากเป้าหมาย)',
		zawakeEffectDesc_in = 'Shana menggunakan energi pedang api merah dengan pedangnya, menyerang target musuh seperti api yang terbang, menyebabkan #C0x3D8A99#220% Kerusakan Ajaib#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerusakan Ajaib#C0x5B545B#, pada barisan depan teman. Target dengan batas HP tertinggi dalam baris mendapatkan <Pakaian Bulu Matahari> selama 3 giliran, dan ada peluang 50% untuk menambahkan Pakaian Bulu Matahari ke target yang tersisa di barisan depan dengan batas HP tertinggi selama 3 giliran (Pakaian Bulu Matahari: efek buff, saat diserang akan memberikan kerusakan api sebesar 120% Kerusakan Ajaib Shana kepada penyerang. Memiliki Pakaian Bulu Matahari akan menghapus efek terjerat dari target)',
		zawakeEffectDesc_ph = 'Gumagamit si Shana ng enerhiya ng pulang apoy ng espada gamit ang kanyang espada, ina-atake ang isang target na kalaban na parang lumilipad na apoy, nagdudulot ng #C0x3D8A99#220% Sakit na Mahiwaga#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sakit na Mahiwaga#C0x5B545B#, sa magiliw na harapan. Ang target na may pinakamataas na limitasyon ng HP sa hanay ay nakakakuha ng <Damit ng Balahibo ng Araw> para sa 3 na rounds, at may 50% posibilidad na maidagdag ang Damit ng Balahibo ng Araw sa natitirang target sa unang hanay na may pinakamataas na limitasyon ng HP sa loob ng 3 rounds (Damit ng Balahibo ng Araw: epekto ng buff, kapag inatake ay nagdudulot ng apoy na pinsala na katumbas ng 120% ng Sakit na Mahiwaga ni Shana pabalik sa umaatake. Ang pagkakaroon ng Damit ng Balahibo ng Araw ay aalisin ang epekto ng pagkakabigti sa target)',
		zawakeEffectDesc_ma = 'Shana menggunakan tenaga pedang api merah dengan pedangnya, menyerang sasaran musuh seperti api terbang, menyebabkan #C0x3D8A99#220% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerosakan Sihir#C0x5B545B#, pada barisan hadapan rakan. Sasaran dengan had HP tertinggi dalam barisan diberi <Pakaian Bulu Matahari> selama 3 pusingan, dan ada 50% peluang untuk menambah Pakaian Bulu Matahari pada sasaran yang tinggal di barisan hadapan dengan had HP tertinggi selama 3 pusingan (Pakaian Bulu Matahari: kesan buff, apabila diserang akan menyebabkan kerosakan api sama dengan 120% Kerosakan Sihir Shana kepada penyerang. Mempunyai Pakaian Bulu Matahari akan menghapuskan kesan ikatan pada sasaran)',
		zawakeEffectDesc_vn = 'Shana sử dụng năng lượng kiếm lửa đỏ bằng thanh kiếm của mình, tấn công một mục tiêu kẻ thù như ngọn lửa bay, gây ra #C0x3D8A99#220% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, là mặt trận thân thiện. Mục tiêu có giới hạn máu cao nhất trong hàng được thêm <Quần áo lông mặt trời> cho 3 lượt, và có 50% xác suất thêm Quần Áo Lông Mặt Trời vào mục tiêu còn lại ở hàng trước có giới hạn máu cao nhất trong 3 lượt (Quần Áo Lông Mặt Trời: hiệu ứng buff, khi bị tấn công sẽ gây sát thương lửa bằng 120% Sát Thương Phép Thuật của Shana lên kẻ tấn công. Có Quần Áo Lông Mặt Trời sẽ loại bỏ hiệu ứng vướng víu lên mục tiêu)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#50% chance to grant Sun Feather Cloak to the front-row ally with the highest HP limit for 3 turns',
