	[31526] = {
		id = 31526,
		skillName_vn = 'Chiến binh Sương Lửa',
		skillName_en = 'Frostfire Warrior',
		skillName_th = 'นักรบไฟน้ำแข็ง',
		skillName_in = 'Prajurit Es Api',
		skillName_ph = 'Mandirigmang Apoy-Yelo',
		skillName_ma = 'Pahlawan Api Ais',
		skillName = 'Frostfire Warrior',
		describe_vn = 'Khi tấn công [Mời chiến] ngẫu nhiên 1 đồng minh (Mời chiến: Đồng minh được mời chiến sẽ sử dụng đòn đánh thường để tấn công cùng mục tiêu kẻ địch), mỗi đồng minh có #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# xác suất được mời chiến, tỷ lệ càng thấp của mục tiêu bị tấn công thì xác suất càng cao, tối đa có thể tăng lên 40%, nếu là anh hùng hệ kiếm thì xác suất tăng thêm 40%;\nBản thân vĩnh viễn sở hữu [Áo lông mặt trời] (không thể xóa bỏ)',
		describe_en = 'When attacking, [Challenge Ally] randomly summons 1 ally (Challenge Ally: The summoned ally will use normal attacks to attack the same enemy target). Each ally has a #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# chance to be summoned. The lower the target\'s hit rate, the higher the chance, up to a maximum increase of 40%. If the ally is a sword-wielding hero, the chance increases by an additional 40%.;\n Permanently possesses [Sun Feather Cloak] (cannot be removed).',
		describe_th = 'เมื่อโจมตี [ท้าชวนพันธมิตร] สุ่มพันธมิตร 1 คน (ท้าชวนพันธมิตร: พันธมิตรที่ถูกชวนจะใช้การโจมตีปกติเพื่อโจมตีเป้าหมายศัตรูเดียวกัน) แต่ละพันธมิตรมีโอกาส #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# ในการถูกชวน ยิ่งอัตราการโจมตีของเป้าหมายต่ำ โอกาสจะยิ่งสูงขึ้น สามารถเพิ่มได้สูงสุด 40% หากเป็นฮีโร่สายดาบ โอกาสจะเพิ่มขึ้นอีก 40%;\n เป็นเจ้าของ [เสื้อขนนกแสงอาทิตย์] ตลอดกาล (ไม่สามารถลบได้).',
		describe_in = 'Saat menyerang, [Tantang Sekutu] secara acak memanggil 1 sekutu (Tantang Sekutu: Sekutu yang dipanggil akan menggunakan serangan normal untuk menyerang target musuh yang sama). Setiap sekutu memiliki peluang #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# untuk dipanggil. Semakin rendah tingkat target yang diserang, semakin tinggi peluangnya, dengan kenaikan maksimum 40%. Jika pahlawan menggunakan pedang, peluang meningkat sebesar 40%;\n Selalu memiliki [Jubah Bulu Matahari] (tidak bisa dihapus).',
		describe_ph = 'Kapag umatake, [Anyayahan ng Pakikipaglaban] ay random na pumipili ng 1 kaalyado (Anyayahan ng Pakikipaglaban: Ang kaalyadong naanyayahan ay gagamit ng normal na pag-atake para atakihin ang parehong kalaban). Bawat kaalyado ay may #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# na tsansa na mapanyayahan. Kapag mas mababa ang hit rate ng target na inaatake, mas mataas ang tsansa, hanggang maximum na 40%. Kung bayani ay mula sa sword type, dagdagan ng 40% ang tsansa;\n Lagi siyang may [Balabal ng Balahibong Araw] (hindi maaaring alisin).',
		describe_ma = 'Apabila menyerang, [Ajak Bertempur] secara rawak memanggil 1 sekutu (Ajak Bertempur: Sekutu yang dijemput akan menggunakan serangan biasa untuk menyerang musuh yang sama). Setiap sekutu mempunyai #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# peluang untuk dijemput. Semakin rendah sasaran diserang, semakin tinggi peluang, maksimum boleh meningkat sehingga 40%. Jika wira menggunakan pedang, peluang bertambah 40%;\n Sentiasa memiliki [Jubah Bulu Matahari] (tidak boleh dipadam).',
		describe = 'When attacking, [Challenge Ally] randomly summons 1 ally (Challenge Ally: The summoned ally will use normal attacks to attack the same enemy target). Each ally has a #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# chance to be summoned. The lower the target\'s hit rate, the higher the chance, up to a maximum increase of 40%. If the ally is a sword-wielding hero, the chance increases by an additional 40%.;\n Permanently possesses [Sun Feather Cloak] (cannot be removed).',
		starEffect = __data_t__starEffect[31526],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi đồng minh bị mời chiến đấu tấn công, sát thương tăng 15%.',
		starEffectDesc = 'Additional effect: When an ally is invited to fight and attack, damage increases by 15%.',
		starEffectDesc_en = 'Additional effect: When an ally is invited to fight and attack, damage increases by 15%.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อพันธมิตรถูกเชิญให้ต่อสู้และโจมตี ความเสียหายเพิ่มขึ้น 15%',
		starEffectDesc_in = 'Efek tambahan: Ketika sekutu diundang untuk bertarung dan menyerang, kerusakan meningkat 15%.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag inimbitahan ang kakampi na lumaban at umatake, tumataas ang pinsala ng 15%.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila sekutu dijemput untuk berperang dan menyerang, kerosakan meningkat 15%.',
		zawakeEffect = __data_t__zawakeEffect[31526],
		-- {79004}
		zawakeEffectDesc = 'When attacking <Invite to Battle> a random teammate (Invite to Battle: the invited teammate will use a normal attack to attack the same enemy target), each teammate has #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# chance to be invited to battle, the chance increases when the enemy\'s health rate is low, up to a maximum of 40%, if it is a sword system hero, the chance increases by an additional 40%;\nPermanently own <Sun Feather Cloak> (cannot be removed)',
		zawakeEffectDesc_en = 'When attacking <Invite to Battle> a random teammate (Invite to Battle: the invited teammate will use a normal attack to attack the same enemy target), each teammate has #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# chance to be invited to battle, the chance increases when the enemy\'s health rate is low, up to a maximum of 40%, if it is a sword system hero, the chance increases by an additional 40%;\nPermanently own <Sun Feather Cloak> (cannot be removed)',
		zawakeEffectDesc_th = 'เมื่อโจมตี <เชิญเข้าร่วมต่อสู้> เพื่อนร่วมทีมแบบสุ่ม 1 คน (เชิญเข้าร่วมต่อสู้: เพื่อนร่วมทีมที่ถูกเชิญจะใช้การโจมตีปกติเพื่อโจมตีเป้าหมายศัตรูเดียวกัน), แต่ละเพื่อนร่วมทีมมีโอกาส #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# ที่จะถูกเชิญเข้าร่วมต่อสู้, โอกาสจะเพิ่มขึ้นเมื่ออัตราพลังกำลังของศัตรูต่ำ, สูงสุดเพิ่มขึ้นถึง 40%, หากเป็นฮีโร่ระบบดาบ โอกาสเพิ่มขึ้นอีก 40%;\nเป็นเจ้าของ <เสื้อขนนกพระอาทิตย์> อย่างถาวร (ไม่สามารถลบได้)',
		zawakeEffectDesc_in = 'Saat menyerang <Undang Bertarung> satu rekan tim secara acak (Undang Bertarung: rekan tim yang diundang akan menggunakan serangan biasa untuk menyerang target musuh yang sama), setiap rekan tim memiliki #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# peluang untuk diundang bertarung, peluang meningkat saat rasio kesehatan target rendah, maksimal bisa meningkat hingga 40%, jika hero jenis pedang maka peluang meningkat tambahan 40%;\nSelamanya memiliki <Jubah Bulu Matahari> (tidak dapat dihapus)',
		zawakeEffectDesc_ph = 'Kapag umatake <Imbitahan sa Laban> ng isang random na kasama sa koponan (Imbitahan sa Laban: ang imbitadong kasama ay gagamit ng normal na atake upang atakihin ang parehong target na kaaway), bawat kasama ay may #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# na tsansang maimbitahan sa laban, tumataas ang tsansa kapag mababa ang health rate ng target, maximum na tataas ng 40%, kung bayani ng uri ng espada, tataas pa ng dagdag na 40%;\nPermanente na may <Sun Feather Cloak> (hindi maaaring alisin)',
		zawakeEffectDesc_ma = 'Apabila menyerang <Jemput Bertarung> rakan sepasukan secara rawak 1 orang (Jemput Bertarung: rakan sepasukan yang dijemput akan menggunakan serangan biasa untuk menyerang sasaran musuh yang sama), setiap rakan sepasukan mempunyai #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# peluang untuk dijemput bertarung, peluang meningkat apabila kadar nyawa sasaran rendah, maksimum boleh meningkat sehingga 40%, jika wira jenis pedang peluang meningkat tambahan 40%;\nSentiasa memiliki <Jubah Bulu Matahari> (tidak boleh dipadamkan)',
		zawakeEffectDesc_vn = 'Khi tấn công <Mời Chiến> ngẫu nhiên 1 đồng đội (Mời Chiến: đồng đội được mời chiến sẽ sử dụng đòn đánh thường tấn công cùng mục tiêu kẻ địch), mỗi đồng đội có #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# xác suất được mời chiến, tỷ lệ xác suất tăng cao khi tỷ lệ sinh mệnh của mục tiêu thấp, tối đa có thể tăng lên 40%, nếu là anh hùng hệ kiếm thì xác suất tăng thêm 40%;\nBản thân vĩnh viễn sở hữu <Áo Lông Mặt Trời> (không thể xóa bỏ)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Attack invitation chance increased by 10%',
		zawakeSimpleDesc_en = 'Attack invitation chance increased by 10%',
		zawakeSimpleDesc_th = 'โอกาสเชิญโจมตีเพิ่มขึ้น 10%',
		zawakeSimpleDesc_in = 'Peluang mengundang serangan meningkat 10%',
		zawakeSimpleDesc_ph = 'Tumaas ng 10% ang tsansa ng imbitasyong atake',
		zawakeSimpleDesc_ma = 'Peluang menjemput serangan meningkat sebanyak 10%',
