		skillName_in = 'Pembaptisan Cahaya Suci',
		skillName_ph = 'Binyag ng Banal na Liwanag',
		skillName_ma = 'Pembaptisan Cahaya Suci',
		skillName = 'Holy Light Baptism',
		describe_vn = 'Belldandy triệu hồi ánh sáng thánh trừng phạt mục tiêu đơn lẻ của kẻ địch, gây #C0xE69900#130% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, tăng 35% phòng thủ vật lý của bản thân trong 2 lượt, và nhận một lá chắn bằng 400% phòng thủ vật lý trong 1 lượt',
		describe_en = 'Belldandy summons holy light to punish a single enemy target, dealing #C0xE69900#130% Physical Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#, increases self physical defense by 35% for 2 turns, and gains a shield equal to 400% physical defense for 1 turn.',
		describe_th = 'เบลดดี้ดี้ เรียกแสงศักดิ์สิทธิ์ลงโทษเป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0xE69900#130% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มการป้องกันทางกายภาพของตัวเอง 35% เป็นเวลา 2 เทิร์น และได้รับโล่เทียบเท่ากับการป้องกันทางกายภาพ 400% เป็นเวลา 1 เทิร์น',
		describe_in = 'Belldandy memanggil cahaya suci untuk menghukum satu target musuh, memberikan #C0xE69900#130% Serangan Fisik#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, meningkatkan pertahanan fisik sendiri sebesar 35% selama 2 giliran, dan menerima pelindung sebesar 400% pertahanan fisik selama 1 giliran.',
		describe_ph = 'Si Belldandy ay nag-summon ng banal na liwanag upang parusahan ang isang kalaban na target, na nagdudulot ng #C0xE69900#130% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Pinsalang Pisikal#C0x5B545B#, nagpapataas ng 35% pisikal na depensa ng sarili sa loob ng 2 turn, at tumatanggap ng isang kalasag na katumbas ng 400% pisikal na depensa sa loob ng 1 turn.',
		describe_ma = 'Belldandy memanggil cahaya suci untuk menghukum sasaran musuh tunggal, memberikan #C0xE69900#130% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, meningkatkan pertahanan fizikal diri sendiri sebanyak 35% selama 2 pusingan, dan menerima pelindung sebanyak 400% pertahanan fizikal selama 1 pusingan.',
		describe = 'Belldandy summons holy light to punish a single enemy target, dealing #C0xE69900#130% Physical Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#, increases self physical defense by 35% for 2 turns, and gains a shield equal to 400% physical defense for 1 turn.',
		simDesc_vn = 'Belldandy triệu hồi ánh sáng thánh phạt tấn công mục tiêu đơn lẻ của kẻ thù.',
		simDesc_en = 'Belldandy summons a holy light punishment to attack a single enemy target.',
		simDesc_th = 'เบลดดันดี้เรียกแสงศักดิ์สิทธิ์ลงโทษโจมตีเป้าหมายศัตรูเดี่ยว',
		simDesc_in = 'Belldandy memanggil cahaya suci hukuman untuk menyerang satu target musuh.',
		simDesc_ph = 'Tinatawag ni Belldandy ang banal na liwanag na parusa upang atakihin ang isang kalaban na target.',
		simDesc_ma = 'Belldandy memanggil cahaya suci hukuman untuk menyerang satu sasaran musuh.',
