	[31612] = {
		id = 31612,
		skillName_vn = 'Ánh sáng thánh tần số cao',
		skillName_en = 'High-frequency holy light',
		skillName_th = 'แสงศักดิ์สิทธิ์ความถี่สูง',
		skillName_in = 'Cahaya suci frekuensi tinggi',
		skillName_ph = 'Mataas na dalas na banal na liwanag',
		skillName_ma = 'Cahaya suci frekuensi tinggi',
		skillName = 'High-frequency holy light',
		describe_vn = 'Belldandy bao phủ mục tiêu đơn lẻ của kẻ địch bằng sóng âm thánh, thực hiện lễ rửa tội ánh sáng, gây #C0xE69900#200% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, khiến hai anh hùng đồng minh có lượng máu thấp nhất nhận một lá chắn bằng 350% phòng thủ vật lý, khi lá chắn bị phá vỡ sẽ gây sát thương bằng 150% phòng thủ vật lý của Belldandy lên toàn bộ kẻ địch, kéo dài 2 lượt',
		describe_en = 'Belldandy covers a single enemy target with holy sound waves, performing the light baptism, dealing #C0xE69900#200% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, causing the two allied heroes with the lowest health to receive a shield equal to 350% physical defense. When the shield breaks, it will deal damage equal to 150% of Belldandy\'s physical defense to all enemies, lasting 2 turns.',
		describe_th = 'Belldandy ปกป้องเป้าหมายศัตรูเดี่ยวด้วยคลื่นเสียงศักดิ์สิทธิ์ ทำพิธีล้างด้วยแสง สร้าง #C0xE69900#200% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ทำให้ฮีโร่พันธมิตรสองคนที่มีพลังชีวิตต่ำที่สุดได้รับโล่เท่ากับ 350% ของการป้องกันทางกายภาพ เมื่อโล่ถูกทำลายจะก่อให้เกิดความเสียหายเท่ากับ 150% ของการป้องกันทางกายภาพของ Belldandy แก่ศัตรูทั้งหมด มีผลอยู่ 2 เทิร์น',
		describe_in = 'Belldandy menutupi satu target musuh dengan gelombang suara suci, melaksanakan pembaptisan cahaya, memberikan #C0xE69900#200% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, menyebabkan dua pahlawan sekutu dengan HP terendah menerima perisai sebesar 350% pertahanan fisik. Ketika perisai rusak, akan memberikan kerusakan sebesar 150% pertahanan fisik Belldandy ke semua musuh, berlangsung selama 2 giliran.',
		describe_ph = 'Nilalapatan ni Belldandy ang isang target ng kalaban gamit ang banal na alon ng tunog, isinasagawa ang pagbibinyag ng liwanag, na nagdudulot ng #C0xE69900#200% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#, na nagpaparamdam sa dalawang kaalyadong bayani na may pinakamababang HP ng isang panangga na katumbas ng 350% pisikal na depensa. Kapag nabasag ang panangga, magdudulot ito ng pinsala na katumbas ng 150% ng pisikal na depensa ni Belldandy sa lahat ng kalaban, tumatagal ng 2 turn.',
		describe_ma = 'Belldandy menutupi satu sasaran musuh dengan gelombang bunyi suci, melaksanakan pembaptisan cahaya, memberikan #C0xE69900#200% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, menyebabkan dua wira sekutu dengan darah paling rendah menerima perisai sebesar 350% pertahanan fizikal. Apabila perisai pecah, ia akan menyebabkan kerosakan sebanyak 150% pertahanan fizikal Belldandy kepada semua musuh, berlangsung selama 2 pusingan.',
		describe = 'Belldandy covers a single enemy target with holy sound waves, performing the light baptism, dealing #C0xE69900#200% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, causing the two allied heroes with the lowest health to receive a shield equal to 350% physical defense. When the shield breaks, it will deal damage equal to 150% of Belldandy\'s physical defense to all enemies, lasting 2 turns.',
		simDesc_vn = 'Belldandy bao phủ mục tiêu đơn lẻ của kẻ thù bằng sóng âm thánh, thực hiện nghi thức thanh tẩy ánh sáng.',
		simDesc_en = 'Belldandy covers a single enemy target with holy sonic waves, performing the light purification ritual.',
		simDesc_th = 'เบลดดันดี้ปกป้องเป้าหมายศัตรูเดี่ยวด้วยคลื่นโซนิคศักดิ์สิทธิ์ ดำเนินพิธีชำระล้างด้วยแสงสว่าง',
		simDesc_in = 'Belldandy menutupi satu target musuh dengan gelombang suara suci, melaksanakan ritual penyucian cahaya.',
		simDesc_ph = 'Sinaklaw ni Belldandy ang isang target na kalaban ng banal na alon ng tunog, isinasagawa ang ritwal ng paglilinis ng liwanag.',
		simDesc_ma = 'Belldandy menutup satu sasaran musuh dengan gelombang bunyi suci, melaksanakan ritual penyucian cahaya.',
