	[31613] = {
		id = 31613,
		skillName_vn = 'Âm thanh chuông thánh',
		skillName_en = 'Holy bell sound',
		skillName_th = 'เสียงระฆังศักดิ์สิทธิ์',
		skillName_in = 'Suara lonceng suci',
		skillName_ph = 'Tunog ng banal na kampana',
		skillName_ma = 'Bunyi loceng suci',
		skillName = 'Holy bell sound',
		describe_vn = 'Belldandy đứng trên đỉnh núi nhìn xuống, triệu hồi ánh sáng thánh vô tận trừng phạt mục tiêu hàng sau của kẻ địch, gây #C0xE69900#250% Công Vật Lý#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, tăng 10% kháng chí mạng cho toàn bộ đồng minh trong 2 lượt (anh hùng dòng Thánh Kiếm Sĩ và cơ khí được tăng thêm 10%), và khiến toàn bộ đồng minh nhận một lá chắn bằng 350% phòng thủ vật lý của Belldandy, khi lá chắn bị phá vỡ sẽ gây sát thương bằng 150% phòng thủ vật lý của Belldandy lên toàn bộ kẻ địch, kéo dài 2 lượt',
		describe_en = 'Belldandy stands atop the mountain, summoning the endless holy light to punish the enemy\'s backline target, dealing #C0xE69900#250% Physical Attack#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#, increasing critical resistance for all allies by 10% for 2 turns (heroes of the Holy Swordsman and Mechanic classes gain an additional 10%), and granting all allies a shield equal to 350% of Belldandy\'s physical defense. When the shield breaks, it deals damage equal to 150% of Belldandy\'s physical defense to all enemies, lasting 2 turns.',
		describe_th = 'เบลดันดี้ยืนอยู่บนยอดเขา เรียกแสงศักดิ์สิทธิ์ที่ไม่มีที่สิ้นสุดลงมาลงโทษเป้าหมายแถวหลังของศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#250%#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มการต้านทานคริติคอลให้กับพันธมิตรทั้งหมด 10% เป็นเวลา 2 เทิร์น (ฮีโร่สาย นักดาบศักดิ์สิทธิ์ และกลไกเพิ่มขึ้นอีก 10%) และมอบโล่ให้กับพันธมิตรทั้งหมดเท่ากับ 350% ของการป้องกันกายภาพของเบลดันดี้ เมื่โล่ถูกทำลายจะสร้างความเสียหายเท่ากับ 150% ของการป้องกันกายภาพของเบลดันดี้ต่อศัตรูทั้งหมด มีผลนาน 2 เทิร์น',
		describe_in = 'Belldandy berdiri di puncak gunung, memanggil cahaya suci tanpa batas untuk menghukum target barisan belakang musuh, menghasilkan #C0xE69900#250% Serangan Fisik#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, meningkatkan ketahanan kritikal seluruh sekutu sebesar 10% selama 2 giliran (pahlawan kelas Pendekar Suci dan Mekanik mendapatkan tambahan 10%), dan memberikan seluruh sekutu sebuah perisai sebesar 350% pertahanan fisik Belldandy. Saat perisai hancur, akan memberikan kerusakan sebesar 150% pertahanan fisik Belldandy ke semua musuh, berlangsung selama 2 giliran.',
		describe_ph = 'Nakatayo si Belldandy sa tuktok ng bundok, nagpapatawag ng walang hanggang banal na liwanag upang parusahan ang target sa likurang hanay ng kalaban, na nagdudulot ng #C0xE69900#250% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#, nagpapataas ng 10% kritikal na resistensya para sa lahat ng mga kaalyado sa loob ng 2 turn (ang mga bayani mula sa linya ng Banal na Mandirigma at Mekaniko ay tumatanggap ng dagdag na 10%), at nagbibigay sa lahat ng mga kaalyado ng isang kalasag na katumbas ng 350% ng pisikal na depensa ni Belldandy. Kapag nabasag ang kalasag, nagdudulot ito ng pinsala na katumbas ng 150% ng pisikal na depensa ni Belldandy sa lahat ng kalaban, tumatagal ng 2 turn.',
		describe_ma = 'Belldandy berdiri di puncak gunung, memanggil cahaya suci yang tiada berakhir untuk menghukum sasaran barisan belakang musuh, menyebabkan #C0xE69900#250% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, meningkatkan ketahanan kritikal untuk semua sekutu sebanyak 10% selama 2 pusingan (wira kelas Pendekar Suci dan Mekanikal mendapat tambahan 10%), dan memberikan semua sekutu perisai bersamaan dengan 350% pertahanan fizikal Belldandy. Apabila perisai dipecahkan, ia akan menyebabkan kerosakan bersamaan 150% pertahanan fizikal Belldandy kepada semua musuh, berlanjutan selama 2 pusingan.',
		describe = 'Belldandy stands atop the mountain, summoning the endless holy light to punish the enemy\'s backline target, dealing #C0xE69900#250% Physical Attack#C0x5B545B# + $(skillLevel*4*75)$ #C0xF13B54#Physical Damage#C0x5B545B#, increasing critical resistance for all allies by 10% for 2 turns (heroes of the Holy Swordsman and Mechanic classes gain an additional 10%), and granting all allies a shield equal to 350% of Belldandy\'s physical defense. When the shield breaks, it deals damage equal to 150% of Belldandy\'s physical defense to all enemies, lasting 2 turns.',
		simDesc_vn = 'Belldandy đứng trên đỉnh núi, triệu hồi vô số ánh sáng thánh tấn công mục tiêu ở hàng sau của kẻ thù, tăng cường kháng sát thương chí mạng cho toàn bộ đồng đội và tạo cho toàn bộ đồng đội một lá chắn. Khi lá chắn bị phá vỡ, sẽ gây ra một phần sát thương cho toàn bộ kẻ thù.',
		simDesc_en = 'Belldandy stands atop the mountain, summoning countless holy lights to attack the enemies in the back row, enhancing critical damage resistance for all allies and granting a shield to the entire team. When the shield breaks, it deals a portion of damage to all enemies.',
		simDesc_th = 'เบลดันดี้ยืนอยู่บนยอดเขา เรียกแสงศักดิ์สิทธิ์นับไม่ถ้วนโจมตีเป้าหมายแถวหลังของศัตรู เพิ่มความต้านทานความเสียหายคริติคอลให้กับเพื่อนร่วมทีมทั้งหมด และมอบโล่ให้กับเพื่อนร่วมทีมทั้งหมด เมื่อโล่แตก จะสร้างความเสียหายส่วนหนึ่งแก่ศัตรูทั้งหมด',
		simDesc_in = 'Belldandy berdiri di puncak gunung, memanggil cahaya suci yang tak terhitung jumlahnya untuk menyerang target di barisan belakang musuh, meningkatkan ketahanan terhadap kerusakan kritis untuk seluruh tim, dan memberikan perisai kepada seluruh anggota tim. Ketika perisai hancur, itu akan memberikan sebagian kerusakan pada semua musuh.',
		simDesc_ph = 'Nakatindig si Belldandy sa tuktok ng bundok, nag-summon ng napakaraming banal na liwanag upang atakihin ang mga target sa likurang hanay ng mga kalaban, pinapalakas ang resistensya laban sa kritikal na pinsala para sa lahat ng kakampi, at nagbibigay ng isang shield sa buong koponan. Kapag nabasag ang shield, magdudulot ito ng bahagi ng pinsala sa lahat ng kalaban.',
		simDesc_ma = 'Belldandy berdiri di puncak gunung, memanggil cahaya suci yang tidak terhitung untuk menyerang sasaran di barisan belakang musuh, meningkatkan ketahanan terhadap kerosakan kritikal kepada semua rakan sepasukan dan memberikan perisai kepada semua rakan sepasukan. Apabila perisai pecah, ia akan menyebabkan sebahagian kerosakan kepada semua musuh.',
		simDesc = 'Belldandy stands atop the mountain, summoning countless holy lights to attack the enemies in the back row, enhancing critical damage resistance for all allies and granting a shield to the entire team. When the shield breaks, it deals a portion of damage to all enemies.',
		starEffect = __data_t__starEffect[31613],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Trong 2 lượt, khi đồng minh tấn công sẽ gây thêm Sát Thương Vật Lý bằng giá trị lá chắn hiện tại (tối đa không vượt quá 500% phòng thủ vật lý của Bé Lộ Đan Tì).',
		starEffectDesc = 'Additional effect: For 2 turns, when allies attack, they will deal extra Physical Damage equal to the current shield value (maximum not exceeding 500% of Bé Lộ Đan Tì\'s physical defense).',
		starEffectDesc_en = 'Additional effect: For 2 turns, when allies attack, they will deal extra Physical Damage equal to the current shield value (maximum not exceeding 500% of Bé Lộ Đan Tì\'s physical defense).',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ภายใน 2 เทิร์น การโจมตีของฝ่ายเราจะสร้างความเสียหายกายภาพเพิ่มเติมเท่ากับค่าพลังโล่ปัจจุบัน (ไม่เกิน 500% ของพลังป้องกันกายภาพของเบลล์แดนดี้)',
		starEffectDesc_in = 'Efek tambahan: Selama 2 giliran, ketika sekutu menyerang akan memberikan kerusakan fisik tambahan sebesar nilai perisai saat ini (maksimal tidak melebihi 500% pertahanan fisik Bé Lộ Đan Tì).',
		starEffectDesc_ph = 'Karagdagang epekto: Sa loob ng 2 turn, kapag umatake ang mga kaalyado, magdudulot sila ng karagdagang Pisikal na Pinsala base sa kasalukuyang halaga ng panangga (hindi lalagpas sa 500% ng pisikal na depensa ni Bé Lộ Đan Tì).',
		starEffectDesc_ma = 'Kesan tambahan: Dalam 2 pusingan, apabila sekutu menyerang akan menyebabkan Kerusakan Fizikal tambahan berdasarkan nilai perisai semasa (maksimum tidak melebihi 500% pertahanan fizikal Bé Lộ Đan Tì).',
		upLvDesc = 'Fixed damage +300',
