	[31616] = {
		id = 31616,
		skillName_vn = 'Đấm bóng ảnh',
		skillName_en = 'Punching bag image',
		skillName_th = 'ภาพกระสอบทราย',
		skillName_in = 'Gambar bola tinju',
		skillName_ph = 'Larawan ng punching ball',
		skillName_ma = 'Imej bola tinju',
		skillName = 'Punching bag image',
		describe_vn = 'Kỹ năng hào quang: Khi bất kỳ đồng minh nào ngoài bản thân có tỷ lệ máu dưới 30%, ngay lập tức thêm một lá chắn bằng lượng máu đã mất của mục tiêu, kéo dài 2 lượt, hiệu ứng hồi sau 2 lượt lớn\nGiảm sát thương chí mạng của toàn bộ kẻ địch #C0x5c9970#$(5+skillLevel*0.02-0.02)$%#C0x5B545B# (hiệu quả gấp đôi với anh hùng hệ Bóng Tối)',
		describe_en = 'Aura Skill: When any ally other than yourself has health below 30%, immediately add a shield equal to the health lost by the target, lasting 2 turns, effect recovers after 2 turns. Reduces critical damage received by all enemies by #C0x5c9970#$(5+skillLevel*0.02-0.02)$%#C0x5B545B# (effect doubles for Dark-type heroes).',
		describe_th = 'ทักษะออร่า: เมื่อพันธมิตรรายใดที่ไม่ใช่ตัวคุณมีพลังชีวิตต่ำกว่า 30% จะเพิ่มโล่ให้เท่ากับพลังชีวิตที่สูญเสียของเป้าหมายทันที เป็นเวลา 2 เทิร์น และมีผลฟื้นฟูหลังจากครบ 2 เทิร์น ลดความเสียหายคริติคอลของศัตรูทั้งหมดลง #C0x5c9970#$(5+skillLevel*0.02-0.02)$%#C0x5B545B# (มีผลคูณสองกับฮีโร่ประเภทมืด)',
		describe_in = 'Keterampilan Aura: Ketika sekutu manapun selain diri sendiri memiliki persentase HP di bawah 30%, segera tambahkan sebuah perisai sebesar HP yang hilang dari target, berlangsung selama 2 giliran, efek pulih setelah 2 giliran. Mengurangi kerusakan kritis semua musuh sebesar #C0x5c9970#$(5+skillLevel*0.02-0.02)$%#C0x5B545B# (efek dua kali lipat untuk pahlawan tipe Kegelapan).',
		describe_ph = 'Kasanayan ng Aura: Kapag ang alinmang kakampi maliban sa iyong sarili ay may HP na mas mababa sa 30%, agad na magdagdag ng isang panangga na katumbas ng nawalang HP ng target, tumatagal ng 2 turn, epekto ay bumabalik pagkatapos ng 2 turn. Binabawasan ang kritikal na pinsala ng lahat ng mga kalaban ng #C0x5c9970#$(5+skillLevel*0.02-0.02)$%#C0x5B545B# (doble ang epekto para sa mga bayani ng Uri ng Kadiliman).',
		describe_ma = 'Kemahiran Aura: Apabila mana-mana sekutu selain diri sendiri mempunyai peratusan kesihatan di bawah 30%, secara serta-merta menambah perisai bersamaan jumlah kesihatan yang hilang oleh sasaran, bertahan selama 2 pusingan, kesan pemulihan selepas 2 pusingan. Mengurangkan kerosakan kritikal semua musuh sebanyak #C0x5c9970#$(5+skillLevel*0.02-0.02)$%#C0x5B545B# (kesan berganda untuk wira jenis Gelap).',
		describe = 'Aura Skill: When any ally other than yourself has health below 30%, immediately add a shield equal to the health lost by the target, lasting 2 turns, effect recovers after 2 turns. Reduces critical damage received by all enemies by #C0x5c9970#$(5+skillLevel*0.02-0.02)$%#C0x5B545B# (effect doubles for Dark-type heroes).',
		starEffect = __data_t__starEffect[31616],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi vòng đời của lá chắn do Bé Lộ Đan Tì tạo ra kết thúc, nếu lá chắn chưa bị phá vỡ, thì hồi phục cho mục tiêu 180% phòng thủ vật lý của Bé Lộ Đan Tì.',
		starEffectDesc = 'Additional Effect: When the shield created by Bé Lộ Đan Tì\'s lifecycle ends, if the shield is not broken, it restores 180% of Bé Lộ Đan Tì\'s physical defense to the target.',
		starEffectDesc_en = 'Additional Effect: When the shield created by Bé Lộ Đan Tì\'s lifecycle ends, if the shield is not broken, it restores 180% of Bé Lộ Đan Tì\'s physical defense to the target.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อลโล่ที่เบลล์แดนดี้สร้างขึ้นสิ้นสุดระยะเวลา หากโล่ไม่ถูกทำลาย จะฟื้นฟูพลังชีวิตให้เป้าหมายเท่ากับ 180% ของพลังป้องกันกายภาพของเบลล์แดนดี้',
		starEffectDesc_in = 'Efek Tambahan: Ketika siklus hidup perisai yang dibuat oleh Bé Lộ Đan Tì berakhir, jika perisai belum hancur, maka akan memulihkan 180% pertahanan fisik Bé Lộ Đan Tì untuk target.',
