	[31721] = {
		id = 31721,
		skillName_vn = 'Cú Đấm Rồng',
		skillName_en = 'Dragon Fist',
		skillName_th = 'หมัดมังกร',
		skillName_in = 'Pukulan Naga',
		skillName_ph = 'Suntok ng Dragon',
		skillName_ma = 'Tumbukan Naga',
		skillName = 'Dragon Fist',
		describe_vn = 'Goku dồn tung ra một cú đấm mang theo luồng năng lượng bùng nổ, tạo thành một sóng xung kích xuyên phá hàng dọc kẻ thù. #C0xE69900#160% Công V.Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, và tăng 20% Công V.Lý ban đầu, kéo dài 2 lượt. Nếu đòn đánh vượt quá 30% HP tối đa của mục tiêu, kẻ địch sẽ bị choáng trong 1 lượt.',
		describe_en = 'Goku unleashes a powerful punch infused with explosive energy, creating a shockwave that pierces through enemy rows. Deals #C0xE69900#160% Physical ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#, and increases base Physical ATK by 20% for 2 turns. If the attack exceeds 30% of the target\'s Max HP, the enemy will be stunned for 1 turn',
		describe_th = 'โกคูปล่อยหมัดพลังมหาศาลที่อัดแน่นด้วยพลังระเบิด สร้างคลื่นกระแทกทะลวงศัตรูในแนวตั้ง สร้างความเสียหาย #C0xE69900#160% กายภาพ#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# และเพิ่มพลังโจมตีกายภาพพื้นฐาน 20% เป็นเวลา 2 เทิร์น หากความเสียหายเกิน 30% HP สูงสุดของเป้าหมาย ศัตรูจะถูกสตั้นเป็นเวลา 1 เทิร์น',
		describe_in = 'Goku melancarkan pukulan dahsyat dengan energi ledakan, menciptakan gelombang kejut yang menembus barisan musuh. Memberikan #C0xE69900#160% ATK Fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Damage Fisik#C0x5B545B#, serta meningkatkan 20% ATK Fisik dasar selama 2 giliran. Jika serangan melebihi 30% HP Maks target, musuh akan terkena stun selama 1 giliran',
		describe_ph = 'Si Goku ay naglalabas ng isang malakas na suntok na may kasamang sumasabog na enerhiya, lumilikha ng shockwave na tumatagos sa linya ng mga kalaban. Nagdudulot ng #C0xE69900#160% Physical ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#, at tumataas ng 20% ang base Physical ATK sa loob ng 2 turn. Kung ang atake ay lumampas sa 30% ng Max HP ng kalaban, ito ay ma-stun ng 1 turn',
		describe_ma = 'Goku melepaskan tumbukan bertenaga yang dipenuhi dengan tenaga letupan, menghasilkan gelombang kejut yang menembusi barisan musuh. Memberikan #C0xE69900#160% ATK Fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Damage Fizikal#C0x5B545B#, serta meningkatkan 20% ATK Fizikal asas selama 2 giliran. Jika serangan melebihi 30% HP Maks sasaran, musuh akan terkena stun selama 1 giliran',
		describe = 'Goku unleashes a powerful punch infused with explosive energy, creating a shockwave that pierces through enemy rows. Deals #C0xE69900#160% Physical ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#, and increases base Physical ATK by 20% for 2 turns. If the attack exceeds 30% of the target\'s Max HP, the enemy will be stunned for 1 turn',
		simDesc = 'Goku dồn sức tung ra một cú đấm mang theo luồng năng lượng bùng nổ, tạo thành sóng xung kích xuyên phá hàng dọc kẻ thù. Gây sát thương vật lý và tăng 20% Công V.Lý trong 2 lượt. Nếu đòn đánh vượt quá 30% HP tối đa của mục tiêu, kẻ địch bị choáng 1 lượt',
		zawakeEffect = __data_t__zawakeEffect[31721],
		-- {79001}
		zawakeEffectDesc = 'Goku dồn tung ra một cú đấm mang theo luồng năng lượng bùng nổ, tạo thành một sóng xung kích xuyên phá hàng dọc kẻ thù. #C0xE69900#160% Công V.Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, và tăng 20% Công V.Lý ban đầu, kéo dài 2 lượt. Nếu đòn đánh vượt quá 20% HP tối đa của mục tiêu, kẻ địch sẽ bị choáng trong 1 lượt.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'If the attack exceeds 30% of the target\'s Max HP, the enemy will be stunned for 1 turn. \n#F20# \n#F40##C0x5c9970#→ If the attack exceeds 20% of the target\'s Max HP, the enemy will be stunned for 1 turn.',
		zawakeSimpleDesc_en = 'If the attack exceeds 30% of the target\'s Max HP, the enemy will be stunned for 1 turn. \n#F20# \n#F40##C0x5c9970#→ If the attack exceeds 20% of the target\'s Max HP, the enemy will be stunned for 1 turn.',
		zawakeSimpleDesc_th = 'หากการโจมตีเกิน 30% ของ HP สูงสุดของเป้าหมาย ศัตรูจะถูกสตันเป็นเวลา 1 เทิร์น \n#F20# \n#F40##C0x5c9970#→ หากการโจมตีเกิน 20% ของ HP สูงสุดของเป้าหมาย ศัตรูจะถูกสตันเป็นเวลา 1 เทิร์น',
		zawakeSimpleDesc_in = 'Jika serangan melebihi 30% dari HP Maks target, musuh akan terkena stun selama 1 giliran. \n#F20# \n#F40##C0x5c9970#→ Jika serangan melebihi 20% dari HP Maks target, musuh akan terkena stun selama 1 giliran.',
		zawakeSimpleDesc_ph = 'Kung ang atake ay lumampas sa 30% ng Max HP ng target, ang kalaban ay ma-stun ng 1 turn. \n#F20# \n#F40##C0x5c9970#→ Kung ang atake ay lumampas sa 20% ng Max HP ng target, ang kalaban ay ma-stun ng 1 turn.',
		zawakeSimpleDesc_ma = 'Jika serangan melebihi 30% daripada HP Maks sasaran, musuh akan terkena stun selama 1 giliran. \n#F20# \n#F40##C0x5c9970#→ Jika serangan melebihi 20% daripada HP Maks sasaran, musuh akan terkena stun selama 1 giliran.',
		zawakeSimpleDesc_vn = 'Nếu đòn đánh vượt quá 30% HP tối đa của mục tiêu, kẻ địch sẽ bị choáng trong 1 lượt. \n#F20# \n#F40##C0x5c9970#→ Nếu đòn đánh vượt quá 20% HP tối đa của mục tiêu, kẻ địch sẽ bị choáng trong 1 lượt.',
		iconRes = 'battle/skill_icon/skill_31721.png',
		changeUnitTrigger = true,
		isCombat = true,
