	[31722] = {
		id = 31722,
		skillName_vn = 'Quả Cầu Nguyên Khí',
		skillName_en = 'Spirit Bomb',
		skillName_th = 'ลูกบอลพลังวิญญาณ',
		skillName_in = 'Bola Roh',
		skillName_ph = 'Bomba ng Enerhiya',
		skillName_ma = 'Bom Roh',
		skillName = 'Spirit Bomb',
		describe_vn = 'Goku triệu hồi sức mạnh từ tất cả đồng đội xung quanh tích tụ thành một Quả Cầu Nguyên Khí khổng lồ, rực sáng cả bầu trời, được Goku ném ra với toàn bộ sức mạnh của mình xuyên phá hàng dọc kẻ thù, gây #C0xE69900#240% Công V.Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#. Sau khi tung chiêu, Goku bước vào trạng thái hưng phấn chiến đấu: Tăng 20% tỷ lệ hút máu trong 2 lượt, giúp hồi phục mạnh mẽ từ sát thương gây ra. Nếu đòn đánh vượt quá 20% HP tối đa của mục tiêu, kẻ địch sẽ bị choáng trong 1 lượt. Goku đồng thời nhận thêm 15% khả năng né tránh và 20% kháng hiệu ứng trong 2 lượt, nâng cao khả năng sinh tồn khi bước vào giao tranh ác liệt.',
		describe_en = 'Goku summons the power of all nearby allies, condensing it into a massive Spirit Bomb that lights up the entire sky, hurling it with full force to pierce through the enemy’s vertical row, dealing #C0xE69900#240% Physical ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#. After casting, Goku enters a battle frenzy state: increases Lifesteal Rate by 20% for 2 turns, greatly restoring HP from damage dealt. If the attack exceeds 20% of the target’s Max HP, the enemy will be stunned for 1 turn. Goku also gains +15% Dodge and +20% Debuff Resistance for 2 turns, enhancing survivability in fierce combat',
		describe_th = 'โกคูรวบรวมพลังจากเพื่อนร่วมทีมทั้งหมด กลั่นรวมเป็นลูกพลังวิญญาณขนาดมหึมาที่ส่องสว่างไปทั่วท้องฟ้า ปล่อยออกไปด้วยพลังทั้งหมด ทะลวงแนวตั้งของศัตรู สร้างความเสียหาย #C0xE69900#240% กายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B#. หลังใช้ท่า โกคูเข้าสู่สภาวะต่อสู้อย่างคลั่ง: เพิ่มอัตราดูดเลือด 20% เป็นเวลา 2 เทิร์น ฟื้นฟูพลังชีวิตจากความเสียหายที่ทำได้อย่างมหาศาล หากการโจมตีเกินกว่า 20% ของ HP สูงสุดของเป้าหมาย ศัตรูจะติดสตัน 1 เทิร์น นอกจากนี้ โกคูยังได้รับการหลบหลีก +15% และต้านทานดีบัฟ +20% เป็นเวลา 2 เทิร์น เพิ่มความอยู่รอดในการต่อสู้อันดุเดือด',
		describe_in = 'Goku memanggil kekuatan dari semua rekan tim di sekitarnya, memadatkannya menjadi sebuah Spirit Bomb raksasa yang menerangi seluruh langit, melemparkannya dengan kekuatan penuh untuk menembus barisan vertikal musuh, memberikan #C0xE69900#240% ATK Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Damage Fisik#C0x5B545B#. Setelah melancarkan skill, Goku memasuki keadaan pertempuran bersemangat: meningkatkan Lifesteal Rate sebesar 20% selama 2 giliran, memulihkan HP secara besar dari damage yang diberikan. Jika serangan melebihi 20% HP Maks target, musuh akan terkena stun selama 1 giliran. Goku juga memperoleh +15% Dodge dan +20% Resistensi Debuff selama 2 giliran, meningkatkan daya tahan saat pertempuran sengit',
		describe_ph = 'Si Goku ay tumatawag ng lakas mula sa lahat ng kakampi sa paligid at pinagsasanib ito sa isang napakalaking Spirit Bomb na nagliliwanag sa buong kalangitan, ibinabato ito nang buong lakas upang butasin ang vertical row ng mga kalaban, nagdudulot ng #C0xE69900#240% Physical ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Pagkatapos gamitin, pumapasok si Goku sa estado ng labang sabik: +20% Lifesteal Rate sa loob ng 2 turn, nagbibigay ng malakas na paghilom mula sa pinsalang nagawa. Kung ang atake ay lumampas sa 20% ng Max HP ng target, ang kalaban ay mai-stun ng 1 turn. Kasabay nito, nakakatanggap si Goku ng +15% Dodge at +20% Debuff Resistance sa loob ng 2 turn, pinapataas ang survival sa matinding laban',
		describe_ma = 'Goku memanggil kuasa daripada semua rakan sepasukan di sekeliling, memekatkannya menjadi Spirit Bomb gergasi yang menerangi seluruh langit, melemparkannya dengan sepenuh tenaga untuk menembusi barisan menegak musuh, memberikan #C0xE69900#240% ATK Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerusakan Fizikal#C0x5B545B#. Selepas melancarkan, Goku memasuki keadaan ghairah pertempuran: meningkatkan Kadar Lifesteal sebanyak 20% selama 2 giliran, memulihkan HP dengan kuat dari kerosakan yang diberikan. Jika serangan melebihi 20% daripada HP Maks sasaran, musuh akan terkena stun selama 1 giliran. Goku juga menerima +15% Elakan dan +20% Rintangan Debuff selama 2 giliran, meningkatkan kelangsungan hidup ketika pertarungan sengit',
		describe = 'Goku summons the power of all nearby allies, condensing it into a massive Spirit Bomb that lights up the entire sky, hurling it with full force to pierce through the enemy’s vertical row, dealing #C0xE69900#240% Physical ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#. After casting, Goku enters a battle frenzy state: increases Lifesteal Rate by 20% for 2 turns, greatly restoring HP from damage dealt. If the attack exceeds 20% of the target’s Max HP, the enemy will be stunned for 1 turn. Goku also gains +15% Dodge and +20% Debuff Resistance for 2 turns, enhancing survivability in fierce combat',
		simDesc = 'Goku triệu hồi sức mạnh từ tất cả đồng đội, tích tụ thành Quả Cầu Nguyên Khí khổng lồ rực sáng cả bầu trời, rồi ném ra xuyên phá hàng dọc kẻ thù, gây sát thương vật lý. Sau khi tung chiêu, Goku bước vào trạng thái hưng phấn chiến đấu: Tăng 20% tỷ lệ hút máu trong 2 lượt, giúp hồi phục từ sát thương gây ra. Nếu đòn đánh vượt quá 20% HP tối đa của mục tiêu, kẻ địch bị choáng 1 lượt. Đồng thời, Goku nhận thêm 15% né tránh và 20% kháng hiệu ứng trong 2 lượt, nâng cao khả năng sinh tồn',
		zawakeEffect = __data_t__zawakeEffect[31722],
		-- {79002}
		zawakeEffectDesc = 'Goku triệu hồi sức mạnh từ tất cả đồng đội xung quanh tích tụ thành một Quả Cầu Nguyên Khí khổng lồ, rực sáng cả bầu trời, được Goku ném ra với toàn bộ sức mạnh của mình xuyên phá hàng dọc kẻ thù, gây #C0xE69900#240% Công V.Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#. Sau khi tung chiêu, Goku bước vào trạng thái hưng phấn chiến đấu: Tăng 20% tỷ lệ hút máu trong 2 lượt, giúp hồi phục mạnh mẽ từ sát thương gây ra. Nếu đòn đánh vượt quá 10% HP tối đa của mục tiêu, kẻ địch sẽ bị choáng trong 1 lượt. Goku đồng thời nhận thêm 15% khả năng né tránh và 20% kháng hiệu ứng trong 2 lượt, nâng cao khả năng sinh tồn khi bước vào giao tranh ác liệt.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'If the attack exceeds 20% of the target\'s Max HP, the enemy will be stunned for 1 turn. \n#F20# \n#F40##C0x5c9970#→ If the attack exceeds 10% of the target\'s Max HP, the enemy will be stunned for 1 turn.',
		zawakeSimpleDesc_en = 'If the attack exceeds 20% of the target\'s Max HP, the enemy will be stunned for 1 turn. \n#F20# \n#F40##C0x5c9970#→ If the attack exceeds 10% of the target\'s Max HP, the enemy will be stunned for 1 turn.',
		zawakeSimpleDesc_th = 'หากการโจมตีเกิน 20% ของ HP สูงสุดของเป้าหมาย ศัตรูจะถูกสตันเป็นเวลา 1 เทิร์น \n#F20# \n#F40##C0x5c9970#→ หากการโจมตีเกิน 10% ของ HP สูงสุดของเป้าหมาย ศัตรูจะถูกสตันเป็นเวลา 1 เทิร์น',
		zawakeSimpleDesc_in = 'Jika serangan melebihi 20% dari HP Maks target, musuh akan terkena stun selama 1 giliran. \n#F20# \n#F40##C0x5c9970#→ Jika serangan melebihi 10% dari HP Maks target, musuh akan terkena stun selama 1 giliran.',
		zawakeSimpleDesc_ph = 'Kung ang atake ay lumampas sa 20% ng Max HP ng target, ang kalaban ay ma-stun ng 1 turn. \n#F20# \n#F40##C0x5c9970#→ Kung ang atake ay lumampas sa 10% ng Max HP ng target, ang kalaban ay ma-stun ng 1 turn.',
		zawakeSimpleDesc_ma = 'Jika serangan melebihi 20% daripada HP Maks sasaran, musuh akan terkena stun selama 1 giliran. \n#F20# \n#F40##C0x5c9970#→ Jika serangan melebihi 10% daripada HP Maks sasaran, musuh akan terkena stun selama 1 giliran.',
		zawakeSimpleDesc_vn = 'Nếu đòn đánh vượt quá 20% HP tối đa của mục tiêu, kẻ địch sẽ bị choáng trong 1 lượt. \n#F20# \n#F40##C0x5c9970#→ Nếu đòn đánh vượt quá 10% HP tối đa của mục tiêu, kẻ địch sẽ bị choáng trong 1 lượt.',
