	[31723] = {
		id = 31723,
		skillName_vn = 'Super Kamehameha',
		skillName_en = 'Super Kamehameha',
		skillName_th = 'ซูเปอร์คาเมฮาเมฮา',
		skillName_in = 'Super Kamehameha',
		skillName_ph = 'Super Kamehameha',
		skillName_ma = 'Super Kamehameha',
		skillName = 'Super Kamehameha',
		describe_vn = 'Goku lao vào giữa đội hình kẻ địch như một cơn lốc thần thánh, tung ra những cú đấm bạo liệt nghiền nát hàng ngũ đối phương, khiến cả chiến trường rung chuyển. Ngay sau đó, anh dồn toàn bộ khí lực giải phóng tuyệt kỹ huyền thoại Super Kamehameha, gây #C0xE69900#350% Công V.Lý#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#. Trong lần tấn công tối thượng này, Goku bước vào trạng thái bùng nổ sức mạnh tột độ tăng 20% Công V.Lý, 20% Tỉ lệ chí mạng, 20% Sát thương chí mạng. Sau khi kết thúc kĩ năng Goku nhận 15% khả năng né tránh và 20% kháng hiệu ứng trong 2 lượt.',
		describe_en = 'Goku charges into the enemy formation like a divine storm, unleashing furious punches that shatter the opposing ranks, shaking the entire battlefield. Immediately after, he gathers all his energy to release the legendary Super Kamehameha, dealing #C0xE69900#350% Physical ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical DMG#C0x5B545B#. During this ultimate strike, Goku enters an overwhelming power burst state, gaining +20% Physical ATK, +20% Critical Rate, and +20% Critical DMG. After the skill ends, Goku gains +15% Dodge and +20% Effect Resistance for 2 turns',
		describe_th = 'โกคูพุ่งเข้าไปกลางกองทัพศัตรูราวกับพายุศักดิ์สิทธิ์ ปล่อยหมัดรุนแรงบดขยี้แนวหน้าศัตรูจนทั้งสนามรบสั่นสะเทือน จากนั้นเขารวบรวมพลังทั้งหมดเพื่อปลดปล่อยท่าไม้ตายในตำนาน ซูเปอร์คาเมฮาเมฮา สร้างความเสียหาย #C0xE69900#350% กายภาพ#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#ดาเมจกายภาพ#C0x5B545B# ในการโจมตีสูงสุดครั้งนี้ โกคูเข้าสู่สภาวะระเบิดพลังขั้นสุด เพิ่มพลังโจมตีกายภาพ 20% อัตราคริติคอล 20% และดาเมจคริติคอล 20% หลังจบทักษะ โกคูได้รับโอกาสหลบหลีก 15% และต้านทานสถานะ 20% เป็นเวลา 2 เทิร์น',
		describe_in = 'Goku menerjang ke tengah formasi musuh seperti badai ilahi, melancarkan pukulan ganas yang menghancurkan barisan lawan hingga seluruh medan perang bergetar. Segera setelah itu, ia mengerahkan seluruh energinya untuk melepaskan jurus legendaris Super Kamehameha, memberikan #C0xE69900#350% ATK Fisik#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#DMG Fisik#C0x5B545B#. Dalam serangan pamungkas ini, Goku memasuki keadaan ledakan kekuatan penuh, mendapatkan +20% ATK Fisik, +20% Peluang Crit, dan +20% DMG Crit. Setelah skill berakhir, Goku mendapatkan +15% Dodge dan +20% Resistensi Efek selama 2 giliran',
		describe_ph = 'Sumugod si Goku sa gitna ng hanay ng kalaban na parang isang banal na bagyo, ibinagsak ang malalakas na suntok na nagdurog sa kanilang linya, yumanig ang buong labanan. Kaagad pagkatapos, ibinuhos niya ang lahat ng kanyang enerhiya upang ilabas ang alamat na Super Kamehameha, na nagdudulot ng #C0xE69900#350% Pisikal na ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Pisikal na DMG#C0x5B545B#. Sa ultimong atake na ito, pumasok si Goku sa isang estado ng matinding pagsabog ng lakas, tumataas ng +20% Pisikal na ATK, +20% Critical Rate, at +20% Critical DMG. Pagkatapos ng kasanayan, nakakakuha si Goku ng +15% Dodge at +20% Effect Resistance sa loob ng 2 turn',
		describe_ma = 'Goku menerjah ke tengah barisan musuh seperti ribut suci, melepaskan tumbukan dahsyat yang menghancurkan pertahanan musuh sehingga seluruh medan perang bergetar. Selepas itu, dia menumpukan semua tenaga untuk melepaskan teknik lagenda Super Kamehameha, memberikan #C0xE69900#350% ATK Fizikal#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#DMG Fizikal#C0x5B545B#. Dalam serangan muktamad ini, Goku memasuki keadaan letupan kuasa maksimum, memperoleh +20% ATK Fizikal, +20% Kadar Kritikal, dan +20% DMG Kritikal. Selepas kemahiran berakhir, Goku memperoleh +15% Elak dan +20% Rintangan Kesan selama 2 giliran',
		describe = 'Goku charges into the enemy formation like a divine storm, unleashing furious punches that shatter the opposing ranks, shaking the entire battlefield. Immediately after, he gathers all his energy to release the legendary Super Kamehameha, dealing #C0xE69900#350% Physical ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical DMG#C0x5B545B#. During this ultimate strike, Goku enters an overwhelming power burst state, gaining +20% Physical ATK, +20% Critical Rate, and +20% Critical DMG. After the skill ends, Goku gains +15% Dodge and +20% Effect Resistance for 2 turns',
		simDesc = 'Goku lao vào giữa đội hình kẻ địch như một cơn lốc, tung ra những cú đấm bạo liệt nghiền nát hàng ngũ đối phương, rồi dồn toàn bộ khí lực giải phóng tuyệt kỹ Super Kamehameha, gây sát thương vật lý cực lớn. Trong lần tấn công tối thượng này, Goku bước vào trạng thái bùng nổ sức mạnh: tăng 30% Công V.Lý, 30% Tỷ lệ chí mạng và 30% Sát thương chí mạng. Sau khi kết thúc kỹ năng, anh nhận thêm 15% né tránh và 20% kháng hiệu ứng trong 2 lượt.',
		starEffect = __data_t__starEffect[31723],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng tăng cường: Tăng mạnh khả năng bùng nổ của Goku: Trạng thái bùng nổ sức mạnh tột độ tăng 25% Công V.Lý, 25% Tỉ lệ chí mạng, 25% Sát thương chí mạng trong lần tấn công này.',
		starEffectDesc = 'Enhancement Effect: Greatly boosts Goku’s explosive power: The ultimate power burst state increases 25% Physical Attack, 25% Critical Rate, and 25% Critical Damage in this attack',
		starEffectDesc_en = 'Enhancement Effect: Greatly boosts Goku’s explosive power: The ultimate power burst state increases 25% Physical Attack, 25% Critical Rate, and 25% Critical Damage in this attack',
		starEffectDesc_th = 'เอฟเฟกต์เสริมพลัง: เพิ่มพลังระเบิดของโกคูอย่างมาก: สภาวะระเบิดพลังสูงสุดเพิ่มพลังโจมตีกายภาพ 25% อัตราคริ 25% และดาเมจคริ 25% ในการโจมตีครั้งนี้',
		starEffectDesc_in = 'Efek Peningkatan: Meningkatkan ledakan kekuatan Goku secara besar: Keadaan ledakan kekuatan tertinggi meningkatkan 25% Serangan Fisik, 25% Critical Rate, dan 25% Critical Damage pada serangan ini',
		starEffectDesc_ph = 'Epekto ng Pagpapalakas: Malaking pinapataas ang lakas ng pagsabog ni Goku: Sa estado ng sukdulang lakas, tumataas ng 25% Physical Attack, 25% Critical Rate, at 25% Critical Damage sa atakeng ito',
		starEffectDesc_ma = 'Kesan Peningkatan: Meningkatkan secara besar kuasa letupan Goku: Keadaan letupan kuasa tertinggi menambah 25% Serangan Fizikal, 25% Kadar Kritikal, dan 25% Kerosakan Kritikal dalam serangan ini',
		zawakeEffect = __data_t__zawakeEffect[31723],
