		skillName_in = 'Bunuh',
		skillName_ph = 'Patayin',
		skillName_ma = 'Bunuh',
		skillName = 'Defeat',
		describe_vn = 'Zenyatta phóng những viên bi cơ học để tấn công một mục tiêu kẻ địch, gây ra #C0x3D8A99#120% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, đồng thời tăng phòng thủ phép thuật của bản thân thêm 50% và tấn Công Phép thuật thêm 10% trong 2 lượt.',
		describe_en = 'Zenyatta launches mechanical orbs to attack an enemy target, dealing #C0x3D8A99#120% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage#C0x5B545B#, while simultaneously increasing his own magic defense by 50% and magic attack by 10% for 2 turns.',
		describe_th = 'เซนยัตต้ายิงลูกกลมกลไกเพื่อโจมตีเป้าหมายศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#120%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# พร้อมกันนั้นเพิ่มการป้องกันเวทมนตร์ของตัวเองขึ้น 50% และการโจมตีเวทมนตร์ขึ้น 10% เป็นเวลา 2 เทิร์น',
		describe_in = 'Zenyatta melepaskan bola mekanik untuk menyerang target musuh, memberikan #C0x3D8A99#120% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerusakan Sihir#C0x5B545B#, sekaligus meningkatkan pertahanan sihir sendiri sebesar 50% dan serangan sihir sebesar 10% selama 2 giliran.',
		describe_ph = 'Inilulunsad ni Zenyatta ang mga mekanikal na bola upang atakihin ang isang target na kalaban, na nagdudulot ng #C0x3D8A99#120% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage#C0x5B545B#, kasabay ng pagtaas ng sariling magic defense ng 50% at magic attack ng 10% sa loob ng 2 turn.',
		describe_ma = 'Zenyatta melancarkan bola mekanikal untuk menyerang sasaran musuh, memberikan #C0x3D8A99#120% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerosakan Sihir#C0x5B545B#, sambil meningkatkan pertahanan sihir dirinya sendiri sebanyak 50% dan serangan sihir sebanyak 10% selama 2 pusingan.',
		describe = 'Zenyatta launches mechanical orbs to attack an enemy target, dealing #C0x3D8A99#120% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage#C0x5B545B#, while simultaneously increasing his own magic defense by 50% and magic attack by 10% for 2 turns.',
		simDesc_vn = 'Zenyatta phóng những viên bi cơ học để tấn công một mục tiêu kẻ thù.',
		simDesc_en = 'Zenyatta launches mechanical orbs to attack an enemy target.',
		simDesc_th = 'เซ็นยัตตาโจมตีเป้าหมายศัตรูด้วยลูกกลมกลไก',
		simDesc_in = 'Zenyatta melempar bola mekanis untuk menyerang musuh.',
		simDesc_ph = 'Si Zenyatta ay nagpapalipad ng mga mekanikal na orb upang atakihin ang isang kaaway.',
		simDesc_ma = 'Zenyatta melancarkan bola mekanikal untuk menyerang sasaran musuh.',
