	[31813] = {
		id = 31813,
		skillName_vn = 'Thánh',
		skillName_en = 'Saint',
		skillName_th = 'เซนต์',
		skillName_in = 'Orang Suci',
		skillName_ph = 'Santo',
		skillName_ma = 'Orang Suci',
		skillName = 'Saint',
		describe_vn = 'Zenyatta giải phóng bộ phận giả cơ khí của mình để bắn phá các mục tiêu ở hàng đầu của kẻ địch, gây ra #C0x3D8A99#250% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, hấp thụ 10% máu của mục tiêu (không quá 30% máu tối đa của Zenyatta) và phân bổ đều cho mục tiêu ở hàng đầu của bạn, tăng 20% khả năng giảm sát thương của hàng trước đồng minh và khiến mục tiêu có tỷ lệ máu thấp nhất giữa bạn và bạn của bạn nhận được [Lá bảo vệ] trong 3 lượt.',
		describe_en = 'Zenyatta releases his mechanical prosthetic to bombard enemy frontline targets, dealing #C0x3D8A99#250% Magic Damage#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Magic Damage#C0x5B545B#, absorbing 10% of the target\'s health (not exceeding 30% of Zenyatta\'s maximum health) and distributing it evenly among your frontline allies, increasing their damage reduction by 20% and granting the ally with the lowest health between you and your teammate [Guardian Leaf] for 3 turns.',
		describe_th = 'เซนยัตตะปลดปล่อยแขนกลจักรกลของเขาเพื่อโจมตีเป้าหมายแนวหน้าในฝ่ายศัตรู สร้าง #C0x3D8A99#250% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# ดูดเลือดเป้าหมาย 10% (ไม่เกิน 30% ของพลังชีวิตสูงสุดของเซนยัตตะ) และแจกจ่ายเลือดนั้นอย่างเท่าเทียมให้กับแนวหน้าของคุณ เพิ่มความสามารถในการลดความเสียหายของพันธมิตรแนวหน้า 20% และมอบ [ใบปกป้อง] ให้แก่เป้าหมายที่มีพลังชีวิตต่ำที่สุดในระหว่างคุณกับเพื่อนของคุณเป็นเวลา 3 เทิร์น',
		describe_in = 'Zenyatta melepaskan bagian prostetik mekaniknya untuk menembak sasaran lini depan musuh, menyebabkan #C0x3D8A99#250% Damage Sihir#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Damage Sihir#C0x5B545B#, menyerap 10% darah target (tidak lebih dari 30% darah maksimum Zenyatta) dan membagikannya secara merata ke target di lini depan Anda, meningkatkan pengurangan damage rekan di barisan depan sebesar 20% dan memberikan [Daun Pelindung] kepada target yang memiliki darah terendah antara Anda dan rekan Anda selama 3 giliran.',
		describe_ph = 'Inilabas ni Zenyatta ang kanyang mekanikal na prosthetic upang barilin ang mga target sa harapang linya ng kalaban, na nagdudulot ng #C0x3D8A99#250% Magic Damage#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Magic Damage#C0x5B545B#, sumisipsip ng 10% ng HP ng target (hindi hihigit sa 30% ng maximum HP ni Zenyatta) at pantay-pantay na ipinamamahagi ito sa mga target sa iyong harapang linya, nagpapataas ng 20% damage reduction ng mga kakampi sa harapang linya at binibigyan ang target na may pinakamababang HP sa pagitan mo at ng kasama mo ng [Guardian Leaf] sa loob ng 3 na turn.',
		describe_ma = 'Zenyatta melepaskan anggota prostetik mekanikalnya untuk menembak sasaran barisan hadapan musuh, menyebabkan #C0x3D8A99#250% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Kerosakan Sihir#C0x5B545B#, menyerap 10% darah sasaran (tidak melebihi 30% darah maksimum Zenyatta) dan membahagikannya sama rata kepada sasaran di barisan hadapan anda, meningkatkan pengurangan kerosakan barisan depan rakan sepasukan sebanyak 20% dan memberikan [Daun Pelindung] kepada sasaran dengan darah terendah antara anda dan rakan anda selama 3 pusingan.',
		describe = 'Zenyatta releases his mechanical prosthetic to bombard enemy frontline targets, dealing #C0x3D8A99#250% Magic Damage#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#Magic Damage#C0x5B545B#, absorbing 10% of the target\'s health (not exceeding 30% of Zenyatta\'s maximum health) and distributing it evenly among your frontline allies, increasing their damage reduction by 20% and granting the ally with the lowest health between you and your teammate [Guardian Leaf] for 3 turns.',
		simDesc_vn = 'Zenyatta giải phóng một cánh tay giả cơ học để bắn phá các mục tiêu ở hàng đầu của kẻ thù.',
		simDesc_en = 'Zenyatta releases a mechanical prosthetic arm to bombard the enemy\'s front-line targets.',
		simDesc_th = 'เซ็นยัตตาปล่อยแขนเทียมกลไกออกมาเพื่อโจมตีเป้าหมายแถวหน้าของศัตรู',
		simDesc_in = 'Zenyatta melepaskan lengan prostetik mekanis untuk menyerang target di barisan depan musuh.',
		simDesc_ph = 'Pinakakawala ni Zenyatta ang isang mekanikal na prosthetic na braso upang bombahin ang mga target sa unahang linya ng kalaban.',
		simDesc_ma = 'Zenyatta melepaskan lengan prostetik mekanikal untuk membedil sasaran di barisan hadapan musuh.',
		simDesc = 'Zenyatta releases a mechanical prosthetic arm to bombard the enemy\'s front-line targets.',
		starEffect = __data_t__starEffect[31813],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Cung cấp <Lá Bảo Vệ> cho hai mục tiêu có tỷ lệ máu thấp nhất của bản thân và đồng minh trong 3 lượt.',
		starEffectDesc = 'Additional effect: Provides <Protection Leaves> to the two lowest health targets of yourself and allies for 3 turns.',
		starEffectDesc_en = 'Additional effect: Provides <Protection Leaves> to the two lowest health targets of yourself and allies for 3 turns.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ทำให้ตนเองและยูนิตฝ่ายเราที่มีสัดส่วนพลังชีวิตต่ำที่สุด 2 ตัว ได้รับ [ใบไม้พิทักษ์] เป็นเวลา 3 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Memberikan <Lá Bảo Vệ> kepada dua target dengan HP terendah dari diri sendiri dan sekutu selama 3 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Nagbibigay ng <Lá Bảo Vệ> sa dalawang target na may pinakamababang health ng sarili at mga kakampi sa loob ng 3 na turn.',
		starEffectDesc_ma = 'Kesan tambahan: Memberikan <Lá Bảo Vệ> kepada dua sasaran dengan kesihatan terendah daripada diri sendiri dan sekutu selama 3 pusingan.',
