	[31816] = {
		id = 31816,
		skillName_vn = 'Siêu phàm nhập thánh',
		skillName_en = 'Transcendence into Sanctity',
		skillName_th = 'เหนือมนุษย์เข้าสู่ความศักดิ์สิทธิ์',
		skillName_in = 'Melampaui Manusia Menuju Kesucian',
		skillName_ph = 'Supernatural na Pagpasok sa Banal na Kalagayan',
		skillName_ma = 'Melampaui Manusia Menuju Kesucian',
		skillName = 'Transcendence into Sanctity',
		describe_vn = 'Lá giám hộ: Vào và nhận [Lá hộ mệnh] trong 3 lượt (hiệu ứng buff, có thể bị xua tan, hồi phục sau khi bị tấn công) từ Zenyatta #C0x5c9970#$(60+skillLevel*0.3-0.3)$%#C0x5B545B# Cuộc sống của đòn tấn công ma thuật. Khi máu thấp hơn 35%, nó sẽ tàng hình trong 1 hiệp. Sau khi tàng hình kết thúc, lá bảo vệ sẽ được tiêu hao để phục hồi 25% máu tối đa của mục tiêu)\nTrái tim công lý: Giảm 10% sát thương kỹ năng (sát thương bóng tối 20%)',
		describe_en = 'Guardian Leaf: Enter and receive [Protection Leaf] for 3 turns (buff effect, can be dispelled, heals after being attacked) from Zenyatta #C0x5c9970#$(60+skillLevel*0.3-0.3)$%#C0x5B545B# Magical attack life. When HP is below 35%, becomes invisible for 1 turn. After invisibility ends, the protection leaf is consumed to restore 25% of the target\'s max HP. \n Heart of Justice: Reduces skill damage by 10% (dark damage 20%)',
		describe_th = 'ใบอารักขา: เข้าสู่สถานะและรับ [ใบอารักขา] เป็นเวลา 3 เทิร์น (เอฟเฟกต์บัฟ สามารถถูกลบได้ ฟื้นฟูเมื่อถูกโจมตี) จาก Zenyatta #C0x5c9970#$(60+skillLevel*0.3-0.3)$%#C0x5B545B# ชีวิตจากการโจมตีเวทย์มนตร์ เมื่อพลังชีวิตต่ำกว่า 35% จะล่องหนเป็นเวลา 1 เทิร์น เมื่อหมดการล่องหน ใบอารักขาจะถูกใช้เพื่อฟื้นฟูพลังชีวิตของเป้าหมาย 25% ของพลังชีวิตสูงสุด \n หัวใจแห่งความยุติธรรม: ลดความเสียหายจากสกิลลง 10% (ความเสียหายเวทมนตร์มืด 20%)',
		describe_in = 'Daun Pelindung: Masuk dan dapatkan [Daun Perlindungan] selama 3 giliran (efek buff, dapat dihapus, pulih setelah diserang) dari Zenyatta #C0x5c9970#$(60+skillLevel*0.3-0.3)$%#C0x5B545B# Kehidupan serangan sihir. Saat HP kurang dari 35%, menjadi tak terlihat selama 1 giliran. Setelah tak terlihat berakhir, daun pelindung akan digunakan untuk memulihkan 25% HP maksimal target. \n Hati Keadilan: Mengurangi damage skill sebesar 10% (damage gelap 20%)',
		describe_ph = 'Guardian Leaf: Pumasok at tumanggap ng [Protection Leaf] sa loob ng 3 turn (buff effect, maaaring maalis, nag-hihilom pagkatapos tamaan) mula kay Zenyatta #C0x5c9970#$(60+skillLevel*0.3-0.3)$%#C0x5B545B# Buhay ng magic attack. Kapag ang HP ay mas mababa sa 35%, nagiging invisible sa loob ng 1 turn. Pagkatapos ng invisibility, ang protection leaf ay nauubos para magpagaling ng 25% ng maximum HP ng target. \n Puso ng Katarungan: Nagbabawas ng 10% skill damage (20% dark damage)',
		describe_ma = 'Daun Penjaga: Masuk dan terima [Daun Pelindung] selama 3 pusingan (kesan buff, boleh dibersihkan, pulih selepas diserang) daripada Zenyatta #C0x5c9970#$(60+skillLevel*0.3-0.3)$%#C0x5B545B# Kehidupan serangan magik. Apabila HP kurang daripada 35%, menjadi tidak kelihatan selama 1 pusingan. Selepas tidak kelihatan berakhir, daun pelindung akan digunakan untuk memulihkan 25% HP maksimum sasaran. \n Hati Keadilan: Mengurangkan kerosakan kemahiran sebanyak 10% (kerosakan gelap 20%)',
		describe = 'Guardian Leaf: Enter and receive [Protection Leaf] for 3 turns (buff effect, can be dispelled, heals after being attacked) from Zenyatta #C0x5c9970#$(60+skillLevel*0.3-0.3)$%#C0x5B545B# Magical attack life. When HP is below 35%, becomes invisible for 1 turn. After invisibility ends, the protection leaf is consumed to restore 25% of the target\'s max HP. \n Heart of Justice: Reduces skill damage by 10% (dark damage 20%)',
		starEffect = __data_t__starEffect[31816],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: <Lá Bảo Vệ> cung cấp thêm 10% hút máu và giảm sát thương.',
		starEffectDesc = 'Additional Effect: <Lá Bảo Vệ> provides an extra 10% life steal and damage reduction.',
		starEffectDesc_en = 'Additional Effect: <Lá Bảo Vệ> provides an extra 10% life steal and damage reduction.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: [ใบไม้พิทักษ์] มอบเอฟเฟกต์เพิ่มเติมคือเพิ่มอัตราดูดเลือด 10% และลดความเสียหายที่ได้รับ 10%',
