	[32011] = {
		id = 32011,
		skillName_vn = 'Sấm sét',
		skillName_en = 'Thunder',
		skillName_th = 'ฟ้าร้อง',
		skillName_in = 'Guntur',
		skillName_ph = 'Kidlat',
		skillName_ma = 'Guruh',
		skillName = 'Thunder',
		describe_vn = 'Đám mây sấm sét thu hút một tia sét tấn công một mục tiêu kẻ địch, gây ra #C0x3D8A99#100% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B# và tăng Sát Thương Phép Thuật của bản thân thêm 20% trong 2 lượt.',
		describe_en = 'The thundercloud attracts a lightning bolt to strike an enemy target, dealing #C0x3D8A99#100% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magical Damage#C0x5B545B# and increasing own Magical Damage by 20% for 2 turns.',
		describe_th = 'กลุ่มเมฆฟ้าร้องดึงดูดสายฟ้าโจมตีเป้าหมายศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#100%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# และเพิ่มความเสียหายเวทมนตร์ของตนเองขึ้น 20% เป็นเวลา 2 เทิร์น',
		describe_in = 'Awan badai menarik petir menyerang target musuh, memberikan #C0x3D8A99#100% Damage Magis#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Damage Magis#C0x5B545B# dan meningkatkan Damage Magis sendiri sebesar 20% selama 2 giliran.',
		describe_ph = 'Ang ulap na may kulog ay humihila ng kidlat upang umatake sa isang kalabang target, na nagdudulot ng #C0x3D8A99#100% Sakit na Mahika#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Sakit na Mahika#C0x5B545B# at nagdaragdag ng 20% sa sariling Sakit na Mahika sa loob ng 2 turns.',
		describe_ma = 'Awan guruh menarik kilat menyerang sasaran musuh, menyebabkan #C0x3D8A99#100% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerosakan Magik#C0x5B545B# dan meningkatkan Kerosakan Magik diri sendiri sebanyak 20% selama 2 pusingan.',
		describe = 'The thundercloud attracts a lightning bolt to strike an enemy target, dealing #C0x3D8A99#100% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magical Damage#C0x5B545B# and increasing own Magical Damage by 20% for 2 turns.',
