	[32013] = {
		id = 32013,
		skillName_vn = 'Dông bão',
		skillName_en = 'Stormy',
		skillName_th = 'พายุ',
		skillName_in = 'Badai',
		skillName_ph = 'Bagyo',
		skillName_ma = 'Badai',
		skillName = 'Stormy',
		describe_vn = 'Đám mây sấm sét biến mất trong đám mây sấm sét, gây ra giông bão tấn công một mục tiêu kẻ địch, gây ra #C0x3D8A99#460% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B 54#Spell Damage#C0x5B545B#, sau đó gây ra giông bão kéo dài 1 hiệp. Trong thời gian này, một sấm sét sẽ được tạo ra vào cuối mỗi kẻ thù và vòng giao hữu để tấn công một mục tiêu kẻ thù ngẫu nhiên. Một sấm bầu trời bổ sung sẽ được tạo ra vào cuối vòng đấu của người hùng sấm sét thân thiện.',
		describe_en = 'The thundercloud vanished within the thundercloud, causing a storm to strike an enemy target, dealing #C0x3D8A99#460% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B 54#Spell Damage#C0x5B545B#. Then, it triggers a storm that lasts for 1 turn. During this time, a thunderbolt will be summoned at the end of each enemy and friendly round to attack a random enemy target. An additional sky thunderbolt will be created at the end of the friendly thunder hero\'s round.',
		describe_th = 'เมฆฝนฟ้าคะนองหายไปในเมฆฝนฟ้าคะนอง ทำให้เกิดพายุโจมตีเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#460%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B 54#ความเสียหายจากเวทมนตร์#C0x5B545B# จากนั้นจะทำให้เกิดพายุที่ยาวนาน 1 เทิร์น ในระหว่างนี้ ฟ้าผ่าจะถูกสร้างขึ้นในตอนสิ้นสุดแต่ละรอบของศัตรูและรอบมิตร เพื่อโจมตีเป้าหมายศัตรูแบบสุ่ม ฟ้าผ่าเสริมจะถูกสร้างขึ้นในตอนสิ้นสุดรอบของฮีโร่สายฟ้าเพื่อนบ้าน',
		describe_in = 'Awan petir menghilang dalam awan petir, menyebabkan badai menyerang satu target musuh, memberikan #C0x3D8A99#460% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B 54#Kerusakan Spell#C0x5B545B#. Kemudian menyebabkan badai berlangsung selama 1 giliran. Selama waktu ini, sambaran petir akan dibuat di akhir setiap giliran musuh dan giliran teman untuk menyerang target musuh secara acak. Sambaran petir tambahan akan dibuat di akhir giliran pahlawan petir teman.',
		describe_ph = 'Ang ulap ng kidlat ay nawala sa ulap ng kidlat, nagdulot ng bagyong umatake sa isang kalabang target, na nagdudulot ng #C0x3D8A99#460% Panlaban sa Salamangka#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B 54#Danyong Salamangka#C0x5B545B#. Pagkatapos ay nagdudulot ng bagyo na tumatagal ng 1 turn. Sa panahong ito, isang kidlat ang lilikhain sa dulo ng bawat kalabang at kaibigang round upang umatake sa isang random na kalabang target. Isang dagdag na kidlat sa langit ang lilikhain sa dulo ng round ng kaibigang hero ng kidlat.',
		describe_ma = 'Awan petir hilang dalam awan petir, menyebabkan ribut menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#460% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B 54#Kerosakan Sihir#C0x5B545B#. Kemudian menyebabkan ribut yang berterusan selama 1 pusingan. Dalam tempoh ini, petir akan dijana pada akhir setiap giliran musuh dan giliran sekutu untuk menyerang sasaran musuh secara rawak. Satu petir tambahan akan dijana pada akhir giliran wira petir sekutu.',
		describe = 'The thundercloud vanished within the thundercloud, causing a storm to strike an enemy target, dealing #C0x3D8A99#460% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B 54#Spell Damage#C0x5B545B#. Then, it triggers a storm that lasts for 1 turn. During this time, a thunderbolt will be summoned at the end of each enemy and friendly round to attack a random enemy target. An additional sky thunderbolt will be created at the end of the friendly thunder hero\'s round.',
		simDesc_vn = 'Đám mây sấm sét biến mất trong đám mây sấm sét, gây ra giông bão tấn công một mục tiêu địch, sau đó tiếp tục gây ra giông bão tấn công một mục tiêu địch ngẫu nhiên.',
		simDesc_en = 'The thundercloud dissipates within the thundercloud, causing a storm to strike an enemy target, then continues to cause a storm to attack a random enemy target.',
		simDesc_th = 'เมฆฟ้าร้องจางหายไปในเมฆฟ้าร้อง ก่อให้เกิดพายุโจมตีเป้าหมายศัตรู จากนั้นก็สร้างพายุโจมตีเป้าหมายศัตรูแบบสุ่มต่อเนื่อง',
		simDesc_in = 'Awan petir menghilang di dalam awan petir, menyebabkan badai menyerang satu target musuh, lalu terus menyebabkan badai menyerang target musuh acak.',
		simDesc_ph = 'Ang ulap ng kidlat ay nawawala sa loob ng ulap ng kidlat, na nagdudulot ng bagyong umatake sa isang kalabang target, pagkatapos ay nagpapatuloy na magdulot ng bagyong umatake sa isang random na kalabang target.',
		simDesc_ma = 'Awan guruh hilang dalam awan guruh, menyebabkan ribut menyerang satu sasaran musuh, kemudian terus menyebabkan ribut menyerang sasaran musuh secara rawak.',
		simDesc = 'The thundercloud dissipates within the thundercloud, causing a storm to strike an enemy target, then continues to cause a storm to attack a random enemy target.',
		starEffect = __data_t__starEffect[32013],
		-- {11}
