	[32016] = {
		id = 32016,
		skillName_vn = 'Sấm sét',
		skillName_en = 'Thunder',
		skillName_th = 'ฟ้าร้อง',
		skillName_in = 'Guntur',
		skillName_ph = 'Kidlat',
		skillName_ma = 'Guruh',
		skillName = 'Thunder',
		describe_vn = 'Sky Thunder: Vào cuối mỗi vòng lớn, nó sẽ gây ra 100% sát thương sấm sét thực sự của Sát Thương Phép Thuật của chính mình cho một mục tiêu kẻ địch ngẫu nhiên. Mỗi đòn tấn công sấm sét trên bầu trời có xác suất cơ bản là #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, khiến mục tiêu nhận được một lớp [Siêu dẫn]\n#F10# \n#F40##L10#[Siêu dẫn]: #L0# có thể được xếp chồng lên đến năm lớp. Mỗi lớp siêu dẫn làm tăng khả năng khuếch đại sát thương do sét thêm 5% và tỷ lệ dẫn điện thêm 20%. Khi mục tiêu siêu dẫn bị sấm sét tấn công, tất cả các mục tiêu siêu dẫn sẽ nhận sát thương sấm sét thực sự tương ứng với tỷ lệ dẫn điện.',
		describe_en = 'Sky Thunder: At the end of each major round, it deals 100% of its own true Lightning Magic Damage to a random enemy target. Each Sky Thunder strike has a base chance of #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# to inflict a [Superconductor]\n#F10# \n#F40##L10#[Superconductor]: #L0# stacks up to five layers. Each Superconductor layer increases lightning damage amplification by 5% and conducts rate by 20%. When a Superconductor target is hit by lightning, all Superconductor targets receive true lightning damage corresponding to the conduction rate.',
		describe_th = 'สกาย ธันเดอร์: ในตอนท้ายของรอบใหญ่แต่ละรอบ จะก่อให้เกิดความเสียหายสายฟ้าจริง 100% ของพลังโจมตีเวทมนตร์ของตนเองต่อเป้าหมายศัตรูแบบสุ่ม การโจมตีสายฟ้าแต่ละครั้งมีโอกาสพื้นฐาน #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# ทำให้เป้าหมายได้รับสถานะ [ตัวนำยิ่งยวด]\n#F10# \n#F40##L10#[ตัวนำยิ่งยวด]: #L0# ซ้อนได้สูงสุดห้าชั้น แต่ละชั้นของตัวนำยิ่งยวดเพิ่มการขยายความเสียหายสายฟ้า 5% และอัตราการนำไฟฟ้า 20% เมื่อเป้าหมายที่มีตัวนำยิ่งยวดถูกโจมตีด้วยสายฟ้า เป้าหมายตัวนำยิ่งยวดทั้งหมดจะได้รับความเสียหายสายฟ้าจริงตามอัตราการนำไฟฟ้า',
		describe_in = 'Sky Thunder: Pada akhir setiap putaran besar, ini memberikan 100% kerusakan sebenarnya dari Damage Sihir Petir miliknya sendiri kepada satu target musuh secara acak. Setiap serangan petir Sky Thunder memiliki peluang dasar #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# untuk memberikan lapisan [Superkonduktor]\n#F10# \n#F40##L10#[Superkonduktor]: #L0# dapat ditumpuk hingga lima lapisan. Setiap lapisan superkonduktor meningkatkan amplifikasi kerusakan petir sebesar 5% dan tingkat konduksi sebesar 20%. Ketika target superkonduktor diserang petir, semua target yang memiliki superkonduktor akan menerima kerusakan petir sebenarnya sesuai dengan tingkat konduktivitas.',
		describe_ph = 'Sky Thunder: Sa pagtatapos ng bawat malaking round, magdudulot ito ng 100% tunay na pinsala ng Lightning Magic Damage nito sa isang random na kalaban na target. Ang bawat pag-atake ng kidlat mula sa Sky Thunder ay may base chance na #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# upang magdulot ng isang layer ng [Superconductor]\n#F10# \n#F40##L10#[Superconductor]: #L0# maaaring ma-stack hanggang limang layers. Bawat layer ng Superconductor ay nagpapataas ng damage amplification ng kidlat ng 5% at conduction rate ng 20%. Kapag ang target na may Superconductor ay tinamaan ng kidlat, lahat ng Superconductor targets ay makatatanggap ng tunay na lightning damage ayon sa conduction rate.',
		describe_ma = 'Sky Thunder: Pada akhir setiap pusingan besar, ia akan menyebabkan 100% kerosakan sebenar Sihir Petirnya sendiri ke sasaran musuh rawak. Setiap serangan petir Sky Thunder mempunyai peluang asas #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# untuk menyebabkan lapisan [Superkonduktor]\n#F10# \n#F40##L10#[Superkonduktor]: #L0# boleh bertumpuk sehingga lima lapisan. Setiap lapisan superkonduktor meningkatkan penguatan kerosakan petir sebanyak 5% dan kadar konduksi sebanyak 20%. Apabila sasaran superkonduktor diserang oleh petir, semua sasaran superkonduktor akan menerima kerosakan petir sebenar yang bersesuaian dengan kadar konduksi.',
		describe = 'Sky Thunder: At the end of each major round, it deals 100% of its own true Lightning Magic Damage to a random enemy target. Each Sky Thunder strike has a base chance of #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# to inflict a [Superconductor]\n#F10# \n#F40##L10#[Superconductor]: #L0# stacks up to five layers. Each Superconductor layer increases lightning damage amplification by 5% and conducts rate by 20%. When a Superconductor target is hit by lightning, all Superconductor targets receive true lightning damage corresponding to the conduction rate.',
		starEffect = __data_t__starEffect[32016],
		-- {8}
		starEffectDesc_vn = 'Hiệu quả tăng cường: Sát thương của  <Thiên Lôi>  gây thêm sát thương chuẩn thuộc tính Lôi tương đương 15% lượng máu đã mất của mục tiêu (không vượt quá 300% Công Phép của Lôi Điện Vân).',
		starEffectDesc = 'Enhancement Effect: Damage from <Thiên Lôi> inflicts additional Lightning attribute true damage equal to 15% of the target\'s lost health (not exceeding 300% of Lightning Electric Cloud\'s Magic Power).',
		starEffectDesc_en = 'Enhancement Effect: Damage from <Thiên Lôi> inflicts additional Lightning attribute true damage equal to 15% of the target\'s lost health (not exceeding 300% of Lightning Electric Cloud\'s Magic Power).',
		starEffectDesc_th = 'ผลการเสริม: ความเสียหายจาก <Thiên Lôi> ก่อให้เกิดความเสียหายจริงธาตุสายฟ้าเพิ่มเติมเท่ากับ 15% ของพลังชีวิตที่สูญเสียของเป้าหมาย (ไม่เกิน 300% ของพลังเวทมนตร์ของเมฆไฟฟ้าสายฟ้า).',
		starEffectDesc_in = 'Efek Peningkatan: Kerusakan dari <Thiên Lôi> menyebabkan kerusakan nyata atribut Petir tambahan sebesar 15% dari kesehatan yang hilang dari target (tidak melebihi 300% Kekuatan Sihir dari Awan Listrik Petir).',
		starEffectDesc_ph = 'Epekto ng Pagpapalakas: Ang pinsalang dulot ng <Thiên Lôi> ay nagdudulot ng karagdagang totoong pinsala ng katangiang Kidlat na katumbas ng 15% ng nawalang buhay ng target (hindi lalampas sa 300% ng Magic Power ng Kidlat na Ulap ng Elektrisidad).',
		starEffectDesc_ma = 'Kesan Peningkatan: Kerosakan dari <Thiên Lôi> menyebabkan kerosakan atribut Kilat sebenar tambahan bersamaan dengan 15% daripada kesihatan yang hilang oleh sasaran (tidak melebihi 300% Kuasa Sihir Awan Elektrik Kilat).',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {320161}
	},
