	[32113] = {
		id = 32113,
		skillName_vn = 'Tiên Pháp: Ngũ Hữu Vệ Môn',
		skillName_en = 'Immortal Spell: Five Sacred Gatekeepers',
		skillName_th = 'เวทมนตร์อมตะ: ห้าประตูศักดิ์สิทธิ์',
		skillName_in = 'Mantra Abadi: Lima Penjaga Gerbang Suci',
		skillName_ph = 'Wicca ng Imortal: Limang Banal na Tagapagtanggol ng Pintu',
		skillName_ma = 'Ilmu Abadi: Lima Penjaga Gerbang Suci',
		skillName = 'Immortal Spell: Five Sacred Gatekeepers',
		describe_vn = 'Jiraiya lao lên, sau đó phun ra siêu lửa từ đuôi lao về phía đỉnh núi, sau đó tung ra đòn tấn công bằng ngọn lửa hoa sen xanh, gây #C0x3D8A99#210% Sát Thương Phép Thuật #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, tất cả mục tiêu địch có Ngọn lửa Ninja Qinglian sẽ ngay lập tức giải quyết toàn bộ tác dụng của [#L10#Đốt lửa xanh#L0#] (không trừ số vòng của Ngọn lửa Ninja Qinglian đốt cháy trên mục tiêu) và xây dựng [#L10#Tường lửa thánh#L0#] ở trung tâm của chiến trường giao hữu kéo dài trong 1 hiệp\n#F20# \n#F40##L10#[#L10#Tường lửa thánh#L0#]: #L0#Hiệu ứng đặc biệt, khi Anh hùng của bạn phát động một cuộc tấn công, Tường Lửa Thánh sẽ xua tan hiệu ứng tiêu cực (ngoại trừ hiệu ứng đốt cháy) và khiến đòn tấn công này trở thành mục tiêu. Một đơn vị ngẫu nhiên sẽ nhận thêm 50% Sát Thương Phép Thuật của Jiraiya; khi tướng địch tung đòn tấn công, nó sẽ nhận 100% sát thương phép của Jiraiya, xóa bỏ hiệu ứng buff và chịu [#L10#Green Flame Burn#L0#] trong 2 lượt.',
		describe_en = 'Jiraiya lunged forward, then spewed super flames from his tail towards the mountain peak, followed by an attack with a blue lotus flame, dealing #C0x3D8A99#210% Magic Damage #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Magic Damage #C0x5B545B#. All enemy targets with Qinglian Ninja Flame will immediately have all effects of [#L10#Blue Flame Burn#L0#] dispelled (without reducing the number of stacks of Qinglian Ninja Flame burning on the target) and build a [#L10#Sacred Flame Wall#L0#] at the center of the friendly battle arena lasting 1 turn. #F20# #F40##L10#[#L10#Sacred Flame Wall#L0#]: #L0#Special effect: When your hero initiates an attack, the Sacred Flame Wall will dispel negative effects (except burn effects) and cause this attack to be targeted. A random unit will receive an additional 50% of Jiraiya\'s Magic Damage; when an enemy general attacks, it will receive 100% of Jiraiya\'s magic damage, remove buff effects, and suffer [#L10#Green Flame Burn#L0#] for 2 turns.',
		describe_th = 'จิไรยะพุ่งโจมตี จากนั้นพ่นไฟแรงสูงจากหางไปยังยอดเขา แล้วปล่อยท่าฟื้นไฟดอกบัวสีฟ้า สร้างความเสียหายเวทมนตร์ #C0x3D8A99#210% #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# ให้กับศัตรูทั้งหมดที่มีไฟนินจาเฉิงเลียน จะถูกลบเอฟเฟกต์ทั้งหมดของ [#L10#การไหม้ไฟฟ้าเขียว#L0#] ทันที (โดยไม่ลดจำนวนรอบไฟนินจาเฉิงเลียนที่เผาซ้อนบนเป้าหมาย) และก่อให้เกิด [#L10#กำแพงไฟศักดิ์สิทธิ์#L0#] ที่ศูนย์กลางสนามรบต่อสู้ระหว่างพันธมิตร เป็นเวลาหนึ่งเทิร์น #F20# #F40##L10#[#L10#กำแพงไฟศักดิ์สิทธิ์#L0#]: #L0#เอฟเฟกต์พิเศษ เมื่อฮีโร่ของคุณเริ่มโจมตี กำแพงไฟศักดิ์สิทธิ์จะขจัดผลลบ (ยกเว้นผลการไหม้) และทำให้การโจมตีนี้เป็นเป้าหมาย หน่วยสุ่มจะได้รับความเสียหายเวทเพิ่มอีก 50% ของจิไรยะ; เมื่อเจ้าแม่ศัตรูโจมตี จะได้รับความเสียเวท 100% ของจิไรยะ, ล้างบัฟ และรับ [#L10#การไหม้ไฟเขียว#L0#] เป็นเวลา 2 เทิร์น',
		describe_in = 'Jiraiya melompat maju, lalu menyemburkan api super dari ekornya ke arah puncak gunung, kemudian melancarkan serangan dengan api teratai biru, memberikan #C0x3D8A99#210% Damage Magis #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Damage Magis #C0x5B545B#. Semua target musuh yang memiliki Api Ninja Qinglian akan segera menghapus semua efek dari [#L10#Pembakaran Api Biru#L0#] (tanpa mengurangi jumlah tumpukan Api Ninja Qinglian yang membakar pada target) dan membangun [#L10#Tembok Api Suci#L0#] di pusat medan pertempuran persahabatan selama 1 giliran. #F20# #F40##L10#[#L10#Tembok Api Suci#L0#]: #L0#Efek khusus: Ketika pahlawan Anda memulai serangan, Tembok Api Suci akan menghilangkan efek negatif (kecuali efek terbakar) dan membuat serangan ini menjadi sasaran. Satu unit acak akan menerima tambahan 50% Damage Magis Jiraiya; ketika jenderal musuh menyerang, ia akan menerima 100% damage magis dari Jiraiya, menghapus efek buff, dan menderita [#L10#Pembakaran Api Hijau#L0#] selama 2 giliran.',
		describe_ph = 'Tumakbo si Jiraiya pasulong, pagkatapos ay sumabog ng super apoy mula sa buntot patungo sa tuktok ng bundok, pagkatapos ay inilunsad ang atake gamit ang asul na apoy ng lotus, na nagdulot ng #C0x3D8A99#210% Sakit na Magic #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Sakit na Magic #C0x5B545B#. Lahat ng mga kalabang target na may Qinglian Ninja Flame ay agad na mawawala ang lahat ng epekto ng [#L10#Pagsunog ng Asul na Apoy#L0#] (hindi binabawasan ang bilang ng mga yugto ng Qinglian Ninja Flame na sinusunog sa target) at bumuo ng [#L10#Banal na Pader ng Apoy#L0#] sa gitna ng larangang paligsahan na tumatagal ng 1 round. #F20# #F40##L10#[#L10#Banal na Pader ng Apoy#L0#]: #L0#Espesyal na Epekto: Kapag ang iyong bayani ay naglunsad ng atake, ang Banal na Pader ng Apoy ay bubura ng mga negatibong epekto (maliban sa efektong pagsunog) at gagawing target ang atakeng ito. Isang random na yunit ang makakatanggap ng dagdag na 50% ng Sakit na Magic ni Jiraiya; kapag ang kalabang heneral ay umatake, tatanggap ito ng 100% na sakit na magic ni Jiraiya, aalisin ang mga buff effect, at magdurusa ng [#L10#Green Flame Burn#L0#] sa loob ng 2 round.',
		describe_ma = 'Jiraiya melompat ke hadapan, kemudian menyemburkan api super dari ekornya ke arah puncak gunung, kemudian melancarkan serangan dengan api bunga teratai biru, menyebabkan #C0x3D8A99#210% Kerosakan Sihir #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Semua sasaran musuh yang mempunyai Api Ninja Qinglian akan segera menyelesaikan semua kesan [#L10#Pembakaran Api Biru#L0#] (tanpa mengurangkan bilangan lapisan Api Ninja Qinglian pada sasaran) dan membina [#L10#Tembok Api Suci#L0#] di tengah medan pertempuran persahabatan selama 1 pusingan. #F20# #F40##L10#[#L10#Tembok Api Suci#L0#]: #L0#Kesan khas: Apabila hero anda memulakan serangan, Tembok Api Suci akan membersihkan kesan negatif (kecuali kesan terbakar) dan menjadikan serangan ini sebagai sasaran. Satu unit rawak akan menerima tambahan 50% Kerosakan Sihir Jiraiya; apabila jeneral musuh menyerang, ia akan menerima 100% Kerosakan Sihir Jiraiya, menghapuskan kesan buff, dan menderita [#L10#Pembakaran Api Hijau#L0#] selama 2 pusingan.',
		describe = 'Jiraiya lunged forward, then spewed super flames from his tail towards the mountain peak, followed by an attack with a blue lotus flame, dealing #C0x3D8A99#210% Magic Damage #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Magic Damage #C0x5B545B#. All enemy targets with Qinglian Ninja Flame will immediately have all effects of [#L10#Blue Flame Burn#L0#] dispelled (without reducing the number of stacks of Qinglian Ninja Flame burning on the target) and build a [#L10#Sacred Flame Wall#L0#] at the center of the friendly battle arena lasting 1 turn. #F20# #F40##L10#[#L10#Sacred Flame Wall#L0#]: #L0#Special effect: When your hero initiates an attack, the Sacred Flame Wall will dispel negative effects (except burn effects) and cause this attack to be targeted. A random unit will receive an additional 50% of Jiraiya\'s Magic Damage; when an enemy general attacks, it will receive 100% of Jiraiya\'s magic damage, remove buff effects, and suffer [#L10#Green Flame Burn#L0#] for 2 turns.',
		simDesc_vn = 'Jiraiya lao lên, sau đó phun ra siêu ngọn lửa từ đuôi của mình và lao lên đỉnh núi, sau đó tung ra đòn tấn công Ngọn lửa Ninja Qinglian, gây sát thương phép thuật cho kẻ thù trong phạm vi chéo, ngay lập tức tính toán sát thương đốt cháy của Ngọn lửa Ninja Qinglian và xây dựng một bức tường lửa thánh.',
		simDesc_en = 'Jiraiya lunged forward, then spewed a super flame from his tail and surged up the mountain peak, then unleashed the Ninja Qinglian Flame attack, dealing magical damage to enemies in a diagonal area. Immediately, the burning damage of the Ninja Qinglian Flame is calculated and a holy wall of fire is constructed.',
		simDesc_th = 'จิไรยะพุ่งเข้าไปข้างหน้า จากนั้นพ่นไฟวิเศษจากหางของเขาและพุ่งขึ้นยอดเขา จากนั้นโจมตีด้วยเปลวไฟนินจา ชิงเหลียน สร้างความเสียหายเวทย์มนตร์แก่ศัตรูในพื้นที่แนวทแยง คำนวณความเสียหายจากการถูกไฟเผาของเปลวไฟนินจาชิงเหลียนทันที และสร้างกำแพงไฟศักดิ์สิทธิ์ขึ้น',
		simDesc_in = 'Jiraiya melesat maju, kemudian memuntahkan api super dari ekornya dan meluncur ke puncak gunung, lalu melancarkan serangan Api Ninja Qinglian yang menyebabkan kerusakan magis pada musuh dalam area diagonal, segera menghitung kerusakan terbakar dari Api Ninja Qinglian dan membangun tembok api suci.',
		simDesc_ph = 'Sumugod si Jiraiya, saka umagos ng super apoy mula sa kanyang buntot at umakyat sa tuktok ng bundok, saka inilunsad ang pag-atake na Ninja Qinglian Flame, na nagdudulot ng pangmahikang pinsala sa mga kalaban sa saklaw na pahilis, agad na kinakalkula ang nasunog na pinsala ng Ninja Qinglian Flame at nagtatayo ng isang banal na pader ng apoy.',
		simDesc_ma = 'Jiraiya meluru ke depan, kemudian memuntahkan api super dari ekornya dan meluru ke puncak gunung, kemudian melancarkan serangan Api Ninja Qinglian yang menyebabkan kerosakan magik kepada musuh dalam kawasan serong, segeralah mengira kerosakan terbakar Api Ninja Qinglian dan membina tembok api suci.',
		simDesc = 'Jiraiya lunged forward, then spewed a super flame from his tail and surged up the mountain peak, then unleashed the Ninja Qinglian Flame attack, dealing magical damage to enemies in a diagonal area. Immediately, the burning damage of the Ninja Qinglian Flame is calculated and a holy wall of fire is constructed.',
		starEffect = __data_t__starEffect[32113],
		-- {11}
		starEffectDesc_vn = '<#L10#Tường Lửa Thánh#L0#> trong tuyệt kỹ duy trì 2 lượt và tăng thêm 100% sát thương tuyệt kỹ khi ở trạng thái Tiên Nhân.',
		starEffectDesc = '<#L10#Holy Firewall#L0#> lasts for 2 turns and increases skill damage by 100% when in Immortal state.',
		starEffectDesc_en = '<#L10#Holy Firewall#L0#> lasts for 2 turns and increases skill damage by 100% when in Immortal state.',
		starEffectDesc_th = '<#L10#กำแพงไฟศักดิ์สิทธิ์#L0#> คงอยู่ 2 เทิร์นและเพิ่มความเสียหายของสกิล 100% เมื่ออยู่ในสถานะอมตะ',
		starEffectDesc_in = '<#L10#Tembok Api Suci#L0#> bertahan selama 2 giliran dan meningkatkan kerusakan skill sebesar 100% saat dalam status Abadi.',
		starEffectDesc_ph = '<#L10#Banal na Firewall#L0#> tumatagal ng 2 turno at nagdaragdag ng 100% na pinsala sa kasanayan kapag nasa estado ng Imortal.',
		starEffectDesc_ma = '<#L10#Firewall Suci#L0#> bertahan selama 2 pusingan dan meningkatkan kerosakan kemahiran sebanyak 100% apabila berada dalam keadaan Abadi.',
		zawakeEffect = __data_t__zawakeEffect[32113],
		-- {79003}
		zawakeEffectDesc = 'Jiraiya lunges forward, then spits super fire from his tail toward the mountain peak, then launches an attack with green lotus flames, dealing #C0x3D8A99#210% Magic Damage #C0x5B545B#+$(skillLevel*4*60)$ of #C0xF13B54# magical damage in a cross range to enemies. The #C0x5B545B# effect causes all enemy targets with Qinglian Ninja Flame to immediately dispel all effects of <#L10#Green Flame Burning#L0#> (excluding the remaining rounds that Qinglian Ninja Flame burns on the target) and creates a <#L10#Holy Fire Wall#L0#> at the center of the friendly battlefield for 2 turns. \n#F20# \n#F40#In Immortal Mode, Immortal Mode duration is extended by 1 turn. \n#F20# \n#F40##L10#<#L10#Holy Fire Wall#L0#>: #L0#Special effect, when your hero launches an attack, the holy fire wall dispels negative effects (except burn effects) and makes this attack a target. A random unit takes an additional 50% of Jiraiya’s magic damage; when an enemy hero attacks, it takes 100% of Jiraiya’s magic damage, removes buff effects, and suffers <#L10#Green Flame Burn#L0#> for 2 turns.',
		zawakeEffectDesc_en = 'Jiraiya lunges forward, then spits super fire from his tail toward the mountain peak, then launches an attack with green lotus flames, dealing #C0x3D8A99#210% Magic Damage #C0x5B545B#+$(skillLevel*4*60)$ of #C0xF13B54# magical damage in a cross range to enemies. The #C0x5B545B# effect causes all enemy targets with Qinglian Ninja Flame to immediately dispel all effects of <#L10#Green Flame Burning#L0#> (excluding the remaining rounds that Qinglian Ninja Flame burns on the target) and creates a <#L10#Holy Fire Wall#L0#> at the center of the friendly battlefield for 2 turns. \n#F20# \n#F40#In Immortal Mode, Immortal Mode duration is extended by 1 turn. \n#F20# \n#F40##L10#<#L10#Holy Fire Wall#L0#>: #L0#Special effect, when your hero launches an attack, the holy fire wall dispels negative effects (except burn effects) and makes this attack a target. A random unit takes an additional 50% of Jiraiya’s magic damage; when an enemy hero attacks, it takes 100% of Jiraiya’s magic damage, removes buff effects, and suffers <#L10#Green Flame Burn#L0#> for 2 turns.',
		zawakeEffectDesc_th = 'จิไรยะพุ่งตัวไปข้างหน้า จากนั้นพ่นไฟแรงสูงจากหางไปยังยอดเขา จากนั้นโจมตีด้วยเปลวไฟดอกบัวสีเขียว สร้าง #C0x3D8A99#210% ความเสียหายเวทมนตร์ #C0x5B545B#+$(skillLevel*4*60)$ ของ #C0xF13B54# ความเสียหายเวทมนตร์ในระยะรูปกากบาทต่อศัตรู ผลกระทบ #C0x5B545B# ทำให้เป้าหมายศัตรูทั้งหมดที่มีเปลวนินจาเฉิงเหลียนลบล้างเอฟเฟกต์ทั้งหมดของ <#L10#Green Flame Burning#L0#> ทันที (ยกเว้นจำนวนรอบที่เปลวนินจาเฉิงเหลียนเผาไหม้บนเป้าหมาย) และสร้าง <#L10#กำแพงไฟศักดิ์สิทธิ์#L0#> ที่ศูนย์กลางสนามรบฝ่ายเดียวกันเป็นเวลา 2 เทิร์น \n#F20# \n#F40#ในโหมดอมตะ เวลาโหมดอมตะจะเพิ่มขึ้นอีก 1 เทิร์น \n#F20# \n#F40##L10#<#L10#Holy Fire Wall#L0#>: #L0#เอฟเฟกต์พิเศษ เมื่อฮีโร่ของคุณโจมตี กำแพงไฟศักดิ์สิทธิ์จะขจัดเอฟเฟกต์ลบ (ยกเว้นเอฟเฟกต์ไฟไหม้) และทำให้การโจมตีนี้เป็นเป้าหมาย หน่วยสุ่มได้รับความเสียหายเวทมนตร์เพิ่ม 50% ของจิไรยะ; เมื่อฮีโร่ศัตรูโจมตี หน่วยนั้นจะได้รับความเสียหายเวทมนตร์ของจิไรยะ 100%, ลบเอฟเฟกต์บัฟ และได้รับ <#L10#Green Flame Burn#L0#> เป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Jiraiya melesat maju, lalu menyemburkan api super dari ekornya ke puncak gunung, kemudian melancarkan serangan dengan api teratai hijau, memberikan #C0x3D8A99#210% Kerusakan Sihir #C0x5B545B#+$(skillLevel*4*60)$ dari #C0xF13B54# kerusakan sihir dalam jarak silang terhadap musuh. Efek #C0x5B545B# menyebabkan semua target musuh dengan Api Ninja Qinglian segera menghilangkan semua efek dari <#L10#Green Flame Burning#L0#> (tidak termasuk jumlah giliran dimana Api Ninja Qinglian terbakar pada target) dan membangun <#L10#Tembok Api Suci#L0#> di pusat medan pertempuran sekutu selama 2 giliran. \n#F20# \n#F40#Di Mode Abadi, durasi Mode Abadi diperpanjang 1 giliran lagi. \n#F20# \n#F40##L10#<#L10#Holy Fire Wall#L0#>: #L0#Efek khusus, ketika pahlawan Anda melancarkan serangan, Tembok Api Suci akan menghilangkan efek negatif (kecuali efek terbakar) dan membuat serangan ini menjadi sasaran. Sebuah unit acak akan menerima tambahan 50% kerusakan sihir Jiraiya; ketika pahlawan musuh menyerang, unit itu akan menerima 100% kerusakan sihir Jiraiya, menghapus efek buff, dan mengalami <#L10#Green Flame Burn#L0#> selama 2 giliran.',
		zawakeEffectDesc_ph = 'Jiraiya ayun pasulong, pagkatapos ay sumabog ng super na apoy mula sa buntot papunta sa tuktok ng bundok, pagkatapos ay naglunsad ng atake gamit ang berdeng apoy ng lotus, na nagdudulot ng #C0x3D8A99#210% Damage ng Magic #C0x5B545B#+$(skillLevel*4*60)$ ng #C0xF13B54# na damage ng magic sa isang cross na saklaw sa mga kaaway. Ang epekto ng #C0x5B545B# ay ginagawang lahat ng mga target na kalaban na may Qinglian Ninja Flame ay agad na natatanggal lahat ng epekto ng <#L10#Green Flame Burning#L0#> (hindi kasama ang bilang ng mga round na nasusunog ang Qinglian Ninja Flame sa target) at nagtatayo ng <#L10#Holy Fire Wall#L0#> sa gitna ng larangan ng labanan ng mga kaalyado sa loob ng 2 na turno. \n#F20# \n#F40#Sa Immortal Mode, ang tagal ng Immortal Mode ay pinalawig ng 1 pa na turno. \n#F20# \n#F40##L10#<#L10#Holy Fire Wall#L0#>: #L0#Espesyal na epekto, kapag ang iyong bayani ay naglunsad ng atake, ang banal na pader ng apoy ay nag-aalis ng mga negatibong epekto (maliban sa epekto ng pagkasunog) at ginagawang target ang atakeng ito. Isang random na yunit ang tatanggap ng dagdag na 50% na magic damage ni Jiraiya; kapag ang kalabang bayani ay umatake, tatanggap ito ng 100% magic damage ni Jiraiya, mawawala ang mga buff effect, at magdaranas ng <#L10#Green Flame Burn#L0#> sa loob ng 2 turnos.',
		zawakeEffectDesc_ma = 'Jiraiya meluru ke hadapan, kemudian menyemburkan api super dari ekornya ke arah puncak gunung, lalu melancarkan serangan dengan api teratai hijau, memberikan #C0x3D8A99#210% Kerosakan Sihir #C0x5B545B#+$(skillLevel*4*60)$ daripada #C0xF13B54# kerosakan sihir dalam julat silang kepada musuh. Kesan #C0x5B545B# menyebabkan semua sasaran musuh dengan Api Ninja Qinglian serta-merta menyingkirkan semua kesan <#L10#Green Flame Burning#L0#> (tidak termasuk bilangan pusingan yang Api Ninja Qinglian membakar pada sasaran) dan membina <#L10#Tembok Api Suci#L0#> di tengah medan perang bersekutu selama 2 pusingan. \n#F20# \n#F40#Dalam Mod Abadi, tempoh Mod Abadi dilanjutkan 1 pusingan lagi. \n#F20# \n#F40##L10#<#L10#Holy Fire Wall#L0#>: #L0#Kesan istimewa, apabila wira anda melancarkan serangan, Tembok Api Suci akan menyingkirkan kesan negatif (kecuali kesan terbakar) dan menjadikan serangan ini sasaran. Unit rawak akan menerima tambahan 50% kerosakan sihir Jiraiya; apabila wira musuh melancarkan serangan, ia akan menerima 100% kerosakan sihir Jiraiya, membuang kesan buff, dan menderita <#L10#Green Flame Burn#L0#> selama 2 pusingan.',
		zawakeEffectDesc_vn = 'Jiraiya lao lên, sau đó phun ra siêu lửa từ đuôi lao về phía đỉnh núi, sau đó tung ra đòn tấn công bằng ngọn lửa hoa sen xanh, gây #C0x3D8A99#210% Sát Thương Phép Thuật #C0x5B545B#+$(skillLevel*4*60)$ thuộc #C0xF13B54# sát thương phép trên phạm vi chéo của kẻ địch Tác hại #C0x5B545B#, tất cả mục tiêu địch có Ngọn lửa Ninja Qinglian sẽ ngay lập tức giải quyết toàn bộ tác dụng của <#L10#Green Flame Burning#L0#> (không trừ số vòng mà Ngọn lửa Ninja Qinglian đốt cháy trên mục tiêu) và xây dựng <#L10#Tường lửa thánh#L0#> ở trung tâm chiến trường giao hữu trong 2 hiệp\n#F20# \n#F40#Ở Chế độ Bất tử, Chế độ Bất tử được kéo dài thêm 1 hiệp\n#F20# \n#F40##L10#<#L10#Holy Fire Wall#L0#>: #L0#Hiệu ứng đặc biệt, khi anh hùng của bạn phát động một cuộc tấn công, Tường lửa thiêng sẽ xua tan hiệu ứng tiêu cực (ngoại trừ hiệu ứng đốt cháy) và khiến đòn tấn công này trở thành mục tiêu Một đơn vị ngẫu nhiên sẽ nhận thêm 50% sát thương phép của Jiraiya; khi tướng địch tung đòn tấn công, nó sẽ nhận 100% sát thương phép của Jiraiya, xóa bỏ hiệu ứng buff và chịu <#L10#Green Flame Burn#L0#> trong 2 lượt.',
		zawakeSimpleType = 1,
