		skillName_ph = 'Atake ni Susanoo',
		skillName_ma = 'Serangan Susanoo',
		skillName = 'Susanoo Strike',
		describe_vn = 'Uchiha Itachi vẫy đôi cánh tung đòn tấn công sấm sét vào một mục tiêu kẻ thù, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, đồng thời tăng sức Sát Thương Vật Lý của bản thân thêm 10% và tốc độ thêm 10% trong 2 lượt (có thể cộng dồn 2 lượt) lần)\n#F20# \n#F40# Complete Susanoo có 50% cơ hội thực hiện combo.',
		describe_en = 'Uchiha Itachi waves his wings to unleash a lightning strike attack on an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, while increasing his own Physical Damage by 10% and speed by 10% for 2 turns (can stack for 2 turns). The Complete Susanoo has a 50% chance to perform a combo.',
		describe_th = 'อุจิวะ อิทาจิ โบกปีกของเขาโจมตีด้วยฟ้าผ่าใส่เป้าหมายศัตรู ทำ #C0xE69900#100% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# พร้อมทั้งเพิ่มความเสียหายทางกายภาพของตัวเองขึ้น 10% และความเร็วขึ้น 10% เป็นเวลา 2 เทิร์น (สามารถสะสมได้ 2 เทิร์น) Complete Susanoo มีโอกาส 50% ในการทำคอมโบ',
		describe_in = 'Uchiha Itachi mengibaskan sayapnya untuk melancarkan serangan petir ke musuh, memberikan #C0xE69900#100% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, sekaligus meningkatkan Kerusakan Fisik dirinya sendiri sebesar 10% dan kecepatan sebesar 10% selama 2 giliran (dapat menumpuk hingga 2 giliran). Complete Susanoo memiliki peluang 50% untuk melakukan combo.',
		describe_ph = 'Uchiha Itachi ayin ang kanyang mga pakpak upang maglunsad ng kidlat na pag-atake sa isang kalaban, na nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, kasabay ng pagtaas ng kanyang sariling Pisikal na Pinsala ng 10% at bilis ng 10% sa loob ng 2 turn (maaaring mag-stack ng 2 turn). Ang Complete Susanoo ay may 50% na tsansa na magsagawa ng combo.',
		describe_ma = 'Uchiha Itachi mengayunkan sayapnya untuk melancarkan serangan kilat pada sasaran musuh, memberikan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, serta meningkatkan Kerosakan Fizikal dirinya sendiri sebanyak 10% dan kelajuan sebanyak 10% selama 2 pusingan (boleh bertindih sehingga 2 pusingan). Complete Susanoo mempunyai peluang 50% untuk menjalankan kombo.',
		describe = 'Uchiha Itachi waves his wings to unleash a lightning strike attack on an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, while increasing his own Physical Damage by 10% and speed by 10% for 2 turns (can stack for 2 turns). The Complete Susanoo has a 50% chance to perform a combo.',
		zawakeEffect = __data_t__zawakeEffect[32211],
		-- {79001}
		zawakeEffectDesc = 'Uchiha Itachi waves his wings to unleash a thunderous attack on an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, while increasing his own Physical Damage by 10% and speed by 10% for 2 turns (can stack up to 2 turns).#F20# \n#F40# Completing Susanoo has a 100% chance to perform a combo.',
		zawakeEffectDesc_en = 'Uchiha Itachi waves his wings to unleash a thunderous attack on an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, while increasing his own Physical Damage by 10% and speed by 10% for 2 turns (can stack up to 2 turns).#F20# \n#F40# Completing Susanoo has a 100% chance to perform a combo.',
		zawakeEffectDesc_th = 'อุจิฮะ อิทาจิ โบกปีกเพื่อปล่อยการโจมตีฟ้าร้องใส่เป้าหมายศัตรู สร้าง #C0xE69900#ความเสียหายทางกายภาพ 100%#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# พร้อมกับเพิ่มความเสียหายทางกายภาพของตนเอง 10% และความเร็ว 10% เป็นเวลา 2 เทิร์น (สามารถสะสมได้ 2 เทิร์น).#F20# \n#F40# การทำ Susanoo เสร็จสมบูรณ์มีโอกาส 100% ในการเรียกคอมโบ',
		zawakeEffectDesc_in = 'Uchiha Itachi mengibaskan sayapnya untuk melancarkan serangan petir ke target musuh, memberikan #C0xE69900#100% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, sekaligus meningkatkan Kerusakan Fisik dirinya sendiri sebesar 10% dan kecepatan sebesar 10% selama 2 giliran (bisa bertumpuk hingga 2 giliran).#F20# \n#F40# Menyelesaikan Susanoo memiliki peluang 100% untuk melakukan combo.',
		zawakeEffectDesc_ph = 'Nililipad ni Uchiha Itachi ang mga pakpak upang maglunsad ng isang kidlat na pag-atake sa isang kalaban na target, na nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, kasabay ng pagtaas ng sariling Pisikal na Pinsala ng 10% at bilis ng 10% sa loob ng 2 turn (maaaring mag-stack ng hanggang 2 turn).#F20# \n#F40# Ang pagkumpleto ng Susanoo ay may 100% na tsansa na magpatupad ng combo.',
		zawakeEffectDesc_ma = 'Uchiha Itachi mengibaskan sayapnya untuk melancarkan serangan petir ke sasaran musuh, memberikan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, sekaligus meningkatkan Kerosakan Fizikal dirinya sendiri sebanyak 10% dan kelajuan sebanyak 10% selama 2 pusingan (boleh bertindih sehingga 2 pusingan).#F20# \n#F40# Menyelesaikan Susanoo mempunyai peluang 100% untuk melakukan combo.',
		zawakeEffectDesc_vn = 'Uchiha Itachi vẫy đôi cánh tung đòn tấn công sấm sét vào một mục tiêu kẻ thù, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, đồng thời tăng sức Sát Thương Vật Lý của bản thân thêm 10% và tốc độ thêm 10% trong 2 lượt (có thể cộng dồn 2 lượt) lần)\n#F20# \n#F40# Hoàn thành Susanoo có 100% cơ hội thực hiện combo.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Complete Susanoo has a 50% chance to perform combo\n#F20# \n#F40##C0x5c9970#→Complete Susanoo has a 100% chance to perform combo',
		zawakeSimpleDesc_en = 'Complete Susanoo has a 50% chance to perform combo\n#F20# \n#F40##C0x5c9970#→Complete Susanoo has a 100% chance to perform combo',
