	[32212] = {
		id = 32212,
		skillName_vn = 'Tsukuyomi Vô Hạn',
		skillName_en = 'Infinite Tsukuyomi',
		skillName_th = 'สึคุโยมิไม่มีที่สิ้นสุด',
		skillName_in = 'Tsukuyomi Tak Terbatas',
		skillName_ph = 'Walang Hanggang Tsukuyomi',
		skillName_ma = 'Tsukuyomi Tanpa Had',
		skillName = 'Infinite Tsukuyomi',
		describe_vn = 'Uchiha Itachi nhảy lên không trung và triệu hồi một luồng điện cực mạnh đánh vào một mục tiêu địch, gây #C0xE69900#180% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, trừ 10% máu của một người và triệu hồi đám mây giông trong 2 lượt (tăng khả năng né tránh thêm 20% và hút máu thêm 20%)\n#F20# \n#F40# Khi Susanoo ở trạng thái toàn thân, máu của hắn sẽ không bị trừ nữa và hắn sẽ phóng ra một tia sét, gây 120% Sát Thương Vật Lý lên mục tiêu địch có lượng máu thấp nhất trên sân.',
		describe_en = 'Uchiha Itachi jumps into the air and summons a powerful lightning strike targeting an enemy, dealing #C0xE69900#180% Physical Damage#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#, reducing one enemy\'s HP by 10% and summoning a thundercloud for 2 turns (increasing evasion by 20% and lifesteal by 20%). \n#F20# \n#F40# When Susanoo is in full body form, his HP will no longer decrease, and he will release a lightning beam dealing 120% Physical Damage to the enemy with the lowest HP on the field.',
		describe_th = 'อุจิฮะ อิทาจิ กระโดดขึ้นกลางอากาศและเรียกสายฟ้าพลังแรงโจมตีศัตรูเป้าหมาย สร้าง #C0xE69900#180% ความเสียหายทางกายภาพ#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# ลดพลังชีวิตของศัตรูหนึ่งคนลง 10% และเรียกเมฆพายุฟ้าผ่าเป็นเวลา 2 เทิร์น (เพิ่มโอกาสหลบหลีก 20% และดูดเลือด 20%) \n#F20# \n#F40# เมื่อซุซาโนะอยู่ในสถานะร่างเต็มตัว พลังชีวิตของเขาจะไม่ลดลง และเขาจะปล่อยลำแสงสายฟ้า สร้างความเสียหายทางกายภาพ 120% ต่อศัตรูที่มีพลังชีวิตต่ำที่สุดในสนาม',
		describe_in = 'Uchiha Itachi melompat ke udara dan memanggil sambaran petir yang sangat kuat mengenai satu musuh, memberikan #C0xE69900#180% Damage Fisik#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Damage Fisik #C0x5B545B#, mengurangi 10% HP satu musuh dan memanggil awan badai selama 2 giliran (meningkatkan ketangkasan menghindar sebesar 20% dan serapan darah sebesar 20%). \n#F20# \n#F40# Saat Susanoo dalam bentuk tubuh penuh, HP-nya tidak akan berkurang dan dia akan melepaskan sinar petir yang memberikan 120% Damage Fisik pada musuh dengan HP terendah di medan.',
		describe_ph = 'Uchiha Itachi tumalon sa hangin at nag-summon ng napakalakas na kidlat na tumama sa isang kaaway, nagdudulot ng #C0xE69900#180% Pisikal na Pinsala#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, nagpapababa ng 10% ng HP ng isang tao at nag-summon ng bagyong ulap sa loob ng 2 turn (nagpapataas ng 20% dagdag na pag-iwas at 20% dagdag na lifesteal). \n#F20# \n#F40# Kapag ang Susanoo ay nasa buong katawan na estado, ang kanyang HP ay hindi na mababawasan at magpapalabas siya ng kidlat na sinag na nagdudulot ng 120% Pisikal na Pinsala sa kaaway na may pinakamababang HP sa larangan.',
		describe_ma = 'Uchiha Itachi melompat ke udara dan memanggil petir yang sangat kuat menyerang satu musuh, menyebabkan #C0xE69900#180% Kerosakan Fizikal#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, mengurangkan 10% darah satu orang dan memanggil awan ribut selama 2 giliran (meningkatkan kemampuan mengelak sebanyak 20% dan penyerapan darah sebanyak 20%). \n#F20# \n#F40# Apabila Susanoo berada dalam keadaan badan penuh, darahnya tidak akan berkurang lagi dan dia akan memancarkan sinar petir yang menyebabkan 120% Kerosakan Fizikal kepada musuh dengan darah terendah di medan pertempuran.',
		describe = 'Uchiha Itachi jumps into the air and summons a powerful lightning strike targeting an enemy, dealing #C0xE69900#180% Physical Damage#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#, reducing one enemy\'s HP by 10% and summoning a thundercloud for 2 turns (increasing evasion by 20% and lifesteal by 20%). \n#F20# \n#F40# When Susanoo is in full body form, his HP will no longer decrease, and he will release a lightning beam dealing 120% Physical Damage to the enemy with the lowest HP on the field.',
		zawakeEffect = __data_t__zawakeEffect[32212],
		-- {79002}
		zawakeEffectDesc = 'Uchiha Itachi leaps into the air and summons an extremely strong electric current to strike an enemy target, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# Physical Damage #C0x5B545B#, sacrificing 10% of his own HP and summoning a thundercloud for 2 turns (increasing evasion by 25% and lifesteal by 25%)\n#F20# \n#F40# When Susanoo is in full body state, his HP will no longer decrease and he will release a lightning beam, dealing 180% Physical Damage to the enemy target with the lowest HP on the field.',
		zawakeEffectDesc_en = 'Uchiha Itachi leaps into the air and summons an extremely strong electric current to strike an enemy target, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# Physical Damage #C0x5B545B#, sacrificing 10% of his own HP and summoning a thundercloud for 2 turns (increasing evasion by 25% and lifesteal by 25%)\n#F20# \n#F40# When Susanoo is in full body state, his HP will no longer decrease and he will release a lightning beam, dealing 180% Physical Damage to the enemy target with the lowest HP on the field.',
		zawakeEffectDesc_th = 'อุจิฮะ อิทาจิ กระโดดขึ้นสู่อากาศและเรียกกระแสไฟฟ้าที่แรงมากโจมตีเป้าหมายศัตรู สร้าง #C0xE69900#180% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# แลกกับการสูญเสีย HP ของตนเอง 10% และเรียกเมฆพายุฟ้าผ่าเป็นเวลา 2 เทิร์น (เพิ่มการหลบหลีก 25% และดูดเลือด 25%)\n#F20# \n#F40# เมื่อซุซาโนโอะอยู่ในสถานะร่างเต็ม ตัวเขาจะไม่เสียเลือดอีกต่อไปและจะปล่อยสายฟ้าโจมตี สร้าง 180% ความเสียหายทางกายภาพกับเป้าหมายศัตรูที่มี HP ต่ำที่สุดบนสนาม',
		zawakeEffectDesc_in = 'Uchiha Itachi meloncat ke udara dan memanggil arus listrik yang sangat kuat untuk menyerang target musuh, memberikan #C0xE69900#180% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#, mengorbankan 10% HP miliknya sendiri dan memanggil awan badai selama 2 giliran (meningkatkan penghindaran 25% dan pencurian darah 25%)\n#F20# \n#F40# Ketika Susanoo dalam keadaan tubuh penuh, HP-nya tidak akan berkurang lagi dan dia akan melepaskan sinar petir, memberikan 180% Kerusakan Fisik pada target musuh dengan HP terendah di medan pertempuran.',
		zawakeEffectDesc_ph = 'Uchiha Itachi tumalon pataas at tumawag ng napakalakas na kuryenteng pangkalawakan upang tamaan ang isang kalaban na target, nagdudulot ng #C0xE69900#180% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, nagbawas ng 10% ng sariling HP at tumawag ng isang ulap ng bagyo sa loob ng 2 turns (nagpapataas ng pag-iwas ng 25% at pag-sipsip ng dugo ng 25%)\n#F20# \n#F40# Kapag ang Susanoo ay nasa buong katawan na estado, ang kanyang HP ay hindi na mababawasan at magpapalabas siya ng kidlat, na nagdudulot ng 180% Pisikal na Pinsala sa kalabang target na may pinakamababang HP sa labanan.',
		zawakeEffectDesc_ma = 'Uchiha Itachi melompat ke udara dan memanggil arus elektrik yang sangat kuat untuk menyerang sasaran musuh, memberikan #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, mengorbankan 10% HP dirinya sendiri dan memanggil awan ribut selama 2 pusingan (meningkatkan elakan 25% dan penyedut darah 25%)\n#F20# \n#F40# Apabila Susanoo berada dalam keadaan badan penuh, HPnya tidak akan berkurang lagi dan dia akan melepaskan pancaran kilat, memberikan 180% Kerosakan Fizikal kepada sasaran musuh dengan HP terendah di medan pertempuran.',
		zawakeEffectDesc_vn = 'Uchiha Itachi nhảy lên không trung và triệu hồi một dòng điện cực mạnh đánh vào một mục tiêu địch, gây #C0xE69900#180% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, trừ 10% HP của bản thân và triệu hồi đám mây giông trong 2 lượt (tăng né tránh 25% và hút máu 25%)\n#F20# \n#F40# Khi Susanoo ở trạng thái toàn thân, máu của hắn sẽ không bị trừ nữa và hắn sẽ phóng ra một tia sét, gây 180% Sát Thương Vật Lý lên mục tiêu địch có lượng máu thấp nhất trên sân.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increase Evasion and Lifesteal by 20%, and lightning strike deals 120% Physical Damage\n#F20# \n#F40##C0x5c9970#→Increase Evasion and Lifesteal by 25%, and lightning strike deals 180% Physical Damage',
		zawakeSimpleDesc_en = 'Increase Evasion and Lifesteal by 20%, and lightning strike deals 120% Physical Damage\n#F20# \n#F40##C0x5c9970#→Increase Evasion and Lifesteal by 25%, and lightning strike deals 180% Physical Damage',
		zawakeSimpleDesc_th = 'เพิ่มการหลบหลีก 20% และดูดเลือด 20%, สายฟ้าฟาดสร้างความเสียหายกายภาพ 120%\n#F20# \n#F40##C0x5c9970#→เพิ่มการหลบหลีก 25% และดูดเลือด 25%, สายฟ้าฟาดสร้างความเสียหายกายภาพ 180%',
		zawakeSimpleDesc_in = 'Meningkatkan Evasion dan Lifesteal sebesar 20%, dan sambaran petir memberikan 120% Physical Damage\n#F20# \n#F40##C0x5c9970#→Meningkatkan Evasion dan Lifesteal sebesar 25%, dan sambaran petir memberikan 180% Physical Damage',
		zawakeSimpleDesc_ph = 'Dagdagan ang Evasion at Lifesteal ng 20%, at ang kidlat ay nagdudulot ng 120% Physical Damage\n#F20# \n#F40##C0x5c9970#→Dagdagan ang Evasion at Lifesteal ng 25%, at ang kidlat ay nagdudulot ng 180% Physical Damage',
		zawakeSimpleDesc_ma = 'Meningkatkan Elakan dan Hisapan Nyawa sebanyak 20%, dan kilat memberikan 120% Kerosakan Fizikal\n#F20# \n#F40##C0x5c9970#→Meningkatkan Elakan dan Hisapan Nyawa sebanyak 25%, dan kilat memberikan 180% Kerosakan Fizikal',
		zawakeSimpleDesc_vn = 'Tăng khả năng né tránh thêm 20% và hút máu thêm 20%, đồng thời sét đánh gây 120% Sát Thương Vật Lý\n#F20# \n#F40##C0x5c9970#→Tăng khả năng né tránh thêm 25% và hút máu thêm 25%, đồng thời sét đánh gây 180% Sát Thương Vật Lý',
		upLvDesc = 'Fixed damage +240',
		upLvDesc_en = 'Fixed damage +240',
		upLvDesc_th = 'ดาเมจคงที่ +240',
		upLvDesc_in = 'Kerusakan tetap +240',
