	[32213] = {
		id = 32213,
		skillName_vn = 'Susanoo',
		skillName_en = 'Susanoo',
		skillName_th = 'ซูซาโนะโอะ',
		skillName_in = 'Susanoo',
		skillName_ph = 'Susanoo',
		skillName_ma = 'Susanoo',
		skillName = 'Susanoo',
		describe_vn = 'Uchiha Itachi kiêu hãnh đứng trên nóc tòa nhà, bộc phát dòng điện dao động hàng trăm triệu volt xuyên qua bầu trời, gây #C0xE69900#360% Sát Thương Vật Lý #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, bạn sẽ nhận được 3 [Tiên Seeds] ngay trước khi tung ra chiêu thức đặc biệt. Hạt Giống Tiên tràn tràn sẽ chuyển thành 100 điểm cuồng nộ\n#F20# \n#F40#Susanoo hoàn chỉnh tấn công mục tiêu tầm xa, gây #C0xE69900#360% Sát Thương Vật Lý#C0x5B545B# vào mục tiêu chính (các mục tiêu còn lại: #C0xE69900#180% Sát Thương Vật Lý#C0x5B545B# ) + $(skillLevel*4*60)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B# và có 40% khả năng [làm tê liệt] mục tiêu trong 1 hiệp; khi bắt đầu ép xung lần đầu tiên, một chiêu thức đặc biệt sẽ được tung ra vào đầu vòng tiếp theo mà không tiêu tốn.',
		describe_en = 'Uchiha Itachi proudly stands on the rooftop, unleashing electric currents fluctuating hundreds of millions of volts across the sky, dealing #C0xE69900#360% Physical Damage #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#. You will receive 3 [Tien Seeds] immediately before casting the special move. The overflowing Tien Seeds convert into 100 rage points. \n#F20# \n#F40# Complete Susanoo attacks a long-range target, dealing #C0xE69900#360% Physical Damage#C0x5B545B# to the main target (other targets: #C0xE69900#180% Physical Damage#C0x5B545B# ) + $(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B# and has a 40% chance to [paralyze] the target for 1 turn; when initiating the first overclock, a special move will be triggered at the beginning of the next round without consuming resources.',
		describe_th = 'อุจิวะ อิทาจิเผยร่างสง่างามเหนือท้องฟ้า ใช้เนตรขั้นสุดยอด "สุซาโนโอะ" โจมตีเป้าหมาย สร้างความเสียหายกายภาพ #C0xE69900#380% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*60)$ เป็น #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# ก่อนปล่อยท่าไม้ตายจะได้รับ [เมล็ดเซียน] 3 เมล็ดทันที เมล็ดเซียนส่วนเกินจะเปลี่ยนเป็นพลังโกรธ 100 หน่วย #F20# #F40# เมื่ออยู่ในร่างสุซาโนโอะสมบูรณ์แบบ จะโจมตีเป้าหมายในรูปกากบาท โดยเป้าหมายหลักจะได้รับความเสียหายกายภาพ #C0xE69900#480% พลังโจมตีกายภาพ#C0x5B545B# ส่วนเป้าหมายอื่นจะได้รับ #C0xE69900#380% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*60)$ เป็น #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# และมีโอกาส 40% ทำให้เป้าหมาย [เป็นอัมพาต] 1 เทิร์น ครั้งแรกที่เข้าสู่ร่างสุซาโนโอะสมบูรณ์แบบ จะสามารถใช้ท่าไม้ตายฟรี 1 ครั้งโดยไม่เสียพลังโกรธในรอบใหญ่ถัดไป',
		describe_in = 'Uchiha Itachi berdiri dengan bangga di atas atap, melepaskan arus listrik yang berfluktuasi ratusan juta volt menembus langit, menyebabkan #C0xE69900#360% Kerusakan Fisik #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#. Kamu akan menerima 3 [Biji Tien] tepat sebelum melancarkan serangan khusus. Biji Tien yang melimpah akan berubah menjadi 100 poin amarah. \n#F20# \n#F40# Susanoo lengkap menyerang target jarak jauh, menyebabkan #C0xE69900#360% Kerusakan Fisik#C0x5B545B# ke target utama (target lain: #C0xE69900#180% Kerusakan Fisik#C0x5B545B#) + $(skillLevel*4*60)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B# dan memiliki peluang 40% untuk [melumpuhkan] target selama 1 giliran; saat memulai overclock pertama kali, serangan khusus akan dilancarkan di awal giliran berikutnya tanpa menghabiskan sumber daya.',
		describe_ph = 'Uchiha Itachi ayamang proud na nakatayo sa bubong, nagpapalabas ng kuryente na umuuga ng daan-daang milyong volt na pumapailanlang sa kalangitan, nagdudulot ng #C0xE69900#360% Pisikal na Pinsala #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Pisikal na Pinsala #C0x5B545B#. Makakatanggap ka ng 3 [Tien Seeds] bago ilabas ang espesyal na galaw. Ang dami ng Tien Seeds ay magbabago sa 100 puntos ng galit. \n#F20# \n#F40# Kumpletong Susanoo ang umatake sa malayong target, nagdudulot ng #C0xE69900#360% Pisikal na Pinsala#C0x5B545B# sa pangunahing target (ibang mga target: #C0xE69900#180% Pisikal na Pinsala#C0x5B545B#) + $(skillLevel*4*60)$ #C0xF13B54# Pisikal na Pinsala #C0x5B545B# at may 40% na posibilidad na [maparalisa] ang target sa loob ng 1 turn; kapag sinimulan ang unang overclock, isang espesyal na galaw ang ilalabas sa simula ng susunod na round nang hindi kumakain ng resources.',
		describe_ma = 'Uchiha Itachi berdiri dengan megah di atas bumbung, melepaskan arus elektrik yang bergetar ratusan juta volt menyeberangi langit, menyebabkan #C0xE69900#360% Kerosakan Fizikal #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#. Anda akan menerima 3 [Biji Tien] serta-merta sebelum melancarkan serangan khas. Biji Tien yang melimpah akan bertukar menjadi 100 mata kemarahan. \n#F20# \n#F40# Susanoo lengkap menyerang sasaran jarak jauh, menyebabkan #C0xE69900#360% Kerosakan Fizikal#C0x5B545B# kepada sasaran utama (sasaran lain: #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#) + $(skillLevel*4*60)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B# dan mempunyai peluang 40% untuk [melumpuhkan] sasaran selama 1 pusingan; apabila memulakan overclock kali pertama, serangan khas akan dilancarkan pada permulaan pusingan berikutnya tanpa menggunakan sumber.',
		describe = 'Uchiha Itachi proudly stands on the rooftop, unleashing electric currents fluctuating hundreds of millions of volts across the sky, dealing #C0xE69900#360% Physical Damage #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#. You will receive 3 [Tien Seeds] immediately before casting the special move. The overflowing Tien Seeds convert into 100 rage points. \n#F20# \n#F40# Complete Susanoo attacks a long-range target, dealing #C0xE69900#360% Physical Damage#C0x5B545B# to the main target (other targets: #C0xE69900#180% Physical Damage#C0x5B545B# ) + $(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B# and has a 40% chance to [paralyze] the target for 1 turn; when initiating the first overclock, a special move will be triggered at the beginning of the next round without consuming resources.',
		simDesc_vn = 'Sasuke Itachi ngạo nghễ đứng trên tòa nhà rộng lớn, bộc phát ra dòng điện đan xen hàng trăm triệu vôn xuyên thấu bầu trời, thu được 3 hạt giống thần tiên, có xác suất làm tê liệt mục tiêu. Susanoo hoàn chỉnh có thể tấn công mục tiêu trong phạm vi chéo.',
		simDesc_en = 'Sasuke and Itachi arrogantly stand on a vast building, unleashing intertwined electricity of hundreds of millions of volts that pierce the sky, acquiring 3 divine seeds with a chance to paralyze the target. The complete Susanoo can attack targets within a diagonal range.',
		simDesc_th = 'ซาสึเกะและอิทาจิยืนอย่างหยิ่งผยองบนอาคารขนาดใหญ่ ปล่อยไฟฟ้าสลับซับซ้อนจำนวนหลายร้อยล้านโวลต์ทะลุผ่านท้องฟ้า รับ 3 เมล็ดพันธุ์ศักดิ์สิทธิ์ ซึ่งมีโอกาสทำให้เป้าหมายชาที่สุด Susanoo ที่สมบูรณ์สามารถโจมตีเป้าหมายในระยะทแยงมุมได้',
		simDesc_in = 'Sasuke dan Itachi dengan sombong berdiri di atas gedung besar, memancarkan listrik yang saling terkait sebesar ratusan juta volt menembus langit, memperoleh 3 benih dewa dengan kemungkinan melumpuhkan target. Susanoo lengkap dapat menyerang target dalam jangkauan diagonal.',
		simDesc_ph = 'Sasuke at Itachi ay matapang na nakatayo sa isang malawak na gusali, nagpapalabas ng magkakaibang kuryente na pumapailanglang sa langit ng daan-daang milyong boltahe, nakakuha ng 3 banal na buto na may pagkakataong paralisahin ang target. Ang kompletong Susanoo ay maaaring umatake sa mga target sa saklaw ng dayagonal.',
		simDesc_ma = 'Sasuke dan Itachi berdiri dengan angkuh di atas bangunan besar, memancarkan elektrik berjalin beratus juta volt yang menembusi langit, memperoleh 3 benih ketuhanan dengan peluang melumpuhkan sasaran. Susanoo lengkap boleh menyerang sasaran dalam julat serong.',
		simDesc = 'Sasuke and Itachi arrogantly stand on a vast building, unleashing intertwined electricity of hundreds of millions of volts that pierce the sky, acquiring 3 divine seeds with a chance to paralyze the target. The complete Susanoo can attack targets within a diagonal range.',
		starEffect = __data_t__starEffect[32213],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng thêm: Khi thi triển kỹ năng tất sát dưới trạng thái Susanoo Hoàn Chỉnh, không tiêu hao  <Tiên Chủng> và tăng tỷ lệ gây tê liệt mục tiêu chính lên 80%.',
		starEffectDesc = 'เอฟเฟกต์เพิ่มเติม: ขณะอยู่ในร่างสุซาโนโอะสมบูรณ์แบบ การใช้ท่าไม้ตายจะไม่สิ้นเปลือง [เมล็ดเซียน] และมีโอกาสทำให้เป้าหมายหลัก [เป็นอัมพาต] เพิ่มขึ้นเป็น 100%',
		starEffectDesc_en = 'Additional effect: When using the instant kill skill under the Complete Susanoo state, does not consume <Tiên Chủng> and increases the paralysis rate on the main target by 80%.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ขณะอยู่ในสถานะ [ซุซาโนโอร่างสมบูรณ์] การใช้ท่าไม้ตายจะไม่สิ้นเปลือง [พลังเซียน] และเพิ่มโอกาสทำให้เป้าหมายหลักติดสถานะอัมพาตเป็น 100%',
		starEffectDesc_in = 'Efek tambahan: Saat menggunakan skill pembunuhan instan dalam kondisi Susanoo Lengkap, tidak menghabiskan <Tiên Chủng> dan meningkatkan tingkat kelumpuhan pada target utama sebesar 80%.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag ginamit ang instant kill na kakayahan sa ilalim ng kompletong estado ng Susanoo, hindi nauubos ang <Tiên Chủng> at nadaragdagan ang tsansa ng pag-paralyze sa pangunahing target ng 80%.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila menggunakan kemahiran bunuh serta-merta dalam keadaan Susanoo Lengkap, tidak menggunakan <Tiên Chủng> dan meningkatkan kadar lumpuh pada sasaran utama sebanyak 80%.',
		zawakeEffect = __data_t__zawakeEffect[32213],
		-- {79003}
		zawakeEffectDesc = 'Uchiha Itachi proudly stands on the rooftop, unleashing hundreds of millions of volts of oscillating electric current through the sky, dealing #C0xE69900#360% Physical Damage to the target#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#, you will receive 3 <Tiên Seeds> immediately before casting the special skill. Overflowing Tiên Seeds convert into 150 Frenzy points\n#F20# \n#F40#Complete Susanoo attacks a distant target, dealing #C0xE69900#360% Physical Damage#C0x5B545B# to the primary target (other targets receive #C0xE69900#180% Physical Damage#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#Physical Damage#C0x5B545B# and has a 40% chance to <paralyze> the target for 1 turn; When starting the first two bursts, a special skill will be triggered at the beginning of the next big round without consuming energy.',
		zawakeEffectDesc_en = 'Uchiha Itachi proudly stands on the rooftop, unleashing hundreds of millions of volts of oscillating electric current through the sky, dealing #C0xE69900#360% Physical Damage to the target#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#, you will receive 3 <Tiên Seeds> immediately before casting the special skill. Overflowing Tiên Seeds convert into 150 Frenzy points\n#F20# \n#F40#Complete Susanoo attacks a distant target, dealing #C0xE69900#360% Physical Damage#C0x5B545B# to the primary target (other targets receive #C0xE69900#180% Physical Damage#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#Physical Damage#C0x5B545B# and has a 40% chance to <paralyze> the target for 1 turn; When starting the first two bursts, a special skill will be triggered at the beginning of the next big round without consuming energy.',
		zawakeEffectDesc_th = 'อุชิฮะ อิทาจิ ยืนอย่างภูมิใจบนหลังคาตึก ปล่อยกระแสไฟฟ้าแกว่งหลายร้อยล้านโวลต์ผ่านท้องฟ้า ส่งผล #C0xE69900#360% ความเสียหายกายภาพ ไปยังเป้าหมาย#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# ความเสียหายกายภาพ #C0x5B545B# คุณจะได้รับ 3 <เมล็ดพันธุ์เทียน> ทันที ก่อนใช้สกิลพิเศษ เมล็ดพันธุ์เทียนที่ล้นเหลือจะเปลี่ยนเป็น 150 แต้มความคลั่ง\n#F20# \n#F40#ซูซาโนโอสมบูรณ์โจมตีเป้าหมายระยะไกล ก่อให้เกิด #C0xE69900#360% ความเสียหายกายภาพ#C0x5B545B# กับเป้าหมายหลัก (เป้าหมายอื่นได้รับ #C0xE69900#180% ความเสียหายกายภาพ#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B#และมีโอกาส 40% <ทำให้ชา> เป้าหมายเป็นเวลา 1 เทิร์น; เมื่อเริ่มบูสท์สองครั้งแรก สกิลพิเศษจะถูกปล่อยที่จุดเริ่มต้นของรอบใหญ่ถัดไปโดยไม่ใช่พลังงาน',
		zawakeEffectDesc_in = 'Uchiha Itachi berdiri dengan bangga di atas atap gedung, melepaskan arus listrik berosilasi ratusan juta volt melintasi langit, memberikan #C0xE69900#360% Kerusakan Fisik pada target#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#, kamu akan menerima 3 <Biji Tiên> segera sebelum menggunakan skill khusus. Biji Tiên yang melimpah akan berubah menjadi 150 poin Amukan\n#F20# \n#F40#Susanoo lengkap menyerang target jarak jauh, memberikan #C0xE69900#360% Kerusakan Fisik#C0x5B545B# pada target utama (target lainnya menerima #C0xE69900#180% Kerusakan Fisik#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#Kerusakan Fisik#C0x5B545B# dan memiliki 40% peluang untuk <melumpuhkan> target selama 1 giliran; Saat memulai dua kali ledakan pertama, sebuah skill khusus akan diluncurkan di awal putaran besar berikutnya tanpa mengkonsumsi energi.',
		zawakeEffectDesc_ph = 'Uchiha Itachi ay proud na nakatayo sa bubong ng gusali, nagpapalabas ng oscillating electric current na daan-daang milyon volts sa kalangitan, nagdudulot ng #C0xE69900#360% Physical Damage sa target#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#, makakatanggap ka ng 3 <Tiên Seeds> agad bago gamitin ang special skill. Ang sobrang Tiên Seeds ay magiging 150 points ng Frenzy\n#F20# \n#F40#Kumpletong Susanoo ay umatake sa malayong target, nagdudulot ng #C0xE69900#360% Physical Damage#C0x5B545B# sa pangunahing target (ang ibang mga target ay tatanggap ng #C0xE69900#180% Physical Damage#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#Physical Damage#C0x5B545B# at may 40% na tsansa na <paralyze> ang target ng 1 turn; Kapag nagsimula ang unang dalawang bursts, isang special skill ang lalabas sa simula ng susunod na malaking round nang hindi kumokonsumo.',
		zawakeEffectDesc_ma = 'Uchiha Itachi berdiri dengan bangga di atas bumbung bangunan, melepaskan arus elektrik berayun ratusan juta volt melintasi langit, menyebabkan #C0xE69900#360% Kerosakan Fizikal kepada sasaran#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, anda akan menerima 3 <Biji Tiên> dengan serta-merta sebelum melancarkan kemahiran istimewa. Biji Tiên yang melimpah akan bertukar menjadi 150 mata kemarahan\n#F20# \n#F40#Susanoo lengkap menyerang sasaran jarak jauh, menyebabkan #C0xE69900#360% Kerosakan Fizikal#C0x5B545B# kepada sasaran utama (sasaran lain menerima #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B# dan mempunyai peluang 40% untuk <melumpuhkan> sasaran selama 1 pusingan; Apabila memulakan dua letupan pertama, kemahiran istimewa akan dilancarkan pada permulaan pusingan besar seterusnya tanpa menggunakan tenaga.',
		zawakeEffectDesc_vn = 'Uchiha Itachi kiêu hãnh đứng trên nóc tòa nhà, bộc phát dòng điện dao động hàng trăm triệu volt xuyên qua bầu trời, gây #C0xE69900#360% Sát Thương Vật Lý vào mục tiêu#C0x5B545B#+$(skillLeve l*4*60)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, bạn sẽ nhận được 3 <Tiên Seeds> ngay trước khi tung ra chiêu thức đặc biệt. Hạt Giống Tiên tràn tràn sẽ chuyển thành 150 điểm cuồng nộ\n#F20# \n#F40#Susanoo hoàn chỉnh tấn công mục tiêu tầm xa, gây #C0xE69900#360% Sát Thương Vật Lý#C0x5B545B# vào mục tiêu chính (các mục tiêu còn lại: #C0xE69900#180% Sát Thương Vật Lý#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B# và có 40% khả năng <làm tê liệt> mục tiêu trong 1 lượt; Khi bắt đầu ép xung hai lần đầu tiên, một chiêu thức đặc biệt sẽ được tung ra vào đầu vòng lớn tiếp theo mà không tiêu hao.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Overflowing divine seed will convert into 100 Rage. Upon first Overdrive entry, a special skill will be released at the start of the next major round without cost\n#F20# \n#F40##C0x5c9970# →Overflowing divine seed will convert into 150 Rage. Upon first two Overdrive entries, a special skill will be released for free at the start of the next major round.',
		zawakeSimpleDesc_en = 'Overflowing divine seed will convert into 100 Rage. Upon first Overdrive entry, a special skill will be released at the start of the next major round without cost\n#F20# \n#F40##C0x5c9970# →Overflowing divine seed will convert into 150 Rage. Upon first two Overdrive entries, a special skill will be released for free at the start of the next major round.',
		zawakeSimpleDesc_th = 'เมล็ดเทพที่ล้นจะถูกแปลงเป็น 100 โทสะ เมื่อเข้าสู่โอเวอร์ไดรฟ์ครั้งแรก จะปล่อยท่าไม้ตายฟรีในรอบใหญ่ถัดไป\n#F20# \n#F40##C0x5c9970# →เมล็ดเทพที่ล้นจะถูกแปลงเป็น 150 โทสะ เมื่อเข้าสู่โอเวอร์ไดรฟ์สองครั้งแรก จะปล่อยท่าไม้ตายฟรีในรอบใหญ่ถัดไป',
		zawakeSimpleDesc_in = 'Biji dewa yang melimpah akan berubah menjadi 100 Rage. Saat memasuki Overdrive pertama, skill spesial akan dikeluarkan gratis di awal ronde besar berikutnya\n#F20# \n#F40##C0x5c9970# →Biji dewa yang melimpah akan berubah menjadi 150 Rage. Saat dua kali pertama Overdrive, skill spesial akan dikeluarkan gratis di awal ronde besar berikutnya',
		zawakeSimpleDesc_ph = 'Ang labis na binhi ng diyos ay magiging 100 Rage. Sa unang Overdrive, isang espesyal na skill ay awtomatikong ilalabas sa susunod na malaking round\n#F20# \n#F40##C0x5c9970# →Ang labis na binhi ng diyos ay magiging 150 Rage. Sa unang dalawang Overdrive, isang espesyal na skill ay ilalabas nang libre sa susunod na malaking round',
		zawakeSimpleDesc_ma = 'Benih suci melimpah akan ditukar menjadi 100 Kemarahan. Ketika pertama kali memasuki Overdrive, satu kemahiran khas akan dilancarkan secara percuma pada permulaan pusingan besar seterusnya\n#F20# \n#F40##C0x5c9970# →Benih suci melimpah akan ditukar menjadi 150 Kemarahan. Dalam dua Overdrive pertama, kemahiran khas akan dilancarkan secara percuma pada permulaan pusingan besar seterusnya',
		zawakeSimpleDesc_vn = 'Tràn hạt giống thần tiên sẽ được chuyển đổi thành 100 điểm thịnh nộ. Khi tham gia Ép xung lần đầu tiên, một chiêu thức đặc biệt sẽ được tung ra mà không tiêu hao khi bắt đầu vòng lớn tiếp theo\n#F20# \n#F40##C0x5c9970# → Tràn hạt giống thần tiên sẽ được chuyển đổi thành 150 điểm thịnh nộ. Khi tham gia ép xung hai lần đầu tiên, một chiêu thức đặc biệt sẽ được tung ra miễn phí khi bắt đầu vòng lớn tiếp theo.',
