	[32221] = {
		id = 32221,
		skillName_vn = 'Susana thổi',
		skillName_en = 'Susana blows',
		skillName_th = 'ซูซาน่าพัด',
		skillName_in = 'Susana meniup',
		skillName_ph = 'Si Susana humihip',
		skillName_ma = 'Susana meniup',
		skillName = 'Susana blows',
		describe_vn = 'Uchiha Itachi vẫy đôi cánh tung đòn tấn công sấm sét vào một mục tiêu kẻ thù, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, đồng thời tăng sức Sát Thương Vật Lý của bản thân thêm 10% và tốc độ thêm 10% trong 2 lượt (có thể cộng dồn 2 lượt) lần)\n#F20# \n#F40# Complete Susanoo có 50% cơ hội thực hiện combo.',
		describe_en = 'Uchiha Itachi waves his wings to unleash a thunder strike attack on an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, while increasing his own Physical Damage by 10% and speed by 10% for 2 turns (can stack for 2 turns). Complete Susanoo has a 50% chance to perform a combo.',
		describe_th = 'อุจิฮะ อิทาจิ โบกปีกของเขาเพื่อปล่อยการโจมตีสายฟ้าขึ้นใส่เป้าหมายศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#100%#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# พร้อมกับเพิ่มความเสียหายทางกายภาพของตัวเอง 10% และความเร็ว 10% เป็นเวลา 2 เทิร์น (สามารถทบได้ 2 เทิร์น) Complete Susanoo มีโอกาส 50% ในการทำคอมโบ',
		describe_in = 'Uchiha Itachi mengayunkan sayapnya untuk melancarkan serangan petir ke target musuh, memberikan #C0xE69900#100% Damage Fisik#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Damage Fisik#C0x5B545B#, sekaligus meningkatkan Damage Fisik dirinya sendiri sebesar 10% dan kecepatan sebesar 10% selama 2 giliran (dapat bertumpuk hingga 2 giliran). Complete Susanoo memiliki peluang 50% untuk melakukan combo.',
		describe_ph = 'Uchiha Itachi ayusin ang kanyang mga pakpak para maglunsad ng kidlat na pag-atake sa isang kalaban, nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, kasabay ng pagtaas ng kanyang sariling Pisikal na Pinsala ng 10% at bilis ng 10% sa loob ng 2 turn (pwedeng mag-stack ng 2 turn). Ang Complete Susanoo ay may 50% tsansa na magsagawa ng combo.',
		describe_ma = 'Uchiha Itachi mengibaskan sayapnya untuk melancarkan serangan kilat ke sasaran musuh, menyebabkan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, serta meningkatkan Kerosakan Fizikal dirinya sendiri sebanyak 10% dan kelajuan sebanyak 10% selama 2 pusingan (boleh bertindih untuk 2 pusingan). Complete Susanoo mempunyai peluang 50% untuk melaksanakan combo.',
		describe = 'Uchiha Itachi waves his wings to unleash a thunder strike attack on an enemy target, dealing #C0xE69900#100% Physical Damage#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, while increasing his own Physical Damage by 10% and speed by 10% for 2 turns (can stack for 2 turns). Complete Susanoo has a 50% chance to perform a combo.',
		zawakeEffect = __data_t__zawakeEffect[32221],
		-- {79001}
		zawakeEffectDesc = 'Uchiha Itachi waves his wings and unleashes a lightning attack on an enemy target, causing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, while increasing his own Physical Damage by 10% and speed by 10% for 2 turns (can be stacked for 2 turns) \n#F20# \n#F40# Completing Susanoo has a 100% chance to perform a combo.',
		zawakeEffectDesc_en = 'Uchiha Itachi waves his wings and unleashes a lightning attack on an enemy target, causing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, while increasing his own Physical Damage by 10% and speed by 10% for 2 turns (can be stacked for 2 turns) \n#F20# \n#F40# Completing Susanoo has a 100% chance to perform a combo.',
		zawakeEffectDesc_th = 'อุจิฮะ อิทาจิ โบกปีกและปล่อยการโจมตีฟ้าผ่าใส่เป้าหมายศัตรู สร้าง #C0xE69900#100% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# พร้อมทั้งเพิ่มความเสียหายทางกายภาพของตนเองขึ้น 10% และความเร็วขึ้น 10% เป็นเวลา 2 เทิร์น (สามารถสะสมได้ 2 เทิร์น) \n#F20# \n#F40# การทำ Susanoo สำเร็จมีโอกาส 100% ในการทำคอมโบ',
		zawakeEffectDesc_in = 'Uchiha Itachi mengibaskan sayapnya dan melancarkan serangan petir ke musuh target, menyebabkan #C0xE69900#100% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, sekaligus meningkatkan Kerusakan Fisik dirinya sendiri sebesar 10% dan kecepatan sebesar 10% selama 2 giliran (dapat ditumpuk selama 2 giliran) \n#F20# \n#F40# Menyelesaikan Susanoo memiliki peluang 100% untuk melakukan combo.',
		zawakeEffectDesc_ph = 'Iwinagay ni Uchiha Itachi ang kanyang mga pakpak at nagpapalabas ng kidlat na pag-atake sa isang kaaway, na nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, kasabay ng pagtaas ng kanyang Pisikal na Pinsala ng 10% at bilis ng 10% sa loob ng 2 turn (maaaring mag-stack hanggang 2 turn) \n#F20# \n#F40# Ang pagtatapos ng Susanoo ay may 100% na tsansa na makagawa ng combo.',
		zawakeEffectDesc_ma = 'Uchiha Itachi mengibaskan sayapnya dan melancarkan serangan kilat ke sasaran musuh, menyebabkan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, sambil meningkatkan Kerosakan Fizikal dirinya sendiri sebanyak 10% dan kelajuan sebanyak 10% selama 2 pusingan (boleh bertindih selama 2 pusingan) \n#F20# \n#F40# Menyelesaikan Susanoo mempunyai peluang 100% untuk melakukan combo.',
		zawakeEffectDesc_vn = 'Uchiha Itachi vẫy đôi cánh tung đòn tấn công sấm sét vào một mục tiêu kẻ thù, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, đồng thời tăng sức Sát Thương Vật Lý của bản thân thêm 10% và tốc độ thêm 10% trong 2 lượt (có thể cộng dồn 2 lượt) lần)\n#F20# \n#F40# Hoàn thành Susanoo có 100% cơ hội thực hiện combo.',
