	[32222] = {
		id = 32222,
		skillName_vn = 'Thuật Đồng Nguyệt Độc',
		skillName_en = 'Alchemist of the Poisoned Moon',
		skillName_th = 'นักเล่นแร่แปรธาตุแห่งพระจันทร์พิษ',
		skillName_in = 'Alkemis Bulan Beracun',
		skillName_ph = 'Alkemista ng Nakakalason na Buwan',
		skillName_ma = 'Ahli Kimia Bulan Beracun',
		skillName = 'Alchemist of the Poisoned Moon',
		describe_vn = 'Uchiha Itachi nhảy lên không trung và triệu hồi một luồng điện cực mạnh đánh vào một mục tiêu địch, gây #C0xE69900#180% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, trừ 10% máu của một người và triệu hồi đám mây giông trong 2 lượt (tăng khả năng né tránh thêm 20% và hút máu thêm 20%)\n#F20# \n#F40# Khi Susanoo ở trạng thái toàn thân, máu của hắn sẽ không bị trừ nữa và hắn sẽ phóng ra một tia sét, gây 120% Sát Thương Vật Lý lên mục tiêu địch có lượng máu thấp nhất trên sân.',
		describe_en = 'Uchiha Itachi leaps into the air and summons a powerful electric current to strike an enemy target, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#, reducing 10% of one person\'s HP and summoning a thundercloud for 2 turns (increasing evasion by 20% and life steal by 20%)\n#F20# \n#F40# When Susanoo is in full body state, his HP will no longer decrease and he will release a lightning beam, dealing 120% Physical Damage to the enemy target with the lowest HP on the field.',
		describe_th = 'อุจิฮะ อิตาจิ กระโดดขึ้นสู่อากาศและเรียกกระแสไฟฟ้าที่ทรงพลังโจมตีเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#180%#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B#, ลดพลังชีวิตของหนึ่งคน 10% และเรียกก้อนเมฆฟ้าผ่าใน 2 เทิร์น (เพิ่มความสามารถในการหลบหลีก 20% และดูดเลือด 20%)\n#F20# \n#F40# เมื่อซุซาโนะอยู่ในสถานะร่างเต็ม ร่างกายของเขาจะไม่เสียพลังชีวิตอีกต่อไปและเขาจะปล่อยแสงฟ้าโจมตีศัตรูที่มีพลังชีวิตน้อยที่สุดบนสนาม สร้างความเสียหายทางกายภาพ 120%',
		describe_in = 'Uchiha Itachi melompat ke udara dan memanggil aliran listrik yang sangat kuat untuk menyerang target musuh, memberikan #C0xE69900#180% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#, mengurangi 10% darah satu orang dan memanggil awan badai selama 2 giliran (meningkatkan kemampuan menghindar sebesar 20% dan menyerap darah sebesar 20%)\n#F20# \n#F40# Ketika Susanoo berada dalam keadaan tubuh penuh, darahnya tidak akan berkurang lagi dan ia akan meluncurkan sinar petir, memberikan 120% Kerusakan Fisik pada target musuh yang memiliki darah terendah di medan pertempuran.',
		describe_ph = 'Uchiha Itachi tumalon sa hangin at nag-anyaya ng isang malakas na kuryenteng tumama sa isang kalaban, nagdudulot ng #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#, binabawasan ang 10% ng HP ng isang tao at nagpatawag ng ulap ng bagyo sa loob ng 2 turn (pinapataas ang pag-iwas ng 20% at life steal ng 20%)\n#F20# \n#F40# Kapag ang Susanoo ay nasa buong anyo, hindi na mababawasan ang kanyang HP at magpapalabas siya ng kidlat na sinag, na nagdudulot ng 120% Physical Damage sa kaaway na may pinakamababang HP sa larangan.',
		describe_ma = 'Uchiha Itachi melompat ke udara dan memanggil arus elektrik yang sangat kuat untuk menyerang sasaran musuh, memberikan #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, mengurangkan 10% darah seseorang dan memanggil awan ribut selama 2 pusingan (meningkatkan keupayaan mengelak sebanyak 20% dan menyerap darah sebanyak 20%)\n#F20# \n#F40# Apabila Susanoo berada dalam keadaan tubuh penuh, darahnya tidak akan berkurang lagi dan dia akan melepaskan sinar petir, memberikan 120% Kerosakan Fizikal kepada sasaran musuh dengan darah terendah di medan pertempuran.',
		describe = 'Uchiha Itachi leaps into the air and summons a powerful electric current to strike an enemy target, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#, reducing 10% of one person\'s HP and summoning a thundercloud for 2 turns (increasing evasion by 20% and life steal by 20%)\n#F20# \n#F40# When Susanoo is in full body state, his HP will no longer decrease and he will release a lightning beam, dealing 120% Physical Damage to the enemy target with the lowest HP on the field.',
		zawakeEffect = __data_t__zawakeEffect[32222],
		-- {79002}
		zawakeEffectDesc = 'Uchiha Itachi jumps into the air and summons a powerful electric current to strike an enemy target, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# Physical Damage #C0x5B545B#, sacrificing 10% of his own HP and summoning a thundercloud for 2 turns (increasing evasion by 25% and lifesteal by 25%)\n#F20# \n#F40# When Susanoo is in full body state, his HP will no longer be reduced and he will release a lightning bolt, dealing 180% Physical Damage to the enemy with the lowest HP on the field.',
		zawakeEffectDesc_en = 'Uchiha Itachi jumps into the air and summons a powerful electric current to strike an enemy target, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# Physical Damage #C0x5B545B#, sacrificing 10% of his own HP and summoning a thundercloud for 2 turns (increasing evasion by 25% and lifesteal by 25%)\n#F20# \n#F40# When Susanoo is in full body state, his HP will no longer be reduced and he will release a lightning bolt, dealing 180% Physical Damage to the enemy with the lowest HP on the field.',
		zawakeEffectDesc_th = 'อุจิฮะ อิทาจิ กระโดดขึ้นสู่ท้องฟ้าและเรียกกระแสไฟฟ้าที่ทรงพลังโจมตีเป้าหมายศัตรู สร้าง #C0xE69900#180% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# โดยแลกกับการเสีย HP ของตัวเอง 10% และเรียกก้อนเมฆพายุฟ้าผ่าเป็นเวลา 2 เทิร์น (เพิ่มหลบหลีก 25% และดูดเลือด 25%)\n#F20# \n#F40# เมื่อซุซาโนโอะอยู่ในสภาพร่างเต็มตัว HP ของเขาจะไม่ลดลงอีก และเขาจะปล่อยสายฟ้าโจมตีศัตรูที่มี HP ต่ำที่สุดในสนาม สร้างความเสียหายทางกายภาพ 180%',
		zawakeEffectDesc_in = 'Uchiha Itachi melompat ke udara dan memanggil arus listrik yang sangat kuat untuk menyerang target musuh, memberikan #C0xE69900#180% Damage Fisik#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# Damage Fisik #C0x5B545B#, mengorbankan 10% HP dirinya sendiri dan memanggil awan badai selama 2 giliran (meningkatkan evasion 25% dan lifesteal 25%)\n#F20# \n#F40# Saat Susanoo dalam keadaan penuh badan, HP-nya tidak akan berkurang lagi dan dia akan melepaskan sambaran petir, memberikan 180% Damage Fisik ke musuh dengan HP terendah di medan perang.',
		zawakeEffectDesc_ph = 'Uchiha Itachi tumalon sa hangin at tumawag ng isang napakalakas na kuryente upang tamaan ang isang kalabang target, nagdudulot ng #C0xE69900#180% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, nagbabawas ng 10% ng sarili niyang HP at tumatawag ng isang ulap ng kulog sa loob ng 2 turn (nagtataas ng 25% na pag-iwas at 25% na lifesteal)\n#F20# \n#F40# Kapag ang Susanoo ay nasa full body state, hindi na mababawasan ang kanyang HP at magpapalabas siya ng kidlat, nagdudulot ng 180% Pisikal na Pinsala sa kalabang may pinakamababang HP sa laban.',
		zawakeEffectDesc_ma = 'Uchiha Itachi melompat ke udara dan memanggil arus elektrik yang sangat kuat untuk menyerang sasaran musuh, memberikan #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, mengorbankan 10% HP dirinya dan memanggil awan ribut selama 2 pusingan (meningkatkan elakan 25% dan serapan nyawa 25%)\n#F20# \n#F40# Apabila Susanoo berada dalam keadaan badan penuh, HPnya tidak akan dikurangkan lagi dan dia akan memancarkan petir, memberikan 180% Kerosakan Fizikal kepada musuh dengan HP paling rendah di medan pertempuran.',
		zawakeEffectDesc_vn = 'Uchiha Itachi nhảy lên không trung và triệu hồi một dòng điện cực mạnh đánh vào một mục tiêu địch, gây #C0xE69900#180% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*6 0)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, trừ 10% HP của bản thân và triệu hồi đám mây giông trong 2 lượt (tăng né tránh 25% và hút máu 25%)\n#F20# \n#F40# Khi Susanoo ở trạng thái toàn thân, máu của hắn sẽ không bị trừ nữa và hắn sẽ phóng ra một tia sét, gây 180% Sát Thương Vật Lý lên mục tiêu địch có lượng máu thấp nhất trên sân.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increases Evasion and Lifesteal by 25%, and lightning strikes deal 150% Physical Damage.',
		zawakeSimpleDesc_en = 'Increases Evasion and Lifesteal by 25%, and lightning strikes deal 150% Physical Damage.',
		zawakeSimpleDesc_th = 'เพิ่มการหลบหลีก 25% และดูดเลือด 25% และสายฟ้าฟาดสร้างความเสียหายทางกายภาพ 150%',
		zawakeSimpleDesc_in = 'Meningkatkan Evasion dan Lifesteal sebesar 25%, dan serangan petir memberikan 150% Physical Damage.',
		zawakeSimpleDesc_ph = 'Dagdag 25% sa Evasion at Lifesteal, at ang mga kidlat ay magdudulot ng 150% Physical Damage.',
		zawakeSimpleDesc_ma = 'Meningkatkan Elakan dan Hisapan Nyawa sebanyak 25%, dan serangan kilat menyebabkan 150% Kerosakan Fizikal.',
		zawakeSimpleDesc_vn = 'Tăng khả năng né tránh thêm 25% và hút máu thêm 25%, đồng thời các tia sét gây ra 150% Sát Thương Vật Lý',
		changeUnitTrigger = true,
