	[32223] = {
		id = 32223,
		skillName_vn = 'Tô Tô Năng Hồ',
		skillName_en = 'To To Energy Lake',
		skillName_th = 'โต้ โต้ พลังทะเลสาบ',
		skillName_in = 'To To Energi Danau',
		skillName_ph = 'To To Lakas Lawa',
		skillName_ma = 'To To Tenaga Tasik',
		skillName = 'To To Energy Lake',
		describe_vn = 'Uchiha Itachi kiêu hãnh đứng trên nóc tòa nhà, bộc phát dòng điện dao động hàng trăm triệu volt xuyên qua bầu trời, gây #C0xE69900#360% Sát Thương Vật Lý #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, bạn sẽ nhận được 3 [Tiên Seeds] ngay trước khi tung ra chiêu thức đặc biệt. Hạt Giống Tiên tràn tràn sẽ chuyển thành 100 điểm cuồng nộ\n#F20# \n#F40#Susanoo hoàn chỉnh tấn công mục tiêu tầm xa, gây #C0xE69900#360% Sát Thương Vật Lý#C0x5B545B# vào mục tiêu chính (các mục tiêu còn lại: #C0xE69900#180% Sát Thương Vật Lý#C0x5B545B# ) + $(skillLevel*4*60)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B# và có 40% khả năng [làm tê liệt] mục tiêu trong 1 hiệp; khi bắt đầu ép xung lần đầu tiên, một chiêu thức đặc biệt sẽ được tung ra vào đầu vòng tiếp theo mà không tiêu tốn.',
		describe_en = 'Uchiha Itachi proudly stands on the rooftop, unleashing oscillating electric currents of hundreds of millions of volts across the sky, dealing #C0xE69900#360% Physical Damage #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#. You will receive 3 [Sage Seeds] right before releasing the special technique. Overflowing Sage Seeds will convert into 100 rage points. \n#F20# \n#F40# The fully formed Susanoo strikes long-range targets, dealing #C0xE69900#360% Physical Damage#C0x5B545B# to the main target (other targets take #C0xE69900#180% Physical Damage#C0x5B545B#) + $(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B# and has a 40% chance to [paralyze] the target for 1 turn; when the first overclock is triggered, a special technique will be released at the start of the next round without consuming resources.',
		describe_th = 'อุจิฮะ อิตาจิ ภาคภูมิใจยืนอยู่บนหลังคา ปล่อยกระแสไฟกระพริบหลายร้อยล้านโวลต์ทะลุผ่านท้องฟ้า สร้างความเสียหายทางกายภาพ #C0xE69900#360% #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# คุณจะได้รับ [เมล็ดพันธุ์เซน] 3 เมล็ดทันที ก่อนปล่อยท่าไม้ตาย เมล็ดพันธุ์เซนที่ล้นจะเปลี่ยนเป็น 100 คะแนนความโกรธ \n#F20# \n#F40# ซูซาโน่เต็มรูปแบบโจมตีเป้าหมายระยะไกล สร้างความเสียหายทางกายภาพ #C0xE69900#360%#C0x5B545B# กับเป้าหมายหลัก (เป้าหมายอื่นได้รับ #C0xE69900#180% ความเสียหายทางกายภาพ#C0x5B545B#) + $(skillLevel*4*60)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# และมีโอกาส 40% [ทำให้เป็นอัมพาต] เป้าหมายใน 1 เทิร์น; เมื่อเริ่มโอเวอร์คล็อกครั้งแรก ท่าไม้ตายจะถูกปล่อยออกมาในรอบถัดไปโดยไม่เสียทรัพยากร',
		describe_in = 'Uchiha Itachi berdiri dengan bangga di atas atap bangunan, melepaskan aliran listrik berosilasi jutaan volt yang menyambar langit, menyebabkan #C0xE69900#360% Kerusakan Fisik #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#. Kamu akan menerima 3 [Benih Sage] tepat sebelum menggunakan jurus spesial. Benih Sage yang melimpah akan berubah menjadi 100 poin kemarahan. \n#F20# \n#F40# Susanoo yang lengkap menyerang target jarak jauh, memberikan #C0xE69900#360% Kerusakan Fisik#C0x5B545B# ke target utama (target lain menerima #C0xE69900#180% Kerusakan Fisik#C0x5B545B#) + $(skillLevel*4*60)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B# dan memiliki peluang 40% untuk [lumpuhkan] target selama 1 giliran; saat overclock pertama kali dimulai, jurus spesial akan diluncurkan pada awal giliran berikutnya tanpa mengeluarkan biaya.',
		describe_ph = 'Si Uchiha Itachi ay proud na nakatayo sa bubong ng gusali, nagpapalabas ng osilating na kuryente na umaabot ng daan-daang milyong boltahe na tumatagos sa kalangitan, nagdudulot ng #C0xE69900#360% Pisikal na Pinsala #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Pisikal na Pinsala #C0x5B545B#. Makakatanggap ka ng 3 [Sage Seeds] bago mo ilabas ang espesyal na teknik. Ang napakaraming Sage Seeds ay magko-convert sa 100 puntos ng galit. \n#F20# \n#F40# Ang ganap na Susanoo ay sumasalakay sa malalayong target, nagdudulot ng #C0xE69900#360% Pisikal na Pinsala#C0x5B545B# sa pangunahing target (ang ibang mga target ay matatanggap ang #C0xE69900#180% Pisikal na Pinsala#C0x5B545B#) + $(skillLevel*4*60)$ #C0xF13B54# Pisikal na Pinsala #C0x5B545B# at may 40% tsansa na [maiparalisa] ang target sa loob ng 1 round; kapag sinimulan ang unang overclock, isang espesyal na teknik ang ilalabas sa simula ng susunod na round nang walang gastos.',
		describe_ma = 'Uchiha Itachi berdiri dengan bangga di atas bumbung bangunan, melepaskan arus elektrik berosilasi beratus juta volt melintasi langit, menyebabkan #C0xE69900#360% Kerosakan Fizikal #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#. Anda akan menerima 3 [Benih Sage] tepat sebelum melancarkan teknik khas. Benih Sage yang melimpah akan bertukar menjadi 100 mata kemarahan. \n#F20# \n#F40# Susanoo lengkap menyerang sasaran jarak jauh, menyebabkan #C0xE69900#360% Kerosakan Fizikal#C0x5B545B# pada sasaran utama (sasaran lain: #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#) + $(skillLevel*4*60)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B# dan mempunyai peluang 40% untuk [melumpuhkan] sasaran selama 1 pusingan; apabila overclock pertama kali bermula, teknik khas akan dilancarkan pada permulaan pusingan berikutnya tanpa mengeluarkan sebarang kos.',
		describe = 'Uchiha Itachi proudly stands on the rooftop, unleashing oscillating electric currents of hundreds of millions of volts across the sky, dealing #C0xE69900#360% Physical Damage #C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#. You will receive 3 [Sage Seeds] right before releasing the special technique. Overflowing Sage Seeds will convert into 100 rage points. \n#F20# \n#F40# The fully formed Susanoo strikes long-range targets, dealing #C0xE69900#360% Physical Damage#C0x5B545B# to the main target (other targets take #C0xE69900#180% Physical Damage#C0x5B545B#) + $(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B# and has a 40% chance to [paralyze] the target for 1 turn; when the first overclock is triggered, a special technique will be released at the start of the next round without consuming resources.',
		simDesc_vn = 'Sasuke Itachi ngạo nghễ đứng trên tòa nhà rộng lớn, bộc phát ra dòng điện đan xen hàng trăm triệu vôn xuyên thấu bầu trời, thu được 3 hạt giống thần tiên, có xác suất làm tê liệt mục tiêu. Susanoo hoàn chỉnh có thể tấn công mục tiêu trong phạm vi chéo.',
		simDesc_en = 'Sasuke Itachi proudly stands on a huge building, unleashing electricity intertwined with hundreds of millions of volts piercing the sky, acquiring 3 divine seeds that have a chance to paralyze the target. A complete Susanoo can attack targets diagonally within range.',
		simDesc_th = 'ซาสึเกะ อิตาจิ ยืนอย่างภาคภูมิใจบนอาคารขนาดใหญ่ ปล่อยกระแสไฟฟ้าที่สอดประสานกันมากกว่าร้อยล้านโวลต์ทะลุฟากฟ้า ได้รับ 3 เมล็ดพันธุ์ศักดิ์สิทธิ์ที่มีโอกาสทำให้เป้าหมายเป็นอัมพาต ซูซาโนโอที่สมบูรณ์แบบสามารถโจมตีเป้าหมายในระยะแนวทแยงได้',
		simDesc_in = 'Sasuke Itachi dengan bangga berdiri di atas gedung besar, melepaskan listrik yang saling terkait dengan ratusan juta volt menembus langit, mendapatkan 3 benih ilahi yang memiliki kemungkinan melumpuhkan target. Susanoo lengkap dapat menyerang target dalam jangkauan diagonal.',
		simDesc_ph = 'Si Sasuke Itachi ay nakataas na nakatayo sa isang malaking gusali, nagpapalabas ng kuryenteng humahalo na may daang-milyong volts na sumasalpok sa kalangitan, nakakuha ng 3 banal na buto na may posibilidad na paralizan ang target. Ang kumpletong Susanoo ay maaaring umatake sa mga target sa loob ng dayagonal na saklaw.',
		simDesc_ma = 'Sasuke Itachi berdiri dengan megah di atas bangunan besar, melepaskan elektrik yang berjalin dengan ratusan juta volt menembusi langit, memperoleh 3 benih ilahi yang berpeluang melumpuhkan sasaran. Susanoo lengkap boleh menyerang sasaran dalam julat serong.',
		simDesc = 'Sasuke Itachi proudly stands on a huge building, unleashing electricity intertwined with hundreds of millions of volts piercing the sky, acquiring 3 divine seeds that have a chance to paralyze the target. A complete Susanoo can attack targets diagonally within range.',
		starEffect = __data_t__starEffect[32223],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi thi triển kỹ năng tất sát dưới trạng thái Susanoo Hoàn Chỉnh, không tiêu hao <Tiên Chủng> và tăng tỷ lệ gây tê liệt mục tiêu chính lên 80%.',
		starEffectDesc = 'Additional effect: When casting the finishing skill under the Complete Susanoo state, <Tiên Chủng> is not consumed and the paralysis chance on the main target is increased to 80%.',
		starEffectDesc_en = 'Additional effect: When casting the finishing skill under the Complete Susanoo state, <Tiên Chủng> is not consumed and the paralysis chance on the main target is increased to 80%.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อใช้สกิลสังหารทันทีในสถานะ Susanoo สมบูรณ์ จะไม่ใช้ <Tiên Chủng> และเพิ่มโอกาสทำให้อัมพาตเป้าหมายหลักเป็น 80%',
		starEffectDesc_in = 'Efek tambahan: Saat menggunakan skill fatal di bawah keadaan Susanoo Lengkap, <Tiên Chủng> tidak dikonsumsi dan meningkatkan peluang melumpuhkan target utama menjadi 80%.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag ginamit ang finishing skill sa ilalim ng Complete Susanoo state, hindi nauubos ang <Tiên Chủng> at tumataas ang tsansa ng paralisis sa pangunahing target ng 80%.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila menggunakan kemahiran pembunuh saat dalam keadaan Susanoo Lengkap, <Tiên Chủng> tidak terpakai dan meningkatkan peluang lumpuh pada sasaran utama sebanyak 80%.',
		zawakeEffect = __data_t__zawakeEffect[32223],
		-- {79003}
		zawakeEffectDesc = 'Uchiha Itachi proudly stands on the rooftop, unleashing oscillating electric currents of hundreds of millions of volts across the sky, dealing #C0xE69900#360% Physical Damage to the target#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#. You will receive 3 <Tiên Seeds> immediately before casting the special skill. Overflowing Tiên Seeds will convert into 150 rage points\n#F20# \n#F40# Complete Susanoo attacks the target at long range, dealing #C0xE69900#360% Physical Damage#C0x5B545B# to the primary target (other targets: #C0xE69900#180% Physical Damage#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#Physical Damage#C0x5B545B# and has a 40% chance to <paralyze> the target for 1 turn; When starting the first two bursts, a special skill will be cast at the beginning of the next major round without cost.',
		zawakeEffectDesc_en = 'Uchiha Itachi proudly stands on the rooftop, unleashing oscillating electric currents of hundreds of millions of volts across the sky, dealing #C0xE69900#360% Physical Damage to the target#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#. You will receive 3 <Tiên Seeds> immediately before casting the special skill. Overflowing Tiên Seeds will convert into 150 rage points\n#F20# \n#F40# Complete Susanoo attacks the target at long range, dealing #C0xE69900#360% Physical Damage#C0x5B545B# to the primary target (other targets: #C0xE69900#180% Physical Damage#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#Physical Damage#C0x5B545B# and has a 40% chance to <paralyze> the target for 1 turn; When starting the first two bursts, a special skill will be cast at the beginning of the next major round without cost.',
		zawakeEffectDesc_th = 'อุจิฮะ อิทาจิ ยืนอย่างภาคภูมิบนหลังคา ปล่อยกระแสไฟฟ้าสั่นสะเทือนหลายร้อยล้านโวลต์ผ่านท้องฟ้า สร้าง #C0xE69900#360% ความเสียหายกายภาพให้กับเป้าหมาย#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# ความเสียหายกายภาพ #C0x5B545B# คุณจะได้รับ 3 <เมล็ดพันธุ์เทียน> ทันที ก่อนใช้สกิลพิเศษ เมล็ดพันธุ์เทียนล้นจะเปลี่ยนเป็น 150 คะแนนความคลั่ง\n#F20# \n#F40# ซูซาโนโอที่สมบูรณ์โจมตีเป้าหมายระยะไกล สร้าง #C0xE69900#360% ความเสียหายกายภาพ#C0x5B545B# ให้กับเป้าหมายหลัก (เป้าหมายอื่น: #C0xE69900#180% ความเสียหายกายภาพ#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# และมีโอกาส 40% ที่จะ <ทำให้อัมพาต> เป้าหมายเป็นเวลา 1 เทิร์น; เมื่อเริ่มการบูสต์สองครั้งแรก สกิลพิเศษจะถูกใช้ที่ต้นรอบใหญ่ถัดไปโดยไม่เสียค่าใช้จ่าย',
		zawakeEffectDesc_in = 'Uchiha Itachi dengan bangga berdiri di atap, melepaskan arus listrik berosilasi ratusan juta volt melintasi langit, memberikan #C0xE69900#360% Kerusakan Fisik kepada target#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#. Anda akan menerima 3 <Biji Tiên> segera sebelum menggunakan keterampilan khusus. Biji Tiên yang melimpah akan berubah menjadi 150 poin kemarahan\n#F20# \n#F40# Susanoo lengkap menyerang target jarak jauh, memberikan #C0xE69900#360% Kerusakan Fisik#C0x5B545B# ke target utama (target lain: #C0xE69900#180% Kerusakan Fisik#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#Kerusakan Fisik#C0x5B545B# dan memiliki peluang 40% untuk <melumpuhkan> target selama 1 giliran; Saat memulai dua letupan pertama, keterampilan khusus akan diluncurkan di awal putaran besar berikutnya tanpa biaya.',
		zawakeEffectDesc_ph = 'Mapagmalaking tumayo si Uchiha Itachi sa bubong, nagpapalabas ng oscillating electric current na daan-daang milyong volts sa himpapawid, na nagdudulot ng #C0xE69900#360% Physical Damage sa target#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#. Makakatanggap ka ng 3 <Tiên Seeds> agad bago gamitin ang espesyal na kakayahan. Ang sobrang Tiên Seeds ay magiging 150 na puntos ng galit\n#F20# \n#F40# Kumpletong Susanoo ay aalis sa target malayo, nagdudulot ng #C0xE69900#360% Physical Damage#C0x5B545B# sa pangunahing target (ang ibang mga target: #C0xE69900#180% Physical Damage#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#Physical Damage#C0x5B545B# at may 40% na tsansang <ma-paralyze> ang target sa loob ng 1 turn; Kapag sinimulan ang unang dalawang burst, isang espesyal na kakayahan ang ilalabas sa simula ng susunod na malaking round nang walang gastos.',
		zawakeEffectDesc_ma = 'Uchiha Itachi berdiri dengan bangga di atas bumbung, melepaskan arus elektrik berayun ratusan juta volt merentasi langit, menyebabkan #C0xE69900#360% Kerosakan Fizikal ke sasaran#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#. Anda akan menerima 3 <Benih Tiên> segera sebelum menggunakan kemahiran khas. Benih Tiên yang melimpah akan bertukar menjadi 150 mata kemarahan\n#F20# \n#F40# Susanoo lengkap menyerang sasaran jarak jauh, menyebabkan #C0xE69900#360% Kerosakan Fizikal#C0x5B545B# kepada sasaran utama (sasaran lain: #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B# dan mempunyai peluang 40% untuk <melumpuhkan> sasaran selama 1 pusingan; Apabila memulakan dua kali lonjakan pertama, satu kemahiran khas akan dilancarkan pada permulaan pusingan besar berikutnya tanpa kos.',
		zawakeEffectDesc_vn = 'Uchiha Itachi kiêu hãnh đứng trên nóc tòa nhà, bộc phát dòng điện dao động hàng trăm triệu volt xuyên qua bầu trời, gây #C0xE69900#360% Sát Thương Vật Lý vào mục tiêu#C0x5B545B#+$(skillLeve l*4*60)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, bạn sẽ nhận được 3 <Tiên Seeds> ngay trước khi tung ra chiêu thức đặc biệt. Hạt Giống Tiên tràn tràn sẽ chuyển thành 150 điểm cuồng nộ\n#F20# \n#F40#Susanoo hoàn chỉnh tấn công mục tiêu tầm xa, gây #C0xE69900#360% Sát Thương Vật Lý#C0x5B545B# vào mục tiêu chính (các mục tiêu còn lại: #C0xE69900#180% Sát Thương Vật Lý#C0x5B545B#) +$(skillLevel*4*60)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B# và có 40% khả năng <làm tê liệt> mục tiêu trong 1 lượt; Khi bắt đầu ép xung hai lần đầu tiên, một chiêu thức đặc biệt sẽ được tung ra vào đầu vòng lớn tiếp theo mà không tiêu hao.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'During the first two Overdrive modes, you can unleash a special move for free before the start of the next major round.',
		zawakeSimpleDesc_en = 'During the first two Overdrive modes, you can unleash a special move for free before the start of the next major round.',
		zawakeSimpleDesc_th = 'ในสองโหมดโอเวอร์ไดรฟ์แรก คุณสามารถปล่อยท่าไม้ตายพิเศษโดยไม่เสียค่าใช้จ่ายก่อนเริ่มรอบใหญ่ถัดไป',
		zawakeSimpleDesc_in = 'Dalam dua mode Overdrive pertama, kamu dapat mengeluarkan jurus spesial secara gratis sebelum ronde besar berikutnya dimulai.',
		zawakeSimpleDesc_ph = 'Sa unang dalawang Overdrive mode, maaari kang maglunsad ng espesyal na galaw nang libre bago magsimula ang susunod na major round.',
		zawakeSimpleDesc_ma = 'Dalam dua mod Overdrive pertama, anda boleh melancarkan gerakan khas secara percuma sebelum pusingan besar seterusnya bermula.',
		zawakeSimpleDesc_vn = 'Trong hai chế độ ép xung đầu tiên, bạn có thể thực hiện một động thái đặc biệt mà không tiêu hao trước khi bắt đầu vòng lớn tiếp theo.',
