	[32226] = {
		id = 32226,
		skillName_vn = 'Vạn Hoa Chi Đồng',
		skillName_en = 'Ten Thousand Flowers Child',
		skillName_th = 'เด็กหมื่นดอกไม้',
		skillName_in = 'Anak Sepuluh Ribu Bunga',
		skillName_ph = 'Sampung Libong Bulaklak na Bata',
		skillName_ma = 'Anak Sepuluh Ribu Bunga',
		skillName = 'Ten Thousand Flowers Child',
		describe_vn = '#L10# Tải hạt giống thần tiên: #L0# Bạn có thể nhận được một [Hạt giống thần tiên] sau mỗi đòn tấn công hoặc cứ sau 10% mạng sống bị mất (#L10# Hạt giống thần tiên: #L0# hiệu ứng buff, chỉ có thể bị xua tan, tăng 5% sát thương sét, tối đa 6, mỗi hạt giống thần tiên sẽ tự phục hồi 50 điểm thịnh nộ khi biến mất)\n#F10# \n#F40# Khi [Fairy Seed] đạt 6, hãy nhập [Hoàn thành] Susanoo] trong 2 hiệp\n#F10# \n#F40##L10#Hoàn thành Susanoo: #L0#Cải thiện bản thân#C0x5c9970#$(25+skillLevel*0.1-0.1)$%#C0x5B545B#Đòn Sát Thương Vật Lý ban đầu và đòn chí mạng (không thể xua tan, dịch chuyển, v.v.), loại bỏ và miễn nhiễm với các hiệu ứng ngủ, ác mộng, tê liệt và giảm cơn thịnh nộ, mỗi loài thần tiên cung cấp 10% khả năng né tránh\n#F10# \n#F40# Không nhận được hạt giống thần tiên nào trong quá trình ép xung. Mỗi đòn tấn công tiêu tốn 1 hạt giống thần tiên. Sau khi quá trình ép xung kết thúc, bản thân [kiệt sức] trong 1 vòng (kiệt sức: hiệu ứng khống chế, không thể di chuyển, có thể bị xua tan)\n#F10# \n#F40##L10#Siêu dẫn vật lý: #L0# Trong 3 vòng đầu tiên tham gia, bạn sẽ nhận được 300/200/100 điểm thịnh nộ tương ứng khi giải phóng các kỹ năng thể chất chủ động.',
		describe_en = '#L10# Divine Seed Loading: #L0# You can obtain a [Divine Seed] after each attack or every 10% of lost HP (#L10# Divine Seed: #L0# buff effect, can only be dispelled, increases lightning damage by 5%, up to 6 stacks, each Divine Seed restores 50 rage points when it disappears) \n#F10# \n#F40# When [Fairy Seed] reaches 6, enter [Complete] Susanoo] for 2 turns \n#F10# \n#F40##L10#Complete Susanoo: #L0# Self-enhancement #C0x5c9970#$(25+skillLevel*0.1-0.1)$%#C0x5B545B# Initial Physical Damage and Critical Hits (cannot be dispelled, displaced, etc.), removes and is immune to sleep, nightmare, paralysis effects and rage reduction, each fairy provides 10% dodge chance \n#F10# \n#F40# No Divine Seeds are gained during overclocking. Each attack consumes 1 Divine Seed. After overclocking ends, you are [exhausted] for 1 turn (exhausted: control effect, cannot move, can be dispelled) \n#F10# \n#F40##L10#Physical Superconductivity: #L0# During the first 3 turns of participation, you will receive 300/200/100 rage points respectively when releasing active physical skills.',
		describe_th = '#L10# กำลังโหลดเมล็ดพันธุ์เทพ: #L0# คุณสามารถได้รับ [เมล็ดพันธุ์เทพ] หลังจากแต่ละการโจมตี หรือทุก ๆ 10% ของพลังชีวิตที่สูญเสียไป (#L10# เมล็ดพันธุ์เทพ: #L0# ผลบัฟ, สามารถถูกลบได้เพียงอย่างเดียว เพิ่มความเสียหายสายฟ้า 5%, สูงสุด 6 ซ้อนกัน, เมล็ดพันธุ์เทพแต่ละเมล็ดฟื้นฟูพลังแค้น 50 จุดเมื่อหายไป) \n#F10# \n#F40# เมื่อ [เมล็ดเทพ] ถึง 6, เข้าสู่ [Susanoo เสร็จสมบูรณ์] เป็นเวลา 2 เทิร์น \n#F10# \n#F40##L10#Susanoo เสร็จสมบูรณ์: #L0# ปรับปรุงตัวเอง #C0x5c9970#$(25+skillLevel*0.1-0.1)$%#C0x5B545B# ความเสียหายทางกายภาพเริ่มต้นและคริติคอล (ไม่สามารถลบหรือย้ายได้ ฯลฯ), ลบและป้องกันผลการหลับ, ฝันร้าย, ชา และลดพลังแค้น, เทพแต่ละตัวให้โอกาสหลบหลีก 10% \n#F10# \n#F40# ไม่ได้รับเมล็ดพันธุ์เทพระหว่างการโอเวอร์คล็อก ทุกการโจมตีใช้เมล็ดพันธุ์เทพ 1 เมล็ด หลังการโอเวอร์คล็อกจบ คุณจะอยู่ในสถานะ [หมดแรง] เป็นเวลา 1 เทิร์น (หมดแรง: สถานะควบคุม, เคลื่อนที่ไม่ได้, ลบออกได้) \n#F10# \n#F40##L10#กระแสไฟฟ้าทางกายภาพ: #L0# ใน 3 เทิร์นแรกของการเข้าร่วม คุณจะได้รับพลังแค้น 300/200/100 ตามลำดับเมื่อใช้สกิลกายภาพแบบแอคทีฟ',
		describe_in = '#L10# Memuat Benih Ilahi: #L0# Anda dapat memperoleh [Benih Ilahi] setelah setiap serangan atau setiap kehilangan 10% HP (#L10# Benih Ilahi: #L0# efek buff, hanya bisa dihapus, meningkatkan 5% kerusakan petir, maksimal 6 tumpukan, setiap Benih Ilahi memulihkan 50 poin kemarahan saat hilang) \n#F10# \n#F40# Saat [Benih Peri] mencapai 6, aktifkan [Susanoo Lengkap] selama 2 giliran \n#F10# \n#F40##L10#Susanoo Lengkap: #L0# Peningkatan diri sendiri #C0x5c9970#$(25+skillLevel*0.1-0.1)$%#C0x5B545B# Kerusakan Fisik Awal dan Serangan Kritis (tidak dapat dihapus, dipindahkan, dll.), menghapus dan kebal terhadap efek tidur, mimpi buruk, kelumpuhan dan pengurangan kemarahan, setiap peri memberikan 10% peluang menghindar \n#F10# \n#F40# Tidak mendapatkan Benih Ilahi selama overclock. Setiap serangan mengonsumsi 1 Benih Ilahi. Setelah overclock selesai, diri sendiri menjadi [kelelahan] selama 1 giliran (kelelahan: efek kendali, tidak bisa bergerak, dapat dihapus) \n#F10# \n#F40##L10#Superkonduktivitas Fisik: #L0# Dalam 3 giliran pertama ikut serta, Anda akan menerima masing-masing 300/200/100 poin kemarahan ketika melepaskan skill fisik aktif.',
		describe_ph = '#L10# Pag-load ng Butil ng Banal: #L0# Maaari kang makakuha ng [Butil ng Banal] pagkatapos ng bawat atake o bawat 10% na nawalang buhay (#L10# Butil ng Banal: #L0# buff effect, maaari lamang matanggal, nagdaragdag ng 5% pinsala sa kidlat, hanggang 6 na stack, bawat Butil ng Banal ay nagbabalik ng 50 puntos ng galit kapag nawala) \n#F10# \n#F40# Kapag umabot ang [Fairy Seed] sa 6, pumasok sa [Kumpletong] Susanoo] sa loob ng 2 turn\n#F10# \n#F40##L10#Kumpletong Susanoo: #L0# Pagpapahusay sa sarili #C0x5c9970#$(25+skillLevel*0.1-0.1)$%#C0x5B545B# Paunang Pisikal na Pinsala at Kritikal na Pagkakasakit (hindi maaaring alisin, ilipat, atbp.), tinatanggal at immune sa mga epekto ng pagtulog, bangungot, paralisis at pagbawas ng galit, bawat engkanto ay nagbibigay ng 10% tsansa na umiwas \n#F10# \n#F40# Walang makukuhang butil ng banal habang nag-overclock. Bawat atake ay gumagamit ng 1 butil ng banal. Matapos ang overclock ay magtapos, ikaw ay magiging [pagod] sa loob ng 1 turn (pagod: control effect, hindi makagalaw, maaaring matanggal) \n#F10# \n#F40##L10#Pisikal na Superkonduktor: #L0# Sa unang 3 turn ng pakikilahok, makakatanggap ka ng 300/200/100 puntos ng galit ayon sa pagkakasunud-sunod kapag naglalabas ng aktibong pisikal na kasanayan.',
		describe_ma = '#L10# Memuat Benih Ilahi: #L0# Anda boleh memperoleh [Benih Ilahi] selepas setiap serangan atau setiap kehilangan 10% kesihatan (#L10# Benih Ilahi: #L0# kesan buff, hanya boleh dibersihkan, meningkat 5% kerosakan elektrik, maksima 6 tumpukan, setiap Benih Ilahi akan pulihkan 50 mata kemarahan apabila hilang) \n#F10# \n#F40# Apabila [Benih Peri] mencapai 6, masuk ke [Selesai] Susanoo] selama 2 pusingan \n#F10# \n#F40##L10#Susanoo Selesai: #L0# Tingkatkan diri sendiri #C0x5c9970#$(25+skillLevel*0.1-0.1)$%#C0x5B545B# Kerosakan Fizikal Asal dan Kritikal (tidak boleh dibersihkan, teralih, dan lain-lain), menghapus dan kebal kepada kesan tidur, mimpi ngeri, lumpuh dan pengurangan kemarahan, setiap peri beri 10% peluang elak \n#F10# \n#F40# Tiada benih ilahi diperoleh semasa overclock. Setiap serangan menggunakan 1 benih ilahi. Selepas overclock berakhir, diri sendiri [keletihan] selama 1 pusingan (keletihan: kesan kawalan, tidak boleh bergerak, boleh dibersihkan) \n#F10# \n#F40##L10#Superkonduktiviti Fizikal: #L0# Dalam 3 pusingan pertama penyertaan, anda akan menerima 300/200/100 mata kemarahan semasa melepaskan kemahiran fizikal aktif.',
		describe = '#L10# Divine Seed Loading: #L0# You can obtain a [Divine Seed] after each attack or every 10% of lost HP (#L10# Divine Seed: #L0# buff effect, can only be dispelled, increases lightning damage by 5%, up to 6 stacks, each Divine Seed restores 50 rage points when it disappears) \n#F10# \n#F40# When [Fairy Seed] reaches 6, enter [Complete] Susanoo] for 2 turns \n#F10# \n#F40##L10#Complete Susanoo: #L0# Self-enhancement #C0x5c9970#$(25+skillLevel*0.1-0.1)$%#C0x5B545B# Initial Physical Damage and Critical Hits (cannot be dispelled, displaced, etc.), removes and is immune to sleep, nightmare, paralysis effects and rage reduction, each fairy provides 10% dodge chance \n#F10# \n#F40# No Divine Seeds are gained during overclocking. Each attack consumes 1 Divine Seed. After overclocking ends, you are [exhausted] for 1 turn (exhausted: control effect, cannot move, can be dispelled) \n#F10# \n#F40##L10#Physical Superconductivity: #L0# During the first 3 turns of participation, you will receive 300/200/100 rage points respectively when releasing active physical skills.',
		starEffect = __data_t__starEffect[32226],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi vào trận nhận 3 Tiên Chủng, khi kết thúc Siêu Tần mỗi  <Tiên Chủng>  gây 50% Công Vật Lý lên tướng địch có lượng máu thấp nhất.',
		starEffectDesc = 'Additional effect: When entering battle, receive 3 #F Tiên Chủng#L, at the end of #F Siêu Tần#L each <#F Tiên Chủng#L> deals 50% Physical Attack to the enemy hero with the lowest HP.',
		starEffectDesc_en = 'Additional effect: When entering battle, receive 3 #F Tiên Chủng#L, at the end of #F Siêu Tần#L each <#F Tiên Chủng#L> deals 50% Physical Attack to the enemy hero with the lowest HP.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อเข้าสู่การต่อสู้ รับ 3 #F Tiên Chủng#L เมื่อสิ้นสุด #F Siêu Tần#L แต่ละ <#F Tiên Chủng#L> จะสร้างความเสียหายกายภาพ 50% ไปยังเจ้าของศัตรูที่มีพลังชีวิตต่ำที่สุด',
		starEffectDesc_in = 'Efek tambahan: Saat memasuki pertempuran terima 3 #F Tiên Chủng#L, saat akhir #F Siêu Tần#L setiap <#F Tiên Chủng#L> memberikan 50% Serangan Fisik ke pahlawan musuh dengan HP terendah.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag pumasok sa laban, makatanggap ng 3 #F Tiên Chủng#L, sa pagtatapos ng #F Siêu Tần#L bawat <#F Tiên Chủng#L> ay nagdudulot ng 50% Pisikal na Atake sa kaaway na bayani na may pinakamababang HP.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila memasuki pertempuran, terima 3 #F Tiên Chủng#L, pada akhir #F Siêu Tần#L setiap <#F Tiên Chủng#L> memberikan 50% Serangan Fizikal kepada wira musuh dengan HP terendah.',
		zawakeEffect = __data_t__zawakeEffect[32226],
		-- {79004}
		zawakeEffectDesc = '#L10# Download the Fairy Seed: #L0# You can obtain a <Fairy Seed> after each attack or every 10% lost health (#L10# Fairy Seed: #L0# buff effect, can only be dispelled, increases lightning damage by 5%, up to 6, each Fairy Seed will restore 50 rage when disappearing)\n#F10# \n#F40# When <Fairy Seed> reaches 6, activate <Complete Susanoo> within 2 rounds\n#F10# \n#F40##L10#Complete Susanoo: #L0# Self-improvement#C0x5c9970#$(30+skillLevel*0.1-0.1)$%#C0x5B545B# Initial Physical Damage and critical strike, and 40% control immunity rate (cannot be dispelled, transferred, etc.). Lightning allies increase critical attack and double attack by 15%. Removes self and immune to sleep, nightmare, paralysis, and rage reduction effects. Each fairy grants 10% chance to dodge critical hits\n#F10# \n#F40#No Fairy Seed gained during overload. Each attack consumes 1 Fairy Seed. After overload ends, self is <Exhausted> for 1 round (Exhausted: control effect, unable to move, can be dispelled)\n#F10# \n#F40##L10#Physical Superconducting: #L0# During the first 3 rounds, your team gains 300/200/100 rage points respectively when unleashing active physical skills. After lightning team members use active skills to attack, Uchiha Itachi will gain 1 additional immortal seed.',
		zawakeEffectDesc_en = '#L10# Download the Fairy Seed: #L0# You can obtain a <Fairy Seed> after each attack or every 10% lost health (#L10# Fairy Seed: #L0# buff effect, can only be dispelled, increases lightning damage by 5%, up to 6, each Fairy Seed will restore 50 rage when disappearing)\n#F10# \n#F40# When <Fairy Seed> reaches 6, activate <Complete Susanoo> within 2 rounds\n#F10# \n#F40##L10#Complete Susanoo: #L0# Self-improvement#C0x5c9970#$(30+skillLevel*0.1-0.1)$%#C0x5B545B# Initial Physical Damage and critical strike, and 40% control immunity rate (cannot be dispelled, transferred, etc.). Lightning allies increase critical attack and double attack by 15%. Removes self and immune to sleep, nightmare, paralysis, and rage reduction effects. Each fairy grants 10% chance to dodge critical hits\n#F10# \n#F40#No Fairy Seed gained during overload. Each attack consumes 1 Fairy Seed. After overload ends, self is <Exhausted> for 1 round (Exhausted: control effect, unable to move, can be dispelled)\n#F10# \n#F40##L10#Physical Superconducting: #L0# During the first 3 rounds, your team gains 300/200/100 rage points respectively when unleashing active physical skills. After lightning team members use active skills to attack, Uchiha Itachi will gain 1 additional immortal seed.',
		zawakeEffectDesc_th = '#L10# ดาวน์โหลดเมล็ดเทพ: #L0# คุณจะได้รับ <เมล็ดเทพ> หลังจากการโจมตีแต่ละครั้งหรือทุกครั้งที่สูญเสียสุขภาพ 10% (#L10# เมล็ดเทพ: #L0# เอฟเฟกต์บัฟ, สามารถถูกขจัดได้เท่านั้น, เพิ่มความเสียหายสายฟ้า 5% สูงสุด 6 เมล็ด, เมล็ดเทพแต่ละเมล็ดจะฟื้นฟูบ้าระห่ำ 50 เมื่อหายไป)\n#F10# \n#F40# เมื่อ <เมล็ดเทพ> ถึง 6 ให้เปิดใช้งาน <ซูซาโนโอสมบูรณ์> ภายใน 2 เทิร์น\n#F10# \n#F40##L10#ซูซาโนโอสมบูรณ์: #L0# การพัฒนาตนเอง#C0x5c9970#$(30+skillLevel*0.1-0.1)$%#C0x5B545B# ความเสียหายทางกายภาพเริ่มต้นและคริติคอล และอัตราป้องกันการควบคุม 40% (ไม่สามารถขจัดโอนย้าย ฯลฯ ได้) เพื่อนร่วมทีมสายฟ้าเพิ่มความรุนแรงโจมตีคริติคอลและการโจมตีคู่ 15% ลบตัวเองและป้องกันเอฟเฟกต์การนอนหลับ ฝันร้าย ชา และลดความโกรธ ทุกเมล็ดเทพให้โอกาสหลบคริติคอล 10%\n#F10# \n#F40# ไม่ได้รับเมล็ดเทพระหว่างการโอเวอร์โหลด ทุกการโจมตีจะใช้เมล็ดเทพ 1 เมล็ด หลังจากโอเวอร์โหลดสิ้นสุด ตัวเองจะถูก <เหนื่อยล้า> เป็นเวลา 1 เทิร์น (เหนื่อยล้า: เอฟเฟกต์ควบคุม, ไม่สามารถเคลื่อนที่ได้, สามารถขจัดได้)\n#F10# \n#F40##L10#การนำไฟฟ้าทางกายภาพ: #L0# ใน 3 เทิร์นแรก ทีมของคุณจะได้รับบ้าระห่ำ 300/200/100 แต้มตามลำดับเมื่อใช้ทักษะกายภาพ เวลาสมาชิกทีมสายฟ้าใช้ทักษะกายภาพจะได้รับเมล็ดอมตะเพิ่มอีก 1 เมล็ดของ Uchiha Itachi',
		zawakeEffectDesc_in = '#L10# Unduh Benih Peri: #L0# Kamu bisa mendapatkan <Benih Peri> setelah setiap serangan atau setiap kehilangan 10% HP (#L10# Benih Peri: #L0# efek buff, hanya bisa hilang, meningkatkan damage petir 5%, maksimal 6, setiap benih peri akan memulihkan 50 kemarahan saat hilang)\n#F10# \n#F40# Ketika <Benih Peri> mencapai 6, aktifkan <Susanoo Selesai> dalam 2 giliran\n#F10# \n#F40##L10#Susanoo Selesai: #L0# Peningkatan diri#C0x5c9970#$(30+skillLevel*0.1-0.1)$%#C0x5B545B# Damage Fisik awal dan serangan kritis, serta tingkat imun kontrol 40% (tidak bisa hilang, dipindahkan, dll). Sekutu petir meningkatkan serangan kritis dan serangan ganda sebesar 15%. Menghapus efek diri sendiri dan kebal terhadap tidur, mimpi buruk, kelumpuhan, dan pengurangan kemarahan. Setiap peri memberikan 10% kesempatan menghindari serangan kritis\n#F10# \n#F40# Tidak mendapatkan Benih Peri saat overload. Setiap serangan menghabiskan 1 Benih Peri. Setelah overload berakhir, diri sendiri menjadi <Kelelahan> selama 1 giliran (Kelelahan: efek kontrol, tidak bisa bergerak, bisa hilang)\n#F10# \n#F40##L10#Konduktivitas Fisik: #L0# Selama 3 giliran pertama, tim kamu akan mendapatkan 300/200/100 poin kemarahan saat menggunakan skill fisik aktif. Setelah anggota tim petir menggunakan skill aktif untuk menyerang, Uchiha Itachi akan mendapatkan 1 Benih Abadi tambahan.',
		zawakeEffectDesc_ph = '#L10# I-download ang Fairy Seed: #L0# Makakakuha ka ng <Fairy Seed> pagkatapos ng bawat atake o kada 10% na nabawas ng buhay (#L10# Fairy Seed: #L0# epekto ng buff, maaari lang matanggal, nagdaragdag ng 5% sira ng kidlat, hanggang 6, bawat Fairy Seed ay magbabawi ng 50 galit kapag nawala)\n#F10# \n#F40# Kapag umabot ang <Fairy Seed> sa 6, i-activate ang <Complete Susanoo> sa loob ng 2 rounds\n#F10# \n#F40##L10#Complete Susanoo: #L0# Pagpapabuti ng sarili#C0x5c9970#$(30+skillLevel*0.1-0.1)$%#C0x5B545B# Panimulang Physical Damage at kritikal na atake, at 40% resistensya sa kontrol (hindi maaaring matanggal, mailipat, atbp.). Ang mga kasamahan sa kidlat ay nagpapataas ng kritikal na atake at dobleng atake ng 15%. Tinatanggal ang sarili at immune sa epekto ng tulog, bangungot, paralisis, at pagbabawas ng galit. Bawat fairy ay nagbibigay ng 10% na tsansa na iwasan ang kritikal na tama\n#F10# \n#F40# Walang mapapansing Fairy Seed habang nag-o-overload. Bawat atake ay kumakain ng 1 Fairy Seed. Pagkatapos ng overload, ang sarili ay magiging <Exhausted> sa loob ng 1 round (Exhausted: kontrol na epekto, hindi makagalaw, maaaring matanggal)\n#F10# \n#F40##L10#Physical Superconducting: #L0# Sa unang 3 rounds, ang iyong koponan ay makakakuha ng 300/200/100 puntos ng galit kapag nagpalabas ng mga aktibong physical skill. Pagkatapos gamitin ng miyembro ng kidlat na koponan ang aktibong skill sa pag-atake, makakakuha si Uchiha Itachi ng 1 karagdagang immortal seed.',
		zawakeEffectDesc_ma = '#L10# Muat turun Benih Peri: #L0# Anda boleh memperoleh <Benih Peri> selepas setiap serangan atau setiap 10% kesihatan hilang (#L10# Benih Peri: #L0# kesan buff, hanya boleh dipadamkan, meningkatkan 5% kerosakan kilat, maksimum 6, setiap benih peri akan memulihkan 50 kemarahan apabila hilang)\n#F10# \n#F40# Apabila <Benih Peri> mencapai 6, aktifkan <Susanoo Lengkap> dalam 2 pusingan\n#F10# \n#F40##L10#Susanoo Lengkap: #L0# Peningkatan diri#C0x5c9970#$(30+skillLevel*0.1-0.1)$%#C0x5B545B# Kerosakan Fizikal awal dan serangan kritikal serta kadar imuniti kawalan 40% (tidak boleh dipadamkan, dipindahkan, dll). Rakan sepasukan kilat meningkatkan serangan kritikal dan serangan berganda sebanyak 15%. Menghapus sendiri dan kebal kepada kesan tidur, mimpi ngeri, lumpuh dan pengurangan kemarahan. Setiap peri memberi 10% peluang mengelak serangan kritikal\n#F10# \n#F40# Tidak memperoleh Benih Peri semasa terlebih muatan. Setiap serangan menggunakan 1 Benih Peri. Selepas terlebih muatan berakhir, diri sendiri akan <Penat> selama 1 pusingan (Penat: kesan kawalan, tidak boleh bergerak, boleh dipadamkan)\n#F10# \n#F40##L10#Konduktiviti Fizikal: #L0# Sepanjang 3 pusingan pertama, pasukan anda akan mendapat 300/200/100 mata kemarahan masing-masing apabila melepaskan kemahiran fizikal aktif. Selepas ahli pasukan kilat menggunakan kemahiran aktif untuk menyerang, Uchiha Itachi akan mendapat 1 benih abadi tambahan.',
		zawakeEffectDesc_vn = '#L10# Tải hạt giống thần tiên: #L0# Bạn có thể nhận được một <Hạt giống thần tiên> sau mỗi đòn tấn công hoặc cứ sau 10% mạng sống bị mất (#L10# Hạt giống thần tiên: #L0# hiệu ứng buff, chỉ có thể bị xua tan, tăng 5% sát thương sét, tối đa 6, mỗi hạt giống thần tiên sẽ tự phục hồi 50 điểm thịnh nộ khi biến mất)\n#F10# \n#F40# Khi <Fairy Seed> đạt 6, hãy nhập <Hoàn thành> Susanoo> trong 2 hiệp\n#F10# \n#F40##L10#Hoàn thành Susanoo: #L0#Cải thiện bản thân#C0x5c9970#$(30+skillLevel*0.1-0.1)$%#C0x5B545B#Đòn Sát Thương Vật Lý ban đầu và đòn chí mạng và tỷ lệ miễn nhiễm kiểm soát 40% (không thể xua tan, chuyển giao, v.v.). Đồng đội sấm sét tăng đòn tấn công chí mạng và tấn công gấp đôi thêm 15%. Tự loại bỏ và miễn nhiễm với các ảnh hưởng của giấc ngủ, ác mộng, tê liệt và giảm tức giận. Mỗi loại thần tiên cung cấp 10% khả năng né tránh\n#F10# \n#F40#Không nhận được Hạt giống thần tiên trong quá trình ép xung. Mỗi đòn tấn công tiêu tốn 1 Hạt Giống Tiên. Sau khi quá trình ép xung kết thúc, bản thân bị <Cạn kiệt> trong 1 vòng (Kiệt sức: hiệu ứng khống chế, không thể di chuyển, có thể bị xua tan)\n#F10# \n#F40##L10#Physical Superconducting: #L0# Trong 3 vòng đầu tiên, đội của bạn sẽ nhận được 300/200/100 điểm thịnh nộ tương ứng khi giải phóng các kỹ năng thể chất chủ động. Sau khi các thành viên trong đội sấm sét sử dụng kỹ năng chủ động để tấn công, Uchiha Itachi sẽ nhận được thêm 1 Hạt giống bất tử.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'When Susanoo is in full form, his Physical Damage and Critical Hit are increased by 5%.',
		zawakeSimpleDesc_en = 'When Susanoo is in full form, his Physical Damage and Critical Hit are increased by 5%.',
		zawakeSimpleDesc_th = 'เมื่อซูซาโนะอยู่ในร่างสมบูรณ์ การโจมตีทางกายภาพและคริติคอลของเขาจะเพิ่มขึ้น 5%',
		zawakeSimpleDesc_in = 'Saat Susanoo dalam bentuk penuh, Serangan Fisik dan Serangan Kritis miliknya akan meningkat sebesar 5%.',
		zawakeSimpleDesc_ph = 'Kapag nasa kumpletong anyo si Susanoo, tataas ng 5% ang kanyang Physical Damage at Critical Hit.',
		zawakeSimpleDesc_ma = 'Apabila Susanoo berada dalam bentuk penuh, Serangan Fizikal dan Pukulan Kritikalnya akan meningkat sebanyak 5%.',
		zawakeSimpleDesc_vn = 'Khi Susanoo ở dạng đầy đủ, đòn Sát Thương Vật Lý và tấn công chí mạng của anh ta sẽ được tăng thêm 5%.',
		changeUnitTrigger = true,
