	[32411] = {
		id = 32411,
		skillName_vn = 'Long Quyền',
		skillName_en = 'Dragon Fist',
		skillName_th = 'หมัดมังกร',
		skillName_in = 'Tinju Naga',
		skillName_ph = 'Dragon Fist',
		skillName_ma = 'Tinju Naga',
		skillName = 'Dragon Fist',
		describe_vn = 'Kyurem nhảy lên cao và đập xuống đất bằng nắm đấm rồng của mình, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ trong số #C0xF13B54# Sát Thương Vật Lý#C0x5B545B# cho một kẻ địch, tăng Sát Thương Phép Thuật ban đầu thêm 15% và đòn Sát Thương Vật Lý ban đầu thêm 15%, kéo dài trong 2 round\n#F10# \n#F40# Nhận lá chắn bông tuyết khi tấn công mục tiêu [Săn bắn]',
		describe_en = 'Kyurem leaps high and slams down with its dragon fist, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ of #C0xF13B54# Physical Damage#C0x5B545B# to a single enemy, increases initial Magic Damage by 15% and initial Physical Damage by 15%, lasting for 2 rounds \n#F10# \n#F40#. Gains a snowflake shield when attacking the target [Hunting].',
		describe_th = 'เคียวเร็ม กระโดดสูงแล้วทุบลงด้วยหมัดมังกรของมัน ทำให้เกิด #C0xE69900#ความเสียหายทางกายภาพ 100%#C0x5B545B#+$(skillLevel*4*24)$ จาก #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ต่อตัวศัตรูหนึ่งตัว, เพิ่มความเสียหายเวทเริ่มต้นขึ้น 15% และความเสียหายทางกายภาพเริ่มต้นขึ้น 15% ต่อเนื่อง 2 เทิร์น \n#F10# \n#F40# รับโล่เกล็ดหิมะเมื่อโจมตีเป้าหมาย [การล่า].',
		describe_in = 'Kyurem melompat tinggi dan menghantam tanah dengan pukulan naga-nya, memberikan #C0xE69900#100% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*24)$ dari #C0xF13B54# Kerusakan Fisik#C0x5B545B# ke satu musuh, meningkatkan Kerusakan Sihir awal sebesar 15% dan Kerusakan Fisik awal sebesar 15%, berlangsung selama 2 ronde \n#F10# \n#F40#. Mendapatkan perisai serpihan salju saat menyerang target [Berburu].',
		describe_ph = 'Tumalon si Kyurem nang mataas at tinumbok ang lupa gamit ang kanyang dragon fist, na nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*24)$ ng #C0xF13B54# Pisikal na Pinsala#C0x5B545B# sa isang kalaban, pinapataas ang unang Magic Damage ng 15% at unang Pisikal na Pinsala ng 15%, tumatagal ng 2 rounds \n#F10# \n#F40#. Nakakakuha ng snowflake shield kapag inaatake ang target [Hunting].',
		describe_ma = 'Kyurem melompat tinggi dan memukul ke tanah dengan kepalan tangan naga, menyebabkan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ daripada #C0xF13B54# Kerosakan Fizikal#C0x5B545B# kepada satu musuh, meningkatkan Kerosakan Sihir awal sebanyak 15% dan serangan Kerosakan Fizikal awal sebanyak 15%, berlangsung selama 2 pusingan \n#F10# \n#F40#. Mendapatkan perisai kepingan salji apabila menyerang sasaran [Memburu].',
		describe = 'Kyurem leaps high and slams down with its dragon fist, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ of #C0xF13B54# Physical Damage#C0x5B545B# to a single enemy, increases initial Magic Damage by 15% and initial Physical Damage by 15%, lasting for 2 rounds \n#F10# \n#F40#. Gains a snowflake shield when attacking the target [Hunting].',
		zawakeEffect = __data_t__zawakeEffect[32411],
		-- {79001}
		zawakeEffectDesc = 'Kyurem jumps high and slams down with a dragon fist, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ of #C0xF13B54# Physical Damage#C0x5B545B# to one enemy, increasing Magic Attack and Physical Damage by 20% for 2 turns#F10# Getting a snowflake shield when attacking the target <Hunting>',
		zawakeEffectDesc_en = 'Kyurem jumps high and slams down with a dragon fist, dealing #C0xE69900#100% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ of #C0xF13B54# Physical Damage#C0x5B545B# to one enemy, increasing Magic Attack and Physical Damage by 20% for 2 turns#F10# Getting a snowflake shield when attacking the target <Hunting>',
		zawakeEffectDesc_th = 'Kyurem กระโดดขึ้นสูงแล้วทุบลงด้วยหมัดมังกร สร้างความเสียหายทางกายภาพ #C0xE69900#100%#C0x5B545B#+$(skillLevel*4*24)$ ของ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# แก่ศัตรูหนึ่งตัว เพิ่มพลังโจมตีเวทและความเสียหายทางกายภาพ 20% เป็นเวลา 2 เทิร์น#F10# ได้รับโล่เกล็ดหิมะเมื่อโจมตีเป้าหมาย <ล่าสัตว์>',
		zawakeEffectDesc_in = 'Kyurem melompat tinggi dan menghantam tanah dengan pukulan naga, memberikan #C0xE69900#100% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*24)$ dari #C0xF13B54# Kerusakan Fisik#C0x5B545B# kepada satu musuh, meningkatkan Serangan Sihir dan Kerusakan Fisik sebesar 20% selama 2 giliran#F10# Mendapatkan pelindung kepingan salju saat menyerang target <Berburu>',
		zawakeEffectDesc_ph = 'Tumalon si Kyurem nang mataas at pinakawalan ng dragon fist na hampas sa lupa, nagdudulot ng #C0xE69900#100% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*24)$ ng #C0xF13B54# Pisikal na Pinsala#C0x5B545B# sa isang kalaban, nagpapataas ng 20% na Magic Attack at 20% Pisikal na Pinsala sa loob ng 2 turn#F10# Nakakakuha ng snowflake shield kapag inaatake ang target <Pangangaso>',
		zawakeEffectDesc_ma = 'Kyurem melompat tinggi dan menghentak ke tanah dengan penumbuk naga, memberikan #C0xE69900#100% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ dari #C0xF13B54# Kerosakan Fizikal#C0x5B545B# kepada seorang musuh, meningkatkan Serangan Sihir dan Kerosakan Fizikal sebanyak 20% selama 2 pusingan#F10# Mendapatkan perisai kepingan salji apabila menyerang sasaran <Berburu>',
		zawakeEffectDesc_vn = 'Kyurem nhảy lên cao và đập xuống đất bằng nắm đấm rồng, gây #C0xE69900#100% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ của #C0xF13B54# Sát Thương Vật Lý#C0x5B545B# cho một kẻ địch, tăng 20% ​​​​tấn Công Phép thuật và 20% Sát Thương Vật Lý, kéo dài 2 hiệp\n#F10# \n#F40# Nhận được tấm bảo vệ bông tuyết khi tấn công mục tiêu <Săn bắn>',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increase initial Magic Attack by 15% and initial Physical Damage by 15%\n#F20# \n#F40##C0x5c9970#→Increase Magic Attack by 20% and Physical Damage by 20%#C0x5B545B#',
		zawakeSimpleDesc_en = 'Increase initial Magic Attack by 15% and initial Physical Damage by 15%\n#F20# \n#F40##C0x5c9970#→Increase Magic Attack by 20% and Physical Damage by 20%#C0x5B545B#',
		zawakeSimpleDesc_th = 'เพิ่มพลังโจมตีเวทเริ่มต้น 15% และความเสียหายทางกายภาพเริ่มต้น 15%\n#F20# \n#F40##C0x5c9970#→เพิ่มพลังโจมตีเวท 20% และความเสียหายทางกายภาพ 20%#C0x5B545B#',
		zawakeSimpleDesc_in = 'Meningkatkan Serangan Sihir awal sebesar 15% dan Serangan Fisik awal sebesar 15%\n#F20# \n#F40##C0x5c9970#→Meningkatkan Serangan Sihir sebesar 20% dan Serangan Fisik sebesar 20%#C0x5B545B#',
		zawakeSimpleDesc_ph = 'Dagdag 15% sa paunang Magic Attack at 15% sa paunang Physical Damage\n#F20# \n#F40##C0x5c9970#→Dagdag 20% sa Magic Attack at 20% sa Physical Damage#C0x5B545B#',
