	[32412] = {
		id = 32412,
		skillName_vn = 'Băng Hộ Vệ',
		skillName_en = 'Guardian Ice',
		skillName_th = 'น้ำแข็งผู้พิทักษ์',
		skillName_in = 'Pelindung Es',
		skillName_ph = 'Tagapangalaga ng Yelo',
		skillName_ma = 'Penjaga Ais',
		skillName = 'Guardian Ice',
		describe_vn = 'Kyurem thở ra hơi thở băng, ngưng tụ không khí thành các cột băng cứng, gây #C0xE69900#180% đòn Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Sát Thương Vật Lý cho một kẻ thù. Hại #C0x5B545B#, thêm [Deep Cold Shield] cho bản thân trong 2 lượt (sau khi bị tấn công, cướp 10% giới hạn máu của kẻ tấn công (tối đa không được vượt quá 10% giới hạn máu của bản thân) và chuyển hiệu ứng tiêu cực của bản thân sang kẻ tấn công)\n#F10# \n#F40# Khi tấn công mục tiêu [Săn bắn], hiệu ứng [Xé] sẽ được thêm trong 2 lượt (Xé: hiệu ứng tiêu cực, hiệu ứng mục tiêu bị cấm hồi máu và sẽ nhận 80% sát thương chuẩn của đòn Sát Thương Vật Lý của Kyurem khi tấn công)',
		describe_en = 'Kyurem exhales an icy breath, condensing the air into solid ice pillars, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Physical Damage to a single enemy. Additionally, applies [Deep Cold Shield] to self for 2 turns (upon being attacked, steals 10% of the attacker\'s max HP (not exceeding 10% of self max HP) and transfers negative effects from self to the attacker)\n#F10# \n#F40# When attacking a [Hunting] target, applies the [Tear] effect for 2 turns (Tear: negative effect, target is forbidden from healing and takes 80% of Kyurem\'s Physical Damage as true damage when attacked).',
		describe_th = 'คิวเร็มพ่นลมหายใจเย็นแข็งกลายเป็นเสาไอซ์แข็ง, สร้างความเสียหายทางกายภาพ #C0xE69900#180%#+$(skillLevel*4*60)$#C0xF13B54# ให้กับศัตรูหนึ่งตัว พร้อมกับเพิ่ม [โล่เยือกแข็งลึก] ให้ตนเองเป็นเวลา 2 เทิร์น (เมื่อถูกโจมตีจะขโมยเลือดสูงสุด 10% ของผู้โจมตี (ไม่เกิน 10% ของเลือดสูงสุดของตนเอง) และโอนผลลบจากตนเองไปยังผู้โจมตี)\n#F10# \n#F40# เมื่อโจมตีเป้าหมาย [ล่าสัตว์] จะเพิ่มเอฟเฟกต์ [ฉีก] เป็นเวลา 2 เทิร์น (ฉีก: เอฟเฟกต์ลบ, เป้าหมายถูกห้ามฟื้นฟูเลือด และจะได้รับความเสียหายจริง 80% ของความเสียหายทางกายภาพจากคิวเร็มเมื่อถูกโจมตี).',
		describe_in = 'Kyurem menghembuskan napas es, mengkondensasikan udara menjadi tiang-tiang es keras, menyebabkan #C0xE69900#180% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Kerusakan Fisik pada satu musuh. Menyebabkan #C0x5B545B#, menambahkan [Perisai Dingin Dalam] pada diri sendiri selama 2 giliran (setelah diserang, mencuri 10% batas maksimal HP penyerang (maksimal tidak melebihi 10% batas maksimal HP diri) dan memindahkan efek negatif dari diri ke penyerang)\n#F10# \n#F40# Saat menyerang target [Berburu], efek [Robek] akan ditambahkan selama 2 giliran (Robek: efek negatif, target dilarang pulih HP dan menerima 80% dari kerusakan fisik Kyurem sebagai kerusakan murni saat diserang).',
		describe_ph = 'Humihinga si Kyurem ng malamig na hangin, kinokondensa ang hangin upang maging matigas na mga haliging yelo, nagdudulot ng #C0xE69900#180% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Pisikal na Pinsala sa isang kalaban. Nagdudulot din ng #C0x5B545B#, naglalagay ng [Deep Cold Shield] sa sarili sa loob ng 2 turn (kapag inatake, ninanakaw ang 10% ng max HP ng attacker (hindi lalampas sa 10% ng sariling max HP) at inililipat ang mga negatibong epekto mula sa sarili papunta sa attacker)\n#F10# \n#F40# Kapag inaatake ang target na [Hunting], idinadagdag ang efektong [Tear] sa loob ng 2 turn (Tear: negatibong epekto, hindi maaaring magpagaling ang target at tumatanggap ng 80% ng Pisikal na Pinsala ni Kyurem bilang tunay na pinsala kapag inatake).',
		describe_ma = 'Kyurem menghembus nafas ais, memampatkan udara menjadi tiang ais keras, menyebabkan #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*60)$#Kerosakan Fizikal kepada satu musuh. Menyebabkan #C0x5B545B#, menambah [Perisai Dingin Mendalam] pada diri sendiri selama 2 pusingan (selepas diserang, mencuri 10% had max HP penyerang (maksimum tidak melebihi 10% had max HP diri sendiri) dan memindahkan kesan negatif dari diri ke penyerang)\n#F10# \n#F40# Apabila menyerang sasaran [Memburu], kesan [Robek] akan ditambah selama 2 pusingan (Robek: kesan negatif, sasaran dilarang sembuh dan akan menerima 80% kesan Kerosakan Fizikal Kyurem sebagai kerosakan tulen apabila diserang).',
		describe = 'Kyurem exhales an icy breath, condensing the air into solid ice pillars, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Physical Damage to a single enemy. Additionally, applies [Deep Cold Shield] to self for 2 turns (upon being attacked, steals 10% of the attacker\'s max HP (not exceeding 10% of self max HP) and transfers negative effects from self to the attacker)\n#F10# \n#F40# When attacking a [Hunting] target, applies the [Tear] effect for 2 turns (Tear: negative effect, target is forbidden from healing and takes 80% of Kyurem\'s Physical Damage as true damage when attacked).',
		zawakeEffect = __data_t__zawakeEffect[32412],
		-- {79002}
		zawakeEffectDesc = 'Kyurem breathes ice, condensing the air into hard ice pillars, causing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#Physical Damage#C0x5B for one enemy. Adds <Deep Cold Shield> to self for 2 turns (after being attacked, steals 10% max HP of attacker (maximum cannot exceed 10% of your own HP limit) and transfers your negative effects to the attacker, and applies <Tear> to the attacker for 1 turn)\n#F10# \n#F40# When attacking a <Hunted> target, <Tear> effect is applied for 3 turns (<Tear>: negative effect, target is forbidden to heal and receives 80% of Kyurem\'s standard physical damage when attacked).',
		zawakeEffectDesc_en = 'Kyurem breathes ice, condensing the air into hard ice pillars, causing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#Physical Damage#C0x5B for one enemy. Adds <Deep Cold Shield> to self for 2 turns (after being attacked, steals 10% max HP of attacker (maximum cannot exceed 10% of your own HP limit) and transfers your negative effects to the attacker, and applies <Tear> to the attacker for 1 turn)\n#F10# \n#F40# When attacking a <Hunted> target, <Tear> effect is applied for 3 turns (<Tear>: negative effect, target is forbidden to heal and receives 80% of Kyurem\'s standard physical damage when attacked).',
		zawakeEffectDesc_th = 'Kyurem หายใจเอาน้ำแข็ง รวมอากาศให้กลายเป็นเสาน้ำแข็งแข็งแรง สร้างความเสียหายทางกายภาพ #C0xE69900#180%#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B แก่ศัตรูหนึ่งตัว เพิ่ม <Deep Cold Shield> ให้ตัวเองเป็นเวลา 2 เทิร์น (หลังถูกโจมตี ขโมยเลือดสูงสุด 10% ของผู้โจมตี (สูงสุดไม่เกิน 10% ของค่าพลังชีวิตตัวเอง) และส่งผลลบของคุณไปยังผู้โจมตี พร้อมทั้งเพิ่ม <Xé> แก่ผู้โจมตีใน 1 เทิร์น)\n#F10# \n#F40# เมื่อโจมตีกลุ่มเป้าหมาย <Săn bắn> จะได้รับผล <Xé> เป็นเวลา 3 เทิร์น (<Xé>: ผลลบ เป้าหมายถูกห้ามฟื้นฟูและจะได้รับความเสียหายกายภาพมาตรฐาน 80% ของ Kyurem เมื่อถูกโจมตี)',
		zawakeEffectDesc_in = 'Kyurem menghirup es, mengkondensasikan udara menjadi tiang es keras, menyebabkan #C0xE69900#180% Damage Fisik#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#Damage Fisik#C0x5B pada satu musuh. Menambahkan <Deep Cold Shield> pada diri sendiri selama 2 giliran (setelah diserang, mencuri 10% HP maksimal penyerang (maksimum tidak bisa melebihi 10% batas HP Anda sendiri) dan memindahkan efek negatif Anda ke penyerang serta memberi efek <Xé> kepada penyerang selama 1 giliran)\n#F10# \n#F40# Saat menyerang target <Săn bắn>, efek <Xé> ditambahkan selama 3 giliran (<Xé>: efek negatif, target dilarang menyembuhkan dan akan menerima 80% kerusakan fisik standar Kyurem saat diserang).',
		zawakeEffectDesc_ph = 'Humihinga ng yelo si Kyurem, pinipiga ang hangin upang maging matitibay na haligi ng yelo, nagdudulot ng #C0xE69900#180% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#Pisikal na Pinsala#C0x5B sa isang kalaban. Nagdaragdag ng <Deep Cold Shield> sa sarili sa loob ng 2 turn (pagkatapos tamaan, nagnanakaw ng 10% ng maximum na HP ng umaatake (ang pinakamataas ay hindi lalampas sa 10% ng iyong sariling limitasyon ng HP) at inililipat ang iyong negatibong epekto sa umaatake at naglalagay ng <Xé> sa umaatake sa loob ng 1 turn)\n#F10# \n#F40# Kapag inaatake ang target na <Săn bắn>, ang epekto ng <Xé> ay dinaragdagan sa loob ng 3 turn (<Xé>: negatibong epekto, ipinagbabawal ang target na magpagaling at tatanggap ng 80% pisikal na standard na pinsala mula kay Kyurem kapag inaatake).',
		zawakeEffectDesc_ma = 'Kyurem menghembuskan nafas ais, memampatkan udara menjadi tiang ais keras, menyebabkan #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#Kerosakan Fizikal#C0x5B kepada satu musuh. Menambah <Deep Cold Shield> pada diri sendiri selama 2 pusingan (selepas diserang, mencuri 10% HP maksimum penyerang (had maksimum tidak boleh melebihi 10% had HP anda sendiri) dan memindahkan kesan negatif anda kepada penyerang serta menyebabkan <Xé> kepada penyerang selama 1 pusingan)\n#F10# \n#F40# Apabila menyerang sasaran <Săn bắn>, kesan <Xé> akan ditambah selama 3 pusingan (<Xé>: kesan negatif, sasaran dilarang untuk sembuh dan akan menerima 80% kerosakan fizikal standard Kyurem apabila diserang).',
		zawakeEffectDesc_vn = 'Kyurem hít thở băng, ngưng tụ không khí thành các cột băng cứng, gây #C0xE69900#180% đòn Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#Sát Thương Vật Lý#C0x5B cho một kẻ thù. 545B#, thêm <Deep Cold Shield> cho bản thân trong 2 lượt (sau khi bị tấn công, cướp 10% máu tối đa của kẻ tấn công (mức tối đa không thể vượt quá 10% giới hạn máu của chính bạn) và chuyển hiệu ứng tiêu cực của bạn cho kẻ tấn công và gây <Xé> cho kẻ tấn công trong 1 lượt)\n#F10# \n#F40# Khi tấn công mục tiêu <Săn bắn>, hiệu ứng <Xé> sẽ được thêm trong 3 lượt (Xé: hiệu ứng tiêu cực, mục tiêu bị cấm hồi máu và sẽ nhận 80% sát thương chuẩn vật lý của Kyurem khi tấn công)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#When Deep Cold Shield is hit, it causes 1 turn of Tear to the attacker, and the duration of <Tear> inflicted when attacking a <Hunted> target increases to 3 turns#C0x5B545B#',
		zawakeSimpleDesc_en = '#C0x5c9970#When Deep Cold Shield is hit, it causes 1 turn of Tear to the attacker, and the duration of <Tear> inflicted when attacking a <Hunted> target increases to 3 turns#C0x5B545B#',
		zawakeSimpleDesc_th = '#C0x5c9970#เมื่อ Deep Cold Shield ถูกโจมตี จะทำให้ศัตรูติดสถานะ <ฉีก> 1 เทิร์น และระยะเวลาของ <ฉีก> เมื่อโจมตีเป้าหมาย <ล่า> จะเพิ่มเป็น 3 เทิร์น#C0x5B545B#',
		zawakeSimpleDesc_in = '#C0x5c9970#Ketika Deep Cold Shield terkena serangan, akan menyebabkan <Robek> selama 1 giliran pada penyerang, dan durasi <Robek> saat menyerang target <Buruan> meningkat menjadi 3 giliran#C0x5B545B#',
		zawakeSimpleDesc_ph = '#C0x5c9970#Kapag tinamaan ang Deep Cold Shield, magdudulot ito ng 1 turn ng <Punit> sa kalaban at ang tagal ng <Punit> kapag inatake ang <Hinahabol> na target ay tataas sa 3 turn#C0x5B545B#',
		zawakeSimpleDesc_ma = '#C0x5c9970#Apabila Perisai Sejuk Beku terkena serangan, ia menyebabkan <Koyak> selama 1 giliran kepada penyerang, dan tempoh <Koyak> apabila menyerang sasaran <Buruan> meningkat kepada 3 giliran#C0x5B545B#',
		zawakeSimpleDesc_vn = '#C0x5c9970#Khi Deep Cold Shield bị bắn trúng sẽ gây ra 1 lượt xé cho kẻ tấn công và thời gian <Xé> gây ra khi tấn công mục tiêu <Săn bắn> tăng lên 3 lượt#C0x5B545B#',
		upLvDesc = 'Fixed damage +240',
