	[32413] = {
		id = 32413,
		skillName_vn = 'Thế giới băng giá',
		skillName_en = 'Frozen world',
		skillName_th = 'โลกน้ำแข็ง',
		skillName_in = 'Dunia beku',
		skillName_ph = 'Niyelong napakalamig',
		skillName_ma = 'Dunia beku',
		skillName = 'Frozen world',
		describe_vn = 'Kyurem thức dậy dưới dòng sông băng, biến cả thế giới thành bãi săn và lấy được 2 [Bông tuyết]. Nếu không có mục tiêu [Săn bắn] trên sân, anh ta sẽ đánh dấu một mục tiêu ngẫu nhiên ở hàng sau của kẻ địch làm mục tiêu [Săn bắn] trong 2 lượt, và biến sân đấu thành [Thế giới băng giá] trong 2 lượt, gây sát thương cho mục tiêu. Vào #C0xE69900#400% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B#；\n#F10# \n#F40##L10# Frozen World: #L0# Tốc độ và khả năng phòng thủ gấp đôi của tất cả kẻ thù bị giảm 30%. Trong thế giới băng giá, chế nhạo [Săn bắn] mục tiêu (khiêu khích: kiểm soát hiệu ứng, buộc mục tiêu phải tự tấn công) và cướp đi 25% phòng thủ gấp đôi ban đầu của nó. Tấn công, 150 cơn thịnh nộ và hiệu ứng buff, đồng thời có 100% khả năng đóng băng ngẫu nhiên một đơn vị kẻ địch không bị đóng băng khác trong 1 lượt; nếu chiêu thức đặc biệt này khiến mục tiêu [Săn bắn] chết, dấu [Săn bắn] sẽ được thêm vào hàng sau của kẻ địch ngay lập tức.',
		describe_en = 'Kyurem awakens under the glacial river, turning the entire world into a hunting ground and obtains 2 [Snowflakes]. If there is no [Hunting] target on the field, he will mark a random target in the back row of the enemy as the [Hunting] target for 2 turns and transform the battlefield into the [Frozen World] for 2 turns, dealing damage to the target. Deals #C0xE69900#400% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Physical Damage#C0x5B545B#；\n#F10# \n#F40##L10# Frozen World: #L0# Speed and defense of all enemies are halved and reduced by 30%. In the Frozen World, taunt the [Hunting] target (taunt: control effect forcing the target to attack itself) and steal 25% of its original doubled defense. Attack with 150 fury and buff effect, and has 100% chance to freeze a random enemy unit that is not frozen for 1 turn; if this special skill kills the [Hunting] target, the [Hunting] mark will immediately be applied to a back-row enemy.',
		describe_th = 'ไคเร็มตื่นขึ้นใต้แม่น้ำธารน้ำแข็ง เปลี่ยนโลกทั้งใบให้กลายเป็นสนามล่า และได้รับ [เกล็ดหิมะ] 2 อัน หากไม่มีเป้าหมาย [ล่า] อยู่ในสนาม เขาจะทำเครื่องหมายเป้าหมายสุ่มในแถวหลังของศัตรูเป็นเป้าหมาย [ล่า] เป็นเวลา 2 รอบ และเปลี่ยนสนามรบเป็น [โลกน้ำแข็ง] เป็นเวลา 2 รอบ ทำความเสียหายต่อเป้าหมาย สร้าง #C0xE69900#ความเสียหายกายภาพ 400%#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B#；\n#F10# \n#F40##L10# โลกน้ำแข็ง: #L0# ความเร็วและการป้องกันของศัตรูทั้งหมดถูกลดลงครึ่งหนึ่งและลดลง 30% ในโลกน้ำแข็ง เย้ยหยันเป้าหมาย [ล่า] (เย้ยหยัน: เอฟเฟกต์ควบคุม บังคับเป้าหมายให้โจมตีตัวเอง) และขโมยเกราะป้องกันสองเท่าเริ่มต้น 25% ของเป้าหมาย โจมตีด้วยความโกรธ 150 และบัฟ มีโอกาส 100% ที่จะทำให้หน่วยศัตรูแบบสุ่มที่ไม่ได้ถูกแช่แข็งติดสถานะแช่แข็งเป็นเวลา 1 รอบ; หากทักษะพิเศษนี้ทำให้เป้าหมาย [ล่า] ตาย เครื่องหมาย [ล่า] จะถูกเพิ่มไปยังแถวหลังของศัตรูทันที',
		describe_in = 'Kyurem bangun di bawah sungai es, mengubah seluruh dunia menjadi arena perburuan dan mendapatkan 2 [Bunga Salju]. Jika tidak ada target [Berburu] di medan, dia akan menandai target acak di barisan belakang musuh sebagai target [Berburu] selama 2 giliran dan mengubah medan menjadi [Dunia Beku] selama 2 giliran, memberikan damage ke target. Memberikan #C0xE69900#400% Damage Fisik#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Damage Fisik#C0x5B545B#；\n#F10# \n#F40##L10# Dunia Beku: #L0# Kecepatan dan pertahanan semua musuh dibagi dua dan berkurang 30%. Dalam Dunia Beku, ejek target [Berburu] (ejekan: efek kontrol, memaksa target menyerang dirinya sendiri) dan curi 25% dari pertahanan ganda aslinya. Serang dengan kemarahan 150 dan efek buff, serta memiliki peluang 100% membekukan unit musuh acak yang belum beku selama 1 giliran; jika skil khusus ini membunuh target [Berburu], tanda [Berburu] langsung ditambahkan ke barisan belakang musuh.',
		describe_ph = 'Nagising si Kyurem sa ilalim ng yelong ilog, ginawang parang pang-hunting ang buong mundo at nakuha ang 2 [Snowflakes]. Kung walang target na [Pangangaso] sa field, mamarkahan niya ang isang random na target sa likod ng kalaban bilang target na [Pangangaso] sa loob ng 2 turn, at gagawing [Frozen World] ang battlefield sa loob ng 2 turn, nagdudulot ng pinsala sa target. Nagdudulot ng #C0xE69900#400% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Physical Damage#C0x5B545B#；\n#F10# \n#F40##L10# Frozen World: #L0# Ang bilis at depensa ng lahat ng kalaban ay nahahati sa dalawa at nababawasan ng 30%. Sa Frozen World, pinapakanta ang [Pangangaso] na target (taunt: control effect na pinipilit ang target na atakihin ang sarili) at nagnanakaw ng 25% ng original nitong doubled defense. Atake na may 150 na galit at buff effect, at may 100% tsansa na i-freeze ang isang random na kalaban na hindi pa naffreeze sa loob ng 1 turn; kung ang espesyal na skill na ito ang nakapatay sa [Pangangaso] na target, ang marka ng [Pangangaso] ay agad na ilalagay sa likod ng kalaban.',
		describe_ma = 'Kyurem bangun di bawah sungai ais, mengubah seluruh dunia menjadi medan pemburuan dan memperoleh 2 [Bunga Salji]. Jika tiada sasaran [Pemburuan] di medan, dia akan menandakan sasaran rawak di barisan belakang musuh sebagai sasaran [Pemburuan] selama 2 pusingan dan mengubah medan pertempuran menjadi [Dunia Beku] selama 2 pusingan, menyebabkan kerosakan kepada sasaran. Menyerang dengan #C0xE69900#400% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B#；\n#F10# \n#F40##L10# Dunia Beku: #L0# Kelajuan dan pertahanan semua musuh dibahagikan dua dan dikurangkan sebanyak 30%. Dalam Dunia Beku, mentertawakan sasaran [Pemburuan] (mentertawakan: kesan kawalan, memaksa sasaran menyerang dirinya sendiri) dan mencuri 25% pertahanan berganda asalnya. Menyerang dengan 150 kemarahan dan kesan buff, serta mempunyai peluang 100% untuk membekukan satu unit musuh rawak yang belum dibekukan selama 1 pusingan; jika skill istimewa ini membunuh sasaran [Pemburuan], tanda [Pemburuan] akan segera ditambah ke barisan belakang musuh.',
		describe = 'Kyurem awakens under the glacial river, turning the entire world into a hunting ground and obtains 2 [Snowflakes]. If there is no [Hunting] target on the field, he will mark a random target in the back row of the enemy as the [Hunting] target for 2 turns and transform the battlefield into the [Frozen World] for 2 turns, dealing damage to the target. Deals #C0xE69900#400% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Physical Damage#C0x5B545B#；\n#F10# \n#F40##L10# Frozen World: #L0# Speed and defense of all enemies are halved and reduced by 30%. In the Frozen World, taunt the [Hunting] target (taunt: control effect forcing the target to attack itself) and steal 25% of its original doubled defense. Attack with 150 fury and buff effect, and has 100% chance to freeze a random enemy unit that is not frozen for 1 turn; if this special skill kills the [Hunting] target, the [Hunting] mark will immediately be applied to a back-row enemy.',
		simDesc_vn = 'Kyurem sẽ đóng băng trái đất, và khi đó cả thế giới sẽ trở thành nơi săn mồi của hắn',
		simDesc_en = 'Kyurem will freeze the Earth, turning the entire world into his hunting ground.',
		simDesc_th = 'คิวเร็มจะทำให้โลกกลายเป็นน้ำแข็ง และเมื่อถึงตอนนั้น โลกทั้งใบจะกลายเป็นที่ล่าของเขา',
		simDesc_in = 'Kyurem akan membekukan Bumi, dan ketika itu seluruh dunia akan menjadi tempat berburu bagi dirinya.',
		simDesc_ph = 'Papatigasin ni Kyurem ang mundo, at kapag nangyari iyon, ang buong mundo ay magiging kanyang pook-panghuhuli.',
		simDesc_ma = 'Kyurem akan membekukan Bumi, dan ketika itu seluruh dunia akan menjadi tempat memburunya.',
		simDesc = 'Kyurem will freeze the Earth, turning the entire world into his hunting ground.',
		starEffect = __data_t__starEffect[32413],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng thêm: Khi tấn công mục tiêu bị <Săn Bắt> trong Thế Giới Băng Giá, mời ngẫu nhiên hai tướng hàng sau phe ta cùng tấn công thường mục tiêu <Săn Bắt>.',
		starEffectDesc = 'Additional effect: When attacking a target affected by <Hunting> in the Frozen World, randomly invite two rear-line allies to perform a normal attack on the <Hunting> target.',
		starEffectDesc_en = 'Additional effect: When attacking a target affected by <Hunting> in the Frozen World, randomly invite two rear-line allies to perform a normal attack on the <Hunting> target.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อตีเป้าหมายที่ได้รับ <การล่าสัตว์> ในโลกน้ำแข็ง ให้เชิญสุ่มสองฮีโร่แถวหลังฝ่ายเราโจมตีปกติเป้าหมาย <การล่าสัตว์>',
		starEffectDesc_in = 'Efek tambahan: Saat menyerang target yang terkena <Berburu> di Dunia Beku, undang secara acak dua pahlawan barisan belakang dari pihak kita untuk melakukan serangan normal pada target <Berburu>.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag umaatake sa target na may <Pangangaso> sa Frozen World, pumili nang random ng dalawang huling hanay na mga kakampi upang mag-normal na atake sa target na may <Pangangaso>.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila menyerang sasaran yang terkena <Pemburuan> dalam Dunia Beku, jemput secara rawak dua wira barisan belakang dari pihak kita untuk menyerang sasaran <Pemburuan> secara biasa.',
		zawakeEffect = __data_t__zawakeEffect[32413],
		-- {79003}
		zawakeEffectDesc = 'Kyurem awakens under the glacier river, turning the whole world into a hunting ground and gaining 2 <Snowflakes>. If there is no <Hunting> target on the field, he will mark a random target in the enemy\'s back row as a <Hunting> target for 2 turns and turn the battlefield into <Ice World> for 2 turns, dealing damage to the target. Deals #C0xE69900#400% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Physical Damage#C0x5B545B#；\n#F10# \n#F40##L10#Ice World: #L0# Enemy speed and defense are halved, reduced by 30%. In the ice world, taunt <Hunting> targets (taunt: control effect, forcing the target to attack itself), steal 25% of the original double attack, 150 fury and buff effects, and have a 100% chance to be frozen. Freeze one random unfrozen enemy unit for 1 turn; if this special move causes the death of the <Hunting> target, the <Hunting> mark is immediately added to the enemy\'s back row; if the <Hunting> target dies in the frozen world, Kyurem gains 300 fury and a snowflake and permanently gains the double attack effect of looting.',
		zawakeEffectDesc_en = 'Kyurem awakens under the glacier river, turning the whole world into a hunting ground and gaining 2 <Snowflakes>. If there is no <Hunting> target on the field, he will mark a random target in the enemy\'s back row as a <Hunting> target for 2 turns and turn the battlefield into <Ice World> for 2 turns, dealing damage to the target. Deals #C0xE69900#400% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Physical Damage#C0x5B545B#；\n#F10# \n#F40##L10#Ice World: #L0# Enemy speed and defense are halved, reduced by 30%. In the ice world, taunt <Hunting> targets (taunt: control effect, forcing the target to attack itself), steal 25% of the original double attack, 150 fury and buff effects, and have a 100% chance to be frozen. Freeze one random unfrozen enemy unit for 1 turn; if this special move causes the death of the <Hunting> target, the <Hunting> mark is immediately added to the enemy\'s back row; if the <Hunting> target dies in the frozen world, Kyurem gains 300 fury and a snowflake and permanently gains the double attack effect of looting.',
		zawakeEffectDesc_th = 'คิวเร็มตื่นขึ้นใต้แม่น้ำธารน้ำแข็ง เปลี่ยนทั้งโลกให้เป็นสนามล่าเหยื่อและได้รับ 2 <เกล็ดหิมะ>. หากไม่มีเป้าหมาย <การล่า> บนสนาม เขาจะทำเครื่องหมายเป้าหมายสุ่มในแถวหลังของศัตรูเป็นเป้าหมาย <การล่า> เป็นเวลา 2 เทิร์น และเปลี่ยนสนามต่อสู้เป็น <โลกน้ำแข็ง> เป็นเวลา 2 เทิร์น ทำความเสียหายแก่เป้าหมาย ทำ #C0xE69900#400% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B#；\n#F10# \n#F40##L10#โลกน้ำแข็ง: #L0# ความเร็วและการป้องกันของศัตรูทั้งหมดลดลงเหลือครึ่งหนึ่งและลดลง 30%. ในโลกน้ำแข็ง เย้ยหยันเป้าหมาย <การล่า> (เย้ยหยัน: ควบคุมเอฟเฟกต์ บังคับเป้าหมายให้โจมตีตัวเอง), ขโมย 25% ของการโจมตีสองครั้งเดิม, 150 ความโกรธและเอฟเฟกต์บัฟ และมีโอกาส 100% ที่จะถูกแช่แข็ง. แช่แข็งศัตรูแบบสุ่มหนึ่งหน่วยที่ยังไม่ถูกแช่แข็งเป็นเวลา 1 เทิร์น; ถ้าความสามารถพิเศษนี้ทำให้เป้าหมาย <การล่า> ตาย เครื่องหมาย <การล่า> จะถูกเพิ่มทันทีในแถวหลังของศัตรู; ถ้าเป้าหมาย <การล่า> ตายในโลกน้ำแข็ง คิวเร็มจะได้รับ 300 ความโกรธและเกล็ดหิมะหนึ่งชิ้น และได้รับเอฟเฟกต์โจมตีสองครั้งจากการปล้นอย่างถาวร.',
		zawakeEffectDesc_in = 'Kyurem bangun di bawah sungai glasial, mengubah seluruh dunia menjadi area berburu dan mendapatkan 2 <Bunga Salju>. Jika tidak ada target <Berburu> di medan, dia akan menandai target acak di barisan belakang musuh sebagai target <Berburu> selama 2 giliran, dan mengubah medan menjadi <Dunia Es> selama 2 giliran, memberikan kerusakan ke target. Memberikan #C0xE69900#400% Damage Fisik#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Damage Fisik#C0x5B545B#；\n#F10# \n#F40##L10#Dunia Es: #L0# Kecepatan dan pertahanan semua musuh berkurang setengah dan berkurang 30%. Di dunia es, mengejek target <Berburu> (ejekan: efek kontrol, memaksa target menyerang dirinya sendiri), mencuri 25% serangan ganda asli, 150 amarah dan efek buff, serta memiliki kemungkinan 100% untuk membekukan. Membekukan satu unit musuh acak yang belum beku selama 1 giliran; jika kemampuan khusus ini menyebabkan kematian target <Berburu>, tanda <Berburu> segera ditambahkan ke barisan belakang musuh; jika target <Berburu> mati di dunia beku, Kyurem mendapatkan 300 amarah dan satu bunga salju dan secara permanen mendapatkan efek serangan ganda dari penjarahan.',
		zawakeEffectDesc_ph = 'Nagising si Kyurem sa ilalim ng glacier river, ginawa ang buong mundo na parang hunting ground at nakuha ang 2 <Snowflakes>. Kung walang target na <Pangangaso> sa field, mamarkahan niya ang isang random na target sa likurang hanay ng kalaban bilang <Pangangaso> target sa loob ng 2 turn, at gagawin ang battlefield na <Ice World> sa loob ng 2 turn, na nagdudulot ng pinsala sa target. Nagdudulot ng #C0xE69900#400% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Physical Damage#C0x5B545B#；\n#F10# \n#F40##L10#Ice World: #L0# Ang bilis at depensa ng lahat ng kalaban ay humahati sa dalawa at nababawasan ng 30%. Sa ice world, inaantagonize ang <Pangangaso> target (antagonize: control effect, pinipilit ang target na saktan ang sarili), nagnanakaw ng 25% ng orihinal na double attack, 150 galit at buff effect, at may 100% tsansa na ma-frozen. I-freeze ang isang random na hindi pa na-frozen na kalabang yunit sa loob ng 1 turn; kung ang special move na ito ay magdulot ng pagkamatay ng <Pangangaso> target, ang <Pangangaso> mark ay agad na idaragdag sa likurang hanay ng kalaban; kung ang <Pangangaso> target ay mamatay sa frozen world, makakatanggap si Kyurem ng 300 galit at isang snowflake at permanenteng makakakuha ng double attack effect mula sa pagnanakaw.',
		zawakeEffectDesc_ma = 'Kyurem bangun di bawah sungai glasier, mengubah seluruh dunia menjadi kawasan memburu dan mendapat 2 <Keping Salji>. Jika tiada sasaran <Memburu> di medan, dia akan menandakan sasaran rawak di barisan belakang musuh sebagai sasaran <Memburu> selama 2 giliran, dan mengubah medan menjadi <Dunia Ais> selama 2 giliran, menyerang sasaran. Melakukan #C0xE69900#400% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B#；\n#F10# \n#F40##L10#Dunia Ais: #L0# Kelajuan dan pertahanan semua musuh berkurang separuh dan berkurang 30%. Dalam dunia ais, mengejek sasaran <Memburu> (ejek: kesan kawalan, memaksa sasaran menyerang dirinya sendiri), mencuri 25% serangan berganda asal, 150 kemarahan dan kesan buff, serta mempunyai peluang 100% untuk dibekukan. Membekukan satu unit musuh rawak yang belum dibekukan selama 1 giliran; jika gerakan khas ini menyebabkan kematian sasaran <Memburu>, tanda <Memburu> akan segera ditambah ke barisan belakang musuh; jika sasaran <Memburu> mati dalam dunia beku, Kyurem akan mendapat 300 kemarahan dan satu keping salji dan secara kekal mendapat kesan serangan berganda dari penjarahan.',
		zawakeEffectDesc_vn = 'Kyurem thức dậy dưới dòng sông băng, biến cả thế giới thành bãi săn và lấy được 2 <Bông tuyết>. Nếu không có mục tiêu <Săn bắn> trên sân, anh ta sẽ đánh dấu một mục tiêu ngẫu nhiên ở hàng sau của kẻ địch làm mục tiêu <Săn bắn> trong 2 lượt, và biến sân đấu thành <Thế giới băng giá> trong 2 lượt, gây sát thương cho mục tiêu. Vào #C0xE69900#400% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B#；\n#F10# \n#F40##L10#Ice World: #L0# Tốc độ và khả năng phòng thủ gấp đôi của tất cả kẻ thù bị giảm 30%. Trong thế giới băng giá, chế nhạo <Săn bắn> mục tiêu (khiêu khích: kiểm soát hiệu ứng, buộc mục tiêu phải tự tấn công), cướp 25% đòn tấn công kép ban đầu, 150 cơn thịnh nộ và hiệu ứng buff, đồng thời có 100% khả năng bị đóng băng. Đóng băng một đơn vị kẻ địch chưa bị đóng băng ngẫu nhiên trong 1 lượt; nếu chiêu thức đặc biệt này dẫn đến cái chết của mục tiêu <Săn bắn>, dấu hiệu <Săn bắn> sẽ ngay lập tức được thêm vào hàng sau của kẻ địch; nếu mục tiêu <Săn bắn> chết trong thế giới đóng băng, Kyurem sẽ nhận 300 cơn thịnh nộ và một bông tuyết và vĩnh viễn nhận được hiệu ứng tấn công kép của cướp bóc.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#If the <Hunted> target dies in the Frozen World, Kyurem gains 300 Rage and one Snowflake, and permanently gains the double attack effect of Plunder#C0x5B545B#',
		zawakeSimpleDesc_en = '#C0x5c9970#If the <Hunted> target dies in the Frozen World, Kyurem gains 300 Rage and one Snowflake, and permanently gains the double attack effect of Plunder#C0x5B545B#',
		zawakeSimpleDesc_th = '#C0x5c9970#หากเป้าหมาย <ล่า> ตายในโลกน้ำแข็ง Kyurem จะได้รับโทสะ 300 หน่วยและเกล็ดหิมะ 1 อัน และถาวรได้รับผลของการโจมตีสองครั้งจาก Plunder#C0x5B545B#',
		zawakeSimpleDesc_in = '#C0x5c9970#Jika target <Buruan> mati dalam Dunia Beku, Kyurem akan mendapatkan 300 Rage dan satu kepingan salju, serta secara permanen mendapatkan efek serangan ganda dari Plunder#C0x5B545B#',
		zawakeSimpleDesc_ph = '#C0x5c9970#Kung mamatay ang target na <Hinahabol> sa nagyeyelong mundo, makakakuha si Kyurem ng 300 Rage at isang snowflake, at permanenteng makakakuha ng double attack effect mula sa Plunder#C0x5B545B#',
		zawakeSimpleDesc_ma = '#C0x5c9970#Jika sasaran <Buruan> mati di Dunia Beku, Kyurem akan mendapat 300 Kemarahan dan satu kepingan salji, serta secara kekal menerima kesan serangan berganda dari Plunder#C0x5B545B#',
		zawakeSimpleDesc_vn = '#C0x5c9970#Nếu mục tiêu <Săn bắn> chết trong thế giới đóng băng, Kyurem sẽ nhận 300 cơn thịnh nộ và một bông tuyết và vĩnh viễn nhận được hiệu ứng tấn công kép của cướp bóc #C0x5B545B#',
		upLvDesc = 'Fixed damage +360',
		upLvDesc_en = 'Fixed damage +360',
		upLvDesc_th = 'ความเสียหายคงที่ +360',
