	[32416] = {
		id = 32416,
		skillName_vn = 'Deep Cold Realm',
		skillName_en = 'Deep Cold Realm',
		skillName_th = 'อาณาจักรเย็นลึก',
		skillName_in = 'Alam Dingin Dalam',
		skillName_ph = 'Malalim na Malamig na Kaharian',
		skillName_ma = 'Alam Sejuk Mendalam',
		skillName = 'Deep Cold Realm',
		describe_vn = '#L10# Chôn cất băng tuyết: #L0# Miễn nhiễm với đóng băng. Khi người đứng đầu hoặc chính mình bị giết, một bộ xương băng sẽ bị bỏ lại. Bộ xương băng thừa hưởng 30% lượng máu giới hạn trên của Kyurem (giới hạn kích hoạt hai lần). Khi bị nghiền nát, nó gây 240% sát thương tấn Công Phép thuật ban đầu cho tất cả kẻ địch và có 100% xác suất đóng băng một đơn vị kẻ địch ngẫu nhiên trong 2 lượt\n#F10# \n#F40##L10#Snowflake Guard: #L0#Thêm bông tuyết cho bản thân theo số lượng kẻ địch lúc đầu (1/3/5 kẻ địch tương ứng với 1/2/3 bông tuyết, giới hạn trên là 3; khi một lần mất máu vượt quá 20% vượt quá giới hạn máu, người dùng bông tuyết sẽ bị tiêu hao Lượng máu mất này bằng 20% ​​giới hạn máu tối đa và có #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# xác suất đóng băng nguồn sát thương trong 1 hiệp)\n#F10# \n#F40##L10#Săn băng: #L0# Lúc đầu, đánh dấu một kẻ thù ngẫu nhiên ở hàng sau làm mục tiêu [Săn bắn] trong 2 lượt (chỉ có thể bị xua tan, giảm 900 tốc độ ban đầu. Khi cuộc săn kết thúc hoặc bị phân tán, có 100% khả năng đóng băng mục tiêu trong 1 lượt. Kyurem sẽ ưu tiên tấn công mục tiêu săn bắn)',
		describe_en = '#L10# Burial of Snow: #L0# Immune to freezing. When the leader or oneself is killed, an ice skeleton will be left behind. The ice skeleton inherits 30% of Kyurem’s max HP (limit activates twice). When shattered, it deals 240% magic attack damage to all enemies and has a 100% chance to freeze a random enemy unit for 2 turns.#F10# #F40# #L10# Snowflake Guard: #L0# Adds snowflakes to yourself based on the initial number of enemies (1/3/5 enemies correspond to 1/2/3 snowflakes, max 3). When losing more than 20% HP beyond the limit at once, the snowflake user loses that HP equal to 20% of max HP and has #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# chance to freeze the source of damage for 1 turn.#F10# #F40# #L10# Ice Hunt: #L0# At the start, marks a random enemy in the back row as the [Hunt] target for 2 turns (can only be dispelled, reduces initial speed by 900). When the hunt ends or is dispelled, there is a 100% chance to freeze the target for 1 turn. Kyurem prioritizes attacking the hunted target.',
		describe_th = '#L10# ฝังหิมะ: #L0# ภูมิคุ้มกันการถูกแช่แข็ง เมื่อนายท่านหรือผู้ใช้ถูกฆ่า โครงกระดูกน้ำแข็งจะถูกทิ้งไว้ โครงกระดูกน้ำแข็งสืบทอดพลังชีวิตสูงสุด 30% ของ Kyurem (จำกัดการเปิดใช้งาน 2 ครั้ง) เมื่อถูกทำลาย มันจะสร้างความเสียหายเวทมนตร์ 240% แก่ศัตรูทั้งหมดและมีโอกาส 100% ที่จะแช่แข็งศัตรูแบบสุ่ม 1 หน่วยเป็นเวลา 2 เทิร์น#F10# #F40# #L10# การป้องกันเกล็ดหิมะ: #L0# เพิ่มเกล็ดหิมะให้ตนเองตามจำนวนศัตรูเริ่มต้น (1/3/5 ศัตรูจะได้รับ 1/2/3 เกล็ดหิมะ สูงสุด 3) เมื่อต้องสูญเสียพลังชีวิตมากกว่า 20% ของขีดจำกัดในครั้งเดียว ผู้ใช้เกล็ดหิมะจะสูญเสียพลังชีวิตนี้เท่ากับ 20% ของพลังชีวิตสูงสุด และมีโอกาส #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# ที่จะแช่แข็งแหล่งที่มาของความเสียหายใน 1 เทิร์น#F10# #F40# #L10# การล่าน้ำแข็ง: #L0# เมื่อเริ่มต้น ทำเครื่องหมายศัตรูสุ่มในแถวหลังเป็นเป้าหมาย [ล่า] เป็นเวลา 2 เทิร์น (สามารถลบล้างได้เท่านั้น ลดความเร็วเริ่มต้นลง 900) เมื่อการล่าสิ้นสุดหรือถูกลบล้าง มีโอกาส 100% ที่จะแช่แข็งเป้าหมายเป็นเวลา 1 เทิร์น Kyurem จะเลือกโจมตีเป้าหมายที่ถูกล่าก่อน',
		describe_in = '#L10# Penguburan Salju: #L0# Kebal terhadap pembekuan. Ketika pemimpin atau diri sendiri terbunuh, akan tersisa kerangka es. Kerangka es mewarisi 30% dari HP maksimum Kyurem (batas aktivasi dua kali). Saat dihancurkan, kerangka es memberikan 240% kerusakan serangan sihir awal kepada semua musuh dan memiliki 100% peluang membekukan satu unit musuh secara acak selama 2 giliran.#F10# #F40# #L10# Penjaga Serpihan Salju: #L0# Menambahkan serpihan salju pada diri sendiri sesuai dengan jumlah musuh awal (1/3/5 musuh masing-masing mendapatkan 1/2/3 serpihan salju, maksimal 3). Ketika kehilangan lebih dari 20% HP melebihi batas sekaligus, pengguna serpihan salju akan kehilangan HP tersebut setara dengan 20% dari HP maksimum dan memiliki #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# peluang membekukan sumber kerusakan selama 1 giliran.#F10# #F40# #L10# Berburu Es: #L0# Pada awalnya, menandai satu musuh acak di barisan belakang sebagai target [Berburu] selama 2 giliran (hanya bisa dibersihkan, mengurangi kecepatan awal sebesar 900). Ketika berburu berakhir atau dibersihkan, ada 100% peluang membekukan target selama 1 giliran. Kyurem akan memprioritaskan menyerang target berburu.',
		describe_ph = '#L10# Libing ng Yelo: #L0# Immune sa nagyeyelong. Kapag ang pinuno o ang sarili ay napatay, isang ice skeleton ang maiiwan. Ang ice skeleton ay nagmamana ng 30% ng maximum HP ni Kyurem (limitadong activation ng dalawang beses). Kapag nabasag, nagdudulot ito ng 240% magic attack damage sa lahat ng kalaban at may 100% na tsansang nagyelo ang isang random na yunit ng kalaban sa loob ng 2 turn.#F10# #F40# #L10# Snowflake Guard: #L0# Nagdadagdag ng snowflakes sa sarili batay sa bilang ng mga kalaban sa simula (1/3/5 kalaban ay katumbas ng 1/2/3 snowflakes, hanggang 3). Kapag nawalan ng higit sa 20% HP nang sabay-sabay lampas sa limit, mawawala ang HP ng user ng snowflake na katumbas ng 20% ng maximum HP at may #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# na tsansa na nagyelo ang source ng damage sa loob ng 1 turn.#F10# #F40# #L10# Pagtangay ng Yelo: #L0# Sa simula, minamarkahan ang isang random na kalaban sa likod bilang target ng [Pagtangay] sa loob ng 2 turn (pwedeng tanggalin lang, binabawasan ng 900 ang initial speed). Kapag natapos ang pagtangay o na-disperse, may 100% tsansa na nagyelo ang target sa loob ng 1 turn. Inuuna ni Kyurem ang pag-atake sa target ng pagtangay.',
		describe_ma = '#L10# Pengkebumian Salji: #L0# Kebal terhadap pembekuan. Apabila ketua atau diri sendiri terbunuh, rangka ais akan ditinggalkan. Rangka ais mewarisi 30% daripada had maksimum HP Kyurem (had pengaktifan dua kali). Apabila hancur, ia menyebabkan 240% kerosakan serangan sihir asal kepada semua musuh dan mempunyai peluang 100% untuk membekukan satu unit musuh secara rawak selama 2 giliran.#F10# #F40# #L10# Penjaga Kelopak Salji: #L0# Tambah kelopak salji pada diri sendiri berdasarkan bilangan musuh awal (1/3/5 musuh masing-masing memberikan 1/2/3 kelopak salji, had maksimum 3). Apabila kehilangan lebih daripada 20% HP melewati had sekaligus, pengguna kelopak salji akan kehilangan HP ini sama dengan 20% daripada had maksimum HP dan mempunyai #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# peluang untuk membekukan sumber kerosakan selama 1 giliran.#F10# #F40# #L10# Pemburuan Ais: #L0# Pada permulaan, tandakan musuh rawak di barisan belakang sebagai sasaran [Pemburuan] selama 2 giliran (hanya boleh dibersihkan, mengurangkan kelajuan awal sebanyak 900). Apabila pemburuan berakhir atau dibersihkan, terdapat peluang 100% untuk membekukan sasaran selama 1 giliran. Kyurem akan mengutamakan menyerang sasaran pemburuan.',
		describe = '#L10# Burial of Snow: #L0# Immune to freezing. When the leader or oneself is killed, an ice skeleton will be left behind. The ice skeleton inherits 30% of Kyurem’s max HP (limit activates twice). When shattered, it deals 240% magic attack damage to all enemies and has a 100% chance to freeze a random enemy unit for 2 turns.#F10# #F40# #L10# Snowflake Guard: #L0# Adds snowflakes to yourself based on the initial number of enemies (1/3/5 enemies correspond to 1/2/3 snowflakes, max 3). When losing more than 20% HP beyond the limit at once, the snowflake user loses that HP equal to 20% of max HP and has #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# chance to freeze the source of damage for 1 turn.#F10# #F40# #L10# Ice Hunt: #L0# At the start, marks a random enemy in the back row as the [Hunt] target for 2 turns (can only be dispelled, reduces initial speed by 900). When the hunt ends or is dispelled, there is a 100% chance to freeze the target for 1 turn. Kyurem prioritizes attacking the hunted target.',
		starEffect = __data_t__starEffect[32416],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng phụ: Lần đầu tiên lượng máu xuống dưới 60% và 30%, hồi phục 20% máu và nhận 1 Bông Tuyết.',
		starEffectDesc = 'Side effect: The first time HP drops below 60% and 30%, restore 20% HP and receive 1 Snowflake.',
		starEffectDesc_en = 'Side effect: The first time HP drops below 60% and 30%, restore 20% HP and receive 1 Snowflake.',
		starEffectDesc_th = 'ผลข้างเคียง: ครั้งแรกที่ HP ลดลงต่ำกว่า 60% และ 30% ฟื้นฟู HP 20% และได้รับ 1 เกล็ดหิมะ',
		starEffectDesc_in = 'Efek samping: Pertama kali HP turun di bawah 60% dan 30%, pulihkan 20% HP dan dapatkan 1 Puspah Salju.',
		starEffectDesc_ph = 'Side effect: Sa unang beses na bumaba ang HP sa ilalim ng 60% at 30%, mag-recover ng 20% HP at makatanggap ng 1 Snowflake.',
		starEffectDesc_ma = 'Kesan sampingan: Kali pertama HP jatuh di bawah 60% dan 30%, pulihkan 20% HP dan terima 1 Bunga Salji.',
