	[32433] = {
		id = 32433,
		skillName_vn = 'Thế giới băng giá',
		skillName_en = 'Frozen world',
		skillName_th = 'โลกน้ำแข็ง',
		skillName_in = 'Dunia beku',
		skillName_ph = 'Niyalang mundo',
		skillName_ma = 'Dunia beku',
		skillName = 'Frozen world',
		describe_vn = '#C0xB15BFF#[Máy chủ thử nghiệm]#C0x5B545B#, Kyurem ngay lập tức nhận được 2 [Snowflakes] và biến sân thành [Frozen World] trong 2 hiệp: tốc độ và khả năng phòng thủ gấp đôi của tất cả đơn vị địch trong sân giảm 30%\n#F10# \n#F40#Nếu không có mục tiêu săn bắn trên sân, hãy đánh dấu một mục tiêu ngẫu nhiên ở hàng sau của kẻ địch làm mục tiêu [Săn bắn] trong 2 lượt, gây ra #C0xE69900#600% Sát Thương Vật Lý lên mục tiêu [Săn bắn]#C0x5B545B#+$(sk illLevel*4*90)$\'s #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, đồng thời khiêu khích mục tiêu để đòn tấn công tiếp theo của nó sẽ chỉ nhắm vào Kyurem, đồng thời giảm 30% đòn tấn công kép của mục tiêu và phong ấn cơn giận của mục tiêu.',
		describe_en = '#C0xB15BFF#[Test Server]#C0x5B545B#, Kyurem immediately gains 2 [Snowflakes] and transforms the field into [Frozen World] for 2 turns: speed and defense of all enemy units on the field are doubled and reduced by 30% \n#F10# \n#F40#If there is no hunting target on the field, randomly mark a target in the enemy\'s back row as the [Hunting] target for 2 turns, dealing #C0xE69900#600% Physical Damage to the [Hunting] target#C0x5B545B#+$(skillLevel*4*90)$\'s #C0xF13B54#Physical Damage#C0x5B545B#, and provoke the target so its next attack will only target Kyurem, while reducing the target\'s double attack by 30% and sealing its rage.',
		describe_th = '#C0xB15BFF#[เซิร์ฟเวอร์ทดลอง]#C0x5B545B# คิวเริมได้รับ [เกล็ดหิมะ] 2 ชิ้นทันที และเปลี่ยนสนามเป็น [โลกน้ำแข็ง] เป็นเวลา 2 เทิร์น: ความเร็วและการป้องกันของหน่วยศัตรูทั้งหมดในสนามเพิ่มเป็นสองเท่าและลดลง 30% \n#F10# \n#F40#ถ้าไม่มีเป้าหมายล่าบนสนาม ให้เลือกเป้าหมายสุ่มในแถวหลังของศัตรูเป็นเป้าหมาย [ล่า] เป็นเวลา 2 เทิร์น ทำให้เกิด #C0xE69900#600% ความเสียหายทางกายภาพแก่เป้าหมาย [ล่า]#C0x5B545B#+$(skillLevel*4*90)$\'s #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# พร้อมกับล่อเป้าหมายให้การโจมตีครั้งถัดไปมุ่งเป้าไปที่คิวเริมเท่านั้น และลดการโจมตีคู่ของเป้าหมายลง 30% พร้อมกับปิดผนึกความโกรธของเป้าหมาย',
		describe_in = '#C0xB15BFF#[Server Uji Coba]#C0x5B545B#, Kyurem segera mendapatkan 2 [Snowflakes] dan mengubah arena menjadi [Dunia Beku] selama 2 giliran: kecepatan dan pertahanan semua unit musuh di arena menjadi dua kali lipat dan berkurang 30% \n#F10# \n#F40#Jika tidak ada target berburu di arena, tandai secara acak satu target di barisan belakang musuh sebagai target [Berburu] selama 2 giliran, memberikan #C0xE69900#600% Kerusakan Fisik pada target [Berburu]#C0x5B545B#+$(skillLevel*4*90)$\'s #C0xF13B54#Kerusakan Fisik#C0x5B545B#, serta memancing target agar serangan berikutnya hanya menarget Kyurem, sekaligus mengurangi serangan ganda target sebesar 30% dan membekukan amarah target.',
		describe_ph = '#C0xB15BFF#[Test Server]#C0x5B545B#, Kyurem ay agad na tumanggap ng 2 [Snowflakes] at binago ang larangan sa [Frozen World] sa loob ng 2 turn: ang bilis at depensa ng lahat ng kalabang yunit sa larangan ay nadodoble at bumaba ng 30% \n#F10# \n#F40#Kung walang target na panghuli sa larangan, pumili ng isang random na target sa likurang hanay ng kalaban bilang [Pangangaso] target sa loob ng 2 turn, na nagdudulot ng #C0xE69900#600% Pisikal na Pinsala sa [Pangangaso] target#C0x5B545B#+$(skillLevel*4*90)$\'s #C0xF13B54#Pisikal na Pinsala#C0x5B545B#, at panuholin ang target upang ang susunod nitong atake ay tututok lamang kay Kyurem, habang binabawasan ang dobleng atake ng target ng 30% at pinipigilan ang galit ng target.',
		describe_ma = '#C0xB15BFF#[Server Ujian]#C0x5B545B#, Kyurem segera menerima 2 [Snowflakes] dan mengubah medan menjadi [Dunia Beku] selama 2 pusingan: kelajuan dan pertahanan semua unit musuh di medan menjadi dua kali ganda dan dikurangkan sebanyak 30% \n#F10# \n#F40#Jika tiada sasaran memburu di medan, tandakan satu sasaran rawak di barisan belakang musuh sebagai sasaran [Memburu] selama 2 pusingan, memberikan #C0xE69900#600% Kerosakan Fizikal kepada sasaran [Memburu]#C0x5B545B#+$(skillLevel*4*90)$\'s #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, serta menggoda sasaran supaya serangan seterusnya hanya akan menumpukan pada Kyurem, sambil mengurangkan serangan berganda sasaran sebanyak 30% dan membekukan kemarahan sasaran.',
		describe = '#C0xB15BFF#[Test Server]#C0x5B545B#, Kyurem immediately gains 2 [Snowflakes] and transforms the field into [Frozen World] for 2 turns: speed and defense of all enemy units on the field are doubled and reduced by 30% \n#F10# \n#F40#If there is no hunting target on the field, randomly mark a target in the enemy\'s back row as the [Hunting] target for 2 turns, dealing #C0xE69900#600% Physical Damage to the [Hunting] target#C0x5B545B#+$(skillLevel*4*90)$\'s #C0xF13B54#Physical Damage#C0x5B545B#, and provoke the target so its next attack will only target Kyurem, while reducing the target\'s double attack by 30% and sealing its rage.',
		simDesc_vn = 'Tổng quan về kỹ năng đặc biệt:',
		simDesc_en = 'Overview of special skills:',
		simDesc_th = 'ภาพรวมเกี่ยวกับทักษะพิเศษ:',
		simDesc_in = 'Ikhtisar keterampilan khusus:',
		simDesc_ph = 'Pangkalahatang-ideya ng mga espesyal na kasanayan:',
		simDesc_ma = 'Gambaran keseluruhan tentang kemahiran istimewa:',
		simDesc = 'Overview of special skills:',
		starEffect = __data_t__starEffect[32433],
		-- {11}
		starEffectDesc_vn = 'Giảm 30% song công của mục tiêu thành hấp thụ 30% song công của mục tiêu, nếu mục tiêu chết thì bản thân vĩnh viễn nhận được phần thưởng này, trong các lượt của màn chơi, khi bản thân tấn công mục tiêu bị "Săn đuổi", mục tiêu có tấn công cao nhất của phe ta cũng sẽ dùng tấn công thường để tấn công mục tiêu bị "Săn đuổi" một lần.',
		starEffectDesc = 'Reduce the target\'s dual attack by 30% to absorb 30% of the target\'s dual attack. If the target dies, you permanently receive this reward. During the turns of the stage, when you attack a target marked as "Hunted", the ally with the highest attack will also perform a normal attack on the "Hunted" target once.',
		starEffectDesc_en = 'Reduce the target\'s dual attack by 30% to absorb 30% of the target\'s dual attack. If the target dies, you permanently receive this reward. During the turns of the stage, when you attack a target marked as "Hunted", the ally with the highest attack will also perform a normal attack on the "Hunted" target once.',
		starEffectDesc_th = 'เปลี่ยนการลดการโจมตีคู่ของเป้าหมาย 30% เป็นการดูดซับการโจมตีคู่ของเป้าหมาย 30% หากเป้าหมายตาย ตัวเองจะได้รับรางวัลนี้ถาวร ในแต่ละเทิร์นของด่าน เมื่อคุณโจมตีเป้าหมายที่ถูก "ล่า" เป้าหมายที่มีการโจมตีสูงสุดในฝ่ายเราจะใช้การโจมตีปกติโจมตีเป้าหมายที่ถูก "ล่า" อีกครั้งหนึ่ง',
		starEffectDesc_in = 'Ubah pengurangan serangan ganda target sebesar 30% menjadi menyerap 30% serangan ganda target. Jika target mati, Anda akan menerima hadiah ini secara permanen. Dalam giliran permainan, ketika Anda menyerang target yang "Dikejar", target dengan serangan tertinggi di pihak kita juga akan menggunakan serangan biasa untuk menyerang target "Dikejar" tersebut sekali.',
		starEffectDesc_ph = 'Ibaba ang 30% na doble na atake ng target upang sumipsip ng 30% ng doble na atake ng target. Kung ang target ay mamatay, permanente mong matatanggap ang gantimpalang ito. Sa mga turn ng laro, kapag inaatake mo ang target na may markang "Hinahabol", ang target na may pinakamataas na atake sa ating panig ay gagamit din ng normal na atake upang atakihin ang "Hinahabol" na target nang isang beses.',
		starEffectDesc_ma = 'Tukar pengurangan serangan berganda sasaran sebanyak 30% kepada menyerap 30% serangan berganda sasaran. Jika sasaran mati, anda akan menerima ganjaran ini secara kekal. Dalam pusingan permainan, apabila anda menyerang sasaran yang "Dikejar", sasaran dengan serangan tertinggi dalam pihak kita juga akan menggunakan serangan biasa untuk menyerang sasaran "Dikejar" itu sekali.',
