	[32513] = {
		id = 32513,
		skillName_vn = 'Lời nguyền: Ngục Viêm',
		skillName_en = 'Curse: Flame Prison',
		skillName_th = 'คำสาป: คุกไฟ',
		skillName_in = 'Kutukan: Penjara Api',
		skillName_ph = 'Sumpa: Kulungan ng Apoy',
		skillName_ma = 'Sumpahan: Penjara Api',
		skillName = 'Curse: Flame Prison',
		describe_vn = 'Meliodas giải phóng mảng kiếm, chém một mục tiêu địch bằng thanh kiếm xé nát mọi thứ, gây #C0xF13B54# sát thương phép #C0x3D8A99#500% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#. Nếu bạn có 3 cấp độ kiếm giác trở lên, bạn sẽ bước vào [Thế thức thức tỉnh] kéo dài cho đến khi kết thúc trận chiến\n#F10# \n#F40##L10#Tư thế thức tỉnh: #L0#Hiệu ứng đặc biệt, sáu chiều ban đầu được tăng thêm 20% và hiệu ứng buff bị loại bỏ khỏi mục tiêu trước mỗi đòn tấn công.',
		describe_en = 'Meliodas unleashes a sword array, slashing an enemy target with a sword that tears everything apart, dealing #C0xF13B54# magic damage #C0x3D8A99#500% Magic Damage #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Magic Damage #C0x5B545B#. If you have 3 or more Sword Awakening levels, you will enter [Awakening Stance] lasting until the end of the battle\n#F10# \n#F40##L10#Awakening Stance: #L0#Special effect, the original six dimensions are increased by 20% and buff effects are removed from the target before each attack.',
		describe_th = 'เมลิโอดาสปลดปล่อยแถวดาบ ฟันเป้าหมายศัตรูด้วยดาบที่สับสลายทุกอย่าง สร้างความเสียหายเวทมนตร์ #C0xF13B54# #C0x3D8A99#500% ความเสียหายเวทมนตร์ #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# หากคุณมีระดับการปลุกดาบ 3 ขั้นขึ้นไป คุณจะเข้าสู่ [ท่าร่างปลุก] ซึ่งดำเนินต่อไปจนจบการต่อสู้\n#F10# \n#F40##L10#ท่าร่างปลุก: #L0#เอฟเฟกต์พิเศษ มิติเบื้องต้นทั้งหกจะเพิ่มขึ้น 20% และผลบัฟจะถูกลบออกจากเป้าหมายก่อนการโจมตีแต่ละครั้ง',
		describe_in = 'Meliodas melepaskan formasi pedang, menebas satu target musuh dengan pedang yang merobek segalanya, menyebabkan #C0xF13B54# kerusakan sihir #C0x3D8A99#500% Kerusakan Sihir #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#. Jika kamu memiliki 3 tingkat Kebangkitan Pedang atau lebih, kamu akan memasuki [Posisi Kebangkitan] yang bertahan hingga akhir pertempuran\n#F10# \n#F40##L10#Posisi Kebangkitan: #L0#Efek khusus, enam dimensi asli meningkat 20% dan efek buff dihapus dari target sebelum setiap serangan.',
		describe_ph = 'Pinakawalan ni Meliodas ang array ng espada, hinihampas ang isang kalaban gamit ang espada na siyang sumusuntok at pumupunit sa lahat, nagdudulot ng #C0xF13B54# magic damage #C0x3D8A99#500% Magic Damage #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Magic Damage #C0x5B545B#. Kung mayroon kang 3 o higit pang antas ng Sword Awakening, papasok ka sa [Awakening Stance] na tatagal hanggang matapos ang laban\n#F10# \n#F40##L10#Awakening Stance: #L0#Espesyal na epekto, ang orihinal na anim na dimensyon ay nadagdagan ng 20% at ang mga buff effect ay tinatanggal mula sa target bago bawat pag-atake.',
		describe_ma = 'Meliodas melepaskan susunan pedang, memotong satu sasaran musuh dengan pedang yang merobek segala-galanya, menyebabkan #C0xF13B54# kerosakan sihir #C0x3D8A99#500% Kerosakan Sihir #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Jika anda mempunyai 3 tahap Kebangkitan Pedang atau lebih, anda akan memasuki [Posisi Kebangkitan] yang berlangsung sehingga akhir pertempuran\n#F10# \n#F40##L10#Posisi Kebangkitan: #L0#Kesan khas, enam dimensi asal ditingkatkan sebanyak 20% dan kesan buff dialih keluar daripada sasaran sebelum setiap serangan.',
		describe = 'Meliodas unleashes a sword array, slashing an enemy target with a sword that tears everything apart, dealing #C0xF13B54# magic damage #C0x3D8A99#500% Magic Damage #C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Magic Damage #C0x5B545B#. If you have 3 or more Sword Awakening levels, you will enter [Awakening Stance] lasting until the end of the battle\n#F10# \n#F40##L10#Awakening Stance: #L0#Special effect, the original six dimensions are increased by 20% and buff effects are removed from the target before each attack.',
		simDesc_vn = 'Meliodas giải phóng đội hình kiếm, chém một mục tiêu địch bằng một thanh kiếm xé nát mọi thứ.',
		simDesc_en = 'Meliodas releases the sword formation, slashing an enemy target with a sword that tears through everything.',
		simDesc_th = 'เมลิโอดัสปลดปล่อยแผนผังดาบ ฟันเป้าหมายศัตรูด้วยดาบที่ฉีกทุกอย่างจนขาด.',
		simDesc_in = 'Meliodas melepaskan formasi pedang, mengayunkan pedang ke satu target musuh yang merobek segalanya.',
		simDesc_ph = 'Inilabas ni Meliodas ang sword formation, hinihata ang isang kalaban gamit ang isang espada na sumisira ng lahat.',
		simDesc_ma = 'Meliodas melepaskan formasi pedang, memotong sasaran musuh dengan pedang yang merobek segalanya.',
		simDesc = 'Meliodas releases the sword formation, slashing an enemy target with a sword that tears through everything.',
		starEffect = __data_t__starEffect[32513],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng thêm: Mỗi tầng Kiếm Nghĩa bỏ qua 10% kháng phép của mục tiêu, nếu có 5 tầng Kiếm Nghĩa, sẽ tạm thời tăng 50% tỷ lệ bạo kích trước khi tấn công.',
		starEffectDesc = 'Additional effect: Each layer of Sword Righteousness ignores 10% of the target\'s magic resistance. If there are 5 layers of Sword Righteousness, temporarily increase the critical hit rate by 50% before attacking.',
		starEffectDesc_en = 'Additional effect: Each layer of Sword Righteousness ignores 10% of the target\'s magic resistance. If there are 5 layers of Sword Righteousness, temporarily increase the critical hit rate by 50% before attacking.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: แต่ละชั้นของ ดาบศีลธรรม จะเพิกเฉยต่อการต้านเวทของเป้าหมาย 10% หากมี 5 ชั้นของ ดาบศีลธรรม จะเพิ่มอัตราคริติคอลขึ้นชั่วคราว 50% ก่อนโจมตี',
		starEffectDesc_in = 'Efek tambahan: Setiap lapisan Pedang Kebenaran mengabaikan 10% resistensi sihir target. Jika terdapat 5 lapisan Pedang Kebenaran, tingkatkan sementara peluang serangan kritis sebesar 50% sebelum menyerang.',
		starEffectDesc_ph = 'Karagdagang epekto: Bawat layer ng Sword Righteousness ay nilalampasan ang 10% magic resistance ng target. Kung may 5 layers ng Sword Righteousness, pansamantalang tumaas ng 50% ang critical hit rate bago umatake.',
		starEffectDesc_ma = 'Kesan tambahan: Setiap lapisan Pedang Kebenaran mengabaikan 10% ketahanan sihir sasaran. Jika terdapat 5 lapisan Pedang Kebenaran, sementara masa meningkatkan kadar serangan kritikal sebanyak 50% sebelum menyerang.',
		zawakeEffect = __data_t__zawakeEffect[32513],
		-- {79003}
		zawakeEffectDesc = 'Meliodas unleashes a sword array, slashing an enemy target with a sword that tears everything apart, dealing #C0xF13B54# magic damage #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*75)$#C0x5B545B#. If you have 3 or more sword awakening levels, you will enter <Awakening Stance> lasting until the end of the battle\n#F10# \n#F40##L10#Awakening Stance: #L0#Special effect, the original six directions are increased by 25% and the buff effects are removed from the target before each attack.',
		zawakeEffectDesc_en = 'Meliodas unleashes a sword array, slashing an enemy target with a sword that tears everything apart, dealing #C0xF13B54# magic damage #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*75)$#C0x5B545B#. If you have 3 or more sword awakening levels, you will enter <Awakening Stance> lasting until the end of the battle\n#F10# \n#F40##L10#Awakening Stance: #L0#Special effect, the original six directions are increased by 25% and the buff effects are removed from the target before each attack.',
		zawakeEffectDesc_th = 'Meliodas ปลดปล่อยดาบเรียงตัว ฟันเป้าหมายศัตรูด้วยดาบที่ฉีกทุกสิ่งให้ขาด ทำให้เกิด #C0xF13B54# ความเสียหายเวท #C0x3D8A99#500% ความเสียหายเวท#C0x5B545B#+$(skillLevel*4*75)$#C0x5B545B#. หากคุณมีเลเวลดาบตื่น 3 ขึ้นไป คุณจะเข้าสู่ <ท่าตื่นตัว> ซึ่งใช้ได้นานจนจบการต่อสู\n#F10# \n#F40##L10#ท่าตื่นตัว: #L0#เอฟเฟกต์พิเศษ แบริเวณหกทิศเดิมเพิ่มขึ้น 25% และเอฟเฟกต์บัฟถูกลบออกจากเป้าหมายก่อนการโจมตีแต่ละครั้ง',
		zawakeEffectDesc_in = 'Meliodas melepaskan formasi pedang, mengiris target musuh dengan pedang yang merobek segala sesuatu, memberikan #C0xF13B54# kerusakan sihir #C0x3D8A99#500% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*75)$#C0x5B545B#. Jika kamu memiliki level awakening pedang 3 atau lebih, kamu akan memasuki <Pose Awakening> yang berlangsung hingga akhir pertempuran\n#F10# \n#F40##L10#Pose Awakening: #L0#Efek khusus, enam arah asli ditingkatkan 25% dan efek buff dihapus dari target sebelum setiap serangan.',
		zawakeEffectDesc_ph = 'Pinakawalan ni Meliodas ang sword array, pinutol ang isang target na kalaban gamit ang espada na pumupunit ng lahat, na nagdudulot ng #C0xF13B54# magic damage #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*75)$#C0x5B545B#. Kung mayroon kang 3 o higit pang level ng sword awakening, papasok ka sa <Awakening Stance> na tumatagal hanggang matapos ang laban\n#F10# \n#F40##L10#Awakening Stance: #L0#Espesyal na epekt, ang orihinal na anim na direksyon ay nadagdagan ng 25% at ang mga buff effect ay tinanggal mula sa target bago bawat pag-atake.',
		zawakeEffectDesc_ma = 'Meliodas melepaskan formasi pedang, memotong sasaran musuh dengan pedang yang merobek segala-galanya, menyebabkan #C0xF13B54# kerosakan sihir #C0x3D8A99#500% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*75)$#C0x5B545B#. Jika anda mempunyai tahap pembangkitan pedang 3 atau lebih, anda akan memasuki <Posisi Pembangkitan> yang berlangsung sehingga akhir pertarungan\n#F10# \n#F40##L10#Posisi Pembangkitan: #L0#Kesan istimewa, enam arah asal meningkat sebanyak 25% dan kesan buff dikeluarkan daripada sasaran sebelum setiap serangan.',
		zawakeEffectDesc_vn = 'Meliodas giải phóng mảng kiếm, chém một mục tiêu địch bằng thanh kiếm xé nát mọi thứ, gây #C0xF13B54# sát thương phép #C0x3D8A99#500% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*75)$#C0x5B545B#. Nếu bạn có 3 cấp độ kiếm giác trở lên, bạn sẽ bước vào <Thế thức thức tỉnh> kéo dài cho đến khi kết thúc trận chiến\n#F10# \n#F40##L10#Tư thế thức tỉnh: #L0#Hiệu ứng đặc biệt, sáu chiều ban đầu được tăng thêm 25% và hiệu ứng buff bị loại bỏ khỏi mục tiêu trước mỗi đòn tấn công.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Initial six dimensions of the Awakening Stance increase by 20%\n#F20# \n#F40##C0x5c9970#→Initial six dimensions of the Awakening Stance increase by 25%',
		zawakeSimpleDesc_en = 'Initial six dimensions of the Awakening Stance increase by 20%\n#F20# \n#F40##C0x5c9970#→Initial six dimensions of the Awakening Stance increase by 25%',
		zawakeSimpleDesc_th = 'มิติเริ่มต้นทั้งหกของท่าตื่นรู้เพิ่มขึ้น 20%\n#F20# \n#F40##C0x5c9970#→มิติเริ่มต้นทั้งหกของท่าตื่นรู้เพิ่มขึ้น 25%',
		zawakeSimpleDesc_in = 'Enam dimensi awal dari pose Kebangkitan meningkat 20%\n#F20# \n#F40##C0x5c9970#→Enam dimensi awal dari pose Kebangkitan meningkat 25%',
		zawakeSimpleDesc_ph = 'Ang unang anim na dimensyon ng Awakening Stance ay tumataas ng 20%\n#F20# \n#F40##C0x5c9970#→Tumataas ng 25%',
		zawakeSimpleDesc_ma = 'Enam dimensi awal Gaya Kebangkitan meningkat sebanyak 20%\n#F20# \n#F40##C0x5c9970#→Enam dimensi awal Gaya Kebangkitan meningkat sebanyak 25%',
		zawakeSimpleDesc_vn = 'Sáu chiều ban đầu của tư thế thức tỉnh tăng thêm 20%\n#F20# \n#F40##C0x5c9970#→Sáu chiều ban đầu của tư thế thức tỉnh tăng thêm 25%',
