	[32516] = {
		id = 32516,
		skillName_vn = 'Tội lỗi của sự giận dữ',
		skillName_en = 'The sin of anger',
		skillName_th = 'บาปแห่งความโกรธ',
		skillName_in = 'Dosa kemarahan',
		skillName_ph = 'Kasalanan ng galit',
		skillName_ma = 'Dosa kemarahan',
		skillName = 'The sin of anger',
		describe_vn = 'Khi HP tấn công của kẻ địch thấp hơn 50% của phe đồng minh, Meliodas có xác suất #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# (nếu kẻ địch Nếu Fang là anh hùng bóng tối, có xác suất 100%) để ngay lập tức phản công hắn bằng đòn tấn công bình thường. Trong tư thế thức tỉnh, anh ta sẽ phản công bằng một chiêu thức đặc biệt giúp tránh tiêu hao. Chiêu thức đặc biệt có thể được kích hoạt tối đa 3 lần trên toàn sân (sau khi đạt giới hạn trên, anh ta vẫn sẽ sử dụng đòn đánh thường để phản công).',
		describe_en = 'When the enemy\'s attack HP is below 50% of the allied side, Meliodas has a #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# chance (if the enemy Fang is a dark hero, the chance is 100%) to immediately counterattack him with a normal attack. In awakened state, he will counterattack with a special move that helps avoid consumption. The special move can be triggered up to 3 times on the entire field (after reaching the limit, he will continue to counterattack using normal attacks).',
		describe_th = 'เมื่อ HP การโจมตีของศัตรูต่ำกว่า 50% ของฝ่ายพันธมิตร Meliodas มีโอกาส #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# (หากศัตรู Fang เป็นฮีโร่แห่งความมืด โอกาสเป็น 100%) ในการสวนกลับทันทีด้วยการโจมตีปกติ ในสถานะตื่นตัว เขาจะสวนกลับด้วยท่าไม้ตายพิเศษที่ช่วยหลีกเลี่ยงการใช้พลัง ท่าไม้ตายพิเศษสามารถเปิดใช้ได้สูงสุด 3 ครั้งทั่วสนาม (หลังจากถึงขีดจำกัด จะใช้การโจมตีปกติในการสวนกลับแทน)',
		describe_in = 'Ketika HP serangan musuh kurang dari 50% dari pihak sekutu, Meliodas memiliki peluang #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# (jika musuh Fang adalah pahlawan gelap, memiliki peluang 100%) untuk segera membalas serangan dengan serangan biasa. Dalam keadaan terbangun, dia akan membalas dengan serangan khusus yang membantu menghindari konsumsi. Serangan khusus dapat diaktifkan maksimal 3 kali di seluruh medan (setelah batas tercapai, dia tetap akan menggunakan serangan biasa untuk membalas).',
		describe_ph = 'Kapag ang HP ng pag-atake ng kalaban ay bumaba sa ilalim ng 50% ng panig ng alyado, si Meliodas ay may #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# na tsansa (kung ang kalaban na si Fang ay isang madilim na bayani, may 100% na tsansa) na agad na kontrahin siya gamit ang normal na pag-atake. Sa paggising na estado, magko-counterattack siya gamit ang isang espesyal na galaw na tumutulong iwasan ang pag-ubos. Ang espesyal na galaw ay maaaring ma-activate hanggang 3 beses sa buong larangan (pagkatapos maabot ang hangganan, gagamitin pa rin niya ang normal na pag-atake para mag-counterattack).',
		describe_ma = 'Apabila HP serangan musuh kurang daripada 50% daripada pihak sekutu, Meliodas mempunyai kebarangkalian #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# (jika musuh Fang adalah wira kegelapan, mempunyai kebarangkalian 100%) untuk segera menyerang balas dengan serangan biasa. Dalam keadaan terjaga, dia akan menyerang balas dengan serangan khas yang membantu mengelakkan penggunaan. Serangan khas boleh diaktifkan sehingga 3 kali di seluruh medan (selepas mencapai had, dia akan terus menggunakan serangan biasa untuk menyerang balas).',
		describe = 'When the enemy\'s attack HP is below 50% of the allied side, Meliodas has a #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# chance (if the enemy Fang is a dark hero, the chance is 100%) to immediately counterattack him with a normal attack. In awakened state, he will counterattack with a special move that helps avoid consumption. The special move can be triggered up to 3 times on the entire field (after reaching the limit, he will continue to counterattack using normal attacks).',
		starEffect = __data_t__starEffect[32516],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi bất kỳ đồng minh nào bị hạ gục, giải 1 hiệu ứng khống chế lên bản thân và nhận 1 tầng Kiếm Nghĩa.',
		starEffectDesc = 'Additional effect: When any ally is defeated, dispel 1 control effect on yourself and gain 1 stack of Sword Righteousness.',
		starEffectDesc_en = 'Additional effect: When any ally is defeated, dispel 1 control effect on yourself and gain 1 stack of Sword Righteousness.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อพันธมิตรใด ๆ ถูกกำจัด จะปลดปล่อย 1 ผลกระทบควบคุมบนตัวเองและได้รับ 1 ชั้นของ อุดมการณ์ดาบ',
		starEffectDesc_in = 'Efek tambahan: Saat sekutu mana pun dikalahkan, hapus 1 efek kontrol pada diri sendiri dan dapatkan 1 tumpukan Pedang Kebenaran.',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag ang sinumang kakampi ay natalo, alisin ang 1 kontrol na epekto sa sarili at tumanggap ng 1 layer ng Sword Righteousness.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila mana-mana sekutu dikalahkan, hilangkan 1 kesan kawalan pada diri sendiri dan terima 1 lapisan Pedang Keadilan.',
		zawakeEffect = __data_t__zawakeEffect[32516],
		-- {79004, 1}
		zawakeEffectDesc = 'Additional effect: When any allied group is killed, it removes 1 control effect on itself and gains 1 layer of sword of justice. If it reaches 3 or more layers of sword, it immediately enters the awakening state.',
		zawakeEffectDesc_en = 'Additional effect: When any allied group is killed, it removes 1 control effect on itself and gains 1 layer of sword of justice. If it reaches 3 or more layers of sword, it immediately enters the awakening state.',
		zawakeEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อกลุ่มพันธมิตรใด ๆ ถูกฆ่า มันจะลบ 1 เอฟเฟกต์ควบคุมบนตัวเองและได้รับ 1 ชั้นดาบแห่งความยุติธรรม หากถึง 3 ชั้นดาบขึ้นไปจะเข้าสู่สถานะการตื่นรู้ทันที',
		zawakeEffectDesc_in = 'Efek tambahan: Ketika kelompok sekutu mana pun terbunuh, itu menghapus 1 efek kontrol pada dirinya sendiri dan mendapatkan 1 lapisan pedang keadilan. Jika mencapai 3 lapisan pedang atau lebih, itu langsung memasuki keadaan kesadaran.',
		zawakeEffectDesc_ph = 'Karagdagang epekto: Kapag ang anumang grup ng allies ay napatay, tinatanggal nito ang 1 control effect sa sarili nito at nakakamit ang 1 layer ng sword of justice. Kapag umabot sa 3 layer ng sword o higit pa, agad itong papasok sa estado ng awakening.',
		zawakeEffectDesc_ma = 'Kesan tambahan: Apabila mana-mana kumpulan sekutu terbunuh, ia membuang 1 kesan kawalan ke atas dirinya dan menerima 1 lapisan pedang keadilan. Jika mencapai 3 lapisan pedang atau lebih, ia akan terus memasuki keadaan kebangkitan.',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: Khi bất kỳ nhóm đồng minh nào bị giết, nó sẽ loại bỏ 1 hiệu ứng khống chế lên chính nó và nhận được 1 lớp kiếm công lý. Nếu đạt tới 3 tầng kiếm công trở lên sẽ ngay lập tức tiến vào trạng thái thức tỉnh.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#If reaching level 3 of Sword Intent, you will immediately enter Awakening Stance.',
		zawakeSimpleDesc_en = '#C0x5c9970#If reaching level 3 of Sword Intent, you will immediately enter Awakening Stance.',
		zawakeSimpleDesc_th = '#C0x5c9970#หากถึงระดับ 3 ของจิตดาบ จะเข้าสู่ท่าตื่นรู้ทันที',
		zawakeSimpleDesc_in = '#C0x5c9970#Jika mencapai tingkat 3 Makna Pedang, langsung masuk ke pose Kebangkitan',
		zawakeSimpleDesc_ph = '#C0x5c9970#Kapag nakaabot ng level 3 ng Kahulugan ng Espada, agad papasok sa Awakening Stance',
		zawakeSimpleDesc_ma = '#C0x5c9970#Jika mencapai Tahap 3 Maksud Pedang, akan segera memasuki Gaya Kebangkitan',
		zawakeSimpleDesc_vn = '#C0x5c9970#Nếu đạt cấp độ 3 kiếm nghĩa trở lên, bạn sẽ ngay lập tức vào tư thế thức tỉnh.',
		iconRes = 'battle/skill_icon/skill_32516.png',
