	[32612] = {
		id = 32612,
		skillName_vn = 'Tấn công tinh thần',
		skillName_en = 'Mental attack',
		skillName_th = 'การโจมตีทางจิต',
		skillName_in = 'Serangan mental',
		skillName_ph = 'Mental na atake',
		skillName_ma = 'Serangan mental',
		skillName = 'Mental attack',
		describe_vn = '#L10# Dạng nhảy: #L0# Meloetta tấn công bất kỳ mục tiêu nào bằng chân bay, gây #C0xE69900#120% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Sát Thương Vật Lý#C0x5B54 5B#, sử dụng [Pink Melody Fruit] với xác suất ảo 100% lên mục tiêu chính (Bóng ma: hiệu ứng khống chế, buộc sử dụng đòn đánh thường để tấn công đồng minh) và sử dụng [Quả giai điệu vàng]: 40% khả năng tạo bóng ma một đơn vị ngẫu nhiên ở hàng sau trong 1 lượt (ưu tiên mục tiêu không ở trạng thái mê hoặc hoặc ma)\n#F10# \n#F40##L10#Dạng hát: #L0# Meloetta phát ra tia nhạc tấn công bất kỳ mục tiêu nào, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel* 4*48)$ của #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, sử dụng [Blue Melody Fruit] để khiến Meloetta tàng hình cho đến hành động tiếp theo trong hình thức hát. Sau khi phá vỡ khả năng tàng hình, 20% HP của cô sẽ được phục hồi.',
		describe_en = 'Form Jump: Meloetta attacks any target with flying kick, causing 120% Physical Damage + $(skillLevel*4*48)$ Physical Damage, uses [Pink Melody Fruit] with a virtual 100% chance on the main target (Phantom: control effect, forcing the use of normal attacks to hit allies) and uses [Golden Melody Fruit]: 40% chance to create a phantom of a random unit in the back row for 1 turn (prioritizing targets not charmed or phantoms). Form Sing: Meloetta emits a musical beam to attack any target, causing 180% Magical Damage + $(skillLevel*4*48)$ Magical Damage, uses [Blue Melody Fruit] to make Meloetta invisible until the next action in sing form. After breaking invisibility, 20% of her HP will be restored.',
		describe_th = 'รูปแบบกระโดด: เมโลเอตต้าโจมตีเป้าหมายใดก็ได้ด้วยการเตะบิน สร้างความเสียหายทางกายภาพ 120% + $(skillLevel*4*48)$ ความเสียหายทางกายภาพ ใช้ [ผลไม้เมโลดีสีชมพู] มีโอกาสเสมือนจริง 100% กับเป้าหมายหลัก (ผีเสื้อ: ผลกระทบควบคุม บังคับให้ใช้การโจมตีปกติต่อพันธมิตร) และใช้ [ผลไม้เมโลดีสีทอง]: โอกาส 40% สร้างผียุ่งของยูนิตสุ่มในแถวหลัง 1 เทิร์น (ให้ความสำคัญกับเป้าหมายที่ไม่ได้ถูกสะกดจิตหรือผีเสื้อมาก่อน). รูปแบบร้องเพลง: เมโลเอตต้าปล่อยลำแสงเพลงโจมตีเป้าหมายใดก็ได้ สร้างความเสียหายทางเวทย์ 180% + $(skillLevel*4*48)$ ความเสียหายทางเวทย์ ใช้ [ผลไม้เมโลดีสีน้ำเงิน] ทำให้เมโลเอต้าซ่อนตัวจนกว่าจะกระทำการถัดไปในรูปแบบร้องเพลง หลังจากที่การซ่อนตัวถูกทำลาย จะฟื้นฟู HP 20% ของเธอ.',
		describe_in = 'Bentuk Lompat: Meloetta menyerang target mana pun dengan tendangan terbang, menyebabkan 120% Damage Fisik + $(skillLevel*4*48)$ Damage Fisik, menggunakan [Buah Melodi Merah Muda] dengan peluang virtual 100% pada target utama (Hantu: efek kontrol, memaksa menggunakan serangan normal untuk menyerang sekutu) dan menggunakan [Buah Melodi Emas]: 40% kemungkinan menciptakan hantu dari satu unit acak di barisan belakang selama 1 giliran (mengutamakan target yang tidak berada dalam kondisi terpikat atau hantu). Bentuk Nyanyi: Meloetta mengeluarkan sinar musik untuk menyerang target mana pun, menyebabkan 180% Damage Magis + $(skillLevel*4*48)$ Damage Magis, menggunakan [Buah Melodi Biru] untuk membuat Meloetta menghilang hingga aksi berikutnya dalam bentuk nyanyi. Setelah penghilangan terputus, 20% HP-nya akan pulih.',
		describe_ph = 'Form Jump: Meloetta ayusin ang kahit anong target gamit ang flying kick, nagdudulot ng 120% Physical Damage + $(skillLevel*4*48)$ Physical Damage, gumagamit ng [Pink Melody Fruit] na may virtual 100% na tsansa sa pangunahing target (Phantom: control effect, pinipilit gumamit ng normal na atake para tamaan ang mga kakampi) at gumagamit ng [Golden Melody Fruit]: 40% tsansang makagawa ng phantom ng isang random unit sa likurang hanay sa loob ng 1 turn (pinaprioritize ang target na hindi na-fascinate o phantom). Form Sing: Meloetta naglalabas ng musical beam para atakihin ang kahit anong target, nagdudulot ng 180% Magical Damage + $(skillLevel*4*48)$ Magical Damage, gumagamit ng [Blue Melody Fruit] para gawing invisible si Meloetta hanggang sa susunod na aksyon sa sing form. Pag na-break ang invisibility, mare-recover ang 20% ng kanyang HP.',
		describe_ma = 'Bentuk Melompat: Meloetta menyerang mana-mana sasaran dengan tendangan terbang, menyebabkan 120% Kerosakan Fizikal + $(skillLevel*4*48)$ Kerosakan Fizikal, menggunakan [Buah Melodi Merah Jambu] dengan kebarangkalian maya 100% pada sasaran utama (Hantu: kesan kawalan, memaksa penggunaan serangan biasa untuk menyerang sekutu) dan menggunakan [Buah Melodi Emas]: 40% kemungkinan mencipta hantu bagi satu unit rawak di barisan belakang selama 1 pusingan (mengutamakan sasaran yang tidak dalam keadaan terpesona atau hantu). Bentuk Nyanyian: Meloetta memancarkan sinaran muzik untuk menyerang mana-mana sasaran, menyebabkan 180% Kerosakan Sihir + $(skillLevel*4*48)$ Kerosakan Sihir, menggunakan [Buah Melodi Biru] untuk menjadikan Meloetta tidak kelihatan sehingga tindakan seterusnya dalam bentuk nyanyian. Selepas menyekat kebolehan tidak kelihatan, 20% HPnya akan dipulihkan.',
		describe = 'Form Jump: Meloetta attacks any target with flying kick, causing 120% Physical Damage + $(skillLevel*4*48)$ Physical Damage, uses [Pink Melody Fruit] with a virtual 100% chance on the main target (Phantom: control effect, forcing the use of normal attacks to hit allies) and uses [Golden Melody Fruit]: 40% chance to create a phantom of a random unit in the back row for 1 turn (prioritizing targets not charmed or phantoms). Form Sing: Meloetta emits a musical beam to attack any target, causing 180% Magical Damage + $(skillLevel*4*48)$ Magical Damage, uses [Blue Melody Fruit] to make Meloetta invisible until the next action in sing form. After breaking invisibility, 20% of her HP will be restored.',
		zawakeEffect = __data_t__zawakeEffect[32612],
		-- {79002}
		zawakeEffectDesc = '#L10# Jump Form: #L0# Meloetta attacks any target with flying kick, causing #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Physical Damage#C0x5B545B#, using <Pink Melody Fruit> with a 100% virtual chance on the main target (Shadow: control effect, forced to use normal attacks to attack allies) and using <Golden Melody Fruit>: has a 60% chance to create a shadow of a random unit in the back row for 1 turn (prioritizing targets not under charm or shadow status)\n#F10# \n#F40##L10# Sing Form: #L0# Meloetta emits a music beam to attack any target, causing #C0x3D8A99#180% Spell Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Spell Damage#C0x5B545B#, using <Blue Melody Fruit> to make Meloetta invisible. During this time, damage of the column you are in is reduced by 15%. This lasts until the next action in singing form. After breaking invisibility, 20% of your HP will be restored.',
		zawakeEffectDesc_en = '#L10# Jump Form: #L0# Meloetta attacks any target with flying kick, causing #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Physical Damage#C0x5B545B#, using <Pink Melody Fruit> with a 100% virtual chance on the main target (Shadow: control effect, forced to use normal attacks to attack allies) and using <Golden Melody Fruit>: has a 60% chance to create a shadow of a random unit in the back row for 1 turn (prioritizing targets not under charm or shadow status)\n#F10# \n#F40##L10# Sing Form: #L0# Meloetta emits a music beam to attack any target, causing #C0x3D8A99#180% Spell Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Spell Damage#C0x5B545B#, using <Blue Melody Fruit> to make Meloetta invisible. During this time, damage of the column you are in is reduced by 15%. This lasts until the next action in singing form. After breaking invisibility, 20% of your HP will be restored.',
		zawakeEffectDesc_th = '#L10# รูปแบบกระโดด: #L0# Meloetta โจมตีเป้าหมายใด ๆ ด้วยการเตะบิน ทำให้เกิด #C0xE69900#120% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# โดยใช้ <Pink Melody Fruit> ด้วยโอกาสเสมือน 100% กับเป้าหมายหลัก (เงา: ผลของการควบคุม บังคับให้ใช้การโจมตีปกติเพื่อโจมตีพันธมิตร) และใช้ <Golden Melody Fruit>: มีโอกาส 60% ในการสร้างเงาของหน่วยสุ่มหนึ่งตัวที่แถวหลังเป็นเวลา 1 เทิร์น (ให้ความสำคัญกับเป้าหมายที่ไม่ได้อยู่ในสถานะหลงใหลหรือเงา)\n#F10# \n#F40##L10# รูปแบบร้องเพลง: #L0# Meloetta ปล่อยลำแสงดนตรีโจมตีเป้าหมายใด ๆ ทำให้เกิด #C0x3D8A99#180% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายจากเวทมนตร์#C0x5B545B# โดยใช้ <Blue Melody Fruit> เพื่อทำให้ Meloetta ล่องหน ในช่วงเวลานี้ ความเสียหายของคอลัมน์ที่คุณอยู่จะลดลง 15% ซึ่งจะคงอยู่จนกว่าจะถึงการกระทำถัดไปในรูปแบบการร้องเพลง หลังจากทำลายความล่องหนไปแล้ว พลังชีวิตของคุณ 20% จะถูกฟื้นฟู',
		zawakeEffectDesc_in = '#L10# Bentuk Melompat: #L0# Meloetta menyerang target mana pun dengan tendangan terbang, menyebabkan #C0xE69900#120% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerusakan Fisik#C0x5B545B#, menggunakan <Pink Melody Fruit> dengan peluang virtual 100% pada target utama (Bayangan: efek kontrol, dipaksa menggunakan serangan normal untuk menyerang sekutu) dan menggunakan <Golden Melody Fruit>: memiliki peluang 60% untuk menciptakan bayangan dari unit acak di barisan belakang selama 1 giliran (memprioritaskan target yang tidak dalam status terpikat atau bayangan)\n#F10# \n#F40##L10# Bentuk Bernyanyi: #L0# Meloetta mengeluarkan sinar musik untuk menyerang target mana pun, menyebabkan #C0x3D8A99#180% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerusakan Sihir#C0x5B545B#, menggunakan <Blue Melody Fruit> untuk membuat Meloetta menjadi tak terlihat. Selama waktu ini, kerusakan kolom tempat Anda berada berkurang 15%. Ini berlangsung hingga tindakan berikutnya dalam bentuk bernyanyi. Setelah menghilangkan kemampuan tak terlihat, 20% HP Anda akan dipulihkan.',
		zawakeEffectDesc_ph = '#L10# Hugis ng Tatalon: #L0# Meloetta ay inaatake ang sinumang target gamit ang flying kick, nagdudulot ng #C0xE69900#120% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Pisikal na Pinsala#C0x5B545B#, gamit ang <Pink Melody Fruit> na may 100% na virtual na tsansa sa pangunahing target (Anino: kontrol na epekto, pinipilit gumamit ng normal na atake upang atakihin ang mga kaalyado) at gamit ang <Golden Melody Fruit>: may 60% tsansa na lumikha ng anino ng isang random na yunit sa likurang hanay sa loob ng 1 turn (binibigyang prayoridad ang mga target na hindi nasa status na naakit o anino)\n#F10# \n#F40##L10# Hugis ng Pag-awit: #L0# Meloetta ay nagpapalabas ng sinag ng musika upang atakihin ang sinumang target, nagdudulot ng #C0x3D8A99#180% Sakit ng Spell#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Pinsala ng Spell#C0x5B545B#, gamit ang <Blue Melody Fruit> upang gawing invisible si Meloetta. Sa panahong ito, ang pinsala ng haligi na kinaroroonan mo ay bumaba ng 15%. Ito ay magtatagal hanggang sa susunod na aksyon sa anyo ng pag-awit. Pagkatapos mabasag ang invisibility, 20% ng iyong HP ay mare-recover.',
		zawakeEffectDesc_ma = '#L10# Bentuk Lompat: #L0# Meloetta menyerang mana-mana sasaran dengan tendangan terbang, menyebabkan #C0xE69900#120% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerosakan Fizikal#C0x5B545B#, menggunakan <Pink Melody Fruit> dengan kebarangkalian maya 100% ke sasaran utama (Bayang: kesan kawalan, dipaksa menggunakan serangan biasa untuk menyerang sekutu) dan menggunakan <Golden Melody Fruit>: mempunyai kebarangkalian 60% untuk mencipta bayang satu unit secara rawak di barisan belakang untuk 1 pusingan (mengutamakan sasaran yang tidak berada dalam keadaan terpesona atau bayang)\n#F10# \n#F40##L10# Bentuk Nyanyian: #L0# Meloetta mengeluarkan sinar muzik untuk menyerang mana-mana sasaran, menyebabkan #C0x3D8A99#180% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerosakan Sihir#C0x5B545B#, menggunakan <Blue Melody Fruit> untuk menjadikan Meloetta tidak kelihatan. Dalam tempoh ini, kerosakan lajur tempat anda berada akan berkurang sebanyak 15%. Ini akan berlanjutan sehingga tindakan seterusnya dalam bentuk nyanyian. Selepas memecahkan keupayaan tidak kelihatan, 20% HP anda akan dipulihkan.',
		zawakeEffectDesc_vn = '#L10# Dạng nhảy: #L0# Meloetta tấn công bất kỳ mục tiêu nào bằng chân bay, gây #C0xE69900#120% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Sát Thương Vật Lý#C0x5B54 5B#, sử dụng <Pink Melody Fruit> với xác suất ảo 100% lên mục tiêu chính (Bóng ma: hiệu ứng khống chế, buộc sử dụng đòn đánh thường để tấn công đồng minh) và sử dụng <Quả giai điệu vàng>: có 60% khả năng tạo bóng ma một đơn vị ngẫu nhiên ở hàng sau trong 1 lượt (ưu tiên mục tiêu không ở trạng thái mê hoặc hoặc ma)\n#F10# \n#F40##L10#Dạng hát: #L0# Meloetta phát ra một chùm âm nhạc để tấn công bất kỳ mục tiêu nào, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$# C0xF13B54#Spell Damage#C0x5B545B#, sử dụng <Blue Melody Fruit> để khiến Meloetta tàng hình. Trong thời gian này, sát thương mà cột bạn đang ở sẽ giảm 15%. Điều này sẽ kéo dài cho đến hành động tiếp theo dưới hình thức ca hát. Sau khi phá vỡ khả năng tàng hình, 20% HP của bạn sẽ được phục hồi.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#L10#Dance Stance:#L0#60% chance to randomly select a back-row enemy; #L10#Singing Stance:#L0#While in stealth, Meloetta’s row receives 15% damage reduction',
		zawakeSimpleDesc_en = '#L10#Dance Stance:#L0#60% chance to randomly select a back-row enemy; #L10#Singing Stance:#L0#While in stealth, Meloetta’s row receives 15% damage reduction',
		zawakeSimpleDesc_th = '#L10#ท่าร่ายรำ:#L0#โอกาส 60% เลือกศัตรูแถวหลังแบบสุ่ม; #L10#ท่าร้องเพลง:#L0#ขณะล่องหน แถวของเมโลเอตต้าจะได้รับลดความเสียหาย 15%',
		zawakeSimpleDesc_in = '#L10#Pose Menari:#L0#Peluang 60% memilih unit musuh baris belakang secara acak; #L10#Pose Bernyanyi:#L0#Saat menyamar, barisan Meloetta menerima pengurangan damage 15%',
		zawakeSimpleDesc_ph = '#L10#Dance Stance:#L0#60% chance pumili ng random back-row enemy; #L10#Singing Stance:#L0#Habang nakatago, row ni Meloetta ay makakatanggap ng 15% damage reduction',
		zawakeSimpleDesc_ma = '#L10#Gaya Menari:#L0#60% peluang pilih unit musuh barisan belakang secara rawak; #L10#Gaya Nyanyian:#L0#Semasa bersembunyi, barisan Meloetta menerima 15% pengurangan kerosakan',
		zawakeSimpleDesc_vn = '#L10#Tư thế Vũ Bộ:#L0#Xác suất chọn ngẫu nhiên một đơn vị hàng sau của đối thủ tăng lên 60%; #L10#Tư thế Ca Hát:#L0#Trong thời gian ẩn thân, hàng của Meloetta nhận giảm 15% sát thương',
