	[32613] = {
		id = 32613,
		skillName_vn = 'Hình ảnh song sinh',
		skillName_en = 'Twin image',
		skillName_th = 'ภาพฝาแฝด',
		skillName_in = 'Gambar kembar',
		skillName_ph = 'Larawan ng kambal',
		skillName_ma = 'Imej kembar',
		skillName = 'Twin image',
		describe_vn = 'Cặp song sinh Meloetta sử dụng [Trái giai điệu tím] cùng nhau để gây ra #C0x3D8A99#440% mức tấn công kép cao hơn #C0x5B545B# cho bất kỳ mục tiêu chính nào của kẻ địch (các mục tiêu khác trong hàng của chúng bị ảnh hưởng bởi #C0xE69900#200% mức tấn công kép cao hơn #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#sát thương Sát Thương Vật Lý#C0x5B545B# (chiêu đặc biệt được tung ra khi hành động ở dạng hát là sát thương phép), do đó, việc sử dụng chiêu thức đặc biệt này có 50% khả năng khiến mục tiêu trở thành bóng ma trong 1 hiệp và xác suất các bóng ma mục tiêu còn lại tăng lên 30%\n#F10# \n#F40##L10#Dance Form#L0#: 80% khiến mục tiêu chính trở thành bóng ma và xác suất tạo bóng ma cho các mục tiêu khác tăng lên 50%\n#F10# \n#F40##L10#Singing Form#L0#: Đối với các đơn vị ma hoặc bị mê hoặc, sát thương của chiêu thức đặc biệt này tăng thêm 60%',
		describe_en = 'The Meloetta twins use [Purple Melody Fruit] together to deal #C0x3D8A99#440% increased Dual Attack#C0x5B545B# damage to any primary enemy target (other targets in their row are affected by #C0xE69900#200% increased Dual Attack#C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (special move used while in singing form deals Magic Damage). This special skill has a 50% chance to turn the target into a shadow for 1 turn and increases the chance for other target shadows by 30%\n#F10# \n#F40##L10#Dance Form#L0#: 80% chance to turn the main target into a shadow and 50% increased chance to create shadows for other targets. \n#F10# \n#F40##L10#Singing Form#L0#: For ghost units or charmed enemies, this special skill’s damage increases by an additional 60%.',
		describe_th = 'ฝาแฝด Meloetta ใช้ [ผลเมโลดี้สีม่วง] ร่วมกันเพื่อสร้างความเสียหาย #C0x3D8A99#440% เพิ่มการโจมตีคู่#C0x5B545B# กับเป้าหมายหลักใดๆ ของศัตรู (เป้าหมายอื่นในแถวของพวกเขาจะได้รับผลกระทบจาก #C0xE69900#200% เพิ่มการโจมตีคู่#C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# (ท่าโจมตีพิเศษในรูปแบบการร้องเพลงจะเป็นความเสียหายเวทมนตร์) ทักษะพิเศษนี้มีโอกาส 50% ที่จะเปลี่ยนเป้าหมายเป็นเงาเป็นเวลา 1 เทิร์น และเพิ่มโอกาสการสร้างเงาของเป้าหมายอื่นขึ้น 30% \n#F10# \n#F40##L10#รูปแบบเต้น#L0#: โอกาส 80% ที่จะเปลี่ยนเป้าหมายหลักเป็นเงาและเพิ่มโอกาสสร้างเงาให้เป้าหมายอื่นขึ้น 50% \n#F10# \n#F40##L10#รูปแบบร้องเพลง#L0#: สำหรับยูนิตผีหรือศัตรูที่ถูกเสน่ห์ ความเสียหายของท่านี้จะเพิ่มขึ้นอีก 60%.',
		describe_in = 'Kembar Meloetta menggunakan [Buah Melodi Ungu] secara bersamaan untuk memberikan #C0x3D8A99#440% peningkatan Serangan Ganda#C0x5B545B# pada target utama musuh mana pun (target lain dalam baris mereka terpengaruh oleh #C0xE69900#200% peningkatan Serangan Ganda#C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Kerusakan Fisik#C0x5B545B# (serangan khusus yang dilakukan saat dalam bentuk bernyanyi adalah kerusakan sihir). Serangan khusus ini memiliki peluang 50% untuk mengubah target menjadi bayangan selama 1 giliran dan meningkatkan peluang bayangan untuk target lainnya sebesar 30% \n#F10# \n#F40##L10#Form Tari#L0#: 80% kemungkinan menjadikan target utama bayangan dan peningkatan 50% peluang untuk membuat bayangan bagi target lainnya \n#F10# \n#F40##L10#Form Bernyanyi#L0#: Untuk unit hantu atau musuh yang terpesona, kerusakan serangan khusus ini meningkat sebesar 60%.',
		describe_ph = 'Ginagamit nang sabay ang kambal na Meloetta ang [Purple Melody Fruit] para magdulot ng #C0x3D8A99#440% na pagtaas sa Dual Attack#C0x5B545B# sa sinumang pangunahing target ng kalaban (ang ibang mga target sa kanilang hanay ay naapektuhan ng #C0xE69900#200% na pagtaas sa Dual Attack#C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (ang espesyal na kasanayan na ginagamit habang nasa singing form ay nagdudulot ng magic damage). Ang espesyal na kasanayang ito ay may 50% tsansa na gawing shadow ang target sa loob ng 1 turn at pinapataas ang tsansa ng ibang target shadows ng 30% \n#F10# \n#F40##L10#Dance Form#L0#: 80% tsansa na gawing shadow ang pangunahing target at 50% na pagtaas ng tsansa na makagawa ng shadows para sa iba pang mga target. \n#F10# \n#F40##L10#Singing Form#L0#: Para sa mga ghost units o mga na-charm na kalaban, tumataas ng karagdagang 60% ang damage ng espesyal na kasanayang ito.',
		describe_ma = 'Kembar Meloetta menggunakan [Buah Melodi Ungu] bersama-sama untuk memberikan #C0x3D8A99#440% peningkatan Serangan Berganda#C0x5B545B# kepada mana-mana sasaran utama musuh (sasaran lain dalam barisan mereka terjejas oleh #C0xE69900#200% peningkatan Serangan Berganda#C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B# (serangan khas yang digunakan dalam bentuk nyanyian adalah kerosakan magik). Serangan khas ini mempunyai peluang 50% untuk menjadikan sasaran sebagai bayang selama 1 pusingan dan meningkatkan peluang bayang sasaran lain sebanyak 30% \n#F10# \n#F40##L10#Bentuk Tarian#L0#: 80% peluang menjadikan sasaran utama sebagai bayang dan peningkatan 50% peluang untuk mencipta bayang bagi sasaran lain \n#F10# \n#F40##L10#Bentuk Nyanyian#L0#: Untuk unit hantu atau musuh yang terpesona, kerosakan serangan khas ini meningkat sebanyak 60%.',
		describe = 'The Meloetta twins use [Purple Melody Fruit] together to deal #C0x3D8A99#440% increased Dual Attack#C0x5B545B# damage to any primary enemy target (other targets in their row are affected by #C0xE69900#200% increased Dual Attack#C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (special move used while in singing form deals Magic Damage). This special skill has a 50% chance to turn the target into a shadow for 1 turn and increases the chance for other target shadows by 30%\n#F10# \n#F40##L10#Dance Form#L0#: 80% chance to turn the main target into a shadow and 50% increased chance to create shadows for other targets. \n#F10# \n#F40##L10#Singing Form#L0#: For ghost units or charmed enemies, this special skill’s damage increases by an additional 60%.',
		simDesc_vn = 'Meloyeta và người bạn song sinh cùng nhau sử dụng quả nho tím, gây sát thương cho hàng mà mục tiêu chính đang ở, có khả năng quyến rũ mục tiêu.',
		simDesc_en = 'Meloyeta and her twin friend use purple grapes together, dealing damage to the row where the main target is located, with the ability to charm the target.',
		simDesc_th = 'เมโลเยต้าและเพื่อนแฝดของเธอใช้องุ่นม่วงร่วมกัน สร้างความเสียหายแก่แถวที่เป้าหมายหลักอยู่ และมีความสามารถล่อลวงเป้าหมายได้',
		simDesc_in = 'Meloyeta dan teman kembarnya menggunakan anggur ungu bersama-sama, memberikan kerusakan pada baris tempat target utama berada, dengan kemampuan untuk memikat target tersebut.',
		simDesc_ph = 'Gamit ni Meloyeta at ng kanyang kambal na kaibigan ang kulay-ubeng ubas upang makapinsala sa hanay kung saan naroroon ang pangunahing target, at may kakayahang mang-akit sa target.',
