	[32622] = {
		id = 32622,
		skillName_vn = 'Tấn công tinh thần',
		skillName_en = 'Mental attack',
		skillName_th = 'การโจมตีทางจิต',
		skillName_in = 'Serangan mental',
		skillName_ph = 'Mental na atake',
		skillName_ma = 'Serangan mental',
		skillName = 'Mental attack',
		describe_vn = '#L10# Dạng nhảy: #L0# Meloetta tấn công bất kỳ mục tiêu nào bằng chân bay, gây #C0xE69900#120% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Sát Thương Vật Lý#C0x5B54 5B#, sử dụng [Pink Melody Fruit] với xác suất ảo 100% lên mục tiêu chính (Bóng ma: hiệu ứng khống chế, buộc sử dụng đòn đánh thường để tấn công đồng minh) và sử dụng [Quả giai điệu vàng]: 40% khả năng tạo bóng ma một đơn vị ngẫu nhiên ở hàng sau trong 1 lượt (ưu tiên mục tiêu không ở trạng thái mê hoặc hoặc ma)\n#F10# \n#F40##L10#Dạng hát: #L0# Meloetta phát ra tia nhạc tấn công bất kỳ mục tiêu nào, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel* 4*48)$ của #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, sử dụng [Blue Melody Fruit] để khiến Meloetta tàng hình cho đến hành động tiếp theo trong hình thức hát. Sau khi phá vỡ khả năng tàng hình, 20% HP của cô sẽ được phục hồi.',
		describe_en = '#L10# Jump Form: #L0# Meloetta attacks any target with flying kicks, dealing #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Physical Damage#C0x5B545B#. Uses [Pink Melody Fruit] with a virtual 100% chance on the main target (Phantom: control effect forcing to use normal attacks to hit allies) and uses [Golden Melody Fruit]: 40% chance to create a phantom of a random unit in the back row for 1 turn (prioritizing targets not charmed or phantom)\n#F10# \n#F40##L10# Sing Form: #L0# Meloetta emits a musical beam attacking any target, dealing #C0x3D8A99#180% Magical Damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Magical Damage #C0x5B545B#. Uses [Blue Melody Fruit] to make Meloetta invisible until the next action in sing form. Upon breaking invisibility, 20% of her HP is restored.',
		describe_th = '#L10# รูปแบบกระโดด: #L0# Meloetta โจมตีเป้าหมายใดก็ได้ด้วยการเตะบิน ก่อให้เกิด #C0xE69900#120% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B#. ใช้ [Pink Melody Fruit] กับเป้าหมายหลักด้วยโอกาสเสมือนจริง 100% (ผี: ผลกระทบควบคุมบังคับให้ใช้การโจมตีปกติเพื่อโจมตีพันธมิตร) และใช้ [Golden Melody Fruit]: โอกาส 40% ในการสร้างผีของหน่วยสุ่มแถวหลังเป็นเวลา 1 เทิร์น (ให้ความสำคัญกับเป้าหมายที่ไม่ได้ถูกเสน่ห์หรือเป็นผี)\n#F10# \n#F40##L10# รูปแบบร้องเพลง: #L0# Meloetta ปล่อยลำแสงดนตรีโจมตีเป้าหมายใดก็ได้ ก่อให้เกิด #C0x3D8A99#180% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*48)$ ของ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B#. ใช้ [Blue Melody Fruit] ทำให้ Meloetta ล่องหนจนกว่าจะทำการต่อไปในรูปแบบร้องเพลง เมื่อเลิกซ่อนตัว จะฟื้นฟู HP 20% ของเธอ',
		describe_in = '#L10# Bentuk Lompat: #L0# Meloetta menyerang target apa saja dengan tendangan terbang, menyebabkan #C0xE69900#120% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerusakan Fisik#C0x5B545B#. Menggunakan [Pink Melody Fruit] dengan peluang virtual 100% pada target utama (Phantom: efek kontrol yang memaksa menggunakan serangan biasa untuk menyerang sekutu) dan menggunakan [Golden Melody Fruit]: 40% kemungkinan membuat hantu dari satu unit acak di barisan belakang selama 1 giliran (mendahulukan target yang tidak dalam keadaan terpesona atau hantu)\n#F10# \n#F40##L10# Bentuk Nyanyi: #L0# Meloetta memancarkan sinar musik menyerang target apa saja, menyebabkan #C0x3D8A99#180% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54# Kerusakan Magis #C0x5B545B#. Menggunakan [Blue Melody Fruit] untuk membuat Meloetta tak terlihat hingga aksi berikutnya dalam bentuk nyanyi. Setelah menghilangkan kemampuan tak terlihat, 20% HP-nya akan pulih.',
		describe_ph = '#L10# Hugis ng Lukso: #L0# Atin kinakamot Meloetta ang sinumang target gamit ang lumilipad na paa, na nagdudulot ng #C0xE69900#120% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Ginagamit ang [Pink Melody Fruit] na may 100% virtual na tsansa sa pangunahing target (Phantom: kontrol na epekto na pumipilit gamitin ang normal na atake para saktan ang mga kaalyado) at ginagamit ang [Golden Melody Fruit]: 40% posibilidad na lumikha ng phantom ng isang random na yunit sa likurang linya sa loob ng 1 turn (pinaprioritize ang mga target na hindi na-enchant o phantom)\n#F10# \n#F40##L10# Hugis ng Pag-awit: #L0# Nagpapalabas si Meloetta ng musical beam na umatake sa sinumang target, na nagdudulot ng #C0x3D8A99#180% Magical Damage#C0x5B545B#+$(skillLevel*4*48)$ ng #C0xF13B54# Magical Damage #C0x5B545B#. Ginagamit ang [Blue Melody Fruit] upang gawing invisible si Meloetta hanggang sa susunod na aksyon sa hugis ng pag-awit. Kapag naputol ang invisibility, 20% ng kanyang HP ay mababawi.',
		describe_ma = '#L10# Bentuk Lompat: #L0# Meloetta menyerang mana-mana sasaran dengan tendangan terbang, menyebabkan #C0xE69900#120% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Menggunakan [Pink Melody Fruit] dengan kebarangkalian maya 100% ke atas sasaran utama (Phantom: kesan kawalan memaksa menggunakan serangan biasa untuk menyerang sekutu) dan menggunakan [Golden Melody Fruit]: 40% peluang untuk mencipta hantu daripada satu unit rawak di barisan belakang selama 1 giliran (mengutamakan sasaran yang tidak dalam keadaan terpesona atau hantu)\n#F10# \n#F40##L10# Bentuk Nyanyian: #L0# Meloetta memancarkan sinar muzik menyerang mana-mana sasaran, menyebabkan #C0x3D8A99#180% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*48)$ daripada #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Menggunakan [Blue Melody Fruit] untuk menjadikan Meloetta hilang sehingga tindakan seterusnya dalam bentuk nyanyian. Selepas menghapuskan kebolehan hilang, 20% HPnya akan dipulihkan.',
		describe = '#L10# Jump Form: #L0# Meloetta attacks any target with flying kicks, dealing #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Physical Damage#C0x5B545B#. Uses [Pink Melody Fruit] with a virtual 100% chance on the main target (Phantom: control effect forcing to use normal attacks to hit allies) and uses [Golden Melody Fruit]: 40% chance to create a phantom of a random unit in the back row for 1 turn (prioritizing targets not charmed or phantom)\n#F10# \n#F40##L10# Sing Form: #L0# Meloetta emits a musical beam attacking any target, dealing #C0x3D8A99#180% Magical Damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Magical Damage #C0x5B545B#. Uses [Blue Melody Fruit] to make Meloetta invisible until the next action in sing form. Upon breaking invisibility, 20% of her HP is restored.',
		zawakeEffect = __data_t__zawakeEffect[32622],
		-- {79002}
		zawakeEffectDesc = '#L10# Jumping form: #L0# Meloetta attacks any target with flying kicks, dealing #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Physical Damage#C0x5B545B#, using <Pink Melody Fruit> with a 100% chance to apply to the main target (Shadow: control effect, forcing the use of normal attacks to attack allies) and using <Golden Melody Fruit>: 60% chance to create a shadow clone of a random unit in the back row for 1 turn (priority to targets not charmed or shadowed)\n#F10# \n#F40##L10#Singing form: #L0# Meloetta emits a musical beam to attack any target, dealing #C0x3D8A99#180% Spell Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Spell Damage#C0x5B545B#, using <Blue Melody Fruit> to make Meloetta invisible. During this time, the damage of the column you are in is reduced by 15%. This lasts until the next action in singing form. After breaking invisibility, 20% of your HP will be restored.',
		zawakeEffectDesc_en = '#L10# Jumping form: #L0# Meloetta attacks any target with flying kicks, dealing #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Physical Damage#C0x5B545B#, using <Pink Melody Fruit> with a 100% chance to apply to the main target (Shadow: control effect, forcing the use of normal attacks to attack allies) and using <Golden Melody Fruit>: 60% chance to create a shadow clone of a random unit in the back row for 1 turn (priority to targets not charmed or shadowed)\n#F10# \n#F40##L10#Singing form: #L0# Meloetta emits a musical beam to attack any target, dealing #C0x3D8A99#180% Spell Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Spell Damage#C0x5B545B#, using <Blue Melody Fruit> to make Meloetta invisible. During this time, the damage of the column you are in is reduced by 15%. This lasts until the next action in singing form. After breaking invisibility, 20% of your HP will be restored.',
		zawakeEffectDesc_th = '#L10# รูปแบบกระโดด: #L0# Meloetta โจมตีเป้าหมายใดก็ได้ด้วยการเตะกลางอากาศ สร้างความเสียหายทางกายภาพ #C0xE69900#120%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ใช้ <Pink Melody Fruit> ด้วยโอกาส 100% กับเป้าหมายหลัก (เงา: เอฟเฟกต์ควบคุม บังคับให้ใช้การโจมตีปกติเพื่อโจมตีเพื่อนร่วมทีม) และใช้ <Golden Melody Fruit>: มีโอกาส 60% ในการสร้างเงาของยูนิตสุ่มในแถวหลังเป็นเวลา 1 เทิร์น (ให้ความสำคัญกับเป้าหมายที่ไม่ได้ถูกสะกดจิตหรือเป็นเงา)\n#F10# \n#F40##L10#รูปแบบการร้องเพลง: #L0# Meloetta ปล่อยลำแสงดนตรีเพื่อโจมตีเป้าหมายใดก็ได้ สร้างความเสียหายเวทมนตร์ #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายทางเวทมนตร์#C0x5B545B# ใช้ <Blue Melody Fruit> เพื่อทำให้ Meloetta ล่องหน ในช่วงเวลานี้ ความเสียหายของแถวที่คุณอยู่จะลดลง 15% ผลนี้จะอยู่จนกว่าการกระทำต่อไปในรูปแบบร้องเพลง หลังจากหลุดล่องหน จะฟื้นฟู HP ของคุณ 20%.',
		zawakeEffectDesc_in = '#L10# Bentuk lompat: #L0# Meloetta menyerang target mana pun dengan tendangan terbang, menyebabkan #C0xE69900#120% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerusakan Fisik#C0x5B545B#, menggunakan <Pink Melody Fruit> dengan peluang 100% pada target utama (Bayangan: efek kontrol, memaksa menggunakan serangan biasa untuk menyerang sekutu) dan menggunakan <Golden Melody Fruit>: memiliki peluang 60% untuk membuat bayangan unit acak di barisan belakang selama 1 giliran (prioritaskan target yang tidak terpesona atau bayangan)\n#F10# \n#F40##L10# Bentuk menyanyi: #L0# Meloetta mengeluarkan sinar musik untuk menyerang target manapun, menyebabkan #C0x3D8A99#180% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerusakan Sihir#C0x5B545B#, menggunakan <Blue Melody Fruit> untuk membuat Meloetta tak terlihat. Selama waktu ini, kerusakan kolom tempat Anda berada berkurang 15%. Efek ini bertahan sampai aksi berikutnya dalam bentuk menyanyi. Setelah menghilangkan ketidaknampakan, 20% HP Anda akan pulih.',
		zawakeEffectDesc_ph = '#L10# Uri ng pagtalon: #L0# Meloetta ay umaatake sa kahit anong target gamit ang flying kick, nagdudulot ng #C0xE69900#120% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Pisikal na Pinsala#C0x5B545B#, gamit ang <Pink Melody Fruit> na may 100% tsansa sa pangunahing target (Anino: control effect, pinipilit gumamit ng ordinaryong atake para atakehin ang mga kaalyado) at gamit ang <Golden Melody Fruit>: may 60% tsansa na lumikha ng anino ng isang random unit sa likod na hanay sa loob ng 1 turn (priority sa target na hindi na-charme o may shadow)\n#F10# \n#F40##L10# Uri ng pagkanta: #L0# Meloetta ay naglalabas ng isang musika na sinag para atakehin ang kahit anong target, nagdudulot ng #C0x3D8A99#180% Spell Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Spell Damage#C0x5B545B#, gamit ang <Blue Melody Fruit> para gawing invisible si Meloetta. Sa panahong ito, bumababa ng 15% ang damage ng column kung saan ka naka-stand. Tatagal ito hanggang sa susunod na aksyon sa uri ng pagkanta. Pagkatapos masira ang invisibility, maibabalik ang 20% HP mo.',
		zawakeEffectDesc_ma = '#L10# Bentuk melompat: #L0# Meloetta menyerang mana-mana sasaran dengan tendangan terbang, menyebabkan #C0xE69900#120% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerosakan Fizikal#C0x5B545B#, menggunakan <Pink Melody Fruit> dengan kebarangkalian 100% pada sasaran utama (Bayang: kesan kawalan, memaksa menggunakan serangan biasa untuk menyerang sekutu) dan menggunakan <Golden Melody Fruit>: mempunyai kebarangkalian 60% untuk mencipta bayang satu unit rawak di barisan belakang selama 1 pusingan (utamakan sasaran yang tidak dalam keadaan terpesona atau bayang)\n#F10# \n#F40##L10# Bentuk menyanyi: #L0# Meloetta mengeluarkan pancaran muzik untuk menyerang mana-mana sasaran, menyebabkan #C0x3D8A99#180% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerosakan Sihir#C0x5B545B#, menggunakan <Blue Melody Fruit> untuk menjadikan Meloetta tidak kelihatan. Dalam tempoh ini, kerosakan lajur tempat anda berada berkurang 15%. Kesan ini berterusan sehingga tindakan seterusnya dalam bentuk menyanyi. Selepas menamatkan ketidakkelihatan, 20% HP anda akan dipulihkan.',
		zawakeEffectDesc_vn = '#L10# Dạng nhảy: #L0# Meloetta tấn công bất kỳ mục tiêu nào bằng chân bay, gây #C0xE69900#120% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Sát Thương Vật Lý#C0x5B54 5B#, sử dụng <Pink Melody Fruit> với xác suất ảo 100% lên mục tiêu chính (Bóng ma: hiệu ứng khống chế, buộc sử dụng đòn đánh thường để tấn công đồng minh) và sử dụng <Quả giai điệu vàng>: có 60% khả năng tạo bóng ma một đơn vị ngẫu nhiên ở hàng sau trong 1 lượt (ưu tiên mục tiêu không ở trạng thái mê hoặc hoặc ma)\n#F10# \n#F40##L10#Dạng hát: #L0# Meloetta phát ra một chùm âm nhạc để tấn công bất kỳ mục tiêu nào, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$# C0xF13B54#Spell Damage#C0x5B545B#, sử dụng <Blue Melody Fruit> để khiến Meloetta tàng hình. Trong thời gian này, sát thương mà cột bạn đang ở sẽ giảm 15%. Điều này sẽ kéo dài cho đến hành động tiếp theo dưới hình thức ca hát. Sau khi phá vỡ khả năng tàng hình, 20% HP của bạn sẽ được phục hồi.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#L10#Dance Stance:#L0#Chance to randomly select a back-row enemy unit increases to 60%; #L10#Singing Stance:#L0#While hidden, Meloetta’s row takes 15% less damage',
		zawakeSimpleDesc_en = '#L10#Dance Stance:#L0#Chance to randomly select a back-row enemy unit increases to 60%; #L10#Singing Stance:#L0#While hidden, Meloetta’s row takes 15% less damage',
		zawakeSimpleDesc_th = '#L10#ท่าร่ายรำ:#L0#โอกาสเลือกยูนิตศัตรูแถวหลังแบบสุ่มเพิ่มเป็น 60%; #L10#ท่าร้องเพลง:#L0#ขณะล่องหน แถวของเมโลเอตต้าได้รับการลดความเสียหาย 15%',
		zawakeSimpleDesc_in = '#L10#Gaya Menari:#L0#Peluang memilih unit musuh baris belakang secara acak meningkat menjadi 60%; #L10#Gaya Bernyanyi:#L0#Saat tersembunyi, barisan Meloetta mendapat pengurangan damage 15%',
		zawakeSimpleDesc_ph = '#L10#Tindig Sayaw:#L0#60% tsansa na random na pumili ng kalaban sa likod na hanay; #L10#Tindig Awit:#L0#Habang nakatago, ang hanay ni Meloetta ay tumatanggap ng 15% mas kaunting pinsala',
		zawakeSimpleDesc_ma = '#L10#Gaya Menari:#L0#Peluang memilih unit musuh barisan belakang secara rawak meningkat kepada 60%; #L10#Gaya Nyanyian:#L0#Semasa bersembunyi, barisan Meloetta menerima pengurangan kerosakan 15%',
		zawakeSimpleDesc_vn = '#L10#Tư thế Vũ Bộ:#L0#Xác suất chọn ngẫu nhiên một đơn vị hàng sau của đối thủ tăng lên 60%; #L10#Tư thế Ca Hát:#L0#Trong thời gian ẩn thân, hàng của Meloetta nhận giảm 15% sát thương',
