	[32623] = {
		id = 32623,
		skillName_vn = 'Hình ảnh song sinh',
		skillName_en = 'Twin image',
		skillName_th = 'ภาพฝาแฝด',
		skillName_in = 'Gambar kembar',
		skillName_ph = 'Larawan ng kambal',
		skillName_ma = 'Imej kembar',
		skillName = 'Twin image',
		describe_vn = 'Cặp song sinh Meloetta sử dụng [Trái giai điệu tím] cùng nhau để gây ra #C0x3D8A99#440% mức tấn công kép cao hơn #C0x5B545B# cho bất kỳ mục tiêu chính nào của kẻ địch (các mục tiêu khác trong hàng của chúng bị ảnh hưởng bởi #C0xE69900#200% mức tấn công kép cao hơn #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#sát thương Sát Thương Vật Lý#C0x5B545B# (chiêu đặc biệt được tung ra khi hành động ở dạng hát là sát thương phép), do đó, việc sử dụng chiêu thức đặc biệt này có 50% khả năng khiến mục tiêu trở thành bóng ma trong 1 hiệp và xác suất các bóng ma mục tiêu còn lại tăng lên 30%\n#F10# \n#F40##L10#Dance Form#L0#: 80% khiến mục tiêu chính trở thành bóng ma và xác suất tạo bóng ma cho các mục tiêu khác tăng lên 50%\n#F10# \n#F40##L10#Singing Form#L0#: Đối với các đơn vị ma hoặc bị mê hoặc, sát thương của chiêu thức đặc biệt này tăng thêm 60%',
		describe_en = 'The Meloetta twins use [Purple Melody Fruit] together to deal #C0x3D8A99#440% higher dual attack damage #C0x5B545B# to any main enemy target (other targets in their row are affected by #C0xE69900#200% higher dual attack damage #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (special move cast while in singing form is magical damage). Using this special skill has a 50% chance to turn the target into a shadow for 1 turn and increases the chance of shadows on other targets by 30%\n#F10# \n#F40##L10#Dance Form#L0#: 80% chance to turn the main target into a shadow and increases the chance of creating shadows on other targets by 50%\n#F10# \n#F40##L10#Singing Form#L0#: For ghost or charmed units, this special skill\'s damage increases by 60%.',
		describe_th = 'ฝาแฝด Meloetta ใช้ [ผลดนตรีสีม่วง] ร่วมกันเพื่อสร้างความเสียหายการโจมตีคู่สูงขึ้น #C0x3D8A99#440% #C0x5B545B# กับเป้าหมายหลักใด ๆ ของศัตรู (เป้าหมายอื่น ๆ ในแถวของพวกเขาจะได้รับผลกระทบจาก #C0xE69900#การโจมตีคู่สูงขึ้น #C0x5B545B# 200%) +$(skillLevel*4*48)$#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# (ท่าพิเศษเมื่อใช้ในรูปแบบขับร้องจะกลายเป็นความเสียหายเวทมนตร์) การใช้ท่านี้มีโอกาส 50% ที่จะเปลี่ยนเป้าหมายเป็นเงาใน 1 เทิร์น และเพิ่มโอกาสการเกิดเงาในเป้าหมายอื่น ๆ ขึ้น 30%\n#F10# \n#F40##L10#รูปแบบเต้นรำ#L0#: 80% โอกาสที่เป้าหมายหลักจะกลายเป็นเงาและเพิ่มโอกาสการสร้างเงาในเป้าหมายอื่นขึ้น 50%\n#F10# \n#F40##L10#รูปแบบขับร้อง#L0#: สำหรับหน่วยผีหรือที่ถูกเสกสาป ความเสียหายของท่าสกิลพิเศษนี้จะเพิ่มขึ้นอีก 60%',
		describe_in = 'Kembar Meloetta menggunakan [Buah Melodi Ungu] bersama-sama untuk memberikan #C0x3D8A99#440% serangan ganda lebih tinggi #C0x5B545B# kepada target utama musuh mana pun (target lain dalam baris mereka terpengaruh oleh #C0xE69900#200% serangan ganda lebih tinggi #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Kerusakan Fisik#C0x5B545B# (gerakan khusus yang dilepaskan saat dalam bentuk menyanyi adalah kerusakan magis). Menggunakan gerakan khusus ini memiliki peluang 50% untuk mengubah target menjadi bayangan selama 1 giliran dan meningkatkan peluang bayangan pada target lain sebesar 30%\n#F10# \n#F40##L10#Bentuk Tarian#L0#: 80% peluang mengubah target utama menjadi bayangan dan meningkatkan peluang pembuatan bayangan pada target lain sebesar 50%\n#F10# \n#F40##L10#Bentuk Menyanyi#L0#: Untuk unit hantu atau yang terpesona, kerusakan gerakan khusus ini meningkat sebesar 60%.',
		describe_ph = 'Gumagamit ang kambal na Meloetta ng [Purple Melody Fruit] nang magkakasama upang magdulot ng #C0x3D8A99#440% na mas mataas na dobleng atake #C0x5B545B# sa anumang pangunahing target ng kalaban (ang iba pang mga target sa kanilang hanay ay apektado ng #C0xE69900#200% na mas mataas na dobleng atake #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Pisikal na Pinsala#C0x5B545B# (ang espesyal na galaw na inilalabas kapag nasa anyo ng pagkanta ay mágical na pinsala). Ang paggamit ng espesyal na galaw na ito ay may 50% na tsansa na gawing anino ang target para sa 1 turn at pinapataas ang tsansa ng mga anino sa ibang mga target ng 30%\n#F10# \n#F40##L10#Anyong Sayaw#L0#: 80% tsansa na gawing anino ang pangunahing target at pinapataas ang tsansa ng paglikha ng mga anino sa ibang mga target ng 50%\n#F10# \n#F40##L10#Anyong Pagkanta#L0#: Para sa mga yunit na multo o naakit, tumataas ang pinsala ng espesyal na galaw na ito ng 60%.',
		describe_ma = 'Kembar Meloetta menggunakan [Buah Melodi Ungu] bersama untuk menyebabkan #C0x3D8A99#440% serangan berganda yang lebih tinggi #C0x5B545B# kepada mana-mana sasaran utama musuh (sasaran lain dalam barisan mereka terjejas oleh #C0xE69900#200% serangan berganda yang lebih tinggi #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Kerusakan Fizikal#C0x5B545B# (gerakan khas yang dilancarkan ketika dalam bentuk menyanyi adalah kerosakan magik). Menggunakan gerakan khas ini mempunyai 50% peluang untuk menjadikan sasaran sebagai bayangan dalam 1 giliran dan meningkatkan kebarangkalian bayangan pada sasaran lain sebanyak 30%\n#F10# \n#F40##L10#Bentuk Tarian#L0#: 80% kebarangkalian menjadikan sasaran utama sebagai bayangan dan meningkatkan kebarangkalian penciptaan bayangan pada sasaran lain sebanyak 50%\n#F10# \n#F40##L10#Bentuk Menyanyi#L0#: Bagi unit hantu atau yang terpesona, kerosakan gerakan khas ini meningkat sebanyak 60%.',
		describe = 'The Meloetta twins use [Purple Melody Fruit] together to deal #C0x3D8A99#440% higher dual attack damage #C0x5B545B# to any main enemy target (other targets in their row are affected by #C0xE69900#200% higher dual attack damage #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (special move cast while in singing form is magical damage). Using this special skill has a 50% chance to turn the target into a shadow for 1 turn and increases the chance of shadows on other targets by 30%\n#F10# \n#F40##L10#Dance Form#L0#: 80% chance to turn the main target into a shadow and increases the chance of creating shadows on other targets by 50%\n#F10# \n#F40##L10#Singing Form#L0#: For ghost or charmed units, this special skill\'s damage increases by 60%.',
		simDesc_vn = 'Meloyeta và người bạn song sinh cùng nhau sử dụng quả nho tím, gây sát thương cho hàng mà mục tiêu chính đang ở, có khả năng quyến rũ mục tiêu.',
		simDesc_en = 'Meloyeta and her twin use the purple grape together, dealing damage to the row where the main target is located and having the ability to charm the target.',
		simDesc_th = 'เมโลเยตาและฝาแฝดของเธอใช้ลูกองุ่นสีม่วงร่วมกัน สร้างความเสียหายแก่แถวที่เป้าหมายหลักอยู่ และมีความสามารถในการล่อลวงเป้าหมาย',
		simDesc_in = 'Meloyeta dan saudara kembarnya menggunakan anggur ungu bersama-sama, menyebabkan kerusakan pada baris tempat target utama berada, dengan kemampuan untuk memikat target.',
		simDesc_ph = 'Gamit ng Meloyeta at ng kanyang kambal ang kulay ube na ubas, nagdudulot ng pinsala sa hanay kung saan naroroon ang pangunahing target, at may kakayahang alindahin ang target.',
		simDesc_ma = 'Meloyeta dan kembarannya menggunakan anggur ungu bersama-sama, memberikan kerosakan pada baris di mana sasaran utama berada, dengan keupayaan untuk memikat sasaran.',
		simDesc = 'Meloyeta and her twin use the purple grape together, dealing damage to the row where the main target is located and having the ability to charm the target.',
		starEffect = __data_t__starEffect[32623],
		-- {11}
		starEffectDesc_vn = 'Kỹ năng đặc biệt có 100% xác suất triệu hồi thêm một anh hùng khác ngoài mục tiêu chính, tất cả các bóng ma và anh hùng bị quyến rũ của kẻ địch sẽ tấn công cùng một mục tiêu với Meloyata.',
		starEffectDesc = 'Special skill has a 100% chance to summon an additional hero besides the main target, all enemies\' ghosts and charmed heroes will attack the same target as Meloyata.',
		starEffectDesc_en = 'Special skill has a 100% chance to summon an additional hero besides the main target, all enemies\' ghosts and charmed heroes will attack the same target as Meloyata.',
		starEffectDesc_th = 'ทักษะพิเศษมีโอกาส 100% ในการเรียกฮีโร่เพิ่มอีกหนึ่งตัวนอกจากเป้าหมายหลัก ผีทั้งหมดและฮีโร่ที่ถูกล่อลวงของศัตรูจะโจมตีเป้าหมายเดียวกับ Meloyata',
		starEffectDesc_in = 'Keterampilan khusus memiliki peluang 100% untuk memanggil pahlawan lain selain dari target utama, semua hantu dan pahlawan yang terpesona dari musuh akan menyerang target yang sama dengan Meloyata.',
		starEffectDesc_ph = 'Ang espesyal na kakayahan ay may 100% na tsansa na mag-summon ng karagdagang bayani bukod sa pangunahing target, lahat ng mga multo at mga bayani na naakit ng kalaban ay sasalakay sa parehong target tulad ni Meloyata.',
		starEffectDesc_ma = 'Kemahiran khas mempunyai 100% peluang untuk memanggil wira tambahan selain sasaran utama, semua hantu dan wira yang tergoda musuh akan menyerang sasaran yang sama seperti Meloyata.',
		zawakeEffect = __data_t__zawakeEffect[32623],
		-- {79003}
		zawakeEffectDesc = 'The Meloetta twins use <Purple Melody Fruit> together to deal #C0x3D8A99#440% higher dual attack levels than #C0x5B545B# for any primary enemy target (other targets in their row are affected by #C0xE69900#200% higher dual attack levels than #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (the special skill cast when acting in singing form deals Magical Damage), thus using this special skill has a 50% chance to turn the target into a shadow for 1 turn and the probability of other target shadows increases by 30%\n#F10# \n#F40##L10#Dance Form#L0#: 100% shadow of the primary target and shadow chance of other targets increase by 50%\n#F10# \n#F40##L10#Singing Form#L0#: For ghost or charmed units, this special skill damage increases by 60% and has a 50% chance to extend the illusion effect of the illusion unit by 1 turn; dance form and singing form will deal 150% real damage of its total dual attacks to ghosts and charms.',
		zawakeEffectDesc_en = 'The Meloetta twins use <Purple Melody Fruit> together to deal #C0x3D8A99#440% higher dual attack levels than #C0x5B545B# for any primary enemy target (other targets in their row are affected by #C0xE69900#200% higher dual attack levels than #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (the special skill cast when acting in singing form deals Magical Damage), thus using this special skill has a 50% chance to turn the target into a shadow for 1 turn and the probability of other target shadows increases by 30%\n#F10# \n#F40##L10#Dance Form#L0#: 100% shadow of the primary target and shadow chance of other targets increase by 50%\n#F10# \n#F40##L10#Singing Form#L0#: For ghost or charmed units, this special skill damage increases by 60% and has a 50% chance to extend the illusion effect of the illusion unit by 1 turn; dance form and singing form will deal 150% real damage of its total dual attacks to ghosts and charms.',
		zawakeEffectDesc_th = 'แฝด Meloetta ใช้ <ผลดนตรีม่วง> ร่วมกันเพื่อสร้าง #C0x3D8A99#440% ระดับการโจมตีคู่ที่สูงกว่าของ #C0x5B545B# ให้เป้าหมายหลักของศัตรูใด ๆ (เป้าหมายอื่นในแถวของพวกเขาถูกผลกระทบโดย #C0xE69900#200% ระดับการโจมตีคู่ที่สูงกว่าของ #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# (ทักษะพิเศษที่ใช้เมื่ออยู่ในรูปแบบร้องเพลงจะก่อให้เกิดความเสียหายเวทย์มนตร์) ดังนั้นการใช้ทักษะพิเศษนี้มีโอกาส 50% ที่จะเปลี่ยนเป้าหมายให้กลายเป็นเงาเป็นเวลา 1 เทิร์นและโอกาสของเงาของเป้าหมายอื่นจะเพิ่มขึ้น 30%\n#F10# \n#F40##L10#รูปแบบเต้น#L0#: 100% เงาของเป้าหมายหลักและโอกาสเงาของเป้าหมายอื่นเพิ่มขึ้น 50%\n#F10# \n#F40##L10#รูปแบบร้องเพลง#L0#: สำหรับหน่วยปีศาจหรือหน่วยที่ถูกสะกดจิต ความเสียหายของทักษะพิเศษนี้เพิ่มขึ้น 60% และมีโอกาส 50% ที่จะขยายผลลวงของหน่วยลวงให้เพิ่มขึ้นอีก 1 เทิร์น; รูปแบบเต้นและรูปแบบร้องเพลงจะก่อให้เกิดความเสียหายจริง 150% ของการโจมตีคู่ทั้งหมดของมันต่อปีศาจและสิ่งที่ถูกสะกดจิต',
		zawakeEffectDesc_in = 'Pasangan kembar Meloetta menggunakan <Buah Melodi Ungu> bersama-sama untuk menyebabkan level serangan ganda #C0x3D8A99#440% lebih tinggi dari #C0x5B545B# untuk target utama musuh mana pun (target lain dalam barisan mereka dipengaruhi oleh level serangan ganda #C0xE69900#200% lebih tinggi dari #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Kerusakan Fisik#C0x5B545B# (kemampuan khusus yang dilemparkan saat bertindak dalam bentuk menyanyi menyebabkan Kerusakan Magis), sehingga penggunaan kemampuan khusus ini memiliki peluang 50% untuk mengubah target menjadi bayangan selama 1 giliran dan probabilitas bayangan target lainnya meningkat sebesar 30%\n#F10# \n#F40##L10#Bentuk Tarian#L0#: 100% bayangan target utama dan peluang bayangan target lain meningkat 50%\n#F10# \n#F40##L10#Bentuk Menyanyi#L0#: Untuk unit hantu atau yang terpesona, kerusakan kemampuan khusus ini meningkat 60% dan memiliki peluang 50% untuk memperpanjang efek ilusi unit ilusi selama 1 giliran; bentuk tarian dan bentuk menyanyi akan memberikan 150% kerusakan nyata dari total serangan gandanya ke unit hantu dan pesona.',
		zawakeEffectDesc_ph = 'Gumagamit ang kambal na Meloetta ng <Purple Melody Fruit> nang sabay upang magdulot ng #C0x3D8A99#440% mas mataas na antas ng dobleng atake kaysa sa #C0x5B545B# para sa anumang pangunahing target ng kalaban (ang ibang mga target sa kanilang hanay ay naapektuhan ng #C0xE69900#200% mas mataas na antas ng dobleng atake kaysa sa #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (ang espesyal na kasanayang inilalabas kapag kumikilos sa anyo ng pagkanta ay nagdudulot ng Magic Damage), kaya ang paggamit ng espesyal na kasanayang ito ay may 50% tsansa na gawing anino ang target sa loob ng 1 turn at ang posibilidad ng mga anino ng iba pang mga target ay tumataas ng 30%\n#F10# \n#F40##L10#Dance Form#L0#: 100% anino ng pangunahing target at posibilidad ng anino ng ibang mga target ay tumataas ng 50%\n#F10# \n#F40##L10#Singing Form#L0#: Para sa mga yunit ng multo o naaakit, tumataas ang pinsala ng espesyal na kasanayang ito ng 60% at may 50% tsansa na palawigin ang ilusyon ng yunit ng ilusyon ng isa pang turn; ang dance form at singing form ay magdudulot ng 150% totoong pinsala ng kabuuang dobleng atake nito sa mga yunit ng multo at nahikayat.',
		zawakeEffectDesc_ma = 'Kembar Meloetta menggunakan <Buah Melodi Ungu> bersama-sama untuk menyebabkan tahap serangan berganda #C0x3D8A99#440% lebih tinggi daripada #C0x5B545B# untuk mana-mana sasaran utama musuh (sasaran lain dalam barisan mereka terjejas oleh tahap serangan berganda #C0xE69900#200% lebih tinggi daripada #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B# (kemahiran khas digunakan ketika bertindak dalam bentuk menyanyi memberi Kerosakan Magik), oleh itu menggunakan kemahiran khas ini mempunyai 50% peluang untuk menjadikan sasaran sebagai bayang selama 1 giliran dan kemungkinan bayang sasaran lain meningkat sebanyak 30%\n#F10# \n#F40##L10#Bentuk Tarian#L0#: 100% bayang sasaran utama dan kemungkinan bayang sasaran lain meningkat 50%\n#F10# \n#F40##L10#Bentuk Menyanyi#L0#: Bagi unit hantu atau yang terpesona, kerosakan kemahiran khas ini meningkat 60% dan mempunyai 50% peluang untuk melanjutkan kesan ilusi unit ilusi selama 1 giliran; bentuk tarian dan bentuk menyanyi akan memberikan 150% kerosakan sebenar daripada jumlah serangan bergandanya kepada unit hantu dan yang terpesona.',
		zawakeEffectDesc_vn = 'Cặp song sinh Meloetta sử dụng <Trái giai điệu tím> cùng nhau để gây ra #C0x3D8A99#440% mức tấn công kép cao hơn #C0x5B545B# cho bất kỳ mục tiêu chính nào của kẻ địch (các mục tiêu khác trong hàng của chúng bị ảnh hưởng bởi #C0xE69900#200% mức tấn công kép cao hơn #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#sát thương Sát Thương Vật Lý#C0x5B545B# (chiêu đặc biệt được tung ra khi hành động ở dạng hát là Sát Thương Phép Thuật), do đó việc sử dụng chiêu thức đặc biệt này có 50% khả năng khiến mục tiêu trở thành bóng ma trong 1 hiệp và xác suất của các bóng ma mục tiêu còn lại tăng lên 30%\n#F10# \n#F40##L10#Dance Form#L0#: 100% bóng ma của mục tiêu chính và xác suất bóng ma của các mục tiêu khác tăng lên 50%\n#F10# \n#F40##L10#Singing Form#L0#: Đối với các đơn vị ma hoặc bị quyến rũ, sát thương của chiêu thức đặc biệt này tăng thêm 60% và có 50% cơ hội mở rộng hiệu ứng ảo của đơn vị ảo thêm 1 lượt; hình thức nhảy và hình thức ca hát sẽ gây ra 150% sát thương thực sự của tổng số đòn tấn công kép của chính nó lên các đơn vị ma và bùa mê.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#L10#Dance Stance:#L0#Chance to select the main target increases to 100%; #L10#Singing Stance:#L0#50% chance to extend effect duration by 1 turn',
