	[32626] = {
		id = 32626,
		skillName_vn = 'Kéo cắt hình chữ thập',
		skillName_en = 'Cross shape cut',
		skillName_th = 'ตัดเป็นรูปกากบาท',
		skillName_in = 'Potongan bentuk silang',
		skillName_ph = 'Gupitin na hugis krus',
		skillName_ma = 'Potongan bentuk salib',
		skillName = 'Cross shape cut',
		describe_vn = '#L10# Cộng sinh: #L0# Cặp song sinh của Meloetta hành động riêng biệt trong trận chiến, chia sẻ sức khỏe, cơn thịnh nộ và hiệu ứng chiến đấu. Giới hạn trên của lượng máu tăng 30%. Cơn giận tấn công của cặp song sinh hành động riêng lẻ giảm đi 30%\n#F20# \n#F40##L10# Twin Phantoms: #L0# Khi tấn công ở dạng nhảy, sử dụng [Pink Melody Fruit]: có 20% khả năng bóng ma nhắm mục tiêu ngẫu nhiên vào kẻ thù trong 1 lượt; khi tấn công ở dạng ca hát, hãy sử dụng [Quả giai điệu đỏ]: Ưu tiên cho các đơn vị tấn công bóng ma hoặc bùa mê, và các đơn vị tấn công đã bị bóng ma bỏ qua mức giảm 40% sát thương của chúng; Meloetta miễn nhiễm với các hiệu ứng ma quái và quyến rũ\n#F20# \n#F40##L10#Melody Tree: #L0# Sau khi Meloetta sử dụng trái giai điệu năm màu, cô ấy sẽ trốn trong cây giai điệu sau khi nhận sát thương chí mạng. Cây giai điệu kế thừa 100% thuộc tính của Meloetta và có #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C 0x5B545B#Lượng máu của giới hạn trên của sự sống, nếu không bị nghiền nát sau vòng đấu lớn, Meloetta sẽ hồi phục #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#Lượng máu của giới hạn trên của sinh mệnh và 500 điểm thịnh nộ sẽ xuất hiện trở lại trên chiến trường.',
		describe_en = '#L10# Symbiosis: #L0# The Meloetta twins act independently in battle, sharing health, rage, and combat effects. The upper limit of health increases by 30%. The attack rage of the twins acting separately is reduced by 30%\n#F20# \n#F40##L10# Twin Phantoms: #L0# When attacking in jump form, using [Pink Melody Fruit]: there is a 20% chance the phantom randomly targets an enemy for 1 turn; when attacking in singing form, using [Red Melody Fruit]: Priority is given to phantom or charm attacking units, and attacking units that have been ignored by the phantom receive a 40% damage reduction; Meloetta is immune to ghostly and charm effects\n#F20# \n#F40##L10# Melody Tree: #L0# After Meloetta uses the five-color melody fruit, she hides in the melody tree after receiving a critical hit. The melody tree inherits 100% of Meloetta’s attributes and has #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# of the upper limit of life health. If it is not crushed after the big round, Meloetta will recover #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# of the upper limit of life health and 500 rage points will reappear on the battlefield.',
		describe_th = '#L10# การอยู่ร่วมกัน: #L0# ฝาแฝดของ Meloetta ปฏิบัติการแยกกันในสนามรบ แบ่งปันสุขภาพ ความโกรธ และผลกระทบในการต่อสู้ ขีดจำกัดบนของพลังชีวิตเพิ่มขึ้น 30% ความโกรธจากการโจมตีของฝาแฝดที่ปฏิบัติการแยกกันลดลง 30%\n#F20# \n#F40##L10# ฝาแฝดแฟนท่อม: #L0# เมื่อโจมตีในรูปแบบกระโดด โดยใช้ [Pink Melody Fruit]: มีโอกาส 20% ที่แฟนท่อมจะสุ่มเลือกเป้าหมายเป็นศัตรูเป็นเวลา 1 เทิร์น; เมื่อโจมตีในรูปแบบร้องเพลง โดยใช้ [Red Melody Fruit]: ให้ความสำคัญกับหน่วยที่โจมตีด้วยแฟนท่อมหรือเสน่ห์ และหน่วยที่โจมตีที่ถูกแฟนท่อมมองข้ามได้รับการลดความเสียหายลง 40%; Meloetta ป้องกันผลกระทบจากผีและเสน่ห์\n#F20# \n#F40##L10# ต้นเมโลดี้: #L0# หลังจาก Meloetta ใช้ผลเมโลดี้ห้าสี เธอจะหลบในต้นเมโลดี้หลังจากได้รับความเสียหายวิกฤต ต้นเมโลดี้สืบทอดคุณสมบัติ 100% ของ Meloetta และมี #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# ของข้อจำกัดบนของพลังชีวิต ถ้าไม่ถูกทำลายหลังจากรอบใหญ่ Meloetta จะฟื้นฟู #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# ของข้อจำกัดบนของพลังชีวิต และ 500 คะแนนความโกรธจะปรากฏกลับขึ้นในสนามรบ',
		describe_in = '#L10# Simbiosis: #L0# Kembar Meloetta bertindak secara terpisah dalam pertempuran, berbagi kesehatan, kemarahan, dan efek tempur. Batas atas kesehatan meningkat 30%. Kemarahan serangan kembar yang bertindak sendiri berkurang 30%\n#F20# \n#F40##L10# Fantom Kembar: #L0# Ketika menyerang dalam bentuk lompatan, menggunakan [Pink Melody Fruit]: ada 20% kemungkinan fantom menargetkan musuh secara acak selama 1 giliran; saat menyerang dalam bentuk bernyanyi, menggunakan [Red Melody Fruit]: Prioritaskan unit penyerang fantom atau pesona, dan unit penyerang yang diabaikan oleh fantom menerima pengurangan kerusakan sebesar 40%; Meloetta kebal terhadap efek gaib dan pesona\n#F20# \n#F40##L10# Pohon Melodi: #L0# Setelah Meloetta menggunakan buah melodi lima warna, dia bersembunyi di pohon melodi setelah menerima serangan kritis. Pohon melodi mewarisi 100% atribut Meloetta dan memiliki #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# dari batas atas kesehatan hidup. Jika tidak dihancurkan setelah ronde besar, Meloetta akan pulih #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# dari batas atas kesehatan hidup dan 500 poin kemarahan akan muncul kembali di medan perang.',
		describe_ph = '#L10# Simbiosis: #L0# Ang kambal na Meloetta ay kumikilos nang hiwalay sa labanan, ibinabahagi ang kalusugan, galit, at mga epekto sa labanan. Ang pinakamataas na hangganan ng kalusugan ay tumataas ng 30%. Ang galit na pag-atake ng kambal na kumikilos nang hiwalay ay nababawasan ng 30%\n#F20# \n#F40##L10# Kambal na Phantom: #L0# Kapag umaatake sa anyong paglukso, gamit ang [Pink Melody Fruit]: may 20% na tsansang ang phantom ay random na targetin ang kalaban sa loob ng 1 turn; kapag umaatake sa anyong pagkanta, gamit ang [Red Melody Fruit]: Pinaprioritize ang mga yunit na umaatake gamit ang phantom o pang-akit, at ang mga yunit na inabandona ng phantom ay nakakakuha ng 40% bawas sa pinsala; Meloetta ay immune sa mga epekto ng multo at pang-akit\n#F20# \n#F40##L10# Puno ng Melodiya: #L0# Matapos gamitin ni Meloetta ang limang kulay na prutas ng melodiya, siya ay nagtatago sa puno ng melodiya matapos makatanggap ng kritikal na pinsala. Ang puno ng melodiya ay mana ng 100% ng mga katangian ni Meloetta at may #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# ng pinakamataas na hangganan ng kalusugan. Kung hindi ito mabuwag pagkatapos ng malaking round, mababawi ni Meloetta ang #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# ng pinakamataas na hangganan ng kalusugan at 500 puntos ng galit ang muling lalabas sa battlefield.',
		describe_ma = '#L10# Simbiosis: #L0# Kembar Meloetta bertindak secara berasingan dalam pertempuran, berkongsi kesihatan, kemarahan, dan kesan pertempuran. Had atas kesihatan meningkat sebanyak 30%. Kemarahan serangan kembar yang bertindak sendiri berkurang sebanyak 30%\n#F20# \n#F40##L10# Fantom Kembar: #L0# Apabila menyerang dalam bentuk lompat, menggunakan [Pink Melody Fruit]: terdapat 20% kemungkinan fantom menyasarkan musuh secara rawak selama 1 giliran; ketika menyerang dalam bentuk menyanyi, menggunakan [Red Melody Fruit]: Memberi keutamaan kepada unit penyerang fantom atau pesona, dan unit penyerang yang diabaikan oleh fantom menerima pengurangan kerosakan sebanyak 40%; Meloetta kebal kepada kesan hantu dan pesona\n#F20# \n#F40##L10# Pokok Melodi: #L0# Selepas Meloetta menggunakan buah melodi lima warna, dia akan bersembunyi dalam pokok melodi selepas menerima serangan kritikal. Pokok melodi mewarisi 100% atribut Meloetta dan mempunyai #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# daripada had atas kesihatan hidup. Jika tidak dihancurkan selepas pusingan besar, Meloetta akan pulih #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# daripada had atas kesihatan hidup dan 500 mata kemarahan akan muncul kembali di medan perang.',
		describe = '#L10# Symbiosis: #L0# The Meloetta twins act independently in battle, sharing health, rage, and combat effects. The upper limit of health increases by 30%. The attack rage of the twins acting separately is reduced by 30%\n#F20# \n#F40##L10# Twin Phantoms: #L0# When attacking in jump form, using [Pink Melody Fruit]: there is a 20% chance the phantom randomly targets an enemy for 1 turn; when attacking in singing form, using [Red Melody Fruit]: Priority is given to phantom or charm attacking units, and attacking units that have been ignored by the phantom receive a 40% damage reduction; Meloetta is immune to ghostly and charm effects\n#F20# \n#F40##L10# Melody Tree: #L0# After Meloetta uses the five-color melody fruit, she hides in the melody tree after receiving a critical hit. The melody tree inherits 100% of Meloetta’s attributes and has #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# of the upper limit of life health. If it is not crushed after the big round, Meloetta will recover #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# of the upper limit of life health and 500 rage points will reappear on the battlefield.',
		starEffect = __data_t__starEffect[32626],
		-- {8}
		starEffectDesc_vn = 'Sau khi đơn vị bóng ma của kẻ địch hành động, Meloyata có thể hồi phục 50% tổng chỉ số Công Vật Lý và phép của bản thân.',
		starEffectDesc = 'After the enemy\'s phantom unit takes action, Meloyata can recover 50% of her total Physical and Magical Attack stats.',
		starEffectDesc_en = 'After the enemy\'s phantom unit takes action, Meloyata can recover 50% of her total Physical and Magical Attack stats.',
		starEffectDesc_th = 'หลังจากหน่วยผีของศัตรูทำการโจมตี Meloyata สามารถฟื้นฟูพลังโจมตีทางกายภาพและเวทมนตร์ทั้งหมดได้ 50%',
		starEffectDesc_in = 'Setelah unit hantu musuh bertindak, Meloyata dapat memulihkan 50% dari total Attack Fisik dan Sihirnya.',
		starEffectDesc_ph = 'Pagkatapos kumilos ang phantom unit ng kalaban, maaaring makabawi si Meloyata ng 50% ng kanyang kabuuang Physical at Magical Attack.',
		starEffectDesc_ma = 'Selepas unit hantu musuh bertindak, Meloyata boleh memulihkan 50% daripada jumlah Serangan Fizikal dan Magiknya.',
		zawakeEffect = __data_t__zawakeEffect[32626],
		-- {79004, 1}
		zawakeEffectDesc = '#L10# Symbiosis: #L0# The twin pair of Meloetta act independently in battle, sharing health, rage, and combat effects. The upper limit of health increases by 30%. Rage attacks in the corresponding actions of the twins are reduced by 30%. After performing in dance form, the double attack of the singing form increases by 20%. After performing in singing form, the speed of the dance form increases by 15%\n#F20# \n#F40# #L10# Twin Phantoms: #L0# When attacking in dance form, using <Pink Melody Fruit>: 20% chance a random phantom targets an enemy for 1 turn; when attacking in singing form, using <Red Melody Fruit>: prioritizes phantom or charm attacking units, and attacking units ignored by phantoms reduce their damage by 40%; Meloetta is immune to phantom and charm effects\n#F20# \n#F40# #L10# Melody Tree: #L0# After Meloetta uses the five-color melody fruit, she hides in the melody tree upon receiving a critical hit. The melody tree inherits 100% of Meloetta\'s attributes and has a health limit of #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#. If in a large battle, if not crushed after the end, Meloetta will recover #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# HP and 500 rage points to reappear on the battlefield; after obtaining the four-color melody fruits other than <Purple Melody Fruit> for the first time, it immediately unleashes a special finishing move and destroys all current rage.',
		zawakeEffectDesc_en = '#L10# Symbiosis: #L0# The twin pair of Meloetta act independently in battle, sharing health, rage, and combat effects. The upper limit of health increases by 30%. Rage attacks in the corresponding actions of the twins are reduced by 30%. After performing in dance form, the double attack of the singing form increases by 20%. After performing in singing form, the speed of the dance form increases by 15%\n#F20# \n#F40# #L10# Twin Phantoms: #L0# When attacking in dance form, using <Pink Melody Fruit>: 20% chance a random phantom targets an enemy for 1 turn; when attacking in singing form, using <Red Melody Fruit>: prioritizes phantom or charm attacking units, and attacking units ignored by phantoms reduce their damage by 40%; Meloetta is immune to phantom and charm effects\n#F20# \n#F40# #L10# Melody Tree: #L0# After Meloetta uses the five-color melody fruit, she hides in the melody tree upon receiving a critical hit. The melody tree inherits 100% of Meloetta\'s attributes and has a health limit of #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#. If in a large battle, if not crushed after the end, Meloetta will recover #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# HP and 500 rage points to reappear on the battlefield; after obtaining the four-color melody fruits other than <Purple Melody Fruit> for the first time, it immediately unleashes a special finishing move and destroys all current rage.',
		zawakeEffectDesc_th = '#L10# การอยู่ร่วมกัน: #L0# คู่แฝดของ Meloetta ปฏิบัติการแยกกันในการต่อสู้ แบ่งปันสุขภาพ ความโกรธ และผลกระทบการต่อสู้ ขีดจำกัดบนของพลังชีวิตเพิ่มขึ้น 30% การโจมตีด้วยความโกรธในการกระทำที่สอดคล้องกันของฝาแฝดลดลง 30% หลังจากแสดงในรูปแบบเต้น คู่โจมตีของรูปแบบร้องเพลงเพิ่มขึ้น 20% หลังจากแสดงในรูปแบบร้องเพลง ความเร็วของรูปแบบเต้นเพิ่มขึ้น 15%\n#F20# \n#F40# #L10# ผีคู่: #L0# เมื่อโจมตีในรูปแบบเต้น โดยใช้ <ผลเมโลดี้สีชมพู>: มีโอกาส 20% ที่ผีสุ่มจะโจมตีศัตรูเป็นเวลา 1 เทิร์น เมื่อโจมตีในรูปแบบร้องเพลง โดยใช้ <ผลเมโลดี้สีแดง>: ให้ความสำคัญกับหน่วยที่โจมตีผีหรือเสน่ห์ และหน่วยโจมตีที่ถูกผีละเลยจะลดความเสียหายลง 40%; Meloetta ป้องกันผลกระทบของผีและการเสน่ห์\n#F20# \n#F40# #L10# ต้นเมโลดี้: #L0# หลังจาก Meloetta ใช้ผลเมโลดี้ห้าสี เธอจะหลบในต้นเมโลดี้หลังจากได้รับการโจมตีวิกฤติ ต้นเมโลดี้สืบทอดคุณสมบัติ 100% ของ Meloetta และมีขีดจำกัดสุขภาพ #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# หากอยู่ในการต่อสู้ใหญ่ หากไม่ถูกทำลายหลังสิ้นสุด Meloetta จะฟื้นฟู #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# HP และ 500 แต้มความโกรธเพื่อปรากฏตัวใหม่ในสนามรบ; หลังจากได้รับผลเมโลดี้สีสี่อื่นนอกจาก <ผลเมโลดี้สีม่วง> ครั้งแรก มันจะปล่อยท่าพิเศษเพื่อทำลายล้างและทำลายความโกรธทั้งหมดปัจจุบัน',
		zawakeEffectDesc_in = '#L10# Simbiosis: #L0# Pasangan kembar Meloetta bertindak secara terpisah dalam pertempuran, berbagi kesehatan, amarah, dan efek pertarungan. Batas atas kesehatan meningkat 30%. Serangan amarah dalam tindakan kembar yang sesuai berkurang 30%. Setelah menampilkan dalam bentuk tari, serangan ganda dari bentuk menyanyi meningkat sebesar 20%. Setelah menampilkan dalam bentuk menyanyi, kecepatan bentuk tari meningkat sebesar 15%\n#F20# \n#F40# #L10# Hantu Kembar: #L0# Saat menyerang dalam bentuk tari, gunakan <Buah Melodi Merah Muda>: ada 20% peluang hantu acak menargetkan musuh selama 1 giliran; saat menyerang dalam bentuk menyanyi, gunakan <Buah Melodi Merah>: memprioritaskan unit yang menyerang hantu atau pesona, dan unit yang diserang yang diabaikan hantu mengurangi kerusakan mereka sebesar 40%; Meloetta kebal terhadap efek hantu dan pesona\n#F20# \n#F40# #L10# Pohon Melodi: #L0# Setelah Meloetta menggunakan buah melodi lima warna, dia bersembunyi di pohon melodi setelah menerima serangan kritis. Pohon melodi mewarisi 100% atribut Meloetta dan memiliki batas kesehatan #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#. Jika dalam pertempuran besar, jika tidak dihancurkan setelah selesai, Meloetta akan memulihkan #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# HP dan 500 poin amarah untuk muncul kembali di medan perang; setelah mendapatkan buah melodi empat warna selain <Buah Melodi Ungu> untuk pertama kalinya, pohon itu segera melancarkan serangan khusus yang menghancurkan dan menghabisi semua amarah saat ini.',
		zawakeEffectDesc_ph = '#L10# Pagkakasama: #L0# Ang kambal na pares ni Meloetta ay kumikilos nang hiwalay sa labanan, nagbabahagi ng kalusugan, galit, at mga epekto ng laban. Ang itaas na limit ng kalusugan ay tumataas ng 30%. Ang mga atake ng galit sa mga kaukulang kilos ng kambal ay bumababa ng 30%. Pagkatapos magpakita sa anyo ng sayaw, ang dobleng atake ng anyo ng pagkanta ay tumataas ng 20%. Pagkatapos magpakita sa anyo ng pagkanta, ang bilis ng anyo ng sayaw ay tumataas ng 15%\n#F20# \n#F40# #L10# Tomas na Anino: #L0# Kapag umaatake sa anyo ng sayaw, gamit ang <Pink Melody Fruit>: may 20% na tsansa na random na anino ay tututok sa kaaway sa loob ng 1 turn; kapag umaatake sa anyo ng pagkanta, gamitin ang <Red Melody Fruit>: prayoridad ang mga yunit na umatake sa anino o alindog, at ang mga yunit na umatake na nilampasan ng mga anino ay binabawasan ang kanilang pinsala ng 40%; Si Meloetta ay immune sa mga epektong anino at alindog\n#F20# \n#F40# #L10# Puno ng Melodiya: #L0# Pagkatapos gamitin ni Meloetta ang limang kulay na prutas ng melodiya, nagtago siya sa puno ng melodiya matapos makatanggap ng kritikal na pinsala. Ang puno ng melodiya ay minana ang 100% na katangian ni Meloetta at may hangganan ng kalusugan na #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#. Kung sa isang malaking laban, kung hindi sila napabagsak pagkatapos ng pagtatapos, gagaling si Meloetta ng #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# HP at 500 puntos ng galit upang muling lumitaw sa labanan; pagkatapos makuha ang apat na kulay na prutas ng melodiya maliban sa <Purple Melody Fruit> sa unang pagkakataon, agad itong maglulunsad ng isang espesyal na pagtatapos na atake at sisira sa lahat ng kasalukuyang galit.',
		zawakeEffectDesc_ma = '#L10# Simbiosis: #L0# Pasangan kembar Meloetta bertindak secara berasingan dalam pertempuran, berkongsi kesihatan, kemarahan, dan kesan pertarungan. Had atas kesihatan meningkat sebanyak 30%. Serangan kemarahan dalam tindakan yang sepadan bagi kembar dikurangkan sebanyak 30%. Selepas melakukan dalam bentuk tarian, serangan berganda bagi bentuk nyanyian meningkat sebanyak 20%. Selepas melakukan dalam bentuk nyanyian, kelajuan bentuk tarian meningkat sebanyak 15%\n#F20# \n#F40# #L10# Hantu Kembar: #L0# Apabila menyerang dalam bentuk tarian, menggunakan <Buah Melodi Merah Jambu>: terdapat 20% kemungkinan hantu rawak mensasarkan musuh selama 1 giliran; apabila menyerang dalam bentuk nyanyian, menggunakan <Buah Melodi Merah>: mengutamakan unit menyerang hantu atau pesona, dan unit menyerang yang diabaikan hantu mengurangkan kerosakan mereka sebanyak 40%; Meloetta kebal terhadap kesan hantu dan pesona\n#F20# \n#F40# #L10# Pokok Melodi: #L0# Selepas Meloetta menggunakan buah melodi lima warna, dia bersembunyi dalam pokok melodi selepas menerima serangan kritikal. Pokok melodi mewarisi 100% atribut Meloetta dan mempunyai had kesihatan #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#. Jika dalam pertempuran besar, jika tidak dihancurkan selepas tamat, Meloetta akan pulih #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# HP dan 500 mata kemarahan untuk muncul semula di medan perang; selepas mendapatkan buah melodi empat warna selain <Buah Melodi Ungu> buat pertama kali, ia akan terus melancarkan serangan khas yang memusnahkan dan memadamkan semua kemarahan semasa.',
		zawakeEffectDesc_vn = '#L10# Cộng sinh: #L0# Cặp song sinh của Meloetta hành động riêng biệt trong trận chiến, chia sẻ sức khỏe, cơn thịnh nộ và hiệu ứng chiến đấu. Giới hạn trên của lượng máu tăng 30%. Cơn giận tấn công trong các hành động tương ứng của cặp song sinh giảm đi 30%. Sau khi diễn ở dạng nhảy, đòn tấn công kép của dạng hát tăng thêm 20%. Sau khi diễn ở dạng ca hát, tốc độ của dạng nhảy tăng thêm 15%\n#F20# \n#F40##L10# Twin Phantoms: #L0# Khi tấn công ở dạng nhảy, sử dụng <Pink Melody Fruit>: có 20% khả năng bóng ma ngẫu nhiên nhắm vào kẻ địch trong 1 lượt; khi tấn công ở dạng ca hát, hãy sử dụng <Quả giai điệu đỏ>: Ưu tiên cho các đơn vị tấn công bóng ma hoặc bùa mê, và các đơn vị tấn công đã bị bóng ma bỏ qua mức giảm 40% sát thương của chúng; Meloetta miễn nhiễm với các hiệu ứng ma quái và quyến rũ\n#F20# \n#F40##L10#Melody Tree: #L0# Sau khi Meloetta sử dụng trái giai điệu năm màu, cô ấy sẽ trốn trong cây giai điệu sau khi nhận sát thương chí mạng. Cây giai điệu kế thừa 100% thuộc tính của Meloetta và có giới hạn máu #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#. Nếu trong một hiệp đấu lớn, Nếu không bị đè bẹp sau khi kết thúc, Meloetta sẽ hồi phục #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# HP và 500 điểm thịnh nộ để xuất hiện trở lại trên chiến trường; sau khi lấy được trái giai điệu bốn màu khác ngoại trừ <Trái giai điệu tím> lần đầu tiên, nó sẽ ngay lập tức tung ra một chiêu thức tiêu diệt đặc biệt và tiêu diệt toàn bộ cơn thịnh nộ hiện tại.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'After acting in Dance Stance, increase dual attack by 20% for Singing Stance; after acting in Singing Stance, increase speed by 15% for Dance Stance; upon receiving a four-color melody orb (excluding purple) for the first time, immediately cast the Ultimate Skill once and consume all current rage',
		zawakeSimpleDesc_en = 'After acting in Dance Stance, increase dual attack by 20% for Singing Stance; after acting in Singing Stance, increase speed by 15% for Dance Stance; upon receiving a four-color melody orb (excluding purple) for the first time, immediately cast the Ultimate Skill once and consume all current rage',
		zawakeSimpleDesc_th = 'หลังจากใช้ท่าร่ายรำ เพิ่มพลังโจมตีคู่ 20% ให้กับท่าร้องเพลง; หลังจากใช้ท่าร้องเพลง เพิ่มความเร็ว 15% ให้กับท่าร่ายรำ; เมื่อได้รับลูกกลมทำนอง 4 สี (ยกเว้นสีม่วง) เป็นครั้งแรก จะใช้ท่าไม้ตายทันทีและใช้โกรธทั้งหมด',
		zawakeSimpleDesc_in = 'Setelah bertindak dalam Gaya Menari, tingkatkan serangan ganda sebesar 20% untuk Gaya Bernyanyi; setelah bertindak dalam Gaya Bernyanyi, tingkatkan kecepatan sebesar 15% untuk Gaya Menari; saat pertama kali mendapatkan bola nada empat warna (kecuali ungu), segera gunakan Ultimate dan konsumsi semua amarah',
		zawakeSimpleDesc_ph = 'Pagkatapos gumamit ng Tindig Sayaw, +20% dual attack para sa Tindig Awit; pagkatapos gumamit ng Tindig Awit, +15% speed para sa Tindig Sayaw; kapag unang nakakuha ng apat-na-kulay na melody orb (maliban sa purple), agad na gamitin ang Ultimate at ubusin lahat ng Rage',
		zawakeSimpleDesc_ma = 'Selepas bertindak dalam Gaya Menari, tambah serangan berganda sebanyak 20% untuk Gaya Nyanyian; selepas bertindak dalam Gaya Nyanyian, tambah kelajuan sebanyak 15% untuk Gaya Menari; apabila pertama kali memperoleh orbe melodi empat warna (kecuali ungu), segera guna Ultimate dan habiskan semua Kemarahan',
		zawakeSimpleDesc_vn = 'Sau khi hành động trong Tư thế Vũ Bộ, tăng 20% song công cho Tư thế Ca Hát; sau khi hành động trong Tư thế Ca Hát, tăng 15% tốc độ cho Tư thế Vũ Bộ; lần đầu nhận được quả giai điệu bốn màu (trừ quả giai điệu tím), sẽ ngay lập tức sử dụng một lần kỹ năng tối thượng và tiêu hao toàn bộ nộ khí hiện tại',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
