		zawakeSimpleDesc = '#L10#Dance Stance:#L0#Increases damage reduction for Twin Meloetta by 12%; #L10#Singing Stance:#L0#Increases bonus damage for Twin Meloetta by 12%\n#F20# \n#F40#→#L10#Dance Stance:#L0#Increases damage reduction for Twin Meloetta by 18%; #L10#Singing Stance:#L0#Increases bonus damage for Twin Meloetta by 18%',
		zawakeSimpleDesc_en = '#L10#Dance Stance:#L0#Increases damage reduction for Twin Meloetta by 12%; #L10#Singing Stance:#L0#Increases bonus damage for Twin Meloetta by 12%\n#F20# \n#F40#→#L10#Dance Stance:#L0#Increases damage reduction for Twin Meloetta by 18%; #L10#Singing Stance:#L0#Increases bonus damage for Twin Meloetta by 18%',
		zawakeSimpleDesc_th = '#L10#ท่าร่ายรำ:#L0#เพิ่มการลดความเสียหายให้เมโลเอตต้าคู่ 12%; #L10#ท่าร้องเพลง:#L0#เพิ่มความเสียหายเพิ่มเติมให้เมโลเอตต้าคู่ 12%\n#F20# \n#F40#→#L10#ท่าร่ายรำ:#L0#เพิ่มการลดความเสียหายเป็น 18%; #L10#ท่าร้องเพลง:#L0#เพิ่มความเสียหายเพิ่มเติมเป็น 18%',
		zawakeSimpleDesc_in = '#L10#Gaya Menari:#L0#Meningkatkan pengurangan damage untuk Meloetta Kembar sebesar 12%; #L10#Gaya Bernyanyi:#L0#Meningkatkan damage tambahan sebesar 12% untuk Meloetta Kembar\n#F20# \n#F40#→#L10#Gaya Menari:#L0#Meningkatkan pengurangan damage menjadi 18%; #L10#Gaya Bernyanyi:#L0#Meningkatkan damage tambahan menjadi 18%',
		zawakeSimpleDesc_ph = '#L10#Tindig Sayaw:#L0#Dagdag 12% bawas pinsala para sa Kambal na Meloetta; #L10#Tindig Awit:#L0#Dagdag 12% bonus pinsala para sa Kambal na Meloetta\n#F20# \n#F40#→#L10#Tindig Sayaw:#L0#Dagdag 18% bawas pinsala; #L10#Tindig Awit:#L0#Dagdag 18% bonus pinsala',
