	[32632] = {
		id = 32632,
		skillName_vn = 'Tấn công tinh thần',
		skillName_en = 'Mental attack',
		skillName_th = 'การโจมตีทางจิต',
		skillName_in = 'Serangan mental',
		skillName_ph = 'Mental na atake',
		skillName_ma = 'Serangan mental',
		skillName = 'Mental attack',
		describe_vn = '#L10# Dạng nhảy: #L0# Meloetta tấn công bất kỳ mục tiêu nào bằng chân bay, gây #C0xE69900#120% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Sát Thương Vật Lý#C0x5B54 5B#, sử dụng [Pink Melody Fruit] với xác suất ảo 100% lên mục tiêu chính (Bóng ma: hiệu ứng khống chế, buộc sử dụng đòn đánh thường để tấn công đồng minh) và sử dụng [Quả giai điệu vàng]: 40% khả năng tạo bóng ma một đơn vị ngẫu nhiên ở hàng sau trong 1 lượt (ưu tiên mục tiêu không ở trạng thái mê hoặc hoặc ma)\n#F10# \n#F40##L10#Dạng hát: #L0# Meloetta phát ra tia nhạc tấn công bất kỳ mục tiêu nào, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel* 4*48)$ của #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, sử dụng [Blue Melody Fruit] để khiến Meloetta tàng hình cho đến hành động tiếp theo trong hình thức hát. Sau khi phá vỡ khả năng tàng hình, 20% HP của cô sẽ được phục hồi.',
		describe_en = '#L10# Jump Form: #L0# Meloetta attacks any target with flying kicks, dealing #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Physical Damage#C0x5B545B#. Uses [Pink Melody Fruit] with a 100% virtual chance on the main target (Phantom: control effect forcing the use of normal attacks to attack allies) and uses [Golden Melody Fruit]: 40% chance to create a phantom of a random unit in the back row for 1 turn (prioritizing targets not confused or phantom). \n#F10# \n#F40# #L10# Sing Form: #L0# Meloetta emits a music beam attacking any target, dealing #C0x3D8A99#180% Magical Damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Magical Damage#C0x5B545B#. Uses [Blue Melody Fruit] making Meloetta invisible until the next action in sing form. Upon breaking invisibility, 20% of her HP is restored.',
		describe_th = '#L10# รูปแบบการกระโดด: #L0# Meloetta โจมตีเป้าหมายใดก็ได้ด้วยการเตะบิน สร้างความเสียหายทางกายภาพ #C0xE69900#120%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ใช้ [Pink Melody Fruit] กับโอกาสเสมือน 100% กับเป้าหมายหลัก (ผี: เอฟเฟกต์ควบคุม บังคับใช้การโจมตีปกติเพื่อโจมตีพันธมิตร) และใช้ [Golden Melody Fruit]: โอกาส 40% ในการสร้างผีของยูนิตสุ่มในแถวหลังเป็นเวลา 1 เทิร์น (ให้ความสำคัญกับเป้าหมายที่ไม่ได้อยู่ในสถานะหลงใหลหรือผี) \n#F10# \n#F40# #L10# รูปแบบร้องเพลง: #L0# Meloetta ปล่อยลำแสงดนตรีโจมตีเป้าหมายใดก็ได้ สร้างความเสียหายทางเวทมนตร์ #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*48)$ ของ #C0xF13B54# ความเสียหายทางเวทมนตร์#C0x5B545B# ใช้ [Blue Melody Fruit] ทำให้ Meloetta ล่องหนจนกว่าจะถึงการกระทำถัดไปในรูปแบบร้องเพลง หลังจากทำลายความล่องหน 20% ของ HP ของเธอจะได้รับการฟื้นฟู',
		describe_in = '#L10# Bentuk Melompat: #L0# Meloetta menyerang target manapun dengan tendangan terbang, memberikan #C0xE69900#120% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerusakan Fisik#C0x5B545B#. Menggunakan [Pink Melody Fruit] dengan peluang virtual 100% pada target utama (Phantom: efek kontrol memaksa menggunakan serangan biasa untuk menyerang sekutu) dan menggunakan [Golden Melody Fruit]: 40% kemungkinan menciptakan hantu dari satu unit acak di barisan belakang selama 1 giliran (memprioritaskan target yang tidak dalam keadaan bingung atau hantu) \n#F10# \n#F40# #L10# Bentuk Bernyanyi: #L0# Meloetta memancarkan sinar musik menyerang target manapun, memberikan #C0x3D8A99#180% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54# Kerusakan Magis#C0x5B545B#. Menggunakan [Blue Melody Fruit] untuk membuat Meloetta tak terlihat sampai aksi berikutnya dalam bentuk bernyanyi. Setelah kemampuan tak terlihat dihentikan, 20% HP-nya akan dipulihkan.',
		describe_ph = '#L10# Jump Form: #L0# Meloetta ayusin ang anomang target gamit ang flying kick, nagdudulot ng #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Physical Damage#C0x5B545B#. Gumagamit ng [Pink Melody Fruit] na may 100% virtual na tsansa sa pangunahing target (Phantom: control effect na pumipilit gumamit ng normal na atake para umatake sa mga kaalyado) at gumagamit ng [Golden Melody Fruit]: 40% tsansa na lumikha ng phantom ng isang random na yunit sa likurang hanay sa loob ng 1 turn (binibigyang prayoridad ang mga target na hindi nahihilo o phantom) \n#F10# \n#F40# #L10# Sing Form: #L0# Meloetta nagpapalabas ng musikang sinag na umaatake sa kahit anong target, nagdudulot ng #C0x3D8A99#180% Magical Damage#C0x5B545B#+$(skillLevel*4*48)$ ng #C0xF13B54# Magical Damage#C0x5B545B#. Gumagamit ng [Blue Melody Fruit] upang gawing invisible si Meloetta hanggang sa susunod na aksyon sa anyo ng pagkanta. Pagkatapos mabasag ang invisibility, muli niyang makukuha ang 20% ng kanyang HP.',
		describe_ma = '#L10# Bentuk Melompat: #L0# Meloetta menyerang mana-mana sasaran dengan tendangan terbang, menyebabkan #C0xE69900#120% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Menggunakan [Pink Melody Fruit] dengan kebarangkalian maya 100% ke sasaran utama (Hantu: kesan kawalan yang memaksa menggunakan serangan biasa untuk menyerang sekutu) dan menggunakan [Golden Melody Fruit]: 40% peluang mencipta hantu daripada satu unit rawak di barisan belakang selama 1 giliran (memberi keutamaan kepada sasaran yang tidak dalam keadaan terpesona atau hantu) \n#F10# \n#F40# #L10# Bentuk Menyanyi: #L0# Meloetta melepaskan pancaran muzik menyerang mana-mana sasaran, menyebabkan #C0x3D8A99#180% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*48)$ daripada #C0xF13B54# Kerosakan Sihir#C0x5B545B#. Menggunakan [Blue Melody Fruit] untuk menjadikan Meloetta tidak kelihatan sehingga tindakan berikutnya dalam bentuk menyanyi. Selepas memecahkan kebolehan tidak kelihatan, 20% HP beliau akan dipulihkan.',
		describe = '#L10# Jump Form: #L0# Meloetta attacks any target with flying kicks, dealing #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Physical Damage#C0x5B545B#. Uses [Pink Melody Fruit] with a 100% virtual chance on the main target (Phantom: control effect forcing the use of normal attacks to attack allies) and uses [Golden Melody Fruit]: 40% chance to create a phantom of a random unit in the back row for 1 turn (prioritizing targets not confused or phantom). \n#F10# \n#F40# #L10# Sing Form: #L0# Meloetta emits a music beam attacking any target, dealing #C0x3D8A99#180% Magical Damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Magical Damage#C0x5B545B#. Uses [Blue Melody Fruit] making Meloetta invisible until the next action in sing form. Upon breaking invisibility, 20% of her HP is restored.',
		zawakeEffect = __data_t__zawakeEffect[32632],
		-- {79002}
		zawakeEffectDesc = '#L10# Jump Form: #L0# Meloetta attacks any target with a flying kick, dealing #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B#, using <Pink Melody Fruit> with a 100% virtual chance on the main target (Phantom: control effect, forces normal attack to hit allies) and using <Golden Melody Fruit>: 60% chance to create a phantom of a random unit in the back row for 1 turn (prioritizing targets not charmed or ghosted)\n#F10# \n#F40##L10#Sing Form: #L0# Meloetta emits a musical beam to attack any target, dealing #C0x3D8A99#180% Spell Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Spell Damage#C0x5B545B#, using <Blue Melody Fruit> to make Meloetta invisible. During this time, damage on the column you are in is reduced by 15%. This lasts until the next action in singing form. After breaking invisibility, 20% of your HP is restored.',
		zawakeEffectDesc_en = '#L10# Jump Form: #L0# Meloetta attacks any target with a flying kick, dealing #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B#, using <Pink Melody Fruit> with a 100% virtual chance on the main target (Phantom: control effect, forces normal attack to hit allies) and using <Golden Melody Fruit>: 60% chance to create a phantom of a random unit in the back row for 1 turn (prioritizing targets not charmed or ghosted)\n#F10# \n#F40##L10#Sing Form: #L0# Meloetta emits a musical beam to attack any target, dealing #C0x3D8A99#180% Spell Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Spell Damage#C0x5B545B#, using <Blue Melody Fruit> to make Meloetta invisible. During this time, damage on the column you are in is reduced by 15%. This lasts until the next action in singing form. After breaking invisibility, 20% of your HP is restored.',
		zawakeEffectDesc_th = '#L10# รูปแบบกระโดด: #L0# Meloetta โจมตีเป้าหมายใดก็ได้ด้วยการเตะกลางอากาศ ทำความเสียหายทางกายภาพ #C0xE69900#120%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# โดยใช้ <Pink Melody Fruit> ด้วยโอกาสเสมือน 100% กับเป้าหมายหลัก (ผีเสื้อ: เอฟเฟ็กต์ควบคุม บังคับให้โจมตีปกติเพื่อโจมตีพันธมิตร) และใช้ <Golden Melody Fruit>: โอกาส 60% ในการสร้างผีเสื้อของหน่วยสุ่มในแถวหลังเป็นเวลา 1 รอบ (ให้ความสำคัญกับเป้าหมายที่ไม่อยู่ในสถานะมอมเมาหรือผี)#F10# #F40##L10# รูปแบบร้องเพลง: #L0# Meloetta ปล่อยลำแสงดนตรีเพื่อโจมตีเป้าหมายใดก็ได้ ทำความเสียหายเวทย์มนตร์ #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#ความเสียหายเวทย์มนตร์#C0x5B545B# โดยใช้ <Blue Melody Fruit> เพื่อทำให้ Meloetta ล่องหน ในช่วงเวลานี้ ความเสียหายของแถวที่คุณอยู่จะลดลง 15% ซึ่งจะคงอยู่จนกว่าจะถึงการกระทำถัดไปในรูปแบบการร้องเพลง หลังจากล่องหนถูกทำลาย HP ของคุณจะได้รับการฟื้นฟู 20%',
		zawakeEffectDesc_in = '#L10# Bentuk Melompat: #L0# Meloetta menyerang target mana pun dengan tendangan terbang, memberikan #C0xE69900#120% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Kerusakan Fisik#C0x5B545B#, menggunakan <Pink Melody Fruit> dengan peluang virtual 100% pada target utama (Phantom: efek kontrol, memaksa serangan biasa menyerang rekan) dan menggunakan <Golden Melody Fruit>: ada 60% kemungkinan menciptakan hantu dari unit acak di barisan belakang selama 1 giliran (prioritaskan target yang tidak dalam kondisi terpikat atau hantu)\n#F10# \n#F40##L10# Bentuk Bernyanyi: #L0# Meloetta mengeluarkan sinar musik untuk menyerang target mana pun, memberikan #C0x3D8A99#180% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Kerusakan Sihir#C0x5B545B#, menggunakan <Blue Melody Fruit> untuk membuat Meloetta menghilang. Selama waktu ini, kerusakan di kolom tempat kamu berada akan berkurang 15%. Ini berlangsung hingga aksi berikutnya dalam bentuk bernyanyi. Setelah menghilangkan kemampuan menghilang, 20% HP-mu akan dipulihkan.',
		zawakeEffectDesc_ph = '#L10# Jump Form: #L0# Meloetta ay lumalaban sa kahit anong target gamit ang flying kick, na nagdudulot ng #C0xE69900#120% Pisikal na Dami ng Pinsala#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Pisikal na Dami ng Pinsala#C0x5B545B#, gamit ang <Pink Melody Fruit> na may 100% virtual na posibilidad sa pangunahing target (Phantom: control effect, pinipilit gamitin ang normal attack para atakihin ang mga kakampi) at gamit ang <Golden Melody Fruit>: may 60% tsansa na gumawa ng phantom ng isang random na yunit sa back row sa loob ng 1 turn (binibigyan ng priyoridad ang mga target na hindi nahospital o multo)\n#F10# \n#F40##L10# Sing Form: #L0# Meloetta ay nagpapalabas ng isang musical beam para atakihin ang kahit anong target, na nagdudulot ng #C0x3D8A99#180% Spell Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Spell Damage#C0x5B545B#, gamit ang <Blue Melody Fruit> para maging invisible si Meloetta. Sa panahong ito, ang damage ng column na kinaroroonan mo ay bumababa ng 15%. Ito ay magtatagal hanggang sa iyong susunod na aksyon sa anyo ng pagkanta. Pagkatapos mabasag ang invisibility, 20% ng iyong HP ay magagaling.',
		zawakeEffectDesc_ma = '#L10# Bentuk Melompat: #L0# Meloetta menyerang mana-mana sasaran dengan tendangan terbang, menyebabkan #C0xE69900#120% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B#, menggunakan <Pink Melody Fruit> dengan kebarangkalian maya 100% pada sasaran utama (Hantu: kesan kawalan, memaksa serangan biasa menyerang rakan sepasukan) dan menggunakan <Golden Melody Fruit>: mempunyai 60% peluang untuk mencipta hantu unit rawak di barisan belakang selama 1 pusingan (mengutamakan sasaran yang tidak dalam keadaan terpesona atau hantu)\n#F10# \n#F40##L10# Bentuk Menyanyi: #L0# Meloetta mengeluarkan pancaran muzik untuk menyerang mana-mana sasaran, menyebabkan #C0x3D8A99#180% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Kerosakan Sihir#C0x5B545B#, menggunakan <Blue Melody Fruit> untuk menjadikan Meloetta tidak kelihatan. Dalam masa ini, kerosakan pada lajur yang anda berada akan dikurangkan sebanyak 15%. Ini berterusan sehingga tindakan seterusnya dalam bentuk menyanyi. Selepas menamatkan kebolehan tidak kelihatan, 20% HP anda akan dipulihkan.',
		zawakeEffectDesc_vn = '#L10# Dạng nhảy: #L0# Meloetta tấn công bất kỳ mục tiêu nào bằng chân bay, gây #C0xE69900#120% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Sát Thương Vật Lý#C0x5B54 5B#, sử dụng <Pink Melody Fruit> với xác suất ảo 100% lên mục tiêu chính (Bóng ma: hiệu ứng khống chế, buộc sử dụng đòn đánh thường để tấn công đồng minh) và sử dụng <Quả giai điệu vàng>: có 60% khả năng tạo bóng ma một đơn vị ngẫu nhiên ở hàng sau trong 1 lượt (ưu tiên mục tiêu không ở trạng thái mê hoặc hoặc ma)\n#F10# \n#F40##L10#Dạng hát: #L0# Meloetta phát ra một chùm âm nhạc để tấn công bất kỳ mục tiêu nào, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$# C0xF13B54#Spell Damage#C0x5B545B#, sử dụng <Blue Melody Fruit> để khiến Meloetta tàng hình. Trong thời gian này, sát thương mà cột bạn đang ở sẽ giảm 15%. Điều này sẽ kéo dài cho đến hành động tiếp theo dưới hình thức ca hát. Sau khi phá vỡ khả năng tàng hình, 20% HP của bạn sẽ được phục hồi.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#L10#Dance Stance:#L0#Chance to randomly select a back-row enemy unit increases to 60%; #L10#Singing Stance:#L0#While hidden, Meloetta’s row takes 15% less damage',
		zawakeSimpleDesc_en = '#L10#Dance Stance:#L0#Chance to randomly select a back-row enemy unit increases to 60%; #L10#Singing Stance:#L0#While hidden, Meloetta’s row takes 15% less damage',
		zawakeSimpleDesc_th = '#L10#ท่าร่ายรำ:#L0#โอกาสเลือกยูนิตศัตรูแถวหลังแบบสุ่มเพิ่มเป็น 60%; #L10#ท่าร้องเพลง:#L0#ขณะล่องหน แถวของเมโลเอตต้าได้รับการลดความเสียหาย 15%',
		zawakeSimpleDesc_in = '#L10#Gaya Menari:#L0#Peluang memilih unit musuh baris belakang secara acak meningkat menjadi 60%; #L10#Gaya Bernyanyi:#L0#Saat tersembunyi, barisan Meloetta mendapat pengurangan damage 15%',
		zawakeSimpleDesc_ph = '#L10#Tindig Sayaw:#L0#60% tsansa na random na pumili ng kalaban sa likod na hanay; #L10#Tindig Awit:#L0#Habang nakatago, ang hanay ni Meloetta ay tumatanggap ng 15% mas kaunting pinsala',
		zawakeSimpleDesc_ma = '#L10#Gaya Menari:#L0#Peluang memilih unit musuh barisan belakang secara rawak meningkat kepada 60%; #L10#Gaya Nyanyian:#L0#Semasa bersembunyi, barisan Meloetta menerima pengurangan kerosakan 15%',
		zawakeSimpleDesc_vn = '#L10#Tư thế Vũ Bộ:#L0#Xác suất chọn ngẫu nhiên một đơn vị hàng sau của đối thủ tăng lên 60%; #L10#Tư thế Ca Hát:#L0#Trong thời gian ẩn thân, hàng của Meloetta nhận giảm 15% sát thương',
