	[32633] = {
		id = 32633,
		skillName_vn = 'Hình ảnh song sinh',
		skillName_en = 'Twin image',
		skillName_th = 'ภาพฝาแฝด',
		skillName_in = 'Gambar kembar',
		skillName_ph = 'Larawan ng kambal',
		skillName_ma = 'Imej kembar',
		skillName = 'Twin image',
		describe_vn = 'Cặp song sinh Meloetta sử dụng [Trái giai điệu tím] cùng nhau để gây ra #C0x3D8A99#440% mức tấn công kép cao hơn #C0x5B545B# cho bất kỳ mục tiêu chính nào của kẻ địch (các mục tiêu khác trong hàng của chúng bị ảnh hưởng bởi #C0xE69900#200% mức tấn công kép cao hơn #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#sát thương Sát Thương Vật Lý#C0x5B545B# (chiêu đặc biệt được tung ra khi hành động ở dạng hát là sát thương phép), do đó, việc sử dụng chiêu thức đặc biệt này có 50% khả năng khiến mục tiêu trở thành bóng ma trong 1 hiệp và xác suất các bóng ma mục tiêu còn lại tăng lên 30%\n#F10# \n#F40##L10#Dance Form#L0#: 80% khiến mục tiêu chính trở thành bóng ma và xác suất tạo bóng ma cho các mục tiêu khác tăng lên 50%\n#F10# \n#F40##L10#Singing Form#L0#: Đối với các đơn vị ma hoặc bị mê hoặc, sát thương của chiêu thức đặc biệt này tăng thêm 60%',
		describe_en = 'The Meloetta twins use [Purple Melody Fruit] together to deal #C0x3D8A99#440% higher dual attack power #C0x5B545B# to any main enemy target (other targets in their row are affected by #C0xE69900#200% higher dual attack power #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (the special move cast during singing form deals magical damage), thus, using this special move has a 50% chance to turn the target into a shadow for 1 turn and increases the chance of shadows on the remaining targets by 30%\n#F10# \n#F40##L10#Dance Form#L0#: 80% chance to turn the main target into a shadow and increases shadow creation chance for other targets by 50%\n#F10# \n#F40##L10#Singing Form#L0#: For ghost or charmed units, this special move\'s damage increases by 60%',
		describe_th = 'ฝาแฝด Meloetta ใช้ [ผลไม้ทำนองม่วง] ร่วมกันเพื่อสร้างความเสียหายการโจมตีคู่สูงขึ้น #C0x3D8A99#440% #C0x5B545B# ไปยังเป้าหมายศัตรูหลักใด ๆ (เป้าหมายอื่นในแถวเดียวกันจะได้รับผลกระทบโดย #C0xE69900#200% การโจมตีคู่สูงขึ้น #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# (สกิลพิเศษที่ใช้ในรูปแบบร้องเพลงเป็นความเสียหายเวทมนตร์) ดังนั้น การใช้ทักษะพิเศษนี้มีโอกาส 50% ที่จะทำให้เป้าหมายกลายเป็นเงามืดเป็นเวลา 1 เทิร์น และเพิ่มโอกาสเงามืดในเป้าหมายที่เหลืออีก 30%\n#F10# \n#F40##L10#รูปแบบเต้น#L0#: 80% โอกาสทำให้เป้าหมายหลักกลายเป็นเงามืด และเพิ่มโอกาสสร้างเงามืดสำหรับเป้าหมายอื่นอีก 50%\n#F10# \n#F40##L10#รูปแบบร้องเพลง#L0#: สำหรับยูนิตผีหรือถูกล่อลวง ความเสียหายสกิลพิเศษนี้เพิ่มขึ้น 60%',
		describe_in = 'Kembar Meloetta menggunakan [Buah Melodi Ungu] bersama untuk menyebabkan #C0x3D8A99#440% tingkat serangan ganda lebih tinggi #C0x5B545B# ke target musuh utama mana pun (target lain dalam barisan mereka terpengaruh oleh #C0xE69900#200% tingkat serangan ganda lebih tinggi #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Kerusakan Fisik#C0x5B545B# (gerakan khusus yang diluncurkan saat dalam bentuk menyanyi memberikan kerusakan magis), oleh karena itu, penggunaan gerakan khusus ini memiliki 50% peluang untuk mengubah target menjadi bayangan selama 1 giliran dan meningkatkan peluang bayangan pada target lainnya sebesar 30%\n#F10# \n#F40##L10#Bentuk Tarian#L0#: 80% peluang untuk mengubah target utama menjadi bayangan dan meningkatkan peluang pembentukan bayangan pada target lain sebesar 50%\n#F10# \n#F40##L10#Bentuk Menyanyi#L0#: Untuk unit hantu atau yang terhipnotis, kerusakan gerakan khusus ini meningkat 60%',
		describe_ph = 'Gumagamit ang kambal na Meloetta ng [Purple Melody Fruit] nang sabay upang magdulot ng #C0x3D8A99#440% na mas mataas na dual attack power #C0x5B545B# sa anumang pangunahing target ng kalaban (ang ibang mga target sa kanilang hanay ay apektado ng #C0xE69900#200% na mas mataas na dual attack power #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (ang espesyal na galaw na inilalabas kapag nasa anyo ng pagkanta ay nagdudulot ng magic damage), kaya\'t ang paggamit ng espesyal na galaw na ito ay may 50% na posibilidad na gawing anino ang target sa loob ng 1 turn at pinapataas ang posibilidad ng mga anino sa mga natitirang target ng 30%\n#F10# \n#F40##L10#Dance Form#L0#: 80% na posibilidad na gawing anino ang pangunahing target at pinapataas ang posibilidad ng paglikha ng anino para sa ibang mga target ng 50%\n#F10# \n#F40##L10#Singing Form#L0#: Para sa mga ghost o enchanted na yunit, tumataas ng 60% ang damage ng espesyal na galaw na ito',
		describe_ma = 'Kembar Meloetta menggunakan [Buah Melodi Ungu] bersama-sama untuk menyebabkan #C0x3D8A99#440% tahap serangan berganda lebih tinggi #C0x5B545B# ke mana-mana sasaran musuh utama (sasaran lain dalam barisan mereka terjejas oleh #C0xE69900#200% tahap serangan berganda lebih tinggi #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Kerusakan Fizikal#C0x5B545B# (gerakan khas yang dilancarkan ketika dalam bentuk menyanyi ialah kerosakan magik), oleh itu, penggunaan gerakan khas ini mempunyai 50% peluang untuk menjadikan sasaran menjadi bayang selama 1 giliran dan meningkatkan peluang bayang pada sasaran lain sebanyak 30%\n#F10# \n#F40##L10#Bentuk Tarian#L0#: 80% peluang untuk menjadikan sasaran utama menjadi bayang dan meningkatkan peluang pembentukan bayang untuk sasaran lain sebanyak 50%\n#F10# \n#F40##L10#Bentuk Menyanyi#L0#: Untuk unit hantu atau yang terpesona, kerosakan gerakan khas ini meningkat 60%',
		describe = 'The Meloetta twins use [Purple Melody Fruit] together to deal #C0x3D8A99#440% higher dual attack power #C0x5B545B# to any main enemy target (other targets in their row are affected by #C0xE69900#200% higher dual attack power #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (the special move cast during singing form deals magical damage), thus, using this special move has a 50% chance to turn the target into a shadow for 1 turn and increases the chance of shadows on the remaining targets by 30%\n#F10# \n#F40##L10#Dance Form#L0#: 80% chance to turn the main target into a shadow and increases shadow creation chance for other targets by 50%\n#F10# \n#F40##L10#Singing Form#L0#: For ghost or charmed units, this special move\'s damage increases by 60%',
		simDesc_vn = 'Meloyeta và người bạn song sinh cùng nhau sử dụng quả nho tím, gây sát thương cho hàng mà mục tiêu chính đang ở, có khả năng quyến rũ mục tiêu.',
		simDesc_en = 'Meloyeta and her twin use a purple grape together to deal damage to the row where the main target is located, with a chance to charm the target.',
		simDesc_th = 'เมลอยเอตาและฝาแฝดของเธอใช้ผลองุ่นสีม่วงร่วมกันเพื่อสร้างความเสียหายให้กับแถวที่เป้าหมายหลักอยู่ พร้อมกับมีโอกาสสาปเสน่ห์เป้าหมาย',
		simDesc_in = 'Meloyeta dan kembarnya menggunakan anggur ungu bersama untuk memberikan kerusakan pada baris tempat target utama berada, dengan kemampuan untuk memikat target.',
		simDesc_ph = 'Sama-sama ginagamit ni Meloyeta at ng kanyang kambal na kapatid ang isang purple grape upang makapagdulot ng pinsala sa hilera kung saan naroroon ang pangunahing target, na may kakayahang maakit ang target.',
		simDesc_ma = 'Meloyeta dan kembarnya menggunakan anggur ungu bersama-sama untuk memberikan kerosakan pada barisan di mana sasaran utama berada, dengan keupayaan untuk memikat sasaran.',
		simDesc = 'Meloyeta and her twin use a purple grape together to deal damage to the row where the main target is located, with a chance to charm the target.',
		starEffect = __data_t__starEffect[32633],
		-- {11}
		starEffectDesc_vn = 'Kỹ năng đặc biệt có 100% xác suất triệu hồi thêm một anh hùng khác ngoài mục tiêu chính, tất cả các bóng ma và anh hùng bị quyến rũ của kẻ địch sẽ tấn công cùng một mục tiêu với Meloyata.',
		starEffectDesc = 'The special skill has a 100% chance to summon an additional hero besides the main target, all ghosts and enemy charmed heroes will attack the same target as Meloyata.',
		starEffectDesc_en = 'The special skill has a 100% chance to summon an additional hero besides the main target, all ghosts and enemy charmed heroes will attack the same target as Meloyata.',
		starEffectDesc_th = 'ทักษะพิเศษมีโอกาส 100% ในการเรียกฮีโร่อีกตัวหนึ่งนอกจากเป้าหมายหลัก ผีทั้งหมดและฮีโร่ที่ถูกล่อลวงของฝ่ายศัตรูจะโจมตีเป้าหมายเดียวกับเมโลยาเทะ',
		starEffectDesc_in = 'Skill khusus memiliki peluang 100% untuk memanggil pahlawan tambahan selain target utama, semua hantu dan pahlawan yang tergoda dari musuh akan menyerang target yang sama dengan Meloyata.',
		starEffectDesc_ph = 'Ang espesyal na kasanayan ay may 100% tsansa na mag-summon ng isa pang bayani bukod sa pangunahing target, lahat ng mga multo at mga bayaning naakit ng kaaway ay sasalakay sa parehong target kay Meloyata.',
		starEffectDesc_ma = 'Kemahiran khas mempunyai peluang 100% untuk memanggil satu wira tambahan selain sasaran utama, semua hantu dan wira yang tergoda musuh akan menyerang sasaran yang sama dengan Meloyata.',
		zawakeEffect = __data_t__zawakeEffect[32633],
		-- {79003}
		zawakeEffectDesc = 'The Meloetta twins use <Purple Melody Fruit> together to inflict #C0x3D8A99#440% higher dual attack level than #C0x5B545B# on any main target of the enemy (other targets in their row are affected by #C0xE69900#200% higher dual attack level than #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (special move launched when acting in singing form is Magical Damage), thus using this special move has a 50% chance to make the target a shadow for 1 turn and the chance of other target shadows increases by 30%\n#F10# \n#F40##L10#Dance Form#L0#: 100% shadow of the main target and the shadow chance of other targets increase by 50%\n#F10# \n#F40##L10#Singing Form#L0#: For ghost or charmed units, the damage of this special move increases by 60% and has a 50% chance to extend the illusion effect of the illusion unit by 1 turn; dance form and singing form deal 150% true damage of their total dual attack to ghost and charm units.',
		zawakeEffectDesc_en = 'The Meloetta twins use <Purple Melody Fruit> together to inflict #C0x3D8A99#440% higher dual attack level than #C0x5B545B# on any main target of the enemy (other targets in their row are affected by #C0xE69900#200% higher dual attack level than #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (special move launched when acting in singing form is Magical Damage), thus using this special move has a 50% chance to make the target a shadow for 1 turn and the chance of other target shadows increases by 30%\n#F10# \n#F40##L10#Dance Form#L0#: 100% shadow of the main target and the shadow chance of other targets increase by 50%\n#F10# \n#F40##L10#Singing Form#L0#: For ghost or charmed units, the damage of this special move increases by 60% and has a 50% chance to extend the illusion effect of the illusion unit by 1 turn; dance form and singing form deal 150% true damage of their total dual attack to ghost and charm units.',
		zawakeEffectDesc_th = 'ฝาแฝด Meloetta ใช้ <ผลดนตรีม่วง> ร่วมกันเพื่อสร้าง #C0x3D8A99#ระดับการโจมตีคู่ที่สูงกว่า 440% เมื่อเทียบกับ #C0x5B545B# กับเป้าหมายหลักใดๆ ของศัตรู (เป้าหมายอื่นในแถวเดียวกันถูกส่งผลกระทบโดย #C0xE69900#ระดับการโจมตีคู่ที่สูงกว่า 200% เมื่อเทียบกับ #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# (ท่าไม้ตายจะทำตอนอยู่ในรูปแบบการร้องเพลงเป็นความเสียหายเวทมนตร์) ดังนั้นการใช้ท่าไม้ตายนี้มีโอกาส 50% ที่จะทำให้เป้าหมายกลายเป็นเงาใน 1 เทิร์น และโอกาสเงาของเป้าหมายอื่น ๆ เพิ่มขึ้น 30%\n#F10# \n#F40##L10#รูปแบบการเต้น#L0#: เงา 100% ของเป้าหมายหลักและโอกาสเงาของเป้าหมายอื่นเพิ่มขึ้น 50%\n#F10# \n#F40##L10#รูปแบบการร้องเพลง#L0#: สำหรับยูนิตผีหรือถูกเสน่ห์ ความเสียหายของท่าไม้ตายนี้เพิ่มขึ้น 60% และมีโอกาส 50% ที่จะขยายผลลวงของยูนิตลวงเพิ่มอีก 1 เทิร์น; รูปแบบเต้นรำและรูปแบบร้องเพลงจะสร้างความเสียหายจริง 150% ของการโจมตีคู่รวมทั้งหมดของมันต่อตัวยูนิตผีและเสน่ห์',
		zawakeEffectDesc_in = 'Pasangan kembar Meloetta menggunakan <Buah Melodi Ungu> bersama-sama untuk memberikan #C0x3D8A99#tingkat serangan ganda 440% lebih tinggi dari #C0x5B545B# pada target utama musuh mana pun (target lain dalam baris mereka terpengaruh oleh #C0xE69900#tingkat serangan ganda 200% lebih tinggi dari #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Kerusakan Fisik#C0x5B545B# (gerakan khusus yang diluncurkan saat bertindak dalam bentuk bernyanyi adalah Kerusakan Magis), sehingga menggunakan gerakan khusus ini memiliki peluang 50% untuk membuat target menjadi bayangan selama 1 giliran dan peluang bayangan target lain meningkat sebesar 30%\n#F10# \n#F40##L10#Bentuk Tarian#L0#: 100% bayangan dari target utama dan peluang bayangan target lain meningkat sebesar 50%\n#F10# \n#F40##L10#Bentuk Bernyanyi#L0#: Untuk unit hantu atau yang tergoda, kerusakan gerakan khusus ini meningkat sebesar 60% dan memiliki peluang 50% untuk memperpanjang efek ilusi unit ilusi selama 1 giliran; bentuk tari dan bentuk nyanyi akan memberikan 150% kerusakan nyata dari total serangan ganda mereka ke unit hantu dan yang tergoda.',
		zawakeEffectDesc_ph = 'Magkapatid na Meloetta ay gumagamit ng <Purple Melody Fruit> nang sabay-sabay upang magdulot ng #C0x3D8A99#440% na mas mataas na antas ng dobleng atake kaysa sa #C0x5B545B# sa anumang pangunahing target ng kalaban (ang ibang mga target sa kanilang hanay ay apektado ng #C0xE69900#200% na mas mataas na antas ng dobleng atake kaysa sa #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B# (ang espesyal na galaw na inilunsad kapag kumikilos sa anyo ng pagkanta ay Magical Damage), kaya ang paggamit ng espesyal na galaw na ito ay may 50% na tsansa na gawing anino ang target sa loob ng 1 turn at ang tsansa ng mga shadow ng ibang target ay tumataas ng 30%\n#F10# \n#F40##L10#Dance Form#L0#: 100% shadow ng pangunahing target at ang tsansa ng shadow ng ibang target ay tumataas ng 50%\n#F10# \n#F40##L10#Singing Form#L0#: Para sa mga ghost o charm na yunit, ang pinsala ng espesyal na galaw na ito ay tumataas ng 60% at may 50% na tsansa na pahabain ang illusion effect ng illusion unit ng 1 turn; ang dance form at singing form ay magdudulot ng 150% na tunay na pinsala ng kanilang kabuuang dobleng atake sa ghost at charm units.',
		zawakeEffectDesc_ma = 'Pasangan kembar Meloetta menggunakan <Buah Melodi Ungu> bersama-sama untuk menyebabkan #C0x3D8A99# tahap serangan berganda 440% lebih tinggi daripada #C0x5B545B# pada mana-mana sasaran utama musuh (sasaran lain dalam barisan mereka terjejas oleh #C0xE69900# tahap serangan berganda 200% lebih tinggi daripada #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#Keradangan Fizikal#C0x5B545B# (gerakan khas yang dilancarkan semasa bertindak dalam bentuk menyanyi adalah Keradangan Magik), oleh itu menggunakan gerakan khas ini mempunyai 50% peluang untuk menjadikan sasaran menjadi bayang selama 1 giliran dan kebarangkalian bayang sasaran lain meningkat sebanyak 30%\n#F10# \n#F40##L10#Bentuk Tarian#L0#: 100% bayang sasaran utama dan kebarangkalian bayang sasaran lain meningkat sebanyak 50%\n#F10# \n#F40##L10#Bentuk Menyanyi#L0#: Untuk unit hantu atau yang terpesona, kerosakan gerakan khas ini meningkat sebanyak 60% dan mempunyai 50% peluang untuk melanjutkan kesan ilusi unit ilusi selama 1 giliran; bentuk tarian dan bentuk menyanyi akan menyebabkan 150% kerosakan sebenar dari jumlah serangan berganda mereka ke unit hantu dan terpesona.',
		zawakeEffectDesc_vn = 'Cặp song sinh Meloetta sử dụng <Trái giai điệu tím> cùng nhau để gây ra #C0x3D8A99#440% mức tấn công kép cao hơn #C0x5B545B# cho bất kỳ mục tiêu chính nào của kẻ địch (các mục tiêu khác trong hàng của chúng bị ảnh hưởng bởi #C0xE69900#200% mức tấn công kép cao hơn #C0x5B545B#) +$(skillLevel*4*48)$#C0xF13B54#sát thương Sát Thương Vật Lý#C0x5B545B# (chiêu đặc biệt được tung ra khi hành động ở dạng hát là Sát Thương Phép Thuật), do đó việc sử dụng chiêu thức đặc biệt này có 50% khả năng khiến mục tiêu trở thành bóng ma trong 1 hiệp và xác suất của các bóng ma mục tiêu còn lại tăng lên 30%\n#F10# \n#F40##L10#Dance Form#L0#: 100% bóng ma của mục tiêu chính và xác suất bóng ma của các mục tiêu khác tăng lên 50%\n#F10# \n#F40##L10#Singing Form#L0#: Đối với các đơn vị ma hoặc bị quyến rũ, sát thương của chiêu thức đặc biệt này tăng thêm 60% và có 50% cơ hội mở rộng hiệu ứng ảo của đơn vị ảo thêm 1 lượt; hình thức nhảy và hình thức ca hát sẽ gây ra 150% sát thương thực sự của tổng số đòn tấn công kép của chính nó lên các đơn vị ma và bùa mê.',
