	[32641] = {
		id = 32641,
		skillName_vn = 'Bài hát cổ xưa',
		skillName_en = 'Ancient song',
		skillName_th = 'เพลงโบราณ',
		skillName_in = 'Lagu kuno',
		skillName_ph = 'Lumang kanta',
		skillName_ma = 'Lagu kuno',
		skillName = 'Ancient song',
		describe_vn = '#L10# Dạng nhảy: #L0# Meloetta nhảy và tấn công mục tiêu địch, gây #C0xE69900#80% Sát Thương Vật Lý #C0x5B545B#+$(skillLevel*4*24)$ của #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, đồng thời tăng khả năng giảm sát thương của cặp song sinh Meloetta thêm 12%, kéo dài trong 3 round\n#F10# \n#F40##L10#Hình thức hát: #L0# Meloetta hát để tấn công bất kỳ mục tiêu kẻ thù nào, gây ra #C0x3D8A99#100% Sát Thương Phép Thuật#C0x5B545B#+ $(skillLevel*4*24)$’s #C0xF13B54# sát thương phép #C0x5B545B#, và tăng sát thương cộng thêm của Cặp song sinh Meloetta tăng 12%, kéo dài 3 hiệp',
		describe_en = '#L10# Dance Form: #L0# Meloetta dances and attacks enemy targets, dealing #C0xE69900#80% Physical Damage #C0x5B545B#+$(skillLevel*4*24)$ of #C0xF13B54# Physical Damage #C0x5B545B#, while increasing the Meloetta twins\' damage reduction by 12% for 3 rounds \n#F10# \n#F40##L10# Sing Form: #L0# Meloetta sings to attack any enemy target, dealing #C0x3D8A99#100% Magical Damage #C0x5B545B#+ $(skillLevel*4*24)$’s #C0xF13B54# magical damage #C0x5B545B#, and increasing the Meloetta Twins\' additional damage by 12%, lasting 3 turns',
		describe_th = '#L10# รูปแบบเต้น: #L0# เมลโอเอตต้าเต้นและโจมตีเป้าหมายศัตรู ก่อให้เกิด #C0xE69900#80% ความเสียหายทางกายภาพ #C0x5B545B#+$(skillLevel*4*24)$ ของ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# พร้อมกับเพิ่มความสามารถในการลดความเสียหายของเมลโอเอตต้าคู่แฝดขึ้นอีก 12% เป็นเวลา 3 เทิร์น \n#F10# \n#F40##L10# รูปแบบการร้องเพลง: #L0# เมลโอเอตต้าร้องเพลงโจมตีเป้าหมายศัตรูใด ๆ ก่อให้เกิด #C0x3D8A99#100% ความเสียหายเวทย์มนตร์ #C0x5B545B#+ $(skillLevel*4*24)$’s #C0xF13B54# ความเสียหายเวทย์มนตร์ #C0x5B545B# และเพิ่มความเสียหายเสริมของเมลโอเอตต้าคู่แฝดขึ้นอีก 12% เป็นเวลา 3 เทิร์น',
		describe_in = '#L10# Bentuk Menari: #L0# Meloetta menari dan menyerang target musuh, memberikan #C0xE69900#80% Kerusakan Fisik #C0x5B545B#+$(skillLevel*4*24)$ dari #C0xF13B54# Kerusakan Fisik #C0x5B545B#, sekaligus meningkatkan kemampuan pengurangan kerusakan Meloetta kembar sebesar 12%, berlangsung selama 3 ronde \n#F10# \n#F40##L10# Bentuk Bernyanyi: #L0# Meloetta bernyanyi untuk menyerang target musuh mana pun, memberikan #C0x3D8A99#100% Kerusakan Magis #C0x5B545B#+ $(skillLevel*4*24)$’s #C0xF13B54# kerusakan magis #C0x5B545B#, dan meningkatkan kerusakan tambahan dari Meloetta kembar sebesar 12%, berlangsung selama 3 giliran',
