	[32642] = {
		id = 32642,
		skillName_vn = 'Tấn công tinh thần',
		skillName_en = 'Mental attack',
		skillName_th = 'การโจมตีทางจิต',
		skillName_in = 'Serangan mental',
		skillName_ph = 'Mental na atake',
		skillName_ma = 'Serangan mental',
		skillName = 'Mental attack',
		describe_vn = '#L10# Dạng nhảy: #L0# Meloetta tấn công bất kỳ mục tiêu nào bằng chân bay, gây #C0xE69900#120% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Sát Thương Vật Lý#C0x5B54 5B#, sử dụng [Pink Melody Fruit] với xác suất ảo 100% lên mục tiêu chính (Bóng ma: hiệu ứng khống chế, buộc sử dụng đòn đánh thường để tấn công đồng minh) và sử dụng [Quả giai điệu vàng]: 40% khả năng tạo bóng ma một đơn vị ngẫu nhiên ở hàng sau trong 1 lượt (ưu tiên mục tiêu không ở trạng thái mê hoặc hoặc ma)\n#F10# \n#F40##L10#Dạng hát: #L0# Meloetta phát ra tia nhạc tấn công bất kỳ mục tiêu nào, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel* 4*48)$ của #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, sử dụng [Blue Melody Fruit] để khiến Meloetta tàng hình cho đến hành động tiếp theo trong hình thức hát. Sau khi phá vỡ khả năng tàng hình, 20% HP của cô sẽ được phục hồi.',
		describe_en = 'Mode Jump: Meloetta attacks any target with flying kicks, dealing 120% Physical Damage + $(skillLevel*4*48)$ Physical Damage, using [Pink Melody Fruit] with a virtual 100% chance on the main target (Phantom: control effect, forcing the use of normal attacks to hit allies) and uses [Golden Melody Fruit]: 40% chance to create a phantom of a random unit in the back row for 1 turn (prioritizing targets not under charm or phantom state). Mode Sing: Meloetta emits a music beam to attack any target, dealing 180% Magic Damage + $(skillLevel*4*48)$ Magic Damage, using [Blue Melody Fruit] to make Meloetta invisible until her next action in sing mode. After breaking invisibility, 20% of her HP will be restored.',
		describe_th = 'โหมดกระโดด: เมลอเลตต้าจะโจมตีเป้าหมายใดก็ได้ด้วยการเตะบิน สร้างความเสียหายทางกายภาพ 120% + $(skillLevel*4*48)$ ความเสียหายทางกายภาพ ใช้ [ผลเมโลดี้สีชมพู] ด้วยโอกาสเสมือน 100% กับเป้าหมายหลัก (ผี: เอฟเฟกต์ควบคุม บังคับให้ใช้การโจมตีปกติเพื่อโจมตีพันธมิตร) และใช้ [ผลเมโลดี้สีทอง]: มีโอกาส 40% ที่จะสร้างผีของยูนิตแบบสุ่มในแถวหลังเป็นเวลา 1 เทิร์น (ให้ความสำคัญกับเป้าหมายที่ไม่อยู่ในสถานะหลงใหลหรือผี) โหมดร้องเพลง: เมลอเลตต้าปล่อยลำแสงดนตรีโจมตีเป้าหมายใดก็ได้ สร้างความเสียหายเวทมนตร์ 180% + $(skillLevel*4*48)$ ความเสียหายเวทมนตร์ ใช้ [ผลเมโลดี้สีน้ำเงิน] เพื่อทำให้เมลอเลตต้าเป็นล่องหนจนกว่าจะถึงการกระทำถัดไปในโหมดร้องเพลง เมื่อเลิกสถานะล่องหนจะฟื้นฟู HP ของเธอ 20%',
		describe_in = 'Mode lompat: Meloetta menyerang target mana pun dengan tendangan terbang, memberikan 120% Damage Fisik + $(skillLevel*4*48)$ Damage Fisik, menggunakan [Buah Melodi Pink] dengan peluang virtual 100% pada target utama (Hantu: efek kontrol, memaksa menggunakan serangan normal untuk menyerang sekutu) dan menggunakan [Buah Melodi Emas]: 40% kemungkinan membuat hantu dari satu unit acak di barisan belakang selama 1 giliran (memprioritaskan target yang tidak dalam keadaan terpesona atau hantu). Mode bernyanyi: Meloetta memancarkan sinar musik menyerang target mana pun, memberikan 180% Damage Magis + $(skillLevel*4*48)$ Damage Magis, menggunakan [Buah Melodi Biru] untuk membuat Meloetta menjadi tak terlihat hingga tindakan berikutnya dalam mode bernyanyi. Setelah menghilangkan kemampuan tak terlihat tersebut, 20% HP-nya akan dipulihkan.',
		describe_ph = 'Mode Jump: Meloetta ayusin ang kahit anong target gamit ang flying kick, na nagdudulot ng 120% Physical Damage + $(skillLevel*4*48)$ Physical Damage, gamit ang [Pink Melody Fruit] na may virtual 100% chance sa pangunahing target (Phantom: control effect, pinipilit gumamit ng normal na atake para atakihin ang mga kaalyado) at ginagamit ang [Golden Melody Fruit]: 40% tsansa na gumawa ng phantom ng isang random na yunit sa likod sa loob ng 1 turn (binibigyang prayoridad ang mga target na hindi na-curse o phantom). Mode Sing: Meloetta nagpapalabas ng music beam para atakihin ang kahit anong target, na nagdudulot ng 180% Magic Damage + $(skillLevel*4*48)$ Magic Damage, gamit ang [Blue Melody Fruit] para maging invisible si Meloetta hanggang sa susunod niyang aksyon sa sing mode. Pagkatapos masira ang invisibility, mare-recover ang 20% ng kanyang HP.',
		describe_ma = 'Mod Lompat: Meloetta menyerang mana-mana sasaran dengan tendangan terbang, memberikan 120% Kerosakan Fizikal + $(skillLevel*4*48)$ Kerosakan Fizikal, menggunakan [Buah Melodi Merah Jambu] dengan kebarangkalian maya 100% ke atas sasaran utama (Hantu: kesan kawalan, memaksa menggunakan serangan biasa untuk menyerang sekutu) dan menggunakan [Buah Melodi Emas]: 40% kemungkinan mencipta hantu unit rawak di barisan belakang selama 1 pusingan (mengutamakan sasaran yang tidak berada dalam keadaan terpesona atau hantu). Mod Nyanyian: Meloetta memancarkan pancaran muzik menyerang mana-mana sasaran, memberikan 180% Kerosakan Sihir + $(skillLevel*4*48)$ Kerosakan Sihir, menggunakan [Buah Melodi Biru] untuk membuat Meloetta hilang sehingga tindakan seterusnya dalam mod nyanyian. Selepas menamatkan keupayaan hilang itu, 20% HPnya akan dipulihkan.',
		describe = 'Mode Jump: Meloetta attacks any target with flying kicks, dealing 120% Physical Damage + $(skillLevel*4*48)$ Physical Damage, using [Pink Melody Fruit] with a virtual 100% chance on the main target (Phantom: control effect, forcing the use of normal attacks to hit allies) and uses [Golden Melody Fruit]: 40% chance to create a phantom of a random unit in the back row for 1 turn (prioritizing targets not under charm or phantom state). Mode Sing: Meloetta emits a music beam to attack any target, dealing 180% Magic Damage + $(skillLevel*4*48)$ Magic Damage, using [Blue Melody Fruit] to make Meloetta invisible until her next action in sing mode. After breaking invisibility, 20% of her HP will be restored.',
		zawakeEffect = __data_t__zawakeEffect[32642],
		-- {79002}
		zawakeEffectDesc = '#L10# Jump Form: #L0# Meloetta attacks any target with flying kicks, dealing #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B#, using <Pink Melody Fruit> with a 100% fake probability on the main target (Phantom: control effect, forces the use of normal attacks to attack allies) and uses <Golden Melody Fruit>: 60% chance to create a phantom of a random unit in the back row for 1 turn (prioritizing targets not under charm or phantom status)\n#F10# \n#F40##L10#Singing Form: #L0# Meloetta emits a music beam to attack any target, dealing #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Spell Damage#C0x5B545B#, using <Blue Melody Fruit> to make Meloetta invisible. During this time, damage taken by the column Meloetta is in is reduced by 15%. This lasts until the next action in singing form. After breaking invisibility, 20% of your HP is restored.',
		zawakeEffectDesc_en = '#L10# Jump Form: #L0# Meloetta attacks any target with flying kicks, dealing #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B#, using <Pink Melody Fruit> with a 100% fake probability on the main target (Phantom: control effect, forces the use of normal attacks to attack allies) and uses <Golden Melody Fruit>: 60% chance to create a phantom of a random unit in the back row for 1 turn (prioritizing targets not under charm or phantom status)\n#F10# \n#F40##L10#Singing Form: #L0# Meloetta emits a music beam to attack any target, dealing #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Spell Damage#C0x5B545B#, using <Blue Melody Fruit> to make Meloetta invisible. During this time, damage taken by the column Meloetta is in is reduced by 15%. This lasts until the next action in singing form. After breaking invisibility, 20% of your HP is restored.',
		zawakeEffectDesc_th = '#L10# รูปแบบกระโดด: #L0# Meloetta โจมตีเป้าหมายใดก็ได้ด้วยการเตะบิน สร้างความเสียหายทางกายภาพ #C0xE69900#120%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ใช้ <Pink Melody Fruit> ด้วยโอกาสปลอม 100% กับเป้าหมายหลัก (ผี: เอฟเฟกต์ควบคุม บังคับให้ใช้การโจมตีปกติเพื่อโจมตีเพื่อนร่วมทีม) และใช้ <Golden Melody Fruit>: มีโอกาส 60% ที่จะสร้างผีของยูนิตสุ่มในแถวหลังเป็นเวลา 1 เทิร์น (จัดลำดับเป้าหมายที่ไม่ได้อยู่ในสถานะหลงใหลหรือผี) \n#F10# \n#F40##L10# รูปแบบร้องเพลง: #L0# Meloetta ปล่อยลำแสงดนตรีเพื่อโจมตีเป้าหมายใดก็ได้ สร้างความเสียหายเวทมนตร์ #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#ความเสียหายจากเวทมนตร์#C0x5B545B# ใช้ <Blue Melody Fruit> เพื่อทำให้ Meloetta ซ่อนตัว ในช่วงนี้ ความเสียหายที่คอลัมน์ที่ Meloetta อยู่ถูกลดลง 15% ระยะเวลาจะคงอยู่จนกว่าการกระทำครั้งถัดไปในรูปแบบร้องเพลง หลังจากสลายการซ่อนไม่เห็น ตัว จะฟื้นฟู HP ของคุณ 20%.',
		zawakeEffectDesc_in = '#L10# Bentuk Melompat: #L0# Meloetta menyerang target mana pun dengan tendangan terbang, memberikan #C0xE69900#120% Damage Fisik#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Damage Fisik#C0x5B545B#, menggunakan <Pink Melody Fruit> dengan peluang palsu 100% pada target utama (Phantom: efek kontrol, memaksa menggunakan serangan biasa untuk menyerang sekutu) dan menggunakan <Golden Melody Fruit>: ada peluang 60% untuk membuat phantom unit acak di baris belakang selama 1 giliran (memprioritaskan target yang tidak dalam status terpikat atau phantom) \n#F10# \n#F40##L10# Bentuk Bernyanyi: #L0# Meloetta mengeluarkan sinar musik untuk menyerang target mana pun, memberikan #C0x3D8A99#180% Damage Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Damage Spell#C0x5B545B#, menggunakan <Blue Melody Fruit> untuk membuat Meloetta tak terlihat. Selama waktu ini, kerusakan yang diterima oleh kolom tempat Meloetta berada berkurang 15%. Efek ini bertahan hingga tindakan berikutnya dalam bentuk bernyanyi. Setelah menghilangkan kemampuan tak terlihat, 20% HP Anda akan dipulihkan.',
		zawakeEffectDesc_ph = '#L10# Jump Form: #L0# Meloetta ay sumusugod sa kahit anong target gamit ang lumilipad na sipa, na nagdudulot ng #C0xE69900#120% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B#, gumagamit ng <Pink Melody Fruit> na may 100% pekeng pagkakataon sa pangunahing target (Phantom: control effect, pinipilit gumamit ng normal na atake para atakihin ang kakampi) at gumagamit ng <Golden Melody Fruit>: may 60% na pagkakataon na lumikha ng phantom ng isang random na yunit sa likod na hilera sa loob ng 1 turn (pinaprayoridad ang mga target na hindi naactively naibibitin o phantom) \n#F10# \n#F40##L10# Singing Form: #L0# Meloetta ay nagpapalabas ng isang sinag ng musika para atakihin ang kahit anong target, na nagdudulot ng #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Spell Damage#C0x5B545B#, gumagamit ng <Blue Melody Fruit> para gawing invisible si Meloetta. Sa panahong ito, nababawasan ng 15% ang damage sa column na kinaroroonan ng Meloetta. Ito ay tatagal hanggang sa susunod na kilos sa anyong pagkanta. Pagkatapos mabali ang invisibility, nakakabawi ka ng 20% HP.',
		zawakeEffectDesc_ma = '#L10# Bentuk Melompat: #L0# Meloetta menyerang mana-mana sasaran dengan tendangan terbang, memberi #C0xE69900#120% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B#, menggunakan <Pink Melody Fruit> dengan kebarangkalian palsu 100% pada sasaran utama (Phantom: kesan kawalan, memaksa menggunakan serangan biasa untuk menyerang sekutu) dan menggunakan <Golden Melody Fruit>: ada kebarangkalian 60% untuk menghasilkan phantom unit rawak di barisan belakang selama 1 pusingan (mengutamakan sasaran yang tidak berada dalam keadaan terpikat atau phantom) \n#F10# \n#F40##L10# Bentuk Menyanyi: #L0# Meloetta mengeluarkan sinaran muzik untuk menyerang mana-mana sasaran, memberi #C0x3D8A99#180% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Kerosakan Sihir#C0x5B545B#, menggunakan <Blue Melody Fruit> untuk menjadikan Meloetta tidak kelihatan. Dalam tempoh ini, kerosakan yang dialami oleh lajur tempat Meloetta berada dikurangkan sebanyak 15%. Ini akan berlanjutan sehingga tindakan seterusnya dalam bentuk menyanyi. Selepas membuka kebolehan tidak kelihatan, 20% HP anda akan dipulihkan.',
		zawakeEffectDesc_vn = '#L10# Dạng nhảy: #L0# Meloetta tấn công bất kỳ mục tiêu nào bằng chân bay, gây #C0xE69900#120% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Sát Thương Vật Lý#C0x5B54 5B#, sử dụng <Pink Melody Fruit> với xác suất ảo 100% lên mục tiêu chính (Bóng ma: hiệu ứng khống chế, buộc sử dụng đòn đánh thường để tấn công đồng minh) và sử dụng <Quả giai điệu vàng>: có 60% khả năng tạo bóng ma một đơn vị ngẫu nhiên ở hàng sau trong 1 lượt (ưu tiên mục tiêu không ở trạng thái mê hoặc hoặc ma)\n#F10# \n#F40##L10#Dạng hát: #L0# Meloetta phát ra một chùm âm nhạc để tấn công bất kỳ mục tiêu nào, gây ra #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$# C0xF13B54#Spell Damage#C0x5B545B#, sử dụng <Blue Melody Fruit> để khiến Meloetta tàng hình. Trong thời gian này, sát thương mà cột bạn đang ở sẽ giảm 15%. Điều này sẽ kéo dài cho đến hành động tiếp theo dưới hình thức ca hát. Sau khi phá vỡ khả năng tàng hình, 20% HP của bạn sẽ được phục hồi.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#L10#Tư thế Vũ Bộ:#L0#Xác suất chọn ngẫu nhiên một đơn vị hàng sau của đối thủ tăng lên 60%; #L10#Tư thế Ca Hát:#L0#Trong thời gian ẩn thân, hàng của Meloetta nhận giảm 15% sát thương',
		zawakeSimpleDesc_en = '#L10#Tư thế Vũ Bộ:#L0#Xác suất chọn ngẫu nhiên một đơn vị hàng sau của đối thủ tăng lên 60%; #L10#Tư thế Ca Hát:#L0#Trong thời gian ẩn thân, hàng của Meloetta nhận giảm 15% sát thương',
