	[32646] = {
		id = 32646,
		skillName_vn = 'Kéo cắt hình chữ thập',
		skillName_en = 'Cross-shaped cutter',
		skillName_th = 'ตัดรูปทรงกากบาท',
		skillName_in = 'Pemotong berbentuk silang',
		skillName_ph = 'Panukat na hugis krus',
		skillName_ma = 'Pemotong berbentuk silang',
		skillName = 'Cross-shaped cutter',
		describe_vn = '#L10# Cộng sinh: #L0# Cặp song sinh của Meloetta hành động riêng biệt trong trận chiến, chia sẻ sức khỏe, cơn thịnh nộ và hiệu ứng chiến đấu. Giới hạn trên của lượng máu tăng 30%. Cơn giận tấn công của cặp song sinh hành động riêng lẻ giảm đi 30%\n#F20# \n#F40##L10# Twin Phantoms: #L0# Khi tấn công ở dạng nhảy, sử dụng [Pink Melody Fruit]: có 20% khả năng bóng ma nhắm mục tiêu ngẫu nhiên vào kẻ thù trong 1 lượt; khi tấn công ở dạng ca hát, hãy sử dụng [Quả giai điệu đỏ]: Ưu tiên cho các đơn vị tấn công bóng ma hoặc bùa mê, và các đơn vị tấn công đã bị bóng ma bỏ qua mức giảm 40% sát thương của chúng; Meloetta miễn nhiễm với các hiệu ứng ma quái và quyến rũ\n#F20# \n#F40##L10#Melody Tree: #L0# Sau khi Meloetta sử dụng trái giai điệu năm màu, cô ấy sẽ trốn trong cây giai điệu sau khi nhận sát thương chí mạng. Cây giai điệu kế thừa 100% thuộc tính của Meloetta và có #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C 0x5B545B#Lượng máu của giới hạn trên của sự sống, nếu không bị nghiền nát sau vòng đấu lớn, Meloetta sẽ hồi phục #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#Lượng máu của giới hạn trên của sinh mệnh và 500 điểm thịnh nộ sẽ xuất hiện trở lại trên chiến trường.',
		describe_en = '#L10# Symbiosis: #L0# Meloetta\'s twin acts separately in battle, sharing health, rage, and combat effects. The upper limit of health increases by 30%. The twin\'s individual attack rage decreases by 30%\n#F20# \n#F40##L10# Twin Phantoms: #L0# When attacking in jump form, using [Pink Melody Fruit]: there is a 20% chance that a phantom will randomly target an enemy for 1 turn; when attacking in singing form, using [Red Melody Fruit]: prioritize phantom or charm-attacking units, and units attacked by phantoms ignore 40% of the damage reduction; Meloetta is immune to ghostly and charm effects\n#F20# \n#F40##L10# Melody Tree: #L0# After Meloetta uses the five-color melody fruit, she hides inside the melody tree after receiving a critical hit. The melody tree inherits 100% of Meloetta\'s attributes and has #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# of the upper health limit. If not destroyed after the major round, Meloetta recovers #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# of the upper health limit and 500 rage points reappear on the battlefield.',
		describe_th = '#L10# การอยู่ร่วมกัน: #L0# ฝาแฝดของเมลอเอตต้าทำงานแยกกันในการต่อสู้ แบ่งปันสุขภาพ ความโกรธ และผลการต่อสู้ ขีดจำกัดบนของพลังชีวิตเพิ่มขึ้น 30% ความโกรธของการโจมตีจากแฝดที่ทำงานแยกกันลดลง 30%\n#F20# \n#F40##L10# ผีคู่: #L0# เมื่อโจมตีในรูปแบบกระโดด โดยใช้ [ผลไม้ทำนองชมพู]: มีโอกาส 20% ที่ผีจะสุ่มเป้าหมายศัตรูเป็นเวลา 1 เทิร์น; เมื่อโจมตีในรูปแบบขับร้อง โดยใช้ [ผลไม้ทำนองแดง]: ให้ความสำคัญกับหน่วยโจมตีผีหรือเสน่ห์ และหน่วยที่ถูกโจมตีโดยผีจะละเลยการลดความเสียหาย 40%; เมลอเอตต้าได้รับภูมิคุ้มกันต่อผลกระทบผีและเสน่ห์\n#F20# \n#F40##L10# ต้นเสียง: #L0# หลังจากเมลอเอตต้าใช้ผลไม้ทำนองห้าสี เธอจะหลบซ่อนในต้นเสียงหลังจากได้รับความเสียหายวิกฤต ต้นเสียงสืบทอดคุณสมบัติของเมลอเอตต้า 100% และมี #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# ของขีดจำกัดบนของพลังชีวิต หากไม่ถูกทำลายหลังจบรอบใหญ่ เมลอเอตต้าจะฟื้นฟู #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# ของขีดจำกัดบนของพลังชีวิต และ 500 แต้มความโกรธจะปรากฏอีกครั้งบนสนามรบ.',
		describe_in = '#L10# Simbiosis: #L0# Kembaran Meloetta bertindak secara terpisah dalam pertarungan, berbagi kesehatan, kemarahan, dan efek tempur. Batas atas kesehatan meningkat 30%. Kemarahan serangan kembar yang bertindak sendiri berkurang 30%\n#F20# \n#F40##L10# Twin Phantoms: #L0# Saat menyerang dalam bentuk lompat, menggunakan [Pink Melody Fruit]: ada 20% kemungkinan hantu secara acak menargetkan musuh selama 1 giliran; saat menyerang dalam bentuk menyanyi, menggunakan [Red Melody Fruit]: prioritaskan unit penyerang hantu atau pesona, dan unit yang diserang oleh hantu mengabaikan 40% pengurangan kerusakan mereka; Meloetta imun terhadap efek gaib dan pesona\n#F20# \n#F40##L10# Melody Tree: #L0# Setelah Meloetta menggunakan buah melodi lima warna, dia bersembunyi di dalam pohon melodi setelah menerima serangan kritis. Pohon melodi mewarisi 100% atribut Meloetta dan memiliki #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# batas atas kesehatan. Jika tidak hancur setelah ronde besar, Meloetta akan pulih #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# batas atas kesehatan dan 500 poin kemarahan akan muncul kembali di medan perang.',
		describe_ph = '#L10# Simbiosis: #L0# Ang kambal ni Meloetta ay kumikilos nang hiwalay sa laban, nagbabahagi ng kalusugan, galit, at epekto sa labanan. Ang itaas na hangganan ng kalusugan ay tumataas ng 30%. Ang galit sa pag-atake ng kambal na kumikilos nang hiwalay ay bumababa ng 30%\n#F20# \n#F40##L10# Twin Phantoms: #L0# Kapag umaatake sa anyong tumatalon, gamit ang [Pink Melody Fruit]: may 20% na tsansa na ang multo ay random na tututok sa kalaban sa loob ng 1 turn; kapag umaatake sa anyong kumakanta, gamit ang [Red Melody Fruit]: unahin ang mga yunit na umaatake gamit ang multo o pang-akit, at ang mga yunit na inatake ng mga multo ay nilalampasan ang 40% na bawas sa pinsala; si Meloetta ay immune sa mga epekto ng multo at pang-akit\n#F20# \n#F40##L10# Melody Tree: #L0# Pagkatapos gamitin ni Meloetta ang limang-kulay na prutas ng melodiya, siya ay magtatago sa loob ng puno ng melodiya pagkatapos makatanggap ng kritikal na pinsala. Ang puno ng melodiya ay namamana ang 100% na katangian ni Meloetta at may #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# ng itaas na hangganan ng kalusugan. Kung hindi ito masisira pagkatapos ng malaking round, si Meloetta ay gagaling ng #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# ng itaas na hangganan ng kalusugan at 500 puntos ng galit ay muling lilitaw sa battlefield.',
		describe_ma = '#L10# Simbiosis: #L0# Kembar Meloetta bertindak secara berasingan dalam pertempuran, berkongsi kesihatan, kemarahan, dan kesan bertempur. Had atas kesihatan meningkat 30%. Kemarahan serangan kembar yang bertindak sendiri berkurangan 30%\n#F20# \n#F40##L10# Twin Phantoms: #L0# Apabila menyerang dalam bentuk melompat, menggunakan [Buah Melodi Merah Jambu]: terdapat 20% kemungkinan hantu secara rawak mensasarkan musuh selama 1 giliran; apabila menyerang dalam bentuk menyanyi, menggunakan [Buah Melodi Merah]: mengutamakan unit penyerang hantu atau pesona, dan unit yang diserang oleh hantu mengabaikan pengurangan kerosakan mereka sebanyak 40%; Meloetta kebal terhadap kesan hantu dan pesona\n#F20# \n#F40##L10# Melody Tree: #L0# Selepas Meloetta menggunakan buah melodi lima warna, dia akan bersembunyi dalam pokok melodi selepas menerima serangan kritikal. Pokok melodi mewarisi 100% atribut Meloetta dan mempunyai #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# had atas kesihatan. Jika tidak hancur selepas pusingan besar, Meloetta akan pulih #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# had atas kesihatan dan 500 mata kemarahan akan muncul semula di medan perang.',
		describe = '#L10# Symbiosis: #L0# Meloetta\'s twin acts separately in battle, sharing health, rage, and combat effects. The upper limit of health increases by 30%. The twin\'s individual attack rage decreases by 30%\n#F20# \n#F40##L10# Twin Phantoms: #L0# When attacking in jump form, using [Pink Melody Fruit]: there is a 20% chance that a phantom will randomly target an enemy for 1 turn; when attacking in singing form, using [Red Melody Fruit]: prioritize phantom or charm-attacking units, and units attacked by phantoms ignore 40% of the damage reduction; Meloetta is immune to ghostly and charm effects\n#F20# \n#F40##L10# Melody Tree: #L0# After Meloetta uses the five-color melody fruit, she hides inside the melody tree after receiving a critical hit. The melody tree inherits 100% of Meloetta\'s attributes and has #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# of the upper health limit. If not destroyed after the major round, Meloetta recovers #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# of the upper health limit and 500 rage points reappear on the battlefield.',
		starEffect = __data_t__starEffect[32646],
		-- {8}
		starEffectDesc_vn = 'Sau khi đơn vị bóng ma của kẻ địch hành động, Meloyata có thể hồi phục 50% tổng chỉ số Công Vật Lý và phép của bản thân.',
		starEffectDesc = 'After the enemy\'s ghost unit acts, Meloyata can recover 50% of her total Physical and Magical Attack stats.',
		starEffectDesc_en = 'After the enemy\'s ghost unit acts, Meloyata can recover 50% of her total Physical and Magical Attack stats.',
		starEffectDesc_th = 'หลังจากที่หน่วยผีของศัตรูทำการเคลื่อนไหว Meloyata สามารถฟื้นฟูพลังโจมตีร่างกายและเวทมนตร์ทั้งหมดของตัวเองได้ 50%',
		starEffectDesc_in = 'Setelah unit hantu musuh bertindak, Meloyata dapat memulihkan 50% dari total statistik Serangan Fisik dan Magical-nya.',
		starEffectDesc_ph = 'Pagkatapos kumilos ang yunit ng multo ng kalaban, maaaring makabawi si Meloyata ng 50% ng kabuuang katangian ng kanyang Pisikal at Mahikal na Atake.',
		starEffectDesc_ma = 'Selepas unit hantu musuh bergerak, Meloyata boleh memulihkan 50% jumlah keseluruhan statistik Serangan Fizikal dan Sihirnya.',
		zawakeEffect = __data_t__zawakeEffect[32646],
		-- {79004, 1}
		zawakeEffectDesc = '#L10# Symbiosis: #L0# The twin pair of Meloetta act independently in battle, sharing health, rage, and combat effects. The upper limit of increased HP is 30%. The rage attack in the corresponding actions of the twins is reduced by 30%. After performing in dance form, the double attack of the singing form increases by 20%. After performing in singing form, the speed of the dance form increases by 15%\n#F20# \n#F40# #L10# Twin Phantoms: #L0# When attacking in dance form, using <Pink Melody Fruit>: there is a 20% chance a phantom randomly targets an enemy for 1 turn; when attacking in singing form, use <Red Melody Fruit>: prioritizing phantom or charm attacking units, and attack units that have had their damage reduction by phantoms bypassed by 40%; Meloetta is immune to ghostly and charm effects\n#F20# \n#F40# #L10# Melody Tree: #L0# After Meloetta uses the five-colored melody fruit, she hides in the melody tree after receiving a critical hit. The melody tree inherits 100% of Meloetta\'s attributes and has an HP limit of #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#. If in a large battle round, if not crushed after the end, Meloetta will recover #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# HP and 500 rage points to reappear on the battlefield; after obtaining a different four-colored melody fruit except the <Purple Melody Fruit> for the first time, she immediately unleashes a special killer move and consumes all current rage.',
		zawakeEffectDesc_en = '#L10# Symbiosis: #L0# The twin pair of Meloetta act independently in battle, sharing health, rage, and combat effects. The upper limit of increased HP is 30%. The rage attack in the corresponding actions of the twins is reduced by 30%. After performing in dance form, the double attack of the singing form increases by 20%. After performing in singing form, the speed of the dance form increases by 15%\n#F20# \n#F40# #L10# Twin Phantoms: #L0# When attacking in dance form, using <Pink Melody Fruit>: there is a 20% chance a phantom randomly targets an enemy for 1 turn; when attacking in singing form, use <Red Melody Fruit>: prioritizing phantom or charm attacking units, and attack units that have had their damage reduction by phantoms bypassed by 40%; Meloetta is immune to ghostly and charm effects\n#F20# \n#F40# #L10# Melody Tree: #L0# After Meloetta uses the five-colored melody fruit, she hides in the melody tree after receiving a critical hit. The melody tree inherits 100% of Meloetta\'s attributes and has an HP limit of #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#. If in a large battle round, if not crushed after the end, Meloetta will recover #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# HP and 500 rage points to reappear on the battlefield; after obtaining a different four-colored melody fruit except the <Purple Melody Fruit> for the first time, she immediately unleashes a special killer move and consumes all current rage.',
		zawakeEffectDesc_th = '#L10# การพึ่งพาอาศัยกัน: #L0# คู่แฝดของ Meloetta ทำหน้าที่แยกกันในสนามรบ โดยแบ่งปันสุขภาพ ความโกรธ และผลต่อการต่อสู้ ขีดจำกัดบนของการเพิ่มพลังชีวิตคือ 30% การโจมตีด้วยความโกรธในแต่ละการกระทำของคู่แฝดลดลง 30% หลังจากแสดงในรูปแบบเต้น ร่วมโจมตีของรูปแบบร้องเพลงเพิ่มขึ้น 20% หลังจากแสดงในรูปแบบร้องเพลง ความเร็วของรูปแบบเต้นเพิ่มขึ้น 15%\n#F20# \n#F40# #L10# ผีแฝด: #L0# เมื่อโจมตีในรูปแบบเต้น โดยใช้ <ผลไม้เมโลดี้สีชมพู>: มีโอกาส 20% ที่ผีจะสุ่มโจมตีเป้าหมายศัตรูเป็นเวลา 1 เทิร์น; เมื่อโจมตีในรูปแบบร้องเพลง ใช้ <ผลไม้เมโลดี้สีแดง>: ให้ความสำคัญกับหน่วยที่โจมตีด้วยผีหรือสาป และหน่วยโจมตีที่ถูกผีละเลย ค่าลดความเสียหายจากผีลดลง 40%; Meloetta ป้องกันผลกระทบจากผีและเสน่ห์\n#F20# \n#F40# #L10# ต้นเมโลดี้: #L0# หลังจาก Meloetta ใช้ผลไม้ท่วงทำนองห้าสี เธอจะหลบซ่อนในต้นเมโลดี้หลังจากได้รับบาดเจ็บวิกฤติ ต้นเมโลดี้สืบทอดคุณสมบัติ 100% ของ Meloetta และมีข้อจำกัดพลังชีวิต #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# หากในการต่อสู้รอบใหญ่ หากไม่ถูกบดขยี้หลังสิ้นสุด Meloetta จะฟื้นพลังชีวิต #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# และ 500 คะแนนความโกรธ เพื่อปรากฏตัวอีกครั้งบนสนามรบ; หลังได้รับผลไม้ท่วงทำนองสีสี่อื่นที่ไม่ใช่ <ผลไม้ท่วงทำนองสีม่วง> ครั้งแรก จะปล่อยท่าโจมตีฆ่าพิเศษทันทีและใช้ความโกรธทั้งหมดที่มีอยู่',
		zawakeEffectDesc_in = '#L10# Simbiosis: #L0# Pasangan kembar Meloetta bertindak secara terpisah dalam pertempuran, berbagi kesehatan, kemarahan, dan efek pertarungan. Batas atas peningkatan HP adalah 30%. Serangan kemarahan pada aksi terkait pasangan kembar berkurang 30%. Setelah tampil dalam bentuk tarian, serangan ganda bentuk bernyanyi meningkat 20%. Setelah tampil dalam bentuk bernyanyi, kecepatan bentuk tarian meningkat 15%\n#F20# \n#F40# #L10# Twin Phantoms: #L0# Saat menyerang dalam bentuk tarian, menggunakan <Buah Melodi Merah Muda>: ada 20% kemungkinan hantu secara acak menargetkan musuh selama 1 giliran; saat menyerang dalam bentuk bernyanyi, gunakan <Buah Melodi Merah>: memprioritaskan unit penyerang hantu atau pesona, dan unit penyerang yang telah melewati pengurangan damage dari hantu sebesar 40%; Meloetta kebal terhadap efek hantu dan pesona\n#F20# \n#F40# #L10# Pohon Melodi: #L0# Setelah Meloetta menggunakan buah melodi lima warna, dia bersembunyi di pohon melodi setelah menerima serangan kritis. Pohon melodi mewarisi 100% atribut Meloetta dan memiliki batas HP #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#. Jika dalam ronde pertempuran besar, jika tidak hancur setelah selesai, Meloetta akan memulihkan #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# HP dan 500 poin kemarahan untuk muncul kembali di medan perang; setelah mendapatkan buah melodi empat warna berbeda kecuali <Buah Melodi Ungu> untuk pertama kalinya, ia segera melancarkan serangan pembunuh khusus dan menghabiskan semua kemarahan saat ini.',
		zawakeEffectDesc_ph = '#L10# Simbiosis: #L0# Ang kambal na pares ni Meloetta ay kumikilos nang hiwalay sa laban, nagbabahagi ng kalusugan, galit, at epekto sa laban. Ang itaas na limitasyon ng pagtaas ng HP ay 30%. Ang galit na atake sa kaugnay na kilos ng kambal ay nababawasan ng 30%. Pagkatapos mag-porma sa sayaw, ang dobleng atake ng pormang kumakanta ay tumataas ng 20%. Pagkatapos mag-porma sa pagkanta, ang bilis ng pormang sumasayaw ay tumataas ng 15%\n#F20# \n#F40# #L10# Mga Kambal na Multo: #L0# Kapag umaatake sa pormang sumasayaw, gamit ang <Pink Melody Fruit>: may 20% na pagkakataon na ang multo ay random na lalapit sa kalaban sa loob ng 1 turn; kapag umaatake sa pormang kumakanta, gamitin ang <Red Melody Fruit>: inuuna ang mga yunit na umaatake gamit ang multo o pang-akit, at mga yunit na umaatake na nilaktawan ang 40% pagbawas ng pinsala ng mga multo; ang Meloetta ay immune sa mga epekto ng multo at pang-akit\n#F20# \n#F40# #L10# Puno ng Melodiya: #L0# Pagkatapos gamitin ni Meloetta ang limang-kulay na prutas ng melodiya, siya ay nagtatago sa puno ng melodiya pagkatapos makatanggap ng matinding tama. Ang puno ng melodiya ay namamana ng 100% mga katangian ni Meloetta at may limitasyon ng HP na #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#. Kung sa isang malaking laban, kung hindi siya napatumba pagkatapos ng pagtatapos, si Meloetta ay gagaling ng #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# HP at 500 puntos ng galit para muling lumitaw sa laban; pagkatapos makakuha ng ibang apat na kulay na prutas ng melodiya maliban sa <Purple Melody Fruit> sa unang pagkakataon, agad niyang ilulunsad ang isang espesyal na patayang galaw at kukonsumo ang lahat ng kasalukuyang galit.',
		zawakeEffectDesc_ma = '#L10# Simbiosis: #L0# Pasangan kembar Meloetta bertindak secara berasingan dalam pertempuran, berkongsi kesihatan, kemarahan, dan kesan pertempuran. Batas atas peningkatan HP adalah 30%. Serangan kemarahan dalam tindakan berkaitan pasangan kembar dikurangkan sebanyak 30%. Selepas melakukan aksi dalam bentuk tarian, serangan berganda bentuk nyanyian meningkat sebanyak 20%. Selepas melakukan aksi dalam bentuk nyanyian, kelajuan bentuk tarian meningkat sebanyak 15%\n#F20# \n#F40# #L10# Roh Kembar: #L0# Apabila menyerang dalam bentuk tarian, menggunakan <Buah Melodi Merah Jambu>: terdapat 20% kemungkinan roh hantu menyerang musuh secara rawak selama 1 pusingan; apabila menyerang dalam bentuk nyanyian, gunakan <Buah Melodi Merah>: utamakan unit penyerang roh hantu atau pesona, dan unit penyerang yang telah melepasi pengurangan kerosakan oleh roh hantu sebanyak 40%; Meloetta kebal terhadap kesan hantu dan pesona\n#F20# \n#F40# #L10# Pokok Melodi: #L0# Selepas Meloetta menggunakan buah melodi lima warna, dia bersembunyi dalam pokok melodi selepas menerima serangan kritikal. Pokok melodi mewarisi 100% atribut Meloetta dan mempunyai had HP #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#. Jika dalam pusingan pertempuran besar, jika tidak dihancurkan selepas tamat, Meloetta akan pulih #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# HP dan 500 mata kemarahan untuk muncul semula di medan perang; selepas mendapat buah melodi empat warna lain kecuali <Buah Melodi Ungu> kali pertama, ia segera melancarkan serangan pembunuh khas dan menggunakan semua kemarahan semasa.',
		zawakeEffectDesc_vn = '#L10# Cộng sinh: #L0# Cặp song sinh của Meloetta hành động riêng biệt trong trận chiến, chia sẻ sức khỏe, cơn thịnh nộ và hiệu ứng chiến đấu. Giới hạn trên của lượng máu tăng 30%. Cơn giận tấn công trong các hành động tương ứng của cặp song sinh giảm đi 30%. Sau khi diễn ở dạng nhảy, đòn tấn công kép của dạng hát tăng thêm 20%. Sau khi diễn ở dạng ca hát, tốc độ của dạng nhảy tăng thêm 15%\n#F20# \n#F40##L10# Twin Phantoms: #L0# Khi tấn công ở dạng nhảy, sử dụng <Pink Melody Fruit>: có 20% khả năng bóng ma ngẫu nhiên nhắm vào kẻ địch trong 1 lượt; khi tấn công ở dạng ca hát, hãy sử dụng <Quả giai điệu đỏ>: Ưu tiên cho các đơn vị tấn công bóng ma hoặc bùa mê, và các đơn vị tấn công đã bị bóng ma bỏ qua mức giảm 40% sát thương của chúng; Meloetta miễn nhiễm với các hiệu ứng ma quái và quyến rũ\n#F20# \n#F40##L10#Melody Tree: #L0# Sau khi Meloetta sử dụng trái giai điệu năm màu, cô ấy sẽ trốn trong cây giai điệu sau khi nhận sát thương chí mạng. Cây giai điệu kế thừa 100% thuộc tính của Meloetta và có giới hạn máu #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B#. Nếu trong một hiệp đấu lớn, Nếu không bị đè bẹp sau khi kết thúc, Meloetta sẽ hồi phục #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# HP và 500 điểm thịnh nộ để xuất hiện trở lại trên chiến trường; sau khi lấy được trái giai điệu bốn màu khác ngoại trừ <Trái giai điệu tím> lần đầu tiên, nó sẽ ngay lập tức tung ra một chiêu thức tiêu diệt đặc biệt và tiêu diệt toàn bộ cơn thịnh nộ hiện tại.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Sau khi hành động trong Tư thế Vũ Bộ, tăng 20% song công cho Tư thế Ca Hát; sau khi hành động trong Tư thế Ca Hát, tăng 15% tốc độ cho Tư thế Vũ Bộ; lần đầu nhận được quả giai điệu bốn màu (trừ quả giai điệu tím), sẽ ngay lập tức sử dụng một lần kỹ năng tối thượng và tiêu hao toàn bộ nộ khí hiện tại',
		zawakeSimpleDesc_en = 'Sau khi hành động trong Tư thế Vũ Bộ, tăng 20% song công cho Tư thế Ca Hát; sau khi hành động trong Tư thế Ca Hát, tăng 15% tốc độ cho Tư thế Vũ Bộ; lần đầu nhận được quả giai điệu bốn màu (trừ quả giai điệu tím), sẽ ngay lập tức sử dụng một lần kỹ năng tối thượng và tiêu hao toàn bộ nộ khí hiện tại',
		zawakeSimpleDesc_th = 'Sau khi hành động trong Tư thế Vũ Bộ, tăng 20% song công cho Tư thế Ca Hát; sau khi hành động trong Tư thế Ca Hát, tăng 15% tốc độ cho Tư thế Vũ Bộ; lần đầu nhận được quả giai điệu bốn màu (trừ quả giai điệu tím), sẽ ngay lập tức sử dụng một lần kỹ năng tối thượng và tiêu hao toàn bộ nộ khí hiện tại',
		zawakeSimpleDesc_in = 'Sau khi hành động trong Tư thế Vũ Bộ, tăng 20% song công cho Tư thế Ca Hát; sau khi hành động trong Tư thế Ca Hát, tăng 15% tốc độ cho Tư thế Vũ Bộ; lần đầu nhận được quả giai điệu bốn màu (trừ quả giai điệu tím), sẽ ngay lập tức sử dụng một lần kỹ năng tối thượng và tiêu hao toàn bộ nộ khí hiện tại',
		zawakeSimpleDesc_ph = 'Sau khi hành động trong Tư thế Vũ Bộ, tăng 20% song công cho Tư thế Ca Hát; sau khi hành động trong Tư thế Ca Hát, tăng 15% tốc độ cho Tư thế Vũ Bộ; lần đầu nhận được quả giai điệu bốn màu (trừ quả giai điệu tím), sẽ ngay lập tức sử dụng một lần kỹ năng tối thượng và tiêu hao toàn bộ nộ khí hiện tại',
		zawakeSimpleDesc_ma = 'Sau khi hành động trong Tư thế Vũ Bộ, tăng 20% song công cho Tư thế Ca Hát; sau khi hành động trong Tư thế Ca Hát, tăng 15% tốc độ cho Tư thế Vũ Bộ; lần đầu nhận được quả giai điệu bốn màu (trừ quả giai điệu tím), sẽ ngay lập tức sử dụng một lần kỹ năng tối thượng và tiêu hao toàn bộ nộ khí hiện tại',
		zawakeSimpleDesc_vn = 'Sau khi hành động trong Tư thế Vũ Bộ, tăng 20% song công cho Tư thế Ca Hát; sau khi hành động trong Tư thế Ca Hát, tăng 15% tốc độ cho Tư thế Vũ Bộ; lần đầu nhận được quả giai điệu bốn màu (trừ quả giai điệu tím), sẽ ngay lập tức sử dụng một lần kỹ năng tối thượng và tiêu hao toàn bộ nộ khí hiện tại',
