	[32712] = {
		id = 32712,
		skillName_vn = 'Súng ánh sáng công nghệ cao',
		skillName_en = 'High-tech light gun',
		skillName_th = 'ปืนแสงเทคโนโลยีขั้นสูง',
		skillName_in = 'Senjata cahaya teknologi tinggi',
		skillName_ph = 'Mataas na teknolohiyang ilaw na baril',
		skillName_ma = 'Senapang cahaya teknologi tinggi',
		skillName = 'High-tech light gun',
		describe_vn = 'Genesect liên tục bắn đạn pháo vào một mục tiêu địch, gây #C0xE69900# tấn công 180% #C0x5B545B# + $(skillLevel*4*48)$ của #C0xF13B54# sát thương #C0x5B545B# và triệu tập một người lính\n#F20# \n#F40##L10#[Soldier]#L0#At đến cuối lượt của Genesect, nó tấn công một kẻ thù. Mỗi người lính gây ra 180% Sát Thương Vật Lý. Các đòn tấn công của người lính có hiệu ứng tải xuống và tăng Cơn thịnh nộ thêm 100. Khi được sạc đầy, sát thương của người lính tăng thêm 50%\n#F20# \n#F40##L10#[Sacrifice]#L0# Mỗi người lính tự nguyện hy sinh để bù đắp đòn tấn công chủ động của Genesect có giá trị sát thương vượt quá 35% giới hạn máu tối đa và phục hồi 200 cơn thịnh nộ của nó. Những người lính vượt quá giới hạn trên sẽ bị [Hy sinh].',
		describe_en = 'Genesect continuously fires cannonballs at an enemy target, dealing #C0xE69900# 180% attack #C0x5B545B# + $(skillLevel*4*48)$ of #C0xF13B54# damage #C0x5B545B# and summons a soldier \n#F20# \n#F40##L10#[Soldier]#L0#. Until the end of Genesect\'s turn, it attacks an enemy. Each soldier deals 180% Physical Damage. Soldiers\' attacks have a charge effect and increase Fury by 100. When fully charged, soldiers\' damage is increased by 50% \n#F20# \n#F40##L10#[Sacrifice]#L0#. Each soldier voluntarily sacrifices to compensate for Genesect\'s active attack damage exceeding 35% of max HP and restores 200 Fury. Soldiers exceeding this limit will be [Sacrificed].',
		describe_th = 'Genesect ยิงกระสุนปืนใหญ่ใส่เป้าหมายศัตรูอย่างต่อเนื่อง ทำให้เกิดความเสียหาย #C0xE69900# 180% การโจมตี #C0x5B545B# + $(skillLevel*4*48)$ ของ #C0xF13B54# ความเสียหาย #C0x5B545B# และเรียกทหาร \n#F20# \n#F40##L10#[Soldier]#L0# จนถึงสิ้นสุดเทิร์นของ Genesect มันโจมตีศัตรู แต่ละทหารสร้างความเสียหายทางกายภาพ 180% การโจมตีของทหารมีเอฟเฟกต์ชาร์จและเพิ่มความโกรธขึ้น 100 เมื่อชาร์จเต็ม ความเสียหายของทหารจะเพิ่มขึ้นอีก 50% \n#F20# \n#F40##L10#[Sacrifice]#L0# ทหารแต่ละคนยอมสละตัวเองเพื่อชดเชยการโจมตีหลักของ Genesect ที่มีค่าความเสียหายเกิน 35% ของพลังชีวิตสูงสุดและฟื้นฟูความโกรธ 200 ทหารที่เกินขีดจำกัดนี้จะถูก [Hy sinh].',
		describe_in = 'Genesect terus menembakkan peluru meriam ke target musuh, memberikan serangan #C0xE69900# 180% #C0x5B545B# + $(skillLevel*4*48)$ dari #C0xF13B54# kerusakan #C0x5B545B# dan memanggil seorang prajurit \n#F20# \n#F40##L10#[Soldier]#L0#. Hingga akhir giliran Genesect, ia menyerang musuh. Setiap prajurit memberikan 180% Damage Fisik. Serangan prajurit memiliki efek pengisian dan meningkatkan Amarah sebesar 100. Saat terisi penuh, kerusakan prajurit meningkat 50% \n#F20# \n#F40##L10#[Sacrifice]#L0#. Setiap prajurit dengan sukarela berkorban untuk menutupi serangan aktif Genesect yang melebihi 35% batas HP maksimal dan memulihkan 200 Amarah. Prajurit yang melebihi batas ini akan [Dikorbankan].',
		describe_ph = 'Patuloy na nagpapaputok si Genesect ng mga bala ng kanyon sa isang kaaway na target, na nagdudulot ng #C0xE69900# 180% na atake #C0x5B545B# + $(skillLevel*4*48)$ ng #C0xF13B54# pinsala #C0x5B545B# at sumusumpa ng isang sundalo \n#F20# \n#F40##L10#[Soldier]#L0#. Hanggang sa katapusan ng turn ni Genesect, ito ay umaatake sa isang kalaban. Bawat sundalo ay nagdudulot ng 180% Physical Damage. Ang mga atake ng sundalo ay may charging effect at nagpapataas ng Galit ng 100. Kapag ganap nang nai-charge, tumataas ang pinsala ng sundalo ng 50% \n#F20# \n#F40##L10#[Sacrifice]#L0#. Bawat sundalo ay kusang nag-aalay ng sarili upang mapunan ang aktibong atake ni Genesect na lumalampas sa 35% ng maximum na HP at nagpapagaling ng 200 Galit. Ang mga sundalong lumalampas sa limitasyong ito ay [Isasakripisyo].',
		describe_ma = 'Genesect berterusan menembak peluru meriam ke sasaran musuh, memberikan serangan #C0xE69900# 180% #C0x5B545B# + $(skillLevel*4*48)$ daripada #C0xF13B54# kerosakan #C0x5B545B# dan memanggil seorang askar \n#F20# \n#F40##L10#[Soldier]#L0#. Sehingga akhir giliran Genesect, ia menyerang musuh. Setiap askar menyebabkan 180% Kerosakan Fizikal. Serangan askar mempunyai kesan cas dan meningkatkan Amarah sebanyak 100. Apabila dicas penuh, kerosakan askar meningkat 50% \n#F20# \n#F40##L10#[Sacrifice]#L0#. Setiap askar secara sukarela berkorban untuk menampung serangan aktif Genesect yang melebihi 35% had HP maksimum dan memulihkan 200 Amarah. Askar yang melebihi had ini akan [Dikorbankan].',
		describe = 'Genesect continuously fires cannonballs at an enemy target, dealing #C0xE69900# 180% attack #C0x5B545B# + $(skillLevel*4*48)$ of #C0xF13B54# damage #C0x5B545B# and summons a soldier \n#F20# \n#F40##L10#[Soldier]#L0#. Until the end of Genesect\'s turn, it attacks an enemy. Each soldier deals 180% Physical Damage. Soldiers\' attacks have a charge effect and increase Fury by 100. When fully charged, soldiers\' damage is increased by 50% \n#F20# \n#F40##L10#[Sacrifice]#L0#. Each soldier voluntarily sacrifices to compensate for Genesect\'s active attack damage exceeding 35% of max HP and restores 200 Fury. Soldiers exceeding this limit will be [Sacrificed].',
