	[32713] = {
		id = 32713,
		skillName_vn = 'Tải xuống',
		skillName_en = 'Download',
		skillName_th = 'ดาวน์โหลด',
		skillName_in = 'Unduh',
		skillName_ph = 'I-download',
		skillName_ma = 'Muat turun',
		skillName = 'Download',
		describe_vn = 'Genesect ra lệnh cho quân đoàn bao vây mục tiêu và triệu tập một người lính\n#F10# \n#F40# Sau đó anh ta bước vào giai đoạn sạc trong 1 hiệp. Trong thời gian sạc, tỷ lệ không cần điều khiển và giảm Sát Thương Vật Lý tăng thêm 50%. Lần tiếp theo mệnh lệnh hành động của anh ta được nâng lên vị trí đầu tiên trong trại của chính mình, khi cuộc tấn công kết thúc, anh ta phóng đại bác hạng nhẹ công nghệ cao bắn phá các mục tiêu hàng của kẻ thù, gây ra #C0xE69900#700% attack#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#damage#C0x5B545B#\n#F10# \n#F40# Sau khi sạc, vào 1 hiệp [chế độ tháp pháo] (tốc độ giảm xuống 1 điểm, giảm 30% sát thương và tỷ lệ không bị khống chế, khi các anh hùng côn trùng hoặc máy móc thân thiện khác sử dụng kỹ năng chủ động, họ sẽ sử dụng pháo hạng nhẹ để hợp tác, gây ra #C0xE69900#300% tấn công vào một mục tiêu#C0x5B545B#+$(skillL evel*4*90)$\'s #C0xF13B54# sát thương #C0x5B545B#, và gây 30% sát thương lan ra xung quanh, hưởng phần thưởng sát thương di chuyển đặc biệt và bị giới hạn 5 lần), kiểm soát không chiếm ưu thế sẽ làm gián đoạn quá trình tấn công và giải phóng chiêu thức đặc biệt trước (chỉ giữ lại 50% sức mạnh và trả lại 300 cơn thịnh nộ và không thể vào [chế độ tháp pháo])',
		describe_en = 'Genesect commands the legion to surround the target and summons a scout. Then he enters a charging phase for 1 turn. During charging, the control immunity rate and Physical Damage Reduction increase by 50%. The next action order of his commands is elevated to the first position in his own camp. When the attack finishes, he fires a high-tech light-class cannon at rows of enemy targets, dealing #C0xE69900#700% attack#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# damage#C0x5B545B#. After charging, he enters a [turret mode] for 1 turn (speed reduces by 1 point, damage and control immunity decrease by 30%). When friendly insect or mechanical heroes use active skills, they will cooperate by firing light cannons, dealing #C0xE69900#300% attack#C0x5B545B#+$(skillLevel*4*90)$\'s #C0xF13B54# damage#C0x5B545B# to a single target, and causing 30% splash damage around, gaining special move damage bonuses and is limited to 5 times. Non-dominant control will interrupt the attack process and release the special skill early (with only 50% power retained and refunding 300 rage, unable to enter [turret mode]).',
		describe_th = 'Genesect สั่งกองทัพให้ล้อมเป้าหมายและเรียกทหารลาดตระเวน จากนั้นเขาเข้าสู่ช่วงชาร์จเป็นเวลา 1 เทิร์น ในช่วงชาร์จ อัตราป้องกันสถานะควบคุมและการลดความเสียหายทางกายภาพเพิ่มขึ้น 50% คำสั่งถัดไปของเขาจะถูกยกระดับเป็นอันดับหนึ่งในค่ายของตนเอง เมื่อการโจมตีสิ้นสุดลง เขาจะยิงปืนเบาเทคโนโลยีสูงใส่แถวเป้าหมายของศัตรู สร้างความเสียหาย #C0xE69900#700% การโจมตี#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# ความเสียหาย#C0x5B545B# หลังการชาร์จ เขาเข้าสู่ [โหมดป้อมปืน] เป็นเวลา 1 เทิร์น (ความเร็วลดลง 1 แต้ม ลดความเสียหายและอัตราป้องกันสถานะควบคุมลง 30%) เมื่อฮีโร่แมลงหรือเครื่องจักรพันธมิตรใช้สกิลเชิงรุก พวกเขาจะใช้ปืนเบาร่วมกัน สร้างความเสียหาย #C0xE69900#300% การโจมตี#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# ความเสียหาย#C0x5B545B# ใส่เป้าหมายเดี่ยว และทำความเสียหายรอบข้าง 30% รับโบนัสความเสียหายพิเศษและจำกัด 5 ครั้ง การควบคุมที่ไม่ครอบงำจะหยุดกระบวนการโจมตีและปล่อยทักษะพิเศษก่อน (เก็บพลังไว้เพียง 50% คืนแค้น 300 แต้ม และไม่สามารถเข้าสู่ [โหมดป้อมปืน])',
		describe_in = 'Genesect memerintahkan pasukan untuk mengepung target dan memanggil seorang pengintai. Kemudian dia memasuki fase pengisian selama 1 giliran. Selama pengisian, tingkat kebal kontrol dan pengurangan Kerusakan Fisik meningkat sebesar 50%. Perintah aksi berikutnya dinaikkan ke posisi pertama di kamarnya sendiri. Saat serangan selesai, dia menembakkan meriam ringan teknologi tinggi ke barisan target musuh, memberikan #C0xE69900#700% serangan#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# kerusakan#C0x5B545B#. Setelah pengisian, memasuki [mode turret] selama 1 giliran (kecepatan berkurang 1 poin, pengurangan 30% kerusakan dan kebal kontrol), saat pahlawan serangga atau mekanik ramah menggunakan skill aktif, mereka akan bekerjasama menggunakan meriam ringan, memberikan #C0xE69900#300% serangan#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# kerusakan#C0x5B545B# ke satu target, serta menyebabkan 30% kerusakan area di sekitar, mendapat bonus kerusakan gerakan khusus dan dibatasi 5 kali. Kontrol non-dominan akan menghentikan proses serangan dan melepaskan skill khusus terlebih dahulu (hanya mempertahankan 50% kekuatan dan mengembalikan 300 kemarahan, tidak dapat memasuki [mode turret]).',
		describe_ph = 'Iniuutos ni Genesect ang utos sa legion na bumalot sa target at tumawag ng isang scout. Pagkatapos ay pumapasok siya sa phase ng pagsingil sa loob ng 1 turn. Sa panahon ng pagsingil, ang rate ng immunity sa control at pagbawas ng Pisikal na Pinsala ay tumataas ng 50%. Ang susunod na utos ng kanyang aksyon ay itinaas sa unang posisyon sa sariling kampo. Kapag natapos ang pag-atake, nagpapaputok siya ng high-tech light-class cannon sa mga hilera ng mga target ng kalaban, na nagdudulot ng #C0xE69900#700% attack#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# damage#C0x5B545B#. Pagkatapos ng pagsingil, pumapasok sa [turret mode] sa loob ng 1 turn (bawas ng 1 point sa bilis, bawas ng 30% sa pinsala at rate ng immunity sa control). Kapag ang mga kaibigang insect o mekanikal na bayani ay gumamit ng aktibong kasanayan, sila ay magko-kolaborasyon gamit ang light cannon, na nagdudulot ng #C0xE69900#300% attack#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# damage#C0x5B545B# sa isang target, at nagdudulot ng 30% splash damage sa paligid, tumatanggap ng espesyal na bonus sa pinsala at limitado sa 5 beses. Ang hindi nangingibabaw na kontrol ay nakakagambala sa proseso ng pag-atake at nagpapakawala ng espesyal na kasanayan nang maaga (nagpapanatili lamang ng 50% lakas at nagbabalik ng 300 galit, hindi makapasok sa [turret mode]).',
		describe_ma = 'Genesect mengarahkan tentera mengepung sasaran dan memanggil seorang pengintip. Kemudian dia memasuki fasa mengecas selama 1 pusingan. Semasa mengecas, kadar imun kawalan dan pengurangan Kerosakan Fizikal meningkat sebanyak 50%. Perintah tindakannya yang seterusnya dinaikkan ke kedudukan pertama dalam kemnya sendiri. Apabila serangan selesai, dia membaling meriam ringan berteknologi tinggi ke barisan sasaran musuh, menyebabkan #C0xE69900#700% serangan#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# kerosakan#C0x5B545B#. Selepas mengecas, memasuki [mod menara] selama 1 pusingan (kelajuan berkurang 1 mata, pengurangan 30% kerosakan dan kadar imun kawalan), apabila wira serangga atau mekanik yang mesra menggunakan kemahiran aktif, mereka akan bekerjasama menggunakan meriam ringan, menyebabkan #C0xE69900#300% serangan#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# kerosakan#C0x5B545B# ke satu sasaran, dan menyebabkan 30% kerosakan sekitar, mendapat bonus kerosakan gerakan khas dan dihadkan kepada 5 kali. Kawalan tidak dominan akan mengganggu proses serangan dan melepaskan kemahiran khas terlebih dahulu (hanya mengekalkan 50% kekuatan dan mengembalikan 300 kemarahan, tidak boleh masuk ke [mod menara]).',
		describe = 'Genesect commands the legion to surround the target and summons a scout. Then he enters a charging phase for 1 turn. During charging, the control immunity rate and Physical Damage Reduction increase by 50%. The next action order of his commands is elevated to the first position in his own camp. When the attack finishes, he fires a high-tech light-class cannon at rows of enemy targets, dealing #C0xE69900#700% attack#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# damage#C0x5B545B#. After charging, he enters a [turret mode] for 1 turn (speed reduces by 1 point, damage and control immunity decrease by 30%). When friendly insect or mechanical heroes use active skills, they will cooperate by firing light cannons, dealing #C0xE69900#300% attack#C0x5B545B#+$(skillLevel*4*90)$\'s #C0xF13B54# damage#C0x5B545B# to a single target, and causing 30% splash damage around, gaining special move damage bonuses and is limited to 5 times. Non-dominant control will interrupt the attack process and release the special skill early (with only 50% power retained and refunding 300 rage, unable to enter [turret mode]).',
		simDesc_vn = 'Genocect chỉ huy quân đoàn bao vây mục tiêu, phóng ra súng ánh sáng công nghệ cao tấn công kẻ thù.',
		simDesc_en = 'Genocect commands the legion to surround the target, unleashing high-tech light guns to attack the enemy.',
		simDesc_th = 'Genocect สั่งการกองพลล้อมเป้าหมาย ปล่อยปืนแสงเทคโนโลยีขั้นสูงโจมตีศัตรู',
		simDesc_in = 'Genocect memerintahkan legiun untuk mengepung target, meluncurkan senjata cahaya teknologi tinggi untuk menyerang musuh.',
		simDesc_ph = 'Pinamumunuan ni Genocect ang legion para salakayin ang target, pinakakawala ang high-tech na light guns upang atakihin ang kalaban.',
		simDesc_ma = 'Genocect mengetuai kor legiun mengepung sasaran, melepaskan senjata cahaya berteknologi tinggi untuk menyerang musuh.',
		simDesc = 'Genocect commands the legion to surround the target, unleashing high-tech light guns to attack the enemy.',
		starEffect = __data_t__starEffect[32713],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Trong trạng thái không phải pháo đài và không phải trạng thái tích lũy, khi đầy giận dữ sẽ ngay lập tức vào trạng thái tích lũy; nếu trạng thái tích lũy bị ngắt, vẫn có thể vào chế độ pháo đài.',
		starEffectDesc = 'Enhance effect: When not in fortress state and not in accumulation state, upon full rage, immediately enter accumulation state; if accumulation state is interrupted, can still enter fortress mode.',
		starEffectDesc_en = 'Enhance effect: When not in fortress state and not in accumulation state, upon full rage, immediately enter accumulation state; if accumulation state is interrupted, can still enter fortress mode.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: ในสถานะที่ไม่ใช่ป้อมปราการและไม่ใช่สถานะสะสม เมื่อความโกรธเต็ม จะเข้าสู่สถานะสะสมทันที; หากสถานะสะสมถูกขัดจังหวะ ยังคงสามารถเข้าสู่โหมดป้อมปราการได้',
		starEffectDesc_in = 'Tingkatkan efek: Dalam keadaan bukan benteng dan bukan dalam keadaan akumulasi, saat kemarahan penuh langsung masuk ke keadaan akumulasi; jika keadaan akumulasi terganggu, masih dapat masuk ke mode benteng.',
		starEffectDesc_ph = 'Palakasin ang epekto: Kapag hindi nasa estado ng fort at hindi nasa estado ng akumulasyon, kapag puno na ng galit ay agad pumasok sa estado ng akumulasyon; kung ang estado ng akumulasyon ay naputol, maaari pa ring pumasok sa mode ng fort.',
		starEffectDesc_ma = 'Tingkatkan kesan: Dalam keadaan bukan kubu dan bukan dalam keadaan pengumpulan, apabila kemarahan penuh akan terus masuk ke keadaan pengumpulan; jika keadaan pengumpulan terganggu, masih boleh masuk ke mod kubu.',
		upLvDesc = 'Fixed damage +136',
		upLvDesc_en = 'Fixed damage +136',
		upLvDesc_th = 'ความเสียหายคงที่ +136',
		upLvDesc_in = 'Kerusakan tetap +136',
