	[32714] = {
		id = 32714,
		describe_vn = 'Mỗi anh hùng hệ côn trùng hoặc cơ khí tăng cho bản thân 10% tăng sát thương và 10% miễn khống chế',
		describe_en = 'Each Insect or Mechanical hero increases their own damage by 10% and resistance to control effects by 10%.',
		describe_th = 'ฮีโร่ระบบแมลงหรือเครื่องจักรแต่ละตัวเพิ่มพลังโจมตีของตนเอง 10% และเพิ่มการต้านทานการควบคุม 10%',
		describe_in = 'Setiap pahlawan sistem serangga atau mekanik meningkatkan kerusakan diri sendiri sebesar 10% dan kekebalan kontrol sebesar 10%.',
		describe_ph = 'Bawat bayani sa sistema ng insekto o mekanikal ay nagpapataas ng sariling pinsala ng 10% at resistensya sa kontrol ng 10%.',
		describe_ma = 'Setiap wira sistem serangga atau mekanikal meningkatkan kerosakan sendiri sebanyak 10% dan imun kawalan sebanyak 10%.',
		describe = 'Each Insect or Mechanical hero increases their own damage by 10% and resistance to control effects by 10%.',
		skillType = 2,
