	[32716] = {
		id = 32716,
		skillName_vn = 'Đầu nhọn',
		skillName_en = 'Pointed tip',
		skillName_th = 'ปลายแหลม',
		skillName_in = 'Ujung runcing',
		skillName_ph = 'Matulis na dulo',
		skillName_ma = 'Titik tajam',
		skillName = 'Pointed tip',
		describe_vn = '#L10#Download: #L0#So sánh khả năng phòng thủ kép của mục tiêu trước khi tấn công, thay đổi kiểu tấn công tùy theo vật phẩm cấp dưới của nó và tăng sức tấn công tương ứng #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; Mỗi anh hùng côn trùng hoặc máy móc bên cạnh bạn sẽ tăng phần thưởng sát thương và tỷ lệ miễn nhiễm kiểm soát thêm 10%\n#F20# \n#F40##L10#Dự trữ năng lượng: #L0# Cơn tức giận dâng trào sẽ được tích trữ dưới dạng năng lượng, với giới hạn trên là 300. Nó sẽ chuyển thành tức giận trước khi bản thân hành động. Năng lượng sẽ được nhận đầu tiên trong thời gian sạc\n#F20# \n#F40##L10# Legion: #L0# Ban đầu đi theo một người lính (tối đa hai), khi người lính được triệu tập, 20% lượng máu đã mất của anh ta sẽ được phục hồi. Khi lần đầu tiên không có lính, anh ta sẽ ngay lập tức triệu tập 1-2 lính\n#F20# \n#F40##L10#Tự hủy: #L0# Khi lượng máu về 0, nó sẽ ngay lập tức chuyển sang chế độ tự hủy. Nó sẽ đếm ngược trong ba vòng. Trong thời gian này, nó sẽ không thể hành động. Nó sẽ phát nổ sau tổng cộng 3 đòn tấn công đang hoạt động hoặc thời gian đếm ngược kết thúc. Nó sẽ gây 300% sát thương phép cho tất cả kẻ địch. Mỗi vòng, hệ số tăng 100%.',
		describe_en = '#L10#Download: #L0#Compare the target\'s dual defense capability before attacking, change the attack style according to its lower-tier items, and increase the corresponding attack power #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; Each insect or mechanical hero beside you increases the damage reward and control immunity rate by 10% \n#F20# \n#F40##L10#Energy Reserve: #L0#The surge of anger accumulates as energy, capped at 300. It transforms into rage before the user acts. Energy is gained first during charge \n#F20# \n#F40##L10#Legion: #L0#Initially follows one soldier (up to two). When the soldier is summoned, 20% of his lost HP is restored. When there are no soldiers for the first time, he will immediately summon 1-2 soldiers \n#F20# \n#F40##L10#Self-Destruct: #L0#When HP reaches 0, it immediately switches to self-destruct mode. It counts down three rounds during which it cannot act. It will explode after a total of 3 active attacks or when the countdown ends. It deals 300% magic damage to all enemies. Each round, the coefficient increases by 100%.',
		describe_th = '#L10#ดาวน์โหลด: #L0#เปรียบเทียบความสามารถป้องกันคู่ของเป้าหมายก่อนโจมตี ปรับเปลี่ยนรูปแบบการโจมตีตามไอเท็มชั้นล่างของมันและเพิ่มพลังโจมตีที่สอดคล้องกัน #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; ฮีโร่แมลงหรือเครื่องจักรแต่ละตัวที่อยู่เคียงข้างคุณจะเพิ่มรางวัลความเสียหายและอัตราป้องกันการถูกควบคุมอีก 10% \n#F20# \n#F40##L10#การสะสมพลังงาน: #L0#ความโกรธที่พุ่งพล่านจะสะสมเป็นพลังงานโดยมีขีดจำกัดสูงสุด 300 พลังงานจะเปลี่ยนเป็นความโกรธก่อนที่ตัวละครจะลงมือทำ พลังงานจะได้รับก่อนในช่วงชาร์จ \n#F20# \n#F40##L10#กองทัพ: #L0#ตอนแรกติดตามทหารหนึ่งคน (สูงสุดสองคน) เมื่อทหารถูกอัญเชิญจะฟื้นฟูเลือดที่เสียไป 20% เมื่อไม่มีทหารเป็นครั้งแรกเขาจะเรียกทหาร 1-2 คนทันที \n#F20# \n#F40##L10#ทำลายตัวเอง: #L0#เมื่อเลือดลดเหลือ 0 มันจะเปลี่ยนเป็นโหมดทำลายตัวเองทันที นับถอยหลังสามรอบในช่วงเวลานี้จะไม่สามารถกระทำการใดๆ ได้ มันจะระเบิดหลังจากโจมตีที่ใช้งานรวม 3 ครั้งหรือเมื่อการนับถอยหลังสิ้นสุดลง สร้างความเสียหายเวทมนตร์ 300% แก่ศัตรูทั้งหมด แต่ละรอบค่าสัมประสิทธิ์เพิ่มขึ้น 100%',
		describe_in = '#L10#Unduh: #L0#Bandingkan kemampuan pertahanan ganda target sebelum menyerang, ubah gaya serangan sesuai dengan item tingkatan bawahnya dan tingkatkan kekuatan serangan yang sesuai #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; Setiap pahlawan serangga atau mekanis di dekatmu akan menambah hadiah kerusakan dan tingkat kekebalan kontrol sebesar 10% \n#F20# \n#F40##L10#Cadangan Energi: #L0#Kemarahan yang menggelegak akan disimpan sebagai energi, dengan batas atas 300. Energi ini akan berubah menjadi amarah sebelum bertindak. Energi diterima terlebih dahulu saat pengisian \n#F20# \n#F40##L10#Legiun: #L0#Awalnya mengikuti satu prajurit (maksimal dua). Saat prajurit dipanggil, 20% HP yang hilang akan pulih. Ketika tidak ada prajurit untuk pertama kalinya, dia akan segera memanggil 1-2 prajurit \n#F20# \n#F40##L10#Melepaskan Diri: #L0#Saat HP mencapai 0, ia langsung beralih ke mode hancur diri. Mode ini menghitung mundur selama tiga putaran dan selama itu tidak dapat bertindak. Ia akan meledak setelah total 3 serangan aktif atau saat hitungan mundur berakhir. Meledakkan damage sihir 300% ke semua musuh. Setiap putaran, koefisien bertambah 100%.',
		describe_ph = '#L10#I-download: #L0#Ihambing ang kakayahan ng doble depensa ng target bago umatake, baguhin ang istilo ng pag-atake ayon sa mababang antas na item nito at dagdagan ang angkop na kapangyarihan ng pag-atake #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; Bawat bayani na insekto o makina sa tabi mo ay nadaragdagan ang gantimpalang pinsala at porsyento ng resistensya sa control ng 10% \n#F20# \n#F40##L10#Reserbang Enerhiya: #L0#Ang sumisiklab na poot ay iniipon bilang enerhiya, na may pinakamataas na limitasyon na 300. Ito ay nagiging poot bago kumilos ang sarili. Enerhiya ang unang natatanggap habang nagcha-charge \n#F20# \n#F40##L10#Legion: #L0#Unang sumusunod sa isang sundalo (hanggang dalawa). Kapag na-summon ang sundalo, makakabawi ito ng 20% ng nawalang HP. Kapag unang walang sundalo, agad itong magse-summon ng 1-2 sundalo \n#F20# \n#F40##L10#Self-Destruct: #L0#Kapag umabot sa 0 ang HP, agad itong lilipat sa self-destruct mode. Magbibilang ito ng tatlong rounds na kung saan ay hindi ito makakagalaw. Mag-eexplote ito pagkatapos ng kabuuang 3 aktibong atake o matapos ang countdown. Magdudulot ito ng 300% magic damage sa lahat ng kalaban. Kada round, tumataas ng 100% ang coefficient.',
		describe_ma = '#L10#Muat turun: #L0#Bandingkan keupayaan pertahanan berganda sasaran sebelum menyerang, ubah gaya serangan mengikut item peringkat rendahnya dan tingkatkan kuasa serangan yang bersesuaian #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; Setiap wira serangga atau mekanikal di sebelah anda akan menambah ganjaran kerosakan dan kadar imuniti kawalan sebanyak 10% \n#F20# \n#F40##L10#Simpanan Tenaga: #L0#Kemarahan yang membuak-buak akan disimpan sebagai tenaga, dengan had atas 300. Ia akan berubah menjadi kemarahan sebelum bertindak. Tenaga diperoleh terlebih dahulu semasa mengecas \n#F20# \n#F40##L10#Legion: #L0#Pada mulanya mengikuti seorang tentera (maksimum dua). Apabila tentera dipanggil, 20% HP yang hilang akan dipulihkan. Apabila tiada tentera buat kali pertama, dia akan segera memanggil 1-2 tentera \n#F20# \n#F40##L10#Pemusnahan Diri: #L0#Apabila HP mencapai 0, ia akan segera beralih ke mod pemusnahan diri. Ia akan mengira undur selama tiga pusingan. Dalam tempoh ini, ia tidak dapat berbuat apa-apa. Ia akan meletup selepas 3 serangan aktif atau apabila pengiraan undur tamat. Ia memberikan 300% kerosakan sihir kepada semua musuh. Setiap pusingan, pekali meningkat 100%.',
		describe = '#L10#Download: #L0#Compare the target\'s dual defense capability before attacking, change the attack style according to its lower-tier items, and increase the corresponding attack power #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#; Each insect or mechanical hero beside you increases the damage reward and control immunity rate by 10% \n#F20# \n#F40##L10#Energy Reserve: #L0#The surge of anger accumulates as energy, capped at 300. It transforms into rage before the user acts. Energy is gained first during charge \n#F20# \n#F40##L10#Legion: #L0#Initially follows one soldier (up to two). When the soldier is summoned, 20% of his lost HP is restored. When there are no soldiers for the first time, he will immediately summon 1-2 soldiers \n#F20# \n#F40##L10#Self-Destruct: #L0#When HP reaches 0, it immediately switches to self-destruct mode. It counts down three rounds during which it cannot act. It will explode after a total of 3 active attacks or when the countdown ends. It deals 300% magic damage to all enemies. Each round, the coefficient increases by 100%.',
		starEffect = __data_t__starEffect[32716],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Số lượng binh lính ban đầu +1; khi vào trận sẽ đầy năng lượng.',
		starEffectDesc = 'Enhance Effect: Initial number of soldiers +1; full energy upon entering the battle.',
