		skillName_ph = 'Matulis na baluti',
		skillName_ma = 'Zirah tajam',
		skillName = 'Sharp armor',
		describe_vn = 'Haric bắn tên lửa hạt dẻ từ trên đầu, tấn công nhanh mục tiêu hàng trước của kẻ địch, gây Sát Thương Vật Lý #C0xE69900#170% Công Vật Lý#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#, tăng 20% tỷ lệ chống chịu và 20% cường độ chống chịu cho bản thân và đồng đội ở ô phía sau, kéo dài hai lượt',
		describe_en = 'Haric fires chestnut rockets from above, quickly attacking the enemy\'s front-row targets, dealing Physical Damage of #C0xE69900#170% Physical Attack#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#. Increases resistance rate and resistance intensity by 20% for yourself and teammates in the back row, lasting for two turns.',
		describe_th = 'Haric ยิงจรวดเชสนัทจากด้านบน โจมตีอย่างรวดเร็วเป้าหมายแถวหน้าของศัตรู ทำให้เกิดความเสียหายทางกายภาพ #C0xE69900#170% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# เพิ่มอัตราการต้านทานและความเข้มข้นของการต้านทานให้กับตัวเองและเพื่อนร่วมทีมในแถวหลัง 20% เป็นเวลาสองรอบ',
		describe_in = 'Haric menembakkan roket kastanye dari atas, menyerang dengan cepat target barisan depan musuh, menyebabkan Kerusakan Fisik sebesar #C0xE69900#170% Serangan Fisik#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#. Meningkatkan tingkat ketahanan dan intensitas ketahanan sebesar 20% untuk diri sendiri dan rekan di barisan belakang, berlangsung selama dua giliran.',
		describe_ph = 'Si Haric ay nagpaputok ng mga kastanyang rocket mula sa itaas, mabilis na ina-atake ang mga target sa unahang hanay ng kaaway, nagdudulot ng Pisikal na Pinsala na #C0xE69900#170% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#. Nagpapataas ng 20% na rate ng resistensya at 20% na intensity ng resistensya para sa sarili at kapwa koponan sa likurang hanay, tumatagal ng dalawang turn.',
		describe_ma = 'Haric menembak peluru berpandu kastanye dari atas, menyerang dengan pantas sasaran barisan hadapan musuh, menyebabkan Kerosakan Fizikal sebanyak #C0xE69900#170% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#. Meningkatkan kadar ketahanan dan intensiti ketahanan sebanyak 20% untuk diri sendiri dan rakan sepasukan di barisan belakang, berlangsung selama dua pusingan.',
		describe = 'Haric fires chestnut rockets from above, quickly attacking the enemy\'s front-row targets, dealing Physical Damage of #C0xE69900#170% Physical Attack#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#. Increases resistance rate and resistance intensity by 20% for yourself and teammates in the back row, lasting for two turns.',
		simDesc_vn = 'Hali Li phóng ra hạt dẻ từ trên đầu, tấn công nhanh vào mục tiêu ở hàng trước của kẻ thù, đồng thời tăng cường khả năng phòng ngự và sức mạnh phòng ngự cho bản thân và hero ở phía sau.',
		simDesc_en = 'Hali Li shoots chestnuts from above, swiftly attacking the enemy\'s front-line target while simultaneously enhancing defense capabilities and defensive strength for herself and the hero behind.',
		simDesc_th = 'ฮาลิ ลี ยิงเกาลัดจากด้านบน โจมตีอย่างรวดเร็วไปยังเป้าหมายแถวหน้าของศัตรู พร้อมเพิ่มความสามารถในการป้องกันและความแข็งแกร่งในการป้องกันให้กับตัวเองและฮีโร่ด้านหลัง',
		simDesc_in = 'Hali Li menembakkan kastanye dari atas kepala, menyerang cepat ke target di barisan depan musuh, sekaligus meningkatkan kemampuan pertahanan dan kekuatan pertahanan untuk dirinya sendiri dan pahlawan di belakang.',
		simDesc_ph = 'Pinaputok ni Hali Li ang mga kastanyas mula sa itaas ng ulo, mabilis na inaatake ang target sa harapang linya ng kalaban, kasabay ng pagpapalakas ng depensa at lakas ng depensa para sa kanyang sarili at ng hero sa likod.',
		simDesc_ma = 'Hali Li melepaskan biji kastanye dari atas kepala, menyerang dengan cepat ke sasaran di barisan hadapan musuh, sambil meningkatkan keupayaan pertahanan dan kekuatan pertahanan untuk dirinya dan wira di belakang.',
		simDesc = 'Hali Li shoots chestnuts from above, swiftly attacking the enemy\'s front-line target while simultaneously enhancing defense capabilities and defensive strength for herself and the hero behind.',
		starEffect = __data_t__starEffect[32813],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi bản thân kích hoạt kháng cự, hồi phục 150% phòng thủ vật lý của bản thân (hiệu ứng kéo dài 3 lượt).',
		starEffectDesc = 'Additional Effect: When activating resistance, recover 150% of your own physical defense (effect lasts for 3 turns).',
		starEffectDesc_en = 'Additional Effect: When activating resistance, recover 150% of your own physical defense (effect lasts for 3 turns).',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อเปิดใช้งานการต้านทาน ฟื้นฟู 150% ของการป้องกันทางกายภาพของตัวเอง (เอฟเฟกต์มีผล 3 เทิร์น)',
		starEffectDesc_in = 'Efek Tambahan: Saat mengaktifkan resistensi, pulihkan 150% pertahanan fisik sendiri (efek berlangsung selama 3 giliran).',
		starEffectDesc_ph = 'Karagdagang Epekto: Kapag na-activate ang resistensya, bumawi ng 150% ng sariling physical defense (epekto tatagal ng 3 rounds).',
		starEffectDesc_ma = 'Kesan Tambahan: Apabila mengaktifkan rintangan, pulihkan 150% pertahanan fizikal sendiri (kesan berlangsung selama 3 pusingan).',
		zawakeEffect = __data_t__zawakeEffect[32813],
		-- {79003}
		zawakeEffectDesc = 'Ha Lili launches a chestnut missile from the top of her head to quickly attack the frontline target, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*34)$ of #C0xF13B54#Physical Damage#C0x5B545B#. A hero standing behind him will increase resistance rate by 20% and resistance power by 20% for three turns.',
		zawakeEffectDesc_en = 'Ha Lili launches a chestnut missile from the top of her head to quickly attack the frontline target, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*34)$ of #C0xF13B54#Physical Damage#C0x5B545B#. A hero standing behind him will increase resistance rate by 20% and resistance power by 20% for three turns.',
		zawakeEffectDesc_th = 'Ha Lili ยิงจรวดเกาลัดจากยอดหัวเพื่อโจมตีเป้าหมายแถวหน้าอย่างรวดเร็ว สร้างความเสียหายทางกายภาพ #C0xE69900#170%#C0x5B545B#+$(skillLevel*4*34)$ ของ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ฮีโร่ที่ยืนอยู่ข้างหลังเขาจะเพิ่มอัตราการต้านทานขึ้น 20% และพลังการต้านทานเพิ่มขึ้น 20% เป็นเวลาสามเทิร์น',
		zawakeEffectDesc_in = 'Ha Lili meluncurkan misil kastanye dari puncak kepalanya untuk menyerang cepat target di garis depan musuh, menyebabkan #C0xE69900#170% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*34)$ dari #C0xF13B54#Kerusakan Fisik#C0x5B545B#. Seorang pahlawan yang berdiri di belakangnya akan meningkatkan tingkat ketahanan sebesar 20% dan kekuatan ketahanan sebesar 20% selama tiga giliran.',
		zawakeEffectDesc_ph = 'Si Ha Lili ay naglunsad ng kastanyas na missile mula sa tuktok ng kanyang ulo upang mabilis na atakihin ang target sa harapang linya ng kalaban, nagdudulot ng #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4*34)$ ng #C0xF13B54#Physical Damage#C0x5B545B#. Ang isang bayani na nakatayo sa likod niya ay magpapataas ng resistance rate ng 20% at resistance power ng 20% sa loob ng tatlong turn.',
		zawakeEffectDesc_ma = 'Ha Lili melancarkan peluru peluncur kacang dari puncak kepalanya untuk menyerang sasaran barisan depan dengan cepat, menyebabkan #C0xE69900#170% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*34)$ daripada #C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Seorang wira yang berdiri di belakangnya akan meningkatkan kadar rintangan sebanyak 20% dan kekuatan rintangan sebanyak 20% selama tiga pusingan.',
		zawakeEffectDesc_vn = 'Ha Lili phóng tên lửa hạt dẻ từ đỉnh đầu tấn công nhanh mục tiêu ở hàng đầu của địch, gây #C0xE69900#170% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*34)$ thuộc #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# . Một anh hùng đứng sau anh ta sẽ tăng tỷ lệ kháng cự lên 20% và sức mạnh kháng cự thêm 20% trong ba hiệp.',
