		skillName_ph = 'Pahalang na hiwa',
		skillName_ma = 'Parutan menegak',
		skillName = 'Vertical slash',
		describe_vn = 'Béo Béo Ha Lực tung cú đấm nhanh từ xa, tấn công mục tiêu hàng trước của kẻ địch, gây ra #C0xE69900#180% Công Vật Lý#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, tăng 20% tỷ lệ chống đỡ và 20% cường độ chống đỡ cho bản thân và anh hùng ở ô phía sau, kéo dài hai lượt',
		describe_en = 'Chubby Ha Lực unleashes a rapid punch from afar, attacking the enemy\'s front-line target, dealing #C0xE69900#180% Physical Attack#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# Physical Damage#C0x5B545B#, increases block rate by 20% and block strength by 20% for himself and the hero in the rear cell, lasting two turns.',
		describe_th = 'ชีบี้ ฮา ลุก ปล่อยหมัดเร็วจากระยะไกล โจมตีเป้าหมายแถวหน้าในฝ่ายศัตรู ก่อให้เกิด #C0xE69900#180% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มอัตราการบล็อก 20% และความแรงการบล็อก 20% ให้กับตัวเองและฮีโร่ในช่องด้านหลัง เป็นเวลาสองรอบ',
		describe_in = 'Béo Béo Ha Lực melancarkan pukulan cepat dari jauh, menyerang target barisan depan musuh, memberikan #C0xE69900#180% Serangan Fisik#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, meningkatkan 20% tingkat blok dan 20% kekuatan blok untuk dirinya sendiri dan pahlawan di sel belakang, berlangsung selama dua giliran.',
		describe_ph = 'Pinatumba ni Béo Béo Ha Lực ang mabilis na suntok mula sa malayo, inaatake ang harapang target ng kalaban, nagdudulot ng #C0xE69900#180% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, nagpapataas ng 20% block rate at 20% block strength para sa sarili at bayani sa likod na posisyon, tumatagal ng dalawang turn.',
		describe_ma = 'Béo Béo Ha Lực melontar tumbukan pantas dari jauh, menyerang sasaran barisan hadapan musuh, menyebabkan #C0xE69900#180% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, meningkatkan 20% kadar blok dan 20% kekuatan blok untuk dirinya dan wira di petak belakang, berlangsung selama dua pusingan.',
		describe = 'Chubby Ha Lực unleashes a rapid punch from afar, attacking the enemy\'s front-line target, dealing #C0xE69900#180% Physical Attack#C0x5B545B#+$(skillLevel*4*34)$ #C0xF13B54# Physical Damage#C0x5B545B#, increases block rate by 20% and block strength by 20% for himself and the hero in the rear cell, lasting two turns.',
		simDesc_vn = 'Hali Li mập mạp lao tới mục tiêu ở hàng trước của kẻ thù bằng một cú đấm nhanh, tăng cường khả năng phòng ngự và sức mạnh phòng ngự cho bản thân và hero ở phía sau.',
		simDesc_en = 'Hali Li, chubby, lunged at the frontline enemy with a quick punch, boosting defense ability and defensive power for herself and the hero behind.',
		simDesc_th = 'ฮาลิ ลี ตัวอ้วนพุ่งเข้าสู่เป้าหมายแถวหน้าอย่างรวดเร็วด้วยหมัดหนึ่งที เพิ่มความสามารถในการป้องกันและพลังป้องกันให้กับตัวเองและฮีโร่ด้านหลัง',
		simDesc_in = 'Hali Li yang gemuk melompat ke sasaran di barisan depan musuh dengan pukulan cepat, meningkatkan kemampuan pertahanan dan kekuatan pertahanan untuk dirinya sendiri dan pahlawan di belakangnya.',
		simDesc_ph = 'Si matabang na si Hali Li ay sumugod sa target sa unahang hanay ng kalaban gamit ang mabilis na suntok, pinapalakas ang kakayahan sa depensa at lakas ng depensa para sa kanyang sarili at ang bayani sa likod.',
		simDesc_ma = 'Hali Li yang gemuk meluru ke sasaran di barisan hadapan musuh dengan satu pukulan pantas, meningkatkan keupayaan pertahanan dan kuasa pertahanan untuk dirinya sendiri dan wira di belakang.',
		simDesc = 'Hali Li, chubby, lunged at the frontline enemy with a quick punch, boosting defense ability and defensive power for herself and the hero behind.',
		starEffect = __data_t__starEffect[32823],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi bản thân kích hoạt kháng cự, hồi phục 150% phòng thủ vật lý của bản thân (hiệu ứng kéo dài 3 lượt).',
		starEffectDesc = 'Additional effect: When activating resistance, recover 150% of own physical defense (effect lasts 3 turns).',
		starEffectDesc_en = 'Additional effect: When activating resistance, recover 150% of own physical defense (effect lasts 3 turns).',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อเปิดใช้งานการต้านทาน ฟื้นฟูค่าป้องกันทางกายภาพของตัวเอง 150% (เอฟเฟกต์คงอยู่ 3 เทิร์น)',
		starEffectDesc_in = 'Efek tambahan: Saat mengaktifkan ketahanan, pulihkan 150% pertahanan fisik sendiri (efek berlangsung selama 3 giliran).',
		starEffectDesc_ph = 'Karagdagang epekto: Kapag na-activate ang resistensya, mag-recover ng 150% ng sariling physical defense (ang epekto ay tumatagal ng 3 turn).',
		starEffectDesc_ma = 'Kesan tambahan: Apabila mengaktifkan ketahanan, pulihkan 150% pertahanan fizikal sendiri (kesan berlangsung selama 3 pusingan).',
		zawakeEffect = __data_t__zawakeEffect[32823],
		-- {79003}
		zawakeEffectDesc = 'Fat Hali delivers a fast punch from afar, attacking the target in the front row of the enemy, causing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#Physical Damage#C0x5B545B#. Increases resistance rate and resistance strength by 20% for yourself and the hero behind you for three turns.',
		zawakeEffectDesc_en = 'Fat Hali delivers a fast punch from afar, attacking the target in the front row of the enemy, causing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#Physical Damage#C0x5B545B#. Increases resistance rate and resistance strength by 20% for yourself and the hero behind you for three turns.',
		zawakeEffectDesc_th = 'แฟต ฮาลิ ยิงหมัดเร็วจากระยะไกล โจมตีเป้าหมายแถวหน้าของศัตรู สร้าง #C0xE69900#180% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ให้ตัวเองและฮีโร่ด้านหลังของคุณ เพิ่มอัตราต้านทานและความแข็งแกร่งในการต้านทานขึ้น 20% เป็นเวลาสามเทิร์น',
		zawakeEffectDesc_in = 'Fat Hali melakukan pukulan cepat dari jauh, menyerang target di barisan depan musuh, menyebabkan #C0xE69900#180% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#Kerusakan Fisik#C0x5B545B#. Memberikan diri sendiri dan Pahlawan di belakang Anda, meningkatkan tingkat resistensi dan kekuatan resistensi sebesar 20% selama tiga giliran.',
		zawakeEffectDesc_ph = 'Ang Fat Hali ay nagsagawa ng mabilis na suntok mula sa malayo, inaatake ang target sa unang hanay ng kalaban, dahilan ng #C0xE69900#180% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Sa sarili at sa Bayani sa likod mo, tumaas ang rate ng resistensya at lakas ng resistensya ng 20% sa loob ng tatlong turn.',
		zawakeEffectDesc_ma = 'Fat Hali melakukan tumbukan pantas dari jauh, menyerang sasaran di barisan hadapan musuh, menyebabkan #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Untuk diri sendiri dan Wira di belakang anda, meningkatkan kadar ketahanan dan kekuatan ketahanan sebanyak 20% selama tiga pusingan.',
		zawakeEffectDesc_vn = 'Fat Hali tung cú đấm nhanh từ xa, tấn công mục tiêu ở hàng đầu của kẻ địch, gây #C0xE69900#180% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, Cho bản thân và Người anh hùng phía sau bạn, tăng tỷ lệ kháng cự và sức mạnh kháng cự lên 20% và 20% trong ba hiệp.',
