	[33022] = {
		id = 33022,
		skillName_vn = 'Đánh lén',
		skillName_en = 'Sneak attack',
		skillName_th = 'โจมตีแบบลับ ๆ',
		skillName_in = 'Serangan diam-diam',
		skillName_ph = 'Palihim na pag-atake',
		skillName_ma = 'Serangan secara sembunyi-sembunyi',
		skillName = 'Sneak attack',
		describe_vn = 'Ếch Đầu Nấm lập tức dịch chuyển ra sau mục tiêu đơn lẻ của kẻ địch, sau đó nhanh chóng chém liên tiếp, gây ra #C0x3D8A99#150% Phép Công#C0x5B545B#+$(skillLevel*4*48)$ Sát Thương Phép Thuật #C0xF13B54##C0x5B545B#, cướp 10% tốc độ của kẻ địch, kéo dài 3 lượt; có 50% xác suất [choáng] mục tiêu trong 1 lượt (choáng: hiệu ứng khống chế, không thể hành động), nếu tốc độ của mục tiêu nhanh hơn bản thân, chắc chắn sẽ bị choáng trong 1 lượt',
		describe_en = 'Frog Mushroom instantly teleports behind a single enemy target, then swiftly strikes repeatedly, dealing #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ Magic Damage #C0xF13B54##C0x5B545B#, stealing 10% of the enemy\'s speed for 3 turns; has a 50% chance to [stun] the target for 1 turn (stun: control effect, target cannot act), if the target\'s speed is higher than the user\'s, the target is guaranteed to be stunned for 1 turn.',
		describe_th = 'กบเห็ดเคลื่อนที่ทันทีไปยังเป้าหมายศัตรูเดี่ยวด้านหลัง จากนั้นฟันต่อเนื่องอย่างรวดเร็ว สร้างความเสียหายเวทย์ #C0x3D8A99#150% พลังโจมตีเวทย์#C0x5B545B#+$(skillLevel*4*48)$ ความเสียหายเวทย์ #C0xF13B54##C0x5B545B#; ขโมยความเร็วของศัตรู 10% เป็นเวลา 3 เทิร์น มีโอกาส 50% ที่จะ[ทำให้เป้าหมายมึนงง]เป็นเวลา 1 เทิร์น (มึนงง: สถานะควบคุม ไม่สามารถกระทำการได้) หากความเร็วของเป้าหมายเร็วกว่าผู้ใช้ จะติดมึนงงแน่นอนเป็นเวลา 1 เทิร์น',
		describe_in = 'Katak Jamur segera berpindah ke belakang target musuh tunggal, kemudian dengan cepat melakukan serangan beruntun, memberikan #C0x3D8A99#150% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ Kerusakan Sihir #C0xF13B54##C0x5B545B#, mencuri 10% kecepatan musuh selama 3 giliran; memiliki 50% peluang untuk [membuat target terkejut] selama 1 giliran (terkejut: efek kontrol, target tidak dapat bertindak), jika kecepatan target lebih tinggi dari pengguna, target dijamin terkejut selama 1 giliran.',
		describe_ph = 'Agad na lumipat ang Mushroom Frog sa likod ng isang kalabang target, pagkatapos ay mabilis na sumalakay ng sunud-sunod, nagdudulot ng #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ Magic Damage #C0xF13B54##C0x5B545B#, kinukuha ang 10% bilis ng kalaban sa loob ng 3 turn; may 50% tsansa na [ma-stun] ang target sa loob ng 1 turn (stun: control effect, hindi makakagawa ng aksyon ang target), kung ang bilis ng target ay mas mabilis kaysa sa gumagamit, tiyak na ma-stun ito sa loob ng 1 turn.',
		describe_ma = 'Katak Cendawan segera berpindah ke belakang sasaran musuh tunggal, kemudian dengan pantas menyerang berturut-turut, menyebabkan #C0x3D8A99#150% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ Kerosakan Sihir #C0xF13B54##C0x5B545B#, mencuri 10% kelajuan musuh selama 3 pusingan; mempunyai peluang 50% untuk [membuat sasaran pening] selama 1 pusingan (pening: kesan kawalan, sasaran tidak dapat bertindak), jika kelajuan sasaran lebih cepat daripada pengguna, sasaran pasti akan pening selama 1 pusingan.',
		describe = 'Frog Mushroom instantly teleports behind a single enemy target, then swiftly strikes repeatedly, dealing #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ Magic Damage #C0xF13B54##C0x5B545B#, stealing 10% of the enemy\'s speed for 3 turns; has a 50% chance to [stun] the target for 1 turn (stun: control effect, target cannot act), if the target\'s speed is higher than the user\'s, the target is guaranteed to be stunned for 1 turn.',
		simDesc_vn = 'Quack Đầu Ếch tức thì di chuyển đến sau lưng mục tiêu đơn lẻ của kẻ thù rồi nhanh chóng thực hiện liên hoàn chém vào kẻ thù.',
		simDesc_en = 'Quack Frog Head instantly teleports behind a single enemy target and quickly performs a series of consecutive slashes on the enemy.',
		simDesc_th = 'Quack หัวกบ เคลื่อนย้ายทันทีไปยังด้านหลังเป้าหมายศัตรูเดี่ยว แล้วโจมตีด้วยการฟันติดต่อกันอย่างรวดเร็ว',
		simDesc_in = 'Quack Kepala Katak segera berpindah ke belakang satu target musuh dan dengan cepat melakukan serangkaian tebasan berturut-turut pada musuh tersebut.',
		simDesc_ph = 'Agad na lumilipat ang Quack Ulo ng Palaka sa likod ng isang target na kaaway at mabilis na nagsasagawa ng sunud-sunod na mga hiwa sa kaaway.',
		simDesc_ma = 'Quack Kepala Katak segera berpindah di belakang sasaran musuh tunggal dan dengan pantas melaksanakan rentetan belahan berterusan ke atas musuh tersebut.',
		simDesc = 'Quack Frog Head instantly teleports behind a single enemy target and quickly performs a series of consecutive slashes on the enemy.',
