		-- {79001}
		zawakeEffectDesc = '#C0xC0C0C0#Like water—formless yet powerful#C0x5B545B#\n#F10#\n#F40#Arale condenses a small water shuriken and quickly throws it at a single enemy target (prioritizing the slowest), dealing #C0x3D8A99#100% magic damage#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#special damage#C0x5B545B#, stealing 10% of the target’s speed and 10% of their magic damage, while increasing Water resistance by 10% (stackable up to 3 times), lasting for 3 turns',
		zawakeEffectDesc_en = '#C0xC0C0C0#Like water—formless yet powerful#C0x5B545B#\n#F10#\n#F40#Arale condenses a small water shuriken and quickly throws it at a single enemy target (prioritizing the slowest), dealing #C0x3D8A99#100% magic damage#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#special damage#C0x5B545B#, stealing 10% of the target’s speed and 10% of their magic damage, while increasing Water resistance by 10% (stackable up to 3 times), lasting for 3 turns',
		zawakeEffectDesc_th = 'สิงโตน้อยใช้มือฟาดเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#90%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# เพิ่มความเสียหายเวทมนตร์ของตัวเองอีก 10 รอบ %2',
		zawakeEffectDesc_in = 'Singa kecil menggunakan tangan untuk menampar satu target musuh, menyebabkan #C0x3D8A99#90% Kerusakan Magic#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerusakan Magic#C0x5B545B#, meningkatkan Kerusakan Magic miliknya sendiri selama 10 putaran %2',
		zawakeEffectDesc_ph = 'Ang maliit na leon ay gumagamit ng kamay upang palmutin ang isang target na kalaban, na nagdudulot ng #C0x3D8A99#90% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magical Damage#C0x5B545B#, pinapataas ang sariling Magical Damage nito ng 10 rounds %2',
		zawakeEffectDesc_ma = 'Singa kecil menggunakan tangan untuk menampar satu sasaran musuh, menyebabkan #C0x3D8A99#90% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerosakan Magik#C0x5B545B#, menambah Kerosakan Magik dirinya sendiri sebanyak 10 pusingan %2',
		zawakeEffectDesc_vn = '#C0xC0C0C0#Giống như nước, vô hình nhưng lại mạnh mẽ#C0x5B545B#\n#F10#\n#F40#Arale ngưng tụ một thủy thủ rikens nhỏ và nhanh chóng ném nó vào một mục tiêu địch duy nhất (ưu tiên tấn công chậm nhất), gây #C0x3D8A99#100% sát thương phép#C0x5B545B#+$(cấp độ kỹ năng*4*24)$ #C0xF13B54#sát thương đặc biệt#C0x5B545B#, đánh cắp 10% tốc độ của mục tiêu và 10% sát thương phép của mục tiêu, đồng thời tăng thêm 10% khả năng chống chịu hệ nước (có thể cộng dồn 3 lần), kéo dài trong 3 lượt',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Steals 10% of the target\'s Speed and adds 10% Water Resistance (can stack up to 3 times), lasts 2 turns\n#F10#\n#F40##C0x5c9970#Steals 10% of the target\'s Speed and 10% Magic ATK, and adds 10% Water Resistance (can stack up to 3 times), lasts 3 turns',
		zawakeSimpleDesc_en = 'Steals 10% of the target\'s Speed and adds 10% Water Resistance (can stack up to 3 times), lasts 2 turns\n#F10#\n#F40##C0x5c9970#Steals 10% of the target\'s Speed and 10% Magic ATK, and adds 10% Water Resistance (can stack up to 3 times), lasts 3 turns',
		zawakeSimpleDesc_th = 'ขโมยความเร็วของเป้าหมาย 10% และเพิ่มพลังต้านทานน้ำ 10% (สะสมได้สูงสุด 3 ครั้ง) มีผล 2 เทิร์น\n#F10#\n#F40##C0x5c9970#ขโมยความเร็ว 10% และพลังเวทโจมตี 10% จากเป้าหมาย และเพิ่มพลังต้านทานน้ำ 10% (สะสมได้สูงสุด 3 ครั้ง) มีผล 3 เทิร์น',
		zawakeSimpleDesc_in = 'Mencuri 10% Kecepatan target dan menambahkan 10% Resistensi Air (bisa ditumpuk hingga 3 kali), berlangsung selama 2 giliran\n#F10#\n#F40##C0x5c9970#Mencuri 10% Kecepatan dan 10% Serangan Sihir target, serta menambahkan 10% Resistensi Air (bisa ditumpuk hingga 3 kali), berlangsung selama 3 giliran',
		zawakeSimpleDesc_ph = 'Ninanakaw ang 10% Speed ng target at nagdadagdag ng 10% Water Resistance (maaaring ma-stack hanggang 3 beses), tumatagal ng 2 turn\n#F10#\n#F40##C0x5c9970#Ninanakaw ang 10% Speed at 10% Magic ATK ng target at nagdadagdag ng 10% Water Resistance (maaaring ma-stack hanggang 3 beses), tumatagal ng 3 turn',
		zawakeSimpleDesc_ma = 'Mencuri 10% Kelajuan sasaran dan menambah 10% Rintangan Air (boleh ditindih sehingga 3 kali), bertahan selama 2 pusingan\n#F10#\n#F40##C0x5c9970#Mencuri 10% Kelajuan dan 10% Serangan Magik sasaran serta menambah 10% Rintangan Air (boleh ditindih sehingga 3 kali), bertahan selama 3 pusingan',
		zawakeSimpleDesc_vn = 'Đánh cắp 10% tốc độ của mục tiêu và thêm 10% khả năng kháng nước (có thể cộng dồn 3 lần), kéo dài 2 lượt\n#F10#\n#F40##C0x5c9970#Đánh cắp 10% tốc độ của mục tiêu và 10% đòn tấn công phép thuật và thêm 10% khả năng kháng nước (có thể cộng dồn 3 lần), kéo dài 3 lượt',
