	[33042] = {
		id = 33042,
		skillName_vn = 'Liệt Phong Nha',
		skillName_en = 'Fierce Wind Fang',
		skillName_th = 'เขี้ยวลมพายุ',
		skillName_in = 'Taring Angin Mengerikan',
		skillName_ph = 'Pangil ng Malupit na Hangin',
		skillName_ma = 'Taring Angin Ganas',
		skillName = 'Residual Firewave',
		describe_vn = 'Arale tập hợp năng lượng và đá một mục tiêu địch duy nhất một cách dữ dội (ưu tiên tấn công mục tiêu chậm nhất), gây ra #C0x3D8A99#380% sát thương phép #C0x5B545B#+$(skillLevel*4*48)$ hoặc #C0xF13B54# sát thương phép #C0x5B545B#, 100% cơ hội <làm choáng> mục tiêu trong 1 lượt và xóa bỏ 1 trong các hiệu ứng tăng cường của mục tiêu đó. Nếu không có buff nào để giải trừ hoặc mục tiêu có debuff loại tốc độ, <đẩy lùi> mục tiêu trong 2 lượt, và có xác suất bằng tỷ lệ chênh lệch tốc độ * số lượng kẻ địch (lần đầu sẽ kích hoạt vào lần sau) Đặt một <Phân thân Ninja Siêu cấp> thay thế tại vị trí ban đầu, ẩn mình và không thể bị kẻ địch chọn, khi Phân thân Ninja Siêu cấp bị tiêu diệt, bản thể chính sẽ ngay lập tức xuất hiện\n#F10#\n#F40##L10#Đẩy lùi: #L0#Đặt mục tiêu vào cuối thanh hành động, nếu đã ở cuối, sẽ giảm 200 điểm nộ\n#F10#\n#F40##L10#Phân thân Ninja Siêu cấp:​​#L0# Kế thừa 40% thuộc tính của bản thân, sẽ kháng cự và chia sẻ toàn bộ sát thương thụ động mà bản thể chính phải chịu, Phân thân Ninja Siêu cấp biến mất sau khi bị tấn công một lần hoặc chịu sát thương thụ động quá mức',
		describe_en = 'Arale gathers energy and fiercely kicks a single enemy target (prioritizing the slowest one), dealing #C0x3D8A99#380% magic damage#C0x5B545B#+$(skillLevel*4*48)$ or #C0xF13B54#magic damage#C0x5B545B#, with a 100% chance to <stun> the target for 1 turn and remove 1 of its buffs. If there is no buff to dispel or the target has a speed-type debuff, <push back> the target for 2 turns with a success rate based on speed difference * number of enemies (triggers on next hit if not triggered the first time). Summons a <Super Ninja Clone> at the original position, becoming hidden and unselectable by enemies. When the Super Ninja Clone is defeated, the original body instantly reappears.\n#F10#\n#F40##L10#Push Back: #L0#Moves the target to the end of the action bar; if already at the end, reduces 200 rage points.\n#F10#\n#F40##L10#Super Ninja Clone: #L0#Inherits 40% of Arale\'s attributes, resists and shares all passive damage intended for the original body, disappears after one hit or after taking excessive passive damage.',
		describe_th = 'อาราเล่รวบรวมพลังงานและเตะใส่เป้าหมายศัตรูหนึ่งตัวอย่างรุนแรง (เน้นเป้าหมายที่ช้าที่สุด) สร้างความเสียหายเวท #C0x3D8A99#380%#C0x5B545B#+$(skillLevel*4*48)$ หรือ #C0xF13B54#ความเสียหายเวท#C0x5B545B# มีโอกาส 100% ที่จะ <สตั๊น> เป้าหมายเป็นเวลา 1 เทิร์น และลบ 1 บัฟของเป้าหมาย หากไม่มีบัฟให้ลบหรือเป้าหมายมีดีบัฟประเภทความเร็ว จะ <ผลักกลับ> เป้าหมายเป็นเวลา 2 เทิร์น โดยมีโอกาสสำเร็จตามอัตราส่วนความเร็ว * จำนวนศัตรู (หากไม่สำเร็จครั้งแรก จะทำงานในการโจมตีถัดไป) สร้าง <ร่างแยกนินจาสุดยอด> แทนที่ในตำแหน่งเดิม ล่องหนและไม่สามารถถูกเลือกโดยศัตรูได้ เมื่อร่างแยกถูกทำลาย ร่างจริงจะปรากฏตัวทันที\n#F10#\n#F40##L10#ผลักกลับ: #L0#ส่งเป้าหมายไปยังท้ายแถบการกระทำ หากอยู่ท้ายแล้วจะลด 200 แต้มความโกรธ\n#F10#\n#F40##L10#ร่างแยกนินจาสุดยอด: #L0#สืบทอด 40% ค่าสถานะของตัวเอง ต้านทานและแบ่งความเสียหายแบบพาสซีฟทั้งหมดจากร่างจริง ร่างแยกจะหายไปหลังจากถูกโจมตีหนึ่งครั้งหรือรับความเสียหายพาสซีฟมากเกินไป',
		describe_in = 'Arale mengumpulkan energi dan menendang satu target musuh dengan dahsyat (mengutamakan target paling lambat), memberikan #C0x3D8A99#380% magic damage#C0x5B545B#+$(skillLevel*4*48)$ atau #C0xF13B54#magic damage#C0x5B545B#, dengan 100% peluang untuk <stun> target selama 1 giliran dan menghapus 1 efek peningkatan dari target. Jika tidak ada buff untuk dihapus atau target memiliki debuff jenis kecepatan, <dorong mundur> target selama 2 giliran, dengan peluang keberhasilan berdasarkan selisih kecepatan * jumlah musuh (akan aktif di serangan berikutnya jika gagal pertama kali). Memanggil <Clone Ninja Super> di posisi semula, menjadi tersembunyi dan tidak bisa dipilih oleh musuh. Ketika Clone Ninja Super dikalahkan, tubuh asli langsung muncul kembali.\n#F10#\n#F40##L10#Dorong Mundur: #L0#Memindahkan target ke akhir bar aksi, jika sudah di akhir maka akan mengurangi 200 poin amarah\n#F10#\n#F40##L10#Clone Ninja Super: #L0#Mewarisi 40% atribut Arale, menahan dan berbagi seluruh damage pasif yang ditujukan ke tubuh asli, menghilang setelah terkena satu serangan atau menerima terlalu banyak damage pasif.',
		describe_ph = 'Si Arale ay nag-iipon ng enerhiya at malakas na sinisipa ang isang kalabang target (inuuna ang pinaka-mabagal), nagdudulot ng #C0x3D8A99#380% magic damage#C0x5B545B#+$(skillLevel*4*48)$ o #C0xF13B54#magic damage#C0x5B545B#, may 100% tsansa na <i-stun> ang target sa loob ng 1 turn at tanggalin ang isa sa mga buff nito. Kung walang buff na maalis o may debuff sa bilis, <itulak paatras> ang target sa loob ng 2 turn, may tsansang aktibasyon batay sa agwat ng bilis * bilang ng kalaban (kung hindi gumana sa unang beses, gagalaw sa susunod na atake). Nagsusumon ng <Super Ninja Clone> sa orihinal na posisyon, nagiging invisible at hindi mapipili ng kalaban. Kapag ang Super Ninja Clone ay natalo, ang orihinal na katawan ay agad lilitaw.\n#F10#\n#F40##L10#Itulak Paatras: #L0#Inililipat ang target sa dulo ng action bar; kung nasa dulo na, babawasan ng 200 rage points\n#F10#\n#F40##L10#Super Ninja Clone: #L0#Namamana ang 40% ng stats ni Arale, lumalaban at pinaghahatian ang lahat ng passive damage para sa orihinal na katawan, mawawala matapos tamaan o makatanggap ng sobrang passive damage.',
		describe_ma = 'Arale mengumpul tenaga dan menendang satu sasaran musuh dengan kuat (mengutamakan sasaran paling perlahan), memberikan #C0x3D8A99#380% kerosakan sihir#C0x5B545B#+$(skillLevel*4*48)$ atau #C0xF13B54#kerosakan sihir#C0x5B545B#, dengan 100% peluang untuk <stun> sasaran selama 1 giliran dan menghapus satu buff dari sasaran tersebut. Jika tiada buff untuk dihapus atau sasaran mempunyai debuff jenis kelajuan, akan <tolak ke belakang> sasaran selama 2 giliran, dengan kadar kejayaan berdasarkan perbezaan kelajuan * bilangan musuh (akan diaktifkan pada serangan seterusnya jika tidak berjaya kali pertama). Memanggil <Klon Ninja Super> di kedudukan asal, menjadi tersembunyi dan tidak boleh dipilih oleh musuh. Apabila Klon Ninja Super dikalahkan, tubuh asal akan muncul serta-merta.\n#F10#\n#F40##L10#Tolak ke Belakang: #L0#Memindahkan sasaran ke hujung bar tindakan, jika sudah di hujung, akan mengurangkan 200 mata kemarahan\n#F10#\n#F40##L10#Klon Ninja Super: #L0#Mewarisi 40% atribut Arale, menahan dan berkongsi semua kerosakan pasif yang sepatutnya diterima oleh tubuh asal, hilang selepas diserang sekali atau menerima kerosakan pasif berlebihan.',
		describe = 'Little Sifu spits a wave of fire, attacking a single enemy target, dealing #C0x3D8A99#140% Magic Power#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, reducing the target\'s critical resistance by 10% for 3 turns.',
		simDesc_en = 'Little Lion sprays a wave of fire, attacking a single enemy target.',
		simDesc_in = 'Singamuda menyemburkan gelombang api, menyerang satu target musuh.',
		simDesc_ph = 'Ang Munting Leon ay humihip ng alon ng apoy, sumusugod sa isang kalaban na target.',
		simDesc_ma = 'Singa Kecil menyembur gelombang api, menyerang satu sasaran musuh.',
