		zawakeEffect = __data_t__zawakeEffect[33042],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#The wise have no doubts, thus they are invincible! #C0x5B545B#\n#F10#\n#F40#A water Kunai blade condenses in Arale’s hand, quickly dashing forward and slashing a single enemy target (prioritizing the slowest), dealing #C0x3D8A99#180% magic damage #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#special damage #C0x5B545B#, with a 100% chance to <Stun> the target for 1 turn and remove 1 of their buffs. If there’s no buff to remove or the target has a speed-type debuff, <Push Back> the target for 2 turns, with a chance based on speed difference × number of enemies (must be triggered the first time). Summons a <Super Clone> at the same location to substitute, hidden and untargetable. When the Super Clone is defeated, the real body appears instantly.\n#F10#\n#F40##L10#Push Back: #L0#Places the target at the end of the action bar. If already at the end, reduces 200 rage points.\n#F10#\n#F40##L10#Super Clone: ​​#L0#Inherits 60% of its own stats and resists all passive damage directed at the main body. The Super Clone disappears after taking one attack or excessive passive damage. Upon being defeated, another clone appears instantly, counterattacking the attacker with normal attacks and has a 50% chance to Stun the attacker for 1 turn.',
		zawakeEffectDesc_en = '#C0xC0C0C0#The wise have no doubts, thus they are invincible! #C0x5B545B#\n#F10#\n#F40#A water Kunai blade condenses in Arale’s hand, quickly dashing forward and slashing a single enemy target (prioritizing the slowest), dealing #C0x3D8A99#180% magic damage #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#special damage #C0x5B545B#, with a 100% chance to <Stun> the target for 1 turn and remove 1 of their buffs. If there’s no buff to remove or the target has a speed-type debuff, <Push Back> the target for 2 turns, with a chance based on speed difference × number of enemies (must be triggered the first time). Summons a <Super Clone> at the same location to substitute, hidden and untargetable. When the Super Clone is defeated, the real body appears instantly.\n#F10#\n#F40##L10#Push Back: #L0#Places the target at the end of the action bar. If already at the end, reduces 200 rage points.\n#F10#\n#F40##L10#Super Clone: ​​#L0#Inherits 60% of its own stats and resists all passive damage directed at the main body. The Super Clone disappears after taking one attack or excessive passive damage. Upon being defeated, another clone appears instantly, counterattacking the attacker with normal attacks and has a 50% chance to Stun the attacker for 1 turn.',
		zawakeEffectDesc_th = 'สิงโตน้อยปล่อยคลื่นไฟโจมตีเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหาย #C0x3D8A99#140% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# ลดความต้านทานของเป้าหมาย 15% เป็นเวลา 3 เทิร์น',
		zawakeEffectDesc_in = 'Singa kecil melepaskan gelombang api yang menyerang satu target musuh, memberikan #C0x3D8A99#140% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#Kerusakan Magis#C0x5B545B#, mengurangi resistensi target sebesar 15% selama 3 giliran',
		zawakeEffectDesc_ph = 'Ang maliit na leon ay nagpapalabas ng isang alon ng apoy na umaatake sa isang kaaway na target, nagdudulot ng #C0x3D8A99#140% Pinsalang Mahika#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#Pinsalang Mahika#C0x5B545B#, nagpapababa ng resistensya ng target ng 15% sa loob ng 3 na turn',
		zawakeEffectDesc_ma = 'Singa kecil melepaskan gelombang api yang menyerang satu sasaran musuh, menyebabkan #C0x3D8A99#140% Kerosakan Ajaib#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#Kerosakan Ajaib#C0x5B545B#, mengurangkan ketahanan sasaran sebanyak 15% selama 3 pusingan',
		zawakeEffectDesc_vn = '#C0xC0C0C0#Người khôn ngoan không nghi ngờ,  thì bất khả chiến bại! #C0x5B545B#\n#F10#\n#F40#Một lưỡi kiếm nước Kunai ngưng tụ trong tay Arale, nhanh chóng lao tới và chém để tấn công một mục tiêu địch duy nhất (ưu tiên tấn công mục tiêu chậm nhất), gây #C0x3D8A99#180% sát thương phép #C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#sát thương đặc biệt #C0x5B545B#, 100% khả năng <làm choáng> mục tiêu trong 1 hiệp và xóa bỏ 1 trong các hiệu ứng tăng cường của mục tiêu đó. Nếu không có buff nào để giải trừ hoặc mục tiêu có debuff loại tốc độ, <đẩy lùi> mục tiêu trong 2 hiệp và có xác suất bằng tỷ lệ chênh lệch tốc độ * số lượng kẻ địch (lần đầu tiên phải được Kích hoạt) Đặt một <Bản sao Siêu Cấp> ​​làm vật thay thế tại cùng một vị trí, ẩn mình và không thể bị kẻ địch chọn. Khi Bản sao Siêu Cấp bị tiêu diệt, cơ thể chính sẽ ngay lập tức xuất hiện.\n#F10#\n#F40##L10#Đẩy lùi: #L0#Đặt mục tiêu vào cuối thanh hành động. Nếu đã ở cuối, nó sẽ giảm 200 điểm nộ.\n#F10#\n#F40##L10#Bản sao Siêu Cấp: ​​#L0#Kế thừa 60% thuộc tính của chính nó và sẽ kháng mọi sát thương thụ động lên cơ thể chính. Bản sao Siêu Cấp biến mất sau khi bị tấn công một lần hoặc chịu sát thương thụ động quá mức. Khi bị tiêu diệt, phiên bản khác sẽ ngay lập tức xuất hiện, phản công kẻ tấn công bằng các đòn tấn công thông thường và có 50% cơ hội làm choáng kẻ tấn công trong 1 hiệp.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'The Super Clone inherits 60% of attributes. When destroyed, Arale will immediately appear and counterattack the attacker with normal attacks, with a 50% chance to stun the attacker for 1 turn.',
		zawakeSimpleDesc_en = 'The Super Clone inherits 60% of attributes. When destroyed, Arale will immediately appear and counterattack the attacker with normal attacks, with a 50% chance to stun the attacker for 1 turn.',
		zawakeSimpleDesc_th = 'โคลนซุปเปอร์จะสืบทอดคุณสมบัติ 60% เมื่อถูกทำลาย Arale จะปรากฏตัวทันทีและโต้กลับศัตรูด้วยการโจมตีปกติ และมีโอกาส 50% ที่จะทำให้ศัตรูติดสถานะมึนงง 1 เทิร์น',
		zawakeSimpleDesc_in = 'Salinan Super mewarisi 60% atribut. Saat dihancurkan, Arale akan langsung muncul dan melakukan serangan balik ke penyerang dengan serangan biasa, dengan 50% peluang untuk membuat musuh terkena stun selama 1 giliran.',
		zawakeSimpleDesc_ph = 'Ang Super Clone ay namamana ng 60% ng mga stats. Kapag nasira, agad na lilitaw si Arale at aatakehin ang kalaban gamit ang normal attack, may 50% tsansang ma-stun ang kalaban ng 1 turn.',
		zawakeSimpleDesc_ma = 'Salinan Super mewarisi 60% atribut. Apabila dimusnahkan, Arale akan muncul serta-merta dan menyerang balas penyerang dengan serangan biasa, dengan 50% peluang untuk menyebabkan Stun selama 1 pusingan.',
		zawakeSimpleDesc_vn = 'Bản sao Siêu Cấp thừa hưởng 60% thuộc tính. Khi bị phá hủy, Arale sẽ ngay lập tức xuất hiện, phản công kẻ tấn công bằng các đòn tấn công thông thường và có 50% cơ hội làm choáng kẻ tấn công trong 1 hiệp.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
		upLvDesc_in = 'Kerusakan tetap +192',
		upLvDesc_ph = 'Fixed na pinsala +192',
		upLvDesc_ma = 'Kerosakan tetap +192',
