	[33043] = {
		id = 33043,
		skillName_vn = 'Võ Thần Cước',
		skillName_en = 'Martial God Kick',
		skillName_th = 'ลูกเตะเทพสงคราม',
		skillName_in = 'Tendangan Dewa Bela Diri',
		skillName_ph = 'Sipa ng Diyos ng Pakikidigma',
		skillName_ma = 'Tendangan Dewa Peperangan',
		skillName = 'Lava attack',
		describe_vn = 'Arale kích hoạt chiêu cuối của mình, kết hợp Nhẫn thuật với Khí công, thực hiện một cú Võ Thần Cước vào một mục tiêu địch duy nhất (ưu tiên tấn công mục tiêu tốc chậm nhất), đánh cắp 30% tỷ lệ bạo kích của mục tiêu và 40% sát thương bạo kích trong 2 lượt, gây #C0x3D8A99#780% sát thương phép#C0x5B545B#+$(skillLevel*4*90)$ trong #C0xF13B54# sát thương phép#C0x5B545B#, với 30% hút máu. Nếu tốc độ của mục tiêu thấp hơn tốc độ của chính mình 40% trở lên hoặc sau đòn tấn công này Nếu máu của mục tiêu dưới 10% (bao gồm cả khi chết), một <Thiên Sát Băng Sơn> bổ sung sẽ được thêm vào tất cả kẻ địch (giới hạn 2 lần kích hoạt)\n#F10#\n#F40##C0x4682B4##L10#Thiên Sát Băng Sơn: Gây sát thương chuẩn là #C0x3D8A99#100% công kích phép thuật#C0x5B545B#+10% giới hạn máu của mục tiêu lên tất cả kẻ địch #L0##C0x5B545B# (tối đa 1000% công kích phép thuật của chính mục tiêu), tăng gấp đôi sát thương lên quái vật ngục tối và chắc chắn sẽ được kích hoạt',
		describe_en = 'Arale activates her ultimate skill, combining Ninjutsu and Ki, delivering a Divine Warrior Kick to a single enemy target (prioritizing the slowest), stealing 30% of the target’s critical rate and 40% of their critical damage for 2 turns, dealing #C0x3D8A99#780% magic damage#C0x5B545B#+$(skillLevel*4*90)$ as #C0xF13B54#magic damage#C0x5B545B#, with 30% lifesteal. If the target\'s speed is 40% lower than Arale’s or their HP drops below 10% after the attack (including if killed), an additional <Heavenly Ice Mountain Strike> will hit all enemies (up to 2 activations).\n#F10#\n#F40##C0x4682B4##L10#Heavenly Ice Mountain Strike: Deals true damage equal to #C0x3D8A99#100% of the target’s magic attack#C0x5B545B#+10% of the target’s max HP to all enemies#L0##C0x5B545B# (up to 1000% of the target\'s magic attack), double damage to dungeon monsters and guaranteed activation.',
		describe_th = 'อาราเล่เปิดใช้งานท่าไม้ตายของเธอ ผสานนินจุตสึกับพลังลมปราณ เตะเป้าหมายศัตรูเพียงหนึ่งตัวด้วยท่า "เตะเทพสงคราม" (เน้นเป้าหมายที่ช้าที่สุด) ขโมย 30% อัตราคริติคอล และ 40% ความเสียหายคริติคอลของเป้าหมายเป็นเวลา 2 เทิร์น สร้าง #C0x3D8A99#780% ความเสียหายเวท#C0x5B545B#+$(skillLevel*4*90)$ เป็น #C0xF13B54#ความเสียหายเวท#C0x5B545B# พร้อมดูดเลือด 30% หากความเร็วของเป้าหมายช้ากว่าอาราเล่ 40% ขึ้นไป หรือ HP ของเป้าหมายต่ำกว่า 10% หลังจากโดนโจมตีนี้ (รวมถึงกรณีเสียชีวิต) จะเสริม <ภูผาน้ำแข็งสวรรค์> โจมตีศัตรูทั้งหมด (สูงสุด 2 ครั้ง)\n#F10#\n#F40##C0x4682B4##L10#ภูผาน้ำแข็งสวรรค์: สร้างความเสียหายจริงเท่ากับ #C0x3D8A99#100% พลังเวทของเป้าหมาย#C0x5B545B#+10% HP สูงสุดของเป้าหมายแก่ศัตรูทั้งหมด#L0##C0x5B545B# (สูงสุดไม่เกิน 1000% พลังเวทของเป้าหมาย) สร้างความเสียหายเพิ่ม 2 เท่าแก่บอสดันเจี้ยน และการโจมตีนี้จะเกิดขึ้นแน่นอน',
		describe_in = 'Arale mengaktifkan skill ultimatenya, menggabungkan Ninjutsu dan Ki, melakukan tendangan Divine Warrior Kick ke satu target musuh (prioritaskan target paling lambat), mencuri 30% critical rate dan 40% critical damage target selama 2 giliran, memberikan #C0x3D8A99#780% magic damage#C0x5B545B#+$(skillLevel*4*90)$ sebagai #C0xF13B54#magic damage#C0x5B545B#, dengan 30% lifesteal. Jika kecepatan target lebih rendah 40% dari Arale atau HP target turun di bawah 10% setelah serangan ini (termasuk jika mati), <Serangan Gunung Es Surgawi> tambahan akan mengenai semua musuh (maksimal 2 kali aktif).\n#F10#\n#F40##C0x4682B4##L10#Serangan Gunung Es Surgawi: Memberikan true damage sebesar #C0x3D8A99#100% serangan sihir target#C0x5B545B#+10% HP maksimum target ke semua musuh#L0##C0x5B545B# (maksimal 1000% serangan sihir target), memberikan 2x damage ke monster dungeon dan pasti aktif.',
		describe_ph = 'Ina-activate ni Arale ang kanyang ultimate, pinagsasama ang Ninjutsu at Ki, at binibigyan ng isang Divine Warrior Kick ang isang kalabang target (inuuna ang pinakamabagal), ninanakaw ang 30% crit rate at 40% crit damage ng target sa loob ng 2 turn, nagdudulot ng #C0x3D8A99#780% magic damage#C0x5B545B#+$(skillLevel*4*90)$ bilang #C0xF13B54#magic damage#C0x5B545B#, na may 30% lifesteal. Kung ang bilis ng target ay 40% mas mababa kaysa kay Arale o ang HP ay bumaba sa ilalim ng 10% pagkatapos ng atake (kahit patay na), isang karagdagang <Langit na Hampas ng Bundok ng Yelo> ang lilitaw at aatake sa lahat ng kalaban (limitado sa 2 activation).\n#F10#\n#F40##C0x4682B4##L10#Langit na Hampas ng Bundok ng Yelo: Nagdudulot ng tunay na pinsala na katumbas ng #C0x3D8A99#100% magic attack ng target#C0x5B545B#+10% max HP ng target sa lahat ng kalaban#L0##C0x5B545B# (hanggang 1000% ng magic attack ng target), doble ang pinsala sa dungeon monsters at siguradong mag-aactivate.',
		describe_ma = 'Arale mengaktifkan kemahiran ultimatenya, menggabungkan Ninjutsu dan Ki, melakukan tendangan Divine Warrior Kick ke atas satu sasaran musuh (mengutamakan yang paling perlahan), mencuri 30% kadar kritikal dan 40% kerosakan kritikal sasaran selama 2 pusingan, memberikan #C0x3D8A99#780% kerosakan sihir#C0x5B545B#+$(skillLevel*4*90)$ sebagai #C0xF13B54#kerosakan sihir#C0x5B545B#, dengan 30% curi nyawa. Jika kelajuan sasaran 40% lebih rendah daripada Arale atau HP sasaran jatuh di bawah 10% selepas serangan ini (termasuk jika mati), satu <Serangan Gunung Ais Syurga> tambahan akan menyerang semua musuh (terhad kepada 2 kali pengaktifan).\n#F10#\n#F40##C0x4682B4##L10#Serangan Gunung Ais Syurga: Menyebabkan kerosakan sebenar bersamaan #C0x3D8A99#100% serangan sihir sasaran#C0x5B545B#+10% HP maksimum sasaran kepada semua musuh#L0##C0x5B545B# (maksimum 1000% serangan sihir sasaran), menggandakan kerosakan kepada raksasa penjara bawah tanah dan dijamin akan diaktifkan.',
		describe = 'Little Sisu\'s entire body turns into magma, then slams the ground, using magma to attack the enemy\'s backline, dealing #C0x3D8A99#180% Magic Attack#C0x5B545B# + $(skillLevel*4*34)$ #C0xF13B54# Magic Damage#C0x5B545B#. Each time an ally on the field is lost, this attack\'s critical rate increases by 20%.',
		simDesc_en = 'The Little Lion\'s entire body turns into magma, then strikes the ground, attacking a single enemy target with magma; each time an allied hero is lost, the critical hit rate of this attack increases.',
		simDesc_in = 'Singa Kecil mengubah seluruh tubuhnya menjadi lava, kemudian memukul tanah, menyerang satu sasaran musuh dengan lava; setiap kali satu pahlawan rekan hilang, tingkat serangan kritis dari serangan ini meningkat.',
		simDesc_ph = 'Ang Maliit na Leon ay nagiging lava ang buong katawan, pagkatapos ay tinatamaan ang lupa, inaatake ang isang target na kalaban gamit ang lava; sa tuwing may natalong hero na kasama, tumataas ang kritikal na porsyento ng pag-atake na ito.',
		simDesc_ma = 'Singa Kecil mengubah seluruh badannya menjadi lava, kemudian menumbuk ke tanah, menyerang satu sasaran musuh dengan lava; setiap kali seorang wira sekutu hilang, kadar serangan kritikal serangan ini meningkat.',
		simDesc = 'The Little Lion\'s entire body turns into magma, then strikes the ground, attacking a single enemy target with magma; each time an allied hero is lost, the critical hit rate of this attack increases.',
		starEffect = __data_t__starEffect[33043],
		-- {11}
		starEffectDesc_vn = 'Sau mỗi 3 đòn đánh thường, nó sẽ vào trạng thái <Ảnh Sát> để triệu hồi một phân thân siêu nhẫn thay thế, đồng thời cường hóa chiêu thức đặc biệt tiếp theo, khiến chiêu thức đặc biệt đó có hiệu ứng <Thuỷ Ảnh Liên Kích>\n#F10#\n#F40##L10#Thuỷ Ảnh Liên Kích: #L0#Triệu hồi tối đa 5 phân thân siêu nhẫn lên không trung (về cơ bản là 2, và cứ mỗi 15% tốc độ hiện tại tăng lên so với tốc độ ban đầu, một phân thân siêu ninja khác sẽ được triệu hồi), cùng nhau phóng ra các phi tiêu tấn công mục tiêu địch ngẫu nhiên, gây 200% sát thương phép của phân thân siêu nhẫn',
		starEffectDesc = 'After every 3 normal attacks, it enters the <Shadow Assassination> state to summon a Super Ninja Clone as a replacement and enhances the next special skill, granting it the <Water Shadow Combo> effect\n#F10#\n#F40##L10#Water Shadow Combo: #L0#Summons up to 5 Super Ninja Clones into the air (base is 2 clones, and for every 15% increase in current speed compared to base speed, 1 additional Super Ninja Clone is summoned), they throw shurikens together to attack random enemy targets, dealing 200% of the Super Ninja Clone’s magic damage',
		starEffectDesc_en = 'After every 3 normal attacks, it enters the <Shadow Assassination> state to summon a Super Ninja Clone as a replacement and enhances the next special skill, granting it the <Water Shadow Combo> effect\n#F10#\n#F40##L10#Water Shadow Combo: #L0#Summons up to 5 Super Ninja Clones into the air (base is 2 clones, and for every 15% increase in current speed compared to base speed, 1 additional Super Ninja Clone is summoned), they throw shurikens together to attack random enemy targets, dealing 200% of the Super Ninja Clone’s magic damage',
		starEffectDesc_th = 'หลังจากโจมตีปกติครบ 3 ครั้ง จะเข้าสู่สถานะ <เงาลอบสังหาร> เพื่อเรียกตัวแทนเป็นร่างแยกซูเปอร์นินจา พร้อมเสริมพลังให้สกิลพิเศษถัดไปด้วยเอฟเฟกต์ <คอมโบเงาน้ำ>\n#F10#\n#F40##L10#คอมโบเงาน้ำ: #L0#เรียกร่างแยกซูเปอร์นินจาขึ้นไปบนอากาศสูงสุด 5 ตัว (เริ่มต้น 2 ตัว และทุกๆ 15% ความเร็วที่เพิ่มจากพื้นฐานจะเรียกได้อีก 1 ตัว) โดยจะขว้างชูริเคนใส่ศัตรูแบบสุ่ม สร้างความเสียหายเวท 200% ของร่างแยกซูเปอร์นินจา',
		starEffectDesc_in = 'Setiap 3 serangan normal, akan memasuki status <Pembunuhan Bayangan> untuk memanggil Klon Super Ninja sebagai pengganti, serta memperkuat skill spesial berikutnya dengan efek <Serangan Bayangan Air>\n#F10#\n#F40##L10#Serangan Bayangan Air: #L0#Memanggil hingga 5 Klon Super Ninja ke udara (dasarnya 2, dan setiap kenaikan 15% kecepatan dari awal akan menambah 1 klon lagi), mereka bersama-sama melempar shuriken ke target musuh acak, memberikan 200% magic damage dari klon',
		starEffectDesc_ph = 'Pagkatapos ng bawat 3 normal na atake, papasok ito sa estado ng <Shadow Assassination> upang tumawag ng Super Ninja Clone bilang kapalit, at palalakasin ang susunod na espesyal na kakayahan na may <Water Shadow Combo> na epekto\n#F10#\n#F40##L10#Water Shadow Combo: #L0#Tatawagin ang hanggang 5 Super Ninja Clones sa himpapawid (base ay 2 clones, at bawat dagdag na 15% sa bilis mula sa base ay magdadagdag ng 1 clone), sabay-sabay silang magtatapon ng shuriken sa random na kalaban, na nagdudulot ng 200% magic damage ng clone',
		starEffectDesc_ma = 'Setiap kali selepas 3 serangan biasa, ia akan masuk ke status <Pembunuh Bayangan> untuk memanggil Klon Super Ninja sebagai pengganti, dan memperkuatkan kemahiran khas seterusnya dengan efek <Serangan Bayangan Air>\n#F10#\n#F40##L10#Serangan Bayangan Air: #L0#Memanggil sehingga 5 Klon Super Ninja ke udara (asas ialah 2 klon, dan setiap peningkatan 15% kelajuan berbanding kelajuan asal akan memanggil 1 klon tambahan), mereka melontar shuriken bersama ke sasaran musuh rawak, memberikan 200% kerosakan sihir klon',
		zawakeEffect = __data_t__zawakeEffect[33043],
		-- {79003, 1}
		zawakeEffectDesc = 'Each wave-break attack +1, and increases base damage from 60% to 80% magic attack (adds 20% magic attack for each additional enemy). It can also dispel one of its own buffs. If there’s no debuff or the target has a speed-type debuff, it will <Push Back> the target for 1 turn. After every 3 normal attacks, it enters <Shadow Assassination> state to summon a Super Clone replacement and enhance the next special skill, allowing it to bypass targeting. Reduces all critical damage taken and adds the <Water Shadow Link> effect\n#F10#\n#F40##L10#Water Shadow Link: #L0#Summons up to 5 Super Clones into the air (base is 2, and for every 15% increase in current speed compared to base speed, 1 additional Super Clone will be summoned). Simultaneously launches Sailor Shurikens to attack random enemy targets, dealing damage equal to 200% of the Super Clone\'s magic attack',
		zawakeEffectDesc_en = 'Each wave-break attack +1, and increases base damage from 60% to 80% magic attack (adds 20% magic attack for each additional enemy). It can also dispel one of its own buffs. If there’s no debuff or the target has a speed-type debuff, it will <Push Back> the target for 1 turn. After every 3 normal attacks, it enters <Shadow Assassination> state to summon a Super Clone replacement and enhance the next special skill, allowing it to bypass targeting. Reduces all critical damage taken and adds the <Water Shadow Link> effect\n#F10#\n#F40##L10#Water Shadow Link: #L0#Summons up to 5 Super Clones into the air (base is 2, and for every 15% increase in current speed compared to base speed, 1 additional Super Clone will be summoned). Simultaneously launches Sailor Shurikens to attack random enemy targets, dealing damage equal to 200% of the Super Clone\'s magic attack',
		zawakeEffectDesc_th = 'สิงโตน้อยทั้งตัวเข้าสู่สถานะลาวา จากนั้นตีกระทบพื้น ใช้ลาวาโจมตีเป้าหมายแถวหลังของศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*34) $#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# สำหรับฮีโร่พันธมิตรที่เสียชีวิตในสนามแต่ละคน การโจมตีนี้จะเพิ่มโอกาสคริติคอลขึ้น 20% โอกาสคริติคอลและเอฟเฟกต์โบนัสความเสียหายคริติคอลจะดำเนินต่อไปอีก 1 เทิร์นหลังจากการปล่อยสกิล',
		zawakeEffectDesc_in = 'Seluruh tubuh singa kecil memasuki kondisi lava, lalu menghantam tanah, menggunakan lava untuk menyerang target di barisan belakang musuh, menyebabkan #C0x3D8A99#180% Damage Magic#C0x5B545B#+$(skillLevel*4*34) $#C0xF13B54#Damage Magic#C0x5B545B#. Untuk setiap pahlawan sekutu yang hilang di lapangan, serangan ini meningkatkan peluang serangan kritis sebesar 20%. Peluang serangan kritis dan efek bonus damage kritis akan berlanjut selama 1 giliran setelah pertarungan. Skill dilepaskan.',
		zawakeEffectDesc_ph = 'Ang buong katawan ng maliit na leon ay pumapasok sa estado ng lava, pagkatapos ay tumatama sa lupa, gamit ang lava upang atakihin ang mga target sa likurang hanay ng kalaban, na nagdudulot ng #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*34) $#C0xF13B54#Magic Damage#C0x5B545B#. Para sa bawat kaalyadong bayani na nawala sa laban, pinapataas ng atakeng ito ang tsansa ng critical hit ng 20%. Ang tsansa ng critical hit at mga epekto ng bonus na critical damage ay magpapatuloy ng 1 turn pagkatapos ng laban. Ang kakayahan ay nailabas.',
		zawakeEffectDesc_ma = 'Seluruh badan anak singa memasuki keadaan lava, kemudian memukul tanah, menggunakan lava untuk menyerang sasaran di barisan belakang musuh, menyebabkan #C0x3D8A99#180% Kerosakan Ajaib#C0x5B545B#+$(skillLevel*4*34) $#C0xF13B54#Kerosakan Ajaib#C0x5B545B#. Bagi setiap wira sekutu yang hilang di padang, serangan ini meningkatkan peluang untuk terkena serangan kritikal sebanyak 20%. Peluang serangan kritikal dan kesan bonus kerosakan kritikal akan berterusan selama 1 pusingan selepas pertempuran. Kemahiran dibebaskan.',
		zawakeEffectDesc_vn = 'Mỗi đòn đánh phá sóng +1, và tăng sát thương cơ bản từ 60% lên 80% đòn tấn công phép thuật (tăng đòn tấn công phép thuật thêm 20% cho mỗi kẻ địch tiếp theo). Nó cũng có thể giải trừ một trong những hiệu ứng tăng sức mạnh của nó. Nếu không có hiệu ứng giảm sức mạnh hoặc mục tiêu có debuff loại tốc độ, nó sẽ <đẩy lùi> mục tiêu trong 1 hiệp. Sau mỗi 3 đòn đánh thường, nó sẽ vào trạng thái <Ảnh Sát> để triệu hồi một phân thân Siêu Cấp thay thế và tăng cường chiêu thức đặc biệt tiếp theo, khiến chiêu thức đặc biệt đó bỏ qua mục tiêu. Giảm mọi sát thương chí mạng và thêm hiệu ứng <Thuỷ Ảnh Kích>\n#F10#\n#F40##L10#Water Shadow Link: #L0#Triệu hồi tối đa 5 phân thân Siêu Cấp lên không trung (về cơ bản là 2, và cứ mỗi 15% tăng tốc độ hiện tại so với tốc độ ban đầu, 1 phân thân Siêu Cấp bổ sung sẽ được triệu hồi). Phóng cùng lúc Sailor Phi Tiêu để tấn công mục tiêu địch ngẫu nhiên, gây sát thương bằng 200% đòn tấn công phép thuật của bản sao Siêu Cấp',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'The base damage of Water Shadow Strike has been increased from 60% to 80% of Magic ATK (plus an additional 20% Magic ATK per subsequent enemy) and it can also remove one of its own buffs. If no buffs are removed or if the target has a Slow effect, the target will be <Knocked Back> for 1 turn; Shadow Kill ignores all damage reduction effects on the target.',
		zawakeSimpleDesc_en = 'The base damage of Water Shadow Strike has been increased from 60% to 80% of Magic ATK (plus an additional 20% Magic ATK per subsequent enemy) and it can also remove one of its own buffs. If no buffs are removed or if the target has a Slow effect, the target will be <Knocked Back> for 1 turn; Shadow Kill ignores all damage reduction effects on the target.',
		zawakeSimpleDesc_th = 'ความเสียหายพื้นฐานของท่าโจมตีเงาน้ำเพิ่มจาก 60% เป็น 80% ของพลังเวทโจมตี (เพิ่มอีก 20% พลังเวทโจมตีต่อศัตรูเพิ่มเติม) และสามารถลบสถานะบัฟของตนเอง 1 อย่างได้ หากไม่มีบัฟถูกลบ หรือเป้าหมายติดสถานะลดความเร็ว เป้าหมายจะถูก <ดีดกลับ> 1 เทิร์น; Shadow Kill จะไม่สนใจเอฟเฟกต์ลดความเสียหายทั้งหมดของเป้าหมาย',
		zawakeSimpleDesc_in = 'Damage dasar dari Water Shadow Strike ditingkatkan dari 60% menjadi 80% dari Serangan Sihir (bertambah 20% Serangan Sihir untuk setiap musuh tambahan) dan juga dapat menghapus salah satu buff miliknya. Jika tidak ada buff yang dihapus atau target memiliki efek Slow, target akan terkena <Tendangan Mundur> selama 1 giliran; Shadow Kill mengabaikan semua efek pengurangan damage dari target.',
		zawakeSimpleDesc_ph = 'Ang base damage ng Water Shadow Strike ay tumaas mula 60% hanggang 80% ng Magic ATK (dagdag 20% Magic ATK para sa bawat kalabang susunod), at maaari rin nitong alisin ang isa sa sariling buff. Kung walang buff ang natanggal o ang target ay may Slow effect, ang target ay ma-<Knock Back> ng 1 turn; Binabalewala ng Shadow Kill ang lahat ng damage reduction effect ng target.',
		zawakeSimpleDesc_ma = 'Serangan asas Water Shadow Strike telah dinaikkan daripada 60% kepada 80% Serangan Magik (dengan tambahan 20% Serangan Magik bagi setiap musuh berikutnya) dan ia juga boleh menghapuskan salah satu buff miliknya. Jika tiada buff dihapuskan atau sasaran mempunyai kesan Slow, sasaran akan dikenakan <Tendangan Ke Belakang> selama 1 pusingan; Shadow Kill mengabaikan semua kesan pengurangan kerosakan pada sasaran.',
		zawakeSimpleDesc_vn = 'Sát thương cơ bản của Thuỷ Ảnh Kích đã được tăng từ 60% lên 80% của đòn tấn công phép thuật (tăng thêm 20% đòn tấn công phép thuật cho mỗi kẻ địch tiếp theo) và nó cũng có thể xóa bỏ một trong những hiệu ứng tăng cường của nó. Nếu không có hiệu ứng tăng cường nào bị xóa bỏ hoặc mục tiêu có hiệu ứng giảm tốc độ, mục tiêu sẽ bị <đánh bật> trong 1 hiệp; Ảnh Sát bỏ qua tất cả các hiệu ứng giảm sát thương của mục tiêu.',
		upLvDesc = 'Fixed damage +360',
		upLvDesc_en = 'Fixed damage +360',
