	[33047] = {
		id = 33047,
		skillName_vn = 'Võ Thần Cước',
		skillName_en = 'Martial God Kick',
		skillName_th = 'ลูกเตะเทพสงคราม',
		skillName_in = 'Tendangan Dewa Bela Diri',
		skillName_ph = 'Sipa ng Diyos ng Pakikidigma',
		skillName_ma = 'Tendangan Dewa Peperangan',
		skillName = 'Cosmic flame',
		describe_vn = 'Arale kích hoạt chiêu cuối của mình, kết hợp Nhẫn thuật với Khí công, thực hiện một cú Võ Thần Cước vào một mục tiêu địch duy nhất (ưu tiên tấn công mục tiêu tốc chậm nhất), đánh cắp 30% tỷ lệ bạo kích của mục tiêu và 40% sát thương bạo kích trong 2 lượt, gây #C0x3D8A99#780% sát thương phép#C0x5B545B#+$(skillLevel*4*90)$ trong #C0xF13B54# sát thương phép#C0x5B545B#, với 30% hút máu. Nếu tốc độ của mục tiêu thấp hơn tốc độ của chính mình 40% trở lên hoặc sau đòn tấn công này Nếu máu của mục tiêu dưới 10% (bao gồm cả khi chết), một <Thiên Sát Băng Sơn> bổ sung sẽ được thêm vào tất cả kẻ địch (giới hạn 2 lần kích hoạt)\n#F10#\n#F40##C0x4682B4##L10#Thiên Sát Băng Sơn: Gây sát thương chuẩn là #C0x3D8A99#100% công kích phép thuật#C0x5B545B#+10% giới hạn máu của mục tiêu lên tất cả kẻ địch #L0##C0x5B545B# (tối đa 1000% công kích phép thuật của chính mục tiêu), tăng gấp đôi sát thương lên quái vật ngục tối và chắc chắn sẽ được kích hoạt',
		describe_en = 'Arale activates her ultimate skill, combining Ninjutsu with Ki to perform a Divine Warrior Kick on a single enemy target (prioritizing the slowest one), stealing 30% of the target’s critical rate and 40% of their critical damage for 2 turns, dealing #C0x3D8A99#780% magic damage#C0x5B545B#+$(skillLevel*4*90)$ as #C0xF13B54#magic damage#C0x5B545B#, with 30% lifesteal. If the target’s speed is 40% lower than her own or if after this attack the target’s HP falls below 10% (including if dead), an additional <Heavenly Ice Mountain Strike> will be unleashed on all enemies (limited to 2 activations)\n#F10#\n#F40##C0x4682B4##L10#Heavenly Ice Mountain Strike: Deals true damage equal to #C0x3D8A99#100% of the target’s magic attack#C0x5B545B#+10% of the target’s max HP to all enemies #L0##C0x5B545B# (up to 1000% of the target’s magic attack), deals double damage to dungeon monsters and is guaranteed to activate',
		describe_th = 'Arale ใช้สกิลไม้ตายของเธอ ผสานวิชานินจาเข้ากับลมปราณ เตะศัตรูเป้าหมายเดียว (เลือกเป้าหมายที่ช้าที่สุดก่อน) ขโมยอัตราคริติคอล 30% และพลังคริติคอล 40% ของเป้าหมายเป็นเวลา 2 เทิร์น สร้างความเสียหายเวท #C0x3D8A99#780%#C0x5B545B#+$(skillLevel*4*90)$ เป็น #C0xF13B54#ความเสียหายเวท#C0x5B545B# พร้อมดูดเลือด 30% หากความเร็วของเป้าหมายช้ากว่าตัวเอง 40% ขึ้นไป หรือหลังจากโจมตีนี้ HP ของเป้าหมายต่ำกว่า 10% (รวมถึงหากตาย) จะปล่อย <สวรรค์สังหารเขาน้ำแข็ง> ใส่ศัตรูทั้งหมดเพิ่ม (จำกัด 2 ครั้ง)\n#F10#\n#F40##C0x4682B4##L10#สวรรค์สังหารเขาน้ำแข็ง: สร้างความเสียหายจริงเท่ากับ #C0x3D8A99#100% พลังโจมตีเวทของเป้าหมาย#C0x5B545B#+10% HP สูงสุดของเป้าหมายใส่ศัตรูทั้งหมด #L0##C0x5B545B# (สูงสุดไม่เกิน 1000% พลังเวทของเป้าหมาย) สร้างดาเมจสองเท่ากับมอนสเตอร์ในดันเจี้ยน และรับประกันว่าจะทำงาน',
		describe_in = 'Arale mengaktifkan jurus ultimatenya, menggabungkan Ninjutsu dengan Ki untuk melakukan Tendangan Dewa Perang ke satu target musuh (prioritas target paling lambat), mencuri 30% critical rate dan 40% critical damage target selama 2 giliran, memberikan #C0x3D8A99#780% magic damage#C0x5B545B#+$(skillLevel*4*90)$ sebagai #C0xF13B54#magic damage#C0x5B545B#, dengan 30% lifesteal. Jika kecepatan target lebih lambat 40% dari dirinya atau setelah serangan ini HP target turun di bawah 10% (termasuk jika mati), akan memicu <Serangan Gunung Es Surgawi> tambahan ke semua musuh (maksimal 2 kali)\n#F10#\n#F40##C0x4682B4##L10#Serangan Gunung Es Surgawi: Memberikan true damage sebesar #C0x3D8A99#100% serangan sihir target#C0x5B545B#+10% HP maksimum target ke semua musuh #L0##C0x5B545B# (hingga maksimum 1000% serangan sihir target), memberikan damage ganda ke monster dungeon dan dijamin aktif',
		describe_ph = 'Inia-activate ni Arale ang kanyang ultimate skill, pinagsasama ang Ninjutsu at Ki upang maglunsad ng Divine Warrior Kick sa isang kalabang target (inuuna ang pinakamabagal), ninanakaw ang 30% critical rate at 40% critical damage ng target sa loob ng 2 turn, nagdudulot ng #C0x3D8A99#780% magic damage#C0x5B545B#+$(skillLevel*4*90)$ bilang #C0xF13B54#magic damage#C0x5B545B#, na may 30% lifesteal. Kapag ang bilis ng target ay 40% mas mababa kaysa sa kanya o kapag ang HP ng target ay bumaba sa ilalim ng 10% pagkatapos ng atake (kahit patay), isang karagdagang <Heavenly Ice Mountain Strike> ang ibabagsak sa lahat ng kalaban (limitado sa 2 beses)\n#F10#\n#F40##C0x4682B4##L10#Heavenly Ice Mountain Strike: Nagdudulot ng totoong pinsala na katumbas ng #C0x3D8A99#100% magic attack ng target#C0x5B545B#+10% ng max HP ng target sa lahat ng kalaban #L0##C0x5B545B# (hanggang 1000% magic attack ng target), doble ang pinsala sa dungeon monsters at siguradong i-aactivate',
		describe_ma = 'Arale mengaktifkan kemahiran ultimatenya, menggabungkan Ninjutsu dengan Ki untuk melancarkan Tendangan Pahlawan Dewa kepada satu sasaran musuh (utamakan yang paling perlahan), mencuri 30% kadar kritikal dan 40% kerosakan kritikal musuh selama 2 pusingan, memberikan #C0x3D8A99#780% kerosakan sihir#C0x5B545B#+$(skillLevel*4*90)$ sebagai #C0xF13B54#kerosakan sihir#C0x5B545B#, dengan 30% curi nyawa. Jika kelajuan musuh adalah 40% lebih rendah atau selepas serangan ini HP musuh jatuh bawah 10% (termasuk jika mati), satu <Serangan Gunung Ais Syurga> tambahan akan dilancarkan kepada semua musuh (maksimum 2 kali)\n#F10#\n#F40##C0x4682B4##L10#Serangan Gunung Ais Syurga: Menyebabkan kerosakan sebenar bersamaan #C0x3D8A99#100% serangan sihir sasaran#C0x5B545B#+10% HP maksimum sasaran kepada semua musuh #L0##C0x5B545B# (sehingga maksimum 1000% serangan sihir sasaran), memberikan dua kali ganda kerosakan kepada raksasa penjara dan dijamin akan diaktifkan',
		describe = 'The flying zombie spews cosmic flames to attack an enemy target, dealing #C0x3D8A99#150% Magical Damage#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# Magical Damage#C0x5B545B# and reduces the target\'s critical damage resistance by 10% for 3 turns.',
		simDesc_en = 'The flying zombie emits cosmic flames to attack an enemy target.',
		simDesc_in = 'Zombie terbang memancarkan api kosmik untuk menyerang target musuh.',
		simDesc_ph = 'Ang lumilipad na zombie ay nagpapalabas ng apoy ng kalawakan upang atakihin ang isang target na kaaway.',
		simDesc_ma = 'Zombie terbang memancarkan api kosmik untuk menyerang sasaran musuh.',
		simDesc = 'The flying zombie emits cosmic flames to attack an enemy target.',
		starEffect = __data_t__starEffect[33047],
		-- {11}
		starEffectDesc_vn = 'Sau mỗi 3 đòn đánh thường, nó sẽ vào trạng thái <Ảnh Sát> để triệu hồi một phân thân siêu nhẫn thay thế, đồng thời cường hóa chiêu thức đặc biệt tiếp theo, khiến chiêu thức đặc biệt đó có hiệu ứng <Thuỷ Ảnh Liên Kích>\n#F10#\n#F40##L10#Thuỷ Ảnh Liên Kích: #L0#Triệu hồi tối đa 5 phân thân siêu nhẫn lên không trung (về cơ bản là 2, và cứ mỗi 15% tốc độ hiện tại tăng lên so với tốc độ ban đầu, một phân thân siêu ninja khác sẽ được triệu hồi), cùng nhau phóng ra các phi tiêu tấn công mục tiêu địch ngẫu nhiên, gây 200% sát thương phép của phân thân siêu nhẫn',
		starEffectDesc = 'After every 3 normal attacks, it enters the <Shadow Assassination> state to summon a Super Ninja Clone as a substitute and simultaneously enhances the next special skill, giving it the <Water Shadow Combo> effect\n#F10#\n#F40##L10#Water Shadow Combo: #L0#Summons up to 5 Super Ninja Clones into the air (by default 2, and for every 15% increase in current speed compared to base speed, one additional Super Ninja Clone is summoned), they throw shurikens together to randomly attack enemy targets, dealing 200% magic damage of the Super Ninja Clones',
		starEffectDesc_en = 'After every 3 normal attacks, it enters the <Shadow Assassination> state to summon a Super Ninja Clone as a substitute and simultaneously enhances the next special skill, giving it the <Water Shadow Combo> effect\n#F10#\n#F40##L10#Water Shadow Combo: #L0#Summons up to 5 Super Ninja Clones into the air (by default 2, and for every 15% increase in current speed compared to base speed, one additional Super Ninja Clone is summoned), they throw shurikens together to randomly attack enemy targets, dealing 200% magic damage of the Super Ninja Clones',
		starEffectDesc_th = 'หลังจากโจมตีปกติครบ 3 ครั้ง จะเข้าสู่สถานะ <ลอบสังหารเงา> เพื่ออัญเชิญร่างแยกซูเปอร์นินจาแทนตัวเอง และเพิ่มพลังให้สกิลพิเศษถัดไปพร้อมเอฟเฟกต์ <คอมโบเงาน้ำ>\n#F10#\n#F40##L10#คอมโบเงาน้ำ: #L0#อัญเชิญร่างแยกซูเปอร์นินจาสูงสุด 5 ตัวลอยขึ้นฟ้า (เริ่มต้นที่ 2 ตัว และทุกๆ 15% ความเร็วที่เพิ่มจากพื้นฐาน จะเพิ่มอีก 1 ตัว) พวกมันจะขว้างชูริเคนใส่ศัตรูแบบสุ่ม สร้างความเสียหายเวท 200% จากร่างแยกซูเปอร์นินจา',
		starEffectDesc_in = 'Setelah setiap 3 serangan normal, ia memasuki status <Pembunuhan Bayangan> untuk memanggil Klon Super Ninja sebagai pengganti dan memperkuat skill spesial berikutnya dengan efek <Serangan Bayangan Air>\n#F10#\n#F40##L10#Serangan Bayangan Air: #L0#Memanggil hingga 5 Klon Super Ninja ke udara (default 2, dan setiap peningkatan 15% kecepatan dibandingkan kecepatan dasar akan memanggil satu klon tambahan), mereka melemparkan shuriken bersama untuk menyerang target musuh secara acak, memberikan 200% magic damage dari Klon Super Ninja',
		starEffectDesc_ph = 'Pagkatapos ng bawat 3 normal na atake, papasok ito sa estado ng <Shadow Assassination> upang tumawag ng Super Ninja Clone bilang kapalit at palakasin ang susunod na espesyal na kakayahan na magkakaroon ng <Water Shadow Combo> na epekto\n#F10#\n#F40##L10#Water Shadow Combo: #L0#Tumatawag ng hanggang 5 Super Ninja Clones sa ere (karaniwan ay 2, at bawat 15% dagdag sa kasalukuyang bilis kumpara sa base speed ay tatawag ng 1 karagdagang clone), sabay-sabay silang nagtatapon ng shuriken upang umatake ng random na kalaban, nagdudulot ng 200% magic damage mula sa Super Ninja Clones',
		starEffectDesc_ma = 'Selepas setiap 3 serangan biasa, ia akan memasuki status <Pembunuhan Bayangan> untuk memanggil Klon Super Ninja sebagai pengganti dan menguatkan kemahiran khas seterusnya dengan kesan <Serangan Bayangan Air>\n#F10#\n#F40##L10#Serangan Bayangan Air: #L0#Memanggil sehingga 5 Klon Super Ninja ke udara (asalnya 2, dan bagi setiap peningkatan 15% kelajuan semasa berbanding kelajuan asas, satu klon tambahan akan dipanggil), mereka bersama-sama melontar shuriken untuk menyerang musuh rawak, memberikan 200% kerosakan sihir daripada Klon Super Ninja',
		zawakeEffect = __data_t__zawakeEffect[33047],
		-- {79003, 1}
		zawakeEffectDesc = 'Each wave-break attack +1, and increases base damage from 60% to 80% of magic attack (adds 20% magic attack for each additional enemy). It can also dispel one of its own buffs. If there is no debuff or the target has a speed-type debuff, it will <Push Back> the target for 1 turn. After every 3 normal attacks, it enters <Shadow Assassination> state to summon a Super Clone as a replacement and enhances the next special skill, making that skill ignore targeting. Reduces all critical damage and adds the <Water Shadow Link> effect\n#F10#\n#F40##L10#Water Shadow Link: #L0#Summons up to 5 Super Clones into the air (base is 2, and for every 15% increase in current speed compared to base speed, 1 additional Super Clone is summoned). Simultaneously launches Sailor Shurikens to randomly attack enemy targets, dealing damage equal to 200% of the Super Clone’s magic attack',
		zawakeEffectDesc_en = 'Each wave-break attack +1, and increases base damage from 60% to 80% of magic attack (adds 20% magic attack for each additional enemy). It can also dispel one of its own buffs. If there is no debuff or the target has a speed-type debuff, it will <Push Back> the target for 1 turn. After every 3 normal attacks, it enters <Shadow Assassination> state to summon a Super Clone as a replacement and enhances the next special skill, making that skill ignore targeting. Reduces all critical damage and adds the <Water Shadow Link> effect\n#F10#\n#F40##L10#Water Shadow Link: #L0#Summons up to 5 Super Clones into the air (base is 2, and for every 15% increase in current speed compared to base speed, 1 additional Super Clone is summoned). Simultaneously launches Sailor Shurikens to randomly attack enemy targets, dealing damage equal to 200% of the Super Clone’s magic attack',
		zawakeEffectDesc_th = 'ปีศาจที่ถูกเรียกออกบินปล่อยเปลวเพลิงจักรวาลโจมตีเป้าหมายศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#150%#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# และลดความต้านทานความเสียหายคริติคอลของเป้าหมายลง 15% เป็นเวลา 3 รอบ',
		zawakeEffectDesc_in = 'Iblis yang dipanggil terbang mengeluarkan api kosmik untuk menyerang target musuh, memberikan #C0x3D8A99#150% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#Kerusakan Magis#C0x5B545B# dan mengurangi ketahanan kerusakan kritis target sebesar 15% selama 3 giliran.',
		zawakeEffectDesc_ph = 'Ang demonyo na tinawag ay lumilipad at naglalabas ng apoy ng kosmos upang atakihin ang target na kaaway, na nagdudulot ng #C0x3D8A99#150% Magical Damage#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#Magical Damage#C0x5B545B# at nagpapababa ng resistensya ng target sa critical damage ng 15% sa loob ng 3 turn.',
		zawakeEffectDesc_ma = 'Makhluk summoned terbang melepaskan api kosmik untuk menyerang sasaran musuh, memberikan #C0x3D8A99#150% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#Kerosakan Magik#C0x5B545B# dan mengurangkan ketahanan kerosakan kritikal sasaran sebanyak 15% selama 3 pusingan.',
		zawakeEffectDesc_vn = 'Mỗi đòn đánh phá sóng +1, và tăng sát thương cơ bản từ 60% lên 80% đòn tấn công phép thuật (tăng đòn tấn công phép thuật thêm 20% cho mỗi kẻ địch tiếp theo). Nó cũng có thể giải trừ một trong những hiệu ứng tăng sức mạnh của nó. Nếu không có hiệu ứng giảm sức mạnh hoặc mục tiêu có debuff loại tốc độ, nó sẽ <đẩy lùi> mục tiêu trong 1 hiệp. Sau mỗi 3 đòn đánh thường, nó sẽ vào trạng thái <Ảnh Sát> để triệu hồi một phân thân Siêu Cấp thay thế và tăng cường chiêu thức đặc biệt tiếp theo, khiến chiêu thức đặc biệt đó bỏ qua mục tiêu. Giảm mọi sát thương chí mạng và thêm hiệu ứng <Thuỷ Ảnh Kích>\n#F10#\n#F40##L10#Water Shadow Link: #L0#Triệu hồi tối đa 5 phân thân Siêu Cấp lên không trung (về cơ bản là 2, và cứ mỗi 15% tăng tốc độ hiện tại so với tốc độ ban đầu, 1 phân thân Siêu Cấp bổ sung sẽ được triệu hồi). Phóng cùng lúc Sailor Phi Tiêu để tấn công mục tiêu địch ngẫu nhiên, gây sát thương bằng 200% đòn tấn công phép thuật của bản sao Siêu Cấp',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'The base damage of Water Shadow Strike has been increased from 60% to 80% of Magic ATK (adds 20% Magic ATK per subsequent enemy) and it can also remove one of its own buffs. If no buffs are removed or the target has a Slow effect, the target will be <Knocked Back> for 1 turn; Shadow Kill ignores all damage reduction effects on the target.',
		zawakeSimpleDesc_en = 'The base damage of Water Shadow Strike has been increased from 60% to 80% of Magic ATK (adds 20% Magic ATK per subsequent enemy) and it can also remove one of its own buffs. If no buffs are removed or the target has a Slow effect, the target will be <Knocked Back> for 1 turn; Shadow Kill ignores all damage reduction effects on the target.',
		zawakeSimpleDesc_th = 'ความเสียหายพื้นฐานของท่าเงาน้ำเพิ่มจาก 60% เป็น 80% ของพลังโจมตีเวท (เพิ่มอีก 20% ต่อศัตรูเพิ่มเติม) และสามารถลบหนึ่งในบัฟของตัวเอง หากไม่มีบัฟที่ถูกลบหรือศัตรูติดสถานะลดความเร็ว จะทำให้เป้าหมาย <กระเด็น> เป็นเวลา 1 เทิร์น; Shadow Kill จะไม่สนใจผลลดความเสียหายทั้งหมดของเป้าหมาย',
		zawakeSimpleDesc_in = 'Damage dasar dari Water Shadow Strike meningkat dari 60% menjadi 80% dari Serangan Sihir (tambahan 20% Serangan Sihir untuk setiap musuh berikutnya) dan juga dapat menghapus satu buff milik sendiri. Jika tidak ada buff yang dihapus atau target terkena efek Slow, target akan <Terlempar> selama 1 giliran; Shadow Kill mengabaikan semua efek pengurangan damage.',
		zawakeSimpleDesc_ph = 'Ang base damage ng Water Shadow Strike ay tumaas mula 60% hanggang 80% ng Magic ATK (dagdag 20% Magic ATK sa bawat karagdagang kalaban), at maaari ring alisin ang isa sa sariling buffs. Kung walang buff na natanggal o may Slow ang kalaban, sila ay <maitulak> ng 1 turn; Binabalewala ng Shadow Kill ang lahat ng damage reduction effects ng kalaban.',
		zawakeSimpleDesc_ma = 'Kerosakan asas Water Shadow Strike telah dinaikkan dari 60% ke 80% Serangan Magik (dengan tambahan 20% bagi setiap musuh tambahan) dan juga boleh menghapuskan salah satu buff miliknya. Jika tiada buff yang dihapus atau sasaran mempunyai kesan Perlahan, sasaran akan <Diterajang Balik> selama 1 pusingan; Shadow Kill mengabaikan semua kesan pengurangan kerosakan.',
		zawakeSimpleDesc_vn = 'Sát thương cơ bản của Thuỷ Ảnh Kích đã được tăng từ 60% lên 80% của đòn tấn công phép thuật (tăng thêm 20% đòn tấn công phép thuật cho mỗi kẻ địch tiếp theo) và nó cũng có thể xóa bỏ một trong những hiệu ứng tăng cường của nó. Nếu không có hiệu ứng tăng cường nào bị xóa bỏ hoặc mục tiêu có hiệu ứng giảm tốc độ, mục tiêu sẽ bị <đánh bật> trong 1 hiệp; Ảnh Sát bỏ qua tất cả các hiệu ứng giảm sát thương của mục tiêu.',
		upLvDesc_th = 'ความเสียหายคงที่ +144',
		upLvDesc_in = 'Kerusakan tetap +144',
		upLvDesc_ph = 'Fixed na pinsala +144',
