	[33423] = {
		id = 33423,
		skillName_vn = 'Nhiễu loạn điện từ',
		skillName_en = 'Electromagnetic interference',
		skillName_th = 'สัญญาณรบกวนแม่เหล็กไฟฟ้า',
		skillName_in = 'Gangguan elektromagnetik',
		skillName_ph = 'Electromagnetic interference',
		skillName_ma = 'Gangguan elektromagnet',
		skillName = 'Electromagnetic interference',
		describe_vn = 'Zombie bay bật thiết bị gây nhiễu điện từ và tấn công mục tiêu ở hàng sau của kẻ địch, gây ra #C0x3D8A99#190% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54#sát thương ma thuật#C0x5B545B#. Đối với mỗi anh hùng đồng minh bị mất trên sân, tỷ lệ trúng đòn chí mạng của đòn tấn công này sẽ tăng thêm 20%.',
		describe_en = 'The zombie activates the electromagnetic interference device and attacks the enemy\'s backline, dealing #C0x3D8A99#190% Magical Damage#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# magic damage#C0x5B545B#. For each fallen allied hero on the field, the critical hit rate of this attack increases by 20%.',
		describe_th = 'ซอมบี้เปิดใช้งานอุปกรณ์รบกวนแม่เหล็กไฟฟ้าและโจมตีเป้าหมายในแถวหลังของศัตรู สร้างความเสียหายเวทย์มนตร์ #C0x3D8A99#190%#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# ความเสียหายเวทย์มนตร์#C0x5B545B# สำหรับฮีโร่พันธมิตรที่เสียชีวิตแต่ละคนบนสนาม โอกาสคริติคอลของการโจมตีนี้จะเพิ่มขึ้น 20%',
		describe_in = 'Zombie mengaktifkan perangkat gangguan elektromagnetik dan menyerang target di barisan belakang musuh, menyebabkan #C0x3D8A99#190% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# kerusakan magis#C0x5B545B#. Untuk setiap pahlawan sekutu yang gugur di medan perang, peluang serangan kritis dari serangan ini meningkat sebesar 20%.',
		describe_ph = 'Pinapatakbo ng zombie ang electromagnetic interference device at inaatake ang layunin sa likurang linya ng kalaban, na nagdudulot ng #C0x3D8A99#190% Magical Damage#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# pinsalang mahika#C0x5B545B#. Para sa bawat alyadong bayani na namatay sa larangan, tumataas ang critical hit rate ng pag-atakeng ito ng 20%.',
		describe_ma = 'Zombie mengaktifkan peranti gangguan elektromagnet dan menyerang sasaran di barisan belakang musuh, menyebabkan #C0x3D8A99#190% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# kerosakan magik#C0x5B545B#. Untuk setiap wira sekutu yang gugur di medan pertempuran, kadar serangan kritikal serangan ini meningkat sebanyak 20%.',
		describe = 'The zombie activates the electromagnetic interference device and attacks the enemy\'s backline, dealing #C0x3D8A99#190% Magical Damage#C0x5B545B#+$(skillLevel*4*34)$#C0xF13B54# magic damage#C0x5B545B#. For each fallen allied hero on the field, the critical hit rate of this attack increases by 20%.',
		simDesc_vn = 'Zombie bay bật thiết bị gây nhiễu điện từ và tấn công các mục tiêu ở hàng sau của kẻ thù. Mỗi khi mất một tướng đồng minh trên sân, tỉ lệ chí mạng của đòn tấn công này sẽ cao hơn.',
		simDesc_en = 'The zombie activates the electromagnetic interference device and attacks the enemy\'s backline targets. Each time an allied hero on the field is lost, the critical strike chance of this attack increases.',
		simDesc_th = 'ซอมบี้เปิดใช้อุปกรณ์ก่อกวนคลื่นแม่เหล็กไฟฟ้าและโจมตียังเป้าหมายแถวหลังของศัตรู ทุกครั้งที่สูญเสียวีรบุรุษพันธมิตรหนึ่งคนในสนาม โอกาสคริติคอลของการโจมตีนี้จะเพิ่มสูงขึ้น',
		simDesc_in = 'Zombie mengaktifkan perangkat interferensi elektromagnetik dan menyerang target di barisan belakang musuh. Setiap kali seorang pahlawan sekutu di lapangan hilang, peluang serangan kritis dari serangan ini akan meningkat.',
		simDesc_ph = 'Ang zombie ay nag-activate ng electromagnet interference device at ini-atake ang mga target sa likod na linya ng kaaway. Sa tuwing mawawala ang isang kaalyadong bayani sa labanan, tataas ang critical strike chance ng pag-atakeng ito.',
		simDesc_ma = 'Zombie mengaktifkan peranti gangguan elektromagnet dan menyerang sasaran di barisan belakang musuh. Setiap kali seorang wira sekutu di medan tempur hilang, peluang serangan kritikal serangan ini akan meningkat.',
		simDesc = 'The zombie activates the electromagnetic interference device and attacks the enemy\'s backline targets. Each time an allied hero on the field is lost, the critical strike chance of this attack increases.',
		starEffect = __data_t__starEffect[33423],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Mỗi khi một anh hùng đồng minh bị mất trên sân, sát thương chí mạng của đợt tấn công này sẽ tăng thêm 20%.',
		starEffectDesc = 'Additional effect: Whenever an allied hero is lost on the field, the critical damage of this attack wave will increase by 20%.',
		starEffectDesc_en = 'Additional effect: Whenever an allied hero is lost on the field, the critical damage of this attack wave will increase by 20%.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: ทุกครั้งที่ฮีโร่พันธมิตรคนหนึ่งถูกทำลายบนสนาม ความเสียหายคริติคอลของคลื่นการโจมตีนี้จะเพิ่มขึ้นอีก 20%',
		starEffectDesc_in = 'Efek tambahan: Setiap kali pahlawan sekutu hilang di medan, kerusakan kritis dari gelombang serangan ini akan meningkat sebesar 20%.',
		starEffectDesc_ph = 'Karagdagang epekto: Sa tuwing may natalong kakampi na bayani sa larangan, tataas ng 20% ang kritikal na pinsala ng panibagong pag-atake.',
		starEffectDesc_ma = 'Kesan tambahan: Setiap kali wira sekutu hilang di medan, kerosakan kritikal gelombang serangan ini akan meningkat sebanyak 20%.',
		zawakeEffect = __data_t__zawakeEffect[33423],
		-- {79003}
		zawakeEffectDesc = 'Zombie bay activates an electromagnetic interference device and attacks the backline targets of the enemy, dealing #C0x3D8A99#190% Magical Damage#C0x5B545B#+$(skillLevel*4*34)$#C 0xF13B54#Spell Damage#C0x5B545B#. For each allied hero lost on the field, the critical strike rate of this attack will increase by 20%. The critical hit chance and additional critical damage effect will continue to last for 1 turn after the skill is cast.',
		zawakeEffectDesc_en = 'Zombie bay activates an electromagnetic interference device and attacks the backline targets of the enemy, dealing #C0x3D8A99#190% Magical Damage#C0x5B545B#+$(skillLevel*4*34)$#C 0xF13B54#Spell Damage#C0x5B545B#. For each allied hero lost on the field, the critical strike rate of this attack will increase by 20%. The critical hit chance and additional critical damage effect will continue to last for 1 turn after the skill is cast.',
		zawakeEffectDesc_th = 'ซอมบี้เบย์เปิดใช้อุปกรณ์รบกวนแม่เหล็กไฟฟ้าและโจมตีเป้าหมายแถวหลังของศัตรู ทำให้เกิด #C0x3D8A99#190% ความเสียหายเวทย์มนตร์#C0x5B545B#+$(skillLevel*4*34)$#C 0xF13B54#ความเสียหายจากเวทย์มนตร์#C0x5B545B# สำหรับฮีโร่พันธมิตรที่เสียชีวิตบนสนามโจมตีนี้จะเพิ่มอัตราคริติคอลขึ้นอีก 20% อัตราคริติคอลและผลของความเสียหายคริติคอลจะยังคงอยู่ต่ออีก 1 เทิร์นหลังจากใช้สกิล',
		zawakeEffectDesc_in = 'Zombie bay mengaktifkan perangkat gangguan elektromagnetik dan menyerang target di barisan belakang musuh, memberikan #C0x3D8A99#190% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*34)$#C 0xF13B54#Kerusakan Skill#C0x5B545B#. Untuk setiap pahlawan sekutu yang hilang di medan, tingkat serangan kritis dari serangan ini akan meningkat sebesar 20%. Peluang serangan kritis dan efek tambahan kerusakan kritis akan terus berlangsung selama 1 giliran setelah skill digunakan.',
		zawakeEffectDesc_ph = 'Pinapatakbo ng Zombie bay ang isang elektromagnetik na panghihimasok na aparato at inaatake ang mga target sa likurang hanay ng kalaban, na nagdudulot ng #C0x3D8A99#190% Pinsalang Salamangka#C0x5B545B#+$(skillLevel*4*34)$#C 0xF13B54#Pinsalang Spell#C0x5B545B#. Sa bawat nawalang alyadong bayani sa larangan, tataas ng 20% ang tsansa ng kritikal na atake ng salpok na ito. Ang tsansa ng kritikal na tama at karagdagang epektong pinsalang kritikal ay magpapatuloy ng 1 turn pagkatapos gamitin ang kakayahan.',
		zawakeEffectDesc_ma = 'Zombie bay mengaktifkan peranti gangguan elektromagnet dan menyerang sasaran di barisan belakang musuh, menyebabkan #C0x3D8A99#190% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*34)$#C 0xF13B54#Kerosakan Sihir#C0x5B545B#. Bagi setiap wira sekutu yang hilang di medan, kadar kritikal serangan ini akan meningkat sebanyak 20%. Kadar serangan kritikal dan kesan tambahan kerosakan kritikal akan berterusan selama 1 pusingan selepas skil dilancarkan.',
		zawakeEffectDesc_vn = 'Zombie bay bật thiết bị gây nhiễu điện từ và tấn công các mục tiêu ở hàng sau của kẻ địch, gây ra #C0x3D8A99#190% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*34)$#C 0xF13B54#Spell Damage#C0x5B545B#, với mỗi tướng đồng minh bị mất trên sân, tỷ lệ chí mạng của đòn tấn công này sẽ tăng thêm 20%. Tỷ lệ trúng đòn chí mạng và hiệu ứng cộng thêm sát thương chí mạng sẽ tiếp tục kéo dài trong 1 hiệp sau khi kỹ năng được tung ra.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Buffs that increase Crit Rate and Crit DMG will last 1 more turn after the skill is cast',
		zawakeSimpleDesc_en = '#C0x5c9970#Buffs that increase Crit Rate and Crit DMG will last 1 more turn after the skill is cast',
		zawakeSimpleDesc_th = '#C0x5c9970#บัฟเพิ่มคริติคอลและความเสียหายคริติคอลจะอยู่ต่ออีก 1 เทิร์นหลังใช้สกิล',
		zawakeSimpleDesc_in = '#C0x5c9970#Buff peningkat Crit Rate dan Crit DMG akan bertahan 1 giliran lebih lama setelah skill digunakan',
		zawakeSimpleDesc_ph = '#C0x5c9970#Ang buff na nagpapataas ng Crit Rate at Crit DMG ay tatagal ng dagdag 1 turn matapos gamitin ang skill',
