	[33513] = {
		id = 33513,
		skillName_vn = 'Gió tiên',
		skillName_en = 'Fairy Wind',
		skillName_th = 'ลมเทพธิดา',
		skillName_in = 'Angin Peri',
		skillName_ph = 'Hangin ng Diwata',
		skillName_ma = 'Angin Pari',
		skillName = 'Fairy Wind',
		describe_vn = 'Hoa Bội Bội triệu hồi gió tiên, nơi đi qua như được tắm trong gió xuân, tấn công toàn bộ mục tiêu kẻ địch, gây ra #C0x3D8A99#90% Công Phép#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, hồi máu cho toàn bộ phe ta bằng #C0x3D8A99#70% Công Phép#C0x5B545B#, tăng 50% lượng hồi máu cho hai đơn vị có máu thấp nhất',
		describe_en = 'Hoa Bội Bội summons the wind fairy, passing through like being bathed in spring breeze, attacking all enemy targets, dealing #C0x3D8A99#90% Magic Power#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, healing all allies for #C0x3D8A99#70% Magic Power#C0x5B545B#, and increasing healing received by the two lowest health units by 50%.',
		describe_th = 'ฮวาโบ่ยโบ่ยปลุกลมเทพ ผ่านไปเหมือนถูกอาบลมใบไม้ผลิ โจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวทมนตร์ #C0x3D8A99#90% พลังเวทมนตร์#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# ฟื้นฟูพลังชีวิตให้พันธมิตรทั้งหมดด้วย #C0x3D8A99#70% พลังเวทมนตร์#C0x5B545B# และเพิ่มการฟื้นฟูพลังชีวิต 50% ให้กับสองหน่วยที่มีพลังชีวิตต่ำที่สุด',
		describe_in = 'Hoa Bội Bội memanggil peri angin, melintasi seperti dimandikan angin musim semi, menyerang semua target musuh, memberikan #C0x3D8A99#90% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, menyembuhkan semua sekutu dengan #C0x3D8A99#70% Kekuatan Sihir#C0x5B545B#, serta meningkatkan jumlah penyembuhan sebesar 50% untuk dua unit dengan HP terendah.',
		describe_ph = 'Si Hoa Bội Bội ay summons ng hangin na engkanto, dumadaan na parang naliligo sa hangin ng tagsibol, ina-atake ang lahat ng kalaban, nagdudulot ng #C0x3D8A99#90% Lakas ng Mahika#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Pinsala ng Mahika #C0x5B545B#, nagpapagaling sa lahat ng kaalyado ng #C0x3D8A99#70% Lakas ng Mahika#C0x5B545B#, at pinapataas ng 50% ang halaga ng paggaling sa dalawang yunit na may pinakamababang HP.',
		describe_ma = 'Hoa Bội Bội memanggil pari angin, melewati seperti mandi angin musim bunga, menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#90% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Magik #C0x5B545B#, memulihkan kesihatan kepada semua rakan sepasukan dengan #C0x3D8A99#70% Kuasa Sihir#C0x5B545B#, dan meningkatkan jumlah pemulihan sebanyak 50% untuk dua unit dengan darah paling rendah.',
		describe = 'Hoa Bội Bội summons the wind fairy, passing through like being bathed in spring breeze, attacking all enemy targets, dealing #C0x3D8A99#90% Magic Power#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, healing all allies for #C0x3D8A99#70% Magic Power#C0x5B545B#, and increasing healing received by the two lowest health units by 50%.',
		simDesc_vn = 'Hoa Bội Bội triệu hồi gió tiên, nơi nào gió đến, như làn gió xuân, tấn công toàn bộ mục tiêu của kẻ thù và hồi phục một phần sinh lực cho toàn bộ đồng đội.',
		simDesc_en = 'Hua Boiboi summons the wind spirit; wherever the wind blows, like a spring breeze, it attacks all enemy targets and restores a portion of health to all allies.',
		simDesc_th = 'หัวโป้ยโป้ยเรียกวิญญาณลม ที่ใดที่ลมพัดมาถึง เหมือนสายลมฤดูใบไม้ผลิ โจมตีเป้าหมายศัตรูทั้งหมดและฟื้นฟูพลังชีวิตบางส่วนให้กับเพื่อนร่วมทีมทั้งหมด',
		simDesc_in = 'Hua Boiboi memanggil roh angin; di mana angin bertiup, seperti angin musim semi, menyerang semua target musuh dan memulihkan sebagian kesehatan untuk semua rekan satu tim.',
		simDesc_ph = 'Pinapatawag ni Hua Boiboi ang espiritu ng hangin; saan man dumampi ang hangin, tulad ng hanging tagsibol, inaatake ang lahat ng kalaban at nagpapagaling ng bahagi ng buhay para sa lahat ng kakampi.',
		simDesc_ma = 'Hua Boiboi memanggil roh angin; di mana angin bertiup, seperti angin musim bunga, menyerang semua sasaran musuh dan memulihkan sebahagian tenaga hidup untuk semua rakan sepasukan.',
		simDesc = 'Hua Boiboi summons the wind spirit; wherever the wind blows, like a spring breeze, it attacks all enemy targets and restores a portion of health to all allies.',
