	[34123] = {
		id = 34123,
		skillName_vn = 'Nhảy múa với song kiếm',
		skillName_en = 'Dance with dual swords',
		skillName_th = 'เต้นรำกับดาบคู่',
		skillName_in = 'Menari dengan pedang ganda',
		skillName_ph = 'Sumayaw gamit ang dalawang espada',
		skillName_ma = 'Menari dengan pedang berganda',
		skillName = 'Dance with dual swords',
		describe_vn = 'Vỏ kiếm đôi rút kiếm, phối hợp múa kiếm tấn công mục tiêu đơn của địch, gây ra #C0xE69900#370% Công Vật Lý#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#,\n#L10#Phát động ở hình thái phòng thủ:#L0#Chuyển sang hình thái tấn công, tăng 20% tốc độ cho toàn đội trong 1 lượt, bản thân tăng gấp đôi\n#L10#Phát động ở hình thái tấn công:#L0#Kèm theo hiệu ứng [Chém giết], bỏ qua 30% phòng thủ đôi của mục tiêu có phòng thủ đôi cơ bản thấp hơn bản thân, sau đó chuyển sang hình thái phòng thủ\nSau khi chuyển đổi hình thái, làm mới thời gian hồi chiêu kỹ năng nhỏ',
		describe_en = 'Sheathing twin swords to draw blades, coordinating sword dance to attack a single enemy target, dealing #C0xE69900#370% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Physical Damage#C0x5B545B#.\n#L10#Activated in defense stance:#L0#Switch to attack stance, increase team speed by 20% for 1 turn, self speed doubles.\n#L10#Activated in attack stance:#L0#Includes [Slashing] effect, ignoring 30% of dual defense for targets whose basic dual defense is lower than self, then switch to defense stance.\nAfter stance change, refresh cooldown of minor skill.',
		describe_th = 'ปลอกดาบคู่ค่อย ๆ ดึงดาบออก ร่วมกันร่ายรำดาบโจมตีเป้าหมายศัตรูเดียว สร้างความเสียหาย #C0xE69900#370% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B#.\n#L10#ใช้งานในท่ารับมือ:#L0#เปลี่ยนเป็นท่าโจมตี เพิ่มความเร็วทั้งทีม 20% เป็นเวลา 1 เทิร์น ความเร็วตนเองเพิ่มเป็นสองเท่า.\n#L10#ใช้งานในท่าโจมตี:#L0#มาพร้อมกับเอฟเฟกต์ [ฟันสังหาร] ข้าม 30% ของการป้องกันคู่ของเป้าหมายที่มีการป้องกันคู่พื้นฐานน้อยกว่าตนเอง จากนั้นเปลี่ยนเป็นท่ารับมือ.\nหลังเปลี่ยนท่า รีเฟรชเวลาคูลดาวน์ของทักษะเล็ก.',
		describe_in = 'Sarung pedang ganda ditarik, berkoordinasi menari pedang menyerang satu target musuh, menyebabkan #C0xE69900#370% Serangan Fisik#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#.\n#L10#Aktif dalam posisi bertahan:#L0#Beralih ke posisi menyerang, meningkatkan kecepatan tim sebesar 20% selama 1 giliran, kecepatan diri sendiri menjadi dua kali lipat.\n#L10#Aktif dalam posisi menyerang:#L0#Dilengkapi efek [Potongan Membunuh], mengabaikan 30% pertahanan ganda target yang pertahanan ganda dasarnya lebih rendah dari diri sendiri, lalu beralih ke posisi bertahan.\nSetelah berganti posisi, menyegarkan cooldown skill kecil.',
		describe_ph = 'Isinut ng dobleng espada, sabay-sabay na sa sayaw ng espada upang atakihin ang iisang target ng kalaban, nagdudulot ng #C0xE69900#370% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#.\n#L10#Aktibo sa anyo ng depensa:#L0#Lumipat sa anyo ng atake, dagdagan ang bilis ng buong koponan ng 20% sa loob ng 1 turn, ang sarili ay dumoble ang bilis.\n#L10#Aktibo sa anyo ng atake:#L0#Kasama ang epekto ng [Pagpuputol], nilalampasan ang 30% dobleng depensa ng target na may mababang dobleng depensa kumpara sa sarili, pagkatapos ay lumipat sa anyo ng depensa.\nPagkatapos ng pagbabago ng anyo, i-refresh ang cooldown ng maliit na kasanayan.',
		describe_ma = 'Sarung pedang berganda ditarik, bekerjasama menari pedang menyerang sasaran musuh tunggal, menyebabkan #C0xE69900#370% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#.\n#L10#Diaktifkan dalam bentuk pertahanan:#L0#Beralih ke bentuk serangan, meningkatkan kelajuan pasukan sebanyak 20% selama 1 giliran, kelajuan diri sendiri berganda.\n#L10#Diaktifkan dalam bentuk serangan:#L0#Disertakan kesan [Belah Pembunuh], mengabaikan 30% pertahanan berganda sasaran yang pertahanan berganda asasnya lebih rendah daripada diri sendiri, kemudian bertukar ke bentuk pertahanan.\nSelepas pertukaran bentuk, segarkan masa cooldown kemahiran kecil.',
		describe = 'Sheathing twin swords to draw blades, coordinating sword dance to attack a single enemy target, dealing #C0xE69900#370% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Physical Damage#C0x5B545B#.\n#L10#Activated in defense stance:#L0#Switch to attack stance, increase team speed by 20% for 1 turn, self speed doubles.\n#L10#Activated in attack stance:#L0#Includes [Slashing] effect, ignoring 30% of dual defense for targets whose basic dual defense is lower than self, then switch to defense stance.\nAfter stance change, refresh cooldown of minor skill.',
		simDesc_vn = 'Song Kiếm Sương rút hai thanh kiếm ra, phối hợp thực hiện những động tác tấn công vào mục tiêu đơn lẻ của kẻ thù.',
		simDesc_en = 'Song Kiem Suong draws two swords, coordinating attacks against a single enemy target.',
		simDesc_th = 'ซองคีมซวงดึงดาบสองเล่มออกมา ประสานการโจมตีไปยังเป้าหมายเดียวของศัตรู',
		simDesc_in = 'Song Kiem Suong menghunus dua pedang, melakukan serangan terkoordinasi ke satu target musuh.',
		simDesc_ph = 'Inilabas ni Song Kiem Suong ang dalawang espada, at isinagawa ang mga koordinadong pag-atake sa isang target na kalaban.',
		simDesc_ma = 'Song Kiem Suong mengeluarkan dua pedang, melakukan serangan berkoordinasi ke sasaran musuh tunggal.',
		simDesc = 'Song Kiem Suong draws two swords, coordinating attacks against a single enemy target.',
		starEffect = __data_t__starEffect[34123],
		-- {11}
		starEffectDesc_vn = '\n#L10#Hình thái tấn công giải phóng: #L0#Trước khi tấn công, hấp thụ 8% công đôi của đồng minh khác trong 1 lượt\n#L10#Hình thái phòng thủ giải phóng: #L0#Giảm 20% tỷ lệ chí mạng của kẻ địch ở hàng sau trong 2 lượt',
		starEffectDesc = '\n#L10#Release Attack Mode: #L0#Before attacking, absorb 8% of the double attack power from other allies for 1 turn\n#L10#Release Defense Mode: #L0#Reduce the critical rate of backline enemies by 20% for 2 turns',
		starEffectDesc_en = '\n#L10#Release Attack Mode: #L0#Before attacking, absorb 8% of the double attack power from other allies for 1 turn\n#L10#Release Defense Mode: #L0#Reduce the critical rate of backline enemies by 20% for 2 turns',
		starEffectDesc_th = '\n#L10#รูปแบบการโจมตีปลดปล่อย: #L0#ก่อนโจมตี ดูดซับพลังโจมตีคู่ 8% จากพันธมิตรคนอื่นเป็นเวลา 1 เทิร์น\n#L10#รูปแบบการป้องกันปลดปล่อย: #L0#ลดอัตราคริติคอลของศัตรูแถวหลังลง 20% เป็นเวลา 2 เทิร์น',
		starEffectDesc_in = '\n#L10#Mode Serangan Lepas: #L0#Sebelum menyerang, serap 8% kekuatan serangan dobel dari sekutu lain selama 1 giliran\n#L10#Mode Pertahanan Lepas: #L0#Mengurangi tingkat kritikal musuh di baris belakang sebesar 20% selama 2 giliran',
		starEffectDesc_ph = '\n#L10#Release Attack Mode: #L0#Bago umatake, sumisipsip ng 8% na dobleng lakas ng atake mula sa ibang mga alyado sa loob ng 1 turn\n#L10#Release Defense Mode: #L0#Bawasan ang critical rate ng mga kalaban sa likuran ng 20% sa loob ng 2 na turn',
		starEffectDesc_ma = '\n#L10#Mod Serangan Bebas: #L0#Sebelum menyerang, serap 8% kuasa serangan berganda dari sekutu lain selama 1 giliran\n#L10#Mod Pertahanan Bebas: #L0#Kurangkan kadar kritikal musuh di barisan belakang sebanyak 20% selama 2 giliran',
		zawakeSimpleDesc = 'Defense Stance: Increases the dual defense of the independent scabbard by 20%\nAttack Stance: Absorbs 10% of other allies\' Physical ATK before attacking for 1 turn\n',
		zawakeSimpleDesc_en = 'Defense Stance: Increases the dual defense of the independent scabbard by 20%\nAttack Stance: Absorbs 10% of other allies\' Physical ATK before attacking for 1 turn\n',
		zawakeSimpleDesc_th = 'ท่าป้องกัน: เพิ่มค่าป้องกันคู่ของปลอกดาบอิสระ 20%\nท่ารุก: ดูดซับพลังโจมตีกายภาพ 10% ของพันธมิตรอื่นก่อนโจมตีใน 1 เทิร์น\n',
		zawakeSimpleDesc_in = 'Mode Bertahan: Meningkatkan pertahanan ganda sarung pedang independen sebesar 20%\nMode Serang: Menyerap 10% ATK Fisik dari sekutu lain sebelum menyerang selama 1 giliran\n',
		zawakeSimpleDesc_ph = 'Defense Stance: Dagdag 20% dual defense ng independent scabbard\nAttack Stance: Sinasagap 10% Physical ATK ng ibang kakampi bago umatake sa loob ng 1 turn\n',
