	[34126] = {
		id = 34126,
		skillName_vn = 'Kiếm - Thủ',
		skillName_en = 'Sword - Guard',
		skillName_th = 'ดาบ - ป้องกัน',
		skillName_in = 'Pedang - Penjaga',
		skillName_ph = 'Tabak - Bantay',
		skillName_ma = 'Pedang - Penjaga',
		skillName = 'Sword - Guard',
		describe_vn = '#L10#Hình thức tấn công: #L0#Phòng thủ kép cơ bản giảm 30%, tấn công kép cơ bản tăng#C0x5c9970#$(10+Cấp kỹ năng*0.2-0.2)$%#C0 x5B545B#; Khi bên thiện chiến thực hiện một đòn tấn công cơ bản, họ sẽ tham gia vào [Chiến đấu phối hợp] (Chiến đấu phối hợp: Cùng nhau tấn công mục tiêu của cuộc tấn công chung của thiện chiến)\n#L10#Hình thức phòng thủ: #L0#Đòn tấn công kép cơ bản giảm 30% và tỷ lệ kháng cự tăng lên# C0x5c9970#$(30+skillLevel*0.4-0.4)$%#C0x5B545B#; Khi tỷ lệ máu của bản thân lớn hơn 20%, [Bảo vệ] anh hùng có giá trị máu thấp nhất trong số các đồng minh ngoại trừ chính bạn (Bảo vệ: Nếu bạn không ở trạng thái bất lực, nó sẽ giảm 20% sát thương khi bị tấn công và chống lại 80% sát thương)\n (Mục nhập ban đầu ở dạng phòng thủ)',
		describe_en = '#L10#Attack type: #L0#Basic double defense reduced by 30%, basic double attack increased by #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0 x5B545B#; When the warrior performs a basic attack, they will participate in [Cooperative Combat] (Cooperative Combat: Jointly attack the target of the warrior\'s combined attack)\n#L10#Defense type: #L0#Basic double attack reduced by 30% and resistance rate increased by #C0x5c9970#$(30+skillLevel*0.4-0.4)$%#C0x5B545B#; When own HP is above 20%, [Protect] the ally with the lowest HP among all allies except yourself (Protect: If you are not incapacitated, reduces damage taken by 20% and blocks 80% of damage)\n (Initially in defense form)',
		describe_th = '#L10#รูปแบบการโจมตี: #L0#การป้องกันแบบคู่พื้นฐานลดลง 30%, การโจมตีแบบคู่พื้นฐานเพิ่มขึ้น #C0x5c9970#$(10+ระดับทักษะ*0.2-0.2)$%#C0 x5B545B#; เมื่อผู้รบทำการโจมตีพื้นฐาน จะเข้าร่วมใน [การต่อสู้ร่วม] (การต่อสู้ร่วม: ร่วมกันโจมตีเป้าหมายของการโจมตีร่วมของผู้รบ)\n#L10#รูปแบบการป้องกัน: #L0#การโจมตีแบบคู่พื้นฐานลดลง 30% และอัตราการต้านทานเพิ่มขึ้น #C0x5c9970#$(30+ระดับทักษะ*0.4-0.4)$%#C0x5B545B#; เมื่อพลังชีวิตของตนเองมากกว่า 20%, [ปกป้อง] ฮีโร่ที่มีพลังชีวิตต่ำที่สุดในหมู่พันธมิตรยกเว้นตัวคุณเอง (ปกป้อง: หากคุณไม่อยู่ในสถานะหมดสติ จะลดความเสียหายที่ได้รับ 20% และต้านทานความเสียหาย 80%)\n (รายการเดิมในรูปแบบป้องกัน)',
		describe_in = '#L10#Jenis serangan: #L0#Pertahanan ganda dasar berkurang 30%, serangan ganda dasar meningkat #C0x5c9970#$(10+Level Keterampilan*0.2-0.2)$%#C0 x5B545B#; Saat pejuang melakukan serangan dasar, mereka akan berpartisipasi dalam [Pertempuran Koordinasi] (Pertempuran Koordinasi: Bersama-sama menyerang target dari serangan gabungan pejuang)\n#L10#Jenis pertahanan: #L0#Serangan ganda dasar berkurang 30% dan tingkat ketahanan meningkat #C0x5c9970#$(30+Level Skill*0.4-0.4)$%#C0x5B545B#; Saat HP sendiri di atas 20%, [Lindungi] pahlawan dengan HP terendah di antara sekutu kecuali diri sendiri (Lindungi: Jika kamu tidak dalam keadaan lumpuh, akan mengurangi 20% kerusakan saat diserang dan menahan 80% kerusakan)\n (Entri awal dalam bentuk pertahanan)',
		describe_ph = '#L10#Uri ng pag-atake: #L0#Basic double defense bumaba ng 30%, basic double attack tumaas ng #C0x5c9970#$(10+Level ng Kasanayan*0.2-0.2)$%#C0 x5B545B#; Kapag ang mandirigma ay gumawa ng basic attack, sasali sila sa [Kooperatibong Labanan] (Kooperatibong Labanan: Sama-samang inaatake ang target ng pinagsamang atake ng mandirigma)\n#L10#Uri ng depensa: #L0#Basic double attack bumaba ng 30% at tumaas ang rate ng resistensya #C0x5c9970#$(30+Level ng Kasanayan*0.4-0.4)$%#C0x5B545B#; Kapag ang sariling HP ay higit sa 20%, [Proteksyon] sa bayani na may pinakamababang HP sa mga kakampi maliban sa sarili mo (Proteksyon: Kung hindi ka paralisado, binabawasan nito ang damage na natatanggap ng 20% at nilalabanan ang 80% ng damage)\n (Orihinal na entry sa anyo ng depensa)',
		describe_ma = '#L10#Jenis serangan: #L0#Pertahanan ganda asas berkurang 30%, serangan ganda asas meningkat #C0x5c9970#$(10+Tahap Kemahiran*0.2-0.2)$%#C0 x5B545B#; Apabila pahlawan melakukan serangan asas, mereka akan menyertai [Pertempuran Berkumpulan] (Pertempuran Berkumpulan: Bersama-sama menyerang sasaran serangan bergabung pahlawan)\n#L10#Jenis pertahanan: #L0#Serangan ganda asas berkurang 30% dan kadar ketahanan meningkat #C0x5c9970#$(30+Tahap Kemahiran*0.4-0.4)$%#C0x5B545B#; Apabila HP sendiri melebihi 20%, [Lindungi] pahlawan dengan HP terendah antara sekutu kecuali diri sendiri (Lindungi: Jika anda tidak dalam keadaan lumpuh, ia mengurangkan kerosakan diterima sebanyak 20% dan menahan 80% kerosakan)\n (Entri asal dalam bentuk pertahanan)',
		describe = '#L10#Attack type: #L0#Basic double defense reduced by 30%, basic double attack increased by #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0 x5B545B#; When the warrior performs a basic attack, they will participate in [Cooperative Combat] (Cooperative Combat: Jointly attack the target of the warrior\'s combined attack)\n#L10#Defense type: #L0#Basic double attack reduced by 30% and resistance rate increased by #C0x5c9970#$(30+skillLevel*0.4-0.4)$%#C0x5B545B#; When own HP is above 20%, [Protect] the ally with the lowest HP among all allies except yourself (Protect: If you are not incapacitated, reduces damage taken by 20% and blocks 80% of damage)\n (Initially in defense form)',
		starEffect = __data_t__starEffect[34126],
		-- {8}
