	[34133] = {
		id = 34133,
		skillName_vn = 'Nhảy múa với kiếm và khiên',
		skillName_en = 'Dancing with swords and shields',
		skillName_th = 'เต้นรำกับดาบและโล่',
		skillName_in = 'Menari dengan pedang dan perisai',
		skillName_ph = 'Sumasayaw gamit ang mga espada at kalasag',
		skillName_ma = 'Menari dengan pedang dan perisai',
		skillName = 'Dancing with swords and shields',
		describe_vn = 'Kiếm chắn quái vật tách rời kiếm và khiên phối hợp múa kiếm tấn công mục tiêu đơn của địch, gây ra #C0xE69900#380% Công Vật Lý#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#,\n#L10#Phát động ở hình thái khiên:#L0#Chuyển sang hình thái kiếm, tăng 20% tốc độ cho toàn đội trong 1 lượt, bản thân tăng gấp đôi\n#L10#Phát động ở hình thái kiếm:#L0#Kèm theo hiệu ứng [Chém giết], bỏ qua 30% phòng thủ đôi của mục tiêu có phòng thủ đôi cơ bản thấp hơn bản thân, sau đó chuyển sang hình thái khiên\nSau khi chuyển đổi hình thái, làm mới thời gian hồi chiêu kỹ năng nhỏ',
		describe_en = 'The monster-blocking sword separates the sword and shield, coordinating sword dances to attack a single enemy target, dealing #C0xE69900#380% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Physical Damage#C0x5B545B#. \n#L10#Activated in shield form:#L0#Switch to sword form, increasing the entire team\'s speed by 20% for 1 turn, self speed doubled. \n#L10#Activated in sword form:#L0#Accompanied by [Slashing] effect, ignores 30% dual defense of targets whose dual defense is lower than own, then switches to shield form. \n After switching forms, refresh the cooldown of the minor skill.',
		describe_th = 'ดาบที่ป้องกันมอนสเตอร์แยกดาบและโล่ ร่วมมือเต้นรำดาบโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0xE69900#380% การโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B#. \n#L10#เปิดใช้งานในรูปแบบโล่:#L0#เปลี่ยนเป็นรูปแบบดาบ เพิ่มความเร็วของทีมทั้งหมด 20% เป็นเวลา 1 เทิร์น ความเร็วของตนเองเพิ่มเป็นสองเท่า \n#L10#เปิดใช้งานในรูปแบบดาบ:#L0#มาพร้อมกับเอฟเฟกต์ [ฟัน] ข้ามการป้องกันคู่ 30% ของเป้าหมายที่มีการป้องกันคู่ต่ำกว่าตนเอง จากนั้นเปลี่ยนเป็นรูปแบบโล่ \n หลังจากเปลี่ยนรูปแบบ จะรีเฟรชเวลาคูลดาวน์ของสกิลเล็ก',
		describe_in = 'Pedang pemblokir monster memisahkan pedang dan perisai, mengkoordinasikan tarian pedang untuk menyerang satu target musuh, memberikan #C0xE69900#380% Serangan Fisik#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. \n#L10#Diaktifkan dalam bentuk perisai:#L0#Beralih ke bentuk pedang, meningkatkan kecepatan seluruh tim sebesar 20% selama 1 giliran, kecepatan diri sendiri menjadi dua kali lipat \n#L10#Diaktifkan dalam bentuk pedang:#L0#Disertai efek [Tebas], mengabaikan 30% pertahanan ganda target yang pertahanan gandanya lebih rendah dari diri sendiri, kemudian beralih ke bentuk perisai \n Setelah beralih bentuk, segarkan waktu cooldown keterampilan kecil.',
		describe_ph = 'Ang espada na humahadlang sa halimaw ay naghihiwalay sa espada at kalasag, nagsasama ng sayaw ng espada upang atakihin ang isang target na kalaban, nagdudulot ng #C0xE69900#380% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. \n#L10#Na-activate sa anyo ng kalasag:#L0#Lumipat sa anyo ng espada, pinapataas ang bilis ng buong koponan ng 20% sa loob ng 1 turn, doble ang bilis ng sarili \n#L10#Na-activate sa anyo ng espada:#L0#Kasama ang epekto ng [Pagputol], nilalampasan ang 30% na dobleng depensa ng target na may dobleng depensang mas mababa kaysa sa sarili, pagkatapos ay lumilipat sa anyo ng kalasag \n Pagkatapos ng pagpapalit ng anyo, ire-refresh ang cooldown ng maliit na kasanayan.',
		describe_ma = 'Pedang penahan raksasa memisahkan pedang dan perisai, menggabungkan tarian pedang menyerang sasaran tunggal musuh, menyebabkan #C0xE69900#380% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. \n#L10#Diaktifkan dalam bentuk perisai:#L0#Beralih ke bentuk pedang, meningkatkan kelajuan seluruh pasukan sebanyak 20% selama 1 giliran, diri sendiri menggandakan kelajuan \n#L10#Diaktifkan dalam bentuk pedang:#L0#Disertai kesan [Tebasan], mengabaikan 30% pertahanan berganda sasaran yang pertahanan bergandanya lebih rendah daripada diri sendiri, kemudian beralih ke bentuk perisai \n Selepas bertukar bentuk, segar semula masa sejuk kemahiran kecil.',
		describe = 'The monster-blocking sword separates the sword and shield, coordinating sword dances to attack a single enemy target, dealing #C0xE69900#380% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Physical Damage#C0x5B545B#. \n#L10#Activated in shield form:#L0#Switch to sword form, increasing the entire team\'s speed by 20% for 1 turn, self speed doubled. \n#L10#Activated in sword form:#L0#Accompanied by [Slashing] effect, ignores 30% dual defense of targets whose dual defense is lower than own, then switches to shield form. \n After switching forms, refresh the cooldown of the minor skill.',
		simDesc_vn = 'Kiên ĐShield Kiếm Quái tách rời kiếm và khiên, phối hợp thực hiện những động tác tấn công vào mục tiêu đơn lẻ của kẻ thù.',
		simDesc_en = 'The Knight\'s Shield Sword separates the sword and shield, coordinating attacks on a single enemy target.',
		simDesc_th = 'เกราะและดาบของอัศวินแยกออกจากกัน พร้อมประสานการโจมตีไปยังเป้าหมายเดียวของศัตรู',
		simDesc_in = 'Pedang Perisai Ksatria memisahkan pedang dan perisai, mengoordinasikan serangan pada satu target musuh.',
		simDesc_ph = 'Ang Knight\'s Shield Sword ay naghihiwalay ng espada at kalasag, na inaayos ang pag-atake sa isang target ng kalaban.',
		simDesc_ma = 'Pedang Perisai Kesatria memisahkan pedang dan perisai, menyelaraskan serangan pada satu sasaran musuh.',
		simDesc = 'The Knight\'s Shield Sword separates the sword and shield, coordinating attacks on a single enemy target.',
		starEffect = __data_t__starEffect[34133],
		-- {11}
		starEffectDesc_vn = '\n#L10#Hình thái kiếm giải phóng: #L0#Trước khi tấn công, hấp thụ 8% công đôi của đồng minh khác trong 1 lượt\n#L10#Hình thái khiên giải phóng: #L0#Giảm 20% tỷ lệ chí mạng của kẻ địch ở hàng sau trong 2 lượt',
		starEffectDesc = '\n#L10#Liberation Sword Mode: #L0#Before attacking, absorb 8% of another ally\'s double attack for 1 turn\n#L10#Liberation Shield Mode: #L0#Reduces the critical hit rate of back row enemies by 20% for 2 turns',
		starEffectDesc_en = '\n#L10#Liberation Sword Mode: #L0#Before attacking, absorb 8% of another ally\'s double attack for 1 turn\n#L10#Liberation Shield Mode: #L0#Reduces the critical hit rate of back row enemies by 20% for 2 turns',
		starEffectDesc_th = '\n#L10#โหมดดาบปลดปล่อย: #L0#ก่อนโจมตี ดึงดูด 8% ของการโจมตีคู่ของพันธมิตรอื่นเป็นเวลา 1 เทิร์น\n#L10#โหมดโล่ปลดปล่อย: #L0#ลดอัตราคริติคอลของศัตรูแถวหลังลง 20% เป็นเวลา 2 เทิร์น',
		starEffectDesc_in = '\n#L10#Mode Pedang Pembebasan: #L0#Sebelum menyerang, menyerap 8% serangan ganda dari sekutu lain selama 1 giliran\n#L10#Mode Perisai Pembebasan: #L0#Mengurangi tingkat kritis musuh di baris belakang sebesar 20% selama 2 giliran',
		starEffectDesc_ph = '\n#L10#Paraang Kalayaan na Mode: #L0#Bago umatake, sumipsip ng 8% na doble na atake ng ibang kaalyado sa loob ng 1 turn\n#L10#Kalayang Kalasag na Mode: #L0#Binabawasan ang 20% na tsansa ng kritikal ng mga kalabang nasa likuran sa loob ng 2 turn',
		starEffectDesc_ma = '\n#L10#Mod Pedang Pembebasan: #L0#Sebelum menyerang, menyerap 8% serangan berganda sekutu lain selama 1 pusingan\n#L10#Mod Perisai Pembebasan: #L0#Mengurangkan kadar kritikal musuh di barisan belakang sebanyak 20% selama 2 pusingan',
		zawakeSimpleDesc = 'Defense Stance: Increases the dual defense of the independent scabbard by 20%\nAttack Stance: Absorbs 10% of other allies\' Physical ATK before attacking for 1 turn\n',
		zawakeSimpleDesc_en = 'Defense Stance: Increases the dual defense of the independent scabbard by 20%\nAttack Stance: Absorbs 10% of other allies\' Physical ATK before attacking for 1 turn\n',
		zawakeSimpleDesc_th = 'ท่าป้องกัน: เพิ่มค่าป้องกันคู่ของปลอกดาบอิสระ 20%\nท่ารุก: ดูดซับพลังโจมตีกายภาพ 10% ของพันธมิตรอื่นก่อนโจมตีใน 1 เทิร์น\n',
		zawakeSimpleDesc_in = 'Mode Bertahan: Meningkatkan pertahanan ganda sarung pedang independen sebesar 20%\nMode Serang: Menyerap 10% ATK Fisik dari sekutu lain sebelum menyerang selama 1 giliran\n',
		zawakeSimpleDesc_ph = 'Defense Stance: Dagdag 20% dual defense ng independent scabbard\nAttack Stance: Sinasagap 10% Physical ATK ng ibang kakampi bago umatake sa loob ng 1 turn\n',
		zawakeSimpleDesc_ma = 'Kedudukan Pertahanan: Meningkatkan pertahanan berganda sarung pedang bebas sebanyak 20%\nKedudukan Serangan: Menyerap 10% Serangan Fizikal sekutu lain sebelum menyerang selama 1 pusingan\n',
		zawakeSimpleDesc_vn = 'Trạng thái phòng thủ: Tăng 20% phòng thủ kép của vỏ kiếm độc lập\nTrạng thái tấn công: Hấp thụ 10% Công Vật Lý của đồng minh khác trước khi tấn công trong 1 lượt\n',
