	[34136] = {
		id = 34136,
		skillName_vn = 'Kiếm - Khiên',
		skillName_en = 'Sword - Shield',
		skillName_th = 'ดาบ - โล่',
		skillName_in = 'Pedang - Perisai',
		skillName_ph = 'Espada - Kalasag',
		skillName_ma = 'Pedang - Perisai',
		skillName = 'Sword - Shield',
		describe_vn = '#L10#Dạng kiếm: #L0#Phòng thủ kép cơ bản giảm 30%, tấn công kép cơ bản tăng#C0x5c9970#$(10+Cấp kỹ năng*0.2-0.2)$%#C0 x5B545B#; Khi bên đồng minh thực hiện một đòn tấn công cơ bản, họ sẽ tham gia vào [Hợp tác] (Hợp tác: cùng tấn công mục tiêu của đòn tấn công cơ bản đồng minh)\n#L10# Dạng khiên: #L0# Đòn tấn công kép cơ bản giảm 30% và tỷ lệ kháng cự tăng lên# C0x5c9970#$(30+skillLevel*0.4-0.4)$%#C0x5B545B#; Khi tỷ lệ máu của bản thân lớn hơn 20%, [Bảo vệ] anh hùng có lượng máu thấp nhất trong số các đồng minh ngoại trừ chính bạn (Bảo vệ: Nếu bạn không ở trạng thái bất lực, nó sẽ giảm 20% sát thương khi bị tấn công và chống lại 80% sát thương)\n (Ban đầu nhập ở dạng khiên)',
		describe_en = '#L10#Sword Form: #L0#Basic double defense reduced by 30%, basic double attack increased by #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#; When an ally performs a basic attack, they will join [Cooperation] (Cooperation: jointly attack the target of the ally’s basic attack)\n#L10#Shield Form: #L0#Basic double attack reduced by 30% and resistance rate increased by #C0x5c9970#$(30+skillLevel*0.4-0.4)$%#C0x5B545B#; When your own HP is above 20%, [Protect] the ally hero with the lowest HP except yourself (Protect: If you are not incapacitated, it reduces damage taken by 20% and blocks 80% of damage)\n (Initially entered in Shield Form)',
		describe_th = '#L10#รูปแบบดาบ: #L0#การป้องกันคู่พื้นฐานลดลง 30% การโจมตีคู่พื้นฐานเพิ่มขึ้น #C0x5c9970#$(10+ระดับทักษะ*0.2-0.2)$%#C0x5B545B#; เมื่อพันธมิตรทำการโจมตีพื้นฐาน พวกเขาจะเข้าร่วม [ความร่วมมือ] (ความร่วมมือ: โจมตีเป้าหมายของการโจมตีพื้นฐานของพันธมิตรพร้อมกัน)\n#L10#รูปแบบโล่: #L0#การโจมตีคู่พื้นฐานลดลง 30% และอัตราการต้านทานเพิ่มขึ้น #C0x5c9970#$(30+ระดับทักษะ*0.4-0.4)$%#C0x5B545B#; เมื่อพลังชีวิตของคุณมากกว่า 20%, [ปกป้อง] ฮีโร่พันธมิตรที่มีพลังชีวิตต่ำที่สุด ยกเว้นตัวคุณเอง (ปกป้อง: หากคุณไม่ได้อยู่ในสถานะหมดสติ จะลดความเสียหายที่ได้รับลง 20% และป้องกันความเสียหาย 80%)\n (เริ่มต้นเข้ารูปแบบโล่)',
		describe_in = '#L10#Form Pedang: #L0#Pertahanan ganda dasar dikurangi 30%, serangan ganda dasar meningkat sebesar #C0x5c9970#$(10+Level Skill*0.2-0.2)$%#C0x5B545B#; Ketika sekutu melakukan serangan dasar, mereka akan ikut [Kerjasama] (Kerjasama: menyerang bersama target serangan dasar sekutu)\n#L10#Form Perisai: #L0#Serangan ganda dasar dikurangi 30% dan tingkat ketahanan meningkat sebesar #C0x5c9970#$(30+Level Skill*0.4-0.4)$%#C0x5B545B#; Ketika HP kamu di atas 20%, [Lindungi] pahlawan sekutu dengan HP terendah kecuali diri sendiri (Lindungi: Jika kamu tidak dalam keadaan lumpuh, mengurangi 20% kerusakan yang diterima dan menahan 80% kerusakan)\n (Awalnya masuk dalam bentuk perisai)',
		describe_ph = '#L10#Anyo ng Espada: #L0#Pangunahing dobleng depensa nabawasan ng 30%, pangunahing dobleng atake tumaas ng #C0x5c9970#$(10+Antas ng Kasanayan*0.2-0.2)$%#C0x5B545B#; Kapag ang isang kakampi ay gumawa ng pangunahing atake, sila ay sasali sa [Pagtutulungan] (Pagtutulungan: sabay na atakihin ang target ng pangunahing atake ng kakampi)\n#L10#Anyo ng Kalasag: #L0#Pangunahing dobleng atake nabawasan ng 30% at tumaas ang rate ng pagtutol ng #C0x5c9970#$(30+Antas ng Kasanayan*0.4-0.4)$%#C0x5B545B#; Kapag ang sarili mong HP ay higit sa 20%, [Protektahan] ang kakampi na may pinakamababang HP maliban sa iyo (Protektahan: Kung hindi ka paralizado, babawasan nito ang 20% pinsalang matatanggap at haharangan ang 80% pinsala)\n (Unang pumasok sa Anyo ng Kalasag)',
		describe_ma = '#L10#Bentuk Pedang: #L0#Pertahanan berganda asas dikurangkan sebanyak 30%, serangan berganda asas meningkat sebanyak #C0x5c9970#$(10+Tahap Kemahiran*0.2-0.2)$%#C0x5B545B#; Apabila sekutu melakukan serangan asas, mereka akan menyertai [Kerjasama] (Kerjasama: menyerang sasaran serangan asas sekutu bersama-sama)\n#L10#Bentuk Perisai: #L0#Serangan berganda asas dikurangkan sebanyak 30% dan kadar ketahanan meningkat sebanyak #C0x5c9970#$(30+Tahap Kemahiran*0.4-0.4)$%#C0x5B545B#; Apabila HP anda melebihi 20%, [Lindungi] wira sekutu dengan HP terendah kecuali diri anda sendiri (Lindungi: Jika anda tidak dalam keadaan lumpuh, ia mengurangkan 20% kerosakan yang diterima dan menahan 80% kerosakan)\n (Pada mulanya masuk dalam bentuk perisai)',
		describe = '#L10#Sword Form: #L0#Basic double defense reduced by 30%, basic double attack increased by #C0x5c9970#$(10+skillLevel*0.2-0.2)$%#C0x5B545B#; When an ally performs a basic attack, they will join [Cooperation] (Cooperation: jointly attack the target of the ally’s basic attack)\n#L10#Shield Form: #L0#Basic double attack reduced by 30% and resistance rate increased by #C0x5c9970#$(30+skillLevel*0.4-0.4)$%#C0x5B545B#; When your own HP is above 20%, [Protect] the ally hero with the lowest HP except yourself (Protect: If you are not incapacitated, it reduces damage taken by 20% and blocks 80% of damage)\n (Initially entered in Shield Form)',
