		skillName_in = 'Napas Naga',
		skillName_ph = 'Hininga ng Dragon',
		skillName_ma = 'Nafas Naga',
		skillName = 'Dragon\'s Breath',
		describe_vn = 'Nhầy Nhụa Bảo thổi hơi mạnh vào mục tiêu hàng ngang của kẻ địch, gây ra #C0x3D8A99#200% Công Phép#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, tăng Phép Phòng từ Nhầy Mỹ Long 100% và giảm Sát Thương Phép Thuật 15% cho toàn bộ đồng minh trong 2 lượt, trong thời gian này giảm một nửa tất cả hiệu ứng tiêu cực của phe ta',
		describe_en = 'Slimy Ba blowing a strong gust horizontally at enemy targets, causing #C0x3D8A99#200% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, increasing Magic Defense from Slimy Dragon by 100% and reducing Magic Damage by 15% for all allies for 2 turns, meanwhile halving all negative effects on our side during this time.',
		describe_th = 'หนองเหนียวเมืองเป่าลมแรงในแนวระนาบไปยังเป้าหมายของศัตรู ทำให้เกิด #C0x3D8A99#200% พลังเวท#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# เพิ่มการป้องกันเวทมนตร์จากหนองเหนียวมังกร 100% และลดความเสียหายเวทมนตร์ 15% ให้กับพันธมิตรทั้งหมดเป็นเวลา 2 เทิร์น ในช่วงเวลานี้ลดผลลบทั้งหมดของฝ่ายเราไปครึ่งหนึ่ง',
		describe_in = 'Slimy Bao meniup angin kuat secara horizontal ke target musuh, menyebabkan #C0x3D8A99#200% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, meningkatkan Pertahanan Sihir dari Slimy Dragon sebesar 100% dan mengurangi Kerusakan Sihir sebesar 15% untuk semua sekutu selama 2 giliran, selama waktu ini mengurangi semua efek negatif dari pihak kita menjadi setengahnya.',
		describe_ph = 'Si Slimy Bao ay malakas na humihip ng hangin pahalang sa mga kalaban, nagdudulot ng #C0x3D8A99#200% Lakas ng Magic#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Damage ng Magic #C0x5B545B#, nagpapataas ng Magic Defense mula kay Slimy Dragon ng 100% at nagpapababa ng Magic Damage ng 15% para sa lahat ng kakampi sa loob ng 2 rounds, habang binabawasan ng kalahati ang lahat ng negatibong epekto ng ating panig sa panahong ito.',
		describe_ma = 'Slimy Bao meniup angin kuat secara mendatar ke sasaran musuh, menyebabkan #C0x3D8A99#200% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, meningkatkan Pertahanan Sihir dari Slimy Dragon sebanyak 100% dan mengurangkan Kerosakan Sihir sebanyak 15% untuk semua sekutu selama 2 pusingan, dalam tempoh ini mengurangkan semua kesan negatif pihak kami sebanyak separuh.',
		describe = 'Slimy Ba blowing a strong gust horizontally at enemy targets, causing #C0x3D8A99#200% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, increasing Magic Defense from Slimy Dragon by 100% and reducing Magic Damage by 15% for all allies for 2 turns, meanwhile halving all negative effects on our side during this time.',
		simDesc_vn = 'Nhão Nhão Bảo thổi một luồng khí mạnh mẽ vào mục tiêu ở hàng sau của kẻ thù, tăng cường khả năng phòng thủ phép và giảm sát thương phép cho toàn bộ đồng đội.',
		starEffect = __data_t__starEffect[35413],
		-- {11}
		starEffectDesc_vn = 'Tăng 20% giảm sát thương phép cho toàn đội, kéo dài 2 lượt.',
		starEffectDesc = 'Increase magic damage reduction for the entire team by 20%, lasting 2 turns.',
		starEffectDesc_en = 'Increase magic damage reduction for the entire team by 20%, lasting 2 turns.',
		starEffectDesc_th = 'เพิ่มการลดความเสียหายเวทมนตร์ให้กับทีมทั้งหมด 20% เป็นเวลา 2 ตา',
		starEffectDesc_in = 'Meningkatkan pengurangan kerusakan sihir untuk seluruh tim sebesar 20%, berlangsung selama 2 giliran.',
		starEffectDesc_ph = 'Dagdagan ang pagbawas ng pinsalang mahika para sa buong koponan ng 20%, tatagal ng 2 na turn.',
		starEffectDesc_ma = 'Meningkatkan pengurangan kerosakan sihir untuk seluruh pasukan sebanyak 20%, berlangsung selama 2 giliran.',
		zawakeEffect = __data_t__zawakeEffect[35413],
		-- {79003}
		zawakeEffectDesc = 'Niem Niem Bao breathes strong breath into the enemy\'s horizontal target, causing #C0x3D8A99#200% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, increases Magic Defense from Niem My Long by 100% and reduces Magic Damage taken by all allied heroes by 15% for 3 turns, during which all negative effects on our side are halved',
		zawakeEffectDesc_en = 'Niem Niem Bao breathes strong breath into the enemy\'s horizontal target, causing #C0x3D8A99#200% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, increases Magic Defense from Niem My Long by 100% and reduces Magic Damage taken by all allied heroes by 15% for 3 turns, during which all negative effects on our side are halved',
		zawakeEffectDesc_th = 'Niêm Niêm Bảo พ่นลมหายใจแรงใส่เป้าหมายแนวนอนของศัตรู ก่อให้เกิด #C0x3D8A99#200% พลังโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B#, เพิ่มการป้องกันเวทมนตร์จาก Niêm Mỹ Long ขึ้น 100% และลดความเสียหายเวทมนตร์ที่ฮีโร่พันธมิตรทั้งหมดได้รับลง 15% เป็นเวลา 3 เทิร์น ในช่วงนี้ลดผลกระทบด้านลบทั้งหมดของฝ่ายเราเหลือครึ่งหนึ่ง',
		zawakeEffectDesc_in = 'Niêm Niêm Bảo menghembuskan napas kuat ke target horizontal musuh, menyebabkan #C0x3D8A99#200% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, meningkatkan Pertahanan Sihir dari Niem My Long sebesar 100% dan mengurangi Kerusakan Sihir yang diterima oleh semua pahlawan sekutu sebesar 15% selama 3 giliran, selama waktu ini mengurangi semua efek negatif dari pihak kita menjadi setengahnya',
		zawakeEffectDesc_ph = 'Niêm Niêm Bảo humihinga ng malakas sa pahalang na target ng kalaban, nagdudulot ng #C0x3D8A99#200% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, nagpapataas ng Magic Defense mula kay Niem My Long ng 100% at nagpapababa ng Magic Damage sa lahat ng kakampi na bayani ng 15% sa loob ng 3 turns, habang ito\'y aktibo nagpapababa ng lahat ng negatibong epekto sa ating panig ng kalahati',
		zawakeEffectDesc_ma = 'Niêm Niêm Bảo menghembuskan nafas kuat ke sasaran mendatar musuh, menyebabkan #C0x3D8A99#200% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, meningkatkan Pertahanan Sihir dari Niêm Mỹ Long sebanyak 100% dan mengurangkan Kerusakan Sihir yang diterima oleh semua wira sekutu sebanyak 15% selama 3 pusingan, dalam tempoh ini mengurangkan semua kesan negatif pihak kita kepada separuh',
		zawakeEffectDesc_vn = 'Niêm Niêm Bảo thổi hơi thở mạnh mẽ vào mục tiêu hàng ngang của đối phương, gây ra #C0x3D8A99#200% Phép Công#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, tăng 100% Phép Phòng từ Niêm Mỹ Long và 15% giảm Sát Thương Phép Thuật cho toàn bộ anh hùng đồng minh trong 3 lượt, trong thời gian này giảm một nửa tất cả các hiệu ứng tiêu cực của phe ta',
