	[35433] = {
		id = 35433,
		skillName_vn = 'Pháo cao su',
		skillName_en = 'Rubber cannon',
		skillName_th = 'ปืนยาง',
		skillName_in = 'Meriam karet',
		skillName_ph = 'Baril ng goma',
		skillName_ma = 'Meriam getah',
		skillName = 'Rubber cannon',
		describe_vn = 'Luffy biến thành người khổng lồ bằng cao su và sử dụng bệ phóng tên lửa cao su để tấn công mục tiêu của kẻ thù, gây ra #C0x3D8A99#220% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật#C0x5B545B# tăng khả năng phòng thủ phép thuật của tất cả các anh hùng thân thiện từ Luffy Zombie lên 100% phòng thủ phép thuật và giảm 15% Sát Thương Phép Thuật cho 2 người lượt, trong thời gian đó mọi tác động tiêu cực về phía chúng ta giảm đi một nửa.',
		describe_en = 'Luffy transforms into a giant made of rubber and uses a rubber rocket launcher to attack enemy targets, dealing #C0x3D8A99#220% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage#C0x5B545B#. This increases the magic defense of all friendly heroes from Luffy Zombie to 100% magic defense and reduces Magic Damage by 15% for 2 turns. During this time, all negative effects against us are halved.',
		describe_th = 'ลูฟี่แปลงร่างเป็นยักษ์ยางและใช้ขีปนาวุธยางยิงโจมตีเป้าหมายของศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#220%#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# เพิ่มความสามารถป้องกันเวทมนตร์ของฮีโร่ฝ่ายเดียวกันที่มาจากลูฟี่ซอมบี้เป็น 100% การป้องกันเวทมนตร์ และลดความเสียหายเวทมนตร์ลง 15% เป็นเวลา 2 เทิร์น ในช่วงเวลานั้นผลลบที่เกิดกับพวกเราจะลดลงครึ่งหนึ่ง',
		describe_in = 'Luffy berubah menjadi raksasa dari karet dan menggunakan peluncur roket karet untuk menyerang target musuh, memberikan #C0x3D8A99#220% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Sihir#C0x5B545B#. Ini meningkatkan pertahanan sihir semua pahlawan ramah dari Luffy Zombie menjadi 100% pertahanan sihir dan mengurangi Kerusakan Sihir sebesar 15% selama 2 giliran. Selama waktu ini, semua efek negatif terhadap kami berkurang setengahnya.',
		describe_ph = 'Nag-transform si Luffy bilang higanteng goma at ginagamit ang goma rocket launcher para atakihin ang mga kalabang target, na nagdudulot ng #C0x3D8A99#220% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage#C0x5B545B#. Pinapataas nito ang magic defense ng lahat ng mga kaibigang bayani mula kay Luffy Zombie sa 100% magic defense at binabawasan ang Magic Damage ng 15% sa loob ng 2 na turn. Sa panahong ito, ang lahat ng negatibong epekto laban sa amin ay nababawasan ng kalahati.',
		describe_ma = 'Luffy berubah menjadi raksasa getah dan menggunakan pelancar roket getah untuk menyerang sasaran musuh, menyebabkan #C0x3D8A99#220% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Sihir#C0x5B545B#. Ini meningkatkan pertahanan sihir semua wira mesra dari Luffy Zombie kepada 100% pertahanan sihir dan mengurangkan Kerosakan Sihir sebanyak 15% untuk 2 giliran. Sepanjang tempoh ini, semua kesan negatif terhadap kami dikurangkan separuh.',
		describe = 'Luffy transforms into a giant made of rubber and uses a rubber rocket launcher to attack enemy targets, dealing #C0x3D8A99#220% Magic Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage#C0x5B545B#. This increases the magic defense of all friendly heroes from Luffy Zombie to 100% magic defense and reduces Magic Damage by 15% for 2 turns. During this time, all negative effects against us are halved.',
		simDesc_vn = 'Luffy biến thành người khổng lồ cao su dưới dạng zombie và sử dụng bệ phóng tên lửa cao su để tấn công mục tiêu kẻ thù theo hàng, tăng khả năng phòng thủ phép thuật nhất định và giảm sát thương phép thuật cho tất cả đồng minh.',
		simDesc_en = 'Luffy transforms into a giant rubber zombie and uses a rubber rocket launcher to attack enemy targets in a row, increasing certain magical defense and reducing magic damage for all allies.',
		simDesc_th = 'ลูฟี่แปลงร่างเป็นซอมบี้ยางยักษ์และใช้ปืนยิงจรวดยางโจมตีเป้าหมายศัตรูเป็นแถว ๆ เพิ่มความสามารถป้องกันเวทมนตร์บางส่วนและลดความเสียหายเวทมนตร์ของพันธมิตรทั้งหมด',
		simDesc_in = 'Luffy berubah menjadi zombie karet raksasa dan menggunakan peluncur roket karet untuk menyerang target musuh secara berbaris, meningkatkan kemampuan pertahanan sihir tertentu dan mengurangi kerusakan sihir untuk semua sekutu.',
		simDesc_ph = 'Nagbabago si Luffy sa isang higanteng rubber zombie at gumagamit ng rubber rocket launcher upang atakihin ang mga kaaway na target sa isang hilera, pinapataas ang tiyak na depensa sa mahika at binabawasan ang pinsala mula sa mahika para sa lahat ng mga kakampi.',
		simDesc_ma = 'Luffy berubah menjadi zombi getah gergasi dan menggunakan pelancar roket getah untuk menyerang sasaran musuh secara berbaris, meningkatkan pertahanan sihir tertentu dan mengurangkan kerosakan sihir untuk semua sekutu.',
		simDesc = 'Luffy transforms into a giant rubber zombie and uses a rubber rocket launcher to attack enemy targets in a row, increasing certain magical defense and reducing magic damage for all allies.',
		starEffect = __data_t__starEffect[35433],
		-- {11}
		starEffectDesc_vn = 'Tăng 20% giảm sát thương phép cho toàn đội, kéo dài 2 lượt.',
		starEffectDesc = 'Increases magic damage reduction by 20% for the entire team, lasting 2 turns.',
		starEffectDesc_en = 'Increases magic damage reduction by 20% for the entire team, lasting 2 turns.',
		starEffectDesc_th = 'เพิ่มการลดความเสียหายเวทมนตร์ 20% ให้กับทั้งทีม เป็นเวลา 2 เทิร์น',
		starEffectDesc_in = 'Meningkatkan pengurangan kerusakan sihir sebesar 20% untuk seluruh tim, berlangsung selama 2 giliran.',
		starEffectDesc_ph = 'Pinapataas ang 20% na bawas sa pinsalang magic para sa buong koponan, tumatagal ng 2 na turn.',
