	[35613] = {
		id = 35613,
		skillName_vn = 'Lời nguyền rừng',
		skillName_en = 'Forest Curse',
		skillName_th = 'คำสาปป่า',
		skillName_in = 'Kutukan Hutan',
		skillName_ph = 'Sumpa ng Gubat',
		skillName_ma = 'Sumpahan Hutan',
		skillName = 'Forest Curse',
		describe_vn = 'Tiểu Mộc Linh mọc ra những rễ cây khổng lồ dưới chân để áp đặt lời nguyền rừng lên mục tiêu hàng sau của kẻ địch, gây #C0xE69900#170% vật công#C0x5B545B#+$(skillLevel*4*26)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, đồng thời có 20% xác suất [Câm lặng] mục tiêu trong 1 lượt (Câm lặng: hiệu ứng khống chế, không thể sử dụng kỹ năng nhỏ và tuyệt chiêu)',
		describe_en = 'Little Mokuring grows giant roots underfoot to impose the forest curse on the enemy\'s backline target, dealing #C0xE69900#170% physical attack#C0x5B545B# + $(skillLevel*4*26)$ #C0xF13B54# Physical Damage#C0x5B545B#, and has a 20% chance to [Silence] the target for 1 turn (Silence: a control effect that prevents using ninjutsu and ultimate skills).',
		describe_th = 'ไทโอะโมะคุริงงอกรากต้นไม้ยักษ์ใต้เท้าเพื่อลงคำสาปป่าลงบนเป้าหมายแถวหลังของศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#170%#C0x5B545B# + $(skillLevel*4*26)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# พร้อมทั้งมีโอกาส 20% ที่จะ [ทำให้เงียบ] เป้าหมายเป็นเวลา 1 เทิร์น (ทำให้เงียบ: เอฟเฟกต์ควบคุม ห้ามใช้สกิลเล็กและสกิลสุดยอด)',
		describe_in = 'Little Mokuring menumbuhkan akar raksasa di bawah kaki untuk memberlakukan kutukan hutan pada target barisan belakang musuh, memberikan #C0xE69900#170% serangan fisik#C0x5B545B# + $(skillLevel*4*26)$ #C0xF13B54# Damage Fisik#C0x5B545B#, sekaligus memiliki peluang 20% untuk [Membungkam] target selama 1 giliran (Membungkam: efek kontrol yang mencegah penggunaan jurus kecil dan jurus pamungkas).',
		describe_ph = 'Lumalaki ang malalaking ugat ni Little Mokuring sa ilalim ng paa upang ipataw ang sumpa ng gubat sa target sa likurang hanay ng kalaban, na nagdudulot ng #C0xE69900#170% pisikal na atake#C0x5B545B# + $(skillLevel*4*26)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, at may 20% na pagkakataon na [Matahimik] ang target sa loob ng 1 turn (Matahimik: isang control effect na pumipigil sa paggamit ng mga maliit na kakayahan at ultimate na kakayahan).',
		describe_ma = 'Little Mokuring menumbuhkan akar pokok gergasi di bawah kaki untuk mengenakan sumpahan hutan ke sasaran barisan belakang musuh, memberi #C0xE69900#170% serangan fizikal#C0x5B545B# + $(skillLevel*4*26)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, serta mempunyai 20% peluang untuk [Menyenyapkan] sasaran selama 1 giliran (Menyenyapkan: kesan kawalan yang menghalang penggunaan kemahiran kecil dan kemahiran ulti).',
		describe = 'Little Mokuring grows giant roots underfoot to impose the forest curse on the enemy\'s backline target, dealing #C0xE69900#170% physical attack#C0x5B545B# + $(skillLevel*4*26)$ #C0xF13B54# Physical Damage#C0x5B545B#, and has a 20% chance to [Silence] the target for 1 turn (Silence: a control effect that prevents using ninjutsu and ultimate skills).',
