	[35623] = {
		id = 35623,
		skillName_vn = 'Đột kích linh hồn',
		skillName_en = 'Soul Raid',
		skillName_th = 'จู่โจมวิญญาณ',
		skillName_in = 'Serangan Jiwa',
		skillName_ph = 'Soul Raid',
		skillName_ma = 'Serangan Jiwa',
		skillName = 'Soul Raid',
		describe_vn = 'Yêu Mộc triệu hồi phân thân bóng tối tấn công bất ngờ mục tiêu hàng sau của kẻ địch, gây ra #C0xE69900#180% Công Vật Lý#C0x5B545B#+$(skillLevel*4*26)$ sát thương #C0xF13B54#vật lý#C0x5B545B#, và có 20% xác suất [Câm lặng] mục tiêu trong 1 lượt (Câm lặng: hiệu ứng khống chế, không thể sử dụng kỹ năng nhỏ và kỹ năng tối thượng)',
		describe_en = 'Yêu Mộc summons shadow clones to suddenly attack the enemy\'s backline targets, dealing #C0xE69900#180% Physical Attack#C0x5B545B# + $(skillLevel*4*26)$ #C0xF13B54#physical#C0x5B545B# damage, with a 20% chance to [Silence] the target for 1 turn (Silence: a control effect that prevents the use of minor and ultimate skills).',
		describe_th = 'ยมโมกะเรียกเงาคลอนส์โจมตีเป้าหมายแถวหลังของศัตรูโดยกะทันหัน สร้างความเสียหาย #C0xE69900#180% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*26)$ #C0xF13B54#กายภาพ#C0x5B545B# และมีโอกาส 20% ที่จะ [เงียบ] เป้าหมายเป็นเวลา 1 เทิร์น (เงียบ: เอฟเฟกต์ควบคุม ไม่สามารถใช้ทักษะเล็กและทักษะขั้นสูงได้)',
		describe_in = 'Yêu Mộc memanggil klon bayangan untuk menyerang secara tiba-tiba target barisan belakang musuh, memberikan damage #C0xE69900#180% Serangan Fisik#C0x5B545B# + $(skillLevel*4*26)$ #C0xF13B54#fisik#C0x5B545B#, dengan 20% peluang untuk [Diam] target selama 1 giliran (Diam: efek kontrol yang mencegah penggunaan skill kecil dan skill ulti).',
		describe_ph = 'Yêu Mộc ay nagtataglay ng mga aninong klon upang biglang atakihin ang mga target sa likurang linya ng kalaban, na nagdudulot ng #C0xE69900#180% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*26)$ #C0xF13B54#pisikal#C0x5B545B# na pinsala, at may 20% tsansa na [Manahimik] ang target nang 1 liko (Manahimik: isang control effect na pumipigil sa paggamit ng maliit at ultimatong mga kasanayan).',
		describe_ma = 'Yêu Mộc memanggil bayangan klon untuk menyerang secara mengejut sasaran barisan belakang musuh, menyebabkan #C0xE69900#180% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*26)$ #C0xF13B54#fizikal#C0x5B545B# kerosakan, dan mempunyai 20% peluang untuk [Bisu] sasaran selama 1 giliran (Bisu: kesan kawalan yang menghalang penggunaan kemahiran kecil dan kemahiran utama).',
		describe = 'Yêu Mộc summons shadow clones to suddenly attack the enemy\'s backline targets, dealing #C0xE69900#180% Physical Attack#C0x5B545B# + $(skillLevel*4*26)$ #C0xF13B54#physical#C0x5B545B# damage, with a 20% chance to [Silence] the target for 1 turn (Silence: a control effect that prevents the use of minor and ultimate skills).',
		simDesc_vn = 'Gỗ Mục Nát triệu hồi bóng hình tấn công từ hai phía, đánh lén mục tiêu ở hàng sau của kẻ thù, có khả năng làm cho mục tiêu bị câm.',
		simDesc_en = 'Rotten Wood summons shadow figures to attack from both sides, ambushing targets in the enemy\'s back row, with the ability to silence the targets.',
