	[35913] = {
		id = 35913,
		skillName_vn = 'Bão sóng âm',
		skillName_en = 'Sonic Storm',
		skillName_th = 'พายุคลื่นเสียง',
		skillName_in = 'Badai Gelombang Suara',
		skillName_ph = 'Bagyong Alon ng Tunog',
		skillName_ma = 'Badai Gelombang Bunyi',
		skillName = 'Sonic Storm',
		describe_vn = 'Dơi Vù bay lên không trung, sau đó phát ra cơn bão âm thanh tấn công mục tiêu hàng ngang của kẻ địch, gây ra #C0x3D8A99#210% Công Phép thuật#C0x5B545B#+$(skillLevel*4*48)$ sát thương #C0xF13B54#pháp thuật#C0x5B545B#, nếu tốc độ nhanh hơn mục tiêu, thì đòn tấn công này sẽ bỏ qua 35% phòng thủ pháp thuật và có 60% xác suất [Hỗn loạn] mục tiêu trong 1 lượt (Hỗn loạn: hiệu ứng khống chế, tấn công ngẫu nhiên không phân biệt địch ta)',
		describe_en = 'The Vù Bat flies into the air, then unleashes a sonic storm attacking a horizontal line of enemy targets, dealing #C0x3D8A99#210% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#magical#C0x5B545B# damage. If faster than the target, this attack ignores 35% of the target\'s magic defense and has a 60% chance to inflict [Confusion] on the target for 1 turn (Confusion: a control effect causing random attacks regardless of ally or enemy).',
		describe_th = 'ค้างคาววู บินขึ้นสู่อากาศ จากนั้นปล่อยพายุเสียงโจมตีเป้าหมายในแนวนอนของศัตรู ทำหน้าที่สร้างความเสียหาย #C0x3D8A99#210% พลังเวทย์#C0x5B545B#+$(skillLevel*4*48)$ ความเสียหาย #C0xF13B54#เวทย์มนตร์#C0x5B545B# หากเร็วกว่าเป้าหมาย การโจมตีนี้จะละเลยเกราะเวทย์มนตร์ของเป้าหมาย 35% และมีโอกาส 60% ทำให้เป้าหมาย [สับสน] เป็นเวลา 1 เทิร์น (สับสน:สถานะควบคุม ทำให้โจมตีอย่างสุ่มโดยไม่แบ่งฝ่าย).',
		describe_in = 'Kelelawar Vù terbang ke udara, kemudian mengeluarkan badai suara yang menyerang baris horizontal target musuh, menyebabkan #C0x3D8A99#210% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*48)$ kerusakan #C0xF13B54#magis#C0x5B545B#. Jika lebih cepat dari target, serangan ini akan mengabaikan 35% pertahanan sihir target dan memiliki peluang 60% untuk memberikan [Kebingungan] pada target selama 1 giliran (Kebingungan: efek kontrol, menyerang secara acak tanpa memandang teman atau musuh).',
		describe_ph = 'Ang Lumipad ang Paniki ng Vù sa himpapawid, pagkatapos ay naglunsad ng bagyong tunog na umaatake sa pahalang na linya ng mga target ng kalaban, na nagdudulot ng #C0x3D8A99#210% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ na #C0xF13B54#magical#C0x5B545B# na pinsala. Kung mas mabilis kaysa sa target, pinapalampas ng atakeng ito ang 35% ng magic defense ng target at may 60% na tsansa na magdulot ng [Kalituhan] sa target sa loob ng 1 turn (Kalituhan: control effect na nagreresulta sa walang piniling random na pag-atake sa kaaway o kakampi).',
		describe_ma = 'Kelawar Vù terbang ke udara, kemudian melepaskan ribut bunyi yang menyerang sasaran berbaris secara mendatar di pihak musuh, menyebabkan #C0x3D8A99#210% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$ kerosakan #C0xF13B54#magikal#C0x5B545B#. Jika lebih pantas daripada sasaran, serangan ini akan mengabaikan 35% pertahanan sihir sasaran dan mempunyai peluang 60% untuk memberi [Kekeliruan] kepada sasaran selama 1 pusingan (Kekeliruan: kesan kawalan, menyerang secara rawak tanpa mengira musuh atau rakan).',
		describe = 'The Vù Bat flies into the air, then unleashes a sonic storm attacking a horizontal line of enemy targets, dealing #C0x3D8A99#210% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#magical#C0x5B545B# damage. If faster than the target, this attack ignores 35% of the target\'s magic defense and has a 60% chance to inflict [Confusion] on the target for 1 turn (Confusion: a control effect causing random attacks regardless of ally or enemy).',
		simDesc_vn = 'Bọ Cánh Cứng bay lên không trung, sau đó phát ra bão âm thanh tấn công toàn bộ mục tiêu của kẻ thù; nếu tốc độ nhanh hơn mục tiêu, lần tấn công này sẽ bỏ qua một phần phòng thủ phép và có khả năng làm cho mục tiêu [bị hỗn loạn].',
		simDesc_en = 'The Beetle flies up into the air, then unleashes a sonic storm attacking all enemy targets; if its speed is higher than the target, this attack will bypass part of the magic defense and can cause the target to become <confused>.',
		simDesc_th = 'แมลงเต่าทองบินขึ้นสู่อากาศ จากนั้นปล่อยพายุเสียงโจมตีเป้าหมายศัตรูทั้งหมด; หากความเร็วสูงกว่าเป้าหมาย การโจมตีครั้งนี้จะข้ามส่วนหนึ่งของการป้องกันเวทมนตร์และมีโอกาสทำให้เป้าหมายตกอยู่ในสถานะ [สับสน].',
		simDesc_in = 'Kumbang terbang ke udara, kemudian melepaskan badai suara yang menyerang semua target musuh; jika kecepatannya lebih tinggi dari target, serangan ini akan melewati sebagian pertahanan sihir dan berpotensi membuat target <bingung>.',
		simDesc_ph = 'Ang kumbong lumilipad sa himpapawid, pagkatapos ay nagpapalabas ng isang bagyong tunog na umaatake sa lahat ng kaaway; kung mas mabilis ang bilis kaysa sa target, ang atakeng ito ay lilampas sa bahagi ng magic defense at maaaring magdulot ng <kalituhan> sa target.',
		simDesc_ma = 'Kumbang terbang ke udara kemudian melepaskan ribut bunyi yang menyerang semua sasaran musuh; jika kelajuannya lebih tinggi daripada sasaran, serangan ini akan mengabaikan sebahagian pertahanan sihir dan berpeluang menyebabkan sasaran menjadi <keliru>.',
		simDesc = 'The Beetle flies up into the air, then unleashes a sonic storm attacking all enemy targets; if its speed is higher than the target, this attack will bypass part of the magic defense and can cause the target to become [confused].',
		starEffect = __data_t__starEffect[35913],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sóng âm có thể xuyên qua lá chắn, gây sát thương trực tiếp cho kẻ địch; đối với mục tiêu đã bị hỗn loạn, sẽ làm cho chúng choáng 1 lượt.',
		starEffectDesc = 'Additional effect: Sound waves can penetrate shields, dealing direct damage to enemies; targets already confused will be stunned for 1 turn.',
		starEffectDesc_en = 'Additional effect: Sound waves can penetrate shields, dealing direct damage to enemies; targets already confused will be stunned for 1 turn.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: คลื่นเสียงสามารถทะลุโล่ได้ ทำความเสียหายโดยตรงกับศัตรู; สำหรับเป้าหมายที่สับสนจะทำให้พวกมันมึนงง 1 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Gelombang suara dapat menembus perisai, memberikan kerusakan langsung kepada musuh; untuk target yang sudah bingung, akan membuat mereka pingsan selama 1 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Ang mga alon ng tunog ay maaaring tumagos sa mga panangga, na nagbibigay ng direktang pinsala sa mga kalaban; para sa mga target na nalito, papakulubin sila ng 1 turn.',
		starEffectDesc_ma = 'Kesan tambahan: Gelombang bunyi boleh menembusi perisai, menyebabkan kerosakan terus kepada musuh; bagi sasaran yang sudah keliru, ia akan membuat mereka terpesona selama 1 giliran.',
