	[36011] = {
		id = 36011,
		skillName_vn = 'Tiễn Linh',
		skillName_en = 'Spirit Arrow',
		skillName_th = 'ศรวิญญาณ',
		skillName_in = 'Panah Roh',
		skillName_ph = 'Espiritu Pana',
		skillName_ma = 'Panah Roh',
		skillName = 'Spirit Arrow',
		describe_vn = 'Hakurei Reimu dùng cung và phù tấn công mục tiêu đơn, gây #C0x3D8A99#200% công phép#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#sát thương phép#C0x5B545B#, tăng 20% kháng chí mạng và 20% giảm sát thương cho bản thân, duy trì 2 lượt.#F20##F40#Ở trạng thái [Bảo hộ], tăng thêm 20% kháng chí mạng và 20% giảm sát thương cho một đồng đội ngẫu nhiên, duy trì 2 lượt.',
		describe_en = 'Reimu Hakurei uses bow and talisman to attack a single enemy target, dealing #C0x3D8A99#200% magic attack#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#magic damage#C0x5B545B#, increases her own critical resistance by 20% and damage reduction by 20%, lasting for 2 turns.#F20##F40#Under [Guard] state, increases 20% critical resistance and 20% damage reduction for another random ally, lasting for 2 turns.',
		describe_th = 'เรย์มุ ฮาคุเร ใช้คันธนูและยันต์โจมตีศัตรูเป้าหมายเดี่ยว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#200% พลังเวท#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#ความเสียหายเวท#C0x5B545B# เพิ่มความต้านคริติคอล 20% และลดความเสียหายที่ได้รับ 20% ให้ตัวเอง นาน 2 เทิร์น.#F20##F40#ในสถานะ [ปกป้อง] จะเพิ่มความต้านคริติคอล 20% และลดความเสียหาย 20% ให้กับพันธมิตรแบบสุ่มอีก 1 คน นาน 2 เทิร์น',
		describe_in = 'Hakurei Reimu menggunakan busur dan jimat untuk menyerang satu target musuh, memberikan #C0x3D8A99#200% serangan sihir#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#kerusakan sihir#C0x5B545B#, meningkatkan 20% resistensi kritikal dan 20% pengurangan damage untuk dirinya sendiri, bertahan selama 2 giliran.#F20##F40#Dalam status [Penjaga], memberikan tambahan 20% resistensi kritikal dan 20% pengurangan damage kepada 1 rekan acak, bertahan selama 2 giliran.',
		describe_ph = 'Si Hakurei Reimu ay gumagamit ng pana at talisman para umatake sa isang kalabang target, dealing #C0x3D8A99#200% magic attack#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#magic damage#C0x5B545B#, nagpapataas ng sariling 20% crit resistance at 20% damage reduction, tumatagal ng 2 turns.#F20##F40#Sa [Guard] state, nagbibigay ng dagdag 20% crit resistance at 20% damage reduction sa isang random na kakampi, tumatagal ng 2 turns.',
		describe_ma = 'Si Hakurei Reimu ay gumagamit ng pana at talisman para umatake sa isang kalabang target, dealing #C0x3D8A99#200% magic attack#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#magic damage#C0x5B545B#, nagpapataas ng sariling 20% crit resistance at 20% damage reduction, tumatagal ng 2 turns.#F20##F40#Sa [Guard] state, nagbibigay ng dagdag 20% crit resistance at 20% damage reduction sa isang random na kakampi, tumatagal ng 2 turns.',
		describe = 'Reimu Hakurei uses bow and talisman to attack a single enemy target, dealing #C0x3D8A99#200% magic attack#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#magic damage#C0x5B545B#, increases her own critical resistance by 20% and damage reduction by 20%, lasting for 2 turns.#F20##F40#Under [Guard] state, increases 20% critical resistance and 20% damage reduction for another random ally, lasting for 2 turns.',
		zawakeEffect = __data_t__zawakeEffect[36011],
		-- {79001}
		zawakeEffectDesc = 'Reimu Hakurei uses her bow and talismans to attack a single enemy target, dealing #C0x3D8A99#200% magic attack#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#magic damage#C0x5B545B#, increasing her own critical resistance by 40% and damage reduction by 40% for 2 turns.#F20##F40#In [Guard] state, she instead grants 40% critical resistance and 40% damage reduction to another random ally for 2 turns.',
		zawakeEffectDesc_en = 'Reimu Hakurei uses her bow and talismans to attack a single enemy target, dealing #C0x3D8A99#200% magic attack#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#magic damage#C0x5B545B#, increasing her own critical resistance by 40% and damage reduction by 40% for 2 turns.#F20##F40#In [Guard] state, she instead grants 40% critical resistance and 40% damage reduction to another random ally for 2 turns.',
		zawakeEffectDesc_th = 'เรย์มุ ฮาคุเร ใช้คันธนูและยันต์โจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายเวท #C0x3D8A99#200% พลังเวท#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#ความเสียหายเวท#C0x5B545B# เพิ่มการต้านคริ 40% และลดความเสียหายที่ได้รับ 40% ให้ตัวเอง เป็นเวลา 2 เทิร์น#F20##F40#ในสถานะ [คุ้มกัน] จะมอบการต้านคริ 40% และลดความเสียหาย 40% ให้ยูนิตพันธมิตรแบบสุ่มอีก 1 ตัว แทน เป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Reimu Hakurei menggunakan busur dan jimat untuk menyerang satu target musuh, memberikan #C0x3D8A99#200% serangan sihir#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#kerusakan sihir#C0x5B545B#, meningkatkan resistensi kritikal sendiri sebesar 40% dan pengurangan kerusakan sebesar 40% selama 2 giliran.#F20##F40#Dalam status [Penjaga], sebagai gantinya memberikan 40% resistensi kritikal dan 40% pengurangan kerusakan kepada satu unit sekutu acak selama 2 giliran.',
		zawakeEffectDesc_ph = 'Ginagamit ni Reimu Hakurei ang pana at talisman para umatake sa isang kalabang target, nagdudulot ng #C0x3D8A99#200% magic attack#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#magic damage#C0x5B545B#, pinapataas ang sariling critical resistance ng 40% at damage reduction ng 40% sa loob ng 2 turn.#F20##F40#Sa [Guard] status, sa halip ay binibigyan ng 40% critical resistance at 40% damage reduction ang isa pang random na kakampi sa loob ng 2 turn.',
		zawakeEffectDesc_ma = 'Reimu Hakurei menggunakan busur dan azimat untuk menyerang satu sasaran musuh, memberikan #C0x3D8A99#200% serangan magik#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#kerosakan magik#C0x5B545B#, meningkatkan ketahanan kritikal sendiri sebanyak 40% dan pengurangan kerosakan sebanyak 40% selama 2 giliran.#F20##F40#Dalam keadaan [Penjaga], sebaliknya memberikan 40% ketahanan kritikal dan 40% pengurangan kerosakan kepada satu sekutu rawak lain selama 2 giliran.',
		zawakeEffectDesc_vn = 'Hakurei Reimu dùng cung và phù tấn công một mục tiêu địch đơn, gây #C0x3D8A99#200% sát thương phép#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#sát thương phép#C0x5B545B#, đồng thời tăng 40% kháng chí mạng và giảm sát thương bản thân 40% trong 2 lượt.#F20##F40#Khi ở trạng thái [Bảo hộ], thay vào đó tăng 40% kháng chí mạng và 40% giảm sát thương cho 1 đồng minh ngẫu nhiên khác trong 2 lượt.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increase own critical resistance by 15% and damage reduction by 15%, lasting for 2 turns.#F20##F40#In [Guard] state, instead increases critical resistance and damage reduction of another random ally by 15%, lasting for 2 turns.#F20##F40##C0x5c9970#Increase own critical resistance by 40% and damage reduction by 40%, lasting for 2 turns.#F20##F40#In [Guard] state, instead increases critical resistance and damage reduction of another random ally by 40%, lasting for 2 turns.',
		zawakeSimpleDesc_en = 'Increase own critical resistance by 15% and damage reduction by 15%, lasting for 2 turns.#F20##F40#In [Guard] state, instead increases critical resistance and damage reduction of another random ally by 15%, lasting for 2 turns.#F20##F40##C0x5c9970#Increase own critical resistance by 40% and damage reduction by 40%, lasting for 2 turns.#F20##F40#In [Guard] state, instead increases critical resistance and damage reduction of another random ally by 40%, lasting for 2 turns.',
		zawakeSimpleDesc_th = 'เพิ่มการต้านคริของตนเอง 15% และลดความเสียหาย 15% นาน 2 เทิร์น#F20##F40#ในสถานะ [คุ้มกัน] จะเพิ่มการต้านคริและลดความเสียหาย 15% ให้ยูนิตพันธมิตรแบบสุ่มอีก 1 ตัว นาน 2 เทิร์น#F20##F40##C0x5c9970#เพิ่มการต้านคริของตนเอง 40% และลดความเสียหาย 40% นาน 2 เทิร์น#F20##F40#ในสถานะ [คุ้มกัน] จะเพิ่มการต้านคริและลดความเสียหาย 40% ให้ยูนิตพันธมิตรแบบสุ่มอีก 1 ตัว นาน 2 เทิร์น',
		zawakeSimpleDesc_in = 'Meningkatkan resistensi kritikal sendiri sebesar 15% dan pengurangan kerusakan sebesar 15%, berlangsung selama 2 giliran.#F20##F40#Dalam status [Penjaga], sebagai gantinya memberikan 15% resistensi kritikal dan 15% pengurangan kerusakan kepada satu unit sekutu acak, berlangsung selama 2 giliran.#F20##F40##C0x5c9970#Meningkatkan resistensi kritikal sendiri sebesar 40% dan pengurangan kerusakan sebesar 40%, berlangsung selama 2 giliran.#F20##F40#Dalam status [Penjaga], sebagai gantinya memberikan 40% resistensi kritikal dan 40% pengurangan kerusakan kepada satu unit sekutu acak, berlangsung selama 2 giliran.',
		zawakeSimpleDesc_ph = 'Pinapataas ang sariling critical resistance ng 15% at damage reduction ng 15%, tumatagal ng 2 turn.#F20##F40#Sa [Guard] status, sa halip ay binibigyan ng 15% critical resistance at 15% damage reduction ang isa pang random na kakampi, tumatagal ng 2 turn.#F20##F40##C0x5c9970#Pinapataas ang sariling critical resistance ng 40% at damage reduction ng 40%, tumatagal ng 2 turn.#F20##F40#Sa [Guard] status, sa halip ay binibigyan ng 40% critical resistance at 40% damage reduction ang isa pang random na kakampi, tumatagal ng 2 turn.',
		zawakeSimpleDesc_ma = 'Meningkatkan ketahanan kritikal sendiri sebanyak 15% dan pengurangan kerosakan sebanyak 15%, bertahan selama 2 pusingan.#F20##F40#Dalam keadaan [Penjaga], sebagai gantinya memberikan 15% ketahanan kritikal dan 15% pengurangan kerosakan kepada satu sekutu rawak lain selama 2 pusingan.#F20##F40##C0x5c9970# Meningkatkan ketahanan kritikal sendiri sebanyak 40% dan pengurangan kerosakan sebanyak 40%, bertahan selama 2 pusingan.#F20##F40#Dalam keadaan [Penjaga], sebagai gantinya memberikan 40% ketahanan kritikal dan 40% pengurangan kerosakan kepada satu sekutu rawak lain selama 2 pusingan.',
		zawakeSimpleDesc_vn = 'Tăng 15% kháng chí mạng và 15% giảm sát thương cho bản thân, duy trì 2 lượt.#F20##F40#Ở trạng thái [Bảo hộ], thay vào đó tăng 15% kháng chí mạng và 15% giảm sát thương cho 1 đồng minh ngẫu nhiên khác, duy trì 2 lượt.#F20##F40##C0x5c9970# Tăng 40% kháng chí mạng và 40% giảm sát thương cho bản thân, duy trì 2 lượt.#F20##F40#Ở trạng thái [Bảo hộ], thay vào đó tăng 40% kháng chí mạng và 40% giảm sát thương cho 1 đồng minh ngẫu nhiên khác, duy trì 2 lượt.',
		iconRes = 'battle/skill_icon/skill_36011.png',
