	[36012] = {
		id = 36012,
		skillName_vn = 'Sao Rơi',
		skillName_en = 'Falling Meteor',
		skillName_th = 'ดาวตก',
		skillName_in = 'Meteor Jatuh',
		skillName_ph = 'Bagsak Meteor',
		skillName_ma = 'Meteor Jatuh',
		skillName = 'Falling Meteor',
		describe_vn = 'Hakurei Reimu dùng cung và phù, dẫn lực sao băng tấn công hàng trước địch, gây #C0x3D8A99#200% công phép#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#sát thương phép#C0x5B545B#. Bản thân và 1 đồng đội hàng sau ngẫu nhiên nhận được [Chế độ bảo hộ] trong 1 lượt (ưu tiên đơn vị được附身). Trong [Chế độ bảo hộ], khi dùng kỹ năng phụ này hoặc lần tấn công chủ động tiếp theo đánh cùng mục tiêu với kỹ năng của đồng đội, có 100% xác suất khiến mục tiêu bị [Choáng] 1 lượt (tối đa choáng 3 mục tiêu cùng lúc).#F20##F40#[Chế độ bảo hộ]: Hiệu ứng đặc biệt, không thể xóa, chuyển hay sao chép; tàng hình và tăng 100% cả hai phòng thủ.',
		describe_en = 'Reimu Hakurei uses bow and talisman to channel the power of meteors to attack the enemy front row, dealing #C0x3D8A99#200% magic attack#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#magic damage#C0x5B545B#. Grants herself and another random back-row ally [Guard Mode] for 1 turn (priority to possessed unit). While in [Guard Mode], when she uses this minor skill or her next active attack to attack the same target as an ally\'s skill attack, there is a 100% chance to [Stun] the target for 1 turn (up to 3 targets stunned at the same time).#F20##F40#[Guard Mode]: Special effect, cannot be dispelled, transferred, or copied; gains stealth and 100% boost to both defenses.',
		describe_th = 'ฮาคุเรย์ เรย์มุใช้ธนูควบคุมยันต์ อัญเชิญพลังแห่งดาวตกเพื่อโจมตีศัตรูแถวหน้า สร้าง#C0x3D8A99#200% พลังโจมตีเวท#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายเวท#C0x5B545B# และทำให้ตัวเองและยูนิตสุ่มในแถวหลังอีก 1 ตัวได้รับ[โหมดปกป้อง] เป็นเวลา 1 เทิร์น (ให้ยูนิตที่มีการสิงก่อนเป็นลำดับแรก) ขณะอยู่ใน[โหมดปกป้อง] สกิลย่อยครั้งนี้และการโจมตีแบบแอคทีฟครั้งถัดไปของตัวเอง หากโจมตีเป้าหมายเดียวกับที่เพื่อนร่วมทีมใช้สกิลโจมตี จะมีโอกาส 100% ทำให้เป้าหมาย[มึนงง] 1 เทิร์น (มึนงงได้สูงสุดพร้อมกัน 3 ตัว) #F20# #F40#[โหมดปกป้อง]: เอฟเฟกต์พิเศษ ไม่สามารถถูกลบ ย้าย หรือคัดลอกได้ ล่องหน และพลังป้องกันทั้งสองประเภทเพิ่มขึ้น 100%',
		describe_in = 'Hakurei Reimu menggunakan busur dan jimat, memanggil kekuatan meteor untuk menyerang barisan depan musuh, memberikan #C0x3D8A99#200% serangan sihir#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#kerusakan sihir#C0x5B545B#. Memberikan [Mode Penjaga] kepada dirinya sendiri dan 1 rekan acak di barisan belakang selama 1 giliran (prioritas pada unit附身). Dalam [Mode Penjaga], saat menggunakan skill kecil ini atau serangan aktif selanjutnya ke target yang sama dengan skill sekutu, ada 100% kemungkinan untuk [Stun] target selama 1 giliran (maksimal 3 target stun bersamaan).#F20##F40#[Mode Penjaga]: Efek khusus, tidak bisa dihapus, dipindahkan atau disalin; menghilang dan meningkatkan 100% kedua pertahanan.',
		describe_ph = 'Si Hakurei Reimu ay gumagamit ng pana at talisman, tinatawag ang kapangyarihan ng meteor para umatake sa front row ng kalaban, dealing #C0x3D8A99#200% magic attack#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#magic damage#C0x5B545B#. Nagbibigay ng [Guard Mode] sa sarili at isang random backline ally ng 1 turn (priority sa附身 unit). Sa [Guard Mode], kapag ginamit ang minor skill na ito o susunod na active attack sa parehong target ng attack ng ally, 100% chance na [Stun] target ng 1 turn (max 3 target stunned sabay).#F20##F40#[Guard Mode]: Special effect, cannot be dispelled, transferred, or copied; stealth at +100% both defenses.',
		describe_ma = 'Hakurei Reimu menggunakan busur dan jimat, memanggil kekuatan meteor untuk menyerang barisan depan musuh, memberikan #C0x3D8A99#200% serangan sihir#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#kerusakan sihir#C0x5B545B#. Memberikan [Mode Penjaga] kepada dirinya sendiri dan 1 rekan acak di barisan belakang selama 1 giliran (prioritas pada unit附身). Dalam [Mode Penjaga], saat menggunakan skill kecil ini atau serangan aktif selanjutnya ke target yang sama dengan skill sekutu, ada 100% kemungkinan untuk [Stun] target selama 1 giliran (maksimal 3 target stun bersamaan).#F20##F40#[Mode Penjaga]: Efek khusus, tidak bisa dihapus, dipindahkan atau disalin; menghilang dan meningkatkan 100% kedua pertahanan.',
		describe = 'Reimu Hakurei uses bow and talisman to channel the power of meteors to attack the enemy front row, dealing #C0x3D8A99#200% magic attack#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#magic damage#C0x5B545B#. Grants herself and another random back-row ally [Guard Mode] for 1 turn (priority to possessed unit). While in [Guard Mode], when she uses this minor skill or her next active attack to attack the same target as an ally\'s skill attack, there is a 100% chance to [Stun] the target for 1 turn (up to 3 targets stunned at the same time).#F20##F40#[Guard Mode]: Special effect, cannot be dispelled, transferred, or copied; gains stealth and 100% boost to both defenses.',
		zawakeEffect = __data_t__zawakeEffect[36012],
		-- {79002}
		zawakeEffectDesc = 'Hakurei Reimu uses her bow to control talismans, channeling the power of meteors to attack the enemy front row, dealing #C0x3D8A99#200% magic attack#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#magic damage#C0x5B545B#, and grants herself and another random back-row unit 【Guard Mode】for 1 turn (prioritizing herself). In 【Guard Mode】, this small skill and the next active attack will have a 100% chance to 【Stun】 the same target when attacking together with allies for 1 turn (up to 3 enemies stunned at once).\n#F20#\n#F40#【Guard Mode】: Special effect, cannot be dispelled, transferred, or copied, grants invisibility and increases both defenses by 150%, removes one debuff and restores 10% HP when it ends',
		zawakeEffectDesc_en = 'Hakurei Reimu uses her bow to control talismans, channeling the power of meteors to attack the enemy front row, dealing #C0x3D8A99#200% magic attack#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#magic damage#C0x5B545B#, and grants herself and another random back-row unit 【Guard Mode】for 1 turn (prioritizing herself). In 【Guard Mode】, this small skill and the next active attack will have a 100% chance to 【Stun】 the same target when attacking together with allies for 1 turn (up to 3 enemies stunned at once).\n#F20#\n#F40#【Guard Mode】: Special effect, cannot be dispelled, transferred, or copied, grants invisibility and increases both defenses by 150%, removes one debuff and restores 10% HP when it ends',
		zawakeEffectDesc_th = 'Hakurei Reimu ใช้ธนูควบคุมยันต์ ดึงพลังจากดาวตกโจมตีศัตรูแถวหน้า สร้างความเสียหาย #C0x3D8A99#200% พลังเวท#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#ความเสียหายเวท#C0x5B545B# และทำให้ตัวเองกับยูนิตสุ่มในแถวหลังอีกหนึ่งคนได้รับ 【โหมดป้องกัน】1 เทิร์น (จะเลือกตัวเองก่อน), ใน【โหมดป้องกัน】สกิลย่อยครั้งนี้และการโจมตีถัดไปเมื่อโจมตีเป้าหมายเดียวกันกับเพื่อนร่วมทีมจะมีโอกาส 100% ทำให้【สตั้น】เป้าหมาย 1 เทิร์น (ทำให้สตั้นได้สูงสุด 3 คนพร้อมกัน)\n#F20#\n#F40#【โหมดป้องกัน】: เอฟเฟกต์พิเศษ ไม่สามารถถูกลบ โอนไป หรือคัดลอกได้ ล่องหนและเพิ่มพลังป้องกันทั้งสอง 150% เมื่อจบจะลบดีบัฟ 1 อย่างและฟื้นฟู HP 10%.',
		zawakeEffectDesc_in = 'Hakurei Reimu menggunakan busur untuk mengendalikan jimat, memanggil kekuatan meteor untuk menyerang barisan depan musuh, memberikan #C0x3D8A99#200% serangan sihir#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#kerusakan sihir#C0x5B545B#, serta memberikan 【Mode Pelindung】1 giliran kepada dirinya sendiri dan satu unit acak di barisan belakang (prioritas ke dirinya sendiri). Dalam 【Mode Pelindung】, skill kecil kali ini dan serangan aktif berikutnya saat menyerang target yang sama dengan rekan akan memiliki 100% peluang menyebabkan 【Stun】 selama 1 giliran (maksimal 3 musuh yang terkena stun bersamaan).\n#F20#\n#F40#【Mode Pelindung】: Efek spesial, tidak bisa dihapus, dipindahkan, atau disalin, menjadi tak terlihat dan meningkatkan kedua pertahanan sebesar 150%, setelah selesai menghapus 1 debuff dan memulihkan 10% HP.',
		zawakeEffectDesc_ph = 'Ginagamit ni Hakurei Reimu ang busog upang kontrolin ang mga talisman, sumisipsip ng kapangyarihan mula sa mga meteor upang atakihin ang front row ng kalaban, nagdudulot ng #C0x3D8A99#200% magic attack#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#magic damage#C0x5B545B#, at nagbibigay ng 【Guard Mode】sa sarili at isang random na unit sa back row sa loob ng 1 turn (inuuna ang sarili). Sa 【Guard Mode】, ang maliit na skill na ito at ang susunod na active attack kapag umatake sa parehong target kasama ang kakampi ay may 100% chance na magdulot ng 【Stun】 sa loob ng 1 turn (maximum 3 kalaban ang ma-stun sabay).\n#F20#\n#F40#【Guard Mode】: Espesyal na effect, hindi pwedeng ma-dispel, ma-transfer, o ma-copy, invisible at +150% sa parehong defense, matapos ay tatanggalin ang isang debuff at magre-restore ng 10% HP.',
		zawakeEffectDesc_ma = 'Hakurei Reimu menggunakan busur untuk mengawal jimat, menarik kuasa meteor menyerang barisan depan musuh, memberikan #C0x3D8A99#200% serangan magik#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#kerosakan magik#C0x5B545B#, serta memberikan 【Mod Perlindungan】1 pusingan kepada diri sendiri dan satu unit rawak di barisan belakang (mengutamakan diri sendiri). Dalam 【Mod Perlindungan】, skill kecil kali ini dan serangan aktif seterusnya apabila menyerang sasaran sama dengan rakan akan mempunyai 100% peluang untuk 【Stun】 selama 1 pusingan (maksimum 3 musuh stun serentak).\n#F20#\n#F40#【Mod Perlindungan】: Kesan khas, tidak boleh dibuang, dipindahkan atau disalin, jadi halimunan dan tingkatkan kedua-dua pertahanan sebanyak 150%, selepas tamat akan buang 1 debuff dan pulihkan 10% HP.',
		zawakeEffectDesc_vn = 'Reimu Hakurei sử dụng cung điều khiển phù, dẫn lực sao băng tấn công hàng trước địch, gây #C0x3D8A99#200% pháp công#C0x5B545B#+$(skillLevel424)$ #C0xF13B54#sát thương pháp thuật#C0x5B545B#, đồng thời khiến bản thân và một đơn vị ngẫu nhiên hàng sau khác nhận được 【Chế độ bảo hộ】1 lượt (ưu tiên lên bản thân), ở 【Chế độ bảo hộ】, kỹ năng nhỏ lần này và đòn tấn công chủ động kế tiếp khi tấn công cùng mục tiêu với đồng đội sẽ có 100% xác suất khiến mục tiêu bị 【Choáng】1 lượt (tối đa choáng cùng lúc 3 người)\n#F20#\n#F40#【Chế độ bảo hộ】: Hiệu ứng đặc biệt, không thể bị xua tan, chuyển giao hay sao chép, trạng thái tàng hình và tăng 150% cả hai phòng thủ, sau khi kết thúc sẽ xua tan 1 hiệu ứng xấu và hồi 10% HP.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '【Guard Mode】increases both defenses to 150%, and after 【Guard Mode】ends, dispels one debuff and heals 10% HP.',
		zawakeSimpleDesc_en = '【Guard Mode】increases both defenses to 150%, and after 【Guard Mode】ends, dispels one debuff and heals 10% HP.',
		zawakeSimpleDesc_th = '【โหมดป้องกัน】เพิ่มการป้องกันทั้งสองเป็น 150% และเมื่อสิ้นสุด【โหมดป้องกัน】จะลบดีบัฟ 1 อย่างและฟื้นฟู HP 10%.',
		zawakeSimpleDesc_in = '【Mode Pelindung】meningkatkan kedua pertahanan hingga 150%, dan setelah 【Mode Pelindung】berakhir, akan menghapus satu debuff dan memulihkan 10% HP.',
		zawakeSimpleDesc_ph = '【Guard Mode】pinapataas ang parehong defense sa 150%, at pagkatapos ng 【Guard Mode】ay magtatanggal ng isang debuff at magre-restore ng 10% HP.',
		zawakeSimpleDesc_ma = '【Mod Perlindungan】meningkatkan kedua-dua pertahanan hingga 150%, dan selepas 【Mod Perlindungan】tamat, akan menghapuskan satu debuff serta memulihkan 10% HP.',
		zawakeSimpleDesc_vn = '【Chế độ bảo hộ】tăng cả hai phòng thủ lên 150%, và sau khi 【Chế độ bảo hộ】kết thúc sẽ xua tan 1 hiệu ứng xấu và hồi phục 10% HP.',
