	[36015] = {
		id = 36015,
		skillName_vn = 'Khí Trường Miko',
		skillName_en = 'Miko Aura',
		skillName_th = 'รัศมีมิโกะ',
		skillName_in = 'Aura Miko',
		skillName_ph = 'Aura Miko',
		skillName_ma = 'Aura Miko',
		skillName = 'Miko Aura',
		describe_vn = '#L10# Life Aura: Kỹ năng #L0# Aura, giúp tăng giới hạn sinh mệnh của tất cả các anh hùng đồng minh lên tổng cộng 20% ​​giới hạn sinh mệnh ban đầu của chính nó và Xerneas; khi sức khỏe của tất cả các anh hùng đồng minh giảm xuống dưới 40% lần đầu tiên, [Chế độ hoạt động] được cấp trong 2 hiệp\n#F20# \n#F40#[Chế độ hoạt động]: Khôi phục lượng máu của bản thân về giới hạn mạng sống ban đầu trước khi vòng hành động bắt đầu. #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B#\n#F20# \n#F40##L10# Hào quang thần tiên: #L0# Kỹ năng hào quang, hồi sinh đất, tăng trưởng thực vật, hiệu ứng chữa lành của tất cả các anh hùng tăng 30%, hiệu ứng của tiên, cỏ và anh hùng trên mặt đất tăng gấp đôi; khả năng hạn chế sát thương thuộc tính tự nhiên của tiên, cỏ và anh hùng trên mặt đất tăng 20%; kháng thuộc tính tự nhiên tăng thêm 20%\n#F20# \n#F40##L10#Yoyo Luming: #L0# Khi lượng máu lần đầu tiên thấp hơn 50%, nó sẽ biến thành linh hồn hươu. Nó không thể bị tấn công và không thể thêm hiệu ứng, và nó sẽ [sở hữu] một phần linh hồn của mình cho anh hùng thân thiện có đòn tấn công cao nhất trong 3 hiệp\n#F20# \n#F40#[Sở hữu]: Hiệu ứng đặc biệt, cải thiện 50% khả năng kháng đòn chí mạng, kiểm soát tỷ lệ miễn nhiễm, tốc độ hồi phục cơn thịnh nộ và giới hạn sinh mệnh từ giới hạn sinh mệnh tối đa 100% ban đầu của Xerneas. Mỗi khi anh hùng bị chiếm hữu chủ động tấn công, linh hồn bị chiếm hữu sẽ giải phóng các kỹ năng ở cấp độ tương ứng. Linh hồn hươu sẽ tự động tấn công một mục tiêu trong mỗi vòng hành động. Mục tiêu gây ra #C0x3D8A99#300% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#. Sau khi chiếm hữu xong, linh hồn trở về hồn hươu, lượng máu của Xerneas được phục hồi 100%',
		describe_en = 'Lỗi: Unexpected character encountered while parsing value: {. Path \'en\', line 2, position 9.',
		describe_th = 'Lỗi: Unexpected character encountered while parsing value: {. Path \'en\', line 2, position 9.',
		describe_in = 'Lỗi: Unexpected character encountered while parsing value: {. Path \'en\', line 2, position 9.',
		describe_ph = 'Lỗi: Unexpected character encountered while parsing value: {. Path \'en\', line 2, position 9.',
		describe_ma = 'Lỗi: Unexpected character encountered while parsing value: {. Path \'en\', line 2, position 9.',
		describe = 'Lỗi: Unexpected character encountered while parsing value: {. Path \'en\', line 2, position 9.',
		starEffect = __data_t__starEffect[36015],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi bắt đầu trận đấu, liên kết tất cả đồng minh bằng <Liên Kết Sinh Mệnh>, kéo dài đến lượt lớn tiếp theo sau khi bản thân hành động; khi đơn vị bị chiếm hữu nhận sát thương chí mạng, sẽ chặn sát thương này và thoát khỏi hiệu ứng <Chiếm Hữu>.',
		starEffectDesc = 'Additional effect: At the start of the battle, links all allies with <Life Link>, lasting until the next major turn after the user acts; when the possessed unit receives critical damage, it blocks this damage and escapes the <Possession> effect.',
		starEffectDesc_en = 'Additional effect: At the start of the battle, links all allies with <Life Link>, lasting until the next major turn after the user acts; when the possessed unit receives critical damage, it blocks this damage and escapes the <Possession> effect.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อเริ่มการต่อสู้ เชื่อมโยงพันธมิตรทั้งหมดด้วย <ลิงค์แห่งชีวิต> คงอยู่จนกว่าจะถึงรอบหลักถัดไปหลังจากที่ตนเองทำการกระทำ; เมื่อหน่วยที่ถูกครอบครองได้รับความเสียหายคริติคอล จะบล็อกความเสียหายนี้และหลุดออกจากเอฟเฟกต์ <ครอบครอง>.',
		starEffectDesc_in = 'Efek tambahan: Saat pertandingan dimulai, menghubungkan semua sekutu dengan <Life Link>, berlangsung hingga giliran utama berikutnya setelah unit sendiri bertindak; ketika unit yang dikuasai menerima kerusakan kritis, akan memblokir kerusakan ini dan keluar dari efek <Possession>.',
		starEffectDesc_ph = 'Karagdagang epekto: Sa pagsisimula ng laban, nag-uugnay ng lahat ng mga kakampi gamit ang <Life Link>, tumatagal hanggang sa susunod na malaking turn pagkatapos kumilos ang sarili; kapag ang unit na sinakop ay tumanggap ng kritikal na pinsala, pipigilan nito ang pinsalang ito at lalabas mula sa epekto ng <Possession>.',
		starEffectDesc_ma = 'Kesan tambahan: Apabila pertempuran bermula, menghubungkan semua sekutu dengan <Life Link>, berlangsung sehingga giliran utama seterusnya selepas unit itu bertindak; apabila unit yang dikuasai menerima kerosakan kritikal, akan menghalang kerosakan ini dan keluar dari kesan <Possession>.',
		iconRes = 'battle/skill_icon/skill_36016.png',
		changeUnitTrigger = true,
		isCombat = true,
		passivePriority = 8,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		skillProcess = {360161}
	},
	[36016] = {
		id = 36016,
		skillName_vn = 'Khí Trường Miko',
		skillName_en = 'Miko Aura',
		skillName_th = 'รัศมีมิโกะ',
		skillName_in = 'Aura Miko',
		skillName_ph = 'Aura Miko',
		skillName_ma = 'Aura Miko',
		skillName = 'Miko Aura',
		describe_vn = '#L10#Hào quang Vu nữ: #L0#Kỹ năng hào quang. Tăng giới hạn HP tối đa của toàn bộ đồng đội bằng tổng 20% giới hạn HP gốc của họ và Hakurei Reimu; Khi máu của đồng đội lần đầu tiên giảm dưới 40%, nhận 【Chế độ hoạt động】trong 2 lượt\n#F20# \n#F40#【Chế độ hoạt động】: Trước khi bắt đầu lượt hành động, hồi phục #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# giới hạn HP gốc\n#F20# \n#F40##L10#Trường khí Vu nữ: #L0#Kỹ năng hào quang. Ảo Tưởng Hương nằm dưới sự kiểm soát của Vu nữ, đất trời hồi sinh, sự sống bừng nở. Toàn bộ anh hùng tăng hiệu quả hồi máu 30%, hiệu quả gấp đôi với hệ Siêu năng lực, Thánh quang, Địa hệ; Tăng 20% khắc chế thuộc tính tự nhiên của các anh hùng Siêu năng lực, Thánh quang, Địa hệ; Tăng 20% kháng thuộc tính tự nhiên\n#F20# \n#F40##L10#Linh hồn Vu nữ: #L0#Khi Reimu lần đầu tiên giảm máu dưới 50%, cô sẽ hòa vào Ảo Tưởng Hương, biến thành Linh hươu Tự nhiên, không thể bị tấn công hoặc chịu hiệu ứng, và linh hồn sẽ【Nhập thể】vào đồng đội có công cao nhất trong 3 lượt\n#F20# \n#F40#【Nhập thể】: Hiệu ứng đặc biệt, tăng 50% kháng chí mạng, miễn khống, tốc độ hồi nộ và HP tối đa bằng 100% HP gốc của Reimu. Khi đồng đội bị nhập thể tấn công, linh hồn sẽ tung kỹ năng tương ứng. Linh hươu Tự nhiên sẽ tự động đánh thường mỗi lượt, gây #C0x3D8A99#300% pháp công#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#sát thương phép#C0x5B545B# lên 1 mục tiêu. Kết thúc nhập thể, linh hồn quay về, Reimu hồi máu 100%',
		describe_en = '#L10#Miko Aura: #L0#Aura skill. Increases the max HP of all allies by the sum of 20% of their own and Reimu Hakurei’s initial max HP; When any ally’s HP falls below 40% for the first time, grants [Active Mode] for 2 turns\n#F20# \n#F40#[Active Mode]: At the start of the action turn, restores #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# of the initial max HP\n#F20# \n#F40##L10#Miko Domain: #L0#Aura skill. All of Gensokyo is under the shrine maiden’s control. Earth revives, life blooms. All allies\' healing received is increased by 30%, and doubled for heroes of Psychic, Holy, and Ground types; Psychic, Holy, and Ground type heroes\' natural elemental dominance is increased by 20%; Natural resistance increased by 20%\n#F20# \n#F40##L10#Miko Spirit: #L0#When Reimu\'s HP falls below 50% for the first time, she merges with Gensokyo and transforms into a Deer Spirit of Nature. She becomes untargetable and immune to status effects, and a part of her soul [Possesses] the ally with the highest attack for 3 turns\n#F20# \n#F40#[Possess]: A special effect that increases Crit Resistance, Control Immunity, Rage Recovery Speed by 50%, and Max HP by 100% of Reimu\'s initial max HP. When the possessed hero performs a normal attack, the possessing spirit casts a skill of corresponding level. The Deer Spirit automatically performs a normal attack each turn, dealing #C0x3D8A99#300% magic attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#magic damage#C0x5B545B# to a single target. After the possession ends, the soul returns to the deer, and Reimu\'s HP is restored to 100%',
		describe_th = '#L10#ออร่ามิโกะ: #L0#สกิลออร่า เพิ่ม HP สูงสุดของพันธมิตรทั้งหมดตามผลรวม 20% ของ HP เริ่มต้นของตนเองและเรย์มุ ฮาคุเรย์; เมื่อตัวละครพันธมิตรมี HP ต่ำกว่า 40% ครั้งแรก จะได้รับ【โหมดแอคทีฟ】เป็นเวลา 2 เทิร์น\n#F20# \n#F40#【โหมดแอคทีฟ】: ก่อนเริ่มเทิร์นการกระทำ ฟื้นฟู HP #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# ของ HP เริ่มต้น\n#F20# \n#F40##L10#เขตแดนมิโกะ: #L0#สกิลออร่า โลกแฟนตาซีอยู่ภายใต้การควบคุมของมิโกะ ผืนดินฟื้นตัว ชีวิตเบ่งบาน พันธมิตรทุกคนได้รับการฟื้นฟู HP เพิ่มขึ้น 30% และตัวละครสายจิต, แสง, ดิน ได้รับผลสองเท่า; ตัวละครสายจิต, แสง, ดิน เพิ่มความสามารถในการชนะทางธาตุ 20%; เพิ่มความต้านทานธรรมชาติ 20%\n#F20# \n#F40##L10#จิตวิญญาณมิโกะ: #L0#เมื่อ HP ของเรย์มุต่ำกว่า 50% ครั้งแรก เธอจะหลอมรวมกับแฟนตาซี เปลี่ยนร่างเป็นกวางธรรมชาติ ไม่สามารถถูกโจมตีหรือได้รับสถานะ และจะส่งจิตวิญญาณ【สิง】ไปยังพันธมิตรที่มีพลังโจมตีสูงสุดเป็นเวลา 3 เทิร์น\n#F20# \n#F40#【สิง】: เอฟเฟกต์พิเศษ เพิ่มต้านคริติคอล, ป้องกันควบคุม, ฟื้นฟูโกรธ 50%, และเพิ่ม HP สูงสุดเท่ากับ 100% ของ HP เริ่มต้นของเรย์มุ เมื่อฮีโร่ที่ถูกสิงโจมตี จะปล่อยสกิลตามระดับ กวางธรรมชาติจะโจมตีศัตรูเดี่ยวอัตโนมัติทุกเทิร์น สร้างความเสียหายเวท #C0x3D8A99#300% พลังเวท#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#ความเสียหายเวท#C0x5B545B# เมื่อการสิงจบลง วิญญาณจะกลับเข้าร่าง และ HP ของเรย์มุจะฟื้นเป็น 100%',
		describe_in = '#L10#Aura Miko: #L0#Skill aura. Meningkatkan HP maksimum semua sekutu berdasarkan total 20% dari HP awal mereka dan Reimu Hakurei; Saat HP salah satu sekutu pertama kali turun di bawah 40%, memberikan 【Mode Aktif】selama 2 giliran\n#F20# \n#F40#【Mode Aktif】: Sebelum giliran aksi dimulai, memulihkan #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# dari HP maksimum awal\n#F20# \n#F40##L10#Domain Miko: #L0#Skill aura. Seluruh Gensokyo berada di bawah kendali pendeta kuil. Tanah bangkit kembali, kehidupan mekar. Semua sekutu menerima peningkatan penyembuhan sebesar 30%, dan dua kali lipat untuk pahlawan tipe Psikis, Suci, dan Tanah; Dominasi elemen alami dari tipe Psikis, Suci, dan Tanah meningkat 20%; Resistensi alami meningkat 20%\n#F20# \n#F40##L10#Roh Miko: #L0#Saat HP Reimu turun di bawah 50% untuk pertama kalinya, dia bersatu dengan Gensokyo dan berubah menjadi Roh Rusa Alam. Dia menjadi tidak bisa diserang dan kebal terhadap efek status, dan sebagian jiwanya akan【Merasuki】sekutu dengan serangan tertinggi selama 3 giliran\n#F20# \n#F40#【Rasuki】: Efek khusus yang meningkatkan Ketahanan Kritikal, Imunitas Kontrol, Kecepatan Pemulihan Rage sebesar 50%, dan HP maksimum sebesar 100% dari HP awal Reimu. Saat pahlawan yang dirasuki melakukan serangan biasa, roh yang merasuki akan menggunakan skill setingkat. Roh Rusa menyerang otomatis setiap giliran, memberikan #C0x3D8A99#300% serangan sihir#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#damage sihir#C0x5B545B# ke satu target. Setelah rasukan berakhir, jiwa kembali dan HP Reimu dipulihkan 100%',
		describe_ph = '#L10#Aura ng Miko: #L0#Aura skill. Pinapataas ang max HP ng lahat ng kakampi batay sa 20% ng kani-kanilang initial max HP at kay Reimu Hakurei; Kapag ang HP ng isang kakampi ay unang bumaba sa ilalim ng 40%, makakakuha ng 【Active Mode】sa loob ng 2 turno \n#F20# \n#F40#【Active Mode】: Bago magsimula ang turn ng aksyon, magreregenerate ng #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# ng initial max HP\n#F20# \n#F40##L10#Lupain ng Miko: #L0#Aura skill. Ang buong Gensokyo ay nasa ilalim ng kontrol ng shrine maiden. Muling nabubuhay ang lupa, namumukadkad ang buhay. Lahat ng kakampi ay tumatanggap ng 30% dagdag healing received, doble para sa mga bayani ng Psychic, Holy, at Earth na uri; Ang natural elemental dominance ng Psychic, Holy, at Earth na uri ay tumataas ng 20%; Natural resistance +20%\n#F20# \n#F40##L10#Espiritu ng Miko: #L0#Kapag ang HP ni Reimu ay bumaba sa ilalim ng 50% sa unang pagkakataon, siya ay magsasanib sa Gensokyo at magiging Deer Spirit ng Kalikasan. Hindi siya maaaring targetin at immune sa status effects, at bahagi ng kanyang kaluluwa ay 【Sumasanib】sa kakampi na may pinakamataas na attack sa loob ng 3 turno \n#F20# \n#F40#【Sanib】: Espesyal na epekto na nagpapataas ng Crit Resistance, Control Immunity, Rage Recovery Speed ng 50%, at Max HP na katumbas ng 100% ng initial max HP ni Reimu. Kapag ang sinanibang bayani ay gumawa ng normal attack, ang espiritu ay maglalabas ng skill ayon sa level. Awtomatikong umaatake ang Deer Spirit bawat turn, nagbibigay ng #C0x3D8A99#300% magic attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#magic damage#C0x5B545B# sa isang target. Matapos ang pagsanib, bumabalik ang kaluluwa at ang HP ni Reimu ay nagiging 100%',
		describe_ma = '#L10#Aura Miko: #L0#Kemahiran aura. Meningkatkan HP maksimum semua sekutu sebanyak jumlah 20% daripada HP awal mereka dan Reimu Hakurei; Apabila HP mana-mana sekutu jatuh di bawah 40% buat kali pertama, memberikan 【Mod Aktif】selama 2 pusingan\n#F20# \n#F40#【Mod Aktif】: Sebelum giliran tindakan bermula, memulihkan #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# daripada HP maksimum awal\n#F20# \n#F40##L10#Kawasan Miko: #L0#Kemahiran aura. Seluruh Gensokyo di bawah kawalan gadis kuil. Alam pulih, kehidupan berkembang. Semua sekutu menerima penyembuhan yang diterima sebanyak 30%, berganda untuk wira jenis Psikik, Suci, dan Bumi; Dominasi unsur semula jadi bagi wira Psikik, Suci, dan Bumi meningkat 20%; Rintangan semula jadi meningkat 20%\n#F20# \n#F40##L10#Semangat Miko: #L0#Apabila HP Reimu jatuh di bawah 50% buat kali pertama, dia akan bersatu dengan Gensokyo dan berubah menjadi Roh Rusa Alam. Dia tidak boleh disasarkan dan kebal terhadap kesan status, dan sebahagian jiwanya akan【Merasuk】sekutu dengan serangan tertinggi selama 3 pusingan\n#F20# \n#F40#【Rasuk】: Kesan khas yang meningkatkan Ketahanan Kritikal, Imuniti Kawalan, Kelajuan Pemulihan Amarah sebanyak 50%, dan HP maksimum sebanyak 100% daripada HP awal Reimu. Apabila wira yang dirasuk melakukan serangan biasa, roh akan menggunakan kemahiran setara. Roh Rusa akan menyerang secara automatik setiap giliran, memberikan #C0x3D8A99#300% serangan sihir#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#kerosakan sihir#C0x5B545B# kepada satu sasaran. Selepas rasukan tamat, roh kembali dan HP Reimu dipulihkan 100%',
		describe = '#L10#Miko Aura: #L0#Aura skill. Increases the max HP of all allies by the sum of 20% of their own and Reimu Hakurei’s initial max HP; When any ally’s HP falls below 40% for the first time, grants [Active Mode] for 2 turns\n#F20# \n#F40#[Active Mode]: At the start of the action turn, restores #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# of the initial max HP\n#F20# \n#F40##L10#Miko Domain: #L0#Aura skill. All of Gensokyo is under the shrine maiden’s control. Earth revives, life blooms. All allies\' healing received is increased by 30%, and doubled for heroes of Psychic, Holy, and Ground types; Psychic, Holy, and Ground type heroes\' natural elemental dominance is increased by 20%; Natural resistance increased by 20%\n#F20# \n#F40##L10#Miko Spirit: #L0#When Reimu\'s HP falls below 50% for the first time, she merges with Gensokyo and transforms into a Deer Spirit of Nature. She becomes untargetable and immune to status effects, and a part of her soul [Possesses] the ally with the highest attack for 3 turns\n#F20# \n#F40#[Possess]: A special effect that increases Crit Resistance, Control Immunity, Rage Recovery Speed by 50%, and Max HP by 100% of Reimu\'s initial max HP. When the possessed hero performs a normal attack, the possessing spirit casts a skill of corresponding level. The Deer Spirit automatically performs a normal attack each turn, dealing #C0x3D8A99#300% magic attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#magic damage#C0x5B545B# to a single target. After the possession ends, the soul returns to the deer, and Reimu\'s HP is restored to 100%',
		starEffect = __data_t__starEffect[36016],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi bắt đầu trận đấu, liên kết tất cả đồng minh bằng <Liên Kết Sinh Mệnh>, kéo dài đến lượt lớn tiếp theo sau khi bản thân hành động; khi đơn vị bị chiếm hữu nhận sát thương chí mạng, sẽ chặn sát thương này và thoát khỏi hiệu ứng <Chiếm Hữu>.',
		starEffectDesc = 'Additional effect: At the start of the battle, link all allies with <Life Link>, lasting until the next major turn after the unit acts; when a possessed unit receives critical damage, it blocks this damage and escapes the <Possession> effect.',
		starEffectDesc_en = 'Additional effect: At the start of the battle, link all allies with <Life Link>, lasting until the next major turn after the unit acts; when a possessed unit receives critical damage, it blocks this damage and escapes the <Possession> effect.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อเริ่มการต่อสู้ เชื่อมโยงพันธมิตรทั้งหมดด้วย <ลิงค์แห่งชีวิต> คงอยู่จนกว่าจะถึงรอบหลักถัดไปหลังจากที่ตนเองทำการกระทำ; เมื่อหน่วยที่ถูกครอบครองได้รับความเสียหายคริติคอล จะบล็อกความเสียหายนี้และหลุดออกจากเอฟเฟกต์ <ครอบครอง>.',
		starEffectDesc_in = 'Efek tambahan: Saat mulai pertarungan, hubungkan semua sekutu dengan <Liên Kết Sinh Mệnh>, berlangsung hingga giliran besar berikutnya setelah unit bertindak; ketika unit yang dikuasai menerima kerusakan kritis, akan memblokir kerusakan ini dan keluar dari efek <Chiếm Hữu>.',
		starEffectDesc_ph = 'Karagdagang epekto: Sa simula ng laban, i-link ang lahat ng mga kakampi gamit ang <Liên Kết Sinh Mệnh>, tatagal hanggang sa susunod na malaking turn matapos kumilos ang yunit; kapag ang yunit na nasakop ay tumanggap ng critical damage, babara ito sa pinsalang ito at aalis sa epekto ng <Chiếm Hữu>.',
		starEffectDesc_ma = 'Kesan tambahan: Pada permulaan pertempuran, pautkan semua sekutu dengan <Liên Kết Sinh Mệnh>, berlanjutan sehingga giliran besar seterusnya selepas unit bertindak; apabila unit yang dikuasai menerima kerosakan kritikal, ia akan menyekat kerosakan ini dan keluar dari kesan <Chiếm Hữu>.',
		zawakeEffect = __data_t__zawakeEffect[36016],
		-- {79004}
		zawakeEffectDesc = '#L10#Miko Aura:#L0# Aura skill, increases allies\' max HP by the sum of 20% of their own initial max HP and Reimu Hakurei\'s initial max HP; when an ally\'s HP drops below 40% for the first time, grants 【Active Mode】 for 2 turns\n#F20# \n#F40#【Active Mode】: Before action turn starts, restores #C0x5c9970#$(15+skillLevel0.1-0.1)$%#C0x5B545B# of initial max HP\n#F20# \n#F40##L10#Miko Field:#L0# Aura skill, all of Gensokyo is under the shrine maiden\'s control, the earth revives and life blooms; all heroes\' healing received is increased by 30%, Psychic, Holy Light, and Earth-type heroes gain double effect; these heroes also gain 20% increased natural elemental suppression and 20% increased natural resistance; during 【Life Link】, Psychic, Holy Light, and Earth-type heroes additionally restore 5% of their initial max HP after each action\n#F20# \n#F40##L10#Miko Spirit:#L0# When Reimu\'s HP first falls below 50%, she merges with Gensokyo, becoming a natural deer spirit, cannot be attacked or affected by new effects, and attaches part of her soul 【Possession】 to the ally with the highest attack for 3 turns; all units also gain 【Life Link】 until the end of their next action, and units with existing 【Life Link】 additionally restore 5% of their initial max HP\n#F20# \n#F40#【Possession】: Special effect, increases crit resistance, control immunity, rage recovery speed by 50%, and max HP by 100% of Reimu\'s initial max HP; when the possessed hero actively attacks, the soul releases a skill of corresponding level; the deer spirit performs a normal attack each turn, dealing #C0x3D8A99#300% magic attack#C0x5B545B# + $(skillLevel4*24)$ #C0xF13B54#magic damage#C0x5B545B# to a single target; after possession ends, the soul returns and Reimu\'s HP is restored to 100%',
		zawakeEffectDesc_en = '#L10#Miko Aura:#L0# Aura skill, increases allies\' max HP by the sum of 20% of their own initial max HP and Reimu Hakurei\'s initial max HP; when an ally\'s HP drops below 40% for the first time, grants 【Active Mode】 for 2 turns\n#F20# \n#F40#【Active Mode】: Before action turn starts, restores #C0x5c9970#$(15+skillLevel0.1-0.1)$%#C0x5B545B# of initial max HP\n#F20# \n#F40##L10#Miko Field:#L0# Aura skill, all of Gensokyo is under the shrine maiden\'s control, the earth revives and life blooms; all heroes\' healing received is increased by 30%, Psychic, Holy Light, and Earth-type heroes gain double effect; these heroes also gain 20% increased natural elemental suppression and 20% increased natural resistance; during 【Life Link】, Psychic, Holy Light, and Earth-type heroes additionally restore 5% of their initial max HP after each action\n#F20# \n#F40##L10#Miko Spirit:#L0# When Reimu\'s HP first falls below 50%, she merges with Gensokyo, becoming a natural deer spirit, cannot be attacked or affected by new effects, and attaches part of her soul 【Possession】 to the ally with the highest attack for 3 turns; all units also gain 【Life Link】 until the end of their next action, and units with existing 【Life Link】 additionally restore 5% of their initial max HP\n#F20# \n#F40#【Possession】: Special effect, increases crit resistance, control immunity, rage recovery speed by 50%, and max HP by 100% of Reimu\'s initial max HP; when the possessed hero actively attacks, the soul releases a skill of corresponding level; the deer spirit performs a normal attack each turn, dealing #C0x3D8A99#300% magic attack#C0x5B545B# + $(skillLevel4*24)$ #C0xF13B54#magic damage#C0x5B545B# to a single target; after possession ends, the soul returns and Reimu\'s HP is restored to 100%',
		zawakeEffectDesc_th = '#L10#ออร่ามิโกะ:#L0# สกิลออร่า เพิ่ม HP สูงสุดของพันธมิตรทั้งหมด โดยรวม 20% ของ HP เริ่มต้นตัวเองและ HP เริ่มต้นของเรย์มุ; เมื่อ HP ของพันธมิตรต่ำกว่า 40% ครั้งแรก จะได้รับ 【โหมดกระตือรือร้น】 2 เทิร์น\n#F20# \n#F40#【โหมดกระตือรือร้น】: ก่อนเริ่มเทิร์น ฟื้น HP #C0x5c9970#$(15+skillLevel0.1-0.1)$%#C0x5B545B# ของ HP เริ่มต้น\n#F20# \n#F40##L10#สนามมิโกะ:#L0# สกิลออร่า ทุกสิ่งในเกนโซเคียวอยู่ภายใต้การควบคุมของมิโกะ แผ่นดินฟื้น ชีวิตเบ่งบาน พันธมิตรทั้งหมดได้รับการรักษาเพิ่ม 30% ฮีโร่ประเภทจิต แสงศักดิ์สิทธิ์ และดิน ได้ผลคูณสอง; ฮีโร่ทั้งสามยังได้การกดธาตุธรรมชาติ +20% และต้านทานธาตุธรรมชาติ +20%; ในช่วง 【สายสัมพันธ์ชีวิต】 ฮีโร่ทั้งสามจะฟื้น HP เพิ่ม 5% ของ HP เริ่มต้น หลังจบการกระทำ\n#F20# \n#F40##L10#จิตวิญญาณมิโกะ:#L0# เมื่อ HP ของเรย์มุต่ำกว่า 50% ครั้งแรก เธอจะรวมเข้ากับเกนโซเคียว กลายเป็นวิญญาณกวางธรรมชาติ ไม่สามารถถูกโจมตีหรือรับเอฟเฟกต์ใหม่ และจะ 【สิง】 พันธมิตรที่โจมตีสูงสุด 3 เทิร์น; ทุกยูนิตจะได้รับ 【สายสัมพันธ์ชีวิต】 จนกว่าจบการกระทำถัดไป และยูนิตที่มี 【สายสัมพันธ์ชีวิต】 จะฟื้น HP เพิ่มอีก 5%\n#F20# \n#F40#【สิง】: เอฟเฟกต์พิเศษ เพิ่มต้านคริติคอล ต้านควบคุม และความเร็วฟื้นค่าโกรธ 50% และ HP สูงสุด +100% ของ HP เริ่มต้นเรย์มุ; เมื่อฮีโร่ที่ถูกสิงโจมตี วิญญาณจะปล่อยสกิลระดับเดียวกัน วิญญาณกวางจะโจมตีปกติทุกเทิร์น สร้าง #C0x3D8A99#300% พลังเวท#C0x5B545B# + $(skillLevel4*24)$ #C0xF13B54#ความเสียหายเวท#C0x5B545B# ใส่เป้าหมายเดี่ยว หลังจบการสิง วิญญาณจะกลับ และ HP ของเรย์มุฟื้นเต็ม 100%',
		zawakeEffectDesc_in = '#L10#Aura Miko:#L0# Skill aura, meningkatkan max HP sekutu sebesar total 20% dari HP awal mereka sendiri dan Reimu Hakurei; saat HP sekutu turun di bawah 40% pertama kali, mendapatkan 【Mode Aktif】 selama 2 giliran\n#F20# \n#F40#【Mode Aktif】: Sebelum giliran dimulai, memulihkan #C0x5c9970#$(15+skillLevel0.1-0.1)$%#C0x5B545B# dari HP awal\n#F20# \n#F40##L10#Medan Miko:#L0# Skill aura, segala sesuatu di Gensokyo di bawah kendali Miko, bumi bangkit, kehidupan tumbuh; semua hero menerima peningkatan penyembuhan 30%, hero tipe Psychic, Holy Light, dan Earth efeknya ganda; hero tipe tersebut juga mendapat 20% tambahan counter elemen natural dan 20% resistansi natural; selama 【Life Link】, hero-hero ini memulihkan tambahan 5% HP awal setelah aksi\n#F20# \n#F40##L10#Roh Miko:#L0# Saat HP Reimu pertama kali turun di bawah 50%, dia menyatu dengan Gensokyo menjadi roh rusa alam, tidak bisa diserang atau diberi efek baru, dan 【Menjelma】 pada sekutu dengan serangan tertinggi selama 3 giliran; semua unit juga memperoleh 【Life Link】 hingga akhir aksi berikutnya, dan unit dengan 【Life Link】 memulihkan tambahan 5% HP awal\n#F20# \n#F40#【Menjelma】: Efek khusus, meningkatkan resist crit, imun kontrol, kecepatan pemulihan rage 50%, serta max HP +100% dari HP awal Reimu; saat hero yang dijelmakan menyerang, roh akan melepaskan skill setara; roh rusa menyerang normal setiap giliran, memberikan #C0x3D8A99#300% magic attack#C0x5B545B# + $(skillLevel4*24)$ #C0xF13B54#magic damage#C0x5B545B# ke target tunggal; setelah selesai, roh kembali, dan HP Reimu pulih ke 100%',
		zawakeEffectDesc_ph = '#L10#Miko Aura:#L0# Aura skill, pinapataas ang max HP ng lahat ng kakampi ng 20% mula sa sariling initial HP at kay Reimu Hakurei; kapag bumaba sa 40% ang HP ng kakampi sa unang beses, makakakuha ng 【Active Mode】 sa loob ng 2 turns\n#F20# \n#F40#【Active Mode】: Bago magsimula ang turn, nagre-restore ng #C0x5c9970#$(15+skillLevel0.1-0.1)$%#C0x5B545B# ng initial HP\n#F20# \n#F40##L10#Miko Field:#L0# Aura skill, lahat sa Gensokyo ay nasa ilalim ng kontrol ng shrine maiden, muling nabubuhay ang lupa, namumukadkad ang buhay; lahat ng heroes tumatanggap ng 30% dagdag healing, heroes na Psychic, Holy Light, at Earth doble ang effect; heroes na ito nakakatanggap din ng +20% natural counter at +20% natural resistance; sa 【Life Link】, heroes na ito nagre-restore pa ng 5% initial HP pagkatapos ng bawat aksyon\n#F20# \n#F40##L10#Miko Spirit:#L0# Kapag bumaba sa 50% ang HP ni Reimu sa unang beses, magsasanib siya sa Gensokyo at magiging deer spirit, hindi ma-atake at immune sa bagong effects, at 【Possess】 sa kakampi na may pinakamataas na attack sa loob ng 3 turns; lahat ng units makakakuha ng 【Life Link】 hanggang matapos ang susunod na aksyon, at units na may 【Life Link】 magre-restore pa ng 5% initial HP\n#F20# \n#F40#【Possess】: Special effect, +50% crit resist, control immunity, rage recovery speed, at +100% max HP mula kay Reimu; kapag umatake ang possessed hero, maglalabas ang soul ng corresponding skill; deer spirit normal attack kada turn, dealing #C0x3D8A99#300% magic attack#C0x5B545B# + $(skillLevel4*24)$ #C0xF13B54#magic damage#C0x5B545B# sa isang target; pagkatapos, babalik ang soul at HP ni Reimu 100%',
		zawakeEffectDesc_ma = '#L10#Aura Miko:#L0# Skill aura, meningkatkan HP maksimum sekutu sebanyak 20% daripada HP asal mereka sendiri dan Reimu Hakurei; apabila HP sekutu jatuh di bawah 40% buat pertama kali, akan menerima 【Mod Aktif】 selama 2 pusingan\n#F20# \n#F40#【Mod Aktif】: Sebelum giliran bermula, memulihkan #C0x5c9970#$(15+skillLevel0.1-0.1)$%#C0x5B545B# daripada HP asal\n#F20# \n#F40##L10#Medan Miko:#L0# Skill aura, segala di Gensokyo di bawah kawalan Miko, bumi bangkit semula, kehidupan berkembang; semua hero mendapat peningkatan penyembuhan 30%, hero Psychic, Holy Light, dan Earth mendapat kesan berganda; hero ini juga mendapat +20% kelebihan lawan elemen semula jadi dan +20% ketahanan semula jadi; semasa 【Life Link】, hero ini memulihkan tambahan 5% HP asal selepas setiap tindakan\n#F20# \n#F40##L10#Roh Miko:#L0# Apabila HP Reimu jatuh di bawah 50% buat pertama kali, dia bersatu dengan Gensokyo, menjadi roh rusa semula jadi, tidak boleh diserang atau diberikan kesan baharu, dan 【Menjelma】 pada sekutu dengan serangan tertinggi selama 3 pusingan; semua unit turut menerima 【Life Link】 sehingga akhir tindakan seterusnya, dan unit yang mempunyai 【Life Link】 memulihkan tambahan 5% HP asal\n#F20# \n#F40#【Menjelma】: Kesan khas, meningkatkan resist crit, imun kawalan, kadar pemulihan rage 50%, serta +100% HP maksimum daripada HP asal Reimu; apabila hero yang dijelmakan menyerang, roh akan melepaskan skill setara; roh rusa menyerang normal setiap pusingan, memberikan #C0x3D8A99#300% serangan magik#C0x5B545B# + $(skillLevel4*24)$ #C0xF13B54#kerosakan magik#C0x5B545B# kepada satu sasaran; selepas tamat, roh kembali dan HP Reimu pulih ke 100%',
		zawakeEffectDesc_vn = '#L10#Hào quang vu nữ:#L0# Kỹ năng hào quang, tăng giới hạn HP tối đa của toàn bộ đồng minh bằng tổng 20% HP gốc của bản thân và HP gốc của Hakurei Reimu; khi HP của đồng minh lần đầu tiên giảm xuống dưới 40%, nhận được 【Chế độ hoạt động】 trong 2 lượt\n#F20# \n#F40#【Chế độ hoạt động】: Trước khi bắt đầu lượt hành động, hồi phục #C0x5c9970#$(15+skillLevel0.1-0.1)$%#C0x5B545B# HP gốc\n#F20# \n#F40##L10#Khí trường vu nữ:#L0# Kỹ năng hào quang, mọi thứ ở Ảo Tưởng Hương đều dưới sự kiểm soát của vu nữ, đất hồi sinh, sự sống bùng nở; toàn bộ anh hùng nhận hiệu quả trị liệu tăng 30%, các anh hùng hệ Siêu năng, Thánh quang, Địa nhận hiệu quả gấp đôi; các anh hùng này còn nhận thêm 20% khắc chế thuộc tính tự nhiên và 20% kháng thuộc tính tự nhiên; trong thời gian tồn tại 【Liên kết Sinh mệnh】, các anh hùng này hồi phục thêm 5% HP gốc sau mỗi hành động\n#F20# \n#F40##L10#Linh hồn vu nữ:#L0# Khi HP của Reimu lần đầu tiên giảm xuống dưới 50%, cô hòa vào Ảo Tưởng Hương, hóa thành Linh Hươu Tự nhiên, không thể bị tấn công hoặc nhận thêm hiệu ứng mới, đồng thời 【Nhập hồn】 vào đồng minh có công kích cao nhất trong 3 lượt; toàn bộ đơn vị trên sân cũng nhận được 【Liên kết Sinh mệnh】 cho đến hết lượt hành động tiếp theo, và các đơn vị đã có 【Liên kết Sinh mệnh】 hồi thêm 5% HP gốc\n#F20# \n#F40#【Nhập hồn】: Hiệu ứng đặc biệt, tăng 50% kháng bạo, miễn khống chế, tốc độ hồi nộ, và tăng HP tối đa bằng 100% HP gốc của Reimu; khi anh hùng được nhập hồn tấn công chủ động, linh hồn sẽ giải phóng kỹ năng tương ứng; Linh Hươu Tự nhiên mỗi lượt sẽ tự động tấn công thường, gây #C0x3D8A99#300% công phép#C0x5B545B# + $(skillLevel4*24)$ #C0xF13B54#sát thương phép#C0x5B545B# lên mục tiêu đơn; sau khi kết thúc nhập hồn, linh hồn trở về, và HP của Hakurei Reimu được hồi lại 100%',
		zawakeSimpleType = 1,
		iconRes = 'battle/skill_icon/skill_36016.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		skillProcess = {360162, 360163, 360164, 360165}
	},
	[36021] = {
		id = 36021,
		skillName_vn = 'Tấn công mặt trăng',
		skillName_en = 'Attack the moon',
		skillName_th = 'โจมตีพระจันทร์',
		skillName_in = 'Serang bulan',
		skillName_ph = 'Atakihin ang buwan',
		skillName_ma = 'Serang bulan',
		skillName = 'Attack the moon',
		describe_vn = 'Xerneas sử dụng sừng tấn công mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#100% Phép Công#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, tăng 15% kháng chí mạng và 15% giảm sát thương cho bản thân, kéo dài 2 lượt\n#F20# \n#F40#[Trạng thái nhập thân] tăng 15% kháng chí mạng và 15% giảm sát thương cho một đơn vị ngẫu nhiên khác, kéo dài 2 lượt',
		describe_en = 'Xerneas uses its horn to attack a single enemy target, dealing #C0x3D8A99#100% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage #C0x5B545B#, increases 15% critical resistance and 15% damage reduction for itself, lasting 2 turns. \n#F20# \n#F40#[Merged state] increases 15% critical resistance and 15% damage reduction for a random ally, lasting 2 turns.',
		describe_th = 'Xerneas ใช้เขาส่งผลการโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายเวท #C0x3D8A99#100% พลังโจมตีเวท#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายเวท #C0x5B545B# เพิ่มความต้านทานคริติคอล 15% และลดความเสียหาย 15% ให้ตัวเอง เป็นเวลา 2 เทิร์น \n#F20# \n#F40#[สถานะเข้าร่วม] เพิ่มความต้านทานคริติคอล 15% และลดความเสียหาย 15% ให้หน่วยสุ่มอื่น 1 หน่วย เป็นเวลา 2 เทิร์น',
		describe_in = 'Xerneas menggunakan tanduknya untuk menyerang satu target musuh, memberikan #C0x3D8A99#100% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerusakan Sihir #C0x5B545B#, meningkatkan 15% ketahanan kritis dan pengurangan damage 15% untuk diri sendiri, bertahan selama 2 giliran. \n#F20# \n#F40#[Status menyatu] meningkatkan 15% ketahanan kritis dan pengurangan damage 15% untuk satu unit lain secara acak, bertahan selama 2 giliran.',
		describe_ph = 'Ginagamit ng Xerneas ang kanyang sungay upang atakihin ang isang kalabang target, nagdudulot ng #C0x3D8A99#100% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage #C0x5B545B#, nagpapataas ng 15% kritikal na resistensya at 15% pagbabawas ng pinsala para sa sarili, tumatagal ng 2 na turn. \n#F20# \n#F40#[Merged state] nagpapataas ng 15% kritikal na resistensya at 15% pagbabawas ng pinsala para sa isang random na yunit, tumatagal ng 2 na turn.',
		describe_ma = 'Xerneas menggunakan tanduk untuk menyerang satu sasaran musuh tunggal, memberi #C0x3D8A99#100% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerosakan Sihir #C0x5B545B#, meningkatkan 15% ketahanan kritikal dan 15% pengurangan kerosakan untuk diri sendiri, bertahan selama 2 pusingan. \n#F20# \n#F40#[Status penyatuan] meningkatkan 15% ketahanan kritikal dan 15% pengurangan kerosakan untuk satu unit rawak lain, bertahan selama 2 pusingan.',
		describe = 'Xerneas uses its horn to attack a single enemy target, dealing #C0x3D8A99#100% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage #C0x5B545B#, increases 15% critical resistance and 15% damage reduction for itself, lasting 2 turns. \n#F20# \n#F40#[Merged state] increases 15% critical resistance and 15% damage reduction for a random ally, lasting 2 turns.',
		iconRes = 'battle/skill_icon/skill_36011.png',
		changeUnitTrigger = true,
		isCombat = true,
