	[36022] = {
		id = 36022,
		skillName_vn = 'Chế độ thư giãn',
		skillName_en = 'Relaxation mode',
		skillName_th = 'โหมดผ่อนคลาย',
		skillName_in = 'Mode relaksasi',
		skillName_ph = 'Relaxation mode',
		skillName_ma = 'Mod santai',
		skillName = 'Relaxation mode',
		describe_vn = 'Xerneas mượn sức mạnh của mặt trăng tấn công hàng trước của kẻ địch, gây ra #C0x3D8A99#160% Phép Công#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đồng thời khiến bản thân và một đơn vị ngẫu nhiên ở hàng sau nhận được [Chế độ thư giãn] trong 1 lượt (ưu tiên đơn vị nhập thân), trong [Chế độ thư giãn], bản thân khi sử dụng kỹ năng nhỏ lần này và tấn công chủ động lần sau cùng đồng đội tấn công cùng mục tiêu sẽ có 100% xác suất làm [choáng] mục tiêu trong 1 lượt (tối đa làm choáng 3 người cùng lúc)\n#F20# \n#F40#[Chế độ thư giãn]: Hiệu ứng đặc biệt, không thể bị xóa, chuyển hoặc sao chép, ẩn thân và tăng 100% phòng thủ đôi',
		describe_en = 'Xerneas borrows the power of the moon to attack the enemy\'s front row, dealing #C0x3D8A99#160% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage #C0x5B545B#, and simultaneously causes itself and a random unit in the back row to receive [Relaxation Mode] for 1 turn (prioritizing merged units). In [Relaxation Mode], when it uses a minor skill this time and the next active attack with teammates targeting the same enemy occurs, there is a 100% chance to [stun] the target for 1 turn (up to 3 enemies can be stunned simultaneously). \n#F20# \n#F40#[Relaxation Mode]: Special effect, cannot be removed, transferred or copied, stealths and doubles defense by 100%.',
		describe_th = 'เซอร์เนียส ยืมพลังของดวงจันทร์โจมตีแถวหน้าของศัตรู สร้างความเสียหายเวทย์ #C0x3D8A99#160% พลังโจมตีเวทย์#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายเวทย์ #C0x5B545B# พร้อมกันนั้นทำให้ตัวเองและหน่วยสุ่มหนึ่งตัวในแถวหลังได้รับ สถานะ [โหมดผ่อนคลาย] เป็นเวลา 1 เทิร์น (ให้ความสำคัญกับหน่วยผสาน) ใน [โหมดผ่อนคลาย] เมื่อใช้สกิลเล็กในครั้งนี้และการโจมตีครั้งถัดไปพร้อมกับเพื่อนร่วมทีมที่โจมตีเป้าหมายเดียวกัน จะมีโอกาส 100% ทำให้เป้าหมาย [มึนงง] เป็นเวลา 1 เทิร์น (ทำให้มึนงงได้สูงสุด 3 คนพร้อมกัน) \n#F20# \n#F40#[โหมดผ่อนคลาย]: เอฟเฟกต์พิเศษ ไม่สามารถลบ โอนย้าย หรือคัดลอก ซ่อนตัว และเพิ่มการป้องกันเป็น 100%.',
		describe_in = 'Xerneas meminjam kekuatan bulan untuk menyerang barisan depan musuh, menyebabkan #C0x3D8A99#160% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerusakan Sihir #C0x5B545B#, sekaligus membuat dirinya sendiri dan satu unit acak di barisan belakang menerima [Mode Relaksasi] selama 1 giliran (mengutamakan unit yang bergabung). Dalam [Mode Relaksasi], ketika menggunakan skill kecil kali ini dan serangan aktif berikutnya bersama rekan menyerang target yang sama akan memiliki peluang 100% untuk [membungkam] target selama 1 giliran (maksimal membungkam 3 musuh sekaligus). \n#F20# \n#F40#[Mode Relaksasi]: Efek khusus, tidak bisa dihapus, dipindahkan atau disalin, sembunyi dan meningkatkan pertahanan sebesar 100%.',
		describe_ph = 'Umiuutang ng lakas ng buwan si Xerneas para atakihin ang harap na hanay ng kalaban, nagdudulot ng #C0x3D8A99#160% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage #C0x5B545B#, kasabay na inilalagay ang sarili at isang random na yunit sa likod na hanay ng [Relaxation Mode] sa loob ng 1 round (binibigyang prayoridad ang naka-merging na yunit). Sa [Relaxation Mode], kapag ginamit ang maliit na skill sa pagkakataong ito at sa susunod na aktibong atake kasama ng mga kasama na tumatarget sa parehong kalaban, may 100% tsansang ma-[stun] ang target sa loob ng 1 round (hanggang 3 yunit ang pwedeng ma-stun nang sabay). \n#F20# \n#F40#[Relaxation Mode]: Espesyal na epekto, hindi maaaring alisin, ilipat, o kopyahin, nagtatago at nagpapalakas ng depensa ng 100%.',
		describe_ma = 'Xerneas meminjam kuasa bulan untuk menyerang barisan hadapan musuh, menyebabkan #C0x3D8A99#160% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerosakan Sihir #C0x5B545B#, serta menyebabkan dirinya dan satu unit secara rawak di barisan belakang menerima [Mod Relax] selama 1 pusingan (utamakan unit gabungan). Dalam [Mod Relax], apabila menggunakan kemahiran kecil kali ini dan serangan aktif seterusnya bersama rakan menyerang sasaran yang sama, akan ada peluang 100% untuk [membutakan] sasaran selama 1 pusingan (maksima membutakan 3 sasaran sekaligus). \n#F20# \n#F40#[Mod Relax]: Kesan khas, tidak boleh dihapus, dipindah atau disalin, menyamar dan meningkatkan pertahanan sebanyak 100%.',
		describe = 'Xerneas borrows the power of the moon to attack the enemy\'s front row, dealing #C0x3D8A99#160% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage #C0x5B545B#, and simultaneously causes itself and a random unit in the back row to receive [Relaxation Mode] for 1 turn (prioritizing merged units). In [Relaxation Mode], when it uses a minor skill this time and the next active attack with teammates targeting the same enemy occurs, there is a 100% chance to [stun] the target for 1 turn (up to 3 enemies can be stunned simultaneously). \n#F20# \n#F40#[Relaxation Mode]: Special effect, cannot be removed, transferred or copied, stealths and doubles defense by 100%.',
		iconRes = 'battle/skill_icon/skill_36012.png',
