	[36031] = {
		id = 36031,
		skillName_vn = 'Tấn công mặt trăng',
		skillName_en = 'Attack the moon',
		skillName_th = 'โจมตีดวงจันทร์',
		skillName_in = 'Serang bulan',
		skillName_ph = 'Atake ang buwan',
		skillName_ma = 'Serang bulan',
		skillName = 'Attack the moon',
		describe_vn = 'Thần Hươu Chín Màu sử dụng sừng tấn công mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#100% sát thương phép#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#sát thương phép#C0x5B545B#, tăng 15% kháng chí mạng và 15% giảm sát thương cho bản thân, kéo dài 2 lượt\n#F20# \n#F40#[Phụ thân] trạng thái tăng 15% kháng chí mạng và 15% giảm sát thương cho một đơn vị ngẫu nhiên khác, kéo dài 2 lượt',
		describe_en = 'The Nine-Colored Deer God uses its antlers to attack a single enemy target, dealing #C0x3D8A99#100% magical damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# magical damage#C0x5B545B#, increases own critical resistance and damage reduction by 15% each, lasting 2 turns \n#F20# \n#F40#[Father] status increases a random ally\'s critical resistance and damage reduction by 15% each, lasting 2 turns',
		describe_th = 'เทพกวางเก้าสีใช้เขาโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายเวท #C0x3D8A99#100%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายเวท#C0x5B545B# เพิ่มความต้านทานคริติคอลและลดความเสียหายของตนเอง 15% เป็นเวลา 2 ตา \n#F20# \n#F40#[บิดา] สถานะเพิ่มความต้านทานคริติคอลและลดความเสียหาย 15% ให้กับหน่วยสุ่มอีกหนึ่งหน่วย เป็นเวลา 2 ตา',
		describe_in = 'Dewa Rusa Sembilan Warna menggunakan tanduknya untuk menyerang satu target musuh, memberikan #C0x3D8A99#100% kerusakan sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# kerusakan sihir#C0x5B545B#, meningkatkan ketahanan kritis dan pengurangan kerusakan diri sendiri sebesar 15% masing-masing, bertahan selama 2 giliran \n#F20# \n#F40#[Ayah] status meningkatkan ketahanan kritis dan pengurangan kerusakan sebesar 15% untuk satu unit acak lainnya, bertahan selama 2 giliran',
		describe_ph = 'Ang Diyos na Siyam na Kulay na Usa ay gumagamit ng mga sungay upang atakihin ang isang solong target ng kalaban, nagdudulot ng #C0x3D8A99#100% pinsalang mahika#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# pinsalang mahika#C0x5B545B#, tumataas ng 15% ang sariling resistensya sa kritikal at pagbawas ng pinsala, tumatagal ng 2 turn \n#F20# \n#F40#[Ama] ang estado ay nagpapataas ng 15% resistensya sa kritikal at pagbawas ng pinsala para sa isang random na yunit, tumatagal ng 2 turn',
		describe_ma = 'Dewa Rusa Sembilan Warna menggunakan tanduknya untuk menyerang satu sasaran musuh, memberikan #C0x3D8A99#100% kerosakan sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# kerosakan sihir#C0x5B545B#, meningkatkan ketahanan kritikal dan pengurangan kerosakan diri sendiri sebanyak 15% masing-masing, berlangsung selama 2 pusingan \n#F20# \n#F40#[Bapa] status meningkatkan ketahanan kritikal dan pengurangan kerosakan sebanyak 15% untuk satu unit rawak lain, berlangsung selama 2 pusingan',
		describe = 'The Nine-Colored Deer God uses its antlers to attack a single enemy target, dealing #C0x3D8A99#100% magical damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# magical damage#C0x5B545B#, increases own critical resistance and damage reduction by 15% each, lasting 2 turns \n#F20# \n#F40#[Father] status increases a random ally\'s critical resistance and damage reduction by 15% each, lasting 2 turns',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 0,
		skillDamageType = 1,
		skillNatureType = 18,
		posChoose = 1,
		targetTypeDesc = 'Single enemy',
		targetTypeDesc_vn = 'Đơn thể địch',
		targetTypeDesc_en = 'Single enemy',
		targetTypeDesc_th = 'ศัตรูเดี่ยว',
		targetTypeDesc_in = 'Musuh tunggal',
		targetTypeDesc_ph = 'Kalabang iisa',
		targetTypeDesc_ma = 'Musuh tunggal',
		targetChooseType = 'single',
		damageFormula = 'self:hasBuff(3601158) and (self:specialDamage()*3+(self:flag(99) and skillLevel or skillLevel*4)*24) or (self:specialDamage()*1+(self:flag(99) and skillLevel or skillLevel*4)*24)',
		skillProcess = {360311, 360312},
