	[36032] = {
		id = 36032,
		skillName_vn = 'Chế độ thư giãn',
		skillName_en = 'Relaxation mode',
		skillName_th = 'โหมดผ่อนคลาย',
		skillName_in = 'Mode relaksasi',
		skillName_ph = 'Relaxation mode',
		skillName_ma = 'Mod relaksasi',
		skillName = 'Relaxation mode',
		describe_vn = 'Thần Hươu Chín Màu mượn sức mạnh của mặt trăng để tấn công hàng trước của kẻ địch, gây #C0x3D8A99#160% sát thương phép#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#sát thương phép#C0x5B545B#, đồng thời khiến bản thân và một đơn vị ngẫu nhiên khác ở hàng sau nhận được [Chế độ thư giãn] trong 1 lượt (ưu tiên đơn vị phụ thân), trong trạng thái [Chế độ thư giãn], kỹ năng nhỏ lần này và lần tấn công chủ động tiếp theo của bản thân cùng với đồng đội tấn công cùng mục tiêu sẽ có 100% xác suất làm [Choáng] mục tiêu trong 1 lượt (tối đa làm choáng 3 người cùng lúc)\n#F20# \n#F40#[Chế độ thư giãn]: Hiệu ứng đặc biệt, không thể bị xóa, chuyển hoặc sao chép, ẩn thân và tăng 100% phòng thủ đôi',
		describe_en = 'The Nine-Colored Deer borrows the power of the moon to attack the enemy\'s front row, dealing #C0x3D8A99#160% magical damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# magical damage#C0x5B545B#. At the same time, it causes itself and one other random unit in the back row to receive [Relaxation Mode] for 1 turn (prioritizing support units). While in [Relaxation Mode], this minor skill and the user\'s next active attack along with allies attacking the same target have a 100% chance to [Stun] the target for 1 turn (maximum 3 units can be stunned simultaneously). \n#F20# \n#F40#[Relaxation Mode]: A special effect that cannot be removed, transferred, or copied; grants invisibility and doubles defense by 100%.',
		describe_th = 'กวางเก้าสียืมพลังของดวงจันทร์โจมตีแถวหน้าของศัตรู ทำดาเมจเวท #C0x3D8A99#160%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ดาเมจเวท#C0x5B545B# พร้อมกันนี้ทำให้ตัวเองและหน่วยสุ่มหนึ่งในแถวหลังได้รับ [โหมดผ่อนคลาย] เป็นเวลา 1 เทิร์น (ให้ความสำคัญกับหน่วยสนับสนุน) ในสถานะ [โหมดผ่อนคลาย] สกิลเล็กครั้งนี้และการโจมตีครั้งต่อไปของผู้ใช้พร้อมกับพันธมิตรที่โจมตีเป้าหมายเดียวกันมีโอกาส 100% ที่จะทำให้เป้าหมาย [มึนงง] เป็นเวลา 1 เทิร์น (สูงสุดพร้อมกัน 3 คน) \n#F20# \n#F40#[โหมดผ่อนคลาย]: เอฟเฟกต์พิเศษ ไม่สามารถถูกลบ โอน หรือคัดลอก ซ่อนตัวและเพิ่มพลังป้องกันเป็นสองเท่า 100%',
		describe_in = 'Rusa Sembilan Warna meminjam kekuatan bulan untuk menyerang bar depan musuh, memberikan #C0x3D8A99#160% kerusakan magis#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# kerusakan magis#C0x5B545B#, sekaligus menyebabkan dirinya sendiri dan satu unit acak lain di barisan belakang menerima [Mode Santai] selama 1 giliran (utamakan unit pendukung). Dalam keadaan [Mode Santai], keterampilan kecil ini dan serangan aktif berikutnya dari pengguna bersama sekutu yang menyerang target yang sama memiliki peluang 100% untuk [Membuat Pingsan] target selama 1 giliran (maksimal 3 orang dapat dibuat pingsan bersamaan). \n#F20# \n#F40#[Mode Santai]: Efek khusus yang tidak dapat dihapus, dipindahkan, atau disalin; menyembunyikan diri dan meningkatkan pertahanan sebanyak 100%.',
		describe_ph = 'Ang Siyam na Kulay na Usa ay humiram ng lakas ng buwan upang atakihin ang harapang linya ng kalaban, nagdudulot ng #C0x3D8A99#160% na magic damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# magic damage#C0x5B545B#. Kasabay nito, ang sarili at isang random na yunit sa likod na linya ay nakakakuha ng [Relaxation Mode] sa loob ng 1 turn (binibigyang prayoridad ang suportang yunit). Sa loob ng [Relaxation Mode], ang maliit na kasanayang ito at ang susunod na active attack ng sarili kasama ang mga kakampi na umatake sa parehong target ay may 100% tsansang [Stun] ang target sa loob ng 1 turn (maximum na 3 yunit ang maaaring ma-stun nang sabay-sabay). \n#F20# \n#F40#[Relaxation Mode]: Isang espesyal na epekto na hindi maaaring alisin, ilipat, o kopyahin; nagiging invisible at tumataas ng 100% ang depensa.',
		describe_ma = 'Rusa Sembilan Warna meminjam kekuatan bulan untuk menyerang barisan depan musuh, menyebabkan #C0x3D8A99#160% kerosakan sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# kerosakan sihir#C0x5B545B#, serta menyebabkan diri sendiri dan satu unit rawak lain di barisan belakang menerima [Mod Rehat] selama 1 pusingan (utamakan unit sokongan). Dalam keadaan [Mod Rehat], kemahiran kecil kali ini dan serangan aktif seterusnya oleh diri sendiri bersama sekutu yang menyerang sasaran yang sama mempunyai peluang 100% untuk [Menenangkan] sasaran selama 1 pusingan (maksimum 3 orang boleh menenangkan serentak). \n#F20# \n#F40#[Mod Rehat]: Kesan khas, tidak boleh dialih, dipindah atau disalin; menjadi tersembunyi dan meningkatkan pertahanan dua kali ganda iaitu 100%.',
		describe = 'The Nine-Colored Deer borrows the power of the moon to attack the enemy\'s front row, dealing #C0x3D8A99#160% magical damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# magical damage#C0x5B545B#. At the same time, it causes itself and one other random unit in the back row to receive [Relaxation Mode] for 1 turn (prioritizing support units). While in [Relaxation Mode], this minor skill and the user\'s next active attack along with allies attacking the same target have a 100% chance to [Stun] the target for 1 turn (maximum 3 units can be stunned simultaneously). \n#F20# \n#F40#[Relaxation Mode]: A special effect that cannot be removed, transferred, or copied; grants invisibility and doubles defense by 100%.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
