	[36033] = {
		id = 36033,
		skillName_vn = 'Kiểm soát đất đai',
		skillName_en = 'Land control',
		skillName_th = 'การควบคุมที่ดิน',
		skillName_in = 'Kontrol tanah',
		skillName_ph = 'Kontrol sa lupa',
		skillName_ma = 'Kawalan tanah',
		skillName = 'Land control',
		describe_vn = 'Thần Hươu Chín Màu sử dụng sức mạnh của khu rừng để tấn công tất cả các mục tiêu của kẻ thù, gây ra #C0x3D8A99#200% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#sát thương ma thuật#C0x5B545B# và sử dụng sức mạnh của khu rừng để liên kết năng lượng sống trong tất cả đồng đội để tạo thành [Liên kết cuộc sống]\n#F20# \n#F40##L10#Life Link: #L0#Giảm sát thương cuối cùng tăng thêm 35% (giảm 10% mỗi lần thêm vào, tối đa 15%; đơn vị vô hình tăng thêm 15%). Khi đơn vị liên kết bị hư hỏng, 60% thiệt hại sẽ được chia đều cho các đơn vị liên kết khác. Khi liên kết sự sống được thêm vào, mỗi đơn vị được liên kết sẽ phục hồi 15% HP từ giới hạn tuổi thọ cơ bản của Thần Hươu Chín Màu. Liên kết sẽ biến mất sau 1 lượt hành động của Thần Hươu Chín Màu (linh hồn hươu biến mất sau 1 lượt hành động của linh hồn thể)',
		describe_en = 'The Nine-Colored Deer God uses the power of the forest to attack all enemy targets, dealing #C0x3D8A99#200% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B# and harnesses the forest\'s power to link the life energy among all allies, forming [Life Link]\n#F20# \n#F40##L10#Life Link: #L0#Reduces final damage taken by 35% (decreases by 10% with each addition, up to 15%; invisible units gain an extra 15%). When a linked unit takes damage, 60% of that damage is evenly distributed among the other linked units. When Life Link is applied, each linked unit recovers 15% HP based on the Nine-Colored Deer God\'s base lifespan. The link disappears after the Nine-Colored Deer God\'s next action (the deer\'s spirit vanishes after one action of the spirit body).',
		describe_th = 'เทพกวางเก้าสีใช้พลังของป่าเพื่อโจมตีเป้าหมายศัตรูทั้งหมด ก่อให้เกิด #C0x3D8A99#ความเสียหายเวทมนตร์ 200%#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# และใช้พลังของป่าเพื่อเชื่อมโยงพลังชีวิตในกลุ่มพันธมิตรทั้งหมดสร้าง [สายสัมพันธ์ชีวิต]\n#F20# \n#F40##L10#สายสัมพันธ์ชีวิต: #L0#ลดความเสียหายสุดท้ายที่ได้รับลง 35% (ลดลง 10% ทุกครั้งที่เพิ่ม สูงสุด 15%; หน่วยล่องหนได้รับเพิ่ม 15%) เมื่อหน่วยที่เชื่อมโยงถูกทำลาย 60% ของความเสียหายจะแบ่งกันอย่างเท่าเทียมกับหน่วยอื่นๆ ที่เชื่อมโยง เมื่อเพิ่มสายสัมพันธ์ชีวิต หน่วยที่เชื่อมโยงแต่ละหน่วยจะฟื้นฟู HP 15% จากอายุฐานของเทพกวางเก้าสี สายสัมพันธ์จะหายไปหลังจากการกระทำ 1 เทิร์นของเทพกวางเก้าสี (วิญญาณกวางหายไปหลังการกระทำ 1 เทิร์นของร่างวิญญาณ)',
		describe_in = 'Dewa Rusa Sembilan Warna menggunakan kekuatan hutan untuk menyerang semua target musuh, menyebabkan #C0x3D8A99#200% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#kerusakan sihir#C0x5B545B# dan menggunakan kekuatan hutan untuk menghubungkan energi kehidupan di semua sekutu membentuk [Tautan Kehidupan]\n#F20# \n#F40##L10#Tautan Kehidupan: #L0#Mengurangi kerusakan akhir yang diterima sebesar 35% (berkurang 10% untuk setiap tambahan, maksimal 15%; unit tak terlihat mendapat tambahan 15%). Ketika unit yang terhubung terluka, 60% dari kerusakan tersebut dibagi rata kepada unit lain yang terhubung. Ketika Tautan Kehidupan ditambahkan, setiap unit terhubung akan memulihkan 15% HP dari batas umur dasar Dewa Rusa Sembilan Warna. Tautan akan hilang setelah 1 giliran aksi Dewa Rusa Sembilan Warna (roh rusa hilang setelah 1 giliran aksi dari roh jasmani).',
		describe_ph = 'Gumagamit ang Siyam na Kulay na Diyos ng Usa ng kapangyarihan ng kagubatan upang atakihin ang lahat ng mga target ng kaaway, nagdudulot ng #C0x3D8A99#200% Panlaban sa Magic#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# panlaban sa magic#C0x5B545B# at ginagamit ang kapangyarihan ng kagubatan upang iugnay ang enerhiya ng buhay sa lahat ng mga kaalyado upang bumuo ng [Ugnayan ng Buhay]\n#F20# \n#F40##L10#Ugnayan ng Buhay: #L0#Binabawasan ang huling damage na natatanggap ng 35% (bawas ng 10% bawat karagdagan, hanggang sa 15%; nakatagong yunit tumatanggap ng dagdag na 15%). Kapag nasaktan ang isang naka-ugnay na yunit, 60% ng pinsala ay pantay na ibinabahagi sa iba pang mga naka-ugnay na yunit. Kapag naidagdag ang Ugnayan ng Buhay, bawat naka-ugnay na yunit ay nagpapagaling ng 15% HP mula sa pangunahing lifespan ng Siyam na Kulay na Diyos ng Usa. Mawawala ang ugnayan pagkatapos ng 1 pagkilos ng Siyam na Kulay na Diyos ng Usa (ang espiritu ng usa ay mawawala pagkatapos ng 1 pagkilos ng espiritu ng katawan).',
		describe_ma = 'Dewa Rusa Sembilan Warna menggunakan kuasa hutan untuk menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#200% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# kerosakan sihir#C0x5B545B# dan menggunakan kuasa hutan untuk menghubungkan tenaga kehidupan dalam semua rakan sepasukan membentuk [Pautan Kehidupan]\n#F20# \n#F40##L10#Pautan Kehidupan: #L0#Mengurangkan kerosakan akhir yang diterima sebanyak 35% (berkurang 10% setiap penambahan, maksimum 15%; unit tidak kelihatan mendapat tambahan 15%). Apabila unit yang dihubungkan rosak, 60% daripada kerosakan diagihkan sama rata kepada unit lain yang dihubungkan. Apabila Pautan Kehidupan ditambah, setiap unit yang dihubungkan akan memulihkan 15% HP daripada had umur asas Dewa Rusa Sembilan Warna. Pautan akan hilang selepas 1 giliran tindakan Dewa Rusa Sembilan Warna (roh rusa hilang selepas 1 giliran tindakan roh jasmani).',
		describe = 'The Nine-Colored Deer God uses the power of the forest to attack all enemy targets, dealing #C0x3D8A99#200% Magical Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B# and harnesses the forest\'s power to link the life energy among all allies, forming [Life Link]\n#F20# \n#F40##L10#Life Link: #L0#Reduces final damage taken by 35% (decreases by 10% with each addition, up to 15%; invisible units gain an extra 15%). When a linked unit takes damage, 60% of that damage is evenly distributed among the other linked units. When Life Link is applied, each linked unit recovers 15% HP based on the Nine-Colored Deer God\'s base lifespan. The link disappears after the Nine-Colored Deer God\'s next action (the deer\'s spirit vanishes after one action of the spirit body).',
		simDesc_vn = 'Cửu Sắc Lộc cũng sử dụng sức mạnh của rừng để tấn công toàn bộ mục tiêu của kẻ thù, gây sát thương phép và thêm [liên kết sinh mệnh] cho toàn bộ đồng đội.',
		simDesc_en = 'The Nine-Colored Deer also uses the power of the forest to attack all enemy targets, dealing magic damage and granting <life link> to all allies.',
		simDesc_th = 'กวางเก้าสีใช้พลังของป่าในการโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวทและเพิ่ม [การเชื่อมโยงชีวิต] ให้กับเพื่อนร่วมทีมทั้งหมด',
		simDesc_in = 'Rusa Sembilan Warna juga menggunakan kekuatan hutan untuk menyerang semua target musuh, memberikan kerusakan sihir dan menambahkan <tautan nyawa> untuk semua anggota tim.',
		simDesc_ph = 'Ginagamit din ng Siyam na Kulay ng Usa ang kapangyarihan ng kagubatan upang atakihin ang lahat ng mga target ng kalaban, nagdudulot ng magic damage at nagbibigay ng <link ng buhay> sa lahat ng kasamahan.',
		simDesc_ma = 'Rusa Sembilan Warna juga menggunakan kekuatan hutan untuk menyerang semua sasaran musuh, memberikan kerosakan sihir dan menambah <pautan nyawa> untuk semua ahli pasukan.',
		simDesc = 'The Nine-Colored Deer also uses the power of the forest to attack all enemy targets, dealing magic damage and granting [life link] to all allies.',
		starEffect = __data_t__starEffect[36033],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Liên kết kéo dài 2 lượt lớn, và các đơn vị trong liên kết sẽ không bị ảnh hưởng bởi hiệu ứng giảm hồi phục; sau 3 hành động đầu tiên của kẻ thù, hồi phục 5% máu cơ bản của tất cả các đơn vị liên kết từ Thần Tình Yêu Cửu Sắc.',
		starEffectDesc = 'Additional effect: Link duration extended by 2 turns, and units in the link are not affected by reduced recovery effects; after the enemy\'s first 3 actions, recover 5% of the base HP of all linked units from the #F 01#Nine-Colored Love God#L 01#.',
		starEffectDesc_en = 'Additional effect: Link duration extended by 2 turns, and units in the link are not affected by reduced recovery effects; after the enemy\'s first 3 actions, recover 5% of the base HP of all linked units from the #F 01#Nine-Colored Love God#L 01#.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ลิงก์ยืดระยะเวลาเพิ่มอีก 2 เทิร์น และยูนิตในลิงก์จะไม่ถูกผลกระทบจากเอฟเฟกต์ลดการฟื้นฟู; หลังจากการกระทำ 3 ครั้งแรกของศัตรู ฟื้นฟู 5% ของพลังชีวิตพื้นฐานของยูนิตทั้งหมดที่ลิงก์จาก #F 01#เทพเจ้าแห่งความรักเก้าสี#L 01#',
		starEffectDesc_in = 'Efek tambahan: Durasi tautan diperpanjang 2 giliran, dan unit dalam tautan tidak terpengaruh oleh efek pengurangan pemulihan; setelah 3 aksi pertama musuh, pulihkan 5% HP dasar dari semua unit yang terhubung dari #F 01#Dewa Cinta Sembilan Warna#L 01#.',
		starEffectDesc_ph = 'Karagdagang epekto: Pinalawig ang tagal ng link ng 2 turn, at ang mga yunit sa link ay hindi maaapektuhan ng mga epekto ng pagbawas ng pag-recover; pagkatapos ng unang 3 aksyon ng kalaban, mag-recover ng 5% base HP ng lahat ng naka-link na yunit mula sa #F 01#Siyam na Kulay na Diyos ng Pag-ibig#L 01#.',
		starEffectDesc_ma = 'Kesan tambahan: Pautan dilanjutkan selama 2 pusingan, dan unit dalam pautan tidak terjejas oleh kesan pengurangan pemulihan; selepas 3 tindakan pertama musuh, pulihkan 5% HP asas semua unit yang dipautkan dari #F 01#Dewa Cinta Sembilan Warna#L 01#.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
