		posChoose = 1,
		targetTypeDesc = 'Single enemy',
		targetTypeDesc_vn = 'Đơn thể địch',
		targetTypeDesc_en = 'Single enemy',
		targetTypeDesc_th = 'ศัตรูเดี่ยว',
		targetTypeDesc_in = 'Musuh tunggal',
		targetTypeDesc_ph = 'Kalabang iisa',
		targetTypeDesc_ma = 'Musuh tunggal',
		targetChooseType = 'single',
		damageFormula = 'self:hasBuff(3601158) and (self:specialDamage()*3+(self:flag(99) and skillLevel or skillLevel*4)*24) or (self:specialDamage()*1+(self:flag(99) and skillLevel or skillLevel*4)*24)',
		skillProcess = {360411, 360412},
