	[36042] = {
		id = 36042,
		skillName_vn = 'Chế độ thư giãn',
		skillName_en = 'Relaxation mode',
		skillName_th = 'โหมดผ่อนคลาย',
		skillName_in = 'Mode relaksasi',
		skillName_ph = 'Relaxation mode',
		skillName_ma = 'Mod santai',
		skillName = 'Relaxation mode',
		describe_vn = 'Xerneas mượn sức mạnh của mặt trăng tấn công hàng trước của kẻ địch, gây ra #C0x3D8A99#160% Phép Công#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, đồng thời khiến bản thân và một đơn vị ngẫu nhiên ở hàng sau nhận được [Chế độ thư giãn] trong 1 lượt (ưu tiên đơn vị nhập thân), trong [Chế độ thư giãn], bản thân khi sử dụng kỹ năng nhỏ lần này và tấn công chủ động lần sau cùng đồng đội tấn công cùng mục tiêu sẽ có 100% xác suất làm [choáng] mục tiêu trong 1 lượt (tối đa làm choáng 3 người cùng lúc)\n#F20# \n#F40#[Chế độ thư giãn]: Hiệu ứng đặc biệt, không thể bị xóa, chuyển hoặc sao chép, ẩn thân và tăng 100% phòng thủ đôi',
		describe_en = 'Xerneas borrows the power of the moon to attack the enemy\'s front row, dealing #C0x3D8A99#160% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage #C0x5B545B#, while causing itself and a random unit in the back row to gain [Relaxation Mode] for 1 turn (prioritizing the transformed unit). In [Relaxation Mode], when the user uses a minor skill this turn and performs an active attack next time with teammates attacking the same target, there is a 100% chance to [stun] the target for 1 turn (up to 3 targets can be stunned simultaneously)\n#F20# \n#F40# [Relaxation Mode]: A special effect that cannot be removed, transferred, or copied, provides invisibility and doubles defense by 100%.',
		describe_th = 'Xerneas ยืมพลังของพระจันทร์โจมตีแถวหน้าของศัตรู ก่อให้เกิดความเสียหายเวทมนตร์ #C0x3D8A99#160%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# และทำให้ตนเองและหนึ่งหน่วยในแถวหลังแบบสุ่มได้รับ [โหมดผ่อนคลาย] เป็นเวลา 1 เทิร์น (ให้ความสำคัญกับหน่วยที่เปลี่ยนร่าง) ใน [โหมดผ่อนคลาย] เมื่อใช้สกิลเล็กในเทิร์นนี้และโจมตีโดยตรงในครั้งถัดไปกับเพื่อนร่วมทีมที่โจมตีเป้าหมายเดียวกัน จะมีโอกาส 100% ที่จะทำให้เป้าหมาย [มึนงง] เป็นเวลา 1 เทิร์น (สามารถทำให้มึนงงได้สูงสุด 3 เป้าหมายพร้อมกัน)\n#F20# \n#F40# [โหมดผ่อนคลาย]: เอฟเฟกต์พิเศษ ไม่สามารถลบ โอน หรือคัดลอก ซ่อนตัว และเพิ่มความอึดขึ้น 100%',
		describe_in = 'Xerneas meminjam kekuatan bulan untuk menyerang barisan depan musuh, menyebabkan #C0x3D8A99#160% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerusakan Sihir #C0x5B545B#, sekaligus membuat dirinya sendiri dan satu unit acak di barisan belakang mendapatkan [Mode Relaksasi] selama 1 giliran (prioritaskan unit yang transformasi). Dalam [Mode Relaksasi], saat menggunakan skill kecil kali ini dan melakukan serangan aktif berikutnya bersama rekan satu tim yang menyerang target yang sama, ada kesempatan 100% untuk [pingsan] target selama 1 giliran (maksimal 3 orang bisa dibuat pingsan bersamaan)\n#F20# \n#F40# [Mode Relaksasi]: Efek khusus, tidak bisa dihapus, dipindahkan atau disalin, menyamar, dan meningkatkan pertahanan 100% ganda.',
		describe_ph = 'Hiniram ni Xerneas ang kapangyarihan ng buwan upang atakihin ang harapang linya ng kalaban, nagdudulot ng #C0x3D8A99#160% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Sakit na Magic #C0x5B545B#, kasabay nito ay nagiging [Relaxation Mode] para sa sarili at isang random na yunit sa likurang linya sa loob ng 1 turn (pinaprioritize ang unit na nagtago). Sa [Relaxation Mode], kapag ginamit ang maliit na kasanayan ngayong turn at nagkaroon ng aktibong atake sa susunod na pagkakataon kasama ang mga kakampi na umatake sa parehong target, may 100% na tsansang [ma-stun] ang target sa loob ng 1 turn (maximum na 3 tao ang pwedeng ma-stun ng sabay)\n#F20# \n#F40# [Relaxation Mode]: Isang espesyal na epekto, hindi maaaring alisin, ilipat o kopyahin, nagiging invisible at tumataas ang defense ng 100% doble.',
		describe_ma = 'Xerneas meminjam kekuatan bulan untuk menyerang barisan hadapan musuh, menyebabkan #C0x3D8A99#160% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerosakan Sihir #C0x5B545B#, serta menyebabkan dirinya sendiri dan satu unit rawak di barisan belakang menerima [Mod Bersantai] selama 1 giliran (utamakan unit yang berubah bentuk). Dalam [Mod Bersantai], apabila menggunakan kemahiran kecil kali ini dan serangan aktif seterusnya bersama rakan sepasukan menyerang sasaran yang sama, terdapat kebarangkalian 100% untuk [pengejutan] sasaran selama 1 giliran (maksimum 3 orang boleh dikejutkan serentak)\n#F20# \n#F40# [Mod Bersantai]: Kesan khas, tidak boleh dipadam, dipindahkan atau disalin, menyamar dan meningkatkan pertahanan sebanyak 100% berganda.',
		describe = 'Xerneas borrows the power of the moon to attack the enemy\'s front row, dealing #C0x3D8A99#160% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage #C0x5B545B#, while causing itself and a random unit in the back row to gain [Relaxation Mode] for 1 turn (prioritizing the transformed unit). In [Relaxation Mode], when the user uses a minor skill this turn and performs an active attack next time with teammates attacking the same target, there is a 100% chance to [stun] the target for 1 turn (up to 3 targets can be stunned simultaneously)\n#F20# \n#F40# [Relaxation Mode]: A special effect that cannot be removed, transferred, or copied, provides invisibility and doubles defense by 100%.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
