	[36043] = {
		id = 36043,
		skillName_vn = 'Kiểm soát đất đai',
		skillName_en = 'Land control',
		skillName_th = 'การควบคุมที่ดิน',
		skillName_in = 'Kontrol lahan',
		skillName_ph = 'Kontrol sa lupa',
		skillName_ma = 'Kawalan tanah',
		skillName = 'Land control',
		describe_vn = 'Xerneas sử dụng sức mạnh của khu rừng để tấn công tất cả mục tiêu của kẻ thù, gây ra #C0x3D8A99#200% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B# và sử dụng sức mạnh của khu rừng để liên kết năng lượng sống trong tất cả đồng đội, tạo thành [Life Link]\n#F20# \n#F40##L10#Life Link: #L0#Giảm sát thương cuối cùng tăng thêm 35% (giảm 10% mỗi lần được thêm lại, tối đa 15%; đơn vị tàng hình được tăng thêm 15%). Khi đơn vị liên kết bị hư hỏng, 60% thiệt hại sẽ được chia đều cho các đơn vị liên kết khác. Khi liên kết sự sống được thêm vào, mỗi đơn vị được liên kết sẽ phục hồi 15% HP từ giới hạn tuổi thọ cơ bản của Xerneas. Liên kết biến mất sau 1 lượt hành động của Xerneas (ở trạng thái linh hồn hươu, nó biến mất sau 1 lượt hành động của linh hồn)',
		describe_en = 'Xerneas uses the power of the forest to attack all enemy targets, dealing #C0x3D8A99#200% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Magic Damage#C0x5B545B# and harnesses the forest\'s power to link life energy among all allies, forming [Life Link]\n#F20# \n#F40##L10#Life Link: #L0#Reduces final damage taken by 35% (decreases by 10% each time it is reapplied, up to 15%; stealth units gain an additional 15%). When a linked unit takes damage, 60% of the damage is evenly distributed among other linked units. When Life Link is applied, each linked unit recovers 15% HP based on Xerneas\'s base lifespan. The link dissipates after 1 action turn of Xerneas (in deer spirit state, it dissipates after 1 spirit turn).',
		describe_th = 'เซอร์เนียสใช้พลังของป่าในการโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหายเวทมนตร์ #C0x3D8A99#200%#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# และใช้พลังของป่าเชื่อมพลังชีวิตในกลุ่มพันธมิตรทั้งหมด สร้าง [Life Link]\n#F20# \n#F40##L10#Life Link: #L0#ลดความเสียหายท้ายสุดลง 35% (ลดลง 10% ทุกครั้งที่ถูกเพิ่มซ้ำ สูงสุด 15%; หน่วยล่องหนได้รับโบนัสเพิ่มเติม 15%) เมื่อหน่วยที่เชื่อมโยงได้รับความเสียหาย 60% ของความเสียหายจะถูกแบ่งเท่า ๆ กันระหว่างหน่วยเชื่อมโยงอื่น ๆ เมื่อเพิ่ม Life Link หน่วยที่เชื่อมโยงแต่ละหน่วยจะฟื้นฟู HP 15% จากอายุพื้นฐานของเซอร์เนียส ลิงก์จะหายไปหลังจากหนึ่งเทิร์นของเซอร์เนียส (ในสถานะจิตวิญญาณกวาง ลิงก์จะหายไปหลังจากหนึ่งเทิร์นของจิตวิญญาณ)',
		describe_in = 'Xerneas menggunakan kekuatan hutan untuk menyerang semua target musuh, memberikan #C0x3D8A99#200% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Kerusakan Sihir#C0x5B545B# dan menggunakan kekuatan hutan untuk menghubungkan energi kehidupan di antara semua sekutu, membentuk [Life Link]\n#F20# \n#F40##L10#Life Link: #L0#Mengurangi kerusakan akhir sebesar 35% (berkurang 10% setiap kali diterapkan ulang, maksimal 15%; unit siluman mendapat tambahan 15%). Saat unit yang terhubung menerima kerusakan, 60% dari kerusakan dibagi rata ke unit terhubung lainnya. Saat Life Link diterapkan, setiap unit yang terhubung memulihkan 15% HP dari batas usia dasar Xerneas. Ikatan hilang setelah 1 giliran aksi Xerneas (dalam status roh rusa, hilang setelah 1 giliran roh).',
		describe_ph = 'Gamit ng Xerneas ang kapangyarihan ng kagubatan upang atakihin ang lahat ng target ng kalaban, nagdudulot ng #C0x3D8A99#200% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Magic Damage#C0x5B545B# at ginagamit ang kapangyarihan ng kagubatan upang pag-ugnayin ang enerhiya ng buhay sa lahat ng mga kakampi, bumubuo ng [Life Link]\n#F20# \n#F40##L10#Life Link: #L0#Pinapababa ng huli ang natanggap na pinsala ng 35% (nababawasan ng 10% sa bawat muling pagdaragdag, hanggang 15%; ang mga stealth unit ay nakakakuha ng dagdag na 15%). Kapag ang isang naka-link na yunit ay nasira, 60% ng pinsala ay pantay-pantay na hinahati sa iba pang naka-link na yunit. Kapag naidagdag ang Life Link, bawat naka-link na yunit ay nakakabawi ng 15% HP mula sa pangunahing hangganan ng buhay ni Xerneas. Ang link ay nawawala pagkatapos ng 1 turn ng pagkilos ni Xerneas (sa anyo ng espiritu ng usa, nawawala ito pagkatapos ng 1 turn ng espiritu).',
		describe_ma = 'Xerneas menggunakan kuasa hutan untuk menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#200% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Kerosakan Sihir#C0x5B545B# dan menggunakan kuasa hutan untuk menghubungkan tenaga hidup dalam semua sekutu, membentuk [Life Link]\n#F20# \n#F40##L10#Life Link: #L0#Mengurangkan kerosakan akhir sebanyak 35% (berkurang 10% setiap kali ditambah semula, maksimum 15%; unit yang menyamar mendapat tambahan 15%). Apabila unit yang berhubung mendapat kerosakan, 60% kerosakan akan dibahagikan sama rata kepada unit berhubung yang lain. Apabila Life Link ditambah, setiap unit yang berhubung memulihkan 15% HP dari had umur asas Xerneas. Ikatan hilang selepas 1 giliran tindakan Xerneas (dalam keadaan roh rusa, ia hilang selepas 1 giliran roh).',
		describe = 'Xerneas uses the power of the forest to attack all enemy targets, dealing #C0x3D8A99#200% Magic Damage#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# Magic Damage#C0x5B545B# and harnesses the forest\'s power to link life energy among all allies, forming [Life Link]\n#F20# \n#F40##L10#Life Link: #L0#Reduces final damage taken by 35% (decreases by 10% each time it is reapplied, up to 15%; stealth units gain an additional 15%). When a linked unit takes damage, 60% of the damage is evenly distributed among other linked units. When Life Link is applied, each linked unit recovers 15% HP based on Xerneas\'s base lifespan. The link dissipates after 1 action turn of Xerneas (in deer spirit state, it dissipates after 1 spirit turn).',
		starEffect = __data_t__starEffect[36043],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Liên kết kéo dài 2 lượt lớn, và các đơn vị trong liên kết sẽ không bị ảnh hưởng bởi hiệu ứng giảm hồi phục; sau 3 hành động đầu tiên của kẻ thù, hồi phục 5% máu cơ bản của tất cả các đơn vị liên kết từ Zernias.',
		starEffectDesc = 'Additional effect: Link duration extended by 2 turns, and units in the link are not affected by recovery reduction effects; after the enemy\'s first 3 actions, recover 5% base HP of all linked units from Zernias.',
		starEffectDesc_en = 'Additional effect: Link duration extended by 2 turns, and units in the link are not affected by recovery reduction effects; after the enemy\'s first 3 actions, recover 5% base HP of all linked units from Zernias.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: การเชื่อมโยงยาวนานขึ้น 2 เทิร์น และหน่วยในลิงค์จะไม่ถูกผลกระทบจากเอฟเฟกต์ลดการฟื้นฟู; หลังจากการกระทำ 3 ครั้งแรกของศัตรู ฟื้นฟูพลังชีวิตพื้นฐาน 5% ของหน่วยที่เชื่อมโยงทั้งหมดจาก Zernias',
		starEffectDesc_in = 'Efek tambahan: Durasi tautan diperpanjang 2 giliran, dan unit dalam tautan tidak terpengaruh oleh efek pengurangan pemulihan; setelah 3 aksi pertama musuh, pulihkan 5% HP dasar semua unit yang terhubung dari Zernias.',
		starEffectDesc_ph = 'Karagdagang epekto: Pinalawig ang tagal ng link ng 2 turn, at ang mga yunit sa link ay hindi maaapektuhan ng mga epekto ng pagbawas ng paggaling; pagkatapos ng unang 3 aksyon ng kaaway, mababalik ang 5% base HP ng lahat ng mga yunit na naka-link mula sa Zernias.',
		starEffectDesc_ma = 'Kesan tambahan: Tempoh pautan dipanjangkan selama 2 pusingan, dan unit dalam pautan tidak terjejas oleh kesan pengurangan pemulihan; selepas 3 tindakan pertama musuh, pulihkan 5% HP asas semua unit yang dipautkan dari Zernias.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 2,
		skillDamageType = 1,
		skillNatureType = 18,
		targetTypeDesc = 'All enemies',
		targetTypeDesc_vn = 'Toàn bộ địch',
		targetTypeDesc_en = 'All enemies',
		targetTypeDesc_th = 'ศัตรูทั้งหมด',
		targetTypeDesc_in = 'Semua musuh',
