	[36111] = {
		id = 36111,
		skillName_vn = 'Quả cầu pháp tối',
		skillName_en = 'Dark magic orb',
		skillName_th = 'ลูกแก้วเวทมนตร์มืด',
		skillName_in = 'bola sihir gelap',
		skillName_ph = 'dark magic orb',
		skillName_ma = 'bola sihir gelap',
		skillName = 'Dark magic orb',
		describe_vn = 'Yveltal phóng quả cầu bóng tối tấn công mục tiêu có máu thấp nhất ở hàng sau của kẻ địch, gây #C0x3D8A99#100% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, vĩnh viễn cướp 10% công đôi và 10% tốc độ của mục tiêu (tối đa cộng dồn 3 lần, trả lại khi Yveltal chết)',
		describe_en = 'Yveltal launches a dark sphere to attack the enemy with the lowest HP in the back row, dealing #C0x3D8A99#100% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magical Damage#C0x5B545B#, permanently stealing 10% Attack and 10% Speed from the target (stacks up to 3 times, returned when Yveltal dies).',
		describe_th = 'Yveltal ยิงลูกบอลแห่งความมืดโจมตีเป้าหมายที่มีพลังชีวิตต่ำสุดในแถวหลังของศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#100%#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# ขโมยพลังโจมตี 10% และความเร็ว 10% จากเป้าหมายอย่างถาวร (สะสมได้สูงสุด 3 ครั้ง คืนเมื่อ Yveltal ตาย)',
		describe_in = 'Yveltal meluncurkan bola kegelapan untuk menyerang target dengan HP terendah di baris belakang musuh, memberikan #C0x3D8A99#100% Kerusakan Magical#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerusakan Magical#C0x5B545B#, mencuri secara permanen 10% Serangan dan 10% Kecepatan dari target (maksimal bertumpuk 3 kali, dikembalikan saat Yveltal mati).',
		describe_ph = 'Pinaputok ni Yveltal ang bola ng dilim para atakihin ang kalabang may pinakamababang HP sa likurang hanay, nagdudulot ng #C0x3D8A99#100% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magical Damage#C0x5B545B#, permanenteng nagnanakaw ng 10% Atake at 10% Bilis mula sa target (maximum na tatlong beses ang pagtitipon, ibinabalik kapag namatay si Yveltal).',
		describe_ma = 'Yveltal melepaskan bola gelap untuk menyerang sasaran dengan HP terendah di barisan belakang musuh, menyebabkan #C0x3D8A99#100% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerosakan Magik#C0x5B545B#, mencuri secara kekal 10% Serangan dan 10% Kelajuan dari sasaran (maksimum bertindih 3 kali, dikembalikan apabila Yveltal mati).',
		describe = 'Yveltal launches a dark sphere to attack the enemy with the lowest HP in the back row, dealing #C0x3D8A99#100% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magical Damage#C0x5B545B#, permanently stealing 10% Attack and 10% Speed from the target (stacks up to 3 times, returned when Yveltal dies).',
		upLvDesc = 'Fixed damage +96',
		upLvDesc_en = 'Fixed damage +96',
		upLvDesc_th = 'ความเสียหายคงที่ +96',
