	[36112] = {
		id = 36112,
		skillName_vn = 'Lời nguyền bóng tối',
		skillName_en = 'Curse of Darkness',
		skillName_th = 'คำสาปแห่งความมืด',
		skillName_in = 'Kutukan Kegelapan',
		skillName_ph = 'Malediksyon ng Kadiliman',
		skillName_ma = 'Sumpahan Kegelapan',
		skillName = 'Curse of Darkness',
		describe_vn = 'Yveltal dùng đuôi tấn công mục tiêu có máu thấp nhất ở hàng sau của kẻ địch, gây #C0x3D8A99#180% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, và thêm hiệu ứng [Lời nguyền sinh mệnh] lên mục tiêu trong 2 lượt\n#F20# \n#F40#[Lời nguyền sinh mệnh]: Hiệu ứng tiêu cực đặc biệt, không thể bị xóa, chuyển hoặc sao chép, không thể nhận hiệu quả hồi máu, chuyển lượng hồi máu thành sát thương thực bằng 120% Công Phép thuật của Yveltal, và mỗi khi mục tiêu mất 10% máu, công đôi giảm 5%, sát thương cuối cùng nhận phải tăng 5%',
		describe_en = 'Yveltal uses its tail to attack the enemy\'s backline target with the lowest HP, dealing #C0x3D8A99#180% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magical Damage#C0x5B545B#, and applies the [Curse of Life] effect on the target for 2 turns \n#F20# \n#F40#[Curse of Life]: A special negative effect that cannot be removed, transferred, or copied. The target cannot receive healing effects; healing is converted into true damage equal to 120% of Yveltal\'s Magic Attack. Additionally, each time the target loses 10% HP, Yveltal’s attack power decreases by 5%, and the final damage the target takes increases by 5%.',
		describe_th = 'Yveltal ใช้หางโจมตีเป้าหมายที่มี HP ต่ำที่สุดในแถวหลังของศัตรู สร้าง #C0x3D8A99#180% ความเสียหายเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# และเพิ่มเอฟเฟกต์ [คำสาปแห่งชีวิต] ให้กับเป้าหมายเป็นเวลา 2 เทิร์น \n#F20# \n#F40#[คำสาปแห่งชีวิต]: เอฟเฟกต์ลบพิเศษที่ไม่สามารถลบ โอน หรือคัดลอกได้ เป้าหมายจะไม่สามารถรับผลฟื้นฟูเลือดได้ การฟื้นฟูเลือดจะถูกเปลี่ยนเป็นความเสียหายจริงเท่ากับ 120% ของพลังเวทของ Yveltal และทุกครั้งที่เป้าหมายเสียเลือด 10% พลังโจมตีจะลดลง 5% และความเสียหายสุดท้ายที่ได้รับจะเพิ่มขึ้น 5%',
		describe_in = 'Yveltal menggunakan ekornya untuk menyerang target dengan HP terendah di barisan belakang musuh, menyebabkan #C0x3D8A99#180% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerusakan Magis#C0x5B545B#, dan menambahkan efek [Kutukan Kehidupan] pada target selama 2 giliran \n#F20# \n#F40#[Kutukan Kehidupan]: Efek negatif khusus yang tidak dapat dihapus, dipindahkan, atau disalin. Target tidak dapat menerima efek penyembuhan; penyembuhan diubah menjadi kerusakan nyata sebesar 120% dari Serangan Magis Yveltal. Selain itu, setiap kali target kehilangan 10% HP, kekuatan serangan Yveltal berkurang 5%, dan kerusakan akhir yang diterima target meningkat 5%.',
		describe_ph = 'Gumagamit si Yveltal ng buntot para atakihin ang target na may pinakamababang HP sa hulihang linya ng kalaban, na nagdudulot ng #C0x3D8A99#180% Magic Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magic Damage#C0x5B545B#, at naglalagay ng epekto ng [Sumpa ng Buhay] sa target ng 2 turn \n#F20# \n#F40#[Sumpa ng Buhay]: Isang espesyal na negatibong epekto na hindi matatanggal, maipapasa, o makokopya. Hindi makakatanggap ang target ng healing effects; ang healing ay mababago bilang totoong pinsala na katumbas ng 120% ng Magic Attack ni Yveltal. At tuwing mawawalan ang target ng 10% ng HP, bababa ang attack power ni Yveltal ng 5%, at tataas ng 5% ang natanggap na huling pinsala.',
		describe_ma = 'Yveltal menggunakan ekornya untuk menyerang sasaran dengan darah paling rendah di barisan belakang musuh, menyebabkan #C0x3D8A99#180% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerosakan Magik#C0x5B545B#, dan menambah kesan [Sumpahan Kehidupan] ke sasaran selama 2 pusingan \n#F20# \n#F40#[Sumpahan Kehidupan]: Kesan negatif khas yang tidak boleh dihapus, dialihkan atau disalin. Sasaran tidak boleh menerima kesan penyembuhan; penyembuhan ditukar menjadi kerosakan sebenar sebanyak 120% daripada Serangan Magik Yveltal. Selain itu, setiap kali sasaran kehilangan 10% darah, kuasa serangan berkurang 5%, dan kerosakan akhir yang diterima meningkat 5%.',
		describe = 'Yveltal uses its tail to attack the enemy\'s backline target with the lowest HP, dealing #C0x3D8A99#180% Magical Damage#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magical Damage#C0x5B545B#, and applies the [Curse of Life] effect on the target for 2 turns \n#F20# \n#F40#[Curse of Life]: A special negative effect that cannot be removed, transferred, or copied. The target cannot receive healing effects; healing is converted into true damage equal to 120% of Yveltal\'s Magic Attack. Additionally, each time the target loses 10% HP, Yveltal’s attack power decreases by 5%, and the final damage the target takes increases by 5%.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
