	[36113] = {
		id = 36113,
		skillName_vn = 'Cánh chết chóc',
		skillName_en = 'Deadly Wing',
		skillName_th = 'ปีกมรณะ',
		skillName_in = 'Sayap Mematikan',
		skillName_ph = 'Nakakatinding Pakpak',
		skillName_ma = 'Sayap Maut',
		skillName = 'Deadly Wing',
		describe_vn = 'Yveltal bay lên không trung và cuối cùng tấn công mục tiêu địch có lượng máu thấp nhất ở hàng sau, gây ra #C0x3D8A99#500% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B# và hạ gục mục tiêu Tạo thành [Death Link] bằng hai đơn vị ngẫu nhiên ở hàng trước của kẻ địch trong 3 vòng. [Liên kết tử thần]: Khi bất kỳ đơn vị nào trong liên kết bị sát thương, 25% sát thương sẽ được chuyển sang các đơn vị liên kết khác và khi đơn vị trong [Liên kết tử thần] lại bị Yveltal gây sát thương, có 35% khả năng bị hóa đá trong 1 hiệp\n#F20# \n#F40# Sau đó, anh ta kích hoạt [Chết vô tận] trong 1 hiệp: anh ta bị bao quanh bởi 2 cánh tử thần. Trong khoảng thời gian này, khi máu của bất kỳ đơn vị địch nào thấp hơn 25% giới hạn máu ban đầu của trận chiến, Yveltal sẽ tiêu tốn 1 cánh tử thần để giải phóng [Đôi cánh tử thần] trên đó một lần: gây cho bản thân #C0x3D8A99#360% Sát Thương Phép Thuật#C0x5B545 B# + 50% lượng máu đã mất của mục tiêu #C0xF13B54# sát thương phép #C0x5B545B#; khi kết thúc tiêu diệt, cánh tử thần chưa tiêu hao có thể đổi lấy 15% máu tối đa của một mục tiêu ngẫu nhiên trên sân (mục tiêu có nhiều máu nhất trên sân sẽ được ưu tiên)',
		describe_en = 'Yveltal flies into the air and finally attacks the enemy target with the lowest HP in the back row, dealing #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magic Damage#C0x5B545B# and defeating the target. Creates [Death Link] between two random units in the enemy\'s front row for 3 turns. [Death Link]: When any linked unit takes damage, 25% of the damage is transferred to the other linked units, and when a unit in [Death Link] is damaged by Yveltal, there is a 35% chance to be petrified for 1 turn. Then, he activates [Endless Death] for 1 turn: he is surrounded by 2 Death Wings. During this time, when the HP of any enemy unit falls below 25% of the battle\'s original HP limit, Yveltal consumes 1 Death Wing to release [Wings of Death] once: deals #C0x3D8A99#360% Magic Damage#C0x5B545B# + 50% of the target\'s lost HP as #C0xF13B54# magic damage#C0x5B545B# to himself; upon finishing the kill, unused Death Wings can be exchanged to recover 15% max HP of a random target on the field (priority to the highest HP target).',
		describe_th = 'Yveltal บินขึ้นสู่ท้องฟ้าและสุดท้ายโจมตีเป้าหมายศัตรูที่มีพลังชีวิตต่ำที่สุดในแถวหลัง สร้างความเสียหายเวทมนตร์ #C0x3D8A99#500%#C0x5B545B# + $(skillLevel*4*90)$#C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# และกำจัดเป้าหมายนั้น สร้าง [สายสัมพันธ์มรณะ] ระหว่างหน่วยศัตรูสองหน่วยแบบสุ่มในแถวหน้าเป็นเวลา 3 รอบ [สายสัมพันธ์มรณะ]: เมื่อหน่วยไหนก็ตามในลิงก์ได้รับความเสียหาย 25% ของความเสียหายจะถูกส่งต่อไปยังหน่วยลิงก์อื่น และเมื่อหน่วยใน [สายสัมพันธ์มรณะ] ถูก Yveltal ทำความเสียหาย จะมีโอกาส 35% ที่จะถูกแปลงเป็นหินเป็นเวลา 1 เทิร์น จากนั้นเขาจะเปิดใช้งาน [ความตายไม่มีที่สิ้นสุด] เป็นเวลา 1 เทิร์น: เขาถูกล้อมรอบด้วยปีกมรณะ 2 อัน ในช่วงเวลานี้ เมื่อพลังชีวิตของหน่วยศัตรูใดๆ ต่ำกว่า 25% ของขีดจำกัดพลังชีวิตเดิมของการต่อสู้ Yveltal จะใช้ปีกมรณะ 1 อันเพื่อปล่อย [ปีกมรณะ] หนึ่งครั้ง: สร้างความเสียหายเวทมนตร์ให้ตัวเอง #C0x3D8A99#360%#C0x5B545B# + 50% ของพลังชีวิตที่สูญเสียของเป้าหมายเป็น #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B#; เมื่อจบการฆ่า ปีกมรณะที่ไม่ได้ใช้สามารถแลกเปลี่ยนเป็นการฟื้นฟูพลังชีวิต 15% ของเป้าหมายสุ่มในสนาม (จะให้ความสำคัญกับเป้าหมายที่มีพลังชีวิตมากที่สุด)',
		describe_in = 'Yveltal terbang ke udara dan akhirnya menyerang target musuh dengan HP terendah di barisan belakang, memberikan #C0x3D8A99#500% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Kerusakan Sihir#C0x5B545B# dan mengalahkan target tersebut. Membentuk [Death Link] antara dua unit acak di barisan depan musuh selama 3 giliran. [Death Link]: Ketika unit mana pun yang terhubung menerima kerusakan, 25% kerusakan dialihkan ke unit yang terhubung lainnya, dan ketika unit dalam [Death Link] menerima kerusakan dari Yveltal, ada peluang 35% untuk menjadi batu selama 1 giliran. Kemudian, dia mengaktifkan [Endless Death] selama 1 giliran: dia dikelilingi oleh 2 Death Wings. Selama waktu ini, ketika HP unit musuh mana pun turun di bawah 25% dari batas HP asli pertempuran, Yveltal mengonsumsi 1 Death Wing untuk melepaskan [Wings of Death] sekali: memberikan kepada dirinya sendiri #C0x3D8A99#360% Kerusakan Sihir#C0x5B545B# + 50% HP yang hilang dari target sebagai #C0xF13B54# kerusakan sihir #C0x5B545B#; saat menyelesaikan eliminasi, Death Wings yang tidak terpakai dapat ditukar untuk mendapatkan 15% HP maksimum dari target acak di medan (prioritas untuk target dengan HP tertinggi).',
		describe_ph = 'Si Yveltal ay lumipad sa himpapawid at sa huli ay inatake ang kaaway na may pinakamababang HP sa likurang hanay, na nagdudulot ng #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magic Damage#C0x5B545B# at pinapatay ang target. Lumilikha ng [Death Link] sa pagitan ng dalawang random na yunit sa harapang hanay ng kaaway sa loob ng 3 round. [Death Link]: Kapag ang alinmang yunit na nakakabit ay tumatanggap ng pinsala, 25% ng pinsala ay ipinapasa sa iba pang nakakabit na yunit, at kapag ang yunit sa [Death Link] ay tinamaan ng pinsala ni Yveltal, may 35% tsansa na ma-petrify sa loob ng 1 round. Pagkatapos, pinapagana niya ang [Endless Death] sa loob ng 1 round: siya ay napapaligiran ng 2 Death Wings. Sa panahong ito, kapag ang HP ng alinmang yunit ng kaaway ay bumaba sa ilalim ng 25% ng orihinal na limitasyon ng HP ng laban, kukonsumo si Yveltal ng 1 Death Wing para pakawalan ang [Wings of Death] isang beses: nagdudulot sa kanyang sarili ng #C0x3D8A99#360% Magic Damage#C0x5B545B# + 50% ng nawalang HP ng target bilang #C0xF13B54# magic damage#C0x5B545B#; kapag natapos ang pagpatay, ang mga hindi nagamit na Death Wings ay maaaring ipalit para sa 15% max HP ng isang random na target sa larangan (pinaprioritize ang target na may pinakamataas na HP).',
		describe_ma = 'Yveltal terbang ke udara dan akhirnya menyerang sasaran musuh dengan HP terendah di barisan belakang, menyebabkan #C0x3D8A99#500% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Kerosakan Sihir#C0x5B545B# dan menewaskan sasaran tersebut. Membentuk [Death Link] antara dua unit rawak di barisan depan musuh selama 3 pusingan. [Death Link]: Apabila mana-mana unit yang berhubung menerima kerosakan, 25% kerosakan akan dipindahkan ke unit berhubung lain, dan apabila unit dalam [Death Link] menerima kerosakan dari Yveltal, terdapat peluang 35% untuk menjadi batu selama 1 pusingan. Kemudian, dia mengaktifkan [Endless Death] selama 1 pusingan: dia dikelilingi oleh 2 Death Wings. Dalam tempoh ini, apabila HP mana-mana unit musuh jatuh di bawah 25% had HP asal pertempuran, Yveltal membelanjakan 1 Death Wing untuk melepaskan [Wings of Death] sekali: menyebabkan kepada dirinya sendiri #C0x3D8A99#360% Kerosakan Sihir#C0x5B545B# + 50% HP yang hilang oleh sasaran sebagai #C0xF13B54# kerosakan sihir #C0x5B545B#; semasa tamat membunuh, Death Wings yang tidak digunakan boleh ditukar untuk mendapatkan 15% HP maksimum dari sasaran rawak di medan (sasaran dengan HP tertinggi akan diberi keutamaan).',
		describe = 'Yveltal flies into the air and finally attacks the enemy target with the lowest HP in the back row, dealing #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magic Damage#C0x5B545B# and defeating the target. Creates [Death Link] between two random units in the enemy\'s front row for 3 turns. [Death Link]: When any linked unit takes damage, 25% of the damage is transferred to the other linked units, and when a unit in [Death Link] is damaged by Yveltal, there is a 35% chance to be petrified for 1 turn. Then, he activates [Endless Death] for 1 turn: he is surrounded by 2 Death Wings. During this time, when the HP of any enemy unit falls below 25% of the battle\'s original HP limit, Yveltal consumes 1 Death Wing to release [Wings of Death] once: deals #C0x3D8A99#360% Magic Damage#C0x5B545B# + 50% of the target\'s lost HP as #C0xF13B54# magic damage#C0x5B545B# to himself; upon finishing the kill, unused Death Wings can be exchanged to recover 15% max HP of a random target on the field (priority to the highest HP target).',
		simDesc_vn = 'Yveltal bay đến tấn công mục tiêu có lượng máu thấp nhất ở hàng sau của kẻ thù, gây sát thương phép, tạo thành [liên kết tử vong] giữa mục tiêu và đơn vị ở hàng trước của kẻ thù, sau đó tự mở khóa [giết chóc vô hạn] trong 1 lượt.',
		simDesc_en = 'Yveltal flies in to attack the enemy\'s backline target with the lowest HP, dealing magic damage and forming a <death link> between the target and the frontline enemy unit, then unlocks <infinite slaughter> for 1 turn.',
		simDesc_th = 'Yveltal บินเข้าทำการโจมตีเป้าหมายที่มี HP ต่ำที่สุดในแถวหลังของศัตรู สร้างความเสียหายเวทมนตร์ และสร้าง [สายสัมพันธ์มรณะ] ระหว่างเป้าหมายกับหน่วยในแถวหน้า จากนั้นเปิดใช้งาน [การสังหารไม่สิ้นสุด] เป็นเวลา 1 เทิร์น',
		simDesc_in = 'Yveltal terbang menyerang target dengan HP terendah di barisan belakang musuh, memberikan damage magic, membentuk <tautan kematian> antara target dan unit di barisan depan musuh, lalu membuka <pembantaian tak berujung> selama 1 giliran.',
		simDesc_ph = 'Lumilipad si Yveltal upang atakihin ang target na may pinakamababang HP sa likurang hanay ng kalaban, nagdudulot ng magic damage, bumubuo ng <death link> sa pagitan ng target at ng unit sa front line ng kalaban, at pagkatapos ay nag-aunlock ng <infinite slaughter> sa loob ng 1 turn.',
		simDesc_ma = 'Yveltal terbang menyerang sasaran dengan HP terendah di barisan belakang musuh, menyebabkan kerosakan sihir, membentuk <pautan maut> antara sasaran dan unit di barisan hadapan musuh, kemudian membuka kunci <pembunuhan tanpa henti> selama 1 giliran.',
		simDesc = 'Yveltal flies in to attack the enemy\'s backline target with the lowest HP, dealing magic damage and forming a [death link] between the target and the frontline enemy unit, then unlocks [infinite slaughter] for 1 turn.',
		starEffect = __data_t__starEffect[36113],
		-- {11}
		starEffectDesc_vn = 'Hệ số truyền sát thương của Liên Kết Chết Người tăng lên 35%; Cánh Chết Địa Ngục đi kèm với việc mục tiêu bị trừ đi 50% máu tối đa tương đương với lượng sát thương này trong 2 lượt (không hoàn lại lượng máu thực tế vào cuối lượt).',
		starEffectDesc = 'The damage transfer coefficient of Deadly Link increases by 35%; Hell Wings come with the target losing 50% of maximum HP equivalent to this damage for 2 turns (actual HP will not be restored at the end of the turn).',
		starEffectDesc_en = 'The damage transfer coefficient of Deadly Link increases by 35%; Hell Wings come with the target losing 50% of maximum HP equivalent to this damage for 2 turns (actual HP will not be restored at the end of the turn).',
		starEffectDesc_th = 'อัตราการโอนความเสียหายของ #Liên Kết Chết Người# เพิ่มขึ้น 35%; #Cánh Chết Địa Ngục# มาพร้อมกับเป้าหมายที่สูญเสีย 50% ของพลังชีวิตสูงสุดเทียบเท่ากับความเสียหายนี้เป็นเวลา 2 เทิร์น (พลังชีวิตจริงจะไม่ถูกฟื้นฟูในตอนท้ายเทิร์น)',
		starEffectDesc_in = 'Koefisien transfer kerusakan dari #Liên Kết Chết Người# meningkat sebesar 35%; #Cánh Chết Địa Ngục# hadir dengan target kehilangan 50% HP maksimum setara dengan jumlah kerusakan ini selama 2 giliran (HP aktual tidak akan dipulihkan di akhir giliran).',
		starEffectDesc_ph = 'Ang coefficient ng transfer ng damage ng #Liên Kết Chết Người# ay tumataas ng 35%; #Cánh Chết Địa Ngục# ay may kasamang target na mawalan ng 50% ng maximum na HP na katumbas ng damage na ito sa loob ng 2 turn (hindi mare-restore ang aktwal na HP sa pagtatapos ng turn).',
		starEffectDesc_ma = 'Pecahan pemindahan kerosakan #Liên Kết Chết Người# meningkat sebanyak 35%; #Cánh Chết Địa Ngục# membawa sasaran kehilangan 50% HP maksimum yang bersamaan dengan jumlah kerosakan ini selama 2 pusingan (HP sebenar tidak akan dipulihkan pada akhir pusingan).',
		upLvDesc = 'Fixed damage +192',
