	[36313] = {
		id = 36313,
		skillName_vn = 'Bão kim cương',
		skillName_en = 'Diamond Storm',
		skillName_th = 'พายุเพชร',
		skillName_in = 'Badai Berlian',
		skillName_ph = 'Bagyong Diyamante',
		skillName_ma = 'Badai Berlian',
		skillName = 'Diamond Storm',
		describe_vn = 'Dianxi triệu hồi tinh thể bao bọc một mục tiêu kẻ địch, gây ra #C0x3D8A99#500% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#sát thương ma thuật#C0x5B545B#, khiến mục tiêu rơi vào [Diamond Seal] trong 1 hiệp (Diamond Seal: Hiệu ứng điều khiển (hiệu ứng, không thể xua tan, không thể hành động), và xây dựng [Bức tường ánh sáng kim cương] trước mặt tất cả đồng minh (Tường ánh sáng kim cương: lá chắn cho tất cả, sức khỏe của bức tường ánh sáng là tổng sức phòng thủ gấp đôi 250% của Diancie); khi bức tường ánh sáng kim cương bị phá vỡ, nó sẽ phục hồi sức khỏe cho tất cả đồng minh từ tổng sức phòng thủ gấp đôi 250% của Dianxi (lượng hồi phục tràn được chuyển thành lá chắn) và giảm đòn tấn công kép 20% của tất cả kẻ thù trong 1 hiệp.',
		describe_en = 'Dianxi summons a crystal to envelop an enemy target, dealing #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# magic damage#C0x5B545B#, causing the target to fall under [Diamond Seal] for 1 turn (Diamond Seal: Control effect (cannot be dispelled, unable to act)), and creates a [Diamond Light Wall] in front of all allies (Diamond Light Wall: shield for all, the health of the Diamond Light Wall is double 250% of Dianxi\'s total defense); when the Diamond Light Wall is broken, it heals all allies based on double 250% of Dianxi\'s total defense (excess healing converts to shield) and reduces all enemies\' double attack by 20% for 1 turn.',
		describe_th = 'Dianxi เรียกผลึกล้อมเป้าหมายศัตรู สร้างความเสียหายเวท #C0x3D8A99#500%#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# ความเสียหายเวท#C0x5B545B# ทำให้เป้าหมายตกอยู่ในสถานะ [Diamond Seal] เป็นเวลา 1 เทิร์น (Diamond Seal: เอฟเฟกต์ควบคุม (ไม่สามารถลบสถานะได้ ไม่สามารถกระทำการใดๆ)) และสร้าง [กำแพงแสงเพชร] อยู่ด้านหน้าพันธมิตรทั้งหมด (กำแพงแสงเพชร: โล่ปกป้องทั้งหมด พลังชีวิตของกำแพงแสงเพชรเท่ากับ 250% ของการป้องกันรวมของ Dianxi คูณสอง); เมื่อกำแพงแสงเพชรถูกทำลาย จะฟื้นฟูพลังชีวิตให้พันธมิตรทั้งหมดตาม 250% ของการป้องกันรวมของ Dianxi คูณสอง (การฟื้นฟูที่เกินจะถูกเปลี่ยนเป็นโล่) และลดการโจมตีสองครั้งของศัตรูทั้งหมดลง 20% ใน 1 เทิร์น',
		describe_in = 'Dianxi memanggil kristal yang membungkus target musuh, menyebabkan #C0x3D8A99#500% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# kerusakan sihir#C0x5B545B#, membuat target terkena [Diamond Seal] selama 1 giliran (Diamond Seal: efek kontrol (tidak dapat dihilangkan, tidak bisa bertindak)), dan membangun [Tembok Cahaya Berlian] di depan semua sekutu (Tembok Cahaya Berlian: perisai untuk semua, kesehatan Tembok Cahaya Berlian adalah 250% dari total pertahanan Dianxi dikalikan dua); saat Tembok Cahaya Berlian hancur, itu akan memulihkan kesehatan semua sekutu berdasarkan 250% dari total pertahanan Dianxi dikalikan dua (pemulihan berlebih diubah menjadi perisai) dan mengurangi pukulan ganda semua musuh sebesar 20% selama 1 giliran.',
		describe_ph = 'Pinatawag ni Dianxi ang kristal upang balutin ang isang target na kalaban, na nagdudulot ng #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# magic damage#C0x5B545B#, na nagpapailalim sa target sa [Diamond Seal] sa loob ng 1 turn (Diamond Seal: Control effect (hindi matanggal, hindi makakilos)), at nagtatayo ng [Diamond Light Wall] sa harap ng lahat ng mga kakampi (Diamond Light Wall: shield para sa lahat, ang health ng Diamond Light Wall ay double 250% ng total defense ni Dianxi); kapag nasira ang Diamond Light Wall, ito ay magpapagaling sa lahat ng kakampi batay sa double 250% ng total defense ni Dianxi (ang sobrang paggaling ay nagiging shield) at nagpapababa ng double attack ng lahat ng kalaban ng 20% sa loob ng 1 turn.',
		describe_ma = 'Dianxi memanggil kristal yang meliputi sasaran musuh, menyebabkan #C0x3D8A99#500% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# kerosakan sihir#C0x5B545B#, menyebabkan sasaran terkena [Diamond Seal] selama 1 giliran (Diamond Seal: kesan kawalan (tidak boleh disingkirkan, tidak boleh bertindak)), dan membina [Dinding Cahaya Berlian] di hadapan semua sekutu (Dinding Cahaya Berlian: perisai untuk semua, kesihatan Dinding Cahaya Berlian adalah 250% daripada jumlah pertahanan Dianxi didarab dua); apabila Dinding Cahaya Berlian pecah, ia akan memulihkan kesihatan semua sekutu berdasarkan 250% daripada jumlah pertahanan Dianxi didarab dua (pemulihan berlebihan ditukar menjadi perisai) dan mengurangkan serangan berganda semua musuh sebanyak 20% selama 1 giliran.',
		describe = 'Dianxi summons a crystal to envelop an enemy target, dealing #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# magic damage#C0x5B545B#, causing the target to fall under [Diamond Seal] for 1 turn (Diamond Seal: Control effect (cannot be dispelled, unable to act)), and creates a [Diamond Light Wall] in front of all allies (Diamond Light Wall: shield for all, the health of the Diamond Light Wall is double 250% of Dianxi\'s total defense); when the Diamond Light Wall is broken, it heals all allies based on double 250% of Dianxi\'s total defense (excess healing converts to shield) and reduces all enemies\' double attack by 20% for 1 turn.',
		simDesc_vn = 'Dianxi triệu hồi các tinh thể để bao bọc một mục tiêu của kẻ thù, phong ấn mục tiêu trong một viên kim cương khổng lồ và xây dựng một bức tường ánh sáng kim cương trước toàn đội. Khi bức tường ánh sáng bị phá vỡ, toàn đội sẽ được phục hồi một lượng HP nhất định và đòn tấn công kép của tất cả kẻ thù sẽ bị giảm bớt.',
		starEffect = __data_t__starEffect[36313],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung:  <Tường Sáng Kim Cương> có thể phản xạ hiệu ứng tiêu cực.',
		starEffectDesc = 'Additional effect: <Diamond Light Wall> can reflect negative effects.',
		starEffectDesc_en = 'Additional effect: <Diamond Light Wall> can reflect negative effects.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: <กำแพงแสงเพชร> สามารถสะท้อนผลกระทบเชิงลบได้',
		starEffectDesc_in = 'Efek tambahan: <Dinding Cahaya Berlian> dapat memantulkan efek negatif.',
		starEffectDesc_ph = 'Karagdagang epekto: <Diamond Light Wall> ay maaaring magbalik ng mga negatibong epekto.',
		starEffectDesc_ma = 'Kesan tambahan: <Dinding Cahaya Berlian> boleh memantulkan kesan negatif.',
		zawakeEffect = __data_t__zawakeEffect[36313],
		-- {79003}
		zawakeEffectDesc = 'Diancie summons crystals to envelop an enemy target, dealing #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magic Damage#C0x5B545B#, causing the target to fall under <Diamond Seal> for 1 turn (Diamond Seal: control effect, cannot be dispelled, cannot move), and builds a <Diamond Light Wall> in front of all allies (Diamond Light Wall: shield for all, the health of the light wall is the total of 250% of Diancie\'s double defense); when the diamond light wall is broken, it will heal all allies from the total 250% of Diancie\'s double defense (overflow healing is converted into a shield), then reduces the double attack of all enemies by 30% for 1 turn and causes a random enemy target to fall under <Diamond Seal> for 1 turn.',
		zawakeEffectDesc_en = 'Diancie summons crystals to envelop an enemy target, dealing #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magic Damage#C0x5B545B#, causing the target to fall under <Diamond Seal> for 1 turn (Diamond Seal: control effect, cannot be dispelled, cannot move), and builds a <Diamond Light Wall> in front of all allies (Diamond Light Wall: shield for all, the health of the light wall is the total of 250% of Diancie\'s double defense); when the diamond light wall is broken, it will heal all allies from the total 250% of Diancie\'s double defense (overflow healing is converted into a shield), then reduces the double attack of all enemies by 30% for 1 turn and causes a random enemy target to fall under <Diamond Seal> for 1 turn.',
		zawakeEffectDesc_th = 'Dianxi เรียกผลึกขึ้นมาล้อมรอบเป้าหมายศัตรู ทำให้เกิด #C0x3D8A99#ความเสียหายเวทมนตร์ 500%#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# ทำให้เป้าหมายตกอยู่ในสถานะ <Diamond Seal> เป็นเวลา 1 เทิร์น (Diamond Seal: เอฟเฟกต์ควบคุม, ไม่สามารถลบสถานะได้, ไม่สามารถเคลื่อนที่), และสร้าง <กำแพงแสงเพชร> อยู่หน้าทุกพันธมิตร (กำแพงแสงเพชร: โล่สำหรับทุกคน, พลังชีวิตของกำแพงแสงรวมเป็น 250% ของการป้องกันคู่ของ Dianxi); เมื่อกำแพงแสงเพชรถูกทำลาย จะฟื้นฟูพลังชีวิตให้พันธมิตรทั้งหมดจาก 250% ของการป้องกันคู่ของ Dianxi (การฟื้นฟูเกินจะเปลี่ยนเป็นโล่), จากนั้นลดการโจมตีคู่ของศัตรูทั้งหมดลง 30% เป็นเวลา 1 เทิร์น และทำให้เป้าหมายศัตรูแบบสุ่มตกอยู่ในสถานะ <Diamond Seal> เป็นเวลา 1 เทิร์น',
		zawakeEffectDesc_in = 'Diancie memanggil kristal untuk membungkus target musuh, memberikan #C0x3D8A99#500% Damage Sihir#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Damage Sihir#C0x5B545B#, menyebabkan target terkena <Diamond Seal> selama 1 giliran (Diamond Seal: efek kontrol, tidak dapat dihapus, tidak dapat bergerak), dan membangun <Dinding Cahaya Berlian> di depan semua sekutu (Dinding Cahaya Berlian: perisai untuk semua, jumlah darah dinding cahaya adalah total 250% pertahanan ganda Diancie); ketika dinding cahaya berlian dihancurkan, itu akan menyembuhkan semua sekutu dari total 250% pertahanan ganda Diancie (penyembuhan berlebih diubah menjadi perisai), kemudian mengurangi serangan ganda semua musuh sebesar 30% selama 1 giliran dan menyebabkan target musuh acak terkena <Diamond Seal> selama 1 giliran.',
		zawakeEffectDesc_ph = 'Tinatawagan ni Diancie ang mga kristal upang balutin ang isang target na kaaway, nagbibigay ng #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magic Damage#C0x5B545B#, na nagdudulot sa target na mahulog sa ilalim ng <Diamond Seal> sa loob ng 1 turn (Diamond Seal: epekto ng kontrol, hindi maaaring tanggalin, hindi maaaring gumalaw), at bumubuo ng <Diamond Light Wall> sa harap ng lahat ng mga kakampi (Diamond Light Wall: kalasag para sa lahat, ang kalusugan ng light wall ay ang kabuuan ng 250% ng dobleng depensa ni Diancie); kapag nasira ang diamond light wall, maghihilom ito sa lahat ng kakampi mula sa kabuuang 250% ng dobleng depensa ni Diancie (ang sobra sa pagpapagaling ay nagiging kalasag), pagkatapos ay binabawasan ang dobleng atake ng lahat ng mga kaaway ng 30% sa loob ng 1 turn at nagdudulot sa isang random na target na kaaway na mahulog sa ilalim ng <Diamond Seal> sa loob ng 1 turn.',
		zawakeEffectDesc_ma = 'Diancie memanggil kristal untuk meliputi sasaran musuh, menyebabkan #C0x3D8A99#500% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Kerosakan Sihir#C0x5B545B#, menyebabkan sasaran jatuh di bawah <Diamond Seal> selama 1 pusingan (Diamond Seal: kesan kawalan, tidak boleh dikeluarkan, tidak boleh bergerak), dan membina <Dinding Cahaya Berlian> di hadapan semua sekutu (Dinding Cahaya Berlian: perisai untuk semua, jumlah hayat dinding cahaya adalah jumlah 250% pertahanan ganda Diancie); apabila dinding cahaya berlian pecah, ia akan memulihkan hayat semua sekutu dari jumlah 250% pertahanan ganda Diancie (pemulihan lebihan ditukar menjadi perisai), kemudian mengurangkan serangan berganda semua musuh sebanyak 30% selama 1 pusingan dan menyebabkan sasaran musuh rawak jatuh di bawah <Diamond Seal> selama 1 pusingan.',
		zawakeEffectDesc_vn = 'Dianxi triệu hồi các tinh thể để bao bọc một mục tiêu kẻ địch, gây ra #C0x3D8A99#500% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, khiến mục tiêu rơi vào <Diamond Seal> trong 1 hiệp (Diamond Seal: hiệu ứng khống chế, không thể xua tan, không thể di chuyển ), và xây dựng <Bức tường ánh sáng kim cương> trước mặt tất cả các đồng minh (Bức tường ánh sáng kim cương: lá chắn cho tất cả, lượng máu của bức tường ánh sáng là tổng của 250% khả năng phòng thủ kép của Diancie); khi bức tường ánh sáng kim cương bị phá vỡ, nó sẽ phục hồi máu cho tất cả đồng minh từ tổng 250% phòng thủ kép của Diancie (lượng hồi phục tràn được chuyển thành lá chắn), sau đó giảm 30% đòn tấn công kép của tất cả kẻ thù trong 1 hiệp và khiến một mục tiêu địch ngẫu nhiên rơi vào <Diamond Seal> trong 1 hiệp.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#<Diamond Light Wall> When all shields are broken, a random enemy will be trapped in <Diamond Seal> for 1 turn and all enemies will have their Dual Attack reduced by 30% for 1 turn.',
		zawakeSimpleDesc_en = '#C0x5c9970#<Diamond Light Wall> When all shields are broken, a random enemy will be trapped in <Diamond Seal> for 1 turn and all enemies will have their Dual Attack reduced by 30% for 1 turn.',
		zawakeSimpleDesc_th = '#C0x5c9970#<กำแพงแสงเพชร> เมื่อโล่ทั้งหมดแตก ศัตรูแบบสุ่ม 1 ตัวจะติด <ผนึกเพชร> 1 เทิร์น และศัตรูทั้งหมดจะถูกลดพลังโจมตีคู่ลง 30% เป็นเวลา 1 เทิร์น',
		zawakeSimpleDesc_in = '#C0x5c9970#<Dinding Cahaya Berlian> Saat semua perisai hancur, 1 musuh acak akan terkena <Segel Berlian> selama 1 giliran dan semua musuh akan dikurangi 30% Serangan Ganda selama 1 giliran.',
		zawakeSimpleDesc_ph = '#C0x5c9970#<Diamond Light Wall> Kapag nawasak lahat ng shield, isang random na kalaban ay maiipit sa <Diamond Seal> ng 1 turn at lahat ng kalaban ay mababawasan ng 30% Dual Attack sa loob ng 1 turn.',
		zawakeSimpleDesc_ma = '#C0x5c9970#<Tembok Cahaya Berlian> Apabila semua perisai musnah, satu musuh rawak akan terperangkap dalam <Diamond Seal> selama 1 pusingan dan semua musuh akan dikurangkan 30% Serangan Berganda selama 1 pusingan.',
		zawakeSimpleDesc_vn = '#C0x5c9970#<Bức tường ánh sáng kim cương> Khi toàn bộ lá chắn bị phá vỡ, một mục tiêu ngẫu nhiên của kẻ địch sẽ bị mắc kẹt trong <Diamond Seal> trong 1 lượt và tất cả kẻ địch sẽ bị giảm 30% đòn tấn công kép trong 1 lượt.',
