	[36316] = {
		id = 36316,
		skillName_vn = 'Bảo vệ huyền bí',
		skillName_en = 'Mystical Guardian',
		skillName_th = 'ผู้พิทักษ์ลี้ลับ',
		skillName_in = 'Penjaga Mistis',
		skillName_ph = 'Mahiwagang Tagapagtanggol',
		skillName_ma = 'Penjaga Misteri',
		skillName = 'Mystical Guardian',
		describe_vn = 'Khúc xạ kim cương: Mỗi khi kết thúc một đại lượt, sao chép ngẫu nhiên ba hiệu ứng tiêu cực của phe ta sang mục tiêu có công kích cao nhất của kẻ địch, mỗi lần sao chép thành công sẽ hồi phục lượng máu bằng #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# tổng phòng thủ kép của bản thân',
		describe_en = 'Diamond Refraction: At the end of each major turn, randomly copy three negative effects from our side to the enemy\'s highest attack target. Each successful copy restores HP equal to #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# of your total double defense.',
		describe_th = 'การหักเหของเพชร: เมื่อสิ้นสุดแต่ละรอบใหญ่ จะคัดลอกสถานะลบแบบสุ่มสามสถานะจากฝ่ายเราไปยังเป้าหมายที่มีพลังโจมตีสูงสุดของศัตรู แต่ละครั้งที่คัดลอกสำเร็จจะฟื้นฟูพลังชีวิตเป็นจำนวน #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# ของเกราะป้องกันรวมสองเท่าของตัวเอง',
		describe_in = 'Pembiasan Berlian: Setiap kali akhir putaran besar, secara acak menyalin tiga efek negatif dari pihak kita ke target musuh dengan serangan tertinggi. Setiap kali penyalinan berhasil, akan memulihkan HP sebesar #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# dari total pertahanan ganda diri sendiri.',
		describe_ph = 'Pagbabago ng Diyamante: Sa pagtatapos ng bawat malaking yugto, random na kinokopya ang tatlong negatibong epekto mula sa aming panig papunta sa kalaban na may pinakamataas na atake. Sa bawat matagumpay na pagkopya, nagpapagaling ng HP ng #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# ng kabuuang dobleng depensa ng sarili.',
		describe_ma = 'Pelarasan Berlian: Setiap kali tamat satu pusingan besar, secara rawak menyalin tiga kesan negatif dari pihak kita ke sasaran musuh dengan serangan tertinggi. Setiap salinan berjaya akan memulihkan HP sebanyak #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# jumlah pertahanan berganda sendiri.',
		describe = 'Diamond Refraction: At the end of each major turn, randomly copy three negative effects from our side to the enemy\'s highest attack target. Each successful copy restores HP equal to #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# of your total double defense.',
		starEffect = __data_t__starEffect[36316],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng thêm: Bắt đầu trận chiến sẽ dựng lên một bức  <Tường Ánh Sáng Kim Cương> , lượng máu của bức tường này bằng 500% tổng phòng thủ kép của Diancie.',
		starEffectDesc = 'Additional effect: At the start of the battle, a <Diamond Light Wall> will be erected, and the HP of this wall is 500% of Diancie\'s total dual defense.',
		starEffectDesc_en = 'Additional effect: At the start of the battle, a <Diamond Light Wall> will be erected, and the HP of this wall is 500% of Diancie\'s total dual defense.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อเริ่มการต่อสู้ จะตั้ง <#F3#<Tường Ánh Sáng Kim Cương>#L3#> ขึ้นมา โดยพลังชีวิตของกำแพงนี้เท่ากับ 500% ของการป้องกันคู่รวมของ Diancie',
		starEffectDesc_in = 'Efek tambahan: Pada awal pertempuran, sebuah <#F3#<Tường Ánh Sáng Kim Cương>#L3#> akan didirikan, dan HP dinding ini adalah 500% dari total pertahanan ganda Diancie.',
		starEffectDesc_ph = 'Karagdagang epekto: Sa simula ng laban, isang <#F3#<Tường Ánh Sáng Kim Cương>#L3#> ang itatatag, at ang HP ng pader na ito ay 500% ng kabuuang dobleng depensa ni Diancie.',
		starEffectDesc_ma = 'Kesan tambahan: Pada permulaan pertempuran, sebuah <#F3#<Tường Ánh Sáng Kim Cương>#L3#> akan didirikan, dan jumlah HP dinding ini adalah 500% daripada jumlah pertahanan berganda Diancie.',
		zawakeEffect = __data_t__zawakeEffect[36316],
		-- {79004, 1}
		zawakeEffectDesc = 'Additional effect: <Diamond Light Wall> is constructed at the start of the battle. The health of this light wall is the total defense multiplied by 500% of Dianxi; Improved effect of <Diamond Light Wall>: for each teammate present, the health of the light wall increases by 15%',
		zawakeEffectDesc_en = 'Additional effect: <Diamond Light Wall> is constructed at the start of the battle. The health of this light wall is the total defense multiplied by 500% of Dianxi; Improved effect of <Diamond Light Wall>: for each teammate present, the health of the light wall increases by 15%',
		zawakeEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: <กำแพงแสงเพชร> ถูกสร้างขึ้นเมื่อเริ่มการต่อสู้ ชีวิตของกำแพงแสงนี้คือค่าป้องกันรวมคูณ 500% ของ Dianxi; ปรับปรุงเอฟเฟกต์ของ <กำแพงแสงเพชร>: สำหรับแต่ละเพื่อนร่วมทีมที่อยู่ กำแพงแสงจะเพิ่มพลังชีวิตขึ้น 15%',
		zawakeEffectDesc_in = 'Efek tambahan: <Tembok Cahaya Berlian> dibangun saat mulai pertarungan. Kesehatan tembok cahaya ini adalah total pertahanan dikalikan 500% dari Dianxi; Meningkatkan efek <Tembok Cahaya Berlian>: untuk setiap rekan tim yang hadir, kesehatan tembok cahaya bertambah 15%',
		zawakeEffectDesc_ph = 'Karagdagang epekto: <Diamond Light Wall> ay binuo sa simula ng laban. Ang kalusugan ng light wall na ito ay ang kabuuang depensa na pinarami ng 500% ng Dianxi; Pinahusay na epekto ng <Diamond Light Wall>: para sa bawat kasamang koponan na naroroon, tumataas ang kalusugan ng light wall ng 15%',
		zawakeEffectDesc_ma = 'Kesan tambahan: <Tembok Cahaya Berlian> dibina pada permulaan pertempuran. Kesihatan tembok cahaya ini ialah jumlah pertahanan digandakan 500% daripada Dianxi; Menambah kesan <Tembok Cahaya Berlian>: untuk setiap rakan sepasukan yang hadir, kesihatan tembok cahaya meningkat 15%',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: <Bức tường ánh sáng kim cương> được xây dựng khi bắt đầu trận chiến. Sức khỏe của bức tường ánh sáng này là tổng sức phòng thủ gấp đôi 500% của Dianxi; Cải thiện hiệu ứng <Bức tường ánh sáng kim cương>: với mỗi đồng đội có mặt, máu của bức tường ánh sáng tăng thêm 15%',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970# <Diamond Light Wall> Enhanced effect: For each ally present, the wall\'s HP increases by 15%',
		zawakeSimpleDesc_en = '#C0x5c9970# <Diamond Light Wall> Enhanced effect: For each ally present, the wall\'s HP increases by 15%',
		zawakeSimpleDesc_th = '#C0x5c9970# <กำแพงแสงเพชร> เอฟเฟกต์เพิ่มเติม: สำหรับเพื่อนร่วมทีมแต่ละคนที่มีอยู่ เลือดของกำแพงแสงจะเพิ่มขึ้น 15%',
		zawakeSimpleDesc_in = '#C0x5c9970# <Dinding Cahaya Berlian> Efek tambahan: Untuk setiap rekan tim yang hadir, HP dinding akan meningkat 15%',
		zawakeSimpleDesc_ph = '#C0x5c9970# <Diamond Light Wall> Dagdag na epekto: Bawat kasamang kaalyado ay magdaragdag ng 15% HP sa pader',
		zawakeSimpleDesc_ma = '#C0x5c9970# <Tembok Cahaya Berlian> Kesan tambahan: Setiap rakan sepasukan yang hadir akan meningkatkan HP tembok sebanyak 15%',
		zawakeSimpleDesc_vn = '#C0x5c9970# <Tường ánh sáng kim cương> Cải thiện hiệu ứng: Với mỗi đồng đội có mặt, máu của bức tường ánh sáng được tăng thêm 15%',
