	[36322] = {
		id = 36322,
		skillName_vn = 'Ánh sáng ngọc',
		skillName_en = 'Gem light',
		skillName_th = 'แสงอัญมณี',
		skillName_in = 'Cahaya permata',
		skillName_ph = 'Ilaw ng hiyas',
		skillName_ma = 'Cahaya permata',
		skillName = 'Gem light',
		describe_vn = 'Viên đá quý trên đầu Diancie phát ra ánh sáng rực rỡ, tấn công mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#180% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ Sát Thương Phép Thuật#C0xF13B54#, đồng thời thêm một lá chắn đá quý có thể hấp thụ sát thương bằng 300% tổng phòng thủ kép của Diancie trong 2 lượt cho bản thân và đồng đội có công kích cao nhất (lấy giá trị lớn nhất giữa Công Vật Lý và Công Phép thuật) ngoại trừ bản thân; mục tiêu có lá chắn này sẽ tạm thời tăng 10% công kép của bản thân trước khi tấn công (lá chắn đá quý không thể chồng lặp)',
		describe_en = 'The gem on Diancie\'s head emits a brilliant light, attacking a single enemy target, causing #C0x3D8A99#180% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ Magic Damage#C0xF13B54#, while also adding a gem shield that can absorb damage equal to 300% of Diancie\'s total double defense for 2 turns to herself and the highest attack teammate (taking the greater value between Physical Attack and Magic Attack) excluding herself; targets with this shield will temporarily increase their double attack by 10% before attacking (gem shield cannot stack).',
		describe_th = 'อัญมณีบนหัวของดิแอนซี่ปล่อยแสงเจิดจ้า โจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0x3D8A99#180% พลังโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$ ความเสียหายเวทมนตร์#C0xF13B54# พร้อมทั้งเพิ่มโล่ห์อัญมณีที่สามารถดูดซับความเสียหายเท่ากับ 300% ของค่าป้องกันคู่รวมทั้งหมดของดิแอนซี่ เป็นเวลา 2 เทิร์น ให้กับตัวเองและเพื่อนร่วมทีมที่มีพลังโจมตีสูงสุด (โดยใช้ค่าที่สูงที่สุดระหว่างพลังโจมตีทางกายภาพและพลังโจมตีเวทมนตร์) ยกเว้นตัวเอง; เป้าหมายที่มีโล่นี้จะเพิ่มอัตราครั้งตีคู่ขึ้น 10% ชั่วคราวก่อนโจมตี (โล่อัญมณีไม่สามารถซ้อนทับได้)',
		describe_in = 'Batu permata di kepala Diancie memancarkan cahaya cemerlang, menyerang satu target musuh, menyebabkan #C0x3D8A99#180% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ Damage Sihir#C0xF13B54#, sekaligus menambahkan perisai permata yang dapat menyerap kerusakan sebesar 300% total pertahanan ganda Diancie selama 2 giliran untuk dirinya sendiri dan rekan tim dengan serangan tertinggi (mengambil nilai terbesar antara Serangan Fisik dan Serangan Sihir) kecuali dirinya sendiri; target dengan perisai ini akan sementara meningkatkan serangan ganda mereka sebesar 10% sebelum menyerang (perisai permata tidak dapat bertumpuk).',
		describe_ph = 'Ang hiyas sa ulo ni Diancie ay nagpapalabas ng maliwanag na liwanag, umaatake sa isang kalaban, nagdudulot ng #C0x3D8A99#180% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ Magical Damage#C0xF13B54#, kasabay ng pagdaragdag ng isang gem shield na maaaring sumipsip ng pinsalang katumbas ng 300% ng kabuuang dobleng depensa ni Diancie sa loob ng 2 turn para sa kanyang sarili at sa kasamahan na may pinakamataas na atake (kinukuha ang pinakamalaking halaga sa pagitan ng Physical Attack at Magic Attack) maliban sa kanya mismo; ang target na may shield na ito ay pansamantalang tataas ang kanilang dobleng atake ng 10% bago umatake (ang gem shield ay hindi maaaring magsanib).',
		describe_ma = 'Batu permata di atas kepala Diancie memancarkan cahaya terang, menyerang sasaran musuh tunggal, menyebabkan #C0x3D8A99#180% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ Kecederaan Sihir#C0xF13B54#, serta menambah perisai permata yang boleh menyerap kerosakan sebanyak 300% jumlah pertahanan berganda Diancie selama 2 giliran kepada dirinya sendiri dan rakan sepasukan dengan serangan tertinggi (mengambil nilai terbesar antara Serangan Fizikal dan Serangan Sihir) kecuali dirinya sendiri; sasaran yang mempunyai perisai ini akan sementara meningkatkan serangan berganda mereka sebanyak 10% sebelum menyerang (perisai permata tidak boleh bertindih).',
		describe = 'The gem on Diancie\'s head emits a brilliant light, attacking a single enemy target, causing #C0x3D8A99#180% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ Magic Damage#C0xF13B54#, while also adding a gem shield that can absorb damage equal to 300% of Diancie\'s total double defense for 2 turns to herself and the highest attack teammate (taking the greater value between Physical Attack and Magic Attack) excluding herself; targets with this shield will temporarily increase their double attack by 10% before attacking (gem shield cannot stack).',
		simDesc_vn = 'Viên ngọc trên đầu Tianxi phát ra ánh sáng chói lóa, hồi phục sinh lực cho toàn bộ đồng đội.',
		simDesc_en = 'The gem on Tianxi\'s forehead emitted a dazzling light, restoring vitality to the entire team.',
		simDesc_th = 'อัญมณีบนหน้าผากของเทียนซีเปล่งแสงเจิดจ้า ฟื้นฟูพลังชีวิตให้กับทีมทั้งหมด',
		simDesc_in = 'Permata di dahi Tianxi memancarkan cahaya yang menyilaukan, memulihkan energi seluruh tim.',
		simDesc_ph = 'Ang hiyas sa noo ni Tianxi ay naglabas ng makinang na liwanag, nagpapagaling ng lakas para sa buong koponan.',
		simDesc_ma = 'Mutiara di dahi Tianxi memancarkan cahaya yang terang, memulihkan tenaga kepada seluruh pasukan.',
		simDesc = 'The gem on Tianxi\'s forehead emitted a dazzling light, restoring vitality to the entire team.',
		zawakeEffect = __data_t__zawakeEffect[36322],
		-- {79002}
		zawakeEffectDesc = 'The gem on Diancie\'s head emits a dazzling light, attacking a single enemy target, causing #C0x3D8A99#180% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ Magic Damage#C0xF13B54# and creating a gem power shield for itself and the ally with the highest attack (taking the max double attack) that absorbs damage equal to a total of 400% of Diancie\'s double defense for 2 turns. Targets with this shield temporarily gain 20% double attack before attacking (gem power cannot stack).',
		zawakeEffectDesc_en = 'The gem on Diancie\'s head emits a dazzling light, attacking a single enemy target, causing #C0x3D8A99#180% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ Magic Damage#C0xF13B54# and creating a gem power shield for itself and the ally with the highest attack (taking the max double attack) that absorbs damage equal to a total of 400% of Diancie\'s double defense for 2 turns. Targets with this shield temporarily gain 20% double attack before attacking (gem power cannot stack).',
		zawakeEffectDesc_th = 'อัญมณีบนหัวของ Diyanshi ปล่อยแสงสว่างเจิดจ้า โจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0x3D8A99#180% พลังเวท#C0x5B545B#+$(skillLevel*4*24)$ ความเสียหายเวทมนตร์#C0xF13B54# และสร้างโล่พลังอัญมณีให้กับตนเองและพันธมิตรที่มีพลังโจมตีสูงสุด (เลือกการโจมตีคู่สูงสุด) ดูดซับความเสียหายจากการป้องกันคู่รวม 400% ของ Diyanshi เป็นเวลา 2 เทิร์น เป้าหมายที่มีโล่นี้จะได้รับพลังโจมตีคู่เพิ่มชั่วคราว 20% ก่อนที่จะโจมตี (พลังอัญมณีไม่สามารถซ้อนกันได้)',
		zawakeEffectDesc_in = 'Batu permata di kepala Diancie memancarkan cahaya terang, menyerang satu musuh target, menyebabkan #C0x3D8A99#180% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ Kerusakan Sihir#C0xF13B54# dan membuat perisai kekuatan permata untuk dirinya sendiri dan sekutu dengan serangan tertinggi (mengambil serangan ganda maksimum) yang menyerap kerusakan dari total 400% pertahanan ganda Diancie selama 2 giliran. Target dengan perisai ini sementara mendapatkan peningkatan 20% serangan ganda sebelum menyerang (kekuatan permata tidak dapat ditumpuk).',
		zawakeEffectDesc_ph = 'Ang bato sa ulo ni Diancie ay naglalabas ng nakakasilaw na liwanag, tumatama sa isang solong target na kaaway, nagdudulot ng #C0x3D8A99#180% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ Magic Damage#C0xF13B54# at lumilikha ng isang gemstone power shield para sa sarili at sa kakampi na may pinakamataas na atake (pinipili ang maximum na dobleng atake) na sumisipsip ng pinsala mula sa kabuuang 400% dobleng depensa ni Diancie sa loob ng 2 na turn. Ang mga target na may shield na ito ay pansamantalang tumataas ang 20% dobleng atake bago umatake (ang gemstone power ay hindi maaaring mag-stack).',
		zawakeEffectDesc_ma = 'Batu permata di kepala Diancie memancarkan cahaya yang berkilauan, menyerang sasaran musuh tunggal, menyebabkan #C0x3D8A99#180% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ Kerosakan Sihir#C0xF13B54# dan mencipta perisai kuasa permata untuk dirinya sendiri dan sekutu dengan serangan tertinggi (mengambil serangan berganda maksimum) yang menyerap kerosakan daripada jumlah 400% pertahanan berganda Diancie selama 2 pusingan. Sasaran dengan perisai ini sementara mendapat peningkatan 20% serangan berganda sebelum menyerang (kuasa permata tidak boleh bertindih).',
		zawakeEffectDesc_vn = 'Viên đá trên đầu Diancie phát ra ánh sáng chói lóa, tấn công mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#180% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ Sát Thương Phép Thuật#C0xF13B54# và tạo cho bản thân và đồng minh có tấn công cao nhất (lấy tối đa tấn công đôi) một lá chắn đá quý sức mạnh hấp thụ sát thương từ tổng 400% phòng thủ đôi của Diancie trong 2 lượt, mục tiêu có lá chắn này tạm thời tăng 20% tấn công đôi trước khi tấn công (đá quý sức mạnh không thể cộng dồn)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Grants a protective shield equal to 300% of Diancie\'s total Dual Defense for 2 turns. Targets with this shield will temporarily gain 10% Dual Attack before attacking#F20# #F40##C0x5c9970#→Grants a protective shield equal to 400% of Diancie\'s total Dual Defense for 2 turns. Targets with this shield will temporarily gain 20% Dual Attack before attacking',
		zawakeSimpleDesc_en = 'Grants a protective shield equal to 300% of Diancie\'s total Dual Defense for 2 turns. Targets with this shield will temporarily gain 10% Dual Attack before attacking#F20# #F40##C0x5c9970#→Grants a protective shield equal to 400% of Diancie\'s total Dual Defense for 2 turns. Targets with this shield will temporarily gain 20% Dual Attack before attacking',
		zawakeSimpleDesc_th = 'สร้างโล่ป้องกันเท่ากับ 300% ของพลังป้องกันคู่รวมของ Diancie เป็นเวลา 2 เทิร์น เป้าหมายที่มีโล่นี้จะได้รับพลังโจมตีคู่เพิ่มขึ้น 10% ชั่วคราวก่อนโจมตี#F20# #F40##C0x5c9970#→สร้างโล่ป้องกันเท่ากับ 400% ของพลังป้องกันคู่รวมของ Diancie เป็นเวลา 2 เทิร์น เป้าหมายจะได้รับพลังโจมตีคู่เพิ่มขึ้น 20% ชั่วคราวก่อนโจมตี',
		zawakeSimpleDesc_in = 'Memberikan perisai sebesar 300% dari total Pertahanan Ganda Diancie selama 2 giliran. Target dengan perisai ini akan mendapatkan 10% Serangan Ganda sementara sebelum menyerang#F20# #F40##C0x5c9970#→Memberikan perisai sebesar 400% dari total Pertahanan Ganda Diancie selama 2 giliran. Target akan mendapatkan 20% Serangan Ganda sementara sebelum menyerang',
		zawakeSimpleDesc_ph = 'Nagbibigay ng shield na katumbas ng 300% ng kabuuang Dual Defense ni Diancie sa loob ng 2 turn. Ang target na may shield ay pansamantalang makakakuha ng 10% Dual Attack bago umatake#F20# #F40##C0x5c9970#→Nagbibigay ng shield na katumbas ng 400% ng kabuuang Dual Defense ni Diancie sa loob ng 2 turn. Makakakuha ng 20% Dual Attack bago umatake',
		zawakeSimpleDesc_ma = 'Menambah perisai pelindung sebanyak 300% daripada jumlah Pertahanan Berganda Diancie selama 2 pusingan. Sasaran dengan perisai ini akan mendapat tambahan 10% Serangan Berganda sementara sebelum menyerang#F20# #F40##C0x5c9970#→Menambah perisai pelindung sebanyak 400% daripada jumlah Pertahanan Berganda Diancie selama 2 pusingan. Sasaran akan mendapat tambahan 20% Serangan Berganda sementara sebelum menyerang',
		zawakeSimpleDesc_vn = 'Thêm lá chắn bảo vệ bằng 300% tổng phòng thủ kép của Diancie trong 2 lượt, mục tiêu có lá chắn này sẽ tạm thời tăng 10% tấn công kép của bản thân trước khi tấn công#F20# #F40##C0x5c9970#→Thêm lá chắn bảo vệ bằng 400% tổng phòng thủ kép của Diancie trong 2 lượt, mục tiêu có lá chắn này sẽ tạm thời tăng 20% tấn công kép của bản thân trước khi tấn công',
		upLvDesc = 'Fixed damage +96',
