	[36323] = {
		id = 36323,
		skillName_vn = 'Bão kim cương',
		skillName_en = 'Diamond Storm',
		skillName_th = 'พายุเพชร',
		skillName_in = 'Badai Berlian',
		skillName_ph = 'Bagyong Diyamante',
		skillName_ma = 'Badai Berlian',
		skillName = 'Diamond Storm',
		describe_vn = 'Dianxi triệu hồi tinh thể bao bọc một mục tiêu kẻ địch, gây ra #C0x3D8A99#500% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#sát thương ma thuật#C0x5B545B#, khiến mục tiêu rơi vào [Diamond Seal] trong 1 hiệp (Diamond Seal: Hiệu ứng điều khiển (hiệu ứng, không thể xua tan, không thể hành động), và xây dựng [Bức tường ánh sáng kim cương] trước mặt tất cả đồng minh (Tường ánh sáng kim cương: lá chắn cho tất cả, sức khỏe của bức tường ánh sáng là tổng sức phòng thủ gấp đôi 250% của Diancie); khi bức tường ánh sáng kim cương bị phá vỡ, nó sẽ phục hồi sức khỏe cho tất cả đồng minh từ tổng sức phòng thủ gấp đôi 250% của Dianxi (lượng hồi phục tràn được chuyển thành lá chắn) và giảm đòn tấn công kép 20% của tất cả kẻ thù trong 1 hiệp.',
		describe_en = 'Dianxi summons a crystal that envelops an enemy target, dealing #C0x3D8A99#500% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# magic damage#C0x5B545B#, causing the target to fall into [Diamond Seal] for 1 turn (Diamond Seal: a control effect (effect, cannot be dispelled, cannot act)), and creates a [Diamond Light Wall] in front of all allies (Diamond Light Wall: a shield for all, its health equals twice 250% of Dianxi\'s total defense); when the Diamond Light Wall is broken, it heals all allies based on twice 250% of Dianxi\'s total defense (excess healing is converted to a shield) and reduces all enemies\' double attack rate by 20% for 1 turn.',
		describe_th = 'Dianxi เรียกคริสตัลล้อมรอบเป้าหมายศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#500%#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# ทำให้เป้าหมายติดสถานะ [Diamond Seal] เป็นเวลา 1 เทิร์น (Diamond Seal: สถานะควบคุม (สถานะ ไม่สามารถล้างสถานะ และไม่สามารถกระทำการใดๆ ได้)), และสร้าง [กำแพงแสงเพชร] อยู่ด้านหน้าของพันธมิตรทั้งหมด (กำแพงแสงเพชร: โล่ป้องกันสำหรับทุกคน สุขภาพของกำแพงเท่ากับค่าการป้องกันรวมที่คูณสอง 250% ของ Dianxi); เมื่อกำแพงแสงเพชรถูกทำลาย จะฟื้นฟูพลังชีวิตให้กับพันธมิตรทั้งหมดจากค่าการป้องกันรวมที่คูณสอง 250% ของ Dianxi (การฟื้นฟูส่วนเกินจะถูกเปลี่ยนเป็นโล่) และลดอัตราการโจมตีสองครั้งของศัตรูทั้งหมดลง 20% เป็นเวลา 1 เทิร์น',
		describe_in = 'Dianxi memanggil kristal yang membungkus target musuh, menyebabkan #C0x3D8A99#500% Kerusakan Sihir#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# kerusakan sihir#C0x5B545B#, membuat target terkena [Diamond Seal] selama 1 giliran (Diamond Seal: efek kontrol (efek, tidak bisa dihapus, tidak bisa bertindak)), dan membangun [Dinding Cahaya Berlian] di depan seluruh sekutu (Dinding Cahaya Berlian: perisai untuk semua, kesehatan dinding cahaya adalah total pertahanan dikalikan dua 250% dari Dianxi); ketika dinding cahaya berlian hancur, ia akan memulihkan kesehatan semua sekutu dari total pertahanan dikalikan dua 250% dari Dianxi (penyembuhan berlebih diubah menjadi perisai) dan mengurangi serangan ganda semua musuh sebesar 20% selama 1 giliran.',
		describe_ph = 'Si Dianxi ay nagmumungkahi ng kristal na bumabalot sa isang target ng kalaban, na nagdudulot ng #C0x3D8A99#500% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# pinsalang mahika#C0x5B545B#, na nagpapasailalim sa target sa [Diamond Seal] sa loob ng 1 liko (Diamond Seal: isang kontrol na epekto (epekto, hindi maaaring alisin, hindi maaaring kumilos)), at nagtatayo ng [Diamond Light Wall] sa harap ng lahat ng mga kaalyado (Diamond Light Wall: isang panangga para sa lahat, ang kalusugan ng dingding ng liwanag ay dalawang beses 250% ng kabuuang depensa ni Dianxi); kapag nabasag ang Diamond Light Wall, magpapagaling ito sa lahat ng kaalyado batay sa dalawang beses 250% ng kabuuang depensa ni Dianxi (ang sobra ng pagpapagaling ay nagiging panangga) at nagpapababa ng 20% sa double attack ng lahat ng mga kalaban sa loob ng 1 liko.',
		describe_ma = 'Dianxi memanggil kristal yang membalut sasaran musuh, menyebabkan #C0x3D8A99#500% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# kerosakan sihir#C0x5B545B#, menyebabkan sasaran terkena [Diamond Seal] selama 1 pusingan (Diamond Seal: kesan kawalan (kesan, tidak boleh dibuang, tidak boleh bertindak)), dan membina [Dinding Cahaya Berlian] di hadapan semua sekutu (Dinding Cahaya Berlian: perisai untuk semua, kesihatan dinding cahaya adalah jumlah pertahanan berganda 250% Dianxi); apabila dinding cahaya berlian musnah, ia akan memulihkan kesihatan semua sekutu berdasarkan jumlah pertahanan berganda 250% Dianxi (jumlah pemulihan berlebihan ditukar menjadi perisai) dan mengurangkan kadar serangan berganda semua musuh sebanyak 20% selama 1 pusingan.',
		describe = 'Dianxi summons a crystal that envelops an enemy target, dealing #C0x3D8A99#500% Magical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# magic damage#C0x5B545B#, causing the target to fall into [Diamond Seal] for 1 turn (Diamond Seal: a control effect (effect, cannot be dispelled, cannot act)), and creates a [Diamond Light Wall] in front of all allies (Diamond Light Wall: a shield for all, its health equals twice 250% of Dianxi\'s total defense); when the Diamond Light Wall is broken, it heals all allies based on twice 250% of Dianxi\'s total defense (excess healing is converted to a shield) and reduces all enemies\' double attack rate by 20% for 1 turn.',
		simDesc_vn = 'Dianxi triệu hồi các tinh thể để bao bọc một mục tiêu của kẻ thù, phong ấn mục tiêu trong một viên kim cương khổng lồ và xây dựng một bức tường ánh sáng kim cương trước toàn đội. Khi bức tường ánh sáng bị phá vỡ, toàn đội sẽ được phục hồi một lượng HP nhất định và đòn tấn công kép của tất cả kẻ thù sẽ bị giảm bớt.',
		simDesc_en = 'Dianxi summons crystals to encase an enemy target, sealing the target within a giant diamond and creating a diamond light wall in front of the entire team. When the diamond light wall is broken, the whole team restores a certain amount of HP, and the dual attacks of all enemies are weakened.',
		simDesc_th = 'Dianxi เรียกคริสตัลมาโอบล้อมเป้าหมายศัตรู ปิดผนึกเป้าหมายไว้ในเพชรขนาดยักษ์ และสร้างกำแพงแสงเพชรขึ้นหน้าทีมทั้งหมด เมื่อกำแพงแสงเพชรถูกทำลาย ทีมทั้งหมดจะได้รับการฟื้นฟูพลังชีวิตในระดับหนึ่ง และการโจมตีคู่ของศัตรูทั้งหมดจะถูกลดความรุนแรงลง',
		simDesc_in = 'Dianxi memanggil kristal untuk membungkus target musuh, menyegel target dalam berlian raksasa dan membangun dinding cahaya berlian di depan seluruh tim. Ketika dinding cahaya berlian hancur, seluruh tim akan memulihkan sejumlah HP tertentu dan serangan ganda semua musuh akan berkurang efeknya.',
		simDesc_ph = 'Si Dianxi ay nagsisummon ng mga kristal upang balutin ang isang kalaban na target, isinelyo ang target sa loob ng isang higanteng diyamante at nagtatayo ng isang pader ng liwanag na diyamante sa harap ng buong koponan. Kapag nabasag ang pader ng liwanag na diyamante, ang buong koponan ay makakabawi ng isang tiyak na halaga ng HP at ang doble na atake ng lahat ng kalaban ay mababawasan.',
		simDesc_ma = 'Dianxi memanggil kristal untuk membalut sasaran musuh, mengunci sasaran dalam berlian gergasi dan membina dinding cahaya berlian di hadapan seluruh pasukan. Apabila dinding cahaya berlian musnah, seluruh pasukan akan mendapat pemulihan HP tertentu dan serangan berganda semua musuh akan dikurangkan.',
		simDesc = 'Dianxi summons crystals to encase an enemy target, sealing the target within a giant diamond and creating a diamond light wall in front of the entire team. When the diamond light wall is broken, the whole team restores a certain amount of HP, and the dual attacks of all enemies are weakened.',
		starEffect = __data_t__starEffect[36323],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung:  <Tường Sáng Kim Cương> có thể phản xạ hiệu ứng tiêu cực.',
		starEffectDesc = 'Additional effect: <Diamond Light Wall> can reflect negative effects.',
		starEffectDesc_en = 'Additional effect: <Diamond Light Wall> can reflect negative effects.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: <กำแพงแสงเพชร> สามารถสะท้อนผลกระทบเชิงลบได้',
		starEffectDesc_in = 'Efek tambahan: <Dinding Cahaya Berlian> dapat memantulkan efek negatif.',
		starEffectDesc_ph = 'Karagdagang epekto: <Diamond Light Wall> ay maaaring magbalik ng mga negatibong epekto.',
		starEffectDesc_ma = 'Kesan tambahan: <Dinding Cahaya Berlian> boleh memantulkan kesan negatif.',
		zawakeEffect = __data_t__zawakeEffect[36323],
		-- {79003}
		zawakeEffectDesc = 'Diancie summons crystals to encase an enemy target, dealing #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magic Damage#C0x5B545B#, causing the target to fall into <Diamond Seal> for 1 turn (Diamond Seal: crowd control effect, cannot be dispelled, cannot move), and creates a <Diamond Light Wall> in front of all allies (Diamond Light Wall: shield for all, the wall\'s HP equals 250% of Diancie\'s dual defense); when the Diamond Light Wall breaks, it heals all allies based on 250% of Diancie\'s dual defense (excess healing converts to shields), then reduces all enemies\' dual attack by 30% for 1 turn and causes a random enemy target to fall into <Diamond Seal> for 1 turn.',
		zawakeEffectDesc_en = 'Diancie summons crystals to encase an enemy target, dealing #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magic Damage#C0x5B545B#, causing the target to fall into <Diamond Seal> for 1 turn (Diamond Seal: crowd control effect, cannot be dispelled, cannot move), and creates a <Diamond Light Wall> in front of all allies (Diamond Light Wall: shield for all, the wall\'s HP equals 250% of Diancie\'s dual defense); when the Diamond Light Wall breaks, it heals all allies based on 250% of Diancie\'s dual defense (excess healing converts to shields), then reduces all enemies\' dual attack by 30% for 1 turn and causes a random enemy target to fall into <Diamond Seal> for 1 turn.',
		zawakeEffectDesc_th = 'Diancie เรียกคริสตัลมาห่อเป้าหมายศัตรู ทำให้เกิดความเสียหายเวทมนตร์ #C0x3D8A99#500%#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# ความเสียหายเวทมนตร์#C0x5B545B# ทำให้เป้าหมายตกอยู่ในสถานะ <Diamond Seal> เป็นเวลา 1 เทิร์น (Diamond Seal: สถานะควบคุมไม่ให้เคลื่อนไหว ไม่สามารถลบออกได้) และสร้าง <กำแพงแสงเพชร> หน้าเพื่อนร่วมทีมทั้งหมด (กำแพงแสงเพชร: โล่ป้องกันสำหรับทุกคน มีพลังชีวิตเท่ากับ 250% ของการป้องกันคู่ของ Diancie); เมื่อกำแพงแสงเพชรถูกทำลาย จะฟื้นฟูพลังชีวิตให้เพื่อนร่วมทีมทั้งหมดตาม 250% การป้องกันคู่ของ Diancie (พลังฟื้นฟูส่วนเกินจะถูกแปลงเป็นโล่) จากนั้นลดพลังโจมตีคู่ของศัตรูทั้งหมด 30% เป็นเวลา 1 เทิร์น และทำให้เป้าหมายศัตรูสุ่มตกอยู่ใน <Diamond Seal> เป็นเวลา 1 เทิร์น',
		zawakeEffectDesc_in = 'Diancie memanggil kristal untuk membungkus target musuh, menyebabkan #C0x3D8A99#500% Damage Magic#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Damage Magic#C0x5B545B#, membuat target terkena <Diamond Seal> selama 1 giliran (Diamond Seal: efek kontrol, tidak bisa dihapus, tidak bisa bergerak), dan membangun <Tembok Cahaya Berlian> di depan semua sekutu (Tembok Cahaya Berlian: perisai untuk semua, HP tembok adalah total 250% dari pertahanan ganda Diancie); ketika Tembok Cahaya Berlian hancur, itu akan menyembuhkan semua sekutu dari total 250% pertahanan ganda Diancie (penyembuhan berlebih diubah menjadi perisai), kemudian mengurangi serangan ganda semua musuh sebesar 30% selama 1 giliran dan membuat satu target musuh secara acak terkena <Diamond Seal> selama 1 giliran.',
		zawakeEffectDesc_ph = 'Sumusumpa si Diancie ng mga kristal para balutin ang isang target na kalaban, na nagdudulot ng #C0x3D8A99#500% Magic Damage#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Magic Damage#C0x5B545B#, na nagpapahinto sa target sa ilalim ng <Diamond Seal> sa loob ng 1 turn (Diamond Seal: control effect, hindi pwedeng alisin, hindi pwedeng gumalaw), at bumubuo ng <Diamond Light Wall> sa harap ng lahat ng mga kasali (Diamond Light Wall: shield para sa lahat, ang HP ng pader ay ang kabuuan ng 250% ng dual defense ni Diancie); kapag nabasag ang Diamond Light Wall, ito ay magpapagaling sa lahat ng kasali base sa 250% dual defense ni Diancie (ang sobrang paggaling ay magiging shield), saka pinabababa ang dual attack ng lahat ng kalaban ng 30% sa loob ng 1 turn at pinapailalim ang isang random na kalaban sa <Diamond Seal> sa loob ng 1 turn.',
		zawakeEffectDesc_ma = 'Diancie memanggil kristal untuk membalut sasaran musuh, menyebabkan #C0x3D8A99#500% Kerosakan Ajaib#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Kerosakan Ajaib#C0x5B545B#, menyebabkan sasaran jatuh ke dalam <Diamond Seal> selama 1 giliran (Diamond Seal: kesan kawalan, tidak boleh dibersihkan, tidak boleh bergerak), dan membina <Dinding Cahaya Berlian> di hadapan semua sekutu (Dinding Cahaya Berlian: perisai untuk semua, jumlah darah dinding cahaya adalah jumlah 250% pertahanan berganda Diancie); apabila dinding cahaya berlian hancur, ia akan memulihkan darah untuk semua sekutu berdasarkan 250% pertahanan berganda Diancie (pemulihan lebihan ditukar menjadi perisai), kemudian mengurangkan serangan berganda semua musuh sebanyak 30% selama 1 giliran dan menyebabkan satu sasaran musuh rawak jatuh ke dalam <Diamond Seal> selama 1 giliran.',
		zawakeEffectDesc_vn = 'Dianxi triệu hồi các tinh thể để bao bọc một mục tiêu kẻ địch, gây ra #C0x3D8A99#500% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B#, khiến mục tiêu rơi vào <Diamond Seal> trong 1 hiệp (Diamond Seal: hiệu ứng khống chế, không thể xua tan, không thể di chuyển ), và xây dựng <Bức tường ánh sáng kim cương> trước mặt tất cả các đồng minh (Bức tường ánh sáng kim cương: lá chắn cho tất cả, lượng máu của bức tường ánh sáng là tổng của 250% khả năng phòng thủ kép của Diancie); khi bức tường ánh sáng kim cương bị phá vỡ, nó sẽ phục hồi máu cho tất cả đồng minh từ tổng 250% phòng thủ kép của Diancie (lượng hồi phục tràn được chuyển thành lá chắn), sau đó giảm 30% đòn tấn công kép của tất cả kẻ thù trong 1 hiệp và khiến một mục tiêu địch ngẫu nhiên rơi vào <Diamond Seal> trong 1 hiệp.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#<Diamond Light Wall> When all shields are broken, a random enemy will be trapped in <Diamond Seal> for 1 turn, and all enemies will have their Dual Attack reduced by 30% for 1 turn.',
		zawakeSimpleDesc_en = '#C0x5c9970#<Diamond Light Wall> When all shields are broken, a random enemy will be trapped in <Diamond Seal> for 1 turn, and all enemies will have their Dual Attack reduced by 30% for 1 turn.',
		zawakeSimpleDesc_th = '#C0x5c9970#<กำแพงแสงเพชร> เมื่อโล่ทั้งหมดถูกทำลาย ศัตรูสุ่มหนึ่งตัวจะติด <ผนึกเพชร> เป็นเวลา 1 เทิร์น และศัตรูทั้งหมดจะถูกลดพลังโจมตีคู่ลง 30% ใน 1 เทิร์น',
		zawakeSimpleDesc_in = '#C0x5c9970#<Dinding Cahaya Berlian> Ketika semua perisai hancur, satu musuh acak akan terperangkap dalam <Segel Berlian> selama 1 giliran dan semua musuh akan dikurangi 30% Serangan Ganda selama 1 giliran.',
		zawakeSimpleDesc_ph = '#C0x5c9970#<Diamond Light Wall> Kapag nawasak lahat ng shield, isang random na kalaban ay maiipit sa <Diamond Seal> ng 1 turn at lahat ng kalaban ay mababawasan ng 30% Dual Attack ng 1 turn.',
		zawakeSimpleDesc_ma = '#C0x5c9970#<Tembok Cahaya Berlian> Apabila semua perisai musnah, satu musuh rawak akan terperangkap dalam <Segel Berlian> selama 1 pusingan dan semua musuh akan dikurangkan 30% Serangan Berganda selama 1 pusingan.',
		zawakeSimpleDesc_vn = '#C0x5c9970#<Bức tường ánh sáng kim cương> Khi toàn bộ lá chắn bị phá vỡ, một mục tiêu ngẫu nhiên của kẻ địch sẽ bị mắc kẹt trong <Diamond Seal> trong 1 lượt và tất cả kẻ địch sẽ bị giảm 30% đòn tấn công kép trong 1 lượt.',
		upLvDesc = 'Fixed damage +360',
		upLvDesc_en = 'Fixed damage +360',
		upLvDesc_th = 'ความเสียหายคงที่ +360',
		upLvDesc_in = 'Kerusakan tetap +360',
