	[36326] = {
		id = 36326,
		skillName_vn = 'Bảo vệ huyền bí',
		skillName_en = 'Mystical Protection',
		skillName_th = 'การปกป้องลึกลับ',
		skillName_in = 'Perlindungan Mistis',
		skillName_ph = 'Mistikong Proteksyon',
		skillName_ma = 'Perlindungan Mistik',
		skillName = 'Mystical Protection',
		describe_vn = 'Khúc xạ kim cương: Mỗi khi kết thúc một đại lượt, sao chép ngẫu nhiên ba hiệu ứng tiêu cực của phe ta sang mục tiêu có công kích cao nhất của kẻ địch, mỗi lần sao chép thành công sẽ hồi phục lượng máu bằng #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# tổng phòng thủ kép của bản thân',
		describe_en = 'Diamond Refraction: At the end of each major turn, randomly copy three negative effects from your team to the enemy target with the highest attack. Each successful copy restores health equal to #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# of your total dual defense.',
		describe_th = 'การหักเหของเพชร: เมื่อจบแต่ละรอบใหญ่ จะคัดลอกผลกระทบลบสามอย่างจากฝ่ายของคุณแบบสุ่มไปยังเป้าหมายศัตรูที่มีพลังโจมตีสูงสุด แต่ละครั้งที่คัดลอกสำเร็จจะฟื้นฟูพลังชีวิตโดยเท่ากับ #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# ของการป้องกันคู่รวมของตัวเอง',
		describe_in = 'Pembiasan Berlian: Setiap kali ronde besar berakhir, salin secara acak tiga efek negatif dari pihak kita ke target musuh dengan serangan tertinggi. Setiap kali penyalinan berhasil, pulihkan kesehatan sebesar #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# dari total pertahanan ganda milikmu.',
		describe_ph = 'Diamond Refraction: Sa pagtatapos ng bawat pangunahing turn, random na kopyahin ang tatlong negatibong epekto mula sa ating panig papunta sa kalaban na may pinakamataas na atake. Bawat matagumpay na pagkopya ay magpapanumbalik ng buhay ng #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# ng kabuuang doble na depensa ng sarili.',
		describe_ma = 'Bias Berlian: Setiap kali satu pusingan utama berakhir, salin tiga kesan negatif secara rawak dari pihak kita ke sasaran musuh yang mempunyai serangan tertinggi. Setiap salinan yang berjaya akan memulihkan kesihatan sebanyak #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# daripada jumlah pertahanan berganda diri sendiri.',
		describe = 'Diamond Refraction: At the end of each major turn, randomly copy three negative effects from your team to the enemy target with the highest attack. Each successful copy restores health equal to #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# of your total dual defense.',
		starEffect = __data_t__starEffect[36326],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng thêm: Bắt đầu trận chiến sẽ dựng lên một bức  <Tường Ánh Sáng Kim Cương> , lượng máu của bức tường này bằng 500% tổng phòng thủ và phòng thủ đặc biệt của Diancie.',
		starEffectDesc = 'Additional effect: At the start of the battle, a <Diamond Light Wall> will be erected, with the wall\'s HP equal to 500% of Diancie\'s total defense and special defense.',
		starEffectDesc_en = 'Additional effect: At the start of the battle, a <Diamond Light Wall> will be erected, with the wall\'s HP equal to 500% of Diancie\'s total defense and special defense.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อต้นการต่อสู้ จะสร้าง <กำแพงแสงเพชร> ขึ้นมา โดยมีพลังชีวิตของกำแพงนี้เท่ากับ 500% ของค่าการป้องกันรวมและการป้องกันพิเศษของ Diancie',
		starEffectDesc_in = 'Efek tambahan: Pada awal pertarungan akan dibangun <Dinding Cahaya Berlian>, dengan HP dinding ini sebesar 500% dari total pertahanan dan pertahanan khusus Diancie.',
		starEffectDesc_ph = 'Karagdagang epekto: Sa simula ng laban ay magtatayo ng isang <Diamond Light Wall>, kung saan ang HP ng pader ay katumbas ng 500% ng kabuuang depensa at espesyal na depensa ni Diancie.',
		starEffectDesc_ma = 'Kesan tambahan: Pada permulaan pertempuran, sebuah <Dinding Cahaya Berlian> akan dibina, dengan jumlah darah dinding ini adalah 500% daripada jumlah pertahanan dan pertahanan khas Diancie.',
		zawakeEffect = __data_t__zawakeEffect[36326],
		-- {79004, 1}
		zawakeEffectDesc = 'Additional effect: <Diamond Light Wall> is built at the start of the battle. The health of this light wall is the sum of the defense doubled 500% of Diancie; Improve the effect of <Diamond Light Wall>: for each enemy present, the health of the light wall increases by 15%',
		zawakeEffectDesc_en = 'Additional effect: <Diamond Light Wall> is built at the start of the battle. The health of this light wall is the sum of the defense doubled 500% of Diancie; Improve the effect of <Diamond Light Wall>: for each enemy present, the health of the light wall increases by 15%',
		zawakeEffectDesc_th = 'เอฟเฟกต์เสริม: <#Bức tường ánh sáng kim cương#> ถูกสร้างขึ้นเมื่อเริ่มการต่อสู้ พลังชีวิตของกำแพงแสงนี้คือผลรวมของพลังป้องกันที่เพิ่มเป็น 500% ของ #F Diancie#; ปรับปรุงเอฟเฟกต์ <#Bức tường ánh sáng kim cương#>: สำหรับศัตรูแต่ละตัวที่อยู่ขณะนั้น พลังชีวิตของกำแพงแสงจะเพิ่มขึ้นอีก 15%',
		zawakeEffectDesc_in = 'Efek tambahan: <#Bức tường ánh sáng kim cương#> dibangun saat pertempuran dimulai. Kesehatan dinding cahaya ini adalah jumlah pertahanan yang digandakan 500% dari #F Diancie#; Tingkatkan efek <#Bức tường ánh sáng kim cương#>: untuk setiap musuh yang hadir, kesehatan dinding cahaya bertambah 15%',
		zawakeEffectDesc_ph = 'Karagdagang epekto: <#Bức tường ánh sáng kim cương#> ay itinayo sa simula ng laban. Ang kalusugan ng liwanag na pader na ito ay ang kabuuan ng depensa na doble ng 500% ni #F Diancie#; Pagbutihin ang epekto ng <#Bức tường ánh sáng kim cương#>: para sa bawat kalabang naroroon, ang kalusugan ng liwanag na pader ay tumataas ng 15%',
		zawakeEffectDesc_ma = 'Kesan tambahan: <#Bức tường ánh sáng kim cương#> dibina semasa permulaan pertempuran. Kesihatan dinding cahaya ini adalah jumlah pertahanan berganda 500% #F Diancie#; Memperbaiki kesan <#Bức tường ánh sáng kim cương#>: untuk setiap musuh yang hadir, kesihatan dinding cahaya bertambah 15%',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: <Bức tường ánh sáng kim cương> được xây dựng khi bắt đầu trận chiến. Sức khỏe của bức tường ánh sáng này là tổng sức phòng thủ gấp đôi 500% của Diancie; Cải thiện hiệu ứng <Bức tường ánh sáng kim cương>: đối với mỗi kẻ địch có mặt, máu của bức tường ánh sáng tăng thêm 15%',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970# <Diamond Light Wall> Enhanced effect: For each ally present, the wall\'s HP increases by 15%',
		zawakeSimpleDesc_en = '#C0x5c9970# <Diamond Light Wall> Enhanced effect: For each ally present, the wall\'s HP increases by 15%',
		zawakeSimpleDesc_th = '#C0x5c9970# <กำแพงแสงเพชร> เอฟเฟกต์เพิ่มเติม: สำหรับเพื่อนร่วมทีมแต่ละคนที่มีอยู่ เลือดของกำแพงแสงจะเพิ่มขึ้น 15%',
		zawakeSimpleDesc_in = '#C0x5c9970# <Tembok Cahaya Berlian> Efek tambahan: Untuk setiap rekan tim yang hadir, HP tembok akan bertambah 15%',
		zawakeSimpleDesc_ph = '#C0x5c9970# <Diamond Light Wall> Dagdag na epekto: Kada kaalyado na nasa field, tataas ng 15% ang HP ng pader',
		zawakeSimpleDesc_ma = '#C0x5c9970# <Tembok Cahaya Berlian> Kesan tambahan: Setiap rakan sepasukan yang hadir akan meningkatkan HP tembok sebanyak 15%',
		zawakeSimpleDesc_vn = '#C0x5c9970# <Tường ánh sáng kim cương> Cải thiện hiệu ứng: Với mỗi đồng đội có mặt, máu của bức tường ánh sáng được tăng thêm 15%',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
