	[36416] = {
		id = 36416,
		skillName_vn = 'Vòng ánh sáng trừng phạt',
		skillName_en = 'Punishment Light Ring',
		skillName_th = 'แหวนแสงลงโทษ',
		skillName_in = 'Cincin Cahaya Hukuman',
		skillName_ph = 'Singsing ng Liwanag na Pagparusa',
		skillName_ma = 'Cincin Cahaya Hukuman',
		skillName = 'Punishment Light Ring',
		describe_vn = 'Trước mỗi vòng lớn, chỉ định ngẫu nhiên 6 [Bánh xe Ánh sáng] trên cơ thể của bạn cho hàng đầu của kẻ địch và lấy lại tất cả [Bánh xe Ánh sáng] trước lượt của mình (hồi phục ngay sau khi mục tiêu chết)\n#F20# \n#F40##L10#Bánh xe Ánh sáng: #L0#Hiệu ứng đặc biệt, 6 bánh xe ánh sáng tương ứng với thuộc tính sáu chiều. Khi được áp dụng, các thuộc tính cơ bản tương ứng của mục tiêu sẽ bị giảm vĩnh viễn (từ 8% thuộc tính sáu chiều cơ bản của Hupa, có thể bị xua tan và giới hạn trên của một mục tiêu là 3 lớp). Khi bánh xe ánh sáng quay trở lại, nó sẽ vĩnh viễn chuyển thành thuộc tính của chính nó\n#F20# \n#F40# Giảm #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# sát thương cuối cùng mà bạn nhận được và chuyển 150% sát thương này sang một mục tiêu ngẫu nhiên ở hàng đầu của kẻ địch với 50% đòn Sát Thương Vật Lý của chính bạn là sát thương chuẩn',
		describe_en = 'Before each major round, randomly assign 6 [Wheels of Light] on your body to the front row of the enemy and recover all [Wheels of Light] before your turn (recover immediately after the target dies)\n#F20# \n#F40##L10#Wheels of Light:#L0#Special effect, 6 wheels of light correspond to the six-dimensional attributes. When applied, the target\'s corresponding basic attributes will be permanently reduced (from 8% of Hupa\'s six-dimensional basic attributes, can be dispelled, with a maximum limit of 3 stacks per target). When the wheels of light return, they will permanently transform into their own attribute\n#F20# \n#F40# Reduces #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# of the final damage you receive and transfers 150% of this damage to a random target in the front row of the enemy, with 50% of your Physical Damage dealt as true damage.',
		describe_th = 'ก่อนแต่ละรอบใหญ่ จะสุ่มกำหนด 6 [ล้อแห่งแสง] บนร่างกายของคุณไปยังแถวหน้าของศัตรูและฟื้นฟู [ล้อแห่งแสง] ทั้งหมดก่อนเทิร์นของคุณ (ฟื้นฟูทันทีหลังจากเป้าหมายตาย)\n#F20# \n#F40##L10#ล้อแห่งแสง:#L0#เอฟเฟกต์พิเศษ ล้อแห่งแสง 6 ล้อสอดคล้องกับคุณสมบัติหกมิติต่างๆ เมื่อถูกใช้งาน คุณสมบัติพื้นฐานที่เกี่ยวข้องของเป้าหมายจะถูกลดลงถาวร (จาก 8% ของคุณสมบัติพื้นฐานหกมิติของฮูป้า สามารถถูกลบและจำกัดสูงสุด 3 ชั้นต่อเป้าหมาย) เมื่อล้อแห่งแสงกลับมา จะเปลี่ยนเป็นคุณสมบัติของมันเองถาวร\n#F20# \n#F40# ลด #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# ของความเสียหายสุดท้ายที่คุณได้รับและโอนความเสียหายนี้ 150% ไปยังเป้าหมายสุ่มในแถวหน้าของศัตรู โดยความเสียหายทางกายภาพ 50% ของคุณจะนับเป็นความเสียหายจริง',
		describe_in = 'Sebelum setiap putaran besar, tetapkan secara acak 6 [Roda Cahaya] pada tubuhmu ke barisan depan musuh dan pulihkan semua [Roda Cahaya] sebelum giliranmu (pulih segera setelah target mati)\n#F20# \n#F40##L10#Roda Cahaya:#L0#Efek khusus, 6 roda cahaya sesuai dengan atribut enam dimensi. Saat diterapkan, atribut dasar target yang sesuai akan berkurang secara permanen (dari 8% atribut dasar enam dimensi Hupa, dapat dibersihkan, dengan batas maksimum 3 tumpukan per target). Ketika roda cahaya kembali, itu akan berubah secara permanen menjadi atributnya sendiri\n#F20# \n#F40# Mengurangi #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# kerusakan akhir yang kamu terima dan mentransfer 150% dari kerusakan ini ke target acak di barisan depan musuh, dengan 50% dari Damage Fisikmu menjadi damage nyata.',
		describe_ph = 'Bago ang bawat malaking round, random na italaga ang 6 na [Mga Gulong ng Liwanag] sa iyong katawan sa harapang hanay ng kalaban at ibalik lahat ng [Mga Gulong ng Liwanag] bago ang iyong turn (mabilis na gumaling pagkatapos mamatay ang target)\n#F20# \n#F40##L10#Mga Gulong ng Liwanag:#L0#Espesyal na epekto, ang 6 na gulong ng liwanag ay tumutugma sa anim na dimensional na katangian. Kapag inilapat, ang katumbas na pangunahing katangian ng target ay permanenteng babawasan (mula sa 8% ng anim na dimensional na pangunahing katangian ng Hupa, maaaring mawala at may maximum na limit na 3 layers bawat target). Kapag bumalik ang mga gulong ng liwanag, permanenteng ito ay magiging sarili nilang katangian\n#F20# \n#F40# Binabawasan ang #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# ng panghuling pinsalang iyong natatanggap at inililipat ang 150% ng pinsalang ito sa isang random na target sa harapang hanay ng kalaban, kung saan 50% ng iyong Physical Damage ay nagiging tunay na pinsala.',
		describe_ma = 'Sebelum setiap pusingan besar, tetapkan secara rawak 6 [Roda Cahaya] pada tubuh anda ke barisan hadapan musuh dan pulihkan semua [Roda Cahaya] sebelum giliran anda (pulih serta-merta selepas sasaran mati)\n#F20# \n#F40##L10#Roda Cahaya:#L0#Kesan khas, 6 roda cahaya sepadan dengan atribut enam dimensi. Apabila digunakan, atribut asas sasaran yang berkaitan akan berkurang secara kekal (daripada 8% atribut asas enam dimensi Hupa, boleh dibersihkan dan had maksimum 3 lapisan bagi setiap sasaran). Apabila roda cahaya kembali, ia akan kekal berubah menjadi atributnya sendiri\n#F20# \n#F40# Mengurangkan #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# kerosakan akhir yang anda terima dan memindahkan 150% kerosakan ini ke sasaran rawak dalam barisan hadapan musuh, dengan 50% daripada Kerosakan Fizikal anda menjadi kerosakan sebenar.',
		describe = 'Before each major round, randomly assign 6 [Wheels of Light] on your body to the front row of the enemy and recover all [Wheels of Light] before your turn (recover immediately after the target dies)\n#F20# \n#F40##L10#Wheels of Light:#L0#Special effect, 6 wheels of light correspond to the six-dimensional attributes. When applied, the target\'s corresponding basic attributes will be permanently reduced (from 8% of Hupa\'s six-dimensional basic attributes, can be dispelled, with a maximum limit of 3 stacks per target). When the wheels of light return, they will permanently transform into their own attribute\n#F20# \n#F40# Reduces #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# of the final damage you receive and transfers 150% of this damage to a random target in the front row of the enemy, with 50% of your Physical Damage dealt as true damage.',
		starEffect = __data_t__starEffect[36416],
		-- {8}
		starEffectDesc_vn = 'Hiệu Ứng Bổ Sung: Khi vào trận, Hu Pa sẽ vươn tay ma quái để vĩnh viễn đánh cắp 10% giảm sát thương từ mỗi mục tiêu hàng đầu của kẻ thù (không thể bị giải tán), và chuyển đổi 10% giảm sát thương đã đánh cắp thành tăng sát thương trước khi tấn công.',
		starEffectDesc = 'Additional Effect: When entering battle, Hu Pa will extend a ghostly hand to permanently steal 10% damage reduction from each of the enemy\'s front-row targets (cannot be dispelled), and convert the stolen 10% damage reduction into increased damage before attacking.',
		starEffectDesc_en = 'Additional Effect: When entering battle, Hu Pa will extend a ghostly hand to permanently steal 10% damage reduction from each of the enemy\'s front-row targets (cannot be dispelled), and convert the stolen 10% damage reduction into increased damage before attacking.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อเข้าสู่การต่อสู้ Hu Pa จะยืดมือผีไปขโมยการลดความเสียหาย 10% จากแต่ละเป้าหมายแถวหน้าในศัตรูอย่างถาวร (ไม่สามารถลบได้) และแปลงการลดความเสียหาย 10% ที่ขโมยมาเป็นการเพิ่มความเสียหายก่อนโจมตี',
		starEffectDesc_in = 'Efek Tambahan: Saat memasuki pertempuran, Hu Pa akan mengulurkan tangan gaib untuk selamanya mencuri 10% pengurangan kerusakan dari setiap target barisan depan musuh (tidak dapat dibatalkan), dan mengubah 10% pengurangan kerusakan yang dicuri menjadi peningkatan kerusakan sebelum menyerang.',
		starEffectDesc_ph = 'Karagdagang Epekto: Kapag pumasok sa laban, si Hu Pa ay magpapalapit ng mahiwagang kamay upang permanenteng nakawin ang 10% bawas sa pinsala mula sa bawat pangunahing target ng kalaban (hindi maaaring alisin), at i-convert ang nakaw na 10% bawas sa pinsala bilang dagdag na pinsala bago umatake.',
		starEffectDesc_ma = 'Kesan Tambahan: Apabila memasuki pertempuran, Hu Pa akan menghulurkan tangan hantu untuk mencuri secara kekal 10% pengurangan kerosakan daripada setiap sasaran barisan hadapan musuh (tidak boleh dibuang), dan menukar 10% pengurangan kerosakan yang dicuri menjadi peningkatan kerosakan sebelum menyerang.',
		zawakeEffect = __data_t__zawakeEffect[36416],
		-- {79004, 1}
		zawakeEffectDesc = 'Additional effect: Upon entering battle, Hoopa permanently steals 10% damage reduction from each enemy front row target (cannot be dispelled), before attacking converts 5% stolen damage reduction into 10% damage increase; each time the light ring returns to position, steals 20 energy points from the target',
		zawakeEffectDesc_en = 'Additional effect: Upon entering battle, Hoopa permanently steals 10% damage reduction from each enemy front row target (cannot be dispelled), before attacking converts 5% stolen damage reduction into 10% damage increase; each time the light ring returns to position, steals 20 energy points from the target',
		zawakeEffectDesc_th = 'เอฟเฟ็กต์เสริม: เมื่อเข้าสู่การต่อสู้ Hoopa จะขโมยการลดความเสียหาย 10% ตลอดไปจากเป้าหมายแถวหน้าของศัตรูแต่ละตัว (ไม่สามารถลบได้) ก่อนโจมตีจะเปลี่ยนการลดความเสียหายที่ขโมยมา 5% เป็นการเพิ่มความเสียหาย 10%; ทุกครั้งที่แหวนแสงกลับตำแหน่งจะขโมยพลังงาน 20 คะแนนจากเป้าหมาย',
		zawakeEffectDesc_in = 'Efek tambahan: Saat bertarung, Hoopa secara permanen mencuri pengurangan kerusakan 10% dari setiap sasaran baris depan musuh (tidak dapat dihilangkan), sebelum menyerang mengubah 5% pengurangan kerusakan yang dicuri menjadi peningkatan kerusakan 10%; setiap kali cincin cahaya kembali ke posisi, mencuri 20 poin energi dari target',
		zawakeEffectDesc_ph = 'Karagdagang epekto: Kapag pumasok sa laban, permanenteng ninakaw ni Hoopa ang 10% bawas pinsala mula sa bawat target sa harapang hilera ng kalaban (hindi maaaring alisin), bago umatake, gagawin nitong 10% ang 5% ninakaw na bawas pinsala bilang dagdag pinsala; sa bawat pagbabalik ng ilaw na singsing sa posisyon, ninanakaw nito ang 20 puntos ng enerhiya mula sa target',
		zawakeEffectDesc_ma = 'Kesan tambahan: Apabila memasuki pertempuran, Hoopa akan mencuri secara kekal pengurangan kerosakan sebanyak 10% daripada setiap sasaran barisan hadapan musuh (tidak boleh dibuang), sebelum menyerang menukar 5% pengurangan kerosakan yang dicuri menjadi peningkatan kerosakan 10%; setiap kali cincin cahaya kembali ke kedudukan, mencuri 20 mata tenaga daripada sasaran',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: Khi vào trận, Hoopa đưa tay ma quỷ vĩnh viễn đánh cắp 10% giảm sát thương của mỗi mục tiêu hàng trước của kẻ địch (không thể xua tan), trước khi tấn công sẽ chuyển đổi 5% giảm sát thương đã đánh cắp thành 10% tăng sát thương; mỗi khi vòng sáng trở về vị trí, đánh cắp 20 điểm nộ khí của mục tiêu',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'At the start of battle, Hoopa extends its demonic hands to permanently steal 10% damage reduction from each front row enemy (cannot be dispelled), and converts 10% of the stolen reduction into bonus damage before attacking#F20# #F40##C0x5c9970#→At the start of battle, Hoopa extends its demonic hands to permanently steal 10% damage reduction from each front row enemy (cannot be dispelled), and converts 5% of the stolen reduction into 10% bonus damage before attacking; each time Halo returns to position, it steals an extra 20 Rage from the target',
		zawakeSimpleDesc_en = 'At the start of battle, Hoopa extends its demonic hands to permanently steal 10% damage reduction from each front row enemy (cannot be dispelled), and converts 10% of the stolen reduction into bonus damage before attacking#F20# #F40##C0x5c9970#→At the start of battle, Hoopa extends its demonic hands to permanently steal 10% damage reduction from each front row enemy (cannot be dispelled), and converts 5% of the stolen reduction into 10% bonus damage before attacking; each time Halo returns to position, it steals an extra 20 Rage from the target',
		zawakeSimpleDesc_th = 'เมื่อเริ่มการต่อสู้ Hoopa จะยื่นมือปีศาจออกมาเพื่อขโมยการลดความเสียหายของศัตรูแถวหน้าถาวร 10% ต่อเป้าหมาย (ไม่สามารถลบได้) และก่อนโจมตีจะแปลง 10% การลดความเสียหายที่ขโมยมาเป็นโบนัสความเสียหาย#F20# #F40##C0x5c9970#→ก่อนโจมตีจะแปลง 5% ของการลดความเสียหายที่ขโมยมาเป็นโบนัสความเสียหาย 10%; ทุกครั้งที่ Halo กลับตำแหน่ง จะขโมยเพิ่มอีก 20 โทสะ',
		zawakeSimpleDesc_in = 'Saat memasuki pertempuran, Hoopa mencuri secara permanen 10% pengurangan kerusakan dari setiap musuh baris depan (tidak bisa dihapus), sebelum menyerang mengubah 10% dari pengurangan tersebut menjadi kerusakan tambahan#F20# #F40##C0x5c9970#→Mengubah 5% pengurangan tersebut menjadi 10% kerusakan tambahan; setiap kali Halo kembali ke posisi, mencuri tambahan 20 Rage dari target',
		zawakeSimpleDesc_ph = 'Sa simula ng laban, ninanakaw ni Hoopa ang 10% damage reduction mula sa bawat kalaban sa front row (hindi matatanggal), bago umatake, nagiging dagdag damage ang 10% nito#F20# #F40##C0x5c9970#→Nagiging 10% bonus damage mula sa 5% ng ninakaw na reduction; kada balik ni Halo sa posisyon, nananakaw pa ng 20 Rage',
		zawakeSimpleDesc_ma = 'Apabila memasuki pertempuran, Hoopa mencuri kekal 10% pengurangan kerosakan dari setiap musuh barisan hadapan (tidak boleh dipadam), sebelum menyerang akan menukar 10% menjadi kerosakan tambahan#F20# #F40##C0x5c9970#→Menukar 5% menjadi 10% kerosakan tambahan; setiap kali Halo kembali ke posisi, mencuri 20 Mata Amarah lagi',
		zawakeSimpleDesc_vn = 'Khi vào trận, Hoopa đưa tay ma quỷ ra cướp vĩnh viễn 10% giảm sát thương của mỗi mục tiêu hàng trước của kẻ địch (không thể xóa), trước khi tấn công sẽ chuyển đổi 10% giảm sát thương đã cướp thành tăng sát thương#F20# #F40##C0x5c9970#→Khi vào trận, Hoopa đưa tay ma quỷ ra cướp vĩnh viễn 10% giảm sát thương của mỗi mục tiêu hàng trước của kẻ địch (không thể xóa), trước khi tấn công sẽ chuyển đổi 5% giảm sát thương đã cướp thành 10% tăng sát thương; mỗi khi Vòng Sáng trở về vị trí, sẽ cướp thêm 20 điểm nộ khí của mục tiêu',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
