	[36426] = {
		id = 36426,
		skillName_vn = 'Giải phóng vòng ánh sáng',
		skillName_en = 'Release the ring of light',
		skillName_th = 'ปลดปล่อยวงแหวนแห่งแสง',
		skillName_in = 'Melepaskan cincin cahaya',
		skillName_ph = 'Palayain ang singsing ng liwanag',
		skillName_ma = 'Melepaskan cincin cahaya',
		skillName = 'Release the ring of light',
		describe_vn = 'Trước mỗi vòng lớn, chỉ định ngẫu nhiên 6 [Bánh xe Ánh sáng] trên cơ thể của bạn cho hàng đầu của kẻ địch và lấy lại tất cả [Bánh xe Ánh sáng] trước lượt của mình (hồi phục ngay sau khi mục tiêu chết)\n#F20# \n#F40##L10#Bánh xe Ánh sáng: #L0#Hiệu ứng đặc biệt, 6 bánh xe ánh sáng tương ứng với thuộc tính sáu chiều. Khi được áp dụng, các thuộc tính cơ bản tương ứng của mục tiêu sẽ bị giảm vĩnh viễn (từ 8% thuộc tính sáu chiều cơ bản của Hupa, có thể bị xua tan và giới hạn trên của một mục tiêu là 3 lớp). Khi bánh xe ánh sáng quay trở lại, nó sẽ vĩnh viễn chuyển thành thuộc tính của chính nó\n#F20# \n#F40# Giảm #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# sát thương cuối cùng mà bạn nhận được và chuyển 150% sát thương này sang một mục tiêu ngẫu nhiên ở hàng đầu của kẻ địch với 50% đòn Sát Thương Vật Lý của chính bạn là sát thương chuẩn',
		describe_en = 'Before each major round, randomly assign 6 [Wheels of Light] on your body to the front row of the enemy and retrieve all [Wheels of Light] before your turn (recover immediately after the target dies). \n#F20# \n#F40##L10#Wheels of Light: #L0#Special effect, 6 wheels of light correspond to the six-dimensional attributes. When applied, the corresponding base attributes of the target are permanently reduced (based on 8% of Hupa\'s six-dimensional base attributes, can be dispelled, and the upper limit per target is 3 stacks). When the wheels of light return, they permanently convert into their own attribute. \n#F20# \n#F40# Reduce #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# of the final damage you receive and transfer 150% of this damage to a random target in the enemy\'s front row, with 50% of your Physical Damage as the damage type.',
		describe_th = 'ก่อนแต่ละรอบใหญ่ ให้ระบุ [ล้อแห่งแสง] จำนวน 6 ลูกบนร่างกายของคุณอย่างสุ่มไปยังแถวหน้าของศัตรู และเรียกคืน [ล้อแห่งแสง] ทั้งหมดก่อนเทิร์นของคุณ (ฟื้นฟูทันทีหลังจากเป้าหมายตาย) \n#F20# \n#F40##L10#ล้อแห่งแสง: #L0#เอฟเฟกต์พิเศษ 6 ล้อแห่งแสงสอดคล้องกับคุณสมบัติหกมิติ เมื่อใช้แล้ว คุณสมบัติพื้นฐานที่เกี่ยวข้องของเป้าหมายจะลดลงอย่างถาวร (จาก 8% ของคุณสมบัติพื้นฐานหกมิติของฮูปา สามารถถูกล้างและขีดจำกัดสูงสุดของแต่ละเป้าหมายคือ 3 ชั้น) เมื่อล้อแห่งแสงกลับมา มันจะเปลี่ยนเป็นคุณสมบัติของมันเองอย่างถาวร \n#F20# \n#F40# ลด #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# ความเสียหายสุดท้ายที่คุณได้รับและส่งต่อความเสียหาย 150% นี้ไปยังเป้าหมายสุ่มในแถวหน้าของศัตรู โดยที่ความเสียหายเป็น 50% ของพลังโจมตีทางกายภาพของคุณ',
		describe_in = 'Sebelum setiap putaran besar, secara acak tetapkan 6 [Roda Cahaya] pada tubuh Anda ke baris depan musuh dan ambil kembali semua [Roda Cahaya] sebelum giliran Anda (pulih segera setelah target mati). \n#F20# \n#F40##L10#Roda Cahaya: #L0#Efek khusus, 6 roda cahaya sesuai dengan atribut enam dimensi. Ketika diterapkan, atribut dasar yang sesuai dari target akan berkurang secara permanen (dari 8% atribut dasar enam dimensi Hupa, dapat dihilangkan dan batas atas untuk satu target adalah 3 lapisan). Ketika roda cahaya kembali, mereka akan berubah permanen menjadi atributnya sendiri \n#F20# \n#F40# Kurangi #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# kerusakan akhir yang Anda terima dan alihkan 150% kerusakan ini ke target acak di baris depan musuh dengan 50% dari Damage Fisik Anda sebagai tipe kerusakan.',
		describe_ph = 'Bago ang bawat malaking round, random na italaga ang 6 na [Gulong ng Liwanag] sa iyong katawan sa harapang hanay ng kaaway at kunin muli lahat ng [Gulong ng Liwanag] bago ang iyong turn (agad na gumaling pagkatapos mamatay ang target). \n#F20# \n#F40##L10#Gulong ng Liwanag: #L0#Espesyal na epekto, ang 6 na gulong ng liwanag ay tumutugma sa anim na dimensional na katangian. Kapag inilapat, ang kaugnay na pangunahing katangian ng target ay permanente nang nababawasan (mula sa 8% ng anim na dimensional na pangunahing katangian ng Hupa, maaaring maalis at ang pinakamataas na limitasyon sa isang target ay 3 stacks). Kapag bumalik ang gulong ng liwanag, permanente itong nagiging sarili nitong katangian \n#F20# \n#F40# Bawasan ang #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# ng huling damage na natatanggap mo at ilipat ang 150% ng damage na ito sa isang random na target sa harapang hanay ng kalaban na may 50% ng iyong Physical Damage bilang damage type.',
		describe_ma = 'Sebelum setiap pusingan besar, tetapkan secara rawak 6 [Roda Cahaya] pada badan anda ke barisan hadapan musuh dan ambil semula semua [Roda Cahaya] sebelum giliran anda (pulih dengan segera selepas sasaran mati). \n#F20# \n#F40##L10#Roda Cahaya: #L0#Kesan khas, 6 roda cahaya sepadan dengan atribut enam dimensi. Apabila digunakan, atribut asas yang sepadan pada sasaran akan dikurangkan secara kekal (daripada 8% atribut asas enam dimensi Hupa, boleh dibersihkan dan had atas untuk satu sasaran adalah 3 lapisan). Apabila roda cahaya kembali, ia akan bertukar secara kekal kepada atributnya sendiri \n#F20# \n#F40# Kurangkan #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# kerosakan akhir yang anda terima dan alihkan 150% kerosakan ini kepada sasaran rawak di barisan hadapan musuh dengan 50% daripada Kerosakan Fizikal anda sebagai jenis kerosakan.',
		describe = 'Before each major round, randomly assign 6 [Wheels of Light] on your body to the front row of the enemy and retrieve all [Wheels of Light] before your turn (recover immediately after the target dies). \n#F20# \n#F40##L10#Wheels of Light: #L0#Special effect, 6 wheels of light correspond to the six-dimensional attributes. When applied, the corresponding base attributes of the target are permanently reduced (based on 8% of Hupa\'s six-dimensional base attributes, can be dispelled, and the upper limit per target is 3 stacks). When the wheels of light return, they permanently convert into their own attribute. \n#F20# \n#F40# Reduce #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# of the final damage you receive and transfer 150% of this damage to a random target in the enemy\'s front row, with 50% of your Physical Damage as the damage type.',
		starEffect = __data_t__starEffect[36426],
		-- {8}
		starEffectDesc_vn = 'Hiệu Ứng Bổ Sung: Khi vào trận, Hu Pa sẽ vươn tay ma quái để vĩnh viễn đánh cắp 10% giảm sát thương từ mỗi mục tiêu hàng đầu của kẻ thù (không thể bị giải tán), và chuyển đổi 10% giảm sát thương đã đánh cắp thành tăng sát thương trước khi tấn công.',
		starEffectDesc = 'Additional Effect: Upon entering the battle, Hu Pa will stretch out a ghostly hand to permanently steal 10% damage reduction from each of the enemy\'s top targets (cannot be dispelled), and convert the stolen 10% damage reduction into increased damage before attacking.',
		starEffectDesc_en = 'Additional Effect: Upon entering the battle, Hu Pa will stretch out a ghostly hand to permanently steal 10% damage reduction from each of the enemy\'s top targets (cannot be dispelled), and convert the stolen 10% damage reduction into increased damage before attacking.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อลงสนาม Hu Pa จะยืดมือผีสางเพื่อขโมยการลดความเสียหาย 10% จากแต่ละเป้าหมายชั้นนำของศัตรูอย่างถาวร (ไม่สามารถลบออกได้) และแปลงการลดความเสียหายที่ขโมยมา 10% นั้นเป็นการเพิ่มความเสียหายก่อนโจมตี',
		starEffectDesc_in = 'Efek Tambahan: Saat memasuki pertarungan, Hu Pa akan merentangkan tangan hantu untuk secara permanen mencuri 10% pengurangan kerusakan dari setiap target teratas musuh (tidak bisa dihapus), dan mengubah 10% pengurangan kerusakan yang dicuri menjadi peningkatan kerusakan sebelum menyerang.',
		starEffectDesc_ph = 'Karagdagang Epekto: Pagpasok sa laban, si Hu Pa ay maghahablot ng mahiwagang kamay upang permanenteng magnakaw ng 10% bawas-sakit mula sa bawat pangunahing target ng kalaban (hindi matatanggal), at gagawing 10% bawas-sakit na ninakaw ay pagtaas ng pinsala bago umatake.',
		starEffectDesc_ma = 'Kesan Tambahan: Apabila memasuki perlawanan, Hu Pa akan menghulurkan tangan hantu untuk mencuri secara kekal pengurangan kerosakan sebanyak 10% daripada setiap sasaran utama musuh (tidak boleh dibuang), dan menukar pengurangan kerosakan 10% yang dicuri itu menjadi peningkatan kerosakan sebelum menyerang.',
		zawakeEffect = __data_t__zawakeEffect[36426],
		-- {79004, 1}
		zawakeEffectDesc = 'Additional effect: When entering battle, Hoopa\'s demonic hand permanently steals 10% damage reduction from each enemy\'s front-line target (cannot be dispelled), before attacking converts 5% stolen damage reduction into 10% damage increase; each time the light ring returns to position, steals 20 energy points from the target',
		zawakeEffectDesc_en = 'Additional effect: When entering battle, Hoopa\'s demonic hand permanently steals 10% damage reduction from each enemy\'s front-line target (cannot be dispelled), before attacking converts 5% stolen damage reduction into 10% damage increase; each time the light ring returns to position, steals 20 energy points from the target',
		zawakeEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อเข้าสู่การต่อสู้ มือปีศาจของ Hoopa ขโมยการลดดาเมจ 10% อย่างถาวรจากเป้าหมายหน้ากองทัพของศัตรูแต่ละตัว (ไม่สามารถขจัดได้), ก่อนโจมตีจะแปลงการลดดาเมจที่ถูกขโมย 5% เป็นการเพิ่มดาเมจ 10%; ทุกครั้งที่วงแสงกลับสู่ตำแหน่ง จะขโมยพลังงาน 20 คะแนนจากเป้าหมาย',
		zawakeEffectDesc_in = 'Efek tambahan: Saat memasuki pertempuran, tangan iblis Hoopa secara permanen mencuri 10% pengurangan kerusakan dari setiap target barisan depan musuh (tidak dapat dibersihkan), sebelum menyerang mengubah 5% pengurangan kerusakan yang dicuri menjadi 10% peningkatan kerusakan; setiap kali cincin cahaya kembali ke posisi, mencuri 20 poin energi dari target',
		zawakeEffectDesc_ph = 'Karagdagang epekto: Kapag pumasok sa laban, ang demonyong kamay ni Hoopa ay permanenteng nagnanakaw ng 10% bawas sa pinsala mula sa bawat target sa harapang linya ng kalaban (hindi maaaring tanggalin), bago umatake ay nagko-convert ng 5% na nakawat na bawas sa pinsala sa 10% dagdag pinsala; bawat pagbalik ng ilaw na singsing sa posisyon, nagnanakaw ng 20 puntos na enerhiya mula sa target',
		zawakeEffectDesc_ma = 'Kesan tambahan: Apabila memasuki pertempuran, tangan iblis Hoopa secara kekal mencuri 10% pengurangan kerosakan daripada setiap sasaran barisan hadapan musuh (tidak boleh dibersihkan), sebelum menyerang menukarkan 5% pengurangan kerosakan yang dicuri menjadi 10% peningkatan kerosakan; setiap kali cincin cahaya kembali ke posisi, mencuri 20 mata tenaga daripada sasaran',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: Khi vào trận, Hoopa đưa tay ma quỷ vĩnh viễn đánh cắp 10% giảm sát thương của mỗi mục tiêu hàng trước của kẻ địch (không thể xua tan), trước khi tấn công sẽ chuyển đổi 5% giảm sát thương đã đánh cắp thành 10% tăng sát thương; mỗi khi vòng sáng trở về vị trí, đánh cắp 20 điểm nộ khí của mục tiêu',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'At battle start, Hoopa extends its demonic hand to permanently steal 10% damage reduction from each enemy front row target (cannot be removed); before attacking, converts 10% of the stolen reduction into bonus damage#F20# #F40##C0x5c9970#→At battle start, Hoopa extends its demonic hand to permanently steal 10% damage reduction from each enemy front row target (cannot be removed); before attacking, converts 5% of the stolen reduction into 10% bonus damage; each time Halo returns to position, it steals an additional 20 Rage',
		zawakeSimpleDesc_en = 'At battle start, Hoopa extends its demonic hand to permanently steal 10% damage reduction from each enemy front row target (cannot be removed); before attacking, converts 10% of the stolen reduction into bonus damage#F20# #F40##C0x5c9970#→At battle start, Hoopa extends its demonic hand to permanently steal 10% damage reduction from each enemy front row target (cannot be removed); before attacking, converts 5% of the stolen reduction into 10% bonus damage; each time Halo returns to position, it steals an additional 20 Rage',
		zawakeSimpleDesc_th = 'เมื่อเริ่มการต่อสู้ Hoopa จะยื่นมือปีศาจเพื่อขโมย 10% การลดความเสียหายของศัตรูแถวหน้า (ไม่สามารถลบได้); ก่อนโจมตี จะเปลี่ยน 10% ที่ขโมยเป็นโบนัสความเสียหาย#F20# #F40##C0x5c9970#→ก่อนโจมตีจะเปลี่ยน 5% ของที่ขโมยเป็นโบนัสความเสียหาย 10%; ทุกครั้งที่ Halo กลับสู่ตำแหน่ง จะขโมยเพิ่มอีก 20 โทสะ',
		zawakeSimpleDesc_in = 'Saat pertempuran dimulai, Hoopa mencuri permanen 10% pengurangan kerusakan dari musuh baris depan (tidak bisa dihapus); sebelum menyerang, mengubah 10% dari itu menjadi bonus damage#F20# #F40##C0x5c9970#→Sebelum menyerang, ubah 5% dari yang dicuri menjadi 10% bonus damage; setiap kali Halo kembali ke posisi, mencuri tambahan 20 Rage',
		zawakeSimpleDesc_ph = 'Sa simula ng laban, ninanakaw ni Hoopa ang 10% damage reduction ng kalaban sa harap (hindi matatanggal); bago umatake, gagawing bonus damage ang 10%#F20# #F40##C0x5c9970#→Gagawin lamang 5% ng ninakaw bilang 10% bonus damage; tuwing bumabalik si Halo, kukuha ng karagdagang 20 Rage',
		zawakeSimpleDesc_ma = 'Apabila pertempuran bermula, Hoopa mencuri secara kekal 10% pengurangan kerosakan daripada musuh barisan hadapan (tidak boleh dihapuskan); sebelum menyerang, tukar 10% daripada yang dicuri kepada kerosakan tambahan#F20# #F40##C0x5c9970#→Tukar 5% kepada 10% kerosakan tambahan; setiap kali Halo kembali ke posisi, mencuri 20 Mata Amarah tambahan',
		zawakeSimpleDesc_vn = 'Khi vào trận, Hoopa đưa tay ma quỷ ra cướp vĩnh viễn 10% giảm sát thương của mỗi mục tiêu hàng trước của kẻ địch (không thể xóa), trước khi tấn công sẽ chuyển đổi 10% giảm sát thương đã cướp thành tăng sát thương#F20# #F40##C0x5c9970#→Khi vào trận, Hoopa đưa tay ma quỷ ra cướp vĩnh viễn 10% giảm sát thương của mỗi mục tiêu hàng trước của kẻ địch (không thể xóa), trước khi tấn công sẽ chuyển đổi 5% giảm sát thương đã cướp thành 10% tăng sát thương; mỗi khi Vòng Sáng trở về vị trí, sẽ cướp thêm 20 điểm nộ khí của mục tiêu',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
