	[36441] = {
		id = 36441,
		skillName_vn = 'Chơi đùa',
		skillName_en = 'Play',
		skillName_th = 'เล่น',
		skillName_in = 'Bermain',
		skillName_ph = 'Maglaro',
		skillName_ma = 'Bermain',
		skillName = 'Play',
		describe_vn = 'Hoopa cưỡi thảm ma sử dụng vòng sáng để tấn công từ phía sau mục tiêu đơn của kẻ địch, gây #C0x3D8A99#100% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, tăng 15% Phép Công và 20% bỏ qua Phép Phòng của bản thân trong 2 lượt',
		describe_en = 'Hoopa rides a magic carpet using a ring of light to attack from behind a single enemy target, dealing #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, increasing own Magic Power by 15% and ignoring 20% of Magic Defense for 2 turns.',
		describe_th = 'ฮูปปาขี่พรมวิเศษใช้วงแหวนแสงโจมตีจากด้านหลังเป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0x3D8A99#100% พลังเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทย์มนตร์ #C0x5B545B# เพิ่มพลังเวทมนตร์ตัวเอง 15% และละเว้นการป้องกันเวทมนตร์ของศัตรู 20% เป็นเวลา 2 ตา',
		describe_in = 'Hoopa menunggangi karpet ajaib menggunakan cincin cahaya untuk menyerang dari belakang target musuh tunggal, memberikan #C0x3D8A99#100% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, meningkatkan Kekuatan Sihir sendiri sebesar 15% dan mengabaikan 20% Pertahanan Sihir selama 2 giliran.',
		describe_ph = 'Si Hoopa ay nakasakay sa magic carpet gamit ang singsing ng liwanag para umatake mula sa likod ng isang kalabang target ng kalaban, na nagdudulot ng #C0x3D8A99#100% Lakas ng Magic#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Pinsalang Magic #C0x5B545B#, nagpapataas ng sariling Lakas ng Magic ng 15% at nilalampasan ang 20% ng Depensa sa Magic sa loob ng 2 turn.',
		describe_ma = 'Hoopa menunggang karpet ajaib menggunakan cincin cahaya untuk menyerang dari belakang sasaran musuh tunggal, menyebabkan #C0x3D8A99#100% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, meningkatkan Kuasa Sihir sendiri sebanyak 15% dan mengabaikan 20% Pertahanan Sihir selama 2 pusingan.',
		describe = 'Hoopa rides a magic carpet using a ring of light to attack from behind a single enemy target, dealing #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, increasing own Magic Power by 15% and ignoring 20% of Magic Defense for 2 turns.',
		zawakeEffect = __data_t__zawakeEffect[36441],
		-- {79001}
		zawakeEffectDesc = 'Hoopa rides a magic carpet and uses a bright ring to attack the single enemy target from behind, dealing #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ magic damage#C0xF13B54#, increasing own Magic Power by 15% and magic penetration by 25% for 3 turns',
		zawakeEffectDesc_en = 'Hoopa rides a magic carpet and uses a bright ring to attack the single enemy target from behind, dealing #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ magic damage#C0xF13B54#, increasing own Magic Power by 15% and magic penetration by 25% for 3 turns',
