	[36443] = {
		id = 36443,
		skillName_vn = 'Máy đánh bạc không gian',
		skillName_en = 'Space slot machine',
		skillName_th = 'เครื่องสล็อตอวกาศ',
		skillName_in = 'Mesin slot ruang angkasa',
		skillName_ph = 'Space slot machine',
		skillName_ma = 'Mesin slot angkasa',
		skillName = 'Space slot machine',
		describe_vn = 'Hupa triệu hồi một máy đánh bạc không gian khác và rải một lượng lớn tiền vàng để tấn công mục tiêu ở hàng trước của kẻ địch, giảm vĩnh viễn mức giảm sát thương của hàng trước đi 15% (có thể chồng chất, không phân tán) và gây sát thương cho mục tiêu chính của kẻ địch (mục tiêu ưu tiên trong chiến đấu tự động). Vào #C0x3D8A99#420% Tấn Công Phép thuật#C0x5B545B# (Các mục tiêu còn lại ở hàng trước#C0x3D8A99#150% Tấn Công Phép thuật#C0x5B545B#)+$(ski llLevel*4*48)$\'s #C0xF13B54#Sát Thương Phép Thuật#C0x5B545B# sẽ [dịch chuyển] mục tiêu chính tới một không gian không gian khác cho đến sau hành động tiếp theo của Hupa và ghi lại lượng sát thương mà tất cả kẻ thù phải nhận trong khoảng thời gian đó. Khi mục tiêu bước ra khỏi bánh xe ánh sáng, nếu Hupa sống sót, [đòn tấn công khác chiều] sẽ được tung ra, khiến nó thiệt hại thực sự bằng 50% tổng giá trị ghi nhận và 100% đòn Sát Thương Vật Lý của chính nó\n#F20# \n#F40##L10#Teleport: #L0# Hiệu ứng khống chế, không thể xua tan, không thể tấn công hoặc bị đánh trong thời gian này, Hupa vẫn có thể tấn công mục tiêu',
		describe_en = 'Hupa summons another spatial slot machine and scatters a large amount of gold coins to attack the enemy\'s front row targets, permanently reducing the front row\'s damage reduction by 15% (stackable, non-dispellable) and damaging the enemy\'s primary target (priority target in auto combat). Deals #C0x3D8A99#420% Magic Attack#C0x5B545B# to the primary target (other front row targets take #C0x3D8A99#150% Magic Attack#C0x5B545B#) + $(skillLevel*4*48)$\'s #C0xF13B54#Magic Damage#C0x5B545B#. The primary target is then [teleported] to another space until after Hupa\'s next action, recording the damage all enemies take during this period. When the target exits the wheel of light, if Hupa is still alive, a [counterattack] is launched, dealing true damage equal to 50% of the recorded value and 100% of its own Physical Damage. \n#F20# \n#F40##L10#Teleport: #L0# Crowd control effect, cannot be dispelled, cannot attack or be attacked during this time, Hupa can still attack the target.',
		describe_th = 'ฮูปะเรียกเครื่องสล็อตอวกาศอีกเครื่องและโปรยเหรียญทองจำนวนมากเพื่อโจมตีเป้าหมายแถวหน้าของศัตรู ลดการลดความเสียหายของแถวหน้าอย่างถาวรลง 15% (สะสมได้ ไม่สามารถลบได้) และสร้างความเสียหายต่อเป้าหมายหลักของศัตรู (เป้าหมายสำคัญในการต่อสู้แบบอัตโนมัติ) สร้าง #C0x3D8A99#420% การโจมตีเวทมนตร์#C0x5B545B# (เป้าหมายอื่นในแถวหน้าสร้าง #C0x3D8A99#150% การโจมตีเวทมนตร์#C0x5B545B#) + $(skillLevel*4*48)$ #C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# โดยเป้าหมายหลักจะถูก [เคลื่อนย้าย] ไปยังอวกาศอื่นจนกว่าจะถึงการกระทำถัดไปของฮูปะ และบันทึกความเสียหายที่ศัตรูทั้งหมดได้รับในช่วงเวลานั้น เมื่อเป้าหมายออกจากวงแสง หากฮูปะยังมีชีวิตอยู่อีก [การโจมตีสวนกลับ] จะถูกปล่อยออกมา สร้างความเสียหายจริงเท่ากับ 50% ของค่าที่บันทึกไว้และ 100% ของความเสียหายทางกายภาพของตัวเอง \n#F20# \n#F40##L10#เทเลพอร์ต: #L0# เอฟเฟกต์ควบคุมฝูงชน ไม่สามารถลบได้ ไม่สามารถโจมตีหรือถูกโจมตีในช่วงเวลานี้ ฮูปะยังสามารถโจมตีเป้าหมายได้',
		describe_in = 'Hupa memanggil mesin slot ruang lain dan menyebarkan sejumlah besar koin emas untuk menyerang target barisan depan musuh, secara permanen mengurangi pengurangan kerusakan barisan depan sebesar 15% (dapat menumpuk, tidak dapat dibersihkan) dan memberikan kerusakan pada target utama musuh (target prioritas dalam pertarungan otomatis). Memberikan #C0x3D8A99#420% Serangan Magic#C0x5B545B# (target lain di barisan depan menerima #C0x3D8A99#150% Serangan Magic#C0x5B545B#) + $(skillLevel*4*48)$\'s #C0xF13B54#Kerusakan Magic#C0x5B545B#. Target utama kemudian [ditransfer] ke ruang lain sampai setelah aksi berikutnya Hupa, merekam kerusakan yang diterima semua musuh selama periode tersebut. Ketika target keluar dari roda cahaya, jika Hupa masih hidup, [serangan balik] akan diluncurkan, menyebabkan damage sejati sebesar 50% dari nilai yang direkam dan 100% dari Damage Fisiknya sendiri. \n#F20# \n#F40##L10#Teleportasi: #L0# Efek kontrol massa, tidak dapat dibersihkan, tidak dapat menyerang atau diserang selama waktu ini, Hupa masih dapat menyerang target.',
		describe_ph = 'Hupa ay nag-summon ng isa pang spatial slot machine at nagkalat ng maraming gintong pera para atakihin ang mga target sa harapang linya ng kalaban, permanenteng nagbabawas ng 15% sa pagbawas ng pinsala sa harapang linya (pwedeng mag-stack, hindi matatanggal) at nagdudulot ng pinsala sa pangunahing target ng kalaban (priority target sa auto combat). Nagdudulot ng #C0x3D8A99#420% Magic Attack#C0x5B545B# (ang iba pang target sa harapang linya ay makatatanggap ng #C0x3D8A99#150% Magic Attack#C0x5B545B#) + $(skillLevel*4*48)$\'s #C0xF13B54#Magic Damage#C0x5B545B#. Ang pangunahing target ay [itatransport] sa ibang espasyo hanggang matapos ang susunod na aksyon ni Hupa at maire-record ang damage na tatanggapin ng lahat ng kalaban sa panahong iyon. Kapag lumabas ang target mula sa wheel of light, kung buhay pa si Hupa, maglalabas siya ng [counterattack], na magdudulot ng true damage na katumbas ng 50% ng narecord na damage at 100% ng sarili nitong Physical Damage. \n#F20# \n#F40##L10#Teleport: #L0# Crowd control effect, hindi matatanggal, hindi pwedeng umatake o maatake sa panahong ito, pero kayang umatake ni Hupa ang target.',
		describe_ma = 'Hupa memanggil mesin slot ruang lain dan menaburkan sejumlah besar syiling emas untuk menyerang sasaran barisan hadapan musuh, secara kekal mengurangkan pengurangan kerosakan barisan hadapan sebanyak 15% (boleh bertindan, tidak boleh dibersihkan) dan menyebabkan kerosakan kepada sasaran utama musuh (sasaran keutamaan dalam pertempuran automatik). Memberikan #C0x3D8A99#420% Serangan Sihir#C0x5B545B# (sasaran lain di barisan hadapan #C0x3D8A99#150% Serangan Sihir#C0x5B545B#) + $(skillLevel*4*48)$ #C0xF13B54#Kerosakan Sihir#C0x5B545B#. Sasaran utama kemudian [berpindah] ke ruang lain sehingga selepas tindakan Hupa yang seterusnya dan merekodkan jumlah kerosakan yang semua musuh terima dalam tempoh tersebut. Apabila sasaran keluar dari roda cahaya, jika Hupa masih hidup, [serangan balas] akan dilancarkan, menyebabkan kerosakan benar sebanyak 50% daripada jumlah yang direkodkan dan 100% daripada Kerosakan Fizikalnya sendiri. \n#F20# \n#F40##L10#Teleport: #L0# Kesan kawalan massa, tidak boleh dibersihkan, tidak boleh menyerang atau diserang dalam tempoh ini, Hupa masih boleh menyerang sasaran.',
		describe = 'Hupa summons another spatial slot machine and scatters a large amount of gold coins to attack the enemy\'s front row targets, permanently reducing the front row\'s damage reduction by 15% (stackable, non-dispellable) and damaging the enemy\'s primary target (priority target in auto combat). Deals #C0x3D8A99#420% Magic Attack#C0x5B545B# to the primary target (other front row targets take #C0x3D8A99#150% Magic Attack#C0x5B545B#) + $(skillLevel*4*48)$\'s #C0xF13B54#Magic Damage#C0x5B545B#. The primary target is then [teleported] to another space until after Hupa\'s next action, recording the damage all enemies take during this period. When the target exits the wheel of light, if Hupa is still alive, a [counterattack] is launched, dealing true damage equal to 50% of the recorded value and 100% of its own Physical Damage. \n#F20# \n#F40##L10#Teleport: #L0# Crowd control effect, cannot be dispelled, cannot attack or be attacked during this time, Hupa can still attack the target.',
		simDesc_vn = 'Hupa điều khiển 6 bàn tay ma quái, sử dụng vòng ánh sáng tấn công không gian vào mục tiêu ở hàng trước, giảm vĩnh viễn khả năng giảm sát thương của mục tiêu, sau đó chuyển mục tiêu chính vào không gian khác, và khi mục tiêu trở về, thực hiện đòn tấn công không gian.',
		simDesc_en = 'Hupa controls six ghostly hands, using a ring of light to launch a spatial attack on the front-row target, permanently reducing the target\'s damage reduction ability. Then, it shifts the main target into another space, and when the target returns, it performs a spatial strike.',
		simDesc_th = 'ฮูปาควบคุมมือผี 6 ข้าง ใช้วงแหวนแสงโจมตีช่องว่างไปยังเป้าหมายแถวหน้า ลดความสามารถการลดความเสียหายของเป้าหมายอย่างถาวร จากนั้นย้ายเป้าหมายหลักไปยังมิติอื่น และเมื่อเป้าหมายกลับมา จะทำการโจมตีช่องว่าง',
		simDesc_in = 'Hupa mengendalikan 6 tangan hantu, menggunakan cincin cahaya untuk menyerang ruang pada target di barisan depan, secara permanen mengurangi kemampuan pengurangan kerusakan target. Kemudian mengalihkan target utama ke ruang lain, dan saat target kembali, melakukan serangan ruang.',
		simDesc_ph = 'Kinokontrol ni Hupa ang anim na espirituwal na kamay, gamit ang singsing ng liwanag para umatake ng espasyo sa layunin sa unahang hanay, pababain nang permanente ang kakayahan ng layunin na bawasan ang pinsala. Pagkatapos, ililipat ang pangunahing layunin sa ibang espasyo, at kapag bumalik ang layunin, isasagawa ang pag-atake sa espasyo.',
		simDesc_ma = 'Hupa mengawal 6 tangan ghaib, menggunakan cincin cahaya untuk menyerang ruang ke sasaran di barisan hadapan, mengurangkan secara kekal keupayaan sasaran untuk mengurangkan kerosakan. Kemudian memindahkan sasaran utama ke ruang lain, dan apabila sasaran kembali, melaksanakan serangan ruang.',
		simDesc = 'Hupa controls six ghostly hands, using a ring of light to launch a spatial attack on the front-row target, permanently reducing the target\'s damage reduction ability. Then, it shifts the main target into another space, and when the target returns, it performs a spatial strike.',
		starEffect = __data_t__starEffect[36443],
		-- {11}
		starEffectDesc_vn = 'Đánh Bại Dị Thế: Gây thêm 30% sát thương thật dựa trên giới hạn máu của mục tiêu.',
		starEffectDesc = 'Defeat the Different World: Deals an additional 30% true damage based on the target\'s health limit.',
		starEffectDesc_en = 'Defeat the Different World: Deals an additional 30% true damage based on the target\'s health limit.',
		starEffectDesc_th = 'ปราบความแตกต่าง: สร้างความเสียหายจริงเพิ่มขึ้น 30% โดยขึ้นอยู่กับขีดจำกัดพลังชีวิตของเป้าหมาย',
		starEffectDesc_in = 'Kalahkan Dunia Lain: Memberikan tambahan 30% kerusakan nyata berdasarkan batas kesehatan target.',
		starEffectDesc_ph = 'Talunin ang Ibang Mundo: Nagdudulot ng karagdagang 30% totoong pinsala batay sa limitasyon ng kalusugan ng target.',
		starEffectDesc_ma = 'Kalahkan Dunia Berbeza: Menyebabkan tambahan 30% kerosakan sebenar berdasarkan had kesihatan sasaran.',
		zawakeEffect = __data_t__zawakeEffect[36443],
		-- {79003, 1}
		zawakeEffectDesc = 'Enhance effect: Damage from other spatial attacks increases by 20%, and adds true damage equal to 30% of the target\'s health limit. If the other spatial attack does not kill the target, it will add 300 rage points to the target.',
		zawakeEffectDesc_en = 'Enhance effect: Damage from other spatial attacks increases by 20%, and adds true damage equal to 30% of the target\'s health limit. If the other spatial attack does not kill the target, it will add 300 rage points to the target.',
		zawakeEffectDesc_th = 'เพิ่มประสิทธิภาพ: ความเสียหายจากการโจมตีช่องว่างอื่นเพิ่มขึ้น 20% และเพิ่มความเสียหายจริงเป็น 30% ของขีดจำกัดสุขภาพของเป้าหมาย หากการโจมตีช่องว่างอื่นไม่ฆ่าเป้าหมาย จะเพิ่มพลังโกรธ 300 แต้มให้กับเป้าหมาย',
		zawakeEffectDesc_in = 'Tingkatkan efektivitas: Kerusakan serangan ruang lain meningkat 20%, dan menambahkan kerusakan nyata sebesar 30% dari batas kesehatan target. Jika serangan ruang lain tidak membunuh target, maka akan menambahkan 300 poin kemarahan pada target.',
		zawakeEffectDesc_ph = 'Palakasin ang epekto: Ang pinsala mula sa ibang spatial attack ay tumataas ng 20%, at magdadagdag ng totoong pinsala na katumbas ng 30% ng health limit ng target. Kung ang ibang spatial attack ay hindi makapatay sa target, magdadagdag ito ng 300 rage points sa target.',
		zawakeEffectDesc_ma = 'Tingkatkan keberkesanan: Kerosakan daripada serangan ruang lain meningkat sebanyak 20%, dan menambah kerosakan sebenar sebanyak 30% had kesihatan sasaran. Jika serangan ruang lain tidak membunuh sasaran, ia akan menambah 300 mata kemarahan pada sasaran.',
		zawakeEffectDesc_vn = 'Tăng cường hiệu quả: Sát thương đòn đánh không gian khác tăng 20%, và thêm sát thương thực bằng 30% giới hạn sinh mệnh của mục tiêu, nếu đòn đánh không gian khác không giết chết mục tiêu, sẽ thêm 300 điểm nộ khí của mục tiêu',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Otherworldly Attack adds true damage equal to 30% of the target’s max HP#F20# #F40##C0x5c9970#→Otherworldly Attack damage increases by 20%, and adds true damage equal to 30% of the target’s max HP; if it doesn\'t kill, it steals an additional 300 Rage from the target  ',
		zawakeSimpleDesc_en = 'Otherworldly Attack adds true damage equal to 30% of the target’s max HP#F20# #F40##C0x5c9970#→Otherworldly Attack damage increases by 20%, and adds true damage equal to 30% of the target’s max HP; if it doesn\'t kill, it steals an additional 300 Rage from the target  ',
		zawakeSimpleDesc_th = 'การโจมตีจากโลกอื่นสร้างความเสียหายจริงเท่ากับ 30% ของ HP สูงสุดของเป้าหมาย#F20# #F40##C0x5c9970#→ความเสียหายของการโจมตีจากโลกอื่นเพิ่มขึ้น 20% และเพิ่มความเสียหายจริง 30% ของ HP สูงสุด; ถ้าไม่ตาย จะขโมยเพิ่มอีก 300 โทสะ',
		zawakeSimpleDesc_in = 'Serangan Dunia Lain memberikan true damage sebesar 30% dari HP maksimum target#F20# #F40##C0x5c9970#→Serangan Dunia Lain memberikan 20% damage tambahan dan true damage 30% HP maksimum target; jika tidak membunuh, akan mencuri 300 Rage tambahan  ',
		zawakeSimpleDesc_ph = 'Ang Attack mula sa Ibang Daigdig ay nagdadagdag ng true damage na 30% ng max HP ng target#F20# #F40##C0x5c9970#→Damage ng Attack +20%, dagdag true damage na 30% ng max HP; kung hindi mapatay, mananakaw ng 300 Rage  ',
		zawakeSimpleDesc_ma = 'Serangan Dunia Lain menambah kerosakan sebenar sebanyak 30% daripada HP maksimum sasaran#F20# #F40##C0x5c9970#→Kerosakan Serangan Dunia Lain meningkat 20% dan menambah kerosakan sebenar sebanyak 30% daripada HP maksimum; jika tidak membunuh, akan mencuri 300 Mata Amarah tambahan  ',
		zawakeSimpleDesc_vn = 'Đòn tấn công Dị Thế Giới thêm sát thương thực bằng 30% giới hạn máu của mục tiêu#F20# #F40##C0x5c9970#→Sát thương của Đòn tấn công Dị Thế Giới tăng 20%, và thêm sát thương thực bằng 30% giới hạn máu của mục tiêu, nếu Đòn tấn công Dị Thế Giới không tiêu diệt mục tiêu, sẽ cướp thêm 300 điểm nộ khí của mục tiêu',
		upLvDesc = 'Fixed damage +192',
