	[36446] = {
		id = 36446,
		skillName_vn = 'Giải phóng vòng ánh sáng',
		skillName_en = 'Release the ring of light',
		skillName_th = 'ปลดปล่อยวงแหวนแห่งแสง',
		skillName_in = 'Melepaskan cincin cahaya',
		skillName_ph = 'Palayain ang singsing ng liwanag',
		skillName_ma = 'Melepaskan cincin cahaya',
		skillName = 'Release the ring of light',
		describe_vn = 'Trước mỗi vòng lớn, chỉ định ngẫu nhiên 6 [Bánh xe Ánh sáng] trên cơ thể của bạn cho hàng đầu của kẻ địch và lấy lại tất cả [Bánh xe Ánh sáng] trước lượt của mình (hồi phục ngay sau khi mục tiêu chết)\n#F20# \n#F40##L10#Bánh xe Ánh sáng: #L0#Hiệu ứng đặc biệt, 6 bánh xe ánh sáng tương ứng với thuộc tính sáu chiều. Khi được áp dụng, các thuộc tính cơ bản tương ứng của mục tiêu sẽ bị giảm vĩnh viễn (từ 8% thuộc tính sáu chiều cơ bản của Hupa, có thể bị xua tan và giới hạn trên của một mục tiêu là 3 lớp). Khi bánh xe ánh sáng quay trở lại, nó sẽ vĩnh viễn chuyển thành thuộc tính của chính nó\n#F20# \n#F40# Giảm #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# sát thương cuối cùng mà bạn nhận được và chuyển 150% sát thương này sang một mục tiêu ngẫu nhiên ở hàng đầu của kẻ địch với 50% đòn Sát Thương Vật Lý của chính bạn là sát thương chuẩn',
		describe_en = 'Before each major round, randomly assign 6 [Wheels of Light] on your body to the front row of the enemy, and recover all [Wheels of Light] before your turn (immediately recovered after the target dies) \n#F20# \n#F40##L10#Wheels of Light: #L0#Special effect, 6 wheels of light correspond to the six-dimensional attributes. When applied, the corresponding basic attributes of the target will be permanently reduced (starting from 8% of Hupa\'s six-dimensional basic attributes, can be dispelled, the upper limit on one target is 3 layers). When the wheels of light return, they permanently convert into their own attribute \n#F20# \n#F40# Reduce #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# of the final damage you receive and redirect 150% of this damage to a random target in the enemy front row with 50% of your Physical Damage as standard damage.',
		describe_th = 'ก่อนเริ่มแต่ละรอบใหญ่ สุ่มกำหนด 6 [ล้อแห่งแสง] บนร่างกายของคุณไปยังแถวหน้า ของศัตรู และกู้คืน [ล้อแห่งแสง] ทั้งหมดก่อนตาของคุณ (ฟื้นฟูทันทีหลังเป้าหมายตาย) \n#F20# \n#F40##L10#ล้อแห่งแสง: #L0#เอฟเฟกต์พิเศษ, ล้อแห่งแสง 6 ล้อสอดคล้องกับคุณสมบัติหกมิติ เมื่อถูกใช้งาน คุณสมบัติพื้นฐานที่เกี่ยวข้องของเป้าหมายจะถูกลดอย่างถาวร (เริ่มที่ 8% ของคุณสมบัติหกมิติพื้นฐานของ Hupa สามารถถูกลบออกได้ และขีดจำกัดสูงสุดของเป้าหมายหนึ่งคือ 3 ชั้น) เมื่อ ล้อแห่งแสง กลับคืนมา จะเปลี่ยนเป็นคุณสมบัติของตนเองอย่างถาวร \n#F20# \n#F40# ลด #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# ของความเสียหายขั้นสุดท้ายที่คุณได้รับและส่งต่อความเสียหาย 150% นี้ไปยังเป้าหมายแบบสุ่มในแถวหน้าของศัตรูโดยใช้ความเสียหายทางกายภาพของคุณ 50% เป็นความเสียหายมาตรฐาน',
		describe_in = 'Sebelum setiap babak besar, tetapkan secara acak 6 [Roda Cahaya] pada tubuh Anda ke baris depan musuh, dan pulihkan semua [Roda Cahaya] sebelum giliran Anda (pulih segera setelah target mati) \n#F20# \n#F40##L10#Roda Cahaya: #L0#Efek khusus, 6 roda cahaya sesuai dengan atribut enam dimensi. Saat diterapkan, atribut dasar yang sesuai dari target akan berkurang secara permanen (dari 8% atribut dasar enam dimensi Hupa, dapat dihilangkan, batas atas untuk satu target adalah 3 lapisan). Ketika roda cahaya kembali, mereka akan secara permanen berubah menjadi atribut mereka sendiri \n#F20# \n#F40# Kurangi #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# dari kerusakan akhir yang Anda terima dan alihkan 150% kerusakan ini ke target acak di baris depan musuh dengan 50% dari Kerusakan Fisik Anda sebagai kerusakan standar.',
		describe_ph = 'Bago ang bawat malaking round, random na itatalaga ang 6 [Mga Gulong ng Liwanag] sa iyong katawan sa frontline ng kalaban at mababawi ang lahat ng [Mga Gulong ng Liwanag] bago ang iyong turn (mabilis na mababawi pagkatapos mamatay ang target) \n#F20# \n#F40##L10#Mga Gulong ng Liwanag: #L0#Espesyal na epekto, ang 6 na gulong ng liwanag ay tumutukoy sa anim na dimenyong katangian. Kapag naipasa, ang kaukulang pangunahing katangian ng target ay permanenteng mababawasan (mula sa 8% ng anim na dimensyong pangunahing katangian ng Hupa, maaaring maalis at ang pinakamataas na limitasyon sa isang target ay 3 layers). Kapag bumalik ang mga gulong ng liwanag, permanenteng ito ay magiging sariling katangian \n#F20# \n#F40# Bawasan ang #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# ng pinakahuling pinsalang natanggap mo at ilipat ang 150% ng pinsalang ito sa isang random na target sa frontline ng kalaban gamit ang 50% ng iyong Pisikal na Pinsala bilang karaniwang pinsala.',
		describe_ma = 'Sebelum setiap pusingan besar, secara rawak tetapkan 6 [Roda Cahaya] pada badan anda ke barisan hadapan musuh, dan pulihkan semua [Roda Cahaya] sebelum giliran anda (pulih serta-merta selepas sasaran mati) \n#F20# \n#F40##L10#Roda Cahaya: #L0#Kesan khas, 6 roda cahaya sepadan dengan atribut enam dimensi. Apabila diaplikasikan, atribut asas yang sepadan pada sasaran akan dikurangkan secara kekal (dari 8% atribut asas enam dimensi Hupa, boleh dihapuskan, had atas untuk satu sasaran adalah 3 lapisan). Apabila roda cahaya kembali, ia akan bertukar secara kekal menjadi atribut sendiri \n#F20# \n#F40# Kurangkan #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# daripada kerosakan terakhir yang anda terima dan alihkan 150% kerosakan ini kepada sasaran rawak di barisan hadapan musuh dengan 50% Kerosakan Fizikal anda sebagai kerosakan standard.',
		describe = 'Before each major round, randomly assign 6 [Wheels of Light] on your body to the front row of the enemy, and recover all [Wheels of Light] before your turn (immediately recovered after the target dies) \n#F20# \n#F40##L10#Wheels of Light: #L0#Special effect, 6 wheels of light correspond to the six-dimensional attributes. When applied, the corresponding basic attributes of the target will be permanently reduced (starting from 8% of Hupa\'s six-dimensional basic attributes, can be dispelled, the upper limit on one target is 3 layers). When the wheels of light return, they permanently convert into their own attribute \n#F20# \n#F40# Reduce #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# of the final damage you receive and redirect 150% of this damage to a random target in the enemy front row with 50% of your Physical Damage as standard damage.',
		starEffect = __data_t__starEffect[36446],
		-- {8}
		starEffectDesc_vn = 'Hiệu Ứng Bổ Sung: Khi vào trận, Hu Pa sẽ vươn tay ma quái để vĩnh viễn đánh cắp 10% giảm sát thương từ mỗi mục tiêu hàng đầu của kẻ thù (không thể bị giải tán), và chuyển đổi 10% giảm sát thương đã đánh cắp thành tăng sát thương trước khi tấn công.',
		starEffectDesc = 'Additional Effect: When entering the battle, Hu Pa will stretch out a ghostly hand to permanently steal 10% damage reduction from each of the enemy\'s top targets (cannot be dispelled), and convert the stolen 10% damage reduction into increased damage before attacking.',
		starEffectDesc_en = 'Additional Effect: When entering the battle, Hu Pa will stretch out a ghostly hand to permanently steal 10% damage reduction from each of the enemy\'s top targets (cannot be dispelled), and convert the stolen 10% damage reduction into increased damage before attacking.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อเข้าสู่การต่อสู้ Hu Pa จะยื่นมือร่างผีเพื่อขโมยการลดความเสียหาย 10% จากเป้าหมายชั้นนำของศัตรูแต่ละตัวอย่างถาวร (ไม่สามารถลบล้างได้) และเปลี่ยนการลดความเสียหาย 10% ที่ถูกขโมยมาเป็นการเพิ่มความเสียหายก่อนโจมตี',
		starEffectDesc_in = 'Efek Tambahan: Saat memasuki pertarungan, Hu Pa akan mengulurkan tangan hantu untuk secara permanen mencuri pengurangan kerusakan 10% dari setiap target teratas musuh (tidak dapat dihapus), dan mengubah pengurangan kerusakan 10% yang dicuri menjadi peningkatan kerusakan sebelum menyerang.',
		starEffectDesc_ph = 'Karagdagang Epekto: Kapag pumapasok sa laban, iaabot ni Hu Pa ang isang mahiwagang kamay upang permanenteng nakawin ang 10% bawas sa pinsala mula sa bawat nangungunang target ng kalaban (hindi maaaring alisin), at i-convert ang nakaw na 10% bawas sa pinsala bilang dagdag na pinsala bago umatake.',
		starEffectDesc_ma = 'Kesan Tambahan: Apabila memasuki pertempuran, Hu Pa akan menghulurkan tangan ghaib untuk mencuri secara kekal 10% pengurangan kerosakan dari setiap sasaran teratas musuh (tidak boleh dibatalkan), dan menukar 10% pengurangan kerosakan yang dicuri menjadi peningkatan kerosakan sebelum menyerang.',
		zawakeEffect = __data_t__zawakeEffect[36446],
		-- {79004, 1}
		zawakeEffectDesc = 'Additional effect: When entering the battle, Hoopa permanently steals 10% damage reduction from each front row enemy target\'s demonic hand (cannot be dispelled), before attacking converts 5% stolen damage reduction into 10% damage increase; each time the light ring returns to position, steals 20 energy points from the target',
		zawakeEffectDesc_en = 'Additional effect: When entering the battle, Hoopa permanently steals 10% damage reduction from each front row enemy target\'s demonic hand (cannot be dispelled), before attacking converts 5% stolen damage reduction into 10% damage increase; each time the light ring returns to position, steals 20 energy points from the target',
		zawakeEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อเข้าสู่การต่อสู้ Hoopa ใช้มือปีศาจขโมยการลดความเสียหาย 10% จากเป้าหมายแถวหน้าของศัตรูแต่ละตัวอย่างถาวร (ไม่สามารถกำจัดได้) ก่อนโจมตีจะเปลี่ยนการลดความเสียหายที่ถูกขโมย 5% เป็นการเพิ่มความเสียหาย 10%; ทุกครั้งที่วงแสงกลับสู่ตำแหน่ง จะขโมยพลังงาน 20 คะแนนจากเป้าหมาย',
		zawakeEffectDesc_in = 'Efek tambahan: Saat memasuki pertarungan, Hoopa menggunakan tangan iblis untuk mencuri secara permanen pengurangan 10% kerusakan dari setiap target baris depan musuh (tidak dapat dihapus), sebelum menyerang mengubah 5% pengurangan kerusakan yang dicuri menjadi peningkatan 10% kerusakan; setiap kali cincin cahaya kembali ke posisi, mencuri 20 poin energi dari target',
		zawakeEffectDesc_ph = 'Karagdagang epekto: Kapag pumasok sa laban, palagiang nagnanakaw si Hoopa ng 10% bawas sa pinsala mula sa kamay ng demonyo ng bawat target sa unahang hanay ng kalaban (hindi maaaring tanggalin), bago umatake ay nagbabago ng 5% na nagnakaw na bawas sa pinsala sa 10% pagtaas ng pinsala; sa tuwing babalik sa posisyon ang liwanag na singsing, nagnanakaw ng 20 puntos ng enerhiya mula sa target',
		zawakeEffectDesc_ma = 'Kesan tambahan: Apabila memasuki pertempuran, Hoopa menggunakan tangan syaitan untuk mencuri 10% pengurangan kerosakan secara kekal daripada setiap sasaran barisan hadapan musuh (tidak boleh dibersihkan), sebelum menyerang menukar 5% pengurangan kerosakan yang dicuri menjadi peningkatan 10% kerosakan; setiap kali cincin cahaya kembali ke posisi, mencuri 20 mata tenaga daripada sasaran',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: Khi vào trận, Hoopa đưa tay ma quỷ vĩnh viễn đánh cắp 10% giảm sát thương của mỗi mục tiêu hàng trước của kẻ địch (không thể xua tan), trước khi tấn công sẽ chuyển đổi 5% giảm sát thương đã đánh cắp thành 10% tăng sát thương; mỗi khi vòng sáng trở về vị trí, đánh cắp 20 điểm nộ khí của mục tiêu',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'At the start of battle, Hoopa extends its demonic hand to permanently steal 10% damage reduction from each enemy front-row target (cannot be removed); before attacking, converts 10% of the stolen reduction into bonus damage#F20# #F40##C0x5c9970#→At the start of battle, Hoopa extends its demonic hand to permanently steal 10% damage reduction from each enemy front-row target (cannot be removed); before attacking, converts 5% of the stolen reduction into 10% bonus damage; each time the Halo returns to position, steals an additional 20 Rage from the target  ',
		zawakeSimpleDesc_en = 'At the start of battle, Hoopa extends its demonic hand to permanently steal 10% damage reduction from each enemy front-row target (cannot be removed); before attacking, converts 10% of the stolen reduction into bonus damage#F20# #F40##C0x5c9970#→At the start of battle, Hoopa extends its demonic hand to permanently steal 10% damage reduction from each enemy front-row target (cannot be removed); before attacking, converts 5% of the stolen reduction into 10% bonus damage; each time the Halo returns to position, steals an additional 20 Rage from the target  ',
		zawakeSimpleDesc_th = 'เมื่อเริ่มการต่อสู้ Hoopa ยื่นมือปีศาจเพื่อขโมย 10% การลดความเสียหายของศัตรูแถวหน้าแบบถาวร (ไม่สามารถลบได้); ก่อนโจมตี จะเปลี่ยน 10% ที่ขโมยเป็นโบนัสความเสียหาย#F20# #F40##C0x5c9970#→เมื่อเริ่มการต่อสู้ Hoopa ยื่นมือปีศาจเพื่อขโมย 10% การลดความเสียหายของศัตรูแถวหน้าแบบถาวร (ไม่สามารถลบได้); ก่อนโจมตี เปลี่ยน 5% ที่ขโมยเป็นโบนัสความเสียหาย 10%; ทุกครั้งที่ Halo กลับตำแหน่ง จะขโมยเพิ่มอีก 20 โทสะ',
		zawakeSimpleDesc_in = 'Saat pertempuran dimulai, Hoopa mencuri permanen 10% pengurangan kerusakan dari setiap musuh baris depan (tidak bisa dihapus); sebelum menyerang, mengubah 10% yang dicuri menjadi damage tambahan#F20# #F40##C0x5c9970#→Saat pertempuran dimulai, Hoopa mencuri permanen 10% pengurangan kerusakan dari setiap musuh baris depan (tidak bisa dihapus); sebelum menyerang, mengubah 5% dari itu menjadi 10% damage tambahan; setiap kali Halo kembali ke posisi, mencuri 20 Rage tambahan  ',
		zawakeSimpleDesc_ph = 'Sa simula ng laban, ninanakaw ni Hoopa ang 10% bawas pinsala mula sa bawat kalaban sa harap (hindi matatanggal); bago umatake, ginagawa niyang dagdag pinsala ang 10% nito#F20# #F40##C0x5c9970#→Sa simula ng laban, ninanakaw ni Hoopa ang 10% bawas pinsala mula sa bawat kalaban sa harap (hindi matatanggal); bago umatake, ginagawa niyang 10% dagdag pinsala mula sa 5% ninakaw; tuwing bumabalik ang Halo, kukuha pa ng 20 Rage  ',
		zawakeSimpleDesc_ma = 'Apabila pertempuran bermula, Hoopa mencuri secara kekal 10% pengurangan kerosakan dari setiap musuh barisan hadapan (tidak boleh dihapuskan); sebelum menyerang, menukar 10% itu menjadi kerosakan tambahan#F20# #F40##C0x5c9970#→Apabila pertempuran bermula, Hoopa mencuri secara kekal 10% pengurangan kerosakan dari setiap musuh barisan hadapan (tidak boleh dihapuskan); sebelum menyerang, menukar 5% menjadi 10% kerosakan tambahan; setiap kali Halo kembali ke posisi, mencuri lagi 20 Mata Amarah  ',
		zawakeSimpleDesc_vn = 'Khi vào trận, Hoopa đưa tay ma quỷ ra cướp vĩnh viễn 10% giảm sát thương của mỗi mục tiêu hàng trước của kẻ địch (không thể xóa), trước khi tấn công sẽ chuyển đổi 10% giảm sát thương đã cướp thành tăng sát thương#F20# #F40##C0x5c9970#→Khi vào trận, Hoopa đưa tay ma quỷ ra cướp vĩnh viễn 10% giảm sát thương của mỗi mục tiêu hàng trước của kẻ địch (không thể xóa), trước khi tấn công sẽ chuyển đổi 5% giảm sát thương đã cướp thành 10% tăng sát thương; mỗi khi Vòng Sáng trở về vị trí, sẽ cướp thêm 20 điểm nộ khí của mục tiêu',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
