	[36611] = {
		id = 36611,
		skillName_vn = 'Lông vũ lưỡi dao',
		skillName_en = 'Feather blade',
		skillName_th = 'ขนนกมีด',
		skillName_in = 'Pisau bulu',
		skillName_ph = 'Feather blade',
		skillName_ma = 'Bilah bulu',
		skillName = 'Feather blade',
		describe_vn = 'Cú mèo bay lên trời, bắn ra những chiếc lông sắc như dao cạo vào mục tiêu đơn lẻ của kẻ địch, gây #C0xE69900#100% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ Sát Thương Vật Lý#C0xF13B54# và tăng 20% sát thương chí mạng của bản thân trong 3 lượt',
		describe_en = 'The flying cat strike shoots razor-sharp feathers at a single enemy target, dealing #C0xE69900#100% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ Physical Damage#C0xF13B54# and increases own critical damage by 20% for 3 turns.',
		describe_th = 'หมัดแมวบินขึ้นฟ้า ยิงขนนกคมเหมือนใบมีดโกนใส่เป้าหมายศัตรูเดี่ยว ก่อให้เกิด #C0xE69900#100% การโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ ความเสียหายทางกายภาพ#C0xF13B54# และเพิ่มความเสียหายคริติคอลของตัวเอง 20% เป็นเวลา 3 เทิร์น',
		describe_in = 'Serangan kucing terbang ke langit, menembakkan bulu tajam seperti pisau cukur ke satu target musuh, menyebabkan #C0xE69900#100% Serangan Fisik#C0x5B545B#+$(skillLevel*4*24)$ Kerusakan Fisik#C0xF13B54# dan meningkatkan 20% kerusakan kritis diri sendiri selama 3 giliran.',
		describe_ph = 'Ang paglipad ng pusa patungo sa langit, nagpapaputok ng mga balahibo na matalim na parang labaha sa iisang target ng kaaway, nagdudulot ng #C0xE69900#100% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*24)$ Pisikal na Pinsala#C0xF13B54# at nagpapataas ng 20% sariling kritikal na pinsala sa loob ng 3 mga turn.',
		describe_ma = 'Serangan kucing terbang ke langit, melepaskan bulu tajam seperti pisau cukur kepada sasaran musuh tunggal, menyebabkan #C0xE69900#100% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ Kerosakan Fizikal#C0xF13B54# dan meningkatkan 20% kerosakan kritikal sendiri selama 3 pusingan.',
		describe = 'The flying cat strike shoots razor-sharp feathers at a single enemy target, dealing #C0xE69900#100% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ Physical Damage#C0xF13B54# and increases own critical damage by 20% for 3 turns.',
		simDesc_vn = 'Mộc Mộc Ưng bay lên không trung, bắn ra những chiếc lông sắc như dao về phía mục tiêu đơn lẻ của kẻ thù.',
		simDesc_en = 'Mộc Mộc Eagle soars into the sky, shooting sharp feathers like knives towards the enemy\'s single target.',
		simDesc_th = 'ม็อก ม็อก อีเกิลบินขึ้นสู่ท้องฟ้า ยิงขนที่คมดั่งมีดไปยังเป้าหมายเดี่ยวของศัตรู',
		simDesc_in = 'Elang Mộc Mộc terbang ke udara, menembakkan bulu tajam seperti pisau ke arah target tunggal musuh.',
