	[36733] = {
		id = 36733,
		skillName_vn = 'Đạn cháy',
		skillName_en = 'Burning bullet',
		skillName_th = 'กระสุนลุกไหม้',
		skillName_in = 'Peluru terbakar',
		skillName_ph = 'Nabarang bala',
		skillName_ma = 'Peluru terbakar',
		skillName = 'Burning bullet',
		describe_vn = 'Beerus hóa thân hỏa diễm lưu quang cũng ném nóng rực đạn công kích địch quân toàn thể, gây #C0xE69900#280% Vật công #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, đồng tiến nhập trạng thái Bùng Cháy 2 Hiệp, đồng thời hồi phục tự thân 30% Lớn nhất HP lượng máu ( Phe bạn cái khác Hỏa hệ khôi phục tự thân 15% Lớn nhất HP lượng máu ), Bùng Cháy: Hút máu tăng lên 30%, tổn thương tăng thêm tăng lên 30%; Tất sát kỹ kết thúc sau tiêu hao hết 2 Tầng chiến ý',
		describe_en = 'Beerus transforms into the Flame Blaze Radiance, throwing blazing hot bullets attacking all enemy troops, dealing #C0xE69900#280% Physical Attack #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Physical Damage #C0x5B545B#, simultaneously entering the Burning state for 2 turns, and healing himself for 30% of max HP (allied Fire attribute units heal themselves for 15% of max HP). Burning: Lifesteal increases by 30%, additional damage increases by 30%; The ultimate skill ends after consuming 2 levels of battle intent.',
		describe_th = 'บีรัสแปลงร่างเป็นเปลวไฟเปล่งประกาย ยิงกระสุนร้อนแรงโจมตีกองทัพศัตรูทั้งหมด สร้างความเสียหาย #C0xE69900#280% การโจมตีทางกายภาพ #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# พร้อมเข้าสู่สถานะลุกไหม้เป็นเวลา 2 เทิร์น และฟื้นฟูตัวเอง 30% ของพลังชีวิตสูงสุด (พันธมิตรธาตุไฟฟื้นฟูตัวเอง 15% ของพลังชีวิตสูงสุด) สถานะลุกไหม้: การดูดเลือดเพิ่มขึ้น 30%, ความเสียหายเพิ่มเติมเพิ่มขึ้น 30%; สกิลสุดท้ายจะจบหลังจากใช้จิตใจรบ 2 ชั้นหมด',
		describe_in = 'Beerus berubah menjadi Sinar Api Membara, melempar peluru panas yang menyerang seluruh pasukan musuh, menyebabkan #C0xE69900#280% Serangan Fisik #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#, sekaligus memasuki status Terbakar selama 2 giliran, dan memulihkan dirinya sendiri sebesar 30% dari HP maksimum (sekutu elemen Api memulihkan dirinya sendiri sebesar 15% dari HP maksimum). Terbakar: Serapan darah meningkat 30%, tambahan kerusakan meningkat 30%; Skill pamungkas berakhir setelah menghabiskan 2 level niat bertarung.',
		describe_ph = 'Nagbago si Beerus sa Anyong Apoy na Naglalagablab, nagbato ng mga mainit na bala na umaatake sa lahat ng kalabang hukbo, nagdudulot ng #C0xE69900#280% Pisikal na Atake #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Pisikal na Danyos #C0x5B545B#, kasabay ng pagpasok sa Burning state sa loob ng 2 turn, at nagpapagaling ng sarili ng 30% ng pinakamataas na HP (ang mga kaalyadong may Fire attribute ay nagpapagaling ng sarili ng 15% ng pinakamataas na HP). Burning: Nadagdag ang lifesteal ng 30%, nadagdag ang dagdag na pinsala ng 30%; Ang ultimate skill ay matatapos pagkatapos maubos ang 2 antas ng battle intent.',
		describe_ma = 'Beerus berubah menjadi Api Nyala Membara, melempar peluru panas yang menyerang seluruh angkatan musuh, menyebabkan #C0xE69900#280% Serangan Fizikal #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, sekali gus memasuki keadaan Terbakar selama 2 pusingan, dan memulihkan diri sebanyak 30% daripada HP maksimum (sekutu elemen Api memulihkan diri sebanyak 15% daripada HP maksimum). Terbakar: Serapan darah meningkat sebanyak 30%, tambahan kerosakan meningkat sebanyak 30%; Kemahiran utama tamat selepas menggunakan 2 tahap niat bertarung.',
		describe = 'Beerus transforms into the Flame Blaze Radiance, throwing blazing hot bullets attacking all enemy troops, dealing #C0xE69900#280% Physical Attack #C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# Physical Damage #C0x5B545B#, simultaneously entering the Burning state for 2 turns, and healing himself for 30% of max HP (allied Fire attribute units heal themselves for 15% of max HP). Burning: Lifesteal increases by 30%, additional damage increases by 30%; The ultimate skill ends after consuming 2 levels of battle intent.',
		simDesc_vn = 'Beerus biến thành một luồng lửa và thả những viên đạn thiêu đốt tấn công mọi kẻ thù.',
		simDesc_en = 'Beerus transforms into a stream of fire and unleashes burning bullets to attack all enemies.',
		simDesc_th = 'บีรัสแปลงร่างเป็นลำไฟแล้วปล่อยกระสุนไฟเผาทำลายเพื่อโจมตีศัตรูทุกตัว',
		simDesc_in = 'Beerus berubah menjadi aliran api dan melepaskan peluru pembakar untuk menyerang semua musuh.',
		simDesc_ph = 'Si Beerus ay nagiging isang daloy ng apoy at nagpapakawala ng mga naglalagablab na bala upang atakihin ang lahat ng kalaban.',
		simDesc_ma = 'Beerus berubah menjadi aliran api dan melepaskan peluru pembakar untuk menyerang semua musuh.',
		simDesc = 'Beerus transforms into a stream of fire and unleashes burning bullets to attack all enemies.',
		starEffect = __data_t__starEffect[36733],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng thêm: Trong trạng thái Bùng Cháy, tăng 50% miễn khống; khi tấn công sẽ thêm hiệu ứng Thiêu Đốt và 30% dễ tổn thương nguyên tố Hỏa trong 2 lượt cho mục tiêu; sau khi kết thúc kỹ năng Tất Sát sẽ tiêu hao 1 tầng Chiến Ý.',
		starEffectDesc = 'Additional Effect: In the Burning state, increase immunity by 50%; when attacking, add Burn effect and 30% increased vulnerability to Fire element for 2 turns on the target; after finishing the Execution skill, consume 1 stack of Battle Intent.',
		starEffectDesc_en = 'Additional Effect: In the Burning state, increase immunity by 50%; when attacking, add Burn effect and 30% increased vulnerability to Fire element for 2 turns on the target; after finishing the Execution skill, consume 1 stack of Battle Intent.',
		starEffectDesc_th = 'ผลเพิ่ม: ในสถานะลุกไหม้ เพิ่มความต้านทานสถานะผิดปกติ 50%; เมื่อโจมตีจะเพิ่มเอฟเฟคเผาไหม้และทำให้เป้าหมายมีความเปราะบางธาตุไฟเพิ่มขึ้น 30% เป็นเวลา 2 เทิร์น; หลังจากจบสกิลสังหาร จะใช้ความตั้งใจสู้รบ 1 ชั้น',
		starEffectDesc_in = 'Efek tambahan: Dalam keadaan Terbakar, tingkatkan imunitas 50%; saat menyerang akan menambahkan efek Terbakar dan 30% kerentanan elemen Api selama 2 giliran pada target; setelah menyelesaikan skill Pembunuhan, akan mengonsumsi 1 tumpukan Intent Pertempuran.',
		starEffectDesc_ph = 'Karagdagang Epekto: Sa Burning state, tumaas ang immunity ng 50%; kapag umatake ay magkakaroon ng Burn effect at 30% dagdag na kahinaan sa Fire element sa loob ng 2 turn sa target; pagkatapos matapos ang Execution skill, gagamitin ang 1 stack ng Battle Intent.',
		starEffectDesc_ma = 'Kesan tambahan: Dalam keadaan Terbakar, tingkatkan imuniti sebanyak 50%; apabila menyerang, akan menambah kesan Terbakar dan 30% kerentanan unsur Api selama 2 pusingan ke atas sasaran; selepas tamat kemahiran Pembunuhan, akan menggunakan 1 lapisan Niat Perang.',
		zawakeEffect = __data_t__zawakeEffect[36733],
		-- {79003}
		zawakeEffectDesc = 'Beerus turns into a fire bearer and drops fire bombs to burn and attack all enemies, causing #C0xF13B54# Physical Damage #C0xE69900#280% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0x5B545B#. And enters a blazing state for 2 turns, simultaneously restoring 30% of maximum HP to himself and fire allies (other non-fire allies restore 15% of your own maximum HP), lifesteal increased by 30%, additional damage increased by 30%, and physical defense penetration increased by 30%; after the special skill is completed, 2 battle stacks will be consumed.',
		zawakeEffectDesc_en = 'Beerus turns into a fire bearer and drops fire bombs to burn and attack all enemies, causing #C0xF13B54# Physical Damage #C0xE69900#280% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$#C0x5B545B#. And enters a blazing state for 2 turns, simultaneously restoring 30% of maximum HP to himself and fire allies (other non-fire allies restore 15% of your own maximum HP), lifesteal increased by 30%, additional damage increased by 30%, and physical defense penetration increased by 30%; after the special skill is completed, 2 battle stacks will be consumed.',
		zawakeEffectDesc_th = 'Beerus กลายเป็นผู้ส่งผ่านไฟและปล่อยระเบิดไฟเผาไหม้โจมตีศัตรูทั้งหมด ทำให้เกิด #C0xF13B54# ความเสียหายทางกายภาพ #C0xE69900#280% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*90)$#C0x5B545B# และเข้าสู่สภาวะลุกเป็นไฟเป็นเวลา 2 เทิร์น พร้อมกับฟื้นฟูพลังชีวิตสูงสุด 30% ให้ตัวเองและพันธมิตรไฟ (พันธมิตรอื่นที่ไม่เป็นไฟจะฟื้นฟูพลังชีวิตสูงสุด 15% ของตัวคุณเอง) การดูดเลือดเพิ่มขึ้น 30%, ความเสียหายเพิ่มเติมเพิ่มขึ้น 30% และการเจาะเกราะกายภาพเพิ่มขึ้น 30%; หลังจากท่าพิเศษเสร็จสิ้น จะใช้ 2 ชั้นของการต่อสู้',
		zawakeEffectDesc_in = 'Beerus berubah menjadi pembawa api dan melepaskan bom api yang membakar untuk menyerang semua musuh, menyebabkan #C0xF13B54# Kerusakan Fisik #C0xE69900#280% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*90)$#C0x5B545B#. Dan memasuki keadaan menyala selama 2 giliran, sekaligus memulihkan 30% HP maksimum untuk diri sendiri dan sekutu api (sekutu lain yang bukan api memulihkan 15% HP maksimum Anda sendiri), lifesteal meningkat 30%, tambahan kerusakan meningkat 30%, dan penetrasi pertahanan fisik meningkat 30%; setelah skill khusus selesai, 2 lapisan pertarungan akan habis.',
		zawakeEffectDesc_ph = 'Nagiging isang tagapagdala ng apoy si Beerus at naglalabas ng mga bomba ng apoy upang sunugin at atakihin ang lahat ng mga kaaway, na nagdudulot ng #C0xF13B54# Pisikal na Pinsala #C0xE69900#280% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*90)$#C0x5B545B#. At pumapasok sa naglalagablab na estado sa loob ng 2 turn, kasabay ng pagpapanumbalik ng 30% ng pinakamataas na HP para sa kanyang sarili at mga kaalyadong apoy (ang ibang mga kaalyado na hindi apoy ay nagpapagaling ng 15% ng iyong sariling pinakamataas na HP), tumaas ng 30% ang lifesteal, dagdag na pinsala tumaas ng 30%, at ang paglusot ng pisikal na depensa tumaas ng 30%; matapos makumpleto ang espesyal na kasanayan, gagamitin ang 2 stacks ng laban.',
		zawakeEffectDesc_ma = 'Beerus berubah menjadi pembawa api dan menjatuhkan bom api untuk membakar dan menyerang semua musuh, menyebabkan #C0xF13B54# Kerosakan Fizikal #C0xE69900#280% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*90)$#C0x5B545B#. Dan memasuki keadaan menyala selama 2 giliran, sekaligus memulihkan 30% HP maksimum kepada dirinya sendiri dan sekutu api (sekutu lain yang bukan api memulihkan 15% HP maksimum anda sendiri), peningkatan serapan darah sebanyak 30%, peningkatan kerosakan tambahan sebanyak 30%, dan peningkatan penembusan pertahanan fizikal sebanyak 30%; selepas kemahiran khas selesai, 2 lapisan pertarungan akan digunakan.',
		zawakeEffectDesc_vn = 'Beerus biến thành một người truyền lửa và thả bom thiêu đốt tấn công tất cả kẻ thù, gây #C0xF13B54# Sát Thương Vật Lý #C0xE69900#280% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*90)$#C0x5B545B#. Và tiến vào trạng thái rực lửa trong 2 hiệp, đồng thời phục hồi 30% máu tối đa cho bản thân và đồng đội lửa (các đồng minh không thân thiện với lửa khác phục hồi 15% máu tối đa của chính bạn), tốc độ hút máu tăng 30%, sát thương cộng thêm tăng 30% và khả năng phòng thủ vật lý bị bỏ qua tăng 30%; sau khi chiêu thức đặc biệt hoàn thành, 2 tầng chiến đấu sẽ bị tiêu hao.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Enhanced Burning State: #C0x5c9970# Ignores 30% Physical Defense; healing amount of other friendly Fire units is increased by 30% of their max HP (non-friendly Fire units restore 15% of their own max HP)',
		zawakeSimpleDesc_en = 'Enhanced Burning State: #C0x5c9970# Ignores 30% Physical Defense; healing amount of other friendly Fire units is increased by 30% of their max HP (non-friendly Fire units restore 15% of their own max HP)',
		zawakeSimpleDesc_th = 'เสริมสถานะไฟลุก: #C0x5c9970# ละเว้นการป้องกันกายภาพ 30%; การฟื้นฟูของยูนิตธาตุไฟฝ่ายเดียวกันเพิ่มขึ้น 30% ของ HP สูงสุด (ธาตุไฟไม่ใช่ฝ่ายเดียวกันฟื้น 15% HP สูงสุดของตัวเอง)',
		zawakeSimpleDesc_in = 'Perkuat status Api Membara: #C0x5c9970# Mengabaikan 30% Pertahanan Fisik; jumlah pemulihan dari unit Elemen Api sekutu lainnya meningkat sebesar 30% dari HP maksimum (unit Api musuh pulihkan 15% dari HP maksimum mereka sendiri)',
		zawakeSimpleDesc_ph = 'Pinalakas na Apoy: #C0x5c9970# Binabalewala ang 30% Physical Defense; ang healing ng iba pang kakamping may elemento ng Apoy ay tumaas ng 30% ng kanilang max HP (kalabang may Apoy ay naghilom ng 15% ng sariling max HP)',
		zawakeSimpleDesc_ma = 'Kuatkan status Api Menyala: #C0x5c9970# Abaikan 30% Pertahanan Fizikal; kadar pemulihan unit Api yang mesra meningkat 30% daripada HP maksimum (unit Api bukan sekutu memulihkan 15% daripada HP maksimum mereka sendiri)',
		zawakeSimpleDesc_vn = 'Cường hóa trạng thái rực lửa: #C0x5c9970# Bỏ qua phòng thủ vật lý tăng 30%; lượng hồi phục của các yếu tố lửa thân thiện khác được tăng lên 30% giá trị sức khỏe tối đa (các yếu tố lửa không thân thiện khác phục hồi lượng máu bằng 15% giá trị sức khỏe tối đa của chính chúng)',
		upLvDesc = 'Fixed damage +360',
		upLvDesc_en = 'Fixed damage +360',
		upLvDesc_th = 'ความเสียหายคงที่ +360',
		upLvDesc_in = 'Kerusakan tetap +360',
