	[36736] = {
		id = 36736,
		skillName_vn = 'Thần hủy diệt',
		skillName_en = 'Destroyer God',
		skillName_th = 'เทพผู้ทำลายล้าง',
		skillName_in = 'Dewa Penghancur',
		skillName_ph = 'Diyos ng Pagwasak',
		skillName_ma = 'Dewa Pemusnah',
		skillName = 'Destroyer God',
		describe_vn = 'Kết thúc hiệp đấu có 60% cơ hội đạt được một tầng tinh thần chiến đấu; khi bị chủ động tấn công có 25% cơ hội nhận được một lớp tinh thần chiến đấu, tối đa bốn điểm cộng dồn; trước khi bắt đầu mỗi vòng lớn, Beerus sẽ cướp 3 đơn vị có đòn tấn công cao nhất của đối phương #C0x5c9970# Đòn tấn công kép $(10+skillLevel*0.05-0.05)$%#C0x5B545B# sẽ được trả lại sau vòng lớn; khi anh hùng lửa đồng minh chết, anh ta sẽ ngay lập tức tung ra chiêu thức đặc biệt và nhận được 2 lớp tinh thần chiến đấu (được kích hoạt một lần trong toàn bộ trò chơi)',
		describe_en = 'At the end of the match, there is a 60% chance to gain one layer of combat spirit; when actively attacked, there is a 25% chance to receive one layer of combat spirit, stacking up to four points; before the start of each major round, Beerus will steal 3 units with the highest attack of the opponent. #C0x5c9970# Double attack $(10+skillLevel*0.05-0.05)$%#C0x5B545B# will be returned after the major round; when the allied fire hero dies, he will immediately unleash a special move and gain 2 layers of combat spirit (activated once per entire game).',
		describe_th = 'เมื่อสิ้นสุดการแข่งขัน จะมีโอกาส 60% ที่จะได้รับชั้นจิตวิญญาณการต่อสู้หนึ่งชั้น; เมื่อถูกโจมตีอย่างตั้งใจ จะมีโอกาส 25% ที่จะได้รับชั้นจิตวิญญาณการต่อสู้หนึ่งชั้น ซึ่งสะสมได้สูงสุดสี่ชั้น; ก่อนเริ่มรอบใหญ่แต่ละรอบ, เบียร์สจะขโมยยูนิต 3 ตัวที่มีพลังโจมตีสูงสุดของฝ่ายตรงข้าม #C0x5c9970# การโจมตีคู่ $(10+skillLevel*0.05-0.05)$%#C0x5B545B# จะถูกคืนหลังจากรอบใหญ่; เมื่อฮีโร่ไฟฝ่ายเดียวกันตาย เขาจะปล่อยท่าพิเศษทันทีและได้รับชั้นจิตวิญญาณการต่อสู้สองชั้น (เปิดใช้งานได้ครั้งเดียวตลอดทั้งเกม)',
		describe_in = 'Di akhir pertandingan, ada peluang 60% untuk mendapatkan satu tingkat semangat bertarung; ketika diserang secara aktif, ada peluang 25% untuk menerima satu lapis semangat bertarung, maksimal empat tumpukan; sebelum memulai setiap ronde besar, Beerus akan mencuri 3 unit dengan serangan tertinggi dari lawan. #C0x5c9970# Serangan ganda $(10+skillLevel*0.05-0.05)$%#C0x5B545B# akan dikembalikan setelah ronde besar; ketika pahlawan api sekutu mati, dia akan segera melancarkan gerakan khusus dan menerima 2 lapis semangat bertarung (diaktifkan sekali selama seluruh permainan).',
		describe_ph = 'Sa pagtatapos ng laban, may 60% na tsansa na makakuha ng isang antas ng espiritu ng pakikipaglaban; kapag inatake nang aktibo, may 25% na tsansa na makatanggap ng isang antas ng espiritu ng pakikipaglaban, hanggang apat na stack; bago magsimula ang bawat malaking round, si Beerus ay magnanakaw ng 3 yunit na may pinakamataas na atake ng kalaban. #C0x5c9970# Ang dobleng atake $(10+skillLevel*0.05-0.05)$%#C0x5B545B# ay ibabalik pagkatapos ng malaking round; kapag namatay ang katulong na bayani ng apoy, agad siyang magpapakawala ng espesyal na galaw at makakatanggap ng 2 antas ng espiritu ng pakikipaglaban (isinaaktibo isang beses sa buong laro).',
		describe_ma = 'Pada akhir perlawanan, terdapat peluang 60% untuk mendapat satu lapisan semangat bertempur; apabila diserang secara aktif, terdapat peluang 25% untuk menerima satu lapisan semangat bertempur, maksimum empat tumpukan; sebelum memulakan setiap pusingan besar, Beerus akan mencuri 3 unit dengan serangan tertinggi dari pihak lawan. #C0x5c9970# Serangan berganda $(10+skillLevel*0.05-0.05)$%#C0x5B545B# akan dikembalikan selepas pusingan besar; apabila wira api sekutu mati, dia akan terus melancarkan serangan khas dan menerima 2 lapisan semangat bertempur (diaktifkan sekali sepanjang permainan).',
		describe = 'At the end of the match, there is a 60% chance to gain one layer of combat spirit; when actively attacked, there is a 25% chance to receive one layer of combat spirit, stacking up to four points; before the start of each major round, Beerus will steal 3 units with the highest attack of the opponent. #C0x5c9970# Double attack $(10+skillLevel*0.05-0.05)$%#C0x5B545B# will be returned after the major round; when the allied fire hero dies, he will immediately unleash a special move and gain 2 layers of combat spirit (activated once per entire game).',
		starEffect = __data_t__starEffect[36736],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng phụ: Mỗi khi một đơn vị địch bị hạ gục, đánh cắp 15% Công Vật Lý và Công Phép của mục tiêu (có thể cộng dồn); toàn bộ đồng minh hệ Hỏa và hệ Ma khác nhận 50% hiệu ứng này.',
		starEffectDesc = 'Side effect: Each time an enemy unit is defeated, steal 15% of the target\'s Physical Attack and Magic Attack (can stack); all other allies from the Fire and Demon factions receive 50% of this effect.',
		starEffectDesc_en = 'Side effect: Each time an enemy unit is defeated, steal 15% of the target\'s Physical Attack and Magic Attack (can stack); all other allies from the Fire and Demon factions receive 50% of this effect.',
		starEffectDesc_th = 'ผลข้างเคียง: ทุกครั้งที่หน่วยศัตรูถูกกำจัด ขโมย 15% ของพลังโจมตีทางกายภาพและเวทมนตร์ของเป้าหมาย (สามารถสะสมได้); พันธมิตรทั้งหมดในระบบไฟและปีศาจอื่นๆ จะได้รับผลนี้ 50%',
		starEffectDesc_in = 'Efek samping: Setiap kali unit musuh dikalahkan, curi 15% Serangan Fisik dan Serangan Sihir target (dapat ditumpuk); semua sekutu lain dari elemen Api dan Iblis menerima 50% dari efek ini.',
		starEffectDesc_ph = 'Side effect: Sa tuwing may natalong kalabang yunit, nakawin ang 15% ng Physical Attack at Magic Attack ng target (pwedeng mag-stack); ang lahat ng ibang alyado mula sa Fire at Demon systems ay tumatanggap ng 50% ng epektong ito.',
		starEffectDesc_ma = 'Kesan sampingan: Setiap kali unit musuh dikalahkan, curi 15% Serangan Fizikal dan Serangan Sihir sasaran (boleh bertindih); semua sekutu lain dari sistem Api dan Syaitan menerima 50% kesan ini.',
		zawakeEffect = __data_t__zawakeEffect[36736],
		-- {79004}
		zawakeEffectDesc = 'When the battle starts, you will get 1 layer of fighting spirit. At the end of the round, you have a 60% chance to receive a layer of fighting spirit. When actively attacked, you will have a 40% chance to receive a layer of fighting spirit, up to a maximum of four stacks. Before each major round begins, Beerus will steal 3 enemy units with the highest attack #C0x5 Double attack c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# which will be returned after the major round; when an allied fire hero dies, he will immediately unleash a special move and receive 2 layers of fighting spirit (activated once throughout the entire game).',
		zawakeEffectDesc_en = 'When the battle starts, you will get 1 layer of fighting spirit. At the end of the round, you have a 60% chance to receive a layer of fighting spirit. When actively attacked, you will have a 40% chance to receive a layer of fighting spirit, up to a maximum of four stacks. Before each major round begins, Beerus will steal 3 enemy units with the highest attack #C0x5 Double attack c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# which will be returned after the major round; when an allied fire hero dies, he will immediately unleash a special move and receive 2 layers of fighting spirit (activated once throughout the entire game).',
		zawakeEffectDesc_th = 'เมื่อเริ่มการต่อสู้ คุณจะได้รับชั้นจิตวิญญาณการต่อสู้ 1 ชั้น เมื่อสิ้นสุดรอบ คุณมีโอกาส 60% ที่จะได้รับชั้นจิตวิญญาณการต่อสู้ 1 ชั้น เมื่อถูกโจมตีอย่างตั้งใจ คุณจะมีโอกาส 40% ที่จะได้รับชั้นจิตวิญญาณการต่อสู้ 1 ชั้น สูงสุดสี่ชั้น ก่อนเริ่มรอบใหญ่แต่ละครั้ง บีรัสจะขโมย 3 หน่วยศัตรูที่มีการโจมตีสูงสุด #C0x5 การโจมตีสองครั้ง c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# จะถูกส่งคืนหลังรอบใหญ่; เมื่อฮีโร่ไฟพันธมิตรตาย เขาจะปล่อยท่าโจมตีพิเศษทันทีและได้รับชั้นจิตวิญญาณการต่อสู้ 2 ชั้น (เปิดใช้งานครั้งเดียวในเกมทั้งหมด)',
		zawakeEffectDesc_in = 'Saat pertempuran dimulai, Anda akan mendapatkan 1 lapis semangat bertarung. Pada akhir putaran, Anda memiliki peluang 60% untuk menerima 1 lapis semangat bertarung. Saat diserang aktif, Anda akan memiliki peluang 40% untuk menerima 1 lapis semangat bertarung, maksimal empat tumpukan. Sebelum memulai setiap putaran besar, Beerus akan mencuri 3 unit musuh dengan serangan tertinggi #C0x5 Serangan ganda c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# yang akan dikembalikan setelah putaran besar; ketika pahlawan api sekutu mati, dia akan segera meluncurkan serangan khusus dan menerima 2 lapis semangat bertarung (diaktifkan sekali selama seluruh permainan).',
		zawakeEffectDesc_ph = 'Kapag nagsimula ang laban, makakakuha ka ng 1 layer ng fighting spirit. Sa pagtatapos ng round, mayroon kang 60% chance na makatanggap ng 1 layer ng fighting spirit. Kapag naaktibong inatake, magkakaroon ka ng 40% chance na makatanggap ng 1 layer ng fighting spirit, hanggang sa maximum na apat na stack. Bago magsimula ang bawat malaking round, si Beerus ay mananakaw ng 3 enemy units na may pinakamataas na atake #C0x5 Double attack c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# na ibabalik pagkatapos ng malaking round; kapag namatay ang allied fire hero, agad niyang ilalabas ang espesyal na galaw at makakatanggap ng 2 layer ng fighting spirit (activated once throughout the entire game).',
		zawakeEffectDesc_ma = 'Apabila pertempuran bermula, anda akan mendapat 1 lapisan semangat bertarung. Pada akhir pusingan, anda mempunyai 60% peluang untuk menerima 1 lapisan semangat bertarung. Apabila diserang secara aktif, anda akan mempunyai 40% peluang untuk menerima 1 lapisan semangat bertarung, maksimum empat tumpukan. Sebelum permulaan setiap pusingan besar, Beerus akan mencuri 3 unit musuh dengan serangan tertinggi #C0x5 Serangan berganda c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# yang akan dikembalikan selepas pusingan besar; apabila wira api sekutu mati, dia akan segera melancarkan serangan khas dan menerima 2 lapisan semangat bertarung (diaktifkan sekali sepanjang permainan).',
		zawakeEffectDesc_vn = 'Khi bắt đầu trận chiến, bạn sẽ có được 1 tầng tinh thần chiến đấu. Khi kết thúc vòng đấu, bạn sẽ có 60% cơ hội nhận được một lớp tinh thần chiến đấu. Khi bị tấn công chủ động, bạn sẽ có 40% cơ hội nhận được một tầng tinh thần chiến đấu, tối đa bốn điểm cộng dồn. Trước khi bắt đầu mỗi vòng lớn, Beerus sẽ cướp 3 đơn vị địch có đòn tấn công cao nhất #C0x5 Đòn tấn công kép c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# sẽ được trả lại sau vòng lớn; khi anh hùng lửa đồng minh chết, anh ta sẽ ngay lập tức tung ra chiêu thức đặc biệt và nhận được 2 lớp tinh thần chiến đấu (được kích hoạt một lần trong toàn bộ trò chơi)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Gain 1 stack of Battle Will when entering battle; and chance to gain Battle Will when actively attacked increases to 40%',
		zawakeSimpleDesc_en = 'Gain 1 stack of Battle Will when entering battle; and chance to gain Battle Will when actively attacked increases to 40%',
		zawakeSimpleDesc_th = 'เมื่อเข้าสู่การต่อสู้จะได้รับ 1 ชั้นของเจตจำนงต่อสู้; และโอกาสได้รับเมื่อถูกโจมตีจะเพิ่มเป็น 40%',
		zawakeSimpleDesc_in = 'Saat memasuki pertempuran, mendapatkan 1 lapisan Niat Bertarung; dan peluang mendapatkannya saat diserang aktif meningkat menjadi 40%  ',
		zawakeSimpleDesc_ph = 'Pagpasok sa laban, makakakuha ng 1 stack ng Lakas ng Laban; at ang tsansa makakuha nito kapag inatake ay tumaas sa 40%  ',
		zawakeSimpleDesc_ma = 'Apabila memasuki pertempuran, dapatkan 1 lapisan Semangat Bertempur; dan kadar peluang menerima semasa diserang meningkat kepada 40%  ',
		zawakeSimpleDesc_vn = 'Khi vào trận nhận 1 tầng Chiến Ý; và xác suất nhận Chiến Ý khi bị tấn công chủ động tăng lên 40%',
		iconRes = 'battle/skill_icon/skill_36736.png',
