	[36812] = {
		id = 36812,
		skillName_vn = 'Giam giữ bóng nước',
		skillName_en = 'Bubble captivity',
		skillName_th = 'การกักขังฟองน้ำ',
		skillName_in = 'Penahanan gelembung',
		skillName_ph = 'Pagkakakulong ng bula',
		skillName_ma = 'Penahanan gelembung',
		skillName = 'Bubble captivity',
		describe_vn = 'Cầu cầu Hải Sư thổi ra một quả bóng nước tấn công mục tiêu đơn lẻ của địch, gây ra#C0x3D8A99#140% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ sát thương#C0xF13B54#pháp thuật#C0x5B545B#, dùng tiếng hát điều khiển phát bóng nước [Trói Buộc] hàng mục tiêu (Trói Buộc: hiệu quả khống chế, không thể sử dụng công thường), sau khi mục tiêu sử dụng kỹ năng nhỏ hoặc tất sát kỹ, bóng nước phát nổ và giải trừ Trói Buộc, gây sát thương bằng 100% Phép Công của Cầu cầu Hải Sư',
		describe_en = 'The Sea Lion Cannon blows out a water bubble to attack a single enemy target, dealing #C0x3D8A99#140% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#magic#C0x5B545B# damage. It uses singing to control and launch the water bubble [Bind] on enemy targets (Bind: a control effect that prevents using normal attacks). After the target uses a minor skill or an ultimate skill, the water bubble explodes and removes the Bind, dealing damage equal to 100% of the Sea Lion Cannon\'s Magic Attack.',
		describe_th = 'ปืนสิงโตทะเลพ่นฟองน้ำโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0x3D8A99#140% พลังโจมตีเวทมนตร์#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#เวทมนตร์#C0x5B545B# ใช้เสียงเพลงควบคุมปล่อยฟองน้ำ [ผูกมัด] ใส่เป้าหมาย (ผูกมัด: ผลการควบคุมที่ไม่สามารถโจมตีปกติได้) เมื่อเป้าหมายใช้ทักษะเล็กหรือทักษะสุดท้าย ฟองน้ำจะแตกและปลดผูกมัด พร้อมสร้างความเสียหายเท่ากับ 100% พลังโจมตีเวทมนตร์ของปืนสิงโตทะเล',
		describe_in = 'Kanon Singa Laut meniup gelembung air untuk menyerang satu target musuh, memberikan #C0x3D8A99#140% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#sihir#C0x5B545B# damage. Menggunakan nyanyian untuk mengendalikan dan meluncurkan gelembung air [Ikatan] ke target musuh (Ikatan: efek kendali yang mencegah penggunaan serangan biasa). Setelah target menggunakan skill kecil atau ultimate, gelembung air meledak dan menghilangkan Ikatan, memberikan damage sebesar 100% Serangan Sihir Kanon Singa Laut.',
		describe_ph = 'Ang kawsa ng Leon sa Dagat ay humihip ng isang bula ng tubig upang umatake sa iisang target na kaaway, na nagdudulot ng #C0x3D8A99#140% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#magical#C0x5B545B# na pinsala. Ginagamit ang pag-awit upang kontrolin ang bula ng tubig [Bind] sa mga target (Bind: epekto ng kontrol na pumipigil sa paggamit ng normal na pag-atake). Kapag gumamit ang target ng maliit na kasanayan o ultimate skill, sasabog ang bula ng tubig at aalisin ang Bind, na nagdudulot ng pinsala katumbas ng 100% ng Magic Attack ng Kawsa ng Leon sa Dagat.',
		describe_ma = 'Meriam Singa Laut meniup gelembung air untuk menyerang satu sasaran musuh, memberikan #C0x3D8A99#140% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#sihir#C0x5B545B# kerosakan. Menggunakan nyanyian untuk mengawal dan melontar gelembung air [Ikatan] ke sasaran musuh (Ikatan: kesan kawalan yang menghalang penggunaan serangan biasa). Setelah sasaran menggunakan kemahiran kecil atau kemahiran utama, gelembung air meletup dan menanggalkan Ikatan, memberikan kerosakan sebanyak 100% Serangan Sihir Meriam Singa Laut.',
		describe = 'The Sea Lion Cannon blows out a water bubble to attack a single enemy target, dealing #C0x3D8A99#140% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#magic#C0x5B545B# damage. It uses singing to control and launch the water bubble [Bind] on enemy targets (Bind: a control effect that prevents using normal attacks). After the target uses a minor skill or an ultimate skill, the water bubble explodes and removes the Bind, dealing damage equal to 100% of the Sea Lion Cannon\'s Magic Attack.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
		upLvDesc_in = 'Kerusakan tetap +192',
