	[36813] = {
		id = 36813,
		skillName_vn = 'Xả nước bắn',
		skillName_en = 'Water spray',
		skillName_th = 'พ่นน้ำ',
		skillName_in = 'Semprotan air',
		skillName_ph = 'Basang tubig',
		skillName_ma = 'Semburan air',
		skillName = 'Water spray',
		describe_vn = 'Cầu cầu Hải Sư phun ra lượng lớn dòng nước quét bắn tấn công mục tiêu hàng trước của địch, gây ra#C0x3D8A99#240% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ sát thương#C0xF13B54#pháp thuật#C0x5B545B#, giảm 200 điểm nộ khí của mục tiêu, và xóa bỏ thiêu đốt của toàn bộ anh hùng trên sân, địch bị xóa bỏ thêm giảm 600 điểm nộ khí, đồng minh bị xóa bỏ hồi phục sinh mệnh bằng 100% Phép Công của Cầu cầu Hải Sư',
		describe_en = 'The Sea Lion Ball sprays a large amount of water that sweeps and attacks the enemy\'s front row targets, causing #C0x3D8A99#240% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#magic#C0x5B545B# damage, reducing the target\'s rage by 200 points, and removing burn from all heroes on the field. Enemies whose burns are removed lose an additional 600 rage points, while allies whose burns are removed recover health equal to 100% of the Sea Lion Ball\'s Magic Attack.',
		describe_th = 'ลูกบอลสิงโตทะเลพ่นน้ำปริมาณมากพุ่งโจมตีเป้าหมายแถวหน้าของศัตรู ทำให้เกิดความเสียหาย #C0x3D8A99#240% พลังเวท#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#เวทมนตร์#C0x5B545B# ลดความโกรธของเป้าหมายลง 200 คะแนน และล้างสถานะเผาของฮีโร่ทั้งหมดในสนาม ศัตรูที่ถูกล้างสถานะเผาจะถูกลดความโกรธเพิ่มอีก 600 คะแนน ในขณะเดียวกันพันธมิตรที่ถูกล้างสถานะเผาจะฟื้นฟูพลังชีวิตเท่ากับ 100% ของพลังเวทของลูกบอลสิงโตทะเล',
		describe_in = 'Bola Singa Laut menyemprotkan sejumlah besar air yang menyapu dan menyerang target barisan depan musuh, menyebabkan #C0x3D8A99#240% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#sihir#C0x5B545B# damage, mengurangi kemarahan target sebesar 200 poin, dan menghapus terbakar dari seluruh pahlawan di lapangan. Musuh yang terbakar dihapus akan kehilangan tambahan 600 poin kemarahan, sedangkan sekutu yang terbakar akan sembuh sebesar 100% Serangan Sihir Bola Singa Laut.',
		describe_ph = 'Ang Sea Lion Ball ay nagbubuga ng malaking dami ng tubig na sumisilab at umaatake sa mga unang hanay ng mga kaaway, na nagdudulot ng #C0x3D8A99#240% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#magic#C0x5B545B# na pinsala, nagpapababa ng 200 puntos ng galit ng target, at tinatanggal ang burn sa lahat ng bayani sa larangan. Ang mga kaaway na natanggal ang burn ay nawawalan ng karagdagang 600 puntos ng galit, habang ang mga kaalyadong natanggal ang burn ay nakakakuha ng healing na katumbas ng 100% ng Magic Attack ng Sea Lion Ball.',
		describe_ma = 'Bola Singa Laut menyembur sejumlah besar air yang menyapu dan menyerang sasaran barisan hadapan musuh, menyebabkan #C0x3D8A99#240% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#sihir#C0x5B545B# kerosakan, mengurangkan kemarahan sasaran sebanyak 200 mata, dan membuang terbakar daripada semua wira di medan. Musuh yang terbakar dibuang kehilangan 600 mata kemarahan tambahan, manakala sekutu yang terbakar dibuang memulihkan kesihatan sebanyak 100% Serangan Sihir Bola Singa Laut.',
		describe = 'The Sea Lion Ball sprays a large amount of water that sweeps and attacks the enemy\'s front row targets, causing #C0x3D8A99#240% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#magic#C0x5B545B# damage, reducing the target\'s rage by 200 points, and removing burn from all heroes on the field. Enemies whose burns are removed lose an additional 600 rage points, while allies whose burns are removed recover health equal to 100% of the Sea Lion Ball\'s Magic Attack.',
		simDesc_vn = 'Cầu Cầu Hải Sư phun ra một lượng lớn nước tấn công mục tiêu ở hàng trước của kẻ thù, giảm năng lượng của mục tiêu và giải tán tất cả các hiệu ứng cháy trên toàn bộ hero.',
		simDesc_en = 'The Sea Lion Statue sprays a large amount of water to attack the enemy\'s front row targets, reducing their energy and dispelling all burn effects on all heroes.',
		simDesc_th = 'รูปปั้นสิงโตทะเลพ่นน้ำจำนวนมากโจมตีเป้าหมายแถวหน้าของศัตรู ลดพลังงานของเป้าหมายและขจัดเอฟเฟกต์การเผาไหม้ทั้งหมดบนฮีโร่ทุกตัว',
		simDesc_in = 'Patung Singa Laut menyemprotkan banyak air untuk menyerang target di barisan depan musuh, mengurangi energi target dan menghilangkan semua efek terbakar pada semua pahlawan.',
		simDesc_ph = 'Ang Pambansang Sea Lion na estatwa ay nagtutulo ng malaking halaga ng tubig upang atakihin ang mga target sa harap na hanay ng kaaway, binabawasan ang enerhiya ng target at tinatanggal ang lahat ng mga burn effect sa lahat ng mga hero.',
		simDesc_ma = 'Arca Singa Laut memancutkan sejumlah besar air untuk menyerang sasaran di barisan depan musuh, mengurangkan tenaga sasaran dan menghapus semua kesan terbakar pada semua wira.',
		simDesc = 'The Sea Lion Statue sprays a large amount of water to attack the enemy\'s front row targets, reducing their energy and dispelling all burn effects on all heroes.',
		starEffect = __data_t__starEffect[36813],
		-- {11}
