	[36816] = {
		id = 36816,
		skillName_vn = 'Giọng nói êm dịu',
		skillName_en = 'Soft voice',
		skillName_th = 'เสียงนุ่มนวล',
		skillName_in = 'Suara lembut',
		skillName_ph = 'Malambing na tinig',
		skillName_ma = 'Suara yang lembut',
		skillName = 'Soft voice',
		describe_vn = 'Khi không phải công thường hoặc bị tấn công, xóa bỏ một hiệu quả tăng ích của mục tiêu, nếu không có tăng ích để xóa bỏ, giảm#C0x5c9970#$(50+skillLevel*0.7-0.7)$#C0x5B545B# điểm nộ khí của mục tiêu',
		describe_en = 'When not performing a normal attack or being attacked, remove one beneficial effect from the target. If there is no beneficial effect to remove, reduce the target\'s chakra by $(50+skillLevel*0.7-0.7)$ points.',
		describe_th = 'เมื่อไม่ใช่การโจมตีปกติหรือถูกโจมตี ให้ลบเอฟเฟกต์บัฟหนึ่งอย่างของเป้าหมายออก หากไม่มีบัฟให้ลบ ให้ลดพลังชากระของเป้าหมายลง $(50+skillLevel*0.7-0.7)$ คะแนน',
		describe_in = 'Ketika bukan serangan biasa atau sedang diserang, hapus satu efek buff dari target. Jika tidak ada buff untuk dihapus, kurangi chakra target sebanyak $(50+skillLevel*0.7-0.7)$ poin.',
		describe_ph = 'Kapag hindi normal na pag-atake o inaatake, tanggalin ang isang benepisyo mula sa target. Kung walang benepisyo na matatanggal, bawasan ang chakra ng target ng $(50+skillLevel*0.7-0.7)$ puntos.',
		describe_ma = 'Apabila bukan serangan biasa atau diserang, padamkan satu kesan peningkatan faedah pada sasaran. Jika tiada kesan peningkatan faedah untuk dipadamkan, kurangkan sebanyak $(50+skillLevel*0.7-0.7)$ mata chakra sasaran.',
		describe = 'When not performing a normal attack or being attacked, remove one beneficial effect from the target. If there is no beneficial effect to remove, reduce the target\'s chakra by $(50+skillLevel*0.7-0.7)$ points.',
		starEffect = __data_t__starEffect[36816],
		-- {8}
		starEffectDesc_vn = 'Hiệu Ứng Bổ Sung: Khi Hải Sư Quả Bóng làm giảm năng lượng mục tiêu xuống dưới 350, có 100% xác suất <Mê Hoặc> trong 1 lượt (nếu năng lượng là 0 thì là 2 lượt), đồng thời hồi phục 50% Sát Thương Phép Thuật của bản thân.',
		starEffectDesc = 'Additional Effect: When Sea Lion Ball reduces the target\'s energy below 350, there is a 100% chance to <Charm> for 1 turn (if energy is 0, then 2 turns), and simultaneously recovers 50% of its own Magic Damage.',
		starEffectDesc_en = 'Additional Effect: When Sea Lion Ball reduces the target\'s energy below 350, there is a 100% chance to <Charm> for 1 turn (if energy is 0, then 2 turns), and simultaneously recovers 50% of its own Magic Damage.',
		starEffectDesc_th = 'ผลเสริม: เมื่อ เม่นทะเลลูกบอล ลดพลังงานของเป้าหมายลงต่ำกว่า 350 มีโอกาส 100% ที่จะ <สะกดจิต> เป็นเวลา 1 เทิร์น (ถ้าพลังงานเป็น 0 จะเป็น 2 เทิร์น) พร้อมกับฟื้นฟู 50% ของความเสียหายเวทของตัวเอง',
		starEffectDesc_in = 'Efek Tambahan: Ketika Bola Singa Laut mengurangi energi target di bawah 350, ada 100% kemungkinan <Mempesona> selama 1 giliran (jika energi adalah 0 maka 2 giliran), sekaligus memulihkan 50% dari Damage Sihir sendiri.',
		starEffectDesc_ph = 'Karagdagang Epekto: Kapag pinababa ng Sea Lion Ball ang enerhiya ng target sa ilalim ng 350, may 100% na pagkakataon na <Makitang-tao> sa loob ng 1 turn (kung 0 ang enerhiya, 2 turn ito), sabay na nagpapagaling ng 50% ng sariling Magic Damage.',
		starEffectDesc_ma = 'Kesan Tambahan: Apabila Bola Singa Laut mengurangkan tenaga sasaran di bawah 350, terdapat peluang 100% untuk <Membius> selama 1 giliran (jika tenaga adalah 0, maka 2 giliran), dan pada masa yang sama memulihkan 50% daripada Kerosakan Sihir diri sendiri.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
