	[36823] = {
		id = 36823,
		skillName_vn = 'Khúc ca bóng nước',
		skillName_en = 'Water Shadow Melody',
		skillName_th = 'บทเพลงเงาน้ำ',
		skillName_in = 'Melodi Bayangan Air',
		skillName_ph = 'Awit ng Anino ng Tubig',
		skillName_ma = 'Melodi Bayangan Air',
		skillName = 'Water Shadow Melody',
		describe_vn = 'Hoa Dạng Hải Sư lặn xuống đáy biển dùng bọt nước tấn công hàng trước của kẻ địch, gây #C0x3D8A99#250% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, giảm 200 điểm nộ khí của mục tiêu, và xóa bỏ hiệu ứng đốt cháy của toàn bộ anh hùng trên sân. Kẻ địch bị xóa bỏ hiệu ứng sẽ giảm thêm 600 điểm nộ khí, đồng đội bị xóa bỏ hiệu ứng sẽ hồi phục lượng máu bằng 100% Phép Công của Hoa Dạng Hải Sư',
		describe_en = 'The Lotus Sea Lion dives to the seafloor and attacks the front row of enemies with water bubbles, dealing #C0x3D8A99#250% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magical Damage #C0x5B545B#, reducing the target\'s rage by 200 points, and removing the burn effect from all heroes on the field. Enemies with the removed effect will lose an additional 600 rage, while allies with the removed effect will recover HP equal to 100% of the Lotus Sea Lion\'s Magic Power.',
		describe_th = 'สิงโตทะเลรูปดอกบัวดำน้ำลงไปที่ก้นทะเลและโจมตีแถวหน้าของศัตรูด้วยฟองน้ำ ใช้พลังเวท #C0x3D8A99#250%#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#ความเสียหายเวทมนตร์ #C0x5B545B# ลดความโกรธของเป้าหมายลง 200 คะแนน และลบสถานะถูกเผาจากฮีโร่ทั้งหมดในสนาม ศัตรูที่ถูกลบสถานะจะเสียความโกรธเพิ่มอีก 600 คะแนน พันธมิตรที่ถูกลบสถานะจะฟื้นฟูพลังชีวิตเท่ากับ 100% ของพลังเวทของสิงโตทะเลรูปดอกบัว',
		describe_in = 'Singa Laut Lotus menyelam ke dasar laut dan menyerang barisan depan musuh dengan gelembung air, memberikan #C0x3D8A99#250% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Magis #C0x5B545B#, mengurangi amarah target sebesar 200 poin, dan menghapus efek terbakar dari semua pahlawan di medan perang. Musuh yang efeknya dihapus akan kehilangan tambahan 600 amarah, sedangkan sekutu yang efeknya dihapus akan memulihkan HP sebesar 100% Kekuatan Sihir Singa Laut Lotus.',
		describe_ph = 'Ang Lotus Sea Lion ay lumulubog sa ilalim ng dagat at umatake sa unahang hanay ng mga kalaban gamit ang mga bula ng tubig, nagbibigay ng #C0x3D8A99#250% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magical Damage #C0x5B545B#, nagpapababa ng 200 puntos ng galit ng target, at tinatanggal ang burn effect sa lahat ng mga bayani sa labanan. Ang mga kalabang natanggalan ng effect ay babawasan pa ng 600 puntos ng galit, habang ang mga kaalyadong natanggalan ng effect ay gagalingin ang HP base sa 100% Magic Power ng Lotus Sea Lion.',
		describe_ma = 'Singa Laut Lotus menyelam ke dasar laut dan menyerang barisan hadapan musuh dengan gelembung air, memberikan #C0x3D8A99#250% Kuasa Magik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Magik #C0x5B545B#, mengurangkan kemarahan sasaran sebanyak 200 mata, dan membuang kesan terbakar pada semua wira di padang. Musuh yang dibuang kesan akan kehilangan tambahan 600 kemarahan, manakala rakan sepasukan yang dibuang kesan akan pulih HP bersamaan 100% Kuasa Magik Singa Laut Lotus.',
		describe = 'The Lotus Sea Lion dives to the seafloor and attacks the front row of enemies with water bubbles, dealing #C0x3D8A99#250% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magical Damage #C0x5B545B#, reducing the target\'s rage by 200 points, and removing the burn effect from all heroes on the field. Enemies with the removed effect will lose an additional 600 rage, while allies with the removed effect will recover HP equal to 100% of the Lotus Sea Lion\'s Magic Power.',
		starEffect = __data_t__starEffect[36823],
		-- {11}
