	[36826] = {
		id = 36826,
		skillName_vn = 'Giọng nói êm dịu',
		skillName_en = 'Soft voice',
		skillName_th = 'เสียงนุ่มนวล',
		skillName_in = 'Suara lembut',
		skillName_ph = 'Malambing na tinig',
		skillName_ma = 'Suara yang lembut',
		skillName = 'Soft voice',
		describe_vn = 'Khi không phải công thường hoặc bị tấn công, xóa bỏ một hiệu quả tăng ích của mục tiêu, nếu không có tăng ích để xóa bỏ, giảm#C0x5c9970#$(50+skillLevel*0.7-0.7)$#C0x5B545B# điểm nộ khí của mục tiêu',
		describe_en = 'When not performing a normal attack or being attacked, remove one beneficial effect from the target; if there is no beneficial effect to remove, reduce the target\'s rage by $(50+skillLevel*0.7-0.7)$ points.',
		describe_th = 'เมื่อไม่ใช่การโจมตีปกติหรือตอนถูกโจมตี ให้ลบหนึ่งสถานะเพิ่มประโยชน์จากเป้าหมาย หากไม่มีสถานะเพิ่มประโยชน์ให้ลบ ให้ลดพลังโกรธของเป้าหมายลง $(50+skillLevel*0.7-0.7)$ คะแนน',
		describe_in = 'Saat tidak melakukan serangan biasa atau diserang, hapus satu efek buff dari target; jika tidak ada buff yang dapat dihapus, kurangi kemarahan target sebesar $(50+skillLevel*0.7-0.7)$ poin.',
		describe_ph = 'Kapag hindi normal na pag-atake o natatamaan, alisin ang isang benepisyong epekto ng target; kung walang benepisyong epekto na aalisin, bawasan ang galit ng target ng $(50+skillLevel*0.7-0.7)$ puntos.',
		describe_ma = 'Apabila bukan serangan biasa atau diserang, buang satu kesan peningkatan daripada sasaran; jika tiada peningkatan untuk dibuang, kurangkan kemarahan sasaran sebanyak $(50+skillLevel*0.7-0.7)$ mata.',
		describe = 'When not performing a normal attack or being attacked, remove one beneficial effect from the target; if there is no beneficial effect to remove, reduce the target\'s rage by $(50+skillLevel*0.7-0.7)$ points.',
		starEffect = __data_t__starEffect[36826],
		-- {8}
		starEffectDesc_vn = 'Hiệu Ứng Bổ Sung: Khi Hải Sư Hoa Màu làm giảm năng lượng mục tiêu xuống dưới 350, có 100% xác suất <Mê Hoặc> trong 1 lượt (nếu năng lượng là 0 thì là 2 lượt), đồng thời hồi phục 50% Sát Thương Phép Thuật của bản thân.',
		starEffectDesc = 'Additional Effect: When the Colored Sea Lion reduces the target\'s energy below 350, there is a 100% chance to <Charm> for 1 turn (if energy is 0, then 2 turns), while recovering 50% of its own Magic Damage.',
		starEffectDesc_en = 'Additional Effect: When the Colored Sea Lion reduces the target\'s energy below 350, there is a 100% chance to <Charm> for 1 turn (if energy is 0, then 2 turns), while recovering 50% of its own Magic Damage.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อสิงโตทะเลสีสันลดพลังงานของเป้าหมายต่ำกว่า 350 มีโอกาส 100% ที่จะ <เสน่ห์> เป็นเวลา 1 เทิร์น (ถ้าพลังงานเป็น 0 จะเป็น 2 เทิร์น) พร้อมกับฟื้นฟูพลังโจมตีเวทมนตร์ของตัวเอง 50%',
		starEffectDesc_in = 'Efek Tambahan: Ketika Singa Laut Berwarna mengurangi energi target di bawah 350, ada kemungkinan 100% untuk <Mempesona> selama 1 giliran (jika energinya 0 maka 2 giliran), sekaligus memulihkan 50% dari Kerusakan Sihir miliknya sendiri.',
		starEffectDesc_ph = 'Karagdagang Epekto: Kapag nabawasan ng Colored Sea Lion ang enerhiya ng target sa ilalim ng 350, may 100% na pagkakataon na <Makitang-kahanga> sa loob ng 1 turn (kung ang enerhiya ay 0, maging 2 turn), kasabay ang paggaling ng 50% ng sariling Damage sa Magic.',
		starEffectDesc_ma = 'Kesan Tambahan: Apabila Singa Laut Berwarna mengurangkan tenaga sasaran di bawah 350, terdapat peluang 100% untuk <Mempesonakan> selama 1 pusingan (jika tenaga adalah 0 maka 2 pusingan), serta memulihkan 50% Kerosakan Sihir sendiri.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
