	[36832] = {
		id = 36832,
		skillName_vn = 'Nhược trí sóng âm',
		skillName_en = 'Hypersonic Wave',
		skillName_th = 'คลื่นเสียงความถี่สูง',
		skillName_in = 'Gelombang Hipersonik',
		skillName_ph = 'Hypersonic Wave',
		skillName_ma = 'Gelombang Hipersonik',
		skillName = 'Hypersonic Wave',
		describe_vn = 'Zombie Doremon nhỏ lấy ra một sản phẩm công nghệ cao và phát ra một làn sóng âm thanh yếu để tấn công một mục tiêu kẻ thù, gây ra #C0x3D8A99#160% Phép Công #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, sóng âm chậm phát triển tạo ra các vết phồng rộp [kiềm chế] và mục tiêu xếp hàng (kiềm chế: hiệu ứng khống chế, không thể sử dụng đòn tấn công thông thường), mục tiêu được giải phóng sau khi sử dụng các kỹ năng nhỏ hoặc chiêu thức đặc biệt, gây 100% Sát Thương Phép Thuật cho Dora Zombie nhỏ',
		describe_en = 'The small Zombie Doraemon pulls out a high-tech product and emits a weak sound wave to attack an enemy target, dealing #C0x3D8A99#160% Magical Attack #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. The slowly developing sound wave causes blisters [restrain] and the target is queued (restrain: a control effect, unable to use normal attacks). The target is freed after using minor skills or special moves, dealing 100% Magic Damage to the small Zombie Doraemon.',
		describe_th = 'ซอมบี้โดราเอมอนตัวเล็กดึงเอาอุปกรณ์เทคโนโลยีขั้นสูงออกมาและปล่อยคลื่นเสียงอ่อน ๆ เพื่อโจมตีเป้าหมายศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#160% #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# คลื่นเสียงที่ค่อย ๆ พัฒนาช้า ๆ ทำให้เกิดตุ่มพอง [ควบคุม] และเป้าหมายจะถูกจัดลำดับ (ควบคุม: ผลของการควบคุม ไม่สามารถใช้การโจมตีปกติได้) เป้าหมายจะถูกปลดปล่อยหลังจากใช้ทักษะเล็ก ๆ หรือท่าพิเศษ สร้างความเสียหายเวทมนตร์ 100% แก่ซอมบี้โดราเอมอนตัวเล็ก',
		describe_in = 'Zombie Doraemon kecil mengeluarkan produk teknologi tinggi dan memancarkan gelombang suara lemah untuk menyerang target musuh, menyebabkan #C0x3D8A99#160% Serangan Magis #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Magis #C0x5B545B#. Gelombang suara yang berkembang perlahan menyebabkan lepuhan [menahan] dan target masuk antrian (menahan: efek kontrol, tidak bisa menggunakan serangan biasa). Target akan dibebaskan setelah menggunakan keterampilan kecil atau gerakan khusus, menyebabkan 100% Kerusakan Magis pada Zombie Doraemon kecil.',
		describe_ph = 'Ang maliit na Zombie Doraemon ay kumukuha ng isang high-tech na produkto at nagpapalabas ng isang mahina na alon ng tunog upang atakihin ang isang kalabang target, na nagdudulot ng #C0x3D8A99#160% Magical Attack #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. Ang mabagal na pag-unlad ng sound wave ay nagdudulot ng mga blister [kontrol] at ang target ay naka-line up (kontrol: isang control effect, hindi maaaring gumamit ng normal na atake). Ang target ay mapapalaya pagkatapos gumamit ng mga maliit na kasanayan o espesyal na mga galaw, na nagdudulot ng 100% Magic Damage sa maliit na Zombie Doraemon.',
		describe_ma = 'Zombie Doraemon kecil mengeluarkan produk teknologi tinggi dan memancarkan gelombang bunyi lemah untuk menyerang sasaran musuh, menyebabkan #C0x3D8A99#160% Serangan Sihir #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#. Gelombang bunyi yang berkembang perlahan menyebabkan lepuhan [menahan] dan sasaran disusun dalam barisan (menahan: kesan kawalan, tidak dapat menggunakan serangan biasa). Sasaran akan dilepaskan selepas menggunakan kemahiran kecil atau gerakan khas, menyebabkan 100% Kerosakan Sihir kepada Zombie Doraemon kecil.',
		describe = 'The small Zombie Doraemon pulls out a high-tech product and emits a weak sound wave to attack an enemy target, dealing #C0x3D8A99#160% Magical Attack #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#. The slowly developing sound wave causes blisters [restrain] and the target is queued (restrain: a control effect, unable to use normal attacks). The target is freed after using minor skills or special moves, dealing 100% Magic Damage to the small Zombie Doraemon.',
		simDesc_vn = 'Thây ma Doremon nhỏ lấy ra các sản phẩm công nghệ cao và phát ra sóng âm thanh chậm phát triển trí tuệ để tấn công các mục tiêu đơn lẻ của kẻ thù.',
		simDesc_en = 'The small Doraemon zombie takes out high-tech products and emits slow-developing intellectual sound waves to attack individual enemy targets.',
		simDesc_th = 'ซอมบี้โดราเอมอนตัวเล็กหยิบผลิตภัณฑ์เทคโนโลยีขั้นสูงออกมาและปล่อยคลื่นเสียงพัฒนาช้าเพื่อโจมตีเป้าหมายเดี่ยวของศัตรู',
		simDesc_in = 'Zombi kecil Doraemon mengeluarkan produk teknologi tinggi dan memancarkan gelombang suara yang berkembang lambat untuk menyerang target musuh secara individu.',
		simDesc_ph = 'Ang maliit na Doraemon zombie ay kumuha ng mga high-tech na produkto at naglalabas ng mabagal na pag-unlad ng mga alon ng tunog upang atakihin ang mga indibidwal na target ng kaaway.',
		simDesc_ma = 'Zombi kecil Doraemon mengeluarkan produk teknologi tinggi dan memancarkan gelombang bunyi yang berkembang perlahan untuk menyerang sasaran musuh secara individu.',
