	[36833] = {
		id = 36833,
		skillName_vn = 'Bánh rán thịnh yến',
		skillName_en = 'Fortune Pancake',
		skillName_th = 'ขนมแพนเค้กโชคลาภ',
		skillName_in = 'Pancake Keberuntungan',
		skillName_ph = 'Swerte Pancake',
		skillName_ma = 'Pancake Nasib Baik',
		skillName = 'Fortune Pancake',
		describe_vn = 'Zombie Dora nhỏ chiêu đãi khách bữa tối, ném dorayaki tấn công mục tiêu ở hàng đầu của địch, gây ra #C0x3D8A99#260% Phép Công #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, giảm 200 điểm tức giận của mục tiêu và xua tan sự thiêu đốt của tất cả các anh hùng trên cánh đồng. Kẻ thù bị phân tán sẽ giảm thêm 600 điểm thịnh nộ, và nhóm bạn bị phân tán sẽ lấy lại 100% sinh mệnh từ đòn tấn công ma thuật của Dora Zombie nhỏ.',
		describe_en = 'Little Zombie Dora treats guests to dinner, throwing dorayaki to attack enemies in the front row, dealing #C0x3D8A99#260% Magic Attack #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, reducing the target\'s rage by 200 points and dispelling the burn status of all heroes on the field. Scattered enemies will have an additional 600 rage reduction, and scattered allies will recover 100% HP from Little Zombie Dora\'s magic attack.',
		describe_th = 'โดราเล็กซอมบี้เลี้ยงรับประทานอาหารค่ำ โดยขว้างโดรายากิโจมตีเป้าหมายในแถวหน้า ทำความเสียหาย #C0x3D8A99#260% พลังเวท #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวท #C0x5B545B# ลดความโกรธของเป้าหมาย 200 แต้มและขจัดสถานะไฟไหม้ของฮีโร่ทั้งหมดในสนาม ศัตรูที่กระจัดกระจายจะถูกลดความโกรธเพิ่มอีก 600 แต้ม และพันธมิตรที่กระจัดกระจายจะฟื้นฟูพลังชีวิต 100% จากการโจมตีเวทของโดราเล็กซอมบี้',
		describe_in = 'Zombie Dora kecil menyajikan makan malam, melempar dorayaki untuk menyerang target di barisan depan musuh, memberikan #C0x3D8A99#260% Serangan Magic #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Magic #C0x5B545B#, mengurangi kemarahan target sebanyak 200 poin dan menghilangkan terbakar dari semua pahlawan di medan. Musuh yang tersebar akan mengurangi kemarahan tambahan sebesar 600 poin, dan grup teman yang tersebar akan memulihkan 100% HP dari serangan magic Zombie Dora kecil.',
		describe_ph = 'Maliit na Zombie Dora ay naghahain ng hapunan, naghahagis ng dorayaki upang atakihin ang mga target sa unahan ng kaaway, na nagdudulot ng #C0x3D8A99#260% Magic Attack #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, nagpapabawas ng 200 puntos ng galit ng target at tinatanggal ang nasunog na epekto ng lahat ng mga bayani sa larangan. Ang mga kalaban na nagkakawatak-watak ay magkakaroon ng karagdagang 600 puntos na bawas sa galit, at ang mga kasamang nagkakawatak-watak ay makakabawi ng 100% HP mula sa magic attack ng Maliit na Zombie Dora.',
		describe_ma = 'Zombie Dora kecil menghidangkan makan malam, melempar dorayaki menyerang sasaran di barisan hadapan musuh, menyebabkan #C0x3D8A99#260% Serangan Sihir #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, mengurangkan 200 mata kemarahan sasaran dan menghilangkan kesan terbakar dari semua wira di medan. Musuh yang berselerak akan kehilangan tambahan 600 mata kemarahan, dan kumpulan rakan yang berselerak akan mendapat kembali 100% nyawa dari serangan sihir Zombie Dora kecil.',
		describe = 'Little Zombie Dora treats guests to dinner, throwing dorayaki to attack enemies in the front row, dealing #C0x3D8A99#260% Magic Attack #C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, reducing the target\'s rage by 200 points and dispelling the burn status of all heroes on the field. Scattered enemies will have an additional 600 rage reduction, and scattered allies will recover 100% HP from Little Zombie Dora\'s magic attack.',
		simDesc_vn = 'Thây ma Doremon nhỏ ném dorayaki để tấn công các mục tiêu ở hàng đầu của kẻ thù.',
		simDesc_en = 'The small Doraemon zombie throws dorayaki to attack the front row targets of the enemy.',
		simDesc_th = 'ซอมบี้โดเรม่อนตัวเล็กขว้างโดรายากิเพื่อโจมตีเป้าหมายแถวหน้าของศัตรู',
		simDesc_in = 'Zombie Doraemon kecil melempar dorayaki untuk menyerang target barisan depan musuh.',
		simDesc_ph = 'Ang maliit na Doraemon na zombie ay naghahagis ng dorayaki upang atakihin ang mga target sa unahang hilera ng kaaway.',
		simDesc_ma = 'Zombie Doraemon kecil melempar dorayaki untuk menyerang sasaran barisan hadapan musuh.',
