	[36836] = {
		id = 36836,
		skillName_vn = 'Doraemon',
		skillName_en = 'Doraemon',
		skillName_th = 'โดราเอมอน',
		skillName_in = 'Doraemon',
		skillName_ph = 'Doraemon',
		skillName_ma = 'Doraemon',
		skillName = 'Doraemon',
		describe_vn = 'Khi không phải công thường hoặc bị tấn công, xóa bỏ một hiệu quả tăng ích của mục tiêu, nếu không có tăng ích để xóa bỏ, giảm#C0x5c9970#$(50+skillLevel*0.7-0.7)$#C0x5B545B# điểm nộ khí của mục tiêu',
		describe_en = 'When not performing a normal attack or being attacked, remove one beneficial effect from the target; if there is no beneficial effect to remove, reduce the target\'s chakra by #(50+skillLevel*0.7-0.7) points.',
		describe_th = 'เมื่อใช้การโจมตีที่ไม่ใช่การโจมตีปกติหรือเมื่อถูกโจมตี จะลบเอฟเฟกต์เสริม 1 อย่างออกจากเป้าหมาย หากไม่มีเอฟเฟกต์ให้ลบ จะลดค่าโทสะของเป้าหมายลง #C0x5c9970#$(50+skillLevel*0.7-0.7)$#C0x5B545B# หน่วย',
		describe_in = 'Saat bukan serangan biasa atau sedang diserang, hapus satu efek manfaat dari target; jika tidak ada efek manfaat yang bisa dihapus, kurangi chakra target sebanyak #(50+skillLevel*0.7-0.7) poin.',
		describe_ph = 'Kapag hindi normal na atake o naaatake, alisin ang isang benepisyong epekto ng target; kung walang benepisyong epekto na aalisin, bawasan ang chakra ng target ng #(50+skillLevel*0.7-0.7) puntos.',
		describe_ma = 'Apabila bukan serangan biasa atau diserang, buang satu kesan peningkatan daripada sasaran; jika tiada kesan peningkatan untuk dibuang, kurangkan tenaga chakra sasaran sebanyak #(50+skillLevel*0.7-0.7) mata.',
		describe = 'When not performing a normal attack or being attacked, remove one beneficial effect from the target; if there is no beneficial effect to remove, reduce the target\'s chakra by #(50+skillLevel*0.7-0.7) points.',
		starEffect = __data_t__starEffect[36836],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng thêm: Tiểu Dora Zombie khiến mục tiêu giảm nộ khí xuống dưới 350 điểm, 100% tỷ lệ <Mê hoặc> mục tiêu đó trong 1 hiệp (2 hiệp nếu nộ khí bằng 0), đồng thời hồi cho bản thân lượng máu bằng 50% Công Phép.',
		starEffectDesc = 'Additional effect: Little Dora Zombie causes the target\'s rage to drop below 350 points, with a 100% chance to <Charm> the target for 1 turn (2 turns if rage is 0), while simultaneously healing itself for 50% of Magic Power.',
		starEffectDesc_en = 'Additional effect: Little Dora Zombie causes the target\'s rage to drop below 350 points, with a 100% chance to <Charm> the target for 1 turn (2 turns if rage is 0), while simultaneously healing itself for 50% of Magic Power.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อลิตเติ้ลโดราเอม่อนซอมบี้ทำให้ค่าโทสะของเป้าหมายลดลงต่ำกว่า 350 จะมีโอกาส 100% ที่จะทำให้เป้าหมายติดสถานะ [เสน่ห์] เป็นเวลา 1 เทิร์น (หากโทสะของเป้าหมายเป็น 0 จะติด [เสน่ห์] นาน 2 เทิร์น) และจะฟื้นฟูพลังชีวิตให้ตนเองเท่ากับ 50% ของพลังโจมตีเวท',
		starEffectDesc_in = 'Efek tambahan: Little Dora Zombie membuat target turun amarahnya di bawah 350 poin, dengan peluang 100% untuk <Mempesona> target tersebut selama 1 giliran (2 giliran jika amarah 0), sekaligus menyembuhkan diri sendiri sebesar 50% dari Kekuatan Sihir.',
		starEffectDesc_ph = 'Karagdagang epekto: Ang Little Dora Zombie ay nagpababa sa galit ng target sa ilalim ng 350 puntos, may 100% na tsansa na <Makitang-mali> ang target sa loob ng 1 turn (2 turn kung galit ay 0), habang nagpapagaling ng sarili ng katumbas ng 50% ng Magic Power.',
		starEffectDesc_ma = 'Kesan tambahan: Little Dora Zombie menyebabkan sasaran mengurangkan kemarahan di bawah 350 mata, dengan peluang 100% untuk <Memikat> sasaran itu selama 1 giliran (2 giliran jika kemarahan adalah 0), dan pada masa yang sama memulihkan diri sendiri dengan 50% Kuasa Sihir.',
		iconRes = 'battle/skill_icon/skill_36836.png',
