		skillName_in = 'Retakan air',
		skillName_ph = 'Bitak ng tubig',
		skillName_ma = 'Retakan air',
		skillName = 'Water crack',
		describe_vn = 'Ngôi sao tốt xấu sử dụng sức mạnh của nước để tấn công mục tiêu đơn lẻ của kẻ địch, gây #C0xE69900#150% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, đồng thời giúp các bộ phận bị tổn thương của bản thân nhanh chóng tái sinh: hồi phục lượng máu bằng (5%+số mục tiêu trúng độc trong đội hình địch*5%) giới hạn máu của bản thân',
		describe_en = 'The Good and Bad Star uses the power of water to attack a single enemy target, dealing #C0xE69900#150% Physical Attack#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, while also helping its own damaged parts rapidly regenerate: restoring health equal to (5% + number of poisoned targets in the enemy formation * 5%) of its maximum health.',
		describe_th = 'ดาวดีและร้ายใช้พลังน้ำโจมตีเป้าหมายศัตรูทีละตัว สร้างความเสียหาย #C0xE69900#150% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# พร้อมทั้งช่วยส่วนที่ได้รับบาดเจ็บของตัวเองฟื้นฟูอย่างรวดเร็ว: ฟื้นฟูพลังชีวิตเท่ากับ (5% + จำนวนเป้าหมายติดพิษในทีมศัตรู * 5%) ของพลังชีวิตสูงสุดของตัวเอง',
		describe_in = 'Bintang Baik dan Buruk menggunakan kekuatan air untuk menyerang satu target musuh, memberikan #C0xE69900#150% Serangan Fisik#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, sekaligus membantu bagian tubuh yang terluka pada dirinya sendiri cepat beregenerasi: memulihkan kesehatan sebesar (5% + jumlah target yang terkena racun dalam formasi musuh * 5%) dari maksimal kesehatannya.',
		describe_ph = 'Ginagamit ng Good and Bad Star ang kapangyarihan ng tubig upang atakihin ang isang target na kalaban, na nagdudulot ng #C0xE69900#150% Physical Attack#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, kasabay ng pagtulong sa mga nasirang bahagi ng sarili upang mabilis na makapag-regenerate: nagpapagaling ng HP na katumbas ng (5% + bilang ng mga target na na-poison sa porma ng kalaban * 5%) ng sariling maximum HP.',
		describe_ma = 'Bintang Baik dan Buruk menggunakan kuasa air untuk menyerang sasaran musuh tunggal, menyebabkan #C0xE69900#150% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, sekaligus membantu bahagian-bahagian yang cedera pada dirinya cepat pulih: memulihkan jumlah darah sebanyak (5% + bilangan sasaran yang terkena racun dalam formasi musuh * 5%) had darah maksimum dirinya.',
		describe = 'The Good and Bad Star uses the power of water to attack a single enemy target, dealing #C0xE69900#150% Physical Attack#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, while also helping its own damaged parts rapidly regenerate: restoring health equal to (5% + number of poisoned targets in the enemy formation * 5%) of its maximum health.',
		simDesc_vn = 'Tốt Xấu Tinh sử dụng sức mạnh của nước để va vào mục tiêu đơn lẻ của kẻ thù.',
		simDesc_en = 'Good Evil Spirit uses the power of water to strike a single enemy target.',
		simDesc_th = 'เทพแห่งความดีความชั่วใช้พลังของน้ำในการโจมตีเป้าหมายศัตรูเดี่ยว',
		simDesc_in = 'Roh Baik Jahat menggunakan kekuatan air untuk menyerang satu target musuh.',
		simDesc_ph = 'Ang Mabuting Masamang Espiritu ay gumagamit ng kapangyarihan ng tubig upang tamaan ang isang kalabang target.',
		simDesc_ma = 'Roh Baik Jahat menggunakan kekuatan air untuk menyerang satu sasaran musuh.',
		simDesc = 'Good Evil Spirit uses the power of water to strike a single enemy target.',
		zawakeEffect = __data_t__zawakeEffect[37712],
		-- {79002}
		zawakeEffectDesc = 'Hảo Hoại Tinh uses the power of water to strike a single enemy target, dealing #C0xE69900#150% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ Physical Damage#C0xF13B54#, causing the damaged part of oneself to quickly regenerate: restoring health equal to (8% + number of poisoned targets in enemy team * 6%) of own max health',
		zawakeEffectDesc_en = 'Hảo Hoại Tinh uses the power of water to strike a single enemy target, dealing #C0xE69900#150% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ Physical Damage#C0xF13B54#, causing the damaged part of oneself to quickly regenerate: restoring health equal to (8% + number of poisoned targets in enemy team * 6%) of own max health',
		zawakeEffectDesc_th = 'Hảo Hoại Tinh ใช้พลังน้ำโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0xE69900#150% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ ความเสียหายทางกายภาพ#C0xF13B54# ทำให้ส่วนที่ได้รับความเสียหายของตัวเองฟื้นฟูอย่างรวดเร็ว: ฟื้นฟูพลังชีวิตเท่ากับ (8% + จำนวนเป้าหมายที่ติดพิษในทีมศัตรู * 6%) ของพลังชีวิตสูงสุดของตนเอง',
		zawakeEffectDesc_in = 'Hảo Hoại Tinh menggunakan kekuatan air untuk menyerang satu target musuh, memberikan #C0xE69900#150% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ Kerusakan Fisik#C0xF13B54#, menyebabkan bagian yang terluka pada dirinya sendiri cepat sembuh: memulihkan kesehatan sebesar (8% + jumlah target yang terkena racun dalam tim musuh * 6%) dari batas maksimal kesehatannya sendiri',
		zawakeEffectDesc_ph = 'Gamit ng Hảo Hoại Tinh ang kapangyarihan ng tubig upang tamaan ang isang target na kalaban, nagdudulot ng #C0xE69900#150% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*48)$ Pisikal na Pinsala#C0xF13B54#, dahilan upang ang nasirang bahagi ng sarili ay mabilis na gumaling: nagpapagaling ng buhay na katumbas ng (8% + dami ng mga target na may lason sa kalabang koponan * 6%) ng sariling maximum na buhay',
		zawakeEffectDesc_ma = 'Hảo Hoại Tinh menggunakan kekuatan air untuk menyerang satu sasaran musuh, memberikan #C0xE69900#150% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ Kerosakan Fizikal#C0xF13B54#, menyebabkan bahagian yang cedera pada dirinya sendiri cepat sembuh: memulihkan kesihatan sebanyak (8% + bilangan sasaran yang terkena racun dalam pasukan musuh * 6%) daripada had maksima kesihatan dirinya sendiri',
		zawakeEffectDesc_vn = 'Hảo Hoại Tinh dùng sức mạnh của nước va chạm vào mục tiêu đơn lẻ của kẻ địch, gây ra #C0xE69900#150% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ Sát Thương Vật Lý#C0xF13B54#，khiến phần bị tổn thương của bản thân nhanh chóng tái sinh: hồi phục lượng máu bằng (8%+số mục tiêu trúng độc trong đội hình địch*6%) giới hạn máu của bản thân',
		zawakeSimpleType = 2,
