	[37723] = {
		id = 37723,
		skillName_vn = 'Đè nén như núi Thái Sơn',
		skillName_en = 'Press down like Mount Tai',
		skillName_th = 'กดทับเหมือนภูเขาไท่ซาน',
		skillName_in = 'Menekan seperti Gunung Tai',
		skillName_ph = 'Pindutin tulad ng Bundok Tai',
		skillName_ma = 'Tekan seperti Gunung Tai',
		skillName = 'Press down like Mount Tai',
		describe_vn = 'Shrek Zombie nhảy lên không trung, ép thân hình to lớn của nó lên tất cả mục tiêu địch, gây #C0xE69900#160% Vật công #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, áp dụng một lớp [ngộ độc] lên tất cả mục tiêu trong 3 lượt (ngộ độc: tác động tiêu cực, mỗi lớp ngộ độc gây ra hiệu ứng mục tiêu để giảm 40% sát thương thực sự của phòng thủ kép và phòng thủ kép của Shrek Zombie trước khi bắt đầu vòng đấu, tối đa 5 lớp), đồng thời tăng xác suất kích hoạt Sting Bunker lên 40% trong 2 hiệp',
		describe_en = 'Shrek Zombie leaps into the air, smashing its massive body onto all enemy targets, dealing #C0xE69900#160% Physical Attack #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage #C0x5B545B#, applying a [poison] stack to all targets for 3 turns (poison: a negative effect, each poison stack reduces the actual damage of Double Defense and Shrek Zombie\'s Double Defense by 40% before the start of the round, up to 5 stacks), and simultaneously increases the chance to activate Sting Bunker by 40% for 2 rounds.',
		describe_th = 'Shrek Zombie กระโดดขึ้นกลางอากาศ บีบตัวโตของมันใส่เป้าหมายศัตรูทั้งหมด สร้างความเสียหาย #C0xE69900#160% พลังโจมตี #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# และใช้เอฟเฟกต์ [พิษ] กับเป้าหมายทั้งหมดเป็นเวลา 3 ตา (พิษ: ผลเสีย แต่ละชั้นพิษทำให้เป้าหมายลดความเสียหายจริงของเกราะคู่และเกราะคู่ของ Shrek Zombie ลง 40% ก่อนเริ่มรอบ สูงสุด 5 ชั้น) พร้อมเพิ่มโอกาสเปิดใช้งาน Sting Bunker ขึ้น 40% เป็นเวลา 2 ตา',
		describe_in = 'Shrek Zombie melompat ke udara, menekan tubuh besar mereka ke semua target musuh, memberikan #C0xE69900#160% Serangan Fisik #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#, menerapkan lapisan [racun] pada semua target selama 3 giliran (racun: efek negatif, setiap lapisan racun mengurangi kerusakan nyata Pertahanan Ganda dan Pertahanan Ganda Shrek Zombie sebesar 40% sebelum ronde dimulai, hingga maksimal 5 lapisan), dan sekaligus meningkatkan peluang mengaktifkan Sting Bunker sebesar 40% selama 2 giliran.',
		describe_ph = 'Tumalon ang Shrek Zombie sa himpapawid, pinipisil ang malaking katawan nito sa lahat ng mga kalaban, nagdudulot ng #C0xE69900#160% Pisikal na Atake #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, naglalagay ng isang tiktik na [pagkalason] sa lahat ng mga target sa loob ng 3 na turn (pagkalason: negatibong epekto, bawat tiktik ng pagkalason ay nagpapababa ng aktwal na pinsala mula sa Double Defense at sa Double Defense ng Shrek Zombie ng 40% bago magsimula ang turno, hanggang sa 5 tiktik), kasabay nito ay nagpapataas ng tsansa na ma-activate ang Sting Bunker ng 40% sa loob ng 2 rounds.',
		describe_ma = 'Shrek Zombie melompat ke udara, menekan tubuh besar itu ke semua sasaran musuh, menyebabkan #C0xE69900#160% Serangan Fizikal #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, mengenakan satu lapisan [racun] pada semua sasaran selama 3 pusingan (racun: kesan negatif, setiap lapisan racun menyebabkan sasaran mengurangkan kerosakan sebenar Pertahanan Berganda dan Pertahanan Berganda Shrek Zombie sebanyak 40% sebelum permulaan pusingan, maksimum 5 lapisan), dan pada masa yang sama meningkatkan kebarangkalian mengaktifkan Sting Bunker sebanyak 40% selama 2 pusingan.',
		describe = 'Shrek Zombie leaps into the air, smashing its massive body onto all enemy targets, dealing #C0xE69900#160% Physical Attack #C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage #C0x5B545B#, applying a [poison] stack to all targets for 3 turns (poison: a negative effect, each poison stack reduces the actual damage of Double Defense and Shrek Zombie\'s Double Defense by 40% before the start of the round, up to 5 stacks), and simultaneously increases the chance to activate Sting Bunker by 40% for 2 rounds.',
		starEffect = __data_t__starEffect[37723],
		-- {11}
		starEffectDesc_vn = 'Hiệu Ứng Bổ Sung: Có 35% xác suất khiêu khích mục tiêu trong 1 lượt.',
		starEffectDesc = 'Additional Effect: 35% chance to provoke the target for 1 turn.',
		starEffectDesc_en = 'Additional Effect: 35% chance to provoke the target for 1 turn.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: มีโอกาส 35% ในการล่อเป้าหมายเป็นเวลา 1 เทิร์น',
		starEffectDesc_in = 'Efek Tambahan: 35% peluang untuk memprovokasi target selama 1 giliran.',
		starEffectDesc_ph = 'Karagdagang Epekto: 35% na tsansa na mag-udyok sa target sa loob ng 1 turn.',
		starEffectDesc_ma = 'Kesan Tambahan: 35% peluang untuk menggoda sasaran selama 1 pusingan.',
		zawakeEffect = __data_t__zawakeEffect[37723],
		-- {79003}
		zawakeEffectDesc = 'Shrek Zombie jumps into the air, its massive body crushing all enemy targets, dealing #C0xE69900#160% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54#Physical Damage#C0x5B545B#, while applying the <Poisoned> effect to all targets for 3 turns (Poisoned: a negative effect, each layer causes the target to take true damage equal to 40% of Shrek Zombie\'s total defense at the start of each turn, up to 5 layers), increases the chance to activate the toxic spiked fortress by 40% for 2 turns and increases flat damage reduction by 10% for self for 2 turns.',
		zawakeEffectDesc_en = 'Shrek Zombie jumps into the air, its massive body crushing all enemy targets, dealing #C0xE69900#160% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54#Physical Damage#C0x5B545B#, while applying the <Poisoned> effect to all targets for 3 turns (Poisoned: a negative effect, each layer causes the target to take true damage equal to 40% of Shrek Zombie\'s total defense at the start of each turn, up to 5 layers), increases the chance to activate the toxic spiked fortress by 40% for 2 turns and increases flat damage reduction by 10% for self for 2 turns.',
		zawakeEffectDesc_th = 'เชร็คซอมบี้กระโดดขึ้นสู่ท้องฟ้า ร่างกายขนาดมหึมาทับเป้าหมายศัตรูทั้งหมด สร้างความเสียหาย #C0xE69900#160% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# พร้อมทั้งสร้างสถานะ <ถูกพิษ> ให้เป้าหมายทั้งหมดเป็นเวลา 3 เทิร์น (ถูกพิษ: สถานะลบ แต่ละชั้นทำให้เป้าหมายได้รับความเสียหายจริงเท่ากับ 40% ของค่าพลังป้องกันรวมของเชร็คซอมบี้ในตอนเริ่มต้นแต่ละเทิร์น สูงสุด 5 ชั้น) เพิ่มโอกาสในการเปิดใช้งานป้อมแหลมพิษขึ้น 40% เป็นเวลา 2 เทิร์น และเพิ่มการลดความเสียหายตรง 10% ให้กับตัวเองเป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Shrek Zombie melompat ke udara, tubuhnya yang besar menghancurkan semua target musuh, memberikan #C0xE69900#160% Serangan Fisik#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, sekaligus memberikan efek <Diracuni> pada semua target selama 3 giliran (Diracuni: efek negatif, setiap lapisan menyebabkan target menerima damage nyata sebesar 40% dari total pertahanan Shrek Zombie di awal setiap giliran, maksimal 5 lapisan), meningkatkan peluang aktifkan benteng berduri beracun sebesar 40% selama 2 giliran dan meningkatkan pengurangan damage flat sebesar 10% untuk diri sendiri selama 2 giliran.',
		zawakeEffectDesc_ph = 'Tumalon ang Shrek Zombie sa hangin, ang dambuhalang katawan nito ay dinudurog ang lahat ng mga kaaway na target, nagdudulot ng #C0xE69900#160% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#, kasabay nito ay naglalagay ng <Napatamaan ng Lason> na epekto sa lahat ng target sa loob ng 3 turn (Napatamaan ng Lason: isang negatibong epekto, bawat patong ay nagpapadagdag ng tunay na pinsala na katumbas ng 40% ng kabuuang depensa ng Shrek Zombie sa simula ng bawat turn, hanggang 5 patong), pinapataas ang tsansa na ma-activate ang nakalalason na matutulis na kuta ng 40% sa loob ng 2 turn at pinapataas ang 10% bawas pinsala para sa sarili sa loob ng 2 turn.',
		zawakeEffectDesc_ma = 'Shrek Zombie melompat ke udara, badannya yang besar memijak semua sasaran musuh, menyebabkan #C0xE69900#160% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B#, serentak memberi kesan <Diracun> kepada semua sasaran selama 3 pusingan (Diracun: kesan negatif, setiap lapisan menyebabkan sasaran menerima kerosakan sebenar bersamaan 40% jumlah pertahanan Shrek Zombie pada awal setiap pusingan, maksimum 5 lapisan), meningkatkan peluang mengaktifkan kota berduri beracun sebanyak 40% selama 2 pusingan dan meningkatkan pengurangan kerosakan rata sebanyak 10% untuk diri sendiri selama 2 pusingan.',
		zawakeEffectDesc_vn = 'Shrek Zombie nhảy lên không trung, thân hình đồ sộ đè xuống toàn bộ mục tiêu địch, gây #C0xE69900#160% Công Vật Lý#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, đồng thời gây hiệu ứng  <Trúng độc>  lên tất cả mục tiêu trong 3 lượt (Trúng độc: hiệu ứng bất lợi, mỗi tầng trúng độc khiến mục tiêu chịu sát thương chuẩn bằng 40% tổng phòng thủ của Shrek Zombie vào đầu mỗi lượt, tối đa 5 tầng), tăng 40% xác suất kích hoạt pháo đài gai độc trong 2 lượt và tăng 10% giảm sát thương tất sát cho bản thân trong 2 lượt.',
		zawakeSimpleType = 1,
