	[40231] = {
		id = 40231,
		skillName_vn = 'Linh hồn - Tấn công Bảo Cụ',
		skillName_en = 'Soul - Attack Artifact',
		skillName_th = 'วิญญาณ - โจมตีเครื่องมือ',
		skillName_in = 'Jiwa - Serang Artefak',
		skillName_ph = 'Kaluluwa - Atake Artifact',
		skillName_ma = 'Jiwa - Serang Artifak',
		skillName = 'Soul - Attack Artifact',
		describe_vn = 'Super Gilgamesh sử dụng Bảo Khí của mình để tấn công một mục tiêu kẻ thù, gây ra #C0xE69900#150% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4 *24)$ #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, giúp tăng khả năng phòng thủ kép của bản thân lên 40% và 10% giới hạn sinh mệnh trên (không vượt quá 300% đòn Sát Thương Vật Lý của bản thân) trong 2 lượt. Nó không thể được chồng lên nhau.',
		describe_en = 'Super Gilgamesh uses his Treasure Weapon to attack an enemy target, dealing #C0xE69900#150% Physical Damage#C0x5B545B#+$(skillLevel*4 *24)$ #C0xF13B54# Physical Damage #C0x5B545B#, increases his dual defense ability by 40% and raises maximum health by 10% (not exceeding 300% of his Physical Damage) for 2 turns. This effect cannot be stacked.',
		describe_th = 'Super Gilgamesh ใช้อาวุธวิเศษของเขาโจมตีเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#150%#C0x5B545B#+$(skillLevel*4 *24)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B#, ช่วยเพิ่มความสามารถป้องกันคู่ของตัวเองขึ้น 40% และเพิ่มขีดจำกัดพลังชีวิตสูงสุด 10% (ไม่เกิน 300% ของความเสียหายทางกายภาพของตนเอง) เป็นเวลา 2 เทิร์น ไม่สามารถซ้อนทับได้',
		describe_in = 'Super Gilgamesh menggunakan Senjata Khazannya untuk menyerang satu target musuh, memberikan #C0xE69900#150% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4 *24)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#, meningkatkan kemampuan pertahanan ganda dirinya sebesar 40% dan menambah batas maksimum kesehatan sebesar 10% (tidak melebihi 300% Kerusakan Fisik miliknya) selama 2 giliran. Efek ini tidak dapat ditumpuk.',
		describe_ph = 'Gumagamit si Super Gilgamesh ng kanyang Treasure Weapon upang atakihin ang isang kalabang target, nagdudulot ng #C0xE69900#150% Physical Damage#C0x5B545B#+$(skillLevel*4 *24)$ #C0xF13B54# Physical Damage #C0x5B545B#, tumataas ang kanyang kakayahan sa dobleng depensa ng 40% at ang maximum health limit ay tataas ng 10% (hindi lalampas sa 300% ng kanyang Physical Damage) sa loob ng 2 turn. Hindi ito maaaring ma-stack.',
		describe_ma = 'Super Gilgamesh menggunakan Senjata Khazannya untuk menyerang satu sasaran musuh, memberikan #C0xE69900#150% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4 *24)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, meningkatkan keupayaan pertahanan berganda dirinya sebanyak 40% dan menaikkan had maksimum kesihatan sebanyak 10% (tidak melebihi 300% Kerosakan Fizikal dirinya) selama 2 pusingan. Ia tidak boleh bertindih.',
		describe = 'Super Gilgamesh uses his Treasure Weapon to attack an enemy target, dealing #C0xE69900#150% Physical Damage#C0x5B545B#+$(skillLevel*4 *24)$ #C0xF13B54# Physical Damage #C0x5B545B#, increases his dual defense ability by 40% and raises maximum health by 10% (not exceeding 300% of his Physical Damage) for 2 turns. This effect cannot be stacked.',
		zawakeEffect = __data_t__zawakeEffect[40231],
		-- {79001}
		zawakeEffectDesc = 'Super Gilgamesh uses his Weapon to attack an enemy target, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ to that single target. F13B54#Physical Damage#C0x5B545B#, increases self-defense by 40% and max HP by 10% (not exceeding 500% of own Physical Damage) for 2 turns, cannot be stacked. When this skill is used to counterattack, damage increases by 10%.',
		zawakeEffectDesc_en = 'Super Gilgamesh uses his Weapon to attack an enemy target, dealing #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ to that single target. F13B54#Physical Damage#C0x5B545B#, increases self-defense by 40% and max HP by 10% (not exceeding 500% of own Physical Damage) for 2 turns, cannot be stacked. When this skill is used to counterattack, damage increases by 10%.',
		zawakeEffectDesc_th = 'ซูเปอร์กิลกาเมชใช้อาวุธของเขาโจมตีเป้าหมายศัตรูหนึ่งตัว สร้าง #C0xE69900#180% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ แก่เป้าหมายเดี่ยว F13B54#ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มความสามารถในการป้องกันตัวเอง 40% และพลังชีวิตสูงสุดเพิ่ม 10% (ไม่เกิน 500% ของความเสียหายทางกายภาพของตัวเอง) เป็นเวลา 2 เทิร์น ไม่สามารถซ้อนทับได้ เมื่อทักษะนี้ถูกใช้เพื่อต่อกร ความเสียหายจะเพิ่มขึ้น 10%',
		zawakeEffectDesc_in = 'Super Gilgamesh menggunakan Senjatanya untuk menyerang satu target musuh, memberikan #C0xE69900#180% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*24)$ kepada target tunggal tersebut. F13B54#Kerusakan Fisik#C0x5B545B#, meningkatkan pertahanan diri sebesar 40% dan HP maksimum sebesar 10% (tidak melebihi 500% dari Kerusakan Fisik sendiri) selama 2 giliran, tidak bisa ditumpuk. Ketika skill ini digunakan untuk menyerang balik, kerusakan akan bertambah 10%.',
		zawakeEffectDesc_ph = 'Ginagamit ni Super Gilgamesh ang kanyang Weapon para atakihin ang isang target na kaaway, na nagdudulot ng #C0xE69900#180% Physical Damage#C0x5B545B#+$(skillLevel*4*24)$ sa iisang target. F13B54#Physical Damage#C0x5B545B#, pinapataas ang sariling defense ng 40% at max HP ng 10% (hindi lalampas sa 500% ng sariling Physical Damage) sa loob ng 2 rounds, hindi maaaring pagdugtungin. Kapag ginamit ang skill na ito bilang counterattack, tumataas ng 10% ang damage.',
		zawakeEffectDesc_ma = 'Super Gilgamesh menggunakan Senjatanya untuk menyerang satu sasaran musuh, memberikan #C0xE69900#180% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ kepada sasaran tunggal tersebut. F13B54#Kerosakan Fizikal#C0x5B545B#, meningkatkan pertahanan diri sebanyak 40% dan HP maksimum sebanyak 10% (tidak melebihi 500% daripada Kerosakan Fizikal sendiri) selama 2 pusingan, tidak boleh bertindih. Apabila kemahiran ini digunakan untuk membalas serangan, kerosakan akan meningkat sebanyak 10%.',
		zawakeEffectDesc_vn = 'Super Gilgamesh sử dụng Bảo Khí của mình để tấn công một mục tiêu kẻ thù, gây ra #C0xE69900#180% đòn Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ cho mục tiêu đơn lẻ đó. F13B54#Sát Thương Vật Lý#C0x5B545B#, tăng khả năng tự vệ thêm 40% và máu tối đa thêm 10% (không vượt quá 500% sức Sát Thương Vật Lý của bản thân) trong 2 lượt, không thể chồng chất. Khi kỹ năng này được sử dụng để phản công, sát thương sẽ tăng thêm 10%.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'When this skill is used as a counterattack, damage increases by 10%  ',
		zawakeSimpleDesc_en = 'When this skill is used as a counterattack, damage increases by 10%  ',
		zawakeSimpleDesc_th = 'เมื่อใช้สกิลนี้เป็นการโต้กลับ ความเสียหายจะเพิ่มขึ้น 10%',
		zawakeSimpleDesc_in = 'Jika skill ini digunakan sebagai serangan balasan, damage bertambah 10%  ',
		zawakeSimpleDesc_ph = 'Kapag ginamit ang skill na ito bilang counter, tumataas ang damage ng 10%  ',
		zawakeSimpleDesc_ma = 'Apabila kemahiran ini digunakan sebagai serangan balas, kerosakan meningkat sebanyak 10%  ',
		zawakeSimpleDesc_vn = 'Khi kỹ năng này được sử dụng làm phản kích, sát thương tăng thêm 10%',
		upLvDesc = 'Fix damage +96',
