	[40232] = {
		id = 40232,
		skillName_vn = 'Linh hồn - Kho báu của vua',
		skillName_en = 'Soul - The King\'s Treasure',
		skillName_th = 'วิญญาณ - ขุมทรัพย์ของกษัตริย์',
		skillName_in = 'Jiwa - Harta Raja',
		skillName_ph = 'Kaluluwa - Kayamanan ng Hari',
		skillName_ma = 'Jiwa - Harta Raja',
		skillName = 'Soul - The King\'s Treasure',
		describe_vn = 'Super Gilgamesh nhảy lên trời, khiến hàng ngàn bảo vật biến thành sấm sét, gây #C0xE69900#100% Sát Thương Vật Lý + 100% phòng thủ vật lý #C0x5B545B#+$(skillLevel*4*48)$ thuộc số #C0xF13B54# Sát Thương Vật Lý #C0x5B545B# lên tất cả mục tiêu kẻ địch, tăng khả năng giảm sát thương thực của bản thân thêm 50% cho 2 lượt và cho các đơn vị thân thiện loại Siêu/Quỷ trong cùng một hàng sẽ thêm hiệu ứng [Cùng kẻ thù] trong 2 lượt\n#F10#\n#F40#[Cùng kẻ thù]: một hiệu ứng buff đặc biệt sẽ kích hoạt hiệu ứng phản công của Super Gilgamesh [Bệ hạ] khi nhận các đòn tấn công chủ động; nhận được [Áo giáp lửa mặt trời] trong thời gian hiệu lực và nếu bạn ở hàng trước, bạn sẽ được giảm thêm 30% sát thương, và nếu ở hàng sau, bạn sẽ nhận được thêm 30% sát thương cộng thêm.',
		describe_en = 'Super Gilgamesh leaps into the sky, turning thousands of treasures into thunder, dealing #C0xE69900#100% Physical Damage + 100% physical defense #C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage #C0x5B545B# to all enemy targets, increasing self true damage reduction by 50% for 2 turns and granting allied units of type Super/Demon in the same row the effect [With the Enemy] for 2 turns. [With the Enemy]: a special buff effect that triggers Super Gilgamesh [Majesty]\'s counterattack effect when receiving active attack hits; gain [Solar Flame Armor] during the effect duration and if you are in the front row, receive an additional 30% damage reduction, and if in the back row, receive an additional 30% bonus damage.',
		describe_th = 'ซูเปอร์กิลกาเมชกระโดดขึ้นสู่ท้องฟ้า ทำให้สมบัตินับพันกลายเป็นฟ้าร้อง สร้าง #C0xE69900#ความเสียหายทางกายภาพ 100% + การป้องกันทางกายภาพ 100% #C0x5B545B#+$(skillLevel*4*48)$ ของ #C0xF13B54#ความเสียหายทางกายภาพ #C0x5B545B# แก่เป้าหมายศัตรูทั้งหมด เพิ่มการลดความเสียหายจริงของตนเองอีก 50% เป็นเวลา 2 เทิร์น และมอบเอฟเฟกต์ [ร่วมกับศัตรู] ให้กับหน่วยพันธมิตรประเภท ซูเปอร์/ปีศาจ ในแถวเดียวกันเป็นเวลา 2 เทิร์น [ร่วมกับศัตรู]: เอฟเฟกต์บัฟพิเศษที่จะกระตุ้นเอฟเฟกต์การโจมตีกลับของซูเปอร์กิลกาเมช [อาณาจักร] เมื่อได้รับการโจมตีแบบแอคทีฟ ได้รับ [เกราะเปลวเพลิงแห่งดวงอาทิตย์] ในช่วงระยะเวลาเอฟเฟกต์ และถ้าคุณอยู่แถวหน้า จะได้รับการลดความเสียหายเพิ่มเติม 30% และถ้าอยู่แถวหลัง จะได้รับความเสียหายเสริม 30% เพิ่มเติม',
		describe_in = 'Super Gilgamesh melompat ke langit, mengubah ribuan harta menjadi guntur, menyebabkan #C0xE69900#100% Kerusakan Fisik + 100% pertahanan fisik #C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54# Kerusakan Fisik #C0x5B545B# ke semua target musuh, meningkatkan pengurangan kerusakan nyata sendiri sebesar 50% selama 2 giliran dan memberikan efek [Bersama musuh] kepada unit sekutu tipe Super/Iblis dalam baris yang sama selama 2 giliran. [Bersama musuh]: efek buff khusus yang mengaktifkan efek serangan balik dari Super Gilgamesh [Yang Mulia] saat menerima serangan aktif; mendapatkan [Baju Zirah Api Matahari] selama durasi efek dan jika kamu berada di baris depan, akan menerima pengurangan kerusakan tambahan 30%, dan jika di baris belakang, akan menerima tambahan 30% kerusakan bonus.',
		describe_ph = 'Tumalon si Super Gilgamesh sa langit, nagpapabago sa libu-libong mga kayamanan na maging kulog, nagdudulot ng #C0xE69900#100% Pisikal na Pinsala + 100% pisikal na depensa #C0x5B545B#+$(skillLevel*4*48)$ ng #C0xF13B54# Pisikal na Pinsala #C0x5B545B# sa lahat ng mga kalaban, nagpapataas ng sariling pagbawas ng tunay na pinsala ng 50% sa loob ng 2 turn at nagbibigay sa mga kaalyadong yunit ng uri ng Super/Demonyo sa parehong hanay ng epekto na [Kasama ang Kaaway] sa loob ng 2 turn. [Kasama ang Kaaway]: isang espesyal na epekto ng buff na nagpapagana ng epekto ng panlaban ni Super Gilgamesh [Haring Hari] kapag tumatanggap ng mga aktibong atake; nakakakuha ng [Baluti ng Apoy ng Araw] habang aktibo, at kung ikaw ay nasa unahang hanay, makakakuha ka ng karagdagang 30% bawas pinsala, at kung nasa likurang hanay, makakatanggap ka ng 30% dagdag pinsala.',
		describe_ma = 'Super Gilgamesh melompat ke langit, menjadikan ribuan harta karun sebagai petir, menyebabkan #C0xE69900#100% Kerosakan Fizikal + 100% pertahanan fizikal #C0x5B545B#+$(skillLevel*4*48)$ daripada #C0xF13B54# Kerosakan Fizikal #C0x5B545B# kepada semua sasaran musuh, meningkatkan pengurangan kerosakan sebenar diri sendiri sebanyak 50% selama 2 pusingan dan memberikan unit bersekutu jenis Super/Demon dalam barisan yang sama kesan [Bersama musuh] selama 2 pusingan. [Bersama musuh]: satu kesan buff khas yang akan mengaktifkan kesan balas serangan Super Gilgamesh [Yang Mulia] apabila menerima serangan aktif; memperoleh [Perisai Api Matahari] sepanjang tempoh kesan dan jika anda berada di barisan hadapan, anda akan menerima pengurangan kerosakan tambahan sebanyak 30%, dan jika di barisan belakang, anda akan menerima 30% kerosakan tambahan.',
		describe = 'Super Gilgamesh leaps into the sky, turning thousands of treasures into thunder, dealing #C0xE69900#100% Physical Damage + 100% physical defense #C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage #C0x5B545B# to all enemy targets, increasing self true damage reduction by 50% for 2 turns and granting allied units of type Super/Demon in the same row the effect [With the Enemy] for 2 turns. [With the Enemy]: a special buff effect that triggers Super Gilgamesh [Majesty]\'s counterattack effect when receiving active attack hits; gain [Solar Flame Armor] during the effect duration and if you are in the front row, receive an additional 30% damage reduction, and if in the back row, receive an additional 30% bonus damage.',
		zawakeEffect = __data_t__zawakeEffect[40232],
		-- {79002}
		zawakeEffectDesc = 'Super Gilgamesh leaps into the sky, turning thousands of treasures into thunder, causing #C0xE69900#100% Physical Damage + 100% physical defense to all enemy targets#C0x5B545B#+$(skillLevel* 4*48)$ of #C0xF13B54# Physical Damage #C0x5B545B#, increasing self\'s true damage reduction by 50% for 2 turns, while also adding the <With Enemy> effect to super friendly/steel units in the same row for 2 turns, <With Enemy> During Enemy\'s turn>, Super Gilgamesh receives <Sunfire Armor>\n#F10#\n#F40#<With Enemy>: a special buff effect that triggers the counterattack effect of Super Gilgamesh\'s <King\'s Majesty> when receiving active attacks and removes all non-dominant control effects on Super Gilgamesh; if the target is super or steel type, it receives <Sunfire Armor> during its effect duration. At the same time, if in the front row, damage is further reduced by 30%, and if in the back row, damage is also further reduced by 30%.',
		zawakeEffectDesc_en = 'Super Gilgamesh leaps into the sky, turning thousands of treasures into thunder, causing #C0xE69900#100% Physical Damage + 100% physical defense to all enemy targets#C0x5B545B#+$(skillLevel* 4*48)$ of #C0xF13B54# Physical Damage #C0x5B545B#, increasing self\'s true damage reduction by 50% for 2 turns, while also adding the <With Enemy> effect to super friendly/steel units in the same row for 2 turns, <With Enemy> During Enemy\'s turn>, Super Gilgamesh receives <Sunfire Armor>\n#F10#\n#F40#<With Enemy>: a special buff effect that triggers the counterattack effect of Super Gilgamesh\'s <King\'s Majesty> when receiving active attacks and removes all non-dominant control effects on Super Gilgamesh; if the target is super or steel type, it receives <Sunfire Armor> during its effect duration. At the same time, if in the front row, damage is further reduced by 30%, and if in the back row, damage is also further reduced by 30%.',
		zawakeEffectDesc_th = 'ซูเปอร์กิลกาเมชกระโดดขึ้นสู่ท้องฟ้า ทำให้สมบัติมากมายกลายเป็นเสียงฟ้าร้อง สร้าง #C0xE69900#100% ความเสียหายทางกายภาพ + 100% การป้องกันกายภาพแก่เป้าหมายศัตรูทั้งหมด#C0x5B545B#+$(skillLevel* 4*48)$ ของ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# ช่วยเพิ่มการลดความเสียหายจริงของตนเอง 50% เป็นเวลา 2 เทิร์น พร้อมทั้งเพิ่มเอฟเฟกต์ <กับศัตรู> ให้กับยูนิตมิตรภาพสูง/เหล็กในแถวเดียวกันเป็นเวลา 2 เทิร์น <กับศัตรู> ในช่วงเวลาของศัตรู ซูเปอร์กิลกาเมชจะได้รับ <ชุดเกราะไฟอาทิตย์>\n#F10#\n#F40#<กับศัตรู>: เอฟเฟกต์บัฟพิเศษที่เปิดใช้งานเอฟเฟกต์ตอบโต้ของ <ราชาความยิ่งใหญ่> ของซูเปอร์กิลกาเมชเมื่อได้รับการโจมตีแบบแอคทีฟ และลบเอฟเฟกต์ควบคุมที่ไม่เด่นชัดทั้งหมดบนซูเปอร์กิลกาเมช; หากเป้าหมายเป็นประเภทซูเปอร์หรือเหล็ก จะได้รับ <ชุดเกราะไฟอาทิตย์> ในระยะเวลาที่มีผล ในเวลาเดียวกัน หากอยู่แถวหน้า จะได้รับการลดความเสียหายเพิ่มอีก 30% และถ้าอยู่แถวหลัง จะได้รับการลดความเสียหายเพิ่มอีก 30%.',
		zawakeEffectDesc_in = 'Super Gilgamesh melompat ke langit, mengubah ribuan harta menjadi petir, menyebabkan #C0xE69900#100% Kerusakan Fisik + 100% pertahanan fisik ke semua target musuh#C0x5B545B#+$(skillLevel* 4*48)$ dari #C0xF13B54# Kerusakan Fisik #C0x5B545B#, membantu meningkatkan pengurangan kerusakan nyata diri sendiri sebesar 50% selama 2 giliran, sekaligus menambahkan efek <Bersama Musuh> pada unit super ramah/ baja di baris yang sama selama 2 giliran, <Bersama Musuh> Selama giliran Musuh>, Super Gilgamesh menerima <Zirah Api Matahari>\n#F10#\n#F40#<Bersama Musuh>: efek buff khusus yang mengaktifkan efek serangan balik <Keagungan Raja> Super Gilgamesh ketika menerima serangan aktif dan Menghapus semua efek kontrol non dominan pada Super Gilgamesh; jika target adalah tipe super atau baja, ia akan menerima <Zirah Api Matahari> selama durasi efek. Pada saat yang sama, jika berada di baris depan akan dikurangi 30% kerusakan tambahan, dan jika di baris belakang juga akan dikurangi 30% kerusakan tambahan.',
		zawakeEffectDesc_ph = 'Super Gilgamesh tumalon sa langit, na nagiging dahilan na ang libu-libong kayamanan ay naging kidlat, na nagdudulot ng #C0xE69900#100% Physical Damage + 100% physical defense sa lahat ng kalabang target#C0x5B545B#+$(skillLevel* 4*48)$ ng #C0xF13B54# Physical Damage #C0x5B545B#, tumutulong para madagdagan ang sariling kakayahan sa pag-reduce ng totoong pinsala ng 50% para sa 2 turns, kasabay nito ay nadadagdag ang effect na <Kasama ang Kaaway> sa mga super friendly/steel units sa parehong hanay para sa 2 turns, <Kasama ang Kaaway> Sa oras ng Kaaway>, natatanggap ni Super Gilgamesh ang <Sunfire Armor>\n#F10#\n#F40#<Kasama ang Kaaway>: isang espesyal na buff effect na nagti-trigger ng counterattack effect ng <King\'s Majesty> ni Super Gilgamesh kapag tumatanggap ng mga aktibong atake at tinatanggal lahat ng non-dominant control effects sa kay Super Gilgamesh; kung ang target ay super o steel type, matatanggap nito ang <Sunfire Armor> habang epektibo. Kasabay nito, kung nasa front row ay mababawasan ng dagdag na 30% ang pinsala, at kung nasa back row ay mababawasan din ng dagdag na 30% ang pinsala.',
		zawakeEffectDesc_ma = 'Super Gilgamesh melompat ke langit, menjadikan ribuan harta karun berubah menjadi guruh, menyebabkan #C0xE69900#100% Kerosakan Fizikal + 100% pertahanan fizikal kepada semua sasaran musuh#C0x5B545B#+$(skillLevel* 4*48)$ daripada #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, membantu meningkatkan keupayaan pengurangan kerosakan sebenar diri sendiri sebanyak 50% selama 2 giliran, serentak menambahkan kesan <Bersama Musuh> kepada unit super mesra/baja dalam baris yang sama selama 2 giliran, <Bersama Musuh> Dalam masa Giliran Musuh>, Super Gilgamesh menerima <Perisai Api Matahari>\n#F10#\n#F40#<Bersama Musuh>: kesan buff khas yang mengaktifkan kesan serangan balas <Keagungan Raja> Super Gilgamesh apabila menerima serangan aktif dan Menghapus semua kesan kawalan bukan dominan ke atas Super Gilgamesh; jika sasaran adalah jenis super atau baja, ia akan menerima <Perisai Api Matahari> dalam tempoh kesan. Pada masa yang sama, jika di barisan hadapan akan dikurangkan 30% kerosakan tambahan, dan jika di barisan belakang juga akan dikurangkan 30% kerosakan tambahan.',
		zawakeEffectDesc_vn = 'Super Gilgamesh nhảy lên trời, khiến hàng ngàn bảo vật biến thành sấm sét, gây #C0xE69900#100% Sát Thương Vật Lý + 100% phòng thủ vật lý cho tất cả mục tiêu địch#C0x5B545B#+$(skillLevel* 4*48)$ của #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, giúp tăng khả năng giảm 50% sát thương thực của bản thân cho 2 lượt, đồng thời thêm hiệu ứng <Cùng kẻ thù> cho các đơn vị siêu thân thiện/thép trong cùng một hàng trong 2 lượt, <Cùng kẻ thù> Trong thời gian của Kẻ thù>, bản thân Super Gilgamesh nhận được <Áo giáp lửa mặt trời>\n#F10#\n#F40#<Cùng kẻ thù>: một hiệu ứng buff đặc biệt kích hoạt hiệu ứng phản công của <King\'s Majesty> của Super Gilgamesh khi nhận các đòn tấn công chủ động và Loại bỏ tất cả hiệu ứng kiểm soát không chiếm ưu thế trên Super Gilgamesh; nếu mục tiêu là loại siêu hoặc loại thép, nó sẽ nhận được <Áo giáp lửa mặt trời> trong thời gian hiệu lực. Đồng thời, nếu ở hàng trước sẽ được giảm thêm 30% sát thương, còn nếu ở hàng sau sẽ được giảm thêm 30% sát thương.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'During <Shared Enemy>, Super Gilgamesh gains <Solar Flame Armor> and the attribute bonuses from <Shared Enemy> apply to both Super/Steel types simultaneously.  ',
		zawakeSimpleDesc_en = 'During <Shared Enemy>, Super Gilgamesh gains <Solar Flame Armor> and the attribute bonuses from <Shared Enemy> apply to both Super/Steel types simultaneously.  ',
		zawakeSimpleDesc_th = 'ในช่วงเวลา <ศัตรูร่วม>, Super Gilgamesh ได้รับ <เกราะเพลิงอาทิตย์> และเอฟเฟกต์เสริมค่าสถานะจาก <ศัตรูร่วม> มีผลกับทั้งประเภท ซุปเปอร์/เหล็ก พร้อมกัน  ',
		zawakeSimpleDesc_in = 'Selama <Musuh Bersama>, Super Gilgamesh memperoleh <Armor Api Surya> dan bonus atribut dari <Musuh Bersama> berlaku pada tipe Super/Baja secara bersamaan  ',
		zawakeSimpleDesc_ph = 'Sa panahon ng <Iisang Kaaway>, makakakuha si Super Gilgamesh ng <Solar Flame Armor> at ang bonus na epekto ng <Iisang Kaaway> ay magkakabisa sa parehong uri ng Super/Bakal  ',
		zawakeSimpleDesc_ma = 'Semasa <Musuh Bersama>, Super Gilgamesh memperoleh <Perisai Api Suria> dan bonus atribut dari <Musuh Bersama> turut berfungsi kepada jenis Super/Besi secara serentak  ',
		zawakeSimpleDesc_vn = 'Trong thời gian của <Cùng kẻ thù>, bản thân Super Gilgamesh nhận được <Áo giáp lửa mặt trời> và hiệu ứng thưởng thuộc tính của <Cùng kẻ thù> có hiệu lực trên các loại Siêu/Thép cùng một lúc.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
		upLvDesc_in = 'Kerusakan tetap +192',
		upLvDesc_ph = 'Fixed damage +192',
