	[40233] = {
		id = 40233,
		skillName_vn = 'Linh hồn - Kiếm phân ly - Ea',
		skillName_en = 'Soul - Parting Sword - Ea',
		skillName_th = 'วิญญาณ - ดาบแห่งการพรากจาก - Ea',
		skillName_in = 'Jiwa - Pedang Perpisahan - Ea',
		skillName_ph = 'Kaluluwa - Espadang Nagkakahiwalay - Ea',
		skillName_ma = 'Jiwa - Pedang Perpisahan - Ea',
		skillName = 'Soul - Parting Sword - Ea',
		describe_vn = 'Super Gilgamesh kích hoạt sức mạnh mặt trời để giải phóng thanh kiếm lệch lạc Ea, vừa chửi rủa vừa nhìn thẳng vào con trai tôi! Gây #C0xE69900#200% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# cho tất cả kẻ thù, sau đó thêm [Taunt] cho tất cả kẻ thù trong 1 hiệp, vào [Trạng thái Mặt trời mọc] trong 2 hiệp và thêm hiệu ứng [Hèn nhát] cho đơn vị kẻ địch có đòn tấn công cao nhất trong 2 vòng\n#F10#\n#F40#[ Trạng thái Mặt trời mọc]: Khi vào trạng thái này, nó ngay lập tức phá vỡ hiệu ứng tàng hình của tất cả kẻ thù và khả năng phòng thủ kép của bản thân tăng lên theo sức tấn công tương ứng. Nếu lượng máu của bản thân dưới 50%, khả năng hút máu tăng 30%\n[Hèn nhát]: Hiệu ứng tiêu cực đặc biệt, không thể xua tan, đơn vị này giảm 20% đòn tấn công kép và 50% tỷ lệ chí mạng trước khi tấn công Super Gilgamesh và không thể nhận được buff loại tấn công khi tấn công\n[Taunt]: Hiệu ứng kiểm soát, kẻ địch phải chọn đơn vị chế nhạo làm mục tiêu tấn công',
		describe_en = 'Super Gilgamesh activates the power of the sun to unleash the distorted sword Ea, cursing while staring straight at my son! Deals #C0xE69900#200% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B# to all enemies, then applies [Taunt] to all enemies for 1 turn, enters [Rising Sun State] for 2 turns, and applies [Cowardice] to the enemy unit with the highest attack for 2 rounds. \n#F10#\n#F40#[Rising Sun State]: Upon entering this state, it instantly breaks all enemies\' invisibility effects and increases own double defense based on attack power. If own HP is below 50%, life steal increases by 30%. \n[Cowardice]: A special negative effect that cannot be removed; the unit’s double attack is reduced by 20% and critical hit rate by 50% before attacking Super Gilgamesh, and it cannot receive attack-type buffs when attacking. \n[Taunt]: Control effect, enemies must choose the taunting unit as the attack target.',
		describe_th = 'ซูเปอร์กิลกาเมชเรียกพลังแห่งดวงอาทิตย์ ปล่อย [ดาบแหวกโลก · Ea] พร้อมตะโกน "กล้าจ้องหน้าข้ารึ เจ้าลูกสารเลว!" สร้างความเสียหายกายภาพแก่ศัตรูทุกตัว #C0xE69900#200% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# จากนั้นใส่สถานะ [ยั่วยุ] ให้ศัตรูทุกตัว 1 เทิร์น, ตนเองเข้าสู่สถานะ [แสงอรุณ] 2 เทิร์น และใส่สถานะ [หวาดกลัว] ให้กับศัตรูที่มีพลังโจมตีสูงสุดเป็นเวลา 2 เทิร์น [แสงอรุณ]: เมื่อตนเองเข้าสู่สถานะนี้ จะลบล้างเอฟเฟกต์ล่องหนของศัตรูทั้งหมดทันที, เพิ่มพลังป้องกันทั้งสองประเภทตามค่าพลังโจมตี, หากพลังชีวิตของตนต่ำกว่า 50% จะเพิ่มอัตราการดูดเลือดอีก 30% [หวาดกลัว]: เอฟเฟกต์ดีบัฟพิเศษ ไม่สามารถลบได้ หน่วยนี้เมื่อจะโจมตีซูเปอร์กิลกาเมชจะลดพลังโจมตีทั้งสองประเภทลง 20% และลดอัตราคริติคอลลง 50% พร้อมไม่สามารถรับบัฟประเภทเพิ่มพลังโจมตีใด ๆ ได้ขณะโจมตี [ยั่วยุ]: เอฟเฟกต์ควบคุม ศัตรูที่ติดสถานะนี้จะต้องเลือกหน่วยที่มี [ยั่วยุ] เป็นเป้าหมายโจมตี',
		describe_in = 'Super Gilgamesh mengaktifkan kekuatan matahari untuk melepaskan pedang Ea yang bengkok, sambil mengutuk dan menatap lurus ke anakku! Menyebabkan #C0xE69900#200% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B# ke semua musuh, kemudian menambahkan [Taunt] ke semua musuh selama 1 giliran, memasuki [Status Matahari Terbit] selama 2 giliran dan menambahkan efek [Ketamakan] ke unit musuh dengan serangan tertinggi selama 2 putaran \n#F10#\n#F40#[Status Matahari Terbit]: Saat memasuki status ini, secara langsung memecahkan efek sembunyi semua musuh dan pertahanan ganda diri sendiri meningkat berdasarkan kekuatan serangan. Jika HP sendiri kurang dari 50%, lifesteal meningkat 30% \n[Ketamakan]: Efek negatif khusus, tidak dapat dihapus, unit ini mengurangi serangan ganda 20% dan tingkat kritis 50% sebelum menyerang Super Gilgamesh dan tidak bisa mendapatkan buff jenis serangan saat menyerang \n[Taunt]: Efek kontrol, musuh harus memilih unit yang mengejek sebagai target serangan',
		describe_ph = 'Pinapagana ni Super Gilgamesh ang kapangyarihan ng araw upang palayain ang baluktot na espada na Ea, habang nanumpa at direktang tumitingin sa aking anak na lalaki! Nagdudulot ng #C0xE69900#200% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B# sa lahat ng kaaway, pagkatapos ay naglalagay ng [Taunt] sa lahat ng kaaway sa loob ng 1 round, pumapasok sa [Kalagayan ng Pagsikat ng Araw] sa loob ng 2 round, at naglalagay ng epekto ng [Duwag] sa kaaway na yunit na may pinakamataas na atake sa loob ng 2 round \n#F10#\n#F40#[Kalagayan ng Pagsikat ng Araw]: Sa pagpasok sa kalagayang ito, agad nitong winawasak ang mga epekto ng pagiging nakatago ng lahat ng kaaway at ang sariling dobleng depensa ay tumataas batay sa kapangyarihan ng atake. Kung ang sariling HP ay mababa sa 50%, tumataas ng 30% ang pag-siphon ng buhay \n[Duwag]: Isang espesyal na negatibong epekto, hindi maaaring alisin; ang yunit na ito ay nababawasan ang dobleng atake ng 20% at 50% kritikal na tsansa bago umatake kay Super Gilgamesh, at hindi maaaring makatanggap ng mga attack-type na buff kapag umaatake \n[Taunt]: Effect ng kontrol, kailangang piliin ng mga kaaway ang yunit na nag-taunt bilang target ng atake',
		describe_ma = 'Super Gilgamesh mengaktifkan kuasa matahari untuk melepaskan pedang Ea yang bengkok, sambil mengutuk dan menatap lurus ke anakku! Menyebabkan #C0xE69900#200% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B# kepada semua musuh, kemudian menambah [Taunt] kepada semua musuh selama 1 pusingan, memasuki [Keadaan Matahari Terbit] selama 2 pusingan dan menambah kesan [Pengecut] kepada unit musuh dengan serangan tertinggi selama 2 pusingan \n#F10#\n#F40#[Keadaan Matahari Terbit]: Apabila memasuki keadaan ini, ia segera memecahkan kesan penyamaran semua musuh dan pertahanan berganda sendiri meningkat mengikut kekuatan serangan. Jika darah sendiri di bawah 50%, pencuri nyawa meningkat 30% \n[Pengecut]: Kesan negatif khas, tidak boleh dibuang, unit ini mengurangkan serangan berganda sebanyak 20% dan kadar kritikal sebanyak 50% sebelum menyerang Super Gilgamesh dan tidak boleh menerima buff jenis serangan ketika menyerang \n[Taunt]: Kesan kawalan, musuh mesti memilih unit yang mengejek sebagai sasaran serangan',
		describe = 'Super Gilgamesh activates the power of the sun to unleash the distorted sword Ea, cursing while staring straight at my son! Deals #C0xE69900#200% Physical Damage#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B# to all enemies, then applies [Taunt] to all enemies for 1 turn, enters [Rising Sun State] for 2 turns, and applies [Cowardice] to the enemy unit with the highest attack for 2 rounds. \n#F10#\n#F40#[Rising Sun State]: Upon entering this state, it instantly breaks all enemies\' invisibility effects and increases own double defense based on attack power. If own HP is below 50%, life steal increases by 30%. \n[Cowardice]: A special negative effect that cannot be removed; the unit’s double attack is reduced by 20% and critical hit rate by 50% before attacking Super Gilgamesh, and it cannot receive attack-type buffs when attacking. \n[Taunt]: Control effect, enemies must choose the taunting unit as the attack target.',
		starEffect = __data_t__starEffect[40233],
		-- {11}
		starEffectDesc_vn = 'Nâng cao hiệu ứng: Chiêu thức đặc biệt được nâng cấp lên <Tác động Corona>, sẽ gây thêm sát thương thực tế bằng với phần thưởng phòng thủ gấp đôi 100% hiện tại của Solgaleo cho tất cả kẻ địch và thêm <Chế nhạo mạnh mẽ> cho kẻ địch trong 1 hiệp và đòn tấn công này sẽ không kích hoạt hiệu ứng trúng đòn của mục tiêu; tiến vào <Trạng thái Mặt trời mọc> , nó sẽ loại bỏ tất cả các hiệu ứng tiêu cực sinh học gắn liền với chính nó (xem các mục tương ứng trong hướng dẫn chiến đấu để biết chi tiết) và sẽ miễn nhiễm với các hiệu ứng đó trong suốt thời gian của <Trạng thái Mặt trời mọc>\n#F10#\n#F40#<Powerful Taunt>: Hiệu ứng kiểm soát đặc biệt, kẻ địch phải sử dụng các đòn tấn công bình thường để chế nhạo đơn vị',
		starEffectDesc = 'Enhance Effect: The special move is upgraded to <Corona Impact>, which will deal additional true damage equal to twice 100% of Solgaleo\'s current defense bonus to all enemies and add <Powerful Taunt> to enemies for 1 turn. This attack will not trigger the target’s hit effects; entering <Sunrise State>, it will remove all attached negative biological effects on itself (see corresponding items in the battle guide for details) and will be immune to those effects throughout the duration of <Sunrise State>\n#F10#\n#F40#<Powerful Taunt>: A special control effect, enemies must use normal attacks to taunt the unit',
		starEffectDesc_en = 'Enhance Effect: The special move is upgraded to <Corona Impact>, which will deal additional true damage equal to twice 100% of Solgaleo\'s current defense bonus to all enemies and add <Powerful Taunt> to enemies for 1 turn. This attack will not trigger the target’s hit effects; entering <Sunrise State>, it will remove all attached negative biological effects on itself (see corresponding items in the battle guide for details) and will be immune to those effects throughout the duration of <Sunrise State>\n#F10#\n#F40#<Powerful Taunt>: A special control effect, enemies must use normal attacks to taunt the unit',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: ท่าไม้ตายอัปเกรด จะสร้างความเสียหายจริงเพิ่มเติมแก่ศัตรูทุกตัว เท่ากับ 20% ของค่าพลังป้องกันทั้งสองประเภทที่ซูเปอร์กิลกาเมชมีในปัจจุบัน และใส่สถานะ [ยั่วยุขั้นสูง] 1 เทิร์นให้ศัตรู โดยการโจมตีครั้งนี้จะไม่กระตุ้นเอฟเฟกต์เมื่อถูกโจมตีของเป้าหมาย; เมื่อเข้าสู่สถานะ [แสงอรุณ] จะลบล้างดีบัฟประเภทชีวภาพทั้งหมดที่ติดอยู่กับตนเอง (ดูรายละเอียดในคู่มือการต่อสู้) และในช่วงที่อยู่ในสถานะ [แสงอรุณ] จะได้รับภูมิคุ้มกันต่อดีบัฟประเภทดังกล่าว [ยั่วยุขั้นสูง]: เอฟเฟกต์ควบคุมพิเศษ ศัตรูจะต้องใช้การโจมตีปกติโจมตีเป้าหมายที่มีสถานะยั่วยุ',
		starEffectDesc_in = 'Enhance Effect: Teknik khusus diupgrade menjadi <Tác động Corona>, yang akan memberikan kerusakan nyata tambahan sebesar dua kali lipat 100% dari bonus pertahanan Solgaleo saat ini ke semua musuh dan menambahkan <Chế nhạo mạnh mẽ> ke musuh selama 1 giliran. Serangan ini tidak akan memicu efek terkena sasaran; memasuki <Trạng thái Mặt trời mọc>, akan menghilangkan semua efek biologis negatif yang melekat pada dirinya sendiri (lihat item terkait dalam panduan pertarungan untuk detail) dan akan kebal terhadap efek tersebut selama durasi <Trạng thái Mặt trời mọc>\n#F10#\n#F40#<Powerful Taunt>: Efek kontrol khusus, musuh harus menggunakan serangan normal untuk mengejek unit',
		starEffectDesc_ph = 'Enhance Effect: Ang espesyal na kakayahan ay in-upgrade sa <Tác động Corona>, na magdudulot ng karagdagang tunay na pinsala na katumbas ng doble ng 100% ng kasalukuyang bonus sa depensa ni Solgaleo sa lahat ng kalaban at magdadagdag ng <Chế nhạo mạnh mẽ> sa mga kalaban sa loob ng 1 turn. Ang pag-atakeng ito ay hindi magti-trigger ng mga epekto ng tama sa target; pumapasok sa <Trạng thái Mặt trời mọc>, aalisin nito ang lahat ng mga negatibong biyolohikal na epekto na nakakabit sa sarili nito (tingnan ang mga kaugnay na item sa gabay sa laban para sa detalye) at magiging immune sa mga epektong iyon sa buong panahon ng <Trạng thái Mặt trời mọc>\n#F10#\n#F40#<Powerful Taunt>: Isang espesyal na effect ng kontrol, kailangan ng mga kalaban na gumamit ng mga normal na pag-atake para mang-insulto sa yunit',
		starEffectDesc_ma = 'Enhance Effect: Serangan khas dinaik taraf menjadi <Tác động Corona>, yang akan menyebabkan kerosakan sebenar tambahan bersamaan dengan ganjaran pertahanan Solgaleo semasa didarab dua 100% kepada semua musuh dan menambah <Chế nhạo mạnh mẽ> pada musuh selama 1 giliran. Serangan ini tidak akan mengaktifkan kesan terkena sasaran musuh; memasuki <Trạng thái Mặt trời mọc>, ia akan menghilangkan semua kesan negatif biologi yang melekat pada dirinya sendiri (rujuk item berkaitan dalam panduan pertempuran untuk butiran) dan akan kebal kepada kesan tersebut sepanjang tempoh <Trạng thái Mặt trời mọc>\n#F10#\n#F40#<Powerful Taunt>: Kesan kawalan khas, musuh mesti menggunakan serangan biasa untuk mengejek unit',
		zawakeEffect = __data_t__zawakeEffect[40233],
		-- {79003, 1}
		zawakeEffectDesc = 'Enhanced Effect: The special skill is upgraded to <Corona Impact>, which deals additional true damage equal to 100% of Super Gilgamesh\'s current double defense bonus to all enemies and applies <Powerful Taunt> to enemies for 1 turn. This attack will not trigger the target\'s hit effect; during <Sunrise State>, 30% of the damage that your super/steel heroes suffer will be taken by Super Gilgamesh, and all attacks will deal an additional 100 of Super Gilgamesh\'s current bonus to enemies. % true damage with double defense bonus; upon entering <Sunrise State>, all biological negative effects attached to itself will be removed (see corresponding entries in the battle guide for details) and it will be immune to those effects during the <Sunrise State>; units affected by <Timid> will activate the <Timid> effect when attacking super/steel heroes#F10#\n#F40#<Powerful Taunt>: Control effect, cannot be dispelled, the enemy must use normal attacks to taunt the unit',
		zawakeEffectDesc_en = 'Enhanced Effect: The special skill is upgraded to <Corona Impact>, which deals additional true damage equal to 100% of Super Gilgamesh\'s current double defense bonus to all enemies and applies <Powerful Taunt> to enemies for 1 turn. This attack will not trigger the target\'s hit effect; during <Sunrise State>, 30% of the damage that your super/steel heroes suffer will be taken by Super Gilgamesh, and all attacks will deal an additional 100 of Super Gilgamesh\'s current bonus to enemies. % true damage with double defense bonus; upon entering <Sunrise State>, all biological negative effects attached to itself will be removed (see corresponding entries in the battle guide for details) and it will be immune to those effects during the <Sunrise State>; units affected by <Timid> will activate the <Timid> effect when attacking super/steel heroes#F10#\n#F40#<Powerful Taunt>: Control effect, cannot be dispelled, the enemy must use normal attacks to taunt the unit',
		zawakeEffectDesc_th = 'เอฟเฟกต์ที่เพิ่มขึ้น: ทักษะพิเศษได้รับการอัปเกรดเป็น <ผลกระทบโคโรนา> ซึ่งสร้างความเสียหายจริงเพิ่มเติมเท่ากับ 100% ของโบนัสป้องกันคู่ปัจจุบันของซูเปอร์กิลกาเมชต่อศัตรูทั้งหมดและเพิ่ม <การเยาะเย้ยอย่างรุนแรง> ให้กับศัตรูเป็นเวลา 1 เทิร์น การโจมตีนี้จะไม่ทำให้เกิดเอฟเฟกต์โดนโจมตีของเป้าหมาย; ในระหว่าง <สถานะพระอาทิตย์ขึ้น> 30% ของความเสียหายที่ฮีโร่ซูเปอร์/เหล็กของคุณได้รับจะถูกซูเปอร์กิลกาเมชรับไว้ และการโจมตีทั้งหมดจะสร้างโบนัสปัจจุบันของซูเปอร์กิลกาเมชเพิ่มอีก 100 คะแนนแก่ศัตรู % ความเสียหายจริงพร้อมโบนัสป้องกันคู่; เมื่อเข้าสู่ <สถานะพระอาทิตย์ขึ้น> ผลกระทบเชิงลบทางชีวภาพทั้งหมดที่ติดอยู่กับตัวเองจะถูกลบออก (ดูรายการที่เกี่ยวข้องในคู่มือการต่อสู้เพื่อดูรายละเอียด) และจะได้รับภูมิคุ้มกันต่อเอฟเฟกต์เหล่านั้นตลอด <สถานะพระอาทิตย์ขึ้น>; หน่วยที่ได้รับผลกระทบจาก <ขี้ขลาด> จะเปิดใช้งานเอฟเฟกต์ <ขี้ขลาด> เมื่อโจมตีฮีโร่ซูเปอร์/เหล็ก#F10#\n#F40#<การเยาะเย้ยอย่างรุนแรง>: เอฟเฟกต์ควบคุม ไม่สามารถลบออกได้ ศัตรูต้องใช้การโจมตีปกติเพื่อเยาะเย้ยหน่วย',
		zawakeEffectDesc_in = 'Efek Tingkat Lanjut: Skill khusus ditingkatkan menjadi <Dampak Corona>, yang memberikan kerusakan nyata tambahan sebesar 100% dari bonus pertahanan ganda Super Gilgamesh saat ini kepada semua musuh dan menambahkan <Sindiran Kuat> kepada musuh selama 1 giliran. Serangan ini tidak akan memicu efek terkena serangan dari target; selama <Status Matahari Terbit>, 30% dari kerusakan yang diderita pahlawan super/baja Anda akan ditanggung oleh Super Gilgamesh, dan semua serangan akan memberikan tambahan 100 poin bonus saat ini dari Super Gilgamesh ke musuh. % kerusakan nyata dengan bonus pertahanan ganda; saat memasuki <Status Matahari Terbit>, semua efek negatif biologis yang melekat pada dirinya akan dihilangkan (lihat entri terkait di panduan pertempuran untuk detail) dan akan kebal terhadap efek tersebut selama <Status Matahari Terbit>; unit yang terkena dampak <Pengecut> akan mengaktifkan efek <Pengecut> saat menyerang pahlawan super/baja#F10#\n#F40#<Sindiran Kuat>: Efek kontrol, tidak bisa dibersihkan, musuh harus menggunakan serangan normal untuk mengejek unit',
		zawakeEffectDesc_ph = 'Pinahusay na Epekto: In-upgrade ang espesyal na kakayahan sa <Corona Impact>, na magbibigay ng karagdagang tunay na pinsala na katumbas ng 100% ng kasalukuyang doble na depensa ng gantimpala ng Super Gilgamesh sa lahat ng mga kalaban at magdaragdag ng <Matinding Panunukso> sa mga kalaban sa loob ng 1 turn. Ang pag-atakeng ito ay hindi magpapagana ng epekto ng pagkakabugbog sa target; sa panahon ng <Sunrise State>, 30% ng pinsalang tinatanggap ng iyong super/steel na mga bayani ay sasapitin ng Super Gilgamesh, at lahat ng mga atake ay magbibigay ng karagdagang 100 puntong gantimpala ng Super Gilgamesh sa mga kalaban. % tunay na pinsala gamit ang doble na gantimpala sa depensa; kapag pumapasok sa <Sunrise State>, lahat ng mga negatibong biyolohikal na epekto na nakakabit sa sarili ay aalisin (tingnan ang mga kaukulang tala sa gabay sa laban para sa detalye) at magiging immune sa mga epektong iyon sa panahon ng <Sunrise State>; ang mga unit na apektado ng <Timid> ay magpapagana ng epektong <Timid> kapag umaatake sa mga super/steel na bayani#F10#\n#F40#<Matinding Panunukso>: Control effect, hindi mapapawi, kailangang gumamit ang kalaban ng normal na atake upang manukso ng unit',
		zawakeEffectDesc_ma = 'Kesan Dipertingkatkan: Kemahiran khas dinaik taraf ke <Kesan Corona>, yang menyebabkan kerosakan sebenar tambahan sebanyak 100% ganjaran pertahanan berganda semasa Super Gilgamesh kepada semua musuh dan menambah <Sindiran Berkuasa> kepada musuh selama 1 pusingan. Serangan ini tidak akan mencetuskan kesan terkena serangan pada sasaran; semasa <Keadaan Matahari Terbit>, 30% kerosakan yang ditanggung wira super/keluli anda akan ditanggung oleh Super Gilgamesh, dan semua serangan akan memberikan tambahan 100 mata ganjaran semasa Super Gilgamesh kepada musuh. % kerosakan sebenar dengan ganjaran pertahanan berganda; apabila memasuki <Keadaan Matahari Terbit>, semua kesan negatif biologi yang melekat pada diri sendiri akan dihapuskan (rujuk entri berkaitan dalam panduan pertempuran untuk maklumat lanjut) dan akan kebal terhadap kesan tersebut sepanjang <Keadaan Matahari Terbit>; unit yang terkesan oleh <Penakut> akan mengaktifkan kesan <Penakut> apabila menyerang wira super/keluli anda#F10#\n#F40#<Sindiran Berkuasa>: Kesan kawalan, tidak dapat disingkirkan, musuh mesti menggunakan serangan biasa untuk mengejek unit',
		zawakeEffectDesc_vn = 'Hiệu ứng nâng cao: Chiêu thức đặc biệt được nâng cấp lên <Tác động Corona>, sẽ gây thêm sát thương thực tế bằng 100% phần thưởng phòng thủ kép hiện tại của Super Gilgamesh cho tất cả kẻ thù và thêm <Chế nhạo mạnh mẽ> cho kẻ thù trong 1 hiệp và đòn tấn công này sẽ không kích hoạt hiệu ứng trúng đòn của mục tiêu; trong suốt thời gian của <Trạng thái Mặt trời mọc>, 30% sát thương mà các anh hùng siêu cấp/thép của bạn phải gánh chịu sẽ do Super Gilgamesh gánh chịu và tất cả các đòn tấn công sẽ gây thêm 100 điểm thưởng hiện tại của Super Gilgamesh cho kẻ thù. % sát thương thực tế với phần thưởng phòng thủ gấp đôi; khi vào <Trạng thái Mặt trời mọc>, tất cả các hiệu ứng tiêu cực sinh học gắn liền với chính nó sẽ bị loại bỏ (xem các mục tương ứng trong hướng dẫn chiến đấu để biết chi tiết) và sẽ miễn nhiễm với các hiệu ứng đó trong suốt thời gian của <Trạng thái Mặt trời mọc>; các đơn vị bị ảnh hưởng bởi <Timid> sẽ kích hoạt hiệu ứng <Timid> khi tấn công các anh hùng siêu cấp/thép\n#F10#\n#F40#<Powerful Taunt>: Hiệu ứng khống chế, không thể xua tan, kẻ địch phải dùng đòn đánh thường để chế nhạo đơn vị',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Throughout <Rising Sun State>, 30% of the damage taken by your Super/Steel heroes is absorbed by Super Gilgamesh. All attacks will deal additional true damage to enemies equal to 100% of Super Gilgamesh’s current Double Defense bonus; <Strong Taunt> cannot be removed.  ',
		zawakeSimpleDesc_en = 'Throughout <Rising Sun State>, 30% of the damage taken by your Super/Steel heroes is absorbed by Super Gilgamesh. All attacks will deal additional true damage to enemies equal to 100% of Super Gilgamesh’s current Double Defense bonus; <Strong Taunt> cannot be removed.  ',
		zawakeSimpleDesc_th = 'ตลอดช่วงเวลา <สถานะพระอาทิตย์ขึ้น>, 30% ของความเสียหายที่ฮีโร่สายซุปเปอร์/เหล็กได้รับจะถูก Super Gilgamesh แบกรับไว้ การโจมตีทั้งหมดจะสร้างความเสียหายจริงเพิ่มเติมต่อศัตรู เท่ากับโบนัสป้องกันคู่ 100% ปัจจุบันของ Super Gilgamesh; <เยาะเย้ยอย่างแรง> ไม่สามารถลบได้  ',
		zawakeSimpleDesc_in = 'Selama <Keadaan Matahari Terbit>, 30% dari damage yang diterima oleh hero bertipe Super/Baja akan diserap oleh Super Gilgamesh. Semua serangan memberikan damage sejati tambahan sebesar 100% dari bonus Pertahanan Ganda saat ini milik Super Gilgamesh; <Provokasi Kuat> tidak dapat dihapus  ',
		zawakeSimpleDesc_ph = 'Habang nasa <Estado ng Pagsikat ng Araw>, 30% ng pinsalang dapat matanggap ng iyong Super/Bakal na bayani ay aakuin ni Super Gilgamesh. Lahat ng atake ay magdudulot ng karagdagang tunay na pinsala sa kalaban batay sa 100% ng kasalukuyang bonus sa Double Defense ni Super Gilgamesh; hindi maaalis ang <Matinding Pang-aasar>  ',
		zawakeSimpleDesc_ma = 'Sepanjang <Keadaan Matahari Terbit>, 30% kerosakan yang diterima oleh wira jenis Super/Besi anda akan ditanggung oleh Super Gilgamesh. Semua serangan akan memberikan kerosakan sebenar tambahan kepada musuh bersamaan dengan 100% bonus Pertahanan Ganda semasa Super Gilgamesh; <Ejekan Kuat> tidak boleh disingkirkan  ',
		zawakeSimpleDesc_vn = 'Trong suốt thời gian của <Trạng thái Mặt trời mọc>, 30% thiệt hại mà các siêu anh hùng/thép của bạn phải gánh chịu sẽ do Super Gilgamesh gánh chịu. Tất cả các đòn tấn công sẽ gây thêm sát thương thực sự cho kẻ địch bằng với phần thưởng phòng thủ gấp đôi 100% hiện tại của Super Gilgamesh; <Chế nhạo mạnh mẽ> không thể bị loại bỏ.',
		upLvDesc = 'Fix damage +360',
		upLvDesc_en = 'Fix damage +360',
		upLvDesc_th = 'แก้ไขความเสียหาย +360',
		upLvDesc_in = 'Perbaiki kerusakan +360',
		upLvDesc_ph = 'Ayusin ang pinsala +360',
		upLvDesc_ma = 'Betulkan kerosakan +360',
		upLvDesc_vn = 'Sửa lỗi sát thương +360',
		iconRes = 'battle/skill_icon/skill_40233.png',
		changeUnitTrigger = true,
		isCombat = true,
		passivePriority = 100,
		skillType2 = 2,
		skillNatureType = 15,
		hintChoose = 11,
		targetTypeDesc = 'All enemies',
		targetTypeDesc_vn = 'Tất cả kẻ thù',
		targetTypeDesc_en = 'All enemies',
		targetTypeDesc_th = 'ศัตรูทั้งหมด',
		targetTypeDesc_in = 'Semua musuh',
		targetTypeDesc_ph = 'Lahat ng kalaban',
		targetTypeDesc_ma = 'Semua musuh',
		targetChooseType = 'all',
		damageFormula = 'self:damage()*2+(self:flag(99) and skillLevel or skillLevel*4)*90+(moreE(self:star(),11) and self:defence() or 0)',
		skillProcess = {402331, 402332, 402333, 402334, 402335, 402336},
