	[40237] = {
		id = 40237,
		skillName_vn = 'Hồn - Cơn Thịnh Nộ của Vua',
		skillName_en = 'Soul - The King\'s Wrath',
		skillName_th = 'วิญญาณ - ความแค้นของกษัตริย์',
		skillName_in = 'Jiwa - Amarah Raja',
		skillName_ph = 'Kaluluwa - Galit ng Hari',
		skillName_ma = 'Roh - Kemarahan Raja',
		skillName = 'Soul - The King\'s Wrath',
		describe_vn = 'Super Gilgamesh sử dụng Bảo Khí của mình để tấn công một mục tiêu kẻ thù, gây ra #C0xE69900#180% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4 *24)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, giúp tăng khả năng phòng thủ kép của bản thân lên 40% và 10% giới hạn sinh mệnh trên (không vượt quá 300% đòn Sát Thương Vật Lý của bản thân) trong 2 lượt. Nó không thể được chồng lên nhau.',
		describe_en = 'Super Gilgamesh uses his Treasure Weapon to attack an enemy target, dealing #C0xE69900#180% Physical Damage#C0x5B545B# + $(skillLevel*4 *24)$\'s #C0xF13B54# Physical Damage #C0x5B545B#. This also increases his Double Defense by 40% and his maximum HP limit by 10% (not exceeding 300% of his own Physical Damage) for 2 turns. This effect cannot be stacked.',
		describe_th = 'Super Gilgamesh ใช้อาวุธวิเศษโจมตีเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#180%#C0x5B545B# + $(skillLevel*4 *24)$\'s ความเสียหายทางกายภาพ #C0xF13B54# #C0x5B545B# ช่วยเพิ่มความสามารถในการป้องกันคู่ของตนขึ้น 40% และเพิ่มขีดจำกัดพลังชีวิตสูงสุดขึ้น 10% (ไม่เกิน 300% ของความเสียหายทางกายภาพของตนเอง) เป็นเวลา 2 ตา ผลนี้ไม่สามารถซ้อนทับได้',
		describe_in = 'Super Gilgamesh menggunakan Senjata Khazanahnya untuk menyerang target musuh, menyebabkan #C0xE69900#180% Kerusakan Fisik#C0x5B545B# + $(skillLevel*4 *24)$\'s #C0xF13B54# Kerusakan Fisik #C0x5B545B#. Ini juga meningkatkan Pertahanan Ganda dirinya sebesar 40% dan batas maksimum HP sebesar 10% (tidak melebihi 300% dari Kerusakan Fisik dirinya sendiri) selama 2 giliran. Efek ini tidak dapat ditumpuk.',
		describe_ph = 'Ginagamit ni Super Gilgamesh ang Kanyang Barang na Pambihira upang atakihin ang isang target na kaaway, na nagdudulot ng #C0xE69900#180% Pisyikal na Pinsala#C0x5B545B# + $(skillLevel*4 *24)$\'s #C0xF13B54# Pisyikal na Pinsala #C0x5B545B#. Nakakatulong ito upang madagdagan ang kanyang Double Defense ng 40% at ang limitasyon ng maximum na HP ng 10% (hindi lalampas sa 300% ng sariling Pisyikal na Pinsala) sa loob ng 2 na turn. Hindi ito maaaring pagsamahin.',
		describe_ma = 'Super Gilgamesh menggunakan Senjata Khazannya untuk menyerang sasaran musuh, menyebabkan #C0xE69900#180% Kerosakan Fizikal#C0x5B545B# + $(skillLevel*4 *24)$\'s #C0xF13B54# Kerosakan Fizikal #C0x5B545B#. Ini juga meningkatkan Pertahanan Berganda dirinya sebanyak 40% dan had maksimum HP sebanyak 10% (tidak melebihi 300% daripada Kerosakan Fizikal dirinya sendiri) selama 2 pusingan. Kesan ini tidak boleh bertindih.',
		describe = 'Super Gilgamesh uses his Treasure Weapon to attack an enemy target, dealing #C0xE69900#180% Physical Damage#C0x5B545B# + $(skillLevel*4 *24)$\'s #C0xF13B54# Physical Damage #C0x5B545B#. This also increases his Double Defense by 40% and his maximum HP limit by 10% (not exceeding 300% of his own Physical Damage) for 2 turns. This effect cannot be stacked.',
		upLvDesc = 'Fix damage +96',
		upLvDesc_en = 'Fix damage +96',
		upLvDesc_th = 'แก้ไขความเสียหาย +96',
