	[40242] = {
		id = 40242,
		skillName_vn = 'Nguyệt Ẩn',
		skillName_en = 'Hidden Moon',
		skillName_th = 'จันทราที่ซ่อนอยู่',
		skillName_in = 'Bulan Tersembunyi',
		skillName_ph = 'Nakatagong Buwan',
		skillName_ma = 'Bulan Tersembunyi',
		skillName = 'Hidden Moon',
		describe_vn = 'Aizen tấn công một mục tiêu kẻ địch, gây #C0xF13B54# sát thương đặc biệt #C0x3D8A99#160% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*36)$#C0x5B545B#Sát thương đặc biệt#C0x5B545B#, sau đó đưa bản thân và đồng đội bóng tối có đòn tấn công cao nhất vào trạng thái [Moon Hidden] 1 hiệp và gây 15% sát thương bonus\n#F10#\n#F40#[Tsukiyaku]: Hiệu ứng đặc biệt, không thể chọn làm mục tiêu kỹ năng. Khi nhận sát thương không chia sẻ, 15% sát thương sẽ bị giảm và 10% máu tối đa của Aizen sẽ được phục hồi (không quá 500% Sát Thương Phép Thuật). Sau khi hiệu ứng [Tsukiyaku] kết thúc, anh ta sẽ chuyển sang trạng thái [Tàng hình] trong 1 hiệp.',
		describe_en = 'Aizen attacks an enemy target, dealing #C0xF13B54# special damage #C0x3D8A99#160% Magic Damage#C0x5B545B#+$(skillLevel*4*36)$#C0x5B545B# special damage#C0x5B545B#, then puts himself and the dark team member with the highest attack into [Moon Hidden] state for 1 turn and deals 15% bonus damage. [Tsukiyaku]: Special effect, cannot be selected as a skill target. When receiving damage, damage is not shared, 15% damage is reduced, and 10% of Aizen\'s max HP is restored (not exceeding 500% Magic Damage). After the [Tsukiyaku] effect ends, he switches to [Invisible] state for 1 turn.',
		describe_th = 'ไอเซ็นโจมตีศัตรูเป้าหมายเดี่ยว สร้างความเสียหายเวท #C0x3D8A99#280% พลังโจมตีเวท#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#ความเสียหายเวท#C0x5B545B# จากนั้นทำให้ตนเองและฮีโร่สายความมืดที่มีพลังโจมตีสูงสุด 1 ตัวเข้าสู่สถานะ [หลบซ่อนวิญญาณ] เป็นเวลา 1 เทิร์น และได้รับโบนัสความเสียหายเพิ่ม 15% [หลบซ่อนวิญญาณ]: เอฟเฟกต์พิเศษ ไม่สามารถถูกเลือกเป็นเป้าหมายของสกิลได้ เมื่อได้รับความเสียหายที่ไม่ใช่แบบแบ่งรับ จะลดความเสียหายครั้งนั้นลง 15% และฟื้นฟูพลังชีวิตเท่ากับ 10% ของพลังชีวิตสูงสุดของไอเซ็น (ไม่เกิน 500% ของพลังโจมตีเวท); เมื่อเอฟเฟกต์ [หลบซ่อนวิญญาณ] สิ้นสุด ตนเองจะเข้าสู่สถานะ [ล่องหน] เป็นเวลา 1 เทิร์น',
		describe_in = 'Aizen menyerang satu target musuh, memberikan #C0xF13B54# damage khusus #C0x3D8A99#160% Magic Damage#C0x5B545B#+$(skillLevel*4*36)$#C0x5B545B# damage khusus#C0x5B545B#, lalu menempatkan dirinya sendiri dan anggota tim gelap dengan serangan tertinggi ke dalam status [Moon Hidden] selama 1 giliran dan memberikan 15% damage bonus. [Tsukiyaku]: Efek khusus, tidak dapat dipilih sebagai target skill. Saat menerima damage, damage tidak dibagi, damage dikurangi 15%, dan 10% HP maksimum Aizen dipulihkan (tidak melebihi 500% Magic Damage). Setelah efek [Tsukiyaku] berakhir, dia berubah ke status [Invisible] selama 1 giliran.',
		describe_ph = 'Inaatake ni Aizen ang isang target na kaaway, na nagdudulot ng #C0xF13B54# espesyal na pinsala #C0x3D8A99#160% Magic Damage#C0x5B545B#+$(skillLevel*4*36)$#C0x5B545B# espesyal na pinsala#C0x5B545B#, pagkatapos ay inilalagay ang kanyang sarili at ang kasapi ng madilim na koponan na may pinakamataas na atake sa estado na [Moon Hidden] sa loob ng 1 turn at nagdudulot ng 15% bonus na pinsala. [Tsukiyaku]: Espesyal na epekto, hindi maaaring maging target ng kasanayan. Kapag nakakatanggap ng pinsala, hindi hinahati ang pinsala, nababawasan ang pinsala ng 15%, at naibabalik ang 10% ng maximum na HP ni Aizen (hindi lalampas sa 500% Magic Damage). Pagkatapos matapos ang epekto ng [Tsukiyaku], siya ay lilipat sa estado na [Invisible] sa loob ng 1 turn.',
		describe_ma = 'Aizen menyerang satu sasaran musuh, memberi #C0xF13B54# kerosakan khas #C0x3D8A99#160% Kerosakan Sihir#C0x5B545B#+$(skillLevel*4*36)$#C0x5B545B# kerosakan khas#C0x5B545B#, kemudian menempatkan dirinya dan anggota pasukan gelap dengan serangan tertinggi ke dalam keadaan [Moon Hidden] selama 1 giliran dan menyebabkan 15% kerosakan bonus. [Tsukiyaku]: Kesan khas, tidak boleh dipilih sebagai sasaran kemahiran. Apabila menerima kerosakan, kerosakan tidak dikongsi, kerosakan dikurangkan sebanyak 15%, dan 10% jumlah HP maksimum Aizen akan dipulihkan (tidak melebihi 500% Kerosakan Sihir). Selepas kesan [Tsukiyaku] berakhir, dia akan beralih ke keadaan [Invisible] selama 1 giliran.',
		describe = 'Aizen attacks an enemy target, dealing #C0xF13B54# special damage #C0x3D8A99#160% Magic Damage#C0x5B545B#+$(skillLevel*4*36)$#C0x5B545B# special damage#C0x5B545B#, then puts himself and the dark team member with the highest attack into [Moon Hidden] state for 1 turn and deals 15% bonus damage. [Tsukiyaku]: Special effect, cannot be selected as a skill target. When receiving damage, damage is not shared, 15% damage is reduced, and 10% of Aizen\'s max HP is restored (not exceeding 500% Magic Damage). After the [Tsukiyaku] effect ends, he switches to [Invisible] state for 1 turn.',
		zawakeEffect = __data_t__zawakeEffect[40242],
		-- {79002}
		zawakeEffectDesc = 'Aizen attacks a single enemy target, dealing #C0x3D8A99#160% Magical Damage#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#special damage#C0x5B545B#, then causes himself and the darkest ally with the highest attack to immediately recover 10% of Aizen\'s max HP, increase lifesteal rate by 20%, and enter the <Moon Hidden> state for 1 turn and receive an additional 15% damage.\n#F10#\n#F40#<Moon Hidden>: Special effect, cannot be chosen as a skill target. When receiving damage without sharing, 15% of the damage will be reduced and 10% of Aizen\'s max HP will be restored (not exceeding 500% Magical Damage). After the <Moon Hidden> effect ends, it switches to the <Invisible> state for 1 turn.',
		zawakeEffectDesc_en = 'Aizen attacks a single enemy target, dealing #C0x3D8A99#160% Magical Damage#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#special damage#C0x5B545B#, then causes himself and the darkest ally with the highest attack to immediately recover 10% of Aizen\'s max HP, increase lifesteal rate by 20%, and enter the <Moon Hidden> state for 1 turn and receive an additional 15% damage.\n#F10#\n#F40#<Moon Hidden>: Special effect, cannot be chosen as a skill target. When receiving damage without sharing, 15% of the damage will be reduced and 10% of Aizen\'s max HP will be restored (not exceeding 500% Magical Damage). After the <Moon Hidden> effect ends, it switches to the <Invisible> state for 1 turn.',
		zawakeEffectDesc_th = 'ไอเซ็นโจมตีเป้าหมายศัตรูเพียงหนึ่งเดียว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#160%#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# จากนั้นทำให้ตัวเองและพันธมิตรฝ่ายมืดที่มีพลังโจมตีสูงสุดฟื้นฟู HP สูงสุดของไอเซ็น 10%, เพิ่มอัตราดูดเลือด 20% และเข้าสู่สถานะ <Moon Hidden> เป็นเวลา 1 เทิร์น พร้อมรับความเสียหายเพิ่มอีก 15% \n#F10#\n#F40#<Moon Hidden>: เอฟเฟกต์พิเศษ ไม่สามารถถูกเลือกเป็นเป้าหมายของสกิล เมื่อรับความเสียหายโดยไม่แบ่งปัน จะลดความเสียหาย 15% และฟื้นฟู HP ไอเซ็น 10% ของสูงสุด (ไม่เกิน 500% ความเสียหายเวทมนตร์) หลังจากเอฟเฟกต์ <Moon Hidden> สิ้นสุด จะเปลี่ยนเป็นสถานะ <Invisible> เป็นเวลา 1 เทิร์น',
		zawakeEffectDesc_in = 'Aizen menyerang satu target musuh tunggal, memberikan #C0x3D8A99#160% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#kerusakan khusus#C0x5B545B#, lalu membuat dirinya dan rekan gelap dengan serangan tertinggi segera memulihkan 10% HP maksimal Aizen, meningkatkan 20% tingkat lifesteal dan masuk ke dalam status <Moon Hidden> selama 1 giliran serta menerima tambahan 15% kerusakan.\n#F10#\n#F40#<Moon Hidden>: Efek khusus, tidak dapat dipilih sebagai target skill. Saat menerima kerusakan tanpa berbagi, 15% kerusakan akan dikurangi dan 10% HP maksimal Aizen akan dipulihkan (tidak melebihi 500% Kerusakan Magis). Setelah efek <Moon Hidden> berakhir, akan berubah ke status <Invisible> selama 1 giliran.',
		zawakeEffectDesc_ph = 'Inaatake ni Aizen ang isang target na kaaway, nagbibigay ng #C0x3D8A99#160% Panlaban sa Mahika#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#espesyal na pinsala#C0x5B545B#, pagkatapos ay pinapayagan ang sarili niya at ang madilim na kakampi na may pinakamataas na atake na agad na magpagaling ng 10% ng pinakamataas na HP ni Aizen, tumaas ng 20% ang rate ng lifesteal at pumasok sa estado ng <Moon Hidden> sa loob ng 1 turn at tumanggap ng dagdag na 15% pinsala.\n#F10#\n#F40#<Moon Hidden>: Espesyal na epekto, hindi maaaring maging target ng skill. Kapag tumatanggap ng pinsala nang hindi naghahati, 15% ng pinsala ay mababawasan at 10% ng pinakamataas na HP ni Aizen ay gagalingin (hindi lalampas sa 500% Panlaban sa Mahika). Matapos matapos ang epekto ng <Moon Hidden>, ito ay babago sa estado ng <Invisible> sa loob ng 1 turn.',
		zawakeEffectDesc_ma = 'Aizen menyerang satu sasaran musuh sahaja, memberikan #C0x3D8A99#160% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#kerosakan khas#C0x5B545B#, kemudian menyebabkan dirinya dan rakan sekutu gelap dengan serangan tertinggi segera memulihkan 10% HP maksimum Aizen, menambah 20% kadar lifesteal dan memasuki keadaan <Moon Hidden> selama 1 pusingan serta menerima tambahan 15% kerosakan.\n#F10#\n#F40#<Moon Hidden>: Kesan khas, tidak boleh dipilih sebagai sasaran kemahiran. Apabila menerima kerosakan tanpa berkongsi, 15% kerosakan akan dikurangkan dan 10% HP maksimum Aizen akan dipulihkan (tidak melebihi 500% Kerosakan Magik). Selepas kesan <Moon Hidden> berakhir, ia akan bertukar ke keadaan <Invisible> selama 1 pusingan.',
		zawakeEffectDesc_vn = 'Aizen tấn công một mục tiêu địch duy nhất, gây #C0x3D8A99#160% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# sát thương đặc biệt#C0x5B545B#, sau đó khiến bản thân và đồng đội hắc ám có đòn tấn công cao nhất lập tức hồi phục 10% HP tối đa của Aizen, tăng thêm 20% tỉ lệ hút máu và vào trạng thái <Moon Hidden> trong 1 hiệp và nhận thêm 15% sát thương.\n#F10#\n#F40#<Moon Hidden>: Hiệu ứng đặc biệt, không thể chọn làm mục tiêu kỹ năng. Khi nhận sát thương không chia sẻ, 15% sát thương sẽ bị giảm và 10% máu tối đa của Aizen sẽ được phục hồi (không quá 500% Sát Thương Phép Thuật). Sau khi hiệu ứng <Ẩn mặt trăng> kết thúc, nó sẽ chuyển sang trạng thái <Vô hình> trong 1 hiệp.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Grants the highest-attack dark ally and Aizen a 20% lifesteal rate for 1 turn and instantly restores 10% of Aizen\'s max HP.',
		zawakeSimpleDesc_en = 'Grants the highest-attack dark ally and Aizen a 20% lifesteal rate for 1 turn and instantly restores 10% of Aizen\'s max HP.',
		zawakeSimpleDesc_th = 'มอบอัตราดูดเลือด 20% เป็นเวลา 1 เทิร์นให้กับ Aizen และพันธมิตรธาตุมืดที่มีพลังโจมตีสูงสุด พร้อมฟื้นฟู HP สูงสุดของ Aizen ทันที 10%',
		zawakeSimpleDesc_in = 'Memberikan 20% lifesteal selama 1 giliran kepada Aizen dan rekan elemen kegelapan dengan serangan tertinggi, serta langsung memulihkan 10% HP maksimum Aizen.',
		zawakeSimpleDesc_ph = 'Nagbibigay ng 20% lifesteal sa loob ng 1 turn kay Aizen at sa pinakamalakas na dark ally, at agad na nagre-restore ng 10% ng max HP ni Aizen.',
		zawakeSimpleDesc_ma = 'Memberi 20% kebolehan menyedut nyawa selama 1 pusingan kepada Aizen dan sekutu elemen gelap dengan serangan tertinggi, serta-merta memulihkan 10% HP maksimum Aizen.',
		zawakeSimpleDesc_vn = 'Tạo cho bản thân và đồng đội bóng tối có đòn tấn công cao nhất 20% tỷ lệ hút mạng trong 1 hiệp và ngay lập tức phục hồi 10% máu tối đa cho Aizen.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
