		simDesc_vn = 'Độc Bạch Bì bay lên không trung, đảo ngược và phun ra một lượng lớn độc tố, tấn công toàn bộ hàng kẻ thù, gây trạng thái trúng độc cho mục tiêu và ngay lập tức tính toán sát thương từ độc.',
		simDesc_en = 'Dok Bach Bi flies into the air, reverses direction, and spits out a large amount of toxin, attacking the entire row of enemies, inflicting poison status on the targets and immediately calculating poison damage.',
		simDesc_th = 'ด๊อกบัคบี บินขึ้นสู่อากาศ พลิกตัวและพ่นสารพิษจำนวนมาก โจมตีแถวศัตรูทั้งหมด ก่อให้เกิดสถานะถูกพิษกับเป้าหมายและคำนวณความเสียหายจากพิษทันที',
		simDesc_in = 'Dok Bach Bi terbang ke udara, berbalik, dan meludahkan sejumlah besar racun, menyerang seluruh baris musuh, menyebabkan status keracunan pada target dan langsung menghitung kerusakan racun.',
		simDesc_ph = 'Lumilipad si Dok Bach Bi pataas, umiikot at lumalabas ng malaking halaga ng lason, umaatake sa buong hanay ng mga kalaban, nagdudulot ng poison status sa mga target at agad na kinakalkula ang damage mula sa poison.',
		simDesc_ma = 'Dok Bach Bi terbang ke udara, berpusing dan memuntahkan sejumlah besar racun, menyerang seluruh barisan musuh, menyebabkan status diracun pada sasaran dan segera mengira kerosakan daripada racun.',
		simDesc = 'Dok Bach Bi flies into the air, reverses direction, and spits out a large amount of toxin, attacking the entire row of enemies, inflicting poison status on the targets and immediately calculating poison damage.',
		starEffect = __data_t__starEffect[41313],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng Tăng Cường: Gây 2 lớp <Độc> lên mục tiêu và tạm thời tăng 10% tỷ lệ chí mạng và 30% sát thương chí mạng trước khi tính toán sát thương từ độc.',
		starEffectDesc = 'Enhancement Effect: Applies 2 layers of <Poison> to the target and temporarily increases critical hit rate by 10% and critical damage by 30% before calculating damage from poison.',
		starEffectDesc_en = 'Enhancement Effect: Applies 2 layers of <Poison> to the target and temporarily increases critical hit rate by 10% and critical damage by 30% before calculating damage from poison.',
		starEffectDesc_th = 'Enhancement Effect: Gây 2 lớp <Độc> lên mục tiêu và tạm thời tăng 10% tỷ lệ chí mạng và 30% sát thương chí mạng trước khi tính toán sát thương từ độc.',
		starEffectDesc_in = 'Enhancement Effect: Gây 2 lớp <Độc> lên mục tiêu và tạm thời tăng 10% tỷ lệ chí mạng và 30% sát thương chí mạng trước khi tính toán sát thương từ độc.',
		starEffectDesc_ph = 'Enhancement Effect: Gây 2 lớp <Độc> lên mục tiêu và tạm thời tăng 10% tỷ lệ chí mạng và 30% sát thương chí mạng trước khi tính toán sát thương từ độc.',
		starEffectDesc_ma = 'Enhancement Effect: Gây 2 lớp <Độc> lên mục tiêu và tạm thời tăng 10% tỷ lệ chí mạng và 30% sát thương chí mạng trước khi tính toán sát thương từ độc.',
		zawakeEffect = __data_t__zawakeEffect[41313],
		-- {79003}
		zawakeEffectDesc = 'Poison Baby flies into the air, spraying a large amount of poison while standing upside down and attacking enemy targets in a row, dealing #C0x3D8A99#290% Magical Damage#C0x5B545B#+$(skillLevel*4*48) $\'s #C0xF13B54# Magical Damage #C0x5B545B# applying 1 layer of <poison> to targets for 3 turns and immediately inflicting poison damage once, while increasing damage dealt by 30% to targets with less than 30% health.',
		zawakeEffectDesc_en = 'Poison Baby flies into the air, spraying a large amount of poison while standing upside down and attacking enemy targets in a row, dealing #C0x3D8A99#290% Magical Damage#C0x5B545B#+$(skillLevel*4*48) $\'s #C0xF13B54# Magical Damage #C0x5B545B# applying 1 layer of <poison> to targets for 3 turns and immediately inflicting poison damage once, while increasing damage dealt by 30% to targets with less than 30% health.',
		zawakeEffectDesc_th = 'Poison Baby บินขึ้นกลางอากาศ พ่นพิษจำนวนมากขณะยืนหัวทิ่มและโจมตีเป้าหมายศัตรูตามแนวแถว สร้างความเสียหาย #C0x3D8A99#290% พิษเวทย์มนตร์#C0x5B545B#+$(skillLevel*4*48) $\'s #C0xF13B54# ความเสียหายเวทย์มนตร์ #C0x5B545B# ทำให้เป้าหมายติด <พิษ> 1 ชั้นเป็นเวลา 3 เทิร์น และทันทีที่สร้างความเสียหายพิษครั้งหนึ่ง พร้อมเพิ่มความเสียหายที่ทำกับเป้าหมายที่มีพลังชีวิตต่ำกว่า 30% ขึ้น 30%.',
		zawakeEffectDesc_in = 'Poison Baby terbang ke udara, menyemprotkan sejumlah besar racun sambil berdiri terbalik dan menyerang target musuh dalam satu baris, memberikan #C0x3D8A99#290% Kerusakan Magis#C0x5B545B#+$(skillLevel*4*48) $\'s #C0xF13B54# Kerusakan Magis #C0x5B545B# menerapkan 1 lapis <racun> kepada target selama 3 giliran dan segera memberikan kerusakan racun sekali, sekaligus meningkatkan 30% kerusakan yang diberikan kepada target dengan kesehatan di bawah 30%.',
		zawakeEffectDesc_ph = 'Poison Baby lumilipad sa hangin, sumisiklab ng malaking dami ng lason habang nakatindig nang nakabaligtad at umaatake sa mga target ng kaaway ayon sa hilera, nagdadala ng #C0x3D8A99#290% Pinsalang Mahiwaga#C0x5B545B#+$(skillLevel*4*48) $\'s #C0xF13B54# Pinsalang Mahiwaga #C0x5B545B# na naglalapat ng 1 patong ng <lason> sa mga target sa loob ng 3 turn at agad na nagpapataw ng pinsalang lason isang beses, kasabay ng pagtaas ng 30% pinsala laban sa mga target na may buhay na mas mababa sa 30%.',
		zawakeEffectDesc_ma = 'Poison Baby terbang ke udara, menyembur sejumlah besar racun sambil berdiri terbalik dan menyerang sasaran musuh secara berbaris, memberikan #C0x3D8A99#290% Kerosakan Magik#C0x5B545B#+$(skillLevel*4*48) $\'s #C0xF13B54# Kerosakan Magik #C0x5B545B# memberikan 1 lapisan <racun> kepada sasaran selama 3 pusingan dan segera memberikan kerosakan racun sekali, serta meningkatkan 30% kerosakan yang diberikan kepada sasaran dengan darah di bawah 30%.',
		zawakeEffectDesc_vn = 'Poison Baby bay lên không trung, phun ra một lượng lớn nọc độc khi đứng lộn ngược và tấn công các mục tiêu địch theo hàng, gây ra #C0x3D8A99#290% Sát Thương Phép Thuật#C0x5B545B#+$(skillLevel*4*48) $\'s #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# áp dụng 1 lớp <độc> cho mục tiêu trong 3 lượt và ngay lập tức giải quyết sát thương độc một lần, đồng thời tăng 30% sát thương gây ra cho mục tiêu có máu dưới 30%.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Deals 30% more damage to targets below 30% HP',
		zawakeSimpleDesc_en = '#C0x5c9970#Deals 30% more damage to targets below 30% HP',
		zawakeSimpleDesc_th = '#C0x5c9970#สร้างความเสียหายเพิ่มขึ้น 30% กับเป้าหมายที่มี HP ต่ำกว่า 30%',
		zawakeSimpleDesc_in = '#C0x5c9970#Memberikan 30% lebih banyak damage kepada target dengan HP di bawah 30%',
		zawakeSimpleDesc_ph = '#C0x5c9970#Nagbibigay ng 30% karagdagang damage sa mga target na may HP na mas mababa sa 30%',
		zawakeSimpleDesc_ma = '#C0x5c9970#Menangani 30% lebih banyak kerosakan kepada sasaran yang mempunyai HP di bawah 30%',
		zawakeSimpleDesc_vn = '#C0x5c9970#Gây sát thương tăng 30% đối với mục tiêu có sinh mệnh dưới 30%',
