	[41316] = {
		id = 41316,
		skillName_vn = 'UB: Dính chặt',
		skillName_en = 'Stuck',
		skillName_th = 'ติดแน่น',
		skillName_in = 'Tertempel',
		skillName_ph = 'Naka-dikit',
		skillName_ma = 'Tersekat',
		skillName = 'Stuck',
		describe_vn = 'Chất độc của Bé Độc có độ dính mạnh, khiến mục tiêu trúng độc giảm 20% tốc độ; khi tiêu diệt anh hùng sẽ khiến bản thân nhận được [Tăng cường Dị Thú]\n#F20#\n#F40#[Trúng độc] hiệu ứng tiêu cực, khi kết thúc hành động gây sát thương thực 40% Phép Công, sát thương này có thể chí mạng, tối đa cộng dồn 5 tầng\n[Tăng cường Dị Thú]: Vĩnh viễn tăng 10% tỷ lệ chí mạng và #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# sát thương chí mạng, có thể cộng dồn',
		describe_en = 'Bé Độc\'s poison has strong adhesion, causing poisoned targets to have their speed reduced by 20%; killing a hero grants [Mutated Beast Enhancement]\n#F20#\n#F40#[Poisoned] negative effect to self. At the end of the action, it deals true damage equal to 40% of Magic Attack. This damage can critically strike and stacks up to 5 layers.\n[Mutated Beast Enhancement]: Permanently increases critical rate by 10% and #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# critical damage, stackable.',
		describe_th = 'พิษของเบ็โด๊กมีความหนืดสูง ทำให้เป้าหมายที่ถูกพิษมีความเร็วลดลง 20%; การฆ่าวีรบุรุษจะทำให้ตัวเองได้รับ [การเสริมพลังอสูรกลายพันธุ์]\n#F20#\n#F40#[ถูกพิษ] ผลเสีย และเมื่อสิ้นสุดการกระทำจะสร้างความเสียหายจริงเท่ากับ 40% ของพลังเวท ความเสียหายนี้สามารถวิกฤตได้ และสะสมได้สูงสุด 5 ชั้น\n[การเสริมพลังอสูรกลายพันธุ์]: เพิ่มอัตราคริติคอลถาวร 10% และ #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# ความเสียหายคริติคอล สามารถสะสมได้',
		describe_in = 'Racun Bé Độc memiliki daya rekat yang kuat, menyebabkan target yang teracuni kehilangan 20% kecepatan; membunuh pahlawan akan memberikan efek negatif [Peningkatan Biarawan Mutasi]\n#F20#\n#F40#[Teracuni] pada diri sendiri. Saat akhir aksi, memberikan damage nyata sebesar 40% dari Serangan Sihir. Damage ini dapat mengenai kritikal dan dapat bertumpuk hingga 5 lapisan.\n[Peningkatan Biarawan Mutasi]: Permanen meningkatkan kritikal rate sebesar 10% dan #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# damage kritikal, dapat bertumpuk.',
		describe_ph = 'Ang lason ni Bé Độc ay may matibay na pagkakadikit, na nagbabawas ng 20% ng bilis ng target na nalason; kapag napatay ang bayani, makakatanggap ang sarili ng negatibong epekto na [Pinalakas na Mutant na Hayop]\n#F20#\n#F40#[Nalason]. Sa pagtatapos ng pagkilos, nagdudulot ito ng tunay na pinsala na katumbas ng 40% ng Magic Attack, ang pinsalang ito ay maaaring maging kritikal at maaaring mag-stack nang hanggang 5 layers.\n[Pinalakas na Mutant na Hayop]: Permanently nagdaragdag ng 10% critical rate at #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# critical damage, at maaari itong mag-stack.',
		describe_ma = 'Racun Bé Độc mempunyai daya lekat yang kuat, menyebabkan sasaran yang diracun berkurang 20% kelajuan; membunuh wira akan memberikan kesan negatif [Peningkatan Haiwan Mutasi]\n#F20#\n#F40#[Diracun] kepada diri sendiri. Pada akhir tindakan, akan menyebabkan kerosakan sebenar sebanyak 40% Serangan Sihir. Kerosakan ini boleh menjadi kritikal dan boleh bertimbun hingga 5 lapisan.\n[Peningkatan Haiwan Mutasi]: Meningkatkan kekal kadar kritikal sebanyak 10% dan #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# kerosakan kritikal, boleh bertimbun.',
		describe = 'Bé Độc\'s poison has strong adhesion, causing poisoned targets to have their speed reduced by 20%; killing a hero grants [Mutated Beast Enhancement]\n#F20#\n#F40#[Poisoned] negative effect to self. At the end of the action, it deals true damage equal to 40% of Magic Attack. This damage can critically strike and stacks up to 5 layers.\n[Mutated Beast Enhancement]: Permanently increases critical rate by 10% and #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# critical damage, stackable.',
		starEffect = __data_t__starEffect[41316],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Bổ Sung: Khi kỹ năng chủ động gây chí mạng, sẽ thêm 1 lớp <Độc> lên mục tiêu trong 3 lượt.',
		starEffectDesc = 'Supplement Effect: When the active skill causes a critical hit, it will add a layer of <Poison> to the target for 3 turns.',
		starEffectDesc_en = 'Supplement Effect: When the active skill causes a critical hit, it will add a layer of <Poison> to the target for 3 turns.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อทักษะเชิงรุกทำให้เกิดคริติคอล จะเพิ่มชั้น <พิษ> ให้กับเป้าหมายเป็นเวลา 3 เทิร์น',
		starEffectDesc_in = 'Efek Tambahan: Saat skill aktif menyebabkan serangan kritis, akan menambahkan 1 lapisan <Racun> pada target selama 3 giliran.',
		starEffectDesc_ph = 'Supplement Effect: Kapag ang aktibong kakayahan ay nagdudulot ng kritikal na tama, magdaragdag ito ng 1 layer ng <Poison> sa target sa loob ng 3 turn.',
		starEffectDesc_ma = 'Kesan Tambahan: Apabila kemahiran aktif menyebabkan serangan kritikal, ia akan menambah 1 lapisan <Racun> kepada sasaran selama 3 giliran.',
		zawakeEffect = __data_t__zawakeEffect[41316],
		-- {79004}
		zawakeEffectDesc = 'Poison Baby\'s toxin has strong adhesion, reducing the speed of poisoned targets by 20%; when killing a champion, the target will receive <Exotic Beast Boost>\n#F20# \n#F40#<Poisoned> negative effect, causing 40% true damage of Magical Damage at the end of the action. This damage can cause a critical hit and can stack up to 5 times\n<Alien Monster Improvement> : Permanently increases own critical hit rate by 10% and #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B#Critical damage, stackable; each skill activated without a critical hit increases own critical rate by 5%, this rate can be stacked. removed after a critical hit is successfully triggered.',
		zawakeEffectDesc_en = 'Poison Baby\'s toxin has strong adhesion, reducing the speed of poisoned targets by 20%; when killing a champion, the target will receive <Exotic Beast Boost>\n#F20# \n#F40#<Poisoned> negative effect, causing 40% true damage of Magical Damage at the end of the action. This damage can cause a critical hit and can stack up to 5 times\n<Alien Monster Improvement> : Permanently increases own critical hit rate by 10% and #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B#Critical damage, stackable; each skill activated without a critical hit increases own critical rate by 5%, this rate can be stacked. removed after a critical hit is successfully triggered.',
		zawakeEffectDesc_th = 'พิษของ Poison Baby มีความเหนียวแน่นสูง ช่วยลดความเร็วของเป้าหมายที่ได้รับพิษลง 20%; เมื่อฆ่าฆ่าตัวละคร เป้าหมายจะได้รับ <Exotic Beast Boost>\n#F20# \n#F40#<ถูกพิษ> ผลกระทบทางลบ ก่อให้เกิดความเสียหายจริง 40% ของความเสียหายเวทย์มนตร์เมื่อสิ้นสุดการกระทำ ความเสียหายนี้สามารถก่อให้เกิดการโจมตีคริติคอลได้และสามารถทับซ้อนได้สูงสุด 5 ครั้ง\n<พัฒนาการสัตว์ประหลาดต่างดาว> : เพิ่มอัตราการโจมตีคริติคอลของตนถาวร 10% และ #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B#ความเสียหายคริติคอล, ทับซ้อนกันได้; ทุกทักษะที่เปิดใช้โดยไม่มีการโจมตีคริติคอล จะเพิ่มอัตราคริติคอลของตนขึ้น 5%, อัตรานี้สามารถทับซ้อนได้ ถูกลบเมื่อโจมตีคริติคอลสำเร็จ',
		zawakeEffectDesc_in = 'Racun Poison Baby memiliki daya rekat kuat, mengurangi kecepatan target yang terkena racun sebesar 20%; saat membunuh jagoan, target akan menerima efek negatif <Exotic Beast Boost>\n#F20# \n#F40#<Teracuni>, menyebabkan 40% kerusakan nyata dari Kerusakan Magis saat aksi berakhir. Kerusakan ini dapat menyebabkan serangan kritikal dan bisa bertumpuk hingga 5 kali\n<Peningkatan Monster Alien> : Permanen meningkatkan tingkat serangan kritikal sendiri sebesar 10% dan #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B#Kerusakan kritikal, bisa bertumpuk; setiap skill yang diaktifkan tanpa serangan kritikal akan meningkatkan tingkat kritikal sendiri sebesar 5%, tingkat ini bisa bertumpuk. dihapus setelah serangan kritikal berhasil diaktifkan.',
		zawakeEffectDesc_ph = 'Ang lason ng Poison Baby ay may malakas na pagdikit, tumutulong na bawasan ang bilis ng target na nalunod sa lason ng 20%; kapag napatay ang isang kampiyon, ang target ay makakatanggap ng negatibong epekto ng <Exotic Beast Boost>\n#F20# \n#F40#<Nalason>, na nagdudulot ng 40% totoong pinsala mula sa Magical Damage kapag natapos ang aksyon. Ang pinsalang ito ay maaaring magdulot ng kritikal na atake at maaaring mag-stack hanggang 5 beses\n<Pagpapahusay ng Alien na Halimaw> : Permanenteng pinapataas ang sariling critical hit rate ng 10% at #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B#Critical damage, maaaring mag-stack; bawat skill na magagamit nang walang kritikal na atake ay nagpapataas ng sariling critical rate ng 5%, ang rate na ito ay maaaring mag-stack. tinatanggal pagkatapos matagumpay na ma-trigger ang isang kritikal na atake.',
		zawakeEffectDesc_ma = 'Racun Poison Baby mempunyai daya lekat yang kuat, membantu mengurangkan kelajuan sasaran yang terkena racun sebanyak 20%; apabila membunuh juara, sasaran akan menerima kesan negatif <Exotic Beast Boost>\n#F20# \n#F40#<Terkontaminasi>, menyebabkan 40% kerosakan sebenar daripada Kerosakan Magik apabila tindakan tamat. Kerosakan ini boleh menyebabkan serangan kritikal dan boleh bertindih sehingga 5 kali\n<Peningkatan Raksasa Alien> : Meningkatkan kadar serangan kritikal sendiri secara kekal sebanyak 10% dan #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B#Kerosakan kritikal, boleh bertindih; setiap kemahiran yang diaktifkan tanpa serangan kritikal akan meningkatkan kadar kritikal sendiri sebanyak 5%, kadar ini boleh bertindih. dibuang selepas serangan kritikal berjaya diaktifkan.',
		zawakeEffectDesc_vn = 'Độc tố của Poison Baby có độ dính mạnh, giúp giảm 20% tốc độ của mục tiêu bị nhiễm độc; khi giết tướng, mục tiêu sẽ nhận được <Exotic Beast Boost>\n#F20# \n#F40#<Ngộ độc> hiệu ứng tiêu cực, gây ra 40% sát thương thực sự của Sát Thương Phép Thuật khi kết thúc hành động. Sát thương này có thể gây ra một đòn chí mạng và có thể cộng dồn lên tới 5 lớp\n<Cải tiến quái vật ngoài hành tinh> : Tăng vĩnh viễn tỷ lệ đòn chí mạng của bản thân thêm 10% và #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B#Sát thương chí mạng, có thể cộng dồn; mỗi kỹ năng kích hoạt không có đòn chí mạng sẽ tăng tỷ lệ chí mạng của bản thân lên 5%, tỷ lệ này có thể được cộng dồn. bị xóa sau khi một đòn chí mạng được kích hoạt thành công.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Each time an active skill doesn\'t crit, your crit rate increases by 5%, stackable, and is cleared upon a successful critical hit.',
		zawakeSimpleDesc_en = '#C0x5c9970#Each time an active skill doesn\'t crit, your crit rate increases by 5%, stackable, and is cleared upon a successful critical hit.',
		zawakeSimpleDesc_th = '#C0x5c9970#ทุกครั้งที่ใช้สกิลแอคทีฟไม่ติดคริติคอล อัตราคริติคอลจะเพิ่มขึ้น 5% สามารถสะสมได้ และจะหายไปเมื่อโจมตีคริติคอลสำเร็จ',
		zawakeSimpleDesc_in = '#C0x5c9970#Setiap kali skill aktif tidak menghasilkan critical, tingkat critical-mu meningkat 5%, dapat ditumpuk, dan akan dihapus saat critical berhasil',
		zawakeSimpleDesc_ph = '#C0x5c9970#Bawat beses na ang aktibong skill ay hindi critical, tataas ng 5% ang crit rate mo, maaaring maipon, at mawawala kapag nag-critical nang matagumpay',
		zawakeSimpleDesc_ma = '#C0x5c9970#Setiap kali kemahiran aktif gagal melakukan kritikal, kadar kritikal anda meningkat 5%, boleh ditindih, dan akan dipadam selepas kritikal berjaya',
		zawakeSimpleDesc_vn = '#C0x5c9970#Mỗi lần kỹ năng chủ động không chí mạng sẽ tăng 5% tỷ lệ chí mạng của bản thân, có thể cộng dồn, khi kích hoạt chí mạng thành công sẽ xóa bỏ hiệu ứng này.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
