	[41323] = {
		id = 41323,
		skillName_vn = 'Độc tố tràn ngập',
		skillName_en = 'Toxin overload',
		skillName_th = 'สารพิษล้นหลาม',
		skillName_in = 'Racun berlebih',
		skillName_ph = 'Sobra sa lason',
		skillName_ma = 'Toksin berlebihan',
		skillName = 'Toxin overload',
		describe_vn = 'Tứ Hàm Châm Long tập hợp chất độc thành một quả cầu lớn ném lên trời, sau đó phát nổ thành mưa chất độc tấn công mục tiêu hàng ngang của kẻ địch, gây #C0x3D8A99#300% Phép Công#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, áp dụng 1 tầng [Trúng độc] trong 3 lượt và ngay lập tức tính toán một lần sát thương trúng độc',
		describe_en = 'The Four Fang Poison Dragon gathers poison into a large orb and throws it into the sky, then it explodes into a shower of poison attacks targeting the enemy\'s horizontal row, dealing #C0x3D8A99#300% Magic Power#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Magic Damage #C0x5B545B#, applies 1 stack of [Poisoned] for 3 turns and immediately calculates poison damage once.',
		describe_th = 'ตู่ห่ำฉามหลงรวบรวมสารพิษเป็นลูกบอลใหญ่แล้วขว้างขึ้นฟ้า จากนั้นระเบิดเป็นฝนสารพิษโจมตีเป้าหมายแถวแนวนอนของศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#300%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# พลังโจมตีเวทมนตร์ #C0x5B545B# และเพิ่มสถานะ [ถูกพิษ] 1 ชั้นนาน 3 เทิร์น พร้อมคำนวณความเสียหายจากพิษทันทีหนึ่งครั้ง',
		describe_in = 'Empat Taring Ular Racun mengumpulkan racun menjadi bola besar dan melemparkannya ke langit, kemudian meledak menjadi hujan racun yang menyerang target bar horizontal musuh, memberikan #C0x3D8A99#300% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerusakan Sihir #C0x5B545B#, menerapkan 1 tumpukan [Terkontaminasi Racun] selama 3 giliran dan segera menghitung kerusakan racun sekali.',
		describe_ph = 'Ang Apat na Pangil ng Ahas na Lason ay nagtitipon ng lason sa isang malaking bola at itinatapon ito sa langit, pagkatapos ay sumabog ito bilang pag-ulan ng lason na umaatake sa pahalang na linya ng mga kalaban, na nagdudulot ng #C0x3D8A99#300% Kapangyarihan ng Magic#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Pinsalang Magic #C0x5B545B#, naglalagay ng 1 stack ng [Na-lason] sa loob ng 3 turn at kaagad na kinakalkula ang isang beses na pinsalang dulot ng lason.',
		describe_ma = 'Empat Taring Naga Racun mengumpulkan racun menjadi satu bola besar dan melemparkannya ke langit, kemudian meletup menjadi hujan racun yang menyerang baris mendatar musuh, menyebabkan #C0x3D8A99#300% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerosakan Sihir #C0x5B545B#, mengenakan 1 lapisan [Beracun] selama 3 pusingan dan serta-merta mengira kerosakan beracun sekali.',
		describe = 'The Four Fang Poison Dragon gathers poison into a large orb and throws it into the sky, then it explodes into a shower of poison attacks targeting the enemy\'s horizontal row, dealing #C0x3D8A99#300% Magic Power#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Magic Damage #C0x5B545B#, applies 1 stack of [Poisoned] for 3 turns and immediately calculates poison damage once.',
		simDesc_vn = 'Tứ Nhạc Châm Long tụ tập độc tố thành một quả cầu độc lớn ném lên không trung, sau đó phát nổ thành độc tố tấn công toàn bộ hàng kẻ thù, gây trạng thái trúng độc cho mục tiêu và ngay lập tức tính toán sát thương từ độc.',
		simDesc_en = 'The Four Music Piercing Dragons gather poison into a large toxic orb and throw it into the air, which then explodes into poison attacking the entire enemy row, inflicting a poisoned status on targets and immediately calculating poison damage.',
		simDesc_th = 'เหล่ามังกรพิษเสียงสี่ตัวรวบรวมพิษเป็นลูกบอลพิษขนาดใหญ่แล้วขว้างขึ้นฟ้า จากนั้นระเบิดเป็นพิษโจมตีแถวศัตรูทั้งหมด ทำให้เป้าหมายติดสถานะถูกพิษและคำนวณความเสียหายจากพิษทันที',
		simDesc_in = 'Empat Naga Musik mengumpulkan racun menjadi bola racun besar lalu melemparkannya ke udara, kemudian meledak menjadi racun yang menyerang seluruh barisan musuh, menyebabkan status keracunan pada target dan langsung menghitung kerusakan dari racun tersebut.',
		simDesc_ph = 'Ang Apat na Melodiyang Dragon ay nagtipon ng lason sa isang malaking lason na bola at itinapon ito sa himpapawid, pagkatapos ay sumabog ito bilang lason na sumasalakay sa buong hanay ng mga kalaban, nagdudulot ng status na nalason sa mga target at agad na kinakalkula ang pinsala mula sa lason.',
		simDesc_ma = 'Empat Naga Muzik mengumpulkan racun menjadi bola racun besar dan melemparkannya ke udara, kemudian meletup menjadi racun yang menyerang keseluruhan barisan musuh, menyebabkan status diracun pada sasaran dan serta-merta mengira kerosakan daripada racun itu.',
		simDesc = 'The Four Music Piercing Dragons gather poison into a large toxic orb and throw it into the air, which then explodes into poison attacking the entire enemy row, inflicting a poisoned status on targets and immediately calculating poison damage.',
		starEffect = __data_t__starEffect[41323],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng Tăng Cường: Gây 2 lớp <Độc> lên mục tiêu và tạm thời tăng 10% tỷ lệ chí mạng và 30% sát thương chí mạng trước khi tính toán sát thương từ độc.',
		starEffectDesc = 'Enhancement Effect: Applies 2 layers of <Poison> on the target and temporarily increases critical rate by 10% and critical damage by 30% before calculating poison damage.',
		starEffectDesc_en = 'Enhancement Effect: Applies 2 layers of <Poison> on the target and temporarily increases critical rate by 10% and critical damage by 30% before calculating poison damage.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: ก่อให้เกิด <พิษ> 2 ชั้นกับเป้าหมายและเพิ่มอัตราคริติคอลชั่วคราว 10% และความเสียหายคริติคอล 30% ก่อนการคำนวณความเสียหายจากพิษ',
		starEffectDesc_in = 'Efek Penguatan: Memberikan 2 lapis <Racun> pada target dan sementara meningkatkan 10% peluang serangan kritis serta 30% kerusakan kritis sebelum menghitung kerusakan racun.',
		starEffectDesc_ph = 'Epekto ng Pagpapalakas: Nagdudulot ng 2 layer ng <Lason> sa target at pansamantalang nagdaragdag ng 10% na tsansa ng kritikal at 30% na pinsalang kritikal bago kalkulahin ang pinsala mula sa lason.',
		starEffectDesc_ma = 'Kesan Penguatan: Menyebabkan 2 lapisan <Racun> pada sasaran dan sementara meningkatkan 10% kadar kritikal dan 30% kerosakan kritikal sebelum mengira kerosakan daripada racun.',
		zawakeEffect = __data_t__zawakeEffect[41323],
		-- {79003}
		zawakeEffectDesc = 'The golden four-jaw dragon condenses poison into a large poison sphere and throws it into the sky, then explodes into a poison-filled sky to attack the enemy\'s target, causing a magical attack of #C0x3D8A99#300%#C0x5B545B#+$( skillLevel *4*48)$\'s #C0xF13B54# Magic Damage #C0x5B545B# applying 1 layer of <poison> to the target for 3 turns and instantly dealing poison damage once, while increasing damage dealt to targets with health below 30% by 30%.',
		zawakeEffectDesc_en = 'The golden four-jaw dragon condenses poison into a large poison sphere and throws it into the sky, then explodes into a poison-filled sky to attack the enemy\'s target, causing a magical attack of #C0x3D8A99#300%#C0x5B545B#+$( skillLevel *4*48)$\'s #C0xF13B54# Magic Damage #C0x5B545B# applying 1 layer of <poison> to the target for 3 turns and instantly dealing poison damage once, while increasing damage dealt to targets with health below 30% by 30%.',
		zawakeEffectDesc_th = 'มังกรทองสี่ขากรวมพิษเป็นลูกพิษขนาดใหญ่แล้วขว้างขึ้นฟ้า จากนั้นระเบิดเป็นท้องฟ้าเต็มไปด้วยพิษเพื่อโจมตีเป้าหมายของศัตรู ทำความเสียหายเวทมนตร์ #C0x3D8A99#300%#C0x5B545B#+$( ระดับทักษะ *4*48)$\'s #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# ใช้ 1 ชั้นของ <พิษ> กับเป้าหมายเป็นเวลา 3 เทิร์น และทันทีที่สร้างความเสียหายจากพิษครั้งหนึ่ง พร้อมทั้งเพิ่มความเสียหายที่ทำกับเป้าหมายที่มีพลังชีวิตต่ำกว่า 30% ขึ้น 30%',
		zawakeEffectDesc_in = 'Naga empat rahang emas mengkondensasi racun menjadi bola racun besar dan melemparkannya ke langit, lalu meledak menjadi langit penuh racun untuk menyerang target musuh, menyebabkan serangan magis #C0x3D8A99#300%#C0x5B545B#+$( tingkat keterampilan *4*48)$\'s #C0xF13B54# Kerusakan Sihir #C0x5B545B# menerapkan 1 lapisan <racun> ke target selama 3 giliran dan langsung memberikan kerusakan racun sekali, sekaligus meningkatkan kerusakan yang diberikan kepada target dengan darah di bawah 30% sebesar 30%.',
		zawakeEffectDesc_ph = 'Ang gintong apat na panga na dragon ay nagko-kondensa ng lason sa isang malaking bola ng lason at itinatapon ito sa langit, pagkatapos ay sumabog sa isang langit na punong-puno ng lason upang atakihin ang target ng kalaban, na nagdudulot ng magic attack na #C0x3D8A99#300%#C0x5B545B#+$( antas ng kasanayan *4*48)$\'s #C0xF13B54# Magic Damage #C0x5B545B# na naglalagay ng 1 layer ng <poison> sa target sa loob ng 3 turns at agad na nagpapadulot ng poison damage nang isang beses, kasabay ng pagtaas ng damage na ibinibigay sa mga target na may buhay sa ilalim ng 30% ng 30%.',
		zawakeEffectDesc_ma = 'Naga empat rahang emas menguapkan racun menjadi bola racun besar dan membalingnya ke langit, kemudian meletup menjadi langit yang penuh dengan racun untuk menyerang sasaran musuh, menyebabkan serangan magik #C0x3D8A99#300%#C0x5B545B#+$( tahap kemahiran *4*48)$\'s #C0xF13B54# Kerosakan Magik #C0x5B545B# menerapkan 1 lapisan <racun> kepada sasaran selama 3 pusingan dan segera menyelesaikan kerosakan racun sekali, sambil meningkatkan kerosakan yang diberikan kepada sasaran yang mempunyai darah di bawah 30% sebanyak 30%.',
		zawakeEffectDesc_vn = 'Rồng kim bốn hàm ngưng tụ nọc độc thành một quả cầu độc lớn và ném lên trời, sau đó nổ tung thành bầu trời đầy nọc độc để tấn công mục tiêu của kẻ địch, gây ra đòn tấn công ma thuật #C0x3D8A99#300%#C0x5B545B#+$( cấp độ kỹ năng *4*48)$\'s #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# áp dụng 1 lớp <độc> cho mục tiêu trong 3 lượt và ngay lập tức giải quyết sát thương độc một lần, đồng thời tăng sát thương gây ra cho mục tiêu có máu dưới 30% bằng 30%.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Deals 30% more damage to targets below 30% HP',
