	[41326] = {
		id = 41326,
		skillName_vn = 'UB: Mũi nhọn',
		skillName_en = 'Tip',
		skillName_th = 'ปลายแหลม',
		skillName_in = 'Ujung',
		skillName_ph = 'Dulo',
		skillName_ma = 'Hujung',
		skillName = 'Tip',
		describe_vn = 'Chất độc của Tứ Hàm Châm Long có độ dính mạnh, khiến mục tiêu trúng độc giảm 20% tốc độ; khi tiêu diệt anh hùng sẽ khiến bản thân nhận được [Tăng cường Dị Thú]\n#F20#\n#F40#[Trúng độc] hiệu ứng tiêu cực, khi kết thúc hành động gây sát thương thực 40% Phép Công, sát thương này có thể chí mạng, tối đa cộng dồn 5 tầng\n[Tăng cường Dị Thú]: Vĩnh viễn tăng 10% tỷ lệ chí mạng và #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# sát thương chí mạng, có thể cộng dồn',
		describe_en = 'The poison of the Four Jaw Needle Dragon has strong adhesion, causing poisoned targets to have their speed reduced by 20%; when defeating a hero, the user receives the [Beast Enhancement]\n#F20#\n#F40#[Poisoned] debuff effect. At the end of actions, it deals 40% True Damage of Magic Attack, which can critically strike, stacking up to 5 layers. \n[Beast Enhancement]: Permanently increases critical hit rate by 10% and #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# critical damage, stackable.',
		describe_th = 'พิษของมังกรเขี้ยวสี่มีความเหนียวแน่นสูง ทำให้เป้าหมายที่ถูกพิษลดความเร็วลง 20%; เมื่อกำจัดวีรบุรุษจะทำให้ตนเองได้รับผลลบ [การเสริมพลังสัตว์ประหลาด]\n#F20#\n#F40#[ถูกพิษ] เมื่อสิ้นสุดการกระทำจะสร้างความเสียหายจริง 40% ของพลังเวท ความเสียหายนี้สามารถเป็นคริติคอลได้ สะสมได้สูงสุด 5 ชั้น \n[การเสริมพลังสัตว์ประหลาด]: เพิ่มอัตราคริติคอลถาวร 10% และ #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# ความเสียหายคริติคอล ซึ่งสามารถสะสมได้',
		describe_in = 'Racun dari Naga Jarum Empat Rahang memiliki daya rekat kuat, menyebabkan target yang diracun mengalami pengurangan kecepatan sebesar 20%; saat mengalahkan pahlawan, pengguna mendapatkan efek negatif [Peningkatan Binatang Buas]\n#F20#\n#F40#[Diracun]. Pada akhir aksi, memberikan 40% Damage Sebenar dari Serangan Magic, damage ini bisa critical, maksimal bertumpuk hingga 5 lapis \n[Peningkatan Binatang Buas]: Permanen meningkatkan 10% peluang critical dan #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# damage kritikal, dapat bertumpuk.',
		describe_ph = 'Ang lason ng Apat na Panga ng Dragon ng Karayom ay may malakas na kapit, nagpapababa ng bilis ng target na nalason ng 20%; kapag napatay ang bayani, makakakuha ang sarili ng negatibong epekto ng [Pagpapalakas ng Halimaw]\n#F20#\n#F40#[Nalason]. Sa pagtatapos ng aksyon, nagdudulot ng 40% Tunay na Pinsala mula sa Magic Attack, maaaring magkaroon ng kritikal na tama, na maaaring mag-ipon hanggang 5 layers \n[Pagpapalakas ng Halimaw]: Permanently nagpapataas ng 10% kritikal na tsansa at #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# kritikal na pinsala, maaaring mag-ipon.',
		describe_ma = 'Racun Naga Jarum Empat Rahang mempunyai daya lekatan yang kuat, menyebabkan sasaran yang diracun berkurang 20% kelajuan; apabila mengalahkan wira, pengguna menerima kesan negatif [Peningkatan Binatang Buas]\n#F20#\n#F40#[Diracun]. Pada akhir tindakan, memberikan 40% Kerosakan Sebenar daripada Serangan Sihir, kerosakan ini boleh menjadi kritikal, maksimum bertimbun sehingga 5 lapisan \n[Peningkatan Binatang Buas]: Meningkatkan kadar kritikal sebanyak 10% secara kekal dan #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# kerosakan kritikal, boleh bertimbun.',
		describe = 'The poison of the Four Jaw Needle Dragon has strong adhesion, causing poisoned targets to have their speed reduced by 20%; when defeating a hero, the user receives the [Beast Enhancement]\n#F20#\n#F40#[Poisoned] debuff effect. At the end of actions, it deals 40% True Damage of Magic Attack, which can critically strike, stacking up to 5 layers. \n[Beast Enhancement]: Permanently increases critical hit rate by 10% and #C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B# critical damage, stackable.',
		starEffect = __data_t__starEffect[41326],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Bổ Sung: Khi kỹ năng chủ động gây chí mạng, sẽ gây 1 lớp <Độc> lên mục tiêu trong 3 lượt.',
		starEffectDesc = 'Supplementary Effect: When an active skill causes a critical hit, it will apply one layer of <Poison> on the target for 3 turns.',
		starEffectDesc_en = 'Supplementary Effect: When an active skill causes a critical hit, it will apply one layer of <Poison> on the target for 3 turns.',
		starEffectDesc_th = 'เอฟเฟ็กต์เสริม: เมื่อทักษะใช้งานก่อให้เกิดคริติคัล จะทำให้เกิดชั้น <พิษ> หนึ่งชั้นบนเป้าหมายเป็นเวลา 3 เทิร์น',
		starEffectDesc_in = 'Efek Tambahan: Saat keterampilan aktif mengenai serangan kritis, akan menyebabkan 1 lapisan <Racun> pada target selama 3 giliran.',
		starEffectDesc_ph = 'Karagdagang Epekto: Kapag ang aktibong kakayahan ay nagdulot ng kritikal na tama, magbibigay ito ng 1 patong ng <Nakakalason> sa target sa loob ng 3 turn.',
		starEffectDesc_ma = 'Kesan Tambahan: Apabila kemahiran aktif memberikan serangan kritikal, ia akan menyebabkan 1 lapisan <Racun> pada sasaran selama 3 pusingan.',
		zawakeEffect = __data_t__zawakeEffect[41326],
		-- {79004}
		zawakeEffectDesc = 'The poison of the Four-Jawed Golden Dragon has high adhesion, reducing the speed of poisoned targets by 20%; when killing a champion, you receive <Strange Beast Enhancement>\n#F20# \n#F40#<Poison> negative effect, dealing 40% true damage of Magic Damage at the end of the action. This damage can deal a critical hit and can stack up to 5 layers\n<Alien Monster Improvement>: Permanently increases the user\'s critical hit rate by 10% and #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B# Critical damage, which can stack; each skill activation without a critical hit increases the user\'s critical rate by 5%, and this rate can be stacked. It is reset after a successful critical hit is triggered.',
		zawakeEffectDesc_en = 'The poison of the Four-Jawed Golden Dragon has high adhesion, reducing the speed of poisoned targets by 20%; when killing a champion, you receive <Strange Beast Enhancement>\n#F20# \n#F40#<Poison> negative effect, dealing 40% true damage of Magic Damage at the end of the action. This damage can deal a critical hit and can stack up to 5 layers\n<Alien Monster Improvement>: Permanently increases the user\'s critical hit rate by 10% and #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B# Critical damage, which can stack; each skill activation without a critical hit increases the user\'s critical rate by 5%, and this rate can be stacked. It is reset after a successful critical hit is triggered.',
		zawakeEffectDesc_th = 'พิษของมังกรทองสี่กรามมีความหนืดสูง ลดความเร็วของเป้าหมายที่ถูกพิษลง 20%; เมื่อฆ่าผู้บัญชาการจะได้รับ <การเสริมมอนสเตอร์แปลก>\n#F20# \n#F40#<พิษ> ผลเสีย, สร้างความเสียหายจริง 40% ของความเสียหายเวทมนตร์เมื่อสิ้นสุดการกระทำ. ความเสียหายนี้สามารถสร้างคริติคอลและสามารถสะสมได้สูงสุด 5 ชั้น\n<การปรับปรุงสัตว์ประหลาดต่างดาว>: เพิ่มอัตราคริติคอลของผู้ใช้ถาวรเพิ่มขึ้น 10% และ #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B#ความเสียหายคริติคอล ซึ่งสามารถสะสมได้; ทุกการใช้สกิลที่ไม่มีคริติคอลจะเพิ่มอัตราคริติคอลของผู้ใช้ 5% และอัตรานี้สามารถสะสมได้ จะถูกรีเซ็ตหลังจากคริติคอลสำเร็จครั้งหนึ่งถูกกระตุ้น',
		zawakeEffectDesc_in = 'Racun Naga Emas Empat Rahang memiliki daya rekat tinggi, mengurangi kecepatan target yang diracuni sebesar 20%; saat membunuh jagoan, mendapatkan <Peningkatan Monster Aneh>\n#F20# \n#F40#<Racun> efek negatif, menyebabkan 40% kerusakan nyata dari Damage Magic saat akhir aksi. Kerusakan ini dapat memberikan serangan kritis dan dapat bertumpuk hingga 5 lapis\n<Peningkatan Monster Alien>: Permanen meningkatkan tingkat serangan kritis pengguna sebesar 10% dan #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B# Kerusakan kritis, dapat bertumpuk; setiap aktivasi skill tanpa serangan kritis akan meningkatkan tingkat kritis pengguna sebesar 5%, tingkat ini dapat bertumpuk. Dihapus setelah serangan kritis berhasil diaktifkan.',
		zawakeEffectDesc_ph = 'Ang lason ng Apat na Panga ng Gintong Dragon ay may mataas na pagdikit, nagpapababa ng bilis ng mga target na nalason ng 20%; kapag napatay ang champion ay makakatanggap ng <Kakaibang Pagpapaunlad ng Halimaw>\n#F20# \n#F40#<Lason> negatibong epekto, na nagdudulot ng 40% tunay na pinsala ng Magic Damage kapag natapos ang aksyon. Maaaring magdulot ang pinsalang ito ng critical hit at maaaring mag-stack hanggang 5 na layer\n<Pagsasaayos ng Alien na Halimaw>: Permanenteng nagpapataas ng sariling critical hit rate ng 10% at #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B# Critical damage, maaaring mag-stack; bawat activation ng skill na walang critical hit ay nagpapataas ng sariling critical rate ng 5%, at maaaring mag-stack ito. Nakakansela pagkatapos ma-activate nang matagumpay ang isang critical hit.',
		zawakeEffectDesc_ma = 'Racun Naga Emas Empat Rahang mempunyai daya lekat tinggi, mengurangkan kelajuan sasaran yang dijangkiti sebanyak 20%; apabila membunuh wira, akan menerima <Peningkatan Raksasa Aneh>\n#F20# \n#F40#<Racun> kesan negatif, menyebabkan 40% kerosakan sebenar daripada Kerosakan Sihir apabila tindakan berakhir. Kerosakan ini boleh menyebabkan serangan kritikal dan boleh bertimbun sehingga 5 lapisan\n<Peningkatan Raksasa Alien>: Meningkatkan kadar serangan kritikal diri sendiri secara kekal sebanyak 10% dan #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B# Kerosakan kritikal, boleh bertimbun; setiap pengaktifan kemahiran tanpa serangan kritikal akan meningkatkan kadar kritikal diri sendiri sebanyak 5%, kadar ini boleh bertimbun. Dibuang selepas serangan kritikal berjaya dicetuskan.',
		zawakeEffectDesc_vn = 'Chất độc của Rồng kim bốn hàm có độ bám dính cao, làm giảm 20% tốc độ của mục tiêu bị nhiễm độc; khi giết tướng sẽ nhận được <Cường hóa quái thú kỳ lạ>\n#F20# \n#F40#<Ngộ độc> hiệu ứng tiêu cực, gây ra 40% sát thương thực sự của Sát Thương Phép Thuật khi kết thúc hành động. Sát thương này có thể gây ra một đòn chí mạng và có thể cộng dồn lên tới 5 lớp\n<Cải tiến quái vật ngoài hành tinh> : Tăng vĩnh viễn tỷ lệ đòn chí mạng của bản thân thêm 10% và #C0x5c9970# $(15+skillLevel*0.1-0.1)$%#C0x5B545B#Sát thương chí mạng, có thể cộng dồn; mỗi kỹ năng kích hoạt không có đòn chí mạng sẽ tăng tỷ lệ chí mạng của bản thân lên 5%, tỷ lệ này có thể được cộng dồn. bị xóa sau khi một đòn chí mạng được kích hoạt thành công.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Each time an active skill doesn\'t crit, your crit rate increases by 5%, stackable, and is cleared upon a successful critical hit.',
		zawakeSimpleDesc_en = '#C0x5c9970#Each time an active skill doesn\'t crit, your crit rate increases by 5%, stackable, and is cleared upon a successful critical hit.',
		zawakeSimpleDesc_th = '#C0x5c9970#ทุกครั้งที่ใช้สกิลแอคทีฟไม่ติดคริติคอล อัตราคริติคอลจะเพิ่มขึ้น 5% สามารถสะสมได้ และจะหายไปเมื่อโจมตีคริติคอลสำเร็จ',
		zawakeSimpleDesc_in = '#C0x5c9970#Setiap kali skill aktif tidak menghasilkan critical, tingkat critical-mu meningkat 5%, dapat ditumpuk, dan akan dihapus saat critical berhasil',
		zawakeSimpleDesc_ph = '#C0x5c9970#Bawat beses na ang aktibong skill ay hindi critical, tataas ng 5% ang crit rate mo, maaaring maipon, at mawawala kapag nag-critical nang matagumpay',
		zawakeSimpleDesc_ma = '#C0x5c9970#Setiap kali kemahiran aktif gagal melakukan kritikal, kadar kritikal anda meningkat 5%, boleh ditindih, dan akan dipadam selepas kritikal berjaya',
		zawakeSimpleDesc_vn = '#C0x5c9970#Mỗi lần kỹ năng chủ động không chí mạng sẽ tăng 5% tỷ lệ chí mạng của bản thân, có thể cộng dồn, khi kích hoạt chí mạng thành công sẽ xóa bỏ hiệu ứng này.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		skillProcess = {413261, 413262, 413263}
	},
