	[41611] = {
		id = 41611,
		skillName_vn = 'Thần Lôi Trảm',
		skillName_en = 'Thunder God Slash',
		skillName_th = 'ฟันเทพสายฟ้า',
		skillName_in = 'Tebasan Dewa Petir',
		skillName_ph = 'Slash ng Thunder God',
		skillName_ma = 'Tebasan Dewa Kilat',
		skillName = 'Thunder God Slash',
		describe_vn = 'Minato chém mục tiêu đơn bằng Phi Lôi Thần Trảm, gây 180% công vật lý + thêm.\nTăng 15% công và 10% hút máu trong 2 lượt (cộng dồn 5 lần).',
		describe_en = 'Minato slashes a single enemy with Flying Thunder Slash, dealing 180% ATK + bonus Physical DMG.\nGains +15% ATK and +10% Lifesteal for 2 turns (stacks up to 5).',
		describe_th = 'มินาโตะใช้ ฟันสายฟ้าเหิน โจมตีศัตรูเดี่ยว สร้างความเสียหายกายภาพ 180% ATK + เพิ่ม\nเพิ่ม 15% พลังโจมตี และ 10% ดูดเลือด (สะสมได้ 5 ชั้น, 2 เทิร์น)',
		describe_in = 'Minato menebas musuh dengan Flying Thunder Slash, memberi 180% ATK + bonus Physical DMG.\nMeningkatkan 15% ATK dan 10% Lifesteal (2 giliran, tumpuk hingga 5).',
		describe_ph = 'Minato umatake gamit ang Flying Thunder Slash, dealing 180% ATK + dagdag Physical Damage.\nMakakuha ng +15% ATK at +10% Lifesteal (2 turn, stack hanggang 5).',
		describe_ma = 'Minato tebas musuh tunggal dengan Hirisan Kilat Terbang, beri 180% ATK + tambahan.\nDapat +15% ATK & +10% sedutan darah (2 giliran, hingga 5 lapis).',
		describe = 'Minato slashes a single enemy with Flying Thunder Slash, dealing 180% ATK + bonus Physical DMG.\nGains +15% ATK and +10% Lifesteal for 2 turns (stacks up to 5).',
		zawakeEffect = __data_t__zawakeEffect[41611],
		-- {79001}
		zawakeEffectDesc = 'Minato Namikaze uses Flying Thunder God Slash to strike a single enemy, dealing 180% ATK + $(skillLevel×4×24)$ physical damage. Increases own ATK by 15% and lifesteal by 10% (stackable up to 5 times) for 2 turns. Has an 80% chance to inflict Shock for 2 turns.',
		zawakeEffectDesc_en = 'Minato Namikaze uses Flying Thunder God Slash to strike a single enemy, dealing 180% ATK + $(skillLevel×4×24)$ physical damage. Increases own ATK by 15% and lifesteal by 10% (stackable up to 5 times) for 2 turns. Has an 80% chance to inflict Shock for 2 turns.',
		zawakeEffectDesc_th = 'มินาโตะใช้ ฟันเทพสายฟ้า โจมตีเป้าหมายเดี่ยว สร้างความเสียหายกายภาพ 180% ATK + $(skillLevel×4×24)$ เพิ่มพลังโจมตี 15% และดูดเลือด 10% (สะสมได้ 5 ชั้น) นาน 2 เทิร์น มีโอกาส 80% ทำให้ศัตรู ช็อก 2 เทิร์น',
		zawakeEffectDesc_in = 'Minato menggunakan Tebasan Dewa Petir untuk menyerang satu musuh, memberikan 180% ATK + $(skillLevel×4×24)$ kerusakan fisik. Meningkatkan ATK 15% dan lifesteal 10% (maks 5 tumpukan) selama 2 giliran. Peluang 80% menyebabkan Tersengat selama 2 giliran.',
		zawakeEffectDesc_ph = 'Si Minato ay gumagamit ng Slash ng Thunder God sa isang kalaban, nagdudulot ng 180% ATK + $(skillLevel×4×24)$ physical damage. Nagpapataas ng 15% ATK at 10% lifesteal (up to 5 stacks) sa loob ng 2 turn. May 80% chance na magdulot ng Shock sa loob ng 2 turn.',
		zawakeEffectDesc_ma = 'Minato melancarkan Tebasan Dewa Kilat ke atas satu musuh, memberikan 180% ATK + $(skillLevel×4×24)$ kerosakan fizikal. Meningkatkan 15% ATK dan 10% serapan darah (maks 5 lapisan), selama 2 pusingan. 80% peluang menyebabkan Terkejut selama 2 pusingan.',
		zawakeEffectDesc_vn = 'Minato thi triển Lôi Ảnh Trảm, tấn công 1 mục tiêu, gây 180% công vật lý + $(skillLevel×4×24)$ sát thương. Tăng 15% công và 10% hút máu bản thân (tối đa 5 cộng dồn), kéo dài 2 lượt. Có 80% gây Tê Liệt trong 2 lượt.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '80% chance to inflict 【Electrified】 for 2 turns',
		zawakeSimpleDesc_en = '80% chance to inflict 【Electrified】 for 2 turns',
		zawakeSimpleDesc_th = 'มีโอกาส 80% ที่จะทำให้เป้าหมาย【ช็อต】เป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = '80% peluang menyebabkan efek 【Tersetrum】 selama 2 giliran',
		zawakeSimpleDesc_ph = '80% tsansa na magdulot ng 【Kuryente】 sa loob ng 2 turn',
		zawakeSimpleDesc_ma = '80% peluang mengenakan 【Renjatan】 selama 2 pusingan',
		zawakeSimpleDesc_vn = 'Có 80% xác suất gây 【Cảm điện】 trong 2 lượt',
		upLvDesc = 'Fixed damage +96',
		upLvDesc_en = 'Fixed damage +96',
