	[41612] = {
		id = 41612,
		skillName_vn = 'Lôi Ảnh Nhị Đoạn',
		skillName_en = 'Thunder Step II',
		skillName_th = 'ขั้นสองเทพสายฟ้า',
		skillName_in = 'Langkah Kedua Dewa Petir',
		skillName_ph = 'Ikalawang Hakbang ng Kidlat',
		skillName_ma = 'Langkah Kedua Petir Terbang',
		skillName = 'Thunder Step II',
		describe_vn = 'Minato lao vào hàng địch như tia chớp, gây 240% công vật lý + sát thương thêm, 100% gây Tê liệt mục tiêu 2 lượt, sau đó biến mất để lại Ảo ảnh phân thân đến lượt kế tiếp, khi phân thân biến mất Minato quay lại và tăng 30% né tránh 1 lượt, nếu phân thân bị tiêu diệt sớm sẽ tăng thêm 20% né tránh.',
		describe_en = 'Minato dashes at the enemy column like lightning, dealing 240% physical ATK + bonus damage, 100% chance to Paralyze for 2 turns, then vanishes leaving a Shadow Clone until next turn. When the clone disappears, Minato returns, gaining 30% Dodge for 1 turn; if the clone is killed early, gain extra 20% Dodge.',
		describe_th = 'มินาโตะพุ่งใส่ศัตรูแถวหน้าอย่างสายฟ้า สร้างความเสียหายกายภาพ 240% + ดาเมจพิเศษ มีโอกาส 100% ทำให้เป็นอัมพาต 2 เทิร์น จากนั้นหายตัว ทิ้งร่างแยกไว้จนถึงรอบถัดไป เมื่อตัวแยกหาย มินาโตะกลับมาและได้รับหลบหลีก 30% 1 เทิร์น ถ้าร่างแยกถูกฆ่าก่อน จะได้รับหลบหลีกเพิ่มอีก 20%',
		describe_in = 'Minato menerjang barisan musuh secepat kilat, memberikan 240% serangan fisik + bonus damage, 100% peluang untuk Melumpuhkan selama 2 giliran, lalu menghilang dan meninggalkan Klon Bayangan hingga giliran berikutnya, saat klon menghilang Minato kembali dan mendapatkan 30% Dodge selama 1 giliran, jika klon terbunuh lebih awal dapat tambahan 20% Dodge.',
		describe_ph = 'Sumugod si Minato sa hanay ng kalaban na parang kidlat, nagdudulot ng 240% physical ATK + dagdag na damage, 100% tsansa na ma-Paralyze sa loob ng 2 turn, pagkatapos ay nawawala at nag-iiwan ng Shadow Clone hanggang sa susunod na turn, kapag nawala ang clone ay babalik si Minato at makakakuha ng 30% Dodge sa loob ng 1 turn, kung maagang napatay ang clone dagdag pa ng 20% Dodge.',
		describe_ma = 'Minato meluru ke barisan musuh seperti kilat, menyebabkan 240% ATK fizikal + kerosakan tambahan, 100% peluang Lumpuh selama 2 pusingan, kemudian lenyap dan meninggalkan Klon Bayangan sehingga giliran seterusnya, apabila klon hilang Minato kembali dan mendapat 30% Elak selama 1 pusingan, jika klon dibunuh awal akan dapat tambahan 20% Elak.',
		describe = 'Minato dashes at the enemy column like lightning, dealing 240% physical ATK + bonus damage, 100% chance to Paralyze for 2 turns, then vanishes leaving a Shadow Clone until next turn. When the clone disappears, Minato returns, gaining 30% Dodge for 1 turn; if the clone is killed early, gain extra 20% Dodge.',
		zawakeEffect = __data_t__zawakeEffect[41612],
		-- {79002}
		zawakeEffectDesc = 'Minato dashes with thunder speed, striking enemy row with 240% ATK + $(skillLevel×4×60)$ physical damage. 100% chance to Paralyze for 2 turns. Then vanishes, leaving a Shadow Clone until his next action. Upon clone disappearing, Minato returns and gains 50% Dodge for 1 turn. If clone is killed early, gain extra 50% Dodge.',
		zawakeEffectDesc_en = 'Minato dashes with thunder speed, striking enemy row with 240% ATK + $(skillLevel×4×60)$ physical damage. 100% chance to Paralyze for 2 turns. Then vanishes, leaving a Shadow Clone until his next action. Upon clone disappearing, Minato returns and gains 50% Dodge for 1 turn. If clone is killed early, gain extra 50% Dodge.',
		zawakeEffectDesc_th = 'มินาโตะพุ่งโจมตีศัตรูแถวหน้า สร้างความเสียหายกายภาพ 240% ATK + $(skillLevel×4×60)$ มีโอกาส อัมพาต 100% เป็นเวลา 2 เทิร์น จากนั้นหายตัวและทิ้ง ร่างเงา ไว้จนถึงการกระทำถัดไป เมื่อร่างเงาหาย มินาโตะจะกลับพร้อมรับ หลบหลีก 50% 1 เทิร์น หากร่างเงาถูกฆ่าก่อน จะได้รับหลบหลีกเพิ่มอีก 50%',
		zawakeEffectDesc_in = 'Minato menyergap baris musuh dengan kecepatan kilat, memberikan 240% ATK + $(skillLevel×4×60)$ kerusakan fisik. 100% peluang untuk Melumpuhkan selama 2 giliran. Kemudian menghilang dan meninggalkan Bayangan Clone hingga giliran berikutnya. Saat clone hilang, Minato kembali dan mendapat 50% Dodge selama 1 giliran. Jika clone mati lebih awal, Dodge bertambah 50%.',
		zawakeEffectDesc_ph = 'Si Minato ay sumugod sa hanay ng kalaban gamit ang bilis ng kidlat, dealing 240% ATK + $(skillLevel×4×60)$ physical damage. 100% chance na Paralyze sa loob ng 2 turn. Pagkatapos ay nawawala at nag-iiwan ng isang Shadow Clone hanggang sa susunod niyang turn. Kapag clone nawala, Minato babalik at makakakuha ng 50% Dodge sa loob ng 1 turn. Kung napatay ang clone sớm, dagdag pa 50% Dodge.',
		zawakeEffectDesc_ma = 'Minato menyerang barisan musuh dengan kelajuan kilat, menyebabkan 240% ATK + $(skillLevel×4×60)$ kerosakan fizikal. 100% peluang untuk Lumpuh selama 2 pusingan. Kemudian hilang dan tinggalkan Bayangan Ilusi hingga giliran seterusnya. Bila bayangan hilang, Minato kembali dan dapat 50% Elak Serangan selama 1 pusingan. Jika bayangan mati awal, elakan naik 50% lagi.',
		zawakeEffectDesc_vn = 'Minato lao tới tấn công hàng ngang kẻ địch, gây 240% công vật lý + $(skillLevel×4×60)$ sát thương. 100% gây Tê liệt 2 lượt. Sau đó biến mất, để lại một Phân thân ảo ảnh đến lượt kế tiếp. Khi phân thân biến mất, Minato quay lại vị trí và tăng 50% né tránh trong 1 lượt. Nếu phân thân bị giết sớm, được thêm 50% né nữa.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Increases Dodge by 30% for 1 turn. If the clone returns early after being defeated, gain an additional 20% Dodge\n#F20#\n#F40##C0x5c9970#→Increases Dodge by 50% for 1 turn. If the clone returns early after being defeated, gain an additional 50% Dodge',
		zawakeSimpleDesc_en = 'Increases Dodge by 30% for 1 turn. If the clone returns early after being defeated, gain an additional 20% Dodge\n#F20#\n#F40##C0x5c9970#→Increases Dodge by 50% for 1 turn. If the clone returns early after being defeated, gain an additional 50% Dodge',
		zawakeSimpleDesc_th = 'เพิ่มโอกาสหลบหลีก 30% เป็นเวลา 1 เทิร์น หากร่างแยกถูกสังหารและกลับมาก่อน จะได้หลบหลีกเพิ่มอีก 20%\n#F20#\n#F40##C0x5c9970#→เพิ่มโอกาสหลบหลีก 50% เป็นเวลา 1 เทิร์น หากร่างแยกถูกสังหารและกลับมาก่อน จะได้หลบหลีกเพิ่มอีก 50%',
		zawakeSimpleDesc_in = 'Meningkatkan Dodge 30% selama 1 giliran. Jika clone dikalahkan lebih awal dan kembali, mendapatkan tambahan Dodge 20%\n#F20#\n#F40##C0x5c9970#→Meningkatkan Dodge 50% selama 1 giliran. Jika clone dikalahkan lebih awal dan kembali, mendapatkan tambahan Dodge 50%',
		zawakeSimpleDesc_ph = 'Tumaas ng 30% ang Dodge sa loob ng 1 turn. Kapag ang shadow clone ay napatay at bumalik nang sớm, makakakuha ng dagdag na 20% Dodge\n#F20#\n#F40##C0x5c9970#→Tumaas ng 50% ang Dodge sa loob ng 1 turn. Kapag ang shadow clone ay napatay at bumalik nang sớm, makakakuha ng dagdag na 50% Dodge',
		zawakeSimpleDesc_ma = 'Meningkatkan Elak sebanyak 30% selama 1 pusingan. Jika bayangan dibunuh awal dan kembali, dapat tambahan 20% Elak\n#F20#\n#F40##C0x5c9970#→Meningkatkan Elak sebanyak 50% selama 1 pusingan. Jika bayangan dibunuh awal dan kembali, dapat tambahan 50% Elak',
		zawakeSimpleDesc_vn = 'Tăng 30% Né tránh trong 1 lượt, nếu phân thân bị tiêu diệt sớm và quay lại thì nhận thêm 20% Né tránh\n#F20#\n#F40##C0x5c9970#→Tăng 50% Né tránh trong 1 lượt, nếu phân thân bị tiêu diệt sớm và quay lại thì nhận thêm 50% Né tránh',
		upLvDesc = 'Fixed damage +240',
