	[41613] = {
		id = 41613,
		skillName_vn = 'Lôi Ảnh Rasengan',
		skillName_en = 'Flying Thunder Rasengan',
		skillName_th = 'ราซังกันสายฟ้าแลบ',
		skillName_in = 'Rasengan Petir Terbang',
		skillName_ph = 'Flying Thunder Rasengan',
		skillName_ma = 'Rasengan Halilintar Terbang',
		skillName = 'Flying Thunder Rasengan',
		describe_vn = 'Minato tung hàng loạt phi tiêu bằng hai tay, sau đó chém 5 lần vào mục tiêu ngẫu nhiên với tốc độ sấm sét xé gió. Mỗi đòn gây #C0xE69900#350% công vật lý#C0x5B545B#+$(skillLevel460)$ sát thương #C0xF13B54#vật lý#C0x5B545B#. Nếu đánh trúng 3 tướng khác nhau, sẽ kích hoạt hiệu ứng 【Trường Tĩnh Điện】 lên toàn bộ kẻ địch, kéo dài 1–2 lượt lớn\n#F10#\n#F40##L10#Trường Tĩnh Điện：#L0#Trong thời gian này, mục tiêu bị 【Cảm Điện】 và có 50% xác suất không nhận được buff. Sau khi tấn công, có 80% khả năng bị 【Tê liệt】 1 lượt. Khi đồng minh hệ Lôi tấn công mục tiêu trong Trường Tĩnh Điện, 25% sát thương kỹ năng sẽ truyền sang tối đa 2 mục tiêu bị 【Từ Hóa】.',
		describe_en = 'Minato scatters countless kunai with both hands, then slashes 5 times at random enemy targets with lightning-fast speed that cuts through gusts. Each hit deals #C0xE69900#350% Physical ATK#C0x5B545B#+$(skillLevel460)$ of #C0xF13B54#physical damage#C0x5B545B#. If 3 different heroes are hit, triggers the 【Static Field】 effect on all enemies for 1–2 full rounds\n#F10#\n#F40##L10#Static Field:#L0#During this time, targets are 【Electrified】 and have a 50% chance to fail to receive buffs. After attacking, there\'s an 80% chance to be 【Paralyzed】 for 1 turn. When Thunder-type allies attack targets in Static Field, 25% of skill damage is conducted to up to two 【Magnetized】 targets.',
		describe_th = 'มินาโตะโปรยคุไนจำนวนนับไม่ถ้วนด้วยมือทั้งสอง จากนั้นฟันศัตรูแบบสุ่ม 5 ครั้งด้วยความเร็วสายฟ้าที่เฉือนลมแรงได้ แต่ละครั้งสร้างความเสียหาย #C0xE69900#350% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel460)$ ของ #C0xF13B54#ดาเมจกายภาพ#C0x5B545B# หากโดนฮีโร่ 3 ตัวที่แตกต่างกัน จะเปิดใช้งานเอฟเฟกต์【สนามไฟฟ้าสถิต】ใส่ศัตรูทั้งหมด 1–2 เทิร์นใหญ่\n#F10#\n#F40##L10#สนามไฟฟ้าสถิต：#L0#ช่วงนี้ศัตรูจะ【ช็อต】และมีโอกาส 50% ที่จะไม่ได้รับบัฟ หลังจากโจมตีมีโอกาส 80% ที่จะ【อัมพาต】 1 เทิร์น ฮีโร่สายสายฟ้าจะถ่ายโอน 25% ดาเมจสกิลไปยังศัตรูที่【ติดแม่เหล็ก】ได้สูงสุด 2 ตัว',
		describe_in = 'Minato melempar banyak kunai dengan kedua tangan, lalu menebas 5 kali ke target musuh acak dengan kecepatan kilat yang memotong angin. Setiap serangan memberikan #C0xE69900#350% ATK fisik#C0x5B545B#+$(skillLevel460)$ dari #C0xF13B54#damage fisik#C0x5B545B#. Jika mengenai 3 hero berbeda, efek 【Medan Statis】 akan diaktifkan ke semua musuh selama 1–2 ronde penuh\n#F10#\n#F40##L10#Medan Statis：#L0#Selama efek ini, target akan 【Teraliri Listrik】 dan memiliki peluang 50% gagal mendapatkan buff. Setelah menyerang, ada 80% peluang terkena 【Paralisis】 selama 1 giliran. Hero bertipe Petir akan menyalurkan 25% damage skill ke maksimal dua target 【Termagnetisasi】.',
		describe_ph = 'Nagpakawala si Minato ng napakaraming kunai gamit ang dalawang kamay, saka umatake ng 5 beses sa random na kalaban gamit ang bilis ng kidlat na kayang hatiin ang hangin. Bawat tama ay nagbibigay ng #C0xE69900#350% physical ATK#C0x5B545B#+$(skillLevel460)$ na #C0xF13B54#physical damage#C0x5B545B#. Kapag 3 magkaibang hero ang tinamaan, a-activate ang 【Static Field】 sa lahat ng kalaban sa loob ng 1–2 full rounds\n#F10#\n#F40##L10#Static Field：#L0#Sa panahon nito, ang mga target ay 【Na-kuryente】 at may 50% chance na hindi makatanggap ng buff. Pagkatapos umatake, may 80% chance silang ma-【Paralyze】 ng 1 turn. Ang mga Thunder-type hero ay magta-transfer ng 25% skill damage sa hanggang 2 【Na-magnetize】 na kalaban.',
		describe_ma = 'Minato melontar banyak kunai dengan kedua-dua tangan, kemudian menebas 5 kali pada sasaran rawak dengan kelajuan kilat yang memotong angin. Setiap serangan memberikan #C0xE69900#350% ATK fizikal#C0x5B545B#+$(skillLevel460)$ #C0xF13B54#kerosakan fizikal#C0x5B545B#. Jika mengenai 3 hero yang berbeza, ia mencetuskan kesan 【Medan Statik】 kepada semua musuh selama 1–2 pusingan penuh\n#F10#\n#F40##L10#Medan Statik：#L0#Sepanjang tempoh ini, sasaran akan 【Terkena Kejutan】 dan mempunyai 50% peluang gagal menerima buff. Selepas menyerang, terdapat 80% peluang untuk 【Lumpuh】 selama 1 pusingan. Hero elemen Kilat akan memindahkan 25% kerosakan kemahiran kepada maksimum dua sasaran yang 【Dimagnetkan】.',
		describe = 'Minato scatters countless kunai with both hands, then slashes 5 times at random enemy targets with lightning-fast speed that cuts through gusts. Each hit deals #C0xE69900#350% Physical ATK#C0x5B545B#+$(skillLevel460)$ of #C0xF13B54#physical damage#C0x5B545B#. If 3 different heroes are hit, triggers the 【Static Field】 effect on all enemies for 1–2 full rounds\n#F10#\n#F40##L10#Static Field:#L0#During this time, targets are 【Electrified】 and have a 50% chance to fail to receive buffs. After attacking, there\'s an 80% chance to be 【Paralyzed】 for 1 turn. When Thunder-type allies attack targets in Static Field, 25% of skill damage is conducted to up to two 【Magnetized】 targets.',
		simDesc_vn = 'Minato tụ điện hàng vạn vôn vào hai tay, tung ra 5 cú đấm sấm sét tấn công mục tiêu ngẫu nhiên với tốc độ xé gió. Đánh trúng nhiều mục tiêu khác nhau sẽ kích hoạt hiệu ứng Trường Tĩnh Điện.',
		simDesc_en = 'Minato gathers tens of thousands of volts of electricity in both hands, then punches 5 times at random enemy targets with lightning speed that cuts through the wind. Hitting multiple different targets will trigger the Static Field effect.',
		simDesc_th = 'มินาโตะรวมกระแสไฟฟ้าหลายหมื่นโวลต์ไว้ในมือทั้งสอง แล้วชกใส่เป้าหมายศัตรูแบบสุ่ม 5 ครั้งด้วยความเร็วสายฟ้าที่เฉือนลม การโจมตีหลายเป้าหมายที่แตกต่างกันจะกระตุ้นเอฟเฟกต์สนามไฟฟ้าสถิต',
		simDesc_in = 'Minato mengumpulkan puluhan ribu volt listrik di kedua tangan, lalu meninju 5 kali ke target musuh acak dengan kecepatan kilat yang menembus angin. Menyerang beberapa target berbeda akan memicu efek Medan Statis.',
		simDesc_ph = 'Nagtipon si Minato ng libu-libong volts ng kuryente sa dalawang kamay, at sunod-sunod na umatake ng 5 suntok sa random na kalaban gamit ang bilis ng kidlat. Kapag tumama sa maraming target na magkaiba, mae-activate ang Static Field effect.',
		simDesc_ma = 'Minato mengumpulkan puluhan ribu volt arus elektrik di kedua-dua tangan, kemudian melancarkan 5 tumbukan sepantas kilat ke arah sasaran rawak musuh. Memukul beberapa sasaran berbeza akan mencetuskan kesan Medan Statik.',
		simDesc = 'Minato gathers tens of thousands of volts of electricity in both hands, then punches 5 times at random enemy targets with lightning speed that cuts through the wind. Hitting multiple different targets will trigger the Static Field effect.',
		starEffect = __data_t__starEffect[41613],
		-- {11}
		starEffectDesc_vn = 'Nếu có Phân thân ảo ảnh, hợp thể thành Chế độ Hiền Nhân (2 lượt): nhận 60% chỉ số phân thân, +50% né.\nMỗi đòn đánh thường trở thành Phi Lôi La Hoàn (miễn phí, hồi nộ, tốc độ hồi nộ -50%), đánh 2 lần, chắc chắn trúng.',
		starEffectDesc = 'If a Shadow Clone exists, merge into Sage Mode (2 turns): gains 60% clone stats, +50% Dodge.\nEach attack becomes Flying Thunder Rasengan (free, restores Rage, but -50% Rage gain), hits twice, always lands.',
		starEffectDesc_en = 'If a Shadow Clone exists, merge into Sage Mode (2 turns): gains 60% clone stats, +50% Dodge.\nEach attack becomes Flying Thunder Rasengan (free, restores Rage, but -50% Rage gain), hits twice, always lands.',
		starEffectDesc_th = 'หากมี ร่างเงา จะรวมร่างเข้าสู่ โหมดเซียน (2 เทิร์น): รับ 60% ค่าสถานะ, +50% หลบ\nทุกการโจมตีเป็น ราสเซ็นกันวายุบิน (ฟรี, ฟื้น Rage, ลดฟื้น 50%), โจมตี 2 ครั้ง, โดนแน่นอน',
		starEffectDesc_in = 'Jika ada Clone, masuk Mode Sage (2 giliran): ambil 60% stats clone, +50% dodge.\nSetiap serangan jadi Flying Thunder Rasengan (gratis, pulih Rage, -50% Regen), serang 2x, pasti kena.',
		starEffectDesc_ph = 'May Clone? Pumasok sa Sage Mode (2 turn): +60% clone stats, +50% iwas.\nLahat ng atake ay Flying Thunder Rasengan (libre, regain Rage, pero -50% gain), 2 hit, sigurado tama.',
		starEffectDesc_ma = 'Jika ada Bayangan Ilusi, masuk Mod Sage (2 pusingan): warisi 60% status, +50% elak\nSetiap serangan jadi Rasengan Kilat Terbang (percuma, pulih Rage, -50% pulih), serang 2x, pasti kena.',
		zawakeEffect = __data_t__zawakeEffect[41613],
		-- {79003, 1}
		zawakeEffectDesc = 'If a Shadow Clone exists after casting, Minato merges with it to enter Sage Mode for 2 turns.\nSage Mode: Gains 60% clone stats, +50% Dodge, each normal attack becomes Flying Thunder Rasengan (cost-free, restores rage, but rage recovery -50%).Each attack hits one more time, always lands, and all clones join the strike.Upon entering, all Thunder-type allies gain +30% DMG Bonus for 1 turn.',
		zawakeEffectDesc_en = 'If a Shadow Clone exists after casting, Minato merges with it to enter Sage Mode for 2 turns.\nSage Mode: Gains 60% clone stats, +50% Dodge, each normal attack becomes Flying Thunder Rasengan (cost-free, restores rage, but rage recovery -50%).Each attack hits one more time, always lands, and all clones join the strike.Upon entering, all Thunder-type allies gain +30% DMG Bonus for 1 turn.',
		zawakeEffectDesc_th = 'หากมี ร่างเงา หลังใช้สกิล มินาโตะจะรวมร่างเข้าสู่ โหมดเซียน 2 เทิร์น\nโหมดเซียน: รับ 60% ค่าสถานะจากร่างเงา, +50% หลบหลีก, ทุกการโจมตีปกติกลายเป็น ราสเซ็นกันเทพวายุ (ไม่เสียโกรธ, ฟื้นโกรธ, แต่ลดการฟื้น 50%)โจมตีเพิ่ม 1 ครั้ง, โดนแน่นอน, และร่างเงาร่วมโจมตีด้วยเมื่อเข้าสู่โหมดเซียน, ฮีโร่สายสายฟ้าทั้งทีมเพิ่มดาเมจ +30% 1 เทิร์น',
		zawakeEffectDesc_in = 'Jika ada Bayangan Clone, Minato bergabung untuk masuk Mode Sage selama 2 giliran.\nMode Sage: Menyerap 60% atribut clone, +50% Dodge, semua serangan biasa berubah jadi Flying Thunder Rasengan (gratis, pulihkan Rage, tapi regen Rage -50%)Serangan +1 hit, selalu kena, semua clone ikut menyerang.Saat masuk Mode Sage, semua hero elemen Petir +30% bonus damage selama 1 giliran.',
		zawakeEffectDesc_ph = 'Kung may Shadow Clone, magsasanib si Minato at papasok sa Sage Mode ng 2 turn\nSage Mode: Kukuha ng 60% ng stats ng clone, +50% Dodge, bawat normal attack ay Flying Thunder Rasengan (libre, nagre-regain Rage, pero -50% sa Rage gain)Attack +1 hit, laging tatama, kasama lahat ng clones sa pag-atake.Pag-activate ng Sage Mode, lahat ng Thunder-type hero +30% damage boost sa 1 turn',
		zawakeEffectDesc_ma = 'Jika Bayangan Ilusi wujud, Minato bergabung dengannya lalu aktifkan Mod Sage 2 pusingan\nMod Sage: Warisi 60% status klon, +50% Elakan, setiap serangan biasa jadi Rasengan Kilat Terbang (tanpa kos, pulih Rage, tetapi pemulihan Rage -50%).Tambah 1 serangan, pasti kena, semua klon bantu serang.Ketika masuk Mod Sage, semua hero Elemen Petir dapat +30% kerosakan selama 1 pusingan',
		zawakeEffectDesc_vn = 'Nếu tồn tại Phân thân ảo ảnh, Minato hợp thể và vào Chế Độ Hiền Nhân trong 2 lượt.\nChế Độ Hiền Nhân: Nhận 60% chỉ số phân thân, +50% né tránh, đòn đánh thường chuyển thành Phi Lôi La Hoàn (miễn phí, hồi nộ, nhưng tốc độ hồi nộ -50%).Mỗi đòn đánh thêm 1 lần và chắc chắn trúng, đồng thời phân thân cùng tấn công.Khi vào chế độ, toàn bộ tướng hệ Lôi được +30% sát thương trong 1 lượt.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'When entering Sage Mode, all Thunder-type heroes gain 30% bonus damage for 1 turn; during Sage Mode, casting Flying Thunder Rasengan summons all shadow clones to join the attack',
		zawakeSimpleDesc_en = 'When entering Sage Mode, all Thunder-type heroes gain 30% bonus damage for 1 turn; during Sage Mode, casting Flying Thunder Rasengan summons all shadow clones to join the attack',
		zawakeSimpleDesc_th = 'เมื่อเข้าสู่โหมดเซียน ฮีโร่สายสายฟ้าทั้งหมดได้รับโบนัสความเสียหาย 30% เป็นเวลา 1 เทิร์น; ในโหมดเซียน การใช้ท่า ฟุ้งเรเซ็งกัน จะเรียกเงาจำแลงทั้งหมดเข้าร่วมโจมตี',
		zawakeSimpleDesc_in = 'Saat memasuki Mode Sage, semua hero elemen Petir mendapatkan 30% bonus damage selama 1 giliran; dalam Mode Sage, saat menggunakan Rasengan Petir Terbang, semua bayangan ikut menyerang bersama',
		zawakeSimpleDesc_ph = 'Sa pagpasok sa Sage Mode, lahat ng Thunder-type na bayani ay makakakuha ng 30% dagdag na damage sa loob ng 1 turn; sa ilalim ng Sage Mode, kapag nag-cast ng Flying Thunder Rasengan, lahat ng shadow clone ay sasama sa pag-atake',
		zawakeSimpleDesc_ma = 'Apabila memasuki Mod Bijak, semua wira elemen Petir menerima 30% tambahan kerosakan selama 1 pusingan; dalam Mod Bijak, apabila melepaskan Rasengan Petir Terbang akan memanggil semua bayangan untuk menyerang bersama',
		zawakeSimpleDesc_vn = 'Khi vào trạng thái Tiên Nhân, tất cả anh hùng hệ Lôi tăng 30% sát thương trong 1 lượt; trong trạng thái Tiên Nhân, khi thi triển Phi Lôi La Toàn Hoàn sẽ triệu hồi tất cả phân thân phối hợp tấn công',
		upLvDesc = 'Fixed damage +240',
		upLvDesc_en = 'Fixed damage +240',
		upLvDesc_th = 'ดาเมจคงที่ +240',
