	[41616] = {
		id = 41616,
		skillName_vn = 'Phân Thân Ảo Ảnh',
		skillName_en = 'Shadow Clone',
		skillName_th = 'ร่างแยกมายา',
		skillName_in = 'Bayangan Klon',
		skillName_ph = 'Anino Kopya',
		skillName_ma = 'Bayangan Pendua',
		skillName = 'Shadow Clone',
		describe_vn = 'Nhanh Như Gió:#L0#Chuyển động như sấm chớp, thân pháp như thần, tăng 50% né tránh ban đầu.\n#F10#\n#F40##L10#Phân Thân Ảo Ảnh:#L0#Trước mỗi lượt lớn, tạo một [Phân Thân Ảo Ảnh] đi theo bản thể. Phân thân kế thừa 50% thuộc tính của Minato, miễn nhiễm mọi hiệu ứng. Khi kẻ địch tấn công Minato, có 50% xác suất (mỗi kẻ địch thêm 5%) đánh trúng phân thân và bị [Tê Liệt] 2 lượt. Minato không chịu sát thương hay hiệu ứng từ đòn đánh đó. Khi Minato tấn công, phân thân hỗ trợ gây 250% sát thương vật lý theo chỉ số bản thân.\n#F10#\n#F40##L10#Ra Tay Trước:#L0#Khi có phân thân theo sau, nếu bị tấn công, Minato sẽ tấn công thường trước, chuyển một hiệu ứng có lợi của kẻ địch thành [Tê Liệt] 2 lượt và tăng 20% tốc độ trong 1 lượt.\n#F10#\n#F40##L10#Ninja Phong Lôi:#L0#Tấn công mục tiêu bị [Tê Liệt] sẽ thêm [Từ Hóa] 1 lượt (Từ Hóa: Hút 2 hiệu ứng có lợi khi kích hoạt; tái kích khi tấn công hệ Lôi; kết thúc có 50% xác suất gây [Tê Liệt] 1 lượt).\nTăng Cường Lôi: Đồng minh hệ Lôi gây thêm sát thương #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# lên hệ Khắc (Vong Linh, Thủy), đòn đánh thêm [Tê Liệt] 2 lượt.\nGiảm Sát Thương: Đồng minh hệ Lôi giảm 20% sát thương thêm và sát thương bị động; kẻ địch [Tê Liệt] gây giảm 40% sát thương lên hệ Lôi.',
		describe_en = 'Swift as the Wind:#L0#Moves like thunder, godlike agility, initial dodge rate +50%.\n#F10#\n#F40##L10#Shadow Clone:#L0#At the start of each round, creates a [Shadow Clone] that follows him. The clone inherits 50% of Minato’s stats, is immune to all effects. When enemies attack Minato, there\'s a 50% chance (plus 5% per enemy) to hit the clone instead and inflict [Electrified] for 2 turns. Minato takes no damage or effects from that attack. When Minato attacks, the clone assists by hitting the same target range, dealing 250% of its own physical attack.\n#F10#\n#F40##L10#Preemptive Strike:#L0#When a clone is present, Minato preemptively normal attacks any enemy who tries to hit him, converts one of their buffs into [Electrified] for 2 turns, and increases his own Speed by 20% for 1 turn.\n#F10#\n#F40##L10#Wind-Thunder Ninja:#L0#When attacking [Electrified] targets, Minato also applies [Magnetized] for 1 turn. (Magnetized: Removes 2 buffs on application; when attacking Thunder-type enemies, reactivates. At the end, 50% chance to paralyze target 1 turn.)\nThunder Amplify: Allies of Thunder-type deal +[color=#5c9970]$(20+skillLevel*0.1-0.1)$%[color=#5B545B] more damage to [Undead]/[Aqua] types, and +[Electrified] 2 turns.\nThunder Weaken: Thunder allies receive -20% extra/passive damage; [Electrified] enemies deal -40% damage to Thunder allies.',
		describe_th = 'รวดเร็วดั่งสายลม:#L0#เคลื่อนไหวรวดเร็วราวสายฟ้า อัตราหลบหลีกเริ่มต้น +50%\n#F10#\n#F40##L10#ร่างเงา:#L0#ก่อนเริ่มแต่ละรอบหลัก สร้าง [ร่างเงา] ที่ติดตามตัวหลัก ร่างเงาสืบทอดค่าสถานะ 50% ของมินาโตะ และไม่ได้รับผลกระทบจากสถานะใดๆ เมื่อศัตรูโจมตีมินาโตะ มีโอกาส 50% (เพิ่มอีก 5% ต่อศัตรู 1 ตัว) โจมตีโดนร่างเงาแทน และติด [ไฟฟ้าช็อต] 2 เทิร์น มินาโตะไม่รับความเสียหายหรือผลกระทบใดๆ จากการโจมนั้น เมื่อมินาโตะโจมตี ร่างเงาจะช่วยโจมตีเป้าหมายเดียวกัน สร้างความเสียหายกายภาพ 250%\n#F10#\n#F40##L10#โจมตีก่อน:#L0#ขณะมีร่างเงา มินาโตะจะโจมตีปกติก่อนศัตรูที่กำลังจะโจมตีเขา เปลี่ยนบัฟหนึ่งอย่างของศัตรูเป็น [ไฟฟ้าช็อต] 2 เทิร์น และเพิ่มความเร็วตัวเอง 20% เป็นเวลา 1 เทิร์น\n#F10#\n#F40##L10#นินจาสายลมสายฟ้า:#L0#เมื่อโจมตีศัตรูที่ติด [ไฟฟ้าช็อต] จะเพิ่มสถานะ [แม่เหล็ก] 1 เทิร์น (ดูด 2 บัฟตอนใช้, กระตุ้นซ้ำเมื่อโจมตีสายฟ้า, จบแล้วมีโอกาส 50% ทำให้เป็นอัมพาต 1 เทิร์น)\nขยายพลังสายฟ้า: เพื่อนร่วมทีมสายฟ้าโจมตีศัตรูธาตุแพ้ (อันเดด, น้ำ) จะเพิ่ม [ไฟฟ้าช็อต] 2 เทิร์น และเพิ่มดาเมจ #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#\nลดดาเมจสายฟ้า: พันธมิตรสายฟ้าได้รับดาเมจเสริมและดาเมจติดตัวลดลง 20% ศัตรูที่ติด [ไฟฟ้าช็อต] สร้างดาเมจใส่พันธมิตรสายฟ้าน้อยลง 40%',
		describe_in = 'Secepat Angin:#L0#Bergerak laksana kilat, kecepatan luar biasa, +50% dodge di awal.\n#F10#\n#F40##L10#Bayangan Ilusi:#L0#Sebelum tiap ronde utama, menciptakan [Bayangan Ilusi] yang mengikuti dirinya. Bayangan ini mewarisi 50% atribut Minato dan kebal terhadap semua efek. Saat musuh menyerang Minato, 50% kemungkinan (ditambah 5% untuk tiap musuh) serangan mengarah ke bayangan dan menyebabkan [Tersetrum] selama 2 giliran. Minato tidak terkena damage/efek dari serangan tersebut. Saat menyerang, bayangan juga menyerang target yang sama dengan 250% ATK fisiknya.\n#F10#\n#F40##L10#Serangan Awal:#L0#Saat bayangan ada, Minato menyerang dulu sebelum diserang, mengubah satu buff musuh menjadi [Tersetrum] selama 2 giliran, dan meningkatkan kecepatan sendiri 20% selama 1 giliran.\n#F10#\n#F40##L10#Ninja Angin-Petir:#L0#Saat menyerang musuh yang terkena [Tersetrum], menambahkan [Terganggu Magnetik] 1 giliran (menyerap 2 buff, aktif ulang saat serang tipe Petir, 50% peluang lumpuh saat selesai).\nPenguatan Petir: Rekan tim tipe Petir memberikan +[Tersetrum] 2 giliran pada musuh tipe counter (Undead/Air), dan +#C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# damage.\nPelemahan Petir: Rekan tim tipe Petir menerima 20% lebih sedikit damage tambahan/pasif. Musuh [Tersetrum] memberikan -40% damage ke tim Petir.',
		describe_ph = 'Kasingbilis ng Hangin:#L0#Kumikilos parang kidlat, pambihirang liksi, +50% dodge sa simula.\n#F10#\n#F40##L10#Shadow Clone:#L0#Bago magsimula ang bawat pangunahing turn, lumilikha ng [Shadow Clone] na sumusunod. Minana nito ang 50% ng stats ni Minato, immune sa lahat ng effect. Kapag inatake si Minato, 50% chance (dagdag 5% kada kalaban) ang atake ay tatama sa clone at magdudulot ng [Kuryente] 2 turn. Hindi tatamaan si Minato. Kapag umatake si Minato, sabay rin ang clone, na may 250% physical ATK.\n#F10#\n#F40##L10#Unang Galaw:#L0#Kapag may clone, umatake si Minato bago siya atakihin. Isa sa buffs ng kalaban ay nagiging [Kuryente] 2 turn at tumataas ang Speed niya ng 20% sa loob ng 1 turn.\n#F10#\n#F40##L10#Ninja ng Hangin at Kidlat:#L0#Pag umatake sa [Kuryente] na target, nagdadagdag ng [Magnetized] 1 turn (sumisipsip ng 2 buff; aktibo muli pag umatake ng thunder; may 50% chance paralyze kapag natapos).\nThunder Buff: Mga kakamping Thunder-type nagdadagdag [Kuryente] 2 turn sa kalaban na mahina (Undead/Water) at dagdag damage #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#\nThunder Debuff: Thunder allies tumatanggap ng -20% dagdag/pasyenteng damage, at -40% damage mula sa [Kuryente] na kalaban.',
		describe_ma = 'Sepantas Angin:#L0#Bergerak sepantas kilat, gerakan luar biasa, kadar elak awal +50%\n#F10#\n#F40##L10#Bayangan Ilusi:#L0#Sebelum setiap pusingan utama, cipta [Bayangan Ilusi] yang mengikuti dirinya. Bayangan mewarisi 50% atribut Minato dan kebal terhadap sebarang kesan. Apabila musuh menyerang Minato, 50% kebarangkalian (tambah 5% setiap musuh) untuk menyerang bayangan dan menyebabkan [Tersetrum] 2 pusingan. Minato tidak terkena kerosakan atau kesan. Bila menyerang, bayangan bantu serang sasaran yang sama, beri 250% serangan fizikal dirinya.\n#F10#\n#F40##L10#Serangan Awal:#L0#Jika bayangan ada, Minato akan menyerang musuh terlebih dahulu, menukar satu buff musuh kepada [Tersetrum] 2 pusingan dan menambah 20% kelajuan selama 1 pusingan.\n#F10#\n#F40##L10#Ninja Angin-Petir:#L0#Menyerang sasaran [Tersetrum] akan tambah [Dimagnetkan] 1 pusingan (serap 2 buff, aktif semula bila lawan petir, tamat ada 50% kebarangkalian lumpuh 1 pusingan).\nPenguat Petir: Sekutu petir beri [Tersetrum] 2 pusingan pada musuh jenis lawan (Undead/Air) dan tingkatkan kerosakan sebanyak #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#\nPelemahan Petir: Sekutu petir terima 20% kurang kerosakan tambahan/pasif, dan musuh [Tersetrum] beri -40% kerosakan kepada mereka.',
		describe = 'Swift as the Wind:#L0#Moves like thunder, godlike agility, initial dodge rate +50%.\n#F10#\n#F40##L10#Shadow Clone:#L0#At the start of each round, creates a [Shadow Clone] that follows him. The clone inherits 50% of Minato’s stats, is immune to all effects. When enemies attack Minato, there\'s a 50% chance (plus 5% per enemy) to hit the clone instead and inflict [Electrified] for 2 turns. Minato takes no damage or effects from that attack. When Minato attacks, the clone assists by hitting the same target range, dealing 250% of its own physical attack.\n#F10#\n#F40##L10#Preemptive Strike:#L0#When a clone is present, Minato preemptively normal attacks any enemy who tries to hit him, converts one of their buffs into [Electrified] for 2 turns, and increases his own Speed by 20% for 1 turn.\n#F10#\n#F40##L10#Wind-Thunder Ninja:#L0#When attacking [Electrified] targets, Minato also applies [Magnetized] for 1 turn. (Magnetized: Removes 2 buffs on application; when attacking Thunder-type enemies, reactivates. At the end, 50% chance to paralyze target 1 turn.)\nThunder Amplify: Allies of Thunder-type deal +[color=#5c9970]$(20+skillLevel*0.1-0.1)$%[color=#5B545B] more damage to [Undead]/[Aqua] types, and +[Electrified] 2 turns.\nThunder Weaken: Thunder allies receive -20% extra/passive damage; [Electrified] enemies deal -40% damage to Thunder allies.',
		starEffect = __data_t__starEffect[41616],
		-- {8}
		starEffectDesc_vn = 'Trước mỗi lượt lớn, tạo một “Phân thân ảo” của Namikaze Minato đi theo đồng minh hệ Lôi hoặc hệ Nhẫn có công cao nhất, đồng thời nhận hiệu ứng “Ra Tay Trước”; Phân thân nhận được nộ sẽ truyền lại cho bản thể, khi bị tiêu diệt sẽ gây sát thương vật lý bằng 200% công của phân thân lên kẻ tấn công.',
		starEffectDesc = 'At the start of each major turn, create a Namikaze Minato "Phantom Clone" to follow the Thunder or Ninja ally with the highest attack, granting them the "Preemptive Strike" effect; any rage gained by the Phantom transfers to the main body, and if killed, it deals 200% of the Phantom’s attack as physical damage to the attacker.',
		starEffectDesc_en = 'At the start of each major turn, create a Namikaze Minato "Phantom Clone" to follow the Thunder or Ninja ally with the highest attack, granting them the "Preemptive Strike" effect; any rage gained by the Phantom transfers to the main body, and if killed, it deals 200% of the Phantom’s attack as physical damage to the attacker.',
		starEffectDesc_th = 'เมื่อเริ่มรอบใหญ่แต่ละรอบ จะสร้าง “ร่างเงา” ของ Minato ติดตามพันธมิตรธาตุสายฟ้าหรือนินจาที่มีพลังโจมตีสูงสุด พร้อมได้รับเอฟเฟกต์ “ลงมือก่อน”; ความโกรธที่ได้รับจากร่างเงาจะถูกส่งต่อไปยังร่างหลัก และหากร่างเงาถูกสังหารจะสร้างความเสียหายทางกายภาพ 200% ของพลังโจมตีร่างเงาใส่ผู้โจมตี',
		starEffectDesc_in = 'Pada awal setiap giliran besar, ciptakan “Bayangan Minato” untuk mengikuti sekutu bertipe Petir atau Ninja dengan serangan tertinggi dan beri efek “Serangan Terlebih Dahulu”; Amarah yang diperoleh bayangan akan diteruskan ke tubuh asli, dan jika bayangan dibunuh akan memberikan 200% serangan fisik kepada penyerang.',
		starEffectDesc_ph = 'Sa simula ng bawat major turn, lilikha ng "Phantom Clone" ni Minato upang samahan ang Thunder o Ninja na kakampi na may pinakamataas na atake, at makakakuha ng “Preemptive Strike” effect; Ang galit na nakuha ng clone ay ipapasa sa orihinal na katawan, at kung mapapatay ito ay magdudulot ng 200% physical damage batay sa atake ng clone sa kalaban.',
		starEffectDesc_ma = 'At the start of each major turn, create a Namikaze Minato "Phantom Clone" to follow the Thunder or Ninja ally with the highest attack, granting them the "Preemptive Strike" effect; any rage gained by the Phantom transfers to the main body, and if killed, it deals 200% of the Phantom’s attack as physical damage to the attacker.',
		zawakeEffect = __data_t__zawakeEffect[41616],
		-- {79004, 1}
		zawakeEffectDesc = 'At the start of each major turn, create a Minato "Phantom Clone" to follow the two Thunder or Ninja allies with the highest attack, granting them the "Preemptive Strike" effect; Rage gained by the clone transfers to the main body, and if killed, it deals 200% of its attack as physical damage to the attacker\n#L10#Thunder Charge: #L0#When Thunder heroes take action, they grant Minato 50 rage; likewise, when Minato acts, he grants 50 rage to other Thunder heroes',
		zawakeEffectDesc_en = 'At the start of each major turn, create a Minato "Phantom Clone" to follow the two Thunder or Ninja allies with the highest attack, granting them the "Preemptive Strike" effect; Rage gained by the clone transfers to the main body, and if killed, it deals 200% of its attack as physical damage to the attacker\n#L10#Thunder Charge: #L0#When Thunder heroes take action, they grant Minato 50 rage; likewise, when Minato acts, he grants 50 rage to other Thunder heroes',
		zawakeEffectDesc_th = 'เมื่อเริ่มรอบใหญ่แต่ละรอบ จะสร้าง “ร่างเงา Minato” ให้ติดตามพันธมิตรธาตุสายฟ้าหรือนินจาสองตัวที่มีพลังโจมตีสูงสุด และได้รับเอฟเฟกต์ “ลงมือก่อน”; ความโกรธที่ได้รับจากร่างเงาจะถูกส่งต่อไปยังร่างหลัก และหากร่างเงาถูกสังหารจะสร้างความเสียหายกายภาพ 200% ของพลังโจมตีใส่ผู้โจมตี\n#L10#ชาร์จสายฟ้า: #L0#เมื่อตัวละครธาตุสายฟ้าออกแอคชัน จะเพิ่ม 50 โกรธให้ Minato และเมื่อ Minato ออกแอคชันก็จะเพิ่ม 50 โกรธให้ตัวละครสายฟ้าอื่นๆ',
		zawakeEffectDesc_in = 'Pada awal setiap giliran besar, buat “Bayangan Minato” untuk mengikuti dua sekutu bertipe Petir atau Ninja dengan serangan tertinggi, dan berikan efek “Serangan Terlebih Dahulu”; Amarah yang diperoleh bayangan akan diteruskan ke tubuh asli, dan jika bayangan dibunuh akan memberikan 200% serangan fisik kepada penyerang\n#L10#Pengisian Petir: #L0#Saat hero tipe Petir bertindak, mereka memberikan 50 amarah ke Minato; sebaliknya saat Minato bertindak, dia memberikan 50 amarah ke hero tipe Petir lainnya',
		zawakeEffectDesc_ph = 'Sa simula ng bawat major turn, lilikha ng "Phantom Clone" ni Minato upang samahan ang dalawang Thunder o Ninja na kakampi na may pinakamataas na atake, at makakakuha ng “Preemptive Strike” effect; Ang galit na nakuha ng clone ay ipapasa sa orihinal na katawan, at kung mapapatay ito ay magdudulot ng 200% physical damage batay sa atake ng clone sa kalaban\n#L10#Thunder Recharge: #L0#Kapag kumilos ang Thunder-type heroes, nagbibigay sila ng 50 rage kay Minato; gayundin, kapag si Minato ang kumilos, nagbibigay siya ng 50 rage sa ibang Thunder-type heroes',
		zawakeEffectDesc_ma = 'At the start of each major turn, create a Minato "Phantom Clone" to follow the two Thunder or Ninja allies with the highest attack, granting them the "Preemptive Strike" effect; Rage gained by the clone transfers to the main body, and if killed, it deals 200% of its attack as physical damage to the attacker\n#L10#Thunder Charge: #L0#When Thunder heroes take action, they grant Minato 50 rage; likewise, when Minato acts, he grants 50 rage to other Thunder heroes',
		zawakeEffectDesc_vn = 'Trước mỗi lượt lớn, tạo một “Phân thân Minato” đi theo hai đồng minh hệ Lôi hoặc hệ Nhẫn có công cao nhất, đồng thời nhận hiệu ứng “Ra Tay Trước”; Phân thân nhận được nộ sẽ truyền lại cho bản thể, khi bị tiêu diệt sẽ gây 200% sát thương vật lý của phân thân lên kẻ tấn công\n#L10#Sạc Năng Lượng Lôi: #L0#Khi tướng hệ Lôi hành động, sẽ cung cấp 50 nộ cho Minato, ngược lại khi Minato hành động cũng cung cấp 50 nộ cho các tướng hệ Lôi khác',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Create a Minato “Phantom Clone” to follow the Thunder or Ninja ally with the highest attack\n#F20#\n#F40##C0x5c9970#→Create a Minato “Phantom Clone” to follow the two Thunder or Ninja allies with the highest attack\nThunder Charge: When Thunder heroes act, they grant Minato 50 rage; likewise, when Minato acts, he grants 50 rage to other Thunder heroes',
		zawakeSimpleDesc_en = 'Create a Minato “Phantom Clone” to follow the Thunder or Ninja ally with the highest attack\n#F20#\n#F40##C0x5c9970#→Create a Minato “Phantom Clone” to follow the two Thunder or Ninja allies with the highest attack\nThunder Charge: When Thunder heroes act, they grant Minato 50 rage; likewise, when Minato acts, he grants 50 rage to other Thunder heroes',
		zawakeSimpleDesc_th = 'สร้าง “ร่างเงา Minato” ให้ติดตามพันธมิตรธาตุสายฟ้าหรือนินจาที่มีพลังโจมตีสูงสุด 1 ตัว\n#F20#\n#F40##C0x5c9970#→สร้าง “ร่างเงา Minato” ให้ติดตามพันธมิตรธาตุสายฟ้าหรือนินจาที่มีพลังโจมตีสูงสุด 2 ตัว\nชาร์จสายฟ้า: เมื่อตัวละครธาตุสายฟ้าทำการเคลื่อนไหว จะเพิ่ม 50 โกรธให้ Minato และในทางกลับกัน Minato ก็จะเพิ่ม 50 โกรธให้ตัวละครธาตุสายฟ้าอื่นๆ',
		zawakeSimpleDesc_in = 'Buat satu “Bayangan Minato” untuk mengikuti satu sekutu bertipe Petir atau Ninja dengan serangan tertinggi\n#F20#\n#F40##C0x5c9970#→Buat dua “Bayangan Minato” untuk mengikuti dua sekutu bertipe Petir atau Ninja dengan serangan tertinggi\nPengisian Petir: Saat hero tipe Petir bertindak, mereka memberi 50 amarah ke Minato; sebaliknya, saat Minato bertindak, dia memberi 50 amarah ke hero Petir lainnya',
		zawakeSimpleDesc_ph = 'Lumikha ng isang “Phantom Clone” ni Minato para samahan ang isang kakampi na Thunder o Ninja na may pinakamataas na atake\n#F20#\n#F40##C0x5c9970#→Lumikha ng dalawang “Phantom Clone” ni Minato para samahan ang dalawang Thunder o Ninja na kakampi na may pinakamataas na atake\nThunder Recharge: Kapag kumilos ang Thunder-type heroes, nagbibigay sila ng 50 rage kay Minato; gayundin, kapag si Minato ang kumilos, nagbibigay siya ng 50 rage sa iba pang Thunder-type heroes',
		zawakeSimpleDesc_ma = 'Create a Minato “Phantom Clone” to follow the Thunder or Ninja ally with the highest attack\n#F20#\n#F40##C0x5c9970#→Create a Minato “Phantom Clone” to follow the two Thunder or Ninja allies with the highest attack\nThunder Charge: When Thunder heroes act, they grant Minato 50 rage; likewise, when Minato acts, he grants 50 rage to other Thunder heroes',
		zawakeSimpleDesc_vn = 'Tạo một “Phân thân Minato” đi theo một đồng minh hệ Lôi hoặc hệ Nhẫn có công cao nhất\n#F20#\n#F40##C0x5c9970#→Tạo một “Phân thân Minato” đi theo hai đồng minh hệ Lôi hoặc hệ Nhẫn có công cao nhất\nSạc Năng Lượng Lôi: Khi tướng hệ Lôi hành động, sẽ cung cấp 50 nộ cho Minato; ngược lại, khi Minato hành động, cũng sẽ cung cấp 50 nộ cho các tướng hệ Lôi khác',
		iconRes = 'battle/skill_icon/skill_41616.png',
