	[41622] = {
		id = 41622,
		skillName_vn = 'Bóng sét thoáng qua',
		skillName_en = 'Flash lightning',
		skillName_th = 'ฟ้าผ่าชั่วขณะ',
		skillName_in = 'Kilatan petir',
		skillName_ph = 'Kislap ng kidlat',
		skillName_ma = 'Kilatan kilat',
		skillName = 'Flash lightning',
		describe_vn = 'Zeraora lao vào mục tiêu hàng dọc của kẻ địch với tốc độ sấm sét, gây #C0xE69900#170% Công Vật Lý#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, 100% xác suất [tê liệt] mục tiêu trong 2 lượt, sau đó biến mất khỏi sân, để lại một [ảo ảnh] tại chỗ kéo dài đến trước lượt hành động tiếp theo của bản thân, khi [ảo ảnh] biến mất, Zeraora quay lại vị trí ban đầu',
		describe_en = 'Zeraora charges at the enemy\'s vertical target with lightning speed, dealing #C0xE69900#170% Physical Attack#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Physical Damage#C0x5B545B#, with a 100% chance to [paralyze] the target for 2 turns, then disappears from the field, leaving an [illusion] at the spot lasting until before the next action turn of itself. When the [illusion] disappears, Zeraora returns to the original position.',
		describe_th = 'Zeraora พุ่งเข้ารุกเป้าหมายแนวตั้งของศัตรูด้วยความเร็วฟ้าแลบ สร้างความเสียหาย #C0xE69900#170% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# พร้อมโอกาส 100% ในการ [ทำให้เป็นอัมพาต] เป้าหมายเป็นเวลา 2 เทิร์น จากนั้นหายตัวจากสนาม ทิ้ง [ภาพลวงตา] ไว้ ณ จุดนั้นจนกว่าจะถึงเทิร์นถัดไปของตัวเอง เมื่อ [ภาพลวงตา] หายไป Zeraora จะกลับไปตำแหน่งเดิม',
		describe_in = 'Zeraora menyerbu target baris vertikal musuh dengan kecepatan kilat, menyebabkan #C0xE69900#170% Serangan Fisik#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, dengan peluang 100% untuk [melumpuhkan] target selama 2 giliran, kemudian menghilang dari medan, meninggalkan sebuah [ilusi] di tempat tersebut yang bertahan sampai giliran aksi berikutnya dari dirinya sendiri. Ketika [ilusi] hilang, Zeraora kembali ke posisi awal.',
		describe_ph = 'Si Zeraora ay lumusob sa patindihang target ng kalaban nang kabilis ng kidlat, nagdudulot ng #C0xE69900#170% Physical Attack#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Physical Damage#C0x5B545B#, may 100% na tsansa na [maparalisa] ang target nang 2 na turn, pagkatapos ay nawawala mula sa larangan, nag-iiwan ng isang [illusion] sa lugar na tumatagal hanggang bago ang susunod na turn ng sarili. Kapag nawala ang [illusion], babalik si Zeraora sa orihinal na posisyon.',
		describe_ma = 'Zeraora menyerbu sasaran baris menegak musuh dengan kelajuan kilat, menyebabkan #C0xE69900#170% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, dengan kebarangkalian 100% untuk [melumpuhkan] sasaran selama 2 pusingan, kemudian hilang dari padang, meninggalkan sebuah [ilusi] di tempat tersebut yang berlanjutan sehingga giliran tindakan seterusnya daripadanya sendiri. Apabila [ilusi] hilang, Zeraora kembali ke posisi asal.',
		describe = 'Zeraora charges at the enemy\'s vertical target with lightning speed, dealing #C0xE69900#170% Physical Attack#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Physical Damage#C0x5B545B#, with a 100% chance to [paralyze] the target for 2 turns, then disappears from the field, leaving an [illusion] at the spot lasting until before the next action turn of itself. When the [illusion] disappears, Zeraora returns to the original position.',
		upLvDesc = 'Fixed damage +240',
		upLvDesc_en = 'Fixed damage +240',
		upLvDesc_th = 'ดาเมจคงที่ +240',
		upLvDesc_in = 'Kerusakan tetap +240',
