	[41623] = {
		id = 41623,
		skillName_vn = 'Đấm sét plasma',
		skillName_en = 'Plasma Punch',
		skillName_th = 'หมัดพลาสม่า',
		skillName_in = 'Pukulan Plasma',
		skillName_ph = 'Plasma Punch',
		skillName_ma = 'Pukulan Plasma',
		skillName = 'Plasma Punch',
		describe_vn = 'Zeraora tập hợp dòng điện hàng chục nghìn volt vào tay và ngay lập tức đấm 5 phát với tốc độ cực nhanh xuyên gió, tấn công các mục tiêu địch ngẫu nhiên. Mỗi cú đấm gây ra #C0xE69900#220% Sát Thương Vật Lý#C0x5B545B#+$(skillLev el*4*60)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, nếu trúng 3 tướng khác nhau, hiệu ứng [static field] sẽ được kích hoạt và tác động lên toàn bộ sân của kẻ địch, kéo dài 1~2 hiệp lớn\n#F10# \n#F40##L10#Điện trường tĩnh: Trong thời gian #L0#, có 50% khả năng bị [Cảm ứng] và không thể nhận được buff. Sau khi phát động tấn công, có 80% khả năng bị [Tê liệt] trong 1 lượt. Khi Anh hùng Sấm sét của bạn tấn công một mục tiêu trong Điện trường tĩnh, 25% sát thương kỹ năng sẽ được truyền tới tối đa hai mục tiêu [Từ hóa].',
		describe_en = 'Zeraora gathers tens of thousands of volts of electricity in his hands and immediately punches 5 times at extremely high speed, striking random enemy targets. Each punch deals #C0xE69900#220% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#. If hitting 3 different enemy heroes, the [static field] effect is triggered and affects the entire enemy arena, lasting 1~2 large rounds. Static Field: For #L0# duration, there is a 50% chance to be [Electrified] and unable to receive buffs. After initiating the attack, there is an 80% chance to be [Paralyzed] for 1 turn. When your Thunder Hero attacks a target inside the Static Field, 25% of the skill damage is transferred to up to two [Magnetized] targets.',
		describe_th = 'เซราออระรวบรวมไฟฟ้าสูงถึงหมื่นโวลต์ไว้ที่มือและทันทีที่นั้นก็ชก 5 ครั้งด้วยความเร็วสูงมาก โจมตีนายเป้าหมายศัตรูแบบสุ่ม แต่ละครั้งสร้าง #C0xE69900#220% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# หากโจมตีฮีโร่ศัตรู 3 ตัวที่แตกต่างกัน จะเปิดใช้งานเอฟเฟกต์ [สนามไฟฟ้าสถิต] และส่งผลกระทบต่อศัตรูทั้งสนาม ต่อเนื่องเป็นเวลา 1~2 รอบใหญ่ สนามไฟฟ้าสถิต: ในระยะเวลา #L0# มีโอกาส 50% ที่จะถูก [ช็อตไฟฟ้า] และไม่สามารถรับบัฟ หลังจากเริ่มโจมตี มีโอกาส 80% ที่จะถูก [ชา] เป็นเวลา 1 เทิร์น เมื่อฮีโร่สายฟ้าของคุณโจมตีเป้าหมายในสนามไฟฟ้าสถิต 25% ของความเสียหายทักษะจะถูกส่งต่อไปยังเป้าหมาย [แม่เหล็ก] สูงสุดสองเป้าหมาย',
		describe_in = 'Zeraora mengumpulkan listrik dengan tegangan puluhan ribu volt di tangannya dan langsung memukul 5 kali dengan kecepatan sangat tinggi mengenai target musuh secara acak. Setiap pukulan memberikan #C0xE69900#220% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#. Jika mengenai 3 pahlawan musuh berbeda, efek [static field] akan diaktifkan dan mempengaruhi seluruh arena musuh, berlangsung selama 1~2 giliran besar. Static Field: Selama durasi #L0#, ada 50% kemungkinan terkena [Electrified] dan tidak dapat menerima buff. Setelah melakukan serangan, ada 80% kemungkinan terkena [Paralyzed] selama 1 giliran. Ketika Pahlawan Petir Anda menyerang target di dalam Static Field, 25% kerusakan skill akan diteruskan ke maksimal dua target [Magnetized].',
		describe_ph = 'Nagtipon si Zeraora ng sampu-sampung libong boltahe ng kuryente sa kanyang mga kamay at agad na tumama ng 5 beses nang sobrang bilis na tumatagos sa hangin, umatake sa mga random na target ng kalaban. Bawat suntok ay nagdudulot ng #C0xE69900#220% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#. Kung tumama sa 3 iba\'t ibang bayani ng kalaban, ang epekto ng [static field] ay naipapagana at tumatama sa buong lugar ng kalaban, tumatagal ng 1~2 malaking turn. Static Field: Sa loob ng #L0#, may 50% na tsansa na ma-[Electrified] at hindi makakatanggap ng buffs. Pagkatapos simulan ang pag-atake, may 80% na tsansa ng ma-[Paralyzed] sa loob ng 1 turn. Kapag inatake ng iyong Thunder Hero ang isang target sa loob ng Static Field, 25% ng skill damage ay naipapasa sa hanggang dalawang [Magnetized] na target.',
		describe_ma = 'Zeraora mengumpul elektrik sebanyak puluhan ribu volt di tangannya dan terus-menerus menumbuk sebanyak 5 kali dengan kelajuan yang sangat pantas menyerang sasaran musuh secara rawak. Setiap tumbukan menyebabkan #C0xE69900#220% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#. Jika terkena 3 wira musuh yang berbeza, kesan [medan statik] akan diaktifkan dan memberi kesan ke seluruh medan musuh, berlangsung selama 1~2 pusingan besar. Medan Statik: Dalam tempoh #L0#, terdapat 50% kemungkinan terkena [Tersentuh] dan tidak boleh menerima buff. Selepas melancarkan serangan, terdapat 80% kemungkinan terkena [Purus] selama 1 giliran. Apabila Wira Guruh anda menyerang sasaran dalam Medan Statik, 25% kerosakan kemahiran akan dipindahkan ke maksima dua sasaran [Magnetized].',
		describe = 'Zeraora gathers tens of thousands of volts of electricity in his hands and immediately punches 5 times at extremely high speed, striking random enemy targets. Each punch deals #C0xE69900#220% Physical Damage#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#. If hitting 3 different enemy heroes, the [static field] effect is triggered and affects the entire enemy arena, lasting 1~2 large rounds. Static Field: For #L0# duration, there is a 50% chance to be [Electrified] and unable to receive buffs. After initiating the attack, there is an 80% chance to be [Paralyzed] for 1 turn. When your Thunder Hero attacks a target inside the Static Field, 25% of the skill damage is transferred to up to two [Magnetized] targets.',
		simDesc_vn = 'Jellicent tập trung hàng triệu vôn điện, với tốc độ chớp giật của gió, nhanh chóng tung ra 5 cú đấm tấn công ngẫu nhiên các mục tiêu kẻ thù; tấn công vào nhiều mục tiêu khác nhau sẽ kích hoạt hiệu ứng Điện Trường.',
		simDesc_en = 'Jellicent gathers millions of volts of electricity and, with the lightning-fast speed of the wind, quickly delivers 5 punches attacking random enemy targets; attacking multiple different targets will trigger the Electric Field effect.',
		simDesc_th = 'Jellicent สะสมกระแสไฟฟ้าหลายล้านโวลต์ และด้วยความเร็วว่องไวเหมือนสายลม ฟาดหมัด 5 ครั้งไปยังเป้าหมายศัตรูแบบสุ่ม; การโจมตีเป้าหมายหลายตัวจะทำให้เกิดเอฟเฟกต์สนามไฟฟ้า',
		simDesc_in = 'Jellicent mengumpulkan jutaan volt listrik dan, dengan kecepatan kilat angin, dengan cepat melayangkan 5 pukulan menyerang target musuh secara acak; menyerang beberapa target berbeda akan memicu efek Medan Listrik.',
		simDesc_ph = 'Nagtipon si Jellicent ng milyong volts ng kuryente, at sa kabilis ng kidlat ng hangin, mabilis na nagbigay ng 5 suntok na inaatake ang mga random na target ng kalaban; ang pag-atake sa maraming iba\'t ibang target ay magtutulak ng epekto ng Electric Field.',
		simDesc_ma = 'Jellicent mengumpul jutaan volt elektrik dan, dengan kelajuan kilat angin, dengan pantas melancarkan 5 tumbukan menyerang sasaran musuh secara rawak; menyerang pelbagai sasaran yang berbeza akan mengaktifkan kesan Medan Elektrik.',
		simDesc = 'Jellicent gathers millions of volts of electricity and, with the lightning-fast speed of the wind, quickly delivers 5 punches attacking random enemy targets; attacking multiple different targets will trigger the Electric Field effect.',
		starEffect = __data_t__starEffect[41623],
		-- {11}
		starEffectDesc_vn = 'Giải phóng sau nếu tồn tại <Ảo ảnh sấm sét>, thì hợp thể với Ảo ảnh sấm sét thành <Pháp tướng sấm sét> trong 2 lượt\nPháp tướng sấm sét: thêm 80% thuộc tính hiện tại của Ảo ảnh sấm sét, và tăng thêm 50% né tránh, mỗi lần tấn công chủ động đều là phát ra đòn điện plasma (không tiêu hao, hồi phục tức giận nhưng tốc độ hồi tức giận của bản thân giảm 50%), số lần ra đòn tăng một và chắc chắn trúng đích',
		starEffectDesc = 'Release after if <Thunder Illusion> exists, then merge with Thunder Illusion to form <Thunder Marshal> in 2 turns. Thunder Marshal: adds 80% of current attributes of Thunder Illusion, and increases evasion by 50%. Each active attack emits a plasma electric strike (no consumption, restores rage but reduces own rage recovery speed by 50%), the number of strikes increases by one and is guaranteed to hit.',
		starEffectDesc_en = 'Release after if <Thunder Illusion> exists, then merge with Thunder Illusion to form <Thunder Marshal> in 2 turns. Thunder Marshal: adds 80% of current attributes of Thunder Illusion, and increases evasion by 50%. Each active attack emits a plasma electric strike (no consumption, restores rage but reduces own rage recovery speed by 50%), the number of strikes increases by one and is guaranteed to hit.',
		starEffectDesc_th = 'ปลดปล่อยหลังจากถ้ามี <ภาพลวงตาสายฟ้า> จากนั้นรวมกับภาพลวงตาสายฟ้าเป็น <จอมทัพสายฟ้า> ใน 2 เทิร์น จอมทัพสายฟ้า: เพิ่ม 80% คุณสมบัติปัจจุบันของภาพลวงตาสายฟ้า และเพิ่มการหลบหลีกอีก 50% ทุกการโจมตีที่ใช้งานจะปล่อยการโจมตีด้วยพลาสม่าไฟฟ้า (ไม่มีการใช้พลังงาน ฟื้นฟูความโกรธแต่ความเร็วในการฟื้นความโกรธของตนเองลดลง 50%) จำนวนการโจมตีเพิ่มขึ้นหนึ่งครั้งและโจมตีถูกต้องแน่นอน',
		starEffectDesc_in = 'Bebaskan setelah jika <Ilusi Petir> ada, lalu gabungkan dengan Ilusi Petir menjadi <Komandan Petir> dalam 2 giliran. Komandan Petir: menambahkan 80% atribut saat ini dari Ilusi Petir, dan meningkatkan penghindaran sebesar 50%. Setiap serangan aktif menghasilkan serangan listrik plasma (tanpa konsumsi, memulihkan kemarahan tapi kecepatan pemulihan kemarahan sendiri berkurang 50%), jumlah serangan meningkat satu dan pasti mengenai sasaran.',
		starEffectDesc_ph = 'Pakawalan pagkatapos kung mayroon <Ilusyon ng Kidlat>, pagkatapos pagsamahin ito sa Ilusyon ng Kidlat upang maging <Punong Heneral ng Kidlat> sa loob ng 2 turn. Punong Heneral ng Kidlat: nagdadagdag ng 80% ng kasalukuyang katangian ng Ilusyon ng Kidlat, at tumataas ng 50% ang pag-iwas. Bawat aktibong pag-atake ay naglalabas ng plasma electric strike (hindi kumokonsumo, nagpapagaling ng galit ngunit bumababa ng 50% ang bilis ng paggaling ng sariling galit), tumataas ng isa ang bilang ng atake at sigurado ang tama.',
		starEffectDesc_ma = 'Lepaskan selepas jika <Ilusi Kilat> wujud, kemudian gabungkan dengan Ilusi Kilat menjadi <Panglima Kilat> dalam 2 pusingan. Panglima Kilat: menambah 80% atribut semasa Ilusi Kilat, dan meningkatkan elakan sebanyak 50%. Setiap serangan aktif mengeluarkan serangan elektrik plasma (tiada penggunaan, memulihkan kemarahan tetapi kelajuan pemulihan kemarahan sendiri berkurang 50%), bilangan serangan bertambah satu dan pasti mengenai sasaran.',
		upLvDesc = 'Fixed damage +240',
		upLvDesc_en = 'Fixed damage +240',
		upLvDesc_th = 'ดาเมจคงที่ +240',
