	[41629] = {
		id = 41629,
		skillName_vn = 'Đấm sét plasma',
		skillName_en = 'Plasma punch',
		skillName_th = 'หมัดพลาสม่า',
		skillName_in = 'Pukulan plasma',
		skillName_ph = 'Plasma punch',
		skillName_ma = 'Pukulan plasma',
		skillName = 'Plasma punch',
		describe_vn = 'Zeraora tập hợp dòng điện hàng chục nghìn volt vào tay và ngay lập tức đấm 6 phát với tốc độ tia chớp để cắt gió, tấn công ngẫu nhiên các mục tiêu địch. Mỗi cú đấm gây ra #C0xE69900#220% Sát Thương Vật Lý#C0x5B545B#+$(skillLev el*4*60)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, nếu trúng 3 tướng khác nhau, hiệu ứng [static field] sẽ được kích hoạt và tác động lên toàn bộ sân của kẻ địch, kéo dài 1~2 hiệp lớn\n#F10# \n#F40##L10#Điện trường tĩnh: Trong #L0#, có 50% khả năng bị [Cảm ứng] và không thể nhận được buff, và 80% khả năng bị [Tê liệt] trong 1 lượt sau khi phát động tấn công. Khi Anh hùng Sấm sét của bạn tấn công một mục tiêu trong Điện trường tĩnh, 25% sát thương kỹ năng sẽ được truyền tới tối đa hai mục tiêu [Từ hóa].',
		describe_en = 'Zeraora gathers tens of thousands of volts of electricity into its hands and immediately throws 6 punches at lightning speed to cut through the wind, randomly attacking enemy targets. Each punch deals #C0xE69900#220% Physical Damage#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#. If it hits 3 different heroes, the [static field] effect will be activated, affecting the entire enemy field and lasting 1~2 large turns. \n#F10# \n#F40##L10# Static Field: For #L0#, there is a 50% chance to receive [Induction] and cannot receive buffs, and an 80% chance to be [Paralyzed] for 1 turn after launching the attack. When your Thunder Hero attacks a target in the Static Field, 25% of skill damage will be transferred to up to two [Magnetized] targets.',
		describe_th = 'Zeraora รวบรวมไฟฟ้าหลายหมื่นโวลต์เข้าที่มือและทันทีที่ปล่อยหมัด 6 ครั้งด้วยความเร็วสายฟ้าเพื่อเฉือนลม โจมตีเป้าหมายศัตรูแบบสุ่ม หมัดแต่ละหมัดก่อให้เกิด #C0xE69900#220% ความเสียหายกายภาพ#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# ความเสียหายกายภาพ #C0x5B545B# หากโดนฮีโร่ต่างกัน 3 ตัว เอฟเฟกต์ [static field] จะทำงานและส่งผลต่อทั้งสนามของศัตรู เป็นเวลานาน 1~2 รอบใหญ่ \n#F10# \n#F40##L10# สนามไฟฟ้าสถิต: ใน #L0# มีโอกาส 50% ที่จะเกิด [Induction] และไม่สามารถรับบัฟได้ และโอกาส 80% ที่จะถูก [เป็นอัมพาต] เป็นเวลา 1 เทิร์นหลังโจมตี เมื่อฮีโร่สายฟ้าของคุณโจมตีเป้าหมายในสนามไฟฟ้าสถิต จะมีการส่งต่อความเสียหายทักษะ 25% ไปยังเป้าหมาย [Magnetized] สูงสุดสองตัว',
		describe_in = 'Zeraora mengumpulkan listrik puluhan ribu volt di tangan dan segera melepaskan 6 pukulan dengan kecepatan kilat untuk memotong angin, menyerang target musuh secara acak. Setiap pukulan menyebabkan #C0xE69900#220% Kerusakan Fisik#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Kerusakan Fisik #C0x5B545B#. Jika mengenai 3 pahlawan berbeda, efek [static field] akan diaktifkan dan mempengaruhi seluruh medan musuh, berlangsung selama 1~2 giliran besar. \n#F10# \n#F40##L10# Medan Statis: Selama #L0#, ada peluang 50% untuk terkena [Induction] dan tidak bisa menerima buff, serta peluang 80% untuk terkena [Paralysis] selama 1 giliran setelah menyerang. Ketika Pahlawan Petirmu menyerang target dalam Medan Statis, 25% kerusakan keterampilan akan dialihkan ke maksimal dua target [Magnetized].',
		describe_ph = 'Zeraora ay nagtipon ng sampu-sampung libong boltahe ng kuryente sa mga kamay at agad na tumama ng 6 na suntok sa bilis ng kidlat upang hiwain ang hangin, random na inaatake ang mga kalaban na target. Bawat suntok ay nagdudulot ng #C0xE69900#220% Pisikal na Pinsala#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Pisikal na Pinsala #C0x5B545B#. Kung tumama sa 3 magkakaibang bayani, ang epekto ng [static field] ay aaktibo at gagana sa buong larangan ng kalaban, tumatagal ng 1~2 malalaking turno. \n#F10# \n#F40##L10# Static Field: Sa loob ng #L0#, may 50% tsansa na ma-[Induction] at hindi maaaring tumanggap ng buff, at 80% tsansa na ma-[Paralyzed] sa loob ng 1 turno pagkatapos maglunsad ng atake. Kapag inatake ng iyong Thunder Hero ang isang target sa loob ng Static Field, 25% ng skill damage ay malilipat sa hanggang dalawang [Magnetized] na target.',
		describe_ma = 'Zeraora mengumpulkan puluhan ribu volt elektrik ke tangannya dan segera menumbuk 6 kali dengan kelajuan kilat untuk memotong angin, menyerang sasaran musuh secara rawak. Setiap tumbukan menyebabkan #C0xE69900#220% Kerosakan Fizikal#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Kerosakan Fizikal #C0x5B545B#. Jika terkena 3 wira berbeza, kesan [static field] akan diaktifkan dan memberi kesan kepada keseluruhan medan musuh, berlangsung selama 1~2 pusingan besar. \n#F10# \n#F40##L10# Medan Statik: Dalam #L0#, terdapat 50% kebarangkalian untuk mendapat [Induction] dan tidak dapat menerima buff, serta 80% kebarangkalian untuk mengalami [Lumpuh] selama 1 pusingan selepas melancarkan serangan. Apabila Wira Guntur anda menyerang sasaran dalam Medan Statik, 25% kerosakan kemahiran akan dipindahkan ke maksimum dua sasaran [Magnetized].',
		describe = 'Zeraora gathers tens of thousands of volts of electricity into its hands and immediately throws 6 punches at lightning speed to cut through the wind, randomly attacking enemy targets. Each punch deals #C0xE69900#220% Physical Damage#C0x5B545B# + $(skillLevel*4*60)$ #C0xF13B54# Physical Damage #C0x5B545B#. If it hits 3 different heroes, the [static field] effect will be activated, affecting the entire enemy field and lasting 1~2 large turns. \n#F10# \n#F40##L10# Static Field: For #L0#, there is a 50% chance to receive [Induction] and cannot receive buffs, and an 80% chance to be [Paralyzed] for 1 turn after launching the attack. When your Thunder Hero attacks a target in the Static Field, 25% of skill damage will be transferred to up to two [Magnetized] targets.',
		starEffect = __data_t__starEffect[41629],
		-- {11}
		starEffectDesc_vn = 'Giải phóng sau nếu tồn tại <Ảo ảnh sấm sét>, thì hợp thể với Ảo ảnh sấm sét thành <Pháp tướng sấm sét> trong 2 lượt\nPháp tướng sấm sét: thêm 80% thuộc tính hiện tại của Ảo ảnh sấm sét, và tăng thêm 50% né tránh, mỗi lần tấn công chủ động đều là phát ra đòn điện plasma (không tiêu hao, hồi phục tức giận nhưng tốc độ hồi tức giận của bản thân giảm 50%), số lần ra đòn tăng một và chắc chắn trúng đích',
		starEffectDesc = 'Release afterward if <Thunder Illusion> exists, then merge with Thunder Illusion to form <Thunder Avatar> within 2 rounds. Thunder Avatar: adds 80% of the current attributes of Thunder Illusion, and increases evasion by 50%. Each active attack releases a plasma electric strike (no consumption, restores rage but reduces self rage recovery speed by 50%), the number of strikes increases by one and is guaranteed to hit.',
		starEffectDesc_en = 'Release afterward if <Thunder Illusion> exists, then merge with Thunder Illusion to form <Thunder Avatar> within 2 rounds. Thunder Avatar: adds 80% of the current attributes of Thunder Illusion, and increases evasion by 50%. Each active attack releases a plasma electric strike (no consumption, restores rage but reduces self rage recovery speed by 50%), the number of strikes increases by one and is guaranteed to hit.',
		starEffectDesc_th = 'ปล่อยตัวหลังจากหากมี <ภาพลวงตาแห่งสายฟ้า> จากนั้นรวมกับภาพลวงตาแห่งสายฟ้าเป็น <ภูติสายฟ้า> ใน 2 รอบ ภูติสายฟ้า: เพิ่มคุณสมบัติปัจจุบันของภาพลวงตาแห่งสายฟ้า 80% และเพิ่มการหลบหลีก 50% ทุกการโจมตีแบบแอคทีฟจะปล่อยพลังพลาสมาไฟฟ้า (ไม่เสียพลังงาน ฟื้นฟูความโกรธแต่ลดความเร็วในการฟื้นฟูความโกรธของตนเองลง 50%) จำนวนครั้งในการโจมตีเพิ่มขึ้นหนึ่งครั้งและรับประกันการโจมตีถูกต้อง',
		starEffectDesc_in = 'Lepaskan setelah jika <Ilusi Petir> ada, lalu gabungkan dengan Ilusi Petir menjadi <Avatar Petir> dalam 2 giliran. Avatar Petir: menambahkan 80% atribut saat ini dari Ilusi Petir, dan meningkatkan penghindaran sebesar 50%. Setiap serangan aktif mengeluarkan serangan plasma listrik (tidak mengkonsumsi, mengembalikan kemarahan tetapi mengurangi kecepatan pemulihan kemarahan sendiri sebesar 50%), jumlah serangan meningkat satu dan pasti mengenai sasaran.',
		starEffectDesc_ph = 'Pakawalan pagkatapos kung may <Ilusyon ng Kidlat>, pagkatapos ay pagsamahin ito sa Ilusyon ng Kidlat upang maging <Avatar ng Kidlat> sa loob ng 2 na round. Avatar ng Kidlat: nagdaragdag ng 80% ng kasalukuyang katangian ng Ilusyon ng Kidlat, at tumataas ng 50% ang pag-iwas. Bawat aktibong atake ay naglalabas ng plasma electric strike (hindi kumokonsumo, nagpapagaling ng galit ngunit binabawasan ang bilis ng pagbawi ng sarili ng galit ng 50%), tumataas ang bilang ng atake ng isa at tiyak na tumatama.',
		starEffectDesc_ma = 'Lepaskan selepas jika <Ilusi Guruh> wujud, kemudian gabungkan dengan Ilusi Guruh menjadi <Avatar Guruh> dalam 2 pusingan. Avatar Guruh: menambah 80% atribut semasa Ilusi Guruh, dan meningkatkan elakan sebanyak 50%. Setiap serangan aktif menghasilkan serangan plasma elektrik (tidak menggunakan tenaga, memulihkan kemarahan tetapi mengurangkan kelajuan pemulihan kemarahan sendiri sebanyak 50%), jumlah serangan meningkat satu dan dijamin tepat sasaran.',
