	[41712] = {
		id = 41712,
		skillName_vn = 'Đòn tấn công kim loại',
		skillName_en = 'Metal attack',
		skillName_th = 'การโจมตีโลหะ',
		skillName_in = 'Serangan logam',
		skillName_ph = 'Metal na pag-atake',
		skillName_ma = 'Serangan logam',
		skillName = 'Metal attack',
		describe_vn = 'Melmetal bắn sóng xung kích kim loại tấn công mục tiêu đơn lẻ của kẻ địch, gây ra #C0xE69900#170% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, bản thân chắc chắn chống đỡ đòn tấn công chủ động trong lượt tiếp theo, và áp dụng trạng thái [Hộ vệ sắt] lên mục tiêu phía sau bản thân trong 2 lượt\n#F10# \n#F40##L10#[Hộ vệ sắt]#L0# hiệu ứng tăng cường đặc biệt, mục tiêu nhận được tỷ lệ chống đỡ và cường độ chống đỡ giống với thuộc tính hiện tại của Melmetal, khi chống đỡ thành công sẽ kích hoạt hiệu ứng phản công cứng hóa của Melmetal',
		describe_en = 'Melmetal fires a metal shockwave to attack a single enemy target, dealing #C0xE69900#170% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Melmetal guarantees to block the next active attack on the next turn and applies the [Iron Guard] status to the target behind itself for 2 turns. [Iron Guard] is a special enhancement effect that grants the target the block rate and block strength equal to Melmetal’s current attributes. Upon a successful block, Melmetal’s hardening counterattack effect is triggered.',
		describe_th = 'เมลเมทัลยิงคลื่นช็อกโลหะโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายทางกายภาพ #C0xE69900#170% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เมลเมทัลมั่นใจว่าจะทนทานต่อการโจมตีเชิงรุกในรอบถัดไป และมอบสถานะ [เหล็กป้องกัน] ให้กับเป้าหมายด้านหลังตัวเองเป็นเวลา 2 เทิร์น [เหล็กป้องกัน] เป็นเอฟเฟกต์เสริมพิเศษ โดยเป้าหมายจะได้รับอัตราการทนทานและความแรงของการทนทานเท่ากับคุณสมบัติปัจจุบันของเมลเมทัล เมื่อทนทานสำเร็จจะเปิดใช้งานเอฟเฟกต์ตอบโต้แข็งตัวของเมลเมทัล',
		describe_in = 'Melmetal menembakkan gelombang kejut logam untuk menyerang satu target musuh, menyebabkan #C0xE69900#170% Serangan Fisik#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Melmetal dijamin menahan serangan aktif berikutnya pada putaran berikutnya, dan menerapkan status [Penjaga Besi] pada target di belakang dirinya selama 2 giliran. [Penjaga Besi] adalah efek peningkatan khusus, target menerima tingkat dan kekuatan penahanan yang sama dengan atribut Melmetal saat ini, saat berhasil menahan serangan akan memicu efek serangan balik pengerasan Melmetal.',
		describe_ph = 'Si Melmetal ay nagpapaputok ng metal shockwave upang atakihin ang iisang target ng kaaway, nagdudulot ng #C0xE69900#170% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Tinitiyak ni Melmetal ang pagharang sa susunod na aktibong pag-atake sa susunod na turn, at naglalapat ng estado na [Iron Guard] sa target sa likod niya sa loob ng 2 turn. Ang [Iron Guard] ay isang espesyal na enhancement effect, kung saan ang target ay tumatanggap ng block rate at block strength na katulad ng kasalukuyang attributes ng Melmetal. Kapag nagtagumpay sa blocking, na-trigger ang hardening counterattack effect ng Melmetal.',
		describe_ma = 'Melmetal melepaskan gelombang kejutan logam untuk menyerang satu sasaran musuh, menyebabkan #C0xE69900#170% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Melmetal pasti akan menangkis serangan aktif seterusnya pada giliran berikutnya, dan mengenakan status [Penjaga Besi] pada sasaran di belakang dirinya selama 2 giliran. [Penjaga Besi] adalah kesan peningkatan khas, sasaran menerima kadar dan kekuatan penangkisan yang sama dengan atribut semasa Melmetal, apabila penangkisan berjaya akan mengaktifkan kesan serangan balas pengerasan Melmetal.',
		describe = 'Melmetal fires a metal shockwave to attack a single enemy target, dealing #C0xE69900#170% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Melmetal guarantees to block the next active attack on the next turn and applies the [Iron Guard] status to the target behind itself for 2 turns. [Iron Guard] is a special enhancement effect that grants the target the block rate and block strength equal to Melmetal’s current attributes. Upon a successful block, Melmetal’s hardening counterattack effect is triggered.',
		upLvDesc = 'Fixed damage +144',
