	[41713] = {
		id = 41713,
		skillName_vn = 'Đòn nặng thép',
		skillName_en = 'Heavy steel strike',
		skillName_th = 'การโจมตีเหล็กหนัก',
		skillName_in = 'Serangan baja berat',
		skillName_ph = 'Mabigat na suntok ng bakal',
		skillName_ma = 'Serangan keluli berat',
		skillName = 'Heavy steel strike',
		describe_vn = 'Meltan dùng nắm đấm sắt đập mạnh xuống đất, tấn công ngẫu nhiên một mục tiêu địch ở hàng trước và hàng sau, lần lượt gây ra #C0xE69900#320% đòn Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ và #C0xF13B54#Sát Thương Vật Lý#C0x5B. 545B#, gây ra [Phân rã áo giáp] cho các mục tiêu ở hàng trước và [Thu gọn cánh tay] cho các mục tiêu ở hàng sau. Nếu chỉ có một mục tiêu, cả hai hiệu ứng sẽ được thêm vào mục tiêu đó cùng một lúc. Ở vòng tiếp theo, lượng máu chuyển đổi từ kim loại lỏng sẽ tăng lên 40% và hiệu ứng phản đòn cứng sẽ được kích hoạt miễn là nó bị tấn công\n#F10# \n#F40##L10#[Sự phân hủy áo giáp]#L0#Hiệu ứng tiêu cực đặc biệt, không thể giải trừ, tăng thêm 20% khả năng bị tổn thương và giảm 30% tỷ lệ kháng cự, kéo dài trong 2 hiệp\n#F10# \n#F40##L10#[Áo giáp Phân rã]#L0#Hiệu ứng tiêu cực đặc biệt, không thể xua tan, giảm 30% sát thương cộng thêm và 30% tỷ lệ chí mạng, tồn tại trong 2 hiệp',
		describe_en = 'Meltan uses an iron fist to strike the ground forcefully, randomly attacking one enemy target in the front row and one in the back row, dealing #C0xE69900#320% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ and #C0xF13B54#Physical Damage#C0x5B545B# respectively. It causes [Armor Decomposition] to targets in the front row and [Arm Retraction] to targets in the back row. If there is only one target, both effects will be applied to that target simultaneously. In the next round, the health converted from liquid metal will increase by 40% and a hard counterattack effect will be triggered as long as it is attacked. \n#F10# \n#F40##L10#[Armor Decomposition]#L0# A special negative effect that cannot be dispelled, increasing damage taken by 20% and reducing resistance rate by 30%, lasting 2 turns. \n#F10# \n#F40##L10#[Armor Decay]#L0# A special negative effect that cannot be removed, reducing additional damage by 30% and critical hit rate by 30%, lasting 2 turns.',
		describe_th = 'Meltan ใช้กำปั้นเหล็กทุบลงที่พื้นอย่างแรง โจมตีศัตรูสุ่มหนึ่งตัวในแถวหน้าและหนึ่งตัวในแถวหลัง สร้าง #C0xE69900#320% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ และ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ตามลำดับ พร้อมทั้งก่อให้เกิด [การสลายเกราะ] กับเป้าหมายในแถวหน้า และ [การหุบแขน] กับเป้าหมายในแถวหลัง หากมีเป้าหมายเพียงอันเดียว ทั้งสองเอฟเฟกต์จะถูกเพิ่มพร้อมกันที่เป้าหมายนั้น ในรอบถัดไป พลังชีวิตที่แปลงมาจากโลหะเหลวมจะเพิ่มขึ้น 40% และจะมีเอฟเฟกต์สกัดการโจมตีแบบเหนียวแน่นเมื่อต้องถูกโจมตี \n#F10# \n#F40##L10#[การสลายเกราะ]#L0# เอฟเฟกต์ลบพิเศษ ไม่สามารถลบได้ เพิ่มโอกาสถูกโจมตี 20% และลดอัตราต้านทาน 30% เป็นเวลา 2 รอบ \n#F10# \n#F40##L10#[เกราะสลาย]#L0# เอฟเฟกต์ลบพิเศษ ไม่สามารถขจัดได้ ลดความเสียหายเพิ่มเติม 30% และอัตราคริติคอล 30% คงอยู่ 2 รอบ',
		describe_in = 'Meltan menggunakan kepalan tangan besi untuk memukul tanah dengan keras, menyerang secara acak satu target musuh di baris depan dan satu di baris belakang, masing-masing memberikan #C0xE69900#320% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ dan #C0xF13B54#Serangan Fisik#C0x5B545B#. Memberikan [Penguraian Zirah] kepada target di baris depan dan [Penyerapan Lengan] kepada target di baris belakang. Jika hanya ada satu target, kedua efek akan diterapkan pada target tersebut secara bersamaan. Pada giliran berikutnya, jumlah darah yang dikonversi dari logam cair akan meningkat 40% dan efek serangan balik keras akan aktif asalkan diserang. \n#F10# \n#F40##L10#[Penguraian Zirah]#L0# Efek negatif khusus, tidak bisa dihilangkan, meningkatkan 20% kerentanan, dan mengurangi 30% resistensi, berlangsung selama 2 giliran. \n#F10# \n#F40##L10#[Pembusukan Zirah]#L0# Efek negatif khusus, tidak bisa dihapus, mengurangi 30% kerusakan tambahan dan 30% peluang serangan kritis, bertahan selama 2 giliran.',
		describe_ph = 'Gumagamit si Meltan ng bakal na kamao upang malakas na hampasin ang lupa, random na inaatake ang isang kalaban sa front row at isang kalaban sa back row, na nagdudulot ng #C0xE69900#320% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ at #C0xF13B54#Physical Damage#C0x5B545B# ayon sa pagkakasunod. Nagdudulot ng [Pagkabulok ng Baluti] sa mga target sa harapang linya at [Pag-urong ng Braso] sa mga target sa likurang linya. Kung iisa lamang ang target, pareho ang mga epekto na idaragdag sa target sabay-sabay. Sa susunod na round, ang health na na-convert mula sa liquid metal ay tataas ng 40% at ang hard counterattack effect ay mae-activate hangga\'t ito ay inaatake. \n#F10# \n#F40##L10#[Pagkabulok ng Baluti]#L0# Espesyal na negatibong epekto, hindi maaaring alisin, nagpapataas ng 20% kakayahang masaktan at nagpapababa ng 30% resistensya, tumatagal ng 2 turn. \n#F10# \n#F40##L10#[Pagkakabulok ng Baluti]#L0# Espesyal na negatibong epekto, hindi maaaring matanggal, nagpapababa ng 30% dagdag na pinsala at 30% crit rate, tumatagal ng 2 turn.',
		describe_ma = 'Meltan menggunakan kepalan tangan besi untuk memukul tanah dengan kuat, menyerang secara rawak satu sasaran musuh di barisan hadapan dan satu di barisan belakang, masing-masing menyebabkan #C0xE69900#320% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ dan #C0xF13B54#Serangan Fizikal#C0x5B545B#. Memberi [Penguraian Perisai] kepada sasaran di barisan hadapan dan [Pengetatan Lengan] kepada sasaran di barisan belakang. Jika hanya ada satu sasaran, kedua kesan akan ditambah pada sasaran tersebut serentak. Pada pusingan seterusnya, jumlah kesihatan yang ditukar dari logam cair akan meningkat sebanyak 40% dan kesan serangan balas keras akan diaktifkan selagi ia diserang. \n#F10# \n#F40##L10#[Penguraian Perisai]#L0# Kesan negatif khas, tidak boleh dibuang, menambah 20% kebolehan menerima kerosakan dan mengurangkan 30% kadar rintangan, bertahan selama 2 pusingan. \n#F10# \n#F40##L10#[Penguraian Perisai]#L0# Kesan negatif khas, tidak boleh dihapuskan, mengurangkan 30% kerosakan tambahan dan 30% kadar kritikal, wujud selama 2 pusingan.',
		describe = 'Meltan uses an iron fist to strike the ground forcefully, randomly attacking one enemy target in the front row and one in the back row, dealing #C0xE69900#320% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ and #C0xF13B54#Physical Damage#C0x5B545B# respectively. It causes [Armor Decomposition] to targets in the front row and [Arm Retraction] to targets in the back row. If there is only one target, both effects will be applied to that target simultaneously. In the next round, the health converted from liquid metal will increase by 40% and a hard counterattack effect will be triggered as long as it is attacked. \n#F10# \n#F40##L10#[Armor Decomposition]#L0# A special negative effect that cannot be dispelled, increasing damage taken by 20% and reducing resistance rate by 30%, lasting 2 turns. \n#F10# \n#F40##L10#[Armor Decay]#L0# A special negative effect that cannot be removed, reducing additional damage by 30% and critical hit rate by 30%, lasting 2 turns.',
		simDesc_vn = 'Mê Lục Tán sử dụng nắm đấm thép mạnh mẽ đập xuống mặt đất, tấn công ngẫu nhiên một mục tiêu kẻ thù ở hàng trước và hàng sau.',
		simDesc_en = 'Mê Lục Tán uses a powerful iron fist to strike the ground, randomly attacking an enemy target in both the front and back rows.',
		simDesc_th = 'เมหลู่ตันใช้หมัดเหล็กทรงพลังทุบลงที่พื้น โจมตีเป้าหมายศัตรูแบบสุ่มทั้งในแถวหน้าและแถวหลัง',
		simDesc_in = 'Mê Lục Tán menggunakan kepalan besi yang kuat untuk memukul tanah, menyerang secara acak satu target musuh di baris depan dan belakang.',
		simDesc_ph = 'Gumagamit si Mê Lục Tán ng malakas na bakal na kamao para hampasin ang lupa, na randomly na inaatake ang isang target na kalaban sa harap at likod na hanay.',
		simDesc_ma = 'Mê Lục Tán menggunakan kepalan besi yang kuat untuk memukul tanah, menyerang secara rawak satu sasaran musuh di barisan hadapan dan belakang.',
		simDesc = 'Mê Lục Tán uses a powerful iron fist to strike the ground, randomly attacking an enemy target in both the front and back rows.',
		starEffect = __data_t__starEffect[41713],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng Tăng Cường: Hiệu ứng <Phá Giáp> và <Vũ Khí Sụp Đổ> sẽ lần lượt thêm vào 2 mục tiêu ở hàng trước và hàng sau.',
		starEffectDesc = 'Enhancement Effect: The <Armor Break> and <Weapon Collapse> effects will respectively add to 2 targets in the front and back rows.',
		starEffectDesc_en = 'Enhancement Effect: The <Armor Break> and <Weapon Collapse> effects will respectively add to 2 targets in the front and back rows.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เอฟเฟกต์ <Phá Giáp> และ <Vũ Khí Sụp Đổ> จะถูกเพิ่มไปยังเป้าหมาย 2 ตัวในแถวหน้าและแถวหลังตามลำดับ',
