	[41722] = {
		id = 41722,
		skillName_vn = 'Sóng điện từ',
		skillName_en = 'Electromagnetic waves',
		skillName_th = 'คลื่นแม่เหล็กไฟฟ้า',
		skillName_in = 'Gelombang elektromagnetik',
		skillName_ph = 'Mga alon ng electromagnet',
		skillName_ma = 'Gelombang elektromagnet',
		skillName = 'Electromagnetic waves',
		describe_vn = 'Melmetal bắn sóng điện từ kim loại tấn công mục tiêu đơn địch, gây #C0xE69900#180% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, bản thân chắc chắn chống đỡ đòn tấn công chủ động trong lượt tiếp theo, và áp dụng trạng thái [Hộ Vệ Sắt] lên mục tiêu phía sau bản thân trong 2 lượt\n#F10# \n#F40##L10#[Hộ Vệ Sắt]#L0# hiệu ứng tăng cường đặc biệt, mục tiêu nhận được tỷ lệ chống đỡ và cường độ chống đỡ giống với thuộc tính hiện tại của Melmetal, khi chống đỡ thành công sẽ kích hoạt hiệu ứng phản công cứng hóa của Melmetal',
		describe_en = 'Melmetal fires a metal electromagnetic wave to attack a single enemy target, dealing #C0xE69900#180% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Melmetal guarantees to guard against the next active attack on the following turn and applies the [Iron Guard] status to the target behind itself for 2 turns. [Iron Guard] is a special enhancement effect; the target gains the guard rate and guard intensity equal to Melmetal\'s current attributes. Upon a successful guard, Melmetal activates a hard counterattack effect.',
		describe_th = 'เมลเมทัลยิงคลื่นแม่เหล็กไฟฟ้าจากโลหะโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0xE69900#180% การโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เมลเมทัลรับประกันการป้องกันการโจมตีเชิงรุกในเทราที่จะมาถึง และใช้สถานะ [ป้องกันเหล็ก] บนเป้าหมายที่อยู่ด้านหลังตัวเองเป็นเวลา 2 เทิร์น [ป้องกันเหล็ก] เป็นเอฟเฟกต์เสริมพิเศษ เป้าหมายจะได้รับอัตราการป้องกันและความรุนแรงของการป้องกันเท่ากับสถานะปัจจุบันของเมลเมทัล เมื่อป้องกันสำเร็จจะเปิดใช้งานเอฟเฟกต์ตอบโต้แข็งแกร่งของเมลเมทัล',
		describe_in = 'Melmetal menembakkan gelombang elektromagnetik logam untuk menyerang satu target musuh, memberikan #C0xE69900#180% Serangan Fisik#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Melmetal pasti akan bertahan dari serangan aktif berikutnya pada giliran berikutnya dan menerapkan status [Perisai Besi] pada target di belakangnya selama 2 giliran. [Perisai Besi] adalah efek peningkatan khusus, target menerima tingkat penjagaan dan intensitas penjagaan yang sama dengan atribut Melmetal saat ini. Ketika berhasil bertahan, efek serangan balik keras Melmetal akan diaktifkan.',
		describe_ph = 'Pinaputok ni Melmetal ang metallic electromagnetic wave para atakehin ang isang kalaban, na nagdudulot ng #C0xE69900#180% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Tinitiyak ni Melmetal ang pagdepensa laban sa susunod na aktibong atake sa susunod na turn, at inilalapat ang status na [Iron Guard] sa target sa likod nito sa loob ng 2 turn. Ang [Iron Guard] ay isang espesyal na enhancement effect; tinatanggap ng target ang guard rate at guard intensity na kapareho ng kasalukuyang attributes ni Melmetal. Kapag matagumpay na na-guard, ni-activate ni Melmetal ang hard counterattack effect.',
		describe_ma = 'Melmetal menembak gelombang elektromagnetik logam untuk menyerang sasaran musuh tunggal, memberikan #C0xE69900#180% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Melmetal pastikan menghalang serangan aktif pada giliran berikutnya dan meletakkan status [Perisai Besi] pada sasaran di belakangnya selama 2 giliran. [Perisai Besi] adalah kesan pengukuhan khas, sasaran menerima kadar pertahanan dan intensiti pertahanan sama seperti atribut Melmetal sekarang. Apabila pertahanan berjaya, kesan serangan balas keras Melmetal diaktifkan.',
		describe = 'Melmetal fires a metal electromagnetic wave to attack a single enemy target, dealing #C0xE69900#180% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Melmetal guarantees to guard against the next active attack on the following turn and applies the [Iron Guard] status to the target behind itself for 2 turns. [Iron Guard] is a special enhancement effect; the target gains the guard rate and guard intensity equal to Melmetal\'s current attributes. Upon a successful guard, Melmetal activates a hard counterattack effect.',
		upLvDesc = 'Fixed damage +144',
		upLvDesc_en = 'Fixed damage +144',
