	[41726] = {
		id = 41726,
		skillName_vn = 'Kim loại lỏng',
		skillName_en = 'Liquid metal',
		skillName_th = 'โลหะของเหลว',
		skillName_in = 'Logam cair',
		skillName_ph = 'Likidong metal',
		skillName_ma = 'Logam cecair',
		skillName = 'Liquid metal',
		describe_vn = '#L10# Kim loại lỏng: #L0# Mỗi lần bạn bị đánh, nó sẽ hấp thụ 20% sát thương trúng đòn và chuyển thành lượng máu tương đương, đồng thời tăng 20% ​​tỷ lệ kháng cự và sức kháng cự của bản thân trong 1 hiệp. Bất cứ khi nào kháng cự được kích hoạt thành công, nó sẽ kích hoạt hiệu ứng [tăng cường phản đòn] (tăng vĩnh viễn phòng thủ vật lý cơ bản của bạn thêm 10% (có thể cộng dồn 10 lần) và phản công kẻ tấn công, sát thương là sát thương thực sự của 300% phòng thủ vật lý)\n#F10# \n#F40##L10# Bất kể sự an toàn của bản thân: #L0# Khi anh hùng của chính mình bị sát thương bởi một đòn tấn công chủ động vượt quá 80% mức hiện tại mạng sống, thay vào đó Meilu Meta sẽ chịu thiệt hại trong đòn tấn công này; khi bản thân Meilu Meta bị trúng một đòn chí mạng, nó sẽ miễn nhiễm với sát thương của đòn chí mạng này. Sau khi bất kỳ hiệu ứng nào ở trên được kích hoạt, bất kể sự an toàn của bản thân, Meilu Meta sẽ bước vào thời gian hồi chiêu 2 hiệp\n#F10# \n#F40##L10#Rust: #L0#Khi Melumeta chết, nó sẽ rỉ sét và phân hủy thành Meltan. Meltan kế thừa tất cả các thuộc tính ban đầu của Melumeta#C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# (làm mới nội tại và đặt lại thời gian hồi chiêu kỹ năng nhỏ)',
		describe_en = '#L10# Liquid Metal: #L0# Each time you are hit, it absorbs 20% of the damage taken and converts it into equivalent health, while increasing your resistance rate and resistance power by 20% ​​during one turn. Whenever resistance is successfully activated, it triggers the [Counterattack Enhancement] effect (permanently increases your basic physical defense by 10% (stackable up to 10 times) and counterattacks the attacker, dealing true damage equal to 300% of physical defense) \n#F10# \n#F40##L10# Regardless of Self-Preservation: #L0# When your hero takes damage from an active attack exceeding 80% of current HP, Meilu Meta will take the damage instead; when Meilu Meta is hit by a critical strike, it becomes immune to that critical damage. After any of the above effects are triggered, regardless of self-preservation, Meilu Meta will enter a 2-turn cooldown \n#F10# \n#F40##L10# Rust: #L0# When Melumeta dies, it rusts and decomposes into Meltan. Meltan inherits all original attributes of Melumeta #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# (refreshes passives and resets small skill cooldown)',
		describe_th = '#L10# โลหะเหลว: #L0# ทุกครั้งที่คุณถูกโจมตี มันจะดูดซับความเสียหายได้ 20% ของดาเมจที่โดนและเปลี่ยนเป็นเลือดเทียบเท่า พร้อมทั้งเพิ่มอัตราการต้านทานและพลังต้านทานของตัวเองขึ้นอีก 20% เป็นเวลา 1 เทิร์น ทุกครั้งที่ต้านทานสำเร็จ จะเปิดใช้เอฟเฟกต์ [เพิ่มพลังตอบโต้] (เพิ่มการป้องกันกายภาพพื้นฐานของคุณถาวรขึ้น 10% (ทับซ้อนได้สูงสุด 10 ครั้ง) และตอบโต้ผู้โจมตีด้วยความเสียหายจริงเท่ากับ 300% ของการป้องกันกายภาพ) \n#F10# \n#F40##L10# ไม่ว่าสภาพตัวเองจะเป็นอย่างไร: #L0# เมื่อฮีโร่ของคุณถูกโจมตีครั้งแรงเกิน 80% ของพลังชีวิตปัจจุบัน เมลูเมตาจะได้รับความเสียหายแทน; เมื่อเมลูเมตาถูกโจมตีด้วยคริทิคัล จะได้รับภูมิคุ้มกันต่อดาเมจคริทิคัลครั้งนั้น หลังจากเอฟเฟกต์ใด ๆ ข้างต้นถูกเปิดใช้ เมลูเมตาจะเข้าสู่สถานะคูลดาวน์ 2 เทิร์น \n#F10# \n#F40##L10# สนิม: #L0# เมื่อเมลูเมตาตาย มันจะขึ้นสนิมและสลายกลายเป็นเมลแทน เมลแทนจะสืบทอดคุณสมบัติเดิมทั้งหมดของเมลูเมตา #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# (รีเฟรชสกิลติดตัวและรีเซ็ตคูลดาวน์สกิลเล็ก)',
		describe_in = '#L10# Logam Cair: #L0# Setiap kali kamu terkena serangan, ia menyerap 20% dari damage yang diterima dan mengubahnya menjadi darah yang setara, sekaligus meningkatkan tingkat resistensi dan kekuatan resistensimu sebesar 20% selama 1 giliran. Setiap kali resistensi berhasil diaktifkan, efek [Peningkatan Serangan Balik] akan aktif (meningkatkan pertahanan fisik dasar kamu secara permanen sebesar 10% (dapat ditumpuk hingga 10 kali) dan membalas menyerang penyerang dengan damage nyata sebesar 300% pertahanan fisik) \n#F10# \n#F40##L10# Terlepas dari Keselamatan Diri: #L0# Ketika pahlawanmu terkena serangan aktif yang melebihi 80% dari HP saat ini, Meilu Meta akan menerima damage tersebut sebagai gantinya; saat Meilu Meta terkena serangan kritis, ia kebal terhadap damage kritis tersebut. Setelah efek di atas diaktifkan, Meilu Meta akan memasuki cooldown selama 2 giliran terlepas dari keselamatan diri \n#F10# \n#F40##L10# Karat: #L0# Saat Melumeta mati, ia akan berkarat dan terurai menjadi Meltan. Meltan mewarisi semua atribut asli Melumeta #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# (merefresh pasif dan mereset cooldown skill kecil)',
		describe_ph = '#L10# Likidong Metal: #L0# Sa bawat beses na ikaw ay tamaan, sumisipsip ito ng 20% ng natanggap na pinsala at ginagawang katumbas na buhay, kasabay ng pagtaas ng iyong rate ng pagtitiis at lakas ng pagtitiis ng 20% ​​sa loob ng isang turn. Sa tuwing matagumpay na na-activate ang pagtitiis, nagti-trigger ito ng epekto na [Pinalakas na Pagsalakay] (pinalalakas nang permanente ang iyong pangunahing pisikal na depensa ng 10% (pwedeng i-stack hanggang 10 beses) at sumusukli laban sa umaatake, na may totoong pinsala na katumbas ng 300% ng pisikal na depensa) \n#F10# \n#F40##L10# Hindi Alintana ang Sariling Kaligtasan: #L0# Kapag ang iyong bayani ay nasaktan ng isang aktibong atake na lumalampas sa 80% ng kasalukuyang HP, sa halip ay si Meilu Meta ang tatanggap ng pinsalang iyon; kapag tinamaan si Meilu Meta ng kritikal na tama, ito ay nagiging immune sa kritikal na pinsalang iyon. Pagkatapos ma-activate ang alinman sa mga epektong nabanggit, hindi alintana ang sariling kaligtasan, papasok si Meilu Meta sa cooldown na 2 turn \n#F10# \n#F40##L10# Kalawang: #L0# Kapag namatay si Melumeta, ito ay kalawangin at magde-decompose sa Meltan. Ang Meltan ay namamana ang lahat ng orihinal na katangian ni Melumeta #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# (ni-rerefresh ang passive at nire-reset ang cooldown ng maliit na skills)',
		describe_ma = '#L10# Logam Cecair: #L0# Setiap kali anda terkena serangan, ia akan menyerap 20% kerosakan yang diterima dan menukarnya menjadi darah yang setara, sambil meningkatkan kadar ketahanan dan kuasa ketahanan diri anda sebanyak 20% selama 1 pusingan. Setiap kali ketahanan berjaya diaktifkan, ia akan mencetuskan kesan [Pengukuhan Serangan Balas] (meningkatkan pertahanan fizikal asas anda secara kekal sebanyak 10% (boleh bertindih sehingga 10 kali) dan menyerang balas penyerang, kerosakan sebenar sebanyak 300% pertahanan fizikal) \n#F10# \n#F40##L10# Tanpa Mengira Keselamatan Diri: #L0# Apabila wira anda menerima kerosakan daripada serangan aktif melebihi 80% daripada tahap HP semasa, Meilu Meta akan menerima kerosakan tersebut sebagai ganti; apabila Meilu Meta terkena serangan kritikal, ia menjadi kebal kepada kerosakan kritikal tersebut. Selepas mana-mana kesan di atas diaktifkan, tanpa mengira keselamatan diri, Meilu Meta akan memasuki masa sejuk selama 2 pusingan \n#F10# \n#F40##L10# Karat: #L0# Apabila Melumeta mati, ia akan berkarat dan terurai menjadi Meltan. Meltan mewarisi semua atribut asal Melumeta #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# (menyegarkan pasif dan menetapkan semula masa sejuk kemahiran kecil)',
		describe = '#L10# Liquid Metal: #L0# Each time you are hit, it absorbs 20% of the damage taken and converts it into equivalent health, while increasing your resistance rate and resistance power by 20% ​​during one turn. Whenever resistance is successfully activated, it triggers the [Counterattack Enhancement] effect (permanently increases your basic physical defense by 10% (stackable up to 10 times) and counterattacks the attacker, dealing true damage equal to 300% of physical defense) \n#F10# \n#F40##L10# Regardless of Self-Preservation: #L0# When your hero takes damage from an active attack exceeding 80% of current HP, Meilu Meta will take the damage instead; when Meilu Meta is hit by a critical strike, it becomes immune to that critical damage. After any of the above effects are triggered, regardless of self-preservation, Meilu Meta will enter a 2-turn cooldown \n#F10# \n#F40##L10# Rust: #L0# When Melumeta dies, it rusts and decomposes into Meltan. Meltan inherits all original attributes of Melumeta #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# (refreshes passives and resets small skill cooldown)',
		starEffect = __data_t__starEffect[41726],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Bổ Sung: Sát thương của kỹ năng hợp tác và phản công của các anh hùng thuộc hệ Cơ Giới tăng 30%; khi vào trận hoặc chắn sát thương cho đồng đội, sẽ thêm <Khiên Thép> cho các anh hùng thuộc hệ Cơ Giới (lượng khiên tương đương 500% phòng thủ vật lý của Melometa). Nếu có 3 anh hùng thuộc hệ Thép trở lên, toàn bộ đồng đội sẽ nhận được <Khiên Thép>.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
