	},
	[41741] = {
		id = 41741,
		skillName_vn = 'Đấm triệu tấn',
		skillName_en = 'Punch a million tons',
		skillName_th = 'ชกน้ำหนักล้านตัน',
		skillName_in = 'Pukul jutaan ton',
		skillName_ph = 'Tumbok ng milyong tonelada',
		skillName_ma = 'Pukul sejuta tan',
		skillName = 'Punch a million tons',
		describe_vn = 'Melmetal tấn công mục tiêu đơn địch bằng cú đấm mạnh mẽ, gây #C0xE69900#100% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, tăng 40% phòng thủ vật lý và 20% tỷ lệ chống đỡ của bản thân, không thể cộng dồn, kéo dài 2 lượt',
		describe_en = 'Melmetal attacks a single enemy target with a powerful punch, dealing #C0xE69900#100% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#. It also increases its own physical defense by 40% and block rate by 20%, cannot be stacked, lasting 2 turns.',
		describe_th = 'เมลเมทัลโจมตีเป้าหมายศัตรูเดี่ยวด้วยหมัดอันทรงพลัง สร้างความเสียหาย #C0xE69900#100% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มการป้องกันทางกายภาพของตนเอง 40% และอัตราการบล็อก 20% ไม่สามารถซ้อนทับได้ มีผลต่อเนื่อง 2 เทิร์น',
		describe_in = 'Melmetal menyerang satu target musuh dengan pukulan kuat, memberikan #C0xE69900#100% Serangan Fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, meningkatkan pertahanan fisik diri sendiri sebesar 40% dan tingkat blok sebesar 20%, tidak dapat ditumpuk, berlangsung selama 2 giliran.',
		describe_ph = 'Inaatake ng Melmetal ang isang target na kaaway gamit ang malakas na suntok, na nagdudulot ng #C0xE69900#100% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, nagpapataas ng sarili nitong pisikal na depensa ng 40% at porsyento ng bloke ng 20%, hindi maaaring i-stack, tumatagal ng 2 na turn.',
		describe_ma = 'Melmetal menyerang sasaran musuh tunggal dengan pukulan yang kuat, memberikan #C0xE69900#100% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, meningkatkan pertahanan fizikal sendiri sebanyak 40% dan kadar blok sebanyak 20%, tidak boleh bertindih, berlangsung selama 2 pusingan.',
		describe = 'Melmetal attacks a single enemy target with a powerful punch, dealing #C0xE69900#100% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#. It also increases its own physical defense by 40% and block rate by 20%, cannot be stacked, lasting 2 turns.',
		upLvDesc = 'Fixed damage +96',
		upLvDesc_en = 'Fixed damage +96',
		upLvDesc_th = 'ความเสียหายคงที่ +96',
