	[41742] = {
		id = 41742,
		skillName_vn = 'Sóng điện từ',
		skillName_en = 'Electromagnetic waves',
		skillName_th = 'คลื่นแม่เหล็กไฟฟ้า',
		skillName_in = 'Gelombang elektromagnetik',
		skillName_ph = 'Mga alon ng electromagnet',
		skillName_ma = 'Gelombang elektromagnet',
		skillName = 'Electromagnetic waves',
		describe_vn = 'Melmetal bắn sóng điện từ kim loại tấn công mục tiêu đơn địch, gây #C0xE69900#180% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, bản thân chắc chắn chống đỡ đòn tấn công chủ động trong lượt tiếp theo, và áp dụng trạng thái [Hộ Vệ Sắt] lên mục tiêu phía sau bản thân trong 2 lượt\n#F10# \n#F40##L10#[Hộ Vệ Sắt]#L0# hiệu ứng tăng cường đặc biệt, mục tiêu nhận được tỷ lệ chống đỡ và cường độ chống đỡ giống với thuộc tính hiện tại của Melmetal, khi chống đỡ thành công sẽ kích hoạt hiệu ứng phản công cứng hóa của Melmetal',
		describe_en = 'Melmetal fires a metal electromagnetic wave to attack a single enemy target, dealing #C0xE69900#180% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Melmetal guarantees to block an active attack in the next turn and applies the [Iron Guard] status to the ally behind itself for 2 turns. The [Iron Guard] effect enhances the target\'s block rate and block strength to match Melmetal\'s current attributes. Upon a successful block, Melmetal\'s hardening counterattack effect is triggered.',
		describe_th = 'เมลเมทัลยิงคลื่นแม่เหล็กไฟฟ้าจากโลหะโจมตียูนิตศัตรูเดี่ยว สร้างความเสียหาย #C0xE69900#180% การโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เมลเมทัลรับประกันการป้องกันการโจมตีแบบแอคทีฟในเทรินถัดไป และมอบสถานะ [Iron Guard] ให้กับเป้าหมายที่อยู่ด้านหลังเป็นเวลา 2 เทิร์น เอฟเฟ็กต์ [Iron Guard] เพิ่มอัตราการป้องกันและความแข็งแกร่งของการป้องกันตามสถานะปัจจุบันของเมลเมทัล เมื่อป้องกันสำเร็จจะทำให้เกิดเอฟเฟ็กต์โจมตีตอบโต้ฮาร์ดเท็นเนสของเมลเมทัล',
		describe_in = 'Melmetal melepaskan gelombang elektromagnetik dari logam untuk menyerang musuh tunggal, memberikan #C0xE69900#180% Serangan Fisik#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Melmetal dipastikan dapat menahan serangan aktif di giliran berikutnya dan menerapkan status [Iron Guard] pada target di belakangnya selama 2 giliran. Efek [Iron Guard] meningkatkan tingkat dan kekuatan penahanan target sesuai dengan atribut Melmetal saat ini. Saat berhasil menahan serangan, efek serangan balik pengerasan Melmetal akan aktif.',
		describe_ph = 'Pinaputok ni Melmetal ang metal electromagnetic wave para atakihin ang isang target na kalaban, na nagdudulot ng #C0xE69900#180% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Tinitiyak ni Melmetal ang pag-block ng active attack sa susunod na turn, at naglalagay ng status na [Iron Guard] sa target sa likod niya ng 2 turns. Ang epekto ng [Iron Guard] ay nagpapataas ng block rate at block strength ng target base sa kasalukuyang attributes ni Melmetal. Kapag matagumpay na na-block, magta-trigger ang hardening counterattack effect ni Melmetal.',
		describe_ma = 'Melmetal menembak gelombang elektromagnetik logam untuk menyerang satu sasaran musuh, menyebabkan #C0xE69900#180% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Melmetal pasti dapat mengelak serangan aktif pada giliran seterusnya, dan mengenakan status [Iron Guard] ke sasaran di belakang dirinya selama 2 giliran. Kesan [Iron Guard] meningkatkan kadar elakan dan kekuatan elakan sasaran mengikut atribut semasa Melmetal. Apabila elakan berjaya, kesan serangan balas pengerasan Melmetal akan diaktifkan.',
		describe = 'Melmetal fires a metal electromagnetic wave to attack a single enemy target, dealing #C0xE69900#180% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Melmetal guarantees to block an active attack in the next turn and applies the [Iron Guard] status to the ally behind itself for 2 turns. The [Iron Guard] effect enhances the target\'s block rate and block strength to match Melmetal\'s current attributes. Upon a successful block, Melmetal\'s hardening counterattack effect is triggered.',
		upLvDesc = 'Fixed damage +144',
		upLvDesc_en = 'Fixed damage +144',
		upLvDesc_th = 'ความเสียหายคงที่ +144',
		upLvDesc_in = 'Kerusakan tetap +144',
