	[41743] = {
		id = 41743,
		skillName_vn = 'Đánh hai tay bằng thép',
		skillName_en = 'Fight with steel hands',
		skillName_th = 'ต่อสู้ด้วยมือเหล็ก',
		skillName_in = 'Bertarung dengan tangan baja',
		skillName_ph = 'Laban gamit ang bakal na kamay',
		skillName_ma = 'Bertarung dengan tangan besi',
		skillName = 'Fight with steel hands',
		describe_vn = 'Melumeta xoay quanh đai ốc trên ngực và vẫy tay hai lần liên tiếp để đánh đối thủ. Anh ta tấn công một mục tiêu kẻ thù ngẫu nhiên ở hàng trước và sau, gây ra #C0xE69900#320% đòn Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ và #C0xF13B54# Sát Thương Vật Lý tương ứng. Sát thương #C0x5B545B#, gây [Phân rã Giáp] cho các mục tiêu ở hàng trước và [Thu gọn Cánh tay] cho các mục tiêu ở hàng sau. Nếu chỉ có một mục tiêu, hai hiệu ứng này sẽ được thêm vào mục tiêu đó cùng lúc. Ở vòng tiếp theo, lượng máu chuyển đổi từ kim loại lỏng sẽ tăng lên 40% và hiệu ứng phản đòn cứng sẽ được kích hoạt miễn là nó bị tấn công\n#F10# \n#F40##L10#[Sự phân hủy áo giáp]#L0#Hiệu ứng tiêu cực đặc biệt, không thể giải trừ, tăng thêm 20% khả năng bị tổn thương và giảm 30% tỷ lệ kháng cự, kéo dài trong 2 hiệp\n#F10# \n#F40##L10#[Áo giáp Phân rã]#L0#Hiệu ứng tiêu cực đặc biệt, không thể xua tan, giảm 30% sát thương cộng thêm và 30% tỷ lệ chí mạng, tồn tại trong 2 hiệp',
		describe_en = 'Melumeta revolves around the nut on his chest and waves his hand twice consecutively to strike the opponent. He attacks a random enemy target in the front and back row, dealing #C0xE69900#320% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ and #C0xF13B54# corresponding Physical Damage. The #C0x5B545B# damage causes [Armor Deterioration] to targets in the front row and [Arm Retraction] to targets in the back row. If there is only one target, both effects will be applied to that target simultaneously. In the next round, the health converted from liquid metal will increase by 40%, and a hard counterattack effect will be triggered as long as it is attacked. \n#F10# \n#F40##L10#[Armor Decay]#L0#A special negative effect, cannot be dispelled, increases damage taken by 20% and reduces resistance rate by 30%, lasting for 2 turns \n#F10# \n#F40##L10#[Armor Decay]#L0#A special negative effect, cannot be removed, reduces additional damage by 30% and critical rate by 30%, lasting for 2 turns.',
		describe_th = 'เมลูเมตา หมุนรอบน็อตบนอกและโบกมือสองครั้งติดต่อกันเพื่อโจมตีศัตรู เขาโจมตีเป้าหมายศัตรูแบบสุ่มในแถวหน้าและหลัง สร้าง #C0xE69900#320% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ และ #C0xF13B54# ความเสียหายทางกายภาพที่สอดคล้องกัน ความเสียหาย #C0x5B545B# ทำให้เกิด [การเสื่อมสภาพของเกราะ] กับเป้าหมายในแถวหน้า และ [การหดแขน] กับเป้าหมายในแถวหลัง หากมีเป้าหมายเพียงตัวเดียว เอฟเฟกต์ทั้งสองจะถูกเพิ่มเข้าไปยังเป้าหมายนั้นพร้อมกัน ในรอบถัดไป จำนวนพลังชีวิตที่แปลงจากโลหะเหลวจะเพิ่มขึ้น 40% และจะเปิดใช้งานเอฟเฟกต์กันโต้กลับแข็งเมื่อถูกโจมตี \n#F10# \n#F40##L10#[การสลายเกราะ]#L0#เอฟเฟกต์ลบพิเศษ ไม่สามารถลบได้ เพิ่มโอกาสได้รับความเสียหาย 20% และลดอัตราการต้านทาน 30% เป็นเวลา 2 เทิร์น \n#F10# \n#F40##L10#[เกราะสลาย]#L0#เอฟเฟกต์ลบพิเศษ ไม่สามารถกำจัดได้ ลดความเสียหายเพิ่มเติม 30% และอัตราคริติคอล 30% คงอยู่ 2 เทิร์น',
		describe_in = 'Melumeta berputar di sekitar mur di dada dan melambaikan tangan dua kali berturut-turut untuk menyerang lawan. Dia menyerang target musuh acak di baris depan dan belakang, memberikan #C0xE69900#320% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$ dan #C0xF13B54# Kerusakan Fisik yang sesuai. Kerusakan #C0x5B545B# menyebabkan [Kerusakan Armor] pada target di baris depan dan [Penarikan Lengan] pada target di baris belakang. Jika hanya ada satu target, kedua efek ini akan diterapkan pada target tersebut sekaligus. Pada putaran berikutnya, jumlah darah yang dikonversi dari logam cair akan meningkat sebesar 40%, dan efek serangan balik keras akan diaktifkan selama diserang \n#F10# \n#F40##L10#[Penguraian Armor]#L0#Efek negatif khusus, tidak dapat dihapus, meningkatkan kemungkinan menerima kerusakan sebesar 20% dan mengurangi tingkat resistensi sebesar 30%, bertahan selama 2 giliran \n#F10# \n#F40##L10#[Armor Penguraian]#L0#Efek negatif khusus, tidak dapat dihilangkan, mengurangi kerusakan tambahan sebesar 30% dan tingkat kritis sebesar 30%, bertahan selama 2 giliran.',
		describe_ph = 'Si Melumeta ay umiikot sa nut sa dibdib at kumaway ng dalawang beses nang sunod-sunod para umatake sa kalaban. Siya ay umaatake sa isang random na target na kalaban sa harap at likod na hanay, na nagdudulot ng #C0xE69900#320% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ at #C0xF13B54# kaukulang Physical Damage. Ang #C0x5B545B# na pinsala ay nagdudulot ng [Armor Deterioration] sa mga target sa harap na hanay at [Arm Retraction] sa mga target sa likod na hanay. Kung iisa lamang ang target, ang dalawang epektong ito ay sabay na iaaplay sa nasabing target. Sa susunod na round, tataas ng 40% ang health na na-convert mula sa liquid metal at maa-activate ang hard counterattack effect hangga\'t ito ay naaatake \n#F10# \n#F40##L10#[Pagkabulok ng Baluti]#L0#Isang espesyal na negatibong epekto, hindi matatanggal, nagpapataas ng 20% tsansa na makatanggap ng pinsala at nagpapababa ng 30% ratio ng resistensya, tumatagal ng 2 turn \n#F10# \n#F40##L10#[Pagkabulok ng Baluti]#L0#Isang espesyal na negatibong epekto, hindi maaaring alisin, nagpapababa ng 30% dagdag na pinsala at 30% chance ng critical hit, tumatagal ng 2 turn.',
		describe_ma = 'Melumeta berpusing sekitar nat pada dada dan melambai tangan dua kali berturut-turut untuk menyerang lawan. Dia menyerang sasaran musuh rawak di barisan hadapan dan belakang, menyebabkan #C0xE69900#320% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ dan #C0xF13B54# Kerosakan Fizikal yang sepadan. Kerosakan #C0x5B545B# menyebabkan [Kemerosotan Perisai] pada sasaran di barisan hadapan dan [Penarikan Lengan] pada sasaran di barisan belakang. Jika hanya ada satu sasaran, kedua-dua kesan ini akan ditambah pada sasaran tersebut serentak. Pada pusingan seterusnya, jumlah darah yang ditukar dari logam cecair akan meningkat sebanyak 40%, dan kesan serangan balas keras akan diaktifkan selagi ia diserang \n#F10# \n#F40##L10#[Kemerosotan Perisai]#L0#Kesan negatif khas, tidak boleh dibuang, meningkatkan 20% kemungkinan menerima kerosakan dan mengurangkan 30% kadar penentangan, berlangsung selama 2 giliran \n#F10# \n#F40##L10#[Perisai Kemerosotan]#L0#Kesan negatif khas, tidak boleh dihapuskan, mengurangkan 30% kerosakan tambahan dan 30% kadar kritikal, bertahan selama 2 giliran.',
		describe = 'Melumeta revolves around the nut on his chest and waves his hand twice consecutively to strike the opponent. He attacks a random enemy target in the front and back row, dealing #C0xE69900#320% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ and #C0xF13B54# corresponding Physical Damage. The #C0x5B545B# damage causes [Armor Deterioration] to targets in the front row and [Arm Retraction] to targets in the back row. If there is only one target, both effects will be applied to that target simultaneously. In the next round, the health converted from liquid metal will increase by 40%, and a hard counterattack effect will be triggered as long as it is attacked. \n#F10# \n#F40##L10#[Armor Decay]#L0#A special negative effect, cannot be dispelled, increases damage taken by 20% and reduces resistance rate by 30%, lasting for 2 turns \n#F10# \n#F40##L10#[Armor Decay]#L0#A special negative effect, cannot be removed, reduces additional damage by 30% and critical rate by 30%, lasting for 2 turns.',
		simDesc_vn = 'Mê Lục Mê Tát xoay quanh nắp ốc trên ngực, liên tục vung tay 2 lần tấn công đối thủ, tấn công ngẫu nhiên một mục tiêu kẻ thù ở hàng trước và hàng sau.',
		simDesc_en = 'Enchanted Maze Metat revolves around the shell cap on the chest, continuously swinging twice to attack the opponent, randomly attacking one enemy target in the front and back rows.',
		simDesc_th = 'เมล็ก เมตัท หมุนรอบฝาหอยที่หน้าอก โบกมือสองครั้งติดต่อกันเพื่อโจมตีคู่ต่อสู้ โจมตีเป้าหมายศัตรูแบบสุ่มหนึ่งตัวในแถวหน้าและแถวหลัง',
		simDesc_in = 'Mê Lục Mê Tát berputar di sekitar tutup kerang di dada, terus mengayunkan tangan dua kali untuk menyerang musuh, menyerang secara acak satu target musuh di barisan depan dan belakang.',
		simDesc_ph = 'Ang Mê Lục Mê Tát ay umiikot sa takip ng kabibe sa dibdib, paulit-ulit na iwinawasi nang dalawang beses upang atakihin ang kalaban, random na umaatake sa isang target na kalaban sa unahan at likuran ng linya.',
		simDesc_ma = 'Mê Lục Mê Tát berpusing di sekitar penutup kerang di dada, terus mengayunkan tangan dua kali untuk menyerang musuh, menyerang sasaran musuh secara rawak di barisan depan dan belakang.',
		simDesc = 'Enchanted Maze Metat revolves around the shell cap on the chest, continuously swinging twice to attack the opponent, randomly attacking one enemy target in the front and back rows.',
		starEffect = __data_t__starEffect[41743],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng Tăng Cường: Hiệu ứng <Phá Giáp> và <Vũ Khí Sụp Đổ> sẽ lần lượt thêm vào 2 mục tiêu ở hàng trước và hàng sau.',
		starEffectDesc = 'Enhancement Effect: The <Armor Break> and <Weapon Collapse> effects will be applied sequentially to 2 targets in the front and back rows.',
		starEffectDesc_en = 'Enhancement Effect: The <Armor Break> and <Weapon Collapse> effects will be applied sequentially to 2 targets in the front and back rows.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เอฟเฟกต์ <Phá Giáp> และ <Vũ Khí Sụp Đổ> จะถูกเพิ่มไปยังเป้าหมาย 2 ตัวในแถวหน้าและแถวหลังตามลำดับ',
		starEffectDesc_in = 'Efek Peningkatan: Efek <Phá Giáp> dan <Vũ Khí Sụp Đổ> akan diterapkan secara berurutan pada 2 target di baris depan dan belakang.',
		starEffectDesc_ph = 'Epekto ng Pagpapalakas: Ang mga epekto ng <Phá Giáp> at <Vũ Khí Sụp Đổ> ay ilalapat nang sunud-sunod sa 2 target sa unahan at likuran na hanay.',
		starEffectDesc_ma = 'Kesan Peningkatan: Kesan <Phá Giáp> dan <Vũ Khí Sụp Đổ> akan ditambahkan berturut-turut kepada 2 sasaran di barisan hadapan dan belakang.',
		upLvDesc = 'Fixed damage +192',
