	[41752] = {
		id = 41752,
		skillName_vn = 'Đạn kim loại',
		skillName_en = 'Metal Bullet',
		skillName_th = 'กระสุนโลหะ',
		skillName_in = 'Peluru Logam',
		skillName_ph = 'Metal Bullet',
		skillName_ma = 'Peluru Logam',
		skillName = 'Metal Bullet',
		describe_vn = 'Melmetal bắn đạn kim loại tấn công mục tiêu đơn địch, gây #C0xE69900#170% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, bản thân chắc chắn chống đỡ đòn tấn công chủ động trong lượt tiếp theo, và áp dụng trạng thái [Hộ Vệ Sắt] lên mục tiêu phía sau bản thân trong 2 lượt\n#F10# \n#F40##L10#[Hộ Vệ Sắt]#L0# hiệu ứng tăng cường đặc biệt, mục tiêu nhận được tỷ lệ chống đỡ và cường độ chống đỡ giống với thuộc tính hiện tại của Melmetal, khi chống đỡ thành công sẽ kích hoạt hiệu ứng phản công cứng hóa của Melmetal',
		describe_en = 'Melmetal fires metal bullets to attack a single enemy target, dealing #C0xE69900#170% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Melmetal guarantees to block the next active attack in the upcoming turn, and applies the [Iron Guard] state to the target behind itself for 2 turns \n#F10# \n#F40##L10#[Iron Guard]#L0#, a special enhancement effect. The target receives a block rate and block intensity equal to Melmetal\'s current attributes. When the block succeeds, Melmetal triggers a hardening counterattack effect.',
		describe_th = 'Melmetal ยิงกระสุนโลหะโจมตีเป้าหมายศัตรูเดียว สร้างความเสียหาย #C0xE69900#170% การโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# Melmetal รับประกันการป้องกันการโจมตีที่ใช้งานในรอบถัดไป และใช้สถานะ [การ์ดเหล็ก] กับเป้าหมายที่อยู่ด้านหลังตัวเองเป็นเวลา 2 รอบ \n#F10# \n#F40##L10#[การ์ดเหล็ก]#L0# เอฟเฟกต์เสริมพิเศษ เป้าหมายจะได้รับอัตราการป้องกันและความเข้มของการป้องกันเท่ากับคุณสมบัติปัจจุบันของ Melmetal เมื่อป้องกันสำเร็จจะเปิดใช้งานเอฟเฟกต์โจมตีกลับแข็งแกร่งของ Melmetal',
		describe_in = 'Melmetal menembakkan peluru logam untuk menyerang satu target musuh, memberikan #C0xE69900#170% Serangan Fisik#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Melmetal memastikan untuk menahan serangan aktif pada giliran berikutnya, dan menerapkan status [Perisai Besi] pada target di belakang dirinya selama 2 giliran \n#F10# \n#F40##L10#[Perisai Besi]#L0#, efek peningkatan khusus. Target menerima tingkat dan intensitas tahanan yang sama dengan atribut Melmetal saat ini. Saat tahanan berhasil, Melmetal mengaktifkan efek counterattack pengerasan.',
		describe_ph = 'Ang Melmetal ay nagpaputok ng mga bala ng metal upang atakihin ang isang kalabang target, na nagdudulot ng #C0xE69900#170% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Tinitiyak ni Melmetal ang pagtatanggol sa susunod na aktibong pag-atake sa susunod na turn, at inilalagay ang estado ng [Bakod na Bakal] sa target sa likod nito sa loob ng 2 turns \n#F10# \n#F40##L10#[Bakod na Bakal]#L0#, isang espesyal na pinalakas na epekto. Ang target ay tumatanggap ng porsyento ng pagtatanggol at tindi ng pagtatanggol na katulad ng kasalukuyang katangian ni Melmetal. Kapag matagumpay ang pagtatanggol, pinapagana ni Melmetal ang matibay na counterattack effect.',
		describe_ma = 'Melmetal menembak peluru logam untuk menyerang satu sasaran musuh, menyebabkan #C0xE69900#170% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Melmetal memastikan untuk menangkis serangan aktif pada giliran berikutnya, dan menggunakan status [Perisai Besi] pada sasaran di belakangnya selama 2 giliran \n#F10# \n#F40##L10#[Perisai Besi]#L0#, kesan peningkatan khas. Sasaran menerima kadar dan intensiti pertahanan yang sama dengan atribut Melmetal semasa. Apabila pertahanan berjaya, Melmetal mengaktifkan kesan serangan balas pengerasan.',
		describe = 'Melmetal fires metal bullets to attack a single enemy target, dealing #C0xE69900#170% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Melmetal guarantees to block the next active attack in the upcoming turn, and applies the [Iron Guard] state to the target behind itself for 2 turns \n#F10# \n#F40##L10#[Iron Guard]#L0#, a special enhancement effect. The target receives a block rate and block intensity equal to Melmetal\'s current attributes. When the block succeeds, Melmetal triggers a hardening counterattack effect.',
		upLvDesc = 'Fixed damage +144',
		upLvDesc_en = 'Fixed damage +144',
