	[41753] = {
		id = 41753,
		skillName_vn = 'Sóng xung kích',
		skillName_en = 'Shockwave',
		skillName_th = 'คลื่นช็อก',
		skillName_in = 'Gelombang Kejut',
		skillName_ph = 'Alon ng Alon',
		skillName_ma = 'Gelombang Kejut',
		skillName = 'Shockwave',
		describe_vn = 'Meltan tung ra một làn sóng xung kích, tấn công một mục tiêu địch ngẫu nhiên ở hàng trước và hàng sau, gây #C0xE69900#320% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545 B#, gây [Phân hủy giáp] cho các mục tiêu ở hàng trước và [Thu gọn cánh tay] cho các mục tiêu ở hàng sau. Nếu chỉ có một mục tiêu, cả hai hiệu ứng sẽ được thêm vào mục tiêu đó cùng một lúc. Ở vòng tiếp theo, lượng máu chuyển đổi từ kim loại lỏng sẽ tăng lên 40% và hiệu ứng phản đòn cứng sẽ được kích hoạt miễn là nó bị tấn công\n#F10# \n#F40##L10#[Sự phân hủy áo giáp]#L0#Hiệu ứng tiêu cực đặc biệt, không thể giải trừ, tăng thêm 20% khả năng bị tổn thương và giảm 30% tỷ lệ kháng cự, kéo dài trong 2 hiệp\n#F10# \n#F40##L10#[Áo giáp Phân rã]#L0#Hiệu ứng tiêu cực đặc biệt, không thể xua tan, giảm 30% sát thương cộng thêm và 30% tỷ lệ chí mạng, tồn tại trong 2 hiệp',
		describe_en = 'Meltan unleashes a shockwave, attacking a random enemy target in the front and back rows, dealing #C0xE69900#320% Physical Damage#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, applying [Armor Decomposition] to targets in the front row and [Arm Retraction] to targets in the back row. If there is only one target, both effects are applied to that target simultaneously. In the next round, the amount of HP converted from liquid metal increases by 40%, and a hard counterattack effect is triggered whenever it is attacked.\n#F10# \n#F40##L10#[Armor Decomposition]#L0#A special negative effect that cannot be dispelled, increases damage taken by 20% and reduces resistance rate by 30%, lasting for 2 turns.\n#F10# \n#F40##L10#[Armor Decay]#L0#A special negative effect that cannot be removed, reduces additional damage by 30% and critical rate by 30%, lasting for 2 turns.',
		describe_th = 'Meltan ปล่อยคลื่นช็อกโจมตีเป้าหมายศัตรูสุ่มในแถวหน้าและแถวหลัง สร้างความเสียหายทางกายภาพ #C0xE69900#320%#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ทำให้เกิดสถานะ [การสลายเกราะ] กับเป้าหมายในแถวหน้า และ [การหดแขน] กับเป้าหมายในแถวหลัง หากมีเป้าหมายเพียงหนึ่งเดียว จะได้รับเอฟเฟกต์ทั้งสองพร้อมกัน ในรอบถัดไป ปริมาณ HP ที่แปลงจากโลหะเหลวจะเพิ่มขึ้น 40% และจะเปิดใช้งานเอฟเฟกต์การสวนกลับอย่างรุนแรงทุกครั้งที่ถูกโจมตี \n#F10# \n#F40##L10#[การสลายเกราะ]#L0#เอฟเฟกต์ลบพิเศษ ไม่สามารถกำจัดได้ เพิ่มโอกาสถูกทำลาย 20% และลดอัตราต้านทาน 30% คงอยู่ 2 เทิร์น \n#F10# \n#F40##L10#[เกราะสลาย]#L0#เอฟเฟกต์ลบพิเศษ ไม่สามารถลบได้ ลดความเสียหายเพิ่มเติม 30% และอัตราคริติคอล 30% คงอยู่ 2 เทิร์น',
		describe_in = 'Meltan melepaskan gelombang kejut, menyerang sasaran musuh acak di barisan depan dan belakang, memberikan #C0xE69900#320% Kerusakan Fisik#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, memberikan efek [Penguraian Baju Zirah] pada target di barisan depan dan [Penarikan Lengan] pada target di barisan belakang. Jika hanya ada satu target, kedua efek akan diterapkan secara bersamaan pada target tersebut. Pada giliran berikutnya, jumlah HP yang diubah dari logam cair akan meningkat sebesar 40% dan efek serangan balasan keras akan diaktifkan setiap kali terkena serangan.\n#F10# \n#F40##L10#[Penguraian Baju Zirah]#L0#Efek negatif khusus yang tidak bisa dihapus, meningkatkan kemungkinan terkena kerusakan sebesar 20% dan mengurangi tingkat resistensi sebesar 30%, berlangsung selama 2 giliran.\n#F10# \n#F40##L10#[Peluruhan Baju Zirah]#L0#Efek negatif khusus yang tidak bisa dihapus, mengurangi kerusakan tambahan sebesar 30% dan tingkat kritis sebesar 30%, bertahan selama 2 giliran.',
		describe_ph = 'Meltan ay nagpapalabas ng isang alon ng lindol, umatake sa isang random na kalaban sa harap at likurang hanay, nagdudulot ng #C0xE69900#320% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Pisikal na Pinsala#C0x5B545B#, naglalagay ng [Pagka-decompose ng Baluti] sa mga target sa harapang hanay at [Pag-urong ng Braso] sa mga target sa likurang hanay. Kung isa lamang ang target, pareho ang mga epekto ay ipapatupad sabay-sabay sa target na iyon. Sa susunod na round, ang dami ng HP na na-convert mula sa likidong metal ay tataas ng 40% at ang epekto ng matigas na pag-counter ay maa-activate tuwing ito ay aatakehin.\n#F10# \n#F40##L10#[Pagka-decompose ng Baluti]#L0#Isang espesyal na negatibong epekto na hindi maaaring alisin, nagpapataas ng 20% na posibilidad ng pagtanggap ng pinsala at nagpapababa ng 30% na resistensya, tumatagal ng 2 round.\n#F10# \n#F40##L10#[Pagkabulok ng Baluti]#L0#Isang espesyal na negatibong epekto na hindi maaaring alisin, nagpapababa ng 30% dagdag na pinsala at 30% tsansa ng kritikal, tumatagal ng 2 round.',
		describe_ma = 'Meltan melancarkan gelombang kejutan, menyerang sasaran musuh rawak di barisan hadapan dan belakang, menyebabkan #C0xE69900#320% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B#, menyebabkan [Penguraian Zirah] kepada sasaran di barisan hadapan dan [Penarikan Lengan] kepada sasaran di barisan belakang. Jika hanya terdapat satu sasaran, kedua-dua kesan akan ditambah pada sasaran tersebut sekaligus. Pada pusingan seterusnya, jumlah HP yang ditukar daripada logam cair akan meningkat sebanyak 40% dan kesan serangan balas keras akan diaktifkan setiap kali ia diserang.\n#F10# \n#F40##L10#[Penguraian Zirah]#L0#Kesan negatif khas, tidak boleh dibuang, meningkatkan peluang menerima kerosakan sebanyak 20% dan mengurangkan kadar rintangan sebanyak 30%, berlangsung selama 2 pusingan.\n#F10# \n#F40##L10#[Pelupusan Zirah]#L0#Kesan negatif khas, tidak boleh dibuang, mengurangkan kerosakan tambahan sebanyak 30% dan kadar kritikal sebanyak 30%, kekal selama 2 pusingan.',
		describe = 'Meltan unleashes a shockwave, attacking a random enemy target in the front and back rows, dealing #C0xE69900#320% Physical Damage#C0x5B545B# + $(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, applying [Armor Decomposition] to targets in the front row and [Arm Retraction] to targets in the back row. If there is only one target, both effects are applied to that target simultaneously. In the next round, the amount of HP converted from liquid metal increases by 40%, and a hard counterattack effect is triggered whenever it is attacked.\n#F10# \n#F40##L10#[Armor Decomposition]#L0#A special negative effect that cannot be dispelled, increases damage taken by 20% and reduces resistance rate by 30%, lasting for 2 turns.\n#F10# \n#F40##L10#[Armor Decay]#L0#A special negative effect that cannot be removed, reduces additional damage by 30% and critical rate by 30%, lasting for 2 turns.',
		starEffect = __data_t__starEffect[41753],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng Tăng Cường: Hiệu ứng <Phá Giáp> và <Vũ Khí Sụp Đổ> sẽ lần lượt thêm vào 2 mục tiêu ở hàng trước và hàng sau.',
		starEffectDesc = 'Enhancement Effect: The <Armor Break> and <Weapon Collapse> effects will respectively add to 2 targets in the front and back rows.',
		starEffectDesc_en = 'Enhancement Effect: The <Armor Break> and <Weapon Collapse> effects will respectively add to 2 targets in the front and back rows.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เอฟเฟกต์ <Phá Giáp> และ <Vũ Khí Sụp Đổ> จะถูกเพิ่มไปยังเป้าหมาย 2 ตัวในแถวหน้าและแถวหลังตามลำดับ',
		starEffectDesc_in = 'Efek Peningkatan: Efek <Phá Giáp> dan <Vũ Khí Sụp Đổ> masing-masing akan menambahkan pada 2 target di barisan depan dan belakang.',
		starEffectDesc_ph = 'Epekto ng Pagpapalakas: Ang mga epekto ng <Phá Giáp> at <Vũ Khí Sụp Đổ> ay isa-isang idaragdag sa 2 target sa harap at likuran na hanay.',
		starEffectDesc_ma = 'Kesan Peningkatan: Kesan <Phá Giáp> dan <Vũ Khí Sụp Đổ> akan ditambahkan kepada 2 sasaran di barisan hadapan dan belakang secara berurutan.',
