	[41772] = {
		id = 41772,
		skillName_vn = 'Đạn kim loại',
		skillName_en = 'Metal bullets',
		skillName_th = 'กระสุนโลหะ',
		skillName_in = 'Peluru logam',
		skillName_ph = 'Metal bullets',
		skillName_ma = 'Peluru logam',
		skillName = 'Metal bullets',
		describe_vn = 'Melmetal bắn đạn kim loại tấn công mục tiêu đơn địch, gây #C0xE69900#170% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, bản thân chắc chắn chống đỡ đòn tấn công chủ động trong lượt tiếp theo, và áp dụng trạng thái [Hộ Vệ Sắt] lên mục tiêu phía sau bản thân trong 2 lượt\n#F10# \n#F40##L10#[Hộ Vệ Sắt]#L0# hiệu ứng tăng cường đặc biệt, mục tiêu nhận được tỷ lệ chống đỡ và cường độ chống đỡ giống với thuộc tính hiện tại của Melmetal, khi chống đỡ thành công sẽ kích hoạt hiệu ứng phản công cứng hóa của Melmetal',
		describe_en = 'Melmetal fires metal bullets to attack a single enemy target, dealing #C0xE69900#170% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Melmetal ensures to block an active attack in the next turn and applies the [Iron Guard] status to the target behind itself for 2 turns \n#F10# \n#F40##L10#[Iron Guard]#L0#, a special buff effect that grants the target the same block rate and block intensity attributes as Melmetal has currently. When the block is successful, Melmetal\'s Rock-hard Counterattack effect is triggered.',
		describe_th = 'Melmetal ยิงกระสุนโลหะโจมตีเป้าหมายศัตรูเดียว สร้างความเสียหาย #C0xE69900#170% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# Melmetal แน่นอนว่าจะป้องกันการโจมตีแบบแอคทีฟในเทถัดไป และมอบสถานะ [การปกป้องเหล็ก] ให้กับเป้าหมายด้านหลังของตนเป็นเวลา 2 เทิร์น \n#F10# \n#F40##L10#[การปกป้องเหล็ก]#L0# เป็นเอฟเฟกต์บัฟพิเศษ เป้าหมายจะได้รับอัตราการป้องกันและความเข้มข้นของการป้องกันเหมือนกับคุณสมบัติที่ Melmetal มีอยู่ เมื่อป้องกันสำเร็จจะเป็นการเปิดใช้งานเอฟเฟกต์โจมตีตอบโต้แบบแข็งแกร่งของ Melmetal',
		describe_in = 'Melmetal menembakkan peluru logam untuk menyerang satu target musuh, memberikan #C0xE69900#170% Serangan Fisik#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Melmetal pasti akan menahan serangan aktif pada giliran berikutnya, dan menerapkan status [Perlindungan Besi] pada target di belakangnya selama 2 giliran \n#F10# \n#F40##L10#[Perlindungan Besi]#L0#, efek buff khusus yang meningkatkan tingkat penahanan dan intensitas penahanan sesuai dengan atribut Melmetal saat ini. Saat berhasil menahan serangan, efek serangan balik mengeras dari Melmetal akan diaktifkan.',
		describe_ph = 'Humihip ang Melmetal ng mga metal na bala upang atakihin ang isang kalabang target, na nagdudulot ng #C0xE69900#170% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Tinitiyak ng Melmetal na mapipigilan ang isang aktibong pag-atake sa susunod na turn, at inilalapat ang estado ng [Iron Guard] sa target sa likod niya sa loob ng 2 turn \n#F10# \n#F40##L10#[Iron Guard]#L0#, isang espesyal na enhancement effect kung saan ang target ay nakakakuha ng parehong block rate at block intensity gaya ng kasalukuyang katangian ni Melmetal. Kapag nagtagumpay sa pag-block, naitataguyod ang matigas na counterattack effect ng Melmetal.',
		describe_ma = 'Melmetal menembak peluru logam untuk menyerang satu sasaran musuh, memberikan #C0xE69900#170% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Melmetal pasti akan menangkis serangan aktif dalam giliran seterusnya, dan menggunakan status [Perisai Besi] kepada sasaran di belakangnya selama 2 giliran \n#F10# \n#F40##L10#[Perisai Besi]#L0#, kesan peningkatan khas yang memberikan sasaran kadar pertahanan dan intensiti pertahanan yang sama dengan atribut semasa Melmetal. Apabila pertahanan berjaya, kesan serangan balas keras Melmetal akan diaktifkan.',
		describe = 'Melmetal fires metal bullets to attack a single enemy target, dealing #C0xE69900#170% Physical Attack#C0x5B545B# + $(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#. Melmetal ensures to block an active attack in the next turn and applies the [Iron Guard] status to the target behind itself for 2 turns \n#F10# \n#F40##L10#[Iron Guard]#L0#, a special buff effect that grants the target the same block rate and block intensity attributes as Melmetal has currently. When the block is successful, Melmetal\'s Rock-hard Counterattack effect is triggered.',
		upLvDesc = 'Fixed damage +144',
		upLvDesc_en = 'Fixed damage +144',
