	[41773] = {
		id = 41773,
		skillName_vn = 'Sóng xung kích',
		skillName_en = 'Shockwave',
		skillName_th = 'คลื่นช็อก',
		skillName_in = 'Gelombang Kejut',
		skillName_ph = 'Shockwave',
		skillName_ma = 'Gelombang Kejut',
		skillName = 'Shockwave',
		describe_vn = 'Meltan tung ra một làn sóng xung kích, tấn công một mục tiêu địch ngẫu nhiên ở hàng trước và hàng sau, gây #C0xE69900#320% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545 B#, gây [Phân hủy giáp] cho các mục tiêu ở hàng trước và [Thu gọn cánh tay] cho các mục tiêu ở hàng sau. Nếu chỉ có một mục tiêu, cả hai hiệu ứng sẽ được thêm vào mục tiêu đó cùng một lúc. Ở vòng tiếp theo, lượng máu chuyển đổi từ kim loại lỏng sẽ tăng lên 40% và hiệu ứng phản đòn cứng sẽ được kích hoạt miễn là nó bị tấn công\n#F10# \n#F40##L10#[Sự phân hủy áo giáp]#L0#Hiệu ứng tiêu cực đặc biệt, không thể giải trừ, tăng thêm 20% khả năng bị tổn thương và giảm 30% tỷ lệ kháng cự, kéo dài trong 2 hiệp\n#F10# \n#F40##L10#[Áo giáp Phân rã]#L0#Hiệu ứng tiêu cực đặc biệt, không thể xua tan, giảm 30% sát thương cộng thêm và 30% tỷ lệ chí mạng, tồn tại trong 2 hiệp',
		describe_en = 'Meltan unleashes a shockwave, attacking a random enemy target in the front row and the back row, dealing #C0xE69900#320% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B#. It inflicts [Armor Decay] on front row targets and [Arm Contraction] on back row targets. If there is only one target, both effects will be applied simultaneously. In the next round, the health converted from liquid metal increases by 40%, and a hard counterattack effect is triggered as long as it is attacked. \n#F10# \n#F40##L10#[Armor Decay]#L0# A special negative effect that cannot be dispelled, increases the chance to take damage by 20% and reduces resistance rate by 30%, lasting 2 turns. \n#F10# \n#F40##L10#[Armor Disintegration]#L0# A special negative effect that cannot be removed, reduces bonus damage by 30% and critical hit rate by 30%, lasting 2 turns.',
		describe_th = 'Meltan ปล่อยคลื่นช็อก โจมตีเป้าหมายศัตรูแบบสุ่มในแถวหน้าและแถวหลัง สร้างความเสียหายกายภาพ #C0xE69900#320%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# ทำให้เกิด [การสลายเกราะ] กับเป้าหมายแถวหน้าและ [การหดแขน] กับเป้าหมายแถวหลัง หากมีเป้าหมายเพียงหนึ่งเดียว ผลกระทบทั้งสองจะถูกเพิ่มพร้อมกัน ในรอบถัดไป พลังชีวิตที่แปลงจากโลหะเหลวจะเพิ่มขึ้น 40% และเอฟเฟกต์การตอบโต้แข็งจะถูกเปิดใช้งานตราบใดที่ถูกโจมตี \n#F10# \n#F40##L10#[การสลายเกราะ]#L0# เอฟเฟกต์ลบพิเศษ ไม่สามารถล้างได้ เพิ่มโอกาสรับความเสียหาย 20% และลดอัตราต้านทาน 30% มีผล 2 เทิร์น \n#F10# \n#F40##L10#[เกราะสลาย]#L0# เอฟเฟกต์ลบพิเศษ ไม่สามารถขจัดได้ ลดความเสียหายพิเศษ 30% และอัตราคริติคอล 30% มีผล 2 เทิร์น',
		describe_in = 'Meltan melepaskan gelombang kejut, menyerang target musuh acak di baris depan dan belakang, memberikan #C0xE69900#320% Damage Fisik#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Damage Fisik#C0x5B545B#. Memberikan efek [Penguraian Armor] pada target baris depan dan [Pengerutan Lengan] pada target baris belakang. Jika hanya ada satu target, kedua efek akan diterapkan sekaligus. Pada giliran berikutnya, jumlah HP yang dikonversi dari logam cair meningkat sebesar 40% dan efek counter keras akan aktif selama diserang. \n#F10# \n#F40##L10#[Penguraian Armor]#L0# Efek negatif khusus yang tidak dapat dihilangkan, meningkatkan kemungkinan menerima damage sebesar 20% dan mengurangi tingkat resistensi sebesar 30%, berlangsung selama 2 giliran \n#F10# \n#F40##L10#[Armor Hancur]#L0# Efek negatif khusus yang tidak dapat disembuhkan, mengurangi damage tambahan sebesar 30% dan tingkat kritikal 30%, berlangsung selama 2 giliran',
		describe_ph = 'Meltan ay nagpapalabas ng isang alon ng shockwave, umaatake sa isang random na target ng kalaban sa harap at likod na hanay, na nagdudulot ng #C0xE69900#320% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Nagdudulot ng [Pagkabulok ng Baluti] sa mga target sa harap na hanay at [Pag-urong ng Braso] sa mga target sa likod na hanay. Kung iisa lamang ang target, parehong effect ay ilalapat nang sabay. Sa susunod na round, tataas ang health na na-convert mula sa likidong metal ng 40% at mag-a-activate ang hard counter effect hangga\'t ito ay naaatake. \n#F10# \n#F40##L10#[Pagkabulok ng Baluti]#L0# Isang espesyal na negatibong effect na hindi maaaring alisin, nagpapataas ng 20% ng posibilidad na makatanggap ng pinsala at nagpapababa ng 30% ng resistance rate, tatagal ng 2 rounds. \n#F10# \n#F40##L10#[Pagkawasak ng Baluti]#L0# Isang espesyal na negatibong effect na hindi maaaring tanggalin, nagpapababa ng 30% ng karagdagang pinsala at 30% ng critical rate, tatagal ng 2 rounds.',
		describe_ma = 'Meltan melepaskan gelombang kejutan, menyerang sasaran musuh rawak di barisan hadapan dan belakang, menyebabkan #C0xE69900#320% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Memberikan kesan [Pemusnahan Perisai] kepada sasaran di barisan hadapan dan [Pengerutan Lengan] kepada sasaran di barisan belakang. Jika hanya ada satu sasaran, kedua-dua kesan akan ditambahkan secara serentak. Pada pusingan seterusnya, jumlah darah yang ditukar dari logam cair akan meningkat sebanyak 40% dan kesan serangan balas keras akan diaktifkan selagi ia diserang. \n#F10# \n#F40##L10#[Pemusnahan Perisai]#L0# Kesan negatif khas, tidak boleh dihapuskan, meningkatkan peluang menerima kerosakan sebanyak 20% dan mengurangkan kadar daya tahan sebanyak 30%, berlangsung selama 2 pusingan \n#F10# \n#F40##L10#[Perisai Hancur]#L0# Kesan negatif khas, tidak boleh dihilangkan, mengurangkan kerosakan tambahan sebanyak 30% dan kadar kritikal sebanyak 30%, berlangsung selama 2 pusingan',
		describe = 'Meltan unleashes a shockwave, attacking a random enemy target in the front row and the back row, dealing #C0xE69900#320% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Physical Damage#C0x5B545B#. It inflicts [Armor Decay] on front row targets and [Arm Contraction] on back row targets. If there is only one target, both effects will be applied simultaneously. In the next round, the health converted from liquid metal increases by 40%, and a hard counterattack effect is triggered as long as it is attacked. \n#F10# \n#F40##L10#[Armor Decay]#L0# A special negative effect that cannot be dispelled, increases the chance to take damage by 20% and reduces resistance rate by 30%, lasting 2 turns. \n#F10# \n#F40##L10#[Armor Disintegration]#L0# A special negative effect that cannot be removed, reduces bonus damage by 30% and critical hit rate by 30%, lasting 2 turns.',
		starEffect = __data_t__starEffect[41773],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng Tăng Cường: Hiệu ứng <Phá Giáp> và <Vũ Khí Sụp Đổ> sẽ lần lượt thêm vào 2 mục tiêu ở hàng trước và hàng sau.',
		starEffectDesc = 'Enhancement Effect: The <Armor Break> and <Weapon Collapse> effects will respectively add to 2 targets in the front and back rows.',
		starEffectDesc_en = 'Enhancement Effect: The <Armor Break> and <Weapon Collapse> effects will respectively add to 2 targets in the front and back rows.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เอฟเฟกต์ <Phá Giáp> และ <Vũ Khí Sụp Đổ> จะถูกเพิ่มไปยังเป้าหมาย 2 ตัวในแถวหน้าและแถวหลังตามลำดับ',
		starEffectDesc_in = 'Efek Peningkatan: Efek <Phá Giáp> dan <Vũ Khí Sụp Đổ> masing-masing akan menambahkan pada 2 target di barisan depan dan belakang.',
		starEffectDesc_ph = 'Epekto ng Pagpapalakas: Ang mga epekto ng <Phá Giáp> at <Vũ Khí Sụp Đổ> ay isa-isang idaragdag sa 2 target sa harap at likuran na hanay.',
		starEffectDesc_ma = 'Kesan Peningkatan: Kesan <Phá Giáp> dan <Vũ Khí Sụp Đổ> akan ditambahkan kepada 2 sasaran di barisan hadapan dan belakang secara berurutan.',
