	[52004] = {
		id = 52004,
		skillName_vn = 'Mang theo đạo cụ',
		skillName_en = 'Carry props',
		skillName_th = 'พกอุปกรณ์',
		skillName_in = 'Membawa properti',
		skillName_ph = 'Magdala ng mga props',
		skillName_ma = 'Membawa alat',
		skillName = 'Carry props',
		describe_vn = 'Trong 4 hiệp đầu tiên của trận chiến, tốc độ và sát thương cộng thêm mỗi lần tăng thêm $(16+(skillLevel-1)*2)$% và tấn công các đơn vị có lượng máu cao hơn 50% sẽ gây thêm $(15+(skillLevel-1)*1.5)$% sát thương (tích lũy trong toàn bộ trò chơi ở chế độ chơi đơn)\n#F10# \n#F40##L10#Immortal Legend: #L0# Trước mỗi hành động, tỷ lệ tấn công kép và đòn chí mạng tăng thêm 5% trong 2 lượt, có thể cộng dồn 2 lần; Hiệu ứng này được kích hoạt liên tục trong cùng một hiệp (các kỹ năng bổ sung cũng có thể được kích hoạt, xem hướng dẫn chiến đấu để biết chi tiết), đồng thời tỷ lệ tấn công kép và đòn chí mạng tăng 15% trong 2 lượt, không thể chồng lên nhau.',
		describe_en = 'In the first 4 rounds of the battle, speed and additional damage increase by $(16+(skillLevel-1)*2)$% each time, and attacking units with more than 50% HP deals an additional $(15+(skillLevel-1)*1.5)$% damage (accumulates throughout the single-player mode). \n#F10# \n#F40##L10#Immortal Legend: #L0# Before each action, the double attack and critical hit rates increase by 5% for 2 turns, can stack up to 2 times; this effect is continuously triggered within the same round (additional skills may also be activated, see combat guide for details), meanwhile double attack and critical hit rates increase by 15% for 2 turns, cannot stack.',
		describe_th = 'ใน 4 รอบแรกของการต่อสู้ ความเร็วและความเสียหายเพิ่มเติมเพิ่มขึ้น $(16+(skillLevel-1)*2)$% ในแต่ละครั้ง และการโจมตีหน่วยที่มีพลังชีวิตมากกว่า 50% จะก่อให้เกิดความเสียหายเพิ่มเติม $(15+(skillLevel-1)*1.5)$% (สะสมตลอดโหมดเล่นคนเดียว) \n#F10# \n#F40##L10#ตำนานอมตะ: #L0# ก่อนการกระทำแต่ละครั้ง อัตราการโจมตีคู่และโอกาสคริติคอลเพิ่มขึ้น 5% เป็นเวลา 2 รอบ สามารถสะสมได้ 2 ครั้ง; เอฟเฟกต์นี้จะถูกกระตุ้นอย่างต่อเนื่องในรอบเดียวกัน (สกิลเพิ่มเติมก็อาจถูกกระตุ้น ดูคำแนะนำการต่อสู้สำหรับรายละเอียด) ในขณะเดียวกัน อัตราการโจมตีคู่และโอกาสคริติคอลเพิ่มขึ้น 15% เป็นเวลา 2 รอบ ไม่สามารถซ้อนทับกันได้',
		describe_in = 'Dalam 4 ronde pertama pertarungan, kecepatan dan tambahan kerusakan meningkat sebesar $(16+(skillLevel-1)*2)$% setiap kali, dan menyerang unit dengan HP lebih dari 50% akan menyebabkan tambahan kerusakan sebesar $(15+(skillLevel-1)*1.5)$% (terakumulasi di seluruh mode pemain tunggal). \n#F10# \n#F40##L10#Legenda Abadi: #L0# Sebelum setiap aksi, tingkat serangan ganda dan critical hit meningkat 5% selama 2 giliran, dapat menumpuk hingga 2 kali; efek ini terus diaktifkan dalam ronde yang sama (kemampuan tambahan juga dapat diaktifkan, lihat panduan pertempuran untuk detail), sementara itu tingkat serangan ganda dan critical hit meningkat 15% selama 2 giliran, tidak dapat bertumpuk.',
		describe_ph = 'Sa unang 4 na round ng laban, ang bilis at dagdag na pinsala ay tumataas ng $(16+(skillLevel-1)*2)$% kada pagkakataon, at ang pag-atake sa mga yunit na may higit sa 50% HP ay nagdudulot ng dagdag na pinsala na $(15+(skillLevel-1)*1.5)$% (nakaipon sa buong single-player mode). \n#F10# \n#F40##L10#Immortal Legend: #L0# Bago ang bawat aksyon, tumataas ang tsansa ng double attack at critical hit ng 5% sa loob ng 2 turn, maaaring ma-stack ng 2 beses; ang epekto na ito ay patuloy na nai-activate sa parehong round (maaari rin ma-activate ang dagdag na skills, tingnan ang combat guide para sa detalye), kasabay nito tumataas ang tsansa ng double attack at critical hit ng 15% sa loob ng 2 turn, hindi maaaring mag-stack.',
		describe_ma = 'Dalam 4 pusingan pertama pertempuran, kelajuan dan kerosakan tambahan meningkat sebanyak $(16+(skillLevel-1)*2)$% setiap kali, dan menyerang unit dengan lebih daripada 50% HP akan menyebabkan kerosakan tambahan sebanyak $(15+(skillLevel-1)*1.5)$% (terakumulasi sepanjang mod pemain tunggal). \n#F10# \n#F40##L10#Legenda Abadi: #L0# Sebelum setiap tindakan, kadar serangan berganda dan serangan kritikal meningkat sebanyak 5% selama 2 pusingan, boleh bertimbun hingga 2 kali; kesan ini diaktifkan secara berterusan dalam pusingan yang sama (kemahiran tambahan juga boleh diaktifkan, lihat panduan pertempuran untuk butiran), pada masa yang sama kadar serangan berganda dan serangan kritikal meningkat 15% selama 2 pusingan, tidak boleh bertindih.',
		describe = 'In the first 4 rounds of the battle, speed and additional damage increase by $(16+(skillLevel-1)*2)$% each time, and attacking units with more than 50% HP deals an additional $(15+(skillLevel-1)*1.5)$% damage (accumulates throughout the single-player mode). \n#F10# \n#F40##L10#Immortal Legend: #L0# Before each action, the double attack and critical hit rates increase by 5% for 2 turns, can stack up to 2 times; this effect is continuously triggered within the same round (additional skills may also be activated, see combat guide for details), meanwhile double attack and critical hit rates increase by 15% for 2 turns, cannot stack.',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 1,
		passiveTriggerArg = 1,
		posChoose = 5,
		skillProcess = {529041}
