	[52005] = {
		id = 52005,
		skillName_vn = 'Mang theo đạo cụ',
		skillName_en = 'Carry props',
		skillName_th = 'พกอุปกรณ์',
		skillName_in = 'Membawa properti',
		skillName_ph = 'Magdala ng mga props',
		skillName_ma = 'Membawa alat',
		skillName = 'Carry props',
		describe_vn = 'Trong trận chiến, khi lượng máu của một người thấp hơn 40%, lượng máu $(18+(skillLevel-1)*1.5)$% giới hạn mạng sống của một người sẽ được phục hồi ngay lập tức. Nó chỉ có thể được kích hoạt 3 lần trong toàn bộ trò chơi (tích lũy trong toàn bộ trò chơi ở chế độ chơi đơn)\n#F10# \n#F40##L10#Hiệu ứng bất tử: #L0# Khi máu của người mặc giảm xuống dưới 5% lần đầu tiên, 60% máu của anh ta sẽ được phục hồi (hiệu ứng bất tử bỏ qua lệnh cấm hồi máu và ảnh hưởng của việc giảm hiệu ứng hồi máu. Nhiều trang bị có hiệu ứng bất tử chỉ có thể kích hoạt 2)',
		describe_en = 'In battle, when a person\'s health falls below 40%, an amount of health equal to $(18+(skillLevel-1)*1.5)$% of their life limit will be instantly restored. This can only be activated 3 times throughout the entire game (accumulated across the whole game in single-player mode). \n#F10# \n#F40##L10#Immortality Effect: #L0# When the wearer\'s health drops below 5% for the first time, 60% of their health will be restored (the immortality effect bypasses healing prohibition and reduction effects. Many equipments with immortality effect can only be triggered twice).',
		describe_th = 'ในการต่อสู้ เมื่อตัวละครมีพลังชีวิตต่ำกว่า 40% พลังชีวิต $(18+(skillLevel-1)*1.5)$% ของขีดจำกัดชีวิตจะถูกฟื้นฟูทันที สามารถเปิดใช้งานได้เพียง 3 ครั้งตลอดทั้งเกม (สะสมในโหมดเล่นคนเดียวทั้งเกม) \n#F10# \n#F40##L10#ผลลัพธ์อมตะ: #L0# เมื่อพลังชีวิตของผู้สวมใส่ครั้งแรกลดลงต่ำกว่า 5% จะฟื้นฟูพลังชีวิต 60% (เอฟเฟกต์อมตะจะข้ามข้อห้ามการฟื้นฟูและผลของการลดการฟื้นฟู อุปกรณ์หลายชิ้นที่มีผลแบบอมตะสามารถเปิดใช้งานได้เพียง 2 ครั้ง)',
		describe_in = 'Dalam pertarungan, ketika darah seseorang turun di bawah 40%, sejumlah $(18+(skillLevel-1)*1.5)$% dari batas hidupnya akan dipulihkan segera. Efek ini hanya dapat diaktifkan 3 kali sepanjang permainan (terakumulasi selama mode pemain tunggal). \n#F10# \n#F40##L10#Efek keabadian: #L0# Ketika darah pemakai turun di bawah 5% untuk pertama kalinya, 60% darahnya akan dipulihkan (efek keabadian melewati larangan penyembuhan dan pengurangan efek penyembuhan. Banyak perlengkapan dengan efek keabadian hanya dapat diaktifkan 2 kali).',
		describe_ph = 'Sa laban, kapag ang health ng isang tao ay bumaba sa ilalim ng 40%, ang health na katumbas ng $(18+(skillLevel-1)*1.5)$% ng kanilang life limit ay agad na mababawi. Maaari lamang itong ma-trigger ng 3 beses sa buong laro (naipon sa buong laro sa single-player mode). \n#F10# \n#F40##L10#Epekto ng Immortality: #L0# Kapag ang health ng nagsusuot ay bumaba sa ilalim ng 5% sa unang pagkakataon, 60% ng health niya ay mababawi (ang epekto ng immortality ay nilalampasan ang pagbabawal sa healing at ang epekto ng pagbawas sa healing. Maraming kagamitan na may immortality effect ay maaari lamang ma-activate ng 2 beses).',
		describe_ma = 'Dalam pertempuran, apabila darah seseorang kurang dari 40%, sejumlah $(18+(skillLevel-1)*1.5)$% daripada had nyawa akan dipulihkan serta-merta. Ia hanya boleh diaktifkan 3 kali sepanjang permainan (berkumpul sepanjang permainan dalam mod pemain tunggal). \n#F10# \n#F40##L10#Kesan keabadian: #L0# Apabila darah pemakai jatuh di bawah 5% buat pertama kali, 60% daripada darah akan dipulihkan (kesan keabadian mengabaikan larangan pemulihan dan pengurangan kesan pemulihan. Banyak peralatan dengan kesan keabadian hanya boleh diaktifkan 2 kali).',
		describe = 'In battle, when a person\'s health falls below 40%, an amount of health equal to $(18+(skillLevel-1)*1.5)$% of their life limit will be instantly restored. This can only be activated 3 times throughout the entire game (accumulated across the whole game in single-player mode). \n#F10# \n#F40##L10#Immortality Effect: #L0# When the wearer\'s health drops below 5% for the first time, 60% of their health will be restored (the immortality effect bypasses healing prohibition and reduction effects. Many equipments with immortality effect can only be triggered twice).',
		alwaysEffective = true,
		passivePriority = 3,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {520051}
	},
	[52006] = {
		id = 52006,
		skillName_vn = 'Mang đạo cụ - Tấn công',
		skillName_en = 'Manga items - Attack',
		skillName_th = 'ไอเทมมังงะ - การโจมตี',
		skillName_in = 'Item Manga - Serangan',
		skillName_ph = 'Manga na gamit - Atake',
		skillName_ma = 'Barang Manga - Serangan',
		skillName = 'Manga items - Attack',
		describe_vn = 'Trong 2 hiệp đầu tiên của trận chiến, bạn sẽ hồi lại $(90+(skillLevel-1)*15)$ điểm tức giận trước khi tấn công. Trong 4 hiệp đầu tiên của trận chiến, các đòn tấn công của bạn sẽ bỏ qua mức giảm sát thương của mục tiêu $(6+(skillLevel-1)*1.5)$% (tích lũy trong chơi một người chơi)\n#F10# \n#F40##L10#Eternal Energy: #L0# Khi bạn sử dụng chiêu thức đặc biệt hoặc chiêu thức đặc biệt hơn để đánh bại đơn vị không được triệu tập, bạn sẽ ngay lập tức nhận được 300 điểm tức giận và bỏ qua 20% phòng thủ kép cho lần tấn công tiếp theo (được kích hoạt một lần trên toàn sân)',
		describe_en = 'In the first 2 rounds of the battle, you will recover $(90+(skillLevel-1)*15)$ anger points before attacking. In the first 4 rounds of the battle, your attacks will ignore the target\'s damage reduction by $(6+(skillLevel-1)*1.5)$% (accumulates in single-player mode). \n#F10# \n#F40##L10#Eternal Energy: #L0# When you use a special or greater special move to defeat an unsummoned unit, you will immediately gain 300 anger points and ignore 20% dual defense for the next attack (activates once on the entire field).',
		describe_th = 'ใน 2 รอบแรกของการต่อสู้ คุณจะฟื้นฟู $(90+(skillLevel-1)*15)$ คะแนนความโกรธก่อนที่จะโจมตี ใน 4 รอบแรกของการต่อสู้ การโจมตีของคุณจะละเลยการลดความเสียหายของเป้าหมาย $(6+(skillLevel-1)*1.5)$% (สะสมในโหมดเล่นคนเดียว) \n#F10# \n#F40##L10#พลังงานนิรันดร์: #L0# เมื่อคุณใช้ท่าไม้ตายพิเศษหรือท่าไม้ตายที่ยิ่งใหญ่กว่าในการกำจัดหน่วยที่ไม่ได้ถูกอัญเชิญ คุณจะได้รับคะแนนความโกรธทันที 300 คะแนน และละเลยการป้องกันคู่ 20% สำหรับการโจมตีครั้งถัดไป (เปิดใช้งานครั้งเดียวทั่วสนาม)',
		describe_in = 'Dalam 2 ronde pertama pertarungan, kamu akan memulihkan $(90+(skillLevel-1)*15)$ poin kemarahan sebelum menyerang. Dalam 4 ronde pertama pertarungan, seranganmu akan mengabaikan pengurangan kerusakan target sebesar $(6+(skillLevel-1)*1.5)$% (terakumulasi dalam mode pemain tunggal) \n#F10# \n#F40##L10#Energi Abadi: #L0# Saat kamu menggunakan jurus khusus atau jurus khusus tingkat lebih tinggi untuk mengalahkan unit yang tidak dipanggil, kamu akan langsung mendapatkan 300 poin kemarahan dan mengabaikan 20% pertahanan ganda untuk serangan berikutnya (diaktifkan satu kali di seluruh medan).',
		describe_ph = 'Sa unang 2 rounds ng laban, mababawi mo ang $(90+(skillLevel-1)*15)$ puntos ng galit bago umatake. Sa unang 4 rounds ng laban, ang mga atake mo ay lilipas sa pagbawas ng pinsala ng target na $(6+(skillLevel-1)*1.5)$% (nakakumulat sa single-player mode) \n#F10# \n#F40##L10#Eternal Energy: #L0# Kapag ginamit mo ang espesyal o mas malakas na espesyal na galaw para talunin ang yunit na hindi summons, agad kang makakakuha ng 300 puntos ng galit at nilalaktawan ang 20% dobleng depensa para sa susunod na atake (activate isang beses sa buong field).',
		describe_ma = 'Dalam 2 pusingan pertama pertempuran, anda akan memulihkan $(90+(skillLevel-1)*15)$ mata kemarahan sebelum menyerang. Dalam 4 pusingan pertama pertempuran, serangan anda akan mengabaikan pengurangan kerosakan sasaran sebanyak $(6+(skillLevel-1)*1.5)$% (berkumpul dalam mod pemain tunggal) \n#F10# \n#F40##L10#Tenaga Abadi: #L0# Apabila anda menggunakan gerakan khas atau gerakan khas lebih hebat untuk mengalahkan unit yang tidak dipanggil, anda akan segera menerima 300 mata kemarahan dan mengabaikan 20% pertahanan dua kali untuk serangan berikutnya (diaktifkan sekali di seluruh medan).',
		describe = 'In the first 2 rounds of the battle, you will recover $(90+(skillLevel-1)*15)$ anger points before attacking. In the first 4 rounds of the battle, your attacks will ignore the target\'s damage reduction by $(6+(skillLevel-1)*1.5)$% (accumulates in single-player mode). \n#F10# \n#F40##L10#Eternal Energy: #L0# When you use a special or greater special move to defeat an unsummoned unit, you will immediately gain 300 anger points and ignore 20% dual defense for the next attack (activates once on the entire field).',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		alwaysEffective = true,
		passivePriority = 3,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {520061}
	},
