	[52008] = {
		id = 52008,
		skillName_vn = 'Mang theo đạo cụ - Phản sát khi còn ít máu',
		skillName_en = 'Carry props - Retaliate when low on health',
		skillName_th = 'พกอุปกรณ์ - ตอบโต้เมื่อเลือดน้อย',
		skillName_in = 'Bawa properti - Balas saat darah sedikit',
		skillName_ph = 'Magdala ng kagamitan - Ganti kapag mababa ang buhay',
		skillName_ma = 'Bawa peralatan - Balas apabila darah sedikit',
		skillName = 'Carry props - Retaliate when low on health',
		describe_vn = 'Trong trận chiến, người mặc chủ động tấn công và thêm hiệu ứng đốt tâm trí cho mục tiêu chính (gây 80% Sát Thương Vật Lý của bản thân, tồn tại trong 3 hiệp và có thể cộng dồn tối đa 5 lần). Nếu có một đơn vị đang cháy trong phạm vi sát thương, tỷ lệ trúng đòn chí mạng của chủ sở hữu là $(12+(skillLevel-1)*1.5)$% và hút máu $(8+(skillLevel-1)*1)$% sẽ tạm thời tăng lên trước khi tấn công\n#F10# \n#F40# Khi lượng máu thấp hơn 40% trong lần đầu tiên, sát thương cộng thêm 12% và tỷ lệ chí mạng 5% sẽ tăng lên trong 3 vòng.',
		describe_en = 'In battle, the wearer actively attacks and applies a Mind Burn effect to the main target (dealing 80% of their Physical Damage, lasting for 3 turns and can stack up to 5 times). If there is a burning unit within the damage range, the owner\'s critical hit rate of $(12+(skillLevel-1)*1.5)$% and lifesteal of $(8+(skillLevel-1)*1)$% will temporarily increase before attacking. When health drops below 40% for the first time, additional damage of 12% and critical rate of 5% will increase for 3 turns.',
		describe_th = 'ในระหว่างการต่อสู้ ผู้สวมใส่จะโจมตีอย่างรุกและเพิ่มเอฟเฟกต์เผาจิตใจให้แก่เป้าหมายหลัก (ก่อให้เกิดความเสียหายทางกายภาพ 80% ของตัวเอง ยังคงอยู่เป็นเวลา 3 เทิร์น และสามารถสะสมได้สูงสุด 5 ครั้ง) หากมีหน่วยที่กำลังถูกเผาอยู่ในระยะความเสียหาย อัตราคริติคอลของเจ้าของที่มีค่า $(12+(skillLevel-1)*1.5)$% และการดูดเลือด $(8+(skillLevel-1)*1)$% จะเพิ่มขึ้นชั่วคราวก่อนโจมตี เมื่อพลังชีวิตต่ำกว่า 40% เป็นครั้งแรก ความเสียหายพิเศษ 12% และอัตราคริติคอล 5% จะเพิ่มขึ้นเป็นเวลา 3 รอบ',
		describe_in = 'Dalam pertarungan, pemakai secara aktif menyerang dan menambahkan efek Pembakaran Pikiran pada target utama (menyebabkan 80% Kerusakan Fisik miliknya, bertahan selama 3 giliran dan dapat menumpuk hingga 5 kali). Jika ada unit yang terbakar dalam jangkauan kerusakan, tingkat kritikal pemilik sebesar $(12+(skillLevel-1)*1.5)$% dan serapan darah $(8+(skillLevel-1)*1)$% akan meningkat sementara sebelum menyerang. Ketika darah di bawah 40% untuk pertama kalinya, tambahan kerusakan 12% dan tingkat kritikal 5% akan meningkat selama 3 putaran.',
		describe_ph = 'Sa laban, ang nagsusuot ay aktibong umatake at nagdaragdag ng Mind Burn effect sa pangunahing target (nagdudulot ng 80% ng sariling Physical Damage, tumatagal ng 3 turn at maaaring mag-stack hanggang 5 beses). Kung may yunit na nasusunog sa saklaw ng pinsala, ang critical hit rate ng may-ari na $(12+(skillLevel-1)*1.5)$% at lifesteal na $(8+(skillLevel-1)*1)$% ay pansamantalang tataas bago umatake. Kapag bumaba ang HP sa ibaba ng 40% sa unang pagkakataon, ang dagdag na 12% damage at 5% critical rate ay tataas sa loob ng 3 rounds.',
		describe_ma = 'Dalam pertempuran, pemakai secara aktif menyerang dan menambah kesan Pembakaran Minda pada sasaran utama (menyebabkan 80% Kerosakan Fizikal dirinya, bertahan selama 3 pusingan dan boleh bertumpuk sehingga 5 kali). Jika terdapat unit yang terbakar dalam julat kerosakan, kadar kritikal pemilik sebanyak $(12+(skillLevel-1)*1.5)$% dan hisap darah $(8+(skillLevel-1)*1)$% akan meningkat sementara sebelum menyerang. Apabila darah kurang daripada 40% untuk kali pertama, kerosakan tambahan 12% dan kadar kritikal 5% akan meningkat selama 3 pusingan.',
		describe = 'In battle, the wearer actively attacks and applies a Mind Burn effect to the main target (dealing 80% of their Physical Damage, lasting for 3 turns and can stack up to 5 times). If there is a burning unit within the damage range, the owner\'s critical hit rate of $(12+(skillLevel-1)*1.5)$% and lifesteal of $(8+(skillLevel-1)*1)$% will temporarily increase before attacking. When health drops below 40% for the first time, additional damage of 12% and critical rate of 5% will increase for 3 turns.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		alwaysEffective = true,
		passivePriority = 3,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {520081}
	},
	[52009] = {
		id = 52009,
		skillName_vn = 'Mang theo đạo cụ - Phản đòn phòng thủ',
		skillName_en = 'Carry props - Counter defense',
		skillName_th = 'พกอุปกรณ์ - โต้กลับการป้องกัน',
		skillName_in = 'Bawa alat - Serangan balik pertahanan',
		skillName_ph = 'Dalhin ang gamit - Pagsalungat sa depensa',
		skillName_ma = 'Bawa alat - Serang balas pertahanan',
		skillName = 'Carry props - Counter defense',
		describe_vn = 'Trong trận chiến, trước khi nhận sát thương từ một chiêu thức đặc biệt, bạn sẽ ngay lập tức phục hồi $(12+(skillLevel-1)*1.5)$% giới hạn máu của mình (điều trị quá mức sẽ được chuyển thành lá chắn) và $(60+(skillLevel-1)* Sự tức giận của 15)$ chỉ có thể được kích hoạt 3 lần trong toàn bộ trò chơi (tích lũy khi chơi một người chơi). Sau khi chủ sở hữu trang bị kích hoạt 4 hành động đặc biệt (hợp tác, phản công, mời đánh, tấn công phủ đầu), tổng số lần hiệu ứng cơ bản của trang bị là +1 (hiệu ứng chỉ có thể kích hoạt một lần)',
		describe_en = 'In battle, before receiving damage from a special attack, you will immediately recover $(12+(skillLevel-1)*1.5)$% of your maximum HP (overhealing is converted into a shield) and $(60+(skillLevel-1)*15)$ Anger. This can only be activated 3 times throughout the game (accumulates in single-player mode). After the equipment owner performs 4 special actions (cooperate, counterattack, invite to fight, preemptive strike), the total number of basic equipment effects is increased by 1 (effect can only be triggered once).',
		describe_th = 'ในการต่อสู้ ก่อนที่จะได้รับความเสียหายจากท่าพิเศษ คุณจะฟื้นฟูทันที $(12+(skillLevel-1)*1.5)$% ของค่าพลังชีวิตสูงสุดของคุณ (การรักษาเกินจะถูกแปลงเป็นโล่) และ $(60+(skillLevel-1)*15)$ ความโกรธ สามารถเปิดใช้งานได้เพียง 3 ครั้งตลอดเกม (สะสมเมื่อเล่นแบบผู้เล่นคนเดียว) หลังจากเจ้าของอุปกรณ์ทำการกระทำพิเศษ 4 ครั้ง (ร่วมมือ, ตอบโต้, เชิญสู้, ซุ่มโจมตี) จำนวนผลกระทบพื้นฐานของอุปกรณ์จะเพิ่มขึ้น 1 (ผลกระทบนี้สามารถเปิดใช้งานได้เพียงครั้งเดียว)',
		describe_in = 'Dalam pertarungan, sebelum menerima kerusakan dari serangan khusus, kamu akan segera pulih sebanyak $(12+(skillLevel-1)*1.5)$% dari batas HP-mu (pemulihan berlebih akan diubah menjadi perisai) dan $(60+(skillLevel-1)*15)$ Kemarahan. Ini hanya dapat diaktifkan 3 kali selama seluruh permainan (terakumulasi saat bermain mode pemain tunggal). Setelah pemilik perlengkapan melakukan 4 aksi khusus (bekerja sama, membalas serangan, mengajak bertarung, serangan awal), total efek dasar perlengkapan bertambah +1 (efek ini hanya bisa diaktifkan satu kali).',
		describe_ph = 'Sa laban, bago tumanggap ng pinsala mula sa isang espesyal na atake, agad kang makabawi ng $(12+(skillLevel-1)*1.5)$% ng iyong maximum na HP (ang sobrang pagpapagaling ay magiging shield) at $(60+(skillLevel-1)*15)$ galit. Maaari lamang itong ma-activate nang 3 beses sa buong laro (naaipon sa single-player). Pagkatapos magpatupad ng 4 na espesyal na aksyon ang may-ari ng kagamitan (coop, counterattack, paanyaya sa labanan, preemptive strike), tataas ang kabuuang bilang ng pangunahing epekto ng kagamitan ng +1 (ang epekto ay maaaring mag-trigger ng isang beses lamang).',
		describe_ma = 'Dalam pertempuran, sebelum menerima kerosakan daripada serangan khas, anda akan segera memulihkan $(12+(skillLevel-1)*1.5)$% had maksimum darah anda (pemulihan berlebihan akan ditukar menjadi perisai) dan $(60+(skillLevel-1)*15)$ Kemarahan. Ini hanya boleh diaktifkan 3 kali sepanjang permainan (terkumpul semasa bermain seorang pemain). Selepas pemilik peralatan melakukan 4 tindakan khas (bekerjasama, serangan balas, menjemput bertarung, serangan awal), jumlah kesan asas peralatan akan bertambah +1 (kesan hanya boleh diaktifkan sekali).',
		describe = 'In battle, before receiving damage from a special attack, you will immediately recover $(12+(skillLevel-1)*1.5)$% of your maximum HP (overhealing is converted into a shield) and $(60+(skillLevel-1)*15)$ Anger. This can only be activated 3 times throughout the game (accumulates in single-player mode). After the equipment owner performs 4 special actions (cooperate, counterattack, invite to fight, preemptive strike), the total number of basic equipment effects is increased by 1 (effect can only be triggered once).',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		alwaysEffective = true,
		passivePriority = 3,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {520091}
	},
	[52010] = {
		id = 52010,
		skillName_vn = 'Mang đạo cụ - Phòng thủ',
		skillName_en = 'Manga items - Defense',
		skillName_th = 'ไอเทมมังงะ - การป้องกัน',
		skillName_in = 'Item manga - Pertahanan',
		skillName_ph = 'Mga gamit sa manga - Depensa',
		skillName_ma = 'Barangan manga - Pertahanan',
		skillName = 'Manga items - Defense',
		describe_vn = 'Trong trận chiến, khả năng giảm sát thương đặc biệt của người mặc sẽ tạm thời tăng thêm $(20+(skillLevel-1)*2)$% trước khi nhận 4 đòn tấn công đặc biệt đầu tiên\n#F10# \n#F40##L10# Hiệu ứng cộng hưởng: #L0# 2 hiệp trước khi bắt đầu trận chiến, khi có 2 đồng đội trở lên có cùng thuộc tính với người mặc, sát thương hạn chế thuộc tính tự nhiên mà người mặc nhận được sẽ giảm 20%, và đồng đội có cùng thuộc tính được giảm 10% sát thương chí mạng (hiệu ứng cộng hưởng chỉ có thể có hiệu lực trên nhiều trang bị)',
		describe_en = 'In battle, the wearer’s special damage reduction increases temporarily by $(20+(skillLevel-1)*2)$% before receiving the first 4 special attacks. Resonance Effect: For 2 turns before battle starts, if there are 2 or more teammates with the same attribute as the wearer, the wearer’s natural attribute damage received is reduced by 20%, and teammates with the same attribute receive 10% less critical damage (resonance effect can only be effective with multiple equipment).',
		describe_th = 'ในการต่อสู้ ความสามารถลดความเสียหายพิเศษของผู้สวมใส่จะเพิ่มขึ้นชั่วคราว $(20+(skillLevel-1)*2)$% ก่อนที่จะได้รับการโจมตีพิเศษ 4 ครั้งแรก เอฟเฟกต์เรโซแนนซ์: 2 เทิร์นก่อนเริ่มการต่อสู้ เมื่อมีเพื่อนร่วมทีมอย่างน้อย 2 คนที่มีคุณลักษณะเหมือนกับผู้สวมใส่ ความเสียหายจากคุณลักษณะธรรมชาติที่ผู้สวมใส่ได้รับจะลดลง 20% และเพื่อนร่วมทีมที่มีคุณลักษณะเหมือนกันจะได้รับความเสียหายคริติคอลลดลง 10% (เอฟเฟกต์เรโซแนนซ์มีผลได้ก็ต่อเมื่อมีอุปกรณ์หลายชิ้นเท่านั้น)',
		describe_in = 'Dalam pertarungan, kemampuan pengurangan kerusakan khusus pemakai akan meningkat sementara sebanyak $(20+(skillLevel-1)*2)$% sebelum menerima 4 serangan khusus pertama. Efek Resonansi: Selama 2 giliran sebelum pertarungan dimulai, jika ada 2 atau lebih rekan tim dengan atribut yang sama dengan pemakai, kerusakan atribut alami yang diterima pemakai berkurang 20%, dan rekan tim dengan atribut yang sama menerima pengurangan 10% kerusakan kritis (efek resonansi hanya berlaku jika ada beberapa perlengkapan).',
		describe_ph = 'Sa laban, ang kakayahang magpababa ng espesyal na pinsala ng nagsusuot ay pansamantalang tataas ng $(20+(skillLevel-1)*2)$% bago makatanggap ng unang 4 na espesyal na atake. Resonance Effect: Sa loob ng 2 na round bago magsimula ang laban, kung mayroong 2 o higit pang mga kakampi na may parehong katangian tulad ng nagsusuot, babawasan ng 20% ang likas na pinsalang natatanggap ng nagsusuot, at ang mga kakampi na may parehong katangian ay mababawasan ng 10% ang critical damage (ang resonance effect ay epektibo lamang kapag may maraming kagamitan).',
		describe_ma = 'Dalam pertempuran, keupayaan pengurangan kerosakan khas pemakai akan meningkat buat sementara sebanyak $(20+(skillLevel-1)*2)$% sebelum menerima 4 serangan khas pertama. Kesan Resonans: Selama 2 pusingan sebelum pertempuran bermula, jika terdapat 2 atau lebih rakan sepasukan dengan atribut yang sama seperti pemakai, kerosakan atribut semula jadi yang diterima pemakai dikurangkan sebanyak 20%, dan rakan sepasukan dengan atribut sama menerima pengurangan 10% kerosakan kritikal (kesan resonans hanya berkesan dengan beberapa peralatan).',
		describe = 'In battle, the wearer’s special damage reduction increases temporarily by $(20+(skillLevel-1)*2)$% before receiving the first 4 special attacks. Resonance Effect: For 2 turns before battle starts, if there are 2 or more teammates with the same attribute as the wearer, the wearer’s natural attribute damage received is reduced by 20%, and teammates with the same attribute receive 10% less critical damage (resonance effect can only be effective with multiple equipment).',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		alwaysEffective = true,
		passivePriority = 3,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {520101}
