	[52014] = {
		id = 52014,
		skillName_vn = 'Mang theo đạo cụ - Phản khống',
		skillName_en = 'Carry the props - Counter',
		skillName_th = 'พกอุปกรณ์ - ต้าน',
		skillName_in = 'Bawa alat peraga - Melawan',
		skillName_ph = 'Magdala ng kagamitan - Kontra',
		skillName_ma = 'Bawa alat peraga - Menangkis',
		skillName = 'Carry the props - Counter',
		describe_vn = 'Trong chiến đấu, trước khi lượt hành động của bản thân bắt đầu, có $(14+(skillLevel-1)*1)$% xác suất làm tê liệt ngẫu nhiên một anh hùng địch không trong trạng thái khống chế, kéo dài 1 lượt (nếu bản thân đang trong trạng thái khống chế, tăng thêm 10% xác suất), hiệu quả thực tế kích hoạt 3 lần sẽ không còn kích hoạt nữa',
		describe_en = 'In battle, before your turn begins, there is a $(14+(skillLevel-1)*1)$% chance to paralyze a random enemy hero who is not under control status for 1 turn (if you are under control status, the chance increases by 10%). The effect will no longer activate after triggering 3 times.',
		describe_th = 'ในการต่อสู้ ก่อนเริ่มเทิร์นของตนเอง จะมีโอกาส $(14+(skillLevel-1)*1)$% ที่จะทำให้ฮีโร่ศัตรูที่ไม่ได้อยู่ในสถานะควบคุมเป็นอัมพาตเป็นเวลา 1 เทิร์น (ถ้าตัวเองอยู่ในสถานะควบคุม โอกาสจะเพิ่มขึ้นอีก 10%) ผลลัพธ์จะไม่สามารถเปิดใช้ได้อีกหลังจากถูกกระตุ้น 3 ครั้งแล้ว',
		describe_in = 'Dalam pertempuran, sebelum giliran Anda dimulai, ada peluang sebesar $(14+(skillLevel-1)*1)$% untuk melumpuhkan secara acak satu hero musuh yang tidak dalam status terkendali selama 1 giliran (jika Anda dalam status terkendali, peluang bertambah 10%). Efek ini tidak akan aktif lagi setelah dipicu 3 kali.',
		describe_ph = 'Sa labanan, bago magsimula ang iyong turn, may $(14+(skillLevel-1)*1)$% na tsansa na ma-paralyze ang random na kalabang hero na hindi kontrolado ng estado sa loob ng 1 turn (kung ikaw ay nasa ilalim ng kontrol, tataas ng 10% ang tsansa). Hindi na muling magtataguyod ang epektong ito pagkatapos na ma-trigger ng 3 beses.',
		describe_ma = 'Dalam pertempuran, sebelum giliran anda bermula, terdapat peluang sebanyak $(14+(skillLevel-1)*1)$% untuk melumpuhkan secara rawak seorang wira musuh yang tidak berada di bawah kawalan selama 1 giliran (jika anda berada dalam keadaan terkawal, peluang meningkat sebanyak 10%). Kesan ini tidak akan diaktifkan lagi selepas dicetuskan 3 kali.',
		describe = 'In battle, before your turn begins, there is a $(14+(skillLevel-1)*1)$% chance to paralyze a random enemy hero who is not under control status for 1 turn (if you are under control status, the chance increases by 10%). The effect will no longer activate after triggering 3 times.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 23,
		posChoose = 5,
		skillProcess = {520141, 520142}
