	[52015] = {
		id = 52015,
		skillName_vn = 'Mang theo đạo cụ - Phục hồi',
		skillName_en = 'Carry props - Recover',
		skillName_th = 'พกอุปกรณ์ - ฟื้นฟู',
		skillName_in = 'Bawa perlengkapan - Pemulihan',
		skillName_ph = 'Magdala ng gamit - Pagpapagaling',
		skillName_ma = 'Bawa alat - Pemulihan',
		skillName = 'Carry props - Recover',
		describe_vn = 'Trong trận chiến, sau khi đồng đội khác ngoài bản thân sử dụng kỹ năng tuyệt chiêu, hồi phục lượng máu bằng sát thương gây ra bởi kỹ năng tuyệt chiêu lần này của bản thân *$(18+(skillLevel-1)*2)$%, tối đa kích hoạt 5 lần',
		describe_en = 'In battle, after teammates other than yourself use a special skill, recover health based on the damage dealt by your own special skill this time *$(18+(skillLevel-1)*2)$%, can activate up to 5 times.',
		describe_th = 'ในสนามรบ หลังจากที่เพื่อนร่วมทีมคนอื่นนอกจากตัวคุณใช้ทักษะพิเศษ ฟื้นฟูพลังชีวิตตามความเสียหายที่เกิดจากทักษะพิเศษของคุณเองครั้งนี้ *$(18+(skillLevel-1)*2)$%, สามารถเปิดใช้งานได้สูงสุด 5 ครั้ง',
		describe_in = 'Dalam pertempuran, setelah rekan satu tim selain diri Anda menggunakan skill spesial, pulihkan kesehatan berdasarkan kerusakan yang ditimbulkan oleh skill spesial Anda kali ini *$(18+(skillLevel-1)*2)$%, maksimum aktivasi 5 kali.',
		describe_ph = 'Sa laban, pagkatapos gamitin ng ibang kasama sa koponan maliban sa sarili mo ang espesyal na kasanayan, mag-recover ng health base sa damage na dulot ng sariling espesyal na kasanayan ngayong pagkakataon *$(18+(skillLevel-1)*2)$%, maximum na puwedeng mag-activate ng 5 beses.',
		describe_ma = 'Dalam pertempuran, selepas rakan sepasukan selain diri anda menggunakan kemahiran istimewa, pulihkan kesihatan berdasarkan kerosakan yang disebabkan oleh kemahiran istimewa anda kali ini *$(18+(skillLevel-1)*2)$%, maksimum diaktifkan 5 kali.',
		describe = 'In battle, after teammates other than yourself use a special skill, recover health based on the damage dealt by your own special skill this time *$(18+(skillLevel-1)*2)$%, can activate up to 5 times.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		alwaysEffective = true,
		passivePriority = 3,
