	[52018] = {
		id = 52018,
		skillName_vn = 'Mang theo đạo cụ - Phục hồi',
		skillName_en = 'Carry props - Restore',
		skillName_th = 'พกอุปกรณ์ - ฟื้นฟู',
		skillName_in = 'Bawa alat - Pulihkan',
		skillName_ph = 'Magdala ng gamit - Magpagaling',
		skillName_ma = 'Bawa alat - Pulih',
		skillName = 'Carry props - Restore',
		describe_vn = 'Trong 2 lượt lớn đầu tiên của trận đấu, mỗi khi bắt đầu lượt lớn sẽ hồi phục $(100+(skillLevel-1)*15)$ điểm nộ khí cho bản thân; trong 4 lượt lớn đầu tiên của trận đấu, mỗi khi bắt đầu lượt lớn sẽ tăng $(8+(skillLevel-1)*1)$% tỷ lệ khống chế (tổng cộng trong chế độ đấu đơn)#F10# #F40##L10#Khống chế mạnh mẽ:#L0#Trong 4 lượt đầu tiên của trận đấu, sau khi kết thúc lượt hành động của bản thân, có 35% xác suất khống chế ngẫu nhiên một anh hùng địch (một trong các hiệu ứng: choáng, ngủ, câm lặng, tê liệt, hỗn loạn)',
		describe_en = 'In the first 2 main turns of the battle, at the start of each main turn, recover $(100+(skillLevel-1)*15)$ anger points for yourself; in the first 4 main turns of the battle, at the start of each main turn, increase control rate by $(8+(skillLevel-1)*1)$% (accumulated in single battle mode).#F10# #F40##L10#Strong Control:#L0#In the first 4 turns of the battle, after finishing your action turn, there is a 35% chance to randomly control an enemy hero (one of the effects: stun, sleep, silence, paralysis, chaos).',
		describe_th = 'ใน 2 เทิร์นใหญ่แรกของการต่อสู้ เมื่อเริ่มต้นเทิร์นใหญ่แต่ละครั้ง จะฟื้นฟูพลังโกรธให้ตัวเอง $(100+(skillLevel-1)*15)$ แต้ม; ใน 4 เทิร์นใหญ่แรกของการต่อสู้ เมื่อเริ่มต้นเทิร์นใหญ่แต่ละครั้ง จะเพิ่มอัตราควบคุมได้ $(8+(skillLevel-1)*1)$% (สะสมในโหมดต่อสู้เดี่ยว)#F10# #F40##L10#การควบคุมอย่างทรงพลัง:#L0#ใน 4 เทิร์นแรกของการต่อสู้ หลังจากจบเทิร์นการกระทำของตัวเอง มีโอกาส 35% ที่จะควบคุมฮีโร่ศัตรูแบบสุ่ม (หนึ่งในผล: มึนงง, หลับ, เงียบ, ชา, สับสน)',
		describe_in = 'Dalam 2 giliran besar pertama pertempuran, setiap kali giliran besar dimulai, pulihkan $(100+(skillLevel-1)*15)$ poin kemarahan untuk diri sendiri; dalam 4 giliran besar pertama pertempuran, setiap kali giliran besar dimulai, tingkatkan tingkat kontrol sebesar $(8+(skillLevel-1)*1)$% (terakumulasi dalam mode duel tunggal).#F10# #F40##L10#Kontrol Kuat:#L0#Dalam 4 giliran pertama pertempuran, setelah menyelesaikan giliran aksi sendiri, ada peluang 35% untuk mengontrol secara acak pahlawan musuh (salah satu efek: terpukul, tidur, senyap, kelumpuhan, kekacauan).',
		describe_ph = 'Sa unang 2 malaking turno ng laban, sa simula ng bawat malaking turno ay gagalingin ang $(100+(skillLevel-1)*15)$ puntos ng galit para sa sarili; sa unang 4 malaking turno ng laban, sa simula ng bawat malaking turno ay tumaas ang porsyento ng kontrol ng $(8+(skillLevel-1)*1)$% (nakaipon sa single battle mode).#F10# #F40##L10#Malakas na Kontrol:#L0#Sa unang 4 turno ng laban, matapos matapos ang sariling aksyon, may 35% pagkakataon na kontrolin nang random ang isang kalabang bayani (isa sa mga epekto: stun, tulog, katahimikan, paralisis, kaguluhan).',
		describe_ma = 'Dalam 2 pusingan besar pertama pertempuran, setiap kali pusingan besar bermula, pulihkan $(100+(skillLevel-1)*15)$ mata kemarahan untuk diri sendiri; dalam 4 pusingan besar pertama pertempuran, setiap kali pusingan besar bermula, tingkatkan kadar kawalan sebanyak $(8+(skillLevel-1)*1)$% (terakumulasi dalam mod pertempuran tunggal).#F10# #F40##L10#Kawalan Kuat:#L0#Dalam 4 pusingan pertama pertempuran, selepas tamat pusingan tindakan sendiri, terdapat peluang 35% untuk mengawal secara rawak wira musuh (salah satu kesan: pening, tidur, senyap, lumpuh, kekacauan).',
		describe = 'In the first 2 main turns of the battle, at the start of each main turn, recover $(100+(skillLevel-1)*15)$ anger points for yourself; in the first 4 main turns of the battle, at the start of each main turn, increase control rate by $(8+(skillLevel-1)*1)$% (accumulated in single battle mode).#F10# #F40##L10#Strong Control:#L0#In the first 4 turns of the battle, after finishing your action turn, there is a 35% chance to randomly control an enemy hero (one of the effects: stun, sleep, silence, paralysis, chaos).',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		alwaysEffective = true,
		passivePriority = 3,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {520181}
	},
	[52019] = {
		id = 52019,
		skillName_vn = 'Mang theo đạo cụ - Khôi phục',
		skillName_en = 'Carry the prop - Restore',
		skillName_th = 'พกพร็อพ - กู้คืน',
		skillName_in = 'Bawa properti - Pulihkan',
		skillName_ph = 'Dalhin ang kagamitan - Ibalik',
		skillName_ma = 'Bawa alat - Pulihkan',
		skillName = 'Carry the prop - Restore',
		describe_vn = 'Sau khi người đeo giải phóng các kỹ năng hoạt động không phải kỹ năng, giới hạn máu cơ bản của người dùng sẽ tăng thêm $(12+(skillLevel-1)*1)$%. Khi chiêu thức đặc biệt được tung ra, nó sẽ tạm thời tăng phần thưởng sát thương tiêu diệt đặc biệt của người dùng thêm $(15+(skillLevel-1)*1.5)$%. Nó cũng sẽ gây sát thương thực tế bằng 8% máu tối đa của bản thân cho mục tiêu chính và một mục tiêu ngẫu nhiên trong trạng thái tàng hình của kẻ thù. Nó sẽ được kích hoạt hai lần trên sân (tích lũy trong toàn bộ trò chơi ở chế độ chơi đơn).',
		describe_en = 'After the wearer activates non-skill operational abilities, the user\'s basic HP limit will increase by $(12+(skillLevel-1)*1)$%. When the special move is unleashed, it temporarily increases the user\'s special kill damage reward by $(15+(skillLevel-1)*1.5)$%. It also deals true damage equal to 8% of the user\'s maximum HP to the main target and one random enemy target in stealth. This effect triggers twice on the field (accumulated throughout the entire game in single-player mode).',
		describe_th = 'หลังจากที่ผู้สวมใส่ปลดปล่อยทักษะปฏิบัติการที่ไม่ใช่ทักษะ ขีดจำกัดเลือดพื้นฐานของผู้ใช้จะเพิ่มขึ้น $(12+(skillLevel-1)*1)$% เมื่อปล่อยท่าไม้ตายพิเศษ จะเพิ่มรางวัลความเสียหายจากการสังหารพิเศษของผู้ใช้ชั่วคราวอีก $(15+(skillLevel-1)*1.5)$% นอกจากนี้ยังสร้างความเสียหายจริงเท่ากับ 8% ของพลังชีวิตสูงสุดของตัวเองต่อเป้าหมายหลักและเป้าหมายสุ่มหนึ่งตัวในสถานะล่องหนของศัตรู เอฟเฟกต์นี้จะถูกเปิดใช้งานสองครั้งบนสนาม (สะสมได้ทั้งเกมในโหมดเล่นคนเดียว)',
		describe_in = 'Setelah pemakai melepaskan kemampuan aktif yang bukan skill, batas darah dasar pengguna akan meningkat sebesar $(12+(skillLevel-1)*1)$%. Ketika jurus khusus dikeluarkan, itu akan sementara meningkatkan hadiah kerusakan pembunuhan khusus pengguna sebesar $(15+(skillLevel-1)*1.5)$%. Itu juga akan memberikan kerusakan nyata sebesar 8% dari darah maksimum pengguna pada target utama dan satu target acak yang sedang dalam keadaan sembunyi musuh. Efek ini akan diaktifkan dua kali di medan pertempuran (terakumulasi di seluruh permainan dalam mode pemain tunggal).',
		describe_ph = 'Matapos gamitin ng nagsusuot ang mga aktibong kasanayan na hindi kasanayan, tataas ang pangunahing limitasyon ng HP ng gumagamit ng $(12+(skillLevel-1)*1)$%. Kapag inilabas ang espesyal na kilos, pansamantalang tataas nito ang gantimpala sa pinsala ng espesyal na pagpatay ng gumagamit ng $(15+(skillLevel-1)*1.5)$%. Magdudulot din ito ng totoong pinsala na katumbas ng 8% ng pinakamataas na HP ng sarili sa pangunahing target at isang random na target na nakatago sa mga kalaban. Ito ay maa-activate ng dalawang beses sa larangan (nakakabuo sa buong laro sa single-player mode).',
		describe_ma = 'Setelah pemakai melepaskan kemahiran aktif bukan kemahiran, had asas darah pengguna akan meningkat sebanyak $(12+(skillLevel-1)*1)$%. Apabila gerakan istimewa dilancarkan, ia akan menambah ganjaran kerosakan pembunuhan istimewa pengguna sebanyak $(15+(skillLevel-1)*1.5)$% buat sementara waktu. Ia juga akan menyebabkan kerosakan sebenar sebanyak 8% daripada darah maksimum diri sendiri kepada sasaran utama dan satu sasaran rawak dalam keadaan sembunyi musuh. Ia akan diaktifkan dua kali di medan (terakumulasi sepanjang permainan dalam mod pemain tunggal).',
		describe = 'After the wearer activates non-skill operational abilities, the user\'s basic HP limit will increase by $(12+(skillLevel-1)*1)$%. When the special move is unleashed, it temporarily increases the user\'s special kill damage reward by $(15+(skillLevel-1)*1.5)$%. It also deals true damage equal to 8% of the user\'s maximum HP to the main target and one random enemy target in stealth. This effect triggers twice on the field (accumulated throughout the entire game in single-player mode).',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		alwaysEffective = true,
		passivePriority = 3,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {520191}
	},
	[52020] = {
		id = 52020,
		skillName_vn = 'Đạo cụ mang theo - Bạo kích',
		skillName_en = 'Carried items - Critical hit',
		skillName_th = 'ไอเท็มที่พกพา - โอกาสคริติคอล',
		skillName_in = 'Barang yang dibawa - Serangan kritis',
		skillName_ph = 'Mga dala na gamit - Kritikal na tama',
		skillName_ma = 'Barang dibawa - Serangan kritikal',
		skillName = 'Carried items - Critical hit',
		describe_vn = 'Trong trận chiến, trong 2 lượt hành động đầu tiên của bạn, các đòn tấn công kỹ năng sẽ gây thêm $(15+(skillLevel-1)*1.5)$% sát thương cho mục tiêu và sát thương của đòn tấn công này sẽ không khôi phục lại sự tức giận của mục tiêu\n#F10# \n#F40##L10#Blood cuồng nộ crit: #L0# Khi đòn tấn công đặc biệt chí mạng vào mục tiêu chính, nó sẽ gây ra 20% sát thương lan cho các mục tiêu xung quanh và kẻ thù Đòn tấn công kỹ năng chủ động tiếp theo của anh hùng sẽ bị tránh sau khi chí mạng (hiệu ứng chí mạng cuồng nộ máu có thời gian hồi chiêu là 5 hiệp và chỉ có thể được kích hoạt 2 lần trên toàn sân)',
		describe_en = 'In battle, during your first 2 action turns, skill attack moves deal an additional $(15+(skillLevel-1)*1.5)$% damage to the target, and damage from these attacks will not restore the target\'s rage. Blood Rage Crit: When a special critical attack hits the main target, it deals 20% splash damage to surrounding enemies. The hero\'s next active skill attack will be evaded after a critical hit (the Blood Rage Crit effect has a cooldown of 5 rounds and can only be triggered twice per entire battlefield).',
		describe_th = 'ในการต่อสู้ใน 2 เทิร์นการกระทำแรกของคุณ การโจมตีด้วยทักษะจะสร้างความเสียหายเพิ่มเติม $(15+(skillLevel-1)*1.5)$% ให้กับเป้าหมาย และความเสียหายจากการโจมตีนี้จะไม่ฟื้นฟูความโกรธของเป้าหมาย Blood Rage Crit: เมื่อการโจมตีพิเศษคริติคอลโดนเป้าหมายหลัก จะสร้างความเสียหายลาม 20% ให้กับเป้าหมายรอบข้าง และศัตรู การโจมตีทักษะที่ใช้งานครั้งถัดไปของฮีโร่จะถูกหลบหลังกการคริติคอล (เอฟเฟกต์ Blood Rage Crit มีคูลดาวน์ 5 เทิร์นและสามารถเปิดใช้ได้เพียง 2 ครั้งทั่วทั้งสนาม)',
		describe_in = 'Dalam pertarungan, selama 2 giliran aksi pertama Anda, serangan keterampilan memberikan tambahan $(15+(skillLevel-1)*1.5)$% kerusakan ke target dan kerusakan dari serangan ini tidak akan mengembalikan kemarahan target. Blood Rage Crit: Ketika serangan kritis khusus mengenai target utama, itu menyebabkan 20% kerusakan area ke musuh di sekitarnya. Serangan keterampilan aktif pahlawan berikutnya akan dihindari setelah serangan kritis (efek Blood Rage Crit memiliki cooldown 5 giliran dan hanya dapat diaktifkan 2 kali di seluruh medan perang).',
		describe_ph = 'Sa laban, sa unang 2 na mga action turn mo, ang mga skill attack ay magdudulot ng dagdag na $(15+(skillLevel-1)*1.5)$% na damage sa target at ang damage nito ay hindi magre-restore ng galit ng target. Blood Rage Crit: Kapag nag-critical hit ang special attack sa pangunahing target, magdudulot ito ng 20% splash damage sa mga kalapit na kalaban. Ang susunod na active skill attack ng hero ay maiiwasan pagkatapos ng critical hit (ang Blood Rage Crit effect ay may cooldown na 5 rounds at maaari lamang ma-activate nang 2 beses sa buong battlefield).',
		describe_ma = 'Dalam pertempuran, dalam 2 giliran tindakan pertama anda, serangan kemahiran akan menyebabkan tambahan $(15+(skillLevel-1)*1.5)$% kerosakan kepada sasaran dan kerosakan daripada serangan ini tidak akan memulihkan kemarahan sasaran. Blood Rage Crit: Apabila serangan kritikal istimewa mengenai sasaran utama, ia menyebabkan 20% kerosakan berleluasa kepada musuh di sekeliling. Serangan kemahiran aktif seterusnya wira akan dielakkan selepas serangan kritikal (kesan Blood Rage Crit mempunyai waktu rehat 5 pusingan dan hanya boleh diaktifkan 2 kali di seluruh medan).',
		describe = 'In battle, during your first 2 action turns, skill attack moves deal an additional $(15+(skillLevel-1)*1.5)$% damage to the target, and damage from these attacks will not restore the target\'s rage. Blood Rage Crit: When a special critical attack hits the main target, it deals 20% splash damage to surrounding enemies. The hero\'s next active skill attack will be evaded after a critical hit (the Blood Rage Crit effect has a cooldown of 5 rounds and can only be triggered twice per entire battlefield).',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		alwaysEffective = true,
		passivePriority = 3,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {520201}
	},
	[52021] = {
		id = 52021,
		skillName_vn = 'Mang đạo cụ - Quỷ Long',
