	[70511] = {
		id = 70511,
		skillName_vn = 'Hình Thái Thứ Ba: Mưa Mèo Tình Ái',
		skillName_en = 'Form III: Love Cat Shigure',
		skillName_th = 'ร่างที่ 3: แมวแห่งความรักในสายฝน',
		skillName_in = 'Bentuk Ketiga: Kucing Cinta di Tengah Hujan',
		skillName_ph = 'Ikatlong Anyo: Pusang Umiibig sa Ulan',
		skillName_ma = 'Bentuk Ketiga: Kucing Cinta di Hujan',
		skillName = 'Form III: Love Cat Shigure',
		describe_vn = 'Mitsuri Kanroji kích hoạt Chiêu III: Mưa Mèo Tình Ái, nhảy nhẹ như mèo và chém một mục tiêu địch duy nhất bằng lưỡi kiếm cong mềm mại của cô, gây#C0x3D8A99#180% Công đ.biệt#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#S.Thương đ.biệt#C0x5B545B#,Đặt lên mục tiêu <Bẫy Gai>,đồng thời tăng 20% Công đ.biệt bản thân trong 2 lượt\n#F10#\n#F40#<Bẫy Gai>: Có thể chồng 2 tầng,kích hoạt trước hành động mục tiêu,gây sát thương bẫy bằng 200% Công đ.biệt của người đặt.Khi bẫy phát động, gây thêm một tầng <Chảy máu> duy trì 2 lượt',
		describe_en = 'Mitsuri Kanroji activates Skill III: Love Cat Rain, leaps lightly like a cat and slashes a single enemy target with her soft curved blade, dealing #C0x3D8A99#180% Special ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Special DMG#C0x5B545B#, applies <Thorn Trap> to the target, and increases her own Special ATK by 20% for 2 turns\n#F10#\n#F40#<Thorn Trap>: Can stack up to 2 layers, activates before the target\'s action, dealing trap damage equal to 200% of the caster’s Special ATK. When triggered, adds one stack of <Bleed> lasting 2 turns.',
		describe_th = 'มิตสึริ คันโรจิ ใช้งานสกิล III: ฝนแมวแห่งรัก กระโดดเบาเหมือนแมวและฟันศัตรูเป้าหมายเดี่ยวด้วยดาบโค้งอ่อนนุ่มของเธอ สร้างความเสียหาย #C0x3D8A99#180% พลังพิเศษ#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ดาเมจพิเศษ#C0x5B545B# ใส่ <กับดักหนาม> ให้เป้าหมาย และเพิ่มพลังพิเศษของตัวเอง 20% เป็นเวลา 2 เทิร์น\n#F10#\n#F40#<กับดักหนาม>: ซ้อนทับได้สูงสุด 2 ชั้น ทำงานก่อนเป้าหมายจะเคลื่อนไหว สร้างดาเมจกับดัก 200% พลังพิเศษของผู้วาง เมื่อกับดักทำงาน จะเพิ่มสถานะ <เลือดไหล> 1 ชั้น นาน 2 เทิร์น',
		describe_in = 'Mitsuri Kanroji mengaktifkan Skill III: Hujan Kucing Cinta, melompat ringan seperti kucing dan menebas satu target musuh dengan pedang melengkung lembutnya, memberikan #C0x3D8A99#180% ATK Khusus#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#DMG Khusus#C0x5B545B#, menerapkan <Perangkap Duri> ke target, dan meningkatkan 20% ATK Khusus dirinya selama 2 giliran\n#F10#\n#F40#<Perangkap Duri>: Dapat ditumpuk hingga 2 lapis, aktif sebelum target bertindak, memberikan damage perangkap sebesar 200% ATK Khusus dari pengguna. Saat terpicu, memberikan tambahan satu lapis <Perdarahan> selama 2 giliran',
		describe_ph = 'Ina-activate ni Mitsuri Kanroji ang Kasanayan III: Ulan ng Pusang Pag-ibig, tumatalon nang magaan gaya ng pusa at humihiwa sa isang kalaban gamit ang kanyang malambot at hubog na espada, nagdudulot ng #C0x3D8A99#180% Espesyal na ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Espesyal na DMG#C0x5B545B#, naglalagay ng <Bitag ng Tinik> sa target, at nagpapataas ng sarili niyang Espesyal na ATK ng 20% sa loob ng 2 turns\n#F10#\n#F40#<Bitag ng Tinik>: Maaaring ma-stack hanggang 2 layer, uma-activate bago kumilos ang target, nagdudulot ng damage mula sa bitag na katumbas ng 200% Espesyal na ATK ng caster. Kapag na-trigger, nagdaragdag ng isang layer ng <Pagdurugo> na tumatagal ng 2 turn',
		describe_ma = 'Mitsuri Kanroji mengaktifkan Kemahiran III: Hujan Kucing Cinta, melompat ringan seperti kucing dan menebas satu sasaran musuh dengan pedang melengkung lembutnya, memberikan #C0x3D8A99#180% ATK Khas#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#DMG Khas#C0x5B545B#, mengenakan <Perangkap Duri> pada sasaran, serta meningkatkan 20% ATK Khas dirinya selama 2 pusingan\n#F10#\n#F40#<Perangkap Duri>: Boleh ditindan hingga 2 lapisan, diaktifkan sebelum tindakan sasaran, memberikan kerosakan perangkap sebanyak 200% ATK Khas pengguna. Apabila dicetuskan, menambah satu lapisan <Berdarah> selama 2 pusingan',
		describe = 'Life#C0x5C9970#+$skillLevel*0.1$%#C0x5B545B#\nCritical Resistance#C0x5C9970#+$skillLevel*0.1$%#C0x5B545B#',
		zawakeEffect = __data_t__zawakeEffect[70511],
		-- {79001}
		zawakeEffectDesc = 'Mitsuri Kanroji activates Form III: Koi Neko Shigure, gracefully leaping like a cat and slashing a single enemy target with her soft curved blade, dealing #C0x3D8A99#180% MAG#C0x5B545B#+$(skillLevel*4*24)$ magic damage #C0xF13B54##C0x5B545B#, setting <Thorn Trap> on the target, increasing her own MAG by 50% and increasing the control rate of charming allies by 20%, lasting for 2 turns.#F10##F40#<Thorn Trap>: Adds 2 stacks, triggers before the target moves, dealing 200% trap MAG damage to the caster. After the trap is triggered, 1 layer of <Bleed> is applied for 2 turns (Charming heroes are defined as all female heroes except zombies)',
		zawakeEffectDesc_en = 'Mitsuri Kanroji activates Form III: Koi Neko Shigure, gracefully leaping like a cat and slashing a single enemy target with her soft curved blade, dealing #C0x3D8A99#180% MAG#C0x5B545B#+$(skillLevel*4*24)$ magic damage #C0xF13B54##C0x5B545B#, setting <Thorn Trap> on the target, increasing her own MAG by 50% and increasing the control rate of charming allies by 20%, lasting for 2 turns.#F10##F40#<Thorn Trap>: Adds 2 stacks, triggers before the target moves, dealing 200% trap MAG damage to the caster. After the trap is triggered, 1 layer of <Bleed> is applied for 2 turns (Charming heroes are defined as all female heroes except zombies)',
		zawakeEffectDesc_th = 'มิตสึริ คันโรจิ เปิดใช้งานฟอร์ม III: โคอิ เนโกะ ชิกุเระ กระโดดเบา ๆ เหมือนแมวและฟันเป้าหมายศัตรูเพียงหนึ่งตัวด้วยดาบโค้งอ่อนของเธอ สร้างความเสียหายเวทมนตร์ #C0x3D8A99#180% MAG#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54##C0x5B545B# และวาง <กับดักหนาม> ไว้บนเป้าหมาย เพิ่ม MAG ของตัวเองขึ้น 50% และเพิ่มอัตราควบคุมของพันธมิตรที่มีเสน่ห์ขึ้น 20% เป็นเวลา 2 เทิร์น#F10##F40#<กับดักหนาม>: เพิ่ม 2 ชั้น ทำงานก่อนเป้าหมายจะเคลื่อนไหว สร้างความเสียหายเวทกับดัก 200% ให้กับผู้วาง หลังจากกับดักทำงาน จะได้รับ <เลือดออก> 1 ชั้น เป็นเวลา 2 เทิร์น (ฮีโร่ที่มีเสน่ห์คือฮีโร่ผู้หญิงทั้งหมด ยกเว้นซอมบี้)',
		zawakeEffectDesc_in = 'Mitsuri Kanroji mengaktifkan Form III: Koi Neko Shigure, melompat anggun seperti kucing dan menebas satu target musuh dengan pedang melengkung lembutnya, memberikan #C0x3D8A99#180% MAG#C0x5B545B#+$(skillLevel*4*24)$ damage sihir #C0xF13B54##C0x5B545B#, memasang <Perangkap Duri> pada target, meningkatkan MAG dirinya sendiri sebesar 50% dan meningkatkan rate kontrol dari sekutu yang menawan sebesar 20%, berlangsung selama 2 giliran.#F10##F40#<Perangkap Duri>: Menambahkan 2 tumpukan, aktif sebelum target bergerak, memberikan 200% damage perangkap MAG kepada pemasang. Setelah perangkap aktif, 1 lapisan <Perdarahan> diterapkan selama 2 giliran (Pahlawan menawan didefinisikan sebagai semua pahlawan wanita kecuali zombie)',
		zawakeEffectDesc_ph = 'Ina-activate ni Mitsuri Kanroji ang Form III: Koi Neko Shigure, magaan na tumatalon na parang pusa at humahampas sa isang kalabang target gamit ang kanyang malambot na hubog na espada, nagdudulot ng #C0x3D8A99#180% MAG#C0x5B545B#+$(skillLevel*4*24)$ magic damage #C0xF13B54##C0x5B545B#, naglalagay ng <Trap ng Tinik> sa target, pinapataas ang sariling MAG ng 50% at pinapataas ang control rate ng mga kaalyadong kaakit-akit ng 20%, tumatagal ng 2 turn.#F10##F40#<Trap ng Tinik>: Nagdaragdag ng 2 stack, na-aactivate bago gumalaw ang target, nagdudulot ng 200% trap MAG damage sa naglagay. Pagkatapos ma-activate ang trap, 1 stack ng <Pagdurugo> ay ilalapat sa loob ng 2 turn (Ang mga kaakit-akit na bayani ay lahat ng babaeng bayani maliban sa mga zombie)',
		zawakeEffectDesc_ma = 'Mitsuri Kanroji mengaktifkan Form III: Koi Neko Shigure, melompat ringan seperti kucing dan menetak satu sasaran musuh dengan pedang melengkung lembutnya, memberikan #C0x3D8A99#180% MAG#C0x5B545B#+$(skillLevel*4*24)$ kerosakan sihir #C0xF13B54##C0x5B545B#, menetapkan <Perangkap Duri> pada sasaran, meningkatkan MAG sendiri sebanyak 50% dan meningkatkan kadar kawalan sekutu yang menawan sebanyak 20%, bertahan selama 2 giliran.#F10##F40#<Perangkap Duri>: Menambah 2 lapisan, diaktifkan sebelum sasaran bergerak, memberikan 200% kerosakan sihir perangkap kepada si pemasang. Selepas perangkap diaktifkan, 1 lapisan <Pendarahan> akan dikenakan selama 2 giliran (Wira menawan ditakrifkan sebagai semua wira wanita kecuali zombi)',
		zawakeEffectDesc_vn = 'Mitsuri Kanroji kích hoạt Form III: Koi Neko Shigure, nhảy nhẹ như mèo và chém một mục tiêu địch duy nhất bằng lưỡi kiếm cong mềm mại của cô, gây #C0x3D8A99#180% MAG#C0x5B545B#+$(skillLevel*4*24)$ sát thương phép #C0xF13B54##C0x5B545B#, thiết lập <Bẫy Gai> lên mục tiêu, tăng MAG của bản thân thêm 50% và tăng tỷ lệ kiểm soát của đồng đội hấp dẫn thêm 20%, kéo dài trong 2 lượt.\n#F10#\n#F40#<Bẫy Gai>: Thêm 2 chồng, kích hoạt trước khi mục tiêu di chuyển, gây 200% sát thương bẫy MAG cho người thiết lập. Sau khi bẫy được kích hoạt, 1 lớp <Chảy máu> được áp dụng trong 2 lượt (Anh hùng hấp dẫn được định nghĩa là tất cả anh hùng nữ ngoại trừ thây ma)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Increases Magic Damage by 50% and boosts control rate of Charming allies by 20%',
