	[70512] = {
		id = 70512,
		skillName_vn = 'Chiêu V Đu Đưa Lãng Mạng',
		skillName_en = 'Skill V: Romantic Sway',
		skillName_th = 'สกิล V: แกว่งไกวสุดโรแมนติก',
		skillName_in = 'Skill V: Ayunan Romantis',
		skillName_ph = 'Kasanayan V: Romantikong Pag-ugoy',
		skillName_ma = 'Kemahiran V: Hayunan Romantis',
		skillName = 'Skill V: Romantic Sway',
		describe_vn = 'Mitsuri Kanroji kích hoạt Chiêu V: Đu Đưa Lãng Mạng,dùng khớp mềm linh hoạt vung mạnh Nhật Luân Kiếm,tạo vô số kiếm quang nhấn chìm hàng dọc địch, gây#C0x3D8A99#180% Công đ.biệt #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#S.thương đ.biệt#C0x5B545B#,Khiến mục tiêu rơi vào trạng thái <Mê Hoặc> 1 lượt\n#F10#\n#F40#Triệu hồi thủ hộ giả Iguro Obanai vào sân trong một lượt(lần đầu 2 lượt,kế thừa 200% Công vật lý) Chịu thay toàn bộ sát thương cho bản thân,khi triệu hồi lại Iguro Obanai hồi 300% Công đ.biệt tương đương máu\n#F10#\n#F40#Thủ hộ giả Iguro Obanai hỗ trợ tấn công gây #C0xE69900#160% Công v.lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#S.thương v.lý#C0x5B545B#,gây 2 lượt <Chảy Máu>, nếu mục tiêu đã <Chảy Máu> sẽ chuyển thành<Xé Rách>',
		describe_en = 'Mitsuri Kanroji activates Skill V: Romantic Sway, using her flexible joints to swing the Nichirin Blade powerfully, unleashing countless sword lights that engulf a vertical row of enemies, dealing #C0x3D8A99#180% Special ATK #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Special DMG#C0x5B545B#, inflicting <Charm> on the targets for 1 turn\n#F10#\n#F40#Summons the guardian Iguro Obanai to the field for one turn (first time: 2 turns, inherits 200% Physical ATK), takes all damage for Mitsuri. When re-summoned, Iguro Obanai heals HP equal to 300% of Mitsuri\'s Special ATK\n#F10#\n#F40#Iguro Obanai assists by attacking, dealing #C0xE69900#160% Physical ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Physical DMG#C0x5B545B#, inflicts <Bleed> for 2 turns; if the target is already <Bleeding>, it becomes <Lacerate>.',
		describe_th = 'มิตสึริ คันโรจิ ใช้งานสกิล V: แกว่งไกวสุดโรแมนติก ใช้ข้อต่อที่ยืดหยุ่นแกว่งดาบนิจิรินอย่างแรง สร้างแสงดาบนับไม่ถ้วนถาโถมใส่ศัตรูแนวตั้ง สร้างความเสียหาย #C0x3D8A99#180% พลังพิเศษ #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#ดาเมจพิเศษ#C0x5B545B# ทำให้เป้าหมายตกอยู่ในสถานะ <หลงใหล> 1 เทิร์น\n#F10#\n#F40#เรียกผู้พิทักษ์ อิกุโระ โอบาไน ลงสนาม 1 เทิร์น (ครั้งแรก 2 เทิร์น, รับพลังโจมตีกายภาพ 200%) รับความเสียหายแทนทั้งหมดให้มิตสึริ เมื่อเรียกใหม่อีกครั้ง อิกุโระจะฟื้น HP เท่ากับ 300% พลังพิเศษของมิตสึริ\n#F10#\n#F40#อิกุโระ โอบาไน ช่วยโจมตี สร้างความเสียหาย #C0xE69900#160% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#ดาเมจกายภาพ#C0x5B545B# สร้างสถานะ <เลือดไหล> 2 เทิร์น หากเป้าหมายมี <เลือดไหล> อยู่แล้ว จะเปลี่ยนเป็น <ฉีกขาด>',
		describe_in = 'Mitsuri Kanroji mengaktifkan Skill V: Ayunan Romantis, menggunakan persendian lenturnya untuk mengayunkan Pedang Nichirin dengan kuat, menciptakan cahaya pedang yang tak terhitung jumlahnya menyapu baris musuh vertikal, memberikan #C0x3D8A99#180% ATK Khusus #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#DMG Khusus#C0x5B545B#, membuat target terkena status <Terkesima> selama 1 giliran\n#F10#\n#F40#Memanggil pelindung Iguro Obanai ke medan selama satu giliran (pertama kali: 2 giliran, mewarisi 200% ATK Fisik), menyerap semua damage untuk Mitsuri. Saat dipanggil kembali, Iguro menyembuhkan HP setara dengan 300% ATK Khusus Mitsuri\n#F10#\n#F40#Iguro Obanai membantu menyerang, memberikan #C0xE69900#160% ATK Fisik#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#DMG Fisik#C0x5B545B#, memberikan efek <Berdarah> selama 2 giliran; jika target sudah <Berdarah>, berubah menjadi <Terkoyak>',
		describe_ph = 'Ina-activate ni Mitsuri Kanroji ang Kasanayan V: Romantikong Pag-ugoy, gamit ang malambot niyang kasukasuan para paikutin nang malakas ang Nichirin Blade, lumilikha ng maraming liwanag ng espada na nilalamon ang mga kalaban sa isang vertical na hilera, nagdudulot ng #C0x3D8A99#180% Espesyal na ATK #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Espesyal na DMG#C0x5B545B#, inilalagay ang target sa estado ng <Pagkaakit> sa loob ng 1 turno \n#F10#\n#F40#Tumatatawag kay Iguro Obanai bilang tagapangalaga sa loob ng isang turno (unang beses: 2 turno, minamana ang 200% Pisikal na ATK), tinatanggap ang lahat ng damage para kay Mitsuri. Sa muling pagtawag, pinapagaling ni Iguro ang HP katumbas ng 300% Espesyal na ATK ni Mitsuri\n#F10#\n#F40#Sumusuportang umatake si Iguro Obanai, nagdudulot ng #C0xE69900#160% Pisikal na ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Pisikal na DMG#C0x5B545B#, nagdudulot ng <Pagdurugo> sa loob ng 2 turno; kung ang target ay mayroon nang <Pagdurugo>, ito ay nagiging <Punit>',
		describe_ma = 'Mitsuri Kanroji mengaktifkan Kemahiran V: Hayunan Romantis, menggunakan sendi fleksibelnya untuk menghayun Pedang Nichirin dengan kuat, mencipta pancaran pedang yang tenggelamkan barisan menegak musuh, memberikan #C0x3D8A99#180% ATK Khas #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#DMG Khas#C0x5B545B#, menyebabkan sasaran terkena status <Terpesona> selama 1 pusingan\n#F10#\n#F40#Memanggil penjaga Iguro Obanai ke medan selama satu pusingan (kali pertama 2 pusingan, mewarisi 200% ATK Fizikal), menanggung semua kerosakan bagi pihak Mitsuri. Apabila dipanggil semula, Iguro memulihkan HP bersamaan 300% ATK Khas Mitsuri\n#F10#\n#F40#Iguro Obanai membantu menyerang, memberikan #C0xE69900#160% ATK Fizikal#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#DMG Fizikal#C0x5B545B#, memberikan kesan <Berdarah> selama 2 pusingan; jika sasaran sudah <Berdarah>, ia akan menjadi <Koyak>',
		describe = 'Dual Stance +$skillLevel*0.1$% Increase Damage +$skillLevel*0.1$%',
		zawakeEffect = __data_t__zawakeEffect[70512],
		-- {79002}
		zawakeEffectDesc = 'Mitsuri Kanroji activates Elemental Five: Swinging Romance, using her flexible joints to widely swing the Sun Blade, engulfing the enemy\'s formation in countless sword lights, dealing #C0x3D8A99#180% Mage Power #C0x5B545B#+$(skillLevel*4*48)$ among #C0xF13B54#magic damage #C0x5B545B#, inflicting <Charming> for 1 turn on the target#F10##F40#Summons Guardian Iguro Obanai to the field this turn (inherits 200% Physical Attack), and takes all damage. When summoned again, Guardian Iguro Xiaobanai fully recovers HP and resets its duration#F10##F40#Guardian Iguro Xiaobanai performs coordinated attacks with itself. When a charming ally attacks, Guardian Iguro Xiaobanai also performs a coordinated attack, dealing #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54#physical damage#C0x5B545B#, adding <Bleed> for 2 turns. When attacking a target already <Bleeding>, <Rip> will be applied instead.',
		zawakeEffectDesc_en = 'Mitsuri Kanroji activates Elemental Five: Swinging Romance, using her flexible joints to widely swing the Sun Blade, engulfing the enemy\'s formation in countless sword lights, dealing #C0x3D8A99#180% Mage Power #C0x5B545B#+$(skillLevel*4*48)$ among #C0xF13B54#magic damage #C0x5B545B#, inflicting <Charming> for 1 turn on the target#F10##F40#Summons Guardian Iguro Obanai to the field this turn (inherits 200% Physical Attack), and takes all damage. When summoned again, Guardian Iguro Xiaobanai fully recovers HP and resets its duration#F10##F40#Guardian Iguro Xiaobanai performs coordinated attacks with itself. When a charming ally attacks, Guardian Iguro Xiaobanai also performs a coordinated attack, dealing #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54#physical damage#C0x5B545B#, adding <Bleed> for 2 turns. When attacking a target already <Bleeding>, <Rip> will be applied instead.',
		zawakeEffectDesc_th = 'มิตสึริ คันโรจิ เปิดใช้งานธาตุทั้งห้า: Swinging Romance ใช้ข้อต่อที่ยืดหยุ่นของเธอเหวี่ยงดาบตะวันกว้าง กวาดศัตรูที่เรียงแถวด้วยแสงดาบนับไม่ถ้วน สร้างความเสียหายเวท #C0x3D8A99#180% พลังเวท #C0x5B545B#+$(skillLevel*4*48)$ รวม #C0xF13B54#ความเสียหายเวท#C0x5B545B# และทำให้เกิด <เสน่ห์> 1 เทิร์นกับเป้าหมาย#F10##F40#อัญเชิญผู้พิทักษ์ Iguro Obanai ลงสนามในเทิร์นนี้ (รับสืบทอดพลังโจมตีกายภาพ 200%) และรับความเสียหายทั้งหมด เมื่อถูกอัญเชิญอีกครั้ง Iguro Xiaobanai จะฟื้นฟู HP เต็มและรีเซ็ตระยะเวลา#F10##F40#ผู้พิทักษ์ Iguro Xiaobanai โจมตีร่วมกับตัวเอง เมื่อพันธมิตรที่มีเสน่ห์โจมตี ผู้พิทักษ์ก็จะโจมตีร่วมด้วย สร้างความเสียหายกายภาพ #C0xE69900#160% โจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ ของ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# และเพิ่ม <เลือดออก> 2 เทิร์น หากโจมตีเป้าหมายที่ <เลือดออก> อยู่แล้ว จะเปลี่ยนเป็น <ฉีกขาด>',
		zawakeEffectDesc_in = 'Mitsuri Kanroji mengaktifkan Lima Elemen: Swinging Romance, menggunakan persendian fleksibelnya untuk mengayunkan Pedang Matahari secara luas, membanjiri barisan musuh dengan cahaya pedang yang tak terhitung, memberikan #C0x3D8A99#180% Kekuatan Penyihir #C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54#damage sihir#C0x5B545B#, memberikan efek <Memikat> selama 1 giliran pada target#F10##F40#Memanggil Guardian Iguro Obanai ke arena pada giliran ini (mewarisi 200% Serangan Fisik), dan menerima semua damage. Saat dipanggil kembali, Guardian Iguro Xiaobanai memulihkan seluruh HP dan mengatur ulang durasi#F10##F40#Guardian Iguro Xiaobanai melakukan serangan gabungan dengan dirinya sendiri. Saat sekutu yang memikat menyerang, Guardian juga akan menyerang secara bersamaan, memberikan #C0xE69900#160% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54#damage fisik#C0x5B545B#, menambahkan efek <Berdarah> selama 2 giliran. Saat menyerang target yang sudah terkena <Berdarah>, <Mengoyak> akan diterapkan sebagai gantinya.',
		zawakeEffectDesc_ph = 'Ina-activate ni Mitsuri Kanroji ang Limang Elemento: Swinging Romance, gamit ang malalambot niyang kasukasuan upang iwasiwas nang malapad ang Araw na Espada, nilulunod ang hanay ng kalaban sa walang katapusang liwanag ng espada, nagdudulot ng #C0x3D8A99#180% Kapangyarihan ng Mago #C0x5B545B#+$(skillLevel*4*48)$ mula sa #C0xF13B54#magic damage#C0x5B545B#, naglalagay ng <Kaakit-akit> sa target sa loob ng 1 turn#F10##F40#Tatawagin si Guardian Iguro Obanai sa field ngayong turn (namamana ang 200% Physical Attack), at tinatanggap ang lahat ng damage. Kapag muling tinawag, si Guardian Iguro Xiaobanai ay magrerecover ng buong HP at ire-reset ang tagal#F10##F40#Si Guardian Iguro Xiaobanai ay umaatake kasabay ng sarili. Kapag ang isang kaalyadong kaakit-akit ay umatake, makikipag-combo rin si Guardian, nagdudulot ng #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ ng #C0xF13B54#physical damage#C0x5B545B#, nagbibigay ng <Pagdurugo> sa loob ng 2 turn. Kapag umatake sa target na may <Pagdurugo>, papalitan ito ng <Punit>.',
		zawakeEffectDesc_ma = 'Mitsuri Kanroji mengaktifkan Lima Elemen: Swinging Romance, menggunakan sendi fleksibelnya untuk menghayun Pedang Matahari dengan luas, menenggelamkan barisan musuh dalam cahaya pedang yang tidak terhitung, memberikan #C0x3D8A99#180% Kuasa Ahli Sihir #C0x5B545B#+$(skillLevel*4*48)$ daripada #C0xF13B54#kerosakan sihir#C0x5B545B#, menyebabkan <Menawan> selama 1 giliran ke atas sasaran#F10##F40#Memanggil Penjaga Iguro Obanai ke medan dalam giliran ini (mewarisi 200% Serangan Fizikal), dan menanggung semua kerosakan. Apabila dipanggil semula, Penjaga Iguro Xiaobanai memulihkan HP sepenuhnya dan menetapkan semula tempoh masa#F10##F40#Penjaga Iguro Xiaobanai melakukan serangan bersama dengan dirinya sendiri. Apabila sekutu menawan menyerang, Penjaga juga akan menyerang bersama, memberikan #C0xE69900#160% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ daripada #C0xF13B54#kerosakan fizikal#C0x5B545B#, menambah <Pendarahan> selama 2 giliran. Apabila menyerang sasaran yang sudah mengalami <Pendarahan>, <Koyak> akan digunakan sebagai ganti.',
		zawakeEffectDesc_vn = 'Mitsuri Kanroji kích hoạt Ngũ hệ: Swinging Romance, sử dụng các khớp linh hoạt của mình để vung rộng Lưỡi kiếm Mặt trời, nhấn chìm các mục tiêu xếp hàng của kẻ địch bằng vô số ánh sáng kiếm, gây ra #C0x3D8A99#180% Công pháp sư #C0x5B545B#+$(skillLevel*4*48)$ trong số #C0xF13B54# sát thương phép #C0x5B545B#, gây <Hấp dẫn> trong 1 lượt lên mục tiêu\n#F10#\n#F40# Triệu hồi Hộ vệ Iguro Obanai vào sân trong lượt này (thừa hưởng 200% Công vật lý), và tự chịu mọi sát thương. Khi được triệu hồi lần nữa, Hộ vệ Iguro Xiaobanai hồi phục toàn bộ HP và đặt lại thời gian hiệu lực\n#F10#\n#F40# Hộ vệ Iguro Xiaobanai tấn công phối hợp với chính nó. Khi một đồng đội có sức lôi cuốn tấn công, Guardian Iguro Xiaobanai cũng sẽ tấn công phối hợp, gây ra #C0xE69900#160% Tấn công vật lý#C0x5B545B#+$(skillLevel*4*48)$ của #C0xF13B54#sát thương vật lý#C0x5B545B#, thêm <Chảy máu> trong 2 lượt. Khi tấn công một mục tiêu đã <Chảy máu>, <Rip> sẽ được thêm vào thay thế.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Permanently summons the Guardian Iguro Xiaobanei for 2 turns; when a Charming ally attacks, the Guardian Iguro Xiaobanei performs a follow-up attack',
		zawakeSimpleDesc_en = '#C0x5c9970#Permanently summons the Guardian Iguro Xiaobanei for 2 turns; when a Charming ally attacks, the Guardian Iguro Xiaobanei performs a follow-up attack',
		zawakeSimpleDesc_th = '#C0x5c9970#อัญเชิญผู้พิทักษ์ Iguro Xiaobanei อย่างถาวรเป็นเวลา 2 เทิร์น; เมื่อพันธมิตรที่มีเสน่ห์โจมตี ผู้พิทักษ์ Iguro Xiaobanei จะโจมตีร่วม',
		zawakeSimpleDesc_in = '#C0x5c9970#Memanggil Penjaga Iguro Xiaobanei secara permanen selama 2 giliran; saat sekutu dengan pesona menyerang, Penjaga Iguro Xiaobanei akan ikut menyerang',
		zawakeSimpleDesc_ph = '#C0x5c9970#Permanenteng tinatawag si Iguro Xiaobanei ang Tagapangalaga sa loob ng 2 turn; kapag umatake ang Charming na kakampi, sasabay si Iguro Xiaobanei sa pag-atake',
		zawakeSimpleDesc_ma = '#C0x5c9970#Memanggil secara kekal Penjaga Iguro Xiaobanei selama 2 pusingan; apabila sekutu yang memikat menyerang, Penjaga Iguro Xiaobanei akan menyerang bersama',
		zawakeSimpleDesc_vn = '#C0x5c9970#Triệu hồi Người bảo vệ Iguro Xiaobanei vĩnh viễn trong 2 hiệp; khi một đồng đội có sức lôi cuốn tấn công, Người bảo vệ Iguro Xiaobanei sẽ tấn công phối hợp',
