	[70513] = {
		id = 70513,
		skillName_vn = 'Chiêu VI Phong Tình Miêu Bộ',
		skillName_en = 'Skill VI: Charming Cat Steps',
		skillName_th = 'สกิล VI: ก้าวย่างแมวเสน่ห์',
		skillName_in = 'Skill VI: Langkah Kucing Menawan',
		skillName_ph = 'Kasanayan VI: Hakbang ng Kaakit-akit na Pusa',
		skillName_ma = 'Kemahiran VI: Langkah Kucing Menawan',
		skillName = 'Skill VI: Charming Cat Steps',
		describe_vn = 'Mitsuri Kanroji kích hoạt Chiêu VI Phong Tình Miêu Bộ,xoay người và chém điên cuồng 3 mục tiêu địch ngẫu nhiên với tốc độ bão tố, gây#C0x3D8A99#350% Công đ.biệt#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#S.thương đ.biệt#C0x5B545B#,Khiến cả 3 rơi vào <Tranh Sủng> 1 lượt, giảm 30% song thủ trong 2 lượt\n#F10#\n#F40#<Tranh Sủng>:mục tiêu sẽ dùng đòn đánh thường tấn công lẫn nhaugiảm 30% song thủ đồng thời sát thương đánh thường tăng 300%\n#F10#\n#F40#Khi thủ hộ giả Iguro Obanai có mặt sẽ lập tức tấn công mục tiêu gây#C0xE69900#600% Công v.lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#S.thương v.lý',
		describe_en = 'Mitsuri Kanroji activates Skill VI: Charming Cat Steps, spins and furiously slashes 3 random enemy targets with storm-like speed, dealing #C0x3D8A99#350% Special ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#Special DMG#C0x5B545B#, causing all 3 to enter <Jealous Rivalry> for 1 turn, reducing both ATKs by 30% for 2 turns\n#F10#\n#F40#<Jealous Rivalry>: Targets will use normal attacks against each other, reducing both ATKs by 30% while normal attack damage is increased by 300%\n#F10#\n#F40#When guardian Iguro Obanai is present, he immediately attacks the target, dealing #C0xE69900#600% Physical ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Physical DMG',
		describe_th = 'มิตสึริ คันโรจิ ใช้งานสกิล VI: ก้าวย่างแมวเสน่ห์ หมุนตัวและฟันใส่ศัตรูแบบสุ่ม 3 ตัวด้วยความเร็วพายุ สร้างความเสียหาย #C0x3D8A99#350% พลังพิเศษ#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#ดาเมจพิเศษ#C0x5B545B# ทำให้ทั้ง 3 ตกอยู่ในสถานะ <แย่งความรัก> 1 เทิร์น ลดพลังโจมตีกายภาพและเวท 30% เป็นเวลา 2 เทิร์น\n#F10#\n#F40#<แย่งความรัก>: เป้าหมายจะโจมตีธรรมดาใส่กันเอง ลดพลังโจมตีทั้งสองด้าน 30% แต่ความเสียหายโจมตีธรรมดาเพิ่มขึ้น 300%\n#F10#\n#F40#หากอิกุโระ โอบาไนอยู่ในสนาม เขาจะโจมตีทันที สร้างความเสียหาย #C0xE69900#600% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#ดาเมจกายภาพ',
		describe_in = 'Mitsuri Kanroji mengaktifkan Skill VI: Langkah Kucing Menawan, berputar dan menebas 3 target musuh acak secara membabi buta dengan kecepatan badai, memberikan #C0x3D8A99#350% ATK Khusus#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#DMG Khusus#C0x5B545B#, menyebabkan ketiganya terkena efek <Bersaing Cinta> selama 1 giliran, mengurangi ATK fisik dan sihir sebesar 30% selama 2 giliran\n#F10#\n#F40#<Bersaing Cinta>: Target akan menyerang satu sama lain dengan serangan biasa, ATK fisik dan sihir berkurang 30% namun damage serangan biasa meningkat 300%\n#F10#\n#F40#Jika Iguro Obanai hadir, ia akan langsung menyerang target dan memberikan #C0xE69900#600% ATK Fisik#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#DMG Fisik',
		describe_ph = 'Ina-activate ni Mitsuri Kanroji ang Kasanayan VI: Hakbang ng Kaakit-akit na Pusa, umiikot at brutal na humihiwa sa 3 random na kalaban gamit ang bilis ng bagyo, nagdudulot ng #C0x3D8A99#350% Espesyal na ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#Espesyal na DMG#C0x5B545B#, inilalagay silang tatlo sa estado ng <Pag-aagawan ng Pagmamahal> sa loob ng 1 turno, binabawasan ang Physical at Magic ATK ng 30% sa loob ng 2 turns\n#F10#\n#F40#<Pag-aagawan ng Pagmamahal>: Mag-aattack ang mga target sa isa’t isa gamit ang normal attacks, bawas 30% ATK ngunit tataas ang damage ng normal attack ng 300%\n#F10#\n#F40#Kung naroon si Iguro Obanai, agad siyang aatake sa target at magdudulot ng #C0xE69900#600% Pisikal na ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Pisikal na DMG',
		describe_ma = 'Mitsuri Kanroji mengaktifkan Kemahiran VI: Langkah Kucing Menawan, berpusing dan menebas secara ganas 3 sasaran musuh rawak dengan kelajuan taufan, memberikan #C0x3D8A99#350% ATK Khas#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#DMG Khas#C0x5B545B#, menyebabkan ketiga-tiga terkena <Perebutan Kasih> selama 1 pusingan, mengurangkan 30% serangan fizikal dan magik selama 2 pusingan\n#F10#\n#F40#<Perebutan Kasih>: Sasaran akan menyerang sesama sendiri menggunakan serangan biasa, serangan fizikal dan magik berkurang 30% tetapi kerosakan serangan biasa meningkat 300%\n#F10#\n#F40#Jika penjaga Iguro Obanai berada di medan, dia akan terus menyerang sasaran dan memberikan #C0xE69900#600% ATK Fizikal#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#DMG Fizikal',
		describe = 'Dual Wield#C0x5C9970#+$skillLevel*0.1$%#C0x5B545B#\nDamage Reduction#C0x5C9970#+$skillLevel*0.1$%#C0x5B545B#',
		starEffect = __data_t__starEffect[70513],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Mục tiêu không thể nhận được buff trong 2 lượt, sau đó khiến tất cả kẻ địch đang chịu <Mê Hoặc> ngoại trừ mục tiêu chính sẽ tấn công một lần ngay lập tức. Sau đòn tấn công, một <Bẫy Gai> sẽ được thiết lập cho tất cả kẻ địch.',
		starEffectDesc = 'Enhanced Effect: The target cannot receive buffs for 2 turns. Then, all enemies under <Charm> except the main target will immediately perform one attack. After the attack, a <Thorn Trap> will be set on all enemies.',
		starEffectDesc_en = 'Enhanced Effect: The target cannot receive buffs for 2 turns. Then, all enemies under <Charm> except the main target will immediately perform one attack. After the attack, a <Thorn Trap> will be set on all enemies.',
		starEffectDesc_th = 'เอฟเฟกต์ที่เพิ่มขึ้น: เป้าหมายจะไม่สามารถได้รับบัฟเป็นเวลา 2 เทิร์น จากนั้นศัตรูทั้งหมดที่อยู่ในสถานะ <หลงใหล> ยกเว้นเป้าหมายหลักจะโจมตีทันทีหนึ่งครั้ง หลังจากการโจมตี จะมีการวาง <กับดักหนาม> ให้กับศัตรูทุกตัว',
		starEffectDesc_in = 'Efek Ditingkatkan: Target tidak dapat menerima buff selama 2 giliran. Setelah itu, semua musuh yang berada dalam status <Terkesima> kecuali target utama akan segera melakukan satu serangan. Setelah serangan, <Perangkap Duri> akan dipasang ke semua musuh.',
		starEffectDesc_ph = 'Pinahusay na Epekto: Ang target ay hindi makakatanggap ng buff sa loob ng 2 turno. Pagkatapos nito, lahat ng kalabang nasa ilalim ng <Pagkaakit> maliban sa pangunahing target ay agad na aatake isang beses. Pagkatapos ng pag-atake, isang <Bitag ng Tinikan> ang ilalagay sa lahat ng kalaban.',
		starEffectDesc_ma = 'Kesan Dipertingkat: Sasaran tidak boleh menerima buff selama 2 pusingan. Kemudian, semua musuh yang berada di bawah status <Terpesona> kecuali sasaran utama akan melancarkan satu serangan serta-merta. Selepas serangan, satu <Perangkap Duri> akan dipasang pada semua musuh.',
		zawakeEffect = __data_t__zawakeEffect[70513],
		-- {79003}
		zawakeEffectDesc = 'Mitsuri Kanroji activates Earth Element: Cat Foot Love Wind, flipping while slashing three random enemy targets at blinding speed, dealing #C0x3D8A99#350% magic damage#C0x5B545B#+$(skillLevel*4*42)$ among #C0xF13B54#magic damage#C0x5B545B#, creating three <Fight for Favor> that last for 1 turn and reducing the target\'s dual defense by 40% for 2 turns#F10##F40#<Fight for Favor>: Targets fight each other using normal attacks, reducing dual defense by 30% and increasing normal attack damage dealt by 300%#F10##F40#Guardian Iguro Koba: When on the field, it immediately attacks a target, dealing #C0xE69900#600% physical attack damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54#physical damage#C0x5B545B##F10##F40#After <Fight for Favor> ends, the targets will <Fall in Love> with Kanroji Mitsuri, lasting for 2 turns#F10##F40#<Fall in Love>: Unique effect, gains 20% double attack and 30% double defense from the target#F10##F40#After the final strike ends, all charmed enemy targets will voluntarily donate 10% of their max HP to Kanroji Mitsuri',
		zawakeEffectDesc_en = 'Mitsuri Kanroji activates Earth Element: Cat Foot Love Wind, flipping while slashing three random enemy targets at blinding speed, dealing #C0x3D8A99#350% magic damage#C0x5B545B#+$(skillLevel*4*42)$ among #C0xF13B54#magic damage#C0x5B545B#, creating three <Fight for Favor> that last for 1 turn and reducing the target\'s dual defense by 40% for 2 turns#F10##F40#<Fight for Favor>: Targets fight each other using normal attacks, reducing dual defense by 30% and increasing normal attack damage dealt by 300%#F10##F40#Guardian Iguro Koba: When on the field, it immediately attacks a target, dealing #C0xE69900#600% physical attack damage#C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54#physical damage#C0x5B545B##F10##F40#After <Fight for Favor> ends, the targets will <Fall in Love> with Kanroji Mitsuri, lasting for 2 turns#F10##F40#<Fall in Love>: Unique effect, gains 20% double attack and 30% double defense from the target#F10##F40#After the final strike ends, all charmed enemy targets will voluntarily donate 10% of their max HP to Kanroji Mitsuri',
		zawakeEffectDesc_th = 'มิตสึริ คันโรจิ เปิดใช้งานธาตุดิน: Cat Foot Love Wind พลิกตัวขณะฟันศัตรูแบบสุ่ม 3 เป้าหมายด้วยความเร็วราวพายุ สร้างความเสียหายเวท #C0x3D8A99#350%#C0x5B545B#+$(skillLevel*4*42)$ จาก #C0xF13B54#ความเสียหายเวท#C0x5B545B# สร้าง <Fight for Favor> 3 ชุด คงอยู่ 1 เทิร์น และลดพลังป้องกันคู่ของเป้าหมายลง 40% เป็นเวลา 2 เทิร์น#F10##F40#<Fight for Favor>: เป้าหมายจะโจมตีกันด้วยการโจมตีปกติ ลดการป้องกันคู่ลง 30% และเพิ่มความเสียหายจากการโจมตีปกติขึ้น 300%#F10##F40#ผู้พิทักษ์ Iguro Koba: เมื่ออยู่ในสนาม จะโจมตีเป้าหมายทันที สร้างความเสียหายกายภาพ #C0xE69900#600% จากการโจมตีปกติ#C0x5B545B#+$(skillLevel*4*48)$ ของ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B##F10##F40#หลังจาก <Fight for Favor> จบลง เป้าหมายจะ <ตกหลุมรัก> คันโรจิ มิตสึริ เป็นเวลา 2 เทิร์น#F10##F40#<Fall in Love>: เอฟเฟกต์พิเศษ รับโบนัสโจมตีสองเท่า 20% และป้องกันสองเท่า 30% จากเป้าหมาย#F10##F40#หลังจากจบการโจมตีสุดท้าย เป้าหมายศัตรูที่ถูกล่อลวงทั้งหมดจะบริจาค 10% HP สูงสุดของตนให้กับ คันโรจิ มิตสึริ โดยสมัครใจ',
		zawakeEffectDesc_in = 'Mitsuri Kanroji mengaktifkan Elemen Tanah: Cat Foot Love Wind, membalik sambil menebas tiga target musuh acak dengan kecepatan luar biasa, memberikan #C0x3D8A99#350% damage sihir#C0x5B545B#+$(skillLevel*4*42)$ dari #C0xF13B54#damage sihir#C0x5B545B#, menciptakan tiga <Fight for Favor> yang bertahan selama 1 giliran dan mengurangi 40% pertahanan ganda target selama 2 giliran#F10##F40#<Fight for Favor>: Target bertarung satu sama lain dengan serangan normal, mengurangi pertahanan ganda sebesar 30% dan meningkatkan damage serangan normal sebesar 300%#F10##F40#Guardian Iguro Koba: Saat berada di medan, langsung menyerang target, memberikan #C0xE69900#600% damage serangan fisik#C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54#damage fisik#C0x5B545B##F10##F40#Setelah <Fight for Favor> berakhir, target akan <jatuh cinta> pada Kanroji Mitsuri selama 2 giliran#F10##F40#<Fall in Love>: Efek unik, menerima 20% serangan ganda dan 30% pertahanan ganda dari target#F10##F40#Setelah serangan terakhir berakhir, semua target musuh yang terpesona akan secara sukarela menyumbangkan 10% dari HP maksimum mereka kepada Kanroji Mitsuri',
		zawakeEffectDesc_ph = 'Ina-activate ni Mitsuri Kanroji ang Earth Element: Cat Foot Love Wind, umiikot habang hinihiwa ang tatlong random na kalabang target nang napakabilis, nagdudulot ng #C0x3D8A99#350% magic damage#C0x5B545B#+$(skillLevel*4*42)$ mula sa #C0xF13B54#magic damage#C0x5B545B#, lumilikha ng tatlong <Fight for Favor> na tumatagal ng 1 turn at nagpapababa ng 40% ng double defense ng target sa loob ng 2 turn#F10##F40#<Fight for Favor>: Ang mga target ay naglalaban gamit ang normal attacks, binabawasan ang double defense ng 30% at pinapataas ng 300% ang damage mula sa normal attacks#F10##F40#Guardian Iguro Koba: Kapag nasa field, agad na umaatake sa target, nagdudulot ng #C0xE69900#600% physical attack damage#C0x5B545B#+$(skillLevel*4*48)$ ng #C0xF13B54#physical damage#C0x5B545B##F10##F40#Pagkatapos ng <Fight for Favor>, ang mga target ay <ma-iin love> kay Kanroji Mitsuri sa loob ng 2 turn#F10##F40#<Fall in Love>: Natatanging epekto, tumatanggap ng 20% double attack at 30% double defense mula sa target#F10##F40#Matapos ang huling atake, lahat ng kalabang target na naakit ay kusang-loob na magdo-donate ng 10% ng kanilang max HP kay Kanroji Mitsuri',
		zawakeEffectDesc_ma = 'Mitsuri Kanroji mengaktifkan Elemen Bumi: Cat Foot Love Wind, berpusing sambil menetak tiga sasaran musuh rawak dengan kelajuan luar biasa, memberikan #C0x3D8A99#350% kerosakan sihir#C0x5B545B#+$(skillLevel*4*42)$ daripada #C0xF13B54#kerosakan sihir#C0x5B545B#, mencipta tiga <Fight for Favor> yang kekal selama 1 pusingan dan mengurangkan pertahanan berganda sasaran sebanyak 40% selama 2 pusingan#F10##F40#<Fight for Favor>: Sasaran bertarung sesama sendiri menggunakan serangan biasa, mengurangkan pertahanan berganda sebanyak 30% dan meningkatkan kerosakan serangan biasa sebanyak 300%#F10##F40#Guardian Iguro Koba: Apabila berada di medan, ia akan segera menyerang sasaran, memberikan #C0xE69900#600% kerosakan serangan fizikal#C0x5B545B#+$(skillLevel*4*48)$ daripada #C0xF13B54#kerosakan fizikal#C0x5B545B##F10##F40#Selepas <Fight for Favor> tamat, sasaran akan <jatuh cinta> pada Kanroji Mitsuri selama 2 pusingan#F10##F40#<Fall in Love>: Kesan unik, menerima 20% serangan berganda dan 30% pertahanan berganda daripada sasaran#F10##F40#Selepas serangan terakhir berakhir, semua sasaran musuh yang terpesona akan secara sukarela mendermakan 10% HP maksimum mereka kepada Kanroji Mitsuri',
		zawakeEffectDesc_vn = 'Mitsuri Kanroji kích hoạt Hệ đất: Cat Foot Love Wind, lật người trong khi chém ba mục tiêu địch ngẫu nhiên với tốc độ như vũ bão, gây ra #C0x3D8A99#350% sát thương phép#C0x5B545B#+$(skillLevel*4*42)$ trong số #C0xF13B54# sát thương phép#C0x5B545B#, khiến ba <Fight for Favor> tồn tại trong 1 hiệp và giảm 40% khả năng phòng thủ kép của mục tiêu trong 2 hiệp\n#F10#\n#F40#<Fight for Favor>: Các mục tiêu chiến đấu với nhau bằng các đòn tấn công thường, giảm 30% khả năng phòng thủ kép và tăng 300% sát thương gây ra bởi các đòn tấn công thường\n#F10#\n#F40#Guardian Iguro Koba Khi ở trong trường bên trong, nó sẽ ngay lập tức tấn công mục tiêu, gây ra #C0xE69900#600% sát thương vật lý đòn tấn công#C0x5B545B#+$(skillLevel*4*48)$ của #C0xF13B54# sát thương vật lý#C0x5B545B#\n#F10#\n#F40#Sau khi <Fight for Favor> kết thúc, mục tiêu sẽ <phải lòng> Kanroji Mitsuri, kéo dài trong 2 hiệp\n#F10#\n#F40#<Fall in Love>: Hiệu ứng độc nhất, nhận được 20% tấn công gấp đôi và 30% phòng thủ gấp đôi từ mục tiêu\n#F10#\n#F40#Sau khi đòn đánh cuối kết thúc, tất cả mục tiêu bị quyến rũ của kẻ địch sẽ tự nguyện hiến tặng 10% máu tối đa của chúng cho Kanroji Mitsuri',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'After <Fight for Favor> ends, the target will <Fall in Love> with Kanroji Mitsuri for 2 turns.\n#F10#\n#F40#<Fall in Love>: Unique effect, gains 20% double attack and 30% double defense from the target.\n#F10#\n#F40#After the final attack ends, all Charmed enemy targets will voluntarily donate 10% of their max HP to Kanroji Mitsuri.',
		zawakeSimpleDesc_en = 'After <Fight for Favor> ends, the target will <Fall in Love> with Kanroji Mitsuri for 2 turns.\n#F10#\n#F40#<Fall in Love>: Unique effect, gains 20% double attack and 30% double defense from the target.\n#F10#\n#F40#After the final attack ends, all Charmed enemy targets will voluntarily donate 10% of their max HP to Kanroji Mitsuri.',
		zawakeSimpleDesc_th = 'หลังจาก <Fight for Favor> สิ้นสุด เป้าหมายจะ <ตกหลุมรัก> Kanroji Mitsuri เป็นเวลา 2 เทิร์น\n#F10#\n#F40#<ตกหลุมรัก>: เอฟเฟกต์พิเศษ ได้รับ 20% โจมตีคู่ และ 30% ป้องกันคู่ จากเป้าหมาย\n#F10#\n#F40#เมื่อการโจมตีสุดท้ายสิ้นสุดลง เป้าหมายศัตรูที่หลงเสน่ห์ทั้งหมดจะบริจาค 10% ของ HP สูงสุดให้กับ Kanroji Mitsuri โดยสมัครใจ',
		zawakeSimpleDesc_in = 'Setelah <Fight for Favor> berakhir, target akan <Jatuh Cinta> pada Kanroji Mitsuri selama 2 giliran\n#F10#\n#F40#<Jatuh Cinta>: Efek unik, menerima 20% serangan ganda dan 30% pertahanan ganda dari target.\n#F10#\n#F40#Setelah serangan terakhir selesai, semua target musuh yang terpesona akan secara sukarela menyumbangkan 10% HP maksimum mereka kepada Kanroji Mitsuri.',
		zawakeSimpleDesc_ph = 'Pagkatapos ng <Fight for Favor>, ang target ay <Maiinlove> kay Kanroji Mitsuri sa loob ng 2 turn\n#F10#\n#F40#<Fall in Love>: Natatanging epekto, tumatanggap ng 20% double attack at 30% double defense mula sa target.\n#F10#\n#F40#Pagkatapos ng huling atake, ang lahat ng kalabang naakit ay kusang magdo-donate ng 10% ng kanilang max HP kay Kanroji Mitsuri.',
		zawakeSimpleDesc_ma = 'Selepas <Fight for Favor> tamat, sasaran akan <Jatuh Cinta> kepada Kanroji Mitsuri selama 2 pusingan\n#F10#\n#F40#<Jatuh Cinta>: Kesan unik, menerima 20% serangan berganda dan 30% pertahanan berganda daripada sasaran.\n#F10#\n#F40#Selepas serangan akhir tamat, semua musuh yang terpesona akan secara sukarela mendermakan 10% HP maksimum mereka kepada Kanroji Mitsuri.',
		zawakeSimpleDesc_vn = 'Sau khi <Fight for Favor> kết thúc, mục tiêu sẽ <phải lòng> Kanroji Mitsuri trong 2 hiệp.\n#F10#\n#F40#<Fall in Love>: Hiệu ứng độc nhất, nhận được 20% tấn công kép và 30% phòng thủ kép từ mục tiêu.\n#F10#\n#F40#Sau khi đòn tấn công cuối kết thúc, tất cả mục tiêu bị mê hoặc của kẻ địch sẽ tự nguyện hiến 10% máu giới hạn trên của chúng cho Kanroji Mitsuri.',
		upLvDesc = 'Fixed damage +168',
