	[70516] = {
		id = 70516,
		skillName_vn = 'Hơi thở của Tình Yêu',
		skillName_en = 'Breath of Love',
		skillName_th = 'ลมหายใจแห่งรัก',
		skillName_in = 'Napas Cinta',
		skillName_ph = 'Hininga ng Pag-ibig',
		skillName_ma = 'Nafas Cinta',
		skillName = 'Breath of Love',
		describe_vn = '#C0xC0C0C0#Bọn chúng giờ thuộc về ta rồi~#C0x5B545B#\n#F10#\n#F40##L10#Nữ hoàng của tình yêu#L0#: Giảm 20% sát thương nhận vào từ kẻ địch hệ Quyến Rũ (đối với kẻ địch khác giảm thêm 10%) (anh hùng hệ Quyến Rũ được định nghĩa là tất cả nữ anh hùng trừ zombie), trước mỗi lượt lớn, sẽ đặt [Bẫy Gai] lên 1 mục tiêu địch ngẫu nhiên, có #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# tỷ lệ [Mê Hoặc] 1 mục tiêu địch ngẫu nhiên trong 1 lượt, có 50% tỷ lệ [Mê Hoặc] thêm 1 mục tiêu khác; mỗi khi phe ta có 1 anh hùng hệ Siêu Năng, sẽ tăng thêm 10% tỷ lệ kích hoạt kỹ năng bị động Mê Hoặc ở lượt đầu\n#F10#\n#F40##L10#Duyên dáng tuyệt trần:#L0# Khi có mặt, mỗi khi phe ta có 1 anh hùng hệ Quyến Rũ, sẽ tăng 5% giới hạn HP, 10% sát thương gây ra và 10% giảm sát thương cho anh hùng đó (với anh hùng hệ Siêu Năng và hệ Nhẫn Thuật thì hiệu quả gấp đôi)\n#F10#\n#F40#Khi anh hùng hệ Quyến Rũ của phe ta bị tấn công chủ động bởi kẻ địch hệ khác, giảm 30% sát thương nhận vào, và có 30% tỷ lệ [Mê Hoặc] kẻ tấn công trong 1 lượt; khi tấn công mục tiêu đang chịu [Mê Hoặc], sẽ bỏ qua một nửa chỉ số phòng thủ\n#F10#\n#F40##L10#Mê Hoặc Chúng Sinh:#L0# Trong hai lượt lớn đầu tiên, kẻ địch không thể xóa bỏ bất kỳ hiệu ứng [Mê Hoặc] nào\n#F10#\n#F40#Cứ mỗi 3 lượt lớn, sẽ chia sẻ khả năng [Mê Hoặc] cho 1 đồng minh hệ Siêu Năng hoặc Nhẫn Thuật ngẫu nhiên trong 1 lượt; sau khi Kanroji Mitsuri tấn công, đồng minh đó có thể [Mê Hoặc] 1 mục tiêu địch ngẫu nhiên trong 1 lượt; mục tiêu bị [Mê Hoặc] khi tấn công đồng minh sẽ tăng 30% sát thương gây ra\n#F10#\n#F40#Khi cùng chiến đấu với Kamado Tanjiro hoặc Daki, trong trận chiến này, thuộc tính phụ thứ hai của Kamado Tanjiro và Daki sẽ được thay bằng hệ Siêu Năng, đồng thời cả ba sẽ nhận thêm 50% sát thương cộng thêm',
		describe_en = '#C0xC0C0C0#They’re mine now~#C0x5B545B#\n#F10#\n#F40##L10#Queen of Love#L0#: Reduces damage taken from Charm-type enemies by 20% (reduces an additional 10% from other enemies). (Charm-type heroes are defined as all female heroes except zombies.) Before each major turn, places a [Thorn Trap] on a random enemy, with a #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# chance to [Charm] a random enemy target for 1 turn, and a 50% chance to additionally [Charm] one more target. For each Psychic-type ally, increases the first-turn passive skill\'s charm chance by an extra 10%.\n#F10#\n#F40##L10#Elegant Grace:#L0# While on the field, for each Charm-type ally, increases that hero’s max HP by 5%, damage dealt by 10%, and damage reduction by 10% (these effects are doubled for Psychic and Ninja-type heroes).\n#F10#\n#F40#When Charm-type allies take active attacks from other enemy types, reduces damage taken by 30% and has a 30% chance to [Charm] the attacker for 1 turn; when attacking targets under [Charm], ignores half of their defense stats.\n#F10#\n#F40##L10#Charm All Beings:#L0# In the first two major turns, enemies cannot dispel any [Charm]-type effects.\n#F10#\n#F40#Every 3 major turns, shares the [Charm] ability with a random Psychic or Ninja-type ally for 1 turn. After Kanroji Mitsuri attacks, that ally can [Charm] a random enemy target for 1 turn. Targets under [Charm] will deal 30% increased damage when attacking Mitsuri’s allies.\n#F10#\n#F40#When fighting together with Kamado Tanjiro or Daki, in that battle only, Tanjiro\'s and Daki’s second sub-attribute will be converted to Psychic-type, and all three receive a 50% damage bonus.',
		describe_th = '#C0xC0C0C0#พวกเขาเป็นของข้าแล้ว~#C0x5B545B# [ราชินีแห่งความรัก]: ลดความเสียหายที่ได้รับจากศัตรูสายเสน่ห์ลง 20% (ศัตรูประเภทอื่นลดเพิ่มอีก 10%) (ฮีโร่สายเสน่ห์หมายถึงฮีโร่หญิงทั้งหมด ยกเว้นประเภทซอมบี้) ก่อนเริ่มแต่ละรอบใหญ่ จะสุ่มวาง [กับดักหนาม] บนศัตรู 1 ตัว มีโอกาส #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# ทำให้ศัตรูแบบสุ่มติดสถานะ [เสน่ห์] 1 เทิร์น และมีโอกาส 50% ที่จะเสน่ห์เป้าหมายเพิ่มอีก 1 ตัว ฝ่ายเราจะเพิ่มโอกาสเสน่ห์จากสกิลติดตัวในเทิร์นแรกอีก 10% ต่อจำนวนฮีโร่สายพลังจิตที่มี [ความงามไร้เทียมทาน]: ขณะอยู่ในสนาม ฮีโร่ฝ่ายเราทุกตัวที่เป็นสายเสน่ห์จะได้รับพลังชีวิตสูงสุดเพิ่ม 5%, โบนัสความเสียหายและลดความเสียหายเพิ่มอีก 10% (หากเป้าหมายเป็นฮีโร่สายพลังจิตหรือสายนินจา เอฟเฟกต์นี้จะเพิ่มเป็นสองเท่า) ฮีโร่สายเสน่ห์ของฝ่ายเราจะลดความเสียหายที่ได้รับจากการโจมตีแบบแอคทีฟของศัตรูที่ไม่ใช่สายเสน่ห์ลง 30% และมีโอกาส 30% ที่จะ [เสน่ห์] ผู้โจมตีเป็นเวลา 1 เทิร์น; เมื่อโจมตีเป้าหมายที่อยู่ในสถานะ [เสน่ห์] จะสามารถละเลยค่าพลังป้องกันครึ่งหนึ่ง [เสน่ห์สะกดใจ]: ในสองรอบใหญ่แรก ฝ่ายศัตรูจะไม่สามารถลบเอฟเฟกต์ใด ๆ ที่เกี่ยวข้องกับ [เสน่ห์] ได้ ทุก ๆ 3 รอบใหญ่ จะส่งต่อความสามารถ [เสน่ห์] ให้กับฮีโร่สายพลังจิตหรือสายนินจาแบบสุ่ม 1 ตัวในฝ่ายเราเป็นเวลา 1 เทิร์น เมื่อคันโรจิมิตสึริโจมตี ฮีโร่ที่ได้รับการส่งต่อจะสามารถ [เสน่ห์] ศัตรูแบบสุ่ม 1 ตัวได้เป็นเวลา 1 เทิร์น และศัตรูที่อยู่ในสถานะ [เสน่ห์] จะสร้างความเสียหายเพิ่มขึ้น 30% เมื่อตีใส่ยูนิตเพื่อนร่วมทีมของคันโรจิ หากต่อสู้ร่วมกับทันจิโร่หรือดาคิ ในการต่อสู้นั้นเท่านั้น ทันจิโร่และดาคิจะเปลี่ยนธาตุรองเป็นสายพลังจิต และทั้งสามจะได้รับโบนัสความเสียหายเพิ่ม 50%',
		describe_in = '#C0xC0C0C0#They’re mine now~#C0x5B545B#\n#F10#\n#F40##L10#Queen of Love#L0#: Reduces damage taken from Charm-type enemies by 20% (reduces an additional 10% from other enemies). (Charm-type heroes are defined as all female heroes except zombies.) Before each major turn, places a [Thorn Trap] on a random enemy, with a #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# chance to [Charm] a random enemy target for 1 turn, and a 50% chance to additionally [Charm] one more target. For each Psychic-type ally, increases the first-turn passive skill\'s charm chance by an extra 10%.\n#F10#\n#F40##L10#Elegant Grace:#L0# While on the field, for each Charm-type ally, increases that hero’s max HP by 5%, damage dealt by 10%, and damage reduction by 10% (these effects are doubled for Psychic and Ninja-type heroes).\n#F10#\n#F40#When Charm-type allies take active attacks from other enemy types, reduces damage taken by 30% and has a 30% chance to [Charm] the attacker for 1 turn; when attacking targets under [Charm], ignores half of their defense stats.\n#F10#\n#F40##L10#Charm All Beings:#L0# In the first two major turns, enemies cannot dispel any [Charm]-type effects.\n#F10#\n#F40#Every 3 major turns, shares the [Charm] ability with a random Psychic or Ninja-type ally for 1 turn. After Kanroji Mitsuri attacks, that ally can [Charm] a random enemy target for 1 turn. Targets under [Charm] will deal 30% increased damage when attacking Mitsuri’s allies.\n#F10#\n#F40#When fighting together with Kamado Tanjiro or Daki, in that battle only, Tanjiro\'s and Daki’s second sub-attribute will be converted to Psychic-type, and all three receive a 50% damage bonus.',
		describe_ph = '#C0xC0C0C0#They’re mine now~#C0x5B545B#\n#F10#\n#F40##L10#Queen of Love#L0#: Reduces damage taken from Charm-type enemies by 20% (reduces an additional 10% from other enemies). (Charm-type heroes are defined as all female heroes except zombies.) Before each major turn, places a [Thorn Trap] on a random enemy, with a #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# chance to [Charm] a random enemy target for 1 turn, and a 50% chance to additionally [Charm] one more target. For each Psychic-type ally, increases the first-turn passive skill\'s charm chance by an extra 10%.\n#F10#\n#F40##L10#Elegant Grace:#L0# While on the field, for each Charm-type ally, increases that hero’s max HP by 5%, damage dealt by 10%, and damage reduction by 10% (these effects are doubled for Psychic and Ninja-type heroes).\n#F10#\n#F40#When Charm-type allies take active attacks from other enemy types, reduces damage taken by 30% and has a 30% chance to [Charm] the attacker for 1 turn; when attacking targets under [Charm], ignores half of their defense stats.\n#F10#\n#F40##L10#Charm All Beings:#L0# In the first two major turns, enemies cannot dispel any [Charm]-type effects.\n#F10#\n#F40#Every 3 major turns, shares the [Charm] ability with a random Psychic or Ninja-type ally for 1 turn. After Kanroji Mitsuri attacks, that ally can [Charm] a random enemy target for 1 turn. Targets under [Charm] will deal 30% increased damage when attacking Mitsuri’s allies.\n#F10#\n#F40#When fighting together with Kamado Tanjiro or Daki, in that battle only, Tanjiro\'s and Daki’s second sub-attribute will be converted to Psychic-type, and all three receive a 50% damage bonus.',
		describe_ma = '#C0xC0C0C0#They’re mine now~#C0x5B545B#\n#F10#\n#F40##L10#Queen of Love#L0#: Reduces damage taken from Charm-type enemies by 20% (reduces an additional 10% from other enemies). (Charm-type heroes are defined as all female heroes except zombies.) Before each major turn, places a [Thorn Trap] on a random enemy, with a #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# chance to [Charm] a random enemy target for 1 turn, and a 50% chance to additionally [Charm] one more target. For each Psychic-type ally, increases the first-turn passive skill\'s charm chance by an extra 10%.\n#F10#\n#F40##L10#Elegant Grace:#L0# While on the field, for each Charm-type ally, increases that hero’s max HP by 5%, damage dealt by 10%, and damage reduction by 10% (these effects are doubled for Psychic and Ninja-type heroes).\n#F10#\n#F40#When Charm-type allies take active attacks from other enemy types, reduces damage taken by 30% and has a 30% chance to [Charm] the attacker for 1 turn; when attacking targets under [Charm], ignores half of their defense stats.\n#F10#\n#F40##L10#Charm All Beings:#L0# In the first two major turns, enemies cannot dispel any [Charm]-type effects.\n#F10#\n#F40#Every 3 major turns, shares the [Charm] ability with a random Psychic or Ninja-type ally for 1 turn. After Kanroji Mitsuri attacks, that ally can [Charm] a random enemy target for 1 turn. Targets under [Charm] will deal 30% increased damage when attacking Mitsuri’s allies.\n#F10#\n#F40#When fighting together with Kamado Tanjiro or Daki, in that battle only, Tanjiro\'s and Daki’s second sub-attribute will be converted to Psychic-type, and all three receive a 50% damage bonus.',
		describe = '#C0xC0C0C0#They’re mine now~#C0x5B545B#\n#F10#\n#F40##L10#Queen of Love#L0#: Reduces damage taken from Charm-type enemies by 20% (reduces an additional 10% from other enemies). (Charm-type heroes are defined as all female heroes except zombies.) Before each major turn, places a [Thorn Trap] on a random enemy, with a #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# chance to [Charm] a random enemy target for 1 turn, and a 50% chance to additionally [Charm] one more target. For each Psychic-type ally, increases the first-turn passive skill\'s charm chance by an extra 10%.\n#F10#\n#F40##L10#Elegant Grace:#L0# While on the field, for each Charm-type ally, increases that hero’s max HP by 5%, damage dealt by 10%, and damage reduction by 10% (these effects are doubled for Psychic and Ninja-type heroes).\n#F10#\n#F40#When Charm-type allies take active attacks from other enemy types, reduces damage taken by 30% and has a 30% chance to [Charm] the attacker for 1 turn; when attacking targets under [Charm], ignores half of their defense stats.\n#F10#\n#F40##L10#Charm All Beings:#L0# In the first two major turns, enemies cannot dispel any [Charm]-type effects.\n#F10#\n#F40#Every 3 major turns, shares the [Charm] ability with a random Psychic or Ninja-type ally for 1 turn. After Kanroji Mitsuri attacks, that ally can [Charm] a random enemy target for 1 turn. Targets under [Charm] will deal 30% increased damage when attacking Mitsuri’s allies.\n#F10#\n#F40#When fighting together with Kamado Tanjiro or Daki, in that battle only, Tanjiro\'s and Daki’s second sub-attribute will be converted to Psychic-type, and all three receive a 50% damage bonus.',
		starEffect = __data_t__starEffect[70516],
		-- {8}
		starEffectDesc_vn = 'Khi nhận sát thương chí mạng lần đầu tiên, nó sẽ hồi phục đầy máu và triệu hồi Guardian Iguro Kobane vào sân trong 2 lượt (thừa hưởng 300% Tấn công vật lý). Khi nhận sát thương chí mạng lần nữa, một mục tiêu địch khác ngoài kẻ tấn công đang chịu <Mê Hoặc> sẽ chịu đòn thay (chỉ có thể kích hoạt một lần, tích lũy trên toàn sân). Nếu chịu sát thương thành công, nó sẽ ngay lập tức tung ra một chiêu thức đặc biệt. Khi Guardian Iguro Kobane vào sân, nó sẽ ngay lập tức nhận được 240 điểm Nộ.',
		starEffectDesc = 'When receiving a critical hit for the first time, she will fully restore HP and summon Guardian Iguro Kobane to the field for 2 turns (inherits 300% Physical Attack). Upon receiving another critical hit, a different enemy under <Charm> other than the attacker will take the damage instead (can only trigger once, shared across the battlefield). If the damage is successfully transferred, she will immediately unleash a special skill. When Guardian Iguro Kobane enters the field, he will instantly gain 240 Rage points.',
		starEffectDesc_en = 'When receiving a critical hit for the first time, she will fully restore HP and summon Guardian Iguro Kobane to the field for 2 turns (inherits 300% Physical Attack). Upon receiving another critical hit, a different enemy under <Charm> other than the attacker will take the damage instead (can only trigger once, shared across the battlefield). If the damage is successfully transferred, she will immediately unleash a special skill. When Guardian Iguro Kobane enters the field, he will instantly gain 240 Rage points.',
		starEffectDesc_th = 'เมื่อได้รับความเสียหายคริติคอลครั้งแรก จะฟื้นฟู HP เต็มและเรียก Guardian Iguro Kobane ลงสนามเป็นเวลา 2 เทิร์น (รับพลังโจมตีกายภาพ 300%) เมื่อได้รับคริติคอลอีกครั้ง ศัตรูตัวอื่นที่อยู่ในสถานะ <หลงใหล> (ยกเว้นผู้โจมตี) จะรับความเสียหายแทน (สามารถเกิดได้เพียง 1 ครั้ง, ทั่วทั้งสนาม) หากการรับความเสียหายสำเร็จ จะปล่อยสกิลพิเศษทันที เมื่อ Guardian Iguro Kobane เข้าสนาม จะได้รับ 240 แต้มโกรธทันที',
		starEffectDesc_in = 'Saat menerima serangan kritikal untuk pertama kalinya, dia akan memulihkan HP sepenuhnya dan memanggil Guardian Iguro Kobane ke medan selama 2 giliran (mewarisi 300% Serangan Fisik). Ketika menerima serangan kritikal lagi, musuh lain yang berada dalam status <Terkesima> selain penyerang akan menerima serangan tersebut (hanya bisa dipicu sekali, berlaku di seluruh medan). Jika serangan berhasil dialihkan, dia akan segera melancarkan skill spesial. Saat Guardian Iguro Kobane masuk medan, dia langsung memperoleh 240 poin Amarah.',
		starEffectDesc_ph = 'Kapag unang beses siyang tumanggap ng critical damage, agad siyang magpapagaling ng buong HP at magpapatawag kay Guardian Iguro Kobane sa field sa loob ng 2 turn (minamana ang 300% Physical Attack). Sa susunod na critical hit, isang kalaban na nasa ilalim ng <Pagkaakit> maliban sa umatake ay tatanggap ng damage sa halip (maaaring mag-trigger isang beses lang, pinagsasaluhan sa buong field). Kung matagumpay ang paglipat ng damage, agad siyang maglalabas ng espesyal na kasanayan. Kapag pumasok sa field si Guardian Iguro Kobane, agad siyang makakatanggap ng 240 Rage points.',
		starEffectDesc_ma = 'Apabila menerima serangan kritikal buat kali pertama, dia akan memulihkan HP sepenuhnya dan memanggil Guardian Iguro Kobane ke medan selama 2 pusingan (mewarisi 300% Serangan Fizikal). Apabila menerima serangan kritikal sekali lagi, seorang musuh lain yang berada dalam status <Terpesona> selain penyerang akan menanggung serangan tersebut (hanya boleh diaktifkan sekali, dikongsi di seluruh medan). Jika kerosakan berjaya dipindahkan, dia akan serta-merta melancarkan satu kemahiran khas. Apabila Guardian Iguro Kobane memasuki medan, dia akan terus menerima 240 mata Kemarahan.',
		zawakeEffect = __data_t__zawakeEffect[70516],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#Now they are mine~#C0x5B545B# #F10# #F40##L10#Queen of Love#L0#: Reduces damage taken from Charmed enemies by 20% (reduces an additional 10% from other enemies) (Charmed heroes are defined as all female heroes except zombies). Places a <Thorn Trap> on a random enemy before each round, with a #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# chance to <Charm> a random enemy target for 1 round and a 50% chance to <Charm> another target. For each Psychic ally on your team, the passive charm chance in the first round is increased by 10% #F10# #F40##L10#Graceful and Elegant: #L0#When present, for each Charmed hero on your team, increases their HP cap by 5%, and damage bonus and damage reduction by 10% (for Psychic and Ninjutsu heroes). Upgrade effects are doubled #F10# #F40#When a Charmed Hero is attacked by non-Charmed enemies, damage taken is reduced by 30% and there is a 30% chance to <Charm> the attacker for 1 turn; when attacking a <Charmed> unit, ignores half of their defense stat #F10# #F40##L10#Charm All Beings: #L0#During the first two rounds, enemies cannot dispel all <Charmed> effects #F10# #F40#Every 3 rounds, <Charmed> is Shared with a random friendly Psychic/Ninjutsu ally for 1 turn. After Kanroji Mitsuri attacks, this ally can <Charm> a random enemy target for 1 turn. A <Charmed> target deals 30% more damage when attacking its friendly units #F10# #F40#Charmed allies are immune to Charm #F10# #F40#When fighting Tanjiro Kamado or Daki, their secondary attributes are replaced with Psychic only for this battle, and all three receive 50% bonus damage',
		zawakeEffectDesc_en = '#C0xC0C0C0#Now they are mine~#C0x5B545B# #F10# #F40##L10#Queen of Love#L0#: Reduces damage taken from Charmed enemies by 20% (reduces an additional 10% from other enemies) (Charmed heroes are defined as all female heroes except zombies). Places a <Thorn Trap> on a random enemy before each round, with a #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# chance to <Charm> a random enemy target for 1 round and a 50% chance to <Charm> another target. For each Psychic ally on your team, the passive charm chance in the first round is increased by 10% #F10# #F40##L10#Graceful and Elegant: #L0#When present, for each Charmed hero on your team, increases their HP cap by 5%, and damage bonus and damage reduction by 10% (for Psychic and Ninjutsu heroes). Upgrade effects are doubled #F10# #F40#When a Charmed Hero is attacked by non-Charmed enemies, damage taken is reduced by 30% and there is a 30% chance to <Charm> the attacker for 1 turn; when attacking a <Charmed> unit, ignores half of their defense stat #F10# #F40##L10#Charm All Beings: #L0#During the first two rounds, enemies cannot dispel all <Charmed> effects #F10# #F40#Every 3 rounds, <Charmed> is Shared with a random friendly Psychic/Ninjutsu ally for 1 turn. After Kanroji Mitsuri attacks, this ally can <Charm> a random enemy target for 1 turn. A <Charmed> target deals 30% more damage when attacking its friendly units #F10# #F40#Charmed allies are immune to Charm #F10# #F40#When fighting Tanjiro Kamado or Daki, their secondary attributes are replaced with Psychic only for this battle, and all three receive 50% bonus damage',
		zawakeEffectDesc_th = '#C0xC0C0C0#ตอนนี้พวกเขาเป็นของฉันแล้ว~#C0x5B545B# #F10# #F40##L10#ราชินีแห่งความรัก#L0#: ลดความเสียหายที่ได้รับจากศัตรูที่ถูกดึงดูด 20% (ลดเพิ่มอีก 10% จากศัตรูอื่น) (ฮีโร่ที่ถูกดึงดูดหมายถึงฮีโร่ผู้หญิงทั้งหมด ยกเว้นซอมบี้) วางกับดักหนามไว้บนศัตรูแบบสุ่มก่อนแต่ละรอบ โดยมีโอกาส #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# เพื่อ <ดึงดูด> เป้าหมายศัตรูแบบสุ่ม 1 รอบ และมีโอกาส 50% ที่จะ <ดึงดูด> เป้าหมายอื่น สำหรับแต่ละพันธมิตรประเภทจิต โอกาสดึงดูดในรอบแรกจะเพิ่มขึ้น 10% #F10# #F40##L10#สง่างามและมีเสน่ห์: #L0#เมื่ออยู่ในสนาม สำหรับแต่ละฮีโร่ที่ถูกดึงดูดในทีม จะเพิ่มขีดจำกัด HP ขึ้น 5% และเพิ่มโบนัสความเสียหายและลดความเสียหาย 10% (สำหรับฮีโร่จิตและนินจุสึ) ผลการอัปเกรดจะเพิ่มเป็นสองเท่า #F10# #F40#เมื่อฮีโร่ที่ถูกดึงดูดถูกศัตรูประเภทอื่นโจมตี จะลดความเสียหายที่ได้รับลง 30% และมีโอกาส 30% ที่จะ <ดึงดูด> ผู้โจมตี 1 รอบ; เมื่อโจมตีหน่วย <ลุ่มหลง> จะละเลยครึ่งหนึ่งของค่าป้องกัน #F10# #F40##L10#เสน่ห์ครอบงำสรรพสิ่ง: #L0#ในสองรอบแรก ศัตรูไม่สามารถลบล้างผล <ลุ่มหลง> ทั้งหมดได้ #F10# #F40#ทุก ๆ 3 รอบ ผล <ลุ่มหลง> จะถูกแบ่งให้กับพันธมิตรประเภทจิต/นินจุสึแบบสุ่ม 1 คน เป็นเวลา 1 รอบ หลังจากที่คันโรจิ มิทสึริ โจมตี พันธมิตรนี้สามารถ <ลุ่มหลง> เป้าหมายศัตรูแบบสุ่ม 1 รอบ หน่วยที่ <ลุ่มหลง> จะสร้างความเสียหายเพิ่มขึ้น 30% เมื่อโจมตีพันธมิตรของตน #F10# #F40#พันธมิตรที่ถูกลุ่มหลงจะมีภูมิต้านทานต่อการลุ่มหลง #F10# #F40#เมื่อสู้กับทันจิโร่ คามาโดะ หรือดากิ คุณสมบัติรองของทั้งสองจะถูกแทนที่ด้วยจิตในศึกนี้ และทั้งสามจะได้รับโบนัสความเสียหาย 50%',
		zawakeEffectDesc_in = '#C0xC0C0C0#Sekarang mereka milikku~#C0x5B545B# #F10# #F40##L10#Ratu Cinta#L0#: Mengurangi 20% damage dari musuh yang Tertarik (mengurangi tambahan 10% dari musuh lainnya) (Hero Tertarik didefinisikan sebagai semua hero wanita kecuali zombie). Menempatkan <Perangkap Duri> pada musuh acak sebelum setiap ronde, dengan peluang #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# untuk <Menarik> satu target musuh acak selama 1 ronde dan peluang 50% untuk <Menarik> target lainnya. Untuk setiap sekutu bertipe Psikis di tim, peluang menarik pasif di ronde pertama meningkat 10% #F10# #F40##L10#Anggun dan Elegan: #L0#Saat hadir, untuk setiap hero Tertarik di tim, meningkatkan batas HP mereka sebesar 5%, dan bonus serta pengurangan damage sebesar 10% (untuk hero Psikis dan Ninjutsu). Efek upgrade digandakan #F10# #F40#Saat hero Tertarik diserang oleh musuh non-Tertarik, damage yang diterima berkurang 30% dan ada peluang 30% untuk <Menarik> penyerang selama 1 ronde; saat menyerang unit <Terpesona>, mengabaikan setengah atribut pertahanannya #F10# #F40##L10#Memikat Segala Makhluk: #L0#Selama dua ronde pertama, musuh tidak dapat menghapus semua efek <Terpesona> #F10# #F40#Setiap 3 ronde, efek <Terpesona> akan Dibagikan kepada satu sekutu acak tipe Psikis/Ninjutsu selama 1 ronde. Setelah Kanroji Mitsuri menyerang, sekutu ini dapat <Memikat> satu musuh acak selama 1 ronde. Target <Terpesona> memberikan 30% damage tambahan saat menyerang unit sekutunya sendiri #F10# #F40#Sekutu yang Terpesona kebal terhadap efek Terpesona #F10# #F40#Saat melawan Tanjiro Kamado atau Daki, atribut sekunder mereka akan diganti menjadi Psikis hanya untuk pertarungan ini dan ketiganya mendapatkan bonus damage 50%',
		zawakeEffectDesc_ph = '#C0xC0C0C0#Akin na sila ngayon~#C0x5B545B# #F10# #F40##L10#Reyna ng Pag-ibig#L0#: Binabawasan ng 20% ang pinsala mula sa mga kalabang Nahumaling (karagdagang 10% bawas mula sa iba pang kalaban) (Ang mga Nahumaling na bayani ay ang lahat ng babaeng bayani maliban sa mga zombie). Naglalagay ng <Bitag ng Tinik> sa isang random na kalaban bago ang bawat round, na may #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# na pagkakataong <Mahumaling> ang isang random na kalaban sa loob ng 1 round at 50% tsansang <Mahumaling> pa ang isa. Kada Psychic na kakampi, tumataas ng 10% ang passive charm chance sa unang round #F10# #F40##L10#Maganda at Marikit: #L0#Kapag naroroon, kada Nahumaling na bayani sa team ay tataas ang HP limit ng 5% at makakakuha ng 10% dagdag sa bonus damage at damage reduction (para sa mga bayani ng Psychic at Ninjutsu). Ang upgrade effects ay nadodoble #F10# #F40#Kapag ang isang Nahumaling na Bayani ay inatake ng ibang uri ng kalaban, ang natatanggap na pinsala ay nababawasan ng 30% at may 30% tsansang <Mahumaling> ang kalaban sa loob ng 1 turn; kapag umaatake sa isang yunit na <Nahumaling>, binabalewala ang kalahati ng depensa nito #F10# #F40##L10#Humaling sa Lahat: #L0#Sa unang dalawang round, hindi maaalis ng mga kalaban ang mga <Nahumaling> na epekto #F10# #F40#Bawat 3 rounds, ang <Nahumaling> ay Ibabahagi sa isang random na kakampi na Psychic/Ninjutsu sa loob ng 1 turn. Matapos umatake si Kanroji Mitsuri, ang kakamping ito ay maaaring <Mahumaling> sa isang random na kalaban sa loob ng 1 turn. Ang target na <Nahumaling> ay magdudulot ng 30% karagdagang pinsala kapag umatake sa sariling kakampi #F10# #F40#Immune sa Nahumaling ang mga kakampi na Nahumaling na #F10# #F40#Kapag lumaban kina Tanjiro Kamado o Daki, ang kanilang pangalawang katangian ay magiging Psychic lamang sa laban na ito at silang tatlo ay makakakuha ng 50% bonus damage',
		zawakeEffectDesc_ma = '#C0xC0C0C0#Sekarang mereka milikku~#C0x5B545B# #F10# #F40##L10#Ratu Cinta#L0#: Mengurangkan 20% kerosakan daripada musuh yang Tertarik (tambahan 10% dari musuh lain) (Hero yang Tertarik didefinisikan sebagai semua hero wanita kecuali zombi). Letakkan <Perangkap Duri> pada musuh rawak sebelum setiap pusingan, dengan peluang #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# untuk <Menarik> satu musuh rawak selama 1 pusingan dan 50% peluang untuk <Menarik> musuh lain. Untuk setiap sekutu jenis Psikik dalam pasukan, peluang pesona pasif dalam pusingan pertama meningkat 10% #F10# #F40##L10#Anggun dan Menawan: #L0#Apabila hadir, untuk setiap hero Tertarik dalam pasukan, had HP mereka meningkat 5% dan bonus kerosakan serta pengurangan kerosakan meningkat 10% (untuk hero Psikik dan Ninjutsu). Kesan naik taraf digandakan #F10# #F40#Apabila hero Tertarik diserang oleh musuh jenis lain, kerosakan diterima berkurang 30% dan ada 30% peluang untuk <Menarik> penyerang selama 1 pusingan; apabila menyerang unit <Tergoda>, abaikan separuh pertahanannya #F10# #F40##L10#Memikat Semua Makhluk: #L0#Dalam dua pusingan pertama, musuh tidak boleh menyingkirkan semua kesan <Tergoda> #F10# #F40#Setiap 3 pusingan, kesan <Tergoda> akan Dikongsi kepada satu sekutu rawak jenis Psikik/Ninjutsu selama 1 pusingan. Selepas Kanroji Mitsuri menyerang, sekutu ini boleh <Menarik> satu musuh rawak selama 1 pusingan. Musuh <Tergoda> akan memberikan 30% lebih kerosakan apabila menyerang sekutunya sendiri #F10# #F40#Sekutu yang Tergoda kebal terhadap efek Tergoda #F10# #F40#Apabila bertarung dengan Tanjiro Kamado atau Daki, atribut kedua mereka akan digantikan dengan Psikik dalam pertempuran ini sahaja dan ketiga-tiga akan menerima 50% bonus kerosakan',
		zawakeEffectDesc_vn = '#C0xC0C0C0#Giờ chúng là của tôi~#C0x5B545B#\n#F10#\n#F40##L10#Queen of Love#L0#: Giảm 20% sát thương từ kẻ địch hấp dẫn (giảm thêm 10% sát thương từ những kẻ địch khác) (anh hùng hấp dẫn được định nghĩa là tất cả anh hùng nữ trừ thây ma). Đặt <Bẫy gai> lên một kẻ địch ngẫu nhiên trước mỗi vòng, với #C0x5c9970#$(20+skillLevel*0.3-0 .3) $%#C0x5B545B# có cơ hội <Hấp dẫn> một mục tiêu kẻ địch ngẫu nhiên trong 1 vòng và có 50% cơ hội <Hấp dẫn> một mục tiêu khác. Với mỗi anh hùng Tâm linh ở phe bạn, cơ hội quyến rũ kỹ năng thụ động ở lượt đầu tiên tăng thêm 10%\n#F10#\n#F40##L10# Duyên dáng và thanh lịch: #L0# Khi có mặt, với mỗi anh hùng Quyến rũ ở phe bạn, tăng giới hạn HP của loại anh hùng đó thêm 5%, và phần thưởng sát thương và giảm sát thương thêm 10% (đối với anh hùng Tâm linh và Nhẫn thuật). Hiệu ứng nâng cấp được nhân đôi)\n#F10#\n#F40#Khi một Anh hùng Quyến rũ bị các loại kẻ thù khác tấn công chủ động, sát thương phải chịu sẽ giảm 30% và có 30% cơ hội <Quyến rũ> kẻ tấn công trong 1 lượt; khi tấn công một đơn vị <Mê Hoặc>, bỏ qua một nửa thuộc tính phòng thủ\n#F10#\n#F40##L10#Mê Hoặc All Beings: #L0#Trong hai vòng đầu tiên, kẻ địch sẽ không thể giải trừ tất cả các hiệu ứng <Mê Hoặc>\n#F10#\n#F40#Cứ sau 3 vòng, <Mê Hoặc> sẽ được Chia sẻ khả năng với một đồng đội Psychic/Ninjutsu thân thiện ngẫu nhiên trong 1 lượt. Sau khi Kanroji Mitsuri tấn công, đồng đội này có thể <Mê Hoặc> một mục tiêu địch ngẫu nhiên trong 1 lượt. Sát thương của mục tiêu <Mê Hoặced> khi tấn công đơn vị thân thiện của nó tăng 30%\n#F10#\n#F40# Đồng đội Mê Hoặced miễn nhiễm với Mê Hoặc\n#F10#\n#F40# Khi chiến đấu với Tanjiro Kamado hoặc Daki, thuộc tính thứ hai của Tanjiro Kamado và Daki sẽ được thay thế bằng thuộc tính Psychic chỉ trong trận chiến này và cả ba sẽ nhận được 50% tiền thưởng sát thương',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#Charming allies are immune to all charm effects',
		zawakeSimpleDesc_en = '#C0x5c9970#Charming allies are immune to all charm effects',
		zawakeSimpleDesc_th = '#C0x5c9970#พันธมิตรที่มีเสน่ห์จะต้านทานต่อเอฟเฟกต์เสน่ห์ทั้งหมด',
		zawakeSimpleDesc_in = '#C0x5c9970#Sekutu yang menawan kebal terhadap semua efek pesona',
		zawakeSimpleDesc_ph = '#C0x5c9970#Ang mga kakamping may alindog ay immune sa lahat ng charm effects',
		zawakeSimpleDesc_ma = '#C0x5c9970#Sekutu yang memikat kebal terhadap semua kesan pesona',
		zawakeSimpleDesc_vn = '#C0x5c9970# Đồng đội quyến rũ sẽ miễn nhiễm với mọi hiệu ứng quyến rũ',
