		describe_in = 'Saat menerima kerusakan, dapatkan tambahan 100 poin kemarahan.',
		describe_ph = 'Kapag nakatanggap ng pinsala, kumita ng dagdag na 100 puntos ng galit.',
		describe_ma = 'Apabila menerima kerosakan, terima tambahan 100 mata kemarahan.',
