	[80019] = {
		id = 80019,
		describe_vn = 'Cung cấp cho tất cả anh hùng trên sân 5% Công Vật Lý và Công Phép thuật dựa trên loại thuộc tính hiện tại (chỉ tính thuộc tính đầu tiên)',
		describe_en = 'Grants all heroes on the field 5% Physical Attack and Magic Attack based on their current primary attribute (only the first attribute counts).',
		describe_th = 'มอบพลังโจมตีทางกายและพลังโจมตีทางเวทให้กับฮีโร่ทั้งหมดในสนาม 5% โดยพิจารณาจากแอตทริบิวต์หลักปัจจุบัน (นับเฉพาะแอตทริบิวต์แรกเท่านั้น)',
		describe_in = 'Memberikan semua pahlawan di medan 5% Serangan Fisik dan Serangan Sihir berdasarkan atribut utama mereka saat ini (hanya atribut pertama yang dihitung).',
		describe_ph = 'Nagbibigay sa lahat ng mga bayani sa larangan ng 5% Pisikal na Atake at Magic na Atake base sa kasalukuyang pangunahing katangian (tanging ang unang katangian lamang ang binibilang).',
		describe_ma = 'Memberikan semua wira di medan 5% Serangan Fizikal dan Serangan Sihir berdasarkan atribut utama mereka sekarang (hanya atribut pertama yang diambil kira).',
		describe = 'Grants all heroes on the field 5% Physical Attack and Magic Attack based on their current primary attribute (only the first attribute counts).',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 1,
		passiveTriggerArg = 1,
		posChoose = 5,
		skillProcess = {800191}
	},
	[80020] = {
		id = 80020,
		describe_vn = 'Anh hùng thuộc thuộc tính đặc biệt (chỉ tính thuộc tính đầu tiên) có thể nhận thêm 20% Công Vật Lý và Công Phép thuật (mỗi thuộc tính đều có một buff)',
		describe_en = 'Heroes with a special attribute (only the first attribute counts) can receive an additional 20% Physical Attack and Magic Attack (each attribute has its own buff).',
		describe_th = 'ฮีโร่ที่มีคุณสมบัติพิเศษ (นับเฉพาะคุณสมบัติแรกเท่านั้น) สามารถรับการเพิ่มพลังโจมตีทางกายภาพและโจมตีเวทมนตร์อีก 20% (แต่ละคุณสมบัติจะมีบัฟของตัวเอง).',
		describe_in = 'Pahlawan dengan atribut khusus (hanya atribut pertama yang dihitung) dapat menerima tambahan 20% Serangan Fisik dan Serangan Sihir (setiap atribut memiliki buff tersendiri).',
		describe_ph = 'Ang mga bayani na may espesyal na katangian (tanging unang katangian lamang ang binibilang) ay maaaring makatanggap ng karagdagang 20% Pisikal na Atake at Magic na Atake (bawat katangian ay may sariling buff).',
		describe_ma = 'Wira dengan atribut istimewa (hanya atribut pertama diambil kira) boleh menerima tambahan 20% Serangan Fizikal dan Serangan Sihir (setiap atribut mempunyai buff tersendiri).',
		describe = 'Heroes with a special attribute (only the first attribute counts) can receive an additional 20% Physical Attack and Magic Attack (each attribute has its own buff).',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 1,
		passiveTriggerArg = 1,
		posChoose = 5,
		skillProcess = {800201}
	},
	[80021] = {
		id = 80021,
		describe_vn = 'Tính thuộc tính của anh hùng ra trận (chỉ tính thuộc tính đầu tiên), tăng thêm Công Vật Lý và Công Phép thuật bằng 5% số lượng anh hùng thuộc loại thuộc tính được sử dụng nhiều nhất',
		describe_en = 'Calculate the attribute of the hero entering the battle (only calculate the first attribute), increase Physical Attack and Magic Attack by 5% of the number of heroes with the most frequently used attribute type.',
		describe_th = 'คำนวณคุณสมบัติของฮีโร่ที่ออกสู่สนามรบ (คำนวณเพียงคุณสมบัติแรก) เพิ่มพลังโจมตีทางกายภาพและพลังโจมตีเวทมนตร์ขึ้น 5% ของจำนวนฮีโร่ที่มีประเภทคุณสมบัติที่ถูกใช้งานบ่อยที่สุด',
		describe_in = 'Hitung atribut pahlawan yang masuk ke medan perang (hanya hitung atribut pertama), tingkatkan Serangan Fisik dan Serangan Sihir sebesar 5% dari jumlah pahlawan dengan jenis atribut yang paling sering digunakan.',
		describe_ph = 'Kalkulahin ang katangian ng bayani sa pagpasok sa labanan (kalkulahin lamang ang unang katangian), dagdagan ang Physical Attack at Magic Attack ng 5% ng bilang ng mga bayani na may pinakaginagamit na uri ng katangian.',
		describe_ma = 'Kira atribut wira yang masuk ke medan perang (hanya kira atribut pertama), tingkatkan Serangan Fizikal dan Serangan Sihir sebanyak 5% daripada bilangan wira dengan jenis atribut yang paling kerap digunakan.',
		describe = 'Calculate the attribute of the hero entering the battle (only calculate the first attribute), increase Physical Attack and Magic Attack by 5% of the number of heroes with the most frequently used attribute type.',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 1,
		passiveTriggerArg = 1,
		posChoose = 5,
		skillProcess = {800211}
	},
	[80022] = {
		id = 80022,
		describe_vn = 'Khi gây Sát Thương Phép Thuật, tỷ lệ bạo kích tăng 5%, kéo dài 2 lượt, tối đa cộng dồn 4 lần, cộng dồn làm mới thời gian kéo dài',
		describe_en = 'When dealing Magic Damage, critical hit rate increases by 5%, lasting 2 turns, stacking up to 4 times. Stacking refreshes the duration.',
		describe_th = 'เมื่อก่อให้เกิดความเสียหายเวทมนตร์ โอกาสคริติคอลเพิ่มขึ้น 5% นาน 2 เทิร์น สะสมได้สูงสุด 4 ครั้ง การสะสมจะรีเฟรชระยะเวลา',
		describe_in = 'Saat memberikan Damage Magic, peluang critical hit meningkat 5%, berlangsung selama 2 giliran, dapat bertumpuk hingga 4 kali. Penumpukan memperbarui durasi.',
		describe_ph = 'Kapag nagdudulot ng Magic Damage, tumataas ng 5% ang critical hit rate, tumatagal ng 2 turn, maaaring mag-stack hanggang 4 na beses. Ang pag-stack ay nire-refresh ang tagal.',
		describe_ma = 'Apabila menyebabkan Kerosakan Ajaib, kadar crit meningkat sebanyak 5%, berlangsung selama 2 pusingan, boleh bertindih sehingga 4 kali. Penindihan menyegarkan tempoh masa.',
		describe = 'When dealing Magic Damage, critical hit rate increases by 5%, lasting 2 turns, stacking up to 4 times. Stacking refreshes the duration.',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800221}
	},
	[80023] = {
		id = 80023,
		describe_vn = 'Mỗi khi nhận thêm 20% Công Phép thuật, có thể nhận thêm 10% Công Vật Lý',
		describe_en = 'Each time you gain an additional 20% Magic Attack, you can also gain an additional 10% Physical Attack.',
		describe_th = 'ทุกครั้งที่ได้รับพลังโจมตีเวทมนตร์เพิ่มขึ้น 20% สามารถได้รับพลังโจมตีทางกายภาพเพิ่มขึ้นอีก 10%',
		describe_in = 'Setiap kali menerima tambahan 20% Serangan Ajaib, dapat menerima tambahan 10% Serangan Fisik.',
		describe_ph = 'Sa bawat pagtanggap ng dagdag na 20% Magic Attack, maaari ring makatanggap ng dagdag na 10% Physical Attack.',
		describe_ma = 'Setiap kali menerima tambahan 20% Serangan Ajaib, boleh mendapat tambahan 10% Serangan Fizikal.',
		describe = 'Each time you gain an additional 20% Magic Attack, you can also gain an additional 10% Physical Attack.',
		alwaysEffective = true,
