	[80026] = {
		id = 80026,
		skillTypeShow = '改动',
		describe_vn = 'Khi gây sát thương lên kẻ địch bị khống chế, giải trừ hiệu ứng khống chế của chúng và tăng thêm 50% * số lượt còn lại sát thương',
		describe_en = 'When dealing damage to a controlled enemy, remove their control effects and increase damage by 50% * the number of remaining turns.',
		describe_th = 'เมื่อสร้างความเสียหายให้ศัตรูที่ถูกควบคุม จะปลดปล่อยผลการควบคุมของพวกเขาและเพิ่มความเสียหายขึ้น 50% * จำนวนรอบที่เหลืออยู่',
		describe_in = 'Saat memberikan kerusakan pada musuh yang dikendalikan, lepaskan efek kontrol mereka dan tingkatkan kerusakan sebesar 50% * jumlah giliran yang tersisa.',
		describe_ph = 'Kapag nagdudulot ng pinsala sa isang kontroladong kalaban, alisin ang kanilang mga epekto ng kontrol at dagdagan ang pinsala ng 50% * ng natitirang bilang ng mga turn.',
		describe_ma = 'Apabila menyebabkan kerosakan kepada musuh yang dikawal, hapuskan kesan kawalan mereka dan tambah kerosakan sebanyak 50% * bilangan pusingan yang tinggal.',
		describe = 'When dealing damage to a controlled enemy, remove their control effects and increase damage by 50% * the number of remaining turns.',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800261}
	},
	[80027] = {
		id = 80027,
		describe_vn = 'Khi gây sát thương bạo kích pháp thuật, tăng thêm 20% sát thương bạo kích lần này và hồi phục 5% giá trị sát thương này thành máu',
		describe_en = 'When dealing magical critical damage, increase the critical damage by 20% this time and recover 5% of the damage dealt as health.',
		describe_th = 'เมื่อสร้างความเสียหายคริติคอลเวทมนตร์ เพิ่มความเสียหายคริติคอลขึ้น 20% ในครั้งนี้ และฟื้นฟู 5% ของค่าความเสียหายนี้เป็นพลังชีวิต',
		describe_in = 'Saat memberikan kerusakan kritis sihir, tingkatkan kerusakan kritis sebesar 20% kali ini dan pulihkan 5% dari nilai kerusakan ini menjadi kesehatan.',
		describe_ph = 'Kapag nakapagbigay ng magic critical damage, dagdagan ang critical damage ng 20% sa pagkakataong ito at magpagaling ng 5% ng damage na ito bilang health.',
		describe_ma = 'Apabila menyebabkan kerosakan kritikal sihir, tingkatkan kerosakan kritikal sebanyak 20% kali ini dan pulihkan 5% daripada nilai kerosakan ini menjadi kesihatan.',
		describe = 'When dealing magical critical damage, increase the critical damage by 20% this time and recover 5% of the damage dealt as health.',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800271}
	},
	[80028] = {
		id = 80028,
		skillTypeShow = '改动',
		describe_vn = 'Kết thúc mỗi đại hiệp, giải trừ ngẫu nhiên một hiệu ứng khống chế của tất cả anh hùng phe ta',
		describe_en = 'At the end of each hero\'s turn, randomly remove one control effect from all allied heroes.',
		describe_th = 'เมื่อสิ้นสุดเทิร์นของแต่ละวีรบุรุษ ให้ลบเอฟเฟกต์ควบคุมอันหนึ่งแบบสุ่มออกจากวีรบุรุษฝ่ายเราแต่ละคน',
		describe_in = 'Di akhir giliran setiap pahlawan, secara acak hapus satu efek kontrol dari semua pahlawan sekutu kami.',
		describe_ph = 'Sa pagtatapos ng bawat turn ng bayani, random na alisin ang isang control effect mula sa lahat ng kaalyadong bayani.',
		describe_ma = 'Pada akhir giliran setiap wira, secara rawak membuang satu kesan kawalan dari semua wira sekutu kami.',
		describe = 'At the end of each hero\'s turn, randomly remove one control effect from all allied heroes.',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 9,
		passiveTriggerArg = 1,
		posChoose = 5,
		skillProcess = {800281}
	},
	[80029] = {
		id = 80029,
		describe_vn = 'Khi tấn công, tính toán toàn bộ sát thương liên tục trên mục tiêu, khiến giá trị sát thương liên tục còn lại trên mục tiêu có hiệu lực ngay lập tức',
		describe_en = 'When attacking, continuously calculate the total damage on the target, causing the remaining continuous damage value on the target to take effect immediately.',
		describe_th = 'เมื่อโจมตี ให้คำนวณความเสียหายทั้งหมดอย่างต่อเนื่องบนเป้าหมาย ทำให้ค่าความเสียหายต่อเนื่องที่เหลืออยู่บนเป้าหมายมีผลทันที',
		describe_in = 'Saat menyerang, hitung total kerusakan berkelanjutan pada target, menyebabkan nilai kerusakan berkelanjutan yang tersisa pada target berlaku segera.',
		describe_ph = 'Kapag umaatake, patuloy na kalkulahin ang kabuuang pinsala sa target, na nagiging sanhi ng natitirang halaga ng tuloy-tuloy na pinsala sa target na agad na epektibo.',
		describe_ma = 'Semasa menyerang, kira jumlah keseluruhan kerosakan berterusan pada sasaran, menyebabkan nilai kerosakan berterusan yang tinggal pada sasaran berkuat kuasa serta-merta.',
		describe = 'When attacking, continuously calculate the total damage on the target, causing the remaining continuous damage value on the target to take effect immediately.',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800291}
	},
	[80030] = {
		id = 80030,
		describe_vn = 'Khi bắt đầu mỗi lượt, giải trừ hiệu ứng tiêu cực trên bản thân, mỗi lần giải trừ nhận thêm 5% sát thương trong lượt đó',
		describe_en = 'At the start of each turn, remove negative effects from yourself. Each removal grants an additional 5% damage during that turn.',
		describe_th = 'เมื่อเริ่มต้นแต่ละรอบ ให้ล้างผลกระทบเชิงลบออกจากตัวเอง ทุกครั้งที่ล้างจะได้รับโบนัสความเสียหายเพิ่มขึ้น 5% ในรอบนั้น',
		describe_in = 'Pada awal setiap giliran, hapus efek negatif pada diri sendiri. Setiap penghapusan memberikan tambahan 5% kerusakan selama giliran tersebut.',
		describe_ph = 'Sa simula ng bawat turn, alisin ang mga negatibong epekto sa sarili. Sa bawat pagtanggal, nakakakuha ka ng dagdag na 5% na pinsala sa turn na iyon.',
		describe_ma = 'Pada permulaan setiap pusingan, hapuskan kesan negatif pada diri sendiri. Setiap penghapusan memberikan tambahan 5% kerosakan dalam pusingan itu.',
		describe = 'At the start of each turn, remove negative effects from yourself. Each removal grants an additional 5% damage during that turn.',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800301}
	},
	[80031] = {
		id = 80031,
		skillName_vn = 'Vũ Khúc Lam Ảnh',
		skillName_en = 'Dance of Azure Shadows',
		skillName_th = 'ระบำเงาสีน้ำเงิน',
		skillName_in = 'Tarian Bayangan Biru',
		skillName_ph = 'Sayaw ng Asul na Anino',
		skillName_ma = 'Tarian Bayangan Biru',
		skillName = 'Dance of Azure Shadows',
		describe_vn = 'Kochou Shinobu uyển chuyển vung kiếm, tạo nên đường kiếm lam sắc như cánh bướm khẽ lướt, tấn công kẻ địch đơn lẻ. Đòn đánh gây #C0x3D8A99#180% sát thương phép thuật#C0x5B545B#+$(skillLevel*4*24)$ sát thương phép thuật#C0x5B545B#, đồng thời khiến đối thủ nhiễm <Độc>, <Độc> khiến kẻ địch mất 5% máu, kéo dài 2 lượt. Nếu mục tiêu đã dính <Độc>, Shinobu đánh cắp 15% phòng thủ của kẻ địch và gây thêm một lần sát thương phụ bằng 10% lượng sát thương chính.',
		describe_en = 'Kochou Shinobu gracefully swings her blade, creating a blue slash like a butterfly’s gentle glide, striking a single enemy. The attack deals #C0x3D8A99#180% magic damage#C0x5B545B#+$(skillLevel*4*24)$ magic damage#C0x5B545B#, and inflicts <Poison>. <Poison> causes the enemy to lose 5% HP for 2 turns. If the target is already poisoned, Shinobu steals 15% of the enemy’s defense and deals an additional damage equal to 10% of the main damage',
		describe_th = 'โคะโจ ชิโนบุแกว่งดาบอย่างอ่อนช้อย สร้างคมดาบสีน้ำเงินดุจผีเสื้อโบยบิน โจมตีศัตรูเดี่ยว การโจมตีสร้างความเสียหายเวทมนตร์ #C0x3D8A99#180%#C0x5B545B#+$(skillLevel*4*24)$ ความเสียหายเวทมนตร์#C0x5B545B# และทำให้ศัตรูติด <พิษ> <พิษ> จะทำให้ศัตรูสูญเสีย 5% HP เป็นเวลา 2 เทิร์น หากเป้าหมายติด <พิษ> อยู่แล้ว ชิโนบุจะขโมยพลังป้องกันของศัตรู 15% และสร้างความเสียหายเพิ่มเติมอีก 10% ของความเสียหายหลัก',
		describe_in = 'Kochou Shinobu mengayunkan pedangnya dengan anggun, menciptakan tebasan biru seperti sayap kupu-kupu yang melayang, menyerang satu musuh. Serangan ini memberikan #C0x3D8A99#180% damage sihir#C0x5B545B#+$(skillLevel*4*24)$ damage sihir#C0x5B545B#, serta memberikan efek <Racun>. <Racun> membuat musuh kehilangan 5% HP selama 2 giliran. Jika target sudah terkena <Racun>, Shinobu mencuri 15% pertahanan musuh dan memberikan tambahan damage sebesar 10% dari damage utama.',
		describe_ph = 'Maingat na iwinasiwas ni Kochou Shinobu ang kanyang espada, lumilikha ng asul na hiwa na parang pakpak ng paru-paro na dumadausdos, at umatake sa isang kalabang target. Ang atake ay nagdudulot ng #C0x3D8A99#180% magic damage#C0x5B545B#+$(skillLevel*4*24)$ magic damage#C0x5B545B#, at naglalagay ng <Lason>. Ang <Lason> ay nag-aalis ng 5% HP ng kalaban sa loob ng 2 turn. Kung ang target ay mayroon nang <Lason>, ninanakaw ni Shinobu ang 15% ng depensa ng kalaban at nagdudulot ng karagdagang pinsala na katumbas ng 10% ng pangunahing pinsala.',
		describe_ma = 'Kochou Shinobu menghayunkan pedangnya dengan anggun, menghasilkan tebasan biru seperti kepak rama-rama yang beralun, menyerang musuh tunggal. Serangan ini memberikan #C0x3D8A99#180% kerosakan sihir#C0x5B545B#+$(skillLevel*4*24)$ kerosakan sihir#C0x5B545B#, serta mengenakan <Racun>. <Racun> menyebabkan musuh kehilangan 5% HP selama 2 giliran. Jika sasaran sudah terkena <Racun>, Shinobu mencuri 15% pertahanan musuh dan memberikan kerosakan tambahan sebanyak 10% daripada kerosakan utama.',
		describe = 'Kochou Shinobu gracefully swings her blade, creating a blue slash like a butterfly’s gentle glide, striking a single enemy. The attack deals #C0x3D8A99#180% magic damage#C0x5B545B#+$(skillLevel*4*24)$ magic damage#C0x5B545B#, and inflicts <Poison>. <Poison> causes the enemy to lose 5% HP for 2 turns. If the target is already poisoned, Shinobu steals 15% of the enemy’s defense and deals an additional damage equal to 10% of the main damage',
		simDesc = 'Chém kiếm lam gây sát thương phép thuật, đầu độc mục tiêu và đánh cắp giáp nếu địch đã bị Độc.',
		zawakeEffect = __data_t__zawakeEffect[80031],
		-- {79001}
		zawakeEffectDesc = '#C0xC0C0C0#Like water, invisible yet powerful#C0x5B545B#\n#F10#\n#F40#Satoshi in Armor Ha Nhan Qua gathers Water Shuriken, swiftly throwing it at a single enemy target (prioritizes the slowest enemy), dealing #C0x3D8A99#100% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#special#C0x5B545B# damage, stealing 10% Speed and 10% Magic Attack from the target, and inflicting 10% increased Water damage taken (can stack up to 3 layers), lasting 3 turns.',
		zawakeEffectDesc_en = '#C0xC0C0C0#Like water, invisible yet powerful#C0x5B545B#\n#F10#\n#F40#Satoshi in Armor Ha Nhan Qua gathers Water Shuriken, swiftly throwing it at a single enemy target (prioritizes the slowest enemy), dealing #C0x3D8A99#100% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#special#C0x5B545B# damage, stealing 10% Speed and 10% Magic Attack from the target, and inflicting 10% increased Water damage taken (can stack up to 3 layers), lasting 3 turns.',
		zawakeEffectDesc_th = '#C0xC0C0C0#ดังสายน้ำ มองไม่เห็นแต่ทรงพลัง#C0x5B545B#\n#F10#\n#F40#Satoshi แห่งเกราะ Ha Nhan Qua รวมพลังชูริเคนแห่งน้ำ ขว้างใส่เป้าหมายศัตรูเดี่ยวอย่างรวดเร็ว (โจมตีศัตรูที่มีความเร็วช้าที่สุดก่อน) สร้างความเสียหาย #C0x3D8A99#100% พลังเวท#C0x5B545B#+$(skillLevel*4*24)$ ความเสียหาย #C0xF13B54#พิเศษ#C0x5B545B#, ขโมย 10% ความเร็ว และ 10% พลังเวทของเป้าหมาย พร้อมทำให้ได้รับความเสียหายธาตุน้ำเพิ่มขึ้น 10% (สะสมได้สูงสุด 3 ชั้น) คงอยู่ 3 เทิร์น',
		zawakeEffectDesc_in = '#C0xC0C0C0#Seperti air, tak terlihat namun kuat#C0x5B545B#\n#F10#\n#F40#Satoshi dalam Armor Ha Nhan Qua mengumpulkan Shuriken Air, lalu dengan cepat melemparkannya ke target musuh tunggal (memprioritaskan musuh dengan kecepatan paling lambat), memberikan #C0x3D8A99#100% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ damage #C0xF13B54#spesial#C0x5B545B#, mencuri 10% Kecepatan dan 10% Serangan Sihir dari target, serta memberikan efek menerima 10% lebih banyak damage Elemen Air (dapat ditumpuk hingga 3 lapisan), berlangsung 3 giliran.',
		zawakeEffectDesc_ph = '#C0xC0C0C0#Tulad ng tubig, hindi nakikita ngunit makapangyarihan#C0x5B545B#\n#F10#\n#F40#Si Satoshi sa Armor Ha Nhan Qua ay nagtitipon ng Water Shuriken, mabilis itong ibinabato sa isang kalabang target (inuuna ang pinakamabagal na kalaban), nagdudulot ng #C0x3D8A99#100% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#espesyal#C0x5B545B# na pinsala, nagnanakaw ng 10% Speed at 10% Magic Attack mula sa target, at naglalagay ng debuff na tumatanggap ng +10% Water damage (maaaring maipon hanggang 3 stack), tumatagal ng 3 turn.',
		zawakeEffectDesc_ma = '#C0xC0C0C0#Seperti air, tidak kelihatan tetapi kuat#C0x5B545B#\n#F10#\n#F40#Satoshi dalam Armor Ha Nhan Qua mengumpulkan Shuriken Air, lalu segera membalingnya ke arah sasaran musuh tunggal (mengutamakan musuh yang paling perlahan), memberikan #C0x3D8A99#100% Serangan Magik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#kerosakan khas#C0x5B545B#, mencuri 10% Kelajuan dan 10% Serangan Magik daripada sasaran, serta memberikan kesan menerima +10% kerosakan Elemen Air (boleh ditindih sehingga 3 lapisan), bertahan selama 3 giliran.',
		zawakeEffectDesc_vn = '#C0xC0C0C0#Như nước, vô hình mà mạnh mẽ#C0x5B545B#\n#F10#\n#F40#Satoshi bản Giáp Hà Nhẫn Qua tụ hợp Phi Tiêu Nước nhỏ, nhanh chóng ném về phía mục tiêu đơn bên địch (ưu tiên tấn công kẻ có tốc độ chậm nhất), gây ra #C0x3D8A99#100% công pháp#C0x5B545B#+$(skillLevel*4*24)$ sát thương #C0xF13B54#đặc biệt#C0x5B545B#, đánh cắp 10% tốc độ và 10% công pháp của mục tiêu, kèm hiệu ứng dễ bị sát thương hệ Nước 10% (có thể cộng dồn 3 tầng), duy trì 3 lượt',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Steal 10% of the target\'s Speed and apply 10% Water Damage Vulnerability (can stack up to 3 layers), lasting 2 turns \n#F10#\n#F40##C0x5c9970#→ Steal 10% of the target\'s Speed and 10% of their Skill Power, apply 10% Water Damage Vulnerability (can stack up to 3 layers), lasting 3 turns',
		zawakeSimpleDesc_en = 'Steal 10% of the target\'s Speed and apply 10% Water Damage Vulnerability (can stack up to 3 layers), lasting 2 turns \n#F10#\n#F40##C0x5c9970#→ Steal 10% of the target\'s Speed and 10% of their Skill Power, apply 10% Water Damage Vulnerability (can stack up to 3 layers), lasting 3 turns',
		zawakeSimpleDesc_th = 'ขโมย 10% ความเร็วของเป้าหมาย และเพิ่ม 10% ความเปราะต่อความเสียหายระบบน้ำ (ซ้อนกันได้สูงสุด 3 ชั้น) คงอยู่ 2 ตา \n#F10#\n#F40##C0x5c9970#→ ขโมย 10% ความเร็วและ 10% พลังทักษะของเป้าหมาย เพิ่ม 10% ความเปราะต่อความเสียหายระบบน้ำ (ซ้อนกันได้สูงสุด 3 ชั้น) คงอยู่ 3 ตา',
		zawakeSimpleDesc_in = 'Mencuri 10% Kecepatan target dan memberikan 10% Kerentanan terhadap Kerusakan Air (dapat menumpuk hingga 3 lapisan), bertahan 2 giliran \n#F10#\n#F40##C0x5c9970#→ Mencuri 10% Kecepatan dan 10% Kekuatan Skill target, memberikan 10% Kerentanan terhadap Kerusakan Air (dapat menumpuk hingga 3 lapisan), bertahan 3 giliran',
		zawakeSimpleDesc_ph = 'Nakawin ang 10% ng Bilis ng target at magdagdag ng 10% Kahinaan sa Water Damage (maaaring mag-stack ng hanggang 3 layers), tumatagal ng 2 na turn \n#F10#\n#F40##C0x5c9970#→ Nakawin ang 10% Bilis at 10% Skill Power ng target, magdagdag ng 10% Kahinaan sa Water Damage (maaaring mag-stack ng hanggang 3 layers), tumatagal ng 3 na turn',
		zawakeSimpleDesc_ma = 'Curai 10% Kelajuan sasaran dan berikan 10% Kelemahan kepada Kerosakan Air (boleh bertindih sehingga 3 lapisan), bertahan 2 pusingan \n#F10#\n#F40##C0x5c9970#→ Curai 10% Kelajuan dan 10% Kuasa Kemahiran sasaran, berikan 10% Kelemahan kepada Kerosakan Air (boleh bertindih sehingga 3 lapisan), bertahan 3 pusingan',
		zawakeSimpleDesc_vn = 'Đánh cắp 10% tốc độ mục tiêu và kèm 10% dễ bị sát thương hệ Nước (có thể cộng dồn 3 tầng), duy trì 2 lượt\n#F10#\n#F40##C0x5c9970#→Đánh cắp 10% tốc độ và 10% công pháp mục tiêu, kèm 10% dễ bị sát thương hệ Nước (có thể cộng dồn 3 tầng), duy trì 3 lượt',
