	[80032] = {
		id = 80032,
		skillName_vn = 'Độc Ảnh Kiếm Kích',
		skillName_en = 'Poison Shadow Sword Strike',
		skillName_th = 'ดาบเงาพิษ แทงจู่โจม',
		skillName_in = 'Tebasan Pedang Bayangan Beracun',
		skillName_ph = 'Taga ng Espadang Aninong Lason',
		skillName_ma = 'Tikaman Pedang Bayangan Beracun',
		skillName = 'Poison Shadow Sword Strike',
		describe_vn = 'Kochou Shinobu tập trung năng lượng, lao kiếm về phía trước tấn công mục tiêu đơn bên địch, gây ra #C0x3D8A99#220% sát thương phép thuật#C0x5B545B#+$(skillLevel*4*28)$ sát thương phép thuật#C0x5B545B#. Nếu mục tiêu đã có Độc sẽ bị <Hỗn loạn> 1 lượt, mất quyền kiểm soát hành động; Nếu chưa dính Độc thì chịu <Giảm giáp> 50% trong 2 lượt. Khi Kochou Shinobu hạ gục mục tiêu bằng kỹ năng này, cô nhận được <Ẩn thân> trong 1 lượt, không thể bị chọn làm mục tiêu bởi các kỹ năng đơn lẻ.',
		describe_en = 'Kochou Shinobu concentrates her energy, thrusts her sword forward to attack a single enemy target, dealing #C0x3D8A99#220% magic damage#C0x5B545B#+$(skillLevel*4*28)$ magic damage#C0x5B545B#. If the target is already Poisoned, they will be inflicted with <Confusion> for 1 turn, losing control of their actions; If not Poisoned, they will suffer <Armor Reduction> by 50% for 2 turns. When Kochou Shinobu kills a target with this skill, she gains <Stealth> for 1 turn, making her untargetable by single-target skills.',
		describe_th = 'โคโจ ชิโนบุรวบรวมพลังงาน พุ่งดาบไปข้างหน้าโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#220%#C0x5B545B#+$(skillLevel*4*28)$ ความเสียหายเวทมนตร์#C0x5B545B# หากเป้าหมายติดพิษแล้ว จะถูกทำให้ <สับสน> 1 เทิร์น ไม่สามารถควบคุมการกระทำได้; หากยังไม่ติดพิษ จะได้รับผล <ลดเกราะ> 50% เป็นเวลา 2 เทิร์น เมื่อโคโจ ชิโนบุสังหารเป้าหมายด้วยสกิลนี้ เธอจะได้รับ <ล่องหน> 1 เทิร์น ไม่สามารถถูกเลือกเป็นเป้าหมายจากสกิลโจมตีเดี่ยวได้',
		describe_in = 'Kochou Shinobu memusatkan energi, menusukkan pedangnya ke depan menyerang satu target musuh, memberikan #C0x3D8A99#220% magic damage#C0x5B545B#+$(skillLevel*4*28)$ magic damage#C0x5B545B#. Jika target sudah terkena Racun, mereka akan terkena <Kebingungan> selama 1 giliran, kehilangan kendali atas aksinya; Jika belum terkena Racun, mereka akan menderita <Pengurangan Armor> sebesar 50% selama 2 giliran. Saat Kochou Shinobu menghabisi target dengan skill ini, ia mendapatkan <Menyamar> selama 1 giliran, membuatnya tidak dapat ditargetkan oleh skill single-target.',
		describe_ph = 'Pinupokus ni Kochou Shinobu ang kanyang enerhiya, inihahampas ang espada pasulong upang umatake sa isang kalabang target, nagdudulot ng #C0x3D8A99#220% magic damage#C0x5B545B#+$(skillLevel*4*28)$ magic damage#C0x5B545B#. Kung ang target ay may Lason na, sila ay malalagay sa <Pagkalito> sa loob ng 1 turn, mawawalan ng kontrol sa kanilang aksyon; Kung wala pang Lason, sila ay makakatanggap ng <Bawas Armor> ng 50% sa loob ng 2 turn. Kapag napatay ni Kochou Shinobu ang target gamit ang skill na ito, siya ay makakakuha ng <Paglalaho> sa loob ng 1 turn, na hindi siya maaaring maging target ng single-target skills.',
		describe_ma = 'Kochou Shinobu memusatkan tenaganya, menikam pedang ke hadapan untuk menyerang satu sasaran musuh, memberikan #C0x3D8A99#220% kerosakan sihir#C0x5B545B#+$(skillLevel*4*28)$ kerosakan sihir#C0x5B545B#. Jika sasaran sudah diracun, mereka akan dikenakan <Kekeliruan> selama 1 giliran, kehilangan kawalan tindakan; Jika belum diracun, mereka akan menerima <Pengurangan Perisai> sebanyak 50% selama 2 giliran. Apabila Kochou Shinobu membunuh sasaran dengan kemahiran ini, dia mendapat <Halimunan> selama 1 giliran, menjadikannya tidak dapat disasarkan oleh kemahiran single-target.',
		describe = 'Kochou Shinobu concentrates her energy, thrusts her sword forward to attack a single enemy target, dealing #C0x3D8A99#220% magic damage#C0x5B545B#+$(skillLevel*4*28)$ magic damage#C0x5B545B#. If the target is already Poisoned, they will be inflicted with <Confusion> for 1 turn, losing control of their actions; If not Poisoned, they will suffer <Armor Reduction> by 50% for 2 turns. When Kochou Shinobu kills a target with this skill, she gains <Stealth> for 1 turn, making her untargetable by single-target skills.',
		simDesc = 'Đâm kiếm gây sát thương phép thuật, có cơ hội gây Độc, hỗn loạn hoặc giảm giáp; hạ gục mục tiêu sẽ được ẩn thân.',
		zawakeEffect = __data_t__zawakeEffect[80032],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#The wise are without delusion, the ninja are invincible!#C0x5B545B#\n#F10#\n#F40#Satoshi Armor Ha Shinqua gathers water Kunai blades, swiftly slashing at a single enemy target (prioritizing the one with the slowest speed), dealing #C0x3D8A99#180% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#special#C0x5B545B# damage, with 100% chance to inflict <Stun> for 1 turn on the target and dispel 1 beneficial effect. If there is no beneficial effect to dispel or the target is under Slow effect, <Knockback> the target for 2 turns. At the same time, there is a chance equal to Speed difference ratio * number of enemies (guaranteed to trigger the first time) to create a <Super Ninja Clone> in place as a substitute. The user becomes hidden and cannot be targeted by enemies. When the Super Ninja Clone is destroyed, the real body immediately appears.\n#F10#\n#F40##L10#Knockback:#L0# Pushes the target to the end of the action bar; if already at the end, reduces 200 rage points.\n#F10#\n#F40##L10#Super Ninja Clone:#L0# Inherits 60% of the user’s stats, will endure and share all passive damage instead of the real body. The clone disappears after taking one active hit or when passive damage exceeds the limit. When destroyed, Satoshi Armor Ha Shinqua immediately reappears, counterattacking with a normal attack against the attacker, with 50% chance to stun the target for 1 turn.',
		zawakeEffectDesc_en = '#C0xC0C0C0#The wise are without delusion, the ninja are invincible!#C0x5B545B#\n#F10#\n#F40#Satoshi Armor Ha Shinqua gathers water Kunai blades, swiftly slashing at a single enemy target (prioritizing the one with the slowest speed), dealing #C0x3D8A99#180% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#special#C0x5B545B# damage, with 100% chance to inflict <Stun> for 1 turn on the target and dispel 1 beneficial effect. If there is no beneficial effect to dispel or the target is under Slow effect, <Knockback> the target for 2 turns. At the same time, there is a chance equal to Speed difference ratio * number of enemies (guaranteed to trigger the first time) to create a <Super Ninja Clone> in place as a substitute. The user becomes hidden and cannot be targeted by enemies. When the Super Ninja Clone is destroyed, the real body immediately appears.\n#F10#\n#F40##L10#Knockback:#L0# Pushes the target to the end of the action bar; if already at the end, reduces 200 rage points.\n#F10#\n#F40##L10#Super Ninja Clone:#L0# Inherits 60% of the user’s stats, will endure and share all passive damage instead of the real body. The clone disappears after taking one active hit or when passive damage exceeds the limit. When destroyed, Satoshi Armor Ha Shinqua immediately reappears, counterattacking with a normal attack against the attacker, with 50% chance to stun the target for 1 turn.',
		zawakeEffectDesc_th = '#C0xC0C0C0#ปราชญ์ไร้ความหลง นินจาไร้ผู้ต้าน!#C0x5B545B#\n#F10#\n#F40#ซาโตชิ เกราะ ฮะ ชินควะ รวมพลังคุนายน้ำ ฟันใส่ศัตรูเดี่ยวอย่างรวดเร็ว (โจมตีศัตรูที่มีความเร็วช้าที่สุดก่อน) สร้างความเสียหาย #C0x3D8A99#180% พลังเวท#C0x5B545B#+$(skillLevel*4*48)$ ความเสียหาย #C0xF13B54#พิเศษ#C0x5B545B# มีโอกาส 100% ทำให้เป้าหมาย <สตัน> 1 เทิร์น และลบ 1 ผลบัฟออก หากไม่มีผลบัฟให้ลบหรือเป้าหมายอยู่ในสถานะลดความเร็ว จะ <ผลักถอยหลัง> เป้าหมาย 2 เทิร์น นอกจากนี้ยังมีโอกาสตามอัตราส่วนความต่างความเร็ว * จำนวนศัตรู (ครั้งแรกการันตี) เพื่อสร้าง <ร่างแยกนินจาสุดยอด> แทนที่ ผู้ใช้จะเข้าสู่สถานะซ่อนตัวและไม่สามารถถูกเลือกเป็นเป้าหมายได้ เมื่อร่างแยกถูกทำลาย ร่างจริงจะปรากฏทันที\n#F10#\n#F40##L10#ผลักถอยหลัง:#L0# ดันเป้าหมายไปท้ายแถบการกระทำ ถ้าอยู่ท้ายแล้วจะลด 200 แต้มโกรธ\n#F10#\n#F40##L10#ร่างแยกนินจาสุดยอด:#L0# สืบทอด 60% ค่าสถานะจากร่างจริง รับและแบ่งความเสียหายแบบพาสซีฟแทนร่างจริง ร่างแยกจะหายไปหลังจากโดนการโจมตีแบบแอคทีฟหนึ่งครั้ง หรือความเสียหายพาสซีฟเกินขีดจำกัด เมื่อถูกทำลาย ซาโตชิ เกราะ ฮะ ชินควะ จะโผล่มาทันทีและโจมตีกลับด้วยการโจมตีปกติใส่ศัตรูที่โจมตี มีโอกาส 50% ทำให้เป้าหมายสตัน 1 เทิร์น',
		zawakeEffectDesc_in = '#C0xC0C0C0#Orang bijak tanpa kebingungan, ninja tak terkalahkan!#C0x5B545B#\n#F10#\n#F40#Satoshi Armor Ha Shinqua mengumpulkan pisau Kunai air, dengan cepat menebas target musuh tunggal (memprioritaskan yang memiliki kecepatan paling lambat), memberikan #C0x3D8A99#180% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#kerusakan khusus#C0x5B545B#, dengan 100% peluang menyebabkan <Stun> selama 1 giliran pada target dan menghapus 1 efek menguntungkan. Jika tidak ada efek menguntungkan untuk dihapus atau target terkena efek Slow, maka akan <Knockback> target selama 2 giliran. Pada saat yang sama, ada peluang sebesar rasio perbedaan kecepatan * jumlah musuh (pasti aktif pertama kali) untuk menciptakan <Klon Ninja Super> di tempat sebagai pengganti. Pengguna bersembunyi dan tidak dapat ditargetkan musuh. Saat Klon Ninja Super dihancurkan, tubuh asli segera muncul.\n#F10#\n#F40##L10#Knockback:#L0# Mendorong target ke akhir bar aksi; jika sudah di akhir, mengurangi 200 poin amarah.\n#F10#\n#F40##L10#Klon Ninja Super:#L0# Mewarisi 60% atribut tubuh asli, akan menanggung dan berbagi semua kerusakan pasif sebagai pengganti tubuh asli. Klon menghilang setelah menerima satu serangan aktif atau kerusakan pasif melebihi batas. Saat dihancurkan, Satoshi Armor Ha Shinqua segera muncul, melakukan serangan balik dengan serangan normal ke penyerang, dengan 50% peluang memberikan stun pada target selama 1 giliran.',
		zawakeEffectDesc_ph = '#C0xC0C0C0#Ang matalino ay walang pagkalito, ang ninja ay walang talo!#C0x5B545B#\n#F10#\n#F40#Si Satoshi Armor Ha Shinqua ay nagtipon ng mga talim na Kunai ng tubig, mabilis na umatake sa isang kalabang target (inuuna ang pinakamabagal), nagdudulot ng #C0x3D8A99#180% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#espesyal#C0x5B545B# na pinsala, na may 100% tsansa na magdulot ng <Stun> ng 1 turn sa target at alisin ang 1 benepisyong epekto. Kung walang benepisyong epekto na matatanggal o nasa ilalim ng Slow ang target, ito ay <Knockback> sa loob ng 2 turn. Kasabay nito, may tsansa batay sa ratio ng bilis * bilang ng kalaban (tiyak na magti-trigger sa unang beses) upang lumikha ng isang <Super Ninja Clone> sa lugar bilang kapalit. Ang katawan ay nagiging nakatago at hindi maaaring maging target ng kalaban. Kapag nawasak ang Super Ninja Clone, agad na lilitaw ang tunay na katawan.\n#F10#\n#F40##L10#Knockback:#L0# Itinutulak ang target sa dulo ng action bar; kung nasa dulo na, binabawasan ng 200 rage points.\n#F10#\n#F40##L10#Super Ninja Clone:#L0# Namamana ang 60% ng stats ng katawan, tatanggap at magbabahagi ng lahat ng passive damage bilang kapalit ng tunay na katawan. Mawawala ang clone matapos tumanggap ng isang aktibong atake o kapag lumampas sa limitasyon ang passive damage. Kapag nawasak, agad na lilitaw si Satoshi Armor Ha Shinqua, babawi gamit ang normal na atake sa umatake, na may 50% tsansa na ma-stun ang target ng 1 turn.',
		zawakeEffectDesc_ma = '#C0xC0C0C0#Bijak tanpa kekeliruan, ninja tanpa tandingan!#C0x5B545B#\n#F10#\n#F40#Satoshi Armor Ha Shinqua mengumpulkan bilah Kunai air, dengan pantas menebas sasaran musuh tunggal (utamakan yang paling perlahan), memberikan #C0x3D8A99#180% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#kerosakan khas#C0x5B545B#, dengan 100% peluang menyebabkan <Stun> selama 1 giliran ke sasaran dan menghapus 1 kesan positif. Jika tiada kesan positif untuk dihapuskan atau sasaran berada dalam status Slow, ia akan <Knockback> sasaran selama 2 giliran. Pada masa yang sama, terdapat peluang berdasarkan nisbah perbezaan kelajuan * bilangan musuh (pasti aktif pada kali pertama) untuk mencipta <Klon Ninja Super> di tempat sebagai pengganti. Pengguna bersembunyi dan tidak boleh dijadikan sasaran oleh musuh. Apabila Klon Ninja Super dimusnahkan, tubuh asal segera muncul.\n#F10#\n#F40##L10#Knockback:#L0# Menolak sasaran ke hujung bar tindakan; jika sudah berada di hujung, mengurangkan 200 mata kemarahan.\n#F10#\n#F40##L10#Klon Ninja Super:#L0# Mewarisi 60% atribut tubuh asal, akan menanggung dan berkongsi semua kerosakan pasif menggantikan tubuh asal. Klon hilang selepas menerima satu serangan aktif atau apabila kerosakan pasif melebihi had. Apabila dimusnahkan, Satoshi Armor Ha Shinqua segera muncul, membalas dengan serangan biasa kepada penyerang, dengan 50% peluang menyebabkan stun ke sasaran selama 1 giliran.',
		zawakeEffectDesc_vn = '#C0xC0C0C0#Trí giả vô hoặc, nhẫn giả vô địch!#C0x5B545B#\n#F10#\n#F40#Satoshi bản Giáp Hà Nhẫn Qua tụ hợp lưỡi dao Kunai nước nhanh chóng lao chém vào mục tiêu đơn bên địch (ưu tiên tấn công kẻ có tốc độ chậm nhất), gây ra #C0x3D8A99#180% công pháp#C0x5B545B#+$(skillLevel*4*48)$ sát thương #C0xF13B54#đặc biệt#C0x5B545B#, có 100% xác suất gây <Choáng>1 lượt lên mục tiêu và xua tan 1 hiệu ứng có lợi, nếu không có hiệu ứng có lợi để xua tan hoặc mục tiêu đang chịu hiệu ứng giảm tốc thì sẽ <Đẩy lui>mục tiêu 2 lượt, đồng thời có xác suất bằng tỷ lệ chênh lệch tốc độ * số lượng kẻ địch (lần đầu chắc chắn kích hoạt) để tạo ra một <Phân thân Siêu Nhẫn>tại chỗ làm thế thân, bản thân ẩn mình và không thể bị kẻ địch chọn làm mục tiêu, khi Phân thân Siêu Nhẫn bị phá hủy thì bản thể lập tức hiện thân\n#F10#\n#F40##L10#Đẩy lui：#L0#đưa mục tiêu xuống cuối thanh hành động, nếu đã ở cuối thì giảm 200 điểm nộ khí\n#F10#\n#F40##L10#Phân thân Siêu Nhẫn：#L0#kế thừa 60% thuộc tính bản thể, sẽ gánh chịu và chia sẻ toàn bộ sát thương bị động thay bản thể, phân thân sẽ biến mất sau khi chịu một đòn chủ động hoặc sát thương bị động vượt mức, khi bị phá hủy Satoshi bản Giáp Hà Nhẫn Qua lập tức xuất hiện, phản công bằng đòn đánh thường vào kẻ tấn công, có 50% xác suất gây choáng mục tiêu 1 lượt',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'The Super Ninja Clone inherits 60% of the attributes; when destroyed, Satoshi Armor Ninja immediately appears, counterattacking with a normal attack on the attacker, with a 50% chance to stun the target for 1 turn',
		zawakeSimpleDesc_en = 'The Super Ninja Clone inherits 60% of the attributes; when destroyed, Satoshi Armor Ninja immediately appears, counterattacking with a normal attack on the attacker, with a 50% chance to stun the target for 1 turn',
		zawakeSimpleDesc_th = 'ร่างโคลนซูเปอร์นินจาสืบทอดคุณสมบัติ 60% เมื่อถูกทำลาย Satoshi Giáp Hà Nhẫn Qua จะปรากฏทันที ตอบโต้ด้วยการโจมตีปกติต่อผู้โจมตี มีโอกาส 50% ที่จะทำให้เป้าหมายมึนงง 1 ตา',
		zawakeSimpleDesc_in = 'Super Ninja Clone mewarisi 60% atribut; ketika dihancurkan, Satoshi Armor Ninja segera muncul, menyerang balik dengan serangan normal ke penyerang, dengan peluang 50% untuk membuat target stun selama 1 giliran',
		zawakeSimpleDesc_ph = 'Ang Super Ninja Clone ay namamana ng 60% ng mga katangian; kapag nawasak, agad na lalabas si Satoshi Armor Ninja, kumokontra gamit ang normal na atake sa attacker, may 50% tsansa na ma-stun ang target sa loob ng 1 turn',
		zawakeSimpleDesc_ma = 'Klona Super Ninja mewarisi 60% atribut; apabila dimusnahkan, Satoshi Armor Ninja akan muncul serta-merta, menyerang balas dengan serangan biasa ke penyerang, dengan peluang 50% untuk membuat sasaran terhentak selama 1 pusingan',
		zawakeSimpleDesc_vn = 'Phân thân Siêu Nhẫn kế thừa 60% thuộc tính, khi bị phá hủy Satoshi bản Giáp Hà Nhẫn Qua lập tức xuất hiện, phản công bằng đòn đánh thường vào kẻ tấn công, có 50% xác suất gây choáng mục tiêu 1 lượt',
		iconRes = 'battle/skill_icon/skill_80032.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 1,
		skillDamageType = 1,
		skillNatureType = 12,
