	[80033] = {
		id = 80033,
		skillName_vn = 'Tử Điệp Ẩn Sát',
		skillName_en = 'Hidden Assassination of the Violet Butterfly',
		skillName_th = 'ผีเสื้อม่วงสังหารลับ',
		skillName_in = 'Kupu-Kupu Ungu: Pembunuhan Tersembunyi',
		skillName_ph = 'Paruparong Ube: Lihim na Pagpaslang',
		skillName_ma = 'Rama-Rama Ungu: Pembunuhan Tersembunyi',
		skillName = 'Hidden Assassination of the Violet Butterfly',
		describe_vn = 'Kochou Shinobu tung liên hoàn đòn chém kiếm ngắn khiến toàn bộ kẻ địch nhiễm <Độc> trong 2 lượt và  gây <Choáng> cho ngẫu nhiên một kẻ địch trong 1 lượt, sau đó lộn nhào né tránh rồi lao kiếm tấn công các mục tiêu bên địch, gây #C0x3D8A99#550% sát thương phép thuật + $(skillLevel*4*90)$ sát thương phép thuật #C0x5B545B#, hồi 20% máu từ sát thương gây ra. Shinobu đồng thời tăng 15% tốc độ trong 2 lượt. Kết thúc chuỗi kiếm, Shinobu tạo một vụ nổ để rút lui <Ẩn thân> trong 1 lượt và gây sát thương phép lên toàn bộ kẻ địch gây <Suy Nhược> (giảm 10% sát thương gây ra trong 1 lượt), <Vết Thương Sâu> giảm 50% hồi phục) trong 2 lượt.',
		describe_en = 'Kochou Shinobu unleashes a flurry of short sword slashes, inflicting <Poison> on all enemies for 2 turns and causing <Stun> on a random enemy for 1 turn. She then somersaults to evade and lunges with her blade, striking enemy targets for #C0x3D8A99#550% Magic Damage + $(skillLevel*4*90)$ Magic Damage #C0x5B545B#, restoring 20% HP from the damage dealt. Shinobu also gains 15% Speed for 2 turns. At the end of the sword combo, Shinobu creates an explosion to retreat into <Stealth> for 1 turn and deals magic damage to all enemies, applying <Weaken> (reduces damage dealt by 10% for 1 turn) and <Deep Wound> (reduces healing received by 50%) for 2 turns.',
		describe_th = 'โคโจ ชิโนบุปลดปล่อยการฟันดาบสั้น連撃 ทำให้ศัตรูทั้งหมดติดสถานะ <พิษ> เป็นเวลา 2 เทิร์น และทำให้ศัตรูสุ่ม 1 ตัวติด <สตัน> เป็นเวลา 1 เทิร์น จากนั้นเธอกลิ้งตัวเพื่อหลบหลีกและพุ่งดาบโจมตีศัตรู สร้างความเสียหายเวท #C0x3D8A99#550% + $(skillLevel*4*90)$ ความเสียหายเวท #C0x5B545B# พร้อมฟื้นฟู HP 20% จากความเสียหายที่สร้างได้ ชิโนบุยังได้รับความเร็วเพิ่มขึ้น 15% เป็นเวลา 2 เทิร์น เมื่อจบคอมโบดาบ ชิโนบุสร้างการระเบิดเพื่อถอยและเข้าสู่สถานะ <ล่องหน> เป็นเวลา 1 เทิร์น พร้อมสร้างความเสียหายเวทใส่ศัตรูทั้งหมด และทำให้ติด <อ่อนแอ> (ลดความเสียหายที่ทำได้ 10% เป็นเวลา 1 เทิร์น) และ <บาดแผลลึก> (ลดการฟื้นฟู 50%) เป็นเวลา 2 เทิร์น',
		describe_in = 'Kochou Shinobu melancarkan tebasan pedang pendek beruntun yang membuat semua musuh terkena <Racun> selama 2 giliran dan menyebabkan <Stun> pada 1 musuh acak selama 1 giliran. Ia lalu berguling menghindar dan menusuk musuh dengan pedangnya, memberikan #C0x3D8A99#550% Magic Damage + $(skillLevel*4*90)$ Magic Damage #C0x5B545B#, memulihkan 20% HP dari kerusakan yang diberikan. Shinobu juga mendapatkan 15% Kecepatan selama 2 giliran. Di akhir combo pedang, Shinobu menciptakan ledakan untuk mundur ke dalam <Menyamar> selama 1 giliran dan memberikan Magic Damage kepada semua musuh, serta memberikan <Lemah> (mengurangi 10% damage yang dihasilkan selama 1 giliran) dan <Luka Dalam> (mengurangi penyembuhan sebesar 50%) selama 2 giliran.',
		describe_ph = 'Si Kochou Shinobu ay nagpapakawala ng sunod-sunod na mga hiwa gamit ang maikling espada, naglalagay ng <Lason> sa lahat ng kalaban sa loob ng 2 turn at nagdudulot ng <Pagkakahilo> sa isang random na kalaban sa loob ng 1 turn. Pagkatapos ay gumulong siya upang umiwas at sumugod gamit ang espada, nagdudulot ng #C0x3D8A99#550% Magic Damage + $(skillLevel*4*90)$ Magic Damage #C0x5B545B#, na nagbabalik ng 20% HP mula sa pinsalang nagawa. Nakakakuha rin si Shinobu ng 15% Bilis sa loob ng 2 turn. Sa pagtatapos ng combo ng espada, lumilikha si Shinobu ng pagsabog upang umurong sa <Pagkubli> sa loob ng 1 turn at magdulot ng Magic Damage sa lahat ng kalaban, na naglalagay ng <Panghihina> (binabawasan ang damage na naibibigay ng 10% sa loob ng 1 turn) at <Malalim na Sugat> (binabawasan ang paggaling ng 50%) sa loob ng 2 turn.',
		describe_ma = 'Kochou Shinobu melepaskan serangan bertubi-tubi dengan pedang pendek, menyebabkan semua musuh terkena <Racun> selama 2 giliran dan memberikan <Pengsan> kepada 1 musuh rawak selama 1 giliran. Dia kemudian berguling untuk mengelak dan menikam musuh dengan pedangnya, memberikan #C0x3D8A99#550% Magic Damage + $(skillLevel*4*90)$ Magic Damage #C0x5B545B#, memulihkan 20% HP daripada kerosakan yang diberikan. Shinobu juga mendapat 15% Kelajuan selama 2 giliran. Di akhir combo pedang, Shinobu mencipta letupan untuk berundur ke dalam <Menyamar> selama 1 giliran dan memberikan Magic Damage kepada semua musuh, serta mengenakan <Lemah> (mengurangkan 10% damage yang dilakukan selama 1 giliran) dan <Luka Parah> (mengurangkan pemulihan sebanyak 50%) selama 2 giliran.',
		describe = 'Kochou Shinobu tung liên hoàn đòn chém kiếm ngắn khiến toàn bộ kẻ địch nhiễm <Độc> trong 2 lượt và  gây <Choáng> cho ngẫu nhiên một kẻ địch trong 1 lượt, sau đó lộn nhào né tránh rồi lao kiếm tấn công các mục tiêu bên địch, gây #C0x3D8A99#550% sát thương phép thuật + $(skillLevel*4*90)$ sát thương phép thuật #C0x5B545B#, hồi 20% máu từ sát thương gây ra. Shinobu đồng thời tăng 15% tốc độ trong 2 lượt. Kết thúc chuỗi kiếm, Shinobu tạo một vụ nổ để rút lui <Ẩn thân> trong 1 lượt và gây sát thương phép lên toàn bộ kẻ địch gây <Suy Nhược> (giảm 10% sát thương gây ra trong 1 lượt), <Vết Thương Sâu> giảm 50% hồi phục) trong 2 lượt.',
		simDesc = 'Tuyệt kỹ đâm kiếm mạnh gây choáng ngẫu nhiên một kẻ địch, sát thương lớn và hút máu; kết thúc lan sát thương diện rộng và gây suy yếu, độc lên toàn bộ kẻ địch. Vào trạng thái <Ẩn thân> sau khi kết thúc chiêu.',
		starEffect = __data_t__starEffect[80033],
		-- {11}
		starEffectDesc_vn = 'Khi nâng cấp sao, sát thương tuyệt kỹ tăng mạnh và tỷ lệ hút máu được cường hóa. Sau khi kích hoạt <Tử Điệp Ẩn Sát>, Shinobu nhận thêm hiệu ứng đặc biệt trong 1 lượt: tăng 50% tốc độ, hồi 15% nộ sau khi tung chiêu và nếu mục tiêu trúng chiêu đang bị Độc, sẽ chịu thêm 20% sát thương phép. Đồng thời, Shinobu hồi máu bằng 40% lượng sát thương gây ra .',
		starEffectDesc = 'When upgrading stars, the ultimate skill damage increases significantly and the lifesteal rate is enhanced. After activating <Silent Death of the Poison Butterfly>, Shinobu gains an additional special effect for 1 turn: increases speed by 50%, restores 15% rage after casting the skill, and if the target hit is Poisoned, they take an additional 20% magic damage. At the same time, Shinobu heals for 40% of the damage dealt.',
		starEffectDesc_en = 'When upgrading stars, the ultimate skill damage increases significantly and the lifesteal rate is enhanced. After activating <Silent Death of the Poison Butterfly>, Shinobu gains an additional special effect for 1 turn: increases speed by 50%, restores 15% rage after casting the skill, and if the target hit is Poisoned, they take an additional 20% magic damage. At the same time, Shinobu heals for 40% of the damage dealt.',
		starEffectDesc_th = 'เมื่ออัปเกรดดาว ความเสียหายของสกิลอัลติเมทจะเพิ่มขึ้นอย่างมากและอัตราการดูดเลือดได้รับการเสริม หลังจากเปิดใช้งาน <การสังหารลับผีเสื้อพิษ> ชิโนบุจะได้รับเอฟเฟกต์พิเศษเพิ่มเติมเป็นเวลา 1 เทิร์น: เพิ่มความเร็ว 50% ฟื้นคืนโทสะ 15% หลังจากใช้สกิล และหากเป้าหมายที่โดนโจมตีติดพิษ จะได้รับความเสียหายเวทเพิ่มขึ้น 20% พร้อมกันนี้ ชิโนบุจะฟื้นฟูพลังชีวิตเท่ากับ 40% ของความเสียหายที่สร้างได้',
		starEffectDesc_in = 'Saat meningkatkan bintang, damage ultimate meningkat secara signifikan dan tingkat lifesteal diperkuat. Setelah mengaktifkan <Pembunuhan Tersembunyi Kupu-Kupu Racun>, Shinobu mendapatkan efek khusus tambahan selama 1 giliran: meningkatkan kecepatan sebesar 50%, memulihkan 15% amarah setelah mengeluarkan skill, dan jika target yang terkena berada dalam kondisi Racun, mereka menerima 20% damage sihir tambahan. Pada saat yang sama, Shinobu memulihkan HP sebesar 40% dari damage yang diberikan.',
		starEffectDesc_ph = 'Kapag nag-upgrade ng bituin, malaki ang pagtaas ng damage ng ultimate at pinapalakas ang lifesteal rate. Pagkatapos i-activate ang <Tahimik na Pagpatay ng Paru-parong May Lason>, makakakuha si Shinobu ng karagdagang espesyal na epekto sa loob ng 1 turn: tataas ng 50% ang bilis, makakabawi ng 15% rage matapos gumamit ng skill, at kung ang tinamaan na target ay may Lason, tatanggap sila ng karagdagang 20% magic damage. Kasabay nito, maghihilom si Shinobu ng HP na katumbas ng 40% ng nagawang damage.',
		starEffectDesc_ma = 'Apabila menaik taraf bintang, kerosakan kemahiran muktamad meningkat dengan ketara dan kadar serapan nyawa dipertingkatkan. Selepas mengaktifkan <Pembunuhan Senyap Rama-Rama Beracun>, Shinobu mendapat kesan khas tambahan selama 1 pusingan: meningkatkan kelajuan sebanyak 50%, memulihkan 15% kemarahan selepas menggunakan kemahiran, dan jika sasaran yang terkena berada dalam keadaan Racun, mereka akan menerima 20% kerosakan sihir tambahan. Pada masa yang sama, Shinobu memulihkan HP sebanyak 40% daripada kerosakan yang dilakukan.',
		zawakeEffect = __data_t__zawakeEffect[80033],
		-- {79003, 1}
		zawakeEffectDesc = 'Wave-Cutting Combo Slash: Number of strikes +1, base damage increased from 60% magic attack to 80% magic attack (each additional enemy increases damage by 20% magic attack), and can dispel 1 beneficial effect from the target. If there is no beneficial effect to dispel or the target is under a Slow effect, the target will be <Pushed Back> for 1 turn. Every 3 normal attacks, enter the <Shadow Assassination> state, summoning a Super Ninja Clone as a substitute, and enhance the next ultimate skill to ignore all ultimate damage reduction of the target, additionally inflicting the <Water Shadow Combo>.\n#F10#\n#F40##L10#Water Shadow Combo:#L0#Summon up to 5 Super Ninja Clones to soar into the air (base 2 clones, summon 1 additional clone for every 15% current Speed increase compared to base Speed). All clones throw Water Shuriken to attack random enemy targets, dealing damage equal to 200% of the Clone’s magic attack.',
		zawakeEffectDesc_en = 'Wave-Cutting Combo Slash: Number of strikes +1, base damage increased from 60% magic attack to 80% magic attack (each additional enemy increases damage by 20% magic attack), and can dispel 1 beneficial effect from the target. If there is no beneficial effect to dispel or the target is under a Slow effect, the target will be <Pushed Back> for 1 turn. Every 3 normal attacks, enter the <Shadow Assassination> state, summoning a Super Ninja Clone as a substitute, and enhance the next ultimate skill to ignore all ultimate damage reduction of the target, additionally inflicting the <Water Shadow Combo>.\n#F10#\n#F40##L10#Water Shadow Combo:#L0#Summon up to 5 Super Ninja Clones to soar into the air (base 2 clones, summon 1 additional clone for every 15% current Speed increase compared to base Speed). All clones throw Water Shuriken to attack random enemy targets, dealing damage equal to 200% of the Clone’s magic attack.',
		zawakeEffectDesc_th = 'ฟ้าผ่าฟันคลื่น: จำนวนครั้งโจมตี +1 ความเสียหายพื้นฐานเพิ่มจาก 60% พลังเวท เป็น 80% พลังเวท (ศัตรูเพิ่ม 1 ตัว เพิ่มความเสียหายอีก 20% พลังเวท) และสามารถลบ 1 สถานะบัฟของเป้าหมายได้ หากไม่มีสถานะบัฟให้ลบหรือเป้าหมายอยู่ในสถานะลดความเร็ว จะทำให้เป้าหมายถูก <ผลักถอย> 1 เทิร์น ทุกครั้งที่โจมตีปกติครบ 3 ครั้ง จะเข้าสู่สถานะ <สังหารเงา> เรียก เงานินจาสุดยอด ขึ้นมาแทนตัวเอง และเสริมพลังสกิลอัลติเมตครั้งถัดไป ทำให้สกิลอัลติเมตเพิกเฉยต่อการลดความเสียหายทั้งหมดของเป้าหมาย และมาพร้อมเอฟเฟกต์ <เงาน้ำโจมตีต่อเนื่อง>\n#F10#\n#F40##L10#เงาน้ำโจมตีต่อเนื่อง:#L0#สามารถเรียก เงานินจาสุดยอด ได้สูงสุด 5 ตัว ลอยขึ้นฟ้า (เริ่มต้น 2 ตัว และเพิ่ม 1 ตัว ทุกๆ ที่ความเร็วปัจจุบันเพิ่มขึ้น 15% จากค่าพื้นฐาน) เงาทั้งหมดจะขว้างชูริเคนน้ำโจมตีเป้าหมายแบบสุ่ม ฝ่ายศัตรู สร้างความเสียหายเท่ากับ 200% พลังเวทของ เงานินจาสุดยอด',
		zawakeEffectDesc_in = 'Tebasan Gabungan Pemecah Ombak: Jumlah serangan +1, damage dasar meningkat dari 60% serangan sihir menjadi 80% serangan sihir (setiap musuh tambahan meningkatkan 20% serangan sihir), serta dapat menghapus 1 efek menguntungkan dari target. Jika tidak ada efek menguntungkan untuk dihapus atau target sedang terkena efek Slow, maka target akan <Didorong Mundur> selama 1 giliran. Setiap 3 serangan normal, masuk ke status <Pembunuh Bayangan> memanggil Klon Ninja Super sebagai pengganti, sekaligus memperkuat skill ultimate berikutnya agar mengabaikan semua pengurangan damage ultimate target, serta memberikan efek <Kombo Bayangan Air>.\n#F10#\n#F40##L10#Kombo Bayangan Air:#L0#Memanggil hingga 5 Klon Ninja Super untuk terbang ke udara (dasar 2 klon, memanggil 1 klon tambahan setiap kali kecepatan saat ini meningkat 15% dibandingkan kecepatan dasar). Semua klon melemparkan Shuriken Air menyerang target musuh acak, memberikan damage sebesar 200% serangan sihir dari Klon Ninja Super.',
		zawakeEffectDesc_ph = 'Wave-Cutting Combo Slash: +1 hit count, base damage increases from 60% magic attack to 80% magic attack (each additional enemy adds 20% magic attack), and can dispel 1 beneficial effect from the target. If there’s no beneficial effect to dispel or the target is under a Slow effect, the target will be <Itinulak Pabalik> for 1 turn. Every 3 normal attacks, enter the <Shadow Assassination> state, summoning a Super Ninja Clone as a substitute, and empower the next ultimate skill to ignore all ultimate damage reduction of the target, while applying <Water Shadow Combo>.\n#F10#\n#F40##L10#Water Shadow Combo:#L0#Summon up to 5 Super Ninja Clones to rise into the air (base 2 clones, summon 1 more clone every time current Speed increases by 15% compared to base Speed). All clones throw Water Shuriken at random enemy targets, dealing damage equal to 200% of the Clone’s magic attack.',
		zawakeEffectDesc_ma = 'Tebasan Kombinasi Pemecah Ombak: Bilangan serangan +1, kerosakan asas meningkat daripada 60% serangan sihir kepada 80% serangan sihir (setiap musuh tambahan menambah 20% serangan sihir), serta boleh menghapuskan 1 kesan positif pada sasaran. Jika tiada kesan positif untuk dihapuskan atau sasaran berada dalam kesan Perlahan, sasaran akan <Ditolak Mundur> selama 1 giliran. Setiap 3 serangan biasa, masuk ke dalam keadaan <Pembunuh Bayang> memanggil Klon Ninja Super sebagai pengganti, dan memperkuatkan kemahiran muktamad seterusnya untuk mengabaikan semua pengurangan kerosakan muktamad pada sasaran, sambil menambahkan kesan <Kombo Bayang Air>.\n#F10#\n#F40##L10#Kombo Bayang Air:#L0#Memanggil sehingga 5 Klon Ninja Super untuk terbang ke udara (asas 2 klon, memanggil 1 klon tambahan setiap kali Kelajuan semasa meningkat 15% berbanding Kelajuan asas). Semua klon melontarkan Shuriken Air menyerang sasaran musuh rawak, memberikan kerosakan bersamaan dengan 200% serangan sihir Klon Ninja Super.',
		zawakeEffectDesc_vn = 'Phá Lãng Cư Hợp Trảm số lần +1, sát thương cơ bản tăng từ 60% công pháp lên 80% công pháp (mỗi thêm 1 kẻ địch tăng thêm 20% công pháp), đồng thời có thể xua tan 1 hiệu ứng có lợi của mục tiêu, nếu không có hiệu ứng có lợi để xua tan hoặc mục tiêu đang chịu hiệu ứng giảm tốc thì sẽ <Đẩy lui>mục tiêu 1 lượt; mỗi khi đánh thường 3 lần sẽ bước vào trạng thái <Ảnh Sát>triệu hồi một Phân Thân Siêu Nhẫn làm thế thân, đồng thời cường hóa đòn tuyệt kỹ tiếp theo, khiến tuyệt kỹ bỏ qua toàn bộ giảm sát thương tuyệt kỹ của mục tiêu và kèm theo hiệu ứng <Thủy Ảnh Liên Kích>\n#F10#\n#F40##L10#Thủy Ảnh Liên Kích：#L0#Triệu hồi tối đa 5 Phân Thân Siêu Nhẫn bay lên không (cơ bản 2 phân thân, mỗi khi tốc độ hiện tại tăng thêm 15% so với tốc độ gốc thì triệu hồi thêm 1 Phân Thân Siêu Nhẫn), tất cả cùng tung Phi Tiêu Nước tấn công mục tiêu ngẫu nhiên bên địch, gây sát thương bằng 200% công pháp của Phân Thân Siêu Nhẫn',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Shattered Mist Blade: base damage increased from 60% to 80% Magic Power (each additional enemy increases Magic Power by 20%), while dispelling 1 beneficial effect; if there is no beneficial effect to dispel or the target is under a slow effect, the target is <Pushed Back> for 1 turn. Shadow State ignores all target\'s skill damage reduction.',
		zawakeSimpleDesc_en = 'Shattered Mist Blade: base damage increased from 60% to 80% Magic Power (each additional enemy increases Magic Power by 20%), while dispelling 1 beneficial effect; if there is no beneficial effect to dispel or the target is under a slow effect, the target is <Pushed Back> for 1 turn. Shadow State ignores all target\'s skill damage reduction.',
		zawakeSimpleDesc_th = 'Phá Lãng Cư Hợp Trảm: ความเสียหายพื้นฐานเพิ่มจาก 60% พลังเวทเป็น 80% พลังเวท (แต่ละศัตรูเพิ่มพลังเวทอีก 20%) และสลายเอฟเฟกต์บวก 1 ชิ้น; หากไม่มีเอฟเฟกต์บวกให้สลายหรือเป้าหมายอยู่ในสถานะช้า จะ <ผลักกลับ> เป้าหมาย 1 ตา สถานะเงาโจมตีละเว้นการลดความเสียหายของเป้าหมายทั้งหมด',
		zawakeSimpleDesc_in = 'Phá Lãng Cư Hợp Trảm: damage dasar meningkat dari 60% menjadi 80% Kekuatan Sihir (setiap musuh tambahan meningkatkan Kekuatan Sihir sebesar 20%), sekaligus menghapus 1 efek menguntungkan; jika tidak ada efek menguntungkan untuk dihapus atau target berada di bawah efek lambat, target <Didorong Mundur> selama 1 giliran. Shadow State mengabaikan semua pengurangan damage skill target.',
		zawakeSimpleDesc_ph = 'Phá Lãng Cư Hợp Trảm: ang base damage ay tumaas mula 60% hanggang 80% Magic Power (bawat karagdagang kalaban ay nagdaragdag ng 20% Magic Power), sabay na tinatanggal ang 1 beneficial effect; kung walang beneficial effect na matatanggal o ang target ay nasa slow effect, ang target ay <Naitulak Pabalik> sa loob ng 1 turn. Shadow State ay nilalaktawan ang lahat ng pagbawas ng skill damage ng target.',
		zawakeSimpleDesc_ma = 'Phá Lãng Cư Hợp Trảm: kerosakan asas meningkat daripada 60% kepada 80% Kuasa Sihir (setiap musuh tambahan meningkatkan Kuasa Sihir sebanyak 20%), sambil menyingkirkan 1 kesan bermanfaat; jika tiada kesan bermanfaat untuk disingkirkan atau sasaran berada di bawah kesan perlahan, sasaran <Didorong Balik> selama 1 pusingan. Shadow State mengabaikan semua pengurangan kerosakan kemahiran sasaran.',
		zawakeSimpleDesc_vn = 'Phá Lãng Cư Hợp Trảm sát thương cơ bản tăng từ 60% công pháp lên 80% công pháp (mỗi thêm 1 kẻ địch tăng 20% công pháp), đồng thời xua tan 1 hiệu ứng có lợi, nếu không có hiệu ứng có lợi để xua tan hoặc mục tiêu đang chịu hiệu ứng giảm tốc thì <Đẩy lui>mục tiêu 1 lượt; trạng thái Ảnh Sát bỏ qua toàn bộ giảm sát thương tuyệt kỹ của mục tiêu',
		iconRes = 'battle/skill_icon/skill_80033.png',
