	[80035] = {
		id = 80035,
		describe_vn = 'Khi gây sát thương, có thể tăng thêm sát thương bằng giá trị hút máu dư thừa',
		describe_en = 'When dealing damage, excess lifesteal value can additionally increase the damage dealt.',
		describe_th = 'เมื่อสร้างความเสียหาย อาจเพิ่มความเสียหายเพิ่มเติมโดยใช้ค่าดูดเลือดส่วนเกิน',
		describe_in = 'Saat memberikan damage, dapat menambah damage tambahan dengan nilai lifesteal yang berlebih.',
		describe_ph = 'Kapag nagdudulot ng pinsala, maaaring madagdagan pa ang pinsala gamit ang sobrang halaga ng lifesteal.',
		describe_ma = 'Apabila menyebabkan kerosakan, boleh menambah kerosakan tambahan menggunakan nilai serapan darah yang berlebihan.',
		describe = 'When dealing damage, excess lifesteal value can additionally increase the damage dealt.',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800351}
	},
	[80036] = {
		id = 80036,
		skillName_vn = 'Độc Vũ Huyễn Tâm',
		skillName_en = 'Poison Dance: Illusory Heart',
		skillName_th = 'ระบำพิษ: หัวใจมายา',
		skillName_in = 'Tarian Racun: Hati Ilusi',
		skillName_ph = 'Sayaw ng Lason: Pusong Ilusyon',
		skillName_ma = 'Tarian Racun: Hati Ilusi',
		skillName = 'Poison Dance: Illusory Heart',
		describe_vn = 'Khi có mặt, Shinobu giúp toàn đội tăng 10% tốc độ dựa trên tốc độ của Shinobu. Có 50% lan <Độc> sang mục tiêu ngẫu nhiên chưa nhiễm trong 1 lượt. Khi Shinobu xuống dưới 20% máu thì sẽ nhận <Ẩn thân> và tăng 20% sát thương trong 1 lượt',
		describe_en = 'When present, Shinobu helps the entire team gain 10% Speed based on her Speed. Has a 50% chance to spread <Poison> to a random target not yet affected for 1 turn. When Shinobu falls below 20% HP, she gains <Stealth> and increases damage by 20% for 1 turn',
		describe_th = 'เมื่ออยู่ในสนาม ชิโนบุจะช่วยให้ทั้งทีมเพิ่มความเร็ว 10% ตามความเร็วของเธอ มีโอกาส 50% ที่จะแพร่ <พิษ> ไปยังเป้าหมายแบบสุ่มที่ยังไม่ได้รับผล เป็นเวลา 1 เทิร์น เมื่อพลังชีวิตของชิโนบุลดลงต่ำกว่า 20% เธอจะได้รับ <ล่องหน> และเพิ่มความเสียหาย 20% เป็นเวลา 1 เทิร์น',
		describe_in = 'Saat hadir, Shinobu membantu seluruh tim mendapatkan 10% Kecepatan berdasarkan Kecepatan miliknya. Memiliki 50% peluang menyebarkan <Racun> ke target acak yang belum terinfeksi selama 1 giliran. Saat HP Shinobu turun di bawah 20%, dia mendapatkan <Menyamar> dan meningkatkan damage sebesar 20% selama 1 giliran',
		describe_ph = 'Kapag naroroon, tinutulungan ni Shinobu ang buong koponan na makakuha ng 10% Bilis batay sa kanyang Bilis. Mayroong 50% na tsansa na maikalat ang <Lason> sa isang random na target na hindi pa apektado sa loob ng 1 turn. Kapag bumaba ang HP ni Shinobu sa ibaba ng 20%, makakakuha siya ng <Pagkakubli> at tataas ng 20% ang kanyang pinsala sa loob ng 1 turn',
		describe_ma = 'Apabila hadir, Shinobu membantu seluruh pasukan memperoleh 10% Kelajuan berdasarkan Kelajuannya. Mempunyai 50% peluang untuk menyebarkan <Racun> kepada sasaran rawak yang belum dijangkiti selama 1 giliran. Apabila HP Shinobu jatuh di bawah 20%, dia akan mendapat <Menyamar> dan meningkatkan kerosakan sebanyak 20% selama 1 giliran',
		describe = 'When present, Shinobu helps the entire team gain 10% Speed based on her Speed. Has a 50% chance to spread <Poison> to a random target not yet affected for 1 turn. When Shinobu falls below 20% HP, she gains <Stealth> and increases damage by 20% for 1 turn',
		simDesc = 'Các đòn đánh có tỷ lệ gây Độc; sát thương tăng khi tấn công kẻ địch đã bị Độc.',
		starEffect = __data_t__starEffect[80036],
		-- {8}
		starEffectDesc_vn = '<Hoa Độc Tỉnh Thức>: Nếu HP của Shinobu lần đầu tiên xuống dưới 40%, tự động kích hoạt trạng thái <Ẩn Thân> và tăng 50% sát thương trong 1 lượt (chỉ kích hoạt 1 lần mỗi trận), đồng thời khi đến lượt giải toàn bộ không chế trên người và cộng thêm 500 nộ . <Khi thế Hoa Độc>: Khi bắt đầu trận, toàn đội nhận 15% kháng khống chế trong 1 lượt.\n#F10#\n#F40##L10#Hiệu ứng sát thương bùng nổ:#L0# Khi Shinobu lần đầu rơi vào tình thế nguy hiểm, cô lập tức lẩn tránh và phản đòn mạnh mẽ. Đồng minh cũng được bảo vệ tốt hơn ngay từ đầu trận với khả năng tăng kháng hiệu ứng.',
		starEffectDesc = '<Awakened Poison Flower>: When Shinobu’s HP drops below 40% for the first time, she automatically activates <Stealth> and gains 50% damage boost for 1 turn (triggers only once per battle). At the same time, at the start of her turn she dispels all control effects on herself and gains 500 Rage. <Poison Flower Aura>: At the beginning of the battle, the whole team gains 15% control resistance for 1 turn.\n#F10#\n#F40##L10#Burst Damage Effect:#L0# When Shinobu first falls into a dangerous situation, she immediately hides and counterattacks fiercely. Allies are also better protected from the start with increased resistance to effects',
		starEffectDesc_en = '<Awakened Poison Flower>: When Shinobu’s HP drops below 40% for the first time, she automatically activates <Stealth> and gains 50% damage boost for 1 turn (triggers only once per battle). At the same time, at the start of her turn she dispels all control effects on herself and gains 500 Rage. <Poison Flower Aura>: At the beginning of the battle, the whole team gains 15% control resistance for 1 turn.\n#F10#\n#F40##L10#Burst Damage Effect:#L0# When Shinobu first falls into a dangerous situation, she immediately hides and counterattacks fiercely. Allies are also better protected from the start with increased resistance to effects',
		starEffectDesc_th = '<ดอกพิษตื่นรู้>: เมื่อ HP ของ Shinobu ลดลงต่ำกว่า 40% เป็นครั้งแรก จะทำการเปิดใช้งาน <ล่องหน> โดยอัตโนมัติและเพิ่มความเสียหายขึ้น 50% เป็นเวลา 1 เทิร์น (เปิดใช้งานได้เพียง 1 ครั้งต่อการต่อสู้) พร้อมกันนี้ เมื่อถึงตาของเธอ จะลบผลควบคุมทั้งหมดบนตัวเองและได้รับโทสะ 500 แต้ม <พลังดอกพิษ>: เมื่อเริ่มการต่อสู้ ทีมทั้งหมดจะได้รับต้านทานการควบคุม 15% เป็นเวลา 1 เทิร์น \n#F10#\n#F40##L10#เอฟเฟกต์ความเสียหายระเบิด:#L0# เมื่อ Shinobu ตกอยู่ในสถานการณ์อันตรายครั้งแรก เธอจะล่องหนทันทีและโต้กลับอย่างรุนแรง พันธมิตรก็ได้รับการปกป้องที่ดียิ่งขึ้นตั้งแต่เริ่มต้นด้วยการต้านทานเอฟเฟกต์ที่เพิ่มขึ้น',
		starEffectDesc_in = '<Bunga Racun Terbangun>: Saat HP Shinobu pertama kali turun di bawah 40%, ia otomatis mengaktifkan <Menyamar> dan mendapatkan peningkatan damage 50% selama 1 giliran (hanya aktif sekali per pertempuran). Pada saat yang sama, ketika gilirannya tiba, semua efek kontrol pada dirinya akan dihapus dan ia memperoleh 500 Amarah. <Aura Bunga Racun>: Saat awal pertempuran, seluruh tim memperoleh 15% resistansi kontrol selama 1 giliran.\n#F10#\n#F40##L10#Efek Ledakan Damage:#L0# Ketika Shinobu pertama kali berada dalam situasi berbahaya, ia segera bersembunyi dan melakukan serangan balik yang kuat. Sekutu juga mendapatkan perlindungan lebih baik sejak awal dengan peningkatan resistansi terhadap efek.',
		starEffectDesc_ph = '<Gumising na Bulaklak ng Lason>: Kapag unang bumaba ang HP ni Shinobu sa ibaba ng 40%, awtomatiko niyang a-activate ang <Pagtatago> at makakakuha ng 50% dagdag na damage sa loob ng 1 turn (maaari lang mangyari isang beses bawat laban). Kasabay nito, kapag dumating ang kanyang turn, mawawala ang lahat ng control effects sa kanya at makakakuha siya ng 500 Rage. <Aura ng Bulaklak ng Lason>: Sa simula ng laban, lahat ng kakampi ay makakakuha ng 15% control resistance sa loob ng 1 turn.\n#F10#\n#F40##L10#Epekto ng Sumabog na Pinsala:#L0# Kapag unang napunta si Shinobu sa mapanganib na sitwasyon, agad siyang magtatago at babawi ng malakas. Mas protektado rin ang mga kakampi mula sa simula ng laban gamit ang dagdag na resistansya laban sa mga epekto.',
		starEffectDesc_ma = '<Bunga Racun Sedar>: Apabila HP Shinobu jatuh di bawah 40% buat kali pertama, dia akan secara automatik mengaktifkan <Halimunan> dan memperoleh peningkatan 50% kerosakan selama 1 giliran (hanya berlaku sekali setiap pertarungan). Pada masa yang sama, apabila gilirannya tiba, semua kesan kawalan ke atas dirinya akan dibersihkan dan dia memperoleh 500 Kemarahan. <Aura Bunga Racun>: Pada permulaan pertarungan, seluruh pasukan memperoleh 15% rintangan kawalan selama 1 giliran.\n#F10#\n#F40##L10#Kesan Letupan Kerosakan:#L0# Apabila Shinobu pertama kali berada dalam keadaan berbahaya, dia segera menghilang dan melakukan serangan balas yang kuat. Sekutu juga lebih dilindungi sejak permulaan dengan peningkatan rintangan terhadap kesan.',
		zawakeEffect = __data_t__zawakeEffect[80036],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#It’s you, Satoshi!#C0x5B545B#\n#F10#\n#F40##L10#Ultimate Ninja Skill:#L0#When attacking a target with lower speed than self, ignores #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# of the target’s magic resistance and deals additional true damage equal to 100% of magic power; the greater the speed difference between self and target, the higher the additional damage, each 1% speed difference increases damage by 3%, up to a maximum of 100%;\nAfter attacking, there is a probability equal to the speed difference ratio between both sides to apply <Water Shuriken> mark to the target\nWater Shuriken: When the target takes 10% additional Water damage, allies attacking this target will perform a normal attack assist and consume the Water Shuriken mark on the target\n#F10#\n#F40##L10#Flowing Steps into Blade:#L0#After a Water ally acts, gain 1 stack of <Flowing Steps>; when self purifies debuffs and control or purifies enemy buffs, gain 1 stack of <Flowing Steps>; when control effects end naturally, gain 4 stacks of <Flowing Steps>; reaching 6 stacks will consume all to trigger <Water Dragon Vortex> covering self and purifying all debuffs (Water Dragon Vortex: shield that absorbs damage equal to 600% magic power, increases 100% crit resistance, increases 30% Water skill damage, increases 60% resistance to debuffs and grants control immunity, lasts until shield breaks or round ends); when Water Dragon Vortex disappears, water gathers behind into a Giant Water Shuriken and grants an extra turn, when possessing Giant Water Shuriken, ultimate skill can be used without consuming rage (cooldown 2 rounds)\nFlowing Steps: special effect, increases 5% speed and 10% crit resistance\n#F10#\n#F40##L10#Bonded Strength:#L0#When entering battle, each Water or Evil ally grants corresponding stacks of <Bonded Strength> (special effect, increases 2% magic power and 2% lifesteal, up to 20 stacks); when self assists in attack, gain 1 stack of <Bonded Strength>; when being called to assist or protected, gain 2 stacks of <Bonded Strength>; when possessing <Bonded Strength>, if receiving lethal damage while allies remain on the field, can delay death for 1 turn; when <Bonded Strength> reaches 20 stacks, immediately enter Shadow Kill state, temporarily increasing 100% crit rate and crit damage, and instantly perform one <Golden Water Shuriken>',
		zawakeEffectDesc_en = '#C0xC0C0C0#It’s you, Satoshi!#C0x5B545B#\n#F10#\n#F40##L10#Ultimate Ninja Skill:#L0#When attacking a target with lower speed than self, ignores #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# of the target’s magic resistance and deals additional true damage equal to 100% of magic power; the greater the speed difference between self and target, the higher the additional damage, each 1% speed difference increases damage by 3%, up to a maximum of 100%;\nAfter attacking, there is a probability equal to the speed difference ratio between both sides to apply <Water Shuriken> mark to the target\nWater Shuriken: When the target takes 10% additional Water damage, allies attacking this target will perform a normal attack assist and consume the Water Shuriken mark on the target\n#F10#\n#F40##L10#Flowing Steps into Blade:#L0#After a Water ally acts, gain 1 stack of <Flowing Steps>; when self purifies debuffs and control or purifies enemy buffs, gain 1 stack of <Flowing Steps>; when control effects end naturally, gain 4 stacks of <Flowing Steps>; reaching 6 stacks will consume all to trigger <Water Dragon Vortex> covering self and purifying all debuffs (Water Dragon Vortex: shield that absorbs damage equal to 600% magic power, increases 100% crit resistance, increases 30% Water skill damage, increases 60% resistance to debuffs and grants control immunity, lasts until shield breaks or round ends); when Water Dragon Vortex disappears, water gathers behind into a Giant Water Shuriken and grants an extra turn, when possessing Giant Water Shuriken, ultimate skill can be used without consuming rage (cooldown 2 rounds)\nFlowing Steps: special effect, increases 5% speed and 10% crit resistance\n#F10#\n#F40##L10#Bonded Strength:#L0#When entering battle, each Water or Evil ally grants corresponding stacks of <Bonded Strength> (special effect, increases 2% magic power and 2% lifesteal, up to 20 stacks); when self assists in attack, gain 1 stack of <Bonded Strength>; when being called to assist or protected, gain 2 stacks of <Bonded Strength>; when possessing <Bonded Strength>, if receiving lethal damage while allies remain on the field, can delay death for 1 turn; when <Bonded Strength> reaches 20 stacks, immediately enter Shadow Kill state, temporarily increasing 100% crit rate and crit damage, and instantly perform one <Golden Water Shuriken>',
		zawakeEffectDesc_th = '#C0xC0C0C0#ใช่แล้ว เจ้าแหละ Satoshi!#C0x5B545B#\n#F10#\n#F40##L10#ท่าไม้ตาย นินจาสุดยอด:#L0#เมื่อโจมตีเป้าหมายที่มีความเร็วต่ำกว่าตัวเอง จะทะลุ #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# ต้านทานเวทของเป้าหมาย และสร้างความเสียหายจริงเพิ่มเติมเท่ากับ 100% พลังเวท; ความต่างความเร็วระหว่างตนเองกับเป้าหมายยิ่งมาก ความเสียหายเพิ่มเติมยิ่งสูงขึ้น แต่ละ 1% ความต่างความเร็วเพิ่มดาเมจ 3% สูงสุดไม่เกิน 100%;\nหลังโจมตี จะมีโอกาสเท่ากับสัดส่วนความต่างความเร็วระหว่างทั้งสองฝ่ายที่จะติด <ชูริเคนน้ำ> บนเป้าหมาย\nชูริเคนน้ำ: เมื่อเป้าหมายได้รับดาเมจธาตุน้ำเพิ่ม 10% พันธมิตรที่โจมตีเป้าหมายนี้จะทำการโจมตีปกติช่วยเสริม และ消耗เครื่องหมายชูริเคนน้ำบนเป้าหมาย\n#F10#\n#F40##L10#ก้าวไหลกลายดาบ:#L0#หลังพันธมิตรธาตุน้ำทำการโจมตี ได้รับ 1 ชั้นของ <ก้าวไหล>; เมื่อชำระล้างสถานะไม่ดีและควบคุม หรือลบล้างบัฟศัตรู ได้รับ 1 ชั้น <ก้าวไหล>; เมื่อเอฟเฟกต์ควบคุมสิ้นสุดเอง จะได้รับ 4 ชั้น <ก้าวไหล>; ครบ 6 ชั้นจะ消耗ทั้งหมดเพื่อเรียกใช้ <มังกรน้ำวน> ครอบคลุมตนเองและล้างทุกสถานะไม่ดี (มังกรน้ำวน: โล่ดูดซับความเสียหายเท่ากับ 600% พลังเวท เพิ่ม 100% ต้านทานคริต เพิ่ม 30% ดาเมจสกิลธาตุน้ำ เพิ่ม 60% ต้านทานดีบัฟและกันควบคุม อยู่จนกว่าโล่แตกหรือสิ้นสุดรอบ); เมื่อมังกรน้ำวนหายไป น้ำจะรวมตัวด้านหลังกลายเป็นชูริเคนน้ำยักษ์และได้รับรอบพิเศษ เมื่อมีชูริเคนน้ำยักษ์ สกิลไม้ตายสามารถใช้โดยไม่เสียโทสะ (คูลดาวน์ 2 รอบใหญ่)\nก้าวไหล: เอฟเฟกต์พิเศษ เพิ่มความเร็ว 5% และต้านทานคริต 10%\n#F10#\n#F40##L10#พลังผูกพัน:#L0#เมื่อเข้าสู่การต่อสู้ พันธมิตรธาตุน้ำหรือธาตุชั่วร้ายแต่ละคนจะให้ <พลังผูกพัน> ตามจำนวน (เอฟเฟกต์พิเศษ เพิ่มพลังเวท 2% และดูดเลือด 2% สูงสุด 20 ชั้น); เมื่อช่วยโจมตี ได้รับ 1 ชั้น <พลังผูกพัน>; เมื่อถูกเรียกช่วยหรือได้รับการปกป้อง ได้รับ 2 ชั้น <พลังผูกพัน>; เมื่อมี <พลังผูกพัน> หากได้รับดาเมจร้ายแรงแต่ยังมีพันธมิตรอยู่ จะสามารถชะลอความตายได้ 1 รอบ; เมื่อ <พลังผูกพัน> ครบ 20 ชั้น จะเข้าสู่สภาพ Shadow Kill ทันที เพิ่มอัตราคริตและดาเมจคริต 100% ชั่วคราว และปล่อย <ชูริเคนน้ำทอง> หนึ่งครั้งทันที',
		zawakeEffectDesc_in = '#C0xC0C0C0#Kamulah, Satoshi!#C0x5B545B#\n#F10#\n#F40##L10#Jurang Ninja Pamungkas:#L0#Saat menyerang target dengan kecepatan lebih rendah, akan mengabaikan #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# resistensi sihir target dan memberikan damage nyata tambahan sebesar 100% kekuatan sihir; semakin besar selisih kecepatan antara diri sendiri dan target, semakin tinggi tambahan damage, setiap 1% perbedaan kecepatan menambah 3% damage, maksimal 100%;\nSetelah menyerang, ada peluang sebesar rasio perbedaan kecepatan antara kedua pihak untuk memberi tanda <Shuriken Air> pada target\nShuriken Air: Saat target menerima 10% tambahan damage elemen Air, sekutu yang menyerang target ini akan melakukan serangan normal tambahan dan mengonsumsi tanda Shuriken Air pada target\n#F10#\n#F40##L10#Langkah Mengalir Jadi Pedang:#L0#Setelah sekutu elemen Air bertindak, memperoleh 1 lapisan <Langkah Mengalir>; saat diri sendiri membersihkan debuff dan kontrol atau menghapus buff musuh, memperoleh 1 lapisan <Langkah Mengalir>; saat efek kontrol berakhir alami, memperoleh 4 lapisan <Langkah Mengalir>; mencapai 6 lapisan akan mengonsumsi semua untuk memicu <Pusaran Naga Air> melindungi diri sendiri dan membersihkan semua debuff (Pusaran Naga Air: perisai menyerap damage sebesar 600% kekuatan sihir, meningkatkan 100% resistensi krit, meningkatkan 30% damage skill elemen Air, meningkatkan 60% resistensi debuff dan kebal kontrol, bertahan hingga perisai hancur atau ronde berakhir); ketika Pusaran Naga Air hilang, air berkumpul di belakang berubah menjadi Shuriken Air Raksasa dan mendapat giliran tambahan, ketika memiliki Shuriken Air Raksasa, ultimate dapat digunakan tanpa konsumsi amarah (cooldown 2 ronde)\nLangkah Mengalir: efek khusus, meningkatkan 5% kecepatan dan 10% resistensi krit\n#F10#\n#F40##L10#Kekuatan Ikatan:#L0#Saat memasuki pertempuran, setiap sekutu elemen Air atau Jahat memberikan lapisan <Kekuatan Ikatan> sesuai jumlahnya (efek khusus, meningkatkan 2% kekuatan sihir dan 2% lifesteal, maksimal 20 lapisan); saat membantu serangan, memperoleh 1 lapisan <Kekuatan Ikatan>; saat dipanggil membantu atau dilindungi, memperoleh 2 lapisan <Kekuatan Ikatan>; saat memiliki <Kekuatan Ikatan>, jika menerima damage mematikan sementara sekutu masih ada, dapat menunda kematian 1 ronde; saat <Kekuatan Ikatan> mencapai 20 lapisan, langsung masuk ke status Shadow Kill, sementara meningkatkan 100% crit rate dan crit damage, serta segera melancarkan satu <Shuriken Air Emas>',
		zawakeEffectDesc_ph = '#C0xC0C0C0#Ikaw nga, Satoshi!#C0x5B545B#\n#F10#\n#F40##L10#Pinakamataas na Teknik ng Ninja:#L0#Kapag umatake sa target na mas mabagal kaysa sa sarili, babalewalain ang #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# magic resistance ng target at magdudulot ng karagdagang totoong pinsala na katumbas ng 100% magic power; mas malaki ang agwat ng bilis sa pagitan ng sarili at target, mas mataas ang dagdag na pinsala, bawat 1% na agwat ng bilis ay nagdaragdag ng 3% pinsala, hanggang maximum 100%;\nPagkatapos umatake, may posibilidad na katumbas ng ratio ng bilis na agwat ng magkabilang panig na maglagay ng marka ng <Water Shuriken> sa target\nWater Shuriken: Kapag ang target ay tumatanggap ng 10% dagdag na pinsala ng elemento Tubig, ang mga kakampi na umaatake sa target na ito ay magsasagawa ng karaniwang atake bilang suporta at mauubos ang marka ng Water Shuriken sa target\n#F10#\n#F40##L10#Umaagos na Hakbang sa Espada:#L0#Pagkatapos kumilos ang isang kakamping Tubig, makakakuha ng 1 stack ng <Umaagos na Hakbang>; kapag ang sarili ay nagtanggal ng debuff at kontrol o nagtanggal ng buff ng kalaban, makakakuha ng 1 stack ng <Umaagos na Hakbang>; kapag ang kontrol na epekto ay natural na natapos, makakakuha ng 4 na stack ng <Umaagos na Hakbang>; kapag umabot ng 6 na stack, mauubos lahat upang i-activate ang <Alon ng Dragon na Tubig> na bumabalot sa sarili at nagtatanggal ng lahat ng debuff (Alon ng Dragon na Tubig: kalasag na sumisipsip ng pinsala na katumbas ng 600% magic power, nagpapataas ng 100% crit resistance, nagpapataas ng 30% Water skill damage, nagpapataas ng 60% debuff resistance at nagbibigay ng control immunity, tumatagal hanggang sa masira ang kalasag o matapos ang round); kapag nawala ang Alon ng Dragon na Tubig, ang tubig ay titipon sa likod at magiging Higanteng Water Shuriken at makakakuha ng dagdag na turn, kapag may Higanteng Water Shuriken, maaaring gamitin ang ultimate skill nang hindi gumagamit ng rage (cooldown 2 malalaking round)\nUmaagos na Hakbang: espesyal na epekto, nagpapataas ng 5% bilis at 10% crit resistance\n#F10#\n#F40##L10#Lakas ng Pagkakabigkis:#L0#Kapag pumasok sa laban, bawat kakamping Tubig o Masama ay magbibigay ng mga stack ng <Lakas ng Pagkakabigkis> ayon sa bilang (espesyal na epekto, nagpapataas ng 2% magic power at 2% lifesteal, maximum 20 stack); kapag tumutulong sa pag-atake, makakakuha ng 1 stack ng <Lakas ng Pagkakabigkis>; kapag tinawag para tumulong o pinrotektahan, makakakuha ng 2 stack ng <Lakas ng Pagkakabigkis>; kapag may <Lakas ng Pagkakabigkis>, kung tatanggap ng nakamamatay na pinsala ngunit may natitirang kakampi, maaaring maantala ang kamatayan ng 1 turn; kapag umabot sa 20 stack ang <Lakas ng Pagkakabigkis>, agad na papasok sa estado ng Shadow Kill, pansamantalang nagpapataas ng 100% crit rate at crit damage, at agad na magsasagawa ng isang <Golden Water Shuriken>',
		zawakeEffectDesc_ma = '#C0xC0C0C0#Kamulah, Satoshi!#C0x5B545B#\n#F10#\n#F40##L10#Kemahiran Ninja Muktamad:#L0#Apabila menyerang sasaran yang lebih perlahan daripada diri sendiri, akan mengabaikan #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# ketahanan sihir sasaran dan memberikan kerosakan sebenar tambahan bersamaan dengan 100% kuasa sihir; semakin besar perbezaan kelajuan antara diri sendiri dan sasaran, semakin tinggi kerosakan tambahan, setiap 1% perbezaan kelajuan menambah 3% kerosakan, maksimum 100%;\nSelepas menyerang, terdapat kebarangkalian bersamaan nisbah perbezaan kelajuan antara kedua pihak untuk meletakkan tanda <Shuriken Air> pada sasaran\nShuriken Air: Apabila sasaran menerima 10% kerosakan tambahan elemen Air, sekutu yang menyerang sasaran ini akan melakukan serangan biasa tambahan dan menggunakan tanda Shuriken Air pada sasaran\n#F10#\n#F40##L10#Langkah Mengalir Jadi Pedang:#L0#Selepas sekutu elemen Air bertindak, mendapat 1 lapisan <Langkah Mengalir>; apabila diri sendiri membersihkan debuff dan kawalan atau membersihkan buff musuh, mendapat 1 lapisan <Langkah Mengalir>; apabila kesan kawalan berakhir secara semula jadi, mendapat 4 lapisan <Langkah Mengalir>; mencapai 6 lapisan akan menggunakan semua untuk mengaktifkan <Pusaran Naga Air> melindungi diri dan membersihkan semua debuff (Pusaran Naga Air: perisai menyerap kerosakan bersamaan dengan 600% kuasa sihir, meningkatkan 100% rintangan krit, meningkatkan 30% kerosakan kemahiran elemen Air, meningkatkan 60% rintangan debuff dan kebal kawalan, bertahan sehingga perisai pecah atau tamat giliran); apabila Pusaran Naga Air hilang, air berkumpul di belakang menjadi Shuriken Air Gergasi dan mendapat giliran tambahan, apabila memiliki Shuriken Air Gergasi, kemahiran muktamad boleh digunakan tanpa menggunakan kemarahan (cooldown 2 giliran besar)\nLangkah Mengalir: kesan khas, meningkatkan 5% kelajuan dan 10% rintangan krit\n#F10#\n#F40##L10#Kekuatan Ikatan:#L0#Apabila memasuki pertempuran, setiap sekutu elemen Air atau Jahat akan memberikan lapisan <Kekuatan Ikatan> mengikut bilangan (kesan khas, meningkatkan 2% kuasa sihir dan 2% serapan nyawa, maksimum 20 lapisan); apabila membantu serangan, mendapat 1 lapisan <Kekuatan Ikatan>; apabila dipanggil membantu atau dilindungi, mendapat 2 lapisan <Kekuatan Ikatan>; apabila memiliki <Kekuatan Ikatan>, jika menerima kerosakan maut sementara sekutu masih ada, boleh menangguhkan kematian selama 1 giliran; apabila <Kekuatan Ikatan> mencapai 20 lapisan, segera memasuki keadaan Shadow Kill, sementara meningkatkan 100% kadar krit dan kerosakan krit, serta segera melancarkan satu <Shuriken Air Emas>',
		zawakeEffectDesc_vn = '#C0xC0C0C0#Chính là cậu rồi, Satoshi!#C0x5B545B#\n#F10#\n#F40##L10#Tuyệt kỹ Siêu Nhẫn：#L0#Khi tấn công mục tiêu có tốc độ thấp hơn bản thân, sẽ bỏ qua #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#kháng phép của mục tiêu và gây thêm sát thương thực tế bằng 100% công pháp; chênh lệch tốc độ giữa bản thân và mục tiêu càng lớn thì sát thương thêm càng cao, mỗi 1% chênh lệch tốc độ tăng 3% sát thương, tối đa tăng thêm 100%;\nSau khi tấn công có xác suất bằng tỷ lệ chênh lệch tốc độ giữa hai bên để thêm dấu ấn <Phi Tiêu Nước>lên mục tiêu\nPhi Tiêu Nước：Khi mục tiêu chịu thêm 10% sát thương hệ Nước, đồng minh tấn công mục tiêu này sẽ thực hiện một đòn đánh thường hỗ trợ và tiêu hao dấu ấn Phi Tiêu Nước trên mục tiêu\n#F10#\n#F40##L10#Lăng Ba Hóa Kiếm：#L0#Sau khi đồng minh hệ Nước hành động, nhận 1 tầng <Lăng Ba>, khi bản thân được thanh tẩy trạng thái xấu và khống chế hoặc thanh tẩy hiệu ứng có lợi của địch, nhận 1 tầng <Lăng Ba>, khi hiệu ứng khống chế kết thúc tự nhiên sẽ nhận 4 tầng <Lăng Ba>, đạt 6 tầng sẽ tiêu hao toàn bộ để kích hoạt <Thủy Long Quyển>bao phủ bản thân và thanh tẩy toàn bộ trạng thái xấu (Thủy Long Quyển: lá chắn hấp thụ sát thương bằng 600% công pháp, tăng 100% kháng bạo, tăng 30% sát thương kỹ năng hệ Nước, tăng 60% kháng hiệu ứng xấu và miễn khống chế, duy trì đến khi lá chắn vỡ hoặc hết lượt lớn); khi Thủy Long Quyển biến mất, dòng nước tụ lại sau lưng hóa thành Phi Tiêu Nước Khổng Lồ và nhận thêm một lượt mới, khi sở hữu Phi Tiêu Nước Khổng Lồ, tuyệt kỹ có thể dùng mà không tốn nộ khí (thời gian hồi chiêu 2 lượt lớn)\nLăng Ba：hiệu ứng đặc biệt, tăng 5% tốc độ và 10% kháng bạo\n#F10#\n#F40##L10#Sức Mạnh Gắn Kết：#L0#Khi ra trận, mỗi đồng minh hệ Nước hoặc hệ Ác sẽ nhận số tầng <Sức Mạnh Gắn Kết>tương ứng (hiệu ứng đặc biệt, tăng 2% công pháp và 2% hút máu, tối đa 20 tầng), khi bản thân hỗ trợ tấn công sẽ nhận 1 tầng <Sức Mạnh Gắn Kết>, khi bị gọi hỗ trợ hoặc được bảo vệ sẽ nhận 2 tầng <Sức Mạnh Gắn Kết>, khi sở hữu <Sức Mạnh Gắn Kết>, nếu nhận sát thương chí tử mà vẫn còn đồng minh trên sân thì có thể trì hoãn cái chết 1 lượt; khi <Sức Mạnh Gắn Kết>đạt 20 tầng sẽ lập tức vào trạng thái Ảnh Sát, tạm thời tăng 100% tỷ lệ bạo kích và sát thương, đồng thời ngay lập tức thi triển một lần <Phi Tiêu Nước Vàng>',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Water Dragon Scroll cleanses all negative effects on the user, increases 60% resistance to negative effects, grants immunity to control, and provides a shield absorbing 600% Magic Power; when Bonded Power reaches 20 stacks, instantly enters Shadow State, temporarily increasing Critical Rate and Damage by 100%, and immediately unleashes one <Golden Water Shuriken>.',
		zawakeSimpleDesc_en = 'Water Dragon Scroll cleanses all negative effects on the user, increases 60% resistance to negative effects, grants immunity to control, and provides a shield absorbing 600% Magic Power; when Bonded Power reaches 20 stacks, instantly enters Shadow State, temporarily increasing Critical Rate and Damage by 100%, and immediately unleashes one <Golden Water Shuriken>.',
		zawakeSimpleDesc_th = 'Thủy Long Quyển จะล้างสถานะลบทั้งหมดบนตัวเอง พร้อมเพิ่มความต้านทานต่อสถานะลบ 60% และได้รับภูมิคุ้มกันการควบคุม พร้อมโล่ดูดซับเท่ากับ 600% พลังเวท; เมื่อ Sức Mạnh Gắn Kết มี 20 ชั้น จะเข้าสู่สถานะเงาโจมตีทันที เพิ่มอัตราคริติคอลและความเสียหายชั่วคราว 100% และทันทีปล่อย <Phi Tiêu Nước Vàng> 1 ครั้ง',
		zawakeSimpleDesc_in = 'Water Dragon Scroll membersihkan semua efek negatif pada diri sendiri, meningkatkan 60% resistensi terhadap efek negatif, memberikan kebal terhadap kontrol, dan memberikan perisai yang menyerap 600% Kekuatan Sihir; ketika Bonded Power mencapai 20 tumpukan, langsung memasuki Shadow State, sementara meningkatkan Critical Rate dan Damage sebesar 100%, dan segera melepaskan satu <Golden Water Shuriken>.',
		zawakeSimpleDesc_ph = 'Water Dragon Scroll ay naglilinis ng lahat ng negative effects sa sarili, nagdaragdag ng 60% resistance sa negative effects, nagbibigay ng immunity sa control, at nagbibigay ng shield na sumisipsip ng 600% Magic Power; kapag ang Bonded Power ay umabot ng 20 stacks, agad pumapasok sa Shadow State, pansamantalang nagpapataas ng Critical Rate at Damage ng 100%, at agad na naglalabas ng isang <Golden Water Shuriken>.',
		zawakeSimpleDesc_ma = 'Water Dragon Scroll akan menyingkirkan semua kesan negatif pada diri sendiri, meningkatkan 60% rintangan terhadap kesan negatif, memberi imuniti kepada kawalan, dan menyediakan perisai yang menyerap 600% Kuasa Sihir; apabila Bonded Power mencapai 20 timbunan, terus memasuki Shadow State, sementara meningkatkan Critical Rate dan Damage sebanyak 100%, dan segera melancarkan satu <Golden Water Shuriken>.',
		zawakeSimpleDesc_vn = 'Thủy Long Quyển sẽ thanh tẩy toàn bộ trạng thái xấu trên bản thân, đồng thời tăng 60% kháng hiệu ứng xấu và miễn khống chế, lượng hấp thụ tăng lên 600% công pháp; khi Sức Mạnh Gắn Kết đạt 20 tầng, lập tức vào trạng thái Ảnh Sát, tạm thời tăng 100% tỷ lệ bạo kích và sát thương, đồng thời ngay lập tức thi triển một lần <Phi Tiêu Nước Vàng>',
		iconRes = 'battle/skill_icon/skill_80036.png',
