	[80040] = {
		id = 80040,
		describe_vn = 'Khi bắt đầu trận chiến tiếp theo, có 15% cơ hội giảm một nửa máu hiện tại của kẻ địch, chỉ kích hoạt trong lần thử thách đầu tiên của trận chiến này, các lần thử thách sau sẽ không kích hoạt',
		describe_en = 'At the start of the next battle, there is a 15% chance to reduce the enemy\'s current HP by half, only activating on the first challenge of this battle; subsequent challenges will not trigger.',
		describe_th = 'เมื่อเริ่มการต่อสู้ครั้งถัดไป มีโอกาส 15% ที่จะลดพลังชีวิตปัจจุบันของศัตรูลงครึ่งหนึ่ง โดยจะทำงานเฉพาะในครั้งท้าทายแรกของการต่อสู้นี้ ครั้งท้าทายถัดไปจะไม่ทำงาน',
		describe_in = 'Saat memulai pertarungan berikutnya, ada peluang 15% untuk mengurangi setengah dari HP musuh saat ini, hanya aktif pada tantangan pertama dalam pertarungan ini; tantangan berikutnya tidak akan aktif.',
		describe_ph = 'Sa pagsisimula ng susunod na laban, may 15% na pagkakataon na mapababa ng kalahati ang kasalukuyang HP ng kalaban, aktibo lamang sa unang hamon ng laban na ito; ang mga sumusunod na hamon ay hindi magti-trigger.',
		describe_ma = 'Pada permulaan pertempuran seterusnya, terdapat peluang 15% untuk mengurangkan separuh darah semasa musuh, hanya diaktifkan pada cabaran pertama pertempuran ini; cabaran seterusnya tidak akan diaktifkan.',
		describe = 'At the start of the next battle, there is a 15% chance to reduce the enemy\'s current HP by half, only activating on the first challenge of this battle; subsequent challenges will not trigger.',
