		skillName_ma = 'Pedang Rhododendron',
		skillName = 'Rhododendron Sword',
		describe_vn = 'Tsuyuri Kanao chém thẳng gây #C0xE69900#175% Công Vật Lý#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# và gây hiệu ứng <Vết Thương Sâu> trong 2 lượt. <Vết Thương Sâu>: giảm hiệu quả hồi phục 20%, nếu mục tiệu thuộc hệ Độc thì giảm hiệu quả hồi phục 40%.',
		describe_en = 'Tsuyuri Kanao slashes straight, dealing #C0xE69900#175% Physical ATK#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#Physical DMG#C0x5B545B# and inflicting <Deep Wound> for 2 turns. <Deep Wound>: reduces healing effectiveness by 20%, if the target belongs to the Poison element, healing effectiveness is reduced by 40%',
		describe_th = 'สึยุริ คานาโอะฟันตรง สร้างความเสียหาย #C0xE69900#175% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# และทำให้เกิดสถานะ <บาดแผลลึก> เป็นเวลา 2 เทิร์น <บาดแผลลึก>: ลดประสิทธิภาพการฟื้นฟู 20% หากเป้าหมายเป็นธาตุพิษ ประสิทธิภาพการฟื้นฟูลดลง 40%',
		describe_in = 'Tsuyuri Kanao menebas lurus, memberikan #C0xE69900#175% ATK Fisik#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#DMG Fisik#C0x5B545B# dan memberikan efek <Luka Dalam> selama 2 giliran. <Luka Dalam>: mengurangi efektivitas penyembuhan sebesar 20%, jika target adalah elemen Racun maka efektivitas penyembuhan berkurang 40%',
		describe_ph = 'Tsuyuri Kanao ay tumaga nang diretso, nagdudulot ng #C0xE69900#175% Pisikal na ATK#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#Pisikal na DMG#C0x5B545B# at naglalagay ng <Malalim na Sugat> sa loob ng 2 turn. <Malalim na Sugat>: binabawasan ang bisa ng pagpapagaling ng 20%, kung ang target ay Poison element, ang bisa ng pagpapagaling ay mababawasan ng 40%',
		describe_ma = 'Tsuyuri Kanao menebas lurus, memberikan #C0xE69900#175% ATK Fizikal#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#DMG Fizikal#C0x5B545B# dan mengenakan efek <Luka Dalam> selama 2 giliran. <Luka Dalam>: mengurangkan keberkesanan pemulihan sebanyak 20%, jika sasaran adalah elemen Racun maka keberkesanan pemulihan berkurang sebanyak 40%',
		describe = 'Tsuyuri Kanao slashes straight, dealing #C0xE69900#175% Physical ATK#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#Physical DMG#C0x5B545B# and inflicting <Deep Wound> for 2 turns. <Deep Wound>: reduces healing effectiveness by 20%, if the target belongs to the Poison element, healing effectiveness is reduced by 40%',
		simDesc = 'Chém kiếm nhanh về phía trước gây sát thương vật lý lớn, tăng mạnh tỷ lệ né tránh trong lượt tiếp theo.',
		zawakeEffect = __data_t__zawakeEffect[80041],
		-- {79001}
		zawakeEffectDesc = 'Tsuyuri Kanao slashes directly, dealing #C0xE69900#175% Physical ATK#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#Physical DMG#C0x5B545B# and inflicting <Deep Wound> for 2 turns. <Deep Wound>: reduces healing effectiveness by 20%, if the target belongs to the Poison element, reduces healing effectiveness by 40%. The struck target becomes inflicted with <Poison>, taking damage equal to 8% of their Max HP each turn for 2 turns.',
		zawakeEffectDesc_en = 'Tsuyuri Kanao slashes directly, dealing #C0xE69900#175% Physical ATK#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#Physical DMG#C0x5B545B# and inflicting <Deep Wound> for 2 turns. <Deep Wound>: reduces healing effectiveness by 20%, if the target belongs to the Poison element, reduces healing effectiveness by 40%. The struck target becomes inflicted with <Poison>, taking damage equal to 8% of their Max HP each turn for 2 turns.',
		zawakeEffectDesc_th = 'Tsuyuri Kanao ฟันตรง สร้างความเสียหาย #C0xE69900#175% กายภาพ#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# และทำให้เกิดเอฟเฟกต์ <บาดแผลลึก> เป็นเวลา 2 เทิร์น <บาดแผลลึก>: ลดประสิทธิภาพการฟื้นฟู 20% หากเป้าหมายเป็นธาตุพิษ จะลดประสิทธิภาพการฟื้นฟู 40% เป้าหมายที่โดนโจมตีจะติดสถานะ <พิษ> ได้รับความเสียหายเท่ากับ 8% ของ HP สูงสุดในแต่ละเทิร์นเป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Tsuyuri Kanao menebas lurus, memberikan #C0xE69900#175% ATK Fisik#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#DMG Fisik#C0x5B545B# dan memberikan efek <Luka Dalam> selama 2 giliran. <Luka Dalam>: mengurangi efektivitas pemulihan sebesar 20%, jika target adalah elemen Racun maka efektivitas pemulihan berkurang 40%. Target yang terkena serangan akan terinfeksi <Racun>, menerima DMG sebesar 8% HP Maks setiap giliran selama 2 giliran.',
		zawakeEffectDesc_ph = 'Tsuyuri Kanao ay tumaga nang diretso, nagdudulot ng #C0xE69900#175% Pisikal na ATK#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#Pisikal na DMG#C0x5B545B# at naglalagay ng <Malalim na Sugat> sa loob ng 2 turn. <Malalim na Sugat>: binabawasan ang bisa ng paggaling ng 20%, kung ang target ay may Poison element, binabawasan ang bisa ng paggaling ng 40%. Ang tinamaan ay mae-expose sa <Lason>, tumatanggap ng DMG katumbas ng 8% ng Max HP bawat turn sa loob ng 2 turn.',
		zawakeEffectDesc_ma = 'Tsuyuri Kanao menetak lurus, memberikan #C0xE69900#175% ATK Fizikal#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#DMG Fizikal#C0x5B545B# serta mengenakan kesan <Luka Dalam> selama 2 giliran. <Luka Dalam>: mengurangkan keberkesanan pemulihan sebanyak 20%, jika sasaran adalah elemen Racun maka keberkesanan pemulihan berkurang 40%. Sasaran yang terkena serangan akan dijangkiti <Racun>, menerima DMG sebanyak 8% daripada HP Maks setiap giliran selama 2 giliran.',
		zawakeEffectDesc_vn = 'Tsuyuri Kanao chém thẳng gây #C0xE69900#175% Công Vật Lý#C0x5B545B#+$(skillLevel*4*23)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# và gây hiệu ứng <Vết Thương Sâu> trong 2 lượt. <Vết Thương Sâu>: giảm hiệu quả hồi phục 20%, nếu mục tiệu thuộc hệ Độc thì giảm hiệu quả hồi phục 40%. Mục tiêu trúng chiêu bị nhiễm <Độc>, chịu sát thương bằng 8% HP tối đa mỗi lượt trong 2 lượt.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Targets hit are inflicted with <Poison>, taking damage equal to 8% of their Max HP per turn for 2 turns.  ',
		zawakeSimpleDesc_en = 'Targets hit are inflicted with <Poison>, taking damage equal to 8% of their Max HP per turn for 2 turns.  ',
		zawakeSimpleDesc_th = 'เป้าหมายที่ถูกโจมตีติด <พิษ> รับความเสียหายเท่ากับ 8% ของ HP สูงสุดต่อรอบเป็นเวลา 2 รอบ',
		zawakeSimpleDesc_in = 'Target yang terkena terkena <Racun>, menerima damage sebesar 8% HP Maks mereka per giliran selama 2 giliran.  ',
