	[80042] = {
		id = 80042,
		skillName_vn = 'Flower-Slaying Shadow Slash',
		skillName_en = 'Flower-Slaying Shadow Slash',
		skillName_th = 'ฟันทำลายดอกไม้ เงามายา',
		skillName_in = 'Tebasan Bayangan Pembantai Bunga',
		skillName_ph = 'Hiwa ng Aninong Pumupuksa ng Bulaklak',
		skillName_ma = 'Tebasan Bayangan Pemusnah Bunga',
		skillName = 'Flower-Slaying Shadow Slash',
		describe_vn = 'Tsuyuri Kanao vung kiếm chém thẳng về phía trước, tấn công mục tiêu trực diện ở hàng trước của kẻ địch, gây #C0xE69900#250% Công V.Lý#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#. Sau khi tấn công, Kanao tăng 20% tốc độ trong 1 lượt, nhận giáp hấp thụ bằng 10% HP tối đa trong 2 lượt; đồng thời, mục tiêu trúng chiêu bị nhiễm <Độc>, chịu sát thương bằng 8% HP tối đa mỗi lượt trong 2 lượt.',
		describe_en = 'Tsuyuri Kanao swings her sword forward, striking the front-row enemy directly, dealing #C0xE69900#250% Physical ATK#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#Physical DMG#C0x5B545B#. After attacking, Kanao increases her Speed by 20% for 1 turn, gains a shield equal to 10% of her Max HP for 2 turns; at the same time, the target hit is inflicted with <Poison>, taking damage equal to 8% of their Max HP per turn for 2 turns',
		describe_th = 'สึยุริ คานาโอะเหวี่ยงดาบฟันไปข้างหน้า โจมตีศัตรูแถวหน้าตรงๆ สร้างความเสียหาย #C0xE69900#250% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# หลังจากโจมตี คานาโอะเพิ่มความเร็ว 20% เป็นเวลา 1 เทิร์น ได้รับเกราะดูดซับเท่ากับ 10% HP สูงสุด เป็นเวลา 2 เทิร์น; ในขณะเดียวกัน เป้าหมายที่โดนโจมตีจะติดสถานะ <พิษ> รับความเสียหายเท่ากับ 8% ของ HP สูงสุดต่อเทิร์น เป็นเวลา 2 เทิร์น',
		describe_in = 'Tsuyuri Kanao mengayunkan pedangnya ke depan, menyerang musuh baris depan secara langsung, memberikan #C0xE69900#250% ATK Fisik#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#DMG Fisik#C0x5B545B#. Setelah menyerang, Kanao meningkatkan Kecepatan sebesar 20% selama 1 giliran, mendapatkan perisai yang menyerap setara dengan 10% HP Maks selama 2 giliran; pada saat yang sama, target yang terkena serangan akan terkena <Racun>, menerima damage sebesar 8% HP Maks setiap giliran selama 2 giliran',
		describe_ph = 'Si Tsuyuri Kanao ay iwinasiwas ang kanyang espada pasulong, direktang inaatake ang kalabang nasa front row, nagdudulot ng #C0xE69900#250% Pisikal na ATK#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#Pisikal na DMG#C0x5B545B#. Pagkatapos umatake, tataas ang Speed ni Kanao ng 20% sa loob ng 1 turn, makakakuha siya ng shield na sumisipsip ng damage katumbas ng 10% Max HP sa loob ng 2 turn; kasabay nito, ang target na tinamaan ay malalason <Poison>, tumatanggap ng damage katumbas ng 8% Max HP bawat turn sa loob ng 2 turn',
		describe_ma = 'Tsuyuri Kanao menghayun pedang ke hadapan, menyerang musuh barisan depan secara langsung, memberikan #C0xE69900#250% ATK Fizikal#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#DMG Fizikal#C0x5B545B#. Selepas menyerang, Kanao meningkatkan Kelajuan sebanyak 20% selama 1 giliran, memperoleh perisai yang menyerap sama dengan 10% HP Maks selama 2 giliran; pada masa yang sama, sasaran yang terkena serangan akan dijangkiti <Racun>, menerima damage sebanyak 8% HP Maks setiap giliran selama 2 giliran',
		describe = 'Tsuyuri Kanao swings her sword forward, striking the front-row enemy directly, dealing #C0xE69900#250% Physical ATK#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#Physical DMG#C0x5B545B#. After attacking, Kanao increases her Speed by 20% for 1 turn, gains a shield equal to 10% of her Max HP for 2 turns; at the same time, the target hit is inflicted with <Poison>, taking damage equal to 8% of their Max HP per turn for 2 turns',
		simDesc = 'Vung kiếm chém thẳng gây sát thương vật lý lớn, tăng tốc độ trong lượt kế tiếp.',
		zawakeEffect = __data_t__zawakeEffect[80042],
		-- {79002}
		zawakeEffectDesc = 'Tsuyuri Kanao swings her sword straight forward, attacking the front-row target of the enemy, dealing #C0xE69900#250% Physical ATK#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#Physical DMG#C0x5B545B#. After attacking, Kanao gains 20% Speed for 1 turn, receives a shield equal to 10% of her Max HP for 2 turns; meanwhile, the target hit becomes inflicted with <Poison>, taking DMG equal to 8% of Max HP per turn for 2 turns and suffers <Deep Wound> (healing reduced by 50%) for 2 turns.',
		zawakeEffectDesc_en = 'Tsuyuri Kanao swings her sword straight forward, attacking the front-row target of the enemy, dealing #C0xE69900#250% Physical ATK#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#Physical DMG#C0x5B545B#. After attacking, Kanao gains 20% Speed for 1 turn, receives a shield equal to 10% of her Max HP for 2 turns; meanwhile, the target hit becomes inflicted with <Poison>, taking DMG equal to 8% of Max HP per turn for 2 turns and suffers <Deep Wound> (healing reduced by 50%) for 2 turns.',
		zawakeEffectDesc_th = 'Tsuyuri Kanao ฟันตรงไปข้างหน้า โจมตีเป้าหมายแถวหน้าของศัตรู สร้างความเสียหาย #C0xE69900#250% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# หลังจากโจมตี Kanao จะได้รับความเร็วเพิ่มขึ้น 20% เป็นเวลา 1 เทิร์น ได้รับโล่ดูดซับความเสียหายเท่ากับ 10% ของ HP สูงสุดเป็นเวลา 2 เทิร์น; ในขณะเดียวกัน เป้าหมายที่ถูกโจมตีจะติด <พิษ> ได้รับความเสียหายเท่ากับ 8% ของ HP สูงสุดต่อเทิร์นเป็นเวลา 2 เทิร์น และได้รับเอฟเฟกต์ <บาดแผลลึก> (ลดการฟื้นฟู 50%) เป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Tsuyuri Kanao mengayunkan pedangnya lurus ke depan, menyerang target barisan depan musuh, memberikan #C0xE69900#250% ATK Fisik#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#DMG Fisik#C0x5B545B#. Setelah menyerang, Kanao mendapatkan 20% Kecepatan selama 1 giliran, menerima perisai setara dengan 10% HP Maks selama 2 giliran; sementara itu, target yang terkena serangan akan terkena <Racun>, menerima damage sebesar 8% HP Maks per giliran selama 2 giliran dan menderita efek <Luka Dalam> (pemulihan berkurang 50%) selama 2 giliran.',
		zawakeEffectDesc_ph = 'Tsuyuri Kanao ay mabilis na humataw ng espada nang diretso pasulong, inaatake ang target sa harapang hanay ng kalaban, nagdudulot ng #C0xE69900#250% Pisikal na ATK#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#Pisikal na DMG#C0x5B545B#. Pagkatapos umatake, nakakakuha si Kanao ng +20% Bilis sa loob ng 1 turn, at tumatanggap ng kalasag na sumisipsip ng pinsala katumbas ng 10% ng Max HP sa loob ng 2 turn; samantala, ang target na tinamaan ay malalason <Lason>, tumatanggap ng pinsala na katumbas ng 8% ng Max HP bawat turn sa loob ng 2 turn at tatamaan ng <Malalim na Sugat> (50% bawas sa paggaling) sa loob ng 2 turn.',
		zawakeEffectDesc_ma = 'Tsuyuri Kanao menghayunkan pedangnya lurus ke hadapan, menyerang sasaran barisan depan musuh, memberikan #C0xE69900#250% ATK Fizikal#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#DMG Fizikal#C0x5B545B#. Selepas menyerang, Kanao mendapat +20% Kelajuan selama 1 giliran, menerima perisai serapan sama dengan 10% HP Maks selama 2 giliran; pada masa yang sama, sasaran yang terkena serangan akan diracuni <Racun>, menerima kerosakan sebanyak 8% HP Maks setiap giliran selama 2 giliran dan mengalami kesan <Luka Dalam> (pemulihan berkurang 50%) selama 2 giliran.',
		zawakeEffectDesc_vn = 'Tsuyuri Kanao vung kiếm chém thẳng về phía trước, tấn công mục tiêu trực diện ở hàng trước của kẻ địch, gây #C0xE69900#250% Công V.Lý#C0x5B545B#+$(skillLevel*4*25)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#. Sau khi tấn công, Kanao tăng 20% tốc độ trong 1 lượt, nhận giáp hấp thụ bằng 10% HP tối đa trong 2 lượt; đồng thời, mục tiêu trúng chiêu bị nhiễm <Độc>, chịu sát thương bằng 8% HP tối đa mỗi lượt trong 2 lượt và chịu hiệu ứng <Vết Thương Sâu> (giảm 50% hồi phục) trong 2 lượt.',
		zawakeSimpleType = 1,
