	[80043] = {
		id = 80043,
		skillName_vn = 'Dance of Cherry Blossoms',
		skillName_en = 'Dance of Cherry Blossoms',
		skillName_th = 'ระบำซากุระ',
		skillName_in = 'Tarian Bunga Sakura',
		skillName_ph = 'Sayaw ng mga Bulaklak ng Sakura',
		skillName_ma = 'Tarian Bunga Sakura',
		skillName = 'Dance of Cherry Blossoms',
		describe_vn = 'Tsuyuri Kanao xoay người tung ra chuỗi chém liên hoàn vào một mục tiêu phía trước, gây #C0xE69900#660% Công V.Lý#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#. Sau khi tấn công, Kanao tăng 25% tỷ lệ né tránh trong 2 lượt; đồng thời, mục tiêu trúng chiêu bị giảm 30% thủ vật lý và chịu hiệu ứng <Vết Thương Sâu> (giảm 50% hồi phục) trong 2 lượt',
		describe_en = 'Tsuyuri Kanao spins and unleashes a chain of slashes at a front enemy target, dealing #C0xE69900#660% Physical ATK#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#Physical Damage#C0x5B545B#. After the attack, Kanao increases Dodge Rate by 25% for 2 turns; at the same time, the target hit suffers -30% Physical DEF and is inflicted with <Deep Wound> (healing reduced by 50%) for 2 turns.',
		describe_th = 'Tsuyuri Kanao หมุนตัวปลดปล่อยการฟันต่อเนื่องใส่เป้าหมายศัตรูด้านหน้า สร้างความเสียหาย #C0xE69900#660% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# หลังการโจมตี Kanao เพิ่มอัตราหลบหลีก 25% เป็นเวลา 2 เทิร์น; พร้อมกันนี้เป้าหมายที่ถูกโจมตีจะลดการป้องกันกายภาพ 30% และได้รับเอฟเฟกต์ <บาดแผลลึก> (ลดการฟื้นฟู 50%) เป็นเวลา 2 เทิร์น',
		describe_in = 'Tsuyuri Kanao berputar lalu melancarkan serangan beruntun ke satu musuh di depan, memberikan #C0xE69900#660% ATK Fisik#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#Damage Fisik#C0x5B545B#. Setelah menyerang, Kanao meningkatkan 25% Dodge Rate selama 2 giliran; pada saat yang sama, target yang terkena serangan berkurang 30% DEF Fisik dan terkena efek <Luka Dalam> (pemulihan berkurang 50%) selama 2 giliran',
		describe_ph = 'Tsuyuri Kanao umiikot at naglalabas ng sunod-sunod na tebas sa isang kalabang nasa harap, nagdudulot ng #C0xE69900#660% Physical ATK#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#Physical Damage#C0x5B545B#. Pagkatapos umatake, tumataas ang Dodge Rate ni Kanao ng 25% sa loob ng 2 turn; kasabay nito, ang kalabang tinamaan ay nababawasan ng 30% Physical DEF at nagkakaroon ng <Malalim na Sugat> (bawas 50% healing) sa loob ng 2 turn',
		describe_ma = 'Tsuyuri Kanao berpusing lalu melancarkan siri tebasan berturut-turut ke arah satu musuh di hadapan, memberikan #C0xE69900#660% ATK Fizikal#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#Damage Fizikal#C0x5B545B#. Selepas menyerang, Kanao meningkatkan 25% Kadar Elak selama 2 giliran; pada masa yang sama, sasaran yang terkena serangan berkurang 30% DEF Fizikal dan dikenakan kesan <Luka Parah> (penyembuhan berkurang 50%) selama 2 giliran',
		describe = 'Tsuyuri Kanao spins and unleashes a chain of slashes at a front enemy target, dealing #C0xE69900#660% Physical ATK#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#Physical Damage#C0x5B545B#. After the attack, Kanao increases Dodge Rate by 25% for 2 turns; at the same time, the target hit suffers -30% Physical DEF and is inflicted with <Deep Wound> (healing reduced by 50%) for 2 turns.',
		simDesc = 'Liên hoàn xoay kiếm tấn công một mục tiêu, gây sát thương cực lớn và tăng mạnh né tránh cho bản thân',
		starEffect = __data_t__starEffect[80043],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Ngoài ra, mỗi khi Kanao tung kỹ năng này, cô được tăng 15% tốc độ và giảm 20% sát thương nhận vào trong 1 lượt.',
		starEffectDesc = 'Additional Effect: Furthermore, each time Kanao uses this skill, she gains 15% Speed and reduces damage taken by 20% for 1 turn',
		starEffectDesc_en = 'Additional Effect: Furthermore, each time Kanao uses this skill, she gains 15% Speed and reduces damage taken by 20% for 1 turn',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: นอกจากนี้ ทุกครั้งที่ Kanao ใช้สกิลนี้ เธอจะได้รับความเร็วเพิ่มขึ้น 15% และลดความเสียหายที่ได้รับลง 20% เป็นเวลา 1 เทิร์น',
		starEffectDesc_in = 'Efek Tambahan: Selain itu, setiap kali Kanao menggunakan skill ini, ia mendapatkan 15% Kecepatan dan mengurangi damage yang diterima sebesar 20% selama 1 giliran',
		starEffectDesc_ph = 'Karagdagang Epekto: Bukod pa rito, sa tuwing ginagamit ni Kanao ang kasanayang ito, nakakakuha siya ng 15% Speed at nababawasan ang natatanggap na damage ng 20% sa loob ng 1 turn',
		starEffectDesc_ma = 'Kesan Tambahan: Selain itu, setiap kali Kanao menggunakan kemahiran ini, dia akan memperoleh 15% Kelajuan dan mengurangkan kerosakan yang diterima sebanyak 20% selama 1 giliran',
		zawakeEffect = __data_t__zawakeEffect[80043],
		-- {79003}
		zawakeEffectDesc = 'Tsuyuri Kanao spins and unleashes a chain of slashes on a front target, dealing #C0xE69900#660% Physical ATK#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#Physical DMG#C0x5B545B#. After the attack, Kanao increases Dodge Rate by 25% for 2 turns; at the same time, the struck target’s Physical DEF is reduced by 30% and suffers <Deep Wound> (healing reduced by 50%) for 2 turns. The struck target is also inflicted with <Poison>, taking damage equal to 8% of Max HP per turn for 2 turns.',
		zawakeEffectDesc_en = 'Tsuyuri Kanao spins and unleashes a chain of slashes on a front target, dealing #C0xE69900#660% Physical ATK#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#Physical DMG#C0x5B545B#. After the attack, Kanao increases Dodge Rate by 25% for 2 turns; at the same time, the struck target’s Physical DEF is reduced by 30% and suffers <Deep Wound> (healing reduced by 50%) for 2 turns. The struck target is also inflicted with <Poison>, taking damage equal to 8% of Max HP per turn for 2 turns.',
		zawakeEffectDesc_th = 'สึยุริ คานาโอะหมุนตัวฟันต่อเนื่องใส่เป้าหมายด้านหน้า สร้างความเสียหาย #C0xE69900#660% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# หลังการโจมตี คานาโอะเพิ่มอัตราหลบหลีก 25% เป็นเวลา 2 เทิร์น; ในเวลาเดียวกัน เป้าหมายที่ถูกฟันจะลดพลังป้องกันกายภาพลง 30% และติดสถานะ <บาดแผลลึก> (ลดการฟื้นฟู 50%) เป็นเวลา 2 เทิร์น เป้าหมายยังติดสถานะ <พิษ> ได้รับความเสียหาย 8% ของ HP สูงสุดต่อเทิร์นเป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Tsuyuri Kanao berputar lalu melancarkan serangan tebasan beruntun pada satu target di depan, memberikan #C0xE69900#660% ATK Fisik#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#DMG Fisik#C0x5B545B#. Setelah menyerang, Kanao meningkatkan 25% Peluang Menghindar selama 2 giliran; pada saat yang sama, target yang terkena serangan berkurang 30% DEF Fisik dan terkena efek <Luka Dalam> (pemulihan berkurang 50%) selama 2 giliran. Target juga terkena <Racun>, menerima DMG setara 8% Max HP tiap giliran selama 2 giliran.',
		zawakeEffectDesc_ph = 'Si Tsuyuri Kanao ay umiikot at nagpakawala ng sunod-sunod na tebas sa isang target sa harap, nagdudulot ng #C0xE69900#660% Physical ATK#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#Physical DMG#C0x5B545B#. Pagkatapos umatake, tumataas ang Dodge Rate ni Kanao ng 25% sa loob ng 2 turn; kasabay nito, ang target na tinamaan ay nababawasan ng 30% Physical DEF at tatamaan ng <Malalim na Sugat> (bawas 50% healing) sa loob ng 2 turn. Ang target ay tatamaan din ng <Lason>, tumatanggap ng 8% ng Max HP bilang DMG bawat turn sa loob ng 2 turn.',
		zawakeEffectDesc_ma = 'Tsuyuri Kanao berpusing lalu melancarkan siri tebasan berturut-turut ke arah satu sasaran di hadapan, memberikan #C0xE69900#660% ATK Fizikal#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#DMG Fizikal#C0x5B545B#. Selepas menyerang, Kanao meningkatkan Kadar Elak sebanyak 25% selama 2 giliran; pada masa yang sama, sasaran yang terkena serangan berkurang 30% DEF Fizikal dan menerima kesan <Luka Dalam> (pemulihan berkurang 50%) selama 2 giliran. Sasaran juga akan dijangkiti <Racun>, menerima DMG bersamaan 8% HP Maksimum setiap giliran selama 2 giliran.',
		zawakeEffectDesc_vn = 'Tsuyuri Kanao xoay người tung ra chuỗi chém liên hoàn vào một mục tiêu phía trước, gây #C0xE69900#660% Công V.Lý#C0x5B545B#+$(skillLevel*4*32)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#. Sau khi tấn công, Kanao tăng 25% tỷ lệ né tránh trong 2 lượt; đồng thời, mục tiêu trúng chiêu bị giảm 30% thủ vật lý và chịu hiệu ứng <Vết Thương Sâu> (giảm 50% hồi phục) trong 2 lượt. Mục tiêu trúng chiêu bị nhiễm <Độc>, chịu sát thương bằng 8% HP tối đa mỗi lượt trong 2 lượt.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Targets hit are inflicted with <Poison>, taking damage equal to 8% of their Max HP per turn for 2 turns.',
		zawakeSimpleDesc_en = 'Targets hit are inflicted with <Poison>, taking damage equal to 8% of their Max HP per turn for 2 turns.',
		zawakeSimpleDesc_th = 'เป้าหมายที่ถูกโจมตีติด <พิษ> รับความเสียหายเท่ากับ 8% ของ HP สูงสุดต่อรอบเป็นเวลา 2 รอบ',
		zawakeSimpleDesc_in = 'Target yang terkena terkena <Racun>, menerima damage sebesar 8% HP Maks mereka per giliran selama 2 giliran.',
		zawakeSimpleDesc_ph = 'Ang mga target na tinamaan ay nagkakaroon ng <Poison>, tumatanggap ng pinsalang katumbas ng 8% ng Max HP bawat turno sa loob ng 2 turno.',
		zawakeSimpleDesc_ma = 'Sasaran yang terkena akan dijangkiti <Racun>, menerima kerosakan bersamaan 8% HP Maksimum setiap giliran selama 2 giliran.',
