	[80044] = {
		id = 80044,
		describe_vn = 'Cứ sau 5% sức mạnh phòng thủ bổ sung (phần thưởng thiên đường ether, phần thưởng chiến đấu đặc biệt, tăng buff) sẽ tăng hiệu ứng đẩy lùi sát thương lên 5%',
		describe_en = 'For every additional 5% defense power (Ether Heaven reward, special battle reward, buff increase), the damage knockback effect increases by 5%.',
		describe_th = 'ทุกๆ การเพิ่มพลังป้องกัน 5% (รางวัลสวรรค์เอเทอร์, รางวัลการต่อสู้พิเศษ, การเพิ่มบัฟ) จะเพิ่มผลการดันความเสียหายขึ้น 5%.',
		describe_in = 'Setiap tambahan 5% kekuatan pertahanan (hadiah Ether Surga, hadiah pertempuran khusus, peningkatan buff) akan meningkatkan efek tolak kerusakan sebesar 5%.',
		describe_ph = 'Sa bawat karagdagang 5% na lakas ng depensa (Ether Heaven reward, espesyal na gantimpala sa laban, pagtaas ng buff) ay nagpapataas ng epekto ng knockback damage ng 5%.',
		describe_ma = 'Setiap tambahan 5% kuasa pertahanan (ganjaran Ether Syurga, ganjaran pertempuran istimewa, peningkatan buff) akan meningkatkan kesan tolak kerosakan sebanyak 5%.',
		describe = 'For every additional 5% defense power (Ether Heaven reward, special battle reward, buff increase), the damage knockback effect increases by 5%.',
