	},
	[80045] = {
		id = 80045,
		describe_vn = 'Mỗi lần gây sát thương có thể nhận được giá trị lá chắn bằng 10% giá trị sát thương',
		describe_en = 'Each time damage is dealt, a shield value equal to 10% of the damage dealt can be received.',
		describe_th = 'ทุกครั้งที่สร้างความเสียหาย จะได้รับค่าพลังโล่เท่ากับ 10% ของค่าความเสียหายที่สร้างได้',
		describe_in = 'Setiap kali memberikan kerusakan, dapat menerima nilai perisai sebesar 10% dari nilai kerusakan tersebut.',
		describe_ph = 'Sa bawat beses na makapagdulot ng pinsala, maaaring makatanggap ng halaga ng kalasag na katumbas ng 10% ng pinsalang nagawa.',
