	[80046] = {
		id = 80046,
		skillName_vn = 'Đồng Tâm Như Thủy',
		skillName_en = 'United Heart Like Water',
		skillName_th = 'ใจเป็นหนึ่งดุจสายน้ำ',
		skillName_in = 'Hati Seirama Bagaikan Air',
		skillName_ph = 'Pusong Nagkakaisa Gaya ng Tubig',
		skillName_ma = 'Hati Sejiwa Laksana Air',
		skillName = 'United Heart Like Water',
		describe_vn = 'Khi HP của Kanao giảm xuống dưới 40%, cô tự động loại bỏ toàn bộ hiệu ứng bất lợi trên bản thân, tăng 15% tốc độ và 18% tỷ lệ chí mạng trong 2 lượt đồng thời nhận thêm hiệu ứng <Tĩnh Tâm>: mỗi lần nhận sát thương sẽ hồi phục 8% HP đã mất.',
		describe_en = 'When Kanao\'s HP falls below 40%, she automatically removes all debuffs on herself, increases Speed by 15% and Crit Rate by 18% for 2 turns, and additionally gains the <Calm Mind> effect: each time she takes damage, she recovers 8% of lost HP',
		describe_th = 'เมื่อ HP ของ Kanao ลดต่ำกว่า 40% เธอจะลบสถานะลบทั้งหมดบนตัวเองโดยอัตโนมัติ เพิ่มความเร็ว 15% และอัตราคริติคอล 18% เป็นเวลา 2 เทิร์น และยังได้รับเอฟเฟกต์ <จิตสงบ>: ทุกครั้งที่ได้รับความเสียหายจะฟื้นฟู 8% ของ HP ที่สูญเสียไป',
		describe_in = 'Ketika HP Kanao turun di bawah 40%, dia secara otomatis menghapus semua debuff pada dirinya, meningkatkan Speed sebesar 15% dan Crit Rate sebesar 18% selama 2 giliran, serta mendapatkan efek <Tenang>: setiap kali menerima damage, dia memulihkan 8% HP yang hilang',
		describe_ph = 'Kapag bumaba ang HP ni Kanao sa ilalim ng 40%, awtomatiko niyang inaalis ang lahat ng debuff sa sarili, tumataas ang Speed ng 15% at Crit Rate ng 18% sa loob ng 2 turn, at nakakatanggap din siya ng epekto <Payapang Isip>: sa bawat pagtanggap ng damage, nakakabawi siya ng 8% ng nawalang HP',
		describe_ma = 'Apabila HP Kanao jatuh di bawah 40%, dia secara automatik membuang semua debuff pada dirinya, meningkatkan Kelajuan sebanyak 15% dan Kadar Kritikal sebanyak 18% selama 2 giliran, serta menerima kesan <Tenang>: setiap kali menerima damage, dia memulihkan 8% HP yang hilang',
		describe = 'When Kanao\'s HP falls below 40%, she automatically removes all debuffs on herself, increases Speed by 15% and Crit Rate by 18% for 2 turns, and additionally gains the <Calm Mind> effect: each time she takes damage, she recovers 8% of lost HP',
		simDesc = 'Khi máu xuống thấp, bộc phát sức mạnh',
		starEffect = __data_t__starEffect[80046],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Khi máu giảm dưới 40%, Kanao ngay lập tức hồi phục 20% lượng máu đã mất và nhận trạng thái miễn nhiễm hiệu ứng xấu trong 1 lượt. Hiệu ứng này chỉ xảy ra tối đa 1 lần mỗi trận.',
		starEffectDesc = 'Additional Effect: When HP falls below 40%, Kanao immediately recovers 20% of lost HP and gains immunity to negative effects for 1 turn. This effect can only trigger once per battle',
		starEffectDesc_en = 'Additional Effect: When HP falls below 40%, Kanao immediately recovers 20% of lost HP and gains immunity to negative effects for 1 turn. This effect can only trigger once per battle',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: เมื่อ HP ลดต่ำกว่า 40% Kanao จะฟื้นฟูทันที 20% ของ HP ที่สูญเสียไป และได้รับสถานะป้องกันผลลบเป็นเวลา 1 เทิร์น เอฟเฟกต์นี้จะเกิดขึ้นได้สูงสุดเพียง 1 ครั้งต่อการต่อสู้',
		starEffectDesc_in = 'Efek Tambahan: Saat HP turun di bawah 40%, Kanao langsung memulihkan 20% HP yang hilang dan mendapatkan status kebal terhadap efek negatif selama 1 giliran. Efek ini hanya dapat aktif maksimal 1 kali per pertarungan',
		starEffectDesc_ph = 'Karagdagang Epekto: Kapag bumaba ang HP sa ilalim ng 40%, agad na nagre-recover si Kanao ng 20% ng nawalang HP at nakakakuha ng immunity laban sa negatibong epekto sa loob ng 1 turn. Ang epektong ito ay maaari lamang mangyari nang isang beses bawat laban',
		starEffectDesc_ma = 'Kesan Tambahan: Apabila HP jatuh di bawah 40%, Kanao serta-merta memulihkan 20% HP yang hilang dan memperoleh imuniti terhadap kesan negatif selama 1 giliran. Kesan ini hanya boleh berlaku maksimum 1 kali setiap pertempuran',
		zawakeEffect = __data_t__zawakeEffect[80046],
		-- {79004}
		zawakeEffectDesc = 'When Kanao\'s HP drops below 40%, she automatically removes all debuffs on herself, increases Speed by 15% and Critical Rate by 18% for 2 turns, and additionally gains <Calm Mind>: each time she takes damage, she recovers 12% of lost HP.',
		zawakeEffectDesc_en = 'When Kanao\'s HP drops below 40%, she automatically removes all debuffs on herself, increases Speed by 15% and Critical Rate by 18% for 2 turns, and additionally gains <Calm Mind>: each time she takes damage, she recovers 12% of lost HP.',
		zawakeEffectDesc_th = 'เมื่อ HP ของ Kanao ลดลงต่ำกว่า 40% เธอจะลบผลลัพธ์ด้านลบทั้งหมดของตัวเองโดยอัตโนมัติ เพิ่มความเร็ว 15% และอัตราคริติคอล 18% เป็นเวลา 2 เทิร์น พร้อมได้รับเอฟเฟกต์ <จิตสงบ>: ทุกครั้งที่ได้รับความเสียหาย จะฟื้นฟู 12% ของ HP ที่สูญเสียไป',
		zawakeEffectDesc_in = 'Ketika HP Kanao turun di bawah 40%, dia secara otomatis menghapus semua efek negatif pada dirinya, meningkatkan Kecepatan sebesar 15% dan Peluang Crit sebesar 18% selama 2 giliran, serta mendapatkan efek <Tenang>: setiap kali menerima damage, dia memulihkan 12% HP yang hilang.',
		zawakeEffectDesc_ph = 'Kapag bumaba ang HP ni Kanao sa ibaba ng 40%, awtomatiko niyang aalisin ang lahat ng debuff sa sarili niya, tataas ang Bilis ng 15% at Critical Rate ng 18% sa loob ng 2 turn, at makakakuha ng karagdagang epekto na <Payapang Isip>: sa bawat pagtanggap ng pinsala, makakabawi siya ng 12% ng nawawalang HP.',
		zawakeEffectDesc_ma = 'Apabila HP Kanao jatuh di bawah 40%, dia secara automatik akan menghapuskan semua kesan negatif pada dirinya, meningkatkan Kelajuan sebanyak 15% dan Kadar Kritikal sebanyak 18% selama 2 giliran, serta memperoleh kesan <Tenang>: setiap kali menerima kerosakan, dia memulihkan 12% HP yang hilang.',
		zawakeEffectDesc_vn = 'Khi HP của Kanao giảm xuống dưới 40%, cô tự động loại bỏ toàn bộ hiệu ứng bất lợi trên bản thân, tăng 15% tốc độ và 18% tỷ lệ chí mạng trong 2 lượt đồng thời nhận thêm hiệu ứng <Tĩnh Tâm>: mỗi lần nhận sát thương sẽ hồi phục 12% HP đã mất.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Effect <Calm Mind>: Each time damage is received, restores 8% of lost HP. \n#F20# \n#F40##C0x5c9970#→ Effect <Calm Mind>: Each time damage is received, restores 12% of lost HP.',
		zawakeSimpleDesc_en = 'Effect <Calm Mind>: Each time damage is received, restores 8% of lost HP. \n#F20# \n#F40##C0x5c9970#→ Effect <Calm Mind>: Each time damage is received, restores 12% of lost HP.',
		zawakeSimpleDesc_th = 'เอฟเฟกต์ <จิตสงบ>: ทุกครั้งที่ได้รับความเสียหาย ฟื้นฟู 8% ของ HP ที่เสียไป \n#F20# \n#F40##C0x5c9970#→ เอฟเฟกต์ <จิตสงบ>: ทุกครั้งที่ได้รับความเสียหาย ฟื้นฟู 12% ของ HP ที่เสียไป',
		zawakeSimpleDesc_in = 'Efek <Calm Mind>: Setiap kali menerima damage, memulihkan 8% HP yang hilang. \n#F20# \n#F40##C0x5c9970#→ Efek <Calm Mind>: Setiap kali menerima damage, memulihkan 12% HP yang hilang.',
		zawakeSimpleDesc_ph = 'Epekto <Calm Mind>: Sa bawat beses na tumatanggap ng pinsala, bumabalik ang 8% ng nawalang HP. \n#F20# \n#F40##C0x5c9970#→ Epekto <Calm Mind>: Sa bawat beses na tumatanggap ng pinsala, bumabalik ang 12% ng nawalang HP.',
		zawakeSimpleDesc_ma = 'Kesan <Calm Mind>: Setiap kali menerima kerosakan, memulihkan 8% HP yang hilang. \n#F20# \n#F40##C0x5c9970#→ Kesan <Calm Mind>: Setiap kali menerima kerosakan, memulihkan 12% HP yang hilang.',
		zawakeSimpleDesc_vn = 'Hiệu ứng <Tĩnh Tâm>: mỗi lần nhận sát thương sẽ hồi phục 8% HP đã mất. \n#F20# \n#F40##C0x5c9970#→ Hiệu ứng <Tĩnh Tâm>: mỗi lần nhận sát thương sẽ hồi phục 12% HP đã mất.',
		iconRes = 'battle/skill_icon/skill_80046.png',
