	[80047] = {
		id = 80047,
		describe_vn = 'Khi anh hùng đầu tiên của phe ta tử trận, sẽ hồi sinh trước khi bắt đầu lượt hành động tiếp theo, hồi phục 50% máu và 100% giá trị nộ khí, hiệu quả này chỉ áp dụng một lần trong một trận chiến',
		describe_en = 'When the first hero of our side falls, they will be resurrected before the next action turn begins, recovering 50% health and 100% chakra value. This effect can only be applied once per battle.',
		describe_th = 'เมื่อฮีโร่คนแรกของฝ่ายเราตาย จะฟื้นคืนชีพก่อนเริ่มรอบการกระทำถัดไป โดยฟื้นฟูพลังชีวิต 50% และพลังจักระ 100% ผลนี้ใช้ได้เพียงครั้งเดียวต่อการต่อสู้หนึ่งครั้งเท่านั้น',
		describe_in = 'Ketika pahlawan pertama dari pihak kami gugur, mereka akan dibangkitkan kembali sebelum giliran aksi berikutnya dimulai, memulihkan 50% kesehatan dan 100% nilai chakra. Efek ini hanya berlaku satu kali dalam satu pertempuran.',
		describe_ph = 'Kapag ang unang bayani ng aming panig ay namatay, siya ay muling mabubuhay bago magsimula ang susunod na turn ng aksyon, magpapagaling ng 50% ng buhay at 100% ng halaga ng chakra. Ang epekto na ito ay nalalapat lamang nang isang beses bawat laban.',
		describe_ma = 'Apabila wira pertama pihak kami terkorban, dia akan dihidupkan semula sebelum pusingan tindakan seterusnya bermula, memulihkan 50% kesihatan dan 100% nilai chakra. Kesan ini hanya terpakai sekali dalam satu pertempuran.',
		describe = 'When the first hero of our side falls, they will be resurrected before the next action turn begins, recovering 50% health and 100% chakra value. This effect can only be applied once per battle.',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800471}
	},
