	[80054] = {
		id = 80054,
		describe_vn = 'Khi vào trận chiến, toàn bộ anh hùng nhận thêm giá trị nộ khí bằng số loại thuộc tính hiện tại (chỉ tính thuộc tính đầu tiên) * 50',
		describe_en = 'When entering the battle, all heroes gain additional rage value equal to the number of current attribute types (counting only the first attribute) * 50.',
		describe_th = 'เมื่อเข้าสู่การต่อสู้ ฮีโร่ทั้งหมดจะได้รับค่าพลังแค้นเพิ่มขึ้นเท่ากับจำนวนชนิดของคุณสมบัติในขณะนั้น (นับเฉพาะคุณสมบัติแรก) * 50',
		describe_in = 'Saat memasuki pertempuran, semua pahlawan menerima tambahan nilai amarah sebesar jumlah jenis atribut saat ini (hanya menghitung atribut pertama) * 50.',
		describe_ph = 'Kapag pumasok sa laban, ang lahat ng mga bayani ay tumatanggap ng karagdagang halaga ng galit na katumbas ng bilang ng mga uri ng kasalukuyang katangian (binibilang lamang ang unang katangian) * 50.',
		describe_ma = 'Apabila memasuki pertempuran, semua wira mendapat nilai kemarahan tambahan bersamaan dengan bilangan jenis atribut semasa (hanya kira atribut pertama) * 50.',
