	[80055] = {
		id = 80055,
		describe_vn = 'Nếu đội hình có hơn 4 anh hùng có thuộc tính đầu tiên giống nhau, khi bắt đầu trận chiến, anh hùng thuộc tính đó nhận thêm 500 giá trị nộ khí ban đầu',
		describe_en = 'If the team has more than 4 heroes with the same first attribute, at the start of the battle, heroes with that attribute receive an additional 500 initial chakra value.',
		describe_th = 'ถ้าทีมมีฮีโร่มากกว่า 4 ตัวที่มีคุณสมบัติแรกเหมือนกัน เมื่อเริ่มการต่อสู้ ฮีโร่ที่มีคุณสมบัตินั้นจะได้รับพลังชากระเริ่มต้นเพิ่มอีก 500 หน่วย',
		describe_in = 'Jika tim memiliki lebih dari 4 pahlawan dengan atribut pertama yang sama, saat mulai pertempuran, pahlawan dengan atribut tersebut menerima tambahan 500 nilai chakra awal.',
		describe_ph = 'Kung ang koponan ay may higit sa 4 na bayani na may parehong unang katangian, sa simula ng laban, ang mga bayani na may katangiang iyon ay makakatanggap ng dagdag na 500 halaga ng panimulang chakra.',
		describe_ma = 'Jika pasukan mempunyai lebih daripada 4 wira dengan atribut pertama yang sama, pada permulaan pertempuran, wira dengan atribut tersebut menerima tambahan nilai chakra awal sebanyak 500.',
		describe = 'If the team has more than 4 heroes with the same first attribute, at the start of the battle, heroes with that attribute receive an additional 500 initial chakra value.',
