	[80078] = {
		id = 80078,
		describe_vn = 'Trong các lượt lẻ, anh hùng phe ta tăng 30% sát thương kỹ năng đặc biệt, trong các lượt chẵn giảm 15% sát thương kỹ năng đặc biệt',
		describe_en = 'In odd turns, our heroes increase special skill damage by 30%, while in even turns, special skill damage is reduced by 15%.',
		describe_th = 'ในตาที่เป็นเลขคี่ ฮีโร่ฝ่ายเราจะเพิ่มความเสียหายสกิลพิเศษขึ้น 30% ในขณะที่ในตาที่เป็นเลขคู่ ความเสียหายสกิลพิเศษจะลดลง 15%',
		describe_in = 'Pada giliran ganjil, pahlawan kita meningkatkan damage skill khusus sebesar 30%, sedangkan pada giliran genap mengurangi damage skill khusus sebesar 15%.',
