		posChoose = 5,
		skillProcess = {800781}
	},
	[80079] = {
		id = 80079,
		describe_vn = 'Khi kết thúc mỗi vòng lớn, gây sát thương thực bằng 20% tấn công của anh hùng có tấn công cao nhất phe ta lên tất cả anh hùng địch',
		describe_en = 'At the end of each major round, deal true damage equal to 20% of the highest attack hero\'s attack from our side to all enemy heroes.',
		describe_th = 'เมื่อจบรอบใหญ่แต่ละรอบ สร้างความเสียหายจริงเท่ากับ 20% ของพลังโจมตีของฮีโร่ที่มีพลังโจมตีสูงสุดในฝั่งเราต่อฮีโร่ฝ่ายศัตรูทั้งหมด',
		describe_in = 'Pada akhir setiap putaran besar, berikan kerusakan nyata sebesar 20% serangan pahlawan dengan serangan tertinggi dari pihak kita ke semua pahlawan musuh.',
		describe_ph = 'Sa pagtatapos ng bawat malaking round, magdulot ng tunay na pinsala na katumbas ng 20% ng atake ng pinakamatinding hero sa ating panig sa lahat ng kalabang hero.',
		describe_ma = 'Pada akhir setiap pusingan utama, berikan kerosakan sebenar sebanyak 20% serangan wira dengan serangan tertinggi di pihak kita ke semua wira musuh.',
		describe = 'At the end of each major round, deal true damage equal to 20% of the highest attack hero\'s attack from our side to all enemy heroes.',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 9,
		passiveTriggerArg = 1,
		posChoose = 5,
		skillProcess = {800791}
	},
	[80080] = {
		id = 80080,
		describe_vn = 'Khi vào trận chiến, nhận một lá chắn toàn đội, lá chắn này có thể hấp thụ toàn bộ sát thương nhận vào của anh hùng phe ta, giá trị hấp thụ bằng với máu cao nhất của anh hùng phe ta',
		describe_en = 'When entering battle, grant a shield to the entire team that can absorb all damage received by our heroes. The absorption value equals the highest health among our heroes.',
		describe_th = 'เมื่อเข้าสู่การต่อสู้ ให้โล่ป้องกันแก่ทีมทั้งหมด โล่นี้สามารถดูดซับความเสียหายที่ฮีโร่ฝ่ายเรารับได้ทั้งหมด ค่าการดูดซับเท่ากับพลังชีวิตสูงสุดของฮีโร่ฝ่ายเรา',
		describe_in = 'Saat memasuki pertempuran, berikan perisai untuk seluruh tim yang dapat menyerap semua kerusakan yang diterima oleh pahlawan tim kita. Nilai penyerapannya sama dengan kesehatan tertinggi di antara pahlawan tim kita.',
		describe_ph = 'Kapag pumapasok sa laban, magbibigay ng isang shield sa buong koponan na kayang sumipsip ng lahat ng damage na matatanggap ng mga bayani ng aming panig. Ang halaga ng pagsipsip ay kapantay ng pinakamataas na health ng mga bayani ng aming panig.',
		describe_ma = 'Apabila memasuki pertempuran, berikan satu perisai kepada seluruh pasukan yang dapat menyerap semua kerosakan yang diterima oleh wira pasukan kita. Nilai penyerapan adalah sama dengan kesihatan tertinggi wira pasukan kita.',
		describe = 'When entering battle, grant a shield to the entire team that can absorb all damage received by our heroes. The absorption value equals the highest health among our heroes.',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800801}
	},
	[80081] = {
		id = 80081,
		describe_vn = 'Sát thương đốt cháy gây ra bởi anh hùng phe ta tăng gấp đôi',
		describe_en = 'Burn damage caused by our faction\'s hero is doubled',
		describe_th = 'ความเสียหายจากการเผาไหม้ที่เกิดจากฮีโร่ฝ่ายเราถูกเพิ่มเป็นสองเท่า',
