	[80082] = {
		id = 80082,
		describe_vn = 'Trong lượt đầu tiên của trận chiến, đầy nộ khí nhưng sát thương kỹ năng đặc biệt giảm 20% trong 1 lượt',
		describe_en = 'In the first turn of the battle, full of rage but the special skill damage is reduced by 20% for 1 turn.',
		describe_th = 'ในรอบแรกของการต่อสู้ เต็มไปด้วยความโกรธ แต่ความเสียหายจากทักษะพิเศษลดลง 20% เป็นเวลา 1 เทิร์น',
		describe_in = 'Pada giliran pertama pertempuran, penuh dengan kemarahan tetapi kerusakan keterampilan khusus berkurang 20% selama 1 giliran.',
		describe_ph = 'Sa unang turn ng laban, puno ng galit ngunit ang damage ng espesyal na kakayahan ay nabawasan ng 20% sa loob ng 1 turn.',
		describe_ma = 'Pada pusingan pertama pertempuran, penuh dengan kemarahan tetapi kerosakan kemahiran khas dikurangkan sebanyak 20% selama 1 pusingan.',
		describe = 'In the first turn of the battle, full of rage but the special skill damage is reduced by 20% for 1 turn.',
