	[80083] = {
		id = 80083,
		describe_vn = '[Sức mạnh Lửa]: Mỗi lần gây sát thương cho kẻ địch, giảm 8% công đôi của chúng, không vượt quá 10% của bản thân ([Sức mạnh Ác] sẽ tăng cường hiệu quả bổ sung)',
		describe_en = '[Fire Power]: Each time you deal damage to an enemy, reduce their double attack by 8%, not exceeding 10% of your own ( [Evil Power] will enhance the additional effect )',
		describe_th = '[พลังไฟ]: ทุกครั้งที่โจมตีศัตรู จะลดโอกาสโจมตีคู่ของศัตรูลง 8% โดยไม่เกิน 10% ของตัวเอง ([พลังจอมปีศาจ] จะเพิ่มประสิทธิภาพเสริม)',
		describe_in = '[Kekuatan Api]: Setiap kali memberikan kerusakan pada musuh, kurangi serangan ganda mereka sebesar 8%, tidak melebihi 10% dari milikmu sendiri ([Kekuatan Jahat] akan meningkatkan efek tambahan)',
		describe_ph = '[Lakas ng Apoy]: Sa bawat beses na nakakapinsala ka sa kalaban, bawasan ang kanilang dobleng pag-atake ng 8%, hindi lalampas sa 10% ng sarili mo ([Lakas ng Kasamaan] ay magpapalakas sa karagdagang epekto)',
		describe_ma = '[Kuasa Api]: Setiap kali memberikan kesanahan kepada musuh, kurangkan serangan berganda mereka sebanyak 8%, tidak melebihi 10% milik anda sendiri ([Kuasa Jahat] akan meningkatkan kesan tambahan)',
		describe = '[Fire Power]: Each time you deal damage to an enemy, reduce their double attack by 8%, not exceeding 10% of your own ( [Evil Power] will enhance the additional effect )',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800831}
	},
	[80084] = {
		id = 80084,
		describe_vn = '[Sức mạnh Nước]: Mỗi lần gây sát thương cho kẻ địch, giảm 8% phòng đôi của chúng, không vượt quá 10% của bản thân ([Sức mạnh Ác] sẽ tăng cường hiệu quả bổ sung)',
		describe_en = '[Water Power]: Each time you deal damage to an enemy, reduce their defense by 8%, not exceeding 10% of your own ([Evil Power] will further enhance this effect).',
		describe_th = '[พลังน้ำ]: ทุกครั้งที่ทำความเสียหายต่อศัตรู จะลดเกราะของพวกเขา 8% แต่ไม่เกิน 10% ของตัวคุณเอง ([พลังชั่ว]: จะเพิ่มประสิทธิภาพเพิ่มเติมในผลนี้)',
		describe_in = '[Kekuatan Air]: Setiap kali menyerang musuh, kurangi pertahanan mereka sebesar 8%, tidak melebihi 10% dari dirimu sendiri ([Kekuatan Jahat] akan meningkatkan efek tambahan ini).',
		describe_ph = '[Lakas ng Tubig]: Sa bawat beses na makapinsala sa kaaway, bawasan ang kanilang depensa ng 8%, hindi lalampas sa 10% ng sarili mo ([Lakas ng Kasamaan] ay magpapalakas pa ng karagdagang epekto).',
		describe_ma = '[Kekuatan Air]: Setiap kali menyebabkan kerosakan pada musuh, kurangkan pertahanan mereka sebanyak 8%, tidak melebihi 10% dari diri anda sendiri ([Kekuatan Jahat] akan meningkatkan kesan tambahan ini).',
		describe = '[Water Power]: Each time you deal damage to an enemy, reduce their defense by 8%, not exceeding 10% of your own ([Evil Power] will further enhance this effect).',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800841}
	},
	[80085] = {
		id = 80085,
		describe_vn = '[Sức mạnh Ác]: Hiệu quả tăng cường của [Sức mạnh Lửa, Sức mạnh Nước]: Khi tấn công giảm công đôi và phòng đôi của mục tiêu, sẽ chuyển đổi lượng thuộc tính tương đương cho người tấn công, đồng thời khi sở hữu [Sức mạnh Ác, Sức mạnh Lửa, Sức mạnh Nước], toàn đội phe ta nhận thêm 10% hút máu',
		describe_en = '[Evil Power]: The enhancement effect of [Fire Power, Water Power]: When attacking, reduces the target\'s double attack and double defense, converts the equivalent attribute amount to the attacker. Additionally, when possessing [Evil Power, Fire Power, Water Power], our entire team gains an extra 10% lifesteal.',
		describe_th = '[พลังชั่ว]: ผลเสริมของ [พลังไฟ, พลังน้ำ]: เมื่อโจมตีจะลดการโจมตีคู่และป้องกันคู่ของเป้าหมาย และแปลงค่าคุณสมบัติที่เทียบเท่าเป็นของผู้โจมตี อีกทั้งเมื่อครอบครอง [พลังชั่ว, พลังไฟ, พลังน้ำ] ทั้งทีมของเราจะได้รับการดูดเลือดเพิ่มขึ้น 10%.',
		describe_in = '[Kekuatan Jahat]: Efek peningkatan dari [Kekuatan Api, Kekuatan Air]: Saat menyerang mengurangi serangan ganda dan pertahanan ganda target, akan mengubah jumlah atribut yang setara ke penyerang. Selain itu, saat memiliki [Kekuatan Jahat, Kekuatan Api, Kekuatan Air], seluruh tim kita mendapatkan tambahan 10% lifesteal.',
		describe_ph = '[Evil Power]: Ang pag-boost na epekto ng [Fire Power, Water Power]: Kapag umaatake ay nagpapababa ng doble na atake at doble na depensa ng target, ise-convert ang katumbas na halaga ng attribute sa attacker. Kasabay nito, kapag mayroon ng [Evil Power, Fire Power, Water Power], buong koponan natin ay nakakakuha ng dagdag na 10% lifesteal.',
		describe_ma = '[Kekuatan Jahat]: Kesan peningkatan bagi [Kekuatan Api, Kekuatan Air]: Semasa menyerang mengurangkan serangan berganda dan pertahanan berganda sasaran, akan menukar jumlah atribut yang setara kepada penyerang. Selain itu semasa memiliki [Kekuatan Jahat, Kekuatan Api, Kekuatan Air], seluruh pasukan kita menerima tambahan 10% sedutan darah.',
		describe = '[Evil Power]: The enhancement effect of [Fire Power, Water Power]: When attacking, reduces the target\'s double attack and double defense, converts the equivalent attribute amount to the attacker. Additionally, when possessing [Evil Power, Fire Power, Water Power], our entire team gains an extra 10% lifesteal.',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800851}
	},
	[80086] = {
		id = 80086,
		describe_vn = '[Đá Mặt Trời]: Hồi phục 200 điểm nộ khí trước khi bắt đầu lượt hành động (khi đồng thời sở hữu [Đá Mặt Trời và Mặt Trăng], tốc độ hồi phục nộ khí tăng 30%)',
		describe_en = '[Sun Stone]: Recovers 200 chakra points before starting the action turn (when simultaneously possessing [Sun Stone] and [Moon Stone], chakra recovery speed increases by 30%)',
		describe_th = '[หินดวงอาทิตย์]: ฟื้นฟูพลังจักระ 200 หน่วยก่อนเริ่มเทิร์นการเคลื่อนไหว (เมื่อมี [หินดวงอาทิตย์] และ [หินจันทร์] พร้อมกัน ความเร็วการฟื้นฟูจักระจะเพิ่มขึ้น 30%)',
		describe_in = '[Batu Matahari]: Memulihkan 200 poin chakra sebelum memulai giliran aksi (ketika memiliki [Batu Matahari] dan [Batu Bulan] secara bersamaan, kecepatan pemulihan chakra meningkat 30%)',
		describe_ph = '[Bato ng Araw]: Nagpapagaling ng 200 puntos ng chakra bago simulan ang turn ng aksyon (kapag sabay na mayroong [Bato ng Araw] at [Bato ng Buwan], tumataas ang bilis ng pagpapagaling ng chakra ng 30%)',
		describe_ma = '[Batu Matahari]: Memulihkan 200 mata chakra sebelum memulakan giliran tindakan (apabila memiliki [Batu Matahari] dan [Batu Bulan] serentak, kelajuan pemulihan chakra meningkat sebanyak 30%)',
		describe = '[Sun Stone]: Recovers 200 chakra points before starting the action turn (when simultaneously possessing [Sun Stone] and [Moon Stone], chakra recovery speed increases by 30%)',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800861}
	},
	[80087] = {
		id = 80087,
		describe_vn = '[Đá Mặt Trăng]: Hồi phục 10% lượng máu đã mất của bản thân sau khi kết thúc đại hiệp (khi đồng thời sở hữu [Đá Mặt Trời và Mặt Trăng], tốc độ hồi phục nộ khí tăng 30%)',
		describe_en = '[Moon Stone]: Recovers 10% of the user\'s lost health after the end of a round (when simultaneously possessing [Sun and Moon Stones], anger recovery speed increases by 30%)',
		describe_th = '[หินจันทร์]: ฟื้นฟูพลังชีวิตที่เสียไป 10% ของตัวเองหลังจบรอบ (เมื่อถือครอง [หินอาทิตย์และหินจันทร์] พร้อมกัน ความเร็วการฟื้นฟูพลังโกรธเพิ่มขึ้น 30%)',
		describe_in = '[Batu Bulan]: Memulihkan 10% dari HP yang hilang setelah ronde berakhir (ketika memiliki [Batu Matahari dan Bulan] secara bersamaan, kecepatan pemulihan amarah meningkat 30%)',
		describe_ph = '[Bato ng Buwan]: Nagpapagaling ng 10% ng nawalang health ng sarili pagkatapos matapos ang round (kapag sabay na may [Bato ng Araw at Buwan], tumataas ng 30% ang recovery speed ng galit)',
		describe_ma = '[Batu Bulan]: Memulihkan 10% daripada kesihatan yang hilang selepas tamat pusingan (apabila memiliki [Batu Matahari dan Bulan] serentak, kadar pemulihan kemarahan meningkat 30%)',
		describe = '[Moon Stone]: Recovers 10% of the user\'s lost health after the end of a round (when simultaneously possessing [Sun and Moon Stones], anger recovery speed increases by 30%)',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800871}
	},
	[80088] = {
		id = 80088,
		describe_vn = '[Nộ Hỏa]: Khi bắt đầu chiến đấu, toàn bộ đồng minh nhận được 100 điểm nộ khí (mỗi hiệu ứng khác [Chuyển Nộ, Nộ Kích, Hút Nộ, Kích Nộ, Bạo Nộ] tăng thêm 100 điểm nộ khí)',
		describe_en = '[Rage Fire]: At the start of the battle, all allies receive 100 rage points (each effect other than [Rage Transfer, Rage Attack, Rage Absorb, Rage Trigger, Rage Burst] increases rage points by an additional 100).',
		describe_th = '[ไฟโกรธ]: เมื่อเริ่มการต่อสู้ เพื่อนร่วมทีมทั้งหมดจะได้รับ 100 คะแนนความโกรธ (แต่ละเอฟเฟกต์ที่ไม่ใช่ [โอนความโกรธ, โจมตีความโกรธ, ดูดความโกรธ, กระตุ้นความโกรธ, ระเบิดความโกรธ] จะเพิ่มความโกรธขึ้นอีก 100 คะแนน)',
		describe_in = '[Api Amarah]: Saat memulai pertarungan, semua sekutu menerima 100 poin amarah (setiap efek selain [Transfer Amarah, Serangan Amarah, Serap Amarah, Pemicu Amarah, Ledakan Amarah] menambah 100 poin amarah tambahan).',
		describe_ph = '[Galit na Apoy]: Sa pagsisimula ng laban, lahat ng mga kakampi ay makakatanggap ng 100 puntos ng galit (bawat epektong iba sa [Paglipat ng Galit, Atake ng Galit, Pag-absorb ng Galit, Pag-trigger ng Galit, Pagputok ng Galit] ay nagpapataas ng dagdag na 100 puntos ng galit).',
		describe_ma = '[Api Amarah]: Apabila pertempuran bermula, semua sekutu menerima 100 mata amarah (setiap kesan selain [Pindah Amarah, Serangan Amarah, Hisap Amarah, Picu Amarah, Letupan Amarah] menambah 100 mata amarah tambahan).',
		describe = '[Rage Fire]: At the start of the battle, all allies receive 100 rage points (each effect other than [Rage Transfer, Rage Attack, Rage Absorb, Rage Trigger, Rage Burst] increases rage points by an additional 100).',
		alwaysEffective = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {800881}
	},
	[80089] = {
		id = 80089,
