	[80114] = {
		id = 80114,
		skillName_vn = 'Giấc Ngủ Tử Thần',
		skillName_en = 'Death’s Slumber',
		skillName_th = 'นิทราแห่งความตาย',
		skillName_in = 'Tidur Kematian',
		skillName_ph = 'Pag-idlip ng Kamatayan',
		skillName_ma = 'Tidur Maut',
		skillName = 'Death’s Slumber',
		describe_vn = 'Khi bắt đầu trận, nếu tốc độ của Zenitsu cao nhất đội, nhận trạng thái <Ngủ Mê Tỉnh Thức> trong 2 lượt, giúp tăng #C0xE69900#30% Tỷ lệ Chí mạng#C0x5B545B# và gây thêm #C0xF13B54#20% Sát Thương Vật Lý#C0x5B545B# khi bị tấn công. Khi HP lần đầu xuống dưới 30%, hồi #C0x3D8A99#15% HP#C0x5B545B# và giảm 1 lượt hồi chiêu cho toàn bộ kỹ năng.',
		describe_en = 'At the start of battle, if Zenitsu has the highest Speed in the team, he gains <Awakened Slumber> status for 2 turns, increasing #C0xE69900#30% Critical Rate#C0x5B545B# and dealing an additional #C0xF13B54#20% Physical Damage#C0x5B545B# when attacked. When his HP first drops below 30%, he restores #C0x3D8A99#15% HP#C0x5B545B# and reduces the cooldown of all skills by 1 turn',
		describe_th = 'เมื่อเริ่มการต่อสู้ หากความเร็วของเซ็นอิทสึสูงที่สุดในทีม เขาจะได้รับสถานะ <หลับใหลที่ตื่นรู้> เป็นเวลา 2 เทิร์น เพิ่ม #C0xE69900#30% อัตราคริติคอล#C0x5B545B# และสร้างดาเมจกายภาพเพิ่มอีก #C0xF13B54#20%#C0x5B545B# เมื่อถูกโจมตี เมื่อ HP ของเขาลดลงต่ำกว่า 30% เป็นครั้งแรก ฟื้นฟู #C0x3D8A99#15% HP#C0x5B545B# และลดคูลดาวน์ของสกิลทั้งหมดลง 1 เทิร์น',
		describe_in = 'Pada awal pertempuran, jika Zenitsu memiliki Kecepatan tertinggi di tim, ia memperoleh status <Tidur Terbangun> selama 2 giliran, meningkatkan #C0xE69900#30% Critical Rate#C0x5B545B# dan memberikan tambahan #C0xF13B54#20% Damage Fisik#C0x5B545B# saat diserang. Ketika HP-nya pertama kali turun di bawah 30%, ia memulihkan #C0x3D8A99#15% HP#C0x5B545B# dan mengurangi 1 giliran cooldown untuk semua skill',
		describe_ph = 'At the start of battle, if Zenitsu has the highest Speed in the team, he gains <Awakened Slumber> status for 2 turns, increasing #C0xE69900#30% Critical Rate#C0x5B545B# and dealing an additional #C0xF13B54#20% Physical Damage#C0x5B545B# when attacked. When his HP first falls below 30%, he recovers #C0x3D8A99#15% HP#C0x5B545B# and reduces all skill cooldowns by 1 turn.',
		describe_ma = 'Pada permulaan pertempuran, jika Zenitsu mempunyai Kelajuan tertinggi dalam pasukan, dia memperoleh status <Tidur Terjaga> selama 2 giliran, meningkatkan #C0xE69900#30% Kadar Kritikal#C0x5B545B# dan memberikan tambahan #C0xF13B54#20% Damage Fizikal#C0x5B545B# apabila diserang. Apabila HPnya pertama kali jatuh di bawah 30%, dia memulihkan #C0x3D8A99#15% HP#C0x5B545B# dan mengurangkan 1 giliran masa sejuk untuk semua kemahiran',
		describe = 'At the start of battle, if Zenitsu has the highest Speed in the team, he gains <Awakened Slumber> status for 2 turns, increasing #C0xE69900#30% Critical Rate#C0x5B545B# and dealing an additional #C0xF13B54#20% Physical Damage#C0x5B545B# when attacked. When his HP first drops below 30%, he restores #C0x3D8A99#15% HP#C0x5B545B# and reduces the cooldown of all skills by 1 turn',
		simDesc = 'Tăng sức mạnh khi có tốc độ cao và phản đòn khi bị ép. Có cơ chế sinh tồn khi gần chết – rất đáng sở hữu.',
		starEffect = __data_t__starEffect[80114],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Sát thương cộng thêm trong trạng thái Ngủ Mê Tỉnh Thức tăng từ 20% lên 30%.',
		starEffectDesc = 'Enhanced Effect: Additional damage in Awakened Sleep state increases from 20% to 30%.',
		starEffectDesc_en = 'Enhanced Effect: Additional damage in Awakened Sleep state increases from 20% to 30%.',
		starEffectDesc_th = 'เอฟเฟกต์ที่เสริมความแข็งแกร่ง: ความเสียหายเพิ่มเติมในสถานะ หลับใหลตื่นขึ้น เพิ่มจาก 20% เป็น 30%',
		starEffectDesc_in = 'Efek Ditingkatkan: Damage tambahan dalam keadaan Tidur Terbangun meningkat dari 20% menjadi 30%.',
		starEffectDesc_ph = 'Pinahusay na Epekto: Ang karagdagang pinsala sa estado ng Gising na Panaginip ay tumataas mula 20% hanggang 30%.',
