	[80121] = {
		id = 80121,
		skillName_vn = 'Sương Ảnh Đoạn',
		skillName_en = 'Frost Shadow Slash',
		skillName_th = 'ฟันเงาน้ำค้างแข็ง',
		skillName_in = 'Tebasan Bayangan Es',
		skillName_ph = 'Hiwa ng Aninong Yelo',
		skillName_ma = 'Tebasan Bayangan Ais',
		skillName = 'Frost Shadow Slash',
		describe_vn = 'Muichiro ẩn mình trong màn sương mù tĩnh lặng, lao vụt qua kẻ địch như bóng ma, tung ra nhát kiếm siêu tốc gây #C0xE69900#180% Công Vật Lý#C0x5B545B#+$(skillLevel* 4*24)#C0x5B545B#. Nếu tốc độ của Muichiro vượt trội hơn mục tiêu, kỹ năng gây thêm 20% sát thương và có 60% xác suất khiến mục tiêu bị <Giảm Tầm Nhìn> trong 1 lượt (Giảm Tầm Nhìn: giảm 30% tỷ lệ chính xác kỹ năng và đòn đánh, làm suy yếu khả năng phản kích của mục tiêu). Kỹ năng ưu tiên tấn công kẻ địch có HP thấp nhất nếu có nhiều mục tiêu khả thi.',
		describe_en = 'Muichiro hides within the silent mist, dashing past enemies like a ghost, unleashing a super-fast slash that deals #C0xE69900#180% Physical ATK#C0x5B545B#+$(skillLevel*4*24)#C0x5B545B#. If Muichiro’s Speed surpasses the target, the skill deals an additional 20% damage and has a 60% chance to inflict <Vision Reduction> for 1 turn (Vision Reduction: decreases Skill and Attack Accuracy by 30%, weakening the target’s counterattack ability). This skill prioritizes attacking the enemy with the lowest HP if multiple targets are available',
		describe_th = 'มุอิจิโร่ซ่อนกายอยู่ในหมอกอันเงียบสงัด พุ่งผ่านศัตรูดุจวิญญาณ ปล่อยคมดาบความเร็วสูง สร้างความเสียหาย #C0xE69900#180% กายภาพ#C0x5B545B#+$(skillLevel*4*24)#C0x5B545B# หากความเร็วของมุอิจิโร่สูงกว่าเป้าหมาย สกิลจะสร้างดาเมจเพิ่มอีก 20% และมีโอกาส 60% ที่จะทำให้เป้าหมายติดสถานะ <ลดการมองเห็น> 1 เทิร์น (ลดการมองเห็น: ลดความแม่นยำของสกิลและการโจมตีลง 30% ทำให้ความสามารถในการโต้กลับของเป้าหมายอ่อนแอลง) สกิลนี้จะโจมตีศัตรูที่มี HP ต่ำที่สุดก่อนหากมีหลายเป้าหมาย',
		describe_in = 'Muichiro bersembunyi dalam kabut sunyi, melesat melewati musuh seperti hantu, melepaskan tebasan super cepat yang memberikan #C0xE69900#180% ATK Fisik#C0x5B545B#+$(skillLevel*4*24)#C0x5B545B#. Jika Kecepatan Muichiro lebih tinggi dari target, skill ini memberikan 20% damage tambahan dan memiliki 60% peluang untuk menyebabkan <Penglihatan Berkurang> selama 1 giliran (Penglihatan Berkurang: mengurangi Akurasi Skill dan Serangan sebesar 30%, melemahkan kemampuan counterattack target). Skill ini memprioritaskan menyerang musuh dengan HP terendah jika ada beberapa target yang memungkinkan',
		describe_ph = 'Muichiro conceals himself within the silent mist, darting past enemies like a ghost, unleashing a super-fast slash that deals #C0xE69900#180% Physical ATK#C0x5B545B#+$(skillLevel*4*24)#C0x5B545B#. If Muichiro’s Speed exceeds the target’s, the skill deals an additional 20% damage and has a 60% chance to inflict <Vision Reduction> for 1 turn (Vision Reduction: reduces Skill and Attack Accuracy by 30%, weakening the target’s ability to counterattack). This skill prioritizes attacking the enemy with the lowest HP if multiple targets are available',
		describe_ma = 'Muichiro bersembunyi dalam kabus yang sunyi, meluncur melepasi musuh seperti hantu, melancarkan tebasan berkelajuan tinggi yang menyebabkan #C0xE69900#180% ATK Fizikal#C0x5B545B#+$(skillLevel*4*24)#C0x5B545B#. Jika Kelajuan Muichiro melebihi sasaran, kemahiran ini memberikan 20% damage tambahan dan mempunyai 60% peluang untuk mengenakan <Penglihatan Berkurang> selama 1 giliran (Penglihatan Berkurang: mengurangkan Ketepatan Kemahiran dan Serangan sebanyak 30%, melemahkan keupayaan serangan balas sasaran). Kemahiran ini mengutamakan menyerang musuh dengan HP terendah jika terdapat beberapa sasaran yang boleh diserang',
		describe = 'Muichiro hides within the silent mist, dashing past enemies like a ghost, unleashing a super-fast slash that deals #C0xE69900#180% Physical ATK#C0x5B545B#+$(skillLevel*4*24)#C0x5B545B#. If Muichiro’s Speed surpasses the target, the skill deals an additional 20% damage and has a 60% chance to inflict <Vision Reduction> for 1 turn (Vision Reduction: decreases Skill and Attack Accuracy by 30%, weakening the target’s counterattack ability). This skill prioritizes attacking the enemy with the lowest HP if multiple targets are available',
		simDesc = 'Tấn công đơn thể cực nhanh. Gây thêm sát thương nếu tốc độ vượt trội và có xác suất làm giảm tầm nhìn mục tiêu.',
