	[80122] = {
		id = 80122,
		skillName_vn = 'Sương Giáng Tán Ảnh',
		skillName_en = 'Frost Descent: Scattered Shadows',
		skillName_th = 'น้ำค้างแข็งโปรย: เงาสลาย',
		skillName_in = 'Turunnya Es: Bayangan Tersebar',
		skillName_ph = 'Pagbagsak ng Yelo: Nagkawatak-watak na Anino',
		skillName_ma = 'Turunnya Ais: Bayangan Berselerak',
		skillName = 'Frost Descent: Scattered Shadows',
		describe_vn = 'Muichiro sử dụng sức mạnh tử thần, hợp nhất linh hồn với thể xác, tung ra một nhát kiếm khí vô biên chém xuyên toàn bộ hàng kẻ địch, gây #C0xE69900#350% Công Vật Lý#C0x5B545B#+$(skillLevel* 4*48)#C0x5B545B#. Sau chiêu thức, Muichiro mất 5% máu hiện tại nhưng nhận trạng thái <Bất Khuất> trong 2 lượt – giúp tăng sát thương gây ra khi máu càng thấp (tối đa +100% khi máu dưới 30%). Ngoài ra, kẻ địch trúng chiêu sẽ bị <Đốt Cháy> trong 2 lượt, mỗi lượt mất 12% sát thương dựa trên lượng máu mà Muichiro đã mất.',
		describe_en = 'Muichiro unleashes the power of death, merging soul and body, delivering an infinite sword strike that cuts through the entire enemy row, dealing #C0xE69900#350% Physical ATK#C0x5B545B#+$(skillLevel*4*48)#C0x5B545B#. After the strike, Muichiro loses 5% of his current HP but gains <Indomitable> for 2 turns – increasing damage dealt the lower his HP is (up to +100% when HP is below 30%). In addition, enemies hit are inflicted with <Burn> for 2 turns, taking 12% damage each turn based on the amount of HP Muichiro has lost',
		describe_th = 'มุอิจิโร่ปลดปล่อยพลังแห่งความตาย ผสานวิญญาณกับร่างกาย ฟาดดาบพลังไร้ขีดจำกัดฟันทะลุศัตรูทั้งแถว สร้างความเสียหาย #C0xE69900#350% กายภาพ#C0x5B545B#+$(skillLevel*4*48)#C0x5B545B# หลังจากใช้สกิล มุอิจิโร่สูญเสีย HP ปัจจุบัน 5% แต่ได้รับสถานะ <ไม่ยอมสยบ> 2 เทิร์น – เพิ่มดาเมจที่สร้างขึ้นเมื่อ HP ต่ำลง (สูงสุด +100% เมื่อ HP ต่ำกว่า 30%) นอกจากนี้ ศัตรูที่โดนโจมตีจะติดสถานะ <เผาไหม้> 2 เทิร์น รับดาเมจ 12% ต่อเทิร์น ตามจำนวน HP ที่มุอิจิโร่สูญเสีย',
		describe_in = 'Muichiro menggunakan kekuatan kematian, menyatukan jiwa dan raga, melepaskan tebasan pedang tak terbatas yang menembus seluruh barisan musuh, memberikan #C0xE69900#350% ATK Fisik#C0x5B545B#+$(skillLevel*4*48)#C0x5B545B#. Setelah serangan, Muichiro kehilangan 5% HP saat ini tetapi mendapatkan status <Pantang Menyerah> selama 2 giliran – meningkatkan damage yang diberikan semakin rendah HP-nya (hingga +100% ketika HP di bawah 30%). Selain itu, musuh yang terkena akan terkena <Terbakar> selama 2 giliran, menerima 12% damage setiap giliran berdasarkan jumlah HP yang telah hilang oleh Muichiro',
		describe_ph = 'Muichiro calls upon the power of death, merging soul with body, unleashing an endless sword strike that cuts through the entire enemy row, dealing #C0xE69900#350% Physical ATK#C0x5B545B#+$(skillLevel*4*48)#C0x5B545B#. After the strike, Muichiro loses 5% of his current HP but gains <Indomitable> for 2 turns – increasing damage dealt the lower his HP is (up to +100% when HP is below 30%). Additionally, enemies hit are afflicted with <Burn> for 2 turns, taking 12% damage each turn based on the amount of HP Muichiro has lost',
		describe_ma = 'Muichiro menggunakan kuasa kematian, menggabungkan roh dengan jasad, melancarkan tebasan pedang tanpa batas yang menembusi seluruh barisan musuh, menyebabkan #C0xE69900#350% ATK Fizikal#C0x5B545B#+$(skillLevel*4*48)#C0x5B545B#. Selepas serangan, Muichiro kehilangan 5% HP semasa tetapi memperoleh status <Pantang Kalah> selama 2 giliran – meningkatkan damage yang dilakukan apabila HP semakin rendah (sehingga +100% apabila HP di bawah 30%). Selain itu, musuh yang terkena akan terkena <Terbakar> selama 2 giliran, menerima 12% damage setiap giliran berdasarkan jumlah HP yang telah hilang oleh Muichiro',
		describe = 'Muichiro unleashes the power of death, merging soul and body, delivering an infinite sword strike that cuts through the entire enemy row, dealing #C0xE69900#350% Physical ATK#C0x5B545B#+$(skillLevel*4*48)#C0x5B545B#. After the strike, Muichiro loses 5% of his current HP but gains <Indomitable> for 2 turns – increasing damage dealt the lower his HP is (up to +100% when HP is below 30%). In addition, enemies hit are inflicted with <Burn> for 2 turns, taking 12% damage each turn based on the amount of HP Muichiro has lost',
		simDesc = 'Kỹ năng gây sát thương hàng dọc cực mạnh, tỷ lệ sát thương tăng theo lượng máu mất. Gây Đốt Cháy và nhận hiệu ứng Bất Khuất, cực kỳ hiệu quả trong tình huống sinh tồn.',
		zawakeEffect = __data_t__zawakeEffect[80122],
