	[80123] = {
		id = 80123,
		skillName_vn = 'Sương Tỏa Tuyệt Trảm',
		skillName_en = 'Frozen Mist: Ultimate Slash',
		skillName_th = 'หมอกน้ำแข็ง: ฟันเด็ดขาด',
		skillName_in = 'Kabut Beku: Tebasan Pamungkas',
		skillName_ph = 'Nagyeyelong Ulap: Huling Hiwa',
		skillName_ma = 'Kabut Beku: Tebasan Mutlak',
		skillName = 'Frozen Mist: Ultimate Slash',
		describe_vn = 'Muichiro, trong hình dáng xoay chuyển mờ ảo giữa làn sương mù đặc quánh, thi triển kiếm kỹ tối thượng tạo thành lốc xoáy sương sắc bén quét toàn bộ địch gây #C0xE69900#650% Công Vật Lý#C0x5B545B#+$(skillLevel* 4*90)#C0x5B545B#. Mỗi mục tiêu có 60% xác suất bị áp hiệu ứng <Tan Sương> trong 2 lượt, khiến giảm 25% tỷ lệ Né Tránh và 15% thủ vật lí, làm suy yếu khả năng phòng ngự. Ngẫu nhiên làm choáng 2 kẻ địch trong một lượt. Nếu kỹ năng trúng ít hơn 4 mục tiêu, Muichiro tự nhận <Tăng 20% Sát Thương Vật Lý gây ra> trong 2 lượt và <Phản Đòn 40% sát thương nhận vào> trong 2 lượt, sẵn sàng đáp trả mọi đòn công kích.',
		describe_en = 'Muichiro, in a shifting phantom form within the thick mist, unleashes his ultimate sword technique, forming a razor-sharp mist vortex that sweeps all enemies, dealing #C0xE69900#650% Physical ATK#C0x5B545B#+$(skillLevel*4*90)#C0x5B545B#. Each target has a 60% chance to be afflicted with <Mist Dissolve> for 2 turns, reducing Dodge Rate by 25% and Physical Defense by 15%, weakening their defenses. Randomly stuns 2 enemies for 1 turn. If the skill hits fewer than 4 targets, Muichiro gains <+20% Physical Damage Dealt> for 2 turns and <Counter 40% of received damage> for 2 turns, ready to retaliate against all attacks',
		describe_th = 'มุอิจิโร่ในร่างเงาเลือนท่ามกลางหมอกหนา ปลดปล่อยวิชาดาบสูงสุด สร้างพายุหมอกคมกริบกวาดศัตรูทั้งหมด สร้างความเสียหาย #C0xE69900#650% กายภาพ#C0x5B545B#+$(skillLevel*4*90)#C0x5B545B# แต่ละเป้าหมายมีโอกาส 60% ติดสถานะ <สลายหมอก> 2 เทิร์น ลดอัตราหลบหลีกลง 25% และป้องกันกายภาพลง 15% ทำให้การป้องกันอ่อนแอลง สุ่มสตันศัตรู 2 ตัวเป็นเวลา 1 เทิร์น หากสกิลโจมตีโดนน้อยกว่า 4 เป้าหมาย มุอิจิโร่จะได้รับ <เพิ่มดาเมจกายภาพ 20%> 2 เทิร์น และ <สะท้อนดาเมจ 40% ที่ได้รับ> 2 เทิร์น พร้อมโต้กลับการโจมตีใด ๆ',
		describe_in = 'Muichiro, dalam wujud bayangan samar di tengah kabut tebal, melepaskan teknik pedang pamungkas, membentuk pusaran kabut tajam yang menyapu semua musuh, memberikan #C0xE69900#650% ATK Fisik#C0x5B545B#+$(skillLevel*4*90)#C0x5B545B#. Setiap target memiliki 60% peluang terkena efek <Kabut Terurai> selama 2 giliran, mengurangi Dodge Rate sebesar 25% dan Pertahanan Fisik sebesar 15%, melemahkan pertahanan mereka. Secara acak membuat 2 musuh terkena stun selama 1 giliran. Jika skill mengenai kurang dari 4 target, Muichiro memperoleh <+20% Damage Fisik Diberikan> selama 2 giliran dan <Counter 40% damage yang diterima> selama 2 giliran, siap membalas semua serangan',
		describe_ph = 'Muichiro, in a phantom-like form within the dense mist, executes his ultimate sword technique, creating a razor-sharp mist vortex that sweeps all enemies, dealing #C0xE69900#650% Physical ATK#C0x5B545B#+$(skillLevel*4*90)#C0x5B545B#. Each target has a 60% chance to be afflicted with <Mist Dissolve> for 2 turns, reducing Dodge Rate by 25% and Physical Defense by 15%, weakening their defenses. Randomly stuns 2 enemies for 1 turn. If the skill hits fewer than 4 targets, Muichiro gains <+20% Physical Damage Dealt> for 2 turns and <Counter 40% of received damage> for 2 turns, prepared to retaliate against any attack',
		describe_ma = 'Muichiro, dalam wujud bayangan samar di tengah kabus pekat, melancarkan teknik pedang muktamad, membentuk pusaran kabus tajam yang menyapu semua musuh, menyebabkan #C0xE69900#650% ATK Fizikal#C0x5B545B#+$(skillLevel*4*90)#C0x5B545B#. Setiap sasaran mempunyai 60% peluang dikenakan kesan <Kabut Terurai> selama 2 giliran, mengurangkan Kadar Elak sebanyak 25% dan Pertahanan Fizikal sebanyak 15%, melemahkan pertahanan mereka. Secara rawak mengejutkan 2 musuh selama 1 giliran. Jika kemahiran mengenai kurang daripada 4 sasaran, Muichiro memperoleh <+20% Damage Fizikal Dikenakan> selama 2 giliran dan <Pantulan 40% damage diterima> selama 2 giliran, bersedia membalas semua serangan',
		describe = 'Muichiro, in a shifting phantom form within the thick mist, unleashes his ultimate sword technique, forming a razor-sharp mist vortex that sweeps all enemies, dealing #C0xE69900#650% Physical ATK#C0x5B545B#+$(skillLevel*4*90)#C0x5B545B#. Each target has a 60% chance to be afflicted with <Mist Dissolve> for 2 turns, reducing Dodge Rate by 25% and Physical Defense by 15%, weakening their defenses. Randomly stuns 2 enemies for 1 turn. If the skill hits fewer than 4 targets, Muichiro gains <+20% Physical Damage Dealt> for 2 turns and <Counter 40% of received damage> for 2 turns, ready to retaliate against all attacks',
		simDesc = 'Chém toàn bộ địch gây sát thương diện rộng, có thể gây <Tan Sương> và <Choáng>, đồng thời tăng sát thương bản thân nếu trúng ít mục tiêu.',
		starEffect = __data_t__starEffect[80123],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Nếu kỹ năng trúng ≤ 4 mục tiêu, Muichiro nhận lá chắn <Phong kiếm> bằng 30% máu tối đa của bản thân trong 2 lượt và nhận Phản Đòn 60% sát thương nhận vào trong 1 lượt.',
		starEffectDesc = 'Additional Effect: If the skill hits ≤ 4 targets, Muichiro gains a <Wind Blade> shield equal to 30% of his Max HP for 2 turns and receives Counterattack, reflecting 60% of the damage taken for 1 turn.',
		starEffectDesc_en = 'Additional Effect: If the skill hits ≤ 4 targets, Muichiro gains a <Wind Blade> shield equal to 30% of his Max HP for 2 turns and receives Counterattack, reflecting 60% of the damage taken for 1 turn.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: หากสกิลโจมตีโดนเป้าหมาย ≤ 4 ตัว Muichiro จะได้รับโล่ <คมดาบลม> เท่ากับ 30% ของ HP สูงสุด เป็นเวลา 2 เทิร์น และได้รับเอฟเฟกต์ โต้กลับ สะท้อนความเสียหาย 60% ที่ได้รับ เป็นเวลา 1 เทิร์น',
		starEffectDesc_in = 'Efek Tambahan: Jika skill mengenai ≤ 4 target, Muichiro memperoleh perisai <Pedang Angin> sebesar 30% dari HP Maks miliknya selama 2 giliran dan mendapatkan Counterattack, memantulkan 60% damage yang diterima selama 1 giliran.',
		starEffectDesc_ph = 'Dagdag na Epekto: Kung ang kasanayan ay tumama sa ≤ 4 na target, makakakuha si Muichiro ng kalasag na <Wind Blade> na katumbas ng 30% ng kanyang Max HP sa loob ng 2 turn at tatanggap ng Counterattack, na nagbabalik ng 60% ng pinsalang natanggap sa loob ng 1 turn.',
		starEffectDesc_ma = 'Kesan Tambahan: Jika kemahiran terkena ≤ 4 sasaran, Muichiro akan mendapat perisai <Pedang Angin> sebanyak 30% daripada HP Maksnya selama 2 giliran dan menerima Counterattack, memantulkan 60% daripada kerosakan yang diterima selama 1 giliran.',
		zawakeEffect = __data_t__zawakeEffect[80123],
