	[80124] = {
		id = 80124,
		skillName_vn = 'Vô Niệm Vô Ảnh',
		skillName_en = 'No Thought, No Shadow',
		skillName_th = 'ไร้จิต ไร้เงา',
		skillName_in = 'Tanpa Pikiran, Tanpa Bayangan',
		skillName_ph = 'Walang Isip, Walang Anino',
		skillName_ma = 'Tanpa Fikiran, Tanpa Bayangan',
		skillName = 'No Thought, No Shadow',
		describe_vn = 'Muichiro nhận trạng thái <Vô Niệm> trong 2 lượt: tăng 15% Né tránh và nhận hiệu ứng <Tự Làm Mới> mỗi khi kết thúc lượt (xóa 1 hiệu ứng bất lợi). Khi HP lần đầu xuống dưới 40%, nhận thêm trạng thái <Vô Ảnh> trong 2 lượt: tăng 30% Tốc độ và các kỹ năng gây thêm 15% sát thương thực.',
		describe_en = 'Muichiro enters <No Thought> state for 2 turns: increases Dodge by 15% and gains <Self-Renewal> effect at the end of each turn (removes 1 debuff). When HP drops below 40% for the first time, also gains <Shadowless> state for 2 turns: increases Speed by 30% and skills deal an additional 15% true damage',
		describe_th = 'Muichiro เข้าสู่สถานะ <ไร้ความคิด> เป็นเวลา 2 เทิร์น: เพิ่มการหลบหลีก 15% และได้รับเอฟเฟกต์ <ฟื้นฟูตัวเอง> ทุกครั้งเมื่อจบเทิร์น (ลบ 1 ดีบัฟ). เมื่อ HP ลดลงต่ำกว่า 40% ครั้งแรก จะได้รับสถานะ <ไร้เงา> เป็นเวลา 2 เทิร์น: เพิ่มความเร็ว 30% และสกิลสร้างความเสียหายจริงเพิ่มขึ้น 15%',
		describe_in = 'Muichiro memasuki status <Tanpa Pikiran> selama 2 giliran: meningkatkan Dodge 15% dan mendapatkan efek <Perbarui Diri> setiap akhir giliran (menghapus 1 debuff). Saat HP pertama kali turun di bawah 40%, juga mendapatkan status <Tanpa Bayangan> selama 2 giliran: meningkatkan Kecepatan 30% dan skill memberikan tambahan 15% true damage',
		describe_ph = 'Si Muichiro ay papasok sa estado ng <Walang Isip> sa loob ng 2 turn: tumataas ang Dodge ng 15% at nakakakuha ng epekto <Sariling Pagbago> sa pagtatapos ng bawat turn (nag-aalis ng 1 debuff). Kapag bumaba sa ilalim ng 40% ang HP sa unang pagkakataon, makakakuha din siya ng estado ng <Walang Anino> sa loob ng 2 turn: tumataas ang Bilis ng 30% at ang mga kasanayan ay magdudulot ng dagdag na 15% totoong pinsala',
		describe_ma = 'Muichiro memasuki status <Tanpa Fikiran> selama 2 giliran: meningkatkan Elak sebanyak 15% dan menerima efek <Pembaharuan Diri> pada setiap akhir giliran (menghapus 1 debuff). Apabila HP jatuh di bawah 40% untuk kali pertama, juga memperoleh status <Tanpa Bayangan> selama 2 giliran: meningkatkan Kelajuan sebanyak 30% dan kemahiran memberikan tambahan 15% kerosakan sebenar',
		describe = 'Muichiro enters <No Thought> state for 2 turns: increases Dodge by 15% and gains <Self-Renewal> effect at the end of each turn (removes 1 debuff). When HP drops below 40% for the first time, also gains <Shadowless> state for 2 turns: increases Speed by 30% and skills deal an additional 15% true damage',
		simDesc = 'Bắt đầu trận tăng Né tránh, mỗi lượt xóa 1 hiệu ứng bất lợi. Khi HP < 40%, tăng Tốc độ và gây thêm sát thương thực.',
		starEffect = __data_t__starEffect[80124],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Tinh thần chiến đấu Muichiro tập trung đến mức hoàn hảo, kích hoạt trạng thái <Song Thủ Hợp Nhất> mang lại cho hắn 30% thủ vật lí và 30% thủ P.Thuật.',
		starEffectDesc = 'Enhanced Effect: Muichiro’s fighting spirit reaches perfect focus, activating the <Dual Hands Unity> state, granting him 30% Physical Defense and 30% Magic Defense.',
		starEffectDesc_en = 'Enhanced Effect: Muichiro’s fighting spirit reaches perfect focus, activating the <Dual Hands Unity> state, granting him 30% Physical Defense and 30% Magic Defense.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: จิตวิญญาณการต่อสู้ของ Muichiro มีสมาธิถึงขีดสุด เปิดใช้งานสถานะ <สองมือรวมเป็นหนึ่ง> มอบพลังป้องกันกายภาพ 30% และพลังป้องกันเวท 30%',
		starEffectDesc_in = 'Efek Ditingkatkan: Semangat juang Muichiro mencapai fokus sempurna, mengaktifkan status <Penyatuan Dua Tangan> yang memberinya 30% Pertahanan Fisik dan 30% Pertahanan Sihir.',
		starEffectDesc_ph = 'Pinahusay na Epekto: Ang diwa ng pakikipaglaban ni Muichiro ay nagiging ganap na nakapokus, na nagpapagana ng estado <Pagsasanib ng Dalawang Kamay> na nagbibigay sa kanya ng 30% Physical Defense at 30% Magic Defense.',
		starEffectDesc_ma = 'Kesan Dipertingkat: Semangat juang Muichiro mencapai fokus sempurna, mengaktifkan keadaan <Penyatuan Dua Tangan> yang memberikannya 30% Pertahanan Fizikal dan 30% Pertahanan Sihir.',
