	[210212] = {
		id = 210212,
		skillName_vn = 'Đòn tấn công bóng',
		skillName_en = 'Shadow attack',
		skillName_th = 'การโจมตีเงา',
		skillName_in = 'Serangan bayangan',
		skillName_ph = 'Anino ng atake',
		skillName_ma = 'Serangan bayangan',
		skillName = 'Shadow attack',
		describe_vn = 'Giratina biến thành ma và di chuyển đến một mục tiêu địch để đánh lén, gây #C0xE69900#170% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B# tăng khả năng giảm sát thương của cột mình thêm 15% trong 2 lượt. Sau khi tấn công, bản thân nhận được 2 điểm ma\n#F20# \n#F40#[#L10#Origin Form#L0#], phạm vi tấn công thay đổi theo hàng và có thêm 80% xác suất [#L10#Ghost Fire#L0#] trong 2 lượt\n[#L10# Netherworld Wisp#L0#]: Hiệu ứng tiêu cực đặc biệt, chỉ có thể xua tan và không thể áp dụng. Trước khi mục tiêu di chuyển hoặc khi Netherworld Wisp bị xua tan, máu của mục tiêu sẽ bị giảm (12% lượng máu tối đa của Giratina) và 120 điểm thịnh nộ.',
		describe_en = 'Giratina transforms into a ghost and moves to an enemy target to perform a sneaky attack, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Physical Damage #C0x5B545B# and increasing Giratina\'s damage reduction ability by 15% for 2 turns. After attacking, Giratina gains 2 points of ma\n#F20# \n#F40#[#L10#Origin Form#L0#]. Its attack range changes by row and gains an additional 80% chance to apply [#L10#Ghost Fire#L0#] for 2 turns. \n[#L10# Netherworld Wisp#L0#]: A special negative effect that can only be dispelled and cannot be applied again. Before the target moves or when Netherworld Wisp is dispelled, the target\'s health is reduced by (12% of Giratina\'s max HP) and 120 points of rage.',
		describe_th = 'Giratina กลายร่างเป็นผีและเคลื่อนที่ไปยังเป้าหมายศัตรูเพื่อโจมตีแบบลอบโจมตี ทำความเสียหาย #C0xE69900#170% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# และเพิ่มความสามารถในการลดความเสียหายของตัวเองขึ้น 15% เป็นเวลา 2 เทิร์น หลังจากโจมตี ตัวเองจะได้รับ 2 แต้ม ma\n#F20# \n#F40#[#L10#Origin Form#L0#] ขอบเขตการโจมตีเปลี่ยนแปลงตามแถว และมีโอกาส 80% ที่จะเกิด [#L10#Ghost Fire#L0#] เป็นเวลา 2 เทิร์น \n[#L10# Netherworld Wisp#L0#]: ผลกระทบลบพิเศษ ไม่สามารถบังคับใช้ซ้ำได้และสามารถสลายได้เท่านั้น ก่อนที่เป้าหมายจะเคลื่อนที่หรือขณะที่ Netherworld Wisp ถูกสลาย พลังชีวิตของเป้าหมายจะลดลง (12% ของพลังชีวิตสูงสุดของ Giratina) และได้รับ 120 แต้มความโกรธ',
		describe_in = 'Giratina berubah menjadi hantu dan bergerak ke target musuh untuk melakukan serangan diam-diam, memberikan #C0xE69900#170% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Kerusakan Fisik #C0x5B545B# dan meningkatkan kemampuan pengurangan kerusakan dirinya sebesar 15% selama 2 giliran. Setelah menyerang, dirinya mendapatkan 2 poin ma\n#F20# \n#F40#[#L10#Origin Form#L0#]. Jangkauan serangan berubah berdasarkan baris dan mendapatkan tambahan 80% peluang untuk memberikan [#L10#Ghost Fire#L0#] selama 2 giliran. \n[#L10# Netherworld Wisp#L0#]: Efek negatif khusus yang hanya bisa dihilangkan dan tidak bisa diterapkan kembali. Sebelum target bergerak atau saat Netherworld Wisp dihilangkan, HP target akan berkurang (12% dari HP maksimum Giratina) dan 120 poin kemarahan.',
		describe_ph = 'Nagiging ghost si Giratina at lumilipat sa isang kalaban upang magsagawa ng palihim na atake, na nagdudulot ng #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Physical Damage #C0x5B545B# at pinapataas ang kakayahan sa pagpapababa ng pinsala ng sarili ng 15% sa loob ng 2 turn. Pagkatapos umatake, nakakakuha ito ng 2 points ng ma\n#F20# \n#F40#[#L10#Origin Form#L0#]. Nagbabago ang saklaw ng atake base sa hanay at may karagdagang 80% tsansa ng [#L10#Ghost Fire#L0#] sa loob ng 2 turn. \n[#L10# Netherworld Wisp#L0#]: Isang espesyal na negatibong epekto na maaari lamang ma-dispel at hindi maaaring ilapat muli. Bago gumalaw ang target o kapag na-dispel ang Netherworld Wisp, mababawasan ang buhay ng target ng (12% ng maximum HP ni Giratina) at 120 points ng galit.',
		describe_ma = 'Giratina berubah menjadi hantu dan bergerak ke sasaran musuh untuk menyerang secara mengejutkan, memberikan #C0xE69900#170% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Kerosakan Fizikal #C0x5B545B# dan meningkatkan keupayaan pengurangan kerosakan dirinya sebanyak 15% selama 2 pusingan. Selepas menyerang, dirinya memperoleh 2 mata ma\n#F20# \n#F40#[#L10#Origin Form#L0#]. Julat serangan berubah mengikut baris dan mendapat peluang tambahan 80% untuk [#L10#Ghost Fire#L0#] selama 2 pusingan. \n[#L10# Netherworld Wisp#L0#]: Kesan negatif khas yang hanya boleh dibuang dan tidak boleh digunakan semula. Sebelum sasaran bergerak atau apabila Netherworld Wisp dibuang, darah sasaran akan berkurang (12% daripada darah maksimum Giratina) dan 120 mata kemarahan.',
		describe = 'Giratina transforms into a ghost and moves to an enemy target to perform a sneaky attack, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Physical Damage #C0x5B545B# and increasing Giratina\'s damage reduction ability by 15% for 2 turns. After attacking, Giratina gains 2 points of ma\n#F20# \n#F40#[#L10#Origin Form#L0#]. Its attack range changes by row and gains an additional 80% chance to apply [#L10#Ghost Fire#L0#] for 2 turns. \n[#L10# Netherworld Wisp#L0#]: A special negative effect that can only be dispelled and cannot be applied again. Before the target moves or when Netherworld Wisp is dispelled, the target\'s health is reduced by (12% of Giratina\'s max HP) and 120 points of rage.',
		simDesc_vn = 'Kira Đế Tân biến hình thành bóng ma, di chuyển đến trước mục tiêu đơn lẻ của kẻ thù để tấn công lén, gây sát thương vật lý, đồng thời tăng giới hạn tức giận của mục tiêu và bản thân nhận điểm ma quái; trong trạng thái nguồn gốc, phạm vi tấn công chuyển thành hàng và có xác suất kèm theo hồn ma.',
		simDesc_en = 'Kira Đế Tân transforms into a phantom, moving to the enemy\'s single target for a stealth attack, dealing physical damage, while increasing the target\'s rage limit and gaining a ghost point for himself; in the origin state, the attack range changes to a row and has a chance to summon a ghost.',
		simDesc_th = 'คิระ เด เทียน แปลงร่างเป็นผีปอบ เคลื่อนที่ไปยังเป้าหมายเดี่ยวของศัตรูเพื่อโจมตีอย่างลับ ๆ สร้างความเสียหายทางกายภาพ พร้อมเพิ่มขีดจำกัดความโกรธของเป้าหมายและได้รับคะแนนวิญญาณ; ในสภาพแหล่งกำเนิด พิสัยโจมตีเปลี่ยนเป็นแถวและมีโอกาสดึงผีรับร่วมด้วย',
		simDesc_in = 'Kira Đế Tân berubah menjadi hantu, bergerak ke target tunggal musuh untuk serangan diam-diam, memberikan kerusakan fisik, sekaligus meningkatkan batas kemarahan target dan dirinya sendiri menerima poin hantu; dalam keadaan asal, jangkauan serangan berubah menjadi baris dan memiliki kemungkinan disertai hantu.',
		simDesc_ph = 'Si Kira Đế Tân ay nagbabago sa isang multo, lumalapit sa isang kalaban na target para sa isang lihim na pag-atake, na nagdudulot ng pisikal na pinsala, kasabay ng pagtaas ng limitasyon ng galit ng target at nakakakuha ng puntos ng multo para sa sarili; sa estado ng pinagmulan, ang saklaw ng pag-atake ay nagiging hanay at may pagkakataong may kasamang multo.',
		simDesc_ma = 'Kira Đế Tân berubah menjadi hantu, bergerak ke sasaran tunggal musuh untuk serangan pernicious, menyebabkan kerosakan fizikal, sekaligus meningkatkan had kemarahan sasaran dan dirinya sendiri menerima mata hantu; dalam keadaan asal, julat serangan berubah kepada barisan dan mempunyai kemungkinan disertai hantu.',
		simDesc = 'Kira Đế Tân transforms into a phantom, moving to the enemy\'s single target for a stealth attack, dealing physical damage, while increasing the target\'s rage limit and gaining a ghost point for himself; in the origin state, the attack range changes to a row and has a chance to summon a ghost.',
		upLvDesc = 'Fixed damage +192',
