	[210213] = {
		id = 210213,
		skillName_vn = 'Thế giới đảo ngược',
		skillName_en = 'Reverse world',
		skillName_th = 'โลกกลับด้าน',
		skillName_in = 'Dunia terbalik',
		skillName_ph = 'Baliktad na mundo',
		skillName_ma = 'Dunia terbalik',
		skillName = 'Reverse world',
		describe_vn = 'Giratina thức tỉnh từ vực thẳm, sau đó triệu hồi lối vào thế giới đảo ngược, hút các đơn vị hàng đầu của kẻ địch vào đó, gây #C0xE69900#230% Sát Thương Vật Lý#C0x5B545B#+$(ski llLevel*4*48)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, giảm cơn thịnh nộ của mục tiêu trúng đòn đi 250 điểm và nhận được 3 điểm ma sau khi tấn công\n#F20# \n#F40#Sau khi thực hiện chiêu thức đặc biệt, anh ta chuyển sang [#L10#Origin Form#L0#] trong 2 hiệp. Giới hạn trên của lượng máu của chính anh ta (chỉ tăng giới hạn trên), tốc độ và tỷ lệ kiểm soát tổng thể được tăng thêm 50% (không thể phân tán, chuyển giao hoặc sao chép). Chuyển sang chiêu thức đặc biệt mới (không cần nộ và không tiêu hao nộ khi phóng ra, hồi lại trong 2 lượt sau khi phóng): Phạm vi thay đổi đối với tất cả kẻ địch và có thêm 75% xác suất thêm [#L10#鬼鬼火#L0#] vào 4 tướng địch có nộ cao nhất trong 2 lượt.',
		describe_en = 'Giratina awakens from the abyss, then summons the entrance to the reverse world, pulling in the enemy\'s frontline units, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, reducing the target\'s rage by 250 points upon hit, and gaining 3 mana points after attacking\n#F20# \n#F40#After performing the special move, he shifts to [#L10#Origin Form#L0#] for 2 turns. His maximum health limit (only the upper limit increases), speed, and overall control rate are increased by 50% (cannot be dispelled, transferred, or copied). Switches to a new special move (no rage required and no rage consumed when launched, recovers in 2 turns after launching): Range changes to all enemies and adds a 75% chance to apply [#L10#鬼鬼火#L0#] to the 4 enemy generals with the highest rage for 2 turns.',
		describe_th = 'กิราติน่าตื่นขึ้นจากเหวลึก จากนั้นเรียกทางเข้าของโลกกลับด้าน ดึงหน่วยแนวหน้าแห่งศัตรูเข้ามา สร้างความเสียหายทางกายภาพ #C0xE69900#230%#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# และลดความโกรธของเป้าหมายที่โดนโจมตีลง 250 แต้ม พร้อมได้รับพลังวิญญาณ 3 แต้มหลังโจมตี\n#F20# \n#F40# หลังจากใช้ท่าไม้ตาย เขาจะเปลี่ยนเป็น [#L10#Origin Form#L0#] เป็นเวลา 2 เทิร์น ขีดจำกัดเลือดสูงสุดของเขา (เพิ่มเพียงขีดจำกัดบน) ความเร็ว และอัตราการควบคุมโดยรวมเพิ่มขึ้น 50% (ไม่สามารถลบ โอน หรือคัดลอกได้) เปลี่ยนไปใช้ท่าไม้ตายใหม่ (ไม่ต้องใช้โกรธและไม่ใช้โกรธเมื่อโจมตี ฟื้นฟูใน 2 เทิร์นหลังโจมตี): พิสัยเปลี่ยนเป็นศัตรูทั้งหมด และมีโอกาส 75% ที่จะเพิ่ม [#L10#鬼鬼火#L0#] ให้กับ 4 ผู้บัญชาการศัตรูที่มีความโกรธสูงสุดเป็นเวลา 2 เทิร์น',
		describe_in = 'Giratina bangkit dari jurang, kemudian memanggil pintu masuk ke dunia terbalik, menarik unit depan musuh ke sana, memberikan #C0xE69900#230% Damage Fisik#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Damage Fisik #C0x5B545B#, mengurangi amarah target yang terkena sebanyak 250 poin dan mendapatkan 3 poin mana setelah menyerang\n#F20# \n#F40#Setelah melakukan jurus khusus, dia berubah ke [#L10#Origin Form#L0#] selama 2 giliran. Batas atas HP-nya (hanya meningkatkan batas atas), kecepatan, dan tingkat kontrol keseluruhan meningkat sebesar 50% (tidak dapat dibersihkan, dialihkan, atau disalin). Beralih ke jurus khusus baru (tidak perlu amarah dan tidak mengonsumsi amarah saat diluncurkan, pulih dalam 2 giliran setelah diluncurkan): Jangkauan berubah ke semua musuh dan memiliki 75% peluang menambahkan [#L10#鬼鬼火#L0#] ke 4 jenderal musuh dengan amarah tertinggi selama 2 giliran.',
		describe_ph = 'Nagising si Giratina mula sa kailaliman, pagkatapos ay tinawag ang daan papunta sa reverse world, hinihila ang mga nangungunang yunit ng kalaban doon, nagdudulot ng #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, nagpapababa ng galit ng target na tinamaan ng 250 puntos at nakakakuha ng 3 mana points pagkatapos umatake\n#F20# \n#F40#Pagkatapos gawin ang special move, siya ay magpapalit sa [#L10#Origin Form#L0#] sa loob ng 2 turno. Ang maximum HP limit niya (tumaas lamang ang upper limit), bilis, at kabuuang control rate ay tumataas ng 50% (hindi matatanggal, maililipat, o mako-copy). Lumilipat sa bagong special move (hindi kailangan ng galit at hindi gumagamit ng galit kapag inilunsad, bumabalik sa 2 turno pagkatapos lumunsad): Nagbabago ang saklaw sa lahat ng kalaban at may karagdagang 75% tsansa na maglagay ng [#L10#鬼鬼火#L0#] sa 4 na kalabang heneral na may pinakamataas na galit sa loob ng 2 turno.',
		describe_ma = 'Giratina terjaga dari jurang, kemudian memanggil pintu masuk ke dunia songsang, menarik unit barisan hadapan musuh ke dalamnya, menyebabkan #C0xE69900#230% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, mengurangkan kemarahan sasaran yang terkena sebanyak 250 mata dan memperoleh 3 mata mana selepas menyerang\n#F20# \n#F40#Selepas melakukan serangan khas, dia bertukar kepada [#L10#Origin Form#L0#] selama 2 pusingan. Had atas kesihatan maksimum dirinya (hanya had atas yang meningkat), kelajuan dan kadar kawalan keseluruhan meningkat sebanyak 50% (tidak boleh dialih keluar, dipindahkan atau disalin). Beralih kepada serangan khas baru (tidak memerlukan kemarahan dan tidak menggunakan kemarahan semasa dilancarkan, pulih dalam 2 pusingan selepas pelancaran): Julat berubah kepada semua musuh dan mempunyai 75% peluang untuk menambah [#L10#鬼鬼火#L0#] pada 4 jeneral musuh tertinggi kemarahannya selama 2 pusingan.',
		describe = 'Giratina awakens from the abyss, then summons the entrance to the reverse world, pulling in the enemy\'s frontline units, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, reducing the target\'s rage by 250 points upon hit, and gaining 3 mana points after attacking\n#F20# \n#F40#After performing the special move, he shifts to [#L10#Origin Form#L0#] for 2 turns. His maximum health limit (only the upper limit increases), speed, and overall control rate are increased by 50% (cannot be dispelled, transferred, or copied). Switches to a new special move (no rage required and no rage consumed when launched, recovers in 2 turns after launching): Range changes to all enemies and adds a 75% chance to apply [#L10#鬼鬼火#L0#] to the 4 enemy generals with the highest rage for 2 turns.',
		simDesc_vn = 'Kira Đế Tân từ vực sâu tỉnh dậy, sau đó triệu hồi cổng vào thế giới đảo ngược, hút các đơn vị kẻ thù ở hàng trước vào trong đó, gây sát thương vật lý, giảm giá trị tức giận của chúng và hồi phục điểm ma quái; sau đó, hầu hết thuộc tính sẽ được nâng cấp chuyển sang trạng thái nguồn gốc; trong trạng thái nguồn gốc, phạm vi tấn công chuyển thành toàn bộ và có xác suất rất cao kèm theo hồn ma.',
		simDesc_en = 'Kira Emperor Xin awakens from the abyss, then summons a portal to the inverted world, pulling enemy units in the front row into it, dealing physical damage, reducing their rage value, and restoring demon points; afterwards, most attributes will be upgraded to the origin state; in the origin state, the attack range changes to entire area with a very high chance accompanied by spirits.',
		simDesc_th = 'กิร่า เอ็มเพอเรอร์ ซิน ฟื้นขึ้นจากห้วงลึก จากนั้นเรียกประตูสู่โลกกลับด้าน ดูดหน่วยศัตรูแถวหน้ามาในนั้น สร้างความเสียหายกายภาพ ลดค่าความโกรธของพวกมัน และฟื้นฟูพลังปีศาจ; จากนั้นคุณสมบัติส่วนใหญ่จะถูกอัปเกรดเป็นสถานะต้นกำเนิด; ในสถานะต้นกำเนิด ช่วงการโจมตีจะเปลี่ยนเป็นทั้งพื้นที่และมีโอกาสสูงมากพร้อมกับวิญญาณ',
		simDesc_in = 'Kira Kaisar Xin bangkit dari jurang, kemudian memanggil portal ke dunia terbalik, menarik unit musuh di barisan depan ke dalamnya, menyebabkan kerusakan fisik, mengurangi nilai kemarahan mereka, dan memulihkan poin demon; setelah itu, sebagian besar atribut akan ditingkatkan ke status asal; dalam status asal, jangkauan serangan berubah menjadi seluruh area dengan peluang sangat tinggi disertai roh.',
		simDesc_ph = 'Nagising si Kira Emperor Xin mula sa kailaliman, pagkatapos ay nag-summon ng portal papunta sa inverted world, hinihila ang mga kalaban sa front row papunta dito, nagdudulot ng pisikal na pinsala, nagpapababa ng kanilang halaga ng galit, at nagpapagaling ng demon points; pagkatapos, karamihan sa mga katangian ay ia-upgrade sa origin state; sa origin state, ang saklaw ng pag-atake ay nagiging buong area na may napakataas na pagkakataon na may kasamang mga espiritu.',
		simDesc_ma = 'Kira Maharaja Xin bangun dari jurang, kemudian memanggil pintu masuk ke dunia terbalik, menarik unit musuh di barisan depan ke dalamnya, menyebabkan kerosakan fizikal, mengurangkan nilai kemarahan mereka, dan memulihkan mata demon; selepas itu, kebanyakan atribut akan dinaik taraf ke keadaan asal; dalam keadaan asal, julat serangan berubah menjadi keseluruhan dengan kebarangkalian yang sangat tinggi disertai roh.',
		simDesc = 'Kira Emperor Xin awakens from the abyss, then summons a portal to the inverted world, pulling enemy units in the front row into it, dealing physical damage, reducing their rage value, and restoring demon points; afterwards, most attributes will be upgraded to the origin state; in the origin state, the attack range changes to entire area with a very high chance accompanied by spirits.',
		starEffect = __data_t__starEffect[210213],
		-- {11}
		starEffectDesc_vn = 'Kỹ năng chí mạng hình thái khác sẽ đảo ngược toàn bộ thế giới kéo dài 3 lượt: giảm tốc độ hồi phục tức giận của toàn bộ địch 15%; số lượt duy trì của hình thái nguồn gốc +1',
		starEffectDesc = 'Different form critical skill will invert the entire world for 3 turns: reduce all enemies\' anger recovery speed by 15%; origin form\'s duration +1',
		starEffectDesc_en = 'Different form critical skill will invert the entire world for 3 turns: reduce all enemies\' anger recovery speed by 15%; origin form\'s duration +1',
		starEffectDesc_th = 'ทักษะคริติคัลรูปร่างต่างจะทำให้โลกทั้งใบกลับด้านเป็นเวลา 3 เทิร์น: ลดความเร็วฟื้นฟูความโกรธของศัตรูทั้งหมดลง 15%; ระยะเวลารูปร่างต้นกำเนิด +1',
		starEffectDesc_in = 'Skill kritis bentuk berbeda akan membalik seluruh dunia selama 3 giliran: mengurangi kecepatan pemulihan amarah musuh sebesar 15%; durasi bentuk asal +1',
		starEffectDesc_ph = 'Ang iba’t ibang anyo ng kritikal na kasanayan ay mag-iinvert ng buong mundo sa loob ng 3 turn: bawasan ang bilis ng pagbawi ng galit ng lahat ng kalaban ng 15%; dagdagan ng 1 ang tagal ng anyo ng pinagmulan',
		starEffectDesc_ma = 'Kemahiran kritikal bentuk berbeza akan memutar balikkan seluruh dunia selama 3 pusingan: mengurangkan kelajuan pulih kemarahan semua musuh sebanyak 15%; tempoh bentuk asal +1',
		upLvDesc = 'Fixed damage +192',
