	[210216] = {
		id = 210216,
		skillName_vn = 'Bóng ma dày đặc',
		skillName_en = 'Dense ghost',
		skillName_th = 'ผีหนาแน่น',
		skillName_in = 'Hantu yang padat',
		skillName_ph = 'Mabangis na multo',
		skillName_ma = 'Hantu tebal',
		skillName = 'Dense ghost',
		describe_vn = 'Khi Giratio bước vào hiện trường, anh ta sẽ nhận được số lượng hồn ma của các anh hùng trong trại của mình ngoài chính mình (giới hạn trên của số lượng ma: 5 điểm, không thể xua tan hoặc bỏ qua), và mỗi hồn ma có thể giảm số lượng hồn ma của mình #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# Sát thương cuối cùng nhận được sẽ giảm 1 hồn ma mỗi khi trúng đòn. Khi bóng ma giảm đi, 80 điểm thịnh nộ sẽ được phục hồi\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn, bạn và anh hùng có phần trăm máu thấp nhất ở hàng sau trong đội của bạn sẽ nhận được [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: lượng khiên bằng 15% máu tối đa của Giratina. , không thể chồng lên, mục tiêu tấn công khiên ma sẽ yếu: đòn tấn công kép giảm 15% trong 2 lượt); khi chuyển sang dạng gốc, 30% lượng HP đã mất có thể được phục hồi (không bị ảnh hưởng bởi phương pháp điều trị bị cấm) và bản thân sẽ không tái sinh khi tấn công ở dạng gốc.',
		describe_en = 'When Giratio enters the scene, he will receive the number of souls of the heroes in his camp besides himself (upper limit of souls: 5 points, cannot be dispelled or ignored), and each soul can reduce his own soul count by #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. The final damage received will reduce one soul each time he is hit. When the ghost fades, 80 rage points will be recovered \n#F20# \n#F40#. At the start of each major round, you and the hero with the lowest HP in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: shield amount equals 15% of Giratina\'s max HP, cannot be stacked, targets of the ghost shield will be weakened: double attacks reduce by 15% for 2 turns); when switching to original form, 30% of the lost HP can be restored (not affected by prohibited healing methods) and Giratio himself will not resurrect when attacking in original form.',
		describe_th = 'เมื่อ Giratio เข้าสู่สนาม เขาจะได้รับจำนวนวิญญาณของฮีโร่ในค่ายของเขานอกเหนือจากตัวเอง (จำนวนวิญญาณสูงสุด: 5 แต้ม ไม่สามารถขจัดหรือเพิกเฉยได้) และวิญญาณแต่ละดวงสามารถลดจำนวนวิญญาณของเขาเองได้ #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# ความเสียหายสุดท้ายที่ได้รับจะทำให้วิญญาณลดลง 1 ดวงทุกครั้งที่ถูกโจมตี เมื่อวิญญาณลดลง จะฟื้นฟูพลังโกรธ 80 แต้ม \n#F20# \n#F40# เมื่อเริ่มแต่ละรอบใหญ่ คุณและฮีโร่ที่มี HP ต่ำที่สุดในแถวหลังของทีมจะได้รับ [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: เกราะเท่ากับ 15% ของ HP สูงสุดของ Giratina ไม่สามารถซ้อนทับได้ เป้าหมายที่ได้รับเกราะผีจะอ่อนแอลง: การโจมตีคู่ลดลง 15% เป็นเวลา 2 เทิร์น); เมื่อเปลี่ยนเป็นรูปแบบดั้งเดิม จะสามารถฟื้นฟู HP ที่สูญเสียไป 30% (ไม่ถูกกระทบโดยวิธีการรักษาที่ถูกห้าม) และตัวเองจะไม่เกิดใหม่เมื่อโจมตีในรูปแบบดั้งเดิม',
		describe_in = 'Ketika Giratio memasuki medan pertarungan, ia akan menerima jumlah jiwa para pahlawan di perkemahannya selain dirinya sendiri (batas atas jumlah jiwa: 5 poin, tidak dapat dihapus atau diabaikan), dan setiap jiwa dapat mengurangi jumlah jiwanya sendiri sebesar #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Kerusakan terakhir yang diterima akan mengurangi satu jiwa setiap kali terkena serangan. Ketika bayangan hantu berkurang, 80 poin amarah akan dipulihkan \n#F20# \n#F40#. Pada awal setiap ronde besar, kamu dan pahlawan dengan HP terendah di barisan belakang timmu akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: jumlah perisai sebesar 15% dari HP maksimum Giratina, tidak dapat ditumpuk, target yang dilindungi oleh perisai hantu akan melemah: serangan ganda berkurang 15% selama 2 giliran); saat beralih ke bentuk asli, 30% dari HP yang hilang dapat dipulihkan (tidak terpengaruh oleh metode penyembuhan yang dilarang) dan dirinya sendiri tidak akan bereinkarnasi saat menyerang dalam bentuk asli.',
		describe_ph = 'Kapag pumasok si Giratio sa lugar ng labanan, tatanggap siya ng bilang ng mga kaluluwa ng mga bayani sa kanyang kampo bukod sa kanyang sarili (pinakamataas na bilang ng kaluluwa: 5 puntos, hindi maaaring i-disperse o balewalain), at bawat kaluluwa ay maaaring magpababa ng kanyang sariling bilang ng kaluluwa ng #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Ang huling tinanggap na pinsala ay magbabawas ng isang kaluluwa sa bawat pagkatamaan. Kapag nabawasan ang multo, 80 puntos ng galit ang mababawi \n#F20# \n#F40#. Sa simula ng bawat malaking round, ikaw at ang bayani na may pinakamababang porsyento ng HP sa likurang hanay ng iyong koponan ay makakatanggap ng [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: kalasag na katumbas ng 15% ng max HP ni Giratina, hindi maaaring ipatong, ang target ng kalasag ng multo ay magiging mahina: doble ang pag-atake ay bumaba ng 15% sa loob ng 2 turn); kapag lumipat sa orihinal na anyo, 30% ng nawalang HP ay maaaring maibalik (hindi naaapektuhan ng mga ipinagbabawal na paraan ng paggagamot) at hindi muling mabubuhay si Giratio kapag umaatake sa orihinal na anyo.',
		describe_ma = 'Apabila Giratio memasuki medan, dia akan menerima bilangan roh wira di kemahnya selain dirinya sendiri (had atas bilangan roh: 5 mata, tidak boleh dihapus atau diabaikan), dan setiap roh boleh mengurangkan bilangan rohnya sendiri sebanyak #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Kerosakan terakhir yang diterima akan mengurangkan satu roh setiap kali terkena serangan. Apabila bayangan roh berkurang, 80 mata kemarahan akan dipulihkan \n#F20# \n#F40#. Pada permulaan setiap pusingan besar, anda dan wira yang mempunyai peratusan darah terendah di barisan belakang dalam pasukan anda akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: jumlah perisai bersamaan 15% darah maksimum Giratina, tidak boleh bertindan, sasaran yang diserang oleh perisai roh akan menjadi lemah: serangan berganda berkurang 15% selama 2 giliran); apabila bertukar ke bentuk asal, 30% daripada darah yang hilang boleh dipulihkan (tidak terjejas oleh kaedah rawatan yang dilarang) dan dirinya sendiri tidak akan bangkit semula ketika menyerang dalam bentuk asal.',
		describe = 'When Giratio enters the scene, he will receive the number of souls of the heroes in his camp besides himself (upper limit of souls: 5 points, cannot be dispelled or ignored), and each soul can reduce his own soul count by #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. The final damage received will reduce one soul each time he is hit. When the ghost fades, 80 rage points will be recovered \n#F20# \n#F40#. At the start of each major round, you and the hero with the lowest HP in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: shield amount equals 15% of Giratina\'s max HP, cannot be stacked, targets of the ghost shield will be weakened: double attacks reduce by 15% for 2 turns); when switching to original form, 30% of the lost HP can be restored (not affected by prohibited healing methods) and Giratio himself will not resurrect when attacking in original form.',
		starEffect = __data_t__starEffect[210216],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Quỷ khiên nâng cấp: tăng 5% lượng khiên, mỗi lượt lớn kết thúc bản thân nhận 1 điểm Quỷ ảnh',
		starEffectDesc = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
