	[210217] = {
		id = 210217,
		skillName_vn = 'Bị động',
		skillName_en = 'Passive',
		skillName_th = 'ถูกกระทำ',
		skillName_in = 'Pasif',
		skillName_ph = 'Passive',
		skillName_ma = 'Pasif',
		skillName = 'Passive',
		describe_vn = 'Khi Giratio bước vào hiện trường, anh ta sẽ nhận được số lượng hồn ma của các anh hùng trong trại của mình ngoài chính mình (giới hạn trên của số lượng ma: 5 điểm, không thể xua tan hoặc bỏ qua), và mỗi hồn ma có thể giảm số lượng hồn ma của mình #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# Sát thương cuối cùng nhận được sẽ giảm 1 hồn ma mỗi khi trúng đòn. Khi bóng ma giảm đi, 80 điểm thịnh nộ sẽ được phục hồi\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn, bạn và anh hùng có phần trăm máu thấp nhất ở hàng sau trong đội của bạn sẽ nhận được [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: lượng khiên bằng 15% máu tối đa của Giratina. , không thể chồng lên, mục tiêu tấn công khiên ma sẽ yếu: đòn tấn công kép giảm 15% trong 2 lượt); khi chuyển sang dạng gốc, 30% lượng HP đã mất có thể được phục hồi (không bị ảnh hưởng bởi phương pháp điều trị bị cấm) và bản thân sẽ không tái sinh khi tấn công ở dạng gốc.',
		describe_en = 'When Giratio enters the battlefield, he will receive the number of ghosts of the heroes in his camp besides himself (maximum ghost limit: 5 points, cannot be dispelled or ignored), and each ghost can reduce his own ghost count by #(4 + s killLevel * 0.04 - 0.04)%#. The final damage received will reduce one ghost each time he is hit. When a ghost is lost, 80 rage points will be restored. At the start of each major round, you and the hero with the lowest percentage health in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: a shield equal to 15% of Giratio\'s max health, cannot stack, targets attacking the ghost shield will be weakened: dual attacks are reduced by 15% for 2 turns); when switching to the original form, 30% of the lost HP can be recovered (not affected by banned treatment methods) and he will not resurrect when attacking in original form.',
		describe_th = 'เมื่อ Giratio เข้าสู่สนามรบ เขาจะได้รับจำนวนผีของฮีโร่ในค่ายของเขานอกจากตัวเขาเอง (จำกัดจำนวนผีสูงสุด: 5 คะแนน ไม่สามารถลบล้างหรือเพิกเฉยได้) และผีแต่ละตัวสามารถลดจำนวนผีของเขาเองได้ #(4 + ระดับการฆ่า * 0.04 - 0.04)%# ความเสียหายสุดท้ายที่ได้รับจะทำให้เสียผีหนึ่งตัวทุกครั้งที่ถูกโจมตี เมื่อผีลดลง จะได้รับคืน 80 คะแนนความโกรธ เมื่อเริ่มแต่ละรอบใหญ่ คุณและฮีโร่ที่มีเปอร์เซ็นต์เลือดต่ำที่สุดในแถวหลังของทีมจะได้รับ [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: โล่เท่ากับ 15% ของเลือดสูงสุดของ Giratio ไม่สามารถซ้อนทับได้ เป้าหมายที่โจมตีโล่ผีจะถูกอ่อนแอลง: การโจมตีคู่ลดลง 15% ใน 2 เทิร์น); เมื่อเปลี่ยนเป็นรูปแบบดั้งเดิม จะสามารถฟื้นฟูได้ 30% ของ HP ที่สูญเสียไป (ไม่ถูกผลกระทบจากวิธีการรักษาที่ถูกห้าม) และตัวละครจะไม่ฟื้นคืนชีพเมื่อโจมตีในรูปแบบดั้งเดิม',
		describe_in = 'Ketika Giratio memasuki medan tempur, ia akan menerima jumlah hantu para pahlawan di kampnya selain dirinya sendiri (batas atas jumlah hantu: 5 poin, tidak dapat disingkirkan atau diabaikan), dan setiap hantu dapat mengurangi jumlah hantunya sendiri sebesar #(4 + level kill * 0.04 - 0.04)%#. Kerusakan terakhir yang diterima akan mengurangi satu hantu setiap kali terkena serangan. Ketika hantu hilang, 80 poin amarah akan dipulihkan. Pada awal setiap ronde besar, kamu dan pahlawan dengan persentase HP terendah di barisan belakang timmu akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: perisai sebesar 15% dari HP maksimal Giratio, tidak dapat ditumpuk, target yang menyerang perisai hantu akan melemah: serangan ganda berkurang 15% selama 2 giliran); ketika beralih ke bentuk asli, 30% dari HP yang hilang dapat dipulihkan (tidak terpengaruh oleh metode penyembuhan yang dilarang) dan dia tidak akan bangkit kembali saat menyerang dalam bentuk asli.',
		describe_ph = 'Kapag pumasok si Giratio sa laban, matatanggap niya ang bilang ng mga multo ng mga bayani sa kanyang kampo bukod sa kanyang sarili (pinakamataas na limitasyon ng bilang ng mga multo: 5 puntos, hindi maaaring alisin o balewalain), at bawat multo ay maaaring bawasan ang kanyang sariling bilang ng mga multo ng #(4 + killLevel * 0.04 - 0.04)%#. Ang huling pinsalang tatanggapin ay magbabawas ng isang multo sa bawat beses na tamaan. Kapag nabawasan ang mga multo, makakabawi siya ng 80 puntos ng galit. Sa pagsisimula ng bawat pangunahing round, ikaw at ang bayani na may pinakamababang porsyento ng HP sa likurang hanay ng iyong koponan ay makakatanggap ng [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: isang kalasag na katumbas ng 15% ng maximum na HP ni Giratio, hindi mapagsasama, ang target na umatake sa ghost shield ay magiging mahina: ang dobleng atake ay mababawasan ng 15% sa loob ng 2 turn); kapag lumipat sa orihinal na anyo, 30% ng nawalang HP ay maaaring mabawi (hindi naaapektuhan ng mga ipinagbabawal na paraan ng paggamot) at hindi siya muling magbabangon kapag umatake sa orihinal na anyo.',
		describe_ma = 'Apabila Giratio memasuki medan pertempuran, dia akan menerima jumlah hantu wira dalam kem pangnya selain dirinya sendiri (had atas jumlah hantu: 5 mata, tidak boleh dihapus atau diabaikan), dan setiap hantu boleh mengurangkan bilangan hantunya sendiri sebanyak #(4 + tahap kill * 0.04 - 0.04)%#. Kerosakan terakhir yang diterima akan mengurangkan satu hantu setiap kali terkena serangan. Apabila hantu berkurang, 80 mata kemarahan akan dipulihkan. Pada permulaan setiap pusingan besar, anda dan wira dengan peratusan darah terendah di barisan belakang dalam pasukan anda akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: perisai bersamaan 15% darah maksimum Giratio, tidak boleh bertindih, sasaran yang menyerang perisai hantu akan menjadi lemah: serangan berganda dikurangkan sebanyak 15% selama 2 pusingan); apabila bertukar ke bentuk asal, 30% daripada HP yang hilang boleh dipulihkan (tidak terjejas oleh kaedah rawatan dilarang) dan dia tidak akan hidup semula ketika menyerang dalam bentuk asal.',
		describe = 'When Giratio enters the battlefield, he will receive the number of ghosts of the heroes in his camp besides himself (maximum ghost limit: 5 points, cannot be dispelled or ignored), and each ghost can reduce his own ghost count by #(4 + s killLevel * 0.04 - 0.04)%#. The final damage received will reduce one ghost each time he is hit. When a ghost is lost, 80 rage points will be restored. At the start of each major round, you and the hero with the lowest percentage health in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: a shield equal to 15% of Giratio\'s max health, cannot stack, targets attacking the ghost shield will be weakened: dual attacks are reduced by 15% for 2 turns); when switching to the original form, 30% of the lost HP can be recovered (not affected by banned treatment methods) and he will not resurrect when attacking in original form.',
		starEffect = __data_t__starEffect[210217],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Quỷ khiên nâng cấp: tăng 5% lượng khiên, mỗi lượt lớn kết thúc bản thân nhận 1 điểm Quỷ ảnh',
		starEffectDesc = 'Demon Shield upgrade effect: increases shield amount by 5%, at the end of each big turn, the user receives 1 Demon Shadow point',
