	[210223] = {
		id = 210223,
		skillName_vn = 'Thế giới đảo ngược',
		skillName_en = 'The Reverse World',
		skillName_th = 'โลกกลับหัว',
		skillName_in = 'Dunia Terbalik',
		skillName_ph = 'Ang Baliktarang Mundo',
		skillName_ma = 'Dunia Terbalik',
		skillName = 'The Reverse World',
		describe_vn = 'Giratina một lần nữa triệu hồi lối vào thế giới ngược để đẩy toàn bộ đơn vị địch xuống vực thẳm vô tận, gây #C0xE69900#230% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, giảm cơn thịnh nộ của mục tiêu trúng đòn 250 điểm và nhận 3 điểm ma sau đó tấn công\n#F20# \n#F40#Sau khi thực hiện chiêu thức đặc biệt, anh ta chuyển sang [#L10#Origin Form#L0#] trong 2 hiệp. Giới hạn trên của lượng máu của chính anh ta (chỉ tăng giới hạn trên), tốc độ và tỷ lệ kiểm soát tổng thể được tăng thêm 50% (không thể phân tán, chuyển giao hoặc sao chép). Chuyển sang chiêu thức đặc biệt mới (không cần nộ và không tiêu hao nộ khi phóng ra, hồi lại trong 2 lượt sau khi phóng): Phạm vi thay đổi đối với tất cả kẻ địch và có thêm 75% xác suất thêm [#L10#鬼鬼火#L0#] vào 4 tướng địch có nộ cao nhất trong 2 lượt.',
		describe_en = 'Giratina once again summons an entrance to the inverted world to push all enemy units into an endless abyss, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, reducing the target\'s rage by 250 points and gaining 3 demon points. Then attacks \n#F20# \n#F40#. After performing the special move, he shifts into [#L10#Origin Form#L0#] for 2 turns. His maximum HP limit (only increases the limit), speed, and overall control rate are increased by 50% (cannot be dispersed, transferred, or copied). Switches to a new special move (no rage required and no rage consumed when activated, recovers in 2 turns after activation): range changes to all enemies and gains a 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy units with the highest rage for 2 turns.',
		describe_th = 'Giratina เรียกประตูสู่โลกกลับหัวอีกครั้งเพื่อผลักหน่วยศัตรูทั้งหมดลงสู่หุบเหวนิรันดร์ ส่งผลให้เกิด #C0xE69900#230% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ลดความโกรธของเป้าหมายลง 250 แต้ม และได้รับ 3 คะแนนปีศาจ จากนั้นโจมตี \n#F20# \n#F40# หลังจากใช้ท่าไม้ตาย เขาจะเปลี่ยนเป็น [#L10#Origin Form#L0#] เป็นเวลา 2 เทิร์น ขีดจำกัดสูงสุดของพลังชีวิตของเขา (เพิ่มเพียงขีดจำกัด) ความเร็ว และอัตราการควบคุมโดยรวมเพิ่มขึ้น 50% (ไม่สามารถถูกกระจาย โอนไป หรือคัดลอกได้) เปลี่ยนไปใช้ท่าไม้ตายใหม่ (ไม่ต้องใช้ความโกรธและไม่ใช้ความโกรธเมื่อปล่อย ท่าไม้ตายจะฟื้นฟูใน 2 เทิร์นหลังจากใช้): พิสัยเปลี่ยนเป็นศัตรูทั้งหมด และมีโอกาส 75% ที่จะเพิ่ม [#L10#鬼鬼火#L0#] ให้กับ 4 นายทัพศัตรูที่มีความโกรธสูงสุดเป็นเวลา 2 เทิร์น',
		describe_in = 'Giratina sekali lagi memanggil pintu ke dunia terbalik untuk mendorong seluruh unit musuh ke jurang tanpa akhir, menyebabkan #C0xE69900#230% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, mengurangi kemarahan target sebesar 250 poin dan mendapatkan 3 poin iblis kemudian menyerang \n#F20# \n#F40#. Setelah melakukan gerakan khusus, ia beralih ke [#L10#Origin Form#L0#] selama 2 giliran. Batas atas HP-nya (hanya menaikkan batas), kecepatan, dan tingkat kontrol keseluruhan meningkat sebesar 50% (tidak dapat disebarkan, dialihkan, atau disalin). Beralih ke gerakan khusus baru (tidak perlu kemarahan dan tidak menghabiskan kemarahan saat digunakan, pulih dalam 2 giliran setelah digunakan): jangkauan berubah ke semua musuh dan memiliki 75% peluang menambahkan [#L10#鬼鬼火#L0#] ke 4 unit musuh dengan kemarahan tertinggi selama 2 giliran.',
		describe_ph = 'Minsan muling tinatawag ni Giratina ang daan patungo sa baliktad na mundo upang itulak lahat ng kalabang yunit sa walang katapusang hukay, na nagdudulot ng #C0xE69900#230% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, binabawasan ang galit ng target ng 250 puntos at nakakakuha ng 3 demonic points, pagkatapos ay umaatake \n#F20# \n#F40#. Pagkatapos gawin ang espesyal na galaw, siya ay nagbabago sa [#L10#Origin Form#L0#] sa loob ng 2 turn. Ang pinakamataas na limitasyon ng kanyang HP (tanging tumataas ang limitasyon), bilis, at pangkalahatang kontrol ay tumaas ng 50% (hindi maaaring ipamahagi, ilipat, o kopyahin). Nagpalit sa bagong espesyal na galaw (hindi nangangailangan ng galit at hindi kumukunsumo ng galit kapag inilunsad, bumabalik sa loob ng 2 turn pagkatapos ilunsad): nagbabago ang saklaw sa lahat ng kalaban at may 75% pagkakataon na magdagdag ng [#L10#鬼鬼火#L0#] sa 4 na kalabang yunit na may pinakamataas na galit sa loob ng 2 turn.',
		describe_ma = 'Giratina sekali lagi memanggil pintu ke dunia terbalik untuk menolak semua unit musuh ke dalam jurang tanpa akhir, menyebabkan #C0xE69900#230% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, mengurangkan kemarahan sasaran sebanyak 250 mata dan menerima 3 mata syaitan kemudian menyerang \n#F20# \n#F40#. Selepas melakukan serangan khas, dia bertukar ke [#L10#Origin Form#L0#] selama 2 pusingan. Had atas HPnya (hanya meningkatkan had), kelajuan dan kadar kawalan keseluruhan ditingkatkan sebanyak 50% (tidak boleh diagihkan, dipindahkan atau disalin). Beralih ke serangan khas baru (tidak memerlukan kemarahan dan tidak menggunakan kemarahan semasa dilancarkan, pulih semula dalam 2 pusingan selepas dilancarkan): julat berubah ke semua musuh dan mempunyai 75% peluang untuk menambahkan [#L10#鬼鬼火#L0#] kepada 4 wira musuh yang mempunyai kemarahan tertinggi selama 2 pusingan.',
		describe = 'Giratina once again summons an entrance to the inverted world to push all enemy units into an endless abyss, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, reducing the target\'s rage by 250 points and gaining 3 demon points. Then attacks \n#F20# \n#F40#. After performing the special move, he shifts into [#L10#Origin Form#L0#] for 2 turns. His maximum HP limit (only increases the limit), speed, and overall control rate are increased by 50% (cannot be dispersed, transferred, or copied). Switches to a new special move (no rage required and no rage consumed when activated, recovers in 2 turns after activation): range changes to all enemies and gains a 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy units with the highest rage for 2 turns.',
		simDesc_vn = 'Kira Đế Tân một lần nữa triệu hồi cổng vào thế giới đảo ngược, khiến toàn bộ đơn vị kẻ thù rơi vào vực sâu vô tận, gây sát thương vật lý, giảm giá trị tức giận của chúng và có xác suất rất cao kèm theo hồn ma.',
		simDesc_en = 'Kira The Emperor Xin once again summons the gateway to the reversed world, causing all enemy units to fall into an endless abyss, dealing physical damage, reducing their anger value, and having a very high chance to inflict a ghost spirit.',
		simDesc_th = 'Kira จักรพรรดิซินได้เรียกประตูสู่โลกกลับด้านอีกครั้ง ทำให้หน่วยศัตรูทั้งหมดตกลงสู่หุบเหวมิรู้จบ สร้างความเสียหายทางกายภาพ ลดค่าความโกรธของพวกเขา และมีโอกาสสูงมากที่จะมาพร้อมกับวิญญาณผี',
		simDesc_in = 'Kira Kaisar Xin sekali lagi memanggil gerbang ke dunia terbalik, menyebabkan semua unit musuh jatuh ke dalam jurang yang tak berujung, memberikan kerusakan fisik, mengurangi nilai kemarahan mereka, dan memiliki peluang sangat tinggi disertai dengan roh hantu.',
		simDesc_ph = 'Minsan muli nang tinawag ni Kira The Emperor Xin ang pintuan papunta sa baliktad na mundo, na nagdudulot sa lahat ng yunit ng kalaban na mahulog sa walang katapusang bangin, nagdudulot ng pisikal na pinsala, nagpapababa ng halaga ng kanilang galit, at may mataas na posibilidad na may kasamang espiritu ng multo.',
		simDesc_ma = 'Kira Maharaja Xin sekali lagi memanggil pintu masuk ke dunia terbalik, menyebabkan semua unit musuh jatuh ke dalam jurang yang tidak berpenghujung, memberikan kerosakan fizikal, mengurangkan nilai kemarahan mereka, dan mempunyai peluang yang sangat tinggi untuk disertai roh hantu.',
		simDesc = 'Kira The Emperor Xin once again summons the gateway to the reversed world, causing all enemy units to fall into an endless abyss, dealing physical damage, reducing their anger value, and having a very high chance to inflict a ghost spirit.',
		starEffect = __data_t__starEffect[210223],
		-- {11}
		starEffectDesc_vn = 'Kỹ năng chí mạng hình thái khác sẽ đảo ngược toàn bộ thế giới kéo dài 3 lượt: giảm tốc độ hồi phục tức giận của toàn bộ địch 15%; số lượt duy trì của hình thái nguồn gốc +1',
		starEffectDesc = 'Different form critical skill will reverse the entire world for 3 turns: reduce the anger recovery speed of all enemies by 15%; duration of origin form +1',
		starEffectDesc_en = 'Different form critical skill will reverse the entire world for 3 turns: reduce the anger recovery speed of all enemies by 15%; duration of origin form +1',
		starEffectDesc_th = 'ทักษะวิกฤติรูปร่างที่แตกต่างจะพลิกโลกทั้งหมดเป็นเวลา 3 เทิร์น: ลดความเร็วในการฟื้นฟูความโกรธของศัตรูทั้งหมด 15%; ระยะเวลารูปร่างต้นกำเนิด +1',
		starEffectDesc_in = 'Skill kritis bentuk berbeda akan membalikkan seluruh dunia selama 3 giliran: mengurangi kecepatan pemulihan kemarahan semua musuh sebesar 15%; durasi bentuk asal +1',
		starEffectDesc_ph = 'Iba\'t ibang anyo ng kasanayang kritikal ay babaliktarin ang buong mundo ng 3 na turn: pababain ang bilis ng pag-recover ng galit ng lahat ng kalaban ng 15%; tagal ng anyo ng pinagmulan +1',
