	[210226] = {
		id = 210226,
		skillName_vn = 'Bóng ma dày đặc',
		skillName_en = 'Dense ghost',
		skillName_th = 'ผีหนาแน่น',
		skillName_in = 'Hantu tebal',
		skillName_ph = 'Matinding multo',
		skillName_ma = 'Hantu tebal',
		skillName = 'Dense ghost',
		describe_vn = 'Khi Giratio bước vào hiện trường, anh ta sẽ nhận được số lượng hồn ma của các anh hùng trong trại của mình ngoài chính mình (giới hạn trên của số lượng ma: 5 điểm, không thể xua tan hoặc bỏ qua), và mỗi hồn ma có thể giảm số lượng hồn ma của mình #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# Sát thương cuối cùng nhận được sẽ giảm 1 hồn ma mỗi khi trúng đòn. Khi bóng ma giảm đi, 80 điểm thịnh nộ sẽ được phục hồi\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn, bạn và anh hùng có phần trăm máu thấp nhất ở hàng sau trong đội của bạn sẽ nhận được [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: lượng khiên bằng 15% máu tối đa của Giratina. , không thể chồng lên, mục tiêu tấn công khiên ma sẽ yếu: đòn tấn công kép giảm 15% trong 2 lượt); khi chuyển sang dạng gốc, 30% lượng HP đã mất có thể được phục hồi (không bị ảnh hưởng bởi phương pháp điều trị bị cấm) và bản thân sẽ không tái sinh khi tấn công ở dạng gốc.',
		describe_en = 'When Giratio enters the battlefield, he will receive the number of ghosts of the heroes in his camp excluding himself (maximum number of ghosts: 5 points, cannot be dispelled or ignored), and each ghost can reduce his own ghost count by #(4 + s killLevel * 0.04 - 0.04)%#. The final damage received will reduce one ghost each time he is hit. When the ghosts decrease, 80 points of Fury will be restored \n#F20# \n#F40# At the start of each major round, you and the hero with the lowest HP percentage in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: shield amount equal to 15% of Giratia’s max HP, cannot be stacked, targets attacked by the ghost shield are weakened: double attacks reduced by 15% for 2 turns); when switching to original form, 30% of lost HP can be recovered (not affected by forbidden healing methods) and you will not resurrect when attacking in original form.',
		describe_th = 'เมื่อ Giratio เข้าไปในสนามรบ เขาจะได้รับจำนวนผีของเหล่าฮีโร่ในค่ายของเขานอกเหนือจากตัวเอง (ขีดจำกัดสูงสุดของจำนวนผี: 5 คะแนน ไม่สามารถขจัดหรือละเลยได้) และผีแต่ละตัวสามารถลดจำนวนผีของเขาเองได้ #(4 + s killLevel * 0.04 - 0.04)%#. ความเสียหายสุดท้ายที่ได้รับจะลดผีไปหนึ่งตัวทุกครั้งที่ถูกโจมตี เมื่อผีลดลงจะฟื้นฟูความโกรธ 80 คะแนน \n#F20# \n#F40# เมื่อเริ่มรอบใหญ่แต่ละรอบ คุณและฮีโร่ที่มีเปอร์เซ็นต์ HP ต่ำที่สุดในแถวหลังของทีมจะได้รับ [#L10#โล่ผี#L0#] ([#L10#โล่ผี#L0#]: โล่เท่ากับ 15% ของ HP สูงสุดของ Giratio ไม่สามารถซ้อนทับได้ เป้าหมายที่ถูกโจมตีโดยโล่ผีจะอ่อนแอ: การโจมตีคู่ลดลง 15% เป็นเวลา 2 เทิร์น); เมื่อเปลี่ยนเป็นรูปแบบเดิม จะฟื้นฟู HP ที่เสียไป 30% (ไม่ได้รับผลกระทบจากวิธีการรักษาที่ห้าม) และตัวเองจะไม่ฟื้นคืนชีพเมื่อโจมตีในรูปแบบเดิม',
		describe_in = 'Saat Giratio memasuki medan pertempuran, dia akan menerima jumlah hantu para pahlawan di perkemahannya selain dirinya sendiri (batas atas jumlah hantu: 5 poin, tidak dapat dihapus atau diabaikan), dan setiap hantu dapat mengurangi jumlah hantunya sendiri sebesar #(4 + s killLevel * 0.04 - 0.04)%#. Kerusakan akhir yang diterima akan mengurangi satu hantu setiap kali terkena serangan. Ketika bayangan hantu berkurang, 80 poin Amarah akan dipulihkan \n#F20# \n#F40# Pada awal setiap ronde besar, kamu dan pahlawan dengan persentase HP terendah di barisan belakang timmu akan menerima [#L10#Perisai Hantu#L0#] ([#L10#Perisai Hantu#L0#]: jumlah perisai sama dengan 15% HP maksimum Giratio, tidak dapat ditumpuk, target yang diserang oleh perisai hantu akan melemah: serangan ganda berkurang 15% selama 2 giliran); saat beralih ke bentuk asli, 30% HP yang hilang dapat dipulihkan (tidak terpengaruh oleh metode penyembuhan terlarang) dan kamu tidak akan dibangkitkan saat menyerang dalam bentuk asli.',
		describe_ph = 'Kapag pumasok si Giratio sa larangan ng digmaan, makakatanggap siya ng bilang ng mga multo ng mga bayani sa kanyang kampo maliban sa kanyang sarili (pinakamataas na bilang ng mga multo: 5 puntos, hindi maaaring alisin o balewalain), at bawat multo ay maaaring bawasan ang kanyang sariling bilang ng mga multo ng #(4 + s killLevel * 0.04 - 0.04)%#. Ang huling pinsalang matatanggap ay magbabawas ng isang multo sa tuwing tatama. Kapag nabawasan ang mga multo, 80 puntos ng Galit ang mababawi \n#F20# \n#F40# Sa simula ng bawat malaking round, ikaw at ang bayani na may pinakamababang porsyento ng HP sa likurang hanay ng iyong koponan ay makakatanggap ng [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: halaga ng kalasag katumbas ng 15% ng maximum HP ni Giratio, hindi maaaring mag-stack, ang mga target na inaatake ng ghost shield ay magiging mahina: binabawasan ang dobleng atake ng 15% sa loob ng 2 mga turn); kapag lumipat sa orihinal na anyo, maaaring mabawi ang 30% ng nawalang HP (hindi naaapektuhan ng mga ipinagbabawal na paraan ng paggaling) at hindi muling mabubuhay kapag umaatake sa orihinal na anyo.',
		describe_ma = 'Apabila Giratio memasuki medan pertempuran, dia akan menerima jumlah hantu wira dalam kemahnya selain dirinya sendiri (had atas bilangan hantu: 5 mata, tidak boleh dihapus atau diabaikan), dan setiap hantu boleh mengurangkan bilangan hantunya sendiri sebanyak #(4 + s killLevel * 0.04 - 0.04)%#. Kerosakan akhir diterima akan mengurangkan satu hantu setiap kali terkena serangan. Apabila bayangan hantu berkurang, 80 mata Kemurkaan akan dipulihkan \n#F20# \n#F40# Pada permulaan setiap pusingan besar, anda dan wira dengan peratusan darah terendah di barisan belakang pasukan anda akan menerima [#L10#Perisai Hantu#L0#] ([#L10#Perisai Hantu#L0#]: jumlah perisai bersamaan 15% darah maksimum Giratio, tidak boleh bertindih, sasaran yang diserang perisai hantu akan menjadi lemah: serangan berganda dikurangkan 15% selama 2 pusingan); apabila beralih ke bentuk asal, 30% jumlah HP yang hilang boleh dipulihkan (tidak terjejas oleh kaedah rawatan yang dilarang) dan diri sendiri tidak akan bangkit semula apabila menyerang dalam bentuk asal.',
		describe = 'When Giratio enters the battlefield, he will receive the number of ghosts of the heroes in his camp excluding himself (maximum number of ghosts: 5 points, cannot be dispelled or ignored), and each ghost can reduce his own ghost count by #(4 + s killLevel * 0.04 - 0.04)%#. The final damage received will reduce one ghost each time he is hit. When the ghosts decrease, 80 points of Fury will be restored \n#F20# \n#F40# At the start of each major round, you and the hero with the lowest HP percentage in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: shield amount equal to 15% of Giratia’s max HP, cannot be stacked, targets attacked by the ghost shield are weakened: double attacks reduced by 15% for 2 turns); when switching to original form, 30% of lost HP can be recovered (not affected by forbidden healing methods) and you will not resurrect when attacking in original form.',
		starEffect = __data_t__starEffect[210226],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Quỷ khiên nâng cấp: tăng 5% lượng khiên, mỗi lượt lớn kết thúc bản thân nhận 1 điểm Quỷ ảnh',
		starEffectDesc = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
		starEffectDesc_en = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
		starEffectDesc_th = 'เอฟเฟกต์การอัปเกรดโล่ปีศาจ: เพิ่มปริมาณโล่ 5% เมื่อสิ้นสุดแต่ละเทิร์นใหญ่ รับ 1 คะแนนเงาปีศาจ',
		starEffectDesc_in = 'Efek Peningkatan Perisai Setan: meningkatkan jumlah perisai sebesar 5%, pada akhir setiap giliran besar, menerima 1 poin Bayangan Setan',
		starEffectDesc_ph = 'Epekto ng Pag-upgrade ng Demon Shield: nagdaragdag ng 5% sa dami ng shield, sa pagtatapos ng bawat malaking turn ay tumatanggap ng 1 Demon Shadow point',
		starEffectDesc_ma = 'Kesan Naik Taraf Perisai Iblis: meningkatkan jumlah perisai sebanyak 5%, pada akhir setiap giliran besar, menerima 1 mata Bayangan Iblis',
		changeUnitTrigger = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {2102261, 2102262, 2102263}
	},
	[210227] = {
		id = 210227,
		skillName_vn = 'Bị động',
		skillName_en = 'Passive',
		skillName_th = 'ถูกกระทำ',
		skillName_in = 'Pasif',
		skillName_ph = 'Passive',
		skillName_ma = 'Pasif',
		skillName = 'Passive',
		describe_vn = 'Khi Giratio bước vào hiện trường, anh ta sẽ nhận được số lượng hồn ma của các anh hùng trong trại của mình ngoài chính mình (giới hạn trên của số lượng ma: 5 điểm, không thể xua tan hoặc bỏ qua), và mỗi hồn ma có thể giảm số lượng hồn ma của mình #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# Sát thương cuối cùng nhận được sẽ giảm 1 hồn ma mỗi khi trúng đòn. Khi bóng ma giảm đi, 80 điểm thịnh nộ sẽ được phục hồi\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn, bạn và anh hùng có phần trăm máu thấp nhất ở hàng sau trong đội của bạn sẽ nhận được [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: lượng khiên bằng 15% máu tối đa của Giratina. , không thể chồng lên, mục tiêu tấn công khiên ma sẽ yếu: đòn tấn công kép giảm 15% trong 2 lượt); khi chuyển sang dạng gốc, 30% lượng HP đã mất có thể được phục hồi (không bị ảnh hưởng bởi phương pháp điều trị bị cấm) và bản thân sẽ không tái sinh khi tấn công ở dạng gốc.',
		describe_en = 'When Giratio enters the battlefield, he will receive the number of ghosts of the heroes in his camp excluding himself (maximum ghost count: 5 points, cannot be dispelled or ignored). Each ghost can reduce his own ghost count by #(4+s killLevel*0.04-0.04)%#. The final damage received will reduce one ghost each time he is hit. When ghosts decrease, 80 points of rage will be restored. At the start of each major round, you and the hero with the lowest HP percentage in the back row of your team will receive [Ghost Shield] (Ghost Shield: shield amount equals 15% of Giratio\'s max HP, cannot stack; the target attacking the ghost shield will be weakened: dual strikes deal 15% less damage for 2 turns). When switching to original form, 30% of lost HP can be restored (not affected by banned healing methods), and he will not resurrect when attacking in original form.',
		describe_th = 'เมื่อ Giratio เข้าสู่สนามรบ เขาจะได้รับจำนวนผีของฮีโร่ในค่ายของเขายกเว้นตัวเอง (จำนวนผีสูงสุด: 5 คะแนน ไม่สามารถลบหรือเพิกเฉยได้) แต่ละผีสามารถลดจำนวนผีของตัวเองได้ #(4+s killLevel*0.04-0.04)%#. ความเสียหายสุดท้ายที่ได้รับจะลดจำนวนผีลงหนึ่งตัวทุกครั้งที่โดนโจมตี เมื่อผีลดลง จะฟื้นฟูค่าความโกรธได้ 80 คะแนน ในตอนเริ่มแต่ละรอบใหญ่ คุณและฮีโร่ที่มีเปอร์เซ็นต์ HP ต่ำที่สุดในแถวหลังของทีมจะได้รับ [Ghost Shield] (Ghost Shield: โล่จำนวนเท่ากับ 15% ของ HP สูงสุดของ Giratio ไม่สามารถซ้อนทับได้; เป้าหมายที่โจมตีโล่ผีจะอ่อนแอ: การโจมตีคู่ลดลง 15% เป็นเวลา 2 เทิร์น) เมื่อเปลี่ยนเป็นรูปแบบดั้งเดิม จะฟื้นฟู HP ที่เสียไปได้ 30% (ไม่ถูกกระทบโดยวิธีการรักษาที่ถูกห้าม) และจะไม่ฟื้นจากการโจมตีในรูปแบบดั้งเดิม',
		describe_in = 'Saat Giratio memasuki medan pertempuran, dia akan menerima jumlah hantu pahlawan di kampnya selain dirinya sendiri (batas atas jumlah hantu: 5 poin, tidak dapat dibersihkan atau diabaikan). Setiap hantu dapat mengurangi jumlah hantunya sendiri sebanyak #(4+s killLevel*0.04-0.04)%#. Kerusakan akhir yang diterima akan mengurangi satu hantu setiap kali terkena serangan. Ketika jumlah hantu berkurang, akan memulihkan 80 poin kemarahan. Pada awal setiap putaran besar, kamu dan pahlawan dengan persentase HP terendah di barisan belakang timmu akan menerima [Ghost Shield] (Ghost Shield: jumlah perisai sebesar 15% HP maksimum Giratio, tidak dapat ditumpuk; target yang menyerang perisai hantu akan melemah: serangan ganda berkurang 15% selama 2 giliran). Saat beralih ke bentuk asli, 30% HP yang hilang dapat dipulihkan (tidak terpengaruh oleh metode penyembuhan yang dilarang), dan dirinya tidak akan bangkit kembali saat menyerang dalam bentuk asli.',
		describe_ph = 'Kapag pumasok si Giratio sa lugar ng labanan, makakatanggap siya ng bilang ng mga multo ng mga bayani sa kanyang kampo bukod sa kanyang sarili ( pinakamataas na bilang ng multo: 5 puntos, hindi maaaring alisin o balewalain). Bawat multo ay maaaring magbawas ng sariling bilang ng multo ng #(4+s killLevel*0.04-0.04)%#. Ang huling natanggap na pinsala ay magbabawas ng isang multo sa tuwing matama. Kapag bumaba ang bilang ng mga multo, 80 puntos ng galit ang mababawi. Sa simula ng bawat malaking round, ikaw at ang bayani na may pinakamababang porsyento ng HP sa likurang hanay ng iyong koponan ay makakatanggap ng [Ghost Shield] ([Ghost Shield]: dami ng kalasag na katumbas ng 15% ng maximum HP ni Giratio, hindi maaaring pagsamahin; ang target na umaatake sa kalasag ng multo ay magiging mahina: doble ang pag-atake ay nababawasan ng 15% sa loob ng 2 turn). Kapag lumipat sa orihinal na anyo, maaaring maibalik ang 30% ng nawalang HP (hindi naapektuhan ng ipinagbabawal na paraan ng paggaling) at hindi siya muling mabubuhay kapag umaatake sa orihinal na anyo.',
		describe_ma = 'Apabila Giratio memasuki medan pertempuran, dia akan menerima bilangan hantu wira dalam kemnya selain dirinya sendiri (had atas bilangan hantu: 5 mata, tidak boleh disingkir atau diabaikan). Setiap hantu boleh mengurangkan bilangan hantunya sendiri sebanyak #(4+s killLevel*0.04-0.04)%#. Kerosakan akhir yang diterima akan mengurangkan satu hantu setiap kali terkena serangan. Apabila hantu berkurangan, 80 mata kemarahan akan dipulihkan. Pada permulaan setiap pusingan besar, anda dan wira dengan peratusan HP terendah di barisan belakang dalam pasukan anda akan menerima [Ghost Shield] ([Ghost Shield]: jumlah perisai sama dengan 15% HP maksimum Giratio, tidak boleh bertindih; sasaran yang menyerang perisai hantu akan menjadi lemah: serangan berganda berkurang 15% selama 2 giliran); apabila bertukar ke bentuk asal, 30% HP yang hilang dapat dipulihkan (tidak dipengaruhi oleh kaedah rawatan yang dilarang), dan dia tidak akan hidup semula apabila menyerang dalam bentuk asal.',
		describe = 'When Giratio enters the battlefield, he will receive the number of ghosts of the heroes in his camp excluding himself (maximum ghost count: 5 points, cannot be dispelled or ignored). Each ghost can reduce his own ghost count by #(4+s killLevel*0.04-0.04)%#. The final damage received will reduce one ghost each time he is hit. When ghosts decrease, 80 points of rage will be restored. At the start of each major round, you and the hero with the lowest HP percentage in the back row of your team will receive [Ghost Shield] (Ghost Shield: shield amount equals 15% of Giratio\'s max HP, cannot stack; the target attacking the ghost shield will be weakened: dual strikes deal 15% less damage for 2 turns). When switching to original form, 30% of lost HP can be restored (not affected by banned healing methods), and he will not resurrect when attacking in original form.',
		starEffect = __data_t__starEffect[210227],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Quỷ khiên nâng cấp: tăng 5% lượng khiên, mỗi lượt lớn kết thúc bản thân nhận 1 điểm Quỷ ảnh',
