		skillName_th = 'ลมแปลกๆ',
		skillName_in = 'Angin aneh',
		skillName_ph = 'Kakaibang hangin',
		skillName_ma = 'Angin pelik',
		skillName = 'Strange wind',
		describe_vn = 'Giratina đập mặt đất triệu hồi gió kỳ dị tấn công mục tiêu đơn thể địch, gây #C0xE69900#100% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ Sát Thương Vật Lý#C0xF13B54#, tăng 50% phòng thủ đôi của bản thân trong 2 lượt, sau khi tấn công bản thân nhận 1 điểm bóng ma',
		describe_en = 'Giratina slams the ground to summon a strange wind that attacks a single enemy target, dealing #C0xE69900#100% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ Physical Damage#C0xF13B54#, increases own dual defense by 50% for 2 turns, after attacking gains 1 ghost point.',
		describe_th = 'กิราติน่าตีพื้นเพื่อเรียกลมประหลาดโจมตีศัตรูเป้าหมายเดี่ยว ทำความเสียหาย #C0xE69900#100% การโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ ความเสียหายทางกายภาพ#C0xF13B54# เพิ่มการป้องกันคู่ของตัวเองขึ้น 50% เป็นเวลา 2 เทิร์น หลังจากโจมตีได้รับ 1 คะแนนผี.',
		describe_in = 'Giratina menghantam tanah untuk memanggil angin aneh yang menyerang satu target musuh, memberikan #C0xE69900#100% Serangan Fisik#C0x5B545B#+$(skillLevel*4*24)$ Damage Fisik#C0xF13B54#, meningkatkan pertahanan ganda sendiri sebesar 50% selama 2 giliran, setelah menyerang menerima 1 poin hantu.',
		describe_ph = 'Binuksan ni Giratina ang lupa upang tumawag ng kakaibang hangin na umaatake sa isang kaaway, nagdudulot ng #C0xE69900#100% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ Physical Damage#C0xF13B54#, tumataas ng 50% ang sariling doble depensa sa loob ng 2 turn, pagkatapos makaatake ay nakakakuha ng 1 ghost point.',
		describe_ma = 'Giratina memukul tanah untuk memanggil angin pelik yang menyerang satu sasaran musuh, menyebabkan #C0xE69900#100% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ Kerosakan Fizikal#C0xF13B54#, meningkatkan pertahanan berganda sendiri sebanyak 50% selama 2 pusingan, selepas menyerang menerima 1 mata hantu.',
		describe = 'Giratina slams the ground to summon a strange wind that attacks a single enemy target, dealing #C0xE69900#100% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ Physical Damage#C0xF13B54#, increases own dual defense by 50% for 2 turns, after attacking gains 1 ghost point.',
		simDesc_vn = 'Kira Đế Tân đập xuống mặt đất, triệu hồi gió kỳ lạ tấn công mục tiêu đơn lẻ của kẻ thù, gây sát thương vật lý, tăng cường khả năng giảm sát thương của bản thân và hồi phục điểm ma quái.',
		simDesc_en = 'Kira Tei Shin strikes the ground, summoning a strange wind to attack a single enemy target, dealing physical damage, enhancing self damage reduction, and restoring eerie points.',
		simDesc_th = 'คิระ เทย์ ชิน ทุบลงกับพื้น เรียกลมประหลาดโจมตีเป้าหมายศัตรูเดี่ยว ทำความเสียหายทางกายภาพ เสริมความสามารถในการลดความเสียหายของตนเอง และฟื้นฟูจุดวิญญาณลึกลับ',
		simDesc_in = 'Kira Tei Shin memukul tanah, memanggil angin aneh untuk menyerang satu target musuh, memberikan kerusakan fisik, meningkatkan kemampuan pengurangan kerusakan diri sendiri, dan memulihkan poin roh aneh.',
		simDesc_ph = 'Binugbog ni Kira Tei Shin ang lupa, sumangguni ng kakaibang hangin para salakayin ang isang kalaban na target, nagdudulot ng pisikal na pinsala, nagpapalakas ng kakayahan sa pagbawas ng pinsala sa sarili, at nagpapagaling ng mga punto ng mahiwagang espiritu.',
		simDesc_ma = 'Kira Tei Shin memukul tanah, memanggil angin aneh untuk menyerang sasaran musuh tunggal, menyebabkan kerosakan fizikal, meningkatkan kemampuan mengurangkan kerosakan diri sendiri, dan memulihkan mata roh aneh.',
		simDesc = 'Kira Tei Shin strikes the ground, summoning a strange wind to attack a single enemy target, dealing physical damage, enhancing self damage reduction, and restoring eerie points.',
		upLvDesc = 'Fixed damage +96',
		upLvDesc_en = 'Fixed damage +96',
