	[210312] = {
		id = 210312,
		skillName_vn = 'Đòn tấn công bóng',
		skillName_en = 'Light attack',
		skillName_th = 'การโจมตีเบา',
		skillName_in = 'Serangan ringan',
		skillName_ph = 'Magaan na pag-atake',
		skillName_ma = 'Serangan ringan',
		skillName = 'Light attack',
		describe_vn = 'Giratina biến thành ma và di chuyển đến một mục tiêu địch để đánh lén, gây #C0xE69900#170% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B# tăng khả năng giảm sát thương của cột mình thêm 15% trong 2 lượt. Sau khi tấn công, bản thân nhận được 2 điểm ma\n#F20# \n#F40#[#L10#Origin Form#L0#], phạm vi tấn công thay đổi theo hàng và có thêm 80% xác suất [#L10#Ghost Fire#L0#] trong 2 lượt\n[#L10# Netherworld Wisp#L0#]: Hiệu ứng tiêu cực đặc biệt, chỉ có thể xua tan và không thể áp dụng. Trước khi mục tiêu di chuyển hoặc khi Netherworld Wisp bị xua tan, máu của mục tiêu sẽ bị giảm (12% lượng máu tối đa của Giratina) và 120 điểm thịnh nộ.',
		describe_en = 'Giratina transforms into a ghost and moves to an enemy target to strike from behind, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#. It also increases the target\'s damage reduction by 15% for 2 turns. After attacking, Giratina gains 2 points of ma\n#F20# \n#F40#[#L10#Origin Form#L0#], with attack range changing by rows and an 80% chance to trigger [#L10#Ghost Fire#L0#] for 2 turns\n[#L10# Netherworld Wisp#L0#]: a special negative effect that can only be dispelled and not reapplied. Before the target moves or when Netherworld Wisp is dispelled, the target\'s HP will decrease (12% of Giratina\'s max HP) and 120 Rage points.',
		describe_th = 'Giratina เปลี่ยนร่างเป็นผีและเคลื่อนที่ไปยังเป้าหมายศัตรูเพื่อโจมตีแบบลอบโจมตี สร้างความเสียหายทางกายภาพ #C0xE69900#170%#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# และเพิ่มความสามารถในการลดความเสียหายของเป้าหมายขึ้นอีก 15% เป็นเวลา 2 เทิร์น หลังจากโจมตีเองจะได้รับ 2 แต้ม ma\n#F20# \n#F40#[#L10#Origin Form#L0#] ระยะโจมตีเปลี่ยนไปตามแถว และมีโอกาส 80% ที่จะเกิด [#L10#Ghost Fire#L0#] เป็นเวลา 2 เทิร์น\n[#L10# Netherworld Wisp#L0#]: เป็นสถานะลบพิเศษ ที่สามารถลบได้เท่านั้นและไม่สามารถใช้ซ้ำได้ ก่อนที่เป้าหมายจะเคลื่อนที่ หรือเมื่อ Netherworld Wisp ถูกลบ เลือดของเป้าหมายจะลดลง (12% ของเลือดสูงสุดของ Giratina) และได้รับ 120 คะแนนความโกรธ',
		describe_in = 'Giratina berubah menjadi hantu dan bergerak ke target musuh untuk menyerang secara diam-diam, memberikan #C0xE69900#170% Damage Fisik#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Damage Fisik #C0x5B545B# serta meningkatkan kemampuan pengurangan damage sasaran sebesar 15% selama 2 giliran. Setelah menyerang, Giratina mendapatkan 2 poin ma\n#F20# \n#F40#[#L10#Origin Form#L0#], jangkauan serangan berubah berdasarkan baris dan memiliki peluang 80% untuk mengaktifkan [#L10#Ghost Fire#L0#] selama 2 giliran\n[#L10# Netherworld Wisp#L0#]: efek negatif khusus yang hanya dapat dihapus dan tidak bisa diterapkan kembali. Sebelum target bergerak atau saat Netherworld Wisp dihapus, HP target akan berkurang (12% dari HP maksimal Giratina) dan mendapatkan 120 poin Kemarahan.',
		describe_ph = 'Nagiging multo si Giratina at gumalaw patungo sa isang kalaban upang maglunsad ng sneak attack, na nagdudulot ng #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Physical Damage #C0x5B545B# at pinapataas ang kakayahan ng target na magpababa ng damage ng 15% sa loob ng 2 liko. Pagkatapos umatake, nakakakuha ng 2 puntos ang sarili ng ma\n#F20# \n#F40#[#L10#Origin Form#L0#], nagbabago ang saklaw ng atake ayon sa hilera at may 80% tsansa ng [#L10#Ghost Fire#L0#] sa loob ng 2 liko\n[#L10# Netherworld Wisp#L0#]: isang espesyal na negatibong epekto na maaari lamang matanggal at hindi maaaring muling ilapat. Bago gumalaw ang target o kapag natanggal ang Netherworld Wisp, mababawasan ang HP ng target (12% ng maximum HP ni Giratina) at magkakaroon ng 120 na puntos ng Galit.',
		describe_ma = 'Giratina berubah menjadi hantu dan bergerak ke sasaran musuh untuk menyerang secara mengejutkan, menyebabkan #C0xE69900#170% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Kerosakan Fizikal #C0x5B545B# serta meningkatkan keupayaan pengurangan kerosakan sasaran sebanyak 15% selama 2 pusingan. Selepas menyerang, Giratina menerima 2 mata ma\n#F20# \n#F40#[#L10#Origin Form#L0#], julat serangan berubah mengikut baris dan mempunyai 80% peluang untuk mencetuskan [#L10#Ghost Fire#L0#] selama 2 pusingan\n[#L10# Netherworld Wisp#L0#]: kesan negatif khas yang hanya boleh dipadam dan tidak boleh digunakan semula. Sebelum sasaran bergerak atau apabila Netherworld Wisp dipadam, darah sasaran akan berkurang (12% daripada darah maksimum Giratina) dan mendapat 120 mata Kemarahan.',
		describe = 'Giratina transforms into a ghost and moves to an enemy target to strike from behind, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#. It also increases the target\'s damage reduction by 15% for 2 turns. After attacking, Giratina gains 2 points of ma\n#F20# \n#F40#[#L10#Origin Form#L0#], with attack range changing by rows and an 80% chance to trigger [#L10#Ghost Fire#L0#] for 2 turns\n[#L10# Netherworld Wisp#L0#]: a special negative effect that can only be dispelled and not reapplied. Before the target moves or when Netherworld Wisp is dispelled, the target\'s HP will decrease (12% of Giratina\'s max HP) and 120 Rage points.',
		simDesc_vn = 'Kira Đế Tân biến hình thành bóng ma, di chuyển đến trước mục tiêu đơn lẻ của kẻ thù để tấn công lén, gây sát thương vật lý, đồng thời tăng giới hạn tức giận của mục tiêu và bản thân nhận điểm ma quái; trong trạng thái nguồn gốc, phạm vi tấn công chuyển thành hàng và có xác suất kèm theo hồn ma.',
		simDesc_en = 'Kira Đế Tân transforms into a phantom, moving to the enemy\'s single target for a stealth attack, dealing physical damage, while increasing the target\'s rage limit and gaining a ghost point for himself; in the origin state, the attack range changes to a row and has a chance to summon a ghost.',
		simDesc_th = 'คิระ เด เทียน แปลงร่างเป็นผีปอบ เคลื่อนที่ไปยังเป้าหมายเดี่ยวของศัตรูเพื่อโจมตีอย่างลับ ๆ สร้างความเสียหายทางกายภาพ พร้อมเพิ่มขีดจำกัดความโกรธของเป้าหมายและได้รับคะแนนวิญญาณ; ในสภาพแหล่งกำเนิด พิสัยโจมตีเปลี่ยนเป็นแถวและมีโอกาสดึงผีรับร่วมด้วย',
		simDesc_in = 'Kira Đế Tân berubah menjadi hantu, bergerak ke target tunggal musuh untuk serangan diam-diam, memberikan kerusakan fisik, sekaligus meningkatkan batas kemarahan target dan dirinya sendiri menerima poin hantu; dalam keadaan asal, jangkauan serangan berubah menjadi baris dan memiliki kemungkinan disertai hantu.',
		simDesc_ph = 'Si Kira Đế Tân ay nagbabago sa isang multo, lumalapit sa isang kalaban na target para sa isang lihim na pag-atake, na nagdudulot ng pisikal na pinsala, kasabay ng pagtaas ng limitasyon ng galit ng target at nakakakuha ng puntos ng multo para sa sarili; sa estado ng pinagmulan, ang saklaw ng pag-atake ay nagiging hanay at may pagkakataong may kasamang multo.',
		simDesc_ma = 'Kira Đế Tân berubah menjadi hantu, bergerak ke sasaran tunggal musuh untuk serangan pernicious, menyebabkan kerosakan fizikal, sekaligus meningkatkan had kemarahan sasaran dan dirinya sendiri menerima mata hantu; dalam keadaan asal, julat serangan berubah kepada barisan dan mempunyai kemungkinan disertai hantu.',
		simDesc = 'Kira Đế Tân transforms into a phantom, moving to the enemy\'s single target for a stealth attack, dealing physical damage, while increasing the target\'s rage limit and gaining a ghost point for himself; in the origin state, the attack range changes to a row and has a chance to summon a ghost.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
		upLvDesc_in = 'Kerusakan tetap +192',
		upLvDesc_ph = 'Fixed damage +192',
