	[210313] = {
		id = 210313,
		skillName_vn = 'Thế giới đảo ngược',
		skillName_en = 'Reverse World',
		skillName_th = 'โลกกลับด้าน',
		skillName_in = 'Dunia Terbalik',
		skillName_ph = 'Kabaliktaran na Mundo',
		skillName_ma = 'Dunia Terbalik',
		skillName = 'Reverse World',
		describe_vn = 'Giratina thức tỉnh từ vực thẳm, sau đó triệu hồi lối vào thế giới đảo ngược, hút các đơn vị hàng đầu của kẻ địch vào đó, gây #C0xE69900#230% Sát Thương Vật Lý#C0x5B545B#+$(ski llLevel*4*48)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, giảm cơn thịnh nộ của mục tiêu trúng đòn đi 250 điểm và nhận được 3 điểm ma sau khi tấn công\n#F20# \n#F40#Sau khi thực hiện chiêu thức đặc biệt, anh ta chuyển sang [#L10#Origin Form#L0#] trong 2 hiệp. Giới hạn trên của lượng máu của chính anh ta (chỉ tăng giới hạn trên), tốc độ và tỷ lệ kiểm soát tổng thể được tăng thêm 50% (không thể phân tán, chuyển giao hoặc sao chép). Chuyển sang chiêu thức đặc biệt mới (không cần nộ và không tiêu hao nộ khi phóng ra, hồi lại trong 2 lượt sau khi phóng): Phạm vi thay đổi đối với tất cả kẻ địch và có thêm 75% xác suất thêm [#L10#鬼鬼火#L0#] vào 4 tướng địch có nộ cao nhất trong 2 lượt.',
		describe_en = 'Giratina awakens from the abyss, then summons the entrance to the reverse world, sucking in the enemy\'s top units, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, reducing the targeted enemy\'s rage by 250 points and gaining 3 demonic points after attacking\n#F20# \n#F40#After performing the special skill, he switches to [#L10#Origin Form#L0#] for 2 turns. His max HP limit (only the upper limit increases), speed, and overall control rate are increased by 50% (cannot be dispersed, transferred, or copied). Switches to a new special skill (no rage required and no rage consumed upon activation, recovers in 2 turns after use): Range changes to all enemies and gains a 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy units with the highest rage for 2 turns.',
		describe_th = 'Giratina ตื่นขึ้นจากเหวลึก จากนั้นเรียกทางเข้าของโลกกลับด้าน ดึงหน่วยชั้นนำของศัตรูเข้าไปในนั้น สร้าง #C0xE69900#230% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# ลดความโกรธของเป้าหมายที่ถูกโจมตีลง 250 คะแนน และได้รับ 3 คะแนนวิญญาณร้ายหลังโจมตี\n#F20# \n#F40# หลังจากใช้งานสกิลพิเศษ เขาจะเปลี่ยนเป็น [#L10#Origin Form#L0#] เป็นเวลา 2 เทิร์น ขีดจำกัดสูงสุดของ HP (เพิ่มเฉพาะขีดจำกัดสูงสุด), ความเร็ว และอัตราควบคุมโดยรวมเพิ่มขึ้น 50% (ไม่สามารถแยก ย้าย หรือคัดลอกได้) เปลี่ยนเป็นสกิลพิเศษใหม่ (ไม่ต้องใช้โกรธและไม่ใช้โกรธเมื่อใช้ ฟื้นฟูใน 2 เทิร์นหลังใช้): ระยะเปลี่ยนเป็นศัตรูทั้งหมด และมีโอกาส 75% ที่จะเพิ่ม [#L10#鬼鬼火#L0#] ให้กับ 4 หน่วยศัตรูที่มีโกรธสูงสุดใน 2 เทิร์น',
		describe_in = 'Giratina bangkit dari jurang, kemudian memanggil pintu masuk ke dunia terbalik, menarik unit teratas musuh ke dalamnya, memberikan #C0xE69900#230% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Kerusakan Fisik #C0x5B545B#, mengurangi kemarahan target yang terkena serangan sebesar 250 poin dan mendapatkan 3 poin setan setelah menyerang\n#F20# \n#F40# Setelah menggunakan skill khusus, dia beralih ke [#L10#Origin Form#L0#] selama 2 giliran. Batas atas HP-nya (hanya batas atas yang bertambah), kecepatan, dan tingkat kontrol keseluruhan meningkat 50% (tidak dapat disebarkan, dipindahkan, atau disalin). Beralih ke skill khusus baru (tidak memerlukan kemarahan dan tidak mengonsumsi kemarahan saat digunakan, pulih dalam 2 giliran setelah digunakan): Jangkauan berubah ke semua musuh dan memiliki peluang 75% untuk menambahkan [#L10#鬼鬼火#L0#] ke 4 unit musuh dengan kemarahan tertinggi selama 2 giliran.',
		describe_ph = 'Giratina ay nagising mula sa kailaliman, pagkatapos ay tinawag ang pasukan sa mundo ng kabaligtaran, hinihila ang mga nangungunang unit ng kalaban papunta doon, nagdudulot ng #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, nagpapababa ng galit ng tumatakbong target ng 250 puntos at nakakakuha ng 3 demonic points pagkatapos umatake\n#F20# \n#F40# Pagkatapos gawin ang espesyal na kakayahan, siya ay lumilipat sa [#L10#Origin Form#L0#] nang 2 turn. Ang pinakamataas na limitasyon ng kanyang HP (tumaas lamang ang limitasyon sa itaas), bilis, at pangkalahatang rate ng kontrol ay nadagdagan ng 50% (hindi maaaring ipamahagi, ilipat o kopyahin). Lumilipat sa bagong espesyal na kakayahan (hindi kailangan ng galit at hindi kumukonsumo ng galit kapag ginamit, bumabalik sa 2 turn pagkatapos gamitin): Ang saklaw ay nagbabago para sa lahat ng kalaban at may 75% na tsansa na magdagdag ng [#L10#鬼鬼火#L0#] sa 4 na kalaban na may pinakamataas na galit sa loob ng 2 turn.',
		describe_ma = 'Giratina terjaga dari jurang, kemudian memanggil pintu masuk ke dunia terbalik, menarik unit teratas musuh ke dalamnya, memberikan #C0xE69900#230% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, mengurangkan kemarahan sasaran yang terkena serangan sebanyak 250 mata dan menerima 3 mata syaitan selepas menyerang\n#F20# \n#F40# Selepas melaksanakan kemahiran khas, dia bertukar ke [#L10#Origin Form#L0#] selama 2 pusingan. Had atas HPnya (hanya had atas yang bertambah), kelajuan, dan kadar kawalan keseluruhan meningkat sebanyak 50% (tidak boleh diagihkan, dipindahkan, atau disalin). Beralih ke kemahiran khas baru (tidak memerlukan kemarahan dan tidak menggunakan kemarahan ketika dilancarkan, pulih dalam 2 pusingan selepas dilancarkan): Julat berubah kepada semua musuh dan mempunyai 75% peluang untuk menambah [#L10#鬼鬼火#L0#] kepada 4 unit musuh dengan kemarahan tertinggi selama 2 pusingan.',
		describe = 'Giratina awakens from the abyss, then summons the entrance to the reverse world, sucking in the enemy\'s top units, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, reducing the targeted enemy\'s rage by 250 points and gaining 3 demonic points after attacking\n#F20# \n#F40#After performing the special skill, he switches to [#L10#Origin Form#L0#] for 2 turns. His max HP limit (only the upper limit increases), speed, and overall control rate are increased by 50% (cannot be dispersed, transferred, or copied). Switches to a new special skill (no rage required and no rage consumed upon activation, recovers in 2 turns after use): Range changes to all enemies and gains a 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy units with the highest rage for 2 turns.',
		simDesc_vn = 'Kira Đế Tân từ vực sâu tỉnh dậy, sau đó triệu hồi cổng vào thế giới đảo ngược, hút các đơn vị kẻ thù ở hàng trước vào trong đó, gây sát thương vật lý, giảm giá trị tức giận của chúng và hồi phục điểm ma quái; sau đó, hầu hết thuộc tính sẽ được nâng cấp chuyển sang trạng thái nguồn gốc; trong trạng thái nguồn gốc, phạm vi tấn công chuyển thành toàn bộ và có xác suất rất cao kèm theo hồn ma.',
		simDesc_en = 'Kira De Tan awakens from the abyss, then summons a portal to the inverted world, pulling enemy units in the front row into it, dealing physical damage, reducing their anger values, and restoring mystic points; afterwards, most attributes will be upgraded and switched to the origin state; in the origin state, the attack range changes to full area and has a very high chance to be accompanied by spirits.',
		simDesc_th = 'คิร่า เดอ ตัน ฟื้นขึ้นจากหุบเหว จากนั้นเรียกประตูสู่โลกผกผัน ดูดหน่วยศัตรูแถวหน้าเข้ามาในนั้น สร้างความเสียหายทางกายภาพ ลดค่าความโกรธของพวกเขาและฟื้นฟูจุดเวทมนตร์; หลังจากนั้น แทบทุกคุณสมบัติจะได้รับการอัปเกรดและเปลี่ยนเป็นสถานะต้นกำเนิด; ในสถานะต้นกำเนิด ระยะการโจมตีเปลี่ยนเป็นทั่วทั้งพื้นที่ และมีโอกาสสูงมากที่มีวิญญาณร่วมด้วย',
		simDesc_in = 'Kira De Tan bangun dari jurang, kemudian memanggil portal ke dunia terbalik, menarik unit musuh di barisan depan ke dalamnya, menyebabkan kerusakan fisik, mengurangi nilai kemarahan mereka, dan memulihkan poin mistis; setelah itu, sebagian besar atribut akan ditingkatkan dan beralih ke status asal; dalam status asal, jangkauan serangan berubah menjadi seluruh area dan memiliki kemungkinan sangat tinggi disertai roh.',
		simDesc_ph = 'Si Kira De Tan ay nagising mula sa kailaliman, pagkatapos ay tinawag ang portal papuntang baligtad na mundo, hinihila ang mga yunit ng kalaban sa unahang hanay papasok dito, nagdudulot ng pisikal na pinsala, nagpapababa ng kanilang galit, at nagpapagaling ng mystical points; pagkatapos, karamihan sa mga katangian ay ia-upgrade at magsusumite sa estado ng pinagmulan; sa estado ng pinagmulan, ang saklaw ng atake ay nagiging buong lugar at may napakataas na tsansa na may kasamang mga espiritu.',
		simDesc_ma = 'Kira De Tan bangkit dari jurang, kemudian memanggil pintu masuk ke dunia terbalik, menarik unit musuh di barisan hadapan ke dalamnya, menyebabkan kerosakan fizikal, mengurangkan nilai kemarahan mereka, dan memulihkan mata mistik; selepas itu, kebanyakan atribut akan dinaik taraf dan beralih ke keadaan asal; dalam keadaan asal, julat serangan berubah menjadi keseluruhan dan mempunyai kebarangkalian sangat tinggi disertai roh.',
		simDesc = 'Kira De Tan awakens from the abyss, then summons a portal to the inverted world, pulling enemy units in the front row into it, dealing physical damage, reducing their anger values, and restoring mystic points; afterwards, most attributes will be upgraded and switched to the origin state; in the origin state, the attack range changes to full area and has a very high chance to be accompanied by spirits.',
		starEffect = __data_t__starEffect[210313],
		-- {11}
		starEffectDesc_vn = 'Kỹ năng chí mạng hình thái khác sẽ đảo ngược toàn bộ thế giới kéo dài 3 lượt: giảm tốc độ hồi phục tức giận của toàn bộ địch 15%; số lượt duy trì của hình thái nguồn gốc +1',
		starEffectDesc = 'Other critical form skills will reverse the entire world for 3 turns: reduce the anger recovery speed of all enemies by 15%; duration of origin form +1',
		starEffectDesc_en = 'Other critical form skills will reverse the entire world for 3 turns: reduce the anger recovery speed of all enemies by 15%; duration of origin form +1',
		starEffectDesc_th = 'ทักษะรูปแบบวิกฤตอื่นจะย้อนกลับทั้งโลกเป็นเวลา 3 เทิร์น: ลดความเร็วในการฟื้นฟูความโกรธของศัตรูทั้งหมดลง 15%; เพิ่มจำนวนรอบของรูปแบบต้นกำเนิด +1',
		starEffectDesc_in = 'Keterampilan bentuk kritis lainnya akan membalikkan seluruh dunia selama 3 giliran: mengurangi kecepatan pemulihan amarah semua musuh sebesar 15%; durasi bentuk asal +1',
		starEffectDesc_ph = 'Ang iba pang mga kasanayan sa kritikal na anyo ay magpabaliktad ng buong mundo sa loob ng 3 turn: bawasan ang bilis ng pag-recover ng galit ng lahat ng kalaban ng 15%; dagdagan ang tagal ng pinagmulan na anyo ng +1',
		starEffectDesc_ma = 'Kemahiran bentuk kritikal lain akan membalikkan seluruh dunia selama 3 giliran: mengurangkan kelajuan pemulihan kemarahan semua musuh sebanyak 15%; tempoh bentuk asal +1',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
		upLvDesc_in = 'Kerusakan tetap +192',
		upLvDesc_ph = 'Fixed damage +192',
		upLvDesc_ma = 'Kerosakan tetap +192',
		upLvDesc_vn = 'Sát thương cố định +192',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		skillType2 = 2,
		skillNatureType = 15,
		targetTypeDesc = 'Front row or all enemies',
		targetTypeDesc_vn = 'Hàng trước hoặc Toàn bộ địch',
		targetTypeDesc_en = 'Front row or all enemies',
		targetTypeDesc_th = 'แถวหน้า หรือ ศัตรูทั้งหมด',
		targetTypeDesc_in = 'Baris depan atau semua musuh',
		targetTypeDesc_ph = 'Unahang hanay o lahat ng kalaban',
		targetTypeDesc_ma = 'Baris depan atau semua musuh',
		targetChooseType = 'row',
		damageFormula = 'self:damage()*2.2+(self:flag(99) and skillLevel or skillLevel*4)*48',
		skillProcess = {2103131, 2103132, 2103133, 2103134, 2103135, 2103136},
