	[210322] = {
		id = 210322,
		skillName_vn = 'Đuôi rồng',
		skillName_en = 'Dragon tail',
		skillName_th = 'หางมังกร',
		skillName_in = 'Ekor naga',
		skillName_ph = 'Buntot ng dragon',
		skillName_ma = 'Ekor naga',
		skillName = 'Dragon tail',
		describe_vn = 'Giratina sử dụng Đuôi Rồng để tấn công một mục tiêu địch, gây #C0xE69900#170% Sát Thương Vật Lý #C0x5B545B#+$(skillLevel*4*48)$ thuộc #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, tăng khả năng giảm sát thương cho cột của anh ta thêm 15% trong 2 lượt và nhận được 2 điểm ma sau đòn tấn công\n#F20# \n#F40#[#L10#Origin Form#L0#], phạm vi tấn công thay đổi theo hàng và có thêm 80% xác suất xảy ra [#L10#Ghost Fire#L0#] trong 2 lượt\n[#L10# Netherworld Wisp#L0#]: Hiệu ứng tiêu cực đặc biệt, chỉ có thể xua tan và không thể chồng lên. Trước khi mục tiêu di chuyển hoặc khi Netherworld Wisp bị xua tan, máu của mục tiêu sẽ bị giảm (12% lượng máu tối đa của Giratina) và 120 điểm thịnh nộ.',
		describe_en = 'Giratina uses Dragon Tail to attack an enemy target, dealing #C0xE69900#170% Physical Damage #C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage #C0x5B545B#, increases his column\'s damage reduction by 15% for 2 turns, and gains 2 spirit points after the attack\n#F20# \n#F40#[#L10#Origin Form#L0#], attack range changes by row and has an 80% chance to trigger [#L10#Ghost Fire#L0#] for 2 turns\n[#L10# Netherworld Wisp#L0#]: A special negative effect that can only be dispelled and cannot stack. Before the target moves or when Netherworld Wisp is dispelled, the target’s HP is reduced (12% of Giratina’s max HP) and 120 anger points.',
		describe_th = 'Giratina ใช้หางมังกรโจมตีเป้าหมายศัตรู สร้าง #C0xE69900#170% ความเสียหายกายภาพ #C0x5B545B#+$(skillLevel*4*48)$ ของ #C0xF13B54# ความเสียหายกายภาพ #C0x5B545B# เพิ่มการลดความเสียหายของคอลัมน์ของเขาอีก 15% เป็นเวลา 2 เทิร์น และได้รับ 2 แต้มวิญญาณหลังการโจมตี \n#F20# \n#F40#[#L10#Origin Form#L0#] ระยะการโจมตีเปลี่ยนแปลงตามแถว และมีโอกาส 80% ในการเกิด [#L10#Ghost Fire#L0#] เป็นเวลา 2 เทิร์น \n[#L10# Netherworld Wisp#L0#]: ผลลบพิเศษ สามารถลบได้เท่านั้นและไม่สามารถซ้อนทับได้ ก่อนที่เป้าหมายจะเคลื่อนที่หรือเมื่อ Netherworld Wisp ถูกลบ เลือดของเป้าหมายจะลดลง (12% ของพลังชีวิตสูงสุดของ Giratina) และได้รับความโกรธ 120 แต้ม',
		describe_in = 'Giratina menggunakan Ekor Naga untuk menyerang target musuh, memberikan #C0xE69900#170% Damage Fisik #C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54# Damage Fisik #C0x5B545B#, meningkatkan kemampuan pengurangan damage kolomnya sebesar 15% selama 2 giliran dan mendapatkan 2 poin roh setelah serangan\n#F20# \n#F40#[#L10#Origin Form#L0#], jangkauan serangan berubah menurut baris dan memiliki peluang 80% untuk memicu [#L10#Ghost Fire#L0#] selama 2 giliran\n[#L10# Netherworld Wisp#L0#]: Efek negatif khusus, hanya dapat dihapus dan tidak dapat bertumpuk. Sebelum target bergerak atau ketika Netherworld Wisp dihapus, HP target akan berkurang (12% dari HP maksimum Giratina) dan 120 poin kemarahan.',
		describe_ph = 'Giratina ay gamit ang Dragon Tail upang atakihin ang isang kaaway na target, na nagdudulot ng #C0xE69900#170% Pisikal na Pinsala #C0x5B545B#+$(skillLevel*4*48)$ ng #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, pinapataas ang kakayahan ng pagbawas ng pinsala ng kanyang hanay ng 15% sa loob ng 2 turn at tumatanggap ng 2 puntos ng kaluluwa pagkatapos ng atake\n#F20# \n#F40#[#L10#Origin Form#L0#], ang saklaw ng atake ay nagbabago ayon sa hilera at may 80% tsansa na mag-trigger ng [#L10#Ghost Fire#L0#] sa loob ng 2 turn\n[#L10# Netherworld Wisp#L0#]: Isang espesyal na negatibong epekto na maaari lamang alisin at hindi pwedeng mag-stack. Bago gumalaw ang target o kapag naalis ang Netherworld Wisp, mababawasan ang HP ng target (12% ng maximum HP ni Giratina) at 120 puntos ng galit.',
		describe_ma = 'Giratina menggunakan Ekor Naga untuk menyerang sasaran musuh, menyebabkan #C0xE69900#170% Kerosakan Fizikal #C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, meningkatkan keupayaan pengurangan kerosakan untuk kolumnya sebanyak 15% selama 2 pusingan dan menerima 2 mata roh selepas serangan\n#F20# \n#F40#[#L10#Origin Form#L0#], julat serangan berubah mengikut baris dan mempunyai peluang 80% untuk mencetuskan [#L10#Ghost Fire#L0#] selama 2 pusingan\n[#L10# Netherworld Wisp#L0#]: Kesan negatif khas, hanya boleh dihapus dan tidak boleh bertindih. Sebelum sasaran bergerak atau apabila Netherworld Wisp dihapus, darah sasaran akan berkurang (12% daripada darah maksimum Giratina) dan 120 mata kemarahan.',
		describe = 'Giratina uses Dragon Tail to attack an enemy target, dealing #C0xE69900#170% Physical Damage #C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage #C0x5B545B#, increases his column\'s damage reduction by 15% for 2 turns, and gains 2 spirit points after the attack\n#F20# \n#F40#[#L10#Origin Form#L0#], attack range changes by row and has an 80% chance to trigger [#L10#Ghost Fire#L0#] for 2 turns\n[#L10# Netherworld Wisp#L0#]: A special negative effect that can only be dispelled and cannot stack. Before the target moves or when Netherworld Wisp is dispelled, the target’s HP is reduced (12% of Giratina’s max HP) and 120 anger points.',
		simDesc_vn = 'Kira Đế Tân sử dụng đuôi rồng tấn công mục tiêu đơn lẻ của kẻ thù, gây sát thương vật lý, tăng giới hạn tức giận của mục tiêu và bản thân nhận điểm ma quái; trong trạng thái nguồn gốc, phạm vi tấn công chuyển thành hàng và có xác suất kèm theo hồn ma.',
		simDesc_en = 'Kira Đế Tân uses a dragon tail to attack a single enemy target, dealing physical damage, increasing the target\'s rage limit, and gaining spirit points for himself; in the origin state, the attack range changes to a row and has a chance to summon a ghost.',
		simDesc_th = 'Kira Đế Tân ใช้หางมังกรโจมตีเป้าหมายศัตรูรายเดียว สร้างความเสียหายทางกายภาพ เพิ่มขีดจำกัดความโกรธของเป้าหมาย และได้รับคะแนนวิญญาณสำหรับตัวเอง; ในสภาวะแหล่งกำเนิด ระยะการโจมตีเปลี่ยนเป็นแถวและมีโอกาสเรียกผีร่วมด้วย',
		simDesc_in = 'Kira Đế Tân menggunakan ekor naga untuk menyerang satu target musuh, memberikan kerusakan fisik, meningkatkan batas kemarahan target dan mendapatkan poin roh untuk dirinya sendiri; dalam keadaan asal, jangkauan serangan berubah menjadi barisan dan memiliki kemungkinan untuk memanggil hantu.',
		simDesc_ph = 'Gumagamit si Kira Đế Tân ng buntot ng dragon upang atakihin ang isang solong target ng kalaban, na nagdudulot ng pisikal na pinsala, nagpapataas ng hangganan ng galit ng target, at kumikita ng puntos ng espiritu para sa kanyang sarili; sa estado ng pinagmulan, nagbabago ang saklaw ng pag-atake sa isang hanay at may tsansa na magdala ng multo.',
		simDesc_ma = 'Kira Đế Tân menggunakan ekor naga untuk menyerang sasaran musuh tunggal, memberi kerosakan fizikal, meningkatkan had kemarahan sasaran dan memperoleh mata roh untuk dirinya sendiri; dalam keadaan asal, julat serangan berubah menjadi barisan dan berpeluang memanggil hantu.',
		simDesc = 'Kira Đế Tân uses a dragon tail to attack a single enemy target, dealing physical damage, increasing the target\'s rage limit, and gaining spirit points for himself; in the origin state, the attack range changes to a row and has a chance to summon a ghost.',
		upLvDesc = 'Fixed damage +192',
