	[210323] = {
		id = 210323,
		skillName_vn = 'Thế giới đảo ngược',
		skillName_en = 'The reversed world',
		skillName_th = 'โลกที่กลับด้าน',
		skillName_in = 'Dunia terbalik',
		skillName_ph = 'Ang baligtad na mundo',
		skillName_ma = 'Dunia terbalik',
		skillName = 'The reversed world',
		describe_vn = 'Giratina một lần nữa triệu hồi lối vào thế giới ngược để đẩy toàn bộ đơn vị địch xuống vực thẳm vô tận, gây #C0xE69900#230% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, giảm cơn thịnh nộ của mục tiêu trúng đòn 250 điểm và nhận 3 điểm ma sau đó tấn công\n#F20# \n#F40#Sau khi thực hiện chiêu thức đặc biệt, anh ta chuyển sang [#L10#Origin Form#L0#] trong 2 hiệp. Giới hạn trên của lượng máu của chính anh ta (chỉ tăng giới hạn trên), tốc độ và tỷ lệ kiểm soát tổng thể được tăng thêm 50% (không thể phân tán, chuyển giao hoặc sao chép). Chuyển sang chiêu thức đặc biệt mới (không cần nộ và không tiêu hao nộ khi phóng ra, hồi lại trong 2 lượt sau khi phóng): Phạm vi thay đổi đối với tất cả kẻ địch và có thêm 75% xác suất thêm [#L10#鬼鬼火#L0#] vào 4 tướng địch có nộ cao nhất trong 2 lượt.',
		describe_en = 'Giratina summons the entrance to the reverse world once again to push all enemy units into the endless abyss, causing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, reducing the target\'s fury by 250 points and gaining 3 mana points. Then attack\n#F20# \n#F40# After executing the special move, he shifts into [#L10#Origin Form#L0#] for 2 turns. His maximum HP limit (only increasing the upper limit), speed, and overall control rate are increased by 50% (cannot be dispersed, transferred, or copied). Switches to a new special move (no energy required and no energy consumed when launched, recovers in 2 turns after launching): Range changes to all enemies and has a 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy units with the highest energy for 2 turns.',
		describe_th = 'กิราไทน่าเรียกประตูสู่โลกกลับด้านอีกครั้งเพื่อผลักหน่วยศัตรูทั้งหมดตกลงสู่เหวลึกไม่มีที่สิ้นสุด สร้าง #C0xE69900#230% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ลดความโกรธของเป้าหมายที่ถูกโจมตี 250 แต้มและได้รับ 3 แต้มมานา จากนั้นโจมตี\n#F20# \n#F40# หลังจากใช้ท่าพิเศษ เขาจะเปลี่ยนเป็น [#L10#Origin Form#L0#] เป็นเวลา 2 เทิร์น ขีดจำกัดสูงสุดของพลังชีวิตของเขา (เพิ่มแค่ขีดจำกัดสูงสุด), ความเร็ว และอัตราการควบคุมรวมเพิ่มขึ้น 50% (ไม่สามารถแจกจ่าย โอน หรือคัดลอกได้) เปลี่ยนไปใช้ท่าพิเศษใหม่ (ไม่ต้องใช้พลังและไม่ลดพลังเมื่อโจมตี ฟื้นฟูใน 2 เทิร์นหลังโจมตี): ระยะโจมตีเปลี่ยนเป็นทั้งหมดของศัตรู และมีโอกาส 75% ที่จะเพิ่ม [#L10#鬼鬼火#L0#] ให้กับ 4 หน่วยศัตรูที่มีพลังงานสูงสุดเป็นเวลา 2 เทิร์น',
		describe_in = 'Giratina sekali lagi memanggil pintu masuk ke dunia terbalik untuk mendorong semua unit musuh ke dalam jurang tak berujung, menyebabkan #C0xE69900#230% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, mengurangi amarah target sebanyak 250 poin dan mendapatkan 3 poin mana. Kemudian menyerang\n#F20# \n#F40# Setelah melakukan gerakan khusus, dia beralih ke [#L10#Origin Form#L0#] selama 2 giliran. Batas atas HP-nya (hanya meningkatkan batas atas), kecepatan, dan tingkat kontrol keseluruhan meningkat sebesar 50% (tidak dapat disebarkan, dialihkan, atau disalin). Beralih ke gerakan khusus baru (tidak memerlukan energi dan tidak menguras energi saat diluncurkan, pulih dalam 2 giliran setelah diluncurkan): Jangkauan berubah menjadi semua musuh dan memiliki peluang 75% untuk menambahkan [#L10#鬼鬼火#L0#] pada 4 unit musuh dengan energi tertinggi selama 2 giliran.',
		describe_ph = 'Muling tinawag ni Giratina ang daan sa baligtarang mundo upang itulak ang lahat ng yunit ng kalaban sa walang katapusang kailaliman, na nagdudulot ng #C0xE69900#230% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, binabawasan ang galit ng tinatamaan ng 250 puntos at tumatanggap ng 3 puntos ng mana. Pagkatapos ay umatake\n#F20# \n#F40# Pagkatapos isagawa ang espesyal na galaw, siya ay lilipat sa [#L10#Origin Form#L0#] sa loob ng 2 turn. Ang pinakamataas na hangganan ng kanyang HP (tanging pataasin ang pinakamataas na hangganan), bilis, at pangkalahatang rate ng kontrol ay tataas ng 50% (hindi maaaring ipamahagi, ilipat, o kopyahin). Lumilipat sa bagong espesyal na galaw (hindi kailangan ang enerhiya at hindi kumukonsumo ng enerhiya kapag inilulunsad, bumabalik sa loob ng 2 turn pagkatapos ilunsad): Nagbabago ang saklaw sa lahat ng kalaban at may 75% na pagkakataon na magdagdag ng [#L10#鬼鬼火#L0#] sa 4 na pangkat ng kalaban na may pinakamataas na enerhiya sa loob ng 2 turn.',
		describe_ma = 'Giratina sekali lagi memanggil pintu masuk ke dunia songsang untuk menolak semua unit musuh ke gaung tanpa batas, menyebabkan #C0xE69900#230% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, mengurangkan kemarahan sasaran yang terkena sebanyak 250 mata dan menerima 3 mata mana. Kemudian menyerang\n#F20# \n#F40# Selepas melaksanakan gerakan istimewa, dia bertukar ke [#L10#Origin Form#L0#] selama 2 pusingan. Had atas jumlah darahnya (hanya meningkatkan had atas), kelajuan, dan kadar kawalan keseluruhan meningkat sebanyak 50% (tidak boleh diagihkan, dipindahkan atau disalin). Bertukar ke gerakan istimewa baru (tidak memerlukan tenaga dan tidak memakan tenaga semasa dilancarkan, pulih dalam 2 pusingan selepas pelancaran): Julat berubah kepada semua musuh dan mempunyai 75% peluang untuk menambah [#L10#鬼鬼火#L0#] kepada 4 unit musuh yang mempunyai tenaga tertinggi selama 2 pusingan.',
		describe = 'Giratina summons the entrance to the reverse world once again to push all enemy units into the endless abyss, causing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, reducing the target\'s fury by 250 points and gaining 3 mana points. Then attack\n#F20# \n#F40# After executing the special move, he shifts into [#L10#Origin Form#L0#] for 2 turns. His maximum HP limit (only increasing the upper limit), speed, and overall control rate are increased by 50% (cannot be dispersed, transferred, or copied). Switches to a new special move (no energy required and no energy consumed when launched, recovers in 2 turns after launching): Range changes to all enemies and has a 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy units with the highest energy for 2 turns.',
		simDesc_vn = 'Kira Đế Tân một lần nữa triệu hồi cổng vào thế giới đảo ngược, khiến toàn bộ đơn vị kẻ thù rơi vào vực sâu vô tận, gây sát thương vật lý, giảm giá trị tức giận của chúng và có xác suất rất cao kèm theo hồn ma.',
		simDesc_en = 'Kira Ten once again summons the gateway to the inverted world, causing all enemy units to fall into an endless abyss, dealing physical damage, reducing their anger levels, and having a very high chance to accompany with a ghost spirit.',
		simDesc_th = 'คิระ เท็น ได้เรียกประตูสู่โลกกลับด้านอีกครั้ง ทำให้หน่วยศัตรูทั้งหมดตกลงสู่หุบเหวนิรันดร์ก่อให้เกิดความเสียหายทางกายภาพ ลดค่าความโกรธของพวกเขา และมีโอกาสสูงมากที่จะมาพร้อมกับวิญญาณผี',
		simDesc_in = 'Kira Ten sekali lagi memanggil gerbang ke dunia terbalik, menyebabkan semua unit musuh jatuh ke dalam jurang tak berujung, memberikan kerusakan fisik, mengurangi nilai kemarahan mereka, dan memiliki kemungkinan sangat tinggi disertai dengan roh hantu.',
		simDesc_ph = 'Muling tinawag ni Kira Ten ang tarangkahan papasok sa salungat na mundo, na nagdudulot sa lahat ng kalaban na yunit na mahulog sa walang hanggang bangin, nagdudulot ng pisikal na pinsala, nagpapababa ng kanilang antas ng galit, at may mataas na tsansa na samahan ng espiritu ng multo.',
		simDesc_ma = 'Kira Ten sekali lagi memanggil pintu gerbang ke dunia terbalik, menyebabkan semua unit musuh jatuh ke dalam jurang tanpa penghujung, memberikan kerosakan fizikal, mengurangkan nilai kemarahan mereka, dan mempunyai kemungkinan yang sangat tinggi disertai dengan roh hantu.',
		simDesc = 'Kira Ten once again summons the gateway to the inverted world, causing all enemy units to fall into an endless abyss, dealing physical damage, reducing their anger levels, and having a very high chance to accompany with a ghost spirit.',
		starEffect = __data_t__starEffect[210323],
		-- {11}
		starEffectDesc_vn = 'Kỹ năng chí mạng hình thái khác sẽ đảo ngược toàn bộ thế giới kéo dài 3 lượt: giảm tốc độ hồi phục tức giận của toàn bộ địch 15%; số lượt duy trì của hình thái nguồn gốc +1',
		starEffectDesc = 'Different form critical skill will invert the entire world for 3 turns: reduce all enemies\' anger recovery speed by 15%; origin form\'s duration +1',
		starEffectDesc_en = 'Different form critical skill will invert the entire world for 3 turns: reduce all enemies\' anger recovery speed by 15%; origin form\'s duration +1',
		starEffectDesc_th = 'ทักษะคริติคัลรูปร่างต่างจะทำให้โลกทั้งใบกลับด้านเป็นเวลา 3 เทิร์น: ลดความเร็วฟื้นฟูความโกรธของศัตรูทั้งหมดลง 15%; ระยะเวลารูปร่างต้นกำเนิด +1',
		starEffectDesc_in = 'Skill kritis bentuk berbeda akan membalik seluruh dunia selama 3 giliran: mengurangi kecepatan pemulihan amarah musuh sebesar 15%; durasi bentuk asal +1',
		starEffectDesc_ph = 'Ang iba’t ibang anyo ng kritikal na kasanayan ay mag-iinvert ng buong mundo sa loob ng 3 turn: bawasan ang bilis ng pagbawi ng galit ng lahat ng kalaban ng 15%; dagdagan ng 1 ang tagal ng anyo ng pinagmulan',
		starEffectDesc_ma = 'Kemahiran kritikal bentuk berbeza akan memutar balikkan seluruh dunia selama 3 pusingan: mengurangkan kelajuan pulih kemarahan semua musuh sebanyak 15%; tempoh bentuk asal +1',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
		upLvDesc_in = 'Kerusakan tetap +192',
