	[210326] = {
		id = 210326,
		skillName_vn = 'Bóng ma dày đặc',
		skillName_en = 'Dense ghost',
		skillName_th = 'ผีหนาแน่น',
		skillName_in = 'Hantu yang padat',
		skillName_ph = 'Mabangis na multo',
		skillName_ma = 'Hantu tebal',
		skillName = 'Dense ghost',
		describe_vn = 'Khi Giratio bước vào hiện trường, anh ta sẽ nhận được số lượng hồn ma của các anh hùng trong trại của mình ngoài chính mình (giới hạn trên của số lượng ma: 5 điểm, không thể xua tan hoặc bỏ qua), và mỗi hồn ma có thể giảm số lượng hồn ma của mình #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# Sát thương cuối cùng nhận được sẽ giảm 1 hồn ma mỗi khi trúng đòn. Khi bóng ma giảm đi, 80 điểm thịnh nộ sẽ được phục hồi\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn, bạn và anh hùng có phần trăm máu thấp nhất ở hàng sau trong đội của bạn sẽ nhận được [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: lượng khiên bằng 15% máu tối đa của Giratina. , không thể chồng lên, mục tiêu tấn công khiên ma sẽ yếu: đòn tấn công kép giảm 15% trong 2 lượt); khi chuyển sang dạng gốc, 30% lượng HP đã mất có thể được phục hồi (không bị ảnh hưởng bởi phương pháp điều trị bị cấm) và bản thân sẽ không tái sinh khi tấn công ở dạng gốc.',
		describe_en = 'When Giratio enters the battlefield, he will receive a number of hero spirits from his camp besides himself (maximum spirit count: 5, cannot be dispelled or ignored), and each spirit can reduce his own spirit count by #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Each final hit received reduces the spirit count by one. When the spirits decrease, 80 fury points will be restored \n#F20# \n#F40#. At the start of each major round, you and the hero in your team’s back row with the lowest health percentage will receive the [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: a shield equal to 15% of Giratina\'s maximum HP; cannot stack; targets hit by the ghost shield will be weakened: dual attacks are reduced by 15% for 2 turns). When reverting to original form, 30% of lost HP can be restored (not affected by banned healing methods) and Giratio will not revive when attacking in original form.',
		describe_th = 'เมื่อ Giratio เข้าสู่สนามรบ เขาจะได้รับจำนวนวิญญาณฮีโร่จากค่ายของเขานอกเหนือจากตัวเอง (จำนวนสูงสุดของวิญญาณ: 5 ไม่สามารถขจัดหรือละเลยได้) และแต่ละวิญญาณสามารถลดจำนวนวิญญาณของตัวเองได้ #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# ความเสียหายครั้งสุดท้ายที่ได้รับจะลดจำนวนวิญญาณลงหนึ่งตัวทุกครั้งที่โดน เมื่อจำนวนวิญญาณลดลง จะฟื้นฟูความโกรธ 80 คะแนน \n#F20# \n#F40# เมื่อเริ่มรอบใหญ่แต่ละรอบ คุณและฮีโร่ที่มีเปอร์เซ็นต์เลือดต่ำที่สุดในแถวหลังของทีมจะได้รับ [#L10# Ghost Shield #L0#] ([#L10# Ghost Shield #L0#]: โล่เท่ากับ 15% ของพลังชีวิตสูงสุดของ Giratio ไม่สามารถซ้อนทับได้ เป้าหมายที่โจมตีโล่วิญญาณจะอ่อนแอ: การโจมตีคู่จะลดลง 15% เป็นเวลา 2 ตา) เมื่อกลับสู่รูปแบบดั้งเดิม จะฟื้นฟู HP ที่เสียไป 30% (ไม่ถูกผลกระทบจากวิธีการรักษาที่ถูกแบน) และตัวเองจะไม่ฟื้นคืนชีพเมื่อโจมตีในรูปแบบดั้งเดิม',
		describe_in = 'Ketika Giratio memasuki medan pertempuran, dia akan menerima sejumlah roh pahlawan dari kampnya selain dirinya sendiri (batas atas jumlah roh: 5, tidak dapat dibasmi atau diabaikan), dan setiap roh dapat mengurangi jumlah rohnya sendiri sebesar #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Setiap serangan terakhir yang diterima akan mengurangi jumlah roh sebanyak satu. Ketika roh berkurang, 80 poin kemarahan akan dipulihkan \n#F20# \n#F40#. Pada awal setiap ronde besar, kamu dan pahlawan dengan persentase HP terendah di barisan belakang timmu akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: perisai sebesar 15% dari HP maksimum Giratio, tidak dapat ditumpuk, target yang menyerang perisai hantu akan melemah: serangan ganda berkurang 15% selama 2 giliran). Saat kembali ke bentuk asli, 30% HP yang hilang dapat dipulihkan (tidak terpengaruh oleh metode penyembuhan yang dilarang), dan dia tidak akan bangkit kembali saat menyerang dalam bentuk asli.',
		describe_ph = 'Kapag pumasok si Giratio sa lugar ng laban, matatanggap niya ang bilang ng mga kaluluwa ng mga bayani sa kanyang kampo maliban sa kanyang sarili (limitasyon sa bilang ng mga kaluluwa: 5, hindi maaaring alisin o balewalain), at bawat kaluluwa ay maaaring magpababa ng kanyang sariling bilang ng kaluluwa ng #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Bawat huling tama na matatanggap ay magbabawas ng isang kaluluwa. Kapag bumaba ang bilang ng mga kaluluwa, 80 puntos ng galit ang mare-restore \n#F20# \n#F40#. Sa simula ng bawat malaking round, ikaw at ang bayani na may pinakamababang porsyento ng HP sa likod ng inyong koponan ay makakatanggap ng [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: isang shield na katumbas ng 15% ng maximum HP ni Giratio, hindi pwedeng pagsabayin, ang mga target na tumatama sa ghost shield ay magiging mahina: doble ang pinsalang atake ay nababawasan ng 15% sa loob ng 2 turn). Kapag bumalik sa orihinal na anyo, 30% ng nawalang HP ay maibabalik (hindi naapektuhan ng mga pinagbawal na paraan ng pagpapagaling) at hindi siya magpapatuloy pa kapag umatake sa orihinal na anyo.',
		describe_ma = 'Apabila Giratio memasuki medan pertempuran, dia akan menerima sejumlah roh wira dari kemnya selain dirinya sendiri (had maksimum jumlah roh: 5, tidak boleh dibersihkan atau diabaikan), dan setiap roh boleh mengurangkan jumlah rohnya sendiri sebanyak #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Setiap serangan akhir yang diterima akan mengurangkan jumlah roh sebanyak satu. Apabila roh berkurang, 80 mata kemarahan akan dipulihkan \n#F20# \n#F40#. Pada permulaan setiap pusingan besar, anda dan wira dengan peratusan darah terendah di barisan belakang dalam pasukan anda akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: perisai bersamaan dengan 15% HP maksima Giratio, tidak boleh bertindih, sasaran yang menyerang perisai hantu akan menjadi lemah: serangan berganda dikurangkan sebanyak 15% selama 2 pusingan). Apabila kembali ke bentuk asal, 30% HP yang hilang dapat dipulihkan (tidak terjejas oleh kaedah penyembuhan yang diharamkan) dan dirinya tidak akan bangkit semula apabila menyerang dalam bentuk asal.',
		describe = 'When Giratio enters the battlefield, he will receive a number of hero spirits from his camp besides himself (maximum spirit count: 5, cannot be dispelled or ignored), and each spirit can reduce his own spirit count by #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Each final hit received reduces the spirit count by one. When the spirits decrease, 80 fury points will be restored \n#F20# \n#F40#. At the start of each major round, you and the hero in your team’s back row with the lowest health percentage will receive the [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: a shield equal to 15% of Giratina\'s maximum HP; cannot stack; targets hit by the ghost shield will be weakened: dual attacks are reduced by 15% for 2 turns). When reverting to original form, 30% of lost HP can be restored (not affected by banned healing methods) and Giratio will not revive when attacking in original form.',
		starEffect = __data_t__starEffect[210326],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Quỷ khiên nâng cấp: tăng 5% lượng khiên, mỗi lượt lớn kết thúc bản thân nhận 1 điểm Quỷ ảnh',
		starEffectDesc = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
		starEffectDesc_en = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
		starEffectDesc_th = 'เอฟเฟกต์การอัปเกรดโล่ปีศาจ: เพิ่มปริมาณโล่ 5% เมื่อสิ้นสุดแต่ละเทิร์นใหญ่ รับ 1 คะแนนเงาปีศาจ',
		starEffectDesc_in = 'Efek Peningkatan Perisai Setan: meningkatkan jumlah perisai sebesar 5%, pada akhir setiap giliran besar, menerima 1 poin Bayangan Setan',
		starEffectDesc_ph = 'Epekto ng Pag-upgrade ng Demon Shield: nagdaragdag ng 5% sa dami ng shield, sa pagtatapos ng bawat malaking turn ay tumatanggap ng 1 Demon Shadow point',
		starEffectDesc_ma = 'Kesan Naik Taraf Perisai Iblis: meningkatkan jumlah perisai sebanyak 5%, pada akhir setiap giliran besar, menerima 1 mata Bayangan Iblis',
		changeUnitTrigger = true,
