	},
	[210411] = {
		id = 210411,
		skillName_vn = 'Gió kỳ lạ',
		skillName_en = 'Strange wind',
		skillName_th = 'ลมประหลาด',
		skillName_in = 'Angin aneh',
		skillName_ph = 'Kakaibang hangin',
		skillName_ma = 'Angin pelik',
		skillName = 'Strange wind',
		describe_vn = 'Giratina đập mặt đất triệu hồi gió kỳ dị tấn công mục tiêu đơn thể địch, gây #C0xE69900#100% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ Sát Thương Vật Lý#C0xF13B54#, tăng 50% phòng thủ đôi của bản thân trong 2 lượt, sau khi tấn công bản thân nhận 1 điểm bóng ma',
		describe_en = 'Giratina slams the ground to summon strange winds that attack a single enemy target, dealing #C0xE69900#100% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ Physical Damage#C0xF13B54#, increases own double defense by 50% for 2 turns, after attacking gains 1 shadow point.',
		describe_th = 'กิราติน่าทุบพื้นเพื่อเรียกลมประหลาดโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายทางกายภาพ #C0xE69900#100% พลังโจมตี#C0x5B545B#+$(skillLevel*4*24)$ ความเสียหายทางกายภาพ#C0xF13B54# เพิ่มการป้องกันแบบคู่ของตนเองขึ้น 50% เป็นเวลา 2 เทิร์น หลังจากโจมตี รับ 1 จุดเงา',
		describe_in = 'Giratina menghantam tanah memanggil angin aneh yang menyerang satu target musuh, memberikan #C0xE69900#100% Serangan Fisik#C0x5B545B#+$(skillLevel*4*24)$ Kerusakan Fisik#C0xF13B54#, meningkatkan pertahanan ganda diri sendiri sebesar 50% selama 2 giliran, setelah menyerang mendapatkan 1 poin bayangan.',
		describe_ph = 'Inihampas ni Giratina ang lupa para tumawag ng kakaibang hangin na umaatake sa isang target na kalaban, na nagdudulot ng #C0xE69900#100% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ Physical Damage#C0xF13B54#, nagpapataas ng sariling doble depensa ng 50% sa loob ng 2 turn, pagkatapos umatake ay nakakakuha ng 1 shadow point.',
		describe_ma = 'Giratina menumbuk tanah untuk memanggil angin aneh yang menyerang satu sasaran musuh, menyebabkan #C0xE69900#100% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ Kerosakan Fizikal#C0xF13B54#, meningkatkan pertahanan berganda diri sendiri sebanyak 50% selama 2 giliran, selepas menyerang menerima 1 mata bayang.',
		describe = 'Giratina slams the ground to summon strange winds that attack a single enemy target, dealing #C0xE69900#100% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ Physical Damage#C0xF13B54#, increases own double defense by 50% for 2 turns, after attacking gains 1 shadow point.',
		simDesc_vn = 'Kira Đế Tân đập xuống mặt đất, triệu hồi gió kỳ lạ tấn công mục tiêu đơn lẻ của kẻ thù, gây sát thương vật lý, tăng cường khả năng giảm sát thương của bản thân và hồi phục điểm ma quái.',
		simDesc_en = 'Kira Đế Tân slams down to the ground, summoning a strange wind to attack a single enemy target, dealing physical damage, enhancing self damage reduction, and restoring demonic points.',
		simDesc_th = 'Kira Đế Tân ต่อยลงพื้น เรียกลมประหลาดโจมตีเป้าหมายศัตรูเดียว สร้างความเสียหายทางกายภาพ เพิ่มความสามารถป้องกันความเสียหายของตัวเอง และฟื้นฟูพลังปีศาจ',
		simDesc_in = 'Kira Đế Tân menghantam tanah, memanggil angin aneh untuk menyerang satu target musuh, memberikan kerusakan fisik, meningkatkan kemampuan pengurangan kerusakan sendiri, dan memulihkan poin iblis.',
		simDesc_ph = 'Pinabagsak ni Kira Đế Tân ang lupa, nagpanawag ng kakaibang hangin upang atakihin ang isang kaaway na target, nagdudulot ng pisikal na pinsala, pinalalakas ang kakayahan sa pagbawas ng pinsala sa sarili, at nagpapagaling ng demonic points.',
		simDesc_ma = 'Kira Đế Tân memukul tanah, memanggil angin pelik untuk menyerang sasaran musuh tunggal, menyebabkan kerosakan fizikal, meningkatkan keupayaan pengurangan kerosakan diri dan memulihkan mata iblis.',
		simDesc = 'Kira Đế Tân slams down to the ground, summoning a strange wind to attack a single enemy target, dealing physical damage, enhancing self damage reduction, and restoring demonic points.',
		upLvDesc = 'Fixed damage +96',
		upLvDesc_en = 'Fixed damage +96',
		upLvDesc_th = 'ความเสียหายคงที่ +96',
		upLvDesc_in = 'Kerusakan tetap +96',
		upLvDesc_ph = 'Fixed damage +96',
		upLvDesc_ma = 'Kerosakan tetap +96',
		upLvDesc_vn = 'Sát thương cố định +96',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		skillType2 = 0,
		skillNatureType = 14,
		posChoose = 1,
