	[210412] = {
		id = 210412,
		skillName_vn = 'Đòn tấn công bóng',
		skillName_en = 'Shadow attack',
		skillName_th = 'การโจมตีเงา',
		skillName_in = 'Serangan bayangan',
		skillName_ph = 'Anino ng atake',
		skillName_ma = 'Serangan bayangan',
		skillName = 'Shadow attack',
		describe_vn = 'Giratina biến thành ma và di chuyển đến một mục tiêu địch để đánh lén, gây #C0xE69900#170% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B# tăng khả năng giảm sát thương của cột mình thêm 15% trong 2 lượt. Sau khi tấn công, bản thân nhận được 2 điểm ma\n#F20# \n#F40#[#L10#Origin Form#L0#], phạm vi tấn công thay đổi theo hàng và có thêm 80% xác suất [#L10#Ghost Fire#L0#] trong 2 lượt\n[#L10# Netherworld Wisp#L0#]: Hiệu ứng tiêu cực đặc biệt, chỉ có thể xua tan và không thể áp dụng. Trước khi mục tiêu di chuyển hoặc khi Netherworld Wisp bị xua tan, máu của mục tiêu sẽ bị giảm (12% lượng máu tối đa của Giratina) và 120 điểm thịnh nộ.',
		describe_en = 'Giratina transforms into a ghost and moves to an enemy target to ambush, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#. It increases the column\'s damage reduction by 15% for 2 turns. After attacking, Giratina gains 2 points of ma\n#F20# \n#F40#[#L10#Origin Form#L0#], with attack range changing by row and an 80% chance to apply [#L10#Ghost Fire#L0#] for 2 turns. \n[#L10# Netherworld Wisp#L0#]: A special negative effect that can only be dispelled and cannot be applied. Before the target moves or when Netherworld Wisp is dispelled, the target\'s HP is reduced by (12% of Giratina\'s max HP) and 120 rage points.',
		describe_th = 'Giratina แปลงร่างเป็นผีและเคลื่อนที่ไปยังเป้าหมายศัตรูเพื่อลอบโจมตี ทำ #C0xE69900#170% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# เพิ่มความสามารถในการลดความเสียหายของแถวตัวเองเพิ่มขึ้น 15% ใน 2 เทิร์น หลังโจมตี ตัวเองได้รับ 2 คะแนน ma\n#F20# \n#F40#[#L10#ต้นแบบ#L0#] ขอบเขตการโจมตีเปลี่ยนแปลงตามแถว และมีโอกาส 80% ที่จะได้รับ [#L10#ไฟผี#L0#] เป็นเวลา 2 เทิร์น \n[#L10#เนเธอร์เวิร์ล วิสป#L0#]: เอฟเฟคติดลบพิเศษที่สามารถลบได้เท่านั้นและไม่สามารถซ้อนทับ ก่อนที่เป้าหมายจะเคลื่อนที่หรือเมื่อเนเธอร์เวิร์ล วิสปถูกลบ พลังชีวิตของเป้าหมายจะลดลง (12% ของพลังชีวิตสูงสุดของ Giratina) และเพิ่มความโกรธ 120 แต้ม',
		describe_in = 'Giratina berubah menjadi hantu dan bergerak ke target musuh untuk menyerang diam-diam, memberikan #C0xE69900#170% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Kerusakan Fisik #C0x5B545B#. Meningkatkan kemampuan pengurangan kerusakan kolom sendiri sebesar 15% selama 2 giliran. Setelah menyerang, Giratina menerima 2 poin ma\n#F20# \n#F40#[#L10#Bentuk Asal#L0#], jangkauan serangan berubah sesuai baris dan memiliki peluang 80% mendapatkan efek [#L10#Api Hantu#L0#] selama 2 giliran. \n[#L10#Bisikan Alam Bawah#L0#]: Efek negatif khusus yang hanya bisa dihilangkan dan tidak bisa diterapkan. Sebelum target bergerak atau saat Bisikan Alam Bawah dihilangkan, HP target akan berkurang (12% dari HP maksimum Giratina) dan 120 poin kemarahan.',
		describe_ph = 'Nagiging espiritu si Giratina at lumalapit sa isang kalaban upang umatake nang palihim, nagdudulot ng #C0xE69900#170% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Pisikal na Pinsala #C0x5B545B#. Pinapataas ang kakayahang bawasan ang pinsala ng sariling hanay ng 15% sa loob ng 2 turn. Pagkatapos umatake, nakakatanggap si Giratina ng 2 puntos ng ma\n#F20# \n#F40#[#L10#Orihinal na Anyò#L0#], nagbabago ang saklaw ng atake ayon sa hilera at may 80% tsansa na magkaroon ng [#L10#Apoy ng Multo#L0#] sa loob ng 2 turn. \n[#L10#Netherworld Wisp#L0#]: Isang espesyal na negatibong epektong maaari lamang mapawi at hindi maaaring ipatupad. Bago kumilos ang target o kapag napawi ang Netherworld Wisp, mababawasan ang HP ng target ng (12% ng max HP ni Giratina) at 120 na puntos ng galit.',
		describe_ma = 'Giratina berubah menjadi hantu dan bergerak ke sasaran musuh untuk menyerang secara tiba-tiba, menyebabkan #C0xE69900#170% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Kerosakan Fizikal #C0x5B545B#. Meningkatkan keupayaan pengurangan kerosakan kolum sendiri sebanyak 15% selama 2 giliran. Selepas menyerang, Giratina menerima 2 mata ma\n#F20# \n#F40#[#L10#Bentuk Asal#L0#], julat serangan berubah mengikut baris dan ada 80% peluang untuk mendapat [#L10#Api Hantu#L0#] selama 2 giliran. \n[#L10#Bisikan Dunia Bawah#L0#]: Kesan negatif khas yang hanya boleh dibersihkan dan tidak boleh digunakan. Sebelum sasaran bergerak atau apabila Bisikan Dunia Bawah dibersihkan, HP sasaran akan berkurang (12% daripada HP maksimum Giratina) dan 120 mata kemarahan.',
		describe = 'Giratina transforms into a ghost and moves to an enemy target to ambush, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#. It increases the column\'s damage reduction by 15% for 2 turns. After attacking, Giratina gains 2 points of ma\n#F20# \n#F40#[#L10#Origin Form#L0#], with attack range changing by row and an 80% chance to apply [#L10#Ghost Fire#L0#] for 2 turns. \n[#L10# Netherworld Wisp#L0#]: A special negative effect that can only be dispelled and cannot be applied. Before the target moves or when Netherworld Wisp is dispelled, the target\'s HP is reduced by (12% of Giratina\'s max HP) and 120 rage points.',
		simDesc_vn = 'Kira Đế Tân biến hình thành bóng ma, di chuyển đến trước mục tiêu đơn lẻ của kẻ thù để tấn công lén, gây sát thương vật lý, đồng thời tăng giới hạn tức giận của mục tiêu và bản thân nhận điểm ma quái; trong trạng thái nguồn gốc, phạm vi tấn công chuyển thành hàng và có xác suất kèm theo hồn ma.',
		simDesc_en = 'Kira The New Emperor transforms into a ghost, moving to a single enemy target for a stealth attack, dealing physical damage, while increasing the rage limit of the target and gaining demonic points for himself; in origin state, the attack range changes to a row and has a chance to summon a ghost.',
		simDesc_th = 'คิระ จักรพรรดิ์ใหม่ เปลี่ยนร่างเป็นผี วิ่งไปยังเป้าหมายศัตรูเดี่ยวเพื่อโจมตีลับ ทำดาเมจทางกายภาพ พร้อมทั้งเพิ่มขีดจำกัดความโกรธของเป้าหมายและได้รับคะแนนปีศาจ; ในสถานะต้นกำเนิด ระยะการโจมตีเปลี่ยนเป็นแบบแถว และมีโอกาสเรียกผีตามมา',
		simDesc_in = 'Kira Kaisar Baru berubah menjadi hantu, bergerak ke satu target musuh untuk serangan tersembunyi, memberikan kerusakan fisik, sekaligus meningkatkan batas kemarahan target dan mendapatkan poin iblis untuk dirinya sendiri; dalam keadaan asal, jangkauan serangan berubah menjadi baris dan memiliki peluang untuk memanggil hantu.',
		simDesc_ph = 'Ang Kira Bagong Emperador ay nagiging isang multo, lumalapit sa isang kalabang target para sa isang lihim na atake, nagdudulot ng pisikal na pinsala, habang pinapataas ang limitasyon ng galit ng target at nakakakuha ng demonyong puntos para sa sarili; sa estado ng pinagmulan, ang saklaw ng atake ay nagiging hanay at may tsansang may kasamang multo.',
		simDesc_ma = 'Kira Maharaja Baru berubah menjadi hantu, bergerak ke sasaran musuh tunggal untuk serangan rahsia, menyebabkan kerosakan fizikal, sambil meningkatkan had kemarahan sasaran dan menerima mata iblis untuk dirinya sendiri; dalam keadaan asal usul, julat serangan bertukar menjadi barisan dan mempunyai peluang disertai dengan hantu.',
		simDesc = 'Kira The New Emperor transforms into a ghost, moving to a single enemy target for a stealth attack, dealing physical damage, while increasing the rage limit of the target and gaining demonic points for himself; in origin state, the attack range changes to a row and has a chance to summon a ghost.',
		upLvDesc = 'Fixed damage +192',
