	[210413] = {
		id = 210413,
		skillName_vn = 'Thế giới đảo ngược',
		skillName_en = 'Reverse world',
		skillName_th = 'โลกกลับด้าน',
		skillName_in = 'Dunia terbalik',
		skillName_ph = 'Baliktad na mundo',
		skillName_ma = 'Dunia terbalik',
		skillName = 'Reverse world',
		describe_vn = 'Giratina thức tỉnh từ vực thẳm, sau đó triệu hồi lối vào thế giới đảo ngược, hút các đơn vị hàng đầu của kẻ địch vào đó, gây #C0xE69900#230% Sát Thương Vật Lý#C0x5B545B#+$(ski llLevel*4*48)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, giảm cơn thịnh nộ của mục tiêu trúng đòn đi 250 điểm và nhận được 3 điểm ma sau khi tấn công\n#F20# \n#F40#Sau khi thực hiện chiêu thức đặc biệt, anh ta chuyển sang [#L10#Origin Form#L0#] trong 2 hiệp. Giới hạn trên của lượng máu của chính anh ta (chỉ tăng giới hạn trên), tốc độ và tỷ lệ kiểm soát tổng thể được tăng thêm 50% (không thể phân tán, chuyển giao hoặc sao chép). Chuyển sang chiêu thức đặc biệt mới (không cần nộ và không tiêu hao nộ khi phóng ra, hồi lại trong 2 lượt sau khi phóng): Phạm vi thay đổi đối với tất cả kẻ địch và có thêm 75% xác suất thêm [#L10#鬼鬼火#L0#] vào 4 tướng địch có nộ cao nhất trong 2 lượt.',
		describe_en = 'Giratina awakens from the abyss, then summons the entrance to the reverse world, sucking the enemy\'s top units inside, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, reducing the target\'s rage by 250 points and gaining 3 magic points after attacking\n#F20# \n#F40# After performing the special move, he switches to [#L10#Origin Form#L0#] for 2 turns. His maximum HP (only the upper limit increases), speed, and overall control rate increase by 50% (cannot be dispersed, transferred, or copied). Switches to a new special move (no rage required and no rage consumed when activated, recovers in 2 turns after release): Range changes to affect all enemies and gains a 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy generals with the highest rage for 2 turns.',
		describe_th = 'กิรา ติน่า ตื่นขึ้นจากเหวลึก จากนั้นเรียกทางเข้าสู่โลกย้อนกลับ ดูดหน่วยชั้นนำของศัตรูเข้าไป ทำให้เกิด #C0xE69900#ความเสียหายทางกายภาพ 230%#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# ลดความโกรธของเป้าหมายลง 250 คะแนน และได้รับ 3 คะแนนเวทหลังจากโจมตี \n#F20# \n#F40# หลังจากใช้ท่าไม้ตาย เขาจะเปลี่ยนเป็น [#L10#Origin Form#L0#] เป็นเวลา 2 เทิร์น ขีดจำกัดสูงสุดของ HP เขา (เฉพาะขีดจำกัดบนเท่านั้น) ความเร็ว และอัตราการควบคุมโดยรวมเพิ่มขึ้น 50% (ไม่สามารถแจกจ่าย โอนย้าย หรือคัดลอก) เปลี่ยนเป็นท่าไม้ตายใหม่ (ไม่ต้องใช้ความโกรธและไม่กินความโกรธเมื่อปล่อย ฟื้นฟูใน 2 เทิร์นหลังจากใช้): ระยะครอบคลุมศัตรูทั้งหมดและมีโอกาส 75% เพิ่ม [#L10#鬼鬼火#L0#] ให้กับ 4 พลธนูศัตรูที่มีความโกรธสูงสุดเป็นเวลา 2 เทิร์น',
		describe_in = 'Giratina terbangun dari jurang, kemudian memanggil pintu masuk ke dunia terbalik, menyedot unit teratas musuh ke dalamnya, menyebabkan #C0xE69900#230% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$ Kerusakan Fisik #C0xF13B54# #C0x5B545B#, mengurangi kemarahan target sebesar 250 poin dan mendapatkan 3 poin sihir setelah menyerang \n#F20# \n#F40# Setelah melakukan serangan khusus, dia beralih ke [#L10#Origin Form#L0#] selama 2 giliran. Batas atas HP-nya (hanya batas atas yang meningkat), kecepatan, dan tingkat kontrol keseluruhan meningkat 50% (tidak dapat dibagikan, dipindahkan, atau disalin). Beralih ke serangan khusus baru (tidak memerlukan dan tidak mengonsumsi kemarahan saat melepaskan, pulih dalam 2 giliran setelah dilepaskan): Jangkauan berubah ke semua musuh dan memiliki 75% kemungkinan untuk menambahkan [#L10#鬼鬼火#L0#] ke 4 jenderal musuh dengan kemarahan tertinggi selama 2 giliran.',
		describe_ph = 'Nagising si Giratina mula sa kailaliman, pagkatapos ay tinawag ang pasukan sa reverse world, hinatak ang nangungunang mga yunit ng kalaban doon, nagdudulot ng #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, binabawasan ang galit ng target ng 250 puntos at nakakakuha ng 3 magic points pagkatapos umatake \n#F20# \n#F40# Pagkatapos gawin ang espesyal na galaw, siya ay lumilipat sa [#L10#Origin Form#L0#] sa loob ng 2 turn. Ang maximum na HP niya (tanging ang upper limit ang tumataas), bilis, at pangkalahatang control rate ay tumataas ng 50% (hindi maaaring ipamahagi, ilipat, o kopyahin). Lumilipat sa bagong special move (hindi kailangan ng galit at hindi kumukonsumo ng galit kapag ginamit, bumabalik pagkatapos ng 2 turn): Ang saklaw ay nagbabago para sa lahat ng mga kalaban at may 75% na tsansa na magdagdag ng [#L10#鬼鬼火#L0#] sa 4 na kalaban na may pinakamataas na galit sa loob ng 2 turn.',
		describe_ma = 'Giratina terjaga dari jurang, kemudian memanggil pintu masuk ke dunia terbalik, menyedut unit utama musuh ke dalamnya, menyebabkan #C0xE69900#230% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ Kerosakan Fizikal #C0xF13B54# #C0x5B545B#, mengurangkan kemarahan sasaran sebanyak 250 mata dan mendapat 3 mata sihir selepas menyerang \n#F20# \n#F40# Selepas melakukan serangan khas, dia bertukar kepada [#L10#Origin Form#L0#] selama 2 pusingan. Had atas HP beliau (hanya had atas meningkat), kelajuan, dan kadar kawalan keseluruhan meningkat sebanyak 50% (tidak boleh diagihkan, dipindahkan, atau disalin). Bertukar kepada serangan khas baru (tidak memerlukan dan tidak menggunakan kemarahan ketika dilancarkan, pulih dalam 2 pusingan selepas dilancarkan): Julat berubah untuk semua musuh dan mendapat peluang 75% untuk menambah [#L10#鬼鬼火#L0#] kepada 4 ketua musuh yang mempunyai kemarahan tertinggi selama 2 pusingan.',
		describe = 'Giratina awakens from the abyss, then summons the entrance to the reverse world, sucking the enemy\'s top units inside, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, reducing the target\'s rage by 250 points and gaining 3 magic points after attacking\n#F20# \n#F40# After performing the special move, he switches to [#L10#Origin Form#L0#] for 2 turns. His maximum HP (only the upper limit increases), speed, and overall control rate increase by 50% (cannot be dispersed, transferred, or copied). Switches to a new special move (no rage required and no rage consumed when activated, recovers in 2 turns after release): Range changes to affect all enemies and gains a 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy generals with the highest rage for 2 turns.',
		simDesc_vn = 'Kira Đế Tân từ vực sâu tỉnh dậy, sau đó triệu hồi cổng vào thế giới đảo ngược, hút các đơn vị kẻ thù ở hàng trước vào trong đó, gây sát thương vật lý, giảm giá trị tức giận của chúng và hồi phục điểm ma quái; sau đó, hầu hết thuộc tính sẽ được nâng cấp chuyển sang trạng thái nguồn gốc; trong trạng thái nguồn gốc, phạm vi tấn công chuyển thành toàn bộ và có xác suất rất cao kèm theo hồn ma.',
		simDesc_en = 'Kira Đế Tân awakens from the abyss, then summons a portal to the reversed world, pulling enemy units in the front row inside, dealing physical damage, reducing their anger value, and restoring phantom points; afterward, most attributes are upgraded and shifted into the origin state; in the origin state, the attack range changes to the entire field with a very high chance of accompanying a ghost.',
		simDesc_th = 'คิระ เด กี เซิน ตื่นขึ้นจากห้วงลึก จากนั้นเรียกพอร์ทัลเข้าสู่โลกกลับด้าน ดึงยูนิตศัตรูแถวหน้าเข้ามาในนั้น สร้างความเสียหายทางกายภาพ ลดค่าความโกรธของพวกเขา และฟื้นฟูคะแนนผี จากนั้น คุณสมบัติเกือบทั้งหมดจะถูกอัปเกรดและเปลี่ยนเป็นสถานะต้นกำเนิด ในสถานะต้นกำเนิด ระยะการโจมตีเปลี่ยนเป็นทั่วทั้งสนามและมีโอกาสสูงมากที่จะมาพร้อมกับวิญญาณ',
		simDesc_in = 'Kira Đế Tân bangkit dari kedalaman, kemudian memanggil portal ke dunia terbalik, menarik unit musuh di barisan depan ke dalamnya, memberikan kerusakan fisik, mengurangi nilai amarah mereka, dan memulihkan poin hantu; setelah itu, sebagian besar atribut ditingkatkan dan beralih ke keadaan asal; dalam keadaan asal, jangkauan serangan berubah menjadi seluruh area dan memiliki peluang sangat tinggi disertai roh hantu.',
		simDesc_ph = 'Nagising si Kira Đế Tân mula sa kailaliman, pagkatapos ay tumawag ng portal papunta sa baliktad na mundo, hinila ang mga yunit ng kalaban sa unang hanay papasok dito, nagdulot ng pisikal na pinsala, binabawasan ang kanilang halaga ng galit at nagpapanumbalik ng mga phantom points; pagkatapos nito, karamihan sa mga katangian ay ina-upgrade at inililipat sa estado ng pinagmulan; sa estado ng pinagmulan, ang saklaw ng atake ay nagbabago sa buong lugar at may napakataas na tsansa na may kasamang espiritu.',
		simDesc_ma = 'Kira Đế Tân bangkit dari ke dalam jurang, kemudian memanggil pintu masuk ke dunia terbalik, menarik unit musuh barisan depan ke dalamnya, memberikan kerosakan fizikal, mengurangkan nilai kemarahan mereka, dan memulihkan mata hantu; selepas itu, kebanyakan atribut dinaik taraf dan berubah ke keadaan asal; dalam keadaan asal, julat serangan berubah menjadi keseluruhan kawasan dan mempunyai kebarangkalian yang sangat tinggi disertai roh hantu.',
		simDesc = 'Kira Đế Tân awakens from the abyss, then summons a portal to the reversed world, pulling enemy units in the front row inside, dealing physical damage, reducing their anger value, and restoring phantom points; afterward, most attributes are upgraded and shifted into the origin state; in the origin state, the attack range changes to the entire field with a very high chance of accompanying a ghost.',
		starEffect = __data_t__starEffect[210413],
		-- {11}
		starEffectDesc_vn = 'Kỹ năng chí mạng hình thái khác sẽ đảo ngược toàn bộ thế giới kéo dài 3 lượt: giảm tốc độ hồi phục tức giận của toàn bộ địch 15%; số lượt duy trì của hình thái nguồn gốc +1',
		starEffectDesc = 'Different form critical skill will invert the entire world for 3 turns: reduce all enemies\' anger recovery speed by 15%; origin form\'s duration +1',
		starEffectDesc_en = 'Different form critical skill will invert the entire world for 3 turns: reduce all enemies\' anger recovery speed by 15%; origin form\'s duration +1',
		starEffectDesc_th = 'ทักษะคริติคัลรูปร่างต่างจะทำให้โลกทั้งใบกลับด้านเป็นเวลา 3 เทิร์น: ลดความเร็วฟื้นฟูความโกรธของศัตรูทั้งหมดลง 15%; ระยะเวลารูปร่างต้นกำเนิด +1',
		starEffectDesc_in = 'Skill kritis bentuk berbeda akan membalik seluruh dunia selama 3 giliran: mengurangi kecepatan pemulihan amarah musuh sebesar 15%; durasi bentuk asal +1',
		starEffectDesc_ph = 'Ang iba’t ibang anyo ng kritikal na kasanayan ay mag-iinvert ng buong mundo sa loob ng 3 turn: bawasan ang bilis ng pagbawi ng galit ng lahat ng kalaban ng 15%; dagdagan ng 1 ang tagal ng anyo ng pinagmulan',
		starEffectDesc_ma = 'Kemahiran kritikal bentuk berbeza akan memutar balikkan seluruh dunia selama 3 pusingan: mengurangkan kelajuan pulih kemarahan semua musuh sebanyak 15%; tempoh bentuk asal +1',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
		upLvDesc_in = 'Kerusakan tetap +192',
