	[210416] = {
		id = 210416,
		skillName_vn = 'Bóng ma dày đặc',
		skillName_en = 'Dense ghost',
		skillName_th = 'ผีหนาแน่น',
		skillName_in = 'Hantu tebal',
		skillName_ph = 'Makapal na multo',
		skillName_ma = 'Hantu tebal',
		skillName = 'Dense ghost',
		describe_vn = 'Khi Giratio bước vào hiện trường, anh ta sẽ nhận được số lượng hồn ma của các anh hùng trong trại của mình ngoài chính mình (giới hạn trên của số lượng ma: 5 điểm, không thể xua tan hoặc bỏ qua), và mỗi hồn ma có thể giảm số lượng hồn ma của mình #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# Sát thương cuối cùng nhận được sẽ giảm 1 hồn ma mỗi khi trúng đòn. Khi bóng ma giảm đi, 80 điểm thịnh nộ sẽ được phục hồi\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn, bạn và anh hùng có phần trăm máu thấp nhất ở hàng sau trong đội của bạn sẽ nhận được [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: lượng khiên bằng 15% máu tối đa của Giratina. , không thể chồng lên, mục tiêu tấn công khiên ma sẽ yếu: đòn tấn công kép giảm 15% trong 2 lượt); khi chuyển sang dạng gốc, 30% lượng HP đã mất có thể được phục hồi (không bị ảnh hưởng bởi phương pháp điều trị bị cấm) và bản thân sẽ không tái sinh khi tấn công ở dạng gốc.',
		describe_en = 'When Giratio enters the battlefield, he receives the number of ghost souls of heroes in his camp excluding himself (maximum ghost count: 5, cannot be dispelled or ignored), and each ghost can reduce his own ghost count by #C0x5c9970#$(4 + s killLevel * 0.04 - 0.04)$%#C0x5B545B#. The final damage received reduces one ghost each time he is hit. When ghosts decrease, 80 points of fury are restored \n#F20# \n#F40#. At the start of each major round, you and the hero with the lowest percentage HP in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: a shield equal to 15% of Giratina\'s maximum HP, cannot be stacked, the target attacked by the ghost shield is weakened: double attack damage reduced by 15% for 2 turns). When switching to original form, 30% of lost HP can be restored (not affected by banned healing methods) and the user does not revive when attacking in original form.',
		describe_th = 'เมื่อ Giratio เข้าสู่สนามประลอง เขาจะได้รับจำนวนวิญญาณผีของฮีโร่ในค่ายของเขานอกจากตัวเอง (จำนวนผีสูงสุด: 5 ตัว, ไม่สามารถสลายหรือมองข้ามได้) และแต่ละวิญญาณผีสามารถลดจำนวนผีของเขาเองได้ #C0x5c9970#$(4 + s killLevel * 0.04 - 0.04)$%#C0x5B545B# ความเสียหายสุดท้ายที่ได้รับจะลดวิญญาณผีหนึ่งตัวทุกครั้งที่ถูกโจมตี เมื่อวิญญาณลดลง จะได้รับพลังโกรธคืน 80 คะแนน \n#F20# \n#F40# ในช่วงเริ่มต้นแต่ละรอบใหญ่ คุณและฮีโร่ที่มีเปอร์เซ็นต์พลังชีวิตต่ำที่สุดในแถวหลังของทีมจะได้รับ [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: โล่เท่ากับ 15% ของพลังชีวิตสูงสุดของ Giratina, ไม่สามารถทับซ้อน, เป้าหมายที่ถูกโจมตีโดยโล่ผีจะอ่อนแอ: ความเสียหายการโจมตีสองครั้งลดลง 15% เป็นเวลา 2 เทิร์น) เมื่อเปลี่ยนเป็นรูปลักษณ์เดิม จะฟื้นฟูพลังชีวิตที่เสียไป 30% (ไม่ถูกกระทบโดยวิธีรักษาที่ห้าม) และตัวผู้ใช้จะไม่ฟื้นคืนชีพเมื่อโจมตีในรูปลักษณ์เดิม',
		describe_in = 'Ketika Giratio memasuki medan perang, ia akan menerima jumlah jiwa hantu pahlawan di perkemahannya kecuali dirinya sendiri (batas maksimum jumlah hantu: 5, tidak bisa disingkirkan atau diabaikan), dan setiap hantu dapat mengurangi jumlah hantunya sendiri sebesar #C0x5c9970#$(4 + s killLevel * 0.04 - 0.04)$%#C0x5B545B#. Kerusakan akhir yang diterima akan mengurangi satu hantu setiap kali terkena serangan. Ketika hantu berkurang, 80 poin kemarahan akan dipulihkan \n#F20# \n#F40#. Pada awal setiap putaran besar, kamu dan pahlawan dengan persentase HP terendah di barisan belakang timmu akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: perisai sebesar 15% dari HP maksimum Giratina, tidak dapat ditumpuk, target yang diserang oleh perisai hantu akan melemah: kerusakan serangan ganda berkurang 15% selama 2 giliran). Saat beralih ke bentuk asli, 30% HP yang hilang dapat dipulihkan (tidak terpengaruh oleh metode penyembuhan terlarang) dan pengguna tidak akan bangkit kembali saat menyerang dalam bentuk asli.',
		describe_ph = 'Kapag pumasok si Giratio sa larangan ng laban, makakatanggap siya ng bilang ng mga espiritu ng mga bayani sa kanyang kampo maliban sa kanyang sarili (limitasyon ng bilang ng espiritu: 5, hindi maaaring maalis o balewalain), at bawat espiritu ay maaaring pababain ang bilang ng kanyang sariling espiritu ng #C0x5c9970#$(4 + s killLevel * 0.04 - 0.04)$%#C0x5B545B#. Ang huling natanggap na pinsala ay magbabawas ng isang espiritu tuwing tinatamaan. Kapag bumaba ang mga espiritu, 80 puntos ng galit ang ibabalik \n#F20# \n#F40#. Sa simula ng bawat malaking round, ikaw at ang bayani na may pinakamababang porsyento ng HP sa likurang linya ng iyong koponan ay makakatanggap ng [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: isang kalasag na katumbas ng 15% ng maximum na HP ni Giratina, hindi maaaring magsabay, ang target na tinatamaan ng kalasag ng espiritu ay nanghihina: doble ang pinsala sa atake ay nababawasan ng 15% sa loob ng 2 turn). Kapag lumipat sa orihinal na anyo, maaaring maibalik ang 30% ng nawalang HP (hindi naaapektuhan ng ipinagbabawal na mga paraan ng pagpapagaling) at hindi muling mabubuhay ang sarili kapag umaatake sa orihinal na anyo.',
		describe_ma = 'Apabila Giratio memasuki medan pertempuran, dia akan menerima jumlah roh hantu wira dalam kemahnya selain dirinya sendiri (had maksimum jumlah hantu: 5, tidak boleh disingkir atau diabaikan), dan setiap hantu boleh mengurangkan jumlah roh hantunya sendiri sebanyak #C0x5c9970#$(4 + s killLevel * 0.04 - 0.04)$%#C0x5B545B#. Kerosakan akhir diterima akan mengurangkan satu hantu setiap kali terkena serangan. Apabila hantu berkurang, 80 poin kemarahan akan dipulihkan \n#F20# \n#F40#. Pada permulaan setiap pusingan besar, anda dan wira dengan peratusan HP terendah di barisan belakang pasukan anda akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: perisai sama dengan 15% HP maksimum Giratina, tidak boleh bertindih, sasaran yang diserang oleh perisai hantu akan lemah: serangan berganda dikurangkan 15% selama 2 pusingan). Apabila beralih ke bentuk asal, 30% HP yang hilang boleh dipulihkan (tidak terjejas oleh kaedah penyembuhan yang dilarang) dan diri tidak akan bangkit semula apabila menyerang dalam bentuk asal.',
		describe = 'When Giratio enters the battlefield, he receives the number of ghost souls of heroes in his camp excluding himself (maximum ghost count: 5, cannot be dispelled or ignored), and each ghost can reduce his own ghost count by #C0x5c9970#$(4 + s killLevel * 0.04 - 0.04)$%#C0x5B545B#. The final damage received reduces one ghost each time he is hit. When ghosts decrease, 80 points of fury are restored \n#F20# \n#F40#. At the start of each major round, you and the hero with the lowest percentage HP in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: a shield equal to 15% of Giratina\'s maximum HP, cannot be stacked, the target attacked by the ghost shield is weakened: double attack damage reduced by 15% for 2 turns). When switching to original form, 30% of lost HP can be restored (not affected by banned healing methods) and the user does not revive when attacking in original form.',
		starEffect = __data_t__starEffect[210416],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Quỷ khiên nâng cấp: tăng 5% lượng khiên, mỗi lượt lớn kết thúc bản thân nhận 1 điểm Quỷ ảnh',
		starEffectDesc = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
		starEffectDesc_en = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
