	[210422] = {
		id = 210422,
		skillName_vn = 'Đuôi rồng',
		skillName_en = 'Dragon Tail',
		skillName_th = 'หางมังกร',
		skillName_in = 'Ekor Naga',
		skillName_ph = 'Buntot ng Dragon',
		skillName_ma = 'Ekor Naga',
		skillName = 'Dragon Tail',
		describe_vn = 'Giratina sử dụng Đuôi Rồng để tấn công một mục tiêu địch, gây #C0xE69900#170% Sát Thương Vật Lý #C0x5B545B#+$(skillLevel*4*48)$ thuộc #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, tăng khả năng giảm sát thương cho cột của anh ta thêm 15% trong 2 lượt và nhận được 2 điểm ma sau đòn tấn công\n#F20# \n#F40#[#L10#Origin Form#L0#], phạm vi tấn công thay đổi theo hàng và có thêm 80% xác suất xảy ra [#L10#Ghost Fire#L0#] trong 2 lượt\n[#L10# Netherworld Wisp#L0#]: Hiệu ứng tiêu cực đặc biệt, chỉ có thể xua tan và không thể chồng lên. Trước khi mục tiêu di chuyển hoặc khi Netherworld Wisp bị xua tan, máu của mục tiêu sẽ bị giảm (12% lượng máu tối đa của Giratina) và 120 điểm thịnh nộ.',
		describe_en = 'Giratina uses Dragon Tail to attack an enemy target, dealing #C0xE69900#170% Physical Damage #C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage #C0x5B545B#, increasing his column\'s damage reduction by 15% for 2 turns and gaining 2 chakra points after the attack\n#F20# \n#F40#[#L10#Origin Form#L0#], attack range changes by row and has an 80% chance to trigger [#L10#Ghost Fire#L0#] for 2 turns\n[#L10# Netherworld Wisp#L0#]: A special negative effect that can only be dispelled and cannot stack. Before the target moves or when Netherworld Wisp is dispelled, the target\'s HP will be reduced (12% of Giratina\'s max HP) and 120 rage points will be generated.',
		describe_th = 'Giratina ใช้หางมังกรโจมตีเป้าหมายศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#170% #C0x5B545B#+$(skillLevel*4*48)$ ของ #C0xF13B54# ความเสียหายทางกายภาพ #C0x5B545B# เพิ่มการลดความเสียหายของแถวของเขาอีก 15% เป็นเวลา 2 เทิร์นและได้รับ 2 คะแนนมานาหลังการโจมตี\n#F20# \n#F40#[#L10#Origin Form#L0#] ระยะโจมตีเปลี่ยนตามแถวและมีโอกาส 80% จะเกิด [#L10#Ghost Fire#L0#] เป็นเวลา 2 เทิร์น\n[#L10# Netherworld Wisp#L0#]: เอฟเฟกต์ลบพิเศษ สามารถขจัดได้เท่านั้นและไม่สามารถซ้อนทับได้ ก่อนที่เป้าหมายจะเคลื่อนที่หรือเมื่อ Netherworld Wisp ถูกขจัด เลือดของเป้าหมายจะลดลง (12% ของ HP สูงสุดของ Giratina) และได้รับ 120 แต้มความโกรธ',
		describe_in = 'Giratina menggunakan Ekor Naga untuk menyerang target musuh, memberikan #C0xE69900#170% Kerusakan Fisik #C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54# Kerusakan Fisik #C0x5B545B#, meningkatkan pengurangan kerusakan untuk kolomnya sebesar 15% selama 2 giliran dan memperoleh 2 poin chakra setelah menyerang\n#F20# \n#F40#[#L10#Origin Form#L0#], jangkauan serangan berubah berdasarkan baris dan memiliki peluang 80% untuk memicu [#L10#Ghost Fire#L0#] selama 2 giliran\n[#L10# Netherworld Wisp#L0#]: Efek negatif khusus, hanya dapat dihapus dan tidak dapat ditumpuk. Sebelum target bergerak atau saat Netherworld Wisp dihapus, HP target akan berkurang (12% dari HP maksimal Giratina) dan menghasilkan 120 poin kemarahan.',
		describe_ph = 'Giratina ay gumagamit ng Dragon Tail upang atakihin ang isang kalabang target, na nagdudulot ng #C0xE69900#170% Pisikal na Pinsala #C0x5B545B#+$(skillLevel*4*48)$ ng #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, pinapataas ang kakayahan ng kanyang hanay na bawasan ang pinsala ng 15% sa loob ng 2 turn at nakakakuha ng 2 chakra points pagkatapos ng pag-atake\n#F20# \n#F40#[#L10#Origin Form#L0#], nagbabago ang saklaw ng pag-atake base sa hanay at may 80% tsansa na mag-trigger ng [#L10#Ghost Fire#L0#] sa loob ng 2 turn\n[#L10# Netherworld Wisp#L0#]: Isang espesyal na negatibong epekto, maaari lamang matanggal at hindi pwedeng mag-overlap. Bago gumalaw ang target o kapag na-dispel ang Netherworld Wisp, babawasan ang HP ng target (12% ng max HP ni Giratina) at makakakuha ng 120 puntos ng galit.',
		describe_ma = 'Giratina menggunakan Ekor Naga untuk menyerang satu sasaran musuh, menyebabkan #C0xE69900#170% Kerosakan Fizikal #C0x5B545B#+$(skillLevel*4*48)$ daripada #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, meningkatkan keupayaan pengurangan kerosakan pada lajurnya sebanyak 15% selama 2 giliran dan menerima 2 mata chakra selepas serangan\n#F20# \n#F40#[#L10#Origin Form#L0#], julat serangan berubah mengikut baris dan mempunyai peluang 80% untuk berlaku [#L10#Ghost Fire#L0#] selama 2 giliran\n[#L10# Netherworld Wisp#L0#]: Kesan negatif khas, hanya boleh disingkirkan dan tidak boleh bertindih. Sebelum sasaran bergerak atau apabila Netherworld Wisp disingkirkan, darah sasaran akan berkurang (12% daripada jumlah darah maksimum Giratina) dan 120 mata kemarahan.',
		describe = 'Giratina uses Dragon Tail to attack an enemy target, dealing #C0xE69900#170% Physical Damage #C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage #C0x5B545B#, increasing his column\'s damage reduction by 15% for 2 turns and gaining 2 chakra points after the attack\n#F20# \n#F40#[#L10#Origin Form#L0#], attack range changes by row and has an 80% chance to trigger [#L10#Ghost Fire#L0#] for 2 turns\n[#L10# Netherworld Wisp#L0#]: A special negative effect that can only be dispelled and cannot stack. Before the target moves or when Netherworld Wisp is dispelled, the target\'s HP will be reduced (12% of Giratina\'s max HP) and 120 rage points will be generated.',
		simDesc_vn = 'Kira Đế Tân sử dụng đuôi rồng tấn công mục tiêu đơn lẻ của kẻ thù, gây sát thương vật lý, tăng giới hạn tức giận của mục tiêu và bản thân nhận điểm ma quái; trong trạng thái nguồn gốc, phạm vi tấn công chuyển thành hàng và có xác suất kèm theo hồn ma.',
		simDesc_en = 'Kira De Tan uses a dragon tail to attack a single enemy target, dealing physical damage, increasing the target\'s rage limit, and gaining phantom points for himself; in origin state, the attack range changes to a row and has a chance to accompany a ghost.',
		simDesc_th = 'คิร่า เดะ ตัน ใช้หางมังกรโจมตีเป้าหมายศัตรูเดียว สร้างความเสียหายทางกายภาพ เพิ่มขีดจำกัดความโกรธของเป้าหมาย และได้รับแต้มผี สำหรับตัวเอง; ในสถานะต้นกำเนิด ช่วงการโจมตีเปลี่ยนเป็นแถวและมีโอกาสที่จะมีผีร่วมด้วย',
		simDesc_in = 'Kira De Tan menggunakan ekor naga untuk menyerang satu target musuh, memberikan kerusakan fisik, meningkatkan batas kemarahan target, dan mendapatkan poin hantu untuk dirinya sendiri; dalam keadaan asal, jangkauan serangan berubah menjadi satu baris dan memiliki peluang disertai hantu.',
		simDesc_ph = 'Ginagamit ni Kira De Tan ang buntot ng dragon para atakihin ang isang target na kaaway, nagdudulot ng pisikal na pinsala, nagpapataas ng limit ng galit ng target, at nakakakuha ng phantom points para sa kanyang sarili; sa estado ng pinagmulan, nagbabago ang saklaw ng pag-atake sa isang hanay at may pagkakataong may kasamang espiritu.',
		simDesc_ma = 'Kira De Tan menggunakan ekor naga untuk menyerang satu sasaran musuh, menyebabkan kerosakan fizikal, meningkatkan had kemarahan sasaran dan memperoleh mata hantu untuk dirinya sendiri; dalam keadaan asal, julat serangan berubah menjadi barisan dan mempunyai kemungkinan disertai hantu.',
		simDesc = 'Kira De Tan uses a dragon tail to attack a single enemy target, dealing physical damage, increasing the target\'s rage limit, and gaining phantom points for himself; in origin state, the attack range changes to a row and has a chance to accompany a ghost.',
		upLvDesc = 'Fixed damage +192',
