	[210423] = {
		id = 210423,
		skillName_vn = 'Thế giới đảo ngược',
		skillName_en = 'Reverse world',
		skillName_th = 'โลกกลับด้าน',
		skillName_in = 'Dunia terbalik',
		skillName_ph = 'Baliktad na mundo',
		skillName_ma = 'Dunia terbalik',
		skillName = 'Reverse world',
		describe_vn = 'Giratina một lần nữa triệu hồi lối vào thế giới ngược để đẩy toàn bộ đơn vị địch xuống vực thẳm vô tận, gây #C0xE69900#230% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, giảm cơn thịnh nộ của mục tiêu trúng đòn 250 điểm và nhận 3 điểm ma sau đó tấn công\n#F20# \n#F40#Sau khi thực hiện chiêu thức đặc biệt, anh ta chuyển sang [#L10#Origin Form#L0#] trong 2 hiệp. Giới hạn trên của lượng máu của chính anh ta (chỉ tăng giới hạn trên), tốc độ và tỷ lệ kiểm soát tổng thể được tăng thêm 50% (không thể phân tán, chuyển giao hoặc sao chép). Chuyển sang chiêu thức đặc biệt mới (không cần nộ và không tiêu hao nộ khi phóng ra, hồi lại trong 2 lượt sau khi phóng): Phạm vi thay đổi đối với tất cả kẻ địch và có thêm 75% xác suất thêm [#L10#鬼鬼火#L0#] vào 4 tướng địch có nộ cao nhất trong 2 lượt.',
		describe_en = 'Giratina once again summons the gateway to the reverse world to push all enemy units into the endless abyss, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, reducing the target\'s rage by 250 points and gaining 3 mana points. Then attacks \n#F20# \n#F40#. After performing the special move, he switches to [#L10#Origin Form#L0#] for 2 turns. His maximum HP limit (only the upper limit increases), speed, and overall control rate are increased by 50% (cannot be dispersed, transferred, or copied). Switches to a new special move (no rage required and no rage consumed when released, recovers in 2 turns after use): Range changes to affect all enemies and has a 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy units with the highest rage for 2 turns.',
		describe_th = 'Giratina เรียกทางเข้าโลกกลับด้านอีกครั้งเพื่อผลักยูนิตศัตรูทั้งหมดตกลงสู่เหวไม่มีที่สิ้นสุด สร้างความเสียหายทางกายภาพ #C0xE69900#230%#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ลดความโกรธของเป้าหมายลง 250 คะแนน และได้รับ 3 คะแนนมานา จากนั้นโจมตี \n#F20# \n#F40# หลังจากใช้สกิลพิเศษ เขาจะเปลี่ยนเป็น [#L10#Origin Form#L0#] เป็นเวลา 2 เทิร์น ค่า HP สูงสุดของเขา (เพิ่มเฉพาะค่าขีดจำกัดสูงสุด), ความเร็ว และอัตราการควบคุมโดยรวม เพิ่มขึ้น 50% (ไม่สามารถกระจาย, โอน หรือคัดลอกได้) เปลี่ยนสกิลพิเศษเป็นสกิลใหม่ (ไม่ต้องใช้มานาและไม่เสียมานาเมื่อปล่อย ฟื้นฟูใน 2 เทิร์นหลังใช้งาน): ระยะโจมตีเปลี่ยนเป็นทุกศัตรู และมีโอกาส 75% ที่จะเพิ่ม [#L10#鬼鬼火#L0#] ให้แก่ 4 ยูนิตศัตรูที่มีความโกรธสูงสุดเป็นเวลา 2 เทิร์น',
		describe_in = 'Giratina sekali lagi memanggil pintu masuk ke dunia terbalik untuk mendorong semua unit musuh ke jurang tanpa akhir, memberikan #C0xE69900#230% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, mengurangi kemarahan target yang terkena sebanyak 250 poin dan mendapatkan 3 poin mana. Kemudian menyerang \n#F20# \n#F40#. Setelah melakukan serangan khusus, dia beralih ke [#L10#Origin Form#L0#] selama 2 giliran. Batas atas HP-nya (hanya meningkatkan batas atas), kecepatan, dan tingkat kontrol keseluruhan meningkat 50% (tidak bisa disebar, dipindahkan, atau disalin). Beralih ke serangan khusus baru (tidak perlu mana dan tidak mengkonsumsi mana saat digunakan, pulih dalam 2 giliran setelah penggunaan): Jangkauan berubah menjadi semua musuh dan memiliki peluang 75% untuk menambahkan [#L10#鬼鬼火#L0#] pada 4 unit musuh dengan kemarahan tertinggi selama 2 giliran.',
		describe_ph = 'Muling tinawag ni Giratina ang pintuan patungo sa salungat na mundo upang itulak ang lahat ng kalabang yunit pababa sa walang katapusang bangin, nagdudulot ng #C0xE69900#230% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, bawasan ang galit ng target ng 250 puntos at tumanggap ng 3 puntos ng mana. Pagkatapos ay umatake \n#F20# \n#F40#. Pagkatapos gawin ang espesyal na kakayahan, siya ay lilipat sa [#L10#Origin Form#L0#] sa loob ng 2 turn. Ang itaas na hangganan ng kanyang HP (tanging itaas na limit lang ang tumataas), bilis, at pangkalahatang rate ng kontrol ay tumataas ng 50% (hindi maaaring ipamahagi, ilipat o kopyahin). Lumipat sa bagong espesyal na kakayahan (hindi kailangan ng mana at hindi kumukunsumo ng mana kapag ginamit, bumabalik sa loob ng 2 turn pagkatapos gamitin): Ang saklaw ay nagbabago upang maapektuhan ang lahat ng kalaban at may 75% na tsansa na magdagdag ng [#L10#鬼鬼火#L0#] sa 4 kalabang yunit na may pinakamataas na galit sa loob ng 2 turn.',
		describe_ma = 'Giratina sekali lagi memanggil pintu masuk ke dunia terbalik untuk menolak semua unit musuh ke dalam jurang tanpa batas, memberikan #C0xE69900#230% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, mengurangkan kemarahan sasaran yang terkena sebanyak 250 mata dan memperoleh 3 mata mana. Kemudian menyerang \n#F20# \n#F40#. Selepas melakukan serangan khas, dia bertukar ke [#L10#Origin Form#L0#] selama 2 pusingan. Had atas HPnya (hanya meningkatkan had atas), kelajuan, dan kadar kawalan keseluruhan meningkat sebanyak 50% (tidak boleh disebarkan, dipindahkan, atau disalin). Bertukar ke serangan khas baharu (tidak memerlukan mana dan tidak menggunakan mana ketika digunakan, pulih dalam 2 pusingan selepas pelancaran): Julat berubah ke semua musuh dan mempunyai 75% peluang untuk menambah [#L10#鬼鬼火#L0#] pada 4 unit musuh dengan kemarahan tertinggi selama 2 pusingan.',
		describe = 'Giratina once again summons the gateway to the reverse world to push all enemy units into the endless abyss, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, reducing the target\'s rage by 250 points and gaining 3 mana points. Then attacks \n#F20# \n#F40#. After performing the special move, he switches to [#L10#Origin Form#L0#] for 2 turns. His maximum HP limit (only the upper limit increases), speed, and overall control rate are increased by 50% (cannot be dispersed, transferred, or copied). Switches to a new special move (no rage required and no rage consumed when released, recovers in 2 turns after use): Range changes to affect all enemies and has a 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy units with the highest rage for 2 turns.',
		simDesc_vn = 'Kira Đế Tân một lần nữa triệu hồi cổng vào thế giới đảo ngược, khiến toàn bộ đơn vị kẻ thù rơi vào vực sâu vô tận, gây sát thương vật lý, giảm giá trị tức giận của chúng và có xác suất rất cao kèm theo hồn ma.',
		simDesc_en = 'Kira Emperor Tan once again summons the portal to the reversed world, causing all enemy units to fall into an endless abyss, dealing physical damage, reducing their anger value, and having a very high chance to accompany a ghost.',
		simDesc_th = 'คิราย อิมเปอเรอร์ แทน ยกเว้นประตูสู่โลกกลับด้านอีกครั้ง ทำให้หน่วยศัตรูทั้งหมดตกลงไปในเหวลึกไม่มีที่สิ้นสุด สร้างความเสียหายทางกายภาพ ลดมูลค่าความโกรธของพวกเขา และมีโอกาสสูงมากที่จะมีผีตามมา',
		simDesc_in = 'Kira Emperor Tan sekali lagi memanggil portal ke dunia terbalik, menyebabkan semua unit musuh jatuh ke jurang tanpa batas, memberikan damage fisik, mengurangi nilai kemarahan mereka, dan memiliki peluang sangat tinggi disertai hantu.',
		simDesc_ph = 'Muling hinaharap ni Kira Emperor Tan ang portal papunta sa baliktad na mundo, na siyang nagpapahulog sa lahat ng mga kaaway sa walang katapusang bangin, na nagdudulot ng pisikal na pinsala, nagpapababa ng kanilang halaga ng galit, at may mataas na tsansa na may kasamang multo.',
		simDesc_ma = 'Kira Emperor Tan sekali lagi memanggil pintu masuk ke dunia terbalik, menyebabkan semua unit musuh terjatuh ke dalam jurang yang tidak berpenghujung, menyebabkan kerosakan fizikal, mengurangkan nilai kemarahan mereka, dan mempunyai peluang yang sangat tinggi disertai roh.',
		simDesc = 'Kira Emperor Tan once again summons the portal to the reversed world, causing all enemy units to fall into an endless abyss, dealing physical damage, reducing their anger value, and having a very high chance to accompany a ghost.',
		starEffect = __data_t__starEffect[210423],
		-- {11}
		starEffectDesc_vn = 'Kỹ năng chí mạng hình thái khác sẽ đảo ngược toàn bộ thế giới kéo dài 3 lượt: giảm tốc độ hồi phục tức giận của toàn bộ địch 15%; số lượt duy trì của hình thái nguồn gốc +1',
		starEffectDesc = 'Different form critical skill will invert the entire world for 3 turns: reduce all enemies\' anger recovery speed by 15%; origin form\'s duration +1',
		starEffectDesc_en = 'Different form critical skill will invert the entire world for 3 turns: reduce all enemies\' anger recovery speed by 15%; origin form\'s duration +1',
		starEffectDesc_th = 'ทักษะคริติคัลรูปร่างต่างจะทำให้โลกทั้งใบกลับด้านเป็นเวลา 3 เทิร์น: ลดความเร็วฟื้นฟูความโกรธของศัตรูทั้งหมดลง 15%; ระยะเวลารูปร่างต้นกำเนิด +1',
		starEffectDesc_in = 'Skill kritis bentuk berbeda akan membalik seluruh dunia selama 3 giliran: mengurangi kecepatan pemulihan amarah musuh sebesar 15%; durasi bentuk asal +1',
		starEffectDesc_ph = 'Ang iba’t ibang anyo ng kritikal na kasanayan ay mag-iinvert ng buong mundo sa loob ng 3 turn: bawasan ang bilis ng pagbawi ng galit ng lahat ng kalaban ng 15%; dagdagan ng 1 ang tagal ng anyo ng pinagmulan',
		starEffectDesc_ma = 'Kemahiran kritikal bentuk berbeza akan memutar balikkan seluruh dunia selama 3 pusingan: mengurangkan kelajuan pulih kemarahan semua musuh sebanyak 15%; tempoh bentuk asal +1',
