	[210426] = {
		id = 210426,
		skillName_vn = 'Bóng ma dày đặc',
		skillName_en = 'Dense ghost',
		skillName_th = 'ผีหนาแน่น',
		skillName_in = 'Hantu yang padat',
		skillName_ph = 'Mabangis na multo',
		skillName_ma = 'Hantu tebal',
		skillName = 'Dense ghost',
		describe_vn = 'Khi Giratio bước vào hiện trường, anh ta sẽ nhận được số lượng hồn ma của các anh hùng trong trại của mình ngoài chính mình (giới hạn trên của số lượng ma: 5 điểm, không thể xua tan hoặc bỏ qua), và mỗi hồn ma có thể giảm số lượng hồn ma của mình #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# Sát thương cuối cùng nhận được sẽ giảm 1 hồn ma mỗi khi trúng đòn. Khi bóng ma giảm đi, 80 điểm thịnh nộ sẽ được phục hồi\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn, bạn và anh hùng có phần trăm máu thấp nhất ở hàng sau trong đội của bạn sẽ nhận được [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: lượng khiên bằng 15% máu tối đa của Giratina. , không thể chồng lên, mục tiêu tấn công khiên ma sẽ yếu: đòn tấn công kép giảm 15% trong 2 lượt); khi chuyển sang dạng gốc, 30% lượng HP đã mất có thể được phục hồi (không bị ảnh hưởng bởi phương pháp điều trị bị cấm) và bản thân sẽ không tái sinh khi tấn công ở dạng gốc.',
		describe_en = 'When Giratio enters the scene, he will receive the number of ghosts of the heroes in his camp excluding himself (maximum number of ghosts: 5 points, cannot be dispelled or ignored), and each ghost can reduce his own number of ghosts by #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. The final damage received will reduce one ghost each time he is hit. When a ghost is lost, 80 rage points will be restored \n#F20# \n#F40#. At the start of each major round, you and the hero with the lowest HP in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: shield amount equals 15% of Giratio’s max HP, cannot stack, the target attacked by the ghost shield will be weakened: double attacks reduce damage by 15% for 2 turns); when shifting to original form, 30% of lost HP can be recovered (not affected by forbidden healing methods), and will not resurrect when attacking in original form.',
		describe_th = 'เมื่อจิราเทียร์เข้าสู่สนาม เขาจะได้รับจำนวนผีของฮีโร่ในค่ายของเขานอกเหนือจากตัวเอง (จำนวนผีสูงสุด: 5 คะแนน ไม่สามารถขจัดหรือมองข้ามได้) และผีแต่ละตนสามารถลดจำนวนผีของตนเองได้ #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. ความเสียหายสุดท้ายที่ได้รับจะลดผีหนึ่งตัวทุกครั้งที่โดนโจมตี เมื่อผีลดลง จะฟื้นฟูความโกรธ 80 คะแนน \n#F20# \n#F40#. ในช่วงต้นของแต่ละรอบใหญ่ คุณและฮีโร่ที่มีพลังชีวิตต่ำที่สุดในแถวหลังของทีมจะได้รับ [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: โล่เท่ากับ 15% ของพลังชีวิตสูงสุดของจิราเทียร์ ไม่สามารถซ้อนทับได้ เป้าหมายที่ถูกโจมตีด้วยโล่ผีจะอ่อนแอ: การโจมตีคู่ลดลง 15% เป็นเวลา 2 เทิร์น); เมื่อเปลี่ยนเป็นรูปแบบเดิม จะฟื้นฟูพลังชีวิตที่เสียไป 30% (ไม่ถูกผลกระทบจากวิธีการรักษาต้องห้าม) และจะไม่ฟื้นคืนชีพเมื่อโจมตีในรูปแบบเดิม',
		describe_in = 'Ketika Giratio memasuki arena, dia akan menerima jumlah hantu para pahlawan di kampnya kecuali dirinya sendiri (batas maksimal jumlah hantu: 5 poin, tidak bisa dihilangkan atau diabaikan), dan setiap hantu dapat mengurangi jumlah hantunya sebanyak #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Kerusakan akhir yang diterima akan mengurangi satu hantu setiap kali terkena serangan. Saat hantu berkurang, 80 poin amarah akan dipulihkan \n#F20# \n#F40#. Pada awal setiap putaran besar, kamu dan pahlawan dengan HP terendah di barisan belakang timmu akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: jumlah perisai sebesar 15% dari HP maksimal Giratio, tidak dapat menumpuk, target yang diserang oleh perisai hantu akan melemah: serangan ganda berkurang 15% selama 2 giliran); saat beralih ke bentuk asli, 30% HP yang hilang dapat dipulihkan (tidak terpengaruh oleh metode penyembuhan terlarang), dan tidak akan bereinkarnasi saat menyerang dalam bentuk asli.',
		describe_ph = 'Kapag pumasok si Giratio sa lugar ng labanan, makakakuha siya ng bilang ng mga multo ng mga bayani sa kanyang kampo bukod sa sarili niya (pinakamataas na bilang ng mga multo: 5 puntos, hindi maaaring alisin o balewalain), at bawat multo ay maaaring bawasan ang kanyang sariling bilang ng mga multo ng #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Ang huling natanggap na pinsala ay magbabawas ng isang multo tuwing tinatamaan. Kapag nabawasan ang mga multo, mababawi ang 80 puntos ng galit \n#F20# \n#F40#. Sa simula ng bawat malaking round, ikaw at ang bayani na may pinakamababang porsyento ng HP sa likurang hanay ng iyong koponan ay makakatanggap ng [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: shield na katumbas ng 15% ng maximum HP ni Giratio, hindi maaaring mag-stack, ang target na aatakehin ng ghost shield ay magiging mahina: doble ang atake na nababawasan ng 15% sa loob ng 2 turn); kapag lumipat sa orihinal na anyo, maaaring mabawi ang 30% ng nawalang HP (hindi naaapektuhan ng mga ipinagbabawal na paraan ng paggaling) at hindi muling mabubuhay kapag umaatake sa orihinal na anyo.',
		describe_ma = 'Apabila Giratio memasuki medan pertempuran, dia akan menerima jumlah hantu wira dalam kem-kemnya selain dirinya sendiri (had maksimum bilangan hantu: 5, tidak boleh dihapus atau diabaikan), dan setiap hantu boleh mengurangkan bilangan hantunya sebanyak #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Kerosakan akhir yang diterima akan mengurangkan satu hantu setiap kali terkena serangan. Apabila hantu berkurangan, 80 mata kemarahan akan dipulihkan \n#F20# \n#F40#. Pada permulaan setiap pusingan besar, kamu dan wira yang memiliki peratusan darah terendah dalam barisan belakang pasukan kamu akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: jumlah perisai sama dengan 15% darah maksimum Giratio, tidak boleh bertindih, sasaran yang diserang oleh perisai hantu akan menjadi lemah: serangan berganda berkurang 15% selama 2 pusingan); apabila beralih ke bentuk asal, 30% HP yang hilang boleh dipulihkan (tidak terjejas oleh kaedah rawatan yang dilarang) dan dirinya tidak akan bangkit semula ketika menyerang dalam bentuk asal.',
		describe = 'When Giratio enters the scene, he will receive the number of ghosts of the heroes in his camp excluding himself (maximum number of ghosts: 5 points, cannot be dispelled or ignored), and each ghost can reduce his own number of ghosts by #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. The final damage received will reduce one ghost each time he is hit. When a ghost is lost, 80 rage points will be restored \n#F20# \n#F40#. At the start of each major round, you and the hero with the lowest HP in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: shield amount equals 15% of Giratio’s max HP, cannot stack, the target attacked by the ghost shield will be weakened: double attacks reduce damage by 15% for 2 turns); when shifting to original form, 30% of lost HP can be recovered (not affected by forbidden healing methods), and will not resurrect when attacking in original form.',
		starEffect = __data_t__starEffect[210426],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Quỷ khiên nâng cấp: tăng 5% lượng khiên, mỗi lượt lớn kết thúc bản thân nhận 1 điểm Quỷ ảnh',
		starEffectDesc = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
		starEffectDesc_en = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
