	[210427] = {
		id = 210427,
		skillName_vn = 'Bị động',
		skillName_en = 'Passive',
		skillName_th = 'ถูกกระทำ',
		skillName_in = 'Pasif',
		skillName_ph = 'Passive',
		skillName_ma = 'Pasif',
		skillName = 'Passive',
		describe_vn = 'Khi Giratio bước vào hiện trường, anh ta sẽ nhận được số lượng hồn ma của các anh hùng trong trại của mình ngoài chính mình (giới hạn trên của số lượng ma: 5 điểm, không thể xua tan hoặc bỏ qua), và mỗi hồn ma có thể giảm số lượng hồn ma của mình #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# Sát thương cuối cùng nhận được sẽ giảm 1 hồn ma mỗi khi trúng đòn. Khi bóng ma giảm đi, 80 điểm thịnh nộ sẽ được phục hồi\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn, bạn và anh hùng có phần trăm máu thấp nhất ở hàng sau trong đội của bạn sẽ nhận được [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: lượng khiên bằng 15% máu tối đa của Giratina. , không thể chồng lên, mục tiêu tấn công khiên ma sẽ yếu: đòn tấn công kép giảm 15% trong 2 lượt); khi chuyển sang dạng gốc, 30% lượng HP đã mất có thể được phục hồi (không bị ảnh hưởng bởi phương pháp điều trị bị cấm) và bản thân sẽ không tái sinh khi tấn công ở dạng gốc.',
		describe_en = 'When Giratio enters the scene, he will receive a number of ghost souls from the heroes in his camp besides himself (maximum limit of spirits: 5 points, cannot be dispelled or ignored), and each ghost soul can reduce his own ghost soul count by #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. The final damage received will reduce one ghost soul each time he is hit. When spirits decrease, 80 rage points will be restored \n#F20# \n#F40#. At the start of each major round, you and the hero with the lowest health percentage in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: shield amount equal to 15% of Giratina\'s maximum HP, non-stackable, melee targets weakened: double attacks reduced by 15% for 2 turns); when switching to original form, 30% of lost HP can be recovered (not affected by forbidden healing methods) and the character will not revive when attacking in original form.',
		describe_th = 'เมื่อ Giratio เข้าสู่สนาม เขาจะได้รับจำนวนวิญญาณผีของเหล่าฮีโร่ในค่ายของเขานอกจากตัวเอง (ขีดจำกัดสูงสุดของวิญญาณ: 5 คะแนน ไม่สามารถลบหรือเพิกเฉยได้) และแต่ละวิญญาณผีสามารถลดจำนวนวิญญาณผีของตนเองได้ #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# ความเสียหายสุดท้ายที่ได้รับจะลดวิญญาณผีลง 1 ตัวทุกครั้งที่ถูกโจมตี เมื่อวิญญาณผีลดลง จะฟื้นฟูความโกรธ 80 คะแนน \n#F20# \n#F40# เมื่อเริ่มแต่ละรอบใหญ่ คุณและฮีโร่ที่มีเปอร์เซ็นต์เลือดต่ำที่สุดในแถวหลังของทีมคุณจะได้รับ [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: โล่เท่ากับ 15% ของพลังชีวิตสูงสุดของ Giratina ไม่สามารถซ้อนทับได้ เป้าหมายที่โจมตีโล่วิญญาณจะอ่อนแอ: การโจมตีคู่ลดลง 15% ใน 2 เทิร์น); เมื่อเปลี่ยนเป็นรูปแบบดั้งเดิม จะสามารถฟื้นฟู HP ที่เสียไป 30% (ไม่ถูกผลกระทบจากวิธีการรักษาที่ถูกห้าม) และตัวละครจะไม่คืนชีพเมื่อโจมตีในรูปแบบดั้งเดิม',
		describe_in = 'Saat Giratio memasuki medan pertarungan, dia akan menerima sejumlah roh hantu dari para pahlawan di kampnya selain dirinya sendiri (batas atas jumlah roh: 5 poin, tidak dapat dibersihkan atau diabaikan), dan setiap roh hantu dapat mengurangi jumlah roh hantunya sendiri #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Kerusakan akhir yang diterima akan mengurangi satu roh hantu setiap kali terkena serangan. Ketika roh berkurang, 80 poin amarah akan dipulihkan \n#F20# \n#F40#. Pada awal tiap putaran besar, kamu dan pahlawan dengan persentase HP terendah di barisan belakang timmu akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: jumlah perisai setara dengan 15% HP maksimal Giratina, tidak bisa bertumpuk, target serangan perisai hantu akan melemah: serangan ganda dikurangi 15% selama 2 giliran); saat beralih ke bentuk asli, 30% HP yang hilang dapat dipulihkan (tidak terpengaruh oleh metode penyembuhan terlarang) dan karakter tidak akan bereinkarnasi saat menyerang dalam bentuk asli.',
		describe_ph = 'Kapag pumasok si Giratio sa eksena, makakatanggap siya ng bilang ng mga kaluluwa ng mga bayani sa kanyang kampo bukod sa kanyang sarili (pinakamataas na limitasyon ng mga kaluluwa: 5 puntos, hindi maaaring alisin o balewalain), at bawat kaluluwang multo ay maaaring bawasan ang sariling bilang ng mga kaluluwa ni Giratio ng #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Ang huling natanggap na pinsala ay magbabawas ng isang kaluluwang multo sa tuwing tatamaan. Kapag bumaba ang mga multo, babangon ang 80 puntos ng galit \n#F20# \n#F40#. Sa simula ng bawat malaking round, ikaw at ang bayani na may pinakamababang porsyento ng HP sa likod na hanay ng iyong koponan ay makakatanggap ng [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: kalasag na katumbas ng 15% ng maximum HP ni Giratina, hindi pwedeng mag-stack, ang mga target na umaatake sa kalasag ng multo ay humihina: doble ang pag-atake ay nababawasan ng 15% sa loob ng 2 turn); kapag lumipat sa orihinal na anyo, 30% ng nawalang HP ay maaaring mabawi (hindi naapektuhan ng ipinagbabawal na paraan ng pagpapagaling) at hindi muling mabubuhay ang karakter kapag umaatake sa orihinal na anyo.',
		describe_ma = 'Apabila Giratio memasuki medan pertempuran, dia akan menerima sejumlah roh hantu dari wira dalam kem-nya selain dirinya sendiri (had atas jumlah roh: 5 mata, tidak boleh dihapus atau diabaikan), dan setiap roh hantu boleh mengurangkan jumlah rohnya sendiri sebanyak #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Kerosakan akhir yang diterima akan mengurangkan satu roh hantu setiap kali terkena serangan. Apabila roh berkurangan, 80 mata kemarahan akan dipulihkan \n#F20# \n#F40#. Pada permulaan setiap pusingan besar, anda dan wira yang mempunyai peratusan darah terendah di barisan belakang pasukan anda akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: jumlah pelindung bersamaan dengan 15% HP maksimum Giratina, tidak boleh bertindih, sasaran yang menyerang pelindung hantu akan menjadi lemah: serangan berganda dikurangkan 15% selama 2 giliran); apabila bertukar ke bentuk asal, 30% HP yang hilang dapat dipulihkan (tidak dipengaruhi oleh kaedah rawatan yang dilarang) dan karakter tidak akan bangkit semula ketika menyerang dalam bentuk asal.',
		describe = 'When Giratio enters the scene, he will receive a number of ghost souls from the heroes in his camp besides himself (maximum limit of spirits: 5 points, cannot be dispelled or ignored), and each ghost soul can reduce his own ghost soul count by #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. The final damage received will reduce one ghost soul each time he is hit. When spirits decrease, 80 rage points will be restored \n#F20# \n#F40#. At the start of each major round, you and the hero with the lowest health percentage in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: shield amount equal to 15% of Giratina\'s maximum HP, non-stackable, melee targets weakened: double attacks reduced by 15% for 2 turns); when switching to original form, 30% of lost HP can be recovered (not affected by forbidden healing methods) and the character will not revive when attacking in original form.',
		starEffect = __data_t__starEffect[210427],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Quỷ khiên nâng cấp: tăng 5% lượng khiên, mỗi lượt lớn kết thúc bản thân nhận 1 điểm Quỷ ảnh',
		starEffectDesc = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
		starEffectDesc_en = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
		starEffectDesc_th = 'เอฟเฟกต์การอัปเกรดโล่ปีศาจ: เพิ่มปริมาณโล่ 5% เมื่อสิ้นสุดแต่ละเทิร์นใหญ่ รับ 1 คะแนนเงาปีศาจ',
		starEffectDesc_in = 'Efek Peningkatan Perisai Setan: meningkatkan jumlah perisai sebesar 5%, pada akhir setiap giliran besar, menerima 1 poin Bayangan Setan',
		starEffectDesc_ph = 'Epekto ng Pag-upgrade ng Demon Shield: nagdaragdag ng 5% sa dami ng shield, sa pagtatapos ng bawat malaking turn ay tumatanggap ng 1 Demon Shadow point',
