	[210512] = {
		id = 210512,
		skillName_vn = 'Đòn tấn công bóng',
		skillName_en = 'Shadow attack',
		skillName_th = 'การโจมตีแบบเงา',
		skillName_in = 'Serangan bayangan',
		skillName_ph = 'Aninag na atake',
		skillName_ma = 'Serangan bayang',
		skillName = 'Shadow attack',
		describe_vn = 'Giratina biến thành ma và di chuyển đến một mục tiêu địch để đánh lén, gây #C0xE69900#170% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B# tăng khả năng giảm sát thương của cột mình thêm 15% trong 2 lượt. Sau khi tấn công, bản thân nhận được 2 điểm ma\n#F20# \n#F40#[#L10#Origin Form#L0#], phạm vi tấn công thay đổi theo hàng và có thêm 80% xác suất [#L10#Ghost Fire#L0#] trong 2 lượt\n[#L10# Netherworld Wisp#L0#]: Hiệu ứng tiêu cực đặc biệt, chỉ có thể xua tan và không thể áp dụng. Trước khi mục tiêu di chuyển hoặc khi Netherworld Wisp bị xua tan, máu của mục tiêu sẽ bị giảm (12% lượng máu tối đa của Giratina) và 120 điểm thịnh nộ.',
		describe_en = 'Giratina transforms into a ghost and moves to an enemy target to ambush, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Physical Damage #C0x5B545B# and increasing its own damage reduction by 15% for 2 turns. After attacking, it gains 2 points of ma\n#F20# \n#F40#[#L10#Origin Form#L0#], attack range changes by row and it gains an 80% chance of [#L10#Ghost Fire#L0#] for 2 turns. \n[#L10# Netherworld Wisp#L0#]: Special negative effect, can only be dispelled and cannot be applied again. Before the target moves or when Netherworld Wisp is dispelled, the target\'s HP is reduced (12% of Giratina\'s max HP) and it loses 120 rage.',
		describe_th = 'Giratina แปลงร่างเป็นผีและเคลื่อนที่ไปยังเป้าหมายศัตรูเพื่อโจมตีแบบซุ่มโจมตี สร้าง #C0xE69900#170% ความเสียหายกายภาพ#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# ความเสียหายกายภาพ #C0x5B545B# และเพิ่มความสามารถในการลดความเสียหายของตัวเองขึ้น 15% เป็นเวลา 2 เทิร์น หลังโจมตีจะได้รับ 2 คะแนน ma\n#F20# \n#F40#[#L10#Origin Form#L0#] ระยะการโจมตีเปลี่ยนแปลงตามแถวและมีโอกาส 80% ได้รับ [#L10#Ghost Fire#L0#] เป็นเวลา 2 เทิร์น \n[#L10# Netherworld Wisp#L0#]: เอฟเฟคทางลบพิเศษ สามารถลบออกได้เท่านั้นและไม่สามารถใช้ซ้ำได้ ก่อนที่เป้าหมายจะเคลื่อนที่หรือเมื่อ Netherworld Wisp ถูกลบเลือดของเป้าหมายจะลดลง (12% ของเลือดสูงสุดของ Giratina) และเสีย 120 แต้มโกรธ',
		describe_in = 'Giratina berubah menjadi hantu dan bergerak ke target musuh untuk menyergap, memberikan #C0xE69900#170% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Kerusakan Fisik #C0x5B545B# serta meningkatkan kemampuan self reduction damage sebesar 15% selama 2 giliran. Setelah menyerang, dirinya menerima 2 poin ma\n#F20# \n#F40#[#L10#Origin Form#L0#], jangkauan serangan berubah berdasarkan baris dan mendapatkan 80% peluang [#L10#Ghost Fire#L0#] selama 2 giliran. \n[#L10# Netherworld Wisp#L0#]: Efek negatif khusus, hanya bisa dihapus dan tidak bisa diterapkan lagi. Sebelum target bergerak atau saat Netherworld Wisp dihapus, HP target akan berkurang (12% HP maksimal Giratina) dan kehilangan 120 amarah.',
		describe_ph = 'Nagiging multo si Giratina at lumilipat sa isang kaaway na target para umatake nang palihim, nagdudulot ng #C0xE69900#170% Pisikal na Pinsala#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Pisikal na Pinsala #C0x5B545B# at pinapataas ang kakayahan nitong bawasan ang natatanggap na pinsala ng 15% sa loob ng 2 turn. Pagkatapos umatake, nakakakuha ito ng 2 puntos ng ma\n#F20# \n#F40#[#L10#Origin Form#L0#], nagbabago ang saklaw ng atake ayon sa hilera at may 80% tsansa na magkaroon ng [#L10#Ghost Fire#L0#] sa loob ng 2 turn. \n[#L10# Netherworld Wisp#L0#]: Espesyal na negatibong epek, maaari lamang matanggal pero hindi maipapatupad muli. Bago kumilos ang target o kapag naalis ang Netherworld Wisp, mababawasan ang HP ng target (12% ng max HP ni Giratina) at mawawala ang 120 galit.',
		describe_ma = 'Giratina berubah menjadi hantu dan bergerak ke sasaran musuh untuk menyerang secara sembunyi, memberikan #C0xE69900#170% Serangan Fizikal#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Serangan Fizikal #C0x5B545B# serta meningkatkan keupayaan pengurangan kerosakan diri sendiri sebanyak 15% selama 2 pusingan. Selepas menyerang, ia menerima 2 mata ma\n#F20# \n#F40#[#L10#Origin Form#L0#], julat serangan berubah mengikut baris dan mempunyai peluang 80% untuk [#L10#Ghost Fire#L0#] selama 2 pusingan. \n[#L10# Netherworld Wisp#L0#]: Kesan negatif khas, hanya boleh dibersihkan dan tidak boleh digunakan semula. Sebelum sasaran bergerak atau apabila Netherworld Wisp dibersihkan, HP sasaran akan berkurang (12% HP maksimum Giratina) dan kehilangan 120 kemarahan.',
		describe = 'Giratina transforms into a ghost and moves to an enemy target to ambush, dealing #C0xE69900#170% Physical Damage#C0x5B545B#+$(skillLevel*4 *48)$\'s #C0xF13B54# Physical Damage #C0x5B545B# and increasing its own damage reduction by 15% for 2 turns. After attacking, it gains 2 points of ma\n#F20# \n#F40#[#L10#Origin Form#L0#], attack range changes by row and it gains an 80% chance of [#L10#Ghost Fire#L0#] for 2 turns. \n[#L10# Netherworld Wisp#L0#]: Special negative effect, can only be dispelled and cannot be applied again. Before the target moves or when Netherworld Wisp is dispelled, the target\'s HP is reduced (12% of Giratina\'s max HP) and it loses 120 rage.',
		simDesc_vn = 'Kira Đế Tân biến hình thành bóng ma, di chuyển đến trước mục tiêu đơn lẻ của kẻ thù để tấn công lén, gây sát thương vật lý, đồng thời tăng giới hạn tức giận của mục tiêu và bản thân nhận điểm ma quái; trong trạng thái nguồn gốc, phạm vi tấn công chuyển thành hàng và có xác suất kèm theo hồn ma.',
		simDesc_en = 'Kira Emperor transforms into a phantom, moving stealthily toward a single enemy target to perform a surprise attack, dealing physical damage, while increasing the target\'s anger limit and granting Kira a specter point; in origin state, the attack range changes to a row and has a chance to summon a ghost.',
		simDesc_th = 'จักรพรรดิกิระแปลงร่างเป็นเงาผี เคลื่อนที่ไปยังเป้าหมายศัตรูทีละคนเพื่อโจมตีแบบลอบทำร้าย สร้างความเสียหายทางกายภาพ พร้อมทั้งเพิ่มขีดจำกัดความโกรธของเป้าหมายและเพิ่มคะแนนวิญญาณผีให้ตัวเอง; ในสถานะต้นกำเนิด ระยะโจมตีจะเปลี่ยนเป็นแถวและมีโอกาสเรียกผีตามมา',
		simDesc_in = 'Kira Kaisar berubah menjadi bayangan hantu, bergerak ke depan sasaran musuh tunggal untuk menyerang secara tiba-tiba, memberikan kerusakan fisik, sekaligus meningkatkan batas kemarahan target dan mendapatkan poin hantu; dalam keadaan asal, jangkauan serangan berubah menjadi baris dan memiliki kemungkinan disertai hantu.',
		simDesc_ph = 'Si Kira Emperador ay nagbago bilang isang multo, lumalapit sa iisang target ng kalaban upang magsagawa ng isang lihim na pag-atake, na nagdudulot ng pisikal na pinsala, kasabay ng pagtaas ng hangganan ng galit ng target at pagkuha ng puntos ng espiritu; sa estado ng pinagmulan, ang saklaw ng pag-atake ay nagbabago sa isang hanay at may posibilidad na may kasamang multo.',
		simDesc_ma = 'Kira Maharaja berubah menjadi bayangan hantu, bergerak ke hadapan sasaran musuh tunggal untuk menyerang secara tiba-tiba, menyebabkan kerosakan fizikal, sambil meningkatkan had kemarahan sasaran dan menerima mata hantu; dalam keadaan asal, julat serangan berubah menjadi baris dan mempunyai kebarangkalian untuk disertai hantu.',
		simDesc = 'Kira Emperor transforms into a phantom, moving stealthily toward a single enemy target to perform a surprise attack, dealing physical damage, while increasing the target\'s anger limit and granting Kira a specter point; in origin state, the attack range changes to a row and has a chance to summon a ghost.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
