	[210513] = {
		id = 210513,
		skillName_vn = 'Thế giới đảo ngược',
		skillName_en = 'Reverse world',
		skillName_th = 'โลกกลับด้าน',
		skillName_in = 'Dunia terbalik',
		skillName_ph = 'Baliktad na mundo',
		skillName_ma = 'Dunia terbalik',
		skillName = 'Reverse world',
		describe_vn = 'Giratina thức tỉnh từ vực thẳm, sau đó triệu hồi lối vào thế giới đảo ngược, hút các đơn vị hàng đầu của kẻ địch vào đó, gây #C0xE69900#230% Sát Thương Vật Lý#C0x5B545B#+$(ski llLevel*4*48)$\'s #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, giảm cơn thịnh nộ của mục tiêu trúng đòn đi 250 điểm và nhận được 3 điểm ma sau khi tấn công\n#F20# \n#F40#Sau khi thực hiện chiêu thức đặc biệt, anh ta chuyển sang [#L10#Origin Form#L0#] trong 2 hiệp. Giới hạn trên của lượng máu của chính anh ta (chỉ tăng giới hạn trên), tốc độ và tỷ lệ kiểm soát tổng thể được tăng thêm 50% (không thể phân tán, chuyển giao hoặc sao chép). Chuyển sang chiêu thức đặc biệt mới (không cần nộ và không tiêu hao nộ khi phóng ra, hồi lại trong 2 lượt sau khi phóng): Phạm vi thay đổi đối với tất cả kẻ địch và có thêm 75% xác suất thêm [#L10#鬼鬼火#L0#] vào 4 tướng địch có nộ cao nhất trong 2 lượt.',
		describe_en = 'Giratina awakens from the abyss, then summons the entrance to the reversed world, pulling the enemy\'s top units in, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, reducing the target\'s rage by 250 points upon hit and gaining 3 soul points after attacking \n#F20# \n#F40# After performing the special move, he shifts to [#L10#Origin Form#L0#] for 2 turns. His maximum HP limit (only the upper limit increases), speed, and overall control rate increase by 50% (cannot be dispersed, transferred, or copied). Switches to a new special move (no rage needed and no rage consumed when cast, recovers in 2 turns after casting): Range changes to all enemies and gains a 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy generals with the highest rage for 2 turns.',
		describe_th = 'กิราติน่าตื่นขึ้นจากหุบเหว แล้วเรียกทางเข้าสู่โลกกลับด้าน ดึงหน่วยชั้นนำของศัตรูเข้ามา ทำความเสียหาย #C0xE69900#230% ความเสียหายกายภาพ#C0x5B545B# +$(skillLevel*4*48)$\'s #C0xF13B54# ความเสียหายกายภาพ #C0x5B545B# ลดความโกรธของเป้าหมายที่โดนโจมตีลง 250 คะแนน และได้รับ 3 แต้มวิญญาณ หลังโจมตี \n#F20# \n#F40# หลังจากใช้สกิลพิเศษ เขาจะเปลี่ยนเป็น [#L10#Origin Form#L0#] เป็นเวลา 2 เทิร์น ขีดจำกัดสูงสุดของพลังชีวิต (เพิ่มแค่ขีดจำกัดบน), ความเร็ว และอัตราการควบคุมโดยรวมเพิ่มขึ้น 50% (ไม่สามารถแจกจ่าย, โอน หรือก็อปปี้ได้) เปลี่ยนไปใช้สกิลพิเศษใหม่ (ไม่ต้องใช้โกรธและไม่ใช้โกรธเมื่อปล่อย, ฟื้นฟูหลัง 2 เทิร์น): ระยะเปลี่ยนเป็นทุกศัตรู และเพิ่มโอกาส 75% ที่จะเพิ่ม [#L10#鬼鬼火#L0#] ให้กับ 4 จอมทัพศัตรูที่มีโกรธสูงสุดเป็นเวลา 2 เทิร์น',
		describe_in = 'Giratina terbangun dari jurang, lalu memanggil pintu masuk ke dunia terbalik, menarik unit teratas musuh ke sana, memberikan #C0xE69900#230% Kerusakan Fisik#C0x5B545B# + $(skillLevel*4*48)$\'s #C0xF13B54# Kerusakan Fisik #C0x5B545B#, mengurangi kemarahan target yang terkena sebanyak 250 poin dan mendapatkan 3 poin jiwa setelah menyerang \n#F20# \n#F40# Setelah melakukan serangan khusus, ia beralih ke [#L10#Origin Form#L0#] selama 2 giliran. Batas atas HPnya (hanya batas atas yang meningkat), kecepatan, dan rasio kontrol keseluruhan meningkat sebesar 50% (tidak bisa didistribusikan, dipindahtangankan atau disalin). Beralih ke serangan khusus baru (tidak perlu kemarahan dan tidak menghabiskan kemarahan saat diluncurkan, pulih dalam 2 giliran setelah diluncurkan): Jangkauan berubah untuk semua musuh dan memiliki peluang 75% untuk menambahkan [#L10#鬼鬼火#L0#] ke 4 panglima musuh dengan kemarahan tertinggi selama 2 giliran.',
		describe_ph = 'Nagising si Giratina mula sa kailaliman, pagkatapos ay tinawag ang pasukan sa mundo ng baliktad, hinila ang mga nangungunang yunit ng kalaban doon, nagdudulot ng #C0xE69900#230% Pisikal na Pinsala#C0x5B545B# + $(skillLevel*4*48)$\'s #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, binabawasan ang galit ng tinatamaan ng 250 puntos at nakakakuha ng 3 puntos ng kaluluwa pagkatapos umatake \n#F20# \n#F40# Pagkatapos gawin ang espesyal na galaw, siya ay nagpalit sa [#L10#Origin Form#L0#] sa loob ng 2 turno. Ang itaas na limitasyon ng kanyang HP (tanging ang itaas na limitasyon ang tumataas), bilis, at pangkalahatang rate ng kontrol ay tumaas ng 50% (hindi maaaring ipamahagi, ilipat o kopyahin). Lumipat sa bagong espesyal na galaw (hindi kailangan ng galit at walang galit na ginagastos kapag inilunsad, bumabalik pagkatapos ng 2 turno mula sa paglunsad): Ang saklaw ay nagbabago para sa lahat ng kalaban at may 75% na pagkakataon na magdagdag ng [#L10#鬼鬼火#L0#] sa 4 na pinakamaraming galit na heneral ng kalaban sa loob ng 2 turno.',
		describe_ma = 'Giratina terjaga dari lembah, kemudian memanggil pintu masuk ke dunia terbalik, menarik unit teratas musuh ke situ, memberikan #C0xE69900#230% Kerosakan Fizikal#C0x5B545B# + $(skillLevel*4*48)$\'s #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, mengurangkan kemarahan sasaran yang terkena sebanyak 250 mata dan menerima 3 mata jiwa selepas menyerang \n#F20# \n#F40# Selepas melakukan serangan khas, dia beralih kepada [#L10#Origin Form#L0#] selama 2 giliran. Had atas HPnya (hanya had atas bertambah), kelajuan, dan kadar kawalan keseluruhan meningkat sebanyak 50% (tidak boleh diagihkan, dipindah milik atau disalin). Beralih kepada serangan khas baru (tidak perlu nadi dan tidak menggunakan nadi semasa dilancarkan, pulih dalam 2 giliran selepas dilancarkan): Julat berubah kepada semua musuh dan mempunyai 75% peluang untuk menambah [#L10#鬼鬼火#L0#] ke 4 jeneral musuh dengan nadi tertinggi selama 2 giliran.',
		describe = 'Giratina awakens from the abyss, then summons the entrance to the reversed world, pulling the enemy\'s top units in, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$\'s #C0xF13B54# Physical Damage #C0x5B545B#, reducing the target\'s rage by 250 points upon hit and gaining 3 soul points after attacking \n#F20# \n#F40# After performing the special move, he shifts to [#L10#Origin Form#L0#] for 2 turns. His maximum HP limit (only the upper limit increases), speed, and overall control rate increase by 50% (cannot be dispersed, transferred, or copied). Switches to a new special move (no rage needed and no rage consumed when cast, recovers in 2 turns after casting): Range changes to all enemies and gains a 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy generals with the highest rage for 2 turns.',
		simDesc_vn = 'Kira Đế Tân từ vực sâu tỉnh dậy, sau đó triệu hồi cổng vào thế giới đảo ngược, hút các đơn vị kẻ thù ở hàng trước vào trong đó, gây sát thương vật lý, giảm giá trị tức giận của chúng và hồi phục điểm ma quái; sau đó, hầu hết thuộc tính sẽ được nâng cấp chuyển sang trạng thái nguồn gốc; trong trạng thái nguồn gốc, phạm vi tấn công chuyển thành toàn bộ và có xác suất rất cao kèm theo hồn ma.',
		simDesc_en = 'Kira Te Tân awakens from the abyss, then summons a portal to the reversed world, pulling enemy units in the front row inside, dealing physical damage, reducing their rage value, and restoring phantom points; after that, most attributes will be upgraded and switched to origin state; in origin state, attack range changes to entire field with a very high chance accompanied by a ghost.',
		simDesc_th = 'คิระ เต ตัน ฟื้นตัวจากห้วงลึก จากนั้นเรียกประตูสู่โลกกลับด้าน ดึงหน่วยศัตรูแถวหน้าเข้ามาข้างใน สร้างความเสียหายทางกายภาพ ลดค่าความโกรธของพวกมัน และฟื้นฟูพลังวิญญาณ; หลังจากนั้น คุณสมบัติเกือบทั้งหมดจะถูกอัปเกรดเป็นสถานะต้นกำเนิด; ในสถานะต้นกำเนิด ระยะโจมตีจะกลายเป็นทั่วทั้งสนาม และมีโอกาสมากที่มาพร้อมกับผี',
		simDesc_in = 'Kira Te Tân bangkit dari jurang, kemudian memanggil portal ke dunia terbalik, menarik unit musuh di baris depan ke dalamnya, memberikan kerusakan fisik, mengurangi nilai kemarahan mereka, dan memulihkan poin hantu; setelah itu, sebagian besar atribut akan ditingkatkan dan berubah ke keadaan asal; dalam keadaan asal, jangkauan serangan berubah menjadi seluruh area dengan kemungkinan sangat tinggi disertai dengan roh hantu.',
		simDesc_ph = 'Nagising si Kira Te Tân mula sa kailaliman, pagkatapos ay summona ang portal papunta sa baliktad na mundo, hinihila ang mga yunit ng kalaban sa harapang linya papasok dito, nagdudulot ng pisikal na pinsala, nagpapababa ng kanilang halaga ng galit, at nagpapagaling ng phantom points; pagkatapos nito, karamihan sa mga katangian ay ia-upgrade at ililipat sa estado ng pinagmulan; sa estado ng pinagmulan, ang saklaw ng pag-atake ay nagsisilbing buong larangan na may napakataas na posibilidad na may kasamang espiritu.',
		simDesc_ma = 'Kira Te Tân bangkit dari jurang, kemudian memanggil pintu masuk ke dunia terbalik, menyedut unit musuh di barisan depan ke dalamnya, menyebabkan kerosakan fizikal, mengurangkan nilai kemarahan mereka dan memulihkan mata hantu; selepas itu, kebanyakan atribut akan dinaik taraf ke keadaan asal; dalam keadaan asal, julat serangan berubah menjadi keseluruhan dan mempunyai kemungkinan sangat tinggi disertai dengan hantu.',
		simDesc = 'Kira Te Tân awakens from the abyss, then summons a portal to the reversed world, pulling enemy units in the front row inside, dealing physical damage, reducing their rage value, and restoring phantom points; after that, most attributes will be upgraded and switched to origin state; in origin state, attack range changes to entire field with a very high chance accompanied by a ghost.',
		starEffect = __data_t__starEffect[210513],
		-- {11}
		starEffectDesc_vn = 'Kỹ năng chí mạng hình thái khác sẽ đảo ngược toàn bộ thế giới kéo dài 3 lượt: giảm tốc độ hồi phục tức giận của toàn bộ địch 15%; số lượt duy trì của hình thái nguồn gốc +1',
		starEffectDesc = 'Different form critical skill will invert the entire world for 3 turns: reduce all enemies\' anger recovery speed by 15%; origin form\'s duration +1',
		starEffectDesc_en = 'Different form critical skill will invert the entire world for 3 turns: reduce all enemies\' anger recovery speed by 15%; origin form\'s duration +1',
		starEffectDesc_th = 'ทักษะคริติคัลรูปร่างต่างจะทำให้โลกทั้งใบกลับด้านเป็นเวลา 3 เทิร์น: ลดความเร็วฟื้นฟูความโกรธของศัตรูทั้งหมดลง 15%; ระยะเวลารูปร่างต้นกำเนิด +1',
		starEffectDesc_in = 'Skill kritis bentuk berbeda akan membalik seluruh dunia selama 3 giliran: mengurangi kecepatan pemulihan amarah musuh sebesar 15%; durasi bentuk asal +1',
		starEffectDesc_ph = 'Ang iba’t ibang anyo ng kritikal na kasanayan ay mag-iinvert ng buong mundo sa loob ng 3 turn: bawasan ang bilis ng pagbawi ng galit ng lahat ng kalaban ng 15%; dagdagan ng 1 ang tagal ng anyo ng pinagmulan',
		starEffectDesc_ma = 'Kemahiran kritikal bentuk berbeza akan memutar balikkan seluruh dunia selama 3 pusingan: mengurangkan kelajuan pulih kemarahan semua musuh sebanyak 15%; tempoh bentuk asal +1',
