	[210516] = {
		id = 210516,
		skillName_vn = 'Bóng ma dày đặc',
		skillName_en = 'Dense ghost',
		skillName_th = 'ผีหนาแน่น',
		skillName_in = 'Hantu yang padat',
		skillName_ph = 'Mabangis na multo',
		skillName_ma = 'Hantu tebal',
		skillName = 'Dense ghost',
		describe_vn = 'Khi Giratio bước vào hiện trường, anh ta sẽ nhận được số lượng hồn ma của các anh hùng trong trại của mình ngoài chính mình (giới hạn trên của số lượng ma: 5 điểm, không thể xua tan hoặc bỏ qua), và mỗi hồn ma có thể giảm số lượng hồn ma của mình #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# Sát thương cuối cùng nhận được sẽ giảm 1 hồn ma mỗi khi trúng đòn. Khi bóng ma giảm đi, 80 điểm thịnh nộ sẽ được phục hồi\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn, bạn và anh hùng có phần trăm máu thấp nhất ở hàng sau trong đội của bạn sẽ nhận được [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: lượng khiên bằng 15% máu tối đa của Giratina. , không thể chồng lên, mục tiêu tấn công khiên ma sẽ yếu: đòn tấn công kép giảm 15% trong 2 lượt); khi chuyển sang dạng gốc, 30% lượng HP đã mất có thể được phục hồi (không bị ảnh hưởng bởi phương pháp điều trị bị cấm) và bản thân sẽ không tái sinh khi tấn công ở dạng gốc.',
		describe_en = 'When Giratio enters the battlefield, he will receive the number of ghosts of the heroes in his camp excluding himself (maximum ghosts limit: 5, cannot be dispelled or ignored), and each ghost can reduce his ghost count by #(4 + s killLevel * 0.04 - 0.04)%#. The last damage received will reduce one ghost per hit. When a ghost is lost, 80 rage points will be restored. At the beginning of each major round, you and the hero with the lowest HP percentage in the back row of your team will receive [Ghost Shield] (Ghost Shield: shield amount equal to 15% of Giratio’s max HP, cannot stack, targets attacking the ghost shield will be weakened: double attacks reduce damage by 15% for 2 turns). When reverting to original form, 30% of lost HP can be recovered (not affected by forbidden healing methods) and the user will not resurrect when attacking in original form.',
		describe_th = 'เมื่อ Giratio เข้าสู่สนามรบ เขาจะได้รับจำนวนผีของฮีโร่ในค่ายของเขานอกเหนือจากตัวเขาเอง (จำกัดจำนวนผีสูงสุด: 5 ตัว ไม่สามารถลบหรือมองข้ามได้) และผีแต่ละตัวสามารถลดจำนวนผีของเขาได้ #(4 + s killLevel * 0.04 - 0.04)%#. ความเสียหายครั้งสุดท้ายที่ได้รับจะลดจำนวนผีลง 1 ตัวต่อการโจมตี เมื่อผีลดลง จะฟื้นฟูค่าความโกรธ 80 คะแนน ในแต่ละรอบใหญ่ คุณและฮีโร่ที่มีเปอร์เซ็นต์ HP ต่ำที่สุดในแถวหลังของทีมจะได้รับ [Ghost Shield] (Ghost Shield: โล่เท่ากับ 15% ของ HP สูงสุดของ Giratio ไม่สามารถซ้อนทับได้ เป้าหมายที่โจมตีโล่วิญญาณจะอ่อนแอลง: การโจมตีคู่ลดความเสียหาย 15% เป็นเวลา 2 เทิร์น) เมื่อกลับสู่รูปแบบเดิม จะฟื้นฟู HP ที่เสียไป 30% (ไม่ได้รับผลกระทบจากวิธีการรักษาที่ห้าม) และตัวเองจะไม่ฟื้นคืนชีพเมื่อโจมตีในรูปแบบเดิม',
		describe_in = 'Ketika Giratio memasuki medan tempur, dia akan menerima jumlah hantu dari para pahlawan di kampnya selain dirinya sendiri (batas maksimum hantu: 5, tidak bisa dihapus atau diabaikan), dan setiap hantu dapat mengurangi jumlah hantunya sebanyak #(4 + s killLevel * 0.04 - 0.04)%#. Kerusakan terakhir yang diterima akan mengurangi satu hantu setiap kali terkena serangan. Ketika hantu berkurang, 80 poin kemarahan akan dipulihkan. Pada awal setiap putaran besar, kamu dan pahlawan dengan persentase HP terendah di barisan belakang timmu akan menerima [Perisai Hantu] (Perisai Hantu: jumlah perisai setara dengan 15% HP maksimum Giratio, tidak dapat ditumpuk, target yang menyerang perisai hantu akan melemah: serangan ganda mengurangi kerusakan sebesar 15% selama 2 giliran). Saat beralih ke bentuk asli, 30% HP yang hilang dapat dipulihkan (tidak dipengaruhi oleh metode penyembuhan terlarang) dan dia tidak akan hidup kembali saat menyerang dalam bentuk asli.',
		describe_ph = 'Kapag pumasok si Giratio sa laban, makakakuha siya ng bilang ng mga espiritu ng mga bayani sa kampo niya maliban sa sarili niya (pinakamataas na bilang ng espiritu: 5 puntos, hindi maaaring alisin o balewalain), at bawat espiritu ay maaaring magbawas ng kanyang bilang ng espiritu ng #(4 + s killLevel * 0.04 - 0.04)%#. Ang huling natanggap na pinsala ay magbabawas ng isang espiritu sa bawat tama. Kapag nabawasan ang espiritu, babalik ang 80 puntos ng galit. Sa simula ng bawat malaking round, ikaw at ang bayani na may pinakamababang porsyento ng HP sa likod na hanay ng iyong koponan ay makakatanggap ng [Ghost Shield] (Ghost Shield: shield na katumbas ng 15% ng max HP ni Giratio, hindi pwedeng pagsabayin, ang mga target na umatake sa ghost shield ay humihina: ang doble na atake ay bumabawas ng 15% pinsala sa loob ng 2 turns). Kapag bumalik sa orihinal na anyo, maaaring maibalik ang 30% ng nawalang HP (hindi naapektuhan ng ipinagbabawal na paraan ng pagpapagaling) at hindi siya muling mabubuhay kapag umaatake sa orihinal na anyo.',
		describe_ma = 'Apabila Giratio memasuki medan pertempuran, dia akan menerima bilangan hantu wira dalam kemnya selain dirinya sendiri (had bilangan hantu maksimum: 5, tidak boleh dihapus atau diabaikan), dan setiap hantu boleh mengurangkan bilangan hantunya sebanyak #(4 + s killLevel * 0.04 - 0.04)%#. Kerosakan terakhir yang diterima akan mengurangkan satu hantu setiap kali terkena serangan. Apabila hantu berkurang, 80 mata kemarahan akan dipulihkan. Pada permulaan setiap pusingan besar, anda dan wira yang mempunyai peratusan darah paling rendah di barisan belakang pasukan anda akan menerima [Perisai Hantu] ([Perisai Hantu]: jumlah perisai bersamaan 15% darah maksimum Giratio, tidak boleh bertindan, sasaran yang menyerang perisai hantu akan menjadi lemah: serangan berganda mengurangkan 15% kerosakan selama 2 giliran). Apabila beralih ke bentuk asal, 30% daripada darah yang hilang boleh dipulihkan (tidak terjejas oleh kaedah rawatan yang dilarang) dan dirinya tidak akan hidup semula ketika menyerang dalam bentuk asal.',
		describe = 'When Giratio enters the battlefield, he will receive the number of ghosts of the heroes in his camp excluding himself (maximum ghosts limit: 5, cannot be dispelled or ignored), and each ghost can reduce his ghost count by #(4 + s killLevel * 0.04 - 0.04)%#. The last damage received will reduce one ghost per hit. When a ghost is lost, 80 rage points will be restored. At the beginning of each major round, you and the hero with the lowest HP percentage in the back row of your team will receive [Ghost Shield] (Ghost Shield: shield amount equal to 15% of Giratio’s max HP, cannot stack, targets attacking the ghost shield will be weakened: double attacks reduce damage by 15% for 2 turns). When reverting to original form, 30% of lost HP can be recovered (not affected by forbidden healing methods) and the user will not resurrect when attacking in original form.',
		starEffect = __data_t__starEffect[210516],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Quỷ khiên nâng cấp: tăng 5% lượng khiên, mỗi lượt lớn kết thúc bản thân nhận 1 điểm Quỷ ảnh',
		starEffectDesc = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
		starEffectDesc_en = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
		starEffectDesc_th = 'เอฟเฟกต์การอัปเกรดโล่ปีศาจ: เพิ่มปริมาณโล่ 5% เมื่อสิ้นสุดแต่ละเทิร์นใหญ่ รับ 1 คะแนนเงาปีศาจ',
		starEffectDesc_in = 'Efek Peningkatan Perisai Setan: meningkatkan jumlah perisai sebesar 5%, pada akhir setiap giliran besar, menerima 1 poin Bayangan Setan',
		starEffectDesc_ph = 'Epekto ng Pag-upgrade ng Demon Shield: nagdaragdag ng 5% sa dami ng shield, sa pagtatapos ng bawat malaking turn ay tumatanggap ng 1 Demon Shadow point',
		starEffectDesc_ma = 'Kesan Naik Taraf Perisai Iblis: meningkatkan jumlah perisai sebanyak 5%, pada akhir setiap giliran besar, menerima 1 mata Bayangan Iblis',
		changeUnitTrigger = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {2105161, 2105162, 2105163}
	},
	[210517] = {
		id = 210517,
		skillName_vn = 'Bị động',
		skillName_en = 'Passive',
		skillName_th = 'ถูกกระทำ',
		skillName_in = 'Pasif',
		skillName_ph = 'Passive',
		skillName_ma = 'Pasif',
		skillName = 'Passive',
		describe_vn = 'Khi Giratio bước vào hiện trường, anh ta sẽ nhận được số lượng hồn ma của các anh hùng trong trại của mình ngoài chính mình (giới hạn trên của số lượng ma: 5 điểm, không thể xua tan hoặc bỏ qua), và mỗi hồn ma có thể giảm số lượng hồn ma của mình #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# Sát thương cuối cùng nhận được sẽ giảm 1 hồn ma mỗi khi trúng đòn. Khi bóng ma giảm đi, 80 điểm thịnh nộ sẽ được phục hồi\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn, bạn và anh hùng có phần trăm máu thấp nhất ở hàng sau trong đội của bạn sẽ nhận được [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: lượng khiên bằng 15% máu tối đa của Giratina. , không thể chồng lên, mục tiêu tấn công khiên ma sẽ yếu: đòn tấn công kép giảm 15% trong 2 lượt); khi chuyển sang dạng gốc, 30% lượng HP đã mất có thể được phục hồi (không bị ảnh hưởng bởi phương pháp điều trị bị cấm) và bản thân sẽ không tái sinh khi tấn công ở dạng gốc.',
		describe_en = 'When Giratio enters the battlefield, he will receive the number of ghosts of the heroes in his camp excluding himself (maximum number of ghosts: 5 points, cannot be dispelled or ignored). Each ghost can reduce his own number of ghosts by #(4 + s killLevel * 0.04 - 0.04)%#. The final damage received will reduce one ghost each time he is hit. When a ghost decreases, 80 rage points will be restored. At the start of each major round, you and the hero with the lowest health percentage in the back row of your team will receive [Ghost Shield] (Ghost Shield: shield amount equal to 15% of Giratio\'s maximum health, cannot be stacked, targets attacking the ghost shield will be weakened: dual attacks are reduced by 15% for 2 turns). When transforming back to original form, 30% of lost HP can be recovered (not affected by forbidden healing methods), and Giratio will not revive when attacking in original form.',
		describe_th = 'เมื่อ Giratio เข้าสู่สนามรบ เขาจะได้รับจำนวนผีของฮีโร่ในค่ายของเขายกเว้นตัวเอง (จำนวนผีสูงสุด: 5 จุด, ไม่สามารถขจัดหรือละเว้นได้) แต่ละผีสามารถลดจำนวนผีของเขาเองได้ #(4 + s killLevel * 0.04 - 0.04)%# ความเสียหายสุดท้ายที่ได้รับจะลดผีหนึ่งตัวทุกครั้งที่ถูกโจมตี เมื่อผีลดลง จะได้รับการฟื้นฟูพลังแค้น 80 คะแนน ในช่วงเริ่มต้นของรอบใหญ่แต่ละรอบ คุณและฮีโร่ที่มีเปอร์เซ็นต์เลือดต่ำสุดในแถวหลังของทีมจะได้รับ [โล่ผี] (โล่ผี: เกราะเท่ากับ 15% ของพลังชีวิตสูงสุดของ Giratio ไม่สามารถวางซ้อนเป้าหมายที่โจมตีโล่ผีจะถูกอ่อนแอ: การโจมตีคู่ลดลง 15% เป็นเวลา 2 เทิร์น) เมื่อเปลี่ยนกลับเป็นรูปแบบต้นฉบับ สามารถฟื้นฟูพลังชีวิตที่เสียไป 30% (ไม่ถูกผลกระทบโดยวิธีการรักษาต้องห้าม) และจะไม่ฟื้นคืนชีพเมื่อโจมตีในรูปแบบต้นฉบับ',
		describe_in = 'Saat Giratio memasuki medan perang, dia akan menerima jumlah hantu dari para pahlawan di kampnya selain dirinya sendiri (batas atas jumlah hantu: 5 poin, tidak bisa dihapus atau diabaikan). Setiap hantu dapat mengurangi jumlah hantunya sendiri sebanyak #(4 + s killLevel * 0.04 - 0.04)%#. Kerusakan akhir yang diterima akan mengurangi satu hantu setiap kali terkena serangan. Ketika hantu berkurang, 80 poin kemarahan akan dipulihkan. Pada awal setiap putaran besar, kamu dan pahlawan dengan persentase HP terendah di barisan belakang timmu akan menerima [Perisai Hantu] (Perisai Hantu: jumlah perisai sama dengan 15% dari HP maksimum Giratio, tidak dapat ditumpuk, target yang menyerang perisai hantu akan melemah: serangan ganda berkurang 15% selama 2 giliran). Saat berubah kembali ke bentuk asli, 30% HP yang hilang dapat dipulihkan (tidak terpengaruh oleh metode penyembuhan terlarang), dan Giratio tidak akan hidup kembali saat menyerang dalam bentuk asli.',
		describe_ph = 'Kapag pumasok si Giratio sa larangan ng digmaan, matatanggap niya ang bilang ng mga multo ng mga bayani sa kanyang kampo maliban sa kanyang sarili (pinakamataas na bilang ng multo: 5 puntos, hindi maaaring mapawi o balewalain). Bawat multo ay maaaring magpabawas ng kanyang sariling bilang ng mga multo ng #(4 + s killLevel * 0.04 - 0.04)%#. Ang huling damage na matatanggap ay magbabawas ng isang multo sa tuwing matatamaan. Kapag bumaba ang mga multo, 80 puntos ng galit ang mare-restore. Sa simula ng bawat malaking round, ikaw at ang bayani na may pinakamababang porsyento ng HP sa likurang hanay ng iyong koponan ay makakatanggap ng [Ghost Shield] (Ghost Shield: halaga ng shield na katumbas ng 15% ng maximum na HP ng Giratio, hindi maaaring mag-stack, ang target na umatake sa multo na shield ay magiging mahina: ang dobleng atake ay bumababa ng 15% sa loob ng 2 turn). Kapag bumalik sa orihinal na anyo, 30% ng nawalang HP ay maaaring maibalik (hindi naaapektuhan ng ipinagbabawal na paraan ng pagpapagaling) at hindi siya muling magbubuhay kapag umaatake sa orihinal na anyo.',
		describe_ma = 'Apabila Giratio memasuki medan pertempuran, dia akan menerima bilangan hantu wira di kemnya selain dirinya sendiri (had maksimum bilangan hantu: 5 mata, tidak boleh dibuang atau diabaikan). Setiap hantu boleh mengurangkan bilangan hantunya sendiri sebanyak #(4 + s killLevel * 0.04 - 0.04)%#. Kerosakan terakhir yang diterima akan mengurangkan satu hantu setiap kali terkena serangan. Apabila bilangan hantu berkurangan, 80 mata kemarahan akan dipulihkan. Pada permulaan setiap pusingan besar, kamu dan wira yang mempunyai peratusan kesihatan paling rendah di barisan belakang pasukanmu akan menerima [Perisai Hantu] (Perisai Hantu: jumlah perisai bersamaan dengan 15% kesihatan maksimum Giratio, tidak boleh bertindih, sasaran menyerang perisai hantu akan menjadi lemah: serangan berganda dikurangkan 15% selama 2 pusingan). Apabila kembali ke bentuk asal, 30% HP yang hilang boleh dipulihkan (tidak terkesan oleh kaedah rawatan terlarang) dan Giratio tidak akan bangkit semula apabila menyerang dalam bentuk asal.',
		describe = 'When Giratio enters the battlefield, he will receive the number of ghosts of the heroes in his camp excluding himself (maximum number of ghosts: 5 points, cannot be dispelled or ignored). Each ghost can reduce his own number of ghosts by #(4 + s killLevel * 0.04 - 0.04)%#. The final damage received will reduce one ghost each time he is hit. When a ghost decreases, 80 rage points will be restored. At the start of each major round, you and the hero with the lowest health percentage in the back row of your team will receive [Ghost Shield] (Ghost Shield: shield amount equal to 15% of Giratio\'s maximum health, cannot be stacked, targets attacking the ghost shield will be weakened: dual attacks are reduced by 15% for 2 turns). When transforming back to original form, 30% of lost HP can be recovered (not affected by forbidden healing methods), and Giratio will not revive when attacking in original form.',
		starEffect = __data_t__starEffect[210517],
