	[210522] = {
		id = 210522,
		skillName_vn = 'Đuôi rồng',
		skillName_en = 'Dragon tail',
		skillName_th = 'หางมังกร',
		skillName_in = 'Ekor naga',
		skillName_ph = 'Buntot ng dragon',
		skillName_ma = 'Ekor naga',
		skillName = 'Dragon tail',
		describe_vn = 'Giratina sử dụng Đuôi Rồng để tấn công một mục tiêu địch, gây #C0xE69900#170% Sát Thương Vật Lý #C0x5B545B#+$(skillLevel*4*48)$ thuộc #C0xF13B54# Sát Thương Vật Lý #C0x5B545B#, tăng khả năng giảm sát thương cho cột của anh ta thêm 15% trong 2 lượt và nhận được 2 điểm ma sau đòn tấn công\n#F20# \n#F40#[#L10#Origin Form#L0#], phạm vi tấn công thay đổi theo hàng và có thêm 80% xác suất xảy ra [#L10#Ghost Fire#L0#] trong 2 lượt\n[#L10# Netherworld Wisp#L0#]: Hiệu ứng tiêu cực đặc biệt, chỉ có thể xua tan và không thể chồng lên. Trước khi mục tiêu di chuyển hoặc khi Netherworld Wisp bị xua tan, máu của mục tiêu sẽ bị giảm (12% lượng máu tối đa của Giratina) và 120 điểm thịnh nộ.',
		describe_en = 'Giratina uses Dragon Tail to attack an enemy target, dealing #C0xE69900#170% Physical Damage #C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage #C0x5B545B#, increasing his column’s damage reduction by 15% for 2 turns and gaining 2 ghost points after the attack\n#F20# \n#F40#[#L10#Origin Form#L0#], attack range changes according to the row and adds an 80% chance to trigger [#L10#Ghost Fire#L0#] for 2 turns\n[#L10# Netherworld Wisp#L0#]: A special negative effect that can only be dispelled and cannot be stacked. Before the target moves or when Netherworld Wisp is dispelled, the target’s HP is reduced (12% of Giratina\'s max HP) and 120 anger points are gained.',
		describe_th = 'Giratina ใช้หางมังกรโจมตียังเป้าหมายศัตรูหนึ่งตัว สร้างความเสียหายทางกายภาพ #C0xE69900#170% #C0x5B545B#+$(skillLevel*4*48)$ ของ #C0xF13B54#ความเสียหายทางกายภาพ #C0x5B545B# เพิ่มความสามารถในการลดความเสียหายของแถวของเขาอีก 15% เป็นเวลา 2 เทิร์นและได้รับ 2 คะแนนวิญญาณหลังการโจมตี\n#F20# \n#F40#[#L10#Origin Form#L0#] ช่วงการโจมตีเปลี่ยนไปตามแถวและเพิ่มโอกาส 80% ในการเกิด [#L10#Ghost Fire#L0#] เป็นเวลา 2 เทิร์น\n[#L10# Netherworld Wisp#L0#]: ผลกระทบลบพิเศษที่สามารถบรรเทาได้เท่านั้นและไม่สามารถซ้อนทับได้ ก่อนที่เป้าหมายจะเคลื่อนที่หรือเมื่อ Netherworld Wisp ถูกบรรเทา พลังชีวิตของเป้าหมายจะลดลง (12% ของพลังชีวิตสูงสุดของ Giratina) และได้รับจุดความโกรธ 120 จุด',
		describe_in = 'Giratina menggunakan Ekor Naga untuk menyerang satu target musuh, memberikan #C0xE69900#170% Kerusakan Fisik #C0x5B545B#+$(skillLevel*4*48)$ dari #C0xF13B54# Kerusakan Fisik #C0x5B545B#, meningkatkan kemampuan pengurangan kerusakan untuk kolomnya sebesar 15% selama 2 giliran dan mendapatkan 2 poin hantu setelah serangan\n#F20# \n#F40#[#L10#Origin Form#L0#], jangkauan serangan berubah sesuai baris dan menambahkan 80% peluang untuk memicu [#L10#Ghost Fire#L0#] selama 2 giliran\n[#L10# Netherworld Wisp#L0#]: Efek negatif khusus yang hanya bisa dihilangkan dan tidak bisa ditumpuk. Sebelum target bergerak atau saat Netherworld Wisp dihilangkan, HP target akan berkurang (12% dari HP maksimal Giratina) dan mendapatkan 120 poin kemarahan.',
		describe_ph = 'Giratina ay gumagamit ng Dragon Tail upang atakihin ang isang kalabang target, nagdudulot ng #C0xE69900#170% Pisikal na Pinsala #C0x5B545B#+$(skillLevel*4*48)$ ng #C0xF13B54# Pisikal na Pinsala #C0x5B545B#, pinapataas ang kakayahang magbawas ng pinsala para sa kanyang hanay ng 15% sa loob ng 2 turn at nakakakuha ng 2 ghost points pagkatapos ng atake\n#F20# \n#F40#[#L10#Origin Form#L0#], nagbabago ang saklaw ng pag-atake ayon sa hilera at may 80% tsansang mag-trigger ng [#L10#Ghost Fire#L0#] sa loob ng 2 turn\n[#L10# Netherworld Wisp#L0#]: Isang espesyal na negatibong epekto na maaari lamang tanggalin ngunit hindi puwedeng pagsamahin. Bago lumipat ang target o kapag tinanggal ang Netherworld Wisp, mababawasan ang HP ng target (12% ng max HP ni Giratina) at makakakuha ng 120 points ng galit.',
		describe_ma = 'Giratina menggunakan Ekor Naga untuk menyerang satu sasaran musuh, menyebabkan #C0xE69900#170% Kerosakan Fizikal #C0x5B545B#+$(skillLevel*4*48)$ daripada #C0xF13B54# Kerosakan Fizikal #C0x5B545B#, meningkatkan keupayaan pengurangan kerosakan untuk kolumnya sebanyak 15% selama 2 pusingan dan menerima 2 mata hantu selepas serangan\n#F20# \n#F40#[#L10#Origin Form#L0#], julat serangan berubah mengikut baris dan menambah 80% kemungkinan berlaku [#L10#Ghost Fire#L0#] selama 2 pusingan\n[#L10# Netherworld Wisp#L0#]: Kesan negatif khas, hanya boleh dihapuskan dan tidak boleh bertindih. Sebelum sasaran bergerak atau apabila Netherworld Wisp dihapuskan, darah sasaran akan berkurang (12% daripada jumlah darah maksimum Giratina) dan menerima 120 mata kemarahan.',
		describe = 'Giratina uses Dragon Tail to attack an enemy target, dealing #C0xE69900#170% Physical Damage #C0x5B545B#+$(skillLevel*4*48)$ of #C0xF13B54# Physical Damage #C0x5B545B#, increasing his column’s damage reduction by 15% for 2 turns and gaining 2 ghost points after the attack\n#F20# \n#F40#[#L10#Origin Form#L0#], attack range changes according to the row and adds an 80% chance to trigger [#L10#Ghost Fire#L0#] for 2 turns\n[#L10# Netherworld Wisp#L0#]: A special negative effect that can only be dispelled and cannot be stacked. Before the target moves or when Netherworld Wisp is dispelled, the target’s HP is reduced (12% of Giratina\'s max HP) and 120 anger points are gained.',
		simDesc_vn = 'Kira Đế Tân sử dụng đuôi rồng tấn công mục tiêu đơn lẻ của kẻ thù, gây sát thương vật lý, tăng giới hạn tức giận của mục tiêu và bản thân nhận điểm ma quái; trong trạng thái nguồn gốc, phạm vi tấn công chuyển thành hàng và có xác suất kèm theo hồn ma.',
		simDesc_en = 'Kira De Tan uses a dragon tail to attack a single enemy target, dealing physical damage, increasing the target\'s rage limit, and gaining phantom points for himself; in origin state, the attack range changes to a row and has a chance to accompany a ghost.',
		simDesc_th = 'คิร่า เดะ ตัน ใช้หางมังกรโจมตีเป้าหมายศัตรูเดียว สร้างความเสียหายทางกายภาพ เพิ่มขีดจำกัดความโกรธของเป้าหมาย และได้รับแต้มผี สำหรับตัวเอง; ในสถานะต้นกำเนิด ช่วงการโจมตีเปลี่ยนเป็นแถวและมีโอกาสที่จะมีผีร่วมด้วย',
		simDesc_in = 'Kira De Tan menggunakan ekor naga untuk menyerang satu target musuh, memberikan kerusakan fisik, meningkatkan batas kemarahan target, dan mendapatkan poin hantu untuk dirinya sendiri; dalam keadaan asal, jangkauan serangan berubah menjadi satu baris dan memiliki peluang disertai hantu.',
		simDesc_ph = 'Ginagamit ni Kira De Tan ang buntot ng dragon para atakihin ang isang target na kaaway, nagdudulot ng pisikal na pinsala, nagpapataas ng limit ng galit ng target, at nakakakuha ng phantom points para sa kanyang sarili; sa estado ng pinagmulan, nagbabago ang saklaw ng pag-atake sa isang hanay at may pagkakataong may kasamang espiritu.',
		simDesc_ma = 'Kira De Tan menggunakan ekor naga untuk menyerang satu sasaran musuh, menyebabkan kerosakan fizikal, meningkatkan had kemarahan sasaran dan memperoleh mata hantu untuk dirinya sendiri; dalam keadaan asal, julat serangan berubah menjadi barisan dan mempunyai kemungkinan disertai hantu.',
		simDesc = 'Kira De Tan uses a dragon tail to attack a single enemy target, dealing physical damage, increasing the target\'s rage limit, and gaining phantom points for himself; in origin state, the attack range changes to a row and has a chance to accompany a ghost.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
		upLvDesc_in = 'Kerusakan tetap +192',
		upLvDesc_ph = 'Fixed damage +192',
		upLvDesc_ma = 'Kerosakan tetap +192',
		upLvDesc_vn = 'Sát thương cố định +192',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		skillType2 = 1,
		skillNatureType = 14,
		cdRound = 2,
		posChoose = 1,
		targetTypeDesc = 'Single unit or enemy vertical row',
		targetTypeDesc_vn = 'Đơn thể hoặc hàng dọc địch',
		targetTypeDesc_en = 'Single unit or enemy vertical row',
		targetTypeDesc_th = 'ยูนิตเดี่ยวหรือแถวตั้งของศัตรู',
		targetTypeDesc_in = 'Unit tunggal atau baris vertikal musuh',
