	[210523] = {
		id = 210523,
		skillName_vn = 'Thế giới đảo ngược',
		skillName_en = 'Reverse world',
		skillName_th = 'โลกกลับด้าน',
		skillName_in = 'Dunia terbalik',
		skillName_ph = 'Baliktad na mundo',
		skillName_ma = 'Dunia terbalik',
		skillName = 'Reverse world',
		describe_vn = 'Giratina một lần nữa triệu hồi lối vào thế giới ngược để đẩy toàn bộ đơn vị địch xuống vực thẳm vô tận, gây #C0xE69900#230% Sát Thương Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, giảm cơn thịnh nộ của mục tiêu trúng đòn 250 điểm và nhận 3 điểm ma sau đó tấn công\n#F20# \n#F40#Sau khi thực hiện chiêu thức đặc biệt, anh ta chuyển sang [#L10#Origin Form#L0#] trong 2 hiệp. Giới hạn trên của lượng máu của chính anh ta (chỉ tăng giới hạn trên), tốc độ và tỷ lệ kiểm soát tổng thể được tăng thêm 50% (không thể phân tán, chuyển giao hoặc sao chép). Chuyển sang chiêu thức đặc biệt mới (không cần nộ và không tiêu hao nộ khi phóng ra, hồi lại trong 2 lượt sau khi phóng): Phạm vi thay đổi đối với tất cả kẻ địch và có thêm 75% xác suất thêm [#L10#鬼鬼火#L0#] vào 4 tướng địch có nộ cao nhất trong 2 lượt.',
		describe_en = 'Giratina once again summons the entrance to the reverse world to push all enemy units into an endless abyss, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, reducing the rage of targets hit by 250 points and gaining 3 demon points afterward \n#F20# \n#F40# After performing the special move, he switches to [#L10#Origin Form#L0#] for 2 turns. His maximum health limit (only the upper limit increases), speed, and overall control rate increase by 50% (cannot be dispersed, transferred, or copied). Switches to a new special move (no rage required and no rage consumed when released, recovers in 2 turns after release): The range changes to all enemies and there is an additional 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy generals with the highest rage for 2 turns.',
		describe_th = 'Giratina เรียกทางเข้าโลกกลับด้านอีกครั้งเพื่อผลักหน่วยศัตรูทั้งหมดลงสู่เหวที่ไม่มีที่สิ้นสุด สร้าง #C0xE69900#230% ความเสียหายทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ลดความโกรธของเป้าหมายที่ถูกโจมตีลง 250 แต้ม และได้รับ 3 คะแนนปีศาจหลังจากนั้น \n#F20# \n#F40# หลังจากใช้ท่าพิเศษ เขาจึงเปลี่ยนเป็น [#L10#Origin Form#L0#] เป็นเวลา 2 เทิร์น ขีดจำกัดบนของพลังชีวิตของเขา (เพิ่มเฉพาะขีดจำกัดบน) ความเร็ว และอัตราการควบคุมโดยรวม เพิ่มขึ้น 50% (ไม่สามารถกระจาย โอน หรือคัดลอกได้) เปลี่ยนไปสู่ท่าพิเศษใหม่ (ไม่ต้องใช้ความโกรธและไม่เสียความโกรธเมื่อใช้ ฟื้นฟูใน 2 เทิร์นหลังใช้): ระยะเปลี่ยนเป็นศัตรูทั้งหมดและมีโอกาส 75% เพิ่ม [#L10#鬼鬼火#L0#] ให้กับผู้บัญชาการศัตรู 4 คนที่มีความโกรธสูงสุดเป็นเวลา 2 เทิร์น',
		describe_in = 'Giratina sekali lagi memanggil pintu masuk ke dunia terbalik untuk mendorong semua unit musuh ke dalam jurang tanpa batas, memberikan #C0xE69900#230% Kerusakan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, mengurangi kemarahan target yang terkena sebesar 250 poin dan menerima 3 poin setan setelah itu \n#F20# \n#F40# Setelah melakukan gerakan khusus, dia berubah ke [#L10#Origin Form#L0#] selama 2 giliran. Batas atas dari jumlah HP-nya sendiri (hanya meningkatkan batas atas), kecepatan dan tingkat kontrol keseluruhan meningkat sebesar 50% (tidak dapat disebarkan, dipindahkan, atau disalin). Beralih ke gerakan khusus baru (tidak perlu rage dan tidak mengonsumsi rage saat dilempar, pulih dalam 2 giliran setelah dilempar): Jangkauan berubah menjadi semua musuh dan ada tambahan 75% peluang untuk menambahkan [#L10#鬼鬼火#L0#] ke 4 jenderal musuh dengan kemarahan tertinggi selama 2 giliran.',
		describe_ph = 'Muling tinatawag ni Giratina ang pintuan papunta sa reverse world upang itulak ang lahat ng kalabang yunit sa walang katapusang amihan, na nagdudulot ng #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, nagpapababa ng galit ng mga tinamaan ng 250 puntos at kumukuha ng 3 demon points pagkatapos nito \n#F20# \n#F40# Pagkatapos isagawa ang espesyal na galaw, siya ay lilipat sa [#L10#Origin Form#L0#] sa loob ng 2 turns. Ang itaas na limit ng kanyang HP (tanging ang itaas na limit lang ang tataas), bilis, at pangkalahatang kontrol rate ay tataas ng 50% (hindi maaaring ipamahagi, ilipat, o kopyahin). Lumilipat sa bagong espesyal na galaw (hindi nangangailangan ng galit at hindi kumokonsumo ng galit kapag inilabas, bumabawi sa loob ng 2 turns pagkatapos ilabas): Ang saklaw ay nagbabago sa lahat ng mga kalaban at may karagdagang 75% tsansa na magdagdag ng [#L10#鬼鬼火#L0#] sa 4 na pinakamaraming galit na kalaban na heneral sa loob ng 2 turns.',
		describe_ma = 'Giratina sekali lagi memanggil pintu masuk ke dunia songsang untuk menolak semua unit musuh ke jurang yang tiada berpenghujung, menyebabkan #C0xE69900#230% Kerosakan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, mengurangkan kemarahan sasaran yang terkena sebanyak 250 mata dan menerima 3 mata syaitan selepas itu \n#F20# \n#F40# Selepas melakukan langkah istimewa, dia beralih ke [#L10#Origin Form#L0#] selama 2 pusingan. Had atas jumlah kesihatannya sendiri (hanya meningkatkan had atas), kelajuan dan kadar kawalan keseluruhan ditingkatkan sebanyak 50% (tidak boleh diagihkan, dipindahkan atau disalin). Beralih kepada langkah istimewa baru (tidak perlu rage dan tidak menggunakan rage ketika dilancarkan, pulih dalam 2 pusingan selepas dilancarkan): Julat berubah kepada semua musuh dan ada tambahan 75% peluang untuk menambah [#L10#鬼鬼火#L0#] kepada 4 panglima musuh yang mempunyai rage tertinggi dalam 2 pusingan.',
		describe = 'Giratina once again summons the entrance to the reverse world to push all enemy units into an endless abyss, dealing #C0xE69900#230% Physical Damage#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, reducing the rage of targets hit by 250 points and gaining 3 demon points afterward \n#F20# \n#F40# After performing the special move, he switches to [#L10#Origin Form#L0#] for 2 turns. His maximum health limit (only the upper limit increases), speed, and overall control rate increase by 50% (cannot be dispersed, transferred, or copied). Switches to a new special move (no rage required and no rage consumed when released, recovers in 2 turns after release): The range changes to all enemies and there is an additional 75% chance to add [#L10#鬼鬼火#L0#] to the 4 enemy generals with the highest rage for 2 turns.',
		simDesc_vn = 'Kira Đế Tân một lần nữa triệu hồi cổng vào thế giới đảo ngược, khiến toàn bộ đơn vị kẻ thù rơi vào vực sâu vô tận, gây sát thương vật lý, giảm giá trị tức giận của chúng và có xác suất rất cao kèm theo hồn ma.',
		simDesc_en = 'Kira The Emperor Xin once again summons the gateway to the reversed world, causing all enemy units to fall into an endless abyss, dealing physical damage, reducing their anger value, and having a very high chance to inflict a ghost spirit.',
		simDesc_th = 'Kira จักรพรรดิซินได้เรียกประตูสู่โลกกลับด้านอีกครั้ง ทำให้หน่วยศัตรูทั้งหมดตกลงสู่หุบเหวมิรู้จบ สร้างความเสียหายทางกายภาพ ลดค่าความโกรธของพวกเขา และมีโอกาสสูงมากที่จะมาพร้อมกับวิญญาณผี',
		simDesc_in = 'Kira Kaisar Xin sekali lagi memanggil gerbang ke dunia terbalik, menyebabkan semua unit musuh jatuh ke dalam jurang yang tak berujung, memberikan kerusakan fisik, mengurangi nilai kemarahan mereka, dan memiliki peluang sangat tinggi disertai dengan roh hantu.',
		simDesc_ph = 'Minsan muli nang tinawag ni Kira The Emperor Xin ang pintuan papunta sa baliktad na mundo, na nagdudulot sa lahat ng yunit ng kalaban na mahulog sa walang katapusang bangin, nagdudulot ng pisikal na pinsala, nagpapababa ng halaga ng kanilang galit, at may mataas na posibilidad na may kasamang espiritu ng multo.',
		simDesc_ma = 'Kira Maharaja Xin sekali lagi memanggil pintu masuk ke dunia terbalik, menyebabkan semua unit musuh jatuh ke dalam jurang yang tidak berpenghujung, memberikan kerosakan fizikal, mengurangkan nilai kemarahan mereka, dan mempunyai peluang yang sangat tinggi untuk disertai roh hantu.',
		simDesc = 'Kira The Emperor Xin once again summons the gateway to the reversed world, causing all enemy units to fall into an endless abyss, dealing physical damage, reducing their anger value, and having a very high chance to inflict a ghost spirit.',
		starEffect = __data_t__starEffect[210523],
		-- {11}
		starEffectDesc_vn = 'Kỹ năng chí mạng hình thái khác sẽ đảo ngược toàn bộ thế giới kéo dài 3 lượt: giảm tốc độ hồi phục tức giận của toàn bộ địch 15%; số lượt duy trì của hình thái nguồn gốc +1',
		starEffectDesc = 'Different form critical skill will invert the entire world for 3 turns: reduce all enemies\' anger recovery speed by 15%; origin form\'s duration +1',
		starEffectDesc_en = 'Different form critical skill will invert the entire world for 3 turns: reduce all enemies\' anger recovery speed by 15%; origin form\'s duration +1',
		starEffectDesc_th = 'ทักษะคริติคัลรูปร่างต่างจะทำให้โลกทั้งใบกลับด้านเป็นเวลา 3 เทิร์น: ลดความเร็วฟื้นฟูความโกรธของศัตรูทั้งหมดลง 15%; ระยะเวลารูปร่างต้นกำเนิด +1',
		starEffectDesc_in = 'Skill kritis bentuk berbeda akan membalik seluruh dunia selama 3 giliran: mengurangi kecepatan pemulihan amarah musuh sebesar 15%; durasi bentuk asal +1',
		starEffectDesc_ph = 'Ang iba’t ibang anyo ng kritikal na kasanayan ay mag-iinvert ng buong mundo sa loob ng 3 turn: bawasan ang bilis ng pagbawi ng galit ng lahat ng kalaban ng 15%; dagdagan ng 1 ang tagal ng anyo ng pinagmulan',
		starEffectDesc_ma = 'Kemahiran kritikal bentuk berbeza akan memutar balikkan seluruh dunia selama 3 pusingan: mengurangkan kelajuan pulih kemarahan semua musuh sebanyak 15%; tempoh bentuk asal +1',
		upLvDesc = 'Fixed damage +192',
