	[210526] = {
		id = 210526,
		skillName_vn = 'Bóng ma dày đặc',
		skillName_en = 'Dense ghost',
		skillName_th = 'ผีหนาแน่น',
		skillName_in = 'Hantu yang padat',
		skillName_ph = 'Mabangis na multo',
		skillName_ma = 'Hantu tebal',
		skillName = 'Dense ghost',
		describe_vn = 'Khi Giratio bước vào hiện trường, anh ta sẽ nhận được số lượng hồn ma của các anh hùng trong trại của mình ngoài chính mình (giới hạn trên của số lượng ma: 5 điểm, không thể xua tan hoặc bỏ qua), và mỗi hồn ma có thể giảm số lượng hồn ma của mình #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# Sát thương cuối cùng nhận được sẽ giảm 1 hồn ma mỗi khi trúng đòn. Khi bóng ma giảm đi, 80 điểm thịnh nộ sẽ được phục hồi\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn, bạn và anh hùng có phần trăm máu thấp nhất ở hàng sau trong đội của bạn sẽ nhận được [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: lượng khiên bằng 15% máu tối đa của Giratina. , không thể chồng lên, mục tiêu tấn công khiên ma sẽ yếu: đòn tấn công kép giảm 15% trong 2 lượt); khi chuyển sang dạng gốc, 30% lượng HP đã mất có thể được phục hồi (không bị ảnh hưởng bởi phương pháp điều trị bị cấm) và bản thân sẽ không tái sinh khi tấn công ở dạng gốc.',
		describe_en = 'When Giratio enters the battlefield, he will receive the number of souls of the heroes in his camp excluding himself (maximum limit of souls: 5 points, cannot be dispelled or ignored), and each soul can reduce the number of his own souls by #(4 + s killLevel * 0.04 - 0.04)%#. The final damage received will reduce one soul each time he is hit. When souls are reduced, 80 points of Fury will be restored. At the start of each major round, you and the hero with the lowest health percentage in the back row of your team will receive [Ghost Shield] (Ghost Shield: shield amount equal to 15% of Giratio\'s max HP, cannot stack, targets attacked by ghost shield are weakened: dual attacks reduced by 15% for 2 turns); when transforming to original form, 30% of lost HP can be recovered (not affected by prohibited healing methods) and Giratio will not resurrect when attacking in original form.',
		describe_th = 'เมื่อ Giratio เข้าสู่สนามรบ เขาจะได้รับจำนวนวิญญาณของเหล่าวีรบุรุษในค่ายของเขานอกจากตัวเขาเอง (จำกัดสูงสุดของวิญญาณ: 5 แต้ม ไม่สามารถลบล้างหรือเพิกเฉยได้) และวิญญาณแต่ละดวงสามารถลดจำนวนวิญญาณของเขาเองลงได้ #(4 + s killLevel * 0.04 - 0.04)%#. ความเสียหายสุดท้ายที่ได้รับจะลดวิญญาณลง 1 ดวงทุกครั้งที่ถูกโจมตี เมื่อวิญญาณลดลง จะฟื้นฟูค่าโกรธได้ 80 แต้ม ในช่วงเริ่มต้นของแต่ละรอบใหญ่ คุณและวีรบุรุษที่มีพลังชีวิตน้อยที่สุดในแถวหลังของทีมจะได้รับ [โล่ผี] (โล่ผี: จำนวนโล่เท่ากับ 15% ของพลังชีวิตสูงสุดของ Giratio ไม่สามารถซ้อนทับได้ เป้าหมายที่ถูกโจมตีโดยโล่ผีจะอ่อนแอลง: การโจมตีคู่ลดลง 15% เป็นเวลา 2 เทิร์น); เมื่อเปลี่ยนเป็นรูปแบบต้นกำเนิด จะสามารถฟื้นฟู HP ที่สูญเสียไป 30% (ไม่ถูกผลกระทบจากวิธีการรักษาที่ถูกห้าม) และจะไม่เกิดใหม่เมื่อโจมตีในรูปแบบต้นกำเนิด',
		describe_in = 'Saat Giratio memasuki medan, dia akan menerima jumlah jiwa pahlawan di perkemahan miliknya selain dirinya sendiri (batas maksimum jiwa: 5 poin, tidak bisa dibersihkan atau diabaikan), dan setiap jiwa dapat mengurangi jumlah jiwanya sendiri sebesar #(4 + s killLevel * 0.04 - 0.04)%#. Kerusakan akhir yang diterima akan mengurangi satu jiwa setiap kali terkena serangan. Ketika jiwa berkurang, 80 poin Kemarahan akan dipulihkan. Pada awal setiap putaran besar, Anda dan pahlawan dengan persentase HP terendah di barisan belakang tim Anda akan menerima [Perisai Hantu] (Perisai Hantu: jumlah perisai sama dengan 15% HP maksimal Giratio, tidak dapat ditumpuk, target yang diserang oleh perisai hantu akan melemah: serangan ganda dikurangi 15% selama 2 giliran); saat berubah ke bentuk asli, 30% HP yang hilang dapat dipulihkan (tidak terpengaruh oleh metode penyembuhan yang dilarang) dan Giratio tidak akan bereinkarnasi saat menyerang dalam bentuk asli.',
		describe_ph = 'Kapag pumasok si Giratio sa lugar ng laban, tatanggap siya ng bilang ng mga kaluluwa ng mga bayani sa kanyang kampo bukod sa kanyang sarili (pinakamataas na limitasyon ng kaluluwa: 5 puntos, hindi maaaring mawala o balewalain), at bawat kaluluwa ay maaaring bawasan ang bilang ng kanyang sariling kaluluwa ng #(4 + s killLevel * 0.04 - 0.04)%#. Ang huling pinsalang matatanggap ay magbabawas ng isang kaluluwa tuwing tatamaan. Kapag nabawasan ang mga kaluluwa, 80 puntos ng Galit ang mababawi. Sa simula ng bawat malaking round, ikaw at ang bayani na may pinakamababang porsyento ng HP sa hulihan ng iyong koponan ay makakatanggap ng [Ghost Shield] (Ghost Shield: dami ng kalasag na katumbas ng 15% ng max HP ni Giratio, hindi maaaring pag-ugpulin, ang mga target na inaatake ng ghost shield ay magiging mahina: doble ang atake na nababawasan ng 15% sa loob ng 2 turno); kapag nag-transform sa orihinal na anyo, 30% ng nawalang HP ay maaaring mabawi (hindi naapektuhan ng mga ipinagbabawal na paraan ng pagpapagaling) at hindi muling mabubuhay si Giratio kapag umaatake sa orihinal na anyo.',
		describe_ma = 'Apabila Giratio memasuki medan tempur, dia akan menerima bilangan jiwa wira di kemahnya selain dirinya sendiri (had atas bilangan jiwa: 5 mata, tidak boleh hilang atau diabaikan), dan setiap jiwa boleh mengurangkan bilangan jiwanya sendiri sebanyak #(4 + s killLevel * 0.04 - 0.04)%#. Kerosakan terakhir yang diterima akan mengurangkan satu jiwa setiap kali terkena serangan. Apabila jiwa berkurang, 80 mata kemarahan akan dipulihkan. Pada permulaan setiap pusingan utama, anda dan wira dengan peratusan darah terendah di barisan belakang dalam pasukan anda akan menerima [Perisai Hantu] ([Perisai Hantu]: kuantiti perisai sama dengan 15% darah maksimum Giratio, tidak boleh bertindan, sasaran yang diserang perisai hantu akan menjadi lemah: serangan berganda dikurangkan 15% selama 2 pusingan); apabila bertukar ke bentuk asal, 30% HP yang hilang boleh dipulihkan (tidak terjejas oleh kaedah rawatan yang dilarang) dan Giratio tidak akan bangkit semula ketika menyerang dalam bentuk asal.',
		describe = 'When Giratio enters the battlefield, he will receive the number of souls of the heroes in his camp excluding himself (maximum limit of souls: 5 points, cannot be dispelled or ignored), and each soul can reduce the number of his own souls by #(4 + s killLevel * 0.04 - 0.04)%#. The final damage received will reduce one soul each time he is hit. When souls are reduced, 80 points of Fury will be restored. At the start of each major round, you and the hero with the lowest health percentage in the back row of your team will receive [Ghost Shield] (Ghost Shield: shield amount equal to 15% of Giratio\'s max HP, cannot stack, targets attacked by ghost shield are weakened: dual attacks reduced by 15% for 2 turns); when transforming to original form, 30% of lost HP can be recovered (not affected by prohibited healing methods) and Giratio will not resurrect when attacking in original form.',
		starEffect = __data_t__starEffect[210526],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Quỷ khiên nâng cấp: tăng 5% lượng khiên, mỗi lượt lớn kết thúc bản thân nhận 1 điểm Quỷ ảnh',
		starEffectDesc = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
		starEffectDesc_en = 'Demon Shield Upgrade Effect: increases shield amount by 5%, at the end of each big turn, gain 1 Demon Shadow point',
		starEffectDesc_th = 'เอฟเฟกต์การอัปเกรดโล่ปีศาจ: เพิ่มปริมาณโล่ 5% เมื่อสิ้นสุดแต่ละเทิร์นใหญ่ รับ 1 คะแนนเงาปีศาจ',
		starEffectDesc_in = 'Efek Peningkatan Perisai Setan: meningkatkan jumlah perisai sebesar 5%, pada akhir setiap giliran besar, menerima 1 poin Bayangan Setan',
		starEffectDesc_ph = 'Epekto ng Pag-upgrade ng Demon Shield: nagdaragdag ng 5% sa dami ng shield, sa pagtatapos ng bawat malaking turn ay tumatanggap ng 1 Demon Shadow point',
		starEffectDesc_ma = 'Kesan Naik Taraf Perisai Iblis: meningkatkan jumlah perisai sebanyak 5%, pada akhir setiap giliran besar, menerima 1 mata Bayangan Iblis',
		changeUnitTrigger = true,
