	[210527] = {
		id = 210527,
		skillName_vn = 'Bị động',
		skillName_en = 'Passive',
		skillName_th = 'ถูกกระทำ',
		skillName_in = 'Pasif',
		skillName_ph = 'Passive',
		skillName_ma = 'Pasif',
		skillName = 'Passive',
		describe_vn = 'Khi Giratio bước vào hiện trường, anh ta sẽ nhận được số lượng hồn ma của các anh hùng trong trại của mình ngoài chính mình (giới hạn trên của số lượng ma: 5 điểm, không thể xua tan hoặc bỏ qua), và mỗi hồn ma có thể giảm số lượng hồn ma của mình #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B# Sát thương cuối cùng nhận được sẽ giảm 1 hồn ma mỗi khi trúng đòn. Khi bóng ma giảm đi, 80 điểm thịnh nộ sẽ được phục hồi\n#F20# \n#F40#Khi bắt đầu mỗi vòng lớn, bạn và anh hùng có phần trăm máu thấp nhất ở hàng sau trong đội của bạn sẽ nhận được [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: lượng khiên bằng 15% máu tối đa của Giratina. , không thể chồng lên, mục tiêu tấn công khiên ma sẽ yếu: đòn tấn công kép giảm 15% trong 2 lượt); khi chuyển sang dạng gốc, 30% lượng HP đã mất có thể được phục hồi (không bị ảnh hưởng bởi phương pháp điều trị bị cấm) và bản thân sẽ không tái sinh khi tấn công ở dạng gốc.',
		describe_en = 'When Giratio enters the battlefield, he will gain a number of ghost spirits of the heroes in his camp besides himself (maximum number of ghosts: 5 points, cannot be dispelled or ignored), and each ghost can reduce his own number of ghosts by #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. The final damage received will reduce one ghost each time he is hit. When a ghost is lost, 80 fury points will be restored \n#F20# \n#F40#. At the start of each large round, you and the hero with the lowest percentage of HP in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: a shield equal to 15% of Giratina\'s max HP, cannot stack, and targets attacking the ghost shield will be weakened: dual attacks are reduced by 15% for 2 turns); when switching to original form, 30% of lost HP can be recovered (not affected by forbidden healing methods) and Giratio himself will not revive when attacking in original form.',
		describe_th = 'เมื่อ Giratio เข้าสู่สนามรบ เขาจะได้รับจำนวนวิญญาณของฮีโร่ในค่ายของเขานอกจากตัวเอง (ขีดจำกัดสูงสุดของจำนวนวิญญาณ: 5 จุด ไม่สามารถขจัดหรือมองข้ามได้) และวิญญาณแต่ละดวงสามารถลดจำนวนวิญญาณของตนเองได้ #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. ความเสียหายสุดท้ายที่ได้รับจะลดวิญญาณลง 1 ดวงทุกครั้งที่โดนโจมตี เมื่อวิญญาณลดลง จะได้รับพลังโกรธ 80 คะแนน \n#F20# \n#F40#. เมื่อเริ่มแต่ละรอบใหญ่ คุณและฮีโร่ที่มีเปอร์เซ็นต์ HP ต่ำที่สุดแถวหลังในทีมของคุณจะได้รับ [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: เกราะเท่ากับ 15% ของ HP สูงสุดของ Giratina ไม่สามารถทับซ้อนกันได้ เป้าหมายที่โจมตีเกราะวิญญาณจะถูกอ่อนแอ: การโจมตีคู่ลดลง 15% เป็นเวลา 2 เทิร์น); เมื่อเปลี่ยนเป็นรูปแบบเดิม จะฟื้นฟู HP ที่เสียไป 30% (ไม่ถูกผลกระทบจากวิธีการรักษาที่ถูกห้าม) และตัว Giratio จะไม่ฟื้นคืนชีพเมื่อโจมตีในรูปแบบเดิม',
		describe_in = 'Ketika Giratio masuk ke medan perang, dia akan menerima sejumlah roh hantu para pahlawan di kampnya selain dirinya sendiri (batas atas jumlah hantu: 5 poin, tidak bisa diusir atau diabaikan), dan setiap hantu dapat mengurangi jumlah hantu miliknya sendiri sebesar #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Kerusakan akhir yang diterima akan mengurangi satu hantu setiap kali terkena serangan. Ketika hantu berkurang, 80 poin kemarahan akan dipulihkan \n#F20# \n#F40#. Pada awal setiap ronde besar, kamu dan pahlawan dengan persentase HP terendah di barisan belakang timmu akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: perisai sebesar 15% dari HP maksimal Giratina, tidak dapat ditumpuk, target yang menyerang perisai hantu akan melemah: serangan ganda dikurangi 15% selama 2 giliran); saat berubah ke wujud asli, 30% dari HP yang hilang dapat dipulihkan (tidak terpengaruh oleh metode penyembuhan terlarang) dan Giratio sendiri tidak akan bereinkarnasi saat menyerang dalam bentuk asli.',
		describe_ph = 'Kapag pumasok si Giratio sa larangan ng laban, matatanggap niya ang bilang ng mga espiritu ng mga bayani sa kanyang kampo bukod sa kanyang sarili (hangganan ng bilang ng mga espiritu: 5 puntos, hindi maaaring alisin o balewalain), at bawat espiritu ay maaaring magpababa ng kanyang sariling bilang ng mga espiritu ng #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Ang huling natanggap na pinsala ay magbabawas ng isang espiritu tuwing tinatamaan. Kapag nabawasan ang espiritu, 80 puntos ng galit ang mare-recover \n#F20# \n#F40#. Sa pagsisimula ng bawat malaking round, ikaw at ang bayani na may pinakamababang porsyento ng HP sa likurang hanay ng iyong koponan ay makakatanggap ng [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: isang kalasag na katumbas ng 15% ng max HP ni Giratina, hindi maaaring magsabay, ang target na umaatake sa kalasag ng espiritu ay mahihinang: doble ang pag-atake ay nababawasan ng 15% sa loob ng 2 turn); kapag lumipat sa orihinal na anyo, 30% ng nawalang HP ay maaaring maibalik (hindi naapektuhan ng ipinagbabawal na mga pamamaraan ng pagpapagaling) at si Giratio mismo ay hindi muling mabubuhay kapag umaatake sa orihinal na anyo.',
		describe_ma = 'Apabila Giratio memasuki medan tempur, dia akan menerima bilangan roh hantu wira dalam kemnya selain dirinya sendiri (had maksimum bilangan hantu: 5 mata, tidak boleh disingkirkan atau diabaikan), dan setiap hantu boleh mengurangkan bilangan hantu dirinya sendiri sebanyak #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. Kerosakan terakhir diterima akan mengurangkan satu hantu setiap kali terkena serangan. Apabila bilangan hantu berkurangan, 80 mata kemarahan akan dipulihkan \n#F20# \n#F40#. Pada permulaan setiap pusingan besar, kamu dan wira dengan peratusan kesihatan terendah di barisan belakang dalam pasukan kamu akan menerima [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: perisai bersamaan 15% kesihatan maksima Giratina, tidak boleh bertindan, sasaran yang menyerang perisai hantu akan menjadi lemah: serangan berganda dikurangkan 15% selama 2 pusingan); apabila bertukar ke bentuk asal, 30% daripada HP yang hilang dapat dipulihkan (tidak terjejas oleh kaedah rawatan yang dilarang) dan Giratio sendiri tidak akan bereinkarnasi apabila menyerang dalam bentuk asal.',
		describe = 'When Giratio enters the battlefield, he will gain a number of ghost spirits of the heroes in his camp besides himself (maximum number of ghosts: 5 points, cannot be dispelled or ignored), and each ghost can reduce his own number of ghosts by #C0x5c9970#$(4+s killLevel*0.04-0.04)$%#C0x5B545B#. The final damage received will reduce one ghost each time he is hit. When a ghost is lost, 80 fury points will be restored \n#F20# \n#F40#. At the start of each large round, you and the hero with the lowest percentage of HP in the back row of your team will receive [#L10#Ghost Shield#L0#] ([#L10#Ghost Shield#L0#]: a shield equal to 15% of Giratina\'s max HP, cannot stack, and targets attacking the ghost shield will be weakened: dual attacks are reduced by 15% for 2 turns); when switching to original form, 30% of lost HP can be recovered (not affected by forbidden healing methods) and Giratio himself will not revive when attacking in original form.',
		starEffect = __data_t__starEffect[210527],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng Quỷ khiên nâng cấp: tăng 5% lượng khiên, mỗi lượt lớn kết thúc bản thân nhận 1 điểm Quỷ ảnh',
