	[220041] = {
		id = 220041,
		skillName_vn = 'Đấm siêu năng',
		skillName_en = 'Super punch',
		skillName_th = 'หมัดพลังพิเศษ',
		skillName_in = 'Pukulan super',
		skillName_ph = 'Super suntok',
		skillName_ma = 'Deburan super',
		skillName = 'Super punch',
		describe_vn = 'Hoopa điều khiển tay ma tấn công nhanh mục tiêu đơn của kẻ địch, gây #C0x3D8A99#100% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, tăng 15% Phép Công và 20% bỏ qua Phép Phòng của bản thân trong 2 lượt',
		describe_en = 'Hoopa controls phantom hands to quickly attack a single enemy target, dealing #C0x3D8A99#100% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, increasing own Magic Attack by 15% and ignoring 20% Magic Defense for 2 turns.',
		describe_th = 'Hoopa ควบคุมมือมายาโจมตีเป้าหมายศัตรูเดี่ยวอย่างรวดเร็ว สร้างความเสียหาย #C0x3D8A99#100% พลังเวท#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ความเสียหายเวทย์มนตร์ #C0x5B545B# และเพิ่มพลังเวทของตนเอง 15% พร้อมเพิกเฉยต่อการป้องกันเวท 20% เป็นเวลา 2 เทิร์น',
		describe_in = 'Hoopa mengendalikan tangan bayangan untuk menyerang cepat satu target musuh, memberikan #C0x3D8A99#100% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, meningkatkan Serangan Sihir sendiri sebesar 15% dan mengabaikan 20% Pertahanan Sihir selama 2 giliran.',
		describe_ph = 'Kinokontrol ni Hoopa ang mga phantom na kamay para mabilis na atakihin ang isang target na kalaban, na nagdudulot ng #C0x3D8A99#100% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, nagpapataas ng sariling Magic Attack ng 15% at nagpapawalang-bisa ng 20% Magic Defense sa loob ng 2 na turn.',
		describe_ma = 'Hoopa mengawal tangan ghaib untuk menyerang pantas sasaran tunggal musuh, menyebabkan #C0x3D8A99#100% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, meningkatkan Serangan Sihir diri sendiri sebanyak 15% dan mengabaikan 20% Pertahanan Sihir selama 2 pusingan.',
		describe = 'Hoopa controls phantom hands to quickly attack a single enemy target, dealing #C0x3D8A99#100% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Magic Damage #C0x5B545B#, increasing own Magic Attack by 15% and ignoring 20% Magic Defense for 2 turns.',
		zawakeEffect = __data_t__zawakeEffect[220041],
		-- {79001}
		zawakeEffectDesc = 'Hoopa quickly controls the demon hand to punch the single target enemy, dealing #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ magic damage#C0xF13B54#, increases Magic Power by 15% and ignores 25% magic defense for 3 turns on itself',
		zawakeEffectDesc_en = 'Hoopa quickly controls the demon hand to punch the single target enemy, dealing #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ magic damage#C0xF13B54#, increases Magic Power by 15% and ignores 25% magic defense for 3 turns on itself',
		zawakeEffectDesc_th = 'Hoopa ควบคุมมือปีศาจอย่างรวดเร็วเพื่อชกใส่เป้าหมายเดี่ยวของศัตรู สร้าง #C0x3D8A99#100% พลังเวท#C0x5B545B#+$(skillLevel*4*24)$ ความเสียหายเวท#C0xF13B54# และเพิ่มพลังเวท 15% พร้อมลดการป้องกันเวทของตัวเอง 25% เป็นเวลา 3 เทิร์น',
		zawakeEffectDesc_in = 'Hoopa mengendalikan tangan iblis dengan cepat untuk memukul target tunggal musuh, menyebabkan #C0x3D8A99#100% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*24)$ kerusakan sihir#C0xF13B54#, meningkatkan Kekuatan Sihir sebesar 15% dan mengabaikan 25% pertahanan sihir pada dirinya sendiri selama 3 giliran',
		zawakeEffectDesc_ph = 'Mabilis na kinokontrol ni Hoopa ang demon hand upang suntukin ang isang target lang na kalaban, nagdudulot ng #C0x3D8A99#100% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ magic damage#C0xF13B54#, nagpapataas ng Magic Power ng 15% at nagpapabaya ng 25% magic defense ng sarili sa loob ng 3 turns',
		zawakeEffectDesc_ma = 'Hoopa mengawal tangan syaitan dengan pantas untuk menumbuk musuh sasaran tunggal, menyebabkan #C0x3D8A99#100% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*24)$ kerosakan sihir#C0xF13B54#, meningkatkan Kuasa Sihir sebanyak 15% dan mengabaikan 25% pertahanan sihir pada dirinya sendiri selama 3 pusingan',
		zawakeEffectDesc_vn = 'Hoopa điều khiển tay ma quỷ nhanh chóng đấm vào mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#100% Công Phép#C0x5B545B#+$(skillLevel*4*24)$ sát thương phép#C0xF13B54#，tăng 15% Công Phép và 25% bỏ qua phòng phép của bản thân trong 3 lượt',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Increases own Magic Attack by 15% and Magic Defense Penetration by 20% for 2 turns#F20# #F40##C0x5c9970#→Increases own Magic Attack by 15% and Magic Defense Penetration by 25% for 3 turns',
		zawakeSimpleDesc_en = 'Increases own Magic Attack by 15% and Magic Defense Penetration by 20% for 2 turns#F20# #F40##C0x5c9970#→Increases own Magic Attack by 15% and Magic Defense Penetration by 25% for 3 turns',
		zawakeSimpleDesc_th = 'เพิ่มพลังโจมตีเวท 15% และเจาะเกราะเวท 20% ให้ตัวเองเป็นเวลา 2 เทิร์น#F20# #F40##C0x5c9970#→เพิ่มพลังโจมตีเวท 15% และเจาะเกราะเวท 25% ให้ตัวเองเป็นเวลา 3 เทิร์น',
		zawakeSimpleDesc_in = 'Meningkatkan Magic Attack sebesar 15% dan Penetrasi Pertahanan Sihir sebesar 20% selama 2 giliran#F20# #F40##C0x5c9970#→Meningkatkan Magic Attack sebesar 15% dan Penetrasi Pertahanan Sihir sebesar 25% selama 3 giliran',
		zawakeSimpleDesc_ph = 'Nagpapataas ng Magic Attack ng 15% at Magic Defense Penetration ng 20% sa loob ng 2 turn#F20# #F40##C0x5c9970#→Nagpapataas ng Magic Attack ng 15% at Magic Defense Penetration ng 25% sa loob ng 3 turn',
		zawakeSimpleDesc_ma = 'Meningkatkan Serangan Sihir sebanyak 15% dan Penembusan Pertahanan Sihir sebanyak 20% selama 2 pusingan#F20# #F40##C0x5c9970#→Meningkatkan Serangan Sihir sebanyak 15% dan Penembusan Pertahanan Sihir sebanyak 25% selama 3 pusingan',
		zawakeSimpleDesc_vn = 'Tăng 15% Phép Công và 20% bỏ qua Phép Phòng của bản thân trong 2 lượt#F20# #F40##C0x5c9970#→Tăng 15% Phép Công và 25% bỏ qua Phép Phòng của bản thân trong 3 lượt',
