	[220042] = {
		id = 220042,
		skillName_vn = 'Đạn sóng',
		skillName_en = 'Wave Bullet',
		skillName_th = 'กระสุลคลื่น',
		skillName_in = 'Peluru Gelombang',
		skillName_ph = 'Balaheng Alon',
		skillName_ma = 'Peluru Gelombang',
		skillName = 'Wave Bullet',
		describe_vn = 'Hoopa sử dụng vòng sáng để truyền tống và tung sóng ác quỷ vào mục tiêu đơn của kẻ địch, gây #C0x3D8A99#180% Phép Công#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, khiến mục tiêu hàng trước dễ bị tổn thương 25%, giảm hồi máu 20%, kéo dài 3 lượt',
		describe_en = 'Hoopa uses a ring of light to teleport and unleash a demonic wave at a single enemy target, dealing 180% Magical Attack + $(skillLevel*4*24)$ Magical Damage, making the frontline target more vulnerable by 25%, reducing healing by 20%, lasting 3 turns.',
		describe_th = 'ฮูปปะใช้แหวนแห่งแสงในการเคลื่อนที่และปล่อยคลื่นปีศาจใส่เป้าหมายเดี่ยวของศัตรู สร้างความเสียหายเวทมนตร์ 180% + $(skillLevel*4*24)$ ทำให้เป้าหมายแถวหน้าเปราะบางขึ้น 25%, ลดการฟื้นฟูเลือด 20%, นาน 3 เทิร์น',
		describe_in = 'Hoopa menggunakan cincin cahaya untuk teleportasi dan melepaskan gelombang iblis ke satu sasaran musuh, memberikan 180% Serangan Sihir + $(skillLevel*4*24)$ Kerusakan Sihir, membuat target barisan depan menjadi 25% lebih rentan, mengurangi penyembuhan sebesar 20%, bertahan selama 3 giliran.',
		describe_ph = 'Ginagamit ni Hoopa ang singsing ng liwanag upang mag-teleport at magpalabas ng demonyong alon sa isang target na kaaway, na nagdudulot ng 180% Magical Attack + $(skillLevel*4*24)$ na Pinsalang Salamangka, nagpapahina ng 25% sa front row target, nagpapababa ng paggaling ng 20%, tumatagal ng 3 na turn.',
		describe_ma = 'Hoopa menggunakan cincin cahaya untuk teleport dan melepaskan gelombang iblis ke sasaran musuh tunggal, menyebabkan 180% Serangan Sihir + $(skillLevel*4*24)$ Kerosakan Sihir, menyebabkan sasaran barisan hadapan menjadi 25% lebih mudah terjejas, mengurangkan penyembuhan sebanyak 20%, berlangsung selama 3 giliran.',
		describe = 'Hoopa uses a ring of light to teleport and unleash a demonic wave at a single enemy target, dealing 180% Magical Attack + $(skillLevel*4*24)$ Magical Damage, making the frontline target more vulnerable by 25%, reducing healing by 20%, lasting 3 turns.',
		zawakeEffect = __data_t__zawakeEffect[220042],
		-- {79002}
		zawakeEffectDesc = 'Hoopa borrows the light ring to teleport and perform a wave attack on a single enemy target, dealing #C0x3D8A99#180% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ magic damage#C0xF13B54#, causing front row targets to be 30% more vulnerable to damage, reducing healing by 20%, lasting 4 turns',
		zawakeEffectDesc_en = 'Hoopa borrows the light ring to teleport and perform a wave attack on a single enemy target, dealing #C0x3D8A99#180% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ magic damage#C0xF13B54#, causing front row targets to be 30% more vulnerable to damage, reducing healing by 20%, lasting 4 turns',
		zawakeEffectDesc_th = 'ฮูปป้า ยืมวงแสงเพื่อเคลื่อนที่และทำการโจมตีคลื่นต่อเป้าหมายศัตรูเดี่ยว สร้างความเสียหายเวท #C0x3D8A99#180% พลังเวท#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# ทำให้เป้าหมายแถวหน้าได้รับการโจมตีเพิ่มขึ้น 30% ลดการฟื้นฟูเลือด 20% อยู่ได้นาน 4 เทิร์น',
		zawakeEffectDesc_in = 'Hoopa meminjam cincin cahaya untuk berpindah tempat dan melakukan serangan gelombang pada satu target musuh, memberikan #C0x3D8A99#180% Power Sihir#C0x5B545B#+$(skillLevel*4*24)$ kerusakan sihir#C0xF13B54#, menyebabkan target barisan depan lebih mudah terluka 30%, mengurangi penyembuhan 20%, berlangsung selama 4 giliran',
		zawakeEffectDesc_ph = 'Hiniram ni Hoopa ang singsing ng ilaw para maglakbay at maglunsad ng wave attack sa isang kalaban, nagdudulot ng #C0x3D8A99#180% Magic Power#C0x5B545B#+$(skillLevel*4*24)$ magic damage#C0xF13B54#, nagiging 30% mas madaling saktan ang mga target sa front row, bumababa ang healing ng 20%, tumatagal ng 4 na turn',
		zawakeEffectDesc_ma = 'Hoopa meminjam cincin cahaya untuk berpindah dan melakukan serangan gelombang ke sasaran musuh tunggal, menyebabkan #C0x3D8A99#180% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*24)$ kerosakan sihir#C0xF13B54#, menyebabkan sasaran barisan hadapan mudah cedera 30%, mengurangkan penyembuhan 20%, berlangsung selama 4 giliran',
		zawakeEffectDesc_vn = 'Hoopa mượn vòng sáng để dịch chuyển thực hiện đòn sóng ác lên mục tiêu đơn lẻ của kẻ địch, gây ra #C0x3D8A99#180% Công Phép#C0x5B545B#+$(skillLevel*4*24)$ sát thương phép#C0xF13B54#，khiến mục tiêu hàng trước dễ bị thương 30%, giảm hồi máu 20%, kéo dài 4 lượt',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Makes front row targets 25% more vulnerable and reduces healing received by 20% for 3 turns#F20# #F40##C0x5c9970#→Makes front row targets 30% more vulnerable and reduces healing by 20% for 4 turns',
		zawakeSimpleDesc_en = 'Makes front row targets 25% more vulnerable and reduces healing received by 20% for 3 turns#F20# #F40##C0x5c9970#→Makes front row targets 30% more vulnerable and reduces healing by 20% for 4 turns',
		zawakeSimpleDesc_th = 'ทำให้เป้าหมายแถวหน้าอ่อนแอลง 25% และลดการฟื้นฟู 20% เป็นเวลา 3 เทิร์น#F20# #F40##C0x5c9970#→ทำให้เป้าหมายแถวหน้าอ่อนแอลง 30% และลดการฟื้นฟู 20% เป็นเวลา 4 เทิร์น',
		zawakeSimpleDesc_in = 'Membuat target baris depan menerima 25% lebih banyak damage dan mengurangi pemulihan sebesar 20% selama 3 giliran#F20# #F40##C0x5c9970#→Membuat target baris depan menerima 30% lebih banyak damage dan mengurangi pemulihan sebesar 20% selama 4 giliran',
		zawakeSimpleDesc_ph = 'Ginagawang 25% mas mahina ang front row target at binabawasan ang healing ng 20% sa loob ng 3 turn#F20# #F40##C0x5c9970#→Ginagawang 30% mas mahina ang front row target at binabawasan ang healing ng 20% sa loob ng 4 turn',
		zawakeSimpleDesc_ma = 'Menyebabkan sasaran barisan depan menjadi 25% lebih terdedah dan mengurangkan pemulihan sebanyak 20% selama 3 pusingan#F20# #F40##C0x5c9970#→Menyebabkan sasaran barisan depan menjadi 30% lebih terdedah dan mengurangkan pemulihan sebanyak 20% selama 4 pusingan',
		zawakeSimpleDesc_vn = 'Khiến mục tiêu hàng trước dễ bị tổn thương 25%, giảm hồi máu 20%, kéo dài 3 lượt#F20# #F40##C0x5c9970#→Khiến mục tiêu hàng trước dễ bị tổn thương 30%, giảm hồi máu 20%, kéo dài 4 lượt',
