	[220046] = {
		id = 220046,
		skillName_vn = 'Giải phóng vòng ánh sáng',
		skillName_en = 'Release the ring of light',
		skillName_th = 'ปลดปล่อยวงแหวนแห่งแสง',
		skillName_in = 'Melepaskan cincin cahaya',
		skillName_ph = 'Palayain ang singsing ng liwanag',
		skillName_ma = 'Melepaskan cincin cahaya',
		skillName = 'Release the ring of light',
		describe_vn = 'Trước mỗi vòng lớn, chỉ định ngẫu nhiên 6 [Bánh xe Ánh sáng] trên cơ thể của bạn cho hàng đầu của kẻ địch và lấy lại tất cả [Bánh xe Ánh sáng] trước lượt của mình (hồi phục ngay sau khi mục tiêu chết)\n#F20# \n#F40##L10#Bánh xe Ánh sáng: #L0#Hiệu ứng đặc biệt, 6 bánh xe ánh sáng tương ứng với thuộc tính sáu chiều. Khi được áp dụng, các thuộc tính cơ bản tương ứng của mục tiêu sẽ bị giảm vĩnh viễn (từ 8% thuộc tính sáu chiều cơ bản của Hupa, có thể bị xua tan và giới hạn trên của một mục tiêu là 3 lớp). Khi bánh xe ánh sáng quay trở lại, nó sẽ vĩnh viễn chuyển thành thuộc tính của chính nó\n#F20# \n#F40# Giảm #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# sát thương cuối cùng mà bạn nhận được và chuyển 150% sát thương này sang một mục tiêu ngẫu nhiên ở hàng đầu của kẻ địch với 50% đòn Sát Thương Vật Lý của chính bạn là sát thương chuẩn',
		describe_en = 'Before each major round, randomly assign 6 [Wheels of Light] on your body to the front row of the enemy and recover all [Wheels of Light] before your turn (immediately restored after the target dies).\n#F20# \n#F40##L10#Wheels of Light: #L0#Special effect, 6 wheels of light correspond to the six-dimensional attributes. When applied, the target\'s corresponding basic attributes will be permanently reduced (from 8% of Hupa\'s basic six-dimensional attributes, can be dissipated and the upper limit per target is 3 layers). When the wheels of light return, they will permanently convert into their own attribute.\n#F20# \n#F40# Reduce #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# of the final damage you receive and transfer 150% of this damage to a random target in the enemy front row, dealing 50% of your Physical Damage as true damage.',
		describe_th = 'ก่อนทุกรอบใหญ่ สุ่มกำหนด 6 [ล้อแสงสว่าง] บนร่างกายของคุณไปยังแถวหน้าของศัตรู และฟื้นฟู [ล้อแสงสว่าง] ทั้งหมดก่อนเทิร์นของคุณ (ฟื้นฟูทันทีหลังเป้าหมายตาย) \n#F20# \n#F40##L10#ล้อแสงสว่าง: #L0#เอฟเฟกต์พิเศษ, 6 ล้อแสงสว่างสอดคล้องกับคุณลักษณะมิติเฉียง ซึ่งเมื่อนำไปใช้ คุณลักษณะพื้นฐานที่เกี่ยวข้องของเป้าหมายจะถูกลดลงอย่างถาวร (จาก 8% ของคุณลักษณะมิติเบื้องต้นของฮูปา สามารถถูกสลายและมีขีดจำกัดสูงสุดต่อเป้าหมาย 3 ชั้น) เมื่อล้อแสงสว่างกลับมา มันจะเปลี่ยนเป็นคุณลักษณะของมันเองอย่างถาวร \n#F20# \n#F40# ลด #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# ของดาเมจสุดท้ายที่คุณได้รับ และถ่ายโอน 150% ของดาเมจนี้ไปยังเป้าหมายสุ่มในแถวหน้าของศัตรู โดยมี 50% ของดาเมจกายภาพของคุณเป็นดาเมจจริง',
		describe_in = 'Sebelum setiap babak besar, secara acak tetapkan 6 [Roda Cahaya] pada tubuh Anda ke barisan depan musuh dan pulihkan semua [Roda Cahaya] sebelum giliran Anda (pulih segera setelah target mati). \n#F20# \n#F40##L10#Roda Cahaya: #L0#Efek khusus, 6 roda cahaya sesuai dengan atribut enam dimensi. Ketika diterapkan, atribut dasar yang sesuai dari target akan berkurang secara permanen (dari 8% atribut dasar enam dimensi Hupa, dapat dihilangkan dan batas atas untuk satu target adalah 3 lapisan). Ketika roda cahaya kembali, mereka akan berubah secara permanen menjadi atribut mereka sendiri. \n#F20# \n#F40# Kurangi #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# dari total kerusakan yang Anda terima dan transfer 150% dari kerusakan ini ke target acak di barisan depan musuh, dengan 50% dari Damage Fisik Anda sebagai damage nyata.',
		describe_ph = 'Bago ang bawat malaking round, random na magtalaga ng 6 [Mga Gulong ng Liwanag] sa iyong katawan sa front row ng kalaban at kunin muli lahat ng [Mga Gulong ng Liwanag] bago ang iyong turno (biglang bumalik pagkatapos mamatay ang target). \n#F20# \n#F40##L10#Mga Gulong ng Liwanag: #L0#Espesyal na epekto, 6 na gulong ng liwanag ay katumbas ng anim na dimensional na katangian. Kapag inilapat, ang kaukulang pangunahing katangian ng target ay permanenteng mababawasan (mula sa 8% ng pangunahing anim na dimensional na katangian ni Hupa, maaaring mapawi at ang maximum na limitasyon ng isang target ay 3 layers). Kapag bumalik ang mga gulong ng liwanag, permanenteng nagbabago ito sa sariling katangian nito. \n#F20# \n#F40# Bawasan ang #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# ng huling damage na natatanggap mo at i-transfer ang 150% ng damage na ito sa isang random na target sa front row ng kalaban, na may 50% ng iyong Physical Damage bilang tunay na damage.',
		describe_ma = 'Sebelum setiap pusingan besar, secara rawak tugaskan 6 [Roda Cahaya] pada badan anda ke barisan hadapan musuh dan pulihkan semua [Roda Cahaya] sebelum giliran anda (pulih segera selepas sasaran mati). \n#F20# \n#F40##L10#Roda Cahaya: #L0#Kesan khas, 6 roda cahaya masing-masing mewakili atribut enam dimensi. Apabila digunakan, atribut asas yang sepadan pada sasaran akan dikurangkan secara kekal (daripada 8% atribut asas enam dimensi Hupa, boleh dihapuskan dan had atas bagi satu sasaran ialah 3 lapisan). Apabila roda cahaya kembali, ia akan berubah secara kekal menjadi atributnya sendiri. \n#F20# \n#F40# Kurangkan #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# daripada kerosakan terakhir yang anda terima dan alihkan 150% kerosakan ini ke sasaran rawak di barisan hadapan musuh dengan 50% daripada Kerosakan Fizikal anda sebagai kerosakan sebenar.',
		describe = 'Before each major round, randomly assign 6 [Wheels of Light] on your body to the front row of the enemy and recover all [Wheels of Light] before your turn (immediately restored after the target dies).\n#F20# \n#F40##L10#Wheels of Light: #L0#Special effect, 6 wheels of light correspond to the six-dimensional attributes. When applied, the target\'s corresponding basic attributes will be permanently reduced (from 8% of Hupa\'s basic six-dimensional attributes, can be dissipated and the upper limit per target is 3 layers). When the wheels of light return, they will permanently convert into their own attribute.\n#F20# \n#F40# Reduce #C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# of the final damage you receive and transfer 150% of this damage to a random target in the enemy front row, dealing 50% of your Physical Damage as true damage.',
		starEffect = __data_t__starEffect[220046],
		-- {8}
		starEffectDesc_vn = 'Hiệu Ứng Bổ Sung: Khi vào trận, Hu Pa sẽ vươn tay ma quái để vĩnh viễn đánh cắp 10% giảm sát thương từ mỗi mục tiêu hàng đầu của kẻ thù (không thể bị giải tán), và chuyển đổi 10% giảm sát thương đã đánh cắp thành tăng sát thương trước khi tấn công.',
		starEffectDesc = 'Additional Effect: When entering battle, Hu Pa will extend a ghostly hand to permanently steal 10% damage reduction from each of the enemy\'s front-row targets (cannot be dispelled), and convert the stolen 10% damage reduction into increased damage before attacking.',
		starEffectDesc_en = 'Additional Effect: When entering battle, Hu Pa will extend a ghostly hand to permanently steal 10% damage reduction from each of the enemy\'s front-row targets (cannot be dispelled), and convert the stolen 10% damage reduction into increased damage before attacking.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เมื่อเข้าสู่การต่อสู้ Hu Pa จะยืดมือผีไปขโมยการลดความเสียหาย 10% จากแต่ละเป้าหมายแถวหน้าในศัตรูอย่างถาวร (ไม่สามารถลบได้) และแปลงการลดความเสียหาย 10% ที่ขโมยมาเป็นการเพิ่มความเสียหายก่อนโจมตี',
		starEffectDesc_in = 'Efek Tambahan: Saat memasuki pertempuran, Hu Pa akan mengulurkan tangan gaib untuk selamanya mencuri 10% pengurangan kerusakan dari setiap target barisan depan musuh (tidak dapat dibatalkan), dan mengubah 10% pengurangan kerusakan yang dicuri menjadi peningkatan kerusakan sebelum menyerang.',
		starEffectDesc_ph = 'Karagdagang Epekto: Kapag pumasok sa laban, si Hu Pa ay magpapalapit ng mahiwagang kamay upang permanenteng nakawin ang 10% bawas sa pinsala mula sa bawat pangunahing target ng kalaban (hindi maaaring alisin), at i-convert ang nakaw na 10% bawas sa pinsala bilang dagdag na pinsala bago umatake.',
		starEffectDesc_ma = 'Kesan Tambahan: Apabila memasuki pertempuran, Hu Pa akan menghulurkan tangan hantu untuk mencuri secara kekal 10% pengurangan kerosakan daripada setiap sasaran barisan hadapan musuh (tidak boleh dibuang), dan menukar 10% pengurangan kerosakan yang dicuri menjadi peningkatan kerosakan sebelum menyerang.',
		zawakeEffect = __data_t__zawakeEffect[220046],
		-- {79004, 1}
		zawakeEffectDesc = 'Additional effect: Upon entering battle, Hoopa permanently steals 10% damage reduction from each enemy front row target (cannot be dispelled), before attacking converts 5% stolen damage reduction into 10% damage increase; each time the light ring returns to position, steals 20 energy points from the target',
		zawakeEffectDesc_en = 'Additional effect: Upon entering battle, Hoopa permanently steals 10% damage reduction from each enemy front row target (cannot be dispelled), before attacking converts 5% stolen damage reduction into 10% damage increase; each time the light ring returns to position, steals 20 energy points from the target',
		zawakeEffectDesc_th = 'เอฟเฟ็กต์เสริม: เมื่อเข้าสู่การต่อสู้ Hoopa จะขโมยการลดความเสียหาย 10% ตลอดไปจากเป้าหมายแถวหน้าของศัตรูแต่ละตัว (ไม่สามารถลบได้) ก่อนโจมตีจะเปลี่ยนการลดความเสียหายที่ขโมยมา 5% เป็นการเพิ่มความเสียหาย 10%; ทุกครั้งที่แหวนแสงกลับตำแหน่งจะขโมยพลังงาน 20 คะแนนจากเป้าหมาย',
		zawakeEffectDesc_in = 'Efek tambahan: Saat bertarung, Hoopa secara permanen mencuri pengurangan kerusakan 10% dari setiap sasaran baris depan musuh (tidak dapat dihilangkan), sebelum menyerang mengubah 5% pengurangan kerusakan yang dicuri menjadi peningkatan kerusakan 10%; setiap kali cincin cahaya kembali ke posisi, mencuri 20 poin energi dari target',
		zawakeEffectDesc_ph = 'Karagdagang epekto: Kapag pumasok sa laban, permanenteng ninakaw ni Hoopa ang 10% bawas pinsala mula sa bawat target sa harapang hilera ng kalaban (hindi maaaring alisin), bago umatake, gagawin nitong 10% ang 5% ninakaw na bawas pinsala bilang dagdag pinsala; sa bawat pagbabalik ng ilaw na singsing sa posisyon, ninanakaw nito ang 20 puntos ng enerhiya mula sa target',
		zawakeEffectDesc_ma = 'Kesan tambahan: Apabila memasuki pertempuran, Hoopa akan mencuri secara kekal pengurangan kerosakan sebanyak 10% daripada setiap sasaran barisan hadapan musuh (tidak boleh dibuang), sebelum menyerang menukar 5% pengurangan kerosakan yang dicuri menjadi peningkatan kerosakan 10%; setiap kali cincin cahaya kembali ke kedudukan, mencuri 20 mata tenaga daripada sasaran',
		zawakeEffectDesc_vn = 'Hiệu ứng bổ sung: Khi vào trận, Hoopa đưa tay ma quỷ vĩnh viễn đánh cắp 10% giảm sát thương của mỗi mục tiêu hàng trước của kẻ địch (không thể xua tan), trước khi tấn công sẽ chuyển đổi 5% giảm sát thương đã đánh cắp thành 10% tăng sát thương; mỗi khi vòng sáng trở về vị trí, đánh cắp 20 điểm nộ khí của mục tiêu',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Upon entering battle, Hoopa uses its demonic hands to permanently steal 10% damage reduction from each enemy front-row target (cannot be dispelled), and before attacking, converts 10% of the stolen reduction into bonus damage#F20# #F40##C0x5c9970#→Upon entering battle, Hoopa uses its demonic hands to permanently steal 10% damage reduction from each enemy front-row target (cannot be dispelled), and before attacking, converts 5% of the stolen reduction into 10% bonus damage; each time the Halo returns to position, it steals an additional 20 rage from the target',
		zawakeSimpleDesc_en = 'Upon entering battle, Hoopa uses its demonic hands to permanently steal 10% damage reduction from each enemy front-row target (cannot be dispelled), and before attacking, converts 10% of the stolen reduction into bonus damage#F20# #F40##C0x5c9970#→Upon entering battle, Hoopa uses its demonic hands to permanently steal 10% damage reduction from each enemy front-row target (cannot be dispelled), and before attacking, converts 5% of the stolen reduction into 10% bonus damage; each time the Halo returns to position, it steals an additional 20 rage from the target',
		zawakeSimpleDesc_th = 'เมื่อเริ่มการต่อสู้ Hoopa จะใช้มือปีศาจขโมยถาวร 10% การลดความเสียหายจากเป้าหมายศัตรูแถวหน้าแต่ละตัว (ไม่สามารถลบได้) และก่อนโจมตีจะแปลง 10% ของการลดความเสียหายที่ขโมยมาเป็นโบนัสความเสียหาย#F20# #F40##C0x5c9970#→เมื่อเริ่มการต่อสู้ Hoopa จะใช้มือปีศาจขโมยถาวร 10% การลดความเสียหายจากเป้าหมายศัตรูแถวหน้าแต่ละตัว (ไม่สามารถลบได้) และก่อนโจมตีจะแปลง 5% ของที่ขโมยมาเป็นโบนัสความเสียหาย 10%; ทุกครั้งที่ Halo กลับสู่ตำแหน่ง จะขโมยเพิ่มอีก 20 โกรธจากเป้าหมาย',
		zawakeSimpleDesc_in = 'Saat memasuki pertempuran, Hoopa menggunakan tangan iblisnya untuk mencuri secara permanen 10% pengurangan damage dari setiap musuh di baris depan (tidak dapat dihapus), dan sebelum menyerang, mengubah 10% dari pengurangan tersebut menjadi bonus damage#F20# #F40##C0x5c9970#→Saat memasuki pertempuran, Hoopa mencuri secara permanen 10% pengurangan damage dari setiap musuh di baris depan (tidak dapat dihapus), dan sebelum menyerang, mengubah 5% dari pengurangan menjadi',
		zawakeSimpleDesc_ph = 'Pagpasok sa laban, ginagamit ni Hoopa ang kamay ng demonyo para magnakaw ng permanenteng 10% damage reduction mula sa bawat target sa front row ng kalaban (hindi maaaring alisin), bago umatake ay iko-convert ang 10% ng ninakaw na reduction bilang dagdag na damage#F20# #F40##C0x5c9970#→Pagpasok sa laban, ginagamit ni Hoopa ang kamay ng demonyo para magnakaw ng permanenteng 10% damage reduction mula sa bawat target sa front row ng kalaban (hindi maaaring alisin), bago umatake ay iko-convert ang 5% ng ninakaw na reduction bilang 10% dagdag na damage; tuwing babalik ang Halo sa posisyon, magnanakaw ng karagdagang 20 Rage mula sa target',
		zawakeSimpleDesc_ma = 'Apabila memasuki pertempuran, Hoopa menggunakan tangan iblis untuk mencuri secara kekal 10% pengurangan kerosakan daripada setiap musuh di barisan depan (tidak boleh dibuang), dan sebelum menyerang akan menukar 10% daripada pengurangan tersebut kepada bonus kerosakan#F20# #F40##C0x5c9970#→Apabila memasuki pertempuran, Hoopa mencuri secara kekal 10% pengurangan kerosakan daripada setiap musuh di barisan depan (tidak boleh dibuang), sebelum menyerang akan menukar 5% daripada pengurangan itu kepada 10% bonus kerosakan; setiap kali Halo kembali ke posisi, mencuri tambahan 20 mata kemarahan daripada sasaran',
		zawakeSimpleDesc_vn = 'Khi vào trận, Hoopa đưa tay ma quỷ ra cướp vĩnh viễn 10% giảm sát thương của mỗi mục tiêu hàng trước của kẻ địch (không thể xóa), trước khi tấn công sẽ chuyển đổi 10% giảm sát thương đã cướp thành tăng sát thương#F20# #F40##C0x5c9970#→Khi vào trận, Hoopa đưa tay ma quỷ ra cướp vĩnh viễn 10% giảm sát thương của mỗi mục tiêu hàng trước của kẻ địch (không thể xóa), trước khi tấn công sẽ chuyển đổi 5% giảm sát thương đã cướp thành 10% tăng sát thương; mỗi khi Vòng Sáng trở về vị trí, sẽ cướp thêm 20 điểm nộ khí của mục tiêu',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
