	[230500] = {
		id = 230500,
		skillName_vn = 'Đòn tấn công cuối cùng',
		skillName_en = 'Final attack',
		skillName_th = 'การโจมตีครั้งสุดท้าย',
		skillName_in = 'Serangan terakhir',
		skillName_ph = 'Huling atake',
		skillName_ma = 'Serangan terakhir',
		skillName = 'Final attack',
		describe_vn = 'Vua nghỉ phép tung cú đấm tối thượng, đánh bay mục tiêu đơn lẻ của đối phương, gây #C0xE69900#600% Công Vật Lý#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, sát thương này bỏ qua 30% phòng thủ vật lý của mục tiêu, sau khi tấn công bản thân [ngủ] một lượt (ngủ: hiệu ứng đặc biệt, không thể bị đánh thức hoặc xóa bỏ; khi ngủ miễn nhiễm sát thương, sẽ tỉnh dậy và nhận 500 nộ khí khi đồng đội tử trận)',
		describe_en = 'The King of Leave unleashes the ultimate punch, knocking away a single enemy target, dealing #C0xE69900#600% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Physical Damage#C0x5B545B#. This damage ignores 30% of the target\'s physical defense. After the attack, the user falls [asleep] for one turn (asleep: a special effect, cannot be awakened or removed; while asleep, immune to damage, will awaken and gain 500 rage when an ally dies).',
		describe_th = 'ราชาพักผ่อนได้ปล่อยหมัดสุดยอด อัดเป้าหมายฝ่ายเดียวให้ลอยออกไป สร้างความเสียหาย #C0xE69900#600% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ความเสียหายนี้ละเลยการป้องกันทางกายภาพของเป้าหมาย 30% หลังจากโจมตี ผู้ใช้จะ [หลับ] หนึ่งเทิร์น (หลับ: เอฟเฟกต์พิเศษ ไม่สามารถถูกปลุกหรือลบ ได้ขณะหลับจะได้รับการป้องกันความเสียหาย เมื่อเพื่อนร่วมทีมตายจะตื่นและได้รับความโกรธ 500)',
		describe_in = 'Raja cuti melancarkan pukulan tertinggi, menyingkirkan satu sasaran musuh, menyebabkan #C0xE69900#600% Serangan Fisik#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Serangan ini mengabaikan 30% pertahanan fisik target, setelah menyerang pengguna [tidur] selama satu giliran (tidur: efek khusus, tidak bisa dibangunkan atau dihapus; saat tidur kebal terhadap kerusakan, akan bangun dan mendapatkan 500 kemarahan saat rekan mati).',
		describe_ph = 'Pinuno ng bakasyon ay nagpalabas ng pinakamakapangyarihang suntok, na tinataboy ang isang sagutang target ng kalaban, na nagdudulot ng #C0xE69900#600% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Nilalampasan ng pinsalang ito ang 30% pisikal na depensa ng target; pagkatapos ng atake, ang gumagamit ay [natutulog] ng isang turn (natutulog: espesyal na epekto, hindi maaaring magising o maalis; habang natutulog ay immune sa pinsala, magigising at tatanggap ng 500 galit kapag namatay ang kakampi).',
		describe_ma = 'Raja cuti melancarkan tumbukan tertinggi, menewaskan sasaran tunggal musuh, menyebabkan #C0xE69900#600% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Kerosakan ini mengabaikan 30% pertahanan fizikal sasaran. Selepas menyerang, pengguna [tidur] selama satu pusingan (tidur: kesan khas, tidak boleh dibangunkan atau dihapus; semasa tidur kebal kepada kerosakan, akan bangun dan memperoleh 500 amarah apabila rakan sepasukan mati).',
		describe = 'The King of Leave unleashes the ultimate punch, knocking away a single enemy target, dealing #C0xE69900#600% Physical Attack#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54# Physical Damage#C0x5B545B#. This damage ignores 30% of the target\'s physical defense. After the attack, the user falls [asleep] for one turn (asleep: a special effect, cannot be awakened or removed; while asleep, immune to damage, will awaken and gain 500 rage when an ally dies).',
		simDesc_vn = 'Vương Giả sử dụng cú đấm tối thượng, đấm bay mục tiêu đơn lẻ của kẻ thù, bỏ qua một phần phòng ngự vật lý, sau khi tấn công sẽ bắt đầu lười biếng và không thể hành động.',
		simDesc_en = 'The King uses the ultimate punch, launching a single enemy target flying, ignoring part of their physical defense. After the attack, he becomes lazy and unable to act.',
		simDesc_th = 'ราชาใช้หมัดสูงสุด ชกเป้าหมายศัตรูเดี่ยวให้ลอยออกไป โดยละเลยการป้องกันทางกายภาพบางส่วน หลังจากโจมตีจะเริ่มขี้เกียจและไม่สามารถเคลื่อนไหวได้',
		simDesc_in = 'Raja menggunakan pukulan pamungkas, menghentakkan satu target musuh tunggal, mengabaikan sebagian pertahanan fisik. Setelah menyerang, dia menjadi malas dan tidak bisa bertindak.',
		simDesc_ph = 'Gumagamit ang Hari ng sukdulang suntok, tinatamaan ang isang kalabang target nang malakas, nilalampasan ang bahagi ng kanilang pisikal na depensa. Pagkatapos ng pag-atake, nagsisimula siyang maging tamad at hindi makakilos.',
		simDesc_ma = 'Raja menggunakan pukulan utama, menumbangkan satu sasaran musuh tunggal, mengabaikan sebahagian pertahanan fizikal. Selepas serangan, dia menjadi malas dan tidak dapat bertindak.',
		simDesc = 'The King uses the ultimate punch, launching a single enemy target flying, ignoring part of their physical defense. After the attack, he becomes lazy and unable to act.',
		starEffect = __data_t__starEffect[230500],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Bỏ qua 40% phòng thủ vật lý của mục tiêu, sau khi tỉnh dậy sẽ tăng cường 30% sát thương chí mạng trong 3 lượt.',
		starEffectDesc = 'Enhance effect: Ignore 40% of the target\'s physical defense. After waking up, increase critical damage by 30% for 3 turns.',
		starEffectDesc_en = 'Enhance effect: Ignore 40% of the target\'s physical defense. After waking up, increase critical damage by 30% for 3 turns.',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพ: ข้ามการป้องกันทางกายภาพของเป้าหมาย 40% หลังจากตื่นขึ้นจะเพิ่มความเสียหายคริติคอล 30% เป็นเวลา 3 เทิร์น',
		starEffectDesc_in = 'Perkuat efek: Abaikan 40% pertahanan fisik target, setelah bangun tingkatkan 30% kerusakan kritis selama 3 giliran.',
		starEffectDesc_ph = 'Pahusayin ang epekto: I-ignore ang 40% ng pisikal na depensa ng target, pagkatapos magising magpapataas ng 30% sa critical damage sa loob ng 3 na turn.',
		starEffectDesc_ma = 'Perkuat kesan: Abaikan 40% pertahanan fizikal sasaran, selepas bangun tingkatkan 30% kerosakan kritikal selama 3 pusingan.',
		upLvDesc = 'Fixed damage +300',
