	[250022] = {
		id = 250022,
		skillName_vn = 'Trút giận',
		skillName_en = 'Vent anger',
		skillName_th = 'ระบายความโกรธ',
		skillName_in = 'Melampiaskan kemarahan',
		skillName_ph = 'Ibulalas ang galit',
		skillName_ma = 'Lampiaskan kemarahan',
		skillName = 'Vent anger',
		describe_vn = 'Jigglypuff tức giận nhảy lên đấm mục tiêu đơn lẻ của đối phương, gây #C0x3D8A99#140% Công Phép thuật#C0x5B545B#+$(skillLevel*36)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, và có 50% xác suất khiến mục tiêu ngủ, kéo dài 1 lượt',
		describe_en = 'Jigglypuff angrily jumps up to punch a single enemy target, dealing #C0x3D8A99#140% Magic Power#C0x5B545B#+$(skillLevel*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 50% chance to put the target to sleep for 1 turn.',
		describe_th = 'จิกกลีพัฟกระโดดขึ้นด้วยความโกรธเพื่อชกเป้าหมายศัตรูเดี่ยว สร้าง #C0x3D8A99#140% พลังเวทมนตร์#C0x5B545B#+$(skillLevel*36)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# และมีโอกาส 50% ที่จะทำให้เป้าหมายหลับเป็นเวลา 1 เทิร์น',
