	[250121] = {
		id = 250121,
		skillName_vn = 'Tử khí tràn ngập',
		skillName_en = 'Death energy is overwhelming',
		skillName_th = 'พลังแห่งความตายล้นหลาม',
		skillName_in = 'Energi kematian meluap',
		skillName_ph = 'Ang enerhiya ng kamatayan ay bumabalot',
		skillName_ma = 'Tenaga maut melimpah',
		skillName = 'Death energy is overwhelming',
		describe_vn = 'Skeleton Lich King vung kiếm để giải phóng sức mạnh chết chóc, gây ra một lượng #C0xF13B54# sát thương phép #C0x5B545B# cho hai kẻ thù ngẫu nhiên. Đồng thời có khả năng 80-100% khiến chúng [ngủ] trong 2-3 hiệp (ngủ: không thể hành động và sẽ bị đánh thức khi bị tấn công). Khi Skeleton Lich King trở nên tức giận, phạm vi tấn công sẽ tăng thêm một mục tiêu.',
		describe_en = 'Skeleton Lich King swings his sword to unleash deadly power, causing #C0xF13B54# magic damage #C0x5B545B# to two random enemies. At the same time, he has an 80-100% chance to [sleep] them for 2-3 turns (sleep: unable to act and will be awakened when attacked). When Skeleton Lich King becomes furious, the attack range increases by one more target.',
		describe_th = 'Skeleton Lich King ฟันดาบเพื่อปลดปล่อยพลังทำลายล้าง สร้างความเสียหายเวทมนตร์ #C0xF13B54# #C0x5B545B# แก่ศัตรูสุ่ม 2 ตัว พร้อมโอกาส 80-100% ที่จะทำให้พวกเขา [หลับ] เป็นเวลา 2-3 เทิร์น (หลับ: ไม่สามารถกระทำได้และจะตื่นเมื่อถูกโจมตี) เมื่อ Skeleton Lich King โกรธ เคลือบช่วงการโจมตีจะเพิ่มเป้าหมายอีก 1 ตัว',
		describe_in = 'Skeleton Lich King mengayunkan pedangnya untuk melepaskan kekuatan mematikan, menyebabkan #C0xF13B54# kerusakan sihir #C0x5B545B# pada dua musuh acak. Pada saat yang sama, dia memiliki peluang 80-100% untuk membuat mereka [tidur] selama 2-3 giliran (tidur: tidak bisa bertindak dan akan terbangun saat diserang). Ketika Skeleton Lich King menjadi marah, jangkauan serangan bertambah satu target lagi.',
		describe_ph = 'Nililikha ng Skeleton Lich King ang kanyang espada upang palayain ang nakamamatay na kapangyarihan, na nagdudulot ng #C0xF13B54# magic na pinsala #C0x5B545B# sa dalawang random na kaaway. Kasabay nito, may 80-100% na pagkakataon na mapatulog sila ng 2-3 na turn (tulog: hindi makakilos at magigising kapag inatake). Kapag nagalit si Skeleton Lich King, tataas ang saklaw ng atake ng isa pang target.',
		describe_ma = 'Skeleton Lich King mengayunkan pedang untuk melepaskan kuasa maut, menyebabkan #C0xF13B54# kerosakan sihir #C0x5B545B# kepada dua musuh rawak. Pada masa yang sama, dia mempunyai peluang 80-100% untuk menyebabkan mereka [tidur] selama 2-3 pusingan (tidur: tidak dapat bertindak dan akan terjaga apabila diserang). Apabila Skeleton Lich King menjadi marah, julat serangan akan bertambah satu sasaran lagi.',
		describe = 'Skeleton Lich King swings his sword to unleash deadly power, causing #C0xF13B54# magic damage #C0x5B545B# to two random enemies. At the same time, he has an 80-100% chance to [sleep] them for 2-3 turns (sleep: unable to act and will be awakened when attacked). When Skeleton Lich King becomes furious, the attack range increases by one more target.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		skillType2 = 0,
		skillDamageType = 1,
		skillNatureType = 6,
		posChoose = 5,
		targetTypeDesc = 'Hai Random enemy target',
		targetTypeDesc_vn = 'Hai mục tiêu ngẫu nhiên của địch',
		targetTypeDesc_en = 'Hai Random enemy target',
		targetTypeDesc_th = 'Hai เป้าหมายสุ่มของศัตรู',
