	[250122] = {
		id = 250122,
		skillName_vn = 'Bộc phát tử khí',
		skillName_en = 'Sudden deadly aura',
		skillName_th = 'พลังมรณะที่เกิดขึ้นทันที',
		skillName_in = 'Aura kematian yang tiba-tiba muncul',
		skillName_ph = 'Biglang sumiklab na nakamamatay na aura',
		skillName_ma = 'Aura maut yang tiba-tiba muncul',
		skillName = 'Sudden deadly aura',
		describe_vn = 'Skeleton Lich King vung kiếm để kích nổ sức mạnh tử thần, tấn công một mục tiêu địch duy nhất gây ra một lượng #C0xF13B54# sát thương phép #C0x5B545B#, gây thêm 30% sát thương cho mục tiêu hiện đang ngủ và giảm vĩnh viễn 5% sát thương của mục tiêu đó (không thể hóa giải). Khi giấc ngủ trên sân địch tích lũy đến một mức nhất định, những anh hùng ngủ quá lâu sẽ bị Lich King trừng phạt.',
		describe_en = 'Skeleton Lich King swings his sword to unleash necrotic power, attacking a single enemy target to deal #C0xF13B54# magic damage #C0x5B545B#, dealing an additional 30% damage to targets currently asleep and permanently reducing that target\'s damage by 5% (cannot be dispelled). When the sleep effect on the enemy field accumulates to a certain level, heroes who have slept too long will be punished by the Lich King.',
		describe_th = 'Skeleton Lich King ฟันดาบเพื่อปลดปล่อยพลังปีศาจโจมตีเป้าหมายศัตรูเพียงหนึ่งรายสร้างความเสียหายเวทย์ #C0xF13B54# #C0x5B545B# เพิ่มเติม 30% กับเป้าหมายที่กำลังหลับและลดความเสียหายของเป้าหมายถาวร 5% (ไม่สามารถลบล้างได้) เมื่อสถานะหลับในสนามศัตรูสะสมถึงระดับหนึ่ง ฮีโร่ที่หลับนานเกินไปจะได้รับการลงโทษจาก Lich King',
		describe_in = 'Skeleton Lich King mengayunkan pedangnya untuk melepaskan kekuatan kematian, menyerang satu target musuh dan memberikan #C0xF13B54# kerusakan sihir #C0x5B545B#, memberikan tambahan 30% kerusakan pada target yang sedang tertidur dan secara permanen mengurangi 5% kerusakan target tersebut (tidak bisa dihilangkan). Saat efek tidur di medan musuh mencapai tingkat tertentu, para pahlawan yang tertidur terlalu lama akan dihukum oleh Lich King.',
		describe_ph = 'Inihahampas ng Skeleton Lich King ang kanyang espada upang palayain ang kapangyarihan ng kamatayan, sumasalakay sa isang target na kalaban na nagdudulot ng #C0xF13B54# na magic damage #C0x5B545B#, nagdaragdag ng 30% na dagdag na pinsala sa mga target na natutulog at permanenteng binabawasan ang pinsala ng target ng 5% (hindi maaaring alisin). Kapag ang pagtulog sa larangan ng kalaban ay umabot sa isang tiyak na antas, ang mga bayani na matagal nang natutulog ay paparusahan ng Lich King.',
		describe_ma = 'Skeleton Lich King mengayunkan pedangnya untuk melepaskan kuasa kematian, menyerang satu sasaran musuh dan menyebabkan #C0xF13B54# kerosakan sihir #C0x5B545B#, memberikan tambahan 30% kerosakan kepada sasaran yang sedang tidur dan mengurangkan kerosakan sasaran itu secara kekal sebanyak 5% (tidak boleh dibersihkan). Apabila kesan tidur di medan musuh terkumpul ke tahap tertentu, wira yang tidur terlalu lama akan dihukum oleh Lich King.',
		describe = 'Skeleton Lich King swings his sword to unleash necrotic power, attacking a single enemy target to deal #C0xF13B54# magic damage #C0x5B545B#, dealing an additional 30% damage to targets currently asleep and permanently reducing that target\'s damage by 5% (cannot be dispelled). When the sleep effect on the enemy field accumulates to a certain level, heroes who have slept too long will be punished by the Lich King.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
