	[250126] = {
		id = 250126,
		skillName_vn = 'Vua Lich',
		skillName_en = 'King of History',
		skillName_th = 'ราชาแห่งประวัติศาสตร์',
		skillName_in = 'Raja Sejarah',
		skillName_ph = 'Hari ng Kasaysayan',
		skillName_ma = 'Raja Sejarah',
		skillName = 'King of History',
		describe_vn = '[Kiểm soát miễn dịch]: Hiệu ứng kiểm soát miễn dịch của Skeleton Lich King;\n[Giấc ngủ đặc biệt]: Tấn công một anh hùng đang ngủ sẽ không đánh thức mục tiêu. Sau khi mục tiêu bị Skeleton Lich King thôi miên, nếu giấc ngủ của mục tiêu bị xua tan hoặc đánh thức, giá trị cơn thịnh nộ của mục tiêu sẽ tăng thêm 400 điểm. Nếu mục tiêu thức dậy một cách tự nhiên, mục tiêu sẽ mất 200 điểm nộ. giá trị;\n[Nâng cao kỹ năng]: Khi Skeleton Lich King tung ra chiêu thức đặc biệt của mình hai lần, mỗi lần tung ra Vụ nổ không khí tử thần, hắn sẽ tấn công tất cả các mục tiêu đang ngủ trên sân;\n[Cải thiện khả năng]: Skeleton Lich King sẽ tăng dần thuộc tính và hiệu ứng tấn công tùy theo lượng sát thương mà nó nhận được và sẽ chuyển sang trạng thái tức giận sau một vòng nhất định.',
		describe_en = '[Immune Control]: Immune control effect of Skeleton Lich King;\n[Special Sleep]: Attacking a sleeping hero will not wake the target. After the target is hypnotized by Skeleton Lich King, if the target\'s sleep is dispelled or awakened, the target\'s rage value will increase by 400 points. If the target wakes up naturally, the target will lose 200 rage points.;\n[Skill Enhancement]: When Skeleton Lich King uses his special skill twice, each time unleashing the Death Air Burst, he will attack all sleeping targets on the field;\n[Ability Improvement]: Skeleton Lich King will gradually increase his attributes and attack effects based on the damage he receives and will enter an enraged state after a certain round.',
		describe_th = '[ควบคุมภูมิคุ้มกัน]: เอฟเฟกต์ควบคุมภูมิคุ้มกันของ Skeleton Lich King;\n[การนอนหลับพิเศษ]: การโจมตีฮีโร่ที่กำลังนอนหลับจะไม่ปลุกเป้าหมาย หลังจากที่เป้าหมายถูกสะกดจิตโดย Skeleton Lich King หากการนอนของเป้าหมายถูกขจัดหรือปลุกขึ้น ค่าโกรธของเป้าหมายจะเพิ่มขึ้น 400 คะแนน หากเป้าหมายตื่นขึ้นเองตามธรรมชาติ เป้าหมายจะสูญเสียค่าโกรธ 200 คะแนน;\n[การเพิ่มทักษะ]: เมื่อ Skeleton Lich King ใช้สกิลพิเศษของเขาสองครั้ง แต่ละครั้งที่ใช้ระเบิดลมมรณะ เขาจะโจมตีเป้าหมายที่กำลังนอนหลับทั้งหมดบนสนาม;\n[การปรับปรุงความสามารถ]: Skeleton Lich King จะเพิ่มค่าคุณลักษณะและเอฟเฟกต์การโจมตีตามปริมาณความเสียหายที่ได้รับ และจะเข้าสู่สถานะโกรธหลังจากรอบหนึ่งรอบ',
		describe_in = '[Kontrol Kekebalan]: Efek kontrol kekebalan dari Skeleton Lich King;\n[Tidur Khusus]: Menyerang pahlawan yang sedang tidur tidak akan membangunkan target. Setelah target terhipnotis oleh Skeleton Lich King, jika tidur target terganggu atau dibangunkan, nilai amarah target akan meningkat 400 poin. Jika target terbangun secara alami, target akan kehilangan 200 poin amarah.;\n[Peningkatan Keterampilan]: Ketika Skeleton Lich King menggunakan skill khususnya dua kali, setiap kali melepaskan Ledakan Udara Kematian, dia akan menyerang semua target yang sedang tidur di medan;\n[Peningkatan Kemampuan]: Skeleton Lich King akan secara bertahap meningkatkan atribut dan efek serangan tergantung pada jumlah kerusakan yang diterimanya dan akan memasuki keadaan marah setelah putaran tertentu.',
		describe_ph = '[Kontrol ng Imyunidad]: Epekto ng kontrol ng imyunidad ng Skeleton Lich King;\n[Espesyal na Tulog]: Ang pag-atake sa isang bayani na natutulog ay hindi magigising sa target. Pagkatapos mahypnotize ang target ng Skeleton Lich King, kung mabubura o magigising ang tulog ng target, tataas ang halaga ng galit ng target ng 400 puntos. Kung ang target ay natural na magigising, mawawala ang 200 puntos ng galit ng target.;\n[Pagpapahusay ng Kasanayan]: Kapag ginamit ni Skeleton Lich King ang kanyang espesyal na kasanayan nang dalawang beses, sa bawat pagpapalabas ng Patay na Pagsabog ng Hangin, siya ay aatake sa lahat ng mga natutulog na target sa larangan;\n[Pagpapabuti ng Kakayahan]: Unti-unting dadagdagan ni Skeleton Lich King ang kanyang mga katangian at epekto ng atake batay sa natanggap niyang pinsala at papasok siya sa estado ng galit pagkatapos ng isang natukoy na round.',
		describe_ma = '[Kawalan Imuniti]: Kesan kawalan imuniti bagi Skeleton Lich King;\n[Tidur Khas]: Menyerang wira yang sedang tidur tidak akan membangunkan sasaran. Setelah sasaran dihipnotis oleh Skeleton Lich King, jika tidur sasaran dibatalkan atau dibangunkan, nilai kemarahan sasaran akan meningkat 400 mata. Jika sasaran bangun secara semula jadi, sasaran akan kehilangan 200 mata kemarahan.;\n[Peningkatan Kemahiran]: Apabila Skeleton Lich King menggunakan kemahiran khasnya dua kali, setiap kali melancarkan Letupan Udara Kematian, dia akan menyerang semua sasaran yang sedang tidur di medan;\n[Peningkatan Keupayaan]: Skeleton Lich King akan meningkatkan atribut dan kesan serangannya secara beransur-ansur bergantung pada jumlah kerosakan yang diterimanya dan akan memasuki keadaan marah selepas satu pusingan tertentu.',
		describe = '[Immune Control]: Immune control effect of Skeleton Lich King;\n[Special Sleep]: Attacking a sleeping hero will not wake the target. After the target is hypnotized by Skeleton Lich King, if the target\'s sleep is dispelled or awakened, the target\'s rage value will increase by 400 points. If the target wakes up naturally, the target will lose 200 rage points.;\n[Skill Enhancement]: When Skeleton Lich King uses his special skill twice, each time unleashing the Death Air Burst, he will attack all sleeping targets on the field;\n[Ability Improvement]: Skeleton Lich King will gradually increase his attributes and attack effects based on the damage he receives and will enter an enraged state after a certain round.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = __data_t__skillProcess[250126]
