	[251011] = {
		id = 251011,
		skillName_vn = 'Bóng dáng thần thánh',
		skillName_en = 'Divine figure',
		skillName_th = 'ร่างเทพเจ้า',
		skillName_in = 'Sosok ilahi',
		skillName_ph = 'Diyos na nilalang',
		skillName_ma = 'Sosok ilahi',
		skillName = 'Divine figure',
		describe_vn = 'Con rắn đen giải phóng bóng tối của tâm trí, triệu hồi linh hồn ma quỷ gây ra một lượng #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B# cho 2-3 mục tiêu địch ngẫu nhiên, đồng thời thêm 1 lớp [ngộ độc] (ngộ độc: mục tiêu mất 1% giới hạn mạng sống tối đa của sát thương thực tế trước mỗi hiệp, kéo dài 5 hiệp, hiệu ứng đầu độc có thể bị giải trừ, khi chồng lên 10 lớp sẽ ngay lập tức gây ra 80% giới hạn tuổi thọ tối đa của sát thương thực tế của mục tiêu). Nếu mục tiêu đã bị nhiễm độc, số lớp nhiễm độc sẽ tăng gấp đôi.',
		describe_en = 'The black snake releases the darkness of the mind, summoning the demon spirit to deal #C0xF13B54# Magical Damage #C0x5B545B# to 2-3 random enemy targets, while adding 1 layer of [poison] (poison: the target loses 1% of maximum HP from actual damage before each turn, lasts 5 turns, poison effect can be dispelled, and when stacked to 10 layers, instantly deals 80% of the target\'s maximum lifespan as actual damage). If the target is already poisoned, the poison stacks double.',
		describe_th = 'งูดำปลดปล่อยความมืดมิดในจิตใจ เรียกวิญญาณปีศาจก่อให้เกิด #C0xF13B54# พลังโจมตีเวทมนตร์ #C0x5B545B# แก่ศัตรู 2-3 ตัวแบบสุ่ม พร้อมเพิ่มชั้น [พิษ] 1 ชั้น (พิษ: ศัตรูจะเสียพลังชีวิตสูงสุด 1% จากความเสียหายจริงก่อนแต่ละเทิร์น เป็นเวลา 5 เทิร์น เอฟเฟกต์พิษสามารถถูกขจัดได้ เมื่อสะสมครบ 10 ชั้น จะทำความเสียหายจริงเท่ากับ 80% ของพลังชีวิตสูงสุดของเป้าหมายทันที) หากเป้าหมายติดพิษอยู่แล้ว จำนวนชั้นพิษจะเพิ่มเป็นสองเท่า',
		describe_in = 'Ular hitam melepaskan kegelapan pikiran, memanggil roh setan yang menyebabkan #C0xF13B54# Kerusakan Sihir #C0x5B545B# kepada 2-3 target musuh secara acak, sekaligus menambahkan 1 lapis [racun] (racun: target kehilangan 1% batas maksimum HP dari damage sebenarnya sebelum setiap giliran, bertahan selama 5 giliran, efek racun dapat dihapus, saat menumpuk hingga 10 lapisan langsung menyebabkan damage nyata sebesar 80% dari batas umur maksimum target). Jika target sudah teracuni, jumlah lapisan racun akan meningkat dua kali lipat.',
		describe_ph = 'Ang itim na ahas ay nagpapalaya ng kadiliman ng isip, nananawagan ng espiritu ng demonyo na nagdudulot ng #C0xF13B54# Magical Damage #C0x5B545B# sa 2-3 na random na kalaban, kasabay ng pagdaragdag ng 1 layer ng [poison] (poison: nawawalan ang target ng 1% ng maximum HP mula sa aktwal na pinsala bago ang bawat turn, tumatagal ng 5 turns, ang epekto ng poison ay maaaring maalis, kapag umabot sa 10 layers ay agad na nagdudulot ng 80% ng maximum lifespan na aktwal na pinsala sa target). Kung ang target ay na-poison na, ang bilang ng poison layers ay dodoblehin.',
		describe_ma = 'Ular hitam membebaskan kegelapan minda, memanggil roh iblis yang menyebabkan #C0xF13B54# Kerosakan Sihir #C0x5B545B# kepada 2-3 sasaran musuh secara rawak, serta menambah 1 lapisan [racun] (racun: sasaran kehilangan 1% had maksimum HP daripada kerosakan sebenar sebelum setiap giliran, bertahan selama 5 giliran, kesan racun boleh disingkirkan, apabila bertindih hingga 10 lapisan akan terus menyebabkan 80% had umur maksimum sebagai kerosakan sebenar kepada sasaran). Jika sasaran sudah dijangkiti racun, bilangan lapisan racun akan meningkat dua kali ganda.',
		describe = 'The black snake releases the darkness of the mind, summoning the demon spirit to deal #C0xF13B54# Magical Damage #C0x5B545B# to 2-3 random enemy targets, while adding 1 layer of [poison] (poison: the target loses 1% of maximum HP from actual damage before each turn, lasts 5 turns, poison effect can be dispelled, and when stacked to 10 layers, instantly deals 80% of the target\'s maximum lifespan as actual damage). If the target is already poisoned, the poison stacks double.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
