	[251012] = {
		id = 251012,
		skillName_vn = 'Ngọn lửa phẫn nộ',
		skillName_en = 'Flame of Rage',
		skillName_th = 'เปลวไฟแห่งความโกรธ',
		skillName_in = 'Api Kemarahan',
		skillName_ph = 'Apoy ng Galit',
		skillName_ma = 'Api Kemarahan',
		skillName = 'Flame of Rage',
		describe_vn = 'Dark Serpent sử dụng sức mạnh của bóng tối để hấp thụ 300 điểm giận dữ từ hai mục tiêu ngẫu nhiên, gây ra một lượng #C0xF13B54# sát thương phép #C0x5B545B# và tăng tỷ lệ chí mạng của bản thân thêm 40% trong 2 lượt. Sau một vòng nhất định, khả năng hấp thụ tức giận sẽ có hiệu lực đối với tất cả các mục tiêu trên sân đang ở trạng thái [Sợ hãi]',
		describe_en = 'Dark Serpent uses the power of darkness to absorb 300 anger points from two random targets, dealing #C0xF13B54# magic damage #C0x5B545B# and increasing its own critical rate by 40% for 2 turns. After a certain number of rounds, the anger absorption ability will affect all targets on the field who are in [Fear] status.',
		describe_th = 'Dark Serpent ใช้พลังแห่งความมืดเพื่อดูดซับความโกรธ 300 จุดจากเป้าหมายสุ่มสองตัว สร้างความเสียหายเวทมนตร์ #C0xF13B54# และเพิ่มอัตราคริติคอลของตนเองขึ้น 40% เป็นเวลา 2 เทิร์น หลังจากรอบที่กำหนด ความสามารถดูดซับความโกรธจะส่งผลต่อเป้าหมายทั้งหมดบนสนามที่อยู่ในสถานะ [กลัว]',
		describe_in = 'Dark Serpent menggunakan kekuatan kegelapan untuk menyerap 300 poin kemarahan dari dua target acak, memberikan #C0xF13B54# damage sihir #C0x5B545B# dan meningkatkan rate kritisnya sendiri sebesar 40% selama 2 giliran. Setelah sejumlah giliran tertentu, kemampuan penyerap amarah akan berlaku untuk semua target di medan yang berada dalam status [Takut].',
		describe_ph = 'Ginagamit ng Dark Serpent ang kapangyarihan ng kadiliman para sumipsip ng 300 puntos ng galit mula sa dalawang random na target, na nagdudulot ng #C0xF13B54# na spell damage #C0x5B545B# at pinapataas ang sariling crit rate ng 40% sa loob ng 2 na turn. Pagkatapos ng ilang round, ang kakayahan sa pagsipsip ng galit ay magkakaroon ng epekto sa lahat ng target sa field na nasa [Takot] na estado.',
		describe_ma = 'Dark Serpent menggunakan kuasa kegelapan untuk menyerap 300 mata kemarahan daripada dua sasaran rawak, menyebabkan kerosakan sihir #C0xF13B54# dan meningkatkan kadar kritikal sendiri sebanyak 40% selama 2 pusingan. Selepas beberapa pusingan tertentu, keupayaan penyerap kemarahan akan berkesan ke atas semua sasaran di medan yang berada dalam keadaan [Takut].',
		describe = 'Dark Serpent uses the power of darkness to absorb 300 anger points from two random targets, dealing #C0xF13B54# magic damage #C0x5B545B# and increasing its own critical rate by 40% for 2 turns. After a certain number of rounds, the anger absorption ability will affect all targets on the field who are in [Fear] status.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
