	[251016] = {
		id = 251016,
		skillName_vn = 'Ý chí trái đất',
		skillName_en = 'Will of the Earth',
		skillName_th = 'เจตจำนงแห่งโลก',
		skillName_in = 'Kemauan Bumi',
		skillName_ph = 'Kalooban ng Lupa',
		skillName_ma = 'Keazaman Bumi',
		skillName = 'Will of the Earth',
		describe_vn = '[Cấu trúc miễn dịch]: Miễn dịch với các hiệu ứng kiểm soát và hiệu ứng đầu độc;\n[Sáng tạo tiêu cực]: Mỗi đòn tấn công khiến mục tiêu rơi vào hai hiệu ứng tiêu cực ngẫu nhiên (giảm tấn Công Phép thuật, phòng thủ phép thuật, Sát Thương Vật Lý, phòng thủ vật lý, đầu độc, giảm khả năng hồi máu), kéo dài trong 5 hiệp và có thể bị xua tan;\n[Sợ hãi sâu sắc]: Khi mục tiêu [Sợ hãi] lại rơi vào trạng thái [Sợ hãi], nó sẽ chuyển sang [Sợ hãi sâu sắc] và hiệu ứng sợ hãi cũng sẽ làm giảm tốc độ hồi phục cơn thịnh nộ thêm một phần 50% và không thể hoạt động được. Được tự động hóa giải;\n[Lời nguyền cực ác]: Bắt đầu từ vòng thứ 8, Dark Serpent sẽ quan sát mục tiêu tấn công cao nhất của kẻ địch cứ sau 1 lượt và gắn [Lời nguyền] vào mục tiêu đó trong 2 lượt (Lời nguyền: Sát thương tăng 50%, luôn ở trạng thái cuồng nộ tối đa, nhưng sau khi tung ra chiêu thức đặc biệt, nó sẽ phản công gấp đôi sát thương của chiêu thức đặc biệt này)\n[Cải thiện khả năng]: Dark Serpent sẽ tăng dần thuộc tính và hiệu ứng tấn công theo lượng thiệt hại mà nó nhận được.',
		describe_en = '[Immune Structure]: Immune to control effects and poison effects;\n[Negative Creation]: Each attack causes the target to fall under two random negative effects (reduced Magic Attack, Magic Defense, Physical Damage, Physical Defense, poison, reduced healing ability), lasting 5 turns and can be dispelled;\n[Deep Fear]: When a target already under [Fear] falls under [Fear] again, it will be converted to [Deep Fear], and the fear effect will additionally reduce rage recovery speed by 50% and disables its actions. Auto dispelled;\n[Extremely Evil Curse]: Starting from round 8, Dark Serpent will observe the enemy\'s highest attacking target every turn and place [Curse] on that target for 2 turns (Curse: Damage increased by 50%, always at maximum rage state, but after using a special skill, it retaliates with double the damage of that special skill)\n[Ability Enhancement]: Dark Serpent will gradually increase its attributes and attack effects based on the damage it receives.',
		describe_th = '[โครงสร้างภูมิคุ้มกัน]: ภูมิคุ้มกันต่อเอฟเฟกต์ควบคุมและเอฟเฟกต์พิษ;\n[การสร้างลบ]: ทุกการโจมตีทำให้เป้าหมายตกอยู่ภายใต้เอฟเฟกต์ลบแบบสุ่มสองอย่าง (ลดพลังโจมตีเวทย์มนตร์, การป้องกันเวทย์มนตร์, ความเสียหายทางกายภาพ, การป้องกันทางกายภาพ, พิษ, ลดความสามารถในการฟื้นฟู) มีผล 5 เทิร์นและสามารถกำจัดได้;\n[ความกลัวลึกซึ้ง]: เมื่อเป้าหมายที่อยู่ในสถานะ [กลัว] ถูกตกอยู่ในสถานะ [กลัว] อีกครั้ง มันจะกลายเป็น [ความกลัวลึกซึ้ง] และเอฟเฟกต์กลัวจะลดความเร็วในการฟื้นฟูความโกรธลงอีก 50% และไม่สามารถทำงานได้ การกำจัดอัตโนมัติ;\n[คำสาปชั่วร้ายสุดขีด]: เริ่มตั้งแต่รอบที่ 8 Dark Serpent จะสังเกตเป้าหมายที่มีการโจมตีสูงสุดของศัตรูในแต่ละเทิร์นและติด [คำสาป] กับเป้าหมายนั้นเป็นเวลา 2 เทิร์น (คำสาป: ความเสียหายเพิ่มขึ้น 50% อยู่ในสถานะความโกรธสูงสุดเสมอ แต่หลังจากใช้สกิลพิเศษ มันจะตอบโต้ด้วยความเสียหายจากสกิลพิเศษนั้นสองเท่า)\n[การเพิ่มประสิทธิภาพความสามารถ]: Dark Serpent จะเพิ่มแอตทริบิวต์และเอฟเฟกต์การโจมตีทีละน้อยตามปริมาณความเสียหายที่ได้รับ',
		describe_in = '[Struktur Kekebalan]: Kebal terhadap efek kontrol dan efek racun;\n[Kreasi Negatif]: Setiap serangan membuat target terkena dua efek negatif acak (mengurangi Serangan Sihir, Pertahanan Sihir, Kerusakan Fisik, Pertahanan Fisik, racun, mengurangi kemampuan penyembuhan), berlangsung selama 5 giliran dan bisa dihapus;\n[Rasa Takut Mendalam]: Ketika target yang sudah terkena [Takut] terkena [Takut] lagi, ia akan berubah menjadi [Takut Mendalam], dan efek takut juga akan mengurangi kecepatan pemulihan kemarahan sebesar 50% tambahan dan tidak bisa beraksi. Otomatis hilang;\n[Sumpah Serapah Jahat]: Mulai dari ronde ke-8, Dark Serpent akan mengamati target dengan serangan tertinggi musuh setiap giliran dan menempelkan [Sumpah Serapah] pada target itu selama 2 giliran (Sumpah Serapah: Kerusakan meningkat 50%, selalu dalam keadaan kemarahan maksimal, tetapi setelah menggunakan skill spesial, akan membalas dengan damage skill spesial itu dua kali lipat)\n[Peningkatan Kemampuan]: Dark Serpent akan secara bertahap meningkatkan atribut dan efek serangan berdasarkan jumlah damage yang diterimanya.',
		describe_ph = '[Immune Structure]: Immune sa mga control effects at poison effects;\n[Negative Creation]: Bawat atake ay nagdudulot sa target ng dalawang random na negative effects (bawas sa Magic Attack, Magic Defense, Physical Damage, Physical Defense, poison, bawas sa healing ability), tumatagal ng 5 turns at maaaring matanggal;\n[Deep Fear]: Kapag ang target na may [Fear] ay naulit na mapapasok sa [Fear], ito ay magiging [Deep Fear], at ang fear effect ay babawasan pa lalo ang bilis ng rage recovery ng 50% at hindi makakagawa ng aksyon. Kusang naaalis;\n[Extreme Evil Curse]: Simula sa round 8, ang Dark Serpent ay mag-oobserba sa pinakamataas na attacking target ng kalaban bawat turn at maglalagay ng [Curse] sa target na iyon ng 2 turns (Curse: Damage tumaas ng 50%, palaging nasa maximum rage state, ngunit pagkatapos mag-cast ng special skill, magrereact ng doble ng damage ng special skill na iyon)\n[Ability Enhancement]: Unti-unting tataas ang attributes at attack effects ng Dark Serpent base sa damage na natatanggap nito.',
		describe_ma = '[Struktur Imuniti]: Kebal terhadap kesan kawalan dan kesan racun;\n[Kreativiti Negatif]: Setiap serangan menyebabkan sasaran mengalami dua kesan negatif rawak (mengurangkan Serangan Sihir, Pertahanan Sihir, Kerosakan Fizikal, Pertahanan Fizikal, racun, mengurangkan kemampuan pemulihan), berlangsung selama 5 pusingan dan boleh dibuang;\n[Ketakutan Mendalam]: Apabila sasaran yang sudah [Ketakutan] terkena [Ketakutan] lagi, ia akan bertukar menjadi [Ketakutan Mendalam], dan kesan takut juga akan mengurangkan kelajuan pemulihan kemarahan sebanyak 50% tambahan dan tidak boleh bertindak. Automatik dibuang;\n[Sumpahan Jahat]: Bermula dari pusingan ke-8, Dark Serpent akan memerhati sasaran serangan tertinggi musuh setiap pusingan dan meletakkan [Sumpahan] pada sasaran itu selama 2 pusingan (Sumpahan: Kerosakan meningkat 50%, sentiasa dalam keadaan kemarahan maksimum, tetapi selepas menggunakan kemahiran khas, ia akan membalas dengan kerosakan kemahiran khas itu dua kali ganda)\n[Peningkatan Keupayaan]: Dark Serpent akan secara beransur-ansur meningkatkan atribut dan kesan serangan berdasarkan jumlah kerosakan yang diterimanya.',
		describe = '[Immune Structure]: Immune to control effects and poison effects;\n[Negative Creation]: Each attack causes the target to fall under two random negative effects (reduced Magic Attack, Magic Defense, Physical Damage, Physical Defense, poison, reduced healing ability), lasting 5 turns and can be dispelled;\n[Deep Fear]: When a target already under [Fear] falls under [Fear] again, it will be converted to [Deep Fear], and the fear effect will additionally reduce rage recovery speed by 50% and disables its actions. Auto dispelled;\n[Extremely Evil Curse]: Starting from round 8, Dark Serpent will observe the enemy\'s highest attacking target every turn and place [Curse] on that target for 2 turns (Curse: Damage increased by 50%, always at maximum rage state, but after using a special skill, it retaliates with double the damage of that special skill)\n[Ability Enhancement]: Dark Serpent will gradually increase its attributes and attack effects based on the damage it receives.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {2510161, 2510162}
	},
