	[300113] = {
		id = 300113,
		skillName_vn = 'Phun lửa',
		skillName_en = 'Fire breath',
		skillName_th = 'พ่นไฟ',
		skillName_in = 'Menyemburkan api',
		skillName_ph = 'Umiilaw ng apoy',
		skillName_ma = 'Menyembur api',
		skillName = 'Fire breath',
		describe_vn = 'Bay lên không trung, phun lửa vào mục tiêu hàng dọc của kẻ địch, gây ra #C0x3D8A99#220% Công Phép#C0x5B545B#+$( skillLevel *36)$ sát thương #C0x8A5C99#phép thuật#C0x5B545B#, nếu đơn vị kẻ địch có hiệu ứng đốt cháy, sát thương lần này tăng 25%; và có 60% xác suất thêm 2 tầng hiệu ứng đốt cháy cho mục tiêu, kéo dài 2 lượt.',
		describe_en = 'Soar into the air, spitting fire at a vertical line of enemy targets, dealing #C0x3D8A99#220% Magic Power#C0x5B545B#+$( skillLevel *36)$ #C0x8A5C99#magic#C0x5B545B# damage. If the enemy unit is affected by Burn, this damage is increased by 25%; and there is a 60% chance to add 2 layers of Burn effect to the target, lasting 2 turns.',
		describe_th = 'บินขึ้นสู่อากาศ พ่นไฟใส่เป้าหมายในแนวตั้งของศัตรู สร้างความเสียหาย #C0x3D8A99#220% พลังเวท#C0x5B545B#+$( skillLevel *36)$ #C0x8A5C99#เวทมนตร์#C0x5B545B# หากหน่วยศัตรูมีสถานะเผาไหม้ ความเสียหายนี้จะเพิ่มขึ้น 25%; และมีโอกาส 60% ที่จะเพิ่มชั้นสถานะเผาไหม้ 2 ชั้นให้กับเป้าหมาย เป็นเวลานาน 2 เทิร์น',
		describe_in = 'Terbang ke udara, menyemburkan api ke barisan target musuh vertikal, memberikan #C0x3D8A99#220% Kekuatan Sihir#C0x5B545B#+$( skillLevel *36)$ kerusakan #C0x8A5C99#sihir#C0x5B545B#. Jika unit musuh memiliki efek terbakar, kerusakan ini meningkat 25%; dan ada peluang 60% untuk menambahkan 2 lapis efek terbakar pada target, berlangsung selama 2 giliran.',
		describe_ph = 'Lumipad sa himpapawid, umuusok ng apoy sa isang patayong hanay ng mga kalaban, na nagdudulot ng #C0x3D8A99#220% Lakas ng Mahika#C0x5B545B#+$( skillLevel *36)$ na pinsalang #C0x8A5C99#mahika#C0x5B545B#. Kung ang unit ng kalaban ay may epekto ng pagsunog, tumataas ang pinsala ng 25%; at may 60% na tsansa na magdagdag ng 2 patong ng epekto ng pagsunog sa target, na tumatagal ng 2 turnos.',
		describe_ma = 'Terbang ke udara, memuntahkan api ke barisan sasaran musuh, menyebabkan #C0x3D8A99#220% Kuasa Sihir#C0x5B545B#+$( skillLevel *36)$ kerosakan #C0x8A5C99#sihir#C0x5B545B#. Jika unit musuh mempunyai kesan terbakar, kerosakan ini meningkat 25%; dan terdapat 60% peluang untuk menambah 2 lapisan kesan terbakar ke sasaran, berlangsung selama 2 pusingan.',
		describe = 'Soar into the air, spitting fire at a vertical line of enemy targets, dealing #C0x3D8A99#220% Magic Power#C0x5B545B#+$( skillLevel *36)$ #C0x8A5C99#magic#C0x5B545B# damage. If the enemy unit is affected by Burn, this damage is increased by 25%; and there is a 60% chance to add 2 layers of Burn effect to the target, lasting 2 turns.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		skillType2 = 2,
		skillDamageType = 1,
		skillNatureType = 2,
		targetTypeDesc = 'Enemy vertical row',
