	[420011] = {
		id = 420011,
		skillName_vn = 'Kỹ năng nhỏ siêu xấu',
		skillName_en = 'Super ugly small skill',
		skillName_th = 'ทักษะเล็กที่น่าเกลียดมาก',
		skillName_in = 'Keterampilan kecil yang sangat jelek',
		skillName_ph = 'Sobrang pangit na maliit na kasanayan',
		skillName_ma = 'Kemahiran kecil yang sangat hodoh',
		skillName = 'Super ugly small skill',
		describe_vn = 'Siêu Xấu Tinh bắn toàn bộ gai độc trên người về phía mục tiêu đơn lẻ của đối phương, gây #C0xE69900#160% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, đồng thời làm các bộ phận bị tổn thương của bản thân tái sinh nhanh chóng: hồi phục lượng máu bằng (5%+số mục tiêu bị trúng độc trong đội hình đối phương*5%) giới hạn máu của bản thân, tối đa không vượt quá 300% Công Phép của bản thân',
		describe_en = 'Super Evil Star shoots all the poisonous spikes on its body towards a single enemy target, dealing #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#. At the same time, the injured parts of itself rapidly regenerate: healing HP equal to (5% + number of poisoned targets in the enemy team * 5%) of its max HP, capped at a maximum of 300% of its Magic Attack.',
		describe_th = 'ซูเปอร์สตาร์ชั่วร้ายยิงหนามพิษทั้งหมดบนร่างกายไปยังเป้าหมายศัตรูเดี่ยว ทำดาเมจ #C0xE69900#160% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# พร้อมทั้งฟื้นฟูส่วนที่บาดเจ็บของตัวเองอย่างรวดเร็ว: ฟื้นฟูพลังชีวิตเท่ากับ (5% + จำนวนเป้าหมายที่ติดพิษในทีมศัตรู * 5%) ของพลังชีวิตสูงสุดของตัวเอง โดยจำกัดไม่เกิน 300% ของพลังโจมตีเวทย์ของตัวเอง',
		describe_in = 'Bintang Jahat Super menembakkan semua duri beracun di tubuhnya ke arah satu target musuh, menyebabkan #C0xE69900#160% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, sekaligus bagian tubuh yang terluka cepat beregenerasi: memulihkan HP sebanyak (5% + jumlah target yang terkena racun di formasi musuh * 5%) dari HP maksimalnya, maksimal tidak melebihi 300% Serangan Sihir miliknya sendiri.',
		describe_ph = 'Ang Super Evil Star ay nagpapaputok ng lahat ng mga nakalalasong tinik sa kanyang katawan papunta sa iisang kalaban, na nagdudulot ng #C0xE69900#160% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Kasabay nito, mabilis na nagreregenerate ang mga nasirang bahagi ng sarili: nagpapagaling ng HP na katumbas ng (5% + bilang ng mga nabiktimang naipokson sa kalabang pangkat * 5%) ng kanyang maximum na HP, na hindi lalampas sa 300% ng kanyang Magic na Atake.',
		describe_ma = 'Bintang Jahat Super menembak semua duri beracun di tubuhnya ke arah satu sasaran musuh, menyebabkan #C0xE69900#160% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, sambil bahagian yang cedera pada dirinya pulih dengan cepat: memulihkan HP sebanyak (5% + bilangan sasaran yang terkena racun dalam barisan musuh * 5%) had maksimum HP sendiri, had maksimum tidak melebihi 300% Serangan Sihir dirinya sendiri.',
		describe = 'Super Evil Star shoots all the poisonous spikes on its body towards a single enemy target, dealing #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#. At the same time, the injured parts of itself rapidly regenerate: healing HP equal to (5% + number of poisoned targets in the enemy team * 5%) of its max HP, capped at a maximum of 300% of its Magic Attack.',
		simDesc_vn = 'Siêu Xấu sẽ bắn toàn bộ mũi độc trên cơ thể vào mục tiêu đơn lẻ của kẻ thù.',
		simDesc_en = 'The Super Villain will shoot all the poison spikes on its body at a single enemy target.',
		simDesc_th = 'ตัวร้ายสุดโหดจะยิงหนามพิษทั้งหมดบนร่างกายไปยังเป้าหมายศัตรูคนเดียว',
		simDesc_in = 'Penjahat Super akan menembakkan semua duri beracun di tubuhnya ke satu sasaran musuh.',
		simDesc_ph = 'Ang Super Villain ay magpaputok ng lahat ng mga lasong tinik sa katawan nito sa isang solong target na kaaway.',
