	[420012] = {
		id = 420012,
		skillName_vn = 'Đòn lớn của Lickitung',
		skillName_en = 'Lickitung\'s big hit',
		skillName_th = 'การโจมตีครั้งใหญ่ของลิคกิธัง',
		skillName_in = 'Serangan besar Lickitung',
		skillName_ph = 'Malaking suntok ni Lickitung',
		skillName_ma = 'Serangan besar Lickitung',
		skillName = 'Lickitung\'s big hit',
		describe_vn = 'Lưỡi Dài dùng lưỡi quất vào mục tiêu hàng ngang của đối phương, gây #C0xE69900#190% Công Vật Lý#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, có 40% xác suất [Tê Liệt] mục tiêu trong 1 lượt (Tê Liệt: hiệu ứng khống chế, không thể sử dụng kỹ năng đặc biệt), đồng thời hồi phục lượng máu bằng 15% giới hạn máu của bản thân, tối đa không vượt quá 800% Công Vật Lý của bản thân',
		describe_en = 'Long Tongue lashes horizontally at the enemy targets, dealing #C0xE69900#190% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#, with a 40% chance to [Paralyze] the targets for 1 turn (Paralyze: a control effect that prevents the use of special skills), while restoring HP equal to 15% of the user\'s max HP, up to a maximum of 800% of the user\'s Physical Attack.',
		describe_th = 'ลิ้นยาวใช้ลิ้นฟาดไปยังเป้าหมายในแถวที่อยู่แนวนอน ทำให้เกิดความเสียหายทางกายภาพ #C0xE69900#190%#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายกายภาพ#C0x5B545B# มีโอกาส 40% ที่จะ [เป็นอัมพาต] เป้าหมายเป็นเวลา 1 เทิร์น (อัมพาต: สถานะควบคุม ไม่สามารถใช้สกิลพิเศษได้) พร้อมฟื้นฟูพลังชีวิตเท่ากับ 15% ของพลังชีวิตสูงสุดของตัวเอง สูงสุดไม่เกิน 800% ของพลังโจมตีทางกายภาพของตัวเอง',
		describe_in = 'Lidah Panjang menggunakan lidahnya untuk memukul target secara horizontal, memberikan #C0xE69900#190% Serangan Fisik#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, dengan kemungkinan 40% untuk [Melumpuhkan] target selama 1 giliran (Melumpuhkan: efek kontrol yang mencegah penggunaan skill khusus), sekaligus memulihkan HP sebesar 15% dari batas maksimal HP pengguna, maksimal hingga 800% Serangan Fisik pengguna.',
		describe_ph = 'Mahabang Dila ang ginagamit ang kanyang dila para hampasin ang mga target nang pahalang, na nagdudulot ng #C0xE69900#190% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, may 40% na pagkakataon na [Maparalisa] ang mga target sa loob ng 1 turn (Maparalisa: epekto ng kontrol, hindi makagamit ng mga espesyal na kasanayan), kasabay nito ay nagpapa-recover ng HP ng 15% mula sa maximum HP ng sarili, hanggang maximum na 800% ng Pisikal na Atake ng sarili.',
		describe_ma = 'Lidah Panjang menggunakan lidahnya untuk menyepak sasaran secara mendatar, memberikan #C0xE69900#190% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, dengan peluang 40% untuk [Terencat] sasaran selama 1 giliran (Terencat: kesan kawalan, tidak dapat menggunakan kemahiran khas), sambil memulihkan HP sebanyak 15% daripada had maksimum HP sendiri, maksimum tidak melebihi 800% Serangan Fizikal sendiri.',
		describe = 'Long Tongue lashes horizontally at the enemy targets, dealing #C0xE69900#190% Physical Attack#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Physical Damage#C0x5B545B#, with a 40% chance to [Paralyze] the targets for 1 turn (Paralyze: a control effect that prevents the use of special skills), while restoring HP equal to 15% of the user\'s max HP, up to a maximum of 800% of the user\'s Physical Attack.',
		simDesc_vn = 'Lickitung dùng lưỡi quất vào mục tiêu đơn lẻ của đối phương, có khả năng làm tê liệt mục tiêu và hồi phục một phần sinh lực cho bản thân.',
		simDesc_en = 'Lickitung lashes its tongue at a single enemy target, with a chance to paralyze the target and restore some of its own HP.',
		simDesc_th = 'ลิคกิทังใช้ลิ้นฟาดเป้าหมายศัตรูหนึ่งตัว โดยมีโอกาสทำให้เป้าหมายนิ้วล็อกและฟื้นฟูพลังชีวิตบางส่วนให้กับตัวเอง',
		simDesc_in = 'Lickitung menggunakan lidahnya untuk menyambar satu target musuh, dengan kemungkinan membuat target lumpuh dan memulihkan sebagian HP dirinya sendiri.',
		simDesc_ph = 'Ginagamit ng Lickitung ang dila upang hampasin ang isang kalaban na target, na may kakayahang paralyzin ang target at magpagaling ng bahagi ng sarili nitong HP.',
		simDesc_ma = 'Lickitung menggunakan lidahnya untuk menyambar satu sasaran musuh, berkemungkinan menyebabkan sasaran lumpuh dan memulihkan sebahagian HP dirinya sendiri.',
		simDesc = 'Lickitung lashes its tongue at a single enemy target, with a chance to paralyze the target and restore some of its own HP.',
