	[800901] = {
		id = 800901,
		skillName_vn = 'Hắc Kiếm Lướt Bóng',
		skillName_en = 'Shadow Sword Dash',
		skillName_th = 'เงาดาบพุ่ง',
		skillName_in = 'Luncuran Pedang Bayangan',
		skillName_ph = 'Anino ng Tabak na Pagsalpok',
		skillName_ma = 'Luncur Pedang Bayangan',
		skillName = 'Shadow Sword Dash',
		describe_vn = 'Mihawk lướt tới như một cái bóng đen mờ ảo, Yoru rít gió trong không trung, tung cú chém sắc bén trực diện vào kẻ địch được chỉ định. Gây #C0xE69900#180% Công V.Lý#C0x5B545B# và thêm #C0xF13B54#+$(skillLevel424)$ Sát Thương Vật Lý#C0x5B545B# lên mục tiêu. Sau khi ra đòn, Mihawk tập trung tinh thần và giữ thế sẵn sàng, tăng #C0x3D8A99#15% Tỷ lệ Chí Mạng#C0x5B545B# trong 2 lượt, giúp các đòn đánh tiếp theo có khả năng chí mạng cao hơn.',
		describe_en = 'Mihawk dashes forward like a shadowy figure, Yoru slicing the air as he delivers a sharp direct slash to the designated enemy. Deals #C0xE69900#180% Physical Attack#C0x5B545B# plus #C0xF13B54#+$(skillLevel424)$#C0x5B545B# Physical Damage to the target. After the strike, Mihawk focuses his spirit and assumes a ready stance, increasing #C0x3D8A99#15% Critical Rate#C0x5B545B# for 2 turns, enhancing the chance of critical hits for subsequent attacks.',
		describe_th = 'มิฮอว์กพุ่งไปเหมือนเงามืดลึกลับ ดาบ Yoru กรีดอากาศ ส่งการฟันตรงไปยังศัตรูที่กำหนด สร้างความเสียหาย #C0xE69900#180% การโจมตีทางกายภาพ#C0x5B545B# และเพิ่ม #C0xF13B54#+$(skillLevel424)$#C0x5B545B# ความเสียหายกายภาพแก่เป้าหมาย หลังจากโจมตี มิฮอว์กมุ่งสมาธิและเตรียมพร้อม เพิ่ม #C0x3D8A99#15% อัตราคริติคอล#C0x5B545B# เป็นเวลา 2 เทิร์น เพิ่มโอกาสโจมตีคริติคอลในการโจมตีครั้งถัดไป',
		describe_in = 'Mihawk melesat seperti bayangan gelap, Yoru membelah udara saat ia melancarkan tebasan tajam langsung ke musuh yang dituju. Memberikan #C0xE69900#180% Serangan Fisik#C0x5B545B# dan tambahan #C0xF13B54#+$(skillLevel424)$#C0x5B545B# Kerusakan Fisik ke target. Setelah serangan, Mihawk memfokuskan semangatnya dan bersiap siaga, meningkatkan #C0x3D8A99#15% Tingkat Kritikal#C0x5B545B# selama 2 giliran, meningkatkan peluang serangan kritis pada serangan berikutnya.',
		describe_ph = 'Mihawk ay bumilis tulad ng isang aninong madilim, Yoru\'y gumigising sa hangin habang nagtataguyod ng matalim na direktang palo sa itinakdang kalaban. Nagdudulot ng #C0xE69900#180% Pisikal na Atake#C0x5B545B# at karagdagang #C0xF13B54#+$(skillLevel424)$#C0x5B545B# Pisikal na Pinsala sa target. Pagkatapos ng atake, Mihawk ay nagtuon ng kanyang espiritu at pumapasok sa handang posisyon, nagdaragdag ng #C0x3D8A99#15% Kritikal na Porsyento#C0x5B545B# sa loob ng 2 turn, nagpapataas ng tsansa ng kritikal na palo sa mga susunod na atake.',
		describe_ma = 'Mihawk meluncur seperti bayang gelap, Yoru menghiris udara semasa dia melancarkan serangan tepat ke musuh yang ditetapkan. Memberi #C0xE69900#180% Serangan Fizikal#C0x5B545B# dan tambahan #C0xF13B54#+$(skillLevel424)$#C0x5B545B# Kerosakan Fizikal ke sasaran. Selepas serangan, Mihawk menumpukan semangatnya dan bersedia, meningkatkan #C0x3D8A99#15% Kadar Kritikal#C0x5B545B# selama 2 pusingan, meningkatkan peluang serangan kritikal untuk serangan seterusnya.',
		describe = 'Mihawk dashes forward like a shadowy figure, Yoru slicing the air as he delivers a sharp direct slash to the designated enemy. Deals #C0xE69900#180% Physical Attack#C0x5B545B# plus #C0xF13B54#+$(skillLevel424)$#C0x5B545B# Physical Damage to the target. After the strike, Mihawk focuses his spirit and assumes a ready stance, increasing #C0x3D8A99#15% Critical Rate#C0x5B545B# for 2 turns, enhancing the chance of critical hits for subsequent attacks.',
		simDesc = 'Chém mục tiêu được chỉ định, gây sát thương vật lý và tăng chí mạng trong 2 lượt.',
		zawakeEffect = __data_t__zawakeEffect[800901],
		-- {79001}
		zawakeEffectDesc = 'Mihawk dashes forward like a shadowy blur, Yoru whistling through the air as he unleashes a sharp slash directly at the designated enemy. Deals #C0xE69900#180% Physical ATK#C0x5B545B# and an additional #C0xF13B54#+$(skillLevel424)$ Physical Damage#C0x5B545B# to the target. After striking, Mihawk focuses his spirit and holds a ready stance, increasing #C0x3D8A99#20% Critical Rate#C0x5B545B# for 2 turns, making subsequent attacks more likely to be critical.',
		zawakeEffectDesc_en = 'Mihawk dashes forward like a shadowy blur, Yoru whistling through the air as he unleashes a sharp slash directly at the designated enemy. Deals #C0xE69900#180% Physical ATK#C0x5B545B# and an additional #C0xF13B54#+$(skillLevel424)$ Physical Damage#C0x5B545B# to the target. After striking, Mihawk focuses his spirit and holds a ready stance, increasing #C0x3D8A99#20% Critical Rate#C0x5B545B# for 2 turns, making subsequent attacks more likely to be critical.',
		zawakeEffectDesc_th = 'Mihawk พุ่งไปข้างหน้าอย่างเงาลางเลือน ดาบ Yoru แหวกอากาศปลดปล่อยการฟันคมกริบใส่ศัตรูที่เลือก สร้างความเสียหาย #C0xE69900#180% พลังโจมตีกายภาพ#C0x5B545B# และเพิ่มอีก #C0xF13B54#+$(skillLevel424)$ ความเสียหายกายภาพ#C0x5B545B# แก่เป้าหมาย หลังจากโจมตี Mihawk จดจ่อจิตใจและเข้าสู่ท่าพร้อม เพิ่ม #C0x3D8A99#20% อัตราคริติคอล#C0x5B545B# เป็นเวลา 2 เทิร์น ทำให้การโจมตีถัดไปมีโอกาสคริติคอลสูงขึ้น',
		zawakeEffectDesc_in = 'Mihawk melesat ke depan seperti bayangan samar, Yoru mendesing di udara saat ia melancarkan tebasan tajam langsung ke musuh yang ditentukan. Memberikan #C0xE69900#180% ATK Fisik#C0x5B545B# dan tambahan #C0xF13B54#+$(skillLevel424)$ Damage Fisik#C0x5B545B# kepada target. Setelah menyerang, Mihawk memusatkan pikiran dan mengambil sikap siap, meningkatkan #C0x3D8A99#20% Peluang Crit#C0x5B545B# selama 2 giliran, membuat serangan berikutnya lebih berpeluang menjadi crit.',
		zawakeEffectDesc_ph = 'Mihawk ay mabilis na dumulas pasulong na parang anino, umuugong ang Yoru sa hangin habang ibinabagsak niya ang matalim na hiwa diretso sa napiling kalaban. Nagdudulot ng #C0xE69900#180% Physical ATK#C0x5B545B# at karagdagang #C0xF13B54#+$(skillLevel424)$ Physical Damage#C0x5B545B# sa target. Pagkatapos umatake, nagpo-focus si Mihawk at pumapasok sa handa na posisyon, tumataas ang #C0x3D8A99#20% Critical Rate#C0x5B545B# sa loob ng 2 turn, na nagbibigay ng mas mataas na tsansa ng critical sa mga susunod na atake.',
		zawakeEffectDesc_ma = 'Mihawk meluncur ke hadapan seperti bayangan samar, Yoru berdesing di udara sambil melepaskan tebasan tajam tepat ke musuh yang ditentukan. Memberikan #C0xE69900#180% ATK Fizikal#C0x5B545B# serta tambahan #C0xF13B54#+$(skillLevel424)$ Kerosakan Fizikal#C0x5B545B# kepada sasaran. Selepas menyerang, Mihawk menumpukan semangat dan bersedia dalam posisi siaga, meningkatkan #C0x3D8A99#20% Kadar Kritikal#C0x5B545B# selama 2 giliran, menjadikan serangan seterusnya lebih berpotensi kritikal.',
		zawakeEffectDesc_vn = 'Mihawk lướt tới như một cái bóng đen mờ ảo, Yoru rít gió trong không trung, tung cú chém sắc bén trực diện vào kẻ địch được chỉ định. Gây #C0xE69900#180% Công V.Lý#C0x5B545B# và thêm #C0xF13B54#+$(skillLevel424)$ Sát Thương Vật Lý#C0x5B545B# lên mục tiêu. Sau khi ra đòn, Mihawk tập trung tinh thần và giữ thế sẵn sàng, tăng #C0x3D8A99#20% Tỷ lệ Chí Mạng#C0x5B545B# trong 2 lượt, giúp các đòn đánh tiếp theo có khả năng chí mạng cao hơn.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Mihawk increases #C0x3D8A99#15% Critical Rate#C0x5B545B# for 2 turns. \n#F20# \n#F40##C0x5c9970#→ Mihawk increases #C0x3D8A99#20% Critical Rate#C0x5B545B#.',
		zawakeSimpleDesc_en = 'Mihawk increases #C0x3D8A99#15% Critical Rate#C0x5B545B# for 2 turns. \n#F20# \n#F40##C0x5c9970#→ Mihawk increases #C0x3D8A99#20% Critical Rate#C0x5B545B#.',
		zawakeSimpleDesc_th = 'Mihawk เพิ่ม #C0x3D8A99#15% อัตราคริติคอล#C0x5B545B# เป็นเวลา 2 เทิร์น \n#F20# \n#F40##C0x5c9970#→ Mihawk เพิ่ม #C0x3D8A99#20% อัตราคริติคอล#C0x5B545B#.',
		zawakeSimpleDesc_in = 'Mihawk meningkatkan #C0x3D8A99#15% Tingkat Kritis#C0x5B545B# selama 2 giliran. \n#F20# \n#F40##C0x5c9970#→ Mihawk meningkatkan #C0x3D8A99#20% Tingkat Kritis#C0x5B545B#.',
		zawakeSimpleDesc_ph = 'Mihawk tumataas ng #C0x3D8A99#15% Rate ng Kritikal#C0x5B545B# sa loob ng 2 na turn. \n#F20# \n#F40##C0x5c9970#→ Mihawk tumataas ng #C0x3D8A99#20% Rate ng Kritikal#C0x5B545B#.',
		zawakeSimpleDesc_ma = 'Mihawk meningkatkan #C0x3D8A99#15% Kadar Kritikal#C0x5B545B# selama 2 pusingan. \n#F20# \n#F40##C0x5c9970#→ Mihawk meningkatkan #C0x3D8A99#20% Kadar Kritikal#C0x5B545B#.',
		zawakeSimpleDesc_vn = ' Mihawk tăng #C0x3D8A99#15% Tỷ lệ Chí Mạng#C0x5B545B#, kéo dài 2 lượt.\n#F20# \n#F40##C0x5c9970#→  Mihawk tăng #C0x3D8A99#20% Tỷ lệ Chí Mạng#C0x5B545B#.',
		iconRes = 'battle/skill_icon/skill_80091.png',
