	[800902] = {
		id = 800902,
		skillName_vn = 'Hắc Kiếm Truy Sát',
		skillName_en = 'Shadow Sword Pursuit',
		skillName_th = 'เงาดาบไล่ล่า',
		skillName_in = 'Pengejaran Pedang Bayangan',
		skillName_ph = 'Pagsubaybay ng Anino ng Tabak',
		skillName_ma = 'Pengejaran Pedang Bayangan',
		skillName = 'Shadow Sword Pursuit',
		describe_vn = 'Mihawk bước tới như một cơn sóng đen ngầu, Yoru vung lên mở ra sát khí bức người, tạo áp lực khủng khiếp xé toạc kẻ địch được chỉ định. Gây #C0xE69900#580% Công V.Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel475)$ Sát Thương Vật Lý#C0x5B545B#. Nếu mục tiêu còn sống, Mihawk gây thêm sát thương thực bằng #C0xF13B54#50% lượng máu hiện tại#C0x5B545B# của mục tiêu đó (tối đa không vượt quá #C0xE69900#400% Công V.Lý#C0x5B545B# của bản thân), xuyên mọi phòng thủ. Cuối cùng, nạn nhân bị cấm hồi máu vĩnh viễn cho đến hết trận đấu.',
		describe_en = 'Mihawk advances like a dark, ominous wave, Yoru swinging with overwhelming killing intent, exerting immense pressure that tears through the designated enemy. Deals #C0xE69900#580% Physical Attack#C0x5B545B# plus #C0xF13B54#+$(skillLevel475)$#C0x5B545B# Physical Damage. If the target survives, Mihawk deals additional true damage equal to #C0xF13B54#50% of the target\'s current HP#C0x5B545B# (capped at #C0xE69900#400% of Mihawk\'s Physical Attack#C0x5B545B#), ignoring all defenses. Finally, the victim is permanently forbidden from healing for the remainder of the battle.',
		describe_th = 'มิฮอว์กก้าวไปเหมือนคลื่นดำมืด Yoru ฟันขึ้นด้วยแรงกดดันอันรุนแรง ทำลายศัตรูที่กำหนด สร้างความเสียหาย #C0xE69900#580% การโจมตีทางกายภาพ#C0x5B545B# และ #C0xF13B54#+$(skillLevel475)$#C0x5B545B# ความเสียหายทางกายภาพ หากเป้าหมายยังมีชีวิต มิฮอว์กจะสร้างความเสียหายจริงเพิ่มเติมเท่ากับ #C0xF13B54#50% ของ HP ปัจจุบันของเป้าหมาย#C0x5B545B# (สูงสุดไม่เกิน #C0xE69900#400% การโจมตีทางกายภาพ#C0x5B545B# ของตัวเอง) ข้ามการป้องกันทั้งหมด สุดท้าย เป้าหมายจะถูกห้ามฟื้นฟูเลือดถาวรจนจบการต่อสู้',
		describe_in = 'Mihawk maju seperti gelombang gelap, Yoru mengayun dengan niat membunuh yang luar biasa, menciptakan tekanan hebat yang merobek musuh yang dituju. Memberikan #C0xE69900#580% Serangan Fisik#C0x5B545B# dan #C0xF13B54#+$(skillLevel475)$#C0x5B545B# Kerusakan Fisik. Jika target masih hidup, Mihawk memberikan tambahan kerusakan nyata sebesar #C0xF13B54#50% dari HP saat ini target#C0x5B545B# (maksimum tidak melebihi #C0xE69900#400% Serangan Fisik#C0x5B545B# Mihawk), menembus semua pertahanan. Akhirnya, korban dilarang untuk pulih selamanya hingga akhir pertarungan.',
		describe_ph = 'Mihawk ay umaabante tulad ng isang madilim na alon, Yoru ay humahampas na may nakamamatay na intensyon, na lumilikha ng matinding presyon na sumisira sa itinakdang kalaban. Nagdudulot ng #C0xE69900#580% Pisikal na Atake#C0x5B545B# at #C0xF13B54#+$(skillLevel475)$#C0x5B545B# Pisikal na Pinsala. Kung ang target ay buhay pa, Mihawk ay nagdudulot ng karagdagang totoong pinsala na katumbas ng #C0xF13B54#50% ng kasalukuyang HP ng target#C0x5B545B# (hindi lalampas sa #C0xE69900#400% Pisikal na Atake#C0x5B545B# ni Mihawk), na tinataboy ang lahat ng depensa. Sa huli, ang biktima ay permanenteng ipinagbabawal na gumaling sa natitirang bahagi ng labanan.',
		describe_ma = 'Mihawk melangkah seperti gelombang gelap, Yoru menghayun dengan niat membunuh yang dahsyat, menghasilkan tekanan hebat yang merobek musuh yang ditetapkan. Memberi #C0xE69900#580% Serangan Fizikal#C0x5B545B# dan #C0xF13B54#+$(skillLevel475)$#C0x5B545B# Kerosakan Fizikal. Jika sasaran masih hidup, Mihawk memberikan kerosakan sebenar tambahan sebanyak #C0xF13B54#50% daripada HP semasa sasaran#C0x5B545B# (maksimum tidak melebihi #C0xE69900#400% Serangan Fizikal#C0x5B545B# Mihawk), menembusi semua pertahanan. Akhirnya, mangsa dilarang untuk pulih secara kekal sehingga akhir pertempuran.',
		describe = 'Mihawk advances like a dark, ominous wave, Yoru swinging with overwhelming killing intent, exerting immense pressure that tears through the designated enemy. Deals #C0xE69900#580% Physical Attack#C0x5B545B# plus #C0xF13B54#+$(skillLevel475)$#C0x5B545B# Physical Damage. If the target survives, Mihawk deals additional true damage equal to #C0xF13B54#50% of the target\'s current HP#C0x5B545B# (capped at #C0xE69900#400% of Mihawk\'s Physical Attack#C0x5B545B#), ignoring all defenses. Finally, the victim is permanently forbidden from healing for the remainder of the battle.',
		simDesc = 'Chém đơn mục tiêu cực mạnh, gây sát thương theo máu hiện tại và cấm hồi máu vĩnh viễn.',
		zawakeEffect = __data_t__zawakeEffect[800902],
		-- {79002}
		zawakeEffectDesc = 'Mihawk steps forward like a raging dark wave, Yoru swings unleashing a terrifying killing intent, tearing apart the designated enemy. Deals #C0xE69900#580% Physical ATK#C0x5B545B# and #C0xF13B54#+$(skillLevel475)$ Physical Damage#C0x5B545B#. If the target survives, Mihawk deals additional true damage equal to #C0xF13B54#50% of the target\'s current HP#C0x5B545B# (capped at #C0xE69900#400% Physical ATK#C0x5B545B# of his own), ignoring all defense, and increases his own #C0x3D8A99#Critical Damage by 15%#C0x5B545B# for 2 turns. Finally, the victim is permanently forbidden from healing for the rest of the battle.',
		zawakeEffectDesc_en = 'Mihawk steps forward like a raging dark wave, Yoru swings unleashing a terrifying killing intent, tearing apart the designated enemy. Deals #C0xE69900#580% Physical ATK#C0x5B545B# and #C0xF13B54#+$(skillLevel475)$ Physical Damage#C0x5B545B#. If the target survives, Mihawk deals additional true damage equal to #C0xF13B54#50% of the target\'s current HP#C0x5B545B# (capped at #C0xE69900#400% Physical ATK#C0x5B545B# of his own), ignoring all defense, and increases his own #C0x3D8A99#Critical Damage by 15%#C0x5B545B# for 2 turns. Finally, the victim is permanently forbidden from healing for the rest of the battle.',
		zawakeEffectDesc_th = 'Mihawk ก้าวไปข้างหน้าเหมือนคลื่นสีดำที่ปั่นป่วน Yoru ฟาดออกปลดปล่อยกลิ่นอายสังหารอันน่าหวาดกลัว ฉีกศัตรูที่กำหนดออกเป็นชิ้น สร้างความเสียหาย #C0xE69900#580% กายภาพ#C0x5B545B# และ #C0xF13B54#+$(skillLevel475)$ ความเสียหายกายภาพ#C0x5B545B# หากเป้าหมายยังมีชีวิต Mihawk จะสร้างความเสียหายจริงเพิ่มเติมเท่ากับ #C0xF13B54#50% ของ HP ปัจจุบันของเป้าหมาย#C0x5B545B# (สูงสุดไม่เกิน #C0xE69900#400% กายภาพ#C0x5B545B# ของตัวเอง) ทะลวงการป้องกันทั้งหมด และเพิ่ม #C0x3D8A99#คริแดเมจ 15%#C0x5B545B# ของตัวเองเป็นเวลา 2 เทิร์น สุดท้ายเป้าหมายจะถูกห้ามฟื้นฟูอย่างถาวรจนจบการต่อสู้',
		zawakeEffectDesc_in = 'Mihawk melangkah maju seperti gelombang hitam yang mengamuk, Yoru diayunkan melepaskan aura pembunuh yang menakutkan, merobek musuh yang ditunjuk. Memberikan #C0xE69900#580% ATK Fisik#C0x5B545B# dan #C0xF13B54#+$(skillLevel475)$ Damage Fisik#C0x5B545B#. Jika target masih hidup, Mihawk memberikan tambahan True Damage sebesar #C0xF13B54#50% HP saat ini target#C0x5B545B# (maksimal tidak melebihi #C0xE69900#400% ATK Fisik#C0x5B545B# miliknya), menembus semua pertahanan, dan meningkatkan #C0x3D8A99#Critical Damage sebesar 15%#C0x5B545B# untuk dirinya selama 2 giliran. Akhirnya, korban dilarang memulihkan HP secara permanen hingga akhir pertarungan.',
		zawakeEffectDesc_ph = 'Mihawk ay sumusugod na parang nagngangalit na alon ng kadiliman, iwinawasiwas ang Yoru na nagpapakawala ng nakakatakot na pwersa ng pagpatay, pinupunit ang itinakdang kalaban. Nagdudulot ng #C0xE69900#580% Pisikal na ATK#C0x5B545B# at #C0xF13B54#+$(skillLevel475)$ Pisikal na Pinsala#C0x5B545B#. Kung buhay pa ang target, magdudulot si Mihawk ng karagdagang totoong pinsala katumbas ng #C0xF13B54#50% ng kasalukuyang HP ng target#C0x5B545B# (hindi lalampas sa #C0xE69900#400% Pisikal na ATK#C0x5B545B# ng sarili niya), binabalewala ang lahat ng depensa, at pinapataas ang #C0x3D8A99#Critical Damage ng 15%#C0x5B545B# sa loob ng 2 turn. Sa huli, ang biktima ay permanenteng ipinagbabawal na magpagaling hanggang matapos ang laban.',
		zawakeEffectDesc_ma = 'Mihawk melangkah ke hadapan seperti ombak hitam yang mengganas, Yoru dihayunkan melepaskan aura pembunuhan yang menakutkan, mengoyakkan musuh yang ditentukan. Menyebabkan #C0xE69900#580% ATK Fizikal#C0x5B545B# dan #C0xF13B54#+$(skillLevel475)$ Damage Fizikal#C0x5B545B#. Jika sasaran masih hidup, Mihawk memberikan tambahan True Damage sebanyak #C0xF13B54#50% HP semasa sasaran#C0x5B545B# (maksimum tidak melebihi #C0xE69900#400% ATK Fizikal#C0x5B545B# dirinya), menembusi semua pertahanan, dan meningkatkan #C0x3D8A99#Critical Damage sebanyak 15%#C0x5B545B# kepada dirinya selama 2 giliran. Akhirnya, mangsa diharamkan memulihkan HP secara kekal sehingga tamat perlawanan.',
		zawakeEffectDesc_vn = 'Mihawk bước tới như một cơn sóng đen ngầu, Yoru vung lên mở ra sát khí bức người, tạo áp lực khủng khiếp xé toạc kẻ địch được chỉ định. Gây #C0xE69900#580% Công V.Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel475)$ Sát Thương Vật Lý#C0x5B545B#. Nếu mục tiêu còn sống, Mihawk gây thêm sát thương thực bằng #C0xF13B54#50% lượng máu hiện tại#C0x5B545B# của mục tiêu đó (tối đa không vượt quá #C0xE69900#400% Công V.Lý#C0x5B545B# của bản thân), xuyên mọi phòng thủ, tăng #C0x3D8A99#15% Sát Thương Chí Mạng#C0x5B545B# cho bản thân trong 2 lượt. Cuối cùng, nạn nhân bị cấm hồi máu vĩnh viễn cho đến hết trận đấu.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'The legendary sword Yoru pierces through the enemy, Mihawk gains #C0x3D8A99#15% Critical Damage#C0x5B545B# for 2 turns.',
		zawakeSimpleDesc_en = 'The legendary sword Yoru pierces through the enemy, Mihawk gains #C0x3D8A99#15% Critical Damage#C0x5B545B# for 2 turns.',
		zawakeSimpleDesc_th = 'ดาบในตำนาน Yoru ฟันทะลุศัตรู Mihawk ได้รับ #C0x3D8A99#15% ความเสียหายคริติคอล#C0x5B545B# เป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Pedang legendaris Yoru menembus musuh, Mihawk mendapatkan #C0x3D8A99#15% Damage Kritikal#C0x5B545B# selama 2 giliran.',
		zawakeSimpleDesc_ph = 'Ang maalamat na espada na Yoru ay tumatagos sa kaaway, Mihawk ay tumataas ng #C0x3D8A99#15% Kritikal na Sakit#C0x5B545B# sa loob ng 2 turn.',
		zawakeSimpleDesc_ma = 'Pedang lagenda Yoru menebusi musuh, Mihawk mendapat #C0x3D8A99#15% Kerosakan Kritikal#C0x5B545B# selama 2 pusingan.',
		zawakeSimpleDesc_vn = 'Chém xuyên cơ thể của kẻ thù thanh kiếm thần thoại Yoru được tăng cường sức mạnh, Mihawk được tăng #C0x3D8A99#15% Sát thương chí mạng#C0x5B545B# trong 2 lượt',
		iconRes = 'battle/skill_icon/skill_80092.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 1,
		skillNatureType = 16,
		cdRound = 2,
