	[800903] = {
		id = 800903,
		skillName_vn = 'Thiên Trảm Hắc Kiếm',
		skillName_en = 'Heavenly Slash Shadow Sword',
		skillName_th = 'ฟันสวรรค์เงาดาบ',
		skillName_in = 'Pedang Bayangan Tebasan Surgawi',
		skillName_ph = 'Langit na Hataw ng Anino ng Tabak',
		skillName_ma = 'Pedang Bayangan Tebasan Syurga',
		skillName = 'Heavenly Slash Shadow Sword',
		describe_vn = 'Mihawk tung ba nhát chém liên hoàn bằng Yoru, cắt thẳng qua hàng dọc của kẻ địch với tốc độ vượt xa thị giác con người. Mỗi nhát gây #C0xE69900#220% Công V.Lý#C0x5B545B# và thêm #C0xF13B54#+$(skillLevel430)$ Sát Thương Vật Lý#C0x5B545B# lên toàn bộ kẻ địch trong hàng. Nếu ba nhát đều trúng, mục tiêu hứng chịu tổng cộng đến #C0xE69900#660% Công V.Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel490)$ sát thương vật lý#C0x5B545B# – đủ để xé toạc bất kỳ tuyến thủ nào. Kích hoạt hiệu ứng tàn khốc: Nếu một mục tiêu trong hàng bị hạ gục trong chuỗi chém, Mihawk lập tức hồi #C0x3D8A99#20% Nộ#C0x5B545B# và tăng #C0x3D8A99#15% Tốc Độ#C0x5B545B# trong 1 lượt, sẵn sàng cho đòn kế tiếp.',
		describe_en = 'Mihawk unleashes three consecutive slashes with Yoru, cutting straight through the enemy\'s column at a speed beyond human sight. Each strike deals #C0xE69900#220% Physical Attack#C0x5B545B# plus #C0xF13B54#+$(skillLevel430)$ Physical Damage#C0x5B545B# to all enemies in the row. If all three strikes hit, the target suffers a total of #C0xE69900#660% Physical Attack#C0x5B545B# plus #C0xF13B54#+$(skillLevel490)$ Physical Damage#C0x5B545B# – enough to tear through any defense line. Activates a brutal effect: if a target in the row is defeated during the slash chain, Mihawk instantly recovers #C0x3D8A99#20% Rage#C0x5B545B# and gains #C0x3D8A99#15% Speed#C0x5B545B# for 1 turn, ready for the next strike.',
		describe_th = 'มิฮอว์กปล่อยการฟันต่อเนื่องสามครั้งด้วย Yoru, ตัดตรงผ่านแถวศัตรูด้วยความเร็วเกินกว่าสายตามนุษย์ แต่ละครั้งสร้างความเสียหาย #C0xE69900#220% การโจมตีทางกายภาพ#C0x5B545B# และ #C0xF13B54#+$(skillLevel430)$ ความเสียหายทางกายภาพ#C0x5B545B# ไปยังศัตรูทั้งหมดในแถว หากทั้งสามฟันโดนเป้าหมาย ศัตรูจะได้รับความเสียหายรวมถึง #C0xE69900#660% การโจมตีทางกายภาพ#C0x5B545B# และ #C0xF13B54#+$(skillLevel490)$ ความเสียหายทางกายภาพ#C0x5B545B# – เพียงพอที่จะฉีกแนวป้องกันใด ๆ เปิดใช้งานเอฟเฟกต์โหดร้าย: หากเป้าหมายในแถวถูกกำจัดในขณะฟันต่อเนื่อง มิฮอว์กจะฟื้น #C0x3D8A99#20% โกรธ#C0x5B545B# และเพิ่ม #C0x3D8A99#15% ความเร็ว#C0x5B545B# เป็นเวลา 1 เทิร์น พร้อมสำหรับการโจมตีครั้งต่อไป',
		describe_in = 'Mihawk melancarkan tiga tebasan berturut-turut dengan Yoru, memotong lurus melalui barisan musuh dengan kecepatan melebihi penglihatan manusia. Setiap tebasan memberikan #C0xE69900#220% Serangan Fisik#C0x5B545B# dan #C0xF13B54#+$(skillLevel430)$ Kerusakan Fisik#C0x5B545B# ke semua musuh dalam barisan. Jika ketiga tebasan mengenai, target menerima total #C0xE69900#660% Serangan Fisik#C0x5B545B# dan #C0xF13B54#+$(skillLevel490)$ Kerusakan Fisik#C0x5B545B# – cukup untuk merobek setiap garis pertahanan. Mengaktifkan efek brutal: jika target dalam barisan dikalahkan selama rantai tebasan, Mihawk langsung memulihkan #C0x3D8A99#20% Amarah#C0x5B545B# dan memperoleh #C0x3D8A99#15% Kecepatan#C0x5B545B# selama 1 giliran, siap untuk serangan berikutnya.',
		describe_ph = 'Mihawk ay naglabas ng tatlong sunod-sunod na hiwa gamit ang Yoru, direktang tumatagos sa hilera ng kalaban sa bilis na lampas sa paningin ng tao. Bawat hiwa ay nagdudulot ng #C0xE69900#220% Pisikal na Atake#C0x5B545B# at #C0xF13B54#+$(skillLevel430)$ Pisikal na Pinsala#C0x5B545B# sa lahat ng kalaban sa hilera. Kung lahat ng tatlong hiwa ay tumama, ang target ay tumatanggap ng kabuuang #C0xE69900#660% Pisikal na Atake#C0x5B545B# at #C0xF13B54#+$(skillLevel490)$ Pisikal na Pinsala#C0x5B545B# – sapat upang punitin ang anumang linya ng depensa. Nag-aaktibo ng malupit na epekto: kung ang isang target sa hilera ay mapapatay sa chain ng hiwa, Mihawk ay agad na bumabalik ng #C0x3D8A99#20% Galit#C0x5B545B# at nakakakuha ng #C0x3D8A99#15% Bilis#C0x5B545B# sa loob ng 1 turn, handa para sa susunod na atake.',
		describe_ma = 'Mihawk melancarkan tiga serangan berturut-turut dengan Yoru, memotong lurus melalui barisan musuh dengan kelajuan melebihi penglihatan manusia. Setiap serangan memberikan #C0xE69900#220% Serangan Fizikal#C0x5B545B# dan #C0xF13B54#+$(skillLevel430)$ Kerosakan Fizikal#C0x5B545B# kepada semua musuh dalam barisan. Jika ketiga serangan mengenai, sasaran menerima jumlah keseluruhan #C0xE69900#660% Serangan Fizikal#C0x5B545B# dan #C0xF13B54#+$(skillLevel490)$ Kerosakan Fizikal#C0x5B545B# – cukup untuk merobek mana-mana garis pertahanan. Mengaktifkan kesan brutal: jika sasaran dalam barisan dikalahkan semasa rantaian serangan, Mihawk segera memulihkan #C0x3D8A99#20% Marah#C0x5B545B# dan memperoleh #C0x3D8A99#15% Kelajuan#C0x5B545B# selama 1 pusingan, bersedia untuk serangan seterusnya.',
		describe = 'Mihawk unleashes three consecutive slashes with Yoru, cutting straight through the enemy\'s column at a speed beyond human sight. Each strike deals #C0xE69900#220% Physical Attack#C0x5B545B# plus #C0xF13B54#+$(skillLevel430)$ Physical Damage#C0x5B545B# to all enemies in the row. If all three strikes hit, the target suffers a total of #C0xE69900#660% Physical Attack#C0x5B545B# plus #C0xF13B54#+$(skillLevel490)$ Physical Damage#C0x5B545B# – enough to tear through any defense line. Activates a brutal effect: if a target in the row is defeated during the slash chain, Mihawk instantly recovers #C0x3D8A99#20% Rage#C0x5B545B# and gains #C0x3D8A99#15% Speed#C0x5B545B# for 1 turn, ready for the next strike.',
		simDesc = 'Mihawk tung ba nhát chém liên hoàn bằng Yoru, mỗi nhát sắc bén và nhanh đến mức không thể nhìn thấy bằng mắt thường, cắt dọc theo đội hình kẻ địch. Mỗi nhát gây 220% Công V.Lý và Sát Thương Vật Lý lên toàn bộ mục tiêu trong hàng dọc, tạo thành làn sóng sát thương chồng lấp. Nếu cả ba nhát trúng, mỗi mục tiêu trong hàng có thể chịu đến 660% Công V.Lý – một lượng sát thương khủng khiếp có thể quét sạch cả hàng phòng thủ. Hiệu ứng phụ: Nếu bất kỳ mục tiêu nào trong hàng dọc bị hạ gục, Mihawk lập tức: Hồi 20% Nộ, Tăng 15% Tốc Độ trong 1 lượt, sẵn sàng chuyển sang mục tiêu kế tiếp với tốc độ còn nhanh hơn.',
		starEffect = __data_t__starEffect[800903],
		-- {11}
		starEffectDesc_vn = 'Ngay khi tung kỹ năng, Mihawk sử dụng uy lực từ nhát chém siêu tốc để áp chế phòng ngự của kẻ địch: Giảm 30% Giáp của toàn bộ mục tiêu bị trúng đòn. Hiệu ứng này kéo dài 2 lượt, khiến kẻ địch nhận sát thương vật lý cao hơn trong thời gian bị giảm giáp. Tăng 15% Giáp cho bản thân Mihawk, kéo dài 2 lượt.',
		starEffectDesc = 'Immediately upon casting the skill, Mihawk unleashes the power of a supersonic slash to suppress the enemy’s defense: Reduces the Armor of all hit targets by 30%. This effect lasts for 2 turns, causing enemies to take increased Physical Damage while their Armor is reduced. Mihawk also gains 15% Armor for himself, lasting 2 turns.',
		starEffectDesc_en = 'Immediately upon casting the skill, Mihawk unleashes the power of a supersonic slash to suppress the enemy’s defense: Reduces the Armor of all hit targets by 30%. This effect lasts for 2 turns, causing enemies to take increased Physical Damage while their Armor is reduced. Mihawk also gains 15% Armor for himself, lasting 2 turns.',
		starEffectDesc_th = 'ทันทีที่ใช้สกิล Mihawk ปล่อยพลังจากการฟันความเร็วเหนือเสียงเพื่อกดดันการป้องกันของศัตรู: ลดเกราะของเป้าหมายทั้งหมดที่โดนโจมตีลง 30% เอฟเฟกต์นี้คงอยู่ 2 เทิร์น ทำให้ศัตรูได้รับความเสียหายกายภาพมากขึ้นในช่วงที่เกราะลดลง Mihawk ยังได้รับเกราะเพิ่มขึ้น 15% เป็นเวลา 2 เทิร์น',
		starEffectDesc_in = 'Segera setelah menggunakan skill, Mihawk melepaskan kekuatan dari tebasan super cepat untuk menekan pertahanan musuh: Mengurangi Armor semua target yang terkena sebesar 30%. Efek ini berlangsung selama 2 giliran, membuat musuh menerima lebih banyak Damage Fisik saat Armor mereka berkurang. Mihawk juga mendapatkan 15% Armor untuk dirinya sendiri selama 2 giliran.',
		starEffectDesc_ph = 'Agad matapos gamitin ang kakayahan, pinakawalan ni Mihawk ang kapangyarihan ng isang supersonic slash upang supilin ang depensa ng kalaban: Binabawasan ang Armor ng lahat ng target na tinamaan ng 30%. Tumagal ito ng 2 turn, na nagiging sanhi ng mas mataas na pagtanggap ng Physical Damage ng mga kalaban habang nabawasan ang kanilang Armor. Si Mihawk ay nakakatanggap din ng 15% Armor para sa kanyang sarili sa loob ng 2 turn.',
		starEffectDesc_ma = 'Sebaik sahaja menggunakan kemahiran, Mihawk melepaskan kuasa daripada tebasan supersonik untuk menekan pertahanan musuh: Mengurangkan Armor semua sasaran yang terkena sebanyak 30%. Kesan ini berlangsung selama 2 giliran, menyebabkan musuh menerima lebih banyak Damage Fizikal semasa Armor mereka berkurang. Mihawk juga mendapat 15% Armor untuk dirinya sendiri selama 2 giliran.',
		zawakeEffect = __data_t__zawakeEffect[800903],
		-- {79003, 1}
		zawakeEffectDesc = 'Immediately upon unleashing the skill, Mihawk uses the force of his ultra-fast slash to suppress enemy defenses: Reduces 40% Armor of all affected targets. This effect lasts for 2 turns, causing enemies to take more physical damage while their armor is reduced. Increases Mihawk\'s own Armor by 15% for 2 turns.',
		zawakeEffectDesc_en = 'Immediately upon unleashing the skill, Mihawk uses the force of his ultra-fast slash to suppress enemy defenses: Reduces 40% Armor of all affected targets. This effect lasts for 2 turns, causing enemies to take more physical damage while their armor is reduced. Increases Mihawk\'s own Armor by 15% for 2 turns.',
		zawakeEffectDesc_th = 'ทันทีที่ใช้สกิล Mihawk ใช้พลังจากการฟันความเร็วสูงสุดเพื่อกดดันการป้องกันของศัตรู: ลดเกราะของเป้าหมายที่โดนทั้งหมด 40% เอฟเฟกต์นี้คงอยู่ 2 เทิร์น ทำให้ศัตรูได้รับความเสียหายกายภาพมากขึ้นในระหว่างที่เกราะลดลง เพิ่มเกราะของ Mihawk เอง 15% เป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Segera setelah mengeluarkan skill, Mihawk menggunakan kekuatan dari tebasan super cepatnya untuk menekan pertahanan musuh: Mengurangi 40% Armor dari semua target yang terkena. Efek ini berlangsung selama 2 giliran, membuat musuh menerima lebih banyak damage fisik saat armor mereka berkurang. Meningkatkan Armor Mihawk sendiri sebesar 15% selama 2 giliran.',
		zawakeEffectDesc_ph = 'Pagkatapos gamitin ang kasanayan, ginamit ni Mihawk ang lakas ng kanyang sobrang bilis na tebas upang supilin ang depensa ng kalaban: Binabawasan ng 40% ang Armor ng lahat ng target na tinamaan. Tumagal ito ng 2 turn, dahilan upang makatanggap ang mga kalaban ng mas mataas na physical damage habang mababa ang kanilang armor. Tumataas ang Armor ni Mihawk ng 15% sa loob ng 2 turn.',
		zawakeEffectDesc_ma = 'Sebaik sahaja menggunakan kemahiran, Mihawk menggunakan kuasa daripada tebasan super pantasnya untuk menekan pertahanan musuh: Mengurangkan 40% Armor bagi semua sasaran yang terkena. Kesan ini bertahan selama 2 giliran, menyebabkan musuh menerima lebih banyak kerosakan fizikal ketika armor mereka berkurang. Meningkatkan Armor Mihawk sendiri sebanyak 15% selama 2 giliran.',
		zawakeEffectDesc_vn = 'Ngay khi tung kỹ năng, Mihawk sử dụng uy lực từ nhát chém siêu tốc để áp chế phòng ngự của kẻ địch: Giảm 40% Giáp của toàn bộ mục tiêu bị trúng đòn. Hiệu ứng này kéo dài 2 lượt, khiến kẻ địch nhận sát thương vật lý cao hơn trong thời gian bị giảm giáp. Tăng 15% Giáp cho bản thân Mihawk, kéo dài 2 lượt.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Upon activating the skill, Mihawk uses the force of his ultra-fast slash to suppress the enemy\'s defense: Reduces the Armor of all targets hit by 40%. This effect lasts 2 turns, causing enemies to take increased physical damage while their Armor is reduced.',
		zawakeSimpleDesc_en = 'Upon activating the skill, Mihawk uses the force of his ultra-fast slash to suppress the enemy\'s defense: Reduces the Armor of all targets hit by 40%. This effect lasts 2 turns, causing enemies to take increased physical damage while their Armor is reduced.',
		zawakeSimpleDesc_th = 'ทันทีที่ใช้สกิล Mihawk ใช้พลังจากการฟันอันรวดเร็วเพื่อกดดันการป้องกันของศัตรู: ลดเกราะของเป้าหมายทั้งหมดที่ถูกโจมตีลง 40% เอฟเฟกต์นี้อยู่ได้นาน 2 เทิร์น ทำให้ศัตรูได้รับความเสียหายทางกายภาพมากขึ้นในช่วงที่เกราะลดลง',
		zawakeSimpleDesc_in = 'Saat mengaktifkan skill, Mihawk menggunakan kekuatan dari tebasan super cepatnya untuk menekan pertahanan musuh: Mengurangi Armor semua target yang terkena sebesar 40%. Efek ini bertahan selama 2 giliran, menyebabkan musuh menerima lebih banyak damage fisik saat Armor mereka berkurang.',
		zawakeSimpleDesc_ph = 'Sa pag-activate ng kakayahan, ginagamit ni Mihawk ang lakas mula sa napakabilis na palo upang supilin ang depensa ng kalaban: Binabawasan ang Armor ng lahat ng target na tinamaan ng 40%. Ang epekto ay tumatagal ng 2 turn, na nagiging dahilan upang tumanggap ang mga kalaban ng mas mataas na pisikal na pinsala habang nababawasan ang kanilang Armor.',
		zawakeSimpleDesc_ma = 'Apabila mengaktifkan kemahiran, Mihawk menggunakan kuasa dari tebasan super pantasnya untuk menekan pertahanan musuh: Mengurangkan Armor semua sasaran yang terkena sebanyak 40%. Kesan ini bertahan selama 2 pusingan, menyebabkan musuh menerima lebih banyak kerosakan fizikal sementara Armor mereka berkurang.',
		zawakeSimpleDesc_vn = ' Ngay khi tung kỹ năng, Mihawk sử dụng uy lực từ nhát chém siêu tốc để áp chế phòng ngự của kẻ địch: Giảm 30% Giáp của toàn bộ mục tiêu bị trúng đòn. Hiệu ứng này kéo dài 2 lượt, khiến kẻ địch nhận sát thương vật lý cao hơn trong thời gian bị giảm giáp. \n#F20# \n#F40##C0x5c9970#→ Ngay khi tung kỹ năng, Mihawk sử dụng uy lực từ nhát chém siêu tốc để áp chế phòng ngự của kẻ địch: Giảm 40% Giáp của toàn bộ mục tiêu bị trúng đòn. Hiệu ứng này kéo dài 2 lượt, khiến kẻ địch nhận sát thương vật lý cao hơn trong thời gian bị giảm giáp.',
		iconRes = 'battle/skill_icon/skill_80093.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 2,
		skillNatureType = 12,
