	[800904] = {
		id = 800904,
		skillName_vn = 'Kiếm Vương Tối Thượng',
		skillName_en = 'Supreme Sword King',
		skillName_th = 'ราชาดาบสูงสุด',
		skillName_in = 'Raja Pedang Tertinggi',
		skillName_ph = 'Pinakamataas na Hari ng Tabak',
		skillName_ma = 'Raja Pedang Tertinggi',
		skillName = 'Supreme Sword King',
		describe_vn = 'Mihawk bước vào trận với uy thế áp đảo của một Kiếm Vương tối thượng. Trong 2 lượt đầu trận: Mihawk được tăng #C0x3D8A99#15% Tỷ lệ Chí Mạng#C0x5B545B# và #C0x3D8A99#10% Sát Thương Kỹ Năng#C0x5B545B#, củng cố thế công từ sớm. Mỗi đòn đánh cơ bản có #C0xF13B54#25%#C0x5B545B# xác suất gây thêm sát thương chuẩn bằng 5% Máu Tối Đa của mục tiêu — bỏ qua mọi phòng thủ, gây áp lực liên tục ngay cả khi không tung kỹ năng. Mỗi khi Mihawk hạ gục mục tiêu bằng kỹ năng chủ động, anh ta nhận hiệu ứng <Bá Khí Kiếm Vương> trong 2 lượt, tăng: #C0xF13B54#15% Tổng Sát Thương Gây Ra#C0x5B545B#, #C0x3D8A99#10% Tốc Độ#C0x5B545B#. Hiệu ứng này có thể cộng dồn tối đa 2 lần, biến Mihawk thành cơn ác mộng càng về sau càng nhanh và chí tử hơn.',
		describe_en = 'Mihawk enters the battle with the overwhelming presence of a Supreme Sword King. During the first 2 turns: Mihawk gains #C0x3D8A99#15% Critical Rate#C0x5B545B# and #C0x3D8A99#10% Skill Damage#C0x5B545B#, reinforcing his offense early on. Each basic attack has a #C0xF13B54#25%#C0x5B545B# chance to deal additional true damage equal to 5% of the target\'s Max HP — ignoring all defenses, applying constant pressure even without using skills. Whenever Mihawk defeats a target with an active skill, he gains the effect <Sword King’s Dominance> for 2 turns, increasing: #C0xF13B54#15% Total Damage Dealt#C0x5B545B#, #C0x3D8A99#10% Speed#C0x5B545B#. This effect can stack up to 2 times, turning Mihawk into an increasingly lethal and rapid nightmare.',
		describe_th = 'มิฮอว์กเข้าสู่สนามรบด้วยอำนาจเหนือกว่าของราชาแห่งดาบสูงสุด ใน 2 เทิร์นแรก: มิฮอว์กได้รับการเพิ่ม #C0x3D8A99#15% อัตราคริติคอล#C0x5B545B# และ #C0x3D8A99#10% ความเสียหายสกิล#C0x5B545B# เสริมความแข็งแกร่งให้การโจมตีตั้งแต่ต้น ทุกการโจมตีพื้นฐานมี #C0xF13B54#25%#C0x5B545B# โอกาสสร้างความเสียหายจริงเพิ่มอีกเท่ากับ 5% ของ HP สูงสุดของเป้าหมาย — ข้ามทุกการป้องกัน สร้างแรงกดดันต่อเนื่องแม้ไม่ใช้สกิล เมื่อใดก็ตามที่มิฮอว์กกำจัดเป้าหมายด้วยสกิลใช้งาน เขาจะได้รับเอฟเฟกต์ <อำนาจราชาดาบ> เป็นเวลา 2 เทิร์น เพิ่ม: #C0xF13B54#15% ความเสียหายรวมที่สร้าง#C0x5B545B#, #C0x3D8A99#10% ความเร็ว#C0x5B545B#. เอฟเฟกต์นี้สามารถสะสมได้สูงสุด 2 ครั้ง ทำให้มิฮอว์กกลายเป็นฝันร้ายที่รุนแรงและรวดเร็วขึ้นเรื่อย ๆ',
		describe_in = 'Mihawk memasuki pertempuran dengan kehadiran yang luar biasa sebagai Raja Pedang Tertinggi. Selama 2 giliran pertama: Mihawk mendapatkan #C0x3D8A99#15% Tingkat Kritis#C0x5B545B# dan #C0x3D8A99#10% Kerusakan Keterampilan#C0x5B545B#, memperkuat serangan sejak awal. Setiap serangan dasar memiliki #C0xF13B54#25%#C0x5B545B# peluang untuk memberikan tambahan damage sejati sebesar 5% dari HP Maks target — mengabaikan semua pertahanan, memberikan tekanan terus-menerus bahkan tanpa menggunakan skill. Setiap kali Mihawk mengalahkan target dengan skill aktif, ia memperoleh efek <Dominasi Raja Pedang> selama 2 giliran, meningkatkan: #C0xF13B54#15% Total Damage#C0x5B545B#, #C0x3D8A99#10% Kecepatan#C0x5B545B#. Efek ini dapat menumpuk hingga 2 kali, menjadikan Mihawk mimpi buruk yang semakin cepat dan mematikan.',
		describe_ph = 'Mihawk ay pumapasok sa labanan na may nakamamanghang presensya ng isang Pinakamataas na Hari ng Espada. Sa unang 2 turn: Mihawk ay nakakakuha ng #C0x3D8A99#15% Critical Rate#C0x5B545B# at #C0x3D8A99#10% Skill Damage#C0x5B545B#, pinapalakas ang kanyang opensa mula sa simula. Bawat basic attack ay may #C0xF13B54#25%#C0x5B545B# tsansa na magdulot ng karagdagang true damage na katumbas ng 5% ng Max HP ng target — nilalampasan ang lahat ng depensa, nagpapanatili ng tuloy-tuloy na pressure kahit hindi gumagamit ng skill. Sa tuwing Mihawk ay nakapatay ng target gamit ang active skill, nakakakuha siya ng epekto <Sword King’s Dominance> sa loob ng 2 turn, nagpapataas ng: #C0xF13B54#15% Total Damage Dealt#C0x5B545B#, #C0x3D8A99#10% Speed#C0x5B545B#. Ang epekto na ito ay maaaring ma-stack hanggang 2 beses, ginagawang Mihawk isang lumalakas na nakamamatay na bangungot.',
		describe_ma = 'Mihawk memasuki pertempuran dengan kehadiran yang mengatasi sebagai Raja Pedang Tertinggi. Dalam 2 pusingan pertama: Mihawk memperoleh #C0x3D8A99#15% Kadar Kritikal#C0x5B545B# dan #C0x3D8A99#10% Kerosakan Kemahiran#C0x5B545B#, mengukuhkan serangan awal. Setiap serangan asas mempunyai #C0xF13B54#25%#C0x5B545B# peluang untuk memberikan kerosakan sebenar tambahan bersamaan 5% HP Maks sasaran — mengabaikan semua pertahanan, mengekalkan tekanan walaupun tanpa menggunakan kemahiran. Setiap kali Mihawk mengalahkan sasaran dengan kemahiran aktif, dia menerima kesan <Dominasi Raja Pedang> selama 2 pusingan, meningkatkan: #C0xF13B54#15% Jumlah Kerosakan#C0x5B545B#, #C0x3D8A99#10% Kelajuan#C0x5B545B#. Kesan ini boleh bertimbun sehingga 2 kali, menjadikan Mihawk mimpi ngeri yang semakin pantas dan mematikan.',
		describe = 'Mihawk enters the battle with the overwhelming presence of a Supreme Sword King. During the first 2 turns: Mihawk gains #C0x3D8A99#15% Critical Rate#C0x5B545B# and #C0x3D8A99#10% Skill Damage#C0x5B545B#, reinforcing his offense early on. Each basic attack has a #C0xF13B54#25%#C0x5B545B# chance to deal additional true damage equal to 5% of the target\'s Max HP — ignoring all defenses, applying constant pressure even without using skills. Whenever Mihawk defeats a target with an active skill, he gains the effect <Sword King’s Dominance> for 2 turns, increasing: #C0xF13B54#15% Total Damage Dealt#C0x5B545B#, #C0x3D8A99#10% Speed#C0x5B545B#. This effect can stack up to 2 times, turning Mihawk into an increasingly lethal and rapid nightmare.',
		simDesc = 'Tăng sát thương và chí mạng đầu trận. Đòn đánh thường có xác suất gây sát thương chuẩn. Hạ mục tiêu bằng kỹ năng giúp tăng sát thương và tốc độ (tối đa 2 lần).',
		starEffect = __data_t__starEffect[800904],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Tăng thêm $(500 + skillLevel*40)$ sát thương gây ra. Hiệu ứng này giúp Mihawk gia tăng sát thương theo cấp độ kỹ năng, khiến các đòn đánh của hắn trở nên ngày càng uy lực hơn khi kỹ năng được nâng cấp. Khi máu dưới 30% máu, Mihawk vực dậy với ý chí kiên cường, miễn nhiễm với các hiệu ứng khống chế đồng thời hồi phục 20% máu.',
		starEffectDesc = 'Enhanced Effect: Increases damage dealt by an additional $(500 + skillLevel*40)$. This effect allows Mihawk to scale his damage with skill level, making his attacks increasingly powerful as the skill is upgraded. When his HP falls below 30%, Mihawk rises with indomitable will, becoming immune to control effects and restoring 20% HP.',
		starEffectDesc_en = 'เอฟเฟกต์ที่เพิ่มขึ้น: เพิ่มความเสียหายที่สร้างได้อีก $(500 + skillLevel*40)$ เอฟเฟกต์นี้ทำให้ Mihawk เพิ่มพลังโจมตีตามเลเวลของสกิล ทำให้การโจมตีของเขารุนแรงมากขึ้นเรื่อย ๆ เมื่อสกิลถูกอัปเกรด เมื่อ HP ต่ำกว่า 30% Mihawk จะลุกขึ้นด้วยเจตจำนงที่ไม่ยอมแพ้ ได้รับการป้องกันจากเอฟเฟกต์ควบคุม และฟื้นฟู HP 20%',
		starEffectDesc_th = 'Efek yang Ditingkatkan: Meningkatkan damage yang dihasilkan sebesar $(500 + skillLevel*40)$. Efek ini membuat Mihawk meningkatkan damage sesuai level skill, menjadikan serangannya semakin kuat saat skill ditingkatkan. Ketika HP berada di bawah 30%, Mihawk bangkit dengan tekad baja, kebal terhadap efek kontrol sekaligus memulihkan 20% HP.',
		starEffectDesc_in = 'Pinahusay na Epekto: Nagdaragdag ng karagdagang $(500 + skillLevel*40)$ na damage. Ang epektong ito ay nagbibigay-daan kay Mihawk na pataasin ang kanyang damage ayon sa antas ng kakayahan, kaya’t lalong tumitindi ang kanyang mga atake habang naia-upgrade ang skill. Kapag bumaba sa 30% ang HP, bumabangon si Mihawk na may matatag na kalooban, nagiging immune sa mga control effect at nagbabalik ng 20% HP.',
		starEffectDesc_ph = 'Kesan Dipertingkatkan: Menambah $(500 + skillLevel*40)$ damage tambahan. Kesan ini membolehkan Mihawk meningkatkan damage mengikut tahap kemahiran, menjadikan serangannya semakin berkuasa apabila kemahiran dinaik taraf. Apabila HP jatuh di bawah 30%, Mihawk bangkit dengan semangat yang kental, kebal terhadap kesan kawalan serta memulihkan 20% HP.',
		zawakeEffect = __data_t__zawakeEffect[800904],
		-- {79004}
		zawakeEffectDesc = 'Mihawk enters the battle with the overwhelming dominance of a supreme Sword King. During the first 2 turns: Mihawk gains #C0x3D8A99#20% Critical Rate#C0x5B545B# and #C0x3D8A99#15% Skill Damage#C0x5B545B#, strengthening his offense early on. Each basic attack has a #C0xF13B54#25%#C0x5B545B# chance to deal additional true damage equal to 5% of the target\'s Max HP — ignoring all defenses, applying constant pressure even without skills. Each time Mihawk defeats a target with an active skill, he gains the effect <Sword King’s Supreme Aura> for 2 turns, increasing: #C0xF13B54#15% Total Damage Dealt#C0x5B545B#, #C0x3D8A99#10% Speed#C0x5B545B#. This effect can stack up to 2 times, turning Mihawk into a nightmare that becomes faster and deadlier as the battle goes on.',
		zawakeEffectDesc_en = 'Mihawk enters the battle with the overwhelming dominance of a supreme Sword King. During the first 2 turns: Mihawk gains #C0x3D8A99#20% Critical Rate#C0x5B545B# and #C0x3D8A99#15% Skill Damage#C0x5B545B#, strengthening his offense early on. Each basic attack has a #C0xF13B54#25%#C0x5B545B# chance to deal additional true damage equal to 5% of the target\'s Max HP — ignoring all defenses, applying constant pressure even without skills. Each time Mihawk defeats a target with an active skill, he gains the effect <Sword King’s Supreme Aura> for 2 turns, increasing: #C0xF13B54#15% Total Damage Dealt#C0x5B545B#, #C0x3D8A99#10% Speed#C0x5B545B#. This effect can stack up to 2 times, turning Mihawk into a nightmare that becomes faster and deadlier as the battle goes on.',
		zawakeEffectDesc_th = 'Mihawk ก้าวเข้าสู่การต่อสู้ด้วยอำนาจที่เหนือกว่าของราชันย์แห่งดาบสูงสุด ใน 2 เทิร์นแรก: Mihawk ได้รับ #C0x3D8A99#อัตราคริติคอล +20%#C0x5B545B# และ #C0x3D8A99#ดาเมจสกิล +15%#C0x5B545B# เสริมความรุนแรงตั้งแต่ต้นเกม การโจมตีปกติแต่ละครั้งมีโอกาส #C0xF13B54#25%#C0x5B545B# ที่จะสร้างดาเมจจริงเพิ่มเติมเท่ากับ 5% ของ HP สูงสุดของเป้าหมาย — ไร้ผลการป้องกัน สร้างแรงกดดันอย่างต่อเนื่องแม้ไม่ได้ใช้สกิล ทุกครั้งที่ Mihawk สังหารเป้าหมายด้วยสกิล เขาจะได้รับเอฟเฟกต์ <ออร่าแห่งราชันย์ดาบ> เป็นเวลา 2 เทิร์น เพิ่ม: #C0xF13B54#ดาเมจรวม +15%#C0x5B545B#, #C0x3D8A99#ความเร็ว +10%#C0x5B545B# เอฟเฟกต์นี้สะสมได้สูงสุด 2 ครั้ง ทำให้ Mihawk กลายเป็นฝันร้ายที่ยิ่งเร็วและร้ายกาจขึ้นเรื่อย ๆ',
		zawakeEffectDesc_in = 'Mihawk memasuki pertempuran dengan dominasi mutlak seorang Raja Pedang tertinggi. Selama 2 giliran pertama: Mihawk mendapatkan #C0x3D8A99#20% Critical Rate#C0x5B545B# dan #C0x3D8A99#15% Skill Damage#C0x5B545B#, memperkuat serangan sejak awal. Setiap serangan dasar memiliki #C0xF13B54#25%#C0x5B545B# peluang memberikan true damage tambahan sebesar 5% dari Max HP target — mengabaikan semua pertahanan, memberi tekanan terus-menerus bahkan tanpa skill. Setiap kali Mihawk menghabisi target dengan skill aktif, ia mendapatkan efek <Aura Raja Pedang> selama 2 giliran, meningkatkan: #C0xF13B54#15% Total Damage Dealt#C0x5B545B#, #C0x3D8A99#10% Speed#C0x5B545B#. Efek ini dapat menumpuk hingga 2 kali, menjadikan Mihawk mimpi buruk yang semakin cepat dan mematikan seiring berjalannya waktu.',
		zawakeEffectDesc_ph = 'Pumasok si Mihawk sa laban na may nakamamanghang kapangyarihan ng isang tunay na Hari ng Espada. Sa unang 2 turn: Nakakakuha si Mihawk ng #C0x3D8A99#20% Critical Rate#C0x5B545B# at #C0x3D8A99#15% Skill Damage#C0x5B545B#, pinatatag ang kanyang opensiba mula sa simula. Bawat basic attack ay may #C0xF13B54#25%#C0x5B545B# tsansang magdulot ng karagdagang true damage na katumbas ng 5% ng Max HP ng target — binabalewala ang lahat ng depensa, nagbibigay ng tuloy-tuloy na presyon kahit walang kasanayan. Sa bawat beses na makapatay si Mihawk gamit ang isang active skill, nakakatanggap siya ng epekto na <Aura ng Hari ng Espada> sa loob ng 2 turn, nagpapataas ng: #C0xF13B54#15% Total Damage Dealt#C0x5B545B#, #C0x3D8A99#10% Speed#C0x5B545B#. Maaaring maipon ang epektong ito hanggang 2 beses, ginagawang isang bangungot si Mihawk na mas bumibilis at mas nagiging nakamamatay habang tumatagal ang laban.',
		zawakeEffectDesc_ma = 'Mihawk memasuki pertempuran dengan kewibawaan mutlak seorang Raja Pedang tertinggi. Dalam 2 giliran pertama: Mihawk memperoleh #C0x3D8A99#20% Kadar Kritikal#C0x5B545B# dan #C0x3D8A99#15% Kerosakan Kemahiran#C0x5B545B#, mengukuhkan serangannya dari awal. Setiap serangan asas mempunyai #C0xF13B54#25%#C0x5B545B# peluang untuk memberikan kerosakan sebenar tambahan bersamaan 5% daripada HP Maks sasaran — mengabaikan semua pertahanan, memberi tekanan berterusan walaupun tanpa kemahiran. Setiap kali Mihawk menewaskan sasaran menggunakan kemahiran aktif, dia menerima kesan <Aura Raja Pedang> selama 2 giliran, meningkatkan: #C0xF13B54#15% Jumlah Kerosakan Diberikan#C0x5B545B#, #C0x3D8A99#10% Kelajuan#C0x5B545B#. Kesan ini boleh ditindih sehingga 2 kali, menjadikan Mihawk satu mimpi ngeri yang semakin pantas dan mematikan apabila pertempuran berlarutan.',
		zawakeEffectDesc_vn = 'Mihawk bước vào trận với uy thế áp đảo của một Kiếm Vương tối thượng. Trong 2 lượt đầu trận: Mihawk được tăng #C0x3D8A99#20% Tỷ lệ Chí Mạng#C0x5B545B# và #C0x3D8A99#15% Sát Thương Kỹ Năng#C0x5B545B#, củng cố thế công từ sớm. Mỗi đòn đánh cơ bản có #C0xF13B54#25%#C0x5B545B# xác suất gây thêm sát thương chuẩn bằng 5% Máu Tối Đa của mục tiêu — bỏ qua mọi phòng thủ, gây áp lực liên tục ngay cả khi không tung kỹ năng. Mỗi khi Mihawk hạ gục mục tiêu bằng kỹ năng chủ động, anh ta nhận hiệu ứng <Bá Khí Kiếm Vương> trong 2 lượt, tăng: #C0xF13B54#15% Tổng Sát Thương Gây Ra#C0x5B545B#, #C0x3D8A99#10% Tốc Độ#C0x5B545B#. Hiệu ứng này có thể cộng dồn tối đa 2 lần, biến Mihawk thành cơn ác mộng càng về sau càng nhanh và chí tử hơn. ',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Mihawk enters the battle with the overwhelming presence of a Supreme Sword King. During the first 2 turns: Mihawk\'s Critical Rate is increased by 20% and Skill Damage by 15%, strengthening his early offensive power.',
		zawakeSimpleDesc_en = 'Mihawk enters the battle with the overwhelming presence of a Supreme Sword King. During the first 2 turns: Mihawk\'s Critical Rate is increased by 20% and Skill Damage by 15%, strengthening his early offensive power.',
		zawakeSimpleDesc_th = 'Mihawk เข้าสู่การต่อสู้ด้วยความมีอำนาจเหนือชั้นของราชาแห่งดาบ ใน 2 เทิร์นแรก: อัตราคริติคอลของ Mihawk เพิ่มขึ้น 20% และความเสียหายสกิลเพิ่มขึ้น 15% เสริมความแข็งแกร่งการโจมตีตั้งแต่ต้นเกม',
		zawakeSimpleDesc_in = 'Mihawk memasuki pertempuran dengan kehadiran yang luar biasa sebagai Raja Pedang Tertinggi. Selama 2 giliran pertama: Critical Rate Mihawk meningkat 20% dan Damage Skill meningkat 15%, memperkuat kekuatan serangan awalnya.',
		zawakeSimpleDesc_ph = 'Pumasok si Mihawk sa laban na may nakaka-overwhelm na presensya ng isang Supreme Sword King. Sa unang 2 turn: Tumataas ang Critical Rate ni Mihawk ng 20% at Skill Damage ng 15%, pinapalakas ang kanyang unang opensiba.',
		zawakeSimpleDesc_ma = 'Mihawk memasuki pertempuran dengan kehadiran yang mengatasi sebagai Raja Pedang Tertinggi. Dalam 2 pusingan pertama: Kadar Kritikal Mihawk meningkat 20% dan Kerosakan Kemahiran meningkat 15%, mengukuhkan kuasa serang awalnya.',
		zawakeSimpleDesc_vn = 'Mihawk bước vào trận với uy thế áp đảo của một Kiếm Vương tối thượng. Trong 2 lượt đầu trận: Mihawk được tăng #C0x3D8A99#15% Tỷ lệ Chí Mạng#C0x5B545B# và #C0x3D8A99#10% Sát Thương Kỹ Năng#C0x5B545B#, củng cố thế công từ sớm \n#F20# \n#F40##C0x5c9970#→ Mihawk bước vào trận với uy thế áp đảo của một Kiếm Vương tối thượng. Trong 2 lượt đầu trận: Mihawk được tăng 20% Tỷ lệ Chí Mạng và 15% Sát Thương Kỹ Năng, củng cố thế công từ sớm',
		iconRes = 'battle/skill_icon/skill_80094.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
