	[981011] = {
		id = 981011,
		skillName_vn = 'Quyền Năng Hủy Diệt',
		skillName_en = 'Destructive Might',
		skillName_th = 'พลังทำลายล้าง',
		skillName_in = 'Kekuatan Penghancur',
		skillName_ph = 'Kapangyarihang Pangwasak',
		skillName_ma = 'Kekuatan Pemusnah',
		skillName = 'Destructive Might',
		describe_vn = 'Jiren giải phóng sức mạnh tối thượng, gây #C0xE69900#160% Công V.Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# lên 1 kẻ địch. Sau đó, Jiren tạo lá chắn 10% máu tối đa cho bản thân và đồng đội có sức tấn công cao nhất đội  trong 3 lượt tiếp theo.',
		describe_en = 'Jiren unleashes his ultimate power, dealing #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B# to a single enemy. Afterwards, Jiren generates a shield equal to 10% of Max HP for himself and the teammate with the highest attack in the team for the next 3 turns.',
		describe_th = 'จิเรนปลดปล่อยพลังสูงสุด สร้างความเสียหาย #C0xE69900#160% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# ต่อศัตรู 1 ตัว จากนั้น จิเรนสร้างโล่เท่ากับ 10% ของ HP สูงสุดให้ตัวเองและเพื่อนร่วมทีมที่มีพลังโจมตีสูงที่สุดเป็นเวลา 3 เทิร์นถัดไป',
		describe_in = 'Jiren melepaskan kekuatan tertinggi, memberikan #C0xE69900#160% Serangan Fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B# kepada 1 musuh. Setelah itu, Jiren menciptakan perisai sebesar 10% HP Maks untuk dirinya sendiri dan rekan tim dengan serangan tertinggi di tim selama 3 giliran berikutnya.',
		describe_ph = 'Ipinakakalabas ni Jiren ang kanyang ultimate power, na nagdudulot ng #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B# sa isang kalaban. Pagkatapos, lumikha si Jiren ng isang shield na katumbas ng 10% Max HP para sa kanyang sarili at sa kasapi ng koponan na may pinakamataas na attack sa susunod na 3 turn.',
		describe_ma = 'Jiren melepaskan kuasa tertinggi, memberikan #C0xE69900#160% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B# kepada 1 musuh. Selepas itu, Jiren mencipta perisai bersamaan 10% HP Maksimum untuk dirinya sendiri dan ahli pasukan dengan serangan tertinggi dalam pasukan selama 3 pusingan seterusnya.',
		describe = 'Jiren unleashes his ultimate power, dealing #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B# to a single enemy. Afterwards, Jiren generates a shield equal to 10% of Max HP for himself and the teammate with the highest attack in the team for the next 3 turns.',
		simDesc = 'Jiren giải phóng sức mạnh tối thượng, gây 150% sát thương vật lý lên 1 kẻ địch . Sau đó, Jiren tạo lá chắn 10% máu tối đa cho bản thân và đồng đội có sức tấn công cao nhất đội  trong 3 lượt tiếp theo.',
		iconRes = 'battle/skill_icon/skill_81011.png',
