	[981013] = {
		id = 981013,
		skillName_vn = 'Niệm Lực Hủy Diệt',
		skillName_en = 'Destructive Psychic Force',
		skillName_th = 'พลังจิตทำลายล้าง',
		skillName_in = 'Kekuatan Pikiran Penghancur',
		skillName_ph = 'Pangwasak na Lakas ng Isip',
		skillName_ma = 'Kuasa Psikik Pemusnah',
		skillName = 'Destructive Psychic Force',
		describe_vn = 'Jiren tập trung sức mạnh tối thượng, niệm lực trong tay và ném một hành tinh vào kẻ địch, gâyy #C0xE69900#300% Công V.Lý#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# sát thương vật lý lên tất cả kẻ địch. Kẻ địch bị tấn công bởi hành tinh sẽ bị tổn thương (nhận thêm 20% sát thương) trong 2 lượt tiếp theo và debuff này không thể bị xoá).',
		describe_en = 'Jiren concentrates his ultimate power, channels his ki, and throws a planet at enemies, dealing #C0xE69900#300% Physical Attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B# to all enemies. Enemies hit by the planet will be afflicted with a vulnerability (take 20% additional damage) for the next 2 turns, and this debuff cannot be removed.',
		describe_th = 'จิเรนรวมพลังขั้นสูงสุด โฟกัสพลังจิตในมือแล้วขว้างดาวเคราะห์ไปยังศัตรู สร้างความเสียหาย #C0xE69900#300% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# ให้กับศัตรูทั้งหมด ศัตรูที่ถูกโจมตีด้วยดาวเคราะห์จะได้รับสถานะบาดเจ็บ (ได้รับความเสียหายเพิ่ม 20%) เป็นเวลา 2 เทิร์นถัดไป และ debuff นี้ไม่สามารถลบได้',
		describe_in = 'Jiren memusatkan kekuatan ultimate-nya, mengumpulkan ki di tangan, dan melemparkan sebuah planet ke musuh, memberikan #C0xE69900#300% Serangan Fisik#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B# kepada semua musuh. Musuh yang terkena planet akan terkena kerentanan (menerima 20% kerusakan tambahan) selama 2 giliran berikutnya, dan debuff ini tidak bisa dihapus.',
		describe_ph = 'Pinagsama ni Jiren ang kanyang ultimate power, kinokontrol ang ki sa kanyang kamay at hinarang ang isang planeta sa mga kalaban, na nagdudulot ng #C0xE69900#300% Physical Attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B# sa lahat ng kalaban. Ang mga kalaban na tinamaan ng planeta ay magkakaroon ng vulnerability (tatanggap ng 20% dagdag na pinsala) sa susunod na 2 turn, at ang debuff na ito ay hindi maaaring alisin.',
		describe_ma = 'Jiren menumpukan kuasa ultimate, menyalurkan ki di tangan dan melemparkan sebuah planet ke musuh, memberikan #C0xE69900#300% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B# kepada semua musuh. Musuh yang terkena planet akan menerima kelemahan (menerima 20% kerosakan tambahan) selama 2 pusingan berikutnya dan debuff ini tidak boleh dihapus.',
		describe = 'Jiren concentrates his ultimate power, channels his ki, and throws a planet at enemies, dealing #C0xE69900#300% Physical Attack#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B# to all enemies. Enemies hit by the planet will be afflicted with a vulnerability (take 20% additional damage) for the next 2 turns, and this debuff cannot be removed.',
		simDesc = 'Jiren tập trung sức mạnh tối thượng, niệm lực trong tay và ném một hành tinh vào kẻ địch sát thương vật lý lên tất cả kẻ địch. Kẻ địch bị tấn công bởi hành tinh sẽ bị tổn thương (nhận thêm 20% sát thương) trong 2 lượt tiếp theo và debuff này không thể bị xoá).',
		starEffect = __data_t__starEffect[981013],
		-- {11}
		starEffectDesc_vn = 'Dư chấn từ vụ nổ gây thêm sát thương vật lý cho hàng trước của địch tương đương với 10% sát thương từ kĩ năng và gây thêm sát thương vật lý cho hàng sau của địch đương với 25% sát thương từ kĩ năng. Đồng thời, đối thủ sẽ bị 30% tỷ lệ choáng trong 1 lượt sau khi bị tấn công bởi kỹ năng này.',
		starEffectDesc = 'Aftershock from the explosion deals additional physical damage to the enemy’s front row equal to 10% of the skill’s damage, and additional physical damage to the enemy’s back row equal to 25% of the skill’s damage. At the same time, enemies hit by this skill have a 30% chance to be stunned for 1 turn.',
		starEffectDesc_en = 'Aftershock from the explosion deals additional physical damage to the enemy’s front row equal to 10% of the skill’s damage, and additional physical damage to the enemy’s back row equal to 25% of the skill’s damage. At the same time, enemies hit by this skill have a 30% chance to be stunned for 1 turn.',
		starEffectDesc_th = 'แรงสะเทือนจากการระเบิดสร้างความเสียหายกายภาพเพิ่มเติมแก่แถวหน้าของศัตรูเท่ากับ 10% ของความเสียหายจากสกิล และสร้างความเสียหายกายภาพเพิ่มเติมแก่แถวหลังของศัตรูเท่ากับ 25% ของความเสียหายจากสกิล ในขณะเดียวกัน ศัตรูที่โดนสกิลนี้จะมีโอกาส 30% ที่จะติดสตันเป็นเวลา 1 เทิร์น',
		starEffectDesc_in = 'Guncangan dari ledakan memberikan tambahan damage fisik pada barisan depan musuh sebesar 10% dari damage skill, dan tambahan damage fisik pada barisan belakang musuh sebesar 25% dari damage skill. Pada saat yang sama, musuh yang terkena skill ini memiliki 30% peluang untuk terkena stun selama 1 giliran.',
		starEffectDesc_ph = 'Ang pagyanig mula sa pagsabog ay nagdudulot ng karagdagang pisikal na pinsala sa hanay sa unahan ng kalaban na katumbas ng 10% ng pinsala mula sa kakayahan, at karagdagang pisikal na pinsala sa hanay sa likuran ng kalaban na katumbas ng 25% ng pinsala mula sa kakayahan. Kasabay nito, ang mga kalabang tinamaan ng kasanayang ito ay may 30% tsansa na ma-stun sa loob ng 1 turn.',
		starEffectDesc_ma = 'Gegaran daripada letupan menyebabkan tambahan damage fizikal kepada barisan hadapan musuh bersamaan dengan 10% daripada damage kemahiran, dan tambahan damage fizikal kepada barisan belakang musuh bersamaan dengan 25% daripada damage kemahiran. Pada masa yang sama, musuh yang terkena kemahiran ini mempunyai 30% peluang untuk terkena stun selama 1 giliran.',
		iconRes = 'battle/skill_icon/skill_81013.png',
		changeUnitTrigger = true,
