	[981016] = {
		id = 981016,
		skillName_vn = 'Sự Hy Sinh Vô Song',
		skillName_en = 'Peerless Sacrifice',
		skillName_th = 'การเสียสละไร้เทียมทาน',
		skillName_in = 'Pengorbanan Tanpa Tanding',
		skillName_ph = 'Walang Kapantay na Sakripisyo',
		skillName_ma = 'Pengorbanan Tiada Bandingan',
		skillName = 'Peerless Sacrifice',
		describe_vn = 'Khi nhận sát thương gây tử vong, Jiren vẫn giữ bản thân sống sót và hồi lại #C0x5c9970#50% máu tối đa #C0x5B545B# +$(skillLevel*4*90)$. Đồng thời, Jiren kích hoạt khiêu khích tất cả kẻ địch trong 1 lượt, buộc chúng phải tấn công vào Jiren. Trong thời gian này, mỗi lượt bị tấn công sẽ tăng 10% tấn công cho Jiren và đồng đội (hệ Đấu nhận gấp đôi), và buff này không thể bị xoá trong 3 lượt.',
		describe_en = 'When taking fatal damage, Jiren survives and recovers #C0x5c9970#50% of his Max HP#C0x5B545B# + $(skillLevel*4*90)$. At the same time, Jiren provokes all enemies for 1 turn, forcing them to attack him. During this period, each turn Jiren is attacked increases attack by 10% for Jiren and allies (Fighter type receives double), and this buff cannot be removed for 3 turns.',
		describe_th = 'เมื่อได้รับความเสียหายถึงขั้นตาย จิเรนยังคงรอดชีวิตและฟื้นฟู #C0x5c9970#50% ของพลังชีวิตสูงสุด#C0x5B545B# + $(skillLevel*4*90) ในเวลาเดียวกัน จิเรนจะทำการยั่วยุศัตรูทั้งหมดเป็นเวลา 1 เทิร์น บังคับให้พวกมันโจมตีเขา ในช่วงนี้ ทุกครั้งที่ถูกโจมตีจะเพิ่มพลังโจมตี 10% ให้กับจิเรนและพันธมิตร (ประเภท Fighter ได้รับสองเท่า) และบัฟนี้ไม่สามารถลบได้เป็นเวลา 3 เทิร์น',
		describe_in = 'Saat menerima damage mematikan, Jiren tetap bertahan dan memulihkan #C0x5c9970#50% HP Maksimum#C0x5B545B# + $(skillLevel*4*90)$. Pada saat yang sama, Jiren memprovokasi semua musuh selama 1 giliran, memaksa mereka menyerang Jiren. Selama periode ini, setiap giliran Jiren diserang akan meningkatkan serangan sebesar 10% untuk Jiren dan sekutu (tipe Fighter menerima dua kali lipat), dan buff ini tidak bisa dihapus selama 3 giliran.',
		describe_ph = 'Kapag tumanggap ng nakamamatay na pinsala, nananatiling buhay si Jiren at nakakabawi ng #C0x5c9970#50% Max HP#C0x5B545B# + $(skillLevel*4*90)$. Kasabay nito, ini-provoke ni Jiren ang lahat ng kalaban sa loob ng 1 turn, pinipilit silang atakihin siya. Sa panahong ito, bawat turn na siya ay inaatake ay nagdaragdag ng 10% attack para kay Jiren at sa kanyang mga kakampi (doble ang natatanggap ng Fighter type), at ang buff na ito ay hindi maaaring alisin sa loob ng 3 turn.',
		describe_ma = 'Apabila menerima kerosakan yang mematikan, Jiren masih terus hidup dan memulihkan #C0x5c9970#50% Darah Maksimum#C0x5B545B# + $(skillLevel*4*90)$. Pada masa yang sama, Jiren memprovokasi semua musuh selama 1 pusingan, memaksa mereka menyerangnya. Dalam tempoh ini, setiap pusingan Jiren diserang akan meningkatkan serangan sebanyak 10% untuk Jiren dan sekutu (jenis Fighter menerima dua kali ganda), dan buff ini tidak boleh dipadamkan selama 3 pusingan.',
		describe = 'When taking fatal damage, Jiren survives and recovers #C0x5c9970#50% of his Max HP#C0x5B545B# + $(skillLevel*4*90)$. At the same time, Jiren provokes all enemies for 1 turn, forcing them to attack him. During this period, each turn Jiren is attacked increases attack by 10% for Jiren and allies (Fighter type receives double), and this buff cannot be removed for 3 turns.',
		simDesc = 'Khi nhận sát thương gây tử vong, Jiren vẫn giữ bản thân còn sống và hồi lại 50% máu. Đồng thời, Jiren kích hoạt khiêu khích tất cả kẻ địch.',
		starEffect = __data_t__starEffect[981016],
		-- {8}
		starEffectDesc_vn = 'Khi đạt mốc 8 sao, Jiren kích hoạt khiêu khích kẻ địch sẽ tăng 20% kháng khống chế và tạo lá chắn bằng 20% máu tối đa của Jiren cho tất cả đồng đội trong 2 lượt( hệ đấu nhận gấp đôi)',
		starEffectDesc = 'Upon reaching 8 stars, when Jiren activates Taunt, he gains 20% control resistance and grants a shield equal to 20% of Jiren’s max HP to all allies for 2 turns (Fighter-type allies receive double the amount).',
		starEffectDesc_en = 'Upon reaching 8 stars, when Jiren activates Taunt, he gains 20% control resistance and grants a shield equal to 20% of Jiren’s max HP to all allies for 2 turns (Fighter-type allies receive double the amount).',
		starEffectDesc_th = 'เมื่อถึงระดับ 8 ดาว Jiren จะได้รับ 20% ต้านทานสถานะควบคุมเมื่อเปิดใช้การยั่วยุ และสร้างโล่เท่ากับ 20% ของ HP สูงสุดของ Jiren ให้กับเพื่อนร่วมทีมทุกคนเป็นเวลา 2 เทิร์น (ตัวละครสายต่อสู้จะได้รับโล่เพิ่มเป็นสองเท่า)',
		starEffectDesc_in = 'Saat mencapai 8 bintang, ketika Jiren mengaktifkan Taunt, ia mendapatkan 20% resistensi kontrol dan memberikan perisai sebesar 20% dari HP maksimum Jiren kepada semua rekan tim selama 2 giliran (tipe Petarung menerima dua kali lipat).',
		starEffectDesc_ph = 'Kapag umabot sa 8 bituin, kapag ginamit ni Jiren ang Taunt, nakakakuha siya ng 20% resistensya laban sa control effects at nagbibigay ng shield na katumbas ng 20% ng max HP ni Jiren sa lahat ng kakampi sa loob ng 2 turn (ang mga kakampi na uri Fighter ay makakatanggap ng doble).',
		starEffectDesc_ma = 'Apabila mencapai 8 bintang, apabila Jiren mengaktifkan Taunt, dia memperoleh 20% ketahanan kawalan dan memberikan perisai bersamaan dengan 20% daripada HP maksimum Jiren kepada semua rakan sepasukan selama 2 giliran (rakan sepasukan jenis Fighter menerima dua kali ganda).',
		iconRes = 'battle/skill_icon/skill_81016.png',
