	[981021] = {
		id = 981021,
		skillName_vn = 'Liên Quyền Sấm Sét',
		skillName_en = 'Thunder Strike Combo',
		skillName_th = 'คอมโบฟ้าร้อง',
		skillName_in = 'Kombo Petir',
		skillName_ph = 'Combo ng Kidlat',
		skillName_ma = 'Gabungan Petir',
		skillName = 'Thunder Strike Combo',
		describe_vn = 'Jiren bùng nổ sức mạnh tối thượng, tung ra đòn tấn công hủy diệt gây #C0xE69900#160% Công V.Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# lên 1 kẻ địch. Sau cú đánh huỷ diệt này Jiren sẽ kích hoạt hiệu ứng <Đồng minh của công lý>, Jiren dựng nên lá chắn tương đương 10% Máu Tối Đa cho bản thân và đồng đội có sức tấn công cao nhất trong đội, duy trì suốt 3 lượt. Đồng thời, Jiren khơi dậy sức mạnh đồng đội: hồi 10% Máu cho bản thân và đồng đội có lượng máu thấp nhất, đồng thời gia tăng 10% Tốc Độ cho bản thân và đồng đội có tốc độ thấp nhất.',
		describe_en = 'Jiren unleashes his ultimate power, performing a devastating attack that deals #C0xE69900#160% Physical ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B# to 1 enemy. After this destructive strike, Jiren activates the effect <Ally of Justice>, creating a shield equal to 10% Max HP for himself and the ally with the highest attack in the team, lasting 3 turns. At the same time, Jiren awakens the strength of his allies: restoring 10% HP to himself and the ally with the lowest HP, and increasing 10% Speed for himself and the ally with the lowest Speed.',
		describe_th = 'จิเรนระเบิดพลังสูงสุด ปล่อยการโจมตีทำลายล้างก่อให้เกิด #C0xE69900#160% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ไปยังศัตรู 1 ตัว หลังจากการโจมตีทำลายล้างนี้ จิเรนจะเปิดใช้งานเอฟเฟกต์ <พันธมิตรแห่งความยุติธรรม> สร้างโล่เท่ากับ 10% ของพลังชีวิตสูงสุดให้กับตนเองและพันธมิตรที่มีพลังโจมตีสูงที่สุดในทีม คงอยู่ 3 เทิร์น ในเวลาเดียวกัน จิเรนกระตุ้นพลังของพันธมิตร: ฟื้นฟู 10% HP ให้กับตนเองและพันธมิตรที่มี HP ต่ำที่สุด พร้อมเพิ่ม 10% ความเร็วให้ตนเองและพันธมิตรที่มีความเร็วต่ำที่สุด',
		describe_in = 'Jiren melepaskan kekuatan ultimate-nya, melakukan serangan dahsyat yang memberikan #C0xE69900#160% Serangan Fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Damage Fisik#C0x5B545B# ke 1 musuh. Setelah serangan menghancurkan ini, Jiren mengaktifkan efek <Ally of Justice>, menciptakan perisai sebesar 10% HP Maksimum untuk dirinya sendiri dan sekutu dengan serangan tertinggi di tim, bertahan selama 3 giliran. Pada saat yang sama, Jiren membangkitkan kekuatan sekutu: memulihkan 10% HP untuk dirinya sendiri dan sekutu dengan HP terendah, serta meningkatkan 10% Kecepatan untuk dirinya sendiri dan sekutu dengan Kecepatan terendah.',
		describe_ph = 'Pinakakawala ni Jiren ang kanyang ultimate power, naglabas ng mapanirang atake na nagdudulot ng #C0xE69900#160% Physical ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B# sa 1 kaaway. Pagkatapos ng mapanirang suntok na ito, aktibo ni Jiren ang effect na <Ally of Justice>, lumilikha ng shield na katumbas ng 10% Max HP para sa kanya at sa ally na may pinakamataas na attack sa team, tumatagal ng 3 turn. Kasabay nito, ginigising ni Jiren ang lakas ng kanyang mga kakampi: nagbabalik ng 10% HP sa kanya at sa ally na may pinakamababang HP, at nagdaragdag ng 10% Speed sa kanya at sa ally na may pinakamababang Speed.',
		describe_ma = 'Jiren melepaskan kuasa tertingginya, melancarkan serangan memusnahkan yang menyebabkan #C0xE69900#160% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B# kepada 1 musuh. Selepas serangan memusnahkan ini, Jiren mengaktifkan kesan <Sekutu Keadilan>, mewujudkan perisai bersamaan 10% HP Maksimum untuk dirinya dan sekutu dengan serangan tertinggi dalam pasukan, bertahan selama 3 pusingan. Pada masa yang sama, Jiren membangkitkan kekuatan sekutu: memulihkan 10% HP kepada dirinya dan sekutu dengan HP terendah, serta meningkatkan 10% Kelajuan kepada dirinya dan sekutu dengan Kelajuan terendah.',
		describe = 'Jiren unleashes his ultimate power, performing a devastating attack that deals #C0xE69900#160% Physical ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B# to 1 enemy. After this destructive strike, Jiren activates the effect <Ally of Justice>, creating a shield equal to 10% Max HP for himself and the ally with the highest attack in the team, lasting 3 turns. At the same time, Jiren awakens the strength of his allies: restoring 10% HP to himself and the ally with the lowest HP, and increasing 10% Speed for himself and the ally with the lowest Speed.',
		simDesc = 'Jiren giải phóng sức mạnh tối thượng, gây 150% sát thương vật lý lên 1 kẻ địch . Sau đó, Jiren tạo lá chắn 10% máu tối đa cho bản thân và đồng đội có sức tấn công cao nhất đội  trong 3 lượt tiếp theo. Hồi máu cho đồng đội có lượng máu thấp nhất. Tăng tốc độ cho đồng đội có tốc độ chậm nhất.',
		zawakeEffect = __data_t__zawakeEffect[981021],
		-- {79001}
		zawakeEffectDesc = 'Jiren erupts with supreme power, unleashing a devastating attack that deals #C0xE69900#160% Physical ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical DMG#C0x5B545B# to 1 enemy. After this destructive strike, Jiren activates the effect <Ally of Justice>, creating a shield equal to 10% of Max HP for himself and the ally with the highest ATK in the team, lasting 3 turns. At the same time, Jiren ignites team power: restores 10% HP for himself and the ally with the lowest HP, increases Speed by 10% for himself and the ally with the lowest Speed for 2 turns, and increases Physical DEF by 10% for himself and the ally with the lowest Physical DEF for 2 turns.',
		zawakeEffectDesc_en = 'Jiren erupts with supreme power, unleashing a devastating attack that deals #C0xE69900#160% Physical ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical DMG#C0x5B545B# to 1 enemy. After this destructive strike, Jiren activates the effect <Ally of Justice>, creating a shield equal to 10% of Max HP for himself and the ally with the highest ATK in the team, lasting 3 turns. At the same time, Jiren ignites team power: restores 10% HP for himself and the ally with the lowest HP, increases Speed by 10% for himself and the ally with the lowest Speed for 2 turns, and increases Physical DEF by 10% for himself and the ally with the lowest Physical DEF for 2 turns.',
		zawakeEffectDesc_th = 'จิเร็นระเบิดพลังสูงสุด ปล่อยการโจมตีทำลายล้างสร้างความเสียหาย #C0xE69900#160% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# แก่ศัตรู 1 เป้าหมาย หลังจากการโจมตีทำลายล้างนี้ จิเร็นจะเปิดใช้งานเอฟเฟกต์ <พันธมิตรแห่งความยุติธรรม> สร้างเกราะเท่ากับ 10% ของ HP สูงสุดให้กับตนเองและพันธมิตรที่มีพลังโจมตีสูงสุดในทีม คงอยู่ 3 เทิร์น พร้อมกันนี้ จิเร็นปลุกพลังทีม: ฟื้นฟู HP 10% ให้กับตนเองและพันธมิตรที่มี HP ต่ำที่สุด เพิ่มความเร็ว 10% ให้กับตนเองและพันธมิตรที่มีความเร็วต่ำที่สุด เป็นเวลา 2 เทิร์น และเพิ่ม DEF กายภาพ 10% ให้กับตนเองและพันธมิตรที่มี DEF กายภาพต่ำที่สุด เป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Jiren meledak dengan kekuatan tertinggi, melancarkan serangan penghancur yang memberikan #C0xE69900#160% ATK Fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#DMG Fisik#C0x5B545B# kepada 1 musuh. Setelah serangan destruktif ini, Jiren mengaktifkan efek <Sekutu Keadilan>, menciptakan perisai setara dengan 10% HP Maks untuk dirinya sendiri dan sekutu dengan ATK tertinggi di tim, bertahan selama 3 giliran. Pada saat yang sama, Jiren membangkitkan kekuatan tim: memulihkan 10% HP untuk dirinya dan sekutu dengan HP terendah, meningkatkan Kecepatan 10% untuk dirinya dan sekutu dengan Kecepatan terendah selama 2 giliran, serta meningkatkan DEF Fisik 10% untuk dirinya dan sekutu dengan DEF Fisik terendah selama 2 giliran.',
		zawakeEffectDesc_ph = 'Sumabog si Jiren gamit ang sukdulang lakas, pinakawalan ang isang mapaminsalang atake na nagdudulot ng #C0xE69900#160% Physical ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical DMG#C0x5B545B# sa 1 kalaban. Pagkatapos ng mapanirang hampas na ito, ina-activate ni Jiren ang epektong <Kakampi ng Katarungan>, lumilikha ng kalasag na katumbas ng 10% ng Max HP para sa sarili at sa kakamping may pinakamataas na ATK sa koponan, na tumatagal ng 3 turn. Kasabay nito, ginigising ni Jiren ang lakas ng koponan: nagre-restore ng 10% HP para sa sarili at kakamping may pinakamababang HP, nagdaragdag ng 10% Speed para sa sarili at kakamping may pinakamababang Speed sa loob ng 2 turn, at nagdaragdag ng 10% Physical DEF para sa sarili at kakamping may pinakamababang Physical DEF sa loob ng 2 turn.',
		zawakeEffectDesc_ma = 'Jiren meletup dengan kuasa tertinggi, melancarkan serangan pemusnah yang memberikan #C0xE69900#160% ATK Fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#DMG Fizikal#C0x5B545B# kepada 1 musuh. Selepas serangan pemusnah ini, Jiren mengaktifkan kesan <Sekutu Keadilan>, mencipta perisai bersamaan dengan 10% HP Maks untuk dirinya dan sekutu dengan ATK tertinggi dalam pasukan, bertahan selama 3 giliran. Pada masa yang sama, Jiren membangkitkan kuasa pasukan: memulihkan 10% HP untuk dirinya dan sekutu dengan HP terendah, meningkatkan Kelajuan 10% untuk dirinya dan sekutu dengan Kelajuan terendah selama 2 giliran, serta meningkatkan DEF Fizikal 10% untuk dirinya dan sekutu dengan DEF Fizikal terendah selama 2 giliran.',
		zawakeEffectDesc_vn = 'Jiren bùng nổ sức mạnh tối thượng, tung ra đòn tấn công hủy diệt gây #C0xE69900#160% Công V.Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# lên 1 kẻ địch. Sau cú đánh huỷ diệt này Jiren sẽ kích hoạt hiệu ứng <Đồng minh của công lý>, Jiren dựng nên lá chắn tương đương 10% Máu Tối Đa cho bản thân và đồng đội có sức tấn công cao nhất trong đội, duy trì suốt 3 lượt. Đồng thời, Jiren khơi dậy sức mạnh đồng đội: hồi 10% Máu cho bản thân và đồng đội có lượng máu thấp nhất, gia tăng 10% Tốc Độ cho bản thân và đồng đội có tốc độ thấp nhất trong 2 lượt, gia tăng 10% Thủ Vật lý cho bản thân và đồng đội có Thủ vật lý thấp nhất trong 2 lượt.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'After using the skill, Jiren increases Physical Defense by 10% for himself and the ally with the lowest Physical Defense for 2 turns.',
		zawakeSimpleDesc_en = 'After using the skill, Jiren increases Physical Defense by 10% for himself and the ally with the lowest Physical Defense for 2 turns.',
		zawakeSimpleDesc_th = 'หลังจากใช้สกิล Jiren เพิ่มค่าป้องกันกายภาพ 10% ให้ตัวเองและพันธมิตรที่มีค่าป้องกันกายภาพต่ำที่สุดเป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Setelah menggunakan skill, Jiren meningkatkan Pertahanan Fisik sebesar 10% untuk dirinya sendiri dan sekutu dengan Pertahanan Fisik terendah selama 2 giliran',
		zawakeSimpleDesc_ph = 'Pagkatapos gamitin ang kakayahan, pinapataas ni Jiren ang Physical Defense ng 10% para sa kanya at sa kaalyado na may pinakamababang Physical Defense sa loob ng 2 turn',
		zawakeSimpleDesc_ma = 'Selepas menggunakan kemahiran, Jiren meningkatkan Pertahanan Fizikal sebanyak 10% untuk dirinya sendiri dan sekutu dengan Pertahanan Fizikal terendah selama 2 pusingan',
		zawakeSimpleDesc_vn = 'Sau khi sử dụng khỉ năng, Jiren gia tăng 10% Thủ Vật lý cho bản thân và đồng đội có Thủ vật lý thấp nhất trong 2 lượt.',
		iconRes = 'battle/skill_icon/skill_81021.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 0,
		skillNatureType = 7,
		posChoose = 1,
		targetTypeDesc = 'Single Enemy',
		targetTypeDesc_vn = 'Đơn thể địch',
		targetTypeDesc_en = 'Single Enemy',
		targetTypeDesc_th = 'ศัตรูเดี่ยว',
