	[981022] = {
		id = 981022,
		skillName_vn = 'Siêu Nhiệt Sóng Hủy Diệt',
		skillName_en = 'Super Heat Destructive Wave',
		skillName_th = 'คลื่นทำลายร้อนจัด',
		skillName_in = 'Gelombang Penghancur Super Panas',
		skillName_ph = 'Super Init na Alon ng Pagwasak',
		skillName_ma = 'Gelombang Pemusnah Super Panas',
		skillName = 'Super Heat Destructive Wave',
		describe_vn = 'Jiren giải phóng luồng năng lượng hủy diệt nóng bỏng gây #C0xE69900#240% Công V.Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# lên 3 mục tiêu ngẫu nhiên. Sóng xung kích từ đòn đánh khiến kẻ địch chậm lại, giảm 10% Tốc Độ Di Chuyển và chịu thêm 20% sát thương trong 2 lượt tiếp theo.\n<Hi sinh vì đồng đội>: Khi lượng máu tối đa của Jiren trên 60% những kẻ bị trúng chiêu có 50% khả năng sẽ rơi vào trạng thái Khiêu Khích trong 2 lượt, buộc mọi đòn tấn công của chúng đều nhằm vào Jiren. Trong thời gian này, Jiren được gia tăng sức chịu đựng, giảm 20% sát thương nhận vào suốt 2 lượt, đứng vững như tấm khiên thép che chở cho đồng đội.',
		describe_en = 'Jiren unleashes a scorching destructive energy, dealing #C0xE69900#240% Physical ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B# to 3 random enemies. The shockwave from the attack slows enemies, reducing their Movement Speed by 10% and causing an additional 20% damage for the next 2 turns.\n<Sacrifice for Allies>: When Jiren’s Max HP is above 60%, enemies hit have a 50% chance to enter Taunt for 2 turns, forcing all their attacks to target Jiren. During this time, Jiren gains increased resilience, taking 20% less damage for 2 turns, standing firm like a steel shield protecting his allies.',
		describe_th = 'จิเรนปล่อยพลังทำลายล้างร้อนแรง สร้างความเสียหาย #C0xE69900#240% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ไปยังศัตรู 3 ตัวแบบสุ่ม คลื่นช็อกจากการโจมตีทำให้ศัตรูช้าลง ลดความเร็วเคลื่อนที่ 10% และรับความเสียหายเพิ่ม 20% เป็นเวลา 2 เทิร์นต่อไป.\n<เสียสละเพื่อเพื่อนร่วมทีม>: เมื่อพลังชีวิตสูงสุดของจิเรนมากกว่า 60% ศัตรูที่ถูกโจมตีมีโอกาส 50% ตกอยู่ในสถานะล่อเป้าเป็นเวลา 2 เทิร์น ทำให้การโจมตีทั้งหมดของพวกเขามุ่งเป้าไปที่จิเรน ในช่วงเวลานี้ จิเรนจะได้รับความทนทานเพิ่มขึ้น ลดความเสียหายที่ได้รับ 20% เป็นเวลา 2 เทิร์น ยืนหยัดเหมือนโล่เหล็กปกป้องเพื่อนร่วมทีม',
		describe_in = 'Jiren melepaskan energi destruktif yang membara, memberikan #C0xE69900#240% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Damage Fisik#C0x5B545B# ke 3 musuh acak. Gelombang kejut dari serangan memperlambat musuh, mengurangi Kecepatan Gerak mereka sebesar 10% dan menerima tambahan 20% damage selama 2 giliran berikutnya.\n<Pengorbanan untuk Sekutu>: Ketika HP Maksimum Jiren di atas 60%, musuh yang terkena serangan memiliki peluang 50% untuk masuk ke status Taunt selama 2 giliran, memaksa semua serangan mereka mengincar Jiren. Selama waktu ini, Jiren mendapatkan ketahanan tambahan, menerima 20% damage lebih sedikit selama 2 giliran, berdiri teguh seperti perisai baja yang melindungi sekutunya.',
		describe_ph = 'Pinakakawala ni Jiren ang nagbabagang enerhiya ng pagkawasak, nagdudulot ng #C0xE69900#240% Physical ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B# sa 3 random na kaaway. Ang shockwave mula sa atake ay nagpapabagal sa mga kaaway, binabawasan ang kanilang Movement Speed ng 10% at tumatanggap ng karagdagang 20% damage sa susunod na 2 turn.\n<Sakripisyo para sa mga Kaalyado>: Kapag ang Max HP ni Jiren ay higit sa 60%, ang mga kaaway na tinamaan ay may 50% chance na pumasok sa Taunt status sa loob ng 2 turn, pinipilit na lahat ng kanilang atake ay tumarget kay Jiren. Sa panahong ito, nakakakuha si Jiren ng dagdag na tibay, tumatanggap ng 20% mas kaunting damage sa loob ng 2 turn, nakatayo nang matatag tulad ng steel shield na nagpoprotekta sa kanyang mga kaalyado.',
		describe_ma = 'Jiren melepaskan tenaga pemusnah yang membara, menyebabkan #C0xE69900#240% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B# kepada 3 musuh secara rawak. Gelombang kejutan daripada serangan memperlahankan musuh, mengurangkan Kelajuan Pergerakan mereka sebanyak 10% dan menerima 20% kerosakan tambahan selama 2 pusingan berikutnya.\n<Pengorbanan untuk Sekutu>: Apabila HP Maksimum Jiren melebihi 60%, musuh yang terkena serangan mempunyai 50% kemungkinan memasuki keadaan Provokasi selama 2 pusingan, memaksa semua serangan mereka tertuju kepada Jiren. Dalam tempoh ini, Jiren memperoleh ketahanan tambahan, menerima 20% kerosakan kurang selama 2 pusingan, berdiri teguh seperti perisai besi melindungi sekutunya.',
		describe = 'Jiren unleashes a scorching destructive energy, dealing #C0xE69900#240% Physical ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B# to 3 random enemies. The shockwave from the attack slows enemies, reducing their Movement Speed by 10% and causing an additional 20% damage for the next 2 turns.\n<Sacrifice for Allies>: When Jiren’s Max HP is above 60%, enemies hit have a 50% chance to enter Taunt for 2 turns, forcing all their attacks to target Jiren. During this time, Jiren gains increased resilience, taking 20% less damage for 2 turns, standing firm like a steel shield protecting his allies.',
		simDesc = 'Jiren gây lên 3 mục tiêu ngẫu nhiên. Kỹ năng này cũng gây debuff lên kẻ địch, khiến chúng giảm 10% tốc độ di chuyển và nhận 20% sát thương thêm trong 2 lượt tiếp theo. Đồng thời khiêu khích kẻ địch trúng đòn.',
		zawakeEffect = __data_t__zawakeEffect[981022],
		-- {79002}
		zawakeEffectDesc = 'Jiren unleashes scorching destructive energy, dealing #C0xE69900#240% Physical ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B# to 3 random enemies. The shockwave slows enemies, reducing Movement Speed by 10% and making them take 20% more damage for the next 2 turns.\n<Sacrifice for Allies>: When Jiren’s Max HP is above 60%, enemies hit have a 50% chance to be Taunted for 2 turns, forcing all their attacks to target Jiren. During this time, Jiren gains resilience, reducing incoming damage by 20% for 2 turns, standing firm as an iron shield protecting his allies. In addition, Jiren creates a shield equal to 10% of Max HP for himself and the ally with the lowest current HP in the team for 2 turns.',
		zawakeEffectDesc_en = 'Jiren unleashes scorching destructive energy, dealing #C0xE69900#240% Physical ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B# to 3 random enemies. The shockwave slows enemies, reducing Movement Speed by 10% and making them take 20% more damage for the next 2 turns.\n<Sacrifice for Allies>: When Jiren’s Max HP is above 60%, enemies hit have a 50% chance to be Taunted for 2 turns, forcing all their attacks to target Jiren. During this time, Jiren gains resilience, reducing incoming damage by 20% for 2 turns, standing firm as an iron shield protecting his allies. In addition, Jiren creates a shield equal to 10% of Max HP for himself and the ally with the lowest current HP in the team for 2 turns.',
		zawakeEffectDesc_th = 'จิเรนปลดปล่อยพลังงานทำลายล้างร้อนแรง สร้างความเสียหาย #C0xE69900#240% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# แก่ศัตรูแบบสุ่ม 3 เป้าหมาย คลื่นกระแทกจากการโจมตีทำให้ศัตรูช้าลง ลดความเร็วเคลื่อนที่ 10% และได้รับความเสียหายเพิ่มขึ้น 20% เป็นเวลา 2 เทิร์นถัดไป \n<สละชีพเพื่อพวกพ้อง>: เมื่อ HP สูงสุดของจิเรนเกิน 60% ศัตรูที่โดนโจมตีจะมีโอกาส 50% ตกอยู่ในสถานะยั่วยุเป็นเวลา 2 เทิร์น บังคับให้การโจมตีทั้งหมดของพวกมันมุ่งเป้าไปที่จิเรน ในช่วงเวลานี้ จิเรนได้รับความทนทาน ลดความเสียหายที่ได้รับลง 20% เป็นเวลา 2 เทิร์น ยืนหยัดเป็นดั่งโล่เหล็กคุ้มครองเพื่อนร่วมทีม นอกจากนี้ จิเรนยังสร้างโล่เท่ากับ 10% ของ HP สูงสุดให้กับตนเองและเพื่อนร่วมทีมที่มี HP ปัจจุบันต่ำที่สุดในทีม เป็นเวลา 2 เทิร์น',
		zawakeEffectDesc_in = 'Jiren melepaskan energi destruktif yang membara, memberikan #C0xE69900#240% ATK Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Damage Fisik#C0x5B545B# kepada 3 musuh acak. Gelombang kejut dari serangan ini memperlambat musuh, mengurangi Kecepatan Gerak sebesar 10% dan membuat mereka menerima 20% lebih banyak damage selama 2 giliran berikutnya.\n<Berkorban untuk Rekan>: Saat HP Maks Jiren di atas 60%, musuh yang terkena serangan memiliki 50% peluang terkena status Taunt selama 2 giliran, memaksa semua serangan mereka tertuju pada Jiren. Selama waktu ini, Jiren memperoleh daya tahan, mengurangi damage yang diterima sebesar 20% selama 2 giliran, berdiri kokoh sebagai perisai baja yang melindungi timnya. Selain itu, Jiren menciptakan perisai setara dengan 10% HP Maks untuk dirinya sendiri dan rekan dengan HP saat ini terendah di tim selama 2 giliran.',
		zawakeEffectDesc_ph = 'Pinalalaya ni Jiren ang naglalagablab na enerhiyang mapanira, nagdudulot ng #C0xE69900#240% Pisikal na ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B# sa 3 random na kalaban. Ang shockwave mula sa atake ay nagpapabagal sa mga kalaban, binabawasan ang Bilis ng Paggalaw ng 10% at pinapataas ang pinsalang natatanggap nila ng 20% sa loob ng susunod na 2 turn.\n<Sakripisyo para sa mga Kaalyado>: Kapag ang Max HP ni Jiren ay higit sa 60%, ang mga kalabang tinamaan ay may 50% tsansang mapasailalim sa Taunt ng 2 turn, na pinipilit ang lahat ng kanilang atake na mapunta kay Jiren. Sa panahong ito, tumataas ang tibay ni Jiren, nababawasan ang pinsalang natatanggap ng 20% sa loob ng 2 turn, tumatayo bilang bakal na kalasag para protektahan ang kanyang mga kakampi. Bukod pa rito, lumilikha si Jiren ng shield na katumbas ng 10% Max HP para sa sarili niya at sa kakampi na may pinakamababang kasalukuyang HP sa koponan sa loob ng 2 turn.',
		zawakeEffectDesc_ma = 'Jiren melepaskan tenaga pemusnah yang membara, memberikan #C0xE69900#240% ATK Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B# kepada 3 musuh rawak. Gelombang kejutan dari serangan ini memperlahankan musuh, mengurangkan Kelajuan Pergerakan sebanyak 10% dan menyebabkan mereka menerima 20% lebih banyak kerosakan selama 2 giliran berikutnya.\n<Berkorban demi Rakan>: Apabila HP Maks Jiren melebihi 60%, musuh yang terkena serangan mempunyai 50% peluang untuk terkena status Taunt selama 2 giliran, memaksa semua serangan mereka tertumpu kepada Jiren. Sepanjang tempoh ini, Jiren mendapat ketahanan, mengurangkan kerosakan yang diterima sebanyak 20% selama 2 giliran, berdiri teguh sebagai perisai besi yang melindungi rakan sepasukannya. Selain itu, Jiren mencipta perisai bersamaan dengan 10% HP Maks untuk dirinya sendiri dan rakan yang mempunyai HP semasa paling rendah dalam pasukan selama 2 giliran.',
		zawakeEffectDesc_vn = 'Jiren giải phóng luồng năng lượng hủy diệt nóng bỏng gây #C0xE69900#240% Công V.Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# lên 3 mục tiêu ngẫu nhiên. Sóng xung kích từ đòn đánh khiến kẻ địch chậm lại, giảm 10% Tốc Độ Di Chuyển và chịu thêm 20% sát thương trong 2 lượt tiếp theo.\n<Hi sinh vì đồng đội>: Khi lượng máu tối đa của Jiren trên 60% những kẻ bị trúng chiêu có 50% khả năng sẽ rơi vào trạng thái Khiêu Khích trong 2 lượt, buộc mọi đòn tấn công của chúng đều nhằm vào Jiren. Trong thời gian này, Jiren được gia tăng sức chịu đựng, giảm 20% sát thương nhận vào suốt 2 lượt, đứng vững như tấm khiên thép che chở cho đồng đội. Ngoài ra Jiren dựng nên lá chắn tương đương 10% Máu Tối Đa cho bản thân và đồng đội có lượng máu hiện tại thấp nhất trong đội trong 2 lượt.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Jiren creates a shield equal to 10% of Max HP for himself and the ally with the lowest current HP in the team for 2 turns.',
		zawakeSimpleDesc_en = 'Jiren creates a shield equal to 10% of Max HP for himself and the ally with the lowest current HP in the team for 2 turns.',
		zawakeSimpleDesc_th = 'Jiren สร้างโล่เท่ากับ 10% ของ HP สูงสุดให้ตัวเองและพันธมิตรที่มี HP ปัจจุบันต่ำที่สุดในทีม เป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Jiren membuat perisai setara 10% HP Maksimum untuk dirinya sendiri dan sekutu dengan HP saat ini terendah dalam tim selama 2 giliran',
		zawakeSimpleDesc_ph = 'Lumilikha si Jiren ng shield na katumbas ng 10% ng Max HP para sa kanya at sa kaalyadong may pinakamababang kasalukuyang HP sa koponan sa loob ng 2 turn',
		zawakeSimpleDesc_ma = 'Jiren mewujudkan perisai bersamaan dengan 10% HP Maksimum untuk dirinya sendiri dan sekutu dengan HP semasa terendah dalam pasukan selama 2 pusingan',
		zawakeSimpleDesc_vn = 'Jiren dựng nên lá chắn tương đương 10% Máu Tối Đa cho bản thân và đồng đội có lượng máu hiện tại thấp nhất trong đội trong  2 lượt.',
		iconRes = 'battle/skill_icon/skill_81022.png',
