	[981023] = {
		id = 981023,
		skillName_vn = 'Cực Nhiệt Sóng Hủy Diệt',
		skillName_en = 'Extreme Heat Destructive Wave',
		skillName_th = 'คลื่นทำลายร้อนสุดขั้ว',
		skillName_in = 'Gelombang Penghancur Ekstrem Panas',
		skillName_ph = 'Pinakamalupit na Init na Alon ng Pagwasak',
		skillName_ma = 'Gelombang Pemusnah Panas Ekstrem',
		skillName = 'Extreme Heat Destructive Wave',
		describe_vn = 'Jiren tập trung sức mạnh tối thượng, niệm lực trong tay và ném một nguồn năng lượng huỷ diệt lên kẻ thù, gây #C0xE69900#300% Công V.Lý#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# sát thương vật lý lên tất cả kẻ địch. Những kẻ trúng đòn sẽ bị Tổn Thương, khiến chúng nhận thêm 20% sát thương trong 2 lượt tiếp theo, và hiệu ứng này không thể bị xóa. Nếu sau đòn tấn công, Máu Tối Đa hiện tại của kẻ địch dưới 10%, Jiren lập tức kích hoạt <Kết Liễu Nhân Đạo>, tiêu diệt ngay mục tiêu, bỏ qua mọi phòng thủ và kể cả các khả năng miễn nhiễm sát thương kết liễu.',
		describe_en = 'Jiren focuses his ultimate power, channels psychic energy in his hands, and hurls a destructive energy at enemies, dealing #C0xE69900#300% Physical ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B# to all enemies. Targets hit will suffer Injured status, taking an additional 20% damage for the next 2 turns, and this effect cannot be removed. If after the attack the enemy’s current Max HP is below 10%, Jiren instantly activates <Merciful Finish>, immediately eliminating the target, bypassing all defenses and any immunity to finishing damage.',
		describe_th = 'จิเรนรวมพลังสูงสุด ใช้พลังจิตในมือและขว้างพลังทำลายล้างไปยังศัตรู สร้างความเสียหาย #C0xE69900#300% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ไปยังศัตรูทั้งหมด ศัตรูที่ถูกโจมตีจะได้รับสถานะบาดเจ็บ ทำให้รับความเสียหายเพิ่ม 20% เป็นเวลา 2 เทิร์นต่อไป และเอฟเฟกต์นี้ไม่สามารถลบออกได้ หากหลังจากโจมตี พลังชีวิตปัจจุบันของศัตรูต่ำกว่า 10% จิเรนจะเปิดใช้งาน <จบชีวิตอย่างเมตตา> ทันที กำจัดเป้าหมายโดยตรง ข้ามการป้องกันทั้งหมด รวมถึงความสามารถในการต้านทานความเสียหายรุนแรง',
		describe_in = 'Jiren memfokuskan kekuatan tertinggi, menyalurkan energi psikis di tangannya, dan melemparkan energi destruktif ke musuh, memberikan #C0xE69900#300% Serangan Fisik#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Damage Fisik#C0x5B545B# ke semua musuh. Musuh yang terkena akan mengalami status Terluka, menerima tambahan 20% damage selama 2 giliran berikutnya, dan efek ini tidak dapat dihapus. Jika setelah serangan HP Maksimum musuh saat ini di bawah 10%, Jiren segera mengaktifkan <Penyelesaian Belas Kasih>, langsung mengeliminasi target, melewati semua pertahanan dan semua kemampuan kekebalan terhadap damage finishing.',
		describe_ph = 'Pinagtutuunan ni Jiren ang kanyang ultimate na lakas, nag-channel ng psychic energy sa kanyang mga kamay, at hinahagis ang nakawasak na enerhiya sa mga kaaway, nagdudulot ng #C0xE69900#300% Physical ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B# sa lahat ng kaaway. Ang mga target na tinamaan ay magkakaroon ng Injured status, tumatanggap ng karagdagang 20% damage sa susunod na 2 turn, at ang epektong ito ay hindi maaaring alisin. Kung pagkatapos ng atake ang kasalukuyang Max HP ng kaaway ay mas mababa sa 10%, agad na ia-activate ni Jiren ang <Merciful Finish>, agad na nililinisan ang target, nilalampasan ang lahat ng depensa at anumang immunity sa finishing damage.',
		describe_ma = 'Jiren menumpukan kuasa tertinggi, menyalurkan tenaga psionik di tangannya, dan melemparkan tenaga pemusnah ke musuh, menyebabkan #C0xE69900#300% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerosakan Fizikal#C0x5B545B# ke semua musuh. Sasaran yang terkena akan menerima status Cedera, menerima 20% kerosakan tambahan selama 2 pusingan berikutnya, dan kesan ini tidak boleh dibuang. Jika selepas serangan HP Maksimum musuh semasa di bawah 10%, Jiren segera mengaktifkan <Penyudahan Berbelas Kasih>, serta-merta menyingkirkan sasaran, mengabaikan semua pertahanan dan mana-mana kebal terhadap kerosakan penyudahan.',
		describe = 'Jiren focuses his ultimate power, channels psychic energy in his hands, and hurls a destructive energy at enemies, dealing #C0xE69900#300% Physical ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B# to all enemies. Targets hit will suffer Injured status, taking an additional 20% damage for the next 2 turns, and this effect cannot be removed. If after the attack the enemy’s current Max HP is below 10%, Jiren instantly activates <Merciful Finish>, immediately eliminating the target, bypassing all defenses and any immunity to finishing damage.',
		simDesc = 'Jiren tập trung sức mạnh tối thượng, niệm lực trong tay và ném một hành tinh vào kẻ địch sát thương vật lý lên tất cả kẻ địch. Kẻ địch bị tấn công bởi hành tinh sẽ bị tổn thương (nhận thêm 20% sát thương) trong 2 lượt tiếp theo và debuff này không thể bị xoá). Khả năng kết liễu đối thủ dưới 10% máu.',
		starEffect = __data_t__starEffect[981023],
		-- {11}
		starEffectDesc_vn = 'Dư chấn từ vụ nổ gây thêm sát thương vật lý cho hàng trước của địch tương đương với 10% sát thương từ kĩ năng và gây thêm sát thương vật lý cho hàng sau của địch đương với 25% sát thương từ kĩ năng. Đồng thời, đối thủ sẽ bị 30% tỷ lệ choáng trong 1 lượt sau khi bị tấn công bởi kỹ năng này. ',
		starEffectDesc = 'The shockwave from the explosion deals additional physical damage to the enemy’s front row equal to 10% of the skill’s damage and additional physical damage to the enemy’s back row equal to 25% of the skill’s damage. At the same time, enemies have a 30% chance to be stunned for 1 turn after being hit by this skill.',
		starEffectDesc_en = 'The shockwave from the explosion deals additional physical damage to the enemy’s front row equal to 10% of the skill’s damage and additional physical damage to the enemy’s back row equal to 25% of the skill’s damage. At the same time, enemies have a 30% chance to be stunned for 1 turn after being hit by this skill.',
		starEffectDesc_th = 'แรงสะเทือนจากการระเบิดจะสร้างความเสียหายกายภาพเพิ่มเติมแก่แถวหน้าของศัตรู เท่ากับ 10% ของความเสียหายจากสกิล และสร้างความเสียหายกายภาพเพิ่มเติมแก่แถวหลังของศัตรู เท่ากับ 25% ของความเสียหายจากสกิล นอกจากนี้ ศัตรูยังมีโอกาส 30% ที่จะติดสตันเป็นเวลา 1 เทิร์นหลังจากถูกโจมตีด้วยสกิลนี้',
		starEffectDesc_in = 'Guncangan dari ledakan memberikan damage fisik tambahan pada barisan depan musuh sebesar 10% dari damage skill dan memberikan damage fisik tambahan pada barisan belakang musuh sebesar 25% dari damage skill. Selain itu, musuh memiliki 30% peluang terkena stun selama 1 giliran setelah diserang oleh skill ini.',
		starEffectDesc_ph = 'Ang pagyanig mula sa pagsabog ay nagdudulot ng karagdagang pisikal na pinsala sa front row ng kalaban na katumbas ng 10% ng damage ng skill at karagdagang pisikal na pinsala sa back row ng kalaban na katumbas ng 25% ng damage ng skill. Kasabay nito, ang mga kalaban ay may 30% na tsansa na ma-stun sa loob ng 1 turn matapos tamaan ng skill na ito.',
		starEffectDesc_ma = 'Kesan gegaran daripada letupan menyebabkan tambahan kerosakan fizikal kepada barisan hadapan musuh bersamaan dengan 10% daripada kerosakan kemahiran dan tambahan kerosakan fizikal kepada barisan belakang musuh bersamaan dengan 25% daripada kerosakan kemahiran. Pada masa yang sama, musuh mempunyai 30% peluang untuk terkena stun selama 1 giliran selepas diserang oleh kemahiran ini.',
		zawakeEffect = __data_t__zawakeEffect[981023],
		-- {79003}
		zawakeEffectDesc = 'Jiren focuses his ultimate power, channeling psychic energy in his hands and hurling a destructive blast at all enemies, dealing #C0xE69900#300% Physical ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B#. Enemies hit will be inflicted with Wounded, causing them to take 30% more damage for 2 turns, and this effect cannot be removed. If after the attack, the enemy’s current Max HP is below 10%, Jiren immediately activates <Humane Execution>, instantly killing the target, ignoring all defenses and even abilities that grant immunity to execution damage.',
		zawakeEffectDesc_en = 'Jiren focuses his ultimate power, channeling psychic energy in his hands and hurling a destructive blast at all enemies, dealing #C0xE69900#300% Physical ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Physical Damage#C0x5B545B#. Enemies hit will be inflicted with Wounded, causing them to take 30% more damage for 2 turns, and this effect cannot be removed. If after the attack, the enemy’s current Max HP is below 10%, Jiren immediately activates <Humane Execution>, instantly killing the target, ignoring all defenses and even abilities that grant immunity to execution damage.',
		zawakeEffectDesc_th = 'จิเรนรวบรวมพลังสูงสุด ใช้พลังจิตในมือแล้วขว้างพลังทำลายล้างใส่ศัตรูทั้งหมด สร้างความเสียหาย #C0xE69900#300% กำลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# ศัตรูที่ถูกโจมตีจะติดสถานะ “บาดเจ็บ” ทำให้ได้รับความเสียหายเพิ่มขึ้น 30% เป็นเวลา 2 เทิร์น และเอฟเฟกต์นี้ไม่สามารถถูกลบได้ หากหลังการโจมตี ค่าพลังชีวิตสูงสุดปัจจุบันของศัตรูต่ำกว่า 10% จิเรนจะเปิดใช้งาน <การประหารด้วยเมตตา> สังหารศัตรูทันที โดยไม่สนการป้องกันหรือความสามารถที่ป้องกันการถูกประหาร',
		zawakeEffectDesc_in = 'Jiren memusatkan kekuatan tertinggi, menyalurkan energi psikis di tangannya dan melemparkan ledakan penghancur ke semua musuh, memberikan #C0xE69900#300% ATK Fisik#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Damage Fisik#C0x5B545B#. Musuh yang terkena akan terkena status Terluka, membuat mereka menerima 30% damage lebih banyak selama 2 giliran, dan efek ini tidak dapat dihapus. Jika setelah serangan, HP Maks saat ini musuh berada di bawah 10%, Jiren langsung mengaktifkan <Eksekusi Manusiawi>, membunuh target seketika, mengabaikan semua pertahanan bahkan kemampuan kebal terhadap damage eksekusi.',
		zawakeEffectDesc_ph = 'Itinatutok ni Jiren ang kanyang sukdulang lakas, kinokolekta ang enerhiya ng isip sa kanyang mga kamay at inihahagis ang isang mapanirang pagsabog sa lahat ng kaaway, nagdudulot ng #C0xE69900#300% Pisikal na ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Pisikal na Pinsala#C0x5B545B#. Ang mga kalabang tinamaan ay magkakaroon ng Wounded, na magpapadagdag ng 30% pinsala na matatanggap nila sa loob ng 2 turn, at ang epektong ito ay hindi maaaring alisin. Kung pagkatapos ng atake, ang kasalukuyang Max HP ng kalaban ay mas mababa sa 10%, agad na i-a-activate ni Jiren ang <Makataong Pagpapatay>, kaagad na pinapatay ang target, hindi pinapansin ang anumang depensa at kahit mga kakayahan na nagbibigay ng immunity laban sa execution damage.',
		zawakeEffectDesc_ma = 'Jiren memfokuskan kuasa mutlaknya, menyalurkan tenaga minda di tangannya lalu melontarkan letupan pemusnah ke semua musuh, memberikan #C0xE69900#300% ATK Fizikal#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Kerusakan Fizikal#C0x5B545B#. Musuh yang terkena akan dikenakan status Cedera, menyebabkan mereka menerima 30% lebih banyak kerusakan selama 2 giliran, dan kesan ini tidak dapat dihapus. Jika selepas serangan, HP Maks semasa musuh berada di bawah 10%, Jiren segera mengaktifkan <Penyudah Berperikemanusiaan>, membunuh sasaran serta-merta, mengabaikan semua pertahanan dan juga kebolehan yang memberi imuniti terhadap kerusakan penyudah.',
		zawakeEffectDesc_vn = 'Jiren tập trung sức mạnh tối thượng, niệm lực trong tay và ném một nguồn năng lượng huỷ diệt lên kẻ thù, gây #C0xE69900#300% Công V.Lý#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B# sát thương vật lý lên tất cả kẻ địch. Những kẻ trúng đòn sẽ bị Tổn Thương, khiến chúng nhận thêm 30% sát thương trong 2 lượt tiếp theo, và hiệu ứng này không thể bị xóa. Nếu sau đòn tấn công, Máu Tối Đa hiện tại của kẻ địch dưới 10%, Jiren lập tức kích hoạt <Kết Liễu Nhân Đạo>, tiêu diệt ngay mục tiêu, bỏ qua mọi phòng thủ và kể cả các khả năng miễn nhiễm sát thương kết liễu.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Targets hit will be Afflicted, causing them to take an additional 30% damage for the next 2 turns, and this effect cannot be removed.',
		zawakeSimpleDesc_en = 'Targets hit will be Afflicted, causing them to take an additional 30% damage for the next 2 turns, and this effect cannot be removed.',
		zawakeSimpleDesc_th = 'เป้าหมายที่โดนโจมตีจะติดสถานะ Afflicted ทำให้ได้รับความเสียหายเพิ่ม 30% ใน 2 เทิร์นถัดไป และเอฟเฟกต์นี้ไม่สามารถลบออกได้',
		zawakeSimpleDesc_in = 'Target yang terkena akan Terkoyak, membuat mereka menerima tambahan 30% kerusakan selama 2 giliran berikutnya, dan efek ini tidak dapat dihapus',
		zawakeSimpleDesc_ph = 'Ang mga target na tinamaan ay magkakaroon ng Afflicted, na magdudulot sa kanila ng karagdagang 30% pinsala sa susunod na 2 turn, at hindi maaaring alisin ang epektong ito',
		zawakeSimpleDesc_ma = 'Sasaran yang terkena akan Terjejas, menyebabkan mereka menerima tambahan 30% kerosakan untuk 2 pusingan berikutnya, dan kesan ini tidak boleh dibuang',
		zawakeSimpleDesc_vn = 'Những kẻ trúng đòn sẽ bị Tổn Thương, khiến chúng nhận thêm 20% sát thương trong 2 lượt tiếp theo, và hiệu ứng này không thể bị xóa. \n#F20# \n#F40##C0x5c9970#→  Những kẻ trúng đòn sẽ bị Tổn Thương, khiến chúng nhận thêm 30% sát thương trong 2 lượt tiếp theo, và hiệu ứng này không thể bị xóa.',
		iconRes = 'battle/skill_icon/skill_81023.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 2,
		skillNatureType = 16,
		targetTypeDesc = 'All Enemies',
