	},
	[981026] = {
		id = 981026,
		skillName_vn = 'Ý chí của anh hùng',
		skillName_en = 'Heroic Will',
		skillName_th = 'จิตวิญญาณวีรบุรุษ',
		skillName_in = 'Kemauan Pahlawan',
		skillName_ph = 'Kalooban ng Bayani',
		skillName_ma = 'Keazaman Wira',
		skillName = 'Heroic Will',
		describe_vn = 'Khi nhận sát thương chí tử, Jiren vẫn kiên cường trụ lại, không thể bị tiêu diệt trong 1 lượt. Sau đó Jiren sẽ hồi lại #C0x5c9970#50% máu tối đa #C0x5B545B# +$(skillLevel*4*90)$. Tiếp đó, Jiren kích hoạt Khiêu Khích toàn bộ kẻ địch trong 2 lượt, buộc chúng dồn mọi đòn tấn công vào mình. Trong thời gian này, mỗi lượt bị tấn công sẽ gia tăng 10% Tấn Công cho Jiren và đồng đội (riêng hệ Đấu nhận gấp đôi), đồng thời buff này không thể bị xóa và duy trì 3 lượt, đồng thời, Jiren được gia tăng sức chịu đựng, giảm 20% sát thương nhận vào suốt 2 lượt.',
		describe_en = 'When receiving lethal damage, Jiren remains resilient, unable to be defeated for 1 turn. Afterwards, Jiren restores #C0x5c9970#50% Max HP #C0x5B545B# +$(skillLevel*4*90)$. Then, Jiren activates Taunt on all enemies for 2 turns, forcing them to direct all attacks at him. During this time, each turn he is attacked increases Jiren’s and allies’ Attack by 10% (Fighter-type allies receive double), and this buff cannot be removed and lasts for 3 turns. Additionally, Jiren gains increased durability, reducing damage taken by 20% for 2 turns.',
		describe_th = 'เมื่อได้รับความเสียหายรุนแรง จิเรนยังคงอดทน ไม่สามารถถูกกำจัดได้เป็นเวลา 1 เทิร์น จากนั้นจิเรนจะฟื้นฟู #C0x5c9970#50% พลังชีวิตสูงสุด #C0x5B545B# +$(skillLevel*4*90)$ ต่อมา จิเรนเปิดใช้งานสถานะยั่วโมโห (Taunt) กับศัตรูทั้งหมดเป็นเวลา 2 เทิร์น บังคับให้พวกเขาโจมตีเขาทุกครั้ง ในระหว่างนี้ ทุกครั้งที่เขาถูกโจมตีจะเพิ่มพลังโจมตีของจิเรนและพันธมิตร 10% (พันธมิตรประเภท Fighter รับสองเท่า) เอฟเฟกต์นี้ไม่สามารถลบออกและคงอยู่ 3 เทิร์น พร้อมทั้งจิเรนได้รับความทนทานเพิ่ม ลดความเสียหายที่ได้รับ 20% เป็นเวลา 2 เทิร์น',
		describe_in = 'Saat menerima damage mematikan, Jiren tetap tangguh, tidak bisa dikalahkan selama 1 giliran. Setelah itu, Jiren memulihkan #C0x5c9970#50% HP Maksimum #C0x5B545B# +$(skillLevel*4*90)$. Selanjutnya, Jiren mengaktifkan Taunt ke semua musuh selama 2 giliran, memaksa mereka mengarahkan semua serangan ke dirinya. Selama waktu ini, setiap giliran ia diserang akan meningkatkan Serangan Jiren dan sekutu sebesar 10% (sekutu tipe Fighter menerima dua kali lipat), dan buff ini tidak dapat dihapus serta bertahan 3 giliran. Selain itu, Jiren mendapatkan daya tahan tambahan, mengurangi damage yang diterima sebesar 20% selama 2 giliran.',
		describe_ph = 'Kapag tumanggap ng nakamamatay na pinsala, nananatiling matatag si Jiren, hindi maaaring mapatay sa loob ng 1 turn. Pagkatapos, si Jiren ay nagre-restore ng #C0x5c9970#50% Max HP #C0x5B545B# +$(skillLevel*4*90)$. Pagkatapos, ini-activate ni Jiren ang Taunt sa lahat ng kaaway sa loob ng 2 turn, pinipilit silang ituon lahat ng atake sa kanya. Sa panahong ito, bawat turn na siya ay tinatamaan ay nagdaragdag ng 10% Attack sa Jiren at sa mga kakampi (Fighter-type allies ay tumatanggap ng doble), at ang buff na ito ay hindi maaaring alisin at tumatagal ng 3 turn. Bukod dito, nakakakuha si Jiren ng dagdag na tibay, binabawasan ang damage na natatanggap ng 20% sa loob ng 2 turn.',
		describe_ma = 'Apabila menerima kerosakan maut, Jiren tetap tabah, tidak boleh dikalahkan selama 1 pusingan. Selepas itu, Jiren memulihkan #C0x5c9970#50% HP Maksimum #C0x5B545B# +$(skillLevel*4*90)$. Kemudian, Jiren mengaktifkan Taunt ke semua musuh selama 2 pusingan, memaksa mereka mengarahkan semua serangan ke dirinya. Sepanjang tempoh ini, setiap pusingan dia diserang akan meningkatkan Serangan Jiren dan sekutu sebanyak 10% (sekutu jenis Fighter menerima dua kali ganda), dan buff ini tidak boleh dibuang dan bertahan 3 pusingan. Selain itu, Jiren memperoleh daya tahan tambahan, mengurangkan kerosakan diterima sebanyak 20% selama 2 pusingan.',
		describe = 'When receiving lethal damage, Jiren remains resilient, unable to be defeated for 1 turn. Afterwards, Jiren restores #C0x5c9970#50% Max HP #C0x5B545B# +$(skillLevel*4*90)$. Then, Jiren activates Taunt on all enemies for 2 turns, forcing them to direct all attacks at him. During this time, each turn he is attacked increases Jiren’s and allies’ Attack by 10% (Fighter-type allies receive double), and this buff cannot be removed and lasts for 3 turns. Additionally, Jiren gains increased durability, reducing damage taken by 20% for 2 turns.',
		simDesc = 'Khi nhận sát thương gây tử vong, Jiren vẫn giữ bản thân còn sống và hồi lại 50% máu. Đồng thời, Jiren kích hoạt khiêu khích tất cả kẻ địch.',
		starEffect = __data_t__starEffect[981026],
		-- {8}
		starEffectDesc_vn = 'Khi đạt mốc 8 sao,Lượng máu mà Jiren nhận được tăng lên #C0x5c9970#60% máu tối đa #C0x5B545B# +$(skillLevel*4*90)$  Jiren kích hoạt khiêu khích kẻ địch sẽ tăng 20% kháng khống chế và tạo lá chắn bằng 20% máu tối đa của Jiren cho tất cả đồng đội trong 2 lượt( hệ đấu nhận gấp đôi)',
		starEffectDesc = 'At 8 stars, the HP Jiren gains increases to #C0x5c9970#60% of Max HP #C0x5B545B# +$(skillLevel*4*90)$. When Jiren activates Taunt on enemies, he gains 20% Control Resistance and creates a shield equal to 20% of Jiren’s Max HP for all allies for 2 turns (Warrior class receives double effect).',
		starEffectDesc_en = 'At 8 stars, the HP Jiren gains increases to #C0x5c9970#60% of Max HP #C0x5B545B# +$(skillLevel*4*90)$. When Jiren activates Taunt on enemies, he gains 20% Control Resistance and creates a shield equal to 20% of Jiren’s Max HP for all allies for 2 turns (Warrior class receives double effect).',
		starEffectDesc_th = 'เมื่อถึงระดับ 8 ดาว ค่าพลังชีวิตที่ Jiren ได้รับจะเพิ่มขึ้นเป็น #C0x5c9970#60% ของ HP สูงสุด #C0x5B545B# +$(skillLevel*4*90)$ เมื่อ Jiren ใช้การยั่วยุศัตรู จะได้รับค่าต้านทานการควบคุมเพิ่มขึ้น 20% และสร้างโล่เท่ากับ 20% ของ HP สูงสุดของ Jiren ให้กับพันธมิตรทั้งหมดเป็นเวลา 2 เทิร์น (สายนักสู้จะได้รับผลลัพธ์เป็นสองเท่า)',
		starEffectDesc_in = 'Saat mencapai 8 bintang, HP yang diperoleh Jiren meningkat menjadi #C0x5c9970#60% dari HP Maksimum #C0x5B545B# +$(skillLevel*4*90)$. Ketika Jiren mengaktifkan Taunt pada musuh, ia mendapatkan 20% Resist Kontrol dan menciptakan perisai sebesar 20% dari HP Maksimum Jiren untuk semua rekan tim selama 2 giliran (kelas Petarung menerima efek ganda).',
		starEffectDesc_ph = 'Kapag umabot sa 8 bituin, ang HP na nakukuha ni Jiren ay tumataas sa #C0x5c9970#60% ng Max HP #C0x5B545B# +$(skillLevel*4*90)$. Kapag in-activate ni Jiren ang Taunt laban sa kalaban, makakakuha siya ng 20% Control Resistance at lilikha ng shield na katumbas ng 20% ng Max HP ni Jiren para sa lahat ng kakampi sa loob ng 2 turn (ang Warrior class ay makakakuha ng dobleng epekto).',
		starEffectDesc_ma = 'Apabila mencapai 8 bintang, HP yang diterima oleh Jiren meningkat kepada #C0x5c9970#60% daripada HP Maksimum #C0x5B545B# +$(skillLevel*4*90)$. Apabila Jiren mengaktifkan Taunt pada musuh, dia mendapat 20% Rintangan Kawalan dan mencipta perisai bersamaan dengan 20% daripada HP Maksimum Jiren untuk semua sekutu selama 2 giliran (kelas Pejuang menerima kesan berganda).',
		zawakeEffect = __data_t__zawakeEffect[981026],
		-- {79004, 1}
		zawakeEffectDesc = 'At 8 stars, the HP Jiren gains increases by #C0x5c9970#60% of Max HP#C0x5B545B# +$(skillLevel*4*90)$. When Jiren activates Taunt on enemies, he gains 30% Control Resistance and creates a shield equal to 20% of Jiren\'s Max HP for all allies for 2 turns (Fighter-type allies receive double).',
		zawakeEffectDesc_en = 'At 8 stars, the HP Jiren gains increases by #C0x5c9970#60% of Max HP#C0x5B545B# +$(skillLevel*4*90)$. When Jiren activates Taunt on enemies, he gains 30% Control Resistance and creates a shield equal to 20% of Jiren\'s Max HP for all allies for 2 turns (Fighter-type allies receive double).',
		zawakeEffectDesc_th = 'เมื่อถึงระดับ 8 ดาว ค่าพลังชีวิตที่ Jiren ได้รับจะเพิ่มขึ้น #C0x5c9970#60% ของพลังชีวิตสูงสุด#C0x5B545B# +$(skillLevel*4*90)$ เมื่อ Jiren ใช้การยั่วยุศัตรู จะได้รับการต้านทานการควบคุม 30% และสร้างเกราะป้องกันเท่ากับ 20% ของพลังชีวิตสูงสุดของ Jiren ให้กับพันธมิตรทั้งหมดเป็นเวลา 2 เทิร์น (พันธมิตรสายต่อสู้จะได้รับเป็นสองเท่า)',
		zawakeEffectDesc_in = 'Saat mencapai 8 bintang, HP yang diperoleh Jiren meningkat sebesar #C0x5c9970#60% dari HP Maks#C0x5B545B# +$(skillLevel*4*90)$. Saat Jiren mengaktifkan Taunt pada musuh, ia mendapatkan 30% Resist Kontrol dan menciptakan perisai sebesar 20% dari HP Maks Jiren untuk semua rekan tim selama 2 giliran (tipe Petarung menerima dua kali lipat).',
		zawakeEffectDesc_ph = 'Kapag umabot sa 8 bituin, tataas ang HP na natatanggap ni Jiren ng #C0x5c9970#60% ng Max HP#C0x5B545B# +$(skillLevel*4*90)$. Kapag in-activate ni Jiren ang Taunt laban sa kalaban, makakakuha siya ng 30% Control Resistance at lilikha ng shield na katumbas ng 20% ng Max HP ni Jiren para sa lahat ng kakampi sa loob ng 2 turn (ang mga Fighter-type na kakampi ay makakatanggap ng doble).',
		zawakeEffectDesc_ma = 'Apabila mencapai 8 bintang, HP yang diperoleh Jiren meningkat sebanyak #C0x5c9970#60% daripada HP Maks#C0x5B545B# +$(skillLevel*4*90)$. Apabila Jiren mengaktifkan Taunt pada musuh, dia mendapat 30% Rintangan Kawalan dan mencipta perisai bersamaan 20% daripada HP Maks Jiren untuk semua sekutu selama 2 giliran (sekutu jenis Pejuang menerima dua kali ganda).',
		zawakeEffectDesc_vn = 'Khi đạt mốc 8 sao,Lượng máu mà Jiren nhận được tăng lên #C0x5c9970#60% máu tối đa #C0x5B545B# +$(skillLevel*4*90)$  Jiren kích hoạt khiêu khích kẻ địch sẽ tăng 30% kháng khống chế và tạo lá chắn bằng 20% máu tối đa của Jiren cho tất cả đồng đội trong 2 lượt( hệ đấu nhận gấp đôi)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'While taunting enemies, each time Jiren is attacked, he recovers 10% of his Max HP.',
		zawakeSimpleDesc_en = 'While taunting enemies, each time Jiren is attacked, he recovers 10% of his Max HP.',
		zawakeSimpleDesc_th = 'ในระหว่างการล่อเป้าศัตรู ทุกครั้งที่ Jiren ถูกโจมตี เขาจะฟื้นฟู 10% ของ HP สูงสุดของตน',
		zawakeSimpleDesc_in = 'Selama menantang musuh, setiap kali Jiren diserang, ia memulihkan 10% HP Maksimalnya',
		zawakeSimpleDesc_ph = 'Habang nagta-taunt ng mga kaaway, sa tuwing tatamaan si Jiren, siya ay gagaling ng 10% ng kanyang Max HP',
		zawakeSimpleDesc_ma = 'Semasa menimbulkan provokasi terhadap musuh, setiap kali Jiren diserang, dia memulihkan 10% HP Maksimumnya',
		zawakeSimpleDesc_vn = 'Trong thời gian khiêu khích kẻ địch, mỗi khi bị tấn công Jiren hồi cho bản thân 10% máu tối đa.',
