	[1000033] = {
		id = 1000033,
		skillName_vn = 'Lửa mặt trời',
		skillName_en = 'Sun fire',
		skillName_th = 'ไฟดวงอาทิตย์',
		skillName_in = 'Api matahari',
		skillName_ph = 'Apoy ng araw',
		skillName_ma = 'Api matahari',
		skillName = 'Sun fire',
		describe_vn = 'Tích tụ ánh sáng mặt trời, sau đó bắn ra ngọn lửa mạnh mẽ tấn công mục tiêu kẻ địch, gây #C0x3D8A99#380% Phép Công#C0x5B545B#+$(skillLevel*60)$ sát thương #C0x8A5C99#phép thuật#C0x5B545B#, và hồi phục sinh mệnh cho toàn bộ đồng minh bằng #C0x3D8A99#150% Phép Công#C0x5B545B#, đồng thời có 30% xác suất thêm hiệu ứng quang hợp kéo dài 2 lượt, trong thời gian quang hợp, mỗi lượt hồi phục sinh mệnh bằng #C0x3D8A99#70% Phép Công#C0x5B545B#',
		describe_en = 'Accumulates sunlight, then fires a powerful flame to attack enemy targets, dealing #C0x3D8A99#380% Magic Attack#C0x5B545B# + $(skillLevel*60)$ #C0x8A5C99#magic#C0x5B545B# damage, and heals all allies for #C0x3D8A99#150% Magic Attack#C0x5B545B#. Additionally, has a 30% chance to apply a photosynthesis effect lasting 2 turns; during photosynthesis, each turn heals for #C0x3D8A99#70% Magic Attack#C0x5B545B# HP.',
		describe_th = 'สะสมแสงแดด จากนั้นปล่อยเปลวไฟที่ทรงพลังโจมตียังเป้าหมายศัตรู สร้างความเสียหาย #C0x3D8A99#380% พลังโจมตีเวทย์#C0x5B545B# + $(skillLevel*60)$ #C0x8A5C99#เวทย์#C0x5B545B# และฟื้นฟูพลังชีวิตให้เพื่อนร่วมทีมทั้งหมดโดยใช้ #C0x3D8A99#150% พลังโจมตีเวทย์#C0x5B545B# พร้อมทั้งมีโอกาส 30% ที่จะเพิ่มเอฟเฟกต์การสังเคราะห์แสงเป็นเวลา 2 เทิร์น ในช่วงเวลาการสังเคราะห์แสง จะฟื้นฟูพลังชีวิตทุกเทิร์นโดยใช้ #C0x3D8A99#70% พลังโจมตีเวทย์#C0x5B545B#',
		describe_in = 'Mengumpulkan sinar matahari, kemudian menembakkan api yang kuat untuk menyerang musuh, memberikan #C0x3D8A99#380% Serangan Sihir#C0x5B545B# + $(skillLevel*60)$ #C0x8A5C99#sihir#C0x5B545B# kerusakan, dan menyembuhkan seluruh sekutu dengan #C0x3D8A99#150% Serangan Sihir#C0x5B545B#. Selain itu, memiliki peluang 30% untuk menambahkan efek fotosintesis yang bertahan selama 2 giliran, selama fotosintesis, setiap giliran menyembuhkan sebanyak #C0x3D8A99#70% Serangan Sihir#C0x5B545B# HP.',
		describe_ph = 'Nagtitipon ng sikat ng araw, pagkatapos ay nagpapadala ng makapangyarihang apoy upang atakihin ang mga kalaban, na nagdudulot ng #C0x3D8A99#380% Magic Attack#C0x5B545B# + $(skillLevel*60)$ #C0x8A5C99#magic#C0x5B545B# na pinsala, at nagpapagaling sa lahat ng mga kakampi ng #C0x3D8A99#150% Magic Attack#C0x5B545B#. Kasabay nito, may 30% na tsansa na magdagdag ng photosynthesis effect na tumatagal ng 2 turn; habang nasa photosynthesis, bawat turn ay nagpapagaling ng buhay gamit ang #C0x3D8A99#70% Magic Attack#C0x5B545B#.',
		describe_ma = 'Mengumpul cahaya matahari, kemudian menembak api yang kuat untuk menyerang sasaran musuh, menyebabkan #C0x3D8A99#380% Serangan Sihir#C0x5B545B# + $(skillLevel*60)$ kerosakan #C0x8A5C99#sihir#C0x5B545B#, dan memulihkan nyawa kepada semua sekutu dengan #C0x3D8A99#150% Serangan Sihir#C0x5B545B#. Pada masa yang sama, terdapat 30% kemungkinan untuk menambah kesan fotosintesis selama 2 pusingan; semasa fotosintesis, setiap pusingan memulihkan nyawa sebanyak #C0x3D8A99#70% Serangan Sihir#C0x5B545B#.',
		describe = 'Accumulates sunlight, then fires a powerful flame to attack enemy targets, dealing #C0x3D8A99#380% Magic Attack#C0x5B545B# + $(skillLevel*60)$ #C0x8A5C99#magic#C0x5B545B# damage, and heals all allies for #C0x3D8A99#150% Magic Attack#C0x5B545B#. Additionally, has a 30% chance to apply a photosynthesis effect lasting 2 turns; during photosynthesis, each turn heals for #C0x3D8A99#70% Magic Attack#C0x5B545B# HP.',
