	[1000133] = {
		id = 1000133,
		skillName_vn = 'Phun lửa',
		skillName_en = 'Fire breath',
		skillName_th = 'พ่นไฟ',
		skillName_in = 'Menyemburkan api',
		skillName_ph = 'Umiilaw ng apoy',
		skillName_ma = 'Menyembur api',
		skillName = 'Fire breath',
		describe_vn = 'Bay lên không trung, phun lửa tấn công mục tiêu hàng ngang của kẻ địch, gây #C0x3D8A99#250% Phép Công#C0x5B545B#+$( skillLevel *36)$ sát thương #C0x8A5C99#phép thuật#C0x5B545B#, nếu đơn vị kẻ địch có hiệu ứng đốt cháy, sát thương lần này tăng 25%; đồng thời có 60% xác suất thêm hiệu ứng đốt cháy (hiệu ứng đốt cháy có thể cộng dồn, mỗi tầng gây #C0x3D8A99#50% Phép Công#C0x5B545B# sát thương thực, kéo dài 2 lượt)',
		describe_en = 'Leaping into the air, unleashes a fiery attack on a horizontal line of enemy targets, dealing #C0x3D8A99#250% Magic Power#C0x5B545B# + $( skillLevel *36)$ #C0x8A5C99#magic#C0x5B545B# damage. If the enemy units are affected by Burn, the damage is increased by 25%; simultaneously, there is a 60% chance to apply the Burn effect (Burn can stack, each stack deals #C0x3D8A99#50% Magic Power#C0x5B545B# true damage, lasting 2 turns).',
		describe_th = 'พุ่งขึ้นสู่ท้องฟ้า พ่นไฟโจมตีเป้าหมายในแนวเดียวกันของศัตรู สร้างความเสียหาย #C0x3D8A99#250% พลังเวท#C0x5B545B# + $( skillLevel *36)$ #C0x8A5C99#เวทมนตร์#C0x5B545B# หากหน่วยศัตรูมีสถานะไฟไหม้ ความเสียหายจะเพิ่มขึ้น 25%; พร้อมกันนี้มีโอกาส 60% ที่จะเพิ่มสถานะไฟไหม้ (สถานะไฟไหม้สามารถทับซ้อนกันได้ แต่ละชั้นก่อให้เกิดความเสียหายจริง #C0x3D8A99#50% พลังเวท#C0x5B545B# ต่อเนื่องเป็นเวลา 2 เทิร์น)',
		describe_in = 'Melompat ke udara, menyemburkan api menyerang target barisan horizontal musuh, memberikan #C0x3D8A99#250% Kekuatan Sihir#C0x5B545B# + $( skillLevel *36)$ #C0x8A5C99#sihir#C0x5B545B# kerusakan. Jika unit musuh memiliki efek terbakar, kerusakan meningkat 25%; sekaligus ada peluang 60% untuk menambah efek terbakar (efek terbakar dapat bertumpuk, setiap tumpukan memberikan #C0x3D8A99#50% Kekuatan Sihir#C0x5B545B# kerusakan nyata, bertahan selama 2 giliran).',
		describe_ph = 'Lumilipad pataas sa himpapawid, bumubuga ng apoy upang atakihin ang mga target ng kalaban sa pahalang na linya, nagtutulot ng #C0x3D8A99#250% Kapangyarihan ng Mahika#C0x5B545B# + $( skillLevel *36)$ #C0x8A5C99#mahika#C0x5B545B# pinsala. Kung ang mga yunit ng kalaban ay may epekto ng pagkasunog, tumataas ang pinsala ng 25%; kasabay nito ay may 60% tsansa na magdagdag ng epekto ng pagkasunog (ang epekto ng pagkasunog ay maaaring mag-stack, bawat layer ay nagdudulot ng #C0x3D8A99#50% Kapangyarihan ng Mahika#C0x5B545B# tunay na pinsala, tumatagal ng 2 mga turn).',
		describe_ma = 'Melompat ke udara, memancarkan api menyerang sasaran barisan mendatar musuh, menyebabkan #C0x3D8A99#250% Kuasa Sihir#C0x5B545B# + $( skillLevel *36)$ #C0x8A5C99#sihir#C0x5B545B# kerosakan. Jika unit musuh mempunyai kesan terbakar, kerosakan kali ini meningkat 25%; serentak terdapat 60% peluang untuk menambah kesan terbakar (kesan terbakar boleh bertindih, setiap lapisan menyebabkan #C0x3D8A99#50% Kuasa Sihir#C0x5B545B# kerosakan sebenar, berlangsung selama 2 pusingan).',
		describe = 'Leaping into the air, unleashes a fiery attack on a horizontal line of enemy targets, dealing #C0x3D8A99#250% Magic Power#C0x5B545B# + $( skillLevel *36)$ #C0x8A5C99#magic#C0x5B545B# damage. If the enemy units are affected by Burn, the damage is increased by 25%; simultaneously, there is a 60% chance to apply the Burn effect (Burn can stack, each stack deals #C0x3D8A99#50% Magic Power#C0x5B545B# true damage, lasting 2 turns).',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
