	[1000933] = {
		id = 1000933,
		skillName_vn = 'Điện áp cao',
		skillName_en = 'High voltage',
		skillName_th = 'แรงดันไฟฟ้าสูง',
		skillName_in = 'Tegangan tinggi',
		skillName_ph = 'Mataas na boltahe',
		skillName_ma = 'Voltan tinggi',
		skillName = 'High voltage',
		describe_vn = 'Bao phủ toàn thân bằng dòng điện di chuyển nhanh tấn công, sau đó phóng ra sấm sét tấn công mục tiêu hàng ngang của kẻ địch, gây #C0x3D8A99#250% Phép Công#C0x5B545B#+$( skillLevel *36)$ sát thương #C0x8A5C99#phép thuật#C0x5B545B#, và có 50% xác suất làm choáng mục tiêu trong 2 lượt; nếu mục tiêu đã ở trạng thái choáng, sát thương lần này tăng 25%',
		describe_en = 'Envelop the entire body with rapidly moving electric currents to attack, then unleash lightning to strike a horizontal line of enemy targets, dealing #C0x3D8A99#250% Magic Attack#C0x5B545B#+$( skillLevel *36)$ #C0x8A5C99#magic#C0x5B545B# damage, with a 50% chance to stun the targets for 2 turns; if the targets are already stunned, the damage this time increases by 25%.',
		describe_th = 'ใช้ไฟฟ้าที่เคลื่อนที่เร็วคลุมทั่วร่างกายเพื่อโจมตี จากนั้นปล่อยสายฟ้าโจมตีเป้าหมายแนวตั้งตามแนวนอน ทำให้เกิดความเสียหาย #C0x3D8A99#250% พลังเวทย์#C0x5B545B#+$( skillLevel *36)$ #C0x8A5C99#เวทมนตร์#C0x5B545B# และมีโอกาส 50% ทำให้เป้าหมายติดสถานะมึนงงเป็นเวลา 2 เทิร์น; หากเป้าหมายอยู่ในสถานะมึนงงอยู่แล้ว ความเสียหายในครั้งนี้จะเพิ่มขึ้น 25%',
		describe_in = 'Menyelimuti seluruh tubuh dengan aliran listrik yang bergerak cepat untuk menyerang, kemudian melepaskan petir yang menyerang baris horizontal target musuh, menyebabkan #C0x3D8A99#250% Serangan Sihir#C0x5B545B#+$( skillLevel *36)$ #C0x8A5C99#sihir#C0x5B545B# kerusakan, dengan peluang 50% untuk membuat target terpukul stun selama 2 giliran; jika target sudah dalam kondisi stun, kerusakan kali ini meningkat 25%.',
		describe_ph = 'Bumalot ang buong katawan ng mabilis na gumagalaw na kuryenteng pang-atake, pagkatapos ay magpapalabas ng kidlat na umatake sa mga kaaway sa pahalang na linya, na nagdudulot ng #C0x3D8A99#250% Magic Attack#C0x5B545B#+$( skillLevel *36)$ #C0x8A5C99#magic#C0x5B545B# na pinsala, at may 50% na tsansa na ma-stun ang mga target sa loob ng 2 rounds; kung ang mga target ay naka-stun na, tataas ang pinsalang ito ng 25%.',
		describe_ma = 'Meliputi seluruh badan dengan arus elektrik yang bergerak pantas untuk menyerang, kemudian melepaskan kilat menyerang barisan mendatar sasaran musuh, menyebabkan #C0x3D8A99#250% Serangan Sihir#C0x5B545B#+$( skillLevel *36)$ #C0x8A5C99#sihir#C0x5B545B# kerosakan, dengan peluang 50% untuk membuat sasaran pengsan selama 2 pusingan; jika sasaran sudah berada dalam keadaan pengsan, kerosakan kali ini meningkat 25%.',
		describe = 'Envelop the entire body with rapidly moving electric currents to attack, then unleash lightning to strike a horizontal line of enemy targets, dealing #C0x3D8A99#250% Magic Attack#C0x5B545B#+$( skillLevel *36)$ #C0x8A5C99#magic#C0x5B545B# damage, with a 50% chance to stun the targets for 2 turns; if the targets are already stunned, the damage this time increases by 25%.',
