	[1005723] = {
		id = 1005723,
		skillName_vn = 'Kẹp bay trên không',
		skillName_en = 'Upper clamp on',
		skillName_th = 'ที่หนีบบน',
		skillName_in = 'Penjepit atas',
		skillName_ph = 'Itinataka sa itaas',
		skillName_ma = 'Pengapit atas',
		skillName = 'Upper clamp on',
		describe_vn = 'Scizor dùng sức mạnh lớn đánh bay mục tiêu, sau đó nhanh chóng truy kích, tấn công mục tiêu có lượng máu thấp nhất ở hàng sau của kẻ địch, gây Sát Thương Vật Lý với #C0xE69900#450% Công Vật Lý#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, hấp thụ 20% Công Vật Lý của mục tiêu. Lượng máu của mục tiêu càng thấp, sát thương càng cao, tối đa tăng thêm 50% sát thương, và hồi phục lượng máu bằng 150% Công Vật Lý của bản thân.',
		describe_en = 'Scizor uses great power to launch the target away, then quickly chases and attacks the enemy\'s backline target with the lowest HP, dealing Physical Damage of #C0xE69900#450% Physical Attack#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# Physical Damage#C0x5B545B#, absorbing 20% of the target\'s Physical Attack. The lower the target\'s HP, the higher the damage, with a maximum increase of 50% damage, and heals itself for 150% of its own Physical Attack.',
		describe_th = 'Scizor ใช้พลังมหาศาลโจมตีเป้าหมายให้กระเด็น จากนั้นรีบไล่ล่าและโจมตีเป้าหมายที่มีพลังชีวิตต่ำที่สุดในแถวหลังของศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#450% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ดูดซับพลังโจมตีทางกายภาพ 20% ของเป้าหมาย ยิ่งพลังชีวิตของเป้าหมายต่ำ ความเสียหายก็ยิ่งสูงขึ้น สูงสุดเพิ่มความเสียหายอีก 50% และฟื้นฟูพลังชีวิตโดยใช้พลังโจมตีทางกายภาพของตัวเอง 150%',
		describe_in = 'Scizor menggunakan kekuatan besar untuk menghantam target, kemudian dengan cepat mengejar dan menyerang target dengan HP terendah di barisan belakang musuh, menyebabkan Kerusakan Fisik sebesar #C0xE69900#450% Serangan Fisik#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, menyerap 20% Serangan Fisik target. Semakin rendah HP target, semakin besar kerusakannya, maksimal meningkat hingga 50% kerusakan tambahan, dan menyembuhkan dirinya sendiri sebesar 150% Serangan Fisik miliknya.',
		describe_ph = 'Gumagamit si Scizor ng malaking lakas para itaboy ang target, pagkatapos ay mabilis na hinahabol at inaatake ang target na may pinakamababang HP sa likurang hanay ng kalaban, na nagdudulot ng Physical Damage na #C0xE69900#450% Physical Attack#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# Physical Damage#C0x5B545B#, sumisipsip ng 20% ng Physical Attack ng target. Kapag mas mababa ang HP ng target, mas mataas ang damage, hanggang sa maximum na dagdag na 50% sa damage, at nagpapagaling ng HP gamit ang 150% ng sariling Physical Attack.',
		describe_ma = 'Scizor menggunakan kekuatan besar untuk menumbangkan sasaran, kemudian pantas memburu dan menyerang sasaran dengan HP terendah di barisan belakang musuh, menyebabkan Kerosakan Fizikal sebanyak #C0xE69900#450% Serangan Fizikal#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, menyerap 20% Serangan Fizikal sasaran. Semakin rendah HP sasaran, semakin tinggi kerosakan, maksimum peningkatan kerosakan sebanyak 50%, dan memulihkan HP dengan 150% Serangan Fizikal dirinya sendiri.',
		describe = 'Scizor uses great power to launch the target away, then quickly chases and attacks the enemy\'s backline target with the lowest HP, dealing Physical Damage of #C0xE69900#450% Physical Attack#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# Physical Damage#C0x5B545B#, absorbing 20% of the target\'s Physical Attack. The lower the target\'s HP, the higher the damage, with a maximum increase of 50% damage, and heals itself for 150% of its own Physical Attack.',
		simDesc_vn = 'Mega Scyther dùng sức mạnh lớn đánh bay mục tiêu, theo đuổi nhanh chóng, tấn công mục tiêu có máu thấp nhất ở hàng sau của đối phương và hấp thụ chỉ số tấn công vật lý của mục tiêu.',
		simDesc_en = 'Mega Scyther uses great power to knock back the target, quickly pursues, attacks the enemy with the lowest HP in the back row, and absorbs the target\'s physical attack stats.',
		simDesc_th = 'เมก้าไซเธอร์ใช้พลังมหาศาลผลักเป้าหมายออกไป ติดตามอย่างรวดเร็ว โจมตีศัตรูที่มี HP ต่ำที่สุดในแถวหลัง และดูดซับค่าสถานะการโจมตีทางกายภาพของเป้าหมาย',
		simDesc_in = 'Mega Scyther menggunakan kekuatan besar untuk menjatuhkan target, mengejar dengan cepat, menyerang musuh dengan HP terendah di barisan belakang, dan menyerap statistik serangan fisik target.',
		simDesc_ph = 'Gumagamit ang Mega Scyther ng malaking lakas upang itaboy ang target, mabilis na sumusunod, inaatake ang kalaban na may pinakamababang HP sa likurang linya, at sumisipsip ng pisikal na attack stats ng target.',
		simDesc_ma = 'Mega Scyther menggunakan kuasa besar untuk menolak sasaran, mengejar dengan pantas, menyerang musuh dengan HP terendah di barisan belakang, dan menyerap statistik serangan fizikal sasaran.',
		simDesc = 'Mega Scyther uses great power to knock back the target, quickly pursues, attacks the enemy with the lowest HP in the back row, and absorbs the target\'s physical attack stats.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		skillType2 = 2,
		skillNatureType = 12,
		hintChoose = 3,
		specialHintChoose = 2,
