		targetTypeDesc_en = 'Enemy\'s special unit',
		targetTypeDesc_th = 'ยูนิตพิเศษของศัตรู',
		targetTypeDesc_in = 'Unit khusus musuh',
		targetTypeDesc_ph = 'Espesyal na yunit ng kalaban',
