	[1006033] = {
		id = 1006033,
		skillName_vn = 'Lửa dung nham',
		skillName_en = 'Lava fire',
		skillName_th = 'ไฟลาวา',
		skillName_in = 'Api lava',
		skillName_ph = 'Apoy ng lava',
		skillName_ma = 'Api lava',
		skillName = 'Lava fire',
		describe_vn = 'Vịt lửa tập trung toàn bộ năng lượng trong cơ thể, phun ra lửa dung nham tấn công mục tiêu hàng trước kẻ địch, gây #C0x3D8A99#250% Công Phép#C0x5B545B#+$(skillLevel*42)$#C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, kèm theo hiệu ứng cháy, nếu mục tiêu đã bị cháy thì thêm hiệu ứng cháy dữ dội, kéo dài 2 lượt: đơn vị bị trạng thái cháy dữ dội khi bị kỹ năng thuộc tính lửa đánh trúng sẽ tạm thời tăng tỷ lệ chí mạng của kỹ năng này thêm 15%',
		describe_en = 'Fire Duck concentrates all the energy in its body, spewing molten fire to attack the front row of enemy targets, dealing #C0x3D8A99#250% Magic Power#C0x5B545B#+$(skillLevel*42)$#C0xF13B54# Magic Damage #C0x5B545B#, accompanied by a burn effect. If the target is already burning, it applies an intense burn effect that lasts 2 turns: units under the intense burn status hit by fire attribute skills temporarily gain an additional 15% critical rate for this skill.',
		describe_th = 'เป็ดไฟรวบรวมพลังงานทั้งหมดในร่างกาย พ่นไฟลาวาโจมตีเป้าหมายแถวหน้า ทำให้เกิด #C0x3D8A99#250% พลังเวทย์#C0x5B545B#+$(skillLevel*42)$#C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# พร้อมทั้งเอฟเฟกต์ไฟไหม้ หากเป้าหมายถูกไฟไหม้อยู่แล้ว จะเพิ่มเอฟเฟกต์ไฟไหม้รุนแรง คงอยู่ 2 เทิร์น: หน่วยที่อยู่ในสถานะไฟไหม้รุนแรงเมื่อตกเป็นเป้าหมายของสกิลธาตุไฟ จะได้รับอัตราคริติคอลเพิ่มขึ้นชั่วคราว 15% สำหรับสกิลนี้',
		describe_in = 'Bebek Api mengumpulkan seluruh energi dalam tubuhnya, memuntahkan api lava untuk menyerang barisan depan musuh, memberikan #C0x3D8A99#250% Kekuatan Sihir#C0x5B545B#+$(skillLevel*42)$#C0xF13B54# Kerusakan Sihir #C0x5B545B#, disertai efek terbakar. Jika target sudah terbakar, efek terbakar hebat akan ditambahkan yang bertahan selama 2 giliran: unit yang dalam status terbakar hebat saat terkena skill atribut api akan sementara mendapatkan tambahan 15% tingkat kritis untuk skill ini.',
		describe_ph = 'Ang Duck ng Apoy ay nagtitipon ng lahat ng enerhiya sa kanyang katawan, nagpapalabas ng apoy ng lawa upang atakehin ang mga target sa unahang hanay ng kaaway, nagdudulot ng #C0x3D8A99#250% Magic Power#C0x5B545B#+$(skillLevel*42)$#C0xF13B54# Magic Damage #C0x5B545B#, kasabay ng epekto ng pagkasunog. Kung ang target ay nasusunog na, magdadagdag ito ng matinding pagkasunog na tumatagal ng 2 na turn: ang yunit na may matinding status ng pagkasunog kapag tinamaan ng fire attribute skills ay pansamantalang tumatanggap ng dagdag na 15% crit rate para sa skill na ito.',
		describe_ma = 'Itik Api menumpukan semua tenaga dalam badannya, melontarkan api lava untuk menyerang barisan depan musuh, menyebabkan #C0x3D8A99#250% Kuasa Sihir#C0x5B545B#+$(skillLevel*42)$#C0xF13B54# Kerosakan Sihir #C0x5B545B#, disertai dengan kesan terbakar. Jika sasaran sudah terbakar, tambah kesan terbakar teruk yang berlangsung selama 2 pusingan: unit yang mendapat status terbakar teruk apabila terkena kemahiran elemen api sementara mendapat peningkatan kadar kritikal sebanyak 15% untuk kemahiran ini.',
		describe = 'Fire Duck concentrates all the energy in its body, spewing molten fire to attack the front row of enemy targets, dealing #C0x3D8A99#250% Magic Power#C0x5B545B#+$(skillLevel*42)$#C0xF13B54# Magic Damage #C0x5B545B#, accompanied by a burn effect. If the target is already burning, it applies an intense burn effect that lasts 2 turns: units under the intense burn status hit by fire attribute skills temporarily gain an additional 15% critical rate for this skill.',
		simDesc_vn = 'Vịt Mỏ Vịt Lửa tập trung toàn bộ năng lượng trong cơ thể, phun ra ngọn lửa dung nham tấn công mục tiêu ở hàng trước của kẻ thù; sát thương lần này tăng tỷ lệ chí mạng và có xác suất gây bỏng.',
		simDesc_en = 'Fire Duckbill Duck concentrates all the energy in its body, unleashing a molten flame to attack the enemy\'s front row; this attack increases critical hit rate and has a chance to inflict burn.',
		simDesc_th = 'เป็ดปากเป็ดไฟรวบรวมพลังงานทั้งหมดในร่างกาย ปล่อยเปลวไฟลาวาโจมตีเป้าหมายแถวหน้าของศัตรู; ความเสียหายในครั้งนี้เพิ่มอัตราคริติคอลและมีโอกาสทำให้ไฟลุกไหม้',
		simDesc_in = 'Bebek Paruh Bebek Api mengumpulkan seluruh energi dalam tubuhnya, memuntahkan api lava untuk menyerang target di barisan depan musuh; serangan ini meningkatkan tingkat kritis dan memiliki peluang menyebabkan terbakar.',
		simDesc_ph = 'Ang Pakpak na Pato ng Apoy ay nagtitipon ng buong enerhiya sa kanyang katawan, nagpapalabas ng alab na lavang apoy para atakihin ang mga kaaway sa unahang hanay; ang pinsalang ito ay tumataas ang porsyento ng kritikal at may tsansang magdulot ng paso.',
		simDesc_ma = 'Itik Paruh Itik Api memfokuskan seluruh tenaga dalam badannya, menyemburkan api lava menyerang sasaran di barisan hadapan musuh; kerosakan kali ini meningkatkan kadar kritikal dan berpeluang menyebabkan terbakar.',
		simDesc = 'Fire Duckbill Duck concentrates all the energy in its body, unleashing a molten flame to attack the enemy\'s front row; this attack increases critical hit rate and has a chance to inflict burn.',
