	[1006323] = {
		id = 1006323,
		skillName_vn = 'Nhảy nước rồng',
		skillName_en = 'Dragon Water Jump',
		skillName_th = 'กระโดดน้ำมังกร',
		skillName_in = 'Lompat Air Naga',
		skillName_ph = 'Dragon Water Jump',
		skillName_ma = 'Lompat Air Naga',
		skillName = 'Dragon Water Jump',
		describe_vn = 'Nhảy lên không trung rồi phun pháo nước tấn công mục tiêu hàng dọc kẻ địch, xóa hiệu ứng tăng cường của hàng mục tiêu và giảm 20% phòng thủ vật lý của chúng (1 lượt), mục tiêu bị đánh trúng sẽ nhận thêm 30% sát thương trong 2 lượt, nếu không tiêu diệt được mục tiêu thì bản thân hồi phục 200 điểm nộ khí',
		describe_en = 'Leap into the air and spray water bombs to attack the enemy\'s column targets, removing their buffs and reducing their physical defense by 20% for 1 turn. Targets hit will take an additional 30% damage for 2 turns. If the target is not defeated, the user recovers 200 rage points.',
		describe_th = 'กระโดดขึ้นสู่อากาศแล้วพ่นระเบิดน้ำโจมตีเป้าหมายแถวศัตรู ล้างเอฟเฟกต์เพิ่มพลังของแถวนั้น และลดค่าป้องกันกายภาพลง 20% เป็นเวลา 1 เทิร์น เป้าหมายที่ถูกโจมตีจะได้รับความเสียหายเพิ่มขึ้น 30% เป็นเวลา 2 เทิร์น หากไม่สามารถกำจัดเป้าหมายได้ ผู้ใช้จะฟื้นฟูพลังโกรธ 200 คะแนน',
		describe_in = 'Melompat ke udara lalu menyemprotkan bom air untuk menyerang target barisan musuh, menghapus peningkatan efek dari barisan target dan mengurangi pertahanan fisik mereka sebesar 20% selama 1 giliran. Target yang terkena akan menerima tambahan 30% kerusakan selama 2 giliran. Jika target tidak berhasil dikalahkan, pengguna akan memulihkan 200 poin kemarahan.',
		describe_ph = 'Tumalon sa hangin at magpabugso ng water bombs para atakihin ang hanay ng mga kalaban, tinatanggal ang mga buff ng hanay at nagpapababa ng 20% ng kanilang pisikal na depensa sa loob ng 1 turn. Ang mga target na tinamaan ay tatanggap ng dagdag na 30% pinsala sa loob ng 2 turns. Kung hindi mapapatay ang target, ang gumagamit ay makakabawi ng 200 puntos ng galit.',
		describe_ma = 'Melompat ke udara dan memuntahkan bom air untuk menyerang barisan musuh, menghapus kesan peningkatan daripada barisan sasaran dan mengurangkan pertahanan fizikal mereka sebanyak 20% selama 1 giliran. Sasaran yang terkena akan menerima kerosakan tambahan sebanyak 30% selama 2 giliran. Jika sasaran tidak dapat dikalahkan, pengguna akan memulihkan 200 mata kemarahan.',
		describe = 'Leap into the air and spray water bombs to attack the enemy\'s column targets, removing their buffs and reducing their physical defense by 20% for 1 turn. Targets hit will take an additional 30% damage for 2 turns. If the target is not defeated, the user recovers 200 rage points.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		skillType2 = 2,
