		targetTypeDesc_ma = 'Barisan menegak musuh',
		targetChooseType = 'column',
		damageFormula = '(self:damage()*2.6+skillLevel*48)*(1+(1-target:hp()/target:hpMax())*(0.15+(skillLv(6326) or 0)*0.0015))',
