	[1007213] = {
		id = 1007213,
		skillName_vn = 'Núi băng',
		skillName_en = 'Ice Mountain',
		skillName_th = 'ภูเขาน้ำแข็ง',
		skillName_in = 'Gunung Es',
		skillName_ph = 'Bundok ng Yelo',
		skillName_ma = 'Gunung Ais',
		skillName = 'Ice Mountain',
		describe_vn = 'Triệu hồi một tảng băng khổng lồ từ trên trời rơi xuống, tấn công toàn bộ mục tiêu kẻ địch, gây #C0x3D8A99#150% Phép Công#C0x5B545B#+$( skillLevel *30)$ Sát Thương Phép Thuật#C0x8A5C99##C0x5B545B#, có 30% xác suất đóng băng toàn bộ mục tiêu kẻ địch, có 50% xác suất giảm 30% tốc độ của toàn bộ mục tiêu, gây thêm 60% sát thương cho mục tiêu bị thêm dấu ấn băng giá',
		describe_en = 'Summon a gigantic block of ice falling from the sky, attacking all enemy targets, dealing #C0x3D8A99#150% Magic Power#C0x5B545B#+$( skillLevel *30)$ Magic Damage#C0x8A5C99##C0x5B545B#. Has a 30% chance to freeze all enemy targets completely, a 50% chance to reduce the speed of all targets by 30%, and deals an additional 60% damage to targets marked with the Frost Mark.',
		describe_th = 'เรียกก้อนน้ำแข็งยักษ์ตกลงมาจากท้องฟ้า โจมตีเป้าหมายศัตรูทั้งหมด ทำความเสียหาย #C0x3D8A99#150% พลังเวท#C0x5B545B#+$( skillLevel *30)$ ความเสียหายเวทมนตร์#C0x8A5C99##C0x5B545B# มีโอกาส 30% ในการแช่แข็งเป้าหมายศัตรูทั้งหมด มีโอกาส 50% ที่จะลดความเร็วของเป้าหมายทั้งหมดลง 30% และก่อให้เกิดความเสียหายเพิ่มขึ้นอีก 60% กับเป้าหมายที่ติดตราประทับน้ำแข็ง',
		describe_in = 'Memanggil bongkahan es raksasa jatuh dari langit, menyerang semua target musuh, menghasilkan #C0x3D8A99#150% Kekuatan Sihir#C0x5B545B#+$( skillLevel *30)$ Kerusakan Sihir#C0x8A5C99##C0x5B545B#. Memiliki peluang 30% untuk membekukan semua target musuh secara keseluruhan, peluang 50% untuk mengurangi kecepatan semua target sebesar 30%, dan memberikan tambahan 60% kerusakan pada target yang terkena tanda Es.',
		describe_ph = 'Nag-summon ng isang higanteng yelong bloke mula sa kalangitan na bumabagsak, ina-atake ang lahat ng kalaban, nagdudulot ng #C0x3D8A99#150% Magical Power#C0x5B545B#+$( skillLevel *30)$ Magical Damage#C0x8A5C99##C0x5B545B#. May 30% na tsansa na nagyelo ang lahat ng kalaban, 50% na tsansa na pabagalin ng 30% ang bilis ng lahat ng target, at nagdudulot pa ng dagdag na 60% pinsala sa mga target na may Frost Mark.',
		describe_ma = 'Memanggil bongkah ais gergasi dari langit jatuh, menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#150% Kuasa Sihir#C0x5B545B#+$( skillLevel *30)$ Kerosakan Sihir#C0x8A5C99##C0x5B545B#. Mempunyai 30% peluang untuk membekukan semua sasaran musuh sepenuhnya, 50% peluang untuk mengurangkan kelajuan semua sasaran sebanyak 30%, dan memberikan tambahan 60% kerosakan kepada sasaran yang mempunyai tanda Sejuk Beku.',
		describe = 'Summon a gigantic block of ice falling from the sky, attacking all enemy targets, dealing #C0x3D8A99#150% Magic Power#C0x5B545B#+$( skillLevel *30)$ Magic Damage#C0x8A5C99##C0x5B545B#. Has a 30% chance to freeze all enemy targets completely, a 50% chance to reduce the speed of all targets by 30%, and deals an additional 60% damage to targets marked with the Frost Mark.',
