	[1007313] = {
		id = 1007313,
		skillName_vn = 'Kim quang ngược rồng',
		skillName_en = 'Reverse Dragon Light',
		skillName_th = 'แสงมังกรย้อนกลับ',
		skillName_in = 'Cahaya Naga Terbalik',
		skillName_ph = 'Baliktad na Liwanag ng Dragon',
		skillName_ma = 'Cahaya Naga Terbalik',
		skillName = 'Reverse Dragon Light',
		describe_vn = 'Chim sét di chuyển giữa các đám mây sấm, điều khiển mây sấm sử dụng sức mạnh sấm sét tấn công mục tiêu hàng dọc kẻ địch, gây #C0x3D8A99#260% Phép Công#C0x5B545B#+$(skillLevel*48)$ Sát Thương Phép Thuật#C0x8A5C99##C0x5B545B#, thêm hiệu ứng tê liệt điện cho mục tiêu hàng dọc trong 2 lượt (trước khi mục tiêu hành động tấn công sẽ giảm trực tiếp 20% sát thương cộng thêm và 100 điểm nộ khí, kèm theo một lần sát thương sét bằng 2 lần Phép Công của chim sét)',
		describe_en = 'The Thunderbird moves between thunderclouds, controlling the thunderclouds to use lightning power to attack a vertical line of enemies, dealing #C0x3D8A99#260% Magic Attack#C0x5B545B#+$(skillLevel*48)$ Magic Damage#C0x8A5C99##C0x5B545B#, applying an electric paralysis effect to the vertical targets for 2 turns (before the target acts, their additional attack damage is directly reduced by 20% and they lose 100 rage points, accompanied by a lightning strike dealing damage equal to twice the Magic Attack of the Thunderbird).',
		describe_th = 'นกฟ้าร้องเคลื่อนที่ระหว่างเมฆฝนฟ้าคะนอง ควบคุมเมฆฝนฟ้าคะนองใช้พลังฟ้าผ่าผลักดันเป้าหมายในแนวตั้ง สร้างความเสียหายเวทมนตร์ #C0x3D8A99#260%#C0x5B545B#+$(skillLevel*48)$#C0x8A5C99##C0x5B545B# พร้อมเพิ่มเอฟเฟกต์ช็อตไฟฟ้าเป็นเวลา 2 เทิร์น (ก่อนที่เป้าหมายจะโจมตี ความเสียหายเพิ่มเติมจะถูกลดลงตรงๆ 20% และสูญเสีย 100 แต้มโกรธ พร้อมด้วยการโจมตีด้วยสายฟ้าหนึ่งครั้งที่มีความเสียหายเป็นสองเท่าของพลังเวทมนตร์ของนกฟ้าร้อง)',
		describe_in = 'Burung Petir bergerak di antara awan badai, mengendalikan awan badai menggunakan kekuatan petir untuk menyerang sasaran dalam garis vertikal musuh, memberikan #C0x3D8A99#260% Serangan Magic#C0x5B545B#+$(skillLevel*48)$ Kerusakan Magic#C0x8A5C99##C0x5B545B#, menambahkan efek paralisis listrik pada sasaran vertikal selama 2 giliran (sebelum sasaran bertindak, serangan tambahan langsung dikurangi 20% dan kehilangan 100 poin amarah, disertai satu kali serangan petir dengan damage dua kali Serangan Magic dari Burung Petir).',
		describe_ph = 'Ang Thunderbird ay gumagalaw sa pagitan ng mga ulap ng kulog, kinokontrol ang mga ulap ng kulog gamit ang kapangyarihan ng kidlat upang atakihin ang isang patayong linya ng mga kalaban, na nagdudulot ng #C0x3D8A99#260% Magic Attack#C0x5B545B#+$(skillLevel*48)$ Magic Damage#C0x8A5C99##C0x5B545B#, naglalagay ng epekto ng elektrikal na paralisis sa mga target sa patayong linya sa loob ng 2 mga turn (bago kumilos ang target, ang karagdagang pinsala sa pag-atake ay diretsong nababawasan ng 20% at nawawala ang 100 puntos ng galit, kasabay ng isang kidlat na pinsalang katumbas ng dalawang beses ng Magic Attack ng Thunderbird).',
		describe_ma = 'Burung Guntur bergerak di antara awan ribut, mengawal awan ribut menggunakan kuasa petir untuk menyerang sasaran dalam barisan menegak musuh, memberikan #C0x3D8A99#260% Serangan Magik#C0x5B545B#+$(skillLevel*48)$ Kerosakan Magik#C0x8A5C99##C0x5B545B#, menambah kesan lumpuh elektrik pada sasaran barisan menegak selama 2 pusingan (sebelum sasaran bertindak, kerosakan tambahan dikurangkan secara langsung sebanyak 20% dan kehilangan 100 mata kemarahan, disertai satu serangan petir dengan kerosakan dua kali Serangan Magik Burung Guntur).',
		describe = 'The Thunderbird moves between thunderclouds, controlling the thunderclouds to use lightning power to attack a vertical line of enemies, dealing #C0x3D8A99#260% Magic Attack#C0x5B545B#+$(skillLevel*48)$ Magic Damage#C0x8A5C99##C0x5B545B#, applying an electric paralysis effect to the vertical targets for 2 turns (before the target acts, their additional attack damage is directly reduced by 20% and they lose 100 rage points, accompanied by a lightning strike dealing damage equal to twice the Magic Attack of the Thunderbird).',
