	[1007613] = {
		id = 1007613,
		skillName_vn = 'Mắt kỳ diệu',
		skillName_en = 'Magical Eye',
		skillName_th = 'ดวงตาวิเศษ',
		skillName_in = 'Mata Ajaib',
		skillName_ph = 'Mahiwagang Mata',
		skillName_ma = 'Mata Ajaib',
		skillName = 'Magical Eye',
		describe_vn = 'Mewtwo mở mắt kỳ diệu, tập trung năng lượng khổng lồ, tấn công mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#530% Công Phép#C0x5B545B#+$(skillLevel*90)$ Sát Thương Phép Thuật#C0xF13B54#C0x5B545B#, bỏ qua 40% phòng thủ pháp thuật của mục tiêu, tăng 30% tỷ lệ chí mạng cho bản thân (2 lượt), giảm 60% tỷ lệ hồi máu của toàn bộ kẻ địch (2 lượt), đồng thời nhận được một lá chắn siêu năng (có thể hấp thụ 100% sát thương từ kỹ năng tối thượng lần này)',
		describe_en = 'Mewtwo miraculously opens its eyes, concentrates immense energy, attacking a single enemy target, dealing #C0x3D8A99#530% Magic Power#C0x5B545B#+$(skillLevel*90)$ Magic Damage#C0xF13B54#C0x5B545B#, ignoring 40% of the target\'s magic defense, increasing its own critical hit rate by 30% (2 turns), reducing the healing rate of all enemies by 60% (2 turns), and simultaneously receiving a psychic shield (which can absorb 100% damage from this ultimate skill).',
		describe_th = 'มิวทูเปิดตาอย่างมหัศจรรย์ รวบรวมพลังงานขนาดมหึมา โจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายเวทมนตร์ #C0x3D8A99#530% พลังเวท#C0x5B545B#+$(skillLevel*90)$ ความเสียหายเวทมนตร์#C0xF13B54#C0x5B545B# ละเลยการป้องกันเวทมนตร์ของเป้าหมาย 40% เพิ่มอัตราคริติคอลของตนเอง 30% (2 เทิร์น) ลดอัตราการฟื้นเลือดของศัตรูทั้งหมด 60% (2 เทิร์น) พร้อมทั้งได้รับโล่พลังจิต (สามารถดูดซับความเสียหาย 100% จากสกิลอัลติเมทนี้)',
		describe_in = 'Mewtwo membuka mata secara ajaib, mengumpulkan energi besar, menyerang satu target musuh, menyebabkan #C0x3D8A99#530% Kekuatan Sihir#C0x5B545B#+$(skillLevel*90)$ Kerusakan Sihir#C0xF13B54#C0x5B545B#, mengabaikan 40% pertahanan sihir target, meningkatkan peluang kritis dirinya sendiri sebesar 30% (2 giliran), mengurangi tingkat penyembuhan semua musuh sebesar 60% (2 giliran), sekaligus menerima perisai psikis (dapat menyerap 100% kerusakan dari skill ultimate ini).',
		describe_ph = 'Mewtwo ay milagrosong binuksan ang mga mata, nagtipon ng napakalaking enerhiya, inaatake ang isang target na kalaban, nagdudulot ng #C0x3D8A99#530% Lakas ng Magic#C0x5B545B#+$(skillLevel*90)$ Pinsalang Magic#C0xF13B54#C0x5B545B#, nilalampasan ang 40% ng magic defense ng target, pinapataas ang sariling critical rate ng 30% (2 turn), binabawasan ang healing rate ng lahat ng kalaban ng 60% (2 turn), at kasabay nito ay tumatanggap ng isang psychic shield (na maaaring sumipsip ng 100% na pinsala mula sa ultimate skill na ito).',
		describe_ma = 'Mewtwo membuka mata secara ajaib, menumpukan tenaga yang besar, menyerang sasaran musuh tunggal, menyebabkan #C0x3D8A99#530% Kuasa Sihir#C0x5B545B#+$(skillLevel*90)$ Kerosakan Sihir#C0xF13B54#C0x5B545B#, mengabaikan 40% pertahanan sihir sasaran, meningkatkan kadar kritikal diri sendiri sebanyak 30% (2 pusingan), mengurangkan kadar penyembuhan semua musuh sebanyak 60% (2 pusingan), dan pada masa yang sama menerima perisai psikis (boleh menyerap 100% kerosakan daripada kemahiran utama ini).',
		describe = 'Mewtwo miraculously opens its eyes, concentrates immense energy, attacking a single enemy target, dealing #C0x3D8A99#530% Magic Power#C0x5B545B#+$(skillLevel*90)$ Magic Damage#C0xF13B54#C0x5B545B#, ignoring 40% of the target\'s magic defense, increasing its own critical hit rate by 30% (2 turns), reducing the healing rate of all enemies by 60% (2 turns), and simultaneously receiving a psychic shield (which can absorb 100% damage from this ultimate skill).',
		simDesc_vn = 'Siêu Mộng mở ra Mắt Kỳ Diệu, thu thập năng lượng khổng lồ tấn công mục tiêu đơn lẻ của kẻ thù, giảm tỷ lệ hồi phục của toàn bộ kẻ thù, tăng tỷ lệ chí mạng của bản thân và có khả năng chặn một hiệu ứng kiểm soát.',
		simDesc_en = 'Super Dream opens the Miracle Eye, gathering massive energy to attack a single enemy target, reducing all enemies\' recovery rate, increasing own critical rate, and having the ability to block a control effect.',
		simDesc_th = 'ซูเปอร์ดรีมเปิดตาวิเศษ รวบรวมพลังงานมหาศาลโจมตีเป้าหมายศัตรูเดี่ยว ลดอัตราการฟื้นฟูของศัตรูทั้งหมด เพิ่มอัตราคริติคอลของตัวเอง และมีความสามารถในการป้องกันเอฟเฟกต์ควบคุมหนึ่งครั้ง',
		simDesc_in = 'Super Dream membuka Mata Keajaiban, mengumpulkan energi besar untuk menyerang satu target musuh, mengurangi tingkat pemulihan semua musuh, meningkatkan tingkat kritis sendiri, dan memiliki kemampuan untuk memblokir satu efek kontrol.',
		simDesc_ph = 'Binuksan ng Super Dream ang Miracle Eye, nagtipon ng dakilang enerhiya upang umatake sa isang target na kaaway, binabawasan ang recovery rate ng lahat ng kaaway, pinapataas ang critical rate ng sarili, at may kakayahang harangin ang isang control effect.',
		simDesc_ma = 'Super Dream membuka Mata Ajaib, mengumpul tenaga besar untuk menyerang satu sasaran musuh, mengurangkan kadar pemulihan semua musuh, meningkatkan kadar kritikal sendiri, dan mempunyai keupayaan untuk menghalang satu kesan kawalan.',
		simDesc = 'Super Dream opens the Miracle Eye, gathering massive energy to attack a single enemy target, reducing all enemies\' recovery rate, increasing own critical rate, and having the ability to block a control effect.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
