	[1007713] = {
		id = 1007713,
		skillName_vn = 'Giấc mơ bầu trời',
		skillName_en = 'Sky dream',
		skillName_th = 'ความฝันบนท้องฟ้า',
		skillName_in = 'Mimpi langit',
		skillName_ph = 'Pangarap sa langit',
		skillName_ma = 'Mimpi langit',
		skillName = 'Sky dream',
		describe_vn = 'Sử dụng năng lực siêu nhiên để mở ra một bầu trời sao mộng ảo, sau đó phá vỡ giấc mơ, tấn công toàn bộ kẻ địch, gây #C0x3D8A99#150% Công Phép#C0x5B545B#+$( skillLevel *24)$ Sát Thương Phép Thuật#C0x8A5C99#C0x5B545B#, khiến toàn bộ mục tiêu kẻ địch có 30% xác suất rơi vào ảo cảnh trong 1 lượt (ảo cảnh: mục tiêu rơi vào một trong các trạng thái câm lặng/hỗn loạn/ngủ/khiêu khích ngẫu nhiên, giảm 20% phòng thủ pháp thuật của chúng), gây thêm 40% sát thương đối với mục tiêu bị khống chế, số lượng anh hùng kẻ địch càng ít, sát thương kỹ năng tối thượng càng cao; số lượng anh hùng kẻ địch càng nhiều, xác suất khống chế của kỹ năng tối thượng càng cao',
		describe_en = 'Use supernatural powers to open a dreamy starry sky, then shatter the dream to attack all enemies, dealing #C0x3D8A99#150% Magic Power#C0x5B545B# + $( skillLevel * 24 )$ Magic Damage#C0x8A5C99#C0x5B545B#. All enemy targets have a 30% chance to fall into an illusion for 1 turn (illusion: targets randomly enter one of the states Silence/Confusion/Sleep/Taunt, and their magic defense is reduced by 20%), dealing an additional 40% damage to controlled targets. The fewer the enemy heroes, the higher the ultimate skill damage; the more enemy heroes, the higher the control chance of the ultimate skill.',
		describe_th = 'ใช้พลังเหนือธรรมชาติเพื่อเปิดท้องฟ้าที่เต็มไปด้วยดาวในฝัน จากนั้นทำลายความฝันเพื่อโจมตีศัตรูทั้งหมด สร้างความเสียหาย #C0x3D8A99#150% พลังเวท#C0x5B545B# + $( skillLevel * 24 )$ ความเสียหายเวท#C0x8A5C99#C0x5B545B# เป้าหมายศัตรูทั้งหมดมีโอกาส 30% ที่จะตกอยู่ในภาพลวงตาเป็นเวลา 1 เทิร์น (ภาพลวงตา: เป้าหมายจะตกอยู่ในสถานะ หน้าปิดปาก/สับสน/หลับ/ยั่วเย้า แบบสุ่ม ลดการป้องกันเวทมนตร์ลง 20%) สร้างความเสียหายเพิ่มเติม 40% กับเป้าหมายที่ถูกควบคุม จำนวนฮีโร่ฝ่ายศัตรูยิ่งน้อย ความเสียหายของสกิลอัลติเมทยิ่งสูง จำนวนฮีโร่ฝ่ายศัตรูยิ่งมาก โอกาสควบคุมสกิลอัลติเมทยิ่งสูง',
		describe_in = 'Gunakan kekuatan supranatural untuk membuka langit berbintang yang penuh mimpi, kemudian hancurkan mimpi itu untuk menyerang semua musuh, memberikan #C0x3D8A99#150% Kekuatan Sihir#C0x5B545B# + $( skillLevel * 24 )$ Kerusakan Sihir#C0x8A5C99#C0x5B545B#. Semua target musuh memiliki peluang 30% untuk jatuh ke dalam ilusi selama 1 giliran (ilusi: target secara acak mengalami salah satu status Diam/Kebingungan/Tidur/Provokasi, serta mengurangi pertahanan sihir mereka sebesar 20%), memberikan tambahan 40% kerusakan pada target yang terkendali. Semakin sedikit pahlawan musuh, semakin tinggi kerusakan keterampilan ultimate; semakin banyak pahlawan musuh, semakin tinggi peluang kontrol keterampilan ultimate.',
		describe_ph = 'Gamitin ang supernatural na kapangyarihan upang buksan ang isang panaginip na bituin na kalangitan, pagkatapos ay sirain ang panaginip upang atakihin ang lahat ng mga kalaban, na nagdudulot ng #C0x3D8A99#150% Lakas ng Mahika#C0x5B545B# + $( skillLevel * 24 )$ Pinsala sa Mahika#C0x8A5C99#C0x5B545B#. Lahat ng mga target ng kalaban ay may 30% pagkakataong mahulog sa ilusyon sa loob ng 1 turn (ilusyon: ang target ay random na mapapasailalim sa isa sa mga estado ng Katahimikan/Kalito/Pagkatulog/Pagpang-akit, na nagpapababa ng kanilang depensa sa mahika ng 20%), nagdudulot ng dagdag na 40% pinsala sa mga target na kontrolado. Kapag mas kakaunti ang mga kalabang bayani, mas mataas ang pinsala ng ultimate na kakayahan; kapag mas marami ang mga kalabang bayani, mas mataas ang tsansa ng control ng ultimate na kakayahan.',
		describe_ma = 'Gunakan kuasa ghaib untuk membuka langit berbintang yang indah seperti mimpi, kemudian hancurkan mimpi itu untuk menyerang semua musuh, menyebabkan #C0x3D8A99#150% Kuasa Sihir#C0x5B545B# + $( skillLevel * 24 )$ Kerosakan Sihir#C0x8A5C99#C0x5B545B#. Semua sasaran musuh mempunyai peluang 30% untuk jatuh ke dalam ilusi selama 1 pusingan (ilusi: sasaran secara rawak mengalami salah satu keadaan Diam/Keliruan/Tidur/Menghasut, dan mengurangkan pertahanan sihir mereka sebanyak 20%), menyebabkan tambahan 40% kerosakan kepada sasaran yang dikawal. Lagi sedikit wira musuh, lagi tinggi kerosakan kemahiran akhir; lagi ramai wira musuh, lagi tinggi peluang kawalan kemahiran akhir.',
		describe = 'Use supernatural powers to open a dreamy starry sky, then shatter the dream to attack all enemies, dealing #C0x3D8A99#150% Magic Power#C0x5B545B# + $( skillLevel * 24 )$ Magic Damage#C0x8A5C99#C0x5B545B#. All enemy targets have a 30% chance to fall into an illusion for 1 turn (illusion: targets randomly enter one of the states Silence/Confusion/Sleep/Taunt, and their magic defense is reduced by 20%), dealing an additional 40% damage to controlled targets. The fewer the enemy heroes, the higher the ultimate skill damage; the more enemy heroes, the higher the control chance of the ultimate skill.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		skillType2 = 2,
		skillDamageType = 1,
		skillNatureType = 11,
		hintChoose = 11,
		targetTypeDesc = 'All enemies',
		targetTypeDesc_vn = 'Toàn bộ địch',
		targetTypeDesc_en = 'All enemies',
		targetTypeDesc_th = 'ศัตรูทั้งหมด',
		targetTypeDesc_in = 'Semua musuh',
		targetTypeDesc_ph = 'Lahat ng kalaban',
		targetTypeDesc_ma = 'Semua musuh',
		targetChooseType = 'all',
		damageFormula = '(self:specialDamage()*1.5+skillLevel*30)*((target:hasBuff(77114) or target:hasBuff(77114) or target:hasBuff(77114) or target:hasBuff(77114)) and 1.5 or 1)*((6-getForceNum(self:force()))*0.1+1)',
		skillProcess = {10077131, 10077132, 10077133, 10077134},
		costMp1 = 1000,
