	[1008832] = {
		id = 1008832,
		skillName_vn = 'Đuôi bóng điện',
		skillName_en = 'Light bulb tail',
		skillName_th = 'หางหลอดไฟ',
		skillName_in = 'Ekor bola lampu',
		skillName_ph = 'Buntot ng bombilya',
		skillName_ma = 'Ekor mentol lampu',
		skillName = 'Light bulb tail',
		describe_vn = 'Đuôi rồng điện phóng ra quả cầu ánh sáng điện tấn công mục tiêu đơn lẻ của kẻ địch, gây #C0x3D8A99#160% Phép Công#C0x5B545B#+$(skillLevel*48)$ Sát Thương Phép Thuật#C0xF13B54#, tăng 20% Phép Công cho mục tiêu đồng minh có Phép Công cao nhất (2 lượt), và tăng 100 điểm nộ khí, nếu mục tiêu thuộc hệ sét hoặc cơ khí, nộ khí tăng thêm 100 điểm',
		describe_en = 'The electric dragon tail launches a ball of electric light to attack a single enemy target, dealing #C0x3D8A99#160% Magic Attack#C0x5B545B#+$(skillLevel*48)$ Magic Damage#C0xF13B54#, increases Magic Attack by 20% for the allied target with the highest Magic Attack (2 turns), and increases 100 rage points; if the target is of Thunder or Mechanical type, rage increases by an additional 100 points.',
		describe_th = 'หางมังกรไฟฟ้าปล่อยลูกบอลแสงไฟฟ้าโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายเวท #C0x3D8A99#160% พลังเวท#C0x5B545B#+$(skillLevel*48)$ ความเสียหายเวท#C0xF13B54#, เพิ่มพลังเวท 20% ให้กับเป้าหมายฝ่ายเดียวที่มีพลังเวทสูงที่สุด (2 รอบ) และเพิ่มพลังแค้น 100 หน่วย หากเป้าหมายเป็นธาตุสายฟ้าหรือเครื่องจักร จะเพิ่มพลังแค้นอีก 100 หน่วย',
		describe_in = 'Ekor naga listrik meluncurkan bola cahaya listrik menyerang satu target musuh, memberikan #C0x3D8A99#160% Serangan Sihir#C0x5B545B#+$(skillLevel*48)$ Kerusakan Sihir#C0xF13B54#, meningkatkan 20% Serangan Sihir untuk target sekutu dengan Serangan Sihir tertinggi (2 giliran), dan menambah 100 poin amarah; jika target berjenis Petir atau Mekanik, amarah bertambah 100 poin lagi.',
		describe_ph = 'Ang buntot ng dragon na elektriko ay nagpapalabas ng bolang ilaw na elektriko upang atakihin ang isang solong target ng kalaban, na nagdudulot ng #C0x3D8A99#160% Magic Attack#C0x5B545B#+$(skillLevel*48)$ Pinsalang Magic#C0xF13B54#, nagpapataas ng 20% Magic Attack para sa alyadong target na may pinakamataas na Magic Attack (2 na turn), at nagpapataas ng 100 puntos ng galit; kung ang target ay kabilang sa Thunder o Mechanical na uri, tataas pa ng 100 puntos ang galit.',
		describe_ma = 'Ekor naga elektrik melancarkan bola cahaya elektrik untuk menyerang satu sasaran musuh, memberikan #C0x3D8A99#160% Serangan Sihir#C0x5B545B#+$(skillLevel*48)$ Kerosakan Sihir#C0xF13B54#, meningkatkan Serangan Sihir sebanyak 20% kepada sasaran sekutu dengan Serangan Sihir tertinggi (2 pusingan), dan menambah 100 mata amarah; jika sasaran adalah jenis Kilat atau Mekanik, amarah bertambah 100 mata lagi.',
		describe = 'The electric dragon tail launches a ball of electric light to attack a single enemy target, dealing #C0x3D8A99#160% Magic Attack#C0x5B545B#+$(skillLevel*48)$ Magic Damage#C0xF13B54#, increases Magic Attack by 20% for the allied target with the highest Magic Attack (2 turns), and increases 100 rage points; if the target is of Thunder or Mechanical type, rage increases by an additional 100 points.',
		simDesc_vn = 'Điện Long phóng ra quả cầu điện từ đuôi tấn công mục tiêu đơn lẻ của kẻ thù.',
		simDesc_en = 'The Electric Dragon launches an electromagnetic sphere from its tail to attack a single enemy target.',
		simDesc_th = 'มังกรสายฟ้าปล่อยบอลแม่เหล็กไฟฟ้าจากหางเพื่อโจมตีเป้าหมายศัตรูเดี่ยว',
		simDesc_in = 'Naga Listrik meluncurkan bola elektromagnetik dari ekornya untuk menyerang satu target musuh.',
		simDesc_ph = 'Ang Electric Dragon ay nagpapalipad ng isang electromagnetic sphere mula sa buntot upang atakihin ang isang kalaban.',
		simDesc_ma = 'Naga Elektrik melancarkan bola elektromagnet dari ekornya untuk menyerang sasaran musuh tunggal.',
		simDesc = 'The Electric Dragon launches an electromagnetic sphere from its tail to attack a single enemy target.',
