	[1008833] = {
		id = 1008833,
		skillName_vn = 'Nổ điện đoàn',
		skillName_en = 'Electric Explosion Squad',
		skillName_th = 'ทีมระเบิดไฟฟ้า',
		skillName_in = 'Pasukan Ledakan Listrik',
		skillName_ph = 'Puwersang Pagsabog ng Kuryente',
		skillName_ma = 'Kumpulan Letupan Elektrik',
		skillName = 'Electric Explosion Squad',
		describe_vn = 'Rồng điện tập trung một quả cầu năng lượng điện, sau đó phát nổ tấn công mục tiêu hàng ngang của kẻ địch, gây #C0x3D8A99#220% Phép Công#C0x5B545B#+$(skillLevel*48)$ Sát Thương Phép Thuật#C0xF13B54#, có 50% cơ hội thêm hiệu ứng cảm điện cho mục tiêu, trong 2 lượt tiếp theo, khi nhận sát thương kỹ năng, mục tiêu sẽ chịu thêm Sát Thương Phép Thuật bằng 45% Phép Công của Mareep; và tăng 20% sát thương tuyệt chiêu cho toàn bộ đồng minh, kéo dài 2 lượt',
		describe_en = 'The Electric Dragon concentrates a sphere of electric energy, then explodes to attack a horizontal line of enemy targets, dealing #C0x3D8A99#220% Magic Attack#C0x5B545B#+$(skillLevel*48)$ Magic Damage#C0xF13B54#. It has a 50% chance to apply an electric shock effect on the targets; for the next 2 turns, when taking skill damage, the targets will receive additional Magic Damage equal to 45% of Mareep\'s Magic Attack. Additionally, it increases ultimate skill damage by 20% for all allies, lasting 2 turns.',
		describe_th = 'มังกรไฟฟ้ารวบรวมลูกบอลพลังงานไฟฟ้า จากนั้นระเบิดโจมตีเป้าหมายในแนวนอนของศัตรู สร้างความเสียหายเวทมนตร์ #C0x3D8A99#220%#C0x5B545B#+$(skillLevel*48)$ #C0xF13B54# มีโอกาส 50% ที่จะเพิ่มสถานะไฟฟ้าช็อตให้กับเป้าหมาย ใน 2 เทิร์นถัดไป เมื่อได้รับความเสียหายจากสกิล เป้าหมายจะได้รับความเสียหายเวทมนตร์เพิ่มอีกเท่ากับ 45% ของพลังเวทมนตร์ของ Mareep และเพิ่มความเสียหายสกิลสุดยอดของพันธมิตรทั้งหมดขึ้น 20% ซึ่งมีผลต่อเนื่อง 2 เทิร์น',
		describe_in = 'Naga Listrik mengumpulkan sebuah bola energi listrik, kemudian meledak menyerang baris horizontal target musuh, memberikan #C0x3D8A99#220% Serangan Sihir#C0x5B545B#+$(skillLevel*48)$ Kerusakan Sihir#C0xF13B54#. Memiliki peluang 50% untuk menambahkan efek kejutan listrik pada target; selama 2 giliran berikutnya, ketika menerima kerusakan skill, target akan menerima tambahan Kerusakan Sihir sebesar 45% dari Serangan Sihir Mareep. Selain itu, meningkatkan kerusakan serangan pamungkas sebesar 20% untuk seluruh sekutu, bertahan selama 2 giliran.',
		describe_ph = 'Ang Electric Dragon ay nagtipon ng isang bola ng electric energy, pagkatapos ay sumabog upang atakuin ang pahalang na hanay ng mga kaaway, na nagdudulot ng #C0x3D8A99#220% Magic Attack#C0x5B545B#+$(skillLevel*48)$ Magic Damage#C0xF13B54#. May 50% na tsansa na magdagdag ng electric shock effect sa mga target; sa loob ng susunod na 2 turn, kapag tumatanggap ng skill damage, ang mga target ay tatanggap ng karagdagang Magic Damage na katumbas ng 45% ng Magic Attack ni Mareep; at tumataas ng 20% ang ultimate skill damage para sa lahat ng kaalyado, tumatagal ng 2 turn.',
		describe_ma = 'Naga Elektrik mengumpulkan satu bola tenaga elektrik, kemudian meletup menyerang sasaran baris mendatar musuh, menyebabkan #C0x3D8A99#220% Serangan Sihir#C0x5B545B#+$(skillLevel*48)$ Kerosakan Sihir#C0xF13B54#. Mempunyai peluang 50% untuk menambah kesan kejutan elektrik kepada sasaran; dalam 2 pusingan berikutnya, apabila menerima kerosakan kemahiran, sasaran akan menerima tambahan Kerosakan Sihir sebanyak 45% Serangan Sihir Mareep. Dan meningkatkan kerosakan serangan hebat sebanyak 20% untuk semua sekutu, bertahan selama 2 pusingan.',
		describe = 'The Electric Dragon concentrates a sphere of electric energy, then explodes to attack a horizontal line of enemy targets, dealing #C0x3D8A99#220% Magic Attack#C0x5B545B#+$(skillLevel*48)$ Magic Damage#C0xF13B54#. It has a 50% chance to apply an electric shock effect on the targets; for the next 2 turns, when taking skill damage, the targets will receive additional Magic Damage equal to 45% of Mareep\'s Magic Attack. Additionally, it increases ultimate skill damage by 20% for all allies, lasting 2 turns.',
		simDesc_vn = 'Điện Long bao bọc bản thân bằng quả cầu điện, dần dần phình to rồi phát nổ tấn công mục tiêu đơn lẻ của kẻ thù.',
		simDesc_en = 'The Lightning Dragon surrounds itself with a sphere of electricity, gradually expanding before exploding to attack a single enemy target.',
		simDesc_th = 'มังกรสายฟ้าล้อมรอบตัวเองด้วยลูกบอลแห่งไฟฟ้า ค่อยๆ ขยายใหญ่ขึ้นแล้วระเบิดโจมตีเป้าหมายเดี่ยวของศัตรู',
		simDesc_in = 'Naga Listrik membungkus dirinya dengan bola listrik, perlahan-lahan membesar lalu meledak menyerang satu target musuh.',
		simDesc_ph = 'Inaalagaan ng Kidlat na Dragon ang sarili gamit ang bola ng kuryente, dahan-dahang lumalaki bago sumabog upang atakihin ang isang target na kaaway.',
		simDesc_ma = 'Naga Elektrik melindungi diri dengan bola elektrik, perlahan-lahan membesar sebelum meletup menyerang satu sasaran musuh.',
		simDesc = 'The Lightning Dragon surrounds itself with a sphere of electricity, gradually expanding before exploding to attack a single enemy target.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		skillType2 = 2,
