	[1010823] = {
		id = 1010823,
		skillName_vn = 'Móng vuốt ác quỷ',
		skillName_en = 'Demon claws',
		skillName_th = 'กรงเล็บปีศาจ',
		skillName_in = 'Cakar setan',
		skillName_ph = 'Sangkalan ng demonyo',
		skillName_ma = 'Cakar syaitan',
		skillName = 'Demon claws',
		describe_vn = 'Weavile vung móng thép như cơn lốc, liên tục chém vào mục tiêu đơn lẻ của kẻ địch, gây #C0xE69900#500% vật công#C0x5B545B#+$(skillLevel*48)$ Sát Thương Vật Lý#C0xF13B54#, gây thêm 80% sát thương cho mục tiêu bị đóng băng, với mục tiêu chưa bị đóng băng có 80% cơ hội đóng băng trong 1 lượt (trong thời gian đóng băng, nếu nhận sát thương vượt quá 30% máu của mục tiêu, hiệu ứng đóng băng sẽ bị hủy)',
		describe_en = 'Weavile swings its steel claws like a whirlwind, continuously slashing at a single enemy target, dealing #C0xE69900#500% physical attack#C0x5B545B# + $(skillLevel*48)$ Physical Damage#C0xF13B54#. It deals an additional 80% damage to frozen targets. Targets not yet frozen have an 80% chance to be frozen for 1 turn (while frozen, if the damage received exceeds 30% of the target\'s HP, the freeze effect is removed).',
		describe_th = 'วีไวล์ใช้กรงเล็บเหล็กที่หมุนวนเหมือนพายุ พุ่งโจมตีเป้าหมายศัตรูเดี่ยวอย่างต่อเนื่อง สร้างความเสียหายทางกายภาพ #C0xE69900#500%#C0x5B545B# + $(skillLevel*48)$#C0xF13B54# ความเสียหายกายภาพ ฝากเพิ่ม 80% ความเสียหายกับเป้าหมายที่ถูกแช่แข็ง เป้าหมายที่ยังไม่ถูกแช่แข็งมีโอกาส 80% ที่จะถูกแช่แข็งเป็นเวลา 1 เทิร์น (ในระหว่างแช่แข็ง หากได้รับความเสียหายเกิน 30% ของพลังชีวิต เป้าหมายจะหลุดจากสถานะแช่แข็ง)',
		describe_in = 'Weavile mengayunkan cakarnya yang terbuat dari baja seperti pusaran angin, terus-menerus memotong satu target musuh, memberikan #C0xE69900#500% serangan fisik#C0x5B545B# + $(skillLevel*48)$ Kerusakan Fisik#C0xF13B54#. Memberikan tambahan 80% kerusakan pada target yang membeku. Target yang belum membeku memiliki peluang 80% untuk membeku selama 1 giliran (selama membeku, jika menerima kerusakan lebih dari 30% HP target, efek membeku akan hilang).',
		describe_ph = 'Weavile ayaw ng kanyang bakal na kuko na parang buhawi, patuloy na hinahampas ang iisang kalaban, nagdudulot ng #C0xE69900#500% pisikal na atake#C0x5B545B# + $(skillLevel*48)$ Pisikal na Pinsala#C0xF13B54#. Nagdudulot ng dagdag na 80% pinsala sa mga kalaban na nagyeyelo. Ang mga kalaban na hindi pa nagyeyelo ay may 80% na tsansa na nagyeyelo sa loob ng 1 turn (habang nagyeyelo, kung makakatanggap ng pinsalang higit sa 30% ng HP ng target, mawawala ang epekto ng yelo).',
		describe_ma = 'Weavile mengayunkan cakar besinya seperti puting beliung, terus-menerus menikam sasaran musuh tunggal, menyebabkan #C0xE69900#500% serangan fizikal#C0x5B545B# + $(skillLevel*48)$ Kerosakan Fizikal#C0xF13B54#. Menyebabkan tambahan 80% kerosakan pada sasaran yang dibekukan. Sasaran yang belum dibekukan mempunyai peluang 80% untuk dibekukan selama 1 giliran (semasa dibekukan, jika menerima kerosakan melebihi 30% HP sasaran, kesan pembekuan akan dibatalkan).',
		describe = 'Weavile swings its steel claws like a whirlwind, continuously slashing at a single enemy target, dealing #C0xE69900#500% physical attack#C0x5B545B# + $(skillLevel*48)$ Physical Damage#C0xF13B54#. It deals an additional 80% damage to frozen targets. Targets not yet frozen have an 80% chance to be frozen for 1 turn (while frozen, if the damage received exceeds 30% of the target\'s HP, the freeze effect is removed).',
		simDesc_vn = 'Ma Nhu Lạp duỗi móng vuốt thép ra, như cơn lốc, liên tục chém vào mục tiêu đơn lẻ của kẻ thù.',
		simDesc_en = 'Ma Nhu Lạp extended his steel claws, like a whirlwind, continuously slashing at a single enemy target.',
		simDesc_th = 'ม่า หนู ลาป ยืดเล็บเหล็กออกมา เหมือนพายุ หมุนวน ฟันต่อเนื่องไปยังเป้าหมายศัตรูเพียงหนึ่งเดียว',
