	[1012533] = {
		id = 1012533,
		skillName_vn = 'Đại pháo đá',
		skillName_en = 'Great Rock Cannon',
		skillName_th = 'ปืนใหญ่หินยักษ์',
		skillName_in = 'Meriam Batu Agung',
		skillName_ph = 'Dakilang Batong Kanyon',
		skillName_ma = 'Meriam Batu Hebat',
		skillName = 'Great Rock Cannon',
		describe_vn = 'Tyranitar tập trung năng lượng lớn trong miệng tạo thành đạn pháo, bắn vào mục tiêu đơn của kẻ địch, gây #C0xE69900#420% Công Vật Lý#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, trước tiên gây thêm sát thương bằng 30% máu đã mất của bản thân, sau khi kết thúc kỹ năng hồi phục 12% máu tối đa của bản thân, nếu máu trước khi hồi phục dưới 50% thì lượng hồi phục tăng lên 18%',
		describe_en = 'Tyranitar concentrates a massive amount of energy in its mouth, forming a cannonball that fires at a single enemy target, dealing #C0xE69900#420% Physical Attack#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# Physical Damage#C0x5B545B#. It first inflicts additional damage equal to 30% of its lost HP. After the skill ends, it restores 12% of its maximum HP. If HP before healing is below 50%, the healing amount increases to 18%.',
		describe_th = 'Tyranitar รวบรวมพลังงานจำนวนมากในปากจนกลายเป็นกระสุนปืนใหญ่ ยิงใส่เป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0xE69900#420% พลังการโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ก่อนอื่นสร้างความเสียหายเพิ่มเติมเป็น 30% ของพลังชีวิตที่สูญเสียไป หลังใช้ทักษะจะฟื้นฟูพลังชีวิตสูงสุดของตนเอง 12% หากพลังชีวิตก่อนฟื้นฟูต่ำกว่า 50% จะเพิ่มการฟื้นฟูเป็น 18%',
		describe_in = 'Tyranitar mengumpulkan energi besar di mulutnya membentuk peluru meriam, menembak ke satu target musuh, memberikan #C0xE69900#420% Serangan Fisik#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Awalnya memberikan kerusakan tambahan sebesar 30% dari HP yang hilang. Setelah skill selesai, memulihkan 12% HP maksimal diri sendiri. Jika HP sebelum pemulihan di bawah 50%, jumlah pemulihan meningkat menjadi 18%.',
		describe_ph = 'Ang Tyranitar ay nagtitipon ng malaking enerhiya sa kanyang bibig na bumubuo ng isang bala ng kanyon, pumutok sa isang target na kalaban, na nagdudulot ng #C0xE69900#420% Pisikal na Atake#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Una, nagdudulot ng dagdag na pinsala na katumbas ng 30% ng nawalang HP ng sarili. Pagkatapos matapos ang kasanayan, nagpapagaling ng 12% ng kanyang maximum na HP. Kung ang HP bago ang pagpapagaling ay mababa sa 50%, tataas ang halagang pagpapagaling sa 18%.',
		describe_ma = 'Tyranitar menumpukan tenaga besar di mulutnya membentuk peluru meriam, menembak ke satu sasaran musuh, menyebabkan #C0xE69900#420% Serangan Fizikal#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Pada awalnya memberi kerosakan tambahan sebanyak 30% daripada keseluruhan darah yang hilang. Selepas tamat kemahiran memulihkan 12% darah maksimum dirinya. Jika darah sebelum pemulihan kurang daripada 50%, jumlah pemulihan akan meningkat kepada 18%.',
		describe = 'Tyranitar concentrates a massive amount of energy in its mouth, forming a cannonball that fires at a single enemy target, dealing #C0xE69900#420% Physical Attack#C0x5B545B#+$(skillLevel*75)$ #C0xF13B54# Physical Damage#C0x5B545B#. It first inflicts additional damage equal to 30% of its lost HP. After the skill ends, it restores 12% of its maximum HP. If HP before healing is below 50%, the healing amount increases to 18%.',
		simDesc_vn = 'Băng Kỳ La S trong miệng tích tụ năng lượng khổng lồ, hình thành viên đạn, tấn công mục tiêu đơn lẻ của kẻ thù; máu càng thấp, sát thương càng cao.',
		simDesc_en = 'S La in the mouth accumulates massive energy, forming a bullet to attack a single enemy target; the lower the HP, the higher the damage.',
		simDesc_th = 'S La ในปากสะสมพลังงานมหาศาล สร้างเป็นกระสุนโจมตีเป้าหมายศัตรูทีละตัว; ยิ่งเลือดต่ำ ยิ่งสร้างความเสียหายมากขึ้น',
		simDesc_in = 'S La di dalam mulut mengumpulkan energi besar, membentuk peluru untuk menyerang satu target musuh; semakin rendah darah, semakin tinggi kerusakan.',
		simDesc_ph = 'S La sa loob ng bibig ay nag-iipon ng malaking enerhiya, bumubuo ng bala upang atakihin ang isang target na kaaway; kapag mas mababa ang dugo, mas mataas ang pinsala.',
		simDesc_ma = 'S La di dalam mulut mengumpul tenaga besar, membentuk peluru untuk menyerang satu sasaran musuh; semakin rendah darah, semakin tinggi kerosakan.',
		simDesc = 'S La in the mouth accumulates massive energy, forming a bullet to attack a single enemy target; the lower the HP, the higher the damage.',
