	[1014233] = {
		id = 1014233,
		skillName_vn = 'Đòn tấn công cuối cùng',
		skillName_en = 'Final attack',
		skillName_th = 'การโจมตีครั้งสุดท้าย',
		skillName_in = 'Serangan terakhir',
		skillName_ph = 'Huling atake',
		skillName_ma = 'Serangan terakhir',
		skillName = 'Final attack',
		describe_vn = 'Tung cú đấm cuối cùng, đánh bay mục tiêu kẻ địch, gây #C0xE69900#500% Công Vật Lý#C0x5B545B#+$( skillLevel *36)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, bỏ qua 60% phòng thủ vật lý, kèm theo 50% hút máu, sau khi tấn công Slaking bắt đầu lười biếng không thể hành động, kéo dài 1 lượt, sau khi Slaking sử dụng kỹ năng tối thượng, trong thời gian không thể hành động tăng 25% phòng thủ vật lý và 25% phòng thủ phép, vĩnh viễn tăng 15% sát thương cho kỹ năng tối thượng tiếp theo của bản thân (tối đa cộng dồn 3 lần)',
		describe_en = 'Unleashes the final punch, knocking the enemy target away, dealing #C0xE69900#500% Physical Attack#C0x5B545B# +$( skillLevel *36)$ #C0xF13B54# Physical Damage#C0x5B545B#, ignoring 60% physical defense, with 50% lifesteal. After the attack, Slaking becomes lazy and unable to act for 1 turn. After Slaking uses the ultimate skill, during the inactive period, physical defense and magic defense increase by 25%, and permanently increases the next ultimate skill\'s damage by 15% (stacks up to 3 times).',
		describe_th = 'ปล่อยหมัดสุดท้าย โจมตีเป้าหมายศัตรู ทำดาเมจ #C0xE69900#500% พลังโจมตีทางกายภาพ#C0x5B545B# +$( skillLevel *36)$ #C0xF13B54# ความเสียหายกายภาพ#C0x5B545B# ละเลยการป้องกันทางกายภาพ 60% พร้อมฟื้นเลือด 50% หลังจากโจมตี Slaking จะขี้เกียจและไม่สามารถทำอะไรได้ 1 เทิร์น หลังจากใช้สกิลอัลติเมท ในระหว่างที่ไม่สามารถเคลื่อนไหวจะได้รับเกราะกายภาพและเวทมนตร์เพิ่มขึ้น 25% และเพิ่มดาเมจสกิลอัลติเมทถัดไปถาวร 15% (สะสมได้สูงสุด 3 ครั้ง)',
		describe_in = 'Melakukan pukulan terakhir, mengusir target musuh, memberikan #C0xE69900#500% Serangan Fisik#C0x5B545B# +$( skillLevel *36)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, mengabaikan 60% pertahanan fisik, disertai dengan 50% pencurian nyawa. Setelah menyerang, Slaking menjadi malas dan tidak dapat bertindak selama 1 giliran. Setelah Slaking menggunakan skill pamungkas, selama tidak dapat bertindak akan meningkatkan pertahanan fisik dan pertahanan sihir sebesar 25%, serta secara permanen meningkatkan damage skill pamungkas berikutnya sebesar 15% (maksimal dapat menumpuk 3 kali).',
		describe_ph = 'Isinasagawa ang huling suntok, tinataboy ang kalaban, nagdudulot ng #C0xE69900#500% Pisikal na Atake#C0x5B545B# +$( skillLevel *36)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, nilalampasan ang 60% pisikal na depensa, may kasamang 50% buhay na nasisipsip. Pagkatapos umatake, nagiging tamad si Slaking at hindi makakilos sa loob ng 1 turn. Matapos gamitin ni Slaking ang ultimate skill, sa panahon ng hindi makakilos ay tumataas ng 25% ang pisikal at magic na depensa, at permanenteng tumataas ng 15% ang pinsala ng susunod na ultimate skill (max na makakapag-stack ng 3 beses).',
		describe_ma = 'Melakukan tumbukan terakhir, menolak sasaran musuh, memberikan #C0xE69900#500% Serangan Fizikal#C0x5B545B# +$( skillLevel *36)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, mengabaikan 60% pertahanan fizikal, disertai dengan pemulihan darah 50%. Selepas menyerang, Slaking mula menjadi malas dan tidak dapat bertindak selama 1 pusingan. Selepas Slaking menggunakan kemahiran utama, semasa tempoh tidak dapat bertindak, pertahanan fizikal dan pertahanan magik meningkat sebanyak 25%, dan meningkatkan kerosakan kemahiran utama seterusnya sebanyak 15% secara kekal (maksima bertindih 3 kali).',
		describe = 'Unleashes the final punch, knocking the enemy target away, dealing #C0xE69900#500% Physical Attack#C0x5B545B# +$( skillLevel *36)$ #C0xF13B54# Physical Damage#C0x5B545B#, ignoring 60% physical defense, with 50% lifesteal. After the attack, Slaking becomes lazy and unable to act for 1 turn. After Slaking uses the ultimate skill, during the inactive period, physical defense and magic defense increase by 25%, and permanently increases the next ultimate skill\'s damage by 15% (stacks up to 3 times).',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
