	[1019033] = {
		id = 1019033,
		skillName_vn = 'Va chạm tối thượng',
		skillName_en = 'Ultimate collision',
		skillName_th = 'การปะทะที่เหนือชั้นสุดยอด',
		skillName_in = 'Tabrakan tertinggi',
		skillName_ph = 'Pinakamataas na banggaan',
		skillName_ma = 'Perlanggaran tertinggi',
		skillName = 'Ultimate collision',
		describe_vn = 'Metagross thu chân lại, dồn toàn lực lao vào mục tiêu hàng trước của kẻ địch, gây #C0xE69900#230% Công Vật Lý#C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, tiêu hao toàn bộ điểm năng lượng, mỗi 1 điểm năng lượng tăng 40% sát thương kỹ năng tối thượng',
		describe_en = 'Metagross withdraws its legs and charges all its strength at the enemy\'s front-line target, dealing #C0xE69900#230% Physical Attack#C0x5B545B# + $(skillLevel*4*42)$ #C0xF13B54# Physical Damage#C0x5B545B#. It consumes all energy points, with each energy point increasing the ultimate skill\'s damage by 40%.',
		describe_th = 'Metagross รวบขาและใช้พลังทั้งหมดพุ่งโจมตีเป้าหมายแถวหน้าของศัตรู สร้างความเสียหาย #C0xE69900#230% การโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*42)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ใช้พลังงานทั้งหมด โดยพลังงานแต่ละจุดเพิ่มความเสียหายสกิลอัลติเมทขึ้น 40%.',
		describe_in = 'Metagross menarik kakinya dan mengerahkan seluruh kekuatan untuk menyerang target barisan depan musuh, memberikan #C0xE69900#230% Serangan Fisik#C0x5B545B# + $(skillLevel*4*42)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#. Menghabiskan semua poin energi, setiap poin energi meningkatkan kerusakan skill ultimate sebesar 40%.',
		describe_ph = 'Inililik si Metagross ang mga paa nito at inilalaan ang buong lakas sa target sa harapang linya ng kaaway, na nagdudulot ng #C0xE69900#230% Pisikal na Atake#C0x5B545B# + $(skillLevel*4*42)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Ginagamit ang lahat ng puntos ng enerhiya, kung saan bawat puntos ng enerhiya ay nagpapataas ng 40% ng pinsala ng ultimate skill.',
		describe_ma = 'Metagross menarik kakinya dan mengerahkan semua kekuatan menyerang sasaran barisan depan musuh, memberikan #C0xE69900#230% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*42)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Menggunakan semua mata tenaga, setiap mata tenaga menambahkan 40% kerosakan kemahiran maha akhir.',
		describe = 'Metagross withdraws its legs and charges all its strength at the enemy\'s front-line target, dealing #C0xE69900#230% Physical Attack#C0x5B545B# + $(skillLevel*4*42)$ #C0xF13B54# Physical Damage#C0x5B545B#. It consumes all energy points, with each energy point increasing the ultimate skill\'s damage by 40%.',
		simDesc_vn = 'Khổng Tước thu chân lại, sử dụng toàn bộ sức mạnh lao vào mục tiêu đơn lẻ của kẻ thù, tiêu hao tất cả điểm năng lượng; mỗi điểm năng lượng tăng cường sát thương chí mạng nhất định.',
		simDesc_en = 'The Peacock retracts its legs and uses all its strength to charge at a single enemy target, consuming all energy points; each energy point increases critical damage by a certain amount.',
		simDesc_th = 'นกยูงเก็บขาเข้ามา ใช้พลังทั้งหมดโจมตีเป้าหมายศัตรูเพียงหนึ่งเดียว ใช้พลังงานทั้งหมด; แต่ละพลังงานเพิ่มความเสียหายคริติคอลในระดับที่แน่นอน',
		simDesc_in = 'Merak menarik kakinya, menggunakan semua kekuatan untuk menyerang satu target musuh, menghabiskan semua poin energi; setiap poin energi meningkatkan kerusakan kritis tertentu.',
		simDesc_ph = 'Inaik ng Peacock ang mga paa, ginagamit ang buong lakas upang atakihin ang isang target na kalaban, kinakain ang lahat ng puntos ng enerhiya; bawat puntos ng enerhiya ay nagpapalakas ng tiyak na kritikal na pinsala.',
		simDesc_ma = 'Merak menarik kakinya, menggunakan semua kekuatan untuk menyerang satu sasaran musuh, menggunakan semua mata tenaga; setiap mata tenaga meningkatkan kerosakan kritikal tertentu.',
		simDesc = 'The Peacock retracts its legs and uses all its strength to charge at a single enemy target, consuming all energy points; each energy point increases critical damage by a certain amount.',
		starEffect = __data_t__starEffect[1019033],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Sau khi phát động kỹ năng chí mạng, giữ lại 300 điểm năng lượng và tăng 20% giảm Sát Thương Vật Lý trong 2 lượt.',
		starEffectDesc = 'Additional effect: After activating the critical skill, retain 300 energy points and increase Physical Damage Reduction by 20% for 2 turns.',
		starEffectDesc_en = 'Additional effect: After activating the critical skill, retain 300 energy points and increase Physical Damage Reduction by 20% for 2 turns.',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: หลังจากใช้สกิลคริติคอล เก็บพลังงานไว้ 300 แต้ม และเพิ่มการลดความเสียหายทางกายภาพ 20% เป็นเวลา 2 เทิร์น',
		starEffectDesc_in = 'Efek tambahan: Setelah mengaktifkan keterampilan kritis, pertahankan 300 poin energi dan tingkatkan pengurangan Kerusakan Fisik sebesar 20% selama 2 giliran.',
		starEffectDesc_ph = 'Karagdagang epekto: Pagkatapos i-activate ang critical skill, panatilihin ang 300 puntos ng enerhiya at pataasin ang 20% na pagbawas ng Pisikal na Pinsala sa loob ng 2 turn.',
		starEffectDesc_ma = 'Kesan tambahan: Selepas mengaktifkan kemahiran kritikal, simpan 300 mata tenaga dan tingkatkan pengurangan Kerosakan Fizikal sebanyak 20% selama 2 giliran.',
