	[1019613] = {
		id = 1019613,
		skillName_vn = 'Tiếng gầm của sóng dữ',
		skillName_en = 'The roar of the furious waves',
		skillName_th = 'เสียงคำรามของคลื่นโหมกระหน่ำ',
		skillName_in = 'Raungan gelombang yang ganas',
		skillName_ph = 'Ang ungol ng mabangis na alon',
		skillName_ma = 'Raungan ombak yang ganas',
		skillName = 'The roar of the furious waves',
		describe_vn = 'Kyogre triệu hồi một cơn sóng lớn, sóng sẽ nảy 6 lần giữa các mục tiêu đơn địch, lần nảy đầu tiên gây sát thương phép #C0x3D8A99#300% Công Phép#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#sát thương phép#C0x5B545B# (mỗi lần nảy không trùng mục tiêu, nếu chỉ có một mục tiêu trên sân thì không nảy nữa, sát thương giảm 30% mỗi lần nảy), mỗi lần nảy giảm 10% tốc độ của mục tiêu (tối đa cộng dồn 5 tầng), kéo dài 2 lượt.',
		describe_en = 'Kyogre summons a massive wave that bounces 6 times between single enemy targets. The first bounce deals magic damage of #C0x3D8A99#300% Magic Power#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# magic damage#C0x5B545B#. Each bounce hits a different target; if there\'s only one target on the field, it won\'t bounce anymore. Damage decreases by 30% with each bounce. Each bounce also reduces the target\'s speed by 10% (up to 5 stacks), lasting 2 turns.',
		describe_th = 'Kyogre เรียกคลื่นขนาดใหญ่ซึ่งจะกระเด้ง 6 ครั้งระหว่างเป้าหมายศัตรูเดี่ยว การกระเด้งครั้งแรกสร้างความเสียหายเวทมนตร์ #C0x3D8A99#300% พลังเวท#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายเวท#C0x5B545B#. ทุกครั้งที่กระเด้งจะต้องโดนเป้าหมายที่แตกต่างกัน; หากในสนามมีเป้าหมายแค่หนึ่งตัว จะไม่กระเด้งต่อไป ความเสียหายจะลดลง 30% ในทุกครั้งที่กระเด้ง นอกจากนี้แต่ละครั้งที่กระเด้งจะลดความเร็วของเป้าหมายลง 10% (สะสมได้สูงสุด 5 ชั้น) ดำเนินการนาน 2 เทิร์น',
		describe_in = 'Kyogre memanggil gelombang besar yang memantul 6 kali di antara target musuh tunggal. Pantulan pertama memberikan damage sihir sebesar #C0x3D8A99#300% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# damage sihir#C0x5B545B#. Setiap pantulan mengenai target yang berbeda; jika hanya ada satu target di medan, pantulan tidak akan berlanjut. Damage berkurang 30% setiap pantulan. Setiap pantulan juga mengurangi kecepatan target sebesar 10% (maksimal bertumpuk 5 kali), berlangsung selama 2 giliran.',
		describe_ph = 'Si Kyogre ay nag-summon ng malaking alon na tumatalbog ng 6 na beses sa pagitan ng iisang target na kalaban. Ang unang talbog ay nagdudulot ng magic damage na #C0x3D8A99#300% Magic Power#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# magic damage#C0x5B545B#. Bawat talbog ay tumatama sa ibang target; kung iisa lang ang target sa larangan, hindi na ito tatabog pa. Bumaba ang damage ng 30% sa bawat talbog. Bawat talbog ay nagpapababa rin ng bilis ng target ng 10% (hanggang makapundong 5 beses), tumatagal ng 2 turn.',
		describe_ma = 'Kyogre memanggil gelombang besar yang memantul 6 kali antara sasaran musuh tunggal. Pantulan pertama menyebabkan kerosakan sihir #C0x3D8A99#300% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# kerosakan sihir#C0x5B545B#. Setiap pantulan mengenai sasaran yang berbeza; jika hanya ada satu sasaran di medan, pantulan tidak akan berterusan. Kerosakan berkurang 30% setiap kali pantulan. Setiap pantulan juga mengurangkan kelajuan sasaran sebanyak 10% (sehingga maksimum 5 timbunan), berlangsung selama 2 pusingan.',
		describe = 'Kyogre summons a massive wave that bounces 6 times between single enemy targets. The first bounce deals magic damage of #C0x3D8A99#300% Magic Power#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# magic damage#C0x5B545B#. Each bounce hits a different target; if there\'s only one target on the field, it won\'t bounce anymore. Damage decreases by 30% with each bounce. Each bounce also reduces the target\'s speed by 10% (up to 5 stacks), lasting 2 turns.',
		simDesc_vn = 'Gai Ô Ca triệu hồi một cơn sóng lớn, sóng sẽ bật giữa các mục tiêu đơn lẻ của kẻ thù; mỗi lần bật giảm tốc độ của chúng.',
		simDesc_en = 'Gai Oca summons a massive wave that bounces between individual enemy targets; each bounce reduces their speed.',
		simDesc_th = 'ไก โอคะ เรียกคลื่นใหญ่ที่สาดกระเซ็นระหว่างเป้าหมายศัตรูทีละตัว; ทุกครั้งที่กระเด้งจะลดความเร็วของพวกมัน',
		simDesc_in = 'Gai Oca memanggil gelombang besar yang memantul di antara target musuh satu per satu; setiap pantulan mengurangi kecepatan mereka.',
		simDesc_ph = 'Gai Oca ay nag-summon ng malaking alon na tumatama sa bawat isa-isang target ng kalaban; bawat tama ay nagpapabagal sa kanilang galaw.',
		simDesc_ma = 'Gai Oca memanggil gelombang besar yang memantul di antara sasaran musuh secara individu; setiap pantulan mengurangkan kelajuan mereka.',
		simDesc = 'Gai Oca summons a massive wave that bounces between individual enemy targets; each bounce reduces their speed.',
		starEffect = __data_t__starEffect[1019613],
