	[1019712] = {
		id = 1019712,
		skillName_vn = 'Khóa đá',
		skillName_en = 'Rock Lock',
		skillName_th = 'ล็อกหิน',
		skillName_in = 'Kunci Batu',
		skillName_ph = 'Rock Lock',
		skillName_ma = 'Kunci Batu',
		skillName = 'Rock Lock',
		describe_vn = 'Groudon đập đất, sau đó nâng đá tấn công mục tiêu đơn, gây Sát Thương Vật Lý #C0xE69900#160% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, đòn tấn công này có hiệu ứng xuyên thấu mặt đất (gây thêm 40% sát thương cuối cùng của kỹ năng này lên mục tiêu phía sau); đồng thời kéo dài thời gian hồi chiêu của kỹ năng nhỏ của mục tiêu thêm 2 lượt.',
		describe_en = 'Groudon slams the ground, then lifts a rock to attack a single target, dealing Physical Damage equal to 160% of Physical Attack plus $(skillLevel*4*24)$ Physical Damage. This attack pierces through the ground (dealing an additional 40% of the final damage of this skill to the target behind); meanwhile, it also extends the cooldown time of the target\'s minor skill by 2 turns.',
		describe_th = 'กรูดอนทุบพื้นแล้วยกหินโจมตีเป้าหมายเดี่ยว สร้างความเสียหายทางกายภาพเท่ากับ 160% ของพลังโจมตีทางกายภาพบวก $(skillLevel*4*24)$ ความเสียหายทางกายภาพ โจมตีนี้มีผลทะลุทะลวงพื้นดิน (สร้างความเสียหายเพิ่มเติม 40% ของความเสียหายสุดท้ายของสกิลนี้แก่เป้าหมายด้านหลัง); พร้อมกันนี้ยังเพิ่มเวลาคูลดาวน์ของสกิลเล็กของเป้าหมายอีก 2 เทิร์น',
		describe_in = 'Groudon menghantam tanah, lalu mengangkat batu untuk menyerang satu target, memberikan Kerusakan Fisik sebesar 160% dari Serangan Fisik ditambah $(skillLevel*4*24)$ Kerusakan Fisik. Serangan ini menembus tanah (memberikan tambahan 40% kerusakan akhir dari skill ini ke target di belakang); sekaligus memperpanjang waktu cooldown skill kecil target selama 2 giliran.',
		describe_ph = 'Binugbog ni Groudon ang lupa, pagkatapos ay inangat ang bato para atakihin ang isang target, na nagdudulot ng Physical Damage na katumbas ng 160% Physical Attack plus $(skillLevel*4*24)$ Physical Damage. Ang atakeng ito ay may epekto na tumagos sa lupa (nagbibigay ng karagdagang 40% ng huling damage ng skill na ito sa target sa likod); kasabay nito, pinahaba ang cooldown ng maliit na skill ng target ng 2 turn.',
		describe_ma = 'Groudon menghentak tanah, kemudian mengangkat batu menyerang sasaran tunggal, memberikan Kerosakan Fizikal sebanyak 160% Serangan Fizikal ditambah $(skillLevel*4*24)$ Kerosakan Fizikal. Serangan ini mempunyai kesan menembusi tanah (menyebabkan tambahan 40% kerosakan terakhir kemahiran ini kepada sasaran di belakang); serta memanjangkan masa penyejukan kemahiran kecil sasaran sebanyak 2 giliran.',
		describe = 'Groudon slams the ground, then lifts a rock to attack a single target, dealing Physical Damage equal to 160% of Physical Attack plus $(skillLevel*4*24)$ Physical Damage. This attack pierces through the ground (dealing an additional 40% of the final damage of this skill to the target behind); meanwhile, it also extends the cooldown time of the target\'s minor skill by 2 turns.',
		simDesc_vn = 'Cố La Đô đập xuống mặt đất, sau đó nâng cao đá tấn công mục tiêu hàng dọc.',
		simDesc_en = 'Kola slammed the ground, then raised the stone to attack the vertical target line.',
		simDesc_th = 'โคลา กระแทกลงที่พื้น จากนั้นยกหินขึ้นโจมตีเป้าหมายในแนวตั้ง',
		simDesc_in = 'Kola memukul tanah, kemudian mengangkat batu untuk menyerang target vertikal.',
		simDesc_ph = 'Binangga ni Kola ang lupa, saka itinaas ang bato para atakihin ang patayong target.',
