	[1019713] = {
		id = 1019713,
		skillName_vn = 'Kiếm vực thẳm',
		skillName_en = 'Abyssal Sword',
		skillName_th = 'ดาบลึกลงไปในหุบเหว',
		skillName_in = 'Pedang Jurang',
		skillName_ph = 'Tabak ng Kailaliman',
		skillName_ma = 'Pedang Gaung',
		skillName = 'Abyssal Sword',
		describe_vn = 'Groudon thức tỉnh từ giấc ngủ, sau đó điều khiển núi đá đâm vào mục tiêu đơn địch, gây Sát Thương Vật Lý #C0xE69900#660% Công Vật Lý#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, đòn tấn công này có hiệu ứng lan tỏa mặt đất (gây thêm 35% sát thương cuối cùng của kỹ năng này lên các mục tiêu xung quanh); kích hoạt hiệu ứng [Sức mạnh nguyên thủy] trong 2 lượt: trước khi bị tấn công, tăng 8% giảm sát thương cho bản thân (có thể cộng dồn), sau khi hiệu ứng [Sức mạnh nguyên thủy] biến mất, giữ lại vĩnh viễn một nửa lượng tăng giảm sát thương từ hiệu ứng này.',
		describe_en = 'Groudon awakens from its slumber, then commands rocky mountains to pierce a single enemy target, causing Physical Damage #C0xE69900#660% Physical Attack#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Physical Damage#C0x5B545B#. This attack has a ground spreading effect (deals an additional 35% of the final damage of this skill to surrounding targets); activates the [Primordial Power] effect for 2 turns: before being attacked, increases damage reduction by 8% for itself (can stack), and after the [Primordial Power] effect ends, permanently retains half of the increased or decreased damage from this effect.',
		describe_th = 'กรูดอนตื่นขึ้นจากการหลับใหล จากนั้นควบคุมภูเขาหินแทงใส่เป้าหมายศัตรูเดี่ยว สร้างความเสียหายกายภาพ #C0xE69900#660% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# ความเสียหายกายภาพ#C0x5B545B# การโจมตีนี้มีผลกระทบแบบกระจายบนพื้นดิน (สร้างความเสียหายเพิ่มเติม 35% ของความเสียหายขั้นสุดท้ายของสกิลนี้กับเป้าหมายรอบข้าง); เปิดใช้งานเอฟเฟกต์ [พลังดั้งเดิม] เป็นเวลา 2 เทิร์น: ก่อนถูกโจมตี เพิ่มการลดความเสียหาย 8% ให้ตัวเอง (สามารถทับซ้อนได้) และหลังเอฟเฟกต์ [พลังดั้งเดิม] หมดลง จะเก็บค่าครึ่งหนึ่งของการเพิ่มหรือลดความเสียหายจากเอฟเฟกต์นี้ไว้อย่างถาวร',
		describe_in = 'Groudon bangun dari tidurnya, kemudian mengendalikan gunung batu untuk menusuk satu target musuh, menyebabkan Damage Fisik #C0xE69900#660% Serangan Fisik#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Damage Fisik#C0x5B545B#. Serangan ini memiliki efek menyebar ke tanah (menimbulkan tambahan 35% dari damage akhir skill ini ke target di sekitar); mengaktifkan efek [Kekuatan Primordial] selama 2 giliran: sebelum diserang, meningkatkan pengurangan damage sebesar 8% untuk dirinya sendiri (dapat menumpuk), dan setelah efek [Kekuatan Primordial] hilang, mempertahankan secara permanen setengah dari peningkatan atau pengurangan damage dari efek ini.',
		describe_ph = 'Nagising si Groudon mula sa pagtulog, pagkatapos ay kinokontrol ang mga batong bundok para tusukin ang isang solong kalabang target, na nagdudulot ng Pisikal na Pinsala #C0xE69900#660% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Pisikal na Pinsala#C0x5B545B#. Ang pag-atakeng ito ay may epekto sa pagkalat sa lupa (nagdudulot ng dagdag na 35% ng huling pinsala ng kasanayang ito sa mga kalapit na target); pinapagana ang epekto ng [Primordial na Kapangyarihan] sa loob ng 2 turn: bago matamaan, nagpapataas ng 8% bawas pinsala para sa sarili (maaaring mag-stack), at matapos mawala ang epekto ng [Primordial na Kapangyarihan], permanenteng pinananatili ang kalahati ng nadagdag o nabawas na pinsala mula sa epektong ito.',
		describe_ma = 'Groudon terjaga dari tidurnya, kemudian mengawal gunung batu untuk menikam sasaran musuh tunggal, menyebabkan Kerosakan Fizikal #C0xE69900#660% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Kerosakan Fizikal#C0x5B545B#. Serangan ini mempunyai efek menyebar ke tanah (menyebabkan tambahan 35% kerosakan akhir kemahiran ini ke sasaran sekitar); mengaktifkan efek [Kuasa Primal] selama 2 pusingan: sebelum diserang, meningkatkan pengurangan kerosakan sebanyak 8% untuk diri sendiri (boleh bertindih), dan selepas efek [Kuasa Primal] tamat, mengekalkan secara kekal separuh daripada peningkatan atau pengurangan kerosakan dari efek ini.',
		describe = 'Groudon awakens from its slumber, then commands rocky mountains to pierce a single enemy target, causing Physical Damage #C0xE69900#660% Physical Attack#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54# Physical Damage#C0x5B545B#. This attack has a ground spreading effect (deals an additional 35% of the final damage of this skill to surrounding targets); activates the [Primordial Power] effect for 2 turns: before being attacked, increases damage reduction by 8% for itself (can stack), and after the [Primordial Power] effect ends, permanently retains half of the increased or decreased damage from this effect.',
		simDesc_vn = 'Cố La Đô từ giấc ngủ tỉnh dậy, sau đó điều khiển đá núi đâm vào mục tiêu đơn lẻ của kẻ thù; lần tấn công này kèm theo hiệu ứng nứt đất và kích hoạt hiệu ứng sức mạnh nguyên thủy.',
		simDesc_en = 'Kola woke up from sleep, then controlled a boulder to strike a single enemy target; this attack came with an earth-cracking effect and triggered the primal power effect.',
		simDesc_th = 'โคลา ตื่นขึ้นจากการหลับ จากนั้นควบคุมก้อนหินพุ่งชนเป้าหมายศัตรูเพียงหนึ่งเดียว การโจมตีครั้งนี้มาพร้อมกับเอฟเฟกต์แผ่นดินแตกร้าวและเปิดใช้งานเอฟเฟกต์พลังดั้งเดิม',
		simDesc_in = 'Kola terbangun dari tidur, lalu mengendalikan batu besar untuk menusuk satu target musuh; serangan ini disertai efek retakan tanah dan mengaktifkan efek kekuatan primal.',
		simDesc_ph = 'Nagising si Kola mula sa pagtulog, pagkatapos ay ginamit ang isang bato upang tumama sa isang kalabang target; ang pag-atakeng ito ay may kasamang epekto ng pagbasag ng lupa at nag-activate ng epekto ng primal na kapangyarihan.',
		simDesc_ma = 'Kola terjaga dari tidur, kemudian mengawal batu besar untuk menyerang sasaran musuh tunggal; serangan ini disertai dengan kesan retakan bumi dan mengaktifkan kesan kuasa primal.',
		simDesc = 'Kola woke up from sleep, then controlled a boulder to strike a single enemy target; this attack came with an earth-cracking effect and triggered the primal power effect.',
		starEffect = __data_t__starEffect[1019713],
		-- {11}
		starEffectDesc_vn = '<Sức mạnh nguyên thủy> có thể giữ lại 80% hiệu ứng; gây thêm 50% sát thương thật dựa trên lượng máu mất của mục tiêu (mục tiêu bị bắn trúng cũng sẽ nhận thêm sát thương theo tỷ lệ bắn trúng)',
		starEffectDesc = '<#F 1019713#><#L 1019713#> <Primal Power> can retain 80% of the effect; deals an additional 50% true damage based on the target\'s lost HP (targets hit will also receive extra damage according to the hit rate)',
		starEffectDesc_en = '<#F 1019713#><#L 1019713#> <Primal Power> can retain 80% of the effect; deals an additional 50% true damage based on the target\'s lost HP (targets hit will also receive extra damage according to the hit rate)',
		starEffectDesc_th = '<#F 1019713#><#L 1019713#> <พลังดั้งเดิม> สามารถรักษาผลกระทบได้ 80%; gâyความเสียหายจริงเพิ่มขึ้น 50% ตามจำนวนเลือดที่เสียไปของเป้าหมาย (เป้าหมายที่ถูกยิงจะได้รับความเสียหายเพิ่มเติมตามอัตราการยิงโดน)',
		starEffectDesc_in = '<#F 1019713#><#L 1019713#> <Kekuatan Primal> dapat mempertahankan 80% efek; memberikan tambahan 50% damage nyata berdasarkan jumlah HP yang hilang dari target (target yang terkena tembakan juga akan menerima damage tambahan sesuai dengan persentase tembakan yang mengenai)',
		starEffectDesc_ph = '<#F 1019713#><#L 1019713#> <Primal Power> ay maaaring panatilihin ang 80% ng epekto; nagdudulot ng karagdagang 50% tunay na pinsala batay sa nawalan ng HP ng target (ang target na tinamaan ay tatanggap din ng karagdagang pinsala ayon sa porsyento ng pagtama)',
		starEffectDesc_ma = '<#F 1019713#><#L 1019713#> <Kuasa Asal> boleh mengekalkan 80% kesan; menyebabkan tambahan 50% kerosakan sebenar berdasarkan jumlah HP yang hilang daripada sasaran (sasaran yang terkena tembakan juga akan menerima kerosakan tambahan mengikut peratusan tembakan yang terkena)',
