	[1019812] = {
		id = 1019812,
		skillName_vn = 'Lốc xoáy',
		skillName_en = 'Tornado',
		skillName_th = 'พายุทอร์นาโด',
		skillName_in = 'Tornado',
		skillName_ph = 'Ipo-ipo',
		skillName_ma = 'Tornado',
		skillName = 'Tornado',
		describe_vn = 'Rayquaza xoay người triệu hồi lốc xoáy tấn công mục tiêu đơn địch, gây Sát Thương Vật Lý #C0xE69900#80% Công Vật Lý#C0x5B545B#+#C0x3D8A99#80% Công Phép#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#sát thương phép#C0x5B545B#, thổi mục tiêu lên không trung (trong thời gian này không thể tấn công hoặc bị tấn công) trong 1 lượt, khi mục tiêu rơi xuống đất có 70% cơ hội bị choáng thêm 1 lượt (càng nhiều mục tiêu xung quanh, tỷ lệ choáng càng cao, tối đa tăng lên 100%).',
		describe_en = 'Rayquaza spins to summon a whirlwind that attacks a single enemy target, dealing Physical Damage of 80% Physical Attack + 80% Magic Attack + $(skillLevel*4*48)$ magic damage. It lifts the target into the air (during this time the target cannot attack or be attacked) for 1 turn. When the target falls to the ground, there is a 70% chance to stun for an additional turn (the more targets nearby, the higher the stun chance, up to a maximum of 100%).',
		describe_th = 'เรเควซ่า หมุนตัวเรียกพายุหมุนโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายกายภาพ 80% พลังโจมตีทางกายภาพ + 80% พลังโจมตีทางเวทมนตร์ + $(skillLevel*4*48)$ ความเสียหายเวทมนตร์ ยกเป้าหมายขึ้นกลางอากาศ (ในระหว่างนี้ไม่สามารถโจมตีหรือถูกโจมตีได้) เป็นเวลา 1 เทิร์น เมื่อเป้าหมายตกลงสู่พื้น มีโอกาส 70% ที่จะติดสถานะมึนงงเพิ่มอีก 1 เทิร์น (ยิ่งมีเป้าหมายรอบข้างมาก โอกาสติดมึนงงก็จะสูงขึ้น สูงสุดถึง 100%)',
		describe_in = 'Rayquaza berputar untuk memanggil pusaran angin yang menyerang satu musuh, memberikan Kerusakan Fisik sebesar 80% Serangan Fisik + 80% Serangan Magis + $(skillLevel*4*48)$ kerusakan magis, mengangkat target ke udara (selama waktu ini target tidak dapat menyerang atau diserang) selama 1 giliran. Ketika target jatuh ke tanah, ada peluang 70% untuk terkena stun tambahan selama 1 giliran (semakin banyak musuh di sekitar, peluang stun semakin tinggi, maksimal hingga 100%).',
		describe_ph = 'Si Rayquaza ay nagpapaliko upang magpatawag ng whirlwind na umaatake sa isang kaaway, nagdudulot ng Physical Damage na 80% Physical Attack + 80% Magic Attack + $(skillLevel*4*48)$ magic damage. Itinatangay ang target sa himpapawid (sa panahong ito ay hindi makakasugod o matatamaan ang target) sa loob ng 1 turn. Kapag bumagsak ang target sa lupa, may 70% chance na ma-stun pa ng 1 turn (mas maraming kalaban sa paligid, mas mataas ang chance ng stun, hanggang sa maximum na 100%).',
		describe_ma = 'Rayquaza berpusing untuk memanggil pusaran angin yang menyerang satu sasaran musuh, menyebabkan Kerosakan Fizikal sebanyak 80% Serangan Fizikal + 80% Serangan Sihir + $(skillLevel*4*48)$ kerosakan sihir, meniup sasaran ke udara (dalam tempoh ini sasaran tidak boleh menyerang atau diserang) selama 1 pusingan. Apabila sasaran jatuh ke tanah, terdapat peluang 70% untuk terkena pengganguan tambahan selama 1 pusingan (semakin banyak sasaran di sekeliling, peluang pengganguan semakin tinggi, maksimum sehingga 100%).',
		describe = 'Rayquaza spins to summon a whirlwind that attacks a single enemy target, dealing Physical Damage of 80% Physical Attack + 80% Magic Attack + $(skillLevel*4*48)$ magic damage. It lifts the target into the air (during this time the target cannot attack or be attacked) for 1 turn. When the target falls to the ground, there is a 70% chance to stun for an additional turn (the more targets nearby, the higher the stun chance, up to a maximum of 100%).',
