	[1019813] = {
		id = 1019813,
		skillName_vn = 'Điểm nhấn rồng',
		skillName_en = 'Dragon highlight',
		skillName_th = 'ไฮไลต์มังกร',
		skillName_in = 'Sorotan naga',
		skillName_ph = 'Dragon highlight',
		skillName_ma = 'Sorotan naga',
		skillName = 'Dragon highlight',
		describe_vn = 'Rayquaza bay lên cao, kéo mục tiêu hàng ngang địch lên không trung, sau đó giải phóng sức mạnh Rayquaza, gây Sát Thương Vật Lý #C0xE69900#180% Công Vật Lý#C0x5B545B#+#C0x3D8A99#180% Công Phép#C0x5B545B#+$(skillLevel*4*80)$#C0xF13B54#sát thương phép#C0x5B545B#, Rayquaza điều chỉnh tinh thần chiến đấu của mục tiêu: khóa nộ khí của mục tiêu trong 1 lượt (trong thời gian khóa không thể hồi phục nộ khí).',
		describe_en = 'Rayquaza flies high, pulls the enemy\'s entire horizontal row into the air, then unleashes Rayquaza\'s power, dealing Physical Damage #C0xE69900#180% Physical Attack#C0x5B545B# + #C0x3D8A99#180% Magical Attack#C0x5B545B# + $(skillLevel*4*80)$ #C0xF13B54#magic damage#C0x5B545B#. Rayquaza manipulates the target\'s fighting spirit: seals the target\'s rage for 1 turn (no rage recovery during the seal).',
		describe_th = 'เรย์เควซ่า บินสูง ดึงเป้าหมายในแถวศัตรูทั้งหมดขึ้นสู่ท้องฟ้า จากนั้นปลดปล่อยพลังของเรย์เควซ่า สร้างความเสียหายกายภาพ #C0xE69900#180% พลังโจมตีทางกายภาพ#C0x5B545B# + #C0x3D8A99#180% พลังโจมตีเวทมนตร์#C0x5B545B# + $(skillLevel*4*80)$ #C0xF13B54#ความเสียหายเวทมนตร์#C0x5B545B# เรย์เควซ่าควบคุมจิตใจการต่อสู้ของเป้าหมาย: ปิดการใช้พลังโกรธของเป้าหมายเป็นเวลา 1 เทิร์น (ในช่วงเวลาที่ถูกปิดจะไม่สามารถฟื้นฟูพลังโกรธได้).',
		describe_in = 'Rayquaza terbang tinggi, menarik seluruh barisan musuh ke udara, lalu melepaskan kekuatan Rayquaza, menyebabkan Damage Fisik #C0xE69900#180% Serangan Fisik#C0x5B545B# + #C0x3D8A99#180% Serangan Magis#C0x5B545B# + $(skillLevel*4*80)$ #C0xF13B54#damage magis#C0x5B545B#. Rayquaza mengendalikan semangat juang target: mengunci kemarahan target selama 1 giliran (selama terkunci tidak dapat memulihkan kemarahan).',
		describe_ph = 'Lumilipad si Rayquaza nang mataas, hinihila ang buong horizontal na hanay ng kaaway pataas, pagkatapos ay pinapalabas ang lakas ni Rayquaza, nagdudulot ng Physical Damage #C0xE69900#180% Physical Attack#C0x5B545B# + #C0x3D8A99#180% Magical Attack#C0x5B545B# + $(skillLevel*4*80)$ #C0xF13B54#magic damage#C0x5B545B#. Kinokontrol ni Rayquaza ang fighting spirit ng target: kinukulong ang galit ng target sa loob ng 1 turn (habang nakakulong ay hindi makakahikbang mag-recover ng galit).',
		describe_ma = 'Rayquaza terbang tinggi, menarik barisan musuh sepenuhnya ke udara, kemudian melepaskan kekuatan Rayquaza, menyebabkan Kerosakan Fizikal #C0xE69900#180% Serangan Fizikal#C0x5B545B# + #C0x3D8A99#180% Serangan Sihir#C0x5B545B# + $(skillLevel*4*80)$ #C0xF13B54#kerosakan sihir#C0x5B545B#. Rayquaza mengawal semangat berperang sasaran: mengunci kemarahan sasaran selama 1 pusingan (dalam masa kunci tidak boleh memulihkan kemarahan).',
		describe = 'Rayquaza flies high, pulls the enemy\'s entire horizontal row into the air, then unleashes Rayquaza\'s power, dealing Physical Damage #C0xE69900#180% Physical Attack#C0x5B545B# + #C0x3D8A99#180% Magical Attack#C0x5B545B# + $(skillLevel*4*80)$ #C0xF13B54#magic damage#C0x5B545B#. Rayquaza manipulates the target\'s fighting spirit: seals the target\'s rage for 1 turn (no rage recovery during the seal).',
		simDesc_vn = 'Liệt Không Tọa bay lên cao, đưa mục tiêu hàng dọc của kẻ thù lên không trung, sau đó phóng ra sức mạnh liệt không, khiến tức giận của mục tiêu bị khóa lại.',
		simDesc_en = 'Liệt Không Tọa rises high, lifting the enemy\'s vertical targets into the air, then unleashes the power of Liệt Không, locking the targets\' anger.',
		simDesc_th = 'Liệt Không Tọa บินขึ้นสูง ยกเป้าหมายในแนวดิ่งของศัตรูขึ้นกลางอากาศ จากนั้นปล่อยพลังของ Liệt Không ทำให้ความโกรธของเป้าหมายถูกล็อคไว้',
		simDesc_in = 'Liệt Không Tọa terbang tinggi, mengangkat target vertikal musuh ke udara, kemudian melepaskan kekuatan Liệt Không, mengunci kemarahan target.',
		simDesc_ph = 'Si Liệt Không Tọa ay tumataas nang mataas, dinadala ang mga patayong target ng kaaway sa himpapawid, pagkatapos ay inilalabas ang kapangyarihan ng Liệt Không, na nakakandado sa galit ng mga target.',
		simDesc_ma = 'Liệt Không Tọa terbang tinggi, mengangkat sasaran menegak musuh ke udara, kemudian melepaskan kuasa Liệt Không, mengunci kemarahan sasaran.',
		simDesc = 'Liệt Không Tọa rises high, lifting the enemy\'s vertical targets into the air, then unleashes the power of Liệt Không, locking the targets\' anger.',
		starEffect = __data_t__starEffect[1019813],
		-- {11}
		starEffectDesc_vn = 'Thêm vào mục tiêu sát thương thực tế bằng tổng Sát Thương Vật Lý và phép thuật của bản thân là 30% (sát thương này có thể chí mạng và không bị ảnh hưởng bởi miễn dịch sát thương phép hoặc vật lý).',
		starEffectDesc = 'Add to the actual damage target by 30% of the sum of your own Physical and Magical Damage (this damage can critical hit and is not affected by magic or physical damage immunity).',
		starEffectDesc_en = 'Add to the actual damage target by 30% of the sum of your own Physical and Magical Damage (this damage can critical hit and is not affected by magic or physical damage immunity).',
		starEffectDesc_th = 'เพิ่มไปยังเป้าหมายที่ได้รับความเสียหายจริงโดย 30% ของผลรวมความเสียหายทางกายภาพและเวทมนตร์ของตัวเอง (ความเสียหายนี้สามารถคริติคอลและไม่ถูกผลกระทบจากการป้องกันความเสียหายเวทหรือกายภาพ).',
		starEffectDesc_in = 'Tambahkan ke target kerusakan nyata sebesar 30% dari total Kerusakan Fisik dan Magis Anda sendiri (kerusakan ini dapat terkena kritikal dan tidak terpengaruh oleh imun terhadap kerusakan magis atau fisik).',
		starEffectDesc_ph = 'Magdagdag sa aktwal na target ng pinsala ng 30% ng kabuuang Pisikal at Mahiwagang Pinsala ng sarili mo (ang pinsalang ito ay maaaring maging kritikal at hindi naapektuhan ng immune sa mahiwaga o pisikal na pinsala).',
		starEffectDesc_ma = 'Tambah kepada sasaran kerosakan sebenar sebanyak 30% daripada jumlah Kerosakan Fizikal dan Magikal anda sendiri (kerosakan ini boleh mendapat serangan kritikal dan tidak terjejas oleh imuniti kerosakan magikal atau fizikal).',
		upLvDesc = 'Fixed damage +320',
		upLvDesc_en = 'Fixed damage +320',
		upLvDesc_th = 'ความเสียหายคงที่ +320',
		upLvDesc_in = 'Kerusakan tetap +320',
		upLvDesc_ph = 'Fixed damage +320',
