	[1022421] = {
		id = 1022421,
		skillName_vn = 'Tăng cường sức mạnh',
		skillName_en = 'Power up',
		skillName_th = 'เพิ่มพลัง',
		skillName_in = 'Tingkatkan kekuatan',
		skillName_ph = 'Palakasin',
		skillName_ma = 'Memperkuat kuasa',
		skillName = 'Power up',
		describe_vn = 'Lucario tấn công về phía trước, sau đó nhảy lên cao tung một cú đấm mạnh, gây Sát Thương Vật Lý #C0xE69900#140% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B# lên mục tiêu đơn địch, đồng thời tăng 15% tốc độ cho bản thân, kéo dài 2 lượt.',
		describe_en = 'Lucario attacks forward, then jumps high to deliver a powerful punch, dealing Physical Damage #C0xE69900#140% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Physical Damage#C0x5B545B# to a single enemy target, while increasing its own speed by 15% for 2 turns.',
		describe_th = 'ูคาริโอ้โจมตีไปข้างหน้า จากนั้นกระโดดขึ้นสูงและชกอย่างแรง สร้างความเสียหายทางกายภาพ #C0xE69900#140% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# ต่อศัตรูเป้าหมายเดียว พร้อมทั้งเพิ่มความเร็วให้ตัวเอง 15% เป็นเวลา 2 เทิร์น',
		describe_in = 'Lucario menyerang ke depan, kemudian melompat tinggi dan melancarkan pukulan kuat, memberikan Kerusakan Fisik #C0xE69900#140% Serangan Fisik#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerusakan Fisik#C0x5B545B# pada satu target musuh, sekaligus meningkatkan kecepatan sendiri sebesar 15% selama 2 giliran.',
		describe_ph = 'Umuurong sina si Lucario, pagkatapos ay tumalon nang mataas at nagpalabas ng malakas na suntok, na nagdudulot ng Physical Damage #C0xE69900#140% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Physical Damage#C0x5B545B# sa isang kaaway, sabay tumaas ng 15% ang bilis niya sa loob ng 2 turn.',
		describe_ma = 'Lucario menyerang ke hadapan, kemudian melompat tinggi dan melancarkan satu tumbukan kuat, memberikan Kerosakan Fizikal #C0xE69900#140% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerosakan Fizikal#C0x5B545B# kepada satu sasaran musuh, sambil meningkatkan kelajuan dirinya sebanyak 15% selama 2 pusingan.',
		describe = 'Lucario attacks forward, then jumps high to deliver a powerful punch, dealing Physical Damage #C0xE69900#140% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Physical Damage#C0x5B545B# to a single enemy target, while increasing its own speed by 15% for 2 turns.',
		simDesc_vn = 'Luka Liêu tiến lên tấn công, sau đó nhảy cao tung một cú đấm mạnh.',
		simDesc_en = 'Luka advances to attack, then jumps high and delivers a powerful punch.',
		simDesc_th = 'ลูคาโจมตีไปข้างหน้า จากนั้นกระโดดสูงและชกด้วยหมัดที่ทรงพลัง',
		simDesc_in = 'Luka maju menyerang, lalu melompat tinggi dan melayangkan pukulan kuat.',
		simDesc_ph = 'Si Luka ay bumangon upang umatake, pagkatapos ay tumalon nang mataas at naglabas ng malakas na suntok.',
		simDesc_ma = 'Luka maju menyerang, kemudian melompat tinggi dan melontar satu tumbukan kuat.',
		simDesc = 'Luka advances to attack, then jumps high and delivers a powerful punch.',
		upLvDesc = 'Fixed damage +96',
