	[1022422] = {
		id = 1022422,
		skillName_vn = 'Tốc độ ánh sáng ý niệm',
		skillName_en = 'Speed of light concept',
		skillName_th = 'ความคิดเรื่องความเร็วแสง',
		skillName_in = 'Konsep kecepatan cahaya',
		skillName_ph = 'Konsepto ng bilis ng liwanag',
		skillName_ma = 'Konsep kelajuan cahaya',
		skillName = 'Speed of light concept',
		describe_vn = 'Lucario tập trung sức mạnh triệu hồi khí chân thật từ tay, sau đó ném mạnh vào mục tiêu đơn địch, gây Sát Thương Vật Lý #C0xE69900#190% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, nếu đòn tấn công này "không hiệu quả", sẽ tạo một lá chắn cho bản thân với giá trị bằng 150% Công Vật Lý, kéo dài 2 lượt; nếu đòn tấn công này "hiệu quả cao", sẽ tăng 20% tỷ lệ chí mạng cho bản thân, kéo dài 2 lượt.',
		describe_en = 'Lucario focuses its power to summon true energy from its hands, then throws it forcefully at a single enemy target, dealing Physical Damage equal to 190% of Physical Attack + $(skillLevel*4*48)$ Physical Damage. If this attack is  "not effective", it creates a shield for itself equal to 150% of Physical Attack, lasting 2 turns; if this attack is \"super effective\", it increases its critical hit rate by 20%, lasting 2 turns.',
		describe_th = 'ลูคาริโอรวบรวมพลังเพื่อเรียกพลังแท้จริงจากมือ จากนั้นขว้างใส่เป้าหมายศัตรูเดี่ยวอย่างแรง สร้างความเสียหายทางกายภาพเท่ากับ 190% ของพลังโจมตีทางกายภาพ + $(skillLevel*4*48)$ ความเสียหายทางกายภาพ หากการโจมตีนี้ "ไม่ค่อยมีประสิทธิภาพ" จะสร้างโล่ให้กับตนเอง มีค่าความทนทานเท่ากับ 150% ของพลังโจมตีทางกายภาพ คงอยู่ 2 เทิร์น; หากการโจมตีนี้ "มีประสิทธิภาพสูง" จะเพิ่มอัตราคริติคอลของตนเอง 20% คงอยู่ 2 เทิร์น',
		describe_in = 'Lucario memfokuskan kekuatannya untuk memanggil energi sejati dari tangannya, kemudian melemparkannya dengan kuat ke satu target musuh, menyebabkan Kerusakan Fisik sebesar 190% Serangan Fisik + $(skillLevel*4*48)$ Kerusakan Fisik. Jika serangan ini "tidak efektif", akan membuat perisai untuk dirinya sendiri dengan nilai sebesar 150% Serangan Fisik, bertahan selama 2 giliran; jika serangan ini "sangat efektif", akan meningkatkan peluang kritis dirinya sebesar 20%, bertahan selama 2 giliran.',
		describe_ph = 'Nakatuon si Lucario ng lakas upang tawagin ang tunay na enerhiya mula sa kanyang mga kamay, pagkatapos ay itapon ito nang malakas sa iisang target na kalaban, na nagdudulot ng Physical Damage na katumbas ng 190% ng Physical Attack + $(skillLevel*4*48)$ Physical Damage. Kung ang pag-atakeng ito ay "hindi epektibo", gagawa ito ng isang kalasag para sa sarili na may halagang 150% ng Physical Attack, tumatagal ng 2 na turn; kung ang pag-atake ay "sobrang epektibo", tataasan nito ang kritikal na porsyento ng sarili ng 20%, tumatagal ng 2 na turn.',
		describe_ma = 'Lucario menumpukan kekuatan untuk memanggil tenaga sebenar dari tangannya, kemudian melemparkannya dengan kuat ke sasaran musuh tunggal, menyebabkan Kerosakan Fizikal sebanyak 190% Serangan Fizikal + $(skillLevel*4*48)$ Kerosakan Fizikal. Jika serangan ini "tidak berkesan", ia akan membentuk perisai untuk dirinya sendiri dengan nilai sebanyak 150% Serangan Fizikal, bertahan selama 2 pusingan; jika serangan ini "sangat berkesan", ia akan meningkatkan kadar kritikalnya sebanyak 20%, bertahan selama 2 pusingan.',
		describe = 'Lucario focuses its power to summon true energy from its hands, then throws it forcefully at a single enemy target, dealing Physical Damage equal to 190% of Physical Attack + $(skillLevel*4*48)$ Physical Damage. If this attack is  "not effective", it creates a shield for itself equal to 150% of Physical Attack, lasting 2 turns; if this attack is \"super effective\", it increases its critical hit rate by 20%, lasting 2 turns.',
		simDesc_vn = 'Luka Liêu phát lực từ tay triệu hồi Chân Khí tốc độ ánh sáng, sau đó ném mạnh về phía mục tiêu đơn lẻ của đối phương.',
		simDesc_en = 'Luka Liêu releases energy from his hand to summon True Qi at the speed of light, then forcefully throws it towards a single enemy target.',
		simDesc_th = 'ลูกา เหลียว ปล่อยพลังจากมือเพื่อเรียกชั้นพลังแท้ด้วยความเร็วแสง จากนั้นขว้างไปยังเป้าหมายเดี่ยวของศัตรูอย่างแรงกล้า',
		simDesc_in = 'Luka Liêu melepaskan energi dari tangannya untuk memanggil Chân Khí dengan kecepatan cahaya, kemudian melemparkannya dengan keras ke arah satu target musuh.',
		simDesc_ph = 'Pinakawalan ni Luka Liêu ang lakas mula sa kanyang kamay upang tawagin ang Tunay na Qi sa bilis ng liwanag, pagkatapos ay mabagsik na itinapon ito patungo sa isang solong target ng kalaban.',
		simDesc_ma = 'Luka Liêu mengeluarkan tenaga dari tangannya untuk memanggil Chân Khí pada kelajuan cahaya, kemudian melemparkannya dengan kuat ke arah sasaran musuh tunggal.',
		simDesc = 'Luka Liêu releases energy from his hand to summon True Qi at the speed of light, then forcefully throws it towards a single enemy target.',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
		upLvDesc_in = 'Kerusakan tetap +192',
		upLvDesc_ph = 'Fixed damage +192',
		upLvDesc_ma = 'Kerosakan tetap +192',
		upLvDesc_vn = 'Sát thương cố định +192',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		skillType2 = 1,
		skillNatureType = 17,
		cdRound = 2,
		posChoose = 1,
		targetTypeDesc = 'Single enemy',
		targetTypeDesc_vn = 'Đơn thể địch',
		targetTypeDesc_en = 'Single enemy',
		targetTypeDesc_th = 'ศัตรูเดี่ยว',
		targetTypeDesc_in = 'Musuh tunggal',
		targetTypeDesc_ph = 'Kalabang iisa',
		targetTypeDesc_ma = 'Musuh tunggal',
		targetChooseType = 'single',
		damageFormula = 'self:damage()*2+(self:flag(99) and skillLevel or skillLevel*4)*48',
		skillCalDamageProcessId = 22421,
		skillProcess = {10224221, 10224222, 10224223},
