	[1022423] = {
		id = 1022423,
		skillName_vn = 'Đạn chân khí',
		skillName_en = 'Compressed air bullet',
		skillName_th = 'กระสุนอัดลม',
		skillName_in = 'Peluru udara tekan',
		skillName_ph = 'Piniga ng hangin',
		skillName_ma = 'Peluru udara mampat',
		skillName = 'Compressed air bullet',
		describe_vn = 'Lucario nhảy lên, sau đó vào trạng thái phát công, bắn ra quả cầu khí chân thật tấn công mục tiêu đơn địch, gây sát thương phép #C0x3D8A99#480% Công Phép#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#sát thương phép#C0x5B545B#, đòn tấn công này chắc chắn trúng; nếu mục tiêu còn sống, sức mạnh sóng dẫn còn lại sẽ gây thêm sát thương bằng 30% sát thương của kỹ năng này trước khi mục tiêu có thể tấn công.',
		describe_en = 'Lucario jumps up, then enters an attack state, firing a real aura sphere to strike a single enemy target, dealing magic damage of #C0x3D8A99#480% Magic Power#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B#. This attack is guaranteed to hit; if the target survives, the remaining wave power will deal additional damage equal to 30% of this skill\'s damage before the target can counterattack.',
		describe_th = 'ลูคาริโอ้กระโดดขึ้น จากนั้นเข้าสู่สถานะโจมตี ยิงลูกบอลออร่าสมจริงโจมตียูนิตศัตรูเดี่ยว สร้างความเสียหายเวท #C0x3D8A99#480% พลังเวท#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#ความเสียหายเวท#C0x5B545B# การโจมตีนี้โจมตีโดนแน่นอน; หากเป้าหมายยังมีชีวิตอยู่ พลังคลื่นที่เหลือจะสร้างความเสียหายเพิ่มเติมเท่ากับ 30% ของความเสียหายสกิลนี้ก่อนที่เป้าหมายจะโจมตีตอบ',
		describe_in = 'Lucario melompat, lalu memasuki keadaan serangan, menembakkan bola aura nyata untuk menyerang satu target musuh, memberikan kerusakan sihir sebesar #C0x3D8A99#480% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# kerusakan sihir#C0x5B545B#. Serangan ini pasti mengenai; jika target masih hidup, kekuatan gelombang yang tersisa akan memberikan tambahan kerusakan sebesar 30% dari kerusakan skill ini sebelum target dapat menyerang balik.',
		describe_ph = 'Tumalon si Lucario pataas, pagkatapos ay pumasok sa estado ng pag-atake, nagpapalabas ng totoong aura sphere upang atakihin ang isang kalabang target, na nagdudulot ng magic damage na #C0x3D8A99#480% Magic Power#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B#. Tiyak na tatama ang atakeng ito; kung buhay pa ang target, ang natitirang kapangyarihan ng wave ay magdudulot ng karagdagang pinsala na katumbas ng 30% ng pinsala ng kasanayang ito bago makapag-atake ang target.',
		describe_ma = 'Lucario melompat, kemudian memasuki keadaan serangan, menembak bola aura sebenar untuk menyerang sasaran musuh tunggal, memberikan kerosakan sihir sebanyak #C0x3D8A99#480% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# kerosakan sihir#C0x5B545B#. Serangan ini pasti mengenai; jika sasaran masih hidup, kekuatan gelombang yang tinggal akan menyebabkan kerosakan tambahan sebanyak 30% daripada kerosakan kemahiran ini sebelum sasaran dapat menyerang balas.',
		describe = 'Lucario jumps up, then enters an attack state, firing a real aura sphere to strike a single enemy target, dealing magic damage of #C0x3D8A99#480% Magic Power#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# magic damage#C0x5B545B#. This attack is guaranteed to hit; if the target survives, the remaining wave power will deal additional damage equal to 30% of this skill\'s damage before the target can counterattack.',
		simDesc_vn = 'Luka Liêu nhảy lên, ngay sau đó phát ra Chân Khí Đạn tấn công mục tiêu đơn lẻ của đối phương. Đòn tấn công này sẽ trúng chắc chắn, nếu mục tiêu còn sống, dư lực từ Bước Sóng sẽ gây thêm sát thương trước khi bản thân hành động.',
		simDesc_en = 'Luka Liêu jumps up, then immediately releases a Vital Energy Bullet targeting a single enemy. This attack is guaranteed to hit; if the target survives, the residual force from Wave Step will deal additional damage before Luka acts again.',
		simDesc_th = 'ลูคา เหลียว กระโดดขึ้น จากนั้นทันทีปล่อย กระสุนพลังชี่โจมตีเป้าหมายเดี่ยวของศัตรู การโจมตีนี้จะโดนแน่นอน หากเป้าหมายยังมีชีวิตอยู่ พลังตกค้างจากก้าวลูกคลื่นจะสร้างความเสียหายเพิ่มเติมก่อนที่ลูคาจะลงมืออีกครั้ง',
		simDesc_in = 'Luka Liêu melompat, kemudian segera melepaskan Peluru Energi Vital yang menyerang satu target musuh. Serangan ini pasti mengenai; jika target masih hidup, sisa kekuatan dari Langkah Gelombang akan menyebabkan kerusakan tambahan sebelum Luka bertindak lagi.',
		simDesc_ph = 'Tumalon si Luka Liêu, pagkatapos ay agad na nagpakawala ng Vital Energy Bullet upang atakihin ang isang tiyak na target ng kalaban. Ang atakeng ito ay tiyak na tatama; kung buhay pa ang target, ang natitirang lakas mula sa Wave Step ay magdudulot pa ng karagdagang pinsala bago muling kumilos si Luka.',
		simDesc_ma = 'Luka Liêu melompat, kemudian segera melepaskan Peluru Tenaga Vital yang menyerang satu sasaran musuh. Serangan ini pasti tepat; jika sasaran masih hidup, sisa tenaga dari Langkah Gelombang akan menyebabkan kerosakan tambahan sebelum Luka bertindak semula.',
		simDesc = 'Luka Liêu jumps up, then immediately releases a Vital Energy Bullet targeting a single enemy. This attack is guaranteed to hit; if the target survives, the residual force from Wave Step will deal additional damage before Luka acts again.',
		starEffect = __data_t__starEffect[1022423],
