	[1024833] = {
		id = 1024833,
		skillName_vn = 'Vòng lửa xoay',
		skillName_en = 'Spinning Fire Ring',
		skillName_th = 'วงไฟหมุน',
		skillName_in = 'Cincin Api Berputar',
		skillName_ph = 'Paikot na Apoy na Singsing',
		skillName_ma = 'Cincin Api Berputar',
		skillName = 'Spinning Fire Ring',
		describe_vn = 'Hóa thân thành một quả cầu lửa xoay lên không trung, sau đó tấn công mục tiêu hàng dọc của kẻ địch, gây Sát Thương Vật Lý #C0xE69900#220% Công Vật Lý#C0x5B545B#+$( skillLevel *36)$ với #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, lượng máu mất đi sẽ chuyển hóa thành sức mạnh, mỗi 1% tỷ lệ máu giảm sẽ tăng thêm 1% sát thương kỹ năng này (tối đa tăng thêm 50%).',
		describe_en = 'Transform into a spinning fireball ascending into the sky, then attack the enemy\'s vertical target line, dealing Physical Damage #C0xE69900#220% Physical Attack#C0x5B545B#+$( skillLevel *36)$ with #C0xF13B54#Physical Damage#C0x5B545B#. The HP lost will be converted into power; every 1% reduction in HP increases this skill\'s damage by 1% (up to a maximum increase of 50%).',
		describe_th = 'กลายร่างเป็นลูกไฟหมุนขึ้นไปในอากาศ จากนั้นโจมตีเป้าหมายแนวตั้งของศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#220% พลังโจมตีทางกายภาพ#C0x5B545B#+$( skillLevel *36)$ พร้อมกับ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# พลังชีวิตที่สูญเสียไปจะถูกแปลงเป็นพลัง ทุก ๆ 1% ของการลดพลังชีวิต จะเพิ่มความเสียหายของสกิลนี้ขึ้น 1% (สูงสุดเพิ่มได้ 50%)',
		describe_in = 'Bermutasi menjadi bola api berputar yang naik ke udara, kemudian menyerang target vertikal musuh, memberikan Damage Fisik #C0xE69900#220% Serangan Fisik#C0x5B545B#+$( skillLevel *36)$ dengan #C0xF13B54#Damage Fisik#C0x5B545B#. HP yang hilang akan diubah menjadi kekuatan; setiap 1% pengurangan HP akan menambah 1% damage skill ini (maksimal tambahan 50%).',
		describe_ph = 'Mag-transform sa umiikot na bola ng apoy na umaakyat sa himpapawid, pagkatapos ay atakihin ang patayong target na hanay ng kalaban, na nagdudulot ng Physical Damage #C0xE69900#220% Physical Attack#C0x5B545B#+$( skillLevel *36)$ gamit ang #C0xF13B54#Physical Damage#C0x5B545B#. Ang nawalang HP ay gagawing lakas; bawat 1% pagbaba ng HP ay magdaragdag ng 1% sa damage ng skill na ito (hanggang maximum na 50% dagdag).',
		describe_ma = 'Bergabung menjadi bola api berpusing yang menaik ke udara, kemudian menyerang sasaran baris menegak musuh, menyebabkan Kerosakan Fizikal #C0xE69900#220% Serangan Fizikal#C0x5B545B#+$( skillLevel *36)$ dengan #C0xF13B54#Kerosakan Fizikal#C0x5B545B#. Jumlah darah yang hilang akan diubah menjadi kekuatan; setiap 1% pengurangan darah akan menambah 1% kerosakan kemahiran ini (maksimum peningkatan 50%).',
		describe = 'Transform into a spinning fireball ascending into the sky, then attack the enemy\'s vertical target line, dealing Physical Damage #C0xE69900#220% Physical Attack#C0x5B545B#+$( skillLevel *36)$ with #C0xF13B54#Physical Damage#C0x5B545B#. The HP lost will be converted into power; every 1% reduction in HP increases this skill\'s damage by 1% (up to a maximum increase of 50%).',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		skillType2 = 2,
		skillDamageType = 1,
		skillNatureType = 2,
		posChoose = 4,
		targetTypeDesc = 'Enemy vertical row',
		targetTypeDesc_vn = 'Hàng dọc địch',
		targetTypeDesc_en = 'Enemy vertical row',
		targetTypeDesc_th = 'แถวตั้งของศัตรู',
		targetTypeDesc_in = 'Baris vertikal musuh',
