	[2600804] = {
		id = 2600804,
		skillName_vn = 'Steel Snake 22-5',
		skillName_en = 'Steel Snake 22-5',
		skillName_th = 'เหล็กงู 22-5',
		skillName_in = 'Ular Baja 22-5',
		skillName_ph = 'Bakal na Asero 22-5',
		skillName_ma = 'Ular Besi 22-5',
		skillName = 'Steel Snake 22-5',
		describe_vn = 'Khi bị tấn công, sẽ phản kích kẻ tấn công, gây sát thương bằng $120+skillLevel*0.3-0.3$% sát thương đòn đánh thường, và tăng 60% phòng thủ vật lý của bản thân, kéo dài 2 lượt (tối đa cộng dồn 3 tầng)',
		describe_en = 'When attacked, counterattacks the attacker, dealing damage equal to $120 + skillLevel × 0.3 - 0.3$% of normal attack damage, and increases own physical defense by 60% for 2 turns (can stack up to 3 layers)',
		describe_th = 'เมื่อถูกโจมตี จะโต้กลับผู้โจมตี สร้างความเสียหายเท่ากับ $120 + skillLevel × 0.3 - 0.3$% ของความเสียหายการโจมตีปกติ และเพิ่มพลังป้องกันทางกายภาพของตนเอง 60% เป็นเวลา 2 เทิร์น (สามารถสะสมได้สูงสุด 3 ชั้น)',
		describe_in = 'Saat diserang, akan membalas serangan kepada penyerang, memberikan damage sebesar $120 + skillLevel × 0.3 - 0.3$% dari damage serangan normal, dan meningkatkan pertahanan fisik sendiri sebesar 60% selama 2 giliran (dapat ditumpuk hingga 3 lapis)',
		describe_ph = 'Kapag inatake, awtomatikong gumaganti sa kalaban, nagdudulot ng $120 + skillLevel × 0.3 - 0.3$% na pinsala base sa normal na atake, at tumataas ng 60% ang sariling physical defense sa loob ng 2 turn (pwedeng maipon hanggang 3 na layer)',
		describe_ma = 'Apabila diserang, akan membalas serangan terhadap penyerang, menyebabkan kerosakan bersamaan $120 + skillLevel × 0.3 - 0.3$% daripada serangan biasa, dan meningkatkan pertahanan fizikal sendiri sebanyak 60% selama 2 pusingan (boleh ditindan sehingga 3 lapisan maksimum)',
		describe = 'When attacked, counterattacks the attacker, dealing damage equal to $120 + skillLevel × 0.3 - 0.3$% of normal attack damage, and increases own physical defense by 60% for 2 turns (can stack up to 3 layers)',
		starEffect = __data_t__starEffect[2600804],
		-- {8}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: anh hùng có lượng máu thấp nhất của chúng ta (không tính bản thân), khi nhận sát thương, Đại Xà sẽ sử dụng chiêu thức để phản công trả thù',
		starEffectDesc = 'Additional effect: our hero with the lowest health (excluding himself), when taking damage, Đại Xà will use a skill to counterattack and retaliate',
		starEffectDesc_en = 'Additional effect: our hero with the lowest health (excluding himself), when taking damage, Đại Xà will use a skill to counterattack and retaliate',
		starEffectDesc_th = 'เอฟเฟกต์เพิ่มเติม: ฮีโร่ของเราที่มีพลังชีวิตต่ำที่สุด (ไม่รวมตัวเขาเอง) เมื่อได้รับความเสียหาย ด่ายซา จะใช้สกิลเพื่อตอบโต้และแก้แค้น',
		starEffectDesc_in = 'Efek tambahan: pahlawan kami dengan kesehatan terendah (tidak termasuk dirinya sendiri), saat menerima kerusakan, Đại Xà akan menggunakan keterampilan untuk membalas serangan dan membalas dendam',
		starEffectDesc_ph = 'Karagdagang epekto: ang aming bayani na may pinakamababang buhay (hindi kasama ang sarili), kapag nakakatanggap ng pinsala, gagamitin ni Đại Xà ang isang kasanayan upang kontrahin at maghiganti',
		starEffectDesc_ma = 'Kesan tambahan: wira kami dengan kesihatan terendah (tidak termasuk dirinya sendiri), apabila menerima kerosakan, Đại Xà akan menggunakan kemahiran untuk menyerang balas dan membalas dendam',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {26008041, 40262}
	},
