	[3013413] = {
		id = 3013413,
		skillName_vn = 'Red Gyarados',
		skillName_en = 'Red Gyarados',
		skillName_th = 'เรดเกียราดอส',
		skillName_in = 'Red Gyarados',
		skillName_ph = 'Red Gyarados',
		skillName_ma = 'Red Gyarados',
		skillName = 'Red Gyarados',
		describe_vn = 'Bạo Lệ Long nhảy lên không trung rồi phun pháo nước tấn công mục tiêu hàng ngang của kẻ địch, gây #C0xE69900#300% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, xóa bỏ toàn bộ hiệu ứng tăng cường của mục tiêu, tăng 80% sát thương chí mạng cho lần tấn công này, nếu kích hoạt chí mạng, sau khi tấn công bản thân có khả năng rơi vào trạng thái hỗn loạn 1-2 lượt (tỷ lệ hỗn loạn càng cao khi tỷ lệ chí mạng hiện tại của bản thân càng cao và số lần sử dụng kỹ năng tuyệt chiêu càng nhiều); nếu không kích hoạt chí mạng, sát thương chí mạng của kỹ năng tuyệt chiêu lần sau sẽ tăng gấp đôi',
		describe_en = 'Violence Dragon leaps into the air and sprays a water cannon to attack the enemy\'s horizontal target line, dealing #C0xE69900#300% Physical Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, removing all buffs from the target, increasing critical damage by 80% for this attack. If a critical hit is triggered, the user may fall into a confused state for 1-2 turns (the chance of confusion increases with the user\'s current critical rate and the number of ultimate skill uses). If the critical hit is not triggered, the critical damage of the ultimate skill will double next time.',
		describe_th = 'มังกรดุร้ายกระโดดขึ้นสู่อากาศแล้วพ่นน้ำโจมตีเป้าหมายในแนวนอนของศัตรู สร้างความเสียหาย #C0xE69900#300% พลังโจมตีทางกายภาพ#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# ลบล้างผลบัพทั้งหมดของเป้าหมาย เพิ่มความเสียหายวิกฤต 80% สำหรับการโจมตีนี้ หากเกิดวิกฤตหลังโจมตี ตัวละครอาจติดสถานะสับสน 1-2 เทิร์น (โอกาสสับสนสูงขึ้นตามอัตราคริติคอลปัจจุบันและจำนวนครั้งที่ใช้สกิลอัลติเมท) หากไม่เกิดวิกฤต ความเสียหายวิกฤตของสกิลอัลติเมทครั้งถัดไปจะเพิ่มเป็นสองเท่า',
		describe_in = 'Naga Kekerasan melompat ke udara lalu menyemburkan meriam air menyerang target baris horizontal musuh, menyebabkan #C0xE69900#300% Serangan Fisik#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, menghapus semua efek buff target, meningkatkan kerusakan kritis sebesar 80% untuk serangan ini. Jika serangan kritis aktif, pengguna mungkin mengalami kebingungan selama 1-2 giliran (peluang kebingungan meningkat sesuai dengan tingkat kritis pengguna saat ini dan jumlah penggunaan skill ultimate). Jika serangan kritis tidak aktif, kerusakan kritis skill ultimate berikutnya akan menjadi dua kali lipat.',
		describe_ph = 'Tumalon ang Marahas na Dragon sa ere at bumuga ng water cannon upang atakihin ang pahalang na hanay ng mga kalaban, na nagdudulot ng #C0xE69900#300% Physical Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, tinatanggal ang lahat ng mga buff sa target, nagpapataas ng kritikal na pinsala ng 80% para sa pag-atakeng ito. Kung mag-trigger ng critical hit, maaaring malagay ang sarili sa confused state sa loob ng 1-2 na turn (tumataas ang tsansa ng confusion base sa kasalukuyang critical rate at dami ng paggamit ng ultimate skill). Kung hindi mag-trigger ng critical hit, magiging doble ang critical damage ng susunod na ultimate skill.',
		describe_ma = 'Naga Kekerasan melompat ke udara dan menyembur meriam air menyerang sasaran baris mendatar musuh, menyebabkan #C0xE69900#300% Serangan Fizikal#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, membuang semua kesan buff pada sasaran, meningkatkan kerosakan kritikal sebanyak 80% untuk serangan ini. Jika kritikal diaktifkan, pengguna mungkin jatuh ke keadaan keliru selama 1-2 giliran (kadar kekeliruan meningkat mengikut kadar kritikal semasa pengguna dan bilangan kali menggunakan kemahiran utama). Jika kritikal tidak diaktifkan, kerosakan kritikal kemahiran utama akan berganda pada kali berikutnya.',
		describe = 'Violence Dragon leaps into the air and sprays a water cannon to attack the enemy\'s horizontal target line, dealing #C0xE69900#300% Physical Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Physical Damage#C0x5B545B#, removing all buffs from the target, increasing critical damage by 80% for this attack. If a critical hit is triggered, the user may fall into a confused state for 1-2 turns (the chance of confusion increases with the user\'s current critical rate and the number of ultimate skill uses). If the critical hit is not triggered, the critical damage of the ultimate skill will double next time.',
		simDesc_vn = 'Gyarados nhảy lên không trung rồi phun ra nước tấn công mục tiêu hàng ngang của đối phương, tăng mạnh sát thương chí mạng, giải tán hiệu ứng buff của mục tiêu, có khả năng gây hỗn loạn cho bản thân sau khi tấn công.',
		simDesc_en = 'Gyarados leaps into the air and sprays water to attack the enemy\'s entire horizontal row, greatly increasing critical damage, dispelling the target\'s buff effects, and has a chance to cause confusion to itself after the attack.',
		simDesc_th = 'กิยาราดอสกระโดดขึ้นกลางอากาศแล้วพ่นน้ำโจมตีเป้าหมายแถวแนวนอนของฝ่ายตรงข้าม เพิ่มความเสียหายคริติคอลอย่างมาก ล้างเอฟเฟกต์บัฟของเป้าหมาย และมีโอกาสทำให้ตัวเองสับสนหลังการโจมตี',
		simDesc_in = 'Gyarados melompat ke udara lalu menyemprotkan air untuk menyerang baris horizontal musuh, meningkatkan kerusakan kritis secara signifikan, menghilangkan efek buff target, dan memiliki kemungkinan menyebabkan kebingungan pada dirinya sendiri setelah menyerang.',
		simDesc_ph = 'Tumatalon ang Gyarados sa hangin at bumubuga ng tubig upang atakihin ang pahalang na hilera ng kalaban, malaki ang pagtaas ng critical damage, tinatanggal ang mga buff effect ng target, at may posibilidad na malito ang sarili pagkatapos ng pag-atake.',
		simDesc_ma = 'Gyarados melompat ke udara lalu memancut air untuk menyerang barisan mendatar musuh, meningkatkan kerosakan kritikal dengan ketara, menghapuskan kesan buff sasaran, dan berkemungkinan menyebabkan kekeliruan pada dirinya sendiri selepas menyerang.',
		simDesc = 'Gyarados leaps into the air and sprays water to attack the enemy\'s entire horizontal row, greatly increasing critical damage, dispelling the target\'s buff effects, and has a chance to cause confusion to itself after the attack.',
		starEffect = __data_t__starEffect[3013413],
