	[3024313] = {
		id = 3024313,
		skillName_vn = 'Phoenix Soaring in the Sky',
		skillName_en = 'Phoenix Soaring in the Sky',
		skillName_th = 'ฟีนิกซ์ทะยานสู่ท้องฟ้า',
		skillName_in = 'Phoenix Terbang Tinggi di Langit',
		skillName_ph = 'Phoenix Lumilipad sa Kalangitan',
		skillName_ma = 'Phoenix Terbang Tinggi di Langit',
		skillName = 'Phoenix Soaring in the Sky',
		describe_vn = 'Ho-Oh bay lượn trên trời, phun ra tia sáng nóng rực như ánh mặt trời tấn công toàn bộ mục tiêu địch, gây ra #C0xE69900#180% Công Vật Lý#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, thêm một tầng [Thiêu đốt Thánh Hỏa] lên tất cả mục tiêu địch trong 2 lượt; ban phước [Phúc lành Thần Điểu] cho một đồng đội (ưu tiên hàng trước) ngoại trừ bản thân (Phúc lành Thần Điểu: hiệu ứng đặc biệt, khi tử trận, sẽ biến thành trứng phượng hoàng, trứng phượng hoàng bị tấn công 6 lần sẽ bị phá hủy, nếu không bị phá hủy, sẽ hồi sinh vào cuối lượt tiếp theo, sau khi hồi sinh giữ lại 30% máu và nộ khí) [Phúc lành Thần Điểu] chỉ kích hoạt một lần trong toàn trận',
		describe_en = 'Ho-Oh soars in the sky, spewing scorching rays like sunlight to attack all enemy targets, dealing #C0xE69900#180% Physical Attack#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage#C0x5B545B#, applying one stack of [Scorching Sacred Flame] on all enemy targets for 2 turns; blessing one ally (front row priority) except itself with [Divine Bird\'s Blessing] (Divine Bird\'s Blessing: special effect, upon death, transforms into a phoenix egg, the phoenix egg can endure 6 attacks before being destroyed; if not destroyed, it will resurrect at the end of the next turn with 30% HP and rage retained). [Divine Bird\'s Blessing] can only trigger once per battle.',
		describe_th = 'โฮ-โอว์บินวนอยู่บนท้องฟ้า พ่นแสงร้อนแรงเหมือนแสงแดดโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหาย #C0xE69900#180% การโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# พร้อมเพิ่มหนึ่งชั้น [เปลวไฟศักดิ์สิทธิ์แผดเผา] ให้กับเป้าหมายศัตรูทั้งหมดเป็นเวลา 2 เทิร์น; มอบพร [พรนกเทพ] ให้กับพันธมิตรหนึ่งคน (จัดลำดับแถวหน้าก่อน) ยกเว้นตัวเอง (พรนกเทพ: ผลพิเศษ เมื่อถูกฆ่าจะกลายเป็นไข่มังกรฟีนิกซ์ ไข่จะทนการโจมตีได้ 6 ครั้งก่อนถูกทำลาย หากไม่ถูกทำลายจะฟื้นคืนชีพในตอนท้ายเทิร์นถัดไป โดยมี HP และพลังแค้นเหลือ 30%) [พรนกเทพ] จะทำงานได้เพียงครั้งเดียวต่อการต่อสู้',
		describe_in = 'Ho-Oh terbang melayang di langit, memuntahkan sinar panas seperti sinar matahari yang menyerang semua target musuh, menyebabkan #C0xE69900#180% Serangan Fisik#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, menambahkan satu lapis [Api Suci Membakar] ke semua target musuh selama 2 giliran; memberkati satu rekan (prioritas barisan depan) kecuali dirinya sendiri dengan [Berkat Burung Dewa] (Berkat Burung Dewa: efek khusus, saat tewas, berubah menjadi telur burung phoenix, telur phoenix dapat menerima 6 serangan sebelum hancur; jika tidak hancur, akan bangkit kembali pada akhir giliran berikutnya dengan 30% HP dan kemarahan yang tersisa). [Berkat Burung Dewa] hanya dapat diaktifkan sekali selama pertarungan.',
		describe_ph = 'Lumilipad si Ho-Oh sa himpapawid, umuwing ng naglalagablab na sinag na parang araw para atakihin ang lahat ng kalaban, nagdudulot ng #C0xE69900#180% Physical Attack#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage#C0x5B545B#, dinadagdagan ng isang layer ng [Sagradong Nasusunog na Apoy] sa lahat ng kalabang target sa loob ng 2 turn; pinagpapala ang isang kakampi (priyoridad sa frontline) maliban sa sarili nito ng [Bendisyon ng Banal na Ibon] (Bendisyon ng Banal na Ibon: espesyal na epekto, kapag namatay, nagiging itlog ng phoenix, ang itlog ng phoenix ay kayang tiisin ang 6 na atake bago masira; kung hindi masira, babangon muli sa katapusan ng susunod na turn na may 30% HP at galit na naiiwan). Ang [Bendisyon ng Banal na Ibon] ay maaaring mag-trigger lamang ng isang beses sa buong laban.',
		describe_ma = 'Ho-Oh terbang melayang di angkasa, memancarkan sinaran panas seperti cahaya matahari yang menyerang semua sasaran musuh, menyebabkan #C0xE69900#180% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, menambah satu lapisan [Api Suci Pembakar] ke semua sasaran musuh selama 2 pusingan; memberkati satu sekutu (keutamaan barisan hadapan) kecuali dirinya sendiri dengan [Berkat Burung Dewa] (Berkat Burung Dewa: kesan khas, apabila mati, akan berubah menjadi telur phoenix, telur phoenix boleh menahan 6 serangan sebelum musnah; jika tidak musnah, akan dibangkitkan semula pada akhir pusingan berikutnya dengan 30% HP dan kemarahan yang dikekalkan). [Berkat Burung Dewa] hanya boleh diaktifkan sekali dalam setiap pertempuran.',
		describe = 'Ho-Oh soars in the sky, spewing scorching rays like sunlight to attack all enemy targets, dealing #C0xE69900#180% Physical Attack#C0x5B545B#+$(skillLevel*4*60)$ #C0xF13B54# Physical Damage#C0x5B545B#, applying one stack of [Scorching Sacred Flame] on all enemy targets for 2 turns; blessing one ally (front row priority) except itself with [Divine Bird\'s Blessing] (Divine Bird\'s Blessing: special effect, upon death, transforms into a phoenix egg, the phoenix egg can endure 6 attacks before being destroyed; if not destroyed, it will resurrect at the end of the next turn with 30% HP and rage retained). [Divine Bird\'s Blessing] can only trigger once per battle.',
		simDesc_vn = 'Phượng Hoàng bay lượn trên trời, phun ra những tia sáng nóng bỏng như ánh mặt trời từ miệng, tấn công toàn bộ mục tiêu kẻ thù, và thêm một lớp lửa thánh, ban cho một đồng đội khác ngoài bản thân hiệu ứng phước lành của thần điểu.',
		simDesc_en = 'The Phoenix soars in the sky, unleashing scorching rays like sunlight from its mouth, attacking all enemy targets, and adding a layer of holy flames, granting another ally besides itself the blessing effect of the divine bird.',
		simDesc_th = 'นกฟีนิกซ์บินวนในท้องฟ้า พ่นแสงเปลวไฟร้อนแรงเหมือนแสงอาทิตย์จากปาก โจมตีเป้าหมายศัตรูทั้งหมด และเพิ่มชั้นไฟศักดิ์สิทธิ์ มอบผลแห่งพรจากนกศักดิ์สิทธิ์ให้กับพันธมิตรอีกคนหนึ่งนอกจากตัวมันเอง',
		simDesc_in = 'Phoenix terbang melayang di langit, memuntahkan sinar panas seperti sinar matahari dari mulutnya, menyerang semua target musuh, dan menambahkan lapisan api suci, memberikan efek berkat dari burung ilahi kepada satu rekan selain dirinya sendiri.',
		simDesc_ph = 'Ang Phoenix ay lumilipad sa himpapawid, nagpapalabas ng mainit na mga sinag tulad ng sikat ng araw mula sa bibig, inaatake ang lahat ng mga kaaway, at nagdadagdag ng isang patong ng banal na apoy, na nagbibigay ng pagpapala mula sa banal na ibon sa isa pang kasamahan bukod sa sarili nito.',
		simDesc_ma = 'Phoenix terbang melayang di langit, memancarkan sinaran panas seperti cahaya matahari dari mulutnya, menyerang semua sasaran musuh, dan menambah lapisan api suci, memberi rakan satu lagi selain dirinya sendiri kesan berkat burung suci.',
		simDesc = 'The Phoenix soars in the sky, unleashing scorching rays like sunlight from its mouth, attacking all enemy targets, and adding a layer of holy flames, granting another ally besides itself the blessing effect of the divine bird.',
		starEffect = __data_t__starEffect[3024313],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: <Phúc lành của thần điểu> mục tiêu được hồi sinh giữ lại 80% máu và toàn bộ năng lượng',
		starEffectDesc = 'Enhance Effect: <Blessing of the Divine Bird> The revived target retains 80% HP and full energy',
		starEffectDesc_en = 'Enhance Effect: <Blessing of the Divine Bird> The revived target retains 80% HP and full energy',
		starEffectDesc_th = 'เพิ่มประสิทธิภาพเอฟเฟกต์: <พรแห่งนกเทพ> เป้าหมายที่ถูกชุบชีวิตจะเก็บรักษา HP 80% และพลังงานทั้งหมดไว้',
		starEffectDesc_in = 'Tingkatkan Efek: <Berkah Burung Ilahi> target yang dihidupkan kembali mempertahankan 80% HP dan energi penuh',
		starEffectDesc_ph = 'Pahusayin ang Epekto: <Pagpalang ng Banal na Ibon> ang muling nabuhay na target ay mananatili sa 80% HP at buong enerhiya',
		starEffectDesc_ma = 'Tingkatkan Kesan: <Berkat Burung Ilahi> sasaran yang dihidupkan semula mengekalkan 80% darah dan tenaga penuh',
