	[3072211] = {
		id = 3072211,
		skillName_vn = 'Hát',
		skillName_en = 'Sing',
		skillName_th = 'ร้องเพลง',
		skillName_in = 'Bernyanyi',
		skillName_ph = 'Kanta',
		skillName_ma = 'Menyanyi',
		skillName = 'Sing',
		describe_vn = 'Bé Ding nhẹ nhàng hát, dùng giọng hát tấn công mục tiêu đơn lẻ của địch, gây sát thương #C0x3D8A99#90% Phép Công#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#',
		describe_en = 'Baby Ding softly sings, using her voice to attack a single enemy target, dealing #C0x3D8A99#90% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage #C0x5B545B#',
		describe_th = 'น้องดิงร้องเพลงอย่างนุ่มนวล ใช้เสียงของเธอโจมตีเป้าหมายศัตรูทีละตัว สร้างความเสียหาย #C0x3D8A99#90% พลังเวท#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B#',
		describe_in = 'Bayi Ding bernyanyi lembut, menggunakan suara untuk menyerang satu target musuh, menyebabkan #C0x3D8A99#90% Serangan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Kerusakan Sihir #C0x5B545B#',
		describe_ph = 'Si Baby Ding ay malumanay na kumakanta, gamit ang kanyang tinig upang atakihin ang isang target na kalaban, na nagdudulot ng #C0x3D8A99#90% Magic Attack#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# Magic Damage #C0x5B545B#',
