	[4001003] = {
		id = 4001003,
		describe_vn = 'Mỗi vòng lớn, anh hùng phe ta đầu tiên sử dụng kỹ năng chí mạng sẽ tạm thời tăng 20% sát thương chí mạng',
		describe_en = 'In each major round, the first hero on our side to use a critical skill will temporarily increase critical damage by 20%.',
		describe_th = 'ในแต่ละรอบใหญ่ ฮีโร่คนแรกของฝ่ายเราที่ใช้ทักษะคริติคอลจะเพิ่มความเสียหายคริติคอลขึ้นชั่วคราว 20%.',
		describe_in = 'Pada setiap putaran besar, pahlawan pertama di pihak kita yang menggunakan keterampilan kritis akan sementara meningkatkan kerusakan kritis sebesar 20%.',
		describe_ph = 'Sa bawat malaking round, ang unang bayani sa ating panig na gagamit ng kritikal na kasanayan ay pansamantalang magpapataas ng kritikal na pinsala ng 20%.',
		describe_ma = 'Pada setiap pusingan besar, wira pertama di pihak kami yang menggunakan kemahiran kritikal akan meningkatkan kerosakan kritikal sebanyak 20% buat sementara waktu.',
		describe = 'In each major round, the first hero on our side to use a critical skill will temporarily increase critical damage by 20%.',
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {40010031}
	},
	[4001004] = {
		id = 4001004,
		describe_vn = 'Mỗi vòng lớn kết thúc, gây sát thương thực bằng 30% tổng công đôi của anh hùng có công đôi cao nhất phe ta lên một đơn vị ngẫu nhiên phe địch',
		describe_en = 'At the end of each major round, deal true damage equal to 30% of the highest total double attack of our hero with the highest double attack to a random enemy unit.',
		describe_th = 'เมื่อสิ้นสุดรอบใหญ่แต่ละครั้ง จะสร้างความเสียหายจริงเท่ากับ 30% ของการโจมตีคู่รวมสูงสุดของฮีโร่ฝ่ายเราที่มีการโจมตีคู่สูงสุดไปยังยูนิตศัตรูแบบสุ่มหนึ่งตัว',
		describe_in = 'Pada akhir setiap putaran besar, berikan damage nyata sebesar 30% dari serangan ganda total tertinggi pahlawan kita yang memiliki serangan ganda tertinggi ke satu unit musuh secara acak.',
		describe_ph = 'Sa pagtatapos ng bawat malaking round, magdulot ng totoong pinsala na katumbas ng 30% ng pinakamataas na kabuuang double attack ng ating bayani na may pinakamataas na double attack sa isang random na yunit ng kalaban.',
		describe_ma = 'Pada akhir setiap pusingan besar, berikan kerosakan sebenar sebanyak 30% daripada jumlah serangan berganda tertinggi wira kita yang mempunyai serangan berganda tertinggi kepada satu unit musuh secara rawak.',
		describe = 'At the end of each major round, deal true damage equal to 30% of the highest total double attack of our hero with the highest double attack to a random enemy unit.',
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {40010041}
	},
