	[8005001] = {
		id = 8005001,
		skillName_vn = 'Hỏa Trảm Thiên Trụ',
		skillName_en = 'Flame Cleaver Heavenly Pillar',
		skillName_th = 'พรหมฟ้าอัคคีดาบ',
		skillName_in = 'Flame Cleaver Pilar Surga',
		skillName_ph = 'Flame Cleaver Haligi ng Langit',
		skillName_ma = 'Flame Cleaver Tiang Syurga',
		skillName = 'Hỏa Trảm Thiên Trụ',
		describe_vn = 'Rengoku lao thẳng đến mục tiêu như một cột lửa sống, vung kiếm thiêu đốt rực lửa và chém mạnh vào đối thủ, gây ra #C0x3D8A99#180% Sát Thương Vật Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel424)$#C0x5B545B# Sát Thương Lửa tăng theo cấp kỹ năng. Sau khi xuất chiêu, ngọn lửa bùng cháy thiêu rụi kẻ thù gây #C0xF13B54#+$(skillLevel*200)$#C0x5B545B# sát thương lửa. Sau đó tiếp thêm sức mạnh cho chính anh ta: Tăng 10% sát thương gây ra từ tất cả kỹ năng và đòn đánh thường trong 2 lượt kế tiếp. Hiệu ứng có thể cộng dồn tối đa 2 lần nếu kỹ năng được sử dụng liên tục hoặc kèm các kỹ năng khác có hiệu ứng tương tự. Tăng sát thương áp dụng cho mọi loại sát thương: vật lý, lửa và kỹ năng phụ. Không thể bị xóa bỏ bằng kỹ năng giải buff.',
		describe_en = 'Rengoku charges straight at the target like a living pillar of flame, swinging his sword to burn intensely and strike the enemy, dealing #C0x3D8A99#180% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*24)$#C0x5B545B# Fire Damage scaling with skill level. After the attack, the flames erupt to incinerate foes, causing #C0xF13B54#+$(skillLevel*200)$#C0x5B545B# Fire Damage. He then empowers himself: increases all skill and normal attack damage by 10% for the next 2 turns. The effect can stack up to 2 times if the skill is used consecutively or with other skills of similar effects. Damage increase applies to all damage types: physical, fire, and secondary skills. Cannot be removed by debuff-clearing skills.',
		describe_th = 'Rengoku พุ่งตรงไปยังเป้าหมายเหมือนเสาไฟมีชีวิต ฟันดาบเผาไหม้อย่างรุนแรงและโจมตีศัตรู ทำให้เกิด #C0x3D8A99#180% ความเสียหายทางกายภาพ#C0x5B545B# และ #C0xF13B54#+$(skillLevel*24)$#C0x5B545B# ความเสียหายไฟเพิ่มตามระดับสกิล หลังจากใช้ท่า ไฟลุกโชนเผาศัตรูทำให้เกิด #C0xF13B54#+$(skillLevel*200)$#C0x5B545B# ความเสียหายไฟ จากนั้นเขาเสริมพลังให้ตัวเอง: เพิ่มความเสียหายจากสกิลและการโจมตีปกติทั้งหมด 10% เป็นเวลา 2 ตาถัดไป เอฟเฟกต์สามารถซ้อนกันได้สูงสุด 2 ครั้งหากสกิลถูกใช้ต่อเนื่องหรือร่วมกับสกิลอื่นที่มีผลเหมือนกัน การเพิ่มความเสียหายใช้กับทุกประเภทความเสียหาย: กายภาพ ไฟ และสกิลรอง ไม่สามารถถูกลบด้วยสกิลล้างดีบัฟ',
		describe_in = 'Rengoku meluncur langsung ke target seperti tiang api hidup, mengayunkan pedangnya membakar hebat dan menyerang musuh, memberikan #C0x3D8A99#180% Damage Fisik#C0x5B545B# dan #C0xF13B54#+$(skillLevel*24)$#C0x5B545B# Damage Api yang meningkat sesuai level skill. Setelah serangan, api meledak membakar musuh, menyebabkan #C0xF13B54#+$(skillLevel*200)$#C0x5B545B# Damage Api. Ia kemudian memberdayakan dirinya sendiri: meningkatkan semua damage skill dan serangan normal sebesar 10% selama 2 giliran berikutnya. Efek ini dapat ditumpuk hingga 2 kali jika skill digunakan berturut-turut atau bersama skill lain dengan efek serupa. Peningkatan damage berlaku untuk semua jenis damage: fisik, api, dan skill sekunder. Tidak bisa dihapus oleh skill yang menghilangkan debuff.',
		describe_ph = 'Rengoku ay sumugod direkta sa target tulad ng buhay na haliging apoy, iniwaksi ang kanyang espada upang magliyab at hampasin ang kalaban, na nagdudulot ng #C0x3D8A99#180% Physical Damage#C0x5B545B# at #C0xF13B54#+$(skillLevel*24)$#C0x5B545B# Fire Damage na tumataas ayon sa antas ng skill. Pagkatapos ng atake, sumabog ang apoy at sinunog ang mga kaaway na nagdudulot ng #C0xF13B54#+$(skillLevel*200)$#C0x5B545B# Fire Damage. Pagkatapos, pinapalakas niya ang sarili: pinapataas ang lahat ng skill at normal attack damage ng 10% sa susunod na 2 turn. Maaaring mag-stack ang epekto ng hanggang 2 beses kung ang skill ay ginamit nang sunud-sunod o kasama ang ibang skills na may parehong epekto. Ang pagtaas ng damage ay naaaplay sa lahat ng uri ng damage: physical, fire, at secondary skills. Hindi maaaring tanggalin gamit ang debuff-clearing skills.',
		describe_ma = 'Rengoku meluru terus ke sasaran seperti tiang api hidup, menghayun pedangnya membakar dan menyerang musuh, memberikan #C0x3D8A99#180% Kerosakan Fizikal#C0x5B545B# dan #C0xF13B54#+$(skillLevel*24)$#C0x5B545B# Kerosakan Api mengikut tahap kemahiran. Selepas serangan, api meletup membakar musuh menyebabkan #C0xF13B54#+$(skillLevel*200)$#C0x5B545B# Kerosakan Api. Kemudian dia memperkuat dirinya sendiri: meningkatkan semua kerosakan kemahiran dan serangan biasa sebanyak 10% untuk 2 giliran berikutnya. Kesan boleh ditumpuk sehingga 2 kali jika kemahiran digunakan berturut-turut atau bersama kemahiran lain dengan kesan serupa. Peningkatan kerosakan terpakai untuk semua jenis kerosakan: fizikal, api, dan kemahiran sekunder. Tidak boleh dihapus dengan kemahiran membersihkan debuff.',
		describe = 'Rengoku charges straight at the target like a living pillar of flame, swinging his sword to burn intensely and strike the enemy, dealing #C0x3D8A99#180% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*24)$#C0x5B545B# Fire Damage scaling with skill level. After the attack, the flames erupt to incinerate foes, causing #C0xF13B54#+$(skillLevel*200)$#C0x5B545B# Fire Damage. He then empowers himself: increases all skill and normal attack damage by 10% for the next 2 turns. The effect can stack up to 2 times if the skill is used consecutively or with other skills of similar effects. Damage increase applies to all damage types: physical, fire, and secondary skills. Cannot be removed by debuff-clearing skills.',
		simDesc_vn = 'Rengoku lao thẳng đến mục tiêu, vung kiếm chém rực lửa vào đối thủ, gây ra #C0x3D8A99#180% Sát Thương Vật Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel*4*24)$#C0x5B545B# Sát Thương Lửa tăng theo cấp kỹ năng. Ngọn lửa bùng cháy quanh Rengoku giúp anh ta tăng 10% sát thương gây ra trong 2 lượt kế tiếp (tối đa 2 cấp)',
		simDesc_en = 'Rengoku charges straight at the target, slashing with a blazing sword strike that deals #C0x3D8A99#180% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*24)$#C0x5B545B# Fire Damage scaling with skill level. The flames burning around Rengoku increase his damage dealt by 10% for the next 2 turns (up to 2 stacks).',
		simDesc_th = 'เรนโกคุพุ่งตรงเข้าใส่เป้าหมาย ฟันด้วยดาบเพลิงอันร้อนแรง สร้างความเสียหาย #C0x3D8A99#180% กายภาพ#C0x5B545B# และ #C0xF13B54#+$(skillLevel*4*24)$#C0x5B545B# ความเสียหายไฟตามเลเวลสกิล เปลวไฟที่ลุกโชนรอบเรนโกคุช่วยเพิ่มความเสียหายที่เขาสร้างขึ้น 10% เป็นเวลา 2 เทิร์นถัดไป (สูงสุด 2 ขั้น)',
		simDesc_in = 'Rengoku menerjang langsung ke target, menebas dengan pedang berapi yang memberikan #C0x3D8A99#180% Damage Fisik#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*24)$#C0x5B545B# Damage Api yang meningkat sesuai level skill. Api yang menyelimuti Rengoku meningkatkan damage yang ia berikan sebesar 10% selama 2 giliran berikutnya (maksimal 2 tumpukan).',
		simDesc_ph = 'Sumugod si Rengoku diretso sa target, humampas gamit ang naglalagablab na espada na nagdudulot ng #C0x3D8A99#180% Pisikal na Pinsala#C0x5B545B# at #C0xF13B54#+$(skillLevel*4*24)$#C0x5B545B# Pinsala ng Apoy na tumataas batay sa antas ng kasanayan. Ang apoy na bumabalot kay Rengoku ay nagpapataas ng 10% sa kanyang damage sa loob ng susunod na 2 turn (hanggang 2 stack).',
		simDesc_ma = 'Rengoku menerjah terus ke arah sasaran, menghayun pedang berapi yang memberikan #C0x3D8A99#180% Kerosakan Fizikal#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*24)$#C0x5B545B# Kerosakan Api yang meningkat mengikut tahap kemahiran. Api yang menyelubungi Rengoku meningkatkan kerosakan yang dihasilkannya sebanyak 10% untuk 2 pusingan seterusnya (maksimum 2 tahap).',
		simDesc = 'Rengoku charges straight at the target, slashing with a blazing sword strike that deals #C0x3D8A99#180% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*24)$#C0x5B545B# Fire Damage scaling with skill level. The flames burning around Rengoku increase his damage dealt by 10% for the next 2 turns (up to 2 stacks).',
		zawakeEffect = __data_t__zawakeEffect[8005001],
		-- {79001}
		zawakeEffectDesc = 'Rengoku charges straight at the target, slashing with his blazing sword, dealing #C0x3D8A99#180% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*24)$ Fire Damage scaling with skill level.',
		zawakeEffectDesc_en = 'Rengoku charges straight at the target, slashing with his blazing sword, dealing #C0x3D8A99#180% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*24)$ Fire Damage scaling with skill level.',
		zawakeEffectDesc_th = 'Rengoku พุ่งเข้าหาเป้าหมาย ฟาดดาบเพลิงใส่ศัตรู สร้างความเสียหาย #C0x3D8A99#180% กายภาพ#C0x5B545B# และ #C0xF13B54#+$(skillLevel*4*24)$ ความเสียหายไฟตามเลเวลสกิล',
		zawakeEffectDesc_in = 'Rengoku menerjang langsung ke target, menebas dengan pedang berapi, memberikan #C0x3D8A99#180% Damage Fisik#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*24)$ Damage Api yang meningkat sesuai level skill.',
		zawakeEffectDesc_ph = 'Rengoku sumugod diretso sa target, humampas gamit ang naglalagablab na espada, nagdudulot ng #C0x3D8A99#180% Physical Damage#C0x5B545B# at #C0xF13B54#+$(skillLevel*4*24)$ Fire Damage na tumataas ayon sa antas ng skill.',
		zawakeEffectDesc_ma = 'Rengoku menyerbu terus ke arah sasaran, menghayun pedang berapi ke musuh, memberikan #C0x3D8A99#180% Damage Fizikal#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*24)$ Damage Api yang meningkat mengikut tahap kemahiran.',
		zawakeEffectDesc_vn = 'Rengoku lao thẳng đến mục tiêu, vung kiếm chém rực lửa vào đối thủ, gây #C0x3D8A99#180% Sát Thương Vật Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel*4*24)$ sát thương lửa tăng theo cấp kỹ năng.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Rush forward and strike powerfully, dealing massive Physical Damage and fire damage scaling with skill level.',
		zawakeSimpleDesc_en = 'Rush forward and strike powerfully, dealing massive Physical Damage and fire damage scaling with skill level.',
		zawakeSimpleDesc_th = 'พุ่งเข้าไปฟันแรง ทำความเสียหายทางกายภาพจำนวนมากและความเสียหายไฟตามระดับทักษะ',
		zawakeSimpleDesc_in = 'Menerjang maju dan menebas dengan keras, memberikan Damage Fisik besar dan damage api sesuai level skill.',
		zawakeSimpleDesc_ph = 'Sumugod at tumama nang malakas, nagdudulot ng malaking Physical Damage at fire damage na tumataas ayon sa antas ng skill.',
		zawakeSimpleDesc_ma = 'Meluru ke hadapan dan menebas dengan kuat, memberikan Damage Fizikal besar dan damage api mengikut tahap skill.',
		zawakeSimpleDesc_vn = 'Lao đến và chém mạnh gây sát thương vật lý lớn và sát thương lửa theo cấp kỹ năng.',
		iconRes = 'battle/skill_icon/skill_80051.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 0,
		skillNatureType = 12,
