		posChoose = 1,
		targetTypeDesc = 'Enemy Special Single Target',
		targetTypeDesc_vn = 'Đơn thể đặc biệt của địch',
		targetTypeDesc_en = 'Enemy Special Single Target',
		targetTypeDesc_th = 'เป้าหมายเดี่ยวพิเศษของศัตรู',
		targetTypeDesc_in = 'Target Tunggal Khusus Musuh',
