	[8005002] = {
		id = 8005002,
		skillName_vn = 'Viêm Hổ Cuồng Liệt',
		skillName_en = 'Fierce Flame Tiger',
		skillName_th = 'เสือไฟดุร้าย',
		skillName_in = 'Harimau Api Garang',
		skillName_ph = 'Galit na Tigre ng Apoy',
		skillName_ma = 'Harimau Api Ganas',
		skillName = 'Viêm Hổ Cuồng Liệt',
		describe_vn = 'Viêm Hổ Cuồng Liệt – Rengoku lao thẳng tới mục tiêu như một cột lửa bùng cháy, gây #C0x3D8A99#280% Sát Thương Vật Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Sát Thương Lửa tăng theo cấp kỹ năng, đồng thời gây <Choáng> mục tiêu trong 2 lượt (hiệu ứng khống chế, không thể hành động). Nếu mục tiêu bị hạ gục trong trạng thái <Choáng>, Rengoku bùng nổ thêm một lần #C0xE69900#200% Tấn Công Lửa#C0x5B545B# vào kẻ địch xung quanh (25% sát thương lan), và để lại hiệu ứng <Tàn Dư Viêm Hổ>, gây sát thương đốt thêm trong 2 lượt tiếp theo. (Hiệu ứng này có thể kích hoạt tối đa 2 lần trong 1 lượt).',
		describe_en = 'Furious Flame Tiger – Rengoku charges straight at the target like a blazing pillar of fire, dealing #C0x3D8A99#280% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Fire Damage scaling with skill level, while stunning the target for 2 turns (<Stun> effect, cannot act). If the target is defeated while <Stunned>, Rengoku triggers an additional #C0xE69900#200% Fire Attack#C0x5B545B# to surrounding enemies (25% damage spreads), leaving a <Residual Furious Flame Tiger> effect, dealing burn damage over the next 2 turns. (This effect can trigger up to 2 times per turn).',
		describe_th = 'เสือเพลิงดุร้าย – Rengoku พุ่งตรงไปยังเป้าหมายเหมือนเสาไฟลุกโชติช่วง ทำให้เกิด #C0x3D8A99#280% ความเสียหายทางกายภาพ#C0x5B545B# และ #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# ความเสียหายไฟตามระดับสกิล พร้อมกับทำให้เป้าหมาย <มึนงง> เป็นเวลา 2 ตา (เอฟเฟกต์ควบคุม, ไม่สามารถกระทำใด ๆ ได้) หากเป้าหมายถูกกำจัดขณะ <มึนงง> Rengoku ระเบิดเพิ่มอีกครั้งด้วย #C0xE69900#200% การโจมตีไฟ#C0x5B545B# ต่อศัตรูรอบข้าง (25% ความเสียหายแพร่), และสร้างเอฟเฟกต์ <เศษเสือเพลิงดุร้าย> ทำความเสียหายเผาไหม้ต่ออีก 2 ตาถัดไป (เอฟเฟกต์นี้สามารถทำงานได้สูงสุด 2 ครั้งต่อรอบ).',
		describe_in = 'Furious Flame Tiger – Rengoku meluncur langsung ke target seperti tiang api yang menyala, memberikan #C0x3D8A99#280% Damage Fisik#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Damage Api yang meningkat sesuai level skill, sekaligus menyebabkan <Stun> pada target selama 2 giliran (efek kontrol, tidak bisa bertindak). Jika target dikalahkan saat <Stunned>, Rengoku meledakkan tambahan #C0xE69900#200% Serangan Api#C0x5B545B# ke musuh di sekitarnya (25% damage menyebar), meninggalkan efek <Residual Furious Flame Tiger>, memberikan damage terbakar selama 2 giliran berikutnya. (Efek ini dapat dipicu hingga 2 kali per giliran).',
		describe_ph = 'Furious Flame Tiger – Rengoku ay sumugod diretso sa target tulad ng naglalagablab na haligi ng apoy, nagdudulot ng #C0x3D8A99#280% Physical Damage#C0x5B545B# at #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Fire Damage na tumataas ayon sa antas ng skill, kasabay ng pag-stun sa target ng 2 turn (<Stun> effect, hindi makakilos). Kung ang target ay natalo habang <Stunned>, Rengoku ay magpapalabas ng karagdagang #C0xE69900#200% Fire Attack#C0x5B545B# sa mga kaaway sa paligid (25% damage ay kumakalat), nag-iiwan ng <Residual Furious Flame Tiger> effect, na nagdudulot ng burn damage sa susunod na 2 turn. (Ang effect na ito ay maaaring mag-trigger ng hanggang 2 beses kada turn).',
		describe_ma = 'Furious Flame Tiger – Rengoku meluru terus ke sasaran seperti tiang api yang menyala, memberikan #C0x3D8A99#280% Kerosakan Fizikal#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Kerosakan Api mengikut tahap kemahiran, serta menyebabkan <Stun> pada sasaran selama 2 giliran (kesan kawalan, tidak boleh bertindak). Jika sasaran dikalahkan semasa <Stunned>, Rengoku meletupkan tambahan #C0xE69900#200% Serangan Api#C0x5B545B# kepada musuh di sekeliling (25% kerosakan tersebar), meninggalkan kesan <Residual Furious Flame Tiger>, memberikan kerosakan terbakar dalam 2 giliran berikutnya. (Kesan ini boleh dicetuskan sehingga 2 kali per giliran).',
		describe = 'Furious Flame Tiger – Rengoku charges straight at the target like a blazing pillar of fire, dealing #C0x3D8A99#280% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Fire Damage scaling with skill level, while stunning the target for 2 turns (<Stun> effect, cannot act). If the target is defeated while <Stunned>, Rengoku triggers an additional #C0xE69900#200% Fire Attack#C0x5B545B# to surrounding enemies (25% damage spreads), leaving a <Residual Furious Flame Tiger> effect, dealing burn damage over the next 2 turns. (This effect can trigger up to 2 times per turn).',
		simDesc_vn = 'Viêm Hổ Cuồng Liệt – Rengoku lao thẳng tới mục tiêu như một cột lửa bùng cháy, gây #C0x3D8A99#280% Sát Thương Vật Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Sát Thương Lửa tăng theo cấp kỹ năng, đồng thời gây <Choáng> mục tiêu trong 2 lượt (hiệu ứng khống chế, không thể hành động). Nếu mục tiêu bị hạ gục trong trạng thái <Choáng>, Rengoku bùng nổ thêm một lần #C0xE69900#200% Tấn Công Lửa#C0x5B545B# vào kẻ địch xung quanh (25% sát thương lan), và để lại hiệu ứng <Tàn Dư Viêm Hổ>, gây sát thương đốt thêm trong 2 lượt tiếp theo. (Hiệu ứng này có thể kích hoạt tối đa 2 lần trong 1 lượt).',
		simDesc_en = 'Blazing Tiger Rampage – Rengoku charges at the target like a blazing pillar of fire, dealing #C0x3D8A99#280% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Fire Damage scaling with skill level, while inflicting <Stun> on the target for 2 turns (control effect, unable to act). If the target is defeated while <Stunned>, Rengoku unleashes an additional #C0xE69900#200% Fire Attack#C0x5B545B# to nearby enemies (25% splash damage), and leaves behind <Blazing Tiger Residue>, burning them for 2 more turns. (This effect can trigger up to 2 times per turn).',
		simDesc_th = 'เสือเพลิงคลั่ง – เรนโกคุพุ่งเข้าหาเป้าหมายดุจเสาเพลิงที่ลุกไหม้ สร้างความเสียหายกายภาพ #C0x3D8A99#280%#C0x5B545B# และความเสียหายไฟ #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# ตามเลเวลสกิล พร้อมทั้งทำให้เป้าหมายติดสถานะ <สตัน> 2 เทิร์น (เอฟเฟกต์คุม ไม่สามารถกระทำการได้) หากเป้าหมายถูกกำจัดขณะ <สตัน> เรนโกคุจะระเบิดสร้างความเสียหายไฟ #C0xE69900#200%#C0x5B545B# ใส่ศัตรูรอบข้าง (ดาเมจแตก 25%) และทิ้งเอฟเฟกต์ <เสือเพลิงตกค้าง> สร้างดาเมจเผาไหม้ต่อเนื่อง 2 เทิร์น (เอฟเฟกต์นี้สามารถทำงานได้สูงสุด 2 ครั้งต่อเทิร์น)',
		simDesc_in = 'Harimau Api Mengamuk – Rengoku menerjang target seperti pilar api yang membara, memberikan #C0x3D8A99#280% Damage Fisik#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Damage Api yang meningkat sesuai level skill, serta memberikan efek <Stun> pada target selama 2 giliran (efek kontrol, tidak bisa bertindak). Jika target dikalahkan saat <Stun>, Rengoku meledak lagi memberikan #C0xE69900#200% Serangan Api#C0x5B545B# ke musuh di sekitarnya (25% damage sebar), dan meninggalkan efek <Sisa Api Harimau>, memberikan damage bakar tambahan selama 2 giliran berikutnya. (Efek ini dapat aktif maksimal 2 kali per giliran).',
		simDesc_ph = 'Naglalagablab na Tigre – Si Rengoku ay sumugod sa kalaban na parang nag-aalab na haligi ng apoy, nagdudulot ng #C0x3D8A99#280% Pisikal na Pinsala#C0x5B545B# at #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Pinsalang Apoy na tumataas ayon sa antas ng kasanayan, habang naglalagay ng <Stun> sa target sa loob ng 2 turn (control effect, hindi makakakilos). Kapag natalo ang target habang naka-<Stun>, si Rengoku ay sasabog pa ng #C0xE69900#200% Atakeng Apoy#C0x5B545B# sa mga kalabang malapit (25% splash damage), at mag-iiwan ng <Naglalagablab na Bakas ng Tigre> na magdudulot ng karagdagang burn damage sa loob ng 2 turn. (Maaaring ma-activate ang epektong ito ng hanggang 2 beses kada turn).',
		simDesc_ma = 'Harimau Api Mengganas – Rengoku menyerbu ke arah sasaran seperti tiang api yang menyala, memberikan #C0x3D8A99#280% Kerosakan Fizikal#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Kerosakan Api yang meningkat mengikut tahap kemahiran, serta mengenakan <Stun> pada sasaran selama 2 pusingan (kesan kawalan, tidak boleh bertindak). Jika sasaran ditewaskan ketika dalam keadaan <Stun>, Rengoku akan meletup sekali lagi memberikan #C0xE69900#200% Serangan Api#C0x5B545B# kepada musuh berdekatan (25% kerosakan sebar), dan meninggalkan kesan <Sisa Harimau Api> yang menyebabkan kerosakan bakar tambahan selama 2 pusingan berikutnya. (Kesan ini boleh diaktifkan maksimum 2 kali dalam satu pusingan).',
		simDesc = 'Blazing Tiger Rampage – Rengoku charges at the target like a blazing pillar of fire, dealing #C0x3D8A99#280% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Fire Damage scaling with skill level, while inflicting <Stun> on the target for 2 turns (control effect, unable to act). If the target is defeated while <Stunned>, Rengoku unleashes an additional #C0xE69900#200% Fire Attack#C0x5B545B# to nearby enemies (25% splash damage), and leaves behind <Blazing Tiger Residue>, burning them for 2 more turns. (This effect can trigger up to 2 times per turn).',
		zawakeEffect = __data_t__zawakeEffect[8005002],
		-- {79002}
		zawakeEffectDesc = 'Rengoku charges at the target like a blazing pillar of fire, dealing #C0x3D8A99#280% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*48)$ Fire Damage scaling with skill level, while stunning the target for 1 turn.',
		zawakeEffectDesc_en = 'Rengoku charges at the target like a blazing pillar of fire, dealing #C0x3D8A99#280% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*48)$ Fire Damage scaling with skill level, while stunning the target for 1 turn.',
		zawakeEffectDesc_th = 'Rengoku พุ่งเข้าใส่เป้าหมายดั่งเสาเพลิงลุกไหม้ สร้างความเสียหาย #C0x3D8A99#280% กายภาพ#C0x5B545B# และ #C0xF13B54#+$(skillLevel*4*48)$ ความเสียหายไฟตามเลเวลสกิล พร้อมทั้งทำให้ศัตรูติดสตัน 1 เทิร์น',
		zawakeEffectDesc_in = 'Rengoku menerjang target seperti pilar api yang menyala, memberikan #C0x3D8A99#280% Damage Fisik#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*48)$ Damage Api yang meningkat sesuai level skill, sekaligus membuat target stun selama 1 giliran.',
		zawakeEffectDesc_ph = 'Rengoku sumugod sa target na parang naglalagablab na haligi ng apoy, nagdudulot ng #C0x3D8A99#280% Physical Damage#C0x5B545B# at #C0xF13B54#+$(skillLevel*4*48)$ Fire Damage na tumataas ayon sa antas ng skill, habang ini-stun ang target ng 1 turn.',
		zawakeEffectDesc_ma = 'Rengoku menyerbu ke arah sasaran seperti tiang api yang menyala, memberikan #C0x3D8A99#280% Damage Fizikal#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*48)$ Damage Api yang meningkat mengikut tahap kemahiran, serta menyebabkan sasaran stun selama 1 giliran.',
		zawakeEffectDesc_vn = 'Rengoku lao thẳng tới mục tiêu như một cột lửa bùng cháy, gây #C0x3D8A99#280% Sát Thương Vật Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel*4*48)$ sát thương lửa tăng theo cấp kỹ năng, đồng thời làm choáng mục tiêu trong 1 lượt.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Rush forward dealing massive damage and stunning the target, with fire damage scaling with skill level.',
		zawakeSimpleDesc_en = 'Rush forward dealing massive damage and stunning the target, with fire damage scaling with skill level.',
		zawakeSimpleDesc_th = 'พุ่งเข้าไปทำความเสียหายรุนแรงและทำให้เป้าหมายมึนงง พร้อมความเสียหายไฟตามระดับทักษะ',
		zawakeSimpleDesc_in = 'Menerjang maju memberikan damage besar dan membuat target stun, disertai damage api sesuai level skill.',
		zawakeSimpleDesc_ph = 'Sumugod at nagdulot ng malaking pinsala at stun sa target, kasabay ng fire damage na tumataas ayon sa antas ng skill.',
		zawakeSimpleDesc_ma = 'Meluru ke hadapan menyebabkan kerosakan besar dan membuat sasaran terhenti, disertai damage api mengikut tahap skill.',
		zawakeSimpleDesc_vn = 'Lao tới gây sát thương lớn và làm choáng mục tiêu, kèm sát thương lửa theo cấp kỹ năng.',
