	[8005003] = {
		id = 8005003,
		skillName_vn = 'Viêm Trụ Trảm: Rực Cháy Tận Cùng',
		skillName_en = 'Flame Pillar Cleaver: Blazing to the End',
		skillName_th = 'เสาไฟดาบ: ลุกโชนถึงที่สุด',
		skillName_in = 'Flame Pillar Cleaver: Terbakar Sampai Akhir',
		skillName_ph = 'Flame Pillar Cleaver: Naglalagablab Hanggang Wakas',
		skillName_ma = 'Flame Pillar Cleaver: Membara Sampai Akhir',
		skillName = 'Viêm Trụ Trảm: Rực Cháy Tận Cùng',
		describe_vn = 'Rengoku dồn toàn bộ sức mạnh vào một cú chém rực lửa, tạo ra vụ nổ hỏa diệm thiêu rụi mọi thứ trong phạm vi hàng dọc, gây #C0x3D8A99#680% Sát Thương Vật Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# Sát Thương Lửa tăng theo cấp kỹ năng. Sức nóng kinh hoàng từ chiêu thức này khiến tất cả mục tiêu trúng đòn rơi vào trạng thái <Hỏa Trụ Vô Tận>. Tất cả kẻ địch trong phạm vi chịu giảm 20~40% phòng thủ, giảm 10% hiệu quả hồi máu, và chịu thêm 60% sát thương lửa. Đồng thời, đồng minh trong hàng ngang với Rengoku nhận thêm 15% sát thương cộng thêm. Nếu bất kỳ kẻ địch nào bị hạ gục trong thời gian hiệu lực, vụ nổ thứ cấp sẽ được kích hoạt, gây 200% sát thương lửa lên toàn bộ kẻ địch cùng hàng.',
		describe_en = 'Rengoku channels all his strength into a blazing slash, creating a fiery explosion that incinerates everything in a vertical line, dealing #C0x3D8A99#680% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# Fire Damage scaling with skill level. The overwhelming heat from this attack causes all hit targets to enter <Infinite Flame Pillar> state. All enemies in range have their defense reduced by 20~40%, healing effectiveness reduced by 10%, and take an additional 60% fire damage. Simultaneously, allies in the same row as Rengoku gain 15% bonus damage. If any enemy is defeated while this effect is active, a secondary explosion triggers, dealing 200% fire damage to all enemies in the same row.',
		describe_th = 'Rengoku รวบรวมพลังทั้งหมดในฟันไฟแผดเผา สร้างการระเบิดไฟเผาผลาญทุกสิ่งในแนวตั้ง ทำให้เกิด #C0x3D8A99#680% ความเสียหายทางกายภาพ#C0x5B545B# และ #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# ความเสียหายไฟตามระดับสกิล ความร้อนรุนแรงจากท่านี้ทำให้เป้าหมายทั้งหมดที่ถูกโจมตีเข้าสู่สถานะ <Infinite Flame Pillar> ศัตรูทั้งหมดในระยะจะลดการป้องกัน 20~40%, ลดประสิทธิภาพการฟื้นฟู 10%, และรับความเสียหายไฟเพิ่ม 60% พร้อมกันนั้น พันธมิตรในแถวเดียวกับ Rengoku ได้รับความเสียหายเพิ่มอีก 15% หากศัตรูใดถูกกำจัดขณะเอฟเฟกต์นี้ทำงาน จะเกิดการระเบิดทุติยภูมิ สร้างความเสียหายไฟ 200% ต่อศัตรูทั้งหมดในแถวเดียวกัน',
		describe_in = 'Rengoku menyalurkan seluruh kekuatannya ke dalam satu tebasan membara, menciptakan ledakan api yang membakar semua di garis vertikal, memberikan #C0x3D8A99#680% Damage Fisik#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# Damage Api yang meningkat sesuai level skill. Panas luar biasa dari serangan ini membuat semua target yang terkena masuk ke status <Infinite Flame Pillar>. Semua musuh dalam jangkauan mengalami pengurangan pertahanan 20~40%, pengurangan efek penyembuhan 10%, dan menerima tambahan 60% damage api. Pada saat yang sama, sekutu dalam baris yang sama dengan Rengoku menerima tambahan 15% damage. Jika ada musuh yang dikalahkan saat efek ini aktif, ledakan sekunder akan terpicu, memberikan 200% damage api ke semua musuh dalam baris yang sama.',
		describe_ph = 'Rengoku ay nag-channel ng lahat ng kanyang lakas sa isang naglalagablab na hiwa, na lumilikha ng pagsabog ng apoy na sinusunog ang lahat sa isang vertical na linya, nagdudulot ng #C0x3D8A99#680% Physical Damage#C0x5B545B# at #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# Fire Damage na tumataas ayon sa antas ng skill. Ang matinding init mula sa atake na ito ay nagdudulot sa lahat ng tinamaan na pumasok sa <Infinite Flame Pillar> state. Lahat ng kaaway sa saklaw ay nababawasan ang depensa ng 20~40%, epektibo ng paggaling nababawasan ng 10%, at tumatanggap ng karagdagang 60% fire damage. Kasabay nito, ang mga kakampi sa parehong hilera kay Rengoku ay nakakakuha ng 15% karagdagang damage. Kung anumang kaaway ay natalo habang aktibo ang effect, isang secondary explosion ang nag-trigger, nagdudulot ng 200% fire damage sa lahat ng kaaway sa parehong hilera.',
		describe_ma = 'Rengoku menyalurkan semua kekuatannya ke dalam satu sapuan pedang berapi, menghasilkan letupan api yang membakar segala-galanya dalam garis menegak, memberikan #C0x3D8A99#680% Kerosakan Fizikal#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# Kerosakan Api mengikut tahap kemahiran. Panas dahsyat dari serangan ini menyebabkan semua sasaran yang terkena berada dalam keadaan <Infinite Flame Pillar>. Semua musuh dalam jarak akan menerima pengurangan pertahanan 20~40%, pengurangan keberkesanan penyembuhan 10%, dan menerima tambahan 60% kerosakan api. Pada masa yang sama, sekutu dalam barisan yang sama dengan Rengoku menerima 15% kerosakan tambahan. Jika mana-mana musuh dikalahkan semasa kesan ini aktif, letupan sekunder dicetuskan, memberikan 200% kerosakan api kepada semua musuh dalam barisan yang sama.',
		describe = 'Rengoku channels all his strength into a blazing slash, creating a fiery explosion that incinerates everything in a vertical line, dealing #C0x3D8A99#680% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# Fire Damage scaling with skill level. The overwhelming heat from this attack causes all hit targets to enter <Infinite Flame Pillar> state. All enemies in range have their defense reduced by 20~40%, healing effectiveness reduced by 10%, and take an additional 60% fire damage. Simultaneously, allies in the same row as Rengoku gain 15% bonus damage. If any enemy is defeated while this effect is active, a secondary explosion triggers, dealing 200% fire damage to all enemies in the same row.',
		simDesc_vn = 'Rengoku dồn toàn bộ sức mạnh vào một cú chém rực lửa, tạo ra vụ nổ hỏa diệm thiêu rụi mọi thứ trong phạm vi hàng dọc, gây 680% Sát Thương Vật Lý và Sát Thương Lửa tăng theo cấp kỹ năng. Sức nóng kinh hoàng từ chiêu thức này khiến tất cả mục tiêu trúng đòn rơi vào trạng thái <Hỏa Trụ Vô Tận>. Tất cả kẻ địch trong phạm vi chịu giảm 20~40% phòng thủ, giảm 10% hiệu quả hồi máu, và chịu thêm 60% sát thương lửa. Đồng thời, đồng minh trong hàng ngang với Rengoku nhận thêm 15% sát thương cộng thêm. Nếu bất kỳ kẻ địch nào bị hạ gục trong thời gian hiệu lực, vụ nổ thứ cấp sẽ được kích hoạt, gây 200% sát thương lửa lên lên toàn bộ kẻ địch cùng hàng.',
		simDesc_en = 'Rengoku channels all his power into a blazing slash, creating a fiery explosion that incinerates everything in a vertical row, dealing 680% Physical Damage and Fire Damage scaling with skill level. The scorching heat forces all struck targets into the state of <Endless Flame Pillar>. All enemies within range suffer a 20~40% Defense reduction, 10% reduced healing effectiveness, and take 60% additional Fire Damage. Meanwhile, allies in the same row as Rengoku gain 15% bonus damage. If any enemy is defeated during the effect, a secondary explosion is triggered, dealing 200% Fire Damage to all enemies in the same row.',
		simDesc_th = 'เรนโกคุทุ่มพลังทั้งหมดใส่ในหนึ่งคมดาบเพลิง สร้างการระเบิดไฟที่เผาผลาญทุกสิ่งในแนวตั้ง สร้างความเสียหายกายภาพ 680% และความเสียหายไฟเพิ่มขึ้นตามเลเวลสกิล ความร้อนแรงนี้ทำให้เป้าหมายทั้งหมดเข้าสู่สถานะ <เสาเพลิงไร้สิ้นสุด> ศัตรูทั้งหมดในระยะถูกลดพลังป้องกัน 20~40% ลดประสิทธิภาพการฟื้นฟู 10% และได้รับความเสียหายไฟเพิ่มขึ้น 60% ขณะเดียวกัน พันธมิตรที่อยู่ในแถวเดียวกับเรนโกคุได้รับโบนัสความเสียหายเพิ่ม 15% หากศัตรูใดถูกกำจัดระหว่างเอฟเฟกต์นี้ การระเบิดครั้งที่สองจะถูกกระตุ้น สร้างความเสียหายไฟ 200% ต่อศัตรูทั้งหมดในแถวเดียวกัน',
		simDesc_in = 'Rengoku mengerahkan seluruh kekuatannya ke dalam satu tebasan api, menciptakan ledakan yang membakar semua musuh dalam baris vertikal, memberikan 680% Damage Fisik dan Damage Api yang meningkat sesuai level skill. Panas mengerikan dari serangan ini membuat semua target yang terkena masuk ke status <Pilar Api Tanpa Akhir>. Semua musuh dalam jangkauan kehilangan 20~40% pertahanan, 10% efektivitas pemulihan berkurang, dan menerima 60% tambahan Damage Api. Sementara itu, sekutu di baris yang sama dengan Rengoku mendapat 15% bonus damage. Jika ada musuh yang dikalahkan selama efek berlangsung, ledakan sekunder akan terpicu, memberikan 200% Damage Api kepada semua musuh di baris yang sama.',
		simDesc_ph = 'Buong lakas na inilagay ni Rengoku sa isang apoy na tebas, lumilikha ng pagsabog ng apoy na tumutupok sa lahat ng nasa patayong linya, nagdudulot ng 680% Pisikal na Pinsala at Pinsalang Apoy na tumataas ayon sa antas ng kasanayan. Ang naglalagablab na init ay naglalagay sa lahat ng tinamaan sa estado ng <Walang Hanggang Haliging Apoy>. Lahat ng kalaban sa saklaw ay nababawasan ng 20~40% depensa, 10% bisa ng paggaling, at tumatanggap ng 60% karagdagang Pinsalang Apoy. Samantala, ang mga kakampi sa parehong hilera ni Rengoku ay nakakatanggap ng dagdag na 15% pinsala. Kung may kalabang mapapatay habang aktibo ang epekto, isang pangalawang pagsabog ang maa-activate, nagdudulot ng 200% Pinsalang Apoy sa lahat ng kalaban sa parehong hilera.',
		simDesc_ma = 'Rengoku menumpukan seluruh tenaganya ke dalam satu tebasan api, mencetuskan letupan yang membakar semua musuh dalam baris menegak, memberikan 680% Kerosakan Fizikal dan Kerosakan Api yang meningkat mengikut tahap kemahiran. Kepanasan dahsyat daripada serangan ini menyebabkan semua sasaran yang terkena jatuh ke dalam status <Tiang Api Tanpa Hujung>. Semua musuh dalam julat menerima pengurangan pertahanan sebanyak 20~40%, keberkesanan pemulihan berkurang 10%, dan menerima tambahan 60% Kerosakan Api. Pada masa yang sama, sekutu yang berada dalam baris yang sama dengan Rengoku mendapat 15% kerosakan tambahan. Jika ada musuh ditewaskan sepanjang tempoh kesan ini, letupan sekunder akan diaktifkan, memberikan 200% Kerosakan Api kepada semua musuh dalam baris yang sama.',
		simDesc = 'Rengoku channels all his power into a blazing slash, creating a fiery explosion that incinerates everything in a vertical row, dealing 680% Physical Damage and Fire Damage scaling with skill level. The scorching heat forces all struck targets into the state of <Endless Flame Pillar>. All enemies within range suffer a 20~40% Defense reduction, 10% reduced healing effectiveness, and take 60% additional Fire Damage. Meanwhile, allies in the same row as Rengoku gain 15% bonus damage. If any enemy is defeated during the effect, a secondary explosion is triggered, dealing 200% Fire Damage to all enemies in the same row.',
		starEffect = __data_t__starEffect[8005003],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung: Tăng Sát Thương Khi Mục Tiêu Bị Choáng #L0# Khi tấn công mục tiêu đang chịu hiệu ứng <Choáng>, sát thương gây ra bởi kỹ năng tăng thêm 25%. #L10# Giảm Hồi Phục Của Mục Tiêu. #L0# Mục tiêu trúng đòn khi đang bị Choáng sẽ bị giảm 50% hiệu quả hồi phục trong 2 lượt kế tiếp (bao gồm cả hồi máu chủ động và thụ động).',
		starEffectDesc = 'Additional Effect: Increase Damage When Target is Stunned #L0# When attacking a target under <Stun>, skill damage is increased by 25%. #L10# Reduce Target’s Recovery. #L0# Targets hit while Stunned will have their recovery reduced by 50% for the next 2 turns (including both active and passive healing).',
		starEffectDesc_en = 'Additional Effect: Increase Damage When Target is Stunned #L0# When attacking a target under <Stun>, skill damage is increased by 25%. #L10# Reduce Target’s Recovery. #L0# Targets hit while Stunned will have their recovery reduced by 50% for the next 2 turns (including both active and passive healing).',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: เพิ่มความเสียหายเมื่อเป้าหมายอยู่ในสถานะมึนงง #L0# เมื่อโจมตีเป้าหมายที่อยู่ในสถานะ <มึนงง> ความเสียหายจากสกิลจะเพิ่มขึ้น 25% #L10# ลดการฟื้นฟูของเป้าหมาย #L0# เป้าหมายที่โดนโจมตีขณะมึนงงจะถูกลดประสิทธิภาพการฟื้นฟูลง 50% เป็นเวลา 2 เทิร์นถัดไป (รวมถึงการฟื้นฟูแบบแอคทีฟและพาสซีฟ)',
		starEffectDesc_in = 'Efek Tambahan: Tingkatkan Damage Saat Target Terkena Stun #L0# Saat menyerang target yang berada dalam efek <Stun>, damage skill meningkat 25%. #L10# Kurangi Pemulihan Target. #L0# Target yang terkena serangan saat Stun akan berkurang 50% efektivitas pemulihannya selama 2 giliran berikutnya (termasuk pemulihan aktif dan pasif).',
		starEffectDesc_ph = 'Karagdagang Epekto: Dagdagan ang Damage Kapag ang Target ay Na-Stun #L0# Kapag inatake ang target na nasa ilalim ng <Stun>, tataas ng 25% ang damage ng skill. #L10# Bawasan ang Pag-recover ng Target. #L0# Ang target na tinamaan habang Na-Stun ay mababawasan ng 50% ang bisa ng pag-recover sa loob ng susunod na 2 turn (kasama ang active at passive healing).',
		starEffectDesc_ma = 'Kesan Tambahan: Tingkatkan Damage Apabila Sasaran Dikenakan Stun #L0# Apabila menyerang sasaran yang berada dalam <Stun>, damage skill meningkat sebanyak 25%. #L10# Kurangkan Pemulihan Sasaran. #L0# Sasaran yang terkena serangan ketika Stun akan dikurangkan keberkesanan pemulihan sebanyak 50% untuk 2 giliran seterusnya (termasuk pemulihan aktif dan pasif).',
		zawakeEffect = __data_t__zawakeEffect[8005003],
		-- {79003}
		zawakeEffectDesc = 'Rengoku channels all his strength into a blazing slash, unleashing a fiery explosion that incinerates everything in a vertical line, dealing #C0x3D8A99#680% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*90)$ Fire Damage scaling with skill level.',
		zawakeEffectDesc_en = 'Rengoku channels all his strength into a blazing slash, unleashing a fiery explosion that incinerates everything in a vertical line, dealing #C0x3D8A99#680% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*90)$ Fire Damage scaling with skill level.',
		zawakeEffectDesc_th = 'Rengoku ทุ่มพลังทั้งหมดใส่การฟาดดาบเพลิง สร้างระเบิดเพลิงเผาผลาญทุกสิ่งในแนวตั้ง สร้างความเสียหาย #C0x3D8A99#680% กายภาพ#C0x5B545B# และ #C0xF13B54#+$(skillLevel*4*90)$ ความเสียหายไฟตามเลเวลสกิล',
		zawakeEffectDesc_in = 'Rengoku mengerahkan seluruh kekuatannya ke dalam satu tebasan berapi, menciptakan ledakan api yang membakar semua musuh dalam garis vertikal, memberikan #C0x3D8A99#680% Damage Fisik#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*90)$ Damage Api yang meningkat sesuai level skill.',
		zawakeEffectDesc_ph = 'Rengoku ibinuhos ang lahat ng lakas sa isang apoy na hiwa, naglalabas ng pagsabog ng apoy na tumutupok sa lahat sa patayong linya, nagdudulot ng #C0x3D8A99#680% Physical Damage#C0x5B545B# at #C0xF13B54#+$(skillLevel*4*90)$ Fire Damage na tumataas ayon sa antas ng skill.',
		zawakeEffectDesc_ma = 'Rengoku menumpukan seluruh kekuatannya ke dalam satu tebasan berapi, mencetuskan letupan api yang membakar semua musuh dalam barisan menegak, memberikan #C0x3D8A99#680% Damage Fizikal#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*90)$ Damage Api yang meningkat mengikut tahap kemahiran.',
		zawakeEffectDesc_vn = 'Rengoku dồn toàn bộ sức mạnh vào một cú chém rực lửa, tạo ra vụ nổ hỏa diệm thiêu rụi mọi thứ trong phạm vi hàng dọc, gây #C0x3D8A99#680% Sát Thương Vật Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel*4*90)$ sát thương lửa tăng theo cấp kỹ năng.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Unleash a powerful flaming slash dealing AoE damage in a vertical line, with fire damage scaling with skill level.',
		zawakeSimpleDesc_en = 'Unleash a powerful flaming slash dealing AoE damage in a vertical line, with fire damage scaling with skill level.',
		zawakeSimpleDesc_th = 'ปล่อยการฟันไฟที่รุนแรง ทำความเสียหายแบบ AoE เป็นแนวตั้ง พร้อมความเสียหายไฟตามระดับทักษะ',
		zawakeSimpleDesc_in = 'Lakukan tebasan api yang sangat kuat memberikan damage AoE dalam garis vertikal, disertai damage api sesuai level skill.',
		zawakeSimpleDesc_ph = 'Maglabas ng malakas na flaming slash na nagdudulot ng AoE damage sa vertical line, kasabay ng fire damage na tumataas ayon sa antas ng skill.',
		zawakeSimpleDesc_ma = 'Lakukan tebasan api yang sangat kuat menyebabkan AoE damage secara barisan menegak, disertai damage api mengikut tahap skill.',
		zawakeSimpleDesc_vn = 'Tung cú chém lửa cực mạnh gây sát thương diện rộng theo hàng dọc, kèm sát thương lửa theo cấp kỹ năng.',
		iconRes = 'battle/skill_icon/skill_80053.png',
