	[8006002] = {
		id = 8006002,
		skillName_vn = 'Lục Liên Trảm',
		skillName_en = 'Six-Linked Cleaver',
		skillName_th = 'ดาบหกข้อเชื่อม',
		skillName_in = 'Cleaver Enam Rantai',
		skillName_ph = 'Anim na Ugnay na Cleaver',
		skillName_ma = 'Cleaver Enam Rantai',
		skillName = 'Lục Liên Trảm',
		describe_vn = 'Lục Liên Trảm – Zenitsu thi triển 6 đòn chớp nhoáng với tốc độ không thể thấy bằng mắt thường, chém thẳng vào mục tiêu chính và lan theo hàng dọc phía sau kẻ địch. Mỗi đòn gây #C0x3D8A99#280% Sát Thương Vật Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Sát Thương Sét Cường Hóa tăng theo cấp kỹ năng. Nếu mục tiêu đang chịu hiệu ứng <Tê Liệt>, mỗi đòn tấn công gây thêm +15% sát thương và có 20% xác suất gây choáng lan cho mục tiêu xung quanh.\n#F10#\n#F40##L10# Lôi Vũ Liên Kích:#L0# Khi sử dụng kỹ năng, có 50% xác suất khiến Lần Đánh Thứ Sáu trở thành <Lôi Trảm Tối Thượng> – gây gấp đôi sát thương sét, đồng thời giảm 20% tốc độ hành động của mục tiêu chính trong 1 lượt.',
		describe_en = 'Six-Strike Slash – Zenitsu performs 6 lightning-fast strikes invisible to the naked eye, slashing straight through the main target and spreading down the row behind enemies. Each strike deals #C0x3D8A99#280% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Enhanced Lightning Damage scaling with skill level. If the target is under <Paralyze> effect, each strike deals an additional +15% damage and has a 20% chance to stun surrounding targets.\n#F10#\n#F40##L10# Thunderstorm Combo:#L0# When using this skill, there is a 50% chance for the Sixth Strike to become <Supreme Thunder Slash> – dealing double lightning damage and reducing the main target’s action speed by 20% for 1 turn.',
		describe_th = 'Six-Strike Slash – Zenitsu ใช้การโจมตีรวดเร็ว 6 ครั้งที่สายตาไม่สามารถมองเห็น ฟันตรงเป้าหมายหลักและแพร่ตามแถวด้านหลังศัตรู แต่ละครั้งสร้างความเสียหาย #C0x3D8A99#280% Physical Damage#C0x5B545B# และ #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Enhanced Lightning Damage ตามระดับสกิล หากเป้าหมายอยู่ในสถานะ <Paralyze> แต่ละครั้งสร้างความเสียหายเพิ่ม +15% และมีโอกาส 20% ทำให้เป้าหมายรอบข้างติด Stun \n#F10#\n#F40##L10# Thunderstorm Combo:#L0# เมื่อใช้สกิลนี้ มีโอกาส 50% ที่การโจมตีครั้งที่หกจะกลายเป็น <Supreme Thunder Slash> – สร้างความเสียหายสายฟ้าสองเท่าและลดความเร็วการกระทำของเป้าหมายหลัก 20% เป็นเวลา 1 เทิร์น',
		describe_in = 'Six-Strike Slash – Zenitsu melakukan 6 serangan super cepat yang tak terlihat oleh mata, menebas langsung target utama dan menyebar ke barisan belakang musuh. Setiap serangan memberikan #C0x3D8A99#280% Physical Damage#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Enhanced Lightning Damage sesuai level skill. Jika target berada di bawah efek <Paralyze>, setiap serangan memberikan +15% damage tambahan dan memiliki 20% kemungkinan membuat target di sekitar terkena stun.\n#F10#\n#F40##L10# Thunderstorm Combo:#L0# Saat menggunakan skill ini, ada 50% kemungkinan Strike Keenam menjadi <Supreme Thunder Slash> – memberikan double lightning damage dan mengurangi kecepatan aksi target utama sebesar 20% selama 1 giliran.',
		describe_ph = 'Six-Strike Slash – Zenitsu ay nagsasagawa ng 6 napakabilis na atake na hindi nakikita ng mata, hiwa diretso sa pangunahing target at kumakalat pababa sa row sa likod ng mga kalaban. Bawat atake ay nagdudulot ng #C0x3D8A99#280% Physical Damage#C0x5B545B# at #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Enhanced Lightning Damage na tumataas sa level ng skill. Kung ang target ay nasa ilalim ng <Paralyze>, bawat atake ay nagbibigay ng karagdagang +15% damage at may 20% chance na ma-stun ang mga target sa paligid.\n#F10#\n#F40##L10# Thunderstorm Combo:#L0# Kapag ginamit ang skill na ito, may 50% chance na ang Sixth Strike ay maging <Supreme Thunder Slash> – nagdudulot ng double lightning damage at binabawasan ang action speed ng pangunahing target ng 20% sa loob ng 1 turn.',
		describe_ma = 'Six-Strike Slash – Zenitsu melaksanakan 6 serangan pantas yang tidak kelihatan dengan mata kasar, menebas terus sasaran utama dan merebak ke barisan belakang musuh. Setiap serangan menyebabkan #C0x3D8A99#280% Physical Damage#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Enhanced Lightning Damage mengikut tahap skill. Jika sasaran berada di bawah kesan <Paralyze>, setiap serangan memberikan +15% damage tambahan dan mempunyai 20% peluang untuk menstun sasaran di sekeliling.\n#F10#\n#F40##L10# Thunderstorm Combo:#L0# Apabila menggunakan skill ini, terdapat 50% peluang Strike Keenam menjadi <Supreme Thunder Slash> – memberikan double lightning damage dan mengurangkan kelajuan aksi sasaran utama sebanyak 20% selama 1 giliran.',
		describe = 'Six-Strike Slash – Zenitsu performs 6 lightning-fast strikes invisible to the naked eye, slashing straight through the main target and spreading down the row behind enemies. Each strike deals #C0x3D8A99#280% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Enhanced Lightning Damage scaling with skill level. If the target is under <Paralyze> effect, each strike deals an additional +15% damage and has a 20% chance to stun surrounding targets.\n#F10#\n#F40##L10# Thunderstorm Combo:#L0# When using this skill, there is a 50% chance for the Sixth Strike to become <Supreme Thunder Slash> – dealing double lightning damage and reducing the main target’s action speed by 20% for 1 turn.',
		simDesc_vn = 'Lục Liên Trảm – Zenitsu thi triển 6 đòn chớp nhoáng với tốc độ không thể thấy bằng mắt thường, chém thẳng vào mục tiêu chính và lan theo hàng dọc phía sau kẻ địch. Mỗi đòn gây #C0x3D8A99#280% Sát Thương Vật Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Sát Thương Sét Cường Hóa tăng theo cấp kỹ năng. Nếu mục tiêu đang chịu hiệu ứng <Tê Liệt>, mỗi đòn tấn công gây thêm +15% sát thương và có 20% xác suất gây choáng lan cho mục tiêu xung quanh.\n#F10#\n#F40##L10# Lôi Vũ Liên Kích:#L0# Khi sử dụng kỹ năng, có 50% xác suất khiến Lần Đánh Thứ Sáu trở thành <Lôi Trảm Tối Thượng> – gây gấp đôi sát thương sét, đồng thời giảm 20% tốc độ hành động của mục tiêu chính trong 1 lượt.',
		simDesc_en = 'Sixfold Slash – Zenitsu unleashes 6 lightning-fast strikes at a speed invisible to the naked eye, slashing through the main target and along the vertical row behind them. Each strike deals #C0x3D8A99#280% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Enhanced Lightning Damage scaling with skill level. If the target is under <Paralysis>, each strike deals +15% additional damage and has a 20% chance to spread Stun to nearby enemies.\n#F10#\n#F40##L10# Thunderstorm Combo:#L0# When casting this skill, there is a 50% chance for the Sixth Strike to become <Supreme Thunder Slash> – dealing double lightning damage and reducing the main target’s action speed by 20% for 1 turn.',
		simDesc_th = 'หกรอยฟันสายฟ้า – เซนิตสึปลดปล่อยการโจมตี 6 ครั้งด้วยความเร็วเหนือสายตา ฟันตรงใส่เป้าหมายหลักและโจมตีทะลุแนวดิ่งด้านหลังศัตรู แต่ละการโจมตีสร้างความเสียหาย #C0x3D8A99#280% กายภาพ#C0x5B545B# และ #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# ความเสียหายสายฟ้าเสริมที่เพิ่มขึ้นตามเลเวลสกิล หากเป้าหมายติดสถานะ <อัมพาต> แต่ละการโจมตีสร้างความเสียหายเพิ่ม +15% และมีโอกาส 20% ทำให้ศัตรูรอบข้างติดสตัน\n#F10#\n#F40##L10# พายุสายฟ้า连击:#L0# เมื่อใช้สกิลนี้ มีโอกาส 50% ที่การโจมตีครั้งที่หกจะกลายเป็น <สายฟ้าฟาดสูงสุด> – สร้างความเสียหายสายฟ้าเป็นสองเท่า และลดความเร็วการกระทำของเป้าหมายหลักลง 20% เป็นเวลา 1 เทิร์น',
		simDesc_in = 'Enam Tebasan Kilat – Zenitsu melancarkan 6 tebasan secepat kilat yang tak terlihat mata, menebas target utama dan menjalar ke barisan musuh di belakangnya. Setiap tebasan memberikan #C0x3D8A99#280% Damage Fisik#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Damage Petir yang ditingkatkan sesuai level skill. Jika target terkena efek <Paralisis>, setiap serangan memberikan +15% damage tambahan dan memiliki 20% peluang untuk menyebarkan Stun ke musuh di sekitar.\n#F10#\n#F40##L10# Kombo Badai Petir:#L0# Saat skill digunakan, ada 50% peluang serangan keenam menjadi <Tebasan Petir Tertinggi> – memberikan dua kali lipat damage petir dan mengurangi kecepatan aksi target utama sebesar 20% selama 1 giliran.',
		simDesc_ph = 'Anim na Sunod-sunod na Tebas – Si Zenitsu ay naglalabas ng 6 na kidlat-bilis na tebas na hindi kayang makita ng mata, tinatamaan ang pangunahing target at ang hilera ng kalaban sa likod nito. Bawat tebas ay nagdudulot ng #C0x3D8A99#280% Pisikal na Pinsala#C0x5B545B# at #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Pinalakas na Pinsala ng Kidlat na tumataas ayon sa antas ng kasanayan. Kung ang target ay nasa ilalim ng <Paralisado>, bawat atake ay nagbibigay ng +15% karagdagang pinsala at may 20% tsansa na magkalat ng Stun sa mga kalaban sa paligid.\n#F10#\n#F40##L10# Sunod-sunod na Bagyong Kidlat:#L0# Kapag ginamit ang kasanayang ito, may 50% tsansa na ang Ika-anim na Tebas ay maging <Supreme Thunder Slash> – nagdudulot ng dobleng pinsala ng kidlat at binabawasan ang bilis ng aksyon ng pangunahing target ng 20% sa loob ng 1 turn.',
		simDesc_ma = 'Enam Tebasan Kilat – Zenitsu melepaskan 6 serangan sepantas kilat yang tidak dapat dilihat dengan mata kasar, menebas sasaran utama dan merebak ke barisan musuh di belakangnya. Setiap serangan memberikan #C0x3D8A99#280% Kerosakan Fizikal#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Kerosakan Petir Dipertingkat mengikut tahap kemahiran. Jika sasaran berada dalam status <Lumpuh>, setiap serangan memberikan +15% kerosakan tambahan dan mempunyai 20% peluang menyebarkan Stun kepada musuh berdekatan.\n#F10#\n#F40##L10# Kombo Ribut Petir:#L0# Apabila menggunakan kemahiran ini, terdapat 50% peluang serangan keenam menjadi <Tebasan Petir Muktamad> – memberikan kerosakan petir berganda dan mengurangkan kelajuan tindakan sasaran utama sebanyak 20% selama 1 giliran.',
		simDesc = 'Sixfold Slash – Zenitsu unleashes 6 lightning-fast strikes at a speed invisible to the naked eye, slashing through the main target and along the vertical row behind them. Each strike deals #C0x3D8A99#280% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*48)$#C0x5B545B# Enhanced Lightning Damage scaling with skill level. If the target is under <Paralysis>, each strike deals +15% additional damage and has a 20% chance to spread Stun to nearby enemies.\n#F10#\n#F40##L10# Thunderstorm Combo:#L0# When casting this skill, there is a 50% chance for the Sixth Strike to become <Supreme Thunder Slash> – dealing double lightning damage and reducing the main target’s action speed by 20% for 1 turn.',
		zawakeEffect = __data_t__zawakeEffect[8006002],
		-- {79002}
		zawakeEffectDesc = 'Zenitsu executes 6 lightning-fast strikes at speeds invisible to the naked eye, hitting the main target and spreading in a vertical line behind enemies. Each strike deals: #C0x3D8A99#280% Physical Damage, #C0xF13B54#+$(skillLevel*448)$ Enhanced Lightning Damage.',
		zawakeEffectDesc_en = 'Zenitsu executes 6 lightning-fast strikes at speeds invisible to the naked eye, hitting the main target and spreading in a vertical line behind enemies. Each strike deals: #C0x3D8A99#280% Physical Damage, #C0xF13B54#+$(skillLevel*448)$ Enhanced Lightning Damage.',
		zawakeEffectDesc_th = 'Zenitsu ปล่อย 6 การโจมตีวาบฟ้าที่เร็วเกินกว่าจะมองเห็นด้วยตาโจมตีเป้าหมายหลักและแพร่ตามแนวตั้งด้านหลังศัตรู แต่ละการโจมตีสร้างความเสียหาย: #C0x3D8A99#280% กายภาพ, #C0xF13B54#+$(skillLevel*448)$ ความเสียหายสายฟ้าเสริมแรง',
		zawakeEffectDesc_in = 'Zenitsu melancarkan 6 serangan kilat secepat mata tak mampu melihat, menyerang target utama dan menyebar dalam garis vertikal di belakang musuh. Setiap serangan memberikan: #C0x3D8A99#280% Damage Fisik, #C0xF13B54#+$(skillLevel*448)$ Damage Petir Ditingkatkan.',
		zawakeEffectDesc_ph = 'Zenitsu naglunsad ng 6 lightning-fast strikes na hindi nakikita ng mata, tinatamaan ang pangunahing target at kumakalat sa vertical line sa likod ng mga kaaway. Bawat suntok ay nagdudulot ng: #C0x3D8A99#280% Physical Damage, #C0xF13B54#+$(skillLevel*448)$ Enhanced Lightning Damage.',
		zawakeEffectDesc_ma = 'Zenitsu melancarkan 6 serangan kilat sepantas yang mata manusia tidak dapat lihat, menyerang sasaran utama dan merebak dalam barisan menegak di belakang musuh. Setiap serangan memberikan: #C0x3D8A99#280% Damage Fizikal, #C0xF13B54#+$(skillLevel*448)$ Damage Petir Dipertingkatkan.',
		zawakeEffectDesc_vn = 'Zenitsu thi triển 6 đòn chớp nhoáng với tốc độ không thể thấy bằng mắt thường, tấn công mục tiêu chính và lan theo hàng dọc phía sau kẻ địch. Mỗi đòn gây: #C0x3D8A99#280% Sát Thương Vật Lý, #C0xF13B54#+$(skillLevel448)$ sát thương sét cường hóa.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Performs 6 rapid strikes causing high damage in a vertical line, with lightning damage increasing per skill level.',
		zawakeSimpleDesc_en = 'Performs 6 rapid strikes causing high damage in a vertical line, with lightning damage increasing per skill level.',
		zawakeSimpleDesc_th = 'โจมตี 6 ครั้งรวดเร็ว สร้างความเสียหายสูงตามแนวตั้ง พร้อมความเสียหายสายฟ้าเพิ่มตามระดับสกิล',
		zawakeSimpleDesc_in = 'Melakukan 6 serangan kilat yang memberikan kerusakan besar secara vertikal, dengan kerusakan petir bertambah sesuai level skill.',
		zawakeSimpleDesc_ph = 'Nagsasagawa ng 6 mabilis na atake na may mataas na damage sa patayong linya, kasabay ng pagtaas ng lightning damage kada level ng skill.',
		zawakeSimpleDesc_ma = 'Melaksanakan 6 serangan pantas yang memberikan kerosakan tinggi secara menegak, dengan kerosakan elektrik meningkat mengikut tahap kemahiran.',
		zawakeSimpleDesc_vn = 'Thi triển 6 đòn chớp nhoáng gây sát thương lớn và lan theo hàng dọc, kèm sát thương sét tăng theo cấp.',
		iconRes = 'battle/skill_icon/skill_80062.png',
