	[8006003] = {
		id = 8006003,
		skillName_vn = 'Lôi Long Nhất Tức: Thất Liên Trảm',
		skillName_en = 'Thunder Dragon Lightning Strike: Seven-Linked Cleaver',
		skillName_th = 'มังกรสายฟ้าฟาดเดียว: ดาบเจ็ดข้อเชื่อม',
		skillName_in = 'Naga Petir Serangan Kilat: Cleaver Tujuh Rantai',
		skillName_ph = 'Thunder Dragon Lightning Strike: Pitong Ugnay na Cleaver',
		skillName_ma = 'Naga Petir Serangan Kilat: Cleaver Tujuh Rantai',
		skillName = 'Lôi Long Nhất Tức: Thất Liên Trảm',
		describe_vn = 'Lôi Long Nhất Tức: Thất Liên Trảm – Zenitsu nhắm mắt, tĩnh tâm trong một khoảnh khắc, dồn toàn bộ sức mạnh sấm sét vào cơ thể. Trong làn chớp lóe sáng, anh lao vụt về phía trước như tia sét, tung ra 7 nhát chém liên hoàn cực mạnh, gây sát thương lên toàn bộ đội hình địch. Gây #C0x3D8A99#680% Sát Thương Vật Lý#C0x5B545B# và #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# Sát Thương Sét Tuyệt Kỹ. \n#F10#\n#F40##L10# Lôi Long Kích: #L0# Kỹ năng đánh trúng toàn bộ kẻ địch, không phân biệt vị trí, mỗi mục tiêu có 60% xác suất bị <Tê Liệt> trong 1 lượt. Nếu Zenitsu đang ở trạng thái <Ngủ Chiến Đấu>, toàn bộ sát thương kỹ năng tăng thêm 30%, và kỹ năng không thể bị gián đoạn bởi hiệu ứng khống chế.',
		describe_en = 'Thunderbolt Flash: Seven-Strike Slash – Zenitsu closes his eyes and centers himself for a moment, channeling all his lightning power into his body. Amidst the blinding flashes, he lunges forward like a bolt of lightning, delivering 7 consecutive strikes that hit the entire enemy formation. Deals #C0x3D8A99#680% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# Ultimate Lightning Damage. \n#F10#\n#F40##L10# Thunder Strike: #L0# The skill hits all enemies regardless of position, with each target having a 60% chance to be <Paralyzed> for 1 turn. If Zenitsu is in <Combat Sleep> state, total skill damage increases by 30%, and the skill cannot be interrupted by control effects.',
		describe_th = 'Thunderbolt Flash: Seven-Strike Slash – Zenitsu หลับตาและตั้งสมาธิในช่วงวินาที สะสมพลังสายฟ้าทั้งหมดในร่างกาย ท่ามกลางแสงวาบของฟ้าผ่า เขาพุ่งไปข้างหน้าเหมือนสายฟ้า ฟันต่อเนื่อง 7 ครั้งโจมตีทั้งแถวศัตรู สร้างความเสียหาย #C0x3D8A99#680% Physical Damage#C0x5B545B# และ #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# Ultimate Lightning Damage. \n#F10#\n#F40##L10# Thunder Strike: #L0# สกิลโจมตีศัตรูทั้งหมดโดยไม่แบ่งตำแหน่ง แต่ละเป้าหมายมีโอกาส 60% ติดสถานะ <Paralyzed> เป็นเวลา 1 เทิร์น หาก Zenitsu อยู่ในสถานะ <Combat Sleep> ความเสียหายของสกิลทั้งหมดเพิ่มขึ้น 30% และสกิลไม่สามารถถูกขัดขวางโดยเอฟเฟกต์ควบคุม',
		describe_in = 'Thunderbolt Flash: Seven-Strike Slash – Zenitsu menutup mata dan menenangkan diri sejenak, menyalurkan seluruh kekuatan petir ke tubuhnya. Di tengah kilatan cahaya, dia melesat ke depan seperti petir, melancarkan 7 serangan berturut-turut yang mengenai seluruh formasi musuh. Memberikan #C0x3D8A99#680% Physical Damage#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# Ultimate Lightning Damage. \n#F10#\n#F40##L10# Thunder Strike: #L0# Skill ini mengenai semua musuh tanpa memandang posisi, dengan setiap target memiliki 60% peluang terkena <Paralyzed> selama 1 giliran. Jika Zenitsu berada dalam status <Combat Sleep>, total damage skill meningkat 30% dan skill tidak dapat dihentikan oleh efek kontrol.',
		describe_ph = 'Thunderbolt Flash: Seven-Strike Slash – Zenitsu ay pumikit at nagtipon ng lakas sandali, ini-channel ang lahat ng kanyang kapangyarihan ng kidlat sa katawan. Sa gitna ng kumikislap na kidlat, siya ay bumangon pasulong na parang kidlat, naglunsad ng 7 sunod-sunod na hiwa na tumatama sa buong pormasyon ng kalaban. Nagdudulot ng #C0x3D8A99#680% Physical Damage#C0x5B545B# at #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# Ultimate Lightning Damage. \n#F10#\n#F40##L10# Thunder Strike: #L0# Ang skill ay tumatama sa lahat ng kalaban kahit saang posisyon, bawat target ay may 60% chance na ma-<Paralyzed> sa loob ng 1 turn. Kung si Zenitsu ay nasa <Combat Sleep> state, ang kabuuang damage ng skill ay tataas ng 30%, at hindi ito maaaring maputol ng mga control effect.',
		describe_ma = 'Thunderbolt Flash: Seven-Strike Slash – Zenitsu menutup mata dan menenangkan diri seketika, menyalurkan semua kuasa petir ke dalam tubuhnya. Di tengah kilatan cahaya, dia meluncur ke hadapan seperti kilat, melancarkan 7 serangan berturut-turut yang menyerang seluruh formasi musuh. Menyebabkan #C0x3D8A99#680% Physical Damage#C0x5B545B# dan #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# Ultimate Lightning Damage. \n#F10#\n#F40##L10# Thunder Strike: #L0# Kemahiran ini menyerang semua musuh tanpa mengira posisi, dengan setiap sasaran mempunyai 60% peluang untuk <Paralyzed> selama 1 giliran. Jika Zenitsu berada dalam keadaan <Combat Sleep>, jumlah kerosakan kemahiran meningkat 30% dan kemahiran tidak boleh diganggu oleh efek kawalan.',
		describe = 'Thunderbolt Flash: Seven-Strike Slash – Zenitsu closes his eyes and centers himself for a moment, channeling all his lightning power into his body. Amidst the blinding flashes, he lunges forward like a bolt of lightning, delivering 7 consecutive strikes that hit the entire enemy formation. Deals #C0x3D8A99#680% Physical Damage#C0x5B545B# and #C0xF13B54#+$(skillLevel*4*90)$#C0x5B545B# Ultimate Lightning Damage. \n#F10#\n#F40##L10# Thunder Strike: #L0# The skill hits all enemies regardless of position, with each target having a 60% chance to be <Paralyzed> for 1 turn. If Zenitsu is in <Combat Sleep> state, total skill damage increases by 30%, and the skill cannot be interrupted by control effects.',
		simDesc_vn = 'Lôi Long Nhất Tức: Thất Liên Trảm – Zenitsu nhắm mắt, tĩnh tâm trong một khoảnh khắc, dồn toàn bộ sức mạnh sấm sét vào cơ thể. Trong làn chớp lóe sáng, anh lao vụt về phía trước như tia sét, tung ra 7 nhát chém liên hoàn cực mạnh, gây sát thương lên toàn bộ đội hình địch. Gây 680% Sát Thương Vật Lý và Sát Thương Sét Tuyệt Kỹ. Lôi Long Kích: Kỹ năng đánh trúng toàn bộ kẻ địch, không phân biệt vị trí, mỗi mục tiêu có 60% xác suất bị <Tê Liệt> trong 1 lượt. Nếu Zenitsu đang ở trạng thái <Ngủ Chiến Đấu>, toàn bộ sát thương kỹ năng tăng thêm 30%, và kỹ năng không thể bị gián đoạn bởi hiệu ứng khống chế. Khi tiêu diệt ít nhất 1 kẻ địch, Lôi Long Tàn Ảnh được kích hoạt, gây thêm 120% Sát Thương Sét lên toàn bộ kẻ địch còn sống.',
		simDesc_en = 'Thunder Dragon Flash: Sevenfold Slash – Zenitsu closes his eyes, calming his mind for a moment, channeling all lightning power into his body. In a blinding flash, he dashes forward like a thunderbolt, unleashing 7 devastating consecutive slashes, striking the entire enemy formation. Deals 680% Physical Damage and Ultimate Lightning Damage.\n#F10#\n#F40##L10# Thunder Dragon Strike:#L0# Hits all enemies regardless of position, with each target having a 60% chance to be <Paralyzed> for 1 turn. If Zenitsu is in <Battle Sleep>, all skill damage is increased by 30%, and the skill cannot be interrupted by control effects. If at least 1 enemy is defeated, Thunder Dragon Afterimage is activated, dealing an additional 120% Lightning Damage to all surviving enemies.',
		simDesc_th = 'ฟาดมังกรสายฟ้า: เจ็ดรอยฟัน – เซนิตสึหลับตา สงบจิตใจในชั่วขณะ รวมพลังสายฟ้าทั้งหมดเข้าสู่ร่างกาย ท่ามกลางแสงฟ้าแลบ เขาพุ่งไปข้างหน้าเหมือนสายฟ้า ฟาดฟันต่อเนื่อง 7 ครั้งอันรุนแรง โจมตีศัตรูทั้งทีม สร้างความเสียหาย 680% กายภาพและดาเมจสายฟ้าอัลติเมต \n#F10#\n#F40##L10# ฟาดมังกรสายฟ้า:#L0# โจมตีโดนศัตรูทุกคนโดยไม่สนตำแหน่ง แต่ละเป้าหมายมีโอกาส 60% ติดสถานะ <อัมพาต> 1 เทิร์น หากเซนิตสึอยู่ในสถานะ <หลับต่อสู้> ดาเมจสกิลทั้งหมดเพิ่มขึ้น 30% และสกิลจะไม่ถูกขัดจังหวะด้วยเอฟเฟกต์ควบคุม หากสังหารได้อย่างน้อย 1 ศัตรู จะกระตุ้นเงามังกรสายฟ้า สร้างดาเมจสายฟ้าเพิ่มอีก 120% ใส่ศัตรูที่เหลือทั้งหมด',
		simDesc_in = 'Naga Petir Sekejap: Tujuh Tebasan – Zenitsu menutup mata, menenangkan diri sejenak, lalu menyalurkan seluruh kekuatan petir ke dalam tubuhnya. Dalam kilatan cahaya, ia melesat maju seperti halilintar, melepaskan 7 tebasan beruntun yang sangat dahsyat, menyerang seluruh formasi musuh. Memberikan 680% Damage Fisik dan Damage Petir Ultimate.\n#F10#\n#F40##L10# Serangan Naga Petir:#L0# Mengenai semua musuh tanpa memandang posisi, setiap target memiliki 60% peluang terkena <Paralisis> selama 1 giliran. Jika Zenitsu berada dalam status <Tidur Tempur>, seluruh damage skill meningkat 30%, dan skill tidak bisa diganggu oleh efek kontrol. Jika setidaknya 1 musuh terbunuh, Naga Petir Bayangan akan terpicu, memberikan tambahan 120% Damage Petir ke semua musuh yang masih hidup.',
		simDesc_ph = 'Kidlat na Dragon Slash: Pitong Sunod-sunod – Pumikit si Zenitsu, kumalma ng ilang saglit, at pinagsama ang lahat ng lakas ng kidlat sa kanyang katawan. Sa isang nakakasilaw na kidlat, siya ay sumugod na parang kulog, naglabas ng 7 sunod-sunod na malalakas na tebas, tumatama sa buong hanay ng kalaban. Nagdudulot ng 680% Pisikal na Pinsala at Ultimate Lightning Damage.\n#F10#\n#F40##L10# Dragon Thunder Strike:#L0# Tumatama sa lahat ng kalaban anuman ang kanilang posisyon, bawat target ay may 60% tsansa na ma-<Paralisado> sa loob ng 1 turn. Kung si Zenitsu ay nasa estado ng <Battle Sleep>, tumataas ng 30% ang lahat ng skill damage, at hindi maaaring ma-interrupt ng mga kontrol na epekto. Kapag nakapatay ng kahit 1 kalaban, na-a-activate ang Thunder Dragon Afterimage, na nagdudulot ng karagdagang 120% Lightning Damage sa lahat ng natitirang kalaban.',
		simDesc_ma = 'Naga Petir Sekilas: Tujuh Tebasan – Zenitsu memejam mata, menenangkan diri seketika, lalu menyalurkan semua kuasa petir ke dalam tubuhnya. Dalam kilauan cahaya, dia meluru ke hadapan seperti halilintar, melepaskan 7 tebasan berturut-turut yang dahsyat, mengenai keseluruhan formasi musuh. Memberikan 680% Kerosakan Fizikal dan Kerosakan Petir Ultimatum.\n#F10#\n#F40##L10# Serangan Naga Petir:#L0# Mengenai semua musuh tanpa mengira posisi, setiap sasaran mempunyai 60% peluang untuk terkena <Lumpuh> selama 1 giliran. Jika Zenitsu berada dalam status <Tidur Pertempuran>, semua kerosakan kemahiran meningkat 30%, dan kemahiran tidak boleh diganggu oleh kesan kawalan. Jika sekurang-kurangnya 1 musuh ditewaskan, Bayangan Naga Petir akan diaktifkan, memberikan tambahan 120% Kerosakan Petir kepada semua musuh yang masih hidup.',
		simDesc = 'Thunder Dragon Flash: Sevenfold Slash – Zenitsu closes his eyes, calming his mind for a moment, channeling all lightning power into his body. In a blinding flash, he dashes forward like a thunderbolt, unleashing 7 devastating consecutive slashes, striking the entire enemy formation. Deals 680% Physical Damage and Ultimate Lightning Damage.\n#F10#\n#F40##L10# Thunder Dragon Strike:#L0# Hits all enemies regardless of position, with each target having a 60% chance to be <Paralyzed> for 1 turn. If Zenitsu is in <Battle Sleep>, all skill damage is increased by 30%, and the skill cannot be interrupted by control effects. If at least 1 enemy is defeated, Thunder Dragon Afterimage is activated, dealing an additional 120% Lightning Damage to all surviving enemies.',
		starEffect = __data_t__starEffect[8006003],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng bổ sung:Đảo Ngược Dòng Chảy #L0# Khi Lôi Long Nhất Tức: Thất Liên Trảm được kích hoạt dưới trạng thái <Lôi Hóa> và gây kỹ năng chí mạng, sẽ tạo hiệu ứng <Đảo Ngược Dòng Chảy>: Giảm 20% tốc độ hồi phục năng lượng của toàn bộ kẻ địch trong 2 lượt (bao gồm cả hồi phục chủ động, bị động và theo lượt). Hiệu ứng này không thể cộng dồn nhưng có thể làm mới thời gian hiệu lực khi tái kích hoạt.',
		starEffectDesc = 'Additional Effect: Flow Reversal #L0# When Thunder Dragon One Breath: Seven Consecutive Slashes is activated under <Thunder Transformation> and lands a critical skill hit, it triggers the <Flow Reversal> effect: Reduces all enemies’ energy recovery rate by 20% for 2 turns (including active, passive, and per-turn recovery). This effect cannot stack but can be refreshed when reactivated.',
		starEffectDesc_en = 'Additional Effect: Flow Reversal #L0# When Thunder Dragon One Breath: Seven Consecutive Slashes is activated under <Thunder Transformation> and lands a critical skill hit, it triggers the <Flow Reversal> effect: Reduces all enemies’ energy recovery rate by 20% for 2 turns (including active, passive, and per-turn recovery). This effect cannot stack but can be refreshed when reactivated.',
		starEffectDesc_th = 'เอฟเฟกต์เสริม: ย้อนกระแส #L0# เมื่อ Thunder Dragon One Breath: Seven Consecutive Slashes ถูกใช้งานภายใต้สถานะ <Thunder Transformation> และสร้างคริติคอลสกิล จะก่อให้เกิดเอฟเฟกต์ <ย้อนกระแส>: ลดอัตราการฟื้นฟูพลังงานของศัตรูทั้งหมดลง 20% เป็นเวลา 2 เทิร์น (รวมถึงการฟื้นฟูแบบแอคทีฟ พาสซีฟ และการฟื้นฟูต่อเทิร์น) เอฟเฟกต์นี้ไม่สามารถซ้อนทับได้ แต่สามารถรีเฟรชระยะเวลาได้หากถูกกระตุ้นอีกครั้ง',
		starEffectDesc_in = 'Efek Tambahan: Arus Terbalik #L0# Saat Thunder Dragon One Breath: Seven Consecutive Slashes diaktifkan dalam status <Thunder Transformation> dan menghasilkan serangan skill kritis, akan memicu efek <Arus Terbalik>: Mengurangi laju pemulihan energi seluruh musuh sebesar 20% selama 2 giliran (termasuk pemulihan aktif, pasif, dan per giliran). Efek ini tidak dapat ditumpuk tetapi dapat diperbarui durasinya saat diaktifkan kembali.',
		starEffectDesc_ph = 'Karagdagang Epekto: Pagbaligtad ng Agos #L0# Kapag na-activate ang Thunder Dragon One Breath: Seven Consecutive Slashes sa ilalim ng <Thunder Transformation> at tumama bilang critical skill, magti-trigger ito ng <Pagbaligtad ng Agos>: Binabawasan ng 20% ang bilis ng energy recovery ng lahat ng kalaban sa loob ng 2 turn (kasama ang active, passive, at per-turn recovery). Ang epektong ito ay hindi puwedeng ma-stack ngunit maaaring ma-refresh ang duration kapag muling na-activate.',
		starEffectDesc_ma = 'Kesan Tambahan: Songsangan Aliran #L0# Apabila Thunder Dragon One Breath: Seven Consecutive Slashes diaktifkan dalam status <Thunder Transformation> dan menghasilkan critical skill, ia akan mencetuskan kesan <Songsangan Aliran>: Mengurangkan kadar pemulihan tenaga semua musuh sebanyak 20% selama 2 giliran (termasuk pemulihan aktif, pasif, dan setiap giliran). Kesan ini tidak boleh ditindih tetapi boleh diperbaharui tempoh berlakunya apabila diaktifkan semula.',
		zawakeEffect = __data_t__zawakeEffect[8006003],
		-- {79003}
		zawakeEffectDesc = 'Zenitsu closes his eyes, focuses for 1 second, channels all his lightning power into his body, then dashes forward like a flash of lightning, unleashing 7 consecutive powerful slashes that pierce enemy lines. Deals: #C0x3D8A99#680% Physical Damage, #C0xF13B54#+$(skillLevel*490)$ Ultimate Lightning Damage, dealing AoE damage to all enemies hit.',
		zawakeEffectDesc_en = 'Zenitsu closes his eyes, focuses for 1 second, channels all his lightning power into his body, then dashes forward like a flash of lightning, unleashing 7 consecutive powerful slashes that pierce enemy lines. Deals: #C0x3D8A99#680% Physical Damage, #C0xF13B54#+$(skillLevel*490)$ Ultimate Lightning Damage, dealing AoE damage to all enemies hit.',
		zawakeEffectDesc_th = 'Zenitsu หลับตา ตั้งสมาธิ 1 วินาที รวมพลังสายฟ้าทั้งหมดเข้าร่าง จากนั้นพุ่งไปข้างหน้าเหมือนฟ้าผ่า ปล่อย 7 ฟันดาบต่อเนื่องที่ทรงพลัง ทะลุแนวศัตรู สร้างความเสียหาย: #C0x3D8A99#680% กายภาพ, #C0xF13B54#+$(skillLevel*490)$ ความเสียหายสายฟ้าสุดยอด สร้างความเสียหายแบบ AoE ให้กับศัตรูทั้งหมดที่โดน',
		zawakeEffectDesc_in = 'Zenitsu menutup mata, fokus selama 1 detik, menyalurkan seluruh kekuatan petir ke tubuhnya, kemudian melesat ke depan seperti kilat, melepaskan 7 tebasan berturut-turut yang sangat kuat menembus barisan musuh. Memberikan: #C0x3D8A99#680% Damage Fisik, #C0xF13B54#+$(skillLevel*490)$ Damage Petir Ultimate, memberikan damage AoE ke semua musuh yang terkena.',
		zawakeEffectDesc_ph = 'Zenitsu pumikit, nag-concentrate ng 1 segundo, pinapadaloy ang lahat ng lakas ng kidlat sa kanyang katawan, pagkatapos ay sumugod pasulong tulad ng kidlat, naglabas ng 7 sunod-sunod na malalakas na hiwa na tumatagos sa linya ng kalaban. Nagdudulot ng: #C0x3D8A99#680% Physical Damage, #C0xF13B54#+$(skillLevel*490)$ Ultimate Lightning Damage, nagdudulot ng AoE damage sa lahat ng natamaan.',
		zawakeEffectDesc_ma = 'Zenitsu menutup mata, menenangkan diri selama 1 saat, menyalurkan semua tenaga petir ke tubuhnya, kemudian meluncur ke hadapan seperti kilat, melepaskan 7 serangan berturut-turut yang sangat kuat menembusi barisan musuh. Memberikan: #C0x3D8A99#680% Damage Fizikal, #C0xF13B54#+$(skillLevel*490)$ Ultimate Damage Petir, memberikan damage AoE kepada semua musuh yang terkena.',
		zawakeEffectDesc_vn = 'Zenitsu nhắm mắt, tĩnh tâm trong 1 giây, dồn toàn bộ sức mạnh sấm sét vào cơ thể, sau đó lao vụt về phía trước như tia chớp, tung ra 7 nhát chém liên hoàn cực mạnh, xuyên phá hàng ngũ địch. Gây: #C0x3D8A99#680% Sát Thương Vật Lý, #C0xF13B54#+$(skillLevel490)$ sát thương sét tuyệt kỹ, Gây sát thương diện rộng lên toàn bộ kẻ địch trúng phải.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Executes 7 consecutive powerful lightning slashes, dealing AoE damage and lightning damage based on skill level.',
		zawakeSimpleDesc_en = 'Executes 7 consecutive powerful lightning slashes, dealing AoE damage and lightning damage based on skill level.',
		zawakeSimpleDesc_th = 'ฟันสายฟ้า 7 ครั้งต่อเนื่องรุนแรง สร้างความเสียหายวงกว้างและความเสียหายสายฟ้าตามระดับสกิล',
		zawakeSimpleDesc_in = 'Melancarkan 7 serangan pedang petir beruntun yang sangat kuat, memberikan damage area dan kerusakan petir sesuai level skill.',
		zawakeSimpleDesc_ph = 'Nagpapalabas ng 7 magkakasunod na malakas na lightning slash, na nagdudulot ng AoE damage at lightning damage batay sa skill level.',
		zawakeSimpleDesc_ma = 'Melancarkan 7 serangan pedang elektrik berturut-turut yang sangat kuat, memberikan kerosakan kawasan dan kerosakan elektrik mengikut tahap kemahiran.',
		zawakeSimpleDesc_vn = 'Tung 7 nhát chém sét liên hoàn cực mạnh, gây sát thương diện rộng và sát thương sét theo cấp kỹ năng.',
