	[8006004] = {
		id = 8006004,
		skillName_vn = 'Ngủ Chiến Đấu',
		skillName_en = 'Combat Sleep',
		skillName_th = 'การนอนสู้รบ',
		skillName_in = 'Tidur Tempur',
		skillName_ph = 'Combat Sleep',
		skillName_ma = 'Tidur Pertempuran',
		skillName = 'Ngủ Chiến Đấu',
		describe_vn = 'Ngủ Chiến Đấu – Zenitsu rơi vào trạng thái ngủ sâu kỳ lạ, trong đó bản năng chiến đấu của anh đạt đến đỉnh cao. Khi kích hoạt, giải phóng hào quang rực sáng, tăng mạnh năng lực chiến đấu 20%: Tăng tốc độ hành động 20%, Tăng #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Kháng Bạo Lực (giảm xác suất bị đánh chí mạng và sát thương bạo kích).\n#F10#\n#F40##L10# Bản Năng Tia Chớp: #L0# Trong trạng thái Ngủ Chiến Đấu, các kỹ năng <Lôi hệ> được cường hóa, bỏ qua 15% kháng phép của mục tiêu, đồng thời miễn nhiễm với hiệu ứng làm chậm và câm lặng. Trạng thái kéo dài 2 lượt.',
		describe_en = 'Combat Sleep – Zenitsu enters a strange deep sleep state, in which his combat instincts reach their peak. Upon activation, a radiant aura is released, significantly boosting combat capability by 20%: Increases action speed by 20%, and increases #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Critical Resistance (reduces chance of receiving critical hits and critical damage). \n#F10#\n#F40##L10# Lightning Instinct: #L0# While in Combat Sleep, all <Thunder-type> skills are enhanced, ignoring 15% of the target’s magic resistance, and the user becomes immune to slow and silence effects. State lasts for 2 turns.',
		describe_th = 'Combat Sleep – Zenitsu เข้าสู่สถานะหลับลึกประหลาด ซึ่งสัญชาตญาณการต่อสู้ของเขาถึงจุดสูงสุด เมื่อเปิดใช้งาน จะปล่อยออร่าเจิดจ้า เพิ่มความสามารถในการต่อสู้ 20%: เพิ่มความเร็วในการกระทำ 20%, เพิ่ม #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# การต้านคริติคอล (ลดโอกาสถูกโจมตีคริติคอลและความเสียหายคริติคอล). \n#F10#\n#F40##L10# Lightning Instinct: #L0# ในสถานะ Combat Sleep สกิล <Thunder-type> ทั้งหมดจะถูกเสริมพลัง ข้ามการต้านเวท 15% ของเป้าหมาย และจะไม่ถูกผลกระทบจากสกิลชะลอหรือเงียบ สถานะคงอยู่ 2 เทิร์น',
		describe_in = 'Combat Sleep – Zenitsu memasuki keadaan tidur nyenyak yang aneh, di mana insting bertarungnya mencapai puncak. Saat diaktifkan, memancarkan aura bercahaya, meningkatkan kemampuan bertarung sebesar 20%: Meningkatkan kecepatan aksi 20%, dan meningkatkan #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Resistensi Kritikal (mengurangi kemungkinan terkena serangan kritikal dan damage kritikal). \n#F10#\n#F40##L10# Lightning Instinct: #L0# Dalam keadaan Combat Sleep, semua skill <Thunder-type> ditingkatkan, mengabaikan 15% resistensi sihir target, dan pengguna kebal terhadap efek slow dan silence. Keadaan berlangsung selama 2 giliran.',
		describe_ph = 'Combat Sleep – Zenitsu ay pumapasok sa kakaibang malalim na estado ng pagtulog, kung saan umaabot sa rurok ang kanyang instincts sa pakikipaglaban. Kapag na-activate, nagpapalabas ng maningning na aura, na malakas na nagpapalakas ng kakayahan sa labanan ng 20%: Taasan ang bilis ng pagkilos ng 20%, at taasan ang #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Kritikal na Resistencia (binabawasan ang posibilidad na makatanggap ng critical hit at critical damage). \n#F10#\n#F40##L10# Lightning Instinct: #L0# Sa estado ng Combat Sleep, lahat ng <Thunder-type> skills ay pinalakas, nilalampasan ang 15% magic resistance ng target, at ang gumagamit ay immune sa slow at silence effects. Tumatagal ang estado ng 2 turn.',
		describe_ma = 'Combat Sleep – Zenitsu memasuki keadaan tidur nyenyak yang aneh, di mana naluri pertarungannya mencapai kemuncak. Apabila diaktifkan, aura bersinar dilepaskan, meningkatkan keupayaan pertarungan sebanyak 20%: Meningkatkan kelajuan tindakan 20%, dan meningkatkan #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Rintangan Kritikal (mengurangkan kemungkinan terkena serangan kritikal dan kerosakan kritikal). \n#F10#\n#F40##L10# Lightning Instinct: #L0# Dalam keadaan Combat Sleep, semua kemahiran <Thunder-type> dipertingkatkan, mengabaikan 15% rintangan sihir sasaran, dan pengguna menjadi kebal terhadap efek perlahan dan senyap. Keadaan berlangsung selama 2 giliran.',
		describe = 'Combat Sleep – Zenitsu enters a strange deep sleep state, in which his combat instincts reach their peak. Upon activation, a radiant aura is released, significantly boosting combat capability by 20%: Increases action speed by 20%, and increases #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Critical Resistance (reduces chance of receiving critical hits and critical damage). \n#F10#\n#F40##L10# Lightning Instinct: #L0# While in Combat Sleep, all <Thunder-type> skills are enhanced, ignoring 15% of the target’s magic resistance, and the user becomes immune to slow and silence effects. State lasts for 2 turns.',
		simDesc_vn = 'Ngủ Chiến Đấu – Zenitsu rơi vào trạng thái ngủ sâu kỳ lạ, trong đó bản năng chiến đấu của anh đạt đến đỉnh cao. Khi kích hoạt, giải phóng hào quang rực sáng, tăng mạnh năng lực chiến đấu 20%: Tăng tốc độ hành động 20%, Tăng #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Kháng Bạo Lực (giảm xác suất bị đánh chí mạng và sát thương bạo kích).\n#F10#\n#F40##L10# Bản Năng Tia Chớp: #L0# Trong trạng thái Ngủ Chiến Đấu, các kỹ năng <Lôi hệ> được cường hóa, bỏ qua 15% kháng phép của mục tiêu, đồng thời miễn nhiễm với hiệu ứng làm chậm và câm lặng. Trạng thái kéo dài 2 lượt.',
		simDesc_en = 'Battle Sleep – Zenitsu falls into a strange deep slumber where his combat instincts reach their peak. Upon activation, he radiates a blazing aura, boosting combat power by 20%: +20% Action Speed, +#C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Critical Resistance (reduces chance of receiving critical hits and crit damage).\n#F10#\n#F40##L10# Lightning Instinct:#L0# While in Battle Sleep, all <Lightning>-type skills are enhanced, ignoring 15% of the target’s magic resistance, while gaining immunity to Slow and Silence effects. Lasts for 2 turns.',
		simDesc_th = 'หลับต่อสู้ – เซนิตสึเข้าสู่การหลับลึกประหลาด ที่สัญชาตญาณการต่อสู้ของเขาพุ่งถึงขีดสุด เมื่อเปิดใช้งาน จะปล่อยออร่ารุ่งโรจน์ เพิ่มพลังการต่อสู้ 20%: ความเร็วการกระทำ +20%, +#C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# ต้านคริติคอล (ลดโอกาสโดนคริติคอลและความเสียหายคริติคอล).\n#F10#\n#F40##L10# สัญชาตญาณสายฟ้า:#L0# ขณะอยู่ในสถานะหลับต่อสู้ สกิลประเภท <สายฟ้า> จะถูกเสริมพลัง ทะลวงการต้านเวทของเป้าหมาย 15% และภูมิคุ้มกันต่อสถานะ ช้า และ ปิดปาก ระยะเวลา 2 เทิร์น',
		simDesc_in = 'Tidur Tempur – Zenitsu jatuh ke dalam tidur nyenyak aneh di mana insting bertarungnya mencapai puncak. Saat diaktifkan, ia memancarkan aura bercahaya, meningkatkan kekuatan tempur sebesar 20%: +20% Kecepatan Aksi, +#C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Resistensi Kritikal (mengurangi peluang terkena critical hit dan damage kritikal).\n#F10#\n#F40##L10# Insting Petir:#L0# Dalam keadaan Tidur Tempur, semua skill <Petir> diperkuat, mengabaikan 15% resistensi sihir target, serta kebal terhadap efek Slow dan Silence. Bertahan selama 2 giliran.',
		simDesc_ph = 'Battle Sleep – Nahuhulog si Zenitsu sa isang kakaibang malalim na tulog kung saan ang kanyang instinct sa pakikipaglaban ay umaabot sa sukdulan. Kapag na-activate, naglalabas siya ng makinang na aura, nagpapalakas ng lakas ng laban ng 20%: +20% Bilis ng Aksyon, +#C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Resistensya sa Critical (binabawasan ang tsansa na ma-critical hit at bawas damage mula sa critical).\n#F10#\n#F40##L10# Instinct ng Kidlat:#L0# Habang nasa Battle Sleep, ang lahat ng <Lightning>-type na skill ay pinalalakas, binabalewala ang 15% ng magic resistance ng kalaban, at immune sa epekto ng Slow at Silence. Tumatagal ng 2 turn.',
		simDesc_ma = 'Tidur Pertempuran – Zenitsu jatuh ke dalam tidur nyenyak yang aneh di mana naluri bertarungnya mencapai tahap tertinggi. Apabila diaktifkan, dia melepaskan aura bercahaya, meningkatkan kuasa tempur sebanyak 20%: +20% Kelajuan Tindakan, +#C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Rintangan Kritikal (mengurangkan peluang terkena serangan kritikal dan kerosakan kritikal).\n#F10#\n#F40##L10# Naluri Petir:#L0# Semasa dalam keadaan Tidur Pertempuran, semua kemahiran jenis <Petir> dipertingkatkan, mengabaikan 15% rintangan sihir sasaran, serta kebal terhadap kesan Perlahan dan Senyap. Bertahan selama 2 giliran.',
		simDesc = 'Battle Sleep – Zenitsu falls into a strange deep slumber where his combat instincts reach their peak. Upon activation, he radiates a blazing aura, boosting combat power by 20%: +20% Action Speed, +#C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Critical Resistance (reduces chance of receiving critical hits and crit damage).\n#F10#\n#F40##L10# Lightning Instinct:#L0# While in Battle Sleep, all <Lightning>-type skills are enhanced, ignoring 15% of the target’s magic resistance, while gaining immunity to Slow and Silence effects. Lasts for 2 turns.',
		starEffect = __data_t__starEffect[8006004],
		-- {8}
		starEffectDesc_vn = 'Miễn Nhiễm Khống Chế Tâm Lý: #L0# Trong trạng thái <Ngủ Chiến Đấu>, Zenitsu miễn nhiễm với các hiệu ứng khống chế tâm lý: <Hoảng Sợ> <Rung Động> <Lôi Cuốn> (Không bị làm gián đoạn hành động hoặc thay đổi mục tiêu do các hiệu ứng này). Tăng Tốc Độ và Sát Thương: Khi thực hiện các kĩ năng, Zenitsu được: Tăng 25% tốc độ ra đòn (ưu tiên hành động cao hơn) và Tăng 20% sát thương.',
		starEffectDesc = 'Psychological Control Immunity: #L0# While in <Combat Sleep> state, Zenitsu is immune to psychological control effects: <Fear> <Shaken> <Allure> (Not interrupted or forced to change targets by these effects). Speed and Damage Boost: When using skills, Zenitsu gains: +25% attack speed (higher action priority) and +20% damage.',
		starEffectDesc_en = 'Psychological Control Immunity: #L0# While in <Combat Sleep> state, Zenitsu is immune to psychological control effects: <Fear> <Shaken> <Allure> (Not interrupted or forced to change targets by these effects). Speed and Damage Boost: When using skills, Zenitsu gains: +25% attack speed (higher action priority) and +20% damage.',
		starEffectDesc_th = 'ภูมิคุ้มกันการควบคุมทางจิต: #L0# ขณะอยู่ในสถานะ <Combat Sleep> Zenitsu จะต้านทานผลควบคุมทางจิตทั้งหมด: <Fear> <Shaken> <Allure> (จะไม่ถูกขัดจังหวะการกระทำหรือเปลี่ยนเป้าหมายจากผลเหล่านี้) เพิ่มความเร็วและความเสียหาย: เมื่อใช้สกิล Zenitsu จะได้รับ +25% ความเร็วการโจมตี (ลำดับการกระทำสูงกว่า) และ +20% ความเสียหาย',
		starEffectDesc_in = 'Kebal Kontrol Psikologis: #L0# Dalam status <Combat Sleep>, Zenitsu kebal terhadap efek kontrol psikologis: <Fear> <Shaken> <Allure> (Tidak terganggu atau dipaksa mengubah target oleh efek ini). Peningkatan Kecepatan dan Damage: Saat menggunakan skill, Zenitsu mendapatkan: +25% kecepatan serangan (prioritas aksi lebih tinggi) dan +20% damage.',
		starEffectDesc_ph = 'Imyun sa Psychological Control: #L0# Sa estado ng <Combat Sleep>, immune si Zenitsu sa mga psychological control effects: <Fear> <Shaken> <Allure> (Hindi maaantala ang aksyon o mapipilitang magpalit ng target dahil sa mga effect na ito). Bilis at Damage Bonus: Kapag gumagamit ng skill, nakakatanggap si Zenitsu ng +25% attack speed (mas mataas na action priority) at +20% damage.',
		starEffectDesc_ma = 'Kebal Kawalan Psikologi: #L0# Dalam status <Combat Sleep>, Zenitsu kebal daripada kesan kawalan psikologi: <Fear> <Shaken> <Allure> (Tidak terganggu tindakannya atau dipaksa menukar sasaran oleh kesan ini). Peningkatan Kelajuan dan Damage: Apabila menggunakan skill, Zenitsu memperoleh: +25% kelajuan serangan (keutamaan tindakan lebih tinggi) dan +20% damage.',
		zawakeEffect = __data_t__zawakeEffect[8006004],
		-- {79004}
		zawakeEffectDesc = 'Activate Radiant Aura: Increases speed and #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Resistance to Critical Hits.',
		zawakeEffectDesc_en = 'Activate Radiant Aura: Increases speed and #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Resistance to Critical Hits.',
		zawakeEffectDesc_th = 'เปิดใช้งาน Aura สว่างไสว: เพิ่มความเร็วและ #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# ต้านคริติคอล',
		zawakeEffectDesc_in = 'Aktifkan Aura Bercahaya: Meningkatkan kecepatan dan #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Resistensi terhadap Serangan Kritis',
		zawakeEffectDesc_ph = 'Activate Radiant Aura: Tumataas ang bilis at #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Resistance sa Critical Hits',
		zawakeEffectDesc_ma = 'Aktifkan Aura Bercahaya: Meningkatkan kelajuan dan #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# Rintangan terhadap Serangan Kritikal',
		zawakeEffectDesc_vn = 'Kích hoạt hào quang rực sáng: Tăng tốc độ và #C0x5c9970#$(10 + (skillLevel - 1) * 0.05)$%#C0x5B545B# kháng bạo lực.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Activates aura, boosting speed and critical resistance according to skill level',
		zawakeSimpleDesc_en = 'Activates aura, boosting speed and critical resistance according to skill level',
		zawakeSimpleDesc_th = 'เปิดแสงออร่า เพิ่มความเร็วและต้านทานคริติคอลตามระดับสกิล',
		zawakeSimpleDesc_in = 'Mengaktifkan aura, meningkatkan kecepatan dan resistensi kritis sesuai level skill',
		zawakeSimpleDesc_ph = 'Nag-a-activate ng aura, pinapataas ang bilis at critical resistance ayon sa skill level',
		zawakeSimpleDesc_ma = 'Mengaktifkan aura, meningkatkan kelajuan dan rintangan kritikal mengikut tahap kemahiran',
		zawakeSimpleDesc_vn = 'Kích hoạt hào quang, tăng tốc độ và kháng bạo lực theo cấp kỹ năng',
		iconRes = 'battle/skill_icon/skill_80064.png',
