	[9080071] = {
		id = 9080071,
		skillName_vn = 'Phá Diệt Sát: Huỷ diệt thức',
		skillName_en = 'Destruction Slash: Annihilation Form',
		skillName_th = 'ฟันทำลาย: รูปแบบทำลายล้าง',
		skillName_in = 'Serangan Penghancuran: Bentuk Annihilation',
		skillName_ph = 'Destruction Slash: Annihilation Form',
		skillName_ma = 'Serangan Pemusnah: Bentuk Pemusnahan',
		skillName = 'Phá Diệt Sát: Huỷ diệt thức',
		describe_vn = 'Akaza dồn toàn bộ sức mạnh vào một cú đấm tấn công mục tiêu đơn lẻ của kẻ địch, gây #C0xE69900#150% Công Vật Lý#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, tăng 20% Công Vật Lý ban đầu và giảm sát thương bản thân nhận vào 10%, kéo dài 2 lượt; nếu sát thương lần này vượt quá 10% giới hạn máu của mục tiêu, tăng 10% tốc độ tấn công cho Akaza, kéo dài 2 lượt;\n <Huyết Quỷ> Trong trạng thái Huyết Quỷ kĩ năng Huỷ diệt thức sẽ trở thành <Phá Diệt Sát: Tận Diệt thức>: gây thêm sát thương lên mục tiêu tương đương với 5% máu của chúng, hiệu quả cộng dồn với số tầng của <Cuồng Chiến>',
		describe_en = 'Akaza channels all his strength into a single strike targeting one enemy, dealing #C0xE69900#150% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#, increases base Physical Attack by 20% and reduces damage received by 10% for 2 turns; if this damage exceeds 10% of the target\'s max HP, Akaza gains 10% attack speed for 2 turns;\n <Blood Demon> In Blood Demon state, the Destruction skill transforms into <Destruction Strike: Total Destruction>: dealing additional damage equal to 5% of the target\'s HP, stacking with the levels of <Frenzy>',
		describe_th = 'Akaza รวมพลังทั้งหมดเข้าในการโจมตีครั้งเดียวต่อศัตรูเป้าหมายเดียว สร้าง #C0xE69900#150% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B#, เพิ่มพลังโจมตีทางกายภาพเริ่มต้น 20% และลดความเสียหายที่ได้รับ 10% เป็นเวลา 2 ตา; หากความเสียหายครั้งนี้เกิน 10% ของ HP สูงสุดของเป้าหมาย Akaza จะได้รับความเร็วโจมตีเพิ่ม 10% เป็นเวลา 2 ตา;\n <อสูรโลหิต> ในสถานะอสูรโลหิต สกิลทำลายล้างจะเปลี่ยนเป็น <การทำลายล้าง: ทำลายล้างสุดขีด>: สร้างความเสียหายเพิ่มเติมเท่ากับ 5% ของ HP ของเป้าหมาย สามารถสะสมตามระดับของ <คลั่งสงคราม>',
		describe_in = 'Akaza menyalurkan seluruh kekuatannya ke dalam satu pukulan yang menyerang satu musuh, menyebabkan #C0xE69900#150% Serangan Fisik#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, meningkatkan Serangan Fisik dasar sebesar 20% dan mengurangi damage diterima sebesar 10% selama 2 giliran; jika damage ini melebihi 10% dari HP maksimum target, Akaza mendapatkan 10% kecepatan serangan selama 2 giliran;\n <Iblis Darah> Dalam status Iblis Darah, skill Destruction berubah menjadi <Serangan Destruction: Total Destruction>: memberikan damage tambahan sebesar 5% dari HP target, efek ini menumpuk sesuai level <Frenzy>',
		describe_ph = 'Akaza inilalagay ang lahat ng kanyang lakas sa isang suntok na tumatarget sa isang kalaban, na nagdudulot ng #C0xE69900#150% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#, pinapataas ang base Physical Attack ng 20% at binabawasan ang damage na natatanggap ng 10% sa loob ng 2 turn; kung ang damage na ito ay lumampas sa 10% ng max HP ng target, nakakakuha si Akaza ng 10% attack speed sa loob ng 2 turn;\n <Blood Demon> Sa Blood Demon state, nagbabago ang Destruction skill sa <Destruction Strike: Total Destruction>: nagdudulot ng karagdagang damage na katumbas ng 5% ng HP ng target, na puwedeng mag-stack sa mga level ng <Frenzy>',
		describe_ma = 'Akaza menyalurkan semua kekuatannya ke dalam satu pukulan yang menyerang satu musuh, memberikan #C0xE69900#150% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Kerusakan Fizikal#C0x5B545B#, meningkatkan Serangan Fizikal asas sebanyak 20% dan mengurangkan damage diterima sebanyak 10% selama 2 pusingan; jika damage ini melebihi 10% daripada HP maksimum sasaran, Akaza mendapat 10% kelajuan serangan selama 2 pusingan;\n <Iblis Darah> Dalam status Iblis Darah, kemahiran Destruction bertukar menjadi <Serangan Destruction: Kehancuran Total>: memberikan damage tambahan bersamaan 5% HP sasaran, berkesan bertindih dengan tahap <Frenzy>',
		describe = 'Akaza channels all his strength into a single strike targeting one enemy, dealing #C0xE69900#150% Physical Attack#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#Physical Damage#C0x5B545B#, increases base Physical Attack by 20% and reduces damage received by 10% for 2 turns; if this damage exceeds 10% of the target\'s max HP, Akaza gains 10% attack speed for 2 turns;\n <Blood Demon> In Blood Demon state, the Destruction skill transforms into <Destruction Strike: Total Destruction>: dealing additional damage equal to 5% of the target\'s HP, stacking with the levels of <Frenzy>',
		simDesc_vn = 'Akaza dồn toàn bộ sức mạnh vào một cú đấm tấn công mục tiêu đơn lẻ của kẻ địch, tăng 20% Công Vật Lý ban đầu và giảm sát thương bản thân nhận vào 10%, kéo dài 2 lượt; nếu sát thương lần này vượt quá 10% giới hạn máu của mục tiêu, tăng 10% tốc độ tấn công cho Akaza, kéo dài 2 lượt;  Khi có hiệu ứng <Huyết quỷ>, hiệu quả kĩ năng sẽ được tăng cường mạnh mẽ.',
		simDesc_en = 'Akaza channels all his strength into a single punch targeting one enemy, increasing his base Physical Attack by 20% and reducing damage taken by 10% for 2 turns. If this attack deals more than 10% of the target’s max HP, Akaza gains +10% Attack Speed for 2 turns. When under the <Demon Blood> effect, the skill’s power is greatly enhanced.',
		simDesc_th = 'อาคาซะรวบรวมพลังทั้งหมดปล่อยหมัดโจมตีศัตรูเป้าหมายเดียว เพิ่มพลังโจมตีกายภาพพื้นฐาน 20% และลดความเสียหายที่ได้รับ 10% เป็นเวลา 2 เทิร์น หากดาเมจครั้งนี้เกิน 10% ของ HP สูงสุดของเป้าหมาย อาคาซะจะได้รับความเร็วโจมตี +10% เป็นเวลา 2 เทิร์น เมื่ออยู่ภายใต้เอฟเฟกต์ <โลหิตอสูร> พลังของสกิลนี้จะถูกเสริมอย่างรุนแรง',
		simDesc_in = 'Akaza mengerahkan seluruh kekuatannya dalam satu pukulan ke musuh tunggal, meningkatkan Serangan Fisik dasar sebesar 20% dan mengurangi damage yang diterima sebesar 10% selama 2 giliran. Jika serangan ini memberikan damage lebih dari 10% HP maksimum target, Akaza mendapatkan +10% Kecepatan Serangan selama 2 giliran. Saat berada dalam efek <Darah Iblis>, kekuatan skill ini diperkuat secara signifikan.',
		simDesc_ph = 'Itinutok ni Akaza ang lahat ng kanyang lakas sa isang suntok laban sa isang kalaban, tumataas ng 20% ang base Physical Attack at nababawasan ng 10% ang damage na natatanggap sa loob ng 2 turn. Kung ang atake ay lumampas sa 10% ng max HP ng target, nakakakuha si Akaza ng +10% Attack Speed sa loob ng 2 turn. Kapag nasa ilalim ng <Demon Blood>, mas lalo pang tumitindi ang epekto ng skill na ito.',
		simDesc_ma = 'Akaza menyalurkan semua kekuatannya dalam satu tumbukan ke arah musuh tunggal, meningkatkan Serangan Fizikal asas sebanyak 20% dan mengurangkan kerosakan yang diterima sebanyak 10% selama 2 giliran. Jika serangan ini melebihi 10% daripada HP maksimum sasaran, Akaza mendapat +10% Kelajuan Serangan selama 2 giliran. Apabila berada di bawah kesan <Darah Syaitan>, kuasa kemahiran ini akan dipertingkat dengan ketara.',
		simDesc = 'Akaza channels all his strength into a single punch targeting one enemy, increasing his base Physical Attack by 20% and reducing damage taken by 10% for 2 turns. If this attack deals more than 10% of the target’s max HP, Akaza gains +10% Attack Speed for 2 turns. When under the <Demon Blood> effect, the skill’s power is greatly enhanced.',
