	[9080072] = {
		id = 9080072,
		skillName_vn = 'Phá Diệt Sát: Tam liên sát',
		skillName_en = 'Destruction Slash: Triple Slash',
		skillName_th = 'ฟันทำลาย: ฟันสามครั้ง',
		skillName_in = 'Serangan Penghancuran: Triple Slash',
		skillName_ph = 'Destruction Slash: Triple Slash',
		skillName_ma = 'Serangan Pemusnah: Serangan Tiga Kali',
		skillName = 'Phá Diệt Sát: Tam liên sát',
		describe_vn = 'Akaza lao vào một mục tiêu, áp chế 3 lần gây #C0xE69900#300% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Sát Thương Vật Lý#C0x5B545B#, và giảm 20% sát thương nhận vào, kéo dài 2 lượt;  Akaza nhận hiệu ứng <Say Máu> dựa theo lượng sát thương gây ra trong đòn đánh này; \n#F10#\n#F40#  <Say máu>: Nếu sát thương lần này vượt quá 10% giới hạn máu của mục tiêu, tăng 20% tốc độ tấn công cho Akaza, kéo dài 3 lượt; nếu sát thương lần này vượt quá 20% giới hạn máu của mục tiêu, tăng 20% Công Vật Lý cho Akaza, kéo dài 3 lượt; nếu sát thương lần này vượt quá 30% giới hạn máu của mục tiêu, hồi lại cho Akaza 20% máu tối đa.\n <Huyết Quỷ> Trong trại thái bán Huyết quỷ kĩ năng này sẽ trở thành <Phá Diệt Sát: Cuồng huyết quyền>: gây thêm sát thương lên mục tiêu tương đương với 5% máu của chúng, hiệu quả cộng dồn với số tầng của <Cuồng Chiến>. Trong trạng thái huyết quỷ hoàn chỉnh kĩ năng sẽ phá huỷ thế thủ của đối thủ, giảm 20% Thủ vật lý của đối thủ, kéo dài 2 lượt, hiệu quả cộng dồn với số tầng của <Cuồng chiến>.',
		describe_en = 'Akaza charges at a target, striking 3 times dealing #C0xE69900#300% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, and reduces damage received by 20% for 2 turns; Akaza gains the <Blood Frenzy> effect based on the damage dealt in this attack; \n#F10#\n#F40# <Blood Frenzy>: If this damage exceeds 10% of the target\'s max HP, Akaza gains 20% attack speed for 3 turns; if it exceeds 20%, he gains 20% Physical Attack for 3 turns; if it exceeds 30%, Akaza recovers 20% of his max HP.\n <Blood Demon> In Semi-Blood Demon state, this skill transforms into <Destruction Strike: Frenzied Blood Fist>: dealing additional damage equal to 5% of the target\'s HP, stacking with <Frenzy> levels. In full Blood Demon state, the skill breaks the enemy’s guard, reducing their Physical Defense by 20% for 2 turns, stacking with <Frenzy> levels.',
		describe_th = 'Akaza พุ่งเข้าหาเป้าหมาย สังหาร 3 ครั้ง สร้าง #C0xE69900#300% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# และลดความเสียหายที่ได้รับลง 20% เป็นเวลา 2 ตา; Akaza ได้รับเอฟเฟกต์ <ความคลั่งเลือด> ขึ้นอยู่กับความเสียหายที่ทำในการโจมตีนี้; \n#F10#\n#F40# <ความคลั่งเลือด>: หากความเสียหายนี้เกิน 10% ของ HP สูงสุดเป้าหมาย Akaza จะได้รับความเร็วโจมตีเพิ่ม 20% เป็นเวลา 3 ตา; หากเกิน 20% เพิ่มพลังโจมตีทางกายภาพ 20% เป็นเวลา 3 ตา; หากเกิน 30% ฟื้นฟู HP สูงสุด 20% ของ Akaza.\n <อสูรโลหิต> ในสถานะกึ่งอสูรโลหิต สกิลนี้จะเปลี่ยนเป็น <การทำลายล้าง: หมัดเลือดคลั่ง>: สร้างความเสียหายเพิ่มเติมเท่ากับ 5% ของ HP ของเป้าหมาย สะสมกับระดับ <คลั่งสงคราม>. ในสถานะอสูรโลหิตเต็มรูปแบบ สกิลจะทำลายการป้องกันของศัตรู ลดการป้องกันทางกายภาพ 20% เป็นเวลา 2 ตา สะสมกับระดับ <คลั่งสงคราม>.',
		describe_in = 'Akaza menyerbu ke satu target, menyerang 3 kali menyebabkan #C0xE69900#300% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerusakan Fisik#C0x5B545B#, dan mengurangi damage diterima sebesar 20% selama 2 giliran; Akaza mendapatkan efek <Kegilaan Darah> berdasarkan damage yang diberikan dalam serangan ini; \n#F10#\n#F40# <Kegilaan Darah>: Jika damage ini melebihi 10% HP maksimum target, Akaza mendapatkan 20% kecepatan serangan selama 3 giliran; jika melebihi 20%, Akaza mendapatkan 20% Serangan Fisik selama 3 giliran; jika melebihi 30%, Akaza memulihkan 20% HP maksimum.\n <Iblis Darah> Dalam status Semi-Blood Demon, skill ini berubah menjadi <Serangan Destruction: Tinju Darah Gila>: memberikan damage tambahan sebesar 5% HP target, efek menumpuk dengan level <Frenzy>. Dalam status Blood Demon penuh, skill ini menghancurkan pertahanan musuh, mengurangi Pertahanan Fisik lawan 20% selama 2 giliran, menumpuk dengan level <Frenzy>.',
		describe_ph = 'Akaza sumugod sa isang target, pumalo ng 3 beses na nagdudulot ng #C0xE69900#300% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, at binabawasan ang damage na natatanggap ng 20% sa loob ng 2 turn; Akaza nakakakuha ng epekto ng <Blood Frenzy> batay sa damage na ginawa sa atake na ito; \n#F10#\n#F40# <Blood Frenzy>: Kung ang damage na ito ay lumampas sa 10% ng max HP ng target, Akaza nakakakuha ng 20% attack speed sa loob ng 3 turn; kung lumampas sa 20%, nakakakuha ng 20% Physical Attack sa loob ng 3 turn; kung lumampas sa 30%, nagpapagaling ng 20% ng max HP ni Akaza.\n <Blood Demon> Sa Semi-Blood Demon state, ang skill na ito ay nagiging <Destruction Strike: Frenzied Blood Fist>: nagdudulot ng karagdagang damage na katumbas ng 5% ng HP ng target, nag-stack sa mga level ng <Frenzy>. Sa full Blood Demon state, ang skill ay sumisira sa depensa ng kalaban, binabawasan ang Physical Defense ng kalaban ng 20% sa loob ng 2 turn, nag-stack sa mga level ng <Frenzy>.',
		describe_ma = 'Akaza menyerbu ke satu sasaran, menyerang 3 kali memberikan #C0xE69900#300% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Kerusakan Fizikal#C0x5B545B#, dan mengurangkan damage diterima sebanyak 20% selama 2 pusingan; Akaza menerima efek <Kegilaan Darah> berdasarkan damage yang diberikan dalam serangan ini; \n#F10#\n#F40# <Kegilaan Darah>: Jika damage ini melebihi 10% HP maksimum sasaran, Akaza mendapat 20% kelajuan serangan selama 3 pusingan; jika melebihi 20%, Akaza mendapat 20% Serangan Fizikal selama 3 pusingan; jika melebihi 30%, pulihkan 20% HP maksimum Akaza.\n <Iblis Darah> Dalam status Semi-Blood Demon, kemahiran ini bertukar menjadi <Serangan Destruction: Tinju Darah Gila>: memberikan damage tambahan bersamaan 5% HP sasaran, berkesan bertindih dengan tahap <Frenzy>. Dalam status Blood Demon penuh, kemahiran ini memusnahkan pertahanan musuh, mengurangkan Pertahanan Fizikal musuh sebanyak 20% selama 2 pusingan, berkesan bertindih dengan tahap <Frenzy>.',
		describe = 'Akaza charges at a target, striking 3 times dealing #C0xE69900#300% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#Physical Damage#C0x5B545B#, and reduces damage received by 20% for 2 turns; Akaza gains the <Blood Frenzy> effect based on the damage dealt in this attack; \n#F10#\n#F40# <Blood Frenzy>: If this damage exceeds 10% of the target\'s max HP, Akaza gains 20% attack speed for 3 turns; if it exceeds 20%, he gains 20% Physical Attack for 3 turns; if it exceeds 30%, Akaza recovers 20% of his max HP.\n <Blood Demon> In Semi-Blood Demon state, this skill transforms into <Destruction Strike: Frenzied Blood Fist>: dealing additional damage equal to 5% of the target\'s HP, stacking with <Frenzy> levels. In full Blood Demon state, the skill breaks the enemy’s guard, reducing their Physical Defense by 20% for 2 turns, stacking with <Frenzy> levels.',
		simDesc_vn = 'Akaza lao vào một mục tiêu, áp chế 3 lần và giảm 20% sát thương nhận vào, kéo dài 2 lượt;  Akaza nhận hiệu ứng <Say Máu> dựa theo lượng sát thương gây ra trong đòn đánh này. Khi có hiệu ứng <Huyết quỷ>, hiệu quả kĩ năng sẽ được tăng cường mạnh mẽ.',
		simDesc_en = 'Akaza charges at a single target, suppressing 3 times and reducing damage taken by 20% for 2 turns. He gains the <Blood Frenzy> effect based on the damage dealt by this attack. When under the <Demon Blood> effect, the skill’s power is greatly enhanced.',
		simDesc_th = 'อาคาซะพุ่งเข้าใส่เป้าหมายหนึ่ง กดขี่โจมตี 3 ครั้ง และลดความเสียหายที่ได้รับลง 20% เป็นเวลา 2 เทิร์น อาคาซะได้รับเอฟเฟกต์ <คลั่งเลือด> ตามจำนวนดาเมจที่สร้างได้จากการโจมตีนี้ เมื่ออยู่ภายใต้เอฟเฟกต์ <โลหิตอสูร> พลังของสกิลนี้จะถูกเสริมอย่างรุนแรง',
		simDesc_in = 'Akaza menerjang ke satu target, menekan 3 kali dan mengurangi damage yang diterima sebesar 20% selama 2 giliran. Akaza mendapatkan efek <Amukan Darah> berdasarkan jumlah damage yang dihasilkan dari serangan ini. Saat berada dalam efek <Darah Iblis>, kekuatan skill ini diperkuat secara signifikan.',
		simDesc_ph = 'Sumalakay si Akaza sa isang target, nag-aapply ng 3 suppression hits at nababawasan ang damage na natatanggap ng 20% sa loob ng 2 turn. Nakakakuha si Akaza ng <Blood Frenzy> effect batay sa damage na naidulot ng atakeng ito. Kapag nasa ilalim ng <Demon Blood>, mas lalo pang tumitindi ang bisa ng skill na ito.',
		simDesc_ma = 'Akaza menyerbu ke arah satu sasaran, menekan sebanyak 3 kali dan mengurangkan kerosakan yang diterima sebanyak 20% selama 2 giliran. Akaza menerima kesan <Amukan Darah> berdasarkan jumlah kerosakan yang dihasilkan daripada serangan ini. Apabila berada di bawah kesan <Darah Syaitan>, kuasa kemahiran ini akan dipertingkat dengan ketara.',
		simDesc = 'Akaza charges at a single target, suppressing 3 times and reducing damage taken by 20% for 2 turns. He gains the <Blood Frenzy> effect based on the damage dealt by this attack. When under the <Demon Blood> effect, the skill’s power is greatly enhanced.',
		iconRes = 'battle/skill_icon/skill_80072.png',
