	},
	[9080082] = {
		id = 9080082,
		skillName_vn = 'Lạc Hoa Huyễn Ảnh',
		skillName_en = 'Falling Flower Illusion',
		skillName_th = 'ภาพลวงดอกไม้ร่วง',
		skillName_in = 'Ilusi Bunga Jatuh',
		skillName_ph = 'Falling Flower Illusion',
		skillName_ma = 'Ilusi Bunga Jatuh',
		skillName = 'Lạc Hoa Huyễn Ảnh',
		describe_vn = 'Tamayo giải phóng một làn sóng huyễn thuật huyết dịch từ dòng máu nguyền rủa của mình, tạo nên một cơn lốc ảo ảnh cánh hoa đỏ rực xoáy cuộn quanh kẻ địch. Những cánh hoa huyền hoặc này nhanh chóng bao phủ mục tiêu, bùng nổ thành đòn tấn công gây #C0x3D8A99#120% Công Phép Thuật #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# sát thương ma thuật#C0x5B545B#,  đồng thời khiến mục tiêu bị nhắm đến trực tiếp nhiễm hiệu ứng <Sốt Huyết>. Toàn bộ những kẻ địch trúng phải sát thương đều sẽ bị nhiễm <Hoa Độc>, một loại độc tố ma pháp được ẩn giấu trong mỗi cánh hoa.\n#F10#\n#F40# <Hoa Độc>:  Có thể chồng tối đa 5 tầng, mỗi tầng độc sẽ được kích hoạt trước hành động của mục tiêu, gây thêm #C0x3D8A99#15% Công Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$ lên mục tiêu, khiến chúng dần dần kiệt quệ trong vòng xoáy ảo giác và độc tố chết người.',
		describe_en = 'Tamayo unleashes a wave of blood illusion magic from her cursed blood, creating a swirling vortex of bright red petals around enemies. These enchanting petals quickly envelop the target, exploding into an attack dealing #C0x3D8A99#120% Magic Attack #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Magic Damage#C0x5B545B#, while directly applying the <Blood Fever> effect on the targeted enemy. All enemies hit by the damage are afflicted with <Poisoned Petals>, a hidden magical toxin within each petal.\n#F10#\n#F40# <Poisoned Petals>: Can stack up to 5 layers, each layer triggers before the target’s action, dealing an additional #C0x3D8A99#15% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ to the target, gradually draining them within the deadly spiral of illusions and poison.',
		describe_th = 'Tamayo ปล่อยคลื่นเวทย์มายาเลือดจากเลือดต้องสาปของเธอ สร้างพายุวนของกลีบดอกสีแดงสว่างรอบศัตรู กลีบดอกเวทย์เหล่านี้ปกคลุมเป้าหมายอย่างรวดเร็ว ระเบิดเป็นการโจมตีที่สร้างความเสียหาย #C0x3D8A99#120% พลังโจมตีเวทย์ #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายเวทย์#C0x5B545B# และทำให้เป้าหมายที่โจมตีตรง ๆ ติดเอฟเฟกต์ <Blood Fever> ศัตรูทั้งหมดที่ถูกโจมตีจะติด <Poisoned Petals> ซึ่งเป็นพิษเวทย์ที่ซ่อนอยู่ในแต่ละกลีบดอก.\n#F10#\n#F40# <Poisoned Petals>: สามารถซ้อนกันได้สูงสุด 5 ชั้น แต่ละชั้นทำงานก่อนการกระทำของเป้าหมาย สร้างความเสียหายเพิ่มเติม #C0x3D8A99#15% พลังโจมตีเวทย์#C0x5B545B#+$(skillLevel*4*48)$ แก่เป้าหมาย ทำให้เป้าหมายค่อย ๆ หมดแรงในพายุเวทย์มายาและพิษร้าย',
		describe_in = 'Tamayo melepaskan gelombang sihir ilusi darah dari darah terkutuknya, menciptakan pusaran kelopak merah menyala di sekitar musuh. Kelopak mempesona ini dengan cepat menutupi target, meledak menjadi serangan yang memberikan #C0x3D8A99#120% Serangan Sihir #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerusakan Sihir#C0x5B545B#, sekaligus menyebabkan target yang diserang langsung terkena efek <Blood Fever>. Semua musuh yang terkena serangan akan terinfeksi <Poisoned Petals>, racun sihir tersembunyi dalam setiap kelopak.\n#F10#\n#F40# <Poisoned Petals>: Dapat menumpuk hingga 5 lapis, setiap lapisan aktif sebelum aksi target, memberikan tambahan #C0x3D8A99#15% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ pada target, secara bertahap melemahkan mereka dalam pusaran ilusi dan racun mematikan.',
		describe_ph = 'Pinakakawala ni Tamayo ang alon ng ilusyon ng dugo mula sa kanyang pinagkakutulang dugo, lumilikha ng paikot-ikot na bukol ng maliwanag na pulang mga talulot sa paligid ng mga kaaway. Ang mga kaakit-akit na talulot na ito ay mabilis na bumabalot sa target, sumasabog sa isang pag-atake na nagdudulot ng #C0x3D8A99#120% Magic Attack #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Magic Damage#C0x5B545B#, habang direktang naglalapat ng epekto na <Blood Fever> sa target na kaaway. Lahat ng mga kaaway na tinamaan ng pinsala ay maaapektuhan ng <Poisoned Petals>, isang nakatagong nakamamatay na lason sa bawat talulot.\n#F10#\n#F40# <Poisoned Petals>: Maaaring mag-stack hanggang 5 layers, bawat layer ay na-trigger bago kumilos ang target, nagdudulot ng karagdagang #C0x3D8A99#15% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ sa target, unti-unting pinahihina sila sa loob ng paikot-ikot na ilusyon at nakamamatay na lason.',
		describe_ma = 'Tamayo melepaskan gelombang sihir ilusi darah dari darah terkutuknya, mencipta pusaran kelopak merah menyala di sekeliling musuh. Kelopak mempesona ini dengan cepat menutupi sasaran, meletup menjadi serangan yang memberikan #C0x3D8A99#120% Serangan Sihir #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Kerosakan Sihir#C0x5B545B#, sambil terus memberi kesan <Blood Fever> pada musuh yang disasarkan. Semua musuh yang terkena serangan dijangkiti <Poisoned Petals>, racun sihir tersembunyi dalam setiap kelopak.\n#F10#\n#F40# <Poisoned Petals>: Boleh bertindih sehingga 5 lapisan, setiap lapisan diaktifkan sebelum tindakan sasaran, memberikan tambahan #C0x3D8A99#15% Serangan Sihir#C0x5B545B#+$(skillLevel*4*48)$ kepada sasaran, secara beransur-ansur melemahkan mereka dalam pusaran ilusi dan racun maut.',
		describe = 'Tamayo unleashes a wave of blood illusion magic from her cursed blood, creating a swirling vortex of bright red petals around enemies. These enchanting petals quickly envelop the target, exploding into an attack dealing #C0x3D8A99#120% Magic Attack #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Magic Damage#C0x5B545B#, while directly applying the <Blood Fever> effect on the targeted enemy. All enemies hit by the damage are afflicted with <Poisoned Petals>, a hidden magical toxin within each petal.\n#F10#\n#F40# <Poisoned Petals>: Can stack up to 5 layers, each layer triggers before the target’s action, dealing an additional #C0x3D8A99#15% Magic Attack#C0x5B545B#+$(skillLevel*4*48)$ to the target, gradually draining them within the deadly spiral of illusions and poison.',
		simDesc_vn = 'Tamayo giải phóng một làn sóng huyễn thuật máu đầy ám ảnh, khiến không khí xung quanh nhuộm đỏ bởi những ảo ảnh cánh hoa rực lửa. Những cánh hoa huyền ảo cuộn xoáy và bao phủ kẻ địch. Đồng thời, làn sóng này còn có khả năng gây hiệu ứng <Hoa Độc>, khiến mục tiêu rơi vào trạng thái trúng độc ma thuật âm thầm ăn mòn',
		simDesc_en = 'Tamayo unleashes a haunting wave of blood sorcery, turning the air crimson with blazing petal illusions. The swirling phantom petals engulf enemies, while the wave inflicts the debuff <Poison Blossom>, causing targets to suffer from a creeping magical toxin that corrodes them from within.',
		simDesc_th = 'Tamayo ปล่อยคลื่นเวทเลือดอันน่าสะพรึงกลัว ทำให้อากาศรอบตัวกลายเป็นสีแดงด้วยภาพลวงตาของกลีบดอกไฟเพลิง กลีบลวงตาหมุนวนปกคลุมศัตรู พร้อมสร้างดีบัฟ <ดอกพิษ> ทำให้เป้าหมายตกอยู่ในสภาวะพิษเวทมนตร์ที่ค่อย ๆ กัดกร่อนจากภายใน',
		simDesc_in = 'Tamayo melepaskan gelombang sihir darah yang mencekam, mewarnai udara dengan ilusi kelopak api menyala. Kelopak gaib itu berputar dan menyelimuti musuh. Gelombang ini juga memberikan debuff <Bunga Beracun>, membuat target terjerat racun sihir yang perlahan menggerogoti tubuh mereka.',
		simDesc_ph = 'Pinalaya ni Tamayo ang isang nakakatakot na alon ng mahika ng dugo, pinapula ang paligid ng mga ilusyon ng naglalagablab na mga talulot. Ang mahiwagang mga talulot ay umiikot at bumabalot sa mga kalaban. Kasabay nito, nagdudulot ito ng debuff <Bulaklak ng Lason>, na unti-unting umuukit ng lasong mahikal sa katawan ng target.',
		simDesc_ma = 'Tamayo melepaskan gelombang sihir darah yang menghantui, menjadikan udara sekeliling merah dengan ilusi kelopak api menyala. Kelopak ilusi itu berputar dan menyelubungi musuh. Pada masa yang sama, gelombang ini memberi debuff <Bunga Beracun>, menyebabkan sasaran terkena racun sihir yang perlahan-lahan menghakis dari dalam.',
		simDesc = 'Tamayo unleashes a haunting wave of blood sorcery, turning the air crimson with blazing petal illusions. The swirling phantom petals engulf enemies, while the wave inflicts the debuff <Poison Blossom>, causing targets to suffer from a creeping magical toxin that corrodes them from within.',
		zawakeEffect = __data_t__zawakeEffect[9080082],
		-- {79002}
		zawakeEffectDesc = 'Tamayo unleashes a wave of illusionary blood magic from her cursed blood, creating a whirl of blazing red flower petals swirling around enemies. These enchanted petals quickly cover the target, exploding into an attack that deals #C0x3D8A99#120% Magic Power #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Magic Damage#C0x5B545B# and detonates the blood petals to deal additional damage equal to #C0x5c9970#10% of the target\'s current HP#C0x5B545B#, while directly inflicting the <Blood Fever> effect. All enemies hit are also afflicted with <Poisonous Flowers>, a magical toxin hidden in each petal. \n#F10#\n#F40# <Poisonous Flowers>: Can stack up to 5 layers, each layer triggers before the target acts, dealing an additional #C0x3D8A99#15% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ to the target, gradually exhausting them in the deadly vortex of illusions and toxins.',
		zawakeEffectDesc_en = 'Tamayo unleashes a wave of illusionary blood magic from her cursed blood, creating a whirl of blazing red flower petals swirling around enemies. These enchanted petals quickly cover the target, exploding into an attack that deals #C0x3D8A99#120% Magic Power #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Magic Damage#C0x5B545B# and detonates the blood petals to deal additional damage equal to #C0x5c9970#10% of the target\'s current HP#C0x5B545B#, while directly inflicting the <Blood Fever> effect. All enemies hit are also afflicted with <Poisonous Flowers>, a magical toxin hidden in each petal. \n#F10#\n#F40# <Poisonous Flowers>: Can stack up to 5 layers, each layer triggers before the target acts, dealing an additional #C0x3D8A99#15% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ to the target, gradually exhausting them in the deadly vortex of illusions and toxins.',
		zawakeEffectDesc_th = 'Tamayo ปล่อยคลื่นเวทย์เลือดลวงตาจากเลือดต้องคำสาปของเธอ สร้างพายุดอกไม้สีแดงลุกโชติช่วงหมุนรอบศัตรู ดอกไม้เวทย์เหล่านี้คลุมเป้าหมายอย่างรวดเร็ว ระเบิดเป็นการโจมตีที่สร้าง #C0x3D8A99#120% พลังเวทย์ #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# ความเสียหายเวทย์#C0x5B545B# และระเบิดในเลือดสร้างความเสียหายเพิ่มเติมเท่ากับ #C0x5c9970#10% HP ปัจจุบัน#C0x5B545B# ของเป้าหมาย พร้อมกับทำให้เป้าหมายติด <ไข้เลือด> ทุกศัตรูที่โดนความเสียหายจะติด <ดอกไม้พิษ> พิษเวทย์ซ่อนอยู่ในแต่ละกลีบดอก \n#F10#\n#F40# <ดอกไม้พิษ>: สามารถซ้อนสูงสุด 5 ชั้น แต่ละชั้นทำงานก่อนเป้าหมายกระทำ สร้างความเสียหายเพิ่มเติม #C0x3D8A99#15% พลังเวทย์#C0x5B545B#+$(skillLevel*4*48)$ กับเป้าหมาย ค่อย ๆ ทำให้เป้าหมายอ่อนแรงในพายุลวงตาและพิษร้ายแรง',
		zawakeEffectDesc_in = 'Tamayo melepaskan gelombang sihir darah ilusi dari darah terkutuknya, menciptakan pusaran kelopak bunga merah menyala yang berputar di sekitar musuh. Kelopak-kelopak ajaib ini dengan cepat menutupi target, meledak menjadi serangan yang memberikan #C0x3D8A99#120% Magic Power #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Magic Damage#C0x5B545B# dan meledakkan kelopak darah untuk memberikan damage tambahan sebesar #C0x5c9970#10% HP saat ini#C0x5B545B# dari target, sekaligus langsung menimbulkan efek <Blood Fever>. Semua musuh yang terkena serangan juga akan terinfeksi <Poisonous Flowers>, racun sihir tersembunyi di setiap kelopak. \n#F10#\n#F40# <Poisonous Flowers>: Dapat menumpuk hingga 5 lapisan, setiap lapisan aktif sebelum target bertindak, memberikan tambahan #C0x3D8A99#15% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ ke target, secara bertahap melemahkan mereka dalam pusaran ilusi dan racun mematikan.',
		zawakeEffectDesc_ph = 'Tamayo releases a wave of illusionary blood magic from her cursed blood, creating a vortex of blazing red flower petals swirling around enemies. These enchanted petals quickly cover the target, exploding into an attack that deals #C0x3D8A99#120% Magic Power #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Magic Damage#C0x5B545B# and detonates the blood petals to deal additional damage equal to #C0x5c9970#10% of the target\'s current HP#C0x5B545B#, while directly inflicting the <Blood Fever> effect. All enemies hit are also afflicted with <Poisonous Flowers>, a magical toxin hidden in each petal. \n#F10#\n#F40# <Poisonous Flowers>: Can stack up to 5 layers, each layer triggers before the target acts, dealing an additional #C0x3D8A99#15% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ to the target, gradually exhausting them in the deadly vortex of illusions and toxins.',
		zawakeEffectDesc_ma = 'Tamayo melepaskan gelombang sihir darah ilusi dari darah terkutuknya, mencipta pusaran kelopak bunga merah menyala yang berputar di sekeliling musuh. Kelopak-kelopak ajaib ini cepat menutupi sasaran, meletup menjadi serangan yang memberikan #C0x3D8A99#120% Magic Power #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# Magic Damage#C0x5B545B# dan meletupkan kelopak darah untuk memberikan kerosakan tambahan bersamaan #C0x5c9970#10% HP semasa#C0x5B545B# sasaran, serta langsung memberi kesan <Blood Fever>. Semua musuh yang terkena serangan juga akan terkena <Poisonous Flowers>, racun sihir tersembunyi dalam setiap kelopak. \n#F10#\n#F40# <Poisonous Flowers>: Boleh ditumpuk sehingga 5 lapisan, setiap lapisan diaktifkan sebelum sasaran bertindak, memberikan tambahan #C0x3D8A99#15% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ kepada sasaran, secara beransur-ansur melemahkan mereka dalam pusaran ilusi dan racun maut.',
		zawakeEffectDesc_vn = 'Tamayo giải phóng một làn sóng huyễn thuật huyết dịch từ dòng máu nguyền rủa của mình, tạo nên một cơn lốc ảo ảnh cánh hoa đỏ rực xoáy cuộn quanh kẻ địch. Những cánh hoa huyền hoặc này nhanh chóng bao phủ mục tiêu, bùng nổ thành đòn tấn công gây #C0x3D8A99#120% Công Phép Thuật #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# sát thương ma thuật#C0x5B545B# và phát nổ hoa trong máu gây thêm sát thương tương ứng với #C0x5c9970#10% máu hiện tại#C0x5B545B# của mục tiêu, đồng thời khiến mục tiêu bị nhắm đến trực tiếp nhiễm hiệu ứng <Sốt Huyết> Toàn bộ những kẻ địch trúng phải sát thương đều sẽ bị nhiễm <Hoa Độc>, một loại độc tố ma pháp được ẩn giấu trong mỗi cánh hoa. \n#F10#\n#F40# <Hoa Độc>:  Có thể chồng tối đa 5 tầng, mỗi tầng độc sẽ được kích hoạt trước hành động của mục tiêu, gây thêm #C0x3D8A99#15% Công Phép Thuật#C0x5B545B#+$(skillLevel*4*48)$ lên mục tiêu, khiến chúng dần dần kiệt quệ trong vòng xoáy ảo giác và độc tố chết người.',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'Tamayo swings her blood to create three deadly slashes imbued with chilling intent, targeting the vital arteries of enemies. This precise and ruthless strike deals damage equal to 10% of the target’s current HP, quickly weakening even the strongest foes',
		zawakeSimpleDesc_en = 'Tamayo swings her blood to create three deadly slashes imbued with chilling intent, targeting the vital arteries of enemies. This precise and ruthless strike deals damage equal to 10% of the target’s current HP, quickly weakening even the strongest foes',
		zawakeSimpleDesc_th = 'Tamayo ฟันเลือดสร้างร่องรอยการฟัน 3 เส้นอันตรายที่เต็มไปด้วยเจตนาร้าย พุ่งตรงไปยังเส้นเลือดสำคัญของศัตรู การโจมตีที่แม่นยำและโหดร้ายนี้สร้างความเสียหายเท่ากับ 10% ของ HP ปัจจุบันของเป้าหมาย ทำให้ศัตรูอ่อนแรงอย่างรวดเร็วแม้จะมีพลังชีวิตสูง',
		zawakeSimpleDesc_in = 'Tamayo mengayunkan darahnya menciptakan tiga goresan mematikan yang mengandung aura dingin, menargetkan arteri vital musuh. Serangan tepat dan kejam ini menyebabkan kerusakan sebesar 10% dari HP saat ini target, melemahkan musuh dengan cepat meski memiliki stamina tinggi',
		zawakeSimpleDesc_ph = 'Inihahampas ni Tamayo ang kanyang dugo upang lumikha ng tatlong nakamamatay na hiwa na may lamig na intensyon, tinatarget ang vital arteries ng mga kalaban. Ang tumpak at walang awa na pag-atake na ito ay nagdudulot ng damage katumbas ng 10% ng kasalukuyang HP ng target, nagpapahina sa mga kalaban kahit na may mataas na stamina',
		zawakeSimpleDesc_ma = 'Tamayo mengayunkan darahnya untuk mencipta tiga serangan mematikan yang mengandungi niat dingin, menarget arteri vital musuh. Serangan tepat dan kejam ini menyebabkan kerosakan bersamaan 10% daripada HP semasa sasaran, melemahkan musuh dengan cepat walaupun mempunyai stamina tinggi',
		zawakeSimpleDesc_vn = 'Tamayo vung máu tạo nên ba đường cào chết chóc mang theo sát khí lạnh lẽo, nhắm thẳng vào các động mạch sinh tử của đối phương. Đòn đánh chính xác và tàn nhẫn này gây sát thương tương đương 10% lượng máu hiện tại của mục tiêu, khiến kẻ địch nhanh chóng suy yếu dù có sở hữu thể lực dồi dào',
		iconRes = 'battle/skill_icon/skill_80082.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 1,
		skillDamageType = 1,
		skillNatureType = 8,
		cdRound = 2,
		posChoose = 1,
		hintChoose = 11,
		targetTypeDesc = 'Single Enemy',
		targetTypeDesc_vn = 'Đơn thể địch',
		targetTypeDesc_en = 'Single Enemy',
		targetTypeDesc_th = 'เป้าหมายเดี่ยวของศัตรู',
		targetTypeDesc_in = 'Satu Musuh',
		targetTypeDesc_ph = 'Isang Kalaban',
		targetTypeDesc_ma = 'Satu Musuh',
