	},
	[9080083] = {
		id = 9080083,
		skillName_vn = 'Lạc Hoa Vạn Huyễn',
		skillName_en = 'Falling Flower Myriad Illusions',
		skillName_th = 'ภาพลวงดอกไม้หมื่นพัน',
		skillName_in = 'Myriad Ilusi Bunga Jatuh',
		skillName_ph = 'Falling Flower Myriad Illusions',
		skillName_ma = 'Myriad Ilusi Bunga Jatuh',
		skillName = 'Lạc Hoa Vạn Huyễn',
		describe_vn = 'Tamayo vung máu tạo thành một màn ảo ảnh vạn cánh hoa đỏ rực, cuộn xoáy như bão lửa giữa chiến trường, tràn qua và tấn công tất cả mục tiêu địch. Mỗi cánh hoa ma pháp đều mang theo sát ý mãnh liệt, gây #C0x3D8A99#150% Công Phép Thuật#C0x5B545B#+$(skillLevel* 4*90)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B# cho từng kẻ địch trúng phải. Toàn bộ mục tiêu trúng chiêu lập tức chịu 3 tầng hiệu ứng <Sốt huyết> và <Hoa Độc>, khiến máu huyết hỗn loạn và cơ thể bị tàn phá từ bên trong. Không chỉ là công kích, làn sóng huyết thuật còn mang năng lượng hồi phục, phục hồi #C0x5c9970#20% máu#C0x5B545B# cho toàn bộ đồng minh, giúp đội hình hồi sinh mạnh mẽ trong cơn bão chiến đấu.',
		describe_en = 'Tamayo swings her blood to create a dazzling illusion of countless red petals, swirling like a fiery storm across the battlefield, hitting all enemy targets. Each magical petal carries intense deadly intent, dealing #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel* 4*90)$#C0xF13B54# Magic Damage#C0x5B545B# to each enemy hit. All targets struck immediately suffer 3 layers of <Blood Fever> and <Poisoned Petals>, causing blood chaos and internal devastation. Not only an attack, the wave of blood magic also carries healing energy, restoring #C0x5c9970#20% HP#C0x5B545B# to all allies, allowing the team to recover strongly amid the storm of battle.',
		describe_th = 'Tamayo ฟาดเลือดสร้างภาพลวงตาของกลีบดอกแดงนับพัน วนเป็นพายุไฟกลางสนามรบ โจมตีทุกเป้าหมายศัตรู กลีบดอกเวทย์แต่ละชิ้นมีเจตนาฆ่าที่รุนแรง สร้างความเสียหาย #C0x3D8A99#150% พลังโจมตีเวทย์ #C0x5B545B#+$(skillLevel* 4*90)$#C0xF13B54# ความเสียหายเวทย์#C0x5B545B# ต่อศัตรูที่โดนโจมตีทั้งหมด เป้าหมายทั้งหมดที่ถูกโจมตีติด 3 ชั้นเอฟเฟกต์ <Blood Fever> และ <Poisoned Petals> ทำให้เลือดวุ่นวายและร่างกายถูกทำลายจากภายใน ไม่ใช่แค่การโจมตี แต่คลื่นเวทย์เลือดยังมาพร้อมพลังฟื้นฟู ฟื้นฟู #C0x5c9970#20% พลังชีวิต#C0x5B545B# ให้กับทุกพันธมิตร ทำให้ทีมฟื้นตัวอย่างแข็งแกร่งท่ามกลางพายุแห่งการต่อสู้',
		describe_in = 'Tamayo mengayunkan darahnya membentuk ilusi ribuan kelopak merah yang berputar seperti badai api di medan perang, menyerang semua target musuh. Setiap kelopak sihir membawa niat mematikan yang kuat, memberikan #C0x3D8A99#150% Serangan Sihir#C0x5B545B#+$(skillLevel* 4*90)$#C0xF13B54# Kerusakan Sihir#C0x5B545B# pada setiap musuh yang terkena. Semua target yang terkena langsung menderita 3 lapisan efek <Blood Fever> dan <Poisoned Petals>, menyebabkan kekacauan darah dan kerusakan internal. Bukan hanya serangan, gelombang sihir darah juga membawa energi penyembuhan, memulihkan #C0x5c9970#20% HP#C0x5B545B# untuk semua sekutu, memungkinkan tim bangkit kembali dengan kuat di tengah badai pertempuran.',
		describe_ph = 'Pinakakawala ni Tamayo ang kanyang dugo upang bumuo ng ilusyon ng libu-libong pulang talulot, umiikot na parang bagyong apoy sa gitna ng labanan, tumatama sa lahat ng kaaway. Bawat mahiwagang talulot ay nagdadala ng matinding intensyon na nakamamatay, nagdudulot ng #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel* 4*90)$#C0xF13B54# Magic Damage#C0x5B545B# sa bawat kaaway na tinamaan. Lahat ng target na tinamaan ay agad na nakakaranas ng 3 layers ng <Blood Fever> at <Poisoned Petals>, nagdudulot ng kaguluhan sa dugo at panloob na pagkawasak. Hindi lamang atake, dala rin ng alon ng magic ng dugo ang enerhiyang nakapagpapagaling, nagbabalik ng #C0x5c9970#20% HP#C0x5B545B# sa lahat ng kakampi, nagpapalakas sa koponan sa gitna ng bagyo ng labanan.',
		describe_ma = 'Tamayo menghayunkan darahnya membentuk ilusi ribuan kelopak merah berputar seperti ribut api di medan perang, menyerang semua sasaran musuh. Setiap kelopak sihir membawa niat membunuh yang kuat, memberikan #C0x3D8A99#150% Serangan Sihir#C0x5B545B#+$(skillLevel* 4*90)$#C0xF13B54# Kerosakan Sihir#C0x5B545B# kepada setiap musuh yang terkena. Semua sasaran yang terkena segera mengalami 3 lapisan kesan <Blood Fever> dan <Poisoned Petals>, menyebabkan kekacauan darah dan kemusnahan dalaman. Bukan sekadar serangan, gelombang sihir darah juga membawa tenaga pemulihan, memulihkan #C0x5c9970#20% HP#C0x5B545B# untuk semua sekutu, membolehkan pasukan pulih dengan kuat di tengah ribut peperangan.',
		describe = 'Tamayo swings her blood to create a dazzling illusion of countless red petals, swirling like a fiery storm across the battlefield, hitting all enemy targets. Each magical petal carries intense deadly intent, dealing #C0x3D8A99#150% Magic Attack#C0x5B545B#+$(skillLevel* 4*90)$#C0xF13B54# Magic Damage#C0x5B545B# to each enemy hit. All targets struck immediately suffer 3 layers of <Blood Fever> and <Poisoned Petals>, causing blood chaos and internal devastation. Not only an attack, the wave of blood magic also carries healing energy, restoring #C0x5c9970#20% HP#C0x5B545B# to all allies, allowing the team to recover strongly amid the storm of battle.',
		simDesc_vn = 'Tamayo vung máu tạo nên một cơn lốc ảo ảnh vạn cánh hoa, lan rộng khắp chiến trường và tấn công tất cả mục tiêu địch bằng huyễn thuật chết chóc. Mỗi cánh hoa mang theo ma lực ngầm, lập tức áp dụng 3 tầng hiệu ứng <Sốt huyết> và <Hoa Độc> lên từng mục tiêu, khiến kẻ địch rơi vào trạng thái suy yếu kéo dài. Không chỉ tàn phá đội hình đối phương, kỹ năng còn lan tỏa năng lượng phục hồi, hồi lại 20% máu tối đa cho toàn bộ đồng minh, giúp cả đội nhanh chóng lấy lại nhịp trận và tiếp tục chiến đấu',
		simDesc_en = 'Tamayo unleashes a storm of illusory blood petals, spreading across the battlefield and striking all enemies with deadly sorcery. Each petal carries hidden power, instantly applying 3 stacks of <Blood Fever> and <Poison Blossom> to every target, leaving them in prolonged weakness. Beyond shattering enemy lines, the skill radiates restorative energy, healing 20% of max HP for all allies, allowing the team to recover and press the attack.',
		simDesc_th = 'Tamayo ปล่อยพายุภาพลวงตากลีบดอกนับหมื่นจากโลหิต แผ่กระจายทั่วสนามรบและโจมตีศัตรูทุกคนด้วยเวทมรณะ แต่ละกลีบแฝงด้วยพลังมืด ทันทีที่กระทบเป้าหมายจะมอบ 3 ชั้นดีบัฟ <ไข้เลือด> และ <ดอกพิษ> ทำให้ศัตรูอ่อนแรงยาวนาน ไม่เพียงแต่ทำลายแนวศัตรู สกิลนี้ยังปลดปล่อยพลังฟื้นฟู ฟื้นคืน 20% HP สูงสุดให้แก่พันธมิตรทั้งหมด ช่วยให้ทีมกลับมาควบคุมจังหวะและต่อสู้ต่อไป',
		simDesc_in = 'Tamayo menghempaskan badai ilusi kelopak darah, menyebar ke seluruh medan perang dan menyerang semua musuh dengan sihir mematikan. Setiap kelopak membawa kekuatan tersembunyi, langsung memberikan 3 tumpukan <Demam Darah> dan <Bunga Beracun> pada setiap target, membuat musuh jatuh dalam kondisi lemah berkepanjangan. Tidak hanya menghancurkan barisan lawan, skill ini juga memancarkan energi pemulihan, menyembuhkan 20% HP maksimum seluruh sekutu, membantu tim pulih cepat dan melanjutkan pertarungan.',
		simDesc_ph = 'Si Tamayo ay nagpakawala ng buhawi ng mga ilusyon ng dugong talulot, kumakalat sa buong larangan at inaatake ang lahat ng kaaway gamit ang nakamamatay na mahika. Bawat talulot ay may nakatagong kapangyarihan, agad na naglalagay ng 3 stack ng <Lagnat ng Dugo> at <Bulaklak ng Lason> sa bawat target, na nag-iiwan sa kanila sa matagal na paghina. Higit pa sa pagwasak ng kalaban, ang kasanayang ito ay naglalabas din ng enerhiyang nakapagpapagaling, na nagbabalik ng 20% ng maximum HP ng lahat ng kakampi, upang muling makabawi ang buong koponan at ipagpatuloy ang laban.',
		simDesc_ma = 'Tamayo melepaskan ribut ilusi kelopak darah, merebak ke seluruh medan perang dan menyerang semua musuh dengan sihir maut. Setiap kelopak mengandungi kuasa tersembunyi, serta-merta mengenakan 3 lapisan debuff <Demam Darah> dan <Bunga Beracun> kepada setiap sasaran, menjadikan mereka lemah berpanjangan. Selain memusnahkan barisan lawan, kemahiran ini turut memancarkan tenaga pemulihan, memulihkan 20% HP maksimum kepada semua sekutu, membantu pasukan kembali pulih dan meneruskan pertarungan.',
		simDesc = 'Tamayo unleashes a storm of illusory blood petals, spreading across the battlefield and striking all enemies with deadly sorcery. Each petal carries hidden power, instantly applying 3 stacks of <Blood Fever> and <Poison Blossom> to every target, leaving them in prolonged weakness. Beyond shattering enemy lines, the skill radiates restorative energy, healing 20% of max HP for all allies, allowing the team to recover and press the attack.',
		starEffect = __data_t__starEffect[9080083],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu quả: Lượng hồi máu được tăng thêm 10%, dựa theo máu tối đa của từng đồng minh. Hiệu ứng bổ sung: Giảm 20% Thủ Phép Thuật của kẻ địch, hiệu lực duy trì trong 3 lượt.',
		starEffectDesc = 'Enhanced Effect: Healing amount is increased by 10%, based on each ally’s Max HP. Additional Effect: Reduces enemy’s Magic Defense by 20%, lasting for 3 turns.',
		starEffectDesc_en = 'Enhanced Effect: Healing amount is increased by 10%, based on each ally’s Max HP. Additional Effect: Reduces enemy’s Magic Defense by 20%, lasting for 3 turns.',
		starEffectDesc_th = 'เอฟเฟกต์เสริมพลัง: ปริมาณการฟื้นฟู HP เพิ่มขึ้น 10% อ้างอิงจาก HP สูงสุดของพันธมิตรแต่ละคน เอฟเฟกต์เพิ่มเติม: ลดพลังป้องกันเวทของศัตรู 20% เป็นเวลา 3 เทิร์น',
		starEffectDesc_in = 'Efek Ditingkatkan: Jumlah pemulihan HP meningkat 10%, berdasarkan Max HP setiap sekutu. Efek Tambahan: Mengurangi Magic Defense musuh sebesar 20%, berlangsung selama 3 giliran.',
		starEffectDesc_ph = 'Enhanced Effect: Nadagdagan ng 10% ang healing, batay sa Max HP ng bawat kakampi. Additional Effect: Binabawasan ng 20% ang Magic Defense ng kalaban, tumatagal ng 3 turn.',
		starEffectDesc_ma = 'Kesan Dipertingkat: Jumlah pemulihan HP meningkat sebanyak 10%, berdasarkan HP Maksimum setiap sekutu. Kesan Tambahan: Mengurangkan Pertahanan Magik musuh sebanyak 20%, berlanjutan selama 3 giliran.',
		zawakeEffect = __data_t__zawakeEffect[9080083],
		-- {79003, 1}
		zawakeEffectDesc = 'Enhanced Effect: Healing effect increased by 10% based on allies\' maximum HP.\nAdditional Effect: Reduces enemies\' Magic Defense by 30% for 3 turns.',
		zawakeEffectDesc_en = 'Enhanced Effect: Healing effect increased by 10% based on allies\' maximum HP.\nAdditional Effect: Reduces enemies\' Magic Defense by 30% for 3 turns.',
		zawakeEffectDesc_th = 'เพิ่มประสิทธิภาพ: ผลการฟื้นฟูเพิ่มขึ้น 10% ตาม HP สูงสุดของพันธมิตร.\nเอฟเฟกต์เพิ่มเติม: ลดการป้องกันเวทย์ของศัตรู 30% เป็นเวลา 3 เทิร์น',
		zawakeEffectDesc_in = 'Efek Ditingkatkan: Efek penyembuhan meningkat 10% berdasarkan HP maksimum rekan.\nEfek Tambahan: Mengurangi Pertahanan Sihir musuh sebesar 30% selama 3 giliran.',
		zawakeEffectDesc_ph = 'Enhanced Effect: Tumaas ng 10% ang bisa ng paggaling batay sa maximum HP ng mga kakampi.\nAdditional Effect: Binabawasan ang Magic Defense ng mga kalaban ng 30% sa loob ng 3 turn.',
		zawakeEffectDesc_ma = 'Kesan Ditingkatkan: Kesan penyembuhan meningkat 10% berdasarkan HP maksimum rakan.\nKesan Tambahan: Mengurangkan Magic Defense musuh sebanyak 30% selama 3 giliran.',
		zawakeEffectDesc_vn = 'Tăng cường hiệu quả: Hiệu quả hồi máu tăng 10% dựa theo lượng máu tối đa của đồng đội.\nHiệu ứng bổ sung: Giảm thủ phép thuật của địch  đi 30%, kéo dài 3 lượt.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'Reduces enemy Magic Defense by 20%, for 3 turns.\n#F20# \n#F40##C0x5c9970#→ Reduces enemy Magic Defense by 30%, for 3 turns',
		zawakeSimpleDesc_en = 'Reduces enemy Magic Defense by 20%, for 3 turns.\n#F20# \n#F40##C0x5c9970#→ Reduces enemy Magic Defense by 30%, for 3 turns',
		zawakeSimpleDesc_th = 'ลดป้องกันเวทของศัตรู 20% เป็นเวลา 3 เทิร์น.\n#F20# \n#F40##C0x5c9970#→ ลดป้องกันเวทของศัตรู 30% เป็นเวลา 3 เทิร์น',
		zawakeSimpleDesc_in = 'Mengurangi Pertahanan Sihir musuh sebesar 20%, selama 3 giliran.\n#F20# \n#F40##C0x5c9970#→ Mengurangi Pertahanan Sihir musuh sebesar 30%, selama 3 giliran',
		zawakeSimpleDesc_ph = 'Binabawasan ang Magic Defense ng kalaban ng 20%, sa loob ng 3 turn.\n#F20# \n#F40##C0x5c9970#→ Binabawasan ang Magic Defense ng kalaban ng 30%, sa loob ng 3 turn',
		zawakeSimpleDesc_ma = 'Mengurangkan Pertahanan Sihir musuh sebanyak 20%, selama 3 giliran.\n#F20# \n#F40##C0x5c9970#→ Mengurangkan Pertahanan Sihir musuh sebanyak 30%, selama 3 giliran',
		zawakeSimpleDesc_vn = 'Giảm thủ phép thuật của địch đi 20%, kéo dài 3 lượt.\n#F20# \n#F40##C0x5c9970#→ Giảm thủ phép thuật của địch đi 30%, kéo dài 3 lượt',
		iconRes = 'battle/skill_icon/skill_80083.png',
