	[9080084] = {
		id = 9080084,
		skillName_vn = 'Vô Ngôn Độc Y',
		skillName_en = 'Silent Poison Doctor',
		skillName_th = 'หมอพิษเงียบ',
		skillName_in = 'Dokter Racun Sunyi',
		skillName_ph = 'Tahimik na Poison Doctor',
		skillName_ma = 'Doktor Racun Sunyi',
		skillName = 'Vô Ngôn Độc Y',
		describe_vn = 'Mỗi khi một đồng minh tấn công mục tiêu đang chịu ảnh hưởng của <Sốt huyết> hoặc <Hoa Độc>, họ sẽ nhận được một luồng hồi phục từ dư chấn huyết thuật, giúp hồi lại #C0x5c9970#5% #C0x5B545B# máu tối đa + $(skillLevel*4*12)$. Không chỉ vậy, hiệu ứng hồi máu này còn được cường hóa theo mức độ nhiễm độc của mục tiêu – tăng thêm 1% hồi máu cho mỗi tầng <Sốt huyết> và <Hoa Độc> đang tồn tại. Càng nhiều tầng debuff trên địch, lượng hồi phục nhận được càng lớn, tạo nên sự kết hợp hoàn hảo giữa tấn công và hỗ trợ, giúp đội hình duy trì nhịp chiến đấu liên tục. ',
		describe_en = 'Whenever an ally attacks a target affected by <Blood Fever> or <Poisoned Petals>, they receive a healing surge from the residual blood magic, restoring #C0x5c9970#5% #C0x5B545B# of Max HP + $(skillLevel*4*12)$. Moreover, this healing effect is enhanced based on the target\'s level of debuff – gaining an additional 1% healing for each layer of <Blood Fever> and <Poisoned Petals> present. The more layers on the enemy, the greater the healing received, creating a perfect synergy of offense and support, helping the team maintain continuous combat rhythm.',
		describe_th = 'ทุกครั้งที่พันธมิตรโจมตีเป้าหมายที่ได้รับผลกระทบจาก <Blood Fever> หรือ <Poisoned Petals> พวกเขาจะได้รับการฟื้นฟูจากคลื่นเวทย์เลือดที่เหลืออยู่ ฟื้นฟู #C0x5c9970#5% #C0x5B545B# ของ HP สูงสุด + $(skillLevel*4*12) นอกจากนี้ เอฟเฟกต์ฟื้นฟูนี้ยังถูกเสริมตามระดับการติดพิษของเป้าหมาย – เพิ่มการฟื้นฟูอีก 1% สำหรับแต่ละชั้น <Blood Fever> และ <Poisoned Petals> ยิ่งมีชั้น debuff มากบนศัตรู การฟื้นฟูที่ได้รับก็ยิ่งมากขึ้น สร้างการผสมผสานที่สมบูรณ์แบบระหว่างการโจมตีและสนับสนุน ช่วยให้ทีมรักษาจังหวะการต่อสู้ต่อเนื่อง',
		describe_in = 'Setiap kali seorang sekutu menyerang target yang terkena <Blood Fever> atau <Poisoned Petals>, mereka menerima gelombang penyembuhan dari sisa sihir darah, memulihkan #C0x5c9970#5% #C0x5B545B# HP Maks + $(skillLevel*4*12)$. Selain itu, efek penyembuhan ini diperkuat berdasarkan tingkat debuff target – menambahkan 1% penyembuhan untuk setiap lapisan <Blood Fever> dan <Poisoned Petals> yang ada. Semakin banyak lapisan pada musuh, semakin besar pemulihan yang diterima, menciptakan sinergi sempurna antara serangan dan dukungan, membantu tim mempertahankan ritme pertempuran yang berkelanjutan.',
		describe_ph = 'Tuwing ang isang kakampi ay umatake sa target na apektado ng <Blood Fever> o <Poisoned Petals>, makakatanggap sila ng healing surge mula sa natitirang blood magic, na nagbabalik ng #C0x5c9970#5% #C0x5B545B# ng Max HP + $(skillLevel*4*12)$. Bukod dito, ang healing effect na ito ay pinalakas base sa level ng debuff ng target – tumatanggap ng karagdagang 1% healing para sa bawat layer ng <Blood Fever> at <Poisoned Petals> na naroroon. Mas maraming layer sa kaaway, mas malaki ang healing na matatanggap, lumilikha ng perpektong kombinasyon ng offense at support, tumutulong sa koponan na mapanatili ang tuloy-tuloy na ritmo ng labanan.',
		describe_ma = 'Setiap kali seorang sekutu menyerang sasaran yang terjejas oleh <Blood Fever> atau <Poisoned Petals>, mereka menerima gelombang penyembuhan daripada sisa sihir darah, memulihkan #C0x5c9970#5% #C0x5B545B# HP Maks + $(skillLevel*4*12)$. Selain itu, kesan penyembuhan ini dipertingkatkan mengikut tahap debuff sasaran – menambah 1% pemulihan untuk setiap lapisan <Blood Fever> dan <Poisoned Petals> yang wujud. Semakin banyak lapisan pada musuh, semakin besar pemulihan diterima, mewujudkan gabungan sempurna antara serangan dan sokongan, membantu pasukan mengekalkan rentak pertempuran yang berterusan.',
		describe = 'Whenever an ally attacks a target affected by <Blood Fever> or <Poisoned Petals>, they receive a healing surge from the residual blood magic, restoring #C0x5c9970#5% #C0x5B545B# of Max HP + $(skillLevel*4*12)$. Moreover, this healing effect is enhanced based on the target\'s level of debuff – gaining an additional 1% healing for each layer of <Blood Fever> and <Poisoned Petals> present. The more layers on the enemy, the greater the healing received, creating a perfect synergy of offense and support, helping the team maintain continuous combat rhythm.',
		simDesc_vn = 'Khi đồng đội tấn công mục tiêu đang chịu ảnh hưởng của hiệu ứng <Sốt huyết> hoặc <Hoa độc>, họ sẽ hồi lại 10% máu tối đa. Ngoài ra, hiệu ứng hồi máu được tăng thêm 1% cho mỗi tầng của <Sốt huyết> và <Hoa độc> đang tồn tại trên mục tiêu đó.',
		simDesc_en = 'When an ally attacks a target affected by <Blood Fever> or <Poison Blossom>, they recover 10% of their max HP. Additionally, the healing effect is increased by 1% for each stack of <Blood Fever> and <Poison Blossom> present on that target.',
		simDesc_th = 'เมื่อพันธมิตรโจมตีเป้าหมายที่อยู่ภายใต้ผล <ไข้เลือด> หรือ <ดอกพิษ> พวกเขาจะฟื้นฟู 10% HP สูงสุด นอกจากนี้เอฟเฟกต์ฟื้นฟูจะเพิ่มขึ้นอีก 1% ต่อทุกชั้นของ <ไข้เลือด> และ <ดอกพิษ> ที่มีอยู่บนเป้าหมายนั้น',
		simDesc_in = 'Saat sekutu menyerang target yang terkena efek <Demam Darah> atau <Bunga Beracun>, mereka akan memulihkan 10% HP maksimum. Selain itu, efek penyembuhan bertambah 1% untuk setiap tumpukan <Demam Darah> dan <Bunga Beracun> yang ada pada target tersebut.',
		simDesc_ph = 'Kapag umatake ang kakampi sa target na may epekto ng <Lagnat ng Dugo> o <Bulaklak ng Lason>, sila ay makakabawi ng 10% ng kanilang maximum HP. Dagdag pa rito, tumataas ng 1% ang healing effect para sa bawat stack ng <Lagnat ng Dugo> at <Bulaklak ng Lason> na nasa target.',
		simDesc_ma = 'Apabila sekutu menyerang sasaran yang terjejas dengan kesan <Demam Darah> atau <Bunga Beracun>, mereka akan memulihkan 10% HP maksimum. Selain itu, kesan pemulihan meningkat sebanyak 1% bagi setiap lapisan <Demam Darah> dan <Bunga Beracun> yang wujud pada sasaran tersebut.',
		simDesc = 'When an ally attacks a target affected by <Blood Fever> or <Poison Blossom>, they recover 10% of their max HP. Additionally, the healing effect is increased by 1% for each stack of <Blood Fever> and <Poison Blossom> present on that target.',
		starEffect = __data_t__starEffect[9080084],
		-- {8}
		starEffectDesc_vn = 'Mỗi khi kẻ địch chịu sát thương từ <Sốt huyết> hoặc <Hoa Độc>, Tamayo sẽ kích hoạt một xung hồi phục ma thuật, hồi 5% máu cho một đồng minh ngẫu nhiên. Hiệu ứng này có thể lặp lại nhiều lần trong lượt, tạo nên chuỗi hồi phục liên tục gắn liền với lượng sát thương duy trì gây ra trên kẻ địch.',
		starEffectDesc = 'Each time an enemy takes damage from <Hemorrhage> or <Poison Bloom>, Tamayo triggers a magical recovery pulse, restoring 5% HP to a random ally. This effect can activate multiple times within a turn, creating a continuous healing chain linked to the sustained damage inflicted on enemies.',
		starEffectDesc_en = 'Each time an enemy takes damage from <Hemorrhage> or <Poison Bloom>, Tamayo triggers a magical recovery pulse, restoring 5% HP to a random ally. This effect can activate multiple times within a turn, creating a continuous healing chain linked to the sustained damage inflicted on enemies.',
		starEffectDesc_th = 'ทุกครั้งที่ศัตรูได้รับความเสียหายจาก <Hemorrhage> หรือ <Poison Bloom> Tamayo จะปล่อยคลื่นพลังฟื้นฟูเวทมนตร์ ฟื้นฟู HP 5% ให้พันธมิตรแบบสุ่ม เอฟเฟกต์นี้สามารถทำงานซ้ำได้หลายครั้งภายในหนึ่งเทิร์น สร้างการฟื้นฟูต่อเนื่องเชื่อมโยงกับความเสียหายต่อเนื่องที่สร้างแก่ศัตรู',
		starEffectDesc_in = 'Setiap kali musuh menerima damage dari <Hemorrhage> atau <Poison Bloom>, Tamayo memicu denyut pemulihan sihir, memulihkan 5% HP untuk satu sekutu acak. Efek ini dapat terpicu beberapa kali dalam satu giliran, menciptakan rantai pemulihan berkelanjutan yang terkait dengan damage terus-menerus yang diberikan pada musuh.',
		starEffectDesc_ph = 'Sa tuwing tatamaan ng damage mula sa <Hemorrhage> o <Poison Bloom> ang kalaban, mag-a-activate si Tamayo ng magical recovery pulse na magre-restore ng 5% HP sa isang random na kakampi. Puwedeng maulit ang effect na ito nang maraming beses sa loob ng isang turn, na lumilikha ng tuloy-tuloy na healing chain na naka-link sa sustained damage na naidudulot sa mga kalaban.',
		starEffectDesc_ma = 'Setiap kali musuh menerima damage daripada <Hemorrhage> atau <Poison Bloom>, Tamayo akan mengaktifkan denyutan pemulihan magik, memulihkan 5% HP untuk sekutu rawak. Kesan ini boleh berlaku berulang kali dalam satu giliran, mewujudkan rantai pemulihan berterusan yang berkaitan dengan damage berpanjangan yang dikenakan ke atas musuh.',
		zawakeEffect = __data_t__zawakeEffect[9080084],
		-- {79004}
		zawakeEffectDesc = 'Whenever an ally attacks a target affected by <Blood Fever> or <Poisonous Flowers>, they receive a healing surge from blood magic resonance, restoring #C0x5c9970#7% #C0x5B545B# of maximum HP + $(skillLevel*4*48)$. Moreover, this healing effect is amplified based on the target\'s debuff layers – gaining an additional 1% healing for each existing layer of <Blood Fever> and <Poisonous Flowers>. The more debuff layers on the enemy, the greater the healing received, creating a perfect synergy of offense and support to maintain continuous combat rhythm for the team.',
		zawakeEffectDesc_en = 'Whenever an ally attacks a target affected by <Blood Fever> or <Poisonous Flowers>, they receive a healing surge from blood magic resonance, restoring #C0x5c9970#7% #C0x5B545B# of maximum HP + $(skillLevel*4*48)$. Moreover, this healing effect is amplified based on the target\'s debuff layers – gaining an additional 1% healing for each existing layer of <Blood Fever> and <Poisonous Flowers>. The more debuff layers on the enemy, the greater the healing received, creating a perfect synergy of offense and support to maintain continuous combat rhythm for the team.',
		zawakeEffectDesc_th = 'ทุกครั้งที่พันธมิตรโจมตีเป้าหมายที่ได้รับผลกระทบจาก <ไข้เลือด> หรือ <ดอกไม้พิษ> พวกเขาจะได้รับคลื่นฟื้นฟูจากเรโซแนนซ์เวทย์เลือด ฟื้นฟู #C0x5c9970#7% #C0x5B545B# ของ HP สูงสุด + $(skillLevel*4*48) นอกจากนี้ เอฟเฟกต์การฟื้นฟูนี้ยังถูกเสริมตามระดับของดีบัฟบนเป้าหมาย – เพิ่มการฟื้นฟูอีก 1% สำหรับแต่ละชั้นของ <ไข้เลือด> และ <ดอกไม้พิษ> ยิ่งมีชั้นดีบัฟมาก ยิ่งฟื้นฟูมาก สร้างการผสมผสานสมบูรณ์แบบระหว่างการโจมตีและสนับสนุน ทำให้ทีมรักษาจังหวะการต่อสู้ต่อเนื่อง',
		zawakeEffectDesc_in = 'Setiap kali seorang sekutu menyerang target yang terkena efek <Blood Fever> atau <Poisonous Flowers>, mereka menerima gelombang penyembuhan dari resonansi sihir darah, memulihkan #C0x5c9970#7% #C0x5B545B# HP maksimum + $(skillLevel*4*48)$. Selain itu, efek penyembuhan ini diperkuat berdasarkan jumlah lapisan debuff pada target – menambah 1% penyembuhan untuk setiap lapisan <Blood Fever> dan <Poisonous Flowers> yang ada. Semakin banyak lapisan debuff pada musuh, semakin besar penyembuhan yang diterima, menciptakan sinergi sempurna antara ofensif dan dukungan, menjaga ritme pertempuran tim tetap berkelanjutan.',
		zawakeEffectDesc_ph = 'Sa tuwing isang kakampi ay umatake sa target na apektado ng <Blood Fever> o <Poisonous Flowers>, makakatanggap sila ng isang alon ng paggaling mula sa blood magic resonance, na nagpapagaling ng #C0x5c9970#7% #C0x5B545B# ng maximum HP + $(skillLevel*4*48)$. Bukod dito, ang epekto ng paggaling ay pinalakas batay sa dami ng debuff sa target – dagdag ng 1% paggaling para sa bawat layer ng <Blood Fever> at <Poisonous Flowers> na nasa target. Mas maraming debuff layers sa kaaway, mas malaki ang paggaling na matatanggap, na lumilikha ng perpektong pagsasanib ng opensa at suporta para mapanatili ang tuloy-tuloy na ritmo ng laban ng koponan.',
		zawakeEffectDesc_ma = 'Setiap kali seorang sekutu menyerang sasaran yang terjejas oleh <Blood Fever> atau <Poisonous Flowers>, mereka menerima gelombang penyembuhan daripada resonans sihir darah, memulihkan #C0x5c9970#7% #C0x5B545B# HP maksimum + $(skillLevel*4*48)$. Selain itu, kesan penyembuhan ini diperkuat berdasarkan bilangan lapisan debuff pada sasaran – menambah 1% penyembuhan untuk setiap lapisan <Blood Fever> dan <Poisonous Flowers> yang ada. Semakin banyak lapisan debuff pada musuh, semakin besar penyembuhan diterima, mewujudkan sinergi sempurna antara serangan dan sokongan untuk mengekalkan irama pertempuran berterusan bagi pasukan.',
		zawakeEffectDesc_vn = 'Mỗi khi một đồng minh tấn công mục tiêu đang chịu ảnh hưởng của <Sốt huyết> hoặc <Hoa Độc>, họ sẽ nhận được một luồng hồi phục từ dư chấn huyết thuật, giúp hồi lại #C0x5c9970#7% #C0x5B545B# máu tối đa + $(skillLevel*4*48)$. Không chỉ vậy, hiệu ứng hồi máu này còn được cường hóa theo mức độ nhiễm độc của mục tiêu – tăng thêm 1% hồi máu cho mỗi tầng <Sốt huyết> và <Hoa Độc> đang tồn tại. Càng nhiều tầng debuff trên địch, lượng hồi phục nhận được càng lớn, tạo nên sự kết hợp hoàn hảo giữa tấn công và hỗ trợ, giúp đội hình duy trì nhịp chiến đấu liên tục. ',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'When allies attack a target affected by <Fever Blood> or <Poison Bloom>, they recover #C0x5c9970#5% #C0x5B545B# max HP + 48. \n#F20# \n#F40##C0x5c9970#→ When allies attack a target affected by <Fever Blood> or <Poison Bloom>, they recover #C0x5c9970#7% max HP + 192',
		zawakeSimpleDesc_en = 'When allies attack a target affected by <Fever Blood> or <Poison Bloom>, they recover #C0x5c9970#5% #C0x5B545B# max HP + 48. \n#F20# \n#F40##C0x5c9970#→ When allies attack a target affected by <Fever Blood> or <Poison Bloom>, they recover #C0x5c9970#7% max HP + 192',
		zawakeSimpleDesc_th = 'เมื่อพันธมิตรโจมตีเป้าหมายที่ได้รับผลกระทบจาก <ไข้เลือด> หรือ <ดอกไม้พิษ> พวกเขาจะฟื้น #C0x5c9970#5% #C0x5B545B# HP สูงสุด + 48. \n#F20# \n#F40##C0x5c9970#→ เมื่อพันธมิตรโจมตีเป้าหมายที่ได้รับผลกระทบจาก <ไข้เลือด> หรือ <ดอกไม้พิษ> พวกเขาจะฟื้น #C0x5c9970#7% HP สูงสุด + 192',
		zawakeSimpleDesc_in = 'Ketika sekutu menyerang target yang terkena efek <Demam Darah> atau <Bunga Racun>, mereka memulihkan #C0x5c9970#5% #C0x5B545B# HP maksimal + 48. \n#F20# \n#F40##C0x5c9970#→ Ketika sekutu menyerang target yang terkena efek <Demam Darah> atau <Bunga Racun>, mereka memulihkan #C0x5c9970#7% HP maksimal + 192',
		zawakeSimpleDesc_ph = 'Kapag inatake ng allies ang target na apektado ng <Fever Blood> o <Poison Bloom>, nakakabawi sila ng #C0x5c9970#5% #C0x5B545B# max HP + 48. \n#F20# \n#F40##C0x5c9970#→ Kapag inatake ng allies ang target na apektado ng <Fever Blood> o <Poison Bloom>, nakakabawi sila ng #C0x5c9970#7% max HP + 192',
		zawakeSimpleDesc_ma = 'Apabila sekutu menyerang sasaran yang terjejas oleh <Demam Darah> atau <Bunga Racun>, mereka memulihkan #C0x5c9970#5% #C0x5B545B# HP maksimum + 48. \n#F20# \n#F40##C0x5c9970#→ Apabila sekutu menyerang sasaran yang terjejas oleh <Demam Darah> atau <Bunga Racun>, mereka memulihkan #C0x5c9970#7% HP maksimum + 192',
		zawakeSimpleDesc_vn = 'Khi đồng đội tấn công mục tiêu đang chịu ảnh hưởng của hiệu ứng <Sốt huyết> hoặc <Hoa độc>, họ sẽ hồi lại #C0x5c9970#5% #C0x5B545B# máu tối đa + 48. \n#F20# \n#F40##C0x5c9970#→ Khi đồng đội tấn công mục tiêu đang chịu ảnh hưởng của hiệu ứng <Sốt huyết> hoặc <Hoa độc>, họ sẽ hồi lại #C0x5c9970#7% máu tối đa + 192',
		iconRes = 'battle/skill_icon/skill_80084.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {90800841}
	},
	[9080101] = {
		id = 9080101,
		skillName_vn = 'Pháo Bóng Tối',
		skillName_en = 'Darkness Cannon',
		skillName_th = 'ปืนใหญ่ความมืด',
		skillName_in = 'Meriam Kegelapan',
		skillName_ph = 'Darkness Cannon',
		skillName_ma = 'Meriam Kegelapan',
		skillName = 'Pháo Bóng Tối',
		describe_vn = 'Ulquiorra lạnh lùng nâng ngón tay trỏ giữa màn đêm nhuốm màu xanh lục u ám, một luồng năng lượng hắc ám ngưng tụ rồi xé toạc không gian trong tích tắc. Tia năng lượng ấy xuyên phá trái tim đối phương, gây ra #C0x3D8A99#240% Công Phép Thuật#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Sát Thương Phép Thuật#C0x5B545B# bỏ qua 20% Thủ Phép Thuật của mục tiêu, khiến mọi nỗ lực phòng thủ trở nên vô nghĩa. Cơn bùng nổ sát thương không chỉ hủy diệt kẻ thù mà còn giúp Ulquiorra hấp thụ lại sinh khí, hồi máu bằng  #C0x5c9970#20%#C0x5B545B# lượng sát thương đã gây ra, tối đa không vượt quá 20% máu tối đa của bản thân. ',
		describe_en = 'Ulquiorra coldly raises his index finger under the night dyed in ominous green, as a dark energy condenses and tears through space in an instant. The energy beam pierces the opponent\'s heart, dealing #C0x3D8A99#240% Magic Power#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magic Damage#C0x5B545B# ignoring 20% of the target\'s Magic Defense, rendering all defensive efforts meaningless. The damage explosion not only devastates enemies but also allows Ulquiorra to absorb vitality, healing #C0x5c9970#20%#C0x5B545B# of the damage dealt, up to a maximum of 20% of his own Max HP.',
		describe_th = 'Ulquiorra ยกนิ้วชี้อย่างเย็นชาท่ามกลางค่ำคืนที่เปลี่ยนเป็นสีเขียวมืด พลังมืดรวมตัวแล้วฉีกอวกาศในทันที ลำแสงพลังนั้นแทงทะลุหัวใจของศัตรู สร้างความเสียหาย #C0x3D8A99#240% พลังเวทย์#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#ความเสียหายเวทย์#C0x5B545B# ข้าม 20% การป้องกันเวทย์ของเป้าหมาย ทำให้ความพยายามในการป้องกันทั้งหมดไร้ผล การระเบิดความเสียหายไม่เพียงทำลายศัตรูเท่านั้น แต่ยังช่วยให้ Ulquiorra ดูดซับพลังชีวิต ฟื้นฟู #C0x5c9970#20%#C0x5B545B# ของความเสียหายที่สร้างขึ้น สูงสุดไม่เกิน 20% ของ HP สูงสุดของตนเอง',
		describe_in = 'Ulquiorra dengan dingin mengangkat jari telunjuknya di bawah malam yang bernuansa hijau gelap, saat energi gelap berkondensasi dan merobek ruang dalam sekejap. Sinar energi itu menembus hati lawan, memberikan #C0x3D8A99#240% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerusakan Sihir#C0x5B545B# mengabaikan 20% Pertahanan Sihir target, membuat semua upaya pertahanan sia-sia. Ledakan kerusakan ini tidak hanya menghancurkan musuh tetapi juga memungkinkan Ulquiorra menyerap vitalitas, memulihkan #C0x5c9970#20%#C0x5B545B# dari kerusakan yang diberikan, hingga maksimum 20% dari HP Maksimalnya sendiri.',
		describe_ph = 'Ulquiorra ay malamig na itinaas ang kanyang hintuturo sa ilalim ng gabi na may madilim na berdeng kulay, habang ang madilim na enerhiya ay nagtitipon at pinupunit ang espasyo sa isang iglap. Ang sinag ng enerhiya ay tumatagos sa puso ng kalaban, nagdudulot ng #C0x3D8A99#240% Magic Power#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magic Damage#C0x5B545B# na nilalampasan ang 20% ng Magic Defense ng target, ginagawa ang lahat ng pagtatanggol na walang silbi. Ang pagsabog ng pinsala ay hindi lamang sumisira sa mga kaaway kundi pinapayagan din si Ulquiorra na sumipsip ng vitalidad, nagpapagaling ng #C0x5c9970#20%#C0x5B545B# ng pinsalang naidulot, hanggang sa maximum na 20% ng kanyang Max HP.',
		describe_ma = 'Ulquiorra dengan tenang mengangkat jari telunjuknya di bawah malam yang berwarna hijau suram, apabila tenaga gelap berkondensasi dan merobek ruang dalam sekelip mata. Sinar tenaga itu menembusi hati musuh, menyebabkan #C0x3D8A99#240% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Kerusakan Sihir#C0x5B545B# mengabaikan 20% Pertahanan Sihir sasaran, menjadikan semua usaha pertahanan tidak berguna. Letupan kerosakan ini bukan sahaja memusnahkan musuh tetapi juga membolehkan Ulquiorra menyerap tenaga hidup, memulihkan #C0x5c9970#20%#C0x5B545B# daripada kerosakan yang diberikan, maksimum tidak melebihi 20% daripada HP Maksimumnya sendiri.',
		describe = 'Ulquiorra coldly raises his index finger under the night dyed in ominous green, as a dark energy condenses and tears through space in an instant. The energy beam pierces the opponent\'s heart, dealing #C0x3D8A99#240% Magic Power#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#Magic Damage#C0x5B545B# ignoring 20% of the target\'s Magic Defense, rendering all defensive efforts meaningless. The damage explosion not only devastates enemies but also allows Ulquiorra to absorb vitality, healing #C0x5c9970#20%#C0x5B545B# of the damage dealt, up to a maximum of 20% of his own Max HP.',
		simDesc_vn = 'Ulquiorra nâng ngón tay trỏ giữa màn đêm xanh lục, bắn ra một luồng năng lượng xé toạc không gian, xuyên qua hàng địch, bỏ qua 20% Thủ Phép thuật của địch, đồng thời hồi máu bằng 20% sát thương gây ra',
		simDesc_en = 'Ulquiorra raises his finger in the emerald night, firing a beam of energy that rips through space, piercing enemy lines and ignoring 20% of their Magic Defense, while restoring HP equal to 20% of the damage dealt.',
		simDesc_th = 'Ulquiorra ชูนิ้วชี้ท่ามกลางราตรีสีมรกต ยิงพลังงานที่ฉีกกระชากอวกาศ ทะลวงผ่านแนวศัตรู โดยละเว้น 20% การป้องกันเวทมนตร์ของพวกมัน พร้อมฟื้นฟู HP เท่ากับ 20% ของความเสียหายที่สร้างได้',
		simDesc_in = 'Ulquiorra mengangkat jarinya di tengah malam hijau zamrud, menembakkan energi yang merobek ruang dan menembus barisan musuh, mengabaikan 20% Pertahanan Sihir mereka, sekaligus memulihkan HP sebesar 20% dari total damage yang dihasilkan.',
		simDesc_ph = 'Itinaas ni Ulquiorra ang kanyang daliri sa gitna ng luntiang gabi, nagpapakawala ng sinag ng enerhiya na pumupunit sa kalawakan at tumatagos sa mga kalaban, binabalewala ang 20% ng kanilang Magic Defense, habang nagpapagaling ng HP katumbas ng 20% ng pinsalang naidulot.',
		simDesc_ma = 'Ulquiorra mengangkat jarinya di tengah malam hijau zamrud, menembakkan pancaran tenaga yang merobek ruang dan menembusi barisan musuh, mengabaikan 20% Pertahanan Magik mereka, sambil memulihkan HP sebanyak 20% daripada jumlah kerosakan yang dilakukan.',
		simDesc = 'Ulquiorra raises his finger in the emerald night, firing a beam of energy that rips through space, piercing enemy lines and ignoring 20% of their Magic Defense, while restoring HP equal to 20% of the damage dealt.',
		iconRes = 'battle/skill_icon/skill_80101.png',
