	[9080102] = {
		id = 9080102,
		skillName_vn = 'Ảnh Song Trảm',
		skillName_en = 'Shadow Double Cleaver',
		skillName_th = 'ดาบเงาคู่',
		skillName_in = 'Cleaver Bayangan Ganda',
		skillName_ph = 'Shadow Double Cleaver',
		skillName_ma = 'Cleaver Bayangan Berkembar',
		skillName = 'Ảnh Song Trảm',
		describe_vn = 'Ulquiorra phóng người lao thẳng vào chiến tuyến địch với tốc độ xé gió, thanh kiếm phủ đầy linh áp chém xuyên qua hàng ngũ đối phương, gây ra #C0x3D8A99#280% Công Phép Thuật#C0x5B545B# + $(skillLevel*4*24)$#C0xF13B54# Sát Thương Phép Thuật#C0x5B545B# bỏ qua 30% Thủ Phép Thuật của kẻ địch, khiến ngay cả những mục tiêu phòng ngự cũng khó lòng chống đỡ. Khi thi triển đòn tấn công, Ulquiorra nhận được hiệu ứng hút máu, cho phép chuyển hóa #C0x5c9970#15%#C0x5B545B# sát thương gây ra thành hồi máu, kéo dài trong 2 lượt, gia tăng khả năng trụ vững trong giao tranh. Nếu mục tiêu trúng chiêu đang có dưới 50% máu, hắn còn áp lên chúng hiệu ứng <Ăn mòn>, khiến khả năng hồi phục của nạn nhân bị suy yếu nghiêm trọng .\n#F10#\n#F40# <Ăn mòn>: Lượng hồi máu mà kẻ địch nhận được từ đồng đội và các nguồn khác giảm đi 35%, hiệu lực duy trì trong 2 lượt',
		describe_en = 'Ulquiorra dashes straight into the enemy formation with wind-tearing speed, his sword imbued with spiritual energy slicing through the ranks, dealing #C0x3D8A99#280% Magic Power#C0x5B545B# + $(skillLevel*4*24)$#C0xF13B54# Magic Damage#C0x5B545B# ignoring 30% of the enemy\'s Magic Defense, making it difficult even for defensive targets to withstand. Upon executing the attack, Ulquiorra gains a lifesteal effect, converting #C0x5c9970#15%#C0x5B545B# of the damage dealt into healing for 2 turns, enhancing his survivability in battle. If the target hit has less than 50% HP, he applies the <Corrosion> effect, severely weakening the victim\'s healing ability.\n#F10#\n#F40# <Corrosion>: Healing received by the enemy from allies and other sources is reduced by 35%, lasting for 2 turns.',
		describe_th = 'Ulquiorra พุ่งตรงเข้าสู่แนวศัตรูด้วยความเร็วฉีกอากาศ ดาบของเขาเต็มไปด้วยพลังวิญญาณ ฟันผ่านแถวศัตรู สร้างความเสียหาย #C0x3D8A99#280% พลังเวทย์#C0x5B545B# + $(skillLevel*4*24)$#C0xF13B54#ความเสียหายเวทย์#C0x5B545B# ข้าม 30% การป้องกันเวทย์ของศัตรู ทำให้แม้แต่เป้าหมายที่ตั้งรับก็แทบทนไม่ไหว เมื่อใช้ทักษะ Ulquiorra จะได้รับเอฟเฟกต์ดูดเลือด แปลง #C0x5c9970#15%#C0x5B545B# ของความเสียหายที่สร้างเป็นการฟื้นฟู เป็นเวลา 2 เทิร์น เพิ่มความคงทนในการต่อสู้ หากเป้าหมายที่โดนโจมตีนั้นมี HP ต่ำกว่า 50% เขาจะทำให้เกิดเอฟเฟกต์ <กัดกร่อน> ทำให้ความสามารถในการฟื้นฟูของศัตรูลดลงอย่างรุนแรง.\n#F10#\n#F40# <กัดกร่อน>: การฟื้นฟูที่ศัตรูได้รับจากเพื่อนร่วมทีมและแหล่งอื่นลดลง 35% มีผลเป็นเวลา 2 เทิร์น',
		describe_in = 'Ulquiorra melesat langsung ke formasi musuh dengan kecepatan memecah angin, pedangnya yang dipenuhi energi spiritual menebas barisan musuh, memberikan #C0x3D8A99#280% Kekuatan Sihir#C0x5B545B# + $(skillLevel*4*24)$#C0xF13B54#Kerusakan Sihir#C0x5B545B# mengabaikan 30% Pertahanan Sihir musuh, sehingga sulit bagi target bertahan pun untuk menahan. Saat menyerang, Ulquiorra memperoleh efek lifesteal, mengubah #C0x5c9970#15%#C0x5B545B# dari kerusakan yang diberikan menjadi penyembuhan selama 2 giliran, meningkatkan kemampuan bertahan dalam pertempuran. Jika target yang terkena memiliki HP di bawah 50%, dia menerapkan efek <Korosi>, secara signifikan melemahkan kemampuan penyembuhan korban.\n#F10#\n#F40# <Korosi>: Penyembuhan yang diterima musuh dari sekutu dan sumber lain berkurang 35%, berlaku selama 2 giliran.',
		describe_ph = 'Ulquiorra ay sumugod diretso sa hanay ng kaaway nang may bilis na sumasagasaan sa hangin, ang kanyang espada na puno ng espiritwal na enerhiya ay pumuputok sa hanay ng kaaway, nagdudulot ng #C0x3D8A99#280% Magic Power#C0x5B545B# + $(skillLevel*4*24)$#C0xF13B54#Magic Damage#C0x5B545B# na nilalampasan ang 30% ng Magic Defense ng kaaway, na ginagawang mahirap para sa kahit depensibong target na makatiis. Kapag isinagawa ang atake, nakakakuha si Ulquiorra ng lifesteal effect, na nagko-convert ng #C0x5c9970#15%#C0x5B545B# ng pinsalang nagawa sa pagpapagaling sa loob ng 2 turno, pinapalakas ang kakayahang makatiis sa labanan. Kung ang target na tinamaan ay may HP na mas mababa sa 50%, inilalapat niya ang epekto na <Corrosion>, na malubhang nagpapahina sa kakayahan ng biktima sa pagpapagaling.\n#F10#\n#F40# <Corrosion>: Ang healing na natatanggap ng kaaway mula sa mga kakampi at iba pang pinagmulan ay nababawasan ng 35%, tumatagal ng 2 turno.',
		describe_ma = 'Ulquiorra meluru terus ke barisan musuh dengan kelajuan memecah angin, pedangnya dipenuhi tenaga roh menebas barisan lawan, menyebabkan #C0x3D8A99#280% Kuasa Sihir#C0x5B545B# + $(skillLevel*4*24)$#C0xF13B54#Kerusakan Sihir#C0x5B545B# mengabaikan 30% Pertahanan Sihir musuh, menjadikan sasaran bertahan pun sukar menangkis. Semasa menyerang, Ulquiorra menerima kesan lifesteal, menukar #C0x5c9970#15%#C0x5B545B# daripada kerosakan yang diberikan menjadi penyembuhan selama 2 pusingan, meningkatkan daya tahan dalam pertempuran. Jika sasaran yang terkena mempunyai HP kurang dari 50%, dia memberikan kesan <Kakisan>, melemahkan keupayaan penyembuhan mangsa dengan teruk.\n#F10#\n#F40# <Kakisan>: Penyembuhan yang diterima musuh dari sekutu dan sumber lain dikurangkan 35%, berkesan selama 2 pusingan.',
		describe = 'Ulquiorra dashes straight into the enemy formation with wind-tearing speed, his sword imbued with spiritual energy slicing through the ranks, dealing #C0x3D8A99#280% Magic Power#C0x5B545B# + $(skillLevel*4*24)$#C0xF13B54# Magic Damage#C0x5B545B# ignoring 30% of the enemy\'s Magic Defense, making it difficult even for defensive targets to withstand. Upon executing the attack, Ulquiorra gains a lifesteal effect, converting #C0x5c9970#15%#C0x5B545B# of the damage dealt into healing for 2 turns, enhancing his survivability in battle. If the target hit has less than 50% HP, he applies the <Corrosion> effect, severely weakening the victim\'s healing ability.\n#F10#\n#F40# <Corrosion>: Healing received by the enemy from allies and other sources is reduced by 35%, lasting for 2 turns.',
		simDesc_vn = 'Ulquiorra lao vào chém xuyên qua hàng địch,  bỏ qua 30% Thủ Phép thuật của địch. Nếu mục tiêu còn dưới 50% máu, áp dụng hiệu ứng <Ăn mòn>',
		simDesc_en = 'Ulquiorra dashes forward, slashing through enemy lines and ignoring 30% of their Magic Defense. If the target’s HP is below 50%, applies the debuff <Corrosion>.',
		simDesc_th = 'Ulquiorra พุ่งเข้าโจมตีฟันทะลวงแนวศัตรู โดยละเว้น 30% การป้องกันเวทมนตร์ของพวกมัน หากเป้าหมายมี HP ต่ำกว่า 50% จะได้รับเอฟเฟกต์ <การกัดกร่อน>',
		simDesc_in = 'Ulquiorra menerjang dan menebas menembus barisan musuh, mengabaikan 30% Pertahanan Sihir mereka. Jika HP target di bawah 50%, berikan debuff <Korosi>.',
		simDesc_ph = 'Sumugod si Ulquiorra at humiwa nang diretso sa hanay ng mga kalaban, binabalewala ang 30% ng kanilang Magic Defense. Kapag ang HP ng target ay mas mababa sa 50%, inilalapat ang debuff na <Korosyon>.',
		simDesc_ma = 'Ulquiorra menerpa masuk lalu menebas menembusi barisan musuh, mengabaikan 30% Pertahanan Magik mereka. Jika HP sasaran berada di bawah 50%, kesan debuff <Kakisan> akan dikenakan.',
		simDesc = 'Ulquiorra dashes forward, slashing through enemy lines and ignoring 30% of their Magic Defense. If the target’s HP is below 50%, applies the debuff <Corrosion>.',
		iconRes = 'battle/skill_icon/skill_80102.png',
