	[9080103] = {
		id = 9080103,
		skillName_vn = 'Hắc ám huỷ diệt',
		skillName_en = 'Dark Destruction',
		skillName_th = 'การทำลายล้างมืด',
		skillName_in = 'Penghancuran Gelap',
		skillName_ph = 'Dark Destruction',
		skillName_ma = 'Pemusnahan Gelap',
		skillName = 'Hắc ám huỷ diệt',
		describe_vn = 'Ulquiorra tung ra một cú chưởng ma lực cực mạnh, luồng năng lượng xé rách không khí và phá tan đội hình đối phương, để lại những lỗ hổng không thể lành trong cơ thể kẻ địch. Đòn đánh này gây ra #C0x3D8A99#360% Công Phép Thuật#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Sát Thương Phép Thuật#C0x5B545B# bỏ qua đến 40% Thủ Phép Thuật, khiến nạn nhân gần như không còn khả năng chống đỡ sát thương phép. Tất cả mục tiêu trúng chiêu còn bị áp dụng hiệu ứng <Ăn mòn>, kéo dài 2 lượt, khiến mọi nỗ lực hồi phục từ đồng đội trở nên yếu ớt và vô vọng. Đồng thời, luồng năng lượng hỗn mang đó cũng quay ngược lại tiếp thêm sinh lực cho chủ nhân, hồi lại #C0x5c9970#20% lượng máu tối đa#C0x5B545B# của Ulquiorra. Nếu tại thời điểm kích hoạt kỹ năng, máu của Ulquiorra dưới 30%, lượng hồi phục sẽ tăng lên thành #C0x5c9970#30%#C0x5B545B#, giúp hắn sống sót ngoạn mục trong tình thế nguy hiểm..\n#F10#\n#F40#<Ăn mòn>: Lượng hồi máu mà kẻ địch nhận được từ đồng đội và các nguồn khác bị giảm đi 35%.',
		describe_en = 'Ulquiorra unleashes a powerful magical strike, the energy tearing through the air and shattering enemy formations, leaving irreparable gaps in their bodies. This attack deals #C0x3D8A99#360% Magic Power#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Magic Damage#C0x5B545B# ignoring up to 40% Magic Defense, leaving the targets almost defenseless against magic damage. All targets hit are afflicted with the <Corrosion> effect for 2 turns, weakening any healing from allies. At the same time, the chaotic energy flows back to restore #C0x5c9970#20% of Ulquiorra’s Max HP#C0x5B545B#. If Ulquiorra’s HP is below 30% when the skill is activated, the healing increases to #C0x5c9970#30%#C0x5B545B#, allowing him to survive in critical situations..\n#F10#\n#F40#<Corrosion>: Healing received by enemies from allies and other sources is reduced by 35%.',
		describe_th = 'Ulquiorra ปล่อยหมัดเวทย์มหาศาล พลังงานฉีกอากาศและทำลายการจัดแถวของศัตรู ทิ้งช่องว่างที่ไม่สามารถซ่อมแซมในร่างของศัตรู การโจมตีนี้สร้างความเสียหาย #C0x3D8A99#360% พลังเวทย์#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#ความเสียหายเวทย์#C0x5B545B# ข้ามการป้องกันเวทย์ถึง 40% ทำให้เป้าหมายแทบไม่มีทางต้านทานเวทย์ได้ ทุกเป้าหมายที่โดนโจมตีจะได้รับเอฟเฟกต์ <กัดกร่อน> เป็นเวลา 2 เทิร์น ทำให้การฟื้นฟูจากเพื่อนร่วมทีมอ่อนแอและไร้ผล ในขณะเดียวกันพลังงานวุ่นวายนั้นไหลกลับเพื่อฟื้นฟู #C0x5c9970#20% ของ HP สูงสุด#C0x5B545B# ของ Ulquiorra หาก HP ของ Ulquiorra ต่ำกว่า 30% เมื่อสกิลถูกใช้ การฟื้นฟูจะเพิ่มเป็น #C0x5c9970#30%#C0x5B545B# ช่วยให้เขารอดชีวิตในสถานการณ์วิกฤติ..\n#F10#\n#F40#<กัดกร่อน>: การฟื้นฟูที่ศัตรูได้รับจากเพื่อนร่วมทีมและแหล่งอื่นลดลง 35%',
		describe_in = 'Ulquiorra melepaskan serangan sihir yang sangat kuat, energi itu merobek udara dan menghancurkan formasi musuh, meninggalkan lubang yang tidak dapat diperbaiki pada tubuh lawan. Serangan ini memberikan #C0x3D8A99#360% Kekuatan Sihir#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerusakan Sihir#C0x5B545B# mengabaikan hingga 40% Pertahanan Sihir, membuat target hampir tak berdaya terhadap kerusakan sihir. Semua target yang terkena efek <Korosi> selama 2 giliran, melemahkan penyembuhan dari sekutu. Pada saat yang sama, energi kacau itu mengalir kembali untuk memulihkan #C0x5c9970#20% dari HP Maksimum Ulquiorra#C0x5B545B#. Jika HP Ulquiorra di bawah 30% saat keterampilan diaktifkan, pemulihan meningkat menjadi #C0x5c9970#30%#C0x5B545B#, memungkinkan dia bertahan hidup dalam situasi kritis..\n#F10#\n#F40#<Korosi>: Penyembuhan yang diterima musuh dari sekutu dan sumber lain berkurang 35%',
		describe_ph = 'Ulquiorra ay naglabas ng isang napakalakas na magical strike, ang enerhiya nito ay yumanig sa hangin at winasak ang hanay ng kaaway, nag-iiwan ng hindi maayos na butas sa katawan ng kalaban. Ang pag-atakeng ito ay nagdudulot ng #C0x3D8A99#360% Magic Power#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Magic Damage#C0x5B545B# na nilalampasan ang hanggang 40% ng Magic Defense, halos walang kakayahang depensahan ng target ang pinsalang magic. Lahat ng target na tinamaan ay magkakaroon ng epekto <Corrosion> sa loob ng 2 turno, nagpapahina sa healing mula sa mga kakampi. Kasabay nito, ang magulong enerhiya ay bumabalik upang maibalik ang #C0x5c9970#20% ng Max HP ni Ulquiorra#C0x5B545B#. Kung ang HP ni Ulquiorra ay mababa sa 30% sa oras ng paggamit ng skill, ang healing ay tumataas sa #C0x5c9970#30%#C0x5B545B#, na nagbibigay-daan sa kanya na mabuhay sa kritikal na sitwasyon..\n#F10#\n#F40#<Corrosion>: Ang healing na natatanggap ng kaaway mula sa kakampi at iba pang pinagmulan ay nababawasan ng 35%',
		describe_ma = 'Ulquiorra melepaskan serangan sihir yang amat kuat, tenaga itu merobek udara dan memusnahkan formasi musuh, meninggalkan lubang yang tidak dapat diperbaiki dalam tubuh lawan. Serangan ini memberikan #C0x3D8A99#360% Kuasa Sihir#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerusakan Sihir#C0x5B545B# mengabaikan sehingga 40% Pertahanan Sihir, menjadikan sasaran hampir tidak mampu menahan kerosakan sihir. Semua sasaran terkena kesan <Kakisan> selama 2 pusingan, melemahkan penyembuhan dari sekutu. Pada masa yang sama, tenaga kacau itu kembali untuk memulihkan #C0x5c9970#20% daripada HP Maksimum Ulquiorra#C0x5B545B#. Jika HP Ulquiorra di bawah 30% semasa kemahiran diaktifkan, pemulihan meningkat kepada #C0x5c9970#30%#C0x5B545B#, membolehkannya terus hidup dalam situasi kritikal..\n#F10#\n#F40#<Kakisan>: Penyembuhan yang diterima musuh dari sekutu dan sumber lain dikurangkan 35%',
		describe = 'Ulquiorra unleashes a powerful magical strike, the energy tearing through the air and shattering enemy formations, leaving irreparable gaps in their bodies. This attack deals #C0x3D8A99#360% Magic Power#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Magic Damage#C0x5B545B# ignoring up to 40% Magic Defense, leaving the targets almost defenseless against magic damage. All targets hit are afflicted with the <Corrosion> effect for 2 turns, weakening any healing from allies. At the same time, the chaotic energy flows back to restore #C0x5c9970#20% of Ulquiorra’s Max HP#C0x5B545B#. If Ulquiorra’s HP is below 30% when the skill is activated, the healing increases to #C0x5c9970#30%#C0x5B545B#, allowing him to survive in critical situations..\n#F10#\n#F40#<Corrosion>: Healing received by enemies from allies and other sources is reduced by 35%.',
		simDesc_vn = 'Ulquiorra chướng mạnh xé rách đội hình địch để lại những lỗ hổng không thể lành trong cơ thể kẻ địch bỏ qua 40% Thủ Phép thuật của địch, áp dụng hiệu ứng <Ăn mòn>, kéo dài 2 lượt.',
		simDesc_en = 'Ulquiorra unleashes a powerful strike that tears through enemy lines, leaving unhealable wounds. Ignores 40% of enemy Magic Defense and applies the debuff <Corrosion> for 2 turns.',
		simDesc_th = 'Ulquiorra ฟาดฟันอย่างรุนแรง ฉีกกระชากแนวศัตรู ทิ้งบาดแผลที่ไม่อาจรักษาได้ โดยละเว้น 40% การป้องกันเวทมนตร์ของศัตรู และมอบเอฟเฟกต์ <การกัดกร่อน> เป็นเวลา 2 เทิร์น',
		simDesc_in = 'Ulquiorra menghantam dengan tebasan kuat yang merobek barisan musuh, meninggalkan luka yang tak bisa disembuhkan. Mengabaikan 40% Pertahanan Sihir musuh dan memberikan debuff <Korosi> selama 2 giliran.',
		simDesc_ph = 'Si Ulquiorra ay nagpakawala ng malakas na hiwa na pumupunit sa hanay ng kalaban, nag-iiwan ng mga sugat na hindi magagamot. Binabalewala ang 40% ng Magic Defense ng kalaban at naglalapat ng debuff <Korosyon> sa loob ng 2 turn.',
		simDesc_ma = 'Ulquiorra melepaskan serangan kuat yang mengoyakkan barisan musuh, meninggalkan luka yang tidak dapat dipulihkan. Mengabaikan 40% Pertahanan Magik musuh dan mengenakan debuff <Kakisan> selama 2 pusingan.',
		simDesc = 'Ulquiorra unleashes a powerful strike that tears through enemy lines, leaving unhealable wounds. Ignores 40% of enemy Magic Defense and applies the debuff <Corrosion> for 2 turns.',
		starEffect = __data_t__starEffect[9080103],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng xuyên Thủ Phép Thuật được nâng cấp, đạt mức tối đa 50%, giúp đòn đánh xuyên phá phòng ngự phép của đối phương một cách hiệu quả hơn. Song song đó, hiệu ứng <Ăn mòn> cũng được cường hóa: giảm 50% khả năng hồi máu từ mọi nguồn của kẻ địch, và duy trì trong 3 lượt, khiến mục tiêu gần như không thể hồi phục như bình thường.\nVề phần phục hồi, Ulquiorra sau khi thi triển Hắc Ám Quỷ Diệt sẽ được hồi 25% lượng máu tối đa, mang lại lợi thế sống sót đáng kể trong giao tranh. Đặc biệt, nếu tại thời điểm sử dụng chiêu thức, máu của Ulquiorra thấp hơn 30%, lượng hồi phục sẽ đượctăng mạnh lên 35% máu tối đa, biến hắn thành một cơn ác mộng thực sự khi ở bên bờ vực tử vong.',
		starEffectDesc = 'The Magic Defense Penetration effect is upgraded, reaching up to 50%, allowing attacks to break through enemy magic defenses more effectively. At the same time, the <Corrosion> effect is enhanced: reducing enemy healing from all sources by 50% and lasting for 3 turns, making it nearly impossible for the target to recover normally.\nAs for recovery, after casting Dark Demon Destruction, Ulquiorra restores 25% of his Max HP, granting significant survivability in battle. Especially, if Ulquiorra’s HP is below 30% when the skill is used, the recovery is greatly increased to 35% of his Max HP, turning him into a true nightmare on the brink of death.',
		starEffectDesc_en = 'The Magic Defense Penetration effect is upgraded, reaching up to 50%, allowing attacks to break through enemy magic defenses more effectively. At the same time, the <Corrosion> effect is enhanced: reducing enemy healing from all sources by 50% and lasting for 3 turns, making it nearly impossible for the target to recover normally.\nAs for recovery, after casting Dark Demon Destruction, Ulquiorra restores 25% of his Max HP, granting significant survivability in battle. Especially, if Ulquiorra’s HP is below 30% when the skill is used, the recovery is greatly increased to 35% of his Max HP, turning him into a true nightmare on the brink of death.',
		starEffectDesc_th = 'เอฟเฟกต์เจาะเกราะเวทมนตร์ได้รับการอัปเกรด สูงสุดถึง 50% ทำให้การโจมตีสามารถทะลุการป้องกันเวทของศัตรูได้อย่างมีประสิทธิภาพยิ่งขึ้น พร้อมกันนี้ เอฟเฟกต์ <Corrosion> ก็ได้รับการเสริมพลัง: ลดประสิทธิภาพการฟื้นฟู HP ของศัตรูจากทุกแหล่งลง 50% และคงอยู่ 3 เทิร์น ทำให้เป้าหมายแทบไม่สามารถฟื้นฟูได้ตามปกติ.\nสำหรับการฟื้นฟู Ulquiorra หลังจากใช้ท่า Dark Demon Destruction จะฟื้นคืน HP 25% ของ HP สูงสุด มอบความได้เปรียบในการเอาตัวรอดอย่างมากในระหว่างการต่อสู้ โดยเฉพาะอย่างยิ่ง หาก HP ของ Ulquiorra ต่ำกว่า 30% ในขณะที่ใช้สกิล การฟื้นฟูจะเพิ่มขึ้นเป็น 35% ของ HP สูงสุด ทำให้เขากลายเป็นฝันร้ายที่แท้จริงเมื่ออยู่บนขอบเหวแห่งความตาย',
		starEffectDesc_in = 'Efek Penetrasi Pertahanan Sihir ditingkatkan, mencapai hingga 50%, membuat serangan lebih efektif menembus pertahanan sihir musuh. Pada saat yang sama, efek <Corrosion> diperkuat: mengurangi 50% kemampuan pemulihan HP musuh dari semua sumber dan berlangsung selama 3 giliran, membuat target hampir tidak bisa pulih seperti biasanya.\nUntuk pemulihan, setelah menggunakan Dark Demon Destruction, Ulquiorra memulihkan 25% dari HP Maksimum, memberikan keuntungan besar dalam bertahan hidup di pertempuran. Terutama, jika HP Ulquiorra kurang dari 30% saat skill digunakan, pemulihan meningkat menjadi 35% dari HP Maksimum, menjadikannya mimpi buruk sejati di ambang kematian.',
		starEffectDesc_ph = 'Ang Magic Defense Penetration effect ay na-upgrade, umaabot hanggang 50%, na nagbibigay-daan sa mga atake na mas epektibong makalusot sa magic defense ng kalaban. Kasabay nito, ang <Corrosion> effect ay pinalakas: binabawasan ng 50% ang kakayahan ng kalaban na mag-heal mula sa anumang pinagmulan, tumatagal ng 3 turn, na halos imposibleng makabawi nang normal ang target.\nPara sa recovery, pagkatapos gamitin ang Dark Demon Destruction, si Ulquiorra ay nagre-restore ng 25% ng kanyang Max HP, nagbibigay ng malaking kalamangan sa survivability sa laban. Lalo na kung ang HP ni Ulquiorra ay mas mababa sa 30% sa oras ng paggamit ng skill, tataas ang healing sa 35% ng kanyang Max HP, ginagawang isang tunay na bangungot kapag nasa bingit ng kamatayan.',
		starEffectDesc_ma = 'Kesan Penembusan Pertahanan Magik telah dipertingkat, mencapai sehingga 50%, membolehkan serangan menembusi pertahanan magik musuh dengan lebih berkesan. Pada masa yang sama, kesan <Corrosion> turut diperkasa: mengurangkan 50% keupayaan pemulihan HP musuh daripada semua sumber dan berkekalan selama 3 giliran, menjadikan sasaran hampir mustahil untuk pulih seperti biasa.\nBagi pemulihan, selepas menggunakan Dark Demon Destruction, Ulquiorra akan memulihkan 25% daripada HP Maksimum, memberi kelebihan besar untuk kelangsungan hidup dalam pertarungan. Terutamanya, jika HP Ulquiorra berada di bawah 30% ketika skill digunakan, jumlah pemulihan meningkat kepada 35% daripada HP Maksimum, menjadikannya satu mimpi ngeri sebenar ketika berada di ambang kematian.',
		iconRes = 'battle/skill_icon/skill_80103.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 2,
		skillDamageType = 1,
		skillNatureType = 16,
