	},
	[9080104] = {
		id = 9080104,
		skillName_vn = 'Tái tạo thần tốc',
		skillName_en = 'Rapid Regeneration',
		skillName_th = 'ฟื้นฟูเร็ว',
		skillName_in = 'Regenerasi Cepat',
		skillName_ph = 'Mabilis na Regeneration',
		skillName_ma = 'Regenerasi Pantas',
		skillName = 'Tái tạo thần tốc',
		describe_vn = 'Khả năng đặc biệt của Ulquiorra cho phép hắn hồi phục với tốc độ phi thường. Mỗi khi nhận sát thương từ kẻ địch, Ulquiorra ngay lập tức tái tạo sinh lực, phục hồi #C0x5c9970#4% máu tối đa#C0x5B545B# + $(skillLevel*4*12)$. Tuy nhiên, khi rơi vào trạng thái nguy hiểm, hiệu quả hồi phục sẽ được gia tăng mạnh mẽ — nếu lượng máu hiện tại của hắn giảm xuống dưới 30%, thì tỉ lệ hồi phục tăng lên lên đến #C0x5c9970#8% máu tối đa#C0x5B545B#, giúp Ulquiorra sinh tồn bền bỉ và tiếp tục chiến đấu trong những tình huống khốc liệt nhất.',
		describe_en = 'Ulquiorra\'s special ability allows him to recover at an extraordinary rate. Whenever he takes damage from enemies, Ulquiorra instantly regenerates, restoring #C0x5c9970#4% of Max HP#C0x5B545B# + $(skillLevel*4*12)$. However, when in a critical state, the healing effect is greatly enhanced — if his current HP falls below 30%, the recovery rate increases up to #C0x5c9970#8% of Max HP#C0x5B545B#, allowing Ulquiorra to survive tenaciously and continue fighting in the most intense situations.',
		describe_th = 'ความสามารถพิเศษของ Ulquiorra ทำให้เขาฟื้นฟูได้อย่างรวดเร็วทุกครั้งที่ได้รับความเสียหายจากศัตรู Ulquiorra จะฟื้นฟูทันที, คืน #C0x5c9970#4% ของ HP สูงสุด#C0x5B545B# + $(skillLevel*4*12)$. อย่างไรก็ตาม เมื่ออยู่ในสถานะวิกฤติ ผลการฟื้นฟูจะเพิ่มขึ้นอย่างมาก — หาก HP ปัจจุบันของเขาต่ำกว่า 30% อัตราการฟื้นฟูจะเพิ่มขึ้นเป็น #C0x5c9970#8% ของ HP สูงสุด#C0x5B545B#, ช่วยให้ Ulquiorra มีชีวิตอยู่ต่อไปและต่อสู้ได้ในสถานการณ์ที่รุนแรงที่สุด',
		describe_in = 'Kemampuan khusus Ulquiorra memungkinkannya pulih dengan kecepatan luar biasa. Setiap kali menerima kerusakan dari musuh, Ulquiorra langsung meregenerasi, memulihkan #C0x5c9970#4% HP Maksimum#C0x5B545B# + $(skillLevel*4*12)$. Namun, saat berada dalam kondisi kritis, efek penyembuhan meningkat secara signifikan — jika HP saat ini turun di bawah 30%, tingkat pemulihan meningkat hingga #C0x5c9970#8% HP Maksimum#C0x5B545B#, memungkinkan Ulquiorra bertahan dengan gigih dan terus bertarung dalam situasi paling sengit.',
		describe_ph = 'Ang espesyal na kakayahan ni Ulquiorra ay nagbibigay-daan sa kanya na makabawi sa pambihirang bilis. Sa tuwing tumatanggap ng pinsala mula sa mga kaaway, agad na nagrerehenereta si Ulquiorra, nagbabalik ng #C0x5c9970#4% ng Max HP#C0x5B545B# + $(skillLevel*4*12)$. Gayunpaman, kapag nasa kritikal na estado, ang epekto ng pagpapagaling ay malaki ang pagtaas — kung ang kasalukuyang HP niya ay bumaba sa ilalim ng 30%, tumataas ang rate ng pagbawi hanggang sa #C0x5c9970#8% ng Max HP#C0x5B545B#, na nagpapahintulot kay Ulquiorra na manatiling buhay at magpatuloy sa pakikipaglaban sa pinakamahihirap na sitwasyon.',
		describe_ma = 'Keupayaan istimewa Ulquiorra membolehkan dia pulih pada kadar luar biasa. Setiap kali menerima kerosakan daripada musuh, Ulquiorra segera meremajakan, memulihkan #C0x5c9970#4% HP Maksimum#C0x5B545B# + $(skillLevel*4*12)$. Namun, apabila berada dalam keadaan kritikal, kesan penyembuhan meningkat dengan ketara — jika HP semasa beliau turun di bawah 30%, kadar pemulihan meningkat sehingga #C0x5c9970#8% HP Maksimum#C0x5B545B#, membolehkan Ulquiorra terus bertahan dan berjuang dalam situasi yang paling getir.',
		describe = 'Ulquiorra\'s special ability allows him to recover at an extraordinary rate. Whenever he takes damage from enemies, Ulquiorra instantly regenerates, restoring #C0x5c9970#4% of Max HP#C0x5B545B# + $(skillLevel*4*12)$. However, when in a critical state, the healing effect is greatly enhanced — if his current HP falls below 30%, the recovery rate increases up to #C0x5c9970#8% of Max HP#C0x5B545B#, allowing Ulquiorra to survive tenaciously and continue fighting in the most intense situations.',
		simDesc_vn = ' Mỗi khi chịu sát thương, sẽ hồi lại máu.',
		simDesc_en = 'Restores HP whenever damage is taken.',
		simDesc_th = 'ฟื้นฟู HP ทุกครั้งที่ได้รับความเสียหาย',
		simDesc_in = 'Memulihkan HP setiap kali menerima damage.',
		simDesc_ph = 'Nagbabalik ng HP tuwing tumatanggap ng pinsala.',
		simDesc_ma = 'Memulihkan HP setiap kali menerima kerosakan.',
		simDesc = 'Restores HP whenever damage is taken.',
		starEffect = __data_t__starEffect[9080104],
		-- {8}
		starEffectDesc_vn = 'Khả năng hồi phục của Ulquiorra được nâng lên một tầm cao mới. Mỗi khi chịu sát thương từ kẻ địch, hắn không chỉ phục hồi như trước mà lượng hồi máu tăng lên thành 8% máu tối đa, giúp hắn duy trì thể trạng trong những pha giao tranh dữ dội. Đặc biệt, khi Ulquiorra bị dồn vào tình thế nguy cấp — lượng máu còn lại dưới 30%, hiệu quả hồi phục đạt đỉnh, lên tới 12% máu tối đa, biến hắn thành một cỗ máy bất tử khó bị đánh gục.',
		starEffectDesc = 'Ulquiorra’s recovery ability is elevated to a new level. Each time he takes damage from enemies, he not only recovers as before but the healing is increased to 8% of his Max HP, allowing him to endure during intense battles. Especially, when Ulquiorra is pushed into a critical state — with less than 30% HP remaining, the recovery effect peaks at 12% of his Max HP, turning him into an immortal machine that is extremely hard to defeat.',
		starEffectDesc_en = 'Ulquiorra’s recovery ability is elevated to a new level. Each time he takes damage from enemies, he not only recovers as before but the healing is increased to 8% of his Max HP, allowing him to endure during intense battles. Especially, when Ulquiorra is pushed into a critical state — with less than 30% HP remaining, the recovery effect peaks at 12% of his Max HP, turning him into an immortal machine that is extremely hard to defeat.',
		starEffectDesc_th = 'ความสามารถในการฟื้นฟูของ Ulquiorra ถูกยกระดับขึ้นไปอีกขั้น ทุกครั้งที่ได้รับความเสียหายจากศัตรู เขาจะไม่เพียงฟื้นฟูตามปกติ แต่ปริมาณการฟื้นฟูเพิ่มขึ้นเป็น 8% ของ HP สูงสุด ช่วยให้เขายืนหยัดได้ในศึกที่ดุเดือด โดยเฉพาะเมื่อ Ulquiorra ตกอยู่ในสถานการณ์วิกฤต — HP เหลือต่ำกว่า 30% ประสิทธิภาพการฟื้นฟูจะสูงสุดถึง 12% ของ HP สูงสุด ทำให้เขากลายเป็นเครื่องจักรอมตะที่ยากจะถูกโค่นล้ม',
		starEffectDesc_in = 'Kemampuan pemulihan Ulquiorra meningkat ke tingkat yang lebih tinggi. Setiap kali menerima damage dari musuh, ia tidak hanya memulihkan seperti sebelumnya, tetapi jumlah healing bertambah menjadi 8% dari HP Maksimum, membantunya bertahan dalam pertempuran sengit. Terutama, saat Ulquiorra berada dalam keadaan kritis — dengan HP tersisa di bawah 30%, efek pemulihan memuncak hingga 12% dari HP Maksimum, menjadikannya mesin abadi yang sangat sulit dikalahkan.',
		starEffectDesc_ph = 'Ang kakayahan sa pag-recover ni Ulquiorra ay umangat sa mas mataas na antas. Sa tuwing siya ay tumatanggap ng damage mula sa kalaban, hindi lang siya nag-heal tulad ng dati kundi tumataas pa sa 8% ng kanyang Max HP, na tumutulong sa kanya na manatiling matatag sa matitinding labanan. Lalo na kapag si Ulquiorra ay nasa kritikal na kalagayan — may natitirang mas mababa sa 30% HP, ang healing effect ay umaabot hanggang 12% ng kanyang Max HP, ginagawa siyang isang imortal na makina na napakahirap talunin.',
		starEffectDesc_ma = 'Keupayaan pemulihan Ulquiorra dinaikkan ke tahap yang lebih tinggi. Setiap kali dia menerima kerosakan daripada musuh, dia bukan sahaja pulih seperti sebelumnya malah jumlah pemulihan meningkat kepada 8% daripada HP Maksimum, membantunya bertahan dalam pertempuran sengit. Terutamanya, apabila Ulquiorra berada dalam keadaan kritikal — baki HP kurang daripada 30%, kesan pemulihan memuncak hingga 12% daripada HP Maksimum, menjadikannya mesin abadi yang amat sukar untuk ditewaskan.',
		iconRes = 'battle/skill_icon/skill_80104.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {90801041}
	},
