	[9080112] = {
		id = 9080112,
		skillName_vn = 'Pháo bóng tối huỷ diệt',
		skillName_en = 'Darkness Cannon Destruction',
		skillName_th = 'ปืนใหญ่ความมืดทำลายล้าง',
		skillName_in = 'Meriam Kegelapan Penghancur',
		skillName_ph = 'Darkness Cannon Destruction',
		skillName_ma = 'Meriam Kegelapan Pemusnah',
		skillName = 'Pháo bóng tối huỷ diệt',
		describe_vn = 'Ulquiorra sử dụng ngón tay của mình phóng ra nguồn pháo bóng tối mang năng lượng tử vong, oanh tạc thẳng vào đội hình địch, gây ra #C0x3D8A99#280% Công Phép Thuật#C0x5B545B#+ $(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật#C0x5B545B# Đòn tấn công hung tàn này xuyên thủ 30% Thủ Phép thuật của kẻ địch, khiến mọi lớp phòng thủ phép đều bị xé toạc như tờ giấy. Ngay sau khi tung chiêu, Ulquiorra kích hoạt trạng thái hấp huyết, đạt được khả năng hút máu 15% từ mọi sát thương gây ra trong 2 lượt kế tiếp — một cơ chế giúp hắn duy trì thể lực giữa vòng vây kẻ địch. Nếu mục tiêu trúng pháo đang còn dưới 50% máu, chúng sẽ lập tức bị áp đặt hiệu ứng <Ăn mòn>, khiến khả năng hồi phục của chúng từ đồng đội và các nguồn khác bị giảm đi 35%, kéo dài trong 2 lượt.\n<Dơi - Giai đoạn hai>: Trong hình thái tối thượng, kỹ năng này trở nên càng đáng sợ hơn khi sát thương được tăng thêm 15% dựa trên lượng máu hiện tại của Ulquiorra. Không chỉ vậy, tất cả mục tiêu trúng đòn còn bị giảm 18% Thủ Phép thuật, kéo dài 2 lượt — khiến chúng càng dễ gục ngã trước những đòn đánh tiếp theo như thể đang dần bị nuốt chửng bởi bóng tối tuyệt vọng.',
		describe_en = 'Ulquiorra uses his finger to fire a deathly dark cannonball, striking straight into the enemy formation, dealing #C0x3D8A99#280% Magic Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Magic Damage#C0x5B545B#. This ferocious attack penetrates 30% of the enemy\'s Magic Defense, tearing through all magical layers as if they were paper. Immediately after casting, Ulquiorra activates Bloodsucking state, gaining 15% life steal from all damage dealt for the next 2 turns — a mechanism that helps him sustain himself amidst enemy lines. If the target hit by the cannon has less than 50% HP, they are immediately afflicted with <Corrosion>, reducing healing received from allies and other sources by 35% for 2 turns.\n<Bat – Phase Two>: In his ultimate form, this skill becomes even more terrifying as damage is increased by 15% based on Ulquiorra’s current HP. Moreover, all targets hit have their Magic Defense reduced by 18% for 2 turns — making them even easier to fall to subsequent attacks as if gradually being consumed by the darkness of despair.',
		describe_th = 'Ulquiorra ใช้นิ้วของเขาปล่อยกระสุนมืดที่มีพลังแห่งความตาย พุ่งตรงเข้าสู่แนวศัตรู สร้างความเสียหาย #C0x3D8A99#280% พลังเวทย์#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#ความเสียหายเวทย์#C0x5B545B#. การโจมตีรุนแรงนี้เจาะทะลุ 30% การป้องกันเวทย์ของศัตรู ทำลายทุกชั้นป้องกันเหมือนกระดาษ ทันทีหลังการปล่อยสกิล Ulquiorra เปิดใช้งานสถานะดูดเลือด รับความสามารถในการดูดเลือด 15% จากความเสียหายทั้งหมดเป็นเวลา 2 ตาต่อไป — กลไกที่ช่วยให้เขารักษาสภาพร่างกายท่ามกลางแนวศัตรู หากเป้าหมายที่ถูกโจมตีมี HP ต่ำกว่า 50% พวกเขาจะติดสถานะ <การกัดกร่อน> ลดการฟื้นฟูจากเพื่อนร่วมทีมและแหล่งอื่นลง 35% เป็นเวลา 2 ตา.\n<ค้างคาว – ระยะที่สอง>: ในรูปแบบสูงสุด สกิลนี้น่ากลัวขึ้นอีกด้วยการเพิ่มความเสียหาย 15% ตาม HP ปัจจุบันของ Ulquiorra ยิ่งไปกว่านั้น เป้าหมายทั้งหมดที่ถูกโจมตีจะมีการป้องกันเวทย์ลดลง 18% เป็นเวลา 2 ตา — ทำให้พวกเขาง่ายต่อการพ่ายแพ้ต่อการโจมตีต่อไปราวกับค่อยๆ ถูกกลืนกินโดยความมืดแห่งความสิ้นหวัง',
		describe_in = 'Ulquiorra menggunakan jarinya untuk menembakkan peluru gelap mematikan, menghantam langsung ke formasi musuh, menyebabkan #C0x3D8A99#280% Serangan Sihir#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerusakan Sihir#C0x5B545B#. Serangan brutal ini menembus 30% Pertahanan Sihir musuh, merobek semua lapisan pertahanan sihir seperti kertas. Segera setelah meluncurkan skill, Ulquiorra mengaktifkan status Bloodsucking, mendapatkan 15% life steal dari semua damage yang diberikan selama 2 giliran berikutnya — mekanisme yang membantunya bertahan di tengah garis musuh. Jika target yang terkena peluru memiliki HP kurang dari 50%, mereka langsung terkena efek <Corrosion>, mengurangi pemulihan dari sekutu dan sumber lain sebesar 35% selama 2 giliran.\n<Bat – Fase Dua>: Dalam bentuk ultimate, skill ini menjadi lebih menakutkan karena damage meningkat 15% berdasarkan HP saat ini Ulquiorra. Selain itu, semua target yang terkena serangan memiliki Pertahanan Sihir berkurang 18% selama 2 giliran — membuat mereka lebih mudah jatuh ke serangan berikutnya seolah-olah perlahan-lahan ditelan oleh kegelapan keputusasaan.',
		describe_ph = 'Ulquiorra ay gumagamit ng kanyang daliri upang magpaputok ng mapaminsalang itim na bala, tumatama nang direkta sa pormasyon ng kaaway, na nagdudulot ng #C0x3D8A99#280% Magic Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Magic Damage#C0x5B545B#. Ang marahas na atake na ito ay tumatagos ng 30% ng Magic Defense ng kalaban, na parang punitin ang lahat ng layer ng depensa ng mahika tulad ng papel. Agad pagkatapos gamitin ang kakayahan, Ulquiorra ay nag-activate ng Bloodsucking state, nakakakuha ng 15% life steal mula sa lahat ng pinsalang naibigay sa loob ng 2 turn — mekanismo na tumutulong sa kanya na manatiling matatag sa gitna ng mga linya ng kaaway. Kung ang target na tinamaan ng bala ay may HP na mas mababa sa 50%, sila ay agad na magkakaroon ng epekto <Corrosion>, binabawasan ang pagpapagaling mula sa mga kakampi at iba pang pinagmulan ng 35% sa loob ng 2 turn.\n<Bat – Phase Two>: Sa ultimate form niya, ang kakayahang ito ay nagiging mas nakakatakot dahil nadadagdagan ang pinsala ng 15% base sa kasalukuyang HP ni Ulquiorra. Bukod dito, lahat ng target na tinamaan ay nababawasan ang Magic Defense ng 18% sa loob ng 2 turn — na ginagawang mas madali silang mapabagsak sa mga kasunod na atake na tila unti-unting nilulun',
		describe_ma = 'Ulquiorra menggunakan jarinya untuk menembak peluru gelap maut, menyerang terus ke barisan musuh, menyebabkan #C0x3D8A99#280% Serangan Sihir#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerusakan Sihir#C0x5B545B#. Serangan ganas ini menembusi 30% Pertahanan Sihir musuh, merobek semua lapisan pertahanan sihir seperti kertas. Segera selepas melepaskan kemahiran, Ulquiorra mengaktifkan keadaan Bloodsucking, memperoleh 15% life steal daripada semua kerosakan yang diberikan selama 2 giliran berikutnya — mekanisme yang membantunya kekal bertahan di tengah barisan musuh. Jika sasaran yang terkena peluru mempunyai HP kurang daripada 50%, mereka segera terkena kesan <Corrosion>, mengurangkan pemulihan daripada rakan sepasukan dan sumber lain sebanyak 35% selama 2 giliran.\n<Kelawar – Fasa Dua>: Dalam bentuk ultimate, kemahiran ini menjadi lebih menakutkan kerana kerosakan meningkat 15% berdasarkan HP semasa Ulquiorra. Selain itu, semua sasaran yang terkena serangan mempunyai Pertahanan Sihir berkurang 18% selama 2 giliran — menjadikan mereka lebih mudah tewas kepada serangan seterusnya seolah-olah perlahan-lahan ditelan oleh kegelapan keputusasaan.',
		describe = 'Ulquiorra uses his finger to fire a deathly dark cannonball, striking straight into the enemy formation, dealing #C0x3D8A99#280% Magic Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Magic Damage#C0x5B545B#. This ferocious attack penetrates 30% of the enemy\'s Magic Defense, tearing through all magical layers as if they were paper. Immediately after casting, Ulquiorra activates Bloodsucking state, gaining 15% life steal from all damage dealt for the next 2 turns — a mechanism that helps him sustain himself amidst enemy lines. If the target hit by the cannon has less than 50% HP, they are immediately afflicted with <Corrosion>, reducing healing received from allies and other sources by 35% for 2 turns.\n<Bat – Phase Two>: In his ultimate form, this skill becomes even more terrifying as damage is increased by 15% based on Ulquiorra’s current HP. Moreover, all targets hit have their Magic Defense reduced by 18% for 2 turns — making them even easier to fall to subsequent attacks as if gradually being consumed by the darkness of despair.',
		simDesc_vn = 'Ulquiorra kích hoạt kỹ năng đặc trưng – Pháo Bóng Tối, bắn ra luồng năng lượng hủy diệt xuyên thủng đội hình địch, bỏ qua 30% Thủ Phép thuật, nhận hiệu ứng hút máu 15% trong 2 lượt; nếu mục tiêu dưới 50% máu sẽ bị <Ăn mòn>, giảm 50% hồi phục trong 2 lượt.',
		simDesc_en = 'Ulquiorra activates his signature skill – Dark Cero, unleashing a destructive blast that pierces enemy lines, ignoring 30% of their Magic Defense. Gains 15% Lifesteal for 2 turns; if the target’s HP is below 50%, inflicts <Corrosion>, reducing healing received by 50% for 2 turns.',
		simDesc_th = 'Ulquiorra ปลดปล่อยสกิลประจำตัว – ปืนใหญ่แห่งความมืด ยิงพลังทำลายล้างทะลวงแนวศัตรู โดยละเว้น 30% การป้องกันเวทมนตร์ ได้รับเอฟเฟกต์ดูดเลือด 15% เป็นเวลา 2 เทิร์น; หากเป้าหมายมี HP ต่ำกว่า 50% จะถูก <การกัดกร่อน> ลดการฟื้นฟูลง 50% เป็นเวลา 2 เทิร์น',
		simDesc_in = 'Ulquiorra mengaktifkan skill khasnya – Meriam Kegelapan, menembakkan energi destruktif yang menembus barisan musuh, mengabaikan 30% Pertahanan Sihir. Mendapatkan efek Lifesteal 15% selama 2 giliran; jika HP target di bawah 50%, terkena <Korosi> yang mengurangi pemulihan sebesar 50% selama 2 giliran.',
		simDesc_ph = 'Inilabas ni Ulquiorra ang kanyang natatanging kasanayan – Kanyon ng Kadiliman, nagpapakawala ng mapanirang enerhiya na tumatagos sa hanay ng kaaway, binabalewala ang 30% ng kanilang Magic Defense. Nakakakuha siya ng 15% Lifesteal sa loob ng 2 turn; kung ang HP ng target ay mas mababa sa 50%, maaapektuhan ito ng <Korosyon>, na nagpapababa ng healing ng 50% sa loob ng 2 turn.',
		simDesc_ma = 'Ulquiorra mengaktifkan kemahiran khasnya – Meriam Kegelapan, melepaskan tenaga pemusnah yang menembusi barisan musuh, mengabaikan 30% Pertahanan Magik. Mendapat kesan Hisap Nyawa 15% selama 2 pusingan; jika HP sasaran berada di bawah 50%, dikenakan <Kakisan>, mengurangkan pemulihan sebanyak 50% selama 2 pusingan.',
		simDesc = 'Ulquiorra activates his signature skill – Dark Cero, unleashing a destructive blast that pierces enemy lines, ignoring 30% of their Magic Defense. Gains 15% Lifesteal for 2 turns; if the target’s HP is below 50%, inflicts <Corrosion>, reducing healing received by 50% for 2 turns.',
		zawakeEffect = __data_t__zawakeEffect[9080112],
		-- {79002}
		zawakeEffectDesc = 'Ulquiorra fires a finger-propelled dark cannon infused with deadly energy straight into the enemy formation, dealing #C0x3D8A99#280% Magic Power#C0x5B545B#+ $(skillLevel*4*24)$ #C0xF13B54# Magic Damage#C0x5B545B#. This brutal attack penetrates 30% of the enemy’s Magic Defense, shredding all layers of magical protection like paper. Immediately after casting, Ulquiorra activates Bloodsucking, gaining 15% lifesteal from all damage dealt for the next 2 turns — a mechanism that sustains him amid enemy encirclement. If the target hit is below 50% HP, they are instantly afflicted with <Erosion>, reducing healing from allies and other sources by 35% for 2 turns.\n<Bat - Phase Two>: In his ultimate form, this skill becomes even more terrifying as its damage increases by 15% based on Ulquiorra’s current HP. Additionally, all targets hit have their Magic Defense reduced by 25% for 2 turns — making them increasingly vulnerable to follow-up attacks as if being consumed by the despairing darkness.',
		zawakeEffectDesc_en = 'Ulquiorra fires a finger-propelled dark cannon infused with deadly energy straight into the enemy formation, dealing #C0x3D8A99#280% Magic Power#C0x5B545B#+ $(skillLevel*4*24)$ #C0xF13B54# Magic Damage#C0x5B545B#. This brutal attack penetrates 30% of the enemy’s Magic Defense, shredding all layers of magical protection like paper. Immediately after casting, Ulquiorra activates Bloodsucking, gaining 15% lifesteal from all damage dealt for the next 2 turns — a mechanism that sustains him amid enemy encirclement. If the target hit is below 50% HP, they are instantly afflicted with <Erosion>, reducing healing from allies and other sources by 35% for 2 turns.\n<Bat - Phase Two>: In his ultimate form, this skill becomes even more terrifying as its damage increases by 15% based on Ulquiorra’s current HP. Additionally, all targets hit have their Magic Defense reduced by 25% for 2 turns — making them increasingly vulnerable to follow-up attacks as if being consumed by the despairing darkness.',
		zawakeEffectDesc_th = 'Ulquiorra ใช้นิ้วของเขาปล่อยปืนใหญ่แห่งความมืดที่เต็มไปด้วยพลังร้ายแรง โจมตีตรงเข้าสู่กองกำลังศัตรู สร้างความเสียหาย #C0x3D8A99#280% พลังเวทย์#C0x5B545B#+ $(skillLevel*4*24)$ #C0xF13B54#ความเสียหายเวทย์#C0x5B545B# การโจมตีอันโหดร้ายนี้เจาะทะลุ 30% การป้องกันเวทย์ของศัตรู ทำลายทุกชั้นการป้องกันเวทย์ราวกับเป็นกระดาษ หลังจากใช้สกิล Ulquiorra จะเปิดใช้งานสถานะดูดเลือด รับความสามารถดูดเลือด 15% จากความเสียหายทั้งหมดที่ทำใน 2 เทิร์นถัดไป — กลไกที่ช่วยให้เขารักษาสภาพร่างกายท่ามกลางการล้อมของศัตรู หากเป้าหมายที่โดนโจมตีมี HP ต่ำกว่า 50% จะถูกติด <Erosion> ทันที ลดการฟื้นฟูจากพันธมิตรและแหล่งอื่น 35% เป็นเวลา 2 เทิร์น \n<ค้างคาว - ระยะสอง>: ในรูปลักษณ์สูงสุด สกิลนี้ยิ่งน่ากลัวมากขึ้นเมื่อความเสียหายเพิ่มขึ้น 15% ตาม HP ปัจจุบันของ Ulquiorra นอกจากนี้ ทุกเป้าหมายที่โดนโจมตียังถูกลดการป้องกันเวทย์ 25% เป็นเวลา 2 เทิร์น — ทำให้พวกเขาง่ายต่อการพ่ายแพ้ต่อการโจมตีต่อไปราวกับถูกความมืดแห่งความสิ้นหวังกลืนกิน',
		zawakeEffectDesc_in = 'Ulquiorra menggunakan jarinya untuk menembakkan meriam kegelapan yang penuh energi mematikan langsung ke formasi musuh, memberikan #C0x3D8A99#280% Magic Power#C0x5B545B#+ $(skillLevel*4*24)$ #C0xF13B54# Magic Damage#C0x5B545B#. Serangan brutal ini menembus 30% Magic Defense musuh, merobek semua lapisan pertahanan sihir seperti kertas. Segera setelah menyerang, Ulquiorra mengaktifkan Bloodsucking, memperoleh lifesteal 15% dari semua damage yang diberikan selama 2 giliran berikutnya — mekanisme yang mempertahankan kondisinya di tengah kepungan musuh. Jika target yang terkena berada di bawah 50% HP, mereka langsung terkena <Erosion>, mengurangi penyembuhan dari sekutu dan sumber lain sebesar 35% selama 2 giliran.\n<Bat - Fase Dua>: Dalam bentuk tertinggi, skill ini menjadi lebih menakutkan karena damage meningkat 15% berdasarkan HP Ulquiorra saat ini. Selain itu, semua target yang terkena serangan akan mengalami pengurangan 25% Magic Defense selama 2 giliran — membuat mereka semakin rentan terhadap serangan lanjutan seolah-olah ditelan oleh kegelapan yang putus asa.',
		zawakeEffectDesc_ph = 'Ulquiorra uses his finger to fire a dark cannon infused with deadly energy straight into the enemy formation, dealing #C0x3D8A99#280% Magic Power#C0x5B545B#+ $(skillLevel*4*24)$ #C0xF13B54# Magic Damage#C0x5B545B#. This ruthless attack penetrates 30% of the enemy’s Magic Defense, tearing through all magical defenses like paper. Immediately after casting, Ulquiorra activates Bloodsucking, gaining 15% lifesteal from all damage dealt for the next 2 turns — a mechanism that keeps him sustained amid enemy encirclement. If the target hit is below 50% HP, they are instantly afflicted with <Erosion>, reducing healing from allies and other sources by 35% for 2 turns.\n<Bat - Phase Two>: In ultimate form, this skill becomes even more terrifying as damage increases by 15% based on Ulquiorra’s current HP. Additionally, all targets hit have their Magic Defense reduced by 25% for 2 turns — making them increasingly vulnerable to follow-up attacks as if being consumed by despairing darkness.',
		zawakeEffectDesc_ma = 'Ulquiorra menggunakan jarinya untuk menembakkan meriam gelap yang penuh tenaga maut terus ke formasi musuh, memberikan #C0x3D8A99#280% Magic Power#C0x5B545B#+ $(skillLevel*4*24)$ #C0xF13B54# Magic Damage#C0x5B545B#. Serangan kejam ini menembusi 30% Magic Defense musuh, merobek semua lapisan pertahanan sihir seperti kertas. Segera selepas menyerang, Ulquiorra mengaktifkan Bloodsucking, memperoleh lifesteal 15% dari semua damage yang diberikan untuk 2 giliran berikutnya — mekanisme yang mengekalkan kondisinya di tengah kepungan musuh. Jika sasaran yang terkena berada di bawah 50% HP, mereka segera terkena <Erosion>, mengurangkan penyembuhan dari sekutu dan sumber lain sebanyak 35% selama 2 giliran.\n<Bat - Fasa Dua>: Dalam bentuk tertinggi, kemahiran ini menjadi lebih menakutkan apabila damage meningkat 15% berdasarkan HP semasa Ulquiorra. Selain itu, semua sasaran yang terkena serangan akan mengalami pengurangan 25% Magic Defense selama 2 giliran — membuat mereka semakin mudah dikalahkan oleh serangan seterusnya seolah-olah ditelan oleh kegelapan putus asa.',
		zawakeEffectDesc_vn = 'Ulquiorra sử dụng ngón tay của mình phóng ra nguồn pháo bóng tối mang năng lượng tử vong, oanh tạc thẳng vào đội hình địch, gây ra #C0x3D8A99#280% Công Phép Thuật#C0x5B545B#+ $(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật#C0x5B545B# Đòn tấn công hung tàn này xuyên thủ 30% Thủ Phép thuật của kẻ địch, khiến mọi lớp phòng thủ phép đều bị xé toạc như tờ giấy. Ngay sau khi tung chiêu, Ulquiorra kích hoạt trạng thái hấp huyết, đạt được khả năng hút máu 15% từ mọi sát thương gây ra trong 2 lượt kế tiếp — một cơ chế giúp hắn duy trì thể lực giữa vòng vây kẻ địch. Nếu mục tiêu trúng pháo đang còn dưới 50% máu, chúng sẽ lập tức bị áp đặt hiệu ứng <Ăn mòn>, khiến khả năng hồi phục của chúng từ đồng đội và các nguồn khác bị giảm đi 35%, kéo dài trong 2 lượt.\n<Dơi - Giai đoạn hai>: Trong hình thái tối thượng, kỹ năng này trở nên càng đáng sợ hơn khi sát thương được tăng thêm 15% dựa trên lượng máu hiện tại của Ulquiorra. Không chỉ vậy, tất cả mục tiêu trúng đòn còn bị giảm 25% Thủ Phép thuật, kéo dài 2 lượt — khiến chúng càng dễ gục ngã trước những đòn đánh tiếp theo như thể đang dần bị nuốt chửng bởi bóng tối tuyệt vọng.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'All targets hit by dark magic have their Magic Defense reduced by 18% for 2 turns \n#F20# \n#F40##C0x5c9970#→ All targets hit by dark magic have their Magic Defense reduced by 25% for 2 turns',
		zawakeSimpleDesc_en = 'All targets hit by dark magic have their Magic Defense reduced by 18% for 2 turns \n#F20# \n#F40##C0x5c9970#→ All targets hit by dark magic have their Magic Defense reduced by 25% for 2 turns',
		zawakeSimpleDesc_th = 'เป้าหมายทั้งหมดที่ได้รับความเสียหายจากเวทมนตร์มืดถูกลดป้องกันเวท 18% เป็นเวลา 2 เทิร์น \n#F20# \n#F40##C0x5c9970#→ เป้าหมายทั้งหมดที่ได้รับความเสียหายจากเวทมนตร์มืดถูกลดป้องกันเวท 25% เป็นเวลา 2 เทิร์น',
		zawakeSimpleDesc_in = 'Semua target yang terkena damage dari sihir gelap dikurangi Pertahanan Sihir 18% selama 2 giliran \n#F20# \n#F40##C0x5c9970#→ Semua target yang terkena damage dari sihir gelap dikurangi Pertahanan Sihir 25% selama 2 giliran',
		zawakeSimpleDesc_ph = 'Lahat ng target na tinamaan ng dark magic ay nababawasan ang Magic Defense ng 18% sa loob ng 2 turn \n#F20# \n#F40##C0x5c9970#→ Lahat ng target na tinamaan ng dark magic ay nababawasan ang Magic Defense ng 25% sa loob ng 2 turn',
		zawakeSimpleDesc_ma = 'Semua target yang terkena damage dari sihir gelap dikurangkan Pertahanan Sihir 18% selama 2 giliran \n#F20# \n#F40##C0x5c9970#→ Semua target yang terkena damage dari sihir gelap dikurangkan Pertahanan Sihir 25% selama 2 giliran',
		zawakeSimpleDesc_vn = 'Tất cả mục tiêu nhận sát thương từ pháp bóng tối bị giảm 18% Thủ Phép thuật, kéo dài 2 lượt \n#F20# \n#F40##C0x5c9970#→ Tất cả mục tiêu nhận sát thương từ pháp bóng tối bị giảm 25% Thủ Phép thuật, kéo dài 2 lượt',
		iconRes = 'battle/skill_icon/skill_80112.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 1,
		skillDamageType = 1,
