	[9080113] = {
		id = 9080113,
		skillName_vn = 'Ngọn Thương Sấm Sét',
		skillName_en = 'Thunder Spear',
		skillName_th = 'หอกฟ้าผ่า',
		skillName_in = 'Tombak Petir',
		skillName_ph = 'Thunder Spear',
		skillName_ma = 'Tombak Petir',
		skillName = 'Ngọn Thương Sấm Sét',
		describe_vn = 'Ulquiorra triệu hồi sức mạnh hủy diệt, tạo ra một ngọn thương sét bóng tối mang năng lượng hắc ám xoáy sâu, xuyên thủng đội hình địch như một cú đâm trời giáng, để lại những lỗ hổng không thể lành trên cơ thể kẻ địch. Đòn tấn công gây ra #C0x3D8A99#480% Công Phép Thuật#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Sát Thương Phép Thuật#C0x5B545B# và bỏ qua tới 40% Thủ Phép thuật của địch, khiến mọi lớp bảo vệ phép thuật trở nên vô nghĩa. Ngoài sát thương khủng khiếp, kỹ năng còn áp dụng hiệu ứng <Ăn mòn> lên các mục tiêu, kéo dài 2 lượt, khiến khả năng hồi phục của chúng bị suy giảm mạnh. Sau khi tung chiêu, Ulquiorra hấp thụ sức mạnh bóng tối, hồi lại #C0x5c9970#20% lượng máu tối đa#C0x5B545B# (tăng lên 30% nếu máu hiện tại dưới 30%), đồng thời ban cho toàn bộ đồng minh một lớp giáp bảo vệ tương đương 10% máu tối đa của Ulquiorra, kéo dài trong 3 lượt, giúp củng cố thế trận và đảo chiều cuộc chiến.\n#F10#\n#F40#<Ăn mòn>: Lượng hồi máu mà kẻ địch nhận được từ đồng đội và các nguồn khác bị giảm đi 35%.\n<Dơi - Giai đoạn hai>: Trong giai đoạn này, sát thương của kỹ năng được tăng thêm 20% dựa trên lượng máu hiện tại của Ulquiorra, khiến ngọn thương trở thành đòn kết liễu thực sự.',
		describe_en = 'Ulquiorra summons destructive power, creating a dark lightning spear infused with shadow energy, piercing through enemy formations like a divine thrust, leaving irreparable gaps in the enemies\' bodies. The attack deals #C0x3D8A99#480% Magic Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Magic Damage#C0x5B545B# and ignores up to 40% of the enemy\'s Magic Defense, rendering all magical protection meaningless. Beyond the immense damage, the skill applies <Corrosion> to targets for 2 turns, greatly reducing their healing capabilities. After casting, Ulquiorra absorbs dark energy, restoring #C0x5c9970#20% Max HP#C0x5B545B# (increased to 30% if current HP is below 30%), and grants all allies a shield equal to 10% of Ulquiorra’s Max HP for 3 turns, reinforcing the formation and turning the tide of battle.\n#F10#\n#F40#<Corrosion>: Healing received by enemies from allies and other sources is reduced by 35%.\n<Bat – Phase Two>: In this phase, the skill’s damage is increased by 20% based on Ulquiorra’s current HP, making the spear a true finishing blow.',
		describe_th = 'Ulquiorra เรียกพลังทำลายล้าง สร้างหอกฟ้าแลบสีดำที่เต็มไปด้วยพลังเงามืด พุ่งทะลุแนวศัตรูเหมือนการแทงฟ้า สร้างช่องว่างที่ไม่สามารถซ่อมแซมได้ในร่างศัตรู การโจมตีนี้สร้างความเสียหาย #C0x3D8A99#480% พลังเวทย์#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#ความเสียหายเวทย์#C0x5B545B# และเพิกเฉยต่อ 40% การป้องกันเวทย์ของศัตรู ทำให้ทุกชั้นป้องกันเวทย์ไร้ค่า นอกเหนือจากความเสียหายมหาศาล สกิลนี้ยังใส่เอฟเฟกต์ <การกัดกร่อน> กับเป้าหมายเป็นเวลา 2 ตา ลดความสามารถในการฟื้นฟูของพวกเขาอย่างมาก หลังใช้สกิล Ulquiorra ดูดซับพลังแห่งความมืด ฟื้นฟู #C0x5c9970#20% HP สูงสุด#C0x5B545B# (เพิ่มเป็น 30% หาก HP ปัจจุบันต่ำกว่า 30%) และมอบโล่ให้กับพันธมิตรทุกคนเท่ากับ 10% ของ HP สูงสุดของ Ulquiorra เป็นเวลา 3 ตา ช่วยเสริมแกร่งการจัดการและพลิกสถานการณ์.\n#F10#\n#F40#<การกัดกร่อน>: การฟื้นฟูที่ศัตรูได้รับจากเพื่อนร่วมทีมและแหล่งอื่นลดลง 35%.\n<ค้างคาว – ระยะที่สอง>: ในระยะนี้ ความเสียหายของสกิลจะเพิ่มขึ้นอีก 20% ตาม HP ปัจจุบันของ Ulquiorra ทำให้หอกนี้กลายเป็นการโจมตีตัดสินจริง ๆ',
		describe_in = 'Ulquiorra memanggil kekuatan kehancuran, menciptakan tombak petir gelap yang berenergi bayangan, menembus formasi musuh seperti tusukan surgawi, meninggalkan celah yang tidak bisa diperbaiki pada tubuh musuh. Serangan ini memberikan #C0x3D8A99#480% Serangan Sihir#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerusakan Sihir#C0x5B545B# dan mengabaikan hingga 40% Pertahanan Sihir musuh, membuat semua perlindungan sihir menjadi sia-sia. Selain kerusakan besar, skill ini menerapkan <Corrosion> pada target selama 2 giliran, sangat mengurangi kemampuan penyembuhan mereka. Setelah digunakan, Ulquiorra menyerap energi gelap, memulihkan #C0x5c9970#20% HP Maks#C0x5B545B# (meningkat menjadi 30% jika HP saat ini di bawah 30%), dan memberikan semua sekutu perisai setara 10% HP Maks Ulquiorra selama 3 giliran, memperkuat formasi dan membalikkan jalannya pertempuran.\n#F10#\n#F40#<Corrosion>: Pemulihan yang diterima musuh dari sekutu dan sumber lain dikurangi 35%.\n<Bat – Fase Dua>: Pada fase ini, damage skill meningkat 20% berdasarkan HP saat ini Ulquiorra, menjadikan tombak ini serangan penyelesaian yang sesungguhnya.',
		describe_ph = 'Ulquiorra ay nagpakilos ng puwersa ng pagkawasak, lumikha ng isang madilim na kidlat na sibat na may enerhiya ng anino, tumatagos sa hanay ng kaaway tulad ng banal na tusok, nag-iiwan ng mga hindi maibabal',
		describe_ma = 'Ulquiorra memanggil kuasa pemusnah, mencipta tombak kilat gelap yang dipenuhi tenaga bayangan, menembusi formasi musuh seperti tikaman ilahi, meninggalkan lubang yang tidak boleh diperbaiki pada tubuh musuh. Serangan ini memberikan #C0x3D8A99#480% Serangan Sihir#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54#Kerusakan Sihir#C0x5B545B# dan mengabaikan sehingga 40% Pertahanan Sihir musuh, menjadikan semua perlindungan sihir tidak berguna. Selain kerosakan hebat, kemahiran ini mengenakan efek <Corrosion> pada sasaran selama 2 giliran, mengurangkan keupayaan pemulihan mereka dengan ketara. Selepas digunakan, Ulquiorra menyerap tenaga gelap, memulihkan #C0x5c9970#20% HP Maks#C0x5B545B# (meningkat kepada 30% jika HP semasa di bawah 30%), dan memberikan semua sekutu perisai bersamaan 10% HP Maks Ulquiorra selama 3 giliran, menguatkan formasi dan membalikkan arus pertempuran.\n#F10#\n#F40#<Corrosion>: Pemulihan yang diterima musuh daripada sekutu dan sumber lain dikurangkan 35%.\n<Bat – Fasa Dua>: Pada fasa ini, kerosakan kemahiran meningkat 20% berdasarkan HP semasa Ulquiorra, menjadikan tombak ini serangan penamat yang sebenar.',
		describe = 'Ulquiorra summons destructive power, creating a dark lightning spear infused with shadow energy, piercing through enemy formations like a divine thrust, leaving irreparable gaps in the enemies\' bodies. The attack deals #C0x3D8A99#480% Magic Attack#C0x5B545B# + $(skillLevel*4*24)$ #C0xF13B54# Magic Damage#C0x5B545B# and ignores up to 40% of the enemy\'s Magic Defense, rendering all magical protection meaningless. Beyond the immense damage, the skill applies <Corrosion> to targets for 2 turns, greatly reducing their healing capabilities. After casting, Ulquiorra absorbs dark energy, restoring #C0x5c9970#20% Max HP#C0x5B545B# (increased to 30% if current HP is below 30%), and grants all allies a shield equal to 10% of Ulquiorra’s Max HP for 3 turns, reinforcing the formation and turning the tide of battle.\n#F10#\n#F40#<Corrosion>: Healing received by enemies from allies and other sources is reduced by 35%.\n<Bat – Phase Two>: In this phase, the skill’s damage is increased by 20% based on Ulquiorra’s current HP, making the spear a true finishing blow.',
		simDesc_vn = 'Ulquiorra tạo ra ngọn thương sét hủy diệt xuyên thủng đội hình địch, bỏ qua 40% Thủ Phép thuật, hồi máu cho bản thân và áp dụng <Ăn mòn> lên kẻ địch trong 2 lượt. Ban cho đồng đội một lượng giáp tương với với máu tối đa của hắn.',
		simDesc_en = 'Ulquiorra summons a devastating Lightning Spear that pierces through enemy lines, ignoring 40% of their Magic Defense. Heals himself and inflicts <Corrosion> on enemies for 2 turns. Grants allies a shield equal to his Max HP.',
		simDesc_th = 'Ulquiorra สร้างหอกสายฟ้าแห่งการทำลายล้าง ทะลวงแนวศัตรู โดยละเว้น 40% การป้องกันเวทมนตร์ ฟื้นฟู HP ให้ตนเอง และมอบเอฟเฟกต์ <การกัดกร่อน> แก่ศัตรูเป็นเวลา 2 เทิร์น มอบเกราะให้พันธมิตรเท่ากับ HP สูงสุดของเขา',
		simDesc_in = 'Ulquiorra menciptakan Tombak Petir penghancur yang menembus barisan musuh, mengabaikan 40% Pertahanan Sihir. Memulihkan HP dirinya dan memberikan debuff <Korosi> pada musuh selama 2 giliran. Memberikan sekutu perisai sebesar Max HP miliknya.',
		simDesc_ph = 'Lumikha si Ulquiorra ng isang kidlat na sibat na mapanira, tumatagos sa hanay ng kalaban at binabalewala ang 40% ng kanilang Magic Defense. Siya ay nagpapagaling ng sarili at naglalapat ng <Korosyon> sa mga kalaban sa loob ng 2 turn. Nagbibigay din siya sa mga kakampi ng kalasag na katumbas ng kanyang Max HP.',
		simDesc_ma = 'Ulquiorra mencipta Lembing Petir pemusnah yang menembusi barisan musuh, mengabaikan 40% Pertahanan Magik. Memulihkan HP dirinya serta mengenakan debuff <Kakisan> ke atas musuh selama 2 pusingan. Memberikan sekutu perisai bersamaan dengan HP Maksimumnya.',
		simDesc = 'Ulquiorra summons a devastating Lightning Spear that pierces through enemy lines, ignoring 40% of their Magic Defense. Heals himself and inflicts <Corrosion> on enemies for 2 turns. Grants allies a shield equal to his Max HP.',
		starEffect = __data_t__starEffect[9080113],
		-- {11}
		starEffectDesc_vn = 'Hiệu ứng xuyên Thủ Phép Thuật được nâng cấp, đạt mức tối đa lên đến 50%, giúp đòn đánh xuyên phá phòng ngự phép của đối phương một cách hiệu quả hơn. Song song đó, hiệu ứng <Ăn mòn> cũng được cường hóa: giảm 50% khả năng hồi máu từ mọi nguồn của kẻ địch, và duy trì trong 3 lượt, khiến mục tiêu gần như không thể hồi phục như bình thường.\nVề phần phục hồi, Ulquiorra sau khi thi triển Ngọn thương Sấm Sét sẽ được hồi 25% lượng máu tối đa, mang lại lợi thế sống sót đáng kể trong giao tranh. Đặc biệt, nếu tại thời điểm sử dụng chiêu thức, máu của Ulquiorra thấp hơn 30%, lượng hồi phục sẽ được tăng mạnh lên 35% máu tối đa.',
		starEffectDesc = 'The Magic Defense Penetration effect is upgraded, reaching up to 50%, allowing attacks to pierce enemy magic defenses more effectively. At the same time, the <Corrosion> effect is enhanced: reducing enemy healing from all sources by 50% and lasting for 3 turns, making it nearly impossible for the target to recover normally.\nFor recovery, after casting Thunder Spear, Ulquiorra restores 25% of his Max HP, granting significant survivability in battle. Especially, if Ulquiorra’s HP is below 30% at the time of casting, the recovery is greatly increased to 35% of his Max HP.',
		starEffectDesc_en = 'The Magic Defense Penetration effect is upgraded, reaching up to 50%, allowing attacks to pierce enemy magic defenses more effectively. At the same time, the <Corrosion> effect is enhanced: reducing enemy healing from all sources by 50% and lasting for 3 turns, making it nearly impossible for the target to recover normally.\nFor recovery, after casting Thunder Spear, Ulquiorra restores 25% of his Max HP, granting significant survivability in battle. Especially, if Ulquiorra’s HP is below 30% at the time of casting, the recovery is greatly increased to 35% of his Max HP.',
		starEffectDesc_th = 'เอฟเฟกต์เจาะเกราะเวทมนตร์ได้รับการอัปเกรด สูงสุดถึง 50% ทำให้การโจมตีสามารถเจาะการป้องกันเวทของศัตรูได้อย่างมีประสิทธิภาพมากขึ้น พร้อมกันนี้ เอฟเฟกต์ <Corrosion> ก็ได้รับการเสริมพลัง: ลดการฟื้นฟู HP ของศัตรูจากทุกแหล่งลง 50% และคงอยู่ 3 เทิร์น ทำให้เป้าหมายแทบไม่สามารถฟื้นฟูได้ตามปกติ.\nสำหรับการฟื้นฟู Ulquiorra หลังจากใช้สกิล Thunder Spear จะฟื้นคืน HP 25% ของ HP สูงสุด มอบความได้เปรียบในการเอาตัวรอดในระหว่างการต่อสู้ โดยเฉพาะหาก HP ของ Ulquiorra ต่ำกว่า 30% ในขณะที่ใช้สกิล การฟื้นฟูจะเพิ่มขึ้นเป็น 35% ของ HP สูงสุด',
		starEffectDesc_in = 'Efek Penetrasi Pertahanan Sihir ditingkatkan, mencapai hingga 50%, membuat serangan lebih efektif menembus pertahanan sihir musuh. Pada saat yang sama, efek <Corrosion> diperkuat: mengurangi 50% kemampuan pemulihan HP musuh dari semua sumber dan berlangsung selama 3 giliran, membuat target hampir tidak bisa pulih seperti biasanya.\nUntuk pemulihan, setelah menggunakan Thunder Spear, Ulquiorra memulihkan 25% dari HP Maksimum, memberikan keuntungan besar dalam bertahan hidup di pertempuran. Terutama, jika HP Ulquiorra kurang dari 30% saat skill digunakan, pemulihan meningkat menjadi 35% dari HP Maksimum.',
		starEffectDesc_ph = 'Ang Magic Defense Penetration effect ay na-upgrade, umaabot hanggang 50%, na nagbibigay-daan sa mga atake na mas epektibong makalusot sa magic defense ng kalaban. Kasabay nito, ang <Corrosion> effect ay pinalakas: binabawasan ng 50% ang kakayahan ng kalaban na mag-heal mula sa anumang pinagmulan, tumatagal ng 3 turn, na halos imposibleng makabawi nang normal ang target.\nPara sa recovery, pagkatapos gamitin ang Thunder Spear, si Ulquiorra ay nagre-restore ng 25% ng kanyang Max HP, nagbibigay ng malaking kalamangan sa survivability sa laban. Lalo na kung ang HP ni Ulquiorra ay mas mababa sa 30% sa oras ng paggamit ng skill, tataas ang healing sa 35% ng kanyang Max HP.',
		starEffectDesc_ma = 'Kesan Penembusan Pertahanan Magik telah dipertingkat, mencapai sehingga 50%, membolehkan serangan menembusi pertahanan magik musuh dengan lebih berkesan. Pada masa yang sama, kesan <Corrosion> turut diperkasa: mengurangkan 50% keupayaan pemulihan HP musuh daripada semua sumber dan berkekalan selama 3 giliran, menjadikan sasaran hampir mustahil untuk pulih seperti biasa.\nBagi pemulihan, selepas menggunakan Thunder Spear, Ulquiorra akan memulihkan 25% daripada HP Maksimum, memberi kelebihan besar untuk kelangsungan hidup dalam pertarungan. Terutamanya, jika HP Ulquiorra berada di bawah 30% ketika skill digunakan, jumlah pemulihan meningkat kepada 35% daripada HP Maksimum.',
		zawakeEffect = __data_t__zawakeEffect[9080113],
		-- {79003, 1}
		zawakeEffectDesc = 'Magic Penetration has been upgraded, reaching a maximum of 50%, allowing attacks to more effectively pierce the enemy’s magic defense. Simultaneously, the <Erosion> effect is also enhanced: reducing all healing received by enemies by 50% for 3 turns, making them nearly unable to recover normally.\nRegarding recovery, after Ulquiorra casts Thunder Spear, he restores 25% of his maximum HP, providing a significant survival advantage in battle. Notably, if at the time of casting Ulquiorra’s HP is below 30%, the healing amount is increased to 35% of maximum HP, and the armor received by allies increases to 20%.',
		zawakeEffectDesc_en = 'Magic Penetration has been upgraded, reaching a maximum of 50%, allowing attacks to more effectively pierce the enemy’s magic defense. Simultaneously, the <Erosion> effect is also enhanced: reducing all healing received by enemies by 50% for 3 turns, making them nearly unable to recover normally.\nRegarding recovery, after Ulquiorra casts Thunder Spear, he restores 25% of his maximum HP, providing a significant survival advantage in battle. Notably, if at the time of casting Ulquiorra’s HP is below 30%, the healing amount is increased to 35% of maximum HP, and the armor received by allies increases to 20%.',
		zawakeEffectDesc_th = 'การเจาะทะลุการป้องกันเวทย์ได้รับการอัปเกรดสูงสุดถึง 50% ทำให้การโจมตีทะลุการป้องกันเวทย์ของศัตรูได้อย่างมีประสิทธิภาพมากขึ้น พร้อมกันนี้ เอฟเฟกต์ <Erosion> ยังถูกเสริม: ลดการฟื้นฟูทั้งหมดของศัตรูลง 50% เป็นเวลา 3 เทิร์น ทำให้เป้าหมายแทบไม่สามารถฟื้นฟูตามปกติได้ \nในส่วนของการฟื้นฟู หลังจาก Ulquiorra ใช้ Thunder Spear เขาจะฟื้นฟู HP สูงสุด 25% ให้ความได้เปรียบด้านการอยู่รอดในสนามรบอย่างมาก โดยเฉพาะหากในเวลาที่ใช้สกิล HP ของ Ulquiorra ต่ำกว่า 30% ปริมาณการฟื้นฟูจะเพิ่มขึ้นเป็น 35% ของ HP สูงสุด และเกราะที่พันธมิตรได้รับจะเพิ่มขึ้นเป็น 20%',
		zawakeEffectDesc_in = 'Efek Magic Penetration telah ditingkatkan, mencapai maksimum 50%, memungkinkan serangan menembus pertahanan sihir musuh dengan lebih efektif. Secara bersamaan, efek <Erosion> juga diperkuat: mengurangi semua penyembuhan yang diterima musuh sebesar 50% selama 3 giliran, membuat mereka hampir tidak bisa pulih secara normal.\nMengenai pemulihan, setelah Ulquiorra menggunakan Thunder Spear, ia memulihkan 25% HP maksimum, memberikan keuntungan bertahan hidup yang signifikan dalam pertarungan. Terutama, jika saat menggunakan kemampuan HP Ulquiorra kurang dari 30%, jumlah penyembuhan meningkat menjadi 35% HP maksimum, dan armor yang diterima sekutu meningkat menjadi 20%.',
		zawakeEffectDesc_ph = 'Ang Magic Penetration ay na-upgrade, umaabot sa maximum na 50%, na nagbibigay-daan sa mga atake na mas epektibong tumagos sa depensa ng magic ng kalaban. Kasabay nito, ang epekto ng <Erosion> ay pinalakas din: binabawasan ang lahat ng healing na natatanggap ng mga kaaway ng 50% sa loob ng 3 turn, na halos hindi na sila makapag-recover nang normal.\nTungkol sa pagbawi, pagkatapos i-cast ni Ulquiorra ang Thunder Spear, bumabalik siya ng 25% ng kanyang maximum HP, nagbibigay ng malaking kalamangan sa pag-survive sa labanan. Kapansin-pansin, kung sa oras ng paggamit ng skill ang HP ni Ulquiorra ay mas mababa sa 30%, ang halaga ng healing ay tumataas sa 35% ng maximum HP, at ang armor na natatanggap ng mga kakampi ay tumataas sa 20%.',
		zawakeEffectDesc_ma = 'Magic Penetration telah dinaik taraf, mencapai maksimum 50%, membolehkan serangan menembusi pertahanan sihir musuh dengan lebih berkesan. Pada masa yang sama, kesan <Erosion> juga dipertingkatkan: mengurangkan semua penyembuhan yang diterima oleh musuh sebanyak 50% selama 3 giliran, menjadikan mereka hampir tidak dapat pulih seperti biasa.\nMengenai pemulihan, selepas Ulquiorra menggunakan Thunder Spear, dia memulihkan 25% HP maksimum, memberikan kelebihan ketahanan yang ketara dalam pertempuran. Terutama, jika pada masa menggunakan kemahiran HP Ulquiorra berada di bawah 30%, jumlah pemulihan meningkat kepada 35% HP maksimum, dan armor yang diterima oleh rakan meningkat kepada 20%.',
		zawakeEffectDesc_vn = 'Hiệu ứng xuyên Thủ Phép Thuật được nâng cấp, đạt mức tối đa lên đến 50%, giúp đòn đánh xuyên phá phòng ngự phép của đối phương một cách hiệu quả hơn. Song song đó, hiệu ứng <Ăn mòn> cũng được cường hóa: giảm 50% khả năng hồi máu từ mọi nguồn của kẻ địch, và duy trì trong 3 lượt, khiến mục tiêu gần như không thể hồi phục như bình thường.\nVề phần phục hồi, Ulquiorra sau khi thi triển Ngọn thương Sấm Sét sẽ được hồi 25% lượng máu tối đa, mang lại lợi thế sống sót đáng kể trong giao tranh. Đặc biệt, nếu tại thời điểm sử dụng chiêu thức, máu của Ulquiorra thấp hơn 30%, lượng hồi phục sẽ được tăng mạnh lên 35% máu tối đa, lượng giáp mà đồng đội nhận được tăng lên thành 20%.',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'After using the ultimate skill, Ulquiorra grants allies a shield equal to 20% of his max HP',
		zawakeSimpleDesc_en = 'After using the ultimate skill, Ulquiorra grants allies a shield equal to 20% of his max HP',
		zawakeSimpleDesc_th = 'หลังใช้สกิลอัลติเมท Ulquiorra มอบโล่ให้พันธมิตรเท่ากับ 20% ของ HP สูงสุดของเขา',
		zawakeSimpleDesc_in = 'Setelah menggunakan skill ultimate, Ulquiorra memberikan sekutu perisai sebesar 20% dari HP maksimalnya',
		zawakeSimpleDesc_ph = 'Pagkatapos gamitin ang ultimate skill, nagbibigay si Ulquiorra ng shield sa allies katumbas ng 20% ng kanyang max HP',
		zawakeSimpleDesc_ma = 'Selepas menggunakan skill ultimate, Ulquiorra memberikan sekutu perisai bersamaan 20% dari HP maksumnya',
		zawakeSimpleDesc_vn = 'Sau khi sử dụng kĩ năng tối thượng, Ulquiora ban cho đồng minh lượng giáp tương ứng với 20% máu tối đa của hắn',
		iconRes = 'battle/skill_icon/skill_80113.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 2,
		skillDamageType = 1,
		skillNatureType = 16,
		targetTypeDesc = 'All Enemies',
