	[40000016] = {
		id = 40000016,
		skillName_vn = 'Lưỡi lá',
		skillName_en = 'Leaf Blade',
		skillName_th = 'ใบมีดใบไม้',
		skillName_in = 'Pisau Daun',
		skillName_ph = 'Dahon Talim',
		skillName_ma = 'Bilahan Daun',
		skillName = 'Leaf Blade',
		describe_vn = 'Khi máu bản thân dưới 60%, bản thân vào trạng thái tiềm hành trong 1 lượt (trong trạng thái tiềm hành không thể bị chọn làm mục tiêu, nhưng sẽ bị ảnh hưởng bởi sát thương diện rộng)',
		describe_en = 'When your HP is below 60%, you enter stealth mode for 1 turn (while in stealth mode, you cannot be targeted, but are affected by area damage).',
		describe_th = 'เมื่อเลือดของคุณต่ำกว่า 60% คุณจะเข้าสู่โหมดล่องหนเป็นเวลา 1 เทิร์น (ในโหมดล่องหนจะไม่สามารถถูกเลือกเป็นเป้าหมายได้ แต่ยังได้รับผลกระทบจากความเสียหายแบบวงกว้างได้)',
		describe_in = 'Saat darah Anda di bawah 60%, Anda masuk ke mode sembunyi selama 1 giliran (dalam mode sembunyi, Anda tidak dapat dipilih sebagai target, tetapi tetap terkena dampak dari serangan area).',
		describe_ph = 'Kapag ang iyong HP ay bumaba sa ilalim ng 60%, ikaw ay pumapasok sa stealth mode sa loob ng 1 turn (habang nasa stealth mode, hindi ka maaaring maging target ngunit maaapektuhan pa rin ng area damage).',
		describe_ma = 'Apabila darah anda di bawah 60%, anda akan memasuki mod tersembunyi selama 1 pusingan (dalam mod tersembunyi, anda tidak boleh dijadikan sasaran, tetapi masih terjejas oleh serangan kawasan).',
		describe = 'When your HP is below 60%, you enter stealth mode for 1 turn (while in stealth mode, you cannot be targeted, but are affected by area damage).',
		starEffect = __data_t__starEffect[40000016],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Trong trạng thái lén lút, sát thương chí mạng tăng 25%, lần đầu tiên ở trạng thái lén lút sẽ nhận được một dấu hiệu lạnh lùng.',
		starEffectDesc = 'Enhance effects: While in stealth state, critical damage increases by 25%. The first time entering stealth state, a cold mark is gained.',
		starEffectDesc_en = 'Enhance effects: While in stealth state, critical damage increases by 25%. The first time entering stealth state, a cold mark is gained.',
		starEffectDesc_th = 'เพิ่มประสิทธิผล: ขณะอยู่ในสถานะลอบเร้น ความเสียหายคริติคอลเพิ่มขึ้น 25% ครั้งแรกที่อยู่ในสถานะลอบเร้น จะได้รับเครื่องหมายเย็นชา',
		starEffectDesc_in = 'Tingkatkan efek: Saat dalam keadaan sembunyi, kerusakan kritis meningkat sebesar 25%. Pertama kali dalam keadaan sembunyi akan mendapatkan tanda dingin.',
		starEffectDesc_ph = 'Palakasin ang epekto: Sa estado ng panlilinlang, tumataas ang critical damage ng 25%. Sa unang pagkakataon sa estado ng panlilinlang ay makakakuha ng malamig na marka.',
		starEffectDesc_ma = 'Kukuhkan kesan: Dalam keadaan senyap, kerosakan kritikal meningkat sebanyak 25%. Kali pertama dalam keadaan senyap akan menerima tanda dingin.',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {400000161, 400000361}
	},
	[40000022] = {
		id = 40000022,
		skillName_vn = 'Đột kích',
		skillName_en = 'Sudden Attack',
		skillName_th = 'จู่โจมทันที',
		skillName_in = 'Serangan Mendadak',
		skillName_ph = 'Biglaang Atake',
		skillName_ma = 'Serangan Mengejutkan',
		skillName = 'Sudden Attack',
		describe_vn = 'Cú mèo bắn tỉa lướt đi không một tiếng động, nhanh chóng tiếp cận kẻ địch, tung cú đá mạnh mẽ vào mục tiêu đơn lẻ của đối phương, gây ra #C0xE69900#160% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, và sau khi tấn công sẽ vào trạng thái [Ẩn thân] (Ẩn thân: hiệu ứng đặc biệt, mục tiêu không thể bị chọn, có thể bị ảnh hưởng bởi tấn công diện rộng, giải trừ sau khi tấn công, tối đa duy trì 3 lượt)',
		describe_en = 'The sniper owl silently glides forward, quickly approaching the enemy and delivering a powerful kick to a single target, dealing #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#. After the attack, it enters the [Stealth] state (Stealth: special effect, the target cannot be selected, can be affected by area attacks, removed after attacking, lasts up to 3 turns).',
		describe_th = 'นกฮูกซุ่มยิงลื่นไหลไปอย่างเงียบ ๆ เข้าถึงศัตรูอย่างรวดเร็วและเตะอย่างแรงใส่เป้าหมายเดียวของฝ่ายตรงข้าม สร้างความเสียหาย #C0xE69900#160% การโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# หลังจากโจมตีเข้าสู่สถานะ [ซ่อนตัว] (ซ่อนตัว: เอฟเฟกต์พิเศษ เป้าหมายไม่สามารถถูกเลือกได้ อาจได้รับผลกระทบจากการโจมตีแบบวงกว้าง ยกเลิกหลังโจมตี คงอยู่ได้สูงสุด 3 เทิร์น)',
		describe_in = 'Burung hantu penembak jitu meluncur tanpa suara, dengan cepat mendekati musuh dan melayangkan tendangan kuat ke satu target musuh, menyebabkan #C0xE69900#160% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, setelah menyerang memasuki keadaan [Menyamar] (Menyamar: efek khusus, target tidak dapat dipilih, dapat terkena serangan area, dibatalkan setelah menyerang, bertahan maksimal 3 giliran).',
		describe_ph = 'Ang uwak sniper ay dumulas nang hindi naririnig, mabilis na lumalapit sa kalaban at nagtapon ng malakas na sipa sa isang target ng kalaban, nagdudulot ng #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, at pagkatapos ng pag-atake ay papasok sa estado ng [Pagkakatago] (Pagkakatago: espesyal na epekto, hindi pwedeng mapili ang target, maaari pa ring maapektuhan ng mga malawakang atake, mawawala pagkatapos tumama, tumatagal ng hanggang 3 turn).',
		describe_ma = 'Burung hantu penembak tepat menyelinap tanpa bunyi, dengan pantas menghampiri musuh dan melontar tendangan kuat ke satu sasaran lawan, menyebabkan #C0xE69900#160% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, dan selepas menyerang akan memasuki keadaan [Menyamar] (Menyamar: kesan khas, sasaran tidak boleh dipilih, boleh terkesan oleh serangan luas, dibatalkan selepas menyerang, bertahan maksimum 3 pusingan).',
		describe = 'The sniper owl silently glides forward, quickly approaching the enemy and delivering a powerful kick to a single target, dealing #C0xE69900#160% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#. After the attack, it enters the [Stealth] state (Stealth: special effect, the target cannot be selected, can be affected by area attacks, removed after attacking, lasts up to 3 turns).',
		simDesc_vn = 'Decidueye lướt đi không phát ra một tiếng động, nhanh chóng tiếp cận kẻ địch và tung ra cú đá mạnh mẽ vào mục tiêu đơn lẻ.',
		simDesc_en = 'Decidueye glides silently, swiftly approaching the enemy and delivering a powerful kick to a single target.',
		simDesc_th = 'เดซิเดวีลื่นไหลอย่างเงียบเชียบ เข้าสู่เป้าหมายอย่างรวดเร็วแล้วโจมตีด้วยการเตะอย่างแรงใส่เป้าหมายเดี่ยว',
		simDesc_in = 'Decidueye meluncur tanpa suara, dengan cepat mendekati musuh dan melancarkan tendangan kuat ke satu target.',
		simDesc_ph = 'Tahimik na dumulas si Decidueye, mabilis na lumalapit sa kalaban at nagtataas ng malakas na sipa sa isang target.',
