	[40001012] = {
		id = 40001012,
		skillName_vn = 'Gió băng',
		skillName_en = 'Cold wind',
		skillName_th = 'ลมหนาว',
		skillName_in = 'Angin dingin',
		skillName_ph = 'Malamig na hangin',
		skillName_ma = 'Angin sejuk',
		skillName = 'Cold wind',
		describe_vn = 'Chim băng hóa thành một cơn gió băng, xoay quanh kẻ địch, tấn công mục tiêu hàng dọc của đối phương, gây ra #C0x3D8A99#145% Công Phép thuật#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, có 40% cơ hội [Đóng băng] mục tiêu trong 2 lượt (Đóng băng: hiệu ứng khống chế, không thể hành động, giải trừ khi nhận sát thương tích lũy vượt quá 30% sinh mệnh của mục tiêu)',
		describe_en = 'The Ice Bird transforms into an icy wind, swirling around enemies and attacking a vertical line of enemy targets, dealing #C0x3D8A99#145% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 40% chance to [Freeze] the target for 2 turns (Freeze: a control effect that prevents action and is removed when the target takes accumulated damage exceeding 30% of its health).',
		describe_th = 'นกน้ำแข็งกลายเป็นลมเย็นหมุนรอบศัตรูและโจมตีเป้าหมายเป็นแนวตั้งของฝ่ายตรงข้าม สร้างความเสียหาย #C0x3D8A99#145% พลังเวทย์#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายเวทย์มนตร์ #C0x5B545B# พร้อมโอกาส 40% ที่จะ [แช่แข็ง] เป้าหมายเป็นเวลา 2 เทิร์น (แช่แข็ง: สถานะควบคุมที่ไม่สามารถกระทำได้ และจะถูกลบเมื่อได้รับความเสียหายสะสมเกิน 30% ของพลังชีวิตเป้าหมาย)',
		describe_in = 'Burung Es berubah menjadi angin beku yang berputar di sekitar musuh, menyerang target garis vertikal lawan, memberikan #C0x3D8A99#145% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, dengan peluang 40% untuk [Membekukan] target selama 2 giliran (Membekukan: efek kontrol yang mencegah aksi dan hilang jika target menerima kerusakan terkumulasi melebihi 30% dari nyawa target).',
		describe_ph = 'Ang Ice Bird ay nagiging isang malamig na hangin na umiikot sa paligid ng mga kalaban, sumasalakay sa patayong hanay ng mga target ng kalaban, nagdudulot ng #C0x3D8A99#145% Lakas ng Mahika#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pinsalang Mahika #C0x5B545B#, may 40% pagkakataon na [Mag-yelo] sa target sa loob ng 2 turns (Yelo: isang kontrol na epekto na pumipigil na kumilos at nawawala kapag ang target ay tumanggap ng naipong pinsala na higit sa 30% ng buhay ng target).',
		describe_ma = 'Burung Ais berubah menjadi angin ais yang berputar di sekitar musuh, menyerang sasaran baris menegak musuh, menyebabkan #C0x3D8A99#145% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, dengan peluang 40% untuk [Membekukan] sasaran selama 2 pusingan (Membekukan: kesan kawalan yang menghalang tindakan dan akan hilang apabila sasaran menerima kerosakan terkumpul melebihi 30% daripada nyawa sasaran).',
		describe = 'The Ice Bird transforms into an icy wind, swirling around enemies and attacking a vertical line of enemy targets, dealing #C0x3D8A99#145% Magic Power#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 40% chance to [Freeze] the target for 2 turns (Freeze: a control effect that prevents action and is removed when the target takes accumulated damage exceeding 30% of its health).',
		simDesc_vn = 'Articuno hóa thành một cơn gió băng, xoay quanh kẻ địch và tấn công mục tiêu đơn lẻ của đối phương.',
		simDesc_en = 'Articuno transforms into an icy wind, swirling around the enemy and attacking a single target.',
		simDesc_th = 'อาร์ติกูโน่แปรสภาพเป็นลมเย็นจัด หมุนรอบศัตรูและโจมตีเป้าหมายเดี่ยวของฝ่ายตรงข้าม',
		simDesc_in = 'Articuno berubah menjadi angin es, berputar mengelilingi musuh dan menyerang satu target lawan.',
		simDesc_ph = 'Ang Articuno ay nagiging isang nagyeyelong hangin, umiikot sa paligid ng kalaban at umaatake sa isang target na kalaban.',
		simDesc_ma = 'Articuno berubah menjadi angin beku, berputar di sekitar musuh dan menyerang satu sasaran musuh.',
		simDesc = 'Articuno transforms into an icy wind, swirling around the enemy and attacking a single target.',
