	[40001013] = {
		id = 40001013,
		skillName_vn = 'Núi băng',
		skillName_en = 'Ice Mountain',
		skillName_th = 'ภูเขาน้ำแข็ง',
		skillName_in = 'Gunung Es',
		skillName_ph = 'Bundok ng Yelo',
		skillName_ma = 'Gunung Ais',
		skillName = 'Ice Mountain',
		describe_vn = 'Chim băng triệu hồi một ngọn núi băng khổng lồ từ trên trời rơi xuống, tấn công mục tiêu hàng trước của đối phương, trước tiên giảm 40% phòng thủ pháp thuật của mục tiêu hàng trước trong 1 lượt, gây ra #C0x3D8A99#230% Công Phép thuật#C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, có 40% cơ hội [Đóng băng] mục tiêu trong 2 lượt (Đóng băng: hiệu ứng khống chế, không thể hành động, giải trừ khi nhận sát thương tích lũy vượt quá 30% sinh mệnh của mục tiêu)',
		describe_en = 'The Ice Bird summons a gigantic ice mountain from the sky to crash down, attacking the enemy\'s front row. It first reduces the front row target\'s magic defense by 40% for 1 turn, dealing #C0x3D8A99#230% Magic Power#C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# Magic Damage #C0x5B545B# with a 40% chance to [Freeze] the target for 2 turns (Freeze: a control effect that disables actions, removed when the accumulated damage exceeds 30% of the target\'s HP).',
		describe_th = 'นกน้ำแข็งอัญเชิญภูเขาน้ำแข็งขนาดยักษ์จากบนฟ้าตกลงมาโจมตีแถวหน้าของศัตรู โดยจะลดการป้องกันเวทมนตร์ของเป้าหมายแถวหน้าลง 40% เป็นเวลา 1 เทิร์น สร้างความเสียหายเวทมนตร์ #C0x3D8A99#230% พลังเวท#C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# พร้อมโอกาส 40% ที่จะ [แช่แข็ง] เป้าหมายเป็นเวลา 2 เทิร์น (แช่แข็ง: ผลของสถานะควบคุมทำให้ไม่สามารถกระทำการได้ และจะถูกยกเลิกเมื่อรับความเสียหายสะสมเกิน 30% ของพลังชีวิตของเป้าหมาย)',
		describe_in = 'Burung Es memanggil gunung es raksasa dari langit yang jatuh dan menyerang baris depan musuh. Pertama-tama mengurangi pertahanan sihir target baris depan sebesar 40% selama 1 giliran, menyebabkan #C0x3D8A99#230% Kekuatan Sihir#C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# Kerusakan Sihir #C0x5B545B#, dengan peluang 40% untuk [Membekukan] target selama 2 giliran (Membekukan: efek kontrol yang mencegah aksi, dihapus saat kerusakan kumulatif melebihi 30% HP target).',
		describe_ph = 'Ang Ibon ng Yelo ay nagpapatawag ng isang higanteng bundok ng yelo mula sa langit upang bumagsak, inaatake ang harapang hanay ng kalaban. Una nitong binabawasan ang magic defense ng front row target ng 40% sa loob ng 1 turn, nagdudulot ng #C0x3D8A99#230% Magic Power#C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# Magic Damage #C0x5B545B#, may 40% pagkakataon na [I-freeze] ang target ng 2 turns (Freeze: control effect na pumipigil sa pagkilos, nawawala kapag ang naipong damage ay sumobra sa 30% ng HP ng target).',
		describe_ma = 'Burung Ais memanggil gunung ais gergasi dari langit jatuh ke bawah untuk menyerang barisan hadapan musuh. Ia akan mengurangkan pertahanan sihir sasaran barisan hadapan sebanyak 40% selama 1 pusingan, menyebabkan #C0x3D8A99#230% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, dengan peluang 40% untuk [Membekukan] sasaran selama 2 pusingan (Membekukan: kesan kawalan yang membuat sasaran tidak boleh bertindak, dibatalkan apabila menerima kerosakan terkumpul melebihi 30% HP sasaran).',
		describe = 'The Ice Bird summons a gigantic ice mountain from the sky to crash down, attacking the enemy\'s front row. It first reduces the front row target\'s magic defense by 40% for 1 turn, dealing #C0x3D8A99#230% Magic Power#C0x5B545B#+$(skillLevel*4*42)$ #C0xF13B54# Magic Damage #C0x5B545B# with a 40% chance to [Freeze] the target for 2 turns (Freeze: a control effect that disables actions, removed when the accumulated damage exceeds 30% of the target\'s HP).',
		simDesc_vn = 'Articuno triệu hồi một ngọn núi băng khổng lồ từ trên trời rơi xuống, tấn công hàng trước của đối phương, có cơ hội đóng băng mục tiêu.',
		simDesc_en = 'Articuno summons a gigantic ice mountain that falls from the sky, attacking the enemy\'s front line with a chance to freeze the target.',
		simDesc_th = 'อาร์ติกูโน่ เรียกภูเขาน้ำแข็งขนาดยักษ์จากฟ้าที่ตกลงมาโจมตีแถวหน้าของศัตรู มีโอกาสที่จะทำให้เป้าหมายถูกแช่แข็ง',
		simDesc_in = 'Articuno memanggil gunung es raksasa yang jatuh dari langit, menyerang barisan depan musuh dengan kesempatan membekukan target.',
		simDesc_ph = 'Si Articuno ay nagmumungkahi ng isang malaking bundok ng yelo na bumabagsak mula sa langit, inaatake ang harapang linya ng kalaban na may tsansang makapag-freeze sa target.',
		simDesc_ma = 'Articuno memanggil gunung ais gergasi yang jatuh dari langit, menyerang barisan hadapan musuh dengan peluang untuk membekukan sasaran.',
		simDesc = 'Articuno summons a gigantic ice mountain that falls from the sky, attacking the enemy\'s front line with a chance to freeze the target.',
