	[40001023] = {
		id = 40001023,
		skillName_vn = 'Ma trận băng khóa lục giác',
		skillName_en = 'Hexagonal lock matrix',
		skillName_th = 'เมทริกซ์ล็อคหกเหลี่ยม',
		skillName_in = 'Matriks kunci heksagonal',
		skillName_ph = 'Hexagonal lock matrix',
		skillName_ma = 'Matriks kunci heksagonal',
		skillName = 'Hexagonal lock matrix',
		describe_vn = 'Bông tuyết hình học triệu hồi trận khóa băng sáu cánh tấn công toàn bộ mục tiêu của đối phương, gây ra #C0x3D8A99#120% Công Phép thuật#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Sát Thương Phép Thuật #C0x5B545B#, có 30% cơ hội [Đóng băng] mục tiêu trong 2 lượt, và tăng 120% phòng thủ pháp thuật và 15% giảm Sát Thương Phép Thuật cho bản thân trong 2 lượt',
		describe_en = 'Geometric snowflake summons a six-winged ice lock formation that attacks all enemy targets, dealing #C0x3D8A99#120% Magic Power#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 30% chance to [Freeze] the target for 2 turns, and increases own magic defense by 120% and magic damage reduction by 15% for 2 turns.',
		describe_th = 'เกล็ดหิมะเรขาคณิตเรียกกองกำลังล็อคน้ำแข็งหกปีกโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหาย #C0x3D8A99#120% พลังเวท#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# ความเสียหายเวทมนตร์ #C0x5B545B# มีโอกาส 30% ที่จะ [แช่แข็ง] เป้าหมายเป็นเวลา 2 เทิร์น และเพิ่มการป้องกันเวทมนตร์ของตัวเอง 120% และลดความเสียหายเวทมนตร์ลง 15% เป็นเวลา 2 เทิร์น',
		describe_in = 'Bunga salju geometris memanggil formasi kunci es bersayap enam yang menyerang semua target musuh, menyebabkan #C0x3D8A99#120% Kekuatan Magic#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Damage Magic #C0x5B545B#, dengan peluang 30% untuk [Membekukan] target selama 2 giliran, serta meningkatkan pertahanan sihir sendiri sebesar 120% dan pengurangan damage magic sebesar 15% selama 2 giliran.',
		describe_ph = 'Geometric na niyebe ay nag-summon ng anim na pakpak na yelo na lumilikha ng ice lock formation na umaatake sa lahat ng kalaban, nagdudulot ng #C0x3D8A99#120% Kapangyarihan ng Mahika#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Pinsala ng Mahika #C0x5B545B#, may 30% pagkakataon na [I-freeze] ang target sa loob ng 2 turn, at nagpapataas ng 120% ng sariling magic defense at 15% pagbawas ng pinsala ng mahika sa loob ng 2 turn.',
		describe_ma = 'Bungan salji geometri memanggil formasi kunci ais bersayap enam yang menyerang semua sasaran musuh, menyebabkan #C0x3D8A99#120% Kuasa Sihir#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Kerosakan Sihir #C0x5B545B#, dengan peluang 30% untuk [Membekukan] sasaran selama 2 pusingan, serta meningkatkan pertahanan sihir diri sendiri sebanyak 120% dan pengurangan kerosakan sihir sebanyak 15% selama 2 pusingan.',
		describe = 'Geometric snowflake summons a six-winged ice lock formation that attacks all enemy targets, dealing #C0x3D8A99#120% Magic Power#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54# Magic Damage #C0x5B545B#, with a 30% chance to [Freeze] the target for 2 turns, and increases own magic defense by 120% and magic damage reduction by 15% for 2 turns.',
		simDesc_vn = 'Cryogonal triệu hồi trận pháp băng sáu cánh để tấn công toàn bộ mục tiêu của đối phương, có cơ hội đóng băng mục tiêu, đồng thời tăng phòng thủ phép thuật và giảm sát thương phép nhận vào cho bản thân.',
		simDesc_en = 'Cryogonal summons a six-winged ice formation to attack all enemy targets, with a chance to freeze them, while simultaneously increasing its magic defense and reducing magic damage received.',
		simDesc_th = 'Cryogonal เรียกใช้การจัดการน้ำแข็งหกปีกเพื่อโจมตีเป้าหมายทั้งหมดของศัตรู มีโอกาสทำให้เป้าหมายแข็งตัว พร้อมกับเพิ่มการป้องกันเวทมนตร์และลดความเสียหายเวทมนตร์ที่ได้รับสำหรับตัวเอง',
		simDesc_in = 'Cryogonal memanggil formasi es bersayap enam untuk menyerang semua target musuh, dengan peluang membekukan target, sekaligus meningkatkan pertahanan sihir dan mengurangi kerusakan sihir yang diterima untuk dirinya sendiri.',
		simDesc_ph = 'Inilulunsad ni Cryogonal ang anim na pakpak na yelong pormasyon upang atakihin ang lahat ng mga target ng kalaban, na may pagkakataong mapapaso ang mga target, kasabay ng pagtaas ng depensa sa mahika at pagbabawas ng tanging pinsalang mahika na natatanggap para sa sarili.',
		simDesc_ma = 'Cryogonal memanggil formasi ais enam sayap untuk menyerang semua sasaran musuh, dengan peluang membekukan sasaran, sekaligus meningkatkan pertahanan sihir dan mengurangkan kerosakan sihir yang diterima untuk dirinya sendiri.',
		simDesc = 'Cryogonal summons a six-winged ice formation to attack all enemy targets, with a chance to freeze them, while simultaneously increasing its magic defense and reducing magic damage received.',
