	[40001026] = {
		id = 40001026,
		skillName_vn = 'Frost Seal',
		skillName_en = 'Frost Seal',
		skillName_th = 'ตราประทับแห่งน้ำแข็ง',
		skillName_in = 'Segel Beku',
		skillName_ph = 'Selyo ng Yelo',
		skillName_ma = 'Meterai Sejuk',
		skillName = 'Frost Seal',
		describe_vn = 'Tăng Phép Phòng trong 2 lượt trước chiến đấu #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B#（không thể bị xóa）；\nSau khi bị tấn công, phản xạ một hiệu ứng tiêu cực ngẫu nhiên của bản thân lên kẻ tấn công, và có #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# xác suất khiến kẻ đó [Đóng băng] 1 lượt (Đóng băng: hiệu ứng kiểm soát, không thể hành động, bị giải trừ sau khi nhận sát thương tích lũy vượt quá 30% sinh mệnh của mục tiêu)',
		describe_en = 'Increases Magic Defense for 2 turns before combat by #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (cannot be removed); \n After being attacked, reflects a random negative effect on the attacker, and has a #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# chance to Freeze the attacker for 1 turn (Freeze: control effect, unable to act, removed after receiving accumulated damage exceeding 30% of the target\'s health).',
		describe_th = 'เพิ่มการป้องกันเวทมนตร์เป็นเวลา 2 เทิร์นก่อนการต่อสู้ #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (ไม่สามารถลบออกได้); \n หลังจากถูกโจมตี จะสะท้อนเอฟเฟกต์ลบแบบสุ่มกลับไปยังผู้โจมตี และมีโอกาส #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# ที่จะทำให้ผู้โจมตี [ถูกแช่แข็ง] 1 เทิร์น (แช่แข็ง: เอฟเฟกต์ควบคุม ไม่สามารถกระทำการได้ และจะถูกลบหลังจากรับความเสียหายสะสมเกิน 30% ของพลังชีวิตเป้าหมาย)',
		describe_in = 'Meningkatkan Pertahanan Sihir selama 2 giliran sebelum pertarungan sebesar #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (tidak dapat dihapus); \n Setelah diserang, memantulkan efek negatif acak pada penyerang, dan memiliki peluang #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# untuk Membekukan penyerang selama 1 giliran (Bekukan: efek kontrol, tidak dapat bertindak, akan hilang setelah menerima akumulasi kerusakan melebihi 30% dari kesehatan target).',
		describe_ph = 'Pinapataas ang Laban sa Mahika ng 2 turn bago ang laban ng #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (hindi maaaring matanggal); \n Pagkatapos tamaan, bumabalik ng isang random na negatibong epektong sarili sa kalaban, at may #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# tsansa na ma-[Freeze] ang kalaban ng 1 turn (Freeze: kontrol na epektong hindi makakilos, matatanggal pagkatapos makatanggap ng naipong pinsalang higit sa 30% ng buhay ng target).',
		describe_ma = 'Meningkatkan Pertahanan Sihir selama 2 pusingan sebelum pertempuran sebanyak #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (tidak boleh dipadamkan); \n Selepas diserang, memantulkan kesan negatif rawak kepada penyerang, dan mempunyai peluang #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# untuk Membekukan penyerang selama 1 pusingan (Bekukan: kesan kawalan, tidak boleh bertindak, digugurkan selepas menerima kerosakan terkumpul melebihi 30% kesihatan sasaran).',
		describe = 'Increases Magic Defense for 2 turns before combat by #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# (cannot be removed); \n After being attacked, reflects a random negative effect on the attacker, and has a #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# chance to Freeze the attacker for 1 turn (Freeze: control effect, unable to act, removed after receiving accumulated damage exceeding 30% of the target\'s health).',
		starEffect = __data_t__starEffect[40001026],
		-- {8}
		starEffectDesc_vn = 'Tăng cường hiệu quả: Tăng 10% tỷ lệ đóng băng khi phản xạ.',
