	[40001033] = {
		id = 40001033,
		skillName_vn = 'Móng vuốt ác quỷ',
		skillName_en = 'Demon claws',
		skillName_th = 'กรงเล็บปีศาจ',
		skillName_in = 'Cakar setan',
		skillName_ph = 'Sangkalan ng demonyo',
		skillName_ma = 'Cakar syaitan',
		skillName = 'Demon claws',
		describe_vn = 'Weavile vung móng vuốt thép như cơn lốc, liên tục chém vào mục tiêu đơn lẻ của kẻ địch, gây #C0xE69900#500% Công Vật Lý#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Sát Thương Vật Lý#C0x5B545B#, gây thêm 60% sát thương cho mục tiêu bị đóng băng, và có 80% xác suất đóng băng mục tiêu chưa bị đóng băng trong 1 lượt (trong thời gian đóng băng, nếu nhận sát thương tích lũy vượt quá 30% máu của mục tiêu thì trạng thái đóng băng sẽ bị giải trừ)',
		describe_en = 'Weavile swings its steel claws like a whirlwind, continuously striking a single enemy target, dealing #C0xE69900#500% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, dealing an additional 60% damage to frozen targets, and has an 80% chance to freeze targets that are not yet frozen for 1 turn (while frozen, if accumulated damage exceeds 30% of the target\'s HP, the freeze status will be removed).',
		describe_th = 'วีเวลใช้กรงเล็บเหล็กฟาดเหมือนพายุหมุน ฟันเป้าหมายศัตรูเดี่ยวอย่างต่อเนื่อง ก่อให้เกิด #C0xE69900#500% พลังโจมตีทางกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# ความเสียหายทางกายภาพ#C0x5B545B# เพิ่มเติม ทำความเสียหาย 60% กับเป้าหมายที่ถูกแช่แข็ง และมีโอกาส 80% ที่จะทำให้เป้าหมายที่ยังไม่ถูกแช่แข็งติดสถานะแช่แข็ง 1 เทิร์น (ในระหว่างแช่แข็ง หากรับความเสียหายสะสมเกิน 30% ของพลังชีวิตเป้าหมาย สถานะแช่แข็งจะถูกยกเลิก).',
		describe_in = 'Weavile mengayunkan cakar baja seperti puting beliung, terus-menerus menyerang satu target musuh, memberikan #C0xE69900#500% Serangan Fisik#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerusakan Fisik#C0x5B545B#, memberikan tambahan 60% kerusakan pada target yang membeku, dan memiliki peluang 80% untuk membekukan target yang belum membeku selama 1 giliran (selama beku, jika kerusakan terakumulasi melebihi 30% HP target, status beku akan dihapus).',
		describe_ph = 'Weavile ay bumagsak ng mga bakal na kuko na parang buhawi, patuloy na pinupuntirya ang isang kalaban na target, nagdudulot ng #C0xE69900#500% Pisikal na Atake#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Pisikal na Pinsala#C0x5B545B#, nagdudulot ng karagdagang 60% pinsala sa mga target na nagyeyelo, at may 80% na tsansa na mapamigang ang mga target na hindi pa nagyeyelo sa loob ng 1 turn (habang nagyeyelo, kung ang naipong pinsala ay lumampas ng 30% ng HP ng target, mawawala ang estado ng nagyeyelo).',
		describe_ma = 'Weavile mengayunkan cakar keluli seperti puting beliung, berterusan menyerang sasaran musuh tunggal, menyebabkan #C0xE69900#500% Serangan Fizikal#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Kerosakan Fizikal#C0x5B545B#, menyebabkan tambahan 60% kerosakan pada sasaran yang dibekukan, dan mempunyai peluang 80% untuk membekukan sasaran yang belum dibekukan selama 1 pusingan (semasa beku, jika kerosakan terkumpul melebihi 30% HP sasaran, status beku akan dibuang).',
		describe = 'Weavile swings its steel claws like a whirlwind, continuously striking a single enemy target, dealing #C0xE69900#500% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54# Physical Damage#C0x5B545B#, dealing an additional 60% damage to frozen targets, and has an 80% chance to freeze targets that are not yet frozen for 1 turn (while frozen, if accumulated damage exceeds 30% of the target\'s HP, the freeze status will be removed).',
		simDesc_vn = 'Weavile vươn móng vuốt thép, chém liên tục như cơn lốc vào mục tiêu đơn lẻ của đối phương, gây sát thương lớn lên mục tiêu bị đóng băng và có cơ hội đóng băng mục tiêu.',
		simDesc_en = 'Weavile slashes with steel claws, repeatedly striking like a whirlwind at a single enemy, dealing heavy damage to frozen targets and has a chance to freeze the target.',
		simDesc_th = 'วีไวล์ใช้กรงเล็บเหล็กฟาดอย่างต่อเนื่องเหมือนพายุหมุนไปยังเป้าหมายเดียวของศัตรู สร้างความเสียหายรุนแรงต่อเป้าหมายที่ถูกแช่แข็งและมีโอกาสทำให้เป้าหมายถูกแช่แข็งอีกครั้ง',
		simDesc_in = 'Weavile mengayunkan cakar baja berulang kali seperti pusaran angin ke satu sasaran musuh, memberikan kerusakan besar pada sasaran yang membeku dan memiliki peluang untuk membekukan sasaran tersebut.',
		simDesc_ph = 'Weavile ayun ang mga bakal na kuko, paulit-ulit na sumasalakay na parang bagyo sa iisang kalaban, nagdudulot ng malakas na pinsala sa mga nagyeyelong target at may pagkakataong mapalamig ang target.',
		simDesc_ma = 'Weavile mencakar dengan cakar besi, menyerang bertubi-tubi seperti ribut taufan ke sasaran tunggal musuh, memberikan kerosakan besar kepada sasaran yang membeku dan mempunyai peluang untuk membekukan sasaran tersebut.',
		simDesc = 'Weavile slashes with steel claws, repeatedly striking like a whirlwind at a single enemy, dealing heavy damage to frozen targets and has a chance to freeze the target.',
		starEffect = __data_t__starEffect[40001033],
		-- {11}
		starEffectDesc_vn = 'Tăng cường hiệu ứng: Gây thêm 80% sát thương cho mục tiêu bị đóng băng; có 90% xác suất <đóng băng> mục tiêu chưa bị đóng băng trong 1 lượt (đóng băng: hiệu ứng kiểm soát, không thể hành động, bị giải trừ khi nhận sát thương vượt quá 35% máu).',
		starEffectDesc = 'Enhance effect: Deals an additional 80% damage to targets that are frozen; 90% chance to <freeze> targets that are not yet frozen for 1 turn (#frozen#: a control effect, unable to act, removed if damage exceeding 35% HP is received).',
		starEffectDesc_en = 'Enhance effect: Deals an additional 80% damage to targets that are frozen; 90% chance to <freeze> targets that are not yet frozen for 1 turn (#frozen#: a control effect, unable to act, removed if damage exceeding 35% HP is received).',
		starEffectDesc_th = 'เสริมฤทธิ์: สร้างความเสียหายเพิ่มขึ้น 80% กับเป้าหมายที่ถูกแช่แข็ง; มีโอกาส 90% ที่จะ <แช่แข็ง> เป้าหมายที่ยังไม่ถูกแช่แข็งเป็นเวลา 1 เทิร์น (#แช่แข็ง#: เอฟเฟกต์ควบคุม ไม่สามารถกระทำการได้ จะถูกลบเมื่อได้รับความเสียหายเกิน 35% ของพลังชีวิต).',
		starEffectDesc_in = 'Tingkatkan efek: Berikan tambahan 80% kerusakan pada target yang membeku; 90% peluang untuk <membekukan> target yang belum membeku selama 1 giliran (#membeku#: efek kontrol, tidak dapat bertindak, hilang jika menerima kerusakan melebihi 35% HP).',
		starEffectDesc_ph = 'Palakasin ang epekto: Magdulot ng dagdag na 80% pinsala sa mga target na nagyeyelo; 90% tsansa na <iyelo> ang mga target na hindi pa nagyeyelo sa loob ng 1 turn (#iyelo#: epekto ng kontrol, hindi makakilos, matatanggal kapag nakatanggap ng pinsalang higit sa 35% ng HP).',
		starEffectDesc_ma = 'Tingkatkan kesan: Berikan 80% kerosakan tambahan kepada sasaran yang dibekukan; 90% peluang untuk <membekukan> sasaran yang belum dibekukan selama 1 pusingan (#dibekukan#: kesan kawalan, tidak boleh bertindak, akan hilang apabila menerima kerosakan melebihi 35% HP).',
		upLvDesc = 'Fixed damage +192',
		upLvDesc_en = 'Fixed damage +192',
		upLvDesc_th = 'ความเสียหายคงที่ +192',
		upLvDesc_in = 'Kerusakan tetap +192',
